def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _perturb(h, rng, amp):
    # smooth multiplicative perturbation: preserve non-negativity
    n = h.size
    k = max(3, n // 200)
    z = rng.standard_normal(n + 2 * k)
    w = np.convolve(z, np.ones(k) / k, mode='valid')[:n]
    w = w / (np.std(w) + 1e-12)
    return np.clip(h * np.exp(amp * w), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    rng = np.random.default_rng(12345)

    # 1) Full-resolution polish of the start.
    h = _lbfgs_log(best, 600, deadline)
    r = R_of(h)
    if r > bestR + 1e-15:
        best, bestR = h, r
        print("full R=%.7f" % bestR)

    # 2) Peak-window polish at several widths.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.2f) R=%.7f" % (frac, bestR))

    # 3) Annealed random restarts: perturb, re-optimize, keep improvements.
    #    This is the main new driver: escape shallow local optima of the
    #    (highly nonconvex) R landscape around the polished start.
    amp = 0.05
    stall = 0
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        hp = _perturb(best, rng, amp)
        if hp.sum() <= 0:
            continue
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 300, deadline)
        if time.process_time() >= deadline - 1.5:
            break
        hp = _window_polish_peak(hp, deadline, 0.30, 16, maxiter=200)
        r = R_of(hp)
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("restart[%.3f] R=%.7f" % (amp, bestR))
            stall = 0
            amp = max(0.005, amp * 0.85)
        else:
            stall += 1
            if stall % 3 == 0:
                amp = min(0.20, amp * 1.4)

    # 4) Final intensification.
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
    if time.process_time() < deadline - 0.8:
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

