    hc = _rescale(hc)
    Rc_plain = R_of(hc)
    print("coarse plain Nc=%d R=%.7f" % (Nc, Rc_plain))

    spikes = _extract_spikes(hc, 1e-4)
    # Cap to K<=300 by keeping largest masses.
    if len(spikes) > 300:
        spikes.sort(key=lambda s: -s[1])
        spikes = spikes[:300]
        spikes.sort(key=lambda s: s[0])
    print("spikes K=%d" % len(spikes))

    if len(spikes) == 0:
        # Fall back to plain coarse.
        spikes = [[i, float(v)] for i, v in enumerate(hc) if v > 0]

    def build_arr(sp):
        return _spikes_to_array(sp, Nc)

    def R_sp(sp):
        arr = build_arr(sp)
        if arr.sum() <= 0:
            return 0.0
        return R_of(arr)

    # Optimise heights of spikes at Nc.
    def opt_heights(sp, maxiter=300):
        arr = build_arr(sp)
        if arr.sum() <= 0:
            return sp
        free = np.array([s[0] for s in sp], dtype=int)
        arr2 = _lbfgs_block(arr, free, maxiter=maxiter, deadline=deadline)
        # Re-extract spikes from arr2 at nonzero indices.
        new_sp = []
        for idx in free:
            if idx < Nc and arr2[idx] > 0:
                new_sp.append([int(idx), float(arr2[idx])])
        if len(new_sp) == 0:
            return sp
        return new_sp

    cur_sp = [list(s) for s in spikes]
    cur_sp = opt_heights(cur_sp, maxiter=300)
    curR = R_sp(cur_sp)
    print("spikes init R=%.7f" % curR)

    rng = np.random.default_rng(20240101)
    moves = [-5, -3, -2, -1, 1, 2, 3, 5]
    geo_deadline = min(deadline - 20.0, t0 + 25.0)

    sweeps = 0
    accepted_total = 0
    while sweeps < 60 and time.process_time() < geo_deadline:
        sweeps += 1
        order = rng.permutation(len(cur_sp))
        sweep_accepted = 0
        for oi in order:
            if time.process_time() >= geo_deadline:
                break
            if oi >= len(cur_sp):
                continue
            idx, val = cur_sp[oi]
            best_local = None
            best_local_R = curR
            for d in moves:
                nidx = idx + d
                if nidx < 0 or nidx >= Nc:
                    continue
                # Build trial spikes.
                trial = []
                for j, (jj, vv) in enumerate(cur_sp):
                    if j == oi:
                        continue
                    trial.append([jj, vv])
                trial.append([nidx, val])
                trial = _normalize_spikes(trial, Nc)
                r = R_sp(trial)
                if r > best_local_R + 1e-12:
                    best_local_R = r
                    best_local = trial
            if best_local is not None:
                cur_sp = best_local
                curR = best_local_R
                sweep_accepted += 1
                accepted_total += 1
        # Re-optimise heights after each sweep.
        if time.process_time() < geo_deadline:
            new_sp = opt_heights(cur_sp, maxiter=300)
            newR = R_sp(new_sp)
            if newR > curR + 1e-12:
                cur_sp = new_sp
                curR = newR
        print("sweep %d acc=%d R=%.7f" % (sweeps, sweep_accepted, curR))
        if sweep_accepted == 0 and sweeps >= 3:
            break

    print("geometry done: sweeps=%d acc=%d Rc=%.7f (plain %.7f)" %
          (sweeps, accepted_total, curR, Rc_plain))

    # Build coarse array from best spikes.
    hc_best = build_arr(cur_sp)
    if hc_best.sum() <= 0:
        hc_best = hc
    hc_best = _rescale(hc_best)

    # Prolongate to full resolution.
    hp = _prolongate(hc_best, N)
    hp = _rescale(hp)

    # Polish at full resolution.
    hp = _lbfgs_log(hp, 800, deadline)
    hp = _window_polish_peak(hp, deadline, 0.15, 16)
    hp = _lbfgs_log(hp, 800, deadline)
    r = R_of(hp)
    print("lift R=%.7f" % r)

    alt_best = hp
    alt_bestR = r

    # Alternate polish until deadline.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(alt_best, 800, deadline)
        rr = R_of(h)
        if rr > alt_bestR + 1e-15:
            alt_best, alt_bestR = h, rr
            improved = True
            print("full R=%.7f" % alt_bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(alt_best, deadline, 0.15, 16)
        rr = R_of(h)
        if rr > alt_bestR + 1e-15:
            alt_best, alt_bestR = h, rr
            improved = True
            print("win R=%.7f" % alt_bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final alt R=%.7f (N=%d)" % (alt_bestR, alt_best.size))

    if alt_bestR > start_bestR + 1e-12:
        return alt_best
    return {"best": start_best, "alternative": alt_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _true_polish(h, deadline, rounds=2):
    cur = h
    cur_r = R_of(cur)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish_peak(cur, deadline, 0.10, 8, maxiter=400)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    # Coarsen to N=32768 for the surrogate homotopy
    N0 = 32768
    if cur.size != N0:
        cand = _coarsen(cur, N0)
        cand = _rescale(cand)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    improved = False
    for beta in (4, 8, 16, 32, 64):
        if time.process_time() >= deadline - 6.0:
            break
        cand = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            improved = True

    # True-objective polish at N0
    if time.process_time() < deadline - 4.0:
        cand, r = _true_polish(cur, deadline, rounds=2)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            improved = True

    if improved and time.process_time() < deadline - 3.0:
        # Ladder up
        for N in (65536, 131072, 262144):
            if time.process_time() >= deadline - 4.0:
                break
            if cur.size == N:
                cand = cur.copy()
            else:
                cand = _prolongate(cur, N)
                cand = _rescale(cand)
            for beta in (16, 64):
                if time.process_time() >= deadline - 4.0:
                    break
                c2 = _lbfgs_sm(cand, beta, maxiter=200, deadline=deadline)
                r2 = R_of(c2)
                if r2 > R_of(cand):
                    cand = c2
            cand, r = _true_polish(cand, deadline, rounds=2)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    # Spend remaining budget on true-objective polish loop
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1500, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break
        for frac, extra in ((0.05, 4), (0.10, 8), (0.20, 16)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=600)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

