                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    if alt is not None and alt_r > best_r:
        best, best_r = alt.copy(), alt_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None and best is not None:
        # Provide the perturbed/refined result as alternative if it's distinct
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0
    return float(np.mean(Lf >= 0.99 * mx)), float(np.mean(Lf >= 0.95 * mx))


def _softmax_flat(h, beta, iters, deadline, lr=0.5):
    """Auxiliary: push more knots to near-max by ascending logsumexp(βL) only."""
    h = np.clip(h, 0, None).copy()
    if h.sum() <= 0:
        return h
    for _ in range(iters):
        if time.process_time() >= deadline - 0.3:
            break
        num, dq, Lf = _num_and_dq(h)
        M = Lf.max()
        z = beta * (Lf - M)
        w = np.exp(z)
        S = w.sum()
        gLf = w / S
        grad = _backprop(gLf, h)
        h = h + lr * grad
        h = np.clip(h, 0.0, None)
        h = _rescale(h)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    down_betas = (120.0, 60.0, 30.0, 15.0)
    up_betas = (60.0, 200.0, 600.0, 1500.0, 3000.0)

    cycle = 0
    while time.process_time() < deadline - 0.8:
        cycle += 1
        for beta in down_betas:
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_sm(cur, beta, maxiter=400, deadline=deadline - 0.5)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

        for beta in up_betas:
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_sm(cur, beta, maxiter=400, deadline=deadline - 0.5)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if time.process_time() >= deadline - 0.8:
                break
            cand = _window_polish_peak(cur, deadline - 0.5, 0.15, 8,
                                       maxiter=400, beta=800.0)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if time.process_time() >= deadline - 0.8:
                break
            cand = _window_polish_peak(cur, deadline - 0.5, 0.05, 16,
                                       maxiter=400, beta=800.0)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_log(cur, maxiter=600, deadline=deadline - 0.5)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if time.process_time() < deadline - 0.8:
            cand = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r > alt_r and not np.array_equal(cur, start_arr):
            alternative, alt_r = cur.copy(), cur_r

        s1, s5 = _shares(best)
        print(f"cycle {cycle}: R={best_r:.6f} 1%={s1*100:.1f}% 5%={s5*100:.1f}%")

    # NEW: a genuinely different construction via pure logsumexp flattening,
    # then exact polish. Try to beat best; otherwise register as alternative.
    if time.process_time() < deadline - 2.0:
        alt2 = _softmax_flat(best, beta=400.0, iters=300,
                             deadline=deadline - 1.0, lr=0.3)
        alt2 = _lbfgs_log(alt2, maxiter=600, deadline=deadline - 0.5)
        r2 = R_of(alt2)
        print(f"flat: R={r2:.6f}")
        if r2 > best_r:
            best, best_r = alt2.copy(), r2
        if r2 > alt_r and not np.array_equal(alt2, start_arr):
            alternative, alt_r = alt2.copy(), r2

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

