def _perturb(h, strength, rng):
    # random multiplicative perturbation with smoothing
    n = h.size
    noise = rng.standard_normal(n) * strength
    # smooth the noise a little to keep structure
    k = max(1, n // 256)
    if k > 1:
        ker = np.ones(k) / k
        noise = np.convolve(noise, ker, mode='same')
    h2 = h * np.exp(noise)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(12345)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # Main polish loop with multi-start perturbation (basin hopping style)
    # First a thorough local polish
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=2000, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        else:
            break

    # Basin hopping: perturb, re-polish, keep if better
    alt_track = None
    alt_r = -1.0
    strength = 0.05
    while time.process_time() < deadline - 1.0:
        base = cur if cur_r > best_r - 1e-6 else best
        p = _perturb(base, strength, rng)
        cand = _lbfgs_log(p, maxiter=800, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
            # try peak polish
            if time.process_time() < deadline - 2.0:
                c2 = _window_polish_peak(cur, deadline, 0.10, 8, maxiter=400)
                r2 = R_of(c2)
                if r2 > cur_r:
                    cur, cur_r = c2, r2
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
        else:
            # record a genuinely different construction
            if alt_track is None and r > best_r - 5e-4:
                alt_track, alt_r = cand.copy(), r
        # occasionally increase perturbation strength
        if rng.random() < 0.3:
            strength = min(0.4, strength * 1.15)

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        result = {"best": best}
        if alt_track is not None and alt_r > best_r - 1e-3:
            result["alternative"] = alt_track
        else:
            result["alternative"] = start_arr
        return result
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


