import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 4000:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 4000:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_sm(cur, beta, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_line(h, r, deadline, tag):
    """Aggressively polish a single construction with all tools until deadline."""
    while time.process_time() < deadline - 1.5:
        cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _polish(h, deadline, r,
                           fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=500)
        if r2 > r:
            h, r = cand, r2
        cand = _lbfgs_sm(h, 4096, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        print("  %s R=%.6f" % (tag, r))
    return h, r


def _taper_refine(h, r, deadline, tag):
    """NEW: refine at progressively higher resolution via prolongation, so the
    discrete grid stops limiting the achievable sharpness of the peak region."""
    cur, cur_r = h, r
    sizes = []
    n0 = h.size
    for m in (n0, 2 * n0, 4 * n0):
        if m > 1000000:
            break
        sizes.append(m)
    for m in sizes:
        if time.process_time() >= deadline - 2.0:
            break
        base = _rescale(_prolong(cur, m))
        rr = R_of(base)
        # full log refine at this resolution
        c2 = _lbfgs_log(base, maxiter=400, deadline=deadline)
        r2 = R_of(c2)
        if r2 > rr:
            base, rr = c2, r2
        # peak polish at this resolution
        base, rr = _polish(base, deadline, rr,
                           fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=400)
        print("  %s N=%d R=%.6f" % (tag, m, rr))
        if rr > cur_r:
            cur, cur_r = base, rr
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    if start_arr is not None:
        s_hi = start_arr
        if s_hi.size < 65536:
            s_hi = _rescale(_prolong(s_hi, 65536))
        s_r = R_of(s_hi)
        print("start base R=%.6f N=%d" % (s_r, s_hi.size))
        # NEW: try resolution-ladder refinement (prolongation) on the start.
        # This addresses the grid-limited sharpness of the peak region, which
        # the original never attacks at higher N.
        s_hi, s_r = _taper_refine(s_hi, s_r, deadline, "taper")
        # Then continue standard refine on the best resolution found.
        s_hi, s_r = _refine_line(s_hi, s_r, deadline, "start-refine")
        best, best_r = s_hi, s_r
        print("start-refined R=%.6f (was %.6f)" % (best_r, start_r))

    fresh = None
    fresh_r = -1.0
    if time.process_time() < deadline - 8.0:
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        h = _rescale(h)
        cur_r = R_of(h)
        betas = (8, 32, 128, 512, 2048)
        N = N0
        while N <= 65536 and time.process_time() < deadline - 4.0:
            cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                h, cur_r = cand, r
            cand, r = _homotopy(h, betas, 150, deadline)
            if r > cur_r:
                h, cur_r = cand, r
            if N >= 65536:
                break
            N = min(N * 2, 65536)
            h = _rescale(_prolong(h, N))
            cur_r = R_of(h)
        fresh, fresh_r = h, cur_r
        if time.process_time() < deadline - 4.0:
            fresh, fresh_r = _refine_line(fresh, fresh_r, deadline, "fresh")
        print("fresh R=%.6f" % fresh_r)

    if fresh is not None and fresh_r > best_r:
        best, best_r = fresh, fresh_r
    if best is None:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None and start_r >= best_r:
        alt = best if (fresh is not None and fresh_r > 0) else None
        if alt is not None and not np.array_equal(alt, start_arr):
            return {"best": _rescale(start_arr), "alternative": _rescale(alt)}
        return _rescale(start_arr)

    if start_arr is not None:
        return {"best": _rescale(best), "alternative": _rescale(start_arr)}
    return _rescale(best)

