    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_line(h, r, deadline, tag, do_print=True):
    while time.process_time() < deadline - 1.5:
        cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _polish(h, deadline, r,
                           fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=500)
        if r2 > r:
            h, r = cand, r2
        cand = _lbfgs_sm(h, 4096, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        if do_print:
            print("  %s R=%.6f" % (tag, r))
    return h, r


def _smooth_tilt(h, slope, center=0.5):
    n = h.size
    x = np.linspace(0.0, 1.0, n)
    return _rescale(h * np.exp(slope * (x - center)))


def _refine_local(h, r, deadline, tag, do_print=False):
    for _ in range(3):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(h, maxiter=200, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _polish(h, deadline, r, fracs=(0.20, 0.08, 0.03), maxiter=300)
        if r2 > r:
            h, r = cand, r2
    if do_print:
        print("  %s R=%.6f" % (tag, r))
    return h, r


def _short_refine(h, r, deadline):
    """Short refine used after accepting a perturbation."""
    cand = _lbfgs_log(h, maxiter=150, deadline=deadline)
    r2 = R_of(cand)
    if r2 > r:
        h, r = cand, r2
    cand, r2 = _polish(h, deadline, r, fracs=(0.25, 0.10, 0.04), maxiter=300)
    if r2 > r:
        h, r = cand, r2
    return h, r


def _jitter_peak(h, sigma, rng):
    """Multiplicative log-normal jitter on the peak-feeding window [m-n, m]."""
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - n)
    hi = min(n - 1, m)
    if hi < lo:
        return h.copy()
    idx = np.arange(lo, hi + 1)
    factor = np.exp(rng.normal(0.0, sigma, size=idx.size))
    h2 = h.copy()
    h2[idx] = h2[idx] * factor
    return _rescale(h2)


def _zero_revival(h):
    n = h.size
    h2 = h.copy()
    lo = n // 2
    hi = n
    zeros = np.flatnonzero(h2[lo:hi] == 0.0) + lo
    if zeros.size == 0:
        return h2
    # 256-step local mean
    k = 256
    c = np.concatenate(([0.0], np.cumsum(h2)))
    for z in zeros:
        a = max(0, z - k // 2)
        b = min(n, z + k // 2)
        mean = (c[b] - c[a]) / max(1, (b - a))
        h2[z] = 1e-3 * mean
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    if start_arr is not None:
        h = start_arr.copy()
        if h.size < 65536:
            h = _rescale(_prolong(h, 65536))
        r = R_of(h)
        print("start base R=%.6f N=%d" % (r, h.size))

        # Phase 1: capped refine of the start (12 s CPU).
        cap = time.process_time() + 12.0
        cap_deadline = min(cap, deadline - 3.0)
        h, r = _refine_line(h, r, cap_deadline, "start-refine")
        best, best_r = h, r
        print("start-refined R=%.6f (was %.6f)" % (best_r, start_r))

        # Phase 2: perturbation bank on the incumbent.
        tilts = [0.05, -0.05, 0.15, -0.15, 0.30, -0.30, 0.50, -0.50]
        sigmas = [0.05, 0.10, 0.20]
        cycle = 0
        while time.process_time() < deadline - 2.0:
            accepted = False
            # (a) tilts
            for s in tilts:
                if time.process_time() >= deadline - 2.0:
                    break
                cand = _smooth_tilt(best, s)
                cand, r2 = _short_refine(cand, R_of(cand), deadline - 1.0)
                if r2 > best_r + 1e-12:
                    best, best_r = cand, r2
                    accepted = True
                    print("  tilt %.2f accepted R=%.6f" % (s, best_r))
                    break
            if accepted:
                # Spend up to 6 s refining.
                rd = min(time.process_time() + 6.0, deadline - 2.0)
                best, best_r = _refine_line(best, best_r, rd,
                                            "post-tilt", do_print=False)
                print("  post-tilt R=%.6f" % best_r)
                cycle += 1
                continue
            # (b) jitter
            for sigma in sigmas:
                if time.process_time() >= deadline - 2.0:
                    break
                rng = np.random.RandomState(cycle * 1000 + int(sigma * 1000))
                cand = _jitter_peak(best, sigma, rng)
                cand, r2 = _short_refine(cand, R_of(cand), deadline - 1.0)
                if r2 > best_r + 1e-12:
                    best, best_r = cand, r2
                    accepted = True
                    print("  jitter %.2f accepted R=%.6f" % (sigma, best_r))
                    break
            if accepted:
                rd = min(time.process_time() + 6.0, deadline - 2.0)
                best, best_r = _refine_line(best, best_r, rd,
                                            "post-jitter", do_print=False)
                print("  post-jitter R=%.6f" % best_r)
                cycle += 1
                continue
            # (c) zero revival
            if time.process_time() < deadline - 2.0:
                cand = _zero_revival(best)
                cand, r2 = _short_refine(cand, R_of(cand), deadline - 1.0)
                if r2 > best_r + 1e-12:
                    best, best_r = cand, r2
                    accepted = True
                    print("  zero-revival accepted R=%.6f" % best_r)
                    rd = min(time.process_time() + 6.0, deadline - 2.0)
                    best, best_r = _refine_line(best, best_r, rd,
                                                "post-revival", do_print=False)
                    print("  post-revival R=%.6f" % best_r)
            cycle += 1
            if not accepted:
                # Avoid infinite tight loop; small progress print occasionally.
                if cycle % 3 == 0:
                    print("  cycle %d no acceptance, R=%.6f" % (cycle, best_r))
    else:
        # No start: build a fresh construction from scratch.
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        cur_r = R_of(h)
        betas = (8, 32, 128, 512, 2048)
        N = N0
        while N <= 65536 and time.process_time() < deadline - 3.0:
            cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
            rr = R_of(cand)
            if rr > cur_r:
                h, cur_r = cand, rr
            for beta in betas:
                if time.process_time() >= deadline - 2.0:
                    break
                cand = _lbfgs_sm(h, beta, maxiter=150, deadline=deadline)
                rr = R_of(cand)
                if rr > cur_r:
                    h, cur_r = cand, rr
            if N >= 65536:
                break
            N = min(N * 2, 65536)
            h = _rescale(_prolong(h, N))
            cur_r = R_of(h)
        h, cur_r = _refine_line(h, cur_r, deadline - 1.0, "fresh")
        best, best_r = h, cur_r
        print("fresh R=%.6f" % best_r)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None:
        if best_r > start_r + 1e-12:
            return {"best": _rescale(best), "alternative": _rescale(start_arr)}
        if best is not None and not np.array_equal(best, start_arr) and best_r > 0:
            return {"best": _rescale(start_arr), "alternative": _rescale(best)}
        return _rescale(start_arr)

    return _rescale(best)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _tail_region(h, tol=0.999):
    """Return index range of the two outer shoulders of the peak (where the
    convolution is between tol and, say, 0.5*mx on each side)."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    above = np.flatnonzero(Lf >= 0.5 * mx)
    if above.size == 0:
        return 0, h.size - 1
    return max(0, above.min() - 1), min(h.size - 1, above.max())


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _window_polish_tail(h, deadline, frac, extra, maxiter=400, beta=0.0):
    """Polish only one shoulder (left or right) of the peak — a fresh direction
    that full polishes can't easily reach because they optimise the whole shape."""
    n = h.size
    lo, hi = _tail_region(h)
    span = max(1, hi - lo)
    pad = max(extra, int(span * frac))
    # choose the wider tail
    if lo > (n - 1 - hi):
        a = max(0, lo - pad); b = min(n - 1, lo + span // 2)
    else:
        a = max(0, hi - span // 2); b = min(n - 1, hi + pad)
    free = np.arange(a, b + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _revive_zeros(h, level, win=256):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    if n < 4:
        return h
    pos = h > 0
    if not pos.any():
        return h
    k = max(1, min(win, n))
    kernel = np.ones(k) / k
    posf = pos.astype(float)
    num = np.convolve(h, kernel, mode='same')
    den = np.convolve(posf, kernel, mode='same')
    local_mean = np.where(den > 1e-12, num / np.maximum(den, 1e-12), 0.0)
    gmean = h[pos].mean()
    local_mean = np.where(local_mean > 0, local_mean, gmean)
    fill = level * local_mean
    zeros = ~pos
    h[zeros] = fill[zeros]
    return h


def _smooth(h, k):
    """Moving-average smoothing; useful as a diversification step."""
    if k < 2:
        return h
    ker = np.ones(k) / k
    return np.convolve(h, ker, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # --- Stage A: smooth-and-repolish diversification (new idea). ---
    # A tiny smoothing perturbs the optimum into a nearby, slightly-worse
    # point; from there L-BFGS often finds a genuinely different local basin
    # that a pure polish from `start` never reaches.
    alternatives = []
    if time.process_time() < deadline - 20.0:
        for k in (3, 5, 9):
            if time.process_time() >= deadline - 18.0:
                break
            hs = _smooth(best, k)
            hs = _rescale(hs)
            h = _lbfgs_log(hs, 400, deadline)
            r = R_of(h)
            print("  smooth k=%d -> R=%.7f" % (k, r))
            alternatives.append((r, h))

    # --- Stage B: revival ladder for exact zeros (kept from parent). ---
    levels = (1e-3, 5e-3, 1e-2, 3e-2)
    for L in levels:
        if time.process_time() >= deadline - 12.0:
            break
        cand = _revive_zeros(best, L, win=256)
        cand = _rescale(cand)
        r0 = R_of(cand)
        h = _lbfgs_log(cand, 400, deadline)
        r = R_of(h)
        for beta in (1e3, 1e4):
            if time.process_time() >= deadline - 10.0:
                break
            hb = _lbfgs_log(h, 200, deadline, beta=beta)
            rb = R_of(hb)
            if rb > r:
                h, r = hb, rb
        print("  revive L=%.0e R0=%.7f -> R=%.7f" % (L, r0, r))
        alternatives.append((r, h))

    for r, h in alternatives:
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r

    # --- Stage C: alternate full sharp / peak / tail polish to deadline. ---
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  alt full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  alt peak #%d frac=%.2f R=%.7f" % (it, frac, rp))
        # New: single-shoulder polish to escape symmetric local traps.
        if it % 3 == 0 and time.process_time() < deadline - 2.0:
            ht = _window_polish_tail(best, deadline, 0.10, 32, maxiter=150)
            rt = R_of(ht)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                print("  alt tail #%d R=%.7f" % (it, rt))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

