def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # Extended beta continuation ladder.
    betas = (1e6, 1e7, 1e8, 1e9, 1e10)
    cur = best.copy()
    curR = bestR
    improved_any = False

    perturb_cycle = [(128, 0.005), (256, 0.01), (128, 0.03), (64, 0.02)]
    pidx = 0

    pass_no = 0
    while time.process_time() < deadline - 3.0:
        pass_no += 1
        for beta in betas:
            if time.process_time() >= deadline - 4.0:
                break
            iters = 200 if beta <= 1e7 else 120
            hb = _lbfgs_log(cur, iters, deadline, beta=beta)
            hs = _lbfgs_log(hb, 5, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=120)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                print("  pass %d beta=%.0e R=%.7f" % (pass_no, beta, curR))
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                    improved_any = True
            else:
                print("  pass %d beta=%.0e R=%.7f (no gain)" %
                      (pass_no, beta, rc))

        # Multi-scale block perturbation, cycling.
        if time.process_time() < deadline - 3.0:
            nb, sg = perturb_cycle[pidx % len(perturb_cycle)]
            pidx += 1
            hs = _stochastic_blocks(cur, rng, nblocks=nb, sigma=sg)
            hs = _lbfgs_log(hs, 60, deadline)
            rs = R_of(hs)
            if rs > curR + 3e-13:
                cur, curR = hs, rs
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                    improved_any = True
                print("  pass %d perturb(%d,%.3f) R=%.7f" %
                      (pass_no, nb, sg, curR))
            else:
                print("  pass %d perturb(%d,%.3f) R=%.7f (no gain)" %
                      (pass_no, nb, sg, rs))

