    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _perturb_global(h, rng, amp=0.12):
    h = h.copy()
    n = h.size
    nk = int(rng.integers(3, 7))
    ks = rng.uniform(0.5, 4.0, size=nk)
    amps = rng.normal(0.0, amp, size=nk)
    x = np.linspace(0.0, 1.0, n)
    field = np.zeros(n)
    for k, a in zip(ks, amps):
        field += a * np.sin(np.pi * k * x + rng.uniform(0, 2 * np.pi))
    h *= np.exp(field)
    return _rescale(h)


def _perturb_peak(h, rng):
    h = h.copy()
    n = h.size
    lo, hi = _peak_region(h, tol=0.9)
    pad = max(8, (hi - lo))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    W = hi - lo
    if W < 4:
        return h
    nblocks = int(rng.integers(3, 7))
    cuts = np.sort(rng.choice(np.arange(1, W), size=min(nblocks - 1, W - 1), replace=False))
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, 0.20))
        h[a:c] *= fac
    return _rescale(h)


def _harden(h, deadline):
    cur = h
    for beta in (2000.0, 5000.0, 20000.0):
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_sm(cur, beta, maxiter=250, deadline=deadline)
        if R_of(c) >= R_of(cur):
            cur = c
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(cur, maxiter=600, deadline=deadline)
        if R_of(c) >= R_of(cur):
            cur = c
    return cur


def _tight_polish(h, deadline):
    """Soft->hard schedule plus peak-window polish, returns improved copy."""
    cur = h
    for beta in (300.0, 120.0, 60.0, 30.0):
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline)
        if R_of(c) >= R_of(cur):
            cur = c
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        if R_of(c) >= R_of(cur):
            cur = c
    for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2)):
        if time.process_time() >= deadline - 0.5:
            break
        c = _window_polish_peak(cur, deadline, frac, extra, maxiter=400)
        if R_of(c) >= R_of(cur):
            cur = c
    return cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    best = start_arr.copy()
    best_r = R_of(best)
    alternative = None
    alt_r = -1.0

    # Phase A: harden & tight-polish the start itself.
    h = _harden(best.copy(), hard_end)
    h = _tight_polish(h, hard_end)
    r = R_of(h)
    if r > best_r:
        best, best_r = h.copy(), r

    # Phase B: prolongate to higher resolution and refine.
    for N_big in (64000, 128000, 256000):
        if time.process_time() >= hard_end - 3.0:
            break
        if N_big <= best.size:
            continue
        h_big = _prolongate(best, N_big)
        h_big = _harden(h_big, hard_end)
        h_big = _tight_polish(h_big, hard_end)
        r = R_of(h_big)
        if r > best_r:
            best, best_r = h_big.copy(), r
        elif r > alt_r:
            alternative, alt_r = h_big.copy(), r

    print("phaseB R=%.6f N=%d" % (best_r, best.size))

    # Phase C: perturb + re-polish loop, keeps improving until deadline.
    rnd = 0
    while time.process_time() < hard_end - 2.0:
        rng = np.random.default_rng(9001 + rnd)
        rnd += 1
        base = best.copy()
        # alternate perturbation families
        if rnd % 2 == 0:
            h = _perturb_peak(base, rng)
        else:
            h = _perturb_global(base, rng, amp=0.08)
        h = _tight_polish(h, hard_end)
        r = R_of(h)
        if r > best_r:
            best, best_r = h.copy(), r
        elif r > alt_r:
            alternative, alt_r = h.copy(), r

    print("final R=%.6f N=%d" % (best_r, best.size))

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None and alt_r > R_of(start_arr):
        return {"best": best, "alternative": alternative}
    if best_r > R_of(start_arr):
        return best
    return start_arr

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW: coarse-to-fine. Downsample to a modest grid, optimise cheaply there
    # with a smooth (beta) surrogate that escapes a single-knot maximum, then
    # upsample and polish. This changes the shape in a way full-resolution
    # polishing of `best` cannot reach.
    alt = None
    altR = 0.0
    N = best.size

    def _try(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        print("%s R=%.7f" % (tag, r))
        if alt is None or r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s improved R=%.7f" % (tag, bestR))

    # Coarse solve with smoothing to relocate the peak region.
    for Nc in (1024, 2048, 4096):
        if time.process_time() >= deadline - 8.0:
            break
        if Nc >= N:
            continue
        hc = _coarse(best, Nc)
        hc = _rescale(hc)
        # beta smoothing: spread the max over a band, then tighten.
        for beta in (8.0, 20.0, 60.0, 0.0):
            if time.process_time() >= deadline - 6.0:
                break
            hc = _lbfgs_log(hc, 300, deadline, beta=beta)
        r = R_of(hc)
        print("coarse %d R=%.7f" % (Nc, r))
        # Upsample back and polish at full resolution.
        if time.process_time() < deadline - 4.0:
            hp = _prolongate(hc, N)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 400, deadline)
            _try(hp, "coarse_up")

    # Fine polish of the current best with tightening beta smoothing to
    # sharpen the maximum (beta continuation).
    if time.process_time() < deadline - 3.0:
        h = best.copy()
        for beta in (30.0, 100.0, 300.0, 0.0):
            if time.process_time() >= deadline - 2.0:
                break
            h = _lbfgs_log(h, 400, deadline, beta=beta)
        _try(h, "beta_tight")

    # Peak-focused polish at full resolution.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 500, deadline)
        _try(h, "peak(%.2f)" % frac)

    # Phase exploration around best.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale(hp)
        if hp.sum() <= 0:
            continue
        hp = _lbfgs_log(hp, 600, deadline)
        hp = _window_polish_peak(hp, deadline, 0.35, 16)
        _try(hp, "phase %+.2f" % delta)

    # Final loop: alternate full and peak polish until budget exhausted.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
