    return start_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _resample(h, m):
    """Resample step function h (n steps) to m steps preserving mass shape."""
    n = h.size
    if n == m:
        return h.copy()
    # treat as piecewise constant; integrate cumulative mass at cell boundaries
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    # boundaries of new cells in old-index units
    xb = np.arange(m + 1, dtype=float) * (n / m)
    idx = np.floor(xb).astype(int)
    frac = xb - idx
    idx = np.clip(idx, 0, n)
    x2 = np.clip(idx + 1, 0, n)
    val = c[idx] + frac * (c[x2] - c[idx])
    hn = np.diff(val)
    hn = np.clip(hn, 0, None)
    if hn.sum() <= 0:
        return h.copy()
    return hn * (total / hn.sum())


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    rng = np.random.RandomState(20240607)

    # ---- KEY CHANGE: try a coarser-resolution version of `start` ----
    # The score plateau suggests we are stuck in a fine-grid local optimum.
    # A coarser representation smooths the landscape and may find a
    # genuinely different (and better) basin, which we then prolong back.
    bestH = best.copy()
    bestRH = bestR
    n0 = best.size
    for factor in (2, 3, 4):
        if time.process_time() > deadline - 8.0:
            break
        m = max(64, n0 // factor)
        hc = _resample(best, m)
        Rc = R_of(hc)
        sub = min(deadline - 4.0, time.process_time() + 8.0)
        hc = _lbfgs_log(hc, 200, sub)
        Rc2 = R_of(hc)
        print("coarse /%d R=%.7f -> %.7f (N=%d)" % (factor, Rc, Rc2, hc.size))
        # prolong back to n0 and polish
        if time.process_time() < sub:
            hp = _resample(hc, n0)
            hp = _lbfgs_log(hp, 200, min(deadline - 2.0, time.process_time() + 10.0))
            Rp = R_of(hp)
            print("  prolong /%d R=%.7f" % (factor, Rp))
            if Rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), Rp

    # ---- stochastic perturbations at full resolution ----
    loop_end = t0 + budget_seconds * 0.86
    roundN = 0
    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 4.0:
        roundN += 1
        sub_deadline = min(loop_end, time.process_time() + 10.0)

        h = _lbfgs_log(bestH, 200, sub_deadline)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  L%d sharp R=%.7f" % (roundN, bestRH))

        for beta in (1e7, 1e9):
            if time.process_time() >= sub_deadline - 1.0:
                break
            h = _lbfgs_log(bestH, 100, sub_deadline, beta=beta)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  L%d beta=%.0e R=%.7f" % (roundN, beta, bestRH))

        # peak-window polish
        if time.process_time() < sub_deadline - 1.0:
            lo, hi = _peak_region(bestH)
            span = hi - lo
            pad = max(64, int(span * 0.15))
            lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
            if hi2 > lo2:
                free = np.arange(lo2, hi2 + 1)
                h = _lbfgs_block(bestH, free, 200, sub_deadline)
                r = R_of(h)
                if r > bestRH + 1e-13:
                    bestH, bestRH = h.copy(), r
                print("  L%d peak R=%.7f" % (roundN, bestRH))

        if bestRH > bestR + 1e-13:
            best, bestR = bestH.copy(), bestRH

    # ---- Final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

