    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    near1 = float(np.mean(Lf >= 0.99 * mx))
    return mx, m, near, near1


def _block_means(h, B, o):
    """Mean of h over blocks of size B starting at offset o (pad/trim)."""
    n = h.size
    lo = o
    if lo >= n:
        lo = 0
    seg = h[lo:]
    nb = seg.size // B
    if nb < 1:
        return np.array([seg.mean()]) if seg.size else np.array([0.0])
    seg = seg[:nb * B]
    return seg.reshape(nb, B).mean(axis=1)


def _modulate(h, B, o, sigma, rng):
    n = h.size
    means = _block_means(h, B, o)
    nb = means.size
    z = rng.randn(nb)
    if nb >= 3:
        ker = np.ones(3) / 3.0
        z = np.convolve(z, ker, mode='same')
    fac = np.exp(sigma * z)
    h2 = h.copy()
    lo = o
    for k in range(nb):
        a = lo + k * B
        b = min(n, a + B)
        if a >= n:
            break
        h2[a:b] *= fac[k]
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0, near1_0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near1%%=%.3f" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near1_0))

    rng = np.random.RandomState(20240607)

    # ---- Stage A: block-scale global modulation search ----
    block_sizes = [16, 32, 64, 128, 256]
    sigmas = [0.15, 0.4, 1.0]
    roundA = 0
    while time.process_time() < deadline - 2.0:
        roundA += 1
        B = block_sizes[rng.randint(len(block_sizes))]
        o = rng.randint(B)
        sigma = sigmas[rng.randint(len(sigmas))]

        # (2) block modulation
        hp = _modulate(best, B, o, sigma, rng)

        # (3) one round in three: contiguous-eighth multiplicative scan
        if roundA % 3 == 0:
            n = hp.size
            eighth = n // 8
            if eighth > 0:
                seg = rng.randint(8)
                a = seg * eighth
                b = min(n, a + eighth)
                factors = [0.85, 0.90, 0.95, 1.0, 1.05, 1.11, 1.18]
                best_scan_h = hp
                best_scan_R = R_of(hp)
                for fac in factors:
                    hc = hp.copy()
                    hc[a:b] *= fac
                    hc = _rescale(hc)
                    rc = R_of(hc)
                    if rc > best_scan_R:
                        best_scan_R = rc
                        best_scan_h = hc
                hp = best_scan_h

        sub_deadline = min(deadline - 2.0, time.process_time() + 8.0)

        # (4) polish
        h = _lbfgs_log(hp, 300, sub_deadline)
        r = R_of(h)
        if r > R_of(hp):
            hp = h

        if time.process_time() < sub_deadline - 1.0:
            n = hp.size
            Lf = _knots(hp)
            m = int(np.argmax(Lf))
            # random window OUTSIDE peak window
            wlen = rng.randint(1024, 4097)
            for _try in range(6):
                wlo = rng.randint(0, max(1, n - wlen))
                whi = wlo + wlen
                if whi < m - 300 or wlo > m + 300:
                    break
            free = np.arange(wlo, min(n, whi))
            h = _lbfgs_block(hp, free, 150, sub_deadline)
            r = R_of(h)
            if r > R_of(hp):
                hp = h

