    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    cuts = np.sort(rng.choice(np.arange(1, W), size=nblocks - 1, replace=False))
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(nblocks):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, 0.25))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _smooth_perturb(h, rng, sigma):
    n = h.size
    k = max(3, n // 40)
    noise = rng.normal(0.0, 1.0, n)
    kern = np.ones(k) / k
    sm = np.convolve(noise, kern, mode='same')
    h2 = h * np.exp(sigma * sm)
    return _rescale(np.clip(h2, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0
    hard_end = deadline - 0.3

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(20240607)
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=hard_end)
        return cur

    # Phase A: many smooth full-shape perturbations with smoothed-max polish.
    n = start_arr.size
    trials = 0
    while time.process_time() < hard_end - 8.0 and trials < 30:
        trials += 1
        sigma = 0.03 + 0.05 * rng.random()
        h = _smooth_perturb(start_arr, rng, sigma)
        for beta in (1500.0, 500.0, 150.0):
            if time.process_time() >= hard_end - 5.0:
                break
            c = _lbfgs_log(h, maxiter=200, deadline=hard_end, beta=beta)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 4.0:
            c = _lbfgs_log(h, maxiter=400, deadline=hard_end, beta=0.0)
            if R_of(c) >= R_of(h):
                h = c
        c = _window_polish_peak(h, hard_end, 0.20, 8, maxiter=300)
        if R_of(c) >= R_of(h):
            h = c
        _consider(h, R_of(h))

    print("phaseA R=%.6f N=%d trials=%d" % (best_r, best.size, trials))

    # Phase B: intensify around best with shrinking windows and beta continuation.
    cur = best.copy()
    cur_r = best_r
    while time.process_time() < hard_end - 2.0:
        h = cur.copy()
        improved = False
        for beta in (100.0, 50.0, 25.0, 12.0):
            if time.process_time() >= hard_end - 1.5:
                break
            c = _lbfgs_log(h, maxiter=250, deadline=hard_end, beta=beta)
            if R_of(c) > R_of(h):
                h = c
                improved = True
        if time.process_time() < hard_end - 1.5:
            c = _lbfgs_log(h, maxiter=500, deadline=hard_end, beta=0.0)
            if R_of(c) > R_of(h):
                h = c
                improved = True
        for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2)):
            if time.process_time() >= hard_end - 0.8:
                break
            c = _window_polish_peak(h, hard_end, frac, extra, maxiter=300)
            if R_of(c) > R_of(h):
                h = c
                improved = True
        r = R_of(h)
        if r > cur_r:
            cur, cur_r = h, r
            _consider(h, r)
        if not improved:
            lo, hi = _peak_region(cur)
            h2 = cur.copy()
            pad = max(4, (hi - lo) // 2)
            a = max(0, lo - pad); b = min(n - 1, hi + pad)
            band = h2[a:b + 1]
            h2[a:b + 1] = band * np.exp(rng.normal(0.0, 0.08, band.size))
            h2 = _rescale(np.clip(h2, 0.0, None))
            c = _lbfgs_log(h2, maxiter=300, deadline=hard_end, beta=0.0)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
                _consider(c, r)

    print("phaseB R=%.6f N=%d" % (best_r, best.size))

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_lav(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(N)
    edges = np.linspace(0.0, total, N + 1)
    mass_at = np.interp(edges, cm, np.arange(M + 1, dtype=float))
    new_h = np.diff(mass_at) * (M / float(N))
    return np.maximum(new_h, 0.0)


def _refine(h, deadline, iters):
    """Repeatedly run log-LBFGS + beta smoothing with rising beta."""
    best = h.copy()
    bR = R_of(best)
    betas = [0.0, 200.0, 800.0, 2000.0, 5000.0, 12000.0]
    for it in range(iters):
        if time.process_time() > deadline - 0.5:
            break
        beta = betas[it % len(betas)]
        c = _lbfgs_log(best, 600, deadline, beta=beta)
        rc = R_of(c)
        if rc > bR:
            best, bR = c, rc
    return best, bR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    def time_left(margin=0.5):
        return time.process_time() < deadline - margin

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = R_of(best)

    if best is None:
        best = np.ones(64)
        bestR = R_of(best)

    # The key change: a multi-resolution ladder that refines the given start
    # at higher N, with repeated polishing at each level, always keeping the
    # best-scoring shape. This extracts more resolution from a good start.
    h = best.copy()
    n0 = h.size
    # Candidate ladder: try current, then upsample substantially.
    ladder = [n0]
    for target in (16000, 32000, 64000, 100000, 160000):
        if target > n0:
            ladder.append(target)

    for N in ladder:
        if not time_left(2.0):
            break
        if N != h.size:
            h = _prolongate(h, N)
        c, rc = _refine(h, deadline, iters=8)
        if rc > bestR:
            best, bestR = c, rc
        # Also try beta-only polishing at this level.
        for beta in (3000.0, 8000.0, 20000.0):
            if not time_left(1.0):
                break
            c = _lbfgs_log(h, 500, deadline, beta=beta)
            rc = R_of(c)
            if rc > bestR:
                best, bestR = c, rc
                h = c
        # Window polish on peak region.
        for frac in (0.08, 0.15, 0.25):
            if not time_left(1.0):
                break
            c = _lbfgs_block(best, np.arange(best.size), 200, deadline)
            rc = R_of(c)
            if rc > bestR:
                best, bestR = c, rc

    # Final continuous polishing on the best shape until deadline.
    while time_left(1.0):
        c = _lbfgs_log(best, 500, deadline)
        rc = R_of(c)
        if rc > bestR:
            best, bestR = c, rc
        else:
            # switch to smoothing to escape
            c = _lbfgs_log(best, 400, deadline, beta=10000.0)
            rc = R_of(c)
            if rc > bestR:
                best, bestR = c, rc

    return best

import numpy as np
import time
from scipy.optimize import minimize
