    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _smooth_beta_anneal(h, deadline, iters=(2.0, 1.0, 0.5, 0.25, 0.1)):
    """Smooth-max homotopy: optimise with beta, decreasing, ending at plain max."""
    for beta in iters:
        if time.process_time() >= deadline - 1.0:
            break
        h2 = _lbfgs_log(h, 400, deadline, beta=beta)
        r2 = R_of(h2)
        if r2 >= R_of(h) - 1e-9:
            h = h2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    start_best = best.copy()
    start_R = bestR
    alt = None
    altR = 0.0

    # ---- Phase 1: smooth-max homotopy (NEW) ----
    # Optimise a smooth approximation of max(L), annealing beta -> inf.
    # This escapes the kinks of the plain max and finds a better local basin.
    if time.process_time() < deadline - 8.0:
        h = _smooth_beta_anneal(best.copy(), deadline)
        r = R_of(h)
        print("homotopy R=%.7f" % r)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r

    # ---- Phase 2: peak-window polish with growing windows ----
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 400, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.2f) R=%.7f" % (frac, bestR))

    # ---- Phase 3: phase shifts ----
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale(hp)
        if hp.sum() <= 0:
            continue
        hp = _lbfgs_log(hp, 500, deadline)
        hp = _window_polish_peak(hp, deadline, 0.35, 16)
        r = R_of(hp)
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("phase %+.2f R=%.7f" % (delta, bestR))

    # ---- Phase 4: alternating full / window polish until stall ----
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and altR > 0 and bestR <= start_R + 1e-15:
        return {"best": start_best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * 0.15))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


def _gauss_kernel(w):
    half = max(1, int(3 * w))
    x = np.arange(-half, half + 1, dtype=float)
    k = np.exp(-0.5 * (x / w) ** 2)
    k /= k.sum()
    return k


def _smooth_noise(n, w, rng):
    xi = rng.standard_normal(n)
    k = _gauss_kernel(w)
    if n > 1500:
        xi = fftconvolve(xi, k, mode='same')
    else:
        xi = np.convolve(xi, k, mode='same')
    return xi


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR

    # First, run the base's homotopy ladder briefly to make sure we're at a good point.
    bestH = best.copy()
    bestRH = bestR

    ladder = (4, 8, 16, 32, 64, 128)
    loop_end = t0 + budget_seconds * 0.30

    while time.process_time() < loop_end - 1.5:
        for p in ladder:
            if time.process_time() >= loop_end - 1.5:
                break
            sub_deadline = min(loop_end, time.process_time() + 3.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(bestH, 150, sub_deadline, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
        hs = _lbfgs_log(bestH, 150, min(loop_end, time.process_time() + 3.0))
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
        bestH, bestRH = _peak_polish(bestH, bestRH, 120, min(loop_end, time.process_time() + 3.0))

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    print("after ladder R=%.7f" % bestR)

    # ---- Orthogonal perturbation escape ----
    rng = np.random.default_rng(12345)
    widths = [8, 32, 128, 512]
    trial_end = t0 + budget_seconds * 0.85
    trial = 0
    n = best.size

    while time.process_time() < trial_end - 2.5:
        trial += 1
        w = widths[rng.integers(0, len(widths))]
        eps = 10.0 ** rng.uniform(-3.0, np.log10(3e-2))
        sign = 1.0 if rng.random() < 0.5 else -1.0

        xi = _smooth_noise(n, w, rng)
        # relative field
        xi = xi * best
        # gradient of -log R times h (relative gradient)
        try:
            _, g = _fun_grad(best)
        except Exception:
            break
        gh = g * best
        gg = float(np.dot(gh, gh))
        if gg > 0:
            xi = xi - (np.dot(xi, gh) / gg) * gh
        nx = float(np.linalg.norm(xi))
        if nx <= 0:
            continue
        xi = sign * eps * xi / nx
        # cap exponent to avoid overflow
        xi = np.clip(xi, -0.5, 0.5)
        hprime = _rescale(best * np.exp(xi))

        sub = min(trial_end, time.process_time() + 1.5)
        hp = _lbfgs_log(hprime, 120, sub)
        hp, rp = _peak_polish(hp, R_of(hp), 120, min(trial_end, time.process_time() + 1.0))
        rp = R_of(hp)

        accepted = rp > bestR + 1e-13
        if accepted:
            best, bestR = hp.copy(), rp
        print("trial %d w=%d eps=%.2e sign=%+d R=%.7f best=%.7f%s" %
              (trial, w, eps, int(sign), rp, bestR, " *" if accepted else ""))

    # ---- Final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 300, deadline - 0.5)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
        print("final sharp R=%.7f" % bestR)

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

