        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    N = best.size
    print("base R=%.7f (N=%d)" % (bestR, N))

    alt = None
    altR = 0.0
    beta_table = []

    betas = (1000.0, 3000.0, 1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7)
    fracs = (0.02, 0.05, 0.15)
    rng = np.random.default_rng(12345)

    def _time_left():
        return deadline - time.process_time()

    def _stage_lbfgs(h, iters, cap, beta=0.0):
        cap_deadline = min(deadline, time.process_time() + cap)
        return _lbfgs_log(h, iters, cap_deadline, beta=beta)

    def _stage_window(h, frac, iters, cap):
        cap_deadline = min(deadline, time.process_time() + cap)
        return _window_polish_peak(h, cap_deadline, frac, 8, maxiter=iters)

    round_idx = 0
    while _time_left() > 1.5:
        round_idx += 1
        round_improved = False

        # (1) beta continuation sweep
        hb = best.copy()
        for beta in betas:
            if _time_left() < 1.2:
                break
            cap = min(_time_left() - 0.5, 4.0)
            if cap <= 0.2:
                break
            hb = _stage_lbfgs(hb, 200, cap, beta=beta)
            r = R_of(hb)
            beta_table.append((round_idx, beta, r))
            print("stage beta=%.0f R=%.7f" % (beta, r))
            if r > bestR + 1e-13:
                best, bestR = hb.copy(), r
                round_improved = True
            else:
                # keep hb as the continuation state even if not improving
                pass

        # (2) exact sharp polish
        if _time_left() > 1.0:
            cap = min(_time_left() - 0.5, 5.0)
            if cap > 0.2:
                h = _stage_lbfgs(best, 300, cap, beta=0.0)
                r = R_of(h)
                print("stage sharp R=%.7f" % r)
                if r > bestR + 1e-13:
                    best, bestR = h, r
                    round_improved = True

        # (3) peak-window block polishes
        for frac in fracs:
            if _time_left() < 1.0:
                break
            cap = min(_time_left() - 0.5, 4.0)
            if cap <= 0.2:
                break
            h = _stage_window(best, frac, 150, cap)
            r = R_of(h)
            print("stage peak(%.2f) R=%.7f" % (frac, r))
            if r > bestR + 1e-13:
                best, bestR = h, r
                round_improved = True

        if not round_improved:
            # random-window perturbation kick
            if _time_left() < 1.0:
                break
            wlen = max(4, int(0.02 * N))
            lo = int(rng.integers(0, max(1, N - wlen)))
            hi = min(N, lo + wlen)
            h = best.copy()
            noise = np.exp(rng.normal(0.0, 0.05, hi - lo))
            h[lo:hi] = np.clip(h[lo:hi] * noise, 0.0, None)
            h = _rescale(h)
            cap = min(_time_left() - 0.5, 4.0)
            if cap > 0.2:
                h = _stage_lbfgs(h, 200, cap, beta=0.0)
                r = R_of(h)
                print("stage kick R=%.7f" % r)
                if r > bestR + 1e-13:
                    best, bestR = h, r

        if alt is None or bestR > altR:
            alt, altR = best.copy(), bestR

    print("--- beta table (round, beta, R) ---")
    for row in beta_table[-30:]:
        print("  %d %.0f %.7f" % row)
    print("final R=%.7f (N=%d) startR=%.7f" % (bestR, best.size, startR))

    if alt is not None and altR > startR + 1e-15 and altR >= bestR - 1e-15:
        return {"best": best, "alternative": alt}
    if alt is not None and altR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _mass_downsample(h, N0):
    n = h.size
    if n <= N0:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0, n, N0 + 1)
    out = np.empty(N0)
    for k in range(N0):
        lo = edges[k]; hi = edges[k + 1]
        ilo = int(np.floor(lo)); ihi = int(np.floor(hi))
        if ihi <= ilo:
            out[k] = 0.0
            continue
        val = c[ihi] - c[ilo]
        val -= (lo - ilo) * h[ilo]
        if ihi < n:
            val -= (ihi - hi) * h[ihi]
        out[k] = max(val, 0.0)
    return out


def _prolong2(h):
    n = h.size
    out = np.empty(2 * n)
    out[0::2] = h * 0.5
    out[1::2] = h * 0.5
    return out


def _restrict(h, m):
    """Mass-preserving restriction: h_r[i] = sum of h[i*m:(i+1)*m]."""
    n = h.size
    if m <= 1:
        return h.copy()
    nr = (n + m - 1) // m
    pad = nr * m - n
    if pad > 0:
        hh = np.concatenate((h, np.zeros(pad)))
    else:
        hh = h
    return hh.reshape(nr, m).sum(axis=1)


def _prolong(hc, n):
    """Mass-preserving prolongation: spread each hc[i] uniformly over its block."""
    nr = hc.size
    m = (n + nr - 1) // nr
    out = np.repeat(hc / m, m)
    if out.size > n:
        out = out[:n]
    elif out.size < n:
        out = np.concatenate((out, np.zeros(n - out.size)))
    return out


def _f66_level(h, N, deadline, record_R, tag=""):
    if h.size != N:
        if h.size > N:
            h = _mass_downsample(h, N)
        else:
            while h.size < N:
                h = _prolong2(h)
            if h.size > N:
                h = _mass_downsample(h, N)
    h = _rescale(h)
    best = h.copy()
    bestR = R_of(best)
    for beta in (2.0, 5.0, 10.0, 20.0, 50.0, 100.0):
        if time.process_time() >= deadline - 0.5:
            break
        cap = min(deadline - 0.4, time.process_time() + 2.0)
        hs = _lbfgs_log(best, 100, cap, beta=beta)
        rs = R_of(hs)
        if rs > bestR + 1e-13:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.4, time.process_time() + 3.0)
        hs = _lbfgs_log(best, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-13:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.4, time.process_time() + 2.0)
        hp = _lbfgs_block(best, free, 150, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            best, bestR = hp, rp
    print("  level N=%d %s R=%.7f" % (N, tag, bestR))
    return best, bestR


def _vcycle(h_best, deadline):
    """One multigrid V-cycle. Returns (candidate, coarseR, candR)."""
    n = h_best.size
    m = 4
    hc = _restrict(h_best, m)
    hc = _rescale(hc)
    # refine coarse by beta ladder, keeping best exact R of prolongation
    best_hc = hc.copy()
    best_cR = R_of(_prolong(best_hc, n))
    coarse_deadline = min(deadline, time.process_time() + 3.0)
    for beta in (2.0, 5.0, 10.0, 25.0, 50.0, 100.0):
        if time.process_time() >= coarse_deadline - 0.3:
            break
        cap = min(coarse_deadline, time.process_time() + 1.0)
        hc2 = _lbfgs_log(best_hc, 120, cap, beta=beta)
        cR = R_of(_prolong(hc2, n))
        if cR > best_cR + 1e-13:
            best_hc, best_cR = hc2, cR
    coarseR = best_cR
    # add fine residual back
    fine_res = h_best - _prolong(_restrict(h_best, m), n)
    cand = _prolong(best_hc, n) + fine_res
    cand = _rescale(np.clip(cand, 0, None))
    candR = R_of(cand)
    return cand, coarseR, candR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- V-cycles ----
    for k in range(4):
        if time.process_time() >= deadline - 8.0:
            break
        vc_deadline = min(deadline - 4.0, time.process_time() + 10.0)
        cand, coarseR, candR = _vcycle(bestH, vc_deadline)
        # polish
        polished = cand
        polR = candR
        if time.process_time() < vc_deadline - 0.5:
            cap = min(vc_deadline, time.process_time() + 3.0)
            hs = _lbfgs_log(cand, 300, cap, beta=0.0)
            rs = R_of(hs)
            if rs > polR + 1e-13:
                polished, polR = hs, rs
        if time.process_time() < vc_deadline - 0.5:
            free = _peak_window(polished, frac=0.05)
            cap = min(vc_deadline, time.process_time() + 2.0)
            hp = _lbfgs_block(polished, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > polR + 1e-13:
                polished, polR = hp, rp
        print("V-cycle %d coarseR=%.7f candR=%.7f after polish R=%.7f" %
              (k, coarseR, candR, polR))
        if polR > bestRH + 1e-13:
            bestH, bestRH = polished.copy(), polR
            print("  NEW BEST R=%.7f" % bestRH)

    # ---- leftover time: sharp polish + small peak blocks ----
    rng = np.random.default_rng(987654)
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        if time.process_time() < loop_end - 1.0:
            cap = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs.copy(), rs
                improved = True
        if time.process_time() < loop_end - 1.0:
            frac = float(rng.choice([0.02, 0.05]))
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                improved = True
        if improved:
            print("  iter=%d R=%.7f" % (it, bestRH))

    print("final R=%.7f (best of experiment)" % bestRH)

    if bestRH > start_bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH
    else:
        best, bestR = start_best, start_bestR

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    if bestH.size == start_best.size and bestRH > start_bestR - 1e-6 and bestRH < start_bestR + 1e-12:
        return {"best": start_best, "alternative": bestH}
    return {"best": start_best, "alternative": None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _revive_zeros(h, lo, hi, radius=256, factor=1e-3):
    h = h.copy()
    win = h[lo:hi]
    zeros = np.flatnonzero(win <= 0)
    if zeros.size == 0:
        return h
    pos_idx = np.flatnonzero(win > 0)
    if pos_idx.size == 0:
        return h
    pos_vals = win[pos_idx]
    for z in zeros:
        left = np.searchsorted(pos_idx, z - radius, side='left')
        right = np.searchsorted(pos_idx, z + radius, side='right')
        if right > left:
            lm = pos_vals[left:right].mean()
        else:
            lm = pos_vals.mean()
        win[z] = factor * lm
    h[lo:hi] = win
    return h


def _perturb_window(h, lo, hi, rng, sigma=0.35):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo))
    hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    h = _revive_zeros(h, lo, hi, radius=256, factor=1e-3)
    return _rescale(h)


def _fine_polish(h, deadline):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    for frac in (0.02, 0.04, 0.08):
        if time.process_time() >= deadline - 0.4:
            break
        for beta in (None, 8000.0, 20000.0):
            if time.process_time() >= deadline - 0.4:
                break
            _try(_window_polish_peak(cur, deadline, frac, 4,
                                     maxiter=300, beta=beta))
    if time.process_time() < deadline - 0.4:
        _try(_lbfgs_log(cur, maxiter=600, deadline=deadline))
    return cur, cur_r


def _prolong_mass(h, N2):
    n = h.size
    if N2 <= n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N2)
    edges = np.linspace(0.0, float(n), N2 + 1)
    newc = np.interp(edges, np.arange(n + 1, dtype=float), c)
    h2 = np.diff(newc)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return np.ones(N2)
    return h2


def _refine_difference(h, deadline, levels=3):
    """Add mass where f*f peaks: multiply h by a smoothed tilt of the peak region."""
    if time.process_time() >= deadline - 1.0:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    # tilt: raise h where the knot density near the peak is high
    tilt = np.clip(Lf[1:-1] / mx, 0.0, None)
    # smooth the tilt a bit
    k = max(1, h.size // 400)
    ker = np.ones(2 * k + 1) / (2 * k + 1)
    tilt = np.convolve(tilt, ker, mode='same')
    h2 = h * (1.0 + 0.02 * tilt)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r + 1e-12:
            best, best_r = cand.copy(), r
        elif r > alt_r + 1e-12:
            alternative, alt_r = cand.copy(), r

    # ---- Prolong to higher N and fine-polish ----
    N2 = min(512000, max(96000, base.size * 2))
    hf = _prolong_mass(base, N2)
    hf = _rescale(hf)
    r0 = R_of(hf)
    print("prolonged R=%.7f (base %.7f) N=%d" % (r0, base_r, hf.size))

    if time.process_time() < hard_end - 2.0:
        hp, rp = _fine_polish(hf, hard_end)
        print("fine polish R=%.7f" % rp)
        _consider(hp, rp)
        if rp > r0:
            hf, r0 = hp, rp

    cur = hf
    cur_r = r0
    n = cur.size

    # Peak refinement: tilt
    if time.process_time() < hard_end - 2.0:
        ht = _refine_difference(cur, hard_end)
        ht = _lbfgs_log(ht, maxiter=400, deadline=hard_end)
        rt = R_of(ht)
        print("tilt R=%.7f" % rt)
        _consider(ht, rt)
        if rt > cur_r:
            cur, cur_r = ht, rt

    # Seeded block perturbations at fine grid
    seed = 0
    while time.process_time() < hard_end - 1.0 and seed < 12:
        rng = np.random.default_rng(4242 + seed * 977)
        lo = int(rng.uniform(0.10, 0.50) * n)
        hi = min(n, lo + n // 2)
        base_for_pert = cur
        if seed % 3 == 2:
            base_for_pert = cur[::-1].copy()
        hp = _perturb_window(base_for_pert, lo, hi, rng, sigma=0.30)
        hp = _lbfgs_log(hp, maxiter=500, deadline=hard_end)
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= hard_end - 0.5:
                break
            cand = _window_polish_peak(hp, hard_end, frac, 8,
                                       maxiter=400, beta=None)
            if R_of(cand) > R_of(hp):
                hp = cand
        rp = R_of(hp)
        print("seed %d R=%.7f (cur %.7f base %.7f)"
              % (seed, rp, cur_r, base_r))
        _consider(hp, rp)
        if rp > cur_r + 1e-12:
            cur, cur_r = hp, rp
        seed += 1

    if time.process_time() < hard_end - 0.5:
        hfin, rfin = _fine_polish(cur, hard_end)
        _consider(hfin, rfin)

    print("final R=%.7f N=%d | base R=%.7f N=%d"
          % (best_r, best.size, base_r, base.size))

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_topk(h, k):
    """Replace the max by a soft-max-like average over the top-k knots, with
    the true max kept as a hard cap term so we never exceed the real inf-norm.
    Uses the log-sum-exp over the k largest knots; smoother than a single max,
    encouraging a flat top which raises ||L||_2^2 / ||L||_inf."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    # top-k indices
    if k >= Lf.size:
        idx = np.arange(Lf.size)
    else:
        idx = np.argpartition(Lf, -k)[-k:]
    beta = 1.0 / (1e-3 * mx + 1e-30)
    vals = Lf[idx]
    m2 = vals.max()
    e = np.exp(beta * (vals - m2))
    Z = e.sum()
    w = e / Z
    sm = m2 + np.log(Z) / beta
    gLf = -dq / num + 2.0 / s
    # gradient of sm wrt L: only on the top-k knots
    gsm = np.zeros_like(Lf)
    gsm[idx] = w / sm
    gLf = np.zeros_like(Lf)
    gLf[:-1] += (2 * Lf[:-1] + Lf[1:]) / 3.0
    gLf[1:] += (Lf[:-1] + 2 * Lf[1:]) / 3.0
    gLf = -gLf / num + gsm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _up_resample(h, N_big):
    n = h.size
    if n == N_big:
        return h.copy()
    x = np.linspace(0.0, 1.0, n)
    xb = np.linspace(0.0, 1.0, N_big)
    hb = np.interp(xb, x, h)
    return np.clip(hb, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: top-k soft-max polishing.  The true objective has a kink at
    # the argmax knot; using a log-sum-exp over the top-k knots gives a smooth
    # surrogate that pushes the whole top band up together (flattening the
    # peak), which is exactly what raises ||L||_2^2 / ||L||_inf.  We anneal
    # k from large (very smooth) to small (approaching true max), keeping the
    # best actual R.  This is different from the single-knot soft-max used by
    # the base program (which only softens a fixed eps band) and directly
    # targets the flat-top structure that the score rewards.

    n = best.size
    for k in (512, 256, 128, 64, 32, 16):
        if time.process_time() >= deadline - 6.0:
            break
        fg = (lambda hh, kk=k: _fun_grad_topk(hh, kk))
        # polish the peak region (and a bit beyond) with the top-k surrogate
        win = _peak_window(best, frac=0.35)
        h = _lbfgs_block(best, win, maxiter=300, deadline=deadline, fg=fg)
        if time.process_time() >= deadline - 5.0:
            break
        h = _lbfgs_log(h, 300, deadline, fg=fg)
        r = R_of(h)
        print("topk k=%d R=%.7f" % (k, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
        elif r > bestR - 0.001:
            best = h  # keep going from flatter state

    # sharpen with the exact objective
    for _ in range(3):
        if time.process_time() >= deadline - 1.5:
            break
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("sharp R=%.7f" % bestR)
        else:
            break

    # try one grid refinement if budget remains
    if time.process_time() < deadline - 10.0:
        N2 = int(min(1000000, max(n, int(n * 1.5))))
        if N2 > n:
            hu = _up_resample(best, N2)
            hu = _rescale(hu)
            fg = (lambda hh: _fun_grad_topk(hh, 128))
            hu = _lbfgs_log(hu, 300, deadline, fg=fg)
            hu = _lbfgs_log(hu, 400, deadline)
            r = R_of(hu)
            print("refine N=%d R=%.7f" % (N2, r))
            if r > bestR + 1e-12:
                best, bestR = hu, r

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lm = Lf.max()
    w = np.exp(beta * (Lf - Lm))
    Z = w.sum()
    gLf = -dq / num
    gLf += beta * (w / Z)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (np.log(Z) / beta + Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _zero_runs(h):
    runs = []
    z = (h <= 1e-14 * max(h.max(), 1e-300))
    n = h.size
    i = 0
    while i < n:
        if z[i]:
            j = i
            while j < n and z[j]:
                j += 1
            runs.append((i, j - i))
            i = j
        else:
            i += 1
    return runs


def _split_side(h, side, K, m):
    """Split outer K cells on side into m equal subcells. Exact step function."""
    n = h.size
    if side == 'left':
        lo, hi = 0, K
    elif side == 'right':
        lo, hi = n - K, n
    else:
        return None
    if hi - lo < K or K <= 0 or m <= 0:
        return None
    seg = h[lo:hi]
    rep = np.repeat(seg, m) / m
    if side == 'left':
        return np.concatenate((rep, h[hi:]))
    else:
        return np.concatenate((h[:lo], rep))


def _tilt_split(h, side, K, m, s):
    """Split outer K cells into m subcells with linear tilt factor."""
    n = h.size
    if side == 'left':
        lo, hi = 0, K
    elif side == 'right':
        lo, hi = n - K, n
    else:
        return None
    if hi - lo < K or K <= 0 or m <= 0:
        return None
    seg = h[lo:hi]
    j = np.arange(m, dtype=float)
    if m > 1:
        tilt = 1.0 + s * (j - (m - 1) / 2.0) / (m - 1)
    else:
        tilt = np.ones(1)
    tilt = np.clip(tilt, 0.0, None)
    block = np.outer(seg / m, tilt).ravel()
    if side == 'left':
        return np.concatenate((block, h[hi:]))
    else:
        return np.concatenate((h[:lo], block))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    R0 = bestR

    runs = _zero_runs(best)
    nz = np.flatnonzero(best > 1e-14 * max(best.max(), 1e-300))
    if nz.size > 0:
        sup_lo, sup_hi = int(nz[0]), int(nz[-1])
    else:
        sup_lo, sup_hi = 0, best.size - 1
    print("base R=%.7f N=%d support=[%d,%d] zero-runs=%d" %
          (bestR, best.size, sup_lo, sup_hi, len(runs)))
    if runs:
        big = sorted(runs, key=lambda t: -t[1])[:6]
        print("  top zero-runs (start,len):", big)
    k = min(40, best.size)
    print("  left40:", np.array2string(best[:k], precision=4, max_line_width=200))
    print("  right40:", np.array2string(best[-k:], precision=4, max_line_width=200))

    bestH = best.copy()
    bestRH = bestR

    sides = ['left', 'right', 'both']
    Ks = [4, 8]
    ms = [8, 16]
    ss = [0.5, 1.0, 2.0]

    table = []

    def do_sweep(incumbent, inc_R, tag):
        nonlocal bestH, bestRH
        cands = []
        for side in sides:
            for K in Ks:
                for m in ms:
                    if side == 'both':
                        # split both sides
                        hl = _split_side(incumbent, 'left', K, m)
                        if hl is None:
                            continue
                        # need to split right of hl too; right K cells of hl are last K
                        hr = _split_side(hl, 'right', K, m)
                        if hr is None:
                            continue
                        h_ref = hr
                    else:
                        h_ref = _split_side(incumbent, side, K, m)
                        if h_ref is None:
                            continue
                    rref = R_of(h_ref)
                    if abs(rref - inc_R) > 1e-12:
                        print("  VALIDATION FAIL side=%s K=%d m=%d rref=%.10f inc=%.10f" %
                              (side, K, m, rref, inc_R))
                        continue
                    cands.append((rref, side, K, m, 0.0, h_ref))
                    for s in ss:
                        if side == 'both':
                            ht = _tilt_split(incumbent, 'left', K, m, s)
                            if ht is None:
                                continue
                            ht = _tilt_split(ht, 'right', K, m, s)
                        else:
                            ht = _tilt_split(incumbent, side, K, m, s)
                        if ht is None:
                            continue
                        rt = R_of(ht)
                        cands.append((rt, side, K, m, s, ht))
        cands.sort(key=lambda t: -t[0])
        top = cands[:8]
        print("[%s] sweep %d cands, top unpolished R=%.7f" %
              (tag, len(cands), top[0][0] if top else 0.0))
        for (rc, side, K, m, s, hc) in top:
            if time.process_time() > deadline - 4.0:
                break
            n = hc.size
            # free region: new subcells + 2*m*K cells inward
            if side == 'left':
                free = np.arange(0, min(n, K * m + 2 * m * K))
            elif side == 'right':
                free = np.arange(max(0, n - (K * m + 2 * m * K)), n)
            else:
                free = np.concatenate((
                    np.arange(0, min(n, K * m + 2 * m * K)),
                    np.arange(max(0, n - (K * m + 2 * m * K)), n)))
            free = np.unique(np.clip(free, 0, n - 1))
            sub_dl = min(deadline - 2.0, time.process_time() + 3.0)
            hp = _lbfgs_block(hc, free, 150, sub_dl)
            rp = R_of(hp)
            if time.process_time() < deadline - 2.0:
                sub_dl = min(deadline - 1.5, time.process_time() + 3.0)
                hg = _lbfgs_log(hp, 250, sub_dl)
                rg = R_of(hg)
                if rg > rp:
                    hp, rp = hg, rg
            for beta in (1e3, 1e4):
                if time.process_time() > deadline - 1.5:
                    break
                sub_dl = min(deadline - 1.0, time.process_time() + 2.0)
                hb = _lbfgs_log(hp, 100, sub_dl,
                                fg=lambda hh, b=beta: _fun_grad_beta(hh, b))
                rb = R_of(hb)
                if rb > rp + 1e-13:
                    hp, rp = hb, rb
            table.append((side, K, m, s, rc, rp))
            print("  cand side=%s K=%d m=%d s=%.1f Rbefore=%.7f Rafter=%.7f" %
                  (side, K, m, s, rc, rp))
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("    ACCEPT R=%.7f" % bestRH)

    round_i = 0
    while time.process_time() < deadline - 4.0:
        round_i += 1
        do_sweep(bestH, bestRH, "round%d" % round_i)
        if round_i >= 3:
            break

    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m_, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m_, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolong(h, N):
    """Cumulative-mass prolongation to N steps, preserving exact zeros."""
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def _smooth_to(h, N, sigma):
    """Resample to N via cumulative-mass, then Gaussian-smooth (circular-free)."""
    hp = _prolong(h, N)
    if sigma <= 0:
        return hp
    k = int(max(1, round(sigma * 3)))
    x = np.arange(-k, k + 1)
    g = np.exp(-0.5 * (x / sigma) ** 2)
    g /= g.sum()
    # pad by reflection to keep ends well behaved
    pad = k
    ext = np.concatenate((hp[pad - 1::-1], hp, hp[:-pad - 1:-1]))
    sm = np.convolve(ext, g, mode='same')
    out = sm[pad:pad + N]
    return np.maximum(out, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def time_left():
        return time.process_time() < deadline

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = R_of(best)

    alt = None
    altR = -1.0

    if best is None:
        best = np.ones(64)
        bestR = R_of(best)

    h = best.copy()

    def try_accept(cand):
        nonlocal best, bestR
        rc = R_of(cand)
        if rc > bestR:
            bestR = rc
            best = cand.copy()
            return True
        return False

    def consider_alt(cand):
        nonlocal alt, altR
        rc = R_of(cand)
        if rc > altR:
            altR = rc
            alt = cand.copy()

    # The main idea: work at a HIGH resolution from the start (upsample start
    # by cumulative mass + smoothing), then optimise with a schedule of
    # beta-annealing that gradually sharpens the sup penalty. This lets the
    # optimiser reshape the broad peak plateau that the previous program
    # already found, but at a finer grid it could not reach efficiently.
    base_N = h.size
    target_N = max(32000, min(200000, base_N * 4))
    if target_N > 1000000:
        target_N = 1000000

    # Build an upsampled, slightly smoothed working copy.
    hw = _smooth_to(h, target_N, sigma=max(1.0, target_N / base_N * 0.5))
    if R_of(hw) < bestR - 5e-3:
        # smoothing hurt too much; fall back to plain prolongation
        hw = _prolong(h, target_N)
        if R_of(hw) < bestR - 5e-3:
            hw = h.copy()

    # Stage 1: coarse beta annealing on the full vector (log parametrisation).
    betas = (20.0, 60.0, 200.0, 600.0, 2000.0, 6000.0, 20000.0)
    for beta in betas:
        if not time_left():
            break
        c = _lbfgs_log(hw, 600, deadline, beta=beta)
        if R_of(c) > R_of(hw):
            hw = c
        try_accept(hw)
        consider_alt(hw)

    # Stage 2: hard-sup polish at current resolution.
    for _ in range(3):
        if not time_left():
            break
        c = _lbfgs_log(hw, 800, deadline)
        if R_of(c) > R_of(hw):
            hw = c
        try_accept(hw)

    # Stage 3: peak-window polishing with growing windows and beta schedule.
    fracs = (0.06, 0.12, 0.20, 0.32, 0.50)
    fi = 0
    betas_pol = (100.0, 400.0, 1500.0, 5000.0)
    bi = 0
    while time_left():
        frac = fracs[fi % len(fracs)]
        fi += 1
        lo, hi = _peak_region(hw, tol=0.999)
        span = max(1, hi - lo)
        pad = max(16, int(span * frac))
        lo2 = max(0, lo - pad)
        hi2 = min(hw.size - 1, hi + pad)
        free = np.arange(lo2, hi2 + 1)
        beta = betas_pol[bi % len(betas_pol)]
        bi += 1
        c = _lbfgs_block(hw, free, 500, deadline, beta=beta)
        if R_of(c) > R_of(hw):
            hw = c
        try_accept(hw)
        if not time_left():
            break
        # occasionally full-vector hard-sup step
        if bi % 3 == 0:
            c = _lbfgs_log(hw, 500, deadline)
            if R_of(c) > R_of(hw):
                hw = c
            try_accept(hw)

    # Stage 4: if we still have time, upsample once more and re-polish.
    if time_left() and hw.size < 1000000:
        newN = min(1000000, hw.size * 2)
        hu = _prolong(hw, newN)
        if R_of(hu) > R_of(hw) - 1e-3:
            hw = hu
            for beta in (200.0, 800.0, 3000.0):
                if not time_left():
                    break
                c = _lbfgs_log(hw, 500, deadline, beta=beta)
                if R_of(c) > R_of(hw):
                    hw = c
                try_accept(hw)
            while time_left():
                c = _lbfgs_log(hw, 400, deadline)
                if R_of(c) > R_of(hw):
                    hw = c
                try_accept(hw)
                if not time_left():
                    break
                lo, hi = _peak_region(hw, tol=0.999)
                span = max(1, hi - lo)
                pad = max(16, int(span * 0.20))
                lo2 = max(0, lo - pad)
                hi2 = min(hw.size - 1, hi + pad)
                free = np.arange(lo2, hi2 + 1)
                c = _lbfgs_block(hw, free, 400, deadline)
                if R_of(c) > R_of(hw):
                    hw = c
                try_accept(hw)

    if alt is not None and altR > bestR:
        return {"best": alt, "alternative": best}
    if alt is not None and altR > 0 and not np.allclose(alt.size, best.size):
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _peak_window(h, frac, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish_peak(h, frac, deadline, maxiter=300):
    h = np.asarray(h, dtype=float)
    if h.size < 8:
        return h
    free = _peak_window(h, frac)
    return _lbfgs_block(h, free, maxiter, deadline, beta=0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Build a working candidate at native size (or prolongate to 8192 if small).
    N_work = h.size
    if N_work < 2048:
        N_work = 8192
        h = _rescale(_prolongate_mass(h, N_work))
        R = R_of(h)
        if R > best_R:
            best_R, best_h = R, h.copy()
        print("prolonged N=%d R=%.6f" % (N_work, R))

    cur_h = h.copy()
    cur_R = R_of(cur_h)

    # Phase 1: logsumexp homotopy (smooth max) at current size.
    for beta in (16, 32, 64, 128, 256, 512):
        if time.process_time() > deadline - 3.0:
            break
        h2 = _lbfgs_log(cur_h, 400, deadline, beta=beta)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    # Phase 2: exact-max polish.
    if time.process_time() < deadline - 2.0:
        h2 = _lbfgs_log(cur_h, 500, deadline, beta=0.0)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    # Phase 3: peak-window polish (exact max), narrowing fracs.
    for frac in (0.30, 0.15, 0.08, 0.04):
        if time.process_time() > deadline - 2.0:
            break
        h2 = _polish_peak(cur_h, frac, deadline, maxiter=250)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    print("phase3 R=%.6f N=%d" % (best_R, best_h.size))

    # Phase 4: alternate global (logsumexp) and peak-window polish until deadline.
    betas = (1024, 512, 256, 128)
    ai = 0
    while time.process_time() < deadline - 1.5:
        beta = betas[ai % len(betas)]
        ai += 1
        h2 = _lbfgs_log(cur_h, 200, deadline, beta=beta)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if time.process_time() > deadline - 1.5:
            break
        frac = (0.05, 0.10, 0.20)[ai % 3]
        h2 = _polish_peak(cur_h, frac, deadline, maxiter=200)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_topk(h, kfrac):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = max(1, int(kfrac * n))
    if k >= n:
        k = n
    idx = np.argpartition(Lf, -k)[-k:]
    sm = Lf[idx].mean()
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[idx] += (1.0 / sm) / k
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _perturb_peak(h, rng):
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    wlen = int(rng.randint(128, 513))
    sigma = rng.uniform(0.02, 0.06)
    lo = max(0, m - wlen)
    hi = min(n, m + wlen)
    if hi - lo < 4:
        return h
    x = np.arange(lo, hi, dtype=float)
    center = rng.uniform(lo, hi)
    width = max(2.0, (hi - lo) * sigma)
    bump = np.exp(-0.5 * ((x - center) / width) ** 2)
    ker = np.ones(9) / 9.0
    bump = np.convolve(bump, ker, mode='same')
    amp = rng.uniform(0.03, 0.10)
    h2 = h.copy()
    h2[lo:hi] *= np.exp(amp * bump)
    return _rescale(h2)


def _perturb_global(h, rng):
    n = h.size
    m = rng.randint(3, 16)
    x = np.linspace(0.0, 1.0, n)
    field = np.zeros(n)
    for j in range(1, m + 1):
        a = rng.randn()
        b = rng.uniform(0.0, 2.0 * np.pi)
        field += a * np.sin(2.0 * np.pi * j * x + b)
    fm = np.abs(field).max()
    if fm > 0:
        field /= fm
    amp = rng.uniform(0.01, 0.10)
    return _rescale(h * np.exp(amp * field))


def _same_shape(a, b):
    if a.size != b.size:
        return False
    aa = a / (a.max() + 1e-300)
    bb = b / (b.max() + 1e-300)
    return np.allclose(aa, bb, rtol=1e-3, atol=1e-5)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_h = _rescale(base)
            start_R = R_of(start_h)
        else:
            start_h, start_R = None, 0.0
    else:
        start_h, start_R = None, 0.0

    if start_h is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_h = _rescale(h)
        start_R = R_of(start_h)

    best = start_h.copy()
    bestR = start_R
    print("base R=%.7f N=%d" % (bestR, best.size))

    rng = np.random.RandomState(98765)

    # Work at a moderate resolution first, then grow only if it helps.
    # Start directly from the given start (do NOT upscale unless beneficial).
    cur = best.copy()
    curR = bestR

    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        sub = min(deadline - 1.0, time.process_time() + 6.0)

        # (1) sharp polish
        h = _lbfgs_log(cur, 200, sub)
        r = R_of(h)
        if r > curR + 1e-14:
            cur, curR = h, r

        # (2) top-k plateau polishes
        for kfrac in (0.02, 0.005):
            if time.process_time() >= sub - 0.5:
                break
            fg = (lambda hh, kf=kfrac: _fun_grad_topk(hh, kf))
            h = _lbfgs_log(cur, 120, sub, fg=fg)
            r = R_of(h)
            if r > curR + 1e-14:
                cur, curR = h, r

        # (3) moderate beta polish
        if time.process_time() < sub - 0.5:
            h = _lbfgs_log(cur, 80, sub, beta=1e7)
            r = R_of(h)
            if r > curR + 1e-14:
                cur, curR = h, r

        # (4) global perturbation
        if time.process_time() < sub - 0.5:
            hp = _perturb_global(cur, rng)
            h = _lbfgs_log(hp, 100, sub)
            r = R_of(h)
            if r > curR + 1e-14:
                cur, curR = h, r

        # (5) peak perturbation
        if time.process_time() < sub - 0.5:
            hp = _perturb_peak(cur, rng)
            h = _lbfgs_log(hp, 90, sub)
            r = R_of(h)
            if r > curR + 1e-14:
                cur, curR = h, r

        if curR > bestR + 1e-14:
            best, bestR = cur.copy(), curR
        print("it%d R=%.7f best=%.7f" % (it, curR, bestR))

        # (6) try higher resolution occasionally, keeping only if better
        if it % 3 == 0 and cur.size * 2 <= 1000000 and time.process_time() < deadline - 12.0:
            up = _rescale(np.repeat(cur, 2))
            upR = R_of(up)
            sub2 = min(deadline - 1.0, time.process_time() + 9.0)
            h = _lbfgs_log(up, 200, sub2)
            r = R_of(h)
            if r > upR + 1e-14:
                up, upR = h, r
            if time.process_time() < sub2 - 0.5:
                fg = (lambda hh: _fun_grad_topk(hh, 0.01))
                h = _lbfgs_log(up, 120, sub2, fg=fg)
                r = R_of(h)
                if r > upR + 1e-14:
                    up, upR = h, r
            if upR > curR + 1e-14:
                cur, curR = up, upR
                if curR > bestR + 1e-14:
                    best, bestR = cur.copy(), curR
                print("  up R=%.7f N=%d" % (curR, cur.size))

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_R + 1e-12:
        return best
    if start_h is not None and not _same_shape(best, start_h):
        return {"best": start_h, "alternative": best}
    return start_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    """Smooth approximation of max via softmax, for escaping the flat max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _mass_resample(h, Nnew):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew) / Nnew
    x = np.linspace(0.0, 1.0, Nnew + 1)
    src_x = np.linspace(0.0, 1.0, N + 1)
    target_c = np.interp(x, src_x, c)
    out = np.diff(target_c)
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return np.ones(Nnew) / Nnew
    return out * (total / out.sum())


def _peak_window(h, frac=0.12, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, time_share, rng, kick=0.0):
    """Iterated local search: log-gradient polish + peak-window polish +
    optional random multiplicative kick around the peak to escape plateaus."""
    best = h.copy()
    bestR = R_of(best)
    if bestR <= 0:
        return best, bestR
    sub = min(deadline - 0.5, time.process_time() + time_share)
    h2 = _lbfgs_log(h, 400, sub, beta=0.0)
    r2 = R_of(h2)
    if r2 > bestR:
        best, bestR = h2, r2
    for beta in [16.0, 64.0, 256.0]:
        if time.process_time() >= deadline - 0.5:
            break
        sub = min(deadline - 0.5, time.process_time() + time_share * 0.5)
        h3 = _lbfgs_log(best, 200, sub, beta=beta)
        r3 = R_of(h3)
        if r3 > bestR:
            best, bestR = h3, r3
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.15)
        sub = min(deadline - 0.5, time.process_time() + time_share * 0.6)
        h4 = _lbfgs_block(best, free, 200, sub)
        r4 = R_of(h4)
        if r4 > bestR:
            best, bestR = h4, r4
    # random kick: perturb the top region multiplicatively, re-polish
    if kick > 0 and time.process_time() < deadline - 0.5:
        Lf = _knots(best)
        m = int(np.argmax(Lf))
        n = best.size
        center = int(round((m - 1) / 2.0))
        w = max(32, n // 6)
        lo = max(0, center - w); hi = min(n, center + w)
        hk = best.copy()
        noise = np.exp(kick * rng.standard_normal(hi - lo))
        hk[lo:hi] = hk[lo:hi] * noise
        hk = _rescale(hk)
        sub = min(deadline - 0.5, time.process_time() + time_share * 0.6)
        hk = _lbfgs_log(hk, 300, sub)
        rk = R_of(hk)
        if rk > bestR:
            best, bestR = hk, rk
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(98765)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        start_best = _rescale(np.ones(N))
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best_h = start_best.copy()
    best_R = start_bestR
    alt_h = None
    alt_R = 0.0

    # ---- Main track: iterated local search on the start at full resolution ----
    if start_best.size >= 1000 and time.process_time() < deadline - 5.0:
        h = start_best.copy()
        n_rounds = 0
        while time.process_time() < deadline - 2.0:
            remaining = deadline - time.process_time()
            share = max(0.5, min(6.0, remaining * 0.4))
            # decay kick strength over rounds
            kick = 0.15 if n_rounds % 3 == 0 else (0.05 if n_rounds % 3 == 1 else 0.0)
            h2, r2 = _polish(h, deadline, share, rng, kick=kick)
            if r2 > best_R + 1e-12:
                best_R = r2
                best_h = h2.copy()
                print("  ILS round %d R=%.7f" % (n_rounds, best_R))
            if r2 > R_of(h) + 1e-13:
                h = h2
            else:
                # restart from best with a fresh kick
                h = best_h.copy()
                n_rounds += 1
                if n_rounds > 200:
                    break
            if time.process_time() >= deadline - 2.0:
                break

    # ---- Secondary track: coarse multistart, escalate, compare ----
    if time.process_time() < deadline - 8.0:
        N0 = 512
        seeds = []
        for _ in range(6):
            seeds.append(_seed_blocky(rng, N0))
        seeds.append(_mass_resample(start_best, N0))
        for s in seeds:
            if time.process_time() >= deadline - 6.0:
                break
            s = _rescale(np.clip(s, 0, None))
            sub = min(deadline - 6.0, time.process_time() + 0.8)
            s2 = _lbfgs_log(s, 200, sub)
            if R_of(s2) < start_bestR - 0.02:
                continue
            # escalate
            h = s2
            for N in [1024, 2048, 4096, 8192, 16384]:
                if time.process_time() >= deadline - 5.0:
                    break
                h = _rescale(_mass_resample(h, N))
                sub = min(deadline - 5.0, time.process_time() + 1.0)
                h = _lbfgs_log(h, 200, sub)
            if time.process_time() >= deadline - 4.0:
                continue
            Nt = start_best.size
            h = _rescale(_mass_resample(h, Nt))
            h2, r2 = _polish(h, deadline, 3.0, rng, kick=0.0)
            if r2 > best_R + 1e-10:
                best_R = r2
                best_h = h2.copy()
                print("  escalated new best R=%.7f" % best_R)
            elif r2 > alt_R + 1e-10:
                alt_R = r2
                alt_h = h2.copy()

    # Final polish of the best
    if time.process_time() < deadline - 1.0:
        h2, r2 = _polish(best_h, deadline, max(0.5, deadline - time.process_time() - 0.5), rng, kick=0.0)
        if r2 > best_R:
            best_R = r2
            best_h = h2

    print("final best R=%.7f (start %.7f)" % (best_R, start_bestR))

    if best_R > start_bestR + 1e-12:
        return best_h
    if alt_h is not None and alt_R > start_bestR - 1e-6:
        return {"best": start_best, "alternative": alt_h}
    return start_best


def _seed_blocky(rng, N):
    K = int(np.exp(rng.uniform(np.log(3), np.log(40))))
    K = max(2, min(K, N))
    edges = np.sort(rng.choice(np.arange(1, N), size=min(K - 1, N - 1), replace=False))
    edges = np.concatenate(([0], edges, [N]))
    h = np.zeros(N)
    for i in range(len(edges) - 1):
        h[edges[i]:edges[i + 1]] = np.exp(rng.uniform(np.log(1e-2), 0.0))
    return h

