def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolong(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def _smooth_to(h, N, sigma):
    hp = _prolong(h, N)
    if sigma <= 0:
        return hp
    k = int(max(1, round(sigma * 3)))
    x = np.arange(-k, k + 1)
    g = np.exp(-0.5 * (x / sigma) ** 2)
    g /= g.sum()
    pad = k
    ext = np.concatenate((hp[pad - 1::-1], hp, hp[:-pad - 1:-1]))
    sm = np.convolve(ext, g, mode='same')
    out = sm[pad:pad + N]
    return np.maximum(out, 0.0)


def _zero_runs(h, minlen=8):
    z = (h <= 0)
    runs = []
    n = z.size
    i = 0
    while i < n:
        if z[i]:
            j = i
            while j < n and z[j]:
                j += 1
            if j - i >= minlen:
                runs.append((i, j))
            i = j
        else:
            i += 1
    return runs


def _revive(h, a):
    h2 = h.copy()
    runs = _zero_runs(h2, 8)
    if not runs:
        return None
    mx = h2.max()
    if mx <= 0:
        return None
    for (i, j) in runs:
        h2[i:j] = a * mx
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def time_left():
        return time.process_time() < deadline

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = R_of(best)

    alt = None
    altR = -1.0

    if best is None:
        best = np.ones(64)
        bestR = R_of(best)

    def try_accept(cand):
        nonlocal best, bestR
        rc = R_of(cand)
        if rc > bestR:
            bestR = rc
            best = cand.copy()
            return True
        return False

    def consider_alt(cand):
        nonlocal alt, altR
        rc = R_of(cand)
        if rc > altR:
            altR = rc
            alt = cand.copy()

    base = best.copy()
    base_N = base.size
    print(f"start R={bestR:.6f} N={base_N}")

    betas = (0.0, 1e2, 1e3, 1e4, 1e5, 1e6)

    def optimise(hw, tag):
        nonlocal bestR
        for beta in betas:
            if not time_left():
                break
            c = _lbfgs_log(hw, 150, deadline, beta=beta)
            rc = R_of(c)
            if rc > R_of(hw):
