    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, fg=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, fg=fg)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    near = np.mean(Lf >= 0.99 * mx)
    argm = int(np.argmax(Lf)) / max(1, Lf.size - 1)
    return (100.0 * np.mean(h <= 0), h.max() / max(1e-30, h.mean()),
            near, argm)


def _unequal_split(h, rng):
    """Split each cell into two unequal halves, mass-preserving."""
    w = 0.5 + rng.uniform(-0.18, 0.18, size=h.size)
    h2 = np.empty(2 * h.size)
    h2[0::2] = h * (2.0 * w)
    h2[1::2] = h * (2.0 * (1.0 - w))
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (baseR, base.size, 100.0 * np.mean(base <= 0)))

    rng = np.random.default_rng(7)

    # Diagnostic: unequal split, check exact R preserved.
    h = _unequal_split(base, rng)
    h = _rescale(h)
    R = R_of(h)
    print("unequal split R=%.10f (N=%d) delta=%.2e" %
          (R, h.size, R - baseR))

    best = h.copy()
    bestR = R

    def stage(hcur, Rcur, label):
        nonlocal best, bestR
        if Rcur > bestR + 1e-13:
            best = hcur.copy(); bestR = Rcur
        z, mm, nm, am = _stats(hcur)
        print("%s R=%.8f N=%d zeros %.1f%% max/mean %.2f near %.4f argmax %.3f" %
              (label, Rcur, hcur.size, z, mm, nm, am))

    # Main pipeline on the unequal-split construction.
    if time.process_time() < deadline - 6.0:
        h2 = _lbfgs_log(h, 250, min(deadline, time.process_time() + 6.0))
        R2 = R_of(h2)
        if R2 > R:
            h, R = h2, R2
        stage(h, R, "lbfgs")

    for beta in (1e2, 1e3, 1e4):
        if time.process_time() >= deadline - 4.0:
            break
        fg = (lambda hh, _b=beta: _fun_grad_beta(hh, _b))
        hb = _lbfgs_log(h, 150, min(deadline, time.process_time() + 4.0), fg=fg)
        Rb = R_of(hb)
        if Rb > R:
            h, R = hb, Rb
        stage(h, R, "beta%.0e" % beta)

    for frac in (0.06, 0.12, 0.25):
        if time.process_time() >= deadline - 3.0:
            break
        hw = _window_polish_peak(h, min(deadline, time.process_time() + 3.0),
                                 frac, 32, maxiter=150)
        Rw = R_of(hw)
        if Rw > R:
            h, R = hw, Rw
        stage(h, R, "win%.2f" % frac)

    # Final polish.
    if time.process_time() < deadline - 2.0:
        hp = _lbfgs_log(h, 200, min(deadline, time.process_time() + 3.0))
        Rp = R_of(hp)
        if Rp > R:
            h, R = hp, Rp
        stage(h, R, "polish")

    # Plateau: ladder more unequal splits of current best, up to N<=250000.
    it = 0
    while time.process_time() < deadline - 3.0 and best.size < 250000:
        it += 1
        hs = _unequal_split(best, rng)
        hs = _rescale(hs)
        Rs = R_of(hs)
        stage(hs, Rs, "split%d" % it)
        if time.process_time() >= deadline - 3.0:
            break
        hs = _lbfgs_log(hs, 200, min(deadline, time.process_time() + 5.0))
        Rs = R_of(hs)
        if Rs > bestR:
            best = hs.copy(); bestR = Rs
        stage(hs, Rs, "split%d-lb" % it)
        for frac in (0.10, 0.20):
            if time.process_time() >= deadline - 2.0:
                break
            hw = _window_polish_peak(hs, min(deadline, time.process_time() + 3.0),
                                     frac, 32, maxiter=120)
            Rw = R_of(hw)
            if Rw > bestR:
                best = hw.copy(); bestR = Rw
            stage(hw, Rw, "split%d-win%.2f" % (it, frac))

    print("final R=%.8f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _shift_raster(h, delta):
    n = h.size
    k = int(np.floor(delta))
    u = delta - k
    idx = np.arange(n)
    i0 = np.clip(idx + k, 0, n - 1)
    i1 = np.clip(idx + k + 1, 0, n - 1)
    hd = (1.0 - u) * h[i0] + u * h[i1]
    return _rescale(np.clip(hd, 0.0, None))


def _upsample(h, factor):
    """Interpolate heights to a finer grid (factor x)."""
    if factor <= 1:
        return h.copy()
    n = h.size
    m = (n - 1) * factor + 1
    x_old = np.arange(n, dtype=float)
    x_new = np.linspace(0.0, n - 1.0, m)
    return np.clip(np.interp(x_new, x_old, h), 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- New idea: upsample the construction to a finer grid, then polish.
    # A finer grid gives more degrees of freedom to sharpen the peak of f*f and
    # to control the tails, which is where R is lost. The existing program only
    # refines within the same N; changing N explores a genuinely new family.
    for factor in (2, 3, 4):
        if time.process_time() >= deadline - 5.0:
            break
        hu = _upsample(best, factor)
        ru = R_of(hu)
        print("  upsample x%d -> N=%d raw R=%.9f" % (factor, hu.size, ru))
        # Polish on the finer grid.
        cand, candR = hu.copy(), ru
        cap = min(deadline - 3.0, time.process_time() + 8.0)
        hs = _lbfgs_log(cand, 400, cap, beta=0.0)
        rs = R_of(hs)
        if rs > candR:
            cand, candR = hs, rs
        if time.process_time() < deadline - 3.0:
            free = _peak_window(cand, frac=0.10)
            cap = min(deadline - 2.0, time.process_time() + 5.0)
            hs = _lbfgs_block(cand, free, 200, cap, beta=0.0)
            rs = R_of(hs)
            if rs > candR:
                cand, candR = hs, rs
        for beta in (1e3, 1e4, 1e5):
            if time.process_time() >= deadline - 2.0:
                break
            cap = min(deadline - 1.0, time.process_time() + 4.0)
            hs = _lbfgs_log(cand, 200, cap, beta=beta)
            rs = R_of(hs)
            if rs > candR:
                cand, candR = hs, rs
        print("  upsample x%d polished R=%.9f" % (factor, candR))
        if candR > bestRH + 1e-13:
            bestH, bestRH = cand.copy(), candR
            print("    NEW BEST R=%.9f (upsample x%d)" % (bestRH, factor))
            # Keep refining the winning finer grid if time allows.
            break

    # ---- Phase-shift rasterisation experiment on the (possibly finer) best.
    if time.process_time() < deadline - 6.0:
        for delta in (-0.5, -0.25, 0.25, 0.5):
            if time.process_time() >= deadline - 4.0:
                break
            hd = _shift_raster(bestH, delta)
            r_raw = R_of(hd)
            cand, candR = hd, r_raw
            cap = min(deadline - 2.0, time.process_time() + 3.0)
            hs = _lbfgs_log(cand, 200, cap, beta=0.0)
            rs = R_of(hs)
            if rs > candR:
                cand, candR = hs, rs
            if time.process_time() < deadline - 2.0:
                free = _peak_window(cand, frac=0.10)
                cap = min(deadline - 1.5, time.process_time() + 2.0)
                hs = _lbfgs_block(cand, free, 150, cap, beta=0.0)
                rs = R_of(hs)
                if rs > candR:
                    cand, candR = hs, rs
            if time.process_time() < deadline - 1.5:
                cap = min(deadline - 1.0, time.process_time() + 2.0)
                hs = _lbfgs_log(cand, 150, cap, beta=1e4)
                rs = R_of(hs)
                if rs > candR:
                    cand, candR = hs, rs
            print("  delta=%+.2f polished R=%.9f" % (delta, candR))
            if candR > bestRH + 1e-13:
                bestH, bestRH = cand.copy(), candR
                print("    NEW BEST R=%.9f (delta=%+.2f)" % (bestRH, delta))

    # ---- Final full polish loop.
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            free = _peak_window(bestH, frac=0.10)
            cap = min(loop_end, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": start_best}
    return {"best": start_best, "alternative": bestH}

