    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, fg=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, fg=fg)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    near = np.mean(Lf >= 0.99 * mx)
    argm = int(np.argmax(Lf)) / max(1, Lf.size - 1)
    return (100.0 * np.mean(h <= 0), h.max() / max(1e-30, h.mean()),
            near, argm)


def _env(h, theta1, theta2):
    n = h.size
    u = (np.arange(n) + 0.5) / n
    x = 2.0 * u - 1.0
    e = np.exp(theta1 * x + theta2 * (x * x - 1.0 / 3.0))
    return _rescale(h * e)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (baseR, base.size, 100.0 * np.mean(base <= 0)))

    best = base.copy()
    bestR = baseR

    def stage(hcur, Rcur, label):
        nonlocal best, bestR
        if Rcur > bestR + 1e-13:
            best = hcur.copy(); bestR = Rcur
        z, mm, nm, am = _stats(hcur)
        print("%s R=%.8f N=%d zeros %.1f%% max/mean %.2f near %.4f argmax %.3f" %
              (label, Rcur, hcur.size, z, mm, nm, am))

    # Stage A: 1-D scan of theta1
    thetas = np.linspace(-0.6, 0.6, 13)
    scan = []
    a_deadline = min(deadline, time.process_time() + 3.0)
    best_t1, best_Ra = 0.0, baseR
    best_ha = base.copy()
    for t1 in thetas:
        if time.process_time() > a_deadline:
            break
        ha = _env(base, t1, 0.0)
        Ra = R_of(ha)
        scan.append((t1, Ra))
        if Ra > best_Ra:
            best_Ra, best_t1, best_ha = Ra, t1, ha
    print("scan theta1: " + " ".join("%.2f:%.7f" % (t, r) for t, r in scan))
    print("scan best theta1=%.3f R=%.8f (gain %.2e)" %
          (best_t1, best_Ra, best_Ra - baseR))

    # Stage B: Nelder-Mead on (theta1, theta2)
    b_deadline = min(deadline, time.process_time() + 8.0)
    evals = [0]

    def obj(x):
        evals[0] += 1
        if time.process_time() > b_deadline:
            raise TimeoutError
        return -R_of(_env(base, x[0], x[1]))

    x0 = np.array([best_t1, 0.0])
    try:
        res = minimize(obj, x0, method='Nelder-Mead',
                       options={'maxfev': 80, 'xatol': 1e-4, 'fatol': 1e-9})
        th1, th2 = res.x
    except (TimeoutError, Exception):
        th1, th2 = best_t1, 0.0
    h_env_best = _env(base, th1, th2)
    R_env = R_of(h_env_best)
    print("env final theta1=%.4f theta2=%.4f R=%.8f (gain %.2e, evals %d)" %
          (th1, th2, R_env, R_env - baseR, evals[0]))

    if R_env > bestR:
        best = h_env_best.copy(); bestR = R_env
    stage(best, bestR, "env")

    # Stage C: standard exact pipeline
    h = best.copy()
    R = bestR

    if time.process_time() < deadline - 6.0:
        h2 = _lbfgs_log(h, 200, min(deadline, time.process_time() + 6.0))
        R2 = R_of(h2)
        if R2 > R:
            h, R = h2, R2
        stage(h, R, "lbfgs")

    for beta in (1e3, 1e4):
        if time.process_time() >= deadline - 4.0:
            break
        fg = (lambda hh, _b=beta: _fun_grad_beta(hh, _b))
        hb = _lbfgs_log(h, 60, min(deadline, time.process_time() + 3.0), fg=fg)
        Rb = R_of(hb)
        if Rb > R:
            h, R = hb, Rb
        stage(h, R, "beta%.0e" % beta)

    for frac in (0.08, 0.15):
        if time.process_time() >= deadline - 3.0:
            break
        hw = _window_polish_peak(h, min(deadline, time.process_time() + 3.0),
                                 frac, 32, maxiter=120)
        Rw = R_of(hw)
        if Rw > R:
            h, R = hw, Rw
        stage(h, R, "win%.2f" % frac)

    # Alternate exact log-L-BFGS while time remains
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        hp = _lbfgs_log(h, 200, min(deadline, time.process_time() + 3.0))
        Rp = R_of(hp)
        if Rp > R:
            h, R = hp, Rp
        stage(h, R, "polish%d" % it)
        if time.process_time() >= deadline - 2.0:
            break
        for frac in (0.08, 0.15):
            if time.process_time() >= deadline - 1.5:
                break
            hw = _window_polish_peak(h, min(deadline, time.process_time() + 2.0),
                                     frac, 32, maxiter=100)
            Rw = R_of(hw)
            if Rw > R:
                h, R = hw, Rw
            stage(h, R, "pol%d-win%.2f" % (it, frac))

    print("final R=%.8f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _random_start(Nc, rng):
    k = rng.integers(3, 7)
    knots = np.sort(rng.uniform(0.0, 1.0, size=k))
    knots = np.concatenate(([0.0], knots, [1.0]))
    amps = rng.uniform(-1.0, 1.0, size=knots.size)
    amps = np.cumsum(amps) * 0.7
    x = np.linspace(0.0, 1.0, Nc)
    env = np.exp(np.interp(x, knots, amps))
    pzero = rng.choice([0.1, 0.3, 0.5])
    mask = (rng.random(Nc) > pzero).astype(float)
    h = env * mask
    if h.sum() <= 0:
        h = env.copy()
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    rng = np.random.default_rng(98765)
    alternative = None
    altR = 0.0

    # Build a fresh multi-scale construction in parallel (for "alternative").
    N_c = 512
    coarse_best = None
    coarse_bestR = 0.0
    ms_deadline = t0 + budget_seconds * 0.55
    n_starts = 12
    for i in range(n_starts):
        if time.process_time() >= ms_deadline - 0.5:
            break
        h0 = _rescale(_random_start(N_c, rng))
        slice_deadline = min(ms_deadline, time.process_time() + 2.5)
        h1 = _lbfgs_log(h0, 400, slice_deadline)
        r = R_of(h1)
        if r > coarse_bestR:
            coarse_bestR = r
            coarse_best = h1

    if coarse_best is not None:
        hp = _rescale(_prolongate(coarse_best, 16384))
        hp = _lbfgs_log(hp, 400, deadline)
        if time.process_time() < deadline - 6.0:
            hp2 = _rescale(_prolongate(hp, N))
            hp2 = _lbfgs_log(hp2, 400, deadline)
            for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32)):
                if time.process_time() >= deadline - 4.0:
                    break
                hp2 = _window_polish_peak(hp2, deadline, frac, extra)
                hp2 = _lbfgs_log(hp2, 300, deadline)
            r2 = R_of(hp2)
            if r2 > R_of(hp):
                hp = hp2
        alternative = hp
        altR = R_of(hp)
        print("alt R=%.7f" % altR)

    # Polish the start (or best-of) with progressively wider peak windows
    # using the smoothed-max (beta) objective to escape the max-knot kink.
    for beta in (0.0, 200.0, 50.0, 0.0):
        for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
            if time.process_time() >= deadline - 2.0:
                break
            h = _window_polish_peak(best, deadline, frac, extra, beta=beta)
            h = _lbfgs_log(h, 500, deadline, beta=beta)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                print("peak(b=%.0f,%.2f) R=%.7f" % (beta, frac, bestR))
        if time.process_time() >= deadline - 2.0:
            break

    # Phase exploration
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _rescale(_phase_shift(best, delta))
        if hp.sum() <= 0:
            continue
        hp = _lbfgs_log(hp, 600, deadline)
        hp = _window_polish_peak(hp, deadline, 0.35, 16)
        r = R_of(hp)
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("phase %+.2f R=%.7f" % (delta, bestR))
        if r > altR + 1e-15:
            alternative, altR = hp, r

    # Final polish loop
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24, beta=20.0)
        h = _lbfgs_log(h, 400, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alternative is not None and altR > bestR + 1e-15:
        return {"best": best, "alternative": alternative}
    if alternative is not None and abs(altR - bestR) <= 1e-12 and not np.array_equal(alternative, best):
        return {"best": best, "alternative": alternative}
    if alternative is not None and altR < bestR:
        return {"best": best, "alternative": alternative}
    return best

