def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _prune_pedestal(h, q, mode):
    """Zero the smallest q fraction of nonzero cells; redistribute their mass
    as a pedestal (mode 0: uniform all; 1: middle 50%; 2: proportional to h
    among top 20%)."""
    h = np.clip(h, 0, None).copy()
    n = h.size
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    k = int(round(q * nz.size))
    if k <= 0:
        return h
    order = nz[np.argsort(h[nz])]
    kill = order[:k]
    M = h[kill].sum()
    h[kill] = 0.0
    if M <= 0:
        return h
    if mode == 0:
        h += M / n
    elif mode == 1:
        lo = n // 4
        hi = n - n // 4
        width = max(1, hi - lo)
        h[lo:hi] += M / width
    else:  # mode 2: proportional among top 20% of cells
        top = order[int(0.8 * nz.size):]
        if top.size == 0:
            h += M / n
        else:
            w = h[top]
            sw = w.sum()
            if sw <= 0:
                h[top] += M / top.size
            else:
                h[top] += M * w / sw
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
