    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _gauss_smooth(h, sigma):
    if sigma <= 0.5:
        return h.copy()
    r = int(3 * sigma) + 1
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def _smooth_perturb(h, sigma, amp, seed):
    n = h.size
    rng = np.random.RandomState(seed)
    m = max(16, n // 64)
    noise = rng.randn(m)
    xp = np.linspace(0, 1, m)
    xi = np.linspace(0, 1, n)
    p = np.interp(xi, xp, noise)
    return np.clip(h * np.exp(amp * p), 0, None)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size
    alt = None
    altR = 0.0

    def anneal_polish(h0, deadline, betas, iters):
        h = h0
        for beta in betas:
            if time.process_time() >= deadline - 1.0:
                break
            h = _lbfgs_log(h, iters, deadline, beta=beta)
            h = _window_polish_peak(h, deadline, 0.35, 16, maxiter=iters, beta=beta)
        return h

    betas = [2.0, 8.0, 32.0, 128.0, 512.0, 2048.0]

    if time.process_time() < deadline - 20.0:
        h = anneal_polish(best, deadline - 15.0, betas, 250)
        h = _lbfgs_log(h, 400, deadline)
        h = _window_polish_peak(h, deadline, 0.40, 24)
        r = R_of(h)
        print("anneal R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("anneal wins R=%.7f" % bestR)
        elif r > altR:
            alt, altR = h, r

    perturb_specs = [
        (max(2.0, N / 300.0), 0.05, 11),
        (max(4.0, N / 150.0), 0.06, 12),
        (max(8.0, N / 80.0), 0.05, 13),
    ]
    for sigma, amp, seed in perturb_specs:
        if time.process_time() >= deadline - 10.0:
            break
        hp = _rescale(_smooth_perturb(best, sigma, amp, seed))
        hp = anneal_polish(hp, deadline - 5.0, betas[:4], 200)
        hp = _lbfgs_log(hp, 400, deadline)
        hp = _window_polish_peak(hp, deadline, 0.35, 16)
        r = R_of(hp)
        print("perturb s=%.1f a=%.2f R=%.7f" % (sigma, amp, r))
        if r > altR:
            alt, altR = hp, r
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("perturb wins R=%.7f" % bestR)

    if time.process_time() < deadline - 8.0:
        for factor in (4, 2):
            if time.process_time() >= deadline - 6.0:
                break
            Nc = max(256, N // factor)
            hc = _rescale(_gauss_smooth(_coarse(best, Nc), sigma=max(1.0, Nc / 400.0)))
            hc = anneal_polish(hc, deadline - 4.0, betas[:3], 200)
            hc = _lbfgs_log(hc, 400, deadline)
            hp = _rescale(_prolongate(hc, N))
            hp = _lbfgs_log(hp, 400, deadline)
            hp = _window_polish_peak(hp, deadline, 0.40, 24)
            r = R_of(hp)
            print("prolong %d->%d R=%.7f" % (Nc, N, r))
            if r > altR:
                alt, altR = hp, r
            if r > bestR + 1e-15:
                best, bestR = hp, r

    # NEW: phase-shift jitter + single-knot peak lifting.
    # The exact ||inf|| ties are near a plateau; nudging the argmax knot up
    # by a tiny amount (and letting L-BFGS rebalance) can re-seat the peak
    # at a better configuration, breaking the plateau symmetry.
    def peak_lift(h, delta_frac, deadline):
        h = h.copy()
        Lf = _knots(h)
        m = int(np.argmax(Lf))
        # lift the h index that most affects knot m: roughly h[m] and h[m-1]
        for idx in (m, m - 1):
            if 0 <= idx < h.size and h[idx] > 0:
                h[idx] *= (1.0 + delta_frac)
        return _rescale(h)

    for delta in (0.02, 0.005, -0.01):
        if time.process_time() >= deadline - 3.0:
            break
        hl = peak_lift(best, delta, deadline)
        hl = _lbfgs_log(hl, 400, deadline)
        hl = _window_polish_peak(hl, deadline, 0.30, 16)
        r = R_of(hl)
        print("lift d=%.3f R=%.7f" % (delta, r))
        if r > altR:
            alt, altR = hl, r
        if r > bestR + 1e-15:
            best, bestR = hl, r
            print("lift wins R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, beta):
    """Soft-max surrogate of the inf norm, smooth in the peak region."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_soft(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_soft(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _plateau_window(h, rel=0.05):
    """Indices of knots within rel of maximum, and corresponding h support."""
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= (1.0 - rel) * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx[0] - 1)
    hi = min(h.size, idx[-1] + 1)
    return np.arange(lo, hi)


def _coarsen(h, k=2):
    n = h.size
    if n % k:
        h = np.concatenate((h, np.zeros(k - n % k)))
        n = h.size
    return h.reshape(-1, k).mean(axis=1)


def _refine(h, k=2):
    """Upsample by linear interpolation on cumulative mass (mass-preserving)."""
    n = h.size
    m = n * k
    xo = (np.arange(n) + 0.5) / n
    xn = (np.arange(m) + 0.5) / m
    # integrate then interpolate the cumulative to preserve mass
    c = np.concatenate(([0.0], np.cumsum(h)))
    ci = np.interp(xn, np.concatenate(([0.0], xo, [1.0])), c)
    # derivative gives new heights (times m)
    hn = np.diff(ci) * m
    return np.clip(hn, 0, None)


def _polish(h, deadline, iters=300):
    best = h.copy()
    bestR = R_of(best)
    while time.process_time() < deadline:
        cap = min(deadline, time.process_time() + 4.0)
        hs = _lbfgs_log(best, iters, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-13:
            best, bestR = hs, rs
            continue
        if time.process_time() < deadline - 1.0:
            free = _peak_window(best, frac=0.05)
            cap = min(deadline, time.process_time() + 3.0)
            hp = _lbfgs_block(best, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
            else:
                break
        else:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            r = _rescale(base)
            baseR = R_of(r)
        else:
            r, baseR = None, 0.0
    else:
        r, baseR = None, 0.0

    if r is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        r = _rescale(h)
        baseR = R_of(r)

    start_best = r.copy()
    start_bestR = baseR
    mx0, m0, near0 = _stats(r)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, r.size, 100.0 * np.mean(r <= 0), mx0, m0, near0))

    # --- New idea: plateau-focused polishing on the active knot region,
    #     with a soft-max surrogate and coarsen/refine multiscale moves.
    incumbent = start_best.copy()
    incR = start_bestR
    alt = start_best.copy()
    altR = start_bestR

    # First: plateau window block polish (targeted at the flat top)
    if time.process_time() < deadline - 2.0:
        free = _plateau_window(incumbent, rel=0.05)
        cap = min(deadline, time.process_time() + 5.0)
        hp = _lbfgs_block(incumbent, free, 200, cap, beta=0.0)
        rp = R_of(hp)
        if rp > incR + 1e-13:
            incumbent, incR = hp, rp
            print("  plateau polish R=%.9f (dR=%+.2e)" % (incR, incR - baseR))

    # Multiscale: coarsen then polish then refine
    if time.process_time() < deadline - 5.0:
        hc = _coarsen(incumbent, 2)
        rc = R_of(hc)
        cap = min(deadline, time.process_time() + 4.0)
        hc = _lbfgs_log(hc, 200, cap, beta=0.0)
        rc = R_of(hc)
        hr = _refine(hc, 2)
        if hr.size != incumbent.size:
            hr = hr[:incumbent.size] if hr.size > incumbent.size else np.concatenate(
                (hr, np.zeros(incumbent.size - hr.size)))
        hr = _rescale(hr)
        rr = R_of(hr)
        print("  coarsen/refine R=%.9f (dR=%+.2e)" % (rr, rr - baseR))
        if rr > altR + 1e-13:
            alt, altR = hr, rr

    # Soft-max polish with increasing beta to sharpen the peak
    for beta in (10.0, 100.0, 1000.0):
        if time.process_time() >= deadline - 2.0:
            break
        cap = min(deadline, time.process_time() + 2.5)
        hs = _lbfgs_log(incumbent, 150, cap, beta=beta)
        rs = R_of(hs)
        if rs > incR + 1e-13:
            incumbent, incR = hs, rs
            print("  softmax beta=%.0f R=%.9f" % (beta, incR))

    # Final standard polish until deadline
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        hp, rp = _polish(incumbent, loop_end, iters=300)
        if rp > incR + 1e-13:
            incumbent, incR = hp, rp
            print("  iter=%d polish R=%.9f" % (it, incR))
        else:
            break

    mx, m, near = _stats(incumbent)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (incR, incumbent.size, 100.0 * np.mean(incumbent <= 0), mx, m, near))

    if incR > start_bestR + 1e-12:
        return {"best": incumbent, "alternative": alt if altR > start_bestR + 1e-12 else start_best}
    else:
        return {"best": start_best, "alternative": alt}

