        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    print("base R=%.9f (N=%d)" % (baseR, baseH.size))

    # Fine array: exact duplication for a better-resolved starting point
    h2 = _rescale(np.repeat(baseH, 2))
    r2 = R_of(h2)
    bestH, bestR = h2.copy(), r2
    print("fine init N=%d R=%.9f" % (h2.size, r2))

    # Global passes first
    for _ in range(3):
        if time.process_time() >= deadline - 3.0:
            break
        cap = min(deadline - 2.0, time.process_time() + 8.0)
        hs = _lbfgs_log(bestH, 300, cap)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            print("  global -> R=%.9f" % bestR)

    # Alternate global / peak-window until deadline
    it = 0
    loop_end = deadline - 3.0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 200, cap)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            print("  iter=%d global R=%.9f" % (it, bestR))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.03 + 0.07 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 150, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                print("  iter=%d peak frac=%.2f R=%.9f" % (it, frac, bestR))

    # Final short polish
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.0)
        hs = _lbfgs_log(bestH, 150, cap)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    # Try a coarsened version (same shape at half resolution, then re-polish)
    hc = _coarsen(bestH)
    rc = R_of(hc)
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.0)
        hcp = _lbfgs_log(hc, 100, cap)
        rcp = R_of(hcp)
        if rcp > rc:
            hc, rc = hcp, rcp
    print("fine R=%.9f coarsened R=%.9f" % (bestR, rc))

    mx, m, near = _stats(bestH)
    print("final N=%d Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestH.size, mx, m, near))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        return {"best": baseH, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample(h, factor=2):
    n = h.size
    i = np.arange(n, dtype=float)
    xi = (np.arange(n * factor) + 0.5) / factor - 0.5
    return np.interp(xi, i, h, left=0.0, right=0.0).clip(0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase 1: refine at current resolution with full log L-BFGS + peak windows
    cyc = 0
    while time.process_time() < deadline - 2.5:
        cyc += 1
        improved = False
        if time.process_time() < deadline - 2.0:
            cap = min(deadline - 0.5, time.process_time() + 3.0)
            hp = _lbfgs_log(best, 300, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
                improved = True
        for frac in (0.02, 0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 2.0:
                break
            free = _peak_window(best, frac=frac)
            cap = min(deadline - 0.5, time.process_time() + 1.5)
            hb = _lbfgs_block(best, free, 100, cap)
            rb = R_of(hb)
            if rb > bestR + 1e-14:
                best, bestR = hb, rb
                improved = True
        if not improved:
            break
    print("phase1 R=%.9f (N=%d)" % (bestR, best.size))

    # Phase 2: try upsampling to a finer grid and re-optimising
    while time.process_time() < deadline - 2.0:
        n = best.size
        if n >= 400000:
            break
        factor = 2 if n < 100000 else 2
        hu = _upsample(best, factor)
        hu = _rescale(hu)
        ru = R_of(hu)
        # short polish
        cap = min(deadline - 0.5, time.process_time() + 5.0)
        hu2 = _lbfgs_log(hu, 200, cap)
        ru2 = R_of(hu2)
        if ru2 > ru:
            hu, ru = hu2, ru2
        for frac in (0.02, 0.05, 0.10):
            if time.process_time() >= deadline - 1.0:
                break
            free = _peak_window(hu, frac=frac)
            cap = min(deadline - 0.5, time.process_time() + 2.0)
            hb = _lbfgs_block(hu, free, 100, cap)
            rb = R_of(hb)
            if rb > ru:
                hu, ru = hb, rb
        print("upsample x%d -> R=%.9f (N=%d)" % (factor, ru, hu.size))
        if ru > bestR + 1e-14:
            best, bestR = hu, ru
        else:
            break

    # Final polish on best
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.2, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _double(h):
    n = len(h)
    out = np.empty(2 * n)
    out[0::2] = h
    out[1::2] = h
    return out


def _polish(h, deadline, time_cap):
    """Peak-window block polish at several fracs + full sharp pass."""
    best = h
    best_R = R_of(h)
    for frac in (0.02, 0.05, 0.10, 0.20):
        if time.process_time() > deadline - 1.0:
            break
        cap = min(deadline - 0.5, time.process_time() + time_cap)
        free = _peak_window(best, frac=frac)
        h2 = _lbfgs_block(best, free, 200, cap)
        r = R_of(h2)
        if r > best_R:
            best_R = r; best = h2
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + time_cap)
        h2 = _lbfgs_log(best, 300, cap)
        r = R_of(h2)
        if r > best_R:
            best_R = r; best = h2
    return best, best_R


def _homotopy(h, deadline, betas, per_beta_time):
    """Run beta-homotopy cycles. Returns (h, R)."""
    best = h
    best_R = R_of(h)
    for beta in betas:
        if time.process_time() > deadline - 2.0:
            break
        cap = min(deadline - 1.0, time.process_time() + per_beta_time)
        h2 = _lbfgs_log(best, 200, cap, beta=beta)
        r = R_of(h2)
        print("  N=%d beta=%.0e R=%.7f" % (len(h2), beta, r))
        if r > best_R:
            best_R = r; best = h2
    return best, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 4.0

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
    else:
        best = np.ones(16384)
    best_R = R_of(best)
    print("start R=%.7f N=%d" % (best_R, len(best)))

    betas = (1e2, 1e3, 1e4, 1e5, 1e6, 1e7)

    # Track best (N, R) pair across levels
    best_level = (best.copy(), best_R)

    # Stage A: homotopy + polish at current N
    if time.process_time() < deadline - 8:
        cap = min(deadline - 6, time.process_time() + 6.0)
        h = _lbfgs_log(best, 400, cap)
        r = R_of(h)
        print("sharp R=%.7f" % r)
        if r > best_R:
            best_R = r; best = h

    if time.process_time() < deadline - 6:
        h, r = _homotopy(best, deadline - 4, betas, 2.0)
        if r > best_R:
            best_R = r; best = h

    if time.process_time() < deadline - 4:
        h, r = _polish(best, deadline - 2, 2.0)
        if r > best_R:
            best_R = r; best = h
    print("level N=%d R=%.7f" % (len(best), best_R))
    if best_R > best_level[1]:
        best_level = (best.copy(), best_R)

    # Stage B: prolongation with continued homotopy
    level_R = best_R
    for target_N in (131072, 262144, 524288):
        if time.process_time() > deadline - 8:
            break
        if len(best) < target_N:
            while len(best) < target_N:
                best = _double(best)
            r = R_of(best)
            print("doubled N=%d R=%.7f" % (len(best), r))
            if r > best_R:
                best_R = r
        # homotopy at new N
        if time.process_time() < deadline - 6:
            h, r = _homotopy(best, deadline - 4, betas, 2.0)
            if r > best_R:
                best_R = r; best = h
        if time.process_time() < deadline - 4:
            h, r = _polish(best, deadline - 2, 2.0)
            if r > best_R:
                best_R = r; best = h
        print("level N=%d R=%.7f" % (len(best), best_R))
        gain = best_R - level_R
        if best_R > best_level[1]:
            best_level = (best.copy(), best_R)
        level_R = best_R
        if gain < 1e-5:
            print("plateau at N=%d (gain %.2e)" % (len(best), gain))
            break

    # Final long sharp pass + polish at best level
    best, best_R = best_level
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 6.0)
        h = _lbfgs_log(best, 800, cap)
        r = R_of(h)
        print("final sharp N=%d R=%.7f" % (len(h), r))
        if r > best_R:
            best_R = r; best = h
    if time.process_time() < deadline - 1.0:
        h, r = _polish(best, deadline - 0.5, 2.0)
        if r > best_R:
            best_R = r; best = h

    print("best R = %.7f, N = %d" % (best_R, len(best)))

    result = {"best": best}
    if start is not None:
        s = np.asarray(start, dtype=float)
        if R_of(s) >= best_R:
            result["best"] = s
            result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c=0.95, beta=1e3):
    """Q-surrogate: penalise knots above c*Lmax softly, still optimise R."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    # soft-max surrogate for L_inf
    thr = c * Lm
    over = Lf > thr
    # gradient of R via log form
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    # add soft penalty pulling knots above thr down
    if np.any(over):
        excess = Lf[over] - thr
        gLf[over] += beta * excess / (Lm * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    if np.any(over):
        val += 0.5 * beta * np.sum((Lf[over] - thr) ** 2) / (Lm * Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _argmax_pos(h):
    Lf = _knots(h)
    return int(np.argmax(Lf)) / max(1, Lf.size - 1)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h.copy()
    bestR = R_of(best)
    for frac in fracs:
        if time.process_time() >= deadline - 0.4:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline, time.process_time() + 1.5)
        hp = _lbfgs_block(best, free, 120, cap)
        r = R_of(hp)
        if r > bestR:
            best, bestR = hp, r
    return best, bestR


# ---- Restriction / prolongation (area-averaging, mass-preserving) ----

def _restrict(h, k):
    """Area-average h into ceil(N/k) cells; each coarse cell has k fine cells
    of equal width, so area-average = mean of the k fine heights."""
    n = h.size
    m = (n + k - 1) // k
    out = np.empty(m)
    for i in range(m):
        lo = i * k
        hi = min(lo + k, n)
        out[i] = h[lo:hi].mean()
    return out


def _prolong(hc, k, n_full):
    """Repeat each coarse value k times (mass-preserving piecewise-constant)."""
    out = np.repeat(hc, k)
    if out.size >= n_full:
        return _rescale(out[:n_full])
    pad = n_full - out.size
    return _rescale(np.concatenate((out, np.full(pad, out[-1]))))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        best = base.copy()
        bestR = R_of(best)
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    def try_new(name, cand):
        nonlocal best, bestR
        if cand is None:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f N=%d argmax=%.4f" %
                  (name, bestR, best.size, _argmax_pos(best)))
            return True
        return False

    loop_end = deadline - 0.5
    n_full = best.size

    # ---- Coarse restriction / optimize / prolongation ladder ----
    cycle = 0
    while time.process_time() < loop_end - 4.0:
        cycle += 1
        improved_this_cycle = False
        for k in (2, 3, 4, 5, 7):
            if time.process_time() >= loop_end - 4.0:
                break
            hc = _restrict(best, k)
            if hc.size < 8:
                continue
            # coarse optimize with exact-R gradient
            cap = min(loop_end, time.process_time() + 3.0)
            hc = _lbfgs_log(hc, 150, cap, _fun_grad)
            r_after_coarse = R_of(hc)
            # Q-surrogate passes
            for beta in (1e3, 1e5):
                if time.process_time() >= loop_end - 4.0:
                    break
                cap = min(loop_end, time.process_time() + 1.5)
                hq = _lbfgs_log(hc, 120, cap,
                                lambda hh, b=beta: _fun_grad_Q(hh, c=0.95, beta=b))
                if R_of(hq) > R_of(hc):
                    hc = hq
            # prolong back to full resolution
            hp = _prolong(hc, k, n_full)
            cap = min(loop_end, time.process_time() + 2.5)
            hp, rp = _polish(hp, cap, fracs=(0.02, 0.05, 0.10, 0.20))
            print("  k=%d c=%d R_coarse=%.9f R_prolong=%.9f" %
                  (k, cycle, r_after_coarse, rp))
            if rp > bestR + 1e-14:
                if try_new("k=%d c=%d" % (k, cycle), hp):
                    improved_this_cycle = True
        if not improved_this_cycle:
            # squeeze full-resolution
            if time.process_time() < loop_end - 2.0:
                cap = min(loop_end, time.process_time() + 3.0)
                hf = _lbfgs_log(best, 250, cap)
                try_new("full c=%d" % cycle, hf)

    # ---- Final long polish ----
    if time.process_time() < loop_end:
        cap = min(loop_end, time.process_time() + 6.0)
        hf = _lbfgs_log(best, 600, cap)
        try_new("final lbfgs", hf)
    if time.process_time() < loop_end:
        hp, rp = _polish(best, loop_end, fracs=(0.02, 0.05, 0.10, 0.20))
        try_new("final polish", hp)

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
