        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * 0.15))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


def _tallest_peaks(h, k=32):
    n = h.size
    if n < 3:
        return np.array([], dtype=int)
    left = np.concatenate(([-1.0], h[:-1]))
    right = np.concatenate((h[1:], [-1.0]))
    is_peak = (h >= left) & (h >= right) & (h > 0)
    idx = np.flatnonzero(is_peak)
    if idx.size == 0:
        idx = np.argsort(h)[::-1][:k]
        return idx.astype(int)
    order = idx[np.argsort(h[idx])[::-1]]
    return order[:k].astype(int)


def _upsample(h, factor):
    """Linear-interpolation upsample of step heights; consistent with continuous f."""
    n = h.size
    if factor <= 1:
        return h.copy()
    N = n * factor
    # treat h as samples of a function on [0,n]; new samples on refined grid
    x_old = np.arange(n, dtype=float)
    x_new = np.arange(N, dtype=float) / factor
    return np.interp(x_new, x_old, h, left=h[0], right=h[-1])


def _refine(seed, seedR, deadline):
    """Try upsampling the current construction by factors and re-optimising."""
    best = seed
    bestR = seedR
    for factor in (2, 3):
        if time.process_time() >= deadline - 2.0:
            break
        if seed.size * factor > 900000:
            break
        hs = _upsample(seed, factor)
        hs = _rescale(hs)
        cap = min(deadline - 1.0, time.process_time() + 6.0)
        hs = _lbfgs_log(hs, 300, cap)
        rs = R_of(hs)
        if rs > bestR + 1e-12:
            best, bestR = hs, rs
        cap2 = min(deadline - 0.5, time.process_time() + 4.0)
        hs, rs = _peak_polish(hs, rs, 200, cap2)
        if rs > bestR + 1e-12:
            best, bestR = hs, rs
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Phase 0: refinement (upsample) -- new idea ----
    refine_end = t0 + budget_seconds * 0.35
    bestH, bestRH = _refine(bestH, bestRH, refine_end)
    print("refine R=%.7f (N=%d)" % (bestRH, bestH.size))

    # ---- Phase 1: p-norm homotopy ladder on refined grid ----
    ladder = (4, 8, 16, 32, 64, 128)
    loop_end = t0 + budget_seconds * 0.80
    roundN = 0

    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 4.0:
        roundN += 1
        for p in ladder:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 4.0:
                break
            sub_deadline = min(loop_end, time.process_time() + 8.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(bestH, 200, sub_deadline, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  R%d p=%d R=%.7f" % (roundN, p, bestRH))

            if p % 32 == 0:
                if time.process_time() >= loop_end - 1.0:
                    break
                sub2 = min(loop_end, time.process_time() + 6.0)
                hs = _lbfgs_log(bestH, 150, sub2)
                rs = R_of(hs)
                if rs > bestRH + 1e-13:
                    bestH, bestRH = hs.copy(), rs
                print("  R%d sharp R=%.7f" % (roundN, bestRH))
                bestH, bestRH = _peak_polish(bestH, bestRH, 150, sub2)
                print("  R%d peak R=%.7f" % (roundN, bestRH))

    # ---- Phase 2: second refinement pass on improved shape ----
    refine2_end = min(t0 + budget_seconds * 0.92, deadline - 3.0)
    if time.process_time() < refine2_end - 3.0:
        bestH, bestRH = _refine(bestH, bestRH, refine2_end)
        print("refine2 R=%.7f (N=%d)" % (bestRH, bestH.size))

    # ---- Final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        bestH, bestRH = _peak_polish(bestH, bestRH, 200, deadline - 0.3)
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)

def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))

def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den

def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf

def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]

def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)

def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad

def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad

def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb

def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)

def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)

def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)

def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    return mx, m


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    hard = t0 + budget_seconds * 0.96

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
        else:
            base = None
    else:
        base = None

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)

    best = base.copy()
    bestR = R_of(best)
    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d" % (bestR, best.size))

    # Main strategy: aggressively polish with mixed gradient methods.
    # First a full log-space L-BFGS pass.
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 20.0)
        hf = _lbfgs_log(best, 500, cap, beta=0.0)
        rf = R_of(hf)
        print("full log -> %.9f" % rf)
        if rf > bestR:
            best, bestR = hf, rf

    # Beta ladder to push the peak flat (helps ||f*f||_inf term).
    beta = 1e1
    while time.process_time() < deadline - 1.0 and beta <= 1e6:
        cap = min(deadline - 0.5, time.process_time() + 8.0)
        hb = _lbfgs_log(best, 200, cap, beta=beta)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
            print("beta=%.0e -> %.9f" % (beta, rb))
        beta *= 3.0

    # Peak-window polish at multiple scales.
    for frac in (0.03, 0.06, 0.10, 0.15, 0.25):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.5, time.process_time() + 6.0)
        hp = _lbfgs_block(best, free, 200, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
            print("peak frac=%.2f -> %.9f" % (frac, rp))

    # Repeated cycles of full polish + beta + peak-window to squeeze further.
    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        prev = bestR
        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 0.5, time.process_time() + 5.0)
            hf = _lbfgs_log(best, 200, cap, beta=0.0)
            rf = R_of(hf)
            if rf > bestR:
                best, bestR = hf, rf
        for b in (1e2, 1e3, 1e4, 1e5):
            if time.process_time() >= deadline - 1.0:
                break
            cap = min(deadline - 0.5, time.process_time() + 3.0)
            hb = _lbfgs_log(best, 120, cap, beta=b)
            rb = R_of(hb)
            if rb > bestR:
                best, bestR = hb, rb
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.0:
                break
            free = _peak_window(best, frac=frac)
            cap = min(deadline - 0.5, time.process_time() + 3.0)
            hp = _lbfgs_block(best, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR:
                best, bestR = hp, rp
        if bestR <= prev + 1e-12:
            break
        print("cycle %d -> %.9f" % (cycle, bestR))

    # Final hard polish.
    if time.process_time() < hard - 1.0:
        cap = min(hard - 0.5, time.process_time() + 2.0)
        hf = _lbfgs_log(best, 100, cap, beta=0.0)
        rf = R_of(hf)
        if rf > bestR:
            best, bestR = hf, rf

    print("final R=%.9f N=%d" % (bestR, best.size))
    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
