import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _smooth_perturb(h, rng, sigma):
    n = h.size
    k = max(3, n // 40)
    noise = rng.normal(0.0, 1.0, n)
    kern = np.ones(k) / k
    sm = np.convolve(noise, kern, mode='same')
    h2 = h * np.exp(sigma * sm)
    return _rescale(np.clip(h2, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    if start is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=hard_end)
        return cur

    start_arr = np.asarray(start, dtype=float)
    if start_arr.ndim != 1 or start_arr.size < 1 or start_arr.sum() <= 0 \
            or not np.all(np.isfinite(start_arr)):
        return np.ones(50)

    start_r = R_of(start_arr)
    best = start_arr.copy()
    best_r = start_r
    alternative = None
    alt_r = -1.0
    rng = np.random.default_rng(1234567)
    n = start_arr.size

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # Phase A: full-shape smooth perturb + smoothed-max + exact polish.
    trials = 0
    while time.process_time() < hard_end - 8.0 and trials < 30:
        trials += 1
        sigma = 0.03 + 0.05 * rng.random()
        h = _smooth_perturb(start_arr, rng, sigma)
        for beta in (1200.0, 500.0, 200.0):
            if time.process_time() >= hard_end - 6.0:
                break
            c = _lbfgs_log(h, maxiter=200, deadline=hard_end, beta=beta)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 4.0:
            c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        c = _window_polish_peak(h, hard_end, 0.20, 8, maxiter=300)
        if R_of(c) >= R_of(h):
            h = c
        _consider(h, R_of(h))

    print("phaseA R=%.6f N=%d trials=%d" % (best_r, best.size, trials))

    # Phase B: intensify around best with shrinking windows + smoothed-max ladder.
    cur = best.copy()
    cur_r = best_r
    while time.process_time() < hard_end - 3.0:
        h = cur.copy()
        improved = False
        for beta in (100.0, 50.0, 25.0, 12.0):
            if time.process_time() >= hard_end - 2.0:
                break
            c = _lbfgs_log(h, maxiter=250, deadline=hard_end, beta=beta)
            if R_of(c) > R_of(h):
                h = c
                improved = True
        if time.process_time() < hard_end - 2.0:
            c = _lbfgs_log(h, maxiter=500, deadline=hard_end)
            if R_of(c) > R_of(h):
                h = c
                improved = True
        for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2)):
            if time.process_time() >= hard_end - 1.0:
                break
            c = _window_polish_peak(h, hard_end, frac, extra, maxiter=300)
            if R_of(c) > R_of(h):
                h = c
                improved = True
        r = R_of(h)
        if r > cur_r:
            cur, cur_r = h, r
            _consider(h, r)
        if not improved:
            lo, hi = _peak_region(cur)
            h2 = cur.copy()
            pad = max(4, (hi - lo) // 2)
            a = max(0, lo - pad); b = min(n - 1, hi + pad)
            band = h2[a:b + 1]
            h2[a:b + 1] = band * np.exp(rng.normal(0.0, 0.08, band.size))
            h2 = _rescale(np.clip(h2, 0.0, None))
            c = _lbfgs_log(h2, maxiter=300, deadline=hard_end)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
                _consider(c, r)

    print("phaseB R=%.6f N=%d" % (best_r, best.size))

    if best_r < start_r:
        best = start_arr.copy()
        best_r = start_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

