import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _prolong(h):
    n = h.size
    h2 = np.empty(2 * n, dtype=float)
    h2[0::2] = h
    h2[1::2] = h
    return h2


def _fp_step(h, theta, floor):
    # multiplicative-projection fixed point: q = backprop(pad(L/M), h)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return h
    g = np.zeros_like(Lf)
    g[1:-1] = Lf[1:-1] / M
    q = _backprop(g, h)
    q = np.clip(q, 0.0, None)
    qmax = q.max()
    if qmax <= 0:
        return h
    q = q / qmax
    h2 = h * (q ** theta)
    h2 = np.clip(h2, floor, None)
    return _rescale(h2)


def _dither_split(h, mode, rng):
    n = h.size
    if n % 2 != 0:
        return h
    if mode == 'unif':
        d = rng.uniform(-0.03, 0.03, size=n // 2)
    else:
        d = rng.normal(0.0, 0.01, size=n // 2)
    h2 = h.copy()
    h2[0::2] *= (1.0 + d)
    h2[1::2] *= (1.0 - d)
    h2 = np.clip(h2, 0.0, None)
    return _rescale(h2)


def _ratio_spread(h):
    if h.size < 2 or h.size % 2 != 0:
        return 1.0
    a = h[0::2]
    b = h[1::2]
    eps = 1e-12
    r = (a + eps) / (b + eps)
    return float(r.max() / max(r.min(), 1e-12))


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    # Prolong to double N (fine grid)
    h2 = _prolong(start_best)
    r_prol = R_of(h2)
    print("start R=%.9f (N=%d) -> prolonged R=%.9f (N=%d)" %
          (start_bestR, start_best.size, r_prol, h2.size))

    best = h2
    bestR = r_prol

    # Dither-split seeds
    seeds = []
    for mode in ('unif', 'norm'):
        hs = _dither_split(h2, mode, rng)
        rs = R_of(hs)
        print("  dither[%s] R=%.9f spread=%.4f" %
              (mode, rs, _ratio_spread(hs)))
        seeds.append((hs, rs))
        if rs > bestR:
            best, bestR = hs, rs

    # theta ladder for fixed point
    thetas = [0.5, 0.3, 0.2, 0.1, 0.05, 0.02]
    floor = 1e-9

    sweep = 0
    while time.process_time() < hard - 2.0:
        sweep += 1
        improved = False

        # exact-R log-space L-BFGS on full fine grid
        if time.process_time() < hard - 2.0:
            cap = min(hard - 1.0, time.process_time() + 2.0)
            hx = _lbfgs_log(best, 200, cap, fg=_fun_grad)
            rx = R_of(hx)
            if rx > bestR + 1e-14:
                best, bestR = hx, rx
                improved = True
                print("  [sweep%d exact] R=%.9f spread=%.4f" %
                      (sweep, bestR, _ratio_spread(best)))

        # fixed-point ladder
        for theta in thetas:
            if time.process_time() >= hard - 2.0:
                break
            hcur = best
            rcur = bestR
            for it in range(10):
                if time.process_time() >= hard - 2.0:
                    break
                hcur = _fp_step(hcur, theta, floor)
            rfp = R_of(hcur)
            print("  [sweep%d fp theta=%.2f] R=%.9f spread=%.4f" %
                  (sweep, theta, rfp, _ratio_spread(hcur)))
            if rfp > bestR + 1e-14:
                best, bestR = hcur, rfp
                improved = True
                print("    new best R=%.9f (fp)" % bestR)
            # polish on peak windows
            if time.process_time() < hard - 1.0:
                hp, rp = _polish(hcur, min(hard - 0.5,
                                           time.process_time() + 3.0))
                if rp > bestR + 1e-14:
                    best, bestR = hp, rp
                    improved = True
                    print("    new best R=%.9f (polish)" % bestR)

        if not improved and sweep > 2:
            # try a fresh dither from best
            hs = _dither_split(best, 'unif', rng)
            rs = R_of(hs)
            if rs > bestR + 1e-13:
                best, bestR = hs, rs
                print("    redither best R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    spread = _ratio_spread(best)
    print("final R=%.9f (N=%d) odd/even spread=%.4f" %
          (bestR, best.size, spread))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

