    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


# ---- NEW: explicit support-extension -----------------------------------------
# The autoconvolution of h is supported on [0, 2N]. Its peak sits where the
# mass of h aligns with itself. To push R higher we can grow the array by adding
# fresh (initially tiny) steps on BOTH ends -- the optimizer then reshapes them
# into extra mass that sharpens the peak (raises ||ff||_2^2 relative to ||ff||_1)
# without widening the peak proportionally. This is a genuinely different
# construction from a pure local polish of `start`.

def _extend_support(h, grow):
    """Return array with `grow` tiny steps prepended and appended."""
    if grow <= 0:
        return h.copy()
    n = h.size
    # tiny but nonzero so the log-parametrization / bounds keep them alive
    eps = 1e-3 * h.mean() if h.mean() > 0 else 1e-3
    pad = np.full(grow, eps)
    return np.concatenate([pad, h, pad])


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    # separate "alternative" line of search that grows the support
    alt = None
    altR = 0.0
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase A: refine `start` in place (cheap, keeps current best) -------
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 600, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # ---- Phase B: grow the support and optimise the extended array ----------
    # Pick a growth size that keeps the array under 1e6 and leaves time.
    n0 = best.size
    grow = max(64, min(int(n0 * 0.15), 4000, (1000000 - n0) // 2))
    if grow > 0 and time.process_time() < deadline - 3.0:
        ext = _extend_support(best, grow)
        ext = _rescale(ext)
        extR = R_of(ext)
        print("grow=%d ext R=%.7f" % (grow, extR))
        # Full-array polish of the extended array, then peak-focused polish.
        if time.process_time() < deadline - 3.0:
            ht = _lbfgs_all_pos(ext, 400, deadline - 3.0, beta=1e7)
            r = R_of(ht)
            if r > extR:
                ext, extR = ht, r
        for it in range(6):
            if time.process_time() >= deadline - 2.5:
                break
            win = _peak_window(ext, pad_frac=0.3 + 0.1 * it, extra=128)
            ht = _lbfgs_block(ext, win, maxiter=250, deadline=deadline - 2.5,
                              beta=1e7)
            r = R_of(ht)
            if r > extR + 1e-14:
                ext, extR = ht, r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(ext, 500, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > extR + 1e-14:
                ext, extR = ht, r
        alt, altR = ext.copy(), extR
        print("extended line R=%.7f (N=%d)" % (altR, alt.size))
        if altR > bestR:
            best, bestR = alt.copy(), altR

    # ---- Phase C: alternate polishing until deadline ------------------------
    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 500, deadline - 1.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 300, deadline - 1.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for frac in (0.1, 0.25, 0.5):
            if time.process_time() >= deadline - 1.5:
                break
            win = _peak_window(best, pad_frac=frac, extra=256)
            ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.5,
                              beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, best.size))

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        if alt is not None and altR < bestR - 1e-9:
            return {"best": best, "alternative": alt}
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6 and altR > 0:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

