def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _bb_polish(h, maxit, deadline, seed_eps=0.0):
    """Barzilai-Borwein projected gradient with non-monotone Armijo backtracking
    on the exact R (via -log R gradient)."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    if seed_eps > 0:
        h = h.copy()
        thr = 1e-12 * h.max()
        m = h.mean()
        if m > 0:
            mask = h < thr
            h[mask] = seed_eps * m
    h = _rescale(h)
    Rbest = R_of(h)
    best = h.copy()

    val, g = _fun_grad(h)
    alpha = 1e-3
    accept_streak = 0
    R_hist = [Rbest]

    for it in range(maxit):
        if time.process_time() > deadline - 0.3:
            break
        gmax = np.abs(g).max()
        if gmax <= 0:
            break
        d = -g / (gmax + 1e-30)
        R_ref = max(R_hist[-10:]) if R_hist else Rbest
        accepted = False
        h_new = None
        for _bt in range(40):
            cand = np.clip(h + alpha * d, 0, None)
            if cand.sum() <= 0:
                alpha *= 0.5
                continue
            cand = _rescale(cand)
            Rc = R_of(cand)
            if Rc > R_ref - 1e-12:
                h_new = cand
                accepted = True
                break
            alpha *= 0.5
        if not accepted:
            # try a tiny step anyway to escape
            cand = np.clip(h + 1e-9 * d, 0, None)
            if cand.sum() > 0:
                h_new = _rescale(cand)
                alpha = 1e-6
            else:
                break
        val_new, g_new = _fun_grad(h_new)
        s = h_new - h
        y = g_new - g
        sy = float(np.dot(s, y))
        ss = float(np.dot(s, s))
        if sy > 1e-30 and ss > 0:
            alpha = np.clip(ss / sy, 1e-9, 1e4)
        else:
            alpha = np.clip(alpha * 1.5, 1e-9, 1e4)
        h = h_new
        g = g_new
        val = val_new
        Rc = R_of(h)
        R_hist.append(Rc)
        if Rc > Rbest:
            Rbest = Rc
            best = h.copy()
        accept_streak += 1
        if accept_streak >= 3:
            alpha = np.clip(alpha * 1.5, 1e-9, 1e4)
            accept_streak = 0
        if (it + 1) % 500 == 0:
            print("bb it=%d R=%.7f zeros=%.1f%% alpha=%.3g"
                  % (it + 1, Rc, 100.0 * np.mean(h <= 0), alpha))
    return best


def construct(budget_seconds, start):
