        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    # --- Experiment: midpoint-interpolate to 2x resolution ---
    h0 = start_best
    N0 = h0.size
    N2 = 2 * N0
    h2 = np.zeros(N2)
    h2[0::2] = h0
    nxt = np.concatenate((h0[1:], h0[-1:]))
    h2[1::2] = 0.5 * (h0 + nxt)
    h2 = _rescale(h2)
    # degeneracy check
    mx2 = h2.max() if h2.size else 0.0
    pairs_equal = np.mean(np.abs(h2[0::2] - h2[1::2]) < 1e-12 * (mx2 + 1e-30))
    R2 = R_of(h2)
    print("interp N=%d R=%.7f pairs_equal=%.3f (start R=%.7f)"
          % (N2, R2, pairs_equal, start_bestR))

    # Polishing at 2x resolution, maxiter scaled ~0.5
    best = h2.copy()
    bestR = R2
    N = N2
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 200, deadline - 2.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for (frac, extra, beta) in [(0.05, 64, 1e7), (0.10, 64, 1e8),
                                    (0.25, 128, 1e8), (0.40, 256, 1e8),
                                    (0.60, 512, 1e8)]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _window_polish_peak(best, deadline - 2.0, frac, extra,
                                     maxiter=150, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_log(best, 150, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 2.0:
            ht = _refine_knots(best, 40, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, N))

    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 2000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.2)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _bb_polish(h, maxit, deadline, seed_eps=0.0):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    if seed_eps > 0:
        h = h.copy()
        thr = 1e-12 * h.max()
        m = h.mean()
        if m > 0:
            mask = h < thr
            h[mask] = seed_eps * m
    h = _rescale(h)
    Rbest = R_of(h)
    best = h.copy()

    val, g = _fun_grad(h)
    alpha = 1e-3
    accept_streak = 0
    R_hist = [Rbest]

    for it in range(maxit):
        if time.process_time() > deadline - 0.3:
            break
        gmax = np.abs(g).max()
        if gmax <= 0:
            break
        d = -g / (gmax + 1e-30)
        R_ref = max(R_hist[-10:]) if R_hist else Rbest
        accepted = False
        h_new = None
        for _bt in range(40):
            cand = np.clip(h + alpha * d, 0, None)
            if cand.sum() <= 0:
                alpha *= 0.5
                continue
            cand = _rescale(cand)
            Rc = R_of(cand)
            if Rc > R_ref - 1e-12:
                h_new = cand
                accepted = True
                break
            alpha *= 0.5
        if not accepted:
            cand = np.clip(h + 1e-9 * d, 0, None)
            if cand.sum() > 0:
                h_new = _rescale(cand)
                alpha = 1e-6
            else:
                break
        val_new, g_new = _fun_grad(h_new)
        s = h_new - h
        y = g_new - g
        sy = float(np.dot(s, y))
        ss = float(np.dot(s, s))
        if sy > 1e-30 and ss > 0:
            alpha = np.clip(ss / sy, 1e-9, 1e4)
        else:
            alpha = np.clip(alpha * 1.5, 1e-9, 1e4)
        h = h_new
        g = g_new
        val = val_new
        Rc = R_of(h)
        R_hist.append(Rc)
        if Rc > Rbest:
            Rbest = Rc
            best = h.copy()
        accept_streak += 1
        if accept_streak >= 3:
            alpha = np.clip(alpha * 1.5, 1e-9, 1e4)
            accept_streak = 0
    return best


def _extend_support(h, grow):
    if grow <= 0:
        return h.copy()
    eps = 1e-3 * h.mean() if h.mean() > 0 else 1e-3
    pad = np.full(grow, eps)
    return np.concatenate([pad, h, pad])


def _interp_refine(h, factor=2):
    """Refine to a finer grid by linear interpolation (upsampling)."""
    n = h.size
    if factor <= 1:
        return h.copy()
    m = (n - 1) * factor + 1
    x_old = np.arange(n, dtype=float)
    x_new = np.linspace(0, n - 1, m)
    hf = np.interp(x_new, x_old, h)
    return np.clip(hf, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- NEW: support-extension construction --------------------------------
    # Grow the array on both ends with small steps, then optimize the whole
    # extended array. This is a genuinely different construction from a pure
    # local polish. Only keep it if it beats `start`; otherwise expose it as
    # an "alternative" so search can restart from it.
    alt = None
    altR = 0.0
    if time.process_time() < deadline - 5.0:
        grow = max(64, best.size // 8)
        he = _extend_support(best, grow)
        he = _lbfgs_all_pos(he, 2000, deadline - 4.0, beta=1e7)
        he = _bb_polish(he, 3000, deadline - 3.0, seed_eps=1e-3)
        he = _lbfgs_all_pos(he, 2000, deadline - 2.0, beta=0.0)
        re = R_of(he)
        print("extend R=%.7f (N=%d)" % (re, he.size))
        if re > bestR + 1e-12:
            best, bestR = he.copy(), re
        else:
            alt, altR = he.copy(), re

    # ---- NEW: interpolation refinement to finer grid ------------------------
    if time.process_time() < deadline - 5.0:
        hf = _interp_refine(best, factor=2)
        hf = _lbfgs_all_pos(hf, 3000, deadline - 4.0, beta=1e7)
        hf = _bb_polish(hf, 4000, deadline - 3.0, seed_eps=1e-3)
        hf = _lbfgs_all_pos(hf, 3000, deadline - 2.0, beta=0.0)
        rf = R_of(hf)
        print("refine R=%.7f (N=%d)" % (rf, hf.size))
        if rf > bestR + 1e-12:
            best, bestR = hf.copy(), rf
        else:
            if alt is None or rf > altR:
                alt, altR = hf.copy(), rf

    # ---- main polish loop ---------------------------------------------------
    N = best.size
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 800, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
            ht = _bb_polish(best, 400, deadline - 2.0, seed_eps=1e-3)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for (frac, extra, beta) in [(0.05, 64, 1e7), (0.10, 64, 1e8),
                                    (0.25, 128, 1e8), (0.40, 256, 1e8),
                                    (0.60, 512, 1e8)]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _window_polish_peak(best, deadline - 2.0, frac, extra,
                                     maxiter=300, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_log(best, 300, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, N))

    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 4000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _bb_polish(best, 20000, deadline - 0.2, seed_eps=1e-3)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": alt}
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else alt}

