    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _grow_boundary(h, grow):
    """Insert `grow` new steps at the boundary positions where the local
    mass is largest, so new degrees of freedom go where they matter."""
    if grow <= 0:
        return h.copy()
    n = h.size
    eps = max(1e-6, 1e-3 * h.mean())
    # Score each boundary by adjacent mass; insert extra steps there.
    out = []
    remaining = grow
    # split grow across the two highest-mass edge regions and the interior
    # take a simple approach: add to both ends proportional to end mass
    left_mass = h[:max(1, n // 8)].sum()
    right_mass = h[-max(1, n // 8):].sum()
    tot = left_mass + right_mass + 1e-30
    gl = int(round(grow * left_mass / tot))
    gr = grow - gl
    if gl > 0:
        out.append(np.full(gl, eps))
    out.append(h)
    if gr > 0:
        out.append(np.full(gr, eps))
    return np.concatenate(out)


def _interp_refine(h, factor=2):
    """Subdivide each step into `factor` equal sub-steps (piecewise-linear
    upsampling preserves the shape and often helps the optimizer)."""
    if factor <= 1:
        return h.copy()
    n = h.size
    out = np.empty(n * factor, dtype=float)
    for k in range(factor):
        out[k::factor] = h
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = 0.0
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase A: refine start in place ----
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 600, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # ---- Phase B: NEW construction line -- grid refinement + boundary growth.
    # Upsample by 2 (each original step becomes two equal sub-steps); this
    # keeps R identical initially but gives the optimizer finer resolution to
    # sharpen the peak plateau. Then grow a small halo of fresh steps at both
    # ends and polish. This is genuinely different from the start.
    if time.process_time() < deadline - 6.0 and best.size * 2 <= 500000:
        try:
            ref = _interp_refine(best, 2)
            ref = _rescale(ref)
            refR = R_of(ref)
            if time.process_time() < deadline - 5.0:
                ht = _lbfgs_all_pos(ref, 300, deadline - 5.0, beta=1e7)
                r = R_of(ht)
                if r > refR:
                    ref, refR = ht, r
            # grow a halo
            n0 = ref.size
            grow = max(64, min(int(n0 * 0.08), 4000, (1000000 - n0) // 2))
            if grow > 0 and time.process_time() < deadline - 4.0:
                ext = _grow_boundary(ref, grow)
                ext = _rescale(ext)
                extR = R_of(ext)
                if time.process_time() < deadline - 4.0:
                    ht = _lbfgs_all_pos(ext, 400, deadline - 4.0, beta=1e7)
                    r = R_of(ht)
                    if r > extR:
                        ext, extR = ht, r
                for it in range(4):
                    if time.process_time() >= deadline - 3.0:
                        break
                    win = _peak_window(ext, pad_frac=0.3 + 0.1 * it, extra=128)
                    ht = _lbfgs_block(ext, win, maxiter=250,
                                      deadline=deadline - 3.0, beta=1e8)
                    r = R_of(ht)
                    if r > extR + 1e-14:
                        ext, extR = ht, r
                if time.process_time() < deadline - 2.5:
                    ht = _lbfgs_all_pos(ext, 500, deadline - 2.5, beta=0.0)
                    r = R_of(ht)
                    if r > extR + 1e-14:
                        ext, extR = ht, r
                ref, refR = ext, extR
            alt, altR = ref.copy(), refR
            print("refined line R=%.7f (N=%d)" % (altR, alt.size))
            if altR > bestR:
                best, bestR = alt.copy(), altR
        except Exception:
            pass

    # ---- Phase C: alternate polishing until deadline ----
    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 500, deadline - 1.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 300, deadline - 1.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for frac in (0.1, 0.25, 0.5):
            if time.process_time() >= deadline - 1.5:
                break
            win = _peak_window(best, pad_frac=frac, extra=256)
            ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.5,
                              beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, best.size))

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        if alt is not None and altR < bestR - 1e-9:
            return {"best": best, "alternative": alt}
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6 and altR > 0:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h, frac=0.05):
    """Perturb: set a small fraction of smallest entries to zero and
    re-optimize; used to escape a critical point."""
    h = np.clip(h, 0, None).copy()
    n = h.size
    k = max(1, int(n * frac))
    idx = np.argsort(h)[:k]
    h[idx] = 0.0
    return _rescale(h)


def _refine_knots(h, maxiter, deadline):
    """Optimize on the knot values directly via the peak window with
    a tight beta schedule."""
    if time.process_time() >= deadline - 0.5:
        return h
    win = _peak_window(h, pad_frac=0.5, extra=512)
    return _lbfgs_block(h, win, maxiter=maxiter, deadline=deadline, beta=1e8)


def run_cycle(best, bestR, deadline):
    """One alternating cycle: full polish, beta polish, peak windows,
    zero-seeded refine."""
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 500, deadline - 1.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 1.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    for frac in (0.1, 0.25, 0.5):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=256)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.5,
                          beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    # zero-seeded escape attempt
    if time.process_time() < deadline - 1.5:
        hz = _seed_zeros(best, frac=0.03)
        ht = _lbfgs_all_pos(hz, 200, deadline - 1.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase A: first cycle loop on the given start ----------------------
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        prevR = bestR
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d dR=%.2e"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, best.size,
                 bestR - prevR))
        if bestR - prevR < 1e-9 and cycle >= 2:
            break

    # ---- Closing stage: full polish + knot refine --------------------------
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 4000, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 2.0:
        ht = _refine_knots(best, 200, deadline - 2.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("closing R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (bestR, 100.0 * np.mean(best <= 0), am, best.size))

    # ---- Second outer loop: 2 full cycles + zero-seeded knot refine --------
    outer = 0
    while outer < 2 and time.process_time() < deadline - 2.0:
        outer += 1
        prevR = bestR
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        if time.process_time() < deadline - 2.0:
            hz = _seed_zeros(best, frac=0.02)
            ht = _refine_knots(hz, 300, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("outer %d R=%.7f zeros=%.1f%% argmax=%d/%d dR=%.2e"
              % (outer, bestR, 100.0 * np.mean(best <= 0), am, best.size,
                 bestR - prevR))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return start_best

