    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _extend(h, pad):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = 1e-3 * h.mean()
    filler = np.full(pad, eps)
    out = np.concatenate((filler, h, filler))
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase C: base cycle loop (upsample phase gated OFF) ----
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        prevR = bestR
        best, bestR, drefine = run_cycle(best, bestR, deadline - 1.5)
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f dR=%.2e drefine=%.2e zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, bestR - prevR, drefine,
                 100.0 * np.mean(best <= 0), am, best.size))
        if bestR - prevR < 1e-13 and cycle > 2:
            if time.process_time() > deadline - 6.0:
                break

    # ---- Phase D: support-extension rounds on the dense representation ----
    ext_pads = [12000, 6000]
    for ei, pad in enumerate(ext_pads):
        if time.process_time() >= deadline - 6.0:
            break
        hext = _extend(best, pad)
        r = R_of(hext)
        print("ext%d R=%.7f (N=%d) zeros=%.1f%%"
              % (ei + 1, r, hext.size, 100.0 * np.mean(hext <= 0)))
        cur, curR = hext, r
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
        gained = 0.0
        ec = 0
        while ec < 8 and time.process_time() < deadline - 6.0:
            ec += 1
            prevR = curR
            cur, curR, dref = run_cycle(cur, curR, deadline - 6.0)
            g = curR - prevR
            gained += max(g, 0.0)
            print("ext%d cycle %d R=%.7f dR=%.2e zeros=%.1f%%"
                  % (ei + 1, ec, curR, g, 100.0 * np.mean(cur <= 0)))
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
            if g < 1e-13:
                break
        if gained >= 1e-6:
            break

    # ---- closing polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.8:
        win = _peak_window(best, pad_frac=0.25, extra=256)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.8:
        ht = _refine_knots(best, 400, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _coarsen4(h):
    n = h.size
    n4 = n // 4
    if n4 < 1:
        return h.copy()
    hh = h[:n4 * 4].reshape(n4, 4)
    return hh.mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase C: one base cycle ----
    if time.process_time() < deadline - 12.0:
        prevR = bestR
        best, bestR, drefine = run_cycle(best, bestR, deadline - 11.0)
        print("cycle 1 R=%.7f dR=%.2e drefine=%.2e zeros=%.1f%%"
              % (bestR, bestR - prevR, drefine, 100.0 * np.mean(best <= 0)))

    # ---- Phase E: coarse basin hopping ----
    hc = _coarsen4(best)
    hcR = R_of(hc)
    print("coarse baseline R=%.7f (N=%d)" % (hcR, hc.size))

    rng = np.random.default_rng(12345)
    candidates = []  # list of (R, hc)
    ncoarse = hc.size
    mean_hc = hc.mean() if hc.size > 0 else 1.0
    eps_seed = 1e-3 * mean_hc if mean_hc > 0 else 1e-6

    restart = 0
    while time.process_time() < deadline - 12.0:
        restart += 1
        hc_r = hc.copy()
        pos = hc_r > 0
        noise = rng.normal(0.0, 0.05, size=hc_r.size)
        hc_r[pos] = hc_r[pos] * np.exp(noise[pos])
        zeros = np.flatnonzero(hc_r <= 0)
        if zeros.size > 0:
            k = max(1, int(0.10 * zeros.size))
            pick = rng.choice(zeros, size=min(k, zeros.size), replace=False)
            hc_r[pick] = eps_seed
        hc_r = _rescale(hc_r)
        try:
            ht = _lbfgs_all_pos(hc_r, 300, deadline - 12.0, beta=1e7)
            ht = _lbfgs_all_pos(ht, 300, deadline - 12.0, beta=0.0)
        except Exception:
            continue
        r = R_of(ht)
        print("restart %d coarse R=%.7f (d=%.2e)"
              % (restart, r, r - hcR))
        # keep best 3 distinct
        duplicate = False
        for (rr, hh) in candidates:
            if hh.size == ht.size and np.allclose(hh, ht, rtol=1e-6, atol=1e-12):
                duplicate = True
                break
        if duplicate:
            continue
        candidates.append((r, ht.copy()))
        candidates.sort(key=lambda x: -x[0])
        if len(candidates) > 3:
            candidates = candidates[:3]

    # ---- Phase F: prolongate best coarse candidates and refine ----
    best_fine = best.copy()
    best_fineR = bestR
    for (rr, hh) in candidates:
        if time.process_time() >= deadline - 2.0:
            break
        hf = np.repeat(hh, 4)
        hf = _rescale(hf)
        cur, curR = hf, R_of(hf)
        for _ in range(2):
            if time.process_time() >= deadline - 2.0:
                break
            cur, curR, _ = run_cycle(cur, curR, deadline - 1.5)
        print("prolongated R=%.7f (coarse %.7f)" % (curR, rr))
        if curR > best_fineR + 1e-13:
            best_fine, best_fineR = cur.copy(), curR

    # ---- Phase G: final polish ----
    if time.process_time() < deadline - 1.0:
        ht = _refine_knots(best_fine, 400, deadline - 0.6)
        r = R_of(ht)
        if r > best_fineR + 1e-14:
            best_fine, best_fineR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best_fine, 600, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > best_fineR + 1e-14:
            best_fine, best_fineR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (best_fineR, best_fine.size, 100.0 * np.mean(best_fine <= 0)))

    if best_fineR > start_bestR + 1e-12:
        return best_fine
    out = {"best": start_best}
    if best_fineR > start_bestR - 1e-6:
        out["alternative"] = best_fine
    return out

