        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


# ---------- flat-target objective (broaden the top of f*f) ----------

def _flat_fg(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    c = Lf.max()
    w = Lf * Lf + 1e-12
    diff = Lf - c
    num = np.sum(w * diff * diff)
    den = np.sum(w)
    if den <= 0:
        return 1e18, np.zeros(h.size)
    val = np.log(num / den + 1e-300)
    gLf = 2.0 * w * diff / num
    grad = _backprop(gLf, h)
    return val, grad


def _flat_descent(h0, seconds, deadline):
    cap = min(deadline - 0.3, time.process_time() + seconds)
    return _lbfgs_log(h0, 200, cap, fg=None) if False else _lbfgs_flat(h0, 200, cap)


def _lbfgs_flat(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _flat_fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _polish(h, deadline, bestR):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 3.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 1.0:
        free = _peak_window(best, tol=0.9995, pad_frac=0.5, extra=512)
        hs = _lbfgs_block(best, free, 200, min(deadline - 0.5, time.process_time() + 5.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


# ---------- the new idea: knot-refinement by inserting interior knots ----------

def _refine_interp(h, factor=2):
    """Resample h to a finer grid via linear interpolation (inserts knots)."""
    n = h.size
    N = n * factor
    x = np.linspace(0, n, N, endpoint=False)
    xi = np.arange(N, dtype=float)
    # positions of the new samples in the old index space
    pos = (xi + 0.5) / factor - 0.5
    pos = np.clip(pos, 0, n - 1)
    lo = np.floor(pos).astype(int)
    hi = np.minimum(lo + 1, n - 1)
    frac = pos - lo
    return (1 - frac) * h[lo] + frac * h[hi]


def _refine_upsample(h, factor=2):
    """Upsample with no smoothing: replicate each height `factor` times."""
    return np.repeat(h, factor).astype(float)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    record_R = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    bestH = best.copy()
    bestRH = bestR

    # ---- New idea: knot-refinement. Finer grid gives the optimiser freedom
    # to smooth the shoulders of f*f, broadening the near-max region. ----
    candidates = []
    if best.size < 300000:
        for factor in (2, 3):
            for tag, fn in (("rep", _refine_upsample), ("lin", _refine_interp)):
                hr = _rescale(fn(best, factor))
                rr = R_of(hr)
                candidates.append(("refine %s x%d" % (tag, factor), hr, rr))
                if time.process_time() > deadline - 6.0:
                    break
            if time.process_time() > deadline - 6.0:
                break
    for name, hr, rr in candidates:
        print("  %-16s pre R=%.7f (d=%.2e)" % (name, rr, rr - record_R))

    candidates.sort(key=lambda v: -v[2])
    # polish the top refined candidates with the true objective
    for name, hr, rr in candidates[:2]:
        if time.process_time() >= deadline - 4.0:
            break
        cap = min(deadline - 1.0, time.process_time() + 10.0)
        hp, rp = _polish(hr, cap, record_R)
        print("  polish %-16s -> R=%.7f" % (name, rp))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST (refine) R=%.7f" % bestRH)

    # ---- flat-target descent on best so far ----
    if time.process_time() < deadline - 6.0:
        cap = min(deadline - 0.5, time.process_time() + 8.0)
        hf = _lbfgs_flat(bestH, 200, cap)
        rf = R_of(hf)
        print("  flat-target R=%.7f (d=%.2e)" % (rf, rf - bestRH))
        if time.process_time() < deadline - 3.0:
            hf2, rf2 = _polish(hf, min(deadline - 0.5, time.process_time() + 6.0), record_R)
            if rf2 > rf:
                hf, rf = hf2, rf2
        if rf > bestRH + 1e-13:
            bestH, bestRH = hf.copy(), rf
            print("    NEW BEST (flat) R=%.7f" % bestRH)

    # ---- remaining time: alternating sharpen + peak-window + soft polish ----
    rng = np.random.default_rng(20240824)
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            improved = True
        if time.process_time() < loop_end:
            free = _peak_window(bestH, tol=0.9995, pad_frac=0.3 + 0.4 * rng.random(), extra=384)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                improved = True
        if not improved and time.process_time() < loop_end - 1.5:
            beta = 10.0 ** rng.uniform(1.0, 4.0)
            cap = min(loop_end, time.process_time() + 2.5)
            hs = _lbfgs_log(bestH, 100, cap, beta=beta)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs.copy(), rs
                improved = True
        if improved:
            print("  iter=%d R=%.7f" % (it, bestRH))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0)))

    if bestRH > start_bestR + 1e-12:
        return bestH
    if bestH.size != start_best.size or bestRH > start_bestR - 5e-3:
        return {"best": start_best, "alternative": bestH}
    return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _envelope(h, alpha, tfrac):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    hmax = h.max()
    act = np.flatnonzero(h > 1e-9 * hmax)
    if act.size == 0:
        return h
    idx = np.arange(h.size)
    d = np.minimum(idx - act.min(), act.max() - idx)
    d = np.clip(d, 0, None)
    tau = max(8.0, tfrac * h.size)
    w = 1.0 + alpha * np.exp(-d / tau)
    return _rescale(h * w)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- One base run_cycle to get incumbent ----
    if time.process_time() < deadline - 2.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("cycle 1 R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Envelope experiment ----
    env_params = [(0.5, 0.01), (2.0, 0.01), (8.0, 0.01), (2.0, 0.03), (8.0, 0.03)]
    n_e = len(env_params)
    for ei, (alpha, tfrac) in enumerate(env_params):
        now = time.process_time()
        if now >= deadline - 4.0:
            break
        remaining = deadline - 4.0 - now
        per = remaining / max(1, (n_e - ei))
        cand_deadline = min(deadline - 4.0, now + per)
        h_env = _envelope(best, alpha, tfrac)
        r0 = R_of(h_env)
        print("env alpha=%.1f tau=%.0f R0=%.7f" % (alpha, tfrac * best.size, r0))
        cur, curR, _ = run_cycle(h_env, r0, cand_deadline)
        Lf = _knots(cur)
        am = int(np.argmax(Lf)) / max(1, cur.size - 1)
        print("env alpha=%.1f R=%.7f dR=%.2e zeros=%.1f%% amax=%.3f"
              % (alpha, curR, curR - bestR, 100.0 * np.mean(cur <= 0), am))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    # ---- Leftover: run_cycle loop + peak ladder on winner ----
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        prevR = bestR
        best, bestR, drefine = run_cycle(best, bestR, deadline - 1.5)
        print("cycle %d R=%.7f dR=%.2e" % (cycle, bestR, bestR - prevR))
        if bestR - prevR < 1e-13 and cycle > 2:
            break

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _runs(idx, n):
    """Split sorted index array into contiguous runs, return list of (lo,hi)."""
    if idx.size == 0:
        return []
    runs = []
    lo = idx[0]; prev = idx[0]
    for v in idx[1:]:
        if v == prev + 1:
            prev = v
        else:
            runs.append((lo, prev))
            lo = v; prev = v
    runs.append((lo, prev))
    return runs


def _peak_windows(h):
    """Multi-region selector: union of dilated contiguous runs at 3 thresholds."""
    Lf = _knots(h)
    mx = Lf.max()
    n = h.size
    if mx <= 0:
        return np.arange(n)
    pad = max(64, int(0.02 * n))
    mask = np.zeros(n, dtype=bool)
    for thr in (0.999, 0.99, 0.95):
        idx = np.flatnonzero(Lf >= thr * mx)
        for lo, hi in _runs(idx, n):
            lo = max(0, lo - pad)
            hi = min(n - 1, hi + pad)
            mask[lo:hi + 1] = True
    return np.flatnonzero(mask)


def _band_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (100.0 * np.mean(Lf >= 0.999 * mx),
            100.0 * np.mean(Lf >= 0.99 * mx),
            100.0 * np.mean(Lf >= 0.95 * mx))


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    # ---- multi-region ladder replaces single-window ladder ----
    ladder = [(1e7, 250), (1e8, 250), (1e8, 250), (1e8, 250), (1e8, 250)]
    for beta, maxiter in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_windows(best)
        ht = _lbfgs_block(best, win, maxiter=maxiter, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        nreg = len(_runs(win, best.size))
        s = _band_shares(ht)
        print("multiwin nregions=%d nidx=%d R=%.7f dR=%.2e bands=%.1f/%.1f/%.1f"
              % (nreg, win.size, r, r - bestR, s[0], s[1], s[2]))
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _extend(h, pad):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = 1e-3 * h.mean()
    filler = np.full(pad, eps)
    out = np.concatenate((filler, h, filler))
    return _rescale(out)


def _kkt_diagnostic(h):
    val, grad = _fun_grad(np.clip(h, 0, None))
    g = -grad
    hmax = h.max() if h.size else 0.0
    zero_mask = h <= 1e-12 * hmax
    pos_mask = ~zero_mask
    gz = g[zero_mask]
    gp = g[pos_mask]
    def stats(a):
        if a.size == 0:
            return (0.0, 0.0, 0.0)
        return (float(a.max()), float(a.mean()), float(np.median(a)))
    sz = stats(gz)
    sp = stats(gp)
    print("KKT: zeros n=%d max=%.3e mean=%.3e med=%.3e | pos n=%d max=%.3e mean=%.3e med=%.3e"
          % (gz.size, sz[0], sz[1], sz[2], gp.size, sp[0], sp[1], sp[2]))
    return g, zero_mask


def _warp(h, gamma):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0:
        return h
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h))) / s
    u = np.linspace(0.0, 1.0, N + 1)
    v = u ** gamma
    newC = np.interp(v, u, C)
    out = np.diff(newC)
    return _rescale(np.clip(out, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: warped restarts before base cycle loop ----
    gammas = [0.85, 0.90, 0.95, 1.05, 1.10, 1.20]
    n_g = len(gammas)
    for gi, gamma in enumerate(gammas):
        now = time.process_time()
        if now >= deadline - 8.0:
            break
        remaining = deadline - 8.0 - now
        per = remaining / max(1, (n_g - gi))
        cand_deadline = min(deadline - 8.0, now + per)
        hw = _warp(start_best, gamma)
        r0 = R_of(hw)
        print("warp gamma=%.2f R0=%.7f" % (gamma, r0))
        cur, curR, _ = run_cycle(hw, r0, cand_deadline)
        print("warp gamma=%.2f R=%.7f (dR=%.2e) zeros=%.1f%%"
              % (gamma, curR, curR - start_bestR, 100.0 * np.mean(cur <= 0)))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    # ---- Phase C: base cycle loop ----
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        prevR = bestR
        best, bestR, drefine = run_cycle(best, bestR, deadline - 1.5)
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f dR=%.2e drefine=%.2e zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, bestR - prevR, drefine,
                 100.0 * np.mean(best <= 0), am, best.size))
        if bestR - prevR < 1e-13 and cycle > 2:
            if time.process_time() > deadline - 6.0:
                break
        if cycle >= 1:
            break

    # ---- KKT diagnostic + multi-zero activation ----
    g, zero_mask = _kkt_diagnostic(best)
    zero_idx = np.flatnonzero(zero_mask)
    if zero_idx.size > 0:
        order = np.argsort(-g[zero_idx])
        ranked_zeros = zero_idx[order]
    else:
        ranked_zeros = zero_idx

    hmean = best.mean()
    ks = [32, 128, 512]
    alphas = [1e-4, 1e-2, 1e-1]
    for k in ks:
        for a in alphas:
            if time.process_time() >= deadline - 6.0:
                break
            if ranked_zeros.size == 0:
                continue
            kk = min(k, ranked_zeros.size)
            cand = best.copy()
            cand[ranked_zeros[:kk]] = a * hmean
            cand = _rescale(cand)
            win = _peak_windows(cand)
            cand = _lbfgs_block(cand, win, maxiter=200,
                                deadline=deadline - 6.0, beta=1e8)
            cand = _lbfgs_all_pos(cand, 200, deadline - 6.0, beta=0.0)
            win2 = _peak_windows(cand)
            cand = _lbfgs_block(cand, win2, maxiter=200,
                                deadline=deadline - 6.0, beta=1e8)
            r = R_of(cand)
            print("trial k=%d a=%.0e -> R=%.7f (dR=%.2e)"
                  % (k, a, r, r - bestR))
            if r > bestR + 1e-13:
                best, bestR = cand.copy(), r

    # ---- Phase D: support-extension rounds ----
    ext_pads = [6000, 3000]
    for ei, pad in enumerate(ext_pads):
        if time.process_time() >= deadline - 6.0:
            break
        hext = _extend(best, pad)
        r = R_of(hext)
        print("ext R=%.7f (N=%d) pad=%d" % (r, hext.size, pad))
        cur, curR = hext, r
        gained = 0.0
        ec = 0
        while time.process_time() < deadline - 6.0:
            ec += 1
            prevR = curR
            cur, curR, dref = run_cycle(cur, curR, deadline - 6.0)
            g_ = curR - prevR
            gained += max(g_, 0.0)
            print("ext%d cycle %d R=%.7f dR=%.2e zeros=%.1f%%"
                  % (ei + 1, ec, curR, g_, 100.0 * np.mean(cur <= 0)))
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
            if g_ < 1e-8:
                break
        if gained >= 1e-8:
            break

    # ---- slot-1 sub-block loop on current best (multi-region windows) ----
    widths = [400, 1200]
    wi = 0
    while time.process_time() < deadline - 1.5:
        w = widths[wi % len(widths)]
        wi += 1
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        lo = max(0, am - w)
        hi = min(best.size - 1, am + w)
        win = np.arange(lo, hi + 1)
        cand = _lbfgs_block(best, win, maxiter=100,
                            deadline=deadline - 1.0, beta=1e8)
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            print("slot1 w=%d R=%.7f" % (w, bestR))
        else:
            cand2 = _lbfgs_all_pos(best, 100, deadline - 1.0, beta=0.0)
            r2 = R_of(cand2)
            if r2 > bestR + 1e-13:
                best, bestR = cand2.copy(), r2

    # ---- NEW: final multi-region softmax pass on full array ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e8)
        r = R_of(ht)
        s = _band_shares(ht)
        print("final multiwin R=%.7f dR=%.2e bands=%.1f/%.1f/%.1f"
              % (r, r - bestR, s[0], s[1], s[2]))
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    # ---- closing global polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _extend_tail(h, pad):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    act = np.flatnonzero(h > 1e-9 * h.max())
    if act.size == 0:
        act = np.arange(h.size)
    hedgeL = float(np.mean(h[act[:min(32, act.size)]]))
    hedgeR = float(np.mean(h[act[-min(32, act.size):]]))
    if hedgeL <= 0:
        hedgeL = 1e-6 * h.mean()
    if hedgeR <= 0:
        hedgeR = 1e-6 * h.mean()
    rho = 0.05 ** (1.0 / pad)
    left = hedgeL * rho ** np.arange(pad, 0, -1)
    right = hedgeR * rho ** np.arange(1, pad + 1)
    out = np.concatenate((left, h, right))
    return _rescale(np.clip(out, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # One base run_cycle to get the reference best.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Experiment: geometrically-decaying tail support extensions ----
    pads = [8000, 16000]
    n_p = len(pads)
    for pi, pad in enumerate(pads):
        now = time.process_time()
        if now >= deadline - 1.5:
            break
        remaining = deadline - 1.5 - now
        per = remaining / max(1, (n_p - pi))
        round_deadline = min(deadline - 1.5, now + per)
        hext = _extend_tail(best, pad)
        r0 = R_of(hext)
        print("extpad pad=%d R0=%.7f N=%d" % (pad, r0, hext.size))
        cur, curR = hext, r0
        ec = 0
        while time.process_time() < round_deadline - 0.5:
            ec += 1
            prevR = curR
            cur, curR, _ = run_cycle(cur, curR, round_deadline - 0.5)
            g = curR - prevR
            print("extpad pad=%d cycle %d R=%.7f dR=%.2e zeros=%.1f%%"
                  % (pad, ec, curR, g, 100.0 * np.mean(cur <= 0)))
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
            if g < 1e-9:
                break

    # ---- Final peak ladder + polish on best ----
    for frac, extra, beta in [(0.10, 128, 1e8), (0.25, 256, 1e8)]:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.0,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, beta):
    """Soft-max surrogate for sup: log-mean-exp of knots, beta controls sharpness."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _Q_value(h, c, beta):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    return float(np.sum(Lf * sig))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Main loop: alternate soft-max surrogate (different basin) with exact polish.
    betas = [50.0, 200.0, 800.0, 3000.0]
    cs = [0.90, 0.95, 0.98, 0.99]
    Qbetas = [1e3, 1e4, 1e5]

    sweep = 0
    stale = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False

        # soft-max attempt at various sharpness (escapes exact-sup flat spots)
        for beta in betas:
            if time.process_time() >= hard - 3.0:
                break
            fg = (lambda hh, bb=beta: _fun_grad_soft(hh, bb))
            cap = min(hard - 2.0, time.process_time() + 3.0)
            hs = _lbfgs_log(best, 150, cap, fg=fg)
            rs = R_of(hs)
            if rs > bestR + 1e-14:
                # polish exact
                hp, rp = _polish(hs, min(hard - 1.0, time.process_time() + 5.0))
                if rp > bestR + 1e-14:
                    best, bestR = hp, rp
                    improved = True
                    print("  [soft b=%.0e] R=%.9f->polish=%.9f BEAT" %
                          (beta, rs, rp))
                elif rs > bestR + 1e-14:
                    best, bestR = hs, rs
                    improved = True
                    print("  [soft b=%.0e] R=%.9f BEAT (raw)" % (beta, rs))

        # Q-sweep (truncated-sup surrogate)
        for c in cs:
            for beta in Qbetas:
                if time.process_time() >= hard - 3.0:
                    break
                fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
                q0 = _Q_value(best, c, beta)
                cap = min(hard - 2.0, time.process_time() + 3.0)
                hq = _lbfgs_log(best, 150, cap, fg=fg)
                q1 = _Q_value(hq, c, beta)
                rq = R_of(hq)
                if rq > bestR + 1e-14 or q1 > q0 * (1 + 1e-4):
                    hp, rp = _polish(hq, min(hard - 1.0,
                                             time.process_time() + 5.0))
                    beat = rp > bestR + 1e-14
                    print("  [Q c=%.2f b=%.0e] Q %.4f->%.4f Rq=%.9f polish=%.9f %s"
                          % (c, beta, q0, q1, rq, rp, "BEAT" if beat else ""))
                    if beat:
                        best, bestR = hp, rp
                        improved = True
                        print("    new best R=%.9f" % bestR)

        if not improved:
            stale += 1
            # fall back to direct exact polish with wider window
            if time.process_time() < hard - 3.0:
                cap = min(hard - 2.0, time.process_time() + 3.0)
                hp = _lbfgs_log(best, 300, cap, fg=_fun_grad)
                rp = R_of(hp)
                if rp > bestR + 1e-13:
                    best, bestR = hp, rp
                    improved = True
                    stale = 0
                    print("    fallback best R=%.9f" % bestR)
            if stale >= 2:
                # perturb: add small noise proportional to local height, then polish
                if time.process_time() < hard - 3.0:
                    rng = np.random.default_rng(sweep)
                    noise = rng.standard_normal(best.size) * 0.02
                    hp = best * np.exp(noise)
                    hp = _rescale(hp)
                    cap = min(hard - 2.0, time.process_time() + 4.0)
                    hp = _lbfgs_log(hp, 200, cap, fg=_fun_grad)
                    rp = R_of(hp)
                    if rp > bestR + 1e-13:
                        best, bestR = hp, rp
                        improved = True
                        stale = 0
                        print("    perturbed best R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

