    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _extend_tail(h, pad):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    act = np.flatnonzero(h > 1e-9 * h.max())
    if act.size == 0:
        act = np.arange(h.size)
    hedgeL = float(np.mean(h[act[:min(32, act.size)]]))
    hedgeR = float(np.mean(h[act[-min(32, act.size):]]))
    if hedgeL <= 0:
        hedgeL = 1e-6 * h.mean()
    if hedgeR <= 0:
        hedgeR = 1e-6 * h.mean()
    rho = 0.05 ** (1.0 / pad)
    left = hedgeL * rho ** np.arange(pad, 0, -1)
    right = hedgeR * rho ** np.arange(1, pad + 1)
    out = np.concatenate((left, h, right))
    return _rescale(np.clip(out, 0, None))


def _refine_peak_tight(h, bestR, deadline, rounds=6):
    """Repeatedly focus L-BFGS on an ever-tighter window around the peak."""
    h = np.clip(h, 0, None)
    best = h.copy()
    for k in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        # progressively tighter window
        tol = 0.9999 - 0.02 * k
        frac = max(0.02, 0.15 - 0.02 * k)
        win = _peak_window(best, tol=tol, pad_frac=frac, extra=64)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5,
                          beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # One base run_cycle to get the reference best.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Experiment: geometrically-decaying tail support extensions ----
    pads = [8000, 16000]
    n_p = len(pads)
    for pi, pad in enumerate(pads):
        now = time.process_time()
        if now >= deadline - 1.5:
            break
        remaining = deadline - 1.5 - now
        per = remaining / max(1, (n_p - pi))
        round_deadline = min(deadline - 1.5, now + per)
        hext = _extend_tail(best, pad)
        r0 = R_of(hext)
        print("extpad pad=%d R0=%.7f N=%d" % (pad, r0, hext.size))
        cur, curR = hext, r0
        ec = 0
        while time.process_time() < round_deadline - 0.5:
            ec += 1
            prevR = curR
            cur, curR, _ = run_cycle(cur, curR, round_deadline - 0.5)
            g = curR - prevR
            print("extpad pad=%d cycle %d R=%.7f dR=%.2e zeros=%.1f%%"
                  % (pad, ec, curR, g, 100.0 * np.mean(cur <= 0)))
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
            if g < 1e-9:
                break

    # ---- Tight peak refinement (new): squeeze peak region harder ----
    if time.process_time() < deadline - 1.0:
        ht, r = _refine_peak_tight(best, bestR, deadline - 1.0)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("tight peak R=%.7f" % bestR)

    # ---- Final peak ladder + polish on best ----
    for frac, extra, beta in [(0.10, 128, 1e8), (0.25, 256, 1e8)]:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.0,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _interp_resample(h, N2):
    """Resample a step function onto N2 steps, preserving the total mass
    (piecewise-constant re-binning, so the shape is preserved as an
    approximation)."""
    N1 = h.size
    if N1 == N2:
        return h.copy()
    # cumulative mass at original step boundaries
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(N2)
    # target boundaries in original-index coordinates
    xs = np.linspace(0.0, N1, N2 + 1)
    cm = np.interp(xs, np.arange(N1 + 1), c)
    out = np.diff(cm)
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- One base run_cycle to get incumbent ----
    if time.process_time() < deadline - 2.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("cycle 1 R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Resample experiment: try coarser resolutions to escape ----
    # a plateau of the fine grid, then refine back.
    resample_targets = [max(2048, best.size // 4),
                        max(4096, best.size // 2)]
    for N2 in resample_targets:
        now = time.process_time()
        if now >= deadline - 4.0:
            break
        if N2 >= best.size:
            continue
        h_r = _interp_resample(best, N2)
        h_r = _rescale(h_r)
        r0 = R_of(h_r)
        print("resample N=%d R0=%.7f" % (N2, r0))
        # optimise at coarse resolution
        cur, curR, _ = run_cycle(h_r, r0, min(deadline - 3.0, now + (deadline - now) * 0.4))
        # refine back to the original resolution
        if time.process_time() < deadline - 2.0:
            h_back = _interp_resample(cur, best.size)
            h_back = _rescale(h_back)
            r1 = R_of(h_back)
            cur2, curR2, _ = run_cycle(h_back, r1, min(deadline - 1.5,
                                                       time.process_time() + (deadline - time.process_time()) * 0.6))
            if curR2 > curR:
                cur, curR = cur2, curR2
        print("resample N=%d R=%.7f dR=%.2e" % (N2, curR, curR - bestR))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    # ---- Leftover: run_cycle loop + peak ladder on winner ----
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        prevR = bestR
        best, bestR, drefine = run_cycle(best, bestR, deadline - 1.5)
        print("cycle %d R=%.7f dR=%.2e" % (cycle, bestR, bestR - prevR))
        if bestR - prevR < 1e-13 and cycle > 1:
            break

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

