    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _extend_tail(h, pad):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    act = np.flatnonzero(h > 1e-9 * h.max())
    if act.size == 0:
        act = np.arange(h.size)
    hedgeL = float(np.mean(h[act[:min(32, act.size)]]))
    hedgeR = float(np.mean(h[act[-min(32, act.size):]]))
    if hedgeL <= 0:
        hedgeL = 1e-6 * h.mean()
    if hedgeR <= 0:
        hedgeR = 1e-6 * h.mean()
    rho = 0.05 ** (1.0 / pad)
    left = hedgeL * rho ** np.arange(pad, 0, -1)
    right = hedgeR * rho ** np.arange(1, pad + 1)
    out = np.concatenate((left, h, right))
    return _rescale(np.clip(out, 0, None))


def _pad_continuation(h, pad):
    """Pad both ends by `pad` steps with heights = edge_height *
    exp(-d/(0.10*N_active)). Continuation, not epsilon filler."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    act = np.flatnonzero(h > 1e-9 * h.max())
    if act.size == 0:
        act = np.arange(h.size)
    n_active = max(1, act.size)
    scale = 0.10 * n_active
    hedgeL = float(np.mean(h[act[:min(32, act.size)]]))
    hedgeR = float(np.mean(h[act[-min(32, act.size):]]))
    if hedgeL <= 0:
        hedgeL = 1e-6 * h.mean()
    if hedgeR <= 0:
        hedgeR = 1e-6 * h.mean()
    d = np.arange(pad, 0, -1, dtype=float)
    left = hedgeL * np.exp(-d / scale)
    d2 = np.arange(1, pad + 1, dtype=float)
    right = hedgeR * np.exp(-d2 / scale)
    out = np.concatenate((left, h, right))
    return _rescale(np.clip(out, 0, None))


def _envelope(h, alpha, frac):
    """Mass-preserving outer envelope: taper the outer `frac` fraction of
    the active support on each side with a smooth cosine-like falloff,
    then renormalise mass. alpha controls sharpness."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    act = np.flatnonzero(h > 1e-9 * h.max())
    if act.size == 0:
        return h
    lo = act.min()
    hi = act.max()
    span = hi - lo + 1
    m = max(1, int(frac * span))
    out = h.copy()
    # left taper
    if m < span:
        idx = np.arange(lo, lo + m)
        t = np.arange(m, dtype=float) / max(1, m - 1)  # 0..1 from outer to inner
        w = 1.0 - np.exp(-alpha * t)
        w = w / max(w.max(), 1e-12)
        out[idx] *= w
        idx2 = np.arange(hi - m + 1, hi + 1)
        t2 = np.arange(m, dtype=float) / max(1, m - 1)
        w2 = 1.0 - np.exp(-alpha * t2)
        w2 = w2 / max(w2.max(), 1e-12)
        out[idx2] *= w2[::-1]
    # preserve mass
    s0 = h.sum()
    s1 = out.sum()
    if s1 > 0:
        out *= s0 / s1
    return _rescale(np.clip(out, 0, None))


def _band01(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= 0.999 * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # One base run_cycle to get the reference best.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Experiment: alternating continuation-pad + envelope rounds ----
    for r in range(1, 4):
        now = time.process_time()
        if now >= deadline - 4.0:
            break
        remaining = deadline - 4.0 - now
        round_deadline = now + remaining / (4 - r)
        prevR = bestR

        # (a) continuation pad
        hpad = _pad_continuation(best, 8000)
        # (b) envelope, alpha=2 odd rounds, 8 even
        alpha = 2.0 if (r % 2 == 1) else 8.0
        henv = _envelope(hpad, alpha, 0.01)
        # (c) rescale + run_cycle
        henv = _rescale(henv)
        cur, curR = henv, R_of(henv)
        ec = 0
        while time.process_time() < round_deadline - 0.5:
            ec += 1
            prev = curR
            cur, curR, _ = run_cycle(cur, curR, round_deadline - 0.5)
            if curR - prev < 1e-9:
                break
        if curR > bestR + 1e-9:
            best, bestR = cur.copy(), curR
        dR = bestR - prevR
        print("round %d alpha=%.1f R=%.7f dR=%.2e zeros=%.1f%% band01=%.2f%%"
              % (r, alpha, bestR, dR, 100.0 * np.mean(best <= 0),
                 100.0 * _band01(best)))

    # ---- Closing polish ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.8, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.6:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), 100.0 * _band01(best)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _tilt(C, delta, rng):
    n = C.size // 2
    e = delta * (2.0 * rng.random(n) - 1.0)
    h2 = C.copy()
    h2[0::2] = C[0::2] * (1.0 + e)
    h2[1::2] = C[1::2] * (1.0 - e)
    h2 = np.clip(h2, 0, None)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Build 2x staircase ----
    C = np.repeat(start_best, 2)
    C = _rescale(C)
    C_R = R_of(C)
    print("staircase N=%d R=%.7f" % (C.size, C_R))

    # ---- Untilted control ----
    if time.process_time() < deadline - 6.0:
        ctl_deadline = min(deadline - 6.0, time.process_time() + 8.0)
        hc, rc, _ = run_cycle(C.copy(), C_R, ctl_deadline)
        print("control R=%.7f dR=%.2e" % (rc, rc - bestR))
        if rc > bestR + 1e-13:
            best, bestR = hc.copy(), rc

    # ---- Tilted candidates ----
    deltas = [0.002, 0.01, 0.03]
    n_c = len(deltas)
    for ci, delta in enumerate(deltas):
        now = time.process_time()
        if now >= deadline - 4.0:
            break
        remaining = deadline - 4.0 - now
        per = remaining / max(1, (n_c - ci))
        tdead = min(deadline - 4.0, now + per)
        h2 = _tilt(C, delta, rng)
        r0 = R_of(h2)
        print("tilt delta=%.3f R0=%.7f" % (delta, r0))
        h2 = _lbfgs_all_pos(h2, 400, tdead)
        r1 = R_of(h2)
        h2, r2, _ = run_cycle(h2, r1, tdead)
        asym = np.mean(np.abs(h2[0::2] - h2[1::2])) / max(1e-12, h2.mean())
        print("tilt delta=%.3f R=%.7f dR=%.2e asym=%.2e"
              % (delta, r2, r2 - bestR, asym))
        if r2 > bestR + 1e-13:
            best, bestR = h2.copy(), r2

    # ---- Leftover polish on winner ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 1500, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 1.0:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    # ---- One more 2x refinement round if enough time ----
    if time.process_time() < deadline - 8.0:
        C2 = _rescale(np.repeat(best, 2))
        r_c2 = R_of(C2)
        print("round2 staircase N=%d R=%.7f" % (C2.size, r_c2))
        rem = deadline - 2.0 - time.process_time()
        if rem > 2.0:
            tdead = min(deadline - 2.0, time.process_time() + rem * 0.5)
            h3 = _tilt(C2, 0.01, rng)
            r0 = R_of(h3)
            h3 = _lbfgs_all_pos(h3, 200, tdead)
            r1 = R_of(h3)
            h3, r2, _ = run_cycle(h3, r1, tdead)
            print("round2 tilt R=%.7f dR=%.2e" % (r2, r2 - bestR))
            if r2 > bestR + 1e-13:
                best, bestR = h3.copy(), r2
        if time.process_time() < deadline - 1.0:
            ht = _lbfgs_all_pos(best, 800, deadline - 0.5)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def run_cycle(best, bestR, deadline):
    # Smoothed homotopy then exact.
    for beta in (16, 64, 256, 1024):
        if time.process_time() > deadline - 4.0:
            return best, bestR
        ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ht = _lbfgs_all_pos(best, 800, deadline - 1.0, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-13:
        best, bestR = ht.copy(), r
    # Peak window polish.
    for tol, padf, extra in ((0.999, 0.6, 512), (0.9999, 0.3, 256), (1.0, 0.1, 128)):
        if time.process_time() > deadline - 2.0:
            break
        win = _peak_window(best, tol, padf, extra)
        ht = _lbfgs_block(best, win, 400, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Try a finer resolution rebuild of the start (prolongate mass).
    if h.size < 32768:
        h32 = _rescale(_prolongate_mass(h, 32768))
        R32 = R_of(h32)
        print("prolongated N=32768 R=%.6f" % R32)
        if R32 > best_R:
            best_R, best_h = R32, h32.copy()

    # First refinement pass on working point.
    cur_h = best_h.copy()
    cur_R = best_R
    cur_h, cur_R = run_cycle(cur_h, cur_R, deadline)
    if cur_R > best_R:
        best_R, best_h = cur_R, cur_h.copy()
    print("after cycle R=%.6f" % best_R)

    # Multi-resolution: try a fresh coarser reparametrization to escape.
    # Block-average to N/2 then prolongate, refine, and compare.
    if best_h.size >= 1024 and time.process_time() < deadline - 10.0:
        N = best_h.size
        half = N // 2
        hb = best_h[:2 * half].reshape(half, 2).mean(axis=1)
        hb = _rescale(_prolongate_mass(hb, N))
        Rb = R_of(hb)
        if Rb > cur_R - 0.005:
            hb2, Rb2 = run_cycle(hb, Rb, deadline)
            print("coarse-restart R=%.6f" % Rb2)
            if Rb2 > best_R:
                best_R, best_h = Rb2, hb2.copy()
                cur_h, cur_R = hb2, Rb2

    # Perturb-and-refine restarts within peak window.
    rng = np.random.default_rng(2024)
    it = 0
    N = best_h.size
    while time.process_time() < deadline - 3.0:
        it += 1
        amp = 0.03 + 0.08 * rng.random()
        win = _peak_window(cur_h, 0.9995, 0.4, 256)
        pert = cur_h.copy()
        pert[win] = pert[win] * np.exp(amp * rng.standard_normal(win.size))
        pert = _rescale(np.maximum(pert, 0))
        hp = _lbfgs_block(pert, win, 300, deadline - 1.0, beta=0.0)
        r = R_of(hp)
        if r > cur_R:
            cur_h, cur_R = hp, r
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()
        # occasionally do a full refinement
        if it % 4 == 0 and time.process_time() < deadline - 8.0:
            cur_h, cur_R = run_cycle(cur_h, cur_R, deadline)
            if cur_R > best_R:
                best_R, best_h = cur_R, cur_h.copy()
        print("perturb#%d R=%.6f best=%.6f" % (it, cur_R, best_R))

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # Main strategy: multi-scale search. The prior program was stuck near a local
    # optimum. Try: (1) downsample-and-refine at coarser grids then upsample,
    # (2) full block refinement on the peak region with p-norm continuation.
    # (1) Multi-scale: create a coarser representation, optimize there, upsample.
    def _downsample(h, factor):
        n = h.size
        pad = (-n) % factor
        if pad:
            h = np.concatenate([h, np.zeros(pad)])
        return h.reshape(-1, factor).sum(axis=1)

    def _upsample(h, factor):
        return np.repeat(h, factor)

    # Coarse-grained optimization pass at multiple scales
    for factor in (8, 4, 2):
        if time.process_time() >= deadline - 8.0:
            break
        try:
            hc = _downsample(bestH, factor)
            hc = _rescale(hc)
            sub = min(deadline - 4.0, time.process_time() + 5.0)
            hco = _lbfgs_log(hc, 200, sub)
            rco = R_of(hco)
            if rco > bestRH - 1e-6:
                hu = _upsample(hco, factor)
                # trim to original size
                if hu.size > bestH.size:
                    hu = hu[:bestH.size]
                elif hu.size < bestH.size:
                    hu = np.concatenate([hu, np.zeros(bestH.size - hu.size)])
                hu = _rescale(hu)
                sub = min(deadline - 3.0, time.process_time() + 5.0)
                hu2 = _lbfgs_log(hu, 150, sub)
                ru = R_of(hu2)
                if ru > bestRH + 1e-13:
                    bestH, bestRH = hu2.copy(), ru
                print("  scale1/%d R=%.7f (best %.7f)" % (factor, ru, bestRH))
        except Exception:
            pass

    # (2) Peak block refinement with p-norm continuation
    ladder = (2, 4, 8, 16, 32, 64, 128)
    it = 0
    while time.process_time() < deadline - 3.0:
        improved = False
        for p in ladder:
            if time.process_time() >= deadline - 2.5:
                break
            sub = min(deadline - 1.5, time.process_time() + 4.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(bestH, 100, sub, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
                improved = True

        # Peak-local block polish
        if time.process_time() < deadline - 2.0:
            lo, hi = _peak_region(bestH, tol=0.9995)
            span = hi - lo
            pad = max(256, int(span * 0.5))
            lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
            if hi2 > lo2:
                free = np.arange(lo2, hi2 + 1)
                sub = min(deadline - 1.0, time.process_time() + 3.0)
                hp = _lbfgs_block(bestH, free, 120, sub)
                rp = R_of(hp)
                if rp > bestRH + 1e-13:
                    bestH, bestRH = hp.copy(), rp
                    improved = True

        print("  iter %d p-ladder done R=%.7f" % (it, bestRH))
        it += 1
        if not improved and time.process_time() > deadline - 5.0:
            break

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

