    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- New idea: Lanczos on the exact FD Hessian to expose negative curvature ----

def _hessvec_operator(h, free, beta=1e6):
    """Return function v -> H v via central differences of the gradient of
    _fun_grad_beta in variables x = log(h[free] + eps)."""
    h = np.clip(h, 0, None)
    eps = max(1e-12, 1e-9 * h.mean())
    hf = h[free]
    scale = max(1e-12, np.max(np.abs(hf)))
    d = 1e-6 * scale

    def grad_x(x):
        hh = h.copy()
        hh[free] = np.exp(np.clip(x, -60.0, 60.0)) - eps
        hh = np.clip(hh, 0.0, None)
        _, g = _fun_grad_beta(hh, beta)
        # chain rule: d/dx = h_free * d/dh
        return g[free] * np.maximum(hh[free], 0.0)

    x0 = np.log(np.maximum(hf, 0.0) + eps)

    def Hv(v):
        v = np.asarray(v, dtype=float)
        nv = np.linalg.norm(v)
        if nv <= 0:
            return np.zeros_like(v)
        u = v / nv
        gp = grad_x(x0 + d * u)
        gm = grad_x(x0 - d * u)
        return nv * (gp - gm) / (2.0 * d)

    return Hv


def _lanczos(Hv, n, m, seed=12345):
    rng = np.random.RandomState(seed)
    q = rng.randn(n)
    q /= np.linalg.norm(q)
    Q = np.zeros((m, n))
    alpha = np.zeros(m)
    beta = np.zeros(m)
    Q[0] = q
    q_prev = np.zeros(n)
    b_prev = 0.0
    for j in range(m):
        w = Hv(Q[j])
        a = np.dot(w, Q[j])
        alpha[j] = a
        w = w - a * Q[j] - b_prev * q_prev
        # full reorthogonalization (small m)
        for k in range(j + 1):
            w -= np.dot(w, Q[k]) * Q[k]
        b = np.linalg.norm(w)
        beta[j] = b
        if j + 1 < m:
            if b < 1e-14:
                # breakdown: fill remaining with random orthonormal
                v = rng.randn(n)
                for k in range(j + 1):
                    v -= np.dot(v, Q[k]) * Q[k]
                nv = np.linalg.norm(v)
                if nv < 1e-14:
                    break
                Q[j + 1] = v / nv
                b_prev = 0.0
                q_prev = np.zeros(n)
            else:
                Q[j + 1] = w / b
                q_prev = Q[j]
                b_prev = b
    k = j + 1
    T = np.diag(alpha[:k])
    if k > 1:
        T += np.diag(beta[:k - 1], 1) + np.diag(beta[:k - 1], -1)
    lam, V = np.linalg.eigh(T)
    # Ritz vectors in full space
    Ritz = V.T @ Q[:k]
    return lam, Ritz


def _try_negative_curvature(best, bestR, deadline, seed=12345):
    """Run Lanczos on the FD Hessian over a peak window; if a genuinely
    negative Ritz value appears, try moving along its Ritz vector."""
    free = _peak_window(best, tol=0.999, pad_frac=0.10, extra=128)
    if free.size > 6000:
        order = np.argsort(-best[free])
        free = np.sort(free[order[:6000]])
    if free.size < 4:
        return best, bestR, False
    Hv = _hessvec_operator(best, free, beta=1e6)
    try:
        lam, Ritz = _lanczos(Hv, free.size, 20, seed=seed)
    except Exception:
        return best, bestR, False
    lam_min = float(lam.min())
    lam_max = float(lam.max())
    print("lanczos lam_min=%.3e lam_max=%.3e" % (lam_min, lam_max))
    if not (lam_min < -1e-6 * abs(lam_max)):
        return best, bestR, False
    # try the lowest (most negative) plus next two
    order = np.argsort(lam)
    improved = False
    for ridx in order[:3]:
        if time.process_time() >= deadline - 1.5:
            break
        v = Ritz[ridx]
        vmax = np.max(np.abs(v))
        if vmax <= 0:
            continue
        vn = v / vmax
        for sign in (1.0, -1.0):
            for t in (0.02, 0.05, 0.1, 0.2, 0.4):
                if time.process_time() >= deadline - 1.5:
                    break
                cand = best.copy()
                cand[free] = cand[free] * np.exp(sign * t * vn)
                cand = _rescale(cand)
                cand2 = _lbfgs_block(cand, free, 120, deadline - 1.5, beta=0.0)
                r = R_of(cand2)
                print("  ritz %d sign %+d t=%.2f R=%.7f" % (ridx, int(sign), t, r))
                if r > bestR + 1e-13:
                    best, bestR = cand2, r
                    improved = True
                    break
            if improved:
                break
        if improved:
            break
    return best, bestR, improved


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: full L-BFGS polish of the start.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2 (NEW): Lanczos on exact FD Hessian to expose negative curvature.
    n_lanc = 0
    while time.process_time() < deadline - 2.5 and n_lanc < 3:
        before = bestR
        ht, rt, improved = _try_negative_curvature(best, bestR, deadline, seed=12345 + n_lanc)
        n_lanc += 1
        if improved and rt > bestR + 1e-13:
            best, bestR = ht, rt
            best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
            print("lanczos round %d: R=%.7f (dR=%.2e)" % (n_lanc, bestR, bestR - before))
        else:
            print("lanczos round %d: no improvement (R=%.7f)" % (n_lanc, bestR))
            break

    # Phase 3: final full L-BFGS polish.
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
