    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def _downsample(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at) * (M / N)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # New idea 1: round-trip through a coarser grid to smooth out discretisation
    # artifacts, then refine. Coarsening + re-fining can escape local optima
    # that pure upsample+refine cannot.
    n0 = base.size
    if time.process_time() < hard_end - 8.0:
        for down_target in (max(64, n0 // 4), max(64, n0 // 2)):
            if time.process_time() >= hard_end - 6.0:
                break
            h_down = _downsample(base, down_target)
            h_down = _lbfgs_log(h_down, maxiter=800, deadline=hard_end - 2.0)
            h_up = _prolongate(h_down, n0)
            h_up = _lbfgs_log(h_up, maxiter=800, deadline=hard_end - 1.0)
            r_up = R_of(h_up)
            print("downup %d->%d R=%.6f" % (down_target, n0, r_up))
            if r_up > base_r - 1e-9:
                _consider(h_up, r_up)

    # New idea 2: upsample to 2x grid and refine.
    n_up = min(1000000, max(n0 * 2, n0))
    if n_up != n0 and time.process_time() < hard_end - 6.0:
        h_up = _prolongate(base, n_up)
        h_up = _lbfgs_log(h_up, maxiter=800, deadline=hard_end - 3.0)
        r_up = R_of(h_up)
        print("upsample %d R=%.6f (base %.6f)" % (n_up, r_up, base_r))
        if r_up > base_r - 1e-9:
            _consider(h_up, r_up)

    print("experiment R=%.6f N=%d | base R=%.6f N=%d"
          % (best_r, best.size, base_r, base.size))

    # Continue local refinement on `best` until the deadline.
    try:
        cur = best.copy()
        cur_r = best_r
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            if R_of(h) > cur_r + 1e-12:
                cur, cur_r = h, R_of(h)
                _consider(h, cur_r)
            else:
                # no progress this round: try a coarsen/refine kick
                if time.process_time() < hard_end - 4.0:
                    nd = max(64, cur.size // 3)
                    hk = _downsample(cur, nd)
                    hk = _lbfgs_log(hk, maxiter=400, deadline=hard_end - 1.0)
                    hk = _prolongate(hk, cur.size)
                    hk = _lbfgs_log(hk, maxiter=400, deadline=hard_end - 0.5)
                    if R_of(hk) > cur_r + 1e-12:
                        cur, cur_r = hk, R_of(hk)
                        _consider(hk, cur_r)
                    else:
                        break
            if time.process_time() >= hard_end - 1.0:
                break
        print("finish R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_clip(h, c):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    thr = c * mx
    d = np.where(Lf > thr, Lf - thr, 0.0)
    pen = np.sum(d * d)
    scale = 1.0 / (mx * mx + 1e-30)
    gLf = -dq / num + 2.0 * d * scale
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + pen * scale
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_clip(h0, free, maxiter, deadline, c):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_clip(hh, c)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _polish(h, deadline):
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_all_pos(h, 400, deadline - 0.5, beta=0.0)
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, tol=0.99, pad_frac=0.4, extra=256)
        h = _lbfgs_block(h, win, 300, deadline - 0.5, beta=1e7)
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, tol=0.99, pad_frac=0.4, extra=256)
        h = _lbfgs_block(h, win, 200, deadline - 0.5, beta=0.0)
    if time.process_time() < deadline - 0.5:
        h = _refine_knots(h, 300, deadline - 0.5)
    return h


def _plateau_clip(h, deadline, cs=(0.85, 0.90, 0.94, 0.97, 0.99)):
    """Flatten the top of f*f with a clipped-L2 penalty, then sharpen.

    The known obstruction to a larger R is a sharp peak of f*f: the L_inf
    term is dominated by a narrow spike while the L2 mass sits below it.
    Penalising knots above c*max flattens the spike; a subsequent sharp
    (beta) pass restores a genuine max while keeping the wider plateau.
    """
    best = h.copy()
    bestR = R_of(best)
    win = _peak_window(h, tol=0.98, pad_frac=0.6, extra=512)
    for c in cs:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block_clip(best, win, 200, deadline - 0.5, c)
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(ht, win, 150, deadline - 0.5, beta=1e7)
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(ht, win, 150, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _move_m1(best, rng):
    n = best.size
    w = int(rng.uniform(0.02, 0.15) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    h[win] = h[win] * np.exp(0.05 * rng.standard_normal(w))
    return h, win


def _move_m2(best, rng):
    _, g = _fun_grad(best)
    zeros = np.flatnonzero(best <= 0)
    if zeros.size == 0:
        return None, None
    order = np.argsort(g[zeros])[::-1]
    k = min(int(rng.choice([16, 64, 256])), zeros.size)
    pick = zeros[order[:k]]
    h = best.copy()
    h[pick] += 1e-3 * best.mean()
    return h, pick


def _move_m3(best, rng):
    n = best.size
    P = min(int(rng.choice([1000, 3000])), 200000)
    pad = np.full(P, 1e-3 * best.mean())
    if rng.random() < 0.5:
        h = np.concatenate((pad, best)); touched = np.arange(0, P)
    else:
        h = np.concatenate((best, pad)); touched = np.arange(n, n + P)
    return _rescale(h), touched


def _move_m4(best, rng):
    n = best.size
    w = max(1, int(0.10 * n))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    t = np.linspace(0, np.pi, w)
    h[win] = h[win] + 0.02 * best.mean() * np.sin(t)
    return h, win


def _halo(touched, n, halo=64):
    if touched is None or touched.size == 0:
        return np.arange(n)
    lo = max(0, int(touched.min()) - halo)
    hi = min(n - 1, int(touched.max()) + halo)
    return np.arange(lo, hi + 1)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    for frac, extra, beta in [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
                              (0.40, 256, 1e8), (0.60, 512, 1e8)]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = np.sqrt(i + 1.0) - np.sqrt(i)
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: squeeze the peak with clipped-L2 flattening.
    if time.process_time() < deadline - 2.0:
        hc, rc = _plateau_clip(best, deadline - 1.5)
        print("clip R=%.7f" % rc)
        if rc > bestR + 1e-13:
            best, bestR = hc.copy(), rc

    # Phase B: standard cycle.
    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase C: hop loop.
    hop = 0; acc = 0
    moves = [_move_m1, _move_m2, _move_m3, _move_m4]
    while time.process_time() < deadline - 1.6:
        hop += 1
        mv = moves[int(rng.integers(0, 4))]
        try:
            h_try, touched = mv(best, rng)
        except Exception:
            continue
        if h_try is None:
            continue
        h_try = np.clip(h_try, 0, None)
        if h_try.sum() <= 0:
            continue
        free = _halo(touched, h_try.size, 64)
        ht = _lbfgs_block(h_try, free, 150, deadline - 1.0, beta=1e7)
        if time.process_time() < deadline - 1.0:
            pw = _peak_window(ht, pad_frac=0.15, extra=128)
            ht = _lbfgs_block(ht, pw, 80, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            acc += 1
        if hop % 5 == 0:
            print("hop %d acc %d bestR=%.7f" % (hop, acc, bestR))

    print("hops done: %d accepted %d bestR=%.7f" % (hop, acc, bestR))

    # Phase D: final polish + a late clip pass.
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.6:
        hc, rc = _plateau_clip(best, deadline - 0.5)
        if rc > bestR + 1e-13:
            best, bestR = hc.copy(), rc
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _move_m1(best, rng):
    n = best.size
    w = int(rng.uniform(0.02, 0.15) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    z = rng.standard_normal(w)
    h[win] = h[win] * np.exp(0.05 * z)
    return h, win


def _move_m2(best, rng):
    _, g = _fun_grad(best)
    zeros = np.flatnonzero(best <= 0)
    if zeros.size == 0:
        return None, None
    gz = g[zeros]
    order = np.argsort(gz)[::-1]
    k = int(rng.choice([16, 64, 256]))
    k = min(k, zeros.size)
    pick = zeros[order[:k]]
    h = best.copy()
    amp = 1e-3 * best.mean()
    h[pick] = h[pick] + amp
    return h, pick


def _move_m3(best, rng):
    n = best.size
    P = int(rng.choice([1000, 3000]))
    P = min(P, 200000)
    amp = 1e-3 * best.mean()
    pad = np.full(P, amp)
    if rng.random() < 0.5:
        h = np.concatenate((pad, best))
        touched = np.arange(0, P)
    else:
        h = np.concatenate((best, pad))
        touched = np.arange(n, n + P)
    h = _rescale(h)
    return h, touched


def _move_m4(best, rng):
    n = best.size
    w = max(1, int(0.10 * n))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    amp = 0.02 * best.mean()
    t = np.linspace(0, np.pi, w)
    h[win] = h[win] + amp * np.sin(t)
    return h, win


def _halo(touched, n, halo=64):
    if touched is None or touched.size == 0:
        return np.arange(n)
    lo = max(0, int(touched.min()) - halo)
    hi = min(n - 1, int(touched.max()) + halo)
    return np.arange(lo, hi + 1)


def _refine4(h, d=0.02):
    s = np.array([1.0, -1.0, 1.0, -1.0])
    h = np.asarray(h, dtype=float)
    n = h.size
    out = np.empty(4 * n, dtype=float)
    for r in range(4):
        out[r::4] = h * (1.0 + d * s[r])
    out = np.clip(out, 0, None)
    return _rescale(out)


def _report(tag, h, R, t0):
    print("%s R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%) [%.1fs]" %
          (tag, R, h.size, 100.0 * np.mean(h <= 0),
           100.0 * _band_frac(h, 0.001), 100.0 * _band_frac(h, 0.01),
           time.process_time() - t0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    _report("base", best, bestR, t0)

    # (a) 4x refinement with antisymmetric split
    if time.process_time() < deadline - 1.5:
        h4 = _refine4(best, d=0.02)
        r4 = R_of(h4)
        _report("refine4", h4, r4, t0)
        # accept the 4x version as the working point regardless (it's a
        # different resolution), but track best separately
        work = h4
        workR = r4
    else:
        work = best.copy()
        workR = bestR

    # (b) one run_cycle at 4x
    if time.process_time() < deadline - 1.5:
        work, workR, _ = run_cycle(work, workR, deadline - 1.5)
        _report("cycle4x", work, workR, t0)
        if workR > bestR + 1e-13:
            best, bestR = work.copy(), workR

    # (c) beta ladder at 4x
    for beta in [1e4, 1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 1.6:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 1.6, beta=beta)
        r = R_of(ht)
        if r > workR + 1e-13:
            work, workR = ht.copy(), r
        if time.process_time() < deadline - 1.6:
            ht2 = _lbfgs_all_pos(work, 200, deadline - 1.6, beta=0.0)
            r2 = R_of(ht2)
            if r2 > workR + 1e-13:
                work, workR = ht2.copy(), r2
        _report("beta%.0e" % beta, work, workR, t0)
        if workR > bestR + 1e-13:
            best, bestR = work.copy(), workR

    # (d) hop loop from p1043
    hop = 0
    acc = 0
    moves = [_move_m1, _move_m2, _move_m3, _move_m4]
    while time.process_time() < deadline - 1.6:
        hop += 1
        mv = moves[int(rng.integers(0, 4))]
        try:
            h_try, touched = mv(work, rng)
        except Exception:
            h_try, touched = None, None
        if h_try is None:
            continue
        h_try = np.clip(h_try, 0, None)
        if h_try.sum() <= 0:
            continue
        n = h_try.size
        free = _halo(touched, n, 64)
        ht = _lbfgs_block(h_try, free, 150, deadline - 1.0, beta=1e7)
        if time.process_time() < deadline - 1.0:
            pw = _peak_window(ht, pad_frac=0.15, extra=128)
            ht = _lbfgs_block(ht, pw, 80, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > workR + 1e-13:
            work, workR = ht.copy(), r
            acc += 1
            if workR > bestR + 1e-13:
                best, bestR = work.copy(), workR
        if hop % 5 == 0:
            print("hop %d acc %d workR=%.7f bestR=%.7f" % (hop, acc, workR, bestR))

    print("hops done: %d accepted %d workR=%.7f bestR=%.7f" % (hop, acc, workR, bestR))

    # (e) final run_cycle
    if time.process_time() < deadline - 1.0:
        work, workR, _ = run_cycle(work, workR, deadline - 1.0)
        _report("final cycle", work, workR, t0)
        if workR > bestR + 1e-13:
            best, bestR = work.copy(), workR
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(work, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > workR + 1e-13:
            work, workR = ht.copy(), r
            if workR > bestR + 1e-13:
                best, bestR = work.copy(), workR

    _report("final", best, bestR, t0)

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if workR > start_bestR - 1e-6 and work.size != start_best.size:
        out["alternative"] = work
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 800, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for (frac, extra, beta) in [(0.05, 64, 1e7), (0.10, 64, 1e8),
                                    (0.25, 128, 1e8), (0.40, 256, 1e8),
                                    (0.60, 512, 1e8)]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _window_polish_peak(best, deadline - 2.0, frac, extra,
                                     maxiter=300, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_log(best, 300, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, N))

    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 4000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


# ---------- two-window mass transfer ----------

def _apply_transfer(h, a1, b1, a2, b2, alpha):
    hn = h.copy()
    m1 = h[a1:b1].sum()
    m2 = h[a2:b2].sum()
    if m1 <= 0 or m2 <= 0:
        return None
    hn[a1:b1] = h[a1:b1] * (1.0 + alpha)
    hn[a2:b2] = h[a2:b2] * (1.0 - alpha * m1 / m2)
    if np.any(hn < 0):
        return None
    return hn


def _best_alpha(h, a1, b1, a2, b2, lo=-0.45, hi=0.45, iters=20):
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    c = hi - gr * (hi - lo)
    d = lo + gr * (hi - lo)
    hc = _apply_transfer(h, a1, b1, a2, b2, c)
    hd = _apply_transfer(h, a1, b1, a2, b2, d)
    fc = R_of(hc) if hc is not None else -1.0
    fd = R_of(hd) if hd is not None else -1.0
    for _ in range(iters):
        if fc > fd:
            hi = d; d = c; fd = fc
            c = hi - gr * (hi - lo)
            hc = _apply_transfer(h, a1, b1, a2, b2, c)
            fc = R_of(hc) if hc is not None else -1.0
        else:
            lo = c; c = d; fc = fd
            d = lo + gr * (hi - lo)
            hd = _apply_transfer(h, a1, b1, a2, b2, d)
            fd = R_of(hd) if hd is not None else -1.0
    alpha = 0.5 * (lo + hi)
    ha = _apply_transfer(h, a1, b1, a2, b2, alpha)
    if ha is None:
        return 0.0, h
    return alpha, ha


# ---------- coordinate-descent on the knot-flatness: adaptive beta schedule ----------

def _polish(h, bestR, deadline, verbose=True):
    """Aggressive multi-scale polish. Returns (h, R)."""
    n = h.size
    # 1) peak windows at decreasing fractions
    for frac in [0.20, 0.10, 0.05, 0.025, 0.012]:
        if time.process_time() >= deadline - 0.5:
            return h, bestR
        free = _peak_window(h, frac=frac)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(h, free, 150, cap, beta=0.0)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            h, bestR = hb, rb
            if verbose:
                print("    polish frac=%.3f R=%.9f" % (frac, bestR))
    # 2) capped-beta smoothing to lower the peak (soften max)
    for beta in [200.0, 500.0, 1500.0, 4000.0]:
        if time.process_time() >= deadline - 0.5:
            return h, bestR
        cap = min(deadline - 0.3, time.process_time() + 1.2)
        hb = _lbfgs_block(h, np.arange(n), 120, cap, beta=beta)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            h, bestR = hb, rb
            if verbose:
                print("    beta=%.0f R=%.9f" % (beta, bestR))
    # 3) exact R polish, full vector
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.5)
        hb = _lbfgs_block(h, np.arange(n), 200, cap, beta=0.0)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            h, bestR = hb, rb
            if verbose:
                print("    full R=%.9f" % bestR)
    return h, bestR


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Immediately polish the start with the aggressive schedule -- this is the
    # main new idea: multi-scale L-BFGS with a beta-continuation path.
    best, bestR = _polish(best, bestR, deadline, verbose=True)
    print("after polish R=%.9f" % bestR)

    # Then keep polishing until time runs out (no scan: polish dominates).
    while time.process_time() < deadline - 1.0:
        prevR = bestR
        best, bestR = _polish(best, bestR, deadline, verbose=False)
        if bestR <= prevR + 1e-14:
            break

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

