    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _interp_resample(h, N2):
    N1 = h.size
    if N1 == N2:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(N2)
    xs = np.linspace(0.0, N1, N2 + 1)
    cm = np.interp(xs, np.arange(N1 + 1), c)
    return np.diff(cm)


def _upsample_smooth(h, N2):
    """Refine resolution: linear interp of the cumulative then smooth slightly."""
    N1 = h.size
    if N1 == N2:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, N1, N2 + 1)
    cm = np.interp(xs, np.arange(N1 + 1), c)
    out = np.diff(cm)
    # tiny smoothing to reduce staircase artifacts
    k = np.array([1.0, 2.0, 1.0]); k /= k.sum()
    out = np.convolve(out, k, mode='same')
    return np.clip(out, 0, None)


def _perturb_local(h, rng, scale=0.02, frac=0.1):
    out = h.copy()
    n = out.size
    m = max(1, int(frac * n))
    idx = rng.integers(0, n, size=m)
    factors = np.exp(rng.normal(0.0, scale, size=m))
    out[idx] *= factors
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(20240917)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Cycle 1
    if time.process_time() < deadline - 2.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("cycle 1 R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # NEW IDEA: resolution refinement (upsample) then re-optimise.
    # The plateau is resolution-limited; a finer grid can capture sharper
    # features near the peak and in low-amplitude tails.
    for factor in [2, 2]:
        now = time.process_time()
        if now >= deadline - 8.0:
            break
        N2 = min(1000000, best.size * factor)
        if N2 <= best.size:
            continue
        h_up = _upsample_smooth(best, N2)
        h_up = _rescale(h_up)
        r0 = R_of(h_up)
        sub_deadline = min(deadline - 5.0, now + (deadline - now) * 0.45)
        cur, curR = run_cycle(h_up, r0, sub_deadline)
        print("upsample N=%d R=%.7f dR=%.2e" % (N2, curR, curR - bestR))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
        else:
            break

    # Perturbation escape attempts
    attempt = 0
    while time.process_time() < deadline - 4.0:
        attempt += 1
        scale = [0.005, 0.02, 0.05, 0.1][(attempt - 1) % 4]
        frac = [0.05, 0.1, 0.2, 0.4][(attempt - 1) % 4]
        cand = _perturb_local(best, rng, scale=scale, frac=frac)
        r0 = R_of(cand)
        if r0 <= 0:
            continue
        ht = _lbfgs_all_pos(cand, 200, deadline - 3.0, beta=0.0)
        r = R_of(ht)
        if r > bestR - 5e-4 and time.process_time() < deadline - 6.0:
            ht2, r2 = run_cycle(ht, r, min(deadline - 2.0,
                                           time.process_time() + (deadline - time.process_time()) * 0.5))
            if r2 > r:
                ht, r = ht2, r2
        print("perturb #%d scale=%.3f frac=%.2f R=%.7f dR=%.2e"
              % (attempt, scale, frac, r, r - bestR))
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # Leftover cycles
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        prevR = bestR
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("cycle %d R=%.7f dR=%.2e" % (cycle, bestR, bestR - prevR))
        if bestR - prevR < 1e-13 and cycle > 1:
            break

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- NEW: targeted knot-alignment / resolution change ----

def _upsample2(h):
    """Insert one interpolated step between every pair: doubles resolution."""
    n = h.size
    out = np.empty(2 * n, dtype=float)
    out[0::2] = h
    out[1:-1:2] = 0.5 * (h[:-1] + h[1:])
    out[-1] = h[-1]
    return out


def _smooth_shift(h, shift, width):
    """Move a block of mass by `shift` steps (rigid translation of one bump)."""
    n = h.size
    if shift == 0:
        return h.copy()
    out = h.copy()
    lo = max(0, min(0, -shift))
    idx = np.arange(n)
    src = idx - shift
    ok = (src >= 0) & (src < n)
    out[idx[ok]] = h[src[ok]]
    return out


def _try_upsample(best, bestR, deadline):
    """Refine at twice the resolution, which can escape plateau of current N."""
    if best.size * 2 > 1000000:
        return best, bestR
    h2 = _upsample2(best)
    h2 = _rescale(h2)
    r2 = R_of(h2)
    # quick polish at doubled resolution
    h3 = _lbfgs_block(h2, np.arange(h2.size), 400, deadline - 0.4, beta=1e8)
    r3 = R_of(h3)
    if r3 > r2:
        h2, r2 = h3, r3
    if time.process_time() < deadline - 0.4:
        h4 = _lbfgs_all_pos(h2, 300, deadline - 0.4, beta=0.0)
        r4 = R_of(h4)
        if r4 > r2:
            h2, r2 = h4, r4
    if r2 > bestR + 1e-13:
        return h2, r2
    return best, bestR


def _try_shift_window(best, bestR, deadline, rng):
    """Rigidly translate one support bump by a few steps, then re-optimise."""
    n = best.size
    if n < 64:
        return best, bestR
    # find contiguous support segments
    sup = best > 1e-12 * best.max()
    if not sup.any():
        return best, bestR
    # pick a random support segment
    d = np.diff(np.concatenate(([0], sup.astype(int), [0])))
    starts = np.flatnonzero(d == 1)
    ends = np.flatnonzero(d == -1)
    if starts.size == 0:
        return best, bestR
    k = int(rng.integers(0, starts.size))
    a, b = int(starts[k]), int(ends[k])
    w = b - a
    if w < 2 or w > n // 2:
        return best, bestR
    shift = int(rng.choice([-8, -4, -2, -1, 1, 2, 4, 8]))
    if a + shift < 0 or b + shift > n:
        return best, bestR
    h = best.copy()
    block = best[a:b].copy()
    h[a:b] = 0.0
    h[a + shift:b + shift] = block
    h = _rescale(h)
    lo = max(0, min(a, a + shift) - 32)
    hi = min(n - 1, max(b, b + shift) + 32)
    free = np.arange(lo, hi + 1)
    ht = _lbfgs_block(h, free, 200, deadline - 0.5, beta=1e7)
    if time.process_time() < deadline - 0.5:
        pw = _peak_window(ht, pad_frac=0.2, extra=128)
        ht2 = _lbfgs_block(ht, pw, 100, deadline - 0.5, beta=0.0)
        if R_of(ht2) > R_of(ht):
            ht = ht2
    r = R_of(ht)
    if r > bestR + 1e-13:
        return ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(20240219)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: confirm plateau at current resolution.
    if time.process_time() < deadline - 2.0:
        best, bestR = run_cycle(best, bestR, deadline - 2.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2: try resolution doubling -- the biggest structural lever.
    if time.process_time() < deadline - 1.5:
        hb, rb = _try_upsample(best, bestR, deadline - 1.5)
        if rb > bestR + 1e-13:
            best, bestR = hb, rb
            print("upsample -> R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 3: shift-window hops targeting the near-peak band.
    hop = 0
    acc = 0
    while time.process_time() < deadline - 1.2:
        hop += 1
        hb, rb = _try_shift_window(best, bestR, deadline - 1.0, rng)
        if rb > bestR + 1e-13:
            best, bestR = hb, rb
            acc += 1
        if hop % 4 == 0:
            print("hop %d acc %d bestR=%.7f" % (hop, acc, bestR))

    print("hops done: %d accepted %d bestR=%.7f" % (hop, acc, bestR))

    # Phase 4: final polish.
    if time.process_time() < deadline - 0.8:
        best, bestR = run_cycle(best, bestR, deadline - 0.8)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
