            gLf2 = -w2 / smin
            grad2 = _backprop(gLf2, h)
            grad = grad - eta * grad2
            val = val - eta * np.log(smin)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, softmin=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if softmin:
        fg = _fun_grad_softmin
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        n_screen = len(cands)
        best_pred = cands[0][0]
        best_cand = None
        best_cand_R = bestR
        best_realized = 0.0
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
                best_realized = r2 - bestR
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
            print("round %d: screened=%d pred=%.3e realized=%.3e R=%.7f" %
                  (round_no, n_screen, best_pred, best_realized, bestR))
        else:
            print("round %d: screened=%d pred=%.3e no accept R=%.7f" %
                  (round_no, n_screen, best_pred, bestR))
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
    print("edit loop: rounds=%d accepted=%d" % (round_no, total_acc))
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


def _phase_flat(best, deadline, n_iters=30):
    """Alternating projections with a sharp trapezoidal target:
    plateau 1.0 over central 93% of [2s0,2s1], cosine ramps over outer 3.5%."""
    n = best.size
    s0, s1 = _active_support(best)
    if s1 <= s0:
        return best
    M = next_fast_len(4 * n)

    gk = np.zeros(2 * n + 1, dtype=float)
    lo = 4 * s0
    hi = 4 * s1
    if hi <= lo:
        return best
    span = hi - lo
    ramp = max(1, int(0.035 * span))
    gk[lo:hi + 1] = 1.0
    if ramp > 1:
        t = np.linspace(0.0, np.pi, ramp)
        rampup = 0.5 * (1.0 - np.cos(t))
        gk[lo:lo + ramp] *= rampup
        gk[hi - ramp + 1:hi + 1] *= rampup[::-1]
    gp = np.zeros(M, dtype=float)
    L = min(M, gk.size)
    gp[:L] = gk[:L]
    A = np.sqrt(np.abs(np.fft.fft(gp)))

    f_pad = np.zeros(M, dtype=float)
    f_pad[:n] = np.clip(best, 0, None)

    mask = np.zeros(M, dtype=bool)
    mask[s0:s1 + 1] = True

    cand = best.copy()
    candR = R_of(cand)
    for it in range(n_iters):
        if time.process_time() >= deadline - 1.0:
            break
        F = np.fft.fft(f_pad)
        mag = np.abs(F)
        phase = F / np.maximum(mag, 1e-30)
        f_new = np.real(np.fft.ifft(A * phase))
        f_new = np.clip(f_new, 0.0, None)
        f_new[~mask] = 0.0
        f_pad = 0.7 * f_new + 0.3 * f_pad
        f_pad = np.clip(f_pad, 0.0, None)
        f_pad[~mask] = 0.0
        hc = f_pad[:n].copy()
        if hc.sum() <= 0:
            break
        hc = _rescale(hc)
        f_pad[:n] = hc
        f_pad[n:] = 0.0
        r = R_of(hc)
        if r > candR + 1e-13:
            cand = hc
            candR = r
    return cand


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # Fused loop: 3 rounds of {phase-flat(30) -> L-BFGS beta=1e7 (60) ->
    # exact-R polish (60) -> softmin pass (60)}, stop with 15s left.
    loop_deadline = deadline - 15.0
    for rnd in range(3):
        if time.process_time() >= loop_deadline:
            break
        try:
            cand = _phase_flat(best, loop_deadline, n_iters=30)
            r = R_of(cand)
            print("round %d phase-flat R=%.7f band01=%.2f%% band1=%.2f%% band5=%.2f%%" %
                  (rnd, r, 100.0 * _band_frac(cand, 0.001),
                   100.0 * _band_frac(cand, 0.01),
                   100.0 * _band_frac(cand, 0.05)))
            if r > bestR + 1e-13:
                best, bestR = cand.copy(), r
            if r > altR:
                alt_cand, altR = cand.copy(), r
        except Exception as e:
            print("round %d phase-flat failed: %s" % (rnd, e))
            continue
        if time.process_time() >= loop_deadline:
            break
        ht = _lbfgs_all_pos(best, 60, loop_deadline, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        if time.process_time() >= loop_deadline:
            break
        ht = _lbfgs_all_pos(best, 60, loop_deadline, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        if time.process_time() >= loop_deadline:
            break
        ht = _lbfgs_all_pos(best, 60, loop_deadline, softmin=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        print("round %d fused R=%.7f band01=%.2f%% band1=%.2f%% band5=%.2f%%" %
              (rnd, bestR, 100.0 * _band_frac(best, 0.001),
               100.0 * _band_frac(best, 0.01),
               100.0 * _band_frac(best, 0.05)))

    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _perturb_peak(h, rng, scale):
    """Add smooth noise localized near the peak plateau of f*f."""
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return h
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = max(1, hi - lo)
    pad = int(scale * span) + 8
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    n = h.size
    x = np.arange(lo, hi + 1, dtype=float)
    B = np.zeros_like(x)
    for _ in range(4):
        k = rng.integers(1, 6)
        a = rng.normal(0.0, 0.35)
        phi = rng.uniform(0.0, 1.0)
        B += a * np.cos(2.0 * np.pi * (k * x / max(1, hi - lo) + phi))
    B = np.clip(B, -3.0, 3.0)
    out = h.copy()
    out[lo:hi + 1] = out[lo:hi + 1] * np.exp(B)
    out = np.clip(out, 0.0, None)
    if out.sum() <= 0:
        return h
    out *= h.sum() / out.sum()
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: cycle to consolidate.
    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("cycle R=%.7f" % bestR)

    # Phase B: local perturbations near the peak, followed by block refine.
    n = best.size
    n_trials = 0
    n_accepted = 0
    while time.process_time() < deadline - 3.0:
        scale = rng.uniform(0.2, 1.5)
        h_try = _perturb_peak(best, rng, scale)
        r_pre = R_of(h_try)
        n_trials += 1
        if r_pre >= bestR - 5e-3:
            # refine a window around the peak, then globally polish
            win = _peak_window(h_try, pad_frac=0.3, extra=192)
            h_p = _lbfgs_block(h_try, win, 120, deadline - 2.5, beta=0.0)
            r_p = R_of(h_p)
            if r_p > bestR + 1e-13:
                best, bestR = h_p.copy(), r_p
                n_accepted += 1
                print("ACCEPT trial %d scale=%.2f pre=%.7f post=%.7f newR=%.7f"
                      % (n_trials, scale, r_pre, r_p, bestR))
        if n_trials % 15 == 0:
            print("  ... %d trials, %d accepted, R=%.7f"
                  % (n_trials, n_accepted, bestR))

    print("perturb phase: %d trials, %d accepted" % (n_trials, n_accepted))

    # Phase C: final global polish.
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 1000, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 96, 1e8), (0.20, 160, 1e8),
              (0.35, 320, 1e8), (0.55, 640, 1e8), (0.80, 1024, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=300, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _spike_perturb(h, rng, frac=0.10, sigma=0.30):
    out = h.copy()
    S = np.flatnonzero(h > 0)
    if S.size == 0:
        return out
    m = max(1, int(frac * S.size))
    S = rng.choice(S, size=m, replace=False)
    out[S] *= np.exp(rng.normal(0.0, sigma, S.size))
    return np.clip(out, 0.0, None)


def _smooth_perturb(h, rng, width=8, sigma=0.10):
    n = h.size
    k = max(1, n // width)
    noise = rng.normal(0.0, sigma, k)
    up = np.repeat(noise, width)[:n]
    if up.size < n:
        up = np.concatenate([up, np.zeros(n - up.size)])
    return np.clip(h * np.exp(up), 0.0, None)


def _upsample(h, N):
    """Resample step heights h (length n) onto N steps by mass-preserving piecewise-constant averaging."""
    n = h.size
    if n == N:
        return h.copy()
    # treat h as density on [0,1]; integrate over N equal bins
    edges = np.linspace(0.0, 1.0, n + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))  # cumulative mass at edges
    # mass as function of x
    xs = np.linspace(0.0, 1.0, N + 1)
    # piecewise linear mass via interpolation of cum at edges
    mass = np.interp(xs, edges, cum)
    out = np.diff(mass) * (N / n) if False else np.diff(mass)
    # heights = mass per bin / bin width; bin width = 1/N; density scale irrelevant
    out = np.clip(out, 0.0, None)
    return out


def _refine_upsampled(h, factor, deadline, tol=1e-7):
    """Upsample then polish at higher resolution to escape grid discretization."""
    N = h.size * factor
    if N > 1000000:
        return h, R_of(h)
    hu = _upsample(h, N)
    r0 = R_of(h)
    hu = _lbfgs_all_pos(hu, 400, deadline, beta=0.0)
    ru = R_of(hu)
    if ru > r0 + tol:
        return hu, ru
    return h, r0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(int(t0 * 1000) & 0xffffffff)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # (1) First polish cycle on the given start.
    if time.process_time() < deadline - 8.0:
        best, bestR = run_cycle(best, bestR, deadline - 8.0)
        print("cycle1 R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # (2) Try upsampling to finer grid: the discretization itself may be limiting.
    for factor in (2, 3, 4):
        if time.process_time() >= deadline - 5.0:
            break
        if best.size * factor > 1000000:
            break
        h_up, r_up = _refine_upsampled(best, factor,
                                        deadline - 5.0)
        print("upsample x%d R=%.7f (N=%d)" % (factor, r_up, h_up.size))
        if r_up > bestR + 1e-9:
            best, bestR = h_up, r_up
            break

    # (3) Population of perturbed variants; polish each and keep the best.
    K = 4
    members = []
    for k in range(K):
        if time.process_time() >= deadline - 3.0:
            break
        if k % 2 == 0:
            h_k = _spike_perturb(best, rng, frac=0.10, sigma=0.30)
        else:
            h_k = _smooth_perturb(best, rng, width=max(4, best.size // 512),
                                  sigma=0.08)
        r_pre = R_of(h_k)
        h_k = _lbfgs_all_pos(h_k, 250, deadline - 3.0, beta=0.0)
        r_post = R_of(h_k)
        members.append((r_post, h_k))
        print("member %d pre %.7f post %.7f" % (k, r_pre, r_post))

    if members:
        members.sort(key=lambda t: -t[0])
        if members[0][0] > bestR + 1e-13:
            best, bestR = members[0][1].copy(), members[0][0]

    # (4) Crossover between top members, then polish.
    if len(members) >= 2 and time.process_time() < deadline - 3.0:
        A = members[0][1]; B = members[1][1]
        n = best.size
        lo = int(rng.uniform(0.25, 0.65) * n)
        hi = min(n, lo + int(rng.uniform(0.2, 0.4) * n))
        child = A.copy()
        child[lo:hi] = B[lo:hi]
        free = np.arange(max(0, lo - 512), min(n, hi + 512))
        child = _lbfgs_block(child, free, 200, deadline - 3.0, beta=1e7)
        child = _lbfgs_all_pos(child, 250, deadline - 3.0, beta=0.0)
        rc = R_of(child)
        print("crossover R=%.7f" % rc)
        if rc > bestR + 1e-13:
            best, bestR = child.copy(), rc

    # (5) Repeated polish cycles until deadline.
    cyc = 0
    while time.process_time() < deadline - 1.5:
        cyc += 1
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("cycle %d R=%.7f" % (cyc + 1, bestR))

    # (6) Final polish.
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _shape_weight(h, alpha, kind):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if h.sum() <= 0:
        return h
    act = np.flatnonzero(h > 1e-9 * h.max())
    if act.size < 2:
        return h
    lo = int(act.min())
    hi = int(act.max())
    span = hi - lo
    if span <= 0:
        return h
    idx = np.arange(n, dtype=float)
    t = (idx - lo) / span
    phi = np.sin(np.pi * t) ** 2
    outside = (idx < lo) | (idx > hi)
    phi = np.clip(phi, 0.0, 1.0)
    phi[outside] = 0.0
    if kind == 'edge':
        phi = 1.0 - phi
        phi[outside] = 0.0
    w = 1.0 + alpha * phi
    w = np.clip(w, 0.0, None)
    return _rescale(h * w)


def _perturb(h, rng, scale):
    """Small multiplicative noise on the active support."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    act = h > 1e-9 * h.max()
    out = h.copy()
    noise = np.exp(scale * rng.standard_normal(h.size))
    out[act] = out[act] * noise[act]
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Primary: push the start as far as possible with the existing pipeline.
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f" % bestR)

    # Sub-sample the support width: try narrower and wider windows around
    # the peak, since the optimum support may not be the full array.
    def _subsample(h, lo_frac, hi_frac):
        n = h.size
        act = np.flatnonzero(h > 1e-9 * h.max())
        if act.size < 4:
            return h
        a0, a1 = act.min(), act.max()
        span = a1 - a0
        lo = a0 + int(lo_frac * span)
        hi = a0 + int(hi_frac * span)
        lo = max(0, lo); hi = min(n - 1, hi)
        if hi - lo < 8:
            return h
        return h[lo:hi + 1].copy()

    # Try a few support crops, refine each, keep if better.
    crop_candidates = [(0.0, 1.0), (0.05, 0.95), (0.10, 0.90), (0.15, 0.85)]
    for lo_frac, hi_frac in crop_candidates:
        now = time.process_time()
        if now >= deadline - 2.0:
            break
        cdl = min(deadline - 1.5, now + (deadline - now) * 0.35)
        hc = _subsample(best, lo_frac, hi_frac)
        if hc.size == best.size:
            continue
        hc = _rescale(hc)
        rc = R_of(hc)
        c1, r1, _ = run_cycle(hc, rc, cdl)
        print("crop %.2f-%.2f R=%.7f" % (lo_frac, hi_frac, r1))
        if r1 > bestR + 1e-13:
            best, bestR = c1.copy(), r1

    # Random restarts / perturbations of the current best, short refinements.
    n_pert = 0
    while time.process_time() < deadline - 1.5:
        now = time.process_time()
        remaining = deadline - 1.5 - now
        if remaining < 2.0:
            break
        cdl = now + min(remaining * 0.5, 8.0)
        scale = 0.05 * (1.0 + 0.5 * rng.standard_normal())
        scale = max(0.01, min(0.4, scale))
        hp = _perturb(best, rng, scale)
        rp = R_of(hp)
        c1, r1, _ = run_cycle(hp, rp, cdl)
        n_pert += 1
        if r1 > bestR + 1e-13:
            best, bestR = c1.copy(), r1
            print("perturb #%d scale=%.3f R=%.7f" % (n_pert, scale, bestR))

    # Final full refinement.
    while time.process_time() < deadline - 1.0:
        prev = bestR
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        if bestR - prev < 1e-10:
            break

    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if best.size != start_best.size or bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

