    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, lo, hi):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    Lm = Lf.max()
    if Lm <= 0:
        return _fun_grad(h)
    mask = (Lf > lo * Lm) & (Lf < hi * Lm)
    d = (Lm - Lf) * mask
    val = np.sum(d * d) / (Lm * Lm)
    gLf = -2.0 * d / (Lm * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _fun_grad_plateau(h):
    # penalise second derivative of L along the top: make peak a flat plateau
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lm = Lf.max()
    if Lm <= 0:
        return _fun_grad(h)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, band=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if band is not None:
        lo, hi = band
        fg = (lambda hh: _fun_grad_band(hh, lo, hi))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _band_stats(h, lo, hi):
    Lf = _knots(h)
    Lm = Lf.max()
    if Lm <= 0:
        return 0.0, 0.0
    mask = (Lf > lo * Lm) & (Lf < hi * Lm)
    frac = np.mean(mask)
    if not np.any(mask):
        return frac, 0.0
    gap = np.mean((Lm - Lf[mask]) / Lm)
    return frac, gap


# ---- NEW: local knot-level ascent on the autocorrelation shape ----
def _shape_grad_step(h, lam, deadline, steps=40):
    """Directly ascend R by small moves that raise the L2 mass where L is
    near but not at the peak (widening the plateau) while keeping the max
    in check. Uses a soft-max weight so the peak can migrate."""
    n = h.size
    if time.process_time() >= deadline - 0.3:
        return h
    for _ in range(steps):
        if time.process_time() >= deadline - 0.3:
            break
        s = h.sum()
        if s <= 0:
            break
        num, dq, Lf = _num_and_dq(h)
        mx = Lf.max()
        beta = 1e5
        e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
        Z = e.sum()
        w = e / Z
        sm = mx + np.log(Z) / beta
        # gradient of log R; ascend
        gLf = -dq / num + w / sm
        g = _backprop(gLf, h) + 2.0 / s
        # normalise and step
        gn = np.linalg.norm(g)
        if gn <= 0:
            break
        h2 = np.clip(h + lam * g / gn * h.max() * 1e-3, 0, None)
        h2 = _rescale(h2)
        if R_of(h2) >= R_of(h):
            h = h2
        else:
            lam *= 0.5
            if lam < 1e-6:
                break
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = start_best.copy()
    curR = start_bestR

    bands = [(0.5, 0.999), (0.3, 0.99), (0.7, 0.999)]
    cycle = 0
    while time.process_time() < deadline - 3.0:
        cycle += 1
        for (lo, hi) in bands:
            if time.process_time() >= deadline - 3.0:
                break
            f0, g0 = _band_stats(cur, lo, hi)
            r_before = curR
            hb = _lbfgs_log(cur, 200, deadline, band=(lo, hi))
            f1, g1 = _band_stats(hb, lo, hi)
            rb = R_of(hb)
            hs = _lbfgs_log(hb, 150, deadline)
            rs = R_of(hs)
            hw = _window_polish_peak(hs, deadline, 0.10, 64,
                                     maxiter=200, beta=1e7)
            rw = R_of(hw)
            cand, rc = (hw, rw) if rw > rs else (hs, rs)
            if rc > curR + 1e-13:
                cur, curR = cand, rc
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
            print("cyc %d band(%.2f,%.3f) frac=%.3f gap %.4f->%.4f R %.7f->%.7f"
                  % (cycle, lo, hi, f0, g0, g1, r_before, curR))

        # NEW: direct shape ascent on the current best
        if time.process_time() < deadline - 3.0:
            hd = _shape_grad_step(best, 1.0, deadline, steps=60)
            rd = R_of(hd)
            if rd > bestR + 1e-13:
                best, bestR = hd, rd
                cur, curR = hd.copy(), rd

        if time.process_time() < deadline - 3.0:
            hb = _lbfgs_log(best, 200, deadline, beta=1e7)
            rb = R_of(hb)
            if rb > bestR + 1e-13:
                best, bestR = hb, rb
                cur, curR = hb.copy(), rb
        if time.process_time() < deadline - 3.0:
            hs = _lbfgs_log(best, 200, deadline)
            rs = R_of(hs)
            if rs > bestR + 1e-13:
                best, bestR = hs, rs
                cur, curR = hs.copy(), rs
        zf = 100.0 * np.mean(best <= 0)
        print("cycle %d R=%.7f zeros=%.1f%%" % (cycle, bestR, zf))

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1200:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1200:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 3 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


# ---------- Multi-scale resampling ----------

def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 4:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor).sum(axis=1)
    return hh


def _upsample(h, factor):
    n = h.size
    out = np.repeat(h, factor)
    return out


def _multiscale_polish(h, bestR, deadline):
    """Coarsen, optimize, refine — escapes local minima."""
    if time.process_time() >= deadline - 0.5:
        return h, bestR
    factors = [8, 4, 2]
    cur = h.copy()
    curR = bestR
    for f in factors:
        if time.process_time() >= deadline - 0.5:
            break
        if cur.size // f < 32:
            continue
        hd = _downsample(cur, f)
        hd = _rescale(hd)
        rd = R_of(hd)
        if rd < 0:
            continue
        # optimize at coarse scale with several restarts
        best_d = hd.copy()
        best_rd = rd
        for beta in (0.0, 1e7):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all(best_d, 400, deadline, beta=beta)
            rt = R_of(ht)
            if rt > best_rd + 1e-13:
                best_d, best_rd = ht, rt
        # upscale and polish
        hu = _upsample(best_d, f)
        if hu.size != cur.size:
            pad = cur.size - hu.size
            if pad > 0:
                hu = np.concatenate([hu, np.zeros(pad)])
            else:
                hu = hu[:cur.size]
        hu = _rescale(hu)
        ru = R_of(hu)
        for beta in (0.0, 1e7):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all(hu, 300, deadline, beta=beta)
            rt = R_of(ht)
            if rt > ru + 1e-13:
                hu, ru = ht, rt
        if ru > curR + 1e-13:
            cur, curR = hu, ru
    return cur, curR


# ---------- Smooth parametric seeds ----------

def _seed_parabola(N):
    """f = sqrt of a smooth bump; f*f ~ parabola near peak."""
    x = np.linspace(-1, 1, N)
    f = np.sqrt(np.clip(1.0 - x * x, 0, None)) ** 0.5
    return _rescale(f)


def _seed_triangular(N):
    x = np.linspace(0, 1, N)
    f = np.sqrt(np.clip(1.0 - np.abs(2 * x - 1), 0, None))
    return _rescale(f)


def _seed_cosine(N):
    x = np.linspace(0, 1, N)
    f = np.cos(np.pi * (x - 0.5)) ** 2
    return _rescale(f)


def _seed_gauss(N):
    x = np.linspace(-3, 3, N)
    f = np.exp(-x * x)
    return _rescale(f)


def _seed_uniform(N):
    return _rescale(np.ones(N))


def _seed_parabola_mix(N, p):
    """f = (1-|x|^p)^(1/(2p)) style — try to make f*f flat-topped."""
    x = np.linspace(-1, 1, N)
    return _rescale(np.clip(1.0 - np.abs(x) ** p, 0, None) ** (1.0 / p))


# ---------- Peak-flattening via phase retrieval ----------

def _phase_flat(h, deadline, iters=300):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h
    s0, s1 = int(pos[0]), int(pos[-1])
    M = 1
    while M < 4 * n:
        M *= 2
    gk = np.zeros(2 * n + 1)
    lo, hi = 2 * s0, 2 * s1
    if hi <= lo:
        return h
    span = hi - lo
    ramp = max(1, span // 20)
    gk[lo:hi + 1] = 1.0
    t = np.linspace(0, np.pi, ramp)
    rampup = 0.5 * (1 - np.cos(t))
    gk[lo:lo + ramp] *= rampup
    gk[hi - ramp + 1:hi + 1] *= rampup[::-1]
    gp = np.zeros(M)
    gp[:min(M, gk.size)] = gk[:min(M, gk.size)]
    A = np.sqrt(np.abs(np.fft.fft(gp)))
    f_pad = np.zeros(M)
    f_pad[:n] = np.clip(h, 0, None)
    mask = np.zeros(M, dtype=bool)
    mask[s0:s1 + 1] = True
    cand = h.copy()
    candR = R_of(cand)
    for it in range(iters):
        if time.process_time() >= deadline - 0.5:
            break
        F = np.fft.fft(f_pad)
        mag = np.abs(F)
        phase = F / np.maximum(mag, 1e-30)
        f_new = np.real(np.fft.ifft(A * phase))
        f_new = np.clip(f_new, 0, None)
        f_new[~mask] = 0.0
        f_pad = 0.6 * f_new + 0.4 * f_pad
        f_pad = np.clip(f_pad, 0, None)
        f_pad[~mask] = 0.0
        if it % 25 == 24:
            hc = _rescale(f_pad[:n].copy())
            f_pad[:n] = hc
            f_pad[n:] = 0
            hp = _lbfgs_all(hc, 60, deadline, beta=0.0)
            rp = R_of(hp)
            if rp > candR + 1e-13:
                cand, candR = hp, rp
    return cand, candR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 2048
        best = _seed_cosine(N)
        bestR = R_of(best)

    print("start R=%.7f N=%d" % (bestR, best.size))
    start_best = best.copy()
    start_bestR = bestR

    alt = None
    altR = -1.0

    # 1. Multi-scale polish of start (coarsen+refine to escape local mins)
    if time.process_time() < deadline - 5.0:
        try:
            hm, rm = _multiscale_polish(best, bestR, deadline - 4.0)
            print("multiscale R=%.7f (d=%.2e)" % (rm, rm - bestR))
            if rm > altR:
                alt, altR = hm.copy(), rm
            if rm > bestR + 1e-13:
                best, bestR = hm.copy(), rm
        except Exception as e:
            print("multiscale failed: %s" % e)

    # 2. Phase-flat: force f*f to be flat-topped
    if time.process_time() < deadline - 6.0:
        try:
            hc, rc = _phase_flat(best, deadline - 5.0, iters=200)
            print("phaseflat raw R=%.7f" % rc)
            if rc > altR:
                alt, altR = hc.copy(), rc
            if rc > bestR + 1e-13:
                best, bestR = hc.copy(), rc
        except Exception as e:
            print("phaseflat failed: %s" % e)

    # 3. Try fresh parametric seeds, polish each, keep best
    if time.process_time() < deadline - 10.0:
        N = best.size
        seeds = []
        try:
            seeds.append(("parab", _seed_parabola(N)))
            seeds.append(("tri", _seed_triangular(N)))
            seeds.append(("cos", _seed_cosine(N)))
            seeds.append(("gauss", _seed_gauss(N)))
            seeds.append(("unif", _seed_uniform(N)))
            for p in (1.5, 2.0, 2.5, 3.0, 4.0):
                seeds.append(("mix%.1f" % p, _seed_parabola_mix(N, p)))
        except Exception:
            pass
        for name, hs in seeds:
            if time.process_time() >= deadline - 8.0:
                break
            try:
                r0 = R_of(hs)
                hp = _lbfgs_all(hs, 300, deadline - 7.0, beta=0.0)
                rp = R_of(hp)
                hp2 = _lbfgs_all(hp, 200, deadline - 7.0, beta=1e7)
                rp2 = R_of(hp2)
                rr = max(rp, rp2)
                hh = hp2 if rp2 >= rp else hp
                if rr > altR:
                    alt, altR = hh.copy(), rr
                if rr > bestR + 1e-13:
                    best, bestR = hh.copy(), rr
                    print("  seed %s -> R=%.7f (new best)" % (name, rr))
            except Exception:
                pass

    # 4. Final intensive polishing around best
    if time.process_time() < deadline - 1.0:
        for beta in (0.0, 1e7, 0.0):
            if time.process_time() >= deadline - 0.8:
                break
            ht = _lbfgs_all(best, 800, deadline - 0.6, beta=beta)
            rt = R_of(ht)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
        print("final polish R=%.7f" % bestR)

    print("FINAL R=%.7f N=%d" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    return _lbfgs_all_pos(_seed_zeros(h), maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


# ---------------------------------------------------------------------------
# NEW IDEA: work on a coarser grid, then upsample.
# The optimum appears to be a "flat-topped" f*f with a wide plateau.  We can
# capture its gross shape on a much smaller grid (N ~ a few thousand), where
# L-BFGS is cheap and reliable, and then upsample (interpolate) to the
# original resolution, followed by local polishing.  This effectively lets
# the optimiser make many more iterations within the budget, exploring the
# large-scale structure (the location and width of the plateau) that the
# full-resolution optimiser is too slow to move.
# ---------------------------------------------------------------------------

def _downsample(h, m):
    """Average-pool h (length n) down to length m."""
    n = h.size
    if m >= n:
        return h.copy()
    edges = np.linspace(0, n, m + 1).astype(int)
    out = np.empty(m)
    for i in range(m):
        lo, hi = edges[i], edges[i + 1]
        if hi <= lo:
            out[i] = h[min(lo, n - 1)]
        else:
            out[i] = h[lo:hi].mean()
    return out


def _upsample(hc, n):
    """Linear-interpolate coarse hc to length n."""
    m = hc.size
    if m == n:
        return hc.copy()
    xc = (np.arange(m) + 0.5) * (n / m)
    xf = np.arange(n) + 0.5
    return np.interp(xf, xc, hc, left=hc[0], right=hc[-1])


def _coarse_polish(best, bestR, deadline, coarse_sizes):
    """For each coarse size: downsample, optimise on coarse grid (many
    iterations), upsample back, then polish locally at full resolution."""
    for m in coarse_sizes:
        if time.process_time() >= deadline - 2.0:
            break
        if m >= best.size:
            continue
        hc = _downsample(best, m)
        if hc.sum() <= 0:
            continue
        hc = _rescale(hc)
        rc = R_of(hc)
        # Optimise on coarse grid: full-res all-pos L-BFGS
        hc2 = _lbfgs_all_pos(hc, 2000, deadline - 1.5, beta=0.0)
        rc2 = R_of(hc2)
        # Also try soft-max at coarse resolution to encourage a flat plateau
        if time.process_time() < deadline - 1.5:
            hc3 = _lbfgs_all_pos(hc2, 1500, deadline - 1.5, beta=1e7)
            rc3 = R_of(hc3)
            if rc3 > rc2:
                hc2, rc2 = hc3, rc3
        # Upsample and polish locally at full resolution
        hu = _rescale(_upsample(hc2, best.size))
        ru = R_of(hu)
        if ru > bestR + 1e-13:
            # polish: local windows around peak, then a short full L-BFGS
            if time.process_time() < deadline - 1.0:
                win = _peak_window(hu, pad_frac=0.8, extra=512)
                hu2 = _lbfgs_block(hu, win, 400, deadline - 1.0, beta=0.0)
                ru2 = R_of(hu2)
                if ru2 > ru:
                    hu, ru = hu2, ru2
            if time.process_time() < deadline - 1.0:
                hu2 = _lbfgs_all_pos(hu, 300, deadline - 1.0, beta=0.0)
                ru2 = R_of(hu2)
                if ru2 > ru:
                    hu, ru = hu2, ru2
            if ru > bestR + 1e-13:
                best, bestR = hu.copy(), ru
    return best, bestR


def _flatten_peak(h, deadline):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    m = int(np.argmax(Lf))
    center = m // 2
    half = max(64, int(0.20 * h.size))
    lo = max(0, center - half)
    hi = min(h.size - 1, center + half)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, 200, deadline, beta=1e8)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Only explore coarse grids when we already have a large start; otherwise
    # any construction we build is already small.
    n = best.size
    if n >= 20000:
        coarse_sizes = [n // 32, n // 16, n // 8, n // 4, n // 2]
    elif n >= 4000:
        coarse_sizes = [max(512, n // 8), max(1024, n // 4), n // 2]
    else:
        coarse_sizes = [n // 4, n // 2]
    coarse_sizes = [m for m in coarse_sizes if 256 <= m < n]
    # Deduplicate preserving order
    seen = set()
    coarse_sizes = [m for m in coarse_sizes if not (m in seen or seen.add(m))]

    # Phase 1: coarse-grid exploration (the new idea).
    best, bestR = _coarse_polish(best, bestR, deadline, coarse_sizes)
    print("after coarse R=%.7f" % bestR)

    # Phase 2: keep polishing at full resolution with the original tools.
    iter_no = 0
    while time.process_time() < deadline - 1.0:
        iter_no += 1
        improved = False

        if time.process_time() < deadline - 1.0:
            ht = _flatten_peak(best, deadline - 1.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
                improved = True

        if time.process_time() < deadline - 1.0:
            ht = _lbfgs_all_pos(best, 300, deadline - 1.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
                improved = True

        if time.process_time() < deadline - 1.0:
            ht = _refine_knots(best, 200, deadline - 1.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
                improved = True

        # Re-run coarse polish periodically with a fresh (improved) base.
        if iter_no % 3 == 0 and time.process_time() < deadline - 3.0:
            best, bestR = _coarse_polish(best, bestR, deadline - 2.0,
                                         coarse_sizes)

        if not improved and iter_no % 4 == 0:
            if time.process_time() < deadline - 1.0:
                ht = _lbfgs_all_pos(best, 200, deadline - 1.0, beta=1e9)
                r = R_of(ht)
                if r > bestR + 1e-13:
                    best, bestR = ht.copy(), r
                    improved = True

        if iter_no % 2 == 0:
            print("iter %d R=%.7f" % (iter_no, bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        n_screen = len(cands)
        best_pred = cands[0][0]
        best_cand = None
        best_cand_R = bestR
        best_realized = 0.0
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
                best_realized = r2 - bestR
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: low-temperature Metropolis walk ----------------

def _metropolis(best, bestR, deadline, rng):
    """Low-T Metropolis walk with tight local window moves."""
    n = best.size
    cur = best.copy()
    curR = bestR
    gbest = best.copy()
    gbestR = bestR
    T = 4e-6
    T_floor = 1e-7
    steps = 0
    accepted = 0
    acc_worse = 0
    improved_from_worse = 0
    worse_origin_R = None
    log8 = np.log(8.0)
    log1500 = np.log(1500.0)

    while time.process_time() < deadline - 1.0:
        steps += 1
        pos = np.flatnonzero(cur > 0)
        if pos.size == 0:
            break
        a = int(pos[rng.integers(pos.size)])
        w = int(np.exp(rng.uniform(log8, log1500)))
        lo = max(0, a - w)
        hi = min(n - 1, a + w)
        win_len = hi - lo + 1
        h2 = cur.copy()
        if rng.random() < 0.5:
            noise = 1.0 + 0.02 * rng.standard_normal(win_len)
            h2[lo:hi + 1] = np.clip(h2[lo:hi + 1] * noise, 0.0, None)
        else:
            local_mean = cur[lo:hi + 1].mean()
            if local_mean <= 0:
                local_mean = cur[pos].mean()
            sigma = max(1.0, w / 4.0)
            center = 0.5 * (lo + hi)
            xs = np.arange(lo, hi + 1, dtype=float)
            bump = 0.05 * local_mean * np.exp(-0.5 * ((xs - center) / sigma) ** 2)
            h2[lo:hi + 1] = h2[lo:hi + 1] + bump
        if h2.sum() <= 0:
            continue
        free = np.arange(lo, hi + 1)
        h2 = _lbfgs_block(h2, free, 60, deadline - 1.0, beta=0.0)
        if time.process_time() >= deadline - 1.0:
            break
        h2 = _lbfgs_block(h2, free, 40, deadline - 1.0, beta=1e7)
        r2 = R_of(h2)
        if not np.isfinite(r2):
            continue
        delta = r2 - curR
        accept = False
        if delta > 0:
            accept = True
        else:
            p = np.exp(delta / T)
            if rng.random() < p:
                accept = True
        if accept:
            accepted += 1
            if delta <= 0:
                acc_worse += 1
                if worse_origin_R is None or curR > worse_origin_R:
                    worse_origin_R = curR
            cur = h2
            curR = r2
            if r2 > gbestR + 1e-13:
                gbest = h2.copy()
                gbestR = r2
                if worse_origin_R is not None:
                    improved_from_worse += 1
                    worse_origin_R = None
            T = max(T_floor, T * 0.97)
        if steps % 40 == 0 and curR < gbestR - 3e-6:
            cur = gbest.copy()
            curR = gbestR
        if steps % 200 == 0:
            print("metro step=%d acc=%d acc_worse=%d cur=%.7f gbest=%.7f T=%.2e" %
                  (steps, accepted, acc_worse, curR, gbestR, T))
    print("metro done: steps=%d acc=%d acc_worse=%d improved_from_worse=%d gbest=%.7f" %
          (steps, accepted, acc_worse, improved_from_worse, gbestR))
    return gbest, gbestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: low-temperature Metropolis walk ----
    if time.process_time() < deadline - 8.0:
        metro_deadline = deadline - 6.0
        gb, gbR = _metropolis(best, bestR, metro_deadline, rng)
        alt_cand, altR = gb.copy(), gbR
        if gbR > bestR + 1e-13:
            best, bestR = gb.copy(), gbR
            print("metro wins: R=%.7f" % bestR)
        else:
            print("metro did not beat base: %.7f vs %.7f" % (gbR, bestR))

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: sub-cell run shifting ----------------

def _find_runs(h, peak_thresh_frac=0.5):
    """Maximal blocks of consecutive positive cells; keep those whose peak
    height >= peak_thresh_frac * global max."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    pos = h > 0
    if not pos.any():
        return []
    gmax = h.max()
    thr = peak_thresh_frac * gmax
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            if h[i:j + 1].max() >= thr:
                runs.append(np.arange(i, j + 1))
            i = j + 1
        else:
            i += 1
    return runs


def _splat(h, runs, s):
    """Re-splat each kept run's mass with a sub-cell shift s_k.
    For run k with cells j and masses m_j, add to fine cell i the mass
    sum_j m_j * max(0, 1 - |i - (j + s_k)|). Unkept cells stay put."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    out = h.copy()
    for k, cells in enumerate(runs):
        sk = float(s[k])
        # remove original masses from out
        masses = h[cells]
        out[cells] -= masses
        # distribute
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            center = j + sk
            i0 = int(np.floor(center - 1.0))
            i1 = int(np.ceil(center + 1.0))
            for i in range(i0, i1 + 1):
                if i < 0 or i >= n:
                    continue
                w = 1.0 - abs(i - center)
                if w > 0.0:
                    out[i] += m * w
    return np.clip(out, 0.0, None)


def _splat_grad(h, runs, s, dRdh):
    """dR/ds_k = sum_i dRdh[i] * dh2[i]/ds_k, exact piecewise-linear."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    K = len(runs)
    g = np.zeros(K)
    for k, cells in enumerate(runs):
        sk = float(s[k])
        masses = h[cells]
        acc = 0.0
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            center = j + sk
            i0 = int(np.floor(center - 1.0))
            i1 = int(np.ceil(center + 1.0))
            for i in range(i0, i1 + 1):
                if i < 0 or i >= n:
                    continue
                d = i - center
                # w = max(0, 1-|d|); dw/ds = dw/dd * dd/ds, dd/ds = -1
                # dw/dd = -sign(d) for |d|<1, 0 otherwise
                if abs(d) < 1.0:
                    dw_dd = -np.sign(d)
                    dw_ds = dw_dd * (-1.0)
                    acc += dRdh[i] * m * dw_ds
        g[k] = acc
    return g


def _fd_check_splat(h, runs, s, dRdh, k, eps=1e-6):
    """Finite-difference check of dR/ds_k for one k."""
    s_plus = s.copy(); s_plus[k] += eps
    s_minus = s.copy(); s_minus[k] -= eps
    h_plus = _splat(h, runs, s_plus)
    h_minus = _splat(h, runs, s_minus)
    R_plus = R_of(h_plus)
    R_minus = R_of(h_minus)
    fd = (R_plus - R_minus) / (2 * eps)
    an = _splat_grad(h, runs, s, dRdh)[k]
    return fd, an


def _shift_opt(h, runs, s0, maxiter, deadline, free_shifts=True,
               free_heights=False, height_cells=None):
    """Joint L-BFGS on shifts (and optionally heights of kept runs)."""
    if time.process_time() >= deadline - 0.3:
        return h, s0
    K = len(runs)
    if K == 0:
        return h, s0
    s = np.clip(s0.copy(), -0.5, 0.5)
    h = np.clip(h, 0, None)
    n = h.size

    if free_heights and height_cells is not None:
        hcells = np.asarray(height_cells, dtype=int)
        x0 = np.concatenate([s, h[hcells]])
        n_s = K
        n_h = hcells.size

        def unpack(x):
            ss = np.clip(x[:n_s], -0.5, 0.5)
            hh = h.copy()
            hh[hcells] = np.clip(x[n_s:], 0.0, None)
            return ss, hh

        def f(x):
            ss, hh = unpack(x)
            h2 = _splat(hh, runs, ss)
            val, g2 = _fun_grad(h2)
            gs = _splat_grad(hh, runs, ss, g2)
            gh = g2[hcells]
            return val, np.concatenate([gs, gh])

        bounds = [(-0.5, 0.5)] * n_s + [(0.0, None)] * n_h
    else:
        x0 = s.copy()

        def f(x):
            ss = np.clip(x, -0.5, 0.5)
            h2 = _splat(h, runs, ss)
            val, g2 = _fun_grad(h2)
            gs = _splat_grad(h, runs, ss, g2)
            return val, gs

        bounds = [(-0.5, 0.5)] * K

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, s0
    if res is None:
        return h, s0

    if free_heights and height_cells is not None:
        ss, hh = unpack(res.x)
        h2 = _splat(hh, runs, ss)
        return h2, ss
    else:
        ss = np.clip(res.x, -0.5, 0.5)
        h2 = _splat(h, runs, ss)
        return h2, ss


def _subcell_experiment(base, baseR, deadline, rng):
    """Run the sub-cell shift experiment. Returns (best_h, bestR, alt_h, altR)."""
    h = np.clip(base, 0, None).copy()
    n = h.size
    runs = _find_runs(h, peak_thresh_frac=0.5)
    print("subcell: %d runs kept (of %d cells, N=%d)" %
          (len(runs), int(np.sum(h > 0)), n))
    if len(runs) == 0:
        return h, baseR, None, -1.0

    K = len(runs)
    s = np.zeros(K)

    # Validate splat gradient vs finite difference for one k
    h_test = _splat(h, runs, s)
    _, g_test = _fun_grad(h_test)
    fd, an = _fd_check_splat(h, runs, s, g_test, 0)
    denom = max(abs(fd), abs(an), 1e-12)
    rel_err = abs(fd - an) / denom
    print("subcell: FD check k=0 fd=%.6e an=%.6e rel_err=%.3e" %
          (fd, an, rel_err))

    best_h = h.copy()
    bestR = baseR
    best_s = s.copy()

    n_rounds = 3
    for rnd in range(n_rounds):
        if time.process_time() >= deadline - 10.0:
            break
        # 1) shifts only
        h1, s1 = _shift_opt(best_h, runs, best_s, 200, deadline - 8.0,
                            free_shifts=True, free_heights=False)
        r1 = R_of(h1)
        if r1 > bestR + 1e-13:
            best_h, bestR, best_s = h1, r1, s1
        # 2) heights only (of kept runs)
        if time.process_time() < deadline - 8.0:
            hcells = np.concatenate(runs)
            h2, s2 = _shift_opt(best_h, runs, best_s, 200, deadline - 6.0,
                                free_shifts=False, free_heights=True,
                                height_cells=hcells)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best_h, bestR, best_s = h2, r2, s2
        # 3) joint
        if time.process_time() < deadline - 8.0:
            hcells = np.concatenate(runs)
            h3, s3 = _shift_opt(best_h, runs, best_s, 400, deadline - 4.0,
                                free_shifts=True, free_heights=True,
                                height_cells=hcells)
            r3 = R_of(h3)
            if r3 > bestR + 1e-13:
                best_h, bestR, best_s = h3, r3, s3
        max_s = float(np.max(np.abs(best_s))) if K else 0.0
        rms_s = float(np.sqrt(np.mean(best_s ** 2))) if K else 0.0
        print("subcell round %d: R=%.7f max|s|=%.4f rms(s)=%.4f" %
              (rnd + 1, bestR, max_s, rms_s))

    alt_h = best_h.copy()
    altR = bestR
    return best_h, bestR, alt_h, altR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: sub-cell run shifting ----
    if time.process_time() < deadline - 20.0:
        try:
            exp_h, expR, alt_h, altR_exp = _subcell_experiment(
                best, bestR, deadline - 12.0, rng)
            if alt_h is not None:
                alt_cand, altR = alt_h.copy(), altR_exp
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("subcell wins: R=%.7f (was %.7f)" %
                      (bestR, start_bestR))
            else:
                print("subcell did not beat base: %.7f vs %.7f" %
                      (expR, bestR))
        except Exception as e:
            print("subcell experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _polish(best, bestR, deadline, loop_end, rng):
    if time.process_time() < loop_end:
        cap = min(loop_end, time.process_time() + 6.0)
        ht = _lbfgs_all_pos(best, 600, cap, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= loop_end:
            break
        cap = min(loop_end, time.process_time() + 3.0)
        ht = _lbfgs_all_pos(best, 200, cap, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    for frac in (0.05, 0.1, 0.2):
        if time.process_time() >= loop_end:
            break
        free = _peak_window(best, tol=0.999, pad_frac=frac, extra=128)
        cap = min(loop_end, time.process_time() + 4.0)
        ht = _lbfgs_block(best, free, 300, cap, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    # knot-level local refine: free the whole peak window with a softer tolerance
    if time.process_time() < loop_end:
        free = _peak_window(best, tol=0.99, pad_frac=0.3, extra=256)
        cap = min(loop_end, time.process_time() + 4.0)
        ht = _lbfgs_block(best, free, 300, cap, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    # ---- Experiment: seed zeros and re-optimize the whole vector in log space ----
    # The start has ~6% zeros, especially at the edges. Seeding them with tiny
    # positive values and re-optimizing the full vector in log space lets the
    # optimizer reshape the tails, which is where the L_inf constraint bites.
    h_exp = best.copy()
    h_exp_seeded = _seed_zeros(h_exp)
    cap = min(deadline - 1.0, time.process_time() + 12.0)
    h_log = _lbfgs_all_pos(h_exp_seeded, 800, cap, beta=0.0)
    r_log = R_of(h_log)
    print("  seeded log-space R=%.7f (was %.7f)" % (r_log, bestR))

    bestH = best.copy()
    bestRH = bestR
    if r_log > bestRH + 1e-13:
        bestH, bestRH = h_log.copy(), r_log
        print("    NEW BEST R=%.7f" % bestRH)

    # polish the experiment result
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 12.0)
        hp, rp = _polish(bestH, bestRH, deadline, cap, rng)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp, rp
            print("    polished NEW BEST R=%.7f" % bestRH)

    # ---- Main loop: alternating polish on bestH ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        improved = False
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_all_pos(bestH, 400, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            improved = True
        if time.process_time() < loop_end:
            tol = 0.999 if rng.random() < 0.5 else 0.995
            pad_frac = 0.1 + 0.5 * rng.random()
            free = _peak_window(bestH, tol=tol, pad_frac=pad_frac, extra=128)
            cap = min(loop_end, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 300, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                improved = True
        if not improved and time.process_time() < loop_end - 2.0:
            beta = 10.0 ** rng.uniform(2.0, 5.0)
            cap = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_all_pos(bestH, 200, cap, beta=beta)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs.copy(), rs
                improved = True
        if improved:
            print("  iter=%d R=%.7f" % (it, bestRH))

    print("final R=%.7f (best of experiment)" % bestRH)

    if bestRH > start_bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH
    else:
        best, bestR = start_best, start_bestR

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    if bestH.size == start_best.size and bestRH > start_bestR - 1e-6:
        return {"best": start_best, "alternative": bestH}
    return {"best": start_best, "alternative": None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _peak_polish(h, deadline, rcur, fracs=(0.03, 0.07, 0.15), maxiter=300, beta=0.0):
    for frac in fracs:
        if time.process_time() >= deadline - 0.5:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _resample(h, n_new):
    n = h.size
    if n == n_new:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    x_new = np.linspace(0.0, 1.0, n_new, endpoint=False)
    return np.interp(x_new, x_old, h)


def _revive_zeros(h, factor, win=256):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    pos = h > 0
    if not pos.any():
        return h
    gmean = h[pos].mean()
    hp = np.where(pos, h, 0.0)
    cnt = pos.astype(float)
    cs = np.concatenate(([0.0], np.cumsum(hp)))
    cc = np.concatenate(([0.0], np.cumsum(cnt)))
    half = win // 2
    idx = np.arange(n)
    lo = np.clip(idx - half, 0, n)
    hi = np.clip(idx + half + 1, 0, n)
    ssum = cs[hi] - cs[lo]
    scnt = cc[hi] - cc[lo]
    local = np.where(scnt > 0, ssum / np.maximum(scnt, 1e-300), gmean)
    zeros = ~pos
    h[zeros] = factor * local[zeros]
    return _rescale(h)


def _perturb(h, rng, scale=0.05):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    p = rng.standard_normal(n) * scale
    if n > 8:
        k = max(3, n // 64)
        kern = np.ones(k) / k
        p = np.convolve(p, kern, mode='same')
    h = h * np.exp(p)
    return _rescale(h)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = _rescale(s.copy())
            best_r = R_of(best)

    if best is None:
        x = np.linspace(0, 1, 256)
        best = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best_r = R_of(best)

    print("start R = %.6f, N = %d" % (best_r, best.size))
    base_r = best_r
    rng = np.random.default_rng(12345)

    # NEW IDEA: dense-seed polish. Fill zeros with tiny positive values and
    # run a full-grid L-BFGS in log-space so previously-zero positions can
    # become active. This unlocks shape changes the sparse-active-set
    # optimizer (which freezes zeros) cannot reach. Do this FIRST on the
    # start grid, since it is cheap and often yields the largest single gain.
    if time.process_time() < deadline - 4.0:
        hs = _seed_zeros(best)
        c = _lbfgs_log(hs, maxiter=1200, deadline=deadline)
        r = R_of(c)
        if r > best_r:
            best, best_r = c.copy(), r
            print("dense-seed -> %.6f" % best_r)

    # Round 2 of dense-seed at slightly larger eps to escape more zeros.
    if time.process_time() < deadline - 4.0:
        hs = _seed_zeros(best)
        hs = _revive_zeros(hs, 1e-2)
        c = _lbfgs_log(hs, maxiter=800, deadline=deadline)
        r = R_of(c)
        if r > best_r:
            best, best_r = c.copy(), r
            print("dense-revive -> %.6f" % best_r)

    # Sharpen the peak via beta-weighted polish on the best grid.
    h, cur = best.copy(), best_r
    for beta in (1e4, 1e5, 1e6):
        if time.process_time() >= deadline - 3.0:
            break
        c = _lbfgs_log(h, maxiter=400, deadline=deadline, beta=beta)
        r = R_of(c)
        if r > cur:
            h, cur = c, r
        h, cur = _peak_polish(h, deadline, cur, fracs=(0.03, 0.07, 0.15),
                              maxiter=300, beta=beta)
    if cur > best_r:
        best, best_r = h.copy(), cur
        print("beta polish -> %.6f" % best_r)

    # Phase B: upsample to a finer grid and re-optimize there.
    alt = []
    for factor in (2, 4):
        if time.process_time() >= deadline - 8.0:
            break
        n_new = min(1000000, best.size * factor)
        if n_new <= best.size:
            continue
        hf = _rescale(_resample(best, n_new))
        hf = _lbfgs_log(hf, maxiter=400, deadline=deadline)
        rf = R_of(hf)
        if rf > best_r:
            hf, rf = _peak_polish(hf, deadline, rf,
                                  fracs=(0.03, 0.07, 0.15), maxiter=300)
        alt.append((rf, hf))
        print("  up %dx R=%.6f N=%d" % (factor, rf, hf.size))

    if alt:
        alt.sort(key=lambda t: -t[0])
        rf, hf = alt[0]
        if rf > best_r:
            best, best_r = hf.copy(), rf
            print("upsample improved to %.6f (N=%d)" % (best_r, best.size))

    # Phase C: zero revival on the best.
    if time.process_time() < deadline - 6.0:
        for factor in (1e-3, 1e-2):
            if time.process_time() >= deadline - 4.0:
                break
            hr = _revive_zeros(best, factor)
            hr = _lbfgs_log(hr, maxiter=500, deadline=deadline)
            rr = R_of(hr)
            for beta in (1e3, 1e4, 1e5):
                if time.process_time() >= deadline - 3.0:
                    break
                cand = _lbfgs_log(hr, maxiter=250, deadline=deadline, beta=beta)
                r = R_of(cand)
                if r > rr:
                    hr, rr = cand, r
                hr, rr = _peak_polish(hr, deadline, rr,
                                      fracs=(0.03, 0.10), maxiter=250)
            if rr > best_r:
                best, best_r = hr.copy(), rr
                print("  revive f=%.0e R=%.6f" % (factor, rr))

    # Phase D: alternating polish + perturbation loop.
    h, cur = best.copy(), best_r
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        c = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r = R_of(c)
        if r > cur:
            h, cur = c, r
        if it % 3 == 0:
            for beta in (1e5, 1e6, 1e7):
                if time.process_time() >= deadline - 1.0:
                    break
                c2 = _lbfgs_log(h, maxiter=200, deadline=deadline, beta=beta)
                r2 = R_of(c2)
                if r2 > cur:
                    h, cur = c2, r2
        h, cur = _peak_polish(h, deadline, cur,
                              fracs=(0.03, 0.07, 0.15), maxiter=300)
        if it % 4 == 0 and time.process_time() < deadline - 3.0:
            hp = _perturb(h, rng, scale=0.03)
            hp = _lbfgs_log(hp, maxiter=200, deadline=deadline)
            rp = R_of(hp)
            if rp > cur:
                h, cur = hp, rp
        if cur > best_r:
            best, best_r = h.copy(), cur
        print("  alt %d R=%.6f (best %.6f) N=%d" % (it, cur, best_r, best.size))

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        if best_r > base_r + 1e-12:
            return {"best": best, "alternative": start_arr}
        return {"best": start_arr, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
