    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


# ---------------- NEW: adaptive knot insertion ----------------

def _resample(h, newN):
    """Resample a step function onto newN equal steps (mass-preserving)."""
    n = h.size
    if n == newN:
        return h.copy()
    # cumulative mass at boundaries of old steps
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(newN)
    # new step edges in old-step index space
    edges = np.linspace(0.0, n, newN + 1)
    # mass at each edge
    mvals = np.interp(edges, np.arange(n + 1), c)
    newh = np.diff(mvals) * (newN / n)
    return np.clip(newh, 0.0, None)


def _insertion_refine(best, bestR, deadline, rng):
    """Insert knots where the f*f knots are near max (peak region), then
    re-polish.  This lets the peak of f*f be better resolved."""
    if time.process_time() >= deadline - 2.0:
        return best, bestR
    n = best.size
    Lf = _knots(best)
    mx = Lf.max()
    if mx <= 0:
        return best, bestR
    # Densify by resampling onto a finer grid; peak region gets more cells.
    target = min(int(n * 1.35), 900000)
    if target <= n:
        return best, bestR
    # Weighted resampling: insert extra cells where f*f is close to max.
    # Approximation: locally double density in high-band region.
    band = Lf >= 0.98 * mx
    frac_band = float(np.mean(band))
    # Build a non-uniform map: cells in the band expanded 2x.
    idx = np.arange(n + 1)
    # weight each old interval by 1 + (band indicator)
    band_lo = Lf[:-1]
    bmid = 0.5 * (Lf[:-1] + Lf[1:])
    w = np.where(bmid >= 0.98 * mx, 2.0, 1.0)
    cumw = np.concatenate(([0.0], np.cumsum(w)))
    totalw = cumw[-1]
    edges = np.linspace(0.0, totalw, target + 1)
    # old-step position (in index space) at each new edge
    pos = np.interp(edges, cumw, np.arange(n + 1))
    c = np.concatenate(([0.0], np.cumsum(best)))
    mvals = np.interp(pos, np.arange(n + 1), c)
    newh = np.diff(mvals)
    newh = np.clip(newh, 0.0, None)
    if newh.sum() <= 0:
        return best, bestR
    # local polish: only the peak band region plus margins
    hp = _rescale(newh)
    r0 = R_of(hp)
    Lp = _knots(hp)
    newmx = Lp.max()
    idx2 = np.flatnonzero(Lp >= 0.995 * newmx)
    lo = max(0, idx2.min() - 1)
    hi = min(hp.size - 1, idx2.max())
    span = hi - lo
    pad = max(512, span)
    lo = max(0, lo - pad)
    hi = min(hp.size - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(hp, free, 300, deadline - 1.0, beta=0.0)
    r1 = R_of(hp)
    if r1 > r0:
        hp = _lbfgs_block(hp, free, 200, deadline - 0.5, beta=1e7)
        r1 = R_of(hp)
    if r1 > bestR + 1e-13:
        return hp, r1
    return best, bestR


def _boundary_value(h, side, k=8):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0.0
    if side == 'L':
        idx = pos[:k]
    else:
        idx = pos[-k:]
    return float(h[idx].mean())


def _make_profile(kind, length, v, eps):
    if length <= 0:
        return np.zeros(0)
    j = np.arange(length, dtype=float)
    if kind == 'eps-const':
        return np.full(length, eps)
    if kind == 'ramp-from-end':
        frac = j / max(1.0, length - 1.0)
        return v * (1.0 - frac) + eps * frac
    if kind == 'exp-decay':
        return v * np.exp(-j / 1500.0) + eps
    return np.full(length, eps)


def _build_padded(start, padL, padR, kind, eps):
    vL = _boundary_value(start, 'L')
    vR = _boundary_value(start, 'R')
    profL = _make_profile(kind, padL, vL, eps)
    profR = _make_profile(kind, padR, vR, eps)
    if padL > 0:
        profL = profL[::-1]
    return np.concatenate([profL, start, profR])


def _tail_polish(h, padL, padR, deadline, it1=250, it2=120):
    n = h.size
    h = _lbfgs_all_pos(h, it1, deadline, beta=0.0)
    if padL > 0:
        free = np.arange(0, min(n - 1, padL + 256) + 1)
        h = _lbfgs_block(h, free, it2, deadline, beta=1e7)
    if padR > 0:
        free = np.arange(max(0, n - padR - 256), n)
        h = _lbfgs_block(h, free, it2, deadline, beta=1e7)
    return h


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR, 0.0


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # (0) Knot-insertion refinement: densify near peak of f*f and re-polish.
    if time.process_time() < deadline - 20.0:
        hb, rb = _insertion_refine(best, bestR, deadline - 18.0, rng)
        print("insertion dR=%+.3e R=%.7f (N=%d)" % (rb - bestR, rb, hb.size))
        if rb > bestR + 1e-13:
            best, bestR = hb, rb

    # (1) Run a full optimisation cycle.
    if time.process_time() < deadline - 12.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 12.0)
        print("cycle1 R=%.7f (N=%d)" % (bestR, best.size))

    # (2) Another insertion pass at the finer resolution.
    if time.process_time() < deadline - 6.0:
        hb, rb = _insertion_refine(best, bestR, deadline - 5.0, rng)
        print("insertion2 dR=%+.3e R=%.7f (N=%d)" % (rb - bestR, rb, hb.size))
        if rb > bestR + 1e-13:
            best, bestR = hb, rb

    # (3) Final cycle to lock in gains.
    if time.process_time() < deadline - 2.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 2.0)
        print("cycle2 R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6 and best.size != start_best.size:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _resample(h, factor):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    m = n * factor
    idx = np.arange(m) // factor
    return h[idx]


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 96, 1e7), (0.25, 192, 1e8),
              (0.45, 384, 1e8), (0.65, 640, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 250, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:30]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 30)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    stats['best_raw'] = max(stats['best_raw'], best_r - bestR)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # Finer-grid refinement: resample exactly onto 2x grid then L-BFGS.
    # This is the key improvement: a finer grid gives the optimiser more
    # degrees of freedom to fit the true optimum shape, and resampling is
    # exact (same piecewise-constant function) so it never hurts.
    if time.process_time() < deadline - 8.0:
        try:
            hf = _resample(best, 2)
            sub_dl = deadline - 6.0
            ht = _lbfgs_all_pos(hf, 500, sub_dl, beta=0.0)
            rt = R_of(ht)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                print("fine refine wins: R=%.7f (N=%d)" % (bestR, best.size))
            else:
                print("fine refine no change: %.7f" % rt)
        except Exception as e:
            print("fine refine failed: %s" % e)

    if time.process_time() < deadline - 3.0:
        best, bestR = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    while time.process_time() < deadline - 4.0:
        best, bestR = _dip_moves(best, bestR, deadline - 4.0, stats)
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: free 5-cell kernel per tall run ----------------

def _find_runs(h, peak_thresh_frac=0.5, K_cap=512):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    pos = h > 0
    if not pos.any():
        return []
    gmax = h.max()
    thr = peak_thresh_frac * gmax
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            pk = h[i:j + 1].max()
            if pk >= thr:
                runs.append((pk, np.arange(i, j + 1)))
            i = j + 1
        else:
            i += 1
    runs.sort(key=lambda t: -t[0])
    runs = [r for _, r in runs[:K_cap]]
    return runs


def _run_centres(runs):
    """Integer centre cell for each run (mass-weighted centre, rounded)."""
    return np.array([int(round(float(c.mean()))) for c in runs], dtype=int)


def _splat(h, runs, W):
    """Replace each kept run's mass by a 5-cell kernel w_k (normalised)
    splatted at centre_k + (-2..+2). Unkept cells untouched."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    out = h.copy()
    K = len(runs)
    if K == 0:
        return out
    centres = _run_centres(runs)
    for k in range(K):
        cells = runs[k]
        mass = float(h[cells].sum())
        out[cells] -= h[cells]
        if mass <= 0.0:
            continue
        w = np.clip(W[k], 0.0, None)
        sw = w.sum()
        if sw <= 0.0:
            w = np.array([1e-4, 1e-4, 1.0, 1e-4, 1e-4])
            sw = w.sum()
        wn = w / sw
        c = centres[k]
        for idx in range(5):
            i = c + (idx - 2)
            if 0 <= i < n:
                out[i] += mass * wn[idx]
    return np.clip(out, 0.0, None)


def _splat_grad(h, runs, W, dRdh):
    """Exact adjoint: dR/dW[k, idx]."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    K = len(runs)
    gW = np.zeros((K, 5))
    if K == 0:
        return gW
    centres = _run_centres(runs)
    for k in range(K):
        cells = runs[k]
        mass = float(h[cells].sum())
        if mass <= 0.0:
            continue
        w = np.clip(W[k], 0.0, None)
        sw = w.sum()
        if sw <= 0.0:
            continue
        wn = w / sw
        c = centres[k]
        # d out_i / d w_idx = mass * (delta_{i, c+idx-2}/sw - wn[idx]/sw^2)
        # so dR/dw_idx = mass * sum_i dRdh[i] * (delta/sw - wn[idx]/sw^2)
        #             = mass * (dRdh[c+idx-2]/sw - wn[idx] * sum_i dRdh[i]/sw^2)
        # where sum_i runs over the 5 splat cells only.
        # Build local g over the 5 splat cells.
        gloc = np.zeros(5)
        for idx in range(5):
            i = c + (idx - 2)
            if 0 <= i < n:
                gloc[idx] = dRdh[i]
        sgloc = gloc.sum()
        for idx in range(5):
            gW[k, idx] = mass * (gloc[idx] / sw - wn[idx] * sgloc / (sw * sw))
    return gW


def _fd_check_splat(h, runs, W, dRdh, k=0, idx=2, eps=1e-6):
    Wp = W.copy(); Wp[k, idx] += eps
    Wm = W.copy(); Wm[k, idx] -= eps
    Rp = R_of(_splat(h, runs, Wp))
    Rm = R_of(_splat(h, runs, Wm))
    fd = (Rp - Rm) / (2 * eps)
    gW = _splat_grad(h, runs, W, dRdh)
    an = gW[k, idx]
    rel = abs(fd - an) / max(abs(fd), abs(an), 1e-12)
    return fd, an, rel


def _splat_opt(h, runs, W0, maxiter, deadline,
               free_W=True, free_heights=False):
    if time.process_time() >= deadline - 0.3:
        return h, W0
    K = len(runs)
    if K == 0:
        return h, W0
    h = np.clip(h, 0, None)
    n = h.size
    W = np.clip(W0.copy(), 0.0, None)
    hcells = np.concatenate(runs) if free_heights else None

    if free_heights:
        n_h = hcells.size
        x0 = np.concatenate([W.ravel(), h[hcells]])

        def unpack(xv):
            Wk = np.clip(xv[:5 * K].reshape(K, 5), 0.0, None)
            hh = h.copy()
            hh[hcells] = np.clip(xv[5 * K:], 0.0, None)
            return Wk, hh

        def f(xv):
            Wk, hh = unpack(xv)
            h2 = _splat(hh, runs, Wk)
            val, g2 = _fun_grad(h2)
            gW = _splat_grad(hh, runs, Wk, g2)
            gh = g2[hcells]
            return val, np.concatenate([gW.ravel(), gh])

        bounds = [(0.0, None)] * (5 * K) + [(0.0, None)] * n_h
    else:
        x0 = W.ravel()

        def f(xv):
            Wk = np.clip(xv.reshape(K, 5), 0.0, None)
            h2 = _splat(h, runs, Wk)
            val, g2 = _fun_grad(h2)
            gW = _splat_grad(h, runs, Wk, g2)
            return val, gW.ravel()

        bounds = [(0.0, None)] * (5 * K)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, W0
    if res is None:
        return h, W0

    if free_heights:
        Wk, hh = unpack(res.x)
        h2 = _splat(hh, runs, Wk)
        return h2, Wk
    else:
        Wk = np.clip(res.x.reshape(K, 5), 0.0, None)
        h2 = _splat(h, runs, Wk)
        return h2, Wk


def _kernel_spread(W):
    if W.size == 0:
        return 0.0
    W = np.clip(W, 0, None)
    spreads = []
    for row in W:
        s = row.sum()
        if s <= 0:
            continue
        m = row.mean()
        spreads.append(np.sum(np.abs(row - m)) / s)
    if not spreads:
        return 0.0
    return float(np.mean(spreads))


def _splat_experiment(base, baseR, deadline, rng):
    h = np.clip(base, 0, None).copy()
    n = h.size
    runs = _find_runs(h, peak_thresh_frac=0.5, K_cap=512)
    K = len(runs)
    print("splat: K=%d runs kept (of %d positive cells, N=%d)" %
          (K, int(np.sum(h > 0)), n))
    if K == 0:
        return h, baseR, None, -1.0

    W = np.tile(np.array([1e-4, 1e-4, 1.0, 1e-4, 1e-4]), (K, 1))

    # FD check on one entry
    h_test = _splat(h, runs, W)
    _, g_test = _fun_grad(h_test)
    fd, an, rel = _fd_check_splat(h, runs, W, g_test, k=0, idx=2)
    print("splat: FD W[0,2]: fd=%.6e an=%.6e rel=%.3e" % (fd, an, rel))

    best_h = h.copy()
    bestR = baseR
    best_W = W.copy()

    for rnd in range(3):
        if time.process_time() >= deadline - 10.0:
            break
        # (a) W only
        h1, W1 = _splat_opt(best_h, runs, best_W, 200, deadline - 8.0,
                            free_W=True, free_heights=False)
        r1 = R_of(h1)
        if r1 > bestR + 1e-13:
            best_h, bestR, best_W = h1, r1, W1
        # (b) heights only
        if time.process_time() < deadline - 8.0:
            h2, W2 = _splat_opt(best_h, runs, best_W, 200, deadline - 6.0,
                                free_W=False, free_heights=True)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best_h, bestR, best_W = h2, r2, W2
        # (c) joint
        if time.process_time() < deadline - 8.0:
            h3, W3 = _splat_opt(best_h, runs, best_W, 400, deadline - 4.0,
                                free_W=True, free_heights=True)
            r3 = R_of(h3)
            if r3 > bestR + 1e-13:
                best_h, bestR, best_W = h3, r3, W3
        sp = _kernel_spread(best_W)
        nz = int(np.sum(np.abs(best_W - best_W.mean(axis=1, keepdims=True))
                        .sum(axis=1) / np.maximum(best_W.sum(axis=1), 1e-12)
                        > 0.05))
        print("splat round %d: R=%.7f spread=%.4f non-delta=%d/%d" %
              (rnd + 1, bestR, sp, nz, K))

    return best_h, bestR, best_h.copy(), bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: free 5-cell kernel per tall run ----
    if time.process_time() < deadline - 20.0:
        try:
            exp_h, expR, alt_h, altR_exp = _splat_experiment(
                best, bestR, deadline - 12.0, rng)
            if alt_h is not None:
                alt_cand, altR = alt_h.copy(), altR_exp
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("splat wins: R=%.7f (was %.7f)" % (bestR, start_bestR))
            else:
                print("splat did not beat base: %.7f vs %.7f" %
                      (expR, bestR))
        except Exception as e:
            print("splat experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: continuous run splitting ----------------

def _find_runs(h, peak_thresh_frac=0.7, K_cap=32):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    pos = h > 0
    if not pos.any():
        return []
    gmax = h.max()
    thr = peak_thresh_frac * gmax
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            pk = h[i:j + 1].max()
            if pk >= thr:
                runs.append((pk, np.arange(i, j + 1)))
            i = j + 1
        else:
            i += 1
    runs.sort(key=lambda t: -t[0])
    runs = [r for _, r in runs[:K_cap]]
    return runs


def _sigmoid(x):
    return 1.0 / (1.0 + np.exp(-np.clip(x, -60.0, 60.0)))


def _split(h, runs, d, x):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    out = h.copy()
    K = len(runs)
    for k, cells in enumerate(runs):
        dk = float(d[k])
        fk = float(_sigmoid(x[k]))
        masses = h[cells]
        out[cells] -= masses
        half = 0.5 * dk
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            for (shift, frac) in ((-half, fk), (half, 1.0 - fk)):
                center = j + shift
                i0 = int(np.floor(center - 1.0))
                i1 = int(np.ceil(center + 1.0))
                for i in range(i0, i1 + 1):
                    if i < 0 or i >= n:
                        continue
                    w = 1.0 - abs(i - center)
                    if w > 0.0:
                        out[i] += m * frac * w
    return np.clip(out, 0.0, None)


def _split_grad(h, runs, d, x, dRdh):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    K = len(runs)
    gd = np.zeros(K)
    gx = np.zeros(K)
    for k, cells in enumerate(runs):
        dk = float(d[k])
        fk = float(_sigmoid(x[k]))
        masses = h[cells]
        half = 0.5 * dk
        acc_d = 0.0
        acc_x = 0.0
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            for (shift, frac, dshift_dd, dfrac_dx) in (
                    (-half, fk, -0.5, fk * (1.0 - fk)),
                    (half, 1.0 - fk, 0.5, -fk * (1.0 - fk))):
                center = j + shift
                i0 = int(np.floor(center - 1.0))
                i1 = int(np.ceil(center + 1.0))
                for i in range(i0, i1 + 1):
                    if i < 0 or i >= n:
                        continue
                    dd = i - center
                    w = 1.0 - abs(dd)
                    if w > 0.0:
                        dw_dshift = np.sign(dd)
                        acc_d += dRdh[i] * m * frac * dw_dshift * dshift_dd
                        acc_x += dRdh[i] * m * w * dfrac_dx
        gd[k] = acc_d
        gx[k] = acc_x
    return gd, gx


def _fd_check_split(h, runs, d, x, dRdh, k, eps=1e-6):
    d_plus = d.copy(); d_plus[k] += eps
    d_minus = d.copy(); d_minus[k] -= eps
    R_plus = R_of(_split(h, runs, d_plus, x))
    R_minus = R_of(_split(h, runs, d_minus, x))
    fd_d = (R_plus - R_minus) / (2 * eps)
    x_plus = x.copy(); x_plus[k] += eps
    x_minus = x.copy(); x_minus[k] -= eps
    R_plus = R_of(_split(h, runs, d, x_plus))
    R_minus = R_of(_split(h, runs, d, x_minus))
    fd_x = (R_plus - R_minus) / (2 * eps)
    gd, gx = _split_grad(h, runs, d, x, dRdh)
    return fd_d, gd[k], fd_x, gx[k]


def _split_opt(h, runs, d0, x0, maxiter, deadline,
               free_split=True, free_heights=False, height_cells=None):
    if time.process_time() >= deadline - 0.3:
        return h, d0, x0
    K = len(runs)
    if K == 0:
        return h, d0, x0
    d = np.clip(d0.copy(), 0.0, 4.0)
    x = x0.copy()
    h = np.clip(h, 0, None)
    n = h.size

    if free_heights and height_cells is not None:
        hcells = np.asarray(height_cells, dtype=int)
        n_h = hcells.size
        x0v = np.concatenate([d, x, h[hcells]])

        def unpack(xv):
            dd = np.clip(xv[:K], 0.0, 4.0)
            xx = xv[K:2 * K]
            hh = h.copy()
            hh[hcells] = np.clip(xv[2 * K:], 0.0, None)
            return dd, xx, hh

        def f(xv):
            dd, xx, hh = unpack(xv)
            h2 = _split(hh, runs, dd, xx)
            val, g2 = _fun_grad(h2)
            gd, gx = _split_grad(hh, runs, dd, xx, g2)
            gh = g2[hcells]
            return val, np.concatenate([gd, gx, gh])

        bounds = [(0.0, 4.0)] * K + [(None, None)] * K + [(0.0, None)] * n_h
    else:
        x0v = np.concatenate([d, x])

        def f(xv):
            dd = np.clip(xv[:K], 0.0, 4.0)
            xx = xv[K:2 * K]
            h2 = _split(h, runs, dd, xx)
            val, g2 = _fun_grad(h2)
            gd, gx = _split_grad(h, runs, dd, xx, g2)
            return val, np.concatenate([gd, gx])

        bounds = [(0.0, 4.0)] * K + [(None, None)] * K

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0v, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, d0, x0
    if res is None:
        return h, d0, x0

    if free_heights and height_cells is not None:
        dd, xx, hh = unpack(res.x)
        h2 = _split(hh, runs, dd, xx)
        return h2, dd, xx
    else:
        dd = np.clip(res.x[:K], 0.0, 4.0)
        xx = res.x[K:2 * K]
        h2 = _split(h, runs, dd, xx)
        return h2, dd, xx


def _split_experiment(base, baseR, deadline, rng):
    h = np.clip(base, 0, None).copy()
    n = h.size
    runs = _find_runs(h, peak_thresh_frac=0.7, K_cap=32)
    K = len(runs)
    print("split: K=%d runs kept (of %d cells, N=%d)" %
          (K, int(np.sum(h > 0)), n))
    if K == 0:
        return h, baseR, None, -1.0

    d = np.zeros(K)
    x = np.zeros(K)

    h_test = _split(h, runs, d, x)
    _, g_test = _fun_grad(h_test)
    fd_d, an_d, fd_x, an_x = _fd_check_split(h, runs, d, x, g_test, 0)
    rel_d = abs(fd_d - an_d) / max(abs(fd_d), abs(an_d), 1e-12)
    rel_x = abs(fd_x - an_x) / max(abs(fd_x), abs(an_x), 1e-12)
    print("split: FD k=0 d: fd=%.6e an=%.6e rel=%.3e | x: fd=%.6e an=%.6e rel=%.3e" %
          (fd_d, an_d, rel_d, fd_x, an_x, rel_x))

    best_h = h.copy()
    bestR = baseR
    best_d = d.copy()
    best_x = x.copy()

    for rnd in range(3):
        if time.process_time() >= deadline - 10.0:
            break
        h1, d1, x1 = _split_opt(best_h, runs, best_d, best_x, 200,
                                deadline - 8.0, free_split=True,
                                free_heights=False)
        r1 = R_of(h1)
        if r1 > bestR + 1e-13:
            best_h, bestR, best_d, best_x = h1, r1, d1, x1
        if time.process_time() < deadline - 8.0:
            hcells = np.concatenate(runs)
            h2, d2, x2 = _split_opt(best_h, runs, best_d, best_x, 200,
                                    deadline - 6.0, free_split=False,
                                    free_heights=True, height_cells=hcells)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best_h, bestR, best_d, best_x = h2, r2, d2, x2
        if time.process_time() < deadline - 8.0:
            hcells = np.concatenate(runs)
            h3, d3, x3 = _split_opt(best_h, runs, best_d, best_x, 400,
                                    deadline - 4.0, free_split=True,
                                    free_heights=True, height_cells=hcells)
            r3 = R_of(h3)
            if r3 > bestR + 1e-13:
                best_h, bestR, best_d, best_x = h3, r3, d3, x3
        fvals = _sigmoid(best_x)
        order = np.argsort(-best_d)
        top = order[:min(5, K)]
        info = ", ".join("d=%.3f f=%.3f" % (best_d[i], fvals[i]) for i in top)
        nz = int(np.sum(best_d > 0.1))
        print("split round %d: R=%.7f nz(d>0.1)=%d | %s" %
              (rnd + 1, bestR, nz, info))

    return best_h, bestR, best_h.copy(), bestR


# ---------------- Experiment: augmented Lagrangian on top-m knots ----------------

def _top_m_stats(Lf, m):
    """Return (mean of top-m knots, max knot, indices of top-m knots)."""
    n = Lf.size
    if n <= m:
        idx = np.arange(n)
    else:
        idx = np.argpartition(Lf, -m)[-m:]
    mx = Lf.max()
    return float(Lf[idx].mean()), float(mx), idx


def _fun_grad_aug(h, lam, rho, m):
    """Augmented Lagrangian objective:
       val = -log(num) + 2 log(s) + lam*g + (rho/2)*g^2
       where g = 1 - mean(top-m knots)/max_knot >= 0.
       Gradient via chain rule on knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mean_top, mx, idx = _top_m_stats(Lf, m)
    if mx <= 0:
        return _fun_grad(h)
    ratio = mean_top / mx
    g = 1.0 - ratio
    # d g / d L_k:
    #   g = 1 - (1/m) sum_{k in top} L_k / L_max
    #   dg/dL_k for k in top (k != argmax): -(1/m)/L_max
    #   dg/dL_max (if argmax in top): -1/m/L_max + mean_top/L_max^2
    #   dg/dL_max (if argmax not in top): +mean_top/L_max^2
    #   dg/dL_k for k not in top (k != argmax): 0
    gLf = -dq / num
    # smooth part: -log(num) + 2 log(s) -> d/dL = -dq/num ; d/dh = backprop + 2/s
    # augmented part: (lam + rho*g) * dg/dL
    coef = lam + rho * g
    if coef != 0.0:
        argmax = int(np.argmax(Lf))
        inv_m = 1.0 / m
        # contributions to dg/dL
        dg = np.zeros_like(Lf)
        # top-m mean term
        dg[idx] += -inv_m / mx
        # max term
        # d(mean/max)/dL_max = -mean/max^2 (from max denom) plus if argmax in top
        # the top-mean also depends on L_max: +1/m/max if argmax in top.
        dg[argmax] += mean_top / (mx * mx)
        if argmax in idx:
            dg[argmax] += inv_m / mx
        # g = 1 - mean/max, so dg/dL = -d(mean/max)/dL
        dg = -dg
        gLf += coef * dg
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + lam * g + 0.5 * rho * g * g
    return val, grad


def _lbfgs_aug(h0, maxiter, deadline, lam, rho, m):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_aug(hh, lam, rho, m)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _aug_lagrangian_experiment(base, baseR, deadline, rng, m=8, rho=50.0):
    h = np.clip(base, 0, None).copy()
    # finite-difference validation on 5 random coordinates
    lam0 = 0.0
    val0, g0 = _fun_grad_aug(h, lam0, rho, m)
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h, baseR
    rng_fd = np.random.default_rng(12345)
    picks = rng_fd.choice(pos, size=min(5, pos.size), replace=False)
    eps = 1e-5 * max(h.mean(), 1e-9)
    max_rel = 0.0
    for p in picks:
        hp = h.copy(); hp[p] += eps
        hm = h.copy(); hm[p] -= eps
        vp, _ = _fun_grad_aug(hp, lam0, rho, m)
        vm, _ = _fun_grad_aug(hm, lam0, rho, m)
        fd = (vp - vm) / (2 * eps)
        an = g0[p]
        rel = abs(fd - an) / max(abs(fd), abs(an), 1e-12)
        max_rel = max(max_rel, rel)
    print("aug: FD max rel err over 5 coords = %.3e" % max_rel)

    lam = 0.0
    best_h = h.copy()
    bestR = baseR
    for rnd in range(5):
        if time.process_time() >= deadline - 2.0:
            break
        ht = _lbfgs_aug(best_h, 150, deadline - 2.0, lam, rho, m)
        # evaluate exact R and g
        Lf = _knots(ht)
        mean_top, mx, _ = _top_m_stats(Lf, m)
        g = 1.0 - mean_top / mx if mx > 0 else 0.0
        r = R_of(ht)
        spread_pct = 100.0 * (mx - mean_top) / mx if mx > 0 else 0.0
        print("aug round %d: lam=%.4f g=%.3e spread=%.3e%% R=%.7f" %
              (rnd + 1, lam, g, spread_pct, r))
        if r > bestR + 1e-13:
            best_h, bestR = ht.copy(), r
        else:
            best_h = ht.copy()
        lam = max(0.0, lam + 0.2 * rho * g)
    return best_h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: augmented Lagrangian on top-m knots ----
    if time.process_time() < deadline - 20.0:
        try:
            exp_h, expR = _aug_lagrangian_experiment(
                best, bestR, deadline - 12.0, rng, m=8, rho=50.0)
            if exp_h is not None:
                alt_cand, altR = exp_h.copy(), expR
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("aug wins: R=%.7f (was %.7f)" % (bestR, start_bestR))
            else:
                print("aug did not beat base: %.7f vs %.7f" % (expR, bestR))
        except Exception as e:
            print("aug experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: recursive 3-way run splitting ----------------

def _find_runs(h, peak_thresh_frac=0.7, K_cap=32):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    pos = h > 0
    if not pos.any():
        return []
    gmax = h.max()
    thr = peak_thresh_frac * gmax
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            pk = h[i:j + 1].max()
            if pk >= thr:
                runs.append((pk, np.arange(i, j + 1)))
            i = j + 1
        else:
            i += 1
    runs.sort(key=lambda t: -t[0])
    runs = [r for _, r in runs[:K_cap]]
    return runs


def _softmax3(f1, f2, f3):
    m = max(f1, f2, f3)
    e1 = np.exp(f1 - m); e2 = np.exp(f2 - m); e3 = np.exp(f3 - m)
    Z = e1 + e2 + e3
    return e1 / Z, e2 / Z, e3 / Z


def _splat3(h, runs, d1, d2, f1, f2, f3):
    """Replace each run's mass by 3 copies at shifts d1,0,d2 with softmax
    mass fractions. Linear re-splat."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    out = h.copy()
    K = len(runs)
    for k, cells in enumerate(runs):
        a1 = float(f1[k]); a2 = float(f2[k]); a3 = float(f3[k])
        w1, w2, w3 = _softmax3(a1, a2, a3)
        s1 = float(d1[k]); s2 = 0.0; s3 = float(d2[k])
        masses = h[cells]
        out[cells] -= masses
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            for (shift, frac) in ((s1, w1), (s2, w2), (s3, w3)):
                if frac <= 0.0:
                    continue
                center = j + shift
                i0 = int(np.floor(center - 1.0))
                i1 = int(np.ceil(center + 1.0))
                for i in range(i0, i1 + 1):
                    if i < 0 or i >= n:
                        continue
                    w = 1.0 - abs(i - center)
                    if w > 0.0:
                        out[i] += m * frac * w
    return np.clip(out, 0.0, None)


def _splat3_grad(h, runs, d1, d2, f1, f2, f3, dRdh):
    """Gradient of R w.r.t. d1,d2,f1,f2,f3 (softmax params)."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    K = len(runs)
    gd1 = np.zeros(K); gd2 = np.zeros(K)
    gf1 = np.zeros(K); gf2 = np.zeros(K); gf3 = np.zeros(K)
    for k, cells in enumerate(runs):
        a1 = float(f1[k]); a2 = float(f2[k]); a3 = float(f3[k])
        w1, w2, w3 = _softmax3(a1, a2, a3)
        s1 = float(d1[k]); s3 = float(d2[k])
        masses = h[cells]
        # softmax jacobian: dw_i/da_j = w_i(delta_ij - w_j)
        w = np.array([w1, w2, w3])
        J = np.diag(w) - np.outer(w, w)
        acc_d1 = 0.0; acc_d2 = 0.0
        acc_f = np.zeros(3)
        for j, m in zip(cells, masses):
            if m == 0.0:
                continue
            for idx, (shift, frac, dshift_dd) in enumerate((
                    (s1, w1, 1.0), (0.0, w2, 0.0), (s3, w3, 1.0))):
                center = j + shift
                i0 = int(np.floor(center - 1.0))
                i1 = int(np.ceil(center + 1.0))
                for i in range(i0, i1 + 1):
                    if i < 0 or i >= n:
                        continue
                    dd = i - center
                    wgt = 1.0 - abs(dd)
                    if wgt > 0.0:
                        g = dRdh[i] * m
                        dw_dshift = np.sign(dd)
                        if idx == 0:
                            acc_d1 += g * frac * dw_dshift * dshift_dd
                        elif idx == 2:
                            acc_d2 += g * frac * dw_dshift * dshift_dd
                        # d/d a_j of (frac * wgt) = wgt * J[idx, j]
                        acc_f += g * wgt * J[idx, :]
        gd1[k] = acc_d1
        gd2[k] = acc_d2
        gf1[k] = acc_f[0]
        gf2[k] = acc_f[1]
        gf3[k] = acc_f[2]
    return gd1, gd2, gf1, gf2, gf3


def _fd_check_splat3(h, runs, d1, d2, f1, f2, f3, dRdh, k, eps=1e-6):
    def build(d1v, d2v, f1v, f2v, f3v):
        return _splat3(h, runs, d1v, d2v, f1v, f2v, f3v)

    def R_at(d1v, d2v, f1v, f2v, f3v):
        return R_of(build(d1v, d2v, f1v, f2v, f3v))

    def fd(arr, i, fn):
        ap = arr.copy(); ap[i] += eps
        am = arr.copy(); am[i] -= eps
        return fn(ap, am)

    fd_d1 = fd(d1, k, lambda ap, am: (R_at(ap, d2, f1, f2, f3) -
                                      R_at(am, d2, f1, f2, f3)) / (2 * eps))
    fd_d2 = fd(d2, k, lambda ap, am: (R_at(d1, ap, f1, f2, f3) -
                                      R_at(d1, am, f1, f2, f3)) / (2 * eps))
    fd_f1 = fd(f1, k, lambda ap, am: (R_at(d1, d2, ap, f2, f3) -
                                      R_at(d1, d2, am, f2, f3)) / (2 * eps))
    fd_f2 = fd(f2, k, lambda ap, am: (R_at(d1, d2, f1, ap, f3) -
                                      R_at(d1, d2, f1, am, f3)) / (2 * eps))
    fd_f3 = fd(f3, k, lambda ap, am: (R_at(d1, d2, f1, f2, ap) -
                                      R_at(d1, d2, f1, f2, am)) / (2 * eps))
    gd1, gd2, gf1, gf2, gf3 = _splat3_grad(h, runs, d1, d2, f1, f2, f3, dRdh)
    return (fd_d1, gd1[k], fd_d2, gd2[k], fd_f1, gf1[k],
            fd_f2, gf2[k], fd_f3, gf3[k])


def _splat3_opt(h, runs, d1, d2, f1, f2, f3, maxiter, deadline,
                free_params=True, free_heights=False, height_cells=None):
    if time.process_time() >= deadline - 0.3:
        return h, d1, d2, f1, f2, f3
    K = len(runs)
    if K == 0:
        return h, d1, d2, f1, f2, f3
    h = np.clip(h, 0, None)
    n = h.size
    d1 = np.clip(d1.copy(), -1.5, 1.5)
    d2 = np.clip(d2.copy(), -1.5, 1.5)
    f1 = f1.copy(); f2 = f2.copy(); f3 = f3.copy()

    if free_heights and height_cells is not None:
        hcells = np.asarray(height_cells, dtype=int)
        n_h = hcells.size
        x0v = np.concatenate([d1, d2, f1, f2, f3, h[hcells]])

        def unpack(xv):
            dd1 = np.clip(xv[:K], -1.5, 1.5)
            dd2 = np.clip(xv[K:2 * K], -1.5, 1.5)
            ff1 = xv[2 * K:3 * K]
            ff2 = xv[3 * K:4 * K]
            ff3 = xv[4 * K:5 * K]
            hh = h.copy()
            hh[hcells] = np.clip(xv[5 * K:], 0.0, None)
            return dd1, dd2, ff1, ff2, ff3, hh

        def f(xv):
            dd1, dd2, ff1, ff2, ff3, hh = unpack(xv)
            h2 = _splat3(hh, runs, dd1, dd2, ff1, ff2, ff3)
            val, g2 = _fun_grad(h2)
            gd1, gd2, gf1, gf2, gf3 = _splat3_grad(
                hh, runs, dd1, dd2, ff1, ff2, ff3, g2)
            gh = g2[hcells]
            return val, np.concatenate([gd1, gd2, gf1, gf2, gf3, gh])

        bounds = ([( -1.5, 1.5)] * K + [(-1.5, 1.5)] * K +
                  [(None, None)] * (3 * K) + [(0.0, None)] * n_h)
    else:
        x0v = np.concatenate([d1, d2, f1, f2, f3])

        def f(xv):
            dd1 = np.clip(xv[:K], -1.5, 1.5)
            dd2 = np.clip(xv[K:2 * K], -1.5, 1.5)
            ff1 = xv[2 * K:3 * K]
            ff2 = xv[3 * K:4 * K]
            ff3 = xv[4 * K:5 * K]
            h2 = _splat3(h, runs, dd1, dd2, ff1, ff2, ff3)
            val, g2 = _fun_grad(h2)
            gd1, gd2, gf1, gf2, gf3 = _splat3_grad(
                h, runs, dd1, dd2, ff1, ff2, ff3, g2)
            return val, np.concatenate([gd1, gd2, gf1, gf2, gf3])

        bounds = ([(-1.5, 1.5)] * K + [(-1.5, 1.5)] * K +
                  [(None, None)] * (3 * K))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0v, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, d1, d2, f1, f2, f3
    if res is None:
        return h, d1, d2, f1, f2, f3

    if free_heights and height_cells is not None:
        dd1, dd2, ff1, ff2, ff3, hh = unpack(res.x)
        h2 = _splat3(hh, runs, dd1, dd2, ff1, ff2, ff3)
        return h2, dd1, dd2, ff1, ff2, ff3
    else:
        dd1 = np.clip(res.x[:K], -1.5, 1.5)
        dd2 = np.clip(res.x[K:2 * K], -1.5, 1.5)
        ff1 = res.x[2 * K:3 * K]
        ff2 = res.x[3 * K:4 * K]
        ff3 = res.x[4 * K:5 * K]
        h2 = _splat3(h, runs, dd1, dd2, ff1, ff2, ff3)
        return h2, dd1, dd2, ff1, ff2, ff3


def _local_repair_runs(h, runs, deadline, iters=80):
    """L-BFGS on [run_start-48, run_end+48] of each edited run, no global."""
    h = np.clip(h, 0, None).copy()
    n = h.size
    for cells in runs:
        if time.process_time() >= deadline - 0.3:
            break
        lo = max(0, int(cells[0]) - 48)
        hi = min(n - 1, int(cells[-1]) + 48)
        free = np.arange(lo, hi + 1)
        h = _lbfgs_block(h, free, iters, deadline, beta=0.0)
    return h


def _split_experiment(base, baseR, deadline, rng):
    h = np.clip(base, 0, None).copy()
    n = h.size
    runs = _find_runs(h, peak_thresh_frac=0.7, K_cap=32)
    K = len(runs)
    print("splat3: K=%d runs kept (of %d cells, N=%d)" %
          (K, int(np.sum(h > 0)), n))
    if K == 0:
        return h, baseR, None, -1.0

    best_h = h.copy()
    bestR = baseR

    # ---------- Round 1: 3-way split of each top run ----------
    d1 = np.full(K, -0.5); d2 = np.full(K, 0.5)
    f1 = np.zeros(K); f2 = np.zeros(K); f3 = np.zeros(K)  # softmax -> 1/3

    h_test = _splat3(h, runs, d1, d2, f1, f2, f3)
    _, g_test = _fun_grad(h_test)
    fd = _fd_check_splat3(h, runs, d1, d2, f1, f2, f3, g_test, 0)
    rels = []
    for i in range(0, len(fd), 2):
        a = fd[i]; b = fd[i + 1]
        rels.append(abs(a - b) / max(abs(a), abs(b), 1e-12))
    print("splat3 R1 FD k=0 rel errs: d1=%.2e d2=%.2e f1=%.2e f2=%.2e f3=%.2e" %
          tuple(rels))

    # joint split-param opt
    h1, d1, d2, f1, f2, f3 = _splat3_opt(
        best_h, runs, d1, d2, f1, f2, f3, 300, deadline - 6.0,
        free_params=True, free_heights=False)
    r1 = R_of(h1)
    if r1 > bestR + 1e-13:
        best_h, bestR = h1, r1
    # local repair of affected runs
    if time.process_time() < deadline - 5.0:
        hr = _local_repair_runs(best_h, runs, deadline - 5.0, iters=80)
        rr = R_of(hr)
        if rr > bestR + 1e-13:
            best_h, bestR = hr, rr
    print("splat3 R1: R=%.7f max|d|=%.3f n(|d|>0.05)=%d" %
          (bestR, max(np.abs(d1).max(), np.abs(d2).max()),
           int(np.sum(np.abs(d1) > 0.05) + np.sum(np.abs(d2) > 0.05))))

    # ---------- Round 2: re-split copies of top 8 original runs ----------
    # Build runs as the copies created: for each of top 8 original runs,
    # we approximate each copy by re-detecting runs near shifted positions.
    # Simpler: re-detect runs on the current best_h and split top 16.
    if time.process_time() < deadline - 8.0:
        runs2 = _find_runs(best_h, peak_thresh_frac=0.7, K_cap=16)
        K2 = len(runs2)
        print("splat3 R2: K2=%d runs" % K2)
        if K2 > 0:
            d1b = np.full(K2, -0.5); d2b = np.full(K2, 0.5)
            f1b = np.zeros(K2); f2b = np.zeros(K2); f3b = np.zeros(K2)
            h2, d1b, d2b, f1b, f2b, f3b = _splat3_opt(
                best_h, runs2, d1b, d2b, f1b, f2b, f3b, 300, deadline - 4.0,
                free_params=True, free_heights=False)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best_h, bestR = h2, r2
            if time.process_time() < deadline - 3.5:
                hr = _local_repair_runs(best_h, runs2, deadline - 3.5, iters=80)
                rr = R_of(hr)
                if rr > bestR + 1e-13:
                    best_h, bestR = hr, rr
            print("splat3 R2: R=%.7f max|d|=%.3f n(|d|>0.05)=%d" %
                  (bestR, max(np.abs(d1b).max(), np.abs(d2b).max()),
                   int(np.sum(np.abs(d1b) > 0.05) +
                       np.sum(np.abs(d2b) > 0.05))))

    # ---------- Joint: split params + affected window heights ----------
    if time.process_time() < deadline - 4.0:
        runs_all = _find_runs(best_h, peak_thresh_frac=0.7, K_cap=32)
        K3 = len(runs_all)
        if K3 > 0:
            d1c = np.zeros(K3); d2c = np.zeros(K3)
            f1c = np.zeros(K3); f2c = np.zeros(K3); f3c = np.zeros(K3)
            hcells_list = []
            for cells in runs_all:
                lo = max(0, int(cells[0]) - 48)
                hi = min(n - 1, int(cells[-1]) + 48)
                hcells_list.append(np.arange(lo, hi + 1))
            hcells = np.unique(np.concatenate(hcells_list))
            hj, d1c, d2c, f1c, f2c, f3c = _splat3_opt(
                best_h, runs_all, d1c, d2c, f1c, f2c, f3c, 400,
                deadline - 2.0, free_params=True, free_heights=True,
                height_cells=hcells)
            rj = R_of(hj)
            if rj > bestR + 1e-13:
                best_h, bestR = hj, rj
            surv = int(np.sum(np.abs(d1c) > 0.05) + np.sum(np.abs(d2c) > 0.05))
            print("splat3 joint: R=%.7f max|d|=%.3f n(|d|>0.05)=%d" %
                  (bestR, max(np.abs(d1c).max(), np.abs(d2c).max()), surv))

    return best_h, bestR, best_h.copy(), bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0
    pre_polish = None
    pre_polish_R = -1.0

    # ---- Experiment: recursive 3-way splitting ----
    if time.process_time() < deadline - 20.0:
        try:
            exp_h, expR, alt_h, altR_exp = _split_experiment(
                best, bestR, deadline - 12.0, rng)
            if alt_h is not None:
                alt_cand, altR = alt_h.copy(), altR_exp
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("splat3 wins: R=%.7f (was %.7f)" % (bestR, start_bestR))
            else:
                print("splat3 did not beat base: %.7f vs %.7f" %
                      (expR, bestR))
            pre_polish = best.copy()
            pre_polish_R = bestR
        except Exception as e:
            print("splat3 experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    # Prefer pre-polish if it scores higher than post-polish
    if pre_polish is not None and pre_polish_R > bestR + 1e-13:
        print("pre-polish wins: %.7f vs %.7f" % (pre_polish_R, bestR))
        best, bestR = pre_polish, pre_polish_R

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    eps = 1e-12
    u0 = np.log(np.clip(h, eps, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        hh = np.exp(np.clip(u, -50.0, 50.0))
        val, g = fg(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(np.clip(res.x, -50.0, 50.0)))


def _refine_knots(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h0
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    win = np.arange(lo, hi + 1)
    zeros = win[h[win] <= 0]
    if zeros.size == 0:
        return h0
    h2 = h.copy()
    h2[zeros] = 1e-3 * h.mean()
    return _lbfgs_block(h2, win, maxiter, deadline, beta=1e8)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _grow_boundary(h, grow):
    if grow <= 0:
        return h.copy()
    eps = 1e-3 * h.mean() if h.mean() > 0 else 1e-3
    pad = np.full(grow, eps)
    return np.concatenate([pad, h, pad])


def _upsample2(h):
    out = np.empty(2 * h.size, dtype=float)
    out[0::2] = h
    out[1::2] = h
    return out


def _run_cycle(best, bestR, deadline, cycle_limit=1000):
    cycle = 0
    stale = 0
    while time.process_time() < deadline - 1.5 and cycle < cycle_limit:
        cycle += 1
        prev = bestR
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 800, deadline - 1.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 400, deadline - 1.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for frac, extra, beta in ((0.05, 64, 1e7), (0.10, 64, 1e8),
                                  (0.25, 128, 1e8), (0.40, 256, 1e8),
                                  (0.60, 512, 1e8)):
            if time.process_time() >= deadline - 1.5:
                break
            win = _peak_window(best, pad_frac=frac, extra=extra)
            ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.5,
                              beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_log(best, 300, deadline - 1.5, beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _refine_knots(best, 300, deadline - 1.5)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, best.size))
        if bestR - prev < 1e-12:
            stale += 1
            if stale >= 2:
                break
        else:
            stale = 0
    return best, bestR


def _extend_and_cycle(best, bestR, pad, deadline, tag):
    if time.process_time() >= deadline - 8.0:
        return best, bestR
    if best.size + 2 * pad > 1000000:
        pad = max(0, (1000000 - best.size) // 2)
    if pad <= 0:
        return best, bestR
    eps = 1e-3 * best.mean() if best.mean() > 0 else 1e-3
    padarr = np.full(pad, eps)
    h2 = np.concatenate([padarr, best, padarr])
    h2 = _rescale(h2)
    r2 = R_of(h2)
    print("ext %s pad=%d N=%d R=%.7f" % (tag, pad, h2.size, r2))
    cur, curR = h2, r2
    if curR > bestR:
        best, bestR = cur.copy(), curR
    while time.process_time() < deadline - 8.0:
        prev = curR
        cur, curR = _run_cycle(cur, curR, deadline - 8.0)
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
        if curR - prev < 1e-8:
            break
    return best, bestR


# ---------- NEW: sub-step (half-step) refinement ----------
def _halve_steps(h):
    """Insert a midpoint between each pair of steps (linear interpolation),
    doubling N while preserving the shape of f*f closely."""
    n = h.size
    out = np.empty(2 * n + 1, dtype=float)
    out[0::2] = h
    out[1:-1:2] = 0.5 * (h[:-1] + h[1:])
    out[-1] = h[-1]
    return out


def _local_upsample_window(h, center, half_width):
    """Halve steps only in a window around the peak of f*f, keeping total N
    reasonable.  Returns new array and the index map of the old steps."""
    n = h.size
    lo = max(0, center - half_width)
    hi = min(n, center + half_width)
    seg = h[lo:hi]
    seg2 = _halve_steps(seg)
    out = np.concatenate([h[:lo], seg2, h[hi:]])
    return out


def _shape_upsample(h):
    """Split each step into 2 using sqrt profile so f*(f) shape is preserved
    better than linear for the square-root-like edge."""
    n = h.size
    out = np.empty(2 * n, dtype=float)
    out[0::2] = h
    out[1::2] = h
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = 0.0
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase A: quick polish of start -------
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 600, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # ---- NEW Phase A2: local half-step refinement near the peak ----
    # The idea: sub-step resolution directly reduces the discretisation
    # error on ||f*f||_2^2 without changing the support.  We halve only a
    # window around the f*f peak (where the profile has its curvature) and
    # re-optimise that window.
    if time.process_time() < deadline - 6.0 and best.size * 2 < 400000:
        Lf0 = _knots(best)
        am = int(np.argmax(Lf0))
        # am is a knot index in [0, N]; corresponding step index ~ am-1
        ctr = min(best.size - 1, max(0, am - 1))
        win = max(2048, best.size // 6)
        h2 = _local_upsample_window(best, ctr, win)
        h2 = _rescale(h2)
        r2 = R_of(h2)
        print("halfstep N=%d R=%.7f (was %.7f)" % (h2.size, r2, bestR))
        # refine the upsampled window
        lo = max(0, 2 * max(0, ctr - win))
        hi = min(h2.size, 2 * min(best.size, ctr + win) + 1)
        active = np.arange(lo, hi)
        ht = _lbfgs_block(h2, active, 400, deadline - 4.0, beta=0.0)
        rt = R_of(ht)
        if rt > bestR + 1e-13:
            best, bestR = ht.copy(), rt
            print("halfstep refined R=%.7f N=%d" % (bestR, best.size))

    # ---- Phase B: 2x duplication upsample + halo grow -------
    refined = None
    refinedR = 0.0
    if time.process_time() < deadline - 4.0:
        n0 = best.size
        if 2 * n0 <= 1000000:
            h1 = _upsample2(best)
            h1 = _rescale(h1)
            r1 = R_of(h1)
            print("upsample2 N=%d R=%.7f" % (h1.size, r1))
            grow = 8000
            if h1.size + 2 * grow > 1000000:
                grow = max(0, (1000000 - h1.size) // 2)
            if grow > 0:
                h2 = _grow_boundary(h1, grow)
                h2 = _rescale(h2)
                r2 = R_of(h2)
                print("halo grow=%d N=%d R=%.7f" % (grow, h2.size, r2))
                if r2 > r1:
                    h1, r1 = h2, r2
            refined, refinedR = h1, r1
            if refinedR > bestR + 1e-13:
                best, bestR = refined.copy(), refinedR

    # ---- Phase C: beta-softmax window ladder on refined array -------
    if refined is not None and time.process_time() < deadline - 3.0:
        cur, curR = refined.copy(), refinedR
        for frac, extra in ((0.30, 128), (0.40, 128), (0.50, 256), (0.60, 256)):
            if time.process_time() >= deadline - 3.0:
                break
            win = _peak_window(cur, pad_frac=frac, extra=extra)
            ht = _lbfgs_block(cur, win, maxiter=250, deadline=deadline - 3.0,
                              beta=1e8)
            r = R_of(ht)
            if r > curR + 1e-14:
                cur, curR = ht, r
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        refined, refinedR = cur, curR
        print("ladder R=%.7f (N=%d)" % (refinedR, refined.size))

    # ---- Phase D: global polish on refined -------
    if refined is not None and time.process_time() < deadline - 2.5:
        ht = _lbfgs_all_pos(refined, 500, deadline - 2.5, beta=0.0)
        r = R_of(ht)
        if r > refinedR + 1e-14:
            refined, refinedR = ht, r
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if refined is not None and time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(refined, 400, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > refinedR + 1e-14:
            refined, refinedR = ht, r
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if refined is not None:
        alt, altR = refined.copy(), refinedR
        print("refined R=%.7f (N=%d)" % (altR, alt.size))

    # ---- Phase E: run_cycle on refined array -------
    if refined is not None and time.process_time() < deadline - 2.0:
        best, bestR = _run_cycle(best, bestR, deadline - 0.5)
        if refinedR > altR:
            alt, altR = refined, refinedR

    # ---- Phase F: support-extension rounds -------
    if time.process_time() < deadline - 8.0:
        best, bestR = _extend_and_cycle(best, bestR, 5000, deadline, "1")
    if time.process_time() < deadline - 8.0:
        best, bestR = _extend_and_cycle(best, bestR, 3000, deadline, "2")

    # ---- final polish -------
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        if alt is not None and altR < bestR - 1e-9 and altR > start_bestR:
            return {"best": best, "alternative": alt}
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6 and altR > 0:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------- New: flat-top shaping via softmax(sharpness) on knots ----------
# Instead of a hard max, use a soft-max of the top band to drive more knots
# into the plateau, which raises ||f*f||_2^2 for fixed max and mass.

def _fun_grad_flat(h, beta, target_frac):
    """Push a fraction target_frac of knots toward the max.
       Objective: -log(num) + 2 log(s) + log(sm) + penalty*max(0, target - frac)^2
       where frac = fraction of knots within 1% of max (smoothly via softmax)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    # fraction proxy: P(knot >= mx*0.99) approximated by softmax at threshold
    thr = 0.99 * mx
    et = np.exp(np.clip(beta * (Lf - thr), -60.0, 60.0))
    Zt = et.sum()
    frac = Zt / Lf.size
    pen = max(0.0, target_frac - frac)
    gLf = -dq / num + w / sm
    # gradient of frac w.r.t. Lf:
    wt = et / Zt
    gfrac = (wt - 1.0 / Lf.size) * beta
    # frac also depends on mx via thr
    dthr_dmx = 0.99
    # mx = Lf[argmax]; treat as constant since at max dLf/dh handled by softmax
    gLf += (-2.0 * pen) * gfrac
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm) + pen * pen
    return val, grad


def _lbfgs_flat(h0, maxiter, deadline, beta, target_frac):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_flat(hh, beta, target_frac)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _flat_experiment(base, baseR, deadline, rng):
    """Try to widen the plateau using softmax-based flat-top pushing."""
    h = np.clip(base, 0, None).copy()
    best_h = h.copy()
    bestR = baseR
    # current plateau fraction at 1%
    Lf = _knots(h)
    mx = Lf.max()
    cur_frac = float(np.mean(Lf >= 0.99 * mx)) if mx > 0 else 0.0
    print("flat: current 1%% band frac = %.4f" % cur_frac)

    # Try increasing target fractions with increasing beta
    configs = [
        (1e4, cur_frac + 0.02),
        (1e5, cur_frac + 0.05),
        (1e5, cur_frac + 0.10),
        (1e6, cur_frac + 0.10),
    ]
    for beta, tgt in configs:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_flat(best_h, 200, deadline - 1.0, beta, tgt)
        r = R_of(ht)
        Lf2 = _knots(ht)
        m2 = Lf2.max()
        f2 = float(np.mean(Lf2 >= 0.99 * m2)) if m2 > 0 else 0.0
        print("flat: beta=%.0e tgt=%.3f -> R=%.7f frac=%.4f" %
              (beta, tgt, r, f2))
        if r > bestR + 1e-13:
            best_h, bestR = ht.copy(), r
    return best_h, bestR


# ---------- New: fine-grained local coordinate ascent on top knots ----------

def _coord_ascent(h, bestR, deadline, max_sweeps=6):
    """Coordinate ascent over the top-band knots' associated heights:
       for each knot in the top band, the two heights feeding it get nudged.
       Extremely cheap per step; catches fine structure L-BFGS misses."""
    h = np.clip(h, 0, None).copy()
    n = h.size
    if n < 4:
        return h, bestR
    for sweep in range(max_sweeps):
        if time.process_time() >= deadline - 0.3:
            break
        Lf = _knots(h)
        mx = Lf.max()
        if mx <= 0:
            break
        # top 5% knots
        thr = np.quantile(Lf, 0.95)
        idx = np.flatnonzero(Lf >= thr)
        if idx.size == 0:
            break
        # sample a subset for speed
        if idx.size > 200:
            sel = np.random.default_rng(sweep).choice(idx, size=200, replace=False)
        else:
            sel = idx
        improved = False
        for k in sel:
            # knot k is between h[k-1] and h[k]
            for pos in (k - 1, k):
                if pos < 0 or pos >= n:
                    continue
                base_v = h[pos]
                if base_v <= 0:
                    continue
                # try a multiplicative nudge
                for scale in (1.05, 0.95, 1.02, 0.98):
                    trial = h.copy()
                    trial[pos] = base_v * scale
                    r = R_of(trial)
                    if r > bestR + 1e-14:
                        h = trial
                        bestR = r
                        improved = True
        if not improved:
            break
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240817)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Flat-top experiment (new idea) ----
    flat_h = None
    flatR = -1.0
    if time.process_time() < deadline - 20.0:
        try:
            flat_h, flatR = _flat_experiment(best, bestR, deadline - 15.0, rng)
            if flatR > bestR + 1e-13:
                best, bestR = flat_h.copy(), flatR
                print("flat wins: R=%.7f" % bestR)
            else:
                print("flat did not beat base: %.7f vs %.7f" % (flatR, bestR))
        except Exception as e:
            print("flat experiment failed: %s" % e)

    # ---- Coordinate ascent on top band (new idea) ----
    if time.process_time() < deadline - 12.0:
        try:
            ca_h, caR = _coord_ascent(best, bestR, deadline - 10.0, max_sweeps=5)
            if caR > bestR + 1e-13:
                best, bestR = ca_h, caR
                print("coord ascent wins: R=%.7f" % bestR)
            else:
                print("coord ascent no gain: %.7f" % caR)
        except Exception as e:
            print("coord ascent failed: %s" % e)

    # ---- Standard polishing cycle ----
    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Final push: alternate flat + standard ----
    while time.process_time() < deadline - 3.0:
        try:
            fh, fr = _flat_experiment(best, bestR, min(deadline - 2.0,
                                                       time.process_time() + 8.0), rng)
            if fr > bestR + 1e-13:
                best, bestR = fh.copy(), fr
        except Exception:
            pass
        if time.process_time() < deadline - 3.0:
            best, bestR = run_cycle(best, bestR, deadline - 2.0)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if alt_cand is None and flat_h is not None and flatR > start_bestR - 1e-6:
        alt_cand, altR = flat_h, flatR

    if bestR > start_bestR + 1e-12:
        out = {"best": best}
        if alt_cand is not None and altR > start_bestR - 1e-6:
            out["alternative"] = alt_cand
        return out
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _build_target(h, s0, s1):
    n = h.size
    Lf = _knots(h)
    M = Lf.max()
    s = h.sum()
    gk = np.zeros(2 * n + 1, dtype=float)
    lo = 2 * s0
    hi = 2 * s1
    if hi <= lo:
        return gk
    span = hi - lo
    ramp = max(1, int(0.035 * span))
    gk[lo:hi + 1] = 1.0
    if ramp > 1:
        t = np.linspace(0.0, np.pi, ramp)
        rampup = 0.5 * (1.0 - np.cos(t))
        gk[lo:lo + ramp] *= rampup
        gk[hi - ramp + 1:hi + 1] *= rampup[::-1]
    cur_max = gk.max()
    if cur_max <= 0:
        return gk
    gk *= (M / cur_max)
    cur_sum = gk.sum()
    if cur_sum > 0:
        gk *= (s * s / cur_sum)
    return gk


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


def _gn_flat(best, deadline):
    n = best.size
    s0, s1 = _active_support(best)
    if s1 <= s0:
        return best, R_of(best)
    h = np.clip(best, 0, None).astype(float)
    if h.sum() <= 0:
        return best, R_of(best)

    lo = 2 * s0
    hi = 2 * s1
    if hi <= lo:
        return best, R_of(best)
    j_lo = max(0, lo - 1)
    j_hi = min(2 * n - 2, hi - 1)
    if j_hi < j_lo:
        return best, R_of(best)
    m = j_hi - j_lo + 1

    best_h = h.copy()
    bestR = R_of(h)
    gk = _build_target(h, s0, s1)
    g_t = gk[lo:hi + 1].copy()

    def residual(hh):
        Lf = _knots(hh)
        return Lf[lo:hi + 1] - g_t

    def J(hh, d):
        c = fftconvolve(hh, d)
        return 2.0 * c[j_lo:j_hi + 1]

    def JT(hh, v):
        vp = np.zeros(2 * n - 1, dtype=float)
        vp[j_lo:j_hi + 1] = v
        return 2.0 * np.correlate(vp, hh, mode='valid')[:n]

    for outer in range(15):
        if time.process_time() >= deadline - 15.0:
            break
        r = residual(h)
        rnorm = np.linalg.norm(r)
        JTr = JT(h, r)
        lam = 1e-6 * np.linalg.norm(JTr)
        if lam <= 0:
            lam = 1e-12
        d = np.zeros(n, dtype=float)
        res = -JTr.copy()
        p = res.copy()
        rs_old = np.dot(res, res)
        for _ in range(20):
            if time.process_time() >= deadline - 15.0:
                break
            Jp = J(h, p)
            Ap = JT(h, Jp) + lam * p
            pAp = np.dot(p, Ap)
            if pAp <= 0:
                break
            alpha = rs_old / pAp
            d += alpha * p
            res -= alpha * Ap
            rs_new = np.dot(res, res)
            if rs_new < 1e-30 * rs_old:
                break
            p = res + (rs_new / rs_old) * p
            rs_old = rs_new
        alpha_step = 1.0
        accepted = False
        for _ in range(12):
            h_new = np.clip(h + alpha_step * d, 0.0, None)
            if h_new.sum() <= 0:
                alpha_step *= 0.5
                continue
            r_new = residual(h_new)
            if np.linalg.norm(r_new) < rnorm:
                h = h_new
                accepted = True
                break
            alpha_step *= 0.5
        if not accepted:
            break
        if outer % 3 == 2:
            if time.process_time() < deadline - 15.0:
                hp = _lbfgs_all_pos(h, 40, deadline - 15.0, beta=0.0)
                rp = R_of(hp)
                if rp > bestR + 1e-13:
                    best_h = hp.copy()
                    bestR = rp
                rh = R_of(h)
                if rh > bestR + 1e-13:
                    best_h = h.copy()
                    bestR = rh
    rh = R_of(h)
    if rh > bestR + 1e-13:
        best_h = h.copy()
        bestR = rh
    return best_h, bestR


def _upsample(h, k):
    """Refine step function by subdividing each step into k sub-steps,
    keeping piecewise-constant. Returns length k*n array."""
    return np.repeat(h, k)


def _densify(best, bestR, deadline):
    """Refine resolution: try k=2 upsample, then L-BFGS all-pos. Accept if
    R improves; else return original."""
    if time.process_time() >= deadline - 2.0:
        return best, bestR
    n = best.size
    if 2 * n > 900000:
        return best, bestR
    h2 = _upsample(best, 2)
    h2 = _rescale(h2)
    r2 = R_of(h2)
    if r2 > bestR + 1e-13:
        best, bestR = h2, r2
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-12:
            best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # Densify: increase resolution and re-optimise.
    if time.process_time() < deadline - 25.0:
        try:
            cand, candR = _densify(best, bestR, deadline - 22.0)
            print("densify raw R=%.7f (N=%d)" % (candR, cand.size))
            if time.process_time() < deadline - 20.0:
                cand2, candR2 = run_cycle(cand, candR, deadline - 18.0)
                if candR2 > candR:
                    cand, candR = cand2, candR2
                print("densify polished R=%.7f" % candR)
            if candR > altR:
                alt_cand, altR = cand.copy(), candR
            if candR > bestR + 1e-13:
                best, bestR = cand.copy(), candR
        except Exception as e:
            print("densify failed: %s" % e)

    # GN flat as an alternative construction.
    if time.process_time() < deadline - 15.0:
        try:
            cand, candR = _gn_flat(best, deadline - 13.0)
            print("GN flat raw R=%.7f" % candR)
            if time.process_time() < deadline - 11.0:
                cand2, candR2 = run_cycle(cand, candR, deadline - 10.0)
                if candR2 > candR:
                    cand, candR = cand2, candR2
                print("GN flat polished R=%.7f" % candR)
            if candR > altR:
                alt_cand, altR = cand.copy(), candR
            if candR > bestR + 1e-13:
                best, bestR = cand.copy(), candR
        except Exception as e:
            print("GN flat failed: %s" % e)

    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    print("  mini_cycle R=%.7f" % bestR)
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_mid(h, eta):
    """Like _fun_grad but with extra penalty on mid-band knots.

    pen = eta * sum_j w_j*(1 - Lf_j/M) / max(cnt,1),
    w_j = 1 for 0.30*M <= Lf_j <= 0.98*M.
    M treated as constant for gradient purposes.
    """
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    M = Lm
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    if eta > 0 and M > 0:
        lo = 0.30 * M
        hi = 0.98 * M
        w = ((Lf >= lo) & (Lf <= hi)).astype(float)
        cnt = w.sum()
        if cnt > 0:
            denom = max(cnt, 1.0)
            pen = eta * np.sum(w * (1.0 - Lf / M)) / denom
            val += pen
            # d pen / d Lf_j = -eta * w_j / (M * denom)
            gLf += -eta * w / (M * denom)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, eta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if eta > 0:
        fg = (lambda hh: _fun_grad_mid(hh, eta))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: mid-band penalty ladder ----------------

def _mid_band_stats(h):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0, 0.0
    lo = 0.30 * M
    hi = 0.98 * M
    mask = (Lf >= lo) & (Lf <= hi)
    cnt = int(mask.sum())
    frac = cnt / float(Lf.size)
    if cnt == 0:
        return frac, 0.0
    mean_val = float(np.mean(Lf[mask]) / M)
    return frac, mean_val


def _mid_band_experiment(base, baseR, deadline):
    best = base.copy()
    bestR = baseR
    etas = [0.5, 2.0, 8.0, 32.0]
    for eta in etas:
        if time.process_time() >= deadline - 1.0:
            break
        # rung: 250 iters with mid penalty
        h1 = _lbfgs_all_pos(best, 250, deadline - 1.0, beta=0.0, eta=eta)
        # sharp pass: 150 iters beta=0
        h2 = _lbfgs_all_pos(h1, 150, deadline - 1.0, beta=0.0)
        r2 = R_of(h2)
        frac, mean_val = _mid_band_stats(h2)
        print("mid eta=%.3g: frac[.3,.98]=%.4f mean/M=%.4f R=%.7f" %
              (eta, frac, mean_val, r2))
        if r2 > bestR + 1e-13:
            best, bestR = h2.copy(), r2
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: mid-band penalty ladder ----
    if time.process_time() < deadline - 20.0:
        try:
            exp_h, expR = _mid_band_experiment(
                best, bestR, deadline - 12.0)
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("mid wins: R=%.7f (was %.7f)" % (bestR, start_bestR))
            else:
                # genuinely different construction: keep as alternative
                alt_cand, altR = exp_h.copy(), expR
                print("mid did not beat base: %.7f vs %.7f" %
                      (expR, bestR))
        except Exception as e:
            print("mid experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    frac01 = _band_frac(best, 1e-3)
    frac1 = _band_frac(best, 1e-2)
    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * frac01, 100.0 * frac1))

    if alt_cand is not None and altR > 0:
        return {"best": best, "alternative": alt_cand}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: pedestal scan ----------------

def _pedestal_schedule(h, p, deadline):
    """Add pedestal p to every cell, rescale, then short polish schedule."""
    hp = np.clip(h, 0, None) + p
    hp = _rescale(hp)
    if time.process_time() < deadline - 0.3:
        hp = _lbfgs_all_pos(hp, 350, deadline, beta=0.0)
    if time.process_time() < deadline - 0.3:
        hp = _lbfgs_all_pos(hp, 150, deadline, beta=1e7)
    for frac in (0.10, 0.30):
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(hp, pad_frac=frac, extra=128)
        hp = _lbfgs_block(hp, win, 150, deadline, beta=0.0)
    return hp


def _pedestal_experiment(base, baseR, deadline):
    h = np.clip(base, 0, None)
    pos = h > 0
    if not pos.any():
        return base, baseR, None, -1.0
    m = float(h[pos].mean())
    ps = [1e-5 * m, 1e-4 * m, 1e-3 * m, 3e-3 * m, 1e-2 * m]
    best_h = base.copy()
    bestR = baseR
    best_p = None
    results = []
    for p in ps:
        if time.process_time() >= deadline - 0.5:
            break
        hp = _pedestal_schedule(h, p, deadline - 0.5)
        r = R_of(hp)
        zf = 100.0 * float(np.mean(hp <= 0))
        results.append((p, r, zf))
        print("pedestal p=%.3e*m R=%.7f zeros=%.1f%%" % (p / m, r, zf))
        if r > bestR + 1e-13:
            best_h, bestR, best_p = hp.copy(), r, p
    # bracket best p geometrically by 1/3 and 3
    if best_p is not None and time.process_time() < deadline - 0.5:
        for p in (best_p / 3.0, best_p * 3.0):
            if time.process_time() >= deadline - 0.5:
                break
            hp = _pedestal_schedule(h, p, deadline - 0.5)
            r = R_of(hp)
            zf = 100.0 * float(np.mean(hp <= 0))
            print("pedestal bracket p=%.3e*m R=%.7f zeros=%.1f%%" %
                  (p / m, r, zf))
            if r > bestR + 1e-13:
                best_h, bestR, best_p = hp.copy(), r, p
    alt = None
    altR = -1.0
    if best_p is not None:
        alt = best_h.copy()
        altR = bestR
    return best_h, bestR, alt, altR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: pedestal scan ----
    if time.process_time() < deadline - 20.0:
        try:
            exp_h, expR, alt_h, altR_exp = _pedestal_experiment(
                best, bestR, deadline - 12.0)
            if alt_h is not None:
                alt_cand, altR = alt_h.copy(), altR_exp
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("pedestal wins: R=%.7f (was %.7f)" % (bestR, start_bestR))
            else:
                print("pedestal did not beat base: %.7f vs %.7f" %
                      (expR, bestR))
        except Exception as e:
            print("pedestal experiment failed: %s" % e)

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if alt_cand is not None and altR > start_bestR + 1e-13 and altR >= bestR - 1e-13:
        return {"best": best, "alternative": alt_cand}
    if alt_cand is not None and altR > start_bestR + 1e-13:
        return {"best": best, "alternative": alt_cand}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    total_acc = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
            total_acc += 1
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- Experiment: graded support extension ----------------

def _extend_support(base, baseR, pad, deadline, decay=60.0):
    """Pad `pad` cells on each end with a graded exponential continuation
    of the toe, then run the extension + polish pipeline."""
    h = np.clip(np.asarray(base, dtype=float), 0, None).copy()
    if h.sum() <= 0:
        return h, baseR, False
    s0, s1 = _active_support(h)
    n = h.size
    A_L = float(np.max(h[s0:s0 + 8])) if s0 + 8 <= n else float(h[s0])
    A_R = float(np.max(h[max(0, s1 - 7):s1 + 1]))
    if A_L <= 0:
        A_L = float(h.max())
    if A_R <= 0:
        A_R = float(h.max())

    left = A_L * np.exp(-np.arange(pad, 0, -1, dtype=float) / decay)
    right = A_R * np.exp(-np.arange(1, pad + 1, dtype=float) / decay)
    h2 = np.concatenate([left, h, right])
    h2 = _rescale(h2)
    new_n = h2.size
    off = pad  # old index i -> new index i + off

    # (b) L-BFGS restricted to pad cells + first/last 2000 of old support
    edge = min(2000, n)
    free = np.concatenate([
        np.arange(0, pad + edge),
        np.arange(new_n - pad - edge, new_n),
    ])
    free = np.unique(free)
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_block(h2, free, 400, deadline - 0.5, beta=0.0)

    # (c) full-array L-BFGS
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_all_pos(h2, 400, deadline - 0.5, beta=0.0)

    pad_mass = float(h2[:pad].sum() + h2[new_n - pad:].sum())
    r2 = R_of(h2)
    improved = r2 > baseR + 1e-13
    best, bestR = (h2, r2) if improved else (base, baseR)

    # (d) beta ladder polish
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r

    return best, bestR, (pad_mass > 1e-3 * max(1e-12, h2[h2 > 0].mean()))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: graded support extension (pad=8000, then 4000) ----
    s0, s1 = _active_support(best)
    print("support [%d,%d] of N=%d" % (s0, s1, best.size))

    for pad in (8000, 4000):
        if time.process_time() >= deadline - 20.0:
            break
        try:
            eh, er, pad_kept = _extend_support(
                best, bestR, pad, deadline - 12.0)
            b01 = _band_frac(eh, 0.001)
            b1 = _band_frac(eh, 0.01)
            print("extend pad=%d: R=%.7f pad_kept=%s band01=%.2f%% band1=%.2f%%"
                  % (pad, er, pad_kept, 100 * b01, 100 * b1))
            if er > bestR + 1e-13:
                best, bestR = eh.copy(), er
                print("extend wins: R=%.7f (was %.7f)" %
                      (bestR, start_bestR))
            else:
                if eh.size != best.size and er > altR:
                    alt_cand, altR = eh.copy(), er
        except Exception as e:
            print("extend pad=%d failed: %s" % (pad, e))

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if alt_cand is not None and altR > start_bestR + 1e-13 and \
            altR <= bestR + 1e-13:
        return {"best": best, "alternative": alt_cand}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, tol=0.9995, pad_frac=0.4, extra=256)
        ht = _lbfgs_block(best, free, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: soft-max / beta continuation to nudge off the exact-max degeneracy.
    alt = None
    altR = 0.0
    if time.process_time() < deadline - 3.0:
        h = _seed_zeros(best)
        for beta in (2.0, 5.0, 10.0, 20.0, 40.0, 80.0):
            if time.process_time() >= deadline - 3.0:
                break
            h = _lbfgs_all_pos(h, 400, deadline - 1.0, beta=beta)
        h = _refine_knots(h, 800, deadline - 1.0)
        r = R_of(h)
        print("beta-cont R=%.7f" % r)
        if alt is None or r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("beta improved R=%.7f" % bestR)

    # Phase 2: alternate full and peak-window L-BFGS until budget nearly exhausted.
    stall = 0
    while time.process_time() < deadline - 0.6:
        prev = bestR
        best, bestR = run_cycle(best, bestR, deadline)
        if time.process_time() >= deadline - 0.6:
            break
        if bestR > prev + 1e-13:
            stall = 0
            print("cycle R=%.7f" % bestR)
        else:
            stall += 1
            # Try a nudge: seed zeros to escape degeneracy
            if stall >= 2:
                hs = _seed_zeros(best)
                hs = _lbfgs_all_pos(hs, 400, deadline - 0.8, beta=5.0)
                hs = _refine_knots(hs, 600, deadline - 0.6)
                r = R_of(hs)
                if r > bestR + 1e-13:
                    best, bestR = hs, r
                    stall = 0
                    print("nudge R=%.7f" % bestR)
                else:
                    if stall >= 4:
                        break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt is not None and altR > 0 and altR < bestR - 1e-12:
        return {"best": best, "alternative": alt}
    return best

