    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


# ---------------- New idea: smooth knot-shaping via peak saddle moves ------

def _saddle_lift(best, bestR, deadline, rng, n_try=24):
    """Try to lift the peak region by re-optimising a band around the maximum
    with a sharper soft-max (higher beta), letting new micro-peaks emerge."""
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    m = int(np.argmax(Lf))
    # half-width of the near-plateau
    span = max(64, int(0.05 * n))
    lo = max(0, m - span)
    hi = min(n - 1, m + span)
    free = np.arange(lo, hi + 1)
    cur_best = best
    cur_R = bestR
    for beta in (1e6, 1e7, 3e7, 1e8):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(cur_best, free, 200, deadline, beta=beta)
        r = R_of(ht)
        if r > cur_R + 1e-13:
            cur_best, cur_R = ht, r
        else:
            break
    return cur_best, cur_R


def _smooth_axis(best, bestR, deadline, rng, n_tries=8):
    """Resample onto a finer grid via mass-preserving interpolation and
    re-optimise; sometimes this escapes local optima of the step layout."""
    n = best.size
    if time.process_time() >= deadline - 0.5:
        return best, bestR
    cur_best, cur_R = best, bestR
    for factor in (2, 3):
        if time.process_time() >= deadline - 0.5:
            break
        n2 = min(1_000_000, n * factor)
        if n2 <= n:
            continue
        H = np.concatenate(([0.0], np.cumsum(best)))
        Htot = H[-1]
        if Htot <= 0:
            continue
        xs = np.linspace(0.0, 1.0, n + 1)
        xt = np.linspace(0.0, 1.0, n2 + 1)
        Ht = np.interp(xt, xs, H)
        h2 = np.diff(Ht)
        h2 = np.clip(h2, 0.0, None)
        if h2.sum() <= 0:
            continue
        h2 = _rescale(h2)
        r2 = R_of(h2)
        # quick polish
        hp = _lbfgs_all_pos(h2, 200, deadline, beta=0.0)
        rp = R_of(hp)
        if rp > r2:
            h2, r2 = hp, rp
        if r2 > cur_R + 1e-13:
            cur_best, cur_R = h2, r2
            break
    return cur_best, cur_R


def _perturb_restart(best, bestR, deadline, rng):
    """Add small structured noise, polish, and keep if better."""
    if time.process_time() >= deadline - 0.5:
        return best, bestR
    n = best.size
    scale = 0.02 * best.mean() if best.mean() > 0 else 1e-3
    h2 = best + scale * rng.standard_normal(n)
    h2 = np.clip(h2, 0.0, None)
    h2 = _rescale(h2)
    hp = _lbfgs_all_pos(h2, 300, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-13:
        return hp, rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(20240517)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # Phase A: smooth-axis resampling (new idea)
    if time.process_time() < deadline - 20.0:
        h2, r2 = _smooth_axis(best, bestR, deadline - 15.0, rng)
        if r2 > bestR + 1e-12:
            best, bestR = h2, r2
            print("smooth-axis win R=%.7f N=%d" % (bestR, best.size))
        elif r2 > altR:
            alt_cand, altR = h2.copy(), r2

    # Phase B: saddle lift about the max (new idea)
    if time.process_time() < deadline - 12.0:
        h2, r2 = _saddle_lift(best, bestR, deadline - 10.0, rng)
        if r2 > bestR + 1e-12:
            best, bestR = h2, r2
            print("saddle-lift win R=%.7f" % bestR)
        elif r2 > altR:
            alt_cand, altR = h2.copy(), r2

    # Phase C: original machinery
    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f" % bestR)

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    last_pert = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 20.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
        if now - last_pert > 25.0:
            last_pert = now
            if time.process_time() < deadline - 6.5:
                st, r = _perturb_restart(best, bestR, deadline - 6.5, rng)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * _band_frac(best, 0.001),
           100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_softmin(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Li = Lf[1:-1]
    mn = Li.min()
    e = np.exp(np.clip(-beta * (Li - mn), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mn - np.log(Z) / beta
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[1:-1] += -w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, softmin=0.0, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if softmin > 0:
        fg = lambda hh: _fun_grad_softmin(hh, softmin)
    elif beta > 0:
        fg = lambda hh: _fun_grad_beta(hh, beta)
    else:
        fg = _fun_grad

    if free is None:
        active = None
        x0 = h
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0
        x0 = h[active].copy()

    def f(x):
        if active is None:
            hh = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    n = x0.size
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    if active is None:
        return _rescale(np.clip(res.x, 0.0, None))
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _accept(best, bestR, ht):
    r = R_of(ht)
    if r > bestR + 1e-13:
        return ht.copy(), r
    return best, bestR


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        best, bestR = _accept(best, bestR, _lbfgs(best, 800, deadline - 0.5, beta=0.0))
    if time.process_time() < deadline - 0.5:
        best, bestR = _accept(best, bestR, _lbfgs(best, 400, deadline - 0.5, beta=1e7))
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        best, bestR = _accept(best, bestR,
                              _lbfgs(best, 250, deadline - 0.5, beta=beta, free=win))
    if time.process_time() < deadline - 0.5:
        best, bestR = _accept(best, bestR, _lbfgs(_seed_zeros(best), 300, deadline - 0.5, beta=0.0))
    return best, bestR


def _softmin_cycle(best, bestR, deadline):
    for beta in (50.0, 200.0, 800.0):
        if time.process_time() >= deadline - 0.6:
            break
        best, bestR = _accept(best, bestR, _lbfgs(best, 200, deadline - 0.6, softmin=beta))
    if time.process_time() < deadline - 0.5:
        best, bestR = _accept(best, bestR, _lbfgs(best, 400, deadline - 0.5, beta=0.0))
    if time.process_time() < deadline - 0.5:
        win = _peak_window(best, pad_frac=0.3, extra=128)
        best, bestR = _accept(best, bestR,
                              _lbfgs(best, 200, deadline - 0.5, softmin=300.0, free=win))
        best, bestR = _accept(best, bestR, _lbfgs(best, 300, deadline - 0.5, beta=0.0))
    return best, bestR


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        best, bestR = _accept(best, bestR, _lbfgs(best, 200, deadline - 0.4, beta=0.0))
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        best, bestR = _accept(best, bestR,
                              _lbfgs(best, 150, deadline - 0.4, beta=beta, free=win))
    if time.process_time() < deadline - 0.4:
        best, bestR = _accept(best, bestR, _lbfgs(best, 150, deadline - 0.4, beta=1e7))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 4.0:
        best, bestR = _softmin_cycle(best, bestR, deadline - 4.0)
        print("softmin cycle R=%.7f" % bestR)

    if time.process_time() < deadline - 3.0:
        best, bestR = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f" % bestR)

    last_print = time.process_time()
    while time.process_time() < deadline - 1.5:
        prevR = bestR
        best, bestR = _softmin_cycle(best, bestR, deadline - 1.5)
        if time.process_time() < deadline - 1.2:
            best, bestR = _mini_cycle(best, bestR, deadline - 1.2)
        if bestR - prevR < 1e-10:
            if time.process_time() < deadline - 1.2:
                best, bestR = run_cycle(best, bestR, deadline - 1.2)
        if time.process_time() - last_print > 8.0:
            last_print = time.process_time()
            print("iter R=%.7f band01 %.2f%%" %
                  (bestR, 100.0 * _band_frac(best, 0.001)))

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

