    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


# ---------------- Coarse (block-averaged) objective ----------------

def _moving_avg(Lf, w):
    """Lb_j = mean(Lf[j-r : j+r+1]) with r = w//2, edge-clamped."""
    n = Lf.size
    if w <= 1:
        return Lf.copy()
    r = w // 2
    # cumulative sum with edge clamping (replicate-pad)
    idx = np.arange(n)
    lo = np.clip(idx - r, 0, n - 1)
    hi = np.clip(idx + r, 0, n - 1)
    cs = np.concatenate(([0.0], np.cumsum(Lf)))
    # sum over [lo_j, hi_j] inclusive
    Lb = (cs[hi + 1] - cs[lo]) / (hi - lo + 1).astype(float)
    return Lb


def _avg_backprop(gLb, w):
    """Adjoint of _moving_avg: dLf_i = sum_j gLb_j * (1/(hi_j-lo_j+1)) [lo_j<=i<=hi_j]."""
    n = gLb.size
    if w <= 1:
        return gLb.copy()
    r = w // 2
    idx = np.arange(n)
    lo = np.clip(idx - r, 0, n - 1)
    hi = np.clip(idx + r, 0, n - 1)
    cnt = (hi - lo + 1).astype(float)
    contrib = gLb / cnt
    # difference array over [lo, hi]
    diff = np.zeros(n + 1)
    np.add.at(diff, lo, contrib)
    np.add.at(diff, hi + 1, -contrib)
    return np.cumsum(diff[:-1])


def _fun_grad_coarse(h, beta, w):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    if w <= 1:
        if beta > 0:
            return _fun_grad_beta(h, beta)
        return _fun_grad(h)
    num, dq, Lf = _num_and_dq(h)
    Lb = _moving_avg(Lf, w)
    a = Lb[:-1]; b = Lb[1:]
    num_c = np.sum(a * a + a * b + b * b) / 3.0
    # gradient of num_c wrt Lb
    dq_c = np.zeros_like(Lb)
    dq_c[:-1] += (2 * a + b)
    dq_c[1:] += (a + 2 * b)
    dq_c /= 3.0
    mx = Lb.max()
    if mx <= 0:
        return _fun_grad(h)
    if beta > 0:
        e = np.exp(np.clip(beta * (Lb - mx), -60.0, 60.0))
        Z = e.sum()
        if Z <= 0:
            return _fun_grad(h)
        wgt = e / Z
        sm = mx + np.log(Z) / beta
        gLb = -dq_c / num_c + wgt / sm
        val = -np.log(num_c) + 2.0 * np.log(s) + np.log(sm)
    else:
        m = int(np.argmax(Lb))
        Lm = Lb[m]
        gLb = -dq_c / num_c
        gLb[m] += 1.0 / Lm
        val = -np.log(num_c) + 2.0 * np.log(s) + np.log(Lm)
    gLf = _avg_backprop(gLb, w)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, w=1):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if w > 1:
        fg = (lambda hh: _fun_grad_coarse(hh, beta, w))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
