# ---------------- Experiment: coarse-to-fine averaging ladder ----------------

def _coarse_ladder(base, baseR, deadline):
    """Run w = 64,32,16,8,4,2,1 with beta=1e7 (beta=0 at w=1). Never revert.
    Returns (best_h, bestR, dip_seen)."""
    best_h = base.copy()
    bestR_exact = baseR
    cur = base.copy()
    dip_seen = False
    rungs = [64, 32, 16, 8, 4, 2, 1]
    for w in rungs:
        if time.process_time() >= deadline - 0.5:
            break
        beta = 0.0 if w == 1 else 1e7
        ht = _lbfgs_all_pos(cur, 300, deadline - 0.5, beta=beta, w=w)
        r_exact = R_of(ht)
        if r_exact < bestR_exact - 1e-9:
            dip_seen = True
        cur = ht
        if r_exact > bestR_exact + 1e-13:
            best_h = ht.copy()
            bestR_exact = r_exact
        print("coarse w=%d beta=%.0e exact R=%.7f (best %.7f)%s" %
              (w, beta, r_exact, bestR_exact, " DIP" if dip_seen else ""))
    return best_h, bestR_exact, dip_seen


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: coarse-to-fine averaging ladder ----
    exp_h = None
    expR = -1.0
    if time.process_time() < deadline - 15.0:
        try:
            exp_h, expR, dip_seen = _coarse_ladder(
                best, bestR, deadline - 15.0)
            if expR > bestR + 1e-13:
                best, bestR = exp_h.copy(), expR
                print("coarse ladder wins: %.7f -> %.7f (dip=%s)" %
                      (start_bestR, bestR, dip_seen))
            else:
                print("coarse ladder no gain: %.7f vs %.7f" % (expR, bestR))
                if exp_h is not None:
                    alt_cand, altR = exp_h.copy(), expR
        except Exception as e:
            print("coarse experiment failed: %s" % e)

    # ---- Base's peak-window polish ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR >= start_bestR - 1e-13:
        if alt_cand is not None and altR > bestR + 1e-13:
            return {"best": best, "alternative": alt_cand}
        return best
    else:
        if alt_cand is not None:
            return {"best": start_best, "alternative": alt_cand}
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


