    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- New idea: resample-to-finer and multi-scale perturbation search ----

def _resample(h, factor):
    """Linearly interpolate heights onto a grid `factor` times finer."""
    n = h.size
    if factor <= 1:
        return h.copy()
    old_x = np.linspace(0.0, 1.0, n, endpoint=False)
    new_n = n * factor
    new_x = np.linspace(0.0, 1.0, new_n, endpoint=False)
    return np.interp(new_x, old_x, h, left=0.0, right=0.0) * factor


def _perturb(h, rng, scale, band_mask):
    """Multiplicative log-normal noise on selected band."""
    out = h.copy()
    noise = np.exp(rng.normal(0.0, scale, out.size))
    out[band_mask] *= noise[band_mask]
    return _rescale(out)


def _sweep_windows(cur, curR, deadline, win, stride, iters, beta):
    n = cur.size
    if n <= win:
        centers = [n // 2]
    else:
        centers = list(range(win // 2, n - win // 2 + 1, stride))
        if not centers or centers[-1] < n - win // 2:
            centers.append(n - win // 2)
    accepted = 0
    for c in centers:
        if time.process_time() >= deadline:
            break
        lo = max(0, c - win // 2)
        hi = min(n, c + win // 2)
        ht = _lbfgs_block(cur, np.arange(lo, hi), iters, deadline, beta=beta)
        r = R_of(ht)
        if r > curR + 1e-13:
            cur = ht
            curR = r
            accepted += 1
    return cur, curR, accepted


def _finer_search(best, bestR, deadline, rng, factor, win_frac, iters):
    """Resample to finer grid, then sweep small windows over whole array."""
    hr = _resample(best, factor)
    hr = _rescale(hr)
    r = R_of(hr)
    if r < bestR - 1e-6:
        return best, bestR, 0
    n = hr.size
    win = max(64, int(n * win_frac))
    win = min(win, 4096)
    stride = max(1, win // 2)
    # sweep in beta=0 first
    cur, curR, acc = _sweep_windows(hr, r, deadline, win, stride, iters, 0.0)
    return cur, curR, acc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    rng = np.random.default_rng(12345)
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # --- Phase 1: quick local polish of start to make sure we're at a good point
    if time.process_time() < deadline - 30.0:
        ht = _lbfgs_all_pos(best, 300, min(deadline - 30.0, time.process_time() + 8.0), beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
            origin = 'local'
            print("local polish R=%.7f" % bestR)

    # --- Phase 2: multi-scale finer-grid search with random perturbations
    # Try a small set of factors; keep whichever improves.
    factors = [2, 3]
    for factor in factors:
        if time.process_time() >= deadline - 20.0:
            break
        try:
            ht, rt, acc = _finer_search(best, bestR, min(deadline - 20.0,
                                       time.process_time() + 12.0),
                                       rng, factor, 0.02, 60)
            print("finer factor=%d: R=%.7f acc=%d (was %.7f)" % (factor, rt, acc, bestR))
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                origin = origin + '+finer%d' % factor
        except Exception as e:
            print("finer %d failed: %s" % (factor, e))

    # --- Phase 3: random multiplicative perturbations + short L-BFGS descent
    n = best.size
    Lf = _knots(best)
    mx = Lf.max()
    # focus perturbation on region where f*f is near max (drives R_inf)
    peak_mask = Lf >= 0.9 * mx
    peak_idx = np.flatnonzero(peak_mask)
    if peak_idx.size > 0:
        # map knot index back to height index roughly
        lo = max(0, peak_idx.min() - 1 - n // 20)
        hi = min(n - 1, peak_idx.max() + n // 20)
    else:
        lo, hi = 0, n - 1
    band_mask = np.zeros(n, dtype=bool)
    band_mask[lo:hi + 1] = True

    scales = [0.02, 0.05, 0.10]
    tries = 0
    while time.process_time() < deadline - 8.0:
        sc = scales[tries % len(scales)]
        cand = _perturb(best, rng, sc, band_mask)
        # short local descent
        hr = _lbfgs_all_pos(cand, 80, min(deadline - 8.0,
                            time.process_time() + 3.0), beta=0.0)
        r = R_of(hr)
        tries += 1
        if r > bestR + 1e-13:
            best, bestR = hr, r
            origin = origin + '+pert'
            print("perturb sc=%.2f try=%d R=%.7f" % (sc, tries, bestR))

    # --- Phase 4: final tight polish on peak window
    for frac in (0.05, 0.10, 0.20):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=128)
        ht = _lbfgs_block(best, win, 200, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
            origin = origin + '+tight'
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
            origin = origin + '+final'

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-14 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


# ---- Warp machinery ----
def _warp(h, d, K=32, amp=0.25):
    N = h.size
    xk = np.arange(K + 1, dtype=float) / K
    u = xk.copy()
    u[1:K] = xk[1:K] + amp * np.tanh(d)
    u[0] = 0.0
    u[K] = 1.0
    u = np.maximum.accumulate(u + 1e-9 * np.arange(K + 1))
    u = np.clip(u, 0.0, 1.0)
    u[0] = 0.0
    u[K] = 1.0
    xj = np.arange(N, dtype=float) / N
    v = np.interp(xj, xk, u)
    C = np.concatenate(([0.0], np.cumsum(h) / h.sum()))
    xi = np.arange(N + 1, dtype=float) / N
    Cnew = np.interp(v, xi, C)
    hnew = N * np.diff(np.concatenate(([0.0], Cnew)))
    return _rescale(np.clip(hnew, 0, None))


def _warp_opt(h, deadline, d0=None, K=32):
    if time.process_time() >= deadline - 0.5:
        return h, R_of(h), np.zeros(K - 1)
    if d0 is None:
        d0 = np.zeros(K - 1)
    best = [None, -1.0, d0.copy()]

    def obj(d):
        if time.process_time() > deadline - 0.3:
            raise TimeoutError
        hw = _warp(h, d, K)
        r = R_of(hw)
        if r > best[1]:
            best[0] = hw
            best[1] = r
            best[2] = d.copy()
        return -r

    try:
        minimize(obj, d0, method='Powell',
                 options={'maxfev': 4000, 'xtol': 1e-4, 'ftol': 1e-11})
    except (TimeoutError, Exception):
        pass
    if best[0] is None:
        return h, R_of(h), d0
    return best[0], best[1], best[2]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    bestH = best.copy()
    bestRH = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    # ---- Warp: several restarts of Powell over breakpoints ----
    rng = np.random.default_rng(2024)
    K = 48
    warp_end = t0 + budget_seconds * 0.45
    d_cur = np.zeros(K - 1)
    for restart in range(6):
        if time.process_time() >= warp_end - 1.0:
            break
        if restart > 0:
            d_cur = d_cur + rng.normal(0.0, 0.4, size=K - 1)
        sub_deadline = min(warp_end, time.process_time() + 4.0)
        hw, rw, d_cur = _warp_opt(bestH, sub_deadline, d0=d_cur, K=K)
        print("  warp %d R=%.7f" % (restart, rw))
        if rw > bestRH + 1e-13:
            bestH, bestRH = hw.copy(), rw

    # ---- Polish: sharp, smooth, p-norm ----
    def record(h, tag):
        nonlocal bestH, bestRH
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  %s R=%.7f" % (tag, bestRH))

    if time.process_time() < deadline - 2.0:
        h = _lbfgs_log(bestH, 300, min(deadline - 1.5, time.process_time() + 5.0))
        record(h, "sharp")

    for beta in (30.0, 100.0, 300.0):
        if time.process_time() >= deadline - 2.0:
            break
        fg = (lambda hh, _b=beta: _fun_grad_beta(hh, _b))
        h = _lbfgs_log(bestH, 200, min(deadline - 1.5, time.process_time() + 4.0), fg=fg)
        record(h, "beta%g" % beta)

    for p in (6, 12, 24, 48):
        if time.process_time() >= deadline - 2.0:
            break
        fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
        h = _lbfgs_log(bestH, 150, min(deadline - 1.5, time.process_time() + 3.5), fg=fg)
        record(h, "p=%d" % p)

    # ---- Peak polish loop ----
    while time.process_time() < deadline - 1.2:
        prev = bestRH
        lo, hi = _peak_region(bestH, tol=0.999)
        span = hi - lo
        pad = max(64, int(span * 0.20))
        lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
        if hi2 > lo2:
            free = np.arange(lo2, hi2 + 1)
            hp = _lbfgs_block(bestH, free, 200, deadline - 0.5)
            record(hp, "peak")
        if time.process_time() < deadline - 1.2:
            h = _lbfgs_log(bestH, 150, min(deadline - 0.5, time.process_time() + 3.0))
            record(h, "sharp2")
        if bestRH <= prev + 1e-14:
            break

    mx, m, near = _stats(bestH)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        return bestH
    return {"best": start_best,
            "alternative": bestH if bestRH > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR, 0.0


def _resample(h, N):
    """Resample step function h (length n) onto N equal steps of same support."""
    n = h.size
    if n == N:
        return h.copy()
    # piecewise-constant resample by overlap length
    edges_old = np.linspace(0.0, 1.0, n + 1)
    edges_new = np.linspace(0.0, 1.0, N + 1)
    # cumulative integral at old edges
    cum = np.concatenate(([0.0], np.cumsum(h))) / n
    new_cum = np.interp(edges_new, edges_old, cum)
    g = np.diff(new_cum) * N
    return np.clip(g, 0.0, None)


def _upsample_refine(h, factor, deadline, bestR):
    """Resample to finer grid and refine. Returns (h, R) or (None, -1)."""
    N = h.size
    N2 = int(min(1000000, N * factor))
    if N2 <= N:
        return None, -1.0
    hr = _resample(h, N2)
    hr = _rescale(hr)
    r = R_of(hr)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(hr, 200, deadline - 0.5, beta=1e7)
        rt = R_of(ht)
        if rt > r:
            hr, r = ht, rt
    return hr, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Experiment: upsample to finer grid and refine ----
    # The idea: the current best is likely limited by its grid resolution.
    # Resample it onto a finer grid (interpolating the step function exactly
    # in mass), then run local optimisation there.  This can find structure
    # below the old step size and raise R.
    if time.process_time() < deadline - 20.0:
        try:
            h_up, r_up = _upsample_refine(best, 2, deadline - 20.0, bestR)
            if h_up is not None:
                print("upsample x2: %.7f (from %.7f, N=%d)" %
                      (r_up, bestR, h_up.size))
                if r_up > bestR + 1e-13:
                    best, bestR = h_up.copy(), r_up
                else:
                    alt_cand, altR = h_up.copy(), r_up
        except Exception as e:
            print("upsample failed: %s" % e)

    # ---- Base's peak-window polish ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- If time remains, try another upsample round ----
    if time.process_time() < deadline - 6.0:
        try:
            h_up, r_up = _upsample_refine(best, 2, deadline - 6.0, bestR)
            if h_up is not None:
                print("upsample x2 (2nd): %.7f (from %.7f, N=%d)" %
                      (r_up, bestR, h_up.size))
                if r_up > bestR + 1e-13:
                    best, bestR = h_up.copy(), r_up
                elif alt_cand is None or r_up > altR:
                    alt_cand, altR = h_up.copy(), r_up
        except Exception as e:
            print("upsample 2 failed: %s" % e)

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR >= start_bestR - 1e-13:
        if alt_cand is not None and altR > bestR + 1e-13:
            return {"best": best, "alternative": alt_cand}
        return best
    else:
        if alt_cand is not None:
            return {"best": start_best, "alternative": alt_cand}
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
