def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- Experiment: upper-hinge cap phase ----------------

def _cap_phase(best, bestR, deadline):
    """Try caps x lams; each: cap-LBFGS then exact-R peak-window polish."""
    caps_frac = [0.9995, 0.998, 0.995, 0.990]
    lams = [1e3, 1e4]
    best_h = best.copy()
    best_r = bestR
    for cf in caps_frac:
        for lam in lams:
            if time.process_time() >= deadline - 0.5:
                print("cap-phase: out of time")
                return best_h, best_r
            Lf = _knots(best)
            mx = Lf.max()
            if mx <= 0:
                continue
            cap = cf * mx
            hc = _lbfgs_cap(best, cap, lam, 120, deadline - 0.5)
            rc = R_of(hc)
            # exact-R peak-window polish
            hp = hc
            rp = rc
            if time.process_time() < deadline - 0.5:
                win = _peak_window(hc, pad_frac=0.10, extra=128)
                hp = _lbfgs_block(hc, win, 120, deadline - 0.5, beta=0.0)
                rp = R_of(hp)
            b1 = 100.0 * _band_frac(hp, 0.01)
            print("cap=%.4f lam=%.0e: capR=%.7f polishR=%.9f band1=%.2f%%"
                  % (cf, lam, rc, rp, b1))
            if rp > best_r + 1e-13:
                best_h, best_r = hp.copy(), rp
    return best_h, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

