        if ib_R > bestR + 1e-13:
            best, bestR = ib_h, ib_R
            origin = 'interiorbeta'
            print("interior-beta improved: R=%.7f" % bestR)
        else:
            print("interior-beta did not improve (best=%.7f)" % ib_R)
    except Exception as e:
        print("interior-beta failed: %s" % e)

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 4.0:
        ht, rt = run_cycle(best, bestR, deadline - 4.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
