        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- Experiment: fractional sub-cell split of tall runs ----------------

def _find_runs(h, thresh=1e-9):
    """Return list of (a, b) inclusive maximal runs of h > thresh."""
    pos = h > thresh
    if not pos.any():
        return []
    d = np.diff(pos.astype(np.int8))
    starts = list(np.flatnonzero(d == 1) + 1)
    ends = list(np.flatnonzero(d == -1))
    if pos[0]:
        starts = [0] + starts
    if pos[-1]:
        ends = ends + [h.size - 1]
    return list(zip(starts, ends))


def _splat_run(h, a, b, m1, m2, c1, c2):
    """Replace run [a,b] by two sub-runs of masses m1,m2 at fractional centres
    c1,c2 (in cell-index coordinates), linearly splatted onto the grid.
    Returns a new array (copy)."""
    out = h.copy()
    out[a:b + 1] = 0.0
    n = h.size
    for m, c in ((m1, c1), (m2, c2)):
        if m <= 0:
            continue
        i0 = int(np.floor(c))
        frac = c - i0
        # linear splat: (1-frac) at i0, frac at i0+1
        if 0 <= i0 < n:
            out[i0] += m * (1.0 - frac)
        if 0 <= i0 + 1 < n:
            out[i0 + 1] += m * frac
    return out


def _split_run_opt(h, a, b, deadline, maxiter=80):
    """Optimise masses and fractional offset for one run. Returns (h_new, R_new)
    or (h, R_of(h)) if no gain."""
    R0 = R_of(h)
    run_mass = h[a:b + 1].sum()
    if run_mass <= 0:
        return h, R0
    # initial centres: cell-centred split at a and b, masses proportional
    c1_0 = float(a)
    c2_0 = float(b)
    m1_0 = 0.5 * run_mass
    m2_0 = 0.5 * run_mass
    # parameters: log m1, log m2, s (offset applied symmetrically)
    # c1 = c1_0 - s, c2 = c2_0 + s, s in [-0.5, 0.5]
    x0 = np.array([np.log(m1_0 + 1e-30), np.log(m2_0 + 1e-30), 0.0])

    def unpack(x):
        m1 = np.exp(x[0]); m2 = np.exp(x[1]); s = x[2]
        # renormalise masses to preserve total
        tot = m1 + m2
        if tot <= 0:
            m1 = m2 = 0.5 * run_mass
        else:
            m1 = m1 / tot * run_mass
            m2 = m2 / tot * run_mass
        c1 = c1_0 - s
        c2 = c2_0 + s
        return m1, m2, c1, c2

    def f(x):
        m1, m2, c1, c2 = unpack(x)
        hh = _splat_run(h, a, b, m1, m2, c1, c2)
        val, g = _fun_grad(hh)
        # numerical gradient wrt x via finite differences (3 params, cheap)
        eps = 1e-6
        gx = np.zeros(3)
        for k in range(3):
            xp = x.copy(); xp[k] += eps
            m1p, m2p, c1p, c2p = unpack(xp)
            hp = _splat_run(h, a, b, m1p, m2p, c1p, c2p)
            vp, _ = _fun_grad(hp)
            gx[k] = (vp - val) / eps
        return val, gx

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(None, None), (None, None), (-0.5, 0.5)],
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 4 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, R0
    if res is None:
        return h, R0
    m1, m2, c1, c2 = unpack(res.x)
    h_new = _splat_run(h, a, b, m1, m2, c1, c2)
    h_new = _rescale(h_new)
    r_new = R_of(h_new)
    if r_new > R0 + 1e-13:
        return h_new, r_new
    return h, R0


def _fractional_split_phase(best, bestR, deadline, K=8):
    """Try splitting the top-K runs by mass with fractional re-splatting."""
    runs = _find_runs(best)
    if not runs:
        print("frac-split: no runs found")
        return best, bestR
    masses = [(h_sum, a, b) for (a, b) in runs
              for h_sum in [best[a:b + 1].sum()]]
    masses.sort(reverse=True)
    top = masses[:K]
    print("frac-split: %d runs, top masses %s" %
          (len(runs), ["%.3g" % m[0] for m in top[:K]]))
    cur = best.copy()
    curR = bestR
    accepted = 0
    for k, (m, a, b) in enumerate(top):
        if time.process_time() >= deadline - 0.5:
            print("frac-split: out of time at run %d" % k)
            break
        h_new, r_new = _split_run_opt(cur, a, b, deadline - 0.5, maxiter=80)
        dR = r_new - curR
        print("frac-split run %d [%d,%d] mass=%.3g: R=%.9f dR=%.3e" %
              (k, a, b, m, r_new, dR))
        if r_new > curR + 1e-13:
            cur, curR = h_new, r_new
            accepted += 1
    print("frac-split accepted %d/%d, R=%.9f" % (accepted, len(top), curR))
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: fractional sub-cell split of top runs ----
    try:
        fs_h, fs_R = _fractional_split_phase(best, bestR, deadline - 18.0, K=8)
        if fs_R > bestR + 1e-13:
            best, bestR = fs_h, fs_R
            origin = 'fracsplit'
            print("frac-split improved: R=%.7f" % bestR)
        else:
            print("frac-split did not improve (best=%.7f)" % fs_R)
    except Exception as e:
        print("frac-split failed: %s" % e)

    # ---- Base's proven machinery on the best array ----
    if time.process_time() < deadline - 4.0:
        ht, rt = run_cycle(best, bestR, deadline - 4.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Tight peak-window block polish with last ~6s ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("tight polish beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight7'
    except Exception as e:
        print("tight polish failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- New idea: resample to finer grid, re-optimise, keep if better ----

def _resample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    new_n = n * factor
    x_new = np.linspace(0.0, 1.0, new_n, endpoint=False)
    return np.interp(x_new, x_old, h, right=h[-1])


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e8), (0.25, 128, 1e8), (0.40, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: base machinery on the start array.
    if time.process_time() < deadline - 6.0:
        ht, rt = run_cycle(best, bestR, deadline - 6.0)
        if rt > bestR + 1e-13:
            best, bestR, origin = ht, rt, origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # Phase B: try refining on a finer grid (up to 2x), keeping the best.
    for factor in (2,):
        if time.process_time() >= deadline - 3.0:
            break
        try:
            hf = _resample(best, factor)
            if hf.size > 900000:
                continue
            hf = _rescale(hf)
            hf = _seed_zeros(hf)
            hf, rf = run_cycle(hf, R_of(hf), deadline - 3.0)
            print("resample x%d: R=%.9f (N=%d)" % (factor, rf, hf.size))
            if rf > bestR + 1e-13:
                best, bestR, origin = hf, rf, origin + '+fine'
        except Exception as e:
            print("resample failed: %s" % e)

    # Phase C: tight polish on the peak window with whatever time remains.
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("tight polish beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR, origin = ht, r, origin + '+tight0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR, origin = ht, r, origin + '+tight7'
    except Exception as e:
        print("tight polish failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

