    loop_end = deadline - 1.5
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            print("  iter=%d global R=%.9f" % (it, bestR))
            if bestR > experiment_bestR + 1e-14:
                experiment_best, experiment_bestR = bestH.copy(), bestR
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.03 + 0.07 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 3.5)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                print("  iter=%d peak frac=%.2f R=%.9f" % (it, frac, bestR))
                if bestR > experiment_bestR + 1e-14:
                    experiment_best, experiment_bestR = bestH.copy(), bestR

    # Final polish
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hs = _lbfgs_log(bestH, 120, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            if bestR > experiment_bestR + 1e-14:
                experiment_best, experiment_bestR = bestH.copy(), bestR

    print("final R=%.9f (base %.9f, N=%d)" % (bestR, baseR, bestH.size))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": experiment_best}
    else:
        return {"best": baseH, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def prolongate(h, Nnew):
    N = len(h)
    xold = (np.arange(N) + 0.5) / N
    xnew = (np.arange(Nnew) + 0.5) / Nnew
    hn = np.interp(xnew, xold, h, left=0.0, right=0.0)
    hn = np.maximum(hn, 0.0)
    s = hn.sum()
    if s > 0:
        hn /= s
    return hn


def polish(h, deadline, rounds=3):
    """Exact-R polish + beta-homotopy + peak-window block polish."""
    if time.process_time() > deadline - 0.5:
        return h
    h = _lbfgs_all_pos(h, 500, deadline)
    R = R_of(h)
    # beta homotopy: smooth log-sum-exp approximation to Linf, ramping beta up
    for beta in (50.0, 200.0, 800.0, 3000.0):
        if time.process_time() > deadline - 0.5:
            break
        hb = _lbfgs_all_pos(h, 200, deadline, beta=beta)
        Rb = R_of(hb)
        if Rb > R:
            R = Rb
            h = hb
    # finish with sharp exact-R
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_all_pos(h, 300, deadline)
        if R_of(h2) > R:
            h = h2
    # peak-window block polish (allows fine shape tweaks near the peak)
    for _ in range(rounds):
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(h)
        h2 = _lbfgs_block(h, win, 300, deadline)
        if R_of(h2) > R_of(h):
            h = h2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.0

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_R = R_of(best_h)

    # Seed: extend start to the working resolution (or 4096 fresh).
    if best_h is not None:
        Nbase = len(best_h)
        cur = best_h.copy()
    else:
        Nbase = 4096
        x = np.linspace(0.0, 1.0, Nbase)
        cur = np.exp(-((x - 0.5) ** 2) / 0.02)
        cur /= cur.sum()
        best_h = cur.copy()
        best_R = R_of(cur)

    # Polish at current resolution
    cur = polish(cur, min(deadline, t0 + budget_seconds * 0.35))
    R = R_of(cur)
    print("seed polish R =", R, "N =", len(cur))
    if R > best_R:
        best_R = R; best_h = cur.copy()

    # Escalation ladder, but stop early if gains stall
    ladder = [4096, 8192, 16384, 24576, 32768]
    ladder = [N for N in ladder if N >= Nbase] or [Nbase]
    prev_R = R
    for N in ladder:
        if time.process_time() > deadline - 2.0:
            break
        if len(cur) != N:
            cur = prolongate(cur, N)
        # give each level a slice of remaining time
        now = time.process_time()
        remain = deadline - now
        slice_end = now + max(2.0, remain * 0.55)
        cur = polish(cur, min(deadline, slice_end))
        R = R_of(cur)
        print("level N =", N, "R =", R)
        if R > best_R:
            best_R = R; best_h = cur.copy()
        # if the last step gave no improvement, stop scaling
        if R <= prev_R + 1e-7 and N > Nbase:
            break
        prev_R = R

    # Final polish of the best-so-far within remaining budget
    if time.process_time() < deadline - 0.5:
        hf = polish(best_h, deadline)
        Rf = R_of(hf)
        if Rf > best_R:
            best_R = Rf
            best_h = hf

    print("best R =", best_R, "N =", len(best_h))
    return best_h

