    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _coarsen(h, f):
    N = h.size
    m = N // f
    if m <= 0:
        return None, 0
    hh = h[:m * f].reshape(m, f)
    g = hh.mean(axis=1)
    return g, m


def _upsample_tilt(g, N, f, rnd):
    """Split each coarse cell into f sub-steps with a linear ramp that
    concentrates mass toward the cell centre; alternate direction."""
    m = g.size
    frac = (np.arange(f, dtype=float) + 0.5) / f - 0.5  # in (-0.5, 0.5)
    sgn = 1.0 if (rnd + f) % 2 == 0 else -1.0
    tilt = 1.0 + 0.6 * sgn * frac  # ramp within cell
    tilt = np.clip(tilt, 0.02, None)
    hp = (g[:, None] * tilt[None, :]).ravel()
    if hp.size < N:
        hp = np.concatenate([hp, np.full(N - hp.size, hp[-1])])
    elif hp.size > N:
        hp = hp[:N]
    return hp


def _refine_support(h, deadline, rounds=3):
    """Reallocate the fixed number of steps: shrink the array by removing
    tiny/zero entries and re-optimise; this lets the optimizer place steps
    where they matter without changing resolution of the active region."""
    if time.process_time() >= deadline - 0.5:
        return h, R_of(h)
    best = h.copy()
    bestR = R_of(best)
    thr = 1e-4
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        mask = best > thr * best.max()
        if mask.all() or mask.sum() < 64:
            break
        idx = np.flatnonzero(mask)
        # compress support: keep only active indices, then re-optimise all
        hc = best[idx].copy()
        hc = _rescale(hc)
        hc = _lbfgs_all_pos(hc, 400, deadline - 0.5, beta=0.0)
        rc = R_of(hc)
        if rc > bestR + 1e-13:
            # expand back to original N by re-inserting zeros
            full = np.zeros_like(best)
            full[idx] = hc * np.sqrt(_knots(best).max() / max(_knots(hc).max(), 1e-30))
            full = _rescale(full)
            rf = R_of(full)
            if rf > bestR + 1e-13:
                best, bestR = full, rf
        thr *= 5.0
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Support refinement: drop near-zero steps and re-optimise on reduced grid.
    if time.process_time() < deadline - 3.0:
        ht, rt = _refine_support(best, deadline - 3.0)
        if rt > bestR + 1e-13:
            print("support refine R=%.7f (N=%d)" % (rt, ht.size))
            best, bestR = ht, rt

    # Coarse round-trip ladder with smooth ramp prolongation.
    N = best.size
    for rnd in (1, 2):
        for f in (4, 8, 16):
            if N // f < 6000:
                continue
            now = time.process_time()
            if now >= deadline - 1.5:
                break
            remaining = deadline - 1.5 - now
            share = max(1.0, min(remaining / 3.0, 6.0))
            g, m = _coarsen(best, f)
            if g is None or g.sum() <= 0:
                continue
            g = _rescale(g)
            gR = R_of(g)
            g, gR = run_cycle(g, gR, now + share)
            hp = _upsample_tilt(g, N, f, rnd)
            hp = _rescale(hp)
            hpR = R_of(hp)
            now2 = time.process_time()
            share2 = max(1.0, min(share, 6.0))
            hp, hpR = run_cycle(hp, hpR, now2 + share2)
            dR = hpR - bestR
            print("round %d f=%d R=%.7f dR=%.2e band01=%.2f%% band1=%.2f%%"
                  % (rnd, f, hpR, dR, 100.0 * _band_frac(hp, 0.001),
                     100.0 * _band_frac(hp, 0.01)))
            if hpR > bestR + 1e-9:
                best, bestR = hp.copy(), hpR

    # Extra support refinement after coarse ladder.
    if time.process_time() < deadline - 2.0:
        ht, rt = _refine_support(best, deadline - 2.0, rounds=2)
        if rt > bestR + 1e-13:
            print("support refine2 R=%.7f (N=%d)" % (rt, ht.size))
            best, bestR = ht, rt

    # Keep polishing.
    stall = 0
    while time.process_time() < deadline - 1.0:
        prev = bestR
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        if bestR - prev < 1e-10:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def _peak_band(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.array([0])
    idx = np.flatnonzero(Lf >= (1.0 - tol) * mx)
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    return idx


def _fun_grad_band(h, beta, band):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lb = Lf[band]
    mx = Lb.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lb - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num
    gLf[band] += w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_band(h0, band, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    band = np.asarray(band, dtype=int)

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_band(hh, beta, band)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_band_cycle(best, bestR, deadline):
    for tol, beta, it in [(0.02, 2e3, 400), (0.005, 2e4, 400),
                          (0.002, 2e5, 400), (0.001, 1e6, 500)]:
        if time.process_time() >= deadline - 0.5:
            break
        band = _peak_band(best, tol)
        ht = _lbfgs_band(best, band, beta, it, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        if time.process_time() < deadline - 0.5:
            hp = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r = R_of(hp)
            if r > bestR + 1e-13:
                best, bestR = hp.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR, 0.0


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


# ---- NEW: momentum-driven softmax polish on the whole support. After the
# last L-BFGS step, run a short gradient-ascent with Nesterov momentum on the
# log-objective. It can squeeze out the tiny plateau residue L-BFGS leaves
# because L-BFGS terminates on curvature/step tests, not on the actual R.

def _momentum_polish(h0, bestR, deadline, steps=400, lr=1e-3, mom=0.9):
    h = np.clip(h0, 0, None).copy()
    if h.sum() <= 0:
        return h0, bestR
    n = h.size
    v = np.zeros(n)
    cur = h.copy()
    curR = bestR
    best = h.copy()
    bestRr = bestR
    for k in range(steps):
        if time.process_time() >= deadline - 0.15:
            break
        val, g = _fun_grad(cur)
        # normalize gradient scale
        gn = np.linalg.norm(g)
        if gn <= 0 or not np.isfinite(gn):
            break
        g = g / gn
        v = mom * v - lr * g
        cur = np.clip(cur + v, 0.0, None)
        if cur.sum() <= 0:
            break
        cur = _rescale(cur)
        r = R_of(cur)
        if r > bestRr + 1e-14:
            bestRr = r
            best = cur.copy()
    return best, bestRr


def _random_bump(best, bestR, deadline, trials=400):
    h = best.copy()
    n = h.size
    if n == 0:
        return best, bestR
    supp = np.flatnonzero(h > 0)
    if supp.size == 0:
        return best, bestR
    rng = np.random.default_rng(12345)
    step = 0.02 * h.max()
    for _ in range(trials):
        if time.process_time() >= deadline - 0.3:
            break
        i = int(supp[rng.integers(0, supp.size)])
        delta = step * (rng.random() * 2.0 - 1.0)
        old = h[i]
        nh = max(0.0, old + delta)
        if nh == old:
            continue
        h[i] = nh
        r = R_of(h)
        if r > bestR + 1e-13:
            bestR = r
            best = h.copy()
        else:
            h[i] = old
        if rng.random() < 0.01:
            step *= 0.9
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 4.0:
        best, bestR = _peak_band_cycle(best, bestR, deadline - 4.0)
        print("peak-band cycle R=%.7f" % bestR)

    if time.process_time() < deadline - 3.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 3.0)
        print("base cycle R=%.7f" % bestR)

    last_print = time.process_time()
    while time.process_time() < deadline - 1.5:
        prevR = bestR
        best, bestR = _peak_band_cycle(best, bestR, deadline - 1.5)
        if time.process_time() < deadline - 1.2:
            st, r = _mini_cycle(best, bestR, deadline - 1.2)
            if r > bestR + 1e-13:
                best, bestR = st, r
        if bestR - prevR < 1e-10:
            if time.process_time() < deadline - 1.2:
                st, r, _ = run_cycle(best, bestR, deadline - 1.2)
                if r > bestR + 1e-13:
                    best, bestR = st, r
        if time.process_time() - last_print > 8.0:
            last_print = time.process_time()
            print("iter R=%.7f band01 %.2f%%" %
                  (bestR, 100.0 * _band_frac(best, 0.001)))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    # NEW: momentum polish on the true objective, then random bumps
    if time.process_time() < deadline - 0.3:
        hp, rp = _momentum_polish(best, bestR, deadline - 0.3,
                                  steps=600, lr=5e-4, mom=0.9)
        if rp > bestR + 1e-13:
            best, bestR = hp, rp
        print("momentum R=%.7f" % bestR)

    if time.process_time() < deadline - 0.25:
        best, bestR = _random_bump(best, bestR, deadline - 0.25, trials=300)
        print("bump R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_interior_beta(h0, free, beta, maxiter, deadline):
    return _lbfgs_block(h0, free, maxiter, deadline, beta=beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _interior_beta_phase(best, bestR, deadline):
    h = np.clip(best, 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return best, bestR
    active = np.flatnonzero(h > 1e-6 * mx)
    if active.size < 4:
        return best, bestR
    i0 = int(active.min())
    i1 = int(active.max())
    L = i1 - i0 + 1
    lo = i0 + int(0.10 * L)
    hi = i0 + int(0.90 * L)
    if hi <= lo:
        return best, bestR
    free = np.arange(lo, hi + 1)
    betas = [1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7]
    cur = h
    curR = bestR
    bestArr = best.copy()
    bestR2 = bestR
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            print("interior-beta: out of time at beta=%.0e" % beta)
            break
        ht = _lbfgs_interior_beta(cur, free, beta, 80, deadline - 0.5)
        r = R_of(ht)
        b1 = _band_frac(ht, 0.01)
        print("interior-beta %.0e: R=%.9f band1=%.4f" % (beta, r, b1))
        if r > bestR2 + 1e-15:
            bestArr, bestR2 = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            cur, curR = ht, r
    print("interior-beta done: best R=%.9f (start %.9f)" % (bestR2, bestR))
    return bestArr, bestR2


# ---------------- Experiment: chained support extension ----------------

def _estimate_rho(h):
    """Estimate geometric decay ratio from outer active cells on each side."""
    h = np.asarray(h, dtype=float)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return 0.9
    pos = np.flatnonzero(h > 1e-9 * mx)
    if pos.size < 4:
        return 0.9
    ratios = []
    # left side: first up to 200 positive cells
    lo_idx = pos[:min(200, pos.size)]
    for a, b in zip(lo_idx[:-1], lo_idx[1:]):
        if h[a] > 0 and b == a + 1:
            ratios.append(h[b] / h[a])
    # right side: last up to 200 positive cells
    hi_idx = pos[-min(200, pos.size):]
    for a, b in zip(hi_idx[:-1], hi_idx[1:]):
        if h[a] > 0 and b == a + 1:
            ratios.append(h[b] / h[a])
    if not ratios:
        return 0.9
    rho = float(np.median(ratios))
    rho = min(max(rho, 0.5), 0.98)
    return rho


def _extend(h, pad):
    """Pad both ends with a matched geometric tail."""
    h = np.asarray(h, dtype=float)
    rho = _estimate_rho(h)
    left_toe = h[0] if h[0] > 0 else (h[h > 0][0] if np.any(h > 0) else 1.0)
    right_toe = h[-1] if h[-1] > 0 else (h[h > 0][-1] if np.any(h > 0) else 1.0)
    # left tail: values decreasing outward from h[0]
    left_tail = left_toe * rho ** np.arange(pad, 0, -1)
    right_tail = right_toe * rho ** np.arange(1, pad + 1)
    h2 = np.concatenate([left_tail, h, right_tail])
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: chained support extension rounds ----
    PAD = 2000
    N_ROUNDS = 8
    for rnd in range(N_ROUNDS):
        if time.process_time() >= deadline - 8.0:
            print("extension: stopping at round %d (time)" % rnd)
            break
        try:
            ht = _extend(best, PAD)
            r0 = R_of(ht)
            print("round %d extend: N=%d R=%.9f (best %.9f, drop %.2e)" %
                  (rnd, ht.size, r0, bestR, bestR - r0))
            ht = _lbfgs_all_pos(ht, 600, deadline - 0.5, beta=0.0)
            n = ht.size
            k = min(2000, n // 4)
            if k > 0:
                outer = np.concatenate((np.arange(0, k),
                                        np.arange(n - k, n)))
                ht = _lbfgs_block(ht, outer, 200, deadline - 0.5, beta=0.0)
                ht = _lbfgs_block(ht, outer, 200, deadline - 0.5, beta=1e7)
            win = _peak_window(ht, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(ht, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            b5 = _band_frac(ht, 0.05)
            print("round %d done: N=%d R=%.9f zeros=%.1f%% band5=%.4f" %
                  (rnd, ht.size, r, 100.0 * np.mean(ht <= 0), b5))
            if r > bestR + 1e-9:
                best, bestR = ht.copy(), r
                origin = origin + '+ext%d' % rnd
                print("round %d ACCEPTED: R=%.9f" % (rnd, bestR))
            else:
                print("round %d reverted (no gain)" % rnd)
        except Exception as e:
            print("round %d failed: %s" % (rnd, e))

    # ---- Base's alternating polish loop until deadline ----
    while time.process_time() < deadline - 0.5:
        prevR = bestR
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        if bestR <= prevR + 1e-13:
            # try a broader pass to keep improving
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
            else:
                break

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

