    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * 0.15))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


def _block_average(h, N0):
    N = h.size
    if N == N0:
        return h.copy()
    edges = np.linspace(0, N, N0 + 1).astype(int)
    out = np.add.reduceat(h, edges[:-1])
    return out


def _staircase_to(h, N_target):
    n = h.size
    if n == N_target:
        return h.copy()
    edges = np.linspace(0, n, N_target + 1).astype(int)
    edges[-1] = n
    out = np.add.reduceat(h, edges[:-1])
    return out


def _escalate_through(h, levels, deadline, bestH, bestRH, per_level_iters=100):
    cur = h.copy()
    for N in levels:
        if time.process_time() >= deadline - 0.5:
            break
        if cur.size != N:
            cur = _staircase_to(cur, N)
        cur = _rescale(cur)
        sub = min(deadline, time.process_time() + 3.0)
        hs = _lbfgs_log(cur, per_level_iters, sub)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
        cur = hs
        for beta in (1e2, 1e3, 1e5, 1e6):
            if time.process_time() >= deadline - 0.5:
                break
            sub = min(deadline, time.process_time() + 2.0)
            hb = _lbfgs_log(cur, 80, sub, beta=beta)
            rb = R_of(hb)
            if rb > bestRH + 1e-13:
                bestH, bestRH = hb.copy(), rb
            cur = hb
        if time.process_time() < deadline - 0.5:
            sub = min(deadline, time.process_time() + 2.0)
            hp, rp = _peak_polish(cur, R_of(cur), 100, sub)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
            cur = hp
    return bestH, bestRH, cur


def _smooth_extend(h, N_target):
    """Upsample h to N_target by linear interpolation (mass-preserving-ish)."""
    n = h.size
    if n == N_target:
        return h.copy()
    xold = (np.arange(n) + 0.5) / n
    xnew = (np.arange(N_target) + 0.5) / N_target
    out = np.interp(xnew, xold, h, left=h[0], right=h[-1])
    # mass preservation
    if out.sum() > 0:
        out = out * (h.sum() / out.sum())
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    N_final = best.size

    # ---- key new idea: try different N values (refine & coarsen) ----
    # The optimum shape depends on N; exploring around N_final can escape local optima.
    N_variants = []
    for mult in (0.5, 0.75, 1.5, 2.0):
        Nv = int(N_final * mult)
        if 256 <= Nv <= 1000000:
            N_variants.append(Nv)

    candidates = [(bestR, best.copy())]

    # ---- refine/coarsen exploration ----
    for Nv in N_variants:
        if time.process_time() >= deadline - 8.0:
            break
        if Nv < N_final:
            hv = _block_average(best, Nv)
        else:
            hv = _smooth_extend(best, Nv)
        hv = _rescale(hv)
        # polish at smaller N (fast), then escalate back to N_final
        sub = min(deadline - 5.0, time.process_time() + 4.0)
        hv = _lbfgs_log(hv, 300, sub)
        rv = R_of(hv)
        # bring back to N_final
        if hv.size != N_final:
            if hv.size < N_final:
                hv = _staircase_to(hv, N_final)
            else:
                hv = _block_average(hv, N_final)
        hv = _rescale(hv)
        sub = min(deadline - 4.0, time.process_time() + 4.0)
        hv = _lbfgs_log(hv, 300, sub)
        rv = R_of(hv)
        candidates.append((rv, hv.copy()))
        print("N-variant %d R=%.7f (best %.7f)" % (Nv, rv, max(bestR, rv)))
        if rv > bestR + 1e-13:
            best, bestR = hv.copy(), rv

    candidates.sort(key=lambda x: -x[0])
    top = candidates[:3]
    if start_bestR > 0:
        top.append((start_bestR, start_best))

    # ---- main polish loop on top candidates ----
    loop_end = t0 + budget_seconds * 0.88
    roundN = 0
    ladder = (4, 8, 16, 32, 64, 128)
    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 2.0:
        roundN += 1
        improved = False
        for rb, hb in top:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 2.0:
                break
            cur = hb
            if cur.size != N_final:
                cur = _staircase_to(cur, N_final) if cur.size < N_final else _block_average(cur, N_final)
            cur = _rescale(cur)
            sub = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(cur, 200, sub)
            rs = R_of(hs)
            if rs > bestR + 1e-13:
                best, bestR = hs.copy(), rs
                improved = True
            cur = hs
            for beta in (1e2, 1e3, 1e5):
                if time.process_time() >= loop_end - 1.5:
                    break
                sub = min(loop_end, time.process_time() + 2.0)
                hb2 = _lbfgs_log(cur, 80, sub, beta=beta)
                rb2 = R_of(hb2)
                if rb2 > bestR + 1e-13:
                    best, bestR = hb2.copy(), rb2
                    improved = True
                cur = hb2
            if time.process_time() < loop_end - 1.0:
                sub = min(loop_end, time.process_time() + 2.0)
                hp, rp = _peak_polish(cur, R_of(cur), 100, sub)
                if rp > bestR + 1e-13:
                    best, bestR = hp.copy(), rp
                    improved = True
        # p-norm homotopy on best
        for p in ladder:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 2.0:
                break
            sub = min(loop_end, time.process_time() + 3.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(best, 150, sub, fg=fg)
            r = R_of(h)
            if r > bestR + 1e-13:
                best, bestR = h.copy(), r
                improved = True
        print("round %d R=%.7f" % (roundN, bestR))
        if not improved and roundN > 2:
            break

    # ---- Final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
        print("final sharp R=%.7f" % bestR)

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def run_cycle(best, bestR, deadline, scale=1.0):
    for beta in (32, 128, 512, 2048):
        if time.process_time() > deadline - 4.0:
            return best, bestR
        ht = _lbfgs_all_pos(best, int(400 * scale), deadline - 2.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ht = _lbfgs_all_pos(best, int(800 * scale), deadline - 1.0, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-13:
        best, bestR = ht.copy(), r
    for tol, padf, extra in ((0.999, 0.6, 512), (0.9999, 0.3, 256), (1.0, 0.1, 128)):
        if time.process_time() > deadline - 2.0:
            break
        win = _peak_window(best, tol, padf, extra)
        ht = _lbfgs_block(best, win, int(400 * scale), deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Level 1: base polish at current N.
    cur_h, cur_R = run_cycle(best_h.copy(), best_R, deadline, scale=1.0)
    if cur_R > best_R:
        best_R, best_h = cur_R, cur_h.copy()
    print("after base cycle R=%.6f N=%d" % (best_R, best_h.size))

    # Escalation ladder.
    for N_target, scale in ((65536, 1.0), (131072, 2.0)):
        if time.process_time() > deadline - 8.0:
            break
        if best_h.size >= N_target:
            continue
        hN = _rescale(_prolongate_mass(best_h, N_target))
        RN = R_of(hN)
        print("prolongated N=%d R=%.6f" % (N_target, RN))
        hN, RN = run_cycle(hN, RN, deadline, scale=scale)
        print("level N=%d R=%.6f" % (N_target, RN))
        if RN > best_R:
            best_R, best_h = RN, hN.copy()

    # Final tight polish at finest level.
    if time.process_time() < deadline - 6.0:
        ht = _lbfgs_all_pos(best_h, 400, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > best_R:
            best_R, best_h = r, ht.copy()
        win = _peak_window(best_h, 1.0, 0.15, 256)
        ht = _lbfgs_block(best_h, win, 400, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > best_R:
            best_R, best_h = r, ht.copy()
        ht = _lbfgs_block(best_h, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > best_R:
            best_R, best_h = r, ht.copy()
        print("final tight R=%.6f N=%d" % (best_R, best_h.size))

    # Keep cycling homotopy at finest level until deadline.
    it = 0
    while time.process_time() < deadline - 3.0:
        it += 1
        cur_h, cur_R = run_cycle(best_h.copy(), best_R, deadline, scale=1.0)
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()
        print("cycle#%d R=%.6f best=%.6f" % (it, cur_R, best_R))

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

