                origin = origin + '+pk0'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk7'
    except Exception as e:
        print("polish loop failed: %s" % e)

    # ---- Outer-window passes ----
    try:
        n = best.size
        k = min(2000, n // 4)
        if k > 0:
            outer = np.concatenate((np.arange(0, k), np.arange(n - k, n)))
            for beta in (0.0, 1e7):
                if time.process_time() >= deadline - 0.5:
                    break
                ht = _lbfgs_block(best, outer, 200, deadline - 0.5, beta=beta)
                r = R_of(ht)
                print("outer pass beta=%.0e: R=%.9f" % (beta, r))
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+outer%.0e' % beta
    except Exception as e:
        print("outer pass failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": hinge_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        return fg(np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------- NEW: adaptive resolution refinement ----------
# The plateau structure of near-optimal f*f has fine-scale structure. The
# previous program was stuck at fixed N. We now (a) upsample the current
# best by linear interpolation into a finer grid, (b) re-optimize on the
# finer grid with L-BFGS, (c) repeat. This lets the plateau widen and R rise.

def _upsample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    newn = (n - 1) * factor + 1
    xs = np.arange(n, dtype=float)
    xn = np.linspace(0.0, n - 1.0, newn)
    out = np.interp(xn, xs, h)
    return _rescale(np.clip(out, 0, None))


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 2:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor).sum(axis=1)
    return _rescale(np.clip(hh, 0, None))


def _adaptive_refine(best, bestR, deadline, maxN=1000000):
    """Repeatedly upsample + optimize. Keeps best across resolutions."""
    factor = 2
    while time.process_time() < deadline - 3.0:
        if best.size * factor > maxN:
            break
        # upsample and reoptimize
        hu = _upsample(best, factor)
        # quick sharpen: seed zeros so L-BFGS can grow plateau edges
        hu = _seed_zeros(hu)
        ht = _lbfgs_all_pos(hu, 500, deadline - 2.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-12:
            best, bestR = ht.copy(), r
        else:
            # try a beta-annealed version on the upsampled grid
            if time.process_time() < deadline - 3.0:
                ht2 = _lbfgs_all_pos(hu, 300, deadline - 2.5, beta=1e7)
                r2 = R_of(ht2)
                if r2 > bestR + 1e-12:
                    best, bestR = ht2.copy(), r2
                else:
                    # upsample did not help: try finer block polish on the
                    # upsampled grid with a peak window; keep best.
                    win = _peak_window(ht, pad_frac=0.4, extra=512)
                    ht3 = _lbfgs_block(ht, win, maxiter=200,
                                       deadline=deadline - 2.5, beta=1e8)
                    r3 = R_of(ht3)
                    if r3 > bestR + 1e-12:
                        best, bestR = ht3.copy(), r3
        # occasionally try a coarser representation: this can escape local
        # minima by smoothing the plateau and re-growing it.
        if time.process_time() < deadline - 3.0:
            hd = _downsample(best, 2)
            hd = _seed_zeros(hd)
            ht4 = _lbfgs_all_pos(hd, 300, deadline - 2.5, beta=0.0)
            r4 = R_of(ht4)
            if r4 > bestR + 1e-12:
                best, bestR = ht4.copy(), r4
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- Adaptive resolution refinement (new idea) ----
    if time.process_time() < deadline - 8.0:
        try:
            ar_h, arR = _adaptive_refine(best, bestR, deadline - 6.0)
            print("adaptive R=%.7f (N=%d)" % (arR, ar_h.size))
            if arR > bestR + 1e-13:
                best, bestR = ar_h.copy(), arR
            else:
                alt_cand, altR = ar_h, arR
        except Exception as e:
            print("adaptive failed: %s" % e)

    # ---- Standard polishing cycle ----
    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Final push: alternate adaptive + standard ----
    while time.process_time() < deadline - 3.0:
        try:
            ar_h, arR = _adaptive_refine(best, bestR,
                                         min(deadline - 2.0,
                                             time.process_time() + 10.0))
            if arR > bestR + 1e-13:
                best, bestR = ar_h.copy(), arR
        except Exception:
            pass
        if time.process_time() < deadline - 3.0:
            best, bestR = run_cycle(best, bestR, deadline - 2.0)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        out = {"best": best}
        if alt_cand is not None and altR > start_bestR - 1e-6:
            out["alternative"] = alt_cand
        return out
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

