    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _short_homotopy(h, R, deadline, betas, iters):
    best, bestR = h, R
    for beta in betas:
        if time.process_time() > deadline - 2.0:
            break
        ht = _lbfgs_all_pos(best, iters, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _tight_polishes(h, R, deadline, iters, rounds=2):
    best, bestR = h, R
    for _ in range(rounds):
        if time.process_time() > deadline - 2.0:
            break
        # full-grid sharp
        ht = _lbfgs_all_pos(best, iters, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        # alternating peak-window polishes
        for tol, padf, extra, beta in ((1.0, 0.15, 256, 0.0),
                                       (1.0, 0.03, 256, 0.0),
                                       (1.0, 0.03, 256, 2048.0),
                                       (0.9999, 0.05, 256, 0.0)):
            if time.process_time() > deadline - 1.0:
                break
            win = _peak_window(best, tol, padf, extra)
            ht = _lbfgs_block(best, win, iters, deadline - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.5

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Immediately prolongate to N=131072.
    N1 = 131072
    if best_h.size < N1:
        hN = _rescale(_prolongate_mass(best_h, N1))
        RN = R_of(hN)
        print("prolongated N=%d R=%.6f" % (N1, RN))
        if RN > best_R:
            best_R, best_h = RN, hN.copy()

    # Short homotopy at N=131072.
    best_h, best_R = _short_homotopy(best_h, best_R, deadline,
                                     (32, 64, 128, 256), 60)
    print("after homotopy N=%d R=%.6f" % (best_h.size, best_R))

    # Bulk: alternating tight peak-window polishes + full-grid at N=131072.
    # Reserve time to try N=262144 if >15s remain.
    reserve = 15.0
    while time.process_time() < deadline - reserve - 2.0:
        prev = best_R
        best_h, best_R = _tight_polishes(best_h, best_R, deadline - reserve,
                                         400, rounds=1)
        print("polish N=%d R=%.6f best=%.6f" % (best_h.size, best_R, best_R))
        if time.process_time() > deadline - reserve - 2.0:
            break
        if best_R - prev < 1e-9 and time.process_time() > deadline - reserve - 6.0:
            # diminishing returns; break to try finer level
            break

    # If enough time remains, prolongate to N=262144 and repeat with half iters.
    if time.process_time() < deadline - 15.0:
        N2 = 262144
        hN = _rescale(_prolongate_mass(best_h, N2))
        RN = R_of(hN)
        print("prolongated N=%d R=%.6f" % (N2, RN))
        if RN > best_R:
            best_R, best_h = RN, hN.copy()
        best_h, best_R = _short_homotopy(best_h, best_R, deadline,
                                         (32, 64, 128, 256), 30)
        print("after homotopy N=%d R=%.6f" % (best_h.size, best_R))
        while time.process_time() < deadline - 2.0:
            best_h, best_R = _tight_polishes(best_h, best_R, deadline,
                                             200, rounds=1)
            print("polish N=%d R=%.6f" % (best_h.size, best_R))
            if time.process_time() > deadline - 3.0:
                break

    # Final polish at finest level.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best_h, 200, deadline, beta=0.0)
        r = R_of(ht)
        if r > best_R:
            best_R, best_h = r, ht.copy()

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fg_hess(h, beta):
    """Return (val, grad, hessp) for beta-softmax log-objective."""
    s = h.sum()
    n = h.size
    if s <= 0:
        return 1e18, np.zeros(n), (lambda v: np.zeros(n))
    num, dq, Lf = _num_and_dq(h)
    K = Lf.size
    mx = Lf.max()
    if mx <= 0:
        v0, g0 = _fun_grad(h)
        return v0, g0, (lambda v: np.zeros(n))
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)

    mask = (h > 0).astype(float)

    def hessp(v):
        v = np.asarray(v, dtype=float)
        v = v * mask
        # dLf = 2 * conv(h, v) padded to K
        if n > 1500:
            c = fftconvolve(h, v)
        else:
            c = np.convolve(h, v)
        dLf = np.zeros(K)
        m = min(K, 2 * n - 1)
        dLf[:m] = 2.0 * c[:m]
        u = float(w @ dLf)
        # dq2 = (4*dLf[j] + dLf[j-1] + dLf[j+1]) / 3
        dq2 = (4.0 * dLf) / 3.0
        dq2[1:] += dLf[:-1] / 3.0
        dq2[:-1] += dLf[1:] / 3.0
        diff = float(dq @ dLf)
        kv = -dq2 / num + diff * dq / (num * num)
        kv += beta * (w * (dLf - u)) / sm - w * u / (sm * sm)
        out = _backprop(kv, v) - 2.0 * v.sum() / (s * s)
        return out * mask

    return val, grad, hessp


def _fun_grad_hinge(h, lam, eps):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    M = Lf[m]
    if M <= 0:
        return _fun_grad(h)
    K = Lf.size
    u = np.maximum((1.0 - eps) * M - Lf, 0.0) / M
    q = float(np.mean(u * u)) + 1e-12
    gLf = -dq / num
    gLf[m] += 1.0 / M
    du_dM = (1.0 - eps) / M - u / M
    dq_dM = float(np.mean(2.0 * u * du_dM))
    gLf[m] += (lam / q) * dq_dM
    gLf += -(2.0 * lam / (M * K * q)) * u
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + lam * np.log(q)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tight=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    if tight:
        opts['ftol'] = 0.0
        opts['gtol'] = 0.0
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, hinge=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if hinge is not None:
        lam, eps = hinge
        fg = (lambda hh: _fun_grad_hinge(hh, lam, eps))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- Experiment: smooth multiplicative envelope ----------------

def _support_bounds(h):
    mx = h.max()
    if mx <= 0:
        return 0, h.size - 1
    act = np.flatnonzero(h > 1e-9 * mx)
    if act.size == 0:
        return 0, h.size - 1
    return int(act.min()), int(act.max())


def _make_basis(N, K, i0, i1):
    L = max(1, i1 - i0)
    idx = np.arange(i0, i1 + 1, dtype=float)
    x = (idx - i0) / float(L)
    B = np.zeros((K, N), dtype=float)
    for k in range(K):
        B[k, i0:i1 + 1] = np.cos(np.pi * k * x)
    return B


def _envelope_opt(h0, K, deadline, iters, c_init=None, additive=False):
    h0 = np.clip(h0, 0, None)
    if h0.sum() <= 0:
        return h0, 0.0, None
    N = h0.size
    i0, i1 = _support_bounds(h0)
    if i1 <= i0:
        return h0, R_of(h0), c_init
    B = _make_basis(N, K, i0, i1)
    if c_init is None:
        c = np.zeros(K)
    else:
        c = np.asarray(c_init, dtype=float).copy()
        if c.size != K:
            c2 = np.zeros(K)
            m = min(K, c.size)
            c2[:m] = c[:m]
            c = c2

    def build(cvec):
        if additive:
            h = h0 + (cvec @ B)
            h = np.clip(h, 0, None)
        else:
            e = np.exp(np.clip(cvec @ B, -20.0, 20.0))
            h = h0 * e
        return _rescale(h)

    def f(cvec):
        h = build(cvec)
        val, g = _fun_grad(h)
        if additive:
            hraw = h0 + (cvec @ B)
            mask = (hraw > 0).astype(float)
            gc = np.array([np.sum(g * B[k] * mask) for k in range(K)])
        else:
            hraw = h0 * np.exp(np.clip(cvec @ B, -20.0, 20.0))
            gc = np.array([np.sum(g * hraw * B[k]) for k in range(K)])
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c, jac=True, method='L-BFGS-B',
                       bounds=[(-1.0, 1.0)] * K,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-16, 'gtol': 1e-16})
        c = res.x
    except (TimeoutError, Exception):
        pass
    h = build(c)
    return h, R_of(h), c


# ---------------- Experiment: hinge on deficit ----------------

def _hinge_phase(h, lam, eps, deadline):
    if time.process_time() >= deadline - 0.5:
        return h
    win = _peak_window(h, pad_frac=0.5, extra=2048)
    ht = _lbfgs_block(h, win, 200, deadline - 0.3, hinge=(lam, eps))
    if time.process_time() < deadline - 0.5:
        ht2 = _lbfgs_all_pos(ht, 100, deadline - 0.3, beta=0.0)
        if R_of(ht2) >= R_of(ht):
            ht = ht2
    return ht


# ---------------- Experiment: trust-ncg with exact Hessian-vector ----------------

def _trust_ncg_all(h0, beta, deadline, maxiter=25):
    if time.process_time() >= deadline - 0.3:
        return h0, None
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, None
    n = h.size
    val0, g0 = _fun_grad_beta(h, beta)
    try:
        _, _, hessp = _fg_hess(h, beta)
    except Exception:
        return h0, None

    def f(x):
        hh = np.clip(x, 0.0, None)
        v, g = _fun_grad_beta(hh, beta)
        return v, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='trust-ncg',
                       hessp=hessp, callback=cb,
                       options={'maxiter': maxiter, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return h0, None
    if res is None:
        return h0, None
    h2 = _rescale(np.clip(res.x, 0.0, None))
    info = {'val0': val0, 'val1': res.fun,
            'step': float(np.linalg.norm(res.x - h))}
    return h2, info


def _trust_ncg_block(h0, free, beta, deadline, maxiter=25):
    if time.process_time() >= deadline - 0.3:
        return h0, None
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, None
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0, None
    x0 = h[active].copy()
    val0, g0 = _fun_grad_beta(h, beta)

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        v, g = _fun_grad_beta(hh, beta)
        return v, g[active]

    def hessp(v):
        hh = h.copy()
        hh[active] = np.clip(x0, 0.0, None)
        _, _, hp_full = _fg_hess(hh, beta)
        vv = np.zeros_like(h)
        vv[active] = v
        return hp_full(vv)[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='trust-ncg',
                       hessp=hessp, callback=cb,
