        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- New: crest-shaping via peaked-knot surrogate ----------------
# Key idea: the max-knot term log(Lm) only sees the single largest knot, so the
# optimizer collapses onto a narrow peak. Instead we maximize log(sum_j L_j^p)
# with a moderate p (a smooth "p-norm" of the knots), which directly rewards
# flattening/multiplicity of near-max knots -- exactly the structure that raises
# ||f*f||_2^2 / ||f*f||_inf. We sweep p from small to large and polish exactly.

def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 1e-12, None)
    # p-norm of knots
    Lp = Lc ** p
    Sp = Lp.sum()
    if Sp <= 0:
        return _fun_grad(h)
    # d/dh log(Sp) = (1/Sp) * sum_j p L_j^(p-1) dL_j/dh
    wL = p * (Lc ** (p - 1.0)) / Sp
    gLf = -dq / num + wL
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Sp) / p
    return val, grad


def _lbfgs_pnorm(h0, p, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_pnorm(hh, p)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _pnorm_climb(best, bestR, deadline):
    """Sweep p from 2 up to ~40, polishing the exact objective after each."""
    p_list = [2.0, 3.0, 4.0, 6.0, 8.0, 12.0, 16.0, 24.0, 32.0, 48.0]
    cur = best.copy()
    for p in p_list:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_pnorm(cur, p, 400, deadline - 0.8)
        # exact polish
        ht2 = _lbfgs_all_pos(ht, 250, deadline - 0.8, beta=0.0)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
            cur = ht2.copy()
        else:
            cur = ht.copy()
        print("pnorm p=%.1f: R=%.9f (best %.9f)" % (p, r2, bestR))
    return best, bestR


def _softmax_ladder(best, bestR, deadline):
    """Fine softmax-beta ladder with exact polish after each stage."""
    for beta in [1e4, 1e5, 1e6, 1e7, 1e8]:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(best, 300, deadline - 0.8, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        print("softmax beta=%.0e: R=%.9f" % (beta, bestR))
    return best, bestR


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.15, 96, 1e8), (0.30, 192, 1e8),
              (0.50, 384, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- New p-norm crest-shaping climb (the main new idea) ----
    if time.process_time() < deadline - 5.0:
        ht, rt = _pnorm_climb(best, bestR, deadline - 5.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+pnorm'
        print("after pnorm R=%.7f" % bestR)

    # ---- Softmax beta ladder ----
    if time.process_time() < deadline - 3.0:
        ht, rt = _softmax_ladder(best, bestR, deadline - 3.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+softmax'

    # ---- Local peak-window cycle to squeeze remaining gains ----
    while time.process_time() < deadline - 1.5:
        ht, rt = run_cycle(best, bestR, deadline - 1.0)
        if rt > bestR + 1e-14:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        else:
            break

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    alt = best if (start_best is None or bestR > start_bestR + 1e-13) else start_best
    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if beta > 0:
        mx = Lf.max()
        if mx <= 0:
            return 1e18, np.zeros(h.size)
        e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
        Z = e.sum()
        w = e / Z
        sm = mx + np.log(Z) / beta
        gLf = -dq / num + w / sm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    else:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta))

    def f(x):
        return fg(np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _upsample(h, factor):
    """Piecewise-constant refinement: each cell splits into `factor` cells."""
    n = h.size
    m = n * factor
    out = np.repeat(h, factor)
    return _rescale(out)


def _random_perturb(h, rng, scale):
    """Multiplicative random perturbation to escape local optima."""
    out = h * np.exp(rng.normal(0.0, scale, size=h.size))
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0 and np.asarray(start).sum() > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float).copy(), 0, None))
        start_best, start_bestR = base.copy(), R_of(base)
    else:
        N = 8192
        i = np.arange(N, dtype=float)
        h = np.sqrt(i + 1.0) - np.sqrt(i)
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Primary polish stages on the current resolution.
    stages = [
        ('glob0', 'all', 0.0, 0.0, 400),
        ('glob7', 'all', 1e7, 0.0, 300),
        ('win05', 'win', 1e8, 0.05, 250),
        ('glob0b', 'all', 0.0, 0.0, 400),
        ('win10', 'win', 1e8, 0.10, 250),
        ('glob0c', 'all', 0.0, 0.0, 300),
        ('win02', 'win', 1e8, 0.02, 200),
        ('glob7b', 'all', 1e7, 0.0, 200),
    ]

    def run_stages(stages, best, bestR, deadline):
        for name, kind, beta, pad, iters in stages:
            if time.process_time() >= deadline - 0.6:
                break
            if kind == 'all':
                ht = _lbfgs_all(best, iters, deadline - 0.5, beta=beta)
            else:
                win = _peak_window(best, pad_frac=pad, extra=128)
                ht = _lbfgs_block(best, win, iters, deadline - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                gain = r - bestR
                best, bestR = ht, r
                print("%s: R=%.9f (+%.2e)" % (name, bestR, gain))
            else:
                print("%s: no gain (%.9f)" % (name, r))
        return best, bestR

    best, bestR = run_stages(stages, best, bestR, deadline)

    # Key new idea: resolution refinement.  Upsample the construction (which
    # is piecewise constant) onto a finer grid, then re-polish.  If the
    # resolution we have is not yet capturing the shape's true smooth optimum,
    # the finer grid can find extra R.  Only accept if it beats the incumbent.
    refine_plan = [(2, 1e8), (2, 1e8)]
    for factor, beta in refine_plan:
        if time.process_time() >= deadline - 3.0:
            break
        if best.size * factor > 900000:
            break
        hu = _upsample(best, factor)
        ru = R_of(hu)
        print("upsample x%d: R=%.9f (was %.9f)" % (factor, ru, bestR))
        # Polish the upsampled version, then compare.
        hu = _lbfgs_all(hu, 250, deadline - 1.0, beta=beta)
        hu = _lbfgs_all(hu, 250, deadline - 1.0, beta=0.0)
        ru = R_of(hu)
        if ru > bestR + 1e-14:
            gain = ru - bestR
            best, bestR = hu, ru
            print("refine x%d: R=%.9f (+%.2e, N=%d)" % (factor, bestR, gain, best.size))
        else:
            print("refine x%d: no gain (%.9f)" % (factor, ru))

    # Escape-local: perturb the peak window with multiplicative noise, re-polish,
    # keep only strict improvements.  Repeats until deadline.
    attempt = 0
    while time.process_time() < deadline - 2.0:
        attempt += 1
        scale = 0.01 + 0.02 * rng.random()
        hp = _random_perturb(best, rng, scale)
        # Only re-optimise the peak window plus a small margin (cheap).
        win = _peak_window(hp, pad_frac=0.15, extra=64)
        hp = _lbfgs_block(hp, win, 150, deadline - 1.0, beta=1e8)
        hp = _lbfgs_block(hp, win, 120, deadline - 1.0, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            gain = rp - bestR
            best, bestR = hp, rp
            print("perturb %d (s=%.3f): R=%.9f (+%.2e)" % (attempt, scale, bestR, gain))
        elif attempt % 5 == 0:
            print("perturb %d: no gain (%.9f)" % (attempt, rp))

    # Final fine polish at current resolution.
    if time.process_time() < deadline - 1.0:
        hs = _seed_zeros(best)
        ht = _lbfgs_all(hs, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("fine polish: R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

