    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _timed_beta_pass(h, beta, iters, cap_seconds):
    t0 = time.process_time()
    deadline = t0 + cap_seconds
    ht = _lbfgs_all_pos(h, iters, deadline, beta=beta)
    return ht, time.process_time() - t0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.5

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Phase A: timing probe at N=524288.
    N_fine = 524288
    N_coarse = 262144
    if best_h.size < N_fine:
        hN = _rescale(_prolongate_mass(best_h, N_fine))
    else:
        hN = best_h.copy()
    RN = R_of(hN)
    print("prolongated N=%d R=%.6f" % (hN.size, RN))

    # Probe: one beta=64 pass, 50 iters, capped at 12s.
    probe_deadline = min(deadline - 5.0, time.process_time() + 12.0)
    ht, dt = _timed_beta_pass(hN, 64, 50, max(0.5, probe_deadline - time.process_time()))
    rp = R_of(ht)
    print("probe beta=64 N=%d dt=%.2fs R=%.6f" % (ht.size, dt, rp))

    if dt > 10.0:
        N_work = N_coarse
        if best_h.size != N_coarse:
            hw = _rescale(_prolongate_mass(best_h, N_coarse))
        else:
            hw = best_h.copy()
        print("using N=%d (probe too slow)" % N_work)
    else:
        N_work = N_fine
        hw = ht if rp > RN else hN
        print("using N=%d" % N_work)

    Rw = R_of(hw)
    if Rw > best_R:
        best_R, best_h = Rw, hw.copy()
    hw = best_h.copy()

    betas = (16, 32, 64, 128, 256, 512, 1024)
    pad_fracs = (0.30, 0.15, 0.08)

    def phase_B(hw, Rw):
        for beta in betas:
            if time.process_time() > deadline - 3.0:
                return hw, Rw
            cap = min(8.0, deadline - time.process_time() - 2.0)
            if cap < 0.5:
                return hw, Rw
            ht = _lbfgs_all_pos(hw, 60, time.process_time() + cap, beta=beta)
            r = R_of(ht)
            if r > Rw + 1e-13:
                hw, Rw = ht, r
            print("rung beta=%d R=%.6f" % (beta, Rw))
            # peak-window polishes with varying pad_frac
            for pf in pad_fracs:
                if time.process_time() > deadline - 2.0:
                    break
                win = _peak_window(hw, 1.0, pf, 512)
                cap2 = min(4.0, deadline - time.process_time() - 1.5)
                if cap2 < 0.3:
                    break
                ht2 = _lbfgs_block(hw, win, 80,
                                   time.process_time() + cap2, beta=beta)
                r2 = R_of(ht2)
                if r2 > Rw + 1e-13:
                    hw, Rw = ht2, r2
            # tight exact peak-window pass
            if time.process_time() < deadline - 1.5:
                win = _peak_window(hw, 1.0, 0.05, 512)
                cap3 = min(4.0, deadline - time.process_time() - 1.0)
                if cap3 > 0.3:
                    ht3 = _lbfgs_block(hw, win, 80,
                                       time.process_time() + cap3, beta=0.0)
                    r3 = R_of(ht3)
                    if r3 > Rw + 1e-13:
                        hw, Rw = ht3, r3
            print("  after polishes R=%.6f" % Rw)
        return hw, Rw

    def phase_C(hw, Rw):
        # prune-and-reprolongate
        if time.process_time() > deadline - 3.0:
            return hw, Rw
        mean = hw.mean()
        keep = hw >= 1e-4 * mean
        if keep.sum() < 16 or keep.sum() == hw.size:
            return hw, Rw
        hc = hw[keep].copy()
        # re-optimize compacted array with beta=256
        cap = min(3.0, deadline - time.process_time() - 2.0)
        if cap > 0.3:
            ht = _lbfgs_all_pos(hc, 60, time.process_time() + cap, beta=256)
            rc = R_of(ht)
            if rc > 0:
                hc = ht
        # prolongate back to full N by cumulative mass
        hfull = _rescale(_prolongate_mass(hc, hw.size))
        rf = R_of(hfull)
        if rf > Rw + 1e-13:
            hw, Rw = hfull, rf
            print("prune+reprolongate R=%.6f (kept %d/%d)" % (Rw, keep.sum(), keep.size))
        else:
            print("prune+reprolongate no gain R=%.6f" % Rw)
        # one tight polish
        if time.process_time() < deadline - 1.5:
            win = _peak_window(hw, 1.0, 0.05, 512)
            cap = min(3.0, deadline - time.process_time() - 1.0)
            if cap > 0.3:
                ht = _lbfgs_block(hw, win, 80, time.process_time() + cap, beta=0.0)
                r = R_of(ht)
                if r > Rw + 1e-13:
                    hw, Rw = ht, r
                    print("  tight polish R=%.6f" % Rw)
        return hw, Rw

    # Phase B-C loop
    iteration = 0
    while time.process_time() < deadline - 2.0:
        iteration += 1
        hw, Rw = phase_B(hw, Rw)
        if Rw > best_R:
            best_R, best_h = Rw, hw.copy()
        print("after B#%d R=%.6f best=%.6f" % (iteration, Rw, best_R))
        if time.process_time() > deadline - 2.0:
            break
        hw, Rw = phase_C(hw, Rw)
        if Rw > best_R:
            best_R, best_h = Rw, hw.copy()
        print("after C#%d R=%.6f best=%.6f" % (iteration, Rw, best_R))
        if time.process_time() > deadline - 4.0:
            break

    # Final full-grid exact polish if time remains
    if time.process_time() < deadline - 1.0:
        cap = deadline - time.process_time() - 0.5
        ht = _lbfgs_all_pos(best_h, 100, time.process_time() + cap, beta=0.0)
        r = R_of(ht)
        if r > best_R:
            best_R, best_h = r, ht.copy()

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _rebin_blockmean(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _short_homotopy(h, R, deadline, betas, iters):
    best, bestR = h, R
    for beta in betas:
        if time.process_time() > deadline - 2.0:
            break
        ht = _lbfgs_all_pos(best, iters, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _tight_polishes(h, R, deadline, iters, rounds=2, pad_fracs=(0.15, 0.03, 0.03, 0.05)):
    best, bestR = h, R
    for _ in range(rounds):
        if time.process_time() > deadline - 2.0:
            break
        ht = _lbfgs_all_pos(best, iters, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        for padf, beta in zip(pad_fracs, (0.0, 0.0, 2048.0, 0.0)):
            if time.process_time() > deadline - 1.0:
                break
            win = _peak_window(best, 1.0, padf, 256)
            ht = _lbfgs_block(best, win, iters, deadline - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
    return best, bestR


def _coarse_polish(h0, deadline, betas, iters):
    best = _rescale(np.maximum(h0, 0))
    bestR = R_of(best)
    for beta in betas:
        if time.process_time() > deadline - 0.5:
            break
        ht = _lbfgs_all_pos(best, iters, deadline - 0.2, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        win = _peak_window(best, 1.0, 0.10, 64)
        ht = _lbfgs_block(best, win, iters, deadline - 0.2, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _perturb(h0, rng):
    n = h0.size
    x = (np.arange(n) + 0.5) / n
    noise = np.zeros(n)
    for k in range(1, 9):
        a = rng.uniform(-0.15, 0.15)
        phi = rng.uniform(0, 2 * np.pi)
        noise += a * np.cos(np.pi * k * x + phi)
    blk = 256
    nb = (n + blk - 1) // blk
    fac = rng.uniform(0.7, 1.4, size=nb)
    fac_full = np.repeat(fac, blk)[:n]
    out = h0 * np.exp(0.5 * noise) * fac_full
    return np.maximum(out, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.5

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    rng = np.random.default_rng(12345)

    # --- Coarse multi-start at N0=8192 ---
    N0 = 8192
    h0 = _rescale(_rebin_blockmean(best_h, N0))
    R0 = R_of(h0)
    print("rebin N=%d R=%.6f" % (N0, R0))

    # Polish base coarse
    base_deadline = min(deadline - 30.0, time.process_time() + 6.0)
    h0p, R0p = _coarse_polish(h0, base_deadline, (32, 128, 512, 2048), 80)
    if R0p > R0:
        h0, R0 = h0p, R0p
    print("coarse R0=%.6f" % R0)

    # 8 restarts
    n_restarts = 8
    coarse_cands = [(R0, h0.copy())]
    per_restart = 1.5
    for i in range(n_restarts):
        if time.process_time() > deadline - 30.0:
            break
        rdl = time.process_time() + per_restart
        hp = _perturb(h0, rng)
        hp = _rescale(hp)
        # 1.5s beta=64 L-BFGS + one peak-window pass
        ht = _lbfgs_all_pos(hp, 60, rdl, beta=64.0)
        r = R_of(ht)
        if time.process_time() < rdl:
            win = _peak_window(ht, 1.0, 0.10, 64)
            ht2 = _lbfgs_block(ht, win, 60, rdl, beta=0.0)
            r2 = R_of(ht2)
            if r2 > r:
                ht, r = ht2, r2
        print("restart %d R=%.6f (R0=%.6f)" % (i, r, R0))
        coarse_cands.append((r, ht.copy()))

    coarse_cands.sort(key=lambda t: -t[0])
    top3 = coarse_cands[:3]
    print("top coarse R: %s" % ", ".join("%.6f" % r for r, _ in top3))

    # --- Ladder: prolongate best through 32768 -> 131072 -> 262144 ---
    ladder_best_h = None
    ladder_best_R = -1.0
    levels = [32768, 131072, 262144]
    # time allocation: split remaining among levels
    for li, N in enumerate(levels):
        if time.process_time() > deadline - 4.0:
            break
        # pick best coarse candidate to prolongate (use top1 for first level,
        # then best so far)
        if li == 0:
            src = top3[0][1]
        else:
            src = ladder_best_h if ladder_best_h is not None else top3[0][1]
        hN = _rescale(_prolongate_mass(src, N))
        RN = R_of(hN)
        # reserve time for remaining levels
        remaining_levels = len(levels) - li
        level_deadline = time.process_time() + max(
            2.0, (deadline - 4.0 - time.process_time()) / remaining_levels)
        level_deadline = min(level_deadline, deadline - 4.0)
        hN, RN = _short_homotopy(hN, RN, level_deadline, (32, 64, 128, 256), 60)
        # peak-window polishes pad_frac 0.25 then 0.10
        for padf in (0.25, 0.10):
            if time.process_time() > level_deadline - 0.5:
                break
            win = _peak_window(hN, 1.0, padf, 256)
            ht = _lbfgs_block(hN, win, 100, level_deadline - 0.2, beta=0.0)
            r = R_of(ht)
            if r > RN + 1e-13:
                hN, RN = ht, r
        print("ladder N=%d R=%.6f" % (N, RN))
        if RN > ladder_best_R:
            ladder_best_R = RN
            ladder_best_h = hN.copy()

    # --- Final 10s full-array beta=1024 + tight exact polish ---
    if ladder_best_h is not None and time.process_time() < deadline - 1.0:
        fin_deadline = min(deadline - 0.5, time.process_time() + 10.0)
        ht = _lbfgs_all_pos(ladder_best_h, 200, fin_deadline - 2.0, beta=1024.0)
        r = R_of(ht)
        if r > ladder_best_R:
            ladder_best_h, ladder_best_R = ht, r
        ht = _lbfgs_all_pos(ladder_best_h, 200, fin_deadline, beta=0.0)
        r = R_of(ht)
        if r > ladder_best_R:
            ladder_best_h, ladder_best_R = ht, r
        print("final polish R=%.6f" % ladder_best_R)

    # --- Fallback: if ladder didn't beat start, run original p1222 path ---
    if ladder_best_h is None or ladder_best_R <= best_R + 1e-9:
        print("fallback to p1222 path")
        # Immediate prolongate to N=131072
