import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 1e-300, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w / Pm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _report(tag, h, R):
    mean = h.mean()
    ratio = (h.max() / mean) if mean > 0 else 0.0
    print("  %s R=%.7f zeros=%.1f%% max/mean=%.2f" %
          (tag, R, 100.0 * np.mean(h <= 0), ratio))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 16384
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    _report("base", best, bestR)

    cur = best.copy()
    curR = bestR

    # Phase 0: NEW — local support-window refinement on the start itself.
    # This is cheap and often nudges the plateau near the peak.
    if best.size > 32:
        sub_end = min(deadline - 2.0, time.process_time() + budget_seconds * 0.15)
        m = int(np.argmax(_knots(cur)))
        w = max(64, cur.size // 8)
        wlo = max(0, m - w)
        whi = min(cur.size - 1, m + w)
        h2 = _lbfgs_block(cur, np.arange(wlo, whi + 1), 200, sub_end)
        r2 = R_of(h2)
        if r2 > curR + 1e-13:
            cur, curR = h2, r2
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
        _report("window0", cur, curR)

    # Phase 1: p-norm polish to break plateaus near the peak.
    for p in (40.0, 100.0, 300.0):
        if time.process_time() > deadline - 3.0:
            break
        h = _lbfgs_log(cur, 120, min(deadline - 2.0,
                                     time.process_time() + 4.0),
                       fg=(lambda hh, pp=p: _fun_grad_pnorm(hh, pp)))
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h.copy(), r
            best, bestR = cur.copy(), curR

    # Phase 2: multi-scale prolongation. Try several factors
    scale_end = t0 + budget_seconds * 0.45
    factors = [2, 2, 3, 2]
    fi = 0
    while time.process_time() < scale_end - 5.0:
        factor = factors[fi % len(factors)]
        fi += 1
        seed = np.repeat(cur, factor).astype(float)
        seed = _rescale(seed)
        sub_end = min(scale_end, time.process_time() + 8.0)
        h = _lbfgs_log(seed, 200, sub_end)
        r = R_of(h)
        if time.process_time() < sub_end - 2.0:
            m = int(np.argmax(_knots(h)))
            w = 250 * factor
            wlo = max(0, m - w)
            whi = min(h.size - 1, m + w)
            h2 = _lbfgs_block(h, np.arange(wlo, whi + 1), 150, sub_end)
            r2 = R_of(h2)
            if r2 > r:
                h, r = h2, r2
        if time.process_time() < sub_end - 2.0:
            h3 = _lbfgs_log(h, 100, sub_end,
                            fg=(lambda hh: _fun_grad_pnorm(hh, 80.0)))
            r3 = R_of(h3)
            if r3 > r:
                h, r = h3, r3
        print("  scale x%d R=%.7f (cur=%.7f best=%.7f)" %
              (factor, r, curR, bestR))
        if r > curR + 1e-13:
            cur, curR = h.copy(), r
            if r > bestR + 1e-13:
                best, bestR = h.copy(), r
                _report("scale x%d keep" % factor, best, bestR)

    # Phase 3: full-array polish + p-norm rounds until deadline.
    full = np.arange(cur.size)
    round_idx = 0
    while time.process_time() < deadline - 1.5:
        round_idx += 1
        sub_deadline = min(deadline - 0.8, time.process_time() + 6.0)
        h = _lbfgs_block(cur, full, 120, sub_deadline)
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h.copy(), r
        if time.process_time() < sub_deadline - 1.0:
            h = _lbfgs_log(cur, 100, sub_deadline)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h.copy(), r
        if round_idx % 2 == 0 and time.process_time() < sub_deadline - 1.0:
            h = _lbfgs_log(cur, 80, sub_deadline,
                           fg=(lambda hh: _fun_grad_pnorm(hh, 80.0)))
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h.copy(), r
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

