    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _flank_window(h, side, lo_frac=0.55, hi_frac=0.995, pad_frac=0.10,
                  extra=128):
    """Cell window covering the rising (left) or falling (right) flank of f*f."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    m = int(np.argmax(Lf))
    lo_v = lo_frac * mx
    hi_v = hi_frac * mx
    if side == 'left':
        seg = Lf[:m + 1]
        idx = np.flatnonzero((seg >= lo_v) & (seg <= hi_v))
    else:
        seg = Lf[m:]
        idx = np.flatnonzero((seg >= lo_v) & (seg <= hi_v))
        idx = idx + m
    if idx.size == 0:
        return _peak_window(h, pad_frac=pad_frac, extra=extra)
    lo = max(0, int(idx.min()) - 1)
    hi = min(h.size - 1, int(idx.max()))
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    """Flank/peak alternating accept-only schedule."""
    modes = ['left', 'peak', 'right', 'peak']
    pads = [0.05, 0.08, 0.10, 0.12, 0.15]
    step = 0
    while time.process_time() < deadline - 0.5:
        mode = modes[step % len(modes)]
        pad = pads[(step // len(modes)) % len(pads)]
        if mode == 'peak':
            win = _peak_window(work, pad_frac=pad, extra=128)
        else:
            win = _flank_window(work, mode, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 350, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        gained = False
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%s%s%d" % (tag, mode[0], step)
            gained = True
            print("  step %d mode=%s pad=%.2f R=%.9f +" %
                  (step, mode, pad, bestR))
        if step % 3 == 2 and time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%s%s%d+all0" % (tag, mode[0], step)
                gained = True
                print("  step %d mode=%s pad=%.2f +all0 R=%.9f +" %
                      (step, mode, pad, bestR))
        if not gained:
            print("  step %d mode=%s pad=%.2f R=%.9f" %
                  (step, mode, pad, bestR))
        step += 1
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    work, best, bestR, origin = _run_cycle(
        start_best.copy(), best.copy(), bestR, deadline, 'base')

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 1e-12, None)
    Lp = Lc ** p
    Sp = Lp.sum()
    if Sp <= 0:
        return _fun_grad(h)
    wL = p * (Lc ** (p - 1.0)) / Sp
    gLf = -dq / num + wL
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Sp) / p
    return val, grad


def _lbfgs_pnorm(h0, p, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_pnorm(hh, p)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


# ---------------- New: knot-density equalisation via coordinate resampling ----------------
# The current best has a very spiky autoconvolution near its max. R is maximized
# when the f*f profile is as flat as possible near its peak, i.e. many near-max
# knots. A structural way to get that is to *redistribute step density* so that
# many more steps fall where f*f is near the max. We do this by splitting/merging
# steps: sample the current h as a piecewise-constant density on a new grid whose
# local step-width is proportional to (local f*f value)^(gamma) -- concentrating
# resolution near the peak -- then re-fit. This is a genuine change of shape
# (not a gradient step) and can jump to a different basin.

def _knots_interp(h, nnew):
    """Resample h (piecewise constant, n steps) onto nnew steps by mass-conserving
    interpolation with a density weighting that concentrates steps near the peak
    of the current autoconvolution."""
    n = h.size
    if nnew == n:
        return h.copy()
    # knots of f*f on the original grid: index 0..n
    Lf = _knots(h)
    # target step positions in original coordinate u in [0,1]
    # density proportional to (Lf at nearest knot)^gamma -> integrate
    xk = np.linspace(0.0, 1.0, n + 1)
    Lk = Lf  # length n+1
    mx = Lk.max()
    if mx <= 0:
        return h.copy()
    dens = (Lk / mx) ** 3.0 + 1e-3   # concentrate near peak
    # cumulative density at original knots
    cum = np.concatenate(([0.0], np.cumsum(0.5 * (dens[:-1] + dens[1:]) * np.diff(xk))))
    tot = cum[-1]
    if tot <= 0:
        return h.copy()
    cum /= tot
    # new boundaries: equally spaced in cumulative density
    tgt = np.linspace(0.0, 1.0, nnew + 1)
    xnew = np.interp(tgt, cum, xk)
    # cumulative mass of h at original boundaries
    m = np.concatenate(([0.0], np.cumsum(h)))
    # mass at new boundaries
    mnew = np.interp(xnew, xk, m)
    hnew = np.diff(mnew)
    hnew = np.clip(hnew, 0.0, None)
    return _rescale(hnew)


def _equalise_climb(best, bestR, deadline):
    """Try several resampling densities and grid sizes, polish each, keep best."""
    n0 = best.size
    trials = []
    for scale in (0.5, 1.0, 2.0):
        nnew = int(max(256, min(400000, n0 * scale)))
        trials.append(nnew)
    for nnew in trials:
        if time.process_time() >= deadline - 2.0:
            break
        ht = _knots_interp(best, nnew)
        ht = _lbfgs_all_pos(ht, 400, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        # then a softmax polish at moderate beta
        if time.process_time() < deadline - 1.0:
            ht2 = _lbfgs_all_pos(ht, 300, deadline - 0.8, beta=1e4)
            r2 = R_of(ht2)
            if r2 > r:
                ht, r = ht2, r2
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        print("equalise nnew=%d: R=%.9f (best %.9f)" % (nnew, r, bestR))
    return best, bestR


def _softmax_ladder(best, bestR, deadline):
    for beta in [1e4, 1e5, 1e6, 1e7, 1e8]:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(best, 300, deadline - 0.8, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        print("softmax beta=%.0e: R=%.9f" % (beta, bestR))
    return best, bestR


def _pnorm_climb(best, bestR, deadline):
    p_list = [2.0, 3.0, 4.0, 6.0, 8.0, 12.0, 16.0, 24.0, 32.0, 48.0]
    cur = best.copy()
    for p in p_list:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_pnorm(cur, p, 400, deadline - 0.8)
        ht2 = _lbfgs_all_pos(ht, 250, deadline - 0.8, beta=0.0)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
            cur = ht2.copy()
        else:
            cur = ht.copy()
        print("pnorm p=%.1f: R=%.9f (best %.9f)" % (p, r2, bestR))
    return best, bestR


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.15, 96, 1e8), (0.30, 192, 1e8),
              (0.50, 384, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- New: knot-density equalisation resampling (main new idea) ----
    if time.process_time() < deadline - 8.0:
        ht, rt = _equalise_climb(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+equalise'
        print("after equalise R=%.7f" % bestR)

    # ---- p-norm crest shaping ----
    if time.process_time() < deadline - 5.0:
        ht, rt = _pnorm_climb(best, bestR, deadline - 5.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+pnorm'

    # ---- Softmax ladder ----
    if time.process_time() < deadline - 3.0:
        ht, rt = _softmax_ladder(best, bestR, deadline - 3.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            origin = origin + '+softmax'

    # ---- Local peak-window cycle to squeeze remaining gains ----
    while time.process_time() < deadline - 1.5:
        ht, rt = run_cycle(best, bestR, deadline - 1.0)
        if rt > bestR + 1e-14:
            best, bestR = ht, rt
            origin = origin + '+cycle'
        else:
            break

    best = _rescale(best)
    bestR = R_of(best)

    print("final R=%.7f origin=%s (N=%d)" % (bestR, origin, best.size))

    if start_best is not None and bestR <= start_bestR + 1e-13:
        if bestR < start_bestR - 1e-13:
            return {"best": start_best, "alternative": best}
        return best
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend(h, K, rho):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * (rho ** k)
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * (rho ** k)
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _short_cycle(work, best, bestR, deadline, origin, tag=""):
    """Shortened cycle: pads [0.20,0.12,0.08], block beta=1e7 + one global all0."""
    pads = [0.20, 0.12, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
    if time.process_time() < deadline - 0.6:
        ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            work, best, bestR = ht2, ht2.copy(), r2
            origin = "%sall0" % tag
    return work, best, bestR, origin


def _zero_fraction(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0:
        return 0.0
    return float(np.mean(h == 0.0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d) zero_frac=%.4f" %
          (bestR, best.size, _zero_fraction(best)))

    # Baseline cycle on the unextended start.
    work0, best0, bestR0, origin0 = _run_cycle(
        start_best.copy(), best.copy(), bestR, deadline, 'base')
    if bestR0 > bestR + 1e-14:
        best, bestR, origin = best0, bestR0, origin0
    print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # --- Revival phase: inject mass into zero cells, guided by gradient / deficit ---
    alt_best = None
    alt_bestR = -1.0
    if time.process_time() < deadline - 2.0:
        h_cur = best.copy()
        # gradient in linear space (valid at h_i = 0)
        _, g = _fun_grad(h_cur)
        Lf = _knots(h_cur)
        mx_h = h_cur.max()
        if mx_h > 0:
            idx = np.flatnonzero(h_cur > 1e-9 * mx_h)
            if idx.size > 0:
                i0 = int(idx.min()); i1 = int(idx.max())
            else:
                i0, i1 = 0, h_cur.size - 1
        else:
            i0, i1 = 0, h_cur.size - 1
        # zero cells inside [i0, i1]
        Z = np.arange(i0, i1 + 1)
        Z = Z[h_cur[Z] == 0.0]
        if Z.size > 0:
            # rank by gradient (largest positive gain first)
            gZ = g[Z]
            order_grad = Z[np.argsort(-gZ)]
            # rank by deficit: lowest f*f knot value near index i -> Lf[i]
            # Lf has length n+1; use Lf[i] for i in Z
            LZ = Lf[Z]
            order_def = Z[np.argsort(LZ)]
            eps = 1e-3 * h_cur.mean()
            modes = [('grad', order_grad), ('deficit', order_def)]
            ms = [128, 512, 2048]
            for mode, order in modes:
                for m in ms:
                    if time.process_time() >= deadline - 1.0:
                        break
                    mm = min(m, order.size)
                    if mm == 0:
                        continue
                    h_rev = h_cur.copy()
                    h_rev[order[:mm]] = eps
                    h_rev = _rescale(h_rev)
                    r_rev = R_of(h_rev)
                    w, b, br, org = _short_cycle(
                        h_rev, h_rev.copy(), r_rev, deadline,
                        'rev_%s_%d' % (mode, m),
                        tag='r%s%d_' % (mode, m))
                    if br > bestR + 1e-14:
                        best, bestR, origin = b, br, org
                    if br > alt_bestR and br < bestR - 1e-14:
                        alt_best, alt_bestR = b, br
                    print("revival mode=%s m=%d: R_rev=%.9f R_polish=%.9f "
                          "zero_frac=%.4f (best %.9f)" %
                          (mode, m, r_rev, br, _zero_fraction(b),
                           bestR))

    # Edge-extension trials (kept from base).
    trials = [(256, 0.90), (1024, 0.97), (4096, 0.995)]
    for (K, rho) in trials:
        if time.process_time() >= deadline - 1.0:
            break
        ext = _edge_extend(best, K, rho)
        r_ext = R_of(ext)
        mx = ext.max()
        idx = np.flatnonzero(ext > 1e-9 * mx)
        if idx.size > 0:
            i0 = int(idx.min()); i1 = int(idx.max())
        else:
            i0, i1 = 0, ext.size - 1
        print("trial K=%d rho=%.3f: start R=%.9f support=[%d,%d]" %
              (K, rho, r_ext, i0, i1))
        if r_ext < bestR - 1e-9:
            if r_ext > alt_bestR:
                alt_best, alt_bestR = ext, r_ext
            continue
        w, b, br, org = _run_cycle(ext, ext.copy(), r_ext, deadline,
                                   'ext%d_%g' % (K, rho),
                                   tag='e%d_%g_' % (K, rho))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
        if br > alt_bestR and br < bestR - 1e-14:
            alt_best, alt_bestR = b, br
        print("trial K=%d rho=%.3f: R=%.9f (best %.9f)" %
              (K, rho, br, bestR))

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.4f)" %
          (bestR, origin, start_bestR, best.size, _zero_fraction(best)))

    if bestR > start_bestR + 1e-12:
        if alt_best is not None and alt_bestR > start_bestR + 1e-12:
            return {"best": best, "alternative": alt_best}
        return best
    if alt_best is not None:
        return {"best": best, "alternative": alt_best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend_pow(h, K, p):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        w = (1.0 + k) ** (-p)
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * w
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * w
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _random_perturb(h, rng, amp):
    """Multiplicative log-normal noise on active cells, zero cells stay zero."""
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: random multi-start perturbations of the best, then polish.
    # This is the key new idea: escape the local optimum via stochastic restarts.
    rng = np.random.default_rng(12345)
    amps = [0.01, 0.03, 0.05, 0.08, 0.12, 0.02, 0.04, 0.06, 0.10, 0.15]

    for trial, amp in enumerate(amps):
        if time.process_time() >= deadline - 1.0:
            break
        seed = _random_perturb(best, rng, amp)
        r_seed = R_of(seed)
        w, b, br, org = _run_cycle(seed, seed.copy(), r_seed, deadline,
                                   'rand%d' % trial)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("rand%d amp=%.3f: R=%.9f NEW BEST" % (trial, amp, bestR))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("rand%d amp=%.3f: R=%.9f (best %.9f)" % (trial, amp, br, bestR))

    # Phase C: if time remains, do a final power-law edge extension sweep
    if time.process_time() < deadline - 2.0:
        for (K, p) in [(2048, 3.0), (2048, 2.0)]:
            if time.process_time() >= deadline - 1.0:
                break
            ext = _edge_extend_pow(best, K, p)
            r_ext = R_of(ext)
            w, b, br, org = _run_cycle(ext, ext.copy(), r_ext, deadline,
                                       'pow%d_%g' % (K, p))
            if br > bestR + 1e-14:
                best, bestR, origin = b, br, org
            elif br > alt_bestR:
                alt_best, alt_bestR = b, br

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _flank_window(h, side, lo_frac=0.55, hi_frac=0.995, pad_frac=0.10, extra=128):
    """Cell window covering the rising (left) or falling (right) flank of f*f."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    m = int(np.argmax(Lf))
    lo_v = lo_frac * mx
    hi_v = hi_frac * mx
    if side == 'left':
        seg = Lf[:m + 1]
        idx = np.flatnonzero((seg >= lo_v) & (seg <= hi_v))
    else:
        seg = Lf[m:]
        idx = np.flatnonzero((seg >= lo_v) & (seg <= hi_v))
        idx = idx + m
    if idx.size == 0:
        return _peak_window(h, pad_frac=pad_frac, extra=extra)
    # idx are knot indices; heights live at index-1..index
    lo = max(0, int(idx.min()) - 1)
    hi = min(h.size - 1, int(idx.max()))
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _resample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    old_x = np.linspace(0.0, 1.0, n, endpoint=False)
    new_n = n * factor
    new_x = np.linspace(0.0, 1.0, new_n, endpoint=False)
    return np.interp(new_x, old_x, h, left=0.0, right=0.0) * factor


def _sweep_windows(cur, curR, deadline, win, stride, iters):
    n = cur.size
    if n <= win:
        centers = [n // 2]
    else:
        centers = list(range(win // 2, n - win // 2 + 1, stride))
        if not centers or centers[-1] < n - win // 2:
            centers.append(n - win // 2)
    accepted = 0
    for c in centers:
        if time.process_time() >= deadline:
            break
        lo = max(0, c - win // 2)
        hi = min(n, c + win // 2)
        ht = _lbfgs_block(cur, np.arange(lo, hi), iters, deadline)
        r = R_of(ht)
        if r > curR + 1e-13:
            cur = ht
            curR = r
            accepted += 1
    return cur, curR, accepted


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # --- New idea: shrink the array by decimation first, so L-BFGS on the
    # whole array is cheap enough to actually converge.  The optimum is a
    # smooth-ish shape; a coarser representation captures it well and then we
    # refine back up.  This complements the (already saturated) fine polish
    # in the inherited program.
    n = best.size
    # try a decimation factor that brings N into a tractable range
    for target in (2048, 4096, 8192):
        if time.process_time() >= deadline - 20.0:
            break
        if n <= target:
            continue
        factor = max(2, n // target)
        # block-average decimation
        n2 = (n // factor) * factor
        hd = best[:n2].reshape(-1, factor).mean(axis=1)
        hd = _rescale(hd)
        rd = R_of(hd)
        # full L-BFGS on the coarse array (now cheap)
        hc = _lbfgs_all_pos(hd, 400, min(deadline - 15.0,
                            time.process_time() + 6.0))
        rc = R_of(hc)
        print("coarse target=%d factor=%d: R=%.7f -> %.7f" %
              (target, factor, rd, rc))
        if rc > bestR + 1e-13:
            # upscale back to original size
            xc = np.linspace(0.0, 1.0, hc.size, endpoint=False)
            xn = np.linspace(0.0, 1.0, n, endpoint=False)
            hu = np.interp(xn, xc, hc, left=0.0, right=0.0)
            hu = _rescale(hu)
            ru = R_of(hu)
            # polish the upscaled version briefly on the full grid
            hp = _lbfgs_all_pos(hu, 60, min(deadline - 10.0,
                               time.process_time() + 4.0))
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                origin = origin + '+coarse%d' % target
                print("upscaled R=%.7f" % bestR)

    # --- Phase: flank windows (both sides of the peak) targeted polish
    for side in ('left', 'right'):
        if time.process_time() >= deadline - 8.0:
            break
        win = _flank_window(best, side, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 200, deadline - 6.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
            origin = origin + '+flank_' + side
            print("flank %s R=%.7f" % (side, bestR))

    # --- Peak window polish at multiple widths
    for frac in (0.10, 0.20, 0.35):
        if time.process_time() >= deadline - 3.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=128)
        ht = _lbfgs_block(best, win, 200, deadline - 2.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
            origin = origin + '+tight'
            print("peak frac=%.2f R=%.7f" % (frac, bestR))

    # --- Final full polish
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
            origin = origin + '+final'

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _support_bounds(h):
    mx = h.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(h > 1e-9 * mx)
    if idx.size == 0:
        return 0, h.size - 1
    return int(idx.min()), int(idx.max())


def _edge_extend(h, K, rho):
    """Geometric edge extension: append K cells at each end with heights
    decaying geometrically (ratio rho) from the boundary value."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.size == 0 or h.sum() <= 0:
        return h
    K = int(K)
    if K <= 0:
        return h
    lo_val = h[0] if h[0] > 0 else h.max() * 1e-3
    hi_val = h[-1] if h[-1] > 0 else h.max() * 1e-3
    left = lo_val * (rho ** np.arange(K, 0, -1))
    right = hi_val * (rho ** np.arange(1, K + 1))
    out = np.concatenate([left, h, right])
    return _rescale(out)


def _edge_extend_both(h, K, rho):
    return _edge_extend(h, K, rho)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    f1 = 100.0 * np.mean(Lf >= 0.99 * mx)
    f5 = 100.0 * np.mean(Lf >= 0.95 * mx)
    arg = float(np.argmax(Lf)) / max(1, Lf.size - 1)
    return f1, f5, arg


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    zf = 100.0 * np.mean(best <= 1e-12 * best.max()) if best.max() > 0 else 0.0
    f1, f5, arg = _stats(best)
    print("base R=%.9f (N=%d) zeros=%.1f%% f1=%.2f%% f5=%.2f%% argmax=%.3f" %
          (bestR, best.size, zf, f1, f5, arg))

    # (2) run _run_cycle on the unextended start
    if time.process_time() < deadline - 0.7:
        w, b, br, org = _run_cycle(best.copy(), best.copy(), bestR,
                                   deadline, 'base', tag='b_')
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            f1, f5, arg = _stats(best)
            print("cycle-base R=%.9f origin=%s f1=%.2f%% f5=%.2f%% argmax=%.3f" %
                  (bestR, origin, f1, f5, arg))

    # (3)-(5) edge-extension loop, feeding best forward
    ext_specs = [(256, 0.90), (1024, 0.97), (2048, 0.99),
                 (4096, 0.995), (8192, 0.999)]
    ext_gate = 0.9412930
    round_no = 0
    while time.process_time() < deadline - 0.7:
        round_no += 1
        improved_round = False
        for (K, rho) in ext_specs:
            if time.process_time() >= deadline - 0.7:
                break
            ext = _edge_extend(best, K, rho)
            rext = R_of(ext)
            if rext < ext_gate:
                continue
            w, b, br, org = _run_cycle(ext, ext, rext, deadline,
                                       'ext%d_%g' % (K, rho),
                                       tag='e%d_%g_' % (K, rho))
            if br > bestR + 1e-14:
                best, bestR, origin = b, br, org
                improved_round = True
                f1, f5, arg = _stats(best)
                print("ext K=%d rho=%g R=%.9f origin=%s f1=%.2f%% f5=%.2f%% argmax=%.3f" %
                      (K, rho, bestR, origin, f1, f5, arg))
        # second full cycle on the winner
        if time.process_time() < deadline - 0.7:
            w, b, br, org = _run_cycle(best.copy(), best.copy(), bestR,
                                       deadline, 'second', tag='s2_')
            if br > bestR + 1e-14:
                best, bestR, origin = b, br, org
                improved_round = True
                f1, f5, arg = _stats(best)
                print("cycle2 R=%.9f origin=%s f1=%.2f%% f5=%.2f%% argmax=%.3f" %
                      (bestR, origin, f1, f5, arg))
        if time.process_time() < deadline - 0.7:
            ht = _lbfgs_all_pos(best, 400, deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht, r, 'final_all0'
                improved_round = True
                f1, f5, arg = _stats(best)
                print("final_all0 R=%.9f f1=%.2f%% f5=%.2f%% argmax=%.3f" %
                      (bestR, f1, f5, arg))
        if not improved_round:
            # no gain this round: still try a small extension variant next round
            if time.process_time() >= deadline - 0.7:
                break

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _support_bounds(h):
    mx = h.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(h > 1e-9 * mx)
    if idx.size == 0:
        return 0, h.size - 1
    return int(idx.min()), int(idx.max())


def _repair(h, touched, deadline, beta=1e7):
    n = h.size
    lo = max(0, touched - 64)
    hi = min(n - 1, touched + 64)
    win = np.arange(lo, hi + 1)
    r0 = R_of(h)
    ht = _lbfgs_block(h, win, 60, deadline - 0.3, beta=beta)
    r1 = R_of(ht)
    if r1 > r0 + 1e-14:
        ht2 = _lbfgs_all_pos(ht, 80, deadline - 0.3, beta=1e6)
        r2 = R_of(ht2)
        if r2 > r1:
            return ht2, r2
        return ht, r1
    return h, r0


def _gen_candidates(h, kind, i0, i1):
    """Yield (candidate_h, touched_index, label) for a given candidate kind."""
    n = h.size
    mx = h.max()
    if mx <= 0:
        return
    mean = h.mean()
    pos = np.flatnonzero(h > 1e-9 * mx)
    if pos.size == 0:
        return
    top = pos[np.argsort(-h[pos])[:16]]

    if kind == "split":
        for i in top:
            if i + 1 < n:
                for f in (0.5, 0.25):
                    hc = h.copy()
                    v = h[i]
                    hc[i] = v * f
                    hc[i + 1] = hc[i + 1] + v * (1.0 - f)
                    yield _rescale(hc), int(i), "split"
    elif kind == "merge":
        for i in top:
            if i + 1 < n and h[i + 1] > 1e-9 * mx:
                hc = h.copy()
                hc[i] = h[i] + h[i + 1]
                hc[i + 1] = 0.0
                yield _rescale(hc), int(i), "merge"
    elif kind == "death":
        small = pos[np.argsort(h[pos])[:16]]
        for i in small:
            hc = h.copy()
            hc[i] = 0.0
            yield _rescale(hc), int(i), "death"
    elif kind == "birth":
        try:
            _, g = _fun_grad(h)
        except Exception:
            return
        zero_mask = h <= 1e-9 * mx
        lo = max(0, i0)
        hi = min(n - 1, i1)
        idx = np.arange(lo, hi + 1)
        idx = idx[zero_mask[idx]]
        if idx.size == 0:
            return
        gz = g[idx]
        order = np.argsort(-gz)[:16]
        for k in order:
            j = int(idx[k])
            hc = h.copy()
            hc[j] = 1e-3 * mean
            yield _rescale(hc), j, "birth"


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    hop_deadline = deadline - 2.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    work = best.copy()
    workR = bestR
    kinds = ["split", "merge", "death", "birth"]
    kpos = 0
    accepted = 0
    evaluated = 0
    accepted_types = set()

    while time.process_time() < hop_deadline:
        i0, i1 = _support_bounds(work)
        kind = kinds[kpos % len(kinds)]
        kpos += 1
        improved = False
        for cand, touched, label in _gen_candidates(work, kind, i0, i1):
            if time.process_time() >= hop_deadline:
                break
            evaluated += 1
            hc, rc = _repair(cand, touched, deadline)
            if rc > workR + 1e-12:
                delta = rc - workR
                work, workR = hc, rc
                accepted += 1
                accepted_types.add(label)
                improved = True
                zf = 100.0 * np.mean(work <= 1e-12 * work.max())
                print("hop %s@%d: dR=%.2e R=%.9f zeros=%.1f%%" %
                      (label, touched, delta, workR, zf))
                if workR > bestR + 1e-14:
                    best, bestR, origin = work.copy(), workR, "hop_" + label
                break
        if not improved:
            # small perturbation to escape: try next kind
            pass

    print("hops: accepted=%d evaluated=%d R=%.9f (start %.9f) types=%s" %
          (accepted, evaluated, bestR, start_bestR, sorted(accepted_types)))

    if time.process_time() < deadline - 0.5:
        w, b, br, org = _run_cycle(best.copy(), best.copy(), bestR,
                                   deadline, 'final', tag='f_')
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": best, "alternative": work}

