            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _refine_split(h, jitter):
    """Exact 2x refinement with alternating jitter to break staircase symmetry."""
    n = h.size
    out = np.zeros(2 * n)
    sign = np.where(np.arange(n) % 2 == 0, 1.0, -1.0)
    fac = 1.0 + jitter * sign
    out[0::2] = h * fac
    out[1::2] = h * (2.0 - fac)
    return out


def _fine_schedule(h2, deadline, tag=""):
    """Fine-grid schedule: 2 passes of beta ladder, 6 pads, edge ext, pad pass."""
    work = h2.copy()
    best = h2.copy()
    bestR = R_of(h2)
    origin = tag + "start"
    r_start = bestR

    # two passes of beta ladder
    for _pass in range(2):
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "%sbeta%g_p%d" % (tag, beta, _pass)
    r_ladder = bestR

    # 6 peak-window pads alternating global
    pads = [0.20, 0.12, 0.10, 0.08, 0.15, 0.06]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 200, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    r_pad = bestR

    # edge extension at fine grid + one more pad pass
    if time.process_time() < deadline - 1.0:
        ext = _edge_extend(work, 2048, 0.995)
        r_ext = R_of(ext)
        if r_ext > bestR + 1e-14:
            work, best, bestR = ext, ext.copy(), r_ext
            origin = tag + "ext"
        for it, pad in enumerate([0.10, 0.08, 0.06]):
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(work, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 200, deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "%sextpk%d" % (tag, it)
    return work, best, bestR, origin, r_start, r_ladder, r_pad


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Baseline cycle on start (keep p1243's good behaviour).
    work0, best0, bestR0, origin0 = _run_cycle(
        start_best.copy(), best.copy(), bestR, deadline, 'base')
    if bestR0 > bestR + 1e-14:
        best, bestR, origin = best0, bestR0, origin0
    print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Experiment: exact 2x refinement with alternating jitter.
    jitters = [0.0, 0.005, 0.02]
    results = {}  # jitter -> (best, bestR, origin)
    for jitter in jitters:
        if time.process_time() >= deadline - 1.0:
            break
        h2 = _refine_split(start_best, jitter)
        h2 = _rescale(h2)
        tag = "j%g_" % jitter
        w, b, br, org, rs, rl, rp = _fine_schedule(h2, deadline, tag=tag)
        results[jitter] = (b, br, org)
        print("jitter=%.3f: start R=%.9f ladder R=%.9f pad R=%.9f final R=%.9f N=%d"
              % (jitter, rs, rl, rp, br, b.size))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org

    # Keep the best branch's pad passes going until deadline.
    if results:
        best_j = max(results.keys(), key=lambda k: results[k][1])
        work = results[best_j][0].copy()
        curR = results[best_j][1]
        pads = [0.10, 0.08, 0.06, 0.12, 0.15, 0.20]
        it = 0
        while time.process_time() < deadline - 1.0:
            pad = pads[it % len(pads)]
            it += 1
            win = _peak_window(work, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 200, deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > curR + 1e-14:
                work, curR = ht, r
                if curR > bestR + 1e-14:
                    best, bestR, origin = ht.copy(), curR, "final_pad%d" % it
            if time.process_time() < deadline - 0.6:
                ht2 = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=0.0)
                r2 = R_of(ht2)
                if r2 > curR + 1e-14:
                    work, curR = ht2, r2
                    if curR > bestR + 1e-14:
                        best, bestR, origin = ht2.copy(), curR, "final_all0_%d" % it

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    # Return best; if experiment branch is genuinely different and doesn't beat start, offer as alternative.
    if bestR > start_bestR + 1e-12:
        return best
    alt = None
    if results:
        best_j = max(results.keys(), key=lambda k: results[k][1])
        alt = results[best_j][0]
    if alt is not None:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _grad_only(h):
    """Return dR/dh (gradient of R itself, not of -log R)."""
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    dnum = _backprop(dq, h)
    dm = _backprop(np.eye(1, Lf.size, m).ravel() * 1.0, h)  # won't be used; do directly below
    # direct peak-derivative (piecewise linear peak): d/dh_j of max_k L_k = 2 h[m-1-j] when valid
    dm = np.zeros(h.size)
    k = m - 1
    if 0 <= k < 2 * h.size - 1:
        for j in range(max(0, k - h.size + 1), min(h.size, k + 1)):
            dm[j] = 2.0 * h[k - j]
    ds = np.ones(h.size)
    den = s * s * Lm
    dR = dnum / den - num * (2 * s * Lm * ds + s * s * dm) / (den * den)
    return dR


def _smooth_polish(h, deadline, iters=400):
    """Maximize R directly with projected gradient ascent + line search.
    Naturally keeps h >= 0, no log-transform, avoids vanishing gradients on zeros."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    R = R_of(h)
    step = 1e-3 * h.max() / (np.abs(_grad_only(h)).max() + 1e-30)
    for it in range(iters):
        if time.process_time() > deadline - 0.3:
            break
        g = _grad_only(h)
        gn = np.max(np.abs(g))
        if gn <= 0:
            break
        step = min(step, 1e-2 * h.max() / gn)
        h2 = np.clip(h + step * g, 0, None)
        R2 = R_of(h2)
        if R2 > R:
            h = h2
            R = R2
            step *= 1.5
        else:
            step *= 0.5
            if step * gn < 1e-12 * h.max():
                break
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best_h = None
    best_R = -1.0
    start_h = None
    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            start_h = s.copy()
            start_R = R_of(s)
            best_h = s.copy()
            best_R = start_R

    if start_h is None:
        # No start: build a compact bump seed and escalate.
        N = 512
        x = (np.arange(N) + 0.5) / N
        seed = np.exp(-((x - 0.5) ** 2) / (2 * 0.15 ** 2))
        h = _rescale(seed)
        for N2 in [1024, 2048, 4096, 8192, 16384, 32768]:
            idx = (np.arange(N2) * N // N2).astype(int)
            h = h[idx]
            N = N2
            if time.process_time() > deadline - 1.0:
                break
            h = _smooth_polish(h, deadline, 200)
        if R_of(h) > best_R:
            best_R = R_of(h)
            best_h = h
        return best_h

    # We have a start. Escalate resolution and polish.
    cur = start_h.copy()
    curR = start_R
    Ncur = len(cur)

    # multi-resolution escalation, trying both upsampling and same-resolution polish
    target_levels = [Ncur, 2 * Ncur, 4 * Ncur]
    target_levels = [n for n in target_levels if n <= 1_000_000]

    for N in target_levels:
        if time.process_time() > deadline - 1.0:
            break
        if N != len(cur):
            # upsample by repeating (block) then optionally linear interp
            idx = (np.arange(N) * len(cur) // N).astype(int)
            h = cur[idx]
            # smooth slightly to avoid block artifacts
            if N > 8:
                ker = np.ones(3) / 3.0
                h = np.convolve(h, ker, mode='same')
        else:
            h = cur.copy()
        # smooth projective polish (handles zeros naturally)
        h = _smooth_polish(h, deadline, 300)
        # then L-BFGS with smoothed-max to sharpen the peak
        for beta in [1e4, 1e5, 1e6]:
            if time.process_time() > deadline - 0.5:
                break
            h2 = _lbfgs(h, 200, deadline, beta=beta)
            if R_of(h2) >= R_of(h) - 1e-9:
                h = h2
        R = R_of(h)
        if R > curR:
            cur = h
            curR = R
        else:
            # keep best but try from previous
            if R_of(cur) < R:
                cur = h
                curR = R

    if curR > best_R:
        best_R = curR
        best_h = cur

    print("R=%.6f N=%d" % (best_R, len(best_h)))

    if best_R > start_R:
        return {"best": best_h, "alternative": start_h}
    else:
        return {"best": start_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _flank_window(h, side, lo_frac=0.55, hi_frac=0.995, pad_frac=0.10,
                  extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    m = int(np.argmax(Lf))
    lo_v = lo_frac * mx
    hi_v = hi_frac * mx
    if side == 'left':
        seg = Lf[:m + 1]
        idx = np.flatnonzero((seg >= lo_v) & (seg <= hi_v))
    else:
        seg = Lf[m:]
        idx = np.flatnonzero((seg >= lo_v) & (seg <= hi_v))
        idx = idx + m
    if idx.size == 0:
        return _peak_window(h, pad_frac=pad_frac, extra=extra)
    lo = max(0, int(idx.min()) - 1)
    hi = min(h.size - 1, int(idx.max()))
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    modes = ['left', 'peak', 'right', 'peak']
    pads = [0.05, 0.08, 0.10, 0.12, 0.15]
    step = 0
    while time.process_time() < deadline - 0.5:
        mode = modes[step % len(modes)]
        pad = pads[(step // len(modes)) % len(pads)]
        if mode == 'peak':
            win = _peak_window(work, pad_frac=pad, extra=128)
        else:
            win = _flank_window(work, mode, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 350, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        gained = False
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%s%s%d" % (tag, mode[0], step)
            gained = True
            print("  step %d mode=%s pad=%.2f R=%.9f +" %
                  (step, mode, pad, bestR))
        if step % 3 == 2 and time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%s%s%d+all0" % (tag, mode[0], step)
                gained = True
                print("  step %d mode=%s pad=%.2f +all0 R=%.9f +" %
                      (step, mode, pad, bestR))
        if not gained:
            print("  step %d mode=%s pad=%.2f R=%.9f" %
                  (step, mode, pad, bestR))
        step += 1
    return work, best, bestR, origin


def _edge_extend_pow(h, K, p):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        w = (1.0 + k) ** (-p)
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * w
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * w
    return _rescale(h)


def _erode_grow(h, factor):
    """Insert a finer grid by linear interpolation (grow), or thin (factor<1)."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    m = max(1, int(round(n * factor)))
    if m == n:
        return h.copy()
    xi = np.linspace(0.0, n - 1.0, m)
    xp = np.arange(n, dtype=float)
    return _rescale(np.interp(xi, xp, h))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = -1.0
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase A: refine on the given grid (same schedule as before, shorter).
    phase_a_deadline = min(deadline - 1.0, t0 + budget_seconds * 0.55)
    work, best, bestR, origin = _run_cycle(
        start_best.copy(), best.copy(), bestR, phase_a_deadline, 'base')

    # Phase B: try a finer grid via linear interpolation, then refine.
    if time.process_time() < deadline - 2.0:
        for factor in (2.0,):
            if time.process_time() >= deadline - 2.0:
                break
            hg = _erode_grow(best, factor)
            if hg.size > 1000000:
                continue
            rg = R_of(hg)
            print("  grow x%.1f -> N=%d R=%.9f" % (factor, hg.size, rg))
            if rg > bestR + 1e-14:
                work, best, bestR, origin = _run_cycle(
                    hg.copy(), hg.copy(), rg, deadline, 'grow')
            else:
                # still try a short refine, keep if it improves
                work, best2, bestR2, origin2 = _run_cycle(
                    hg.copy(), best.copy(), bestR, deadline, 'growtry')
                if bestR2 > bestR + 1e-14:
                    best, bestR, origin = best2, bestR2, origin2

    # Phase C: edge extension to fill in low tails (may improve R).
    if time.process_time() < deadline - 1.0:
        K = max(4, best.size // 64)
        he = _edge_extend_pow(best, K, 2.0)
        re_ = R_of(he)
        if re_ > bestR + 1e-14:
            print("  edge-extend R=%.9f" % re_)
            work, best2, bestR2, origin2 = _run_cycle(
                he.copy(), he.copy(), re_, deadline, 'edge')
            if bestR2 > bestR:
                best, bestR = best2, bestR2
        else:
            alt = he.copy(); altR = re_

    # Final polish (full free, no beta).
    if time.process_time() < deadline - 0.8:
        hp = _lbfgs_all_pos(best, 400, deadline - 0.3, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("  final polish R=%.9f" % bestR)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if alt is not None and altR > -1:
        return {"best": best, "alternative": alt}
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend_pow(h, K, p):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        w = (1.0 + k) ** (-p)
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * w
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * w
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _densify(h, c):
    dense = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    act = dense > 0
    if not np.any(act):
        return dense
    lvl = c * dense[act].mean()
    dense[~act] = lvl
    return _rescale(dense)


def _densify_ladder(dense, deadline, tag=""):
    """Beta ladder at full N, then peak-window pads, then a beta=0 pass."""
    work = dense.copy()
    best = dense.copy()
    bestR = R_of(dense)
    origin = tag + "seed"
    for beta in [1e4, 1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(work, 400, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.15, 0.08]):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 1.2:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 1.0, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase D: densification experiment — fill all zeros with small uniform
    # level (fraction of active mean), then beta ladder at full N.
    for c in [0.002, 0.02]:
        if time.process_time() >= deadline - 2.0:
            break
        dense = _densify(start_best, c)
        r0 = R_of(dense)
        nz0 = int(np.sum(dense == 0))
        if time.process_time() >= deadline - 1.5:
            break
        w, b, br, org = _densify_ladder(dense, deadline - 0.5,
                                        tag='dens%g' % c)
        nz = int(np.sum(b == 0))
        print("dens c=%g: seed R=%.9f zeros=%d -> R=%.9f zeros=%d origin=%s"
              % (c, r0, nz0, br, nz, org))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("dens c=%g NEW BEST R=%.9f" % (c, bestR))
        elif br > alt_bestR and br > start_bestR + 1e-14:
            alt_best, alt_bestR = b, br

    # Phase B: random multi-start perturbations of the best
    rng = np.random.default_rng(12345)
    amps = [0.01, 0.03, 0.05, 0.08, 0.12, 0.02, 0.04, 0.06, 0.10, 0.15]

    for trial, amp in enumerate(amps):
        if time.process_time() >= deadline - 1.0:
            break
        seed = _random_perturb(best, rng, amp)
        r_seed = R_of(seed)
        w, b, br, org = _run_cycle(seed, seed.copy(), r_seed, deadline,
                                   'rand%d' % trial)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("rand%d amp=%.3f: R=%.9f NEW BEST" % (trial, amp, bestR))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("rand%d amp=%.3f: R=%.9f (best %.9f)" % (trial, amp, br, bestR))

    # Phase C: power-law edge extension sweep if time remains
    if time.process_time() < deadline - 2.0:
        for (K, p) in [(2048, 3.0), (2048, 2.0)]:
            if time.process_time() >= deadline - 1.0:
                break
            ext = _edge_extend_pow(best, K, p)
            r_ext = R_of(ext)
            w, b, br, org = _run_cycle(ext, ext.copy(), r_ext, deadline,
                                       'pow%d_%g' % (K, p))
            if br > bestR + 1e-14:
                best, bestR, origin = b, br, org
            elif br > alt_bestR:
                alt_best, alt_bestR = b, br

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend_pow(h, K, p):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        w = (1.0 + k) ** (-p)
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * w
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * w
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _random_perturb(h, rng, amp):
    """Multiplicative log-normal noise on active cells, zero cells stay zero."""
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _cheap_cycle(seed, deadline, tag=""):
    """Cheaper perturb->polish cycle: 2 betas, 3 pads, one global beta=0."""
    work = seed.copy()
    best = seed.copy()
    bestR = R_of(seed)
    origin = tag + "seed"
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.15, 0.08]):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 250, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
    if time.process_time() < deadline - 0.6:
        ht2 = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=0.0)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            work, best, bestR = ht2, ht2.copy(), r2
            origin = "%sall0" % tag
    return best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline full cycle on start (as before).
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: cheap perturb->polish->accept loop, log-uniform amp, capped trials.
    rng = np.random.default_rng(12345)
    lo = np.log(0.003)
    hi = np.log(0.05)
    n_trials = 0
    while time.process_time() < deadline - 6.0 and n_trials < 8:
        amp = float(np.exp(rng.uniform(lo, hi)))
        seed = _random_perturb(best, rng, amp)
        r_seed = R_of(seed)
        b, br, org = _cheap_cycle(seed, deadline, tag='t%d' % n_trials)
        improved = br > bestR + 1e-14
        if improved:
            best, bestR, origin = b, br, org
        if br > alt_bestR and not improved:
            alt_best, alt_bestR = b, br
        print("trial%d amp=%.4f seedR=%.9f postR=%.9f %s (best %.9f)" %
              (n_trials, amp, r_seed, br, "NEW BEST" if improved else "", bestR))
        n_trials += 1

    # Phase C: if time remains, a power-law edge extension sweep.
    if time.process_time() < deadline - 2.0:
        for (K, p) in [(2048, 3.0), (2048, 2.0)]:
            if time.process_time() >= deadline - 1.0:
                break
            ext = _edge_extend_pow(best, K, p)
            r_ext = R_of(ext)
            w, b, br, org = _run_cycle(ext, ext.copy(), r_ext, deadline,
                                       'pow%d_%g' % (K, p))
            if br > bestR + 1e-14:
                best, bestR, origin = b, br, org
            elif br > alt_bestR:
                alt_best, alt_bestR = b, br

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if (alt_best is not None and alt_best.size == best.size
            and alt_bestR < bestR and bestR - alt_bestR <= 1e-9):
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend(h, K, rho):
    """Fill only zero cells beyond outermost active index with h_edge*rho**k."""
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        w = rho ** k
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * w
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * w
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.12]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _active_range(h):
    thr = 1e-9 * h.max()
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return (0, 0)
    return (int(idx.min()), int(idx.max()))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: edge-extension + optional noise trials
    rng = np.random.default_rng(12345)
    trials = [(256, 0.97, 0.0), (256, 0.97, 0.01),
              (1024, 0.99, 0.0), (1024, 0.99, 0.01)]

    for (K, rho, amp) in trials:
        if time.process_time() >= deadline - 8.0:
            print("skip K=%d rho=%.3f amp=%.3f (no time)" % (K, rho, amp))
            break
        r_pre_best = bestR
        ext = _edge_extend(best, K, rho)
        r_ext = R_of(ext)
        if amp > 0:
            ext = _random_perturb(ext, rng, amp)
            r_ext = R_of(ext)
        lo, hi = _active_range(ext)
        if r_ext < r_pre_best - 1e-9:
            print("K=%d rho=%.3f amp=%.3f: pre R=%.9f < best-1e-9, skip polish (range %d..%d)"
                  % (K, rho, amp, r_ext, lo, hi))
            continue
        w, b, br, org = _run_cycle(ext, ext.copy(), r_ext, deadline,
                                   'ext%d_%g_%g' % (K, rho, amp))
        lo2, hi2 = _active_range(b)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("K=%d rho=%.3f amp=%.3f: pre R=%.9f post R=%.9f NEW BEST (range %d..%d -> %d..%d)"
                  % (K, rho, amp, r_ext, br, lo, hi, lo2, hi2))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("K=%d rho=%.3f amp=%.3f: pre R=%.9f post R=%.9f (best %.9f) (range %d..%d -> %d..%d)"
                  % (K, rho, amp, r_ext, br, bestR, lo, hi, lo2, hi2))

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

