def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _densify(h, c):
    dense = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    act = dense > 0
    if not np.any(act):
        return dense
    lvl = c * dense[act].mean()
    dense[~act] = lvl
    return _rescale(dense)


def _densify_ladder(dense, deadline, tag=""):
    work = dense.copy()
    best = dense.copy()
    bestR = R_of(dense)
    origin = tag + "seed"
    for beta in [1e4, 1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(work, 400, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.15, 0.08]):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 1.2:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 1.0, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _sym_project(h):
    return _rescale(0.5 * (h + h[::-1]))


def _sym_seeds(h):
    seeds = []
    s1 = _rescale(h + h[::-1])
    seeds.append(('S1', s1))
    prod = h * h[::-1]
    s2 = np.where(prod > 0, np.sqrt(prod), 0.0)
    s2 = _rescale(s2)
    seeds.append(('S2', s2))
    s3 = 0.5 * (h + h[::-1])
    Lf = _knots(h)
    mx = Lf.max()
    if mx > 0:
        idx = np.flatnonzero(Lf >= 0.999 * mx)
        lo = max(0, idx.min() - 1)
        hi = min(h.size - 1, idx.max())
        s3[lo:hi + 1] = h[lo:hi + 1]
    s3 = _rescale(s3)
    seeds.append(('S3', s3))
    return seeds


def _sym_polish(seed, deadline, tag=""):
    work = seed.copy()
    best = seed.copy()
    bestR = R_of(seed)
    origin = tag + "seed"
    if time.process_time() >= deadline - 0.3:
        return work, best, bestR, origin
    ht = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=1e6)
    ht = _sym_project(ht)
    r = R_of(ht)
    if r > bestR + 1e-14:
        work, best, bestR = ht, ht.copy(), r
        origin = tag + "b1e6"
    else:
        work = ht
    if time.process_time() >= deadline - 0.3:
        return work, best, bestR, origin
    ht = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=1e7)
    ht = _sym_project(ht)
    r = R_of(ht)
    if r > bestR + 1e-14:
        work, best, bestR = ht, ht.copy(), r
        origin = tag + "b1e7"
    else:
        work = ht
    for it, pad in enumerate([0.30, 0.15]):
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 300, deadline - 0.3, beta=1e7)
        ht = _sym_project(ht)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        else:
            work = ht
    if time.process_time() < deadline - 0.3:
        ht = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=0.0)
        ht = _sym_project(ht)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = tag + "b0"
        else:
            work = ht
    return work, best, bestR, origin


def _sym_pad_loop(work, best, bestR, deadline, tag=""):
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    origin = tag + "loop"
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        ht = _sym_project(ht)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        else:
            work = ht
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            ht2 = _sym_project(ht2)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
            else:
                work = ht2
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase D: densification experiment
    for c in [0.002, 0.02]:
        if time.process_time() >= deadline - 2.0:
            break
        dense = _densify(start_best, c)
        r0 = R_of(dense)
        nz0 = int(np.sum(dense == 0))
        if time.process_time() >= deadline - 1.5:
            break
        w, b, br, org = _densify_ladder(dense, deadline - 0.5,
                                        tag='dens%g' % c)
        nz = int(np.sum(b == 0))
        print("dens c=%g: seed R=%.9f zeros=%d -> R=%.9f zeros=%d origin=%s"
              % (c, r0, nz0, br, nz, org))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("dens c=%g NEW BEST R=%.9f" % (c, bestR))
        elif br > alt_bestR and br > start_bestR + 1e-14:
            alt_best, alt_bestR = b, br

    # ---- NEW: symmetrisation experiment ----
    sym_best = None
    sym_bestR = -1.0
    sym_origin = 'none'
    seeds = _sym_seeds(start_best)
    for name, seed in seeds:
        if time.process_time() >= deadline - 1.5:
            break
        r_seed = R_of(seed)
        sub_deadline = min(deadline - 0.5, time.process_time() + 6.0)
        w, b, br, org = _sym_polish(seed, sub_deadline, tag=name)
        Lf = _knots(b)
        am = int(np.argmax(Lf)) / max(1.0, (b.size + 1))
        print("sym %s: seed R=%.9f -> R=%.9f origin=%s argmax=%.3f"
              % (name, r_seed, br, org, am))
        if br > sym_bestR:
            sym_best, sym_bestR, sym_origin = b, br, org
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("sym %s NEW BEST R=%.9f" % (name, bestR))
        elif br > alt_bestR and br > start_bestR + 1e-14:
            alt_best, alt_bestR = b, br

    # Spend remaining time on symmetrised pad-window loop
    if sym_best is not None and time.process_time() < deadline - 1.5:
        w, b, br, org = _sym_pad_loop(sym_best.copy(), sym_best.copy(),
                                      sym_bestR, deadline - 0.5, tag='sym')
        if br > sym_bestR:
            sym_best, sym_bestR, sym_origin = b, br, org
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("sym loop NEW BEST R=%.9f" % bestR)
        elif br > alt_bestR and br > start_bestR + 1e-14:
            alt_best, alt_bestR = b, br

    if sym_best is not None:
        Lf = _knots(sym_best)
        am = int(np.argmax(Lf)) / max(1.0, (sym_best.size + 1))
        print("sym best R=%.9f origin=%s argmax=%.3f" %
              (sym_bestR, sym_origin, am))

    # Phase B: random multi-start perturbations of the best
    rng = np.random.default_rng(12345)
    amps = [0.01, 0.03, 0.05, 0.08, 0.12, 0.02, 0.04, 0.06, 0.10, 0.15]

    for trial, amp in enumerate(amps):
        if time.process_time() >= deadline - 1.0:
            break
        seed = _random_perturb(best, rng, amp)
        r_seed = R_of(seed)
        w, b, br, org = _run_cycle(seed, seed.copy(), r_seed, deadline,
                                   'rand%d' % trial)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("rand%d amp=%.3f: R=%.9f NEW BEST" % (trial, amp, bestR))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("rand%d amp=%.3f: R=%.9f (best %.9f)" % (trial, amp, br, bestR))

    # Phase C: power-law edge extension sweep
    if time.process_time() < deadline - 2.0:
        for (K, p) in [(2048, 3.0), (2048, 2.0)]:
            if time.process_time() >= deadline - 1.0:
                break
            ext = _edge_extend_pow(best, K, p)
            r_ext = R_of(ext)
            w, b, br, org = _run_cycle(ext, ext.copy(), r_ext, deadline,
                                       'pow%d_%g' % (K, p))
            if br > bestR + 1e-14:
                best, bestR, origin = b, br, org
            elif br > alt_bestR:
                alt_best, alt_bestR = b, br

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 1000, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 96, 1e8), (0.20, 160, 1e8),
              (0.35, 320, 1e8), (0.55, 640, 1e8), (0.80, 1024, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=300, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _spike_perturb(h, rng, frac=0.10, sigma=0.30):
    out = h.copy()
    S = np.flatnonzero(h > 0)
    if S.size == 0:
        return out
    m = max(1, int(frac * S.size))
    S = rng.choice(S, size=m, replace=False)
    out[S] *= np.exp(rng.normal(0.0, sigma, S.size))
    return np.clip(out, 0.0, None)


def _smooth_perturb(h, rng, width=8, sigma=0.10):
    n = h.size
    k = max(1, n // width)
    noise = rng.normal(0.0, sigma, k)
    up = np.repeat(noise, width)[:n]
    if up.size < n:
        up = np.concatenate([up, np.zeros(n - up.size)])
    return np.clip(h * np.exp(up), 0.0, None)


def _upsample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    edges = np.linspace(0.0, 1.0, n + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, N + 1)
    mass = np.interp(xs, edges, cum)
    out = np.diff(mass)
    return np.clip(out, 0.0, None)


def _refine_upsampled(h, factor, deadline, tol=1e-7):
    N = h.size * factor
    if N > 1000000:
        return h, R_of(h)
    hu = _upsample(h, N)
    r0 = R_of(h)
    hu = _lbfgs_all_pos(hu, 400, deadline, beta=0.0)
    ru = R_of(hu)
    if ru > r0 + tol:
        return hu, ru
    return h, r0


def _symmetrize(h):
    """Force mirror symmetry about the center; R is invariant to reversal
    but the peak constraint tends to break symmetry, and a symmetric f
    has its autoconvolution peak exactly at center."""
    n = h.size
    i = np.arange(n)
    j = n - 1 - i
    out = 0.5 * (h[i] + h[j])
    # If the peak is not centered, better not symmetrize.
    return out


def _center_peak(h):
    """Shift h so that the autoconvolution peak lies at the center.
    This removes slack from the support boundary constraints."""
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    # knot index m corresponds to peak; support spans [0, n]. We want m ~= n.
    shift = m - h.size
    if shift == 0:
        return h
    out = np.zeros_like(h)
    n = h.size
    if shift > 0:
        # peak is too far right; move mass left
        out[:n - shift] = h[shift:]
    else:
        out[-shift:] = h[:n + shift]
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(int(t0 * 1000) & 0xffffffff)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # (1) Polish the given start.
    if time.process_time() < deadline - 8.0:
        best, bestR = run_cycle(best, bestR, deadline - 8.0)
        print("cycle1 R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # (2) Try peak-centering: shift so peak is centered, then polish.
    if time.process_time() < deadline - 6.0:
        hc = _center_peak(best)
        rc = R_of(hc)
        if rc > bestR - 1e-3:
            hc = _lbfgs_all_pos(hc, 400, deadline - 6.0, beta=0.0)
            rc = R_of(hc)
            if rc > bestR + 1e-9:
                best, bestR = hc, rc
                print("center R=%.7f" % bestR)

    # (3) Upsample to finer grid at each factor, polish.
    for factor in (2, 3, 4):
        if time.process_time() >= deadline - 5.0:
            break
        if best.size * factor > 1000000:
            break
        h_up, r_up = _refine_upsampled(best, factor, deadline - 5.0)
        print("upsample x%d R=%.7f (N=%d)" % (factor, r_up, h_up.size))
        if r_up > bestR + 1e-9:
            best, bestR = h_up, r_up
            break

    # (4) Population of perturbed variants; polish each and keep the best.
    K = 4
    members = []
    for k in range(K):
        if time.process_time() >= deadline - 3.0:
            break
        if k % 2 == 0:
            h_k = _spike_perturb(best, rng, frac=0.10, sigma=0.30)
        else:
            h_k = _smooth_perturb(best, rng, width=max(4, best.size // 512),
                                  sigma=0.08)
        r_pre = R_of(h_k)
        h_k = _lbfgs_all_pos(h_k, 250, deadline - 3.0, beta=0.0)
        r_post = R_of(h_k)
        members.append((r_post, h_k))
        print("member %d pre %.7f post %.7f" % (k, r_pre, r_post))

    if members:
        members.sort(key=lambda t: -t[0])
        if members[0][0] > bestR + 1e-13:
            best, bestR = members[0][1].copy(), members[0][0]

    # (5) Crossover between top members, then polish.
    if len(members) >= 2 and time.process_time() < deadline - 3.0:
        A = members[0][1]; B = members[1][1]
        n = best.size
        lo = int(rng.uniform(0.25, 0.65) * n)
        hi = min(n, lo + int(rng.uniform(0.2, 0.4) * n))
        child = A.copy()
        child[lo:hi] = B[lo:hi]
        free = np.arange(max(0, lo - 512), min(n, hi + 512))
        child = _lbfgs_block(child, free, 200, deadline - 3.0, beta=1e7)
        child = _lbfgs_all_pos(child, 250, deadline - 3.0, beta=0.0)
        rc = R_of(child)
        print("crossover R=%.7f" % rc)
        if rc > bestR + 1e-13:
            best, bestR = child.copy(), rc

    # (6) Repeated polish cycles until deadline.
    cyc = 0
    while time.process_time() < deadline - 1.5:
        cyc += 1
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("cycle %d R=%.7f" % (cyc + 1, bestR))

    # (7) Final polish.
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _densify(h):
    h = np.clip(h, 0, None)
    pos = h[h > 0]
    if pos.size == 0:
        return h
    eps = 1e-6 * pos.mean()
    out = h.copy()
    out[out <= 0] = eps
    return _rescale(out)


# ---- knot insertion / removal: change the resolution itself ----

def _resample_upsample(h, factor):
    """Linear (piecewise) subdivision: each step split into `factor` equal pieces
    with the same height (mass preserved)."""
    if factor <= 1:
        return h.copy()
    return _rescale(np.repeat(np.clip(h, 0, None), factor))


def _resample_smooth(h, newn):
    """Resample h onto `newn` steps by linear interpolation of the cumulative
    integral (keeps total mass and shape smoothness)."""
    h = np.clip(h, 0, None)
    n = h.size
    if n == newn:
        return h.copy()
    if n == 0 or h.sum() <= 0:
        return h
    c = np.concatenate(([0.0], np.cumsum(h)))
    c /= c[-1]
    xs = np.linspace(0.0, 1.0, newn + 1)
    cn = np.interp(xs, np.linspace(0.0, 1.0, n + 1), c)
    hn = np.diff(cn)
    return _rescale(np.clip(hn, 0, None))


def _shrink_zeros(h, keep_frac=1.0):
    """Drop zero runs shorter than a threshold (coarsen leading/trailing zeros)."""
    h = np.clip(h, 0, None)
    n = h.size
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    lo, hi = nz[0], nz[-1]
    # Trim strictly-outside zeros (they cost resolution for nothing)
    return h[lo:hi + 1]


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR, 0.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(20240501)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: trim useless zeros and re-check plateau ----
    trimmed = _shrink_zeros(best)
    if trimmed.size > 0:
        trimmed = _rescale(trimmed)
        r = R_of(trimmed)
        if r > bestR - 1e-9:
            best, bestR = trimmed, r
    print("trim R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # ---- Phase 2: resolution sweep. Try coarser AND finer representations,
    # each polished with the full cycle. This is the new idea: the optimum
    # plateau region may be better represented at a different N. ----
    tried = set()
    results = []

    def try_resolution(hseed, label):
        nonlocal best, bestR
        if time.process_time() >= deadline - 2.0:
            return
        hh = _densify(hseed)
        hh, rr, _ = run_cycle(hh, R_of(hh), deadline - 1.5)
        results.append((rr, hh.size, label))
        if rr > bestR + 1e-13:
            best, bestR = hh.copy(), rr
            print("  %s N=%d -> R=%.7f NEW BEST" % (label, hh.size, rr))
        else:
            print("  %s N=%d -> R=%.7f" % (label, hh.size, rr))

    # Sweep coarse-to-fine around the current N, capped at 1M.
    n0 = best.size
    targets = []
    for f in [0.25, 0.5, 0.75, 1.5, 2.0, 3.0, 4.0, 6.0, 8.0]:
        nn = int(round(n0 * f))
        if 32 <= nn <= 950000 and nn not in tried:
            targets.append(nn)
            tried.add(nn)
    # Also try a few absolute sizes.
    for nn in [16384, 32768, 65536, 131072, 262144, 524288, 900000]:
        if nn not in tried:
            targets.append(nn)
            tried.add(nn)
    # Interleave coarse/fine.
    targets.sort()

    for nn in targets:
        if time.process_time() >= deadline - 2.0:
            break
        hseed = _resample_smooth(best, nn)
        try_resolution(hseed, "resample")

    # ---- Phase 3: from the best resolution, run a final global polish ----
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)

    # ---- Phase 4: use remaining time on fine-grained local moves at
    # the best resolution, upsampling if there's slack. ----
    it = 0
    while time.process_time() < deadline - 1.2:
        it += 1
        # Try slight upsample + polish as a cheap improvement move.
        if best.size < 400000 and time.process_time() < deadline - 3.0:
            hu = _resample_smooth(best, int(best.size * 1.5))
            hu = _lbfgs_all_pos(_densify(hu), 800, deadline - 1.5, beta=0.0)
            r = R_of(hu)
            if r > bestR + 1e-13:
                best, bestR = hu.copy(), r
                print("iter %d upsample R=%.7f N=%d" % (it, bestR, best.size))
                continue
        hp = _densify(best)
        hp = _lbfgs_all_pos(hp, 1200, deadline - 1.2, beta=0.0)
        for beta in [1e5, 1e6, 1e7, 1e8]:
            if time.process_time() >= deadline - 1.2:
                break
            hp = _lbfgs_all_pos(hp, 200, deadline - 1.2, beta=beta)
        if time.process_time() < deadline - 1.2:
            win = _peak_window(hp, tol=0.99, pad_frac=0.3, extra=256)
            hp = _lbfgs_block(hp, win, 250, deadline - 1.2, beta=0.0)
        if time.process_time() < deadline - 1.2:
            hp = _lbfgs_all_pos(hp, 300, deadline - 1.2, beta=0.0)
        r = R_of(hp)
        if r > bestR + 1e-13:
            best, bestR = hp.copy(), r
            print("iter %d R=%.7f N=%d" % (it, bestR, best.size))

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

