        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: trim useless zeros and re-check plateau ----
    trimmed = _shrink_zeros(best)
    if trimmed.size > 0:
        trimmed = _rescale(trimmed)
        r = R_of(trimmed)
        if r > bestR - 1e-9:
            best, bestR = trimmed, r
    print("trim R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    # ---- Phase 2: resolution sweep. Try coarser AND finer representations,
    # each polished with the full cycle. This is the new idea: the optimum
    # plateau region may be better represented at a different N. ----
    tried = set()
    results = []

    def try_resolution(hseed, label):
        nonlocal best, bestR
        if time.process_time() >= deadline - 2.0:
            return
        hh = _densify(hseed)
        hh, rr, _ = run_cycle(hh, R_of(hh), deadline - 1.5)
        results.append((rr, hh.size, label))
        if rr > bestR + 1e-13:
            best, bestR = hh.copy(), rr
            print("  %s N=%d -> R=%.7f NEW BEST" % (label, hh.size, rr))
        else:
            print("  %s N=%d -> R=%.7f" % (label, hh.size, rr))

    # Sweep coarse-to-fine around the current N, capped at 1M.
    n0 = best.size
    targets = []
    for f in [0.25, 0.5, 0.75, 1.5, 2.0, 3.0, 4.0, 6.0, 8.0]:
        nn = int(round(n0 * f))
        if 32 <= nn <= 950000 and nn not in tried:
            targets.append(nn)
            tried.add(nn)
    # Also try a few absolute sizes.
    for nn in [16384, 32768, 65536, 131072, 262144, 524288, 900000]:
        if nn not in tried:
            targets.append(nn)
            tried.add(nn)
    # Interleave coarse/fine.
    targets.sort()

    for nn in targets:
        if time.process_time() >= deadline - 2.0:
            break
        hseed = _resample_smooth(best, nn)
        try_resolution(hseed, "resample")

    # ---- Phase 3: from the best resolution, run a final global polish ----
    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)

    # ---- Phase 4: use remaining time on fine-grained local moves at
    # the best resolution, upsampling if there's slack. ----
    it = 0
    while time.process_time() < deadline - 1.2:
        it += 1
        # Try slight upsample + polish as a cheap improvement move.
        if best.size < 400000 and time.process_time() < deadline - 3.0:
            hu = _resample_smooth(best, int(best.size * 1.5))
            hu = _lbfgs_all_pos(_densify(hu), 800, deadline - 1.5, beta=0.0)
            r = R_of(hu)
            if r > bestR + 1e-13:
                best, bestR = hu.copy(), r
                print("iter %d upsample R=%.7f N=%d" % (it, bestR, best.size))
                continue
        hp = _densify(best)
        hp = _lbfgs_all_pos(hp, 1200, deadline - 1.2, beta=0.0)
        for beta in [1e5, 1e6, 1e7, 1e8]:
            if time.process_time() >= deadline - 1.2:
                break
            hp = _lbfgs_all_pos(hp, 200, deadline - 1.2, beta=beta)
        if time.process_time() < deadline - 1.2:
            win = _peak_window(hp, tol=0.99, pad_frac=0.3, extra=256)
            hp = _lbfgs_block(hp, win, 250, deadline - 1.2, beta=0.0)
        if time.process_time() < deadline - 1.2:
            hp = _lbfgs_all_pos(hp, 300, deadline - 1.2, beta=0.0)
        r = R_of(hp)
        if r > bestR + 1e-13:
            best, bestR = hp.copy(), r
            print("iter %d R=%.7f N=%d" % (it, bestR, best.size))

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _zero_frac(h):
    return float(np.mean(h == 0))


def _upsample(h, factor):
    """Insert zeros into gaps and interpolate to a finer grid."""
    n = h.size
    m = (n - 1) * factor + 1
    x_old = np.arange(n, dtype=float)
    x_new = np.linspace(0, n - 1, m)
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: N-doubling refinement.
    # The optimal f*f has a sharp peak; the peak region is where resolution
    # matters most. Upsampling the current best and re-optimising lets the
    # optimiser place new degrees of freedom near the peak, which the
    # block/window sweeps on the fixed grid cannot do.
    if time.process_time() < deadline - 4.0 and best.size < 200000:
        try:
            factor = 2
            up = _upsample(best, factor)
            up = _rescale(up)
            r_up = R_of(up)
            print("upsample x%d: N=%d R=%.9f" % (factor, up.size, r_up))
            # quick polish on the finer grid, all-pos
            ht = _lbfgs_all_pos(up, 400, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht, r, "upsample%d" % factor
                print("upsample polish: R=%.9f NEW BEST N=%d" % (bestR, best.size))
            else:
                if r > alt_bestR and ht.size == best.size:
                    alt_best, alt_bestR = ht.copy(), r
                print("upsample polish: R=%.9f (best %.9f)" % (r, bestR))
                # try a small window sweep on the upsampled version
                if time.process_time() < deadline - 3.0 and ht.size > 0:
                    win = _peak_window(ht, pad_frac=0.25, extra=128)
                    ht2 = _lbfgs_block(ht, win, 400, deadline - 2.0, beta=1e7)
                    ht2 = _lbfgs_all_pos(ht2, 300, deadline - 2.0, beta=0.0)
                    r2 = R_of(ht2)
                    if r2 > bestR + 1e-14:
                        best, bestR, origin = ht2, r2, "upsample%d+win" % factor
                        print("upsample win: R=%.9f NEW BEST" % bestR)
                    else:
                        if r2 > alt_bestR and ht2.size == best.size:
                            alt_best, alt_bestR = ht2.copy(), r2
                        print("upsample win: R=%.9f (best %.9f)" % (r2, bestR))
        except Exception as exc:
            print("upsample failed: %s" % exc)

    # Phase C: gradient-scaled densification (as before, but on the possibly
    # upsampled best)
    if time.process_time() < deadline - 2.0:
        try:
            val, g = _fun_grad_beta(best, 1e7)
            zi = np.flatnonzero(best == 0)
            if zi.size > 0:
                gi = g[zi]
                keep = gi < 0
                zi = zi[keep]
                gi = gi[keep]
            else:
                gi = np.zeros(0)
        except Exception:
            zi = np.zeros(0, dtype=int)
            gi = np.zeros(0)

        if zi.size > 0:
            pos = best[best > 0]
            amean = float(pos.mean()) if pos.size > 0 else 1.0
            w = (-gi)
            wmean = w.mean()
            if wmean <= 0:
                wmean = 1.0
            w = w / wmean
            print("densify: %d improving zeros, zero_frac=%.3f" %
                  (zi.size, _zero_frac(best)))
            for alpha in [1e-3, 1e-2, 5e-2]:
                if time.process_time() >= deadline - 1.5:
                    break
                dense = best.copy()
                dense[zi] = alpha * amean * w
                dense = _rescale(dense)
                # polish
                ht = _lbfgs_all_pos(dense, 300, deadline - 0.5, beta=1e4)
                ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=1e6)
                ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=1e7)
                r = R_of(ht)
                if r > bestR + 1e-14:
                    best, bestR = ht.copy(), r
                    origin = "dens_a%.0e" % alpha
                    print("  alpha=%.0e polish R=%.9f NEW BEST" % (alpha, bestR))
                else:
                    if r > alt_bestR and ht.size == best.size:
                        alt_best, alt_bestR = ht.copy(), r
                    print("  alpha=%.0e polish R=%.9f (best %.9f)" % (alpha, r, bestR))
                for pad in [0.30, 0.15, 0.08]:
                    if time.process_time() >= deadline - 1.0:
                        break
                    win = _peak_window(ht, pad_frac=pad, extra=128)
                    ht2 = _lbfgs_block(ht, win, 400, deadline - 0.5, beta=1e7)
                    ht2 = _lbfgs_all_pos(ht2, 300, deadline - 0.5, beta=0.0)
                    r2 = R_of(ht2)
                    if r2 > bestR + 1e-14:
                        best, bestR = ht2.copy(), r2
                        origin = "dens_a%.0e_pk%.2f" % (alpha, pad)
                        print("  alpha=%.0e pad=%.2f R=%.9f NEW BEST" % (alpha, pad, bestR))
                    else:
                        if r2 > alt_bestR and ht2.size == best.size:
                            alt_best, alt_bestR = ht2.copy(), r2
                    ht = ht2 if r2 >= r else ht
        else:
            print("densify: no improving zeros, skip")

    # Phase D: random perturbations
    rng = np.random.default_rng(98765)
    amps = [0.01, 0.03, 0.05, 0.08, 0.12, 0.02, 0.04, 0.06, 0.10, 0.15]
    for trial, amp in enumerate(amps):
        if time.process_time() >= deadline - 1.0:
            break
        seed = best.copy()
        nz = seed > 0
        noise = np.exp(amp * rng.standard_normal(seed.size))
        seed[nz] *= noise[nz]
        seed = _rescale(seed)
        r_seed = R_of(seed)
        w2, b, br, org = _run_cycle(seed, seed.copy(), r_seed, deadline,
                                    'rand%d' % trial)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("rand%d amp=%.3f: R=%.9f NEW BEST" % (trial, amp, bestR))
        else:
            if br > alt_bestR and b.size == best.size:
                alt_best, alt_bestR = b, br
            print("rand%d amp=%.3f: R=%.9f (best %.9f)" % (trial, amp, br, bestR))

    # Final window sweep
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, origin + '+finalwin'

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.15, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _zero_frac(h):
    return float(np.mean(h == 0))


def _newton_polish(best, bestR, deadline):
    """Trust-region Newton (trust-krylov) on the peak window in log coords."""
    win = _peak_window(best, pad_frac=0.25, extra=256)
    free = win[best[win] > 0]
    if free.size < 2:
        print("newton: window too small (%d)" % free.size)
        return best, bestR, False
    z0 = np.log(np.clip(best[free], 1e-300, None))
    base = best.copy()

    def fz(z):
        hh = base.copy()
        hh[free] = np.exp(np.clip(z, -700, 700))
        val, g = _fun_grad(hh)
        return val, g[free] * hh[free]

    def gz(z):
        return fz(z)[1]

    def hessp(z, p):
        try:
            nz = np.linalg.norm(z)
            np_ = np.linalg.norm(p)
            eps = 1e-6 * (1.0 + nz) / max(np_, 1e-30)
            gp = gz(z + eps * p)
            gm = gz(z - eps * p)
            return (gp - gm) / (2.0 * eps)
        except Exception:
            return p

    try:
        v0, g0 = fz(z0)
        gn0 = float(np.linalg.norm(g0))
    except Exception:
        gn0 = float('nan')
    print("newton: window=%d free=%d ||grad(z0)||=%.3e" %
          (win.size, free.size, gn0))

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fz, z0, jac=True, hessp=hessp, method='trust-krylov',
                       callback=cb,
                       options={'maxiter': 60, 'gtol': 1e-10,
                                'initial_tr_radius': 1e-3})
    except (TimeoutError, Exception) as e:
        print("newton: failed (%s)" % type(e).__name__)
        return best, bestR, False
    if res is None:
        return best, bestR, False
    try:
        gn1 = float(np.linalg.norm(res.jac))
    except Exception:
        gn1 = float('nan')
    ht = base.copy()
    ht[free] = np.exp(np.clip(res.x, -700, 700))
    ht = _rescale(np.clip(ht, 0.0, None))
    r = R_of(ht)
    print("newton: ||grad(z*)||=%.3e R=%.9f (best %.9f)" % (gn1, r, bestR))
    if r > bestR + 1e-14:
        return ht, r, True
    return best, bestR, False


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: shortened baseline cycle on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: second-order Newton polish on peak window
    newton_gain = False
    if time.process_time() < deadline - 2.0:
        ht, r, gain = _newton_polish(best, bestR, deadline)
        if gain:
            best, bestR = ht, r
            origin = origin + '+newton'
            newton_gain = True
            print("newton: NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # Phase C: consolidate with pad-window beta=1e7 polishes + beta=0 global
    pads = [0.25, 0.15, 0.10, 0.20, 0.08, 0.30, 0.12]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + '+pk%.2f' % pad
            print("pad=%.2f: R=%.9f NEW BEST" % (pad, bestR))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2.copy(), r2
                origin = origin + '+all0'
                print("all0 after pad=%.2f: R=%.9f NEW BEST" % (pad, bestR))
            else:
                if r2 > alt_bestR:
                    alt_best, alt_bestR = ht2.copy(), r2

    # Phase D: if Newton gave a gain, try a second Newton round
    if newton_gain and time.process_time() < deadline - 1.0:
        ht, r, gain = _newton_polish(best, bestR, deadline)
        if gain:
            best, bestR = ht, r
            origin = origin + '+newton2'
            print("newton2: NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag="", pads=None):
    if pads is None:
        pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _zero_frac(h):
    return float(np.mean(h == 0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: shortened baseline cycle from slot 1
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base',
            pads=[0.30, 0.15, 0.08])
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: gradual densification ladder
    arr_walk = best.copy()
    r_walk = bestR
    dense_final = best.copy()
    if time.process_time() < deadline - 2.0:
        base_state = best.copy()
        pos = base_state[base_state > 0]
        mean_act = float(pos.mean()) if pos.size > 0 else 1.0
        work = base_state.copy()
        for c in [1e-3, 3e-3, 1e-2, 3e-2, 1e-1, 3e-1]:
            if time.process_time() >= deadline - 2.0:
                break
            work[work == 0] = c * mean_act
            work = _rescale(work)
            for beta in [1e5, 1e6, 1e7]:
                if time.process_time() >= deadline - 2.0:
                    break
                work = _lbfgs_all_pos(work, 150, deadline - 2.0, beta=beta)
            r = R_of(work)
            print("walk c=%.0e R=%.9f zero_frac=%.3f" %
                  (c, r, _zero_frac(work)))
            if r > r_walk + 1e-14:
                r_walk = r
                arr_walk = work.copy()
            dense_final = work.copy()

    # Phase C: standard cycle from arr_walk
    if time.process_time() < deadline - 1.0:
        w, b, br, org = _run_cycle(
            arr_walk.copy(), arr_walk.copy(), r_walk, deadline, 'walk',
            pads=[0.30, 0.15, 0.08])
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("walk-cycle: R=%.9f NEW BEST zero_frac=%.3f" %
                  (bestR, _zero_frac(best)))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("walk-cycle: R=%.9f (best %.9f)" % (br, bestR))

    # Phase D: standard cycle from dense_final if time allows
    if time.process_time() < deadline - 1.0:
        rd = R_of(dense_final)
        w, b, br, org = _run_cycle(
            dense_final.copy(), dense_final.copy(), rd, deadline, 'dense',
            pads=[0.30, 0.15, 0.08])
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("dense-cycle: R=%.9f NEW BEST zero_frac=%.3f" %
                  (bestR, _zero_frac(best)))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br
            print("dense-cycle: R=%.9f (best %.9f)" % (br, bestR))

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

