def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Shortened baseline: three beta passes then pads [0.30, 0.15, 0.08],
    # with the beta=0 global pass only at the first pad. Finish by deadline-35s.
    base_deadline = deadline - 35.0
    if time.process_time() < base_deadline - 0.5:
        work = best.copy()
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= base_deadline - 0.3:
                break
            ht = _lbfgs_all_pos(work, 300, base_deadline - 0.2, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "basebeta%g" % beta
        for it, pad in enumerate([0.30, 0.15, 0.08]):
            if time.process_time() >= base_deadline - 0.3:
                break
            win = _peak_window(work, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 400, base_deadline - 0.2, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "basepk%d" % it
            if it == 0 and time.process_time() < base_deadline - 0.4:
                ht2 = _lbfgs_all_pos(work, 300, base_deadline - 0.2, beta=0.0)
                r2 = R_of(ht2)
                if r2 > bestR + 1e-14:
                    work, best, bestR = ht2, ht2.copy(), r2
                    origin = "basepk0+all0"
                else:
                    work = ht2 if r2 >= r else work
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase C replacement: time-filling accept-only log-normal perturbation loop.
    rng = np.random.default_rng(1234)
    lo = np.log(2e-3)
    hi = np.log(3e-2)
    pads = [0.30, 0.20, 0.15, 0.12, 0.10, 0.08]
    n_trials = 0
    n_accept = 0
    while time.process_time() < deadline - 2.0:
        amp = float(np.exp(rng.uniform(lo, hi)))
        seed = _random_perturb(best, rng, amp)
        pad = pads[n_trials % 6]
        win = _peak_window(seed, pad_frac=pad, extra=128)
        ht = _lbfgs_block(seed, win, 250, deadline - 0.8, beta=1e7)
        if n_trials % 3 == 0 and time.process_time() < deadline - 1.2:
            ht = _lbfgs_all_pos(ht, 200, deadline - 0.8, beta=0.0)
        r = R_of(ht)
        n_trials += 1
        if r > bestR + 1e-12:
            best, bestR = ht.copy(), r
            n_accept += 1
            origin = "trial%d_a%.4f_p%.2f" % (n_trials, amp, pad)
            print("trial %d amp=%.4f pad=%.2f R=%.9f NEW BEST" %
                  (n_trials, amp, pad, r))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            print("trial %d amp=%.4f pad=%.2f R=%.9f (best %.9f)" %
                  (n_trials, amp, pad, r, bestR))

    # Final window polish.
    if time.process_time() < deadline - 0.6:
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + "+finalwin"

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))
    print("n_trials=%d n_accept=%d" % (n_trials, n_accept))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

