    else:
        bestH, bestR = baseH.copy(), baseR

    altH = bestH.copy()
    altR = bestR

    # Phase 1: beta-schedule global optim (helps escape the argmax plateau).
    for beta in (0.0, 1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 4.0:
