    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish (0-55%) ----
    N = best.size
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        h0 = best.copy()
        resid = float(np.max(np.abs(h0[0::2] - h0[1::2]))) if N else 0.0
        print("initial staircase residual max|h0[0::2]-h0[1::2]| = %.3e" % resid)
        c = h0[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.55
        rounds = 0
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
            if time.process_time() >= half_deadline - 1.0:
                break
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        # lift
        h_lift = np.repeat(best_c, 2)
        h_lift = _rescale(h_lift)
        r_lift = R_of(h_lift)
        print("lifted R=%.9f" % r_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            print("lift+ladder R=%.9f (best %.9f)" % (r, bestR))

    # ---- Phase 2: sharp narrow peak windows in the quotient (55%-deadline) ----
    pads = [0.15, 0.10, 0.08, 0.06, 0.05, 0.04, 0.03]
    accepted_total = 0
    pass_no = 0
    cc = best[0::2].copy()
    ccR = R_of(cc)
    while time.process_time() < deadline - 1.0:
        pass_no += 1
        accepted_this_pass = 0
        for pi, pad in enumerate(pads):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cc, pad_frac=pad, extra=64)
            cand = _lbfgs_block(cc, win, 400, deadline - 0.3, beta=1e7)
            r_cand = R_of(cand)
            if r_cand > ccR + 1e-14:
                cc = cand
