        if time.process_time() < slice_dl - 0.5:
            p = _lbfgs_all_pos(p, 300, slice_dl, beta=0.0)
        r = R_of(p)
        restarts_done += 1
        if r > bestR + 1e-13:
            best, bestR = p.copy(), r
            accepted_count += 1
            origin = 'restart%d' % i
            print("restart %d amp=%.4f R=%.9f ACCEPT (zf=%.3f)"
                  % (i, amp, r, _zero_frac(best)))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = p.copy(), r
            print("restart %d amp=%.4f R=%.9f no gain" % (i, amp, r))

    print("restarts=%d accepted=%d best=%.9f" %
