def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _upsample(h, factor):
    if factor <= 1:
        return h.copy()
    out = np.repeat(h, factor) / factor
    return _rescale(out)


def _try_upsample_refine(best, bestR, deadline, factor):
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    hu = _upsample(best, factor)
    r0 = R_of(hu)
    hu2 = _lbfgs_all_pos(hu, 400, deadline - 0.5, beta=0.0)
    r1 = R_of(hu2)
    if r1 > bestR + 1e-13:
        print("upsample x%d: R=%.7f (base %.7f, raw %.7f)"
              % (factor, r1, bestR, r0))
        return hu2, r1
    if r0 > bestR + 1e-13:
        return hu, r0
    print("upsample x%d: no gain (raw %.7f, refined %.7f vs %.7f)"
          % (factor, r0, r1, bestR))
    return best, bestR


def _perturb_and_polish(best, bestR, deadline, rng, scale, n_pert, maxiter):
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    n = best.size
    cand = best.copy()
    idx = rng.integers(0, n, size=n_pert)
    factors = np.exp(rng.normal(0.0, scale, size=n_pert))
    cand[idx] *= factors
    cand = _rescale(cand)
    cand = _lbfgs_all_pos(cand, maxiter, deadline - 0.5, beta=0.0)
    if time.process_time() < deadline - 0.5:
        win = _peak_window(cand, pad_frac=0.2, extra=256)
        cand = _lbfgs_block(cand, win, maxiter=200, deadline=deadline - 0.5,
                            beta=1e8)
    r = R_of(cand)
    if r > bestR + 1e-13:
        print("perturb n=%d scale=%.2e -> R=%.7f (dR=%.2e)"
              % (n_pert, scale, r, r - bestR))
        return cand, r
    return best, bestR


# ---------------------------------------------------------------------------
# NEW: sub-cell (parametric) refinement.
# Treat the step function as samples of a piecewise-linear continuous profile.
# We refine by splitting each step into pieces and letting L-BFGS find the
# shape, but crucially we *interpolate* into the finer grid rather than simply
# replicating blocks.  Linear interpolation of heights between adjacent cells
# places mass in a smoother way that better approximates the underlying
# continuous optimum, and starting L-BFGS from that point escapes the blocky
# local minimum.
# ---------------------------------------------------------------------------
def _interp_upsample(h, factor):
    """Upsample via linear interpolation of cell-centre heights."""
    n = h.size
    if factor <= 1:
        return h.copy()
    # cell centres at (i + 0.5) / n in [0,1]
    xi = (np.arange(n) + 0.5) / n
    m = n * factor
    xo = (np.arange(m) + 0.5) / m
    out = np.interp(xo, xi, h, left=h[0], right=h[-1])
    out = np.clip(out, 0, None)
    # preserve mass: each output cell is 1/factor wide, so scale by factor
    out = out * factor
    return _rescale(out)


def _try_interp_upsample(best, bestR, deadline, factor, maxiter=500):
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    hu = _interp_upsample(best, factor)
    r0 = R_of(hu)
    hu2 = _lbfgs_all_pos(hu, maxiter, deadline - 0.5, beta=0.0)
    r1 = R_of(hu2)
    if r1 > bestR + 1e-13:
        print("interp-upsample x%d: R=%.7f (base %.7f, raw %.7f)"
              % (factor, r1, bestR, r0))
        return hu2, r1
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase 0: one base cycle ----
    prevR = bestR
    best, bestR, drefine = run_cycle(best, bestR, deadline - 1.5)
    print("cycle 0 R=%.7f dR=%.2e drefine=%.2e zeros=%.1f%%"
          % (bestR, bestR - prevR, drefine, 100.0 * np.mean(best <= 0)))

    # ---- Phase 1: interpolation-based sub-cell refinement (NEW) ----
    # The block-replication upsample keeps a step function; linear interpolation
    # puts mass between cells, giving L-BFGS a smooth starting point that can
    # reach a strictly better local optimum on the finer grid.
    for factor in (2, 2, 3):
        if time.process_time() >= deadline - 25.0:
            break
        best, bestR = _try_interp_upsample(best, bestR, deadline, factor)
        print("after interp-upsample x%d: R=%.7f N=%d"
              % (factor, bestR, best.size))

    # Also try the classic block upsample as fallback
    if time.process_time() < deadline - 20.0:
        best, bestR = _try_upsample_refine(best, bestR, deadline, 2)
        print("after block-upsample: R=%.7f N=%d" % (bestR, best.size))

    # ---- Phase 2: peak-window fine tuning on the (possibly finer) grid ----
    for frac, extra, beta in [(0.03, 64, 1e7), (0.08, 128, 1e8),
                              (0.20, 256, 1e8), (0.45, 512, 1e8)]:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        cand = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                            beta=beta)
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand, r
            print("peak frac=%.2f R=%.7f" % (frac, bestR))

    # ---- Phase 3: perturbation restarts ----
    rng = np.random.default_rng(12345)
    while time.process_time() < deadline - 2.0:
        scale = float(rng.choice([1e-3, 1e-2, 5e-2]))
        n_pert = int(rng.integers(50, 2000))
        best, bestR = _perturb_and_polish(
            best, bestR, deadline, rng, scale, n_pert, maxiter=300)
        if time.process_time() < deadline - 2.0:
            win = _peak_window(best, pad_frac=0.15, extra=256)
            cand = _lbfgs_block(best, win, maxiter=150,
                                deadline=deadline - 0.5, beta=1e8)
            r = R_of(cand)
            if r > bestR + 1e-13:
                best, bestR = cand, r

    # ---- Closing global polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _polish(h, bestR, deadline):
    """Intensive local polishing with multiple beta levels + peak-window blocks."""
    work = h.copy()
    best = h.copy()
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            work, best, bestR = ht, ht.copy(), r
    for pad in [0.25, 0.15, 0.10, 0.06]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-15:
                work, best, bestR = ht2, ht2.copy(), r2
    return best, bestR


def _downsample(h, factor):
    """Average downsample by integer factor."""
    n = h.size
    m = n // factor
    if m < 2:
        return None
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _upsample(c, factor):
    return np.repeat(c, factor)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ============ PHASE A: quick fine polish of start (0-20%) ============
    hA, rA = _polish(best, bestR, t0 + budget_seconds * 0.20)
    if rA > bestR + 1e-15:
        best, bestR, origin = hA.copy(), rA, 'polish-start'
        print("polish-start R=%.9f" % bestR)
    elif rA > alt_bestR:
        alt_best, alt_bestR = hA.copy(), rA

    # ============ PHASE B: multi-scale re-derivation (20-70%) ============
    # Try factors 2, 4, 8: downsample, polish coarse, upsample, polish fine.
    scale_deadline = t0 + budget_seconds * 0.70
    for factor in [2, 4, 8]:
        if time.process_time() >= scale_deadline - 1.0:
            break
        cur = best
        # Try both the current best and the original start as seeds
        seeds = [cur]
        if start_best is not None and start_best.size == cur.size:
            seeds.append(start_best)
        for si, seed in enumerate(seeds):
            if time.process_time() >= scale_deadline - 1.0:
                break
            c = _downsample(seed, factor)
            if c is None or c.sum() <= 0:
                continue
            c = _rescale(c)
            cR = R_of(c)
            # polish coarse
            sub_deadline = min(scale_deadline - 0.5,
                               time.process_time() + (scale_deadline - time.process_time()) / 2.0)
            cc, ccR = _polish(c, cR, sub_deadline)
            h_up = _rescale(_upsample(cc, factor))
            if h_up.size != best.size:
                # pad or trim to match
                if h_up.size < best.size:
                    h_up = np.concatenate([h_up, np.zeros(best.size - h_up.size)])
                else:
                    h_up = h_up[:best.size]
                h_up = _rescale(h_up)
            r_up = R_of(h_up)
            # polish full resolution
            h_fine, r_fine = _polish(h_up, r_up, scale_deadline - 0.5)
            print("  scale f=%d s=%d: coarse %.9f -> up %.9f -> fine %.9f" %
                  (factor, si, ccR, r_up, r_fine))
            if r_fine > bestR + 1e-15:
                best, bestR, origin = h_fine.copy(), r_fine, 'scale%d' % factor
                print("  SCALE NEW BEST R=%.9f" % bestR)
            elif r_fine > alt_bestR:
                alt_best, alt_bestR = h_fine.copy(), r_fine

    # ============ PHASE C: half-resolution fill/prune (70-95%) ============
    if best.size % 2 == 0 and best.size >= 8:
        cc = best[0::2].copy()
        ccR = R_of(cc)
        # polish half-res
        hd = t0 + budget_seconds * 0.75
        cc, ccR = _polish(cc, ccR, hd)
        print("half-res R(c)=%.9f" % ccR)

        rng = np.random.RandomState(4242)
        n = cc.size
        pos_mean = float(np.mean(cc[cc > 0])) if np.any(cc > 0) else 1.0
        trials = 0
        while time.process_time() < deadline - 1.5:
            # build candidates: gaps between heavy runs, adjacencies to top runs
            nz = np.flatnonzero(cc > 0)
            if nz.size == 0:
                break
            runs = []
            s = nz[0]; p = nz[0]
            for q in nz[1:]:
                if q == p + 1:
                    p = q
                else:
                    runs.append((s, p)); s = q; p = q
            runs.append((s, p))
            masses = [(np.sum(cc[a:b + 1]), a, b) for a, b in runs]
            masses.sort(reverse=True)
            fill = []
            for m, a, b in masses[:8]:
                if a - 1 >= 0 and cc[a - 1] == 0:
                    fill.append(a - 1)
                if b + 1 < n and cc[b + 1] == 0:
                    fill.append(b + 1)
            # single-cell gaps
            for i in range(1, n - 1):
                if cc[i] == 0 and cc[i - 1] > 0 and cc[i + 1] > 0:
                    fill.append(i)
            fill = list(dict.fromkeys(fill))
            rng.shuffle(fill)

            nz_idx = np.flatnonzero(cc > 0)
            prune = list(nz_idx[np.argsort(cc[nz_idx])[:12]]) if nz_idx.size > 0 else []

            made = False
            for i in fill:
                if time.process_time() >= deadline - 1.5:
                    break
                if cc[i] != 0:
                    continue
                for eps in (5e-3, 3e-2, 0.15):
                    if time.process_time() >= deadline - 1.5:
                        break
                    cc2 = cc.copy()
                    cc2[i] = eps * pos_mean
                    win = np.arange(max(0, i - 40), min(n, i + 41))
                    cc2 = _lbfgs_block(cc2, win, 80, deadline - 1.0, beta=1e7)
                    if time.process_time() < deadline - 1.2:
                        cc2 = _lbfgs_block(cc2, win, 50, deadline - 1.0, beta=0.0)
                    r2 = R_of(cc2)
                    trials += 1
                    if r2 > ccR + 1e-13:
                        cc, ccR = cc2, r2
                        made = True
                        print("fill i=%d eps=%g R(c)=%.9f" % (i, eps, ccR))
                        break
                if made:
                    break
            if not made:
                for i in prune:
                    if time.process_time() >= deadline - 1.5:
                        break
                    if cc[i] == 0:
                        continue
                    cc2 = cc.copy()
                    cc2[i] = 0.0
                    win = np.arange(max(0, i - 40), min(n, i + 41))
                    cc2 = _lbfgs_block(cc2, win, 80, deadline - 1.0, beta=1e7)
                    if time.process_time() < deadline - 1.2:
                        cc2 = _lbfgs_block(cc2, win, 50, deadline - 1.0, beta=0.0)
                    r2 = R_of(cc2)
                    trials += 1
                    if r2 > ccR + 1e-13:
                        cc, ccR = cc2, r2
                        made = True
                        print("prune i=%d R(c)=%.9f" % (i, ccR))
                        break
            if not made:
                break

        # lift and polish
        h_lift = _rescale(np.repeat(cc, 2))
        h_fine, r_fine = _polish(h_lift, R_of(h_lift), deadline - 0.5)
        print("half-res final: lift %.9f -> fine %.9f" % (R_of(h_lift), r_fine))
        if r_fine > bestR + 1e-15:
            best, bestR, origin = h_fine.copy(), r_fine, 'half+fine'
            print("half+fine NEW BEST R=%.9f" % bestR)
        elif r_fine > alt_bestR:
            alt_best, alt_bestR = h_fine.copy(), r_fine

    # ============ PHASE D: final polish until deadline ============
    if time.process_time() < deadline - 0.5:
        h_fin, r_fin = _polish(best, bestR, deadline - 0.2)
        if r_fin > bestR + 1e-16:
            best, bestR, origin = h_fin.copy(), r_fin, origin + '+final'
            print("final polish R=%.9f" % bestR)
        elif h_fin is not None and r_fin > alt_bestR:
            alt_best, alt_bestR = h_fin.copy(), r_fin

    print("DONE R=%.9f origin=%s (start %.9f, N=%d, zero=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    """Alternation on the half-resolution quotient c."""
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _full_polish(h, slice_deadline, pads=(0.30, 0.15, 0.08)):
    """Beta ladder + peak pads + trailing beta=0, all bounded by slice_deadline."""
    ht = h
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= slice_deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
    for pad in pads:
        if time.process_time() >= slice_deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pad, extra=128)
        ht = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
    if time.process_time() < slice_deadline - 0.5:
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=0.0)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: single half-resolution cycle, lift, ladder ----
    N = best.size
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        h0 = best.copy()
        c = h0[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.12
        work_c, best_c, best_cR, org = _half_cycle(
            c, cR, half_deadline, tag='h0')
        print("half-res R(c)=%.9f" % best_cR)
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        print("lifted R=%.9f" % r_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 400, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            print("lift+ladder R=%.9f (best %.9f)" % (r, bestR))

    # ---- Phase 2: clean quotient-extract -> polish -> lift -> ladder cycles ----
    cycle = 0
    accepted_cycles = 0
    while cycle < 5 and time.process_time() < deadline - 6.0:
        cycle += 1
        c = best[0::2].copy()
        if c.size == 0 or c.sum() <= 0:
            break
        now = time.process_time()
        slice_dl = min(deadline - 4.0, now + 0.22 * (deadline - now))
        cc = _full_polish(c, slice_dl, pads=(0.15, 0.08))
        rc = R_of(cc)
        h_lift = _rescale(np.repeat(cc, 2))
        hl = _lbfgs_all_pos(h_lift, 400, slice_dl, beta=1e6)
        hl = _lbfgs_all_pos(hl, 400, min(deadline - 1.5, slice_dl + 3.0), beta=1e7)
        rl = R_of(hl)
        accepted = rl > bestR + 1e-13
        if accepted:
            best, bestR, origin = hl.copy(), rl, 'cycle%d' % cycle
            accepted_cycles += 1
            print("cycle %d R(c)=%.9f R(hl)=%.9f ACCEPT NEW BEST R=%.9f"
                  % (cycle, rc, rl, bestR))
        else:
            if rl > alt_bestR:
                alt_best, alt_bestR = hl.copy(), rl
            print("cycle %d R(c)=%.9f R(hl)=%.9f no gain (best %.9f)"
                  % (cycle, rc, rl, bestR))

    # ---- Phase 3: peak polish + trailing beta=0 ----
    if time.process_time() < deadline - 2.0:
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pk'
            print("peak polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 1.0:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+all0'
                print("trailing all0 NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    print("cycles=%d accepted=%d best_full=%.9f" %
          (cycle, accepted_cycles, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


