    # ---- Phase 1: just take start (cap 0.10*budget, effectively nothing) ----
    # (h0 = _rescale(start) already done above as best)

    # ---- Phase 1b: chained projection: fold by 4, polish, lift by 4 ----
    N = best.size
    if N % 4 == 0 and N >= 8 and time.process_time() < deadline - 4.0:
        q4 = best[0::4].copy()
        q4R = R_of(q4)
        print("q4 R=%.9f (n=%d)" % (q4R, q4.size))
        slice_dl = t0 + budget_seconds * 0.30
        q4w = q4
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= slice_dl - 0.5:
                break
            q4w = _lbfgs_all_pos(q4w, 300, slice_dl - 0.3, beta=beta)
        if time.process_time() < slice_dl - 0.5:
            win = _peak_window(q4w, pad_frac=0.15, extra=128)
            q4w = _lbfgs_block(q4w, win, 400, slice_dl - 0.3, beta=1e7)
        q4R2 = R_of(q4w)
        print("q4 polished R=%.9f" % q4R2)

        h_lift4 = _rescale(np.repeat(q4w, 4))
        lift_dl = t0 + budget_seconds * 0.55
        for beta in [1e6, 1e7]:
            if time.process_time() >= lift_dl - 0.5:
                break
            h_lift4 = _lbfgs_all_pos(h_lift4, 400, lift_dl - 0.3, beta=beta)
        r_lift4 = R_of(h_lift4)
        print("lift4 R=%.9f" % r_lift4)
        if r_lift4 > bestR + 1e-14:
            best, bestR, origin = h_lift4.copy(), r_lift4, 'lift4'
            print("lift4 NEW BEST R=%.9f" % bestR)
        else:
            if r_lift4 > alt_bestR:
                alt_best, alt_bestR = h_lift4.copy(), r_lift4
            print("lift4 no gain (best %.9f)" % bestR)

    # ---- Phase 2: p1338's clean half-cycle, up to 3 times ----
    cycle = 0
    accepted_cycles = 0
    while cycle < 3 and time.process_time() < deadline - 6.0:
        cycle += 1
        if best.size % 2 != 0:
            break
        c = best[0::2].copy()
        slice_dl = min(deadline - 3.0, time.process_time() + 8.0)
        cc = _full_polish(c, slice_dl, pads=(0.15, 0.08))
        rc = R_of(cc)
        h_lift = _rescale(np.repeat(cc, 2))
        hl = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            hl = _lbfgs_all_pos(hl, 400, deadline - 1.5, beta=beta)
        rl = R_of(hl)
        if rl > bestR + 1e-13:
            best, bestR, origin = hl.copy(), rl, 'cycle%d' % cycle
            accepted_cycles += 1
            print("half-cycle %d R(c)=%.9f R(hl)=%.9f ACCEPT NEW BEST R=%.9f"
                  % (cycle, rc, rl, bestR))
        else:
            if rl > alt_bestR:
                alt_best, alt_bestR = hl.copy(), rl
            print("half-cycle %d R(c)=%.9f R(hl)=%.9f no gain (best %.9f)"
                  % (cycle, rc, rl, bestR))

    # ---- Phase 3: peak polish + trailing beta=0 ----
    if time.process_time() < deadline - 2.0:
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pk'
            print("peak polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 1.0:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+all0'
                print("trailing all0 NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    print("cycles=%d accepted=%d best_full=%.9f" %
          (cycle, accepted_cycles, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _detect_period(h):
    """Return (r2, c2, r4, c4)."""
    N = h.size
    c2 = c4 = None
    r2 = r4 = 1.0
    if N % 2 == 0 and N >= 4:
        c2 = h[0::2].copy()
        if c2.size >= 2:
            r2 = float(np.max(np.abs(c2[0::2] - c2[1::2])))
    if c2 is not None and c2.size % 2 == 0 and c2.size >= 4:
        c4 = c2[0::2].copy()
        if c4.size >= 2:
            r4 = float(np.max(np.abs(c4[0::2] - c4[1::2])))
    return r2, c2, r4, c4


def _lift_and_polish(c, deadline, betas=(1e6, 1e7)):
    h = _rescale(np.repeat(c, 2))
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        h = _lbfgs_all_pos(h, 300, deadline - 0.5, beta=beta)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    N = best.size
    h0 = best.copy()

    r2, c2, r4, c4 = _detect_period(h0)
    print("periodicity r2=%.3e r4=%.3e (N=%d, c2=%s, c4=%s)" %
          (r2, r4, N,
           c2.size if c2 is not None else -1,
           c4.size if c4 is not None else -1))

    use_quarter = (c4 is not None and r4 < 1e-9 and c4.size >= 4096)

    if use_quarter:
        branch = 'quarter'
        print("branch=quarter (r4~0, c4.size=%d)" % c4.size)
        quarter_deadline = t0 + budget_seconds * 0.62
        work_c = c4.copy()
        best_c = c4.copy()
        best_cR = R_of(c4)
        rounds = 0
        while time.process_time() < quarter_deadline - 1.0:
            work_c, best_c, best_cR, org = _cycle(
                work_c, best_cR, quarter_deadline, tag='q%d' % rounds)
            rounds += 1
            if time.process_time() >= quarter_deadline - 1.0:
                break
        print("quarter rounds=%d R(c4)=%.9f" % (rounds, best_cR))

        # lift c4 -> c2
        mid_deadline = t0 + budget_seconds * 0.80
        c2_lift = _lift_and_polish(best_c, mid_deadline)
        c2_liftR = R_of(c2_lift)
        print("lift c4->c2 R=%.9f" % c2_liftR)

        # lift to full
        h_full = _lift_and_polish(c2_lift, deadline - 0.5)
        r_full = R_of(h_full)
        if r_full > bestR + 1e-14:
            best, bestR, origin = h_full.copy(), r_full, 'quarter+lift'
            print("quarter+lift NEW BEST R=%.9f" % bestR)
        else:
            if r_full > alt_bestR:
                alt_best, alt_bestR = h_full.copy(), r_full
            print("quarter+lift R=%.9f (best %.9f)" % (r_full, bestR))

    else:
        branch = 'half'
        print("branch=half (r4=%.3e)" % r4)
        half_deadline = t0 + budget_seconds * 0.72
        if c2 is not None and c2.size >= 4:
            work_c = c2.copy()
            best_c = c2.copy()
            best_cR = R_of(c2)
            rounds = 0
            while time.process_time() < half_deadline - 1.0:
                work_c, best_c, best_cR, org = _cycle(
                    work_c, best_cR, half_deadline, tag='h%d' % rounds)
                rounds += 1
                if time.process_time() >= half_deadline - 1.0:
                    break
            print("half rounds=%d R(c2)=%.9f" % (rounds, best_cR))

            # lift to full
            h_lift = _lift_and_polish(best_c, deadline - 0.5)
            r = R_of(h_lift)
            if r > bestR + 1e-14:
                best, bestR, origin = h_lift.copy(), r, 'half+lift'
                print("half+lift NEW BEST R=%.9f" % bestR)
            else:
                if r > alt_bestR:
                    alt_best, alt_bestR = h_lift.copy(), r
                print("half+lift R=%.9f (best %.9f)" % (r, bestR))

            # final polish on full resolution: full L-BFGS + sharp pads
            if time.process_time() < deadline - 0.6:
                work = best.copy()
                curR = bestR
                # one more full-resolution all-pos beta ladder
                for beta in [1e6, 1e7]:
                    if time.process_time() >= deadline - 0.6:
                        break
                    ht = _lbfgs_all_pos(work, 300, deadline - 0.4, beta=beta)
                    rr = R_of(ht)
                    if rr > curR + 1e-14:
                        work, curR = ht.copy(), rr
                # sharp pads on full resolution
                for pad in [0.08, 0.05, 0.04]:
                    if time.process_time() >= deadline - 0.6:
                        break
                    win = _peak_window(work, pad_frac=pad, extra=128)
                    ht = _lbfgs_block(work, win, 400, deadline - 0.4, beta=1e7)
                    rr = R_of(ht)
                    if rr > curR + 1e-14:
                        work, curR = ht.copy(), rr
                if curR > bestR + 1e-14:
                    best, bestR, origin = work.copy(), curR, 'half+lift+final'
                    print("half+lift+final NEW BEST R=%.9f" % bestR)
                elif curR > alt_bestR:
                    alt_best, alt_bestR = work.copy(), curR

    print("final R=%.9f origin=%s branch=%s r2=%.3e r4=%.3e (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, branch, r2, r4, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

