def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    """Alternation on the half-resolution quotient c."""
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _full_polish(h, slice_deadline, pads=(0.30, 0.15, 0.08)):
    """Beta ladder + peak pads + trailing beta=0, all bounded by slice_deadline."""
    ht = h
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= slice_deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
    for pad in pads:
        if time.process_time() >= slice_deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pad, extra=128)
        ht = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
    if time.process_time() < slice_deadline - 0.5:
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=0.0)
    return ht


def _interlace_quotient(c):
    """Upsample c to length 2m: even slots = c, odd slots = 0.25*(left+right)."""
    m = c.size
    c2 = np.zeros(2 * m, dtype=float)
    c2[0::2] = c
    left = np.concatenate(([0.0], c[:-1]))
    right = np.concatenate((c[1:], [0.0]))
    c2[1::2] = 0.25 * (left + right)
    return _rescale(c2)


def _fold_quotient(c2):
    """Downsample c2 (length 2m) back to length m by averaging pairs."""
    m = c2.size // 2
    return 0.5 * (c2[0:2 * m:2] + c2[1:2 * m:2])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: single half-resolution cycle, lift, ladder ----
    N = best.size
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        h0 = best.copy()
        c = h0[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.12
        work_c, best_c, best_cR, org = _half_cycle(
            c, cR, half_deadline, tag='h0')
        print("half-res R(c)=%.9f" % best_cR)
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        print("lifted R=%.9f" % r_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 400, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            print("lift+ladder R=%.9f (best %.9f)" % (r, bestR))

    # ---- Phase 2: quotient-interlace -> fold -> polish -> lift cycles ----
    cycle = 0
    accepted_cycles = 0
    while cycle < 3 and time.process_time() < deadline - 6.0:
        cycle += 1
        c = best[0::2].copy()
        if c.size == 0 or c.sum() <= 0:
            break
        now = time.process_time()
        slice_dl = min(deadline - 5.0, now + 0.15 * budget_seconds)

        # Interlace quotient to double resolution, polish there.
        c2 = _interlace_quotient(c)
        c2p = _full_polish(c2, slice_dl, pads=(0.15, 0.08))
        # Fold back to quotient resolution.
        c1 = _rescale(_fold_quotient(c2p))
        rc0 = R_of(c)
        rc1 = R_of(c1)
        # Short polish of folded quotient.
        if time.process_time() < slice_dl - 0.5:
            c1p = _lbfgs_all_pos(c1, 200, slice_dl - 0.3, beta=1e7)
            rc1p = R_of(c1p)
            if rc1p > rc1:
                c1, rc1 = c1p, rc1p
        # Replace c if folded quotient improved.
        if rc1 > rc0:
            c_use = c1
        else:
            c_use = c

        # Lift best quotient to full N and polish.
        h_lift = _rescale(np.repeat(c_use, 2))
        hl = _lbfgs_all_pos(h_lift, 400, min(deadline - 1.5, slice_dl + 3.0),
                            beta=1e6)
        hl = _lbfgs_all_pos(hl, 400, min(deadline - 1.5, slice_dl + 5.0),
                            beta=1e7)
        rl = R_of(hl)
        accepted = rl > bestR + 1e-13
        if accepted:
            best, bestR, origin = hl.copy(), rl, 'qcycle%d' % cycle
            accepted_cycles += 1
            print("qcycle %d R(c)=%.9f R(c1)=%.9f R(hl)=%.9f ACCEPT NEW BEST R=%.9f"
                  % (cycle, rc0, rc1, rl, bestR))
        else:
            if rl > alt_bestR:
                alt_best, alt_bestR = hl.copy(), rl
            print("qcycle %d R(c)=%.9f R(c1)=%.9f R(hl)=%.9f no gain (best %.9f)"
                  % (cycle, rc0, rc1, rl, bestR))

    # ---- Phase 3: peak polish + trailing beta=0 ----
    if time.process_time() < deadline - 2.0:
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pk'
            print("peak polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 1.0:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+all0'
                print("trailing all0 NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    print("cycles=%d accepted=%d best_full=%.9f" %
          (cycle, accepted_cycles, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _zero_frac(h):
    return float(np.mean(h == 0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Short baseline smoothing passes on the full array (cheap, warms up).
    base_deadline = deadline - 40.0
    if time.process_time() < base_deadline - 0.5:
        work = best.copy()
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= base_deadline - 0.3:
                break
            ht = _lbfgs_all_pos(work, 200, base_deadline - 0.2, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "basebeta%g" % beta
        print("baseline: R=%.9f origin=%s" % (bestR, origin))

    rng = np.random.default_rng(20240607)
    lo = np.log(1e-3)
    hi = np.log(5e-2)
    pads = [0.40, 0.30, 0.22, 0.16, 0.12, 0.09, 0.07, 0.05]
    n_trials = 0
    n_accept = 0

    # New idea: alternating (a) localized peak-window L-BFGS with a range of
    # pads, and (b) full-array all-positive L-BFGS with a soft-max beta, each
    # seeded from the current best. Accept strictly-improving steps; keep a
    # diverse alternative from the best rejected candidate.
    while time.process_time() < deadline - 2.0:
        use_full = (n_trials % 4 == 3)
        if use_full:
            amp = float(np.exp(rng.uniform(lo, hi)))
            seed = _random_perturb(best, rng, amp) if n_trials % 8 == 7 else best.copy()
            beta = [1e6, 1e7, 1e8][n_trials % 3]
            ht = _lbfgs_all_pos(seed, 200, deadline - 0.8, beta=beta)
            tag = "full_b%.0e_a%.4f" % (beta, amp)
        else:
            amp = float(np.exp(rng.uniform(lo, hi)))
            seed = _random_perturb(best, rng, amp) if amp > 5e-3 else best.copy()
            pad = pads[n_trials % len(pads)]
            win = _peak_window(seed, pad_frac=pad, extra=128)
            ht = _lbfgs_block(seed, win, 250, deadline - 0.8, beta=1e7)
            # Periodic exact (beta=0) polish of the same window.
            if n_trials % 5 == 2 and time.process_time() < deadline - 1.2:
                ht2 = _lbfgs_block(ht, win, 120, deadline - 0.8, beta=0.0)
                r2 = R_of(ht2)
                if r2 > R_of(ht):
                    ht = ht2
            tag = "win_p%.2f_a%.4f" % (pad, amp)
        r = R_of(ht)
        n_trials += 1
        if r > bestR + 1e-12:
            best, bestR = ht.copy(), r
            n_accept += 1
            origin = "t%d_%s" % (n_trials, tag)
            print("trial %d %s R=%.9f NEW BEST" % (n_trials, tag, r))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if n_trials % 5 == 0:
                print("trial %d %s R=%.9f (best %.9f)" %
                      (n_trials, tag, r, bestR))

    # Final polish: exact-objective full pass, then a wide peak window.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + "+finalall0"
    if time.process_time() < deadline - 0.6:
        win = _peak_window(best, pad_frac=0.20, extra=192)
        ht = _lbfgs_block(best, win, 300, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + "+finalwin"

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))
    print("n_trials=%d n_accept=%d" % (n_trials, n_accept))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _zero_frac(h):
    return float(np.mean(h == 0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Short baseline smoothing passes on the full array (cheap, warms up).
    base_deadline = deadline - 40.0
    if time.process_time() < base_deadline - 0.5:
        work = best.copy()
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= base_deadline - 0.3:
                break
            ht = _lbfgs_all_pos(work, 200, base_deadline - 0.2, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "basebeta%g" % beta
        print("baseline: R=%.9f origin=%s" % (bestR, origin))

    rng = np.random.default_rng(20240607)
    lo = np.log(1e-3)
    hi = np.log(5e-2)
    pads = [0.40, 0.30, 0.22, 0.16, 0.12, 0.09, 0.07, 0.05]
    n_trials = 0
    n_accept = 0

    # New idea: alternating (a) localized peak-window L-BFGS with a range of
    # pads, and (b) full-array all-positive L-BFGS with a soft-max beta, each
    # seeded from the current best. Accept strictly-improving steps; keep a
    # diverse alternative from the best rejected candidate.
    while time.process_time() < deadline - 2.0:
        use_full = (n_trials % 4 == 3)
        if use_full:
            amp = float(np.exp(rng.uniform(lo, hi)))
            seed = _random_perturb(best, rng, amp) if n_trials % 8 == 7 else best.copy()
            beta = [1e6, 1e7, 1e8][n_trials % 3]
            ht = _lbfgs_all_pos(seed, 200, deadline - 0.8, beta=beta)
            tag = "full_b%.0e_a%.4f" % (beta, amp)
        else:
            amp = float(np.exp(rng.uniform(lo, hi)))
            seed = _random_perturb(best, rng, amp) if amp > 5e-3 else best.copy()
            pad = pads[n_trials % len(pads)]
            win = _peak_window(seed, pad_frac=pad, extra=128)
            ht = _lbfgs_block(seed, win, 250, deadline - 0.8, beta=1e7)
            # Periodic exact (beta=0) polish of the same window.
            if n_trials % 5 == 2 and time.process_time() < deadline - 1.2:
                ht2 = _lbfgs_block(ht, win, 120, deadline - 0.8, beta=0.0)
                r2 = R_of(ht2)
                if r2 > R_of(ht):
                    ht = ht2
            tag = "win_p%.2f_a%.4f" % (pad, amp)
        r = R_of(ht)
        n_trials += 1
        if r > bestR + 1e-12:
            best, bestR = ht.copy(), r
            n_accept += 1
            origin = "t%d_%s" % (n_trials, tag)
            print("trial %d %s R=%.9f NEW BEST" % (n_trials, tag, r))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if n_trials % 5 == 0:
                print("trial %d %s R=%.9f (best %.9f)" %
                      (n_trials, tag, r, bestR))

    # Final polish: exact-objective full pass, then a wide peak window.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + "+finalall0"
    if time.process_time() < deadline - 0.6:
        win = _peak_window(best, pad_frac=0.20, extra=192)
        ht = _lbfgs_block(best, win, 300, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + "+finalwin"

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))
    print("n_trials=%d n_accept=%d" % (n_trials, n_accept))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

