            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if r > bestR - 1e-5:
                variant_hits[k] = max(variant_hits[k], r)
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: reserve last ~5s for peak-window + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 3j (NEW): index-space block jitter with zero-fill + re-prune ----
    jit_start = t0 + budget_seconds * 0.40
    jit_end = deadline - 6.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < jit_end - 1.0 and best.size >= 8:
        rng = np.random.RandomState(135792468)
        sigmas = [0.004, 0.015, 0.05]
        epss = [3e-3, 1e-2]
        thrs = [1e-4, 1e-3, 3e-3]
        rnd = 0
        accepted = 0
        Ncur = best.size
        Bopts = [max(8, Ncur // 200), max(8, Ncur // 60), max(8, Ncur // 20)]
        while time.process_time() < jit_end - 1.0:
            sigma = sigmas[rnd % len(sigmas)]
            eps = epss[(rnd // len(sigmas)) % len(epss)]
            thr = thrs[rnd % len(thrs)]
            B = Bopts[(rnd // (len(sigmas) * len(epss))) % len(Bopts)]
            rnd += 1
            nz = np.flatnonzero(best > 0)
            if nz.size < 4:
                break
            mean_act = best[nz].mean()
            if Ncur <= B:
                s0 = 0
                Bc = Ncur
            else:
                s0 = rng.randint(0, Ncur - B + 1)
                Bc = B
            now = time.process_time()
            slice_dl = min(now + 2.0, deadline - 6.0)
            if slice_dl <= now + 0.4:
                break
            cand = best.copy()
            blk = cand[s0:s0 + Bc]
            blk = blk * np.exp(sigma * rng.randn(Bc))
            z = (blk == 0)
            if np.any(z):
                blk[z] = eps * mean_act
            cand[s0:s0 + Bc] = blk
            cand = _rescale(np.clip(cand, 0, None))
            win = _peak_window(cand, pad_frac=0.05, extra=128)
            cand = _lbfgs_block(cand, win, 200, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                cand = _lbfgs_all_pos(cand, 200, slice_dl, beta=0.0)
            # re-prune
            mx = cand.max()
            if mx > 0:
                cand[cand < thr * mx] = 0.0
            cand = _rescale(np.clip(cand, 0, None))
            if time.process_time() < slice_dl - 0.4:
                cand = _lbfgs_all_pos(cand, 150, slice_dl, beta=1e7)
            r2 = R_of(cand)
            zf = float(np.mean(cand == 0))
            print("blockjit rnd %d B=%d sigma=%.4g eps=%.3g thr=%.3g zf=%.4f R=%.9f (best %.9f)"
                  % (rnd, Bc, sigma, eps, thr, zf, r2, bestR))
            if r2 > bestR + 1e-13 and 0.62 <= zf <= 0.72:
                best, bestR = cand.copy(), r2
                origin = 'blockjit_r%d' % rnd
                accepted += 1
                print("  blockjit NEW BEST R=%.9f zf=%.4f (B=%d sigma=%.4g thr=%.3g)"
                      % (bestR, zf, Bc, sigma, thr))
            elif r2 > alt_bestR:
                alt_best, alt_bestR = cand.copy(), r2
        print("blockjit done rounds=%d accepted=%d bestR=%.9f" %
              (rnd, accepted, bestR))

    # ---- Phase 4: final peak pads + beta=0 ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _lift4(q, N, rng, sigma=0.02):
    """Lift a stride-4 quotient with randomized per-block weights."""
    m = q.size
    h = np.repeat(q, 4)
    if h.size < N:
        h = np.concatenate((h, np.full(N - h.size, h[-1])))
    h = h[:N]
    nb = N // 4
    w = np.exp(sigma * rng.randn(nb))
    w = w / w.mean()
    h = h * np.repeat(w, 4)[:N]
    return _rescale(np.clip(h, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if r > bestR - 1e-5:
                variant_hits[k] = max(variant_hits[k], r)
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: reserve last ~5s for peak-window + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 3q (NEW): stride-4 quotient jitter + randomized lift ----
    jit_start = t0 + budget_seconds * 0.38
    jit_end = deadline - 6.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < jit_end - 1.0 and best.size >= 16:
        rng = np.random.RandomState(246813579)
        sigmas = [0.002, 0.006, 0.02]
        rnd = 0
        q_improved = 0
        lift_hits = 0
        while time.process_time() < jit_end - 1.0:
            Nc = best.size
            if Nc % 4 != 0:
                break
            q = best.reshape(-1, 4).mean(axis=1)
            q = _rescale(q)
            qR = R_of(q)
            nzq = np.flatnonzero(q > 0)
            if nzq.size < 4:
                break
            # 3-5 jitter rounds at quotient scale
            nrounds = 3 + (rnd % 3)
            q_work = q.copy()
            q_workR = qR
            for rr in range(nrounds):
                sigma = sigmas[(rnd + rr) % len(sigmas)]
                Bs = [max(4, nzq.size // 50),
                      max(4, nzq.size // 10),
                      max(4, nzq.size // 3)]
                B = Bs[(rnd + rr) % len(Bs)]
                if nzq.size <= B:
                    sel = nzq
                else:
                    st = rng.randint(0, nzq.size - B + 1)
                    sel = nzq[st:st + B]
                now = time.process_time()
                slice_dl = min(now + 4.0, deadline - 6.0)
                if slice_dl <= now + 0.4:
                    break
                qc = q_work.copy()
                qc[sel] = qc[sel] * np.exp(sigma * rng.randn(sel.size))
                qc = _rescale(np.clip(qc, 0, None))
                qc = _lbfgs_all_pos(qc, 250, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    qc = _lbfgs_all_pos(qc, 250, slice_dl, beta=0.0)
                qcR = R_of(qc)
                if qcR > q_workR + 1e-14:
                    q_work = qc
                    q_workR = qcR
            rnd += 1
            if q_workR > qR + 1e-14:
                q_improved += 1
            print("qjit rnd %d qR=%.9f -> %.9f (best %.9f)" %
                  (rnd, qR, q_workR, bestR))
            # lift with randomized 4-way split
            now = time.process_time()
            slice_dl = min(now + 4.0, deadline - 6.0)
            if slice_dl <= now + 0.4:
                break
            h = _lift4(q_work, Nc, rng, sigma=0.02)
            h = _lbfgs_block(h, _peak_window(h, pad_frac=0.06, extra=128),
                             250, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                h = _lbfgs_all_pos(h, 250, slice_dl, beta=0.0)
            r = R_of(h)
            print("  lift R=%.9f (best %.9f)" % (r, bestR))
            if r > bestR + 1e-13:
                best, bestR = h.copy(), r
                origin = 'qjit_r%d' % rnd
                lift_hits += 1
                print("  qjit NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = h.copy(), r
        print("qjit done rounds=%d q_improved=%d lift_hits=%d bestR=%.9f" %
              (rnd, q_improved, lift_hits, bestR))

    # ---- Phase 4: final peak pads + beta=0 ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, bestR, deadline, pads=(0.10, 0.06, 0.04)):
    best = h.copy()
    for pad in pads:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        if time.process_time() < deadline - 0.8:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2.copy(), r2
    return best, bestR


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
    return work, best, bestR


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _dilate(h):
    """Insert one zero between each pair of steps: N -> 2N-1."""
    n = h.size
    out = np.zeros(2 * n - 1)
    out[0::2] = h
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 0: DILATION search ----
    # Insert zeros between steps: creates a genuinely different fine structure
    # that local L-BFGS on the original grid cannot reach easily.
    if best.size >= 4 and time.process_time() < deadline - 8.0:
        hd = _dilate(best)
        hdR = R_of(hd)
        print("dilated R=%.9f (N=%d)" % (hdR, hd.size))
        # optimize the dilated version in a peak window first
        dil_end = t0 + budget_seconds * 0.30
        hdwork = hd.copy()
        hdbest = hd.copy()
        hdbestR = hdR
        for beta in [1e6, 1e7]:
            if time.process_time() >= dil_end - 0.5:
                break
            ht = _lbfgs_all_pos(hdwork, 300, dil_end - 0.3, beta=beta)
            r = R_of(ht)
            if r > hdbestR + 1e-14:
                hdwork, hdbest, hdbestR = ht, ht.copy(), r
        # peak-window polish
        for pad in [0.15, 0.10, 0.06]:
            if time.process_time() >= dil_end - 0.5:
                break
            win = _peak_window(hdbest, pad_frac=pad, extra=256)
            ht = _lbfgs_block(hdbest, win, 300, dil_end - 0.3, beta=1e7)
            r = R_of(ht)
            if r > hdbestR + 1e-14:
                hdwork, hdbest, hdbestR = ht, ht.copy(), r
        print("dilated best R=%.9f" % hdbestR)
        if hdbestR > bestR + 1e-14:
            best, bestR, origin = hdbest.copy(), hdbestR, 'dilate'
            print("  DILATE NEW BEST R=%.9f" % bestR)
        elif hdbestR > alt_bestR:
            alt_best, alt_bestR = hdbest.copy(), hdbestR

    # ---- Phase 1: half-resolution quotient search ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.45
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 6.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 5.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception:
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception:
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: structural edits (split/merge) with wider candidate set ----
    struct_end = deadline - 4.0
    if time.process_time() < struct_end - 1.0 and best.size >= 4:
        Ns = best.size
        rng = np.random.RandomState(987654)
        trial = 0
        accepted = 0
        while time.process_time() < struct_end - 1.0:
            act = np.flatnonzero(best > 0.02 * best.max())
            if act.size == 0:
                break
            perm = rng.permutation(act)
            progressed = False
            for i in perm:
                i = int(i)
                if time.process_time() >= struct_end - 1.0:
                    break
                now = time.process_time()
                slice_dl = min(now + 1.4, deadline - 4.0)
                if slice_dl <= now + 0.3:
                    break
                trial += 1
                cands = []
                v = best[i]
                if v > 0:
                    for d in (-1, +1, -2, +2):
                        j = i + d
                        if 0 <= j < Ns and best[j] <= 0:
                            h2 = best.copy()
                            h2[i] = 0.0
                            h2[j] = h2[j] + v
                            cands.append(('move%d' % d, h2))
                            break
                if i + 1 < Ns:
                    h2 = best.copy()
                    half = 0.5 * best[i]
                    h2[i] = half
                    h2[i + 1] = h2[i + 1] + half
                    cands.append(('split', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    a = best[i] * (1.0 / 3.0)
                    h2[i] = a
                    h2[i + 1] = h2[i + 1] + (best[i] - a)
                    cands.append(('split2', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    h2[i] = h2[i] + h2[i + 1]
                    h2[i + 1] = 0.0
                    cands.append(('merge', h2))
                best_local = None
                best_localR = -1.0
                best_type = None
                for typ, h2 in cands:
                    if time.process_time() >= slice_dl - 0.3:
                        break
                    h2 = _rescale(np.clip(h2, 0, None))
                    win = _peak_window(h2, pad_frac=0.15, extra=384)
                    h2 = _lbfgs_block(h2, win, 120, slice_dl, beta=1e6)
                    if time.process_time() < slice_dl - 0.3:
                        h2 = _lbfgs_all_pos(h2, 120, slice_dl, beta=1e7)
                    r2 = R_of(h2)
                    if r2 > best_localR:
                        best_local, best_localR, best_type = h2, r2, typ
                if best_local is None:
                    continue
                progressed = True
                if best_localR > bestR + 1e-13:
                    best, bestR = best_local.copy(), best_localR
                    origin = 'struct_%s' % best_type
                    accepted += 1
                    print("struct trial %d %s at i=%d (frac %.3f) NEW BEST R=%.9f" %
                          (trial, best_type, i, i / float(Ns), bestR))
                elif best_localR > alt_bestR:
                    alt_best, alt_bestR = best_local.copy(), best_localR
            if not progressed:
                break
        print("struct edits done trials=%d accepted=%d bestR=%.9f" %
              (trial, accepted, bestR))

    # ---- Phase 4: final polish ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish(best, bestR, deadline)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _upsample_interp(h, factor):
    """Smooth upsample via linear interpolation between step midpoints."""
    n = h.size
    M = factor * n
    # positions of new samples in old index space
    x = (np.arange(M) + 0.5) / factor - 0.5
    x = np.clip(x, 0.0, n - 1)
    i0 = np.floor(x).astype(int)
    i1 = np.minimum(i0 + 1, n - 1)
    t = x - i0
    return (1.0 - t) * h[i0] + t * h[i1]


def _fold(h, factor):
    n = h.size // factor
    h = h[:n * factor]
    return h.reshape(n, factor).mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.20
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: interlaced 2x upsample polish ----
    # (replaces the 4x scheme: 2x keeps cost manageable while still smoothing)
    p2_start = t0 + budget_seconds * 0.22
    p2_end = t0 + budget_seconds * 0.55
    while time.process_time() < p2_start:
        time.sleep(0.01)
    if time.process_time() < p2_end - 2.0 and best.size >= 2:
        n = best.size
        try:
            u = _upsample_interp(best, 2)
            u = _rescale(u)
            r_pre = R_of(u)
            print("2N pre-polish R=%.9f (best %.9f)" % (r_pre, bestR))
            slice_dl = min(p2_end, deadline - 6.0)
            if slice_dl > time.process_time() + 1.0:
                for beta in [1e5, 1e6, 1e7]:
                    if time.process_time() >= slice_dl - 0.5:
                        break
                    u = _lbfgs_all_pos(u, 300, slice_dl - 0.3, beta=beta)
                if time.process_time() < slice_dl - 0.5:
                    win = _peak_window(u, pad_frac=0.08, extra=256)
                    u = _lbfgs_block(u, win, 400, slice_dl - 0.3, beta=1e7)
            r_post = R_of(u)
            print("2N post-polish R=%.9f (delta %.3e)" % (r_post, r_post - r_pre))
            h2 = _fold(u, 2)
            h2 = _rescale(h2)[:n]
            r_fold0 = R_of(h2)
            if time.process_time() < slice_dl - 0.5:
                h2 = _lbfgs_all_pos(h2, 300, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.5:
                h2 = _lbfgs_all_pos(h2, 300, slice_dl - 0.3, beta=0.0)
            r_fold = R_of(h2)
            print("fold R=%.9f (pre-fold %.9f, entry %.9f, best %.9f)" %
                  (r_fold, r_fold0, r_pre, bestR))
            if r_fold > bestR + 1e-13:
                best, bestR, origin = h2.copy(), r_fold, '2x'
                print("2x fold NEW BEST R=%.9f" % bestR)
            elif r_fold > alt_bestR:
                alt_best, alt_bestR = h2.copy(), r_fold
        except Exception as e:
            print("phase2 exception %s" % e)

    # ---- Phase 3: variant rotation cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 4: final peak-window + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04, 0.03]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _polish(h, slice_dl, pad):
    win = _peak_window(h, pad_frac=pad, extra=128)
    h2 = _lbfgs_block(h, win, 250, slice_dl, beta=1e7)
    if time.process_time() < slice_dl - 0.4:
        h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=0.0)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if r > bestR - 1e-5:
                variant_hits[k] = max(variant_hits[k], r)
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: reserve last ~5s for peak-window + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 3j (NEW): round-robin portfolio of four mechanisms ----
    jit_start = t0 + budget_seconds * 0.38
    jit_end = deadline - 6.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < jit_end - 1.0 and best.size >= 8:
        rng = np.random.RandomState(987654321)
        sigmas = [0.003, 0.008, 0.02]
        pads_j = [0.06, 0.04, 0.03]
        Ks = [16, 32, 64]
        rnd = 0
        accepted = [0, 0, 0, 0]
        while time.process_time() < jit_end - 1.0:
            mech = rnd % 4
            rnd += 1
            now = time.process_time()
            slice_dl = min(now + 2.5, deadline - 6.0)
            if slice_dl <= now + 0.4:
                break
            cand = None
            try:
                if mech == 0:
                    nz = np.flatnonzero(best > 0)
                    if nz.size < 4:
                        break
                    sigma = sigmas[rnd % len(sigmas)]
                    Bs = [max(4, nz.size // 100), max(4, nz.size // 50)]
                    B = Bs[(rnd // len(sigmas)) % len(Bs)]
                    if nz.size <= B:
                        sel = nz
                    else:
                        st = rng.randint(0, nz.size - B + 1)
                        sel = nz[st:st + B]
                    h2 = best.copy()
                    mult = np.exp(sigma * rng.randn(sel.size))
                    h2[sel] = h2[sel] * mult
                    cand = _rescale(np.clip(h2, 0, None))
                elif mech == 1:
                    h2 = best.copy()
                    zeros = np.flatnonzero(h2 <= 0)
                    act = h2[h2 > 0]
                    if zeros.size > 0 and act.size > 0:
                        h2[zeros] = 1e-3 * act.mean()
                    cand = _rescale(h2)
                    for beta in [1e5, 1e6, 1e7]:
                        if time.process_time() >= slice_dl - 0.5:
                            break
                        cand = _lbfgs_all_pos(cand, 200, slice_dl - 0.3, beta=beta)
                elif mech == 2:
                    nz = np.flatnonzero(best > 0)
                    if nz.size < 2:
                        continue
                    K = Ks[(rnd // 4) % len(Ks)]
                    side = (rnd // 12) % 2
                    h2 = best.copy()
                    if side == 0:
                        lo = nz[0]
                        if lo >= 2:
                            slope = h2[lo + 1] - h2[lo]
                            kk = min(K, lo)
                            for j in range(1, kk + 1):
                                v = h2[lo] - slope * j
                                h2[lo - j] = max(0.0, v)
                    else:
                        hi = nz[-1]
                        if hi <= h2.size - 3:
                            slope = h2[hi] - h2[hi - 1]
                            kk = min(K, h2.size - 1 - hi)
                            for j in range(1, kk + 1):
                                v = h2[hi] + slope * j
                                h2[hi + j] = max(0.0, v)
                    cand = _rescale(h2)
                else:
                    h2 = best.copy()
                    act = np.flatnonzero(h2 > 0)
                    if act.size < 2:
                        continue
                    mx = h2.max()
                    big = act[h2[act] > 0.02 * mx]
                    if big.size == 0:
                        big = act
                    i = int(big[rng.randint(big.size)])
                    op = rng.randint(4)
                    if op == 0:
                        d = 1 if rng.rand() < 0.5 else -1
                        j = i + d
                        if 0 <= j < h2.size:
                            h2[j] += h2[i]
                            h2[i] = 0.0
                    elif op == 1:
                        d = 2 if rng.rand() < 0.5 else -2
                        j = i + d
                        if 0 <= j < h2.size:
                            h2[j] += h2[i]
                            h2[i] = 0.0
                    elif op == 2:
                        v = h2[i]
                        h2[i] = v / 3.0
                        for d in (-1, 1):
                            j = i + d
                            if 0 <= j < h2.size:
                                h2[j] += v / 3.0
                    else:
                        nb = i - 1 if (i > 0 and (i == h2.size - 1 or rng.rand() < 0.5)) else i + 1
                        if 0 <= nb < h2.size:
                            h2[nb] += h2[i]
                            h2[i] = 0.0
                    cand = _rescale(np.clip(h2, 0, None))
            except Exception as e:
                print("round %d mech %d exception %s" % (rnd, mech, e))
                continue
            if cand is None:
                continue
            pad = pads_j[rnd % len(pads_j)]
            cand = _polish(cand, slice_dl, pad)
            r = R_of(cand)
            print("round %d mech %d R=%.9f (best %.9f)" % (rnd, mech, r, bestR))
            if r > bestR + 1e-13:
                best, bestR = cand.copy(), r
                origin = 'rr_m%d_r%d' % (mech, rnd)
                accepted[mech] += 1
                print("  round %d mech %d NEW BEST R=%.9f" % (rnd, mech, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = cand.copy(), r
        print("portfolio rounds=%d accepted=%s bestR=%.9f" %
              (rnd, accepted, bestR))

    # ---- Phase 4: final peak pads + beta=0 ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _fold_back(h3, N):
    F = np.concatenate(([0.0], np.cumsum(h3)))
    L = h3.size
    xs = np.linspace(0.0, L, N + 1)
    vals = np.interp(xs, np.arange(L + 1, dtype=float), F)
    out = np.diff(vals)
    return _rescale(np.clip(out, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if r > bestR - 1e-5:
                variant_hits[k] = max(variant_hits[k], r)
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: reserve last ~5s for peak-window + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 3j (NEW): non-commensurate 3:2 lift loop ----
    jit_start = t0 + budget_seconds * 0.35
    jit_end = deadline - 6.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < jit_end - 1.0 and best.size >= 8 and best.size % 2 == 0:
        rng = np.random.RandomState(24681357)
        Ncur = best.size
        mcur = Ncur // 2
        L3 = 3 * mcur
        for rnd in range(3):
            now = time.process_time()
            if now >= jit_end - 1.0:
                break
            slice_dl = min(now + 6.0, deadline - 6.0)
            if slice_dl <= now + 0.8:
                break
            c = best[0::2][:mcur].copy()
            if c.size < mcur:
                c = np.concatenate((c, np.full(mcur - c.size, c[-1])))
            w = np.exp(0.35 * rng.randn(mcur))
            w = w * (3.0 / w.sum())
            h3 = np.zeros(L3)
            h3[0::3] = c * w
            h3[1::3] = c * w
            h3[2::3] = c * w
            h3 = _rescale(h3)
            for beta in [1e5, 1e6, 1e7]:
                if time.process_time() >= slice_dl - 0.6:
                    break
                h3 = _lbfgs_all_pos(h3, 150, slice_dl - 0.3, beta=beta)
            if time.process_time() < slice_dl - 0.6:
                win = _peak_window(h3, pad_frac=0.05, extra=256)
                h3 = _lbfgs_block(h3, win, 200, slice_dl - 0.3, beta=1e7)
            rL = R_of(h3)
            folded = _fold_back(h3, Ncur)
            rfold = R_of(folded)
            if time.process_time() < slice_dl - 0.5:
                win = _peak_window(folded, pad_frac=0.05, extra=128)
                folded = _lbfgs_block(folded, win, 200, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.5:
                folded = _lbfgs_all_pos(folded, 200, slice_dl - 0.3, beta=0.0)
            r2 = R_of(folded)
            zf = float(np.mean(folded == 0))
            accepted = False
            if r2 > bestR + 1e-13 and 0.60 <= zf <= 0.74:
                best, bestR = folded.copy(), r2
                origin = 'nc3_2_r%d' % rnd
                accepted = True
                print("nc round %d R@L=%.9f foldedR=%.9f zf=%.4f ACCEPT best=%.9f"
                      % (rnd, rL, r2, zf, bestR))
            else:
                print("nc round %d R@L=%.9f foldedR=%.9f zf=%.4f reject (best %.9f)"
                      % (rnd, rL, r2, zf, bestR))
                if r2 > alt_bestR:
                    alt_best, alt_bestR = folded.copy(), r2

    # ---- Phase 4: final peak pads + beta=0 ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _zf(h):
    return float(np.mean(h == 0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if r > bestR - 1e-5:
                variant_hits[k] = max(variant_hits[k], r)
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: staged A/B/C chain (multi-attempt per stage) ----
    chain_start = t0 + budget_seconds * 0.35
    chain_end = deadline - 7.0
    if time.process_time() < chain_start:
        while time.process_time() < chain_start - 0.05:
            time.sleep(0.01)

    rng = np.random.RandomState(246813579)
    attempt = 0
    accepted_total = 0
    accepted_stages = set()

    def _try_accept(cand, stage, desc):
        nonlocal best, bestR, origin, alt_best, alt_bestR, accepted_total
        r2 = R_of(cand)
        zf = _zf(cand)
        acc = False
        if r2 > bestR + 1e-13:
            if stage in ('A', 'B'):
                if 0.60 <= zf <= 0.74:
                    acc = True
            else:
                acc = True
        if acc:
            best, bestR = cand.copy(), r2
            origin = '%s_%d' % (stage, attempt)
            accepted_total += 1
            accepted_stages.add(stage)
        elif r2 > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r2
        print("%s %s zf=%.4f R=%.9f %s (best %.9f)" %
              (stage, desc, zf, r2, "ACC" if acc else "---", bestR))
        return acc

    while time.process_time() < chain_end - 1.0:
        for stage in ('A', 'B', 'C'):
            now = time.process_time()
            slice_dl = min(now + 2.5, chain_end)
            if slice_dl <= now + 0.5:
                break
            attempt += 1
            Ncur = best.size
            try:
                if stage == 'A':
                    Bopts = [max(8, Ncur // 200), max(8, Ncur // 60),
                             max(8, Ncur // 20)]
                    B = Bopts[rng.randint(len(Bopts))]
                    sigma = [0.004, 0.015, 0.05][rng.randint(3)]
                    eps = [3e-3, 1e-2][rng.randint(2)]
                    thr = [1e-4, 1e-3, 3e-3][rng.randint(3)]
                    nz = np.flatnonzero(best > 0)
                    if nz.size < 4:
                        continue
                    mean_act = best[nz].mean()
                    if Ncur <= B:
                        s0, Bc = 0, Ncur
                    else:
                        s0 = rng.randint(0, Ncur - B + 1)
                        Bc = B
                    cand = best.copy()
                    blk = cand[s0:s0 + Bc] * np.exp(sigma * rng.randn(Bc))
                    z = (blk == 0)
                    if np.any(z):
                        blk[z] = eps * mean_act
                    cand[s0:s0 + Bc] = blk
                    cand = _rescale(np.clip(cand, 0, None))
                    win = _peak_window(cand, pad_frac=0.05, extra=128)
                    cand = _lbfgs_block(cand, win, 250, slice_dl, beta=1e7)
                    if time.process_time() < slice_dl - 0.4:
                        cand = _lbfgs_all_pos(cand, 200, slice_dl, beta=0.0)
                    mx = cand.max()
                    if mx > 0:
                        cand[cand < thr * mx] = 0.0
                    cand = _rescale(np.clip(cand, 0, None))
                    if time.process_time() < slice_dl - 0.4:
                        cand = _lbfgs_all_pos(cand, 150, slice_dl, beta=1e7)
                    _try_accept(cand, 'A', 'B=%d sig=%.3g eps=%.2g thr=%.1g'
                                % (Bc, sigma, eps, thr))
                elif stage == 'B':
                    h2 = np.zeros(2 * Ncur - 1)
                    h2[0::2] = best
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e6)
                    if time.process_time() < slice_dl - 0.4:
                        h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e7)
                    if time.process_time() < slice_dl - 0.4:
                        win = _peak_window(h2, pad_frac=0.06, extra=256)
                        h2 = _lbfgs_block(h2, win, 200, slice_dl, beta=1e7)
                    ev = h2[0::2]
                    od = h2[1::2]
                    L = min(ev.size, od.size)
                    new = 0.5 * (ev[:L] + od[:L])
                    if new.size < Ncur:
                        new = np.concatenate(
                            (new, np.full(Ncur - new.size, new[-1])))
                    cand = _rescale(np.clip(new[:Ncur], 0, None))
                    if time.process_time() < slice_dl - 0.4:
                        cand = _lbfgs_all_pos(cand, 150, slice_dl, beta=1e7)
                    if time.process_time() < slice_dl - 0.4:
                        cand = _lbfgs_all_pos(cand, 150, slice_dl, beta=0.0)
                    _try_accept(cand, 'B', 'dilate')
                else:
                    nz = np.flatnonzero(best > 0)
                    if nz.size < 8:
                        continue
                    Bopts = [max(4, nz.size // 100), max(4, nz.size // 50)]
                    B = Bopts[rng.randint(len(Bopts))]
                    sigma = [0.003, 0.008, 0.02][rng.randint(3)]
                    mean_act = best[nz].mean()
                    cand = best.copy()
                    if nz.size <= B:
                        idx = nz
                    else:
                        s0 = rng.randint(0, nz.size - B + 1)
                        idx = nz[s0:s0 + B]
                    blk = cand[idx] * np.exp(sigma * rng.randn(idx.size))
                    cand[idx] = blk
                    cand = _rescale(np.clip(cand, 0, None))
                    win = _peak_window(cand, pad_frac=0.05, extra=128)
                    cand = _lbfgs_block(cand, win, 250, slice_dl, beta=1e7)
                    if time.process_time() < slice_dl - 0.4:
                        cand = _lbfgs_all_pos(cand, 200, slice_dl, beta=0.0)
                    _try_accept(cand, 'C', 'B=%d sig=%.3g' % (B, sigma))
            except Exception as e:
                print("stage %s attempt %d exception %s" % (stage, attempt, e))
                continue
        if time.process_time() >= chain_end - 1.0:
            break

    print("chain attempts=%d accepted=%d stages=%s bestR=%.9f" %
          (attempt, accepted_total, sorted(accepted_stages), bestR))

    # ---- Phase 4: final pad ladder + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _polish(h, slice_dl, pad):
    win = _peak_window(h, pad_frac=pad, extra=128)
    h2 = _lbfgs_block(h, win, 250, slice_dl, beta=1e7)
    if time.process_time() < slice_dl - 0.4:
        h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=0.0)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    best_c = None
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- NEW Phase: sub-step refinement via half-step insertion ----
    # Insert a zero-height point between every pair of steps and re-optimise
    # the peak window at the finer resolution.  This gives the optimiser more
    # degrees of freedom near the top of f*f without changing the coarse shape.
    if time.process_time() < deadline - 8.0 and best.size < 400000:
        try:
            N2 = 2 * best.size
            hf = np.zeros(N2)
            hf[0::2] = best
            hf[1::2] = 0.5 * (best + np.concatenate((best[1:], [best[-1]])))
            hf = _rescale(hf)
            r0 = R_of(hf)
            for beta in [1e6, 1e7]:
                if time.process_time() >= deadline - 7.0:
                    break
                hf = _lbfgs_all_pos(hf, 400, deadline - 6.0, beta=beta)
            for pad in [0.15, 0.10, 0.06]:
                if time.process_time() >= deadline - 6.5:
                    break
                win = _peak_window(hf, pad_frac=pad, extra=256)
                hf2 = _lbfgs_block(hf, win, 400, deadline - 6.0, beta=1e7)
                if R_of(hf2) > R_of(hf):
                    hf = hf2
            rf = R_of(hf)
            print("refine N=%d R=%.9f (was %.9f)" % (N2, rf, bestR))
            if rf > bestR + 1e-13:
                best, bestR, origin = hf.copy(), rf, 'refine'
                print("  refine NEW BEST R=%.9f" % bestR)
            elif rf > alt_bestR:
                alt_best, alt_bestR = hf.copy(), rf
        except Exception as e:
            print("refine exception %s" % e)

    # ---- Phase 3: reserve last ~5s for peak-window + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 3j: round-robin portfolio of four mechanisms ----
    jit_start = t0 + budget_seconds * 0.38
    jit_end = deadline - 6.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < jit_end - 1.0 and best.size >= 8:
        rng = np.random.RandomState(987654321)
        sigmas = [0.003, 0.008, 0.02]
        pads_j = [0.06, 0.04, 0.03]
        Ks = [16, 32, 64]
        rnd = 0
        accepted = [0, 0, 0, 0]
        while time.process_time() < jit_end - 1.0:
            mech = rnd % 4
            rnd += 1
            now = time.process_time()
            slice_dl = min(now + 2.5, deadline - 6.0)
            if slice_dl <= now + 0.4:
                break
            cand = None
            try:
                if mech == 0:
                    nz = np.flatnonzero(best > 0)
                    if nz.size < 4:
                        break
                    sigma = sigmas[rnd % len(sigmas)]
                    Bs = [max(4, nz.size // 100), max(4, nz.size // 50)]
                    B = Bs[(rnd // len(sigmas)) % len(Bs)]
                    if nz.size <= B:
                        sel = nz
                    else:
                        st = rng.randint(0, nz.size - B + 1)
                        sel = nz[st:st + B]
                    h2 = best.copy()
                    mult = np.exp(sigma * rng.randn(sel.size))
                    h2[sel] = h2[sel] * mult
                    cand = _rescale(np.clip(h2, 0, None))
                elif mech == 1:
                    h2 = best.copy()
                    zeros = np.flatnonzero(h2 <= 0)
                    act = h2[h2 > 0]
                    if zeros.size > 0 and act.size > 0:
                        h2[zeros] = 1e-3 * act.mean()
                    cand = _rescale(h2)
                    for beta in [1e5, 1e6, 1e7]:
                        if time.process_time() >= slice_dl - 0.5:
                            break
                        cand = _lbfgs_all_pos(cand, 200, slice_dl - 0.3, beta=beta)
                elif mech == 2:
                    nz = np.flatnonzero(best > 0)
                    if nz.size < 2:
                        continue
                    K = Ks[(rnd // 4) % len(Ks)]
                    side = (rnd // 12) % 2
                    h2 = best.copy()
                    if side == 0:
                        lo = nz[0]
                        if lo >= 2:
                            slope = h2[lo + 1] - h2[lo]
                            kk = min(K, lo)
                            for j in range(1, kk + 1):
                                v = h2[lo] - slope * j
                                h2[lo - j] = max(0.0, v)
                    else:
                        hi = nz[-1]
                        if hi <= h2.size - 3:
                            slope = h2[hi] - h2[hi - 1]
                            kk = min(K, h2.size - 1 - hi)
                            for j in range(1, kk + 1):
                                v = h2[hi] + slope * j
                                h2[hi + j] = max(0.0, v)
                    cand = _rescale(h2)
                else:
                    h2 = best.copy()
                    act = np.flatnonzero(h2 > 0)
                    if act.size < 2:
                        continue
                    mx = h2.max()
                    big = act[h2[act] > 0.02 * mx]
                    if big.size == 0:
                        big = act
                    i = int(big[rng.randint(big.size)])
                    op = rng.randint(4)
                    if op == 0:
                        d = 1 if rng.rand() < 0.5 else -1
                        j = i + d
                        if 0 <= j < h2.size:
                            h2[j] += h2[i]
                            h2[i] = 0.0
                    elif op == 1:
                        d = 2 if rng.rand() < 0.5 else -2
                        j = i + d
                        if 0 <= j < h2.size:
                            h2[j] += h2[i]
                            h2[i] = 0.0
                    elif op == 2:
                        v = h2[i]
                        h2[i] = v / 3.0
                        for d in (-1, 1):
                            j = i + d
                            if 0 <= j < h2.size:
                                h2[j] += v / 3.0
                    else:
                        nb = i - 1 if (i > 0 and (i == h2.size - 1 or rng.rand() < 0.5)) else i + 1
                        if 0 <= nb < h2.size:
                            h2[nb] += h2[i]
                            h2[i] = 0.0
                    cand = _rescale(np.clip(h2, 0, None))
            except Exception as e:
                print("round %d mech %d exception %s" % (rnd, mech, e))
                continue
            if cand is None:
                continue
            pad = pads_j[rnd % len(pads_j)]
            cand = _polish(cand, slice_dl, pad)
            r = R_of(cand)
            print("round %d mech %d R=%.9f (best %.9f)" % (rnd, mech, r, bestR))
            if r > bestR + 1e-13:
                best, bestR = cand.copy(), r
                origin = 'rr_m%d_r%d' % (mech, rnd)
                accepted[mech] += 1
                print("  round %d mech %d NEW BEST R=%.9f" % (rnd, mech, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = cand.copy(), r
        print("portfolio rounds=%d accepted=%s bestR=%.9f" %
              (rnd, accepted, bestR))

    # ---- Phase 4: final peak pads + beta=0 ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _quotient_jitter(q, deadline, rng, rounds=4):
    """Jitter rounds on quotient q; return improved q."""
    sigmas = [0.005, 0.015, 0.04]
    for rnd in range(rounds):
        now = time.process_time()
        if now >= deadline - 0.5:
            break
        slice_dl = min(now + 3.0, deadline)
        if slice_dl <= now + 0.4:
            break
        qc = q.copy()
        B = max(4, q.size // 50) if (rnd % 2 == 0) else max(4, q.size // 200)
        if B >= qc.size:
            s0 = 0
            Bc = qc.size
        else:
            s0 = rng.randint(0, qc.size - B + 1)
            Bc = B
        sigma = sigmas[rnd % len(sigmas)]
        qc[s0:s0 + Bc] = qc[s0:s0 + Bc] * np.exp(sigma * rng.randn(Bc))
        qc = _rescale(np.clip(qc, 0, None))
        win = _peak_window(qc, pad_frac=0.06, extra=64)
        qc = _lbfgs_block(qc, win, 250, slice_dl, beta=1e7)
        if time.process_time() < slice_dl - 0.4:
            qc = _lbfgs_all_pos(qc, 200, slice_dl, beta=0.0)
        r_new = R_of(qc)
        r_old = R_of(q)
        acc = r_new > r_old + 1e-13
        if acc:
            q = qc
        print("  qjit rnd %d B=%d sigma=%.4g R %.9f -> %.9f %s"
              % (rnd, Bc, sigma, r_old, r_new, "ACC" if acc else ""))
    return q


def _split_lift(q, k, N, rng):
    """Lift quotient q of size N//k to full size N with random splits."""
    m = q.size
    w = np.exp(0.3 * rng.randn(m, k))
    w = w / w.sum(axis=1, keepdims=True) * k
    h = (q[:, None] * w).reshape(-1)
    if h.size < N:
        h = np.concatenate((h, np.full(N - h.size, h[-1])))
    return _rescale(np.clip(h[:N], 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if r > bestR - 1e-5:
                variant_hits[k] = max(variant_hits[k], r)
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: coarse-to-fine quotient cascade (k=8,4,2) ----
    cascade_start = t0 + budget_seconds * 0.35
    cascade_end = deadline - 6.0
    if time.process_time() < cascade_start:
        while time.process_time() < cascade_start - 0.05:
            time.sleep(0.01)
    rng = np.random.RandomState(246801357)
    if time.process_time() < cascade_end - 1.0 and best.size >= 16:
        stage_len = max(0.5, (cascade_end - time.process_time()) / 3.0)
        for si, k in enumerate([8, 4, 2]):
            if time.process_time() >= cascade_end - 0.5:
                break
            stage_end = min(cascade_end, time.process_time() + stage_len)
            Ncur = best.size
            if Ncur % k != 0:
                print("cascade k=%d skipped (N=%d not divisible)" % (k, Ncur))
                continue
            q = best.reshape(-1, k).mean(axis=1)
            qR0 = R_of(q)
            print("cascade k=%d start R(q)=%.9f (best %.9f)" % (k, qR0, bestR))
            # jitter rounds on quotient
            for rnd in range(4):
                now = time.process_time()
                if now >= stage_end - 0.5:
                    break
                slice_dl = min(now + 3.0, stage_end)
                if slice_dl <= now + 0.4:
                    break
                qc = q.copy()
                B = max(4, q.size // 50) if (rnd % 2 == 0) else max(4, q.size // 200)
                if B >= qc.size:
                    s0 = 0
                    Bc = qc.size
                else:
                    s0 = rng.randint(0, qc.size - B + 1)
                    Bc = B
                sigma = [0.005, 0.015, 0.04][rnd % 3]
                qc[s0:s0 + Bc] = qc[s0:s0 + Bc] * np.exp(sigma * rng.randn(Bc))
                qc = _rescale(np.clip(qc, 0, None))
                win = _peak_window(qc, pad_frac=0.06, extra=64)
                qc = _lbfgs_block(qc, win, 250, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    qc = _lbfgs_all_pos(qc, 200, slice_dl, beta=0.0)
                r_new = R_of(qc)
                r_old = R_of(q)
                acc = r_new > r_old + 1e-13
                if acc:
                    q = qc
                print("  k=%d rnd %d B=%d sigma=%.4g R(q) %.9f -> %.9f %s"
                      % (k, rnd, Bc, sigma, r_old, r_new, "ACC" if acc else ""))
            # lift to full N and polish
            now = time.process_time()
            if now >= stage_end - 0.5:
                continue
            slice_dl = min(now + 3.0, stage_end)
            h = _split_lift(q, k, Ncur, rng)
            win = _peak_window(h, pad_frac=0.06, extra=128)
            h = _lbfgs_block(h, win, 250, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                h = _lbfgs_all_pos(h, 250, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                h = _lbfgs_all_pos(h, 200, slice_dl, beta=0.0)
            r_lift = R_of(h)
            acc = r_lift > bestR + 1e-13
            print("cascade k=%d lift R=%.9f (best %.9f) %s"
                  % (k, r_lift, bestR, "ACC" if acc else ""))
            if acc:
                best, bestR, origin = h.copy(), r_lift, 'cascade_k%d' % k
                print("  cascade NEW BEST R=%.9f (k=%d)" % (bestR, k))
            elif r_lift > alt_bestR:
                alt_best, alt_bestR = h.copy(), r_lift

    # ---- Phase 4: final peak pads + beta=0 ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag=""):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.20, 0.12]):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _polish(h, slice_dl, pad, beta=1e7):
    win = _peak_window(h, pad_frac=pad, extra=128)
    h2 = _lbfgs_block(h, win, 400, slice_dl, beta=beta)
    if time.process_time() < slice_dl - 0.4:
        h2 = _lbfgs_all_pos(h2, 300, slice_dl, beta=0.0)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: rapid alternating peak-window polish at multiple pads ----
    # This is the highest-value move: local L-BFGS on the peak region with
    # tight pad schedule and beta continuation, repeated until no gain.
    polish_end = t0 + budget_seconds * 0.55
    pads = [0.06, 0.04, 0.03, 0.025, 0.02, 0.015]
    round_no = 0
    while time.process_time() < polish_end - 1.0:
        round_no += 1
        improved = False
        for pad in pads:
            if time.process_time() >= polish_end - 0.8:
                break
            slice_dl = min(polish_end, time.process_time() + 0.05 * budget_seconds)
            ht = _polish(best, slice_dl, pad)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, 'pk%.3f' % pad
                improved = True
                print("polish round %d pad %.3f NEW BEST R=%.9f" % (round_no, pad, bestR))
            elif r > alt_bestR and alt_best is None:
                alt_best, alt_bestR = ht.copy(), r
        if not improved:
            break

    # ---- Phase 2: half-resolution extract/lift cycles ----
    N = best.size
    if N % 2 == 0 and N >= 8:
        m = N // 2
        cyc_end = deadline - 8.0
        cyc = 0
        while cyc < 6 and time.process_time() < cyc_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(cyc_end, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            if k == 0:
                c = best[0::2][:m].copy()
            elif k == 1:
                c = best[1::2][:m].copy()
            else:
                a = best[0::2][:m]
                b = best[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            work_c, cand_c, cand_cR, org = _half_cycle(c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc))
            hnew = _lift(cand_c, k, N)
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'lift_v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: alternating peak polish + beta=0 full until deadline ----
    while time.process_time() < deadline - 1.0:
        improved = False
        for pad in [0.03, 0.02, 0.015, 0.01]:
            if time.process_time() >= deadline - 0.8:
                break
            slice_dl = min(deadline - 0.5, time.process_time() + 0.05 * budget_seconds)
            ht = _polish(best, slice_dl, pad)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, origin + '+pk'
                improved = True
                print("late peak pad %.3f NEW BEST R=%.9f" % (pad, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 0.9:
            slice_dl = min(deadline - 0.5, time.process_time() + 0.06 * budget_seconds)
            ht = _lbfgs_all_pos(best, 400, slice_dl, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, origin + '+b0'
                improved = True
                print("late beta0 NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        if not improved and time.process_time() > deadline - 2.0:
            break

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

