            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _asym_lift(c, seed):
    rng = np.random.RandomState(seed)
    w = np.exp(0.5 * rng.randn(2))
    w = w * (2.0 / w.sum())
    N = c.size
    h = np.empty(2 * N)
    h[0::2] = c * w[0]
    h[1::2] = c * w[1]
    return _rescale(np.clip(h, 0.0, None))


def _polish_lift(h, slice_dl):
    if time.process_time() < slice_dl - 0.6:
        h = _lbfgs_all_pos(h, 150, slice_dl - 0.3, beta=1e6)
    if time.process_time() < slice_dl - 0.6:
        h = _lbfgs_all_pos(h, 150, slice_dl - 0.3, beta=1e7)
    if time.process_time() < slice_dl - 0.6:
        win = _peak_window(h, pad_frac=0.08, extra=256)
        h = _lbfgs_block(h, win, 250, slice_dl - 0.3, beta=1e7)
    if time.process_time() < slice_dl - 0.6:
        win = _peak_window(h, pad_frac=0.04, extra=128)
        h = _lbfgs_block(h, win, 250, slice_dl - 0.3, beta=1e7)
    if time.process_time() < slice_dl - 0.6:
        h = _lbfgs_all_pos(h, 150, slice_dl - 0.3, beta=0.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1 + repeated asymmetric-lift rounds ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 8.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))

        # Repeated (half_cycle on c -> asymmetric lift -> polish) rounds
        seed = 1
        while time.process_time() < deadline - 8.0:
            now = time.process_time()
            slice_dl = min(now + 7.0, deadline - 8.0)
            if slice_dl <= now + 1.0:
                break
            # half_cycle on c (short)
            wc, bc, bcR, _ = _half_cycle(work_c, best_cR, slice_dl - 3.0,
                                         tag='c%d' % seed,
                                         pads=[0.15, 0.10, 0.08])
            work_c = wc
            if bcR > best_cR + 1e-14:
                best_c = bc
                best_cR = bcR
            # asymmetric lift
            h_lift = _asym_lift(best_c, seed)
            r_lift = R_of(h_lift)
            # polish
            hp = _polish_lift(h_lift, slice_dl)
            rp = R_of(hp)
            zf = float(np.mean(hp == 0))
            asym = bool(np.any(hp[0::2] != hp[1::2]))
            accept = rp > bestR + 1e-13
            if accept:
                best, bestR = hp.copy(), rp
                origin = 'asym%d' % seed
            elif rp > alt_bestR:
                alt_best, alt_bestR = hp.copy(), rp
            print("asym round %d R(c)=%.9f liftR=%.9f polR=%.9f zf=%.4f asym=%d %s best=%.9f"
                  % (seed, best_cR, r_lift, rp, zf, int(asym),
                     'ACCEPT' if accept else 'reject', bestR))
            seed += 1

    # ---- Phase 3: final pad ladder + beta=1e7 / beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _downsample(h, k):
    n = h.size
    m = (n + k - 1) // k
    pad = m * k - n
    if pad:
        hp = np.concatenate([h, np.zeros(pad)])
    else:
        hp = h
    return hp.reshape(m, k).mean(axis=1)


def _upsample(h, k):
    return np.repeat(h, k)


def _smooth(h, sigma):
    """Gaussian smoothing with edge preservation (reflect)."""
    if sigma <= 0:
        return h
    r = int(np.ceil(3 * sigma))
    if r < 1:
        return h
    x = np.arange(-r, r + 1, dtype=float)
    w = np.exp(-0.5 * (x / sigma) ** 2)
    w /= w.sum()
    hp = np.pad(h, r, mode='edge')
    return np.convolve(hp, w, mode='valid')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(cand, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR, origin = cand.copy(), r, tag
            print("%s NEW BEST R=%.9f" % (tag, bestR))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase 0: quick direct fine polish on the start ----
    # A short polish at full resolution with a tight peak-window before any
    # coarse work: this tends to squeeze a tiny bit out of an already
    # converged start, which the ladders often fail to do.
    q_dl = min(deadline, time.process_time() + 0.10 * budget_seconds)
    ht = _lbfgs_all_pos(best, 400, q_dl, beta=1e7)
    consider(ht, 'prebeta')
    if time.process_time() < q_dl - 0.5:
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht2 = _lbfgs_block(best, win, 400, q_dl - 0.3, beta=1e7)
        consider(ht2, 'prepeak')

    # ---- Phase 1: multi-resolution lift-polish ladder ----
    ladder_deadline = t0 + budget_seconds * 0.58
    ks = [2, 3, 4, 2, 3, 5]
    li = 0
    while time.process_time() < ladder_deadline - 3.0 and li < len(ks):
        k = ks[li]
        li += 1
        if best.size < 2 * k:
            continue
        slice_dl = min(ladder_deadline,
                       time.process_time() + 0.11 * budget_seconds)
        c = _downsample(best, k)
        c = _rescale(c)
        for beta in [1e6, 1e7]:
            if time.process_time() >= slice_dl - 0.5:
                break
            c = _lbfgs_all_pos(c, 400, slice_dl - 0.3, beta=beta)
        r_c = R_of(c)
        h_up = _rescale(_upsample(c, k))
        ht = h_up
        for beta in [1e6, 1e7]:
            if time.process_time() >= slice_dl - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 400, slice_dl - 0.3, beta=beta)
        if time.process_time() < slice_dl - 0.5:
            win = _peak_window(ht, pad_frac=0.15, extra=128)
            ht2 = _lbfgs_block(ht, win, 300, slice_dl - 0.3, beta=1e7)
            if R_of(ht2) > R_of(ht):
                ht = ht2
        if not consider(ht, 'ladder%d(c=%.6f)' % (k, r_c)):
            print("ladder%d no gain R(c)=%.9f R=%.9f" % (k, r_c, R_of(ht)))

    # ---- Phase 2: perturb-and-lift restarts at coarse resolution ----
    restart_deadline = t0 + budget_seconds * 0.82
    rng = np.random.default_rng(12345)
    ri = 0
    amps = [0.01, 0.02, 0.04, 0.06, 0.03]
    while time.process_time() < restart_deadline - 3.0:
        amp = amps[ri % len(amps)]
        ri += 1
        k = [2, 3, 2, 4][ri % 4]
        if best.size < 2 * k:
            continue
        slice_dl = min(restart_deadline,
                       time.process_time() + 0.08 * budget_seconds)
        c = _downsample(best, k)
        c = _rescale(c)
        nz = c > 0
        if nz.sum() == 0:
            break
        c[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
        c = _rescale(c)
        c = _lbfgs_all_pos(c, 300, slice_dl - 0.5, beta=1e7)
        h_up = _rescale(_upsample(c, k))
        ht = h_up
        for beta in [1e6, 1e7]:
            if time.process_time() >= slice_dl - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
        if not consider(ht, 'restart%d(k=%d,amp=%.2f)' % (ri, k, amp)):
            if ri % 3 == 0:
                print("restart%d no gain R=%.9f" % (ri, R_of(ht)))

    # ---- Phase 2b: smooth-and-lift restarts (new idea) ----
    # Applying a Gaussian blur to the best shape and re-lifting through a
    # short polish lets the optimizer escape tiny local ripples that the
    # multiplicative perturbations above cannot remove. This is a
    # qualitatively different move from the noise restarts.
    smooth_deadline = t0 + budget_seconds * 0.90
    for sig in [1.0, 2.0, 4.0, 8.0, 3.0, 6.0]:
        if time.process_time() >= smooth_deadline - 3.0:
            break
        slice_dl = min(smooth_deadline,
                       time.process_time() + 0.07 * budget_seconds)
        hs = _smooth(best, sig)
        hs = _rescale(hs)
        # lift through a coarse downsample so the smooth shape acts as
        # a coarse-scale prior
        k = 2
        if hs.size > 2 * k:
            c = _downsample(hs, k)
            c = _rescale(c)
            c = _lbfgs_all_pos(c, 300, slice_dl - 0.5, beta=1e7)
            hs = _rescale(_upsample(c, k))
        ht = _lbfgs_all_pos(hs, 300, slice_dl - 0.3, beta=1e7)
        if not consider(ht, 'smooth%.1f' % sig):
            print("smooth%.1f no gain R=%.9f" % (sig, R_of(ht)))

    # ---- Phase 3: fine peak polish on best ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.12, 0.08, 0.05, 0.03]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 500, deadline - 0.3, beta=1e7)
            consider(ht2, 'peak%.2f' % pad)

    # ---- Phase 4: trailing beta=0 polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.4, beta=0.0)
        consider(ht, 'beta0')

    # ---- Phase 5: final all-pos beta polish ----
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.25, beta=1e7)
        consider(ht, 'finalbeta')

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

