            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _polish_quotient(c, deadline, maxiter=100):
    """beta ladder 1e6, 1e7, 0 on a coarse quotient."""
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_all_pos(c, maxiter, deadline, beta=beta)
    return c


def _lift_repeat(c):
    return _rescale(np.repeat(c, 2))


def _lift_odd(c):
    """Map c[i] to cells (2i+1, 2i+2) so no mass is lost at the ends.
    Result has length 2*len(c)+2."""
    n = c.size
    h = np.zeros(2 * n + 2)
    h[1:2 * n + 1] = np.repeat(c, 2)
    return _rescale(h)


def _rotation_variants(best):
    """Return list of (name, coarse, lift_fn) rotation variants at stride 2."""
    n = best.size
    variants = []
    # (a) even
    c_even = best[0::2].copy()
    variants.append(('even', c_even, _lift_repeat))
    # (b) odd with shape-safe lift
    if n >= 3:
        c_odd = best[1::2].copy()
        variants.append(('odd', c_odd, _lift_odd))
    # (c) averaged
    m = min(best[0::2].size, best[1::2].size)
    c_avg = 0.5 * (best[0::2][:m] + best[1::2][:m])
    variants.append(('avg', c_avg, _lift_repeat))
    return variants


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish (short) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: stride-2 rotation + stride-4 coarse-to-fine cascade ----
    cascade_start = t0 + budget_seconds * 0.25
    cascade_end = deadline - 4.0
    if time.process_time() < cascade_start:
        while time.process_time() < cascade_start - 0.05:
            time.sleep(0.005)
    cyc = 0
    while cyc < 3 and time.process_time() < cascade_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 12.0, deadline - 5.0)
        if slice_dl <= now + 0.8:
            break

        # ---- stride-2 rotation ----
        variants = _rotation_variants(best)
        order = ['even', 'odd', 'avg']
        rot = cyc % len(order)
        order = order[rot:] + order[:rot]
        vmap = {name: (c, lift) for name, c, lift in variants}

        rot_best_h = None
        rot_bestR = -1.0
        rot_name = None
        for name in order:
            if time.process_time() > slice_dl - 2.0:
                break
            c, lift = vmap[name]
            c = _polish_quotient(c, slice_dl - 1.0, maxiter=100)
            if time.process_time() > slice_dl - 2.0:
                break
            h = lift(c)
            if time.process_time() < slice_dl - 2.0:
                h = _lbfgs_all_pos(h, 150, slice_dl - 1.0, beta=1e7)
            r = R_of(h)
            if r > rot_bestR:
                rot_best_h, rot_bestR, rot_name = h, r, name

        if rot_best_h is None:
            break
        print("cycle %d rot winner=%s R=%.9f" % (cyc, rot_name, rot_bestR))

        # ---- stride-4 cascade on the rotation winner ----
        work = rot_best_h
        if work.size >= 8 and work.size % 4 == 0 and time.process_time() < slice_dl - 1.0:
            c4 = work[0::4].copy()
            if time.process_time() < slice_dl - 1.0:
                c4 = _lbfgs_all_pos(c4, 120, slice_dl, beta=1e6)
            if time.process_time() < slice_dl - 1.0:
                c4 = _lbfgs_all_pos(c4, 120, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 1.0:
                c4 = _lbfgs_all_pos(c4, 120, slice_dl, beta=0.0)
            if time.process_time() < slice_dl - 1.0:
                w = np.exp(0.25 * np.random.RandomState(1000 + cyc).randn(2))
                w = w * 2.0 / w.sum()
                c2 = _rescale(np.repeat(c4, 2) * np.tile(w, c4.size))
                if time.process_time() < slice_dl - 1.0:
                    c2 = _half_cycle(c2, R_of(c2), slice_dl, tag='s4_%d' % cyc)[1]
                h = _rescale(np.repeat(c2, 2))
                if time.process_time() < slice_dl - 1.0:
                    h = _lbfgs_all_pos(h, 150, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 1.0:
                    h = _lbfgs_all_pos(h, 150, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 1.0:
                    h = _lbfgs_block(h, _peak_window(h, 0.06, 128), 250, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 1.0:
                    h = _lbfgs_all_pos(h, 200, slice_dl, beta=0.0)
                r_h = R_of(h)
                if r_h > rot_bestR:
                    work, rot_bestR = h, r_h

        r_h = rot_bestR
        accepted = r_h > bestR + 5e-14
        if accepted:
            best, bestR, origin = work.copy(), r_h, 'rot_%s_%d' % (rot_name, cyc)
        elif r_h > alt_bestR:
            alt_best, alt_bestR = work.copy(), r_h
        print("cycle %d R(h)=%.9f %s best=%.9f"
              % (cyc, r_h, "ACCEPT" if accepted else "reject", bestR))
        cyc += 1

    # ---- Phase 3: final pad ladder + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift_candidates(c, cyc):
    """Build K=4 candidate sub-cell weightings for lifting c by factor 2."""
    cands = []
    # (i) original random draw
    w1 = np.exp(0.25 * np.random.RandomState(1000 + cyc).randn(2))
    w1 = w1 * 2.0 / w1.sum()
    cands.append(('rand025', w1))
    # (ii) deterministic repeat
    cands.append(('repeat', np.array([1.0, 1.0])))
    # (iii) wider random draw
    w3 = np.exp(0.5 * np.random.RandomState(5000 + cyc).randn(2))
    w3 = w3 * 2.0 / w3.sum()
    cands.append(('rand05', w3))
    # (iv) asymmetric sinusoidal
    t = 0.15 * np.sin(cyc)
    cands.append(('asym', np.array([0.5 + t, 1.5 - t])))
    return cands


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish (short) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: stride-4 coarse-to-fine quotient cascade w/ lift portfolio ----
    cascade_start = t0 + budget_seconds * 0.25
    cascade_end = deadline - 4.0
    if time.process_time() < cascade_start:
        while time.process_time() < cascade_start - 0.05:
            time.sleep(0.005)
    cyc = 0
    while cyc < 3 and time.process_time() < cascade_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 12.0, deadline - 5.0)
        if slice_dl <= now + 0.8:
            break
        if best.size < 8 or best.size % 4 != 0:
            break
        # (a) stride-4 quotient polish
        c4 = best[0::4].copy()
        if time.process_time() < slice_dl - 1.0:
            c4 = _lbfgs_all_pos(c4, 120, slice_dl - 1.0, beta=1e6)
        if time.process_time() < slice_dl - 1.0:
            c4 = _lbfgs_all_pos(c4, 120, slice_dl - 1.0, beta=1e7)
        if time.process_time() < slice_dl - 1.0:
            c4 = _lbfgs_all_pos(c4, 120, slice_dl - 1.0, beta=0.0)
        r_c4 = R_of(c4)
        if time.process_time() >= slice_dl - 1.0:
            break
        # (b) lift 4 -> 2 with candidate portfolio screen
        c2 = None
        r_c2 = -1.0
        screen_ok = (slice_dl - time.process_time()) > 4.0
        if screen_ok:
            best_name = None
            best_r = -1.0
            best_h = None
            for name, w in _lift_candidates(c4, cyc):
                if time.process_time() >= slice_dl - 1.0:
                    break
                hk = _rescale(np.repeat(c4, 2) * np.tile(w, c4.size))
                hk = _lbfgs_all_pos(hk, 80, slice_dl - 1.0, beta=1e7)
                rk = R_of(hk)
                if rk > best_r:
                    best_r, best_h, best_name = rk, hk, name
            if best_h is not None:
                c2 = best_h
                r_c2 = best_r
                print("cycle %d screen winner=%s R=%.9f (prev best %.9f)"
                      % (cyc, best_name, r_c2, bestR))
        if c2 is None:
            w = np.exp(0.25 * np.random.RandomState(1000 + cyc).randn(2))
            w = w * 2.0 / w.sum()
            c2 = _rescale(np.repeat(c4, 2) * np.tile(w, c4.size))
        # long polish of the chosen c2
        if time.process_time() < slice_dl - 1.0:
            c2 = _half_cycle(c2, R_of(c2), slice_dl, tag='s4_%d' % cyc)[1]
        r_c2 = R_of(c2)
        if time.process_time() >= slice_dl - 1.0:
            break
        # (c) lift 2 -> N with np.repeat, polish
        h = _rescale(np.repeat(c2, 2))
        if time.process_time() < slice_dl - 1.0:
            h = _lbfgs_all_pos(h, 150, slice_dl - 1.0, beta=1e6)
        if time.process_time() < slice_dl - 1.0:
            h = _lbfgs_all_pos(h, 150, slice_dl - 1.0, beta=1e7)
        if time.process_time() < slice_dl - 1.0:
            h = _lbfgs_block(h, _peak_window(h, 0.06, 128), 250, slice_dl - 1.0, beta=1e7)
        if time.process_time() < slice_dl - 1.0:
            h = _lbfgs_all_pos(h, 200, slice_dl - 1.0, beta=0.0)
        r_h = R_of(h)
        accepted = r_h > bestR + 5e-14
        if accepted:
            best, bestR, origin = h.copy(), r_h, 's4_%d' % cyc
        elif r_h > alt_bestR:
            alt_best, alt_bestR = h.copy(), r_h
        print("cycle %d R(c4)=%.9f R(c2)=%.9f R(h)=%.9f %s best=%.9f"
              % (cyc, r_c4, r_c2, r_h, "ACCEPT" if accepted else "reject", bestR))
        cyc += 1

    # ---- Phase 3: final pad ladder + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _refine_peak_knot(h, deadline, radius=6, maxiter=300):
    """NEW: local free-form reparametrisation of the peak knot region.
    Take the top-knot and free a small symmetric window of *knot* positions
    (i.e. shift mass between neighbouring heights) to allow the peak to move
    off the current grid point. This is a distinct move from window polish
    because it works on the derivative structure of L around its max."""
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    # knot m corresponds to h index m-1 (Lf = [0, conv, 0])
    ci = m - 1
    lo = max(0, ci - radius)
    hi = min(h.size - 1, ci + radius)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt = None
    altR = 0.0
    N = best.size

    def _try(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        print("%s R=%.7f" % (tag, r))
        if alt is None or r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s improved R=%.7f" % (tag, bestR))

    # NEW: peak-knot free-form refinement on best first, cheap and focused.
    if time.process_time() < deadline - 4.0:
        h = best.copy()
        for rad in (4, 6, 10, 16):
            if time.process_time() >= deadline - 2.0:
                break
            h = _refine_peak_knot(h, deadline, radius=rad, maxiter=250)
            h = _lbfgs_log(h, 200, deadline)
        _try(h, "peak_knot")

    # Coarse-to-fine on a fresh downsample (different from best's own grid).
    for Nc in (1024, 2048, 4096):
        if time.process_time() >= deadline - 8.0:
            break
        if Nc >= N:
            continue
        hc = _coarse(best, Nc)
        hc = _rescale(hc)
        for beta in (8.0, 20.0, 60.0, 0.0):
            if time.process_time() >= deadline - 6.0:
                break
            hc = _lbfgs_log(hc, 300, deadline, beta=beta)
        r = R_of(hc)
        print("coarse %d R=%.7f" % (Nc, r))
        if time.process_time() < deadline - 4.0:
            hp = _prolongate(hc, N)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 400, deadline)
            _try(hp, "coarse_up")

    # Beta continuation on best.
    if time.process_time() < deadline - 3.0:
        h = best.copy()
        for beta in (30.0, 100.0, 300.0, 0.0):
            if time.process_time() >= deadline - 2.0:
                break
            h = _lbfgs_log(h, 400, deadline, beta=beta)
        _try(h, "beta_tight")

    # Peak-focused polish at full resolution.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 500, deadline)
        _try(h, "peak(%.2f)" % frac)

    # Phase exploration.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale(hp)
        if hp.sum() <= 0:
            continue
        hp = _lbfgs_log(hp, 600, deadline)
        hp = _window_polish_peak(hp, deadline, 0.35, 16)
        _try(hp, "phase %+.2f" % delta)

    # Final loop: alternate full, peak-window, and peak-knot polish.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _refine_peak_knot(best, deadline, radius=8, maxiter=200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("pk R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt is not None and altR > 0 and altR < bestR - 1e-12:
        return {"best": best, "alternative": alt}
    return best

