def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _polish_coarse(cs, slice_dl, maxiter=100):
    if time.process_time() >= slice_dl - 1.5:
        return cs
    cs = _lbfgs_all_pos(cs, maxiter, slice_dl - 1.0, beta=1e6)
    if time.process_time() >= slice_dl - 1.5:
        return cs
    cs = _lbfgs_all_pos(cs, maxiter, slice_dl - 1.0, beta=1e7)
    if time.process_time() >= slice_dl - 1.5:
        return cs
    cs = _lbfgs_all_pos(cs, maxiter, slice_dl - 1.0, beta=0.0)
    return cs


def _lift_split(c, seed, slice_dl, maxiter=80):
    rs = np.random.RandomState(seed)
    w = np.exp(0.25 * rs.randn(2))
    w = w * 2.0 / w.sum()
    h = _rescale(np.repeat(c, 2) * np.tile(w, c.size))
    if time.process_time() < slice_dl - 1.5:
        h = _lbfgs_all_pos(h, maxiter, slice_dl - 1.0, beta=1e7)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish (short) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: deep stride ladder 16->8->4->2->N cascade ----
    cascade_start = t0 + budget_seconds * 0.25
    cascade_end = deadline - 4.0
    if time.process_time() < cascade_start:
        while time.process_time() < cascade_start - 0.05:
            time.sleep(0.005)
    cyc = 0
    while cyc < 4 and time.process_time() < cascade_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 9.0, deadline - 5.0)
        if slice_dl <= now + 1.0:
            break
        if best.size < 32 or best.size % 16 != 0:
            # fall back: only go as deep as divisibility allows
            pass
        c = best.copy()
        stride_Rs = []
        ok = True
        # fold through strides 16, 8, 4, 2
        for i, s in enumerate((16, 8, 4, 2)):
            if time.process_time() >= slice_dl - 1.5:
                ok = False
                break
            step = 16 // (2 ** i)  # 16, 8, 4, 2
            if c.size % 2 != 0:
                ok = False
                break
            cs = c[0::2].copy()
            cs = _polish_coarse(cs, slice_dl, maxiter=100)
            r_cs = R_of(cs)
            stride_Rs.append((s, r_cs))
            if time.process_time() >= slice_dl - 1.5:
                ok = False
                break
            c = _lift_split(cs, 9000 + 97 * cyc + s, slice_dl, maxiter=80)
        if not ok:
            print("cycle %d aborted mid-ladder" % cyc)
            cyc += 1
            continue
        # c is now at stride 1 (full N) after lifting 2->N
        h = c
        if time.process_time() < slice_dl - 1.5:
            h = _lbfgs_all_pos(h, 150, slice_dl - 1.0, beta=1e6)
        if time.process_time() < slice_dl - 1.5:
            h = _lbfgs_all_pos(h, 150, slice_dl - 1.0, beta=1e7)
        if time.process_time() < slice_dl - 1.5:
            win = _peak_window(h, 0.06, 128)
            h = _lbfgs_block(h, win, 250, slice_dl - 1.0, beta=1e7)
        if time.process_time() < slice_dl - 1.5:
            h = _lbfgs_all_pos(h, 200, slice_dl - 1.0, beta=0.0)
        r_h = R_of(h)
        accepted = r_h > bestR + 5e-14
        if accepted:
            best, bestR, origin = h.copy(), r_h, 'ladder_%d' % cyc
        elif r_h > alt_bestR:
            alt_best, alt_bestR = h.copy(), r_h
        rs_str = " ".join("s%d=%.9f" % (s, r) for s, r in stride_Rs)
        print("cycle %d %s R(h)=%.9f %s best=%.9f"
              % (cyc, rs_str, r_h, "ACCEPT" if accepted else "reject", bestR))
        cyc += 1

    # ---- Phase 3: final pad ladder + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolong(h):
    return np.repeat(h, 2)


def _smooth(h, iters=1):
    """Light smoothing to escape from local optima / break up spurious spikes."""
    k = np.array([1.0, 2.0, 1.0]) / 4.0
    out = h
    for _ in range(iters):
        out = np.convolve(out, k, mode='same')
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    print("base R=%.9f N=%d" % (baseR, baseH.size))

    bestH = baseH.copy()
    bestR = baseR
    altH = baseH.copy()
    altR = baseR

    def _consider(h, tag):
        nonlocal bestH, bestR, altH, altR
        r = R_of(h)
        if r > bestR + 1e-14:
            bestH, bestR = _rescale(h).copy(), r
            print("  %s -> new best R=%.9f" % (tag, bestR))
        if r > altR + 1e-14:
            altH, altR = _rescale(h).copy(), r
        return r

    # Stage 1: polish start with beta-continuation full-space L-BFGS.
    work = bestH.copy()
    for beta in [1e5, 1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 3.0:
            break
        cap = min(deadline - 2.0, time.process_time() + 8.0)
        ht = _lbfgs_all_pos(work, 400, cap, beta=beta)
        r = _consider(ht, "beta%g" % beta)
        if r > R_of(work) + 1e-14:
            work = ht

    # Stage 2: peak-window polish (+ short beta runs inside)
    for pad in (0.30, 0.20, 0.15, 0.10, 0.08, 0.05):
        if time.process_time() >= deadline - 3.0:
            break
        win = _peak_window(bestH, pad_frac=pad)
        cap = min(deadline - 2.0, time.process_time() + 4.0)
        hp = _lbfgs_block(bestH, win, 300, cap)
        _consider(hp, "peak pad=%.2f" % pad)

    # Stage 3: cooperative smoothing + re-optimisation to escape local optima.
    cycle = 0
    while time.process_time() < deadline - 4.0:
        cycle += 1
        # Take best, smooth, re-optimise
        hs = _smooth(bestH, iters=1)
        r0 = R_of(hs)
        if r0 < bestR - 0.005:
            # Don't destroy too much; use lighter perturbation
            hs = _smooth(bestH, iters=1)
        cap = min(deadline - 3.0, time.process_time() + 6.0)
        ht = _lbfgs_all_pos(hs, 300, cap, beta=0.0)
        r = _consider(ht, "smooth+optim cyc%d" % cycle)
        # Also try beta-annealed from smoothed
        if time.process_time() < deadline - 3.0:
            cap = min(deadline - 2.0, time.process_time() + 5.0)
            ht2 = _lbfgs_all_pos(hs, 300, cap, beta=1e6)
            _consider(ht2, "smooth+beta cyc%d" % cycle)

    # Final peak-window polish
    if time.process_time() < deadline - 1.5:
        win = _peak_window(bestH, pad_frac=0.10)
        cap = min(deadline - 1.0, time.process_time() + 3.0)
        hp = _lbfgs_block(bestH, win, 300, cap)
        _consider(hp, "final peak")

    print("final bestR=%.9f baseR=%.9f" % (bestR, baseR))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        if altR > baseR + 1e-12:
            return {"best": altH, "alternative": baseH}
        return {"best": baseH, "alternative": altH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag=""):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.20, 0.10, 0.06]):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
    if time.process_time() < deadline - 0.6:
        ht2 = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=0.0)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            work, best, bestR = ht2, ht2.copy(), r2
            origin = "%s+all0" % tag
    return work, best, bestR, origin


def _lift_candidates(c, cyc):
    cands = []
    w1 = np.exp(0.25 * np.random.RandomState(1000 + cyc).randn(2))
    w1 = w1 * 2.0 / w1.sum()
    cands.append(('rand025', w1))
    cands.append(('repeat', np.array([1.0, 1.0])))
    w3 = np.exp(0.5 * np.random.RandomState(5000 + cyc).randn(2))
    w3 = w3 * 2.0 / w3.sum()
    cands.append(('rand05', w3))
    t = 0.15 * np.sin(cyc)
    cands.append(('asym', np.array([0.5 + t, 1.5 - t])))
    return cands


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Track a working copy that's always the current best candidate
    work = best.copy()
    workR = bestR

    # ---- Phase 1: interleaved coarse quotient polishes on the full best ----
    # Instead of spending 25% on half-res lift, alternate: polish coarse
    # quotient, lift back, polish full; repeat with smaller strides.
    coarse_start = t0
    coarse_end = t0 + budget_seconds * 0.55
    cyc = 0
    strides = [2, 2, 4, 2]  # cycle through different coarse strides
    while time.process_time() < coarse_end - 2.0 and cyc < len(strides) + 2:
        now = time.process_time()
        slice_dl = min(now + 10.0, coarse_end - 1.0)
        if slice_dl <= now + 0.8:
            break
        stride = strides[cyc % len(strides)]
        if work.size % stride != 0 or work.size < 4 * stride:
            cyc += 1
            continue
        c = work[0::stride].copy()
        cR = R_of(c)
        # polish coarse
        c = _half_cycle(c, cR, slice_dl - 4.0, tag='c%d' % cyc)[1]
        if time.process_time() >= slice_dl - 1.0:
            cyc += 1
            continue
        # lift back to full with candidate screen
        best_name = None
        best_r = -1.0
        best_h = None
        for name, w in _lift_candidates(c, cyc):
            if time.process_time() >= slice_dl - 1.0:
                break
            hk = _rescale(np.repeat(c, stride) * np.tile(w, c.size))
            hk = _lbfgs_all_pos(hk, 100, slice_dl - 1.0, beta=1e7)
            rk = R_of(hk)
            if rk > best_r:
                best_r, best_h, best_name = rk, hk, name
        if best_h is None:
            cyc += 1
            continue
        # final polish of chosen lift
        if time.process_time() < slice_dl - 1.0:
            h = _lbfgs_all_pos(best_h, 200, slice_dl - 1.0, beta=1e6)
            r_h = R_of(h)
            if r_h > best_r:
                best_h, best_r = h, r_h
        if time.process_time() < slice_dl - 1.0:
            h = _lbfgs_block(best_h, _peak_window(best_h, 0.06, 128),
                             250, slice_dl - 1.0, beta=1e7)
            r_h = R_of(h)
            if r_h > best_r:
                best_h, best_r = h, r_h
        if time.process_time() < slice_dl - 1.0:
            h = _lbfgs_all_pos(best_h, 200, slice_dl - 1.0, beta=0.0)
            r_h = R_of(h)
            if r_h > best_r:
                best_h, best_r = h, r_h
        if best_r > bestR + 1e-14:
            work, workR = best_h.copy(), best_r
            best, bestR, origin = best_h.copy(), best_r, 'coarse%d_%s' % (stride, best_name)
            print("cycle %d stride=%d %s NEW BEST R=%.9f"
                  % (cyc, stride, best_name, bestR))
        elif best_r > alt_bestR:
            alt_best, alt_bestR = best_h.copy(), best_r
        cyc += 1

    # ---- Phase 2: full-resolution polish with mixed betas + peak windows ----
    polish_end = deadline - 2.0
    while time.process_time() < polish_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 8.0, polish_end)
        if slice_dl <= now + 0.8:
            break
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= slice_dl - 1.0:
                break
            ht = _lbfgs_all_pos(best, 200, slice_dl - 1.0, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, origin + '+b%g' % beta
                print("polish beta=%g NEW BEST R=%.9f" % (beta, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        if time.process_time() >= slice_dl - 1.0:
            break
        for pad in [0.10, 0.06]:
            if time.process_time() >= slice_dl - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 400, slice_dl - 1.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, origin + '+pk%g' % pad
                print("polish pad=%g NEW BEST R=%.9f" % (pad, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: final beta=0 polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+final0'
            print("final beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


class _Timeout(Exception):
    pass


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        if time.process_time() > deadline - 0.2:
            raise _Timeout()
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (_Timeout, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        if time.process_time() > deadline - 0.2:
            raise _Timeout()
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (_Timeout, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _polish(c, bestR, deadline, rounds=3):
    """Alternate full lbfgs (with continuation betas) and peak-window block polish."""
    best = c.copy()
    work = c.copy()
    for it in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        # continuation betas
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(work, 400, deadline - 0.3, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
        # peak-window block polish
        for pad in [0.25, 0.15, 0.10]:
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(work, pad_frac=pad)
            ht = _lbfgs_block(work, win, 400, deadline - 0.3)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
        # plain full
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_all_pos(work, 400, deadline - 0.3)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        s = np.asarray(start, dtype=float).copy()
        if s.size == 0 or not np.all(np.isfinite(s)) or s.sum() <= 0:
            s = np.ones(64)
    else:
        s = np.ones(64)
    s = _rescale(np.maximum(s, 0))
    start_R = R_of(s)
    best_h = s.copy()
    best_R = start_R
    print("start R=%.6f N=%d" % (start_R, s.size))

    # Primary: polish the start at its own resolution, then at a higher resolution.
    if start is not None:
        h, R = _polish(s, best_R, deadline - 0.5 * (deadline - t0), rounds=2)
        if R > best_R:
            best_h, best_R = h.copy(), R
            print("  start polished R=%.6f" % R)

        # prolongate to 2x and re-polish
        if time.process_time() < deadline - 5.0:
            N2 = min(2 * s.size, 262144)
            if N2 > s.size:
                h2 = _rescale(_prolongate_mass(best_h, N2))
                R2 = R_of(h2)
                h2, R2 = _polish(h2, R2, deadline, rounds=2)
                if R2 > best_R:
                    best_h, best_R = h2.copy(), R2
                    print("  N=%d polished R=%.6f" % (N2, R2))

    # Fallback / exploration: super-Gaussian seeds if budget remains
    if time.process_time() < deadline - 10.0 and best_R < 0.95:
        N1 = max(2048, min(8192, best_h.size))
        x = (np.arange(N1) + 0.5) / N1
        best_seed = None
        best_sR = -1.0
        for p in (2, 3, 4, 6, 8):
            for w in (0.2, 0.3, 0.4):
                h = np.exp(-(np.abs(x - 0.5) / w) ** p)
                r = R_of(h)
                if r > best_sR:
                    best_sR = r
                    best_seed = h
        if best_seed is not None and time.process_time() < deadline - 8.0:
            hs, Rs = _polish(best_seed, best_sR, deadline, rounds=2)
            if Rs > best_R:
                best_h, best_R = hs.copy(), Rs
                print("  seed polished R=%.6f" % Rs)

    # Spend remaining time iterating full polish + window block polish.
    cur_h, cur_R = best_h.copy(), best_R
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        if it % 2 == 1:
            h2 = _lbfgs_all_pos(cur_h, 500, deadline - 0.3)
        else:
            win = _peak_window(cur_h, pad_frac=0.10)
            h2 = _lbfgs_block(cur_h, win, 400, deadline - 0.3)
        r2 = R_of(h2)
        if r2 > cur_R + 1e-14:
            cur_h, cur_R = h2, r2
            if cur_R > best_R:
                best_R = cur_R
                best_h = cur_h.copy()
        print("  iter %d R=%.6f best=%.6f" % (it, cur_R, best_R))
        if time.process_time() > deadline - 1.5:
            break

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        sR = R_of(np.asarray(start, dtype=float))
        if sR >= best_R:
            return {"best": np.asarray(start, dtype=float), "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

