        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _polish_quotient(c, deadline, maxiter=100):
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_all_pos(c, maxiter, deadline, beta=beta)
    return c


def _lift_repeat(c):
    return _rescale(np.repeat(c, 2))


def _lift_odd(c):
    n = c.size
    h = np.zeros(2 * n + 2)
    h[1:2 * n + 1] = np.repeat(c, 2)
    return _rescale(h)


def _rotation_variants(best):
    n = best.size
    variants = []
    c_even = best[0::2].copy()
    variants.append(('even', c_even, _lift_repeat))
    if n >= 3:
        c_odd = best[1::2].copy()
        variants.append(('odd', c_odd, _lift_odd))
    m = min(best[0::2].size, best[1::2].size)
    c_avg = 0.5 * (best[0::2][:m] + best[1::2][:m])
    variants.append(('avg', c_avg, _lift_repeat))
    return variants


def _stride3_cycle(best, bestR, deadline, cyc):
    """Mass-fold at stride 3, polish, expand two ways, full-N polish."""
    N = best.size
    m = N // 3
    if m < 4:
        return None, -1.0
    c = best[0:3 * m].reshape(m, 3).sum(axis=1)
    c = _rescale(c)
    dl = deadline
    if time.process_time() >= dl - 1.0:
        return None, -1.0
    c = _lbfgs_all_pos(c, 120, dl, beta=1e6)
    if time.process_time() < dl - 1.0:
        c = _lbfgs_all_pos(c, 120, dl, beta=1e7)
    if time.process_time() < dl - 1.0:
        c = _lbfgs_all_pos(c, 120, dl, beta=0.0)
    cR = R_of(c)
    print("stride3 cyc%d R(c)=%.9f" % (cyc, cR))

    # candidate A: plain repeat padded to N
    hA = np.zeros(N)
    hA[:3 * m] = np.repeat(c, 3)
    hA = _rescale(hA)
    rA = R_of(hA)

    # candidate B: phase-jittered repeat
    rs = np.random.RandomState(31337 + cyc)
    w = np.exp(0.35 * rs.randn(3))
    w = w * 3.0 / w.sum()
    hB = np.zeros(N)
    hB[:3 * m] = np.repeat(c, 3) * np.tile(w, m)
    hB = _rescale(hB)
    rB = R_of(hB)

    if rB > rA:
        h, which = hB, 'B'
    else:
        h, which = hA, 'A'
    print("stride3 cyc%d expand winner=%s (rA=%.9f rB=%.9f)" % (cyc, which, rA, rB))

    if time.process_time() < dl - 1.0:
        h = _lbfgs_all_pos(h, 150, dl, beta=1e6)
    if time.process_time() < dl - 1.0:
        h = _lbfgs_all_pos(h, 150, dl, beta=1e7)
    if time.process_time() < dl - 1.0:
        h = _lbfgs_block(h, _peak_window(h, 0.06, 128), 250, dl, beta=1e7)
    if time.process_time() < dl - 1.0:
        h = _lbfgs_all_pos(h, 200, dl, beta=0.0)
    return h, R_of(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish (short) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.20
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: stride-3 mass fold cycles + stride-2 rotation competition ----
    cascade_start = t0 + budget_seconds * 0.20
    cascade_end = deadline - 3.0
    if time.process_time() < cascade_start:
        while time.process_time() < cascade_start - 0.05:
            time.sleep(0.005)

    cyc = 0
    while cyc < 3 and time.process_time() < cascade_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 12.0, deadline - 4.0)
        if slice_dl <= now + 0.8:
            break

        # ---- stride-3 mass fold ----
        h3, r3 = _stride3_cycle(best, bestR, slice_dl, cyc)
        if h3 is not None:
            if r3 > bestR + 5e-14:
                best, bestR, origin = h3.copy(), r3, 's3_%d' % cyc
                print("stride3 cyc%d ACCEPT R=%.9f" % (cyc, bestR))
            else:
                print("stride3 cyc%d reject R=%.9f best=%.9f" % (cyc, r3, bestR))
                if r3 > alt_bestR:
                    alt_best, alt_bestR = h3.copy(), r3

        # ---- stride-2 rotation (competition) ----
        if time.process_time() < slice_dl - 1.0:
            variants = _rotation_variants(best)
            order = ['even', 'odd', 'avg']
            rot = cyc % len(order)
            order = order[rot:] + order[:rot]
            vmap = {name: (c, lift) for name, c, lift in variants}
            rot_best_h = None
            rot_bestR = -1.0
            rot_name = None
            for name in order:
                if time.process_time() > slice_dl - 1.5:
                    break
                c, lift = vmap[name]
                c = _polish_quotient(c, slice_dl - 0.8, maxiter=80)
                if time.process_time() > slice_dl - 1.5:
                    break
                h = lift(c)
                if time.process_time() < slice_dl - 1.5:
                    h = _lbfgs_all_pos(h, 120, slice_dl - 0.8, beta=1e7)
                r = R_of(h)
                if r > rot_bestR:
                    rot_best_h, rot_bestR, rot_name = h, r, name
            if rot_best_h is not None:
                print("cycle %d rot winner=%s R=%.9f" % (cyc, rot_name, rot_bestR))
                if rot_bestR > bestR + 5e-14:
                    best, bestR, origin = rot_best_h.copy(), rot_bestR, 'rot_%s_%d' % (rot_name, cyc)
                    print("cycle %d rot ACCEPT best=%.9f" % (cyc, bestR))
                elif rot_bestR > alt_bestR:
                    alt_best, alt_bestR = rot_best_h.copy(), rot_bestR
        cyc += 1

    # ---- Phase 3: final pad ladder + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _resample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    new_n = n * factor
    x_new = np.linspace(0.0, 1.0, new_n, endpoint=False)
    return np.interp(x_new, x_old, h, right=h[-1])


# ---- NEW IDEA: peak-tracking local refinement --------------------------
# The bottleneck is the shape of f*f near its maximum: R is bounded by how
# "flat and wide" the top of f*f is relative to its L2 mass. Instead of
# global L-BFGS (which spends time on far tails that barely matter), do many
# short block optimizations on progressively tighter windows around the peak,
# each followed by a full-array rescale. This concentrates gradient signal
# on the knots that actually constrain R (those near ||f*f||_inf).

def _refine_peak(h, deadline, rounds=6, base_frac=0.5):
    best = h.copy()
    bestR = R_of(best)
    work = best.copy()
    for k in range(rounds):
        if time.process_time() >= deadline - 0.4:
            break
        # progressively tighter peak window
        pad_frac = base_frac * (0.6 ** k)
        win = _peak_window(work, tol=0.999, pad_frac=pad_frac,
                           extra=max(48, 256 >> k))
        # alternate sharp (beta) and plain L2 objectives
        beta = 1e8 if (k % 2 == 0) else 0.0
        ht = _lbfgs_block(work, win, maxiter=180, deadline=deadline - 0.3,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
        else:
            work = ht  # still move; may escape a plateau
    return best, bestR


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e8), (0.25, 128, 1e8), (0.40, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _trim_to_support(h, lo_frac=0.0, hi_frac=1.0):
    n = h.size
    lo = int(lo_frac * n)
    hi = max(lo + 8, int(hi_frac * n))
    return h[lo:hi].copy()


def _pad_back(h, n_target):
    n = h.size
    if n >= n_target:
        return h[:n_target].copy() if n > n_target else h.copy()
    out = np.zeros(n_target)
    off = (n_target - n) // 2
    out[off:off + n] = h
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: base machinery
    if time.process_time() < deadline - 8.0:
        ht, rt = run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR, origin = ht, rt, origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # Phase B: peak-tracking refinement (the new idea)
    if time.process_time() < deadline - 3.0:
        ht, rt = _refine_peak(best, deadline - 3.0, rounds=8, base_frac=0.5)
        print("peak-refine R=%.9f" % rt)
        if rt > bestR + 1e-13:
            best, bestR, origin = ht, rt, origin + '+peak'

    # Phase C: fine-grid resample then peak refine again
    if time.process_time() < deadline - 2.0:
        try:
            hf = _resample(best, 2)
            if hf.size <= 900000:
                hf = _rescale(hf)
                hf, rf = run_cycle(hf, R_of(hf), deadline - 2.0)
                print("resample x2: R=%.9f (N=%d)" % (rf, hf.size))
                if rf > bestR + 1e-13:
                    best, bestR, origin = hf, rf, origin + '+fine'
        except Exception as e:
            print("resample failed: %s" % e)

    # Phase D: final peak polish on tightest windows
    if time.process_time() < deadline - 0.5:
        ht, rt = _refine_peak(best, deadline - 0.3, rounds=6, base_frac=0.2)
        print("final peak R=%.9f" % rt)
        if rt > bestR + 1e-13:
            best, bestR, origin = ht, rt, origin + '+fpeak'

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _polish_quotient(c, deadline, maxiter=100):
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_all_pos(c, maxiter, deadline, beta=beta)
    return c


def _lift_repeat(c):
    return _rescale(np.repeat(c, 2))


def _lift_odd(c):
    n = c.size
    h = np.zeros(2 * n + 2)
    h[1:2 * n + 1] = np.repeat(c, 2)
    return _rescale(h)


def _rotation_variants(best):
    n = best.size
    variants = []
    c_even = best[0::2].copy()
    variants.append(('even', c_even, _lift_repeat))
    if n >= 3:
        c_odd = best[1::2].copy()
        variants.append(('odd', c_odd, _lift_odd))
    m = min(best[0::2].size, best[1::2].size)
    c_avg = 0.5 * (best[0::2][:m] + best[1::2][:m])
    variants.append(('avg', c_avg, _lift_repeat))
    return variants


def _edge_extension(h, side, K):
    """Pad K zeros on `side` ('left'/'right'), fill with geometric continuation."""
    h = np.clip(h, 0, None)
    mx = h.max()
    if mx <= 0:
        return None
    thr = 1e-4 * mx
    nz = np.flatnonzero(h > thr)
    if nz.size < 2:
        return None
    i = nz[0]
    j = nz[-1]
    if side == 'left':
        if i < 1:
            return None
        rL = h[i + 1] / h[i] if h[i] > 0 else 1.0
        rL = float(np.clip(rL, 0.5, 1.5))
        new = np.zeros(h.size + K)
        new[K:] = h
        edge_val = h[i]
        for d in range(1, K + 1):
            idx = K - d
            if idx < 0:
                break
            new[idx] = edge_val * (rL ** d)
        return _rescale(new)
    else:
        if j >= h.size - 1:
            return None
        rR = h[j - 1] / h[j] if h[j] > 0 else 1.0
        rR = float(np.clip(rR, 0.5, 1.5))
        new = np.zeros(h.size + K)
        new[:h.size] = h
        edge_val = h[j]
        for d in range(1, K + 1):
            idx = h.size + d - 1
            if idx >= new.size:
                break
            new[idx] = edge_val * (rR ** d)
        return _rescale(new)


def _polish_extension(cand, side, K, slice_dl):
    h = cand
    if time.process_time() < slice_dl - 1.0:
        h = _lbfgs_all_pos(h, 120, slice_dl, beta=1e7)
    if time.process_time() < slice_dl - 1.0:
        n = h.size
        if side == 'left':
            edge_region = np.arange(0, min(n, K + 32))
        else:
            edge_region = np.arange(max(0, n - K - 32), n)
        peak = _peak_window(h, pad_frac=0.10, extra=128)
        free = np.unique(np.concatenate([edge_region, peak]))
        h = _lbfgs_block(h, free, 250, slice_dl, beta=1e7)
    if time.process_time() < slice_dl - 1.0:
        h = _lbfgs_all_pos(h, 200, slice_dl, beta=0.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish (short) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.20
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: stride-2 rotation + stride-4 coarse-to-fine cascade ----
    cascade_start = t0 + budget_seconds * 0.20
    cascade_end = deadline - 8.0
    if time.process_time() < cascade_start:
        while time.process_time() < cascade_start - 0.05:
            time.sleep(0.005)
    cyc = 0
    while cyc < 2 and time.process_time() < cascade_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 8.0, deadline - 8.0)
        if slice_dl <= now + 0.8:
            break

        variants = _rotation_variants(best)
        order = ['even', 'odd', 'avg']
        rot = cyc % len(order)
        order = order[rot:] + order[:rot]
        vmap = {name: (c, lift) for name, c, lift in variants}

        rot_best_h = None
        rot_bestR = -1.0
        rot_name = None
        for name in order:
            if time.process_time() > slice_dl - 2.0:
                break
            c, lift = vmap[name]
            c = _polish_quotient(c, slice_dl - 1.0, maxiter=80)
            if time.process_time() > slice_dl - 2.0:
                break
            h = lift(c)
            if time.process_time() < slice_dl - 2.0:
                h = _lbfgs_all_pos(h, 120, slice_dl - 1.0, beta=1e7)
            r = R_of(h)
            if r > rot_bestR:
                rot_best_h, rot_bestR, rot_name = h, r, name

        if rot_best_h is None:
            break
        print("cycle %d rot winner=%s R=%.9f" % (cyc, rot_name, rot_bestR))

        work = rot_best_h
        if work.size >= 8 and work.size % 4 == 0 and time.process_time() < slice_dl - 1.0:
            c4 = work[0::4].copy()
            if time.process_time() < slice_dl - 1.0:
                c4 = _lbfgs_all_pos(c4, 100, slice_dl, beta=1e6)
            if time.process_time() < slice_dl - 1.0:
                c4 = _lbfgs_all_pos(c4, 100, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 1.0:
                c4 = _lbfgs_all_pos(c4, 100, slice_dl, beta=0.0)
            if time.process_time() < slice_dl - 1.0:
                w = np.exp(0.25 * np.random.RandomState(1000 + cyc).randn(2))
                w = w * 2.0 / w.sum()
                c2 = _rescale(np.repeat(c4, 2) * np.tile(w, c4.size))
                if time.process_time() < slice_dl - 1.0:
                    c2 = _half_cycle(c2, R_of(c2), slice_dl, tag='s4_%d' % cyc)[1]
                h = _rescale(np.repeat(c2, 2))
                if time.process_time() < slice_dl - 1.0:
                    h = _lbfgs_all_pos(h, 120, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 1.0:
                    h = _lbfgs_all_pos(h, 120, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 1.0:
                    h = _lbfgs_block(h, _peak_window(h, 0.06, 128), 200, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 1.0:
                    h = _lbfgs_all_pos(h, 150, slice_dl, beta=0.0)
                r_h = R_of(h)
                if r_h > rot_bestR:
                    work, rot_bestR = h, r_h

        r_h = rot_bestR
        accepted = r_h > bestR + 5e-14
        if accepted:
            best, bestR, origin = work.copy(), r_h, 'rot_%s_%d' % (rot_name, cyc)
        elif r_h > alt_bestR:
            alt_best, alt_bestR = work.copy(), r_h
        print("cycle %d R(h)=%.9f %s best=%.9f"
              % (cyc, r_h, "ACCEPT" if accepted else "reject", bestR))
        cyc += 1

    # ---- Phase 3: support extension via geometric edge continuation ----
    ext_round = 0
    while ext_round < 3 and time.process_time() < deadline - 8.0:
        now = time.process_time()
        slice_dl = min(now + 10.0, deadline - 5.0)
        if slice_dl <= now + 1.0:
            break
        cands = []
        for side in ['left', 'right']:
            for K in [16, 64]:
                if time.process_time() > slice_dl - 2.0:
                    break
                cand = _edge_extension(best, side, K)
                if cand is None:
                    continue
                cand = _polish_extension(cand, side, K, slice_dl)
                r = R_of(cand)
                cands.append((r, side, K, cand))
        if not cands:
            break
        cands.sort(key=lambda t: -t[0])
        r_best, side_best, K_best, cand_best = cands[0]
        if r_best > bestR + 1e-12:
            old_n = best.size
            best = cand_best
            bestR = r_best
            new_n = best.size
            if side_best == 'left':
                new_cells = best[:new_n - old_n]
            else:
                new_cells = best[old_n:]
            frac = new_cells.sum() / best.sum() if best.sum() > 0 else 0.0
            origin = 'ext_%s_%d' % (side_best, K_best)
            print("ext ACCEPT side=%s K=%d R=%.9f newmass=%.4f"
                  % (side_best, K_best, bestR, frac))
        else:
            print("ext round %d no accept (best cand R=%.9f)" % (ext_round, r_best))
            if r_best > alt_bestR:
                alt_best, alt_bestR = cand_best, r_best
            break
        ext_round += 1

    # ---- Phase 4: final polish ----
    if time.process_time() < deadline - 1.0:
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 0.8:
                break
            ht = _lbfgs_all_pos(best, 250, deadline - 0.4, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, origin + '+b%g' % beta
                print("final beta%g NEW BEST R=%.9f" % (beta, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    if time.process_time() < deadline - 0.8:
        for pad in [0.12, 0.08, 0.06, 0.05]:
            if time.process_time() >= deadline - 0.6:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _polish_quotient(c, deadline, maxiter=100):
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_all_pos(c, maxiter, deadline, beta=beta)
    return c


def _lift_repeat(c):
    return _rescale(np.repeat(c, 2))


def _lift_odd(c):
    n = c.size
    h = np.zeros(2 * n + 2)
    h[1:2 * n + 1] = np.repeat(c, 2)
    return _rescale(h)


def _rotation_variants(best):
    n = best.size
    variants = []
    c_even = best[0::2].copy()
    variants.append(('even', c_even, _lift_repeat))
    if n >= 3:
        c_odd = best[1::2].copy()
        variants.append(('odd', c_odd, _lift_odd))
    m = min(best[0::2].size, best[1::2].size)
    c_avg = 0.5 * (best[0::2][:m] + best[1::2][:m])
    variants.append(('avg', c_avg, _lift_repeat))
    return variants


def _resample_mass(h, L, rng=None, jitter=0.0):
    """Mass-preserving resample of step function h (length N) to length L.
    Uses cumulative mass interpolation at positions x_k = k*(N/L) [+ jitter]."""
    N = h.size
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    if total <= 0:
        return np.zeros(L)
    # knot positions in [0, N] for cum
    knots_x = np.arange(N + 1, dtype=float)
    # target positions in [0, N]
    k = np.arange(L + 1, dtype=float)
    x = k * (N / float(L))
    if jitter > 0 and rng is not None:
        x = x + jitter * rng.uniform(-1.0, 1.0, size=L + 1)
        x[0] = 0.0
        x[-1] = float(N)
    x = np.clip(x, 0.0, float(N))
    vals = np.interp(x, knots_x, cum)
    vals = np.maximum.accumulate(vals)
    vals = np.clip(vals, 0.0, total)
    hL = np.diff(vals)
    hL = np.clip(hL, 0.0, None)
    return hL


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish (short) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.20
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: stride-2 rotation + stride-4 coarse-to-fine cascade ----
    cascade_start = t0 + budget_seconds * 0.20
    cascade_end = deadline - 4.0
    if time.process_time() < cascade_start:
        while time.process_time() < cascade_start - 0.05:
            time.sleep(0.005)
    cyc = 0
    while cyc < 2 and time.process_time() < cascade_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 10.0, deadline - 5.0)
        if slice_dl <= now + 0.8:
            break

        variants = _rotation_variants(best)
        order = ['even', 'odd', 'avg']
        rot = cyc % len(order)
        order = order[rot:] + order[:rot]
        vmap = {name: (c, lift) for name, c, lift in variants}

        rot_best_h = None
        rot_bestR = -1.0
        rot_name = None
        for name in order:
            if time.process_time() > slice_dl - 2.0:
                break
            c, lift = vmap[name]
            c = _polish_quotient(c, slice_dl - 1.0, maxiter=80)
            if time.process_time() > slice_dl - 2.0:
                break
            h = lift(c)
            if time.process_time() < slice_dl - 2.0:
                h = _lbfgs_all_pos(h, 120, slice_dl - 1.0, beta=1e7)
            r = R_of(h)
            if r > rot_bestR:
                rot_best_h, rot_bestR, rot_name = h, r, name

        if rot_best_h is None:
            break
        print("cycle %d rot winner=%s R=%.9f" % (cyc, rot_name, rot_bestR))

        work = rot_best_h
        r_h = rot_bestR
        accepted = r_h > bestR + 5e-14
        if accepted:
            best, bestR, origin = work.copy(), r_h, 'rot_%s_%d' % (rot_name, cyc)
        elif r_h > alt_bestR:
            alt_best, alt_bestR = work.copy(), r_h
        print("cycle %d R(h)=%.9f %s best=%.9f"
              % (cyc, r_h, "ACCEPT" if accepted else "reject", bestR))
        cyc += 1

    # ---- Phase 3: 5:4 non-commensurate resample loop ----
    resample_end = deadline - 0.5
    rnd = 0
    while rnd < 3 and time.process_time() < resample_end - 8.0:
        now = time.process_time()
        slice_dl = min(now + 14.0, deadline - 6.0)
        if slice_dl <= now + 5.0:
            break
        N = best.size
        L = int(round(1.25 * N))
        rng = np.random.RandomState(20000 + rnd)
        hL = _resample_mass(best, L, rng=rng, jitter=0.2)
        hL = _rescale(hL)
        rL0 = R_of(hL)
        ht = _lbfgs_all_pos(hL, 60, slice_dl, beta=1e7)
        rL1 = R_of(ht)
        print("round %d: L=%d R(hL)=%.9f after1=%.9f" % (rnd, L, rL0, rL1))

        # polish at L
        if time.process_time() < slice_dl - 1.0:
            ht = _lbfgs_all_pos(ht, 150, slice_dl, beta=1e6)
        if time.process_time() < slice_dl - 1.0:
            ht = _lbfgs_all_pos(ht, 150, slice_dl, beta=1e7)
        for pad in [0.15, 0.10]:
            if time.process_time() >= slice_dl - 1.0:
                break
            win = _peak_window(ht, pad_frac=pad, extra=128)
            ht = _lbfgs_block(ht, win, 300, slice_dl, beta=1e7)
        if time.process_time() < slice_dl - 1.0:
            ht = _lbfgs_all_pos(ht, 150, slice_dl, beta=0.0)
        rL2 = R_of(ht)
        print("round %d: polished L R=%.9f" % (rnd, rL2))

        # fold back to N
        hN = _resample_mass(ht, N, rng=None, jitter=0.0)
        hN = _rescale(hN)
        if time.process_time() < slice_dl - 0.5:
            hN = _lbfgs_all_pos(hN, 80, slice_dl, beta=1e7)
        if time.process_time() < slice_dl - 0.3:
            hN = _lbfgs_all_pos(hN, 120, slice_dl, beta=0.0)
        rN = R_of(hN)
        print("round %d: folded R=%.9f (best %.9f)" % (rnd, rN, bestR))
        if rN > bestR + 1e-12:
            best, bestR, origin = hN.copy(), rN, 'resample%d' % rnd
            print("round %d: NEW BEST R=%.9f" % (rnd, bestR))
        elif rN > alt_bestR:
            alt_best, alt_bestR = hN.copy(), rN
        rnd += 1

    # ---- Phase 4: final polish on surviving best ----
    if time.process_time() < deadline - 1.0:
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 0.8:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, origin + '+b%g' % beta
                print("final beta%g NEW BEST R=%.9f" % (beta, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    if time.process_time() < deadline - 0.8:
        for pad in [0.12, 0.08, 0.06]:
            if time.process_time() >= deadline - 0.6:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r

    # ---- Phase A: half-resolution quotient polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.18
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase B: spectral-shift / convolution smoothing (new idea) ----
    # Idea: the maximiser is a "triangle-like" shape whose autoconvolution peak
    # is flat. Applying a small Gaussian smoothing to the level-set of the
    # current best (in cell space) can help escape local optima; then re-polish.
    if time.process_time() < deadline - 3.0 and best.size < 500000:
        try:
            from scipy.ndimage import gaussian_filter1d
            for sigma in (0.6, 1.2, 2.0):
                if time.process_time() >= deadline - 2.0:
                    break
                sm = gaussian_filter1d(best.astype(float), sigma=sigma, mode='nearest')
                sm = np.clip(sm, 0, None)
                sm = _rescale(sm)
                sm = _polish_ladder(sm, deadline - 1.0, betas=(1e7, 0.0), iters=250)
                offer(sm, 'smooth%.1f' % sigma)
        except Exception:
            pass

    # ---- Phase C: sub-cell spike-shift sweeps ----
    def _find_runs(h, min_frac=0.02):
        nz = h > 0
        if not nz.any():
            return []
        thr = min_frac * h.max()
        runs = []
        i, n = 0, h.size
        while i < n:
            if nz[i]:
                j = i
                while j + 1 < n and nz[j + 1]:
                    j += 1
                if h[i:j + 1].sum() >= thr:
                    runs.append((i, j))
                i = j + 1
            else:
                i += 1
        return runs

    def _shift_run(h, i, j, delta):
        prof = h[i:j + 1].copy()
        n = h.size
        out = h.copy()
        out[i:j + 1] = 0.0
        for k in range(prof.size):
            pos = (i + k) + delta
            lo = int(np.floor(pos))
            frac = pos - lo
            if 0 <= lo < n:
                out[lo] += prof[k] * (1.0 - frac)
            if 0 <= lo + 1 < n:
                out[lo + 1] += prof[k] * frac
        return np.clip(out, 0.0, None)

    def _repair(h, i, j, dl, iters=80):
        win = np.arange(max(0, i - 48), min(h.size, j + 49))
        pk = _peak_window(h, 0.10, 64)
        win = np.union1d(win, pk)
        return _lbfgs_block(h, win, iters, dl, beta=1e7)

    sweep_deadline = deadline - 3.0
    rng = np.random.RandomState(12345)
    sweep = 0
    while time.process_time() < sweep_deadline - 1.0:
        runs = _find_runs(best, min_frac=0.02)
        if not runs:
            break
        order = list(range(len(runs)))
        rng.shuffle(order)
        moved = None
        movedR = bestR
        tried = 0
        for ri in order:
            if time.process_time() > sweep_deadline - 1.5:
                break
            i, j = runs[ri]
            for delta in (0.5, -0.5):
                if time.process_time() > sweep_deadline - 1.5:
                    break
                cand = _shift_run(best, i, j, delta)
                if cand.sum() <= 0:
                    continue
                cand = _rescale(cand)
                cand = _repair(cand, i, j, sweep_deadline - 0.5, iters=80)
                r = R_of(cand)
                tried += 1
                if r > movedR + 1e-9:
                    moved, movedR = cand, r
        if moved is not None:
            best, bestR = moved, movedR
            print("sweep %d tried=%d ACCEPT R=%.9f" % (sweep, tried, bestR))
        else:
            print("sweep %d tried=%d no improvement best=%.9f" % (sweep, tried, bestR))

        if sweep % 4 == 3 and time.process_time() < sweep_deadline - 1.0:
            ht = _polish_ladder(best, sweep_deadline - 0.5, betas=(1e6, 1e7, 0.0), iters=200)
            if R_of(ht) > bestR + 1e-14:
                best, bestR = ht, R_of(ht)
            win = _peak_window(best, 0.06, 128)
            ht = _lbfgs_block(best, win, 300, sweep_deadline - 0.5, beta=1e7)
            if R_of(ht) > bestR + 1e-14:
                best, bestR = ht, R_of(ht)
            print("sweep %d post-ladder R=%.9f" % (sweep, bestR))
        sweep += 1

    # ---- Phase D: final pad ladder + beta=0 polish ----
    ht = _peak_ladder(best, deadline - 1.0, pads=(0.10, 0.06, 0.04), iters=400)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _interlace(best, t):
    """Interlace fresh mass in the gaps: h2[0::2]=best, h2[1::2]=t*avg(neighbors)."""
    n = best.size
    h2 = np.zeros(2 * n)
    h2[0::2] = best
    right = np.append(best[1:], best[-1])
    fill = 0.5 * (right + best)
    h2[1::2] = t * fill
    return _rescale(h2)


def _polish(h2, slice_dl, pads=(0.20, 0.12, 0.08)):
    h = h2
    if time.process_time() < slice_dl - 1.0:
        h = _lbfgs_all_pos(h, 150, slice_dl, beta=1e6)
    if time.process_time() < slice_dl - 1.0:
        h = _lbfgs_all_pos(h, 150, slice_dl, beta=1e7)
    for pad in pads:
        if time.process_time() >= slice_dl - 1.0:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        h = _lbfgs_block(h, win, 400, slice_dl, beta=1e7)
    if time.process_time() < slice_dl - 1.0:
        h = _lbfgs_all_pos(h, 200, slice_dl, beta=0.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Interlace portfolio over fill factors ----
    fills = [0.5, 1.0, 1.5]
    cand_best = None
    cand_bestR = -1.0
    cand_t = None
    for t in fills:
        now = time.process_time()
        if now > deadline - 12.0:
            break
        slice_dl = min(now + 12.0, deadline - 6.0)
        if slice_dl <= now + 1.0:
            break
        h2 = _interlace(best, t)
        r0 = R_of(h2)
        print("interlace t=%.2f raw R=%.9f (d=%.2e)" % (t, r0, r0 - bestR))
        h = _polish(h2, slice_dl)
        r = R_of(h)
        print("interlace t=%.2f polished R=%.9f" % (t, r))
        if r > cand_bestR:
            cand_best, cand_bestR, cand_t = h, r, t
        if r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r

    accepted = False
    if cand_best is not None and cand_bestR > bestR + 1e-12:
        best, bestR, origin = cand_best.copy(), cand_bestR, 'interlace_t%.2f' % cand_t
        accepted = True
        print("interlace ACCEPT t=%.2f R=%.9f" % (cand_t, bestR))

    # ---- Extra interlace round with winning t +- 0.25 ----
    if cand_t is not None:
        for dt in [0.25, -0.25]:
            now = time.process_time()
            if now > deadline - 8.0:
                break
            t2 = cand_t + dt
            if t2 <= 0:
                continue
            slice_dl = min(now + 10.0, deadline - 5.0)
            if slice_dl <= now + 1.0:
                break
            h2 = _interlace(best, t2)
            r0 = R_of(h2)
            print("interlace2 t=%.2f raw R=%.9f" % (t2, r0))
            h = _polish(h2, slice_dl)
            r = R_of(h)
            print("interlace2 t=%.2f polished R=%.9f" % (t2, r))
            if r > bestR + 1e-12:
                best, bestR, origin = h.copy(), r, 'interlace2_t%.2f' % t2
                print("interlace2 NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = h.copy(), r

    # ---- Final full polish ----
    if time.process_time() < deadline - 1.0:
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 0.8:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, origin + '+b%g' % beta
                print("final beta%g NEW BEST R=%.9f" % (beta, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
    if time.process_time() < deadline - 1.0:
        for pad in [0.12, 0.08, 0.06]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.4, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    zf = float(np.mean(best <= 0))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zerofrac=%.3f)" %
          (bestR, origin, start_bestR, best.size, zf))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

