def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _refine_peak(h, deadline, label=""):
    """Aggressively refine around the peak with tight beta and beta=0."""
    best = h.copy()
    bestR = R_of(best)
    pads = [0.08, 0.05, 0.03, 0.02, 0.012, 0.008]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, tol=0.99999, pad_frac=pad, extra=64)
        ht = _lbfgs_block(best, win, 500, deadline - 0.3, beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, tol=0.99999, pad_frac=pad, extra=64)
            ht = _lbfgs_block(best, win, 500, deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht, r
    return best, bestR


def _lift_split(c, seed, slice_dl, maxiter=80):
    rs = np.random.RandomState(seed)
    w = np.exp(0.25 * rs.randn(2))
    w = w * 2.0 / w.sum()
    h = _rescale(np.repeat(c, 2) * np.tile(w, c.size))
    if time.process_time() < slice_dl - 1.5:
        h = _lbfgs_all_pos(h, maxiter, slice_dl - 1.0, beta=1e7)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: peak-focused high-beta / beta=0 refinement of start ----
    # The dominant gains are local: put most of the budget into the peak region.
    phase1_end = t0 + budget_seconds * 0.55
    ht, rt = _refine_peak(best, phase1_end)
    if rt > bestR + 1e-15:
        best, bestR, origin = ht.copy(), rt, 'peak'
        print("peak phase NEW BEST R=%.9f" % bestR)
    elif rt > alt_bestR:
        alt_best, alt_bestR = ht.copy(), rt

    # One full-resolution beta-polish pass after peak refinement.
    if time.process_time() < phase1_end - 1.0:
        for beta in [1e7, 1e8, 0.0]:
            if time.process_time() >= phase1_end - 0.8:
                break
            ht = _lbfgs_all_pos(best, 300, phase1_end - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, origin + '+b%g' % beta
                print("full-beta NEW BEST R=%.9f (beta=%g)" % (bestR, beta))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: fine peak polish with remaining time ----
    phase2_end = deadline - 0.8
    ht, rt = _refine_peak(best, phase2_end)
    if rt > bestR + 1e-15:
        best, bestR, origin = ht.copy(), rt, origin + '+pk2'
        print("phase2 peak NEW BEST R=%.9f" % bestR)
    elif rt > alt_bestR:
        alt_best, alt_bestR = ht.copy(), rt

    if time.process_time() < phase2_end - 1.0:
        ht = _lbfgs_all_pos(best, 300, phase2_end - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _refine(h):
    """Duplicate each cell into two equal halves (exact resampling)."""
    return np.repeat(h, 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    print("base R=%.9f N=%d" % (baseR, baseH.size))

    # Start from a 2x refinement of the start (gives the optimiser room to
    # reshape near the peak). If the start is already very large, keep it.
    if baseH.size <= 500000:
        h2 = _rescale(_refine(baseH))
    else:
        h2 = baseH.copy()
    r2 = R_of(h2)
    print("refined N=%d R=%.9f (base %.9f)" % (h2.size, r2, baseR))

    bestH = h2.copy()
    bestR = r2
    # The alternative we hand back should be genuinely different from start;
    # the refined-then-optimised construction qualifies.
    alternative = h2.copy()
    alternativeR = r2

    def maybe_update(hnew, rnew, tag=""):
        nonlocal bestH, bestR, alternative, alternativeR
        if rnew > bestR + 1e-14:
            bestH, bestR = hnew.copy(), rnew
            if rnew > alternativeR + 1e-14:
                alternative, alternativeR = hnew.copy(), rnew
            if tag:
                print("  %s R=%.9f" % (tag, bestR))
            return True
        return False

    # ---- Phase 1: aggressive beta-smoothing passes to escape local maxima ----
    for beta in (1e4, 1e5, 1e6):
        if time.process_time() >= deadline - 3.0:
            break
        cap = min(deadline - 2.0, time.process_time() + 6.0)
        hs = _lbfgs_log(bestH, 250, cap, beta=beta)
        rs = R_of(hs)
        print("  beta=%.0e -> R=%.9f" % (beta, rs))
        maybe_update(hs, rs, "beta")
        # peak-window polish
        if time.process_time() < deadline - 3.0:
            free = _peak_window(bestH, pad_frac=0.25, extra=512)
            cap = min(deadline - 2.0, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 200, cap, beta=0.0)
            rp = R_of(hp)
            maybe_update(hp, rp, "peak")

    # ---- Phase 2: alternating global + peak-window refinement ----
    it = 0
    loop_end = deadline - 2.5
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if maybe_update(hs, rs, "iter%d global" % it):
            continue
        if time.process_time() < loop_end - 1.0:
            pads = [0.40, 0.25, 0.15, 0.10, 0.06]
            pad = pads[it % len(pads)]
            free = _peak_window(bestH, pad_frac=pad, extra=384)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 200, cap, beta=0.0)
            rp = R_of(hp)
            maybe_update(hp, rp, "iter%d peak pad=%.2f" % (it, pad))

    # ---- Phase 3: one more refinement step if budget remains ----
    if time.process_time() < deadline - 1.5 and bestH.size <= 480000:
        hr = _rescale(_refine(bestH))
        rr = R_of(hr)
        if rr > bestR - 1e-9:
            cap = min(deadline - 0.5, time.process_time() + 6.0)
            hs = _lbfgs_log(hr, 200, cap, beta=0.0)
            rs = R_of(hs)
            print("  refine -> R=%.9f (was %.9f)" % (rs, bestR))
            maybe_update(hs, rs, "refine")

    # ---- Final polish ----
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hs = _lbfgs_log(bestH, 100, cap, beta=0.0)
        rs = R_of(hs)
        maybe_update(hs, rs, "final")

    print("done bestR=%.9f altR=%.9f baseR=%.9f N=%d" %
          (bestR, alternativeR, baseR, bestH.size))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": alternative}
    else:
        return {"best": baseH, "alternative": alternative}

