    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _find_runs(h, min_frac=0.02):
    nz = h > 0
    if not nz.any():
        return []
    thr = min_frac * h.max()
    runs = []
    i, n = 0, h.size
    while i < n:
        if nz[i]:
            j = i
            while j + 1 < n and nz[j + 1]:
                j += 1
            if h[i:j + 1].sum() >= thr:
                runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _shift_run(h, i, j, delta):
    prof = h[i:j + 1].copy()
    n = h.size
    out = h.copy()
    out[i:j + 1] = 0.0
    for k in range(prof.size):
        pos = (i + k) + delta
        lo = int(np.floor(pos))
        frac = pos - lo
        if 0 <= lo < n:
            out[lo] += prof[k] * (1.0 - frac)
        if 0 <= lo + 1 < n:
            out[lo + 1] += prof[k] * frac
    return np.clip(out, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r

    N = best.size
    rng = np.random.RandomState(987654321)

    def make_lift(c, s, variant):
        k = s
        m = c.size
        out = np.empty(m * k, dtype=float)
        if variant == 'eq':
            w = np.ones(k)
        elif variant == 'ln025':
            w = np.exp(rng.randn(k) * 0.25)
        elif variant == 'ln050':
            w = np.exp(rng.randn(k) * 0.50)
        elif variant == 'ramp':
            w = 0.5 + np.arange(k, dtype=float) / max(1, k)
        else:
            w = np.ones(k)
        w = w / w.mean()
        for j in range(k):
            out[j::k] = c * w[j]
        return _rescale(out)

    def make_odd_lift(c):
        m = c.size
        out = np.zeros(m * 2 + 2, dtype=float)
        for j in range(m):
            out[2 * j + 1] = c[j]
            out[2 * j + 2] = c[j]
        # trim to N
        if out.size > N:
            out = out[:N]
        elif out.size < N:
            out = np.concatenate([out, np.zeros(N - out.size)])
        return _rescale(out)

    def subcell_sweep(h, dl, rounds=1):
        cur = h
        curR = R_of(cur)
        for _ in range(rounds):
            if time.process_time() > dl - 1.0:
                break
            runs = _find_runs(cur, min_frac=0.02)
            if not runs:
                break
            order = list(range(len(runs)))
            rng.shuffle(order)
            moved = None
            movedR = curR
            for ri in order:
                if time.process_time() > dl - 1.0:
                    break
                i, j = runs[ri]
                for delta in (0.5, -0.5):
                    if time.process_time() > dl - 1.0:
                        break
                    cand = _shift_run(cur, i, j, delta)
                    if cand.sum() <= 0:
                        continue
                    cand = _rescale(cand)
                    win = np.arange(max(0, i - 48), min(cur.size, j + 49))
                    pk = _peak_window(cand, 0.10, 64)
                    win = np.union1d(win, pk)
                    cand = _lbfgs_block(cand, win, 80, dl - 0.5, beta=1e7)
                    r = R_of(cand)
                    if r > movedR + 1e-9:
                        moved, movedR = cand, r
            if moved is not None:
                cur, curR = moved, movedR
        return cur

    def gauss_round(h, dl, sigma=1.5):
        try:
            from scipy.ndimage import gaussian_filter1d
            sm = gaussian_filter1d(h.astype(float), sigma=sigma, mode='nearest')
            sm = _rescale(np.clip(sm, 0, None))
            sm = _polish_ladder(sm, dl, betas=(1e7, 0.0), iters=250)
            return sm
        except Exception:
            return h

    # ---- Quotient cascade cycles ----
    cycle = 0
    while time.process_time() < deadline - 9.0 and cycle < 2:
        cycle += 1
        cyc_best = best.copy()
        cyc_bestR = bestR
        for s in (16, 8, 4, 2):
            if time.process_time() > deadline - 9.0:
                break
            if N % s != 0:
                continue
            c = best[0::s].copy()
            if c.sum() <= 0:
                continue
            stage_dl = min(deadline - 6.0,
                           time.process_time() + max(2.0, (deadline - time.process_time()) * 0.35))
            c = _polish_ladder(c, stage_dl, betas=(1e6, 1e7, 0.0), iters=250)
            c = _peak_ladder(c, stage_dl, pads=(0.15, 0.10), iters=250)
            cR = R_of(c)
            # build 4 lifts
            lifts = []
            for variant in ('ln025', 'eq', 'ln050', 'ramp'):
                if time.process_time() > deadline - 8.0:
                    break
                hl = make_lift(c, s, variant)
                hl = _polish_ladder(hl, stage_dl, betas=(1e6, 0.0), iters=200)
                hl = _peak_ladder(hl, stage_dl, pads=(0.08, 0.05), iters=300)
                lifts.append((variant, hl, R_of(hl)))
            if not lifts:
                continue
            variant, hbest, hR = max(lifts, key=lambda t: t[2])
            print("cycle %d s=%d cR=%.9f lift=%s R=%.9f" %
                  (cycle, s, cR, variant, hR))
            if hR > bestR + 1e-9:
                best, bestR = hbest.copy(), hR
                cyc_best, cyc_bestR = best.copy(), bestR
                print("  ACCEPT s=%d R=%.9f" % (s, bestR))

        # odd rotation after s=2
        if N >= 3 and time.process_time() < deadline - 9.0:
            stage_dl = min(deadline - 6.0,
                           time.process_time() + max(2.0, (deadline - time.process_time()) * 0.35))
            c_odd = best[1::2].copy()
            if c_odd.sum() > 0:
                c_odd = _polish_ladder(c_odd, stage_dl, betas=(1e6, 1e7, 0.0), iters=250)
                c_odd = _peak_ladder(c_odd, stage_dl, pads=(0.15, 0.10), iters=250)
                h_odd = make_odd_lift(c_odd)
                h_odd = _polish_ladder(h_odd, stage_dl, betas=(1e6, 0.0), iters=200)
                h_odd = _peak_ladder(h_odd, stage_dl, pads=(0.08, 0.05), iters=300)
                r_odd = R_of(h_odd)
                print("cycle %d odd R=%.9f" % (cycle, r_odd))
                if r_odd > bestR + 1e-9:
                    best, bestR = h_odd.copy(), r_odd
                    cyc_best, cyc_bestR = best.copy(), bestR
                    print("  ACCEPT odd R=%.9f" % bestR)

        # one sub-cell sweep + one gaussian smooth on cycle's best
        if time.process_time() < deadline - 6.0:
            sw = subcell_sweep(best, deadline - 5.0, rounds=1)
            offer(sw, 'cycle%d-sweep' % cycle)
            if R_of(sw) > cyc_bestR + 1e-9:
                cyc_best, cyc_bestR = sw.copy(), R_of(sw)
        if time.process_time() < deadline - 4.0:
            gm = gauss_round(best, deadline - 3.0, sigma=1.5)
            offer(gm, 'cycle%d-gauss' % cycle)

    # ---- Final polish ----
    ht = _peak_ladder(best, deadline - 1.0, pads=(0.10, 0.06, 0.04), iters=400)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _asym_lift(c, seed):
    rng = np.random.RandomState(seed)
    w = np.exp(0.5 * rng.randn(2))
    w = w * (2.0 / w.sum())
    N = c.size
    h = np.empty(2 * N)
    h[0::2] = c * w[0]
    h[1::2] = c * w[1]
    return _rescale(np.clip(h, 0.0, None))


def _upsample(h, factor):
    """Linearly interpolate h onto a grid factor times finer."""
    N = h.size
    newN = N * factor
    x_old = np.arange(N, dtype=float)
    x_new = np.arange(newN, dtype=float) / factor
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    start_best = None
    start_bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase A: direct peak-ladder polish of the FULL-resolution start ----
    # This is the key new idea: refine the full-resolution array directly with
    # the smooth-max objective, focusing on the peak region.
    if time.process_time() < deadline - 15.0:
        slice_dl = min(time.process_time() + budget_seconds * 0.30, deadline - 12.0)
        ht = best.copy()
        ht = _peak_ladder(ht, slice_dl, pads=(0.20, 0.12, 0.08, 0.05), iters=500)
        ht = _polish_ladder(ht, slice_dl, betas=(1e6, 1e7, 0.0), iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'peakladder'
            print("phase A NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase B: upsample best to a finer grid, then polish ----
    if time.process_time() < deadline - 8.0 and best.size <= 500000:
        factor = 2
        if best.size * factor <= 1000000:
            hu = _upsample(best, factor)
            hu = _rescale(hu)
            slice_dl = min(time.process_time() + budget_seconds * 0.25, deadline - 6.0)
            hu = _peak_ladder(hu, slice_dl, pads=(0.12, 0.08, 0.05), iters=400)
            hu = _polish_ladder(hu, slice_dl, betas=(1e6, 1e7, 0.0), iters=250)
            r = R_of(hu)
            if r > bestR + 1e-14:
                best, bestR, origin = hu.copy(), r, 'upsample'
                print("phase B NEW BEST R=%.9f (N=%d)" % (bestR, best.size))
            elif r > alt_bestR:
                alt_best, alt_bestR = hu.copy(), r

    # ---- Phase C: asymmetric-lift rounds on the half-resolution ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 6.0:
        c = best[0::2].copy()
        cR = R_of(c)
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        seed = 1
        while time.process_time() < deadline - 5.0:
            now = time.process_time()
            slice_dl = min(now + 5.0, deadline - 5.0)
            if slice_dl <= now + 1.0:
                break
            h_lift = _asym_lift(best_c, seed)
            hp = h_lift
            if time.process_time() < slice_dl - 0.6:
                hp = _lbfgs_all_pos(hp, 200, slice_dl - 0.3, beta=1e6)
            if time.process_time() < slice_dl - 0.6:
                hp = _lbfgs_all_pos(hp, 200, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.6:
                win = _peak_window(hp, pad_frac=0.08, extra=256)
                hp = _lbfgs_block(hp, win, 300, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.6:
                hp = _lbfgs_all_pos(hp, 150, slice_dl - 0.3, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp.copy(), rp
                origin = 'asym%d' % seed
            elif rp > alt_bestR:
                alt_best, alt_bestR = hp.copy(), rp
            print("asym %d R(c)=%.9f polR=%.9f best=%.9f" % (seed, best_cR, rp, bestR))
            seed += 1

    # ---- Final polish ----
    if time.process_time() < deadline - 1.0:
        ht = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04, 0.03), iters=400)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+finpk'
            print("final peak NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

