        hcp = hc.copy()
        nb = int(rng.integers(4, 10))
        cuts = np.sort(rng.choice(np.arange(1, Nc), size=min(nb - 1, Nc - 1),
                                  replace=False))
        edges = np.concatenate(([0], cuts, [Nc]))
        for b in range(len(edges) - 1):
            a = edges[b]; c = edges[b + 1]
            if c > a:
                hcp[a:c] *= np.exp(rng.normal(0.0, 0.20))
