                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase B: high-beta sharpening ladder (kept from base) ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Phase C: NEW — toe windows (ends) free-optimise-prune + extension ----
    def _prune_window(h, lo, hi, thresh_frac=1e-4):
        out = h.copy()
        seg = out[lo:hi + 1]
        active = out[out > 0]
        if active.size == 0:
            return _rescale(out)
        thr = thresh_frac * active.mean()
        seg[seg < thr] = 0.0
        out[lo:hi + 1] = seg
        return _rescale(out)

    def _toe_round(h, side, dl):
        n = h.size
        if side == 'L':
            lo, hi = 0, min(n - 1, 299)
        else:
            lo, hi = max(0, n - 300), n - 1
        win = np.arange(lo, hi + 1)
        cur = h
        curR = R_of(cur)
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() > dl - 1.0:
                break
            ht = _lbfgs_block(cur, win, 400, dl - 0.5, beta=beta)
            if R_of(ht) > curR + 1e-14:
                cur, curR = ht, R_of(ht)
            ht = _polish_ladder(cur, dl - 0.3, betas=(1e7, 0.0), iters=200)
            if R_of(ht) > curR + 1e-14:
                cur, curR = ht, R_of(ht)
        ht = _prune_window(cur, lo, hi)
        ht = _polish_ladder(ht, dl - 0.3, betas=(1e7, 0.0), iters=200)
        if R_of(ht) > curR + 1e-14:
            cur, curR = ht, R_of(ht)
        return cur, curR

    toe_deadline = deadline - 6.0
    zf0 = _zero_frac(best)
    am0 = _argmax_frac(best)
    nm0 = _nearmax_frac(best)
    print("pre-toe zero_frac=%.4f argmax_frac=%.4f nearmax5=%.4f"
          % (zf0, am0, nm0))

    for rnd in range(6):
        if time.process_time() > toe_deadline - 1.0:
            break
        side = 'L' if (rnd % 2 == 0) else 'R'
        cand, candR = _toe_round(best, side, toe_deadline)
        if candR > bestR + 1e-14:
            offer(cand, 'toe%s%d' % (side, rnd))
            print("toe %s rnd=%d R=%.9f N=%d nearmax5=%.4f"
                  % (side, rnd, candR, cand.size, _nearmax_frac(cand)))
        else:
            print("toe %s rnd=%d no gain (R=%.9f)" % (side, rnd, candR))

        if rnd == 2 and time.process_time() < toe_deadline - 2.0:
            # support extension by 64 cells each side
            nz = np.flatnonzero(best > 0)
            if nz.size > 0:
                first = best[nz[0]]
                last = best[nz[-1]]
                left = _edge_geom(64, 0.7 * first)
                right = _edge_geom(64, 0.7 * last)
                h_ext = np.concatenate([left, best, right])
                h_ext = _rescale(h_ext)
                h_ext = _polish_ladder(h_ext, toe_deadline - 0.5,
                                       betas=(1e6, 1e7, 1e8, 0.0), iters=300)
                h_ext = _peak_ladder(h_ext, toe_deadline - 0.3,
                                     pads=(0.10, 0.06), iters=200)
                r_ext = R_of(h_ext)
                if r_ext > bestR + 1e-14:
                    offer(h_ext, 'ext64')
                    print("ext64 ACCEPTED R=%.9f N=%d nearmax5=%.4f"
                          % (r_ext, h_ext.size, _nearmax_frac(h_ext)))
                else:
                    print("ext64 rejected R=%.9f (best %.9f)" % (r_ext, bestR))

    # ---- Phase D: final polish ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 0.0), iters=250)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.06, 0.04), iters=300)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _nearmax_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Lean beta-smoothed exact-gradient ladder + tightening peak sweep ----
    cycle = 0
    betas = (1e4, 1e5, 1e6, 1e7)
    pads = (0.10, 0.07, 0.05, 0.04, 0.03)

    while time.process_time() < deadline - 2.0:
        cycle += 1
        cyc_start_R = bestR

        # (a) beta ladder, full-array
        for b in betas:
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_all_pos(best, 500, deadline - 1.0, beta=b)
            offer(ht, 'beta%.0e' % b)

        # (b) tightening peak-window sweep
        for pad in pads:
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=96)
            ht = _lbfgs_block(best, win, 500, deadline - 0.5, beta=1e7)
            if offer(ht, 'pk%.2f_b7' % pad):
                ht2 = _lbfgs_block(best, win, 500, deadline - 0.5, beta=0.0)
                offer(ht2, 'pk%.2f_b0' % pad)
            else:
                ht2 = _lbfgs_block(ht, win, 500, deadline - 0.5, beta=0.0)
                offer(ht2, 'pk%.2f_b0' % pad)

        # (c) exact beta=0 full-array polish
        if time.process_time() < deadline - 0.8:
            ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
            offer(ht, 'b0full')

        s01, s1, s5 = _nearmax_shares(best)
        print("cycle %d R=%.9f (d=%.2e) near0.1%%=%.4f near1%%=%.4f near5%%=%.4f"
              % (cycle, bestR, bestR - cyc_start_R, s01, s1, s5))

        if cycle >= 2 and abs(bestR - cyc_start_R) < 1e-12:
            print("flat after %d cycles, stopping" % cycle)
            break

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f, cycles=%d)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best), cycle))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- NEW: multi-resolution moves ----

def _resample(h, newN):
    """Resample a step function h to newN equal steps preserving mass."""
    n = h.size
    if n == newN:
        return h.copy()
    # cumulative mass at original knot boundaries (in original units)
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(newN)
    # target boundaries in original index units
    tgt = np.linspace(0.0, float(n), newN + 1)
    vals = np.interp(tgt, np.arange(n + 1, dtype=float), c)
    out = np.diff(vals)
    # scale so mass preserved in new units (mass here is sum; scale-invariant)
    s = out.sum()
    if s > 0 and total > 0:
        out = out * (total / s)
    return np.clip(out, 0.0, None)


def _move_resample(best, rng, factor):
    n = best.size
    newN = int(round(n * factor))
    newN = max(64, min(newN, 1000000))
    return _resample(best, newN)


def _move_peak_perturb(best, rng):
    """Add a structured bump inside the peak band."""
    n = best.size
    Lf = _knots(best)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= 0.7 * mx)
    if idx.size == 0:
        return best.copy()
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    w = hi - lo + 1
    h = best.copy()
    amp = rng.uniform(0.05, 0.3) * best.mean()
    t = np.linspace(0, np.pi, w)
    shape = rng.choice([np.sin(t), np.cos(2 * t), np.sin(2 * t)])
    h[lo:hi + 1] = np.clip(h[lo:hi + 1] + amp * shape, 0, None)
    return h


def _move_global_reshape(best, rng):
    """Broad multiplicative reshape over the whole support."""
    n = best.size
    h = best.copy()
    # smooth low-frequency multiplicative field
    k = int(rng.choice([4, 8, 16, 32]))
    x = np.linspace(0, 1, n)
    field = np.ones(n)
    for j in range(1, k + 1):
        a = rng.uniform(-0.15, 0.15) / j
        ph = rng.uniform(0, 2 * np.pi)
        field += a * np.cos(2 * np.pi * j * x + ph)
    h = h * np.clip(field, 0.1, 3.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: quick cycle to confirm plateau.
    if time.process_time() < deadline - 2.0:
        best, bestR = run_cycle(best, bestR, deadline - 2.0)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2: multi-resolution resampling search.
    # Try factors around 1 that change the grid; each rescale creates a
    # genuinely different parametrization whose local optimum may be higher.
    factors = [1.25, 0.8, 1.5, 0.667, 2.0, 0.5, 1.1, 0.909,
               1.333, 0.75, 1.75, 0.571, 2.5, 0.4, 3.0, 0.333]
    fi = 0
    acc = 0
    while time.process_time() < deadline - 1.5:
        fac = factors[fi % len(factors)]
        fi += 1
        h_try = _move_resample(best, rng, fac)
        # coarser grids: allow full optimization; finer: block polish near peak
        if h_try.size <= best.size:
            ht = _lbfgs_all_pos(h_try, 400, deadline - 1.0, beta=1e7)
            if time.process_time() < deadline - 1.0:
                ht = _lbfgs_all_pos(ht, 300, deadline - 1.0, beta=0.0)
        else:
            win = _peak_window(h_try, pad_frac=0.3, extra=256)
            ht = _lbfgs_block(h_try, win, 300, deadline - 1.0, beta=1e7)
            if time.process_time() < deadline - 1.0:
                ht = _lbfgs_block(ht, win, 200, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            acc += 1
            print("resample fac=%.3f N=%d R=%.7f acc=%d" % (fac, ht.size, bestR, acc))
        if fi % 4 == 0:
            print("resample %d acc %d bestR=%.7f" % (fi, acc, bestR))
            # periodic full cycle at current resolution
            if time.process_time() < deadline - 1.5:
                best, bestR = run_cycle(best, bestR, deadline - 1.5)

    # Phase 3: structural perturbation hops at the best resolution.
    hop = 0
    while time.process_time() < deadline - 1.0:
        hop += 1
        which = int(rng.integers(0, 3))
        if which == 0:
            h_try = _move_peak_perturb(best, rng)
        elif which == 1:
            h_try = _move_global_reshape(best, rng)
        else:
            h_try = _move_resample(best, rng, rng.uniform(0.7, 1.4))
        h_try = np.clip(h_try, 0, None)
        if h_try.sum() <= 0:
            continue
        if h_try.size == best.size:
            win = _peak_window(h_try, pad_frac=0.2, extra=192)
            ht = _lbfgs_block(h_try, win, 200, deadline - 1.0, beta=1e7)
        else:
            ht = _lbfgs_all_pos(h_try, 300, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            print("hop %d R=%.7f" % (hop, bestR))

    # Phase 4: final polish.
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-5:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _refine_at_N(cur, curR, deadline, betas, tag=""):
    gained = False
    while time.process_time() < deadline - 3.0:
        hb = _lbfgs_log(cur, 250, deadline)
        rb = R_of(hb)
        if rb > curR + 1e-13:
            cur, curR = hb, rb
            gained = True
            print("    %slbfgs R=%.7f (N=%d)" % (tag, curR, cur.size))
        for beta in betas:
            if time.process_time() >= deadline - 4.0:
                break
            hb = _lbfgs_log(cur, 120, deadline, beta=beta)
            hs = _lbfgs_log(hb, 5, deadline)
            rs = R_of(hs)
            hp = _peak_ladder(hs, min(deadline, time.process_time() + 6.0))
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 1e-13:
                cur, curR = cand, rc
                gained = True
                print("    %sbeta=%.0e R=%.7f (N=%d)" % (tag, beta, curR, cur.size))
        if time.process_time() < deadline - 3.0:
            hp = _peak_ladder(cur, min(deadline, time.process_time() + 5.0),
                              pads=(0.03, 0.02))
            rp = R_of(hp)
            if rp > curR + 1e-13:
                cur, curR = hp, rp
                gained = True
                print("    %speak R=%.7f (N=%d)" % (tag, curR, cur.size))
    return cur, curR, gained


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    betas = (1e4, 1e5, 1e6, 1e7, 1e8)

    cur, curR = best.copy(), bestR
    cur, curR, _ = _refine_at_N(cur, curR, t0 + budget_seconds * 0.55, betas, tag="N0 ")
    if curR > bestR + 1e-13:
        best, bestR = cur.copy(), curR

    if time.process_time() < deadline - 8.0:
        h2 = np.repeat(best, 2)
        h2 = _rescale(h2 * rng.lognormal(0.0, 1e-5, size=h2.size))
        r2 = R_of(h2)
        cur2, cur2R = h2, r2
        cur2, cur2R, _ = _refine_at_N(cur2, cur2R, deadline, betas, tag="N2 ")
        if cur2R > bestR + 1e-12:
            best, bestR = cur2.copy(), cur2R

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

