def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _nearmax_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _upsample(h, factor):
    """Insert factor-1 new steps between each pair of original steps."""
    if factor <= 1:
        return h.copy()
    n = h.size
    m = (n - 1) * factor + 1
    out = np.zeros(m, dtype=float)
    idx = np.arange(n) * factor
    out[idx] = h
    # linearly interpolate the inserted points
    for k in range(1, factor):
        out[idx[:-1] + k] = ((factor - k) * h[:-1] + k * h[1:]) / factor
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Refinement ladder on the current best ----
    def refine(h, deadline, tag, pads=(0.10, 0.06, 0.04, 0.03), iters=400):
        for b in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 0.5:
                return h
            ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=b)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
                offer(h, tag + '_b%.0e' % b)
        for pad in pads:
            if time.process_time() >= deadline - 0.5:
                return h
            win = _peak_window(h, pad_frac=pad, extra=128)
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
                offer(h, tag + '_pk%.2f' % pad)
            ht2 = _lbfgs_block(ht, win, iters, deadline - 0.3, beta=0.0)
            if R_of(ht2) > R_of(h) + 1e-14:
                h = ht2
                offer(h, tag + '_pk%.2f_b0' % pad)
        return h

    # ---- Main improvement: try upsampling to escape local optima ----
    cycle = 0
    factors = (2, 2, 2)  # successive doublings
    cur = best.copy()
    curR = bestR

    while time.process_time() < deadline - 2.0:
        cycle += 1
        cyc_start = curR

        # (a) refine current at current resolution
        cur = refine(cur, deadline - 1.0, 'c%d' % cycle)
        curR = R_of(cur)
        offer(cur, 'refine_c%d' % cycle)

        if time.process_time() >= deadline - 2.0:
            break

        # (b) upsample: more degrees of freedom can escape the local optimum
        if cur.size < 900000:
            factor = 2
            newN = (cur.size - 1) * factor + 1
            if newN <= 950000:
                up = _upsample(cur, factor)
                up = _rescale(up)
                upR0 = R_of(up)
                # refine the upsampled version
                up = refine(up, deadline - 1.0, 'up%d' % up.size)
                upR = R_of(up)
                print("upsample N=%d->%d  R %.9f -> %.9f" %
                      (cur.size, up.size, upR0, upR))
                offer(up, 'upsample')
                # if the upsample helps, adopt it; else keep the smaller one
                if upR > curR + 1e-12:
                    cur = up
                    curR = upR
                else:
                    # try refining original once more at current res
                    pass

        s01, s1, s5 = _nearmax_shares(cur)
        print("cycle %d R=%.9f (d=%.2e) N=%d near0.1%%=%.4f near1%%=%.4f near5%%=%.4f"
              % (cycle, curR, curR - cyc_start, cur.size, s01, s1, s5))

        if cycle >= 3 and abs(curR - cyc_start) < 1e-13 and cur.size >= best.size:
            print("flat, stopping")
            break

    # final polish of best
    if time.process_time() < deadline - 1.0:
        polished = refine(best, deadline - 0.5, 'final', pads=(0.03, 0.02), iters=300)
        offer(polished, 'final')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _interlace(best, t):
    n = best.size
    h2 = np.zeros(2 * n)
    h2[0::2] = best
    right = np.append(best[1:], best[-1])
    fill = 0.5 * (right + best)
    h2[1::2] = t * fill
    return _rescale(h2)


def _polish(h2, slice_dl, pads=(0.20, 0.12, 0.08)):
    h = h2
    if time.process_time() < slice_dl - 1.0:
        h = _lbfgs_all_pos(h, 150, slice_dl, beta=1e6)
    if time.process_time() < slice_dl - 1.0:
        h = _lbfgs_all_pos(h, 150, slice_dl, beta=1e7)
    for pad in pads:
        if time.process_time() >= slice_dl - 1.0:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        h = _lbfgs_block(h, win, 400, slice_dl, beta=1e7)
    if time.process_time() < slice_dl - 1.0:
        h = _lbfgs_all_pos(h, 200, slice_dl, beta=0.0)
    return h


def _perturb_multiscale(h, rng, scale_frac, amp):
    """Add smooth random perturbation at a spatial scale, multiplicative."""
    n = h.size
    k = max(2, int(n * scale_frac))
    # smooth random field by convolving random noise with a box
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    sm = np.convolve(noise, kern, mode='same')
    sm = sm / (np.std(sm) + 1e-12)
    factor = np.exp(amp * sm)
    return _rescale(h * factor)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0
    rng = np.random.default_rng(12345)

    # ---- Interlace portfolio over fill factors ----
    fills = [0.5, 1.0, 1.5]
    cand_best = None
    cand_bestR = -1.0
    cand_t = None
    for t in fills:
        now = time.process_time()
        if now > deadline - 12.0:
            break
        slice_dl = min(now + 12.0, deadline - 6.0)
        if slice_dl <= now + 1.0:
            break
        h2 = _interlace(best, t)
        r0 = R_of(h2)
        print("interlace t=%.2f raw R=%.9f (d=%.2e)" % (t, r0, r0 - bestR))
        h = _polish(h2, slice_dl)
        r = R_of(h)
        print("interlace t=%.2f polished R=%.9f" % (t, r))
        if r > cand_bestR:
            cand_best, cand_bestR, cand_t = h, r, t
        if r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r

    if cand_best is not None and cand_bestR > bestR + 1e-12:
        best, bestR, origin = cand_best.copy(), cand_bestR, 'interlace_t%.2f' % cand_t
        print("interlace ACCEPT t=%.2f R=%.9f" % (cand_t, bestR))

    # ---- Extra interlace round with winning t +- 0.25 ----
    if cand_t is not None:
        for dt in [0.25, -0.25]:
            now = time.process_time()
            if now > deadline - 8.0:
                break
            t2 = cand_t + dt
            if t2 <= 0:
                continue
            slice_dl = min(now + 10.0, deadline - 5.0)
            if slice_dl <= now + 1.0:
                break
            h2 = _interlace(best, t2)
            r0 = R_of(h2)
            print("interlace2 t=%.2f raw R=%.9f" % (t2, r0))
            h = _polish(h2, slice_dl)
            r = R_of(h)
            print("interlace2 t=%.2f polished R=%.9f" % (t2, r))
            if r > bestR + 1e-12:
                best, bestR, origin = h.copy(), r, 'interlace2_t%.2f' % t2
                print("interlace2 NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = h.copy(), r

    # ---- NEW: multiscale random perturbation search (basin hopping) ----
    # Try perturbing best at several scales and polish; accept improvements.
    scales = [0.30, 0.15, 0.08, 0.04, 0.02, 0.10]
    amps = [0.15, 0.10, 0.08, 0.06, 0.05, 0.12]
    for sc, am in zip(scales, amps):
        now = time.process_time()
        if now > deadline - 8.0:
            break
        slice_dl = min(now + 9.0, deadline - 4.0)
        if slice_dl <= now + 1.0:
            break
        hp = _perturb_multiscale(best, rng, sc, am)
        r0 = R_of(hp)
        h = _polish(hp, slice_dl)
        r = R_of(h)
        print("perturb sc=%.2f raw R=%.9f polished R=%.9f (d=%.2e)" %
              (sc, r0, r, r - bestR))
        if r > bestR + 1e-12:
            best, bestR, origin = h.copy(), r, origin + '+pert%.2f' % sc
            print("perturb NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r

    # ---- Final full polish ----
    if time.process_time() < deadline - 1.0:
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 0.8:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, origin + '+b%g' % beta
                print("final beta%g NEW BEST R=%.9f" % (beta, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
    if time.process_time() < deadline - 1.0:
        for pad in [0.12, 0.08, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.4, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    zf = float(np.mean(best <= 0))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zerofrac=%.3f)" %
          (bestR, origin, start_bestR, best.size, zf))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

