    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best, bestR = None, 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt, altR = None, 0.0

    def consider(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        print("%s R=%.7f" % (tag, r))
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s improved R=%.7f" % (tag, bestR))
        elif alt is None or r > altR:
            alt, altR = h, r

    # Phase 1: smooth-max ramp (beta continuation) to flatten top of f*f
    if time.process_time() < deadline - 4.0:
        h = best.copy()
        for beta in (40.0, 120.0, 350.0, 900.0, 2200.0, 5000.0):
            if time.process_time() >= deadline - 3.0:
                break
            h = _lbfgs_log(h, 400, deadline,
                           fg=(lambda hh, b=beta: _fun_grad_beta(hh, b)))
        h = _lbfgs_log(h, 1200, deadline)
        consider(h, "sm")

