            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _shift_resample(h, delta):
    """Resample step function h at a fractional cell offset delta.

    Treats h as a piecewise-constant density on [0,1] with cell i on
    [i/N, (i+1)/N]. Builds the edge-cumulative mass function and re-integrates
    it over shifted cells [(i+delta)/N, (i+delta+1)/N], dropping mass outside
    [0,1].
    """
    n = h.size
    mass = np.clip(h, 0, None).astype(float)
    tot = mass.sum()
    if tot <= 0:
        return h.copy()
    cum = np.concatenate(([0.0], np.cumsum(mass))) / tot  # length n+1, 0..1
    edges = np.arange(n + 1, dtype=float) / n              # cell boundaries
    # shifted cell boundaries
    xs = (np.arange(n + 1, dtype=float) + delta) / n
    vals = np.interp(xs, edges, cum)
    out = np.diff(vals)
    # drop mass that fell outside [0,1]: cum is clamped by interp at ends
    out = np.clip(out, 0.0, None)
    if out.sum() <= 0:
        return h.copy()
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase A: half-resolution quotient polish (kept from base) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.18
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase B: high-beta sharpening ladder (kept from base) ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Phase C (NEW): lattice-shift resampling rounds ----
    shift_deadline = deadline - 6.0
    deltas = [0.5, 0.5, 0.3333, 0.25, 0.5]
    accepted = 0
    rounds = 0
    for delta in deltas:
        if time.process_time() >= shift_deadline - 1.0:
            break
        rounds += 1
        cand = _shift_resample(best, delta)
        cand = _rescale(cand)
        cand = _polish_ladder(cand, shift_deadline - 0.5,
                              betas=(1e6, 1e7, 0.0), iters=300)
        cand = _peak_ladder(cand, shift_deadline - 0.4,
                            pads=(0.10, 0.06), iters=300)
        r = R_of(cand)
        print("shift rnd=%d delta=%.4f R=%.9f (best %.9f) N=%d"
              % (rounds, delta, r, bestR, cand.size))
        if cand.size == best.size and r > bestR + 1e-14:
            offer(cand, 'shift')
            accepted += 1

    print("shift rounds=%d accepted=%d" % (rounds, accepted))

    # ---- Phase D: final polish ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 0.0), iters=250)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.06, 0.04), iters=300)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _grad_only(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    dnum = _backprop(dq, h)
    dm = np.zeros(h.size)
    k = m - 1
    if 0 <= k < 2 * h.size - 1:
        for j in range(max(0, k - h.size + 1), min(h.size, k + 1)):
            dm[j] = 2.0 * h[k - j]
    ds = np.ones(h.size)
    den = s * s * Lm
    dR = dnum / den - num * (2 * s * Lm * ds + s * s * dm) / (den * den)
    return dR


def _smooth_polish(h, deadline, iters=400):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    R = R_of(h)
    step = 1e-3 * h.max() / (np.abs(_grad_only(h)).max() + 1e-30)
    for it in range(iters):
        if time.process_time() > deadline - 0.3:
            break
        g = _grad_only(h)
        gn = np.max(np.abs(g))
        if gn <= 0:
            break
        step = min(step, 1e-2 * h.max() / gn)
        h2 = np.clip(h + step * g, 0, None)
        R2 = R_of(h2)
        if R2 > R:
            h = h2
            R = R2
            step *= 1.5
        else:
            step *= 0.5
            if step * gn < 1e-12 * h.max():
                break
    return _rescale(h)


def _peak_window_polish(h, deadline, pad, iters=250):
    """Polish only a window around the peak of f*f, keeping the rest fixed."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    # window in h-index space around the peak knot index m-1
    k = m - 1
    lo = max(0, k - int(pad * n))
    hi = min(n, k + int(pad * n) + 1)
    if hi - lo < 8:
        return h
    sub = h[lo:hi].copy()
    # We polish the sub-array but must account for the fixed surroundings via
    # full-array evaluation. Use a wrapper that rebuilds full h and returns R.
    base = h.copy()

    def f(x):
        hh = base.copy()
        hh[lo:hi] = np.clip(x, 0.0, None)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros_like(x)
        num, dq, Lf2 = _num_and_dq(hh)
        mm = int(np.argmax(Lf2))
        Lm = Lf2[mm]
        gLf = -dq / num
        gLf[mm] += 1.0 / Lm
        grad_full = _backprop(gLf, hh) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad_full[lo:hi]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, sub, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * sub.size,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    out = base.copy()
    out[lo:hi] = np.clip(res.x, 0.0, None)
    return _rescale(out)


def _stats(h):
    h = np.clip(np.asarray(h, float), 0, None)
    n = h.size
    zf = float(np.mean(h <= 1e-12))
    mx = h.max()
    mean = h.mean()
    ratio = mx / mean if mean > 0 else 0.0
    Lf = _knots(h)
    Lm = Lf.max()
    nearmax5 = float(np.mean(Lf >= 0.95 * Lm)) if Lm > 0 else 0.0
    return zf, ratio, nearmax5


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_h = None
    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            start_h = s.copy()
            start_R = R_of(s)

    if start_h is None:
        N = 512
        x = (np.arange(N) + 0.5) / N
        seed = np.exp(-((x - 0.5) ** 2) / (2 * 0.15 ** 2))
        h = _rescale(seed)
        for N2 in [1024, 2048, 4096, 8192, 16384, 32768]:
            idx = (np.arange(N2) * N // N2).astype(int)
            h = h[idx]
            N = N2
            if time.process_time() > deadline - 1.0:
                break
            h = _smooth_polish(h, deadline, 200)
        best = h
        bestR = R_of(h)
        zf, ratio, nm5 = _stats(best)
        print("R=%.6f N=%d zf=%.3f mx/mn=%.2f nm5=%.3f" % (bestR, len(best), zf, ratio, nm5))
        return best

    cur = start_h.copy()
    curR = start_R
    bestR = start_R
    best_h = start_h.copy()

    rng = np.random.RandomState(12345)

    round_idx = 0
    while time.process_time() < deadline - 5.0:
        round_idx += 1
        improved = False

        # (a) full-array beta ladder
        h = cur.copy()
        for beta in [1e6, 1e7, 1e8, 0.0]:
            if time.process_time() > deadline - 4.0:
                break
            h2 = _lbfgs(h, 250, deadline, beta=beta)
            if R_of(h2) >= R_of(h) - 1e-12:
                h = h2
        R_h = R_of(h)
        if R_h > curR + 1e-12:
            cur = h
            curR = R_h
            improved = True

        # (b) prune + re-polish at same N
        if time.process_time() < deadline - 4.0:
            h = cur.copy()
            active = h[h > 1e-12]
            if active.size > 0:
                thr = 1e-3 * active.mean()
                h[h < thr] = 0.0
            for beta in [1e7, 0.0]:
                if time.process_time() > deadline - 4.0:
                    break
                h2 = _lbfgs(h, 200, deadline, beta=beta)
                if R_of(h2) >= R_of(h) - 1e-12:
                    h = h2
            R_h = R_of(h)
            if R_h > curR + 1e-12:
                cur = h
                curR = R_h
                improved = True

        # (c) interlace-upsample x2 + peak-window polish
        if time.process_time() < deadline - 4.0 and 2 * cur.size <= 1_000_000:
            n0 = cur.size
            h = np.zeros(2 * n0)
            h[0::2] = cur
            noise = np.exp(rng.randn(n0) * 0.3)
            h[1::2] = cur * noise
            h = np.clip(h, 0.2 * cur.min() if cur.min() > 0 else 0.0, 5.0 * cur.max())
            for pad in [0.15, 0.10, 0.06]:
                if time.process_time() > deadline - 4.0:
                    break
                h2 = _peak_window_polish(h, deadline, pad, iters=250)
                if R_of(h2) >= R_of(h) - 1e-12:
                    h = h2
            R_h = R_of(h)
            if R_h > curR + 1e-12:
                cur = h
                curR = R_h
                improved = True

        if curR > bestR:
            bestR = curR
            best_h = cur.copy()

        zf, ratio, nm5 = _stats(cur)
        print("round %d R=%.6f N=%d zf=%.3f mx/mn=%.2f nm5=%.3f imp=%d"
              % (round_idx, curR, cur.size, zf, ratio, nm5, int(improved)))

        if not improved and round_idx > 1:
            # try a fresh beta ladder from best to escape
            if time.process_time() < deadline - 4.0:
                h = best_h.copy()
                for beta in [1e8, 1e7, 0.0]:
                    if time.process_time() > deadline - 4.0:
                        break
                    h2 = _lbfgs(h, 250, deadline, beta=beta)
                    if R_of(h2) >= R_of(h) - 1e-12:
                        h = h2
                R_h = R_of(h)
                if R_h > curR + 1e-12:
                    cur = h
                    curR = R_h
                    if curR > bestR:
                        bestR = curR
                        best_h = cur.copy()

    # final full polish on best
    if time.process_time() < deadline - 1.0:
        h = best_h.copy()
        for beta in [1e8, 0.0]:
            if time.process_time() > deadline - 1.0:
                break
            h2 = _lbfgs(h, 250, deadline, beta=beta)
            if R_of(h2) >= R_of(h) - 1e-12:
                h = h2
        R_h = R_of(h)
        if R_h > bestR:
            bestR = R_h
            best_h = h

    zf, ratio, nm5 = _stats(best_h)
    print("FINAL R=%.6f N=%d zf=%.3f mx/mn=%.2f nm5=%.3f"
          % (bestR, len(best_h), zf, ratio, nm5))

    if bestR > start_R:
        return {"best": best_h, "alternative": start_h}
    else:
        return {"best": start_h, "alternative": best_h}

