    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04, 0.025), iters=400):
    cur_r = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > cur_r + 1e-14:
            h, cur_r = ht, r
    return h, cur_r


def _refine_at_res(h, deadline, rcur, rounds=3):
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        n = h.size
        if n >= 1_000_000:
            break
        m = min(1_000_000, n * 2)
        h2 = _rescale(_prolong(h, m))
        cand = _lbfgs_log(h2, maxiter=300, deadline=deadline)
        r = R_of(cand)
        if r > rcur + 1e-14:
            h, rcur = cand, r
        else:
            cand2 = _lbfgs_all_pos(h2, 300, deadline)
            r2 = R_of(cand2)
            if r2 > rcur + 1e-14:
                h, rcur = cand2, r2
            else:
                break
    return h, rcur


def _smooth_dilate(h, k):
    if k <= 1:
        return h.copy()
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(h)
        best_r = R_of(best)
        start_r = best_r

    if best.size < 65536:
        best = _rescale(_prolong(best, 65536))
        best_r = R_of(best)

    # Ladder of beta-smoothed optimisations over all positive entries.
    for beta in (1e6, 1e7, 1e8):
        if time.process_time() >= deadline - 1.5:
            break
        cand = _lbfgs_all_pos(best, 400, deadline, beta=beta)
        r = R_of(cand)
        if r > best_r + 1e-14:
            best, best_r = cand, r
    cand = _lbfgs_all_pos(best, 500, deadline)
    r = R_of(cand)
    if r > best_r + 1e-14:
        best, best_r = cand, r
    print("after all-pos R=%.6f" % best_r)

    # Peak-window polish.
    best, best_r = _peak_ladder(best, deadline)
    print("after peak-ladder R=%.6f" % best_r)

    # Resolution refinement.
    best, best_r = _refine_at_res(best, deadline, best_r, rounds=2)
    print("after refine R=%.6f N=%d" % (best_r, best.size))

    alt = None
    alt_r = -1.0
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        # Smooth-dilate restart at current resolution.
        for k in (3, 7, 15, 31):
            if time.process_time() >= deadline - 1.5:
                break
            seed = _rescale(_smooth_dilate(best, k))
            cand = _lbfgs_all_pos(seed, 300, deadline, beta=1e7)
            r = R_of(cand)
            if r > best_r + 1e-14:
                best, best_r = cand, r
            elif alt is None or r > alt_r:
                alt, alt_r = cand, r

        best, best_r = _peak_ladder(best, deadline)
        cand = _lbfgs_all_pos(best, 300, deadline)
        r = R_of(cand)
        if r > best_r + 1e-14:
            best, best_r = cand, r

        if it % 2 == 0:
            best, best_r = _refine_at_res(best, deadline, best_r, rounds=1)
        print("  it#%d R=%.6f N=%d" % (it, best_r, best.size))

    best = _rescale(best)
    print("best R=%.6f (start %.6f) N=%d" % (best_r, start_r, best.size))

    if start_arr is not None and start_r >= best_r:
        if alt is not None and alt_r > start_r:
            return {"best": start_arr, "alternative": alt}
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        if alt is not None and alt_r > 0 and R_of(alt) < best_r:
            return {"best": best, "alternative": alt}
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.08, 0.04, 0.02), iters=400):
    best = h
    bestR = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=64)
        ht = _lbfgs_block(best, win, iters, deadline - 0.3)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    return best, bestR


def _block_multistart(best, bestR, deadline, rng):
    n = best.size
    Lf = _knots(best)
    mx = Lf.max()
    peak_idx = np.flatnonzero(Lf >= 0.97 * mx) if mx > 0 else np.array([0])
    pos_idx = np.flatnonzero(best > 0)
    if pos_idx.size == 0:
        return best, bestR
    windows_tried = 0
    accepted = 0
    while time.process_time() < deadline - 1.0:
        windows_tried += 1
        w = int(rng.choice([64, 128, 256]))
        if rng.random() < 0.5:
            c = int(rng.choice(pos_idx))
        else:
            j = int(rng.choice(peak_idx))
            c = j // 2
        lo = max(0, c - w // 2)
        hi = min(n - 1, lo + w - 1)
        lo = max(0, hi - w + 1)
        free = np.arange(lo, hi + 1)
        ww = free.size
        block_best = None
        block_bestR = bestR
        for k in range(6):
            if time.process_time() >= deadline - 1.0:
                break
            h2 = best.copy()
            noise = np.exp(np.clip(rng.normal(0.0, 0.6, ww), -3.0, 3.0))
            h2[free] = h2[free] * noise
            if rng.random() < 0.3:
                posf = free[h2[free] > 0]
                if posf.size > 0:
                    nz = max(1, int(0.2 * posf.size))
                    kill = rng.choice(posf, size=nz, replace=False)
                    h2[kill] = 0.0
            h2 = np.clip(h2, 0.0, None)
            if h2.sum() <= 0:
                continue
            h2 = _lbfgs_block(h2, free, 25, deadline)
            r2 = R_of(h2)
            if r2 > block_bestR + 1e-13:
                block_best = h2
                block_bestR = r2
        if block_best is not None and block_bestR > bestR + 1e-12:
            best, bestR = block_best, block_bestR
            accepted += 1
        if windows_tried % 40 == 0 and time.process_time() < deadline - 2.0:
            st, r = _peak_ladder(best, deadline - 1.0)
            if r > bestR + 1e-13:
                best, bestR = st, r
    print("block-ms: windows=%d accepted=%d R=%.7f" %
          (windows_tried, accepted, bestR))
    return best, bestR


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = np.clip(h, 0, None)
    if hs.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * hs.mean())
    out = hs.copy()
    out[out <= 0] = eps
    return _lbfgs_all_pos(out, maxiter, deadline)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(20240811)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Half the budget on block multistart exploration
    ms_deadline = t0 + 0.5 * budget_seconds
    if time.process_time() < ms_deadline - 1.0:
        best, bestR = _block_multistart(best, bestR, ms_deadline, rng)
        print("block multistart R=%.7f" % bestR)

    # Peak-window ladder
    if time.process_time() < deadline - 2.0:
        best, bestR = _peak_ladder(best, deadline - 1.0)
        print("peak ladder R=%.7f" % bestR)

    # Refine with all-positive
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("run cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

