    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _report(tag, h, R):
    print("%s R=%.7f N=%d" % (tag, R, h.size))


def _hop(h, bestR, deadline, rng):
    n = h.size
    if n < 8:
        return h, bestR
    wlen = int(rng.integers(max(8, n // 20), max(16, n // 4)))
    wlen = min(wlen, n)
    lo = int(rng.integers(0, n - wlen + 1))
    hi = lo + wlen
    hp = h.copy()
    amp = rng.uniform(0.02, 0.15)
    noise = 1.0 + amp * rng.standard_normal(wlen)
    hp[lo:hi] = np.clip(hp[lo:hi] * noise, 0.0, None)
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 64
    free = np.arange(max(0, lo - halo), min(n, hi + halo))
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 200, deadline - 0.5, beta=1e7)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def _mutate(h, bestR, deadline, rng):
    n = h.size
    hp = h.copy()
    blen = int(rng.integers(max(8, n // 40), max(16, n // 8)))
    blen = min(blen, n)
    lo = int(rng.integers(0, n - blen + 1))
    hi = lo + blen
    hp[lo:hi] = 0.0
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 128
    free = np.arange(max(0, lo - halo), min(n, hi + halo))
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 300, deadline - 0.5, beta=0.0)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def _refine_local(h, bestR, deadline, rng, n_iter):
    for _ in range(n_iter):
        if time.process_time() >= deadline - 0.6:
            break
        pos = np.flatnonzero(h > 1e-9)
        if pos.size == 0:
            break
        lo = max(0, pos.min() - 8)
        hi = min(h.size, pos.max() + 8)
        free = np.arange(lo, hi)
        if free.size > 60000:
            step = 40000
            improved = False
            for st in range(lo, hi, step):
                if time.process_time() >= deadline - 0.6:
                    break
                en = min(hi, st + step + 200)
                sub = np.arange(st, en)
                ht = _lbfgs_block(h, sub, 150, deadline - 0.6, beta=1e8)
                rt = R_of(ht)
                if rt > bestR + 1e-14:
                    h, bestR = ht, rt
                    improved = True
            if not improved:
                break
        else:
            ht = _lbfgs_block(h, free, 200, deadline - 0.6, beta=1e8)
            rt = R_of(ht)
            if rt > bestR + 1e-14:
                h, bestR = ht, rt
            else:
                ht = _lbfgs_block(h, free, 200, deadline - 0.6, beta=0.0)
                rt = R_of(ht)
                if rt > bestR + 1e-14:
                    h, bestR = ht, rt
                else:
                    break
    return h, bestR


def _peak_sharpen(h, bestR, deadline, rng, n_rounds=8):
    """Targeted attack on the ||f*f||_inf plateau: repeatedly re-weight the
    peak knots via beta-smoothing with decreasing beta, applied only to a
    tight window around the maximum, then a global cleanup."""
    for round_i in range(n_rounds):
        if time.process_time() >= deadline - 0.6:
            break
        Lf = _knots(h)
        mx = Lf.max()
        # tight window around maximum of f*f
        idx = np.flatnonzero(Lf >= 0.98 * mx)
        if idx.size == 0:
            break
        c = int(0.5 * (idx.min() + idx.max()))
        half = max(64, int(0.6 * (idx.max() - idx.min()) + 32))
        lo = max(0, c - half)
        hi = min(h.size - 1, c + half)
        win = np.arange(lo, hi + 1)
        beta = 1e8 / (2.0 ** round_i)
        ht = _lbfgs_block(h, win, 200, deadline - 0.6, beta=beta)
        rt = R_of(ht)
        if rt > bestR + 1e-14:
            h, bestR = ht, rt
        else:
            # try a finer beta and accept if improves
            ht = _lbfgs_block(h, win, 200, deadline - 0.6, beta=beta * 10)
            rt = R_of(ht)
            if rt > bestR + 1e-14:
                h, bestR = ht, rt
            else:
                break
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Stage (a): full polish.
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 1.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 1.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(a)", best, bestR)

    # Stage (b): peak-window refinements at multiple scales.
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        if win.size > 40000:
            continue
        ht = _lbfgs_block(best, win, 250, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(b)", best, bestR)

    # Stage (c): support-wide beta-swept local polish.
    rng = np.random.default_rng(987654321)
    best, bestR = _refine_local(best, bestR, deadline, rng, n_iter=6)
    _report("(c)", best, bestR)

    # Stage (c2): NEW — dedicated peak-sharpening attack on the plateau.
    best, bestR = _peak_sharpen(best, bestR, deadline, rng, n_rounds=10)
    _report("(c2)", best, bestR)

    # Stage (d): hop/mutate loop with acceptance.
    n_hops = 0
    n_accept = 0
    while time.process_time() < deadline - 1.2:
        n_hops += 1
        if n_hops % 3 == 0:
            hnew, rnew = _mutate(best, bestR, deadline - 1.2, rng)
        else:
            hnew, rnew = _hop(best, bestR, deadline - 1.2, rng)
        if rnew > bestR + 1e-13:
            best, bestR = hnew, rnew
            n_accept += 1
        if n_hops > 400:
            break
    print("(d) hops=%d accepted=%d" % (n_hops, n_accept))
    _report("(d)", best, bestR)

    # Stage (e): final broad polish + zero seeding.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 500, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        hs = _seed_zeros(best)
        ht = _lbfgs_all_pos(hs, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_soft(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_soft(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    return _lbfgs_all(_seed_zeros(h), maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _tilt(C, delta, rng):
    n = C.size // 2
    e = delta * (2.0 * rng.random(n) - 1.0)
    h2 = C.copy()
    h2[0::2] = C[0::2] * (1.0 + e)
    h2[1::2] = C[1::2] * (1.0 - e)
    return _rescale(np.clip(h2, 0, None))


def _upsample(h, factor):
    """Interpolate h onto a finer grid (piecewise-linear resampling)."""
    n = h.size
    m = n * factor
    x = (np.arange(m) + 0.5) / factor - 0.5
    xi = np.clip(x, 0, n - 1)
    i0 = np.floor(xi).astype(int)
    i1 = np.minimum(i0 + 1, n - 1)
    w = xi - i0
    return (1.0 - w) * h[i0] + w * h[i1]


def _downsample(h, factor):
    n = h.size // factor
    return h[:n * factor].reshape(n, factor).mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Refinement at higher resolution: upsample the start and refine ----
    # This is the key new idea: the previous program only refined at the
    # existing resolution.  By interpolating onto a finer grid (and cleaning
    # up), local optima at higher N can be found, potentially beating the
    # current best.
    if time.process_time() < deadline - 8.0:
        for factor in (2,):
            if time.process_time() >= deadline - 8.0:
                break
            hf = _upsample(best, factor)
            hf = _rescale(_seed_zeros(hf))
            r0 = R_of(hf)
            tdead = min(deadline - 6.0, time.process_time() + (deadline - t0) * 0.25)
            hf = _lbfgs_all(hf, 500, tdead)
            r1 = R_of(hf)
            hf, r2 = run_cycle(hf, r1, tdead)
            print("upsample x%d N=%d R0=%.7f R=%.7f dR=%.2e"
                  % (factor, hf.size, r0, r2, r2 - bestR))
            if r2 > bestR + 1e-13:
                best, bestR = hf.copy(), r2

    # ---- 2x staircase + tilts (as before, but on the possibly-improved best) ----
    if time.process_time() < deadline - 4.0:
        C = _rescale(np.repeat(best, 2))
        C_R = R_of(C)
        print("staircase N=%d R=%.7f" % (C.size, C_R))

        ctl_dead = min(deadline - 4.0, time.process_time() + 5.0)
        hc, rc = run_cycle(C.copy(), C_R, ctl_dead)
        print("control R=%.7f dR=%.2e" % (rc, rc - bestR))
        if rc > bestR + 1e-13:
            best, bestR = hc.copy(), rc

        deltas = [0.005, 0.02, 0.05]
        n_c = len(deltas)
        for ci, delta in enumerate(deltas):
            now = time.process_time()
            if now >= deadline - 3.0:
                break
            per = (deadline - 3.0 - now) / (n_c - ci)
            tdead = min(deadline - 3.0, now + per)
            h2 = _tilt(C, delta, rng)
            r0 = R_of(h2)
            h2 = _lbfgs_all(h2, 400, tdead)
            r1 = R_of(h2)
            h2, r2 = run_cycle(h2, r1, tdead)
            print("tilt d=%.3f R0=%.7f R=%.7f dR=%.2e"
                  % (delta, r0, r2, r2 - bestR))
            if r2 > bestR + 1e-13:
                best, bestR = h2.copy(), r2

    # ---- Final polish ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all(best, 1500, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 1.0:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

