    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size

    # ---- Phase A: coarse-quotient polish, alternating stride 2 / stride 4 ----
    phaseA_deadline = t0 + budget_seconds * 0.55
    c_star = None
    c_starR = -1.0
    c_star_stride = 2
    round_idx = 0
    while time.process_time() < phaseA_deadline - 1.5:
        stride = 2 if (round_idx % 2 == 0) else 4
        if N >= stride and N // stride >= 4:
            c = best[0::stride].copy()
        else:
            c = best[0::2].copy()
            stride = 2
        if c.size < 4:
            break
        c = _rescale(c)
        c = _polish_ladder(c, phaseA_deadline, betas=(1e6, 1e7, 0.0), iters=300)
        c = _peak_ladder(c, phaseA_deadline,
                         pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
        rc = R_of(c)
        if rc > c_starR + 1e-14:
            c_star = c.copy()
            c_starR = rc
            c_star_stride = stride
        round_idx += 1

    if c_star is None:
        c_star = best[0::2].copy() if N >= 4 else best.copy()
        c_star = _rescale(c_star)
        c_starR = R_of(c_star)
        c_star_stride = 2

    print("Phase A: rounds=%d c_starR=%.9f stride=%d len=%d af=%.4f"
          % (round_idx, c_starR, c_star_stride, c_star.size, _argmax_frac(best)))

    # ---- Phase B: 4-candidate weight portfolio lift ----
    phaseB_deadline = deadline - 6.0

    def _lift_with_weights(h_fine_seed):
        h_fine = _rescale(h_fine_seed)
        h_fine = _polish_ladder(h_fine, phaseB_deadline, betas=(1e7, 1e8, 0.0), iters=250)
        h_back = _fold_back(h_fine, N)
        h_back = _rescale(h_back)
        h_back = _polish_ladder(h_back, phaseB_deadline, betas=(1e7, 1e8, 0.0), iters=250)
        h_back = _peak_ladder(h_back, phaseB_deadline, pads=(0.08, 0.05), iters=250)
        return h_back

    n_fine = 3 * c_star.size // 2
    if n_fine < 4:
        n_fine = max(4, 2 * c_star.size)

    candidates = []

    # cand 1: log-normal sigma 0.25
    if time.process_time() < phaseB_deadline - 2.0:
        r1 = np.random.default_rng(101)
        base_fine = _interlace_32(c_star, n_fine, r1)
        w = np.exp(0.25 * r1.standard_normal(n_fine))
        candidates.append(("w0.25", base_fine * w))

    # cand 2: log-normal sigma 0.50
    if time.process_time() < phaseB_deadline - 2.0:
        r2 = np.random.default_rng(202)
        base_fine = _interlace_32(c_star, n_fine, r2)
        w = np.exp(0.50 * r2.standard_normal(n_fine))
        candidates.append(("w0.50", base_fine * w))

    # cand 3: deterministic repeat (no weights)
    if time.process_time() < phaseB_deadline - 2.0:
        r3 = np.random.default_rng(303)
        base_fine = _interlace_32(c_star, n_fine, r3)
        candidates.append(("repeat", base_fine))

    # cand 4: asymmetric ramp [0.6, 1.0, 1.4] cycled
    if time.process_time() < phaseB_deadline - 2.0:
        r4 = np.random.default_rng(404)
        base_fine = _interlace_32(c_star, n_fine, r4)
        ramp = np.array([0.6, 1.0, 1.4])
        w = ramp[np.arange(n_fine) % 3]
        candidates.append(("ramp", base_fine * w))

    for tag, seed in candidates:
        if time.process_time() >= phaseB_deadline - 1.0:
            break
        cand = _lift_with_weights(seed)
        rc = R_of(cand)
        if rc > bestR + 1e-14:
            best, bestR = cand.copy(), rc
            print("NEW BEST (Phase B %s) R=%.9f af=%.4f" % (tag, bestR, _argmax_frac(best)))

    print("Phase B: R=%.9f af=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase C: sharpening ladder + peak ladder ----
    if time.process_time() < deadline - 2.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        if R_of(ht) > bestR + 1e-14:
            best, bestR = ht.copy(), R_of(ht)
            print("NEW BEST (Phase C sharp) R=%.9f" % bestR)
    if time.process_time() < deadline - 1.0:
        ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=250)
        if R_of(ht2) > bestR + 1e-14:
            best, bestR = ht2.copy(), R_of(ht2)
            print("NEW BEST (Phase C peak) R=%.9f" % bestR)

    print("Phase C: R=%.9f af=%.4f" % (bestR, _argmax_frac(best)))
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, r, deadline, pads=(0.20, 0.12, 0.08, 0.05), iters=300):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3)
        rt = R_of(ht)
        if rt > r + 1e-14:
            h, r = ht, rt
    return h, r


def _prolong(h, k):
    n = h.size
    m = int(k) * n
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return _rescale(np.clip(np.diff(c_new), 0.0, None))


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    share = np.mean(Lf >= 0.999 * mx) if mx > 0 else 0.0
    zf = np.mean(h <= 1e-6 * h.max()) if h.max() > 0 else 1.0
    mm = h.max() / h.mean() if h.mean() > 0 else 0.0
    return share, zf, mm


def _refine(h, r, deadline, rounds=6):
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        improved = False
        for beta in (1e4, 1e5, 1e6):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(h, 200, deadline - 0.3, beta=beta)
            rt = R_of(ht)
            if rt > r + 1e-14:
                h, r, improved = ht, rt, True
        for pad in (0.30, 0.15, 0.07, 0.03):
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(h, pad_frac=pad)
            ht = _lbfgs_block(h, win, 300, deadline - 0.3)
            rt = R_of(ht)
            if rt > r + 1e-14:
                h, r, improved = ht, rt, True
        if not improved:
            break
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    # ---- Phase 1: refine start directly ----
    if start_arr is not None:
        h = start_arr.copy()
        r = R_of(h)
        print("start base R=%.6f N=%d" % (r, h.size))
        h, r = _refine(h, r, deadline - 2.0, "start")
        if r > best_r:
            best, best_r = h, r
        print("start-refined R=%.6f (was %.6f)" % (best_r, start_r))

    # ---- Phase 2: all-positive beta-homotopy ladder + resolution refinement ----
    if best is not None:
        h = best.copy()
        r = best_r
        max_len = 4 * 65536
        while time.process_time() < deadline - 6.0:
            # (a) prolong if room
            if h.size < max_len:
                ht = _prolong(h, 2)
                rt = R_of(ht)
                if rt > r - 1e-6:
                    h, r = ht, rt
            # (b) 3 rounds of beta ladder + peak ladder
            for _ in range(3):
                if time.process_time() >= deadline - 3.0:
                    break
                for b in (1e6, 1e7, 1e8, 0.0):
                    if time.process_time() >= deadline - 3.0:
                        break
                    ht = _lbfgs_all_pos(h, 400, deadline - 3.0, beta=b)
                    rt = R_of(ht)
                    if rt > r + 1e-14:
                        h, r = ht, rt
                h, r = _peak_ladder(h, r, deadline - 3.0,
                                    pads=(0.20, 0.12, 0.08, 0.05), iters=300)
                # zero out tiny entries
                thr = 1e-6 * h.max() if h.max() > 0 else 0.0
                h = h.copy()
                h[h < thr] = 0.0
                h = _rescale(h)
                r = R_of(h)
            share, zf, mm = _stats(h)
            print("N=%d R=%.6f zero=%.3f max/mean=%.1f top0.1%%=%.4f"
                  % (h.size, r, zf, mm, share))
            if r > best_r + 1e-12:
                best, best_r = h.copy(), r
            if h.size >= max_len:
                break

    # ---- Fallback fresh build ----
    if best is None:
        N = 256
        x = np.linspace(0, 1, N)
        h = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        cur_r = R_of(h)
        while N <= 65536 and time.process_time() < deadline - 4.0:
            h, cur_r = _refine(h, cur_r, deadline - 2.0, "fresh", rounds=3)
            N *= 2
            h = _rescale(_prolong(h, 2))
            cur_r = R_of(h)
        best, best_r = h, cur_r

    # ---- Final push until deadline ----
    if best is not None:
        best, best_r = _refine(best, best_r, deadline - 0.2, "final", rounds=20)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None:
        if best is not None and best_r > start_r + 1e-12:
            return {"best": _rescale(best), "alternative": _rescale(start_arr)}
        if best is not None and not np.array_equal(best, start_arr) and best_r > 0:
            return {"best": _rescale(start_arr), "alternative": _rescale(best)}
        return _rescale(start_arr)
    return _rescale(best)

