    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is None:
        # smooth bump seed
        N0 = 256
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        cur = _rescale(h)
        cur_r = R_of(cur)
        N = N0
        while N <= 262144:
            if time.process_time() >= deadline - 4.0:
                break
            cur = _polish_ladder(cur, min(deadline - 1.0, time.process_time() + 4.0),
                                 betas=(0.0, 1e6), iters=300)
            cur = _peak_ladder(cur, min(deadline - 1.0, time.process_time() + 3.0),
                               pads=(0.2, 0.1), iters=300)
            r = R_of(cur)
            if r > cur_r:
                cur_r = r
            if N >= 262144:
                break
            N = min(N * 2, 262144)
            cur = _rescale(_prolong(cur, N))
            cur_r = R_of(cur)
        return _rescale(cur)

    best = start_arr.copy()
    best_r = start_r
    print("start R=%.6f N=%d" % (best_r, best.size))

    # Ladder: double N aggressively, polish at each level.
    cur = start_arr.copy()
    cur_r = start_r
    N = start_arr.size
    while N < 1000000 and time.process_time() < deadline - 4.0:
        N2 = min(N * 2, 1000000)
        cur = _rescale(_prolong(cur, N2))
        cur_r = R_of(cur)
        N = N2
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        print("  prolong N=%d R=%.6f" % (N, cur_r))
        # polish: full-pos softmax ladder + peak block ladder
        cur = _polish_ladder(cur, deadline, betas=(1e6, 1e7, 0.0), iters=300)
        cur = _peak_ladder(cur, deadline, pads=(0.20, 0.12, 0.07, 0.04, 0.02), iters=400)
        cur_r = R_of(cur)
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        print("  polish   N=%d R=%.6f" % (N, cur_r))
        if time.process_time() >= deadline - 3.0:
            break

    # Final refinement at best N: multiple rounds until deadline.
    while time.process_time() < deadline - 0.5:
        prev = best_r
        cur = best.copy()
        cur = _polish_ladder(cur, deadline, betas=(1e7, 1e8, 0.0), iters=400)
        cur = _peak_ladder(cur, deadline, pads=(0.05, 0.03, 0.015, 0.008), iters=500)
        cur_r = R_of(cur)
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        print("  refine   R=%.6f (gain %.2e)" % (best_r, best_r - prev))
        if best_r - prev < 1e-10:
            break

    print("best R=%.6f (start %.6f) N=%d" % (best_r, start_r, best.size))
    if start_arr is not None and start_r >= best_r:
        return {"best": _rescale(start_arr), "alternative": _rescale(best)}
    if start_arr is not None:
        return {"best": _rescale(best), "alternative": _rescale(start_arr)}
    return _rescale(best)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _resample(h, n_new):
    n = h.size
    if n == n_new:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    x_new = np.linspace(0.0, 1.0, n_new, endpoint=False)
    return np.interp(x_new, x_old, h)


def _revive_zeros(h, factor, win=256):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    pos = h > 0
    if not pos.any():
        return h
    gmean = h[pos].mean()
    hp = np.where(pos, h, 0.0)
    cnt = pos.astype(float)
    cs = np.concatenate(([0.0], np.cumsum(hp)))
    cc = np.concatenate(([0.0], np.cumsum(cnt)))
    half = win // 2
    idx = np.arange(n)
    lo = np.clip(idx - half, 0, n)
    hi = np.clip(idx + half + 1, 0, n)
    ssum = cs[hi] - cs[lo]
    scnt = cc[hi] - cc[lo]
    local = np.where(scnt > 0, ssum / np.maximum(scnt, 1e-300), gmean)
    zeros = ~pos
    h[zeros] = factor * local[zeros]
    return _rescale(h)


def _perturb(h, rng, scale=0.05):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    p = rng.standard_normal(n) * scale
    if n > 8:
        k = max(3, n // 64)
        kern = np.ones(k) / k
        p = np.convolve(p, kern, mode='same')
    h = h * np.exp(p)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = _rescale(s.copy())
            best_r = R_of(best)

    if best is None:
        x = np.linspace(0, 1, 256)
        best = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best_r = R_of(best)

    print("start R = %.6f, N = %d" % (best_r, best.size))
    base_r = best_r
    rng = np.random.default_rng(12345)

    # Phase 1: smooth-max ladder on the start (crucial for breaking through
    # the non-smoothity of ||f*f||_inf, which stalls plain L-BFGS).
    h, cur_r = best.copy(), best_r
    h = _polish_ladder(h, deadline, betas=(1e5, 1e6, 1e7, 0.0), iters=400)
    r = R_of(h)
    if r > cur_r:
        cur_r = r
        print("  ladder1 R=%.6f" % cur_r)

    # Phase 2: peak-focused polish (only the region near the max of f*f)
    h = _peak_ladder(h, deadline, pads=(0.20, 0.12, 0.08, 0.05), iters=400)
    r = R_of(h)
    if r > cur_r:
        cur_r = r
        print("  peak1 R=%.6f" % cur_r)
    if cur_r > best_r:
        best, best_r = h.copy(), cur_r

    # Phase 3: zero-revival on best (open up dead regions and re-optimize)
    revived = []
    for factor in (1e-3, 1e-2, 1e-1):
        if time.process_time() >= deadline - 3.0:
            break
        hr = _revive_zeros(best, factor)
        hr = _polish_ladder(hr, deadline, betas=(1e5, 1e6, 1e7, 0.0), iters=300)
        hr = _peak_ladder(hr, deadline, pads=(0.15, 0.08, 0.04), iters=300)
        rr = R_of(hr)
        revived.append((rr, hr))
        print("  revive f=%.0e R=%.6f" % (factor, rr))
    if revived:
        revived.sort(key=lambda t: -t[0])
        rr, hr = revived[0]
        if rr > best_r:
            best, best_r = hr.copy(), rr
            print("revival improved to %.6f" % best_r)

    # Phase 4: alternate polish + occasional 2x upsample + restart perturbation
    h, cur_r = best.copy(), best_r
    it = 0
    did_upsample = False
    while time.process_time() < deadline - 1.0:
        it += 1
        # Upsample once, midway through, to refine fine structure
        if (not did_upsample) and h.size < 65536 and \
                time.process_time() < deadline - 15.0:
            hf = _resample(h, h.size * 2)
            hf = _rescale(hf)
            hf = _polish_ladder(hf, deadline, betas=(1e6, 1e7, 0.0), iters=250)
            rf = R_of(hf)
            if rf > cur_r:
                h, cur_r = hf, rf
                print("  up2x R=%.6f N=%d" % (cur_r, h.size))
            did_upsample = True

        h = _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=250)
        h = _peak_ladder(h, deadline, pads=(0.12, 0.06, 0.03), iters=300)
        cur_r = R_of(h)

        if it % 3 == 0 and time.process_time() < deadline - 5.0:
            hp = _perturb(h, rng, scale=0.02)
            hp = _polish_ladder(hp, deadline, betas=(1e5, 1e6, 1e7, 0.0),
                                iters=250)
            rp = R_of(hp)
            if rp > cur_r + 1e-10:
                h, cur_r = hp, rp

        if cur_r > best_r:
            best, best_r = h.copy(), cur_r
        print("  alt %d R=%.6f (best %.6f) N=%d" % (it, cur_r, best_r, best.size))

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        if best_r > base_r + 1e-12:
            return {"best": best, "alternative": start_arr}
        return {"best": start_arr, "alternative": best}
    return best

