def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _densify(h):
    h = np.clip(h, 0, None)
    pos = h[h > 0]
    if pos.size == 0:
        return h
    eps = 1e-6 * pos.mean()
    out = h.copy()
    out[out <= 0] = eps
    return _rescale(out)


def _resample_smooth(h, newn):
    h = np.clip(h, 0, None)
    n = h.size
    if n == newn:
        return h.copy()
    if n == 0 or h.sum() <= 0:
        return h
    c = np.concatenate(([0.0], np.cumsum(h)))
    c /= c[-1]
    xs = np.linspace(0.0, 1.0, newn + 1)
    cn = np.interp(xs, np.linspace(0.0, 1.0, n + 1), c)
    hn = np.diff(cn)
    return _rescale(np.clip(hn, 0, None))


def _shrink_zeros(h):
    h = np.clip(h, 0, None)
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    return h[nz[0]:nz[-1] + 1]


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    trimmed = _shrink_zeros(best)
    if trimmed.size > 0:
        trimmed = _rescale(trimmed)
        r = R_of(trimmed)
        if r > bestR - 1e-9:
            best, bestR = trimmed, r
    print("trim R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: full polishing cycle at current resolution.
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 0.8)
        print("cycle R=%.7f" % bestR)

    # Phase 2: fine-upsample sweep. The new idea: progressively upsample
    # (rather than resample onto arbitrary target sizes) and polish each time,
    # keeping the best. This preserves the discrete structure that gives the
    # record R while gaining the resolution needed to sharpen the plateau.
    factor = 2
    while time.process_time() < deadline - 1.5 and best.size < 900000:
        nn = min(int(best.size * factor), 950000)
        if nn <= best.size:
            break
        hseed = _resample_smooth(best, nn)
        hseed = _densify(hseed)
        ht = _lbfgs_all_pos(hseed, 600, deadline - 1.0, beta=0.0)
        ht = _lbfgs_all_pos(ht, 300, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            print("upsample x%d N=%d R=%.7f" % (factor, best.size, bestR))
            factor = 2
        else:
            # keep going finer regardless; try next factor
            factor += 1
            if factor > 4:
                break

    # Phase 3: peak-focused block polish at the best resolution.
    if time.process_time() < deadline - 1.0:
        for pad in (0.20, 0.10, 0.05):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, tol=0.99, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 1.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
                print("peak pad=%.2f R=%.7f" % (pad, bestR))

    # Phase 4: keep improving until the deadline.
    it = 0
    while time.process_time() < deadline - 0.8:
        it += 1
        hp = _densify(best)
        hp = _lbfgs_all_pos(hp, 1500, deadline - 0.5, beta=0.0)
        for beta in (1e6, 1e7, 1e8):
            if time.process_time() >= deadline - 0.5:
                break
            hp = _lbfgs_all_pos(hp, 250, deadline - 0.5, beta=beta)
        if time.process_time() < deadline - 0.5:
            win = _peak_window(hp, tol=0.99, pad_frac=0.15, extra=128)
            hp = _lbfgs_block(hp, win, 250, deadline - 0.5, beta=0.0)
        r = R_of(hp)
        if r > bestR + 1e-13:
            best, bestR = hp.copy(), r
            print("iter %d R=%.7f N=%d" % (it, bestR, best.size))

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xc = np.linspace(0.0, 1.0, Nc + 1)
    Sc = np.interp(xc, xs, S)
    Sc = np.maximum.accumulate(Sc)
    hc = np.clip(np.diff(Sc), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _smooth_peak_ladder(h, deadline, betas=(2e5, 5e5, 1e6, 3e6, 1e7, 0.0),
                        iters=400):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def _peak_polish(h, deadline, pads=(0.30, 0.18, 0.10, 0.06, 0.035), iters=500):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        for beta in (3e6, 1e7, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
    return h


def _asym_split(h, sigma, rng):
    n = h.size
    w0 = np.exp(sigma * rng.standard_normal(n))
    w1 = np.exp(sigma * rng.standard_normal(n))
    m = 0.5 * (w0 + w1)
    w0 /= m
    w1 /= m
    h2 = np.empty(2 * n)
    h2[0::2] = h * w0
    h2[1::2] = h * w1
    return _rescale(h2)


def _fold_mean(h2):
    return _rescale(0.5 * (h2[0::2] + h2[1::2]))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        h = np.ones(1024)
        h = _lbfgs_all_pos(h, 800, deadline - 1.0, beta=0.0)
        h = _smooth_peak_ladder(h, deadline - 0.5)
        return h

    cur = start_arr.copy()
    cur_r = best_r

    # Baseline refinement from the base program.
    cur = _smooth_peak_ladder(cur, deadline - 3.0)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("smooth R=%.8f" % best_r)

    cur = _peak_polish(cur, deadline - 1.5)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("peak   R=%.8f" % best_r)

    # Asymmetric 2N split exploration loop.
    rng = np.random.default_rng(987654321)
    N = best.size
    round_no = 0
    while time.process_time() < deadline - 15.0:
        round_no += 1
        h2 = _asym_split(best, sigma=0.5, rng=rng)
        # sharp L-BFGS at 2N
        h2 = _lbfgs_all_pos(h2, 120, deadline - 10.0, beta=0.0)
        # beta ladder at 2N
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 10.0:
                break
            ht = _lbfgs_all_pos(h2, 120, deadline - 10.0, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-15:
                h2 = ht
        # peak polish at 2N
        for pad in (0.12, 0.08, 0.05):
            if time.process_time() >= deadline - 10.0:
                break
            win = _peak_window(h2, pad_frac=pad, extra=128)
            for beta in (1e6, 1e7, 0.0):
                if time.process_time() >= deadline - 10.0:
                    break
                ht = _lbfgs_block(h2, win, 120, deadline - 10.0, beta=beta)
                if R_of(ht) > R_of(h2) + 1e-15:
                    h2 = ht
        r2 = R_of(h2)
        # fold back to N
        hf = _fold_mean(h2)
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 10.0:
                break
            ht = _lbfgs_all_pos(hf, 120, deadline - 10.0, beta=beta)
            if R_of(ht) > R_of(hf) + 1e-15:
                hf = ht
        for pad in (0.08, 0.05):
            if time.process_time() >= deadline - 10.0:
                break
            win = _peak_window(hf, pad_frac=pad, extra=128)
            for beta in (1e6, 1e7, 0.0):
                if time.process_time() >= deadline - 10.0:
                    break
                ht = _lbfgs_block(hf, win, 120, deadline - 10.0, beta=beta)
                if R_of(ht) > R_of(hf) + 1e-15:
                    hf = ht
        rf = R_of(hf)
        if rf > best_r + 1e-15:
            best, best_r = hf.copy(), rf
            print("NEW BEST R=%.8f (2N R=%.8f, round %d)" % (best_r, r2, round_no))
        else:
            # try to keep some progress if 2N was better but fold lost it
            if r2 > best_r + 1e-15:
                # keep h2 as alternative path: coarsen back via prolongate inverse
                hc = _coarsen(h2, N)
                rc = R_of(hc)
                if rc > best_r + 1e-15:
                    best, best_r = hc, rc
                    print("NEW BEST(coarse) R=%.8f" % best_r)

    # Final sharp ladder + small peak polish.
    if time.process_time() < deadline - 0.5:
        for beta in (1e8, 1e9, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 0.3, beta=beta)
            if R_of(ht) > best_r + 1e-15:
                best, best_r = ht, R_of(ht)
                print("final  R=%.8f" % best_r)
    if time.process_time() < deadline - 0.5:
        cand = _peak_polish(best, deadline - 0.3, pads=(0.05, 0.03), iters=300)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
            print("polish R=%.8f" % best_r)

    if start_arr is not None and R_of(start_arr) >= best_r:
        if cur.shape == start_arr.shape and not np.allclose(cur, start_arr, rtol=0, atol=0):
            return {"best": start_arr, "alternative": cur}
        return start_arr

    if start_arr is not None and not np.allclose(best, start_arr, rtol=0, atol=0):
        return {"best": best, "alternative": start_arr}

    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _deficit_free(h, frac=0.15):
    """Cells whose perturbation most affects mid-level knots via backprojection
    of the deficit integrand g(M-g)/M."""
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(h.size)
    gLf = (M - 2.0 * Lf) / M
    s = np.abs(_backprop(gLf, h))
    N = h.size
    k = max(1, int(frac * N))
    if k >= N:
        return np.arange(N)
    idx = np.argpartition(-s, k - 1)[:k]
    return np.sort(idx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase A: half-resolution quotient polish (kept from base) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.15
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase D: deficit-sensitivity rounds (the experiment) ----
    deficit_deadline = deadline - 8.0
    for rnd in range(3):
        if time.process_time() >= deficit_deadline - 2.0:
            break
        free = _deficit_free(best, frac=0.15)
        if free.size == 0:
            print("deficit round=%d: no free cells" % rnd)
            continue
        ht = _lbfgs_block(best, free, 300, deficit_deadline, beta=1e6)
        ht = _lbfgs_block(ht, free, 300, deficit_deadline, beta=0.0)
        ht = _peak_ladder(ht, deficit_deadline, pads=(0.08, 0.05), iters=250)
        r = R_of(ht)
        improved = offer(ht, 'deficit_%d' % rnd)
        print("deficit round=%d freed=%d R=%.9f (best %.9f) improved=%s"
              % (rnd, free.size, r, bestR, improved))

    # ---- Phase B: high-beta sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=300)
        offer(ht, 'sharp')

    # ---- Phase P: pool keyed on argmax position ----
    pool = []

    def pool_insert(h, r):
        if h is None or h.size != best.size or h.sum() <= 0:
            return
        af = _argmax_frac(h)
        for i, (rr, hh) in enumerate(pool):
            if abs(_argmax_frac(hh) - af) < 0.005:
                if r > rr + 1e-14:
                    pool.pop(i)
                    pool.append((r, h.copy()))
                pool.sort(key=lambda x: -x[0])
                return
        pool.append((r, h.copy()))
        pool.sort(key=lambda x: -x[0])
        while len(pool) > 5:
            pool.pop()

    pool_insert(best, bestR)

    # ---- Seed pool with four variants ----
    seed_deadline = deadline - 20.0

    def _roundtrip_from_fine(h_fine, N, dl):
        h_back = _fold_back(h_fine, N)
        h_back = _rescale(h_back)
        h_back = _polish_ladder(h_back, dl, betas=(1e7, 1e8, 0.0), iters=250)
        h_back = _peak_ladder(h_back, dl, pads=(0.08, 0.05), iters=250)
        return h_back

    N = best.size

    if time.process_time() < seed_deadline - 4.0 and N >= 4:
        c = best[0::2].copy()
        c = _polish_ladder(c, seed_deadline - 3.0, betas=(1e6, 1e7, 0.0), iters=200)
        h_fine = _interlace_32(c, 3 * c.size // 2, rng)
        h_fine = _rescale(h_fine)
        h_fine = _polish_ladder(h_fine, seed_deadline - 2.0, betas=(1e7, 0.0), iters=200)
        h1 = _roundtrip_from_fine(h_fine, N, seed_deadline - 1.0)
        pool_insert(h1, R_of(h1))
        offer(h1, 'v1')

    if time.process_time() < seed_deadline - 4.0 and N >= 4:
        c = best[1::2].copy()
        c = _polish_ladder(c, seed_deadline - 3.0, betas=(1e6, 1e7, 0.0), iters=200)
        h_fine = _interlace_32(c, 3 * c.size // 2, rng)
        h_fine = _rescale(h_fine)
        h_fine = _polish_ladder(h_fine, seed_deadline - 2.0, betas=(1e7, 0.0), iters=200)
        h2 = _roundtrip_from_fine(h_fine, N, seed_deadline - 1.0)
        pool_insert(h2, R_of(h2))
        offer(h2, 'v2')

    if time.process_time() < seed_deadline - 4.0:
        w = np.exp(0.15 * rng.standard_normal(2 * N))
        h_fine = np.repeat(best, 2) * w
        h_fine = _rescale(h_fine)
        h_fine = _polish_ladder(h_fine, seed_deadline - 2.0, betas=(1e7, 0.0), iters=200)
        h3 = _roundtrip_from_fine(h_fine, N, seed_deadline - 1.0)
        pool_insert(h3, R_of(h3))
        offer(h3, 'v3')

    if time.process_time() < seed_deadline - 4.0:
        h4 = best.copy()
        zeros = np.flatnonzero(h4 <= 0)
        if zeros.size > 0:
            k = max(1, int(0.005 * zeros.size))
            sel = rng.choice(zeros, size=min(k, zeros.size), replace=False)
            mean_h = h4[h4 > 0].mean() if np.any(h4 > 0) else 1.0
            h4[sel] = 1e-2 * mean_h
            h4 = _rescale(h4)
            h4 = _polish_ladder(h4, seed_deadline - 2.0, betas=(1e7, 0.0), iters=200)
            h4 = _peak_ladder(h4, seed_deadline - 1.0, pads=(0.08, 0.05), iters=200)
            pool_insert(h4, R_of(h4))
            offer(h4, 'v4')

    print("pool seeded size=%d" % len(pool))

    # ---- Phase Q: round-robin lift rounds over pool ----
    pool_deadline = deadline - 4.0
    rounds = 0
    while time.process_time() < pool_deadline - 2.0 and len(pool) > 0:
        rounds += 1
        order = sorted(range(len(pool)), key=lambda i: -pool[i][0])
        progressed = False
        for i in order:
            if time.process_time() >= pool_deadline - 2.0:
                break
            if i >= len(pool):
                continue
            rr, hh = pool[i]
            cand = _lift_round(hh, rng, pool_deadline)
            rc = R_of(cand)
            if rc > bestR + 1e-14:
                best, bestR = cand.copy(), rc
                print("NEW BEST (pool) R=%.9f round=%d" % (bestR, rounds))
                progressed = True
            if rc > bestR - 5e-6:
                pool_insert(cand, rc)
                progressed = True
        if not progressed and time.process_time() < pool_deadline - 3.0:
            cand = _lift_round(best, rng, pool_deadline)
            rc = R_of(cand)
            if rc > bestR + 1e-14:
                best, bestR = cand.copy(), rc
                print("NEW BEST (pool-best) R=%.9f round=%d" % (bestR, rounds))
            if rc > bestR - 5e-6:
                pool_insert(cand, rc)

    print("pool rounds=%d pool_size=%d" % (rounds, len(pool)))

    # ---- Final polish on best ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 1e10, 0.0), iters=300)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht.copy(), R_of(ht)
        print("NEW BEST (finalhi) R=%.9f" % bestR)
    ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=250)
    if R_of(ht2) > bestR + 1e-14:
        best, bestR = ht2.copy(), R_of(ht2)
        print("NEW BEST (finalpeak) R=%.9f" % bestR)

    for (rr, hh) in pool:
        if rr > bestR + 1e-14:
            best, bestR = hh.copy(), rr
            print("NEW BEST (pool-final) R=%.9f" % bestR)
            break

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result


def _interlace_32(c, n_target, rng):
    m = c.size
    if m < 2:
        return np.repeat(c, max(1, n_target // max(1, m)))[:n_target]
    cm = np.cumsum(c)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    jitter = np.exp(0.02 * rng.standard_normal(n_target))
    t = np.clip(t * jitter, 1e-9, 1 - 1e-9)
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, m - 1)
    return c[idx].astype(float)


def _fold_back(h_fine, n_target):
    n = h_fine.size
    if n == n_target:
        return h_fine.copy()
    cm = np.cumsum(h_fine)
    if cm[-1] <= 0:
        return np.zeros(n_target)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, n - 1)
    return h_fine[idx].astype(float)


def _lift_round(member, rng, deadline):
    N = member.size
    if N % 2 == 0 and N >= 4:
        c = member[0::2].copy()
    else:
        c = member[::2].copy()
    c = _polish_ladder(c, deadline, betas=(1e6, 1e7, 0.0), iters=200)
    c = _peak_ladder(c, deadline, pads=(0.20, 0.12, 0.08), iters=250)
    h_fine = _interlace_32(c, 3 * c.size // 2, rng)
    h_fine = _rescale(h_fine)
    h_fine = _polish_ladder(h_fine, deadline, betas=(1e7, 1e8, 0.0), iters=200)
    h_back = _fold_back(h_fine, N)
    h_back = _rescale(h_back)
    h_back = _polish_ladder(h_back, deadline, betas=(1e7, 1e8, 0.0), iters=250)
    h_back = _peak_ladder(h_back, deadline, pads=(0.08, 0.05), iters=250)
    return h_back

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol, pad_frac, extra):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _diff_evolve(h, deadline, pop, sigma, iters=100, seed=0):
    """Simple (1+pop) evolution strategy on the height vector via random
    smooth perturbations; accepts improvements. Cheap escape from local max."""
    rng = np.random.RandomState(seed)
    n = h.size
    best = h.copy()
    bestR = R_of(best)
    # smooth kernel for correlated perturbations
    k = max(1, n // 500)
    ker = np.ones(k) / k
    for it in range(iters):
        if time.process_time() >= deadline - 0.5:
            break
        acc = None
        for p in range(pop):
            if time.process_time() >= deadline - 0.5:
                break
            noise = rng.randn(n)
            noise = np.convolve(noise, ker, mode='same')
            cand = np.clip(best + sigma * bestR ** 0 * noise * best.std(), 0, None)
            if cand.sum() <= 0:
                continue
            cand = _rescale(cand)
            r = R_of(cand)
            if r > bestR + 1e-13:
                best, bestR = cand, r
                acc = True
        if acc is None:
            sigma *= 0.7
            if sigma < 1e-6:
                break
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        # Global polish.
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 1500, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        # Multi-scale peak-window polish.
        for (frac, extra) in [(0.03, 48), (0.08, 96), (0.18, 192),
                              (0.35, 384), (0.60, 640)]:
            if time.process_time() >= deadline - 2.0:
                break
            win = _peak_window(best, 0.999, frac, extra)
            ht = _lbfgs_block(best, win, 400, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        # NEW: evolutionary perturbation escape (smooth correlated noise).
        if time.process_time() < deadline - 3.0:
            ht = _diff_evolve(best, deadline - 2.0, pop=6, sigma=0.02,
                              iters=20, seed=cycle)
            ht = _lbfgs_all_pos(ht, 500, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        # Targeted trimming.
        if time.process_time() < deadline - 3.0:
            h = best
            Lf = _knots(h)
            m = int(np.argmax(Lf))
            left = np.arange(0, min(m, h.size))
            right = np.arange(min(m + 1, h.size), h.size)
            cands = []
            if left.size > 8:
                cands.append(left[:max(1, left.size // 20)])
            if right.size > 8:
                cands.append(right[-max(1, right.size // 20):])
            for idxs in cands:
                if time.process_time() >= deadline - 3.0:
                    break
                h2 = h.copy()
                h2[idxs] = 0.0
                if h2.sum() <= 0:
                    continue
                h2 = _rescale(h2)
                ht = _lbfgs_all_pos(h2, 400, deadline - 2.0)
                r = R_of(ht)
                if r > bestR + 1e-13:
                    best, bestR = ht.copy(), r
                    break

        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, N))

    # Final long polish.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 8000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        win = _peak_window(best, 0.999, 0.5, 512)
        ht = _lbfgs_block(best, win, 1000, deadline - 0.2)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample(h, factor):
    if factor <= 1:
        return h.copy()
    n = h.size
    m = (n - 1) * factor + 1
    out = np.zeros(m, dtype=float)
    idx = np.arange(n) * factor
    out[idx] = h
    for k in range(1, factor):
        out[idx[:-1] + k] = ((factor - k) * h[:-1] + k * h[1:]) / factor
    return out


def _smooth(h, k):
    """Local moving-average smoothing preserving support roughly."""
    if k <= 1:
        return h
    ker = np.ones(k) / k
    return np.convolve(h, ker, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR + 1e-14:
            alt_best, alt_bestR = cand.copy(), r
        return False

    def refine(h, dl, tag, pads=(0.10, 0.06, 0.04, 0.03), iters=400):
        for b in (1e6, 1e7, 0.0):
            if time.process_time() >= dl - 0.5:
                return h
            ht = _lbfgs_all_pos(h, iters, dl - 0.3, beta=b)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
                offer(h, tag + '_b%.0e' % b)
        for pad in pads:
            if time.process_time() >= dl - 0.5:
                return h
            win = _peak_window(h, pad_frac=pad, extra=128)
            ht = _lbfgs_block(h, win, iters, dl - 0.3, beta=1e7)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
                offer(h, tag + '_pk%.2f' % pad)
            ht2 = _lbfgs_block(h, win, iters, dl - 0.3, beta=0.0)
            if R_of(ht2) > R_of(h) + 1e-14:
                h = ht2
                offer(h, tag + '_pk%.2f_b0' % pad)
        return h

    # NEW IDEA: perturbation / smoothing restarts to escape local optima.
    # We smooth the current best with a small kernel (introduces a different
    # local basin by mixing neighbouring heights), then re-optimise.
    cur = best.copy()
    curR = bestR
    cycle = 0

    while time.process_time() < deadline - 2.0:
        cycle += 1
        cyc_start = curR

        # (a) standard refinement
        cur = refine(cur, deadline - 1.0, 'c%d' % cycle)
        curR = R_of(cur)
        offer(cur, 'refine_c%d' % cycle)
        if time.process_time() >= deadline - 2.0:
            break

        # (b) smoothing perturbation: several kernel widths tried in turn
        improved = False
        for k in (3, 5, 9, 17):
            if time.process_time() >= deadline - 2.0:
                break
            hs = _smooth(cur, k)
            hs = _rescale(hs)
            hsR0 = R_of(hs)
            hs = refine(hs, deadline - 1.0, 'sm%d' % k, pads=(0.06, 0.04), iters=300)
            hsR = R_of(hs)
            print("smooth k=%d R %.9f -> %.9f" % (k, hsR0, hsR))
            if offer(hs, 'smooth%d' % k):
                improved = True
            if hsR > curR + 1e-12:
                cur = hs
                curR = hsR
                improved = True
                break  # adopt and continue main loop

        # (c) upsample fallback if smoothing didn't help
        if not improved and cur.size < 900000:
            newN = (cur.size - 1) * 2 + 1
            if newN <= 950000:
                up = _rescale(_upsample(cur, 2))
                upR0 = R_of(up)
                up = refine(up, deadline - 1.0, 'up%d' % up.size)
                upR = R_of(up)
                print("upsample N=%d->%d R %.9f -> %.9f" %
                      (cur.size, up.size, upR0, upR))
                if offer(up, 'upsample'):
                    improved = True
                if upR > curR + 1e-12:
                    cur = up
                    curR = upR

        print("cycle %d R=%.9f (d=%.2e) N=%d" % (cycle, curR, curR - cyc_start, cur.size))

        if cycle >= 4 and abs(curR - cyc_start) < 1e-13:
            print("flat, stopping")
            break

    if time.process_time() < deadline - 1.0:
        polished = refine(best, deadline - 0.5, 'final', pads=(0.03, 0.02), iters=300)
        offer(polished, 'final')

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

