    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _knot_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _deficit_free(h, frac=0.15):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(h.size)
    gLf = (M - 2.0 * Lf) / M
    s = np.abs(_backprop(gLf, h))
    N = h.size
    k = max(1, int(frac * N))
    if k >= N:
        return np.arange(N)
    idx = np.argpartition(-s, k - 1)[:k]
    return np.sort(idx)


def _asym_split(h, sigma, rng, phase='even'):
    n = h.size
    w0 = np.exp(sigma * rng.standard_normal(n))
    w1 = np.exp(sigma * rng.standard_normal(n))
    s = (w0 + w1) / 2.0
    w0 = w0 / s
    w1 = w1 / s
    out = np.empty(2 * n)
    out[0::2] = h * w0
    out[1::2] = h * w1
    return out


def _shift_split(h):
    n = h.size
    out = np.empty(2 * n)
    out[0::2] = 0.5 * h
    out[1::2] = 0.5 * (h + np.roll(h, 1))
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f N=%d (%s)" % (bestR, best.size, tag))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase S: asymmetric splits of the staircase to 2N ----
    N0 = best.size
    parent = best.copy()
    parentR = bestR
    print("parent N=%d R=%.9f shares=%.4f/%.4f/%.4f"
          % (N0, parentR, *_knot_shares(parent)))

    cands = []
    if time.process_time() < deadline - 20.0:
        c1 = _rescale(_asym_split(parent, 0.6, rng))
        cands.append(('asym0.6', c1))
    if time.process_time() < deadline - 20.0:
        c2 = _rescale(_asym_split(parent, 0.25, rng))
        cands.append(('asym0.25', c2))
    if time.process_time() < deadline - 20.0:
        c3 = _rescale(_shift_split(parent))
        cands.append(('shift', c3))

    fine_best = None
    fine_bestR = -1.0

    for tag, cand in cands:
        if time.process_time() >= deadline - 15.0:
            break
        r0 = R_of(cand)
        cand = _polish_ladder(cand, deadline - 10.0,
                              betas=(1e5, 1e6, 1e7, 0.0), iters=200)
        cand = _peak_ladder(cand, deadline - 8.0,
                            pads=(0.20, 0.12, 0.08, 0.05), iters=250)
        rc = R_of(cand)
        sh = _knot_shares(cand)
        print("split %s: N=%d R0=%.9f R=%.9f shares=%.4f/%.4f/%.4f"
              % (tag, cand.size, r0, rc, *sh))
        offer(cand, tag)
        if rc > fine_bestR:
            fine_best, fine_bestR = cand.copy(), rc

    # ---- Phase T: second split to 4N if time remains ----
    if fine_best is not None and time.process_time() < deadline - 12.0:
        c4 = _rescale(_asym_split(fine_best, 0.3, rng))
        c4 = _polish_ladder(c4, deadline - 6.0,
                            betas=(1e5, 1e6, 1e7, 0.0), iters=200)
        c4 = _peak_ladder(c4, deadline - 4.0,
                          pads=(0.20, 0.12, 0.08, 0.05), iters=250)
        rc = R_of(c4)
        sh = _knot_shares(c4)
        print("split2 asym0.3: N=%d R=%.9f shares=%.4f/%.4f/%.4f"
              % (c4.size, rc, *sh))
        offer(c4, 'split2')
        if rc > fine_bestR:
            fine_best, fine_bestR = c4.copy(), rc

    # ---- Final polish on best ----
    if time.process_time() < deadline - 2.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e7, 1e8, 1e9, 0.0), iters=300)
        offer(ht, 'finalhi')
    if time.process_time() < deadline - 1.0:
        ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=250)
        offer(ht2, 'finalpeak')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _interlace_32(c, n_target, rng):
    m = c.size
    if m < 2:
        return np.repeat(c, max(1, n_target // max(1, m)))[:n_target]
    cm = np.cumsum(c)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    jitter = np.exp(0.02 * rng.standard_normal(n_target))
    t = np.clip(t * jitter, 1e-9, 1 - 1e-9)
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, m - 1)
    return c[idx].astype(float)


def _fold_back(h_fine, n_target):
    n = h_fine.size
    if n == n_target:
        return h_fine.copy()
    cm = np.cumsum(h_fine)
    if cm[-1] <= 0:
        return np.zeros(n_target)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, n - 1)
    return h_fine[idx].astype(float)


def _refine(h, rng, deadline, iters=250):
    """Cheap local refinement: smooth + peak polish, accept if better."""
    h0 = h.copy()
    r0 = R_of(h0)
    ht = _polish_ladder(h0, deadline, betas=(1e7, 0.0), iters=iters)
    if R_of(ht) > r0 + 1e-15:
        h0, r0 = ht, R_of(ht)
    ht = _peak_ladder(h0, deadline, pads=(0.04,), iters=iters)
    if R_of(ht) > r0 + 1e-15:
        h0, r0 = ht, R_of(ht)
    return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: aggressive coordinate-wise ascent on the current best,
    #      using fine-grained block windows across the whole support ----
    # Improve wherever there's slack by sweeping windows over the support.
    def sweep_windows(h, deadline, n_windows=8, overlap=0.35, iters=150):
        N = h.size
        if N < 8:
            return h
        win_len = max(64, N // n_windows)
        step = max(1, int(win_len * (1 - overlap)))
        starts = list(range(0, max(1, N - win_len + 1), step))
        if starts and starts[-1] + win_len < N:
            starts.append(N - win_len)
        for s in starts:
            if time.process_time() >= deadline - 0.5:
                break
            e = min(N, s + win_len)
            idx = np.arange(s, e)
            ht = _lbfgs_block(h, idx, iters, deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > R_of(h) + 1e-15:
                h = ht
        return h

    # Phase 1: sweep the support looking for local slack
    work = best.copy()
    work = sweep_windows(work, t0 + budget_seconds * 0.30, n_windows=10,
                         overlap=0.4, iters=120)
    work = _peak_ladder(work, t0 + budget_seconds * 0.35,
                        pads=(0.10, 0.06, 0.04), iters=200)
    r = R_of(work)
    if r > bestR + 1e-14:
        best, bestR = work.copy(), r
        print("NEW BEST (sweep) R=%.9f" % bestR)

    # ---- Phase 2: 3:2 interlace lift + fold-back, multiple tries ----
    lift_deadline = t0 + budget_seconds * 0.70
    tries = 0
    while time.process_time() < lift_deadline - 2.0 and tries < 10:
        tries += 1
        N = best.size
        if N < 4:
            break
        c = best[0::2].copy()
        c = _polish_ladder(c, lift_deadline, betas=(1e7, 0.0), iters=150)
        n_fine = max(4, 3 * c.size // 2)
        w = np.exp(0.02 * rng.standard_normal(n_fine))
        h_fine = _interlace_32(c, n_fine, rng) * w
        h_fine = _rescale(h_fine)
        h_fine = _polish_ladder(h_fine, lift_deadline, betas=(1e7, 0.0), iters=150)
        h_back = _fold_back(h_fine, N)
        h_back = _rescale(h_back)
        h_back = _peak_ladder(h_back, lift_deadline, pads=(0.06, 0.04), iters=180)
        r2 = R_of(h_back)
        if r2 > bestR + 1e-14:
            best, bestR = h_back.copy(), r2
            print("NEW BEST (lift) R=%.9f try=%d" % (bestR, tries))
        else:
            print("lift try=%d R=%.9f (best %.9f) rejected" % (tries, r2, bestR))
            if r2 > alt_bestR and h_back.size == best.size:
                alt_best, alt_bestR = h_back.copy(), r2

    # ---- Phase 3: final concentrated polish ----
    ht = _polish_ladder(best, deadline - 2.0, betas=(1e8, 1e9, 1e10, 0.0), iters=300)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht.copy(), R_of(ht)
        print("NEW BEST (finalhi) R=%.9f" % bestR)
    ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04, 0.03), iters=250)
    if R_of(ht2) > bestR + 1e-14:
        best, bestR = ht2.copy(), R_of(ht2)
        print("NEW BEST (finalpeak) R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _refine_blocked(h, deadline, rng, rounds=3):
    """Free contiguous blocks of varying size, refine each with beta-ladder."""
    n = h.size
    for r in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        # split into blocks and refine each
        nb = 4 + r
        edges = np.linspace(0, n, nb + 1).astype(int)
        for k in range(nb):
            if time.process_time() >= deadline - 1.0:
                break
            lo, hi = edges[k], edges[k + 1]
            if hi - lo < 4:
                continue
            free = np.arange(lo, hi)
            for beta in (1e7, 1e8, 0.0):
                if time.process_time() >= deadline - 1.0:
                    break
                ht = _lbfgs_block(h, free, 200, deadline - 0.5, beta=beta)
                if R_of(ht) > R_of(h) + 1e-15:
                    h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(20240917)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase A: sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, t0 + budget_seconds * 0.25,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        if R_of(ht) > bestR + 1e-14:
            best, bestR = ht, R_of(ht)
            print("NEW BEST (sharp) R=%.9f" % bestR)

    # ---- Phase B: blocked coordinate refinement over whole vector ----
    block_deadline = t0 + budget_seconds * 0.65
    ht = _refine_blocked(best, block_deadline, rng, rounds=4)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht, R_of(ht)
        print("NEW BEST (blocked) R=%.9f" % bestR)

    # ---- Phase C: peak/off-peak alternating ----
    off_deadline = t0 + budget_seconds * 0.88
    settings = [
        ('peak',    0.9995, 0.30, 1e7),
        ('offpeak', 0.98, 0.06, 1e7),
        ('peak',    0.999,  0.20, 1e8),
        ('offpeak', 0.95, 0.15, 1e7),
        ('peak',    0.9995, 0.50, 1e8),
        ('offpeak', 0.98, 0.04, 0.0),
        ('peak',    0.999,  0.30, 0.0),
    ]
    accepted = 0
    rounds = 0
    while time.process_time() < off_deadline - 1.0:
        for (kind, tol, pad, beta) in settings:
            if time.process_time() >= off_deadline - 1.0:
                break
            rounds += 1
            win = _peak_window(best, tol=tol, pad_frac=pad, extra=64)
            if kind == 'offpeak':
                mask = np.ones(best.size, dtype=bool)
                mask[win] = False
                free = np.flatnonzero(mask)
            else:
                free = win
            cand = _lbfgs_block(best, free, 500, deadline - 3.0, beta=beta)
            r = R_of(cand)
            if cand.size == best.size and r > bestR + 1e-14:
                best, bestR = cand.copy(), r
                accepted += 1
                print("NEW BEST (%s) R=%.9f beta=%.0e" % (kind, bestR, beta))
    print("block rounds=%d accepted=%d" % (rounds, accepted))

    # ---- Phase D: fine local polish ----
    ht = _polish_ladder(best, deadline - 0.6, betas=(1e9, 1e10, 1e11, 0.0),
                        iters=250)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht, R_of(ht)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR - 1e-12:
        result["alternative"] = alt_best
    return result

