def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
            start_bestR = bestR
        else:
            best, bestR, start_bestR = None, 0.0, 0.0
    else:
        best, bestR, start_bestR = None, 0.0, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)
        start_bestR = bestR

    start_best = best.copy()
    mx0, m0, near1_0 = _stats(best)
    print("base R=%.7f (N=%d) argmax=%d near1%%=%.3f" % (bestR, best.size, m0, near1_0))

    # ---- Stage 1: peak-window ladder (targets the flat near-max region) ----
    if time.process_time() < deadline - 3.0:
        sub = min(deadline - 2.0, time.process_time() + budget_seconds * 0.22)
        h = _peak_ladder(best, sub)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            mx, m, near1 = _stats(best)
            print("  peak-ladder R=%.7f argmax=%d near1%%=%.3f" % (bestR, m, near1))

    # ---- Stage 2: global polish ladder ----
    if time.process_time() < deadline - 3.0:
        sub = min(deadline - 2.0, time.process_time() + budget_seconds * 0.20)
        h = _polish_ladder(best, sub)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("  polish-ladder R=%.7f" % bestR)

    # ---- Stage 3: alternating random-window block + peak refinement ----
    rng = np.random.RandomState(1234567)
    n = best.size
    rounds = 0
    while time.process_time() < deadline - 2.0:
        rounds += 1
        # pick window: sometimes the peak region, sometimes a random region
        if rng.rand() < 0.55:
            win = _peak_window(best, pad_frac=float(rng.uniform(0.02, 0.20)),
                                extra=int(rng.randint(64, 512)))
        else:
            wlen = int(rng.randint(max(256, n // 16), max(512, n // 3)))
            wlo = int(rng.randint(0, max(1, n - wlen)))
            win = np.arange(wlo, min(n, wlo + wlen))
        sub = min(deadline - 1.5, time.process_time() + budget_seconds * 0.10)
        beta = float(rng.choice([0.0, 1e6, 1e7]))
        ht = _lbfgs_block(best, win, 250, sub, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            mx, m, near1 = _stats(best)
            print("  R%d win=%d beta=%.0e R=%.7f near1%%=%.3f" %
                  (rounds, win.size, beta, bestR, near1))
        else:
            # try log-space global polish as fallback
            ht = _lbfgs_log(best, 150, sub, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
                print("  R%d log beta=%.0e R=%.7f" % (rounds, beta, bestR))
            else:
                print("  R%d win=%d beta=%.0e R=%.7f (no gain)" %
                      (rounds, win.size, beta, r))

    # ---- Final sharp polish ----
    final_deadline = t0 + budget_seconds * 0.97
    if time.process_time() < final_deadline - 1.0:
        h = _lbfgs_log(best, 300, final_deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
        print("final sharp R=%.7f" % bestR)

    mx, m, near1 = _stats(best)
    print("final R=%.7f (N=%d) argmax=%d near1%%=%.3f" % (bestR, best.size, m, near1))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

