    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _halfmax_bounds(h):
    """Return (iL, iR): first and last knot index with Lf >= 0.5*M."""
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0, Lf.size - 1
    idx = np.flatnonzero(Lf >= 0.5 * M)
    if idx.size == 0:
        return 0, Lf.size - 1
    return int(idx.min()), int(idx.max())


def _joint_mask(h, pad1=None):
    N = h.size
    if pad1 is None:
        pad1 = max(64, N // 50)
    iL, iR = _halfmax_bounds(h)
    # iL,iR are knot indices in [0, N]; convert to height-index ranges
    # left tail: heights [0, iL+pad1)
    # right tail: heights [iR-pad1, N)
    left_hi = min(N, iL + pad1)
    right_lo = max(0, iR - pad1)
    parts = [np.arange(0, left_hi)]
    if right_lo < N:
        parts.append(np.arange(right_lo, N))
    # peak window pad=0.05
    peak = _peak_window(h, pad_frac=0.05, extra=128)
    parts.append(peak)
    mask = np.unique(np.concatenate(parts))
    return mask


def _joint_opt(h, deadline, iters=300):
    """Run joint-mask beta ladder; return best candidate found."""
    mask = _joint_mask(h)
    cur = h
    curR = R_of(h)
    for beta in (1e5, 1e6, 1e7, 1e8, 0.0):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(cur, mask, iters, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > curR + 1e-15:
            cur, curR = ht, r
    return cur, curR


def _grow_tails(h, tau_frac):
    """Append m cells at each end with geometric decay; return grown array."""
    N = h.size
    m = max(16, N // 100)
    eps = 1e-3 * h.mean()
    tau = max(1.0, m * tau_frac)
    k = np.arange(m, dtype=float)
    tail = eps * np.exp(-k / tau)
    left = tail[::-1].copy()
    right = tail.copy()
    return np.concatenate([left, h, right])


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        if cand.size > 1000000:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, cand.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size
    amax0 = _argmax_frac(best)
    iL0, iR0 = _halfmax_bounds(best)
    print("initial iL=%d iR=%d (N=%d)" % (iL0, iR0, N))

    # ---- Phase A: front-loaded joint-mask optimization ----
    a_deadline = t0 + budget_seconds * 0.25
    cand, r = _joint_opt(best, a_deadline, iters=250)
    offer(cand, 'A-joint')
    print("Phase A done R=%.9f" % bestR)

    # ---- Phase B: alternate joint-mask + tail-growth rounds ----
    b_deadline = deadline - 4.0
    rng = np.random.default_rng(12345)
    round_id = 0
    taus = (1.0 / 3.0, 1.0, 3.0)
    while time.process_time() < b_deadline:
        round_id += 1
        # joint-mask round on current best
        cand, r = _joint_opt(best, b_deadline, iters=250)
        improved = offer(cand, 'B%d-joint' % round_id)
        iL, iR = _halfmax_bounds(best)

        # tail-growth round: try each tau, accept best
        if best.size < 900000:
            best_grow = None
            best_growR = bestR
            for tf in taus:
                if time.process_time() >= b_deadline - 1.0:
                    break
                grown = _grow_tails(best, tf)
                if grown.size > 1000000:
                    continue
                grown = _rescale(grown)
                gc, gr = _joint_opt(grown, b_deadline, iters=200)
                if gr > best_growR + 1e-15:
                    best_grow, best_growR = gc, gr
            if best_grow is not None and best_growR > bestR + 1e-14:
                offer(best_grow, 'B%d-grow' % round_id)
                iL2, iR2 = _halfmax_bounds(best)
                print("B round=%d iL %d->%d iR %d->%d R=%.9f"
                      % (round_id, iL, iL2, iR, iR2, bestR))
            else:
                print("B round=%d iL=%d iR=%d R=%.9f (no gain)"
                      % (round_id, iL, iR, bestR))
        else:
            print("B round=%d iL=%d iR=%d R=%.9f (size cap)"
                  % (round_id, iL, iR, bestR))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.98
    ht = _peak_ladder(best, final_deadline - 0.8, pads=(0.06, 0.04), iters=250)
    offer(ht, 'final-peak')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.4, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.2, beta=0.0)
    offer(ht, 'final-plain')

    amax1 = _argmax_frac(best)
    iL1, iR1 = _halfmax_bounds(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f, iL=%d iR=%d)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best), iL1, iR1))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _full_polish(h, slice_deadline, pads=(0.30, 0.15, 0.08)):
    ht = h
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= slice_deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
    for pad in pads:
        if time.process_time() >= slice_deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pad, extra=128)
        ht = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
    if time.process_time() < slice_deadline - 0.5:
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=0.0)
    return ht


def _head_tail_polish(h, deadline, frac=0.06):
    """Polish the two tails of the support (where the flat top of f*f is shaped)."""
    n = h.size
    k = max(8, int(n * frac))
    idx = np.concatenate([np.arange(0, k), np.arange(n - k, n)])
    ht = _lbfgs_block(h, idx, 500, deadline, beta=1e7)
    if R_of(ht) > R_of(h) + 1e-14:
        h = ht
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(h, idx, 500, deadline, beta=0.0)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish ----
    N = best.size
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        h0 = best.copy()
        c = h0[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.22
        rounds = 0
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
            if time.process_time() >= half_deadline - 1.0:
                break
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        print("lifted R=%.9f" % r_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 400, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            print("lift+ladder R=%.9f (best %.9f)" % (r, bestR))

    # ---- Phase 2: head/tail polish of full-resolution best (new) ----
    if time.process_time() < deadline - 8.0:
        ht = _head_tail_polish(best, min(deadline - 6.0,
                                         time.process_time() + 8.0))
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+ht'
            print("head/tail NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2b: quotient-extract -> polish -> lift cycles ----
    cycle = 0
    accepted_cycles = 0
    while cycle < 6 and time.process_time() < deadline - 4.0:
        cycle += 1
        if best.size % 2 != 0:
            break
        c = best[0::2].copy()
        nz = c > 0
        if nz.sum() == 0:
            break
        rng = np.random.default_rng(100 + cycle)
        c[nz] *= np.exp(0.003 * rng.standard_normal(int(nz.sum())))
        c = _rescale(c)
        slice_dl = min(deadline - 3.0, time.process_time() + 6.0)
        cc = _full_polish(c, slice_dl, pads=(0.20, 0.10))
        rc = R_of(cc)
        h_lift = _rescale(np.repeat(cc, 2))
        hl = h_lift
        if time.process_time() < deadline - 1.5:
            hl = _lbfgs_all_pos(hl, 400, deadline - 1.5, beta=1e6)
        if time.process_time() < deadline - 1.5:
            hl = _lbfgs_all_pos(hl, 400, deadline - 1.5, beta=1e7)
        rl = R_of(hl)
        accepted = rl > bestR + 1e-13
        if accepted:
            best, bestR, origin = hl.copy(), rl, 'cycle%d' % cycle
            accepted_cycles += 1
            print("cycle %d R(c)=%.9f R(hl)=%.9f ACCEPT NEW BEST R=%.9f"
                  % (cycle, rc, rl, bestR))
        else:
            if rl > alt_bestR:
                alt_best, alt_bestR = hl.copy(), rl
            print("cycle %d R(c)=%.9f R(hl)=%.9f no gain (best %.9f)"
                  % (cycle, rc, rl, bestR))

    # ---- Phase 3: peak polish + trailing beta=0 + head/tail again ----
    if time.process_time() < deadline - 2.0:
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pk'
            print("peak polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 1.0:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+all0'
                print("trailing all0 NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 1.0:
        ht3 = _head_tail_polish(best, deadline - 0.5)
        r3 = R_of(ht3)
        if r3 > bestR + 1e-14:
            best, bestR, origin = ht3.copy(), r3, origin + '+ht2'
            print("final head/tail NEW BEST R=%.9f" % bestR)
        elif r3 > alt_bestR:
            alt_best, alt_bestR = ht3.copy(), r3

    print("cycles=%d accepted=%d best_full=%.9f" %
          (cycle, accepted_cycles, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


# ---------- Resampling / upsampling machinery ----------

def _resample(h, N2):
    """Resample step function of length N to length N2 (mass preserving)."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N2 == N:
        return h.copy()
    # cumulative mass at original knots
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(N2)
    # new knot positions in original index units
    x = np.linspace(0.0, N, N2 + 1)
    cm = np.interp(x, np.arange(N + 1), c)
    h2 = np.diff(cm)
    return np.clip(h2, 0, None)


def _upsample_smooth(h, factor):
    """Upsample by linear interpolation of cumulative mass (smooths steps)."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    N2 = int(N * factor)
    if N2 <= N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x = np.linspace(0.0, N, N2 + 1)
    cm = np.interp(x, np.arange(N + 1), c)
    h2 = np.diff(cm)
    return np.clip(h2, 0, None)


def _coarse(h, N2):
    return _resample(h, N2)


# ---------- Main driver ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alternatives = []

    # ---- Strategy A: refine at current resolution in linear space ----
    try:
        cur = best.copy()
        for _ in range(6):
            if time.process_time() >= deadline - 3.0:
                break
            ht = _lbfgs_all_pos(cur, 400, deadline - 3.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                cur = best.copy()
            else:
                cur = ht
            if time.process_time() >= deadline - 3.0:
                break
            ht = _lbfgs_all_pos(cur, 300, deadline - 3.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                cur = best.copy()
            else:
                cur = ht
        print("A refine: R=%.9f" % bestR)
    except Exception as e:
        print("A failed: %s" % e)

    # ---- Strategy B: peak-window ladder at current resolution ----
    try:
        for pad in (0.25, 0.15, 0.10, 0.06, 0.04):
            if time.process_time() >= deadline - 3.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            for beta in (1e7, 0.0):
                if time.process_time() >= deadline - 3.0:
                    break
                ht = _lbfgs_block(best, win, 300, deadline - 3.0, beta=beta)
                r = R_of(ht)
                if r > bestR + 1e-14:
                    best, bestR = ht.copy(), r
        print("B peak: R=%.9f" % bestR)
    except Exception as e:
        print("B failed: %s" % e)

    # ---- Strategy C: upsample and refine (finer resolution search) ----
    # Try a few upsampling factors, keep the best.
    try:
        for factor in (2.0, 1.5, 3.0, 4.0):
            if time.process_time() >= deadline - 3.0:
                break
            if best.size * factor > 400000:
                continue
            hu = _upsample_smooth(best, factor)
            hu = _rescale(hu)
            ru = R_of(hu)
            # refine at fine resolution
            ht = _lbfgs_all_pos(hu, 500, deadline - 3.0, beta=0.0)
            r = R_of(ht)
            if r > ru + 1e-14:
                hu = ht
                ru = r
            if time.process_time() < deadline - 3.0:
                ht = _lbfgs_all_pos(hu, 400, deadline - 3.0, beta=1e7)
                r = R_of(ht)
                if r > ru + 1e-14:
                    hu, ru = ht, r
            if time.process_time() < deadline - 3.0:
                win = _peak_window(hu, pad_frac=0.10, extra=256)
                ht = _lbfgs_block(hu, win, 300, deadline - 3.0, beta=0.0)
                r = R_of(ht)
                if r > ru + 1e-14:
                    hu, ru = ht, r
            print("C up x%.1f: R=%.9f (N=%d)" % (factor, ru, hu.size))
            if ru > bestR + 1e-14:
                best, bestR = hu.copy(), ru
            else:
                # keep as alternative if genuinely different and close
                if ru > start_bestR + 1e-14 and hu.size != start_best.size:
                    alternatives.append((ru, hu.copy()))
    except Exception as e:
        print("C failed: %s" % e)

    # ---- Strategy D: coarse-to-fine: coarse optimize then upsample ----
    try:
        if best.size > 4096 and time.process_time() < deadline - 3.0:
            Nc = max(1024, best.size // 4)
            hc = _coarse(best, Nc)
            hc = _rescale(hc)
            hc = _lbfgs_all_pos(hc, 400, deadline - 3.0, beta=0.0)
            hc = _lbfgs_all_pos(hc, 300, deadline - 3.0, beta=1e7)
            # upsample back
            hu = _upsample_smooth(hc, best.size / float(Nc))
            hu = _rescale(hu)
            ru = R_of(hu)
            if time.process_time() < deadline - 3.0:
                hu = _lbfgs_all_pos(hu, 400, deadline - 3.0, beta=0.0)
                ru = R_of(hu)
            print("D coarse-fine: R=%.9f" % ru)
            if ru > bestR + 1e-14:
                best, bestR = hu.copy(), ru
            elif ru > start_bestR + 1e-14 and hu.size != start_best.size:
                alternatives.append((ru, hu.copy()))
    except Exception as e:
        print("D failed: %s" % e)

    # ---- Final polish on best ----
    try:
        for _ in range(100):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.08, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
    except Exception as e:
        print("polish failed: %s" % e)

    print("final R=%.9f (N=%d, start %.9f)" % (bestR, best.size, start_bestR))

    # Assemble result
    if bestR >= start_bestR - 1e-13:
        if alternatives:
            alternatives.sort(key=lambda x: -x[0])
            alt = alternatives[0][1]
            if alt.size != best.size or not np.allclose(alt, best):
                return {"best": best, "alternative": alt}
        return best
    # best did not beat start; try to return an alternative construction
    if bestR > start_bestR + 1e-14:
        return best
    # pick best alternative if it beats start
    if alternatives:
        alternatives.sort(key=lambda x: -x[0])
        alt = alternatives[0][1]
        if alternatives[0][0] > start_bestR + 1e-14:
            return {"best": alt, "alternative": start_best}
    return start_best

