def _fun_grad_anchor(h, a, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    La = Lf[a]
    if La <= 0:
        return _fun_grad(h)
    excess = Lf - La
    pos = excess > 0
    gLf = -dq / num
    gLf[a] += 1.0 / La
    if mu > 0 and np.any(pos):
        e = excess[pos]
        gLf[pos] += (2.0 * mu / (La * La)) * e
        gLf[a] -= (2.0 * mu / (La * La)) * e.sum()
        pen = mu * np.sum(e * e) / (La * La)
    else:
        pen = 0.0
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(La) + pen
    return val, grad


