        return h0
    n = h.size
    Lf0 = _knots(h)
    a = int(np.argmax(Lf0))

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_anchor(hh, a, mu)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size
    amax0 = _argmax_frac(best)

    # ---- Phase A: front-loaded peak-window beta ladder ----
    a_deadline = t0 + budget_seconds * 0.15
    for pad in (0.06, 0.05, 0.04, 0.03, 0.02):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 250, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.2f' % pad)
        ht2 = _lbfgs_block(best, win, 250, a_deadline - 0.3, beta=0.0)
        offer(ht2, 'A-plain pad=%.2f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase C: fixed-anchor hinge formulation (~40% of budget) ----
    c_deadline = t0 + budget_seconds * 0.55
    anchor_work = best.copy()
    prev_a = int(np.argmax(_knots(anchor_work)))
    for mu in (1e2, 1e4, 1e6, 1e8):
        if time.process_time() >= c_deadline - 0.5:
            break
        ht = _lbfgs_anchor(anchor_work, 120, c_deadline - 0.3, mu)
        a_now = int(np.argmax(_knots(ht)))
        r = R_of(ht)
        print("C mu=%.0e a=%d->%d R=%.9f nearmax5=%.4f"
              % (mu, prev_a, a_now, r, _nearmax_frac(ht)))
        prev_a = a_now
        anchor_work = ht
        offer(ht, 'C-anchor mu=%.0e' % mu)

    # ---- Phase B: random-window block L-BFGS rounds on surviving budget ----
    b_deadline = deadline - 6.0
    rng = np.random.default_rng(12345)
    lo_len = max(8, N // 20)
    hi_len = max(lo_len + 1, N // 6)
    rnd = 0
    while time.process_time() < b_deadline:
        rnd += 1
        L = int(rng.integers(lo_len, hi_len + 1))
        c = int(rng.integers(0, N))
        lo = max(0, c - L // 2)
        hi = min(N, lo + L)
        lo = max(0, hi - L)
        win = np.arange(lo, hi)
        cand = best.copy()
        cand = _lbfgs_block(cand, win, 250, b_deadline, beta=1e6)
        cand = _lbfgs_block(cand, win, 250, b_deadline, beta=0.0)
        cand = _peak_ladder(cand, b_deadline, pads=(0.06, 0.04), iters=200)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("B round=%d center=%.3f len=%d R=%.9f (NEW BEST)"
                  % (rnd, c / N, L, bestR))
        else:
            print("B round=%d center=%.3f len=%d R=%.9f" % (rnd, c / N, L, r))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.98
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend(h, K, rho):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * (rho ** k)
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * (rho ** k)
    return _rescale(h)


def _refine_split(h, jitter):
    n = h.size
    out = np.zeros(2 * n)
    sign = np.where(np.arange(n) % 2 == 0, 1.0, -1.0)
    fac = 1.0 + jitter * sign
    out[0::2] = h * fac
    out[1::2] = h * (2.0 - fac)
    return out


def _peak_ladder(h, deadline, pads=(0.20, 0.12, 0.08, 0.05), iters=300, beta=1e7):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=0.0)
            if R_of(ht2) > R_of(h) + 1e-14:
                h = ht2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            sbest = _rescale(base)
            sR = R_of(sbest)
        else:
            sbest, sR = None, 0.0
    else:
        sbest, sR = None, 0.0

    if sbest is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        sbest = _rescale(h)
        sR = R_of(sbest)

    best = sbest.copy()
    bestR = sR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # === NEW IDEA: doubled-grid high-resolution refinement, kept vs. start ===
    # Split the start into 2x resolution, then run a dedicated schedule. This
    # gives a genuinely finer grid the optimiser can exploit.
    alt = None
    if time.process_time() < deadline - 2.0:
        h2 = _refine_split(sbest, 0.01)
        h2 = _rescale(h2)
        # beta ladder at fine grid
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_all_pos(h2, 250, deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-14:
                h2 = ht
        h2 = _peak_ladder(h2, deadline, pads=(0.20, 0.12, 0.08, 0.05, 0.03), iters=300)
        if time.process_time() < deadline - 1.0:
            ext = _edge_extend(h2, 1024, 0.995)
            if R_of(ext) > R_of(h2) + 1e-14:
                h2 = ext
                h2 = _peak_ladder(h2, deadline, pads=(0.10, 0.06, 0.04), iters=250)
        altR = R_of(h2)
        alt = h2
        print("doubled-grid branch: R=%.9f N=%d" % (altR, h2.size))
        if altR > bestR + 1e-14:
            best, bestR, origin = h2.copy(), altR, "dbl"

    # === Continue from the current best with the usual peak ladder until deadline ===
    work = best.copy()
    curR = bestR
    pads = [0.12, 0.08, 0.06, 0.10, 0.15, 0.20, 0.04, 0.03]
    it = 0
    while time.process_time() < deadline - 0.6:
        pad = pads[it % len(pads)]
        it += 1
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 250, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > curR + 1e-14:
            work, curR = ht, r
            if curR > bestR + 1e-14:
                best, bestR, origin = ht.copy(), curR, "pad%d" % it
        if time.process_time() < deadline - 0.5:
            ht2 = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > curR + 1e-14:
                work, curR = ht2, r2
                if curR > bestR + 1e-14:
                    best, bestR, origin = ht2.copy(), curR, "all0_%d" % it

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, sR, best.size))

    if bestR > sR + 1e-12:
        return {"best": best, "alternative": alt if alt is not None else best}
    if alt is not None:
        return {"best": best, "alternative": alt}
    return best

