    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend(h, K, rho):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * (rho ** k)
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * (rho ** k)
    return _rescale(h)


def _refine_split(h, jitter):
    n = h.size
    out = np.zeros(2 * n)
    sign = np.where(np.arange(n) % 2 == 0, 1.0, -1.0)
    fac = 1.0 + jitter * sign
    out[0::2] = h * fac
    out[1::2] = h * (2.0 - fac)
    return out


def _peak_ladder(h, deadline, pads=(0.20, 0.12, 0.08, 0.05), iters=300, beta=1e7):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=0.0)
            if R_of(ht2) > R_of(h) + 1e-14:
                h = ht2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            sbest = _rescale(base)
            sR = R_of(sbest)
        else:
            sbest, sR = None, 0.0
    else:
        sbest, sR = None, 0.0

    if sbest is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        sbest = _rescale(h)
        sR = R_of(sbest)

    best = sbest.copy()
    bestR = sR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # === NEW IDEA: doubled-grid high-resolution refinement, kept vs. start ===
    # Split the start into 2x resolution, then run a dedicated schedule. This
    # gives a genuinely finer grid the optimiser can exploit.
    alt = None
    if time.process_time() < deadline - 2.0:
        h2 = _refine_split(sbest, 0.01)
        h2 = _rescale(h2)
        # beta ladder at fine grid
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_all_pos(h2, 250, deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-14:
                h2 = ht
        h2 = _peak_ladder(h2, deadline, pads=(0.20, 0.12, 0.08, 0.05, 0.03), iters=300)
        if time.process_time() < deadline - 1.0:
            ext = _edge_extend(h2, 1024, 0.995)
            if R_of(ext) > R_of(h2) + 1e-14:
                h2 = ext
                h2 = _peak_ladder(h2, deadline, pads=(0.10, 0.06, 0.04), iters=250)
        altR = R_of(h2)
        alt = h2
        print("doubled-grid branch: R=%.9f N=%d" % (altR, h2.size))
        if altR > bestR + 1e-14:
            best, bestR, origin = h2.copy(), altR, "dbl"

    # === Continue from the current best with the usual peak ladder until deadline ===
    work = best.copy()
    curR = bestR
    pads = [0.12, 0.08, 0.06, 0.10, 0.15, 0.20, 0.04, 0.03]
    it = 0
    while time.process_time() < deadline - 0.6:
        pad = pads[it % len(pads)]
        it += 1
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 250, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > curR + 1e-14:
            work, curR = ht, r
            if curR > bestR + 1e-14:
                best, bestR, origin = ht.copy(), curR, "pad%d" % it
        if time.process_time() < deadline - 0.5:
            ht2 = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > curR + 1e-14:
                work, curR = ht2, r2
                if curR > bestR + 1e-14:
                    best, bestR, origin = ht2.copy(), curR, "all0_%d" % it

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, sR, best.size))

    if bestR > sR + 1e-12:
        return {"best": best, "alternative": alt if alt is not None else best}
    if alt is not None:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, fg=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, fg=fg)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    near = np.mean(Lf >= 0.99 * mx)
    argm = int(np.argmax(Lf)) / max(1, Lf.size - 1)
    return (100.0 * np.mean(h <= 0), h.max() / max(1e-30, h.mean()),
            near, argm)


def _env(h, theta1, theta2):
    n = h.size
    u = (np.arange(n) + 0.5) / n
    x = 2.0 * u - 1.0
    e = np.exp(theta1 * x + theta2 * (x * x - 1.0 / 3.0))
    return _rescale(h * e)


def _decimate(h, factor):
    """Downsample by averaging blocks of `factor` (keeps mass)."""
    n = h.size
    m = n // factor
    if m < 8:
        return h
    hh = h[:m * factor].reshape(m, factor).sum(axis=1)
    return _rescale(hh)


def _upsample(h, factor):
    """Upsample by repeating each sample `factor` times (keeps mass)."""
    n = h.size
    hu = np.repeat(h, factor) / factor
    return _rescale(hu)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (baseR, base.size, 100.0 * np.mean(base <= 0)))

    best = base.copy()
    bestR = baseR

    def stage(hcur, Rcur, label):
        nonlocal best, bestR
        if Rcur > bestR + 1e-13:
            best = hcur.copy(); bestR = Rcur
        z, mm, nm, am = _stats(hcur)
        print("%s R=%.8f N=%d zeros %.1f%% max/mean %.2f near %.4f argmax %.3f" %
              (label, Rcur, hcur.size, z, mm, nm, am))

    # Stage A: 1-D scan of theta1
    thetas = np.linspace(-0.6, 0.6, 13)
    scan = []
    a_deadline = min(deadline, time.process_time() + 3.0)
    best_t1, best_Ra = 0.0, baseR
    best_ha = base.copy()
    for t1 in thetas:
        if time.process_time() > a_deadline:
            break
        ha = _env(base, t1, 0.0)
        Ra = R_of(ha)
        scan.append((t1, Ra))
        if Ra > best_Ra:
            best_Ra, best_t1, best_ha = Ra, t1, ha
    print("scan theta1: " + " ".join("%.2f:%.7f" % (t, r) for t, r in scan))

    # Stage B: Nelder-Mead on (theta1, theta2)
    b_deadline = min(deadline, time.process_time() + 8.0)
    evals = [0]

    def obj(x):
        evals[0] += 1
        if time.process_time() > b_deadline:
            raise TimeoutError
        return -R_of(_env(base, x[0], x[1]))

    x0 = np.array([best_t1, 0.0])
    try:
        res = minimize(obj, x0, method='Nelder-Mead',
                       options={'maxfev': 80, 'xatol': 1e-4, 'fatol': 1e-9})
        th1, th2 = res.x
    except (TimeoutError, Exception):
        th1, th2 = best_t1, 0.0
    h_env_best = _env(base, th1, th2)
    R_env = R_of(h_env_best)
    print("env final theta1=%.4f theta2=%.4f R=%.8f (gain %.2e)" %
          (th1, th2, R_env, R_env - baseR))

    if R_env > bestR:
        best = h_env_best.copy(); bestR = R_env
    stage(best, bestR, "env")

    h = best.copy()
    R = bestR

    if time.process_time() < deadline - 6.0:
        h2 = _lbfgs_log(h, 200, min(deadline, time.process_time() + 6.0))
        R2 = R_of(h2)
        if R2 > R:
            h, R = h2, R2
        stage(h, R, "lbfgs")

    for beta in (1e3, 1e4):
        if time.process_time() >= deadline - 4.0:
            break
        fg = (lambda hh, _b=beta: _fun_grad_beta(hh, _b))
        hb = _lbfgs_log(h, 60, min(deadline, time.process_time() + 3.0), fg=fg)
        Rb = R_of(hb)
        if Rb > R:
            h, R = hb, Rb
        stage(h, R, "beta%.0e" % beta)

    for frac in (0.08, 0.15):
        if time.process_time() >= deadline - 3.0:
            break
        hw = _window_polish_peak(h, min(deadline, time.process_time() + 3.0),
                                 frac, 32, maxiter=120)
        Rw = R_of(hw)
        if Rw > R:
            h, R = hw, Rw
        stage(h, R, "win%.2f" % frac)

    # NEW: resolution-change (decimate / upsample) refinement to escape N-locked local optima.
    # Try coarsening the current best, optimizing at low N (cheaper, more global), then
    # upsampling back and re-polishing. Repeat while time remains.
    def try_resolution(hcur, Rcur, factor, label):
        nonlocal best, bestR
        if time.process_time() >= deadline - 3.0:
            return hcur, Rcur
        hd = _decimate(hcur, factor)
        if hd.size == hcur.size:
            return hcur, Rcur
        Rd = R_of(hd)
        hd2 = _lbfgs_log(hd, 300, min(deadline, time.process_time() + 4.0))
        Rd2 = R_of(hd2)
        if Rd2 <= Rd:
            hd2, Rd2 = hd, Rd
        hu = _upsample(hd2, factor)
        if hu.size != hcur.size:
            # align sizes: pad or trim by re-decimating then re-upsampling to original n
            n_target = hcur.size
            m = hd2.size
            idx = np.linspace(0, m, n_target + 1)
            lo = np.floor(idx[:-1]).astype(int)
            frac_ = idx[:-1] - lo
            lo = np.clip(lo, 0, m - 1)
            hi = np.clip(lo + 1, 0, m - 1)
            hu = ((1 - frac_) * hd2[lo] + frac_ * hd2[hi])
            hu = _rescale(hu)
        Ru = R_of(hu)
        if Ru > Rcur:
            # re-polish at original resolution
            hu2 = _lbfgs_log(hu, 200, min(deadline, time.process_time() + 3.0))
            Ru2 = R_of(hu2)
            if Ru2 > Ru:
                hu, Ru = hu2, Ru2
        stage(hu, Ru, label)
        if Ru > Rcur:
            return hu, Ru
        return hcur, Rcur

    # Try a few decimation factors (2, 3, 4) to explore different resolutions
    for factor in (2, 3, 4):
        if time.process_time() >= deadline - 5.0:
            break
        h, R = try_resolution(h, R, factor, "res%d" % factor)

    # Alternate exact log-L-BFGS while time remains
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        hp = _lbfgs_log(h, 200, min(deadline, time.process_time() + 3.0))
        Rp = R_of(hp)
        if Rp > R:
            h, R = hp, Rp
        stage(h, R, "polish%d" % it)
        if time.process_time() >= deadline - 2.0:
            break
        for frac in (0.08, 0.15):
            if time.process_time() >= deadline - 1.5:
                break
            hw = _window_polish_peak(h, min(deadline, time.process_time() + 2.0),
                                     frac, 32, maxiter=100)
            Rw = R_of(hw)
            if Rw > R:
                h, R = hw, Rw
            stage(h, R, "pol%d-win%.2f" % (it, frac))

    print("final R=%.8f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _conv2(a, b):
    if a.size > 1500 or b.size > 1500:
        return fftconvolve(a, b)
    return np.convolve(a, b)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pin(h, a):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    a = int(a)
    if a < 0:
        a = 0
    if a >= Lf.size:
        a = Lf.size - 1
    La = Lf[a]
    if La <= 0:
        La = 1e-300
    gLf = -dq / num
    gLf[a] += 1.0 / La
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(La)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_pin(h0, a, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_pin(hh, a)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


