    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.12, 0.07, 0.04, 0.02), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=64)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _refine(h, factor, deadline, iters=300):
    if factor <= 1:
        return h
    n = h.size
    xi = np.linspace(0, n, n * factor, endpoint=False)
    hi = np.interp(xi, np.arange(n), h)
    hi = _rescale(hi)
    return _lbfgs_all(hi, iters, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_end = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        cur = np.ones(512)
        cur = _lbfgs_all(cur, 800, hard_end)
        return cur

    alternative = None
    alt_r = -1.0

    def _consider(cand):
        nonlocal best, best_r, alternative, alt_r
        r = R_of(cand)
        if r > best_r:
            best = cand.copy(); best_r = r
        elif r > alt_r:
            alternative = cand.copy(); alt_r = r

    # Stage A: high-beta smoothing polish of start (tight peak smoothing)
    h = start_arr.copy()
    for beta in (1e7, 1e6, 1e5, 1e4, 1e3):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _lbfgs_all(h, 250, hard_end, beta=beta)
        if R_of(c) >= R_of(h) - 1e-12:
            h = c
    c = _lbfgs_all(h, 500, hard_end)
    if R_of(c) >= R_of(h):
        h = c
    _consider(h)
    print("A R=%.6f N=%d" % (best_r, h.size))

    # Stage B: peak-ladder focused polishing (tighter windows than baseline)
    for _ in range(3):
        if time.process_time() >= hard_end - 0.8:
            break
        c = _peak_ladder(best.copy(), hard_end)
        _consider(c)
    print("B R=%.6f N=%d" % (best_r, best.size))

    # Stage C: refine by upsampling to a bigger N (more degrees of freedom)
    cur = best.copy()
    for factor in (2, 2):
        if time.process_time() >= hard_end - 1.0:
            break
        if cur.size * factor > 1000000:
            break
        c = _refine(cur, factor, hard_end, iters=400)
        c = _peak_ladder(c, hard_end)
        c = _lbfgs_all(c, 400, hard_end)
        _consider(c)
        if R_of(c) >= R_of(cur) - 1e-12:
            cur = c
        print("C R=%.6f N=%d" % (best_r, best.size))

    # Stage D: final fine polishing loop on the best
    while time.process_time() < hard_end - 0.8:
        h = best.copy()
        c = _peak_ladder(h, hard_end,
                         pads=(0.10, 0.06, 0.03, 0.015, 0.007), iters=350)
        c = _lbfgs_all(c, 400, hard_end)
        r = R_of(c)
        if r > best_r + 1e-13:
            _consider(c)
        else:
            break
    print("D R=%.6f N=%d" % (best_r, best.size))

    if start_arr is not None and R_of(start_arr) > best_r:
        best = start_arr.copy(); best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None and alt_r > -1:
        return {"best": best, "alternative": alternative}
    return best

