def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _refine_peak(best, bestR, deadline, max_rounds=200):
    pads = [0.15, 0.10, 0.07, 0.05, 0.035, 0.025, 0.018, 0.012]
    rnd = 0
    while time.process_time() < deadline - 0.6 and rnd < max_rounds:
        pad = pads[rnd % len(pads)]
        rnd += 1
        win = _peak_window(best, pad_frac=pad, extra=96)
        if win.size < 4:
            break
        h1 = _lbfgs_block(best, win, 300, deadline - 0.4, beta=1e7)
        r1 = R_of(h1)
        if r1 > bestR + 1e-15:
            best, bestR = h1, r1
        if time.process_time() < deadline - 0.5:
            h2 = _lbfgs_all_pos(best, 250, deadline - 0.4, beta=0.0)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2, r2
    return best, bestR


def _subwindow_heat(best, deadline, n_probe=24):
    """Local curvature probe: how much does R improve if we free a small
    sub-window near the peak and optimize it alone?  Returns the single
    window that most improves R (an escape direction), or None."""
    n = best.size
    Lf = _knots(best)
    m = int(np.argmax(Lf))
    span = max(8, int(0.12 * n))
    lo0 = max(0, m - span)
    hi0 = min(n - 1, m + span)
    if hi0 - lo0 < 8:
        return None
    best_gain = -1.0
    best_h = None
    width = max(16, (hi0 - lo0) // n_probe)
    for k in range(n_probe):
        if time.process_time() >= deadline - 0.5:
            break
        lo = lo0 + (hi0 - lo0 - width) * k // max(1, n_probe - 1)
        hi = min(hi0, lo + width)
        win = np.arange(lo, hi + 1)
        h1 = _lbfgs_block(best, win, 60, deadline - 0.3, beta=0.0)
        r1 = R_of(h1)
        if r1 > best_gain:
            best_gain = r1
            best_h = h1
    if best_h is not None and best_gain > R_of(best) + 1e-14:
        return best_h
    return None


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    alt_best, alt_bestR = None, -1.0
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase 1: a quick sub-window curvature probe to find an "escape"
    # direction -- a small local move that raises R.  This breaks out of
    # the extremely flat local maximum the previous program got stuck in.
    if time.process_time() < deadline - 2.0:
        hprobe = _subwindow_heat(best, deadline - budget_seconds * 0.30)
        if hprobe is not None:
            rp = R_of(hprobe)
            if rp > bestR + 1e-15:
                best, bestR = hprobe, rp
                print("subwindow probe NEW BEST R=%.9f" % bestR)
            elif rp > alt_bestR:
                alt_best, alt_bestR = hprobe.copy(), rp

    # Phase 2: focused peak-window refinement
    hpk, rpk = _refine_peak(best, bestR, deadline - 0.3)
    if rpk > bestR + 1e-15:
        best, bestR = hpk, rpk
        print("peak refine NEW BEST R=%.9f" % bestR)
    elif rpk > alt_bestR:
        alt_best, alt_bestR = hpk.copy(), rpk

    # Phase 3: final tight full-domain polish
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("final beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR > start_bestR and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth_peak_ladder(h, deadline, betas=(2e5, 5e5, 1e6, 3e6, 1e7, 0.0),
                        iters=400):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def _peak_polish(h, deadline, pads=(0.30, 0.18, 0.10, 0.06, 0.035), iters=500):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        for beta in (3e6, 1e7, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
    return h


def _asym_split(h, sigma, rng):
    n = h.size
    w0 = np.exp(sigma * rng.standard_normal(n))
    w1 = np.exp(sigma * rng.standard_normal(n))
    m = 0.5 * (w0 + w1)
    w0 /= m
    w1 /= m
    h2 = np.empty(2 * n)
    h2[0::2] = h * w0
    h2[1::2] = h * w1
    return _rescale(h2)


def _fold_mean(h2):
    return _rescale(0.5 * (h2[0::2] + h2[1::2]))


def _quotient(h, pairing):
    n = h.size
    m = (n + 1) // 2
    if pairing == 'even':
        c = h[0::2].copy()
    elif pairing == 'odd':
        c = h[1::2].copy()
    else:  # avg
        ev = h[0::2]
        od = h[1::2]
        if od.size < ev.size:
            od = np.concatenate((od, [0.0]))
        c = 0.5 * (ev + od)
    return _rescale(c)


def _lift(c, N, rotate):
    m = c.size
    h2 = np.empty(N)
    if not rotate:
        h2[0::2] = c[:len(h2[0::2])]
        h2[1::2] = c[:len(h2[1::2])]
    else:
        cs = np.concatenate(([c[-1]], c[:-1]))
        h2[0::2] = cs[:len(h2[0::2])]
        h2[1::2] = c[:len(h2[1::2])]
    return _rescale(h2)


def _polish_half(c, deadline):
    for beta, it in ((1e5, 200), (1e6, 200), (1e7, 200), (0.0, 300)):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(c, it, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(c) + 1e-15:
            c = ht
    return c


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        h = np.ones(1024)
        h = _lbfgs_all_pos(h, 800, deadline - 1.0, beta=0.0)
        h = _smooth_peak_ladder(h, deadline - 0.5)
        return h

    cur = start_arr.copy()
    cur_r = best_r

    # Baseline refinement from the base program.
    cur = _smooth_peak_ladder(cur, deadline - 3.0)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("smooth R=%.8f" % best_r)

    cur = _peak_polish(cur, deadline - 1.5)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("peak   R=%.8f" % best_r)

    # ---- Quotient phase: ~40% of budget ----
    q_deadline = t0 + 0.40 * budget_seconds
    N = best.size
    best_quot_r = -1.0
    best_quot_info = None
    for pairing in ('even', 'odd', 'avg'):
        if time.process_time() >= q_deadline - 1.0:
            break
        c_in = _quotient(best, pairing)
        r_in = R_of(c_in)
        c = _polish_half(c_in, q_deadline - 0.5)
        r_c = R_of(c)
        print("quot %s: R_in=%.8f R_c=%.8f" % (pairing, r_in, r_c))
        if r_c > best_quot_r:
            best_quot_r = r_c
            best_quot_info = (pairing, c.copy(), r_in)
        # lift back both orientations, repair, accept if better
        for rotate in (False, True):
            if time.process_time() >= q_deadline - 0.5:
                break
            h2 = _lift(c, N, rotate)
            h2 = _smooth_peak_ladder(h2, q_deadline - 0.3)
            h2 = _peak_polish(h2, q_deadline - 0.2, pads=(0.10, 0.06, 0.035),
                              iters=300)
            r2 = R_of(h2)
            print("  lift %s rot=%s R=%.8f" % (pairing, rotate, r2))
            if r2 > best_r + 1e-15:
                best, best_r = h2.copy(), r2
                print("NEW BEST(quot %s rot=%s) R=%.8f" % (pairing, rotate, best_r))

    if best_quot_info is not None:
        print("best quotient: %s R=%.8f (in %.8f)"
              % (best_quot_info[0], best_quot_r, best_quot_info[2]))

    # ---- Asymmetric 2N split rounds with remaining budget ----
    rng = np.random.default_rng(987654321)
    round_no = 0
    while time.process_time() < deadline - 12.0:
        round_no += 1
        h2 = _asym_split(best, sigma=0.5, rng=rng)
        h2 = _lbfgs_all_pos(h2, 120, deadline - 8.0, beta=0.0)
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 8.0:
                break
            ht = _lbfgs_all_pos(h2, 120, deadline - 8.0, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-15:
                h2 = ht
        for pad in (0.12, 0.08, 0.05):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(h2, pad_frac=pad, extra=128)
            for beta in (1e6, 1e7, 0.0):
                if time.process_time() >= deadline - 8.0:
                    break
                ht = _lbfgs_block(h2, win, 120, deadline - 8.0, beta=beta)
                if R_of(ht) > R_of(h2) + 1e-15:
                    h2 = ht
        r2 = R_of(h2)
        hf = _fold_mean(h2)
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 8.0:
                break
            ht = _lbfgs_all_pos(hf, 120, deadline - 8.0, beta=beta)
            if R_of(ht) > R_of(hf) + 1e-15:
                hf = ht
        for pad in (0.08, 0.05):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(hf, pad_frac=pad, extra=128)
            for beta in (1e6, 1e7, 0.0):
                if time.process_time() >= deadline - 8.0:
                    break
                ht = _lbfgs_block(hf, win, 120, deadline - 8.0, beta=beta)
                if R_of(ht) > R_of(hf) + 1e-15:
                    hf = ht
        rf = R_of(hf)
        if rf > best_r + 1e-15:
            best, best_r = hf.copy(), rf
            print("NEW BEST R=%.8f (2N R=%.8f, round %d)" % (best_r, r2, round_no))
        elif r2 > best_r + 1e-15:
            hc = _quotient(h2, 'avg')
            hc = _lift(hc, N, False)
            rc = R_of(hc)
            if rc > best_r + 1e-15:
                best, best_r = hc, rc
                print("NEW BEST(coarse) R=%.8f" % best_r)

    # Final sharp ladder + small peak polish.
    if time.process_time() < deadline - 0.5:
        for beta in (1e8, 1e9, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 0.3, beta=beta)
            if R_of(ht) > best_r + 1e-15:
                best, best_r = ht, R_of(ht)
                print("final  R=%.8f" % best_r)
    if time.process_time() < deadline - 0.5:
        cand = _peak_polish(best, deadline - 0.3, pads=(0.05, 0.03), iters=300)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
            print("polish R=%.8f" % best_r)

    if start_arr is not None and R_of(start_arr) >= best_r:
        if cur.shape == start_arr.shape and not np.allclose(cur, start_arr, rtol=0, atol=0):
            return {"best": start_arr, "alternative": cur}
        return start_arr

    if start_arr is not None and not np.allclose(best, start_arr, rtol=0, atol=0):
        return {"best": best, "alternative": start_arr}

    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _upsample(h, factor):
    """Refine grid by integer factor via linear interpolation."""
    if factor <= 1:
        return h.copy()
    n = h.size
    xi = np.linspace(0, n - 1, (n - 1) * factor + 1)
    return np.interp(xi, np.arange(n), h)


def _downsample(h, factor):
    """Coarsen grid by integer factor via averaging blocks."""
    if factor <= 1:
        return h.copy()
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        if cand.size > 1000000:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f N=%d (%s)" % (bestR, best.size, tag))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase U: upsample the start onto a finer grid, then polish ----
    # This is the key new idea: the current best sits at N~105k, so we
    # refine onto a 2x grid (N~210k) and re-optimise.  If that fails to
    # help, try 4x on a coarser parent.
    N0 = best.size
    print("parent N=%d R=%.9f" % (N0, bestR))

    refined = None
    refinedR = -1.0

    if time.process_time() < deadline - 15.0:
        up = _rescale(_upsample(best, 2))
        up = _polish_ladder(up, deadline - 10.0,
                            betas=(1e5, 1e6, 1e7, 0.0), iters=250)
        up = _peak_ladder(up, deadline - 8.0,
                          pads=(0.20, 0.12, 0.08, 0.05), iters=250)
        ru = R_of(up)
        print("upsample2: N=%d R=%.9f" % (up.size, ru))
        offer(up, 'up2')
        if ru > refinedR:
            refined, refinedR = up.copy(), ru

    # ---- Phase V: if 2x refinement worked, try 4x refinement ----
    if refined is not None and time.process_time() < deadline - 10.0:
        up4 = _rescale(_upsample(refined, 2))
        up4 = _polish_ladder(up4, deadline - 6.0,
                             betas=(1e5, 1e6, 1e7, 0.0), iters=200)
        up4 = _peak_ladder(up4, deadline - 4.0,
                           pads=(0.20, 0.12, 0.08, 0.05), iters=200)
        r4 = R_of(up4)
        print("upsample4: N=%d R=%.9f" % (up4.size, r4))
        offer(up4, 'up4')

    # ---- Phase W: try downsampling the start and re-polishing, to escape
    # a local optimum in a different resolution ----
    if time.process_time() < deadline - 12.0:
        for fac in (2, 3):
            if time.process_time() >= deadline - 10.0:
                break
            dn = _rescale(_downsample(best, fac))
            dn = _polish_ladder(dn, deadline - 6.0,
                                betas=(1e5, 1e6, 1e7, 0.0), iters=250)
            rn = R_of(dn)
            print("downsample%d: N=%d R=%.9f" % (fac, dn.size, rn))
            offer(dn, 'down%d' % fac)

    # ---- Final polish on best ----
    if time.process_time() < deadline - 2.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e7, 1e8, 1e9, 0.0), iters=300)
        offer(ht, 'finalhi')
    if time.process_time() < deadline - 1.0:
        ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=250)
        offer(ht2, 'finalpeak')

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


# ---- NEW: multi-scale resampling of the shape ----

def _resample(h, N2):
    """Resample step function h to N2 equal-mass bins (via cumulative mass)."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0 or h.size == 0:
        return np.zeros(N2)
    cum = np.concatenate(([0.0], np.cumsum(h) / s))
    targets = np.linspace(0.0, 1.0, N2 + 1)
    # value of h at each target position (piecewise constant)
    idx = np.clip(np.searchsorted(cum, targets, side='left') - 1, 0, h.size - 1)
    vals = h[idx]
    return vals


def _resample_linear(h, N2):
    """Resample via linear interpolation of cumulative at uniform positions."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n == 0:
        return np.zeros(N2)
    xs = (np.arange(n) + 0.5) / n
    xs2 = (np.arange(N2) + 0.5) / N2
    return np.interp(xs2, xs, h, left=0.0, right=0.0)


def _polish(h, deadline, iters_glob=350, iters_beta=250, iters_peak=200):
    best = _rescale(np.clip(h, 0, None))
    bestR = R_of(best)
    if time.process_time() >= deadline - 0.3:
        return best, bestR
    ht = _lbfgs_all_pos(_seed_zeros(best), iters_glob, deadline - 0.3, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-13:
        best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.3:
        ht = _lbfgs_all_pos(best, iters_beta, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    for frac, extra in ((0.15, 64), (0.30, 128)):
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, iters_peak, deadline=deadline - 0.3,
                          beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.3:
        ht = _lbfgs_all_pos(best, iters_glob, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _refine_cycle(best, bestR, deadline):
    """Global + peak ladder, similar to the original run_cycle."""
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.25, 128, 1e8), (0.40, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(1234567)

    start_best = None
    start_bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n0 = best.size

    # NEW IDEA: multi-scale resampling. The optimum has a self-similar comb
    # structure; resampling to different N and polishing lets the optimizer
    # re-arrange the fine structure, escaping the local basin of the current N.
    alt_cand = None
    altR = -1.0

    # Build candidate N values around n0
    scales = []
    for f in (0.5, 0.75, 1.25, 1.5, 2.0, 3.0):
        n2 = int(round(n0 * f))
        if 16 <= n2 <= 900000:
            scales.append(n2)
    # also small fixed sizes to escape to a coarser grid
    for n2 in (2048, 4096, 8192, 16384):
        if n2 not in scales and 16 <= n2 <= 900000:
            scales.append(n2)
    rng.shuffle(scales)

    # Time-slice for the resample experiment
    nv = len(scales) + 1  # +1 for a direct refine of base
    t_now = time.process_time()
    total = max(0.0, deadline - t_now - 3.0)
    per = total / max(1, nv)

    results = []
    for n2 in scales:
        if time.process_time() >= deadline - 3.0:
            break
        sub_deadline = min(deadline - 1.0, time.process_time() + per)
        try:
            hv = _resample(best, n2)
            hv2 = _resample_linear(best, n2)
            for tag, seed in (('cum', hv), ('lin', hv2)):
                if time.process_time() >= sub_deadline - 0.2:
                    break
                hb, rb = _polish(seed, min(sub_deadline, deadline - 1.0),
                                 iters_glob=250, iters_beta=150,
                                 iters_peak=120)
                results.append((rb, hb))
                print("resample N=%d %s: R=%.7f (delta %.3e)" %
                      (n2, tag, rb, rb - bestR))
        except Exception as e:
            print("resample N=%d failed: %s" % (n2, e))

    if results:
        results.sort(key=lambda t: -t[0])
        rb, hb = results[0]
        if rb > bestR + 1e-13:
            alt_cand, altR = hb.copy(), rb
            best, bestR = hb.copy(), rb
            print("resample wins: R=%.7f (was %.7f)" % (bestR, start_bestR))
        else:
            alt_cand, altR = hb.copy(), rb
            print("resample did not beat base: %.7f vs %.7f" % (rb, bestR))

    # Now polish the current best with full machinery
