import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


# ---- NEW: multi-scale resampling of the shape ----

def _resample(h, N2):
    """Resample step function h to N2 equal-mass bins (via cumulative mass)."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0 or h.size == 0:
        return np.zeros(N2)
    cum = np.concatenate(([0.0], np.cumsum(h) / s))
    targets = np.linspace(0.0, 1.0, N2 + 1)
    # value of h at each target position (piecewise constant)
    idx = np.clip(np.searchsorted(cum, targets, side='left') - 1, 0, h.size - 1)
    vals = h[idx]
    return vals


def _resample_linear(h, N2):
    """Resample via linear interpolation of cumulative at uniform positions."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n == 0:
        return np.zeros(N2)
    xs = (np.arange(n) + 0.5) / n
    xs2 = (np.arange(N2) + 0.5) / N2
    return np.interp(xs2, xs, h, left=0.0, right=0.0)


def _polish(h, deadline, iters_glob=350, iters_beta=250, iters_peak=200):
    best = _rescale(np.clip(h, 0, None))
    bestR = R_of(best)
    if time.process_time() >= deadline - 0.3:
        return best, bestR
    ht = _lbfgs_all_pos(_seed_zeros(best), iters_glob, deadline - 0.3, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-13:
        best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.3:
        ht = _lbfgs_all_pos(best, iters_beta, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    for frac, extra in ((0.15, 64), (0.30, 128)):
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, iters_peak, deadline=deadline - 0.3,
                          beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.3:
        ht = _lbfgs_all_pos(best, iters_glob, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _refine_cycle(best, bestR, deadline):
    """Global + peak ladder, similar to the original run_cycle."""
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.25, 128, 1e8), (0.40, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(1234567)

    start_best = None
    start_bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n0 = best.size

    # NEW IDEA: multi-scale resampling. The optimum has a self-similar comb
    # structure; resampling to different N and polishing lets the optimizer
    # re-arrange the fine structure, escaping the local basin of the current N.
    alt_cand = None
    altR = -1.0

    # Build candidate N values around n0
    scales = []
    for f in (0.5, 0.75, 1.25, 1.5, 2.0, 3.0):
        n2 = int(round(n0 * f))
        if 16 <= n2 <= 900000:
            scales.append(n2)
    # also small fixed sizes to escape to a coarser grid
    for n2 in (2048, 4096, 8192, 16384):
        if n2 not in scales and 16 <= n2 <= 900000:
            scales.append(n2)
    rng.shuffle(scales)

    # Time-slice for the resample experiment
    nv = len(scales) + 1  # +1 for a direct refine of base
    t_now = time.process_time()
    total = max(0.0, deadline - t_now - 3.0)
    per = total / max(1, nv)

    results = []
    for n2 in scales:
        if time.process_time() >= deadline - 3.0:
            break
        sub_deadline = min(deadline - 1.0, time.process_time() + per)
        try:
            hv = _resample(best, n2)
            hv2 = _resample_linear(best, n2)
            for tag, seed in (('cum', hv), ('lin', hv2)):
                if time.process_time() >= sub_deadline - 0.2:
                    break
                hb, rb = _polish(seed, min(sub_deadline, deadline - 1.0),
                                 iters_glob=250, iters_beta=150,
                                 iters_peak=120)
                results.append((rb, hb))
                print("resample N=%d %s: R=%.7f (delta %.3e)" %
                      (n2, tag, rb, rb - bestR))
        except Exception as e:
            print("resample N=%d failed: %s" % (n2, e))

    if results:
        results.sort(key=lambda t: -t[0])
        rb, hb = results[0]
        if rb > bestR + 1e-13:
            alt_cand, altR = hb.copy(), rb
            best, bestR = hb.copy(), rb
            print("resample wins: R=%.7f (was %.7f)" % (bestR, start_bestR))
        else:
            alt_cand, altR = hb.copy(), rb
            print("resample did not beat base: %.7f vs %.7f" % (rb, bestR))

    # Now polish the current best with full machinery
    if time.process_time() < deadline - 2.0:
        best, bestR = _refine_cycle(best, bestR, deadline - 2.0)
        print("refine cycle R=%.7f" % bestR)

    # Final short polish
    if time.process_time() < deadline - 0.5:
        hb, rb = _polish(best, deadline - 0.5, iters_glob=200,
                         iters_beta=150, iters_peak=100)
        if rb > bestR + 1e-13:
            best, bestR = hb, rb
        print("final polish R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR >= start_bestR - 1e-13:
        if alt_cand is not None and altR > -1.0:
            return {"best": best, "alternative": alt_cand}
        return best
    else:
        if alt_cand is not None and altR > -1.0:
            return {"best": start_best, "alternative": alt_cand}
        return start_best

