    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _refine(h, factor, deadline, iters=300):
    if factor <= 1:
        return h
    n = h.size
    xi = np.linspace(0, n, n * factor, endpoint=False)
    hi = np.interp(xi, np.arange(n), h)
    hi = _rescale(hi)
    win = np.arange(hi.size)
    ht = _lbfgs_block(hi, win, iters, deadline - 0.3, beta=1e7)
    if R_of(ht) > R_of(h) + 1e-14:
        h = ht
    else:
        h = hi
    ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=0.0)
    return ht


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _nearmax_frac_tol(h, tol=0.001):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _avg_argmax_frac(h, w):
    Lf = _knots(h)
    w = int(max(1, w))
    if w <= 1 or w >= Lf.size:
        return _argmax_frac(h)
    av = np.convolve(Lf, np.ones(w) / w, mode='valid')
    j = int(np.argmax(av))
    return j / max(1, Lf.size - 1)


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size
    amax0 = _argmax_frac(best)

    # ---- Phase A: front-loaded peak-window beta ladder ----
    a_deadline = t0 + budget_seconds * 0.10
    for pad in (0.06, 0.04, 0.025):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.3f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase W: plateau-level window-averaged max, annealed w ----
    w_deadline = t0 + budget_seconds * 0.40
    nm0 = _nearmax_frac_tol(best, 0.001)
    for w in (8, 4, 2, 1):
        if time.process_time() >= w_deadline - 1.0:
            break
        R_before = bestR
        ht = _lbfgs_avg(best, 300, w_deadline - 0.5, w)
        jfrac = _avg_argmax_frac(ht, w)
        ht = _peak_ladder(ht, w_deadline - 0.4, pads=(0.05, 0.03), iters=200)
        r = R_of(ht)
        nm = _nearmax_frac_tol(ht, 0.001)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            tag = "ACCEPT"
        else:
            tag = "reject"
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("W w=%d j*/N=%.4f R=%.9f delta=%.3e nearmax0.1=%.4f %s"
              % (w, jfrac, r, r - R_before, nm, tag))
    print("Phase W done R=%.9f nearmax0.1=%.4f (was %.4f)"
          % (bestR, _nearmax_frac_tol(best, 0.001), nm0))

    # ---- Phase T: exact Clarke subgradient of log(max) over tied knots ----
    t_deadline = t0 + budget_seconds * 0.62
    for tau in (1e-12, 1e-10, 1e-8, 1e-6, 1e-4):
        if time.process_time() >= t_deadline - 1.0:
            break
        R_before = bestR
        ht, K = _lbfgs_tie(best, 300, t_deadline - 5.0, tau)
        win = _peak_window(ht, pad_frac=0.04, extra=128)
        ht = _lbfgs_block(ht, win, 250, t_deadline - 4.0, beta=0.0)
        ht = _peak_ladder(ht, t_deadline - 3.0, pads=(0.05, 0.03), iters=200)
        r = R_of(ht)
        accepted = False
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            accepted = True
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("T tau=%.0e K=%d R=%.9f delta=%.3e %s"
              % (tau, K, r, r - R_before, "ACCEPT" if accepted else "reject"))
    print("Phase T done R=%.9f N=%d" % (bestR, best.size))

    # ---- Phase B: random-window block L-BFGS rounds ----
    b_deadline = deadline - 5.0
    rng = np.random.default_rng(987654321)
    Ncur = best.size
    lo_len = max(8, Ncur // 25)
    hi_len = max(lo_len + 1, Ncur // 8)
    rnd = 0
    while time.process_time() < b_deadline:
        rnd += 1
        Ncur = best.size
        L = int(rng.integers(lo_len, hi_len + 1))
        c = int(rng.integers(0, Ncur))
        lo = max(0, c - L // 2)
        hi = min(Ncur, lo + L)
        lo = max(0, hi - L)
        win = np.arange(lo, hi)
        cand = _lbfgs_block(best, win, 250, b_deadline, beta=1e6)
        cand = _lbfgs_block(cand, win, 250, b_deadline, beta=0.0)
        cand = _peak_ladder(cand, b_deadline, pads=(0.05, 0.03), iters=200)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("B round=%d c=%.3f L=%d R=%.9f (NEW BEST)"
                  % (rnd, c / Ncur, L, bestR))
        else:
            print("B round=%d c=%.3f L=%d R=%.9f" % (rnd, c / Ncur, L, r))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.98
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- resample (change N) ----

def _resample(h, n_new):
    n = h.size
    if n_new == n:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(n_new) + 0.5) / n_new
    out = np.interp(x_new, x_old, h, left=0.0, right=0.0)
    return np.clip(out, 0, None)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(999)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: refine start.
    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("refine R=%.7f" % bestR)

    # Phase 2: N-growth search — resample to larger N and re-optimize.
    # This is the main new idea: increase resolution progressively.
    n_cur = best.size
    trial_Ns = []
    for mult in [1.15, 1.3, 1.5, 1.75, 2.0]:
        trial_Ns.append(int(n_cur * mult))
    trial_Ns.append(200000)
    trial_Ns.append(400000)
    trial_Ns = [n for n in trial_Ns if n <= 1000000 and n > best.size]

    for n_new in trial_Ns:
        if time.process_time() >= deadline - 2.0:
            break
        h_r = _resample(best, n_new)
        h_r = _rescale(h_r)
        r = R_of(h_r)
        if r < bestR - 0.02:
            # resample too lossy — try smaller step
            continue
        # optimize on new grid but with limited iters
        sub_deadline = min(deadline - 1.5, time.process_time() + 8.0)
        ht = _lbfgs_all_pos(h_r, 400, sub_deadline, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            print("grow N=%d R=%.7f" % (n_new, bestR))
        else:
            print("grow N=%d failed (%.7f vs %.7f)" % (n_new, r, bestR))

    # Phase 3: full run_cycle at current N.
    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("cycle R=%.7f N=%d" % (bestR, best.size))

    # Phase 4: alternating resample-up + polish loop.
    while time.process_time() < deadline - 2.5:
        n_cur = best.size
        n_targets = [int(n_cur * 1.08), int(n_cur * 1.15), min(1000000, int(n_cur * 1.25))]
        n_targets = [n for n in n_targets if n > n_cur and n <= 1000000]
        if not n_targets:
            break
        n_new = n_targets[int(rng.integers(0, len(n_targets)))]
        h_r = _resample(best, n_new)
        h_r = _rescale(h_r)
        sub_deadline = min(deadline - 1.5, time.process_time() + 6.0)
        ht = _lbfgs_all_pos(h_r, 300, sub_deadline, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            # follow with full cycle if time
            if time.process_time() < deadline - 4.0:
                best, bestR = run_cycle(best, bestR, deadline - 2.0)
            print("grow-loop N=%d R=%.7f" % (best.size, bestR))
        else:
            break

    # Phase 5: final polish at fixed N.
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

