def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _refine(h, factor, deadline, iters=300):
    if factor <= 1:
        return h
    n = h.size
    xi = np.linspace(0, n, n * factor, endpoint=False)
    hi = np.interp(xi, np.arange(n), h)
    hi = _rescale(hi)
    win = np.arange(hi.size)
    ht = _lbfgs_block(hi, win, iters, deadline - 0.3, beta=1e7)
    if R_of(ht) > R_of(h) + 1e-14:
        h = ht
    else:
        h = hi
    ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=0.0)
    return ht


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size
    amax0 = _argmax_frac(best)

    # ---- Phase A: front-loaded peak-window beta ladder ----
    a_deadline = t0 + budget_seconds * 0.10
    for pad in (0.06, 0.04, 0.025):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.3f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase Q: pinned-tie L-BFGS with annealed tolerance ----
    q_deadline = t0 + budget_seconds * 0.60
    for tol in (0.05, 0.02, 0.01, 0.005, 0.002):
        if time.process_time() >= q_deadline - 1.0:
            break
        R_before = bestR
        Lf = _knots(best)
        mx = Lf.max()
        if mx <= 0:
            continue
        idx = np.flatnonzero(Lf >= mx * (1.0 - tol))
        if idx.size > 200:
            order = np.argsort(Lf[idx])[::-1][:200]
            idx = np.sort(idx[order])
        if idx.size == 0:
            idx = np.array([int(np.argmax(Lf))])
        ht = _lbfgs_pin(best, idx, 150, q_deadline - 0.5)
        ht = _lbfgs_block(ht, _peak_window(ht, pad_frac=0.04, extra=128),
                          250, q_deadline - 0.3, beta=0.0)
        r = R_of(ht)
        accepted = False
        if r > bestR + 1e-12:
            best, bestR = ht.copy(), r
            accepted = True
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("Q tol=%.4f idx=%d R=%.9f delta=%.3e %s"
              % (tol, idx.size, r, r - R_before, "ACCEPT" if accepted else "reject"))
    print("Phase Q done R=%.9f N=%d" % (bestR, best.size))

    # ---- Phase B: random-window block L-BFGS rounds ----
    b_deadline = deadline - 5.0
    rng = np.random.default_rng(987654321)
    Ncur = best.size
    lo_len = max(8, Ncur // 25)
    hi_len = max(lo_len + 1, Ncur // 8)
    rnd = 0
    while time.process_time() < b_deadline:
        rnd += 1
        Ncur = best.size
        L = int(rng.integers(lo_len, hi_len + 1))
        c = int(rng.integers(0, Ncur))
        lo = max(0, c - L // 2)
        hi = min(Ncur, lo + L)
        lo = max(0, hi - L)
        win = np.arange(lo, hi)
        cand = _lbfgs_block(best, win, 250, b_deadline, beta=1e6)
        cand = _lbfgs_block(cand, win, 250, b_deadline, beta=0.0)
        cand = _peak_ladder(cand, b_deadline, pads=(0.05, 0.03), iters=200)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("B round=%d c=%.3f L=%d R=%.9f (NEW BEST)"
                  % (rnd, c / Ncur, L, bestR))
        else:
            print("B round=%d c=%.3f L=%d R=%.9f" % (rnd, c / Ncur, L, r))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.98
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad
    if free is None:
        active = None
        x0 = h.copy()
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0
        x0 = h[active].copy()

    def f(x):
        if active is None:
            hh = np.clip(x, 0.0, None)
        else:
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return (val, g if active is None else g[active])

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    hh = h.copy()
    if active is None:
        hh = np.clip(res.x, 0.0, None)
    else:
        hh[active] = np.clip(res.x, 0.0, None)
    return _rescale(hh)


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _compact_support(h):
    # shift so support starts at 0, trim trailing zeros
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    h = h[nz[0]:nz[-1] + 1]
    return h


def _find_peak_center(h):
    L = _knots(h)
    return int(np.argmax(L))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    best = None
    bestR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.sum() > 0:
            best = s
            bestR = R_of(s)
            print("start R=%.6f N=%d" % (bestR, len(s)))

    # Strategy: the optimum is a sparse, peaked shape. Polish at current
    # resolution with the analytic L-BFGS on the log objective, then refine.
    if best is None:
        # build a simple peaked seed
        N0 = 2000
        h = np.zeros(N0)
        h[N0 // 4: N0 // 4 + 50] = 1.0
        best = _rescale(h)
        bestR = R_of(best)

    # Work on a compacted copy, then re-expand.
    leader = _compact_support(best.copy())
    # normalize length into a reasonable working size
    N = len(leader)
    if N < 512:
        leader = _prolongate(leader, 512)
        N = 512

    # Iterative resolution refinement: optimize, then prolongate and optimize.
    levels = []
    n = N
    while n < 200000:
        levels.append(n)
        n = int(n * 1.6) + 1
    levels.append(min(200000, max(n, N)))

    cur = leader
    for N in levels:
        if time.process_time() > deadline - 1.0:
            break
        cur = _rescale(_prolongate(cur, N))
        # beta-smoothing pass then sharp pass
        for beta in (8.0, 20.0, 0.0):
            if time.process_time() > deadline - 1.0:
                break
            cur = _lbfgs(cur, 300, deadline, beta=beta)
        Rc = R_of(cur)
        if Rc > bestR:
            # store at compact support
            cand = _compact_support(cur)
            Rcc = R_of(cand)
            if Rcc >= Rc - 1e-9:
                best = cand
                bestR = Rcc
            else:
                best = cur
                bestR = Rc
        print("level N=%d R=%.6f best=%.6f" % (N, Rc, bestR))

    # Final polish: iterate peak-localized free coordinates.
    cur = best.copy()
    if time.process_time() < deadline - 1.0:
        L = _knots(cur)
        peak = int(np.argmax(L))
        center = peak // 2
        n = len(cur)
        w = max(8, int(0.15 * n))
        lo = max(0, center - w)
        hi = min(n, center + w)
        free = np.arange(lo, hi)
        for beta in (0.0, 5.0, 0.0):
            if time.process_time() > deadline - 1.0:
                break
            cur = _lbfgs(cur, 400, deadline, beta=beta, free=free)
            Rc = R_of(cur)
            if Rc > bestR:
                best = _compact_support(cur)
                bestR = R_of(best)
        print("final polish R=%.6f" % bestR)

    # one more global sharpen if time remains
    if time.process_time() < deadline - 1.0:
        cur = _lbfgs(best, 500, deadline, beta=0.0)
        Rc = R_of(cur)
        if Rc > bestR:
            best = _compact_support(cur)
            bestR = R_of(best)

    print("final R=%.6f N=%d" % (bestR, len(best)))
    if best is None:
        return np.ones(50)
    return best

