    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---- NEW: refine at higher resolution.  Upsample the current best by an
# integer factor k via linear interpolation, then run a short L-BFGS pass
# to let the finer grid capture more detail near the (flat) maximum of f*f.

def _upsample(h, k):
    n = h.size
    x = np.arange(n)
    xn = np.linspace(0, n - 1, (n - 1) * k + 1)
    return np.interp(xn, x, h)


def _refine_resolution(h, k, deadline, iters=300):
    if time.process_time() >= deadline - 1.0:
        return h
    hu = _upsample(h, k)
    hu = _rescale(np.clip(hu, 0, None))
    # plain polish on the finer grid
    ht = _lbfgs_all_pos(hu, iters, deadline - 0.5, beta=0.0)
    if R_of(ht) > R_of(h) + 1e-14:
        return ht
    return h


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and (alt_best is None or cand.size == alt_best.size):
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size
    amax0 = _argmax_frac(best)

    # ---- Phase A: peak-window beta ladder (polish the current shape) ----
    a_deadline = t0 + budget_seconds * 0.20
    for pad in (0.05, 0.04, 0.03, 0.02, 0.015, 0.01):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.3f' % pad)
        ht2 = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=0.0)
        offer(ht2, 'A-plain pad=%.3f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f nearmax5=%.4f"
          % (bestR, _argmax_frac(best), _nearmax_frac(best)))

    # ---- Phase R: resolution refinement ladder (NEW) ----
    # Upsample by increasing factors, polish on finer grid, keep improvements.
    r_deadline = t0 + budget_seconds * 0.55
    for k in (2, 3, 4, 6, 8):
        if time.process_time() >= r_deadline - 1.0:
            break
        if best.size * k > 900000:
            break
        hk = _refine_resolution(best, k, r_deadline, iters=250)
        offer(hk, 'R-refine k=%d' % k)
        if best.size * k <= 900000:
            # also run a peak-window pass at the new resolution
            win = _peak_window(best, pad_frac=0.02, extra=128)
            ht = _lbfgs_block(best, win, 200, r_deadline - 0.3, beta=1e7)
            offer(ht, 'R-peak k=%d' % k)
    print("Phase R done R=%.9f N=%d" % (bestR, best.size))

    # ---- Phase B: random-window block L-BFGS rounds ----
    b_deadline = deadline - 3.0
    rng = np.random.default_rng(13579)
    N = best.size
    lo_len = max(8, N // 20)
    hi_len = max(lo_len + 1, N // 6)
    rnd = 0
    while time.process_time() < b_deadline:
        rnd += 1
        L = int(rng.integers(lo_len, hi_len + 1))
        c = int(rng.integers(0, N))
        lo = max(0, c - L // 2)
        hi = min(N, lo + L)
        lo = max(0, hi - L)
        win = np.arange(lo, hi)
        cand = best.copy()
        if rnd % 2 == 0:
            cand = _lbfgs_block(cand, win, 250, b_deadline, beta=1e6)
        else:
            cand = _lbfgs_block(cand, win, 250, b_deadline, beta=0.0)
        cand = _peak_ladder(cand, b_deadline, pads=(0.06, 0.04), iters=200)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("B round=%d center=%.3f len=%d R=%.9f (NEW BEST)"
                  % (rnd, c / N, L, bestR))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.98
    # try one more resolution bump if budget allows
    if best.size < 400000 and time.process_time() < final_deadline - 5.0:
        hk = _refine_resolution(best, 2, final_deadline - 1.0, iters=200)
        offer(hk, 'final-refine')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h, tau):
    """Soft tie-breaking: spread the max-weight across all near-max knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size), 0
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        v, g = _fun_grad(h)
        return v, g, 0
    idx = np.flatnonzero(Lf >= mx * (1.0 - tau))
    K = idx.size
    if K == 0:
        idx = np.array([int(np.argmax(Lf))]); K = 1
    gLf = -dq / num
    gLf[idx] += 1.0 / (K * Lf[idx])
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad, K


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_tie(h0, maxiter, deadline, tau):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g, _ = _fun_grad_tie(hh, tau)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tau=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = lambda hh: _fun_grad_beta(hh, beta)
    elif tau > 0:
        fg = lambda hh: _fun_grad_tie(hh, tau)[:2]
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0, tau=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline,
                        beta=beta, tau=tau)


def _perturb_window_at(h, lo, hi, rng, sigma=0.30):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo)); hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]; c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _refine(h, hard_end, use_tie=True):
    """Refinement: beta-continuation, then tie-aware, then exact, then window polish."""
    for beta in (400.0, 150.0, 60.0, 25.0, 10.0):
        if time.process_time() >= hard_end - 0.4:
            break
        c = _lbfgs_all_pos(h, maxiter=200, deadline=hard_end, beta=beta)
        if R_of(c) >= R_of(h):
            h = c
    if use_tie:
        for tau in (1e-2, 3e-3, 1e-3, 3e-4, 1e-4):
            if time.process_time() >= hard_end - 0.4:
                break
            c = _lbfgs_tie(h, maxiter=300, deadline=hard_end, tau=tau)
            if R_of(c) >= R_of(h):
                h = c
    if time.process_time() < hard_end - 0.4:
        c = _lbfgs_all_pos(h, maxiter=400, deadline=hard_end, beta=0.0)
        if R_of(c) >= R_of(h):
            h = c
    for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2)):
        if time.process_time() >= hard_end - 0.4:
            break
        c = _window_polish_peak(h, hard_end, frac, extra, maxiter=300)
        if R_of(c) >= R_of(h):
            h = c
    return h


def _coarsen(h, factor):
    n = h.size
    m = n // factor
    if m < 4:
        return h
    trim = h[:m * factor].reshape(m, factor).mean(axis=1)
    return _rescale(trim)


def _upsample(h, newn):
    n = h.size
    xo = (np.arange(n) + 0.5) / n
    xn = (np.arange(newn) + 0.5) / newn
    return _rescale(np.interp(xn, xo, h))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0
    hard_end = deadline - 0.3

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _refine(cur, hard_end)
        return cur

    best = start_arr.copy()
    best_r = R_of(best)
    alternative = None
    alt_r = -1.0

    def _consider(cand):
        nonlocal best, best_r, alternative, alt_r
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r
        return r

    n = best.size

    # Phase 1: strong refinement of start with the improved (tie-aware) pipeline.
    # This is the main new idea: tie-breaking across near-max knots escapes the
    # plateau where a single-argmax gradient stalls.
    c = _refine(best, min(hard_end, time.process_time() + 18.0))
    _consider(c)
    print("phase1 R=%.6f" % best_r)

    # Phase 2: resolution change - upsample then re-refine, since a finer
    # discretisation can represent a smoother peak that scores marginally higher.
    if time.process_time() < hard_end - 6.0 and n < 500000:
        for fac in (2, 3):
            if time.process_time() >= hard_end - 5.0:
                break
            newn = min(1000000, n * fac)
            if newn == n:
                continue
            up = _upsample(best, newn)
            up = _lbfgs_all_pos(up, maxiter=200, deadline=hard_end, beta=30.0)
            cu = _refine(up, min(hard_end, time.process_time() + 8.0))
            _consider(cu)
            # downsample back to compare at same N is optional; keep as candidate
            if R_of(cu) > best_r:
                # also try coarsening to reduce noise
                for cf in (2,):
                    if cu.size % cf == 0:
                        cc = _coarsen(cu, cf)
                        cc = _lbfgs_all_pos(cc, maxiter=200, deadline=hard_end)
                        _consider(cc)

    # Phase 3: seeded perturbations around peak region, refined with tie-aware pipeline.
    n_seeds = 16
    for seed in range(n_seeds):
        if time.process_time() >= hard_end - 2.0:
            break
        rng_s = np.random.default_rng(9000 + seed)
        Lf = _knots(best)
        m = int(np.argmax(Lf))
        if seed % 3 == 0:
            lo = max(0, m - n // 3); hi = min(n, m + n // 3)
        elif seed % 3 == 1:
            lo = max(0, m - n // 5); hi = min(n, m + n // 5)
        else:
            lo = int(rng_s.uniform(0.0, 0.5) * n)
            hi = min(n, lo + int(rng_s.uniform(0.3, 0.6) * n))
        sigma = float(rng_s.uniform(0.08, 0.30))
        h = _perturb_window_at(best, lo, hi, rng_s, sigma=sigma)
        h = _lbfgs_all_pos(h, maxiter=150, deadline=hard_end, beta=200.0)
        c = _refine(h, hard_end, use_tie=True)
        _consider(c)
    print("phase3 R=%.6f N=%d" % (best_r, best.size))

    # Phase 4: keep polishing until time runs out.
    try:
        while time.process_time() < hard_end - 1.0:
            before = best_r
            c = _refine(best, hard_end, use_tie=True)
            _consider(c)
            if best_r <= before + 1e-10:
                break
    except Exception:
        pass

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    print("final R=%.6f" % best_r)
    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h, tau):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size), 0
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        v, g = _fun_grad(h)
        return v, g, 0
    idx = np.flatnonzero(Lf >= mx * (1.0 - tau))
    K = idx.size
    if K == 0:
        idx = np.array([int(np.argmax(Lf))])
        K = 1
    gLf = -dq / num
    gLf[idx] += 1.0 / (K * Lf[idx])
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad, K


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_tie(h0, maxiter, deadline, tau):
    if time.process_time() >= deadline - 0.3:
        return h0, 0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, 0
    n = h.size
    Kbox = [0]

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g, K = _fun_grad_tie(hh, tau)
        Kbox[0] = K
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0, Kbox[0]
    if res is None:
        return h0, Kbox[0]
    return _rescale(np.clip(res.x, 0.0, None)), Kbox[0]


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _smooth_perturb(h, rng, scale=0.05):
    """Warp the abscissa slightly (monotone) to explore nearby basin."""
    n = h.size
    if n < 32:
        return h
    x = np.arange(n, dtype=float) / n
    k = max(2, n // 200)
    # random smooth displacement via low-freq sinusoids
    disp = np.zeros(n)
    for _ in range(3):
        freq = rng.uniform(1.0, 4.0)
        phase = rng.uniform(0, 2 * np.pi)
        amp = rng.uniform(0.0, scale) * n
        disp += amp * np.sin(2 * np.pi * freq * x + phase)
    xs = np.clip(x + disp / n, 0.0, 1.0)
    xs = np.sort(xs)
    src = np.linspace(0, 1, n)
    return np.interp(src, xs, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.12f (N=%d, zeros %.1f%%) near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Phase 1: softmax (beta) full polish to spread the max ----
    betas = (0, 200, 800, 3000)
    for beta in betas:
        if time.process_time() >= deadline - 2.0:
            break
        cap = min(deadline - 0.5, time.process_time() + 4.0)
        hs = _lbfgs_all_pos(bestH, 200, cap, beta=beta)
        rs = R_of(hs)
        if rs > bestRH + 1e-14:
            bestH, bestRH = hs.copy(), rs
            print("beta=%d full: R=%.12f" % (beta, bestRH))

    # ---- Phase 2: tie-aware polish (equalize top knots) ----
    for tau in (1e-4, 1e-3, 3e-3):
        if time.process_time() >= deadline - 2.0:
            break
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        hs, K = _lbfgs_tie(bestH, 150, cap, tau)
        rs = R_of(hs)
        if rs > bestRH + 1e-14:
            bestH, bestRH = hs.copy(), rs
            print("tie tau=%.0e (K=%d): R=%.12f" % (tau, K, bestRH))

    # ---- Phase 3: peak block polish + perturb-and-refine loop ----
    round_ = 0
    while time.process_time() < deadline - 1.5:
        round_ += 1

        for frac in (0.02, 0.04, 0.08, 0.15):
            if time.process_time() >= deadline - 1.5:
                break
            free = _peak_window(bestH, frac=frac)
            cap = min(deadline - 0.5, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 80, cap)
            rp = R_of(hp)
            if rp > bestRH + 1e-14:
                bestH, bestRH = hp.copy(), rp
                print("r%d peak frac=%.2f: R=%.12f" % (round_, frac, bestRH))

        # perturbed restart to escape local basin
        if time.process_time() < deadline - 4.0:
            scale = 0.02 + 0.06 * rng.random()
            hw = _smooth_perturb(bestH, rng, scale=scale)
            cap = min(deadline - 1.0, time.process_time() + 3.0)
            hw = _lbfgs_all_pos(hw, 120, cap, beta=0.0)
            rw = R_of(hw)
            if rw > bestRH + 1e-14:
                bestH, bestRH = hw.copy(), rw
                print("r%d perturb(%.3f): R=%.12f" % (round_, scale, bestRH))
            # keep exploring from bestH always (don't drift)

    mx, m, near = _stats(bestH)
    print("final R=%.12f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))
    print("gain vs start: %.3e" % (bestRH - start_bestR))

    if bestRH > start_bestR + 1e-13:
        return {"best": bestH, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h, tau):
    """Softmax over near-tied peak knots: spreads the max constraint so the
    optimizer can lift a plateau of peaks together instead of one knot."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size), 0
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        v, g = _fun_grad(h)
        return v, g, 0
    idx = np.flatnonzero(Lf >= mx * (1.0 - tau))
    K = idx.size
    if K == 0:
        idx = np.array([int(np.argmax(Lf))])
        K = 1
    gLf = -dq / num
    gLf[idx] += 1.0 / (K * Lf[idx])
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad, K


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_tie(h0, maxiter, deadline, tau):
    if time.process_time() >= deadline - 0.3:
        return h0, 0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, 0
    n = h.size
    Kbox = [0]

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g, K = _fun_grad_tie(hh, tau)
        Kbox[0] = K
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0, Kbox[0]
    if res is None:
        return h0, Kbox[0]
    return _rescale(np.clip(res.x, 0.0, None)), Kbox[0]


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _spline_eval(c, N):
    K = c.size
    u = (np.arange(N, dtype=float) + 0.5) / N * (K - 1)
    i0 = np.floor(u).astype(int)
    i0 = np.clip(i0, 0, K - 2)
    w = u - i0
    lc = (1.0 - w) * c[i0] + w * c[i0 + 1]
    return np.exp(np.clip(lc, -30.0, 30.0)), i0, w


def _spline_init(h, K):
    N = h.size
    lh = np.log(np.clip(h, 1e-9, None))
    u = (np.arange(N, dtype=float) + 0.5) / N * (K - 1)
    i0 = np.floor(u).astype(int)
    i0 = np.clip(i0, 0, K - 2)
    w = u - i0
    c = np.zeros(K); cnt = np.zeros(K)
    np.add.at(c, i0, (1.0 - w) * lh)
    np.add.at(c, i0 + 1, w * lh)
    np.add.at(cnt, i0, 1.0 - w)
    np.add.at(cnt, i0 + 1, w)
    return c / np.clip(cnt, 1e-9, None)


def _spline_fit(h0, K, maxiter, deadline):
    N = h0.size
    c0 = _spline_init(h0, K)
    if time.process_time() >= deadline - 0.3:
        return h0

    def f(c):
        h, i0, w = _spline_eval(c, N)
        val, g = _fun_grad(h)
        gc = np.zeros(K)
        gw = g * h
        np.add.at(gc, i0, gw * (1.0 - w))
        np.add.at(gc, i0 + 1, gw * w)
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c0, jac=True, method='L-BFGS-B',
                       bounds=[(-25.0, 25.0)] * K, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h, _, _ = _spline_eval(np.clip(res.x, -25.0, 25.0), N)
    return _rescale(h)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0, 0
    return mx, h.mean(), int(np.sum(Lf > 0.99 * mx)), int(np.sum(Lf > 0.95 * mx))


def _polish(h, deadline):
    best = h; bestR = R_of(h)
    for frac in [0.02, 0.05, 0.10]:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, beta=0.0)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 3.0)
        hp = _lbfgs_log(best, 200, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base); bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h); bestR = R_of(h)

    start_best = best.copy(); start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size
    Ks = [129, 257, 513, 1025, 2049, 4097, 8193, 16385]

    cand = best.copy(); candR = bestR

    # NEW: tie-aware full-resolution refinement. The peak of f*f is very flat
    # (18% of knots within 0.1% of max), so single-argmax gradient wastes effort.
    # Lift the whole near-max plateau together via softmax over tied knots,
    # then sharpen tau. This directly attacks the ||f*f||_inf term.
    if time.process_time() < deadline - 3.0:
        ht = best.copy()
        for tau in [1e-2, 5e-3, 2e-3, 1e-3, 5e-4, 2e-4, 1e-4]:
            if time.process_time() >= deadline - 2.0:
                break
            cap = min(deadline - 1.5, time.process_time() + 4.0)
            ht, K = _lbfgs_tie(ht, 300, cap, tau)
            rt = R_of(ht)
            print("  tie tau=%.1e K=%d R=%.9f" % (tau, K, rt))
            if rt > candR:
                cand, candR = ht, rt

    round_i = 0
    while time.process_time() < deadline - 2.0:
        round_i += 1
        for K in Ks:
            if time.process_time() >= deadline - 2.0:
                break
            cap = min(deadline - 1.0, time.process_time() + 6.0)
            hK = _spline_fit(cand, K, 250, cap)
            rK = R_of(hK)
            mx, mean, n1, n5 = _stats(hK)
            flag = "BEAT" if rK > start_bestR + 1e-13 else "    "
            print("  [K%d] R=%.9f mx/mean=%.3f n1%%=%d n5%%=%d %s" %
                  (K, rK, mx / max(mean, 1e-12), n1, n5, flag))
            if rK > candR:
                cand, candR = hK, rK
        if time.process_time() < deadline - 1.0:
            hp, rp = _polish(cand, deadline)
            if rp > candR + 1e-15:
                cand, candR = hp, rp
                print("    polish R=%.9f" % candR)
        if candR > bestR + 1e-15:
            best, bestR = cand.copy(), candR
            print("  round=%d new best R=%.9f" % (round_i, bestR))
        if time.process_time() < deadline - 2.0:
            K = 2049
            c = _spline_init(cand, K)
            c = c + np.random.randn(K) * 0.02
            hpert, _, _ = _spline_eval(c, N)
            hpert = _rescale(hpert)
            rpert = R_of(hpert)
            if rpert > candR:
                cand, candR = hpert, rpert
        if round_i > 6:
            break

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": cand if candR > start_bestR else start_best}
    else:
        return {"best": start_best, "alternative": cand}

import numpy as np
import time
import math
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * np.max(L)
    if den <= 0 or not np.isfinite(num):
        return -1.0
    return num / den


def _R_fast(h):
    """R using fftconvolve for large arrays."""
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = fftconvolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * np.max(L)
    if den <= 0 or not np.isfinite(num):
        return -1.0
    return num / den


def _build_cascade(p, r, L, scales):
    a = np.exp(p[:r])
    h = np.array([1.0])
    for l in range(L):
        h = np.kron(h, a)
        if scales is not None:
            h = h * np.exp(scales[l])
    return h


def _cascade_obj(p, r, L, use_scales):
    if use_scales:
        logs = p[:r]
        scales = p[r:]
    else:
        logs = p
        scales = None
    a = np.exp(np.clip(logs, -20, 5))
    h = np.array([1.0])
    for l in range(L):
        h = np.kron(h, a)
        if scales is not None:
            h = h * np.exp(np.clip(scales[l], -1.5, 1.5))
    if h.size > 300000:
        return 1.0
    return -_R_fast(h)


def _lbfgs_all_pos(h0, budget_end, maxiter=100):
    """Per-cell L-BFGS on -log R via log-parametrization, bounded."""
    n = h0.size
    x0 = np.log(np.clip(h0, 1e-12, None))

    def obj(x):
        if time.process_time() > budget_end:
            raise TimeoutError
        h = np.exp(np.clip(x, -30, 10))
        return -_R_fast(h)

    try:
        res = minimize(obj, x0, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'ftol': 1e-12, 'gtol': 1e-10})
        h = np.exp(np.clip(res.x, -30, 10))
        return h, _R_fast(h)
    except (TimeoutError, Exception):
        return h0, _R_fast(h0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    cascade_deadline = t0 + budget_seconds * 0.35

    # Analytic sqrt-ramp incumbent
    N0 = 8192
    x = np.linspace(0, 1, N0)
    incumbent = np.sqrt(np.clip(1.0 - (2*x - 1)**2, 0, None)) + 1e-6
    best_R = _R_fast(incumbent)
    best_h = incumbent.copy()
    print(f"sqrt-ramp R={best_R:.6f}")

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.size <= 1000000 and np.all(np.isfinite(s)) and s.sum() > 0:
            r_s = _R_fast(s)
            if r_s > best_R:
                best_R = r_s
                best_h = s.copy()
                print(f"start R={best_R:.6f}")

    # Phase (a,b): cascade optimization
    rng = np.random.RandomState(12345)
    for r in (2, 3):
        L = 0
        while r**(L+1) <= 200000:
            L += 1
        if L < 2:
            continue
        use_scales = True
        n_p = r + (L if use_scales else 0)

        for trial in range(6):
            if time.process_time() > cascade_deadline:
                break
            p0 = rng.uniform(-6.9, 0, r)
            if use_scales:
                p0 = np.concatenate([p0, np.zeros(L)])
            try:
                res = minimize(_cascade_obj, p0, args=(r, L, use_scales),
                               method='Nelder-Mead',
                               options={'maxiter': 3000, 'fatol': 1e-12, 'xatol': 1e-8})
                Rv = -res.fun
                if Rv > best_R:
                    logs = res.x[:r]
                    if use_scales:
                        sc = np.clip(res.x[r:], -1.5, 1.5)
                    else:
                        sc = None
                    h = _build_cascade(np.clip(logs, -20, 5), r, L, sc)
                    if h.size <= 1000000 and np.all(np.isfinite(h)) and h.sum() > 0:
                        best_R = Rv
                        best_h = h.copy()
                        print(f"cascade r={r} L={L} trial={trial} R={best_R:.6f} N={h.size}")
            except Exception:
                pass

    # Phase (c): prolongate + jitter + L-BFGS
    h = best_h
    if h.size < 100000 and h.size * 2 <= 1000000:
        n = h.size
        xo = np.linspace(0, 1, n)
        xn = np.linspace(0, 1, 2*n)
        h = np.interp(xn, xo, h)
        h = np.clip(h, 0, None)
        Rv = _R_fast(h)
        if Rv > best_R:
            best_R = Rv
            best_h = h.copy()
        print(f"prolongated R={best_R:.6f} N={h.size}")

    ladder = [1e5, 1e7, 0]
    stage_end = t0 + budget_seconds * 0.90
    for rnd in range(4):
        if time.process_time() > stage_end:
            break
        h = best_h.copy()
        n = h.size
        mask = rng.rand(n) < 0.05
        h[mask] *= np.exp(rng.normal(0, 0.05, mask.sum()))
        h = np.clip(h, 1e-12, None)
        for b in ladder:
            if time.process_time() > stage_end:
                break
            if b == 0:
                h2, R2 = _lbfgs_all_pos(h, stage_end, maxiter=200)
            else:
                h2, R2 = _lbfgs_all_pos(h, stage_end, maxiter=50)
            if R2 > best_R:
                best_R = R2
                best_h = h2.copy()
            h = h2
        print(f"round {rnd} R={best_R:.6f} N={best_h.size}")

    # Final polish
    if time.process_time() < deadline:
        h2, R2 = _lbfgs_all_pos(best_h, deadline, maxiter=300)
        if R2 > best_R:
            best_R = R2
            best_h = h2.copy()

    h = np.clip(best_h, 0, None)
    if h.sum() <= 0:
        h = np.ones(50)
    zf = np.mean(h == 0)
    mm = h.max() / (h.mean() + 1e-30)
    print(f"FINAL R={_R_fast(h):.6f} N={h.size} zero_frac={zf:.3f} max/mean={mm:.2f}")
    return h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h, tau):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size), 0
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        v, g = _fun_grad(h)
        return v, g, 0
    idx = np.flatnonzero(Lf >= mx * (1.0 - tau))
    K = idx.size
    if K == 0:
        idx = np.array([int(np.argmax(Lf))])
        K = 1
    gLf = -dq / num
    gLf[idx] += 1.0 / (K * Lf[idx])
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad, K


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_tie(h0, maxiter, deadline, tau):
    if time.process_time() >= deadline - 0.3:
        return h0, 0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, 0
    n = h.size
    Kbox = [0]

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g, K = _fun_grad_tie(hh, tau)
        Kbox[0] = K
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0, Kbox[0]
    if res is None:
        return h0, Kbox[0]
    return _rescale(np.clip(res.x, 0.0, None)), Kbox[0]


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_blockgain(h0, B, maxiter, deadline):
    """Reparametrise by B contiguous block log-gains: h_i -> h_i*exp(x_b).
    Optimise x with L-BFGS-B using the exact chain-rule gradient."""
    if time.process_time() >= deadline - 0.3:
        return h0, np.zeros(B)
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, np.zeros(B)
    n = h.size
    B = max(1, min(B, n))
    block_id = np.zeros(n, dtype=int)
    for b, idx in enumerate(np.array_split(np.arange(n), B)):
        block_id[idx] = b
    x0 = np.zeros(B)

    def f(x):
        xc = np.clip(x, -4.0, 4.0)
        hh = h * np.exp(xc[block_id])
        val, g = _fun_grad(hh)
        gx = np.zeros(B)
        hg = hh * g
        np.add.at(gx, block_id, hg)
        return val, gx

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-4.0, 4.0)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0, x0
    if res is None:
        return h0, x0
    xc = np.clip(res.x, -4.0, 4.0)
    hh = h * np.exp(xc[block_id])
    return _rescale(np.clip(hh, 0.0, None)), xc


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    amax0 = _argmax_frac(best)

    # ---- Phase A: front-loaded peak-window beta ladder ----
    a_deadline = t0 + budget_seconds * 0.10
    for pad in (0.06, 0.04, 0.025):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.3f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase G: coherent block-gain moves (coarse -> fine) ----
    g_deadline = t0 + budget_seconds * 0.80
    for B in (64, 128, 256, 512, 1024):
        if time.process_time() >= g_deadline - 6.0:
            print("G B=%d skipped (time)" % B)
            break
        R_before = bestR
        cand, x = _lbfgs_blockgain(best, B, 300, g_deadline - 5.0)
        dl = g_deadline - 1.0
        cand = _lbfgs_all_pos(cand, 300, dl, beta=1e7)
        cand = _lbfgs_all_pos(cand, 400, dl, beta=0.0)
        r = R_of(cand)
        maxx = float(np.max(np.abs(x))) if x.size else 0.0
        big = int(np.sum(np.abs(x) > 1e-3)) if x.size else 0
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("G B=%d R=%.9f dR=%.3e maxx=%.2e big=%d ACCEPT"
                  % (B, bestR, r - R_before, maxx, big))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = cand.copy(), r
            print("G B=%d R=%.9f dR=%.3e maxx=%.2e big=%d reject"
                  % (B, r, r - R_before, maxx, big))
    print("Phase G done R=%.9f N=%d" % (bestR, best.size))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.97
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _upsample_lift(c, factor=2):
    """Interlace c with linear interpolation to a finer grid."""
    n = c.size
    N = factor * n
    h = np.zeros(N)
    h[0::factor] = c
    for k in range(1, factor):
        w = k / factor
        h[k::factor] = (1.0 - w) * c + w * np.roll(c, -1)
    return _rescale(h)


def _polish(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    ht = h
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, iters, deadline - 0.3, beta=beta)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    start_best = None
    start_bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(h, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        h = _rescale(np.clip(h, 0, None))
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR, origin = h.copy(), r, tag
            print("%s NEW BEST R=%.9f" % (tag, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r
        return r

    # ---- Phase 1: peak-focused polish of the start ----
    if time.process_time() < deadline - 3.0:
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 500, deadline - 0.5, beta=1e7)
        consider(ht, 'start_pk')
        if time.process_time() < deadline - 2.0:
            ht = _polish(best, deadline, betas=(1e6, 1e7), iters=250)
            consider(ht, 'start_polish')

    # ---- Phase 2: upsample-lift-refine loop (the new idea) ----
    # Repeatedly lift to 2x resolution, polish at high resolution, then
    # downsample back and re-polish. This escapes discretisation local optima.
    if time.process_time() < deadline - 5.0:
        work = best.copy()
        for cycle in range(4):
            if time.process_time() >= deadline - 4.0:
                break
            slice_end = min(deadline - 2.0,
                            time.process_time() + 0.18 * budget_seconds)
            # lift
            h2 = _upsample_lift(work, 2)
            r0 = R_of(h2)
            # high-res polish
            ht = _polish(h2, slice_end, betas=(1e6, 1e7, 0.0), iters=250)
            # peak polish at fine resolution
            if time.process_time() < slice_end - 0.5:
                win = _peak_window(ht, pad_frac=0.08, extra=128)
                ht2 = _lbfgs_block(ht, win, 400, slice_end - 0.3, beta=1e7)
                if R_of(ht2) > R_of(ht):
                    ht = ht2
            r_hi = R_of(ht)
            consider(ht, 'lift2x_c%d' % cycle)
            # downsample by averaging pairs
            n2 = ht.size // 2
            hd = _rescale(0.5 * (ht[0:2 * n2:2] + ht[1:2 * n2:2]))
            if time.process_time() < slice_end - 0.5:
                hd = _polish(hd, slice_end, betas=(1e7, 0.0), iters=250)
            r_d = R_of(hd)
            consider(hd, 'down_c%d' % cycle)
            if r_d >= r_hi - 1e-12:
                work = hd
            else:
                work = ht
            if time.process_time() >= deadline - 4.0:
                break

    # ---- Phase 3: peak-window polish on best ----
    if time.process_time() < deadline - 2.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            consider(ht2, 'pk%.2f' % pad)

    # ---- Phase 4: gentle all-pos polish on best ----
    if time.process_time() < deadline - 1.0:
        ht = _polish(best, deadline, betas=(1e7, 0.0), iters=300)
        consider(ht, 'final_polish')

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()

    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---------------- New idea: shrink (coarsen) the step function ----------------
# The optimum is a fixed shape; a coarser representation with the same shape
# can be polished more cheaply per step and lets L-BFGS move mass more
# freely (fewer local constraints). We downsample by mass-conservation and
# re-optimise, keeping the result if R holds up or improves.

def _coarsen(h, factor):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if factor <= 1 or n < 2 * factor:
        return h.copy()
    m = n // factor
    H = np.concatenate(([0.0], np.cumsum(h)))
    Htot = H[-1]
    if Htot <= 0:
        return h.copy()
    # new uniform breakpoints in cumulative-mass space
    tgt = np.linspace(0.0, 1.0, m + 1)
    Hv = np.interp(tgt, np.linspace(0.0, 1.0, n + 1), H)
    h2 = np.diff(Hv)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return h.copy()
    h2 *= Htot / h2.sum()
    return _rescale(h2)


def _polish_coarse(h, deadline, rounds=3):
    """Alternating full + peak-window polish with a short budget."""
    cur = h.copy()
    curR = R_of(cur)
    for r in range(rounds):
        if time.process_time() >= deadline - 0.4:
            break
        ht = _lbfgs_all_pos(cur, 300, deadline - 0.3, beta=0.0)
        rt = R_of(ht)
        if rt > curR + 1e-13:
            cur, curR = ht, rt
        if time.process_time() >= deadline - 0.4:
            break
        ht = _lbfgs_all_pos(cur, 200, deadline - 0.3, beta=1e7)
        rt = R_of(ht)
        if rt > curR + 1e-13:
            cur, curR = ht, rt
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(cur, pad_frac=0.3, extra=128)
        ht = _lbfgs_block(cur, win, 200, deadline - 0.3, beta=1e7)
        rt = R_of(ht)
        if rt > curR + 1e-13:
            cur, curR = ht, rt
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- New: coarsen-and-polish exploration ----
    # Try a few coarsening factors; each is polished within a fixed slice.
    if time.process_time() < deadline - 8.0:
        n0 = best.size
        factors = [2, 3, 5, 8]
        # time-slice: divide remaining exploration budget among factors
        explore_end = t0 + budget_seconds * 0.55
        per = max(0.5, (explore_end - time.process_time()) / max(1, len(factors)))
        for f in factors:
            if time.process_time() >= explore_end - 0.5:
                break
            if n0 // f < 64:
                continue
            sub_deadline = min(explore_end, time.process_time() + per)
            try:
                hc = _coarsen(best, f)
                rawR = R_of(hc)
                hp, rp = _polish_coarse(hc, sub_deadline, rounds=3)
                print("coarsen f=%d N=%d raw=%.7f pol=%.7f" %
                      (f, hc.size, rawR, rp))
                if rp > altR:
                    alt_cand, altR = hp.copy(), rp
                if rp > bestR + 1e-13:
                    # Lift back to fine grid, then polish at full resolution.
                    # Re-expand by upsampling the coarse profile.
                    best, bestR = hp.copy(), rp
            except Exception as e:
                print("coarsen f=%d failed: %s" % (f, e))

    # ---- Keep the base's proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
        now = time.process_time()
        if now - last_mini > 30.0:
            last_mini = now
            if time.process_time() < deadline - 6.5:
                st, r = _mini_cycle(best, bestR, deadline - 6.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip loop: dips=%d accepted=%d best_raw=%.3e R=%.7f" %
          (stats['dips'], stats['accepted'], stats['best_raw'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.99, pad_frac=0.10, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def polish(h, deadline, rounds=3):
    if time.process_time() > deadline - 0.5:
        return h
    h = _lbfgs_all_pos(h, 500, deadline)
    R = R_of(h)
    for beta in (50.0, 200.0, 800.0, 3000.0):
        if time.process_time() > deadline - 0.5:
            break
        hb = _lbfgs_all_pos(h, 200, deadline, beta=beta)
        Rb = R_of(hb)
        if Rb > R:
            R = Rb
            h = hb
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_all_pos(h, 300, deadline)
        if R_of(h2) > R:
            h = h2
    for _ in range(rounds):
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(h)
        h2 = _lbfgs_block(h, win, 300, deadline)
        if R_of(h2) > R_of(h):
            h = h2
    return h


def _beta_ladder(h, betas, iters, deadline):
    for beta in betas:
        if time.process_time() > deadline - 0.5:
            break
        h = _lbfgs_all_pos(h, iters, deadline, beta=beta)
    return h


def _prune(h, frac=0.03):
    h = np.clip(h, 0, None)
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    k = int(round(frac * nz.size))
    if k <= 0:
        return h
    vals = h[nz]
    order = np.argsort(vals)
    kill = nz[order[:k]]
    h = h.copy()
    h[kill] = 0.0
    return _rescale(h)


def _doubled_round(best, deadline):
    """Exact 2x duplication then polish. Returns (h, R) or (None, -1)."""
    if time.process_time() > deadline - 4.0:
        return None, -1.0
    if best.size * 2 > 1000000:
        return None, -1.0
    R0 = R_of(best)
    h2 = np.repeat(best, 2)
    # sanity: R unchanged by duplication
    h2 = _beta_ladder(h2, (1e6, 1e7, 1e8, 0.0), 250, deadline)
    if time.process_time() < deadline - 3.0:
        win = _peak_window(h2, tol=0.99, pad_frac=0.10, extra=64)
        h2b = _lbfgs_block(h2, win, 300, deadline, beta=1e7)
        if R_of(h2b) > R_of(h2):
            h2 = h2b
        h2b = _lbfgs_block(h2, win, 300, deadline, beta=0.0)
        if R_of(h2b) > R_of(h2):
            h2 = h2b
    if time.process_time() < deadline - 2.0:
        h2b = _lbfgs_all_pos(h2, 300, deadline, beta=0.0)
        if R_of(h2b) > R_of(h2):
            h2 = h2b
    R2 = R_of(h2)
    if R2 > R0 + 1e-14:
        return h2, R2
    return None, -1.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.0

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_R = R_of(best_h)

    if best_h is None:
        Nbase = 4096
        x = np.linspace(0.0, 1.0, Nbase)
        cur = np.exp(-((x - 0.5) ** 2) / 0.02)
        cur /= cur.sum()
        best_h = cur.copy()
        best_R = R_of(cur)

    cur = best_h.copy()
    cur = polish(cur, min(deadline, t0 + budget_seconds * 0.25))
    R = R_of(cur)
    print("seed polish R =", R, "N =", len(cur))
    if R > best_R:
        best_R = R; best_h = cur.copy()

    rnd = 0
    while time.process_time() < deadline - 2.0:
        # (a) doubled-grid round (twice per outer iteration if room)
        h2, R2 = _doubled_round(best_h, deadline)
        if h2 is not None:
            cur = h2
            R = R2
            if R > best_R:
                best_R = R; best_h = cur.copy()
            print("doubled R =", R, "N =", len(cur))
            # second doubling if room
            if time.process_time() < deadline - 6.0:
                h3, R3 = _doubled_round(best_h, deadline)
                if h3 is not None:
                    cur = h3
                    R = R3
                    if R > best_R:
                        best_R = R; best_h = cur.copy()
                    print("doubled2 R =", R, "N =", len(cur))
        else:
            # fall back: sharpen/prune at current N
            cur = _beta_ladder(cur, (1e6, 1e7, 1e8, 0.0), 250, deadline)
            R = R_of(cur)
            if R > best_R:
                best_R = R; best_h = cur.copy()
            cur = _prune(cur, 0.03)
            R = R_of(cur)
            if R > best_R:
                best_R = R; best_h = cur.copy()
            if time.process_time() < deadline - 4.0:
                win = _peak_window(cur, tol=0.99, pad_frac=0.10)
                h2b = _lbfgs_block(cur, win, 300, deadline, beta=1e7)
                if R_of(h2b) > R_of(cur):
                    cur = h2b
                win = _peak_window(cur, tol=0.99, pad_frac=0.06)
                h2b = _lbfgs_block(cur, win, 300, deadline, beta=1e7)
                if R_of(h2b) > R_of(cur):
                    cur = h2b
                R = R_of(cur)
                if R > best_R:
                    best_R = R; best_h = cur.copy()

        nz_frac = float(np.mean(cur <= 0))
        mean = cur.mean()
        mx = cur.max()
        print("round", rnd, "R =", R_of(cur), "N =", len(cur),
              "zero_frac =", round(nz_frac, 4),
              "max/mean =", round(mx / mean if mean > 0 else 0, 2))
        rnd += 1
        if rnd > 20:
            break

    if time.process_time() < deadline - 0.5:
        hf = polish(best_h, deadline)
        Rf = R_of(hf)
        if Rf > best_R:
            best_R = Rf
            best_h = hf

    print("best R =", best_R, "N =", len(best_h))
    return best_h

