import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth(h, passes=1):
    h = h.copy()
    for _ in range(passes):
        h[1:-1] = 0.25 * h[:-2] + 0.5 * h[1:-1] + 0.25 * h[2:]
    return _rescale(h)


# ---- New: direct local search on full N with random sign perturbation ----
def _perturb_descent(best, bestR, rng, end, budget_seconds, consider, tag):
    """Random sign perturbations of small localized blocks + LBFGS refine."""
    n = best.size
    rnd = 0
    while time.process_time() < end - 1.0:
        rnd += 1
        now = time.process_time()
        slice_dl = min(now + 1.5, end - 0.5)
        if slice_dl <= now + 0.3:
            break
        try:
            h = best.copy()
            # localized perturbation: pick a random contiguous block
            blk = max(8, n // 20)
            start_i = rng.integers(0, max(1, n - blk))
            amp = 0.10 * (0.5 + rng.random())
            h[start_i:start_i + blk] *= (1.0 + amp * rng.standard_normal(blk))
            h = _rescale(np.clip(h, 0, None))
            h = _lbfgs_all_pos(h, 120, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                win = _peak_window(h, pad_frac=0.15, extra=128)
                h = _lbfgs_block(h, win, 200, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                h = _lbfgs_all_pos(h, 150, slice_dl, beta=0.0)
            consider(h, 'blk%d' % rnd)
        except Exception:
            continue


# ---- New: windowed full-precision local tighten with tight pads ----
def _tighten(best, bestR, end, consider, tag):
    pads = [0.08, 0.05, 0.03, 0.02, 0.015, 0.01]
    for i, pad in enumerate(pads):
        if time.process_time() >= end - 0.5:
            break
        slice_dl = min(time.process_time() + 1.0, end - 0.3)
        win = _peak_window(best, pad_frac=pad, extra=64)
        ht = _lbfgs_block(best, win, 400, slice_dl, beta=1e7)
        consider(ht, '%s_pk%d' % (tag, i))
        if time.process_time() < slice_dl - 0.3:
            ht = _lbfgs_block(ht, win, 400, slice_dl, beta=0.0)
            consider(ht, '%s_pk%d_b0' % (tag, i))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(ht, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if ht is None or ht.size == 0:
            return
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR, origin = ht.copy(), r, tag
            print("  NEW BEST R=%.9f (%s)" % (bestR, tag))
        elif r > alt_bestR and r < bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 1: immediate fine tighten on start (highest value action) ----
    _tighten(best, bestR, min(deadline - 2.0, t0 + budget_seconds * 0.35),
             consider, 'p1')
    print("after phase1 tighten: R=%.9f" % bestR)

    # ---- Phase 2: alternating perturb + tighten loop ----
    pert_end = deadline - 4.0
    round_i = 0
    # Alternate: local block perturb, smoothing perturb, fine tighten
    while time.process_time() < pert_end - 1.0:
        round_i += 1
        now = time.process_time()
        slice_dl = min(now + 3.0, pert_end)
        if slice_dl <= now + 0.5:
            break
        # A: localized block perturb + LBFGS
        _perturb_descent(best, bestR, rng, slice_dl, budget_seconds, consider,
                         'r%d' % round_i)
        # B: smoothing perturb
        if time.process_time() < slice_dl - 0.5:
            hs = _smooth(best, passes=1 + (round_i % 2))
            hs = _lbfgs_all_pos(hs, 200, slice_dl, beta=1e7)
            consider(hs, 'sm%d' % round_i)
        # C: fine tighten on new best
        if time.process_time() < slice_dl - 0.3:
            _tighten(best, bestR, slice_dl, consider, 't%d' % round_i)

    # ---- Phase 3: N/2 quotient search (structure exploitation) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 3.0:
        # Try extracting even/odd and optimizing at half resolution
        for parity in [0, 1]:
            if time.process_time() >= deadline - 2.5:
                break
            c = best[parity::2].copy()
            c = _rescale(c)
            slice_dl = min(time.process_time() + 2.0, deadline - 1.5)
            c2 = _lbfgs_all_pos(c, 300, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                win = _peak_window(c2, pad_frac=0.15, extra=64)
                c2 = _lbfgs_block(c2, win, 300, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.3:
                c2 = _lbfgs_all_pos(c2, 300, slice_dl, beta=0.0)
            # lift back to N and refine
            h = np.zeros(best.size)
            h[parity::2] = c2[:h[parity::2].size]
            h[1 - parity::2] = c2[:h[1 - parity::2].size]
            h = _rescale(h)
            if time.process_time() < deadline - 0.5:
                h = _lbfgs_all_pos(h, 300, deadline - 0.3, beta=1e7)
            consider(h, 'half%d' % parity)

    # ---- Phase 4: 2N lift refinement (longer per-iteration) ----
    if best.size >= 2 and time.process_time() < deadline - 3.0:
        n = best.size
        u = np.empty(2 * n)
        u[0::2] = best
        u[1::2] = best
        u = _rescale(u)
        slice_dl = min(time.process_time() + 3.0, deadline - 2.0)
        u = _lbfgs_all_pos(u, 200, slice_dl, beta=1e7)
        if time.process_time() < slice_dl - 0.5:
            win = _peak_window(u, pad_frac=0.10, extra=128)
            u = _lbfgs_block(u, win, 200, slice_dl, beta=1e7)
        h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:n]
        if time.process_time() < slice_dl - 0.4:
            h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e6)
        if time.process_time() < slice_dl - 0.3:
            h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e7)
        consider(h2, 'lift2n')

    # ---- Final aggressive tighten ----
    _tighten(best, bestR, deadline - 0.3, consider, 'fin')

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

