        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        for beta in (3e6, 1e7, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
    return h


def _asym_split(h, sigma, rng):
    n = h.size
    w0 = np.exp(sigma * rng.standard_normal(n))
    w1 = np.exp(sigma * rng.standard_normal(n))
    m = 0.5 * (w0 + w1)
    w0 /= m
    w1 /= m
    h2 = np.empty(2 * n)
    h2[0::2] = h * w0
    h2[1::2] = h * w1
    return _rescale(h2)


def _fold_mean(h2):
    return _rescale(0.5 * (h2[0::2] + h2[1::2]))


def _quotient(h, pairing):
    n = h.size
    m = (n + 1) // 2
    if pairing == 'even':
        c = h[0::2].copy()
    elif pairing == 'odd':
        c = h[1::2].copy()
    else:  # avg
        ev = h[0::2]
        od = h[1::2]
        if od.size < ev.size:
            od = np.concatenate((od, [0.0]))
        c = 0.5 * (ev + od)
    return _rescale(c)


def _lift(c, N, rotate):
    m = c.size
    h2 = np.empty(N)
    if not rotate:
        h2[0::2] = c[:len(h2[0::2])]
        h2[1::2] = c[:len(h2[1::2])]
    else:
        cs = np.concatenate(([c[-1]], c[:-1]))
        h2[0::2] = cs[:len(h2[0::2])]
        h2[1::2] = c[:len(h2[1::2])]
    return _rescale(h2)


def _polish_half(c, deadline):
    for beta, it in ((1e5, 200), (1e6, 200), (1e7, 200), (0.0, 300)):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(c, it, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(c) + 1e-15:
            c = ht
    return c


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        h = np.ones(1024)
        h = _lbfgs_all_pos(h, 800, deadline - 1.0, beta=0.0)
        h = _smooth_peak_ladder(h, deadline - 0.5)
        return h

    cur = start_arr.copy()
    cur_r = best_r

    # Baseline refinement from the base program.
    cur = _smooth_peak_ladder(cur, deadline - 3.0)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("smooth R=%.8f" % best_r)

    cur = _peak_polish(cur, deadline - 1.5)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("peak   R=%.8f" % best_r)

    # ---- Quotient phase: ~40% of budget ----
    q_deadline = t0 + 0.40 * budget_seconds
    N = best.size
    best_quot_r = -1.0
    best_quot_info = None
    for pairing in ('even', 'odd', 'avg'):
        if time.process_time() >= q_deadline - 1.0:
            break
        c_in = _quotient(best, pairing)
        r_in = R_of(c_in)
        c = _polish_half(c_in, q_deadline - 0.5)
        r_c = R_of(c)
        print("quot %s: R_in=%.8f R_c=%.8f" % (pairing, r_in, r_c))
        if r_c > best_quot_r:
            best_quot_r = r_c
            best_quot_info = (pairing, c.copy(), r_in)
        # lift back both orientations, repair, accept if better
        for rotate in (False, True):
            if time.process_time() >= q_deadline - 0.5:
                break
            h2 = _lift(c, N, rotate)
            h2 = _smooth_peak_ladder(h2, q_deadline - 0.3)
            h2 = _peak_polish(h2, q_deadline - 0.2, pads=(0.10, 0.06, 0.035),
                              iters=300)
            r2 = R_of(h2)
            print("  lift %s rot=%s R=%.8f" % (pairing, rotate, r2))
            if r2 > best_r + 1e-15:
                best, best_r = h2.copy(), r2
                print("NEW BEST(quot %s rot=%s) R=%.8f" % (pairing, rotate, best_r))

    if best_quot_info is not None:
        print("best quotient: %s R=%.8f (in %.8f)"
              % (best_quot_info[0], best_quot_r, best_quot_info[2]))

    # ---- Asymmetric 2N split rounds with remaining budget ----
    rng = np.random.default_rng(987654321)
    round_no = 0
    while time.process_time() < deadline - 12.0:
        round_no += 1
        h2 = _asym_split(best, sigma=0.5, rng=rng)
        h2 = _lbfgs_all_pos(h2, 120, deadline - 8.0, beta=0.0)
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 8.0:
                break
            ht = _lbfgs_all_pos(h2, 120, deadline - 8.0, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-15:
                h2 = ht
        for pad in (0.12, 0.08, 0.05):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(h2, pad_frac=pad, extra=128)
            for beta in (1e6, 1e7, 0.0):
                if time.process_time() >= deadline - 8.0:
                    break
                ht = _lbfgs_block(h2, win, 120, deadline - 8.0, beta=beta)
                if R_of(ht) > R_of(h2) + 1e-15:
                    h2 = ht
        r2 = R_of(h2)
        hf = _fold_mean(h2)
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 8.0:
                break
            ht = _lbfgs_all_pos(hf, 120, deadline - 8.0, beta=beta)
            if R_of(ht) > R_of(hf) + 1e-15:
                hf = ht
        for pad in (0.08, 0.05):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(hf, pad_frac=pad, extra=128)
            for beta in (1e6, 1e7, 0.0):
                if time.process_time() >= deadline - 8.0:
                    break
                ht = _lbfgs_block(hf, win, 120, deadline - 8.0, beta=beta)
                if R_of(ht) > R_of(hf) + 1e-15:
                    hf = ht
        rf = R_of(hf)
        if rf > best_r + 1e-15:
            best, best_r = hf.copy(), rf
            print("NEW BEST R=%.8f (2N R=%.8f, round %d)" % (best_r, r2, round_no))
        elif r2 > best_r + 1e-15:
            hc = _quotient(h2, 'avg')
            hc = _lift(hc, N, False)
            rc = R_of(hc)
            if rc > best_r + 1e-15:
                best, best_r = hc, rc
                print("NEW BEST(coarse) R=%.8f" % best_r)

    # ---- Phase R: randomized asymmetric 2x split (F1391-style) ----
    # Each original cell's mass is preserved: w0+w1 normalised to mean 1.
    r_deadline = deadline - 3.0
    sigmas = (0.05, 0.10, 0.20)
    rng_r = np.random.default_rng(1391)
    trial = 0
    while trial < 20 and time.process_time() < r_deadline - 1.0:
        sigma = sigmas[trial % len(sigmas)]
        trial += 1
        n = best.size
        w0 = np.exp(sigma * rng_r.standard_normal(n))
        w1 = np.exp(sigma * rng_r.standard_normal(n))
        m = 0.5 * (w0 + w1)
        w0 /= m
        w1 /= m
        h2 = np.empty(2 * n)
        h2[0::2] = best * w0
        h2[1::2] = best * w1
        h2 = _rescale(h2)
        r_in = R_of(h2)
        # beta ladder: 1e5, 1e6, 1e7, 0 each 150 iters
        for beta in (1e5, 1e6, 1e7, 0.0):
            if time.process_time() >= r_deadline - 0.5:
                break
            ht = _lbfgs_all_pos(h2, 150, r_deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-16:
                h2 = ht
        # peak-window polish pad 0.05
        if time.process_time() < r_deadline - 0.5:
            win = _peak_window(h2, pad_frac=0.05, extra=128)
            for beta in (1e6, 1e7, 0.0):
                if time.process_time() >= r_deadline - 0.5:
                    break
                ht = _lbfgs_block(h2, win, 150, r_deadline - 0.3, beta=beta)
                if R_of(ht) > R_of(h2) + 1e-16:
                    h2 = ht
        # full plain polish
        if time.process_time() < r_deadline - 0.5:
            ht = _lbfgs_all_pos(h2, 150, r_deadline - 0.3, beta=0.0)
            if R_of(ht) > R_of(h2) + 1e-16:
                h2 = ht
        r2 = R_of(h2)
        delta = r2 - best_r
        print("split t=%d sigma=%.2f R=%.8f delta=%+.2e" % (trial, sigma, r2, delta))
        if r2 > best_r + 1e-14:
            best, best_r = h2.copy(), r2
            print("NEW BEST(split) R=%.8f" % best_r)

    # Final sharp ladder + small peak polish.
    if time.process_time() < deadline - 0.5:
        for beta in (1e8, 1e9, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 0.3, beta=beta)
            if R_of(ht) > best_r + 1e-15:
                best, best_r = ht, R_of(ht)
                print("final  R=%.8f" % best_r)
    if time.process_time() < deadline - 0.5:
        cand = _peak_polish(best, deadline - 0.3, pads=(0.05, 0.03), iters=300)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
            print("polish R=%.8f" % best_r)

    if start_arr is not None and R_of(start_arr) >= best_r:
        if cur.shape == start_arr.shape and not np.allclose(cur, start_arr, rtol=0, atol=0):
            return {"best": start_arr, "alternative": cur}
        return start_arr

    if start_arr is not None and not np.allclose(best, start_arr, rtol=0, atol=0):
        return {"best": best, "alternative": start_arr}

    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.5, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = int(idx.min()); hi = int(idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.6, 0.4, 0.25, 0.15, 0.08, 0.04)):
    best = h
    bestR = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        cap = min(deadline - 0.3, time.process_time() + 3.0)
        ht = _lbfgs_block(best, win, 400, cap)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
    return best, bestR


def _random_window(h, rng, lo_frac, hi_frac):
    n = h.size
    w = int(rng.uniform(lo_frac, hi_frac) * n)
    w = max(8, min(n, w))
    a = int(rng.integers(0, max(1, n - w)))
    return np.arange(a, a + w)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # Phase 1: full-vector polish (all positive), several restarts from best.
    for _ in range(3):
        if time.process_time() >= deadline - 1.0:
            break
        cap = min(deadline - 0.5, time.process_time() + 6.0)
        hp = _lbfgs_all_pos(best, 300, cap)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
            print("  full R=%.9f" % bestR)

    # Phase 2: peak-focused block polish ladder at multiple tolerance levels.
    cycle = 0
    while time.process_time() < deadline - 0.5:
        cycle += 1
        # peak ladder
        if time.process_time() < deadline - 0.5:
            cap = min(deadline - 0.3, time.process_time() + 8.0)
            hp, rp = _peak_ladder(best, cap)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("  cyc=%d peak R=%.9f" % (cycle, bestR))

        # random sub-window polish: try several random windows of varied sizes
        for _ in range(6):
            if time.process_time() >= deadline - 0.5:
                break
            win = _random_window(best, rng, 0.02, 0.3)
            cap = min(deadline - 0.3, time.process_time() + 1.5)
            ht = _lbfgs_block(best, win, 150, cap)
            rt = R_of(ht)
            if rt > bestR + 1e-15:
                best, bestR = ht, rt
                print("  cyc=%d win R=%.9f" % (cycle, bestR))

        # full-vector polish to consolidate
        if time.process_time() < deadline - 0.5:
            cap = min(deadline - 0.3, time.process_time() + 5.0)
            hp = _lbfgs_all_pos(best, 200, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("  cyc=%d full R=%.9f" % (cycle, bestR))

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
