    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    if c[-1] <= 0:
        return np.ones(n_new)
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _seed_cosine(n):
    x = np.linspace(0, 1, n)
    return np.cos(np.pi * (x - 0.5)) ** 2 + 1e-3


def _seed_asym(n):
    x = np.linspace(0, 1, n)
    return np.exp(-((x - 0.35) / 0.2) ** 2) + 1e-3


def _seed_triangular(n):
    x = np.linspace(0, 1, n)
    return np.minimum(x, 1 - x) + 1e-3


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    bestR = -1.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            best = _rescale(s)
            bestR = R_of(best)

    alt = None

    # ---- Phase A: seed optimisation at small N (only if we have time) ----
    N0 = 256
    seeds = [("cosine", _seed_cosine(N0)),
             ("asym", _seed_asym(N0)),
             ("triangular", _seed_triangular(N0))]
    survivors = []
    if time.process_time() < deadline - 20.0:
        for name, s in seeds:
            if time.process_time() > deadline - 20.0:
                break
            try:
                h = _lbfgs_log(s, 300, deadline - 20.0, beta=0.0)
                h = _lbfgs_log(h, 300, deadline - 20.0, beta=8.0)
                r = R_of(h)
                survivors.append((r, name, h))
            except Exception:
                pass
    survivors.sort(key=lambda t: -t[0])

    # ---- Phase B: ladder prolongation + polishing ----
    ladder_best = None
    ladder_R = -1.0
    for r0, name, h in (survivors[:1] if survivors else []):
        cur = h
        for n_new in [512, 1024, 2048, 4096, 8192, 16384, 32768]:
            if time.process_time() > deadline - 8.0:
                break
            cur = _prolong(cur, n_new)
            cur = _lbfgs_log(cur, 250, deadline - 8.0, beta=0.0)
            cur = _lbfgs_log(cur, 150, deadline - 8.0, beta=10.0)
        r = R_of(cur)
        print(f"ladder {name}: R={r:.6f} N={len(cur)}")
        if r > ladder_R:
            ladder_R = r
            ladder_best = cur

    if ladder_best is not None and ladder_R > bestR:
        best = ladder_best
        bestR = ladder_R

    # ---- Phase C: improve from start itself with a finer ladder ----
    if start is not None and time.process_time() < deadline - 6.0:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            for n_new in [len(s), 2 * len(s), 4 * len(s), 8 * len(s)]:
                if n_new > 300000:
                    break
                if time.process_time() > deadline - 6.0:
                    break
                cur = _prolong(s, n_new)
                cur = _lbfgs_log(cur, 300, deadline - 6.0, beta=0.0)
                cur = _lbfgs_log(cur, 150, deadline - 6.0, beta=6.0)
                r = R_of(cur)
                if r > bestR:
                    best, bestR = cur, r
                    print(f"start-ladder: R={r:.6f} N={len(cur)}")

    # ---- Phase D: refine current best at higher resolution ----
    if best is not None:
        cur = best
        for n_new in [len(cur), 2 * len(cur), 4 * len(cur)]:
            if n_new > 400000:
                break
            if time.process_time() > deadline - 3.0:
                break
            cur = _prolong(cur, n_new)
            cur = _lbfgs_log(cur, 300, deadline - 3.0, beta=0.0)
            r = R_of(cur)
            if r > bestR:
                best, bestR = cur, r
                print(f"refine: R={r:.6f} N={len(cur)}")

    # ---- Phase E: sparsification attempt ----
    if best is not None:
        cur = best.copy()
        nz = cur[cur > 0]
        if nz.size > 0:
            thr = np.quantile(nz, 0.10)
            cur[cur < thr] = 0.0
            cur2 = _lbfgs_log(cur, 200, deadline - 2.0, beta=0.0)
            r = R_of(cur2)
            if r > bestR + 1e-9:
                best, bestR = cur2, r
                print(f"sparsify: R={r:.6f}")

    if best is None:
        best = np.ones(50)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)

    if ladder_best is not None and abs(ladder_R - bestR) > 1e-9 and ladder_R > R_of(start) if start is not None else False:
        alt = ladder_best

    print(f"final R={R_of(best):.6f} N={len(best)}")
    if alt is not None and R_of(alt) > (R_of(start) if start is not None else 0):
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _perturb_peak(h, sigma, frac=0.30):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    L = _conv(h)
    peak = int(np.argmax(L))
    center = peak / 2.0
    half = max(2, int(frac * n))
    lo = max(0, int(center) - half)
    hi = min(n, int(center) + half)
    if hi <= lo:
        return h
    noise = np.random.randn(hi - lo) * sigma
    h[lo:hi] = np.maximum(h[lo:hi] * np.exp(noise), 0.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.0
    np.random.seed(20240)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.clip(h, 0, None))

    best_h = h.copy()
    best_R = R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Prolongate to higher resolution if small.
    target_N = max(h.size, 8192)
    if h.size < target_N:
        hp = _rescale(_prolongate_mass(h, target_N))
        Rp = R_of(hp)
        print("prolongate -> %d R=%.6f" % (target_N, Rp))
        if Rp > best_R:
            best_R, best_h = Rp, hp.copy()
        cur_h = hp.copy()
    else:
        cur_h = h.copy()
    cur_R = R_of(cur_h)

    # Main alternating loop: peak-window polish + full polish + perturbation restarts.
    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1

        # 1. Peak ladder at increasing sharpness.
        cur_h = _peak_ladder(cur_h, deadline)
        cur_R = R_of(cur_h)
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

        if time.process_time() >= deadline - 1.0:
            break

        # 2. Full-vector polish with smoothed-inf (beta) and true objective.
        h2 = _lbfgs_all_pos(cur_h, 300, deadline, beta=1e6)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

        if time.process_time() >= deadline - 1.0:
            break

        h2 = _lbfgs_all_pos(cur_h, 200, deadline, beta=0.0)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

        if time.process_time() >= deadline - 1.0:
            break

        # 3. Perturb the peak and re-polish (escape local optima).
        sigma = 0.02 if (cycle % 2 == 1) else 0.05
        hp = _perturb_peak(cur_h, sigma, frac=0.25)
        hp = _lbfgs_all_pos(hp, 200, deadline, beta=1e6)
        Rp = R_of(hp)
        if Rp > cur_R:
            cur_h, cur_R = hp, Rp
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

        print("  cycle %d R=%.6f best=%.6f" % (cycle, cur_R, best_R))

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

