    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _resample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    new_n = n * factor
    x_new = np.linspace(0.0, 1.0, new_n, endpoint=False)
    return np.interp(x_new, x_old, h, right=h[-1])


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e8), (0.25, 128, 1e8), (0.40, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


# ---- New idea: local "bump" perturbation search ----
# Perturb a localised window of heights by a smooth random bump, re-polish,
# and keep if it improves.  This explores the shape-space near `start`
# instead of only re-descending the same basin, which is what the original
# program does on repeat calls.

def _random_bump(n, rng, frac=0.15, lobes=2):
    m = max(2, int(n * frac))
    if m >= n:
        m = n - 1
    start = rng.integers(0, n - m)
    x = np.linspace(0.0, np.pi, m)
    bump = np.zeros(m)
    for k in range(1, lobes + 1):
        bump += rng.normal() * np.sin(k * x)
    out = np.zeros(n)
    out[start:start + m] = bump
    return out


def _perturb(h, rng, amp):
    n = h.size
    b = _random_bump(n, rng)
    scale = max(h.mean(), 1e-12)
    out = h + amp * scale * b
    return _rescale(np.clip(out, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(int(1e6 * (t0 % 1000)) + 12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: quick polish on the start array (cheap, may already help).
    if time.process_time() < deadline - 8.0:
        ht, rt = run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR, origin = ht, rt, origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # Phase B: local bump perturbation search.  Spend the bulk of the
    # remaining budget here, since repeated identical polishing of the same
    # start is wasted effort.
    n = best.size
    # amplitude ladder in units of mean height; small enough to stay near
    # the current basin but big enough to cross narrow suboptimal ridges.
    amps = [0.02, 0.05, 0.10, 0.20, 0.35]
    it = 0
    while time.process_time() < deadline - 4.0:
        amp = amps[it % len(amps)]
        it += 1
        try:
            hp = _perturb(best, rng, amp)
            hp = _seed_zeros(hp) if np.mean(hp <= 0) > 0.3 else hp
            # quick polish: peak window only, keeps cost low
            win = _peak_window(hp, pad_frac=0.20, extra=128)
            ht = _lbfgs_block(hp, win, 120, deadline - 3.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                # full polish of the promising candidate
                ht, r = run_cycle(ht, r, deadline - 2.0)
                if r > bestR + 1e-13:
                    best, bestR, origin = ht, r, 'perturb(amp=%.2f)' % amp
                    print("perturb amp=%.2f: R=%.9f" % (amp, bestR))
        except Exception:
            pass

    # Phase C: final tight polish on peak window.
    for beta in (0.0, 1e7):
        if time.process_time() >= deadline - 0.5:
            break
        try:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR, origin = ht, r, origin + '+tight'
        except Exception:
            pass

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    amax0 = _argmax_frac(best)

    # ---- Phase A: front-loaded peak-window beta ladder ----
    a_deadline = t0 + budget_seconds * 0.10
    for pad in (0.06, 0.04, 0.025):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.3f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase P: polyphase (strided) coordinate moves ----
    p_deadline = deadline - 4.0
    sched = [32, 16, 32, 8, 16, 32, 4, 16, 32, 8, 32, 16, 32, 32]
    for t in range(1, 15):
        if time.process_time() >= p_deadline:
            print("P t=%d skipped (time)" % t)
            break
        N = best.size
        s = sched[t - 1]
        if N % s != 0:
            s = 1
            for cand_s in (32, 16, 8, 4, 2):
                if N % cand_s == 0:
                    s = cand_s
                    break
        r = (t - 1) % s
        idx = np.arange(r, N, s)
        if idx.size < 2:
            print("P t=%d s=%d r=%d skipped (small)" % (t, s, r))
            continue
        R_before = bestR
        q = best[idx].copy()
        dl = deadline - 2.5
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= dl - 0.5:
                break
            q = _lbfgs_all_pos(q, 150, dl, beta=beta)
        q = np.clip(q, 0.0, None)
        sq = q.sum()
        sb = best[idx].sum()
        if sq > 0 and sb > 0:
            q = q * (sb / sq)
        h2 = best.copy()
        h2[idx] = np.clip(q, 0.0, None)
        h2 = _lbfgs_all_pos(h2, 200, dl, beta=1e7)
        h2 = _lbfgs_all_pos(h2, 200, dl, beta=0.0)
        h2 = _peak_ladder(h2, dl, pads=(0.05, 0.03), iters=150)
        r2 = R_of(h2)
        dR = r2 - R_before
        if r2 > bestR + 1e-14:
            best, bestR = h2.copy(), r2
            print("P t=%d s=%d r=%d dR=%.3e R=%.9f ACCEPT" % (t, s, r, dR, bestR))
        else:
            if r2 > alt_bestR:
                alt_best, alt_bestR = h2.copy(), r2
            print("P t=%d s=%d r=%d dR=%.3e R=%.9f" % (t, s, r, dR, r2))
    print("Phase P done R=%.9f N=%d" % (bestR, best.size))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.97
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

