    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


# ---------- Gauss-Newton on the near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=40):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    A = np.flatnonzero(Lf >= kappa * mx)
    if A.size == 0:
        return h
    A = A.astype(int)
    r = Lf[A] - mx

    def JtJ(v):
        Jv = _Jd(h, v, A)
        return _JT(h, Jv, A, n) + lam_scale * v

    b = -_JT(h, r, A, n)
    x = np.zeros(n)
    rr = b.copy()
    p = rr.copy()
    rsold = np.dot(rr, rr)
    if rsold <= 0:
        return h
    for _ in range(cg_iters):
        if time.process_time() > deadline - 0.5:
            break
        Ap = JtJ(p)
        denom = np.dot(p, Ap)
        if denom <= 0:
            break
        alpha = rsold / denom
        x += alpha * p
        rr -= alpha * Ap
        rsnew = np.dot(rr, rr)
        if rsnew < 1e-20 * rsold:
            break
        p = rr + (rsnew / rsold) * p
        rsold = rsnew
    h2 = np.clip(h + x, 0.0, None)
    return _rescale(h2)


def _gn_polish(h, r, deadline, iters=20):
    for k in range(iters):
        if time.process_time() > deadline - 1.0:
            break
        lam = 10.0 ** (-(k % 6) - 2)
        cand = _gn_step(h, 0.995, lam, deadline, cg_iters=30)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
    return h, r


def _refine_line(h, r, deadline):
    while time.process_time() < deadline - 1.5:
        cand = _lbfgs_all_pos(h, maxiter=200, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _gn_polish(h, r, deadline, iters=8)
        if r2 > r:
            h, r = cand, r2
        cand = _peak_ladder(h, deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        # beta-smoothed full refine to escape the max-index swap
        cand = _lbfgs_all_pos(h, maxiter=150, deadline=deadline, beta=5e5)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    if start_arr is not None:
        h = start_arr.copy()
        r = start_r
        print("start R=%.6f N=%d" % (r, h.size))
        best, best_r = h.copy(), r

        # Multiscale: coarsen -> refine -> prolongate -> refine.
        for target in (8192, 16384, 32768, 65536):
            if time.process_time() > deadline - 6.0:
                break
            if h.size > target:
                hc = h
                while hc.size > target:
                    hc = _coarsen(hc)
                hc = _rescale(hc)
            else:
                hc = _prolongate(h, target)
            rc = R_of(hc)
            cap = min(deadline - 4.0, time.process_time() + 6.0)
            hc, rc = _refine_line(hc, rc, cap)
            if hc.size < best.size:
                hfull = _prolongate(hc, best.size)
            else:
                hfull = hc
            rfull = R_of(hfull)
            cap2 = min(deadline - 2.0, time.process_time() + 8.0)
            hfull, rfull = _refine_line(hfull, rfull, cap2)
            if rfull > best_r:
                best, best_r = hfull, rfull
                print("  multiscale %d -> R=%.6f" % (target, best_r))
            h = best.copy()

        h, r = _refine_line(best, best_r, deadline - 1.0)
        if r > best_r:
            best, best_r = h, r
    else:
        N = 2048
        x = np.linspace(0, 1, N)
        h = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        cur_r = R_of(h)
        while N <= 65536 and time.process_time() < deadline - 4.0:
            h, cur_r = _refine_line(h, cur_r,
                                    min(deadline - 2.0,
                                        time.process_time() + 6.0))
            if N >= 65536:
                break
            N = min(N * 2, 65536)
            h = _prolongate(h, N)
            cur_r = R_of(h)
        best, best_r = h, cur_r
        print("fresh R=%.6f" % best_r)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None:
        if best_r > start_r + 1e-12:
            return {"best": _rescale(best), "alternative": _rescale(start_arr)}
        if best is not None and not np.array_equal(best, start_arr) and best_r > 0:
            return {"best": _rescale(start_arr), "alternative": _rescale(best)}
        return _rescale(start_arr)
    return _rescale(best)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    """Smooth-max surrogate: log-sum-exp of knot values (soft ||f*f||_inf)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=1500):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _perturb(h, rng, scale=0.03, nmodes=6):
    n = h.size
    x = np.linspace(0, 1, n)
    pert = np.zeros(n)
    for _ in range(nmodes):
        k = rng.integers(1, 8)
        ph = rng.uniform(0, 2 * np.pi)
        amp = rng.uniform(0.3, 1.0)
        pert += amp * np.sin(2 * np.pi * k * x + ph)
    if pert.max() - pert.min() > 0:
        pert = pert / (pert.max() - pert.min())
    h2 = h * (1.0 + scale * pert)
    return _rescale(np.clip(h2, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(20250812)

    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(200)
        best_r = R_of(best)

    base = best.copy()
    base_r = best_r

    def try_improve(cand, tol=1e-12):
        nonlocal best, best_r
        if cand is None:
            return False
        r = R_of(cand)
        if r > best_r + tol:
            best, best_r = cand.copy(), r
            return True
        return False

    # --- Phase 1: smooth-max (log-sum-exp) polish chain, then true-inf ---
    # This is the key change: a soft sup surrogate with increasing beta lets
    # mass redistribute smoothly to lift the peak, then true-inf refines it.
    if time.process_time() < deadline - 1.0:
        sub = time.process_time() + (deadline - time.process_time()) * 0.30
        for beta in (2.0, 6.0, 20.0, 80.0):
            if time.process_time() >= sub - 0.5:
                break
            fg = (lambda h, _b=beta: _fun_grad_beta(h, _b))
            cand = _lbfgs_log(best, maxiter=4000, deadline=sub, fg=fg)
            try_improve(cand)
        # pnorm bridge then true-inf
        for p in (12.0, 6.0, 3.0):
            if time.process_time() >= sub - 0.5:
                break
            fg = (lambda h, _p=p: _fun_grad_pnorm(h, _p))
            cand = _lbfgs_log(best, maxiter=4000, deadline=sub, fg=fg)
            try_improve(cand)
        try_improve(_lbfgs_block(best, np.arange(best.size),
                                 maxiter=6000, deadline=sub))

    # --- Phase 2: basin-hopping with perturbations + beta/pnorm smoothing ---
    n_restarts = 0
    while time.process_time() < deadline - 2.0:
        n_restarts += 1
        scale = 0.05 if n_restarts % 3 == 1 else (0.02 if n_restarts % 3 == 2 else 0.01)
        cand = _perturb(best, rng, scale=scale, nmodes=int(rng.integers(2, 8)))
        sub = min(deadline - 1.0,
                  time.process_time() + max(2.0, (deadline - time.process_time()) * 0.4))
        beta = 12.0 if n_restarts % 2 == 0 else 0.0
        if beta > 0:
            fg = (lambda h, _b=beta: _fun_grad_beta(h, _b))
        else:
            fg = (lambda h: _fun_grad_pnorm(h, 6.0))
        cand = _lbfgs_log(cand, maxiter=3000, deadline=sub, fg=fg)
        cand = _lbfgs_block(cand, np.arange(cand.size), maxiter=3000, deadline=sub)
        try_improve(cand, tol=1e-10)

    # --- Phase 3: prolongate to finer grid and polish ---
    if time.process_time() < deadline - 4.0 and best.size < 40000:
        N_big = min(40000, best.size * 2)
        h_big = _prolongate(best, N_big)
        sub = min(deadline - 1.0,
                  time.process_time() + (deadline - time.process_time()) * 0.5)
        fg = (lambda h: _fun_grad_pnorm(h, 6.0))
        cand = _lbfgs_log(h_big, maxiter=4000, deadline=sub, fg=fg)
        cand = _lbfgs_block(cand, np.arange(cand.size), maxiter=4000, deadline=sub)
        try_improve(cand)

    # --- Phase 4: final true-inf polish, plus peak-window ---
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_block(best, np.arange(best.size),
                            maxiter=8000, deadline=deadline)
        try_improve(cand)
    for frac, extra in [(0.5, 4), (0.2, 3), (0.08, 2)]:
        if time.process_time() >= deadline - 0.5:
            break
        sub = min(deadline - 0.3,
                  time.process_time() + (deadline - time.process_time()) * 0.5)
        try_improve(_window_polish_peak(best, sub, frac, extra, maxiter=2000))

    if base_r >= best_r:
        return {"best": base, "alternative": best}
    return {"best": best, "alternative": base}

