    if time.process_time() < deadline - 4.0:
        for gamma in (0.97, 1.03, 0.94, 1.06):
            if time.process_time() >= deadline - 3.0:
                break
            hw = _warp(best, gamma)
            rw = R_of(hw)
            slice_end = min(deadline - 1.0,
                            time.process_time() + budget_seconds * 0.06)
            hw, rw = _sharpen_prune_peak(hw, rw, slice_end)
            if rw > bestR + 1e-13:
                best, bestR = hw.copy(), rw
            if alt_best is None or rw > alt_bestR:
                alt_best, alt_bestR = hw, rw
        print("warp R=%.7f (N=%d)" % (bestR, best.size))

    # upsample 2x and refine
    if time.process_time() < deadline - 3.0:
        hu = _prolong(best, best.size * 2)
        ru = R_of(hu)
        slice_end = min(deadline - 1.0,
                        time.process_time() + budget_seconds * 0.12)
        hu, ru = _sharpen_prune_peak(hu, ru, slice_end)
        if time.process_time() < deadline - 1.0:
            slice_end = min(deadline - 1.0,
                            time.process_time() + budget_seconds * 0.08)
            hu, ru = _sharpen_prune_peak(hu, ru, slice_end)
        if ru > bestR + 1e-13:
            best, bestR = hu.copy(), ru
        if alt_best is None or ru > alt_bestR:
            alt_best, alt_bestR = hu, ru
        print("upsampled R=%.7f (N=%d)" % (ru, hu.size))

