        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _peak_ladder(h, deadline, pads=(0.12, 0.08, 0.05, 0.03), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def _gauss_smooth(h, sigma):
    if sigma <= 0:
        return h
    rad = int(3 * sigma) + 1
    x = np.arange(-rad, rad + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    pad = np.concatenate((np.zeros(rad), h, np.zeros(rad)))
    return np.convolve(pad, k, mode='valid')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_bestR = bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: half-resolution cycle (coarsen, polish, lift back)
    N = best.size
    best_c = None
    best_cR = -1.0
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 3.0:
        c = best[0::2].copy()
        cR = R_of(c)
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            if rounds > 0:
                # perturb
                rng = np.random.default_rng(rounds + 11)
                amp = [0.008, 0.02, 0.04][rounds % 3]
                cc = work_c.copy()
                nz = cc > 0
                if nz.sum() > 0:
                    cc[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
                work_c = _rescale(cc)
            for beta in [1e6, 1e7]:
                if time.process_time() >= half_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(work_c, 300, half_deadline - 0.3, beta=beta)
                r = R_of(ht)
                if r > best_cR + 1e-15:
                    work_c, best_c, best_cR = ht, ht.copy(), r
            for pad in [0.15, 0.10]:
                if time.process_time() >= half_deadline - 0.5:
                    break
                win = _peak_window(work_c, pad_frac=pad, extra=64)
                ht = _lbfgs_block(work_c, win, 300, half_deadline - 0.3, beta=1e7)
                r = R_of(ht)
                if r > best_cR + 1e-15:
                    work_c, best_c, best_cR = ht, ht.copy(), r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # Phase B: smoothing perturbations to escape local optimum
    if time.process_time() < deadline - 4.0:
        sigmas = [0.6, 1.2, 2.0, 3.0, 1.8, 0.9]
        si = 0
        while time.process_time() < deadline - 3.5:
            sigma = sigmas[si % len(sigmas)]
            si += 1
            hs = _rescale(_gauss_smooth(best, sigma))
            slice_deadline = min(deadline - 1.5,
                                 time.process_time() + 0.06 * budget_seconds)
            ht = hs
            for beta in [1e6, 1e7]:
                if time.process_time() >= slice_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 250, slice_deadline - 0.3, beta=beta)
            if time.process_time() < slice_deadline - 0.5:
                ht = _peak_ladder(ht, slice_deadline)
            if time.process_time() < slice_deadline - 0.5:
                ht = _lbfgs_all_pos(ht, 250, slice_deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, 'smooth%d' % si
                print("smooth sigma=%.2f NEW BEST R=%.9f" % (sigma, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # Phase C: upsample (interleave) to higher N and re-optimize to break grid symmetry
    if time.process_time() < deadline - 3.0:
        n = best.size
        h2 = np.zeros(2 * n)
        h2[0::2] = best
        h2[1::2] = 0.5 * (np.roll(best, 1) + best)
        h2 = _rescale(h2)
        slice_deadline = min(deadline - 1.0,
                             time.process_time() + 0.20 * budget_seconds)
        ht = h2
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= slice_deadline - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR, origin = ht.copy(), r, 'upsample'
            print("upsample NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        # also try downsampling back
        if ht.size == 2 * n:
            hd = _rescale(0.5 * (ht[0::2] + ht[1::2]))
            if time.process_time() < deadline - 1.0:
                hd = _lbfgs_all_pos(hd, 300, deadline - 0.5, beta=0.0)
            rd = R_of(hd)
            if rd > bestR + 1e-15:
                best, bestR, origin = hd.copy(), rd, 'upsample+down'
                print("upsample+down NEW BEST R=%.9f" % bestR)
            elif rd > alt_bestR:
                alt_best, alt_bestR = hd.copy(), rd

    # Phase D: fine peak polish on best
    if time.process_time() < deadline - 0.8:
        ht2 = _peak_ladder(best, deadline)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-15:
            best, bestR, origin = ht2.copy(), r2, origin + '+pk'
            print("peak polish NEW BEST R=%.9f" % bestR)
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2

    # Phase E: final all-pos polish
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR, origin = ht.copy(), r, origin + '+fin'
            print("final polish NEW BEST R=%.9f" % bestR)

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.99, pad_frac=0.10, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def polish(h, deadline, rounds=3):
    if time.process_time() > deadline - 0.5:
        return h
    h = _lbfgs_all_pos(h, 500, deadline)
    R = R_of(h)
    for beta in (50.0, 200.0, 800.0, 3000.0):
        if time.process_time() > deadline - 0.5:
            break
        hb = _lbfgs_all_pos(h, 200, deadline, beta=beta)
        Rb = R_of(hb)
        if Rb > R:
            R = Rb
            h = hb
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_all_pos(h, 300, deadline)
        if R_of(h2) > R:
            h = h2
    for _ in range(rounds):
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(h)
        h2 = _lbfgs_block(h, win, 300, deadline)
        if R_of(h2) > R_of(h):
            h = h2
    return h


def _beta_ladder(h, betas, iters, deadline):
    for beta in betas:
        if time.process_time() > deadline - 0.5:
            break
        h = _lbfgs_all_pos(h, iters, deadline, beta=beta)
    return h


def _prune(h, frac=0.03):
    h = np.clip(h, 0, None)
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    k = int(round(frac * nz.size))
    if k <= 0:
        return h
    vals = h[nz]
    order = np.argsort(vals)
    kill = nz[order[:k]]
    h = h.copy()
    h[kill] = 0.0
    return _rescale(h)


def _peak_ladder(h, deadline, pads=(0.06, 0.03)):
    for pad in pads:
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(h, tol=0.99, pad_frac=pad)
        h2 = _lbfgs_block(h, win, 300, deadline, beta=1e7)
        if R_of(h2) > R_of(h):
            h = h2
        h2 = _lbfgs_block(h, win, 300, deadline, beta=0.0)
        if R_of(h2) > R_of(h):
            h = h2
    return h


def _flank_runs(Lf, lo_frac=0.02, hi_frac=0.98, cap=4096):
    """Find contiguous index runs where lo_frac*M < Lf < hi_frac*M."""
    M = Lf.max()
    if M <= 0:
        return []
    mask = (Lf > lo_frac * M) & (Lf < hi_frac * M)
    n = mask.size
    runs = []
    i = 0
    while i < n:
        if mask[i]:
            j = i
            while j < n and mask[j]:
                j += 1
            runs.append((i, j - 1))
            i = j
        else:
            i += 1
    out = []
    for (a, b) in runs:
        if b - a + 1 > cap:
            mid = (a + b) // 2
            a = max(a, mid - cap // 2)
            b = min(b, a + cap - 1)
        out.append((a, b))
    return out


def _phase_R(best, best_R, deadline):
    """Phase R: free flank knots and polish them."""
    for rnd in range(8):
        if time.process_time() > deadline - 2.0:
            break
        Lf = _knots(best)
        M = Lf.max()
        if M <= 0:
            break
        runs = _flank_runs(Lf)
        # report metrics
        g = Lf
        band = np.mean((g > 0.05 * M) & (g < 0.5 * M))
        widths = [b - a + 1 for (a, b) in runs]
        nearmax5 = float(np.mean(Lf >= 0.95 * M))
        # build free set
        free = set()
        n = best.size
        for (a, b) in runs:
            lo = max(0, a - 32)
            hi = min(n - 1, b + 32)
            free.update(range(lo, hi + 1))
        win = _peak_window(best, tol=0.99, pad_frac=0.10)
        free.update(win.tolist())
        free = np.array(sorted(free), dtype=int)
        R0 = best_R
        cur = best
        curR = best_R
        for beta in (1e8, 1e7, 0.0):
            if time.process_time() > deadline - 2.0:
                break
            hb = _lbfgs_block(cur, free, 300, deadline, beta=beta)
            Rb = R_of(hb)
            if Rb > curR:
                cur = hb
                curR = Rb
        # peak ladder
        if time.process_time() < deadline - 2.0:
            hb = _peak_ladder(cur, deadline, pads=(0.06, 0.03))
            Rb = R_of(hb)
            if Rb > curR:
                cur = hb
                curR = Rb
        if time.process_time() < deadline - 6.0:
            hb = _lbfgs_all_pos(cur, 300, deadline, beta=0.0)
            Rb = R_of(hb)
            if Rb > curR:
                cur = hb
                curR = Rb
        dR = curR - R0
        print("R round", rnd, "band5_50 =", round(band, 4),
              "widths =", widths[:4], "nearmax5 =", round(nearmax5, 4),
              "dR =", dR, "R =", curR)
        if curR > best_R:
            best = cur
            best_R = curR
        if dR <= 0 and rnd >= 2:
            # no progress; still try one more but break soon
            if rnd >= 4:
                break
    return best, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.0
    hard = t0 + budget_seconds * 0.95

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_R = R_of(best_h)

    if best_h is None:
        Nbase = 4096
        x = np.linspace(0.0, 1.0, Nbase)
        cur = np.exp(-((x - 0.5) ** 2) / 0.02)
        cur /= cur.sum()
        best_h = cur.copy()
        best_R = R_of(cur)

    cur = best_h.copy()
    cur = polish(cur, min(deadline, t0 + budget_seconds * 0.20))
    R = R_of(cur)
    print("seed polish R =", R, "N =", len(cur))
    if R > best_R:
        best_R = R; best_h = cur.copy()

    # Phase R: flank polish
    best_h, best_R = _phase_R(best_h, best_R, hard)

    # If time remains, try a doubled grid once with flank polish
    while time.process_time() < hard - 4.0 and best_h.size * 2 <= 1000000:
        h2 = np.repeat(best_h, 2)
        h2 = _beta_ladder(h2, (1e6, 1e7, 1e8, 0.0), 250, hard)
        R2 = R_of(h2)
        if R2 > best_R:
            best_h = h2
            best_R = R2
            print("doubled R =", R2, "N =", len(h2))
            best_h, best_R = _phase_R(best_h, best_R, hard)
        else:
            break

    if time.process_time() < hard - 0.5:
        hf = polish(best_h, hard)
        Rf = R_of(hf)
        if Rf > best_R:
            best_R = Rf
            best_h = hf

    print("best R =", best_R, "N =", len(best_h))
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _lift(h, M):
    """Proportional resample to length M, preserving mass."""
    N = h.size
    idx = np.arange(N, dtype=float)
    tgt = np.arange(M, dtype=float) * (N / M)
    h2 = np.interp(tgt, idx, h) * (N / M)
    return np.clip(h2, 0, None)


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds * 0.96
    deadline = hard

    rng = np.random.RandomState(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase L: non-commensurate lift ladder ----
    L_deadline = t0 + budget_seconds * 0.40
    for ratio in (5.0 / 4.0, 4.0 / 3.0, 3.0 / 2.0):
        if time.process_time() >= L_deadline - 2.0:
            print("Phase L ratio %.4f skipped (time)" % ratio)
            break
        N = best.size
        M = int(round(N * ratio))
        if M > 1000000:
            M = 1000000
        h2 = _lift(best, M)
        act = h2 > 0
        h2[act] *= np.exp(0.05 * rng.randn(int(act.sum())))
        h2 = np.clip(h2, 0, None)
        R_before = bestR
        dl = L_deadline - 1.0
        ht = _lbfgs_all_pos(h2, 300, dl, beta=1e6)
        ht = _peak_ladder(ht, dl, pads=(0.06, 0.04, 0.02), iters=250)
        ht = _lbfgs_all_pos(ht, 300, dl, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-9:
            best, bestR = ht.copy(), r
            print("L ratio %.4f ACCEPT R=%.9f dR=%.3e N=%d"
                  % (ratio, bestR, bestR - R_before, best.size))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            print("L ratio %.4f revert R=%.9f dR=%.3e" % (ratio, r, r - R_before))
    print("Phase L done R=%.9f N=%d" % (bestR, best.size))

    # ---- Phase S: extract-quotient / polish / lift cycle ----
    S_deadline = t0 + budget_seconds * 0.80
    for rnd in range(3):
        if time.process_time() >= S_deadline - 4.0:
            print("S round %d skipped (time)" % rnd)
            break
        for stride in (2, 3):
            for off in range(stride):
                if time.process_time() >= S_deadline - 3.0:
                    break
                h = best
                N = h.size
                if N < stride * 8:
                    continue
                idx = np.arange(off, N, stride)
                c = h[idx].copy()
                if c.sum() <= 0:
                    continue
                c = _rescale(c)
                R_before = bestR
                dl = S_deadline - 2.0
                for beta in (1e5, 1e6, 1e7):
                    if time.process_time() >= dl - 1.0:
                        break
                    ct = _lbfgs_all_pos(c, 200, dl, beta=beta)
                    if R_of(ct) > R_of(c) + 1e-14:
                        c = ct
                c = _peak_ladder(c, dl, pads=(0.06, 0.04), iters=200)
                # lift back with randomised interlace weights
                M = N
                h2 = h.copy()
                Mc = c.size
                # place c back at its positions, fill others by interpolation
                full = np.zeros(M)
                full[idx] = c
                # fill non-idx positions by linear interp of neighbours
                if idx.size >= 2:
                    pos = np.arange(M)
                    full = np.interp(pos, idx, c)
                else:
                    full = np.interp(np.arange(M), idx, c)
                u = np.clip(0.5 + 0.1 * rng.randn(M), 0.2, 0.8)
                h2 = np.where(full > 0, full * (1.0 / np.maximum(u, 1e-6)) * 0.5 + h * u, h)
                h2 = np.clip(h2, 0, None)
                if h2.sum() <= 0:
                    continue
                h2 = _rescale(h2)
                ht = _lbfgs_all_pos(h2, 300, dl, beta=1e7)
                ht = _lbfgs_all_pos(ht, 300, dl, beta=0.0)
                r = R_of(ht)
                if r > bestR + 1e-9:
                    best, bestR = ht.copy(), r
                    print("S rnd %d stride %d off %d ACCEPT R=%.9f dR=%.3e"
                          % (rnd, stride, off, bestR, bestR - R_before))
                else:
                    if r > alt_bestR:
                        alt_best, alt_bestR = ht.copy(), r
                    print("S rnd %d stride %d off %d revert R=%.9f dR=%.3e"
                          % (rnd, stride, off, r, r - R_before))
    print("Phase S done R=%.9f N=%d" % (bestR, best.size))

    # ---- Phase F: final polish ----
    final_deadline = hard
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
