            if rb > bestR + 1e-14:
                best, bestR, origin = hb, rb, 'double2'
                print("double2 NEW BEST R=%.9f" % bestR)
            elif rb > alt_bestR:
                alt_best, alt_bestR = hb.copy(), rb

    # ---- Phase 3: structural edits ----
    struct_end = deadline - 4.0
    if time.process_time() < struct_end - 1.0 and best.size >= 4:
        Ns = best.size
        rng = np.random.RandomState(424242)
        trial = 0
        accepted = 0
        while time.process_time() < struct_end - 1.0:
            act = np.flatnonzero(best > 0.02 * best.max())
            if act.size == 0:
                break
            perm = rng.permutation(act)
            progressed = False
            for i in perm:
                i = int(i)
                if time.process_time() >= struct_end - 1.0:
                    break
                now = time.process_time()
                slice_dl = min(now + 1.2, deadline - 4.0)
                if slice_dl <= now + 0.3:
                    break
                trial += 1
                cands = []
                v = best[i]
                if v > 0:
                    for d in (-1, +1, -2, +2):
                        j = i + d
                        if 0 <= j < Ns and best[j] <= 0:
                            h2 = best.copy()
                            h2[i] = 0.0
                            h2[j] = h2[j] + v
                            cands.append(('move%d' % d, h2))
                            break
                if i + 1 < Ns:
                    h2 = best.copy()
                    half = 0.5 * best[i]
                    h2[i] = half
                    h2[i + 1] = h2[i + 1] + half
                    cands.append(('split', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    a = best[i] * (1.0 / 3.0)
                    h2[i] = a
                    h2[i + 1] = h2[i + 1] + (best[i] - a)
                    cands.append(('split2', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    h2[i] = h2[i] + h2[i + 1]
                    h2[i + 1] = 0.0
                    cands.append(('merge', h2))
                best_local = None
                best_localR = -1.0
                best_type = None
                for typ, h2 in cands:
                    if time.process_time() >= slice_dl - 0.3:
                        break
                    h2 = _rescale(np.clip(h2, 0, None))
                    win = _peak_window(h2, pad_frac=0.15, extra=384)
                    h2 = _lbfgs_block(h2, win, 120, slice_dl, beta=1e6)
                    if time.process_time() < slice_dl - 0.3:
                        h2 = _lbfgs_all_pos(h2, 120, slice_dl, beta=1e7)
                    r2 = R_of(h2)
                    if r2 > best_localR:
                        best_local, best_localR, best_type = h2, r2, typ
                if best_local is None:
                    continue
                progressed = True
                if best_localR > bestR + 1e-13:
                    best, bestR = best_local.copy(), best_localR
                    origin = 'struct_%s' % best_type
                    accepted += 1
                    print("struct trial %d %s at i=%d NEW BEST R=%.9f" %
                          (trial, best_type, i, bestR))
                elif best_localR > alt_bestR:
                    alt_best, alt_bestR = best_local.copy(), best_localR
            if not progressed:
                break
        print("struct edits done trials=%d accepted=%d bestR=%.9f" %
              (trial, accepted, bestR))

    # ---- Phase 4: final polish ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish(best, bestR, deadline)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------------- log-space phase ----------------

def _logspace_fun_grad(u, h_full, active):
    """F(u) = -log(num) + 2 log(sum h), with h rescaled so max knot = 1.
    Gradient wrt u has radial component removed."""
    h = h_full.copy()
    hu = np.exp(np.clip(u, -30.0, 30.0))
    h[active] = hu
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(u.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(u.size)
    # rescale h so max knot is exactly 1: h' = h / sqrt(mx)
    # num' = num / mx^2, s' = s / sqrt(mx), so F = -log(num') + 2 log(s')
    # = -log(num) + 2 log(mx) + 2 log(s) - log(mx) = -log(num) + 2 log(s) + log(mx)
    # (same value as before rescaling; gradient wrt h of the rescaled objective:)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    g_h = _backprop(gLf, h) + 2.0 / s
    # chain to u on active cells
    g_u = g_h[active] * hu
    # remove radial component: g_u -= (g_u . hu)/(hu . hu) * hu
    hh = float(np.dot(hu, hu))
    if hh > 0:
        c = float(np.dot(g_u, hu)) / hh
        g_u = g_u - c * hu
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, g_u


def _lbfgs_logspace(h0, thr, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    mxh = h.max()
    if mxh <= 0:
        return h0
    active = np.flatnonzero(h > thr * mxh)
    if active.size < 4:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    h_full = h.copy()

    def f(u):
        return _logspace_fun_grad(u, h_full, active)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    amax0 = _argmax_frac(best)

    # ---- Phase A: front-loaded peak-window beta ladder ----
    a_deadline = t0 + budget_seconds * 0.10
    for pad in (0.06, 0.04, 0.025):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.3f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase L: log-space with exact max projection ----
    l_deadline = t0 + budget_seconds * 0.85
    n_accept = 0
    thrs = (1e-12, 1e-9, 1e-6)
    for rnd, thr in enumerate(thrs):
        if time.process_time() >= l_deadline - 6.0:
            print("L round %d skipped (time)" % rnd)
            break
        R_before = bestR
        n_active = int(np.sum(best > thr * best.max()))
        # log-space optimisation
        ht = _lbfgs_logspace(best, thr, 300, l_deadline - 4.0)
        # one beta peak-window polish
        win = _peak_window(ht, pad_frac=0.05, extra=128)
        ht = _lbfgs_block(ht, win, 200, l_deadline - 2.5, beta=1e7)
        # one full beta=0 polish
        ht = _lbfgs_all_pos(ht, 200, l_deadline - 1.0, beta=0.0)
        r = R_of(ht)
        dR = r - R_before
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            n_accept += 1
            print("L round %d thr=%.0e ACCEPT R=%.9f dR=%.3e n_active=%d"
                  % (rnd, thr, bestR, dR, n_active))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            print("L round %d thr=%.0e reject R=%.9f dR=%.3e n_active=%d"
                  % (rnd, thr, r, dR, n_active))
    print("Phase L done R=%.9f n_accept=%d N=%d" % (bestR, n_accept, best.size))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.97
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time

try:
    from scipy.optimize import minimize
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False


def _R(h):
    h = np.asarray(h, dtype=float)
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    num = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    s = np.sum(h)
    den = s * s * np.max(L)
    if den <= 0:
        return 0.0
    return float(num / den)


def _rescale(h):
    m = np.mean(h)
    if m <= 0:
        return h
    return h / m


def _lbfgs_all_pos(h, iters, R_ref, beta=0.0, t0=None, tlim=None):
    """Maximize R via L-BFGS on -R with positivity; beta penalizes peak sharpness."""
    if not _HAVE_SCIPY:
        return h, _R(h)
    h = np.asarray(h, dtype=float)
    n = h.size
    if n < 2:
        return h, _R(h)

    def obj(z):
        # z = log h
        hh = np.exp(z)
        L = np.convolve(hh, hh)
        Lp = np.concatenate(([0.0], L, [0.0]))
        num = np.sum(Lp[:-1] ** 2 + Lp[:-1] * Lp[1:] + Lp[1:] ** 2) / 3.0
        s = np.sum(hh)
        mx = np.max(Lp)
        den = s * s * mx
        if den <= 0:
            return 1e10
        R = num / den
        val = -R
        if beta > 0:
            val += beta * (mx / (s * s + 1e-300)) * 0.0  # placeholder; keep simple
        return val

    z0 = np.log(np.maximum(h, 1e-12))
    try:
        res = minimize(obj, z0, method='L-BFGS-B',
                       options={'maxiter': iters, 'maxfun': iters * 4,
                                'ftol': 1e-12, 'gtol': 1e-10})
        hh = np.exp(res.x)
    except Exception:
        return h, _R(h)
    if _R(hh) > _R(h):
        return _rescale(hh), _R(hh)
    return h, _R(h)


def _lbfgs_block(h, pad, iters, R_ref, beta=1e4, t0=None, tlim=None):
    """Polish a window around the peak of f*f."""
    if not _HAVE_SCIPY:
        return h, _R(h)
    h = np.asarray(h, dtype=float)
    n = h.size
    L = np.convolve(h, h)
    k = int(np.argmax(L))
    # peak of f*f at index k (in L, length 2n-1); map to h index ~ k/2
    c = k / 2.0
    w = max(2, int(pad * n))
    lo = max(0, int(c - w))
    hi = min(n, int(c + w) + 1)
    if hi - lo < 2:
        return h, _R(h)
    sub = h[lo:hi].copy()
    # optimize sub keeping rest fixed: build full h each eval
    def obj(z):
        hh = h.copy()
        hh[lo:hi] = np.exp(z)
        Lf = np.convolve(hh, hh)
        Lp = np.concatenate(([0.0], Lf, [0.0]))
        num = np.sum(Lp[:-1] ** 2 + Lp[:-1] * Lp[1:] + Lp[1:] ** 2) / 3.0
        s = np.sum(hh)
        mx = np.max(Lp)
        den = s * s * mx
        if den <= 0:
            return 1e10
        return -num / den

    z0 = np.log(np.maximum(sub, 1e-12))
    try:
        res = minimize(obj, z0, method='L-BFGS-B',
                       options={'maxiter': iters, 'maxfun': iters * 4,
                                'ftol': 1e-12, 'gtol': 1e-10})
        hh = h.copy()
        hh[lo:hi] = np.exp(res.x)
    except Exception:
        return h, _R(h)
    if _R(hh) > _R(h):
        return _rescale(hh), _R(hh)
    return h, _R(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.80 * budget_seconds

    def time_left():
        return time.process_time() < deadline

    # Build QR comb
    N = 16384
    p = 251  # prime, p mod 4 = 3
    A = set()
    for i in range(p):
        r = (i * i) % p
        A.add(r)
    idx = np.arange(N)
    x = idx / (N - 1)
    env = ((x + 0.02) * (1 - x + 0.02)) ** -0.5
    env = np.clip(env, 0, 20)
    inA = np.array([1.0 if (i % p) in A else 0.0 for i in range(N)])
    h0 = env * (0.15 + 1.0 * inA)
    h0 = _rescale(h0)

    best = h0.copy()
    bestR = _R(best)
    print("init QR comb R=%.6f" % bestR)

    # Candidate pool: start with start if provided
    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = _R(s)
        if sR > bestR:
            best = _rescale(s.copy())
            bestR = sR
            print("start better R=%.6f" % bestR)

    # Stage 1: full polish beta=0
    if time_left():
        h, r = _lbfgs_all_pos(best, 120, bestR, beta=0.0)
        if r > bestR:
            best, bestR = h, r
        print("stage1 R=%.6f" % bestR)

    # Stage 2: beta ladder then peak windows
    for beta in (1e3, 1e4):
        if not time_left():
            break
        h, r = _lbfgs_all_pos(best, 100, bestR, beta=beta)
        if r > bestR:
            best, bestR = h, r
        print("stage2 beta=%.0e R=%.6f" % (beta, bestR))

    for pad in (0.10, 0.06):
        if not time_left():
            break
        h, r = _lbfgs_block(best, pad, 100, bestR, beta=1e4)
        if r > bestR:
            best, bestR = h, r
        print("stage2 pad=%.2f R=%.6f" % (pad, bestR))

    # Stage 3: 2x interlaced lift
    if time_left():
        n = best.size
        h2 = np.zeros(2 * n)
        h2[0::2] = 0.75 * best
        h2[1::2] = 0.25 * best
        h2 = _rescale(h2)
        r2 = _R(h2)
        if r2 > bestR:
            h, r = _lbfgs_all_pos(h2, 120, r2, beta=0.0)
            if r > bestR:
                best, bestR = h, r
            if time_left():
                h, r = _lbfgs_all_pos(best, 80, bestR, beta=1e4)
                if r > bestR:
                    best, bestR = h, r
            print("stage3 lift R=%.6f" % bestR)

    # Stage 4: alternate pad-0.04 peak ladder and beta=0 full polish
    prune_done = False
    half = t0 + 0.5 * budget_seconds
    while time_left():
        if not prune_done and time.process_time() > half:
            thr = 1e-4 * np.mean(best)
            best = np.where(best < thr, 0.0, best)
            best = _rescale(best)
            bestR = _R(best)
            prune_done = True
            print("pruned R=%.6f" % bestR)
        h, r = _lbfgs_block(best, 0.04, 80, bestR, beta=1e4)
        if r > bestR:
            best, bestR = h, r
        if not time_left():
            break
        h, r = _lbfgs_all_pos(best, 80, bestR, beta=0.0)
        if r > bestR:
            best, bestR = h, r
        print("stage4 R=%.6f" % bestR)

    # near-max fraction diagnostic
    L = np.convolve(best, best)
    mx = np.max(L)
    frac = np.mean(L > 0.99 * mx)
    print("final R=%.6f near-max=%.3f%% N=%d" % (bestR, 100 * frac, best.size))

    # Compare with start
    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = _R(s)
        if sR >= bestR:
            return {"best": s, "alternative": _rescale(best)}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth_peak_ladder(h, deadline, betas=(2e5, 5e5, 1e6, 3e6, 1e7, 0.0),
                        iters=400):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def _peak_polish(h, deadline, pads=(0.30, 0.18, 0.10, 0.06, 0.035), iters=500):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        for beta in (3e6, 1e7, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
    return h


def _quotient(h, pairing):
    n = h.size
    if pairing == 'even':
        c = h[0::2].copy()
    elif pairing == 'odd':
        c = h[1::2].copy()
    else:  # avg
        ev = h[0::2]
        od = h[1::2]
        if od.size < ev.size:
            od = np.concatenate((od, [0.0]))
        c = 0.5 * (ev + od)
    return _rescale(c)


def _polish_half(c, deadline):
    for beta, it in ((1e5, 200), (1e6, 200), (1e7, 200), (0.0, 300)):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(c, it, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(c) + 1e-15:
            c = ht
    # half-res peak-window polish
    if time.process_time() < deadline - 0.5:
        win = _peak_window(c, pad_frac=0.08, extra=128)
        for beta in (0.0, 1e6):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_block(c, win, 200, deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(c) + 1e-15:
                c = ht
    return c


def _lift_phase(c, N, phase):
    m = c.size
    h2 = np.zeros(N)
    if phase == 0:
        # h2[2i+phase]=c[i], h2[2i+1-phase]=c[i]
        idx_a = np.arange(0, N, 2)
        idx_b = np.arange(1, N, 2)
        if phase == 0:
            a_idx, b_idx = idx_a, idx_b
        else:
            a_idx, b_idx = idx_b, idx_a
        la = min(a_idx.size, m)
        lb = min(b_idx.size, m)
        h2[a_idx[:la]] = c[:la]
        h2[b_idx[:lb]] = c[:lb]
    else:
        # h2[2i+phase]=0.7*c[i]+0.3*c[i-1], h2[2i+1-phase]=0.3*c[i]+0.7*c[i-1]
        cprev = np.concatenate(([c[-1]], c[:-1]))
        v0 = 0.7 * c + 0.3 * cprev
        v1 = 0.3 * c + 0.7 * cprev
        idx_a = np.arange(0, N, 2)
        idx_b = np.arange(1, N, 2)
        if phase == 0:
            a_idx, b_idx = idx_a, idx_b
        else:
            a_idx, b_idx = idx_b, idx_a
        la = min(a_idx.size, m)
        lb = min(b_idx.size, m)
        h2[a_idx[:la]] = v0[:la]
        h2[b_idx[:lb]] = v1[:lb]
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        h = np.ones(1024)
        h = _lbfgs_all_pos(h, 800, deadline - 1.0, beta=0.0)
        h = _smooth_peak_ladder(h, deadline - 0.5)
        return h

    cur = start_arr.copy()
    cur_r = best_r

    # Baseline refinement from the base program.
    cur = _smooth_peak_ladder(cur, deadline - 3.0)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("smooth R=%.8f" % best_r)

    cur = _peak_polish(cur, deadline - 1.5)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("peak   R=%.8f" % best_r)

    # ---- Phase Q: cycling extract/polish/lift with rotating pairing ----
    q_deadline = t0 + 0.88 * budget_seconds
    pairings = ('even', 'odd', 'avg')
    phases = (0, 1)
    cycle = 0
    accepted = 0
    while time.process_time() < q_deadline - 1.0 and cycle < 12:
        for pairing in pairings:
            for phase in phases:
                if time.process_time() >= q_deadline - 1.0:
                    break
                N = best.size
                c_in = _quotient(best, pairing)
                r_in = R_of(c_in)
                c = _polish_half(c_in, q_deadline - 0.5)
                r_c = R_of(c)
                # lift back
                h2 = _lift_phase(c, N, phase)
                # repair: one beta=1e7 peak-window polish pad 0.05, 200 iters
                if time.process_time() < q_deadline - 0.5:
                    win = _peak_window(h2, pad_frac=0.05, extra=128)
                    ht = _lbfgs_block(h2, win, 200, q_deadline - 0.3, beta=1e7)
                    if R_of(ht) > R_of(h2) + 1e-16:
                        h2 = ht
                # one beta=0 full polish 200 iters
                if time.process_time() < q_deadline - 0.5:
                    ht = _lbfgs_all_pos(h2, 200, q_deadline - 0.3, beta=0.0)
                    if R_of(ht) > R_of(h2) + 1e-16:
                        h2 = ht
                r2 = R_of(h2)
                dR = r2 - best_r
                print("cycle %d pair=%s phase=%d R=%.8f dR=%+.2e (c_in=%.8f c=%.8f)"
                      % (cycle, pairing, phase, r2, dR, r_in, r_c))
                if r2 > best_r + 1e-14:
                    best, best_r = h2.copy(), r2
                    accepted += 1
                    print("NEW BEST(cycle %d %s p%d) R=%.8f" % (cycle, pairing, phase, best_r))
            if time.process_time() >= q_deadline - 1.0:
                break
        cycle += 1

    print("Phase Q done: %d accepted cycles, best R=%.8f" % (accepted, best_r))

    # Final sharp ladder + small peak polish.
    if time.process_time() < deadline - 0.5:
        for beta in (1e8, 1e9, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 0.3, beta=beta)
            if R_of(ht) > best_r + 1e-15:
                best, best_r = ht, R_of(ht)
                print("final  R=%.8f" % best_r)
    if time.process_time() < deadline - 0.5:
        cand = _peak_polish(best, deadline - 0.3, pads=(0.05, 0.03), iters=300)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
            print("polish R=%.8f" % best_r)

    if start_arr is not None and R_of(start_arr) >= best_r:
        if cur.shape == start_arr.shape and not np.allclose(cur, start_arr, rtol=0, atol=0):
            return {"best": start_arr, "alternative": cur}
        return start_arr

    if start_arr is not None and not np.allclose(best, start_arr, rtol=0, atol=0):
        return {"best": best, "alternative": start_arr}

    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.12, 0.08, 0.05, 0.03), iters=300):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _smooth_bump(n, center, width, sigma):
    t = np.arange(n, dtype=float)
    g = np.exp(-0.5 * ((t - center) / max(width, 1e-6)) ** 2)
    return np.exp(sigma * (g - g.max()))


def _perturb_local(h, rng, sigma, width, center=None):
    n = h.size
    if center is None:
        center = rng.uniform(0.15, 0.85) * n
    bump = _smooth_bump(n, center, width, sigma)
    return np.clip(h * bump, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20250711)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("start R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR

    # ---- Refinement: upsample by 2x (linear interp) and polish ----
    n0 = start_best.size
    if n0 * 2 <= 1_000_000:
        # linear interp between samples => smoother 2x lift
        H = np.repeat(start_best, 2)
        # blend: average neighbours to reduce staircase
        H[1::2] = 0.5 * (start_best + np.roll(start_best, -1))
        H[-1] = start_best[-1]
    else:
        H = start_best.copy()
    H = _rescale(np.clip(H, 0, None))
    print("2x baseline R=%.7f (N=%d)" % (R_of(H), H.size))

    H = _lbfgs_log(H, 200, deadline)
    H = _peak_ladder(H, deadline)
    R_H = R_of(H)
    print("2x polished R=%.7f" % R_H)
    if R_H > bestR + 1e-13:
        best, bestR = H.copy(), R_H

    # ---- End-spike scan (short support tails can lift R) ----
    nH = H.size
    cands = []
    for side in ("left", "right"):
        for k in (1, 2, 4, 8, 16, 32, 64):
            if k > nH:
                continue
            if side == "left":
                seg = H[0:k]; adj = H[k:k + 64]
            else:
                seg = H[-k:]; adj = H[-k - 64:-k]
            adj_mean = float(adj.mean()) if adj.size > 0 else float(H.mean())
            for mult in (1.5, 2.0, 3.0, 5.0, 8.0, 12.0, 20.0):
                for mode in ("scale", "set"):
                    Hc = H.copy()
                    if mode == "scale":
                        if side == "left":
                            Hc[0:k] = seg * mult
                        else:
                            Hc[-k:] = seg * mult
                    else:
                        if side == "left":
                            Hc[0:k] = mult * adj_mean
                        else:
                            Hc[-k:] = mult * adj_mean
                    Hc = _rescale(Hc)
                    r = R_of(Hc)
                    cands.append((r, side, k, mult, mode, Hc))
                    if time.process_time() > deadline - 15.0:
                        break
                if time.process_time() > deadline - 15.0:
                    break
            if time.process_time() > deadline - 15.0:
                break
        if time.process_time() > deadline - 15.0:
            break

    cands.sort(key=lambda t: -t[0])
    top = cands[:3]
    if top:
        print("top candidates: " + ", ".join(
            "%s k=%d mult=%.1f %s R=%.7f" % (c[1], c[2], c[3], c[4], c[0]) for c in top))

    def full_polish(hc, deadline):
        h = _lbfgs_log(hc, 200, deadline)
        h = _peak_ladder(h, deadline)
        r = R_of(h)
        for beta in (1e5, 1e7, 1e9):
            if time.process_time() >= deadline - 3.0:
                break
            hb = _lbfgs_log(h, 120, deadline, beta=beta)
            rb = R_of(hb)
            if rb > r:
                h, r = hb, rb
        return h, r

    for (r0, side, k, mult, mode, Hc) in top:
        if time.process_time() >= deadline - 8.0:
            break
        h, r = full_polish(Hc, deadline)
        print("  polished %s k=%d mult=%.1f %s -> R=%.7f" %
              (side, k, mult, mode, r))
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("  NEW BEST R=%.7f" % bestR)

    # ---- Stochastic loop: broad smooth-bump perturbations + polish ----
    cur = best.copy()
    curR = bestR
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        # choose perturbation: bump somewhere along support, or near peak
        if it % 4 == 0:
            # perturb around peak region
            Lf = _knots(cur)
            m = int(np.argmax(Lf))
            center = float(m) * cur.size / max(1, Lf.size - 1)
            center = float(np.clip(center + rng.normal(0, cur.size * 0.05),
                                   0, cur.size - 1))
        else:
            center = None
        width = float(rng.choice([32, 64, 128, 256, 512]))
        sigma = float(rng.choice([0.002, 0.005, 0.01, 0.02, 0.04]))
        hp = _perturb_local(cur, rng, sigma, width, center=center)
        hp = _rescale(hp)
        h1 = _lbfgs_log(hp, 120, deadline)
        h2 = _peak_ladder(h1, deadline)
        r2 = R_of(h2)
        if r2 > curR + 3e-13:
            cur, curR = h2, r2
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
                print("  loop %d accept R=%.7f (w=%.0f s=%.3f)" %
                      (it, bestR, width, sigma))
        elif it % 6 == 0:
            # occasionally reset to best to escape drift
            cur, curR = best.copy(), bestR

    # final sharp polish
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 250, deadline)
        hf = _peak_ladder(hf, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _flat_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return np.arange(lo, hi + 1)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    cur = best.copy()
    cur_r = best_r

    # New idea: smooth (beta-annealed) polish of the flat max region to escape
    # the kink of the max, then plain polish. This is the key change: p0064
    # only used plain L-BFGS on the max, which stalls on the non-smooth max.
    def smooth_polish(base, deadline_local, iterations=3):
        h = base.copy()
        r = R_of(h)
        for it in range(iterations):
            if time.process_time() >= deadline_local:
                break
            free = _flat_region(h, tol=0.995)
            beta = 50.0 * (2.0 ** it)
            cand = _lbfgs_block(h, free, maxiter=400, deadline=deadline_local, beta=beta)
            rc = R_of(cand)
            if rc > r:
                h, r = cand, rc
            # finish with plain polish on same region
            cand = _lbfgs_block(h, free, maxiter=400, deadline=deadline_local, beta=0.0)
            rc = R_of(cand)
            if rc > r:
                h, r = cand, rc
        return h, r

    # Phase 1: polish at current resolution with the new smooth approach.
    while time.process_time() < deadline - 6.0:
        before = cur_r
        cand, r = smooth_polish(cur, deadline - 6.0, iterations=3)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        # full positive polish
        cand = _lbfgs_all_pos(cur, maxiter=1500, deadline=deadline - 6.0, beta=0.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if cur_r - before < 1e-9:
            break

    # Phase 2: resolution ladder upward.
    levels = [512000, 768000, 1000000]
    for N in levels:
        if N <= cur.size:
            continue
        if time.process_time() >= deadline - 6.0:
            break
        cand = _prolongate(cur, N)
        cand = _rescale(cand)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        cand = _lbfgs_all_pos(cur, maxiter=600, deadline=deadline - 3.0, beta=0.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # Phase 3: keep improving with smooth+plain polish until deadline.
    while time.process_time() < deadline - 1.0:
        before = cur_r
        cand, r = smooth_polish(cur, deadline - 1.0, iterations=3)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        cand = _lbfgs_all_pos(cur, maxiter=1500, deadline=deadline - 1.0, beta=0.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if cur_r - before < 1e-10:
            break

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------------- new: coordinate-descent style fine polish ----------------

def _cd_polish(h, deadline, passes=3, chunk=None):
    """Block coordinate descent: cycle over contiguous windows, L-BFGS each."""
    n = h.size
    if chunk is None:
        chunk = max(16, n // 64)
    for _ in range(passes):
        if time.process_time() >= deadline - 0.5:
            break
        improved = False
        start = 0
        while start < n:
            if time.process_time() >= deadline - 0.5:
                break
            end = min(n, start + chunk)
            win = np.arange(start, end)
            cand = _lbfgs_block(h, win, 60, deadline, beta=0.0)
            if R_of(cand) > R_of(h) + 1e-15:
                h = cand
                improved = True
            start = end
        if not improved:
            break
    return h


def _refine_resolution(h, deadline, maxN=1000000):
    """Try to upsample the construction (split cells) then re-polish."""
    n = h.size
    if n * 2 > maxN:
        return h, False
    if time.process_time() >= deadline - 2.0:
        return h, False
    # Upsample by linear interpolation of the step profile.
    xs = np.linspace(0.0, 1.0, n, endpoint=False)
    xn = np.linspace(0.0, 1.0, 2 * n, endpoint=False)
    up = np.interp(xn, xs, h)
    up = _rescale(up)
    R0 = R_of(h)
    up = _lbfgs_all_pos(up, 120, deadline - 0.5, beta=1e6)
    up = _lbfgs_all_pos(up, 120, deadline - 0.3, beta=0.0)
    up = _peak_ladder(up, deadline - 0.2, pads=(0.05, 0.03), iters=150)
    return up, R_of(up) > R0 + 1e-12


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size
    amax0 = _argmax_frac(best)

    # ---- Phase R: resolution refinement (upsample + polish) ----
    r_deadline = t0 + budget_seconds * 0.28
    for _ in range(3):
        if time.process_time() >= r_deadline - 2.0:
            break
        up, ok = _refine_resolution(best, r_deadline)
        if ok and up.size <= 1000000:
            if up.size == best.size:
                offer(up, 'refine-same')
            else:
                # accept resolution change only if R improves enough to matter
                r = R_of(up)
                if r > bestR + 1e-13:
                    best, bestR = up.copy(), r
                    N = best.size
                    print("Phase R NEW BEST R=%.9f (N=%d)" % (bestR, N))
                else:
                    if alt_best is None or r > alt_bestR:
                        alt_best, alt_bestR = up.copy(), r
        else:
            break

    N = best.size

    # ---- Phase Q: half-resolution quotient polish ----
    q_deadline = t0 + budget_seconds * 0.42
    q_round = 0
    while time.process_time() < q_deadline - 1.0 and q_round < 3:
        q_round += 1
        c = np.clip(best[0::2], 0, None)
        if c.sum() <= 0:
            break
        c = _rescale(c)
        cR0 = R_of(c)
        c = _lbfgs_all_pos(c, 250, q_deadline, beta=1e5)
        c = _lbfgs_all_pos(c, 250, q_deadline, beta=1e6)
        c = _lbfgs_all_pos(c, 250, q_deadline, beta=1e7)
        c = _lbfgs_all_pos(c, 250, q_deadline, beta=0.0)
        for p in (0.30, 0.15, 0.08):
            if time.process_time() >= q_deadline - 0.5:
                break
            win = _peak_window(c, pad_frac=p, extra=128)
            ct = _lbfgs_block(c, win, 200, q_deadline, beta=1e7)
            if R_of(ct) > R_of(c) + 1e-14:
                c = ct
            ct = _lbfgs_block(c, win, 200, q_deadline, beta=0.0)
            if R_of(ct) > R_of(c) + 1e-14:
                c = ct
        print("Q round=%d half R %.9f -> %.9f" % (q_round, cR0, R_of(c)))
        lifted = np.repeat(c, 2)
        if lifted.size != N:
            if lifted.size > N:
                lifted = lifted[:N]
            else:
                lifted = np.concatenate([lifted, np.zeros(N - lifted.size)])
        lifted = _rescale(lifted)
        lifted = _lbfgs_all_pos(lifted, 200, q_deadline, beta=0.0)
        lifted = _peak_ladder(lifted, q_deadline, pads=(0.06, 0.04), iters=200)
        lR = R_of(lifted)
        print("Q round=%d lifted R=%.9f (best %.9f)" % (q_round, lR, bestR))
        if lR > bestR + 1e-14:
            best, bestR = lifted.copy(), lR
            print("Q round=%d NEW BEST R=%.9f" % (q_round, bestR))
        else:
            if lR > alt_bestR and lifted.size == best.size:
                alt_best, alt_bestR = lifted.copy(), lR
        if time.process_time() >= q_deadline - 1.0:
            break

    print("Phase Q done R=%.9f rounds=%d" % (bestR, q_round))
    N = best.size

    # ---- Phase C: coordinate-descent polish over contiguous chunks ----
    c_deadline = t0 + budget_seconds * 0.60
    cd = _cd_polish(best, c_deadline, passes=2, chunk=max(24, N // 48))
    offer(cd, 'cd-polish')
    print("Phase C done R=%.9f" % bestR)

    # ---- Phase A: peak-window beta ladder ----
    a_deadline = t0 + budget_seconds * 0.72
    for pad in (0.06, 0.05, 0.04, 0.03, 0.02):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 250, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.2f' % pad)
        ht2 = _lbfgs_block(best, win, 250, a_deadline - 0.3, beta=0.0)
        offer(ht2, 'A-plain pad=%.2f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase B: random-window block L-BFGS rounds ----
    b_deadline = deadline - 4.0
    rng = np.random.default_rng(20240607)
    lo_len = max(8, N // 20)
    hi_len = max(lo_len + 1, N // 6)
    rnd = 0
    while time.process_time() < b_deadline:
        rnd += 1
        L = int(rng.integers(lo_len, hi_len + 1))
        c = int(rng.integers(0, N))
        lo = max(0, c - L // 2)
        hi = min(N, lo + L)
        lo = max(0, hi - L)
        win = np.arange(lo, hi)
        cand = best.copy()
        cand = _lbfgs_block(cand, win, 250, b_deadline, beta=1e6)
        cand = _lbfgs_block(cand, win, 250, b_deadline, beta=0.0)
        cand = _peak_ladder(cand, b_deadline, pads=(0.06, 0.04), iters=200)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("B round=%d center=%.3f len=%d R=%.9f (NEW BEST)"
                  % (rnd, c / N, L, bestR))
        else:
            print("B round=%d center=%.3f len=%d R=%.9f" % (rnd, c / N, L, r))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.98
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')
    ht = _cd_polish(best, final_deadline - 0.1, passes=1,
                    chunk=max(16, N // 64))
    offer(ht, 'final-cd')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
import random
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------------- log-space phase ----------------

def _logspace_fun_grad(u, h_full, active):
    h = h_full.copy()
    hu = np.exp(np.clip(u, -30.0, 30.0))
    h[active] = hu
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(u.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(u.size)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    g_h = _backprop(gLf, h) + 2.0 / s
    g_u = g_h[active] * hu
    hh = float(np.dot(hu, hu))
    if hh > 0:
        c = float(np.dot(g_u, hu)) / hh
        g_u = g_u - c * hu
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, g_u


def _lbfgs_logspace(h0, thr, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    mxh = h.max()
    if mxh <= 0:
        return h0
    active = np.flatnonzero(h > thr * mxh)
    if active.size < 4:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    h_full = h.copy()

    def f(u):
        return _logspace_fun_grad(u, h_full, active)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    amax0 = _argmax_frac(best)

    # ---- Phase A: front-loaded peak-window beta ladder (kept) ----
    a_deadline = t0 + budget_seconds * 0.10
    for pad in (0.06, 0.04, 0.025):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.3f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase P: adaptive portfolio (replaces fixed Phase L) ----
    p_deadline = t0 + budget_seconds * 0.90 - 5.0
    slice_len = 4.0

    def move_a():
        win = _peak_window(best, pad_frac=0.05, extra=128)
        return _lbfgs_block(best, win, 250, time.process_time() + slice_len, beta=1e7)

    def move_b():
        win = _peak_window(best, pad_frac=0.03, extra=128)
        return _lbfgs_block(best, win, 250, time.process_time() + slice_len, beta=1e7)

    def move_c():
        return _lbfgs_all_pos(best, 250, time.process_time() + slice_len, beta=0.0)

    def move_d():
        return _lbfgs_all_pos(best, 250, time.process_time() + slice_len, beta=1e8)

    def move_e():
        return _lbfgs_logspace(best, 1e-9, 250, time.process_time() + slice_len)

    moves = [('a', move_a), ('b', move_b), ('c', move_c),
             ('d', move_d), ('e', move_e)]
    gain = {k: 0.0 for k, _ in moves}
    tcost = {k: 0.0 for k, _ in moves}

    def score(k):
        return (gain[k] + 1e-12) / (tcost[k] + 0.5)

    rng = random.Random(12345)
    n_iter = 0
    while time.process_time() < p_deadline:
        if rng.random() < 0.75:
            k, fn = max(moves, key=lambda m: score(m[0]))
        else:
            k, fn = moves[rng.randrange(len(moves))]
        R_before = bestR
        ts = time.process_time()
        try:
            cand = fn()
        except Exception:
            cand = None
        te = time.process_time()
        dt = max(te - ts, 1e-6)
        if cand is not None:
            offer(cand, 'P-%s' % k)
        dR = bestR - R_before
        gain[k] += max(dR, 0.0)
        tcost[k] += dt
        n_iter += 1
        if n_iter % 5 == 0:
            print("P iter %d R=%.9f scores=%s" % (
                n_iter, bestR,
                " ".join("%s:%.2e" % (k, score(k)) for k, _ in moves)))

    print("Phase P done R=%.9f n_iter=%d N=%d" % (bestR, n_iter, best.size))

    # ---- Final polish (kept from p1687) ----
    final_deadline = t0 + budget_seconds * 0.97
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

