    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------------- log-space phase ----------------

def _logspace_fun_grad(u, h_full, active):
    h = h_full.copy()
    hu = np.exp(np.clip(u, -30.0, 30.0))
    h[active] = hu
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(u.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(u.size)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    g_h = _backprop(gLf, h) + 2.0 / s
    g_u = g_h[active] * hu
    hh = float(np.dot(hu, hu))
    if hh > 0:
        c = float(np.dot(g_u, hu)) / hh
        g_u = g_u - c * hu
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, g_u


def _lbfgs_logspace(h0, thr, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    mxh = h.max()
    if mxh <= 0:
        return h0
    active = np.flatnonzero(h > thr * mxh)
    if active.size < 4:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    h_full = h.copy()

    def f(u):
        return _logspace_fun_grad(u, h_full, active)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    amax0 = _argmax_frac(best)

    # ---- Phase A: front-loaded peak-window beta ladder ----
    a_deadline = t0 + budget_seconds * 0.10
    for pad in (0.06, 0.04, 0.025):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.3f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase C: coarse block-sum reoptimization ----
    c_deadline = t0 + budget_seconds * 0.30
    for L in (2, 4, 8):
        if time.process_time() >= c_deadline - 4.0:
            print("Phase C L=%d skipped (time)" % L)
            break
        N = best.size
        Nb = N // L
        if Nb < 8:
            continue
        hc = best[:Nb * L].reshape(Nb, L).sum(axis=1)
        hc = _rescale(hc)
        hc = _lbfgs_all_pos(hc, 400, c_deadline - 3.0, beta=0.0)
        hc = _lbfgs_all_pos(hc, 400, c_deadline - 2.0, beta=1e6)
        h2 = np.repeat(hc, L)
        if h2.size < N:
            h2 = np.concatenate([h2, np.zeros(N - h2.size)])
        else:
            h2 = h2[:N]
        h2 = _rescale(h2)
        h2 = _lbfgs_all_pos(h2, 400, c_deadline - 1.0, beta=0.0)
        h2 = _peak_ladder(h2, c_deadline - 0.5,
                          pads=(0.08, 0.05, 0.03), iters=300)
        r = R_of(h2)
        print("Phase C L=%d lifted R=%.9f dR=%.3e" % (L, r, r - bestR))
        offer(h2, 'C-lift L=%d' % L)
    print("Phase C done R=%.9f" % bestR)

    # ---- Phase L: log-space with exact max projection ----
    l_deadline = t0 + budget_seconds * 0.85
    n_accept = 0
    thrs = (1e-12, 1e-9, 1e-6)
    for rnd, thr in enumerate(thrs):
        if time.process_time() >= l_deadline - 6.0:
            print("L round %d skipped (time)" % rnd)
            break
        R_before = bestR
        n_active = int(np.sum(best > thr * best.max()))
        ht = _lbfgs_logspace(best, thr, 300, l_deadline - 4.0)
        win = _peak_window(ht, pad_frac=0.05, extra=128)
        ht = _lbfgs_block(ht, win, 200, l_deadline - 2.5, beta=1e7)
        ht = _lbfgs_all_pos(ht, 200, l_deadline - 1.0, beta=0.0)
        r = R_of(ht)
        dR = r - R_before
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            n_accept += 1
            print("L round %d thr=%.0e ACCEPT R=%.9f dR=%.3e n_active=%d"
                  % (rnd, thr, bestR, dR, n_active))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            print("L round %d thr=%.0e reject R=%.9f dR=%.3e n_active=%d"
                  % (rnd, thr, r, dR, n_active))
    print("Phase L done R=%.9f n_accept=%d N=%d" % (bestR, n_accept, best.size))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.97
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time

try:
    from scipy.optimize import minimize
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False


def _conv(h):
    return np.convolve(h, h)


def _knots(h):
    L = _conv(h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    L = _knots(h)
    num = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    s = np.sum(h)
    den = s * s * np.max(L)
    if den <= 0:
        return 0.0
    return float(num / den)


def _rescale(h):
    m = np.mean(h)
    if m <= 0:
        return h
    return h / m


def _num_and_dq(h):
    """Return numerator (L2^2 of f*f) and d(num)/dL knot gradient."""
    L = _knots(h)
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    # d/da of (a^2+ab+b^2)/3 = (2a+b)/3 ; d/db = (a+2b)/3
    da = (2.0 * a + b) / 3.0
    db = (a + 2.0 * b) / 3.0
    dq = np.zeros_like(L)
    dq[:-1] += da
    dq[1:] += db
    return num, dq


def _backprop(h, dq):
    """Given gradient wrt knots L (length 2n+1 with zero ends), gradient wrt h."""
    # L = [0, conv(h,h), 0]; interior L[1:-1] = conv
    g = dq[1:-1]  # gradient wrt conv output
    # conv(h,h)[k] = sum_i h[i] h[k-i]; d/dh[j] = 2 * sum_i h[i] g[i+j]
    # = 2 * correlate(h, g)
    n = h.size
    gg = np.convolve(h, g[::-1])[n - 1:2 * n - 1]
    # more robust: use direct formula
    grad = np.zeros(n)
    # grad[j] = 2 * sum_k g[k] h[k-j] over valid
    # use convolution of h with reversed g
    rev = g[::-1]
    full = np.convolve(h, rev)
    # full length n + (2n-1) -1 = 3n-2; index for grad[j] is (n-1)+j
    grad = 2.0 * full[n - 1: 2 * n - 1]
    return grad


def _fun_grad(z):
    h = np.exp(z)
    L = _knots(h)
    num, dq = _num_and_dq(h)
    s = np.sum(h)
    mx = np.max(L)
    den = s * s * mx
    if den <= 0:
        return 1e10, np.zeros_like(z)
    R = num / den
    # dR/dh = dnum/den - num * d(den)/den^2
    gnum = _backprop(h, dq)
    # d(den)/dh = 2 s mx * 1 + s^2 * d(mx)/dh
    k = int(np.argmax(L))
    gmx = np.zeros_like(h)
    # L[k] = conv(h,h)[k-1]; dL[k]/dh[j] = 2 h[k-1-j] if valid
    kk = k - 1
    if 0 <= kk < 2 * h.size - 1:
        for j in range(h.size):
            i = kk - j
            if 0 <= i < h.size:
                gmx[j] = 2.0 * h[i]
    gden = 2.0 * s * mx * np.ones_like(h) + s * s * gmx
    gR = gnum / den - num * gden / (den * den)
    # z = log h, dR/dz = gR * h
    gz = gR * h
    return -R, -gz


def _fun_grad_beta(z, beta):
    h = np.exp(z)
    L = _knots(h)
    num, dq = _num_and_dq(h)
    s = np.sum(h)
    mx = np.max(L)
    den = s * s * mx
    if den <= 0:
        return 1e10, np.zeros_like(z)
    R = num / den
    gnum = _backprop(h, dq)
    k = int(np.argmax(L))
    gmx = np.zeros_like(h)
    kk = k - 1
    if 0 <= kk < 2 * h.size - 1:
        for j in range(h.size):
            i = kk - j
            if 0 <= i < h.size:
                gmx[j] = 2.0 * h[i]
    gden = 2.0 * s * mx * np.ones_like(h) + s * s * gmx
    gR = gnum / den - num * gden / (den * den)
    # beta penalty on sharpness: mx/(s^2) -> encourages flat top
    sharp = mx / (s * s)
    gsharp = gmx / (s * s) - 2.0 * mx * np.ones_like(h) / (s * s * s)
    val = -R + beta * sharp
    gz = -(gR * h) + beta * (gsharp * h)
    return val, gz


def _lbfgs_all_pos(h, iters, deadline, beta=0.0):
    if not _HAVE_SCIPY:
        return h, R_of(h)
    h = np.asarray(h, dtype=float)
    if h.size < 2:
        return h, R_of(h)
    z0 = np.log(np.maximum(h, 1e-12))
    if beta > 0:
        fg = lambda z: _fun_grad_beta(z, beta)
    else:
        fg = _fun_grad
    try:
        res = minimize(fg, z0, jac=True, method='L-BFGS-B',
                       options={'maxiter': iters, 'maxfun': iters * 4,
                                'ftol': 1e-14, 'gtol': 1e-12})
        hh = np.exp(res.x)
    except Exception:
        return h, R_of(h)
    if not np.all(np.isfinite(hh)):
        return h, R_of(h)
    if R_of(hh) > R_of(h):
        return _rescale(hh), R_of(hh)
    return h, R_of(h)


def _peak_window(h):
    L = _conv(h)
    k = int(np.argmax(L))
    return k / 2.0


def _lbfgs_block(h, pad, iters, deadline, beta=1e4):
    if not _HAVE_SCIPY:
        return h, R_of(h)
    h = np.asarray(h, dtype=float)
    n = h.size
    c = _peak_window(h)
    w = max(2, int(pad * n))
    lo = max(0, int(c - w))
    hi = min(n, int(c + w) + 1)
    if hi - lo < 2:
        return h, R_of(h)
    sub = h[lo:hi].copy()

    def fg(z):
        hh = h.copy()
        hh[lo:hi] = np.exp(z)
        L = _knots(hh)
        num, dq = _num_and_dq(hh)
        s = np.sum(hh)
        mx = np.max(L)
        den = s * s * mx
        if den <= 0:
            return 1e10, np.zeros_like(z)
        R = num / den
        gnum = _backprop(hh, dq)
        k = int(np.argmax(L))
        gmx = np.zeros_like(hh)
        kk = k - 1
        if 0 <= kk < 2 * hh.size - 1:
            for j in range(hh.size):
                i = kk - j
                if 0 <= i < hh.size:
                    gmx[j] = 2.0 * hh[i]
        gden = 2.0 * s * mx * np.ones_like(hh) + s * s * gmx
        gR = gnum / den - num * gden / (den * den)
        gz = (gR * hh)[lo:hi]
        return -R, -gz

    z0 = np.log(np.maximum(sub, 1e-12))
    try:
        res = minimize(fg, z0, jac=True, method='L-BFGS-B',
                       options={'maxiter': iters, 'maxfun': iters * 4,
                                'ftol': 1e-14, 'gtol': 1e-12})
        hh = h.copy()
        hh[lo:hi] = np.exp(res.x)
    except Exception:
        return h, R_of(h)
    if not np.all(np.isfinite(hh)):
        return h, R_of(h)
    if R_of(hh) > R_of(h):
        return _rescale(hh), R_of(hh)
    return h, R_of(h)


def _peak_ladder(h, pads, iters, deadline):
    best = h
    bestR = R_of(h)
    for pad in pads:
        if time.process_time() > deadline:
            break
        hh, r = _lbfgs_block(best, pad, iters, deadline, beta=1e4)
        if r > bestR:
            best, bestR = hh, r
    return best, bestR


def _polish(h, deadline, iters_full=600, iters_beta=300):
    best = h
    bestR = R_of(h)
    if time.process_time() > deadline:
        return best, bestR
    hh, r = _lbfgs_all_pos(best, iters_full, deadline, beta=0.0)
    if r > bestR:
        best, bestR = hh, r
    for beta in (1e4, 1e5, 1e6, 1e7):
        if time.process_time() > deadline:
            break
        hh, r = _lbfgs_all_pos(best, iters_beta, deadline, beta=beta)
        if r > bestR:
            best, bestR = hh, r
    if time.process_time() < deadline:
        hh, r = _peak_ladder(best, (0.12, 0.08, 0.05, 0.03), 300, deadline)
        if r > bestR:
            best, bestR = hh, r
    if time.process_time() < deadline:
        hh, r = _lbfgs_all_pos(best, iters_full, deadline, beta=0.0)
        if r > bestR:
            best, bestR = hh, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + 0.95 * budget_seconds
    soft = t0 + 0.90 * budget_seconds - 5.0

    if start is None:
        # fallback: simple comb
        h = np.ones(50)
    else:
        h = np.clip(np.asarray(start, dtype=float), 0.0, None)
        if h.size == 0 or np.all(h <= 0):
            h = np.ones(50)

    # Lift to N=1600 by exact duplication
    h = np.repeat(h, 32)
    h = _rescale(h)
    best = h.copy()
    bestR = R_of(best)
    print("lifted N=%d R=%.6f" % (best.size, bestR))

    best, bestR = _polish(best, soft)
    print("after first polish R=%.6f N=%d" % (bestR, best.size))

    while time.process_time() < soft and best.size <= 25600:
        h2 = np.repeat(best, 2)
        h2 = _rescale(h2)
        r2 = R_of(h2)
        cand, candR = _polish(h2, soft)
        if candR > bestR:
            best, bestR = cand, candR
            print("lift N=%d R=%.6f" % (best.size, bestR))
        else:
            print("lift N=%d no gain (%.6f)" % (h2.size, candR))
            # keep going but break if no improvement and size large
            if h2.size > 12800:
                break

    # Final peak ladder and polish
    if time.process_time() < hard:
        hh, r = _peak_ladder(best, (0.10, 0.06, 0.04, 0.02), 300, hard)
        if r > bestR:
            best, bestR = hh, r
