        if r > bestR:
            best, bestR = hh, r

    L = _conv(best)
    mx = np.max(L)
    frac = np.mean(L > 0.99 * mx)
    print("final R=%.6f near-max=%.3f%% N=%d" % (bestR, 100 * frac, best.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = R_of(s)
        if sR >= bestR:
            return {"best": s, "alternative": _rescale(best)}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    """Smoothed max via softmax, so gradient flows to all near-peak knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)
    base = best.copy()
    base_r = best_r

    def try_improve(cand):
        nonlocal best, best_r
        if cand is None:
            return False
        r = R_of(cand)
        if r > best_r + 1e-13:
            best, best_r = cand.copy(), r
            return True
        return False

    # Phase A: smoothed-max global polish (helps escape flat peak plateaus)
    if time.process_time() < deadline - 1.0:
        sub = min(deadline - 0.5, time.process_time() + (deadline - time.process_time()) * 0.30)
        try_improve(_lbfgs_block(best, np.arange(best.size), 4000, sub, beta=1e6))
        if time.process_time() < sub - 0.5:
            try_improve(_lbfgs_block(best, np.arange(best.size), 4000, sub, beta=1e7))

    # Phase B: log-param global polish
    if time.process_time() < deadline - 1.0:
        sub = min(deadline - 0.5, time.process_time() + (deadline - time.process_time()) * 0.35)
        try_improve(_lbfgs_log(best, 6000, sub))

    # Phase C: peak-window ladder with decreasing pad, smoothed-max
    for pad in (0.30, 0.18, 0.10, 0.06, 0.03):
        if time.process_time() >= deadline - 1.0:
            break
        sub = min(deadline - 0.8, time.process_time() + (deadline - time.process_time()) * 0.35)
        win = _peak_window(best, pad_frac=pad, extra=64)
        cand = _lbfgs_block(best, win, 800, sub, beta=1e7)
        if R_of(cand) > R_of(best) + 1e-14:
            best = cand
        cand2 = _lbfgs_block(best, win, 800, sub, beta=0.0)
        try_improve(cand2)

    # Phase D: prolongation to finer grid and re-optimize (finer resolution -> higher R)
    while (time.process_time() < deadline - 5.0
           and best.size < 200000):
        N_big = min(200000, best.size * 2)
        h_big = _prolongate(best, N_big)
        sub = min(deadline - 3.0,
                  time.process_time() + (deadline - time.process_time()) * 0.55)
        cand = _lbfgs_log(h_big, 4000, sub)
        r = R_of(cand)
        if r > best_r + 1e-13:
            best, best_r = cand, r
            # quick smoothed polish on the finer grid
            sub2 = min(deadline - 2.0, time.process_time() + (deadline - time.process_time()) * 0.4)
            win = _peak_window(best, pad_frac=0.15, extra=128)
            cand2 = _lbfgs_block(best, win, 600, sub2, beta=1e7)
            try_improve(cand2)
        else:
            break

    # Phase E: final full-block polish
    if time.process_time() < deadline - 0.8:
        try_improve(_lbfgs_block(best, np.arange(best.size), 4000, deadline - 0.4, beta=0.0))

    if base_r >= best_r:
        return {"best": base, "alternative": best}
    return {"best": best, "alternative": base}

