        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size

    # ---- Phase A (NEW): smoothing escape - blur, re-polish at several scales ----
    # The sharp start sits in a local minimum. Blurring at multiple scales
    # followed by re-polish explores genuinely different shapes.
    blur_deadline = t0 + budget_seconds * 0.55
    for k in (3, 8, 20, 50, 120):
        if time.process_time() >= blur_deadline - 1.5:
            break
        hb = _blur(best, k)
        hb = _rescale(hb)
        hb = _polish_ladder(hb, blur_deadline - 0.5,
                            betas=(1e5, 1e6, 1e7, 0.0), iters=300)
        hb = _peak_ladder(hb, blur_deadline - 0.4,
                          pads=(0.20, 0.10, 0.06), iters=300)
        offer(hb, 'blur%d' % k)

    # ---- Phase B: N-perturbation rounds around best N ----
    perturb_deadline = t0 + budget_seconds * 0.82
    N0 = best.size
    N_candidates = [N0 + 1, N0 - 1, N0 - 3, N0 + 5, N0 + 3, N0 - 5]
    N_candidates = [n for n in N_candidates if 1 <= n <= 1000000]
    for Np in N_candidates:
        if time.process_time() >= perturb_deadline - 1.0:
            break
        cand = _resample_to(best, Np)
        cand = _rescale(cand)
        cand = _polish_ladder(cand, perturb_deadline - 0.5,
                              betas=(1e6, 1e7, 0.0), iters=350)
        cand = _peak_ladder(cand, perturb_deadline - 0.4,
                            pads=(0.10, 0.06, 0.04), iters=300)
        offer(cand, 'Npert%d' % Np)

    # ---- Phase C: half-resolution lift (cheap, different basin) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.90
        c = _polish_ladder(c, half_deadline, betas=(1e6, 1e7, 0.0), iters=250)
        c = _peak_ladder(c, half_deadline, pads=(0.15, 0.10, 0.06), iters=300)
        h_lift = _rescale(np.repeat(c, 2))
        h_lift = _polish_ladder(h_lift, deadline - 0.5, betas=(1e6, 1e7), iters=250)
        offer(h_lift, 'lift')

    # ---- Final polish ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 0.0), iters=250)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.06, 0.04), iters=300)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d)"
          % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _block_sum(h, k):
    n = h.size
    nb = n // k
    if nb < 1:
        return h.copy()
    trimmed = h[:nb * k].reshape(nb, k)
    return trimmed.sum(axis=1)


def _prolongate(coarse, N, rng):
    k = max(1, int(round(N / max(1, coarse.size))))
    full = np.repeat(coarse, k)
    if full.size < N:
        full = np.concatenate([full, np.full(N - full.size, full[-1])])
    elif full.size > N:
        full = full[:N]
    # light smoothing
    if full.size > 3:
        ker = np.array([0.25, 0.5, 0.25])
        full = np.convolve(full, ker, mode='same')
    return _rescale(full)


def _edit_zero_pattern(coarse, rng):
    c = coarse.copy()
    active = np.flatnonzero(c > 0)
    zeros = np.flatnonzero(c <= 0)
    if active.size < 2 or zeros.size < 1:
        return c
    m = rng.integers(1, min(7, active.size + 1))
    order = active[np.argsort(c[active])]
    kill = order[:m]
    c[kill] = 0.0
    rev = rng.choice(zeros, size=min(m, zeros.size), replace=False)
    for idx in rev:
        lo = max(0, idx - 2); hi = min(c.size, idx + 3)
        neigh = c[lo:hi]
        nz = neigh[neigh > 0]
        c[idx] = float(nz.mean()) if nz.size > 0 else float(c.mean())
    return c


def _edit_window(coarse, rng):
    c = coarse.copy()
    n = c.size
    w = int(rng.integers(max(1, n // 10), max(2, n // 2) + 1))
    w = min(w, n)
    lo = int(rng.integers(0, n - w + 1))
    amp = rng.uniform(0.15, 0.7)
    fac = np.exp(amp * rng.standard_normal(w))
    c[lo:lo + w] *= fac
    return c


def _edit_half_scale(coarse, rng):
    c = coarse.copy()
    n = c.size
    half = n // 2
    if rng.random() < 0.5:
        seg = slice(0, half)
    else:
        seg = slice(half, n)
    c[seg] *= rng.uniform(0.9, 1.1)
    return c


def _coarse_polish(c, deadline, rng):
    if time.process_time() >= deadline - 0.3:
        return c, R_of(c)
    c = _rescale(np.clip(c, 0, None))
    if c.sum() <= 0:
        return c, 0.0
    c = _lbfgs_all_pos(c, 60, deadline - 0.1, beta=0.0)
    if time.process_time() < deadline - 0.15:
        win = _peak_window(c, pad_frac=0.15, extra=32)
        ct = _lbfgs_block(c, win, 120, deadline - 0.05, beta=1e6)
        if R_of(ct) > R_of(c):
            c = ct
    return c, R_of(c)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Stage A: coarse screening pool ----
    stageA_end = t0 + budget_seconds * 0.60
    k = 8
    coarse = _block_sum(best, k)
    coarse = _rescale(coarse)
    coarseR0 = R_of(coarse)
    print("coarse R=%.9f (Nc=%d)" % (coarseR0, coarse.size))

    pool = []  # list of (coarseR, coarse_vec, edit_type)
    n_candidates = 250
    edit_types = ['zero', 'window', 'half']
    for ci in range(n_candidates):
        if time.process_time() >= stageA_end - 0.5:
            break
        et = edit_types[ci % 3]
        if et == 'zero':
            cand = _edit_zero_pattern(coarse, rng)
        elif et == 'window':
            cand = _edit_window(coarse, rng)
        else:
            cand = _edit_half_scale(coarse, rng)
        cand = _rescale(np.clip(cand, 0, None))
        if cand.sum() <= 0:
            continue
        # per-candidate small time slice
        cand_deadline = min(stageA_end - 0.3,
                            time.process_time() + max(0.05, (stageA_end - time.process_time()) / max(1, n_candidates - ci)))
        cc, cr = _coarse_polish(cand, cand_deadline, rng)
        pool.append((cr, cc, et))

    pool.sort(key=lambda x: -x[0])
    top = pool[:8]
    print("pool built: %d candidates, top coarse R=%.9f" % (len(pool), top[0][0] if top else 0.0))

    # ---- Stage B: promote top 8 to full N ----
    stageB_end = t0 + budget_seconds * 0.92
    promoted = []
    for rank, (cr, cc, et) in enumerate(top):
        if time.process_time() >= stageB_end - 0.5:
            break
        cap = min(stageB_end - 0.3, time.process_time() + 3.5)
        full = _prolongate(cc, N, rng)
        fullR0 = R_of(full)
        # full polish
        ht = _lbfgs_all_pos(full, 300, cap - 0.3, beta=1e8)
        if time.process_time() < cap - 0.3:
            ht2 = _lbfgs_all_pos(ht, 300, cap - 0.2, beta=0.0)
            if R_of(ht2) > R_of(ht):
                ht = ht2
        if time.process_time() < cap - 0.3:
            ht3 = _peak_ladder(ht, cap - 0.1, pads=(0.06, 0.03), iters=150)
            if R_of(ht3) > R_of(ht):
                ht = ht3
        r = R_of(ht)
        dR = r - bestR
        promoted.append((rank, cr, r, dR, et))
        print("promote #%d et=%s coarseR=%.9f fullR=%.9f dR=%.3e" %
              (rank, et, cr, r, dR))
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("  ACCEPT R=%.9f" % bestR)

    # ---- Stage C: final full polish on best ----
    stageC_end = t0 + budget_seconds * 0.97
    ht = _lbfgs_all_pos(best, 2000, stageC_end - 0.5, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("StageC beta0 ACCEPT R=%.9f" % bestR)
    ht = _peak_ladder(best, stageC_end - 0.2, pads=(0.05, 0.03), iters=200)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("StageC peak ACCEPT R=%.9f" % bestR)

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best), amax1, _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = start_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _perturb_zero_set(h, rng, m):
    h2 = h.copy()
    n = h2.size
    active = np.flatnonzero(h2 > 0)
    zeros = np.flatnonzero(h2 <= 0)
    if active.size < m + 4 or zeros.size < m:
        return None
    order = active[np.argsort(h2[active])]
    pool = order[:min(2000, order.size)]
    if pool.size < m:
        return None
    rem = rng.choice(pool, size=m, replace=False)
    h2[rem] = 0.0
    rev = rng.choice(zeros, size=m, replace=False)
    active_now = np.flatnonzero(h2 > 0)
    med = np.median(h2[active_now]) if active_now.size > 0 else 1.0
    for c in rev:
        lo = c - 1
        while lo >= 0 and h2[lo] <= 0 and c - lo <= 8:
            lo -= 1
        hi = c + 1
        while hi < n and h2[hi] <= 0 and hi - c <= 8:
            hi += 1
        vals = []
        if lo >= 0 and h2[lo] > 0:
            vals.append(h2[lo])
        if hi < n and h2[hi] > 0:
            vals.append(h2[hi])
        if vals:
            h2[c] = float(np.mean(vals))
        else:
            h2[c] = med
    return _rescale(h2)


# ---------- new helpers for the coarse V-cycle ----------

def _coarsen(h, k):
    n = h.size
    nblk = n // k
    if nblk < 8:
        return h.copy()
    hh = h[:nblk * k].reshape(nblk, k)
    c = hh.sum(axis=1)
    return _rescale(c)


def _prolongate(c, k, n_target):
    h = np.repeat(c, k)
    # light 3-tap smoothing
    if h.size >= 3:
        hs = h.copy()
        hs[1:-1] = 0.25 * h[:-2] + 0.5 * h[1:-1] + 0.25 * h[2:]
        h = hs
    if h.size < n_target:
        h = np.concatenate([h, np.zeros(n_target - h.size)])
    elif h.size > n_target:
        h = h[:n_target]
    return _rescale(np.clip(h, 0, None))


def _coarse_move(c, rng):
    """Return (candidate, label) or (None, None)."""
    n = c.size
    if n < 16:
        return None, None
    kind = rng.integers(0, 3)
    c2 = c.copy()
    if kind == 0:
        # jitter a contiguous window
        wfrac = rng.uniform(0.05, 0.40)
        w = max(3, int(wfrac * n))
        start = int(rng.integers(0, max(1, n - w)))
        sigma = rng.uniform(0.1, 0.6)
        noise = np.exp(sigma * rng.standard_normal(w))
        c2[start:start + w] *= noise
        label = "jitter"
    elif kind == 1:
        # zero-edit
        m = int(rng.integers(1, 4))
        active = np.flatnonzero(c2 > 0)
        zeros = np.flatnonzero(c2 <= 0)
        if active.size < m + 4 or zeros.size < m:
            return None, None
        order = active[np.argsort(c2[active])]
        pool = order[:min(500, order.size)]
        if pool.size < m:
            return None, None
        rem = rng.choice(pool, size=m, replace=False)
        c2[rem] = 0.0
        rev = rng.choice(zeros, size=m, replace=False)
        for cc in rev:
            lo = cc - 1
            while lo >= 0 and c2[lo] <= 0 and cc - lo <= 6:
                lo -= 1
            hi = cc + 1
            while hi < n and c2[hi] <= 0 and hi - cc <= 6:
                hi += 1
            vals = []
            if lo >= 0 and c2[lo] > 0:
                vals.append(c2[lo])
            if hi < n and c2[hi] > 0:
                vals.append(c2[hi])
            if vals:
                c2[cc] = float(np.mean(vals))
            else:
                c2[cc] = float(np.median(c2[c2 > 0])) if np.any(c2 > 0) else 1.0
        label = "zero-edit"
    else:
        # low-frequency cosine tilt
        amp = rng.uniform(0.05, 0.3)
        freq = rng.uniform(0.5, 2.5)
        phase = rng.uniform(0, 2 * np.pi)
        x = np.linspace(0, 1, n)
        tilt = 1.0 + amp * np.cos(2 * np.pi * freq * x + phase)
        c2 *= tilt
        label = "tilt"
    c2 = _rescale(np.clip(c2, 0, None))
    if c2.sum() <= 0:
        return None, None
    return c2, label


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f)"
          % (bestR, best.size, _zero_frac(best)))

    amax0 = _argmax_frac(best)
    rng = np.random.default_rng(987654321)

    # coarse V-cycle loop
    cycle_deadline = t0 + budget_seconds * 0.80
    k = 8
    best_coarse_R = R_of(_coarsen(best, k))
    cycle = 0
    prolonged_gain = 0.0
    prolonged_label = None
    n_candidates = 0
    while time.process_time() < cycle_deadline - 1.0:
        cycle += 1
        n_candidates += 1
        c = _coarsen(best, k)
        cR_before = R_of(c)
        cand, label = _coarse_move(c, rng)
        if cand is None:
            continue
        # coarse L-BFGS exact-R, short
        cd = time.process_time() + 0.35
        ct = _lbfgs_all_pos(cand, 250, cd, beta=0.0)
        if time.process_time() < cd - 0.1:
            # coarse peak-window block polish
            win = _peak_window(ct, pad_frac=0.10, extra=64)
            ct2 = _lbfgs_block(ct, win, 150, cd, beta=1e7)
            if R_of(ct2) > R_of(ct):
                ct = ct2
        cR = R_of(ct)
        if cR < cR_before - 1e-9:
            # coarse got worse; still try prolongation only if close
            if cR < best_coarse_R - 1e-6:
                if cycle % 5 == 0:
                    print("cycle %d %s coarse R=%.9f (reject, dR=%.3e)"
                          % (cycle, label, cR, cR - cR_before))
                continue
        # prolongate and full polish
        N = best.size
        hf = _prolongate(ct, k, N)
        fd = time.process_time() + 4.0
        hf = _lbfgs_all_pos(hf, 400, fd, beta=1e8)
        if time.process_time() < fd - 0.3:
            hf = _lbfgs_all_pos(hf, 400, fd, beta=0.0)
        if time.process_time() < fd - 0.3:
            hf = _peak_ladder(hf, fd, pads=(0.05, 0.03), iters=200)
        r = R_of(hf)
        dR = r - bestR
        if r > bestR + 1e-15:
            best, bestR = hf.copy(), r
            best_coarse_R = max(best_coarse_R, cR)
            if dR > prolonged_gain:
                prolonged_gain = dR
                prolonged_label = label
            print("cycle %d %s ACCEPT full R=%.9f dR=%.3e coarseR=%.9f zero_frac=%.4f"
                  % (cycle, label, bestR, dR, cR, _zero_frac(best)))
        else:
            if cycle % 5 == 0:
                print("cycle %d %s reject full R=%.9f dR=%.3e coarseR=%.9f"
                      % (cycle, label, r, dR, cR))

    print("coarse V-cycle done: cycles=%d prolonged_gain=%.3e (%s)"
          % (cycle, prolonged_gain, prolonged_label))

    # final full polish
    fd = t0 + budget_seconds * 0.97
    ht = _lbfgs_all_pos(best, 600, fd, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("FINAL beta0 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _lbfgs_all_pos(best, 400, fd, beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL beta8 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _peak_ladder(best, fd, pads=(0.05, 0.03), iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL peak ACCEPT R=%.9f" % bestR)

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f, cycles=%d)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best), cycle))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = start_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _resample(h, N2):
    n = len(h)
    x_old = np.linspace(0, 1, n, endpoint=False) + 0.5 / n
    x_new = np.linspace(0, 1, N2, endpoint=False) + 0.5 / N2
    h2 = np.interp(x_new, x_old, h, left=0.0, right=0.0)
    s1 = np.sum(h)
    s2 = np.sum(h2)
    if s2 > 0:
        h2 *= s1 / s2
    return h2


def _escalate(h, N2):
    n = len(h)
    if N2 == n:
        return h.copy()
    if N2 % n == 0:
        k = N2 // n
        return np.repeat(h, k) / k
    return _resample(h, N2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best_h = None
    best_R = -1.0
    if start is not None:
        s0 = np.asarray(start, dtype=float)
        best_h = s0.copy()
        best_R = R_of(best_h)

    # If we have a start, first try to refine it directly at its own N
    if best_h is not None:
        h = best_h
        # sharpen peak via tight window
        h = _peak_ladder(h, deadline)
        Rh = R_of(h)
        if Rh > best_R:
            best_R = Rh
            best_h = h
        # full polish
        h2 = _lbfgs_all_pos(h, 300, deadline, beta=1e8)
        R2 = R_of(h2)
        if R2 > best_R:
            best_R = R2
            best_h = h2
        print(f"start polish R={best_R:.6f}")

    # Escalation ladder: grow the best construction to higher N and polish there
    Ns = [2048, 4096, 8192, 16384]
    cur = best_h if best_h is not None else np.ones(1024)
    for N2 in Ns:
        if time.process_time() > deadline - 2.0:
            break
        h2 = _escalate(cur, N2)
        R2 = R_of(h2)
        # polish at new resolution
        h3 = _lbfgs_all_pos(h2, 200, deadline, beta=1e8)
        R3 = R_of(h3)
        if R3 > R2:
            h2, R2 = h3, R3
        h4 = _peak_ladder(h2, deadline)
        R4 = R_of(h4)
        if R4 > R2:
            h2, R2 = h4, R4
        cur = h2
        if R2 > best_R:
            best_R = R2
            best_h = h2
        print(f"ladder N={N2} R={best_R:.6f}")

    # Final long polish loop on best_h at its native resolution
    while time.process_time() < deadline - 1.0:
        improved = False
        for beta in (1e7, 1e8, 1e9, 0.0):
            if time.process_time() > deadline - 1.0:
                break
            ht = _lbfgs_all_pos(best_h, 200, deadline, beta=beta)
            Rt = R_of(ht)
            if Rt > best_R + 1e-13:
                best_R = Rt
                best_h = ht
                improved = True
        hp = _peak_ladder(best_h, deadline)
        Rp = R_of(hp)
        if Rp > best_R + 1e-13:
            best_R = Rp
            best_h = hp
            improved = True
        if not improved:
            break

    if best_h is None:
        best_h = np.ones(64)

    print(f"final best_R={R_of(best_h):.6f}")
    return {"best": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Main improvement loop: progressively tighter p-norm smoothing ----
    # Use a ladder of p values from moderate to very large to push maximiser
    # toward a flatter top, then sharp maximisation on the peak.
    p_ladder = (4, 8, 16, 32, 64, 128, 256, 512, 1024)

    def try_log(h, fg, maxiter, tcap):
        if time.process_time() >= deadline - 1.5:
            return h, R_of(h)
        sub = min(deadline - 1.5, time.process_time() + tcap)
        hn = _lbfgs_log(h, maxiter, sub, fg=fg)
        rn = R_of(hn)
        return hn, rn

    # Phase 1: p-ladder to build a wide flat top
    for p in p_ladder:
        if time.process_time() >= deadline * 0 + t0 + budget_seconds * 0.75 - 2.0:
            break
        fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
        hn, rn = try_log(bestH, fg, 80, 4.0)
        if rn > bestRH + 1e-14:
            bestH, bestRH = hn, rn
        print("  p=%d R=%.7f" % (p, bestRH))

    # Phase 2: alternate sharp global and peak-window polish until budget out
    it = 0
    while time.process_time() < deadline - 2.0:
        prev = bestRH
        # sharp global (log-param, handles zeros)
        if time.process_time() < deadline - 2.0:
            sub = min(deadline - 1.5, time.process_time() + 5.0)
            hn = _lbfgs_log(bestH, 200, sub)
            rn = R_of(hn)
            if rn > bestRH + 1e-14:
                bestH, bestRH = hn, rn
        # peak-window with p=64 smoothing to widen top
        if time.process_time() < deadline - 2.0:
            lo, hi = _peak_region(bestH, 0.998)
            span = hi - lo
            pad = max(128, int(span * 0.30))
            lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
            if hi2 > lo2:
                free = np.arange(lo2, hi2 + 1)
                fg = (lambda hh: _fun_grad_pnorm(hh, 64))
                sub = min(deadline - 1.5, time.process_time() + 4.0)
                hn = _lbfgs_block(bestH, free, 200, sub, fg=fg)
                rn = R_of(hn)
                if rn > bestRH + 1e-14:
                    bestH, bestRH = hn, rn
        # sharp peak-window
        if time.process_time() < deadline - 2.0:
            lo, hi = _peak_region(bestH, 0.999)
            span = hi - lo
            pad = max(64, int(span * 0.15))
            lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
            if hi2 > lo2:
                free = np.arange(lo2, hi2 + 1)
                sub = min(deadline - 1.5, time.process_time() + 4.0)
                hn = _lbfgs_block(bestH, free, 200, sub)
                rn = R_of(hn)
                if rn > bestRH + 1e-14:
                    bestH, bestRH = hn, rn
        it += 1
        print("  round %d R=%.7f" % (it, bestRH))
        if bestRH <= prev + 1e-14:
            # small jitter in log-space to escape local plateau
            if time.process_time() < deadline - 3.0:
                rng = np.random.default_rng(1000 + it)
                hh = bestH.copy()
                nz = hh > 0
                hh[nz] *= np.exp(rng.normal(0.0, 0.02, size=int(nz.sum())))
                hh = _rescale(hh)
                rh = R_of(hh)
                if rh > bestRH - 1e-4:
                    bestH, bestRH = hh, rh
            else:
                break

    mx, m, near = _stats(bestH)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        return bestH
    return {"best": start_best,
            "alternative": bestH if bestRH > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _upsample(h, factor):
    n = h.size
    m = n * factor
    x = (np.arange(m) + 0.5) / factor
    return np.interp(x, np.arange(n) + 0.5, h, left=h[0], right=h[-1])


def _refine_support(h, deadline, maxiter=200):
    cur = h
    curR = R_of(h)
    for beta in (1e5, 1e6, 1e7, 1e8, 1e9, 1e10):
        if time.process_time() >= deadline - 0.5:
            break
        hb = _lbfgs_log(cur, maxiter, deadline, beta=beta)
        rb = R_of(hb)
        if rb > curR + 1e-13:
            cur, curR = hb, rb
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(cur, maxiter, deadline)
        rs = R_of(hs)
        if rs > curR + 1e-13:
            cur, curR = hs, rs
    return cur, curR


def _perturb_restart(h, rng, scale=0.05, frac=0.3):
    """Randomly perturb a fraction of the heights to escape a local max."""
    h2 = h.copy()
    n = h2.size
    k = max(1, int(frac * n))
    idx = rng.choice(n, size=k, replace=False)
    noise = np.exp(rng.normal(0.0, scale, size=k))
    h2[idx] = h2[idx] * noise
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Upsample once early to a finer grid.
    if best.size * 2 <= 1000000 and time.process_time() < deadline - 20.0:
        up = _rescale(_upsample(best, 2))
        ru = R_of(up)
        print("upsample x2 -> R=%.7f (N=%d)" % (ru, up.size))
        if ru > bestR - 1e-6:
            best, bestR = up, ru
            hb, rb = _refine_support(best, deadline, maxiter=200)
            if rb > bestR:
                best, bestR = hb, rb
            print("after upsample refine R=%.7f" % bestR)

    schedule = [
        (0.05, 64, 0.0),
        (0.05, 64, 1e6),
        (0.10, 128, 1e7),
        (0.15, 256, 1e8),
        (0.25, 512, 1e9),
        (0.40, 1024, 1e9),
        (0.60, 2048, 1e10),
        (0.90, 4096, 1e10),
    ]

    cur = best.copy()
    curR = bestR
    cycle = 0
    rng = np.random.default_rng(12345)
    while time.process_time() < deadline - 2.0:
        cycle += 1
        for frac, extra, beta in schedule:
            if time.process_time() >= deadline - 2.0:
                break
            hw = _window_polish_peak(cur, deadline, frac, extra,
                                     maxiter=300, beta=beta)
            rw = R_of(hw)
            if rw > curR + 1e-13:
                cur, curR = hw, rw
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR

        if time.process_time() < deadline - 6.0:
            hb, rb = _refine_support(best, min(deadline - 2.0, time.process_time() + 6.0),
                                     maxiter=200)
            if rb > bestR + 1e-13:
                best, bestR = hb, rb
                cur, curR = hb.copy(), rb

        zf = 100.0 * np.mean(best <= 0)
        am = int(np.argmax(_knots(best)))
        print("cycle %d R=%.7f argmax=%d zeros=%.1f%%" %
              (cycle, bestR, am, zf))

        # NEW: perturb-restart to escape local maxima. Try a few perturbations
        # of the best point; if one improves, adopt it as the new cur.
        if time.process_time() < deadline - 8.0 and cycle % 2 == 0:
            for scale in (0.03, 0.08):
                if time.process_time() >= deadline - 8.0:
                    break
                hp = _perturb_restart(best, rng, scale=scale, frac=0.25)
                hb, rb = _refine_support(
                    hp, min(deadline - 4.0, time.process_time() + 3.0),
                    maxiter=150)
                if rb > bestR + 1e-12:
                    best, bestR = hb, rb
                    cur, curR = hb.copy(), rb
                    print("perturb(%.2f) improved R=%.7f" % (scale, bestR))
                    break

        if best.size * 2 <= 1000000 and time.process_time() < deadline - 15.0:
            up = _rescale(_upsample(best, 2))
            ru = R_of(up)
            if ru > bestR - 1e-6:
                print("upsample x2 -> R=%.7f (N=%d)" % (ru, up.size))
                best, bestR = up, ru
                cur, curR = up.copy(), ru
                hb, rb = _refine_support(best, deadline, maxiter=200)
                if rb > bestR:
                    best, bestR = hb, rb
                    cur, curR = hb.copy(), rb

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

