    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def lift3(h, sigma, rng):
    n = h.size
    u = rng.standard_normal((n, 3)) * sigma
    u -= u.mean(axis=1, keepdims=True)
    sub = (h[:, None] / 3.0) * np.exp(u)
    return _rescale(sub.ravel())


