                  % (p, bestR, _nearmax_frac(best)))
        else:
            print("pnorm p=%d no gain (R=%.9f vs %.9f)" % (p, r, bestR))

    # p-norm peak-window polish
    if time.process_time() < pnorm_deadline - 1.0:
        ht = _peak_ladder_p(best, pnorm_deadline, 128,
                            pads=(0.08, 0.05, 0.03), iters=250)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("pnorm peak NEW BEST R=%.9f nearmax5=%.4f"
                  % (bestR, _nearmax_frac(best)))

    # ---- final hard-max polish ----
    fd = t0 + budget_seconds * 0.90
    ht = _lbfgs_all_pos(best, 800, fd, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("FINAL beta0 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _lbfgs_all_pos(best, 400, fd, beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL beta8 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _peak_ladder(best, fd, pads=(0.05, 0.03), iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _densify(h, c):
    dense = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    act = dense > 0
    if not np.any(act):
        return dense
    lvl = c * dense[act].mean()
    dense[~act] = lvl
    return _rescale(dense)


def _upsample(h, factor=2):
    """Upsample h by factor via linear interpolation to give the optimiser
    more degrees of freedom on the SAME support."""
    n = h.size
    if n < 4:
        return h
    xo = np.arange(n * factor, dtype=float) / factor
    xi = np.arange(n, dtype=float)
    up = np.interp(xo, xi, h)
    return _rescale(up)


def _peak_ladder(h, deadline, pads=(0.15, 0.08, 0.05, 0.03, 0.02),
                 iters=300, beta=1e7):
    best = h
    bestR = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, iters, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_bestR = bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(cand, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR, origin = cand, r, tag
            print("  NEW BEST %s R=%.9f" % (tag, bestR))
        elif r > alt_bestR and r > start_bestR + 1e-14:
            alt_best, alt_bestR = cand, r
        return r

    # (1) refine the peak window on the start as-is
    if time.process_time() < deadline - 1.0:
        ht, r = _peak_ladder(best, min(deadline - 0.5,
                                       time.process_time() + 8.0),
                             pads=(0.20, 0.10, 0.05), iters=300)
        consider(ht, 'pk0')

    # (2) key new idea: upsample the start to double resolution and re-optimise
    #     the peak window.  Doubling resolution lets the optimiser sharpen the
    #     near-plateau region into a slightly better shape without changing
    #     the coarse support (so the seed stays competitive).
    if time.process_time() < deadline - 3.0:
        up = _upsample(best, 2)
        ht, r = _peak_ladder(up, min(deadline - 1.0,
                                     time.process_time() + 12.0),
                             pads=(0.15, 0.08, 0.04), iters=350)
        consider(ht, 'up2pk')

    # (3) densification sweep (from p1274) - only if time remains
    for c in [0.002, 0.01, 0.03]:
        if time.process_time() >= deadline - 3.0:
            break
        branch_deadline = min(deadline - 0.5, time.process_time() + 8.0)
        dense = _densify(best, c)
        work = dense
        for beta in [1e5, 1e7]:
            if time.process_time() >= branch_deadline - 0.5:
                break
            ht = _lbfgs_all_pos(work, 100, branch_deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(work) + 1e-14:
                work = ht
        ht, r = _peak_ladder(work, branch_deadline,
                             pads=(0.15, 0.08, 0.04), iters=200)
        consider(ht, 'dens%g' % c)

    # (4) second upsample pass on the improved best, then final all-pos polish
    if time.process_time() < deadline - 3.0:
        up = _upsample(best, 2)
        ht, r = _peak_ladder(up, min(deadline - 1.0,
                                     time.process_time() + 10.0),
                             pads=(0.10, 0.05, 0.03), iters=300)
        consider(ht, 'up2b')

    # (5) final polish on best
    if time.process_time() < deadline - 2.0:
        for beta in [1e7, 0.0]:
            if time.process_time() >= deadline - 0.8:
                break
            ht = _lbfgs_all_pos(best, 150, deadline - 0.5, beta=beta)
            consider(ht, 'tail%g' % beta)
        ht, r = _peak_ladder(best, deadline - 0.3,
                             pads=(0.05, 0.03), iters=200)
        consider(ht, 'tailpk')

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size >= 1 and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

