            hn = _lbfgs_all_pos(hc, 150, cap, beta=beta)
            rn = R_of(hn)
            if rn > rc:
                hc, rc = hn, rn
        return hc, rc

    if time.process_time() < hard - 2.0:
        hh, rh = homotopy(best, min(hard - 1.0, time.process_time() + 8.0))
        print("homotopy R=%.9f (start %.9f)" % (rh, start_bestR))
        if rh > bestR + 1e-13:
            best, bestR = hh, rh
        else:
            alt, altR = hh, rh

