    stall = 0
    while time.process_time() < hard - 1.0:
        sweep += 1
        improved = False

        # Full optimise
        cap = min(hard - 0.5, time.process_time() + 3.0)
        hx = _lbfgs_all_pos(best, 200, cap)
        rx = R_of(hx)
        if rx > bestR + 1e-14:
            best, bestR = hx, rx
            improved = True
            print("  [s%d full] R=%.9f" % (sweep, bestR))

        # Polish peak windows at several scales
        for frac in (0.02, 0.05, 0.10, 0.20, 0.40):
            if time.process_time() >= hard - 0.6:
                break
            free = _peak_window(best, frac=frac)
            cap = min(hard - 0.4, time.process_time() + 1.5)
            hb = _lbfgs_block(best, free, 120, cap)
            rb = R_of(hb)
            if rb > bestR + 1e-14:
                best, bestR = hb, rb
                improved = True
                print("  [s%d win %.2f] R=%.9f" % (sweep, frac, bestR))

        # Occasional prolong attempt (only if we have budget)
        if not improved and stall >= 1 and best.size * 2 <= 1000000:
            if time.process_time() < hard - 6.0:
                hp = _prolong(best)
                cap = min(hard - 3.0, time.process_time() + 4.0)
                hp = _lbfgs_all_pos(hp, 200, cap)
                rp = R_of(hp)
                print("  [s%d prolong] R=%.9f" % (sweep, rp))
                if rp > bestR + 1e-13:
                    best, bestR = hp, rp
                    improved = True
                    stall = 0

        if improved:
            stall = 0
        else:
            stall += 1
            # Random perturbation around best to escape
            if time.process_time() < hard - 2.0:
                pert = best * (1.0 + 0.01 * rng.standard_normal(best.size))
                pert = _rescale(np.clip(pert, 0, None))
                cap = min(hard - 1.0, time.process_time() + 2.0)
                pert = _lbfgs_all_pos(pert, 150, cap)
                rp = R_of(pert)
                if rp > bestR + 1e-13:
                    best, bestR = pert, rp
                    print("  [s%d perturb] R=%.9f" % (sweep, bestR))

    # Final full polish
    if time.process_time() < hard - 0.5:
        cap = min(hard - 0.3, time.process_time() + 3.0)
        hx = _lbfgs_all_pos(best, 300, cap)
        rx = R_of(hx)
        if rx > bestR:
            best, bestR = hx, rx

    print("final R=%.9f (N=%d) start=%.9f" % (bestR, best.size, start_bestR))

    if alt is not None and altR > start_bestR + 1e-13 and altR > bestR - 1e-10:
        if bestR >= altR:
            return {"best": best, "alternative": alt}
        else:
            return {"best": alt, "alternative": best}

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _full_polish(h, deadline, iters=400):
    ht = h
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, iters, deadline - 0.3, beta=beta)
    return ht


def _lift_and_polish(c, deadline):
    h_lift = _rescale(np.repeat(c, 2))
    ht = h_lift
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 400, deadline - 0.3, beta=beta)
    return ht


def _split_refine(c, deadline):
    """Upsample c by 2 with a smooth interpolation, then polish."""
    n = c.size
    h = np.repeat(c, 2).astype(float)
    # smooth: average neighbours in the lifted array
    if h.size >= 3:
        h2 = h.copy()
        h2[1:-1] = 0.5 * h[1:-1] + 0.25 * (h[:-2] + h[2:])
        h = h2
    h = _rescale(h)
    ht = h
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 400, deadline - 0.3, beta=beta)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    N = best.size
    best_c = None
    best_cR = -1.0

    # ---- Phase 1: half-resolution cycle + lift ----
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.14
        work_c, best_c, best_cR, org = _half_cycle(c, cR, half_deadline, tag='h0')
        print("half-res R(c)=%.9f" % best_cR)
        ht = _lift_and_polish(best_c, deadline)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

        # Try a split refinement of the half-res solution (interpolated lift)
        if time.process_time() < deadline - 3.0:
            ht2 = _split_refine(best_c, deadline)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, 'split'
                print("split NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 2: perturb-restarts on half-res quotient ----
    restart_deadline = t0 + budget_seconds * 0.72
    restarts_done = 0
    restarts_accepted = 0
    if best_c is not None and time.process_time() < restart_deadline - 2.0:
        rng = np.random.default_rng(12345)
        amps = [0.003, 0.006, 0.01, 0.015, 0.02, 0.004, 0.008, 0.012]
        ri = 0
        while time.process_time() < restart_deadline - 2.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc2 = best_c.copy()
            nz = cc2 > 0
            if nz.sum() == 0:
                break
            cc2[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc2 = _rescale(cc2)
            r0 = R_of(cc2)
            slice_deadline = min(restart_deadline,
                                 time.process_time() + 0.09 * budget_seconds)
            work_c2, cand_c, cand_cR, org = _half_cycle(
                cc2, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.20, 0.15])
            restarts_done += 1
            ht = _lift_and_polish(cand_c, slice_deadline)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
                best_c = cand_c.copy()
                best_cR = cand_cR
                restarts_accepted += 1
                origin = 'restart%d' % ri
                print("restart %d amp=%.3f ACCEPT R=%.9f R(c)=%.9f" %
                      (ri, amp, bestR, best_cR))
            else:
                if cand_cR > best_cR + 1e-12:
                    best_c = cand_c.copy()
                    best_cR = cand_cR
                if r > alt_bestR:
                    alt_best, alt_bestR = ht.copy(), r
                print("restart %d amp=%.3f REJECT R=%.9f R(c)=%.9f" %
                      (ri, amp, r, cand_cR))
            if time.process_time() >= restart_deadline - 2.0:
                break

    # ---- Phase 3: full-N polish ----
    if time.process_time() < deadline - 1.5:
        ht = best
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_all_pos(ht, 400, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+full'
            print("full polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    for pad in [0.12, 0.08, 0.05]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.4, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR, origin = ht2.copy(), r2, origin + '+pk'
            print("peak polish pad=%.2f NEW BEST R=%.9f" % (pad, bestR))
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("restarts=%d accepted=%d best_c=%.9f best_full=%.9f" %
          (restarts_done, restarts_accepted, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _full_polish(h, deadline, iters=400):
    ht = h
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, iters, deadline - 0.3, beta=beta)
    return ht


def _lift_and_polish(c, deadline):
    h_lift = _rescale(np.repeat(c, 2))
    ht = h_lift
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 400, deadline - 0.3, beta=beta)
    return ht


def _split_refine(c, deadline):
    """Upsample c by 2 with a smooth interpolation, then polish."""
    n = c.size
    h = np.repeat(c, 2).astype(float)
    # smooth: average neighbours in the lifted array
    if h.size >= 3:
        h2 = h.copy()
        h2[1:-1] = 0.5 * h[1:-1] + 0.25 * (h[:-2] + h[2:])
        h = h2
    h = _rescale(h)
    ht = h
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 400, deadline - 0.3, beta=beta)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    N = best.size
    best_c = None
    best_cR = -1.0

    # ---- Phase 1: half-resolution cycle + lift ----
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.14
        work_c, best_c, best_cR, org = _half_cycle(c, cR, half_deadline, tag='h0')
        print("half-res R(c)=%.9f" % best_cR)
        ht = _lift_and_polish(best_c, deadline)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

        # Try a split refinement of the half-res solution (interpolated lift)
        if time.process_time() < deadline - 3.0:
            ht2 = _split_refine(best_c, deadline)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, 'split'
                print("split NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 2: perturb-restarts on half-res quotient ----
    restart_deadline = t0 + budget_seconds * 0.72
    restarts_done = 0
    restarts_accepted = 0
    if best_c is not None and time.process_time() < restart_deadline - 2.0:
        rng = np.random.default_rng(12345)
        amps = [0.003, 0.006, 0.01, 0.015, 0.02, 0.004, 0.008, 0.012]
        ri = 0
        while time.process_time() < restart_deadline - 2.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc2 = best_c.copy()
            nz = cc2 > 0
            if nz.sum() == 0:
                break
            cc2[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc2 = _rescale(cc2)
            r0 = R_of(cc2)
            slice_deadline = min(restart_deadline,
                                 time.process_time() + 0.09 * budget_seconds)
            work_c2, cand_c, cand_cR, org = _half_cycle(
                cc2, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.20, 0.15])
            restarts_done += 1
            ht = _lift_and_polish(cand_c, slice_deadline)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
                best_c = cand_c.copy()
                best_cR = cand_cR
                restarts_accepted += 1
                origin = 'restart%d' % ri
                print("restart %d amp=%.3f ACCEPT R=%.9f R(c)=%.9f" %
                      (ri, amp, bestR, best_cR))
            else:
                if cand_cR > best_cR + 1e-12:
                    best_c = cand_c.copy()
                    best_cR = cand_cR
                if r > alt_bestR:
                    alt_best, alt_bestR = ht.copy(), r
                print("restart %d amp=%.3f REJECT R=%.9f R(c)=%.9f" %
                      (ri, amp, r, cand_cR))
            if time.process_time() >= restart_deadline - 2.0:
                break

    # ---- Phase 3: full-N polish ----
    if time.process_time() < deadline - 1.5:
        ht = best
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_all_pos(ht, 400, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+full'
            print("full polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    for pad in [0.12, 0.08, 0.05]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.4, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR, origin = ht2.copy(), r2, origin + '+pk'
            print("peak polish pad=%.2f NEW BEST R=%.9f" % (pad, bestR))
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("restarts=%d accepted=%d best_c=%.9f best_full=%.9f" %
          (restarts_done, restarts_accepted, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_simplex(h, beta):
    # mass fixed: drop +2/s gradient and 2*log(s) value term
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if beta > 0:
        mx = Lf.max()
        if mx <= 0:
            m = int(np.argmax(Lf))
            Lm = Lf[m]
            gLf = -dq / num
            gLf[m] += 1.0 / Lm
            grad = _backprop(gLf, h)
            val = -np.log(num) + np.log(Lm)
            return val, grad
        e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
        Z = e.sum()
        if Z <= 0:
            m = int(np.argmax(Lf))
            Lm = Lf[m]
            gLf = -dq / num
            gLf[m] += 1.0 / Lm
            grad = _backprop(gLf, h)
            val = -np.log(num) + np.log(Lm)
            return val, grad
        w = e / Z
        sm = mx + np.log(Z) / beta
        gLf = -dq / num + w / sm
        grad = _backprop(gLf, h)
        val = -np.log(num) + np.log(sm)
        return val, grad
    else:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h)
        val = -np.log(num) + np.log(Lm)
        return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0.0, None)
    Lp = Lc ** p
    S = Lp.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = S ** (1.0 / p)
    if sm <= 0:
        return _fun_grad(h)
    w = Lc ** (p - 1) / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_simplex(h0, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h0 = np.clip(h0, 0, None)
    if h0.sum() <= 0:
        return h0
    n = h0.size
    s0 = h0.sum()
    mx0 = h0.max()
    if mx0 <= 0:
        return h0
    active = np.flatnonzero(h0 > 1e-13 * mx0)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h0[active], 1e-300, None))

    def f(u):
        hh = np.zeros(n)
        hv = np.exp(np.clip(u, -40.0, 0.0))
        hh[active] = hv
        tot = hh.sum()
        if tot <= 0:
            return 1e18, np.zeros(u.size)
        hh *= s0 / tot
        val, g = _fun_grad_simplex(hh, beta)
        ha = hh[active]
        ga = g[active]
        denom = ha.sum()
        if denom <= 0:
            return val, np.zeros(u.size)
        proj = ga - (np.sum(ha * ga) / denom)
        return val, ha * proj

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 0.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    hh = np.zeros(n)
    hh[active] = np.exp(np.clip(res.x, -40.0, 0.0))
    tot = hh.sum()
    if tot <= 0:
        return h0
    hh *= s0 / tot
    return _rescale(hh)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _maxmean(h):
    m = h.mean()
    if m <= 0:
        return 0.0
    return float(h.max() / m)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, maxmean=%.2f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _maxmean(best)))

    # diagnostic: null-direction ratio |sum(h*g_h)| / (||h||*||g_h||)
    try:
        _, g_diag = _fun_grad(best)
        hh = best
        num_r = abs(np.sum(hh * g_diag))
        den_r = np.linalg.norm(hh) * np.linalg.norm(g_diag)
        if den_r > 0:
            print("null-dir ratio |sum(h*g)|/(||h||*||g||) = %.6f"
                  % (num_r / den_r))
    except Exception:
        pass

    # ---- simplex-beta ladder ----
    simplex_deadline = t0 + budget_seconds * 0.62
    betas = (1e4, 1e5, 1e6, 1e7, 1e8)
    per_beta = budget_seconds * 0.10
    for beta in betas:
        if time.process_time() >= simplex_deadline - 1.0:
            break
        db = min(simplex_deadline, time.process_time() + per_beta)
        ht = _lbfgs_simplex(best, 300, db, beta)
        r_s = R_of(ht)
        # exact-R polish
        if time.process_time() < db - 0.3:
            ht2 = _lbfgs_all_pos(ht, 250, db, beta=0.0)
            r2 = R_of(ht2)
            if r2 > r_s:
                ht, r_s = ht2, r2
        if r_s > bestR + 1e-14:
            best, bestR = ht.copy(), r_s
            print("SIMPLEX beta=%.0e NEW BEST R=%.9f nearmax5=%.4f maxmean=%.2f"
                  % (beta, bestR, _nearmax_frac(best), _maxmean(best)))
        else:
            print("SIMPLEX beta=%.0e no gain (R=%.9f vs %.9f)"
                  % (beta, r_s, bestR))

    # ---- final hard-max polish ----
    fd = t0 + budget_seconds * 0.90
    ht = _lbfgs_all_pos(best, 800, fd, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("FINAL beta0 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _peak_ladder(best, fd, pads=(0.05, 0.03), iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, maxmean=%.2f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _maxmean(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0.0, None)
    Lp = Lc ** p
    S = Lp.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = S ** (1.0 / p)
    if sm <= 0:
        return _fun_grad(h)
    w = Lc ** (p - 1) / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h, eta, tau):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    d = np.clip(tau * M - Lf, 0.0, None)
    F = float(np.sum(d * d))
    n = max(1, Lf.size)
    gLf = -dq / num
    gLf[int(np.argmax(Lf))] += 1.0 / M
    gLf += -(2.0 * eta / (M * M * n)) * d
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + eta * F / (M * M * n)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_flat(h0, maxiter, deadline, eta, tau):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_flat(hh, eta, tau)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_all_pos_p(h0, maxiter, deadline, p):
    if time.process_time() >= deadline - 0.3:
