    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_p(h0, free, maxiter, deadline, p):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_pnorm(hh, p)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder_p(h, deadline, p, pads=(0.08, 0.05, 0.03), iters=250):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block_p(h, win, iters, deadline - 0.3, p)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, nearmax50=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best, 0.95),
             _nearmax_frac(best, 0.5)))

    # ---- NEW: deficit-band flattening (target-only derivative) ----
    flat_deadline = t0 + budget_seconds * 0.45
    etas = (1e-3, 1e-2, 3e-2, 1e-1)
    tau = 0.97
    per_eta = budget_seconds * 0.09
    for eta in etas:
        if time.process_time() >= flat_deadline - 1.0:
            break
        dp = min(flat_deadline, time.process_time() + per_eta)
        ht = _lbfgs_flat(best, 250, dp, eta, tau)
        if time.process_time() < dp - 0.5:
            ht = _lbfgs_all_pos(ht, 250, dp, beta=0.0)
        r = R_of(ht)
        Lf = _knots(ht)
        mx = Lf.max()
        ratio = mx / max(1e-30, ht.mean())
        print("flat eta=%.0e R=%.9f nm95=%.4f nm50=%.4f max/mean=%.2f"
              % (eta, r, _nearmax_frac(ht, 0.95), _nearmax_frac(ht, 0.5), ratio))
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("flat eta=%.0e NEW BEST R=%.9f" % (eta, bestR))

    # ---- p-norm smoothing ladder (kept from base) ----
    pnorm_deadline = t0 + budget_seconds * 0.62
    ps = (4, 8, 16, 32, 64, 128)
    per_p = budget_seconds * 0.05
    for p in ps:
        if time.process_time() >= pnorm_deadline - 1.0:
            break
        dp = min(pnorm_deadline, time.process_time() + per_p)
        ht = _lbfgs_all_pos_p(best, 300, dp, p)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("pnorm p=%d NEW BEST R=%.9f nearmax5=%.4f"
                  % (p, bestR, _nearmax_frac(best)))
        else:
            print("pnorm p=%d no gain (R=%.9f vs %.9f)" % (p, r, bestR))

    if time.process_time() < pnorm_deadline - 1.0:
        ht = _peak_ladder_p(best, pnorm_deadline, 128,
                            pads=(0.08, 0.05, 0.03), iters=250)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("pnorm peak NEW BEST R=%.9f nearmax5=%.4f"
                  % (bestR, _nearmax_frac(best)))

    # ---- final hard-max polish ----
    fd = t0 + budget_seconds * 0.90
    ht = _lbfgs_all_pos(best, 800, fd, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("FINAL beta0 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _lbfgs_all_pos(best, 400, fd, beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL beta8 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _peak_ladder(best, fd, pads=(0.05, 0.03), iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, "
          "nearmax50=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best, 0.95), _nearmax_frac(best, 0.5)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _resample(h, N2):
    """Mass-preserving resample of step function h to N2 steps."""
    n = len(h)
    if N2 == n:
        return h.copy()
    cum = np.concatenate(([0.0], np.cumsum(h)))
    M = cum[-1]
    if M <= 0:
        return np.ones(N2)
    edges = np.linspace(0.0, M, N2 + 1)
    # positions in original index-space
    pos = np.interp(edges, cum, np.arange(n + 1))
    # mass in each new cell = width in original index space * ... but h is per-cell mass
    # Actually cum is cumulative mass; edges are mass values. mass per new cell:
    mass = np.diff(edges)
    # distribute mass uniformly within each new cell (step function)
    out = mass / (M / N2) * (M / N2) / (M / N2)  # = mass / cellwidth_in_mass
    # cell width in mass units is M/N2, so height = mass / (M/N2)
    out = mass / (M / N2)
    return np.clip(out, 0.0, None)


def _escalate(h, N2):
    n = len(h)
    if N2 == n:
        return h.copy()
    if N2 % n == 0:
        k = N2 // n
        return np.repeat(h, k) / k
    return _resample(h, N2)


def _interleave_lift(h, w):
    """Lift h to 2x by splitting each cell into two with weights w."""
    n = len(h)
    out = np.empty(2 * n)
    out[0::2] = h * w[0]
    out[1::2] = h * w[1]
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        best = np.clip(np.asarray(start, dtype=float), 0, None)
        if best.sum() <= 0:
            best = np.ones(1024)
    else:
        best = np.ones(1024)
    best = _rescale(best)
    best_R = R_of(best)
    start_R = best_R
    print(f"init R={best_R:.6f} N={best.size}")

    def accept(cand):
        nonlocal best, best_R
        if cand is None:
            return False
        cand = np.clip(cand, 0, None)
        if cand.sum() <= 0:
            return False
        Rc = R_of(cand)
        if Rc > best_R + 1e-14:
            best = cand
            best_R = Rc
            return True
        return False

    # ---- Stage A: coarse V-cycle (0-35%) ----
    A_end = t0 + budget_seconds * 0.35
    for Nc in (4096, 2048):
        if time.process_time() > A_end - 1.0:
            break
        hc = _resample(best, Nc)
        if R_of(hc) > best_R:
            # resample shouldn't improve, but guard
            pass
        for beta in (1e2, 1e3, 1e4, 1e5):
            if time.process_time() > A_end - 0.5:
                break
            hc = _lbfgs_all_pos(hc, 250, A_end, beta=beta)
        hc = _peak_ladder(hc, A_end, pads=(0.12, 0.08, 0.05), iters=200)
        # prolongate back
        hb = _resample(hc, best.size)
        for beta in (1e5, 0.0):
            if time.process_time() > A_end - 0.5:
                break
            hb = _lbfgs_all_pos(hb, 150, A_end, beta=beta)
        accept(hb)
        print(f"A Nc={Nc} R={best_R:.6f}")

    # ---- Stage B: 2x ladder (35-70%) ----
    B_end = t0 + budget_seconds * 0.70
    rng = np.random.default_rng(12345)
    for trial in range(3):
        if time.process_time() > B_end - 2.0:
            break
        w = rng.dirichlet([2.0, 2.0])
        lift = _rescale(_interleave_lift(best, w))
        for beta in (1e4, 1e5, 1e6):
            if time.process_time() > B_end - 1.0:
                break
            lift = _lbfgs_all_pos(lift, 200, B_end, beta=beta)
        lift = _peak_ladder(lift, B_end, pads=(0.08, 0.05, 0.03), iters=250)
        if accept(lift):
            print(f"B trial={trial} N={best.size} R={best_R:.6f}")
            # optionally go to 65536
            if time.process_time() < B_end - 8.0 and best.size <= 32768:
                w2 = rng.dirichlet([2.0, 2.0])
                lift2 = _rescale(_interleave_lift(best, w2))
                for beta in (1e4, 1e5, 1e6):
                    if time.process_time() > B_end - 1.0:
                        break
                    lift2 = _lbfgs_all_pos(lift2, 150, B_end, beta=beta)
                lift2 = _peak_ladder(lift2, B_end, pads=(0.06, 0.04), iters=200)
                if accept(lift2):
                    print(f"B2 N={best.size} R={best_R:.6f}")
        else:
            print(f"B trial={trial} no improve R={best_R:.6f}")

    # ---- Stage C: window jitter + polish (70-100%) ----
    C_end = deadline
    n = best.size
    win_size = max(8, n // 8)
    for it in range(6):
        if time.process_time() > C_end - 2.0:
            break
        improved = False
        # multiplicative jitter on a contiguous window
        for _ in range(3):
            if time.process_time() > C_end - 1.5:
                break
            lo = rng.integers(0, max(1, n - win_size))
            hi = min(n, lo + win_size)
            jit = rng.lognormal(0.0, 0.15, hi - lo)
            cand = best.copy()
            cand[lo:hi] *= jit
            cand = _rescale(cand)
            if accept(cand):
                improved = True
        # polish
        for beta in (1e5, 0.0):
            if time.process_time() > C_end - 1.0:
                break
            ht = _lbfgs_all_pos(best, 200, C_end, beta=beta)
            if accept(ht):
                improved = True
        hp = _peak_ladder(best, C_end, pads=(0.06, 0.04, 0.03), iters=200)
        if accept(hp):
            improved = True
        if not improved and it > 2:
            break

    # final sharp polish
    if time.process_time() < C_end - 1.0:
        ht = _lbfgs_all_pos(best, 800, C_end, beta=0.0)
        accept(ht)

    if best_R < start_R - 1e-12:
        # never return below start
        best = np.asarray(start, dtype=float)
        best_R = start_R

    print(f"final best_R={R_of(best):.6f} N={best.size}")
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None or not np.all(np.isfinite(res.x)):
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None or not np.all(np.isfinite(res.x)):
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline, fg=None):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH)
    span = hi - lo
    pad = max(64, int(span * 0.20))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline, fg=fg)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


def _upsample(h, factor):
    """Smooth (linear) upsample of the step heights by an integer factor."""
    n = h.size
    if factor <= 1:
        return h.copy()
    x = np.linspace(0.0, n - 1, n)
    xn = np.linspace(0.0, n - 1, (n - 1) * factor + 1)
    hn = np.interp(xn, x, h)
    return np.clip(hn, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    start_best = None
    start_bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    bestH = start_best.copy()
    bestRH = start_bestR
    mx0, m0, near0 = _stats(bestH)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx0, m0, near0))

    # ---- idea: refine on a finer grid (upsample), sharp polish, then map back ----
    # Try a modest upsample factor; keep whichever is better.
    if bestH.size <= 300000:
        factor = 2 if bestH.size <= 150000 else 1
        if factor > 1:
            hu = _rescale(_upsample(bestH, factor))
            ru = R_of(hu)
            print("  upsample x%d R=%.7f" % (factor, ru))
            if ru > bestRH + 1e-13:
                bestH, bestRH = hu, ru

    # ---- sharp polish on the (possibly) finer grid ----
    if time.process_time() < deadline - 3.0:
        sub = min(deadline - 1.0, time.process_time() + 20.0)
        h = _lbfgs_all_pos(bestH, 400, sub)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        bestH, bestRH = _peak_polish(bestH, bestRH, 300, sub)
        print("  sharp polish R=%.7f" % bestRH)

    # ---- softmax (beta) homotopy to sharpen the peak ----
    if time.process_time() < deadline - 3.0:
        sub = min(deadline - 1.0, time.process_time() + 20.0)
        for beta in (200.0, 1000.0, 5000.0, 20000.0):
            if time.process_time() >= sub - 1.0:
                break
            h = _lbfgs_all_pos(bestH, 300, sub, beta=beta)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  beta=%g R=%.7f" % (beta, bestRH))
            bestH, bestRH = _peak_polish(bestH, bestRH, 200, sub)

    # ---- final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_all_pos(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        bestH, bestRH = _peak_polish(bestH, bestRH, 300, deadline - 0.3)
        print("final sharp R=%.7f" % bestRH)

    mx, m, near = _stats(bestH)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": start_best if start_bestR > 0 else None}
    return {"best": start_best,
            "alternative": bestH if bestRH > start_bestR - 1e-5 else None}

