        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0
    base_N = best.size

    # ---- Phase 1: full-N polish on start (short, cheap) ----
    # The start is already very good; a full polish from here often gains
    # tiny amounts.  We do it briefly so we don't waste the budget.
    if time.process_time() < t0 + budget_seconds * 0.10:
        ht = best
        for beta in [1e6, 1e7]:
            if time.process_time() >= t0 + budget_seconds * 0.10:
                break
            ht = _lbfgs_all_pos(ht, 250, t0 + budget_seconds * 0.10, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'fullpolish'
            print("full polish NEW BEST R=%.9f" % bestR)

    # ---- Phase 2: multi-scale ladder ----
    # Try several working resolutions (downsamples and up-samples) and
    # lift them back to full resolution.  Different scales explore
    # different local optima.
    #
    # Downsample by 2 (half-res), 3 (third-res), etc.  Each gets a short
    # optimise, then we lift to full res and polish.
    scales = [2, 3, 4]
    alt_cands = []
    for sc in scales:
        if time.process_time() >= deadline - 5.0:
            break
        n = base_N // sc
        if n < 32:
            continue
        c = best[:n * sc].reshape(n, sc).mean(axis=1)
        c = _rescale(c)
        cR = R_of(c)
        slice_end = min(deadline - 4.0,
                        time.process_time() + 0.10 * budget_seconds)
        work_c, cand_c, cand_cR, org = _half_cycle(
            c, cR, slice_end, tag='sc%d' % sc,
            pads=[0.30, 0.20, 0.12])
        if cand_cR > cR + 1e-14:
            # lift back to full res via smooth upsampling
            h_lift = _smooth_upsample(cand_c, sc)
            # pad/truncate to base_N
            if h_lift.size < base_N:
                h_lift = np.concatenate(
                    [h_lift, np.zeros(base_N - h_lift.size)])
            elif h_lift.size > base_N:
                h_lift = h_lift[:base_N]
            h_lift = _rescale(h_lift)
            # quick polish
            hp = h_lift
            for beta in [1e6, 1e7]:
                if time.process_time() >= slice_end:
                    break
                hp = _lbfgs_all_pos(hp, 300, slice_end, beta=beta)
            r = R_of(hp)
            print("scale %d lift R=%.9f (cR=%.9f)" % (sc, r, cand_cR))
            if r > bestR + 1e-14:
                best, bestR, origin = hp.copy(), r, 'scale%d' % sc
                print("scale %d NEW BEST R=%.9f" % (sc, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = hp.copy(), r
                alt_cands.append((sc, hp.copy(), r))

    # ---- Phase 3: perturb-restarts on full-res ----
    # Perturb the current best with multiplicative noise on nonzeros,
    # then polish.  Accept if better.
    restart_deadline = deadline - 1.5
    rng = np.random.default_rng(20240712)
    amps = [0.002, 0.004, 0.006, 0.010, 0.015, 0.003, 0.008, 0.012]
    ri = 0
    restarts_accepted = 0
    while time.process_time() < restart_deadline - 1.0:
        amp = amps[ri % len(amps)]
        ri += 1
        cand = best.copy()
        nz = cand > 0
        if nz.sum() == 0:
            break
        cand[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
        cand = _rescale(cand)
        r0 = R_of(cand)
        slice_end = min(restart_deadline,
                        time.process_time() + 0.06 * budget_seconds)
        # polish with peak ladder
        hp = cand
        for beta in [1e6, 1e7]:
            if time.process_time() >= slice_end - 0.5:
                break
            hp = _lbfgs_all_pos(hp, 300, slice_end - 0.3, beta=beta)
        # peak block
        for pad in [0.20, 0.12]:
            if time.process_time() >= slice_end - 0.4:
                break
            win = _peak_window(hp, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(hp, win, 300, slice_end - 0.3, beta=1e7)
            if R_of(ht2) > R_of(hp) + 1e-14:
                hp = ht2
        r = R_of(hp)
        if r > bestR + 1e-13:
            best, bestR = hp.copy(), r
            origin = 'restart%d' % ri
            restarts_accepted += 1
            print("restart %d amp=%.3f ACCEPT R=%.9f" % (ri, amp, bestR))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = hp.copy(), r
            print("restart %d amp=%.3f REJECT R=%.9f" % (ri, r))

    # ---- Phase 4: final peak ladder on best ----
    for pad in [0.15, 0.10, 0.06, 0.04]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.4, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR, origin = ht2.copy(), r2, origin + '+pk'
            print("peak polish pad=%.2f NEW BEST R=%.9f" % (pad, bestR))
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("restarts=%d accepted=%d best_full=%.9f" %
          (ri, restarts_accepted, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _coarse_vcycle(s, slice_deadline, rng):
    n = s.size
    off = int(rng.integers(0, 2))
    body = s[off:]
    if body.size % 2 == 1:
        body = np.concatenate((body, [0.0]))
    hc = body.reshape(-1, 2).sum(axis=1)
    hc = _rescale(hc)
    hc = _lbfgs_all_pos(hc, 300, slice_deadline, beta=0.0)
    if time.process_time() < slice_deadline - 0.3:
        hc = _lbfgs_all_pos(hc, 200, slice_deadline, beta=1e7)
    up = np.repeat(hc, 2)
    if off > 0:
        up = np.concatenate((np.zeros(off), up))
    up = up[:n]
    if up.size < n:
        up = np.concatenate((up, np.zeros(n - up.size)))
    up = _rescale(up)
    return _lbfgs_all_pos(up, 250, slice_deadline, beta=0.0)


def _jitter_reseed(base, rng, sigma=0.05):
    h = base.copy()
    active = h > 0
    if active.sum() == 0:
        return _rescale(base)
    noise = rng.normal(0.0, sigma, size=h.size)
    h[active] = h[active] * np.exp(noise[active])
    return _rescale(h)


# ---- New: boundary perturbation search on tails, plus interior poke ----
def _tail_poke(h, deadline, rng, frac=0.05, tries=8):
    """Try perturbing one tail region (left or right edge of support) and
    re-optimise locally.  The peak sits at ~0.32 of support, so the right
    tail is long and its shape strongly constrains ||f*f||_inf and the L2."""
    best = h.copy()
    bestR = R_of(h)
    n = h.size
    active = np.flatnonzero(h > 0)
    if active.size < 8:
        return best
    lo, hi = int(active[0]), int(active[-1])
    width = max(8, int((hi - lo + 1) * frac))
    for t in range(tries):
        if time.process_time() >= deadline - 0.5:
            break
        side = rng.integers(0, 2)
        if side == 0:
            a = lo
            b = min(hi, lo + width)
        else:
            a = max(lo, hi - width)
            b = hi
        cand = h.copy()
        seg = cand[a:b + 1]
        if seg.size == 0:
            continue
        # multiplicative dip or bump
        amp = rng.uniform(0.7, 1.3)
        x = np.linspace(-1.0, 1.0, seg.size)
        shape = 1.0 + (amp - 1.0) * np.exp(-3.0 * x * x)
        cand[a:b + 1] = seg * shape
        cand = _rescale(cand)
        win = np.arange(max(0, a - 16), min(n, b + 16 + 1))
        cand = _lbfgs_block(cand, win, 150, deadline - 0.3, beta=1e6)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand, r
    return best


def _interior_poke(h, deadline, rng, tries=6):
    """Perturb a random interior block of the support with an affine tilt
    and locally re-optimise.  Repeated small tilts can nudge the flat top of
    f*f while keeping its max fixed."""
    best = h.copy()
    bestR = R_of(h)
    n = h.size
    active = np.flatnonzero(h > 0)
    if active.size < 16:
        return best
    lo, hi = int(active[0]), int(active[-1])
    span = hi - lo + 1
    for _ in range(tries):
        if time.process_time() >= deadline - 0.5:
            break
        w = max(16, int(span * rng.uniform(0.05, 0.20)))
        a = int(rng.integers(lo, max(lo + 1, hi - w + 1)))
        b = min(hi, a + w)
        cand = h.copy()
        seg = cand[a:b + 1]
        if seg.size == 0:
            continue
        slope = rng.uniform(-0.15, 0.15)
        x = np.linspace(-1.0, 1.0, seg.size)
        cand[a:b + 1] = seg * (1.0 + slope * x)
        cand = _rescale(cand)
        win = np.arange(max(0, a - 8), min(n, b + 8 + 1))
        cand = _lbfgs_block(cand, win, 120, deadline - 0.3, beta=1e6)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand, r
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    amax0 = _argmax_frac(best)
    rng = np.random.default_rng(12345)

    states = {'A': best.copy(), 'B': best.copy(), 'C': best.copy()}
    state_R = {'A': bestR, 'B': bestR, 'C': bestR}
    gain = {'A': 0.0, 'B': 0.0, 'C': 0.0}
    reseeds = {'A': 0, 'B': 0, 'C': 0}

    slice_len = 4.0
    sched_deadline = t0 + budget_seconds * 0.88
    labels = ['A', 'B', 'C']
    li = 0

    while time.process_time() < sched_deadline - 0.5:
        lab = labels[li % 3]
        li += 1
        slice_deadline = min(time.process_time() + slice_len, sched_deadline)
        s = states[lab]

        if lab == 'A':
            s = _lbfgs_all_pos(s, 600, slice_deadline, beta=0.0)
            if time.process_time() < slice_deadline - 0.3:
                s = _lbfgs_all_pos(s, 200, slice_deadline, beta=1e8)
        elif lab == 'B':
            for beta in (1e5, 1e6, 1e8):
                if time.process_time() >= slice_deadline - 0.3:
                    break
                s = _lbfgs_all_pos(s, 250, slice_deadline, beta=beta)
            if time.process_time() < slice_deadline - 0.5:
                s = _peak_ladder(s, slice_deadline, pads=(0.20, 0.10, 0.05),
                                 iters=200)
        else:
            s = _coarse_vcycle(s, slice_deadline, rng)

        r = R_of(s)
        state_R[lab] = r
        states[lab] = s

        if r > bestR + 1e-14:
            gain[lab] += r - bestR
            best = s.copy()
            bestR = r
            print("ACCEPT %s R=%.9f dR=%.3e" % (lab, bestR, r - bestR))

        if state_R[lab] < bestR - 1e-7:
            if time.process_time() < sched_deadline - 0.5:
                seed = _jitter_reseed(best, rng, sigma=0.05)
                seed = _lbfgs_all_pos(seed, 100,
                                      min(time.process_time() + 1.5,
                                          sched_deadline), beta=0.0)
                rs = R_of(seed)
                states[lab] = seed
                state_R[lab] = rs
                reseeds[lab] += 1
                if rs > bestR + 1e-14:
                    gain[lab] += rs - bestR
                    best = seed.copy()
                    bestR = rs
                    print("RESEED-ACCEPT %s R=%.9f dR=%.3e"
                          % (lab, bestR, rs - bestR))

    for lab in labels:
        print("label %s cumulative gain=%.3e reseeds=%d"
              % (lab, gain[lab], reseeds[lab]))

    # ---- New: tail + interior poke stage ----
    poke_deadline = t0 + budget_seconds * 0.93
    ht = _tail_poke(best, poke_deadline, rng, frac=0.06, tries=10)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("TAIL poke ACCEPT R=%.9f dR=%.3e" % (bestR, r - bestR))
    else:
        print("TAIL poke reject R=%.9f" % r)

    poke_deadline = t0 + budget_seconds * 0.955
    ht = _interior_poke(best, poke_deadline, rng, tries=8)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("INTERIOR poke ACCEPT R=%.9f dR=%.3e" % (bestR, r - bestR))
    else:
        print("INTERIOR poke reject R=%.9f" % r)

    # ---- Final full beta=0 polish ----
    polish_deadline = t0 + budget_seconds * 0.975
    ht = _lbfgs_all_pos(best, 4000, polish_deadline, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("FINAL polish ACCEPT R=%.9f dR=%.3e" % (bestR, r - bestR))
    else:
        print("FINAL polish reject R=%.9f dR=%.3e" % (r, r - bestR))

    # ---- Peak ladder polish ----
    peak_deadline = t0 + budget_seconds * 0.995
    ht = _peak_ladder(best, peak_deadline, pads=(0.05, 0.03), iters=300)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("PEAK ladder ACCEPT R=%.9f dR=%.3e" % (bestR, r - bestR))
    else:
        print("PEAK ladder reject R=%.9f dR=%.3e" % (r, r - bestR))

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        alt = _tail_poke(best, t0 + budget_seconds * 0.999, rng,
                         frac=0.10, tries=4)
        result["alternative"] = alt if R_of(alt) > bestR else best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _resample(h, N2):
    n = len(h)
    if N2 == n:
        return h.copy()
    cum = np.concatenate(([0.0], np.cumsum(h)))
    M = cum[-1]
    if M <= 0:
        return np.ones(N2)
    edges = np.linspace(0.0, M, N2 + 1)
    mass = np.diff(edges)
    out = mass / (M / N2)
    return np.clip(out, 0.0, None)


def _escalate(h, N2):
    n = len(h)
    if N2 == n:
        return h.copy()
    if N2 % n == 0:
        k = N2 // n
        return np.repeat(h, k) / k
    return _resample(h, N2)


def _interleave_lift(h, w):
    n = len(h)
    out = np.empty(2 * n)
    out[0::2] = h * w[0]
    out[1::2] = h * w[1]
    return out


def _stats(h):
    zf = float(np.mean(h <= 0))
    Lf = _knots(h)
    mx = Lf.max()
    nm5 = float(np.mean(Lf >= 0.95 * mx)) if mx > 0 else 0.0
    return zf, nm5


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        best = np.clip(np.asarray(start, dtype=float), 0, None)
        if best.sum() <= 0:
            best = np.ones(1024)
    else:
        best = np.ones(1024)
    best = _rescale(best)
    best_R = R_of(best)
    start_R = best_R
    print(f"init R={best_R:.6f} N={best.size}")

    def accept(cand):
        nonlocal best, best_R
        if cand is None:
            return False
        cand = np.clip(cand, 0, None)
        if cand.sum() <= 0:
            return False
        Rc = R_of(cand)
        if Rc > best_R + 1e-14:
            best = cand
            best_R = Rc
            return True
        return False

    rng = np.random.default_rng(987654321)

    def polish_stack(h2, end_time, iters_main=250, iters_final=400):
        for beta in (1e4, 1e5, 1e6):
            if time.process_time() > end_time - 1.0:
                break
            h2 = _lbfgs_all_pos(h2, iters_main, end_time, beta=beta)
        if time.process_time() < end_time - 1.0:
            h2 = _peak_ladder(h2, end_time, pads=(0.08, 0.05, 0.03), iters=250)
        if time.process_time() < end_time - 1.0:
            h2 = _lbfgs_all_pos(h2, iters_final, end_time, beta=0.0)
        return h2

    # ---- Main loop: lift rounds + split-refine + densify-move ----
    main_end = t0 + budget_seconds * 0.85
    MAXN = 262144
    fail_streak = 0
    round_idx = 0

    while time.process_time() < main_end - 3.0:
        round_idx += 1
        gained = False

        # (a) LIFT ROUND
        if best.size * 2 <= MAXN:
            N2 = best.size * 2
            for trial in range(3):
                if time.process_time() > main_end - 3.0:
                    break
                w = rng.dirichlet([2.0, 2.0])
                h2 = np.repeat(best, 2) * np.tile(w, best.size)
                h2 = _rescale(h2)
                h2 = polish_stack(h2, main_end)
                if accept(h2):
                    gained = True
                    zf, nm5 = _stats(best)
                    print(f"LIFT trial={trial} N={best.size} R={best_R:.6f} "
                          f"zf={zf:.3f} nm5={nm5:.4f}")
                    break
                else:
                    zf, nm5 = _stats(h2)
                    print(f"LIFT trial={trial} N={h2.size} noimp R={best_R:.6f} "
                          f"zf={zf:.3f} nm5={nm5:.4f}")

        if gained:
            fail_streak = 0
            continue

        fail_streak += 1

        # (b) SPLIT-REFINE
        if fail_streak >= 2 and best.size * 2 <= MAXN:
            if time.process_time() < main_end - 3.0:
                N2 = best.size * 2
                h2 = _resample(best, N2)
                # 3-tap smoothing
                k = np.array([0.25, 0.5, 0.25])
                h2 = np.convolve(h2, k, mode='same')
                h2 = _rescale(h2)
                h2 = polish_stack(h2, main_end)
                if accept(h2):
                    fail_streak = 0
                    zf, nm5 = _stats(best)
                    print(f"SPLIT N={best.size} R={best_R:.6f} "
                          f"zf={zf:.3f} nm5={nm5:.4f}")
                    continue
                else:
                    print(f"SPLIT noimp R={best_R:.6f}")

        # (c) DENSIFY-MOVE
        if time.process_time() < main_end - 3.0:
            n = best.size
            frac = rng.uniform(0.15, 0.40)
            wlen = max(4, int(frac * n))
            lo = int(rng.integers(0, max(1, n - wlen)))
            hi = min(n, lo + wlen)
            jit = np.exp(0.15 * rng.standard_normal(hi - lo))
            cand = best.copy()
            cand[lo:hi] *= jit
            cand = _rescale(cand)
            for beta in (1e5, 0.0):
                if time.process_time() > main_end - 2.0:
                    break
                cand = _lbfgs_all_pos(cand, 150, main_end, beta=beta)
            if accept(cand):
                fail_streak = 0
                zf, nm5 = _stats(best)
                print(f"DENS R={best_R:.6f} N={best.size} "
                      f"zf={zf:.3f} nm5={nm5:.4f}")
                continue

        # nothing worked; try a small peak polish before giving up
        if time.process_time() < main_end - 2.0:
            hp = _peak_ladder(best, main_end, pads=(0.06, 0.04, 0.03), iters=200)
            if accept(hp):
                fail_streak = 0
                print(f"PEAK R={best_R:.6f} N={best.size}")
                continue

        if fail_streak >= 4:
            break

    # ---- Final long polish ----
    final_end = t0 + budget_seconds * 0.95
    if time.process_time() < final_end - 1.0:
        ht = _lbfgs_all_pos(best, 800, final_end, beta=0.0)
        accept(ht)
    if time.process_time() < final_end - 0.5:
        hp = _peak_ladder(best, final_end, pads=(0.06, 0.04, 0.03), iters=300)
        accept(hp)

    if best_R < start_R - 1e-12:
        best = np.asarray(start, dtype=float)
        best_R = start_R

    zf, nm5 = _stats(best)
    print(f"final best_R={R_of(best):.6f} N={best.size} zf={zf:.3f} nm5={nm5:.4f}")
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0.0, None)
    Lp = Lc ** p
    S = Lp.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = S ** (1.0 / p)
    if sm <= 0:
        return _fun_grad(h)
    w = Lc ** (p - 1) / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_tsm(h, p):
    """Tempered softmax / power-mean surrogate with corrected scale."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0.0, None)
    mx = Lc.max()
    if mx <= 0:
        return _fun_grad(h)
    W = Lc ** (p - 1)
    S = W.sum()
    if S <= 0:
        return _fun_grad(h)
    w = W / S
    # power mean, normalized
    r = Lc / mx
    sm = mx * (np.mean(r ** p)) ** (1.0 / p)
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
