        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder_tsm(h, deadline, p, pads=(0.08, 0.05, 0.03), iters=250):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block_tsm(h, win, iters, deadline - 0.3, p)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _deficit_frac(h, lo=0.7, hi=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    r = Lf / mx
    return float(np.mean((r >= lo) & (r <= hi)))


def _tsm_diagnostics(h, p):
    Lf = _knots(h)
    Lc = np.clip(Lf, 0.0, None)
    mx = Lc.max()
    if mx <= 0:
        return 0.0, 0.0
    W = Lc ** (p - 1)
    S = W.sum()
    if S <= 0:
        return 0.0, 0.0
    w = W / S
    r = Lc / mx
    sm = mx * (np.mean(r ** p)) ** (1.0 / p)
    return sm / mx, float(np.mean(w > 1e-4))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, deficit=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _deficit_frac(best)))

    # ---- tempered-softmax (power-mean) ladder ----
    tsm_deadline = t0 + budget_seconds * 0.60
    ps = (2, 3, 4, 6, 8, 12, 20)
    per_p = budget_seconds * 0.09
    for p in ps:
        if time.process_time() >= tsm_deadline - 1.0:
            break
        dp = min(tsm_deadline, time.process_time() + per_p)
        ht = _lbfgs_all_pos_tsm(best, 250, dp, p)
        r = R_of(ht)
        smr, wbreadth = _tsm_diagnostics(best, p)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("tsm p=%d sm/mx=%.4f wbreadth=%.4f NEW BEST R=%.9f deficit=%.4f"
                  % (p, smr, wbreadth, bestR, _deficit_frac(best)))
        else:
            print("tsm p=%d sm/mx=%.4f wbreadth=%.4f no gain (R=%.9f vs %.9f)"
                  % (p, smr, wbreadth, r, bestR))

    # p-norm peak-window polish using p=8 surrogate
    if time.process_time() < tsm_deadline - 1.0:
        ht = _peak_ladder_tsm(best, tsm_deadline, 8,
                              pads=(0.08, 0.05, 0.03), iters=250)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("tsm peak NEW BEST R=%.9f deficit=%.4f"
                  % (bestR, _deficit_frac(best)))

    # ---- final hard-max polish ----
    fd = t0 + budget_seconds * 0.92
    ht = _lbfgs_all_pos(best, 600, fd, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("FINAL beta0 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _lbfgs_all_pos(best, 400, fd, beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL beta8 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _peak_ladder(best, fd, pads=(0.05, 0.03), iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, deficit=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _deficit_frac(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _interlace_quotient(c):
    m = c.size
    c2 = np.zeros(2 * m, dtype=float)
    c2[0::2] = c
    left = np.concatenate(([0.0], c[:-1]))
    right = np.concatenate((c[1:], [0.0]))
    c2[1::2] = 0.25 * (left + right)
    return _rescale(c2)


def _fold_quotient(c2):
    m = c2.size // 2
    return 0.5 * (c2[0:2 * m:2] + c2[1:2 * m:2])


def _full_polish(h, slice_deadline, pads=(0.30, 0.15, 0.08)):
    ht = h
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= slice_deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
    for pad in pads:
        if time.process_time() >= slice_deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pad, extra=128)
        ht = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
    if time.process_time() < slice_deadline - 0.5:
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=0.0)
    return ht


def _smooth_shift(h, shift, deadline):
    """Interpolate h at integer offset `shift` (subpixel), then polish."""
    n = h.size
    x = np.arange(n)
    xs = x + shift
    xs = np.clip(xs, 0, n - 1)
    i0 = np.floor(xs).astype(int)
    i1 = np.minimum(i0 + 1, n - 1)
    t = xs - i0
    hs = (1 - t) * h[i0] + t * h[i1]
    return _rescale(hs)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 0: shift search (new idea) ----
    # Sub-pixel shifts of the construction may find a better alignment
    # before the expensive polish. Try several small offsets.
    if time.process_time() < deadline - 20.0:
        shifts = [0.5, -0.5, 0.25, -0.25, 0.75, -0.75]
        for sh in shifts:
            if time.process_time() >= deadline - 15.0:
                break
            hs = _smooth_shift(best, sh, deadline)
            r = R_of(hs)
            if r > bestR + 1e-12:
                # quick polish
                slice_dl = min(deadline - 10.0,
                               time.process_time() + 0.08 * budget_seconds)
                hp = _full_polish(hs, slice_dl, pads=(0.15, 0.08))
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best, bestR, origin = hp.copy(), rp, 'shift%+.2f' % sh
                    print("shift %+.2f NEW BEST R=%.9f" % (sh, bestR))
                elif rp > alt_bestR:
                    alt_best, alt_bestR = hp.copy(), rp
                elif r > alt_bestR:
                    alt_best, alt_bestR = hs.copy(), r

    # ---- Phase 1: half-res quotient cycle ----
    N = best.size
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        h0 = best.copy()
        c = h0[0::2].copy()
        cR = R_of(c)
        half_deadline = t0 + budget_seconds * 0.15
        work_c = c.copy()
        best_c, best_cR = c.copy(), cR
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= half_deadline - 0.5:
                break
            ht = _lbfgs_all_pos(work_c, 300, half_deadline - 0.3, beta=beta)
            r = R_of(ht)
            if r > best_cR + 1e-14:
                work_c, best_c, best_cR = ht, ht.copy(), r
        for pad in [0.30, 0.20, 0.15, 0.10, 0.08]:
            if time.process_time() >= half_deadline - 0.5:
                break
            win = _peak_window(work_c, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work_c, win, 400, half_deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > best_cR + 1e-14:
                work_c, best_c, best_cR = ht, ht.copy(), r
        print("half-res R(c)=%.9f" % best_cR)
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 400, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: quotient interlace cycles ----
    cycle = 0
    accepted_cycles = 0
    while cycle < 3 and time.process_time() < deadline - 6.0:
        cycle += 1
        c = best[0::2].copy()
        if c.size == 0 or c.sum() <= 0:
            break
        now = time.process_time()
        slice_dl = min(deadline - 5.0, now + 0.15 * budget_seconds)

        c2 = _interlace_quotient(c)
        c2p = _full_polish(c2, slice_dl, pads=(0.15, 0.08))
        c1 = _rescale(_fold_quotient(c2p))
        rc0 = R_of(c)
        rc1 = R_of(c1)
        if time.process_time() < slice_dl - 0.5:
            c1p = _lbfgs_all_pos(c1, 200, slice_dl - 0.3, beta=1e7)
            rc1p = R_of(c1p)
            if rc1p > rc1:
                c1, rc1 = c1p, rc1p
        c_use = c1 if rc1 > rc0 else c

        h_lift = _rescale(np.repeat(c_use, 2))
        hl = _lbfgs_all_pos(h_lift, 400, min(deadline - 1.5, slice_dl + 3.0),
                            beta=1e6)
        hl = _lbfgs_all_pos(hl, 400, min(deadline - 1.5, slice_dl + 5.0),
                            beta=1e7)
        rl = R_of(hl)
        if rl > bestR + 1e-13:
            best, bestR, origin = hl.copy(), rl, 'qcycle%d' % cycle
            accepted_cycles += 1
            print("qcycle %d R(c)=%.9f R(c1)=%.9f R(hl)=%.9f ACCEPT R=%.9f"
                  % (cycle, rc0, rc1, rl, bestR))
        else:
            if rl > alt_bestR:
                alt_best, alt_bestR = hl.copy(), rl

    # ---- Phase 3: peak ladder + trailing beta=0 ----
    if time.process_time() < deadline - 2.0:
        ht = _peak_ladder(best, deadline - 1.0,
                          pads=(0.10, 0.08, 0.06, 0.04), iters=400)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pk'
            print("peak ladder NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 1.0:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+all0'
                print("trailing all0 NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    print("cycles=%d accepted=%d best_full=%.9f" %
          (cycle, accepted_cycles, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _interlace_quotient(c):
    m = c.size
    c2 = np.zeros(2 * m, dtype=float)
    c2[0::2] = c
    left = np.concatenate(([0.0], c[:-1]))
    right = np.concatenate((c[1:], [0.0]))
    c2[1::2] = 0.25 * (left + right)
    return _rescale(c2)


def _fold_quotient(c2):
    m = c2.size // 2
    return 0.5 * (c2[0:2 * m:2] + c2[1:2 * m:2])


def _full_polish(h, slice_deadline, pads=(0.30, 0.15, 0.08)):
    ht = h
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= slice_deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
    for pad in pads:
        if time.process_time() >= slice_deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pad, extra=128)
        ht = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
    if time.process_time() < slice_deadline - 0.5:
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=0.0)
    return ht


def _smooth_shift(h, shift, deadline):
    """Interpolate h at integer offset `shift` (subpixel), then polish."""
    n = h.size
    x = np.arange(n)
    xs = x + shift
    xs = np.clip(xs, 0, n - 1)
    i0 = np.floor(xs).astype(int)
    i1 = np.minimum(i0 + 1, n - 1)
    t = xs - i0
    hs = (1 - t) * h[i0] + t * h[i1]
    return _rescale(hs)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 0: shift search (new idea) ----
    # Sub-pixel shifts of the construction may find a better alignment
    # before the expensive polish. Try several small offsets.
    if time.process_time() < deadline - 20.0:
        shifts = [0.5, -0.5, 0.25, -0.25, 0.75, -0.75]
        for sh in shifts:
            if time.process_time() >= deadline - 15.0:
                break
            hs = _smooth_shift(best, sh, deadline)
            r = R_of(hs)
            if r > bestR + 1e-12:
                # quick polish
                slice_dl = min(deadline - 10.0,
                               time.process_time() + 0.08 * budget_seconds)
                hp = _full_polish(hs, slice_dl, pads=(0.15, 0.08))
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best, bestR, origin = hp.copy(), rp, 'shift%+.2f' % sh
                    print("shift %+.2f NEW BEST R=%.9f" % (sh, bestR))
                elif rp > alt_bestR:
                    alt_best, alt_bestR = hp.copy(), rp
                elif r > alt_bestR:
                    alt_best, alt_bestR = hs.copy(), r

    # ---- Phase 1: half-res quotient cycle ----
    N = best.size
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        h0 = best.copy()
        c = h0[0::2].copy()
        cR = R_of(c)
        half_deadline = t0 + budget_seconds * 0.15
        work_c = c.copy()
        best_c, best_cR = c.copy(), cR
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= half_deadline - 0.5:
                break
            ht = _lbfgs_all_pos(work_c, 300, half_deadline - 0.3, beta=beta)
            r = R_of(ht)
            if r > best_cR + 1e-14:
                work_c, best_c, best_cR = ht, ht.copy(), r
        for pad in [0.30, 0.20, 0.15, 0.10, 0.08]:
            if time.process_time() >= half_deadline - 0.5:
                break
            win = _peak_window(work_c, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work_c, win, 400, half_deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > best_cR + 1e-14:
                work_c, best_c, best_cR = ht, ht.copy(), r
        print("half-res R(c)=%.9f" % best_cR)
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 400, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: quotient interlace cycles ----
    cycle = 0
    accepted_cycles = 0
    while cycle < 3 and time.process_time() < deadline - 6.0:
        cycle += 1
        c = best[0::2].copy()
        if c.size == 0 or c.sum() <= 0:
            break
        now = time.process_time()
        slice_dl = min(deadline - 5.0, now + 0.15 * budget_seconds)

        c2 = _interlace_quotient(c)
        c2p = _full_polish(c2, slice_dl, pads=(0.15, 0.08))
        c1 = _rescale(_fold_quotient(c2p))
        rc0 = R_of(c)
        rc1 = R_of(c1)
        if time.process_time() < slice_dl - 0.5:
            c1p = _lbfgs_all_pos(c1, 200, slice_dl - 0.3, beta=1e7)
            rc1p = R_of(c1p)
            if rc1p > rc1:
                c1, rc1 = c1p, rc1p
        c_use = c1 if rc1 > rc0 else c

        h_lift = _rescale(np.repeat(c_use, 2))
        hl = _lbfgs_all_pos(h_lift, 400, min(deadline - 1.5, slice_dl + 3.0),
                            beta=1e6)
        hl = _lbfgs_all_pos(hl, 400, min(deadline - 1.5, slice_dl + 5.0),
                            beta=1e7)
        rl = R_of(hl)
        if rl > bestR + 1e-13:
            best, bestR, origin = hl.copy(), rl, 'qcycle%d' % cycle
            accepted_cycles += 1
            print("qcycle %d R(c)=%.9f R(c1)=%.9f R(hl)=%.9f ACCEPT R=%.9f"
                  % (cycle, rc0, rc1, rl, bestR))
        else:
            if rl > alt_bestR:
                alt_best, alt_bestR = hl.copy(), rl

    # ---- Phase 3: peak ladder + trailing beta=0 ----
    if time.process_time() < deadline - 2.0:
        ht = _peak_ladder(best, deadline - 1.0,
                          pads=(0.10, 0.08, 0.06, 0.04), iters=400)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pk'
            print("peak ladder NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 1.0:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+all0'
                print("trailing all0 NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    print("cycles=%d accepted=%d best_full=%.9f" %
          (cycle, accepted_cycles, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _resample_mass(h, N2):
    h = np.asarray(h, dtype=float)
    C = np.concatenate(([0.0], np.cumsum(h)))
    if C[-1] <= 0:
        return np.zeros(N2)
    q = np.linspace(0.0, 1.0, N2 + 1)
    xq = np.interp(q, C / C[-1], np.linspace(0.0, 1.0, h.size + 1))
    return h.sum() * np.diff(xq)


# ---------------- log-space phase ----------------

def _logspace_fun_grad(u, h_full, active):
    h = h_full.copy()
    hu = np.exp(np.clip(u, -30.0, 30.0))
    h[active] = hu
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(u.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(u.size)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    g_h = _backprop(gLf, h) + 2.0 / s
    g_u = g_h[active] * hu
    hh = float(np.dot(hu, hu))
    if hh > 0:
        c = float(np.dot(g_u, hu)) / hh
        g_u = g_u - c * hu
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, g_u


def _lbfgs_logspace(h0, thr, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    mxh = h.max()
    if mxh <= 0:
        return h0
    active = np.flatnonzero(h > thr * mxh)
    if active.size < 4:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    h_full = h.copy()

    def f(u):
        return _logspace_fun_grad(u, h_full, active)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    amax0 = _argmax_frac(best)

    # ---- Phase A: front-loaded peak-window beta ladder ----
    a_deadline = t0 + budget_seconds * 0.10
    for pad in (0.06, 0.04, 0.025):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.3f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- NEW Phase S: fine-scale widening at higher N to escape N-locked optimum ----
    # The prior program was locked at N=104992; resampling to a substantially
    # different N and re-optimising gives the optimiser new degrees of freedom.
    s_deadline = t0 + budget_seconds * 0.35
    for N2 in (140000, 180000):
        if time.process_time() >= s_deadline - 5.0:
            print("Phase S N2=%d skipped (time)" % N2)
            break
        h2 = _rescale(_resample_mass(best, N2))
        h2 = _lbfgs_all_pos(h2, 400, s_deadline - 3.0, beta=1e8)
        h2 = _lbfgs_all_pos(h2, 300, s_deadline - 1.5, beta=0.0)
        h2 = _peak_ladder(h2, s_deadline - 0.4, pads=(0.05, 0.03), iters=200)
        offer(h2, 'S-widen N2=%d' % N2)
    print("Phase S done R=%.9f N=%d" % (bestR, best.size))

    # ---- Phase R: prime-N mass-preserving resample ----
    r_deadline = t0 + budget_seconds * 0.60
    primes = (100003, 99991)
    for k, N2 in enumerate(primes):
        if k == 0:
            dl = r_deadline
        else:
            dl = t0 + budget_seconds * 0.85
        if time.process_time() >= dl - 6.0:
            print("Phase R N2=%d skipped (time)" % N2)
            continue
        R_before = bestR
        h2 = _rescale(_resample_mass(best, N2))
        h2 = _lbfgs_all_pos(h2, 600, dl - 4.0, beta=0.0)
        h2 = _lbfgs_all_pos(h2, 400, dl - 2.0, beta=1e8)
        h2 = _peak_ladder(h2, dl - 0.5, pads=(0.06, 0.04, 0.025), iters=300)
        r = R_of(h2)
        dR = r - R_before
        print("Phase R N2=%d R=%.9f dR=%.3e" % (N2, r, dR))
        offer(h2, 'R-resample N2=%d' % N2)
    print("Phase R done R=%.9f" % bestR)

    # ---- Phase L: log-space with exact max projection ----
    l_deadline = t0 + budget_seconds * 0.85
    n_accept = 0
    thrs = (1e-12, 1e-9, 1e-6)
    for rnd, thr in enumerate(thrs):
        if time.process_time() >= l_deadline - 6.0:
            print("L round %d skipped (time)" % rnd)
            break
        R_before = bestR
        n_active = int(np.sum(best > thr * best.max()))
        ht = _lbfgs_logspace(best, thr, 300, l_deadline - 4.0)
        win = _peak_window(ht, pad_frac=0.05, extra=128)
        ht = _lbfgs_block(ht, win, 200, l_deadline - 2.5, beta=1e7)
        ht = _lbfgs_all_pos(ht, 200, l_deadline - 1.0, beta=0.0)
        r = R_of(ht)
        dR = r - R_before
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            n_accept += 1
            print("L round %d thr=%.0e ACCEPT R=%.9f dR=%.3e n_active=%d"
                  % (rnd, thr, bestR, dR, n_active))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            print("L round %d thr=%.0e reject R=%.9f dR=%.3e n_active=%d"
                  % (rnd, thr, r, dR, n_active))
    print("Phase L done R=%.9f n_accept=%d N=%d" % (bestR, n_accept, best.size))

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.97
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_all_pos(best, 400, final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _resample(h, N2):
    n = len(h)
    if N2 == n:
        return h.copy()
    cum = np.concatenate(([0.0], np.cumsum(h)))
    M = cum[-1]
    if M <= 0:
        return np.ones(N2)
    edges = np.linspace(0.0, M, N2 + 1)
    mass = np.diff(edges)
    out = mass / (M / N2)
    return np.clip(out, 0.0, None)


def _stats(h):
    zf = float(np.mean(h <= 0))
    Lf = _knots(h)
    mx = Lf.max()
    nm5 = float(np.mean(Lf >= 0.95 * mx)) if mx > 0 else 0.0
    return zf, nm5


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        best = np.clip(np.asarray(start, dtype=float), 0, None)
        if best.sum() <= 0:
            best = np.ones(1024)
    else:
        best = np.ones(1024)
    best = _rescale(best)
    best_R = R_of(best)
    start_R = best_R
    print(f"init R={best_R:.6f} N={best.size}")

    def accept(cand):
        nonlocal best, best_R
        if cand is None:
            return False
        cand = np.clip(cand, 0, None)
        if cand.sum() <= 0:
            return False
        Rc = R_of(cand)
        if Rc > best_R + 1e-14:
            best = cand
            best_R = Rc
            return True
        return False

    rng = np.random.default_rng(987654321)

    # Short polish stack: beta=1e4 then exact-R 150 it, short peak ladder,
    # then exact-R 250 it.  Designed to be cheap enough for 2 trials/round.
    def short_stack(h2, end_time):
        if time.process_time() > end_time - 1.0:
            return h2
        h2 = _lbfgs_all_pos(h2, 150, end_time, beta=1e4)
        if time.process_time() > end_time - 1.0:
            return h2
        h2 = _lbfgs_all_pos(h2, 150, end_time, beta=0.0)
        if time.process_time() > end_time - 1.0:
            return h2
        h2 = _peak_ladder(h2, end_time, pads=(0.06, 0.04), iters=150)
        if time.process_time() > end_time - 1.0:
            return h2
        h2 = _lbfgs_all_pos(h2, 250, end_time, beta=0.0)
        return h2

    # Reserve last 20% of budget for one long polish.
    main_end = t0 + budget_seconds * 0.73
    MAXN = 262144
    round_idx = 0

    while time.process_time() < main_end - 2.0 and best.size * 2 <= MAXN:
        round_idx += 1
        N2 = best.size * 2
        gained = False

        # (a) LIFT ROUND: 2 trials of Dirichlet([2,2]) interleave weights
        for trial in range(2):
            if time.process_time() > main_end - 2.0:
                break
            w = rng.dirichlet([2.0, 2.0])
            h2 = np.repeat(best, 2) * np.tile(w, best.size)
            h2 = _rescale(h2)
            h2 = short_stack(h2, main_end)
            if accept(h2):
                gained = True
                zf, nm5 = _stats(best)
                print(f"LIFT round={round_idx} trial={trial} N={best.size} "
                      f"R={best_R:.6f} zf={zf:.3f} nm5={nm5:.4f}")
                break
            else:
                zf, nm5 = _stats(h2)
                print(f"LIFT round={round_idx} trial={trial} N={h2.size} "
                      f"noimp R={best_R:.6f} zf={zf:.3f} nm5={nm5:.4f}")

        if gained:
            continue

        # (b) Fall back once to split-refine lift
        if time.process_time() < main_end - 2.0:
            h2 = _resample(best, N2)
            k = np.array([0.25, 0.5, 0.25])
            h2 = np.convolve(h2, k, mode='same')
            h2 = _rescale(h2)
            h2 = short_stack(h2, main_end)
            if accept(h2):
                zf, nm5 = _stats(best)
                print(f"SPLIT round={round_idx} N={best.size} R={best_R:.6f} "
                      f"zf={zf:.3f} nm5={nm5:.4f}")
                continue
            else:
                print(f"SPLIT round={round_idx} noimp R={best_R:.6f}")

        # Nothing worked this round; stop lifting.
        print(f"STALL round={round_idx} R={best_R:.6f} N={best.size}")
        break

    # ---- Final long polish (last ~20% of budget) ----
    final_end = t0 + budget_seconds * 0.95
    if time.process_time() < final_end - 1.0:
        ht = _lbfgs_all_pos(best, 800, final_end, beta=0.0)
        accept(ht)
    if time.process_time() < final_end - 0.5:
        hp = _peak_ladder(best, final_end,
                          pads=(0.08, 0.05, 0.03), iters=300)
        accept(hp)

    if best_R < start_R - 1e-12:
        best = np.asarray(start, dtype=float)
        best_R = start_R

    zf, nm5 = _stats(best)
    print(f"final best_R={R_of(best):.6f} N={best.size} "
          f"zf={zf:.3f} nm5={nm5:.4f}")
    return {"best": best}

