def _fun_grad_tie(h):
    """Tie-averaged Clarke subgradient over all near-tied max knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- tie-averaged polish loop until 45 s ----
    loop_end = t0 + min(budget_seconds * 0.75, 45.0)
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 8.0)
        h_t = _lbfgs_all_pos(best, 600, slice_end - 3.0, tie=True)
        r_t = R_of(h_t)
        dR = r_t - bestR
        accepted = r_t > bestR + 1e-15
        if accepted:
            best, bestR = h_t.copy(), r_t
        print("tie pass %d N=%d dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f nearmax5=%.4f"
              % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                 bestR, _tie_count(h_t), _zero_frac(h_t),
                 _nearmax_frac(h_t)))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=250, tie=True)
            r_t = R_of(h_t)
            dR = r_t - bestR
            accepted = r_t > bestR + 1e-15
            if accepted:
                best, bestR = h_t.copy(), r_t
            print("tie peak %d N=%d dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f nearmax5=%.4f"
                  % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                     bestR, _tie_count(h_t), _zero_frac(h_t),
                     _nearmax_frac(h_t)))

    # ---- final: tie-averaged full pass, then single-argmax to reject artifacts ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 4.0:
        h_t = _lbfgs_all_pos(best, 600, fd - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL argmax no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0.0, None)
    mx = Lc.max()
    if mx <= 0:
        return _fun_grad(h)
    r = Lc / mx
    S = np.sum(r ** p)
    if S <= 0:
        return _fun_grad(h)
    sm = mx * (S / Lc.size) ** (1.0 / p)
    if sm <= 0:
        return _fun_grad(h)
    w = (r ** (p - 1)) / np.sum(r ** (p - 1))
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, pnorm=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if pnorm is not None:
        fg = (lambda hh: _fun_grad_pnorm(hh, pnorm))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _smooth_peak_ladder(h, deadline, betas=(2e5, 5e5, 1e6, 3e6, 1e7, 0.0),
                        iters=400):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def _peak_polish(h, deadline, pads=(0.30, 0.18, 0.10, 0.06, 0.035), iters=500):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        for beta in (3e6, 1e7, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
    return h


def _pnorm_ladder(h, deadline, ps=(4.0, 8.0, 16.0, 32.0), iters=300):
    """Power-mean surrogate ladder: converges toward max (p->inf) but smoother."""
    for p in ps:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, pnorm=p)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def _asym_split(h, sigma, rng):
    n = h.size
    w0 = np.exp(sigma * rng.standard_normal(n))
    w1 = np.exp(sigma * rng.standard_normal(n))
    m = 0.5 * (w0 + w1)
    w0 /= m
    w1 /= m
    h2 = np.empty(2 * n)
    h2[0::2] = h * w0
    h2[1::2] = h * w1
    return _rescale(h2)


def _fold_mean(h2):
    return _rescale(0.5 * (h2[0::2] + h2[1::2]))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        h = np.ones(2048)
        h = _lbfgs_all_pos(h, 800, deadline - 1.0, beta=0.0)
        h = _smooth_peak_ladder(h, deadline - 0.5)
        return h

    cur = start_arr.copy()

    # Stage 1: p-norm surrogate ladder + sharp, cheap but effective.
    cur = _pnorm_ladder(cur, deadline - 3.0)
    cur = _smooth_peak_ladder(cur, deadline - 3.0)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("smooth R=%.8f" % best_r)

    # Stage 2: peak polish.
    cur = _peak_polish(cur, deadline - 1.5)
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r
        print("peak   R=%.8f" % best_r)

    # Stage 3: asymmetric 2N split exploration loop (main local-search engine).
    rng = np.random.default_rng(987654321)
    N = best.size
    round_no = 0
    while time.process_time() < deadline - 12.0:
        round_no += 1
        h2 = _asym_split(best, sigma=0.5, rng=rng)
        h2 = _lbfgs_all_pos(h2, 120, deadline - 8.0, beta=0.0)
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 8.0:
                break
            ht = _lbfgs_all_pos(h2, 120, deadline - 8.0, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-15:
                h2 = ht
        for pad in (0.12, 0.08, 0.05):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(h2, pad_frac=pad, extra=128)
            for beta in (1e6, 1e7, 0.0):
                if time.process_time() >= deadline - 8.0:
                    break
                ht = _lbfgs_block(h2, win, 120, deadline - 8.0, beta=beta)
                if R_of(ht) > R_of(h2) + 1e-15:
                    h2 = ht
        r2 = R_of(h2)
        hf = _fold_mean(h2)
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 8.0:
                break
            ht = _lbfgs_all_pos(hf, 120, deadline - 8.0, beta=beta)
            if R_of(ht) > R_of(hf) + 1e-15:
                hf = ht
        for pad in (0.08, 0.05):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(hf, pad_frac=pad, extra=128)
            for beta in (1e6, 1e7, 0.0):
                if time.process_time() >= deadline - 8.0:
                    break
                ht = _lbfgs_block(hf, win, 120, deadline - 8.0, beta=beta)
                if R_of(ht) > R_of(hf) + 1e-15:
                    hf = ht
        rf = R_of(hf)
        if rf > best_r + 1e-15:
            best, best_r = hf.copy(), rf
            print("NEW BEST R=%.8f (2N R=%.8f, round %d)" % (best_r, r2, round_no))

    # Stage 4: final sharp ladder + p-norm + small peak polish.
    if time.process_time() < deadline - 0.5:
        for beta in (1e8, 1e9, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 0.3, beta=beta)
            if R_of(ht) > best_r + 1e-15:
                best, best_r = ht, R_of(ht)
                print("final  R=%.8f" % best_r)
    if time.process_time() < deadline - 0.5:
        cand = _pnorm_ladder(best, deadline - 0.3, ps=(16.0, 64.0), iters=200)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
            print("pnorm  R=%.8f" % best_r)
    if time.process_time() < deadline - 0.5:
        cand = _peak_polish(best, deadline - 0.3, pads=(0.05, 0.03), iters=300)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
            print("polish R=%.8f" % best_r)

    if start_arr is not None and R_of(start_arr) >= best_r:
        return start_arr
    if start_arr is not None and not np.allclose(best, start_arr, rtol=0, atol=0):
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _resample(h, N2):
    n = len(h)
    if N2 == n:
        return h.copy()
    cum = np.concatenate(([0.0], np.cumsum(h)))
    M = cum[-1]
    if M <= 0:
        return np.ones(N2)
    edges = np.linspace(0.0, M, N2 + 1)
    mass = np.diff(edges)
    out = mass / (M / N2)
    return np.clip(out, 0.0, None)


def _stats(h):
    zf = float(np.mean(h <= 0))
    Lf = _knots(h)
    mx = Lf.max()
    nm5 = float(np.mean(Lf >= 0.95 * mx)) if mx > 0 else 0.0
    return zf, nm5


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        best = np.clip(np.asarray(start, dtype=float), 0, None)
        if best.sum() <= 0:
            best = np.ones(1024)
    else:
        best = np.ones(1024)
    best = _rescale(best)
    best_R = R_of(best)
    start_R = best_R
    print(f"init R={best_R:.6f} N={best.size}")

    def accept(cand):
        nonlocal best, best_R
        if cand is None:
            return False
        cand = np.clip(cand, 0, None)
        if cand.sum() <= 0:
            return False
        Rc = R_of(cand)
        if Rc > best_R + 1e-14:
            best = cand
            best_R = Rc
            return True
        return False

    rng = np.random.default_rng(987654321)

    # Cheaper per-trial polish: exact-R 80, peak ladder (0.05,0.03) 80 it,
    # exact-R 120.  No beta passes inside trials.
    def short_stack(h2, end_time):
        if time.process_time() > end_time - 1.0:
            return h2
        h2 = _lbfgs_all_pos(h2, 80, end_time, beta=0.0)
        if time.process_time() > end_time - 1.0:
            return h2
        h2 = _peak_ladder(h2, end_time, pads=(0.05, 0.03), iters=80)
        if time.process_time() > end_time - 1.0:
            return h2
        h2 = _lbfgs_all_pos(h2, 120, end_time, beta=0.0)
        return h2

    # Reserve last 14 s for one long polish.
    reserve = 14.0
    main_end = t0 + max(budget_seconds - reserve, budget_seconds * 0.5)
    MAXN = 262144
    round_idx = 0

    while time.process_time() < main_end - 2.0 and best.size * 2 <= MAXN:
        round_idx += 1
        N2 = best.size * 2
        gained = False

        # (a) LIFT ROUND: 3 trials of Dirichlet([2,2]) interleave weights
        for trial in range(3):
            if time.process_time() > main_end - 2.0:
                break
            w = rng.dirichlet([2.0, 2.0])
            h2 = np.repeat(best, 2) * np.tile(w, best.size)
            h2 = _rescale(h2)
            h2 = short_stack(h2, main_end)
            if accept(h2):
                gained = True
                zf, nm5 = _stats(best)
                print(f"LIFT round={round_idx} trial={trial} N={best.size} "
                      f"R={best_R:.6f} zf={zf:.3f} nm5={nm5:.4f}")
                break
            else:
                zf, nm5 = _stats(h2)
                print(f"LIFT round={round_idx} trial={trial} N={h2.size} "
                      f"noimp R={best_R:.6f} zf={zf:.3f} nm5={nm5:.4f}")

        if gained:
            continue

        # (b) Fall back once to split-refine lift
        if time.process_time() < main_end - 2.0:
            h2 = _resample(best, N2)
            k = np.array([0.25, 0.5, 0.25])
            h2 = np.convolve(h2, k, mode='same')
            h2 = _rescale(h2)
            h2 = short_stack(h2, main_end)
            if accept(h2):
                zf, nm5 = _stats(best)
                print(f"SPLIT round={round_idx} N={best.size} R={best_R:.6f} "
                      f"zf={zf:.3f} nm5={nm5:.4f}")
                continue
            else:
                print(f"SPLIT round={round_idx} noimp R={best_R:.6f}")

        # Nothing worked this round; stop lifting.
        print(f"STALL round={round_idx} R={best_R:.6f} N={best.size}")
        break

    # ---- Final long polish (last ~14 s) ----
    final_end = t0 + budget_seconds * 0.95
    if time.process_time() < final_end - 1.0:
        ht = _lbfgs_all_pos(best, 800, final_end, beta=0.0)
        accept(ht)
    if time.process_time() < final_end - 0.5:
        hp = _peak_ladder(best, final_end,
                          pads=(0.06, 0.04), iters=250)
        accept(hp)

    if best_R < start_R - 1e-12:
        best = np.asarray(start, dtype=float)
        best_R = start_R

    zf, nm5 = _stats(best)
    print(f"final best_R={R_of(best):.6f} N={best.size} "
          f"zf={zf:.3f} nm5={nm5:.4f}")
    return {"best": best}

