    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


_LOG_LO = -25.0
_LOG_HI = 12.0


def _lbfgs_logall(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    hmax = h.max()
    if hmax <= 0:
        return h0
    active = np.flatnonzero(h > 1e-12 * hmax)
    if active.size == 0:
        return h0
    u0 = np.log(np.maximum(h[active], 1e-300))
    u0 = np.clip(u0, _LOG_LO, _LOG_HI)
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, _LOG_LO, _LOG_HI))
        val, g = fg(hh)
        gu = g[active] * hh[active]
        return val, gu

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(_LOG_LO, _LOG_HI)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, _LOG_LO, _LOG_HI))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hmax = h.max()
    if hmax <= 0:
        return h0
    mask = h[active] > 1e-12 * hmax
    if not np.any(mask):
        return h0
    sub = active[mask]
    u0 = np.clip(np.log(np.maximum(h[sub], 1e-300)), _LOG_LO, _LOG_HI)
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        hh = h.copy()
        hh[sub] = np.exp(np.clip(u, _LOG_LO, _LOG_HI))
        val, g = fg(hh)
        return val, g[sub] * hh[sub]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(_LOG_LO, _LOG_HI)] * sub.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[sub] = np.exp(np.clip(res.x, _LOG_LO, _LOG_HI))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _active_frac(h, thresh=1e-8):
    hmax = h.max()
    if hmax <= 0:
        return 0.0
    return float(np.mean(h > thresh * hmax))


def _block_means(h, B):
    N = h.size
    nb = N // B
    if nb == 0:
        return None, 0
    return h[:nb * B].reshape(nb, B).mean(axis=1), nb


def _random_split(best, B, rng, alpha=2.0, jitter=0.0):
    """Break the B-fold staircase: random Dirichlet subcell weights per block."""
    N = best.size
    nb = N // B
    if nb == 0:
        return None
    b, nb = _block_means(best, B)
    h = best.copy()
    for j in range(nb):
        w = rng.dirichlet(np.full(B, alpha))
        if jitter > 0:
            w = w * np.exp(rng.normal(0.0, jitter, size=B))
            sw = w.sum()
            if sw > 0:
                w = w / sw
        h[j * B:(j + 1) * B] = b[j] * w * B
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, active1e-8=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _active_frac(best)))

    rng = np.random.default_rng(20240117)

    B = 32
    N = best.size
    nb = N // B
    print("block split: B=%d nb=%d N=%d" % (B, nb, N))

    # Reserve last 12 s for long polish + full peak ladder.
    polish_start = t0 + budget_seconds * 0.90 - 12.0
    trial_end = polish_start

    # ---- randomized subcell split trials ----
    max_trials = 6
    for trial in range(max_trials):
        if time.process_time() >= trial_end - 1.0:
            break
        slice_end = min(trial_end, time.process_time() + 6.5)
        alpha = 2.0 if trial % 2 == 0 else 1.0
        jitter = 0.0 if trial == 0 else 0.15
        try:
            cand = _random_split(best, B, rng, alpha=alpha, jitter=jitter)
        except Exception:
            continue
        if cand is None or cand.size != N:
            continue
        candR0 = R_of(cand)
        # polish: linear L-BFGS, then peak ladder, then linear again
        cand = _lbfgs_all_pos(cand, 300, slice_end - 3.5, beta=0.0)
        if time.process_time() < slice_end - 2.5:
            cand = _peak_ladder(cand, slice_end - 1.5,
                                pads=(0.06, 0.04), iters=200)
        if time.process_time() < slice_end - 1.0:
            cand = _lbfgs_all_pos(cand, 400, slice_end - 0.1, beta=0.0)
        cR = R_of(cand)
        dR = cR - bestR
        if cR > bestR + 1e-15:
            best, bestR = cand.copy(), cR
            print("split trial %d alpha=%.1f jit=%.2f N=%d dR=%+.3e NEW BEST R=%.9f zero_frac=%.4f nearmax5=%.4f"
                  % (trial, alpha, jitter, best.size, dR, bestR,
                     _zero_frac(best), _nearmax_frac(best)))
        else:
            print("split trial %d alpha=%.1f jit=%.2f N=%d dR=%+.3e no gain (R=%.9f vs %.9f, init %.9f) zero_frac=%.4f nearmax5=%.4f"
                  % (trial, alpha, jitter, cand.size, dR, cR, bestR, candR0,
                     _zero_frac(cand), _nearmax_frac(cand)))

    # ---- reserved long polish ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 0.5:
        ht = _lbfgs_all_pos(best, 800, fd, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL linear800 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _peak_ladder(best, fd, pads=(0.06, 0.04, 0.03), iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL peak ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _lbfgs_logall(best, 400, fd, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL log beta0 ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, active1e-8=%.4f)"
          % (bestR, startR, best.size, _zero_frac(best), _nearmax_frac(best),
             _active_frac(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(n)
        num, dq, Lf = _num_and_dq(hh)
        if beta > 0:
            mx = Lf.max()
            e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
            Z = e.sum()
            w = e / Z
            sm = mx + np.log(Z) / beta
            gLf = -dq / num + w / sm
            val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
        else:
            m = int(np.argmax(Lf))
            Lm = Lf[m]
            gLf = -dq / num
            gLf[m] += 1.0 / Lm
            val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        grad = _backprop(gLf, hh) + 2.0 / s
        return val, grad

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _refine_resample(h, deadline, rng, tries=6):
    """Try a finer resolution: resample h at higher N with smoothing, then polish."""
    best = h
    bestR = R_of(h)
    N0 = h.size
    for fac in (2.0, 1.5, 3.0):
        if time.process_time() >= deadline - 1.0:
            break
        N1 = min(1000000, int(round(N0 * fac)))
        if N1 <= N0:
            continue
        # linear interpolation of step heights onto finer grid
        xi = (np.arange(N1) + 0.5) / N1 * N0 - 0.5
        xi = np.clip(xi, 0, N0 - 1)
        lo = np.floor(xi).astype(int)
        hi = np.minimum(lo + 1, N0 - 1)
        w = xi - lo
        h1 = h[lo] * (1 - w) + h[hi] * w
        h1 = _rescale(h1)
        r1 = R_of(h1)
        # quick polish
        ht = _lbfgs_all_pos(h1, 400, deadline - 0.5, beta=0.0)
        rt = R_of(ht)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Resolution refinement: resample finer, then polish ----
    ht, r = _refine_resample(best, t0 + budget_seconds * 0.35, rng)
    if r > bestR + 1e-14:
        best, bestR = ht, r
        print("RESAMPLE ACCEPT R=%.9f N=%d" % (bestR, best.size))
    else:
        print("RESAMPLE reject R=%.9f" % r)

    # ---- Long L-BFGS-B descent ----
    long_deadline = t0 + budget_seconds * 0.70
    ht = _lbfgs_all_pos(best, 20000, long_deadline, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht, r
        print("LONG run ACCEPT R=%.9f dR=%.3e" % (bestR, r - bestR))
    else:
        print("LONG run reject R=%.9f" % r)

    # ---- Peak ladder with tight windows ----
    peak_deadline = t0 + budget_seconds * 0.90
    for pad in (0.08, 0.05, 0.03, 0.02, 0.01):
        if time.process_time() >= peak_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        active = win
        # restricted L-BFGS-B on the window
        if time.process_time() >= peak_deadline - 0.3:
            break
        h = best.copy()
        x0 = h[active].copy()

        def f(x, h=h, active=active):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            return _fun_grad(hh)

        cb = _make_cb(peak_deadline - 0.2)
        try:
            res = minimize(f, x0, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * active.size,
                           callback=cb,
                           options={'maxiter': 600, 'maxfun': 1200,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            h2 = h.copy()
            h2[active] = np.clip(res.x, 0.0, None)
            h2 = _rescale(h2)
            r2 = R_of(h2)
            if r2 > bestR + 1e-14:
                best, bestR = h2, r2
                print("PEAK pad=%.2f ACCEPT R=%.9f" % (pad, bestR))
        except (TimeoutError, Exception):
            pass

    # ---- Final fine polish: neighborhood around argmax ----
    if time.process_time() < t0 + budget_seconds * 0.95 - 0.5:
        ht = _lbfgs_all_pos(best, 300, t0 + budget_seconds * 0.95, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("FINAL ACCEPT R=%.9f" % bestR)

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best), amax1, _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = start_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, deadline, frac=0.4, extra=256, maxiter=400, beta=0.0):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.9995 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=40):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    A = np.flatnonzero(L >= (1.0 - kappa) * mx)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx

    def Jd(d):
        if n > 1500:
            cd = fftconvolve(h, d)
        else:
            cd = np.convolve(h, d)
        return 2.0 * cd[A - 1]

    def JT(y):
        yp = np.zeros(2 * n - 1)
        idx = A - 1
        yp[idx] = y
        if n > 1500:
            c = fftconvolve(yp, h[::-1], mode='valid')
        else:
            c = np.correlate(yp, h, mode='valid')
        out = np.zeros(n)
        m = min(n, c.size)
        out[:m] = 2.0 * c[:m]
        return out

    b = JT(r)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Ap = Jd(p)
        Ap = JT(Ap) + lam * p
        pAp = p @ Ap
        if pAp <= 0:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-12 * bn * bn:
            break
        p = res + (rs_new / rs) * p
        rs = rs_new
    return d


def _gn_polish(h, deadline, kappa=0.02, lam_scale=1e-3, rounds=6):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() > deadline - 0.5:
            break
        d = _gn_step(best, kappa, lam_scale, deadline)
        if d is None:
            break
        improved = False
        step = 1.0
        for _ in range(6):
            cand = np.clip(best + step * d, 0.0, None)
            if cand.sum() <= 0:
                step *= 0.5
                continue
            cand = _rescale(cand)
            rr = R_of(cand)
            if rr > bestR + 1e-13:
                best, bestR = cand, rr
                improved = True
                break
            step *= 0.5
        if not improved:
            if lam_scale < 1.0:
                lam_scale *= 10.0
            else:
                break
    return best, bestR


def _prolong(h, factor=2):
    n = h.size
    m = n * factor
    xp = (np.arange(n) + 0.5) / n
    xq = (np.arange(m) + 0.5) / m
    return np.interp(xq, xp, h)


def _restart_seed(start, N):
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float), 0, None)
        if s.size > 0 and s.sum() > 0:
            if s.size < N:
                # prolong by interpolation
                return _prolong(s, max(1, int(round(N / s.size))))
            return s.copy()
    i = np.arange(N, dtype=float)
    return 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
