        # Peak window with beta smoothing (helps flatten the maximum).
        h = _peak_window(best, deadline, frac=0.4, extra=256, maxiter=400, beta=200.0)
        rr = R_of(h)
        if rr > bestR + 1e-15:
            best, bestR = h, rr
            improved = True
            print("winB R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _peak_window(best, deadline, frac=0.15, extra=16, maxiter=300)
        rr = R_of(h)
        if rr > bestR + 1e-15:
            best, bestR = h, rr
            improved = True
            print("win R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h, rr = _gn_polish(best, deadline, kappa=0.02, lam_scale=1e-3, rounds=4)
        if rr > bestR + 1e-15:
