def _relift(q, s, r, N, best):
    """Relift quotient q back to length N with Dirichlet weights per block."""
    out = best.copy()
    nq = q.size
    # For each block j (output positions r + s*j .. r + s*j + s - 1)
    # fill with q[j] * w where w ~ Dirichlet(ones(s)+1)
    for j in range(nq):
        b = r + s * j
        if b >= N:
            break
        hi = min(N, b + s)
        k = hi - b
        w = np.random.dirichlet(np.ones(k) + 1.0)
        out[b:hi] = q[j] * w * k  # scale so mean ~ q[j]
    # cells before r (0..r-1) and after last block: keep best values
    return out


def _quotient_roundtrip(best, s, r, slice_end):
    N = best.size
    q = _quotient(best, s, r)
    if q.size < 8:
        return best
    # (b) polish q at reduced length
    q2 = _lbfgs_all_pos(q, 300, slice_end - 3.0, beta=1e5)
    if R_of(q2) > R_of(q):
        q = q2
    q2 = _lbfgs_all_pos(q, 300, slice_end - 2.0, beta=0.0)
    if R_of(q2) > R_of(q):
        q = q2
    if time.process_time() < slice_end - 1.5:
        q2 = _peak_ladder(q, slice_end - 0.8,
                          pads=(0.15, 0.08, 0.04), iters=250, tie=True)
        if R_of(q2) > R_of(q):
            q = q2
    # (c) relift
    h = _relift(q, s, r, N, best)
    h = _rescale(h)
    # (d) polish relifted
    if time.process_time() < slice_end - 0.5:
        h2 = _lbfgs_all_pos(h, 400, slice_end - 0.4, beta=1e5)
        if R_of(h2) > R_of(h):
            h = h2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- quotient round-trip sweep ----
    sweep = [(2, 1), (3, 1), (2, 1), (3, 2), (5, 1)]
    for (s, r) in sweep:
        if time.process_time() >= deadline - 6.0:
            break
        slice_end = min(deadline - 2.0, time.process_time() + 6.0)
        if slice_end <= time.process_time() + 1.0:
            break
        h_t = _quotient_roundtrip(best, s, r, slice_end)
        r_t = R_of(h_t)
        dR = r_t - bestR
        accepted = r_t > bestR + 1e-15
        if accepted:
            best, bestR = h_t.copy(), r_t
        print("quot s=%d r=%d N=%d dR=%+.3e %s R=%.9f zero_frac=%.4f nearmax5=%.4f ties=%d"
              % (s, r, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                 bestR, _zero_frac(h_t), _nearmax_frac(h_t),
                 _tie_count(h_t)))

    # ---- remaining time: alternating exact-R passes and peak ladder ----
    it = 0
    while time.process_time() < deadline - 4.0:
        it += 1
        slice_end = min(deadline - 2.0, time.process_time() + 8.0)
        h_t = _lbfgs_all_pos(best, 600, slice_end - 3.0, beta=0.0)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("exact pass %d dR=%+.3e R=%.9f" % (it, r_t - bestR, bestR))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.05, 0.03), iters=250, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("peak pass %d dR=%+.3e R=%.9f" % (it, r_t - bestR, bestR))
        if time.process_time() >= slice_end - 1.0:
            break

    # ---- final high-beta pass then exact-R pass ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 4.0:
        h_t = _lbfgs_all_pos(best, 600, fd - 2.5, beta=1e8)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL beta1e8 ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL beta1e8 no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, beta=0.0)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL exact ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL exact no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_band(h, lo, hi, Mfac=1.0, mode='ramp'):
    """Max-free objective rewarding the transition band [lo*M, hi*M] of f*f.

    We maximize S = sum_j w_j * g_j (quadrature-weighted) / s^2 where g = f*f
    knots and w_j is a tent/Gaussian weight peaking in the transition band.
    Gradient wrt heights via the same 1/3 quadrature derivative pattern,
    treating w as locally constant (its variation is second order).
    """
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Mfac * Lf.max()
    if M <= 0:
        return _fun_grad_tie(h)
    g = Lf
    if mode == 'gauss':
        w = np.exp(-((g - 0.8 * M) / (0.18 * M)) ** 2)
    else:
        w = np.clip((g - lo * M) / (M * (hi - lo + 1e-12)), 0.0, 1.0)
    # quadrature weights per knot: interior knots get (a+b)/3 style weight;
    # use dq-like pattern: d/dg_j of sum_j w_j g_j (trapz-like) -> w_j
    # We use the same 1/3 scheme: contribution of segment (a,b) is (a^2+ab+b^2)/3
    # but here we want a linear functional sum w*g, so derivative wrt knots is w.
    # Build gLf as derivative of -(sum w*g)/s^2 (we minimize negative).
    S = np.sum(w * g)
    if S <= 0:
        return _fun_grad_tie(h)
    # d(-S/s^2)/dg_j = -w_j / s^2
    gLf = -w / (s * s)
    grad = _backprop(gLf, h)
    # d/ds of -S/s^2 = +2S/s^3 ; plus we don't include the max term.
    # Add the s-derivative: dS/ds via chain is 0 (S depends on h not s directly),
    # but -S/s^2 has explicit s dependence: +2S/s^3 * ds/dh = 2S/s^3 * 1
    grad = grad + 2.0 * S / (s ** 3)
    val = -S / (s * s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_band(h0, maxiter, deadline, lo, hi, Mfac=1.0, mode='ramp'):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_band(hh, lo, hi, Mfac, mode)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _band_mass(h, lo=0.5, hi=0.98):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    M = mx
    g = Lf
    w = np.clip((g - lo * M) / (M * (hi - lo + 1e-12)), 0.0, 1.0)
    tot = g.sum()
    if tot <= 0:
        return 0.0
    return float(np.sum(w * g) / tot)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d, bandmass=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best), _band_mass(best)))

    # ---- band-driven loop until 45 s ----
    loop_end = t0 + min(budget_seconds * 0.75, 45.0)
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 8.0)
        h1 = best.copy()
        r0 = R_of(h1)
        bm0 = _band_mass(h1)
        # band passes
        h1 = _lbfgs_band(h1, 250, slice_end - 3.0, 0.5, 0.98, 1.0, 'ramp')
        if time.process_time() < slice_end - 2.5:
            h1 = _lbfgs_band(h1, 200, slice_end - 2.0, 0.7, 0.99, 1.0, 'ramp')
        if time.process_time() < slice_end - 1.8:
            h1 = _lbfgs_band(h1, 150, slice_end - 1.5, 0.5, 0.98, 1.0, 'gauss')
        bm1 = _band_mass(h1)
        # exact polish
        if time.process_time() < slice_end - 1.2:
            h1 = _lbfgs_all_pos(h1, 300, slice_end - 0.9, beta=1e5)
        if time.process_time() < slice_end - 0.7:
            h1 = _lbfgs_all_pos(h1, 300, slice_end - 0.5, beta=0.0)
        if time.process_time() < slice_end - 0.4:
            h1 = _peak_ladder(h1, slice_end - 0.2, pads=(0.06, 0.04), iters=200)
        r1 = R_of(h1)
        dR = r1 - bestR
        accepted = r1 > bestR + 1e-14
        if accepted:
            best, bestR = h1.copy(), r1
        print("band pass %d N=%d dR=%+.3e %s R=%.9f bandmass %.4f->%.4f nearmax5=%.4f ties=%d"
              % (it, h1.size, dR, "ACCEPT" if accepted else "no gain",
                 bestR, bm0, bm1, _nearmax_frac(best), _tie_count(best)))

    # ---- final: tie-averaged full pass, then single-argmax ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 4.0:
        h_t = _lbfgs_all_pos(best, 600, fd - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL argmax no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d, bandmass=%.4f)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best), _band_mass(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    """Soft-max tie-breaking: many knots near max get weight."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    beta = 1e5
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hmax = h.max()
    if hmax <= 0:
        return h0
    mask = h[active] > 1e-12 * hmax
    if not np.any(mask):
        return h0
    sub = active[mask]
    u0 = np.clip(np.log(np.maximum(h[sub], 1e-300)), -25.0, 12.0)
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        hh = h.copy()
        hh[sub] = np.exp(np.clip(u, -25.0, 12.0))
        val, g = fg(hh)
        return val, g[sub] * hh[sub]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-25.0, 12.0)] * sub.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[sub] = np.exp(np.clip(res.x, -25.0, 12.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h, tol=1e-6):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= (1.0 - tol) * mx))


def _detect_block(h):
    N = h.size
    for b in (32, 16, 8, 4, 2, 1):
        if N % b != 0:
            continue
        try:
            hb = h.reshape(-1, b)
        except Exception:
            continue
        if np.allclose(hb[:, 0][:, None], hb, rtol=1e-12, atol=1e-14):
            return b
    return 1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    b = _detect_block(best)
    print("base R=%.9f N=%d block=%d zero_frac=%.4f nearmax5=%.4f tie=%d"
          % (bestR, best.size, b, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    rng = np.random.default_rng(987654321)

    def _Rfine(hc, bb):
        return R_of(np.repeat(hc, bb))

    # coarse surrogate: R_of on the coarse array itself
    def _Rcoarse(hc):
        return R_of(hc)

    # ---- discrete spike-position search at coarse resolution ----
    sweep_end = t0 + budget_seconds * 0.72
    sweep = 0
    while time.process_time() < sweep_end - 2.0:
        sweep += 1
        hc = best.reshape(-1, b)[:, 0].copy()
        Nc = hc.size
        S = np.flatnonzero(hc > 0)
        if S.size == 0:
            break
        if S.size > 1200:
            S = rng.choice(S, size=1200, replace=False)
            S.sort()
        empty = np.flatnonzero(hc <= 0)
        if empty.size == 0:
            break

        cands = []  # (coarse_R, hc_cand, tag)

        def _try(hc_c):
            cands.append((_Rcoarse(hc_c), hc_c))

        # (a) shift i -> i+-1, i+-2 into empty
        for i in S:
            for d in (-2, -1, 1, 2):
                j = i + d
                if 0 <= j < Nc and hc[j] <= 0:
                    hc_c = hc.copy()
                    hc_c[j] = hc_c[i]
                    hc_c[i] = 0.0
                    _try(hc_c)
        # (b) move i to 2 random empty cells within +-8
        for i in S:
            lo = max(0, i - 8); hi = min(Nc, i + 9)
            loc_empty = empty[(empty >= lo) & (empty < hi)]
            if loc_empty.size == 0:
                continue
            for _ in range(2):
                j = int(rng.choice(loc_empty))
                hc_c = hc.copy()
                hc_c[j] = hc_c[i]
                hc_c[i] = 0.0
                _try(hc_c)
        # (c) swap i with 2 random j in S
        if S.size >= 2:
            for i in S:
                for _ in range(2):
                    j = int(rng.choice(S))
                    if j == i:
                        continue
                    hc_c = hc.copy()
                    hc_c[i], hc_c[j] = hc_c[j], hc_c[i]
                    _try(hc_c)
        # (d) split: half of hc[i] at adjacent empty
        for i in S:
            for d in (-1, 1):
                j = i + d
                if 0 <= j < Nc and hc[j] <= 0:
                    hc_c = hc.copy()
                    hc_c[j] = 0.5 * hc_c[i]
                    hc_c[i] = 0.5 * hc_c[i]
                    _try(hc_c)
        # (e) merge with adjacent nonzero
        for i in S:
            for d in (-1, 1):
                j = i + d
                if 0 <= j < Nc and hc[j] > 0:
                    hc_c = hc.copy()
                    hc_c[i] = hc_c[i] + hc_c[j]
                    hc_c[j] = 0.0
                    _try(hc_c)

        if not cands:
            break
        cands.sort(key=lambda t: -t[0])
        # top 40 by coarse surrogate
        top = cands[:40]
        # best per move type: approximate by taking first of each tag - tags not tracked,
        # so also include a few random ones
        extra = cands[40:60]
        top = top + extra

        best_cand = None
        best_cand_R = bestR
        for _, hc_c in top:
            if time.process_time() > sweep_end - 1.5:
                break
            hf_c = np.repeat(hc_c, b)
            r = R_of(hf_c)
            if r > best_cand_R + 1e-13:
                best_cand_R = r
                best_cand = hc_c

        n_eval = len(top)
        if best_cand is None:
            print("sweep %d: %d cands, no exact-fine improvement (bestR=%.9f)"
                  % (sweep, n_eval, bestR))
            # no acceptance; break to save time
            break

        # accept: re-optimize at coarse level with exact-R L-BFGS
        hc_opt = best_cand.copy()
        # coarse L-BFGS uses R_of on coarse array (surrogate); use fine exact via repeat
        # We'll do fine polish directly on repeated array
        hf = np.repeat(hc_opt, b)
        # coarse-level refine: optimize heights on coarse array using fine R
        # (use _lbfgs_block on repeated array restricted to nonzero coarse cells)
        nz = np.flatnonzero(hc_opt > 0)
        if nz.size > 0:
            # build fine free indices
            fine_free = np.concatenate([np.arange(i * b, (i + 1) * b) for i in nz])
            hf = _lbfgs_block(hf, fine_free, 120, sweep_end - 0.5, beta=1e4)
            hf = _lbfgs_block(hf, fine_free, 120, sweep_end - 0.4, beta=0.0)
        # full-array tie polish
        if time.process_time() < sweep_end - 0.3:
            hf = _lbfgs_all_pos(hf, 200, sweep_end - 0.2, tie=True)
        if time.process_time() < sweep_end - 0.2:
            hf = _peak_ladder(hf, sweep_end - 0.1, pads=(0.05, 0.03), iters=200)
        r_new = R_of(hf)
        dR = r_new - bestR
        if r_new > bestR + 1e-13:
            best = hf
            bestR = r_new
            print("sweep %d: %d cands, ACCEPT dR=%+.3e R=%.9f zero_frac=%.4f nearmax5=%.4f tie=%d"
                  % (sweep, n_eval, dR, bestR, _zero_frac(best),
                     _nearmax_frac(best), _tie_count(best)))
        else:
            print("sweep %d: %d cands, reject dR=%+.3e (R=%.9f vs %.9f)"
                  % (sweep, n_eval, dR, r_new, bestR))
            break

    # ---- final full polish ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 0.5:
        ht = _lbfgs_all_pos(best, 400, fd - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL beta0 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.4:
        ht = _lbfgs_all_pos(best, 300, fd - 0.2, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL tie ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.3:
        ht = _peak_ladder(best, fd - 0.1, pads=(0.08, 0.05, 0.03), iters=250)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f tie=%d)"
          % (bestR, startR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0.0, None)
    Lp = Lc ** p
    S = Lp.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = S ** (1.0 / p)
    if sm <= 0:
        return _fun_grad(h)
    w = Lc ** (p - 1) / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if free is None:
        active = np.arange(h.size)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- p-norm smoothing ladder (full) ----
    pnorm_deadline = t0 + budget_seconds * 0.55
    ps = (4, 8, 16, 32, 64, 128)
    per_p = budget_seconds * 0.09
    for p in ps:
        if time.process_time() >= pnorm_deadline - 1.0:
            break
        dp = min(pnorm_deadline, time.process_time() + per_p)
        fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
        ht = _lbfgs(best, None, 300, dp, fg)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("pnorm p=%d NEW BEST R=%.9f" % (p, bestR))

    # p-norm peak-window polish
    if time.process_time() < pnorm_deadline - 1.0:
        fg = (lambda hh: _fun_grad_pnorm(hh, 128))
        for pad in (0.08, 0.05, 0.03):
            if time.process_time() >= pnorm_deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs(best, win, 250, pnorm_deadline - 0.3, fg)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                print("pnorm peak NEW BEST R=%.9f" % bestR)

    # ---- final hard-max polish ----
    fd = t0 + budget_seconds * 0.90
    ht = _lbfgs(best, None, 800, fd, _fun_grad)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("FINAL beta0 ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        fg = (lambda hh: _fun_grad_beta(hh, 1e8))
        ht = _lbfgs(best, None, 400, fd, fg)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL beta8 ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _perturb(base, rng):
    """Random contiguous window scaled by a random factor."""
    h = base.copy()
    n = h.size
    lo_frac = 0.02
    hi_frac = 0.10
    wlen = int(n * rng.uniform(lo_frac, hi_frac))
    wlen = max(1, min(n, wlen))
    start_i = rng.integers(0, max(1, n - wlen + 1))
    factor = rng.choice([0.0, 0.5, 1.5])
    h[start_i:start_i + wlen] *= factor
    return _rescale(h)


def _resample(base, newN):
    n = base.size
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    h = np.interp(x_new, x_old, base)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- Build candidate starts ----
    rng = np.random.default_rng(12345)
    candidates = [best.copy()]
    for _ in range(6):
        candidates.append(_perturb(best, rng))
    try:
        candidates.append(_resample(best, max(1, best.size // 2)))
    except Exception:
        candidates.append(best.copy())

    # ---- Race candidates with a short slice each ----
    race_end = t0 + min(budget_seconds * 0.55, 33.0)
    best_cand = best.copy()
    best_candR = bestR
    best_cand_idx = 0

    for ci, cand in enumerate(candidates):
        if time.process_time() >= race_end - 1.0:
            print("cand %d skipped (time)" % ci)
            continue
        slice_end = min(race_end, time.process_time() + 4.0)
        h = cand.copy()
        r0 = R_of(h)
        h = _lbfgs_all_pos(h, 250, slice_end - 0.5, tie=True)
        if time.process_time() < slice_end - 0.5:
            h = _peak_ladder(h, slice_end - 0.3,
                             pads=(0.08, 0.05, 0.03), iters=150, tie=True)
        r = R_of(h)
        dR = r - best_candR
        if r > best_candR + 1e-15:
            best_cand = h.copy()
            best_candR = r
            best_cand_idx = ci
        print("cand %d N=%d dR=%+.3e R=%.9f zero_frac=%.4f ties=%d"
              % (ci, h.size, dR, r, _zero_frac(h), _tie_count(h)))

    print("race winner cand %d R=%.9f (base %.9f)"
          % (best_cand_idx, best_candR, bestR))

    if best_candR > bestR + 1e-15:
        best, bestR = best_cand.copy(), best_candR

    # ---- Full polish on best candidate ----
    loop_end = t0 + min(budget_seconds * 0.80, 48.0)
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 8.0)
        h_t = _lbfgs_all_pos(best, 600, slice_end - 3.0, tie=True)
        r_t = R_of(h_t)
        dR = r_t - bestR
        accepted = r_t > bestR + 1e-15
        if accepted:
            best, bestR = h_t.copy(), r_t
        print("tie pass %d N=%d dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f nearmax5=%.4f"
              % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                 bestR, _tie_count(h_t), _zero_frac(h_t),
                 _nearmax_frac(h_t)))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=250, tie=True)
            r_t = R_of(h_t)
            dR = r_t - bestR
            accepted = r_t > bestR + 1e-15
            if accepted:
                best, bestR = h_t.copy(), r_t
            print("tie peak %d N=%d dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f nearmax5=%.4f"
                  % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                     bestR, _tie_count(h_t), _zero_frac(h_t),
                     _nearmax_frac(h_t)))

    # ---- Final passes ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 4.0:
        h_t = _lbfgs_all_pos(best, 600, fd - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL argmax no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _resample_mass(h, Np):
    """Mass-preserving resample of step function h (length N) to length Np."""
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    t = np.linspace(0.0, N, Np + 1)
    cp = np.interp(t, np.arange(N + 1, dtype=float), c)
    hp = (Np / N) * np.diff(cp)
    return np.clip(hp, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N_base = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- resolution sweep ----
    sweep_end = t0 + min(budget_seconds * 0.80, 48.0)
    N_list = [26248, 32810, 35000, 43752, 52496, 61248, 70000, 78744, 91868]
    # also include the base N as a sanity reference
    N_list = [n for n in N_list if n != N_base]
    best_alt = None
    best_altR = -1.0

    sweep_it = 0
    while time.process_time() < sweep_end - 4.0:
        progressed = False
        for Np in N_list:
            if time.process_time() >= sweep_end - 4.0:
                break
            sweep_it += 1
            slice_end = min(sweep_end, time.process_time() + 6.0)
            hp = _resample_mass(best, Np)
            if hp.sum() <= 0:
                continue
            hp = _rescale(hp)
            r0 = R_of(hp)
            ht = _lbfgs_all_pos(hp, 400, slice_end - 2.0, tie=True)
            if time.process_time() < slice_end - 1.5:
                ht = _peak_ladder(ht, slice_end - 1.0,
                                  pads=(0.08, 0.05, 0.03), iters=200, tie=True)
            if time.process_time() < slice_end - 0.6:
                ht = _lbfgs_all_pos(ht, 150, slice_end - 0.2, tie=False)
            rt = R_of(ht)
            # track best at its own N (no relift)
            if rt > best_altR:
                best_alt, best_altR = ht.copy(), rt
            # accept into main best only if strictly better
            dR = rt - bestR
            accepted = rt > bestR + 1e-15
            if accepted:
                best, bestR = ht.copy(), rt
