import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _resample_mass(h, Np):
    """Mass-preserving resample of step function h (length N) to length Np."""
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    t = np.linspace(0.0, N, Np + 1)
    cp = np.interp(t, np.arange(N + 1, dtype=float), c)
    hp = (Np / N) * np.diff(cp)
    return np.clip(hp, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N_base = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- resolution sweep ----
    sweep_end = t0 + min(budget_seconds * 0.80, 48.0)
    N_list = [26248, 32810, 35000, 43752, 52496, 61248, 70000, 78744, 91868]
    # also include the base N as a sanity reference
    N_list = [n for n in N_list if n != N_base]
    best_alt = None
    best_altR = -1.0

    sweep_it = 0
    while time.process_time() < sweep_end - 4.0:
        progressed = False
        for Np in N_list:
            if time.process_time() >= sweep_end - 4.0:
                break
            sweep_it += 1
            slice_end = min(sweep_end, time.process_time() + 6.0)
            hp = _resample_mass(best, Np)
            if hp.sum() <= 0:
                continue
            hp = _rescale(hp)
            r0 = R_of(hp)
            ht = _lbfgs_all_pos(hp, 400, slice_end - 2.0, tie=True)
            if time.process_time() < slice_end - 1.5:
                ht = _peak_ladder(ht, slice_end - 1.0,
                                  pads=(0.08, 0.05, 0.03), iters=200, tie=True)
            if time.process_time() < slice_end - 0.6:
                ht = _lbfgs_all_pos(ht, 150, slice_end - 0.2, tie=False)
            rt = R_of(ht)
            # track best at its own N (no relift)
            if rt > best_altR:
                best_alt, best_altR = ht.copy(), rt
            # accept into main best only if strictly better
            dR = rt - bestR
            accepted = rt > bestR + 1e-15
            if accepted:
                best, bestR = ht.copy(), rt
                progressed = True
            print("sweep %d N'=%d r0=%.9f dR=%+.3e %s R=%.9f zero_frac=%.4f nearmax5=%.4f"
                  % (sweep_it, Np, r0, dR, "ACCEPT" if accepted else "no gain",
                     bestR, _zero_frac(ht), _nearmax_frac(ht)))
        if not progressed and time.process_time() > sweep_end - 4.0:
            break

    # ---- final re-polish of overall best ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 4.0:
        h_t = _lbfgs_all_pos(best, 600, fd - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL argmax no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    # If the sweep produced a genuinely different construction (different N)
    # that didn't beat start, still report it as alternative.
    if best_alt is not None and best_alt.size != best.size:
        result["alternative"] = best_alt
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

