def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _perturb(base, rng):
    h = base.copy()
    n = h.size
    lo_frac = 0.02
    hi_frac = 0.10
    wlen = int(n * rng.uniform(lo_frac, hi_frac))
    wlen = max(1, min(n, wlen))
    start_i = rng.integers(0, max(1, n - wlen + 1))
    factor = rng.choice([0.0, 0.5, 1.5])
    h[start_i:start_i + wlen] *= factor
    return _rescale(h)


def _resample(base, newN):
    n = base.size
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    h = np.interp(x_new, x_old, base)
    return _rescale(h)


# ---- Staircase helpers ----
def _expand(x, block):
    return np.repeat(x, block)


def _aggregate(g, block):
    return g.reshape(-1, block).sum(axis=1)


def _phi_grad_x(x, block):
    h = _expand(x, block)
    val, g = _fun_grad_tie(h)
    return val, _aggregate(g, block)


def _hessvec(x, v, block, eps=1e-4):
    _, g1 = _phi_grad_x(x + eps * v, block)
    _, g0 = _phi_grad_x(x - eps * v, block)
    return (g1 - g0) / (2.0 * eps)


def _lanczos_smallest(x, block, rng, m=25, deadline=None):
    n = x.size
    # restrict to top 60% by block gradient norm
    _, g = _phi_grad_x(x, block)
    gn = np.abs(g)
    thr = np.quantile(gn, 0.40)
    mask = gn >= thr
    idx = np.flatnonzero(mask)
    if idx.size < 4:
        idx = np.arange(n)
    r = rng.standard_normal(idx.size)
    v = np.zeros(n)
    v[idx] = r
    nv = np.linalg.norm(v)
    if nv <= 0:
        return 0.0, v
    v /= nv
    V = np.zeros((m + 1, n))
    V[0] = v
    alphas = np.zeros(m)
    betas = np.zeros(m)
    for j in range(m):
        if deadline is not None and time.process_time() > deadline:
            m = j
            break
        w = _hessvec(x, V[j], block)
        # restrict to idx subspace
        w[idx] = w[idx]
        w[~mask] = 0.0
        a = float(np.dot(w, V[j]))
        alphas[j] = a
        w = w - a * V[j]
        if j > 0:
            w = w - betas[j - 1] * V[j - 1]
        b = float(np.linalg.norm(w))
        betas[j] = b
        if b < 1e-12:
            m = j + 1
            break
        V[j + 1] = w / b
    m = max(1, m)
    T = np.diag(alphas[:m])
    for j in range(m - 1):
        T[j, j + 1] = betas[j]
        T[j + 1, j] = betas[j]
    try:
        evals, evecs = np.linalg.eigh(T)
    except Exception:
        return 0.0, v
    lam = float(evals[0])
    y = evecs[:, 0]
    vv = y @ V[:m]
    nvv = np.linalg.norm(vv)
    if nvv > 0:
        vv /= nvv
    return lam, vv


def _lbfgs_x(x0, block, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return x0
    x = np.clip(x0, 0, None)
    if x.sum() <= 0:
        return x0

    def f(xx):
        xxc = np.clip(xx, 0.0, None)
        h = _expand(xxc, block)
        if beta > 0:
            val, g = _fun_grad_beta(h, beta)
        else:
            val, g = _fun_grad_tie(h)
        return val, _aggregate(g, block)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return x0
    if res is None:
        return x0
    return np.clip(res.x, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- Staircase setup: detect block size ----
    block = 32
    N = best.size
    if N % block != 0:
        # fallback: use base program's approach
        block = 1
    nx = N // block
    x = best.reshape(nx, block).mean(axis=1)
    h_from_x = _expand(x, block)
    print("staircase block=%d nx=%d R(x)=%.9f" % (block, nx, R_of(h_from_x)))

    rng = np.random.default_rng(2024)

    # ---- Lanczos smallest eigenvalue ----
    lanc_deadline = time.process_time() + min(12.0, budget_seconds * 0.20)
    lam, v = _lanczos_smallest(x, block, rng, m=25, deadline=lanc_deadline)
    print("smallest Ritz value = %.6e" % lam)

    accepted = False
    if lam < 0 and np.linalg.norm(v) > 0:
        xnorm = np.linalg.norm(x)
        vnorm = np.linalg.norm(v)
        scale = xnorm / max(vnorm, 1e-30)
        for step in (0.01, 0.03, 0.1):
            if time.process_time() > deadline - 8.0:
                break
            for sign in (+1, -1):
                if time.process_time() > deadline - 8.0:
                    break
                xt = x + sign * step * scale * v
                xt = np.clip(xt, 0.0, None)
                if xt.sum() <= 0:
                    continue
                slice_end = min(deadline - 4.0, time.process_time() + 6.0)
                xt = _lbfgs_x(xt, block, 250, slice_end)
                ht = _expand(xt, block)
                ht = _rescale(ht)
                # peak ladder
                ht = _peak_ladder(ht, min(deadline - 1.0,
                                          time.process_time() + 4.0),
                                  pads=(0.08, 0.05, 0.03), iters=150, tie=True)
                rt = R_of(ht)
                dR = rt - bestR
                print("  trial step=%+.3f sign=%+d R=%.9f dR=%+.3e"
                      % (step, sign, rt, dR))
                if rt > bestR + 1e-15:
                    best, bestR = ht.copy(), rt
                    x = best.reshape(nx, block).mean(axis=1)
                    accepted = True
                    print("  ACCEPTED step=%+.3f sign=%+d R=%.9f"
                          % (step, sign, bestR))

    if not accepted:
        print("no curvature escape accepted; polishing base")

    # ---- Polish remaining time ----
    loop_end = t0 + budget_seconds * 0.88
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 6.0)
        h_t = _lbfgs_all_pos(best, 500, slice_end - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("polish %d ACCEPT R=%.9f" % (it, bestR))
        else:
            print("polish %d no gain R=%.9f" % (it, r_t))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=200, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("polish peak %d ACCEPT R=%.9f" % (it, bestR))

    # ---- Final passes ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 400, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- NEW IDEA: gradient-guided mass relocation on a coarse support ----
# The start is a fine-grained (N~105k) highly peaked construction. Most of the
# freedom that matters is in *where* mass sits on the support, not in tiny
# per-step tweaks. We coarsen to a moderate number of bins, optimise the bin
# heights globally with the exact R (via the same backprop on the coarse
# representation), and then upsample back. This changes the shape at a scale
# L-BFGS on the fine grid cannot reach in budget.

def _coarsen(h, nbins):
    n = h.size
    if nbins >= n:
        return h.copy()
    edges = np.linspace(0, n, nbins + 1).astype(int)
    out = np.empty(nbins)
    for i in range(nbins):
        a, b = edges[i], edges[i + 1]
        if b <= a:
            out[i] = 0.0
        else:
            out[i] = h[a:b].mean()
    return out


def _upsample(coarse, n):
    m = coarse.size
    if m >= n:
        return coarse[:n].copy()
    edges = np.linspace(0, n, m + 1).astype(int)
    out = np.empty(n)
    for i in range(m):
        a, b = edges[i], edges[i + 1]
        out[a:b] = coarse[i]
    return out


def _coarse_optimize(h, deadline, nbins_list=(2000, 4000, 8000, 300)):
    best = h.copy()
    bestR = R_of(best)
    n = h.size
    for nb in nbins_list:
        if time.process_time() >= deadline - 0.5:
            break
        if nb > n:
            continue
        c = _coarsen(best, nb)
        c = _rescale(c)
        # refine coarse representation with exact R and gradient
        c2 = _lbfgs_all_pos(c, 400, deadline - 0.4, beta=0.0)
        if time.process_time() < deadline - 0.4:
            c2 = _lbfgs_all_pos(c2, 400, deadline - 0.4, beta=1e6)
        up = _upsample(c2, n)
        up = _rescale(up)
        r = R_of(up)
        if r > bestR + 1e-13:
            best, bestR = up, r
        # also polish the upsampled fine version lightly
        if time.process_time() < deadline - 0.4:
            hp = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
            r = R_of(hp)
            if r > bestR + 1e-13:
                best, bestR = hp, r
    return best, bestR


def _insert_peak_step(h, deadline):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h, R_of(h)
    best = h.copy()
    bestR = R_of(best)
    Lf = _knots(best)
    m = int(np.argmax(Lf))
    n = best.size
    center = m
    tries = set()
    for off in (-3, -2, -1, 0, 1, 2, 3):
        p = center + off
        if 1 <= p < n:
            tries.add(p)
    for p in sorted(tries):
        if time.process_time() >= deadline - 0.2:
            break
        val = 0.5 * (best[p - 1] + best[p]) if p < n else best[p - 1]
        cand = np.concatenate([best[:p], [val], best[p:]])
        win = np.arange(max(0, p - 8), min(cand.size, p + 9))
        cand2 = _lbfgs_block(cand, win, maxiter=80, deadline=deadline, beta=0.0)
        r = R_of(cand2)
        if r > bestR + 1e-14:
            best, bestR = cand2, r
    return best, bestR


def _local_support_refine(h, deadline, rounds=6):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    best = h.copy()
    bestR = R_of(best)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.2:
            break
        num, dq, Lf = _num_and_dq(best)
        s = best.sum()
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, best) + 2.0 / s
        gn = np.linalg.norm(grad)
        if gn <= 0:
            break
        d = grad / gn
        improved = False
        for step in (1e-3, 3e-3, 1e-4, 3e-4):
            cand = best + step * d * best.mean()
            cand = np.clip(cand, 0, None)
            if cand.sum() <= 0:
                continue
            cand = _rescale(cand)
            r = R_of(cand)
            if r > bestR + 1e-14:
                best, bestR = cand, r
                improved = True
                break
        if not improved:
            break
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: polish the start.
    if time.process_time() < deadline - 2.0:
        best, bestR = run_cycle(best, bestR, deadline - 2.0)
        print("base cycle R=%.7f" % bestR)

    # Phase 2 (NEW): coarse-scale global reshape.
    if time.process_time() < deadline - 1.5:
        ht, rt = _coarse_optimize(best, deadline - 1.5)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            print("coarse reshape R=%.7f" % bestR)

    # Phase 3: insert steps near the peak (structural).
    n_insert = 0
    while time.process_time() < deadline - 1.5 and n_insert < 4:
        before = bestR
        ht, rt = _insert_peak_step(best, deadline - 1.2)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            best, bestR = run_cycle(best, bestR, deadline - 1.2)
        n_insert += 1
        print("insert %d: R=%.7f (dR=%.2e)" % (n_insert, bestR, bestR - before))
        if bestR - before < 1e-10:
            break

    # Phase 4: local coordinate-wise refine.
    if time.process_time() < deadline - 1.0:
        ht = _local_support_refine(best, deadline - 0.8, rounds=8)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r

    # Phase 5: final polish.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 600, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
