def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _gauss_smooth(h, sigma):
    if sigma <= 0:
        return h
    rad = int(3 * sigma) + 1
    x = np.arange(-rad, rad + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    pad = np.concatenate((np.zeros(rad), h, np.zeros(rad)))
    out = np.convolve(pad, k, mode='valid')
    return out


def _run_half_phase(c, cR, half_deadline, tag='h', max_rounds=1000):
    work_c = c.copy()
    best_c = c.copy()
    best_cR = cR
    rounds = 0
    while time.process_time() < half_deadline - 1.0 and rounds < max_rounds:
        work_c, best_c, best_cR, org = _half_cycle(
            work_c, best_cR, half_deadline, tag='%s%d' % (tag, rounds))
        rounds += 1
    return best_c, best_cR, rounds


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution polish (0-30%) ----
    N = best.size
    best_c = None
    best_cR = -1.0
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.30
        best_c, best_cR, rounds = _run_half_phase(c, cR, half_deadline, 'h')
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: smoothing perturbations (30-50%) ----
    if time.process_time() < deadline - 6.0:
        sigmas = [0.6, 1.2, 2.0, 3.0, 1.8, 0.9]
        si = 0
        while time.process_time() < deadline - 5.0:
            sigma = sigmas[si % len(sigmas)]
            si += 1
            hs = _rescale(_gauss_smooth(best, sigma))
            slice_deadline = min(deadline - 2.0,
                                 time.process_time() + 0.05 * budget_seconds)
            ht = hs
            for beta in [1e6, 1e7]:
                if time.process_time() >= slice_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 250, slice_deadline - 0.3, beta=beta)
            if time.process_time() < slice_deadline - 0.5:
                win = _peak_window(ht, pad_frac=0.12, extra=128)
                ht2 = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
                if R_of(ht2) > R_of(ht):
                    ht = ht2
            if time.process_time() < slice_deadline - 0.5:
                ht = _lbfgs_all_pos(ht, 250, slice_deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'smooth%d' % si
                print("smooth sigma=%.2f NEW BEST R=%.9f" % (sigma, bestR))
            else:
                if r > alt_bestR:
                    alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: perturb-then-polish restarts on half-res quotient ----
    restarts_done = 0
    if best_c is not None and time.process_time() < deadline - 4.0:
        rng = np.random.default_rng(7)
        amps = [0.008, 0.015, 0.03, 0.05]
        ri = 0
        while time.process_time() < deadline - 4.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc2 = best_c.copy()
            nz = cc2 > 0
            if nz.sum() == 0:
                break
            cc2[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc2 = _rescale(cc2)
            r0 = R_of(cc2)
            slice_deadline = min(deadline - 2.0,
                                 time.process_time() + 0.04 * budget_seconds)
            work_c2, cand_c, cand_cR, org = _half_cycle(
                cc2, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.15])
            restarts_done += 1
            if cand_cR > best_cR + 1e-12:
                best_c = cand_c.copy()
                best_cR = cand_cR
                print("restart %d amp=%.3f ACCEPT R(c)=%.9f" %
                      (ri, amp, best_cR))
            if time.process_time() >= deadline - 4.0:
                break

    # ---- Phase 4: lift best_c and full-N polish ----
    if best_c is not None:
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        if r_lift > bestR + 1e-14:
            best, bestR, origin = h_lift.copy(), r_lift, 'restart_lift'
            print("restart lift NEW BEST R=%.9f" % bestR)
        elif r_lift > alt_bestR:
            alt_best, alt_bestR = h_lift, r_lift
        ht = h_lift
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+full'
            print("full polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 5 (NEW): full-resolution perturb-then-polish restarts ----
    # In the remaining time, apply multiplicative noise directly to the
    # full-resolution best, then re-polish with the beta ladder and peak
    # window. This is a genuinely different neighbourhood from the
    # half-res restarts (which lose full-res freedom).
    fr_done = 0
    if time.process_time() < deadline - 3.0:
        rng = np.random.default_rng(12345)
        amps = [0.004, 0.008, 0.015, 0.025]
        fi = 0
        while time.process_time() < deadline - 2.5:
            amp = amps[fi % len(amps)]
            fi += 1
            hh = best.copy()
            nz = hh > 0
            if nz.sum() == 0:
                break
            hh[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            hh = _rescale(hh)
            slice_deadline = min(deadline - 1.5,
                                 time.process_time() + 0.05 * budget_seconds)
            ht = hh
            for beta in [1e6, 1e7]:
                if time.process_time() >= slice_deadline - 0.4:
                    break
                ht = _lbfgs_all_pos(ht, 200, slice_deadline - 0.25, beta=beta)
            if time.process_time() < slice_deadline - 0.4:
                win = _peak_window(ht, pad_frac=0.10, extra=128)
                ht2 = _lbfgs_block(ht, win, 300, slice_deadline - 0.25, beta=1e7)
                if R_of(ht2) > R_of(ht):
                    ht = ht2
            if time.process_time() < slice_deadline - 0.4:
                ht = _lbfgs_all_pos(ht, 200, slice_deadline - 0.25, beta=0.0)
            r = R_of(ht)
            fr_done += 1
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'fullrs%d' % fi
                print("full-res restart %d amp=%.3f NEW BEST R=%.9f" %
                      (fi, amp, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 6: fine peak polish on best ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    print("restarts=%d full_restarts=%d best_c=%.9f best_full=%.9f" %
          (restarts_done, fr_done, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize


def _R(L):
    L = np.asarray(L, dtype=float)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    l1 = L.sum()
    inf = L.max()
    if inf <= 0 or l1 <= 0:
        return 0.0
    return sq / (l1 * inf)


def _eval(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)) or h.sum() <= 0:
        return 0.0
    L = np.convolve(h, h)
    return _R(L)


def _cantor_intervals(level):
    # start with [0,1], each step split into 3 and keep outer two thirds
    ivs = [(0.0, 1.0)]
    for _ in range(level):
        new = []
        for a, b in ivs:
            w = (b - a) / 3.0
            new.append((a, a + w))
            new.append((b - w, b))
        ivs = new
    return ivs


def _rasterize(ivs, N, heights):
    # exact cell overlap
    h = np.zeros(N)
    for (a, b), val in zip(ivs, heights):
        if b <= a:
            continue
        lo = a * N
        hi = b * N
        i0 = int(np.floor(lo))
        i1 = int(np.ceil(hi))
        i0 = max(i0, 0)
        i1 = min(i1, N)
        for i in range(i0, i1):
            cell_lo = i
            cell_hi = i + 1
            ov = min(hi, cell_hi) - max(lo, cell_lo)
            if ov > 0:
                h[i] += val * ov
    return h


def _make_cantor(N, level, rho, rng, jitter=0.0):
    ivs = _cantor_intervals(level)
    hs = []
    for l in range(level + 1):
        pass
    # intervals are ordered; assign level by count
    # level l has 2^l intervals, total sum over levels = 2^(level+1)-1
    vals = []
    l = 0
    count = 0
    target = 2 ** l
    for _ in ivs:
        if count >= target:
            l += 1
            target = 2 ** l
            count = 0
        base = rho ** l
        if jitter > 0:
            base *= np.exp(rng.normal(0, jitter))
        vals.append(base)
        count += 1
    return _rasterize(ivs, N, vals)


def _obj_tie(h, N):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)) or h.sum() <= 0:
        return 1e6
    L = np.convolve(h, h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    l1 = L.sum()
    inf = L.max()
    if inf <= 0 or l1 <= 0:
        return 1e6
    R = sq / (l1 * inf)
    # tie: penalize variance of near-max knots
    return -R


def _polish(h, deadline, maxiter=300):
    N = len(h)
    x0 = np.asarray(h, dtype=float).copy()
    if x0.sum() <= 0:
        x0 = np.ones(N)
    x0 = x0 / x0.sum() * N

    def f(x):
        return _obj_tie(x, N)

    try:
        res = minimize(f, x0, method='L-BFGS-B',
                       bounds=[(0, None)] * N,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        x = np.clip(res.x, 0, None)
        if x.sum() > 0:
            return x
    except Exception:
        pass
    return x0


def _peak_ladder(h, deadline, best_R):
    N = len(h)
    cur = np.asarray(h, dtype=float).copy()
    cur_R = _eval(cur)
    for pad in (0.15, 0.08, 0.05):
        if time.process_time() > deadline:
            break
        try:
            L = np.convolve(cur, cur)
            mx = L.max()
            # beta penalty on knots above (1-pad)*mx
            thr = (1.0 - pad) * mx
            beta = 1e7

            def f(x):
                if not np.all(np.isfinite(x)) or x.sum() <= 0:
                    return 1e12
                Lx = np.convolve(x, x)
                sq = np.sum(Lx[:-1]**2 + Lx[:-1]*Lx[1:] + Lx[1:]**2) / 3.0
                l1 = Lx.sum()
                inf = Lx.max()
                if inf <= 0 or l1 <= 0:
                    return 1e12
                R = sq / (l1 * inf)
                pen = np.sum(np.maximum(Lx - thr, 0)**2)
                return -R + beta * pen / (mx**2 + 1e-12)

            res = minimize(f, cur, method='L-BFGS-B',
                           bounds=[(0, None)] * N,
                           options={'maxiter': 200, 'maxfun': 600})
            cand = np.clip(res.x, 0, None)
            if cand.sum() > 0:
                r = _eval(cand)
                if r > cur_R:
                    cur = cand
                    cur_R = r
        except Exception:
            pass
    return cur, cur_R


def _double_N(h):
    N = len(h)
    N2 = N * 2
    c = np.cumsum(h)
    total = c[-1]
    if total <= 0:
        return np.ones(N2)
    # mass-preserving: new cell i covers [i, i+1] in old coords / 2
    # new cell i (0..N2-1) spans old [i/2, (i+1)/2]
    xs = np.arange(N2 + 1) * 0.5
    # cumulative mass at xs
    cm = np.interp(xs, np.arange(N + 1), np.concatenate([[0], c]))
    m = np.diff(cm)
    # heights proportional to mass (width equal), scale to preserve mean
    new = m * 2.0
    if new.sum() <= 0:
        return np.ones(N2)
    return new


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    best = None
    best_R = -1.0

    def consider(h):
        nonlocal best, best_R
        h = np.asarray(h, dtype=float)
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return
        r = _eval(h)
        if r > best_R:
            best_R = r
            best = h.copy()

    # seed with start
    if start is not None:
        try:
            consider(np.asarray(start, dtype=float))
        except Exception:
            pass
    if best is None:
        best = np.ones(50)
        best_R = _eval(best)

    N0 = 2048
    rng = np.random.default_rng(12345)

    # race 3 seeds
    seeds = []
    for rho in (0.5, 0.7, 1.0):
        try:
            h = _make_cantor(N0, 4, rho, rng, jitter=0.0)
            seeds.append(h)
        except Exception:
            pass

    for si, h in enumerate(seeds):
        if time.process_time() > deadline:
            break
        try:
            h = _polish(h, deadline, 300)
            h, r = _peak_ladder(h, deadline, _eval(h))
            consider(h)
            print(f"seed rho={[0.5,0.7,1.0][si]} R={_eval(h):.6f} zero_frac={np.mean(h==0):.3f}")
        except Exception:
            pass

    # doubling ladder from best
    N = len(best)
    cur = best.copy()
    for target_N in (4096, 8192):
        if time.process_time() > deadline:
            break
        try:
            while len(cur) < target_N:
                cur = _double_N(cur)
            cur = _polish(cur, deadline, 300)
            cur, r = _peak_ladder(cur, deadline, _eval(cur))
            consider(cur)
            L = np.convolve(cur, cur)
            mx = L.max()
            nearmax5 = np.mean(L > 0.95 * mx)
            print(f"N={len(cur)} R={_eval(cur):.6f} zero_frac={np.mean(cur==0):.3f} nearmax5={nearmax5:.4f}")
        except Exception:
            pass

    # final safety: if best is still the input start and we have time, try more
    if time.process_time() < deadline and best_R < 0.7:
        try:
            h = _make_cantor(N0, 4, 0.6, rng, jitter=0.1)
            h = _polish(h, deadline, 300)
            consider(h)
        except Exception:
            pass

    if best is None:
        best = np.ones(50)
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _perturb_coarse(base, rng):
    h = base.copy()
    n = h.size
    kind = rng.integers(0, 3)
    if kind == 0:
        nb = int(rng.integers(8, 17))
        edges = np.linspace(0, n, nb + 1).astype(int)
        for b in range(nb):
            f = rng.uniform(0.7, 1.3)
            h[edges[b]:edges[b + 1]] *= f
    elif kind == 1:
        wlen = max(1, int(n * rng.uniform(0.02, 0.20)))
        s = rng.integers(0, max(1, n - wlen + 1))
        f = rng.choice([0.0, 0.5, 1.5])
        h[s:s + wlen] *= f
    else:
        wlen = max(1, int(n * 0.05))
        s = rng.integers(0, max(1, n - wlen + 1))
        m = h.mean() if h.mean() > 0 else 1.0
        h[s:s + wlen] = 1e-3 * m
    return _rescale(h)


def _detect_period(h):
    n = h.size
    mx = h.max() if h.size else 0.0
    if mx <= 0:
        return 1
    tol = 1e-12 * mx
    for p in range(2, 65):
        if n % p != 0:
            continue
        m = n // p
        blocks = h.reshape(p, m)
        if np.max(np.abs(blocks - blocks[0])) < tol:
            return p
    return 1


def _resample(base, newN):
    n = base.size
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    h = np.interp(x_new, x_old, base)
    return _rescale(h)


def _resample_mass(base, newN):
    """Mass-preserving resample via cumulative-sum interpolation.
    Keeps int f fixed (hence ||f*f||_1 fixed)."""
    n = base.size
    h = np.clip(base, 0, None)
    c = np.concatenate(([0.0], np.cumsum(h)))
    # cumulative mass at cell edges in [0,1]
    x_old = np.arange(n + 1) / n
    x_new = np.arange(newN + 1) / newN
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    h_new = np.clip(h_new, 0, None)
    if h_new.sum() <= 0:
        return _resample(base, newN)
    return _rescale(h_new)


def _coarse_gradient_ascent(h, deadline, iters=60, lr=0.05):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    best = h.copy()
    bestR = R_of(h)
    cur = h.copy()
    for _ in range(iters):
        if time.process_time() >= deadline - 0.3:
            break
        s = cur.sum()
        if s <= 0:
            break
        num, dq, Lf = _num_and_dq(cur)
        mx = Lf.max()
        if mx <= 0:
            break
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        grad = _backprop(gLf, cur) + 2.0 / s
        gn = np.linalg.norm(grad)
        if gn <= 0:
            break
        step = grad / gn
        scale = lr * np.linalg.norm(cur) / max(1.0, np.sqrt(cur.size))
        trial = np.clip(cur + scale * step, 0, None)
        trial = _rescale(trial)
        r = R_of(trial)
        if r > bestR + 1e-15:
            best, bestR = trial.copy(), r
            cur = trial
        else:
            cur = trial
            lr *= 0.7
            if lr < 1e-6:
                break
    return best


def _polish_at_N(h, deadline, label=""):
    """Run the full ladder (tie L-BFGS, beta ladder, tie peak ladder,
    plain argmax L-BFGS) at the current N."""
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    ht = _lbfgs_all_pos(best, 400, min(deadline - 0.5,
                                       time.process_time() + 12.0), tie=True)
    r = R_of(ht)
    if r > bestR + 1e-15:
        best, bestR = ht, r
    for beta in (1e6, 1e8):
        if time.process_time() >= deadline - 1.0:
            break
