    targets = [157489, 209984]
    # If base is not the expected size, scale targets proportionally
    if N0 != 104992:
        targets = [int(round(N0 * 1.5)), int(round(N0 * 2.0))]

    best = base.copy()
    bestR = startR
    bestN = N0
    alt_candidates = []

    # Split remaining time among candidates
    n_cand = len(targets)
    for ci, newN in enumerate(targets):
        if time.process_time() >= deadline - 2.0:
            break
