        remaining = deadline - time.process_time()
        slices_left = n_cand - ci
        slice_end = time.process_time() + remaining / slices_left

        cand = _resample_mass(base, newN)
        r0 = R_of(cand)
        print("cand N=%d resample R=%.9f (dR=%+.2e)"
              % (newN, r0, r0 - startR))

