import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _perturb_coarse(base, rng):
    h = base.copy()
    n = h.size
    kind = rng.integers(0, 3)
    if kind == 0:
        nb = int(rng.integers(8, 17))
        edges = np.linspace(0, n, nb + 1).astype(int)
        for b in range(nb):
            f = rng.uniform(0.7, 1.3)
            h[edges[b]:edges[b + 1]] *= f
    elif kind == 1:
        wlen = max(1, int(n * rng.uniform(0.02, 0.20)))
        s = rng.integers(0, max(1, n - wlen + 1))
        f = rng.choice([0.0, 0.5, 1.5])
        h[s:s + wlen] *= f
    else:
        wlen = max(1, int(n * 0.05))
        s = rng.integers(0, max(1, n - wlen + 1))
        m = h.mean() if h.mean() > 0 else 1.0
        h[s:s + wlen] = 1e-3 * m
    return _rescale(h)


def _detect_period(h):
    n = h.size
    mx = h.max() if h.size else 0.0
    if mx <= 0:
        return 1
    tol = 1e-12 * mx
    for p in range(2, 65):
        if n % p != 0:
            continue
        m = n // p
        blocks = h.reshape(p, m)
        if np.max(np.abs(blocks - blocks[0])) < tol:
            return p
    return 1


def _resample(base, newN):
    n = base.size
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    h = np.interp(x_new, x_old, base)
    return _rescale(h)


def _resample_mass(base, newN):
    """Mass-preserving resample via cumulative-sum interpolation.
    Keeps int f fixed (hence ||f*f||_1 fixed)."""
    n = base.size
    h = np.clip(base, 0, None)
    c = np.concatenate(([0.0], np.cumsum(h)))
    # cumulative mass at cell edges in [0,1]
    x_old = np.arange(n + 1) / n
    x_new = np.arange(newN + 1) / newN
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    h_new = np.clip(h_new, 0, None)
    if h_new.sum() <= 0:
        return _resample(base, newN)
    return _rescale(h_new)


def _coarse_gradient_ascent(h, deadline, iters=60, lr=0.05):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    best = h.copy()
    bestR = R_of(h)
    cur = h.copy()
    for _ in range(iters):
        if time.process_time() >= deadline - 0.3:
            break
        s = cur.sum()
        if s <= 0:
            break
        num, dq, Lf = _num_and_dq(cur)
        mx = Lf.max()
        if mx <= 0:
            break
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        grad = _backprop(gLf, cur) + 2.0 / s
        gn = np.linalg.norm(grad)
        if gn <= 0:
            break
        step = grad / gn
        scale = lr * np.linalg.norm(cur) / max(1.0, np.sqrt(cur.size))
        trial = np.clip(cur + scale * step, 0, None)
        trial = _rescale(trial)
        r = R_of(trial)
        if r > bestR + 1e-15:
            best, bestR = trial.copy(), r
            cur = trial
        else:
            cur = trial
            lr *= 0.7
            if lr < 1e-6:
                break
    return best


def _polish_at_N(h, deadline, label=""):
    """Run the full ladder (tie L-BFGS, beta ladder, tie peak ladder,
    plain argmax L-BFGS) at the current N."""
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    ht = _lbfgs_all_pos(best, 400, min(deadline - 0.5,
                                       time.process_time() + 12.0), tie=True)
    r = R_of(ht)
    if r > bestR + 1e-15:
        best, bestR = ht, r
    for beta in (1e6, 1e8):
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(best, 300,
                            min(deadline - 0.5, time.process_time() + 8.0),
                            beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    if time.process_time() < deadline - 1.0:
        ht = _peak_ladder(best, min(deadline - 0.3,
                                    time.process_time() + 10.0),
                          pads=(0.10, 0.06, 0.04), iters=200, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.2, tie=False)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    return best, bestR


