        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_band_candidate(h, side, w, e, cap_mult):
    """Replace a band at one edge with a capped inverse-power profile,
    rescaled to preserve the band's total mass."""
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size < 4:
        return None
    if side == 0:
        lo = nz[0]
        hi = min(h2.size, lo + w)
        idx = np.arange(lo, hi)
        if idx.size < 4:
            return None
        mass = h2[idx].sum()
        j = np.arange(idx.size, dtype=float) + 1.0
        prof = j ** (-e)
        cap = cap_mult * prof.mean()
        prof = np.minimum(prof, cap)
        ps = prof.sum()
        if ps <= 0:
            return None
        h2[idx] = prof * (mass / ps)
    else:
        hi = nz[-1]
        lo = max(0, hi - w + 1)
        idx = np.arange(lo, hi + 1)
        if idx.size < 4:
            return None
        mass = h2[idx].sum()
        j = np.arange(idx.size, dtype=float)[::-1] + 1.0
        prof = j ** (-e)
        cap = cap_mult * prof.mean()
        prof = np.minimum(prof, cap)
        ps = prof.sum()
        if ps <= 0:
            return None
        h2[idx] = prof * (mass / ps)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(h, org, tag="NEW BEST"):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR, origin = h.copy(), r, org
            print("  %s R=%.9f (%s)" % (tag, bestR, org))
        elif r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r

    # ---- Phase 0: direct beta-homotopy on the start ----
    if time.process_time() < deadline - 8.0:
        ht = best.copy()
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 8.0:
                break
            ht = _lbfgs_all_pos(ht, 250, deadline - 7.0, beta=beta)
            consider(ht, 'direct_beta%g' % beta, "direct")
        for pad in [0.06, 0.04, 0.03]:
            if time.process_time() >= deadline - 7.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=192)
            hp = _lbfgs_block(best, win, 350, deadline - 6.0, beta=1e7)
            consider(hp, 'direct_pk%g' % pad, "direct pk")

    # ---- Phase 1: edge-band inverse-power experiment ----
    N = best.size
    w = max(8, int(0.01 * N))
    exps = [0.35, 0.5, 0.65]
    caps = [30.0]
    edge_cands = []
    for side in (0, 1):
        for e in exps:
            for cm in caps:
                if time.process_time() >= deadline - 6.0:
                    break
                cand = _edge_band_candidate(best, side, w, e, cm)
                if cand is None:
                    continue
                # polish: full tie, then beta ladder on peak window, then tie peak ladder
                slice_dl = min(deadline - 5.0, time.process_time() + 0.10 * budget_seconds)
                ht = _lbfgs_all_pos(cand, 300, slice_dl, tie=True)
                win = _peak_window(ht, pad_frac=0.06, extra=192)
                for beta in [1e6, 1e8]:
                    if time.process_time() >= slice_dl - 0.5:
                        break
                    ht = _lbfgs_block(ht, win, 300, slice_dl - 0.3, beta=beta)
                for pad in [0.08, 0.05, 0.03]:
                    if time.process_time() >= slice_dl - 0.4:
                        break
                    win = _peak_window(ht, pad_frac=pad, extra=128)
                    ht2 = _lbfgs_block(ht, win, 300, slice_dl - 0.2, beta=1e7, tie=True)
                    if R_of(ht2) > R_of(ht):
                        ht = ht2
                r = R_of(ht)
                edge_cands.append((r, side, e, cm, ht))
                consider(ht, 'edge_s%d_e%.2f_c%g' % (side, e, cm), "edge")
    if edge_cands:
        edge_cands.sort(key=lambda x: -x[0])
        r0, s0, e0, c0, _ = edge_cands[0]
        print("edge best: side=%d e=%.2f cap=%g R=%.9f (start %.9f)" %
              (s0, e0, c0, r0, start_bestR))

    # ---- Phase 2: half-resolution quotient search on the winner ----
    best_c = None
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 4.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.30
        if half_deadline > time.process_time() + 1.0:
            work_c = c.copy()
            best_c = c.copy()
            best_cR = cR
            rounds = 0
            while time.process_time() < half_deadline - 1.0:
                work_c, best_c, best_cR, org = _half_cycle(
                    work_c, best_cR, half_deadline, tag='h%d' % rounds)
                rounds += 1
            print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
            h_lift = _rescale(np.repeat(best_c, 2))
            ht = h_lift
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= deadline - 3.0:
                    break
                ht = _lbfgs_all_pos(ht, 300, deadline - 2.5, beta=beta)
            consider(ht, 'lift', "lift")

    # ---- Phase 3: remaining budget on beta-homotopy + tie polish loop ----
    loop_end = deadline - 1.0
    rounds = 0
    while time.process_time() < loop_end - 1.0:
        rounds += 1
        now = time.process_time()
        slice_dl = min(loop_end, now + 0.10 * budget_seconds)
        if slice_dl <= now + 0.5:
            break
        ht = best.copy()
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= slice_dl - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 250, slice_dl - 0.3, beta=beta)
            consider(ht, 'loop%d_beta%g' % (rounds, beta), "loop")
        for pad in [0.08, 0.05, 0.03]:
            if time.process_time() >= slice_dl - 0.4:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 350, slice_dl - 0.2, beta=1e7, tie=True)
            consider(ht2, 'loop%d_pk%g' % (rounds, pad), "loop pk")
        if time.process_time() < slice_dl - 0.5:
            ht3 = _lbfgs_all_pos(best, 250, slice_dl - 0.3, beta=0.0, tie=True)
            consider(ht3, 'loop%d_b0tie' % rounds, "loop tie")

    # ---- Final tie polish ----
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0, tie=True)
        consider(ht, origin + '+b0tie', "trailing tie")

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    if free is None:
        active = np.arange(h.size)
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _upsample(h, factor):
    n = h.size
    newn = factor * n
    idx = np.linspace(0, n, newn + 1)
    x = np.arange(newn)
    return np.interp(x, idx[:-1] + 0.5, h, left=h[0], right=h[-1])


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase 1: local polish of start with plain objective ----
    p1 = t0 + budget_seconds * 0.10
    h = _lbfgs(best, 300, p1, beta=0.0)
    offer(h, 'p1-plain')
    h = _lbfgs(best, 300, p1, beta=1e7)
    offer(h, 'p1-beta')

    # ---- Phase 2: random-window block descent on the peak region ----
    N = best.size
    p2 = t0 + budget_seconds * 0.45
    rng = np.random.default_rng(987654321)
    rnd = 0
    while time.process_time() < p2:
        rnd += 1
        win = _peak_window(best, pad_frac=0.05, extra=200)
        # random subwindow within the peak
        L0 = win.size
        L = int(rng.integers(max(8, L0 // 4), L0 + 1))
        c = int(rng.integers(win[0], win[-1] + 1))
        lo = max(0, c - L // 2)
        hi = min(N, lo + L)
        lo = max(0, hi - L)
        sub = np.arange(lo, hi)
        cand = _lbfgs(best, 200, p2, beta=1e7, free=sub)
        cand = _lbfgs(cand, 200, p2, beta=0.0, free=sub)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
            print("p2 round=%d len=%d R=%.9f (NEW BEST)" % (rnd, L, bestR))
        else:
            offer(cand, 'p2')

    # ---- Phase 3: upsample and refine (finer discretization near optimum) ----
    p3 = t0 + budget_seconds * 0.72
    if best.size <= 400000:
        for factor in (2,):
            if time.process_time() >= p3 - 1.0:
                break
            up = _upsample(best, factor)
            up = _rescale(up)
            r0 = R_of(up)
            if r0 > bestR - 1e-6:
                hu = _lbfgs(up, 300, p3, beta=1e7)
                hu = _lbfgs(hu, 300, p3, beta=0.0)
                offer(hu, 'p3-up%d' % factor)
                # peak ladder on upsampled
                for pad in (0.06, 0.04, 0.03):
                    if time.process_time() >= p3 - 0.5:
                        break
                    win = _peak_window(hu, pad_frac=pad, extra=128)
                    hu = _lbfgs(hu, 200, p3, beta=1e7, free=win)
                    hu = _lbfgs(hu, 200, p3, beta=0.0, free=win)
                offer(hu, 'p3-up%d-ladder' % factor)

    # ---- Phase 4: final full-vector polish with peak ladder ----
    p4 = t0 + budget_seconds * 0.98
    for pad in (0.05, 0.03, 0.02, 0.015):
        if time.process_time() >= p4 - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        hb = _lbfgs(best, 250, p4, beta=1e7, free=win)
        hb = _lbfgs(hb, 250, p4, beta=0.0, free=win)
        offer(hb, 'p4-peak pad=%.3f' % pad)

    hb = _lbfgs(best, 400, p4, beta=1e8)
    offer(hb, 'p4-full-beta')
    hb = _lbfgs(best, 400, p4, beta=0.0)
    offer(hb, 'p4-full-plain')

    amax = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "nearmax5=%.4f)"
          % (bestR, startR, best.size, float(np.mean(best <= 0)),
             amax, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR - 1e-9:
        result["alternative"] = alt_best
    return result

