    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_fraction(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0:
        return 0.0
    return float(np.mean(h == 0.0))


def _peak_ladder(h, deadline, pads, iters=400):
    best = h.copy()
    bestR = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2, r2
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d) zero_frac=%.4f" %
          (bestR, best.size, _zero_fraction(best)))

    # Phase 1: full ladder polish of the start (global + peak blocks).
    if time.process_time() < deadline - 0.5:
        hp, rp = _peak_ladder(best, deadline,
                              pads=(0.30, 0.20, 0.15, 0.12, 0.08, 0.06, 0.04))
        if rp > bestR + 1e-14:
            best, bestR, origin = hp, rp, 'ladder'
    print("after ladder: R=%.9f origin=%s" % (bestR, origin))

    # Phase 2: revival - inject mass into zero cells and re-polish.
    alt_best = None
    alt_bestR = -1.0
    if time.process_time() < deadline - 2.0:
        h_cur = best.copy()
        _, g = _fun_grad_tie(h_cur)
        Lf = _knots(h_cur)
        mx_h = h_cur.max()
        if mx_h > 0:
            idx = np.flatnonzero(h_cur > 1e-9 * mx_h)
            if idx.size > 0:
                i0 = int(idx.min()); i1 = int(idx.max())
            else:
                i0, i1 = 0, h_cur.size - 1
        else:
            i0, i1 = 0, h_cur.size - 1
        Z = np.arange(i0, i1 + 1)
        Z = Z[h_cur[Z] == 0.0]
        if Z.size > 0:
            gZ = g[Z]
            order_grad = Z[np.argsort(-gZ)]
            LZ = Lf[Z]
            order_def = Z[np.argsort(LZ)]
            eps = 1e-3 * h_cur.mean()
            for mode, order in [('grad', order_grad), ('def', order_def)]:
                for m in (256, 1024):
                    if time.process_time() >= deadline - 1.0:
                        break
                    mm = min(m, order.size)
                    if mm == 0:
                        continue
                    h_rev = h_cur.copy()
                    h_rev[order[:mm]] = eps
                    h_rev = _rescale(h_rev)
                    hr, rr = _peak_ladder(
                        h_rev, deadline,
                        pads=(0.20, 0.12, 0.08, 0.05))
                    if rr > bestR + 1e-14:
                        best, bestR, origin = hr, rr, 'rev_%s_%d' % (mode, m)
                    if rr > alt_bestR and rr < bestR - 1e-14:
                        alt_best, alt_bestR = hr, rr
                    print("revival %s m=%d: R=%.9f (best %.9f)" %
                          (mode, m, rr, bestR))

    # Phase 3: final deep polish until deadline.
    if time.process_time() < deadline - 0.5:
        hp, rp = _peak_ladder(best, deadline,
                              pads=(0.10, 0.06, 0.04, 0.03, 0.02))
        if rp > bestR + 1e-14:
            best, bestR, origin = hp, rp, 'final'

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.4f)" %
          (bestR, origin, start_bestR, best.size, _zero_fraction(best)))

    if bestR > start_bestR + 1e-12:
        if alt_best is not None and alt_bestR > start_bestR + 1e-12:
            return {"best": best, "alternative": alt_best}
        return best
    if alt_best is not None:
        return {"best": best, "alternative": alt_best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _interlace(h, w):
    """Interlace h with per-phase weights w (length m). Result length m*n."""
    m = len(w)
    n = h.size
    out = np.empty(m * n, dtype=float)
    for k in range(m):
        out[k::m] = h * w[k]
    return out


def _fold(h, m):
    n = h.size // m
    return h[:m * n].reshape(n, m).sum(axis=1)


def _opt_weights(h, m, deadline, max_evals=60):
    """Optimize m per-phase weights (w0=1 fixed) to maximize R(interlace)."""
    best_w = np.ones(m)
    best_r = R_of(_interlace(h, best_w))
    evals = 1
    grid = np.array([0.5, 0.7, 0.85, 1.0, 1.18, 1.4, 2.0])
    if m == 3:
        for w1 in grid:
            for w2 in grid:
                if evals >= max_evals or time.process_time() > deadline - 0.5:
                    break
                w = np.array([1.0, w1, w2])
                r = R_of(_interlace(h, w))
                evals += 1
                if r > best_r:
                    best_r, best_w = r, w
            else:
                continue
            break
    else:
        best_w = np.ones(m)
    if evals < max_evals and time.process_time() < deadline - 1.0:
        def neg_r(x):
            w = np.ones(m)
            w[1:] = np.maximum(1e-3, x)
            return -R_of(_interlace(h, w))
        x0 = best_w[1:].copy()
        try:
            res = minimize(neg_r, x0, method='Nelder-Mead',
                           options={'xatol': 1e-4, 'fatol': 1e-11,
                                    'maxiter': 60, 'maxfev': max_evals - evals})
            if res is not None and np.isfinite(res.fun):
                w = np.ones(m)
                w[1:] = np.maximum(1e-3, res.x)
                r = R_of(_interlace(h, w))
                if r > best_r:
                    best_r, best_w = r, w
        except Exception:
            pass
    return best_w, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase A: half-resolution quotient polish (kept from base) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.18
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase B: high-beta sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Phase C: multi-scale interlaced lift (3x and 4x), pick better ----
    lift_deadline = deadline - 8.0
    if time.process_time() < lift_deadline - 2.0:
        results = []
        for m in (3, 4):
            if best.size * m > 1000000:
                continue
            sub_dl = lift_deadline - (0.5 if m == 3 else 0.0)
            w, r_w = _opt_weights(best, m, sub_dl - 1.0, max_evals=50)
            hm = _rescale(_interlace(best, w))
            hm = _polish_ladder(hm, sub_dl - 0.5,
                                betas=(1e6, 1e7, 0.0), iters=300)
            hm = _peak_ladder(hm, sub_dl - 0.3,
                              pads=(0.10, 0.06, 0.04), iters=300)
            rm = R_of(hm)
            print("lift%dx w=%s R(%dxN)=%.9f" % (m, np.round(w, 4), m, rm))
            results.append((m, w, hm, rm))
        if results:
            # best interlaced candidate
            m_best, w_best, h_best, r_best = max(results, key=lambda t: t[3])
            offer(h_best, 'lift%dx' % m_best)
            # fold each back to original N and polish
            for (m, w, hm, rm) in results:
                hf = _rescale(_fold(hm, m))
                hf = _polish_ladder(hf, deadline - 4.0,
                                    betas=(1e7, 0.0), iters=300)
                hf = _peak_ladder(hf, deadline - 3.5,
                                  pads=(0.08, 0.05), iters=300)
                rf = R_of(hf)
                print("  fold %dx: R=%.9f" % (m, rf))
                offer(hf, 'fold%dx' % m)

    # ---- Phase D: final polish ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 0.0), iters=250)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.06, 0.04), iters=300)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _resample_mass(base, newN):
    n = base.size
    h = np.clip(base, 0, None)
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.arange(n + 1) / n
    x_new = np.arange(newN + 1) / newN
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    h_new = np.clip(h_new, 0, None)
    if h_new.sum() <= 0:
        return _rescale(np.interp((np.arange(newN) + 0.5) / newN,
                                  (np.arange(n) + 0.5) / n, base))
    return _rescale(h_new)


def _polish_at_N(h, deadline, label=""):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    ht = _lbfgs_all_pos(best, 400, min(deadline - 0.5,
                                       time.process_time() + 12.0), tie=True)
    r = R_of(ht)
    if r > bestR + 1e-15:
        best, bestR = ht, r
    for beta in (1e6, 1e8):
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(best, 300,
                            min(deadline - 0.5, time.process_time() + 8.0),
                            beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    if time.process_time() < deadline - 1.0:
        ht = _peak_ladder(best, min(deadline - 0.3,
                                    time.process_time() + 10.0),
                          pads=(0.10, 0.06, 0.04), iters=200, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.2, tie=False)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    return best, bestR


def _coarsen(h, p):
    n = h.size
    m = n // p
    hc = h[:m * p].reshape(m, p).sum(axis=1)
    return hc


def _lift_staircase(hc, p):
    return np.repeat(hc, p)


def _lift_profile(hc, q, p):
    return (np.repeat(hc, p) * np.tile(q, hc.size))


def _stage1_coarse(hc0, deadline, rng, n_restarts=10):
    """Jittered restarts of exact-R L-BFGS on the coarse problem."""
    best = hc0.copy()
    bestR = R_of(best)
    m = hc0.size
    for it in range(n_restarts):
        if time.process_time() >= deadline - 0.5:
            break
        sigma = [0.10, 0.20, 0.35][it % 3]
        nb = int(rng.integers(6, 13))
        edges = np.linspace(0, m, nb + 1).astype(int)
        jit = np.ones(m)
        for b in range(nb):
            jit[edges[b]:edges[b + 1]] *= np.exp(rng.normal(0, sigma))
        cand = _rescale(hc0 * jit)
        cap = min(deadline - 0.3, time.process_time() + 3.0)
        ht = _lbfgs_all_pos(cand, 300, cap, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        if time.process_time() < cap - 0.3:
            ht = _lbfgs_all_pos(best, 300, cap, beta=1e5)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht, r
        if time.process_time() < cap - 0.3:
            ht = _lbfgs_all_pos(best, 300, cap, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht, r
    return best, bestR


def _stage2_lift(hc, p, deadline, rounds=3):
    """Alternate L-BFGS on coarse heights and micro-profile q."""
    m = hc.size
    q = np.ones(p)
    h = _lift_staircase(hc, p)
    h = _rescale(h)
    bestR = R_of(h)
    best_h = h.copy()
    best_hc = hc.copy()
    best_q = q.copy()
    for rd in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        # (i) coarse heights, q fixed
        def f_c(xc):
            hh = _lift_profile(np.clip(xc, 0, None), q, p)
            val, g = _fun_grad_tie(hh)
            # aggregate gradient into coarse blocks
            gc = g.reshape(m, p).sum(axis=1)
            return val, gc
        cap = min(deadline - 0.3, time.process_time() + 4.0)
        try:
            res = minimize(f_c, hc, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * m,
                           callback=_make_cb(cap - 0.2),
                           options={'maxiter': 200, 'maxfun': 400,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            if res is not None:
                hc = _rescale(np.clip(res.x, 0, None))
        except (TimeoutError, Exception):
            pass
        # (ii) micro-profile q, hc fixed
        if time.process_time() < deadline - 0.5:
            def f_q(xq):
                qq = np.clip(xq, 0, None)
                if qq.mean() <= 0:
                    return 1e18, np.zeros(p)
                qq = qq / qq.mean()
                hh = _lift_profile(hc, qq, p)
                val, g = _fun_grad_tie(hh)
                gq = (g.reshape(m, p) * np.repeat(hc, p).reshape(m, p)).sum(axis=0)
                return val, gq
            cap = min(deadline - 0.3, time.process_time() + 4.0)
            try:
                res = minimize(f_q, q, jac=True, method='L-BFGS-B',
                               bounds=[(0.0, None)] * p,
                               callback=_make_cb(cap - 0.2),
                               options={'maxiter': 200, 'maxfun': 400,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                if res is not None:
                    qq = np.clip(res.x, 0, None)
                    if qq.mean() > 0:
                        q = qq / qq.mean()
            except (TimeoutError, Exception):
                pass
        h = _rescale(_lift_profile(hc, q, p))
        r = R_of(h)
        if r > bestR + 1e-15:
            bestR = r
            best_h = h.copy()
            best_hc = hc.copy()
            best_q = q.copy()
    return best_h, bestR, best_hc, best_q


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            startR = R_of(base)
        else:
            base, startR = None, 0.0
    else:
        base, startR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        startR = R_of(base)

    print("base R=%.9f (N=%d)" % (startR, base.size))

    N0 = base.size
    # Mass-preserving resample down to N=104992 if larger
    if N0 > 104992 and N0 % 2 == 0:
        cand = _resample_mass(base, 104992)
        r0 = R_of(cand)
        print("resample->104992 R=%.9f (dR=%+.2e)" % (r0, r0 - startR))
        if r0 > startR:
            base, startR = cand, r0
            print("  kept resampled base")
    elif N0 < 104992:
        # upscale to 104992
        cand = _resample_mass(base, 104992)
        r0 = R_of(cand)
        if r0 > startR:
            base, startR = cand, r0

    best = base.copy()
    bestR = startR
    alt_candidates = []

    # Period detection for exact staircase
    def detect_period(h):
        n = h.size
        mx = h.max() if h.size else 0.0
        if mx <= 0:
            return 1
        tol = 1e-10 * mx
        for p in range(2, 65):
            if n % p != 0:
                continue
            m = n // p
            blocks = h.reshape(p, m)
            if np.max(np.abs(blocks - blocks[0])) < tol:
                return p
        return 1

    p_det = detect_period(base)
    print("detected period=%d" % p_det)

    rng = np.random.default_rng(12345)

    # Choose coarsening factors: prefer detected period, plus 32 and 16 fallbacks
    coarsen_list = []
    if p_det > 1 and base.size % p_det == 0:
        coarsen_list.append(p_det)
    for p in (32, 16):
        if base.size % p == 0 and p not in coarsen_list:
            coarsen_list.append(p)
    if not coarsen_list:
        coarsen_list = [16]

    # Time budget allocation
    # Stage 1+2 for first coarsening: ~55% of budget; second: ~25%; polish: rest
    n_coarse = len(coarsen_list)
    remaining = deadline - time.process_time()
    stage12_deadline = time.process_time() + remaining * 0.75

    for ci, p in enumerate(coarsen_list):
        if time.process_time() >= stage12_deadline - 1.0:
            break
        m = base.size // p
        if m < 4:
            continue
        # time slice for this coarsening
        slices_left = n_coarse - ci
        slice_end = time.process_time() + (stage12_deadline - time.process_time()) / slices_left

        hc0 = _coarsen(base, p)
        hc0 = _rescale(hc0)
        rc0 = R_of(hc0)
        print("coarsen p=%d Nc=%d coarse R=%.9f" % (p, m, rc0))

        # Stage 1: jittered restarts
        s1_end = min(slice_end - 1.0, time.process_time() + (slice_end - time.process_time()) * 0.55)
        hc_best, rc_best = _stage1_coarse(hc0, s1_end, rng, n_restarts=10)
        print("  stage1 coarse R=%.9f (dR=%+.2e)" % (rc_best, rc_best - rc0))

        # Stage 2: lift with micro-profile
        if time.process_time() < slice_end - 1.0:
            h_lift, r_lift, hc_lift, q_lift = _stage2_lift(
                hc_best, p, slice_end - 0.5, rounds=3)
            print("  stage2 lifted R=%.9f max|q-1|=%.4f"
                  % (r_lift, float(np.max(np.abs(q_lift - 1.0)))))
            alt_candidates.append((h_lift, r_lift, p))
            if r_lift > bestR + 1e-15:
                best, bestR = h_lift.copy(), r_lift
                print("  -> new best (p=%d) R=%.9f" % (p, bestR))

    # Stage 3: full polish at N=base.size
    if time.process_time() < deadline - 1.5:
        h, r = _polish_at_N(best, deadline - 0.5, label="final")
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final polish R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, startR, best.size, _zero_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14:
        if alt_candidates:
            alt = max(alt_candidates, key=lambda t: t[1])
            result["alternative"] = alt[0]
        else:
            result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _resample_mass(base, newN):
    n = base.size
    h = np.clip(base, 0, None)
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.arange(n + 1) / n
    x_new = np.arange(newN + 1) / newN
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    h_new = np.clip(h_new, 0, None)
    if h_new.sum() <= 0:
        return _rescale(np.interp((np.arange(newN) + 0.5) / newN,
                                  (np.arange(n) + 0.5) / n, base))
    return _rescale(h_new)


def _polish_at_N(h, deadline, label=""):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    ht = _lbfgs_all_pos(best, 400, min(deadline - 0.5,
                                       time.process_time() + 12.0), tie=True)
    r = R_of(ht)
    if r > bestR + 1e-15:
        best, bestR = ht, r
    for beta in (1e6, 1e8):
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(best, 300,
                            min(deadline - 0.5, time.process_time() + 8.0),
                            beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    if time.process_time() < deadline - 1.0:
        ht = _peak_ladder(best, min(deadline - 0.3,
                                    time.process_time() + 10.0),
                          pads=(0.10, 0.06, 0.04), iters=200, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.2, tie=False)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    return best, bestR


def _coarsen(h, p):
    n = h.size
    m = n // p
    hc = h[:m * p].reshape(m, p).sum(axis=1)
    return hc


def _lift_staircase(hc, p):
    return np.repeat(hc, p)


def _lift_profile(hc, q, p):
    return (np.repeat(hc, p) * np.tile(q, hc.size))


def _stage1_coarse(hc0, deadline, rng, n_restarts=10):
    """Jittered restarts of exact-R L-BFGS on the coarse problem."""
    best = hc0.copy()
    bestR = R_of(best)
    m = hc0.size
    for it in range(n_restarts):
        if time.process_time() >= deadline - 0.5:
            break
        sigma = [0.10, 0.20, 0.35][it % 3]
        nb = int(rng.integers(6, 13))
        edges = np.linspace(0, m, nb + 1).astype(int)
        jit = np.ones(m)
        for b in range(nb):
            jit[edges[b]:edges[b + 1]] *= np.exp(rng.normal(0, sigma))
        cand = _rescale(hc0 * jit)
        cap = min(deadline - 0.3, time.process_time() + 3.0)
        ht = _lbfgs_all_pos(cand, 300, cap, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        if time.process_time() < cap - 0.3:
            ht = _lbfgs_all_pos(best, 300, cap, beta=1e5)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht, r
        if time.process_time() < cap - 0.3:
            ht = _lbfgs_all_pos(best, 300, cap, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht, r
    return best, bestR


def _stage2_lift(hc, p, deadline, rounds=3):
    """Alternate L-BFGS on coarse heights and micro-profile q."""
    m = hc.size
    q = np.ones(p)
    h = _lift_staircase(hc, p)
    h = _rescale(h)
    bestR = R_of(h)
    best_h = h.copy()
    best_hc = hc.copy()
    best_q = q.copy()
    for rd in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        # (i) coarse heights, q fixed
        def f_c(xc):
            hh = _lift_profile(np.clip(xc, 0, None), q, p)
            val, g = _fun_grad_tie(hh)
            # aggregate gradient into coarse blocks
            gc = g.reshape(m, p).sum(axis=1)
            return val, gc
        cap = min(deadline - 0.3, time.process_time() + 4.0)
        try:
            res = minimize(f_c, hc, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * m,
                           callback=_make_cb(cap - 0.2),
                           options={'maxiter': 200, 'maxfun': 400,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            if res is not None:
                hc = _rescale(np.clip(res.x, 0, None))
        except (TimeoutError, Exception):
            pass
        # (ii) micro-profile q, hc fixed
        if time.process_time() < deadline - 0.5:
            def f_q(xq):
                qq = np.clip(xq, 0, None)
                if qq.mean() <= 0:
                    return 1e18, np.zeros(p)
                qq = qq / qq.mean()
                hh = _lift_profile(hc, qq, p)
                val, g = _fun_grad_tie(hh)
                gq = (g.reshape(m, p) * np.repeat(hc, p).reshape(m, p)).sum(axis=0)
                return val, gq
            cap = min(deadline - 0.3, time.process_time() + 4.0)
            try:
                res = minimize(f_q, q, jac=True, method='L-BFGS-B',
                               bounds=[(0.0, None)] * p,
                               callback=_make_cb(cap - 0.2),
                               options={'maxiter': 200, 'maxfun': 400,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                if res is not None:
                    qq = np.clip(res.x, 0, None)
                    if qq.mean() > 0:
                        q = qq / qq.mean()
            except (TimeoutError, Exception):
                pass
        h = _rescale(_lift_profile(hc, q, p))
        r = R_of(h)
        if r > bestR + 1e-15:
            bestR = r
            best_h = h.copy()
            best_hc = hc.copy()
            best_q = q.copy()
    return best_h, bestR, best_hc, best_q


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            startR = R_of(base)
        else:
            base, startR = None, 0.0
    else:
        base, startR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        startR = R_of(base)

    print("base R=%.9f (N=%d)" % (startR, base.size))

    N0 = base.size
    # Mass-preserving resample down to N=104992 if larger
    if N0 > 104992 and N0 % 2 == 0:
        cand = _resample_mass(base, 104992)
        r0 = R_of(cand)
        print("resample->104992 R=%.9f (dR=%+.2e)" % (r0, r0 - startR))
        if r0 > startR:
            base, startR = cand, r0
            print("  kept resampled base")
    elif N0 < 104992:
        # upscale to 104992
        cand = _resample_mass(base, 104992)
        r0 = R_of(cand)
        if r0 > startR:
            base, startR = cand, r0

    best = base.copy()
    bestR = startR
    alt_candidates = []

    # Period detection for exact staircase
    def detect_period(h):
        n = h.size
        mx = h.max() if h.size else 0.0
        if mx <= 0:
            return 1
        tol = 1e-10 * mx
        for p in range(2, 65):
            if n % p != 0:
                continue
            m = n // p
            blocks = h.reshape(p, m)
            if np.max(np.abs(blocks - blocks[0])) < tol:
                return p
        return 1

    p_det = detect_period(base)
    print("detected period=%d" % p_det)

    rng = np.random.default_rng(12345)

    # Choose coarsening factors: prefer detected period, plus 32 and 16 fallbacks
    coarsen_list = []
    if p_det > 1 and base.size % p_det == 0:
        coarsen_list.append(p_det)
    for p in (32, 16):
        if base.size % p == 0 and p not in coarsen_list:
            coarsen_list.append(p)
    if not coarsen_list:
        coarsen_list = [16]

    # Time budget allocation
    # Stage 1+2 for first coarsening: ~55% of budget; second: ~25%; polish: rest
    n_coarse = len(coarsen_list)
    remaining = deadline - time.process_time()
    stage12_deadline = time.process_time() + remaining * 0.75

    for ci, p in enumerate(coarsen_list):
        if time.process_time() >= stage12_deadline - 1.0:
            break
        m = base.size // p
        if m < 4:
            continue
        # time slice for this coarsening
        slices_left = n_coarse - ci
        slice_end = time.process_time() + (stage12_deadline - time.process_time()) / slices_left

        hc0 = _coarsen(base, p)
        hc0 = _rescale(hc0)
        rc0 = R_of(hc0)
        print("coarsen p=%d Nc=%d coarse R=%.9f" % (p, m, rc0))

        # Stage 1: jittered restarts
        s1_end = min(slice_end - 1.0, time.process_time() + (slice_end - time.process_time()) * 0.55)
        hc_best, rc_best = _stage1_coarse(hc0, s1_end, rng, n_restarts=10)
        print("  stage1 coarse R=%.9f (dR=%+.2e)" % (rc_best, rc_best - rc0))

        # Stage 2: lift with micro-profile
        if time.process_time() < slice_end - 1.0:
            h_lift, r_lift, hc_lift, q_lift = _stage2_lift(
                hc_best, p, slice_end - 0.5, rounds=3)
            print("  stage2 lifted R=%.9f max|q-1|=%.4f"
                  % (r_lift, float(np.max(np.abs(q_lift - 1.0)))))
            alt_candidates.append((h_lift, r_lift, p))
            if r_lift > bestR + 1e-15:
                best, bestR = h_lift.copy(), r_lift
                print("  -> new best (p=%d) R=%.9f" % (p, bestR))

    # Stage 3: full polish at N=base.size
    if time.process_time() < deadline - 1.5:
        h, r = _polish_at_N(best, deadline - 0.5, label="final")
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final polish R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, startR, best.size, _zero_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14:
        if alt_candidates:
            alt = max(alt_candidates, key=lambda t: t[1])
            result["alternative"] = alt[0]
        else:
            result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _upsample(h, factor):
    """Refine step function by linear interpolation onto finer grid."""
    n = h.size
    m = n * factor
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, m)
    return np.interp(x_new, x_old, h)


def _tail_window(h, frac=0.15, extra=64):
    """Region near the far end where the peak sits (skewed)."""
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    # peak at position m in knots; support roughly [0, 2n]
    span = max(extra, int(frac * n))
    lo = max(0, m - span)
    hi = min(n - 1, m + span)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase A: try upsampling to a finer grid, then polish with peak ladder ----
    # The step function has a sharp peak; refining near the peak region can help.
    up_end = t0 + budget_seconds * 0.35
    for factor in (2, 3):
        if time.process_time() >= up_end - 4.0:
            break
        if best.size * factor > 900000:
            continue
        hu = _upsample(best, factor)
        hu = _rescale(hu)
        ru = R_of(hu)
        # polish with peak ladder on the fine grid
        slice_end = min(up_end, time.process_time() + 8.0)
        hu2 = _peak_ladder(hu, slice_end - 0.5,
                           pads=(0.08, 0.05, 0.03, 0.02), iters=300, tie=True)
        ru2 = R_of(hu2)
        if ru2 > bestR + 1e-15:
            best, bestR = hu2.copy(), ru2
            print("  up x%d ACCEPT R=%.9f N=%d" % (factor, bestR, best.size))
        else:
            print("  up x%d no gain R=%.9f (raw %.9f)" % (factor, ru2, ru))

    # ---- Phase B: peak-focused block refinement on current grid ----
    peak_end = t0 + budget_seconds * 0.60
    for it in range(20):
        if time.process_time() >= peak_end - 2.0:
            break
        # window centered on peak, shrinking
        frac = 0.25 * (0.85 ** it)
        win = _tail_window(best, frac=frac, extra=32)
        ht = _lbfgs_block(best, win, 400, peak_end - 0.5, beta=1e8)
        r1 = R_of(ht)
        ht2 = _lbfgs_block(ht, win, 400, peak_end - 0.3, tie=True)
        r2 = R_of(ht2)
        gained = False
        if r2 > bestR + 1e-15:
            best, bestR = ht2.copy(), r2
            gained = True
        elif r1 > bestR + 1e-15:
            best, bestR = ht.copy(), r1
            gained = True
        if not gained and it > 4:
            break
    print("after peak R=%.9f ties=%d" % (bestR, _tie_count(best)))

    # ---- Phase C: penalised ladder (mass-1, knots<=1) ----
    pen_end = t0 + budget_seconds * 0.82
    for nu in (1e4, 1e5, 1e6, 1e7, 1e8):
        if time.process_time() >= pen_end - 3.0:
            break
        slice_end = min(pen_end, time.process_time() + 4.0)
        h_p = _lbfgs_all_pos(best, 400, slice_end - 1.0, beta=1e8)
        r_p = R_of(h_p)
        if r_p > bestR + 1e-15:
            best, bestR = h_p.copy(), r_p
        h_l = _peak_ladder(best, slice_end - 0.3,
                           pads=(0.06, 0.03, 0.02), iters=200, tie=True)
        r_l = R_of(h_l)
        if r_l > bestR + 1e-15:
            best, bestR = h_l.copy(), r_l
        print("  pen nu=%.0e R=%.9f" % (nu, bestR))

    # ---- Phase D: final full-grid polish ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _split_lift(q, k, N, rng):
    m = q.size
    w = np.exp(0.3 * rng.randn(m, k))
    w = w / w.sum(axis=1, keepdims=True) * k
    h = (q[:, None] * w).reshape(-1)
    if h.size < N:
        h = np.concatenate((h, np.full(N - h.size, h[-1])))
    return _rescale(np.clip(h[:N], 0, None))


def _half_smooth(h):
    """Half-resolution smoothing via a windowed average (quotient candidate)."""
    n = h.size
    m = n // 2
    if m < 2:
        return h.copy()
    a = h[0:2 * m:2]
    b = h[1:2 * m:2]
    c = 0.5 * (a + b)
    # neighbour smooth
    cs = c.copy()
    cs[1:-1] = 0.25 * c[:-2] + 0.5 * c[1:-1] + 0.25 * c[2:]
    return _rescale(cs)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: quotient cycle at half resolution ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: rotation of extract/lift variants ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.07 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                c = _half_smooth(wk)[:m]
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: multi-scale quotient cascade with random-split lift ----
    cascade_start = t0 + budget_seconds * 0.35
    cascade_end = deadline - 6.0
    if time.process_time() < cascade_start:
        while time.process_time() < cascade_start - 0.05:
            time.sleep(0.01)
    rng = np.random.RandomState(246801357)
    if time.process_time() < cascade_end - 1.0 and best.size >= 16:
        stage_len = max(0.5, (cascade_end - time.process_time()) / 3.0)
        for si, k in enumerate([8, 4, 2]):
            if time.process_time() >= cascade_end - 0.5:
                break
            stage_end = min(cascade_end, time.process_time() + stage_len)
            Ncur = best.size
            if Ncur % k != 0:
                print("cascade k=%d skipped (N=%d not divisible)" % (k, Ncur))
                continue
            q = best.reshape(-1, k).mean(axis=1)
            qR0 = R_of(q)
            print("cascade k=%d start R(q)=%.9f (best %.9f)" % (k, qR0, bestR))
            for rnd in range(4):
                now = time.process_time()
                if now >= stage_end - 0.5:
                    break
                slice_dl = min(now + 3.0, stage_end)
                if slice_dl <= now + 0.4:
                    break
                qc = q.copy()
                B = max(4, q.size // 50) if (rnd % 2 == 0) else max(4, q.size // 200)
                if B >= qc.size:
                    s0 = 0
                    Bc = qc.size
                else:
                    s0 = rng.randint(0, qc.size - B + 1)
                    Bc = B
                sigma = [0.005, 0.015, 0.04][rnd % 3]
                qc[s0:s0 + Bc] = qc[s0:s0 + Bc] * np.exp(sigma * rng.randn(Bc))
                qc = _rescale(np.clip(qc, 0, None))
                win = _peak_window(qc, pad_frac=0.06, extra=64)
                qc = _lbfgs_block(qc, win, 250, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    qc = _lbfgs_all_pos(qc, 200, slice_dl, beta=0.0)
                r_new = R_of(qc)
                r_old = R_of(q)
                acc = r_new > r_old + 1e-13
                if acc:
                    q = qc
                print("  k=%d rnd %d B=%d sigma=%.4g R(q) %.9f -> %.9f %s"
                      % (k, rnd, Bc, sigma, r_old, r_new, "ACC" if acc else ""))
            now = time.process_time()
            if now >= stage_end - 0.5:
                continue
            slice_dl = min(now + 3.0, stage_end)
            h = _split_lift(q, k, Ncur, rng)
            win = _peak_window(h, pad_frac=0.06, extra=128)
            h = _lbfgs_block(h, win, 250, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                h = _lbfgs_all_pos(h, 250, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                h = _lbfgs_all_pos(h, 200, slice_dl, beta=0.0)
            r_lift = R_of(h)
            acc = r_lift > bestR + 1e-13
            print("cascade k=%d lift R=%.9f (best %.9f) %s"
                  % (k, r_lift, bestR, "ACC" if acc else ""))
            if acc:
                best, bestR, origin = h.copy(), r_lift, 'cascade_k%d' % k
                print("  cascade NEW BEST R=%.9f (k=%d)" % (bestR, k))
            elif r_lift > alt_bestR:
                alt_best, alt_bestR = h.copy(), r_lift

    # ---- Phase 4: finer peak pads + final polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04, 0.02]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_deficit(h, lam):
    """Objective log(D) - log(M) - log(S) with D = M*S - num.
    Same maximiser as the code's -log(num)+log(M)+log(S) but reweighted."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad_tie(h)
    D = max(M * s - num, 1e-300)
    # tie-averaged peak gradient
    idx = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    gLf_peak = np.zeros_like(Lf)
    gLf_peak[idx] += (1.0 / idx.size) / M
    dM = _backprop(gLf_peak, h)
    dS = 2.0 * np.ones_like(h)
    dnum = _backprop(dq, h)
    grad = (s * dM + M * dS - dnum) / D - lam * (dM / M + dS / s)
    val = np.log(D) - np.log(M) - np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_all_pos_deficit(h0, maxiter, deadline, lam):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
