    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _flank_windows(h, halfwidth):
    """Windows centred on knots where the convolution crosses M/2 on the
    rising and falling flanks."""
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return []
    half = 0.5 * M
    above = Lf >= half
    if not np.any(above):
        return []
    idx = np.flatnonzero(above)
    lo_a, hi_a = idx.min(), idx.max()
    # rising crossing: last index below half before lo_a
    rise = None
    for i in range(lo_a, -1, -1):
        if Lf[i] < half:
            rise = i
            break
    fall = None
    for i in range(hi_a, Lf.size):
        if Lf[i] < half:
            fall = i
            break
    wins = []
    n = h.size
    for c in (rise, fall):
        if c is None:
            continue
        lo = max(0, c - halfwidth)
        hi = min(n - 1, c + halfwidth)
        wins.append(np.arange(lo, hi + 1))
    return wins


def _diag(h):
    num, dq, Lf = _num_and_dq(h)
    S = h.sum()
    M = Lf.max()
    D = M * S - num
    return M, num, D, S


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    M0, num0, D0, S0 = _diag(best)
    M_start = M0
    print("base R=%.9f (N=%d, M=%.6f, num=%.6f, D=%.6e)"
          % (bestR, best.size, M0, num0, D0))

    # ---- Stage (i): full-array deficit L-BFGS at decreasing lam ----
    stage_i_end = t0 + min(budget_seconds * 0.37, 22.0)
    for lam in (1.0, 0.5, 0.2, 0.05):
        if time.process_time() >= stage_i_end - 1.0:
            break
        slice_end = min(stage_i_end, time.process_time() + 6.0)
        h = _lbfgs_all_pos_deficit(best, 400, slice_end - 0.3, lam)
        r = R_of(h)
        M, num, D, S = _diag(h)
        print("i lam=%.2f R=%.9f M=%.6f num=%.6f D=%.6e" % (lam, r, M, num, D))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("  i ACCEPT R=%.9f" % bestR)

    # ---- Stage (ii): beta peak ladder ----
    stage_ii_end = t0 + min(budget_seconds * 0.50, 30.0)
    if time.process_time() < stage_ii_end - 1.0:
        h = _peak_ladder(best, stage_ii_end - 0.3,
                         pads=(0.10, 0.06, 0.04), iters=200, tie=True)
        r = R_of(h)
        M, num, D, S = _diag(h)
        print("ii ladder R=%.9f M=%.6f num=%.6f D=%.6e" % (r, M, num, D))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("  ii ACCEPT R=%.9f" % bestR)

    # ---- Stage (iii): block deficit on peak + flank windows ----
    stage_iii_end = t0 + min(budget_seconds * 0.75, 45.0)
    flank_accepts = 0
    total_accepts_iii = 0
    first_accept_iii = None
    if time.process_time() < stage_iii_end - 1.0:
        N = best.size
        hw = max(1, int(0.05 * N))
        peak_win = _peak_window(best, pad_frac=0.04, extra=128)
        flank_wins = _flank_windows(best, hw)
        allw = [peak_win] + flank_wins
        union = np.unique(np.concatenate(allw)) if allw else peak_win
        # try each window separately first (to see which produces accepts)
        for wi, win in enumerate(allw):
            if time.process_time() >= stage_iii_end - 1.0:
                break
            slice_end = min(stage_iii_end, time.process_time() + 5.0)
            h = _lbfgs_block_deficit(best, win, 300, slice_end - 0.3, 0.05)
            r = R_of(h)
            M, num, D, S = _diag(h)
            tag = "peak" if wi == 0 else "flank%d" % (wi - 1)
            print("iii %s R=%.9f M=%.6f D=%.6e" % (tag, r, M, D))
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                total_accepts_iii += 1
                if wi > 0:
                    flank_accepts += 1
                if first_accept_iii is None:
                    first_accept_iii = tag
                print("  iii ACCEPT (%s) R=%.9f" % (tag, bestR))
        # union pass
        if time.process_time() < stage_iii_end - 1.0:
            slice_end = min(stage_iii_end, time.process_time() + 5.0)
            h = _lbfgs_block_deficit(best, union, 300, slice_end - 0.3, 0.05)
            r = R_of(h)
            M, num, D, S = _diag(h)
            print("iii union R=%.9f M=%.6f D=%.6e" % (r, M, D))
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                total_accepts_iii += 1
                if first_accept_iii is None:
                    first_accept_iii = "union"
                print("  iii ACCEPT (union) R=%.9f" % bestR)
    print("iii summary: accepts=%d flank_accepts=%d first=%s"
          % (total_accepts_iii, flank_accepts, str(first_accept_iii)))

    # ---- Stage (iv): plain tie polish ----
    stage_iv_end = t0 + min(budget_seconds * 0.90, 54.0)
    if time.process_time() < stage_iv_end - 1.0:
        h = _lbfgs_all_pos(best, 500, stage_iv_end - 0.5, tie=True)
        r = R_of(h)
        M, num, D, S = _diag(h)
        print("iv tie R=%.9f M=%.6f num=%.6f D=%.6e" % (r, M, num, D))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("  iv ACCEPT R=%.9f" % bestR)

    M_fin, num_fin, D_fin, S_fin = _diag(best)
    print("final R=%.9f (start %.9f, N=%d, M=%.6f, D=%.6e, dM=%.2e, dD=%.2e)"
          % (bestR, startR, best.size, M_fin, D_fin,
             M_fin - M_start, D_fin - D0))
    print("zero_frac=%.4f nearmax5=%.4f"
          % (_zero_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _resample_mass(base, newN):
    n = base.size
    h = np.clip(base, 0, None)
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.arange(n + 1) / n
    x_new = np.arange(newN + 1) / newN
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    h_new = np.clip(h_new, 0, None)
    if h_new.sum() <= 0:
        return np.ones(newN)
    return _rescale(h_new)


def _detect_period(h):
    n = h.size
    mx = h.max() if h.size else 0.0
    if mx <= 0:
        return 1
    tol = 1e-12 * mx
    for p in range(2, 65):
        if n % p != 0:
            continue
        m = n // p
        blocks = h.reshape(p, m)
        if np.max(np.abs(blocks - blocks[0])) < tol:
            return p
    return 1


def _rasterize(u, v, Nf, K):
    # sw = softmax(u)
    u = np.asarray(u, dtype=float)
    v = np.asarray(v, dtype=float)
    mu = u.max()
    e = np.exp(u - mu)
    sw = e / e.sum()
    cw = np.cumsum(sw)
    p = (Nf - K) * cw + np.arange(1, K + 1)
    # block edges: p_0 = 0, p_k for k=1..K
    edges = np.empty(K + 1, dtype=int)
    edges[0] = 0
    edges[1:] = np.round(p).astype(int)
    # enforce monotone, at least 1 cell
    for k in range(1, K + 1):
        if edges[k] <= edges[k - 1]:
            edges[k] = edges[k - 1] + 1
    if edges[K] > Nf:
        # shrink from the end
        edges[K] = Nf
        for k in range(K - 1, -1, -1):
            if edges[k] >= edges[k + 1]:
                edges[k] = edges[k + 1] - 1
        if edges[0] < 0:
            edges[0] = 0
    a = np.exp(np.clip(v, -18.0, 7.0))
    h = np.empty(Nf, dtype=float)
    for k in range(K):
        lo = edges[k]; hi = edges[k + 1]
        if hi > lo:
            h[lo:hi] = a[k]
    return h, edges, sw, a


def _objective_uv(u, v, Nf, K, mode, beta=0.0):
    h, edges, sw, a = _rasterize(u, v, Nf, K)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(u.size + v.size)
    if mode == 'tie':
        val, g = _fun_grad_tie(h)
    else:
        val, g = _fun_grad_beta(h, beta)
    # g = dR/dh (of the -log objective). Chain to a_k
    da = np.zeros(K)
    for k in range(K):
        lo = edges[k]; hi = edges[k + 1]
        if hi > lo:
            da[k] = g[lo:hi].sum()
    dv = a * da
    # chain to u: p_k depends on u; edges are round(p_k)
    # dR/du_m = sum_k da_k * dp_k/du_m ; dp_k/du_m = (Nf-K)*(delta_km sw_k - sw_k sw_m)
    # = (Nf-K)*sw_k*(delta_km - sw_m)
    # sum_k da_k * (Nf-K)*sw_k*(delta_km - sw_m)
    # = (Nf-K)*sw_m*da_m - (Nf-K)*sw_m*sum_k da_k*sw_k
    wda = sw * da
    total = wda.sum()
    du = (Nf - K) * (wda - sw * total)
    return val, np.concatenate([du, dv])


def _fit_uv(u0, v0, Nf, K, deadline, maxiter=400):
    u = u0.copy(); v = v0.copy()
    x = np.concatenate([u, v])
    n = x.size

    def f(xx):
        return _objective_uv(xx[:K], xx[K:], Nf, K, 'tie')

    def fb(xx, beta):
        return _objective_uv(xx[:K], xx[K:], Nf, K, 'beta', beta)

    cb = _make_cb(deadline - 0.2)
    # tie phase
    try:
        res = minimize(f, x, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        x = res.x
    except (TimeoutError, Exception):
        return u, v
    for beta in (1e5, 1e7):
        if time.process_time() >= deadline - 0.3:
            break
        try:
            res = minimize(lambda xx: fb(xx, beta), x, jac=True,
                           method='L-BFGS-B', callback=cb,
                           options={'maxiter': maxiter,
                                    'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            x = res.x
        except (TimeoutError, Exception):
            break
    return x[:K], x[K:]


def _micro_polish(h, deadline, K=32):
    """32-entry multiplicative profile q[r], h[32j+r]=hc[j]*q[r], q mean 1."""
    if time.process_time() >= deadline - 0.3:
        return h
    Nf = h.size
    if Nf % K != 0:
        return h
    m = Nf // K
    hc = h.reshape(m, K).mean(axis=1)  # coarse per 32-block
    # current q estimate
    q = np.ones(K)
    for r in range(K):
        vals = h[r::K]
        if vals.size == hc.size:
            num = np.sum(vals * hc)
            den = np.sum(hc * hc)
            if den > 0:
                q[r] = num / den
    q = np.clip(q, 1e-3, 1e3)
    q = q / q.mean()

    def build(qq):
        hh = np.empty(Nf)
        for r in range(K):
            hh[r::K] = hc * qq[r]
        return _rescale(hh)

    def f(xq):
        qq = np.exp(xq)
        qq = qq / qq.mean()
        hh = build(qq)
        val, g = _fun_grad_tie(hh)
        # chain: hh[r::K] = hc * qq[r]; dR/dqq_r = sum(hc * g[r::K])
        dq = np.zeros(K)
        for r in range(K):
            dq[r] = np.sum(hc * g[r::K])
        # qq = exp(xq)/mean(exp(xq)); dqq_r/dxq_m = qq_r*(delta_rm - qq_m)
        dx = qq * (dq - np.sum(dq * qq))
        return val, dx

    x0 = np.log(q)
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': 100, 'maxfun': 200,
                                'ftol': 1e-20, 'gtol': 1e-16})
        qq = np.exp(res.x); qq = qq / qq.mean()
        hh = build(qq)
        if R_of(hh) > R_of(h):
            return hh
    except (TimeoutError, Exception):
        pass
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            startR = R_of(base)
        else:
            base, startR = None, 0.0
    else:
        base, startR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        startR = R_of(base)

    print("base R=%.9f (N=%d)" % (startR, base.size))

    N0 = base.size
    # Choose working N: better of base and its mass-preserving resample to N/2
    Nf = N0
    work = base.copy()
    workR = startR
    if N0 > 2000:
        cand = _resample_mass(base, N0 // 2)
        rc = R_of(cand)
        print("resample N=%d R=%.9f" % (N0 // 2, rc))
        if rc > workR:
            work, workR, Nf = cand, rc, N0 // 2

    # Detect exact 32-cell staircase
    p = _detect_period(work)
    print("detected period=%d" % p)
    if p == 32:
        K = Nf // 32
    else:
        K = max(2, Nf // 32)

    print("working N=%d K=%d" % (Nf, K))

    # Initial u,v from uniform widths
    u0 = np.zeros(K)
    v0 = np.log(np.clip(work.mean() if work.size else 1.0, 1e-6, None)) * np.ones(K)
    # Better: derive from actual block means
    h0, edges0, sw0, a0 = _rasterize(u0, v0, Nf, K)
    # initial v from block means of work (resampled to Nf)
    wr = _resample_mass(work, Nf) if work.size != Nf else work
    v_init = np.zeros(K)
    for k in range(K):
        lo = edges0[k]; hi = edges0[k + 1]
        if hi > lo:
            v_init[k] = np.log(max(wr[lo:hi].mean(), 1e-6))
    v_init = np.clip(v_init, -18, 7)

    rng = np.random.default_rng(12345)

    best = work.copy()
    bestR = workR
    best_info = None

    n_restarts = 6
    for ri in range(n_restarts):
        if time.process_time() >= deadline - 2.0:
            break
        if ri == 0:
            u = u0.copy()
            v = v_init.copy()
        else:
            u = u0 + rng.normal(0, 0.35, K)
            v = v_init + rng.normal(0, 0.10, K)
        remaining = deadline - time.process_time()
        slices_left = n_restarts - ri
        slice_end = time.process_time() + remaining / slices_left
        u, v = _fit_uv(u, v, Nf, K, slice_end, maxiter=400)
        h, edges, sw, a = _rasterize(u, v, Nf, K)
        h = _rescale(h)
        r = R_of(h)
        # micro polish
        if time.process_time() < deadline - 1.0:
            hp = _micro_polish(h, min(deadline - 0.5,
                                      time.process_time() + 2.0), K=32)
            rp = R_of(hp)
            if rp > r:
                h, r = hp, rp
        widths = np.diff(edges).astype(float)
        wbar = widths.mean()
        wdev = np.max(np.abs(widths / wbar - 1.0)) if wbar > 0 else 0.0
        nmin = int(np.sum(widths <= 1.0))
        print("restart %d: R=%.9f wdev=%.4f nmin=%d" % (ri, r, wdev, nmin))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            best_info = (u.copy(), v.copy(), edges.copy(), wdev, nmin)

    # Final micro polish on best
    if time.process_time() < deadline - 1.0:
        hp = _micro_polish(best, deadline - 0.5, K=32)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp

    # Report
    if best_info is not None:
        u, v, edges, wdev, nmin = best_info
        widths = np.diff(edges).astype(float)
        wbar = widths.mean()
        wdev = np.max(np.abs(widths / wbar - 1.0))
        nmin = int(np.sum(widths <= 1.0))
        # q deviation
        Nf2 = best.size
        if Nf2 % 32 == 0:
            m = Nf2 // 32
            hc = best.reshape(m, 32).mean(axis=1)
            q = np.ones(32)
            for r in range(32):
                vals = best[r::32]
                if vals.size == hc.size:
                    den = np.sum(hc * hc)
                    if den > 0:
                        q[r] = np.sum(vals * hc) / den
            qdev = np.max(np.abs(q - 1.0))
        else:
            qdev = 0.0
        print("BEST R=%.9f wdev=%.5f nmin=%d qdev=%.5f" %
              (bestR, wdev, nmin, qdev))
    else:
        print("BEST R=%.9f (no mesh info)" % bestR)

    result = {"best": best}
    if bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    bestH = h.copy(); bestR = R_of(h)
    for pf in pads:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(bestH, pad_frac=pf)
        sub = min(deadline, time.process_time() + 8.0)
        hp = _lbfgs_block(bestH, free, iters, sub)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            bestH, bestR = hp, rp
    return bestH, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d zeros=%.1f%%" % (bestR, best.size, 100.0*np.mean(best<=0)))

    bestH = best.copy(); bestRH = bestR

    # Phase A: beta-homotopy (softmax) ladder, sharp, peak interleaving
    betas = (2, 4, 8, 16, 32, 64, 128, 256)
    phaseA_end = t0 + budget_seconds * 0.55
    rnd = 0
    while time.process_time() < phaseA_end - 1.5 and time.process_time() < deadline - 4.0:
        rnd += 1
        for beta in betas:
            if time.process_time() >= phaseA_end - 1.5 or time.process_time() >= deadline - 4.0:
                break
            sub = min(phaseA_end, time.process_time() + 8.0)
            h = _lbfgs_log(bestH, 200, sub,
                           fg=(lambda hh, _b=beta: _fun_grad_beta(hh, _b)))
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  A%d beta=%d R=%.7f" % (rnd, beta, bestRH))
        if time.process_time() >= phaseA_end - 1.0:
            break
        sub2 = min(phaseA_end, time.process_time() + 8.0)
        hs = _lbfgs_log(bestH, 250, sub2)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
        print("  A%d sharp R=%.7f" % (rnd, bestRH))
        hp, rp = _peak_ladder(bestH, sub2)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp, rp
        print("  A%d peak  R=%.7f" % (rnd, bestRH))

    # Phase B: random-direction saddle escape (projected out gradient)
    rng = np.random.default_rng(20240101)
    esc_end = min(deadline - 3.0, t0 + budget_seconds * 0.85)
    improved = False
    while time.process_time() < esc_end - 2.0 and time.process_time() < deadline - 4.0:
        n = bestH.size
        d = rng.standard_normal(n)
        _, g = _fun_grad(bestH)
        gg = g @ g
        if gg > 0:
            d = d - (g @ d) / gg * g
        nrm = np.linalg.norm(d)
        nh = np.linalg.norm(bestH)
        if nrm <= 0 or nh <= 0:
            break
        scale = nh / nrm
        improved_this = False
        for delta in (1e-3, 3e-3, 1e-2, 3e-2, 1e-1):
            if time.process_time() >= esc_end - 1.0:
                break
            h_try = np.clip(bestH + delta * scale * d, 0.0, None)
            if h_try.sum() <= 0:
                continue
            h_try = _rescale(h_try)
            sub = min(esc_end, time.process_time() + 6.0)
            h_pol = _lbfgs_log(h_try, 250, sub)
            r_pol = R_of(h_pol)
            if r_pol > bestRH + 1e-13:
                bestH, bestRH = h_pol.copy(), r_pol
                improved_this = True; improved = True
                print("  rnd delta=%.1e -> R=%.7f *" % (delta, bestRH))
                # peak polish
                if time.process_time() < esc_end - 1.0:
                    sub2 = min(esc_end, time.process_time() + 5.0)
                    hp, rp = _peak_ladder(bestH, sub2)
                    if rp > bestRH + 1e-13:
                        bestH, bestRH = hp, rp
                break
        if not improved_this:
            print("  rnd no improvement")

    # Final sharp polish
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        hp, rp = _peak_ladder(bestH, deadline - 0.3, pads=(0.08, 0.05, 0.03), iters=300)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp, rp
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    print("final R=%.7f N=%d zeros=%.1f%% improved=%s" %
          (bestR, best.size, 100.0*np.mean(best<=0), improved))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

