    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _resample_to(h, N):
    h = np.clip(h, 0, None)
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(N)
    tgt = np.linspace(0.0, total, N + 1)
    edges = np.interp(tgt, c, np.arange(n + 1, dtype=float))
    newh = np.diff(edges)
    return np.clip(newh, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size

    # ---- Phase 1: fine-grained peak polishing directly on best (cheap wins) ----
    p1_deadline = min(deadline - 6.0, time.process_time() + budget_seconds * 0.30)
    work = best.copy()
    workR = bestR
    rounds = 0
    while time.process_time() < p1_deadline - 1.0:
        rounds += 1
        w = _polish_ladder(work, p1_deadline, betas=(1e7, 1e8), iters=250)
        w = _peak_ladder(w, p1_deadline,
                         pads=(0.05, 0.03, 0.02, 0.015), iters=300)
        w = _polish_ladder(w, p1_deadline, betas=(1e9, 1e10, 0.0), iters=250)
        r = R_of(w)
        if r > workR + 1e-14:
            work, workR = w, r
        else:
            # perturb slightly to escape plateau
            noise = np.clip(work * (1.0 + rng.normal(0, 0.02, work.size)), 0, None)
            w = _rescale(noise)
            workR = R_of(w)
            work = w
    print("phase1 rounds=%d R=%.9f" % (rounds, workR))
    if workR > bestR + 1e-14:
        best, bestR = work.copy(), workR
        print("NEW BEST after phase1 R=%.9f" % bestR)

    # ---- Phase 2: stride-3 cascade from current best ----
    s3_deadline = deadline - 3.0
    rounds3 = 0
    acc3 = 0
    while time.process_time() < s3_deadline - 1.0 and rounds3 < 4:
        rounds3 += 1
        m = N // 3
        if m < 8:
            break
        c = best[0:3 * m].reshape(m, 3).mean(axis=1)
        c = _rescale(c)
        cR0 = R_of(c)
        c = _polish_ladder(c, s3_deadline - 0.5,
                           betas=(1e6, 1e7, 0.0), iters=300)
        c = _peak_ladder(c, s3_deadline - 0.5,
                         pads=(0.25, 0.15, 0.10, 0.06), iters=300)
        cR1 = R_of(c)
        if time.process_time() >= s3_deadline - 0.5:
            break
        w = np.clip(np.exp(rng.normal(0.0, 0.45, 3)), 0.2, 5.0)
        f3 = np.repeat(c, 3) * np.tile(w, m)
        f3 = _rescale(f3)
        f3 = _polish_ladder(f3, s3_deadline - 0.5,
                            betas=(1e7, 1e8, 0.0), iters=300)
        f3 = _peak_ladder(f3, s3_deadline - 0.5,
                          pads=(0.10, 0.06), iters=250)
        cand = _resample_to(f3, N)
        cand = _rescale(cand)
        cand = _polish_ladder(cand, s3_deadline - 0.5,
                              betas=(1e8, 0.0), iters=250)
        cand = _peak_ladder(cand, s3_deadline - 0.5,
                            pads=(0.06, 0.04), iters=250)
        r = R_of(cand)
        if cand.size == best.size and r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            acc3 += 1
            print("stride3 round=%d accepted R=%.9f (c %.9f->%.9f)"
                  % (rounds3, bestR, cR0, cR1))
        else:
            print("stride3 round=%d no accept R=%.9f (c %.9f->%.9f)"
                  % (rounds3, r, cR0, cR1))
    print("stride3 rounds=%d accepted=%d" % (rounds3, acc3))

    # ---- Phase 3: fine final polishing of the best, with high-beta tie handling ----
    ht = _polish_ladder(best, deadline - 0.8,
                        betas=(1e8, 1e9, 1e10, 1e11, 0.0), iters=350)
    offer(ht, 'finalhi')
    ht2 = _peak_ladder(best, deadline - 0.8,
                       pads=(0.03, 0.02, 0.015, 0.01), iters=300)
    offer(ht2, 'finalpeak')
    # final all-pos full precision polish
    ht3 = _lbfgs_all_pos(best, 2000, deadline - 0.4, beta=0.0)
    offer(ht3, 'finalfull')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_sm(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_sm(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _peak_window(h, frac, pad):
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    half = max(4, int(frac * n)) + pad
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def _flat_peak_window(h, tol=0.9999, pad_frac=0.5, extra=64):
    """Window covering the near-max region of f*f, with proportional padding.
    Targets the flat top of the autoconvolution where the L-inf constraint binds."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(512)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    alt_returned = None

    # ---- Primary idea: refine on a finer grid; accept if mapped-back improves. ----
    if cur.size < 300000 and time.process_time() < deadline - 25.0:
        N_up = min(cur.size * 2, 400000)
        up = _rescale(_prolongate(cur, N_up))
        up = _lbfgs_log(up, maxiter=500, deadline=deadline - 20.0)
        # flat-peak window polish at fine grid: targets the L-inf-active region
        for tol, pad_frac in ((0.9999, 0.5), (0.999, 0.3), (0.99, 0.2)):
            if time.process_time() >= deadline - 18.0:
                break
            win = _flat_peak_window(up, tol=tol, pad_frac=pad_frac, extra=32)
            cand = _lbfgs_block(up, win, maxiter=400, deadline=deadline - 18.0)
            if R_of(cand) > R_of(up):
                up = cand
        up_r = R_of(up)
        print("fine refine R = %.6f (N=%d)" % (up_r, N_up))
        back = _rescale(_coarsen(up, cur.size))
        back_r = R_of(back)
        if back_r > best_r:
            best, best_r = back.copy(), back_r
            cur, cur_r = back.copy(), back_r
        elif up_r > best_r:
            best, best_r = up.copy(), up_r
            cur, cur_r = up.copy(), up_r
        else:
            alt_returned = up.copy()

    # ---- Region-restricted polish of the current best on its own grid. ----
    if time.process_time() < deadline - 8.0:
        for frac, pad in ((0.02, 2), (0.05, 4), (0.12, 8)):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(cur, frac, pad)
            cand = _lbfgs_block(cur, win, maxiter=600, deadline=deadline - 8.0)
            rc = R_of(cand)
            if rc > cur_r:
                cur, cur_r = cand, rc
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r

    # ---- Smoothing continuation ----
    for beta in (4, 16, 64):
        if time.process_time() >= deadline - 4.0:
            break
        c2 = _lbfgs_log(cur, maxiter=200, deadline=deadline, beta=beta)
        r2 = R_of(c2)
        if r2 > cur_r:
            cur, cur_r = c2, r2
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        print("  beta=%d R=%.6f" % (beta, cur_r))

    # ---- Main loop: alternate full and windowed polish, restart on stall. ----
    restart_tries = 0
    no_improve = 0
    last_r = cur_r
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        # Alternate between local peak window and flat-peak window targeting
        # the L-inf binding region (this is where most gains live).
        for frac, pad in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cur, frac, pad)
            cand = _lbfgs_block(cur, win, maxiter=500, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        for tol, pad_frac in ((0.9999, 0.5), (0.999, 0.3)):
            if time.process_time() >= deadline - 1.0:
                break
            win = _flat_peak_window(cur, tol=tol, pad_frac=pad_frac, extra=32)
            cand = _lbfgs_block(cur, win, maxiter=500, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt_returned is not None and alt_returned.size != best.size:
            out["alternative"] = alt_returned
        else:
            out["alternative"] = start_arr
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    """Rescale so max knot = 1."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tail_window(h, frac=0.15, extra=64):
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    span = max(extra, int(frac * n))
    lo = max(0, m - span)
    hi = min(n - 1, m + span)
    return np.arange(lo, hi + 1)


def _tangent_grad(h):
    """Gauge-fixed objective logQ = log num - 2 log S, projected off the
    peak-direction v = dM/dh (tie-averaged). Returns (logQ, gp, v)."""
    s = h.sum()
    if s <= 0:
        return -1e18, np.zeros(h.size), np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return -1e18, np.zeros(h.size), np.zeros(h.size)
    mx = Lf.max()
    # gradient of logQ (gauge-fixed)
    gLf = -dq / num
    g = _backprop(gLf, h) + 2.0 / s
    # peak direction v = dM/dh (tie-averaged unit vector at argmax knots)
    e = np.zeros_like(Lf)
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    e[idx] = 1.0 / idx.size
    v = _backprop(e, h)
    vv = float(np.dot(v, v))
    if vv > 1e-300:
        gv = float(np.dot(g, v))
        gp = g - (gv / vv) * v
    else:
        gp = g
    logQ = np.log(num) - 2.0 * np.log(s)
    return logQ, gp, v


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase A: tangent-space gauge-fixed descent ----
    tan_end = t0 + budget_seconds * 0.55
    h = _gauge(best.copy())
    # work with unit-mass-normalised for the objective; gauge keeps M=1
    h = h / h.sum() if h.sum() > 0 else h
    logQ, gp, v = _tangent_grad(h)
    prev_h = None
    prev_logQ = None
    n_acc = 0
    n_try = 0
    step = 0
    last_bb = None
    while time.process_time() < tan_end - 2.0:
        step += 1
        # BB step length from last two points
        if prev_h is not None and prev_logQ is not None:
            sh = h - prev_h
            sy = logQ - prev_logQ
            denom = float(np.dot(sh, sh))
            if denom > 1e-300:
                bb = -sy / denom  # gradient-descent BB1 (sy negative for ascent)
                bb = abs(bb)
            else:
                bb = last_bb if last_bb else 1.0
        else:
            bb = 1.0
        ginf = float(np.max(np.abs(gp))) if gp.size else 0.0
        if ginf <= 0:
            break
        # clip step to [0.5,4]/||gp||_inf
        lo = 0.5 / ginf
        hi = 4.0 / ginf
        if bb < lo:
            bb = lo
        elif bb > hi:
            bb = hi
        last_bb = bb
        # ascent direction gp (logQ gradient); move h += t*gp
        accepted = False
        t = bb
        best_cand = None
        best_cand_Q = -1e18
        for _ in range(12):
            cand = np.clip(h + t * gp, 0.0, None)
            if cand.sum() <= 0:
                t *= 0.5
                continue
            cand = _gauge(cand)
            cand = cand / cand.sum()
            candQ = np.log(_num_and_dq(cand)[0]) - 2.0 * np.log(cand.sum())
            # exact R check
            if candQ > best_cand_Q:
                best_cand = cand
                best_cand_Q = candQ
            if candQ > logQ + 1e-15:
                accepted = True
                break
            t *= 0.5
        n_try += 1
        if accepted and best_cand is not None:
            prev_h = h.copy()
            prev_logQ = logQ
            h = best_cand
            logQ, gp, v = _tangent_grad(h)
            n_acc += 1
            # exact R of regauged, unit-mass point
            r_exact = R_of(h)
            if r_exact > bestR + 1e-15:
                best = _rescale(h.copy())
                bestR = r_exact
        else:
            # no descent: try a tiny nudge along gp then break out
            break

        # periodic L-BFGS-B polish on peak window
        if step % 25 == 0 and time.process_time() < tan_end - 3.0:
            win = _peak_window(h, pad_frac=0.06, extra=128)
            ht = _lbfgs_block(h, win, 40, tan_end - 1.0, beta=1e7)
            r_ht = R_of(ht)
            if r_ht > R_of(h) + 1e-15:
                h = _gauge(ht)
                h = h / h.sum()
                logQ, gp, v = _tangent_grad(h)
                if r_ht > bestR + 1e-15:
                    best = _rescale(ht.copy())
                    bestR = r_ht
            win = _peak_window(h, pad_frac=0.03, extra=64)
            ht = _lbfgs_block(h, win, 40, tan_end - 0.5, beta=1e7)
            r_ht = R_of(ht)
            if r_ht > R_of(h) + 1e-15:
                h = _gauge(ht)
                h = h / h.sum()
                logQ, gp, v = _tangent_grad(h)
                if r_ht > bestR + 1e-15:
                    best = _rescale(ht.copy())
                    bestR = r_ht

        if step % 50 == 0:
            f01, f1, f5 = _nearmax_fracs(best)
            acc_frac = n_acc / max(1, n_try)
            print("  tan step=%d R=%.9f acc=%.2f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
                  % (step, bestR, acc_frac, f01, f1, f5))

    f01, f1, f5 = _nearmax_fracs(best)
    print("after tangent R=%.9f acc_frac=%.2f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
          % (bestR, n_acc / max(1, n_try), f01, f1, f5))

    # ---- Phase B: peak ladder polish ----
    peak_end = t0 + budget_seconds * 0.75
    if time.process_time() < peak_end - 3.0:
        ht = _peak_ladder(best, peak_end - 1.0,
                          pads=(0.10, 0.06, 0.04, 0.03), iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.9f" % bestR)

    # ---- Phase C: penalised soft-max ladder ----
    pen_end = t0 + budget_seconds * 0.85
    for beta in (1e6, 1e7, 1e8):
        if time.process_time() >= pen_end - 3.0:
            break
        slice_end = min(pen_end, time.process_time() + 4.0)
        h_p = _lbfgs_all_pos(best, 300, slice_end - 1.0, beta=beta)
        r_p = R_of(h_p)
        if r_p > bestR + 1e-15:
            best, bestR = h_p.copy(), r_p
        print("  pen beta=%.0e R=%.9f" % (beta, bestR))

    # ---- Phase D: final exact tie polish ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong2(h):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    H = np.empty(2 * n)
    H[0::2] = h
    H[1::2] = h
    return H


def _prolong_lin(h):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    H = np.empty(2 * n)
    H[0::2] = h
    mid = np.empty(n)
    mid[:-1] = 0.5 * (h[:-1] + h[1:])
    mid[-1] = h[-1]
    H[1::2] = mid
    return H


def _prolong_sqrt(h):
    """sqrt-of-average prolongation: midpoint uses (sqrt(a)+sqrt(b))/2 squared,
    which is a smoother sub-linear blend that often helps the staircase."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    H = np.empty(2 * n)
    H[0::2] = h
    a = np.sqrt(h)
    mid = np.empty(n)
    mid[:-1] = 0.5 * (a[:-1] + a[1:])
    mid[-1] = a[-1]
    H[1::2] = mid * mid
    return H


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    cand = best
    candR = bestR

    # Try several prolongations; keep the best.
    for prol in (_prolong2, _prolong_lin, _prolong_sqrt):
        if time.process_time() >= deadline - 8.0:
            break
        H = _rescale(prol(cand))
        h = _lbfgs_all(H, 400, deadline)
        r = R_of(h)
        if r > candR + 1e-13:
            cand, candR = h, r
            print("  %s R=%.7f" % (prol.__name__, candR))

    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        # Full polish (sometimes on tie-smoothed objective).
        for tie in (False, True):
            if time.process_time() >= deadline - 2.0:
                break
            h = _lbfgs_all(cand, 400, deadline, tie=tie)
            r = R_of(h)
            if r > candR + 1e-13:
                cand, candR = h, r
                print("  full tie=%d #%d R=%.7f" % (tie, it, candR))

        # Beta ladder with peak-window polishes on a wide window.
        for beta in (1e3, 1e4, 1e5, 1e6):
            if time.process_time() >= deadline - 2.0:
                break
            hb = _lbfgs_all(cand, 200, deadline, beta=beta)
            rb = R_of(hb)
            if rb > candR + 1e-13:
                cand, candR = hb, rb
                print("  beta=%.0e #%d R=%.7f" % (beta, it, candR))
            win = _peak_window(cand, tol=0.9995, pad_frac=0.5, extra=256)
            hp = _lbfgs_block(cand, win, 250, deadline, beta=beta)
            rp = R_of(hp)
            if rp > candR + 1e-13:
                cand, candR = hp, rp
                print("  peak #%d beta=%.0e R=%.7f" % (it, beta, rp))

        # Occasionally try to escape via a different prolongation.
        if it % 2 == 0 and time.process_time() < deadline - 6.0:
            for prol in (_prolong_lin, _prolong_sqrt):
                if time.process_time() >= deadline - 4.0:
                    break
                H = _rescale(prol(cand))
                h = _lbfgs_all(H, 300, deadline)
                r = R_of(h)
                if r > candR + 1e-13:
                    cand, candR = h, r
                    print("  %s #%d R=%.7f" % (prol.__name__, it, candR))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (candR, cand.size, 100.0 * np.mean(cand <= 0)))

    if candR > start_bestR + 1e-12:
        return cand
    return {"best": start_best,
            "alternative": cand if candR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, tie=False, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        active = np.arange(n)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _polish(h, R, deadline, label, verbose):
    """Full + beta homotopy + peak-window polishes."""
    h = _lbfgs(h, 500, deadline, beta=0.0)
    r = R_of(h)
    if r > R + 1e-12:
        R = r
        if verbose:
            print(f"  {label} logopt R={R:.6f} N={len(h)}")
    for beta in [64.0, 256.0, 1024.0, 4096.0, 16384.0]:
        if time.process_time() > deadline - 1.0:
            return h, R
        h2 = _lbfgs(h, 300, deadline, beta=beta)
        r2 = R_of(h2)
        if r2 > R + 1e-12:
            h, R = h2, r2
            if verbose:
                print(f"  {label} beta={beta:.0f} R={R:.6f}")
    # tie-aware polish
    h2 = _lbfgs(h, 300, deadline, tie=True)
    r2 = R_of(h2)
    if r2 > R + 1e-12:
        h, R = h2, r2
        if verbose:
            print(f"  {label} tie R={R:.6f}")
    # peak-window local polishes
    for tol, pad in [(0.9999, 0.4), (0.999, 0.3), (0.99, 0.2)]:
        if time.process_time() > deadline - 1.0:
            break
        win = _peak_window(h, tol=tol, pad_frac=pad, extra=32)
        if win.size < 4:
            continue
        h2 = _lbfgs(h, 400, deadline, free=win)
        r2 = R_of(h2)
        if r2 > R + 1e-12:
            h, R = h2, r2
            if verbose:
                print(f"  {label} window tol={tol} R={R:.6f}")
    return h, R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            r = R_of(s)
            if r > 0:
                best = s.copy()
                best_R = r

    if best is None:
        n = 512
        x = np.linspace(0, 1, n)
        best = np.cos(np.pi * (x - 0.5))**2 + 1e-3
        best = _lbfgs(best, 400, deadline)
        best_R = R_of(best)

    print(f"seed R={best_R:.6f} N={len(best)}")
    cur, cur_R = best.copy(), best_R

    # Initial polish at current resolution
    cur, cur_R = _polish(cur, cur_R, deadline, "seed", True)
    if cur_R > best_R:
        best, best_R = cur.copy(), cur_R

    # Prolong-and-polish ladder. Try a couple of target sizes so we don't
    # overshoot if time is short.
    ladder = [len(best)]
    n = len(best)
    while n < 262144:
        n = min(int(n * 2), 262144)
        ladder.append(n)
        if n >= 262144:
            break

    for N in ladder[1:]:
        if time.process_time() > deadline - 6.0:
            break
        cur = _prolong(best, N)
        cur_R = R_of(cur)
        cur, cur_R = _polish(cur, cur_R, deadline, f"N={N}", True)
        if cur_R > best_R:
            best, best_R = cur.copy(), cur_R
            print(f"ladder N={N} new best R={best_R:.6f}")

    # Alternation at the best resolution: window polishes + beta bumps.
    while time.process_time() < deadline - 1.0:
        improved = False
        h2, r2 = _polish(best, best_R, deadline, "alt", False)
        if r2 > best_R + 1e-12:
            best, best_R = h2, r2
            improved = True
            print(f"alt polish R={best_R:.6f}")

        # Try a bit larger N if time permits.
        if not improved and len(best) < 262144:
            if time.process_time() < deadline - 15.0:
                N = min(2 * len(best), 262144)
                cur = _prolong(best, N)
                cur_R = R_of(cur)
                cur, cur_R = _polish(cur, cur_R, deadline, f"grow N={N}", False)
                if cur_R > best_R + 1e-12:
                    best, best_R = cur.copy(), cur_R
                    improved = True
                    print(f"grow N={N} R={best_R:.6f}")

        if not improved:
            # small perturb-and-reopt to escape local minima
            rng = np.random.default_rng(int(time.process_time() * 1e6) % 2**31)
            hp = best * (1.0 + 0.01 * rng.standard_normal(best.size))
            hp = np.clip(hp, 0, None)
            hp = _lbfgs(hp, 200, deadline, beta=0.0)
            rp = R_of(hp)
            if rp > best_R + 1e-12:
                best, best_R = hp, rp
                print(f"perturb R={best_R:.6f}")
            else:
                break

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={R_of(best):.6f} N={len(best)}")
    return best

