    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400,
                        beta=0.0, tie=False):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline,
                        beta=beta, tie=tie)


def _prolong_mass(h, N2):
    n = h.size
    if N2 <= n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N2)
    edges = np.linspace(0.0, float(n), N2 + 1)
    newc = np.interp(edges, np.arange(n + 1, dtype=float), c)
    h2 = np.diff(newc)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return np.ones(N2)
    return h2


def _shorten(h, N2):
    """Mass-preserving coarsening to N2 steps (for cheap polishing)."""
    n = h.size
    if N2 >= n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, float(n), N2 + 1)
    newc = np.interp(edges, np.arange(n + 1, dtype=float), c)
    h2 = np.diff(newc)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return np.ones(N2)
    return h2


def _fine_polish(h, deadline):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    for frac in (0.02, 0.04, 0.08):
        if time.process_time() >= deadline - 0.4:
            break
        for beta in (0.0, 8000.0, 20000.0):
            if time.process_time() >= deadline - 0.4:
                break
            _try(_window_polish_peak(cur, deadline, frac, 4,
                                     maxiter=300, beta=beta))
    if time.process_time() < deadline - 0.4:
        _try(_lbfgs_log(cur, maxiter=600, deadline=deadline))
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r + 1e-12:
            best, best_r = cand.copy(), r
        elif r > alt_r + 1e-12:
            alternative, alt_r = cand.copy(), r

    # --- Strategy change: polish at COARSE resolution first (cheap, many
    # sweeps), then prolong once at the very end. Coarse-grid L-BFGS moves
    # are far cheaper per iteration, so we get many more effective sweeps.
    n0 = base.size
    target_fine = 256000

    # Coarse representation: keep the start's own grid, but if it is huge,
    # work at ~32k for the bulk of the search.
    work_n = min(n0, 32768)
    hc = _shorten(base, work_n) if work_n < n0 else base.copy()
    hc = _rescale(hc)
    rc = R_of(hc)
    print("coarse base R=%.7f (orig %.7f) N=%d" % (rc, base_r, hc.size))

    # Sweep: alternate log-LBFGS full, beta-smoothed, and peak windows.
    cur, cur_r = hc, rc
    sweep = 0
    while time.process_time() < hard_end - 3.0:
        sweep += 1
        prev_r = cur_r
        # full log-LBFGS
        cand = _lbfgs_log(cur, maxiter=600, deadline=hard_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        # beta-smoothed full
        for beta in (800.0, 3000.0, 12000.0):
            if time.process_time() >= hard_end - 2.0:
                break
            cand = _lbfgs_block(cur, np.arange(cur.size), maxiter=250,
                                deadline=hard_end, beta=beta)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        # peak windows at several scales
        for frac in (0.05, 0.10, 0.20, 0.35):
            if time.process_time() >= hard_end - 1.5:
                break
            cand = _window_polish_peak(cur, hard_end, frac, 6,
                                       maxiter=350, beta=0.0)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        print("sweep %d R=%.7f" % (sweep, cur_r))
        _consider(cur, cur_r)
        if cur_r <= prev_r + 1e-11:
            # tiny shake via beta=large peak window to escape
            cand = _window_polish_peak(cur, hard_end, 0.03, 2,
                                       maxiter=200, beta=40000.0)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r

    # --- Prolong the coarse optimum to the fine grid and polish there ---
    hf = _prolong_mass(cur, target_fine)
    hf = _rescale(hf)
    rf = R_of(hf)
    print("prolonged R=%.7f N=%d" % (rf, hf.size))
    _consider(hf, rf)
    if time.process_time() < hard_end - 0.5:
        hp, rp = _fine_polish(hf, hard_end)
        print("fine polish R=%.7f" % rp)
        _consider(hp, rp)

    print("final R=%.7f N=%d | base R=%.7f N=%d"
          % (best_r, best.size, base_r, base.size))

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
from scipy.signal import fftconvolve
from scipy.interpolate import CubicSpline


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _coarsen(h, Nc):
    """Mass-preserving cumsum resample of h to Nc bins."""
    n = h.size
    if n == Nc:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nc)
    # target edges in fine-cumsum units
    edges = np.linspace(0.0, total, Nc + 1)
    vals = np.interp(edges, np.linspace(0.0, total, n + 1), c)
    hc = np.diff(vals)
    hc = np.clip(hc, 0.0, None)
    return hc


def _spline_basis(Nc, K):
    """Return matrix B (Nc x K) mapping theta -> s at coarse cells.
    Cubic spline through K control values on uniform grid over [0,1]."""
    xc = (np.arange(Nc) + 0.5) / Nc
    xk = np.linspace(0.0, 1.0, K)
    # Use natural cubic spline basis: build via CubicSpline on unit vectors
    B = np.zeros((Nc, K))
    for k in range(K):
        e = np.zeros(K)
        e[k] = 1.0
        cs = CubicSpline(xk, e, bc_type='natural')
        B[:, k] = cs(xc)
    return B


def _spline_eval_fine(N, K, theta):
    xf = (np.arange(N) + 0.5) / N
    xk = np.linspace(0.0, 1.0, K)
    cs = CubicSpline(xk, theta, bc_type='natural')
    return cs(xf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Phase E: low-dimensional envelope search (D2 flip) ----
    Nc = 4096
    K = 48
    hc = _coarsen(best, Nc)
    hc = _rescale(hc)
    Rc0 = R_of(hc)
    print("coarse R=%.9f (Nc=%d)" % (Rc0, Nc))

    B = _spline_basis(Nc, K)
    hc_safe = np.where(hc > 0, hc, 1e-12)

    def obj(theta):
        s = B.dot(theta)
        hh = hc_safe * np.exp(np.clip(s, -30.0, 30.0))
        return -R_of(hh)

    env_end = t0 + budget_seconds * 0.45
    best_theta = np.zeros(K)
    best_env_R = Rc0
    seeds = [12345, 67890]
    for si, seed in enumerate(seeds):
        if time.process_time() >= env_end - 4.0:
            break
        try:
            res = differential_evolution(
                obj, [(-1.5, 1.5)] * K, seed=seed, popsize=12,
                maxiter=60, tol=1e-10, polish=False,
                init='sobol' if si == 0 else 'latinhypercube',
                workers=1, updating='immediate')
            th = res.x
            r = -res.fun
            # L-BFGS-B refine
            try:
                res2 = minimize(obj, th, method='L-BFGS-B',
                                bounds=[(-1.5, 1.5)] * K,
                                options={'maxiter': 200, 'ftol': 1e-18,
                                         'gtol': 1e-14})
                if res2.fun < -r:
                    th = res2.x
                    r = -res2.fun
            except Exception:
                pass
            if r > best_env_R + 1e-15:
                best_env_R = r
                best_theta = th.copy()
            print("  DE seed=%d env R=%.9f max|theta|=%.3f"
                  % (seed, r, float(np.max(np.abs(th)))))
        except Exception as e:
            print("  DE failed:", e)

    # also try theta=0 refine
    try:
        res0 = minimize(obj, np.zeros(K), method='L-BFGS-B',
                        bounds=[(-1.5, 1.5)] * K,
                        options={'maxiter': 200, 'ftol': 1e-18, 'gtol': 1e-14})
        if -res0.fun > best_env_R + 1e-15:
            best_env_R = -res0.fun
            best_theta = res0.x.copy()
    except Exception:
        pass

    print("best env R=%.9f max|theta|=%.3f (coarse base %.9f)"
          % (best_env_R, float(np.max(np.abs(best_theta))), Rc0))

    # ---- Lift envelope to fine grid and multiply ----
    s_fine = _spline_eval_fine(N, K, best_theta)
    h_fine = np.clip(best, 0, None) * np.exp(np.clip(s_fine, -30.0, 30.0))
    h_fine = _rescale(h_fine)
    R_fine0 = R_of(h_fine)
    print("lifted fine R=%.9f (start %.9f)" % (R_fine0, startR))

    # ---- Phase F: base's own polish on the lifted construction ----
    cand = h_fine.copy()
    candR = R_fine0

    # beta-softmax peak-window ladder
    peak_end = t0 + budget_seconds * 0.75
    for beta in (1e5, 1e7):
        if time.process_time() >= peak_end - 2.0:
            break
        for pad in (0.15, 0.10, 0.06, 0.04):
            if time.process_time() >= peak_end - 1.5:
                break
            win = _peak_window(cand, pad_frac=pad, extra=128)
            ht = _lbfgs_block(cand, win, 300, peak_end - 0.5, beta=beta)
            r = R_of(ht)
            if r > candR + 1e-15:
                cand, candR = ht, r
    print("after peak ladder R=%.9f" % candR)

    # exact tie polish
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(cand, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("tie ACCEPT R=%.9f ties=%d" % (candR, _tie_count(cand)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(cand, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("argmax ACCEPT R=%.9f" % candR)

    f01, f1, f5 = _nearmax_fracs(cand)
    print("candidate R=%.9f near 0.1%%/1%%/5%%=%.4f/%.4f/%.4f"
          % (candR, f01, f1, f5))

    # ---- Decide best vs alternative ----
    if candR > bestR + 1e-15:
        best, bestR = cand, candR
        print("ENVELOPE WINS R=%.9f (start %.9f)" % (bestR, startR))
        result = {"best": best}
    else:
        print("envelope no gain (cand %.9f vs start %.9f); returning alternative"
              % (candR, startR))
        result = {"best": best, "alternative": cand}

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))
    return result

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
from scipy.signal import fftconvolve
from scipy.interpolate import CubicSpline


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _coarsen(h, Nc):
    """Mass-preserving cumsum resample of h to Nc bins."""
    n = h.size
    if n == Nc:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nc)
    # target edges in fine-cumsum units
    edges = np.linspace(0.0, total, Nc + 1)
    vals = np.interp(edges, np.linspace(0.0, total, n + 1), c)
    hc = np.diff(vals)
    hc = np.clip(hc, 0.0, None)
    return hc


def _spline_basis(Nc, K):
    """Return matrix B (Nc x K) mapping theta -> s at coarse cells.
    Cubic spline through K control values on uniform grid over [0,1]."""
    xc = (np.arange(Nc) + 0.5) / Nc
    xk = np.linspace(0.0, 1.0, K)
    # Use natural cubic spline basis: build via CubicSpline on unit vectors
    B = np.zeros((Nc, K))
    for k in range(K):
        e = np.zeros(K)
        e[k] = 1.0
        cs = CubicSpline(xk, e, bc_type='natural')
        B[:, k] = cs(xc)
    return B


def _spline_eval_fine(N, K, theta):
    xf = (np.arange(N) + 0.5) / N
    xk = np.linspace(0.0, 1.0, K)
    cs = CubicSpline(xk, theta, bc_type='natural')
    return cs(xf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Phase E: low-dimensional envelope search (D2 flip) ----
    Nc = 4096
    K = 48
    hc = _coarsen(best, Nc)
    hc = _rescale(hc)
    Rc0 = R_of(hc)
    print("coarse R=%.9f (Nc=%d)" % (Rc0, Nc))

    B = _spline_basis(Nc, K)
    hc_safe = np.where(hc > 0, hc, 1e-12)

    def obj(theta):
        s = B.dot(theta)
        hh = hc_safe * np.exp(np.clip(s, -30.0, 30.0))
        return -R_of(hh)

    env_end = t0 + budget_seconds * 0.45
    best_theta = np.zeros(K)
    best_env_R = Rc0
    seeds = [12345, 67890]
    for si, seed in enumerate(seeds):
        if time.process_time() >= env_end - 4.0:
            break
        try:
            res = differential_evolution(
                obj, [(-1.5, 1.5)] * K, seed=seed, popsize=12,
                maxiter=60, tol=1e-10, polish=False,
                init='sobol' if si == 0 else 'latinhypercube',
                workers=1, updating='immediate')
            th = res.x
            r = -res.fun
            # L-BFGS-B refine
            try:
                res2 = minimize(obj, th, method='L-BFGS-B',
                                bounds=[(-1.5, 1.5)] * K,
                                options={'maxiter': 200, 'ftol': 1e-18,
                                         'gtol': 1e-14})
                if res2.fun < -r:
                    th = res2.x
                    r = -res2.fun
            except Exception:
                pass
            if r > best_env_R + 1e-15:
                best_env_R = r
                best_theta = th.copy()
            print("  DE seed=%d env R=%.9f max|theta|=%.3f"
                  % (seed, r, float(np.max(np.abs(th)))))
        except Exception as e:
            print("  DE failed:", e)

    # also try theta=0 refine
    try:
        res0 = minimize(obj, np.zeros(K), method='L-BFGS-B',
                        bounds=[(-1.5, 1.5)] * K,
                        options={'maxiter': 200, 'ftol': 1e-18, 'gtol': 1e-14})
        if -res0.fun > best_env_R + 1e-15:
            best_env_R = -res0.fun
            best_theta = res0.x.copy()
    except Exception:
        pass

    print("best env R=%.9f max|theta|=%.3f (coarse base %.9f)"
          % (best_env_R, float(np.max(np.abs(best_theta))), Rc0))

    # ---- Lift envelope to fine grid and multiply ----
    s_fine = _spline_eval_fine(N, K, best_theta)
    h_fine = np.clip(best, 0, None) * np.exp(np.clip(s_fine, -30.0, 30.0))
    h_fine = _rescale(h_fine)
    R_fine0 = R_of(h_fine)
    print("lifted fine R=%.9f (start %.9f)" % (R_fine0, startR))

    # ---- Phase F: base's own polish on the lifted construction ----
    cand = h_fine.copy()
    candR = R_fine0

    # beta-softmax peak-window ladder
    peak_end = t0 + budget_seconds * 0.75
    for beta in (1e5, 1e7):
        if time.process_time() >= peak_end - 2.0:
            break
        for pad in (0.15, 0.10, 0.06, 0.04):
            if time.process_time() >= peak_end - 1.5:
                break
            win = _peak_window(cand, pad_frac=pad, extra=128)
            ht = _lbfgs_block(cand, win, 300, peak_end - 0.5, beta=beta)
            r = R_of(ht)
            if r > candR + 1e-15:
                cand, candR = ht, r
    print("after peak ladder R=%.9f" % candR)

    # exact tie polish
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(cand, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("tie ACCEPT R=%.9f ties=%d" % (candR, _tie_count(cand)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(cand, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("argmax ACCEPT R=%.9f" % candR)

    f01, f1, f5 = _nearmax_fracs(cand)
    print("candidate R=%.9f near 0.1%%/1%%/5%%=%.4f/%.4f/%.4f"
          % (candR, f01, f1, f5))

    # ---- Decide best vs alternative ----
    if candR > bestR + 1e-15:
        best, bestR = cand, candR
        print("ENVELOPE WINS R=%.9f (start %.9f)" % (bestR, startR))
        result = {"best": best}
    else:
        print("envelope no gain (cand %.9f vs start %.9f); returning alternative"
              % (candR, startR))
        result = {"best": best, "alternative": cand}

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _coarsen(h, f):
    N = h.size
    m = N // f
    if m <= 0:
        return None, 0
    hh = h[:m * f].reshape(m, f)
    g = hh.mean(axis=1)
    return g, m


def _prolongate(g, f, N):
    hp = np.repeat(g, f)
    if hp.size < N:
        hp = np.concatenate([hp, np.full(N - hp.size, hp[-1] if hp.size else 0.0)])
    elif hp.size > N:
        hp = hp[:N]
    return hp


def _peak_ladder(h, deadline, bestR, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    best = h
    for p in pads:
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(best, pad_frac=p, extra=128)
        ht = _lbfgs_block(best, win, maxiter=iters, deadline=deadline - 0.3, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # 1) Fine alternating peak-window refinement (the real workhorse): tie-aware
    #    so peaks can be flattened rather than collapsed into one knot.
    if time.process_time() < deadline - 1.5:
        best, bestR = _peak_ladder(best, deadline - 1.0, bestR,
                                   pads=(0.30, 0.20, 0.12, 0.08, 0.05, 0.03),
                                   iters=300)
        print("peak ladder R=%.7f" % bestR)

    # 2) Global polish, then a coarse-to-fine resolution hunt.
    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    N = best.size
    rnd = 0
    while time.process_time() < deadline - 1.0:
        rnd += 1
        now = time.process_time()
        remaining = deadline - 1.0 - now
        if remaining < 1.0:
            break
        progressed = False

        for f in (4, 8, 16):
            if time.process_time() >= deadline - 1.0:
                break
            g, m = _coarsen(best, f)
            if g is None or g.sum() <= 0 or m < 2000:
                continue
            g = _rescale(g)
            gR = R_of(g)
            share = max(1.0, min(remaining / 6.0, 5.0))
            g, gR = run_cycle(g, gR, time.process_time() + share)
            hp = _prolongate(g, f, best.size)
            idx = np.arange(best.size)
            sgn = 1.0 if (rnd + f) % 2 == 0 else -1.0
            tilt = 1.0 + 0.02 * sgn * ((-1.0) ** idx)
            hp = _rescale(np.clip(hp * tilt, 0.0, None))
            hpR = R_of(hp)
            share2 = max(1.0, min(remaining / 6.0, 5.0))
            hp, hpR = run_cycle(hp, hpR, time.process_time() + share2)
            if hpR > bestR + 1e-10:
                best, bestR = hp.copy(), hpR
                progressed = True
                print("round %d f=%d R=%.7f dR=%.2e" % (rnd, f, hpR, hpR - start_bestR))
                break

        if not progressed and time.process_time() < deadline - 1.0:
            prev = bestR
            best, bestR = run_cycle(best, bestR, deadline - 1.0)
            if bestR - prev > 1e-11:
                progressed = True

        if not progressed:
            break

    # 3) Final squeeze: tie-aware peak ladder + one all-position polish.
    if time.process_time() < deadline - 0.6:
        best, bestR = _peak_ladder(best, deadline - 0.5, bestR,
                                   pads=(0.10, 0.06, 0.04, 0.025, 0.015),
                                   iters=400)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _resample_cumulative(h, Nc):
    """Resample h to Nc cells by cumulative mass."""
    h = np.clip(h, 0, None)
    s = h.sum()
    if s <= 0:
        return np.ones(Nc) / Nc
    c = np.concatenate(([0.0], np.cumsum(h)))
    c /= c[-1]
    targets = np.linspace(0.0, 1.0, Nc + 1)
    # mass in each of Nc equal-mass bins
    edges = np.interp(targets, c, np.arange(h.size + 1))
    out = np.zeros(Nc)
    for i in range(Nc):
        lo = edges[i]; hi = edges[i + 1]
        if hi <= lo:
            continue
        # integrate h over [lo, hi] in index space
        jlo = int(np.floor(lo)); jhi = int(np.floor(hi))
        if jlo == jhi:
            out[i] = h[min(jlo, h.size - 1)] * (hi - lo)
        else:
            out[i] += h[min(jlo, h.size - 1)] * (jlo + 1 - lo)
            if jhi > jlo + 1:
                out[i] += h[jlo + 1:jhi].sum()
            if jhi < h.size:
                out[i] += h[jhi] * (hi - jhi)
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Phase 0: detect staircase block structure ----
    h0 = best.copy()
    hn = np.linalg.norm(h0)
    candidates = []
    for p in (2, 4, 8, 16, 32, 64):
        if N % p != 0:
            continue
        m = N // p
        c = h0.reshape(m, p).mean(1)
        lift = np.repeat(c, p)
        rel = float(np.linalg.norm(h0 - lift) / max(hn, 1e-300))
        rlift = R_of(_rescale(lift))
        candidates.append((p, m, c, rel, rlift))
        print("  p=%d m=%d rel=%.3e R_lift=%.9f" % (p, m, rel, rlift))

    chosen = None
    # pick largest p with rel < 1e-6
    for (p, m, c, rel, rlift) in sorted(candidates, key=lambda t: -t[0]):
        if rel < 1e-6:
            chosen = (p, m, c, rel, rlift, True)
            break
    if chosen is None and candidates:
        best_c = min(candidates, key=lambda t: t[3])
        if best_c[3] < 1e-3:
            chosen = (best_c[0], best_c[1], best_c[2], best_c[3], best_c[4], True)
        else:
            # approximate: resample to 3281
            Nc = 3281
            c = _resample_cumulative(h0, Nc)
            c = _rescale(c)
            lift = np.repeat(c, N // Nc) if N % Nc == 0 else None
            if lift is None:
                # fallback: use p=32 mean anyway
                p = 32; m = N // p
                c = h0.reshape(m, p).mean(1)
                lift = np.repeat(c, p)
            rel = float(np.linalg.norm(h0 - lift) / max(hn, 1e-300))
            rlift = R_of(_rescale(lift))
            chosen = (N // Nc if N % Nc == 0 else 32, Nc, c, rel, rlift, False)
            print("  fallback resample Nc=%d rel=%.3e R_lift=%.9f" % (Nc, rel, rlift))

    p, m, c, rel, rlift, exact = chosen
    c = _rescale(np.clip(c, 0, None))
    print("chosen p=%d m=%d exact=%s rel=%.3e R_c=%.9f R_lift=%.9f"
          % (p, m, exact, rel, R_of(c), rlift))

    # ---- Phase 1: c-space L-BFGS ----
    p1_end = t0 + budget_seconds * 0.45
    for beta in (1e4, 1e6, 1e7):
        if time.process_time() >= p1_end - 2.0:
            break
        slice_end = min(p1_end, time.process_time() + 3.0)
        c_try = _lbfgs_all_pos(c, 400, slice_end - 0.5, beta=beta)
        r_try = R_of(c_try)
        if r_try > R_of(c) + 1e-15:
            c = c_try
        print("  c beta=%.0e R_c=%.9f" % (beta, R_of(c)))
    if time.process_time() < p1_end - 2.0:
        c_try = _lbfgs_all_pos(c, 400, p1_end - 1.0, tie=True)
        if R_of(c_try) > R_of(c) + 1e-15:
            c = c_try
        print("  c tie R_c=%.9f" % R_of(c))

    # peak-window blocks in c-space
    for pad in (0.15, 0.06, 0.03):
        if time.process_time() >= p1_end - 1.0:
            break
        win = _peak_window(c, pad_frac=pad, extra=64)
        c_try = _lbfgs_block(c, win, 200, p1_end - 0.5, beta=1e7)
        if R_of(c_try) > R_of(c) + 1e-15:
            c = c_try
        if time.process_time() < p1_end - 0.5:
            c_try = _lbfgs_block(c, win, 200, p1_end - 0.3, tie=True)
            if R_of(c_try) > R_of(c) + 1e-15:
                c = c_try
        print("  c peak pad=%.2f R_c=%.9f" % (pad, R_of(c)))

    # ---- Phase 2: stochastic restarts in c-space ----
    p2_end = t0 + budget_seconds * 0.65
    rng = np.random.RandomState(12345)
    best_c = c.copy()
    best_cR = R_of(c)
    for sigma in (0.02, 0.05, 0.02, 0.05, 0.02, 0.05):
        if time.process_time() >= p2_end - 2.0:
            break
        c_pert = np.clip(c * np.exp(sigma * rng.randn(c.size)), 0, None)
        c_pert = _rescale(c_pert)
        slice_end = min(p2_end, time.process_time() + 2.0)
        c_try = _lbfgs_all_pos(c_pert, 100, slice_end - 0.3, beta=1e7)
        r_try = R_of(c_try)
        if r_try > best_cR + 1e-15:
            best_c = c_try
            best_cR = r_try
        print("  restart sigma=%.2f R_c=%.9f best=%.9f" % (sigma, r_try, best_cR))
    c = best_c

    # ---- Phase 3: lift and full-resolution polish ----
    h2 = np.repeat(c, p)
    if h2.size != N:
        # resample lift to N
        h2 = _resample_cumulative(h2, N)
    h2 = _rescale(np.clip(h2, 0, None))
    r_h2 = R_of(h2)
    print("lifted R=%.9f (start %.9f)" % (r_h2, startR))

    if r_h2 > bestR + 1e-15:
        best, bestR = h2.copy(), r_h2

    # full-resolution polish
    p3_end = t0 + budget_seconds * 0.85
    if time.process_time() < p3_end - 3.0:
        ht = _peak_ladder(best, p3_end - 1.0,
                          pads=(0.10, 0.06, 0.04, 0.03), iters=200, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("full peak ladder ACCEPT R=%.9f" % bestR)

    # final tie/argmax polish
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 200, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _coarsen(h, Nc):
    """Mass-preserving cumsum resample of h to Nc bins."""
    n = h.size
    if n == Nc:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nc)
    edges = np.linspace(0.0, total, Nc + 1)
    vals = np.interp(edges, np.linspace(0.0, total, n + 1), c)
    hc = np.diff(vals)
    hc = np.clip(hc, 0.0, None)
    return hc


def _prolong(hc, N):
    """Linear-interpolation prolongation of coarse hc to fine N (mass-preserving)."""
    Nc = hc.size
    if Nc == N:
        return hc.copy()
    c = np.concatenate(([0.0], np.cumsum(hc)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    edges = np.linspace(0.0, total, N + 1)
    vals = np.interp(edges, np.linspace(0.0, total, Nc + 1), c)
    hf = np.diff(vals)
    hf = np.clip(hf, 0.0, None)
    return hf


def _interp_matrix(Nc, K):
    """P: Nc x K linear interpolation from K equally spaced block centers.
    Rows sum to 1; P @ theta gives smooth log-factor at each coarse cell."""
    centers = (np.arange(K) + 0.5) / K  # in [0,1]
    x = (np.arange(Nc) + 0.5) / Nc
    P = np.zeros((Nc, K))
    # piecewise linear hat basis at centers, with edge extension
    for k in range(K):
        ck = centers[k]
        if k == 0:
            left = 0.0
        else:
            left = centers[k - 1]
        if k == K - 1:
            right = 1.0
        else:
            right = centers[k + 1]
        # hat: 1 at ck, 0 at left/right, linear in between, extended constant outside
        w = np.zeros(Nc)
        mid = (x >= left) & (x <= ck)
        if ck > left:
            w[mid] = (x[mid] - left) / (ck - left)
        w[x < left] = 0.0
        mid2 = (x > ck) & (x <= right)
        if right > ck:
            w[mid2] = (right - x[mid2]) / (right - ck)
        w[x > right] = 0.0
        w[np.abs(x - ck) < 1e-15] = 1.0
        P[:, k] = w
    # normalize rows to sum 1 (should already be ~1)
    rs = P.sum(axis=1)
    rs[rs <= 0] = 1.0
    P = P / rs[:, None]
    return P


def _param_opt(c0, P, theta0, maxiter, deadline):
    """Optimize theta for c = c0 * exp(P theta), objective -log R(c)."""
    if time.process_time() >= deadline - 0.3:
        return theta0, R_of(c0)
    K = P.shape[1]

    def obj(theta):
        s = P.dot(theta)
        s = np.clip(s, -30.0, 30.0)
        c = c0 * np.exp(s)
        val, g = _fun_grad_tie(c)
        # chain rule: g_theta = P^T (g_c * c)
        gtheta = P.T.dot(g * c)
        return val, gtheta

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(obj, theta0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
        if res is None:
            return theta0, R_of(c0)
        th = res.x
    except (TimeoutError, Exception):
        return theta0, R_of(c0)
    s = np.clip(P.dot(th), -30.0, 30.0)
    c = c0 * np.exp(s)
    return th, R_of(c)


def _interp_theta(theta, K_old, K_new):
    """Warm-start: evaluate old theta's log-factor at new centers."""
    P_old = _interp_matrix(K_new, K_old)
    return P_old.dot(theta)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Phase 1: coarsen start to Nc=2048 ----
    Nc = 2048
    c0 = _coarsen(best, Nc)
    c0 = _rescale(c0)
    Rc0 = R_of(c0)
    print("coarse Nc=%d R=%.9f" % (Nc, Rc0))

    # ---- Phase 2: block-multiplier envelope, K in {16,32,64} ----
    best_c = c0.copy()
    best_cR = Rc0
    best_theta = None
    best_K = 0
    theta_warm = None
    K_prev = 0
    env_end = t0 + budget_seconds * 0.55
    for K in (16, 32, 64):
        if time.process_time() >= env_end - 2.0:
            break
        P = _interp_matrix(Nc, K)
        if theta_warm is None:
            theta0 = np.zeros(K)
        else:
            theta0 = _interp_theta(theta_warm, K_prev, K)
        th, r = _param_opt(best_c, P, theta0, 400, env_end - 0.5)
        s = np.clip(P.dot(th), -30.0, 30.0)
        c = best_c * np.exp(s)
        c = _rescale(c)
        r = R_of(c)
        tinf = float(np.max(np.abs(th)))
        print("  K=%d R=%.9f ||theta||inf=%.4f" % (K, r, tinf))
        if r > best_cR + 1e-15:
            best_c = c
            best_cR = r
            best_theta = th.copy()
            best_K = K
        theta_warm = th
        K_prev = K

    print("best envelope K=%d coarse R=%.9f" % (best_K, best_cR))

    # ---- Phase 3: free L-BFGS at Nc=512 from coarsened c(theta*) ----
    if time.process_time() < env_end - 1.0:
        Nc2 = 512
        c512 = _coarsen(best_c, Nc2)
        c512 = _rescale(c512)
        R512_0 = R_of(c512)
        c512_opt = _lbfgs_all_pos(c512, 400, env_end - 0.3, tie=True)
        R512_1 = R_of(c512_opt)
        print("free Nc=512 R: %.9f -> %.9f" % (R512_0, R512_1))
        if R512_1 > R512_0 + 1e-15:
            # prolong back to 2048
            c_prol = _prolong(c512_opt, Nc)
            c_prol = _rescale(c_prol)
            R_prol = R_of(c_prol)
            print("prolonged to Nc=2048 R=%.9f" % R_prol)
            if R_prol > best_cR + 1e-15:
                best_c = c_prol
                best_cR = R_prol
                print("free-512 ACCEPT coarse R=%.9f" % best_cR)

    # ---- Phase 4: lift to N and polish ----
    h_lift = _prolong(best_c, N)
    h_lift = _rescale(h_lift)
    R_lift = R_of(h_lift)
    print("lifted fine R=%.9f (start %.9f)" % (R_lift, startR))

    cand = h_lift.copy()
    candR = R_lift

    peak_end = t0 + budget_seconds * 0.80
    for beta in (1e5, 1e7):
        if time.process_time() >= peak_end - 2.0:
            break
        for pad in (0.15, 0.10, 0.06, 0.04):
            if time.process_time() >= peak_end - 1.5:
                break
            win = _peak_window(cand, pad_frac=pad, extra=128)
            ht = _lbfgs_block(cand, win, 300, peak_end - 0.5, beta=beta)
            r = R_of(ht)
            if r > candR + 1e-15:
                cand, candR = ht, r
    print("after peak ladder R=%.9f" % candR)

    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(cand, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("tie ACCEPT R=%.9f ties=%d" % (candR, _tie_count(cand)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(cand, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("argmax ACCEPT R=%.9f" % candR)

    f01, f1, f5 = _nearmax_fracs(cand)
    print("candidate R=%.9f near 0.1%%/1%%/5%%=%.4f/%.4f/%.4f"
          % (candR, f01, f1, f5))

    if candR > bestR + 1e-15:
        best, bestR = cand, candR
        print("ENVELOPE WINS R=%.9f (start %.9f)" % (bestR, startR))
        result = {"best": best}
    else:
        print("envelope no gain (cand %.9f vs start %.9f); returning alternative"
              % (candR, startR))
        result = {"best": best, "alternative": cand}

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _upsample(h, factor):
    n = h.size
    m = n * factor
    x = (np.arange(m) + 0.5) / factor
    return np.interp(x, np.arange(n) + 0.5, h, left=h[0], right=h[-1])


def _refine_support(h, deadline, maxiter=200):
    cur = h
    curR = R_of(h)
    for beta in (1e5, 1e6, 1e7, 1e8, 1e9, 1e10):
        if time.process_time() >= deadline - 0.5:
            break
        hb = _lbfgs_log(cur, maxiter, deadline, beta=beta)
        rb = R_of(hb)
        if rb > curR + 1e-13:
            cur, curR = hb, rb
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(cur, maxiter, deadline)
        rs = R_of(hs)
        if rs > curR + 1e-13:
            cur, curR = hs, rs
    return cur, curR


def _perturb(h, rng, scale):
    """Multiplicative log-space perturbation to escape local optima."""
    pos = h > 0
    out = h.copy()
    noise = rng.normal(0.0, scale, size=h.size)
    out[pos] = h[pos] * np.exp(noise[pos])
    return _rescale(out)


def _fill_zeros(h, rng, frac):
    """Give some zero entries small positive values so L-BFGS can revive them."""
    out = h.copy()
    zeros = np.flatnonzero(h <= 0)
    if zeros.size == 0:
        return out
    k = max(1, int(zeros.size * frac))
    pick = rng.choice(zeros, size=min(k, zeros.size), replace=False)
    mx = h.max()
    out[pick] = mx * (10.0 ** rng.uniform(-6, -2, size=pick.size))
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Upsample first to reach finer grid early.
    if best.size * 2 <= 1000000 and time.process_time() < deadline - 20.0:
        up = _rescale(_upsample(best, 2))
        ru = R_of(up)
        print("upsample x2 -> R=%.7f (N=%d)" % (ru, up.size))
        if ru > bestR - 1e-6:
            best, bestR = up, ru
            hb, rb = _refine_support(best, deadline, maxiter=200)
            if rb > bestR:
                best, bestR = hb, rb
            print("after upsample refine R=%.7f" % bestR)

    schedule = [
        (0.05, 64, 0.0),
        (0.05, 64, 1e6),
        (0.10, 128, 1e7),
        (0.15, 256, 1e8),
        (0.25, 512, 1e9),
        (0.40, 1024, 1e9),
        (0.60, 2048, 1e10),
        (0.90, 4096, 1e10),
    ]

    cur = best.copy()
    curR = bestR
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        for frac, extra, beta in schedule:
            if time.process_time() >= deadline - 2.0:
                break
            hw = _window_polish_peak(cur, deadline, frac, extra,
                                     maxiter=300, beta=beta)
            rw = R_of(hw)
            if rw > curR + 1e-13:
                cur, curR = hw, rw
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR

        if time.process_time() < deadline - 6.0:
            hb, rb = _refine_support(best, min(deadline - 2.0, time.process_time() + 6.0),
                                     maxiter=200)
            if rb > bestR + 1e-13:
                best, bestR = hb, rb
                cur, curR = hb.copy(), rb

        # Escape local optima: perturb and revive zeros, then re-polish.
        if time.process_time() < deadline - 4.0:
            for scale in (0.02, 0.05, 0.10):
                if time.process_time() >= deadline - 3.0:
                    break
                cand = _perturb(best, rng, scale)
                cand = _fill_zeros(cand, rng, 0.15)
                hb, rb = _refine_support(
                    cand, min(deadline - 2.0, time.process_time() + 4.0),
                    maxiter=150)
                if rb > bestR + 1e-13:
                    best, bestR = hb, rb
                    cur, curR = hb.copy(), rb
                    print("  perturb %.2f improved -> R=%.7f" % (scale, bestR))
                    break

        zf = 100.0 * np.mean(best <= 0)
        am = int(np.argmax(_knots(best)))
        print("cycle %d R=%.7f argmax=%d zeros=%.1f%%" %
              (cycle, bestR, am, zf))

        if best.size * 2 <= 1000000 and time.process_time() < deadline - 15.0:
            up = _rescale(_upsample(best, 2))
            ru = R_of(up)
            if ru > bestR - 1e-6:
                print("upsample x2 -> R=%.7f (N=%d)" % (ru, up.size))
                best, bestR = up, ru
                cur, curR = up.copy(), ru
                hb, rb = _refine_support(best, deadline, maxiter=200)
                if rb > bestR:
                    best, bestR = hb, rb
                    cur, curR = hb.copy(), rb

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _detect_period(h):
    n = h.size
    mx = h.max() if h.size else 0.0
    if mx <= 0:
        return 1
    tol = 1e-12 * mx
    for p in range(2, 65):
        if n % p != 0:
            continue
        m = n // p
        blocks = h.reshape(p, m)
        if np.max(np.abs(blocks - blocks[0])) < tol:
            return p
    return 1


def _resample(base, newN):
    n = base.size
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    h = np.interp(x_new, x_old, base)
    return _rescale(h)


def _local_peak_perturb(h, rng, strength=0.15):
    """Perturb heights only near the peak region of f*f."""
    h = h.copy()
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.95 * mx)
    lo = max(0, idx.min())
    hi = min(h.size, idx.max() + 1)
    # peak of convolution is around middle; heights near there
    wlen = max(1, int((hi - lo) * 0.5))
    s = max(0, lo)
    e = min(h.size, hi + wlen)
    noise = 1.0 + strength * rng.standard_normal(e - s)
    h[s:e] *= np.clip(noise, 0.0, None)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best)))

    rng = np.random.default_rng(987654321)

    # Phase 1: aggressive near-peak perturbation + tie LBFGS on full vector.
    # This is the key: the current optimum is a sharp peak with ties, so
    # perturbing heights near the peak and re-converging can find better ties.
    phase1_end = t0 + budget_seconds * 0.55
    tries = 0
    accepted = 0
    cur = best.copy()
    while time.process_time() < phase1_end - 3.0:
        tries += 1
        if tries == 1:
            cand = cur.copy()
        else:
            strength = rng.uniform(0.05, 0.30)
            cand = _local_peak_perturb(cur, rng, strength=strength)
        slice_end = min(phase1_end, time.process_time() + 6.0)
        h = _lbfgs_all_pos(cand, 400, slice_end - 3.0, tie=True)
        if time.process_time() < slice_end - 2.5:
            h = _peak_ladder(h, slice_end - 0.5,
                             pads=(0.10, 0.06, 0.04, 0.02), iters=250)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            cur = h.copy()
            accepted += 1
            print("P1 try %d ACCEPT R=%.9f (+%.2e)" % (tries, r, r - startR))
        elif r > bestR - 1e-7:
            # keep near-best to avoid stagnation
            cur = h.copy()
        if tries % 10 == 0:
            print("P1 tries=%d accepted=%d best=%.9f" % (tries, accepted, bestR))

    # Phase 2: final polish with full LBFGS and peak ladder.
    fd = t0 + budget_seconds * 0.90
    it = 0
    while time.process_time() < fd - 3.0:
        it += 1
        slice_end = min(fd, time.process_time() + 7.0)
        h_t = _lbfgs_all_pos(best, 600, slice_end - 3.0, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("P2 tie %d ACCEPT R=%.9f" % (it, bestR))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03, 0.02), iters=300)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("P2 peak %d ACCEPT R=%.9f" % (it, bestR))

    fd2 = t0 + budget_seconds * 0.92
    if time.process_time() < fd2 - 3.0:
        h_t = _lbfgs_all_pos(best, 600, fd2 - 2.0, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, startR, best.size, _zero_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

