def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _coarse_vcycle(s, slice_deadline, rng):
    n = s.size
    off = int(rng.integers(0, 2))
    body = s[off:]
    if body.size % 2 == 1:
        body = np.concatenate((body, [0.0]))
    hc = body.reshape(-1, 2).sum(axis=1)
    hc = _rescale(hc)
    hc = _lbfgs_all_pos(hc, 300, slice_deadline, beta=0.0)
    if time.process_time() < slice_deadline - 0.3:
        hc = _lbfgs_all_pos(hc, 200, slice_deadline, beta=1e7)
    up = np.repeat(hc, 2)
    if off > 0:
        up = np.concatenate((np.zeros(off), up))
    up = up[:n]
    if up.size < n:
        up = np.concatenate((up, np.zeros(n - up.size)))
    up = _rescale(up)
    return _lbfgs_all_pos(up, 250, slice_deadline, beta=0.0)


def _jitter_reseed(base, rng, sigma=0.05):
    h = base.copy()
    active = h > 0
    if active.sum() == 0:
        return _rescale(base)
    noise = rng.normal(0.0, sigma, size=h.size)
    h[active] = h[active] * np.exp(noise[active])
    return _rescale(h)


def _tail_poke(h, deadline, rng, frac=0.05, tries=8):
    best = h.copy()
    bestR = R_of(h)
    n = h.size
    active = np.flatnonzero(h > 0)
    if active.size < 8:
        return best
    lo, hi = int(active[0]), int(active[-1])
    width = max(8, int((hi - lo + 1) * frac))
    for t in range(tries):
        if time.process_time() >= deadline - 0.5:
            break
        side = rng.integers(0, 2)
        if side == 0:
            a = lo
            b = min(hi, lo + width)
        else:
            a = max(lo, hi - width)
            b = hi
        cand = h.copy()
        seg = cand[a:b + 1]
        if seg.size == 0:
            continue
        amp = rng.uniform(0.7, 1.3)
        x = np.linspace(-1.0, 1.0, seg.size)
        shape = 1.0 + (amp - 1.0) * np.exp(-3.0 * x * x)
        cand[a:b + 1] = seg * shape
        cand = _rescale(cand)
        win = np.arange(max(0, a - 16), min(n, b + 16 + 1))
        cand = _lbfgs_block(cand, win, 150, deadline - 0.3, beta=1e6)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand, r
    return best


def _interior_poke(h, deadline, rng, tries=6):
    best = h.copy()
    bestR = R_of(h)
    n = h.size
    active = np.flatnonzero(h > 0)
    if active.size < 16:
        return best
    lo, hi = int(active[0]), int(active[-1])
    span = hi - lo + 1
    for _ in range(tries):
        if time.process_time() >= deadline - 0.5:
            break
        w = max(16, int(span * rng.uniform(0.05, 0.20)))
        a = int(rng.integers(lo, max(lo + 1, hi - w + 1)))
        b = min(hi, a + w)
        cand = h.copy()
        seg = cand[a:b + 1]
        if seg.size == 0:
            continue
        slope = rng.uniform(-0.15, 0.15)
        x = np.linspace(-1.0, 1.0, seg.size)
        cand[a:b + 1] = seg * (1.0 + slope * x)
        cand = _rescale(cand)
        win = np.arange(max(0, a - 8), min(n, b + 8 + 1))
        cand = _lbfgs_block(cand, win, 120, deadline - 0.3, beta=1e6)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand, r
    return best


# ---- NEW: fast local coordinate refinement on the peak region ----
def _peak_refine_1d(h, deadline, rng, sweeps=2, k=40):
    """Coordinate-wise multiplicative refinement of heights in the peak
    region.  Each coordinate is tried with a small set of multipliers and
    the best accepted; cheap and effective at polishing flat maxima."""
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    lo = max(0, idx.min() - k)
    hi = min(n - 1, idx.max() + k)
    coords = np.arange(lo, hi + 1)
    if coords.size == 0:
        return h
    best = h.copy()
    bestR = R_of(best)
    mults = np.array([0.85, 0.93, 0.97, 1.03, 1.07, 1.15])
    order = rng.permutation(coords)
    for sw in range(sweeps):
        if time.process_time() >= deadline - 0.5:
            break
        improved = False
        for c in order:
            if time.process_time() >= deadline - 0.5:
                break
            base_val = best[c]
            if base_val <= 0:
                continue
            bR = bestR
            bMult = 1.0
            for mu in mults:
                trial = best.copy()
                trial[c] = base_val * mu
                trial = _rescale(trial)
                r = R_of(trial)
                if r > bR + 1e-15:
                    bR = r
                    bMult = mu
            if bMult != 1.0:
                best[c] = base_val * bMult
                best = _rescale(best)
                bestR = bR
                improved = True
        if not improved:
            break
        order = rng.permutation(coords)
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    amax0 = _argmax_frac(best)
    rng = np.random.default_rng(12345)

    states = {'A': best.copy(), 'B': best.copy(), 'C': best.copy()}
    state_R = {'A': bestR, 'B': bestR, 'C': bestR}
    gain = {'A': 0.0, 'B': 0.0, 'C': 0.0}
    reseeds = {'A': 0, 'B': 0, 'C': 0}

    slice_len = 4.0
    sched_deadline = t0 + budget_seconds * 0.86
    labels = ['A', 'B', 'C']
    li = 0

    while time.process_time() < sched_deadline - 0.5:
        lab = labels[li % 3]
        li += 1
        slice_deadline = min(time.process_time() + slice_len, sched_deadline)
        s = states[lab]

        if lab == 'A':
            s = _lbfgs_all_pos(s, 600, slice_deadline, beta=0.0)
            if time.process_time() < slice_deadline - 0.3:
                s = _lbfgs_all_pos(s, 200, slice_deadline, beta=1e8)
        elif lab == 'B':
            for beta in (1e5, 1e6, 1e8):
                if time.process_time() >= slice_deadline - 0.3:
                    break
                s = _lbfgs_all_pos(s, 250, slice_deadline, beta=beta)
            if time.process_time() < slice_deadline - 0.5:
                s = _peak_ladder(s, slice_deadline, pads=(0.20, 0.10, 0.05),
                                 iters=200)
        else:
            s = _coarse_vcycle(s, slice_deadline, rng)

        r = R_of(s)
        state_R[lab] = r
        states[lab] = s

        if r > bestR + 1e-14:
            gain[lab] += r - bestR
            best = s.copy()
            bestR = r
            print("ACCEPT %s R=%.9f dR=%.3e" % (lab, bestR, r - bestR))

        if state_R[lab] < bestR - 1e-7:
            if time.process_time() < sched_deadline - 0.5:
                seed = _jitter_reseed(best, rng, sigma=0.05)
                seed = _lbfgs_all_pos(seed, 100,
                                      min(time.process_time() + 1.5,
                                          sched_deadline), beta=0.0)
                rs = R_of(seed)
                states[lab] = seed
                state_R[lab] = rs
                reseeds[lab] += 1
                if rs > bestR + 1e-14:
                    gain[lab] += rs - bestR
                    best = seed.copy()
                    bestR = rs
                    print("RESEED-ACCEPT %s R=%.9f dR=%.3e"
                          % (lab, bestR, rs - bestR))

    for lab in labels:
        print("label %s cumulative gain=%.3e reseeds=%d"
              % (lab, gain[lab], reseeds[lab]))

    # ---- NEW: peak-region coordinate refinement ----
    ref_deadline = t0 + budget_seconds * 0.91
    ht = _peak_refine_1d(best, ref_deadline, rng, sweeps=3, k=48)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("PEAK-REFINE ACCEPT R=%.9f dR=%.3e" % (bestR, r - bestR))
    else:
        print("PEAK-REFINE reject R=%.9f" % r)

    # ---- Tail + interior poke stage ----
    poke_deadline = t0 + budget_seconds * 0.94
    ht = _tail_poke(best, poke_deadline, rng, frac=0.06, tries=10)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("TAIL poke ACCEPT R=%.9f dR=%.3e" % (bestR, r - bestR))
    else:
        print("TAIL poke reject R=%.9f" % r)

    poke_deadline = t0 + budget_seconds * 0.96
    ht = _interior_poke(best, poke_deadline, rng, tries=8)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("INTERIOR poke ACCEPT R=%.9f dR=%.3e" % (bestR, r - bestR))
    else:
        print("INTERIOR poke reject R=%.9f" % r)

    # ---- Final full beta=0 polish ----
    polish_deadline = t0 + budget_seconds * 0.975
    ht = _lbfgs_all_pos(best, 4000, polish_deadline, beta=0.0)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("FINAL polish ACCEPT R=%.9f dR=%.3e" % (bestR, r - bestR))
    else:
        print("FINAL polish reject R=%.9f dR=%.3e" % (r, r - bestR))

    # ---- Peak ladder polish ----
    peak_deadline = t0 + budget_seconds * 0.995
    ht = _peak_ladder(best, peak_deadline, pads=(0.05, 0.03), iters=300)
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("PEAK ladder ACCEPT R=%.9f dR=%.3e" % (bestR, r - bestR))
    else:
        print("PEAK ladder reject R=%.9f dR=%.3e" % (r, r - bestR))

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        alt = _peak_refine_1d(start_best, t0 + budget_seconds * 0.999,
                              rng, sweeps=2, k=40)
        result["alternative"] = alt if R_of(alt) > bestR else best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _coarsen(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nc)
    edges = np.linspace(0.0, total, Nc + 1)
    vals = np.interp(edges, np.linspace(0.0, total, n + 1), c)
    hc = np.diff(vals)
    hc = np.clip(hc, 0.0, None)
    return hc


def _prolong(hc, N):
    Nc = hc.size
    if Nc == N:
        return hc.copy()
    c = np.concatenate(([0.0], np.cumsum(hc)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    edges = np.linspace(0.0, total, N + 1)
    vals = np.interp(edges, np.linspace(0.0, total, Nc + 1), c)
    hf = np.diff(vals)
    hf = np.clip(hf, 0.0, None)
    return hf


def _interp_matrix(Nc, K):
    centers = (np.arange(K) + 0.5) / K
    x = (np.arange(Nc) + 0.5) / Nc
    P = np.zeros((Nc, K))
    for k in range(K):
        ck = centers[k]
        left = 0.0 if k == 0 else centers[k - 1]
        right = 1.0 if k == K - 1 else centers[k + 1]
        w = np.zeros(Nc)
        mid = (x >= left) & (x <= ck)
        if ck > left:
            w[mid] = (x[mid] - left) / (ck - left)
        w[x < left] = 0.0
        mid2 = (x > ck) & (x <= right)
        if right > ck:
            w[mid2] = (right - x[mid2]) / (right - ck)
        w[x > right] = 0.0
        w[np.abs(x - ck) < 1e-15] = 1.0
        P[:, k] = w
    rs = P.sum(axis=1)
    rs[rs <= 0] = 1.0
    P = P / rs[:, None]
    return P


def _param_opt(c0, P, theta0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return theta0, R_of(c0)
    K = P.shape[1]

    def obj(theta):
        s = P.dot(theta)
        s = np.clip(s, -30.0, 30.0)
        c = c0 * np.exp(s)
        val, g = _fun_grad_tie(c)
        gtheta = P.T.dot(g * c)
        return val, gtheta

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(obj, theta0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
        if res is None:
            return theta0, R_of(c0)
        th = res.x
    except (TimeoutError, Exception):
        return theta0, R_of(c0)
    s = np.clip(P.dot(th), -30.0, 30.0)
    c = c0 * np.exp(s)
    return th, R_of(c)


def _interp_theta(theta, K_old, K_new):
    P_old = _interp_matrix(K_new, K_old)
    return P_old.dot(theta)


def _project_theta(c, c0, P):
    s = np.log(np.clip(c, 1e-300, None) / np.clip(c0, 1e-300, None))
    s = np.clip(s, -30.0, 30.0)
    try:
        th, *_ = np.linalg.lstsq(P, s, rcond=None)
    except Exception:
        return np.zeros(P.shape[1])
    return th


def _report(tag, h):
    f01, f1, f5 = _nearmax_fracs(h)
    print("  %s R=%.9f N=%d zero=%.4f near 0.1%%/1%%/5%%=%.4f/%.4f/%.4f"
          % (tag, R_of(h), h.size, _zero_frac(h), f01, f1, f5))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Phase 1: coarsen start to Nc=2048 ----
    Nc = 2048
    c0 = _coarsen(best, Nc)
    c0 = _rescale(c0)
    Rc0 = R_of(c0)
    print("coarse Nc=%d R=%.9f" % (Nc, Rc0))

    best_c = c0.copy()
    best_cR = Rc0
    theta_warm = None
    K_prev = 0

    env_end = t0 + budget_seconds * 0.55
    # ---- Phase 2: extended K ladder [64,128,256,512] ----
    for K in (64, 128, 256, 512):
        if time.process_time() >= env_end - 3.0:
            break
        P = _interp_matrix(Nc, K)
        if theta_warm is None:
            theta0 = np.zeros(K)
        else:
            theta0 = _interp_theta(theta_warm, K_prev, K)
        th, r = _param_opt(best_c, P, theta0, 400, env_end - 1.0)
        s = np.clip(P.dot(th), -30.0, 30.0)
        c_env = _rescale(best_c * np.exp(s))
        r_env = R_of(c_env)
        tinf = float(np.max(np.abs(th)))
        print("  K=%d envelope R=%.9f ||theta||inf=%.4f" % (K, r_env, tinf))
        if r_env > best_cR + 1e-15:
            best_c = c_env
            best_cR = r_env
        theta_warm = th
        K_prev = K

        if time.process_time() < env_end - 2.0:
            c_free = _lbfgs_all_pos(best_c, 250, env_end - 0.5, tie=True)
            r_free = R_of(c_free)
            print("  K=%d free2048 R=%.9f (env %.9f)" % (K, r_free, best_cR))
            if r_free > best_cR + 1e-15:
                best_c = c_free
                best_cR = r_free
                theta_warm = _project_theta(best_c, c0, P)
                print("  K=%d free ACCEPT, re-warm theta" % K)

    print("best coarse R=%.9f" % best_cR)

    # ---- Phase 3: free Nc=4096 solve ----
    if time.process_time() < env_end - 2.0:
        Nc2 = 4096
        c4096 = _prolong(best_c, Nc2)
        c4096 = _rescale(c4096)
        R4096_0 = R_of(c4096)
        c4096_opt = _lbfgs_all_pos(c4096, 250, env_end - 0.5, tie=True)
        R4096_1 = R_of(c4096_opt)
        print("free Nc=4096 R: %.9f -> %.9f" % (R4096_0, R4096_1))
        if R4096_1 > R4096_0 + 1e-15:
            c_back = _coarsen(c4096_opt, Nc)
            c_back = _rescale(c_back)
            R_back = R_of(c_back)
            if R_back > best_cR + 1e-15:
                best_c = c_back
                best_cR = R_back
                print("free-4096 ACCEPT coarse R=%.9f" % best_cR)

    # ---- Phase 4: prolongation ladder with free solve + peak polish at each level ----
    # Start from best_c at Nc, prolong through 16384, 65536, then N.
    ladder_end = t0 + budget_seconds * 0.88
    cur = _prolong(best_c, Nc)
    cur = _rescale(cur)
    curR = R_of(cur)
    _report("ladder-start", cur)

    for Nlvl in (16384, 65536):
        if time.process_time() >= ladder_end - 4.0:
            break
        nxt = _prolong(cur, Nlvl)
        nxt = _rescale(nxt)
        r_lift = R_of(nxt)
        print("  lift -> N=%d R=%.9f (from %.9f)" % (Nlvl, r_lift, curR))
        # free solve at this resolution
        h_free = _lbfgs_all_pos(nxt, 150, ladder_end - 2.5, tie=True)
        r_free = R_of(h_free)
        if r_free > r_lift + 1e-15:
            nxt, r_lift = h_free, r_free
            print("  free N=%d R=%.9f" % (Nlvl, r_lift))
        # peak-window polish at this resolution
        for pad in (0.15, 0.08):
            if time.process_time() >= ladder_end - 1.5:
                break
            win = _peak_window(nxt, pad_frac=pad, extra=128)
            ht = _lbfgs_block(nxt, win, 250, ladder_end - 0.5, beta=1e7)
            r = R_of(ht)
            if r > r_lift + 1e-15:
                nxt, r_lift = ht, r
        cur = nxt
        curR = r_lift
        _report("N=%d" % Nlvl, cur)

    # ---- Phase 5: lift to N and full peak ladder + final tie polish ----
    h_lift = _prolong(cur, N)
    h_lift = _rescale(h_lift)
    R_lift = R_of(h_lift)
    print("lifted fine R=%.9f (start %.9f)" % (R_lift, startR))

    cand = h_lift.copy()
    candR = R_lift

    peak_end = t0 + budget_seconds * 0.94
    for beta in (1e7,):
        for pad in (0.10, 0.06, 0.03):
            if time.process_time() >= peak_end - 1.5:
                break
            win = _peak_window(cand, pad_frac=pad, extra=128)
            ht = _lbfgs_block(cand, win, 300, peak_end - 0.5, beta=beta)
            r = R_of(ht)
            if r > candR + 1e-15:
                cand, candR = ht, r
    print("after peak ladder R=%.9f" % candR)

    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 2.0:
        h_t = _lbfgs_all_pos(cand, 400, fd - 1.0, tie=True)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("tie ACCEPT R=%.9f ties=%d" % (candR, _tie_count(cand)))

    _report("candidate", cand)

    if candR > bestR + 1e-15:
        best, bestR = cand, candR
        print("LADDER WINS R=%.9f (start %.9f)" % (bestR, startR))
        result = {"best": best}
    else:
        print("no gain (cand %.9f vs start %.9f); returning alternative"
              % (candR, startR))
        result = {"best": best, "alternative": cand}

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


