        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Phase 1: coarsen start to Nc=2048 ----
    Nc = 2048
    c0 = _coarsen(best, Nc)
    c0 = _rescale(c0)
    Rc0 = R_of(c0)
    print("coarse Nc=%d R=%.9f" % (Nc, Rc0))

    best_c = c0.copy()
    best_cR = Rc0
    theta_warm = None
    K_prev = 0

    env_end = t0 + budget_seconds * 0.55
    # ---- Phase 2: extended K ladder [64,128,256,512] ----
    for K in (64, 128, 256, 512):
        if time.process_time() >= env_end - 3.0:
            break
        P = _interp_matrix(Nc, K)
        if theta_warm is None:
            theta0 = np.zeros(K)
        else:
            theta0 = _interp_theta(theta_warm, K_prev, K)
        th, r = _param_opt(best_c, P, theta0, 400, env_end - 1.0)
        s = np.clip(P.dot(th), -30.0, 30.0)
        c_env = _rescale(best_c * np.exp(s))
        r_env = R_of(c_env)
        tinf = float(np.max(np.abs(th)))
        print("  K=%d envelope R=%.9f ||theta||inf=%.4f" % (K, r_env, tinf))
        if r_env > best_cR + 1e-15:
            best_c = c_env
            best_cR = r_env
        theta_warm = th
        K_prev = K

        if time.process_time() < env_end - 2.0:
            c_free = _lbfgs_all_pos(best_c, 250, env_end - 0.5, tie=True)
            r_free = R_of(c_free)
            print("  K=%d free2048 R=%.9f (env %.9f)" % (K, r_free, best_cR))
            if r_free > best_cR + 1e-15:
                best_c = c_free
                best_cR = r_free
                theta_warm = _project_theta(best_c, c0, P)
                print("  K=%d free ACCEPT, re-warm theta" % K)

    print("best coarse R=%.9f" % best_cR)

    # ---- Phase 3: free Nc=4096 solve ----
    if time.process_time() < env_end - 2.0:
        Nc2 = 4096
        c4096 = _prolong(best_c, Nc2)
        c4096 = _rescale(c4096)
        R4096_0 = R_of(c4096)
        c4096_opt = _lbfgs_all_pos(c4096, 250, env_end - 0.5, tie=True)
        R4096_1 = R_of(c4096_opt)
        print("free Nc=4096 R: %.9f -> %.9f" % (R4096_0, R4096_1))
        if R4096_1 > R4096_0 + 1e-15:
            c_back = _coarsen(c4096_opt, Nc)
            c_back = _rescale(c_back)
            R_back = R_of(c_back)
            if R_back > best_cR + 1e-15:
                best_c = c_back
                best_cR = R_back
                print("free-4096 ACCEPT coarse R=%.9f" % best_cR)

    # ---- Phase 4: prolongation ladder with free solve + peak polish at each level ----
    # Start from best_c at Nc, prolong through 16384, 65536, then N.
    ladder_end = t0 + budget_seconds * 0.88
    cur = _prolong(best_c, Nc)
    cur = _rescale(cur)
    curR = R_of(cur)
    _report("ladder-start", cur)

    for Nlvl in (16384, 65536):
        if time.process_time() >= ladder_end - 4.0:
            break
        nxt = _prolong(cur, Nlvl)
        nxt = _rescale(nxt)
        r_lift = R_of(nxt)
        print("  lift -> N=%d R=%.9f (from %.9f)" % (Nlvl, r_lift, curR))
        # free solve at this resolution
        h_free = _lbfgs_all_pos(nxt, 150, ladder_end - 2.5, tie=True)
        r_free = R_of(h_free)
        if r_free > r_lift + 1e-15:
            nxt, r_lift = h_free, r_free
            print("  free N=%d R=%.9f" % (Nlvl, r_lift))
        # peak-window polish at this resolution
        for pad in (0.15, 0.08):
            if time.process_time() >= ladder_end - 1.5:
                break
            win = _peak_window(nxt, pad_frac=pad, extra=128)
            ht = _lbfgs_block(nxt, win, 250, ladder_end - 0.5, beta=1e7)
            r = R_of(ht)
            if r > r_lift + 1e-15:
                nxt, r_lift = ht, r
        cur = nxt
        curR = r_lift
        _report("N=%d" % Nlvl, cur)

    # ---- Phase 5: lift to N and full peak ladder + final tie polish ----
    h_lift = _prolong(cur, N)
    h_lift = _rescale(h_lift)
    R_lift = R_of(h_lift)
    print("lifted fine R=%.9f (start %.9f)" % (R_lift, startR))

    cand = h_lift.copy()
    candR = R_lift

    peak_end = t0 + budget_seconds * 0.94
    for beta in (1e7,):
        for pad in (0.10, 0.06, 0.03):
            if time.process_time() >= peak_end - 1.5:
                break
            win = _peak_window(cand, pad_frac=pad, extra=128)
            ht = _lbfgs_block(cand, win, 300, peak_end - 0.5, beta=beta)
            r = R_of(ht)
            if r > candR + 1e-15:
                cand, candR = ht, r
    print("after peak ladder R=%.9f" % candR)

    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 2.0:
        h_t = _lbfgs_all_pos(cand, 400, fd - 1.0, tie=True)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("tie ACCEPT R=%.9f ties=%d" % (candR, _tie_count(cand)))

    _report("candidate", cand)

    if candR > bestR + 1e-15:
        best, bestR = cand, candR
        print("LADDER WINS R=%.9f (start %.9f)" % (bestR, startR))
        result = {"best": best}
    else:
        print("no gain (cand %.9f vs start %.9f); returning alternative"
              % (candR, startR))
        result = {"best": best, "alternative": cand}

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _full_polish(h, slice_deadline, pads=(0.30, 0.15, 0.08)):
    ht = h
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= slice_deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
    for pad in pads:
        if time.process_time() >= slice_deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pad, extra=128)
        ht = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
    if time.process_time() < slice_deadline - 0.5:
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=0.0)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def try_alt(cand):
        nonlocal alt_best, alt_bestR
        r = R_of(cand)
        if r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return r

    # ---- Phase 1: quarter-fold / lift-4 chain ----
    N = best.size
    if N % 4 == 0 and N >= 8 and time.process_time() < deadline - 4.0:
        q4 = best[0::4].copy()
        print("q4 R=%.9f (n=%d)" % (R_of(q4), q4.size))
        slice_dl = t0 + budget_seconds * 0.28
        q4w = q4
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= slice_dl - 0.5:
                break
            q4w = _lbfgs_all_pos(q4w, 300, slice_dl - 0.3, beta=beta)
        if time.process_time() < slice_dl - 0.5:
            win = _peak_window(q4w, pad_frac=0.15, extra=128)
            q4w = _lbfgs_block(q4w, win, 400, slice_dl - 0.3, beta=1e7)
        print("q4 polished R=%.9f" % R_of(q4w))

        h_lift4 = _rescale(np.repeat(q4w, 4))
        lift_dl = t0 + budget_seconds * 0.52
        for beta in [1e6, 1e7]:
            if time.process_time() >= lift_dl - 0.5:
                break
            h_lift4 = _lbfgs_all_pos(h_lift4, 400, lift_dl - 0.3, beta=beta)
        r_lift4 = R_of(h_lift4)
        print("lift4 R=%.9f" % r_lift4)
        if r_lift4 > bestR + 1e-14:
            best, bestR, origin = h_lift4.copy(), r_lift4, 'lift4'
            print("lift4 NEW BEST R=%.9f" % bestR)
        else:
            try_alt(h_lift4)
            print("lift4 no gain (best %.9f)" % bestR)

    # ---- Phase 2: half-cycle alternation ----
    cycle = 0
    accepted = 0
    while cycle < 3 and time.process_time() < deadline - 6.0:
        cycle += 1
        if best.size % 2 != 0:
            break
        c = best[0::2].copy()
        slice_dl = min(deadline - 3.0, time.process_time() + 8.0)
        cc = _full_polish(c, slice_dl, pads=(0.15, 0.08))
        rc = R_of(cc)
        hl = _rescale(np.repeat(cc, 2))
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            hl = _lbfgs_all_pos(hl, 400, deadline - 1.5, beta=beta)
        rl = R_of(hl)
        if rl > bestR + 1e-13:
            best, bestR, origin = hl.copy(), rl, 'cycle%d' % cycle
            accepted += 1
            print("half-cycle %d R(c)=%.9f R(hl)=%.9f ACCEPT R=%.9f"
                  % (cycle, rc, rl, bestR))
        else:
            try_alt(hl)
            print("half-cycle %d R(c)=%.9f R(hl)=%.9f no gain (best %.9f)"
                  % (cycle, rc, rl, bestR))

    # ---- Phase 3: peak polish + trailing beta=0 ----
    if time.process_time() < deadline - 2.0:
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pk'
            print("peak polish NEW BEST R=%.9f" % bestR)
        else:
            try_alt(ht)
        if time.process_time() < deadline - 1.0:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+all0'
                print("trailing all0 NEW BEST R=%.9f" % bestR)
            else:
                try_alt(ht2)

    print("cycles=%d accepted=%d best_full=%.9f" %
          (cycle, accepted, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

