    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _full_polish(h, slice_deadline, pads=(0.30, 0.15, 0.08)):
    ht = h
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= slice_deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
    for pad in pads:
        if time.process_time() >= slice_deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pad, extra=128)
        ht = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
    if time.process_time() < slice_deadline - 0.5:
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=0.0)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def try_alt(cand):
        nonlocal alt_best, alt_bestR
        r = R_of(cand)
        if r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return r

    # ---- Phase 1: quarter-fold / lift-4 chain ----
    N = best.size
    if N % 4 == 0 and N >= 8 and time.process_time() < deadline - 4.0:
        q4 = best[0::4].copy()
        print("q4 R=%.9f (n=%d)" % (R_of(q4), q4.size))
        slice_dl = t0 + budget_seconds * 0.28
        q4w = q4
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= slice_dl - 0.5:
                break
            q4w = _lbfgs_all_pos(q4w, 300, slice_dl - 0.3, beta=beta)
        if time.process_time() < slice_dl - 0.5:
            win = _peak_window(q4w, pad_frac=0.15, extra=128)
            q4w = _lbfgs_block(q4w, win, 400, slice_dl - 0.3, beta=1e7)
        print("q4 polished R=%.9f" % R_of(q4w))

        h_lift4 = _rescale(np.repeat(q4w, 4))
        lift_dl = t0 + budget_seconds * 0.52
        for beta in [1e6, 1e7]:
            if time.process_time() >= lift_dl - 0.5:
                break
            h_lift4 = _lbfgs_all_pos(h_lift4, 400, lift_dl - 0.3, beta=beta)
        r_lift4 = R_of(h_lift4)
        print("lift4 R=%.9f" % r_lift4)
        if r_lift4 > bestR + 1e-14:
            best, bestR, origin = h_lift4.copy(), r_lift4, 'lift4'
            print("lift4 NEW BEST R=%.9f" % bestR)
        else:
            try_alt(h_lift4)
            print("lift4 no gain (best %.9f)" % bestR)

    # ---- Phase 2: half-cycle alternation ----
    cycle = 0
    accepted = 0
    while cycle < 3 and time.process_time() < deadline - 6.0:
        cycle += 1
        if best.size % 2 != 0:
            break
        c = best[0::2].copy()
        slice_dl = min(deadline - 3.0, time.process_time() + 8.0)
        cc = _full_polish(c, slice_dl, pads=(0.15, 0.08))
        rc = R_of(cc)
        hl = _rescale(np.repeat(cc, 2))
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            hl = _lbfgs_all_pos(hl, 400, deadline - 1.5, beta=beta)
        rl = R_of(hl)
        if rl > bestR + 1e-13:
            best, bestR, origin = hl.copy(), rl, 'cycle%d' % cycle
            accepted += 1
            print("half-cycle %d R(c)=%.9f R(hl)=%.9f ACCEPT R=%.9f"
                  % (cycle, rc, rl, bestR))
        else:
            try_alt(hl)
            print("half-cycle %d R(c)=%.9f R(hl)=%.9f no gain (best %.9f)"
                  % (cycle, rc, rl, bestR))

    # ---- Phase 3: peak polish + trailing beta=0 ----
    if time.process_time() < deadline - 2.0:
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 1.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pk'
            print("peak polish NEW BEST R=%.9f" % bestR)
        else:
            try_alt(ht)
        if time.process_time() < deadline - 1.0:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+all0'
                print("trailing all0 NEW BEST R=%.9f" % bestR)
            else:
                try_alt(ht2)

    print("cycles=%d accepted=%d best_full=%.9f" %
          (cycle, accepted, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = np.clip(beta * (Lf - M), -60.0, 60.0)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = _fun_grad if beta is None else (lambda hh: _fun_grad_sm(hh, beta))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad if beta is None else (lambda hh: _fun_grad_sm(hh, beta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _upsample(h, factor=2):
    n = h.size
    x_old = np.linspace(0.0, 1.0, n)
    nn = n * factor
    x_new = np.linspace(0.0, 1.0, nn)
    return np.interp(x_new, x_old, h)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _refine_peak(h, deadline, max_rounds=6):
    """Local block refinement concentrated around peak: cheapest, most reliable gain."""
    n = h.size
    for _ in range(max_rounds):
        if time.process_time() >= deadline - 0.4:
            break
        improved = False
        lo, hi = _peak_region(h, tol=0.9995)
        span = hi - lo
        for frac, extra in ((0.5, 32), (0.25, 16), (0.12, 8), (0.06, 4), (0.03, 2)):
            if time.process_time() >= deadline - 0.3:
                break
            pad = max(extra, int(span * frac))
            l2 = max(0, lo - pad); h2 = min(n - 1, hi + pad)
            c = _lbfgs_block(h, np.arange(l2, h2 + 1), 300, deadline)
            if R_of(c) > R_of(h):
                h = c
                improved = True
        if not improved:
            break
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_end = t0 + budget_seconds - 1.2

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=hard_end)
        return cur

    best = start_arr.copy()
    best_r = R_of(best)
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            alternative, alt_r = best.copy(), best_r
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # Primary work: refine the start at its own resolution around the peak,
    # with a couple of smoothing schedules, until the budget runs out.
    cur = best.copy()
    for beta in (300.0, 120.0, 50.0, 20.0):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _lbfgs_log(cur, maxiter=400, deadline=hard_end, beta=beta)
        if R_of(c) >= R_of(cur):
            cur = c
    if time.process_time() < hard_end - 0.5:
        c = _lbfgs_log(cur, maxiter=800, deadline=hard_end)
        if R_of(c) >= R_of(cur):
            cur = c
    _consider(cur, R_of(cur))
    print("smooth R=%.6f N=%d" % (best_r, best.size))

    # Local peak refinement loop on best.
    while time.process_time() < hard_end - 0.9:
        h = _refine_peak(best.copy(), hard_end)
        r = R_of(h)
        if r > best_r:
            _consider(h, r)
        else:
            break
    print("refine R=%.6f N=%d" % (best_r, best.size))

    # Upsample once with generous smoothing to try a finer discretisation.
    if time.process_time() < hard_end - 3.0 and start_arr.size <= 250000:
        up = _upsample(best, 2)
        h = up
        for beta in (200.0, 60.0, 20.0):
            if time.process_time() >= hard_end - 1.0:
                break
            c = _lbfgs_log(h, maxiter=300, deadline=hard_end, beta=beta)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 0.9:
            h = _refine_peak(h, hard_end)
        _consider(h, R_of(h))
        print("upsample R=%.6f N=%d" % (best_r, best.size))

    # Final polish on whatever is best.
    while time.process_time() < hard_end - 0.6:
        c = _lbfgs_log(best.copy(), maxiter=400, deadline=hard_end)
        if R_of(c) > best_r:
            _consider(c, R_of(c))
            best = _refine_peak(best, hard_end)
            best_r = R_of(best)
        else:
            break
    print("polish R=%.6f N=%d" % (best_r, best.size))

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None and alt_r > -1 and alt_r < best_r:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, bestR, deadline):
    work = h.copy()
    best = h.copy()
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            work, best, bestR = ht, ht.copy(), r
    for pad in [0.25, 0.15, 0.10, 0.06]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-15:
                work, best, bestR = ht2, ht2.copy(), r2
    return best, bestR


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 2:
        return None
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _upsample(c, factor):
    return np.repeat(c, factor)


def _perturb(h, rng, amp):
    """Random multiplicative/structural perturbation."""
    n = h.size
    mode = rng.randint(0, 3)
    if mode == 0:
        # subtle height jitter
        noise = 1.0 + amp * rng.randn(n)
        return _rescale(np.clip(h * noise, 0, None))
    elif mode == 1:
        # flip a random small block to zero / small
        hh = h.copy()
        i = rng.randint(0, n)
        w = rng.randint(1, max(2, n // 200))
        hh[i:i + w] = 0.0
        return _rescale(hh)
    else:
        # add small random mass
        hh = h.copy()
        i = rng.randint(0, n)
        w = rng.randint(1, max(2, n // 300))
        hh[i:i + w] += amp * hh.mean()
        return _rescale(hh)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ============ PHASE A: quick fine polish of start ============
    hA, rA = _polish(best, bestR, t0 + budget_seconds * 0.20)
    if rA > bestR + 1e-15:
        best, bestR, origin = hA.copy(), rA, 'polish-start'
        print("polish-start R=%.9f" % bestR)
    elif rA > alt_bestR:
        alt_best, alt_bestR = hA.copy(), rA

    # ============ PHASE B: multi-scale re-derivation ============
    scale_deadline = t0 + budget_seconds * 0.60
    for factor in [2, 4, 8]:
        if time.process_time() >= scale_deadline - 1.0:
            break
        cur = best
        seeds = [cur]
        if start_best is not None and start_best.size == cur.size:
            seeds.append(start_best)
        for si, seed in enumerate(seeds):
            if time.process_time() >= scale_deadline - 1.0:
                break
            c = _downsample(seed, factor)
            if c is None or c.sum() <= 0:
                continue
            c = _rescale(c)
            cR = R_of(c)
            sub_deadline = min(scale_deadline - 0.5,
                               time.process_time() + (scale_deadline - time.process_time()) / 2.0)
            cc, ccR = _polish(c, cR, sub_deadline)
            h_up = _rescale(_upsample(cc, factor))
            if h_up.size != best.size:
                if h_up.size < best.size:
                    h_up = np.concatenate([h_up, np.zeros(best.size - h_up.size)])
                else:
                    h_up = h_up[:best.size]
                h_up = _rescale(h_up)
            r_up = R_of(h_up)
            h_fine, r_fine = _polish(h_up, r_up, scale_deadline - 0.5)
            print("  scale f=%d s=%d: coarse %.9f -> up %.9f -> fine %.9f" %
                  (factor, si, ccR, r_up, r_fine))
            if r_fine > bestR + 1e-15:
                best, bestR, origin = h_fine.copy(), r_fine, 'scale%d' % factor
                print("  SCALE NEW BEST R=%.9f" % bestR)
            elif r_fine > alt_bestR:
                alt_best, alt_bestR = h_fine.copy(), r_fine

    # ============ PHASE C: half-res fill/prune with LONGER polish ============
    # (a genuine improvement over p1342: use bigger window and more lbfgs iters
    #  per trial, and try more fill/prune candidates per round.)
    if best.size % 2 == 0 and best.size >= 8:
        cc = best[0::2].copy()
        ccR = R_of(cc)
        hd = t0 + budget_seconds * 0.65
        cc, ccR = _polish(cc, ccR, hd)
        print("half-res R(c)=%.9f" % ccR)

        rng = np.random.RandomState(4242)
        n = cc.size
        pos_mean = float(np.mean(cc[cc > 0])) if np.any(cc > 0) else 1.0
        win_half = 64  # larger window than p1342's 40
        trials = 0
        while time.process_time() < deadline - 1.5:
            nz = np.flatnonzero(cc > 0)
            if nz.size == 0:
                break
            runs = []
            s = nz[0]; p = nz[0]
            for q in nz[1:]:
                if q == p + 1:
                    p = q
                else:
                    runs.append((s, p)); s = q; p = q
            runs.append((s, p))
            masses = [(np.sum(cc[a:b + 1]), a, b) for a, b in runs]
            masses.sort(reverse=True)
            fill = []
            for m, a, b in masses[:12]:
                if a - 1 >= 0 and cc[a - 1] == 0:
                    fill.append(a - 1)
                if b + 1 < n and cc[b + 1] == 0:
                    fill.append(b + 1)
            for i in range(1, n - 1):
                if cc[i] == 0 and cc[i - 1] > 0 and cc[i + 1] > 0:
                    fill.append(i)
            fill = list(dict.fromkeys(fill))
            rng.shuffle(fill)

            nz_idx = np.flatnonzero(cc > 0)
            prune = list(nz_idx[np.argsort(cc[nz_idx])[:16]]) if nz_idx.size > 0 else []

            made = False
            for i in fill:
                if time.process_time() >= deadline - 1.5:
                    break
                if cc[i] != 0:
                    continue
                for eps in (5e-3, 3e-2, 0.15, 0.5):
                    if time.process_time() >= deadline - 1.5:
                        break
                    cc2 = cc.copy()
                    cc2[i] = eps * pos_mean
                    win = np.arange(max(0, i - win_half), min(n, i + win_half + 1))
                    cc2 = _lbfgs_block(cc2, win, 150, deadline - 1.0, beta=1e7)
                    if time.process_time() < deadline - 1.2:
                        cc2 = _lbfgs_block(cc2, win, 100, deadline - 1.0, beta=0.0)
                    r2 = R_of(cc2)
                    trials += 1
                    if r2 > ccR + 1e-13:
                        cc, ccR = cc2, r2
                        made = True
                        print("fill i=%d eps=%g R(c)=%.9f" % (i, eps, ccR))
                        break
                if made:
                    break
            if not made:
                for i in prune:
                    if time.process_time() >= deadline - 1.5:
                        break
                    if cc[i] == 0:
                        continue
                    cc2 = cc.copy()
                    cc2[i] = 0.0
                    win = np.arange(max(0, i - win_half), min(n, i + win_half + 1))
                    cc2 = _lbfgs_block(cc2, win, 150, deadline - 1.0, beta=1e7)
                    if time.process_time() < deadline - 1.2:
                        cc2 = _lbfgs_block(cc2, win, 100, deadline - 1.0, beta=0.0)
                    r2 = R_of(cc2)
                    trials += 1
                    if r2 > ccR + 1e-13:
                        cc, ccR = cc2, r2
                        made = True
                        print("prune i=%d R(c)=%.9f" % (i, ccR))
                        break
            if not made:
                break

        h_lift = _rescale(np.repeat(cc, 2))
        h_fine, r_fine = _polish(h_lift, R_of(h_lift), deadline - 0.5)
        print("half-res final: lift %.9f -> fine %.9f" % (R_of(h_lift), r_fine))
        if r_fine > bestR + 1e-15:
            best, bestR, origin = h_fine.copy(), r_fine, 'half+fine'
            print("half+fine NEW BEST R=%.9f" % bestR)
        elif r_fine > alt_bestR:
            alt_best, alt_bestR = h_fine.copy(), r_fine

    # ============ PHASE D: random-perturbation basin hopping + final polish ============
    # (novel vs p1342: keep trying random structural perturbations of best,
    #  polish each briefly, keep improvements.)
    hop_rng = np.random.RandomState(9999)
    hop_best = best.copy()
    hop_bestR = bestR
    while time.process_time() < deadline - 0.8:
        amp = float(hop_rng.choice([0.02, 0.05, 0.1, 0.2]))
        cand = _perturb(hop_best, hop_rng, amp)
        r_c = R_of(cand)
        # short polish
        sub = min(deadline - 0.4, time.process_time() + 2.0)
        cand2, r_c2 = _polish(cand, r_c, sub)
        if r_c2 > hop_bestR + 1e-15:
            hop_best, hop_bestR = cand2, r_c2
            print("hop NEW R=%.9f (amp=%g)" % (hop_bestR, amp))

    if hop_bestR > bestR + 1e-15:
        best, bestR, origin = hop_best.copy(), hop_bestR, origin + '+hop'
        print("hop improved R=%.9f" % bestR)
    elif hop_bestR > alt_bestR and hop_bestR < bestR:
        alt_best, alt_bestR = hop_best.copy(), hop_bestR

    # Final polish until deadline
    if time.process_time() < deadline - 0.5:
        h_fin, r_fin = _polish(best, bestR, deadline - 0.2)
        if r_fin > bestR + 1e-16:
            best, bestR, origin = h_fin.copy(), r_fin, origin + '+final'
            print("final polish R=%.9f" % bestR)
        elif h_fin is not None and r_fin > alt_bestR and r_fin < bestR:
            alt_best, alt_bestR = h_fin.copy(), r_fin

    print("DONE R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0 or not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return -1.0
    return float(num / den)


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size, hi + pad + 1)
    return np.arange(lo, hi)


def _upsample_mass(h, factor):
    h = np.asarray(h, dtype=float)
    n = h.size
    N = n * factor
    c = np.concatenate(([0.0], np.cumsum(h)))
    fine = np.arange(N + 1) / factor
    cnew = np.interp(fine, np.arange(n + 1), c)
    out = np.diff(cnew)
    zero_blocks = h <= 0
    if np.any(zero_blocks):
        for i in np.nonzero(zero_blocks)[0]:
            out[i * factor:(i + 1) * factor] = 0.0
    return np.maximum(out, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    hard_deadline = t0 + budget_seconds - 2.0

    def time_left():
        return time.process_time() < min(deadline, hard_deadline)

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0 and np.all(s >= 0):
            best = s.copy()
            bestR = R_of(best)

    if best is None:
        best = np.ones(64)
        bestR = R_of(best)

    base = best.copy()
    baseR = bestR

    def try_accept(cand):
        nonlocal best, bestR
        rc = R_of(cand)
        if rc > bestR:
            bestR = rc
            best = cand.copy()
            return True
        return False

    # Alternative experiment: branch off start with a different trajectory
    alt = None
    altR = -1.0

    # Try: heavy smoothing (large beta) then sharp refinement at higher resolution
    if time_left():
        n0 = base.size
        # upsample to ~2x for extra resolution if cheap
        factor = 1
        if n0 * 2 <= 400000:
            factor = 2
        hu = _upsample_mass(base, factor) if factor > 1 else base.copy()
        # strong smoothing to find a basin
        c = _lbfgs(hu, 400, deadline, beta=300.0)
        if time_left():
            c = _lbfgs(c, 300, deadline, beta=30.0)
        if time_left():
            c = _lbfgs(c, 400, deadline, tie=True)
        rc = R_of(c)
        if rc > altR:
            altR = rc
            alt = c

    # peak-window alternation on the alt candidate
    if alt is not None and time_left():
        for _ in range(6):
            if not time_left():
                break
            win = _peak_window(alt)
            c2 = _lbfgs_block(alt, win, 200, deadline, tie=True)
            if R_of(c2) > altR:
                alt = c2
                altR = R_of(c2)
            c2 = _lbfgs(alt, 200, deadline, beta=10.0)
            if R_of(c2) > altR:
                alt = c2
                altR = R_of(c2)

    if alt is not None and altR > bestR:
        best = alt
        bestR = altR

    # Main refinement loop on best
    it = 0
    while time_left():
        it += 1
        # alternate: global sharp, tie-aware, peak window
        c = _lbfgs(best, 250, deadline, tie=True)
        try_accept(c)
        if not time_left():
            break
        win = _peak_window(best)
        c = _lbfgs_block(best, win, 200, deadline, tie=True)
        try_accept(c)
        if not time_left():
            break
        c = _lbfgs(best, 200, deadline, beta=30.0)
        try_accept(c)
        if not time_left():
            break
        # occasionally try a bigger window (whole support)
        if it % 3 == 0:
            c = _lbfgs(best, 300, deadline)
            try_accept(c)

    if alt is not None and altR > baseR and altR <= bestR and altR > 0:
        # alt is different from start and worth keeping
        return {"best": best, "alternative": alt}
    if alt is not None and altR > baseR and altR > bestR:
        return best
    if alt is not None and altR > baseR:
        return {"best": best, "alternative": alt}
    return best

