    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _full_polish(h, slice_deadline, pads=(0.30, 0.15, 0.08)):
    ht = h
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= slice_deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
    for pad in pads:
        if time.process_time() >= slice_deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pad, extra=128)
        ht = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
    if time.process_time() < slice_deadline - 0.5:
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=0.0)
    return ht


def _subpixel_refine(h, deadline, factor=2):
    """Refine at higher resolution: upsample, polish, downsample back."""
    if time.process_time() >= deadline - 2.0:
        return h
    n = h.size
    if n * factor > 900000:
        return h
    # linear upsample
    x_old = np.arange(n)
    x_new = np.linspace(0, n - 1, n * factor)
    up = np.interp(x_new, x_old, h)
    up = _rescale(up)
    r0 = R_of(h)
    up = _full_polish(up, deadline, pads=(0.15, 0.08))
    # downsample by averaging blocks
    dn = up.reshape(n, factor).mean(axis=1)
    dn = _rescale(dn)
    if R_of(dn) > r0 + 1e-14:
        return dn
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: subpixel refinement (key new idea) ----
    if time.process_time() < deadline - 20.0:
        slice_dl = t0 + budget_seconds * 0.35
        hs = _subpixel_refine(best, slice_dl, factor=2)
        rs = R_of(hs)
        print("subpixel R=%.9f (from %.9f)" % (rs, bestR))
        if rs > bestR + 1e-14:
            best, bestR, origin = hs.copy(), rs, 'subpixel'
            print("subpixel NEW BEST R=%.9f" % bestR)
        else:
            if rs > alt_bestR:
                alt_best, alt_bestR = hs.copy(), rs

    # ---- Phase 2: peak polish + trailing beta=0 on best ----
    if time.process_time() < deadline - 12.0:
        slice_dl = t0 + budget_seconds * 0.55
        ht = _full_polish(best, slice_dl, pads=(0.30, 0.15, 0.08))
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pol'
            print("polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: second subpixel pass at finer scale if time ----
    if time.process_time() < deadline - 8.0:
        slice_dl = t0 + budget_seconds * 0.78
        hs = _subpixel_refine(best, slice_dl, factor=2)
        rs = R_of(hs)
        print("subpixel2 R=%.9f" % rs)
        if rs > bestR + 1e-14:
            best, bestR, origin = hs.copy(), rs, origin + '+sp2'
            print("subpixel2 NEW BEST R=%.9f" % bestR)
        elif rs > alt_bestR:
            alt_best, alt_bestR = hs.copy(), rs

    # ---- Phase 4: final polish ----
    if time.process_time() < deadline - 2.0:
        ht = _full_polish(best, deadline - 1.0, pads=(0.15, 0.08))
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+fin'
            print("final polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _resample(h, N):
    """Linear-interpolate h onto N uniform steps (preserving shape)."""
    n = h.size
    if n == N:
        return h.copy()
    xo = np.linspace(0.0, 1.0, n)
    xn = np.linspace(0.0, 1.0, N)
    return np.clip(np.interp(xn, xo, h), 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR

    bestH = best.copy()
    bestRH = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    # ---- Coarse-to-fine refinement: resample to a smaller N, optimise, upsample ----
    # The idea: the shape lives at a coarse scale; optimising at reduced N escapes
    # local optima of the fine problem and finds a slightly different (better) basin.
    for Ncoarse in (2000, 4000, 8000):
        if time.process_time() > deadline - 6.0:
            break
        hc = _resample(bestH, Ncoarse)
        # global sharp polish on the coarse problem
        for _ in range(2):
            if time.process_time() > deadline - 5.0:
                break
            hc = _lbfgs_log(hc, 300, min(deadline - 4.0,
                                         time.process_time() + 5.0))
        # soft-max polish to break ties / plateau
        for beta in (1e2, 1e3):
            if time.process_time() > deadline - 4.0:
                break
            hc = _lbfgs_log(hc, 150, min(deadline - 3.0,
                                         time.process_time() + 2.5),
                            fg=lambda hh, b=beta: _fun_grad_beta(hh, b))
        rc = R_of(hc)
        # upsample back to original size and do a short fine polish
        hu = _rescale(_resample(hc, bestH.size))
        ru = R_of(hu)
        if ru > bestRH + 1e-13:
            sub = _lbfgs_log(hu, 300, min(deadline - 2.0,
                                          time.process_time() + 5.0))
            rs = R_of(sub)
            if rs > ru:
                hu, ru = sub, rs
        print("  coarse N=%d R=%.7f -> upsampled R=%.7f (best %.7f)" %
              (Ncoarse, rc, ru, bestRH))
        if ru > bestRH + 1e-13:
            bestH, bestRH = hu.copy(), ru
            print("    ACCEPT R=%.7f" % bestRH)

    # ---- Peak-window block polish: focus free variables near the flat top of f*f ----
    while time.process_time() < deadline - 3.0:
        Lf = _knots(bestH)
        mx = Lf.max()
        idx = np.flatnonzero(Lf >= 0.999 * mx)
        lo_k = max(0, idx.min() - 1)
        hi_k = min(bestH.size - 1, idx.max())
        # f*f knot k ~ h index k/2
        c_lo = lo_k // 2
        c_hi = hi_k // 2 + 1
        pad = max(64, (c_hi - c_lo) // 3)
        lo = max(0, c_lo - pad)
        hi = min(bestH.size, c_hi + pad)
        free = np.arange(lo, hi)
        if free.size == 0:
            break
        sub_dl = min(deadline - 1.0, time.process_time() + 5.0)
        hb = _lbfgs_block(bestH, free, 300, sub_dl)
        rb = R_of(hb)
        if rb > bestRH + 1e-13:
            bestH, bestRH = hb.copy(), rb
            print("  peak-block ACCEPT R=%.7f" % bestRH)
            continue
        # global sharp polish as fallback
        h = _lbfgs_log(bestH, 400, min(deadline - 1.0,
                                       time.process_time() + 5.0))
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
            print("  polish ACCEPT R=%.7f" % bestRH)
        else:
            # try soft-max to escape plateau
            for beta in (1e2, 1e3, 1e4):
                if time.process_time() > deadline - 2.0:
                    break
                hb2 = _lbfgs_log(bestH, 120, min(deadline - 1.0,
                                                 time.process_time() + 2.0),
                                 fg=lambda hh, b=beta: _fun_grad_beta(hh, b))
                rb2 = R_of(hb2)
                if rb2 > bestRH + 1e-13:
                    bestH, bestRH = hb2.copy(), rb2
                    print("  beta=%.0e ACCEPT R=%.7f" % (beta, bestRH))
                    break

    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

