    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = -1.0

    def _record(h, tag):
        nonlocal best, bestR, alt, altR
        h = _rescale(h)
        r = R_of(h)
        print("%s R=%.7f N=%d" % (tag, r, h.size))
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
        elif r > altR:
            alt, altR = h.copy(), r
        return r

    # Stage A: refine the start with beta ladder + peak-window polish.
    # Key change: focus optimization tightly on the peak region of f*f,
    # where the binding constraint ||f*f||_inf lives. This is where
    # the current best construction is most improvable.
    cur = best.copy()
    curR = bestR
    refine_deadline = t0 + budget_seconds * 0.45
    betas = [200.0, 1000.0, 4000.0, 20000.0, 100000.0]
    while time.process_time() < refine_deadline - 1.5:
        improved = False
        for beta in betas:
            if time.process_time() >= refine_deadline - 1.5:
                break
            hc = _lbfgs_block(cur, np.arange(cur.size), 60, refine_deadline,
                              beta=beta)
            hc = _rescale(hc)
            r = R_of(hc)
            if r > curR + 1e-13:
                cur, curR = hc, r
                improved = True
                _record(hc, "beta%.0f" % beta)
                # tight peak polish
                free = _peak_window(hc, 0.05)
                hc2 = _lbfgs_block(hc, free, 80, refine_deadline)
                hc2 = _rescale(hc2)
                r2 = R_of(hc2)
                if r2 > curR + 1e-13:
                    cur, curR = hc2, r2
                    _record(hc2, "peak")
        if not improved:
            break
    if curR > bestR + 1e-13:
        best, bestR = cur.copy(), curR

    # Stage B: upsample the best and refine; the peak region becomes
    # better resolved, often unlocking small gains.
    up_deadline = t0 + budget_seconds * 0.72
    cur = best.copy()
    curR = bestR
    for factor in (2, 2):
        if time.process_time() >= up_deadline - 1.0:
            break
        if cur.size * factor > 1000000:
            break
        hb = _rescale(_upsample(cur, factor))
        slice_dl = min(up_deadline,
                       time.process_time() + (up_deadline - time.process_time()) * 0.9)
        # beta-ladder refinement at finer resolution
        for beta in [1000.0, 10000.0, 100000.0]:
            if time.process_time() >= slice_dl - 0.5:
                break
            hb = _lbfgs_block(hb, np.arange(hb.size), 40, slice_dl, beta=beta)
            hb = _rescale(hb)
        if time.process_time() < slice_dl - 0.5:
            free = _peak_window(hb, 0.05)
            hb = _lbfgs_block(hb, free, 80, slice_dl)
        hb = _rescale(hb)
        r = _record(hb, "up%d" % factor)
        if r > curR + 1e-13:
            cur, curR = hb, r
            if curR > bestR + 1e-13:
                best, bestR = hb.copy(), curR

    # Stage C: final tight polish on the peak with pure ||inf criterion.
    final = best.copy()
    finalR = bestR
    while time.process_time() < deadline - 1.5:
        improved = False
        for beta in [100000.0, 1000000.0]:
            if time.process_time() >= deadline - 1.5:
                break
            hc = _lbfgs_block(final, np.arange(final.size), 40, deadline,
                              beta=beta)
            hc = _rescale(hc)
            if time.process_time() < deadline - 1.0:
                free = _peak_window(hc, 0.04)
                hc = _lbfgs_block(hc, free, 60, deadline)
            hc = _rescale(hc)
            r = R_of(hc)
            if r > finalR + 1e-13:
                final, finalR = hc, r
                improved = True
                _record(hc, "fin%.0f" % beta)
        if not improved:
            break

    _record(final, "final")

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    for frac in fracs:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, beta=0.0)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    return best, bestR


def _build_seed(N):
    i = np.arange(N, dtype=float)
    h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    start_best = None
    start_bestR = 0.0
    best = None
    bestR = 0.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
            best = start_best.copy()
            bestR = start_bestR

    if best is None:
        N = 8192
        best = _build_seed(N)
        bestR = R_of(best)
        start_best = best.copy()
        start_bestR = bestR

    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Aggressive full-space L-BFGS with growing beta (smoother max) to escape
    # the sharp single-knot max escape; then polish on the true objective.
    cycle = 0
    while time.process_time() < deadline - 0.5:
        cycle += 1
        improved = False
        # soft-max full pass to smooth over near-ties
        for beta in (30.0, 100.0, 300.0, 0.0):
            if time.process_time() >= deadline - 0.5:
                break
            cap = min(deadline - 0.3, time.process_time() + 4.0)
            hp = _lbfgs_block(best, np.arange(best.size), 150, cap, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
                improved = True
        if time.process_time() < deadline - 0.5:
            hp, rp = _polish(best, deadline)
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
                improved = True
        print("  cyc=%d R=%.9f imp=%s" % (cycle, bestR, improved))
        if not improved and time.process_time() > deadline - 2.0:
            break

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
