    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.9995):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _smooth_perturb(h, sigma, amp, seed):
    n = h.size
    rng = np.random.RandomState(seed)
    m = max(16, n // 64)
    noise = rng.randn(m)
    xp = np.linspace(0, 1, m)
    xi = np.linspace(0, 1, n)
    p = np.interp(xi, xp, noise)
    return np.clip(h * np.exp(amp * p), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size
    alt = None
    altR = 0.0

    def anneal_polish(h0, dl, bs, iters):
        h = h0
        for beta in bs:
            if time.process_time() >= dl - 0.5:
                break
            h = _lbfgs_all_pos(h, iters, dl, beta=beta)
            h = _window_polish_peak(h, dl, 0.35, 32, maxiter=iters, beta=beta)
        return h

    # NEW main idea: the true optimum has a very flat top plateau, and the
    # exact max objective stalls there. We (a) run a long high-beta ramp so
    # the smooth max surrogate can equalise a broad plateau, then (b) switch
    # back to exact max and do repeated peak-window polishes. Crucially we now
    # ALSO shorten the support: the optimal f is conjectured to be compactly
    # supported and roughly a "tent"; we try trimming tails (which don't
    # affect the peak much) to raise R, then re-polish.

    def trim_tails(h, keep_frac=0.985):
        # zero out tiny tail entries to reduce ||f||_1 without touching peak
        s = h.sum()
        c = np.cumsum(h) / s
        lo = int(np.searchsorted(c, 0.5 - keep_frac / 2))
        hi = int(np.searchsorted(c, 0.5 + keep_frac / 2))
        lo = max(0, lo); hi = min(h.size, hi + 1)
        h2 = h.copy()
        h2[:lo] = 0.0
        h2[hi:] = 0.0
        return h2

    betas = [2.0, 8.0, 32.0, 128.0, 512.0, 2048.0, 8192.0]

    # Pass 1: high-beta anneal from start
    if time.process_time() < deadline - 25.0:
        h = anneal_polish(best, deadline - 18.0, betas, 300)
        h = _lbfgs_all_pos(h, 800, deadline - 12.0)
        h = _window_polish_peak(h, deadline - 10.0, 0.5, 64)
        r = R_of(h)
        print("anneal R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("anneal wins R=%.7f" % bestR)
        elif r > altR:
            alt, altR = h, r

    # Pass 2: perturb + anneal
    perturb_specs = [
        (max(2.0, N / 300.0), 0.04, 21),
        (max(4.0, N / 150.0), 0.05, 22),
        (max(8.0, N / 80.0), 0.04, 23),
    ]
    for sigma, amp, seed in perturb_specs:
        if time.process_time() >= deadline - 12.0:
            break
        hp = _rescale(_smooth_perturb(best, sigma, amp, seed))
        hp = anneal_polish(hp, deadline - 8.0, betas[:5], 220)
        hp = _lbfgs_all_pos(hp, 500, deadline - 5.0)
        hp = _window_polish_peak(hp, deadline - 4.0, 0.45, 48)
        r = R_of(hp)
        print("perturb s=%.1f a=%.2f R=%.7f" % (sigma, amp, r))
        if r > altR:
            alt, altR = hp, r
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("perturb wins R=%.7f" % bestR)

    # Pass 3: multi-scale refine
    if time.process_time() < deadline - 8.0:
        for factor in (3, 2):
            if time.process_time() >= deadline - 6.0:
                break
            Nc = max(256, N // factor)
            hc = _rescale(_coarse(best, Nc))
            hc = anneal_polish(hc, deadline - 5.0, betas[:5], 220)
            hp = _rescale(_prolongate(hc, N))
            hp = _lbfgs_all_pos(hp, 500, deadline - 4.0)
            hp = _window_polish_peak(hp, deadline - 2.0, 0.5, 64)
            r = R_of(hp)
            print("prolong %d->%d R=%.7f" % (Nc, N, r))
            if r > altR:
                alt, altR = hp, r
            if r > bestR + 1e-15:
                best, bestR = hp, r

    # Pass 4: tail-trimming experiments
    for keep in (0.99, 0.98, 0.97, 0.96):
        if time.process_time() >= deadline - 6.0:
            break
        ht = _rescale(trim_tails(best, keep))
        ht = _lbfgs_all_pos(ht, 500, deadline - 3.0)
        ht = _window_polish_peak(ht, deadline - 2.0, 0.5, 64)
        r = R_of(ht)
        print("trim %.2f R=%.7f" % (keep, r))
        if r > altR:
            alt, altR = ht, r
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("trim wins R=%.7f" % bestR)

    # Final: alternate exact full/peak polish with high-beta flattening.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_all_pos(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs_all_pos(best, 400, deadline - 1.0, beta=16384.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.55, 64)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _R_coarse(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = np.concatenate(([0.0], np.convolve(c, c), [0.0]))
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _detect_staircase(h):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in (1, 2, 3, 4, 5, 8, 16, 32, 64):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-10:
            r_c = _R_coarse(c)
            r_h = R_of(h)
            if abs(r_c - r_h) < 1e-12:
                return c, p
    return None, 1


def _sweep_coords(c, coords, deadline, rng):
    m = c.size
    best_R = _R_coarse(c)
    n_moved = 0
    deltas = np.array([-0.75, -0.5, -0.3, -0.15, -0.07, 0.0,
                       0.07, 0.15, 0.3, 0.5, 0.75])
    order = rng.permutation(coords)
    for k in order:
        if time.process_time() > deadline:
            break
        ck = c[k]
        if ck <= 0:
            continue
        cands = ck * deltas
        cands = np.concatenate((cands, [0.0]))
        cands = np.clip(cands, 0.0, None)
        best_d = 0.0
        best_r = best_R
        for d in cands:
            if d == 0.0:
                continue
            c_old = c[k]
            c[k] = d
            r = _R_coarse(c)
            c[k] = c_old
            if r > best_r + 1e-16:
                best_r = r
                best_d = d
        if best_d != 0.0:
            allv = np.sort(np.unique(np.concatenate((cands, [ck]))))
            idx = np.searchsorted(allv, best_d)
            lo = allv[max(0, idx - 1)]
            hi = allv[min(allv.size - 1, idx + 1)]
            gr = (np.sqrt(5.0) - 1.0) / 2.0
            a, b = lo, hi
            c1 = b - gr * (b - a)
            c2 = a + gr * (b - a)
            c[k] = c1; f1 = _R_coarse(c)
            c[k] = c2; f2 = _R_coarse(c)
            for _ in range(30):
                if time.process_time() > deadline:
                    break
                if f1 < f2:
                    a = c1; c1 = c2; f1 = f2
                    c2 = a + gr * (b - a)
                    c[k] = c2; f2 = _R_coarse(c)
                else:
                    b = c2; c2 = c1; f2 = f1
                    c1 = b - gr * (b - a)
                    c[k] = c1; f1 = _R_coarse(c)
            c[k] = 0.5 * (a + b)
            r = _R_coarse(c)
            if r > best_R + 1e-16:
                best_R = r
                n_moved += 1
            else:
                c[k] = ck
    return c, best_R, n_moved


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # ---- Phase S: prune least-sensitive active cells, regrow at deficit knots ----
    s_end = t0 + budget_seconds * 0.86
    cyc = 0
    while time.process_time() < s_end - 3.0:
        cyc += 1
        h = best.copy()
        cycle_start = h.copy()
        cycle_R = bestR

        # (1) sensitivity and prune
        grad = _grad_logR(h)
        active = np.flatnonzero(h > 0)
        if active.size == 0:
            break
        sens = h[active] * np.abs(grad[active])
        K = max(1, int(0.005 * active.size))
        K = min(K, active.size)
        order = np.argsort(sens)
        prune_idx = active[order[:K]]
        h[prune_idx] = 0.0

        # (2) regrow at highest-deficit mid-level knots
        L = _knots(h)
        M = L.max()
        if M <= 0:
            break
        n = h.size
        # knot j corresponds to L[j]; interior knots 1..n-1 map to cells
        jj = np.arange(1, n)
        Lj = L[jj]
        sel = (Lj > 0.10 * M) & (Lj < 0.95 * M)
        jj = jj[sel]
        Lj = Lj[sel]
        if jj.size > 0:
            w = Lj * (M - Lj)
            top = np.argsort(-w)[:K]
            mean_pos = float(np.mean(h[h > 0])) if np.any(h > 0) else 1.0
            seed = 1e-3 * mean_pos
            for t in top:
                j = int(jj[t])
                a = j // 2
                b = j - a
                if 0 <= a < n:
                    if h[a] < seed:
                        h[a] = seed
                if 0 <= b < n:
                    if h[b] < seed:
                        h[b] = seed

        # (3) dilate and polish
        nz = np.flatnonzero(h > 0)
        dil = _dilate(nz, n, 8)
        h = _lbfgs_block(h, dil, 300,
                         min(s_end - 1.0, time.process_time() + 6.0), tie=True)
        win = _peak_window(h, pad_frac=0.06, extra=64)
        h = _lbfgs_block(h, win, 300,
                         min(s_end - 0.5, time.process_time() + 4.0), beta=1e7)

        r_new = R_of(h)
        accepted = r_new > cycle_R + 1e-15
        if accepted:
            best, bestR = h.copy(), r_new
        else:
            best = cycle_start
            bestR = cycle_R
        f01, f1, f5 = _nearmax_fracs(best)
        print("S cyc=%d R=%.9f K=%d acc=%d zf=%.4f near=%.3f/%.3f/%.3f"
              % (cyc, bestR, K, int(accepted), _zero_frac(best), f01, f1, f5))

    # ---- final full tie L-BFGS ----
    fd = t0 + budget_seconds * 0.94
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))

    # ---- peak ladder ----
    peak_end = t0 + budget_seconds * 0.985
    if time.process_time() < peak_end - 2.0:
        ht = _peak_ladder(best, peak_end - 0.5,
                          pads=(0.06, 0.03), iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _mass_resample(h, Nnew):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew) / Nnew
    x = np.linspace(0.0, 1.0, Nnew + 1)
    src_x = np.linspace(0.0, 1.0, N + 1)
    target_c = np.interp(x, src_x, c)
    out = np.diff(target_c)
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return np.ones(Nnew) / Nnew
    return out * (total / out.sum())


def _upsample_linear(h, Nnew):
    # linear interpolation of heights onto finer grid (keeps shape but adds resolution)
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N == Nnew:
        return h.copy()
    src_x = (np.arange(N) + 0.5) / N
    dst_x = (np.arange(Nnew) + 0.5) / Nnew
    out = np.interp(dst_x, src_x, h, left=h[0], right=h[-1])
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        start_best = _rescale(np.ones(8192))
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best_h = start_best.copy()
    best_R = start_bestR

    # --- NEW: refine at a higher resolution grid, upsampled from start ---
    # Reasoning: the optimum shape has fine features near the peak of f*f;
    # refining on a finer grid gives more freedom to raise R.
    N0 = start_best.size
    alt_h = None
    alt_R = 0.0
    for factor in (2, 3):
        if time.process_time() >= deadline - 3.0:
            break
        Nhi = min(1_000_000, N0 * factor)
        if Nhi <= N0:
            continue
        hin = _upsample_linear(best_h, Nhi)
        hin = _rescale(hin)
        cap = min(deadline - 2.0, time.process_time() + 6.0)
        hhi = _lbfgs_log(hin, 300, cap)
        rhi = R_of(hhi)
        print("  hi-res x%d (N=%d) R=%.7f" % (factor, Nhi, rhi))
        if rhi > alt_R:
            alt_h, alt_R = hhi, rhi
        if rhi > best_R + 1e-12:
            best_h, best_R = hhi, rhi

    # --- window polishes on current best ---
    for frac in (0.01, 0.02, 0.05, 0.10, 0.20, 0.35):
        if time.process_time() >= deadline - 2.0:
            break
        free = _peak_window(best_h, frac=frac)
        cap = min(deadline - 1.0, time.process_time() + 3.0)
        hb = _lbfgs_block(best_h, free, 150, cap)
        rb = R_of(hb)
        if rb > best_R + 1e-12:
            best_h, best_R = hb, rb
            print("  window frac=%.2f R=%.7f" % (frac, rb))

    # --- iterate narrow window + full polish ---
    for _ in range(8):
        if time.process_time() >= deadline - 1.5:
            break
        free = _peak_window(best_h, frac=0.02)
        cap = min(deadline - 1.0, time.process_time() + 2.0)
        hb = _lbfgs_block(best_h, free, 120, cap)
        rb = R_of(hb)
        if rb > best_R + 1e-12:
            best_h, best_R = hb, rb
        else:
            break

    if time.process_time() < deadline - 1.5:
        cap = min(deadline - 1.0, time.process_time() + 4.0)
        hp = _lbfgs_log(best_h, 250, cap)
        rp = R_of(hp)
        print("  final full polish R=%.7f" % rp)
        if rp > best_R:
            best_h, best_R = hp, rp

    # --- decide result ---
    if best_R > start_bestR + 1e-12:
        result = best_h
        print("final R=%.7f (beat start %.7f)" % (best_R, start_bestR))
    else:
        # provide the genuinely different hi-res construction as alternative
        if alt_h is not None and alt_R > start_bestR - 1e-6 and alt_h.size != start_best.size:
            result = {"best": start_best, "alternative": alt_h}
            print("final R=%.7f (start %.7f kept; alternative R=%.7f)" %
                  (start_bestR, start_bestR, alt_R))
        else:
            result = {"best": start_best, "alternative": None}
            print("final R=%.7f (start kept)" % start_bestR)

    Lf = _knots(best_h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    print("best R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (best_R, best_h.size, 100.0 * np.mean(best_h <= 0), mx, m, near))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_final(best, bestR, deadline):
    for pad in [0.10, 0.06, 0.04]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _maybe_alt(h2, r2):
        nonlocal alt_best, alt_bestR
        if r2 > alt_bestR:
            alt_best, alt_bestR = h2.copy(), r2

    # ---- Phase A: fine-grid refinement via interpolated upsample then fold ----
    # The key idea for a finer grid: upsample the current best by linear
    # interpolation to 2N, run a short beta-smoothing L-BFGS on the 2N grid,
    # then fold back to N. Repeating with different splittings explores a
    # finer discretisation than the start's resolution, which is where the
    # remaining gains lie.
    N0 = best.size
    upsample_end = t0 + budget_seconds * 0.45
    up_round = 0
    while time.process_time() < upsample_end - 1.5 and N0 >= 8:
        up_round += 1
        now = time.process_time()
        slice_dl = min(upsample_end, now + 3.0)
        if slice_dl <= now + 0.5:
            break
        try:
            # linear interpolate to 2N
            xo = np.arange(N0, dtype=float)
            xn = np.arange(2 * N0, dtype=float) * 0.5
            u = np.interp(xn, xo, best)
            u = _rescale(u)
            r0 = R_of(u)
            u = _lbfgs_all_pos(u, 200, slice_dl - 0.3, beta=1e6)
            if time.process_time() < slice_dl - 0.4:
                u = _lbfgs_all_pos(u, 200, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                win = _peak_window(u, pad_frac=0.08, extra=256)
                u = _lbfgs_block(u, win, 200, slice_dl - 0.3, beta=1e7)
            r_up = R_of(u)
            # fold back: average pairs (works for any N0)
            h2 = _rescale(0.5 * (u[0::2][:N0] + u[1::2][:N0]))
            if time.process_time() < slice_dl - 0.4:
                h2 = _lbfgs_all_pos(h2, 200, slice_dl - 0.3, beta=1e6)
            if time.process_time() < slice_dl - 0.4:
                h2 = _lbfgs_all_pos(h2, 200, slice_dl - 0.3, beta=1e7)
            r_fold = R_of(h2)
            print("up%d r0=%.9f r_up=%.9f r_fold=%.9f (best %.9f)" %
                  (up_round, r0, r_up, r_fold, bestR))
            if r_fold > bestR + 1e-13:
                best, bestR, origin = h2.copy(), r_fold, 'up%d' % up_round
                print("  up NEW BEST R=%.9f" % bestR)
            else:
                _maybe_alt(h2, r_fold)
        except Exception as e:
            print("up%d exception %s" % (up_round, e))

    # ---- Phase B: randomized 2N lift from the current best ----
    lift_end = min(t0 + budget_seconds * 0.72, deadline - 4.0)
    if time.process_time() < lift_end - 1.0 and best.size >= 2:
        n = best.size
        sigmas = [0.02, 0.05, 0.10, 0.03, 0.15]
        rnd = 0
        while time.process_time() < lift_end - 1.0:
            sigma = sigmas[rnd % len(sigmas)]
            rnd += 1
            now = time.process_time()
            slice_dl = min(now + 2.0, deadline - 3.0)
            if slice_dl <= now + 0.3:
                break
            try:
                d = np.clip(sigma * np.random.randn(n), -0.6, 0.6)
                u = np.empty(2 * n)
                u[0::2] = best * (1.0 + d)
                u[1::2] = best * (1.0 - d)
                u = _rescale(u)
                u = _lbfgs_all_pos(u, 120, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    win = _peak_window(u, pad_frac=0.10, extra=128)
                    u = _lbfgs_block(u, win, 150, slice_dl, beta=1e7)
                h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:n]
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e7)
                r_fold = R_of(h2)
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'rnd%d' % rnd
                    print("  rnd NEW BEST R=%.9f" % bestR)
                else:
                    _maybe_alt(h2, r_fold)
            except Exception as e:
                print("rnd %d exception %s" % (rnd, e))

    # ---- Phase C: peak polish ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish_final(best, bestR, deadline - 1.0)

    # ---- Phase D: block-beta polish on the peak region ----
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.05, extra=200)
        ht = _lbfgs_block(best, win, 500, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("  final block R=%.9f" % bestR)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

