def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _deficit_free(h, frac=0.15):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(h.size)
    gLf = (M - 2.0 * Lf) / M
    s = np.abs(_backprop(gLf, h))
    N = h.size
    k = max(1, int(frac * N))
    if k >= N:
        return np.arange(N)
    idx = np.argpartition(-s, k - 1)[:k]
    return np.sort(idx)


def _interlace_32(c, n_target, rng):
    m = c.size
    if m < 2:
        return np.repeat(c, max(1, n_target // max(1, m)))[:n_target]
    cm = np.cumsum(c)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    jitter = np.exp(0.02 * rng.standard_normal(n_target))
    t = np.clip(t * jitter, 1e-9, 1 - 1e-9)
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, m - 1)
    return c[idx].astype(float)


def _fold_back(h_fine, n_target):
    n = h_fine.size
    if n == n_target:
        return h_fine.copy()
    cm = np.cumsum(h_fine)
    if cm[-1] <= 0:
        return np.zeros(n_target)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, n - 1)
    return h_fine[idx].astype(float)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase A: half-resolution polish + lift (cheap, proven) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.12
        work_c = c.copy()
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- NEW: sub-pixel (shifted) half-resolution descent ----
    # The half-res quotient c even/odd is only one decimation. Try the odd
    # decimation and a "shifted" version obtained by splitting the peak.
    if best.size % 2 == 0 and best.size >= 8 and time.process_time() < deadline - 5.0:
        for dec in (1,):
            c2 = best[dec::2].copy()
            sub_dl = time.process_time() + budget_seconds * 0.08
            c2 = _polish_ladder(c2, sub_dl, betas=(1e6, 1e7, 0.0), iters=250)
            c2 = _peak_ladder(c2, sub_dl, pads=(0.20, 0.12, 0.08), iters=300)
            h_lift = _rescale(np.repeat(c2, 2))
            # pad to best.size if needed
            if h_lift.size < best.size:
                h_lift = np.concatenate([h_lift, np.zeros(best.size - h_lift.size)])
            elif h_lift.size > best.size:
                h_lift = h_lift[:best.size]
            h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7, 0.0), iters=250)
            offer(h_lift, 'odd-lift')

    # ---- Phase D: deficit-sensitivity rounds (proven small gain source) ----
    deficit_deadline = deadline - 10.0
    for rnd in range(4):
        if time.process_time() >= deficit_deadline - 2.0:
            break
        free = _deficit_free(best, frac=0.15)
        if free.size == 0:
            continue
        ht = _lbfgs_block(best, free, 400, deficit_deadline, beta=1e6)
        ht = _lbfgs_block(ht, free, 400, deficit_deadline, beta=0.0)
        ht = _peak_ladder(ht, deficit_deadline, pads=(0.08, 0.05), iters=250)
        r = R_of(ht)
        improved = offer(ht, 'deficit_%d' % rnd)
        print("deficit round=%d freed=%d R=%.9f (best %.9f) improved=%s"
              % (rnd, free.size, r, bestR, improved))
        if not improved and rnd >= 2:
            break

    # ---- Phase B: high-beta sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=300)
        offer(ht, 'sharp')

    # ---- Final peak polish ----
    ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=250)
    if R_of(ht2) > bestR + 1e-14:
        best, bestR = ht2.copy(), R_of(ht2)
        print("NEW BEST (finalpeak) R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
