    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _coarsen(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nc)
    edges = np.linspace(0.0, total, Nc + 1)
    vals = np.interp(edges, np.linspace(0.0, total, n + 1), c)
    hc = np.diff(vals)
    hc = np.clip(hc, 0.0, None)
    return hc


def _prolong(hc, N):
    Nc = hc.size
    if Nc == N:
        return hc.copy()
    c = np.concatenate(([0.0], np.cumsum(hc)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    edges = np.linspace(0.0, total, N + 1)
    vals = np.interp(edges, np.linspace(0.0, total, Nc + 1), c)
    hf = np.diff(vals)
    hf = np.clip(hf, 0.0, None)
    return hf


def _block_mean(h, B):
    """Block-mean over consecutive B cells; requires h.size % B == 0."""
    return h.reshape(-1, B).mean(axis=1)


def _block_repeat(c, B):
    return np.repeat(c, B)


def _opt_block(c0, B, maxiter, deadline):
    """Optimize coarse c with h=repeat(c,B) under true R."""
    if time.process_time() >= deadline - 0.3:
        return c0
    c = np.clip(c0, 0, None)
    if c.sum() <= 0:
        return c0
    n = c.size

    def f(x):
        cc = np.clip(x, 0.0, None)
        hh = np.repeat(cc, B)
        val, g = _fun_grad_tie(hh)
        gc = g.reshape(n, B).sum(axis=1)
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.clip(res.x, 0.0, None)


def _opt_asym(c0, B, maxiter, deadline):
    """Split each coarse cell's B copies into two halves with ratio alpha_j.
    Parameterize logit(alpha). Returns fine h of size c0.size*B."""
    if time.process_time() >= deadline - 0.3:
        return _block_repeat(c0, B)
    n = c0.size
    half = B // 2
    # theta = logit(alpha) in R^n; alpha = sigmoid(theta)
    theta0 = np.zeros(n)

    def build(theta):
        alpha = 1.0 / (1.0 + np.exp(-np.clip(theta, -30, 30)))
        # half1 heights: c*2*alpha, half2: c*2*(1-alpha) so mean preserved
        h = np.empty(n * B)
        h1 = (c0 * 2.0 * alpha)
        h2 = (c0 * 2.0 * (1.0 - alpha))
        hh = h.reshape(n, B)
        hh[:, :half] = h1[:, None]
        hh[:, half:] = h2[:, None]
        return h

    def f(theta):
        h = build(theta)
        val, g = _fun_grad_tie(h)
        gh = g.reshape(n, B)
        alpha = 1.0 / (1.0 + np.exp(-np.clip(theta, -30, 30)))
        # d h1/d alpha = 2c ; d h2/d alpha = -2c
        g1 = gh[:, :half].sum(axis=1)
        g2 = gh[:, half:].sum(axis=1)
        dval_dalpha = g1 * (2.0 * c0) + g2 * (-2.0 * c0)
        dalpha_dtheta = alpha * (1.0 - alpha)
        return val, dval_dalpha * dalpha_dtheta

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, theta0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return _block_repeat(c0, B)
    if res is None:
        return _block_repeat(c0, B)
    return build(res.x)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Phase 1: exact block-mean coarsen to Nc = N/B ----
    B = 32
    if N % B != 0:
        # fall back: pick a divisor near 32
        for cand in (32, 16, 8, 4, 2, 1):
            if N % cand == 0:
                B = cand
                break
    Nc = N // B
    c0 = _block_mean(best, B)
    c0 = _rescale(_block_repeat(c0, B))[:0] if False else c0
    # rescale coarse so repeat has sensible scale
    h_init = _block_repeat(c0, B)
    h_init = _rescale(h_init)
    c0 = _block_mean(h_init, B)
    R_init = R_of(h_init)
    print("block-mean Nc=%d (B=%d) R=%.9f" % (Nc, B, R_init))

    best_c = c0.copy()
    best_h = h_init.copy()
    best_hR = R_init

    # ---- Phase 2: coarse L-BFGS on block-constant lift ----
    env_end = t0 + budget_seconds * 0.55
    c_opt = _opt_block(best_c, B, 400, env_end)
    h_opt = _rescale(_block_repeat(c_opt, B))
    R_opt = R_of(h_opt)
    print("coarse L-BFGS R=%.9f (init %.9f)" % (R_opt, R_init))
    if R_opt > best_hR:
        best_c = c_opt
        best_h = h_opt
        best_hR = R_opt

    # ---- Phase 3: asymmetric split ----
    if time.process_time() < env_end - 2.0 and B >= 2:
        h_asym = _opt_asym(best_c, B, 200, env_end)
        h_asym = _rescale(h_asym)
        R_asym = R_of(h_asym)
        print("asymmetric split R=%.9f" % R_asym)
        if R_asym > best_hR:
            best_h = h_asym
            best_hR = R_asym
            best_c = _block_mean(h_asym, B)

    # ---- Phase 4: peak/tie polish ----
    cand = best_h.copy()
    candR = best_hR
    peak_end = t0 + budget_seconds * 0.82
    for beta in (1e5, 1e7):
        if time.process_time() >= peak_end - 2.0:
            break
        for pad in (0.10, 0.06, 0.03):
            if time.process_time() >= peak_end - 1.5:
                break
            win = _peak_window(cand, pad_frac=pad, extra=128)
            ht = _lbfgs_block(cand, win, 300, peak_end - 0.5, beta=beta)
            r = R_of(ht)
            if r > candR + 1e-15:
                cand, candR = ht, r
    print("after peak ladder R=%.9f" % candR)

    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(cand, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("tie ACCEPT R=%.9f ties=%d" % (candR, _tie_count(cand)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(cand, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("argmax ACCEPT R=%.9f" % candR)

    f01, f1, f5 = _nearmax_fracs(cand)
    print("candidate R=%.9f near 0.1%%/1%%/5%%=%.4f/%.4f/%.4f"
          % (candR, f01, f1, f5))

    if candR > bestR + 1e-15:
        best, bestR = cand, candR
        print("BLOCK WINS R=%.9f (start %.9f)" % (bestR, startR))
        result = {"best": best}
    else:
        print("no gain (cand %.9f vs start %.9f); returning alternative"
              % (candR, startR))
        result = {"best": best, "alternative": cand}

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


