def _block_mean(h, B):
    """Block-mean over consecutive B cells; requires h.size % B == 0."""
    return h.reshape(-1, B).mean(axis=1)


def _block_repeat(c, B):
    return np.repeat(c, B)


def _opt_block(c0, B, maxiter, deadline):
    """Optimize coarse c with h=repeat(c,B) under true R."""
    if time.process_time() >= deadline - 0.3:
        return c0
    c = np.clip(c0, 0, None)
    if c.sum() <= 0:
        return c0
    n = c.size

    def f(x):
        cc = np.clip(x, 0.0, None)
        hh = np.repeat(cc, B)
        val, g = _fun_grad_tie(hh)
        gc = g.reshape(n, B).sum(axis=1)
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.clip(res.x, 0.0, None)


def _opt_asym(c0, B, maxiter, deadline):
    """Split each coarse cell's B copies into two halves with ratio alpha_j.
    Parameterize logit(alpha). Returns fine h of size c0.size*B."""
    if time.process_time() >= deadline - 0.3:
        return _block_repeat(c0, B)
    n = c0.size
    half = B // 2
    # theta = logit(alpha) in R^n; alpha = sigmoid(theta)
    theta0 = np.zeros(n)

    def build(theta):
        alpha = 1.0 / (1.0 + np.exp(-np.clip(theta, -30, 30)))
        # half1 heights: c*2*alpha, half2: c*2*(1-alpha) so mean preserved
        h = np.empty(n * B)
        h1 = (c0 * 2.0 * alpha)
        h2 = (c0 * 2.0 * (1.0 - alpha))
        hh = h.reshape(n, B)
        hh[:, :half] = h1[:, None]
        hh[:, half:] = h2[:, None]
        return h

    def f(theta):
        h = build(theta)
        val, g = _fun_grad_tie(h)
        gh = g.reshape(n, B)
        alpha = 1.0 / (1.0 + np.exp(-np.clip(theta, -30, 30)))
        # d h1/d alpha = 2c ; d h2/d alpha = -2c
        g1 = gh[:, :half].sum(axis=1)
        g2 = gh[:, half:].sum(axis=1)
        dval_dalpha = g1 * (2.0 * c0) + g2 * (-2.0 * c0)
        dalpha_dtheta = alpha * (1.0 - alpha)
        return val, dval_dalpha * dalpha_dtheta

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, theta0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return _block_repeat(c0, B)
    if res is None:
        return _block_repeat(c0, B)
    return build(res.x)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Phase 1: exact block-mean coarsen to Nc = N/B ----
    B = 32
    if N % B != 0:
        # fall back: pick a divisor near 32
        for cand in (32, 16, 8, 4, 2, 1):
            if N % cand == 0:
                B = cand
                break
    Nc = N // B
    c0 = _block_mean(best, B)
    c0 = _rescale(_block_repeat(c0, B))[:0] if False else c0
    # rescale coarse so repeat has sensible scale
    h_init = _block_repeat(c0, B)
    h_init = _rescale(h_init)
    c0 = _block_mean(h_init, B)
    R_init = R_of(h_init)
    print("block-mean Nc=%d (B=%d) R=%.9f" % (Nc, B, R_init))

    best_c = c0.copy()
    best_h = h_init.copy()
    best_hR = R_init

    # ---- Phase 2: coarse L-BFGS on block-constant lift ----
    env_end = t0 + budget_seconds * 0.55
    c_opt = _opt_block(best_c, B, 400, env_end)
    h_opt = _rescale(_block_repeat(c_opt, B))
    R_opt = R_of(h_opt)
    print("coarse L-BFGS R=%.9f (init %.9f)" % (R_opt, R_init))
    if R_opt > best_hR:
        best_c = c_opt
        best_h = h_opt
        best_hR = R_opt

    # ---- Phase 3: asymmetric split ----
    if time.process_time() < env_end - 2.0 and B >= 2:
        h_asym = _opt_asym(best_c, B, 200, env_end)
        h_asym = _rescale(h_asym)
        R_asym = R_of(h_asym)
        print("asymmetric split R=%.9f" % R_asym)
        if R_asym > best_hR:
            best_h = h_asym
            best_hR = R_asym
            best_c = _block_mean(h_asym, B)

    # ---- Phase 4: peak/tie polish ----
    cand = best_h.copy()
    candR = best_hR
    peak_end = t0 + budget_seconds * 0.82
    for beta in (1e5, 1e7):
        if time.process_time() >= peak_end - 2.0:
            break
        for pad in (0.10, 0.06, 0.03):
            if time.process_time() >= peak_end - 1.5:
                break
            win = _peak_window(cand, pad_frac=pad, extra=128)
            ht = _lbfgs_block(cand, win, 300, peak_end - 0.5, beta=beta)
            r = R_of(ht)
            if r > candR + 1e-15:
                cand, candR = ht, r
    print("after peak ladder R=%.9f" % candR)

    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(cand, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("tie ACCEPT R=%.9f ties=%d" % (candR, _tie_count(cand)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(cand, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("argmax ACCEPT R=%.9f" % candR)

    f01, f1, f5 = _nearmax_fracs(cand)
    print("candidate R=%.9f near 0.1%%/1%%/5%%=%.4f/%.4f/%.4f"
          % (candR, f01, f1, f5))

    if candR > bestR + 1e-15:
        best, bestR = cand, candR
        print("BLOCK WINS R=%.9f (start %.9f)" % (bestR, startR))
        result = {"best": best}
    else:
        print("no gain (cand %.9f vs start %.9f); returning alternative"
              % (candR, startR))
        result = {"best": best, "alternative": cand}

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    return _rescale(h)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _R_coarse(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = np.concatenate(([0.0], np.convolve(c, c), [0.0]))
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _detect_staircase(h):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in (1, 2, 3, 4, 5, 8, 16, 32, 64):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-10:
            r_c = _R_coarse(c)
            r_h = R_of(h)
            if abs(r_c - r_h) < 1e-12:
                return c, p
    return None, 1


def _sweep_coords(c, coords, deadline, rng):
    m = c.size
    best_R = _R_coarse(c)
    n_moved = 0
    deltas = np.array([-0.75, -0.5, -0.3, -0.15, -0.07, 0.0,
                       0.07, 0.15, 0.3, 0.5, 0.75])
    order = rng.permutation(coords)
    for k in order:
        if time.process_time() > deadline:
            break
        ck = c[k]
        if ck <= 0:
            continue
        cands = ck * deltas
        cands = np.concatenate((cands, [0.0]))
        cands = np.clip(cands, 0.0, None)
        best_d = 0.0
        best_r = best_R
        for d in cands:
            if d == 0.0:
                continue
            c_old = c[k]
            c[k] = d
            r = _R_coarse(c)
            c[k] = c_old
            if r > best_r + 1e-16:
                best_r = r
                best_d = d
        if best_d != 0.0:
            allv = np.sort(np.unique(np.concatenate((cands, [ck]))))
            idx = np.searchsorted(allv, best_d)
            lo = allv[max(0, idx - 1)]
            hi = allv[min(allv.size - 1, idx + 1)]
            gr = (np.sqrt(5.0) - 1.0) / 2.0
            a, b = lo, hi
            c1 = b - gr * (b - a)
            c2 = a + gr * (b - a)
            c[k] = c1; f1 = _R_coarse(c)
            c[k] = c2; f2 = _R_coarse(c)
            for _ in range(30):
                if time.process_time() > deadline:
                    break
                if f1 < f2:
                    a = c1; c1 = c2; f1 = f2
                    c2 = a + gr * (b - a)
                    c[k] = c2; f2 = _R_coarse(c)
                else:
                    b = c2; c2 = c1; f2 = f1
                    c1 = b - gr * (b - a)
                    c[k] = c1; f1 = _R_coarse(c)
            c[k] = 0.5 * (a + b)
            r = _R_coarse(c)
            if r > best_R + 1e-16:
                best_R = r
                n_moved += 1
            else:
                c[k] = ck
    return c, best_R, n_moved


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


# ---------- 16x-repetition parametrization helpers ----------

def _h_of_z(z, rep):
    return np.repeat(z, rep)


def _fun_grad_z(z, rep):
    h = _h_of_z(z, rep)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(z.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(z.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    gh = _backprop(gLf, h) + 2.0 / s
    gz = gh.reshape(z.size, rep).sum(axis=1)
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, gz


def _lbfgs_z(z0, rep, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return z0
    z = np.clip(z0, 0, None)
    if z.sum() <= 0:
        return z0

    def f(x):
        zz = np.clip(x, 0.0, None)
        val, g = _fun_grad_z(zz, rep)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, z, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * z.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return z0
    if res is None:
        return z0
    return np.clip(res.x, 0.0, None)


def _sweep_z(z, rep, deadline, rng, n_sample=200):
    """Exact coordinate sweeps on z, evaluating true R_of(repeat(z,rep))."""
    best_R = R_of(_h_of_z(z, rep))
    n_moved = 0
    m = z.size
    deltas = np.array([-0.5, -0.25, -0.1, 0.0, 0.1, 0.25, 0.5])
    order = rng.permutation(m)[:n_sample]
    for k in order:
        if time.process_time() > deadline:
            break
        zk = z[k]
        if zk <= 0:
            continue
        cands = np.clip(zk * (1.0 + deltas), 0.0, None)
        cands = np.concatenate((cands, [0.0]))
        best_d = zk
        best_r = best_R
        for d in cands:
            z[k] = d
            r = R_of(_h_of_z(z, rep))
            if r > best_r + 1e-16:
                best_r = r
                best_d = d
        if best_d != zk:
            allv = np.sort(np.unique(np.concatenate((cands, [zk]))))
            idx = np.searchsorted(allv, best_d)
            lo = allv[max(0, idx - 1)]
            hi = allv[min(allv.size - 1, idx + 1)]
            gr = (np.sqrt(5.0) - 1.0) / 2.0
            a, b = lo, hi
            c1 = b - gr * (b - a)
            c2 = a + gr * (b - a)
            z[k] = c1; f1 = R_of(_h_of_z(z, rep))
            z[k] = c2; f2 = R_of(_h_of_z(z, rep))
            for _ in range(25):
                if time.process_time() > deadline:
                    break
                if f1 < f2:
                    a = c1; c1 = c2; f1 = f2
                    c2 = a + gr * (b - a)
                    z[k] = c2; f2 = R_of(_h_of_z(z, rep))
                else:
                    b = c2; c2 = c1; f2 = f1
                    c1 = b - gr * (b - a)
                    z[k] = c1; f1 = R_of(_h_of_z(z, rep))
            z[k] = 0.5 * (a + b)
            r = R_of(_h_of_z(z, rep))
            if r > best_R + 1e-16:
                best_R = r
                n_moved += 1
            else:
                z[k] = zk
        else:
            z[k] = zk
    return z, best_R, n_moved


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # ---- Experiment: 16x-repetition parametrization ----
    # Detect the exact staircase of the start, then reparametrize as
    # h = repeat(z, rep) with rep = p/2 (so p1861's p=32 -> rep=16).
    c, p = _detect_staircase(best)
    if c is not None and p >= 2 and p % 2 == 0:
        rep = p // 2
        m = c.size
        z0 = np.empty(m * 2, dtype=float)
        z0[0::2] = c
        z0[1::2] = c
        # sanity: repeat(z0, rep) should equal best (up to scaling)
        h_chk = _h_of_z(z0, rep)
        if h_chk.size == best.size:
            r_chk = R_of(h_chk)
            print("staircase p=%d m=%d -> z len=%d rep=%d, R(z0)=%.9f vs base %.9f"
                  % (p, m, z0.size, rep, r_chk, bestR))
            z = z0.copy()
            zR = r_chk
            if zR > bestR + 1e-15:
                best, bestR = _rescale(h_chk), zR

            # Phase Z1: L-BFGS-B on z
            z1_end = t0 + budget_seconds * 0.35
            if time.process_time() < z1_end - 2.0:
                z_new = _lbfgs_z(z, rep, 400, z1_end - 1.0)
                h_new = _h_of_z(z_new, rep)
                r_new = R_of(h_new)
                if r_new > zR + 1e-15:
                    z = z_new
                    zR = r_new
                    if r_new > bestR + 1e-15:
                        best, bestR = _rescale(h_new), r_new
                # measure divergence of duplicated pairs
                d = np.abs(z[0::2] - z[1::2])
                scale = max(np.abs(z).max(), 1e-300)
                print("  z-lbfgs R=%.9f (best %.9f) pair-div max=%.3e rel=%.3e"
                      % (zR, bestR, d.max(), d.max() / scale))

            # Phase Z2: exact coordinate sweeps on z
            z2_end = t0 + budget_seconds * 0.60
            cyc = 0
            while time.process_time() < z2_end - 3.0 and cyc < 4:
                cyc += 1
                z, zR, n_moved = _sweep_z(
                    z, rep,
                    min(z2_end - 1.0, time.process_time() + 8.0),
                    rng, n_sample=200)
                h_new = _h_of_z(z, rep)
                r_new = R_of(h_new)
                if r_new > bestR + 1e-15:
                    best, bestR = _rescale(h_new), r_new
                d = np.abs(z[0::2] - z[1::2])
                scale = max(np.abs(z).max(), 1e-300)
                f01, f1, f5 = _nearmax_fracs(best)
                print("  z-sweep cyc=%d R=%.9f moved=%d pair-div rel=%.3e "
                      "near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
                      % (cyc, bestR, n_moved, d.max() / scale, f01, f1, f5))
                if n_moved == 0 and cyc > 1:
                    break

            # Phase Z3: peak-window polish on the true h
            z3_end = t0 + budget_seconds * 0.86
            if time.process_time() < z3_end - 3.0:
                ht = _peak_ladder(best, z3_end - 1.0,
                                  pads=(0.10, 0.06, 0.04), iters=300, tie=True)
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r
                    print("  z peak ladder ACCEPT R=%.9f" % bestR)
        else:
            print("staircase p=%d but size mismatch; skipping z-param" % p)
    else:
        print("no even staircase detected (p=%s); skipping z-param" % (p,))

    # ---- Phase V: value-band polish (base) ----
    band_end = t0 + budget_seconds * 0.90
    band_edges = [(0.0, 0.05), (0.05, 0.20), (0.20, 0.50),
                  (0.50, 0.80), (0.80, 0.95), (0.95, 1.001)]
    cyc = 0
    while time.process_time() < band_end - 2.0:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        order = rng.permutation(len(band_edges))
        gains = []
        for bi in order:
            if time.process_time() >= band_end - 1.5:
                break
            lo, hi = band_edges[bi]
            lo *= M; hi *= M
            sel = np.flatnonzero((best > 0) & (v >= lo) & (v < hi))
            if sel.size == 0:
                gains.append(0.0)
                continue
            active = _dilate(sel, n, 16)
            if active.size < 20 or active.size > 0.8 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 300,
                              min(band_end - 1.0,
                                  time.process_time() + 6.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
            if time.process_time() < band_end - 1.0:
                win = _peak_window(best, pad_frac=0.06, extra=64)
                ht2 = _lbfgs_block(best, win, 200,
                                   min(band_end - 0.5,
                                       time.process_time() + 4.0), beta=1e7)
                r2 = R_of(ht2)
                if r2 > bestR + 1e-15:
                    best, bestR = ht2.copy(), r2
        f01, f1, f5 = _nearmax_fracs(best)
        print("band cyc=%d R=%.9f gains=%s near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (cyc, bestR,
                 " ".join("%.1e" % g for g in gains), f01, f1, f5))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase B: peak ladder polish ----
    peak_end = t0 + budget_seconds * 0.94
    if time.process_time() < peak_end - 3.0:
        ht = _peak_ladder(best, peak_end - 1.0,
                          pads=(0.06, 0.03), iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.9f" % bestR)

    # ---- Phase C: final exact tie polish ----
    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------- variable-cell staircase machinery ----------

def _rasterize(a, p_edges, Nf):
    centers = np.arange(Nf) + 0.5
    blk = np.searchsorted(p_edges, centers, side='right') - 1
    blk = np.clip(blk, 0, a.size - 1)
    return a[blk]


def _staircase_obj_grad(v, u, Nf, beta=0.0, tie=True):
    K = v.size
    a = np.exp(np.clip(v, -20.0, 20.0))
    uu = np.clip(u, -30.0, 30.0)
    uu = uu - uu.max()
    e = np.exp(uu)
    sw = e / e.sum()
    p_edges = np.concatenate(([0.0], np.cumsum(Nf * sw)))
    p_edges[-1] = Nf
    h = _rasterize(a, p_edges, Nf)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(K), np.zeros(K)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(K), np.zeros(K)
    gLf = -dq / num
    if beta > 0:
        ee = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
        Z = ee.sum()
        w = ee / Z
        sm = mx + np.log(Z) / beta
        gLf = gLf + w / sm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    else:
        if tie:
            idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
            gLf[idx] += (1.0 / idx.size) / mx
        else:
            m = int(np.argmax(Lf))
            gLf[m] += 1.0 / mx
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    g = _backprop(gLf, h) + 2.0 / s

    b = np.searchsorted(p_edges, np.arange(Nf) + 0.5, side='right') - 1
    gsum = np.bincount(b, weights=g, minlength=K)
    dv = a * gsum

    D = np.zeros(K)
    if K > 1:
        pk = p_edges[1:K]
        idx = np.clip(pk.astype(int), 0, Nf - 1)
        diff = a[:-1] - a[1:]
        D[1:K] = diff * g[idx]
    tot = np.sum(D * sw)
    du = Nf * sw * (D - tot)
    return val, dv, du


def _staircase_lbfgs(v0, u0, Nf, maxiter, deadline, mode='both',
                     beta=0.0, tie=True, u_bound=8.0):
    if time.process_time() >= deadline - 0.3:
        return v0, u0
    K = v0.size
    if mode == 'v':
        x0 = v0.copy()
        def f(x):
            val, dv, du = _staircase_obj_grad(x, u0, Nf, beta=beta, tie=tie)
            return val, dv
        bounds = [(None, None)] * K
    elif mode == 'u':
        x0 = u0.copy()
        def f(x):
            val, dv, du = _staircase_obj_grad(v0, x, Nf, beta=beta, tie=tie)
            return val, du
        bounds = [(-u_bound, u_bound)] * K
    else:
        x0 = np.concatenate([v0, u0])
        def f(x):
            val, dv, du = _staircase_obj_grad(x[:K], x[K:], Nf,
                                              beta=beta, tie=tie)
            return val, np.concatenate([dv, du])
        bounds = [(None, None)] * K + [(-u_bound, u_bound)] * K

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return v0, u0
    if res is None:
        return v0, u0
    x = res.x
    if mode == 'v':
        return x, u0
    elif mode == 'u':
        return v0, x
    else:
        return x[:K], x[K:]


def _raster_from(v, u, Nf):
    a = np.exp(np.clip(v, -20, 20))
    uu = np.clip(u, -30, 30); uu = uu - uu.max()
    e = np.exp(uu); sw = e / e.sum()
    p_edges = np.concatenate(([0.0], np.cumsum(Nf * sw))); p_edges[-1] = Nf
    return _rescale(_rasterize(a, p_edges, Nf))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, N, _zero_frac(best), _nearmax_frac(best)))

    # NEW: try a coarser staircase (fewer cells, variable widths) at a
    # reduced Nf. Fewer degrees of freedom = better conditioned, and the
    # optimiser can genuinely move cell widths. Then rasterise back to N.
    stair_best = None
    stair_bestR = -1.0
    stair_Nf = 0
    try:
        Nf = max(2000, min(N, 24000))
        K = max(200, min(Nf // 2, 2500))
        # downsample start to K cells
        idx = (np.arange(K) * (N // K)).astype(int)
        a0 = np.array([best[i:max(i + N // K, i + 1)].mean()
                       for i in idx])
        a0 = _rescale(np.clip(a0, 1e-12, None))
        v0 = np.log(a0)
        u0 = np.zeros(K)
        print("staircase: K=%d Nf=%d R0=%.9f" % (K, Nf, R_of(_raster_from(v0, u0, Nf))))

        sc_end = t0 + budget_seconds * 0.55
        v, u = v0, u0
        for r in range(4):
            if time.process_time() >= sc_end - 1.0:
                break
            v, u = _staircase_lbfgs(v, u, Nf, 200, sc_end, mode='v', tie=True)
            v, u = _staircase_lbfgs(v, u, Nf, 150, sc_end, mode='u', tie=True)
            if time.process_time() < sc_end - 1.0:
                v, u = _staircase_lbfgs(v, u, Nf, 150, sc_end, mode='both',
                                        beta=1e5, tie=True)
            if time.process_time() < sc_end - 1.0:
                v, u = _staircase_lbfgs(v, u, Nf, 150, sc_end, mode='both',
                                        beta=1e7, tie=True)
            h_sc = _raster_from(v, u, Nf)
            print("SC round %d: R=%.9f" % (r, R_of(h_sc)))

        h_sc = _raster_from(v, u, Nf)
        # upsample back to N (nearest / block-mean)
        if Nf != N:
            rep = int(np.ceil(N / Nf))
            h_up = np.repeat(h_sc, rep)[:N]
        else:
            h_up = h_sc
        h_up = _rescale(h_up)
        r_up = R_of(h_up)
        print("staircase upsample R=%.9f (Nf=%d)" % (r_up, Nf))
        if r_up > stair_bestR:
            stair_best, stair_bestR = h_up.copy(), r_up
            stair_Nf = Nf

        # polish at full N
        pol_end = t0 + budget_seconds * 0.78
        if time.process_time() < pol_end - 2.0:
            h_t = _lbfgs_all_pos(h_up, 400, pol_end - 1.0, tie=True)
            if R_of(h_t) > stair_bestR:
                stair_best, stair_bestR = h_t.copy(), R_of(h_t)
                print("staircase polished R=%.9f" % stair_bestR)
            if time.process_time() < pol_end - 1.5:
                h_t = _peak_ladder(h_t, pol_end - 0.5,
                                   pads=(0.10, 0.06, 0.04),
                                   iters=200, tie=True)
                if R_of(h_t) > stair_bestR:
                    stair_best, stair_bestR = h_t.copy(), R_of(h_t)
                    print("staircase peak R=%.9f" % stair_bestR)
    except Exception as ex:
        print("staircase failed: %r" % (ex,))

    if stair_best is not None and stair_bestR > bestR + 1e-15:
        best, bestR = stair_best.copy(), stair_bestR
        print("staircase IMPROVED R=%.9f" % bestR)

    # Full-N polish of best
    phaseC_end = t0 + min(budget_seconds * 0.90, budget_seconds - 4.0)
    it = 0
    while time.process_time() < phaseC_end - 3.0:
        it += 1
        slice_end = min(phaseC_end, time.process_time() + 7.0)
        h_t = _lbfgs_all_pos(best, 500, slice_end - 3.0, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("C tie %d ACCEPT R=%.9f" % (it, bestR))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=200, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("C peak %d ACCEPT R=%.9f" % (it, bestR))

    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 500, fd - 2.0, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, startR, best.size, _zero_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        if stair_best is not None and stair_bestR > startR + 1e-15:
            result["alternative"] = stair_best
        else:
            result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _polish(h, R_h, deadline, tag):
    for pad in [0.20, 0.12, 0.08, 0.05, 0.03]:
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(h, pad_frac=pad, extra=96)
        ht = _lbfgs_block(h, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > R_h + 1e-14:
            h, R_h = ht, r
        if time.process_time() < deadline - 0.7:
            ht2 = _lbfgs_all_pos(h, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > R_h + 1e-14:
                h, R_h = ht2, r2
    return h, R_h


def _upsample(h, factor):
    """Insert factor-1 interpolated points between each pair (linear)."""
    n = h.size
    out = np.empty(n * factor)
    for j in range(factor):
        a = j / factor
        out[j::factor] = (1 - a) * h + a * np.concatenate((h[1:], [h[-1]]))
    return _rescale(out)


def _refine_at_resolution(h, bestR, deadline, N_target):
    """Increase resolution via interpolation then re-optimise."""
    cur = h
    curR = bestR
    while cur.size * 2 <= N_target and time.process_time() < deadline - 3.0:
        up = _upsample(cur, 2)
        r_up = R_of(up)
        # quick full optimise with beta schedule
        ht = up
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _lbfgs_all_pos(ht, 250, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > curR + 1e-13:
            cur, curR = ht, r
        else:
            break
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase A: resolution refinement (NEW primary idea) ----
    # Upsample start to higher resolution and re-optimise. This is the main
    # new lever: the previous program never increased N.
    N_target = min(400000, max(best.size * 2, 200000))
    if time.process_time() < deadline - 3.0:
        h_ref, r_ref = _refine_at_resolution(best, bestR, deadline, N_target)
        if r_ref > bestR + 1e-13:
            best, bestR, origin = h_ref, r_ref, 'upsample'
            print("upsample NEW BEST R=%.9f (N=%d)" % (bestR, best.size))
        elif r_ref > alt_bestR:
            alt_best, alt_bestR = h_ref, r_ref

    # ---- Phase B: alternate resolution-level peak polish and upsampling ----
    while time.process_time() < deadline - 6.0:
        now = time.process_time()
        slice_dl = min(now + 6.0, deadline - 4.0)
        if slice_dl <= now + 1.0:
            break
        # polish current best
        h_p, r_p = _polish(best, bestR, slice_dl, 'pol')
        if r_p > bestR + 1e-13:
            best, bestR, origin = h_p, r_p, 'polish'
            print("polish NEW BEST R=%.9f" % bestR)
        # try to push resolution up once more if room
        if best.size * 2 <= N_target and time.process_time() < slice_dl - 2.0:
            h_ref, r_ref = _refine_at_resolution(best, bestR, slice_dl, N_target)
            if r_ref > bestR + 1e-13:
                best, bestR, origin = h_ref, r_ref, 'upsample2'
                print("upsample2 NEW BEST R=%.9f (N=%d)" % (bestR, best.size))
            elif r_ref > alt_bestR:
                alt_best, alt_bestR = h_ref, r_ref
        else:
            # no more room to upsample -> do 2N perturbation search
            n = best.size
            rng = np.random.RandomState(int(time.process_time() * 1000) % 100000)
            sigma = 0.02
            d = np.clip(sigma * rng.randn(n), -0.6, 0.6)
            u = np.empty(2 * n)
            u[0::2] = best * (1.0 + d)
            u[1::2] = best * (1.0 - d)
            u = _rescale(u)
            u = _lbfgs_all_pos(u, 120, slice_dl, beta=1e7)
            h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:n]
            h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e7)
            r_fold = R_of(h2)
            if r_fold > bestR + 1e-13:
                best, bestR, origin = h2, r_fold, 'rnd2N'
                print("rnd2N NEW BEST R=%.9f" % bestR)
            elif r_fold > alt_bestR:
                alt_best, alt_bestR = h2, r_fold

    # ---- Phase C: final full polish ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish(best, bestR, deadline - 0.2, 'final')
        print("final polish R=%.9f" % bestR)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    num = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    den = s * s * np.max(L)
    if den <= 0:
        return -1.0
    return num / den


# ---- p1861-style exact machinery with analytic gradients ----

def _conv(a, b):
    n = len(a) + len(b) - 1
    if n > 1500:
        return fftconvolve(a, b)
    return np.convolve(a, b)


def _knots(h):
    L = _conv(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    num = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    den = s * s * np.max(L)
    if den <= 0:
        return -1.0
    return num / den


def _num_and_dq(h):
    """Return (num, dnum/dh, L, s). num = ||f*f||_2^2."""
    s = h.sum()
    L = _knots(h)
    # num = sum (L_j^2 + L_j L_{j+1} + L_{j+1}^2)/3
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    # d num / d L_k
    dnum_dL = np.zeros_like(L)
    # contribution from pair (k, k+1) as a: (2a+b)/3 ; as b: (a+2b)/3
    dnum_dL[:-1] += (2 * a + b) / 3.0
    dnum_dL[1:] += (a + 2 * b) / 3.0
    return num, dnum_dL, L, s


def _backprop(h, dnum_dL):
    """Given dnum/d(knots) return dnum/dh. knots = [0, conv(h,h), 0]."""
    # L_inner = conv(h,h), dnum_dL_inner = dnum_dL[1:-1]
    g = dnum_dL[1:-1]
    n = len(h)
    # d/dh_i sum_k g_k * (h*h)_k  where (h*h)_k = sum_j h_j h_{k-j}
    # = 2 * (h * g_rev) restricted... use correlation via fftconvolve
    if n > 750:
        # conv of h with reversed g gives correlation
        c = fftconvolve(h, g[::-1], mode='valid')
        return 2.0 * c
    return 2.0 * np.convolve(h, g[::-1], mode='valid')


def _rescale(h):
    s = h.sum()
    if s <= 0:
        return h
    return h / s


def _fun_grad(h, beta=None):
    """Return (val=-R, grad=-dR/dh). If beta given, use softmax surrogate."""
    h = np.asarray(h, dtype=float)
    if np.any(h < 0):
        h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return 1e6, np.zeros_like(h)
    num, dnum_dL, L, s = _num_and_dq(h)
    if beta is None:
        k = int(np.argmax(L))
        mx = L[k]
        dden_dL = np.zeros_like(L)
        dden_dL[k] = s * s
        den = s * s * mx
    else:
        mx = np.max(L)
        w = np.exp(beta * (L - mx))
        sw = w.sum()
        soft = mx + np.log(sw) / beta
        dsoft_dL = w / sw
        den = s * s * soft
        dden_dL = s * s * dsoft_dL
    if den <= 0:
        return 1e6, np.zeros_like(h)
    val = -num / den
    # dR/dh = (dnum*den - num*dden) / den^2
    gnum = _backprop(h, dnum_dL)
    gden = _backprop(h, dden_dL)
    # also s dependence: num has no s, den = s^2 * (...). but we normalized? no, keep raw.
    # den = s^2 * M. d den/dh_i includes 2 s M + s^2 dM/dh_i
    # M = mx or soft; dM/dh from dden_dL above already includes s^2 factor; separate:
    # Let's recompute cleanly: den = s^2 * M
    if beta is None:
        k = int(np.argmax(L))
        M = L[k]
        dM = _backprop(h, dden_dL / (s * s)) if s > 0 else np.zeros_like(h)
    else:
        M = soft
        dM = _backprop(h, dden_dL / (s * s)) if s > 0 else np.zeros_like(h)
    dden = 2.0 * s * M * np.ones_like(h) + s * s * dM
    dR = (gnum * den - num * dden) / (den * den)
    return val, -dR


def _fun_grad_tie(h):
    """Tie-averaged: average gradient over all knots near max."""
    h = np.asarray(h, dtype=float)
    if np.any(h < 0):
        h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return 1e6, np.zeros_like(h)
    num, dnum_dL, L, s = _num_and_dq(h)
    mx = np.max(L)
    mask = L >= mx * (1 - 1e-9)
    cnt = mask.sum()
    dden_dL = np.zeros_like(L)
    dden_dL[mask] = s * s / cnt
    den = s * s * mx
    if den <= 0:
        return 1e6, np.zeros_like(h)
    val = -num / den
    gnum = _backprop(h, dnum_dL)
    dden = _backprop(h, dden_dL)
    dR = (gnum * den - num * dden) / (den * den)
    return val, -dR


def _fun_grad_beta(h, beta):
    return _fun_grad(h, beta=beta)


def _lbfgs_all_pos(h, iters, deadline, beta=None, tie=False):
    """L-BFGS on all positive entries with analytic gradient."""
    h = np.asarray(h, dtype=float).copy()
    if h.sum() <= 0:
        return h
    h = _rescale(h)
    N = len(h)

    if tie:
        fg = _fun_grad_tie
    elif beta is not None:
        fg = lambda x: _fun_grad_beta(x, beta)
    else:
        fg = _fun_grad

    def obj(x):
        hh = np.zeros(N)
        hh[:] = np.abs(x)
        return fg(hh)

    try:
        res = minimize(obj, h.copy(), method='L-BFGS-B', jac=True,
                       options={'maxiter': iters, 'ftol': 1e-15, 'gtol': 1e-12})
        hh = np.abs(res.x)
        if hh.sum() > 0:
            hh = _rescale(hh)
            if R_of(hh) >= R_of(h):
                return hh
    except Exception:
        pass
    return h


def _lbfgs_block(h, idx, iters, deadline, beta=None, tie=False):
    h = np.asarray(h, dtype=float).copy()
    if h.sum() <= 0:
        return h
    h = _rescale(h)
    N = len(h)
    idx = np.asarray(idx, dtype=int)
    if len(idx) < 2:
        return h

    if tie:
        fg = _fun_grad_tie
    elif beta is not None:
        fg = lambda x: _fun_grad_beta(x, beta)
    else:
        fg = _fun_grad

    def obj(x):
        hh = h.copy()
        hh[idx] = np.abs(x)
        return fg(hh)

    try:
        res = minimize(obj, h[idx].copy(), method='L-BFGS-B', jac=True,
                       options={'maxiter': iters, 'ftol': 1e-15, 'gtol': 1e-12})
        hh = h.copy()
        hh[idx] = np.abs(res.x)
        if hh.sum() > 0:
            hh = _rescale(hh)
            if R_of(hh) >= R_of(h):
                return hh
    except Exception:
        pass
    return h


def _peak_window(h, pad, iters, deadline):
    h = np.asarray(h, dtype=float).copy()
    if h.sum() <= 0:
        return h
    N = len(h)
    L = _knots(h)
    k = int(np.argmax(L))
    w = max(2, int(pad * N))
    lo = max(0, k - w)
    hi = min(N, k + w)
    if hi - lo < 2:
        return h
    idx = np.arange(lo, hi)
    idx = idx[h[idx] > 1e-12]
    if len(idx) < 2:
        return h
    return _lbfgs_block(h, idx, iters, deadline, tie=True)


def _peak_ladder(h, pads, iters, deadline):
    for pad in pads:
        if time.process_time() > deadline:
            break
        h = _peak_window(h, pad, iters, deadline)
    return h


def _spectral_seed(N0, L, rng, n_iter=150):
    lags = np.arange(N0)
    u = lags / (N0 - 1)
    G = np.zeros(N0)
    lo, hi = 0.15, 0.85
    ramp = 0.10
    for i, uu in enumerate(u):
        if uu < lo - ramp or uu > hi + ramp:
            G[i] = 0.0
        elif lo <= uu <= hi:
            G[i] = 1.0
        elif uu < lo:
            t = (uu - (lo - ramp)) / ramp
            G[i] = 0.5 * (1 - np.cos(np.pi * t))
        else:
            t = ((hi + ramp) - uu) / ramp
            G[i] = 0.5 * (1 - np.cos(np.pi * t))
    Gp = np.zeros(L)
    Gp[0] = G[0]
    for k in range(1, N0):
        Gp[k] = G[k]
        Gp[L - k] = G[k]
    Fg = np.real(np.fft.rfft(Gp))
    mag = np.sqrt(np.maximum(Fg, 0.0))

    best = None
    bestR = -1.0
    for _ in range(6):
        phi = rng.uniform(0, 2 * np.pi, len(mag))
        x = None
        for it in range(n_iter):
            X = mag * np.exp(1j * phi)
            x = np.fft.irfft(X, L)
            x = np.maximum(x, 0.0)
            x[N0:] = 0.0
            if x.sum() <= 0:
                break
            X2 = np.fft.rfft(x)
            phi = np.angle(X2)
        if x is None:
            continue
        h = x[:N0].copy()
        if h.sum() <= 0:
            continue
        h = _rescale(h)
        r = R_of(h)
        if r > bestR:
            bestR = r
            best = h.copy()
    return best, bestR


def _nearmax_frac(h, tol=0.01):
    L = _knots(h)
    m = np.max(L)
    if m <= 0:
        return 0.0
    return float(np.mean(L > (1 - tol) * m))


def construct(budget_seconds, start):
    t0 = time.process_time()
    end = t0 + budget_seconds
    rng = np.random.default_rng(12345)

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.sum() > 0 and np.all(np.isfinite(s)) and np.all(s >= 0):
            s = _rescale(s)
            best = s.copy()
            bestR = R_of(best)

    N0 = 2048
    L = 8192

    # base vector: ignore 50-cell shape, use flat
    base = np.ones(N0)

    # ---- Seed phase ----
    seed_end = t0 + 0.30 * budget_seconds
    best_seed = None
    best_seedR = -1.0
    while time.process_time() < seed_end:
        h, r = _spectral_seed(N0, L, rng)
        if h is not None and r > best_seedR:
            best_seedR = r
            best_seed = h.copy()
        if time.process_time() > seed_end:
            break

    if best_seed is not None:
        nf = _nearmax_frac(best_seed, 0.01)
        print(f"seed R={best_seedR:.6f} nearmax1%={nf:.3f} N={N0}")
        if best_seedR > bestR:
            bestR = best_seedR
            best = best_seed.copy()
    else:
        print("seed failed, using base")
        if best is None:
            best = base.copy()
            bestR = R_of(best)

    # ---- Polish phase ----
    pol_end = t0 + 0.75 * budget_seconds
    beta_ladder = (1e2, 1e3, 1e4, 1e6, 1e7)
    for beta in beta_ladder:
        if time.process_time() > pol_end:
            break
        sub = min(pol_end, time.process_time() + 3.0)
        h = _lbfgs_all_pos(best, 200, sub, beta=beta)
        r = R_of(h)
        if r > bestR:
            bestR = r
            best = h.copy()
        h = _peak_ladder(best, (0.15, 0.10, 0.06, 0.03), 150, sub)
        r = R_of(h)
        if r > bestR:
            bestR = r
            best = h.copy()
        print(f"polish beta={beta:.0e} R={bestR:.6f}")

    # ---- Lift phase ----
    lift_end = t0 + 0.88 * budget_seconds
    for attempt in range(2):
        if time.process_time() > lift_end:
            break
        h = best.copy()
        N = len(h)
        a = rng.uniform(0.2, 0.8, N)
        h2 = np.zeros(2 * N)
        h2[0::2] = a * h
        h2[1::2] = (1 - a) * h
        if h2.sum() <= 0:
            continue
        h2 = _rescale(h2)
        for beta in beta_ladder:
            if time.process_time() > lift_end:
                break
            sub = min(lift_end, time.process_time() + 3.0)
            h2 = _lbfgs_all_pos(h2, 150, sub, beta=beta)
            r = R_of(h2)
            if r > bestR:
                bestR = r
                best = h2.copy()
        print(f"lift attempt {attempt} R={bestR:.6f} N={len(best)}")

    # ---- Final tie-averaged polish ----
    final_end = t0 + 0.97 * budget_seconds
    if best is not None:
        sub = min(final_end, time.process_time() + 3.0)
        h = _lbfgs_all_pos(best, 200, sub, tie=True)
        r = R_of(h)
        if r > bestR:
            bestR = r
            best = h.copy()
        h = _peak_ladder(best, (0.06, 0.03, 0.015), 150, final_end)
        r = R_of(h)
        if r > bestR:
            bestR = r
            best = h.copy()

    print(f"final best R={bestR:.6f} N={len(best) if best is not None else 0}")

    if best is None:
        best = np.ones(50)

    startR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.sum() > 0 and np.all(np.isfinite(s)) and np.all(s >= 0):
            startR = R_of(_rescale(s))

    if bestR >= startR:
        return best
    else:
        return {"best": np.asarray(start, dtype=float) if start is not None else best,
                "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _subdivide(h):
    """Insert midpoints: linear interp doubles resolution, preserving shape."""
    n = h.size
    out = np.empty(2 * n - 1)
    out[0::2] = h
    out[1::2] = 0.5 * (h[:-1] + h[1:])
    return out


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _compress(h):
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    lo, hi = nz[0], nz[-1]
    if hi - lo + 1 < h.size:
        return h[lo:hi + 1]
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    rng = np.random.RandomState(20240607)

    # Phase A: refine at current resolution (tie-aware to break max ties)
    if time.process_time() < deadline - 8.0:
        for beta, mi in [(0.0, 1500), (1e6, 800), (1e7, 800), (1e8, 800)]:
            if time.process_time() >= deadline - 6.0:
                break
            h_try = _lbfgs_all(best, mi, deadline - 5.0, beta=beta, tie=True)
            r = R_of(h_try)
            if r > bestR + 1e-14:
                best, bestR = h_try.copy(), r
                print("A polish beta=%.0e R=%.7f" % (beta, bestR))

    # Phase B: subdivision — double resolution, polish, keep if better.
    # Enables finer structure near the peak; the main new idea.
    while time.process_time() < deadline - 6.0 and best.size < 400000:
        sub = _subdivide(best)
        h_try = _lbfgs_all(sub, 1200, deadline - 4.0, beta=0.0, tie=True)
        # peak-window polish at higher resolution
        if time.process_time() < deadline - 4.0:
            free = _peak_window(h_try, tol=0.999, pad_frac=0.5, extra=512)
            h_try2 = _lbfgs_block(h_try, free, 400, deadline - 3.0,
                                  beta=1e7, tie=True)
            r2 = R_of(h_try2)
            if r2 > R_of(h_try):
                h_try = h_try2
        r = R_of(h_try)
        print("B subdivide N=%d R=%.7f (best %.7f)" % (h_try.size, r, bestR))
        if r > bestR - 2e-5:
            # accept (even slight regression) to keep exploring finer grid
            best = _compress(h_try)
            if r > bestR:
                bestR = r
        else:
            break

    # Phase C: random block coordinate passes at current resolution
    n = best.size
    attempts = 0
    while time.process_time() < deadline - 3.0:
        attempts += 1
        wlen = int(n * rng.uniform(0.05, 0.35))
        wlen = max(64, min(n, wlen))
        lo = rng.randint(0, max(1, n - wlen))
        free = np.arange(lo, lo + wlen)
        beta = 0.0 if rng.rand() < 0.5 else 1e7
        h_try = _lbfgs_block(best, free, 400, deadline - 2.0, beta=beta, tie=True)
        r = R_of(h_try)
        if r > bestR + 1e-14:
            best, bestR = h_try, r
            print("C block wlen=%d R=%.7f" % (wlen, bestR))
        if attempts % 6 == 0 and time.process_time() < deadline - 3.0:
            hs = _lbfgs_all(_seed_zeros(best), 800, deadline - 2.0, tie=True)
            r = R_of(hs)
            if r > bestR + 1e-14:
                best, bestR = _compress(hs), r
                print("C reseed+global R=%.7f (N=%d)" % (bestR, best.size))

    # Phase D: final aggressive polish
    if time.process_time() < deadline - 1.0:
        hf = _lbfgs_all(best, 3000, deadline - 0.6, tie=True)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf
        if time.process_time() < deadline - 0.5:
            free = _peak_window(best, tol=0.999, pad_frac=0.5, extra=256)
            hf = _lbfgs_block(best, free, 400, deadline - 0.3, beta=1e8, tie=True)
            rf = R_of(hf)
            if rf > bestR + 1e-14:
                best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

