    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _subsample(h, factor):
    """Pool h by averaging contiguous blocks of `factor` steps."""
    if factor <= 1 or h.size <= factor:
        return h.copy()
    n = h.size
    nb = n // factor
    if nb < 1:
        return h.copy()
    trim = nb * factor
    return h[:trim].reshape(nb, factor).mean(axis=1)


def _refine_up(h, deadline):
    """Upsample by linear interpolation and re-optimise (adds resolution)."""
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    n2 = min(2 * n, 1000000)
    xs = np.linspace(0.0, 1.0, n, endpoint=False)
    xt = np.linspace(0.0, 1.0, n2, endpoint=False)
    h2 = np.interp(xt, xs, h)
    h2 = _rescale(h2)
    # brief beta polish at the finer resolution
    h2 = _lbfgs_all_pos(h2, 200, deadline - 0.4, beta=1e6)
    if time.process_time() < deadline - 0.3:
        h3 = _lbfgs_all_pos(h2, 200, deadline - 0.2, beta=0.0)
        if R_of(h3) > R_of(h2):
            h2 = h3
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    best, startR = None, 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f N=%d zero=%.4f nearmax5=%.4f ties=%d"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best), _tie_count(best)))

    # ---- Phase 1: multiscale search on subsampled versions ----
    # Coarse optimisations escape the local basin of the full-resolution start,
    # then we upsample back. This is the genuinely different idea.
    loop_end = t0 + min(budget_seconds * 0.55, 33.0)
    for factor in (4, 2, 1):
        if time.process_time() >= loop_end - 2.0:
            break
        hs = _subsample(best, factor)
        r_s = R_of(hs)
        slice_end = min(loop_end, time.process_time() + 5.0)
        for beta in (1e6, 1e5, 1e4, 0.0):
            if time.process_time() >= slice_end - 0.8:
                break
            ht = _lbfgs_all_pos(hs, 400, slice_end - 0.5, beta=beta)
            if R_of(ht) > r_s + 1e-14:
                hs, r_s = ht, R_of(ht)
        # upsample result back to full resolution and polish
        if factor > 1:
            n = best.size
            nb = hs.size
            xs = np.linspace(0.0, 1.0, nb, endpoint=False)
            xt = np.linspace(0.0, 1.0, n, endpoint=False)
            hu = np.interp(xt, xs, hs)
            hu = _rescale(hu)
        else:
            hu = hs
        # polish at full resolution with the real objective
        slice_end2 = min(loop_end, time.process_time() + 4.0)
        if time.process_time() < slice_end2 - 0.6:
            hu = _lbfgs_all_pos(hu, 400, slice_end2 - 0.4, beta=1e5)
        if time.process_time() < slice_end2 - 0.3:
            hu = _lbfgs_all_pos(hu, 300, slice_end2 - 0.2, beta=0.0)
        if time.process_time() < slice_end2 - 0.2:
            hu = _peak_ladder(hu, slice_end2 - 0.1, pads=(0.05, 0.03), iters=150)
        ru = R_of(hu)
        acc = ru > bestR + 1e-14
        if acc:
            best, bestR = hu.copy(), ru
        print("multiscale f=%d dR=%+.3e %s R=%.9f N=%d"
              % (factor, ru - bestR, "ACCEPT" if acc else "no gain", bestR, best.size))

    # ---- Phase 2: try increasing resolution ----
    while time.process_time() < t0 + budget_seconds * 0.72 - 3.0:
        if best.size >= 1000000:
            break
        slice_end = min(t0 + budget_seconds * 0.72, time.process_time() + 6.0)
        hu = _refine_up(best, slice_end - 0.5)
        ru = R_of(hu)
        if ru > bestR + 1e-14:
            best, bestR = hu.copy(), ru
            print("upsample ACCEPT R=%.9f N=%d" % (bestR, best.size))
        else:
            # even if not better, keep trying finer only if close
            print("upsample no gain R=%.9f (best %.9f) N=%d"
                  % (ru, bestR, hu.size))
            if hu.size > 4 * best.size:
                break

    # ---- Phase 3: exact tie-averaged and argmax polishing at full res ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 4.0:
        ht = _lbfgs_all_pos(best, 800, fd - 2.5, tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
        else:
            print("FINAL tie no gain R=%.9f" % rt)

    if time.process_time() < fd - 1.0:
        ht = _peak_ladder(best, fd - 0.5, pads=(0.04, 0.02), iters=300)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("FINAL peak ACCEPT R=%.9f" % bestR)

    if time.process_time() < fd - 0.5:
        ht = _lbfgs_all_pos(best, 300, fd - 0.2, beta=0.0)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("FINAL argmax ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_ksmooth(h, w):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    if w <= 0:
        return _fun_grad_tie(h)
    num, dq, Lf = _num_and_dq(h)
    K = (w + 1 - np.abs(np.arange(2 * w + 1) - w)) / float((w + 1) ** 2)
    gsm = fftconvolve(Lf, K, mode='same')[:Lf.size]
    m = int(np.argmax(gsm))
    gm = gsm[m]
    if gm <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    n = Lf.size
    for i in range(m - w, m + w + 1):
        if 0 <= i < n:
            gLf[i] += K[(i - m) + w] / gm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(gm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False, w=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if w is not None:
        fg = (lambda hh: _fun_grad_ksmooth(hh, w))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _R_coarse(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = np.concatenate(([0.0], np.convolve(c, c), [0.0]))
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _detect_staircase(h):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in (1, 2, 3, 4, 5, 8, 16, 32, 64):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-10:
            r_c = _R_coarse(c)
            r_h = R_of(h)
            if abs(r_c - r_h) < 1e-12:
                return c, p
    return None, 1


def _sweep_coords(c, coords, deadline, rng):
    m = c.size
    best_R = _R_coarse(c)
    n_moved = 0
    deltas = np.array([-0.75, -0.5, -0.3, -0.15, -0.07, 0.0,
                       0.07, 0.15, 0.3, 0.5, 0.75])
    order = rng.permutation(coords)
    for k in order:
        if time.process_time() > deadline:
            break
        ck = c[k]
        if ck <= 0:
            continue
        cands = ck * deltas
        cands = np.concatenate((cands, [0.0]))
        cands = np.clip(cands, 0.0, None)
        best_d = 0.0
        best_r = best_R
        for d in cands:
            if d == 0.0:
                continue
            c_old = c[k]
            c[k] = d
            r = _R_coarse(c)
            c[k] = c_old
            if r > best_r + 1e-16:
                best_r = r
                best_d = d
        if best_d != 0.0:
            allv = np.sort(np.unique(np.concatenate((cands, [ck]))))
            idx = np.searchsorted(allv, best_d)
            lo = allv[max(0, idx - 1)]
            hi = allv[min(allv.size - 1, idx + 1)]
            gr = (np.sqrt(5.0) - 1.0) / 2.0
            a, b = lo, hi
            c1 = b - gr * (b - a)
            c2 = a + gr * (b - a)
            c[k] = c1; f1 = _R_coarse(c)
            c[k] = c2; f2 = _R_coarse(c)
            for _ in range(30):
                if time.process_time() > deadline:
                    break
                if f1 < f2:
                    a = c1; c1 = c2; f1 = f2
                    c2 = a + gr * (b - a)
                    c[k] = c2; f2 = _R_coarse(c)
                else:
                    b = c2; c2 = c1; f2 = f1
                    c1 = b - gr * (b - a)
                    c[k] = c1; f1 = _R_coarse(c)
            c[k] = 0.5 * (a + b)
            r = _R_coarse(c)
            if r > best_R + 1e-16:
                best_R = r
                n_moved += 1
            else:
                c[k] = ck
    return c, best_R, n_moved


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # ---- Phase K: spatial-smoothing max surrogate ladder ----
    k_end = t0 + budget_seconds * 0.65
    N = best.size
    ws = [max(8, int(0.006 * N)), max(4, int(0.003 * N)),
          max(2, int(0.0015 * N)), 2, 1, 0]
    for w in ws:
        if time.process_time() >= k_end - 1.0:
            break
        if w > 0:
            ht = _lbfgs_all_pos(best, 250, min(k_end - 0.5,
                                               time.process_time() + 8.0), w=w)
        else:
            ht = _lbfgs_all_pos(best, 250, min(k_end - 0.5,
                                               time.process_time() + 8.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        f01, f1, f5 = _nearmax_fracs(best)
        print("w=%d R=%.9f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (w, bestR, f01, f1, f5))

    # ---- Phase V: value-band polish ----
    band_end = t0 + budget_seconds * 0.86
    band_edges = [(0.0, 0.05), (0.05, 0.20), (0.20, 0.50),
                  (0.50, 0.80), (0.80, 0.95), (0.95, 1.001)]
    cyc = 0
    while time.process_time() < band_end - 2.0:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        order = rng.permutation(len(band_edges))
        gains = []
        for bi in order:
            if time.process_time() >= band_end - 1.5:
                break
            lo, hi = band_edges[bi]
            lo *= M; hi *= M
            sel = np.flatnonzero((best > 0) & (v >= lo) & (v < hi))
            if sel.size == 0:
                gains.append(0.0)
                continue
            active = _dilate(sel, n, 16)
            if active.size < 20 or active.size > 0.8 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 300,
                              min(band_end - 1.0,
                                  time.process_time() + 6.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
            if time.process_time() < band_end - 1.0:
                win = _peak_window(best, pad_frac=0.06, extra=64)
                ht2 = _lbfgs_block(best, win, 200,
                                   min(band_end - 0.5,
                                       time.process_time() + 4.0), beta=1e7)
                r2 = R_of(ht2)
                if r2 > bestR + 1e-15:
                    best, bestR = ht2.copy(), r2
        f01, f1, f5 = _nearmax_fracs(best)
        print("band cyc=%d R=%.9f gains=%s near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (cyc, bestR,
                 " ".join("%.1e" % g for g in gains), f01, f1, f5))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase B: peak ladder polish ----
    peak_end = t0 + budget_seconds * 0.93
    if time.process_time() < peak_end - 3.0:
        ht = _peak_ladder(best, peak_end - 1.0,
                          pads=(0.06, 0.03), iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.9f" % bestR)

    # ---- Phase C: final exact tie polish ----
    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _smooth_perturb(h, rng, scale=0.05):
    n = h.size
    if n < 32:
        return h
    x = np.arange(n, dtype=float) / n
    disp = np.zeros(n)
    for _ in range(3):
        freq = rng.uniform(1.0, 4.0)
        phase = rng.uniform(0, 2 * np.pi)
        amp = rng.uniform(0.0, scale) * n
        disp += amp * np.sin(2 * np.pi * freq * x + phase)
    xs = np.clip(x + disp / n, 0.0, 1.0)
    xs = np.sort(xs)
    src = np.linspace(0, 1, n)
    return np.interp(src, xs, h)


def _refine(h, budget_end, rng, log_prefix=""):
    """Local refinement: softmax polish + peak-block polish. Returns (h, R)."""
    best = _rescale(np.clip(h, 0, None))
    bestR = R_of(best)
    for beta in (0, 400, 2000):
        if time.process_time() >= budget_end - 0.5:
            break
        cap = min(budget_end - 0.3, time.process_time() + 3.0)
        hs = _lbfgs_all_pos(best, 150, cap, beta=beta)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            best, bestR = hs, rs
    for frac in (0.02, 0.05, 0.10):
        if time.process_time() >= budget_end - 0.5:
            break
        free = _peak_window(best, frac=frac)
        cap = min(budget_end - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_block(best, free, 80, cap)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR

    # ---- New idea: resample the start onto a coarser grid, refine, then upscale ----
    # The start's structure is smooth; refining at coarser resolution is cheaper per
    # iteration and can escape fine-scale local valleys; then map back and polish.
    alt = best.copy()
    altR = bestR
    n0 = best.size
    for factor in (2, 4):
        if time.process_time() >= deadline - 3.0:
            break
        m = max(64, n0 // factor)
        if m >= n0:
            continue
        # block-average downsample
        idx = (np.arange(m + 1) * n0) // m
        coarse = np.array([best[idx[k]:max(idx[k] + 1, idx[k + 1])].mean()
                           for k in range(m)])
        cap = min(deadline - 1.0, time.process_time() + 6.0)
        coarse, cR = _refine(coarse, cap, rng)
        # upsample back by linear interpolation onto n0
        src = np.linspace(0, 1, m)
        dst = np.linspace(0, 1, n0)
        up = np.interp(dst, src, coarse)
        cap = min(deadline - 0.5, time.process_time() + 5.0)
        up, uR = _refine(up, cap, rng)
        if uR > altR + 1e-14:
            alt, altR = up, uR
            print("coarse f=%d up: R=%.12f" % (factor, altR))

    # ---- Direct perturb-and-refine on the full-resolution start ----
    round_ = 0
    while time.process_time() < deadline - 2.0:
        round_ += 1
        # Try a few different perturbation scales
        for scale in (0.01, 0.03, 0.06, 0.10):
            if time.process_time() >= deadline - 2.0:
                break
            hw = _smooth_perturb(alt, rng, scale=scale)
            cap = min(deadline - 0.5, time.process_time() + 3.0)
            hw, rw = _refine(hw, cap, rng)
            if rw > altR + 1e-14:
                alt, altR = hw, rw
                print("r%d pert(%.2f): R=%.12f" % (round_, scale, altR))

        # Also try direct full polish from alt with a small random multiplicative jitter
        if time.process_time() < deadline - 3.0:
            jitter = 1.0 + 0.02 * rng.standard_normal(alt.size)
            hw = _rescale(np.clip(alt * jitter, 0, None))
            cap = min(deadline - 0.5, time.process_time() + 3.0)
            hw, rw = _refine(hw, cap, rng)
            if rw > altR + 1e-14:
                alt, altR = hw, rw
                print("r%d jitter: R=%.12f" % (round_, altR))

    mx, m, near = _stats(alt)
    print("final R=%.12f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (altR, alt.size, 100.0 * np.mean(alt <= 0), mx, m, near))
    print("gain vs start: %.3e" % (altR - start_bestR))

    if altR > start_bestR + 1e-13:
        return {"best": alt, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": alt}

