    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


# ---------- NEW: adaptive coordinate-descent refinement ----------
# The key idea: instead of only global L-BFGS on all N positions (which
# stalls once the pure gradient is tiny because the max-knot is a single
# active constraint), do per-block local polishing with a widening then
# shrinking set of blocks. This lets the shape keep improving in the
# high-curvature regions (near the peak of f*f) where the objective is
# nearly flat in the global gradient direction.

def _block_refine(h, deadline, nblocks, iters_per=120, overlap=0.15):
    N = h.size
    if N < 8:
        return h
    edges = np.linspace(0, N, nblocks + 1).astype(int)
    ov = max(1, int(N / nblocks * overlap))
    order = list(range(nblocks))
    # visit blocks with largest local |f*f - peak| first (impactful)
    Lf = _knots(h)
    mx = Lf.max()
    impact = []
    for b in order:
        lo = edges[b]; hi = edges[b + 1]
        # knot indices correspond to position lo+1..hi
        klo = lo; khi = min(Lf.size, hi + 2)
        impact.append(np.sum(np.abs(Lf[klo:khi] - mx)))
    order = [b for _, b in sorted(zip(impact, order), reverse=True)]
    for b in order:
        if time.process_time() > deadline - 0.5:
            break
        lo = max(0, edges[b] - ov)
        hi = min(N, edges[b + 1] + ov)
        win = np.arange(lo, hi)
        ht = _lbfgs_block(h, win, iters_per, deadline - 0.4, beta=1e6)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
        if time.process_time() > deadline - 0.5:
            break
        ht = _lbfgs_block(h, win, iters_per, deadline - 0.4, tie=True)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)

    startR = R_of(best)
    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt = None
    altR = -1.0

    # Phase 1: short global L-BFGS to settle
    ph1 = t0 + budget_seconds * 0.15
    if time.process_time() < ph1 - 1.0:
        ht = _lbfgs_all_pos(best, 300, ph1 - 0.5, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P1 global R=%.9f" % bestR)

    # Phase 2: block refinement — the new idea
    ph2 = t0 + budget_seconds * 0.55
    nb_list = [16, 24, 32, 48, 64, 96, 128]
    for nb in nb_list:
        if time.process_time() > ph2 - 1.5:
            break
        ht = _block_refine(best.copy(), ph2, nb, iters_per=100)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P2 block nb=%d R=%.9f" % (nb, bestR))
        else:
            # keep as alternative if it's a distinct shape
            if alt is None or r > altR:
                alt, altR = ht.copy(), r

    # Phase 3: peak ladder (careful around the single active max)
    ph3 = t0 + budget_seconds * 0.75
    if time.process_time() < ph3 - 1.5:
        ht = _peak_ladder(best.copy(), ph3 - 0.5,
                          pads=(0.10, 0.06, 0.04, 0.02), iters=200)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P3 peak R=%.9f" % bestR)

    # Phase 4: another short block pass at finer granularity
    ph4 = t0 + budget_seconds * 0.86
    if time.process_time() < ph4 - 1.5:
        ht = _block_refine(best.copy(), ph4, 192, iters_per=80)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P4 fine block R=%.9f" % bestR)

    # Phase 5: final global polish with beta tie-breaking
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 1.5:
        ht = _lbfgs_all_pos(best, 400, fd - 0.5, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P5 final R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt is not None and altR > startR + 1e-15 and bestR <= startR + 1e-14:
        result["alternative"] = alt
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_near_peak(h, deadline, rcur, iters=6, maxiter=300):
    for k in range(iters):
        if time.process_time() >= deadline - 1.0:
            break
        Lf = _knots(h)
        m = int(np.argmax(Lf))
        n = h.size
        c = m // 2
        half = max(16, int(0.25 * n))
        lo_h = max(0, c - half)
        hi_h = min(n - 1, c + half)
        free = np.arange(lo_h, hi_h + 1)
        beta = 64.0 * (2 ** k)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _extend_support(h, deadline, rcur, factor=1.5, maxiter=300):
    """Genuinely different move: widen the support (embed in a longer array
    with empty margins) then re-optimize the whole thing. Allows the optimizer
    to grow the effective support of f beyond the current bounding box."""
    n = h.size
    m = int(n * factor)
    if m <= n:
        return h, rcur
    if m > 1000000:
        m = 1000000
    pad = (m - n) // 2
    hp = np.zeros(m)
    hp[pad:pad + n] = h
    hp = _rescale(hp)
    cand = _lbfgs_log(hp, maxiter=maxiter, deadline=deadline)
    r = R_of(cand)
    if r > rcur:
        return cand, r
    return h, rcur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(h)
        best_r = R_of(best)
        start_r = best_r

    alt = None
    alt_r = -1.0

    # Sharpen with beta-homotopy on the whole support.
    if time.process_time() < deadline - 8:
        h_sharp, r_sharp = _homotopy(
            best, (64, 256, 1024, 4096, 16384), 200, deadline)
        if r_sharp > best_r:
            best, best_r = h_sharp, r_sharp
        print("sharpen R=%.6f" % best_r)

    # Extend support: new idea — grow the bounding box and re-optimize.
    if time.process_time() < deadline - 10:
        h_ext, r_ext = _extend_support(best, deadline, best_r, factor=1.4, maxiter=250)
        if r_ext > best_r:
            best, best_r = h_ext, r_ext
        else:
            alt, alt_r = h_ext, r_ext
        print("extend R=%.6f" % best_r)

    if time.process_time() < deadline - 6:
        h_sharp2, r_sharp2 = _refine_near_peak(best, deadline, best_r, iters=5, maxiter=250)
        if r_sharp2 > best_r:
            best, best_r = h_sharp2, r_sharp2
        print("peak-refine R=%.6f" % best_r)

    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        seed = best.copy()
        rng = np.random.default_rng(it * 7919)
        noise = 1.0 + 0.05 * rng.standard_normal(seed.size)
        seed = _rescale(np.clip(seed * noise, 0.0, None))

        cand, r = _homotopy(seed, (32, 128, 512, 2048, 8192), 150, deadline)
        if r > best_r:
            best, best_r = cand, r
        elif alt is None or r > alt_r:
            alt, alt_r = cand, r

        cand, r = _polish(best, deadline, best_r)
        if r > best_r:
            best, best_r = cand, r

        if it % 2 == 0:
            cand, r = _refine_near_peak(best, deadline, best_r, iters=3, maxiter=200)
            if r > best_r:
                best, best_r = cand, r

        if it % 3 == 0:
            cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
            print("  it#%d R=%.6f (start %.6f)" % (it, best_r, start_r))

    # Trim trailing/leading zeros to keep array compact.
    best = _rescale(best)
    nz = np.flatnonzero(best > 1e-14 * best.max())
    if nz.size > 0:
        lo = max(0, nz[0] - 2)
        hi = min(best.size, nz[-1] + 3)
        best = _rescale(best[lo:hi])

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None:
        if start_r >= best_r:
            if alt is not None and alt_r > start_r:
                return {"best": start_arr, "alternative": alt}
            return {"best": start_arr, "alternative": best}
        if alt is not None and alt_r > 0 and alt_r < best_r:
            return {"best": best, "alternative": alt}
        return {"best": best, "alternative": start_arr}
    return best

