    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


# ---------- free-mesh helpers ----------

def _rasterize(a, u, N):
    """Rasterize mesh heights a (K) with softmax widths from u (K) to N cells."""
    K = a.size
    uu = u - u.max()
    w = np.exp(uu)
    w /= w.sum()
    edges = np.cumsum(w) * N
    edges[-1] = N
    idx = np.searchsorted(edges, np.arange(N) + 0.5)
    idx = np.clip(idx, 0, K - 1)
    return a[idx], idx, w


def _mesh_fg(v, u, N, beta=0.0):
    """Value and gradients wrt v (log heights) and u (log widths)."""
    a = np.exp(np.clip(v, -20.0, 20.0))
    h, idx, w = _rasterize(a, u, N)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros_like(v), np.zeros_like(u)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros_like(v), np.zeros_like(u)
    if beta > 0:
        e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
        Z = e.sum()
        wgt = e / Z
        sm = mx + np.log(Z) / beta
        gLf = -dq / num + wgt / sm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    else:
        m = int(np.argmax(Lf))
        gLf = -dq / num
        gLf[m] += 1.0 / mx
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    gh = _backprop(gLf, h) + 2.0 / s
    # gradient wrt a: sum of gh over cells mapping to each block
    ga = np.bincount(idx, weights=gh, minlength=a.size)
    gv = ga * a  # chain rule through a=exp(v)
    # gradient wrt u: cells are assigned to block idx; block widths w_k
    # h_i = a_{idx_i}. Moving u changes edges -> changes idx assignments.
    # Approximate: treat assignment as fixed (piecewise constant); gradient 0.
    # But we can use a smoothed estimate: perturbing u_k shifts edges.
    # For simplicity, use the "soft" gradient: each block's mass contribution.
    # d h_i / d u_k is nonzero only at boundaries; use a finite-difference-free
    # approximation via the continuous limit: treat block k's contribution to
    # h as a_k * w_k * N cells. Then d/d u_k of sum_i gh_i h_i involves
    # a_k * (sum over block k of gh) * d(w_k N)/d u_k = w_k(1-w_k) N.
    # We compute per-block mean gh and use that.
    K = a.size
    cnt = np.bincount(idx, minlength=K).astype(float)
    sumgh = np.bincount(idx, weights=gh, minlength=K)
    # contribution to log R from block k width change: a_k * mean_gh_k * d(w_k N)
    # d(w_k N)/d u_k = w_k(1-w_k) N ; cross terms w_k w_j N for j!=k
    # Full: d/d u_k = N * w_k * (a_k*mean_gh_k - sum_j w_j a_j mean_gh_j)
    ak = a * (sumgh / np.maximum(cnt, 1.0))
    mean_ak = np.sum(w * ak)
    gu = N * w * (ak - mean_ak)
    return val, gv, gu


def _mesh_opt(v0, u0, N, deadline, mode, maxiter, beta=0.0):
    """mode: 'v' (heights only), 'u' (widths only), 'vu' (joint)."""
    K = v0.size
    if mode == 'v':
        x0 = v0.copy()
        def f(x):
            val, gv, gu = _mesh_fg(x, u0, N, beta)
            return val, gv
        bounds = [(-20.0, 20.0)] * K
    elif mode == 'u':
        x0 = u0.copy()
        def f(x):
            val, gv, gu = _mesh_fg(v0, x, N, beta)
            return val, gu
        bounds = [(-20.0, 20.0)] * K
    else:
        x0 = np.concatenate((v0, u0))
        def f(x):
            val, gv, gu = _mesh_fg(x[:K], x[K:], N, beta)
            return val, np.concatenate((gv, gu))
        bounds = [(-20.0, 20.0)] * (2 * K)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return v0, u0
    if res is None:
        return v0, u0
    if mode == 'v':
        return np.clip(res.x, -20, 20), u0
    elif mode == 'u':
        return v0, np.clip(res.x, -20, 20)
    else:
        return np.clip(res.x[:K], -20, 20), np.clip(res.x[K:], -20, 20)


def _width_dev(w):
    wbar = 1.0 / w.size
    return float(np.max(np.abs(w / wbar - 1.0)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # ---- Free-mesh phase (~70% of budget) ----
    mesh_end = t0 + budget_seconds * 0.70
    N = best.size
    p = 32
    mesh_best = best.copy()
    mesh_bestR = bestR

    if N % p == 0:
        K = N // p
        c = best[::p].copy()
        h_rep = np.repeat(c, p)
        err = np.max(np.abs(best - h_rep)) / max(best.max(), 1e-300)
        print("staircase check p=%d K=%d err=%.2e" % (p, K, err))
        if err < 1e-12:
            eps = 1e-12
            v = np.log(np.maximum(c, eps))
            u = np.zeros(K)
            # verify rasterization matches
            h_test, idx_test, w_test = _rasterize(np.exp(v), u, N)
            err2 = np.max(np.abs(h_test - best)) / max(best.max(), 1e-300)
            print("raster check err=%.2e width_dev=%.2e" % (err2, _width_dev(w_test)))

            v_cur, u_cur = v.copy(), u.copy()

            def _eval_mesh(vv, uu):
                a = np.exp(np.clip(vv, -20, 20))
                h, idx, w = _rasterize(a, uu, N)
                return _rescale(h), R_of(_rescale(h)), w

            # (A) heights only
            if time.process_time() < mesh_end - 3.0:
                v1, u1 = _mesh_opt(v_cur, u_cur, N,
                                   min(mesh_end - 1.0, time.process_time() + 8.0),
                                   'v', 200)
                h1, r1, w1 = _eval_mesh(v1, u1)
                print("  mesh A(v) R=%.9f wdev=%.2e" % (r1, _width_dev(w1)))
                if r1 > mesh_bestR + 1e-15:
                    mesh_best, mesh_bestR = h1.copy(), r1
                    v_cur, u_cur = v1, u1

            # (B) widths only
            if time.process_time() < mesh_end - 3.0:
                v2, u2 = _mesh_opt(v_cur, u_cur, N,
                                   min(mesh_end - 1.0, time.process_time() + 8.0),
                                   'u', 150)
                h2, r2, w2 = _eval_mesh(v2, u2)
                print("  mesh B(u) R=%.9f wdev=%.2e" % (r2, _width_dev(w2)))
                if r2 > mesh_bestR + 1e-15:
                    mesh_best, mesh_bestR = h2.copy(), r2
                    v_cur, u_cur = v2, u2

            # (C) joint with beta 1e5 then 1e7
            for beta in (1e5, 1e7):
                if time.process_time() >= mesh_end - 3.0:
                    break
                v3, u3 = _mesh_opt(v_cur, u_cur, N,
                                   min(mesh_end - 1.0, time.process_time() + 8.0),
                                   'vu', 120, beta=beta)
                h3, r3, w3 = _eval_mesh(v3, u3)
                print("  mesh C(beta=%.0e) R=%.9f wdev=%.2e"
                      % (beta, r3, _width_dev(w3)))
                if r3 > mesh_bestR + 1e-15:
                    mesh_best, mesh_bestR = h3.copy(), r3
                    v_cur, u_cur = v3, u3

            # iterate a few more rounds if time permits
            cyc = 0
            while time.process_time() < mesh_end - 4.0 and cyc < 4:
                cyc += 1
                improved = False
                if time.process_time() < mesh_end - 3.0:
                    v1, u1 = _mesh_opt(v_cur, u_cur, N,
                                       min(mesh_end - 1.0,
                                           time.process_time() + 6.0), 'v', 150)
                    h1, r1, w1 = _eval_mesh(v1, u1)
                    if r1 > mesh_bestR + 1e-15:
                        mesh_best, mesh_bestR = h1.copy(), r1
                        v_cur, u_cur = v1, u1
                        improved = True
                if time.process_time() < mesh_end - 3.0:
                    v2, u2 = _mesh_opt(v_cur, u_cur, N,
                                       min(mesh_end - 1.0,
                                           time.process_time() + 6.0), 'u', 100)
                    h2, r2, w2 = _eval_mesh(v2, u2)
                    if r2 > mesh_bestR + 1e-15:
                        mesh_best, mesh_bestR = h2.copy(), r2
                        v_cur, u_cur = v2, u2
                        improved = True
                if time.process_time() < mesh_end - 3.0:
                    v3, u3 = _mesh_opt(v_cur, u_cur, N,
                                       min(mesh_end - 1.0,
                                           time.process_time() + 6.0),
                                       'vu', 100, beta=1e7)
                    h3, r3, w3 = _eval_mesh(v3, u3)
                    if r3 > mesh_bestR + 1e-15:
                        mesh_best, mesh_bestR = h3.copy(), r3
                        v_cur, u_cur = v3, u3
                        improved = True
                print("  mesh cyc=%d R=%.9f wdev=%.2e"
                      % (cyc, mesh_bestR, _width_dev(w3)))
                if not improved:
                    break

    if mesh_bestR > bestR + 1e-15:
        best, bestR = mesh_best.copy(), mesh_bestR
        print("mesh ACCEPT R=%.9f" % bestR)

    # ---- Final: peak ladder on incumbent ----
    peak_end = t0 + budget_seconds * 0.97
    if time.process_time() < peak_end - 3.0:
        ht = _peak_ladder(best, peak_end - 1.0,
                          pads=(0.06, 0.03), iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.9f" % bestR)

    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 2.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth_filter(h, k):
    """Light smoothing to break symmetry / escape flat ridges, then rescale."""
    if k <= 0 or h.size < 2 * k + 1:
        return h
    ker = np.ones(2 * k + 1) / (2 * k + 1)
    hs = np.convolve(h, ker, mode='same')
    return _rescale(np.clip(hs, 0, None))


def _refine(best, bestR, deadline, alt_state):
    for pad in [0.10, 0.06, 0.04, 0.03]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
        elif r2 > alt_state[1]:
            alt_state[0], alt_state[1] = ht2.copy(), r2
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        elif r > alt_state[1]:
            alt_state[0], alt_state[1] = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_state = [None, -1.0]

    # ---- Phase 1: smooth-perturbation basin hopping polish on current N ----
    # Light smoothing + reopt can escape the flat ridges that block pure LBFGS.
    hop_end = t0 + budget_seconds * 0.45
    hop = 0
    while time.process_time() < hop_end - 2.0:
        now = time.process_time()
        slice_dl = min(now + 5.0, hop_end)
        # perturbation strength varies with round
        k = [2, 4, 8, 16, 32][hop % 5]
        hp = _smooth_filter(best, k)
        if time.process_time() < slice_dl - 0.6:
            hp = _lbfgs_all_pos(hp, 150, slice_dl - 0.3, beta=1e7)
        if time.process_time() < slice_dl - 0.6:
            win = _peak_window(hp, pad_frac=0.08, extra=256)
            hp = _lbfgs_block(hp, win, 250, slice_dl - 0.3, beta=1e7)
        if time.process_time() < slice_dl - 0.6:
            hp = _lbfgs_all_pos(hp, 200, slice_dl - 0.3, beta=0.0)
        r = R_of(hp)
        if r > bestR + 1e-13:
            best, bestR = hp.copy(), r
            origin = 'hop%d' % hop
            print("hop%d k=%d NEW BEST R=%.9f" % (hop, k, bestR))
        elif r > alt_state[1]:
            alt_state[0], alt_state[1] = hp.copy(), r
        hop += 1
    print("hop rounds=%d R=%.9f" % (hop, bestR))

    # ---- Phase 2: final polish ----
    best, bestR = _refine(best, bestR, deadline, alt_state)

    if bestR < start_bestR - 1e-14:
        # our search regressed; keep the start as best
        best, bestR = start_best.copy(), start_bestR

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if (alt_state[0] is not None and alt_state[0].size == best.size
            and alt_state[1] < bestR - 1e-14):
        result["alternative"] = alt_state[0]
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth_filter(h, k):
    """Light smoothing to break symmetry / escape flat ridges, then rescale."""
    if k <= 0 or h.size < 2 * k + 1:
        return h
    ker = np.ones(2 * k + 1) / (2 * k + 1)
    hs = np.convolve(h, ker, mode='same')
    return _rescale(np.clip(hs, 0, None))


def _refine(best, bestR, deadline, alt_state):
    for pad in [0.10, 0.06, 0.04, 0.03]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
        elif r2 > alt_state[1]:
            alt_state[0], alt_state[1] = ht2.copy(), r2
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        elif r > alt_state[1]:
            alt_state[0], alt_state[1] = ht.copy(), r
    return best, bestR


