import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    m = L.max()
    if m <= 0:
        return -1.0
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    return num / (s * s * m)


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        return fg(np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _refine(h, deadline, betas, iters, rounds):
    R = _R_of(h)
    for beta in betas:
        if time.process_time() > deadline - 1.0:
            break
        h2 = _lbfgs_all(h, 200, deadline, beta=beta)
        r2 = _R_of(h2)
        if r2 > R:
            h, R = h2, r2
    if time.process_time() < deadline - 1.0:
        h2 = _lbfgs_all(h, iters, deadline)
        r2 = _R_of(h2)
        if r2 > R:
            h, R = h2, r2
    for _ in range(rounds):
        if time.process_time() > deadline - 1.0:
            break
        free = _peak_window(h, tol=0.999, pad_frac=0.3, extra=32)
        h2 = _lbfgs_block(h, free, 300, deadline)
        r2 = _R_of(h2)
        if r2 > R:
            h, R = h2, r2
        else:
            break
    return h, R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or not np.all(np.isfinite(base)) or base.sum() <= 0:
            base = np.ones(64)
    else:
        base = np.ones(64)
    base = _rescale(base)
    start_R = _R_of(base)
    print("start R=%.6f N=%d" % (start_R, base.size))

    best_h = base.copy()
    best_R = start_R

    # KEY CHANGE: refine at the start's native resolution first, then
    # attempt a finer resolution (upsample) and refine there.  Finer grids
    # can capture sharper structure and typically raise R.
    # Stage 1: refine at current resolution.
    cur = base.copy()
    cur_R = start_R
    betas = (6, 12, 24, 48, 96)
    cur, cur_R = _refine(cur, deadline, betas, 400, 3)
    print("stage1 N=%d R=%.6f" % (cur.size, cur_R))
    if cur_R > best_R:
        best_R, best_h = cur_R, cur.copy()

    # Stage 2: try finer resolutions, budget permitting.
    for N_new in (2 * base.size, 4 * base.size):
        if time.process_time() > deadline - 8.0:
            break
        if N_new > 1000000:
            break
        cur2 = _prolongate_mass(best_h, N_new)
        cur2 = _rescale(cur2)
        r2 = _R_of(cur2)
        # refine at new resolution with a shorter beta schedule
        cur2, r2b = _refine(cur2, deadline, (12, 32, 64), 300, 2)
        if r2b > best_R:
            best_R, best_h = r2b, cur2.copy()
            print("stage2 N=%d R=%.6f" % (N_new, best_R))
        else:
            # even if not better, keep the base (finer grid may still help
            # subsequent full-polish below if it was close)
            if r2b > r2:
                print("stage2 N=%d R=%.6f (not best)" % (N_new, r2b))

    # Stage 3: polish at best resolution until budget end.
    cur = best_h.copy()
    cur_R = best_R
    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h2 = _lbfgs_all(cur, 300, deadline)
        r2 = _R_of(h2)
        if r2 > cur_R:
            cur, cur_R = h2, r2
        else:
            free = _peak_window(cur, tol=0.99, pad_frac=0.5, extra=128)
            h2 = _lbfgs_block(cur, free, 400, deadline)
            r2 = _R_of(h2)
            if r2 > cur_R:
                cur, cur_R = h2, r2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur.copy()
        if it % 5 == 0:
            print("  iter %d R=%.6f best=%.6f" % (it, cur_R, best_R))

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None and start_R >= best_R:
        return {"best": base, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

