def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    return _rescale(h)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _detect_staircase(h):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in (64, 32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-12:
            return c, p
    return None, 1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    c0, p = _detect_staircase(best)
    if c0 is None:
        # fall back to base behaviour: just polish
        fd = t0 + budget_seconds * 0.97
        ht = _lbfgs_all_pos(best, 500, fd - 1.5, tie=True)
        if R_of(ht) > bestR + 1e-15:
            best, bestR = ht.copy(), R_of(ht)
        result = {"best": best}
        if bestR <= startR + 1e-14 and start is not None:
            result["alternative"] = best
        return result

    c = c0.copy()
    m = c.size
    print("staircase detected p=%d m=%d" % (p, m))

    def Rc(cc):
        return R_of(cc)

    inc_c = c.copy()
    inc_R = Rc(inc_c)
    print("coarse incumbent R=%.9f" % inc_R)

    # ---- build initial population ----
    def polish_member(cc, iters=120, deadline_local=None):
        if deadline_local is None:
            deadline_local = time.process_time() + 6.0
        h = _lbfgs_all_pos(cc, iters, deadline_local, tie=True)
        if time.process_time() < deadline_local - 0.3:
            win = _peak_window(h, pad_frac=0.10, extra=32)
            h2 = _lbfgs_block(h, win, 60, deadline_local, beta=1e7)
            if Rc(h2) > Rc(h):
                h = h2
        return h

    def perturb_lognormal(cc, sigma):
        out = cc.copy()
        nz = np.flatnonzero(cc > 0)
        if nz.size == 0:
            return out
        frac = rng.uniform(0.2, 0.4)
        k = max(1, int(frac * nz.size))
        sel = rng.choice(nz, size=k, replace=False)
        mult = np.exp(sigma * rng.standard_normal(k))
        out[sel] = out[sel] * mult
        return _rescale(out)

    def perturb_cosine(cc, amp, nterm=8):
        out = cc.copy()
        x = np.linspace(0, np.pi, m)
        env = np.zeros(m)
        for _ in range(nterm):
            f = rng.uniform(1, 12)
            ph = rng.uniform(0, 2 * np.pi)
            env += rng.standard_normal() * np.cos(f * x + ph)
        env = env / (np.std(env) + 1e-12)
        out = out * np.exp(amp * env)
        return _rescale(out)

    def perturb_smooth(cc, width):
        if width <= 0:
            return cc.copy()
        k = np.exp(-0.5 * (np.arange(-3 * width, 3 * width + 1) / width) ** 2)
        k /= k.sum()
        sm = np.convolve(cc, k, mode='same')
        # mass preserving: rescale to original sum
        s0 = cc.sum()
        s1 = sm.sum()
        if s1 > 0:
            sm *= s0 / s1
        return _rescale(sm)

    def perturb_translate(cc, ntrans):
        out = cc.copy()
        nz = np.flatnonzero(cc > 0)
        if nz.size < 2:
            return out
        for _ in range(ntrans):
            i = int(rng.choice(nz))
            j = int(rng.integers(0, m))
            if i == j:
                continue
            out[j] += out[i]
            out[i] = 0.0
        return _rescale(out)

    P = 24
    pop = [inc_c.copy()]
    sigmas = [0.05, 0.1, 0.2, 0.3]
    for i in range(8):
        pop.append(perturb_lognormal(inc_c, sigmas[i % 4]))
    for i in range(6):
        amp = rng.uniform(0.05, 0.3)
        pop.append(perturb_cosine(inc_c, amp))
    for i in range(5):
        w = rng.integers(1, 4)
        pop.append(perturb_smooth(inc_c, int(w)))
    for i in range(4):
        nt = int(rng.integers(5, 16))
        pop.append(perturb_translate(inc_c, nt))
    pop = pop[:P]

    pop_end = t0 + budget_seconds * 0.80
    Rvals = [Rc(x) for x in pop]

    # polish initial population
    for i in range(P):
        if time.process_time() >= pop_end - 2.0:
            break
        dl = min(pop_end - 1.0, time.process_time() + 6.0)
        pop[i] = polish_member(pop[i], 120, dl)
        Rvals[i] = Rc(pop[i])
        if Rvals[i] > inc_R + 1e-15:
            inc_c = pop[i].copy()
            inc_R = Rvals[i]

    gen = 0
    while time.process_time() < pop_end - 3.0:
        gen += 1
        order = np.argsort(-np.array(Rvals))
        top = order[:6]
        # rank weights
        w = np.array([6 - k for k in range(len(top))], dtype=float)
        w /= w.sum()
        children = []
        child_R = []
        beat_parents = 0
        for _ in range(P - 1):
            if time.process_time() >= pop_end - 2.0:
                break
            a = int(rng.choice(top, p=w))
            b = int(rng.choice(top, p=w))
            pa = pop[a]; pb = pop[b]
            mask = rng.random(m) < 0.5
            child = np.where(mask, pa, pb)
            child = _rescale(child)
            dl = min(pop_end - 1.0, time.process_time() + 4.0)
            child = _lbfgs_all_pos(child, 60, dl, tie=True)
            if time.process_time() < dl - 0.3:
                win = _peak_window(child, pad_frac=0.10, extra=32)
                c2 = _lbfgs_block(child, win, 60, dl, beta=1e7)
                if Rc(c2) > Rc(child):
                    child = c2
            rc = Rc(child)
            children.append(child)
            child_R.append(rc)
            if rc > Rvals[a] + 1e-15 and rc > Rvals[b] + 1e-15:
                beat_parents += 1
        if not children:
            break
        # form next generation: keep incumbent + best children
        all_members = [(Rvals[i], pop[i]) for i in range(P)]
        all_members += [(child_R[k], children[k]) for k in range(len(children))]
        all_members.sort(key=lambda t: -t[0])
        newpop = [t[1] for t in all_members[:P]]
        newR = [t[0] for t in all_members[:P]]
        pop, Rvals = newpop, newR
        if Rvals[0] > inc_R + 1e-15:
            inc_c = pop[0].copy()
            inc_R = Rvals[0]
        meanR = float(np.mean(Rvals))
        print("gen=%d best=%.9f mean=%.9f beat_parents=%d inc=%.9f"
              % (gen, Rvals[0], meanR, beat_parents, inc_R))

    # ---- expand and full-N polish ----
    h_full = np.repeat(inc_c, p)
    h_full = _rescale(h_full)
    r_full = R_of(h_full)
    print("expanded R=%.9f (start %.9f)" % (r_full, startR))
    if r_full > bestR + 1e-15:
        best, bestR = h_full.copy(), r_full

    # full-N tie polish
    fd = t0 + budget_seconds * 0.93
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 400, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("full tie ACCEPT R=%.9f" % bestR)

    # peak ladder
    peak_end = t0 + budget_seconds * 0.97
    if time.process_time() < peak_end - 2.0:
        ht = _peak_ladder(best, peak_end - 1.0, pads=(0.06, 0.03),
                          iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _refine(h, deadline, rounds=6):
    """Alternate global tie-aware and peak-window polishing."""
    best = h
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        # tie-aware global
        cand = _lbfgs_all_pos(best, 400, deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
        # beta softening to flatten peak -> then tighten
        for beta in (200.0, 2000.0, 20000.0):
            if time.process_time() >= deadline - 0.5:
                break
            cand = _lbfgs_all_pos(best, 300, deadline, beta=beta)
            r = R_of(cand)
            if r > bestR:
                best, bestR = cand, r
        # window around peak
        if time.process_time() < deadline - 0.5:
            Lf = _knots(best)
            m = int(np.argmax(Lf))
            # map knot index to h index approx m/2 (knots offset by 1)
            c = (m - 1) / 2.0
            n = best.size
            w = max(4, int(0.25 * n))
            lo = max(0, int(c - w))
            hi = min(n, int(c + w) + 1)
            if hi - lo >= 2:
                free = np.arange(lo, hi)
                cand = _lbfgs_block(best, free, 300, deadline, tie=True)
                r = R_of(cand)
                if r > bestR:
                    best, bestR = cand, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.85 * budget_seconds

    best = None
    bestR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.size >= 2 and s.sum() > 0:
            best = s
            bestR = R_of(s)
            print("start R=%.6f N=%d" % (bestR, s.size))

    # Seed: start, or a smooth bump
    if best is None:
        n = 200
        x = (np.arange(n) + 0.5) / n
        h = np.exp(-40.0 * (x - 0.5) ** 2)
        best = _rescale(h)
        bestR = R_of(best)
        print("init bump R=%.6f" % bestR)

    # Phase 1: refine at current size
    b, r = _refine(best, deadline * 0.7 + t0 * 0.3, rounds=4)
    if r > bestR:
        best, bestR = b, r
    print("phase1 R=%.6f N=%d" % (bestR, best.size))

    # Phase 2: try finer resolution (interlace) and refine
    n = best.size
    if n < 200000 and time.process_time() < deadline - 2.0:
        # linear interlace: split each step into two
        h2 = np.zeros(2 * n)
        h2[0::2] = best
        if n > 1:
            h2[1:-1:2] = 0.5 * (best[:-1] + best[1:])
        h2[-1] = best[-1]
        h2 = _rescale(h2)
        r2 = R_of(h2)
        print("interlace R=%.6f N=%d" % (r2, h2.size))
        b2, rr = _refine(h2, deadline, rounds=3)
        if rr > bestR:
            best, bestR = b2, rr
        print("phase2 R=%.6f N=%d" % (bestR, best.size))

    # Phase 3: keep refining until deadline
    while time.process_time() < deadline - 1.0:
        b, r = _refine(best, deadline, rounds=2)
        if r > bestR + 1e-9:
            best, bestR = b, r
            print("phase3 R=%.6f N=%d" % (bestR, best.size))
        else:
            # tiny random perturbation to escape
            noise = 1.0 + 0.01 * np.random.randn(best.size)
            cand = _rescale(np.clip(best * noise, 0, None))
            rc = R_of(cand)
            if rc > bestR:
                best, bestR = cand, rc
            else:
                break

    best = _rescale(np.clip(best, 0, None))
    finalR = R_of(best)
    print("final R=%.6f N=%d" % (finalR, best.size))

    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        sR = R_of(s)
        if sR >= finalR:
            return {"best": s, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1200:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1200:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, tie=False, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    if free is None:
        active = None
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0

    if active is None:
        def f(x):
            hh = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g
        x0 = h.copy()
        nb = n
    else:
        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g[active]
        x0 = h[active].copy()
        nb = active.size

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    if active is None:
        return _rescale(np.clip(res.x, 0.0, None))
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _prolongate(h, n_new):
    r0 = R_of(h)
    rep = n_new // len(h)
    if rep >= 1 and rep * len(h) == n_new:
        cand = np.repeat(h, rep)
        cand = _rescale(cand)
        if R_of(cand) >= r0 - 1e-6:
            return cand
    cand = _prolong(h, n_new)
    cand = _rescale(cand)
    return cand


def _peak_window(h, tol=0.9995, pad_frac=0.3, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size, hi + pad)
    return np.arange(lo, hi)


def _cycle(cur, cur_R, best, best_R, deadline, betas, windows,
           it_beta=60, it_win=100, it_sharp=80, tag="", beta_cap=None):
    for beta in betas:
        now = time.process_time()
        if now >= deadline - 0.5:
            break
        if beta_cap is not None and now >= beta_cap:
            break
        cand = _lbfgs(cur, it_beta, deadline, beta=beta)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand; cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy(); best_R = r
        print(f"  {tag} beta={beta:.0e} R={cur_R:.6f} best={best_R:.6f}")
    for win in windows:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(cur, tol=win)
        cand = _lbfgs(cur, it_win, deadline, free=free)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand; cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy(); best_R = r
        print(f"  {tag} win={win} R={cur_R:.6f} best={best_R:.6f}")
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs(cur, it_sharp, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand; cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy(); best_R = r
        print(f"  {tag} sharp R={cur_R:.6f} best={best_R:.6f}")
    return cur, cur_R, best, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None; best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy(); best_R = R_of(best)

    if best is None:
        best = np.ones(1024); best_R = R_of(best)

    cur = best.copy(); cur_R = best_R

    # Prolongate to at least 131072.
    if len(cur) < 131072:
        cand = _prolongate(cur, 131072)
        r = R_of(cand)
        print(f"prolongate 131072: R {cur_R:.6f} -> {r:.6f}")
        cand = _lbfgs(cand, 200, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R - 1e-9:
            cur = cand; cur_R = r
            if r > best_R:
                best = cand.copy(); best_R = r
        print(f"after prolong N={len(cur)} R={cur_R:.6f}")

    # Phase 1: sharpening cycles at 131072 (betas + tie + peak windows).
    betas1 = [1e6, 1e7, 1e8, 1e9]
    wins1 = [0.9999, 0.999, 0.99, 0.95]
    for c in range(2):
        if time.process_time() >= deadline - 25.0:
            break
        prev = cur_R
        cur, cur_R, best, best_R = _cycle(cur, cur_R, best, best_R,
                                          deadline, betas1, wins1,
                                          it_beta=50, it_win=80, it_sharp=60,
                                          tag=f"p1c{c+1}")
        # tie-mode polish
        if time.process_time() < deadline - 20.0:
            cand = _lbfgs(cur, 60, deadline, tie=True)
            r = R_of(cand)
            if r > cur_R + 1e-12:
                cur = cand; cur_R = r
                if r > best_R:
                    best = cand.copy(); best_R = r
        print(f"phase1 cycle {c+1}: cur={cur_R:.6f} best={best_R:.6f} gain={cur_R-prev:.2e}")

    # Phase 2: prolongate to 262144 and refine.
    if len(cur) < 262144 and time.process_time() < deadline - 20.0:
        r_before = cur_R
        cand = _prolongate(cur, 262144)
        r_after = R_of(cand)
        print(f"prolongate 262144: R {r_before:.6f} -> {r_after:.6f}")
        cand = _lbfgs(cand, 150, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R - 1e-9:
            cur = cand; cur_R = r
            if r > best_R:
                best = cand.copy(); best_R = r
        print(f"after prolong N={len(cur)} R={cur_R:.6f}")

        betas2 = [1e7, 1e8, 1e9, 1e10]
        wins2 = [0.9999, 0.999, 0.99]
        for c in range(2):
            if time.process_time() >= deadline - 6.0:
                break
            prev = cur_R
            cur, cur_R, best, best_R = _cycle(cur, cur_R, best, best_R,
                                              deadline, betas2, wins2,
                                              it_beta=40, it_win=60, it_sharp=50,
                                              tag=f"p2c{c+1}")
            print(f"phase2 cycle {c+1}: cur={cur_R:.6f} best={best_R:.6f} gain={cur_R-prev:.2e}")

    # Final polish.
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs(best, 500, deadline, beta=0.0)
        r = R_of(cand)
        if r > best_R:
            best = cand; best_R = r
        print(f"final polish R={best_R:.6f}")

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={best_R:.6f} N={len(best)}")

    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_R = R_of(s)

    if best_R >= start_R:
        return best
    return {"best": np.asarray(start, dtype=float), "alternative": best}

