            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    alt = best.copy()
    alt_r = best_r

    # 1) mirror symmetrisation: R is invariant to reversing f, so f+reverse
    #    has a symmetric autoconvolution. Try at doubled resolution.
    if time.process_time() < deadline - 30.0:
        hm = _mirror(best)
        hm = _rescale(hm)
        hm = _lbfgs_log(hm, maxiter=1500,
                        deadline=min(deadline, time.process_time() + 20.0))
        rm = R_of(hm)
        if rm > alt_r + 1e-9:
            alt, alt_r = hm, rm
        if rm > best_r + 1e-9:
            best, best_r = hm.copy(), rm

    # 2) coarse-to-fine polish of the working best
    cur = best.copy()
    cur_r = best_r
    n_cur = cur.size
    for Nc in [max(64, n_cur // 16), max(128, n_cur // 8),
               max(256, n_cur // 4), max(512, n_cur // 2)]:
        if time.process_time() >= deadline - 4.0:
            break
        if Nc >= cur.size:
            continue
        hc = _coarse(cur, Nc)
        hc = _rescale(hc)
        hc = _lbfgs_log(hc, maxiter=1200,
                        deadline=min(deadline, time.process_time() + 4.0))
        hf = _prolongate(hc, cur.size)
        hf = _smooth_conv(hf, 2)
        hf = _rescale(hf)
        hf = _lbfgs_log(hf, maxiter=800, deadline=deadline)
        r = R_of(hf)
        if r > cur_r + 1e-9:
            cur, cur_r = hf, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # 3) grow N and polish (capped to keep cost manageable)
    N = cur.size
    while time.process_time() < deadline - 4.0 and N < 400000:
        N = min(400000, max(N * 2, N + 50))
        if N <= cur.size:
            break
        cand = _prolongate(cur, N)
        cand = _smooth_conv(cand, 2)
        cand = _rescale(cand)
        cand = _lbfgs_log(cand, maxiter=2500, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if r <= best_r - 1e-6 and N > 4000:
            break

    # 4) peak-window polishing with a soft-max (beta>0) to break the tie
    #    among near-maximal knots and expose more of the peak structure.
    for beta, frac, extra in [(200.0, 0.5, 4), (200.0, 0.25, 4),
                              (500.0, 0.1, 4), (1000.0, 0.05, 4)]:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish_peak(cur, deadline, frac, extra,
                                   maxiter=800, beta=beta)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    # 5) final full polish
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(best, maxiter=3000, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            rs = R_of(s)
            if rs >= best_r:
                if alt is not None and alt_r > rs:
                    return {"best": alt, "alternative": s}
                return {"best": best, "alternative": s}
    if alt is not None and alt_r > best_r and alt.size != best.size:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


# ---------- staircase detection (p order per experiment) ----------

def _detect_staircase(h, periods=(64, 32, 16, 8, 4, 2)):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in periods:
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-10:
            return c, p
    return None, 1


def _Rc(c, p):
    return R_of(np.repeat(c, p))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    c, p = _detect_staircase(best)
    have_stair = False
    if c is not None:
        rc = _Rc(c, p)
        if abs(rc - R_of(best)) < 1e-12:
            have_stair = True
            print("staircase detected p=%d m=%d" % (p, c.size))

    if not have_stair:
        # Fallback: only peak ladder on h
        peak_end = t0 + budget_seconds * 0.85
        ht = _peak_ladder(best, peak_end - 1.0,
                          pads=(0.10, 0.06, 0.04, 0.03), iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        fd = t0 + budget_seconds * 0.97
        if time.process_time() < fd - 3.0:
            h_t = _lbfgs_all_pos(best, 500, fd - 1.5, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
        print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))
        result = {"best": best}
        if bestR <= startR + 1e-14 and start is not None:
            result["alternative"] = best
        return result

    # ---- Permutation search on coarse c ----
    m = c.size
    c = c.copy()
    Rc_best = _Rc(c, p)
    best_c = c.copy()
    best_h = np.repeat(c, p)
    bestR = R_of(best_h)
    if bestR < startR:
        best_h = _rescale(np.asarray(start, dtype=float))
        bestR = startR

    perm_end = t0 + budget_seconds * 0.55
    anneal_end = t0 + budget_seconds * 0.25

    # top-30% indices by height
    order = np.argsort(-c)
    top30 = order[:max(1, int(0.30 * m))]

    hist = {"swap": 0, "block": 0, "shift": 0}
    n_prop = 0
    n_acc = 0
    n_acc_total = 0
    T0 = 3e-7
    last_print = 0

    def try_move(cand):
        return _Rc(cand, p)

    while time.process_time() < perm_end - 2.0:
        n_prop += 1
        # choose move type
        u = rng.random()
        cand = c.copy()
        mtype = None
        if u < 0.45:
            # swap c[i] with top-30% j
            i = int(rng.integers(0, m))
            j = int(top30[rng.integers(0, top30.size)])
            if i == j:
                continue
            cand[i], cand[j] = cand[j], cand[i]
            mtype = "swap"
        elif u < 0.80:
            # block interchange
            L = int(rng.integers(2, 65))
            if 2 * L >= m:
                continue
            i = int(rng.integers(0, m - L + 1))
            j = int(rng.integers(0, m - L + 1))
            if abs(i - j) < L:
                continue
            bi = cand[i:i + L].copy()
            bj = cand[j:j + L].copy()
            cand[i:i + L] = bj
            cand[j:j + L] = bi
            mtype = "block"
        else:
            # cyclic shift of a run
            L = int(rng.integers(2, 129))
            if L >= m:
                continue
            i = int(rng.integers(0, m - L + 1))
            seg = cand[i:i + L].copy()
            cand[i:i + L] = np.roll(seg, 1)
            mtype = "shift"

        Rnew = try_move(cand)
        accept = False
        if Rnew > Rc_best + 1e-15:
            accept = True
        elif time.process_time() < anneal_end:
            T = T0 * max(0.0, 1.0 - (time.process_time() - t0) /
                         max(1e-9, anneal_end - t0))
            if T > 0 and rng.random() < np.exp((Rnew - Rc_best) / T):
                accept = True
        if accept:
            c = cand
            Rc_best = Rnew
            n_acc += 1
            n_acc_total += 1
            hist[mtype] += 1
            if Rc_best > _Rc(best_c, p) + 1e-16:
                best_c = c.copy()
            # coarse peak-window L-BFGS
            if time.process_time() < perm_end - 3.0:
                Lf = _knots(c)
                mx = Lf.max()
                if mx > 0:
                    idx = np.flatnonzero(Lf >= 0.9995 * mx)
                    lo = max(0, idx.min() - 1)
                    hi = min(m - 1, idx.max())
                    pad = max(16, int(0.10 * m))
                    lo = max(0, lo - pad)
                    hi = min(m - 1, hi + pad)
                    win = np.arange(lo, hi + 1)
                    c2 = _lbfgs_block(c, win, 150,
                                      min(perm_end - 2.0,
                                          time.process_time() + 3.0),
                                      beta=1e7)
                    r2 = _Rc(c2, p)
                    if r2 > Rc_best + 1e-16:
                        c = c2
                        Rc_best = r2
                        if Rc_best > _Rc(best_c, p) + 1e-16:
                            best_c = c.copy()
            # every 10th acceptance: full-N peak ladder
            if n_acc_total % 10 == 0 and time.process_time() < perm_end - 4.0:
                hh = np.repeat(c, p)
                hh = _peak_ladder(hh,
                                  min(perm_end - 2.0,
                                      time.process_time() + 5.0),
                                  pads=(0.10, 0.04), iters=200, tie=True)
                rh = R_of(hh)
                if rh > bestR + 1e-15:
                    best_h = hh.copy()
                    bestR = rh
                    # re-derive coarse from improved h if still staircase
                    c3, p3 = _detect_staircase(best_h)
                    if c3 is not None and p3 == p:
                        c = c3.copy()
                        Rc_best = _Rc(c, p)
                        if Rc_best > _Rc(best_c, p) + 1e-16:
                            best_c = c.copy()

        if n_prop - last_print >= 500:
            last_print = n_prop
            rh = R_of(np.repeat(c, p))
            print("prop=%d acc=%d Rc=%.9f R_h=%.9f bestR=%.9f hist=%s"
                  % (n_prop, n_acc, Rc_best, rh, bestR,
                     "swap=%d block=%d shift=%d"
                     % (hist["swap"], hist["block"], hist["shift"])))

    # adopt best coarse if better
    hh = np.repeat(best_c, p)
    rh = R_of(hh)
    if rh > bestR + 1e-15:
        best_h = hh
        bestR = rh

    # ---- Final polish: last 15% ----
    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 4.0:
        ht = _peak_ladder(best_h,
                          min(fd - 1.0, time.process_time() + 6.0),
                          pads=(0.06, 0.03), iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best_h, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best_h, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best_h, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best_h)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best_h, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best_h, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)

    if bestR < startR:
        best_h = _rescale(np.asarray(start, dtype=float))
        bestR = startR

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, "
          "ties=%d, props=%d, acc=%d, hist swap=%d block=%d shift=%d)"
          % (bestR, startR, best_h.size, _zero_frac(best_h),
             _nearmax_frac(best_h), _tie_count(best_h),
             n_prop, n_acc, hist["swap"], hist["block"], hist["shift"]))

    result = {"best": best_h}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best_h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


# ---------- NEW: multi-resolution resampling polish ----------
# The pure gradient stalls because equal-height knots around the peak form a
# flat plateau. Coarsening (block-average) the current shape, optimizing the
# low-dimensional proxy, then refining back, lets the shape escape plateaus
# that per-knot L-BFGS cannot. This is the substantial change.

def _coarsen(h, m):
    N = h.size
    if m >= N:
        return h.copy(), N
    idx = np.linspace(0, N, m + 1).astype(int)
    out = np.empty(m)
    for i in range(m):
        a, b = idx[i], idx[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out, N


def _refine_back(hc, N):
    m = hc.size
    x = np.linspace(0, m - 1, N)
    return np.interp(x, np.arange(m), hc)


def _multires_polish(h, deadline, levels=(512, 1024, 2048, 4096, 8192),
                     iters=150):
    best = h
    bestR = R_of(h)
    for m in levels:
        if time.process_time() >= deadline - 0.6:
            break
        hc, N = _coarsen(best, m)
        hc = _rescale(hc)
        for beta in (1e6, 1e7):
            if time.process_time() >= deadline - 0.6:
                break
            hc2 = _lbfgs_all_pos(hc, iters, deadline - 0.4, beta=beta)
            if R_of(hc2) > R_of(hc):
                hc = hc2
        hc = _lbfgs_all_pos(hc, iters, deadline - 0.4, tie=True)
        hf = _refine_back(hc, N)
        hf = _rescale(hf)
        r = R_of(hf)
        if r > bestR + 1e-15:
            best, bestR = hf, r
    return best


def _block_refine(h, deadline, nblocks, iters_per=120, overlap=0.15):
    N = h.size
    if N < 8:
        return h
    edges = np.linspace(0, N, nblocks + 1).astype(int)
    ov = max(1, int(N / nblocks * overlap))
    order = list(range(nblocks))
    Lf = _knots(h)
    mx = Lf.max()
    impact = []
    for b in order:
        lo = edges[b]; hi = edges[b + 1]
        klo = lo; khi = min(Lf.size, hi + 2)
        impact.append(np.sum(np.abs(Lf[klo:khi] - mx)))
    order = [b for _, b in sorted(zip(impact, order), reverse=True)]
    for b in order:
        if time.process_time() > deadline - 0.5:
            break
        lo = max(0, edges[b] - ov)
        hi = min(N, edges[b + 1] + ov)
        win = np.arange(lo, hi)
        ht = _lbfgs_block(h, win, iters_per, deadline - 0.4, beta=1e6)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
        if time.process_time() > deadline - 0.5:
            break
        ht = _lbfgs_block(h, win, iters_per, deadline - 0.4, tie=True)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)

    startR = R_of(best)
    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt = None
    altR = -1.0

    # Phase 0: the new idea — multi-resolution resampling polish
    ph0 = t0 + budget_seconds * 0.40
    ht = _multires_polish(best.copy(), ph0)
    r = R_of(ht)
    if r > bestR + 1e-15:
        best, bestR = ht.copy(), r
        print("P0 multires R=%.9f" % bestR)
    else:
        alt, altR = ht.copy(), r

    # Phase 1: global L-BFGS to settle
    ph1 = t0 + budget_seconds * 0.55
    if time.process_time() < ph1 - 1.0:
        ht = _lbfgs_all_pos(best, 300, ph1 - 0.5, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P1 global R=%.9f" % bestR)

    # Phase 2: block refinement
    ph2 = t0 + budget_seconds * 0.70
    for nb in (32, 64, 96, 128):
        if time.process_time() > ph2 - 1.5:
            break
        ht = _block_refine(best.copy(), ph2, nb, iters_per=100)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P2 block nb=%d R=%.9f" % (nb, bestR))
        elif alt is None or r > altR:
            alt, altR = ht.copy(), r

    # Phase 3: peak ladder
    ph3 = t0 + budget_seconds * 0.80
    if time.process_time() < ph3 - 1.5:
        ht = _peak_ladder(best.copy(), ph3 - 0.5,
                          pads=(0.10, 0.06, 0.04, 0.02), iters=200)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P3 peak R=%.9f" % bestR)

    # Phase 4: second multi-resolution pass — the new idea applied again
    ph4 = t0 + budget_seconds * 0.88
    if time.process_time() < ph4 - 1.5:
        ht = _multires_polish(best.copy(), ph4,
                              levels=(1024, 2048, 4096, 8192, 16384),
                              iters=120)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P4 multires2 R=%.9f" % bestR)
        elif alt is None or r > altR:
            alt, altR = ht.copy(), r

    # Phase 5: final global polish
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 1.5:
        ht = _lbfgs_all_pos(best, 400, fd - 0.5, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P5 final R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt is not None and altR > startR + 1e-15 and bestR <= startR + 1e-14:
        result["alternative"] = alt
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    return _rescale(h)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _coarsen(h, p):
    n = h.size
    m = n // p
    if m < 2:
        return None, 1
    c = h[:m * p].reshape(m, p).mean(axis=1)
    return c, p


def _refine_multiscale(h, deadline, rng):
    """Coarsen, re-optimize at low N, then upsample and polish."""
    best = h.copy()
    bestR = R_of(best)
    for p in (2, 3, 4):
        if time.process_time() > deadline - 2.0:
            break
        c, p_ = _coarsen(h, p)
        if c is None:
            continue
        # optimize coarse with soft-max + tie
        ct = _lbfgs_all_pos(c, 300, min(deadline - 1.0,
                                        time.process_time() + 2.0), beta=1e5)
        ct = _lbfgs_all_pos(ct, 300, min(deadline - 1.0,
                                         time.process_time() + 2.0), tie=True)
        # upsample
        up = np.repeat(ct, p)
        up = _rescale(up)
        r_up = R_of(up)
        # polish upsampled
        up = _peak_ladder(up, min(deadline - 0.5,
                                  time.process_time() + 4.0),
                          pads=(0.10, 0.05), iters=250)
        up = _lbfgs_all_pos(up, 400, min(deadline - 0.3,
                                         time.process_time() + 3.0), tie=True)
        r_up = R_of(up)
        if r_up > bestR + 1e-15:
            best, bestR = up.copy(), r_up
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.97

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(999)

    # Phase 1: multiscale coarsen/refine (first 45% of budget)
    ms_end = t0 + budget_seconds * 0.45
    h_ms, r_ms = _refine_multiscale(best, ms_end, rng)
    if r_ms > bestR + 1e-15:
        best, bestR = h_ms, r_ms
        print("multiscale ACCEPT R=%.9f" % bestR)
    else:
        print("multiscale no gain (%.9f vs %.9f)" % (r_ms, bestR))

    # Phase 2: aggressive soft-max + tie ladder on peak window (next 30%)
    sm_end = t0 + budget_seconds * 0.78
    for beta in (1e2, 1e3, 1e4, 1e5, 1e6, 1e7):
        if time.process_time() > sm_end - 1.0:
            break
        win = _peak_window(best, pad_frac=0.08, extra=128)
        ht = _lbfgs_block(best, win, 300,
                          min(sm_end - 0.5, time.process_time() + 2.0),
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("softmax beta=%.0e ACCEPT R=%.9f" % (beta, bestR))

    # Phase 3: full tie polish (remaining time)
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 500, min(deadline - 0.5,
                                           time.process_time() + 5.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("tie polish ACCEPT R=%.9f" % bestR)

    if time.process_time() < deadline - 0.5:
        ht = _peak_ladder(best, deadline - 0.2,
                          pads=(0.05, 0.03), iters=300)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("final ladder ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return 0.0, 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    den = s * s * (mx if mx > 0 else 1.0)
    if den <= 0:
        return 0.0, mx
    return num / den, mx


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta))
    cb = _make_cb(deadline - 0.2)

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _report(tag, h):
    R, mx = R_of(h)
    L = _conv(np.maximum(h, 0.0))
    if L.max() > 0:
        near = np.mean(L >= 0.99 * L.max())
        am = float(np.argmax(L)) / max(1, 2 * len(h) - 2)
    else:
        near = 0.0
        am = 0.0
    print("%s: R=%.6f N=%d zero_frac=%.3f max/mean=%.2f near_max=%.3f argmax=%.3f" % (
        tag, R, len(h), np.mean(np.asarray(h) <= 0),
        np.max(h) / (np.mean(h) + 1e-12), near, am))
    return R


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    M = len(h)
    if M == N:
        return h.copy()
    edges = np.linspace(0, M, N + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))

    def cum_at(x):
        i = np.floor(x).astype(int)
        i = np.clip(i, 0, M - 1)
        frac = x - i
        return cum[i] + frac * h[i]

    mass = cum_at(edges[1:]) - cum_at(edges[:-1])
    cellw = M / N
    out = mass / cellw
    return np.maximum(out, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()

    def elapsed():
        return time.process_time() - t0

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float), 0.0)
        if s.sum() > 0:
            R, _ = R_of(s)
            best_h = s.copy()
            best_R = R
            print("Start: R=%.6f N=%d" % (R, len(s)))

    if best_h is None:
        N0 = 4096
        x = np.linspace(0, 1, N0)
        best_h = np.sin(np.pi * x) ** 0.5
        best_R, _ = R_of(best_h)

    N = len(best_h)
    print("Working N=%d start R=%.6f" % (N, best_R))

    # Stage 1: directly optimize R with softmax-of-knots objective (beta ladder).
    # This differs from the original's target-projection approach: it directly
    # maximizes R using the smooth surrogate of ||f*f||_inf.
    deadline1 = 0.55 * budget_seconds
    h = best_h.copy()
    betas = (20.0, 80.0, 300.0, 1000.0, 3000.0, 10000.0)
    for beta in betas:
        if elapsed() > deadline1:
            break
        dl = min(deadline1, elapsed() + 0.08 * budget_seconds)
        h2 = _lbfgs(h, 400, dl, beta=beta)
        R2, _ = R_of(h2)
        R1, _ = R_of(h)
        if R2 > R1:
            h = h2
        _report("Stage1 beta=%.0f" % beta, h)
        if R_of(h)[0] > best_R:
            best_R, best_h = R_of(h)[0], h.copy()

    # Stage 2: hard-max (beta -> inf) polish.
    deadline2 = 0.85 * budget_seconds
    if elapsed() < deadline2:
        dl = deadline2
        h2 = _lbfgs(h, 800, dl, beta=1e5)
        R2, _ = R_of(h2)
        _report("Stage2 hardmax", h2)
        if R2 > best_R:
            best_R = R2
            best_h = h2.copy()
            h = h2

    # Stage 3: upsample to 2x and polish to capture finer structure.
    deadline3 = 0.97 * budget_seconds
    if elapsed() < deadline3:
        Nup = min(2 * N, 1000000)
        hu = _resample(best_h, Nup)
        dl = min(deadline3, elapsed() + 0.10 * budget_seconds)
        hu = _lbfgs(hu, 400, dl, beta=3000.0)
        Ru, _ = R_of(hu)
        _report("Stage3 upsample N=%d" % Nup, hu)
        if Ru > best_R:
            best_R = Ru
            best_h = hu.copy()
        # then hardmax polish at new size
        if elapsed() < deadline3:
            hu2 = _lbfgs(hu, 400, deadline3, beta=1e5)
            Ru2, _ = R_of(hu2)
            _report("Stage3 hardmax", hu2)
            if Ru2 > best_R:
                best_R = Ru2
                best_h = hu2.copy()

    best_h = np.maximum(np.asarray(best_h, dtype=float), 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(N)
    if len(best_h) > 1000000:
        best_h = _resample(best_h, 1000000)
    Rf = _report("FINAL", best_h)

    result = {"best": best_h}
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float), 0.0)
        if s.sum() > 0:
            Rs, _ = R_of(s)
            if Rs > Rf:
                result["best"] = s
                result["alternative"] = best_h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prune(h, q):
    h = np.clip(h, 0, None).copy()
    pos = np.flatnonzero(h > 0)
    npos = pos.size
    if npos == 0:
        return _rescale(h)
    k = int(q * npos)
    if k <= 0:
        return _rescale(h)
    if k >= npos:
        k = npos - 1
    vals = h[pos]
    order = np.argsort(vals)
    h[pos[order[:k]]] = 0.0
    return _rescale(h)


def _refine(h, free_mask, deadline, rounds=3, beta_final=1e9):
    """Smoothing continuation: beta 1e3 -> 1e6 -> 1e9 over the free set."""
    for beta in (1e3, 1e6, beta_final):
        if time.process_time() >= deadline - 0.3:
            break
        h = _lbfgs_block(h, free_mask, maxiter=400, deadline=deadline, beta=beta)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: global polish
    if time.process_time() < deadline - 5.0:
        h_try = _lbfgs_all_pos(best, 2000, deadline - 3.0)
        r = R_of(h_try)
        if r > bestR:
            best, bestR = h_try.copy(), r
            print("global polish R=%.7f" % bestR)

    # Phase B: continuation refinement on peak window
    if time.process_time() < deadline - 4.0:
        n = best.size
        for frac, extra in [(2.0, 512), (1.0, 256), (0.5, 128), (0.25, 64)]:
            if time.process_time() >= deadline - 3.0:
                break
            lo, hi = _peak_region(best)
            span = hi - lo
            pad = max(extra, int(span * frac))
            lo = max(0, lo - pad)
            hi = min(n - 1, hi + pad)
            free = np.arange(lo, hi + 1)
            h_try = _refine(best, free, deadline - 2.0)
            r = R_of(h_try)
            if r > bestR + 1e-14:
                best, bestR = h_try.copy(), r
                print("window frac=%.2f R=%.7f" % (frac, bestR))

    # Phase C: prune + regrow with continuation
    qs = [0.01, 0.03, 0.08, 0.15, 0.25]
    rng = np.random.RandomState(12345)
    pass_no = 0
    while time.process_time() < deadline - 2.0:
        pass_no += 1
        order = list(qs)
        rng.shuffle(order)
        for q in order:
            if time.process_time() >= deadline - 2.0:
                break
            hp = _prune(best, q)
            pruned_pos = np.flatnonzero((best > 0) & (hp <= 0))
            hp = _lbfgs_all_pos(hp, 1200, deadline - 2.0, beta=1e4)
            if time.process_time() >= deadline - 2.0:
                break
            hp = _lbfgs_all_pos(hp, 800, deadline - 2.0, beta=0.0)
            if time.process_time() >= deadline - 2.0:
                break
            hp = _window_polish_peak(hp, deadline - 2.0, 0.25, 128,
                                     maxiter=300, beta=1e8)
            r = R_of(hp)
            revived = int(np.sum(hp[pruned_pos] > 0)) if pruned_pos.size else 0
            zf = 100.0 * np.mean(hp <= 0)
            print("prune pass=%d q=%.2f R=%.7f revived=%d/%d zeros=%.1f%% best=%.7f"
                  % (pass_no, q, r, revived, pruned_pos.size, zf, bestR))
            if r > bestR + 1e-13:
                best, bestR = hp.copy(), r
                print("  ACCEPT q=%.2f new best=%.7f" % (q, bestR))

    # Final aggressive polish
    if time.process_time() < deadline - 1.0:
        hf = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf
        hf = _window_polish_peak(best, deadline - 0.3, 0.5, 128, maxiter=400)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

