                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, deadline, betas=(1e6, 1e7), ties=(False, True), maxiter=300):
    """Short multi-pass polish; returns best found."""
    best = h.copy()
    bestR = R_of(best)
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(best, maxiter, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR:
            best, bestR = ht, r
    for tie in ties:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(best, maxiter, deadline - 0.3, beta=0.0, tie=tie)
        r = R_of(ht)
        if r > bestR:
            best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase A: aggressive multi-scale polish of start ----
    # This is the key change: exhaust the direct local search on start first.
    polish_stop = t0 + budget_seconds * 0.35
    if time.process_time() < polish_stop - 1.0:
        ht, r = _polish(best, polish_stop,
                        betas=(1e5, 1e6, 1e7), ties=(False, True), maxiter=400)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, 'polish'
            print("polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht, r

    # Peak-window polish at several widths
    peak_stop = t0 + budget_seconds * 0.50
    for pad in [0.20, 0.12, 0.08, 0.05, 0.03]:
        if time.process_time() >= peak_stop - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        for beta in (1e7, 0.0):
            if time.process_time() >= peak_stop - 0.5:
                break
            ht = _lbfgs_block(best, win, 400, peak_stop - 0.3, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht, r, origin + '+pk'
                print("peak pad=%.2f beta=%g NEW BEST R=%.9f" % (pad, beta, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht, r

    # ---- Phase B: interlace/lift rounds with more time ----
    interlace_stop = t0 + budget_seconds * 0.80
    alphas = [0.5, 0.25, 0.125, 0.0625, 0.375]
    il_round = 0
    while il_round < 5 and time.process_time() < interlace_stop - 3.0:
        alpha = alphas[il_round % len(alphas)]
        slice_dl = min(interlace_stop,
                       time.process_time() + 0.10 * budget_seconds)
        n = best.size
        left = np.concatenate(([0.0], best[:-1]))
        right = np.concatenate((best[1:], [0.0]))
        h2 = np.zeros(2 * n)
        h2[0::2] = best
        h2[1::2] = alpha * (left + right)
        h2 = _rescale(h2)
        r2_start = R_of(h2)
        ht2, r2 = _polish(h2, slice_dl, betas=(1e5, 1e6, 1e7),
                          ties=(False,), maxiter=300)
        # downsample
        h1 = 0.5 * (ht2[0::2] + ht2[1::2])
        h1 = _rescale(h1)
        ht1, r1 = _polish(h1, slice_dl, betas=(1e6, 1e7),
                          ties=(False, True), maxiter=300)
        print("interlace %d alpha=%.3f: 2N %.9f->%.9f, down=%.9f (best %.9f)"
              % (il_round, alpha, r2_start, r2, r1, bestR))
        if r1 > bestR + 1e-13:
            best, bestR, origin = ht1, r1, 'interlace%d' % il_round
            print("interlace NEW BEST R=%.9f" % bestR)
        elif r1 > alt_bestR:
            alt_best, alt_bestR = ht1, r1
        il_round += 1

    # ---- Phase C: final full polish with all beta/tie variants ----
    final_stop = deadline - 0.5
    if time.process_time() < final_stop - 1.0:
        ht, r = _polish(best, final_stop,
                        betas=(1e7, 1e6, 0.0), ties=(True, False), maxiter=400)
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, origin + '+final'
            print("final NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht, r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad):
    """Return free indices in a window around the peak of f*f."""
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    c = (m - 1) / 2.0
    n = h.size
    w = max(3, int(pad * n))
    lo = max(0, int(c - w))
    hi = min(n, int(c + w) + 1)
    if hi - lo < 2:
        return np.arange(n)
    return np.arange(lo, hi)


def _upsample(h, N2):
    N1 = h.size
    if N1 == N2:
        return h.copy()
    x1 = np.linspace(0.0, 1.0, N1)
    x2 = np.linspace(0.0, 1.0, N2)
    return np.interp(x2, x1, h)


def _perturb(h, s, k):
    n = h.size
    idx = np.arange(n)
    E = np.cos(2.0 * np.pi * k * (idx + 0.5) / n)
    return _rescale(np.clip(h * (1.0 + s * E), 0.0, None))


def _level_refine(h, deadline):
    """Run stages (a)-(d) at one resolution level."""
    best = h
    bestR = R_of(best)

    def time_left():
        return time.process_time() < deadline

    # (a) tie-aware full L-BFGS
    if time_left():
        cand = _lbfgs_all_pos(best, 150, deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
        print("  (a) R=%.6f N=%d" % (bestR, best.size))

    # (b) beta ladder
    for beta in (1e3, 1e5, 1e7):
        if not time_left():
            break
        cand = _lbfgs_all_pos(best, 100, deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    print("  (b) R=%.6f" % bestR)

    # (c) peak-window block polish
    for pad in (0.15, 0.10, 0.06, 0.04):
        if not time_left():
            break
        free = _peak_window(best, pad)
        cand = _lbfgs_block(best, free, 150, deadline, beta=1e7)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
        if not time_left():
            break
        cand = _lbfgs_block(best, free, 150, deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    print("  (c) R=%.6f" % bestR)

    # (d) repeat (a)+(c) with perturbations
    trial = 0
    while time_left() and trial < 12:
        trial += 1
        improved = False
        if time_left():
            cand = _lbfgs_all_pos(best, 100, deadline, tie=True)
            r = R_of(cand)
            if r > bestR:
                best, bestR = cand, r
                improved = True
        if time_left():
            free = _peak_window(best, 0.04)
            cand = _lbfgs_block(best, free, 100, deadline, tie=True)
            r = R_of(cand)
            if r > bestR:
                best, bestR = cand, r
                improved = True
        if improved:
            continue
        # try a perturbation
        s = 0.02 + 0.13 * np.random.rand()
        k = 1 + int(np.random.rand() * 3)
        cand = _perturb(best, s, k)
        rc = R_of(cand)
        if rc > bestR:
            # polish it
            cand = _lbfgs_all_pos(cand, 100, deadline, tie=True)
            rc = R_of(cand)
            if rc > bestR:
                best, bestR = cand, rc
                continue
        # no gain: stop (d)
        break
    print("  (d) R=%.6f" % bestR)
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.85 * budget_seconds

    best = None
    bestR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.size >= 2 and s.sum() > 0:
            best = s
            bestR = R_of(s)
            print("start R=%.6f N=%d" % (bestR, s.size))

    if best is None:
        n = 100
        x = (np.arange(n) + 0.5) / n
        h = np.exp(-40.0 * (x - 0.5) ** 2)
        best = _rescale(h)
        bestR = R_of(best)
        print("init bump R=%.6f" % bestR)

    # Resolution ladder
    ladder = [200, 400, 800, 1600, 3200]
    for N2 in ladder:
        if time.process_time() >= deadline - 2.0:
            break
        if N2 <= best.size:
            continue
        cand = _rescale(_upsample(best, N2))
        rc = R_of(cand)
        if rc >= bestR - 1e-9:
            best, bestR = cand, rc
        else:
            # keep previous level; still try refining it
            pass
        print("level N=%d R=%.6f" % (best.size, bestR))
        b, r = _level_refine(best, deadline)
        if r > bestR:
            best, bestR = b, r
        print("level done N=%d R=%.6f" % (best.size, bestR))

    # Final polishing
    final_deadline = t0 + 0.95 * budget_seconds
    while time.process_time() < final_deadline - 1.0:
        free = _peak_window(best, 0.02)
        cand = _lbfgs_block(best, free, 150, final_deadline, tie=True)
        r = R_of(cand)
        if r > bestR + 1e-10:
            best, bestR = cand, r
            print("final pad0.02 R=%.6f N=%d" % (bestR, best.size))
        else:
            cand = _lbfgs_all_pos(best, 150, final_deadline, tie=True)
            r = R_of(cand)
            if r > bestR + 1e-10:
                best, bestR = cand, r
                print("final full R=%.6f N=%d" % (bestR, best.size))
            else:
                break

    best = _rescale(np.clip(best, 0, None))
    finalR = R_of(best)
    print("final R=%.6f N=%d" % (finalR, best.size))

    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        sR = R_of(s)
        if sR >= finalR:
            return {"best": s, "alternative": best}
    return best

