    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, deadline, betas=(1e5, 1e6, 1e7), pad_fracs=(0.08, 0.04)):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        h = _lbfgs_all_pos(h, 300, deadline - 0.3, beta=beta)
    for pad in pad_fracs:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        h = _lbfgs_block(h, win, 400, deadline - 0.3, beta=1e7)
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_all_pos(h, 300, deadline - 0.3, beta=0.0)
    return h


def _refine_at_res(h, deadline, factor=2):
    """Upsample by `factor` via linear interpolation and polish, then fold back."""
    n = h.size
    if factor < 2 or n < 2:
        return h
    u = np.zeros(factor * n)
    shifted = np.concatenate((h[1:], [h[-1]]))
    for k in range(factor):
        a = k / float(factor)
        row = (1.0 - a) * h + a * shifted
        seg = u[k::factor]
        row = row[:seg.size]
        u[k::factor] = row
    u = _rescale(u)
    r_pre = R_of(u)
    u = _polish(u, deadline, betas=(1e5, 1e6, 1e7),
                pad_fracs=(0.08, 0.04))
    r_post = R_of(u)
    # fold back by averaging factor-subsampled sequences
    L = min(u[k::factor].size for k in range(factor))
    h2 = np.zeros(L)
    for k in range(factor):
        h2 += u[k::factor][:L]
    h2 /= factor
    h2 = _rescale(h2)
    if h2.size > n:
        h2 = h2[:n]
    elif h2.size < n:
        h2 = np.concatenate((h2, np.full(n - h2.size, h2[-1])))
    h2 = _polish(h2, deadline, betas=(1e6, 1e7, 0.0),
                 pad_fracs=(0.08, 0.04))
    return h2, r_pre, r_post


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase A: upsampled refinement at 2x, 3x, 4x resolutions ----
    # Each level: polish at higher resolution, fold back; keep if better.
    for factor in (2, 3, 4):
        if time.process_time() >= t0 + budget_seconds * 0.55:
            break
        try:
            now = time.process_time()
            slice_dl = min(t0 + budget_seconds * 0.50,
                           now + 0.14 * budget_seconds)
            if slice_dl <= now + 1.0:
                break
            h2, r_pre, r_post = _refine_at_res(
                best, slice_dl, factor=factor)
            r = R_of(h2)
            print("refine %dx pre=%.9f post=%.9f fold=%.9f (best %.9f)" %
                  (factor, r_pre, r_post, r, bestR))
            if r > bestR + 1e-13:
                best, bestR, origin = h2.copy(), r, 'ref%d' % factor
                print("  refine NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = h2.copy(), r
        except Exception as e:
            print("refine %dx exception %s" % (factor, e))

    # ---- Phase B: multi-pad peak-window polishes ----
    for pad in [0.15, 0.10, 0.07, 0.05, 0.035, 0.025]:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=192)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR, origin = ht2.copy(), r2, origin + '+pk'
            print("peak pad=%.3f NEW BEST R=%.9f" % (pad, bestR))
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2
        if time.process_time() < deadline - 1.2:
            ht3 = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
            r3 = R_of(ht3)
            if r3 > bestR + 1e-14:
                best, bestR, origin = ht3.copy(), r3, origin + '+b0'
                print("all0 NEW BEST R=%.9f" % bestR)
            elif r3 > alt_bestR:
                alt_best, alt_bestR = ht3.copy(), r3

    # ---- Phase C: another refine cycle if time remains ----
    if time.process_time() < deadline - 4.0:
        try:
            now = time.process_time()
            slice_dl = min(deadline - 3.0, now + 0.10 * budget_seconds)
            if slice_dl > now + 1.0:
                h2, r_pre, r_post = _refine_at_res(
                    best, slice_dl, factor=2)
                r = R_of(h2)
                print("late refine pre=%.9f post=%.9f fold=%.9f (best %.9f)" %
                      (r_pre, r_post, r, bestR))
                if r > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r, 'lref'
                    print("  late refine NEW BEST R=%.9f" % bestR)
                elif r > alt_bestR:
                    alt_best, alt_bestR = h2.copy(), r
        except Exception as e:
            print("late refine exception %s" % e)

    # ---- Phase D: final polish ----
    if time.process_time() < deadline - 1.0:
        ht = _polish(best, deadline - 0.5,
                     betas=(1e6, 1e7, 0.0),
                     pad_fracs=(0.06, 0.04))
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+fin'
            print("final polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    c = (m - 1) / 2.0
    n = h.size
    w = max(3, int(pad * n))
    lo = max(0, int(c - w))
    hi = min(n, int(c + w) + 1)
    if hi - lo < 2:
        return np.arange(n)
    return np.arange(lo, hi)


def _perturb(h, s, k):
    n = h.size
    idx = np.arange(n)
    E = np.cos(2.0 * np.pi * k * (idx + 0.5) / n)
    return _rescale(np.clip(h * (1.0 + s * E), 0.0, None))


def _prolongate(h, N2):
    """Mass-preserving cumulative resampling to N2 steps."""
    N1 = h.size
    if N1 == N2:
        return _rescale(np.clip(h, 0, None))
    M = float(N1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, M, N2 + 1)
    cum_at = np.interp(edges, np.arange(N1 + 1), cum)
    mass = np.diff(cum_at)
    out = mass * (M / N2)
    return _rescale(np.clip(out, 0.0, None))


def _level_refine(h, level_deadline):
    """Run stages (a)-(d) at one resolution level within a fixed slice."""
    best = h
    bestR = R_of(best)

    def time_left():
        return time.process_time() < level_deadline

    # (a) tie-aware full L-BFGS
    if time_left():
        cand = _lbfgs_all_pos(best, 300, level_deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # (b) beta ladder
    for beta in (1e3, 1e5, 1e7):
        if not time_left():
            break
        cand = _lbfgs_all_pos(best, 150, level_deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # (c) peak-window block polish
    for pad in (0.20, 0.12, 0.06, 0.03):
        if not time_left():
            break
        free = _peak_window(best, pad)
        cand = _lbfgs_block(best, free, 150, level_deadline, beta=1e7)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
        if not time_left():
            break
        cand = _lbfgs_block(best, free, 150, level_deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # (d) multiplicative single-cosine perturbations
    for s in (0.03, 0.08, 0.15):
        for k in (1, 2, 3):
            if not time_left():
                break
            cand = _perturb(best, s, k)
            free = _peak_window(cand, 0.04)
            cand = _lbfgs_block(cand, free, 150, level_deadline, tie=True)
            r = R_of(cand)
            if r > bestR + 1e-12:
                best, bestR = cand, r

    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.90 * budget_seconds

    best = None
    bestR = -1.0
    start_arr = None
    startR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.size >= 2 and s.sum() > 0:
            start_arr = s
            startR = R_of(s)
            best = s.copy()
            bestR = startR
            print("start R=%.6f N=%d" % (bestR, s.size))

    if best is None:
        n = 100
        x = (np.arange(n) + 0.5) / n
        h = np.exp(-40.0 * (x - 0.5) ** 2)
        best = _rescale(h)
        bestR = R_of(best)
        print("init bump R=%.6f" % bestR)

    # Forced resolution ladder
    ladder = [200, 400, 800, 1600, 3200, 6400]
    work = best
    for li, N2 in enumerate(ladder):
        if N2 <= work.size:
            continue
        if time.process_time() >= deadline - 1.5:
            break
        levels_left = len(ladder) - li
        now = time.process_time()
        slice_end = now + max(0.5, (deadline - now) / levels_left)

        work = _prolongate(work, N2)
        work, r = _level_refine(work, slice_end)
        print("level N=%d R=%.9f" % (work.size, r))
        if r > bestR:
            best, bestR = work.copy(), r

    # Final polishing on global best
    final_deadline = t0 + 0.95 * budget_seconds
    while time.process_time() < final_deadline - 1.0:
        free = _peak_window(best, 0.02)
        cand = _lbfgs_block(best, free, 150, final_deadline, tie=True)
        r = R_of(cand)
        if r > bestR + 1e-10:
            best, bestR = cand, r
            print("final pad0.02 R=%.9f N=%d" % (bestR, best.size))
        else:
            cand = _lbfgs_all_pos(best, 150, final_deadline, tie=True)
            r = R_of(cand)
            if r > bestR + 1e-10:
                best, bestR = cand, r
                print("final full R=%.9f N=%d" % (bestR, best.size))
            else:
                break

    best = _rescale(np.clip(best, 0, None))
    finalR = R_of(best)
    print("final R=%.9f N=%d" % (finalR, best.size))

    if start_arr is not None and startR >= finalR:
        return {"best": start_arr, "alternative": best}
    return best

