    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _R_coarse(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = np.concatenate(([0.0], np.convolve(c, c), [0.0]))
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _detect_staircase(h):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in (1, 2, 3, 4, 5, 8, 16, 32, 64):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-10:
            r_c = _R_coarse(c)
            r_h = R_of(h)
            if abs(r_c - r_h) < 1e-12:
                return c, p
    return None, 1


def _sweep_coords(c, coords, deadline, rng):
    best_R = _R_coarse(c)
    n_moved = 0
    deltas = np.array([-0.75, -0.5, -0.3, -0.15, -0.07, 0.0,
                       0.07, 0.15, 0.3, 0.5, 0.75])
    order = rng.permutation(coords)
    for k in order:
        if time.process_time() > deadline:
            break
        ck = c[k]
        if ck <= 0:
            continue
        cands = np.clip(np.concatenate((ck * deltas, [0.0])), 0.0, None)
        best_d = 0.0
        best_r = best_R
        for d in cands:
            if d == 0.0:
                continue
            c[k] = d
            r = _R_coarse(c)
            if r > best_r + 1e-16:
                best_r = r
                best_d = d
        c[k] = ck
        if best_d != 0.0:
            c[k] = best_d
            best_R = best_r
            n_moved += 1
    return c, best_R, n_moved


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # ---- Phase A: exact coordinate-max sweep on staircase (or coarse) ----
    sweep_end = t0 + budget_seconds * 0.45
    h = best.copy()
    c, p = _detect_staircase(h)
    if c is not None:
        print("staircase detected p=%d m=%d" % (p, c.size))
        work_c = c.copy()
        work_R = _R_coarse(work_c)
        cyc = 0
        while time.process_time() < sweep_end - 2.0:
            cyc += 1
            coords = np.arange(work_c.size)
            work_c, work_R, n_moved = _sweep_coords(
                work_c, coords, min(sweep_end - 1.0,
                                    time.process_time() + 8.0), rng)
            h_new = _rescale(np.repeat(work_c, p))
            win = _peak_window(h_new, pad_frac=0.10, extra=128)
            h_new = _lbfgs_block(h_new, win, 200,
                                 min(sweep_end - 0.5,
                                     time.process_time() + 4.0), beta=1e7)
            r_new = R_of(h_new)
            if r_new > bestR + 1e-15:
                best, bestR = h_new.copy(), r_new
                c2, p2 = _detect_staircase(best)
                if c2 is not None:
                    work_c = c2.copy()
                    p = p2
                else:
                    work_c = best / max(best.sum(), 1e-300)
                    p = 1
                work_R = _R_coarse(work_c)
            f01, f1, f5 = _nearmax_fracs(best)
            print("  sweep cyc=%d R=%.9f moved=%d near=%.3f/%.3f/%.3f"
                  % (cyc, bestR, n_moved, f01, f1, f5))
            if n_moved == 0 and cyc > 2:
                break
    else:
        print("no staircase; skipping coarse sweep")

    # ---- Phase V: value-band polish (tie-aware, bigger windows) ----
    band_end = t0 + budget_seconds * 0.78
    band_edges = [(0.0, 0.05), (0.05, 0.20), (0.20, 0.50),
                  (0.50, 0.80), (0.80, 0.95), (0.95, 1.001)]
    cyc = 0
    while time.process_time() < band_end - 2.0:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        order = rng.permutation(len(band_edges))
        gains = []
        for bi in order:
            if time.process_time() >= band_end - 1.5:
                break
            lo, hi = band_edges[bi]
            lo *= M; hi *= M
            sel = np.flatnonzero((best > 0) & (v >= lo) & (v < hi))
            if sel.size == 0:
                gains.append(0.0)
                continue
            active = _dilate(sel, n, 24)
            if active.size < 20 or active.size > 0.85 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 400,
                              min(band_end - 1.0,
                                  time.process_time() + 7.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
            if time.process_time() < band_end - 1.0:
                win = _peak_window(best, pad_frac=0.06, extra=64)
                ht2 = _lbfgs_block(best, win, 200,
                                   min(band_end - 0.5,
                                       time.process_time() + 4.0), beta=1e7)
                r2 = R_of(ht2)
                if r2 > bestR + 1e-15:
                    best, bestR = ht2.copy(), r2
        f01, f1, f5 = _nearmax_fracs(best)
        print("band cyc=%d R=%.9f gains=%s near=%.3f/%.3f/%.3f"
              % (cyc, bestR,
                 " ".join("%.1e" % g for g in gains), f01, f1, f5))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase B: peak ladder polish ----
    peak_end = t0 + budget_seconds * 0.88
    if time.process_time() < peak_end - 3.0:
        ht = _peak_ladder(best, peak_end - 1.0,
                          pads=(0.06, 0.03, 0.02), iters=400)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.9f" % bestR)

    # ---- Phase C: final exact tie polish ----
    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 600, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, slice_dl, pad, beta=1e7):
    win = _peak_window(h, pad_frac=pad, extra=128)
    h2 = _lbfgs_block(h, win, 400, slice_dl, beta=beta)
    if time.process_time() < slice_dl - 0.4:
        h2 = _lbfgs_all_pos(h2, 300, slice_dl, beta=0.0)
    return h2


def _lift(c, k, N):
    m = c.size
    if k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: fine peak-window polish with tight pads ----
    polish_end = t0 + budget_seconds * 0.5
    pads = [0.04, 0.025, 0.015, 0.01, 0.007, 0.005]
    round_no = 0
    while time.process_time() < polish_end - 1.0:
        round_no += 1
        improved = False
        for pad in pads:
            if time.process_time() >= polish_end - 0.8:
                break
            slice_dl = min(polish_end, time.process_time() + 0.05 * budget_seconds)
            ht = _polish(best, slice_dl, pad)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, 'pk%.3f' % pad
                improved = True
                print("polish round %d pad %.3f NEW BEST R=%.9f" % (round_no, pad, bestR))
            elif r > alt_bestR and (alt_best is None or alt_best.size == ht.size):
                alt_best, alt_bestR = ht.copy(), r
        if not improved:
            break

    # ---- Phase 2: half-resolution extract/lift cycles ----
    N = best.size
    if N % 2 == 0 and N >= 8:
        m = N // 2
        cyc_end = deadline - 6.0
        for cyc in range(4):
            if time.process_time() >= cyc_end - 1.0:
                break
            k = cyc % 3
            now = time.process_time()
            slice_dl = min(cyc_end, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            if k == 0:
                c = best[0::2][:m].copy()
            elif k == 1:
                c = best[1::2][:m].copy()
            else:
                a = best[0::2][:m]
                b = best[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            # small polish of c
            work_c = c
            for pad in [0.05, 0.03]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                work_c = _polish(work_c, time.process_time() + 0.02 * budget_seconds, pad)
            cand_c = work_c
            cand_cR = R_of(cand_c)
            hnew = _lift(cand_c, k, N)
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'lift_v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: alternating peak polish + beta=0 full until deadline ----
    while time.process_time() < deadline - 1.0:
        improved = False
        for pad in [0.02, 0.012, 0.008, 0.005, 0.003]:
            if time.process_time() >= deadline - 0.8:
                break
            slice_dl = min(deadline - 0.5, time.process_time() + 0.05 * budget_seconds)
            ht = _polish(best, slice_dl, pad)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, origin + '+pk'
                improved = True
                print("late peak pad %.3f NEW BEST R=%.9f" % (pad, bestR))
            elif r > alt_bestR and (alt_best is None or alt_best.size == ht.size):
                alt_best, alt_bestR = ht.copy(), r
        if time.process_time() < deadline - 0.9:
            slice_dl = min(deadline - 0.5, time.process_time() + 0.06 * budget_seconds)
            ht = _lbfgs_all_pos(best, 400, slice_dl, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, origin + '+b0'
                improved = True
                print("late beta0 NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        if not improved and time.process_time() > deadline - 2.0:
            break

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    return _rescale(h)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- NEW: gradient-based vertex/tie alignment via active-set saddle ----------

def _band_mask(h, lo_frac, hi_frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    v = Lf[:h.size]  # knots matching cell boundaries for f*f? use interior
    return (v >= lo_frac * mx) & (v < hi_frac * mx)


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


# ---------- NEW: apex-symmetric reparametrization polish ----------
# The optimal f is often (near) symmetric about the location of max(f*f).
# Enforce exact symmetry h[i] = h[n-1-i] and optimize the half, halving
# the number of free variables and regularizing towards the true optimum.

def _sym_polish(h, deadline, iters=400):
    n = h.size
    if n < 8:
        return h
    # symmetrize about center and optimize half
    half = (n + 1) // 2
    hs = h.copy()
    if n % 2 == 0:
        a = hs[:half]
        b = hs[half:][::-1]
        hs[:half] = 0.5 * (a + b)
        hs[half:] = hs[:half][::-1]
    else:
        a = hs[:half]
        b = hs[half:][::-1]
        hs[:half] = 0.5 * (a + b)
        hs[half:] = hs[:half][::-1]
    hs = _rescale(hs)
    r0 = R_of(hs)
    r_orig = R_of(h)
    # optimize only the half, mirrored
    act = np.arange(half)
    if time.process_time() >= deadline - 0.5:
        return h

    def f(x):
        hh = np.empty(n)
        hh[:half] = np.clip(x, 0.0, None)
        if n % 2 == 0:
            hh[half:] = hh[:half][::-1]
        else:
            hh[half:] = hh[:half - 1][::-1]
        val, g = _fun_grad_tie(hh)
        ghalf = g[:half].copy()
        if n % 2 == 0:
            ghalf = ghalf + g[half:][::-1]
        else:
            ghalf[:-1] += g[half:][::-1]
        return val, ghalf

    x0 = hs[:half].copy()
    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * half,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    hh = np.empty(n)
    hh[:half] = np.clip(res.x, 0.0, None)
    if n % 2 == 0:
        hh[half:] = hh[:half][::-1]
    else:
        hh[half:] = hh[:half - 1][::-1]
    hh = _rescale(hh)
    if R_of(hh) > r_orig + 1e-15:
        return hh
    return h


# ---------- NEW: multi-scale upsampling polish ----------
# If a better R exists at coarser resolution, its upsampled version is a
# good seed. Try both coarsening (average) and refinement (interpolate)
# then L-BFGS on the peak window.

def _coarsen(h, p):
    n = h.size
    m = n // p
    if m < 2:
        return None
    c = h[:m * p].reshape(m, p).mean(axis=1)
    return c


def _refine(c, p):
    return np.repeat(c, p)


def _multi_scale_polish(h, deadline):
    best = h.copy()
    bestR = R_of(best)
    n = h.size
    for p in (2, 3, 4):
        if time.process_time() >= deadline - 1.0:
            break
        c = _coarsen(best, p)
        if c is None:
            continue
        cR = R_of(c)
        if cR > bestR + 1e-12:
            # refine back
            hr = _refine(c, p)
            hr = _rescale(hr)
            win = _peak_window(hr, pad_frac=0.08, extra=64)
            hr2 = _lbfgs_block(hr, win, 300,
                               min(deadline - 0.5, time.process_time() + 4.0),
                               beta=1e7)
            r2 = R_of(hr2)
            if r2 > bestR + 1e-15:
                best, bestR = hr2.copy(), r2
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase S: symmetric polish (new primary idea) ----
    # Try exact symmetry about center; if it improves, keep going.
    sym_end = t0 + budget_seconds * 0.35
    if time.process_time() < sym_end - 2.0:
        hs = _sym_polish(best, sym_end, iters=600)
        rs = R_of(hs)
        if rs > bestR + 1e-15:
            best, bestR = hs.copy(), rs
            print("sym polish ACCEPT R=%.9f" % bestR)
        else:
            print("sym polish no gain (R=%.9f)" % rs)

    # ---- Phase M: multi-scale polish ----
    ms_end = t0 + budget_seconds * 0.55
    if time.process_time() < ms_end - 2.0:
        hm = _multi_scale_polish(best, ms_end)
        rm = R_of(hm)
        if rm > bestR + 1e-15:
            best, bestR = hm.copy(), rm
            print("multi-scale ACCEPT R=%.9f" % bestR)

    # ---- Phase P: peak ladder (iterate on tight peak windows) ----
    peak_end = t0 + budget_seconds * 0.80
    pads = (0.12, 0.08, 0.05, 0.03, 0.02, 0.012, 0.008)
    for pad in pads:
        if time.process_time() >= peak_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie in ((1e7, False), (0.0, True), (0.0, False)):
            if time.process_time() >= peak_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(peak_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        f01, f1, f5 = _nearmax_fracs(best)
        print("peak pad=%.3f R=%.9f near=%.3f/%.3f/%.3f"
              % (pad, bestR, f01, f1, f5))

    # ---- Phase T: band polish (targeted value ranges) ----
    band_end = t0 + budget_seconds * 0.90
    band_edges = [(0.0, 0.02), (0.02, 0.10), (0.10, 0.30),
                  (0.30, 0.60), (0.60, 0.85), (0.85, 0.97), (0.97, 1.001)]
    cyc = 0
    rng = np.random.default_rng(999)
    while time.process_time() < band_end - 1.5:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        gains = []
        order = rng.permutation(len(band_edges))
        for bi in order:
            if time.process_time() >= band_end - 1.0:
                break
            lo, hi = band_edges[bi]
            sel = np.flatnonzero((best > 0) & (v >= lo * M) & (v < hi * M))
            if sel.size == 0:
                gains.append(0.0)
                continue
            active = _dilate(sel, n, 12)
            if active.size < 16 or active.size > 0.85 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 250,
                              min(band_end - 0.5,
                                  time.process_time() + 4.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
        print("band cyc=%d R=%.9f gains=%s"
              % (cyc, bestR, " ".join("%.1e" % g for g in gains)))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase F: final symmetric polish + full-ladder ----
    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 2.0:
        hs = _sym_polish(best, fd - 1.0, iters=400)
        rs = R_of(hs)
        if rs > bestR + 1e-15:
            best, bestR = hs.copy(), rs
            print("final sym ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 1.5:
        win = _peak_window(best, pad_frac=0.02, extra=48)
        ht = _lbfgs_block(best, win, 200,
                          min(fd - 0.5, time.process_time() + 2.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return 0.0, 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    den = s * s * (mx if mx > 0 else 1.0)
    if den <= 0:
        return 0.0, mx
    return num / den, mx


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta))
    cb = _make_cb(deadline - 0.2)

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _report(tag, h):
    R, mx = R_of(h)
    L = _conv(np.maximum(h, 0.0))
    if L.max() > 0:
        near = np.mean(L >= 0.99 * L.max())
        near5 = np.mean(L >= 0.95 * L.max())
        am = float(np.argmax(L)) / max(1, 2 * len(h) - 2)
    else:
        near = 0.0
        near5 = 0.0
        am = 0.0
    print("%s: R=%.6f N=%d zero_frac=%.3f max/mean=%.2f near_max=%.3f near5=%.3f argmax=%.3f" % (
        tag, R, len(h), np.mean(np.asarray(h) <= 0),
        np.max(h) / (np.mean(h) + 1e-12), near, near5, am))
    return R


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    M = len(h)
    if M == N:
        return h.copy()
    edges = np.linspace(0, M, N + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))

    def cum_at(x):
        i = np.floor(x).astype(int)
        i = np.clip(i, 0, M - 1)
        frac = x - i
        return cum[i] + frac * h[i]

    mass = cum_at(edges[1:]) - cum_at(edges[:-1])
    cellw = M / N
    out = mass / cellw
    return np.maximum(out, 0.0)


def _revive(h, deadline):
    """Revive top 2% of zero cells by one-sided derivative of log R."""
    h = np.asarray(h, dtype=float)
    if time.process_time() >= deadline - 0.5:
        return h
    s = h.sum()
    if s <= 0:
        return h
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    # gradient of log R wrt h: dq contribution via backprop, minus 2/s
    # log R = log(num) - 2 log(s) - log(mx)
    # d log R / dh_i = (1/num) * d(num)/dh_i - 2/s - (1/mx)*d(mx)/dh_i
    # d(num)/dh_i = backprop(dq)[i]
    # d(mx)/dh_i = 2 * (h * indicator_Lmax)[i] roughly; use hard max
    gnum = _backprop(dq, h) / num
    gs = -2.0 / s
    # hard max derivative: L = conv(h,h); dL_k/dh_i = 2 h_{k-i}
    # at argmax k*, d mx / dh_i = 2 h_{k*-i}
    kmax = int(np.argmax(Lf))
    gmx = np.zeros_like(h)
    # Lf index j corresponds to conv index j-1 = h[i]+h[j-1-i]
    kk = kmax - 1  # conv index
    if 0 <= kk <= 2 * len(h) - 2:
        for i in range(len(h)):
            j = kk - i
            if 0 <= j < len(h):
                gmx[i] += 2.0 * h[j]
    grad = gnum + gs - gmx / mx
    zero_mask = h <= 0
    if not np.any(zero_mask):
        return h
    active = h > 0
    mean_active = h[active].mean() if np.any(active) else 1.0
    delta = 0.02 * mean_active
    # one-sided derivative at zero: use grad (since h=0, gradient is the right derivative)
    idx = np.where(zero_mask)[0]
    gvals = grad[idx]
    nrev = max(1, int(0.02 * len(idx)))
    top = idx[np.argsort(gvals)[-nrev:]]
    h2 = h.copy()
    h2[top] = delta
    return h2


def _peak_window_polish(h, deadline, beta=1e5, iters=300):
    """Free cells whose f*f knots lie within 5% of max, dilated by 256, L-BFGS."""
    h = np.asarray(h, dtype=float)
    if time.process_time() >= deadline - 0.5:
        return h
    L = _conv(h)
    if L.max() <= 0:
        return h
    mask = L >= 0.95 * L.max()
    # dilate by 256 in knot space; knot j corresponds to h indices around j/2
    N = len(h)
    free = np.zeros(N, dtype=bool)
    idx = np.where(mask)[0]
    for j in idx:
        lo = max(0, (j - 256) // 2)
        hi = min(N, (j + 256) // 2 + 1)
        free[lo:hi] = True
    if not np.any(free):
        return h
    # optimize only free cells; freeze others by huge bound trick is messy,
    # instead run full L-BFGS but that's fine given time. Use full.
    return _lbfgs(h, iters, deadline, beta=beta)


def construct(budget_seconds, start):
    t0 = time.process_time()

    def elapsed():
        return time.process_time() - t0

    deadline = 0.92 * budget_seconds

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float), 0.0)
        if s.sum() > 0:
            R, _ = R_of(s)
            best_h = s.copy()
            best_R = R
            print("Start: R=%.6f N=%d" % (R, len(s)))

    if best_h is None:
        N0 = 4096
        x = np.linspace(0, 1, N0)
        best_h = np.sin(np.pi * x) ** 0.5
        best_R, _ = R_of(best_h)

    print("Working N=%d start R=%.6f" % (len(best_h), best_R))

    # Stage 0: revival at current N
    if elapsed() < deadline - 2.0:
        h = best_h.copy()
        h_rev = _revive(h, deadline)
        if np.any(h_rev != h):
            for beta in (1e3, 1e5, 1e7):
                if elapsed() > deadline - 1.0:
                    break
                dl = min(deadline - 0.5, elapsed() + 0.05 * budget_seconds)
                h_rev = _lbfgs(h_rev, 300, dl, beta=beta)
            if elapsed() < deadline - 0.5:
                h_rev = _lbfgs(h_rev, 300, deadline - 0.3, beta=1e5)
            Rr, _ = R_of(h_rev)
            _report("Stage0 revival", h_rev)
            if Rr > best_R:
                best_R = Rr
                best_h = h_rev.copy()

    # Stage 1: resolution ladder
    for N2 in (16384, 32768, 65536):
        if elapsed() > deadline - 1.0:
            break
        h = _resample(best_h, N2)
        R0, _ = R_of(h)
        # (a) beta ladder
        for beta in (1e3, 1e4, 1e5, 1e6):
            if elapsed() > deadline - 1.0:
                break
            dl = min(deadline - 0.5, elapsed() + 0.06 * budget_seconds)
            h2 = _lbfgs(h, 300, dl, beta=beta)
            R2, _ = R_of(h2)
            if R2 > R0:
                h = h2
                R0 = R2
        # (b) tie-aware hard-max
        if elapsed() < deadline - 1.0:
            dl = min(deadline - 0.5, elapsed() + 0.06 * budget_seconds)
            h2 = _lbfgs(h, 300, dl, beta=1e5)
            R2, _ = R_of(h2)
            if R2 > R0:
                h = h2
                R0 = R2
        # (c) peak-window polish
        if elapsed() < deadline - 1.0:
            dl = min(deadline - 0.5, elapsed() + 0.06 * budget_seconds)
            h2 = _peak_window_polish(h, dl, beta=1e5, iters=300)
            R2, _ = R_of(h2)
            if R2 > R0:
                h = h2
                R0 = R2
        _report("level N%d" % N2, h)
        if R0 > best_R:
            best_R = R0
            best_h = h.copy()

    best_h = np.maximum(np.asarray(best_h, dtype=float), 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(len(best_h) if len(best_h) > 0 else 4096)
    if len(best_h) > 1000000:
        best_h = _resample(best_h, 1000000)
    Rf = _report("FINAL", best_h)

    result = {"best": best_h}
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float), 0.0)
        if s.sum() > 0:
            Rs, _ = R_of(s)
            if Rs > Rf:
                result["best"] = s
                result["alternative"] = best_h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    return _rescale(h)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _fg_v(v, kind, beta=0.0):
    h = v * v
    if kind == 'beta':
        val, gh = _fun_grad_beta(h, beta)
    elif kind == 'tie':
        val, gh = _fun_grad_tie(h)
    else:
        val, gh = _fun_grad(h)
    gv = 2.0 * v * gh
    return val, gv


def _lbfgs_all_pos_v(v0, maxiter, deadline, kind='exact', beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return v0
    v = v0.copy()
    n = v.size

    def f(x):
        return _fg_v(x, kind, beta)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, v, jac=True, method='L-BFGS-B',
                       bounds=[(None, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return v0
    if res is None:
        return v0
    return res.x


def _lbfgs_block_v(v0, free, maxiter, deadline, kind='exact', beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return v0
    v = v0.copy()
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return v0
    x0 = v[active].copy()

    def f(x):
        vv = v.copy()
        vv[active] = x
        val, g = _fg_v(vv, kind, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(None, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return v0
    if res is None:
        return v0
    v2 = v.copy()
    v2[active] = res.x
    return v2


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder_v(v, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        h = v * v
        win = _peak_window(h, pad_frac=pad, extra=128)
        vt = _lbfgs_block_v(v, win, iters, deadline - 0.3, kind='beta', beta=1e7)
        if R_of(vt * vt) > R_of(v * v) + 1e-14:
            v = vt
        if time.process_time() < deadline - 0.5:
            vt = _lbfgs_block_v(v, win, iters, deadline - 0.3, kind='tie')
            if R_of(vt * vt) > R_of(v * v) + 1e-14:
                v = vt
    return v


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _R_coarse(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = np.concatenate(([0.0], np.convolve(c, c), [0.0]))
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def _h_to_v(h):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    return np.sqrt(h)


def _prune_v(v, frac=1e-3):
    if v.size == 0:
        return v
    mx = v.max()
    if mx <= 0:
        return v
    v = v.copy()
    v[v < frac * mx] = 0.0
    return v


def _targeted_revive(h, deadline):
    """Seed only the most promising zero cells at a scanned amplitude."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    pos = h[h > 0]
    if pos.size == 0:
        return h
    mean_h = pos.mean()
    zeros = np.flatnonzero(h <= 0)
    if zeros.size == 0:
        return h
    # one-sided derivative at zero cells: use grad_logR at h (zeros contribute 0)
    g = _grad_logR(h)
    gz = g[zeros]
    # rank by positive derivative
    order = np.argsort(-gz)
    order = order[gz[order] > 0]
    if order.size == 0:
        return h
    best_h = h
    best_R = R_of(h)
    for kfrac in (0.005, 0.02):
        if time.process_time() > deadline:
            break
        k = max(1, int(kfrac * n))
        k = min(k, order.size)
        sel = zeros[order[:k]]
        for dscale in (0.01, 0.03, 0.1):
            if time.process_time() > deadline:
                break
            hh = h.copy()
            hh[sel] = dscale * mean_h
            r = R_of(hh)
            if r > best_R + 1e-16:
                best_R = r
                best_h = hh
    return best_h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zf=%.4f)" % (bestR, best.size, _zero_frac(best)))

    rng = np.random.default_rng(12345)

    # ---- Phase R: targeted revival ----
    rev_end = t0 + budget_seconds * 0.12
    h_rev = _targeted_revive(best, rev_end)
    r_rev = R_of(h_rev)
    print("targeted revive R=%.9f zf=%.4f (was %.4f)"
          % (r_rev, _zero_frac(h_rev), _zero_frac(best)))
    if r_rev > bestR + 1e-16:
        best, bestR = _rescale(h_rev), r_rev

    v = _h_to_v(best)

    # ---- Phase V: value-band polish in v-space (p1861 schedule) ----
    band_end = t0 + budget_seconds * 0.55
    band_edges = [(0.0, 0.05), (0.05, 0.20), (0.20, 0.50),
                  (0.50, 0.80), (0.80, 0.95), (0.95, 1.001)]
    cyc = 0
    while time.process_time() < band_end - 2.0:
        cyc += 1
        h = best
        n = h.size
        v = _h_to_v(h)
        vv = v * v
        vvL = _knots(vv)
        vvM = vvL.max()
        v_knot = vvL[:n]
        order = rng.permutation(len(band_edges))
        gains = []
        for bi in order:
            if time.process_time() >= band_end - 1.5:
                break
            lo, hi = band_edges[bi]
            lo *= vvM; hi *= vvM
            sel = np.flatnonzero((vv > 0) & (v_knot >= lo) & (v_knot < hi))
            if sel.size == 0:
                gains.append(0.0)
                continue
            active = _dilate(sel, n, 16)
            if active.size < 20 or active.size > 0.8 * n:
                gains.append(0.0)
                continue
            prevR = R_of(v * v)
            vt = _lbfgs_block_v(v, active, 300,
                                min(band_end - 1.0,
                                    time.process_time() + 6.0), kind='tie')
            vt = _prune_v(vt)
            r = R_of(vt * vt)
            if r > prevR + 1e-15:
                v = vt
                best = _rescale(v * v)
                bestR = r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
            if time.process_time() < band_end - 1.0:
                win = _peak_window(v * v, pad_frac=0.06, extra=64)
                vt2 = _lbfgs_block_v(v, win, 200,
                                     min(band_end - 0.5,
                                         time.process_time() + 4.0),
                                     kind='beta', beta=1e7)
                vt2 = _prune_v(vt2)
                r2 = R_of(vt2 * vt2)
                if r2 > bestR + 1e-15:
                    v = vt2
                    best = _rescale(v * v)
                    bestR = r2
        f01, f1, f5 = _nearmax_fracs(best)
        print("band cyc=%d R=%.9f zf=%.4f gains=%s near=%.3f/%.3f/%.3f"
              % (cyc, bestR, _zero_frac(best),
                 " ".join("%.1e" % g for g in gains), f01, f1, f5))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase B: peak ladder polish in v-space ----
    peak_end = t0 + budget_seconds * 0.80
    if time.process_time() < peak_end - 3.0:
        v = _h_to_v(best)
        vt = _peak_ladder_v(v, peak_end - 1.0, pads=(0.06, 0.03), iters=300)
        vt = _prune_v(vt)
        r = R_of(vt * vt)
        if r > bestR + 1e-15:
            v = vt
            best, bestR = _rescale(v * v), r
            print("peak ladder ACCEPT R=%.9f zf=%.4f"
                  % (bestR, _zero_frac(best)))

    # ---- Phase C: exact/tie polish in v-space ----
    fd = t0 + budget_seconds * 0.93
    if time.process_time() < fd - 3.0:
        v = _h_to_v(best)
        vt = _lbfgs_all_pos_v(v, 500, fd - 1.5, kind='tie')
        vt = _prune_v(vt)
        r_t = R_of(vt * vt)
        if r_t > bestR + 1e-15:
            v = vt
            best, bestR = _rescale(v * v), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d zf=%.4f"
                  % (bestR, _tie_count(best), _zero_frac(best)))
    if time.process_time() < fd - 1.0:
        v = _h_to_v(best)
        vt = _lbfgs_all_pos_v(v, 300, fd - 0.3, kind='exact')
        vt = _prune_v(vt)
        r_t = R_of(vt * vt)
        if r_t > bestR + 1e-15:
            v = vt
            best, bestR = _rescale(v * v), r_t
            print("FINAL argmax ACCEPT R=%.9f zf=%.4f"
                  % (bestR, _zero_frac(best)))

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


# ---------- exact coordinate maximization helpers ----------

def _R_coarse(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = np.concatenate(([0.0], np.convolve(c, c), [0.0]))
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _R_coarse_fft(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = np.concatenate(([0.0], fftconvolve(c, c), [0.0]))
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _detect_staircase(h):
    """Fixed: test large p first (64,32,16,...) to avoid p=1 false positive."""
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in (64, 32, 16, 8, 5, 4, 3, 2, 1):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-10:
            r_c = _R_coarse(c)
            r_h = R_of(h)
            if abs(r_c - r_h) < 1e-10:
                return c, p
    return None, 1


def _sweep_coords(c, coords, deadline, rng):
    m = c.size
    best_R = _R_coarse(c)
    n_moved = 0
    deltas = np.array([-0.75, -0.5, -0.3, -0.15, -0.07, 0.0,
                       0.07, 0.15, 0.3, 0.5, 0.75])
    order = rng.permutation(coords)
    for k in order:
        if time.process_time() > deadline:
            break
        ck = c[k]
        if ck <= 0:
            continue
        cands = ck * deltas
        cands = np.concatenate((cands, [0.0]))
        cands = np.clip(cands, 0.0, None)
        best_d = 0.0
        best_r = best_R
        for d in cands:
            if d == 0.0:
                continue
            c_old = c[k]
            c[k] = d
            r = _R_coarse(c)
            c[k] = c_old
            if r > best_r + 1e-16:
                best_r = r
                best_d = d
        if best_d != 0.0:
            allv = np.sort(np.unique(np.concatenate((cands, [ck]))))
            idx = np.searchsorted(allv, best_d)
            lo = allv[max(0, idx - 1)]
            hi = allv[min(allv.size - 1, idx + 1)]
            gr = (np.sqrt(5.0) - 1.0) / 2.0
            a, b = lo, hi
            c1 = b - gr * (b - a)
            c2 = a + gr * (b - a)
            c[k] = c1; f1 = _R_coarse(c)
            c[k] = c2; f2 = _R_coarse(c)
            for _ in range(30):
                if time.process_time() > deadline:
                    break
                if f1 < f2:
                    a = c1; c1 = c2; f1 = f2
                    c2 = a + gr * (b - a)
                    c[k] = c2; f2 = _R_coarse(c)
                else:
                    b = c2; c2 = c1; f2 = f1
                    c1 = b - gr * (b - a)
                    c[k] = c1; f1 = _R_coarse(c)
            c[k] = 0.5 * (a + b)
            r = _R_coarse(c)
            if r > best_R + 1e-16:
                best_R = r
                n_moved += 1
            else:
                c[k] = ck
    return c, best_R, n_moved


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


# ---------- pairwise multiplicative descent on c ----------

def _pair_eval(c, i, j, a, b):
    ci = c[i]; cj = c[j]
    c[i] = ci * (1.0 + a)
    c[j] = cj * (1.0 + b)
    r = _R_coarse(c)
    c[i] = ci
    c[j] = cj
    return r


def _pair_refine(c, i, j, a0, b0, r0, deadline):
    """2-D pattern search on (a,b) around (a0,b0)."""
    a, b, r = a0, b0, r0
    step = 0.06
    while step > 1e-4 and time.process_time() < deadline:
        improved = False
        for da, db in ((step, 0), (-step, 0), (0, step), (0, -step),
                       (step, step), (step, -step), (-step, step), (-step, -step)):
            aa = a + da; bb = b + db
            if aa <= -1.0 or bb <= -1.0:
                continue
            rr = _pair_eval(c, i, j, aa, bb)
            if rr > r + 1e-16:
                a, b, r = aa, bb, rr
                improved = True
                break
        if not improved:
            step *= 0.5
    return a, b, r


def _pairwise_descent(c, deadline, rng, print_every=500):
    m = c.size
    best_R = _R_coarse(c)
    n_acc = 0
    n_tried = 0
    grid = (-0.25, -0.12, 0.0, 0.12, 0.25)
    active = np.flatnonzero(c > 0)
    if active.size < 2:
        return c, best_R, n_acc, n_tried
    top_idx = active[np.argsort(-c[active])[:min(300, active.size)]]

    while time.process_time() < deadline - 1.0:
        # Build pair list
        pairs = []
        # (a) random pairs among active
        k = min(2000, active.size * 4)
        ia = rng.choice(active, size=k)
        ib = rng.choice(active, size=k)
        for x, y in zip(ia, ib):
            if x != y:
                pairs.append((int(x), int(y)))
        # (b) pairs among top-300
        if top_idx.size >= 2:
            for _ in range(600):
                x, y = rng.choice(top_idx, size=2, replace=False)
                pairs.append((int(x), int(y)))
        # (c) adjacent pairs
        adj = rng.choice(active, size=min(2000, active.size))
        for x in adj:
            if x + 1 < m:
                pairs.append((int(x), int(x + 1)))
            if x - 1 >= 0:
                pairs.append((int(x - 1), int(x)))

        any_acc = False
        for (i, j) in pairs:
            if time.process_time() >= deadline - 1.0:
                break
            if c[i] <= 0 or c[j] <= 0:
                continue
            n_tried += 1
            # coarse grid
            best_a = 0.0; best_b = 0.0; best_r = best_R
            for a in grid:
                for b in grid:
                    if a == 0.0 and b == 0.0:
                        continue
                    if 1.0 + a <= 0 or 1.0 + b <= 0:
                        continue
                    r = _pair_eval(c, i, j, a, b)
                    if r > best_r + 1e-16:
                        best_r = r; best_a = a; best_b = b
            if best_r > best_R + 1e-16:
                a, b, r = _pair_refine(c, i, j, best_a, best_b, best_r,
                                       deadline - 1.0)
                if r > best_R + 1e-16:
                    c[i] *= (1.0 + a)
                    c[j] *= (1.0 + b)
                    best_R = r
                    n_acc += 1
                    any_acc = True
            if n_tried % print_every == 0:
                print("  pair tried=%d acc=%d R=%.10f"
                      % (n_tried, n_acc, best_R))
        if not any_acc:
            # one full pass with no acceptance: try again with fresh random
            # pairs, but cap the number of fruitless passes
            if n_tried > 20000:
                break
    return c, best_R, n_acc, n_tried


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # ---- Detect staircase (fixed order) ----
    c, p = _detect_staircase(best)
    if c is None:
        print("no staircase detected; running base pipeline only")
        # fall back to base pipeline (peak ladder + final polish)
        peak_end = t0 + budget_seconds * 0.93
        if time.process_time() < peak_end - 3.0:
            ht = _peak_ladder(best, peak_end - 1.0,
                              pads=(0.06, 0.03), iters=300, tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                print("peak ladder ACCEPT R=%.9f" % bestR)
        fd = t0 + budget_seconds * 0.97
        if time.process_time() < fd - 3.0:
            h_t = _lbfgs_all_pos(best, 500, fd - 1.5, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("FINAL tie ACCEPT R=%.9f" % bestR)
        print("final R=%.9f (start %.9f)" % (bestR, startR))
        result = {"best": best}
        if bestR <= startR + 1e-14 and start is not None:
            result["alternative"] = best
        return result

    print("staircase detected p=%d m=%d" % (p, c.size))
    work_c = c.copy()
    work_R = _R_coarse(work_c)
    print("  c R=%.10f (matches h R=%.10f)" % (work_R, bestR))

    # ---- Phase P: pairwise multiplicative descent on c ----
    pair_end = t0 + budget_seconds * 0.80
    work_c, work_R, n_acc, n_tried = _pairwise_descent(
        work_c, pair_end, rng, print_every=500)
    print("pairwise done: tried=%d accepted=%d R=%.10f"
          % (n_tried, n_acc, work_R))

    # Rebuild h from c and check
    h_new = _rescale(np.repeat(work_c, p))
    r_new = R_of(h_new)
    if r_new > bestR + 1e-15:
        best, bestR = h_new.copy(), r_new
        print("PAIRWISE ACCEPT R=%.10f (was %.10f)" % (bestR, startR))
    else:
        print("pairwise no net gain (R=%.10f vs %.10f)" % (r_new, bestR))

    # ---- Phase L: peak ladder polish on best ----
    peak_end = t0 + budget_seconds * 0.93
    if time.process_time() < peak_end - 3.0:
        ht = _peak_ladder(best, peak_end - 1.0,
                          pads=(0.10, 0.06, 0.04), iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.10f" % bestR)

    # ---- Phase C: final exact tie polish ----
    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.10f ties=%d" % (bestR, _tie_count(best)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.10f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return -1.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size, hi + pad)
    return np.arange(lo, hi)


def _prolongate(h, Nnew):
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew)
    edges = np.linspace(0.0, N, Nnew + 1)
    m = np.interp(edges, np.arange(N + 1), c)
    return np.maximum(np.diff(m), 0.0)


def _polish(h, deadline, levels=(0.0, 1e3, 1e4)):
    best = np.asarray(h, dtype=float)
    bestR = R_of(best)
    for beta in levels:
        if time.process_time() > deadline - 0.5:
            break
        cand = _lbfgs_all_pos(best, maxiter=400, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(best)
        cand = _lbfgs_block(best, win, maxiter=300, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
    return best, bestR


def main_construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    best_h = None
    best_R = -1.0
    start_h = None
    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_h = s.copy()
            start_R = R_of(s)
            best_h = s.copy()
            best_R = start_R

    if best_h is None:
        best_h = np.ones(64)
        best_R = R_of(best_h)

    # Stage 1: polish the start at its own resolution (cheap, high value)
    if start_h is not None and time.process_time() < deadline - 2.0:
        h, r = _polish(start_h, min(deadline - 1.0, time.process_time() + 8.0))
        if r > best_R:
            best_R = r
            best_h = h
        print("start polish: %.6f" % best_R)

    # Stage 2: escalate resolutions with polishing
    targets = [8192, 16384, 32768, 65536]
    for Ntarget in targets:
        if time.process_time() > deadline - 2.0:
            break
        h = _prolongate(best_h, Ntarget)
        h, r = _polish(h, deadline)
        if r > best_R:
            best_R = r
            best_h = h
        print("escalated R at N=%d: %.6f" % (Ntarget, best_R))

    # Stage 3: final tight polish at current size with tighter deadline
    if time.process_time() < deadline - 0.5:
        h, r = _polish(best_h, deadline, levels=(0.0, 1e4, 1e5))
        if r > best_R:
            best_R = r
            best_h = h

    print("final R: %.6f, N=%d" % (best_R, best_h.size))

    if start_h is not None and start_R >= best_R:
        return start_h
    if start_h is not None and start_R > 0 and best_h is not None and best_R - start_R > 1e-6:
        return {"best": best_h, "alternative": start_h}
    return best_h


def construct(budget_seconds, start):
    try:
        return main_construct(budget_seconds, start)
    except Exception:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(64)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _zero_frac(h):
    return float(np.mean(h == 0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    base_deadline = deadline - 25.0
    if time.process_time() < base_deadline - 0.5:
        work = best.copy()
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= base_deadline - 0.3:
                break
            ht = _lbfgs_all_pos(work, 300, base_deadline - 0.2, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "basebeta%g" % beta
        for it, pad in enumerate([0.30, 0.15, 0.08]):
            if time.process_time() >= base_deadline - 0.3:
                break
            win = _peak_window(work, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 400, base_deadline - 0.2, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "basepk%d" % it
            if it == 0 and time.process_time() < base_deadline - 0.4:
                ht2 = _lbfgs_all_pos(work, 300, base_deadline - 0.2, beta=0.0)
                r2 = R_of(ht2)
                if r2 > bestR + 1e-14:
                    work, best, bestR = ht2, ht2.copy(), r2
                    origin = "basepk0+all0"
                else:
                    work = ht2 if r2 >= r else work
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    rng = np.random.default_rng(1234)
    lo = np.log(1e-3)
    hi = np.log(5e-2)
    pads = [0.30, 0.20, 0.15, 0.12, 0.10, 0.08, 0.06]
    n_trials = 0
    n_accept = 0
    while time.process_time() < deadline - 2.0:
        amp = float(np.exp(rng.uniform(lo, hi)))
        seed = _random_perturb(best, rng, amp)
        pad = pads[n_trials % len(pads)]
        win = _peak_window(seed, pad_frac=pad, extra=128)
        ht = _lbfgs_block(seed, win, 250, deadline - 0.8, beta=1e7)
        if n_trials % 3 == 0 and time.process_time() < deadline - 1.2:
            ht = _lbfgs_all_pos(ht, 200, deadline - 0.8, beta=0.0)
        r = R_of(ht)
        n_trials += 1
        if r > bestR + 1e-12:
            best, bestR = ht.copy(), r
            n_accept += 1
            origin = "trial%d_a%.4f_p%.2f" % (n_trials, amp, pad)
            print("trial %d amp=%.4f pad=%.2f R=%.9f NEW BEST" %
                  (n_trials, amp, pad, r))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    if time.process_time() < deadline - 0.6:
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + "+finalwin"

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

