            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    base_deadline = deadline - 25.0
    if time.process_time() < base_deadline - 0.5:
        work = best.copy()
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= base_deadline - 0.3:
                break
            ht = _lbfgs_all_pos(work, 300, base_deadline - 0.2, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "basebeta%g" % beta
        for it, pad in enumerate([0.30, 0.15, 0.08]):
            if time.process_time() >= base_deadline - 0.3:
                break
            win = _peak_window(work, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 400, base_deadline - 0.2, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR = ht, ht.copy(), r
                origin = "basepk%d" % it
            if it == 0 and time.process_time() < base_deadline - 0.4:
                ht2 = _lbfgs_all_pos(work, 300, base_deadline - 0.2, beta=0.0)
                r2 = R_of(ht2)
                if r2 > bestR + 1e-14:
                    work, best, bestR = ht2, ht2.copy(), r2
                    origin = "basepk0+all0"
                else:
                    work = ht2 if r2 >= r else work
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    rng = np.random.default_rng(1234)
    lo = np.log(1e-3)
    hi = np.log(5e-2)
    pads = [0.30, 0.20, 0.15, 0.12, 0.10, 0.08, 0.06]
    n_trials = 0
    n_accept = 0
    while time.process_time() < deadline - 2.0:
        amp = float(np.exp(rng.uniform(lo, hi)))
        seed = _random_perturb(best, rng, amp)
        pad = pads[n_trials % len(pads)]
        win = _peak_window(seed, pad_frac=pad, extra=128)
        ht = _lbfgs_block(seed, win, 250, deadline - 0.8, beta=1e7)
        if n_trials % 3 == 0 and time.process_time() < deadline - 1.2:
            ht = _lbfgs_all_pos(ht, 200, deadline - 0.8, beta=0.0)
        r = R_of(ht)
        n_trials += 1
        if r > bestR + 1e-12:
            best, bestR = ht.copy(), r
            n_accept += 1
            origin = "trial%d_a%.4f_p%.2f" % (n_trials, amp, pad)
            print("trial %d amp=%.4f pad=%.2f R=%.9f NEW BEST" %
                  (n_trials, amp, pad, r))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    if time.process_time() < deadline - 0.6:
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + "+finalwin"

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _fg_v(v, kind, beta=0.0):
    h = v * v
    if kind == 'beta':
        val, gh = _fun_grad_beta(h, beta)
    elif kind == 'tie':
        val, gh = _fun_grad_tie(h)
    else:
        val, gh = _fun_grad(h)
    gv = 2.0 * v * gh
    return val, gv


def _lbfgs_all_pos_v(v0, maxiter, deadline, kind='exact', beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return v0
    v = v0.copy()
    n = v.size

    def f(x):
        return _fg_v(x, kind, beta)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, v, jac=True, method='L-BFGS-B',
                       bounds=[(None, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return v0
    if res is None:
        return v0
    return res.x


def _lbfgs_block_v(v0, free, maxiter, deadline, kind='exact', beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return v0
    v = v0.copy()
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return v0
    x0 = v[active].copy()

    def f(x):
        vv = v.copy()
        vv[active] = x
        val, g = _fg_v(vv, kind, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(None, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return v0
    if res is None:
        return v0
    v2 = v.copy()
    v2[active] = res.x
    return v2


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _h_to_v(h, revive_scale=0.02):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    v = np.sqrt(h)
    if h.size > 0:
        pos = h[h > 0]
        mean_h = pos.mean() if pos.size > 0 else 1.0
        small = revive_scale * np.sqrt(mean_h)
        v = np.where(h > 0, v, small)
    return v


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _coarsen(h, f):
    n = h.size
    m = n // f
    if m < 2:
        return h
    return h[:m * f].reshape(m, f).mean(axis=1)


def _prolongate(hc, n):
    m = hc.size
    if m == n:
        return hc.copy()
    # cell-centered linear interpolation
    xc = (np.arange(m) + 0.5) / m
    xn = (np.arange(n) + 0.5) / n
    return np.interp(xn, xc, hc)


def _level_opt(h, deadline, iters=400):
    """Optimize at one level in v-space; return best h by exact R."""
    v = _h_to_v(h, revive_scale=0.02)
    best_v = v.copy()
    bestR = R_of(v * v)
    if time.process_time() >= deadline - 0.5:
        return best_v * best_v
    v = _lbfgs_all_pos_v(v, iters, deadline, kind='exact')
    r = R_of(v * v)
    if r > bestR:
        best_v, bestR = v.copy(), r
    if time.process_time() < deadline - 0.5:
        v = _lbfgs_all_pos_v(best_v, 200, deadline, kind='beta', beta=1e4)
        r = R_of(v * v)
        if r > bestR:
            best_v, bestR = v.copy(), r
    if time.process_time() < deadline - 0.5:
        v = _lbfgs_all_pos_v(best_v, 200, deadline, kind='beta', beta=1e6)
        r = R_of(v * v)
        if r > bestR:
            best_v, bestR = v.copy(), r
    return best_v * best_v


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Coarse-to-fine ladder ----
    N = best.size
    # build levels: coarsen by factor 2 four times
    levels = []
    h = best.copy()
    for _ in range(4):
        h = _coarsen(h, 2)
        levels.append(h.copy())
    # levels: [N/2, N/4, N/8, N/16]; optimize coarse -> fine
    ladder = list(reversed(levels))  # coarsest first
    ladder.append(best.copy())       # finest = original N

    # time shares: give coarse levels modest slices, finest gets the rest
    nlev = len(ladder)
    # allocate: coarse levels get small fixed slices, finest gets remainder
    coarse_budget = budget_seconds * 0.35
    per_coarse = coarse_budget / (nlev - 1) if nlev > 1 else 0.0

    cur_h = ladder[0].copy()
    for li in range(nlev):
        if time.process_time() >= deadline - 1.0:
            break
        if li == nlev - 1:
            lev_deadline = deadline - 0.5
        else:
            lev_deadline = min(deadline - 0.5,
                               time.process_time() + per_coarse)
        R_before = R_of(cur_h)
        cur_h = _level_opt(cur_h, lev_deadline, iters=400)
        R_after = R_of(cur_h)
        zf = _zero_frac(cur_h)
        f01, f1, f5 = _nearmax_fracs(cur_h)
        print("level %d N=%d R_before=%.9f R_after=%.9f zf=%.4f near=%.3f/%.3f/%.3f"
              % (li, cur_h.size, R_before, R_after, zf, f01, f1, f5))
        if R_after > bestR + 1e-15:
            best = _rescale(cur_h)
            bestR = R_after
        # prolongate to next finer level
        if li < nlev - 1:
            nnext = ladder[li + 1].size
            cur_h = _prolongate(cur_h, nnext)
            cur_h = np.clip(cur_h, 0, None)

    # ---- Finest-level peak-window ladder with remaining time ----
    if time.process_time() < deadline - 1.0:
        v = _h_to_v(best, revive_scale=0.02)
        for pad in (0.1, 0.05, 0.02, 0.01):
            if time.process_time() >= deadline - 1.0:
                break
            h = v * v
            win = _peak_window(h, pad_frac=pad, extra=128)
            vt = _lbfgs_block_v(v, win, 300,
                                min(deadline - 0.5,
                                    time.process_time() + 5.0),
                                kind='beta', beta=1e7)
            r = R_of(vt * vt)
            if r > bestR + 1e-15:
                v = vt
                best = _rescale(v * v)
                bestR = r
                print("peak pad=%.2f ACCEPT R=%.9f zf=%.4f"
                      % (pad, bestR, _zero_frac(best)))
            if time.process_time() < deadline - 1.0:
                vt = _lbfgs_block_v(v, win, 200,
                                    min(deadline - 0.3,
                                        time.process_time() + 4.0),
                                    kind='tie')
                r = R_of(vt * vt)
                if r > bestR + 1e-15:
                    v = vt
                    best = _rescale(v * v)
                    bestR = r
                    print("peak tie pad=%.2f ACCEPT R=%.9f" % (pad, bestR))

    # ---- Final full-array polish ----
    if time.process_time() < deadline - 1.0:
        v = _h_to_v(best, revive_scale=0.02)
        vt = _lbfgs_all_pos_v(v, 400, deadline - 0.5, kind='tie')
        r = R_of(vt * vt)
        if r > bestR + 1e-15:
            best = _rescale(vt * vt)
            bestR = r
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, startR, best.size, _zero_frac(best), _nearmax_fracs(best)[2]))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve, next_fast_len


def _conv(h):
    if h.size > 1500:
        n = next_fast_len(2 * h.size - 1)
        return fftconvolve(h, h, mode='full')[:2 * h.size - 1]
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    return _rescale(h)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- coarse R for the quotient c ----------

def _R_coarse(c):
    c = np.asarray(c, dtype=float)
    s = c.sum()
    if s <= 0:
        return 0.0
    m = c.size
    n = next_fast_len(4 * m)
    conv = fftconvolve(c, c, mode='full')
    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[1:-1] = conv
    L[-1] = 0.0
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    den = s * s * mx
    if den <= 0:
        return 0.0
    return num / den


# ---------- detect staircase stride ----------

def _detect_stride(h):
    n = h.size
    for p in (64, 32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h[:m * p].reshape(m, p)
        # staircase: within each block, values nearly constant
        var = c.var(axis=1)
        mean = c.mean(axis=1) + 1e-30
        rel = np.median(var / (mean * mean))
        if rel < 1e-6:
            return p, m
    return 1, n


# ---------- pair move with golden-section on t ----------

def _pair_golden(c, i, j, R0, evals=7):
    # c_i -> t*c_i, c_j -> c_j/t ; search t in [0.5,2.0]
    ci = c[i]; cj = c[j]
    if ci <= 0 or cj <= 0:
        return None, R0
    lo, hi = 0.5, 2.0
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    a, b = lo, hi
    x1 = b - gr * (b - a)
    x2 = a + gr * (b - a)
    c1 = c.copy(); c1[i] = ci * x1; c1[j] = cj / x1
    c2 = c.copy(); c2[i] = ci * x2; c2[j] = cj / x2
    f1 = _R_coarse(c1); f2 = _R_coarse(c2)
    best_t = 1.0; best_R = R0
    if f1 > best_R:
        best_R = f1; best_t = x1
    if f2 > best_R:
        best_R = f2; best_t = x2
    for _ in range(evals - 2):
        if f1 > f2:
            b = x2; x2 = x1; f2 = f1
            x1 = b - gr * (b - a)
            c1 = c.copy(); c1[i] = ci * x1; c1[j] = cj / x1
            f1 = _R_coarse(c1)
            if f1 > best_R:
                best_R = f1; best_t = x1
        else:
            a = x1; x1 = x2; f1 = f2
            x2 = a + gr * (b - a)
            c2 = c.copy(); c2[i] = ci * x2; c2[j] = cj / x2
            f2 = _R_coarse(c2)
            if f2 > best_R:
                best_R = f2; best_t = x2
    if best_R > R0 + 1e-14:
        cnew = c.copy()
        cnew[i] = ci * best_t
        cnew[j] = cj / best_t
        return cnew, best_R
    return None, R0


def _rank_cells(c, topk=250):
    # |d log R / d log c_i| via finite difference on log scale
    m = c.size
    R0 = _R_coarse(c)
    idx = np.flatnonzero(c > 0)
    if idx.size == 0:
        return np.array([], dtype=int)
    eps = 1e-3
    scores = np.zeros(idx.size)
    for k, i in enumerate(idx):
        c2 = c.copy()
        c2[i] = c[i] * (1.0 + eps)
        R2 = _R_coarse(c2)
        scores[k] = abs((np.log(max(R2, 1e-30)) - np.log(max(R0, 1e-30))) / eps)
    order = np.argsort(-scores)
    sel = idx[order[:topk]]
    return sel


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # detect staircase stride
    p, m = _detect_stride(best)
    print("stride p=%d m=%d" % (p, m))

    if p > 1 and m >= 4:
        c = best[:m * p].reshape(m, p).mean(axis=1)
        cR = _R_coarse(c)
        print("coarse R=%.9f" % cR)

        # ---- Phase PW: pairwise multiplicative descent ----
        pw_end = t0 + budget_seconds * 0.75
        n_accept = 0
        n_eval = 0
        sweep = 0
        while time.process_time() < pw_end - 1.0:
            sweep += 1
            top = _rank_cells(c, topk=250)
            pairs = set()
            # all pairs among top
            for a in range(top.size):
                for b in range(a + 1, top.size):
                    pairs.add((int(top[a]), int(top[b])))
            # all pairs with |i-j|<=4 among nonzero cells
            nz = np.flatnonzero(c > 0)
            for i in nz:
                for d in range(1, 5):
                    j = i + d
                    if j < m and c[j] > 0:
                        pairs.add((int(i), int(j)))
            pairs = list(pairs)
            # shuffle for diversity
            rng = np.random.default_rng(sweep)
            rng.shuffle(pairs)
            sweep_accept = 0
            for (i, j) in pairs:
                if time.process_time() >= pw_end - 0.8:
                    break
                n_eval += 1
                cnew, Rnew = _pair_golden(c, i, j, cR, evals=7)
                if cnew is not None:
                    c = cnew
                    cR = Rnew
                    n_accept += 1
                    sweep_accept += 1
                    if n_accept % 40 == 0:
                        top = _rank_cells(c, topk=250)
            print("PW sweep=%d accepts=%d total=%d coarseR=%.9f evals=%d"
                  % (sweep, sweep_accept, n_accept, cR, n_eval))
            if sweep_accept == 0:
                break

        print("PW done: accepts=%d evals=%d coarseR=%.9f" % (n_accept, n_eval, cR))

        # prolong and fine polish
        hc = np.repeat(c, p)
        if hc.size < best.size:
            hc = np.concatenate([hc, best[hc.size:]])
        elif hc.size > best.size:
            hc = hc[:best.size]
        hc = _rescale(hc)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc
            print("prolong ACCEPT R=%.9f" % bestR)

    # ---- fine peak-window ladder ----
    fd = t0 + budget_seconds * 0.99
    pads = (0.06, 0.03, 0.02, 0.01)
    for pad in pads:
        if time.process_time() >= fd - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie in ((1e7, False), (0.0, True), (0.0, False)):
            if time.process_time() >= fd - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(fd - 0.5, time.process_time() + 3.0),
                              beta=beta, tie=tie)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        f01, f1, f5 = _nearmax_fracs(best)
        print("peak pad=%.3f R=%.9f near=%.3f/%.3f/%.3f"
              % (pad, bestR, f01, f1, f5))

    if bestR < startR:
        best = _rescale(np.asarray(start, dtype=float))
        bestR = startR

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    return np.concatenate(([0.0], np.convolve(h, h), [0.0]))


def _R_from_L(L):
    m = L.max()
    if m <= 0:
        return 0.0
    Ln = L / m
    s2 = np.sum(Ln[:-1] ** 2 + Ln[:-1] * Ln[1:] + Ln[1:] ** 2) / 3.0
    s1 = np.sum(Ln)  # not used directly; use exact formula below
    return s2 / (s1 * s1) if s1 > 0 else 0.0


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.sum() <= 0:
        return 0.0
    L = _knots(h)
    m = L.max()
    if m <= 0:
        return 0.0
    Ln = L / m
    s2 = np.sum(Ln[:-1] ** 2 + Ln[:-1] * Ln[1:] + Ln[1:] ** 2) / 3.0
    s1 = np.sum(h)  # ||f*f||_1 = (sum h)^2, but with L normalized by m
    # exact: ||f*f||_2^2 / (||f*f||_1 * ||f*f||_inf)
    # L = conv(h,h). ||f*f||_1 = (sum h)^2. ||f*f||_inf = m.
    # ||f*f||_2^2 = sum (L_j^2 + L_j L_{j+1} + L_{j+1}^2)/3
    s2raw = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    s1raw = s1 * s1
    return s2raw / (s1raw * m)


def _objective(h, beta):
    """Beta-softmax surrogate: maximize R ~ minimize -s2/(s1^2 * softmax)."""
    h = np.asarray(h, dtype=float)
    if h.sum() <= 0:
        return 1e10
    L = _knots(h)
    m = L.max()
    if m <= 0:
        return 1e10
    # softmax approximation of max
    Ls = L * beta
    Ls -= Ls.max()
    w = np.exp(Ls)
    softmax = np.sum(L * w) / np.sum(w)
    if softmax <= 0:
        return 1e10
    s2raw = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    s1raw = h.sum() ** 2
    R = s2raw / (s1raw * softmax)
    return -R


def _grad_obj(h, beta):
    """Numerical gradient via finite differences (small arrays only)."""
    eps = 1e-6
    n = len(h)
    g = np.zeros(n)
    f0 = _objective(h, beta)
    for i in range(n):
        hp = h.copy()
        hp[i] += eps
        g[i] = (_objective(hp, beta) - f0) / eps
    return g


def _lbfgsb(h, beta, maxiter, deadline):
    n = len(h)
    if n > 4000:
        # too big for numerical grad; use a coarse subset via active cells
        return h
    def fun(x):
        return _objective(x, beta)
    def jac(x):
        return _grad_obj(x, beta)
    try:
        res = minimize(fun, h, jac=jac, method='L-BFGS-B',
                       bounds=[(0, None)] * n,
                       options={'maxiter': maxiter, 'ftol': 1e-12, 'gtol': 1e-10})
        if time.process_time() > deadline:
            return h
        return np.maximum(res.x, 0.0)
    except Exception:
        return h


def _peak_polish(h, pad_frac, deadline, iters=60):
    """Polish only cells near the peak of f*f."""
    n = len(h)
    L = _knots(h)
    peak = int(np.argmax(L))
    # peak in L corresponds to lag ~ peak-1 in conv; cells contributing are h[i] and h[lag-i]
    lag = peak - 1
    lo = max(0, lag - int(pad_frac * n))
    hi = min(n, lag + int(pad_frac * n) + 1)
    # also include cells near the peak position itself
    idx = set(range(lo, hi))
    # include cells around the peak location in h
    plo = max(0, peak - int(pad_frac * n))
    phi = min(n, peak + int(pad_frac * n))
    idx.update(range(plo, phi))
    idx = sorted(idx)
    if len(idx) == 0 or len(idx) > 3000:
        return h
    sub = h[idx].copy()
    def fun(x):
        hh = h.copy()
        hh[idx] = np.maximum(x, 0.0)
        return _objective(hh, 1e6)
    try:
        res = minimize(fun, sub, method='L-BFGS-B',
                       bounds=[(0, None)] * len(sub),
                       options={'maxiter': iters, 'ftol': 1e-14})
        if time.process_time() > deadline:
            return h
        hh = h.copy()
        hh[idx] = np.maximum(res.x, 0.0)
        return hh
    except Exception:
        return h


def _build_comb(p, q, m):
    Dp = np.unique((np.arange(p) ** 2) % p)
    Dq = np.unique((np.arange(q) ** 2) % q)
    N = m * p * q
    h = np.zeros(N)
    for i in Dp:
        for j in Dq:
            s = i * q + j
            if s < p * q:
                h[s * m:(s + 1) * m] = 1.0
    return h


def _refine(h, deadline, budget):
    """Beta ladder + peak polish."""
    best = h.copy()
    bestR = _R(best)
    # rescale so max knot = 1
    L = _knots(best)
    m = L.max()
    if m > 0:
        best = best / np.sqrt(m)
    for beta in [1e3, 1e5, 1e7]:
        if time.process_time() > deadline:
            break
        cand = _lbfgsb(best, beta, 250, deadline)
        r = _R(cand)
        if r > bestR:
            best, bestR = cand, r
    # peak polish ladder
    for pad in [0.2, 0.1, 0.05, 0.03, 0.02, 0.012]:
        if time.process_time() > deadline:
            break
        cand = _peak_polish(best, pad, deadline)
        r = _R(cand)
        if r > bestR:
            best, bestR = cand, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.92 * budget_seconds

    best = None
    bestR = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best = s.copy()
            bestR = _R(best)

    # Try sumset comb variants
    variants = []
    for m in [16, 32]:
        try:
            h = _build_comb(127, 43, m)
            if h.sum() > 0:
                variants.append(h)
        except Exception:
            pass
    # width-1 no-bump variant
    try:
        h = _build_comb(127, 43, 1)
        if h.sum() > 0:
            variants.append(h)
    except Exception:
        pass

    for h in variants:
        if time.process_time() > deadline:
            break
        r0 = _R(h)
        print(f"raw comb N={len(h)} R={r0:.6f}")
        cand, r = _refine(h, deadline, budget_seconds)
        print(f"  refined R={r:.6f}")
        if r > bestR:
            best, bestR = cand, r

    # If we have a start, also refine it
    if start is not None and best is not None:
        if time.process_time() < deadline:
            cand, r = _refine(best, deadline, budget_seconds)
            if r > bestR:
                best, bestR = cand, r

    if best is None:
        best = np.ones(50)

    # Final check
    finalR = _R(best)
    print(f"final R={finalR:.6f} N={len(best)}")
    L = _knots(best)
    m = L.max()
    if m > 0:
        frac = np.mean(L > 0.999 * m)
        print(f"near-max knot fraction: {frac*100:.2f}%")

    if start is not None:
        sr = _R(np.asarray(start, dtype=float))
        if finalR >= sr:
            return best
        else:
            return {"best": np.asarray(start, dtype=float), "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(start, Nf):
    start = np.asarray(start, dtype=float)
    n = start.size
    if n == Nf:
        return start.copy()
    c = np.concatenate([[0.0], np.cumsum(start)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nf)
    xs = np.linspace(0.0, 1.0, Nf + 1)
    old = np.linspace(0.0, 1.0, n + 1)
    cm = np.interp(xs, old, c)
    h = np.diff(cm) * Nf
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    best = None
    best_r = -1.0
    if start is not None:
        s0 = np.asarray(start, dtype=float)
        r0 = R_of(s0)
        best = s0.copy()
        best_r = r0

    # Starting point
    if best is not None:
        h = best.copy()
    else:
        N0 = 2048
        xk = (np.arange(N0) + 0.5) / N0
        h = 1.0 / np.sqrt(np.maximum(xk * (1 - xk), 1e-3))
        h = np.minimum(h, 4.0 * np.mean(h))
        best_r = R_of(h)
        best = h.copy()

    # Ensure reasonable size
    if h.size < 4096:
        h = _resample(h, 4096)
    elif h.size > 200000:
        h = _resample(h, 200000)

    print(f"start R={best_r:.6f} N={h.size}")

    # Stage 1: polish existing (all-positive L-BFGS)
    rem = deadline - time.process_time()
    if rem > 1.0:
        st1 = min(deadline, time.process_time() + rem * 0.35)
        h1 = _lbfgs_all_pos(h, 400, st1)
        r1 = R_of(h1)
        if r1 > best_r:
            best, best_r, h = h1, r1, h1
        else:
            h = h1 if r1 > R_of(h) * 0.999 else h
        print(f"stage1 R={best_r:.6f}")

    # Stage 2: upsample by 2 and polish
    rem = deadline - time.process_time()
    if rem > 1.0:
        h2 = np.repeat(best, 2)
        st2 = min(deadline, time.process_time() + rem * 0.5)
        h2p = _lbfgs_all_pos(h2, 400, st2)
        r2 = R_of(h2p)
        if r2 > best_r:
            best, best_r = h2p, r2
        print(f"stage2 R={best_r:.6f} N={best.size}")

    # Stage 3: peak-window refinement (finer grid near peak)
    rem = deadline - time.process_time()
    if rem > 1.0 and best.size >= 2000:
        # windowed block polish with higher resolution
        win = _peak_window(best, tol=0.999, pad_frac=0.5, extra=512)
        st3 = min(deadline, time.process_time() + rem * 0.5)
        hb = _lbfgs_block(best, win, 300, st3)
        rb = R_of(hb)
        if rb > best_r:
            best, best_r = hb, rb
        print(f"stage3 R={best_r:.6f}")

    # Stage 4: beta smooth polish for ties
    rem = deadline - time.process_time()
    if rem > 0.5:
        st4 = min(deadline, time.process_time() + rem * 0.6)
        h4 = _lbfgs_all_pos(best, 300, st4, beta=1e6)
        r4 = R_of(h4)
        if r4 > best_r:
            best, best_r = h4, r4
        print(f"stage4 R={best_r:.6f}")

    # Stage 5: final all-pos polish with remaining time
    rem = deadline - time.process_time()
    if rem > 0.5:
        st5 = deadline - 0.2
        h5 = _lbfgs_all_pos(best, 500, st5)
        r5 = R_of(h5)
        if r5 > best_r:
            best, best_r = h5, r5
        print(f"final R={best_r:.6f} N={best.size}")

    if start is not None:
        rs = R_of(np.asarray(start, dtype=float))
        if best_r >= rs:
            return best
        else:
            return {"best": np.asarray(start, dtype=float), "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


# ---------- core R and gradient (FFT-accelerated for large N) ----------

def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -1.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    inf = L.max()
    den = s * s * inf
    if den <= 0:
        return -1.0
    return num / den


def _backprop(gL, h):
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _fg_log(h):
    """Minimise -log R. Returns (val, grad) with grad wrt h."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if num <= 0 or Lm <= 0:
        return 1e18, np.zeros(h.size)
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf[1:-1], h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fg_log_beta(h, beta):
    """Smooth-max version (softmax of top knots) to escape tie issues."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = Lf.max()
    if num <= 0 or mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    gLf = -dq / num + w / sm
    grad = _backprop(gLf[1:-1], h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return np.asarray(h0, dtype=float)
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    if beta > 0:
        fg = (lambda hh: _fg_log_beta(hh, beta))
    else:
        fg = _fg_log

    def f(x):
        return fg(np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return np.asarray(h0, dtype=float)
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fg_log_beta(hh, beta))
    else:
        fg = _fg_log

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        v, g = fg(hh)
        return v, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


# ---------- refinement helpers ----------

def _peak_window(h, tol=0.9995, pad_frac=0.5, extra=128):
    """Index range around the peak region of f*f."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _prolong_repeat(h, n_new):
    """Exact step-doubling: preserves f*f shape up to a factor."""
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n_new % n != 0:
        return _prolong(h, n_new)
    rep = n_new // n
    return np.repeat(h / rep, rep)


def _polish_all(h, deadline, rounds=3):
    """Alternate full + peak-window LBFGS polish."""
    cur = np.asarray(h, dtype=float)
    best_R = _R(cur)
    for _ in range(rounds):
        if time.process_time() > deadline - 0.5:
            break
        # peak window
        w = _peak_window(cur)
        h2 = _lbfgs_block(cur, w, 400, deadline)
        r2 = _R(h2)
        if r2 > best_R + 1e-12:
            cur = h2; best_R = r2
        else:
            break
    return cur, best_R


# ---------- seeds ----------

def _seed_cosine(n):
    x = np.linspace(0, 1, n)
    return np.cos(np.pi * (x - 0.5))**2 + 1e-3


def _seed_asym(n):
    x = np.linspace(0, 1, n)
    return np.exp(-((x - 0.35) / 0.2)**2) + 1e-3


def _seed_two_bumps(n):
    x = np.linspace(0, 1, n)
    b1 = np.exp(-((x - 0.25) / 0.15)**2)
    b2 = np.exp(-((x - 0.70) / 0.30)**2)
    return b1 + b2 + 1e-3


def _seed_triangular(n):
    x = np.linspace(0, 1, n)
    return np.minimum(x, 1 - x) + 1e-3


def _seed_blocks(n, rng_seed=12345):
    rng = np.random.RandomState(rng_seed)
    nb = 12
    w = np.exp(rng.uniform(np.log(1), np.log(max(2, n / 4)), nb))
    w = w / w.sum()
    edges = np.concatenate(([0.0], np.cumsum(w)))
    hs = np.exp(rng.normal(0, 1.5, nb))
    h = np.zeros(n)
    for b in range(nb):
        i0 = int(edges[b] * n); i1 = int(edges[b + 1] * n)
        i1 = max(i1, i0 + 1)
        h[i0:i1] = hs[b]
    return np.maximum(h, 1e-6)


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    stage_seed = t0 + min(12.0, budget_seconds * 0.20)
    stage_grow = t0 + min(35.0, budget_seconds * 0.60)

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            best_R = _R(best)

    # ---- Stage A: build a good seed if start is weak/missing ----
    candidates = []
    if best is not None and best_R > 0.5:
        candidates.append(("start", best.copy()))
    else:
        N0 = 256
        for name, s in [("cosine", _seed_cosine(N0)),
                        ("asym", _seed_asym(N0)),
                        ("twobump", _seed_two_bumps(N0)),
                        ("tri", _seed_triangular(N0)),
                        ("blocks", _seed_blocks(N0))]:
            if time.process_time() > stage_seed:
                break
            h = _lbfgs(s, 300, stage_seed)
            r = _R(h)
            print(f"seed {name}: R={r:.6f}")
            candidates.append((name, h))

    # ---- Stage B: grow the best candidate up the resolution ladder ----
    # Choose the best seed to grow.
    if candidates:
        candidates.sort(key=lambda t: -_R(t[1]))
        cur = candidates[0][1]
    else:
        cur = _seed_cosine(256)
    cur_R = _R(cur)
    print(f"growing from R={cur_R:.6f} N={len(cur)}")

    ladder = [512, 1024, 2048, 4096, 8192, 16384, 32768]
    for n_new in ladder:
        if time.process_time() > stage_grow:
            break
        if n_new > len(cur):
            cur = _prolong_repeat(cur, n_new)
        cur = _lbfgs(cur, 400, stage_grow)
        cur_R = _R(cur)
        print(f"ladder N={len(cur)}: R={cur_R:.6f}")
        if cur_R > best_R:
            best = cur.copy(); best_R = cur_R

    # ---- Stage C: intensive polish of best (window + full alternating) ----
    if best is not None:
        # First try to grow best if it's small relative to time left
        n_best = len(best)
        while time.process_time() < deadline - 3.0 and n_best < 16384:
            n_new = min(16384, n_best * 2)
            cand = _prolong_repeat(best, n_new)
            cand = _lbfgs(cand, 400, deadline)
            r = _R(cand)
            print(f"grow best N={n_new}: R={r:.6f}")
            if r > best_R:
                best = cand; best_R = r; n_best = n_new
            else:
                break

        # Alternate peak-window and short full optimisations.
        stall = 0
        while time.process_time() < deadline - 0.5 and stall < 6:
            improved = False
            w = _peak_window(best)
            h2 = _lbfgs_block(best, w, 500, deadline)
            r2 = _R(h2)
            if r2 > best_R + 1e-11:
                best = h2; best_R = r2; improved = True
            # one short full pass
            if time.process_time() < deadline - 1.0:
                h3 = _lbfgs(best, 150, deadline)
                r3 = _R(h3)
                if r3 > best_R + 1e-11:
                    best = h3; best_R = r3; improved = True
            if not improved:
                stall += 1

    if best is None:
        best = np.ones(50)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={_R(best):.6f} N={len(best)} free={np.mean(best>0):.3f}")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 0.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0, tie=False):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline,
                        beta=beta, tie=tie)


def _smooth_polish(h, deadline, betas):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        c = _lbfgs_log(h, maxiter=300, deadline=deadline, beta=beta)
        if R_of(c) >= R_of(h):
            h = c
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(h, maxiter=600, deadline=deadline, beta=0.0)
        if R_of(c) >= R_of(h):
            h = c
    return h


def _perturb_window(h, rng, lo_frac, hi_frac, sigma, nblk_lo=4, nblk_hi=9,
                    zero_fill=False):
    h = h.copy()
    n = h.size
    lo = int(lo_frac * n)
    hi = int(hi_frac * n)
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(nblk_lo, nblk_hi))
    cuts = np.sort(rng.choice(np.arange(1, W), size=nblocks - 1, replace=False))
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    if zero_fill:
        win = h[lo:hi]
        pos = win[win > 0]
        if pos.size > 0:
            local_mean = pos.mean()
            z = win <= 0
            if np.any(z):
                win[z] = 1e-3 * local_mean
                h[lo:hi] = win
    return _rescale(h)


def _densify(h, start_arr):
    """Upsample factor 2 by linear interpolation; keep best of old vs new."""
    n = h.size
    if n >= 500000:
        return h
    xs_old = np.linspace(0.0, 1.0, n, endpoint=False) + 0.5 / n
    xs_new = np.linspace(0.0, 1.0, 2 * n, endpoint=False) + 0.25 / n
    h2 = np.interp(xs_new, xs_old, h)
    h2 = _rescale(h2)
    if R_of(h2) >= R_of(h):
        return h2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(512)
        best = _smooth_polish(best, deadline, [30.0, 60.0, 120.0, 300.0])
        return best

    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    cur = start_arr.copy()
    cur_r = best_r

    # Quick sharpening of the given start.
    if time.process_time() < hard_end - 1.0:
        c = _smooth_polish(cur, hard_end, [30.0, 15.0, 7.0])
        if R_of(c) > cur_r:
            cur, cur_r = c, R_of(c)
            _consider(cur, cur_r)

    rng = np.random.default_rng(int(t0 * 1e6) % (2**31))
    it = 0
    while time.process_time() < hard_end - 1.0:
        it += 1
        choice = it % 4
        if choice == 0:
            h = _perturb_window(cur, rng, 0.0, 0.50, 0.30, zero_fill=True)
        elif choice == 1:
            h = _perturb_window(cur, rng, 0.55, 1.0, 0.25, zero_fill=True)
        elif choice == 2:
            h = _perturb_window(cur, rng, 0.0, 1.0, 0.15)
        else:
            h = _perturb_window(cur, rng, 0.75, 1.0, 0.20, nblk_lo=3, nblk_hi=6,
                                zero_fill=True)

        Lf = _knots(h)
        mx = Lf.max()
        if mx > 0:
            frac_near = np.mean(Lf >= 0.999 * mx)
        else:
            frac_near = 1.0
        if frac_near > 0.05:
            betas = [30.0, 80.0, 200.0]
        else:
            betas = [100.0, 300.0, 700.0]

        for beta in betas:
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_log(h, maxiter=250, deadline=hard_end, beta=beta)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(h, maxiter=500, deadline=hard_end, beta=0.0)
            if R_of(c) >= R_of(h):
                h = c
        for frac, extra in ((0.30, 16), (0.15, 8)):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _window_polish_peak(h, hard_end, frac, extra, maxiter=350)
            if R_of(c) >= R_of(h):
                h = c
        r = R_of(h)
        _consider(h, r)
        if r > cur_r:
            cur, cur_r = best.copy(), best_r

    # NEW: densify the best construction and re-polish, then tie-aware polish.
    if time.process_time() < hard_end:
        cand = _densify(best, start_arr)
        if cand.size != best.size:
            c = _smooth_polish(cand, hard_end, [30.0, 10.0, 3.0])
            _consider(c, R_of(c))
            # tie-aware block polish on denser grid
            if time.process_time() < hard_end - 1.0:
                c2 = _lbfgs_log(best, maxiter=800, deadline=hard_end, beta=0.0)
                _consider(c2, R_of(c2))
            if time.process_time() < hard_end - 1.0:
                c3 = _window_polish_peak(best, hard_end, 0.5, 64,
                                         maxiter=600, tie=True)
                _consider(c3, R_of(c3))

    # Final polish of best.
    if time.process_time() < hard_end:
        c = _smooth_polish(best, hard_end + 0.5, [10.0, 3.0, 1.0, 0.3])
        if R_of(c) > best_r:
            best, best_r = c, R_of(c)

    if start_arr is not None and R_of(start_arr) > best_r:
        best = start_arr.copy()
        best_r = R_of(best)

    print("main R=%.6f N=%d iters=%d" % (best_r, best.size, it))

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None and alt_r < best_r and start_arr is not None \
            and alt_r > R_of(start_arr):
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _band_mask(h, lo_frac, hi_frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    v = Lf[:h.size]
    return (v >= lo_frac * mx) & (v < hi_frac * mx)


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def _sym_polish(h, deadline, iters=400):
    n = h.size
    if n < 8:
        return h
    half = (n + 1) // 2
    hs = h.copy()
    if n % 2 == 0:
        a = hs[:half]
        b = hs[half:][::-1]
        hs[:half] = 0.5 * (a + b)
        hs[half:] = hs[:half][::-1]
    else:
        a = hs[:half]
        b = hs[half:][::-1]
        hs[:half] = 0.5 * (a + b)
        hs[half:] = hs[:half][::-1]
    hs = _rescale(hs)
    r_orig = R_of(h)
    if time.process_time() >= deadline - 0.5:
        return h

    def f(x):
        hh = np.empty(n)
        hh[:half] = np.clip(x, 0.0, None)
        if n % 2 == 0:
            hh[half:] = hh[:half][::-1]
        else:
            hh[half:] = hh[:half - 1][::-1]
        val, g = _fun_grad_tie(hh)
        ghalf = g[:half].copy()
        if n % 2 == 0:
            ghalf = ghalf + g[half:][::-1]
        else:
            ghalf[:-1] += g[half:][::-1]
        return val, ghalf

    x0 = hs[:half].copy()
    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * half,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    hh = np.empty(n)
    hh[:half] = np.clip(res.x, 0.0, None)
    if n % 2 == 0:
        hh[half:] = hh[:half][::-1]
    else:
        hh[half:] = hh[:half - 1][::-1]
    hh = _rescale(hh)
    if R_of(hh) > r_orig + 1e-15:
        return hh
    return h


# ---------- NEW: exact-R quotient L-BFGS on block-coherent directions ----------

def _detect_block(h, p):
    n = h.size
    m = n // p
    if m < 2:
        return None
    if n % p != 0:
        return None
    c = h.reshape(m, p).mean(axis=1)
    if np.allclose(h, np.repeat(c, p), rtol=1e-9, atol=1e-12):
        return c
    return None


def _quotient_lbfgs(c0, p, maxiter, deadline):
    """L-BFGS on quotient c with exact-R objective and block-summed gradient."""
    m = c0.size
    if m < 2:
        return c0

    def f(x):
        c = np.clip(x, 0.0, None)
        h = np.repeat(c, p)
        val, g = _fun_grad_tie(h)
        gc = g.reshape(m, p).sum(axis=1)
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c0.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * m,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.clip(res.x, 0.0, None)


def _quotient_phase(best, bestR, p, deadline, maxiter=600):
    """Try quotient L-BFGS at block size p. Returns (best, bestR, improved)."""
    if time.process_time() >= deadline - 0.5:
        return best, bestR, False
    c = _detect_block(best, p)
    if c is None:
        # try to coarsen by block means anyway
        n = best.size
        m = n // p
        if m < 2:
            return best, bestR, False
        c = best[:m * p].reshape(m, p).mean(axis=1)
    cR0 = R_of(np.repeat(c, p))
    c2 = _quotient_lbfgs(c, p, maxiter, deadline)
    h2 = _rescale(np.repeat(c2, p))
    r2 = R_of(h2)
    cR1 = R_of(np.repeat(c2, p))
    print("quot p=%d coarseR %.9f->%.9f fullR %.9f->%.9f"
          % (p, cR0, cR1, bestR, r2))
    if r2 > bestR + 1e-15:
        return h2, r2, True
    return best, bestR, False


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase Q: quotient L-BFGS at p=32, then 16, then 8 ----
    q_end = t0 + budget_seconds * 0.40
    for p in (32, 16, 8):
        if time.process_time() >= q_end - 1.0:
            break
        best, bestR, imp = _quotient_phase(best, bestR, p, q_end, maxiter=600)
        if imp:
            print("quot ACCEPT p=%d R=%.9f" % (p, bestR))

    # ---- Phase S: symmetric polish ----
    sym_end = t0 + budget_seconds * 0.55
    if time.process_time() < sym_end - 2.0:
        hs = _sym_polish(best, sym_end, iters=600)
        rs = R_of(hs)
        if rs > bestR + 1e-15:
            best, bestR = hs.copy(), rs
            print("sym polish ACCEPT R=%.9f" % bestR)
        else:
            print("sym polish no gain (R=%.9f)" % rs)

    # ---- Phase P: peak ladder ----
    peak_end = t0 + budget_seconds * 0.80
    pads = (0.12, 0.08, 0.05, 0.03, 0.02, 0.012, 0.008)
    for pad in pads:
        if time.process_time() >= peak_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie in ((1e7, False), (0.0, True), (0.0, False)):
            if time.process_time() >= peak_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(peak_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        f01, f1, f5 = _nearmax_fracs(best)
        print("peak pad=%.3f R=%.9f near=%.3f/%.3f/%.3f"
              % (pad, bestR, f01, f1, f5))

    # ---- Phase T: band polish ----
    band_end = t0 + budget_seconds * 0.90
    band_edges = [(0.0, 0.02), (0.02, 0.10), (0.10, 0.30),
                  (0.30, 0.60), (0.60, 0.85), (0.85, 0.97), (0.97, 1.001)]
    cyc = 0
    rng = np.random.default_rng(999)
    while time.process_time() < band_end - 1.5:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        gains = []
        order = rng.permutation(len(band_edges))
        for bi in order:
            if time.process_time() >= band_end - 1.0:
                break
            lo, hi = band_edges[bi]
            sel = np.flatnonzero((best > 0) & (v >= lo * M) & (v < hi * M))
            if sel.size == 0:
                gains.append(0.0)
                continue
            active = _dilate(sel, n, 12)
            if active.size < 16 or active.size > 0.85 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 250,
                              min(band_end - 0.5,
                                  time.process_time() + 4.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
        print("band cyc=%d R=%.9f gains=%s"
              % (cyc, bestR, " ".join("%.1e" % g for g in gains)))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase F: final short full-N peak-window tie polish at pad 0.02 ----
    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 1.5:
        win = _peak_window(best, pad_frac=0.02, extra=48)
        ht = _lbfgs_block(best, win, 200,
                          min(fd - 0.5, time.process_time() + 2.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return -1.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size, hi + pad)
    return np.arange(lo, hi)


def _prolongate(h, Nnew):
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew)
    edges = np.linspace(0.0, N, Nnew + 1)
    m = np.interp(edges, np.arange(N + 1), c)
    return np.maximum(np.diff(m), 0.0)


def _polish(h, deadline, levels=(0.0, 1e3, 1e4)):
    best = np.asarray(h, dtype=float)
    bestR = R_of(best)
    for beta in levels:
        if time.process_time() > deadline - 0.5:
            break
        cand = _lbfgs_all_pos(best, maxiter=400, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(best)
        cand = _lbfgs_block(best, win, maxiter=300, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
    return best, bestR


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    near5 = np.mean(Lf >= 0.95 * mx) if mx > 0 else 0.0
    zf = np.mean(h <= 0.0)
    return zf, near5


def _revive_zeros(h, frac=0.05, amp=0.01):
    """Rank zero cells by one-sided derivative of log R and revive top frac."""
    h = np.clip(h, 0, None)
    s = h.sum()
    if s <= 0:
        return h
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    # one-sided derivative wrt increasing h[i] from 0 is grad[i] (val decreasing => -grad)
    zeros = np.flatnonzero(h <= 1e-14)
    if zeros.size == 0:
        return h
    # we want to increase h where d(-logR)/dh < 0 => grad > 0
    score = grad[zeros]
    k = max(1, int(round(frac * zeros.size)))
    order = np.argsort(-score)[:k]
    sel = zeros[order]
    active_mean = h[h > 0].mean() if np.any(h > 0) else 1.0
    h2 = h.copy()
    h2[sel] = amp * active_mean
    return h2


def _lift(h, factor=2.0):
    """2x lift: raise a band of cells to sharpen the flat top."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    # cells whose contribution sits under the near-max region: lift by factor
    # find peak region in f*f, map back approximately to cells
    idx = np.flatnonzero(Lf >= 0.95 * mx)
    if idx.size == 0:
        return h
    lo = max(0, idx.min() - 1)
    hi = min(h.size, idx.max())
    h2 = h.copy()
    h2[lo:hi] *= factor
    return h2


def main_construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best_h = None
    best_R = -1.0
    start_h = None
    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_h = s.copy()
            start_R = R_of(s)
            best_h = s.copy()
            best_R = start_R

    if best_h is None:
        best_h = np.ones(64)
        best_R = R_of(best_h)

    # Stage 1: polish the start at its own resolution
    if start_h is not None and time.process_time() < deadline - 2.0:
        h, r = _polish(start_h, min(deadline - 1.0, time.process_time() + 8.0))
        if r > best_R:
            best_R = r
            best_h = h
        print("start polish: %.6f" % best_R)

    # Stage 2: escalate resolutions with polishing
    targets = [8192, 16384, 32768, 65536]
    for Ntarget in targets:
        if time.process_time() > deadline - 2.0:
            break
        h = _prolongate(best_h, Ntarget)
        h, r = _polish(h, deadline)
        if r > best_R:
            best_R = r
            best_h = h
        print("escalated R at N=%d: %.6f" % (Ntarget, best_R))

    # Stage 3: final tight polish at current size
    if time.process_time() < deadline - 0.5:
        h, r = _polish(best_h, deadline, levels=(0.0, 1e4, 1e5))
        if r > best_R:
            best_R = r
            best_h = h

    zf, n5 = _stats(best_h)
    print("pre-experiment R: %.6f N=%d zero=%.3f near5=%.3f" % (best_R, best_h.size, zf, n5))

    # === EXPERIMENT: revival + lift at N=32768 ===
    if time.process_time() < deadline - 1.0:
        # work at N=32768
        N0 = 32768
        if best_h.size != N0:
            h = _prolongate(best_h, N0)
        else:
            h = best_h.copy()
        h, r = _polish(h, min(deadline - 0.5, time.process_time() + 6.0),
                       levels=(0.0, 1e3))
        base_r = r
        # revival
        hr = _revive_zeros(h, frac=0.05, amp=0.01)
        hr, rr = _polish(hr, min(deadline - 0.5, time.process_time() + 8.0),
                         levels=(1e3, 1e5, 1e7))
        if rr > r:
            h, r = hr, rr
        # lift
        hl = _lift(h, factor=2.0)
        hl, rl = _polish(hl, min(deadline - 0.5, time.process_time() + 8.0),
                         levels=(1e3, 1e5, 1e7))
        if rl > r:
            h, r = hl, rl
        # tie polish
        ht = _lbfgs_all_pos(h, maxiter=300, deadline=deadline, beta=0.0)
        rt = R_of(ht)
        if rt > r:
            h, r = ht, rt
        if r > best_R:
            best_R = r
            best_h = h
        zf, n5 = _stats(best_h)
        print("after revival+lift R: %.6f zero=%.3f near5=%.3f" % (best_R, zf, n5))

    # === EXPERIMENT: escalate to N=65536 with beta ladder + peak polishes ===
    if time.process_time() < deadline - 1.0:
        h = _prolongate(best_h, 65536)
        for beta in (1e3, 1e4, 1e5, 1e6, 1e7):
            if time.process_time() > deadline - 1.0:
                break
            cand = _lbfgs_all_pos(h, maxiter=200, deadline=deadline, beta=beta)
            rc = R_of(cand)
            if rc > best_R:
                best_R = rc
                best_h = cand
                h = cand
        ht = _lbfgs_all_pos(best_h, maxiter=300, deadline=deadline, beta=0.0)
        rt = R_of(ht)
        if rt > best_R:
            best_R = rt
            best_h = ht
        # peak-window polishes
        for pad in (0.08, 0.04, 0.02):
            if time.process_time() > deadline - 0.5:
                break
            win = _peak_window(best_h, tol=0.999, pad_frac=pad, extra=64)
            cand = _lbfgs_block(best_h, win, maxiter=300, deadline=deadline, beta=0.0)
            rc = R_of(cand)
            if rc > best_R:
                best_R = rc
                best_h = cand
        zf, n5 = _stats(best_h)
        print("after N=65536 R: %.6f zero=%.3f near5=%.3f" % (best_R, zf, n5))

    # final tight polish
    if time.process_time() < deadline - 0.5:
        h, r = _polish(best_h, deadline, levels=(0.0, 1e4, 1e5))
        if r > best_R:
            best_R = r
            best_h = h

    zf, n5 = _stats(best_h)
    print("final R: %.6f N=%d zero=%.3f near5=%.3f" % (best_R, best_h.size, zf, n5))

    if start_h is not None and start_R >= best_R:
        return start_h
    if start_h is not None and start_R > 0 and best_h is not None and best_R - start_R > 1e-6:
        return {"best": best_h, "alternative": start_h}
    return best_h


def construct(budget_seconds, start):
    try:
        return main_construct(budget_seconds, start)
    except Exception:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(64)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _interp_resample(h, N2):
    N1 = h.size
    if N1 == N2:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(N2)
    xs = np.linspace(0.0, N1, N2 + 1)
    cm = np.interp(xs, np.arange(N1 + 1), c)
    return np.diff(cm)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # KEY NEW IDEA: UP-SAMPLE the current best onto a denser grid, then
    # re-optimise globally.  More degrees of freedom near the plateau allow
    # the peak to sharpen, which is what limits R.
    n_cur = best.size
    # target up to ~4x finer, capped
    for factor in (2, 2):
        now = time.process_time()
        if now >= deadline - 3.0:
            break
        N2 = min(400000, n_cur * factor)
        if N2 <= n_cur:
            break
        hup = _interp_resample(best, N2)
        hup = _rescale(hup)
        rup = R_of(hup)
        if rup < bestR - 1e-3:
            # resampling lost too much; skip
            break
        print("upsample N=%d R=%.7f" % (N2, rup))
        # global L-BFGS on the finer grid (with tie-aware plateau grad)
        sub_deadline = min(deadline - 2.0, now + (deadline - now) * 0.55)
        h2 = _lbfgs_block(hup, np.arange(N2), 600, sub_deadline, tie=True)
        r2 = R_of(h2)
        print("  after global R=%.7f (dR=%.2e)" % (r2, r2 - bestR))
        if r2 > bestR + 1e-12:
            best, bestR, n_cur = h2, r2, N2
        else:
            # keep the finer resolution anyway if not much worse -- allows next round
            if r2 > bestR - 1e-4:
                best, bestR, n_cur = h2, r2, N2
            else:
                break

    # Local peak-window polishing with tie-aware gradient.
    for stage in range(4):
        now = time.process_time()
        if now >= deadline - 1.5:
            break
        win = _peak_window(best, tol=0.9995, pad_frac=0.3, extra=512)
        sub_deadline = min(deadline - 1.0, now + (deadline - now) * 0.5)
        h2 = _lbfgs_block(best, win, 400, sub_deadline, tie=True)
        r2 = R_of(h2)
        print("peak stage %d R=%.7f dR=%.2e" % (stage, r2, r2 - bestR))
        if r2 > bestR + 1e-13:
            best, bestR = h2, r2
        else:
            break

    # Final full-grid touch with tie-aware gradient over all entries.
    now = time.process_time()
    if now < deadline - 0.6:
        h2 = _lbfgs_block(best, np.arange(best.size), 400, deadline - 0.3, tie=True)
        r2 = R_of(h2)
        if r2 > bestR + 1e-14:
            best, bestR = h2, r2

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if start is not None:
        sR = R_of(np.clip(np.asarray(start, dtype=float), 0, None))
    else:
        sR = 0.0
    if bestR > sR + 1e-12:
        return best
    out = {"best": np.clip(np.asarray(start, dtype=float), 0, None) if start is not None else best}
    if bestR > sR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(256)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # Alternative candidate from upsampling refinement (genuinely different)
    alt = None

    # --- Phase 1: work on a finer grid (2x), refine there ---
    if time.process_time() < deadline - 25.0:
        N_up = min(cur.size * 2, 500000)
        up = _rescale(_prolongate(cur, N_up))
        up = _lbfgs_all(up, maxiter=400, deadline=deadline - 22.0)
        for beta in (8, 32, 128):
            if time.process_time() >= deadline - 20.0:
                break
            up2 = _lbfgs_all(up, maxiter=200, deadline=deadline - 20.0, beta=beta)
            if R_of(up2) > R_of(up):
                up = up2
        # peak window polish on the fine grid
        for tol, padf, ex in ((0.9995, 0.3, 64), (0.999, 0.5, 128)):
            if time.process_time() >= deadline - 18.0:
                break
            win = _peak_window(up, tol=tol, pad_frac=padf, extra=ex)
            up3 = _lbfgs_block(up, win, maxiter=300, deadline=deadline - 18.0)
            if R_of(up3) > R_of(up):
                up = up3
        up_r = R_of(up)
        print("fine-grid R = %.6f (N=%d)" % (up_r, N_up))
        alt = up.copy()

        # map back down and try to recover the fine-grid score at coarse N
        back = _rescale(_coarsen(up, cur.size))
        back = _lbfgs_all(back, maxiter=300, deadline=deadline - 16.0)
        back_r = R_of(back)
        if back_r > best_r:
            best, best_r = back.copy(), back_r
            cur, cur_r = back.copy(), back_r
        if up_r > best_r:
            best, best_r = up.copy(), up_r
            cur, cur_r = up.copy(), up_r

    # --- Phase 2: alternate full L-BFGS, peak-window polish, beta continuation ---
    last_r = cur_r
    no_improve = 0
    restart_tries = 0
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_all(cur, maxiter=800, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        # Peak-window polish at increasing widths
        for tol, padf, ex in ((0.9999, 0.2, 32), (0.9995, 0.4, 64),
                              (0.999, 0.6, 128)):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cur, tol=tol, pad_frac=padf, extra=ex)
            cand = _lbfgs_block(cur, win, maxiter=400, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        # Soft-max continuation to sharpen the peak
        if time.process_time() < deadline - 3.0:
            b = 256.0
            cand = _lbfgs_all(cur, maxiter=200, deadline=deadline, beta=b)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-10:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                # Try smoothing continuation from best
                improved = False
                for k in (3, 5, 9):
                    if time.process_time() >= deadline - 3.0:
                        break
                    seed = _rescale(_smooth(best, k))
                    seed = _lbfgs_all(seed, maxiter=500, deadline=deadline)
                    rs = R_of(seed)
                    if rs > cur_r:
                        cur, cur_r = seed, rs
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                        improved = True
                        break
                if not improved:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.15))
                    cand_p = _lbfgs_all(_rescale(perturbed), maxiter=600,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt is not None and alt.size != best.size and R_of(alt) > best_r:
            out["alternative"] = alt
        else:
            out["alternative"] = start_arr
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline,
                        beta=beta, tie=tie)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    return np.arange(max(0, lo - pad), min(h.size - 1, hi + pad) + 1)


# ----------------------------------------------------------------------------
# New idea: adaptive-resolution coarsening (variable-block quotient).
#
# Rather than halving (block=2), we sum runs of variable length via a
# piecewise-constant "block map" derived from the support structure.
# On the coarse representation the problem is far cheaper per iteration;
# optimising there explores a genuinely different basin.  We then lift
# back (uniform split within each block) and polish at full resolution.
# ----------------------------------------------------------------------------

def _build_blockmap(h, target):
    """Return array blk of length h.size giving block index per element."""
    n = h.size
    if target >= n:
        return np.arange(n)
    # weight by (h>0) + small mass so blocks stay near support
    w = (h > 0).astype(float) + 1e-3 * (h / (h.max() + 1e-30))
    cw = np.cumsum(w)
    total = cw[-1]
    # target breakpoints evenly in cumulative weight
    edges = np.linspace(0, total, target + 1)
    idx = np.searchsorted(cw, edges)
    idx[0] = 0
    idx[-1] = n
    blk = np.zeros(n, dtype=np.int64)
    for k in range(target):
        blk[idx[k]:idx[k + 1]] = k
    return blk


def _fold_by_blk(h, blk):
    K = int(blk.max()) + 1
    c = np.zeros(K)
    np.add.at(c, blk, h)
    return c


def _lift_by_blk(c, blk):
    K = int(blk.max()) + 1
    counts = np.bincount(blk, minlength=K).astype(float)
    counts[counts == 0] = 1.0
    return c[blk] / counts[blk]


def _polish(h, deadline, rounds=3):
    best = h.copy()
    bestR = R_of(best)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all(best, 200, deadline - 0.3, beta=0.0, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
        else:
            break
        for frac, extra, beta in [(0.20, 128, 1e7), (0.40, 256, 1e8)]:
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=frac, extra=extra)
            ht = _lbfgs_block(best, win, 150, deadline - 0.3, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt = None
    altR = -1.0

    # ---- Phase 1: adaptive-resolution coarsening at several scales ----
    n = best.size
    targets = [t for t in (2048, 4096, 8192, 16384, 32768) if t < n]
    coarsened_winners = []
    for target in targets:
        if time.process_time() >= deadline - 8.0:
            break
        try:
            blk = _build_blockmap(best, target)
            c = _fold_by_blk(best, blk)
            # optimise on coarse rep
            cc = c.copy()
            rc = R_of(cc)
            for beta in (1e5, 1e6, 1e7):
                if time.process_time() >= deadline - 8.0:
                    break
                ht = _lbfgs_all(cc, 250, deadline - 7.0, beta=beta)
                r = R_of(ht)
                if r > rc + 1e-14:
                    cc, rc = ht, r
            lifted = _lift_by_blk(cc, blk)
            rl = R_of(lifted)
            print("coarse t=%d cR=%.7f liftR=%.7f" % (target, rc, rl))
            coarsened_winners.append((rl, lifted))
            if rl > bestR + 1e-12:
                hp, rp = _polish(lifted, deadline - 6.0, rounds=2)
                if rp > bestR + 1e-13:
                    best, bestR = hp, rp
                    print("  wins: R=%.7f" % bestR)
        except Exception as e:
            print("coarse t=%d failed: %s" % (target, e))

    # keep the best coarse candidate as alternative
    for rl, cand in coarsened_winners:
        if rl > altR:
            altR, alt = rl, cand

    # ---- Phase 2: full-resolution polish ----
    if time.process_time() < deadline - 3.0:
        best, bestR = _polish(best, deadline - 2.0, rounds=4)
        print("polish R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Phase 3: dip-based escaping moves ----
    stats = {'dips': 0, 'acc': 0, 'raw': -1e9}
    if time.process_time() < deadline - 4.0:
        best, bestR = _dip_loop(best, bestR, deadline - 3.0, stats)
        print("dips=%d acc=%d raw=%.2e R=%.7f" %
              (stats['dips'], stats['acc'], stats['raw'], bestR))

    # ---- Phase 4: final polish ----
    if time.process_time() < deadline - 0.5:
        best, bestR = _polish(best, deadline - 0.4, rounds=3)
        print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-4:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out


def _dip_loop(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:16]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 16)

    best_h = None
    best_r = bestR
    info = None
    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] += t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    info = (a, b)
    stats['raw'] = max(stats['raw'], best_r - bestR)
    if best_h is None:
        return best, bestR
    a, b = info
    lo = max(0, min(a, b) - 96)
    hi = min(n - 1, max(a, b) + 96)
    hp = _lbfgs_block(best_h, np.arange(lo, hi + 1), 60, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['acc'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['acc'] += 1
        return best_h, best_r
    return best, bestR

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


# ---------- NEW: max-free flatness objective ----------
def _fun_grad_flat(h):
    """Maximise sum L^2 / (sum L)^2  <=>  minimise -log(sum L^2) + 2 log(sum L).
    No max term, no tie, no beta. Different vector field from exact-R."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    # d/dh of -log(num) + 2 log(s):
    #   -log(num): -1/num * d(num)/dh ; num = sum L^2 -> d num/d L = 2L
    #   so gLf = -2 Lf / num ; then backprop
    #   2 log(s): +2/s
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _band_mask(h, lo_frac, hi_frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    v = Lf[:h.size]
    return (v >= lo_frac * mx) & (v < hi_frac * mx)


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def _sym_polish(h, deadline, iters=400):
    n = h.size
    if n < 8:
        return h
    half = (n + 1) // 2
    hs = h.copy()
    if n % 2 == 0:
        a = hs[:half]
        b = hs[half:][::-1]
        hs[:half] = 0.5 * (a + b)
        hs[half:] = hs[:half][::-1]
    else:
        a = hs[:half]
        b = hs[half:][::-1]
        hs[:half] = 0.5 * (a + b)
        hs[half:] = hs[:half][::-1]
    hs = _rescale(hs)
    r_orig = R_of(h)
    if time.process_time() >= deadline - 0.5:
        return h

    def f(x):
        hh = np.empty(n)
        hh[:half] = np.clip(x, 0.0, None)
        if n % 2 == 0:
            hh[half:] = hh[:half][::-1]
        else:
            hh[half:] = hh[:half - 1][::-1]
        val, g = _fun_grad_tie(hh)
        ghalf = g[:half].copy()
        if n % 2 == 0:
            ghalf = ghalf + g[half:][::-1]
        else:
            ghalf[:-1] += g[half:][::-1]
        return val, ghalf

    x0 = hs[:half].copy()
    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * half,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    hh = np.empty(n)
    hh[:half] = np.clip(res.x, 0.0, None)
    if n % 2 == 0:
        hh[half:] = hh[:half][::-1]
    else:
        hh[half:] = hh[:half - 1][::-1]
    hh = _rescale(hh)
    if R_of(hh) > r_orig + 1e-15:
        return hh
    return h


def _detect_block(h, p):
    n = h.size
    m = n // p
    if m < 2:
        return None
    if n % p != 0:
        return None
    c = h.reshape(m, p).mean(axis=1)
    if np.allclose(h, np.repeat(c, p), rtol=1e-9, atol=1e-12):
        return c
    return None


def _quotient_lbfgs(c0, p, maxiter, deadline):
    m = c0.size
    if m < 2:
        return c0

    def f(x):
        c = np.clip(x, 0.0, None)
        h = np.repeat(c, p)
        val, g = _fun_grad_tie(h)
        gc = g.reshape(m, p).sum(axis=1)
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c0.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * m,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.clip(res.x, 0.0, None)


def _quotient_phase(best, bestR, p, deadline, maxiter=600):
    if time.process_time() >= deadline - 0.5:
        return best, bestR, False
    c = _detect_block(best, p)
    if c is None:
        n = best.size
        m = n // p
        if m < 2:
            return best, bestR, False
        c = best[:m * p].reshape(m, p).mean(axis=1)
    cR0 = R_of(np.repeat(c, p))
    c2 = _quotient_lbfgs(c, p, maxiter, deadline)
    h2 = _rescale(np.repeat(c2, p))
    r2 = R_of(h2)
    cR1 = R_of(np.repeat(c2, p))
    print("quot p=%d coarseR %.9f->%.9f fullR %.9f->%.9f"
          % (p, cR0, cR1, bestR, r2))
    if r2 > bestR + 1e-15:
        return h2, r2, True
    return best, bestR, False


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase Q: quotient L-BFGS at p=32, then 16, then 8 ----
    q_end = t0 + budget_seconds * 0.40
    for p in (32, 16, 8):
        if time.process_time() >= q_end - 1.0:
            break
        best, bestR, imp = _quotient_phase(best, bestR, p, q_end, maxiter=600)
        if imp:
            print("quot ACCEPT p=%d R=%.9f" % (p, bestR))

    # ---- Phase S: symmetric polish ----
    sym_end = t0 + budget_seconds * 0.55
    if time.process_time() < sym_end - 2.0:
        hs = _sym_polish(best, sym_end, iters=600)
        rs = R_of(hs)
        if rs > bestR + 1e-15:
            best, bestR = hs.copy(), rs
            print("sym polish ACCEPT R=%.9f" % bestR)
        else:
            print("sym polish no gain (R=%.9f)" % rs)

    # ---- Phase P: peak ladder (alternate flat with existing tie/beta) ----
    peak_end = t0 + budget_seconds * 0.80
    pads = (0.12, 0.08, 0.05, 0.03, 0.02, 0.012, 0.008)
    for pad in pads:
        if time.process_time() >= peak_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True),
                                (0.0, False, False)):
            if time.process_time() >= peak_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(peak_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if flat:
                acc = 1 if r > bestR + 1e-15 else 0
                print("flat R=%.9f accepted=%d" % (r, acc))
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        f01, f1, f5 = _nearmax_fracs(best)
        print("peak pad=%.3f R=%.9f near=%.3f/%.3f/%.3f"
              % (pad, bestR, f01, f1, f5))

    # ---- Phase T: band polish (alternate flat with tie) ----
    band_end = t0 + budget_seconds * 0.90
    band_edges = [(0.0, 0.02), (0.02, 0.10), (0.10, 0.30),
                  (0.30, 0.60), (0.60, 0.85), (0.85, 0.97), (0.97, 1.001)]
    cyc = 0
    rng = np.random.default_rng(999)
    while time.process_time() < band_end - 1.5:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        gains = []
        order = rng.permutation(len(band_edges))
        for bi in order:
            if time.process_time() >= band_end - 1.0:
                break
            lo, hi = band_edges[bi]
            sel = np.flatnonzero((best > 0) & (v >= lo * M) & (v < hi * M))
            if sel.size == 0:
                gains.append(0.0)
                continue
            active = _dilate(sel, n, 12)
            if active.size < 16 or active.size > 0.85 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            # alternate: tie then flat
            for use_flat in (False, True):
                if time.process_time() >= band_end - 0.8:
                    break
                ht = _lbfgs_block(best, active, 250,
                                  min(band_end - 0.5,
                                      time.process_time() + 4.0),
                                  tie=(not use_flat), flat=use_flat)
                r = R_of(ht)
                if use_flat:
                    acc = 1 if r > prevR + 1e-15 else 0
                    print("flat R=%.9f accepted=%d" % (r, acc))
                if r > prevR + 1e-15:
                    best, bestR = ht.copy(), r
                    prevR = r
            gains.append(max(0.0, prevR - R_of(best) + (bestR - prevR)))
        print("band cyc=%d R=%.9f gains=%s"
              % (cyc, bestR, " ".join("%.1e" % g for g in gains)))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase FLAT-FULL: full-array flat L-BFGS at 0.6 of budget ----
    flat_end = t0 + budget_seconds * 0.60
    if time.process_time() < flat_end - 1.0:
        n = best.size
        active = np.arange(n)
        ht = _lbfgs_block(best, active, 200,
                          min(flat_end - 0.5,
                              time.process_time() + 3.0),
                          flat=True)
        r = R_of(ht)
        acc = 1 if r > bestR + 1e-15 else 0
        print("flat R=%.9f accepted=%d" % (r, acc))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    # ---- Phase F: final short full-N peak-window tie polish at pad 0.02 ----
    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 1.5:
        win = _peak_window(best, pad_frac=0.02, extra=48)
        ht = _lbfgs_block(best, win, 200,
                          min(fd - 0.5, time.process_time() + 2.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    c = (m - 1) / 2.0
    n = h.size
    w = max(3, int(pad * n))
    lo = max(0, int(c - w))
    hi = min(n, int(c + w) + 1)
    if hi - lo < 2:
        return np.arange(n)
    return np.arange(lo, hi)


def _perturb(h, s, k):
    n = h.size
    idx = np.arange(n)
    E = np.cos(2.0 * np.pi * k * (idx + 0.5) / n)
    return _rescale(np.clip(h * (1.0 + s * E), 0.0, None))


def _prolongate(h, N2):
    """Mass-preserving cumulative resampling to N2 steps."""
    N1 = h.size
    if N1 == N2:
        return _rescale(np.clip(h, 0, None))
    M = float(N1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, M, N2 + 1)
    cum_at = np.interp(edges, np.arange(N1 + 1), cum)
    mass = np.diff(cum_at)
    out = mass * (M / N2)
    return _rescale(np.clip(out, 0.0, None))


def _revive_zeros(h):
    """Gradient-ranked zero revival: revive top 3% zero cells."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    zeros = np.flatnonzero(h <= 0)
    if zeros.size < 4:
        return h
    try:
        val, g = _fun_grad_tie(h)
    except Exception:
        return h
    # one-sided derivative of log R w.r.t. raising h[i] from 0
    score = g[zeros]
    k = max(1, int(0.03 * n))
    k = min(k, zeros.size)
    order = np.argsort(-score)
    pick = zeros[order[:k]]
    active_mean = h[h > 0].mean() if np.any(h > 0) else 1.0
    h2 = h.copy()
    h2[pick] = 0.02 * active_mean
    return _rescale(h2)


def _level_refine(h, level_deadline):
    best = h
    bestR = R_of(best)

    def time_left():
        return time.process_time() < level_deadline

    # (i) zero revival
    if time_left():
        cand = _revive_zeros(best)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # (ii) tie-aware full L-BFGS
    if time_left():
        cand = _lbfgs_all_pos(best, 300, level_deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # (iii) beta ladder
    for beta in (1e3, 1e5, 1e7):
        if not time_left():
            break
        cand = _lbfgs_all_pos(best, 150, level_deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # (iv) peak-window block tie polish
    for pad in (0.20, 0.12, 0.06, 0.03):
        if not time_left():
            break
        free = _peak_window(best, pad)
        cand = _lbfgs_block(best, free, 150, level_deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # (v) multiplicative cosine perturbations
    for s in (0.03, 0.08):
        for k in (1, 2):
            if not time_left():
                break
            cand = _perturb(best, s, k)
            free = _peak_window(cand, 0.04)
            cand = _lbfgs_block(cand, free, 150, level_deadline, tie=True)
            r = R_of(cand)
            if r > bestR + 1e-12:
                best, bestR = cand, r

    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.93 * budget_seconds

    best = None
    bestR = -1.0
    start_arr = None
    startR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.size >= 2 and s.sum() > 0:
            start_arr = s
            startR = R_of(s)
            best = s.copy()
            bestR = startR
            print("start R=%.6f N=%d" % (bestR, s.size))

    if best is None:
        n = 100
        x = (np.arange(n) + 0.5) / n
        h = np.exp(-40.0 * (x - 0.5) ** 2)
        best = _rescale(h)
        bestR = R_of(best)
        print("init bump R=%.6f" % bestR)

    # Extended resolution ladder
    ladder = [12800, 25600, 51200]
    work = best
    for li, N2 in enumerate(ladder):
        if time.process_time() >= deadline - 1.5:
            break
        levels_left = len(ladder) - li
        now = time.process_time()
        slice_end = now + max(0.5, (deadline - now) / levels_left)

        work = _prolongate(work, N2)
        work, r = _level_refine(work, slice_end)
        Lf = _knots(work)
        mx = Lf.max()
        zero_frac = float(np.mean(work <= 0))
        near01 = float(np.mean(Lf >= mx * 0.999))
        print("level N=%d R=%.9f zero=%.3f near01=%.3f" % (work.size, r, zero_frac, near01))
        if r > bestR:
            best, bestR = work.copy(), r

    # Final polishing on global best
    final_deadline = t0 + 0.97 * budget_seconds
    while time.process_time() < final_deadline - 1.0:
        free = _peak_window(best, 0.02)
        cand = _lbfgs_block(best, free, 150, final_deadline, tie=True)
        r = R_of(cand)
        if r > bestR + 1e-10:
            best, bestR = cand, r
            print("final pad0.02 R=%.9f N=%d" % (bestR, best.size))
        else:
            cand = _lbfgs_all_pos(best, 150, final_deadline, tie=True)
            r = R_of(cand)
            if r > bestR + 1e-10:
                best, bestR = cand, r
                print("final full R=%.9f N=%d" % (bestR, best.size))
            else:
                break

    best = _rescale(np.clip(best, 0, None))
    finalR = R_of(best)
    print("final R=%.9f N=%d" % (finalR, best.size))

    if start_arr is not None and startR >= finalR:
        return {"best": start_arr, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _neighbor_supports(h):
    """Return list of index arrays that cover the support of h, split into
    contiguous blocks (used for block-coordinate polishing)."""
    n = h.size
    sup = np.flatnonzero(h > 1e-12 * max(h.max(), 1e-300))
    if sup.size == 0:
        return []
    # split into contiguous runs
    runs = []
    start = sup[0]; prev = sup[0]
    for i in sup[1:]:
        if i != prev + 1:
            runs.append(np.arange(start, prev + 1))
            start = i
        prev = i
    runs.append(np.arange(start, prev + 1))
    return runs


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    alt = None
    altR = 0.0

    def try_update(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s R=%.7f" % (tag, bestR))
        else:
            if alt is None or r > altR:
                alt, altR = h, r

    # NEW STRATEGY: block-coordinate descent over the support runs, plus
    # softmax continuation with a wider beta ladder.  The support of an
    # optimal f often has several separated components; optimizing each
    # component separately (with the others fixed) lets mass migrate between
    # components, escaping the single-peak local optimum that the previous
    # program was stuck in.

    # Phase 1: softmax continuation (wider ladder) on full vector
    schedules = [(0.999, 30.0), (0.9993, 100.0), (0.9996, 400.0),
                 (0.99985, 1500.0), (0.99995, 6000.0)]
    for c, beta in schedules:
        if time.process_time() >= deadline - 8.0:
            break
        fg = (lambda c=c, beta=beta: (lambda hh: _fun_grad_Q(hh, c, beta)))()
        h = _lbfgs_log(best, 300, deadline, fg=fg)
        try_update(h, "soft(c=%.4f,b=%g)" % (c, beta))

    # Phase 2: block-coordinate descent over support runs
    stall = 0
    while time.process_time() < deadline - 2.0:
        improved = False
        runs = _neighbor_supports(best)
        # sort runs by descending total mass (bigger first)
        runs = sorted(runs, key=lambda r: -best[r].sum())
        for run in runs:
            if time.process_time() >= deadline - 1.5:
                break
            h = _lbfgs_block(best, run, 200, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                improved = True
                print("blk R=%.7f (support %d)" % (bestR, run.size))
        if not improved:
            stall += 1
            if stall >= 1:
                break
        else:
            stall = 0

    # Phase 3: peak-window polish on best
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        for frac in (0.05, 0.12, 0.25):
            if time.process_time() >= deadline - 1.5:
                break
            free = _peak_window(best, frac=frac)
            h = _lbfgs_block(best, free, 400, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                improved = True
                print("win(%.2f) R=%.7f" % (frac, bestR))
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if start is not None:
        try:
            startR = R_of(np.asarray(start, dtype=float))
        except Exception:
            startR = 0.0
        if alt is not None and altR > 0 and bestR <= startR + 1e-12:
            return {"best": best, "alternative": alt}
    return best

