    n = h.size
    lo = max(0, idx.min() - 1 - n // 20)
    hi = min(n - 1, idx.max() + n // 20)
    return np.arange(lo, hi + 1)


def _smooth(h, k=3):
    if h.size < 2 * k + 1:
        return h
    ker = np.ones(2 * k + 1) / (2 * k + 1)
    hs = np.convolve(h, ker, mode='same')
