            print("FINAL tie ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 400, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL argmax no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    # If the new idea produced a genuinely different construction that
    # doesn't beat start, offer it as "alternative" so a new line of search
    # can start from it.
    if start is not None and bestR <= startR + 1e-14 and candidates:
        alt = max(candidates, key=lambda t: t[0])[1]
        if alt.size != best.size or np.max(np.abs(alt - best)) > 1e-9:
            result["alternative"] = alt
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _fold_to(c, m):
    L = c.size
    cum = np.concatenate(([0.0], np.cumsum(c)))
    total = cum[-1]
    if total <= 0:
        return np.ones(m)
    edges = np.arange(m + 1) / m * L
    mass = np.interp(edges, np.arange(L + 1), cum)
    out = np.diff(mass) * (m / L)
    return np.clip(out, 0, None)


def _sample_centres(c, L):
    m = c.size
    cum = np.concatenate(([0.0], np.cumsum(c)))
    total = cum[-1]
    if total <= 0:
        return np.ones(L)
    edges = np.concatenate(([0.0], np.arange(1, L) / L, [1.0]))
    epos = edges * m
    mass = np.interp(epos, np.arange(m + 1), cum)
    dens = np.diff(mass) * (L / m)
    return np.clip(dens, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
            start_bestR = bestR
        else:
            best, bestR, start_bestR = None, 0.0, 0.0
    else:
        best, bestR, start_bestR = None, 0.0, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
        start_bestR = bestR

    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif cand.size == best.size and r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # Phase A: exploit non-commensurate lift at 5:4 ratio (NEW key change).
    # We sample the current shape finely at 5/4 resolution, perturb with
    # log-normal weights, polish with high beta, fold back and re-expand.
    rng = np.random.default_rng(2024)
    lift_deadline = deadline - 6.0
    round_i = 0
    while round_i < 4 and time.process_time() < lift_deadline:
        round_i += 1
        N = best.size
        m = N
        c = best.copy()
        c = _polish_ladder(c, lift_deadline, betas=(1e7, 0.0), iters=300)
        c = _peak_ladder(c, lift_deadline, pads=(0.12, 0.08), iters=300)
        # 5:4 lift
        L = (5 * m) // 4
        if L < 8 or L > 1000000:
            break
        fine = _sample_centres(c, L)
        sig = 0.35
        w = np.exp(rng.normal(0.0, sig, L))
        w = np.clip(w, 0.3, 4.0)
        fine = _rescale(fine * w)
        fine = _polish_ladder(fine, lift_deadline,
                              betas=(1e5, 1e6, 1e7, 0.0), iters=300)
        fine = _peak_ladder(fine, lift_deadline,
                            pads=(0.10, 0.06), iters=300)
        # fold back to m
        c2 = _fold_to(fine, m)
        c2 = _rescale(c2)
        c2 = _polish_ladder(c2, lift_deadline, betas=(1e6, 1e7, 0.0), iters=300)
        # expand back to N with fresh random weights
        hN = _sample_centres(c2, N)
        w2 = np.exp(rng.normal(0.0, 0.35, N))
        w2 = np.clip(w2, 0.3, 4.0)
        hN = _rescale(hN * w2)
        hN = _polish_ladder(hN, lift_deadline, betas=(1e7, 0.0), iters=300)
        hN = _peak_ladder(hN, lift_deadline, pads=(0.08, 0.05), iters=300)
        r = R_of(hN)
        print("lift54 round=%d R=%.9f (best %.9f) L=%d" % (round_i, r, bestR, L))
        if hN.size == best.size:
            offer(hN, 'lift54')

    # Phase B: half-resolution polish (kept from base but shorter)
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 4.0:
        c = best[0::2].copy()
        half_deadline = min(deadline - 4.0, time.process_time() + budget_seconds * 0.15)
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.20, 0.15, 0.10), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # Phase C: high-beta sharpening + tie-aware final polish
    if time.process_time() < deadline - 2.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # Phase D: final fine polish
    ht = _polish_ladder(best, deadline - 0.8, betas=(1e8, 0.0), iters=250)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=300)
    offer(ht, 'finalpk')
    ht = _lbfgs_all_pos(best, 300, deadline - 0.3, tie=True)
    offer(ht, 'finaltie')
    ht = _polish_ladder(best, deadline - 0.2, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- NEW: residue-class multiplier (w-mod) optimization ----------
def _wmod_block(h, p, maxiter, deadline):
    """Represent h[pm+j] = c[m]*w[j]. Optimize x=(log c, log w) unbounded."""
    n = h.size
    if n % p != 0:
        return h
    m = n // p
    if m < 2:
        return h
    H = h.reshape(m, p)
    c = H.mean(axis=1)
    if np.any(c <= 0):
        c = np.clip(c, 1e-12, None)
    # w = mean over m of H/c
    w = (H / c[:, None]).mean(axis=0)
    if np.any(w <= 0):
        w = np.clip(w, 1e-12, None)
    # re-center w to geometric mean 1, push into c
    lw = np.log(w)
    shift = lw.mean()
    lw = lw - shift
    c = c * np.exp(shift)
    w = np.exp(lw)

    def unpack(x):
        lc = x[:m]
        lw2 = x[m:]
        cc = np.exp(lc)
        ww = np.exp(lw2)
        # re-center ww to geometric mean 1
        sh = lw2.mean()
        if sh != 0.0:
            cc = cc * np.exp(sh)
            ww = ww * np.exp(-sh)
        return cc, ww

    def f(x):
        cc, ww = unpack(x)
        hh = (cc[:, None] * ww[None, :]).ravel()
        val, g = _fun_grad_tie(hh)
        G = g.reshape(m, p)
        # chain rule: h = c*w ; d/d log c[m] = sum_j G[m,j]*h[m,j]
        gc = (G * (cc[:, None] * ww[None, :])).sum(axis=1)
        gw = (G * (cc[:, None] * ww[None, :])).sum(axis=0)
        # account for re-centering: subtract mean of gw from gw, add to gc
        gm = gw.mean()
        gw = gw - gm
        gc = gc + gm
        return val, np.concatenate([gc, gw])

    x0 = np.concatenate([np.log(c), lw])
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    cc, ww = unpack(res.x)
    hh = (cc[:, None] * ww[None, :]).ravel()
    return _rescale(hh)


def _detect_p(h):
    """Find a period p such that h is (approximately) np.repeat(c, p)."""
    n = h.size
    for p in (32, 16, 8, 64, 24, 48):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-6, atol=1e-9):
            return p
    return 32


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- NEW Phase W: residue-class multiplier optimization ----
    w_end = t0 + budget_seconds * 0.72
    p = _detect_p(best)
    print("wmod p=%d" % p)
    for blk in range(3):
        if time.process_time() >= w_end - 1.5:
            break
        prevR = bestR
        ht = _wmod_block(best, p, 150, min(w_end - 0.5,
                                           time.process_time() + 20.0))
        r = R_of(ht)
        dR = r - prevR
        # compute wmax
        n = ht.size
        if n % p == 0:
            m = n // p
            H = ht.reshape(m, p)
            c = H.mean(axis=1)
            if np.all(c > 0):
                w = (H / c[:, None]).mean(axis=0)
                w = w / np.exp(np.mean(np.log(np.clip(w, 1e-30, None))))
                wmax = float(np.max(np.abs(w - 1.0)))
            else:
                wmax = 0.0
        else:
            wmax = 0.0
        print("wmod R=%.9f dR=%.2e wmax=%.3f" % (r, dR, wmax))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    # ---- Phase Q: quotient L-BFGS at p=32, then 16, then 8 ----
    q_end = t0 + budget_seconds * 0.80
    for pp in (32, 16, 8):
        if time.process_time() >= q_end - 1.0:
            break
        n = best.size
        if n % pp != 0:
            continue
        m = n // pp
        if m < 2:
            continue
        c0 = best.reshape(m, pp).mean(axis=1)
        cb = _make_cb(q_end - 0.3)

        def fq(x, m=m, pp=pp):
            c = np.clip(x, 0.0, None)
            h = np.repeat(c, pp)
            val, g = _fun_grad_tie(h)
            gc = g.reshape(m, pp).sum(axis=1)
            return val, gc

        try:
            res = minimize(fq, c0.copy(), jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * m, callback=cb,
                           options={'maxiter': 400, 'maxfun': 800,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            if res is not None:
                h2 = _rescale(np.repeat(np.clip(res.x, 0.0, None), pp))
                r2 = R_of(h2)
                if r2 > bestR + 1e-15:
                    best, bestR = h2, r2
                    print("quot p=%d ACCEPT R=%.9f" % (pp, bestR))
        except (TimeoutError, Exception):
            pass

    # ---- Phase P: peak ladder ----
    peak_end = t0 + budget_seconds * 0.88
    pads = (0.06, 0.03, 0.02, 0.012)
    for pad in pads:
        if time.process_time() >= peak_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= peak_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(peak_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---- Phase F: final short full-N peak-window tie polish ----
    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 1.5:
        win = _peak_window(best, pad_frac=0.02, extra=48)
        ht = _lbfgs_block(best, win, 200,
                          min(fd - 0.5, time.process_time() + 2.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


# ---------- NEW: band flatness objective (max-free) ----------

def _fun_grad_band(h, lo=0.35, hi=0.999):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    mask = (Lf >= lo * M) & (Lf < hi * M)
    d = M - Lf
    val = np.sum(mask * d * d) / (M * M)
    gLf = -2.0 * mask * d / (M * M)
    grad = _backprop(gLf, h)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_band(h0, free, maxiter, deadline, lo=0.35, hi=0.999):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_band(hh, lo, hi)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _band_mask_frac(h, lo=0.35, hi=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean((Lf >= lo * mx) & (Lf < hi * mx)))


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def _sym_polish(h, deadline, iters=400):
    n = h.size
    if n < 8:
        return h
    half = (n + 1) // 2
    hs = h.copy()
    if n % 2 == 0:
        a = hs[:half]
        b = hs[half:][::-1]
        hs[:half] = 0.5 * (a + b)
        hs[half:] = hs[:half][::-1]
    else:
        a = hs[:half]
        b = hs[half:][::-1]
        hs[:half] = 0.5 * (a + b)
        hs[half:] = hs[:half][::-1]
    hs = _rescale(hs)
    r_orig = R_of(h)
    if time.process_time() >= deadline - 0.5:
        return h

    def f(x):
        hh = np.empty(n)
        hh[:half] = np.clip(x, 0.0, None)
        if n % 2 == 0:
            hh[half:] = hh[:half][::-1]
        else:
            hh[half:] = hh[:half - 1][::-1]
        val, g = _fun_grad_tie(hh)
        ghalf = g[:half].copy()
        if n % 2 == 0:
            ghalf = ghalf + g[half:][::-1]
        else:
            ghalf[:-1] += g[half:][::-1]
        return val, ghalf

    x0 = hs[:half].copy()
    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * half,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    hh = np.empty(n)
    hh[:half] = np.clip(res.x, 0.0, None)
    if n % 2 == 0:
        hh[half:] = hh[:half][::-1]
    else:
        hh[half:] = hh[:half - 1][::-1]
    hh = _rescale(hh)
    if R_of(hh) > r_orig + 1e-15:
        return hh
    return h


def _detect_block(h, p):
    n = h.size
    m = n // p
    if m < 2:
        return None
    if n % p != 0:
        return None
    c = h.reshape(m, p).mean(axis=1)
    if np.allclose(h, np.repeat(c, p), rtol=1e-9, atol=1e-12):
        return c
    return None


def _quotient_lbfgs(c0, p, maxiter, deadline):
    m = c0.size
    if m < 2:
        return c0

    def f(x):
        c = np.clip(x, 0.0, None)
        h = np.repeat(c, p)
        val, g = _fun_grad_tie(h)
        gc = g.reshape(m, p).sum(axis=1)
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c0.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * m,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.clip(res.x, 0.0, None)


def _quotient_phase(best, bestR, p, deadline, maxiter=600):
    if time.process_time() >= deadline - 0.5:
        return best, bestR, False
    c = _detect_block(best, p)
    if c is None:
        n = best.size
        m = n // p
        if m < 2:
            return best, bestR, False
        c = best[:m * p].reshape(m, p).mean(axis=1)
    cR0 = R_of(np.repeat(c, p))
    c2 = _quotient_lbfgs(c, p, maxiter, deadline)
    h2 = _rescale(np.repeat(c2, p))
    r2 = R_of(h2)
    cR1 = R_of(np.repeat(c2, p))
    print("quot p=%d coarseR %.9f->%.9f fullR %.9f->%.9f"
          % (p, cR0, cR1, bestR, r2))
    if r2 > bestR + 1e-15:
        return h2, r2, True
    return best, bestR, False


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase Q: quotient L-BFGS at p=32, then 16, then 8 ----
    q_end = t0 + budget_seconds * 0.30
    for p in (32, 16, 8):
        if time.process_time() >= q_end - 1.0:
            break
        best, bestR, imp = _quotient_phase(best, bestR, p, q_end, maxiter=600)
        if imp:
            print("quot ACCEPT p=%d R=%.9f" % (p, bestR))

    # ---- Phase S: symmetric polish ----
    sym_end = t0 + budget_seconds * 0.42
    if time.process_time() < sym_end - 2.0:
        hs = _sym_polish(best, sym_end, iters=600)
        rs = R_of(hs)
        if rs > bestR + 1e-15:
            best, bestR = hs.copy(), rs
            print("sym polish ACCEPT R=%.9f" % bestR)
        else:
            print("sym polish no gain (R=%.9f)" % rs)

    # ---- Phase BAND: new band flatness objective + tie re-polish ----
    band_end = t0 + budget_seconds * 0.72
    pads = (0.12, 0.05, 0.02)
    for pad in pads:
        if time.process_time() >= band_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        prevR = bestR
        # band flatness step
        hb = _lbfgs_block_band(best, win, 250,
                               min(band_end - 0.5,
                                   time.process_time() + 4.0),
                               lo=0.35, hi=0.999)
        # tie re-polish over same window
        ht = _lbfgs_block(hb, win, 200,
                          min(band_end - 0.5,
                              time.process_time() + 4.0), tie=True)
        r = R_of(ht)
        mf = _band_mask_frac(hb, 0.35, 0.999)
        dR = r - prevR
        print("bandQ R=%.9f maskfrac=%.3f dR=%.2e" % (r, mf, dR))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    # ---- Phase P: peak ladder (existing) ----
    peak_end = t0 + budget_seconds * 0.86
    pads2 = (0.12, 0.08, 0.05, 0.03, 0.02, 0.012, 0.008)
    for pad in pads2:
        if time.process_time() >= peak_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie in ((1e7, False), (0.0, True), (0.0, False)):
            if time.process_time() >= peak_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(peak_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        f01, f1, f5 = _nearmax_fracs(best)
        print("peak pad=%.3f R=%.9f near=%.3f/%.3f/%.3f"
              % (pad, bestR, f01, f1, f5))

    # ---- Phase T: band polish (existing) ----
    band2_end = t0 + budget_seconds * 0.94
    band_edges = [(0.0, 0.02), (0.02, 0.10), (0.10, 0.30),
                  (0.30, 0.60), (0.60, 0.85), (0.85, 0.97), (0.97, 1.001)]
    cyc = 0
    rng = np.random.default_rng(999)
    while time.process_time() < band2_end - 1.5:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        gains = []
        order = rng.permutation(len(band_edges))
        for bi in order:
            if time.process_time() >= band2_end - 1.0:
                break
            lo, hi = band_edges[bi]
            sel = np.flatnonzero((best > 0) & (v >= lo * M) & (v < hi * M))
            if sel.size == 0:
                gains.append(0.0)
                continue
            active = _dilate(sel, n, 12)
            if active.size < 16 or active.size > 0.85 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 250,
                              min(band2_end - 0.5,
                                  time.process_time() + 4.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
        print("band cyc=%d R=%.9f gains=%s"
              % (cyc, bestR, " ".join("%.1e" % g for g in gains)))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase F: final short full-N peak-window tie polish ----
    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 1.5:
        win = _peak_window(best, pad_frac=0.02, extra=48)
        ht = _lbfgs_block(best, win, 200,
                          min(fd - 0.5, time.process_time() + 2.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _smooth(h, sigma):
    if sigma <= 0:
        return h
    r = int(np.ceil(3 * sigma))
    xs = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (xs / sigma) ** 2)
    k /= k.sum()
    hs = np.convolve(h, k, mode='same')
    return np.clip(hs, 0.0, None)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    startR = 0.0
    if start is not None:
        s_arr = np.clip(np.asarray(start, dtype=float), 0, None)
        if s_arr.size > 0 and s_arr.sum() > 0:
            startR = R_of(s_arr)
            best = _rescale(s_arr)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: refine the peak with the smooth-max (beta) objective.  The
    # plain max objective has a single dominant active knot; the softmax
    # spreads gradient over the whole near-max plateau, letting the optimiser
    # grow a flat top instead of a sharp spike.  This is the key to beating
    # the sharp-peak local optimum.  We anneal beta from small to large.
    alt_best = best.copy()
    alt_R = bestR
    for beta in (20.0, 60.0, 150.0, 400.0):
        if time.process_time() >= deadline - 4.0:
            break
        h = _window_polish_peak(best, deadline, 0.45, 32, maxiter=250, beta=beta)
        r = R_of(h)
        print("beta %.0f R=%.7f" % (beta, r))
        if r > alt_R + 1e-15:
            alt_best, alt_R = h, r
            best, bestR = h, r

    # Peak-polish loop with mixed objectives to exploit the flat-top basin.
    for frac, extra, beta in ((0.10, 4, 0.0), (0.20, 8, 100.0),
                              (0.35, 16, 0.0), (0.50, 32, 200.0),
                              (0.75, 64, 0.0)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra, beta=beta)
        h = _lbfgs_log(h, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.2f,b=%.0f) R=%.7f" % (frac, beta, bestR))

    # Phase-shift perturbations of the flat-top construction.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale(hp)
        if hp.sum() <= 0:
            continue
        hp = _lbfgs_log(hp, 600, deadline)
        hp = _window_polish_peak(hp, deadline, 0.35, 16)
        r = R_of(hp)
        print("phase %+.2f R=%.7f" % (delta, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # Final alternating polishing until budget runs out.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _window_polish_peak(best, deadline, 0.40, 24, beta=150.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("winB R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR <= startR + 1e-15 and start is not None:
        return {"best": np.clip(np.asarray(start, dtype=float), 0, None),
                "alternative": best}
    return best

