import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    return _lbfgs_block(h0, np.arange(np.asarray(h0).size), maxiter,
                        deadline, beta=beta, tie=tie)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _polish(h, deadline, rounds=3):
    """Full polish: alternating all-var LBFGS and beta-smoothed tie-breaking."""
    best = _rescale(np.clip(h, 0, None))
    bestR = R_of(best)
    betas = [0.0, 200.0, 1000.0, 5000.0, 0.0]
    for r in range(rounds):
        if time.process_time() >= deadline - 0.3:
            break
        for beta in betas:
            if time.process_time() >= deadline - 0.3:
                break
            hs = _seed_zeros(best) if beta == 0.0 else best
            ht = _lbfgs_all(hs, 300, deadline, beta=beta, tie=(beta == 0.0))
            r2 = R_of(ht)
            if r2 > bestR + 1e-14:
                best, bestR = ht.copy(), r2
    return best, bestR


def _find_runs(h):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    pos = h > 0
    n = h.size
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _upsample2(h):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    out = np.empty(2 * h.size, dtype=float)
    out[0::2] = h
    out[1::2] = h
    return out


def _thin_runs(h_orig, h_fine, frac=0.5):
    h_orig = np.clip(np.asarray(h_orig, dtype=float), 0, None)
    out = np.zeros_like(h_fine)
    n_fine = h_fine.size
    for (i, j) in _find_runs(h_orig):
        k = j - i + 1
        mass = h_orig[i:j + 1].sum()
        m = max(1, int(np.ceil(k * frac)))
        lo = 2 * i
        hi = 2 * j + 1
        center = (lo + hi) // 2
        a = center - m // 2
        b = a + m - 1
        if a < 0:
            a = 0
            b = m - 1
        if b >= n_fine:
            b = n_fine - 1
            a = b - m + 1
        if a < 0:
            a = 0
        width = b - a + 1
        if width <= 0:
            continue
        out[a:b + 1] += mass / width
    return out


def _stats_line(tag, h, r):
    pos = h > 0
    mean_pos = h[pos].mean() if pos.any() else 0.0
    mx = h.max() if h.size else 0.0
    ratio = mx / mean_pos if mean_pos > 0 else 0.0
    print("%s: N=%d zeros=%.1f%% max/mean=%.2f R=%.8f" %
          (tag, h.size, 100.0 * np.mean(h <= 0), ratio, r))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.8f (N=%d)" % (start_bestR, start_best.size))

    # ---- Phase 1: build the upsampled+thinned experiment ----
    exp_h, expR = None, -1.0
    try:
        h_orig = start_best.copy()
        hA = _upsample2(h_orig)
        rA = R_of(hA)
        print("StageA: N=%d R=%.8f" % (hA.size, rA))

        now = time.process_time()
        remaining = max(0.0, deadline - now)
        reserve = min(14.0, 0.30 * remaining)
        explore_deadline = deadline - reserve

        candidates = [(hA, rA, "unthin")]
        for frac in (0.5, 0.65, 0.4):
            if time.process_time() >= explore_deadline - 1.0:
                break
            hT = _thin_runs(h_orig, hA, frac=frac)
            rT = R_of(hT)
            sub_deadline = min(explore_deadline,
                               time.process_time() +
                               max(1.0, 0.3 * (explore_deadline -
                                               time.process_time())))
            hp, rp = _polish(hT, sub_deadline, rounds=1)
            print("thin frac=%.2f raw=%.8f pol=%.8f" % (frac, rT, rp))
            candidates.append((hp, rp, "thin%.2f" % frac))

        if time.process_time() < explore_deadline - 1.0:
            sub_deadline = min(explore_deadline,
                               time.process_time() +
                               max(1.0, 0.4 * (explore_deadline -
                                               time.process_time())))
            hp, rp = _polish(hA, sub_deadline, rounds=1)
            print("unthin pol=%.8f" % rp)
            candidates.append((hp, rp, "unthin_pol"))

        best_c, best_rc, tag = max(candidates, key=lambda z: z[1])
        print("chosen: %s R=%.8f" % (tag, best_rc))
        exp_h, expR = _polish(best_c, deadline - 1.0, rounds=3)
        _stats_line("exp", exp_h, expR)
    except Exception as e:
        print("experiment failed: %s" % e)

    # ---- Phase 2: pick best and polish to deadline ----
    if exp_h is not None and expR > start_bestR + 1e-13:
        best, bestR = exp_h.copy(), expR
        alt_cand, altR = None, -1.0
    else:
        best, bestR = start_best.copy(), start_bestR
        alt_cand, altR = exp_h, expR

    if time.process_time() < deadline - 0.5:
        ht, r = _polish(best, deadline, rounds=2)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        print("final R=%.8f" % bestR)

    _stats_line("final", best, bestR)

    if bestR >= start_bestR - 1e-13:
        if alt_cand is not None and altR > -1.0 and bestR - altR < 1e-9:
            return {"best": best, "alternative": alt_cand}
        return best
    else:
        if alt_cand is not None and altR > -1.0:
            return {"best": start_best, "alternative": alt_cand}
        return start_best

