def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- residue-class multiplier (w-mod) optimization ----------
def _wmod_block(h, p, maxiter, deadline):
    n = h.size
    if n % p != 0:
        return h
    m = n // p
    if m < 2:
        return h
    H = h.reshape(m, p)
    c = H.mean(axis=1)
    if np.any(c <= 0):
        c = np.clip(c, 1e-12, None)
    w = (H / c[:, None]).mean(axis=0)
    if np.any(w <= 0):
        w = np.clip(w, 1e-12, None)
    lw = np.log(w)
    shift = lw.mean()
    lw = lw - shift
    c = c * np.exp(shift)
    w = np.exp(lw)

    def unpack(x):
        lc = x[:m]
        lw2 = x[m:]
        cc = np.exp(lc)
        ww = np.exp(lw2)
        sh = lw2.mean()
        if sh != 0.0:
            cc = cc * np.exp(sh)
            ww = ww * np.exp(-sh)
        return cc, ww

    def f(x):
        cc, ww = unpack(x)
        hh = (cc[:, None] * ww[None, :]).ravel()
        val, g = _fun_grad_tie(hh)
        G = g.reshape(m, p)
        gc = (G * (cc[:, None] * ww[None, :])).sum(axis=1)
        gw = (G * (cc[:, None] * ww[None, :])).sum(axis=0)
        gm = gw.mean()
        gw = gw - gm
        gc = gc + gm
        return val, np.concatenate([gc, gw])

    x0 = np.concatenate([np.log(c), lw])
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    cc, ww = unpack(res.x)
    hh = (cc[:, None] * ww[None, :]).ravel()
    return _rescale(hh)


def _detect_p(h):
    n = h.size
    for p in (32, 16, 8, 64, 24, 48):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-6, atol=1e-9):
            return p
    return 32


# ---------- NEW: alternating "lift" of periodicity ----------
# Key idea: the current best is near a periodic-with-pattern-w shape (w-mod structure).
# The true optimum likely has *smaller* period (finer structure) or is *non-periodic*.
# We try: (a) merge pairs of cells (halve N) preserving shape, then re-optimize full;
#         (b) refine by subdividing into finer period via interpolation and re-optimize.
# These are genuinely different constructions from `start`.

def _merge(h, k):
    n = h.size
    if n % k != 0:
        return h
    return h.reshape(n // k, k).mean(axis=1)


def _subdiv(h, k):
    # repeat each cell k times (piecewise-constant subdivision)
    return np.repeat(h, k)


def _polish_full(h, deadline, iters=200):
    return _lbfgs_block(h, np.arange(h.size), iters, deadline, tie=True)


def _polish_peak(h, deadline, pad_frac=0.05, iters=200):
    win = _peak_window(h, pad_frac=pad_frac, extra=64)
    return _lbfgs_block(h, win, iters, deadline, tie=True)


def _polish_beta(h, deadline, beta=1e6, pad_frac=0.05, iters=200):
    win = _peak_window(h, pad_frac=pad_frac, extra=64)
    return _lbfgs_block(h, win, iters, deadline, beta=beta)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---------- Phase A: try structural alternatives (merge / subdivide) ----------
    # These produce genuinely different constructions; keep the best.
    alt_end = t0 + budget_seconds * 0.35
    alternatives = []

    # (a) Merge by 2 and 4 (coarser) then polish
    for k in (2, 4):
        if time.process_time() >= alt_end - 2.0:
            break
        hm = _merge(best, k)
        if hm.size < 8:
            continue
        # polish merged shape on full free set (short)
        h2 = _polish_full(hm, min(alt_end, time.process_time() + 4.0), iters=150)
        r2 = R_of(h2)
        alternatives.append((r2, h2.copy()))
        print("merge k=%d N=%d R=%.9f" % (k, h2.size, r2))

    # (b) Subdivide by 2 then polish (finer resolution)
    for k in (2,):
        if time.process_time() >= alt_end - 2.0:
            break
        hs = _subdiv(best, k)
        if hs.size > 1_000_000:
            continue
        h2 = _polish_full(hs, min(alt_end, time.process_time() + 4.0), iters=150)
        r2 = R_of(h2)
        alternatives.append((r2, h2.copy()))
        print("subdiv k=%d N=%d R=%.9f" % (k, h2.size, r2))

    # Adopt best alternative if it beats current best
    for r2, h2 in alternatives:
        if r2 > bestR + 1e-14:
            best, bestR = h2, r2
            print("ADOPT alt R=%.9f N=%d" % (bestR, best.size))

    # ---------- Phase W: residue-class multiplier optimization ----------
    w_end = t0 + budget_seconds * 0.55
    p = _detect_p(best)
    print("wmod p=%d" % p)
    for blk in range(3):
        if time.process_time() >= w_end - 1.5:
            break
        prevR = bestR
        ht = _wmod_block(best, p, 150, min(w_end - 0.5,
                                           time.process_time() + 15.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("wmod R=%.9f dR=%.2e" % (bestR, r - prevR))

    # ---------- Phase Q: quotient L-BFGS ----------
    q_end = t0 + budget_seconds * 0.68
    for pp in (32, 16, 8):
        if time.process_time() >= q_end - 1.0:
            break
        n = best.size
        if n % pp != 0:
            continue
        m = n // pp
        if m < 2:
            continue
        c0 = best.reshape(m, pp).mean(axis=1)
        cb = _make_cb(q_end - 0.3)

        def fq(x, m=m, pp=pp):
            c = np.clip(x, 0.0, None)
            h = np.repeat(c, pp)
            val, g = _fun_grad_tie(h)
            gc = g.reshape(m, pp).sum(axis=1)
            return val, gc

        try:
            res = minimize(fq, c0.copy(), jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * m, callback=cb,
                           options={'maxiter': 400, 'maxfun': 800,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            if res is not None:
                h2 = _rescale(np.repeat(np.clip(res.x, 0.0, None), pp))
                r2 = R_of(h2)
                if r2 > bestR + 1e-15:
                    best, bestR = h2, r2
                    print("quot p=%d ACCEPT R=%.9f" % (pp, bestR))
        except (TimeoutError, Exception):
            pass

    # ---------- Phase P: peak ladder ----------
    peak_end = t0 + budget_seconds * 0.85
    pads = (0.06, 0.03, 0.02, 0.012)
    for pad in pads:
        if time.process_time() >= peak_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= peak_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(peak_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---------- Phase F: final short full-N peak-window tie polish ----------
    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 1.5:
        win = _peak_window(best, pad_frac=0.02, extra=48)
        ht = _lbfgs_block(best, win, 200,
                          min(fd - 0.5, time.process_time() + 2.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    c = (m - 1) / 2.0
    n = h.size
    w = max(3, int(pad * n))
    lo = max(0, int(c - w))
    hi = min(n, int(c + w) + 1)
    if hi - lo < 2:
        return np.arange(n)
    return np.arange(lo, hi)


def _perturb(h, s, k):
    n = h.size
    idx = np.arange(n)
    E = np.cos(2.0 * np.pi * k * (idx + 0.5) / n)
    return _rescale(np.clip(h * (1.0 + s * E), 0.0, None))


def _prolongate(h, N2):
    N1 = h.size
    if N1 == N2:
        return _rescale(np.clip(h, 0, None))
    M = float(N1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, M, N2 + 1)
    cum_at = np.interp(edges, np.arange(N1 + 1), cum)
    mass = np.diff(cum_at)
    out = mass * (M / N2)
    return _rescale(np.clip(out, 0.0, None))


def _revive_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    zeros = np.flatnonzero(h <= 0)
    if zeros.size < 4:
        return h
    try:
        val, g = _fun_grad_tie(h)
    except Exception:
        return h
    score = g[zeros]
    k = max(1, int(0.03 * n))
    k = min(k, zeros.size)
    order = np.argsort(-score)
    pick = zeros[order[:k]]
    active_mean = h[h > 0].mean() if np.any(h > 0) else 1.0
    h2 = h.copy()
    h2[pick] = 0.02 * active_mean
    return _rescale(h2)


def _level_refine(h, level_deadline):
    best = h
    bestR = R_of(best)

    def time_left():
        return time.process_time() < level_deadline

    if time_left():
        cand = _revive_zeros(best)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    if time_left():
        cand = _lbfgs_all_pos(best, 300, level_deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    for beta in (1e3, 1e5, 1e7):
        if not time_left():
            break
        cand = _lbfgs_all_pos(best, 150, level_deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    for pad in (0.20, 0.12, 0.06, 0.03):
        if not time_left():
            break
        free = _peak_window(best, pad)
        cand = _lbfgs_block(best, free, 150, level_deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    for s in (0.03, 0.08):
        for k in (1, 2):
            if not time_left():
                break
            cand = _perturb(best, s, k)
            free = _peak_window(cand, 0.04)
            cand = _lbfgs_block(cand, free, 150, level_deadline, tie=True)
            r = R_of(cand)
            if r > bestR + 1e-12:
                best, bestR = cand, r

    return best, bestR


def _jitter_phase(h, deadline, rng):
    """Exact-R position jitter: shift contiguous windows by +/-1..2 cells."""
    best = np.clip(h, 0, None).copy()
    bestR = R_of(best)
    n = best.size
    if n < 64:
        return best, bestR
    lengths = [32, 64, 128, 256, 512]
    deltas = [-2, -1, 1, 2]
    k = 0
    acc = 0
    rej_since = 0
    while time.process_time() < deadline:
        k += 1
        L = lengths[rng.integers(0, len(lengths))]
        if L >= n:
            continue
        i = int(rng.integers(0, n - L + 1))
        delta = deltas[int(rng.integers(0, len(deltas)))]
        j = i + delta
        if j < 0 or j + L > n:
            continue
        w = best[i:i + L].copy()
        cand = best.copy()
        cand[i:i + L] = 0.0
        cand[j:j + L] = w
        r = R_of(cand)
        if r > bestR:
            best = cand
            bestR = r
            acc += 1
            rej_since = 0
        else:
            rej_since += 1
            if rej_since >= 200:
                rej_since = 0
                # simulated-annealing accept of a small loss
                if bestR - r < 1e-6:
                    best = cand
                    bestR = r
                    acc += 1
        if k % 1000 == 0:
            print("jit k=%d R=%.9f acc=%d" % (k, bestR, acc))
    print("jit done k=%d R=%.9f acc=%d" % (k, bestR, acc))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.93 * budget_seconds
    rng = np.random.default_rng(12345)

    best = None
    bestR = -1.0
    start_arr = None
    startR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.size >= 2 and s.sum() > 0:
            start_arr = s
            startR = R_of(s)
            best = s.copy()
            bestR = startR
            print("start R=%.6f N=%d" % (bestR, s.size))

    if best is None:
        n = 100
        x = (np.arange(n) + 0.5) / n
        h = np.exp(-40.0 * (x - 0.5) ** 2)
        best = _rescale(h)
        bestR = R_of(best)
        print("init bump R=%.6f" % bestR)

    # Phase J: position jitter (0.05 - 0.45 of budget)
    jit_start = t0 + 0.05 * budget_seconds
    jit_end = t0 + 0.45 * budget_seconds
    if time.process_time() < jit_start:
        # small warm-up: nothing to do, just wait naturally by refining lightly
        pass
    if time.process_time() < jit_end - 0.5:
        work, r = _jitter_phase(best, jit_end, rng)
        if r > bestR:
            best, bestR = work, r

    # Phase C: full-array tie L-BFGS + peak-window polish
    c_end = t0 + 0.60 * budget_seconds
    if time.process_time() < c_end - 0.5:
        cand = _lbfgs_all_pos(best, 300, c_end, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
            print("C full R=%.9f" % bestR)
        for pad in (0.06, 0.03, 0.02):
            if time.process_time() >= c_end - 0.3:
                break
            free = _peak_window(best, pad)
            cand = _lbfgs_block(best, free, 150, c_end, tie=True)
            r = R_of(cand)
            if r > bestR:
                best, bestR = cand, r
                print("C pad%.2f R=%.9f" % (pad, bestR))

    # Resolution refinement
    ladder = [102400, 204800]
    work = best
    for li, N2 in enumerate(ladder):
        if time.process_time() >= deadline - 1.5:
            break
        levels_left = len(ladder) - li
        now = time.process_time()
        slice_end = now + max(0.5, (deadline - now) / levels_left)
        work = _prolongate(work, N2)
        # peak-window tie L-BFGS
        free = _peak_window(work, 0.06)
        work = _lbfgs_block(work, free, 200, slice_end, tie=True)
        # one full-array tie pass
        if time.process_time() < slice_end - 0.3:
            work = _lbfgs_all_pos(work, 150, slice_end, tie=True)
        r = R_of(work)
        print("refine N=%d R=%.9f" % (work.size, r))
        if r > bestR:
            best, bestR = work.copy(), r

    # Final polish
    final_deadline = t0 + 0.97 * budget_seconds
    while time.process_time() < final_deadline - 1.0:
        free = _peak_window(best, 0.02)
        cand = _lbfgs_block(best, free, 150, final_deadline, tie=True)
        r = R_of(cand)
        if r > bestR + 1e-10:
            best, bestR = cand, r
            print("final pad0.02 R=%.9f N=%d" % (bestR, best.size))
        else:
            cand = _lbfgs_all_pos(best, 150, final_deadline, tie=True)
            r = R_of(cand)
            if r > bestR + 1e-10:
                best, bestR = cand, r
                print("final full R=%.9f N=%d" % (bestR, best.size))
            else:
                break

    best = _rescale(np.clip(best, 0, None))
    finalR = R_of(best)
    print("final R=%.9f N=%d" % (finalR, best.size))

    if start_arr is not None and startR >= finalR:
        return {"best": start_arr, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _plateau_window(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return np.arange(h.size)
    n = h.size
    lo = max(0, idx.min() - 1 - n // 20)
    hi = min(n - 1, idx.max() + n // 20)
    return np.arange(lo, hi + 1)


def _smooth(h, k=3):
    if h.size < 2 * k + 1:
        return h
    ker = np.ones(2 * k + 1) / (2 * k + 1)
    hs = np.convolve(h, ker, mode='same')
    return _rescale(np.clip(hs, 0, None))


def _resample(base, newN):
    n = base.size
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    h = np.interp(x_new, x_old, base)
    return _rescale(h)


# ---- NEW: analytic capped two-sided singular seed + mass prolongation ----

def _analytic_seed(n, cap, b, AL, AR, pL, pR, epsL, epsR):
    i = np.arange(n, dtype=float)
    j = (n - 1) - i
    h = b + AL / np.power(i + epsL, pL) + AR / np.power(j + epsR, pR)
    return _rescale(np.minimum(h, cap))


def _mass_prolongate(base, newN):
    """Prolongate by matching cumulative mass at cell centers."""
    n = base.size
    c = np.cumsum(base)
    c = c / c[-1]
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    cm = np.interp(x_new, x_old, c, left=0.0, right=1.0)
    h = np.diff(np.concatenate(([0.0], cm)))
    h = np.clip(h, 0, None)
    return _rescale(h)


def _seed_search(deadline, n=1024):
    """Grid-search the capped two-sided singular family, then Nelder-Mead."""
    from scipy.optimize import minimize as _min
    med = 1.0
    best_r = -1.0
    best_h = None
    caps = [4.0, 8.0, 16.0]
    bs = [0.02, 0.05, 0.1]
    As = [0.5, 1.0, 2.0, 4.0]
    ps = [0.3, 0.5, 0.7]
    es = [0.01, 0.05, 0.2]
    for cap in caps:
        for b in bs:
            for AL in As:
                for AR in As:
                    for pL in ps:
                        for pR in ps:
                            if time.process_time() > deadline:
                                break
                            for epsL in es:
                                for epsR in es:
                                    h = _analytic_seed(n, cap, b, AL, AR,
                                                       pL, pR, epsL, epsR)
                                    r = R_of(h)
                                    if r > best_r:
                                        best_r = r
                                        best_h = h
    if best_h is None:
        best_h = _analytic_seed(n, 8.0, 0.05, 1.0, 1.0, 0.5, 0.5, 0.05, 0.05)
        best_r = R_of(best_h)

    # Nelder-Mead on all 8 params (log-parameterised for positivity)
    def unpack(z):
        cap = np.exp(z[0]); b = np.exp(z[1])
        AL = np.exp(z[2]); AR = np.exp(z[3])
        pL = np.exp(z[4]); pR = np.exp(z[5])
        epsL = np.exp(z[6]); epsR = np.exp(z[7])
        return cap, b, AL, AR, pL, pR, epsL, epsR

    def negR(z):
        cap, b, AL, AR, pL, pR, epsL, epsR = unpack(z)
        h = _analytic_seed(n, cap, b, AL, AR, pL, pR, epsL, epsR)
        return -R_of(h)

    # recover params of best_h approximately by re-gridding? just start from
    # a reasonable point and let NM explore.
    z0 = np.log(np.array([8.0, 0.05, 1.0, 1.0, 0.5, 0.5, 0.05, 0.05]))
    try:
        if time.process_time() < deadline - 0.5:
            res = _min(negR, z0, method='Nelder-Mead',
                       options={'maxiter': 2000, 'xatol': 1e-6,
                                'fatol': 1e-10})
            if res is not None and -res.fun > best_r:
                cap, b, AL, AR, pL, pR, epsL, epsR = unpack(res.x)
                h = _analytic_seed(n, cap, b, AL, AR, pL, pR, epsL, epsR)
                r = R_of(h)
                if r > best_r:
                    best_r = r
                    best_h = h
    except Exception:
        pass
    return best_h, best_r


def _record_polish(h, deadline, level_iters=300):
    """The record chain's polish: tie L-BFGS, beta ladder, peak pads, revive."""
    if time.process_time() >= deadline - 0.5:
        return h
    h = _lbfgs_all_pos(h, level_iters, deadline - 0.3, tie=True)
    for beta in (1e4, 1e5, 1e6, 1e7):
        if time.process_time() >= deadline - 0.5:
            break
        h = _lbfgs_all_pos(h, 150, deadline - 0.3, beta=beta)
        h = _lbfgs_all_pos(h, 100, deadline - 0.3, tie=True)
    if time.process_time() < deadline - 0.5:
        h = _peak_ladder(h, deadline - 0.3,
                         pads=(0.06, 0.03, 0.02), iters=200, tie=True)
    # revive top 2% of zero cells
    if time.process_time() < deadline - 0.5:
        zeros = np.flatnonzero(h <= 0)
        if zeros.size > 0:
            Lf = _knots(h)
            mx = Lf.max()
            # score each zero cell by local knot value (proxy for usefulness)
            vals = Lf[1:-1][zeros]
            k = max(1, int(0.02 * zeros.size))
            order = np.argsort(-vals)[:k]
            h2 = h.copy()
            h2[zeros[order]] = 1e-3 * h.mean()
            h2 = _rescale(h2)
            h2 = _lbfgs_all_pos(h2, 200, deadline - 0.3, tie=True)
            if R_of(h2) > R_of(h):
                h = h2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_arr = _rescale(base)
            startR = R_of(start_arr)
        else:
            start_arr, startR = None, 0.0
    else:
        start_arr, startR = None, 0.0

    print("start R=%.9f (N=%s)" % (startR,
          start_arr.size if start_arr is not None else 0))

    # ============ Phase S: analytic capped two-sided singular seed ============
    s_deadline = t0 + budget_seconds * 0.30
    seed, seedR = _seed_search(s_deadline, n=1024)
    print("seed R=%.9f (N=%d)" % (seedR, seed.size))

    # ============ Phase L: prolongate and polish at each level ============
    h = seed
    levels = [4096, 16384, 65536]
    # allocate remaining budget across levels
    for li, n_new in enumerate(levels):
        if time.process_time() > deadline - 2.0:
            break
        h = _mass_prolongate(h, n_new)
        # time slice for this level
        frac_left = (len(levels) - li)
        remaining = max(0.5, deadline - time.process_time())
        slice_end = time.process_time() + remaining / frac_left
        slice_end = min(slice_end, deadline - 1.0)
        h = _record_polish(h, slice_end, level_iters=300)
        r = R_of(h)
        print("level N=%d R=%.9f" % (n_new, r))

    # ============ Phase F: full tie L-BFGS + final peak polish ============
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_all_pos(h, 800, deadline - 0.5, tie=True)
        if time.process_time() < deadline - 0.5:
            h = _peak_ladder(h, deadline - 0.3,
                             pads=(0.03, 0.02), iters=200, tie=True)
    analyticR = R_of(h)
    print("analytic branch final R=%.9f (N=%d)" % (analyticR, h.size))

    # ============ Compare with start ============
    result = {}
    if start_arr is not None and startR >= analyticR:
        result["best"] = start_arr
        result["alternative"] = h
        print("keeping start as best (%.9f >= %.9f)" % (startR, analyticR))
    else:
        result["best"] = h
        if start_arr is not None:
            result["alternative"] = start_arr
        print("analytic branch wins (%.9f > %.9f)" % (analyticR, startR))

    bestR = R_of(result["best"])
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, result["best"].size,
             _zero_frac(result["best"]), _nearmax_frac(result["best"]),
             _tie_count(result["best"])))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


