    med = 1.0
    best_r = -1.0
    best_h = None
    caps = [4.0, 8.0, 16.0]
    bs = [0.02, 0.05, 0.1]
    As = [0.5, 1.0, 2.0, 4.0]
    ps = [0.3, 0.5, 0.7]
    es = [0.01, 0.05, 0.2]
    for cap in caps:
        for b in bs:
            for AL in As:
                for AR in As:
                    for pL in ps:
                        for pR in ps:
                            if time.process_time() > deadline:
                                break
                            for epsL in es:
                                for epsR in es:
                                    h = _analytic_seed(n, cap, b, AL, AR,
                                                       pL, pR, epsL, epsR)
                                    r = R_of(h)
                                    if r > best_r:
                                        best_r = r
                                        best_h = h
    if best_h is None:
        best_h = _analytic_seed(n, 8.0, 0.05, 1.0, 1.0, 0.5, 0.5, 0.05, 0.05)
        best_r = R_of(best_h)

    # Nelder-Mead on all 8 params (log-parameterised for positivity)
    def unpack(z):
        cap = np.exp(z[0]); b = np.exp(z[1])
        AL = np.exp(z[2]); AR = np.exp(z[3])
        pL = np.exp(z[4]); pR = np.exp(z[5])
        epsL = np.exp(z[6]); epsR = np.exp(z[7])
        return cap, b, AL, AR, pL, pR, epsL, epsR

    def negR(z):
        cap, b, AL, AR, pL, pR, epsL, epsR = unpack(z)
        h = _analytic_seed(n, cap, b, AL, AR, pL, pR, epsL, epsR)
        return -R_of(h)

    # recover params of best_h approximately by re-gridding? just start from
    # a reasonable point and let NM explore.
    z0 = np.log(np.array([8.0, 0.05, 1.0, 1.0, 0.5, 0.5, 0.05, 0.05]))
    try:
        if time.process_time() < deadline - 0.5:
            res = _min(negR, z0, method='Nelder-Mead',
                       options={'maxiter': 2000, 'xatol': 1e-6,
                                'fatol': 1e-10})
            if res is not None and -res.fun > best_r:
                cap, b, AL, AR, pL, pR, epsL, epsR = unpack(res.x)
                h = _analytic_seed(n, cap, b, AL, AR, pL, pR, epsL, epsR)
                r = R_of(h)
                if r > best_r:
                    best_r = r
                    best_h = h
    except Exception:
        pass
    return best_h, best_r


def _record_polish(h, deadline, level_iters=300):
    """The record chain's polish: tie L-BFGS, beta ladder, peak pads, revive."""
    if time.process_time() >= deadline - 0.5:
        return h
    h = _lbfgs_all_pos(h, level_iters, deadline - 0.3, tie=True)
    for beta in (1e4, 1e5, 1e6, 1e7):
        if time.process_time() >= deadline - 0.5:
            break
        h = _lbfgs_all_pos(h, 150, deadline - 0.3, beta=beta)
        h = _lbfgs_all_pos(h, 100, deadline - 0.3, tie=True)
    if time.process_time() < deadline - 0.5:
        h = _peak_ladder(h, deadline - 0.3,
                         pads=(0.06, 0.03, 0.02), iters=200, tie=True)
    # revive top 2% of zero cells
    if time.process_time() < deadline - 0.5:
        zeros = np.flatnonzero(h <= 0)
        if zeros.size > 0:
            Lf = _knots(h)
            mx = Lf.max()
            # score each zero cell by local knot value (proxy for usefulness)
            vals = Lf[1:-1][zeros]
            k = max(1, int(0.02 * zeros.size))
            order = np.argsort(-vals)[:k]
            h2 = h.copy()
            h2[zeros[order]] = 1e-3 * h.mean()
            h2 = _rescale(h2)
            h2 = _lbfgs_all_pos(h2, 200, deadline - 0.3, tie=True)
            if R_of(h2) > R_of(h):
                h = h2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_arr = _rescale(base)
            startR = R_of(start_arr)
        else:
            start_arr, startR = None, 0.0
    else:
        start_arr, startR = None, 0.0

    print("start R=%.9f (N=%s)" % (startR,
          start_arr.size if start_arr is not None else 0))

    # ============ Phase S: analytic capped two-sided singular seed ============
    s_deadline = t0 + budget_seconds * 0.30
    seed, seedR = _seed_search(s_deadline, n=1024)
    print("seed R=%.9f (N=%d)" % (seedR, seed.size))

    # ============ Phase L: prolongate and polish at each level ============
    h = seed
    levels = [4096, 16384, 65536]
    # allocate remaining budget across levels
    for li, n_new in enumerate(levels):
        if time.process_time() > deadline - 2.0:
            break
        h = _mass_prolongate(h, n_new)
        # time slice for this level
        frac_left = (len(levels) - li)
        remaining = max(0.5, deadline - time.process_time())
        slice_end = time.process_time() + remaining / frac_left
        slice_end = min(slice_end, deadline - 1.0)
        h = _record_polish(h, slice_end, level_iters=300)
        r = R_of(h)
        print("level N=%d R=%.9f" % (n_new, r))

    # ============ Phase F: full tie L-BFGS + final peak polish ============
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_all_pos(h, 800, deadline - 0.5, tie=True)
        if time.process_time() < deadline - 0.5:
            h = _peak_ladder(h, deadline - 0.3,
                             pads=(0.03, 0.02), iters=200, tie=True)
    analyticR = R_of(h)
    print("analytic branch final R=%.9f (N=%d)" % (analyticR, h.size))

    # ============ Compare with start ============
    result = {}
    if start_arr is not None and startR >= analyticR:
        result["best"] = start_arr
        result["alternative"] = h
        print("keeping start as best (%.9f >= %.9f)" % (startR, analyticR))
    else:
        result["best"] = h
        if start_arr is not None:
            result["alternative"] = start_arr
        print("analytic branch wins (%.9f > %.9f)" % (analyticR, startR))

    bestR = R_of(result["best"])
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, result["best"].size,
             _zero_frac(result["best"]), _nearmax_frac(result["best"]),
             _tie_count(result["best"])))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_p(h):
    n = h.size
    for p in (32, 16, 8, 64, 24, 48, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-6, atol=1e-9):
            return p
    return 32


# ---------- residue-class multiplier (w-mod) optimization ----------
def _wmod_block(h, p, maxiter, deadline):
    n = h.size
    if n % p != 0:
        return h
    m = n // p
    if m < 2:
        return h
    H = h.reshape(m, p)
    c = H.mean(axis=1)
    if np.any(c <= 0):
        c = np.clip(c, 1e-12, None)
    w = (H / c[:, None]).mean(axis=0)
    if np.any(w <= 0):
        w = np.clip(w, 1e-12, None)
    lw = np.log(w)
    shift = lw.mean()
    lw = lw - shift
    c = c * np.exp(shift)
    w = np.exp(lw)

    def unpack(x):
        lc = x[:m]
        lw2 = x[m:]
        cc = np.exp(lc)
        ww = np.exp(lw2)
        sh = lw2.mean()
        if sh != 0.0:
            cc = cc * np.exp(sh)
            ww = ww * np.exp(-sh)
        return cc, ww

    def f(x):
        cc, ww = unpack(x)
        hh = (cc[:, None] * ww[None, :]).ravel()
        val, g = _fun_grad_tie(hh)
        G = g.reshape(m, p)
        gc = (G * (cc[:, None] * ww[None, :])).sum(axis=1)
        gw = (G * (cc[:, None] * ww[None, :])).sum(axis=0)
        gm = gw.mean()
        gw = gw - gm
        gc = gc + gm
        return val, np.concatenate([gc, gw])

    x0 = np.concatenate([np.log(c), lw])
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    cc, ww = unpack(res.x)
    hh = (cc[:, None] * ww[None, :]).ravel()
    return _rescale(hh)


def _quotient_opt(h, p, maxiter, deadline):
    n = h.size
    if n % p != 0:
        return h
    m = n // p
    if m < 2:
        return h
    c0 = h.reshape(m, p).mean(axis=1)
    cb = _make_cb(deadline - 0.3)

    def fq(x):
        c = np.clip(x, 0.0, None)
        hh = np.repeat(c, p)
        val, g = _fun_grad_tie(hh)
        gc = g.reshape(m, p).sum(axis=1)
        return val, gc

    try:
        res = minimize(fq, c0.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * m, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        if res is None:
            return h
        return _rescale(np.repeat(np.clip(res.x, 0.0, None), p))
    except (TimeoutError, Exception):
        return h


def _merge(h, k):
    n = h.size
    if n % k != 0:
        return h
    return h.reshape(n // k, k).mean(axis=1)


def _subdiv(h, k):
    return np.repeat(h, k)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---------- Phase A: quotient opt on detected period (strongest lever) ----------
    # The optimum is near periodic; quotient opt on the period condenses
    # the m free variables and is far more effective than full-N polishing.
    qa_end = t0 + budget_seconds * 0.30
    p = _detect_p(best)
    print("detected p=%d" % p)
    # Try the detected period and a ladder of alternatives
    for pp in (p, p // 2, p * 2, 8, 4, 2):
        if pp is None or pp < 2 or best.size % pp != 0:
            continue
        if time.process_time() >= qa_end - 1.0:
            break
        ht = _quotient_opt(best, pp, 2000,
                            min(qa_end - 0.5, time.process_time() + 8.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("quot p=%d ACCEPT R=%.9f" % (pp, bestR))

    # ---------- Phase W: residue-class multiplier optimization ----------
    w_end = t0 + budget_seconds * 0.55
    p = _detect_p(best)
    print("wmod p=%d" % p)
    for blk in range(4):
        if time.process_time() >= w_end - 1.5:
            break
        prevR = bestR
        ht = _wmod_block(best, p, 400, min(w_end - 0.5,
                                           time.process_time() + 12.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("wmod R=%.9f dR=%.2e" % (bestR, r - prevR))

    # ---------- Phase Q2: quotient on finer periods ----------
    q2_end = t0 + budget_seconds * 0.72
    for pp in (16, 8, 32, 4):
        if time.process_time() >= q2_end - 1.0:
            break
        if best.size % pp != 0:
            continue
        ht = _quotient_opt(best, pp, 2000,
                            min(q2_end - 0.5, time.process_time() + 5.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("quot2 p=%d ACCEPT R=%.9f" % (pp, bestR))

    # ---------- Phase P: peak ladder (full-N, windowed, multi-objective) ----------
    peak_end = t0 + budget_seconds * 0.90
    pads = (0.06, 0.03, 0.02, 0.012, 0.008)
    for pad in pads:
        if time.process_time() >= peak_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= peak_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 400,
                              min(peak_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---------- Phase F: final quotient opt at detected p and full polish ----------
    fd = t0 + budget_seconds * 0.99
    p = _detect_p(best)
    if time.process_time() < fd - 1.5 and best.size % p == 0:
        ht = _quotient_opt(best, p, 2000,
                            min(fd - 0.5, time.process_time() + 2.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final quot ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 1.0:
        win = _peak_window(best, pad_frac=0.02, extra=48)
        ht = _lbfgs_block(best, win, 300,
                          min(fd - 0.5, time.process_time() + 2.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    return _lbfgs_block(h0, np.arange(np.asarray(h0).size), maxiter, deadline, beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.06, 0.03), iters=200):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _block_sum(h, k):
    n = h.size
    nb = n // k
    if nb < 1:
        return h.copy()
    trimmed = h[:nb * k].reshape(nb, k)
    return trimmed.sum(axis=1)


def _prolongate(coarse, N, rng):
    k = max(1, int(round(N / max(1, coarse.size))))
    full = np.repeat(coarse, k)
    if full.size < N:
        full = np.concatenate([full, np.full(N - full.size, full[-1])])
    elif full.size > N:
        full = full[:N]
    if full.size > 3:
        ker = np.array([0.25, 0.5, 0.25])
        full = np.convolve(full, ker, mode='same')
    return _rescale(full)


def _edit_zero_pattern(coarse, rng):
    c = coarse.copy()
    active = np.flatnonzero(c > 0)
    zeros = np.flatnonzero(c <= 0)
    if active.size < 2 or zeros.size < 1:
        return c
    m = rng.integers(1, min(7, active.size + 1))
    order = active[np.argsort(c[active])]
    kill = order[:m]
    c[kill] = 0.0
    rev = rng.choice(zeros, size=min(m, zeros.size), replace=False)
    for idx in rev:
        lo = max(0, idx - 2); hi = min(c.size, idx + 3)
        neigh = c[lo:hi]
        nz = neigh[neigh > 0]
        c[idx] = float(nz.mean()) if nz.size > 0 else float(c.mean())
    return c


def _edit_window(coarse, rng):
    c = coarse.copy()
    n = c.size
    w = int(rng.integers(max(1, n // 10), max(2, n // 2) + 1))
    w = min(w, n)
    lo = int(rng.integers(0, n - w + 1))
    amp = rng.uniform(0.15, 0.7)
    fac = np.exp(amp * rng.standard_normal(w))
    c[lo:lo + w] *= fac
    return c


def _edit_half_scale(coarse, rng):
    c = coarse.copy()
    n = c.size
    half = n // 2
    seg = slice(0, half) if rng.random() < 0.5 else slice(half, n)
    c[seg] *= rng.uniform(0.9, 1.1)
    return c


def _coarse_polish(c, deadline):
    if time.process_time() >= deadline - 0.3:
        return c, R_of(c)
    c = _rescale(np.clip(c, 0, None))
    if c.sum() <= 0:
        return c, 0.0
    c = _lbfgs_all_pos(c, 60, deadline - 0.1, beta=0.0)
    if time.process_time() < deadline - 0.15:
        win = _peak_window(c, pad_frac=0.15, extra=32)
        ct = _lbfgs_block(c, win, 120, deadline - 0.05, beta=1e6)
        if R_of(ct) > R_of(c):
            c = ct
    return c, R_of(c)


# ---- NEW: direct fine-grained structural perturbation of the full-size shape ----
def _fine_jitter(h, rng, strength):
    """Add smooth multiplicative noise to a random localized window of the full shape."""
    c = h.copy()
    n = c.size
    w = int(rng.integers(max(4, n // 40), max(8, n // 6) + 1))
    w = min(w, n)
    lo = int(rng.integers(0, n - w + 1))
    # smooth noise via cumulative sum of small steps, then subtract mean
    steps = rng.standard_normal(w)
    smooth = np.cumsum(steps)
    smooth -= smooth.mean()
    m = np.max(np.abs(smooth)) + 1e-12
    fac = np.exp(strength * smooth / m)
    c[lo:lo + w] *= fac
    return np.clip(c, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(7919)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Stage 1: fine-grained structural exploration on the full shape ----
    # This is the new idea: perturb windows of the actual best shape at full
    # resolution, then polish only the perturbed window with a soft-max
    # (beta) objective. Small local changes can escape the coarse-screening
    # plateau that the original program was stuck on.
    stage1_end = t0 + budget_seconds * 0.55
    trials = 0
    accepts = 0
    while time.process_time() < stage1_end - 0.5:
        trials += 1
        strength = rng.uniform(0.02, 0.25)
        cand = _fine_jitter(best, rng, strength)
        if cand.sum() <= 0:
            continue
        cand = _rescale(cand)
        # polish only a window around the perturbation region + peak
        win = _peak_window(cand, pad_frac=0.10, extra=256)
        # also include the whole support region where the perturbation matters
        # by using a wider window
        win2 = _peak_window(cand, pad_frac=0.25, extra=512)
        cap = min(stage1_end - 0.3, time.process_time() + 1.5)
        ht = _lbfgs_block(cand, win2, 150, cap - 0.2, beta=1e7)
        if time.process_time() < cap - 0.2:
            ht = _lbfgs_block(ht, win2, 150, cap - 0.1, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            accepts += 1
            print("stage1 accept #%d R=%.9f (trials=%d)" % (accepts, bestR, trials))
    print("stage1 done: trials=%d accepts=%d R=%.9f" % (trials, accepts, bestR))

    # ---- Stage 2: full-shape polish of the best found so far ----
    stage2_end = t0 + budget_seconds * 0.85
    ht = _lbfgs_all_pos(best, 2000, stage2_end - 0.4, beta=0.0)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht.copy(), R_of(ht)
        print("stage2 full polish R=%.9f" % bestR)
    ht = _peak_ladder(best, stage2_end - 0.2, pads=(0.05, 0.03), iters=200)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht.copy(), R_of(ht)
        print("stage2 peak ladder R=%.9f" % bestR)

    # ---- Stage 3: fine jitter again with leftover time ----
    stage3_end = t0 + budget_seconds * 0.97
    trials2 = 0
    while time.process_time() < stage3_end - 0.4:
        trials2 += 1
        strength = rng.uniform(0.01, 0.10)
        cand = _fine_jitter(best, rng, strength)
        if cand.sum() <= 0:
            continue
        cand = _rescale(cand)
        win2 = _peak_window(cand, pad_frac=0.20, extra=384)
        cap = min(stage3_end - 0.3, time.process_time() + 1.2)
        ht = _lbfgs_block(cand, win2, 120, cap - 0.15, beta=1e7)
        if time.process_time() < cap - 0.15:
            ht = _lbfgs_block(ht, win2, 120, cap - 0.05, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            print("stage3 accept #%d R=%.9f" % (trials2, bestR))
    print("stage3 done: trials=%d R=%.9f" % (trials2, bestR))

    # ---- Final full polish ----
    final_end = t0 + budget_seconds * 0.985
    ht = _lbfgs_all_pos(best, 3000, final_end - 0.3, beta=0.0)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht.copy(), R_of(ht)
        print("final polish R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best), _argmax_frac(best),
             _nearmax_frac(best)))

    result = {"best": best}
    if start_best is not None and bestR <= start_bestR + 1e-14:
        result["alternative"] = start_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline,
                        beta=beta, tie=tie)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _resample_upsample(h, factor):
    """Linear interpolation upsample by factor, scaled to preserve sum."""
    n = h.size
    x = np.linspace(0.0, 1.0, n, endpoint=False)
    xn = np.linspace(0.0, 1.0, n * factor, endpoint=False)
    h2 = np.interp(xn, x, h, left=0.0, right=0.0)
    return h2


def _resample_downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h
    return h[:m * factor].reshape(m, factor).sum(axis=1)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


# ---------------------------------------------------------------------------
# NEW IDEA: two-resolution lifting.
#
# The result has N ~ 105k steps with 67.6% zeros. That many small steps are
# likely needed only to resolve the *shape near the peak of f*f*; elsewhere
# the function is close to piecewise linear.  A more effective search is:
#
#   (1) downsample to a modest N (2k-8k) via block-sum, optimise fully there
#       with the tie-aware objective (so multiple knots can share the max,
#       which counteracts the single-knot collapse of _fun_grad);
#   (2) upsample by linear interpolation and re-optimise, repeating at
#       1.5-2x resolution several times.
#
# This makes the whole search happen at coarse resolution first, which is
# much cheaper per iteration and avoids the flat-region stalls of the
# 105k-step problem.  The tie objective lets the coarse solution spread
# mass so that upsampling is not immediately undone.
# ---------------------------------------------------------------------------

def _tie_cycle(best, bestR, deadline, rounds=2):
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all(best, 500, deadline - 0.5, beta=0.0, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all(best, 300, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    return best, bestR


def _multires_search(start_h, start_R, deadline, rng):
    """Coarse-to-fine search via up/down-sampling."""
    best = start_h.copy()
    bestR = start_R
    alt = None
    altR = -1.0

    # Try several coarse representations of the current best.
    n0 = best.size
    coarse_sizes = []
    for target in (2048, 4096, 8192, 16384, 32768):
        if target < n0:
            f = max(1, n0 // target)
            coarse_sizes.append((target, f))
    # Also try the full size directly (only useful as a tie-aware pass).
    coarse_sizes.append((n0, 1))

    for target, factor in coarse_sizes:
        if time.process_time() >= deadline - 1.0:
            break
        if factor == 1:
            hc = best.copy()
        else:
            hc = _resample_downsample(best, factor)
        hc = _rescale(hc)
        rc = R_of(hc)
        # short optimise at coarse resolution
        hc, rc = _tie_cycle(hc, rc, min(deadline - 0.5,
                                        time.process_time() + 4.0), rounds=2)
        # lift back up gradually
        cur = hc
        curR = rc
        cur_n = cur.size
        while cur_n < n0 and time.process_time() < deadline - 1.0:
            step_up = min(n0, cur_n * 2)
            if step_up == cur_n:
                break
            up = _resample_upsample(cur, 2)
            up = _rescale(up)
            upR = R_of(up)
            up, upR = _lbfgs_all(up, 400, min(deadline - 0.5,
                                              time.process_time() + 6.0),
                                 beta=0.0)
            if upR < curR - 1e-9:
                # upsampling hurt; try a tie-aware pass instead
                up2 = _resample_upsample(cur, 2)
                up2 = _rescale(up2)
                up2, upR2 = _lbfgs_all(up2, 400,
                                       min(deadline - 0.5,
                                           time.process_time() + 6.0),
                                       beta=1e7)
                if upR2 > upR:
                    up, upR = up2, upR2
            cur = up[:n0] if up.size > n0 else np.concatenate(
                [up, np.zeros(n0 - up.size)])
            cur = _rescale(cur)
            curR = R_of(cur)
            cur_n = cur.size
        # final full-size polish
        if time.process_time() < deadline - 0.5:
            cur, curR = run_cycle(cur, curR, min(deadline - 0.5,
                                                 time.process_time() + 8.0))
        if curR > bestR + 1e-13:
            best, bestR = cur, curR
        elif curR > altR:
            alt, altR = cur, curR
    return best, bestR, alt, altR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(20240517)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: the proven pipeline (short).
    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f" % bestR)

    alt_cand = None
    altR = -1.0

    # Phase 2: multiresolution coarse-to-fine search.
    if time.process_time() < deadline - 3.0:
        h_m, r_m, h_a, r_a = _multires_search(best, bestR,
                                              deadline - 2.0, rng)
        if r_m > bestR + 1e-13:
            best, bestR = h_m, r_m
            print("multires wins: R=%.7f (N=%d)" % (bestR, best.size))
        if h_a is not None and r_a > altR:
            alt_cand, altR = h_a, r_a

    # Phase 3: final polish at full resolution.
    rounds = 0
    while time.process_time() < deadline - 1.0:
        rounds += 1
        before = bestR
        if time.process_time() < deadline - 1.0:
            best, bestR = run_cycle(best, bestR, deadline - 0.8)
        if bestR <= before + 1e-13:
            # try a tie-aware pass to escape
            if time.process_time() < deadline - 0.8:
                ht = _lbfgs_all(best, 400, deadline - 0.8, beta=0.0, tie=True)
                r = R_of(ht)
                if r > bestR + 1e-13:
                    best, bestR = ht, r
            if bestR <= before + 1e-13:
                break

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- repeat detection ----------
def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


# ---------- coarse L-BFGS on log heights ----------
def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        start = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[start:start + L] *= fac
    return c2


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- Phase A: coarse jitter + repolish ----
    a_end = t0 + budget_seconds * 0.30
    rng = np.random.default_rng(12345)
    c_best = c.copy()
    cR = R_of(c_best)
    accepted = 0
    rounds = 0
    while time.process_time() < a_end - 0.5:
        rounds += 1
        cj = _jitter(c_best, rng)
        cj = _lbfgs_log(cj, 150, min(a_end - 0.3,
                                     time.process_time() + 1.5))
        rj = R_of(cj)
        if rj > cR + 1e-15:
            c_best, cR = cj, rj
            accepted += 1
    print("PhaseA rounds=%d accepted=%d cR=%.9f" % (rounds, accepted, cR))

    # ---- Phase B: interpolating lift ladder ----
    b_end = t0 + budget_seconds * 0.75
    cur = c_best.copy()
    curR = cR
    for step in range(4):
        if time.process_time() >= b_end - 1.0:
            break
        if cur.size * 2 > 300000:
            break
        lifted = _interp_lift(cur)
        lifted = _lbfgs_log(lifted, 200, min(b_end - 0.5,
                                             time.process_time() + 6.0))
        rl = R_of(lifted)
        # peak-window polish
        win = _peak_window(lifted, pad_frac=0.03, extra=64)
        polished = _lbfgs_block(lifted, win, 200,
                                min(b_end - 0.3,
                                    time.process_time() + 3.0), tie=True)
        rp = R_of(polished)
        if rp > rl:
            lifted, rl = polished, rp
        print("lift step=%d n=%d R=%.9f (cur %.9f)" % (step, lifted.size, rl, curR))
        if rl > curR + 1e-15:
            cur, curR = lifted, rl
        else:
            break

    # ---- Phase C: lift back to full N and peak polish ----
    n_target = best.size
    if cur.size != n_target:
        if n_target % cur.size == 0:
            fac = n_target // cur.size
            full = np.repeat(cur, fac)
        else:
            full = np.interp(np.linspace(0, cur.size - 1, n_target),
                             np.arange(cur.size), cur)
    else:
        full = cur
    full = _rescale(full)
    rfull = R_of(full)
    if rfull > bestR + 1e-15:
        best, bestR = full.copy(), rfull
        print("lift ACCEPT R=%.9f" % bestR)

    c_end = t0 + budget_seconds * 0.99
    for pad in (0.06, 0.03, 0.02):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= c_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(c_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.05, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_polish(h, deadline, iters=150):
    if time.process_time() >= deadline - 0.3:
        return h
    win = _peak_window(h, pad_frac=0.05, extra=64)
    ht = _lbfgs_block(h, win, iters, deadline - 0.2, tie=True)
    if R_of(ht) > R_of(h) + 1e-14:
        return ht
    return h


def _mass_resample(base, newN):
    """Mass-preserving cumulative-sum resample to newN bins."""
    n = base.size
    c = np.cumsum(base)
    tot = c[-1]
    if tot <= 0:
        return _rescale(np.ones(newN))
    c = c / tot
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    cm = np.interp(x_new, x_old, c, left=0.0, right=1.0)
    h = np.diff(np.concatenate(([0.0], cm)))
    h = np.clip(h, 0, None)
    return _rescale(h)


def _jitter(h, rng, sigma=0.05):
    n = h.size
    out = h.copy()
    i = 0
    while i < n:
        blk = int(rng.integers(2, 33))
        j = min(n, i + blk)
        f = np.exp(rng.normal(0.0, sigma))
        out[i:j] *= f
        i = j
    return _rescale(np.clip(out, 0, None))


def _jitter_round(h, deadline, rng, rounds=4, iters=200):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _jitter(best, rng, sigma=0.05)
        cand = _lbfgs_all_pos(cand, iters, deadline - 0.3, tie=True)
        if time.process_time() < deadline - 0.5:
            cand = _peak_polish(cand, deadline - 0.2, iters=100)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best = cand
            bestR = r
    return best


def _ladder(seed, levels, deadline, rng, rounds=4):
    """Run the mass-preserving resampling ladder with per-level polish."""
    h = seed
    best_small = None
    best_smallR = -1.0
    for n_new in levels:
        if time.process_time() >= deadline - 1.0:
            break
        h = _mass_resample(h, n_new)
        h = _lbfgs_all_pos(h, 300, deadline - 0.5, tie=True)
        h = _jitter_round(h, deadline, rng, rounds=rounds, iters=200)
        r = R_of(h)
        print("  ladder N=%d R=%.9f" % (n_new, r))
        if n_new <= 4096 and r > best_smallR:
            best_smallR = r
            best_small = h.copy()
    return h, best_small, best_smallR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
