    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR

    # ---- Main improvement loop: refine (upsample) + polish ----
    # Alternate between refining the grid (which increases resolution around
    # the peak, where the constraint is active) and polishing with L-BFGS.
    # This lets the peak region become sharper than the base grid allows.
    round_i = 0
    while time.process_time() < deadline - 4.0:
        round_i += 1
        n_cur = bestH.size
        # Only refine if we can afford it and stay under 1e6 steps
        if n_cur * 2 <= 900000:
            hc = _refine(bestH)
        else:
            hc = bestH.copy()
        hc = _rescale(hc)
        rc = R_of(hc)
        cap = min(deadline - 3.0, time.process_time() + 4.0)
        hp = _lbfgs_log(hc, 200, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            print("  round %d refine N=%d -> R=%.9f" % (round_i, bestH.size, bestR))
        else:
            # refining didn't help; try polishing current best harder
            cap = min(deadline - 2.0, time.process_time() + 3.0)
            hp2 = _lbfgs_log(bestH, 300, cap, beta=0.0)
            rp2 = R_of(hp2)
            if rp2 > bestR + 1e-14:
                bestH, bestR = hp2.copy(), rp2
                print("  round %d polish -> R=%.9f" % (round_i, bestR))
            else:
                break

    # ---- Peak-window polish at high resolution ----
    if time.process_time() < deadline - 2.0:
        free = _peak_window(bestH, tol=0.999, pad_frac=0.3, extra=512)
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        hp = _lbfgs_block(bestH, free, 300, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            print("  final peak-window -> R=%.9f" % bestR)

    # ---- Final global polish ----
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.2, time.process_time() + 2.0)
        hs = _lbfgs_log(bestH, 300, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            print("  final global -> R=%.9f" % bestR)

    mx, m, near = _stats(bestH)
    print("final N=%d zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))
    print("final exact R=%.9f (base %.9f)" % (bestR, baseR))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        return {"best": baseH, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    if beta > 0:
        e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
        Z = e.sum()
        if Z > 0:
            w = e / Z
            sm = mx + np.log(Z) / beta
            gLf = -dq / num + w / sm
            grad = _backprop(gLf, h) + 2.0 / s
            val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
            return val, grad
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_beta(hh, beta)

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 3 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 4:
        return h.copy()
    return h[:m * factor].reshape(m, factor).sum(axis=1)


def _upsample(h, factor, target):
    out = np.repeat(h, factor)
    if out.size < target:
        out = np.concatenate([out, np.zeros(target - out.size)])
    return out[:target]


def _multiscale_polish(h, bestR, deadline):
    if time.process_time() >= deadline - 0.5:
        return h, bestR
    cur = h.copy()
    curR = bestR
    for f in [8, 4, 2]:
        if time.process_time() >= deadline - 0.5:
            break
        if cur.size // f < 32:
            continue
        hd = _rescale(_downsample(cur, f))
        best_d = hd.copy()
        best_rd = R_of(hd)
        for beta in (0.0, 1e7):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all(best_d, 400, deadline, beta=beta)
            rt = R_of(ht)
            if rt > best_rd + 1e-13:
                best_d, best_rd = ht, rt
        hu = _rescale(_upsample(best_d, f, cur.size))
        ru = R_of(hu)
        for beta in (0.0, 1e7):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all(hu, 300, deadline, beta=beta)
            rt = R_of(ht)
            if rt > ru + 1e-13:
                hu, ru = ht, rt
        if ru > curR + 1e-13:
            cur, curR = hu, ru
    return cur, curR


def _seed_parabola(N):
    x = np.linspace(-1, 1, N)
    return _rescale(np.sqrt(np.clip(1.0 - x * x, 0, None)))


def _seed_cosine(N):
    x = np.linspace(0, 1, N)
    return _rescale(np.cos(np.pi * (x - 0.5)) ** 2)


def _seed_gauss(N):
    x = np.linspace(-3, 3, N)
    return _rescale(np.exp(-x * x))


def _seed_uniform(N):
    return _rescale(np.ones(N))


def _seed_parabola_mix(N, p):
    x = np.linspace(-1, 1, N)
    return _rescale(np.clip(1.0 - np.abs(x) ** p, 0, None) ** (1.0 / p))


def _phase_flat(h, deadline, iters=200):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h, R_of(h)
    s0, s1 = int(pos[0]), int(pos[-1])
    M = 1
    while M < 4 * n:
        M *= 2
    gk = np.zeros(M)
    lo, hi = 2 * s0, 2 * s1
    if hi <= lo:
        return h, R_of(h)
    span = hi - lo
    ramp = max(1, span // 20)
    gk[lo:hi + 1] = 1.0
    t = np.linspace(0, np.pi, ramp)
    rampup = 0.5 * (1 - np.cos(t))
    gk[lo:lo + ramp] *= rampup
    gk[hi - ramp + 1:hi + 1] *= rampup[::-1]
    A = np.sqrt(np.abs(np.fft.fft(gk)))
    f_pad = np.zeros(M)
    f_pad[:n] = np.clip(h, 0, None)
    mask = np.zeros(M, dtype=bool)
    mask[s0:s1 + 1] = True
    cand = h.copy()
    candR = R_of(cand)
    for it in range(iters):
        if time.process_time() >= deadline - 0.5:
            break
        F = np.fft.fft(f_pad)
        mag = np.abs(F)
        phase = F / np.maximum(mag, 1e-30)
        f_new = np.real(np.fft.ifft(A * phase))
        f_new = np.clip(f_new, 0, None)
        f_new[~mask] = 0.0
        f_pad = 0.6 * f_new + 0.4 * f_pad
        f_pad = np.clip(f_pad, 0, None)
        f_pad[~mask] = 0.0
        if it % 25 == 24:
            hc = _rescale(f_pad[:n].copy())
            hp = _lbfgs_all(hc, 60, deadline, beta=0.0)
            rp = R_of(hp)
            if rp > candR + 1e-13:
                cand, candR = hp, rp
    return cand, candR


def _local_perturb(h, rng, scale=0.05):
    """Perturb a fraction of heights by multiplicative noise, then rescale."""
    hh = h.copy()
    n = hh.size
    k = max(1, n // 50)
    idx = rng.integers(0, n, size=k)
    hh[idx] *= np.exp(rng.normal(0, scale, size=k))
    return _rescale(hh)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        best = _seed_cosine(2048)
        bestR = R_of(best)

    print("start R=%.7f N=%d" % (bestR, best.size))
    start_best = best.copy()
    start_bestR = bestR

    alt = None
    altR = -1.0

    # 1. Multi-scale polish
    if time.process_time() < deadline - 5.0:
        try:
            hm, rm = _multiscale_polish(best, bestR, deadline - 4.0)
            print("multiscale R=%.7f (d=%.2e)" % (rm, rm - bestR))
            if rm > altR:
                alt, altR = hm.copy(), rm
            if rm > bestR + 1e-13:
                best, bestR = hm.copy(), rm
        except Exception as e:
            print("multiscale failed: %s" % e)

    # 2. Phase-flat
    if time.process_time() < deadline - 6.0:
        try:
            hc, rc = _phase_flat(best, deadline - 5.0, iters=200)
            print("phaseflat raw R=%.7f" % rc)
            if rc > altR:
                alt, altR = hc.copy(), rc
            if rc > bestR + 1e-13:
                best, bestR = hc.copy(), rc
        except Exception as e:
            print("phaseflat failed: %s" % e)

    # 3. Fresh seeds
    if time.process_time() < deadline - 10.0:
        N = best.size
        seeds = [("parab", _seed_parabola(N)), ("cos", _seed_cosine(N)),
                 ("gauss", _seed_gauss(N)), ("unif", _seed_uniform(N))]
        for p in (1.5, 2.0, 2.5, 3.0, 4.0):
            seeds.append(("mix%.1f" % p, _seed_parabola_mix(N, p)))
        for name, hs in seeds:
            if time.process_time() >= deadline - 8.0:
                break
            try:
                hp = _lbfgs_all(hs, 300, deadline - 7.0, beta=0.0)
                hp2 = _lbfgs_all(hp, 200, deadline - 7.0, beta=1e7)
                rp = R_of(hp); rp2 = R_of(hp2)
                if rp2 >= rp:
                    hh, rr = hp2, rp2
                else:
                    hh, rr = hp, rp
                if rr > altR:
                    alt, altR = hh.copy(), rr
                if rr > bestR + 1e-13:
                    best, bestR = hh.copy(), rr
                    print("  seed %s -> R=%.7f" % (name, rr))
            except Exception:
                pass

    # 4. Random perturbation restarts around best (new idea)
    if time.process_time() < deadline - 3.0:
        tries = 0
        gains = 0
        while time.process_time() < deadline - 3.0:
            tries += 1
            scale = 0.02 + 0.08 * rng.random()
            hp = _local_perturb(best, rng, scale=scale)
            hp = _lbfgs_all(hp, 150, deadline - 2.5, beta=0.0)
            rp = R_of(hp)
            if rp > altR:
                alt, altR = hp.copy(), rp
            if rp > bestR + 1e-13:
                best, bestR = hp.copy(), rp
                gains += 1
                print("  perturb #%d -> R=%.7f" % (tries, rp))
        print("perturb: %d tries, %d gains" % (tries, gains))

    # 5. Final intensive polish
    if time.process_time() < deadline - 1.0:
        for beta in (0.0, 1e7, 0.0):
            if time.process_time() >= deadline - 0.8:
                break
            ht = _lbfgs_all(best, 800, deadline - 0.6, beta=beta)
            rt = R_of(ht)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
        print("final polish R=%.7f" % bestR)

    print("FINAL R=%.7f N=%d" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- repeat detection ----------
def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


# ---------- coarse L-BFGS on log heights ----------
def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        start = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[start:start + L] *= fac
    return c2


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


# ---------- trust-region Newton on compressed quotient c = v**2 ----------
def _trust_newton(c0, deadline, method='trust-ncg', init_radius=1e-3):
    if time.process_time() >= deadline - 0.5:
        return c0
    c0 = np.clip(c0, 1e-30, None)
    v0 = np.sqrt(c0)

    def fg(v):
        c = v * v
        val, g = _fun_grad_tie(c)
        return val, 2.0 * v * g

    def hessp(v, w):
        eps = 1e-6 * (1.0 + np.linalg.norm(v))
        vp = v + eps * w
        vm = v - eps * w
        cp = vp * vp
        cm = vm * vm
        _, gp = _fun_grad_tie(cp)
        _, gm = _fun_grad_tie(cm)
        gvp = 2.0 * vp * gp
        gvm = 2.0 * vm * gm
        return (gvp - gvm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg, v0, jac=True, method=method, hessp=hessp,
                       callback=cb,
                       options={'maxiter': 300,
                                'initial_trust_radius': init_radius,
                                'max_trust_radius': 0.5,
                                'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None or not np.all(np.isfinite(res.x)):
        return c0
    c = res.x * res.x
    return _rescale(c)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- Phase A: coarse jitter + repolish ----
    a_end = t0 + budget_seconds * 0.30
    rng = np.random.default_rng(12345)
    c_best = c.copy()
    cR = R_of(c_best)
    accepted = 0
    rounds = 0
    while time.process_time() < a_end - 0.5:
        rounds += 1
        cj = _jitter(c_best, rng)
        cj = _lbfgs_log(cj, 150, min(a_end - 0.3,
                                     time.process_time() + 1.5))
        rj = R_of(cj)
        if rj > cR + 1e-15:
            c_best, cR = cj, rj
            accepted += 1
    print("PhaseA rounds=%d accepted=%d cR=%.9f" % (rounds, accepted, cR))

    # ---- Phase B: interpolating lift ladder ----
    b_end = t0 + budget_seconds * 0.60
    cur = c_best.copy()
    curR = cR
    for step in range(4):
        if time.process_time() >= b_end - 1.0:
            break
        if cur.size * 2 > 300000:
            break
        lifted = _interp_lift(cur)
        lifted = _lbfgs_log(lifted, 200, min(b_end - 0.5,
                                             time.process_time() + 6.0))
        rl = R_of(lifted)
        win = _peak_window(lifted, pad_frac=0.03, extra=64)
        polished = _lbfgs_block(lifted, win, 200,
                                min(b_end - 0.3,
                                    time.process_time() + 3.0), tie=True)
        rp = R_of(polished)
        if rp > rl:
            lifted, rl = polished, rp
        print("lift step=%d n=%d R=%.9f (cur %.9f)" % (step, lifted.size, rl, curR))
        if rl > curR + 1e-15:
            cur, curR = lifted, rl
        else:
            break

    # ---- Phase C: lift back to full N and peak polish ----
    n_target = best.size
    if cur.size != n_target:
        if n_target % cur.size == 0:
            fac = n_target // cur.size
            full = np.repeat(cur, fac)
        else:
            full = np.interp(np.linspace(0, cur.size - 1, n_target),
                             np.arange(cur.size), cur)
    else:
        full = cur
    full = _rescale(full)
    rfull = R_of(full)
    if rfull > bestR + 1e-15:
        best, bestR = full.copy(), rfull
        print("lift ACCEPT R=%.9f" % bestR)

    # ---- Phase D: trust-region Newton on compressed quotient ----
    d_end = t0 + budget_seconds * 0.80
    if time.process_time() < d_end - 1.0:
        _, c_now = _detect_repeat(best)
        if c_now.size == best.size:
            # fall back: block-mean compress
            n = min(4096, best.size)
            if best.size % n == 0:
                c_now = best.reshape(-1, best.size // n).mean(axis=1)
            else:
                c_now = np.interp(np.linspace(0, best.size - 1, n),
                                  np.arange(best.size), best)
        c_now = _rescale(np.clip(c_now, 1e-30, None))
        cR0 = R_of(c_now)
        print("Newton start n_c=%d cR=%.9f" % (c_now.size, cR0))
        c_new = _trust_newton(c_now, d_end, 'trust-ncg', 1e-3)
        cRn = R_of(c_new)
        if cRn <= cR0 + 1e-15 and time.process_time() < d_end - 1.0:
            c_new2 = _trust_newton(c_now, d_end, 'trust-krylov', 1e-2)
            if R_of(c_new2) > cRn:
                c_new, cRn = c_new2, R_of(c_new2)
        print("Newton end cR=%.9f (was %.9f)" % (cRn, cR0))
        if cRn > cR0 + 1e-15:
            # lift back to full size
            if best.size % c_new.size == 0:
                fac = best.size // c_new.size
                full2 = np.repeat(c_new, fac)
            else:
                full2 = np.interp(np.linspace(0, c_new.size - 1, best.size),
                                  np.arange(c_new.size), c_new)
            full2 = _rescale(full2)
            rf = R_of(full2)
            print("Newton lift R(full)=%.9f" % rf)
            if rf > bestR + 1e-15:
                best, bestR = full2.copy(), rf
                print("Newton ACCEPT R=%.9f" % bestR)

    # ---- Phase E: final peak polish ----
    c_end = t0 + budget_seconds * 0.99
    for pad in (0.06, 0.03, 0.02):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= c_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(c_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline, tie=True):
    n = h0.size
    return _lbfgs_block(h0, np.arange(n), maxiter, deadline, tie=tie)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- Experiment: break 32-fold symmetry, assume 16-fold ----
    # Build p of length 2n from c, then h = repeat(p, 16) -> N = 32n
    n = c.size
    rng = np.random.default_rng(20240607)
    i = np.arange(n, dtype=float)
    a = 0.06 * np.sin(2.0 * np.pi * i / 7.0) + 0.02 * rng.standard_normal(n)
    p2 = np.empty(2 * n)
    p2[0::2] = c * (1.0 + a)
    p2[1::2] = c * (1.0 - a)
    p2 = np.clip(p2, 0, None)
    h_break = np.repeat(p2, 16)
    h_break = _rescale(h_break)
    R0 = R_of(h_break)
    print("break R0=%.9f (start %.9f)" % (R0, startR))

    alt_best = h_break.copy()
    alt_bestR = R0

    # ---- Fold/optimise alternation ----
    fold_end = t0 + budget_seconds * 0.93
    cur = h_break.copy()
    curR = R0
    round_r = 0
    first_fold_R = None
    accepted_total = 0
    while time.process_time() < fold_end - 1.0:
        round_r += 1
        slice_end = min(fold_end - 0.5, time.process_time() + 4.0)
        # (a) full-array tie L-BFGS
        h_opt = _lbfgs_all_pos(cur, 60, slice_end, tie=True)
        r_opt = R_of(h_opt)
        # (b) fold back to 16-fold periodicity
        if h_opt.size % 16 == 0:
            p_new = h_opt.reshape(-1, 16).mean(axis=1)
            h_new = np.repeat(p_new, 16)
        else:
            h_new = h_opt
        h_new = _rescale(h_new)
        r_new = R_of(h_new)
        if first_fold_R is None:
            first_fold_R = r_new
        accepted = False
        # candidate is the better of folded and unfolded
        if r_new >= r_opt:
            cand, candR = h_new, r_new
        else:
            cand, candR = h_opt, r_opt
        if candR > curR + 1e-15:
            cur, curR = cand, candR
            accepted = True
            accepted_total += 1
        if candR > alt_bestR + 1e-15:
            alt_best, alt_bestR = cand.copy(), candR
        print("round %d R=%.9f accepted=%d (cur %.9f)" %
              (round_r, candR, int(accepted), curR))
        if time.process_time() >= fold_end - 1.0:
            break

    if first_fold_R is not None:
        print("first fold R=%.12f vs R0=%.12f diff=%.3e" %
              (first_fold_R, R0, first_fold_R - R0))

    # ---- Final: peak-window tie polish + one full tie L-BFGS on global best ----
    c_end = t0 + budget_seconds * 0.99
    for pad in (0.05, 0.02):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(alt_best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(alt_best, win, 300,
                          min(c_end - 0.5, time.process_time() + 3.0),
                          tie=True)
        r = R_of(ht)
        if r > alt_bestR + 1e-15:
            alt_best, alt_bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, alt_bestR))

    if time.process_time() < c_end - 0.8:
        ht = _lbfgs_all_pos(alt_best, 200,
                            min(c_end - 0.5, time.process_time() + 4.0),
                            tie=True)
        r = R_of(ht)
        if r > alt_bestR + 1e-15:
            alt_best, alt_bestR = ht.copy(), r
        print("final full tie R=%.9f" % alt_bestR)

    print("final alt R=%.9f (start %.9f, N=%d, ties=%d)" %
          (alt_bestR, startR, alt_best.size, _tie_count(alt_best)))

    result = {}
    if alt_bestR > startR + 1e-14:
        result["best"] = alt_best
        if start is not None:
            result["alternative"] = best
    else:
        result["best"] = best
        result["alternative"] = alt_best
    return result

