        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _upsample(h, N1):
    N0 = h.size
    xi = (np.arange(N1) + 0.5) / N1 * N0 - 0.5
    xi = np.clip(xi, 0, N0 - 1)
    lo = np.floor(xi).astype(int)
    hi = np.minimum(lo + 1, N0 - 1)
    w = xi - lo
    return h[lo] * (1 - w) + h[hi] * w


def construct(budget_seconds, start):
    t0 = time.process_time()
