    result = {"best": best}
    # Provide alternative if we have a genuinely different construction
    if alt_h is not None and alt_h.size != best.size:
        result["alternative"] = alt_h
    elif bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = start_best
    return result

