    # =====================================================================
    rng = np.random.default_rng(20240607)
    n = best.size
    exp_end = t0 + budget_seconds * 0.90

    cur = best.copy()
    curR = bestR
    rounds = 0
    accepted = 0
    while time.process_time() < exp_end - 1.0 and rounds < 8:
        rounds += 1
        # perturb 4 random windows
        trial = cur.copy()
        for _ in range(4):
            L = int(rng.integers(128, 513))
            if L >= n:
                L = n
            s = int(rng.integers(0, n - L + 1))
            fac = 1.0 + 0.02 * rng.standard_normal(L)
            trial[s:s + L] = np.clip(trial[s:s + L] * fac, 0.0, None)
        r_before = R_of(trial)
        # full-array L-BFGS-B with exact tie gradient
        allidx = np.arange(n)
        trial2 = _lbfgs_block(trial, allidx, 250,
                              min(exp_end - 0.5,
                                  time.process_time() + 4.0), tie=True)
        r_after = R_of(trial2)
        changed = int(np.sum(np.abs(trial2 - trial) > 1e-9))
        print("round %d: R %.9f -> %.9f (changed %d)" %
              (rounds, r_before, r_after, changed))
        # peak-window tie polish at pads 0.06/0.03
        cand = trial2
        candR = r_after
        for pad in (0.06, 0.03):
            if time.process_time() >= exp_end - 0.5:
                break
            win = _peak_window(cand, pad_frac=pad, extra=96)
            ht = _lbfgs_block(cand, win, 300,
                              min(exp_end - 0.3,
                                  time.process_time() + 2.0), tie=True)
            rt = R_of(ht)
            if rt > candR:
                cand, candR = ht, rt
        if candR > curR + 1e-15:
            cur, curR = cand, candR
            accepted += 1
            if curR > bestR:
                best, bestR = cur.copy(), curR
        # else revert (cur unchanged)
    print("experiment rounds=%d accepted=%d bestR=%.9f" % (rounds, accepted, bestR))

    # =====================================================================
    # Final seconds: pads 0.02/0.01 polish of best
    # =====================================================================
    c_end = t0 + budget_seconds * 0.99
    for pad in (0.02, 0.01):
        if time.process_time() >= c_end - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=64)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= c_end - 0.5:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(c_end - 0.3,
                                  time.process_time() + 2.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("final pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, deadline, verbose=""):
    """Multi-stage polish: full -> tie -> peak-window cycles."""
    best = _rescale(np.asarray(h, dtype=float))
    bestR = R_of(best)
    n = best.size
    full = np.arange(n)

    def upd(hh):
        nonlocal best, bestR
        hh = _rescale(hh)
        r = R_of(hh)
        if r > bestR + 1e-12:
            bestR = r
            best = hh
        return r

    # Stage 1: full L-BFGS
    if time.process_time() < deadline - 0.5:
        hh = _lbfgs_block(best, full, 400, min(deadline, time.process_time() + 0.30 * (deadline - time.process_time())))
        upd(hh)
    # Stage 2: tie
    if time.process_time() < deadline - 0.5:
        hh = _lbfgs_block(best, full, 300, min(deadline, time.process_time() + 0.15 * (deadline - time.process_time())), tie=True)
        upd(hh)
    # Stage 3: peak window cycles
    cycle = 0
    while time.process_time() < deadline - 0.5:
        win = _peak_window(best)
        hh = _lbfgs_block(best, win, 200,
                          min(deadline, time.process_time() + 0.08 * (deadline - time.process_time())),
                          tie=(cycle % 2 == 1))
        r = upd(hh)
        cycle += 1
        if cycle > 300:
            break
    return best


def _escalate(h, N):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == N:
        return _rescale(h.copy())
    c = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, c[-1], N + 1)
    newc = np.interp(xs, np.linspace(0.0, c[-1], n + 1), c)
    out = np.diff(newc)
    return _rescale(np.maximum(out, 0.0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds * 0.94

    best = None
    bestR = -1.0
    alt = None
    altR = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best = _rescale(s.copy())
            bestR = R_of(best)

    # ---- Step 1: polish the start as-is (cheap but high value) ----
    if best is not None and time.process_time() < hard - 1.0:
        dl = min(hard, time.process_time() + 0.25 * (hard - time.process_time()))
        hp = _polish(best, dl)
        Rp = R_of(hp)
        if Rp > bestR:
            best = hp; bestR = Rp

    # ---- Step 2: try a different N (upsample to sharpen) ----
    # If start is present, try denser discretization at 1.5x and 2x; if it wins, keep it as alt.
    if best is not None and time.process_time() < hard - 2.0:
        n0 = best.size
        for mult in (2, 3):
            if time.process_time() > hard - 2.0:
                break
            N = min(1000000, n0 * mult)
            if N == n0:
                continue
            cand = _escalate(best, N)
            dl = min(hard, time.process_time() + 0.20 * (hard - time.process_time()))
            hp = _polish(cand, dl)
            Rp = R_of(hp)
            print(f"escalate N={N} R={Rp:.6f}")
            if Rp > bestR:
                alt = best.copy(); altR = bestR
                best = hp; bestR = Rp
            elif Rp > altR:
                alt = hp; altR = Rp

    # ---- Step 3: fresh start from a smooth seed if no start, or to diversify ----
    if best is None:
        N = 4096
        x = np.linspace(0, 1, N)
        # smooth bump seed (roughly matching known optima shapes)
        h0 = np.exp(-((x - 0.5) ** 2) / 0.05)
        best = _rescale(h0)
        bestR = R_of(best)

    # ---- Step 4: spend remaining time cycling polish on best ----
    while time.process_time() < hard - 0.5:
        dl = min(hard, time.process_time() + 0.5 * (hard - time.process_time()))
        hp = _polish(best, dl)
        Rp = R_of(hp)
        if Rp > bestR + 1e-12:
            best = hp; bestR = Rp
        else:
            # no gain: try small perturbation to escape
            pert = best * (1.0 + 0.01 * np.random.default_rng(int(time.process_time() * 1000) % 2**31).standard_normal(best.size))
            pert = np.clip(pert, 0, None)
            if pert.sum() > 0:
                dl2 = min(hard, time.process_time() + 0.3 * (hard - time.process_time()))
                hp2 = _polish(_rescale(pert), dl2)
                Rp2 = R_of(hp2)
                if Rp2 > bestR + 1e-12:
                    best = hp2; bestR = Rp2
                elif Rp2 > altR:
                    alt = hp2; altR = Rp2
            break

    best = _rescale(best)
    print(f"final R={R_of(best):.6f} N={best.size}")

    # Compare against start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            Rs = R_of(s)
            Rb = R_of(best)
            if Rs > Rb:
                if alt is not None and R_of(alt) > 0:
                    return {"best": s, "alternative": alt}
                return {"best": s, "alternative": best}
    if alt is not None and altR > 0 and R_of(alt) < R_of(best) and alt.size != best.size:
        return {"best": best, "alternative": alt}
    return best

