            pert = best * (1.0 + 0.01 * np.random.default_rng(int(time.process_time() * 1000) % 2**31).standard_normal(best.size))
            pert = np.clip(pert, 0, None)
            if pert.sum() > 0:
                dl2 = min(hard, time.process_time() + 0.3 * (hard - time.process_time()))
                hp2 = _polish(_rescale(pert), dl2)
                Rp2 = R_of(hp2)
                if Rp2 > bestR + 1e-12:
                    best = hp2; bestR = Rp2
                elif Rp2 > altR:
                    alt = hp2; altR = Rp2
            break

    best = _rescale(best)
    print(f"final R={R_of(best):.6f} N={best.size}")

    # Compare against start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            Rs = R_of(s)
            Rb = R_of(best)
            if Rs > Rb:
                if alt is not None and R_of(alt) > 0:
                    return {"best": s, "alternative": alt}
                return {"best": s, "alternative": best}
    if alt is not None and altR > 0 and R_of(alt) < R_of(best) and alt.size != best.size:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_tie(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _tie_idx(h, tol=1e-10):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.array([], dtype=int)
    return np.flatnonzero(Lf >= mx * (1.0 - tol))


def _nullspace_dir(h, tie_idx, rng):
    """Random direction in the nullspace of the tie-knot gradients.
    Operates directly on h (not compressed). Returns unit vector or None."""
    n = h.size
    nk = n + 1
    k = tie_idx.size
    if k == 0 or k >= n - 1:
        return None
    # Build G rows one at a time via backprop of unit bumps at tie knots.
    # For efficiency batch: gLf matrix (k, nk) -> backprop each row.
    # Use matrix form: gL = gLf[:,1:-1] (k, n-1); grad_h = 2 * correlate.
    # stack: G = 2 * correlate(gL_row, h) -> use fft-based batched.
    G = np.empty((k, n))
    gLf_all = np.zeros((k, nk))
    gLf_all[np.arange(k), tie_idx] = 1.0
    # _backprop for each row
    gL = gLf_all[:, 1:-1]
    if n > 1500:
        # batched fftconvolve: do row by row (k small usually)
        for r in range(k):
            G[r] = 2.0 * fftconvolve(gL[r], h[::-1], mode='valid')[:n]
    else:
        for r in range(k):
            G[r] = 2.0 * np.correlate(gL[r], h, mode='valid')[:n]
    GGt = G @ G.T
    GGt[np.diag_indices_from(GGt)] += 1e-10
    v = rng.standard_normal(n)
    Gv = G @ v
    try:
        x = np.linalg.solve(GGt, Gv)
    except np.linalg.LinAlgError:
        return None
    vproj = v - G.T @ x
    nv = np.linalg.norm(vproj)
    if nv <= 0:
        return None
    return vproj / nv


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase N: nullspace exploration on full h with tie manifold ----
    # This is the main new attack: instead of compressing to c (which loses
    # the ability to break tie symmetry), work directly on the full h and
    # move along directions orthogonal to all tie-knot gradients.
    n_end = t0 + budget_seconds * 0.55
    rng = np.random.default_rng(2024)
    scales = [1e-8, 3e-8, 1e-7, 3e-7, 1e-6, 3e-6, 1e-5, 3e-5, 1e-4, 3e-4, 1e-3]
    nacc = 0
    nrounds = 0
    cur = best.copy()
    curR = bestR
    while time.process_time() < n_end - 1.0:
        nrounds += 1
        tie_idx = _tie_idx(cur)
        if tie_idx.size == 0:
            break
        v = _nullspace_dir(cur, tie_idx, rng)
        if v is None:
            break
        base = cur.mean()
        best_try = None
        best_try_r = curR
        for s in scales:
            cn = np.clip(cur + s * base * v, 0.0, None)
            if cn.sum() <= 0:
                continue
            r = R_of(cn)
            if r > best_try_r + 1e-15:
                best_try_r = r
                best_try = cn
        if best_try is not None:
            cur = best_try
            curR = best_try_r
            nacc += 1
            if nacc % 3 == 0:
                win = _peak_window(cur, pad_frac=0.05, extra=128)
                cur2 = _lbfgs_tie(cur, win, 60,
                                  min(n_end - 0.5,
                                      time.process_time() + 1.0))
                r2 = R_of(cur2)
                if r2 > curR + 1e-15:
                    cur, curR = cur2, r2
            if curR > bestR + 1e-15:
                best, bestR = _rescale(cur.copy()), curR
            if nacc % 5 == 0 or nacc == 1:
                print("PhaseN round=%d acc=%d R=%.9f" % (nrounds, nacc, bestR))
        else:
            # no scale helped; re-polish to escape
            win = _peak_window(cur, pad_frac=0.1, extra=256)
            cur2 = _lbfgs_tie(cur, win, 80,
                              min(n_end - 0.5, time.process_time() + 1.0))
            r2 = R_of(cur2)
            if r2 > curR + 1e-15:
                cur, curR = cur2, r2
                if curR > bestR + 1e-15:
                    best, bestR = _rescale(cur.copy()), curR
    print("PhaseN done rounds=%d acc=%d R=%.9f" % (nrounds, nacc, bestR))

    # ---- Phase D: trust-region Newton on compressed quotient ----
    d_end = t0 + budget_seconds * 0.80
    if time.process_time() < d_end - 2.0:
        p_now, c_now = _detect_repeat(best)
        if c_now.size == best.size:
            n = min(4096, best.size)
            if best.size % n == 0:
                c_now = best.reshape(-1, best.size // n).mean(axis=1)
            else:
                c_now = np.interp(np.linspace(0, best.size - 1, n),
                                  np.arange(best.size), best)
        c_now = _rescale(np.clip(c_now, 1e-30, None))
        cR0 = R_of(c_now)
        print("Newton start n_c=%d cR=%.9f" % (c_now.size, cR0))

        def _run_newton(c0, method, radius, dl):
            if time.process_time() >= dl - 0.5:
                return c0
            c0 = np.clip(c0, 1e-30, None)
            v0 = np.sqrt(c0)

            def fg(v):
                c = v * v
                val, g = _fun_grad_tie(c)
                return val, 2.0 * v * g

            def hessp(v, w):
                eps = 1e-6 * (1.0 + np.linalg.norm(v))
                vp = v + eps * w
                vm = v - eps * w
                _, gp = _fun_grad_tie(vp * vp)
                _, gm = _fun_grad_tie(vm * vm)
                gvp = 2.0 * vp * gp
                gvm = 2.0 * vm * gm
                return (gvp - gvm) / (2.0 * eps)

            cb = _make_cb(dl - 0.3)
            try:
                res = minimize(fg, v0, jac=True, method=method, hessp=hessp,
                               callback=cb,
                               options={'maxiter': 300,
                                        'initial_trust_radius': radius,
                                        'max_trust_radius': 0.5,
                                        'gtol': 1e-14})
            except (TimeoutError, Exception):
                return c0
            if res is None or not np.all(np.isfinite(res.x)):
                return c0
            return _rescale(res.x * res.x)

        c_new = _run_newton(c_now, 'trust-ncg', 1e-3, d_end)
        cRn = R_of(c_new)
        if cRn <= cR0 + 1e-15 and time.process_time() < d_end - 2.0:
            c_new2 = _run_newton(c_now, 'trust-krylov', 1e-2, d_end)
            if R_of(c_new2) > cRn:
                c_new, cRn = c_new2, R_of(c_new2)
        print("Newton end cR=%.9f (was %.9f)" % (cRn, cR0))
        if cRn > cR0 + 1e-15:
            if best.size % c_new.size == 0:
                fac = best.size // c_new.size
                full2 = np.repeat(c_new, fac)
            else:
                full2 = np.interp(np.linspace(0, c_new.size - 1, best.size),
                                  np.arange(c_new.size), c_new)
            full2 = _rescale(full2)
            rf = R_of(full2)
            if rf > bestR + 1e-15:
                best, bestR = full2.copy(), rf
                print("Newton ACCEPT R=%.9f" % bestR)

    # ---- Phase E: final peak polish ----
    c_end = t0 + budget_seconds * 0.98
    for pad in (0.06, 0.03, 0.015):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_tie(best, win, 300,
                        min(c_end - 0.5, time.process_time() + 3.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d)"
          % (bestR, startR, best.size))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, deadline, iters=350):
    for beta in (1e6, 1e7, 1e8, 0.0):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(h, np.arange(h.size), iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best, alt_bestR = None, -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r

    # Phase A: half-res quotient polish + lift
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 3.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10), iters=400)
            r = R_of(work_c)
            if r > cR + 1e-14:
                cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish(h_lift, deadline, iters=300)
        offer(h_lift, 'lift')

    # Phase B: tie-aware sharpening
    if time.process_time() < deadline - 3.0:
        ht = _lbfgs_block(best, np.arange(best.size), 400, deadline - 1.0, tie=True)
        offer(ht, 'tie')
        ht = _polish(ht, deadline - 1.0, iters=350)
        offer(ht, 'sharp')

    # Phase C: multi-stride quotient lift with weighted splits
    rng = np.random.RandomState(int(t0 * 1000) & 0xffffff)
    stride_deadline = deadline - 6.0
    strides = (3, 4, 2, 5, 6)
    accepted = []
    while time.process_time() < stride_deadline - 1.0:
        any_progress = False
        for k in strides:
            if time.process_time() >= stride_deadline - 1.0:
                break
            n = best.size
            m = n // k
            if m < 8:
                continue
            mk = m * k
            block = best[:mk].reshape(m, k)
            c = block.mean(axis=1)
            if c.sum() <= 0:
                continue
            c = _polish(c, stride_deadline - 0.5, iters=250)
            c = _peak_ladder(c, stride_deadline - 0.5, pads=(0.15, 0.10), iters=250)
            best_cand, best_candR = None, -1.0
            weights = [np.ones((m, k)) / k]
            for sigma in (0.1, 0.3, 0.6):
                w = np.exp(sigma * rng.randn(m, k))
                w = w / w.sum(axis=1, keepdims=True)
                weights.append(w)
            for w in weights:
                if time.process_time() >= stride_deadline - 0.5:
                    break
                h_new = np.zeros(n)
                vals = (k * c)[:, None] * w
                h_new[:mk] = vals.reshape(-1)
                if n > mk:
                    h_new[mk:] = best[mk:]
                h_new = _rescale(h_new)
                h_new = _polish(h_new, stride_deadline - 0.3, iters=250)
                h_new = _peak_ladder(h_new, stride_deadline - 0.3,
                                     pads=(0.10, 0.06), iters=200)
                r = R_of(h_new)
                if r > best_candR:
                    best_cand, best_candR = h_new, r
            if best_cand is not None:
                if best_candR > bestR + 1e-14:
                    best, bestR = best_cand.copy(), best_candR
                    accepted.append(k)
                    any_progress = True
                    print("stride %d ACCEPT R=%.9f" % (k, bestR))
                else:
                    if best_candR > alt_bestR and best_cand.size == best.size:
                        alt_best, alt_bestR = best_cand.copy(), best_candR
        if not any_progress:
            break
    if accepted:
        print("accepted strides: %s" % (accepted,))

    # Phase D: final polish
    ht = _polish(best, deadline - 1.0, iters=350)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.10, 0.06, 0.04), iters=400)
    offer(ht, 'finalpk')
    ht = _polish(best, deadline - 0.3, iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    c = (m - 1) / 2.0
    n = h.size
    w = max(3, int(pad * n))
    lo = max(0, int(c - w))
    hi = min(n, int(c + w) + 1)
    if hi - lo < 2:
        return np.arange(n)
    return np.arange(lo, hi)


def _perturb(h, s, k):
    n = h.size
    idx = np.arange(n)
    E = np.cos(2.0 * np.pi * k * (idx + 0.5) / n)
    return _rescale(np.clip(h * (1.0 + s * E), 0.0, None))


def _prolongate(h, N2):
    """Mass-preserving cumulative resampling to N2 steps."""
    N1 = h.size
    if N1 == N2:
        return _rescale(np.clip(h, 0, None))
    M = float(N1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, M, N2 + 1)
    cum_at = np.interp(edges, np.arange(N1 + 1), cum)
    mass = np.diff(cum_at)
    out = mass * (M / N2)
    return _rescale(np.clip(out, 0.0, None))


def _revive_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    zeros = np.flatnonzero(h <= 0)
    if zeros.size < 4:
        return h
    try:
        val, g = _fun_grad_tie(h)
    except Exception:
        return h
    score = g[zeros]
    k = max(1, int(0.03 * n))
    k = min(k, zeros.size)
    order = np.argsort(-score)
    pick = zeros[order[:k]]
    active_mean = h[h > 0].mean() if np.any(h > 0) else 1.0
    h2 = h.copy()
    h2[pick] = 0.02 * active_mean
    return _rescale(h2)


def _random_window_perturb(h, rng):
    """Multiply 4 random contiguous windows (len 4-32) by 1+0.02*N(0,1)."""
    n = h.size
    h2 = h.copy()
    for _ in range(4):
        L = int(rng.integers(4, 33))
        L = min(L, n)
        st = int(rng.integers(0, n - L + 1))
        factor = 1.0 + 0.02 * rng.standard_normal()
        h2[st:st + L] *= factor
    return _rescale(np.clip(h2, 0.0, None))


def _level_refine(h, level_deadline, rng):
    best = h
    bestR = R_of(best)

    def time_left():
        return time.process_time() < level_deadline - 0.3

    # (i) zero revival
    if time_left():
        cand = _revive_zeros(best)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # (ii) tie-aware full L-BFGS
    if time_left():
        cand = _lbfgs_all_pos(best, 300, level_deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # (iii) beta ladder
    for beta in (1e3, 1e5, 1e7):
        if not time_left():
            break
        cand = _lbfgs_all_pos(best, 150, level_deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # (iv) perturb-then-reoptimize rounds
    for _ in range(6):
        if not time_left():
            break
        cand = _random_window_perturb(best, rng)
        cand = _lbfgs_all_pos(cand, 100, level_deadline, tie=True)
        r = R_of(cand)
        if r > bestR + 1e-12:
            best, bestR = cand, r

    # (v) peak-window polish
    for pad in (0.10, 0.05, 0.02):
        if not time_left():
            break
        free = _peak_window(best, pad)
        cand = _lbfgs_block(best, free, 150, level_deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.95 * budget_seconds
    rng = np.random.default_rng(12345)

    best = None
    bestR = -1.0
    start_arr = None
    startR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.size >= 2 and s.sum() > 0:
            start_arr = s
            startR = R_of(s)
            best = s.copy()
            bestR = startR
            print("start R=%.6f N=%d" % (bestR, s.size))

    if best is None:
        n = 100
        x = (np.arange(n) + 0.5) / n
        h = np.exp(-40.0 * (x - 0.5) ** 2)
        best = _rescale(h)
        bestR = R_of(best)
        print("init bump R=%.6f" % bestR)

    ladder = [2048, 4096, 8192, 16384, 32768, 65536, 131072]
    work = best
    prev_level_R = None
    for li, N2 in enumerate(ladder):
        if time.process_time() >= deadline - 1.5:
            break
        now = time.process_time()
        remaining = deadline - now
        levels_left = len(ladder) - li
        # each level gets at most 15% of what's left, but at least fair share
        slice_cap = 0.15 * remaining
        fair = remaining / max(1, levels_left)
        slice_len = max(fair, min(slice_cap, remaining * 0.5))
        slice_len = min(slice_len, remaining - 0.5)
        if slice_len <= 0.5:
            break
        slice_end = now + slice_len

        work = _prolongate(work, N2)
        work, r = _level_refine(work, slice_end, rng)
        Lf = _knots(work)
        mx = Lf.max()
        zero_frac = float(np.mean(work <= 0))
        mean_h = work.mean() if work.mean() > 0 else 1.0
        maxmean = float(work.max() / mean_h)
        near01 = float(np.mean(Lf >= mx * 0.999))
        print("level N=%d R=%.9f zero=%.3f maxmean=%.2f near01=%.3f" %
              (work.size, r, zero_frac, maxmean, near01))
        if r > bestR:
            best, bestR = work.copy(), r
            prev_level_R = r
        else:
            # never continue with a non-improving state
            work = best.copy()
            if prev_level_R is not None and r - prev_level_R < 1e-5:
                # gains vanishing; still continue but note saturation
                print("  saturation hint: dR<1e-5")

    # Spend remaining time at deepest level: alternate peak-window / full polishes
    final_deadline = t0 + 0.97 * budget_seconds
    while time.process_time() < final_deadline - 1.0:
        free = _peak_window(best, 0.02)
        cand = _lbfgs_block(best, free, 150, final_deadline, tie=True)
        r = R_of(cand)
        if r > bestR + 1e-10:
            best, bestR = cand, r
            print("final pad0.02 R=%.9f N=%d" % (bestR, best.size))
            continue
        cand = _lbfgs_all_pos(best, 150, final_deadline, tie=True)
        r = R_of(cand)
        if r > bestR + 1e-10:
            best, bestR = cand, r
            print("final full R=%.9f N=%d" % (bestR, best.size))
            continue
        # try a random-window perturb round before giving up
        cand = _random_window_perturb(best, rng)
        cand = _lbfgs_all_pos(cand, 100, final_deadline, tie=True)
        r = R_of(cand)
        if r > bestR + 1e-10:
            best, bestR = cand, r
            print("final perturb R=%.9f N=%d" % (bestR, best.size))
            continue
        break

    best = _rescale(np.clip(best, 0, None))
    finalR = R_of(best)
    print("final R=%.9f N=%d" % (finalR, best.size))

    if start_arr is not None and startR >= finalR:
        return {"best": start_arr, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_polish(bestH, bestRH, iters, deadline, tol=0.999, fg=None):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH
    lo, hi = _peak_region(bestH, tol)
    span = hi - lo
    pad = max(64, int(span * 0.15))
    lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
    if hi2 > lo2:
        free = np.arange(lo2, hi2 + 1)
        hp = _lbfgs_block(bestH, free, iters, deadline, fg=fg)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            return hp.copy(), rp
    return bestH, bestRH


def _resample(h, factor):
    n = h.size
    m = n * factor
    x = (np.arange(m) + 0.5) * (n / m) - 0.5
    xi = np.clip(x, 0.0, n - 1)
    i0 = np.floor(xi).astype(int)
    i1 = np.minimum(i0 + 1, n - 1)
    w = xi - i0
    return (1.0 - w) * h[i0] + w * h[i1]


def _split_attempt(bestH, bestRH, deadline, rng, fg=None):
    if time.process_time() >= deadline - 1.0:
        return bestH, bestRH, None
    n = bestH.size
    if n * 2 > 500000:
        return bestH, bestRH, None
    try:
        h2 = _resample(bestH, 2)
    except Exception:
        return bestH, bestRH, None
    sub = min(deadline - 0.5, time.process_time() + 8.0)
    h2p = _lbfgs_log(h2, 200, sub, fg=fg)
    r2 = R_of(h2p)
    if r2 > bestRH + 1e-13:
        return h2p, r2, (n, n * 2)
    return bestH, bestRH, None


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    rng = np.random.default_rng(12345)

    ladder = (4, 8, 16, 32, 64, 128)
    loop_end = t0 + budget_seconds * 0.86
    roundN = 0
    refine_tried = 0
    max_refines = 4

    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 4.0:
        roundN += 1
        for p in ladder:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 4.0:
                break
            sub_deadline = min(loop_end, time.process_time() + 6.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(bestH, 150, sub_deadline, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  R%d p=%d R=%.7f" % (roundN, p, bestRH))

        # tie-aware polish: nudge toward making near-peak knots all equal
        if time.process_time() < loop_end - 1.0:
            sub2 = min(loop_end, time.process_time() + 5.0)
            ht = _lbfgs_log(bestH, 120, sub2, fg=_fun_grad_tie)
            rt = R_of(ht)
            if rt > bestRH + 1e-13:
                bestH, bestRH = ht.copy(), rt
            hs = _lbfgs_log(bestH, 120, sub2, fg=None)
            rs = R_of(hs)
            if rs > bestRH + 1e-13:
                bestH, bestRH = hs.copy(), rs
            bestH, bestRH = _peak_polish(bestH, bestRH, 120, sub2, tol=0.999)
            bestH, bestRH = _peak_polish(bestH, bestRH, 120, sub2, tol=0.9999)
            print("  R%d sharp+tie+peak R=%.7f" % (roundN, bestRH))

        if refine_tried < max_refines and time.process_time() < loop_end - 3.0:
            refine_tried += 1
            hn, rn, info = _split_attempt(bestH, bestRH, loop_end, rng, fg=_fun_grad_tie)
            if info is not None:
                bestH, bestRH = hn, rn
                print("  refine2x #%d -> N=%d R=%.7f" % (refine_tried, bestH.size, bestRH))

    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 300, deadline - 0.5, fg=_fun_grad_tie)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline, beta=beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, slice_dl, pad, beta=1e7):
    win = _peak_window(h, pad_frac=pad, extra=128)
    h2 = _lbfgs_block(h, win, 400, slice_dl, beta=beta)
    if time.process_time() < slice_dl - 0.4:
        h2 = _lbfgs_all_pos(h2, 300, slice_dl, beta=0.0)
    return h2


def _upsample2(h):
    # insert one interpolated step between each pair (doubles resolution)
    n = h.size
    out = np.empty(2 * n)
    out[0::2] = h
    out[1:-1:2] = 0.5 * (h[:-1] + h[1:])
    out[-1] = h[-1]
    return _rescale(out)


def _downsample2(h):
    n = h.size
    if n < 4:
        return h
    m = n // 2
    a = h[0:2 * m:2]
    b = h[1:2 * m:2]
    c = 0.5 * (a + b)
    return _rescale(c)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def try_update(ht, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("%s NEW BEST R=%.9f N=%d" % (tag, bestR, best.size))
            return True
        if r > alt_bestR and (alt_best is None or alt_best.size == ht.size):
            alt_best, alt_bestR = ht.copy(), r
        return False

    # ---- Phase 1: aggressive peak polish on current resolution ----
    polish_end = t0 + budget_seconds * 0.35
    pads = [0.04, 0.02, 0.01, 0.006, 0.004, 0.003]
    rnd = 0
    while time.process_time() < polish_end - 0.8:
        rnd += 1
        improved = False
        for pad in pads:
            if time.process_time() >= polish_end - 0.6:
                break
            slice_dl = min(polish_end, time.process_time() + 0.04 * budget_seconds)
            ht = _polish(best, slice_dl, pad)
            if try_update(ht, "pk%.3f" % pad):
                improved = True
        if not improved and rnd > 1:
            break

    # ---- Phase 2: resolution doubling with peak polish ----
    # The core new idea: upsample to a higher resolution, refine, and
    # accept only if the higher-resolution version beats the current best.
    # This lets the optimum sharpen its peak and smooth the tails.
    up_end = t0 + budget_seconds * 0.75
    while time.process_time() < up_end - 1.0 and best.size < 200000:
        now = time.process_time()
        slice_dl = min(up_end, now + 0.12 * budget_seconds)
        if slice_dl <= now + 0.6:
            break
        hu = _upsample2(best)
        # short polish on the upsampled version
        for pad in [0.02, 0.01, 0.005]:
            if time.process_time() >= slice_dl - 0.5:
                break
            hu = _polish(hu, min(slice_dl, time.process_time() + 0.03 * budget_seconds), pad)
        hu = _lbfgs_all_pos(hu, 300, slice_dl - 0.2, beta=0.0)
        if not try_update(hu, "up2"):
            # if upsampling fails, still try downsampling the current best
            # and re-lifting — sometimes coarser is better
            hd = _downsample2(best)
            for pad in [0.02, 0.01]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                hd = _polish(hd, min(slice_dl, time.process_time() + 0.03 * budget_seconds), pad)
            hd_up = _upsample2(hd)
            hd_up = _lbfgs_all_pos(hd_up, 200, slice_dl - 0.2, beta=0.0)
            try_update(hd_up, "down-up")
            break
        else:
            # also refresh alt from the upsampled version
            if alt_best is None or alt_best.size != hu.size:
                alt_best, alt_bestR = hu.copy(), R_of(hu)

    # ---- Phase 3: alternating polish on the best resolution until deadline ----
    while time.process_time() < deadline - 1.0:
        improved = False
        for pad in [0.015, 0.01, 0.006, 0.004, 0.003]:
            if time.process_time() >= deadline - 0.8:
                break
            slice_dl = min(deadline - 0.4, time.process_time() + 0.04 * budget_seconds)
            ht = _polish(best, slice_dl, pad)
            if try_update(ht, "late-pk%.3f" % pad):
                improved = True
        if time.process_time() < deadline - 0.9:
            slice_dl = min(deadline - 0.4, time.process_time() + 0.05 * budget_seconds)
            ht = _lbfgs_all_pos(best, 400, slice_dl, beta=0.0)
            if try_update(ht, "late-b0"):
                improved = True
        if not improved and time.process_time() > deadline - 2.0:
            break

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

