        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    c = (m - 1) / 2.0
    n = h.size
    w = max(3, int(pad * n))
    lo = max(0, int(c - w))
    hi = min(n, int(c + w) + 1)
    if hi - lo < 2:
        return np.arange(n)
    return np.arange(lo, hi)


def _prolongate(h, N2):
    """Mass-preserving cumulative resampling to N2 steps."""
    N1 = h.size
    if N1 == N2:
        return _rescale(np.clip(h, 0, None))
    M = float(N1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, M, N2 + 1)
    cum_at = np.interp(edges, np.arange(N1 + 1), cum)
    mass = np.diff(cum_at)
    out = mass * (M / N2)
    return _rescale(np.clip(out, 0.0, None))


def _coarsen(h, N2):
    """Mass-preserving cumsum resample down to N2 steps."""
    return _prolongate(h, N2)


def _tooth_perturb(h, rng, nteeth=64, sigma=0.06):
    """Find nteeth largest interior local maxima, multiply by 1+sigma*N(0,1)."""
    n = h.size
    if n < 3:
        return h.copy()
    left = h[1:-1] >= h[:-2]
    right = h[1:-1] >= h[2:]
    loc = np.flatnonzero(left & right) + 1
    if loc.size == 0:
        return h.copy()
    vals = h[loc]
    k = min(nteeth, loc.size)
    order = np.argsort(-vals)[:k]
    pick = loc[order]
    h2 = h.copy()
    factors = 1.0 + sigma * rng.standard_normal(pick.size)
    h2[pick] = np.clip(h2[pick] * factors, 0.0, None)
    return _rescale(h2)


def _polish(h, deadline, rng, pads=(0.15, 0.07, 0.03)):
    best = h
    bestR = R_of(best)
    cand = _lbfgs_all_pos(best, 300, deadline, tie=True)
    r = R_of(cand)
    if r > bestR:
        best, bestR = cand, r
    for beta in (1e6, 1e8):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _lbfgs_all_pos(best, 100, deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, pad)
        cand = _lbfgs_block(best, free, 150, deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.92 * budget_seconds
    rng = np.random.default_rng(20240607)

    # Establish baseline
    start_arr = None
    startR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.size >= 2 and s.sum() > 0:
            start_arr = s
            startR = R_of(s)
            print("start R=%.9f N=%d" % (startR, s.size))

    if start_arr is None:
        n = 200
        x = (np.arange(n) + 0.5) / n
        h = np.exp(-40.0 * (x - 0.5) ** 2)
        start_arr = _rescale(h)
        startR = R_of(start_arr)
        print("init bump R=%.9f" % startR)

    best = start_arr.copy()
    bestR = startR

    # (A) Coarsen to N=16384 and polish
    N_coarse = 16384
    coarse = _coarsen(start_arr, N_coarse)
    coarseR0 = R_of(coarse)
    print("coarsen N=%d R=%.9f" % (N_coarse, coarseR0))
    A_deadline = min(deadline - 0.5, time.process_time() + 0.20 * budget_seconds)
    coarse_p, coarseR = _polish(coarse, A_deadline, rng)
    print("A polish N=%d R=%.9f" % (coarse_p.size, coarseR))
    if coarseR > bestR:
        best, bestR = coarse_p.copy(), coarseR
        print("A accepted R=%.9f" % bestR)

    # (B) Tooth-height perturbation rounds at N=16384 until 75% of budget
    B_end = t0 + 0.75 * budget_seconds
    work = best.copy()
    workR = bestR
    # ensure we work at coarse resolution for tooth rounds
    if work.size != N_coarse:
        work = _coarsen(work, N_coarse)
        workR = R_of(work)
        if workR < bestR:
            # keep both: use coarse for exploration but track global best
            pass
    round_i = 0
    accepted = 0
    while time.process_time() < B_end - 1.0:
        round_i += 1
        seed = work.copy()
        seedR = workR
        cand = _tooth_perturb(seed, rng, nteeth=64, sigma=0.06)
        cand = _lbfgs_all_pos(cand, 200, B_end, tie=True)
        r = R_of(cand)
        if time.process_time() < B_end - 0.8:
            cand2 = _lbfgs_all_pos(cand, 100, B_end, beta=1e7)
            r2 = R_of(cand2)
            if r2 > r:
                cand, r = cand2, r2
        if r > seedR + 1e-12:
            work, workR = cand, r
            accepted += 1
            if r > bestR:
                best, bestR = cand.copy(), r
        else:
            work, workR = seed, seedR
        Lf = _knots(work)
        mx = Lf.max()
        zero_frac = float(np.mean(work <= 0))
        near01 = float(np.mean(Lf >= mx * 0.999))
        print("round %d R=%.9f bestR=%.9f zero=%.3f near01=%.3f acc=%d" %
              (round_i, workR, bestR, zero_frac, near01, accepted))

    # (C) Final 25%: lift best to 65536 then 131072, polish each
    final_deadline = t0 + 0.97 * budget_seconds
    lifted = best
    for N2 in (65536, 131072):
        if time.process_time() >= final_deadline - 2.0:
            break
        lifted = _prolongate(lifted, N2)
        r0 = R_of(lifted)
        # give each level a share
        now = time.process_time()
        remaining = final_deadline - now
        slice_end = now + max(1.0, remaining * 0.45)
        cand = _lbfgs_all_pos(lifted, 150, slice_end, tie=True)
        r = R_of(cand)
        if r > r0:
            lifted = cand
        for pad in (0.10, 0.05, 0.02):
            if time.process_time() >= slice_end - 0.5:
                break
            free = _peak_window(lifted, pad)
            cand = _lbfgs_block(lifted, free, 150, slice_end, tie=True)
            r = R_of(cand)
            if r > R_of(lifted):
                lifted = cand
        liftedR = R_of(lifted)
        print("lift N=%d R=%.9f" % (lifted.size, liftedR))
        if liftedR > bestR:
            best, bestR = lifted.copy(), liftedR

    # Final full tie L-BFGS on whichever of {lifted best, original p2021} is better
    if time.process_time() < final_deadline - 1.0:
        cand = _lbfgs_all_pos(best, 150, final_deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
            print("final full R=%.9f N=%d" % (bestR, best.size))

    best = _rescale(np.clip(best, 0, None))
    finalR = R_of(best)
    print("final R=%.9f N=%d" % (finalR, best.size))

    if start_arr is not None and startR >= finalR:
        return {"best": start_arr, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_beta.__defaults__ and None  # placeholder

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, int(idx.min()) - 1)
    hi = min(h.size - 1, int(idx.max()))
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)
    n = best.size

    # Phase 1: peak-focused beta-ladder polish (softmax of peak) to balance ties.
    cycle = 0
    while time.process_time() < deadline - 0.5:
        cycle += 1
        # Peak ladder with increasing beta (sharper peak focus) then decreasing.
        for beta in (30.0, 100.0, 300.0, 1000.0, 300.0, 100.0, 30.0, 10.0):
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, tol=0.999, pad_frac=0.4, extra=256)
            cap = min(deadline - 0.3, time.process_time() + 2.5)
            ht = _lbfgs_block(best, win, 300, cap, beta=beta)
            rt = R_of(ht)
            if rt > bestR + 1e-15:
                best, bestR = ht, rt
                print("  cyc=%d beta=%.0f R=%.9f" % (cycle, beta, bestR))

        # Random sub-window polish with softmax objective.
        for _ in range(4):
            if time.process_time() >= deadline - 0.5:
                break
            w = int(rng.uniform(0.03, 0.25) * n)
            w = max(8, min(n, w))
            a = int(rng.integers(0, max(1, n - w)))
            win = np.arange(a, a + w)
            cap = min(deadline - 0.3, time.process_time() + 1.5)
            ht = _lbfgs_block(best, win, 200, cap, beta=50.0)
            rt = R_of(ht)
            if rt > bestR + 1e-15:
                best, bestR = ht, rt
                print("  cyc=%d win R=%.9f" % (cycle, bestR))

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- key new idea: sub-step refinement (upsampling) ----------

def _upsample(h, k):
    """Insert k-1 interpolated steps between each existing step (linear)."""
    n = h.size
    if k <= 1:
        return h.copy()
    out = np.empty(n * k)
    # linear interpolation on the grid (piecewise linear in index space)
    x = np.linspace(0.0, n - 1.0, n * k)
    out[:] = np.interp(x, np.arange(n, dtype=float), h)
    return np.clip(out, 0.0, None)


def _smooth_refine(h, deadline, target_R, rng):
    """Repeatedly upsample+relax to escape the coarse grid."""
    best = h.copy()
    bestR = R_of(best)
    for k in (2, 2):
        if time.process_time() >= deadline - 2.0:
            break
        hu = _upsample(best, k)
        # relax with a soft-max objective to encourage flat top
        for beta in (1e4, 1e5, 1e6):
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_block(hu, np.arange(hu.size), 200,
                              min(deadline - 1.0, time.process_time() + 8.0),
                              beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                hu = ht
        # tie polish at this resolution
        if time.process_time() < deadline - 1.0:
            ht = _lbfgs_block(best, np.arange(best.size), 300,
                              min(deadline - 0.5, time.process_time() + 8.0),
                              tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    rng = np.random.default_rng(98765)

    # ---- Phase 1: peak-window polish on the coarse grid ----
    p1_end = t0 + budget_seconds * 0.30
    if time.process_time() < p1_end - 2.0:
        for pad in (0.10, 0.06, 0.04):
            if time.process_time() >= p1_end - 1.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 300,
                              min(p1_end - 1.0, time.process_time() + 6.0),
