                best, bestR = ht.copy(), r
            ht = _lbfgs_block(best, win, 300,
                              min(p1_end - 1.0, time.process_time() + 6.0),
                              tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("phase1 R=%.9f" % bestR)

    # ---- Phase 2: sub-step refinement (the new move) ----
    p2_end = t0 + budget_seconds * 0.65
    if time.process_time() < p2_end - 3.0:
        best, bestR = _smooth_refine(best, p2_end, bestR, rng)
        print("phase2 refine R=%.9f (N=%d, ties=%d)"
              % (bestR, best.size, _tie_count(best)))

    # ---- Phase 3: value-band polish at the finer resolution ----
    p3_end = t0 + budget_seconds * 0.90
    band_edges = [(0.0, 0.05), (0.05, 0.20), (0.20, 0.50),
                  (0.50, 0.80), (0.80, 0.95), (0.95, 1.001)]
    cyc = 0
    while time.process_time() < p3_end - 2.0:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        order = rng.permutation(len(band_edges))
        gains = []
        for bi in order:
            if time.process_time() >= p3_end - 1.5:
                break
            lo, hi = band_edges[bi]
            lo *= M; hi *= M
            sel = np.flatnonzero((best > 0) & (v >= lo) & (v < hi))
            if sel.size == 0:
                gains.append(0.0)
                continue
            # small dilation to keep the band local
            mask = np.zeros(n, dtype=bool)
            mask[sel] = True
            active = mask.copy()
            for d in (1, 2, 4):
                active[d:] |= mask[:-d]
                active[:-d] |= mask[d:]
            active = np.flatnonzero(active)
            if active.size < 20 or active.size > 0.8 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 200,
                              min(p3_end - 1.0,
                                  time.process_time() + 5.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
        f01, f1, f5 = _nearmax_fracs(best)
        print("band cyc=%d R=%.9f gains=%s near=%.3f/%.3f/%.3f"
              % (cyc, bestR,
                 " ".join("%.1e" % g for g in gains), f01, f1, f5))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase 4: final tie polish ----
    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 2.0:
        win = _peak_window(best, pad_frac=0.04, extra=64)
        ht = _lbfgs_block(best, win, 400, fd - 1.0, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


# ---------- spline basis ----------
def _bspline_basis(n, K):
    """Clamped cubic B-spline basis matrix (n x K) on [0,1] with K control points."""
    # K control points, degree 3. Use uniform interior knots.
    deg = 3
    # knot vector: deg+1 zeros, interior, deg+1 ones
    n_int = K - deg - 1
    if n_int < 0:
        n_int = 0
    interior = np.linspace(0, 1, n_int + 2)[1:-1] if n_int > 0 else np.array([])
    knots = np.concatenate(([0.0] * (deg + 1), interior, [1.0] * (deg + 1)))
    x = np.linspace(0, 1, n)
    B = np.zeros((n, K))
    # Cox-de Boor
    def basis(i, d, x):
        if d == 0:
            out = np.zeros_like(x)
            lo = knots[i]; hi = knots[i + 1]
            if hi > lo:
                out[(x >= lo) & (x < hi)] = 1.0
                if i + 1 == len(knots) - 1:
                    out[x == hi] = 1.0
            return out
        out = np.zeros_like(x)
        d1 = knots[i + d] - knots[i]
        if d1 > 0:
            out += (x - knots[i]) / d1 * basis(i, d - 1, x)
        d2 = knots[i + d + 1] - knots[i + 1]
        if d2 > 0:
            out += (knots[i + d + 1] - x) / d2 * basis(i + 1, d - 1, x)
        return out
    for i in range(K):
        B[:, i] = basis(i, deg, x)
    return B


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- (1) detect repeat ----
    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))
    if p > 1:
        rrep = R_of(np.repeat(c, p))
        print("repeat check R_rep=%.12f R_start=%.12f diff=%.2e"
              % (rrep, startR, abs(rrep - startR)))
    else:
        # no repeat: fall back to base behaviour (return start)
        print("no repeat detected; returning start")
        return {"best": best}

    # ---- (2) build spline basis ----
    K = 192
    n = c.size
    B = _bspline_basis(n, K)
    # least squares fit
    theta0, *_ = np.linalg.lstsq(B, c, rcond=None)
    c_comp = np.clip(B @ theta0, 0, None)
    # rescale c_comp to match mean of c so theta0 > 0
    if c_comp.mean() > 0:
        c_comp = c_comp * (c.mean() / c_comp.mean())
    theta0 = np.clip(theta0, 1e-12, None)
    c_comp = np.clip(B @ theta0, 0, None)
    R_comp = R_of(np.repeat(c_comp, p))
    print("R_comp=%.9f (K=%d)" % (R_comp, K))

    # ---- (3) optimize theta multiplicatively ----
    def R_theta(u):
        th = theta0 * np.exp(u)
        cc = np.clip(B @ th, 0, None)
        return R_of(np.repeat(cc, p))

    def fg_theta(u, beta):
        th = theta0 * np.exp(u)
        cc = np.clip(B @ th, 0, None)
        hh = np.repeat(cc, p)
        if beta > 0:
            val, g = _fun_grad_beta(hh, beta)
        else:
            val, g = _fun_grad_tie(hh)
        # g wrt hh; compress to cc: sum blocks
        gc = g.reshape(n, p).sum(axis=1)
        # chain through clip: derivative of clip at 0 is 0 where B@th<0
        mask = (B @ th) > 0
        gc = gc * mask
        # chain through B: g_theta = B^T gc
        gth = B.T @ gc
        # chain through theta = theta0*exp(u): g_u = gth * theta0 * exp(u)
        gu = gth * th
        return val, gu

    theta_best = theta0.copy()
    R_theta_best = R_comp
    u = np.zeros(K)
    for beta in (1e4, 1e6, 1e8):
        if time.process_time() >= deadline - 5.0:
            break
        def f(uu, _beta=beta):
            return fg_theta(uu, _beta)
        cb = _make_cb(deadline - 3.0)
        try:
            res = minimize(f, u, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': 150, 'maxfun': 300,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            u = res.x
        except (TimeoutError, Exception):
            pass
        th = theta0 * np.exp(u)
        cc = np.clip(B @ th, 0, None)
        r = R_of(np.repeat(cc, p))
        if r > R_theta_best:
            R_theta_best = r
            theta_best = th.copy()
        print("spline beta=%.0e R_spline=%.9f" % (beta, R_theta_best))

    c_spline = np.clip(B @ theta_best, 0, None)
    R_spline = R_theta_best
    print("R_spline=%.9f" % R_spline)

    # ---- (4) residual re-add ----
    r_res = c - c_spline
    best_c = c_spline.copy()
    best_cR = R_spline
    for alpha in (0.25, 0.5, 1.0):
        if time.process_time() >= deadline - 3.0:
            break
        c2 = np.clip(c_spline + alpha * r_res, 0, None)
        h2 = np.repeat(c2, p)
        win = _peak_window(h2, pad_frac=0.05, extra=128)
        h2p = _lbfgs_block(h2, win, 200,
                           min(deadline - 2.0, time.process_time() + 5.0),
                           tie=True)
        r2 = R_of(h2p)
        print("residual alpha=%.2f R=%.9f" % (alpha, r2))
        if r2 > best_cR:
            p3, c3 = _detect_repeat(h2p)
            if p3 == p:
                best_c = c3.copy()
            else:
                best_c = c2.copy()
            best_cR = r2

    # ---- (5) full polish at N ----
    full = np.repeat(best_c, p)
    full = _rescale(full)
    rfull = R_of(full)
    if rfull > bestR + 1e-15:
        best, bestR = full.copy(), rfull
        print("spline ACCEPT R=%.9f" % bestR)

    # full tie L-BFGS + peak polish
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.06, extra=128)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.5, time.process_time() + 4.0),
                          tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("full polish R=%.9f" % bestR)

    # knots within 0.1%
    Lf = _knots(best)
    frac = float(np.mean(Lf >= 0.999 * Lf.max()))
    print("R_comp=%.9f R_spline=%.9f R_best=%.9f frac0.1%%=%.4f"
          % (R_comp, R_spline, bestR, frac))

    result = {"best": best}
    if bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return -1.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size, hi + pad)
    return np.arange(lo, hi)


def _prolongate(h, Nnew):
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew)
    edges = np.linspace(0.0, N, Nnew + 1)
    m = np.interp(edges, np.arange(N + 1), c)
    return np.maximum(np.diff(m), 0.0)


def _polish(h, deadline, levels=(0.0, 1e3, 1e4)):
    best = np.asarray(h, dtype=float)
    bestR = R_of(best)
    for beta in levels:
        if time.process_time() > deadline - 0.5:
            break
        cand = _lbfgs_all_pos(best, maxiter=400, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(best)
        cand = _lbfgs_block(best, win, maxiter=300, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
    return best, bestR


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    near01 = np.mean(Lf >= 0.999 * mx)
    near5 = np.mean(Lf >= 0.95 * mx)
    zf = np.mean(h <= 0.0)
    return zf, near01, near5


def _edge_inject(h, p, m, w_frac=0.02, w_min=16, cap_factor=1.0):
    """Replace outer w cells at each end with capped power-law ramp,
    adding total mass m*sum(h) (split between the two ends)."""
    h = np.clip(h, 0, None).astype(float)
    s = h.sum()
    if s <= 0:
        return h
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    lo = int(nz[0]); hi = int(nz[-1])
    N = h.size
    w = max(w_min, int(w_frac * N))
    w = min(w, (hi - lo + 1) // 2)
    if w < 2:
        return h
    cap = cap_factor * h.max()
    target_add = m * s
    h2 = h.copy()

    # left ramp: indices lo..lo+w-1, ramp shape (i-lo+1)^(-p)
    idxL = np.arange(lo, lo + w)
    shapeL = (np.arange(1, w + 1, dtype=float)) ** (-p)
    # right ramp: mirrored, index hi-w+1..hi, ramp shape (hi-i+1)^(-p)
    idxR = np.arange(hi - w + 1, hi + 1)
    shapeR = (np.arange(w, 0, -1, dtype=float)) ** (-p)

    # Solve A so that sum(max(old, min(cap, A*shape)) - old) = target_add
    oldL = h2[idxL].copy()
    oldR = h2[idxR].copy()

    def build(A):
        newL = np.minimum(cap, A * shapeL)
        newR = np.minimum(cap, A * shapeR)
        # never lower existing height that exceeds the ramp
        newL = np.maximum(newL, oldL)
        newR = np.maximum(newR, oldR)
        return newL, newR

    def added(A):
        nL, nR = build(A)
        return (nL.sum() - oldL.sum()) + (nR.sum() - oldR.sum())

    # bisection on A
    Alo, Ahi = 0.0, cap * 10.0
    # ensure Ahi gives enough
    for _ in range(60):
        if added(Ahi) >= target_add:
            break
        Ahi *= 2.0
    for _ in range(80):
        Amid = 0.5 * (Alo + Ahi)
        if added(Amid) < target_add:
            Alo = Amid
        else:
            Ahi = Amid
    A = 0.5 * (Alo + Ahi)
    nL, nR = build(A)
    h2[idxL] = nL
    h2[idxR] = nR
    return h2


def _realized_mass_frac(h_old, h_new):
    s_old = h_old.sum()
    if s_old <= 0:
        return 0.0
    return (h_new.sum() - s_old) / s_old


def main_construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    best_h = None
    best_R = -1.0
    start_h = None
    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_h = s.copy()
            start_R = R_of(s)
            best_h = s.copy()
            best_R = start_R

    if best_h is None:
        best_h = np.ones(64)
        best_R = R_of(best_h)

    # Stage 1: polish the start at its own resolution
    if start_h is not None and time.process_time() < deadline - 2.0:
        h, r = _polish(start_h, min(deadline - 1.0, time.process_time() + 8.0))
        if r > best_R:
            best_R = r
            best_h = h
        print("start polish: %.6f" % best_R)

    # Stage 2: escalate resolutions with polishing
    targets = [8192, 16384, 32768, 65536]
    for Ntarget in targets:
        if time.process_time() > deadline - 2.0:
            break
        h = _prolongate(best_h, Ntarget)
        h, r = _polish(h, deadline)
        if r > best_R:
            best_R = r
            best_h = h
        print("escalated R at N=%d: %.6f" % (Ntarget, best_R))

    # Stage 3: final tight polish at current size
    if time.process_time() < deadline - 0.5:
        h, r = _polish(best_h, deadline, levels=(0.0, 1e4, 1e5))
        if r > best_R:
            best_R = r
            best_h = h

    zf, n01, n5 = _stats(best_h)
    print("pre-experiment R: %.6f N=%d zero=%.3f near01=%.3f near05=%.3f"
          % (best_R, best_h.size, zf, n01, n5))

    # === EXPERIMENT: edge singularity injection ===
    # Work at N=32768
    N0 = 32768
    if best_h.size != N0:
        h_base = _prolongate(best_h, N0)
    else:
        h_base = best_h.copy()
    if time.process_time() < deadline - 1.0:
        h_base, r_base = _polish(h_base,
                                 min(deadline - 0.5, time.process_time() + 6.0),
                                 levels=(0.0, 1e3))
        if r_base > best_R:
            best_R = r_base
            best_h = h_base
    else:
        r_base = R_of(h_base)

    # (A) support ends
    nz = np.flatnonzero(h_base > 0)
    if nz.size > 0:
        lo, hi = int(nz[0]), int(nz[-1])
    else:
        lo, hi = 0, h_base.size - 1
    print("support ends: lo=%d hi=%d (N=%d)" % (lo, hi, h_base.size))

    # (B) score all 6 candidates
    best_cand = None
    best_cand_R = -1.0
    best_cand_desc = None
    for p in (0.3, 0.5, 0.7):
        for m in (0.005, 0.02):
            if time.process_time() > deadline - 1.0:
                break
            cand = _edge_inject(h_base, p, m)
            rc = R_of(cand)
            rm = _realized_mass_frac(h_base, cand)
            print("  p=%.1f m=%.3f -> R=%.6f (base %.6f) mass_frac=%.4f"
                  % (p, m, rc, r_base, rm))
            if rc > best_cand_R:
                best_cand_R = rc
                best_cand = cand
                best_cand_desc = (p, m)

    # (C) polish best candidate
    if best_cand is not None:
        h = best_cand
        r = best_cand_R
        print("best raw candidate p=%.1f m=%.3f R=%.6f"
              % (best_cand_desc[0], best_cand_desc[1], r))
        # tie L-BFGS 250
        if time.process_time() < deadline - 1.0:
            ht = _lbfgs_all_pos(h, maxiter=250, deadline=deadline, beta=0.0)
            rt = R_of(ht)
            if rt > r:
                h, r = ht, rt
            print("  after tie: R=%.6f" % r)
        # beta 1e6, 1e7 (120 iters each)
        for beta in (1e6, 1e7):
            if time.process_time() > deadline - 1.0:
                break
            hb = _lbfgs_all_pos(h, maxiter=120, deadline=deadline, beta=beta)
            rb = R_of(hb)
            if rb > r:
                h, r = hb, rb
            print("  after beta=%.0e: R=%.6f" % (beta, r))
        # peak-window tie polishes
        for pad in (0.10, 0.05, 0.03):
            if time.process_time() > deadline - 0.5:
                break
            win = _peak_window(h, tol=0.999, pad_frac=pad, extra=64)
            hc = _lbfgs_block(h, win, maxiter=250, deadline=deadline, beta=0.0)
            rc = R_of(hc)
            if rc > r:
                h, r = hc, rc
            print("  after peak pad=%.2f: R=%.6f" % (pad, r))
        if r > best_R:
            best_R = r
            best_h = h
        zf, n01, n5 = _stats(best_h)
        print("after edge-inject+polish R: %.6f zero=%.3f near01=%.3f near05=%.3f"
              % (best_R, zf, n01, n5))

    # (D) mass-preserving cumsum lift to N=65536 and repeat (C)
    if time.process_time() < deadline - 1.0:
        h = _prolongate(best_h, 65536)
        # quick polish
        h, r = _polish(h, min(deadline - 0.5, time.process_time() + 6.0),
                       levels=(0.0, 1e3))
        if r > best_R:
            best_R = r
            best_h = h
        # re-inject at new resolution with best (p, m) and a couple neighbors
        if best_cand_desc is not None:
            p0, m0 = best_cand_desc
            trials = [(p0, m0), (p0, m0 * 2.0), (max(0.2, p0 - 0.2), m0)]
            for (p, m) in trials:
                if time.process_time() > deadline - 1.0:
                    break
                cand = _edge_inject(h, p, m)
                rc = R_of(cand)
                if rc > r:
                    # polish it
                    hc = _lbfgs_all_pos(cand, maxiter=200, deadline=deadline, beta=0.0)
                    rc2 = R_of(hc)
                    if rc2 > rc:
                        cand, rc = hc, rc2
                    for beta in (1e6, 1e7):
                        if time.process_time() > deadline - 0.5:
                            break
                        hb = _lbfgs_all_pos(cand, maxiter=120, deadline=deadline, beta=beta)
                        rb = R_of(hb)
                        if rb > rc:
                            cand, rc = hb, rb
                    if rc > r:
                        h, r = cand, rc
                        print("  N=65536 inject p=%.2f m=%.3f -> R=%.6f" % (p, m, r))
        # peak polishes
        for pad in (0.08, 0.04, 0.02):
            if time.process_time() > deadline - 0.5:
                break
            win = _peak_window(h, tol=0.999, pad_frac=pad, extra=64)
            hc = _lbfgs_block(h, win, maxiter=250, deadline=deadline, beta=0.0)
            rc = R_of(hc)
            if rc > r:
                h, r = hc, rc
        if r > best_R:
            best_R = r
            best_h = h
        zf, n01, n5 = _stats(best_h)
        print("after N=65536 R: %.6f zero=%.3f near01=%.3f near05=%.3f"
              % (best_R, zf, n01, n5))

    # final tight polish
    if time.process_time() < deadline - 0.5:
        h, r = _polish(best_h, deadline, levels=(0.0, 1e4, 1e5))
        if r > best_R:
            best_R = r
            best_h = h

    zf, n01, n5 = _stats(best_h)
    print("final R: %.6f N=%d zero=%.3f near01=%.3f near05=%.3f"
          % (best_R, best_h.size, zf, n01, n5))

    if start_h is not None and start_R >= best_R:
        return start_h
    if start_h is not None and start_R > 0 and best_h is not None and best_R - start_R > 1e-6:
        return {"best": best_h, "alternative": start_h}
    return best_h


def construct(budget_seconds, start):
    try:
        return main_construct(budget_seconds, start)
    except Exception:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(64)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _warp(h, a, K):
    N = h.size
    j = np.arange(N + 1, dtype=float)
    t = j.copy()
    for k in range(1, K + 1):
        t += a[k - 1] * np.sin(2.0 * np.pi * k * j / N)
    t[0] = 0.0
    t[N] = float(N)
    if np.any(np.diff(t) <= 0):
        return None
    C = np.concatenate(([0.0], np.cumsum(h)))
    Ct = np.interp(t, j, C)
    hnew = np.diff(Ct)
    hnew = np.clip(hnew, 0.0, None)
    if hnew.sum() <= 0:
        return None
    return hnew


def _warp_bounds(N, K):
    k = np.arange(1, K + 1, dtype=float)
    return 0.15 * N / (2.0 * np.pi * k)


def _optimize_warp(h, K, deadline, x0=None):
    N = h.size
    b = _warp_bounds(N, K)
    if x0 is None:
        x0 = np.zeros(K)
    else:
        x0 = np.asarray(x0, dtype=float)[:K]
        if x0.size < K:
            x0 = np.concatenate([x0, np.zeros(K - x0.size)])
        x0 = np.clip(x0, -b, b)

    best = {'a': x0.copy(), 'R': R_of(h), 'h': h}
    h0R = best['R']

    def f(a):
        if time.process_time() > deadline:
            raise TimeoutError
        hh = _warp(h, a, K)
        if hh is None:
            return 1e6
        r = R_of(hh)
        if r > best['R']:
            best['R'] = r
            best['a'] = a.copy()
            best['h'] = hh
        return -r

    try:
        minimize(f, x0, method='Nelder-Mead',
                 options={'maxiter': 4000, 'xatol': 1e-6,
                          'fatol': 1e-12, 'adaptive': True})
    except (TimeoutError, Exception):
        pass
    if best['R'] > h0R:
        return best['h'], best['a'], best['R']
    return h, x0, h0R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase D: local polish of the START (tie-aware peak window) ----
    # The start is already near-optimal for its own basin; squeeze it first.
    phaseD_end = t0 + budget_seconds * 0.35
    if time.process_time() < phaseD_end - 2.0:
        ht = _peak_ladder(best, phaseD_end - 0.5,
                          pads=(0.06, 0.04, 0.025, 0.015), iters=300)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("PHASE D peak ACCEPT R=%.9f" % bestR)
        else:
            print("PHASE D peak no gain R=%.9f" % rt)

    # ---- Phase A: warp to escape the local optimum ----
    warp_a = None
    phaseA_end = t0 + budget_seconds * 0.62
    if time.process_time() < phaseA_end - 2.0:
        hw, a16, rw = _optimize_warp(best, 16, phaseA_end - 0.5)
        dR = rw - bestR
        print("PHASE A warp K=16 dR=%+.3e R=%.9f" % (dR, rw))
        if rw > bestR + 1e-9:
            best, bestR = hw.copy(), rw
            warp_a = a16.copy()
            print("PHASE A ACCEPT R=%.9f" % bestR)

    # ---- Phase B: re-polish the warped array ----
    phaseB_end = t0 + budget_seconds * 0.80
    if time.process_time() < phaseB_end - 2.0:
        ht = _peak_ladder(best, phaseB_end - 0.5,
                          pads=(0.08, 0.05, 0.03, 0.02), iters=300)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("PHASE B peak ACCEPT R=%.9f" % bestR)
        else:
            print("PHASE B peak no gain R=%.9f" % rt)

    # ---- Phase C: second warp round K=32 ----
    phaseC_end = t0 + budget_seconds * 0.90
    if time.process_time() < phaseC_end - 2.0:
        x0 = None
        if warp_a is not None:
            x0 = np.zeros(32)
            x0[:min(16, warp_a.size)] = warp_a[:16]
        hw, a32, rw = _optimize_warp(best, 32, phaseC_end - 0.5, x0=x0)
        dR = rw - bestR
        print("PHASE C warp K=32 dR=%+.3e R=%.9f" % (dR, rw))
        if rw > bestR + 1e-9:
            best, bestR = hw.copy(), rw
            print("PHASE C ACCEPT R=%.9f" % bestR)

    # ---- Final: tight peak polish ----
    fd = t0 + budget_seconds * 0.915
    if time.process_time() < fd - 1.0:
        ht = _peak_ladder(best, fd - 0.3,
                          pads=(0.03, 0.02, 0.012), iters=250)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("FINAL peak ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL peak no gain R=%.9f" % rt)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _softplus(z):
    return np.logaddexp(0.0, z)


def _clipped_l1_fg(h, cap, tau):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    z = (cap - Lf) / tau
    z = np.clip(z, -60.0, 60.0)
    sp = _softplus(z)
    C = np.sum(cap - tau * sp)
    if C <= 1e-300:
        return 1e18, np.zeros(h.size)
    w = 1.0 / (1.0 + np.exp(-z))  # sigmoid
    gLf = -w / C
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(C) + 2.0 * np.log(s)
    return val, grad


def _lbfgs_clipped(h0, cap, tau, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _clipped_l1_fg(hh, cap, tau)
        return val, g * hh

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * x0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None or not np.all(np.isfinite(res.x)):
        return h0
    return _rescale(np.exp(res.x))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            keep = _rescale(base)
            startR = R_of(keep)
        else:
            keep, startR = None, 0.0
    else:
        keep, startR = None, 0.0

    if keep is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        keep = _rescale(h)
        startR = R_of(keep)

    best = keep.copy()
    bestR = startR
    print("base R=%.9f (N=%d) frac5=%.4f"
          % (bestR, best.size, _frac_near_max(best, 0.95)))

    taus_rel = [1e-3, 3e-4, 1e-4]
    for tau_rel in taus_rel:
        if time.process_time() >= deadline - 1.0:
            break
        cap = float(_knots(keep).max())
        tau = tau_rel * cap
        for rnd in range(4):
            if time.process_time() >= deadline - 1.0:
                break
            h_new = _lbfgs_clipped(keep, cap, tau, 300,
                                   min(deadline - 0.5,
                                       time.process_time() + 8.0))
            # tie-aware peak polish
            for pad in (0.06, 0.03, 0.015):
                if time.process_time() >= deadline - 0.8:
                    break
                win = _peak_window(h_new, pad_frac=pad, extra=96)
                ht = _lbfgs_block(h_new, win, 200,
                                  min(deadline - 0.5,
                                      time.process_time() + 2.5), tie=True)
                r = R_of(ht)
                if r > R_of(h_new) + 1e-15:
                    h_new = ht
            r_new = R_of(h_new)
            accepted = False
            if r_new > bestR + 1e-12:
                best, bestR = h_new.copy(), r_new
                keep = h_new.copy()
                accepted = True
            print("tau=%.1e rnd=%d cap=%.4f R=%.9f frac5=%.4f acc=%s"
                  % (tau_rel, rnd, cap, r_new,
                     _frac_near_max(h_new, 0.95), accepted))
            if not accepted:
                break

    # final tie polish at pad 0.015
    if time.process_time() < deadline - 0.5:
        win = _peak_window(best, pad_frac=0.015, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline, time.process_time() + 3.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    print("final R=%.9f (start %.9f, N=%d, frac5=%.4f)"
          % (bestR, startR, best.size, _frac_near_max(best, 0.95)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


# ---------- clamped cubic B-spline basis, banded ----------
def _bspline_basis_banded(n_ctrl, K, n_eval):
    """Clamped cubic B-spline basis over [0, n_ctrl] with K control points.
    Returns (rows, cols, vals) of the sparse (n_eval, K) matrix.
    Cox-de Boor evaluated at uniform sample points x_i = i (i=0..n_ctrl-1)
    mapped to parameter t in [0,1]."""
    # knot vector: clamped cubic, K control points -> K+4 knots
    # interior knots uniform on (0,1): K-4 of them
    n_int = K - 4
    if n_int < 0:
        n_int = 0
    inner = np.linspace(0.0, 1.0, n_int + 2)[1:-1] if n_int > 0 else np.array([])
    knots = np.concatenate(([0.0, 0.0, 0.0, 0.0], inner, [1.0, 1.0, 1.0, 1.0]))
    # evaluation points
    x = np.linspace(0.0, 1.0, n_eval)
    # degree 3 basis via Cox-de Boor, vectorized over x
    # N_{i,0}
    m = knots.size
    # We'll compute degree 0..3 iteratively, storing N_{i,d} for i=0..m-d-2
    N = np.zeros((m - 1, n_eval))
    for i in range(m - 1):
        N[i] = ((x >= knots[i]) & (x < knots[i + 1])).astype(float)
    # handle right endpoint: last nonzero basis gets x==1
    N[-1] = ((x >= knots[m - 2]) & (x <= knots[m - 1])).astype(float)
    for d in range(1, 4):
        Nd = np.zeros((m - 1 - d, n_eval))
        for i in range(m - 1 - d):
            denom1 = knots[i + d] - knots[i]
            denom2 = knots[i + d + 1] - knots[i + 1]
            a = (x - knots[i]) / denom1 * N[i] if denom1 > 0 else 0.0
            b = (knots[i + d + 1] - x) / denom2 * N[i + 1] if denom2 > 0 else 0.0
            Nd[i] = a + b
        N = Nd
    # N now shape (K, n_eval) since m-1-3 = K
    B = N.T  # (n_eval, K)
    return B


def _bspline_apply(B, theta):
    return B @ theta


def _bspline_apply_T(B, g):
    return B.T @ g


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Step 1: block-mean over 32 ----
    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))
    if p != 32:
        # fall back: try block-mean of 32 anyway
        if best.size % 32 == 0:
            c = best.reshape(-1, 32).mean(axis=1)
            p = 32
        else:
            print("no 32-repeat; aborting to start")
            return {"best": best, "alternative": best}

    rrep = R_of(np.repeat(c, p))
    print("repeat check |R(c)-R(start)|=%.2e" % abs(rrep - startR))
    if abs(rrep - startR) > 1e-12:
        print("repeat fidelity failed; aborting to start")
        return {"best": best, "alternative": best}

    n_c = c.size
    print("n_c=%d" % n_c)

    # ---- Steps 2-3: B-spline ladder ----
    K_list = [65, 129, 257, 513, 1025, 2049]
    results = []
    best_overall = best.copy()
    best_overallR = bestR

    for K in K_list:
        if time.process_time() >= t0 + 0.85 * budget_seconds - 1.0:
            print("K=%d skipped (time)" % K)
            break
        if K > n_c:
            print("K=%d > n_c, skip" % K)
            continue
        try:
            B = _bspline_basis_banded(n_c, K, n_c)  # (n_c, K)
        except Exception as e:
            print("K=%d basis fail: %s" % (K, e))
            continue
        # theta0 = lstsq
        try:
            theta0, *_ = np.linalg.lstsq(B, c, rcond=None)
        except np.linalg.LinAlgError:
            print("K=%d lstsq fail" % K)
            continue
        c0 = np.clip(B @ theta0, 0.0, None)
        h0 = np.repeat(c0, p)
        R_comp = R_of(h0)
        print("K=%d R_comp=%.9f" % (K, R_comp))

        # optimise theta
        # gradient: dF/dtheta = B^T (block-summed dF/dh over groups of p)
        def f_theta(theta, B=B, p=p, n_c=n_c):
            cc = np.clip(B @ theta, 0.0, None)
            hh = np.repeat(cc, p)
            val, g = _fun_grad_tie(hh)
            # block-sum gradient over groups of p
            gb = g.reshape(n_c, p).sum(axis=1)
            gt = B.T @ gb
            return val, gt

        k_end = min(t0 + 0.85 * budget_seconds - 0.5,
                    time.process_time() + 8.0)
        cb = _make_cb(k_end - 0.2)
        theta_opt = theta0.copy()
        try:
            res = minimize(f_theta, theta0, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * K, callback=cb,
                           options={'maxiter': 200, 'maxfun': 400,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            if res is not None and np.all(np.isfinite(res.x)):
                theta_opt = res.x
        except (TimeoutError, Exception):
            pass
        c_opt = np.clip(B @ theta_opt, 0.0, None)
        h_opt = _rescale(np.repeat(c_opt, p))
        R_opt = R_of(h_opt)
        print("K=%d R_opt=%.9f" % (K, R_opt))

        # tie peak polish
        cand = h_opt
        candR = R_opt
        for pad in (0.03, 0.015):
            if time.process_time() >= t0 + 0.88 * budget_seconds - 0.5:
                break
            win = _peak_window(cand, pad_frac=pad, extra=96)
            ht = _lbfgs_block(cand, win, 200,
                              min(t0 + 0.88 * budget_seconds - 0.3,
                                  time.process_time() + 2.0), tie=True)
            r = R_of(ht)
            if r > candR + 1e-15:
                cand, candR = ht, r
        accepted = candR > R_comp + 1e-12
        print("K=%d accepted=%s R_final=%.9f" % (K, accepted, candR))
        results.append((K, R_comp, R_opt, candR))

        if candR > best_overallR + 1e-15:
            best_overall = cand.copy()
            best_overallR = candR
            print("K=%d NEW BEST R=%.9f" % (K, best_overallR))

    print("summary:")
    for (K, rc, ro, rf) in results:
        print("  K=%d R_comp=%.9f R_opt=%.9f R_final=%.9f" % (K, rc, ro, rf))
    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (best_overallR, startR, best_overall.size, _tie_count(best_overall)))

    result = {"best": best_overall}
    if best_overallR <= startR + 1e-14:
        result["alternative"] = best_overall
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _ramp_free_cells(h, margin=2):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    above = np.flatnonzero(Lf > 0.999 * mx)
    if above.size == 0:
        return np.arange(n)
    nlo = int(above[0]); nhi = int(above[-1])
    lo_hi = min(n, nlo + margin + 1)
    hi_lo = max(0, nhi - n - margin)
    return np.unique(np.concatenate([np.arange(0, lo_hi), np.arange(hi_lo, n)]))


def _polish(h, deadline, scale=1.0):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0 * scale), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0 * scale), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0 * scale), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _ramp_phase(best, bestR, deadline, scale=1.0):
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    free = _ramp_free_cells(best, margin=2)
    print("  ramp phase: freeing %d / %d cells" % (free.size, best.size))
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 6.0 * scale)
        hs = _lbfgs_block(best, free, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-13:
            best, bestR = hs, rs
            print("    ramp exact R=%.9f" % bestR)
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 4.0 * scale)
        hs = _lbfgs_block(best, free, 150, cap, beta=1e4)
        rs = R_of(hs)
        if rs > bestR + 1e-13:
            best, bestR = hs, rs
            print("    ramp beta1e4 R=%.9f" % bestR)
    if time.process_time() < deadline - 1.0:
        free2 = _peak_window(best, frac=0.08)
        cap = min(deadline - 0.5, time.process_time() + 4.0 * scale)
        hs = _lbfgs_block(best, free2, 150, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-13:
            best, bestR = hs, rs
            print("    ramp peak R=%.9f" % bestR)
    return best, bestR


def _try_refine(best, bestR, deadline, rng, label=""):
    """A focused refinement attempt: exact R then a couple beta passes and peak windows,
    all bounded so it can be aborted cleanly. Returns (h, R) whichever is better."""
    trial = best.copy()
    trialR = bestR
    end = min(deadline - 0.5, time.process_time() + 8.0)
    if time.process_time() >= end - 0.5:
        return best, bestR
    hs = _lbfgs_log(trial, 250, end, beta=0.0)
    rs = R_of(hs)
    if rs > trialR + 1e-13:
        trial, trialR = hs, rs
    for beta in (3e4, 3e5):
        if time.process_time() >= end - 0.5:
            break
        hs = _lbfgs_log(trial, 150, min(end, time.process_time() + 3.0), beta=beta)
        rs = R_of(hs)
        if rs > trialR + 1e-13:
            trial, trialR = hs, rs
    for frac in (0.03, 0.08, 0.15):
        if time.process_time() >= end - 0.5:
            break
        free = _peak_window(trial, frac=frac)
        hs = _lbfgs_block(trial, free, 150, min(end, time.process_time() + 3.0), beta=0.0)
        rs = R_of(hs)
        if rs > trialR + 1e-13:
            trial, trialR = hs, rs
    if trialR > bestR + 1e-13:
        print("  %s refine R=%.9f (was %.9f)" % (label, trialR, bestR))
        return trial, trialR
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    rng = np.random.default_rng(20240517)

    # ---- 2x prolongation round ----
    if time.process_time() < deadline - 2.0:
        h2 = _rescale(np.repeat(best, 2))
        r2 = R_of(h2)
        print("2x prolongate: N=%d R=%.9f (was %.9f)" % (h2.size, r2, bestR))
        hp, rp = _polish(h2, deadline, scale=0.5)
        print("2x polish R=%.9f" % rp)
        if rp > bestR + 1e-13:
            best, bestR = hp, rp
            print("  2x ACCEPT R=%.9f" % bestR)
        best, bestR = _ramp_phase(best, bestR, deadline, scale=0.5)
        print("after 2x ramp phase R=%.9f" % bestR)

    # ---- 4x prolongation round if time remains ----
    if time.process_time() < deadline - 15.0:
        h4 = _rescale(np.repeat(best, 2))
        r4 = R_of(h4)
        print("4x prolongate: N=%d R=%.9f" % (h4.size, r4))
        hp, rp = _polish(h4, deadline, scale=0.35)
        print("4x polish R=%.9f" % rp)
        if rp > bestR + 1e-13:
            best, bestR = hp, rp
            print("  4x ACCEPT R=%.9f" % bestR)
        best, bestR = _ramp_phase(best, bestR, deadline, scale=0.35)
        print("after 4x ramp phase R=%.9f" % bestR)

    # ---- Final loop: alternate full polish with focused beta refinements ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(best, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-13:
            best, bestR = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestR))
            continue
        if time.process_time() < loop_end - 2.0:
            frac = 0.04 + 0.12 * rng.random()
            free = _peak_window(best, frac=frac)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(best, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestR))
                continue
        if time.process_time() < loop_end - 9.0:
            best, bestR = _try_refine(best, bestR, loop_end, rng, label="loop%d" % it)

    print("final R=%.9f (best of experiment)" % bestR)
    mx, m, near = _stats(best)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return 0.0, 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    den = s * s * (mx if mx > 0 else 1.0)
    if den <= 0:
        return 0.0, mx
    return num / den, mx


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta))
    cb = _make_cb(deadline - 0.2)

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _report(tag, h):
    R, mx = R_of(h)
    L = _conv(np.maximum(h, 0.0))
    if L.max() > 0:
        near = np.mean(L >= 0.99 * L.max())
        near5 = np.mean(L >= 0.95 * L.max())
        am = float(np.argmax(L)) / max(1, 2 * len(h) - 2)
    else:
        near = 0.0
        near5 = 0.0
        am = 0.0
    print("%s: R=%.6f N=%d zero_frac=%.3f max/mean=%.2f near_max=%.3f near5=%.3f argmax=%.3f" % (
        tag, R, len(h), np.mean(np.asarray(h) <= 0),
        np.max(h) / (np.mean(h) + 1e-12), near, near5, am))
    return R


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    M = len(h)
    if M == N:
        return h.copy()
    edges = np.linspace(0, M, N + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))

    def cum_at(x):
        i = np.floor(x).astype(int)
        i = np.clip(i, 0, M - 1)
        frac = x - i
        return cum[i] + frac * h[i]

    mass = cum_at(edges[1:]) - cum_at(edges[:-1])
    cellw = M / N
    out = mass / cellw
    return np.maximum(out, 0.0)


def _make_target(h, half_width, ramp):
    """Build flat-top target T over the conv knot grid (length 2N-1)."""
    N = len(h)
    K = 2 * N - 1
    x = np.linspace(0.0, 2.0, K)
    T = np.zeros(K)
    inner = half_width
    outer = half_width + ramp
    for j in range(K):
        d = abs(x[j] - 1.0)
        if d <= inner:
            T[j] = 1.0
        elif d < outer:
            T[j] = 0.5 * (1.0 + np.cos(np.pi * (d - inner) / ramp))
        else:
            T[j] = 0.0
    s = h.sum()
    dx = 2.0 / (K - 1) if K > 1 else 1.0
    mass = T.sum() * dx
    if mass <= 0:
        return T
    M = (s * s) / mass
    return T * M


def _project_to_target(h, half_width, ramp, deadline, iters=400):
    """Minimise sum (L - T)^2 / M^2 in log-space with L-BFGS-B."""
    if time.process_time() >= deadline - 0.5:
        return h
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    if h.sum() <= 0:
        return h
    T = _make_target(h, half_width, ramp)
    M = T.max()
    if M <= 0:
        return h
    invM2 = 1.0 / (M * M)
    n = h.size

    def fg(theta):
        hh = np.exp(np.clip(theta, -25.0, 25.0))
        Lf = _knots(hh)
        diff = Lf - T
        val = np.sum(diff * diff) * invM2
        gLf = 2.0 * diff * invM2
        g = _backprop(gLf, hh) * hh
        return val, g

    theta0 = np.log(np.maximum(h, 1e-12))
    cb = _make_cb(deadline - 0.2)

    def f(x):
        return fg(x)

    try:
        res = minimize(f, theta0, jac=True, method='L-BFGS-B',
                       bounds=[(-25.0, 25.0)] * n,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    hh = np.exp(np.clip(res.x, -25.0, 25.0))
    return _rescale(hh)


def _polish(h, deadline, budget):
    """Beta ladder + tie-aware hard-max pass; accept best exact R."""
    best = np.maximum(np.asarray(h, dtype=float), 0.0)
    bestR, _ = R_of(best)
    for beta in (1e3, 1e4, 1e5, 1e6):
        if time.process_time() > deadline - 1.0:
            break
        dl = min(deadline - 0.5, time.process_time() + 0.08 * budget)
        h2 = _lbfgs(best, 250, dl, beta=beta)
        R2, _ = R_of(h2)
        if R2 > bestR:
            best = h2
            bestR = R2
    if time.process_time() < deadline - 1.0:
        dl = min(deadline - 0.5, time.process_time() + 0.08 * budget)
        h2 = _lbfgs(best, 250, dl, beta=1e5)
        R2, _ = R_of(h2)
        if R2 > bestR:
            best = h2
            bestR = R2
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()

    def elapsed():
        return time.process_time() - t0

    deadline = t0 + 0.90 * budget_seconds

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float), 0.0)
        if s.sum() > 0:
            R, _ = R_of(s)
            best_h = s.copy()
            best_R = R
            print("Start: R=%.6f N=%d" % (R, len(s)))

    if best_h is None:
        N0 = 4096
        x = np.linspace(0, 1, N0)
        best_h = np.sin(np.pi * x) ** 0.5
        best_R, _ = R_of(best_h)

    print("Working N=%d start R=%.6f" % (len(best_h), best_R))

    # (A) Basin entry: project onto flat-top target
    if elapsed() < deadline - 2.0:
        dl = min(deadline - 1.0, elapsed() + 0.30 * budget_seconds)
        h_proj = _project_to_target(best_h, 0.40, 0.08, dl, iters=400)
        Rp, _ = R_of(h_proj)
        _report("Stage A projection (hw=0.40)", h_proj)
        # (B) Polish the projection
        dl2 = min(deadline - 0.5, elapsed() + 0.25 * budget_seconds)
        h_pol, Rpol = _polish(h_proj, dl2, budget_seconds)
        _report("Stage B polish", h_pol)
        if Rpol > best_R:
            best_h = h_pol.copy()
            best_R = Rpol
        elif Rp > best_R:
            best_h = h_proj.copy()
            best_R = Rp

    # (C) Second pass with wider plateau, warm-started from current best
    if elapsed() < deadline - 2.0:
        dl = min(deadline - 1.0, elapsed() + 0.20 * budget_seconds)
        h_proj2 = _project_to_target(best_h, 0.45, 0.05, dl, iters=400)
        Rp2, _ = R_of(h_proj2)
        _report("Stage C projection (hw=0.45)", h_proj2)
        dl2 = min(deadline - 0.5, elapsed() + 0.15 * budget_seconds)
        h_pol2, Rpol2 = _polish(h_proj2, dl2, budget_seconds)
        _report("Stage C polish", h_pol2)
        if Rpol2 > best_R:
            best_h = h_pol2.copy()
            best_R = Rpol2
        elif Rp2 > best_R:
            best_h = h_proj2.copy()
            best_R = Rp2

    best_h = np.maximum(np.asarray(best_h, dtype=float), 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(len(best_h) if len(best_h) > 0 else 4096)
    if len(best_h) > 1000000:
        best_h = _resample(best_h, 1000000)
    Rf = _report("FINAL", best_h)

    result = {"best": best_h}
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float), 0.0)
        if s.sum() > 0:
            Rs, _ = R_of(s)
            if Rs > Rf:
                result["best"] = s
                result["alternative"] = best_h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-9)))


def _resample(base, newN):
    n = base.size
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    h = np.interp(x_new, x_old, base)
    return _rescale(h)


def _spectral_kick(h, rng, amp, nmode=8):
    n = h.size
    H = np.fft.rfft(h)
    K = H.size
    k = np.arange(K, dtype=float)
    phi = np.zeros(K)
    for j in range(1, nmode + 1):
        a = rng.uniform(-amp, amp)
        b = rng.uniform(-amp, amp)
        phi += a * np.cos(np.pi * j * k / K) + b * np.sin(np.pi * j * k / K)
    phi[0] = 0.0
    H2 = H * np.exp(1j * phi)
    h2 = np.fft.irfft(H2, n=n)
    h2 = np.clip(h2, 0.0, None)
    return _rescale(h2)


def _gauss_bump_kick(h, rng, amp):
    """Multiplicative smooth bump perturbation - changes support structure."""
    n = h.size
    h2 = h.copy()
    for _ in range(rng.integers(1, 4)):
        c = rng.uniform(0.05, 0.95) * n
        w = rng.uniform(0.01, 0.15) * n
        a = rng.uniform(-amp, amp)
        x = np.arange(n, dtype=float)
        g = np.exp(-0.5 * ((x - c) / w) ** 2)
        h2 = h2 * (1.0 + a * g)
    return _rescale(np.clip(h2, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    rng = np.random.default_rng(1234567)

    # ---- Phase 1: aggressive exploration with spectral & bump kicks ----
    kick_end = t0 + budget_seconds * 0.55
    best_seed = best.copy()
    best_seedR = bestR
    n_accepted = 0
    trial = 0
    while time.process_time() < kick_end - 1.5:
        trial += 1
        kind = trial % 3
        amp = rng.choice([0.15, 0.3, 0.5, 0.8, 1.2])
        if kind == 0:
            h = _spectral_kick(best_seed, rng, amp)
        elif kind == 1:
            h = _gauss_bump_kick(best_seed, rng, amp)
        else:
            h = _spectral_kick(best_seed, rng, amp, nmode=16)
        r_pre = R_of(h)

        slice_end = min(kick_end, time.process_time() + 4.0)
        h = _lbfgs_all_pos(h, 300, slice_end - 0.4, tie=True)
        if time.process_time() < slice_end - 0.6:
            h = _peak_ladder(h, slice_end - 0.3,
                             pads=(0.12, 0.06), iters=150, tie=True)
        if time.process_time() < slice_end - 0.3:
            h = _lbfgs_all_pos(h, 200, slice_end - 0.1, beta=1e7)
        r_post = R_of(h)
        dR = r_post - bestR
        accepted = r_post > bestR + 1e-15
        if accepted:
            best = h.copy()
            bestR = r_post
            n_accepted += 1
        if r_post > best_seedR + 1e-15:
            best_seed = h.copy()
            best_seedR = r_post
        print("kick %d kind=%d amp=%.2f pre=%.9f post=%.9f dR=%+.3e %s R=%.9f"
              % (trial, kind, amp, r_pre, r_post, dR,
                 "ACCEPT" if accepted else "no gain", bestR))

    print("kicks done: trials=%d accepted=%d bestR=%.9f (base %.9f)"
          % (trial, n_accepted, bestR, startR))

    # ---- Phase 2: full polish on best, alternating tie and beta ----
    loop_end = t0 + min(budget_seconds * 0.82, 50.0)
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 8.0)
        h_t = _lbfgs_all_pos(best, 800, slice_end - 3.0, tie=True)
        r_t = R_of(h_t)
        dR = r_t - bestR
        accepted = r_t > bestR + 1e-15
        if accepted:
            best, bestR = h_t.copy(), r_t
        print("tie pass %d N=%d dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f nearmax5=%.4f"
              % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                 bestR, _tie_count(h_t), _zero_frac(h_t),
                 _nearmax_frac(h_t)))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=300, tie=True)
            r_t = R_of(h_t)
            dR = r_t - bestR
            accepted = r_t > bestR + 1e-15
            if accepted:
                best, bestR = h_t.copy(), r_t
            print("tie peak %d N=%d dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f nearmax5=%.4f"
                  % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                     bestR, _tie_count(h_t), _zero_frac(h_t),
                     _nearmax_frac(h_t)))
        if time.process_time() < slice_end - 1.5:
            h_t = _lbfgs_all_pos(best, 400, slice_end - 0.3, beta=1e6)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t

    # ---- Final passes ----
    fd = t0 + budget_seconds * 0.95
    if time.process_time() < fd - 4.0:
        h_t = _lbfgs_all_pos(best, 800, fd - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 400, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL argmax no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _detect_staircase(h, plist=(64, 32, 16, 8, 4, 2, 1)):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in plist:
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-10:
            return c, p
    return None, 1


# ------------------------------------------------------------------
# New idea: two-scale optimisation.  Represent the coarse profile c
# (m values) explicitly and optimise it with L-BFGS on the *coarse*
# objective R_coarse(c) (cheap, exact).  Then reconstruct the fine
# profile by repeating each coarse value p times and polish locally.
# The coarse objective is smooth, low-dimensional and cheap to
# evaluate, so we can afford many restarts / random perturb-and-
# optimise steps, which is what actually moves R at this precision.
# ------------------------------------------------------------------

def _coarse_knots(c):
    return np.concatenate(([0.0], np.convolve(c, c), [0.0]))


def _R_coarse(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = _coarse_knots(c)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _coarse_grad_log(c):
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    Lf = _coarse_knots(c)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    if num <= 0:
        return 1e18, np.zeros(c.size)
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(c.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    gL = gLf[1:-1]
    if c.size > 1500:
        grad = 2.0 * fftconvolve(gL, c[::-1], mode='valid')[:c.size]
    else:
        grad = 2.0 * np.correlate(gL, c, mode='valid')[:c.size]
    grad = grad + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _coarse_lbfgs(c0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return c0
    c0 = np.clip(c0, 1e-12, None)
    x0 = np.log(c0)

    def f(x):
        c = np.exp(x)
        val, g = _coarse_grad_log(c)
        return val, g * c

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-np.inf, np.log(1e-6))] * c0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-18, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.exp(np.clip(res.x, -30.0, np.log(1e-6)))


def _propose(c, rng):
    m = c.size
    u = np.arange(m, dtype=float) / m
    kind = rng.integers(0, 4)
    s = np.exp(rng.uniform(np.log(0.01), np.log(0.4)))
    cp = c.copy()
    if kind == 0:
        E = np.zeros(m)
        for k in range(1, 5):
            a = rng.normal()
            phi = rng.uniform(0, 2 * np.pi)
            E += a * np.cos(2 * np.pi * k * u + phi)
        mE = np.max(np.abs(E))
        if mE > 0:
            E /= mE
        cp = c * (1.0 + s * E)
    elif kind == 1:
        nb = rng.integers(8, 65)
        edges = np.sort(rng.choice(m + 1, size=nb + 1, replace=False))
        for i in range(nb):
            lo, hi = edges[i], edges[i + 1]
            if hi <= lo:
                continue
            f = np.exp(rng.uniform(np.log(1 / 1.5), np.log(1.5)))
            cp[lo:hi] *= f
    elif kind == 2:
        frac = rng.uniform(0.03, 0.05)
        k = max(1, int(frac * m))
        idx = rng.choice(m, size=k, replace=False)
        f = np.exp(rng.uniform(np.log(0.5), np.log(2.0), size=k))
        cp[idx] *= f
    else:
        frac = rng.uniform(0.01, 0.03)
        k = max(1, int(frac * m))
        idx = rng.choice(m, size=k, replace=False)
        cp[idx] = 0.0
    cp = np.clip(cp, 0.0, None)
    if cp.sum() <= 0:
        cp = c.copy()
    return cp


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    rng = np.random.default_rng(987654321)

    # Detect staircase
    c_best, p_best = _detect_staircase(best)
    if c_best is None:
        p_best = 1
        c_best = best.copy()

    if p_best >= 2:
        r_coarse = _R_coarse(c_best)
        print("staircase p=%d m=%d R_coarse=%.12f R_full=%.12f"
              % (p_best, c_best.size, r_coarse, bestR))
        c_work = c_best.copy()
        r_work = r_coarse
        c_work = _coarse_lbfgs(c_work, 400, deadline - 5.0)
        r_work = _R_coarse(c_work)
        print("coarse whole-vector LBFGS -> %.12f" % r_work)
        n_imp = 0
        n_res = 0
        while time.process_time() < deadline - 4.0:
            n_res += 1
            cp = _propose(c_work, rng)
            iters = int(rng.integers(60, 151))
            c_new = _coarse_lbfgs(cp, iters, deadline - 3.0)
            r_new = _R_coarse(c_new)
            if r_new > r_work + 1e-16:
                c_work = c_new
                r_work = r_new
                n_imp += 1
                print("  coarse restart %d IMPROVED %.12f (+%.2e)"
                      % (n_res, r_work, r_work - r_coarse))
        print("coarse done restarts=%d improvements=%d R_coarse=%.12f"
              % (n_res, n_imp, r_work))

        h_rec = np.repeat(c_work, p_best)
        h_rec = _rescale(h_rec)
        r_rec = R_of(h_rec)
        print("reconstruct R_full=%.12f (coarse %.12f)" % (r_rec, r_work))
        polish_end = t0 + budget_seconds * 0.97
        for pad in (0.12, 0.08, 0.05, 0.03):
            if time.process_time() >= polish_end - 1.0:
                break
            win = _peak_window(h_rec, pad_frac=pad, extra=128)
            ht = _lbfgs_block(h_rec, win, 250,
                              min(polish_end - 0.5,
                                  time.process_time() + 4.0), beta=1e7)
            rt = R_of(ht)
            if rt > r_rec + 1e-15:
                h_rec = ht
                r_rec = rt
        ht = _lbfgs_all_pos(h_rec, 400, polish_end - 0.5, tie=True)
        rt = R_of(ht)
        if rt > r_rec + 1e-15:
            h_rec = ht
            r_rec = rt
        print("polished R_full=%.12f" % r_rec)
        if r_rec > bestR + 1e-15:
            best = h_rec.copy()
            bestR = r_rec
            print("COARSE ACCEPT R=%.12f" % bestR)
        else:
            print("coarse no gain (%.12f vs %.12f)" % (r_rec, bestR))
    else:
        print("no staircase (p=%d), running peak ladder only" % p_best)

    peak_end = t0 + budget_seconds * 0.99
    if time.process_time() < peak_end - 2.0:
        ht = _peak_ladder(best, peak_end - 1.0,
                          pads=(0.06, 0.04, 0.02), iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.12f" % bestR)

    f01, f1, f5 = _nearmax_fracs(best)
    print("final R=%.9f (start %.9f, N=%d, ties=%d, near 0.1/1/5=%.3f/%.3f/%.3f)"
          % (bestR, startR, best.size, _tie_count(best), f01, f1, f5))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    h0 = best.copy()
    eps = 1e-6 * max(h0.max(), 1e-30)

    def h_of(z):
        return np.sqrt(z * z + eps * eps) - eps

    def dh_of(z):
        return z / np.sqrt(z * z + eps * eps)

    def fg(z):
        hh = h_of(z)
        val, g = _fun_grad_tie(hh)
        return val, g * dh_of(z)

    # sanity: z=h0 gives back h0
    z0 = h0.copy()
    r_check = R_of(h_of(z0))
    print("signed-rep check |R(z0)-R(h0)|=%.2e" % abs(r_check - startR))

    # candidate generation
    med = np.median(h0)
    low_idx = np.flatnonzero(h0 < med)
    rng = np.random.default_rng(121)
    cands = []
    for _ in range(10):
        z = h0.copy()
        if low_idx.size > 0:
            flip = rng.random(low_idx.size) < 0.5
            z[low_idx[flip]] *= -1.0
        cands.append(z)
    # alternate-cell candidate
    z_alt = h0.copy()
    z_alt[1::2] *= -1.0
    cands.append(z_alt)

    def run_signed(z_init, slice_sec):
        z = z_init.copy()
        sl_deadline = min(deadline - 0.5, time.process_time() + slice_sec)
        cb = _make_cb(sl_deadline - 0.2)
        try:
            res = minimize(fg, z, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': 300, 'maxfun': 600,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return z_init, R_of(h_of(z_init))
        if res is None or not np.all(np.isfinite(res.x)):
            return z_init, R_of(h_of(z_init))
        z2 = res.x
        return z2, R_of(h_of(z2))

    n_neg_best = 0.0
    for ci, z_init in enumerate(cands):
        if time.process_time() >= deadline - 2.0:
            break
        z_opt, r_opt = run_signed(z_init, 4.0)
        h_opt = h_of(z_opt)
        frac_neg = float(np.mean(z_opt < 0))
        # peak-window tie polish on the resulting heights
        for pad in (0.03, 0.015):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(h_opt, pad_frac=pad, extra=96)
            hp = _lbfgs_block(h_opt, win, 80,
                              min(deadline - 0.5,
                                  time.process_time() + 1.5), tie=True)
            rp = R_of(hp)
            if rp > r_opt:
                h_opt, r_opt = hp, rp
        if r_opt > bestR + 1e-15:
            best, bestR = h_opt.copy(), r_opt
            n_neg_best = frac_neg
            print("cand %d ACCEPT R=%.9f neg=%.3f" % (ci, bestR, frac_neg))
        else:
            print("cand %d R=%.9f neg=%.3f (best %.9f)"
                  % (ci, r_opt, frac_neg, bestR))

    # final peak polish on best
    c_end = t0 + budget_seconds * 0.99
    for pad in (0.06, 0.03, 0.015):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(c_end - 0.5, time.process_time() + 3.0),
                          tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d, neg_best=%.3f)"
          % (bestR, startR, best.size, _tie_count(best), n_neg_best))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

