    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _coarsen(h, p):
    """Average h into blocks of size p (requires h.size % p == 0)."""
    n = h.size
    if n % p != 0:
        return None
    m = n // p
    c = h.reshape(m, p).mean(axis=1)
    return c


def _refine(hc, p):
    return np.repeat(hc, p)


def _multiscale_round(h, deadline, factors=(4, 2), iters=200):
    """Coarsen h by factor, optimize coarse, refine back, then polish.
    This is a different search direction: it averages out fine detail
    (which is near-degenerate here since the peak is flat) and re-optimizes
    a lower-dimensional problem, then reconstructs at full resolution.
    """
    best = h
    bestR = R_of(h)
    for p in factors:
        if time.process_time() >= deadline - 1.0:
            break
        hc = _coarsen(best, p)
        if hc is None:
            continue
        # optimize coarse problem with tie smoothing
        hc2 = _lbfgs_block(hc, np.arange(hc.size), iters,
                           deadline - 0.5, beta=1e7)
        if time.process_time() < deadline - 0.5:
            hc2 = _lbfgs_block(hc2, np.arange(hc2.size), iters,
                                deadline - 0.4, tie=True)
        # refine and polish full-res
        hr = _refine(hc2, p)
        if time.process_time() < deadline - 0.4:
            win = _peak_window(hr, pad_frac=0.10, extra=128)
            hr = _lbfgs_block(hr, win, iters, deadline - 0.3, beta=1e7)
        if time.process_time() < deadline - 0.3:
            hr = _lbfgs_block(hr, np.arange(hr.size), iters,
                              deadline - 0.2, tie=True)
        r = R_of(hr)
        if r > bestR + 1e-15:
            best, bestR = hr, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, ties=%d)"
          % (bestR, best.size, _tie_count(best)))

    # ---- Phase 1: multiscale round (a genuinely different search direction) ----
    # Try coarsening + re-optimizing + refining. This is cheap and can escape
    # the flat near-degenerate peak region that the original loop gets stuck in.
    ms_end = t0 + budget_seconds * 0.40
    h_ms, r_ms = _multiscale_round(best, ms_end, factors=(4, 2), iters=250)
    print("multiscale dR=%+.3e R=%.9f ties=%d"
          % (r_ms - bestR, r_ms, _tie_count(h_ms)))
    if r_ms > bestR + 1e-15:
        best, bestR = h_ms.copy(), r_ms

    # ---- Phase 2: original-style polish loop on the improved base ----
    loop_end = t0 + min(budget_seconds * 0.87, 52.0)
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 8.0)
        h_t = _lbfgs_block(best, np.arange(best.size), 600,
                           slice_end - 3.0, tie=True)
        r_t = R_of(h_t)
        dR = r_t - bestR
        accepted = r_t > bestR + 1e-15
        if accepted:
            best, bestR = h_t.copy(), r_t
        print("tie pass %d N=%d dR=%+.3e %s R=%.9f ties=%d"
              % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                 bestR, _tie_count(h_t)))
        if time.process_time() < slice_end - 2.0:
            win = _peak_window(best, pad_frac=0.06, extra=128)
            h_t = _lbfgs_block(best, win, 250, slice_end - 0.5, beta=1e7)
            if time.process_time() < slice_end - 0.4:
                h_t = _lbfgs_block(h_t, win, 250, slice_end - 0.3, tie=True)
            r_t = R_of(h_t)
            dR = r_t - bestR
            accepted = r_t > bestR + 1e-15
            if accepted:
                best, bestR = h_t.copy(), r_t
            print("tie peak %d N=%d dR=%+.3e %s R=%.9f ties=%d"
                  % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                     bestR, _tie_count(h_t)))

    # ---- Final passes ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 4.0:
        h_t = _lbfgs_block(best, np.arange(best.size), 600, fd - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_block(best, np.arange(best.size), 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL argmax no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth_window(h, frac=0.5):
    # smooth (non-tight) window: middle region where knot values are large
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= frac * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 2)
    hi = min(h.size - 1, idx.max() + 1)
    return np.arange(lo, hi + 1)


def _upsample(h, factor):
    n = h.size
    m = n * factor
    x = np.linspace(0, n, m, endpoint=False)
    xi = np.arange(n)
    return np.interp(x, xi, h)


def _downsample(h, factor):
    n = h.size
    m = n // factor
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    print("base R=%.12f (N=%d)" % (baseR, base.size))

    bestH = base.copy()
    bestR = baseR

    # NEW IDEA: refine at higher resolution. Upsample base by factor 2,
    # then run exact-R L-BFGS on a smoothed window to break the grid
    # symmetry, allowing sub-step placement of the peak and finer shape.
    factor = 2
    if base.size * factor <= 1000000:
        hi_res = _rescale(_upsample(base, factor))
        hrR = R_of(hi_res)
        print("upsampled R=%.12f (N=%d)" % (hrR, hi_res.size))
        if hrR > bestR:
            bestH, bestR = hi_res.copy(), hrR
        cur = hi_res.copy()
        curR = hrR
    else:
        cur = base.copy()
        curR = baseR

    # Phase 1: tie-aware exact-R polish on smoothed window (allows
    # multiple peak knots to co-develop, which the single-argmax version
    # cannot). This is the key change.
    win = _smooth_window(cur, frac=0.5)
    hn = _lbfgs_block(cur, win, 600, deadline, tie=True)
    rn = R_of(hn)
    if rn > curR + 1e-14:
        cur, curR = hn, rn
        print("tie-polish R=%.12f" % curR)
        if curR > bestR:
            bestH, bestR = cur.copy(), curR

    # Phase 2: beta-annealed polish on tight windows
    betas = [1e3, 1e4, 1e5, 1e6, 1e7]
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(cur, tol=0.999, pad_frac=0.15, extra=128)
        cap_t = min(deadline - 0.8, time.process_time() + 3.0)
        hn = _lbfgs_block(cur, win, 300, cap_t, beta=beta)
        rn = R_of(hn)
        if rn > curR + 1e-14:
            cur, curR = hn, rn
            if curR > bestR:
                bestH, bestR = cur.copy(), curR

    # Phase 3: exact-R on progressively wider tight windows
    for pad in (0.04, 0.06, 0.10, 0.15, 0.25, 0.40, 0.60):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(cur, tol=0.999, pad_frac=pad, extra=256)
        cap_t = min(deadline - 0.8, time.process_time() + 3.0)
        hn = _lbfgs_block(cur, win, 300, cap_t, beta=0.0)
        rn = R_of(hn)
        if rn > curR + 1e-14:
            cur, curR = hn, rn
            if curR > bestR:
                bestH, bestR = cur.copy(), curR

    # Phase 4: full-window tie-aware polish if time remains (this is the
    # most expensive but can unlock the multi-peak structure)
    if time.process_time() < deadline - 5.0:
        win = np.arange(cur.size)
        hn = _lbfgs_block(cur, win, 400, deadline, tie=True)
        rn = R_of(hn)
        if rn > curR + 1e-14:
            cur, curR = hn, rn
            if curR > bestR:
                bestH, bestR = cur.copy(), curR
            print("full-tie R=%.12f" % curR)

    # Phase 5: keep cycling tight tie-aware polish until deadline
    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        improved = False
        for pad in (0.05, 0.10, 0.20, 0.40):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cur, tol=0.9995, pad_frac=pad, extra=256)
            cap_t = min(deadline - 0.8, time.process_time() + 2.5)
            hn = _lbfgs_block(cur, win, 200, cap_t, tie=True)
            rn = R_of(hn)
            if rn > curR + 1e-14:
                cur, curR = hn, rn
                improved = True
                if curR > bestR:
                    bestH, bestR = cur.copy(), curR
        if not improved:
            win = _peak_window(cur, tol=0.99, pad_frac=0.5, extra=512)
            cap_t = min(deadline - 0.8, time.process_time() + 3.0)
            hn = _lbfgs_block(cur, win, 300, cap_t, beta=0.0)
            rn = R_of(hn)
            if rn > curR + 1e-14:
                cur, curR = hn, rn
                if curR > bestR:
                    bestH, bestR = cur.copy(), curR
            else:
                break
        print("cyc=%d R=%.12f" % (cycle, curR))

    altH, altR = cur.copy(), curR

    if bestR > baseR + 1e-12:
        print("final R=%.12f (N=%d) gain=%+.2e" % (bestR, bestH.size, bestR - baseR))
        return {"best": bestH, "alternative": altH}
    else:
        print("no gain over base (R=%.12f)" % baseR)
        return {"best": base, "alternative": altH}

