    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth_window(h, frac=0.5):
    # smooth (non-tight) window: middle region where knot values are large
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= frac * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 2)
    hi = min(h.size - 1, idx.max() + 1)
    return np.arange(lo, hi + 1)


def _upsample(h, factor):
    n = h.size
    m = n * factor
    x = np.linspace(0, n, m, endpoint=False)
    xi = np.arange(n)
    return np.interp(x, xi, h)


def _downsample(h, factor):
    n = h.size
    m = n // factor
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    print("base R=%.12f (N=%d)" % (baseR, base.size))

    bestH = base.copy()
    bestR = baseR

    # NEW IDEA: refine at higher resolution. Upsample base by factor 2,
    # then run exact-R L-BFGS on a smoothed window to break the grid
    # symmetry, allowing sub-step placement of the peak and finer shape.
    factor = 2
    if base.size * factor <= 1000000:
        hi_res = _rescale(_upsample(base, factor))
        hrR = R_of(hi_res)
        print("upsampled R=%.12f (N=%d)" % (hrR, hi_res.size))
        if hrR > bestR:
            bestH, bestR = hi_res.copy(), hrR
        cur = hi_res.copy()
        curR = hrR
    else:
        cur = base.copy()
        curR = baseR

    # Phase 1: tie-aware exact-R polish on smoothed window (allows
    # multiple peak knots to co-develop, which the single-argmax version
    # cannot). This is the key change.
    win = _smooth_window(cur, frac=0.5)
    hn = _lbfgs_block(cur, win, 600, deadline, tie=True)
    rn = R_of(hn)
    if rn > curR + 1e-14:
        cur, curR = hn, rn
        print("tie-polish R=%.12f" % curR)
        if curR > bestR:
            bestH, bestR = cur.copy(), curR

    # Phase 2: beta-annealed polish on tight windows
    betas = [1e3, 1e4, 1e5, 1e6, 1e7]
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(cur, tol=0.999, pad_frac=0.15, extra=128)
        cap_t = min(deadline - 0.8, time.process_time() + 3.0)
        hn = _lbfgs_block(cur, win, 300, cap_t, beta=beta)
        rn = R_of(hn)
        if rn > curR + 1e-14:
            cur, curR = hn, rn
            if curR > bestR:
                bestH, bestR = cur.copy(), curR

    # Phase 3: exact-R on progressively wider tight windows
    for pad in (0.04, 0.06, 0.10, 0.15, 0.25, 0.40, 0.60):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(cur, tol=0.999, pad_frac=pad, extra=256)
        cap_t = min(deadline - 0.8, time.process_time() + 3.0)
        hn = _lbfgs_block(cur, win, 300, cap_t, beta=0.0)
        rn = R_of(hn)
        if rn > curR + 1e-14:
            cur, curR = hn, rn
            if curR > bestR:
                bestH, bestR = cur.copy(), curR

    # Phase 4: full-window tie-aware polish if time remains (this is the
    # most expensive but can unlock the multi-peak structure)
    if time.process_time() < deadline - 5.0:
        win = np.arange(cur.size)
        hn = _lbfgs_block(cur, win, 400, deadline, tie=True)
        rn = R_of(hn)
        if rn > curR + 1e-14:
            cur, curR = hn, rn
            if curR > bestR:
                bestH, bestR = cur.copy(), curR
            print("full-tie R=%.12f" % curR)

    # Phase 5: keep cycling tight tie-aware polish until deadline
    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        improved = False
        for pad in (0.05, 0.10, 0.20, 0.40):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cur, tol=0.9995, pad_frac=pad, extra=256)
            cap_t = min(deadline - 0.8, time.process_time() + 2.5)
            hn = _lbfgs_block(cur, win, 200, cap_t, tie=True)
            rn = R_of(hn)
            if rn > curR + 1e-14:
                cur, curR = hn, rn
                improved = True
                if curR > bestR:
                    bestH, bestR = cur.copy(), curR
        if not improved:
            win = _peak_window(cur, tol=0.99, pad_frac=0.5, extra=512)
            cap_t = min(deadline - 0.8, time.process_time() + 3.0)
            hn = _lbfgs_block(cur, win, 300, cap_t, beta=0.0)
            rn = R_of(hn)
            if rn > curR + 1e-14:
                cur, curR = hn, rn
                if curR > bestR:
                    bestH, bestR = cur.copy(), curR
            else:
                break
        print("cyc=%d R=%.12f" % (cycle, curR))

    altH, altR = cur.copy(), curR

    if bestR > baseR + 1e-12:
        print("final R=%.12f (N=%d) gain=%+.2e" % (bestR, bestH.size, bestR - baseR))
        return {"best": bestH, "alternative": altH}
    else:
        print("no gain over base (R=%.12f)" % baseR)
        return {"best": base, "alternative": altH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _ctrl(h, K):
    n = h.size
    if K >= n:
        return h.copy()
    xk = np.linspace(0, n - 1, K)
    return np.interp(np.arange(n), xk, h)


def _raster(c, N):
    K = c.size
    if K == N:
        return c.copy()
    return np.interp(np.arange(N), np.linspace(0, N - 1, K), c)


def _interp_matrix_apply(g, N, K):
    if K == N:
        return g.copy()
    xo = np.arange(N, dtype=float)
    xk = np.linspace(0, N - 1, K)
    idx = np.searchsorted(xk, xo, side='right') - 1
    idx = np.clip(idx, 0, K - 2)
    x0 = xk[idx]
    x1 = xk[idx + 1]
    w1 = (xo - x0) / (x1 - x0)
    w0 = 1.0 - w1
    gc = np.zeros(K)
    np.add.at(gc, idx, g * w0)
    np.add.at(gc, idx + 1, g * w1)
    return gc


def _lbfgs_ctrl(c0, N, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return c0
    c0 = np.clip(c0, 0, None)
    if c0.sum() <= 0:
        return c0
    K = c0.size
    scale = max(1e-12, 1e-9 * float(c0.max()))
    x0 = np.log(c0 + scale)
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        c = np.exp(x)
        h = _raster(c, N)
        val, gh = fg(h)
        gc = _interp_matrix_apply(gh, N, K)
        return val, gc * c

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.exp(res.x)


def _prune(h, thr):
    """Set entries below thr*max to zero, then re-optimise."""
    out = h.copy()
    mx = out.max()
    if mx <= 0:
        return out
    out[out < thr * mx] = 0.0
    return out


def _smooth(h, sigma):
    """Gaussian smoothing along the index axis."""
    if sigma <= 0:
        return h.copy()
    r = int(max(1, 3 * sigma))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None and np.asarray(start).size > 0:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: polish start
    if time.process_time() < deadline - 2.0:
        best, bestR = run_cycle(best, bestR, min(deadline - 2.0,
                                                 time.process_time() + 0.25 * (deadline - time.process_time())))
        print("phase1 R=%.7f" % bestR)

    # Phase 2: smoothing + reopt to escape local minima
    for sigma in (2.0, 4.0, 8.0):
        if time.process_time() >= deadline - 4.0:
            break
        hs = _smooth(best, sigma)
        hs = _seed_zeros(hs)
        r = R_of(hs)
        sub_deadline = min(deadline - 4.0,
                           time.process_time() + 0.2 * (deadline - time.process_time()))
        hs, r = run_cycle(hs, r, sub_deadline)
        if r > bestR + 1e-13:
            best, bestR = hs.copy(), r
        print("smooth sigma=%.1f R=%.7f" % (sigma, bestR))

    # Phase 3: coarse ctrl-point ladder (from improved program)
    N = best.size
    for K in (384, 1536, 6144):
        if time.process_time() >= deadline - 6.0:
            break
        c0 = _ctrl(best, K)
        c = _lbfgs_ctrl(c0, N, 400, deadline - 6.0, beta=0.0)
        if K == 6144 and time.process_time() < deadline - 5.0:
            c = _lbfgs_ctrl(c, N, 200, deadline - 5.0, beta=1e7)
        h = _raster(c, N)
        h = _seed_zeros(h)
        r0 = R_of(h)
        if time.process_time() < deadline - 3.0:
            h, r0 = run_cycle(h, r0, deadline - 3.0)
        if r0 > bestR + 1e-13:
            best, bestR = h.copy(), r0
        print("ctrl K=%d R=%.7f" % (K, bestR))

    # Phase 4: pruning tiny heights + reopt
    if time.process_time() < deadline - 3.0:
        hp = _prune(best, 1e-4)
        hp = _seed_zeros(hp)
        r = R_of(hp)
        sub_deadline = min(deadline - 3.0,
                           time.process_time() + 0.3 * (deadline - time.process_time()))
        hp, r = run_cycle(hp, r, sub_deadline)
        if r > bestR + 1e-13:
            best, bestR = hp.copy(), r
        print("prune R=%.7f" % bestR)

    # Phase 5: final full polish
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 500, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    """L-BFGS over all positions (bounds >=0), with chosen surrogate."""
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, h.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    def try_stage(seed, seedR, maxiter, beta, tie, label):
        """Run one L-BFGS stage; return (h, R) if it improved seedR, else (seed, seedR)."""
        nonlocal best, bestR
        if time.process_time() >= deadline - 0.5:
            return seed, seedR
        h = _lbfgs_all_pos(seed, maxiter, deadline, beta=beta, tie=tie)
        r = R_of(h)
        print("%s beta=%g R=%.9f best=%.9f" % (label, beta, r, bestR))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("  ACCEPT %s beta=%g -> best=%.9f" % (label, beta, bestR))
        if r >= seedR - 1e-15:
            return h, r
        return seed, seedR

    # ---- Phase A: band ladder from start ----
    seed, seedR = best.copy(), bestR
    for beta in (8.0, 32.0, 128.0, 512.0, 2048.0):
        if time.process_time() >= deadline - 0.5:
            break
        seed, seedR = try_stage(seed, seedR, 250, beta, False, "A")
        seed, seedR = try_stage(seed, seedR, 120, 1e6, False, "A")
        seed, seedR = try_stage(seed, seedR, 150, 0.0, True, "A")

    # ---- Phase B: retighten with peak-window tie polishes ----
    for pad in (0.08, 0.04, 0.02):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 200,
                          min(deadline - 0.3,
                              time.process_time() + 4.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("B pad=%.3f R=%.9f best=%.9f" % (pad, r, bestR))

    # ---- Phase C: spend the rest ----
    while time.process_time() < deadline - 1.0:
        seed, seedR = best.copy(), bestR
        for beta in (4.0, 16.0, 64.0):
            if time.process_time() >= deadline - 0.5:
                break
            seed, seedR = try_stage(seed, seedR, 400, beta, False, "C")
        if time.process_time() >= deadline - 0.5:
            break
        seed, seedR = try_stage(seed, seedR, 300, 0.0, True, "C")
        # if a full cycle made no progress, break to avoid spinning
        if seedR <= bestR + 1e-15 and time.process_time() >= deadline - 2.0:
            break

    best = _rescale(best)
    bestR = R_of(best)
    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
