    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(start, Nf):
    start = np.asarray(start, dtype=float)
    n = start.size
    if n == Nf:
        return start.copy()
    c = np.concatenate([[0.0], np.cumsum(start)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nf)
    xs = np.linspace(0.0, 1.0, Nf + 1)
    old = np.linspace(0.0, 1.0, n + 1)
    cm = np.interp(xs, old, c)
    h = np.diff(cm) * Nf
    return h


def _prolongate(h):
    """Mass-preserving cumsum resample to double resolution."""
    return _resample(h, h.size * 2)


def _polish(h, deadline, tie_iters, beta_iters, pads):
    """(A): full tie L-BFGS, beta ladder, peak-window tie polish.
    Returns best-by-exact-R array found (>= input)."""
    best = h.copy()
    best_r = R_of(best)

    if time.process_time() < deadline - 0.3:
        h1 = _lbfgs_all_pos(best, tie_iters, deadline, tie=True)
        r1 = R_of(h1)
        if r1 > best_r:
            best, best_r = h1, r1

    for beta in (1e3, 1e5, 1e7):
        if time.process_time() >= deadline - 0.3:
            break
        hb = _lbfgs_all_pos(best, beta_iters, deadline, beta=beta)
        rb = R_of(hb)
        if rb > best_r:
            best, best_r = hb, rb

    for pad in pads:
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(best, tol=0.999, pad_frac=pad, extra=128)
        hw = _lbfgs_block(best, win, 150, deadline, tie=True)
        rw = R_of(hw)
        if rw > best_r:
            best, best_r = hw, rw

    return best, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        seed = np.asarray(start, dtype=float).copy()
    else:
        N0 = 4096
        xk = (np.arange(N0) + 0.5) / N0
        seed = 1.0 / np.sqrt(np.maximum(xk * (1 - xk), 1e-3))
        seed = np.minimum(seed, 4.0 * np.mean(seed))

    best = seed.copy()
    best_r = R_of(best)
    print(f"start R={best_r:.9f} N={best.size}")

    # (A) polish at current resolution
    rem = deadline - time.process_time()
    if rem > 1.0:
        st = min(deadline, time.process_time() + rem * 0.55)
        hA, rA = _polish(best, st, 400, 150, (0.15, 0.07, 0.03))
        if rA > best_r:
            best, best_r = hA, rA
        print(f"(A) R={best_r:.9f} N={best.size}")

    # (B) lift ladder: 32768 then 65536
    for target in (32768, 65536):
        if best.size >= target:
            continue
        rem = deadline - time.process_time()
        if rem < 1.5:
            break
        lifted = _prolongate(best) if best.size * 2 == target else _resample(best, target)
        rl = R_of(lifted)
        st = min(deadline, time.process_time() + rem * 0.55)
        hl, rhl = _polish(lifted, st, 300, 120, (0.15, 0.07, 0.03))
        # carry the better of the two candidates forward
        if rhl > best_r:
            best, best_r = hl, rhl
            print(f"lift->{target} ACCEPT R={best_r:.9f}")
        elif rl > best_r:
            best, best_r = lifted, rl
            print(f"lift->{target} raw-accept R={best_r:.9f}")
        else:
            print(f"lift->{target} reject (raw {rl:.9f}, pol {rhl:.9f})")

    # (C) jitter loop
    rng = np.random.default_rng(12345)
    k = 0
    while time.process_time() < deadline - 0.5:
        k += 1
        N = best.size
        seed_h = best.copy()
        seed_r = best_r
        trial = seed_h.copy()
        nwin = 4
        for _ in range(nwin):
            wlen = int(rng.uniform(0.005, 0.05) * N)
            wlen = max(4, min(N, wlen))
            lo = int(rng.integers(0, N - wlen + 1))
            sigma = rng.uniform(0.005, 0.03)
            trial[lo:lo + wlen] *= np.exp(rng.normal(0.0, sigma, wlen))
        trial = _rescale(trial)

        rem = deadline - time.process_time()
        if rem < 0.5:
            break
        # tie L-BFGS 150, beta 1e7 80, peak polish 0.05/0.02
        st = min(deadline, time.process_time() + rem * 0.7)
        ht = _lbfgs_all_pos(trial, 150, st, tie=True)
        rt = R_of(ht)
        if rt > seed_r:
            st2 = min(deadline, time.process_time() + (deadline - time.process_time()) * 0.6)
            hb = _lbfgs_all_pos(ht, 80, st2, beta=1e7)
            rb = R_of(hb)
            if rb > rt:
                ht, rt = hb, rb
        if rt > seed_r:
            for pad in (0.05, 0.02):
                if time.process_time() >= deadline - 0.4:
                    break
                win = _peak_window(ht, tol=0.999, pad_frac=pad, extra=64)
                hw = _lbfgs_block(ht, win, 100, deadline, tie=True)
                rw = R_of(hw)
                if rw > rt:
                    ht, rt = hw, rw
        if rt > best_r:
            best, best_r = ht, rt
            print(f"round {k} R={rt:.9f} best={best_r:.9f} ACCEPT")
        else:
            print(f"round {k} R={rt:.9f} best={best_r:.9f}")

    print(f"final R={best_r:.9f} N={best.size}")

    if start is not None:
        rs = R_of(np.asarray(start, dtype=float))
        if best_r >= rs:
            return best
        else:
            return {"best": np.asarray(start, dtype=float), "alternative": best}
    return best

