    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        if time.process_time() > deadline:
            raise TimeoutError
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None or not np.all(np.isfinite(res.x)):
        return h0
    return _rescale(np.exp(res.x))


def _lbfgs_free(h0, maxiter, deadline, free_mask):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    active = np.flatnonzero(free_mask)
    if active.size == 0:
        return h0
    x0 = np.log(np.maximum(h[active], 1e-30))

    def f(x):
        if time.process_time() > deadline:
            raise TimeoutError
        hh = h.copy()
        hh[active] = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None or not np.all(np.isfinite(res.x)):
        return h0
    h2 = h.copy()
    h2[active] = np.exp(res.x)
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    c = np.concatenate(([0.0], np.cumsum(h)))
    if c[-1] <= 0:
        return np.ones(n_new)
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _peak_window(h, tol=0.999, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = _rescale(np.clip(s, 0, None))
            best_R = _R(best)
            print(f"start R={best_R:.6f} N={len(best)}")

    if best is None:
        n = 256
        x = np.linspace(0, 1, n)
        best = np.cos(np.pi * (x - 0.5))**2 + 1e-3
        best = _rescale(best)
        best_R = _R(best)

    # Phase 1: full-vector L-BFGS on current N
    cur = _lbfgs(best, 400, min(deadline, time.process_time() + budget_seconds * 0.20))
    if _R(cur) > best_R:
        best, best_R = cur, _R(cur)
        print(f"phase1 R={best_R:.6f} N={len(best)}")

    # Phase 2: doubling ladder with peak-window refinement at each rung
    rungs = []
    n0 = len(best)
    n = n0
    while n < 32768:
        n *= 2
        rungs.append(n)

    for n_new in rungs:
        if time.process_time() > deadline - 2.0:
            break
        cur = _prolong(best, n_new)
        rung_deadline = min(deadline, time.process_time() + budget_seconds * 0.20)
        cur = _lbfgs(cur, 300, rung_deadline)
        r = _R(cur)
        print(f"rung N={len(cur)}: R={r:.6f}")
        if r > best_R:
            best, best_R = cur, r

    # Phase 3: peak-window polishing sweeps until deadline
    while time.process_time() < deadline - 0.5:
        win = _peak_window(best, tol=0.999, pad_frac=0.5, extra=128)
        mask = np.zeros(len(best), dtype=bool)
        mask[win] = True
        new = _lbfgs_free(best, 400, deadline - 0.3, mask)
        r = _R(new)
        if r > best_R + 1e-11:
            best, best_R = new, r
            print(f"window polish R={best_R:.6f} N={len(best)}")
        else:
            # widen window and try full polish once
            full = _lbfgs(best, 200, deadline - 0.3)
            rf = _R(full)
            if rf > best_R + 1e-11:
                best, best_R = full, rf
                print(f"full polish R={best_R:.6f}")
            break

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={_R(best):.6f} N={len(best)}")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample(h, k):
    """Upsample heights by factor k using linear interp on cumulative (mass-preserving)."""
    n = h.size
    m = n * k
    # treat as piecewise-linear then resample by averaging over sub-cells
    x = np.linspace(0, n, n)
    xf = np.linspace(0, n, m + 1)
    # cumulative integral of piecewise linear h
    c = np.concatenate(([0.0], np.cumsum((h[:-1] + h[1:]) * 0.5) + h[0]))
    # value at 0..n
    xs = np.arange(n + 1, dtype=float)
    # integral function sampled at integers; use np.interp on cumulative
    cum = np.zeros(n + 1)
    for i in range(1, n + 1):
        cum[i] = cum[i - 1] + 0.5 * (h[i - 1] + (h[i] if i < n else h[i - 1]))
    cum = np.concatenate(([0.0], np.cumsum(h)))
    # piecewise-constant approximation is simpler: just repeat heights
    return np.repeat(h, k)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Strategy: upsample the start to a finer grid to allow small refinements,
    # then run peak-window L-BFGS polishing on the finer grid.
    # This exploits the observation that R is maximized near a flat-top of f*f.
    h_work = best.copy()

    # Try upsampling by factors 2, 4 (limited by step budget)
    maxN = 900000
    for k in (2, 4):
        if h_work.size * k > maxN:
            continue
        if time.process_time() >= deadline - 3.0:
            break
        h_up = _upsample(h_work, k)
        h_up = _rescale(h_up)
        r_up = R_of(h_up)
        print("upsample x%d -> R=%.9f (N=%d)" % (k, r_up, h_up.size))
        # polish on finer grid using peak window
        for pad in (0.1, 0.05, 0.02):
            if time.process_time() >= deadline - 2.0:
                break
            win = _peak_window(h_up, pad_frac=pad, extra=max(64, 32 * k))
            slice_end = min(deadline - 1.0, time.process_time() + 4.0)
            hp = _lbfgs_block(h_up, win, 200, slice_end, tie=True)
            rp = R_of(hp)
            if rp > r_up:
                h_up, r_up = hp, rp
            print("  up x%d pad=%.2f R=%.9f" % (k, pad, r_up))
        if r_up > bestR + 1e-15:
            best, bestR = h_up.copy(), r_up
            h_work = h_up.copy()
            print("upsample x%d ACCEPT R=%.9f" % (k, bestR))
        else:
            print("upsample x%d rejected (best %.9f)" % (k, bestR))

    # Final full-ish polish on a moderately wide peak window
    c_end = t0 + budget_seconds * 0.99
    for pad in (0.08, 0.04, 0.02):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400,
                          min(c_end - 0.5, time.process_time() + 5.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter, beta):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _reparameterise(h, newN):
    n = h.size
    if n == newN:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    xs = np.linspace(0.0, total, newN + 1)
    ys = np.interp(xs, c, np.arange(n + 1, dtype=float))
    hn = np.diff(ys) * (n / newN)
    return np.clip(hn, 0.0, None)


def _smooth_kernel(h, sigma):
    """Gaussian smoothing of step heights (periodic edges not applied)."""
    if sigma <= 0:
        return h
    r = int(max(1, np.ceil(3 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.clip(np.convolve(h, k, mode='same'), 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = best.copy()

    # Stage A: sharp log-space
    if time.process_time() < deadline - 5.0:
        h = _lbfgs_log(cur, 600, deadline, 0.0)
        r = R_of(h)
        print("log-lbfgs R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur

    # Stage B: beta sweep + peak polishes
    for beta in (1e3, 1e4, 5e4, 2e5):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(cur, 200, deadline, beta)
        r = R_of(h)
        print("beta=%.0e R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(cur, deadline, frac, 32, 150, beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                print("  peak frac=%.2f R=%.7f" % (frac, rp))
            cur = hp if rp > bestR - 0.003 else cur

    # NEW: smoothing-based basin escape. Perturb the shape gently in
    # step-space, then re-optimise. This softens the peak micro-structure
    # which tends to trap L-BFGS near sharp local maxima.
    def _try_smooth(h0, sigmas, betas, iters=250):
        nonlocal best, bestR, cur
        for sig in sigmas:
            if time.process_time() >= deadline - 3.0:
                return
            hs = _rescale(_smooth_kernel(h0, sig))
            if R_of(hs) < bestR - 0.02:
                continue
            for beta in betas:
                if time.process_time() >= deadline - 2.5:
                    return
                ht = _lbfgs_log(hs, iters, deadline, beta)
                rt = R_of(ht)
                if rt > bestR + 1e-13:
                    best, bestR = ht, rt
                    print("smooth sig=%.2f beta=%.0e R=%.7f" % (sig, beta, rt))
                    cur = ht
                if rt > R_of(hs):
                    hs = ht

    _try_smooth(best, (1.0, 2.0, 4.0), (5e4, 2e5, 0.0))

    # Re-parameterisation sweep
    if time.process_time() < deadline - 6.0:
        for mult in (2, 3, 1):
            if time.process_time() >= deadline - 5.0:
                break
            newN = int(best.size * mult)
            if newN < 64 or newN > 900000:
                continue
            hh = _rescale(_reparameterise(best, newN))
            r = R_of(hh)
            if r < bestR - 0.01:
                continue
            for beta in (0.0, 5e4, 2e5):
                if time.process_time() >= deadline - 4.0:
                    break
                ht = _lbfgs_log(hh, 250, deadline, beta)
                rt = R_of(ht)
                if rt > r:
                    hh, r = ht, rt
            if r > bestR + 1e-12:
                best, bestR = hh, r
                print("reparam x%d R=%.7f (N=%d)" % (mult, bestR, best.size))
                cur = hh

    # Stage C: final sharp
    if time.process_time() < deadline - 2.0:
        h = _lbfgs_log(best, 400, deadline, 0.0)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final sharp R=%.7f" % bestR)

    # Stage D: alternate full sharp + peak polish + occasional smoothing
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 250, deadline, 0.0)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  alt full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, 150, 0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  alt peak #%d frac=%.2f R=%.7f" % (it, frac, rp))
        if it % 4 == 0 and time.process_time() < deadline - 5.0:
            _try_smooth(best, (1.0, 2.0), (5e4, 0.0), iters=200)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(start, Nf):
    start = np.asarray(start, dtype=float)
    n = start.size
    if n == Nf:
        return start.copy()
    c = np.concatenate([[0.0], np.cumsum(start)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nf)
    xs = np.linspace(0.0, 1.0, Nf + 1)
    old = np.linspace(0.0, 1.0, n + 1)
    cm = np.interp(xs, old, c)
    h = np.diff(cm) * Nf
    return h


def _prolongate(h):
    return _resample(h, h.size * 2)


def _polish(h, deadline, tie_iters, beta_iters, pads, betas=(1e3, 1e5, 1e7)):
    best = h.copy()
    best_r = R_of(best)

    if time.process_time() < deadline - 0.3:
        h1 = _lbfgs_all_pos(best, tie_iters, deadline, tie=True)
        r1 = R_of(h1)
        if r1 > best_r:
            best, best_r = h1, r1

    for beta in betas:
        if time.process_time() >= deadline - 0.3:
            break
        hb = _lbfgs_all_pos(best, beta_iters, deadline, beta=beta)
        rb = R_of(hb)
        if rb > best_r:
            best, best_r = hb, rb

    for pad in pads:
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(best, tol=0.999, pad_frac=pad, extra=128)
        hw = _lbfgs_block(best, win, 150, deadline, tie=True)
        rw = R_of(hw)
        if rw > best_r:
            best, best_r = hw, rw

    return best, best_r


def _envelope_jitter(h, rng, nmodes=4, amp=0.004):
    N = h.size
    i = np.arange(N)
    x = (i + 0.5) / N
    env = np.ones(N)
    for m in range(1, nmodes + 1):
        a = rng.normal(0.0, amp)
        env += a * np.cos(2.0 * np.pi * m * x)
    env = np.clip(env, 0.2, 5.0)
    return h * env


def _window_jitter(h, rng, nwin=4):
    N = h.size
    trial = h.copy()
    for _ in range(nwin):
        wlen = int(rng.uniform(0.005, 0.05) * N)
        wlen = max(4, min(N, wlen))
        lo = int(rng.integers(0, N - wlen + 1))
        sigma = rng.uniform(0.005, 0.03)
        trial[lo:lo + wlen] *= np.exp(rng.normal(0.0, sigma, wlen))
    return trial


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        seed = np.asarray(start, dtype=float).copy()
    else:
        N0 = 4096
        xk = (np.arange(N0) + 0.5) / N0
        seed = 1.0 / np.sqrt(np.maximum(xk * (1 - xk), 1e-3))
        seed = np.minimum(seed, 4.0 * np.mean(seed))

    best = seed.copy()
    best_r = R_of(best)
    print(f"start R={best_r:.9f} N={best.size}")

    # (A) polish at current resolution
    rem = deadline - time.process_time()
    if rem > 1.0:
        st = min(deadline, time.process_time() + rem * 0.55)
        hA, rA = _polish(best, st, 300, 120, (0.10, 0.05, 0.02),
                         betas=(1e5, 1e7))
        if rA > best_r:
            best, best_r = hA, rA
        print(f"(A) R={best_r:.9f} N={best.size}")

    # (B) lift to 131072
    target = 131072
    if best.size < target:
        rem = deadline - time.process_time()
        if rem > 1.5:
            lifted = _prolongate(best) if best.size * 2 == target else _resample(best, target)
            rl = R_of(lifted)
            st = min(deadline, time.process_time() + rem * 0.55)
            hl, rhl = _polish(lifted, st, 250, 100, (0.10, 0.05, 0.02),
                              betas=(1e5, 1e7))
            if rhl > best_r:
                best, best_r = hl, rhl
                print(f"lift->{target} ACCEPT R={best_r:.9f}")
            elif rl > best_r:
                best, best_r = lifted, rl
                print(f"lift->{target} raw-accept R={best_r:.9f}")
            else:
                print(f"lift->{target} reject (raw {rl:.9f}, pol {rhl:.9f})")

    # (C) structured jitter loop
    rng = np.random.default_rng(20240517)
    k = 0
    while time.process_time() < deadline - 0.5:
        k += 1
        N = best.size
        seed_h = best.copy()
        seed_r = best_r

        trial = _envelope_jitter(seed_h, rng, nmodes=4, amp=0.004)
        trial = _window_jitter(trial, rng, nwin=4)
        trial = _rescale(trial)

        rem = deadline - time.process_time()
        if rem < 0.5:
            break
        st = min(deadline, time.process_time() + rem * 0.7)
        ht = _lbfgs_all_pos(trial, 150, st, tie=True)
        rt = R_of(ht)
        if rt > seed_r:
            st2 = min(deadline, time.process_time() + (deadline - time.process_time()) * 0.6)
            hb = _lbfgs_all_pos(ht, 80, st2, beta=1e7)
            rb = R_of(hb)
            if rb > rt:
                ht, rt = hb, rb
        if rt > seed_r:
            for pad in (0.05, 0.02):
                if time.process_time() >= deadline - 0.4:
                    break
                win = _peak_window(ht, tol=0.999, pad_frac=pad, extra=64)
                hw = _lbfgs_block(ht, win, 100, deadline, tie=True)
                rw = R_of(hw)
                if rw > rt:
                    ht, rt = hw, rw
        if rt > best_r:
            best, best_r = ht, rt
            accepted = "ACCEPT"
        else:
            accepted = "revert"
        Lf = _knots(best)
        mx = Lf.max()
        near01 = np.mean(Lf >= 0.999 * mx) if mx > 0 else 0.0
        print(f"round {k} N={best.size} R={rt:.9f} best={best_r:.9f} near01={near01:.4f} {accepted}")

    print(f"final R={best_r:.9f} N={best.size}")

    if start is not None:
        rs = R_of(np.asarray(start, dtype=float))
        if best_r >= rs:
            return best
        else:
            return {"best": np.asarray(start, dtype=float), "alternative": best}
    return best

