def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_floor(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    mask = Lf > 1e-9 * M
    gLf = np.zeros_like(Lf)
    gLf[mask] += -1.0 / Lf[mask]
    gLf[int(np.argmax(Lf))] += mask.sum() / M
    grad = _backprop(gLf, h)
    val = -np.sum(np.log(Lf[mask])) + mask.sum() * np.log(M)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 floor=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if floor:
        fg = _fun_grad_floor
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _near_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0
    return float(np.mean(Lf >= 0.99 * mx)), float(np.mean(Lf >= 0.95 * mx))


def _jitter(h, rng, nwin=4):
    n = h.size
    h2 = h.copy()
    for _ in range(nwin):
        L = int(rng.integers(4, max(5, n // 8)))
        if L >= n:
            L = n
        st = int(rng.integers(0, n - L + 1))
        sig = rng.uniform(0.01, 0.03)
        h2[st:st + L] *= np.exp(rng.normal(0.0, sig, size=L))
    return h2


def _exact_polish(h, deadline, bestR, best):
    """Full exact-R polish: tie L-BFGS, beta ladder, peak windows."""
    win_all = np.arange(h.size)
    ht = _lbfgs_block(h, win_all, 400,
                      min(deadline, time.process_time() + 8.0), tie=True)
    r = R_of(ht)
    if r > bestR + 1e-15:
        best, bestR = ht.copy(), r
    for beta in (1e3, 1e5, 1e7):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(best, win_all, 150,
                          min(deadline, time.process_time() + 4.0), beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
    for pad in (0.15, 0.07, 0.03):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline, time.process_time() + 3.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    n01, n1 = _near_fracs(best)
    print("base near01=%.4f near1=%.4f" % (n01, n1))

    # ---- Phase 1: log-floor surrogate on all cells ----
    win_all = np.arange(best.size)
    floor_iters = 0
    h_floor = best
    r_floor = bestR
    if time.process_time() < deadline - 5.0:
        hf = _lbfgs_block(best, win_all, 150,
                          min(deadline, time.process_time() + 8.0), floor=True)
        floor_iters = 150
        r_floor = R_of(hf)
        h_floor = hf
        n01f, n1f = _near_fracs(hf)
        print("floor pass1 iters=%d Rfloor=%.9f near01=%.4f near1=%.4f"
              % (floor_iters, r_floor, n01f, n1f))

    # ---- Phase 2: exact-R polish of floor result ----
    cand, candR = h_floor.copy(), r_floor
    if time.process_time() < deadline - 3.0:
        cand, candR = _exact_polish(cand, deadline, candR, cand)
    n01c, n1c = _near_fracs(cand)
    print("floor iters=%d Rfloor=%.9f -> R=%.9f best=%.9f near01=%.4f near1=%.4f"
          % (floor_iters, r_floor, candR, bestR, n01c, n1c))

    if candR > bestR + 1e-15:
        best, bestR = cand.copy(), candR
        print("floor ACCEPT R=%.9f" % bestR)

    # ---- Phase 3: retry with 400 floor iters + peak-only polish if failed ----
    if bestR <= startR + 1e-14 and time.process_time() < deadline - 6.0:
        hf = _lbfgs_block(best, win_all, 400,
                          min(deadline, time.process_time() + 10.0), floor=True)
        r_floor = R_of(hf)
        floor_iters = 400
        win = _peak_window(hf, pad_frac=0.10, extra=96)
        hf = _lbfgs_block(hf, win, 300,
                          min(deadline, time.process_time() + 4.0), tie=True)
        cand, candR = _exact_polish(hf, deadline, R_of(hf), hf)
        n01c, n1c = _near_fracs(cand)
        print("floor iters=%d Rfloor=%.9f -> R=%.9f best=%.9f near01=%.4f near1=%.4f"
              % (floor_iters, r_floor, candR, bestR, n01c, n1c))
        if candR > bestR + 1e-15:
            best, bestR = cand.copy(), candR
            print("floor ACCEPT R=%.9f" % bestR)

    # ---- Phase 4: final exact-R jitter loop ----
    rng = np.random.default_rng(2024)
    rounds = 0
    acc = 0
    while time.process_time() < deadline - 1.5:
        rounds += 1
        hj = _jitter(best, rng, nwin=4)
        win = _peak_window(hj, pad_frac=0.05, extra=96)
        hj = _lbfgs_block(hj, win, 150,
                          min(deadline - 1.0, time.process_time() + 2.0),
                          tie=True)
        rj = R_of(hj)
        if rj > bestR + 1e-15:
            win2 = _peak_window(hj, pad_frac=0.02, extra=64)
            hj2 = _lbfgs_block(hj, win2, 150,
                               min(deadline - 0.8, time.process_time() + 1.5),
                               tie=True)
            rj2 = R_of(hj2)
            if rj2 > rj:
                hj, rj = hj2, rj2
            if rj > bestR + 1e-15:
                best, bestR = hj.copy(), rj
                acc += 1
                if acc % 3 == 0:
                    print("jitter round=%d acc=%d R=%.9f" % (rounds, acc, bestR))
    print("jitter done rounds=%d acc=%d R=%.9f" % (rounds, acc, bestR))

    # ---- Phase 5: final exact polish ----
    if time.process_time() < deadline - 0.5:
        best, bestR = _exact_polish(best, deadline, bestR, best)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth_perturb(h, rng, scale):
    n = h.size
    k = max(4, n // 200)
    x = rng.standard_normal(n + k)
    kern = np.ones(k) / k
    sm = np.convolve(x, kern, mode='same')[:n]
    sm = sm / (np.std(sm) + 1e-12)
    return h * np.exp(scale * sm)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(20240517)

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
    if best is None:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    start_best = best.copy()
    start_R = bestR
    alt = None
    altR = 0.0

    # Phase A: exponential-smoothed max (beta) polish on full problem, then exact.
    for beta in (30.0, 100.0, 300.0):
        if time.process_time() >= deadline - 3.0:
            break
        h = _lbfgs_block(best, np.arange(best.size), 400, deadline, beta=beta)
        h = _lbfgs_block(h, np.arange(h.size), 300, deadline)
        r = R_of(h)
        print("beta=%.0f R=%.7f" % (beta, r))
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r

    # Phase B: peak-window polish (exact) with growing windows.
    for tol, pf, ex in ((0.9995, 0.40, 64), (0.999, 0.6, 128), (0.99, 1.0, 256)):
        if time.process_time() >= deadline - 2.0:
            break
        free = _peak_window(best, tol=tol, pad_frac=pf, extra=ex)
        h = _lbfgs_block(best, free, 400, deadline)
        r = R_of(h)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.4f) R=%.7f" % (tol, bestR))

    # Phase C: basin hopping with smooth perturbations + window polish.
    hop = 0
    while time.process_time() < deadline - 2.0 and hop < 60:
        hop += 1
        scale = 0.008 + 0.03 * ((hop * 7) % 5) / 4.0
        h = _smooth_perturb(best, rng, scale)
        h = _rescale(h)
        h = _lbfgs_block(h, np.arange(h.size), 250, deadline)
        if time.process_time() >= deadline - 1.5:
            break
        free = _peak_window(h, tol=0.9995, pad_frac=0.5, extra=64)
        h = _lbfgs_block(h, free, 300, deadline)
        r = R_of(h)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("hop %d R=%.7f" % (hop, bestR))

    # Phase D: alternate full exact + window until stall.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_block(best, np.arange(best.size), 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        free = _peak_window(best, tol=0.9995, pad_frac=0.5, extra=64)
        h = _lbfgs_block(best, free, 400, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and altR > 0 and bestR <= start_R + 1e-15 and altR > 0:
        return {"best": start_best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
