    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


# ------------------------------------------------------------------
# New idea: explicit coarse-profile optimisation on a *coarsened*
# version of the start.  The coarse problem is cheap and smooth, so we
# can do many perturb-and-reoptimise restarts.  Then upscale back to
# the fine grid and polish with a peak-local L-BFGS-B.
# ------------------------------------------------------------------

def _coarse_knots(c):
    return np.concatenate(([0.0], np.convolve(c, c), [0.0]))


def _R_coarse(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = _coarse_knots(c)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _coarse_grad_log(c):
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    Lf = _coarse_knots(c)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    if num <= 0:
        return 1e18, np.zeros(c.size)
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(c.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    gL = gLf[1:-1]
    if c.size > 1500:
        grad = 2.0 * fftconvolve(gL, c[::-1], mode='valid')[:c.size]
    else:
        grad = 2.0 * np.correlate(gL, c, mode='valid')[:c.size]
    grad = grad + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _coarse_lbfgs(c0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return c0
    c0 = np.clip(c0, 1e-12, None)
    x0 = np.log(c0)

    def f(x):
        c = np.exp(x)
        val, g = _coarse_grad_log(c)
        return val, g * c

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-np.inf, np.log(1e-6))] * c0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-18, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.exp(np.clip(res.x, -30.0, np.log(1e-6)))


def _propose(c, rng):
    m = c.size
    u = np.arange(m, dtype=float) / m
    kind = rng.integers(0, 4)
    s = np.exp(rng.uniform(np.log(0.01), np.log(0.4)))
    cp = c.copy()
    if kind == 0:
        E = np.zeros(m)
        for k in range(1, 5):
            a = rng.normal()
            phi = rng.uniform(0, 2 * np.pi)
            E += a * np.cos(2 * np.pi * k * u + phi)
        mE = np.max(np.abs(E))
        if mE > 0:
            E /= mE
        cp = c * (1.0 + s * E)
    elif kind == 1:
        nb = rng.integers(8, 65)
        edges = np.sort(rng.choice(m + 1, size=nb + 1, replace=False))
        for i in range(nb):
            lo, hi = edges[i], edges[i + 1]
            if hi <= lo:
                continue
            f = np.exp(rng.uniform(np.log(1 / 1.5), np.log(1.5)))
            cp[lo:hi] *= f
    elif kind == 2:
        frac = rng.uniform(0.03, 0.05)
        k = max(1, int(frac * m))
        idx = rng.choice(m, size=k, replace=False)
        f = np.exp(rng.uniform(np.log(0.5), np.log(2.0), size=k))
        cp[idx] *= f
    else:
        frac = rng.uniform(0.01, 0.03)
        k = max(1, int(frac * m))
        idx = rng.choice(m, size=k, replace=False)
        cp[idx] = 0.0
    cp = np.clip(cp, 0.0, None)
    if cp.sum() <= 0:
        cp = c.copy()
    return cp


def _coarsen(h, m):
    """Average-pool h down to m bins."""
    n = h.size
    if m >= n:
        return h.copy()
    # cumulative-sum based averaging
    idx = (np.arange(m + 1) * n) // m
    cs = np.concatenate(([0.0], np.cumsum(h)))
    c = (cs[idx[1:]] - cs[idx[:-1]]) / (idx[1:] - idx[:-1])
    return c


def _upsample(c, n):
    m = c.size
    idx = (np.arange(n) * m) // n
    return c[idx]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    rng = np.random.default_rng(20240607)

    # Try coarse optimisation at several resolutions, choose the best.
    n_full = best.size
    coarse_choices = []
    for tgt in (2048, 4096, 8192):
        if tgt < n_full:
            coarse_choices.append(tgt)
    if not coarse_choices:
        coarse_choices = [max(64, n_full // 4)]

    best_fine = best.copy()
    best_fineR = bestR
    coarse_end = t0 + budget_seconds * 0.55

    for m in coarse_choices:
        if time.process_time() >= coarse_end - 2.0:
            break
        c0 = _coarsen(best, m)
        if c0.sum() <= 0:
            continue
        r0 = _R_coarse(c0)
        c_work = c0.copy()
        c_work = _coarse_lbfgs(c_work, 500, coarse_end - 1.0)
        r_work = _R_coarse(c_work)
        n_imp = 0
        n_res = 0
        while time.process_time() < coarse_end - 1.0:
            n_res += 1
            cp = _propose(c_work, rng)
            iters = int(rng.integers(60, 151))
            c_new = _coarse_lbfgs(cp, iters, coarse_end - 0.5)
            r_new = _R_coarse(c_new)
            if r_new > r_work + 1e-16:
                c_work = c_new
                r_work = r_new
                n_imp += 1
        print("  m=%d coarse %.12f->%.12f (restarts=%d imp=%d)"
              % (m, r0, r_work, n_res, n_imp))

        # Upscale and polish
        h_rec = _rescale(_upsample(c_work, n_full))
        r_rec = R_of(h_rec)
        polish_end = t0 + budget_seconds * 0.85
        for pad in (0.12, 0.08, 0.05, 0.03):
            if time.process_time() >= polish_end - 0.5:
                break
            win = _peak_window(h_rec, pad_frac=pad, extra=128)
            ht = _lbfgs_block(h_rec, win, 250,
                              min(polish_end - 0.3,
                                  time.process_time() + 4.0), beta=1e7)
            rt = R_of(ht)
            if rt > r_rec + 1e-15:
                h_rec = ht
                r_rec = rt
        ht = _lbfgs_block(h_rec, np.arange(n_full), 200,
                          polish_end - 0.3, tie=True)
        rt = R_of(ht)
        if rt > r_rec + 1e-15:
            h_rec = ht
            r_rec = rt
        print("  m=%d polished R=%.12f" % (m, r_rec))
        if r_rec > best_fineR + 1e-15:
            best_fine = h_rec.copy()
            best_fineR = r_rec

    best = best_fine
    bestR = best_fineR

    peak_end = t0 + budget_seconds * 0.99
    if time.process_time() < peak_end - 2.0:
        for pad in (0.06, 0.04, 0.02):
            if time.process_time() >= peak_end - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 300, peak_end - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                print("peak ladder ACCEPT R=%.12f" % bestR)
        ht = _lbfgs_block(best, np.arange(best.size), 300,
                          peak_end - 0.3, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("full tie ACCEPT R=%.12f" % bestR)

    f01, f1, f5 = _nearmax_fracs(best)
    print("final R=%.9f (start %.9f, N=%d, ties=%d, near 0.1/1/5=%.3f/%.3f/%.3f)"
          % (bestR, startR, best.size, _tie_count(best), f01, f1, f5))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
import heapq
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter, beta):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _smooth_kernel(h, sigma):
    if sigma <= 0:
        return h
    r = int(max(1, np.ceil(3 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.clip(np.convolve(h, k, mode='same'), 0.0, None)


def _envelope(n, rng, amp):
    if amp <= 0:
        return np.ones(n)
    idx = np.arange(n, dtype=float)
    env = np.ones(n)
    for k in range(1, 6):
        a = rng.standard_normal()
        env += amp * a * np.cos(np.pi * k * idx / n)
    return np.clip(env, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # (A) 0-10s: sharp full L-BFGS + peak-window tie polish on start
    stageA_deadline = min(deadline - 2.0, t0 + 10.0)
    if time.process_time() < stageA_deadline - 0.5:
        h = _lbfgs_log(best, 400, stageA_deadline, 0.0)
        r = R_of(h)
        if r > bestR + 1e-12:
            best, bestR = h, r
            print("A sharp R=%.7f" % bestR)
        for frac in (0.20, 0.10, 0.05):
            if time.process_time() >= stageA_deadline - 0.3:
                break
            hp = _window_polish_peak(best, stageA_deadline, frac, 32, 200, 0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("A peak frac=%.2f R=%.7f" % (frac, bestR))

    # (B) annealing loop over sigma ladder
    sigmas = [1, 2, 4, 8, 16, 24, 32]
    amps = [1.0, 0.7]
    rejected = []  # heap of (R, idx, h)
    trial = 0
    accepted = 0
    sigma_idx = 0
    while time.process_time() < deadline - 3.0:
        trial += 1
        now = time.process_time()
        trial_deadline = min(now + 3.0, deadline - 2.0)
        if trial_deadline <= now + 0.2:
            break

        if trial % 4 == 0 and rejected:
            # restart from best rejected candidate
            _, _, hseed = heapq.nlargest(1, rejected)[0]
            sigma = sigmas[sigma_idx % len(sigmas)]
            amp = amps[trial % len(amps)]
        else:
            hseed = best
            sigma = sigmas[sigma_idx % len(sigmas)]
            amp = amps[trial % len(amps)]
        sigma_idx += 1

        n = hseed.size
        env = _envelope(n, rng, 0.05 * amp)
        hp = np.clip(_smooth_kernel(hseed, sigma) * env, 0.0, None)
        if hp.sum() <= 0:
            continue
        hp = _rescale(hp)

        ht = _lbfgs_log(hp, 250, trial_deadline, 0.0)
        for beta in (1e5, 1e7):
            if time.process_time() >= trial_deadline - 0.3:
                break
            ht = _lbfgs_log(ht, 100, trial_deadline, beta)
        if time.process_time() < trial_deadline - 0.3:
            ht = _window_polish_peak(ht, trial_deadline, 0.03, 32, 100, 0.0)

        rt = R_of(ht)
        acc = rt > bestR + 1e-12
        if acc:
            best, bestR = ht, rt
            accepted += 1
            print("trial %d sig=%d amp=%.1f R=%.7f ACCEPT" % (trial, sigma, amp, rt))
        else:
            heapq.heappush(rejected, (rt, trial, ht))
            if len(rejected) > 4:
                heapq.heappop(rejected)
            print("trial %d sig=%d amp=%.1f R=%.7f (best %.7f)" %
                  (trial, sigma, amp, rt, bestR))

    # final peak-window tie polish
    for frac in (0.05, 0.02, 0.01):
        if time.process_time() >= deadline - 0.5:
            break
        hp = _window_polish_peak(best, deadline, frac, 32, 200, 0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            best, bestR = hp, rp
            print("final peak frac=%.2f R=%.7f" % (frac, bestR))

    print("final R=%.7f (N=%d, zeros %.1f%%, accepted %d/%d)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), accepted, trial))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_pinned(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    grad = _backprop(-dq / num, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        start = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[start:start + L] *= fac
    return c2


def _jitter_full(h, rng, nblocks_lo=2, nblocks_hi=4, sigma=0.02, Lmax=65):
    n = h.size
    h2 = h.copy()
    nb = int(rng.integers(nblocks_lo, nblocks_hi))
    for _ in range(nb):
        L = int(rng.integers(2, Lmax))
        if L >= n:
            L = n
        st = int(rng.integers(0, n - L + 1))
        h2[st:st + L] *= np.exp(rng.normal(0.0, sigma, size=L))
    return h2


def _pinned_outer(h0, iters, deadline):
    """Free ascent of log(num)-2log(sum), projecting peak to 1 after each block."""
    h = _rescale(np.clip(h0, 0, None))
    if h.sum() <= 0:
        return h0
    best = h.copy()
    bestR = R_of(h)
    for it in range(iters):
        if time.process_time() >= deadline - 0.5:
            break
        hmax = h.max()
        if hmax <= 0:
            break
        active = np.flatnonzero(h > 1e-13 * hmax)
        if active.size == 0:
            break
        if it % 5 == 4:
            # exact tie objective on full array, then re-project
            h2 = _lbfgs_block(h, np.arange(h.size), 120,
                              min(deadline - 0.3,
                                  time.process_time() + 1.5), tie=True)
        else:
            h2 = _lbfgs_block(h, active, 80,
                              min(deadline - 0.3,
                                  time.process_time() + 1.0),
                              tie=False, beta=0.0, flat=False)
            # use pinned objective via a dedicated block
            h2 = _pinned_block(h, active, 80,
                               min(deadline - 0.3,
                                   time.process_time() + 1.0))
        # project peak to 1
        M = _knots(h2).max()
        if M > 0:
            h2 = np.clip(h2 / np.sqrt(M), 0.0, None)
        if h2.sum() <= 0:
            break
        h = h2
        r = R_of(h)
        if r > bestR + 1e-15:
            bestR = r
            best = h.copy()
        print("pinned it=%d R=%.9f best=%.9f" % (it, r, bestR))
    return best


def _pinned_block(h0, active, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_pinned(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- (A) baseline tie L-BFGS + peak polish on start ----
    a_end = min(deadline, time.process_time() + 6.0)
    win = _peak_window(best, pad_frac=0.05, extra=96)
    hA = _lbfgs_block(best, win, 400, a_end, tie=True)
    rA = R_of(hA)
    if rA > bestR + 1e-15:
        best, bestR = hA.copy(), rA
    print("PhaseA R=%.9f" % bestR)

    # ---- (B) pinned outer loop ----
    b_end = t0 + budget_seconds * 0.72
    hB = _pinned_outer(best, 60, b_end)
    rB = R_of(hB)
    if rB > bestR + 1e-15:
        best, bestR = hB.copy(), rB
        print("Pinned ACCEPT R=%.9f" % bestR)
    else:
        print("Pinned no gain (rB=%.9f best=%.9f)" % (rB, bestR))

    # ---- (C) exact tie-L-BFGS + beta ladder + peak polish ----
    c_end = min(deadline, time.process_time() + 8.0)
    hC = _lbfgs_block(best, np.arange(best.size), 400, c_end, tie=True)
    rC = R_of(hC)
    if rC > bestR + 1e-15:
        best, bestR = hC.copy(), rC
    for beta in (1e5, 1e7):
        if time.process_time() >= c_end - 0.5:
            break
        hb = _lbfgs_block(best, np.arange(best.size), 200,
                          min(c_end, time.process_time() + 2.0), beta=beta)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb.copy(), rb
    for pad, frac in ((0.05, 0.2), (0.02, 0.1), (0.01, 0.05)):
        if time.process_time() >= c_end - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=96)
        hp = _lbfgs_block(best, win, 300,
                          min(c_end, time.process_time() + 2.0), tie=True)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
    print("PhaseC R=%.9f" % bestR)

    # ---- (D) jitter rounds with tie re-polish ----
    rng = np.random.default_rng(20240607)
    d_end = deadline
    rounds = 0
    accepted = 0
    while time.process_time() < d_end - 1.0:
        rounds += 1
        hj = _jitter_full(best, rng, 2, 4, 0.02, 65)
        hj = _lbfgs_block(hj, np.arange(hj.size), 150,
                          min(d_end - 0.5,
                              time.process_time() + 2.0), tie=True)
        rj = R_of(hj)
        if rj > bestR + 1e-15:
            best, bestR = hj.copy(), rj
            accepted += 1
            print("jitter round=%d ACCEPT R=%.9f" % (rounds, bestR))
    print("PhaseD rounds=%d accepted=%d R=%.9f" % (rounds, accepted, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter, beta):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _reparameterise(h, newN):
    n = h.size
    if n == newN:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    xs = np.linspace(0.0, total, newN + 1)
    ys = np.interp(xs, c, np.arange(n + 1, dtype=float))
    hn = np.diff(ys) * (n / newN)
    return np.clip(hn, 0.0, None)


def _smooth_kernel(h, sigma):
    if sigma <= 0:
        return h
    r = int(max(1, np.ceil(3 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.clip(np.convolve(h, k, mode='same'), 0.0, None)


def _jitter(h, rng):
    """Perturb 2-3 random blocks by exp(N(0,0.05)) times a cosine envelope."""
    n = h.size
    h2 = h.copy()
    nblocks = rng.integers(2, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        s = int(rng.integers(0, n - L + 1))
        env = np.cos(np.linspace(-np.pi / 2, np.pi / 2, L)) ** 2
        fac = np.exp(rng.normal(0.0, 0.05, size=L))
        h2[s:s + L] *= (1.0 + (fac - 1.0) * env)
    return np.clip(h2, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---------- Stage A: tie-aware polish on start ----------
    def _tie_polish(h0, iters, betas, deadline):
        h = h0
        r = R_of(h)
        for beta in betas:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_log(h, iters, deadline, beta)
            rt = R_of(ht)
            if rt > r:
                h, r = ht, rt
        return h, r

    if time.process_time() < deadline - 8.0:
        h, r = _tie_polish(best, 400, (0.0, 1e5, 1e7), min(deadline, t0 + 8.0))
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("A tie-polish R=%.7f" % bestR)
        for frac, pad in ((0.05, 32), (0.02, 16)):
            if time.process_time() >= deadline - 6.0:
                break
            hp = _window_polish_peak(best, deadline, frac, pad, 200, 0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("A peak frac=%.2f R=%.7f" % (frac, rp))

    # ---------- Stage B: coarse ladder ----------
    levels = [1024, 2048, 4096, 8192, 16384]
    level_bests = {}

    def _coarse_search(h_level, level_deadline, iters=250):
        """Tie L-BFGS + jitter rounds at a coarse level."""
        h = h_level
        r = R_of(h)
        ht = _lbfgs_log(h, iters, deadline=level_deadline, beta=0.0)
        rt = R_of(ht)
        if rt > r:
            h, r = ht, rt
        accepted = 0
        rounds = 0
        while time.process_time() < level_deadline - 0.5 and rounds < 25:
            rounds += 1
            hj = _rescale(_jitter(h, rng))
            rj = R_of(hj)
            if rj > r - 0.002:
                ht = _lbfgs_log(hj, 120, level_deadline, 0.0)
                rt = R_of(ht)
                if rt > r + 1e-13:
                    h, r = ht, rt
                    accepted += 1
        return h, r, accepted

    if time.process_time() < deadline - 20.0:
        tB_start = time.process_time()
        tB_end = min(deadline - 15.0, tB_start + 37.0)
        per_level = (tB_end - tB_start) / len(levels)
        cur_best = best
        cur_bestR = bestR
        for N in levels:
            if time.process_time() >= tB_end - 1.0:
                break
            level_deadline = min(tB_end, time.process_time() + per_level)
            hN = _rescale(_reparameterise(cur_best, N))
            rN0 = R_of(hN)
            hN, rN, acc = _coarse_search(hN, level_deadline)
            level_bests[N] = (hN.copy(), rN)
            # lift back and polish briefly to compare
            hl = _rescale(_reparameterise(hN, cur_best.size))
            hl = _lbfgs_log(hl, 100, deadline, 0.0)
            rl = R_of(hl)
            print("B N=%d R %.7f->%.7f acc=%d lift=%.7f" %
                  (N, rN0, rN, acc, rl))
            if rl > cur_bestR + 1e-13:
                cur_best, cur_bestR = hl, rl
                if rl > bestR + 1e-13:
                    best, bestR = hl, rl
            # re-polish best-so-far at this level
            if time.process_time() < level_deadline - 0.5:
                hb = _rescale(_reparameterise(cur_best, N))
                hb, rb, _ = _coarse_search(hb, level_deadline)
                if rb > level_bests[N][1]:
                    level_bests[N] = (hb, rb)

    # ---------- Stage C: prolongate best coarse back to full N ----------
    fullN = start_best.size
    if level_bests and time.process_time() < deadline - 8.0:
        # pick best coarse level by lifted R
        best_lvl = max(level_bests.items(), key=lambda kv: kv[1][1])
        hc = _rescale(_reparameterise(best_lvl[1][0], fullN))
        rc = R_of(hc)
        hc, rc = _tie_polish(hc, 400, (0.0, 1e5, 1e7), min(deadline - 5.0, time.process_time() + 6.0))
        print("C prolongate from N=%d R=%.7f" % (best_lvl[0], rc))
        if rc > bestR + 1e-13:
            best, bestR = hc, rc
        for frac, pad in ((0.2, 32), (0.1, 32), (0.05, 32), (0.02, 16), (0.01, 16)):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(best, deadline, frac, pad, 200, 0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("C peak frac=%.2f R=%.7f" % (frac, rp))

    # ---------- Stage D: full-array jitter rounds ----------
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        hj = _rescale(_jitter(best, rng))
        rj = R_of(hj)
        if rj > bestR - 0.002:
            ht = _lbfgs_log(hj, 150, deadline, 0.0)
            rt = R_of(ht)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                print("D jitter #%d R=%.7f" % (it, bestR))
        if it % 3 == 0 and time.process_time() < deadline - 3.0:
            h = _lbfgs_log(best, 200, deadline, 0.0)
            r = R_of(h)
            if r > bestR + 1e-13:
                best, bestR = h, r
