import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    z = np.clip(beta * (Lf - mx), -60.0, 60.0)
    e = np.exp(z)
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, mode="log", beta=0.0, logparam=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    if mode == "sm":
        fg = lambda hh: _fun_grad_sm(hh, beta)
    elif mode == "tie":
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    if logparam:
        x0 = np.log(np.clip(h[active], 1e-300, None))

        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fg(hh)
            return val, g[active] * hh[active]
        bounds = [(-30.0, 30.0)] * active.size
    else:
        x0 = h[active].copy()

        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g[active]
        bounds = [(0.0, None)] * active.size

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n) if logparam else h.copy()
    if logparam:
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    else:
        h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xc = np.linspace(0.0, 1.0, Nc + 1)
    Sc = np.interp(xc, xs, S)
    Sc = np.maximum.accumulate(Sc)
    hc = np.clip(np.diff(Sc), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _block_perturb(h, rng, nblocks_lo=6, nblocks_hi=12, sigma=0.30):
    h = h.copy()
    n = h.size
    if n < 4:
        return h
    nblocks = int(rng.integers(nblocks_lo, nblocks_hi + 1))
    W = n
    cuts = np.sort(rng.choice(np.arange(1, W), size=min(nblocks - 1, W - 1),
                              replace=False))
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(len(edges) - 1):
        a = edges[b]
        c = edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    pos = h[h > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = h <= 0
        if np.any(z):
            h[z] = 1e-3 * local_mean
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs(cur, np.arange(512), maxiter=800, deadline=deadline)
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand, r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif alternative is None or r > alt_r:
            alternative, alt_r = cand.copy(), r

    hard_end = deadline - 0.5
    N = cur.size

    # ---------------- Experiment: coarse block moves + prolongation --------
    try:
        Nc = min(8000, N)
        hc0 = _coarsen(cur, Nc)
        coarse_cands = []
        n_seeds = 8
        for seed in range(n_seeds):
            if time.process_time() >= hard_end - 2.0:
                break
            rng_s = np.random.default_rng(2000 + seed)
            hc = _block_perturb(hc0, rng_s)
            hc = _lbfgs(hc, np.arange(Nc), maxiter=800, deadline=hard_end,
                        mode="log")
            rc = R_of(hc)
            coarse_cands.append((rc, hc))
        coarse_cands.sort(key=lambda t: -t[0])
        top = coarse_cands[:2]

        for rc, hc in top:
            if time.process_time() >= hard_end - 1.0:
                break
            h = _prolongate(hc, N)
            for beta in (300.0, 800.0, 2000.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs(h, np.arange(N), maxiter=300, deadline=hard_end,
                           mode="sm", beta=beta)
                if R_of(c) >= R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs(h, np.arange(N), maxiter=800, deadline=hard_end,
                           mode="log")
                if R_of(c) >= R_of(h):
                    h = c
            for frac in (0.15, 0.30):
                if time.process_time() >= hard_end - 0.5:
                    break
                win = _peak_window(h, tol=0.999, pad_frac=frac, extra=8)
                c = _lbfgs(h, win, maxiter=400, deadline=hard_end, mode="log")
                if R_of(c) >= R_of(h):
                    h = c
            r = R_of(h)
            _consider(h, r)
        print("experiment R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    # ---------------- Fallback: base-style refinement if time remains ------
    try:
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs(h, np.arange(N), maxiter=250, deadline=hard_end,
                           mode="sm", beta=beta)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs(h, np.arange(N), maxiter=600, deadline=hard_end,
                           mode="log")
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                win = _peak_window(h, tol=0.999, pad_frac=frac, extra=extra)
                c = _lbfgs(h, win, maxiter=400, deadline=hard_end, mode="log")
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= hard_end - 1.0:
                break
        print("fallback R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

