    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(h, pad_frac=frac, extra=8)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_line(h, r, deadline, tag):
    while time.process_time() < deadline - 1.5:
        c = _lbfgs_block(h, np.arange(h.size), maxiter=200, deadline=deadline)
        r2 = R_of(c)
        if r2 > r:
            h, r = c, r2
        c = _lbfgs_block(h, np.arange(h.size), maxiter=200,
                         deadline=deadline, beta=2048.0)
        r2 = R_of(c)
        if r2 > r:
            h, r = c, r2
        h, r = _polish(h, deadline, r,
                       fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=400)
        print("  %s R=%.6f" % (tag, r))
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is None:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        return best

    n0 = start_arr.size
    print("start base R=%.6f N=%d" % (start_r, n0))

    # NEW IDEA: "lift and coarsen" — take the full-resolution start, coarsen
    # it to a moderate mesh (much coarser than full but preserving overall
    # shape), optimize hard at that coarse mesh (cheap per iteration, escapes
    # fine-scale local minima), then prolong back to full resolution and
    # refine. This is the opposite order to before: coarse-first, then
    # fine. It exploits that the objective's landscape is smoother at coarse
    # resolution while the fine result is finally polished at full res.
    base = start_arr.copy()
    base_r = start_r

    # 1) coarse climb on a few mesh sizes, from coarse to fine
    for m in (max(64, n0 // 32), max(256, n0 // 8), max(1024, n0 // 2)):
        if time.process_time() >= deadline - 6.0:
            break
        c = _rescale(_prolong(base, m))
        rc = R_of(c)
        for _ in range(4):
            if time.process_time() >= deadline - 5.0:
                break
            cc = _lbfgs_block(c, np.arange(c.size), maxiter=400,
                              deadline=deadline)
            rcc = R_of(cc)
            if rcc > rc:
                c, rc = cc, rcc
            cc = _lbfgs_block(c, np.arange(c.size), maxiter=300,
                              deadline=deadline, beta=1024.0)
            rcc = R_of(cc)
            if rcc > rc:
                c, rc = cc, rcc
            c, rc = _polish(c, deadline, rc,
                            fracs=(0.5, 0.25, 0.12, 0.06), maxiter=400)
        # prolong back to full res and accept only if it beats base
        up = _rescale(_prolong(c, n0))
        ru = R_of(up)
        if ru > base_r:
            base, base_r = up, ru
        print("  lift m=%d R=%.6f -> full R=%.6f" % (m, rc, base_r))

    # 2) full-resolution refinement
    for _ in range(3):
        if time.process_time() >= deadline - 2.5:
            break
        c = _lbfgs_block(base, np.arange(base.size), maxiter=300,
                         deadline=deadline)
        rc = R_of(c)
        if rc > base_r:
            base, base_r = c, rc
    base, base_r = _polish(base, deadline, base_r,
                           fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=500)

    # 3) final polish loop
    base, base_r = _refine_line(base, base_r, deadline, "final")

    print("best R=%.6f (start %.6f)" % (base_r, start_r))
    base = _rescale(base)

    if start_r >= base_r:
        return {"best": _rescale(start_arr), "alternative": base}
    return {"best": base, "alternative": _rescale(start_arr)}

