    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(h, np.arange(h.size), iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _fold(h, factor):
    """Average-merge adjacent blocks of size `factor` (keeps shape)."""
    n = h.size
    m = n // factor
    if m < 2:
        return h
    return _rescale(h[:m * factor].reshape(m, factor).mean(axis=1))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_R = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_R = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_R
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
        elif cand.size != best.size and r > alt_R:
            alt_best, alt_R = cand.copy(), r

    # ---- Phase A: fold to half resolution, coarsen-optimise, lift back ----
    # The key new idea: the optimum has a self-similar fine structure near the
    # peak. Folding to 1/2, optimising, then lifting back can escape the fine
    # local minimum that the full-resolution L-BFGS cannot.
    if best.size % 2 == 0 and best.size >= 8 and time.process_time() < deadline - 4.0:
        c = _fold(best, 2)
        cR = R_of(c)
        fold_deadline = t0 + budget_seconds * 0.30
        rounds = 0
        while time.process_time() < fold_deadline - 1.0:
            c = _polish_ladder(c, fold_deadline, betas=(1e6, 1e7, 0.0), iters=300)
            c = _peak_ladder(c, fold_deadline, pads=(0.30, 0.20, 0.15, 0.10), iters=400)
            r = R_of(c)
            if r > cR + 1e-14:
                cR = r
            rounds += 1
        print("fold-half rounds=%d R(c)=%.9f" % (rounds, cR))
        # Lift: repeat each value twice, then polish at full resolution
        h_lift = _rescale(np.repeat(c, 2))
        h_lift = _polish_ladder(h_lift, deadline - 2.0, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift2')
        # Alternative lift: linear interpolation (smoother)
        idx = np.arange(best.size)
        h_interp = np.interp(idx / 2.0, np.arange(c.size), c)
        h_interp = _rescale(h_interp)
        h_interp = _polish_ladder(h_interp, deadline - 1.5, betas=(1e6, 1e7), iters=300)
        offer(h_interp, 'lift_interp')

    # ---- Phase B: high-beta sharpening ladder on current best ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')
        ht = _peak_ladder(best, deadline - 0.6, pads=(0.10, 0.06, 0.04), iters=400)
        offer(ht, 'peak')

    # ---- Phase C: fine-grid refinement at 2x resolution ----
    # Keep the 2x parametrisation. This lets the peak sharpen beyond the
    # coarse cell width, which is where the remaining gains live.
    fine_best = None
    fine_R = -1.0

    def offer_fine(cand, tag):
        nonlocal fine_best, fine_R
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > fine_R + 1e-14:
            fine_best, fine_R = cand.copy(), r
            print("FINE R=%.9f (%s, N=%d)" % (fine_R, tag, fine_best.size))

    if time.process_time() < deadline - 6.0:
        h2 = _rescale(np.repeat(best, 2))
        Lc = _knots(best)
        m = int(np.argmax(Lc))
        center = 2 * m
        lo = max(0, center - 1200)
        hi = min(h2.size - 1, center + 1200)
        win = np.arange(lo, hi + 1)
        fine_deadline = deadline - 3.0
        for beta in (1e8, 1e7, 1e6, 0.0):
            if time.process_time() >= fine_deadline - 1.0:
                break
            ht = _lbfgs_block(h2, win, 400, fine_deadline - 0.5, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-14:
                h2 = ht
        h2 = _polish_ladder(h2, fine_deadline - 0.5,
                            betas=(1e7, 1e8, 0.0), iters=250)
        h2 = _peak_ladder(h2, fine_deadline - 0.3, pads=(0.10, 0.06, 0.04), iters=200)
        offer_fine(h2, '2x')

    # ---- Phase D: sub-cell run-shift sweeps on best ----
    def _find_runs(h, min_frac=0.02):
        nz = h > 0
        if not nz.any():
            return []
        thr = min_frac * h.max()
        runs = []
        i, n = 0, h.size
        while i < n:
            if nz[i]:
                j = i
                while j + 1 < n and nz[j + 1]:
                    j += 1
                if h[i:j + 1].sum() >= thr:
                    runs.append((i, j))
                i = j + 1
            else:
                i += 1
        return runs

    def _shift_run(h, i, j, delta):
        prof = h[i:j + 1].copy()
        n = h.size
        out = h.copy()
        out[i:j + 1] = 0.0
        for k in range(prof.size):
            pos = (i + k) + delta
            lo = int(np.floor(pos))
            frac = pos - lo
            if 0 <= lo < n:
                out[lo] += prof[k] * (1.0 - frac)
            if 0 <= lo + 1 < n:
                out[lo + 1] += prof[k] * frac
        return np.clip(out, 0.0, None)

    def _repair(h, i, j, dl, iters=80):
        win = np.arange(max(0, i - 48), min(h.size, j + 49))
        pk = _peak_window(h, 0.10, 64)
        win = np.union1d(win, pk)
        return _lbfgs_block(h, win, iters, dl, beta=1e7)

    sweep_deadline = deadline - 2.0
    rng = np.random.RandomState(12345)
    sweep = 0
    while time.process_time() < sweep_deadline - 1.0:
        runs = _find_runs(best, min_frac=0.02)
        if not runs:
            break
        order = list(range(len(runs)))
        rng.shuffle(order)
        moved = None
        movedR = bestR
        tried = 0
        for ri in order:
            if time.process_time() > sweep_deadline - 1.5:
                break
            i, j = runs[ri]
            for delta in (0.5, -0.5):
                if time.process_time() > sweep_deadline - 1.5:
                    break
                cand = _shift_run(best, i, j, delta)
                if cand.sum() <= 0:
                    continue
                cand = _rescale(cand)
                cand = _repair(cand, i, j, sweep_deadline - 0.5, iters=80)
                r = R_of(cand)
                tried += 1
                if r > movedR + 1e-9:
                    moved, movedR = cand, r
        if moved is not None:
            best, bestR = moved, movedR
            print("sweep %d tried=%d ACCEPT R=%.9f" % (sweep, tried, bestR))
        else:
            print("sweep %d tried=%d no improvement best=%.9f" % (sweep, tried, bestR))

        if sweep % 4 == 3 and time.process_time() < sweep_deadline - 1.0:
            ht = _polish_ladder(best, sweep_deadline - 0.5,
                                betas=(1e7, 1e8, 0.0), iters=200)
            if R_of(ht) > bestR + 1e-14:
                best, bestR = ht, R_of(ht)
            win = _peak_window(best, 0.06, 128)
            ht = _lbfgs_block(best, win, 300, sweep_deadline - 0.5, beta=1e7)
            if R_of(ht) > bestR + 1e-14:
                best, bestR = ht, R_of(ht)
            print("sweep %d post-ladder R=%.9f" % (sweep, bestR))
        sweep += 1

    # ---- Phase E: final high-beta polish + peak ladder ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 0.0), iters=350)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.10, 0.06, 0.04), iters=400)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    # ---- Choose overall best ----
    overall = best
    overallR = bestR
    if fine_best is not None and fine_R > overallR + 1e-14:
        overall, overallR = fine_best, fine_R
        print("using FINE result R=%.9f N=%d" % (overallR, overall.size))

    print("final R=%.9f (start %.9f, N=%d)" % (overallR, start_R, overall.size))

    result = {"best": overall}
    if fine_best is not None and fine_best.size != overall.size:
        result["alternative"] = fine_best
    elif alt_best is not None and alt_best.size != overall.size:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline,
                        beta=beta, tie=tie)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    """Detect if h is a p-fold repeat of a shorter base; return (base, p)."""
    n = h.size
    for p in (64, 32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-10, atol=1e-14):
            return c, p
    return h, 1


def _smooth_local(h, deadline, iters=400):
    """Coordinate-descent style: optimize small sliding windows of heights."""
    n = h.size
    best = h.copy()
    bestR = R_of(best)
    win = max(32, min(512, n // 64))
    step = max(8, win // 4)
    starts = list(range(0, n - win + 1, step))
    # prioritize near-peak windows
    Lf = _knots(best)
    mx = Lf.max()
    order = sorted(starts, key=lambda s: -np.max(Lf[s:s + win]))
    for s in order:
        if time.process_time() >= deadline - 0.5:
            break
        idx = np.arange(s, min(n, s + win))
        ht = _lbfgs_block(best, idx, iters, deadline - 0.3, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Approach 1: work on the base of a periodic repetition ----
    # If best is a p-fold repeat, optimize the short base at higher resolution,
    # then re-expand.  This is much cheaper per gradient eval and lets us
    # squeeze more out of the same effective shape.
    base_h, p = _detect_repeat(best)
    if p > 1:
        m = base_h.size
        print("detected p=%d repeat, base m=%d" % (p, m))
        # Optimize the base directly (R of repeated == R of base scaled).
        hb = _rescale(base_h.copy())
        rb = R_of(hb)
        # expand to a finer mesh (finer N) to find more structure
        end1 = t0 + budget_seconds * 0.55
        # try base at a few resolutions
        for mult in (p, 2 * p, 4 * p):
            if time.process_time() >= end1 - 2.0:
                break
            # take base and upsample by 'mult' (piecewise constant)
            hup = np.repeat(hb, mult)
            hu = _rescale(hup)
            ru = R_of(hu)
            # now optimize the full upsample briefly (peak window + tie)
            ht = _peak_ladder(hu, min(end1 - 1.0, time.process_time() + 8.0),
                              pads=(0.10, 0.05), iters=300)
            rt = R_of(ht)
            print("  mult=%d R=%.9f (base %.9f)" % (mult, rt, ru))
            if rt > bestR + 1e-15:
                best, bestR = ht.copy(), rt
                hb = _rescale(ht[::mult][:m].copy()) if ht.size >= m * mult else hb

    # ---- Approach 2: global tie optimization ----
    end2 = t0 + budget_seconds * 0.78
    if time.process_time() < end2 - 3.0:
        ht = _lbfgs_all_pos(best, 500, min(end2 - 1.0,
                                           time.process_time() + budget_seconds * 0.15),
                            tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("global tie ACCEPT R=%.9f" % bestR)

    # ---- Approach 3: moving-window tie polish ----
    end3 = t0 + budget_seconds * 0.93
    if time.process_time() < end3 - 2.0:
        ht = _smooth_local(best, end3 - 1.0, iters=300)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("window ACCEPT R=%.9f" % bestR)

    # ---- Approach 4: peak ladder + final all-pos ----
    end4 = t0 + budget_seconds * 0.99
    if time.process_time() < end4 - 2.0:
        ht = _peak_ladder(best, end4 - 1.0, pads=(0.06, 0.03),
                          iters=300)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.9f" % bestR)

    if time.process_time() < end4 - 1.0:
        ht = _lbfgs_all_pos(best, 300, end4 - 0.5, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _block_mean(h, B):
    return h.reshape(-1, B).mean(axis=1)


def _block_repeat(c, B):
    return np.repeat(c, B)


def _opt_block(c0, B, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c0
    c = np.clip(c0, 0, None)
    if c.sum() <= 0:
        return c0
    n = c.size

    def f(x):
        cc = np.clip(x, 0.0, None)
        hh = np.repeat(cc, B)
        val, g = _fun_grad_tie(hh)
        gc = g.reshape(n, B).sum(axis=1)
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.clip(res.x, 0.0, None)


def _opt_asym(c0, B, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return _block_repeat(c0, B)
    n = c0.size
    half = B // 2
    theta0 = np.zeros(n)

    def build(theta):
        alpha = 1.0 / (1.0 + np.exp(-np.clip(theta, -30, 30)))
        h = np.empty(n * B)
        h1 = (c0 * 2.0 * alpha)
        h2 = (c0 * 2.0 * (1.0 - alpha))
        hh = h.reshape(n, B)
        hh[:, :half] = h1[:, None]
        hh[:, half:] = h2[:, None]
        return h

    def f(theta):
        h = build(theta)
        val, g = _fun_grad_tie(h)
        gh = g.reshape(n, B)
        alpha = 1.0 / (1.0 + np.exp(-np.clip(theta, -30, 30)))
        g1 = gh[:, :half].sum(axis=1)
        g2 = gh[:, half:].sum(axis=1)
        dval_dalpha = g1 * (2.0 * c0) + g2 * (-2.0 * c0)
        dalpha_dtheta = alpha * (1.0 - alpha)
        return val, dval_dalpha * dalpha_dtheta

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, theta0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return _block_repeat(c0, B)
    if res is None:
        return _block_repeat(c0, B)
    return build(res.x)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Phase 1: block-mean coarsen ----
    B = 32
    if N % B != 0:
        for cand in (32, 16, 8, 4, 2, 1):
            if N % cand == 0:
                B = cand
                break
    Nc = N // B
    c0 = _block_mean(best, B)
    h_init = _rescale(_block_repeat(c0, B))
    c0 = _block_mean(h_init, B)
    R_init = R_of(h_init)
    print("block-mean Nc=%d (B=%d) R=%.9f" % (Nc, B, R_init))

    best_c = c0.copy()
    best_h = h_init.copy()
    best_hR = R_init

    # ---- Phase 2: coarse L-BFGS ----
    env_end = t0 + budget_seconds * 0.50
    c_opt = _opt_block(best_c, B, 400, env_end)
    h_opt = _rescale(_block_repeat(c_opt, B))
    R_opt = R_of(h_opt)
    print("coarse L-BFGS R=%.9f (init %.9f)" % (R_opt, R_init))
    if R_opt > best_hR:
        best_c = c_opt
        best_h = h_opt
        best_hR = R_opt

    # ---- Phase 3: asymmetric split ----
    if time.process_time() < env_end - 2.0 and B >= 2:
        h_asym = _opt_asym(best_c, B, 200, env_end)
        h_asym = _rescale(h_asym)
        R_asym = R_of(h_asym)
        print("asymmetric split R=%.9f" % R_asym)
        if R_asym > best_hR:
            best_h = h_asym
            best_hR = R_asym
            best_c = _block_mean(h_asym, B)

    # ---- Phase 4: peak/tie polish ladder ----
    cand = best_h.copy()
    candR = best_hR
    peak_end = t0 + budget_seconds * 0.78
    for beta in (1e5, 1e7):
        if time.process_time() >= peak_end - 2.0:
            break
        for pad in (0.10, 0.06, 0.03):
            if time.process_time() >= peak_end - 1.5:
                break
            win = _peak_window(cand, pad_frac=pad, extra=128)
            ht = _lbfgs_block(cand, win, 300, peak_end - 0.5, beta=beta)
            r = R_of(ht)
            if r > candR + 1e-15:
                cand, candR = ht, r
    print("after peak ladder R=%.9f" % candR)

    # ---- Phase 5: full tie/argmax polish ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(cand, 500, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("tie ACCEPT R=%.9f ties=%d" % (candR, _tie_count(cand)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(cand, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > candR + 1e-15:
            cand, candR = h_t, r_t
            print("argmax ACCEPT R=%.9f" % candR)

    f01, f1, f5 = _nearmax_fracs(cand)
    print("candidate R=%.9f near 0.1%%/1%%/5%%=%.4f/%.4f/%.4f"
          % (candR, f01, f1, f5))

    # ---- Phase 6: NEW — split-free direct fine-grid refinement from start ----
    # Key new idea: rather than only chaining through a coarse block lift,
    # directly refine the *original* full-resolution candidate with
    # alternating beta-ladder passes that include a wide window and the
    # whole array, which can escape the block-mean local basin.
    fd2 = t0 + budget_seconds * 0.985
    # Start a fresh polish from the *original start* too, in case its basin
    # differs from the block-mean basin.
    if start is not None and time.process_time() < fd2 - 4.0:
        alt = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        altR = R_of(alt)
        # one round of tie-polish on the raw start
        alt_t = _lbfgs_all_pos(alt, 400, fd2 - 2.0, tie=True)
        r_at = R_of(alt_t)
        if r_at > altR:
            alt, altR = alt_t, r_at
        # wide-window beta smoothing near peak
        if time.process_time() < fd2 - 1.5:
            win = _peak_window(alt, pad_frac=0.20, extra=256)
            alt_b = _lbfgs_block(alt, win, 400, fd2 - 0.8, beta=3e6)
            r_ab = R_of(alt_b)
            if r_ab > altR:
                alt, altR = alt_b, r_ab
        print("raw-start polish R=%.9f" % altR)
        if altR > candR + 1e-15:
            cand, candR = alt, altR
            print("RAW-START WINS R=%.9f" % candR)

    if candR > bestR + 1e-15:
        best, bestR = cand, candR
        print("BLOCK WINS R=%.9f (start %.9f)" % (bestR, startR))
        result = {"best": best}
    else:
        print("no gain (cand %.9f vs start %.9f); returning alternative"
              % (candR, startR))
        result = {"best": best, "alternative": cand}

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline,
                        beta=beta, tie=tie)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 400, deadline - 0.5, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 300, deadline - 0.5, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    for a in pos:
        left = pos[pos < a]
        right = pos[pos > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        cands.append((-h[a] * g[a], int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = [int(z) for z in zeros
              if (z - 1 >= 0 and posmask[z - 1]) or
                 (z + 1 < n and posmask[z + 1])]
    if births:
        val = 0.5 * mean_pos
        for z in births:
            cands.append((val * g[z], z, -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 32:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        h2[a] = 0.5 * h2[pos].mean() if pos.any() else 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    raw_delta = best_r - bestR
    stats['best_raw'] = max(stats['best_raw'], raw_delta)

    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _build_target(h, s0, s1):
    n = h.size
    Lf = _knots(h)
    M = Lf.max()
    s = h.sum()
    gk = np.zeros(2 * n + 1, dtype=float)
    lo = 2 * s0
    hi = 2 * s1
    if hi <= lo:
        return gk
    span = hi - lo
    ramp = max(1, int(0.035 * span))
    gk[lo:hi + 1] = 1.0
    if ramp > 1:
        t = np.linspace(0.0, np.pi, ramp)
        rampup = 0.5 * (1.0 - np.cos(t))
        gk[lo:lo + ramp] *= rampup
        gk[hi - ramp + 1:hi + 1] *= rampup[::-1]
    cur_max = gk.max()
    if cur_max <= 0:
        return gk
    gk *= (M / cur_max)
    cur_sum = gk.sum()
    if cur_sum > 0:
        gk *= (s * s / cur_sum)
    return gk


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


def _gn_flat(best, deadline):
    n = best.size
    s0, s1 = _active_support(best)
    if s1 <= s0:
        return best, R_of(best)
    h = np.clip(best, 0, None).astype(float)
    if h.sum() <= 0:
        return best, R_of(best)
    lo = 2 * s0
    hi = 2 * s1
    if hi <= lo:
        return best, R_of(best)
    j_lo = max(0, lo - 1)
    j_hi = min(2 * n - 2, hi - 1)
    if j_hi < j_lo:
        return best, R_of(best)

    best_h = h.copy()
    bestR = R_of(h)
    gk = _build_target(h, s0, s1)
    g_t = gk[lo:hi + 1].copy()

    def residual(hh):
        Lf = _knots(hh)
        return Lf[lo:hi + 1] - g_t

    def J(hh, d):
        c = fftconvolve(hh, d)
        return 2.0 * c[j_lo:j_hi + 1]

    def JT(hh, v):
        vp = np.zeros(2 * n - 1, dtype=float)
        vp[j_lo:j_hi + 1] = v
        return 2.0 * np.correlate(vp, hh, mode='valid')[:n]

    for outer in range(15):
        if time.process_time() >= deadline - 15.0:
            break
        r = residual(h)
        rnorm = np.linalg.norm(r)
        JTr = JT(h, r)
        lam = 1e-6 * np.linalg.norm(JTr)
        if lam <= 0:
            lam = 1e-12
        d = np.zeros(n, dtype=float)
        res = -JTr.copy()
        p = res.copy()
        rs_old = np.dot(res, res)
        for _ in range(20):
            if time.process_time() >= deadline - 15.0:
                break
            Jp = J(h, p)
            Ap = JT(h, Jp) + lam * p
            pAp = np.dot(p, Ap)
            if pAp <= 0:
                break
            alpha = rs_old / pAp
            d += alpha * p
            res -= alpha * Ap
            rs_new = np.dot(res, res)
            if rs_new < 1e-30 * rs_old:
                break
            p = res + (rs_new / rs_old) * p
            rs_old = rs_new
        alpha_step = 1.0
        accepted = False
        for _ in range(12):
            h_new = np.clip(h + alpha_step * d, 0.0, None)
            if h_new.sum() <= 0:
                alpha_step *= 0.5
                continue
            r_new = residual(h_new)
            if np.linalg.norm(r_new) < rnorm:
                h = h_new
                accepted = True
                break
            alpha_step *= 0.5
        if not accepted:
            break
        if outer % 3 == 2:
            if time.process_time() < deadline - 15.0:
                hp = _lbfgs_all(h, 40, deadline - 15.0, beta=0.0)
                rp = R_of(hp)
                if rp > bestR + 1e-13:
                    best_h = hp.copy()
                    bestR = rp
    rh = R_of(h)
    if rh > bestR + 1e-13:
        best_h = h.copy()
        bestR = rh
    return best_h, bestR


def _densify(best, bestR, deadline):
    if time.process_time() >= deadline - 2.0:
        return best, bestR
    n = best.size
    if 2 * n > 900000:
        return best, bestR
    h2 = _rescale(np.repeat(best, 2))
    r2 = R_of(h2)
    if r2 > bestR + 1e-13:
        best, bestR = h2, r2
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all(best, 400, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-12:
            best, bestR = ht, r
    return best, bestR


def _smooth_perturb(h, scale, rng):
    """Add small smooth perturbation to escape a local basin."""
    n = h.size
    k = max(4, n // 200)
    kern = np.exp(-0.5 * (np.arange(-k, k + 1) / (k / 2.0)) ** 2)
    kern /= kern.sum()
    noise = rng.standard_normal(n) * scale * (h.mean() + 1e-12)
    pert = np.convolve(noise, kern, mode='same')
    h2 = np.clip(h + pert, 0.0, None)
    if h2.sum() <= 0:
        return h
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(1234567)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # Densify resolution then polish (new idea: allows finer shape details).
    if time.process_time() < deadline - 20.0:
        try:
            cand, candR = _densify(best, bestR, deadline - 18.0)
            print("densify raw R=%.7f (N=%d)" % (candR, cand.size))
            if time.process_time() < deadline - 15.0:
                cand2, candR2 = run_cycle(cand, candR, deadline - 13.0)
                if candR2 > candR:
                    cand, candR = cand2, candR2
                print("densify polished R=%.7f" % candR)
            if candR > altR:
                alt_cand, altR = cand.copy(), candR
            if candR > bestR + 1e-13:
                best, bestR = cand.copy(), candR
        except Exception as e:
            print("densify failed: %s" % e)

    # Random smooth perturbations to escape local basin, then polish.
    if time.process_time() < deadline - 12.0:
        try:
            for scale in (0.02, 0.05, 0.1):
                if time.process_time() >= deadline - 10.0:
                    break
                hp = _smooth_perturb(best, scale, rng)
                hp = _lbfgs_all(hp, 200, deadline - 10.0, beta=1e7)
                hp = _lbfgs_all(hp, 200, deadline - 10.0, tie=True)
                rp = R_of(hp)
                print("perturb scale=%.2f R=%.7f" % (scale, rp))
                if rp > altR:
                    alt_cand, altR = hp.copy(), rp
                if rp > bestR + 1e-13:
                    best, bestR = hp.copy(), rp
        except Exception as e:
            print("perturb failed: %s" % e)

    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f" % bestR)

    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    while time.process_time() < deadline - 6.0:
        best, bestR = _dip_moves(best, bestR, deadline - 6.0, stats)
    print("dip loop: dips=%d accepted=%d R=%.7f" %
          (stats['dips'], stats['accepted'], bestR))

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 0.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    work = best.copy()

    # Smooth-max continuation with a tie-aware gradient: this is the key
    # change. The start already has a broad, nearly-flat peak, so using
    # the max gradient (or a very steep beta) starves the many knots near
    # the maximum of gradient signal. Instead we scan beta downward while
    # the function has *already* broadened the peak, letting the whole
    # near-max region move coherently.
    betas = [1e3, 3e2, 1e2, 30, 10, 3, 1, 0.3]
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        cap = min(deadline - 0.3, time.process_time() + 5.0)
        hp = _lbfgs_block(work, np.arange(work.size), 500, cap, beta=beta)
        rp = R_of(hp)
        work = hp
        print("  beta=%.0e R=%.9f bestR=%.9f" % (beta, rp, bestR))
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp

    # Peak-window polish at several widths, restarted each time from best.
    fracs = [0.03, 0.06, 0.10, 0.15, 0.25, 0.40, 0.60]
    for frac in fracs:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.3, time.process_time() + 3.0)
        hb = _lbfgs_block(best, free, 400, cap, beta=0.0)
        rb = R_of(hb)
        print("    block frac=%.2f R=%.9f" % (frac, rb))
        if rb > bestR + 1e-15:
            best, bestR = hb.copy(), rb

    # Final all-vector exact-R polish, repeatedly with shrinking betas in
    # a tight loop until no gain is found or the deadline is near.
    while time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 5.0)
        hp = _lbfgs_block(best, np.arange(best.size), 500, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp.copy(), rp
            print("  hard R=%.9f" % bestR)
        else:
            # try one more small-beta pass to escape
            cap = min(deadline - 0.3, time.process_time() + 3.0)
            hp2 = _lbfgs_block(best, np.arange(best.size), 300, cap, beta=0.5)
            rp2 = R_of(hp2)
            if rp2 > bestR + 1e-14:
                best, bestR = hp2.copy(), rp2
                print("  hard(beta=0.5) R=%.9f" % bestR)
            else:
                break

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    return _lbfgs_block(h0, np.arange(np.asarray(h0).size), maxiter, deadline, beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _report(tag, h, R):
    print("%s R=%.7f N=%d" % (tag, R, h.size))


def _hop(h, bestR, deadline, rng):
    n = h.size
    if n < 8:
        return h, bestR
    wlen = int(rng.integers(max(8, n // 20), max(16, n // 4)))
    wlen = min(wlen, n)
    lo = int(rng.integers(0, n - wlen + 1))
    hi = lo + wlen
    hp = h.copy()
    amp = rng.uniform(0.02, 0.15)
    noise = 1.0 + amp * rng.standard_normal(wlen)
    hp[lo:hi] = np.clip(hp[lo:hi] * noise, 0.0, None)
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 64
    flo = max(0, lo - halo); fhi = min(n, hi + halo)
    free = np.arange(flo, fhi)
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 200, deadline - 0.5, beta=1e7)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if time.process_time() < deadline - 0.5:
        win = _peak_window(hp, tol=0.95, pad_frac=0.5, extra=512)
        if win.size <= 40000:
            ht = _lbfgs_block(hp, win, 250, deadline - 0.5, beta=0.0)
            rt = R_of(ht)
            if rt > rp:
                hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def _mutate(h, bestR, deadline, rng):
    n = h.size
    hp = h.copy()
    blen = int(rng.integers(max(8, n // 40), max(16, n // 8)))
    blen = min(blen, n)
    lo = int(rng.integers(0, n - blen + 1))
    hi = lo + blen
    hp[lo:hi] = 0.0
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 128
    free = np.arange(max(0, lo - halo), min(n, hi + halo))
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 300, deadline - 0.5, beta=0.0)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def _smoothed_anneal(h, bestR, deadline, rng):
    """Continuation: soften the max via beta smoothing then sharpen, over the
    peak window -- lets the profile reshape past a local max."""
    if time.process_time() >= deadline - 1.0:
        return h, bestR
    win = _peak_window(h, tol=0.98, pad_frac=0.6, extra=1024)
    if win.size > 60000:
        return h, bestR
    cur, curR = h.copy(), bestR
    # coarse-to-fine beta schedule (anneal towards true max)
    for beta in (1e5, 1e6, 1e7, 1e8):
        if time.process_time() >= deadline - 0.8:
            break
        ht = _lbfgs_block(cur, win, 150, deadline - 0.8, beta=beta)
        rt = R_of(ht)
        if rt > curR - 1e-9:
            cur, curR = ht, rt
    if curR > bestR + 1e-13:
        return cur, curR
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(20250101)

    # Stage (a): full polish.
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 1.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(a)", best, bestR)

    # Stage (b): peak-window refinements at multiple scales.
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        if win.size > 40000:
            continue
        ht = _lbfgs_block(best, win, 250, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(b)", best, bestR)

    # Stage (c): alternating hop / mutate / anneal with acceptance.
    n_hops = 0
    n_accept = 0
    while time.process_time() < deadline - 1.2:
        n_hops += 1
        mode = n_hops % 4
        if mode == 0:
            hnew, rnew = _mutate(best, bestR, deadline - 1.2, rng)
        elif mode == 1:
            hnew, rnew = _smoothed_anneal(best, bestR, deadline - 1.2, rng)
        else:
            hnew, rnew = _hop(best, bestR, deadline - 1.2, rng)
        if rnew > bestR + 1e-13:
            best, bestR = hnew, rnew
            n_accept += 1
        if n_hops > 500:
            break
    print("(c) hops=%d accepted=%d" % (n_hops, n_accept))
    _report("(c)", best, bestR)

    # Stage (d): final broad polish.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 500, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        hs = _seed_zeros(best)
        ht = _lbfgs_all_pos(hs, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0.0, None)
    Lp = Lc ** p
    S = Lp.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = S ** (1.0 / p)
    if sm <= 0:
        return _fun_grad(h)
    w = Lc ** (p - 1) / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h, eta, tau):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    d = np.clip(tau * M - Lf, 0.0, None)
    F = float(np.sum(d * d))
    n = max(1, Lf.size)
    gLf = -dq / num
    gLf[int(np.argmax(Lf))] += 1.0 / M
    gLf += -(2.0 * eta / (M * M * n)) * d
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + eta * F / (M * M * n)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_all_pos_p(h0, maxiter, deadline, p):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_pnorm(hh, p)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder_p(h, deadline, p, pads=(0.08, 0.05, 0.03), iters=250):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_polish(h, deadline, iters=400):
    # tie-aware polish: spread gradient over all near-max knots to encourage
    # a flattened plateau, which is what the true optimum wants
    ht = _lbfgs_block(h, np.arange(h.size), iters, deadline, tie=True)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, nearmax50=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best, 0.95),
             _nearmax_frac(best, 0.5)))

    # ---- NEW: tie-aware plateau polish ----
    # The optimum should have f*f flat near its max, so all near-max knots
    # share the gradient. This directly targets the plateau structure.
    tie_deadline = t0 + budget_seconds * 0.35
    ht = _tie_polish(best, tie_deadline, iters=600)
    r = R_of(ht)
    print("tie R=%.9f nm95=%.4f" % (r, _nearmax_frac(ht, 0.95)))
    if r > bestR + 1e-14:
        best, bestR = ht.copy(), r
        print("tie NEW BEST R=%.9f" % bestR)

    # ---- beta-ladder on top of the tie polish ----
    beta_deadline = t0 + budget_seconds * 0.55
    for beta in (1e3, 1e4, 1e5, 1e6, 1e7):
        if time.process_time() >= beta_deadline - 1.0:
            break
        dp = min(beta_deadline, time.process_time() + budget_seconds * 0.04)
        ht = _lbfgs_all_pos(best, 300, dp, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("beta=%.0e NEW BEST R=%.9f nm95=%.4f"
                  % (beta, bestR, _nearmax_frac(best, 0.95)))

    # ---- p-norm smoothing ladder ----
    pnorm_deadline = t0 + budget_seconds * 0.72
    for p in (4, 8, 16, 32, 64, 128):
        if time.process_time() >= pnorm_deadline - 1.0:
            break
        dp = min(pnorm_deadline, time.process_time() + budget_seconds * 0.03)
        ht = _lbfgs_all_pos_p(best, 300, dp, p)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("pnorm p=%d NEW BEST R=%.9f" % (p, bestR))

    if time.process_time() < pnorm_deadline - 1.0:
        ht = _peak_ladder_p(best, pnorm_deadline, 128,
                            pads=(0.08, 0.05, 0.03), iters=250)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("pnorm peak NEW BEST R=%.9f" % bestR)

    # ---- final hard-max polish with tie-aware alternation ----
    fd = deadline
    for _ in range(3):
        if time.process_time() >= fd - 1.0:
            break
        ht = _tie_polish(best, min(fd, time.process_time() + budget_seconds * 0.04),
                         iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        if time.process_time() >= fd - 1.0:
            break
        ht = _lbfgs_all_pos(best, 400, min(fd, time.process_time() + budget_seconds * 0.04),
                            beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL beta0 ACCEPT R=%.9f" % bestR)

    if time.process_time() < fd - 0.5:
        ht = _peak_ladder(best, fd, pads=(0.05, 0.03), iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("FINAL peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, "
          "nearmax50=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best, 0.95), _nearmax_frac(best, 0.5)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        start = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[start:start + L] *= fac
    return c2


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _trust_newton(c0, deadline, method='trust-ncg', init_radius=1e-3):
    if time.process_time() >= deadline - 0.5:
        return c0
    c0 = np.clip(c0, 1e-30, None)
    v0 = np.sqrt(c0)

    def fg(v):
        c = v * v
        val, g = _fun_grad_tie(c)
        return val, 2.0 * v * g

    def hessp(v, w):
        eps = 1e-6 * (1.0 + np.linalg.norm(v))
        vp = v + eps * w
        vm = v - eps * w
        cp = vp * vp
        cm = vm * vm
        _, gp = _fun_grad_tie(cp)
        _, gm = _fun_grad_tie(cm)
        gvp = 2.0 * vp * gp
        gvm = 2.0 * vm * gm
        return (gvp - gvm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg, v0, jac=True, method=method, hessp=hessp,
                       callback=cb,
                       options={'maxiter': 300,
                                'initial_trust_radius': init_radius,
                                'max_trust_radius': 0.5,
                                'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None or not np.all(np.isfinite(res.x)):
        return c0
    c = res.x * res.x
    return _rescale(c)


# ---------- multi-resolution homotopy helpers ----------
def _coarse(c_in, m):
    """Piecewise-linear interpolation of c_in onto m uniform samples over [0, n_c]."""
    n = c_in.size
    if m == n:
        return c_in.copy()
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 * (n / m)
    xi = np.arange(n, dtype=float) + 0.5
    return np.interp(x, xi, c_in)


def _prolong(c_coarse, m_out):
    """Piecewise-linear interpolation of c_coarse onto m_out uniform samples."""
    m = c_coarse.size
    if m_out == m:
        return c_coarse.copy()
    x = np.linspace(0.0, m, m_out, endpoint=False) + 0.5 * (m_out / m)
    xi = np.arange(m, dtype=float) + 0.5
    return np.interp(x, xi, c_coarse)


def _polish_c(c, p, maxiter, deadline, tie=True):
    """Polish c at fixed resolution; return (c, R(repeat(c,p)))."""
    if time.process_time() >= deadline - 0.3:
        return c, R_of(np.repeat(c, p))
    h = _rescale(np.repeat(c, p))
    h2 = _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=tie)
    c2 = h2.reshape(-1, p).mean(axis=1)
    # verify repeat structure preserved
    hr = np.repeat(c2, p)
    return c2, R_of(hr)


def _vcycle(best, bestR, p, c, deadline, levels):
    """One V-cycle over levels; returns (best, bestR, c)."""
    n_c = c.size
    # descend: c at n_c already; go down
    coarse_list = [(n_c, c.copy())]
    cur = c
    for m in levels[1:]:
        cur = _coarse(cur, m)
        coarse_list.append((m, cur.copy()))
    # polish at coarsest
    m, cc = coarse_list[-1]
    cc, r = _polish_c(cc, p, 80, min(deadline, time.process_time() + 3.0))
    coarse_list[-1] = (m, cc)
    print("  vcycle level=%d R=%.9f" % (m, r))
    if r > bestR + 1e-15:
        best = _rescale(np.repeat(cc, p)); bestR = r
    # ascend
    for i in range(len(coarse_list) - 2, -1, -1):
        m_out, _ = coarse_list[i]
        cc = _prolong(cc, m_out)
        cc, r = _polish_c(cc, p, 100,
                          min(deadline, time.process_time() + 4.0))
        coarse_list[i] = (m_out, cc)
        print("  vcycle level=%d R=%.9f" % (m_out, r))
        if r > bestR + 1e-15:
            best = _rescale(np.repeat(cc, p)); bestR = r
    return best, bestR, cc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- Phase V: multi-resolution V-cycles (60% of remaining time) ----
    v_end = t0 + (deadline - t0) * 0.60 + t0
    if p > 1 and c.size >= 4 and time.process_time() < v_end - 3.0:
        n_c = c.size
        # build level ladder: n_c, ~n_c/4, ~n_c/16
        levels = [n_c]
        m = n_c
        while len(levels) < 3 and m > 8:
            m = max(8, m // 4)
            if m >= levels[-1]:
                break
            levels.append(m)
        print("vcycle levels=%s" % levels)
        # verify start R(repeat) matches
        rrep = R_of(np.repeat(c, p))
        print("vcycle start R(repeat)=%.9f (best %.9f)" % (rrep, bestR))

        cycle = 0
        while time.process_time() < v_end - 3.0:
            cycle += 1
            print("vcycle cycle=%d" % cycle)
            best, bestR, c = _vcycle(best, bestR, p, c, v_end, levels)
            print("vcycle cycle=%d done bestR=%.9f" % (cycle, bestR))
            if cycle >= 2 and time.process_time() > v_end - 6.0:
                break

    # ---- Phase A: coarse jitter + repolish ----
    a_end = t0 + (deadline - t0) * 0.72 + t0
    if time.process_time() < a_end - 0.5:
        rng = np.random.default_rng(12345)
        c_best = c.copy()
        cR = R_of(np.repeat(c_best, p)) if p > 1 else R_of(c_best)
        accepted = 0
        rounds = 0
        while time.process_time() < a_end - 0.5:
            rounds += 1
            cj = _jitter(c_best, rng)
            cj = _lbfgs_log(cj, 150, min(a_end - 0.3,
                                         time.process_time() + 1.5))
            rj = R_of(np.repeat(cj, p)) if p > 1 else R_of(cj)
            if rj > cR + 1e-15:
                c_best, cR = cj, rj
                accepted += 1
        print("PhaseA rounds=%d accepted=%d cR=%.9f" % (rounds, accepted, cR))
        if cR > bestR + 1e-15:
            best = _rescale(np.repeat(c_best, p)) if p > 1 else _rescale(c_best)
            bestR = cR
            c = c_best

    # ---- Phase B: interpolating lift ladder ----
    b_end = t0 + (deadline - t0) * 0.82 + t0
    cur = c.copy()
    curR = R_of(np.repeat(cur, p)) if p > 1 else R_of(cur)
    for step in range(4):
        if time.process_time() >= b_end - 1.0:
            break
        if cur.size * 2 > 300000:
            break
        lifted = _interp_lift(cur)
        lifted = _lbfgs_log(lifted, 200, min(b_end - 0.5,
                                             time.process_time() + 6.0))
        rl = R_of(lifted)
        win = _peak_window(lifted, pad_frac=0.03, extra=64)
        polished = _lbfgs_block(lifted, win, 200,
                                min(b_end - 0.3,
                                    time.process_time() + 3.0), tie=True)
        rp = R_of(polished)
        if rp > rl:
            lifted, rl = polished, rp
        print("lift step=%d n=%d R=%.9f (cur %.9f)" % (step, lifted.size, rl, curR))
        if rl > curR + 1e-15:
            cur, curR = lifted, rl
        else:
            break

    # ---- Phase C: lift back to full N and peak polish ----
    n_target = best.size
    if cur.size != n_target:
        if n_target % cur.size == 0:
            fac = n_target // cur.size
            full = np.repeat(cur, fac)
        else:
            full = np.interp(np.linspace(0, cur.size - 1, n_target),
                             np.arange(cur.size), cur)
    else:
        full = cur
    full = _rescale(full)
    rfull = R_of(full)
    if rfull > bestR + 1e-15:
        best, bestR = full.copy(), rfull
        print("lift ACCEPT R=%.9f" % bestR)

    # ---- Phase D: trust-region Newton on compressed quotient ----
    d_end = t0 + (deadline - t0) * 0.90 + t0
    if time.process_time() < d_end - 1.0:
        _, c_now = _detect_repeat(best)
        if c_now.size == best.size:
            n = min(4096, best.size)
            if best.size % n == 0:
                c_now = best.reshape(-1, best.size // n).mean(axis=1)
            else:
                c_now = np.interp(np.linspace(0, best.size - 1, n),
                                  np.arange(best.size), best)
        c_now = _rescale(np.clip(c_now, 1e-30, None))
        cR0 = R_of(c_now)
        print("Newton start n_c=%d cR=%.9f" % (c_now.size, cR0))
        c_new = _trust_newton(c_now, d_end, 'trust-ncg', 1e-3)
        cRn = R_of(c_new)
        if cRn <= cR0 + 1e-15 and time.process_time() < d_end - 1.0:
            c_new2 = _trust_newton(c_now, d_end, 'trust-krylov', 1e-2)
            if R_of(c_new2) > cRn:
                c_new, cRn = c_new2, R_of(c_new2)
        print("Newton end cR=%.9f (was %.9f)" % (cRn, cR0))
        if cRn > cR0 + 1e-15:
            if best.size % c_new.size == 0:
                fac = best.size // c_new.size
                full2 = np.repeat(c_new, fac)
            else:
                full2 = np.interp(np.linspace(0, c_new.size - 1, best.size),
                                  np.arange(c_new.size), c_new)
            full2 = _rescale(full2)
            rf = R_of(full2)
            print("Newton lift R(full)=%.9f" % rf)
            if rf > bestR + 1e-15:
                best, bestR = full2.copy(), rf
                print("Newton ACCEPT R=%.9f" % bestR)

    # ---- Phase E: final peak polish ----
    c_end = deadline
    for pad in (0.06, 0.03, 0.015):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= c_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(c_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_mix(h, w, P):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    wP = w[P]
    LP = Lf[P]
    M = float(np.dot(wP, LP))
    if M <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    gLf[P] += wP / M
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_mix(h0, w, P, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_mix(hh, w, P)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        start = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[start:start + L] *= fac
    return c2


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _trust_newton(c0, deadline, method='trust-ncg', init_radius=1e-3):
    if time.process_time() >= deadline - 0.5:
        return c0
    c0 = np.clip(c0, 1e-30, None)
    v0 = np.sqrt(c0)

    def fg(v):
        c = v * v
        val, g = _fun_grad_tie(c)
        return val, 2.0 * v * g

    def hessp(v, w):
        eps = 1e-6 * (1.0 + np.linalg.norm(v))
        vp = v + eps * w
        vm = v - eps * w
        cp = vp * vp
        cm = vm * vm
        _, gp = _fun_grad_tie(cp)
        _, gm = _fun_grad_tie(cm)
        gvp = 2.0 * vp * gp
        gvm = 2.0 * vm * gm
        return (gvp - gvm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg, v0, jac=True, method=method, hessp=hessp,
                       callback=cb,
                       options={'maxiter': 300,
                                'initial_trust_radius': init_radius,
                                'max_trust_radius': 0.5,
                                'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None or not np.all(np.isfinite(res.x)):
        return c0
    c = res.x * res.x
    return _rescale(c)


def _phase_mix(best, bestR, deadline):
    """Dual (multiplicative ascent on w) + inner exact-gradient L-BFGS."""
    h = best.copy()
    Lf = _knots(h)
    mx = Lf.max()
    P = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    if P.size == 0:
        P = np.array([int(np.argmax(Lf))])
    w = np.full(Lf.size, 1e-3)
    w[P] = 1.0
    w /= w.sum()
    eta = 2.0
    it = 0
    while time.process_time() < deadline - 0.5:
        it += 1
        # inner: L-BFGS on mixture objective
        sub_deadline = min(deadline - 0.3, time.process_time() + 4.0)
        h_new = _lbfgs_mix(h, w, P, 80, sub_deadline)
        # recompute L, M
        Lf = _knots(h_new)
        mx = Lf.max()
        M = float(np.dot(w[P], Lf[P]))
        if M <= 0:
            break
        # dual multiplicative update
        w[P] *= np.exp(np.clip(eta * (Lf[P] / M - 1.0), -20.0, 20.0))
        w = np.clip(w, 1e-3, 1.0)
        w /= w.sum()
        # extend P
        cand = np.flatnonzero(Lf >= 0.90 * mx)
        if cand.size > 0:
            newP = np.union1d(P, cand)
            if newP.size > 400:
                # keep largest w
                order = np.argsort(-w[newP])
                newP = np.sort(newP[order[:400]])
            P = newP
        # drop knots below 0.85*max
        keep = Lf[P] >= 0.85 * mx
        if np.any(keep):
            P = P[keep]
        if P.size == 0:
            P = np.array([int(np.argmax(Lf))])
        # renormalize w restricted to P
        wP = w[P]
        sw = wP.sum()
        if sw > 0:
            w[P] = wP / sw
        # accept candidate if R >= bestR
        r = R_of(h_new)
        frac1 = float(np.mean(Lf >= 0.99 * mx))
        if r >= bestR - 1e-15:
            h = h_new
            if r > bestR:
                bestR = r
        print("mix it=%d R=%.9f best=%.9f |P|=%d frac1%%=%.3f"
              % (it, r, bestR, P.size, 100.0 * frac1))
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase M: dual mixture search (first 55% budget) ----
    m_end = t0 + budget_seconds * 0.55
    if time.process_time() < m_end - 3.0:
        h_m, r_m = _phase_mix(best, bestR, m_end)
        if r_m > bestR + 1e-15:
            best, bestR = h_m, r_m
            print("mix ACCEPT R=%.9f" % bestR)

    # ---- exact-R tie full polish ----
    if time.process_time() < m_end + budget_seconds * 0.05:
        ht = _lbfgs_block(best, np.arange(best.size), 200,
                          min(deadline - 2.0, time.process_time() + 4.0),
                          tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("tie polish R=%.9f" % bestR)

    # ---- peak-window tie polishes ----
    for pad in (0.06, 0.03, 0.015):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= deadline - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(deadline - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---- final: trust-newton on compressed quotient, if time ----
    d_end = t0 + budget_seconds * 0.92
    if time.process_time() < d_end - 1.0:
        n = min(4096, best.size)
        if best.size % n == 0:
            c_now = best.reshape(-1, best.size // n).mean(axis=1)
        else:
            c_now = np.interp(np.linspace(0, best.size - 1, n),
                              np.arange(best.size), best)
        c_now = _rescale(np.clip(c_now, 1e-30, None))
        cR0 = R_of(c_now)
        c_new = _trust_newton(c_now, d_end, 'trust-ncg', 1e-3)
        cRn = R_of(c_new)
        if cRn > cR0 + 1e-15:
            if best.size % c_new.size == 0:
                fac = best.size // c_new.size
                full2 = np.repeat(c_new, fac)
            else:
                full2 = np.interp(np.linspace(0, c_new.size - 1, best.size),
                                  np.arange(c_new.size), c_new)
            full2 = _rescale(full2)
            rf = R_of(full2)
            if rf > bestR + 1e-15:
                best, bestR = full2.copy(), rf
                print("Newton ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

