    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(start, Nf):
    start = np.asarray(start, dtype=float)
    n = start.size
    if n == Nf:
        return start.copy()
    c = np.concatenate([[0.0], np.cumsum(start)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nf)
    xs = np.linspace(0.0, 1.0, Nf + 1)
    old = np.linspace(0.0, 1.0, n + 1)
    cm = np.interp(xs, old, c)
    h = np.diff(cm) * Nf
    return np.maximum(h, 0.0)


def _detect_repeat(h):
    n = h.size
    for p in (2, 4, 8, 16, 32):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-10, atol=1e-14):
            return m, p
    return n, 1


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        s = np.asarray(start, dtype=float).copy()
        s = np.clip(s, 0, None)
        if s.sum() <= 0:
            s = None
    else:
        s = None

    if s is None:
        # naive initial guess: U-shaped
        N = 1024
        xk = (np.arange(N) + 0.5) / N
        s = 1.0 / np.sqrt(np.maximum(xk * (1 - xk), 1e-3))
        s = np.minimum(s, 4.0 * np.mean(s))

    r_start = R_of(s)

    # Work at a moderate raster. Try to exploit repeating structure if present.
    best = s.copy()
    best_r = r_start

    # Choose working raster: keep close to start size but cap.
    N = s.size
    if N > 4096:
        hw = _resample(s, 4096)
    else:
        hw = s.copy()

    rw = R_of(hw)
    if rw > best_r:
        best, best_r = hw.copy(), rw
    else:
        hw = best.copy()

    # ---- Strategy: alternating full polish + peak-focused polish ----
    # First a full polish at working raster.
    hw = _lbfgs_block(hw, np.arange(hw.size), 400, deadline)
    rw = R_of(hw)
    if rw > best_r:
        best, best_r = hw.copy(), rw
    print(f"full polish N={hw.size}: R={rw:.6f} (best {best_r:.6f})")

    # Peak-focused polishing: concentrate free variables near the max of f*f.
    for it in range(6):
        if time.process_time() > deadline - 1.0:
            break
        win = _peak_window(hw, tol=0.9999, pad_frac=0.25, extra=128)
        free = np.union1d(win, _peak_window(hw, tol=0.999, pad_frac=0.4, extra=256))
        free = np.clip(free, 0, hw.size - 1)
        hw = _lbfgs_block(hw, free, 200, deadline, tie=(_tie_count(hw) > 1))
        rw = R_of(hw)
        if rw > best_r:
            best, best_r = hw.copy(), rw
        # soft-max polish to break ties / smooth peak
        if time.process_time() < deadline - 2.0:
            hw = _lbfgs_block(hw, np.arange(hw.size), 100, deadline, beta=1e5)
            rw = R_of(hw)
            if rw > best_r:
                best, best_r = hw.copy(), rw
        print(f"peak it{it} N={hw.size}: R={rw:.6f} (best {best_r:.6f}) ties={_tie_count(hw)}")

    # ---- Try doubling N (prolongation + polish) ----
    if hw.size * 2 <= 8192 and time.process_time() < deadline - 3.0:
        h2 = np.repeat(hw, 2)
        r2 = R_of(h2)
        if r2 > best_r - 1e-4:
            h2 = _lbfgs_block(h2, np.arange(h2.size), 300, deadline)
            r2 = R_of(h2)
            print(f"2x N={h2.size}: R={r2:.6f}")
            if r2 > best_r:
                best, best_r = h2.copy(), r2
                hw = h2

    # ---- Try reducing to a repeating block then re-expanding ----
    if time.process_time() < deadline - 3.0:
        m, p = _detect_repeat(hw)
        if p > 1:
            c = hw.reshape(m, p).mean(axis=1)
            c = _lbfgs_block(c, np.arange(m), 300, deadline)
            hr = np.repeat(c, p)
            hr = _rescale(hr)
            rr = R_of(hr)
            print(f"repeat p={p} m={m}: R={rr:.6f}")
            if rr > best_r:
                best, best_r = hr.copy(), rr
                hw = hr

    # ---- Final: high-res polish at original raster if room ----
    if s.size <= 20000 and time.process_time() < deadline - 2.0:
        hs = _resample(best, s.size)
        hs = _lbfgs_block(hs, np.arange(hs.size), 200, deadline)
        rs = R_of(hs)
        print(f"final orig-raster N={hs.size}: R={rs:.6f}")
        if rs > best_r:
            best, best_r = hs.copy(), rs

    if r_start > best_r:
        return {"best": np.asarray(start, dtype=float),
                "alternative": best}
    if best_r > r_start + 1e-9:
        if start is not None:
            return {"best": best, "alternative": np.asarray(start, dtype=float)}
        return best
    # no improvement found
    if start is not None:
        return {"best": np.asarray(start, dtype=float), "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _peak_ladder(h, deadline, pads=(0.10, 0.06, 0.04, 0.025), iters=250,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---- Staircase (block-constant) helpers ----
def _expand(x, block):
    return np.repeat(x, block)


def _aggregate(g, block):
    return g.reshape(-1, block).sum(axis=1)


def _phi_grad_x(x, block):
    h = _expand(x, block)
    val, g = _fun_grad_tie(h)
    return val, _aggregate(g, block)


def _hessvec(x, v, block, eps=1e-4):
    _, g1 = _phi_grad_x(x + eps * v, block)
    _, g0 = _phi_grad_x(x - eps * v, block)
    return (g1 - g0) / (2.0 * eps)


def _lanczos_smallest(x, block, rng, m=25, deadline=None):
    n = x.size
    _, g = _phi_grad_x(x, block)
    gn = np.abs(g)
    thr = np.quantile(gn, 0.40)
    mask = gn >= thr
    idx = np.flatnonzero(mask)
    if idx.size < 4:
        idx = np.arange(n)
    r = rng.standard_normal(idx.size)
    v = np.zeros(n)
    v[idx] = r
    nv = np.linalg.norm(v)
    if nv <= 0:
        return 0.0, v
    v /= nv
    V = np.zeros((m + 1, n))
    V[0] = v
    alphas = np.zeros(m)
    betas = np.zeros(m)
    used = 0
    for j in range(m):
        if deadline is not None and time.process_time() > deadline:
            break
        w = _hessvec(x, V[j], block)
        w[~mask] = 0.0
        a = float(np.dot(w, V[j]))
        alphas[j] = a
        w = w - a * V[j]
        if j > 0:
            w = w - betas[j - 1] * V[j - 1]
        b = float(np.linalg.norm(w))
        betas[j] = b
        used = j + 1
        if b < 1e-12:
            break
        V[j + 1] = w / b
    m = max(1, used)
    T = np.diag(alphas[:m])
    for j in range(m - 1):
        T[j, j + 1] = betas[j]
        T[j + 1, j] = betas[j]
    try:
        evals, evecs = np.linalg.eigh(T)
    except Exception:
        return 0.0, v
    lam = float(evals[0])
    y = evecs[:, 0]
    vv = y @ V[:m]
    nvv = np.linalg.norm(vv)
    if nvv > 0:
        vv /= nvv
    return lam, vv


def _lbfgs_x(x0, block, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return x0
    x = np.clip(x0, 0, None)
    if x.sum() <= 0:
        return x0

    def f(xx):
        xxc = np.clip(xx, 0.0, None)
        h = _expand(xxc, block)
        if beta > 0:
            val, g = _fun_grad_beta(h, beta)
        else:
            val, g = _fun_grad_tie(h)
        return val, _aggregate(g, block)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return x0
    if res is None:
        return x0
    return np.clip(res.x, 0.0, None)


def _detect_block(h):
    n = h.size
    for p in (64, 32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 8:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-9, atol=1e-12):
            return p
    return 1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    block = _detect_block(best)
    N = best.size
    if block < 2 or N % block != 0:
        block = 1
    nx = N // block
    x = best.reshape(nx, block).mean(axis=1)
    h_from_x = _expand(x, block)
    print("staircase block=%d nx=%d R(x)=%.9f" % (block, nx, R_of(h_from_x)))

    rng = np.random.default_rng(12345)

    # ---- Curvature-based escape attempt ----
    lanc_deadline = time.process_time() + min(12.0, budget_seconds * 0.20)
    lam, v = _lanczos_smallest(x, block, rng, m=25, deadline=lanc_deadline)
    print("smallest Ritz value = %.6e" % lam)

    accepted = False
    if lam < 0 and np.linalg.norm(v) > 0:
        xnorm = np.linalg.norm(x)
        vnorm = np.linalg.norm(v)
        scale = xnorm / max(vnorm, 1e-30)
        for step in (0.02, 0.06, 0.15):
            if time.process_time() > deadline - 8.0:
                break
            for sign in (+1, -1):
                if time.process_time() > deadline - 8.0:
                    break
                xt = x + sign * step * scale * v
                xt = np.clip(xt, 0.0, None)
                if xt.sum() <= 0:
                    continue
                slice_end = min(deadline - 4.0, time.process_time() + 6.0)
                xt = _lbfgs_x(xt, block, 250, slice_end)
                ht = _rescale(_expand(xt, block))
                ht = _peak_ladder(ht, min(deadline - 1.0,
                                          time.process_time() + 4.0),
                                  pads=(0.08, 0.05, 0.03), iters=150, tie=True)
                rt = R_of(ht)
                print("  trial step=%+.3f sign=%+d R=%.9f dR=%+.3e"
                      % (step, sign, rt, rt - bestR))
                if rt > bestR + 1e-15:
                    best, bestR = ht.copy(), rt
                    x = best.reshape(nx, block).mean(axis=1)
                    accepted = True
                    print("  ACCEPTED step=%+.3f sign=%+d R=%.9f"
                          % (step, sign, bestR))

    if not accepted:
        print("no curvature escape accepted; polishing base")

    # ---- Polish remaining time ----
    loop_end = t0 + budget_seconds * 0.88
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 6.0)
        h_t = _lbfgs_block(best, np.arange(best.size), 500,
                           slice_end - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("polish %d ACCEPT R=%.9f" % (it, bestR))
        else:
            print("polish %d no gain R=%.9f" % (it, r_t))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=200, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("polish peak %d ACCEPT R=%.9f" % (it, bestR))

    # ---- Final passes ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_block(best, np.arange(best.size), 400, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _split2(h):
    n = h.size
    h2 = np.empty(2 * n)
    h2[0::2] = h
    h2[1::2] = h
    return h2


def _jitter_blocks(h, rng, nblocks, blocklen, sigma):
    h2 = h.copy()
    n = h.size
    for _ in range(nblocks):
        L = min(blocklen, n)
        st = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, sigma, size=L))
        h2[st:st + L] *= fac
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Verify p=32 repeat structure ----
    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))
    if p > 1:
        rrep = R_of(np.repeat(c, p))
        print("verify |R(start)-R(repeat(c,p))|=%.3e" % abs(rrep - startR))

    # ---- Phase A: split to 2N, jitter, polish ----
    a_end = min(deadline - 8.0, t0 + 24.0)
    if time.process_time() < a_end - 1.0 and best.size * 2 <= 1000000:
        h2 = _split2(best)
        r2 = R_of(h2)
        print("split2 N=%d R=%.12f (start %.12f) diff=%.3e"
              % (h2.size, r2, startR, abs(r2 - startR)))
        rng = np.random.default_rng(20240517)
        h2 = _jitter_blocks(h2, rng, 40, 64, 3e-3)
        h2 = _lbfgs_block(h2, np.arange(h2.size), 250,
                          min(a_end, time.process_time() + 10.0), tie=True)
        rA = R_of(h2)
        print("PhaseA lbfgs N=%d R=%.9f shares=%.4f/%.4f/%.4f"
              % (h2.size, rA, *_shares(h2)))
        if rA > bestR + 1e-15:
            best, bestR = h2.copy(), rA
        for pad in (0.10, 0.05, 0.025, 0.012, 0.006):
            if time.process_time() >= a_end - 0.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=96)
            ht = _lbfgs_block(best, win, 120,
                              min(a_end - 0.3, time.process_time() + 3.0),
                              tie=True)
            r = R_of(ht)
            print("PhaseA pad=%.3f R=%.9f shares=%.4f/%.4f/%.4f"
                  % (pad, r, *_shares(ht)))
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r

    # ---- Phase B: split again to 4N, polish ----
    b_end = deadline
    if time.process_time() < b_end - 1.0 and best.size * 2 <= 1000000:
        h4 = _split2(best)
        r4 = R_of(h4)
        print("split2 N=%d R=%.12f (best %.12f) diff=%.3e"
              % (h4.size, r4, bestR, abs(r4 - bestR)))
        rng = np.random.default_rng(777)
        h4 = _jitter_blocks(h4, rng, 40, 128, 1e-3)
        h4 = _lbfgs_block(h4, np.arange(h4.size), 200,
                          min(b_end - 0.5, time.process_time() + 8.0),
                          tie=True)
        rB = R_of(h4)
        print("PhaseB lbfgs N=%d R=%.9f shares=%.4f/%.4f/%.4f"
              % (h4.size, rB, *_shares(h4)))
        if rB > bestR + 1e-15:
            best, bestR = h4.copy(), rB
        for pad in (0.05, 0.025, 0.012):
            if time.process_time() >= b_end - 0.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=96)
            ht = _lbfgs_block(best, win, 120,
                              min(b_end - 0.3, time.process_time() + 3.0),
                              tie=True)
            r = R_of(ht)
            print("PhaseB pad=%.3f R=%.9f shares=%.4f/%.4f/%.4f"
                  % (pad, r, *_shares(ht)))
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r

    # ---- Final full tie polish ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_block(best, np.arange(best.size), 200,
                          min(deadline - 0.5, time.process_time() + 5.0),
                          tie=True)
        r = R_of(ht)
        print("final full polish R=%.9f shares=%.4f/%.4f/%.4f"
              % (r, *_shares(ht)))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    print("final R=%.9f (start %.9f, N=%d, ties=%d) shares=%.4f/%.4f/%.4f"
          % (bestR, startR, best.size, _tie_count(best), *_shares(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _jitter_full(h, rng, nblocks_lo=2, nblocks_hi=4, sigma=0.02, Lmax=65):
    n = h.size
    h2 = h.copy()
    nb = int(rng.integers(nblocks_lo, nblocks_hi))
    for _ in range(nb):
        L = int(rng.integers(2, Lmax))
        if L >= n:
            L = n
        st = int(rng.integers(0, n - L + 1))
        h2[st:st + L] *= np.exp(rng.normal(0.0, sigma, size=L))
    return h2


def _upsample(h, factor):
    """Linear-interpolation upsampling of step heights; preserves shape approx."""
    n = h.size
    m = (n - 1) * factor + 1
    xi = np.linspace(0, n - 1, m)
    return np.interp(xi, np.arange(n), h)


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 2:
        return h
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- (A) exact tie-L-BFGS on the full array ----
    a_end = min(deadline, time.process_time() + 8.0)
    hA = _lbfgs_block(best, np.arange(best.size), 500, a_end, tie=True)
    rA = R_of(hA)
    if rA > bestR + 1e-15:
        best, bestR = hA.copy(), rA
    print("PhaseA R=%.9f" % bestR)

    # ---- (B) beta-ladder smoothing pushes toward a flatter peak ----
    b_end = min(deadline, time.process_time() + 8.0)
    for beta in (1e3, 1e5, 1e7):
        if time.process_time() >= b_end - 0.5:
            break
        hb = _lbfgs_block(best, np.arange(best.size), 300,
                          min(b_end, time.process_time() + 2.5), beta=beta)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb.copy(), rb
    print("PhaseB R=%.9f" % bestR)

    # ---- (C) peak-window polish at several scales ----
    c_end = min(deadline, time.process_time() + 8.0)
    for pad, frac in ((0.05, 0.3), (0.02, 0.15), (0.01, 0.08), (0.005, 0.04)):
        if time.process_time() >= c_end - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=128)
        hp = _lbfgs_block(best, win, 400,
                          min(c_end, time.process_time() + 2.0), tie=True)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
    print("PhaseC R=%.9f" % bestR)

    # ---- (D) upsampled refinement: add resolution then re-polish ----
    d_end = min(deadline, time.process_time() + 10.0)
    if best.size < 900000 and time.process_time() < d_end - 2.0:
        fac = 2
        hu = _upsample(best, fac)
        hu = _rescale(hu)
        hu = _lbfgs_block(hu, np.arange(hu.size), 300,
                          min(d_end, time.process_time() + 6.0), tie=True)
        ru = R_of(hu)
        if ru > bestR + 1e-15:
            best, bestR = hu.copy(), ru
            print("Upsample ACCEPT R=%.9f (N=%d)" % (bestR, best.size))
        else:
            print("Upsample no gain (%.9f vs %.9f)" % (ru, bestR))

    # ---- (E) jitter rounds with tie re-polish, saving best ----
    rng = np.random.default_rng(int(20240607 + t0 * 1000) & 0x7fffffff)
    e_end = deadline
    rounds = 0
    accepted = 0
    while time.process_time() < e_end - 1.0:
        rounds += 1
        sigma = 0.02 if rounds < 5 else 0.005
        hj = _jitter_full(best, rng, 2, 4, sigma, 65)
        win = _peak_window(hj, pad_frac=0.1, extra=128)
        hj = _lbfgs_block(hj, win, 200,
                          min(e_end - 0.5,
                              time.process_time() + 2.5), tie=True)
        rj = R_of(hj)
        if rj > bestR + 1e-15:
            best, bestR = hj.copy(), rj
            accepted += 1
            print("jitter round=%d ACCEPT R=%.9f" % (rounds, bestR))
    print("PhaseD rounds=%d accepted=%d R=%.9f" % (rounds, accepted, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
