        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _resample(h, n):
    """Resample step function h onto n steps preserving mass."""
    m = h.size
    if m == n:
        return h.copy()
    # cumulative mass at edges
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    x = np.linspace(0.0, total, n + 1)
    out = np.interp(x, cum, np.arange(m + 1, dtype=float))
    # out[j] in [0,m] position; height = 1/(out[j+1]-out[j])
    d = np.diff(out)
    d = np.maximum(d, 1e-12)
    return 1.0 / d


def _refine_peak(h, deadline, label=""):
    best = h.copy()
    bestR = R_of(best)
    pads = [0.08, 0.05, 0.03, 0.02, 0.012, 0.008]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, tol=0.99999, pad_frac=pad, extra=64)
        ht = _lbfgs_block(best, win, 500, deadline - 0.3, beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, tol=0.99999, pad_frac=pad, extra=64)
            ht = _lbfgs_block(best, win, 500, deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: peak-focused high-beta / beta=0 refinement of start ----
    phase1_end = t0 + budget_seconds * 0.55
    ht, rt = _refine_peak(best, phase1_end)
    if rt > bestR + 1e-15:
        best, bestR, origin = ht.copy(), rt, 'peak'
        print("peak phase NEW BEST R=%.9f" % bestR)
    elif rt > alt_bestR:
        alt_best, alt_bestR = ht.copy(), rt

    # One full-resolution beta-polish pass after peak refinement.
    if time.process_time() < phase1_end - 1.0:
        for beta in [1e7, 1e8, 0.0]:
            if time.process_time() >= phase1_end - 0.8:
                break
            ht = _lbfgs_block(best, np.arange(best.size), 300,
                              phase1_end - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, origin + '+b%g' % beta
                print("full-beta NEW BEST R=%.9f (beta=%g)" % (bestR, beta))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: NEW -- resample to finer grid and re-refine ----
    # Upsampling onto a finer step grid adds degrees of freedom that can
    # break the plateau of the current optimum. We try a few densities.
    phase2_end = deadline - 0.8
    n0 = best.size
    for factor in [2, 3]:
        if time.process_time() >= phase2_end - 1.0:
            break
        n_new = min(1000000, n0 * factor)
        if n_new <= n0:
            continue
        hu = _resample(best, n_new)
        hu = _rescale(hu)
        ru = R_of(hu)
        print("  upsample x%d -> N=%d R=%.9f" % (factor, n_new, ru))
        # refine the upsampled version
        sub_end = min(phase2_end, time.process_time() + (phase2_end - time.process_time()) * 0.5)
        hu2, ru2 = _refine_peak(hu, sub_end)
        if ru2 > bestR + 1e-15:
            best, bestR, origin = hu2.copy(), ru2, origin + '+up%d' % factor
            print("upsample NEW BEST R=%.9f (x%d)" % (bestR, factor))
        elif ru2 > alt_bestR:
            alt_best, alt_bestR = hu2.copy(), ru2

    # ---- Phase 3: fine peak polish with remaining time ----
    ht, rt = _refine_peak(best, phase2_end)
    if rt > bestR + 1e-15:
        best, bestR, origin = ht.copy(), rt, origin + '+pk2'
        print("phase2 peak NEW BEST R=%.9f" % bestR)
    elif rt > alt_bestR:
        alt_best, alt_bestR = ht.copy(), rt

    if time.process_time() < phase2_end - 1.0:
        ht = _lbfgs_block(best, np.arange(best.size), 300,
                          phase2_end - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

