    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 1.2

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    n = best.size
    print("base R=%.9f (N=%d, ties=%d)" % (bestR, n, _tie_count(best)))

    # ---- Phase A: escalate soft-max to flatten/normalise the plateau, then
    # exact tie-aware objective.  The tie-aware gradient is the key change:
    # it treats all near-max knots equally, which avoids the pathological
    # "single knot dominates" local optimum that limits R. ----
    def _try(hc, valR, tag):
        nonlocal best, bestR
        if valR > bestR + 1e-13:
            best, bestR = hc, valR
            print("  %s -> %.9f" % (tag, bestR))
            return True
        return False

    if time.process_time() < hard - 5.0:
        for beta in (200.0, 1500.0, 8000.0, 40000.0):
            if time.process_time() >= hard - 4.0:
                break
            cap = min(hard - 3.0, time.process_time() + 3.0)
            hb = _lbfgs_block(best, np.arange(n), 400, cap, beta=beta)
            _try(hb, R_of(hb), "beta=%.0f" % beta)
        cap = min(hard - 2.5, time.process_time() + 3.0)
        hb = _lbfgs_block(best, np.arange(n), 500, cap, tie=True)
        _try(hb, R_of(hb), "tie-full")

    # ---- Phase B: iterate peak-window tie-aware polishing until plateau
    # is uniformly maximal; then narrow windows on the plateau itself. ----
    for pad in (0.6, 0.3, 0.15, 0.08):
        if time.process_time() >= hard - 2.0:
            break
        free = _peak_window(best, tol=0.9999, pad_frac=pad, extra=128)
        cap = min(hard - 1.5, time.process_time() + 2.5)
        hb = _lbfgs_block(best, free, 300, cap, tie=True)
        _try(hb, R_of(hb), "tie-pad=%.2f" % pad)

    # ---- Phase C: random local perturbations centered on the plateau,
    # each polished with the tie-aware objective (targets the metric that
    # actually limits R). ----
    rng = np.random.RandomState(91173)
    width_fracs = [0.004, 0.008, 0.016, 0.032, 0.064]
    restart = 0
    while time.process_time() < hard - 3.0:
        restart += 1
        Lf = _knots(best)
        mx = Lf.max()
        peak = np.flatnonzero(Lf >= 0.999 * mx)
        if peak.size == 0:
            break
        center = int(peak[rng.randint(peak.size)])
        w = max(4, int(n * width_fracs[rng.randint(len(width_fracs))]))
        i0 = int(np.clip(center - w // 2, 0, max(0, n - w)))
        h = best.copy()
        seg = h[i0:i0 + w]
        if seg.size == 0:
            continue
        mode = rng.randint(3)
        if mode == 0:
            a = rng.choice([-0.03, -0.01, 0.01, 0.03])
            h[i0:i0 + w] = seg * np.exp(a)
        elif mode == 1:
            a = rng.choice([5e-4, 2e-3, 8e-3])
            x = np.arange(w, dtype=float)
            bump = np.exp(-0.5 * ((x - w / 2.0) / max(1.0, w / 4.0)) ** 2)
            h[i0:i0 + w] = seg + a * best.mean() * bump
        else:
            h[i0:i0 + w] = seg * (1.0 + 0.015 * rng.randn(w))
        h = _rescale(h)

        cap = min(hard - 2.5, time.process_time() + 2.5)
        hq = _lbfgs_block(h, np.arange(n), 200, cap, tie=True)
        rq = R_of(hq)
        # local window refine
        free = _peak_window(hq, tol=0.9999, pad_frac=0.25, extra=96)
        cap2 = min(hard - 1.8, time.process_time() + 1.5)
        hq2 = _lbfgs_block(hq, free, 120, cap2, tie=True)
        rq2 = R_of(hq2)
        if rq2 > rq:
            hq, rq = hq2, rq2
        beat = rq > bestR + 1e-13
        print("  [r%d c=%d w=%d m=%d] Rw=%.9f best=%.9f %s" %
              (restart, center, w, mode, rq, bestR, "BEAT" if beat else ""))
        if beat:
            best, bestR = hq, rq

    # ---- final exact polish ----
    if time.process_time() < hard - 0.4:
        cap = min(hard - 0.3, time.process_time() + 2.0)
        hb = _lbfgs_block(best, np.arange(n), 500, cap, tie=False)
        r = R_of(hb)
        if r > bestR:
            best, bestR = hb, r

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

