    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    return _lbfgs_block(h0, np.arange(len(h0)), maxiter, deadline, beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth(h, w):
    if w <= 1:
        return h
    k = np.ones(w) / w
    return np.convolve(h, k, mode='same')


def _mass_jitter(h, amp, rng):
    """Multiplicative log-normal jitter preserving rough magnitude."""
    n = h.size
    noise = rng.standard_normal(n) * amp
    return h * np.exp(noise)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    alt = None
    altR = 0.0
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # ---- NEW IDEA 1: multi-scale random jitter restarts (escapes local minima) ----
    try:
        for trial in range(6):
            if time.process_time() >= deadline - 8.0:
                break
            amp = 0.02 * (1.5 ** trial)
            hj = _mass_jitter(best, amp, rng)
            hj = _rescale(hj)
            sub_dl = min(deadline - 6.0, time.process_time() + 5.0)
            ht = _lbfgs_all_pos(hj, 250, sub_dl, beta=0.0)
            r = R_of(ht)
            print("jitter t=%d amp=%.3f: R=%.9f" % (trial, amp, r))
            if r > altR + 1e-13:
                alt, altR = ht.copy(), r
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+jit%d' % trial
    except Exception as e:
        print("jitter stage failed: %s" % e)

    # ---- NEW IDEA 2: beta annealing (soft-max -> hard max) ----
    try:
        for beta in (1e2, 1e3, 1e4, 1e5, 1e6, 1e7):
            if time.process_time() >= deadline - 6.0:
                break
            sub_dl = min(deadline - 4.0, time.process_time() + 4.0)
            ht = _lbfgs_all_pos(best, 200, sub_dl, beta=beta)
            r = R_of(ht)
            print("beta=%.0e: R=%.9f" % (beta, r))
            if r > altR + 1e-13:
                alt, altR = ht.copy(), r
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+b%.0e' % beta
    except Exception as e:
        print("anneal stage failed: %s" % e)

    print("anneal best: R=%.9f origin=%s" % (bestR, origin))

    # ---- Base alternating polish loop ----
    try:
        for _ in range(300):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all0'
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+all7'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk0'
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+pk7'
    except Exception as e:
        print("polish loop failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d)" % (bestR, origin, best.size))

    if alt is not None and altR > start_bestR + 1e-13 and altR < bestR - 1e-13:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _near_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0
    return float(np.mean(Lf >= 0.99 * mx)), float(np.mean(Lf >= 0.95 * mx))


def _cvar_fg(c, p, q):
    """CVaR objective on c with h=repeat(c,p). Returns (val, grad_c)."""
    h = np.repeat(c, p)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    num, dq, Lf = _num_and_dq(h)
    L = Lf[1:-1]  # conv(h,h), drop pad zeros
    n = L.size
    k = int(np.ceil((1.0 - q) * n))
    k = max(1, min(k, n))
    idx = np.argpartition(L, n - k)[n - k:]
    Q = L[idx].mean()
    if Q <= 0:
        return 1e18, np.zeros(c.size)
    w = np.zeros(n)
    w[idx] = 1.0 / k
    gLf = np.zeros(Lf.size)
    gLf[1:-1] = -dq[1:-1] / num + w / Q
    grad_h = _backprop(gLf, h) + 2.0 / s
    grad_c = grad_h.reshape(c.size, p).sum(axis=1)
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Q)
    return val, grad_c


def _cvar_lbfgs(c0, p, q, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c0
    c = np.clip(c0, 0, None)
    if c.sum() <= 0:
        return c0

    def f(x):
        cc = np.clip(x, 0.0, None)
        return _cvar_fg(cc, p, q)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * c.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.clip(res.x, 0.0, None)


def _tie_polish_c(c, p, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c
    h = _rescale(np.repeat(c, p))
    h2 = _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=True)
    return h2.reshape(-1, p).mean(axis=1)


def _peak_polish_c(c, p, pad, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c
    h = _rescale(np.repeat(c, p))
    win = _peak_window(h, pad_frac=pad, extra=96)
    h2 = _lbfgs_block(h, win, maxiter, deadline, tie=True)
    return h2.reshape(-1, p).mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # verify repeat structure
    try:
        rrep = R_of(np.repeat(c, p))
        assert abs(rrep - R_of(best)) <= 1e-12
    except Exception:
        p = 1
        c = best.copy()

    # track best exact
    def accept(cand_c):
        nonlocal best, bestR
        hh = _rescale(np.repeat(cand_c, p))
        r = R_of(hh)
        if r > bestR + 1e-15:
            best, bestR = hh, r
            return True
        return False

    # ---- CVaR annealing ladder ----
    q_ladder = [0.995, 0.98, 0.95, 0.90, 0.85, 0.80]
    c_cur = c.copy()
    for qi, q in enumerate(q_ladder):
        if time.process_time() >= deadline - 2.0:
            break
        remaining = deadline - time.process_time()
        slice_end = time.process_time() + 0.10 * remaining
        slice_end = min(slice_end, deadline - 1.5)
        c_new = _cvar_lbfgs(c_cur, p, q, 400, slice_end)
        c_cur = c_new
        # exact tie polish of full c
        c_tie = _tie_polish_c(c_cur, p, 200, min(deadline - 1.0,
                                                 time.process_time() + 3.0))
        accept(c_tie)
        # one peak-window tie polish at pad 0.05
        c_pk = _peak_polish_c(c_tie, p, 0.05, 200,
                              min(deadline - 0.8, time.process_time() + 2.0))
        accept(c_pk)
        c_cur = c_pk if R_of(np.repeat(c_pk, p)) >= R_of(np.repeat(c_tie, p)) else c_tie
        n01, n05 = _near_fracs(best)
        print("q=%.3f exactR=%.9f near01=%.4f near05=%.4f"
              % (q, bestR, n01, n05))

    # ---- Final exact tie polish + pads ----
    c_best = best.reshape(-1, p).mean(axis=1) if best.size % p == 0 else c_cur
    c_best = _tie_polish_c(c_best, p, 300,
                           min(deadline - 0.8, time.process_time() + 4.0))
    accept(c_best)
    for pad in (0.10, 0.05, 0.03):
        if time.process_time() >= deadline - 0.8:
            break
        c_best = _peak_polish_c(c_best, p, pad, 300,
                                min(deadline - 0.5, time.process_time() + 3.0))
        accept(c_best)
        n01, n05 = _near_fracs(best)
        print("final pad=%.2f exactR=%.9f near01=%.4f near05=%.4f"
              % (pad, bestR, n01, n05))

    n01, n05 = _near_fracs(best)
    print("final R=%.9f (start %.9f, N=%d, near01=%.4f, near05=%.4f)"
          % (bestR, startR, best.size, n01, n05))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return 0.0, 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    mx = L.max()
    den = s * s * (mx if mx > 0 else 1.0)
    if den <= 0:
        return 0.0, mx
    return num / den, mx


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta))
    cb = _make_cb(deadline - 0.2)

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    """Log-space L-BFGS-B on strictly positive h = exp(theta)."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.maximum(np.asarray(h0, dtype=float), 0.0)
    if h.sum() <= 0:
        return h0
    n = h.size

    def fg(theta):
        hh = np.exp(np.clip(theta, -30.0, 30.0))
        return _fun_grad_beta(hh, beta)

    theta0 = np.log(np.maximum(h, 1e-12))
    cb = _make_cb(deadline - 0.2)

    def f(x):
        return fg(x)

    try:
        res = minimize(f, theta0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(np.clip(res.x, -30.0, 30.0)))


def _fun_grad_tie(h):
    """Hard-max objective: -log(num) + 2 log(s) + log(Lmax), with 1/Lmax on tied argmax knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    tie = Lf >= mx - 1e-12 * max(1.0, abs(mx))
    cnt = tie.sum()
    w = tie.astype(float) / cnt
    gLf = -dq / num + w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _lbfgs_tie(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    cb = _make_cb(deadline - 0.2)

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _revive(h, frac, amp):
    """Gradient-ranked revival of zero cells: set top-frac zero cells to amp*mean(active)."""
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    s = h.sum()
    if s <= 0:
        return h
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return h
    tie = Lf >= mx - 1e-12 * max(1.0, abs(mx))
    cnt = tie.sum()
    w = tie.astype(float) / cnt
    gLf = -dq / num + w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    zero = h <= 0
    nz = zero.sum()
    if nz == 0:
        return h
    k = max(1, int(round(frac * nz)))
    k = min(k, nz)
    gz = grad[zero]
    idx_zero = np.nonzero(zero)[0]
    order = np.argsort(-gz)[:k]
    active = h[~zero]
    if active.size == 0:
        return h
    fill = amp * active.mean()
    out = h.copy()
    out[idx_zero[order]] = fill
    return out


def _report(tag, h):
    R, mx = R_of(h)
    L = _conv(np.maximum(h, 0.0))
    if L.max() > 0:
        near = np.mean(L >= 0.99 * L.max())
        near5 = np.mean(L >= 0.95 * L.max())
        am = float(np.argmax(L)) / max(1, 2 * len(h) - 2)
    else:
        near = 0.0
        near5 = 0.0
        am = 0.0
    print("%s: R=%.6f N=%d zero_frac=%.3f max/mean=%.2f near01=%.3f near05=%.3f argmax=%.3f" % (
        tag, R, len(h), np.mean(np.asarray(h) <= 0),
        np.max(h) / (np.mean(h) + 1e-12), near, near5, am))
    return R


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    M = len(h)
    if M == N:
        return h.copy()
    edges = np.linspace(0, M, N + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))

    def cum_at(x):
        i = np.floor(x).astype(int)
        i = np.clip(i, 0, M - 1)
        frac = x - i
        return cum[i] + frac * h[i]

    mass = cum_at(edges[1:]) - cum_at(edges[:-1])
    cellw = M / N
    out = mass / cellw
    return np.maximum(out, 0.0)


def _upsample_cumsum(h, N):
    """Mass-preserving cumsum upsample to N cells (piecewise-linear interpolation of cumsum)."""
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    M = len(h)
    if M == N:
        return h.copy()
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0, M, N + 1)
    i = np.floor(edges).astype(int)
    i = np.clip(i, 0, M)
    frac = edges - i
    ip = np.clip(i, 0, M)
    im = np.clip(i - 1, 0, M) if False else np.clip(i, 0, M)
    # cum has length M+1, index 0..M
    cval = cum[np.clip(i, 0, M)] + frac * (h[np.clip(i, 0, M - 1)] if M > 0 else 0.0)
    # simpler: interpolate cum linearly
    cval = np.interp(edges, np.arange(M + 1), cum)
    mass = cval[1:] - cval[:-1]
    cellw = M / N
    out = mass / cellw
    return np.maximum(out, 0.0)


def _tie_polish(h, deadline, betas=(1e4, 1e5, 1e6), iters=200):
    best = np.maximum(np.asarray(h, dtype=float), 0.0)
    bestR, _ = R_of(best)
    for beta in betas:
        if time.process_time() > deadline - 0.5:
            break
        dl = min(deadline - 0.3, time.process_time() + 0.10 * max(1.0, deadline - time.process_time()))
        h2 = _lbfgs(best, iters, dl, beta=beta)
        R2, _ = R_of(h2)
        if R2 > bestR:
            best = h2
            bestR = R2
    if time.process_time() < deadline - 0.5:
        dl = min(deadline - 0.3, time.process_time() + 0.10 * max(1.0, deadline - time.process_time()))
        h2 = _lbfgs_tie(best, iters, dl)
        R2, _ = R_of(h2)
        if R2 > bestR:
            best = h2
            bestR = R2
    return best, bestR


def _revival_ladder(h, deadline, rungs, iters, tag_prefix):
    best = np.maximum(np.asarray(h, dtype=float), 0.0)
    bestR, _ = R_of(best)
    for (frac, amp) in rungs:
        if time.process_time() > deadline - 1.0:
            break
        h_rev = _revive(best, frac, amp)
        dl = min(deadline - 0.5, time.process_time() + 0.20 * max(1.0, deadline - time.process_time()))
        h_pol = _lbfgs_all_pos(h_rev, iters, dl, beta=0.0)
        Rpol, _ = R_of(h_pol)
        # exact tie polish
        dl2 = min(deadline - 0.3, time.process_time() + 0.10 * max(1.0, deadline - time.process_time()))
        h_tie = _lbfgs_tie(h_pol, max(50, iters // 2), dl2)
        Rtie, _ = R_of(h_tie)
        cand = h_pol
        Rcand = Rpol
        if Rtie > Rcand:
            cand = h_tie
            Rcand = Rtie
        _report("%s revive(%.3f,%.3f)" % (tag_prefix, frac, amp), cand)
        if Rcand > bestR + 1e-12:
            best = cand
            bestR = Rcand
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()

    def elapsed():
        return time.process_time() - t0

    deadline = t0 + 0.93 * budget_seconds

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float), 0.0)
        if s.sum() > 0:
            R, _ = R_of(s)
            best_h = s.copy()
            best_R = R
            print("Start: R=%.6f N=%d" % (R, len(s)))

    if best_h is None:
        N0 = 4096
        x = np.linspace(0, 1, N0)
        best_h = np.sin(np.pi * x) ** 0.5
        best_R, _ = R_of(best_h)

    print("Working N=%d start R=%.6f" % (len(best_h), best_R))
    _report("INIT", best_h)

    rungs = [(0.01, 0.01), (0.03, 0.01), (0.05, 0.02), (0.10, 0.03), (0.20, 0.03)]

    # (B) Revival ladder at current N
    if elapsed() < deadline - 2.0:
        best_h, best_R = _revival_ladder(best_h, deadline, rungs, 250, "L%d" % len(best_h))

    # (C) Upsample to 65536 and repeat at half iterations
    if elapsed() < deadline - 2.0 and len(best_h) <= 40000:
        h_up = _upsample_cumsum(best_h, 65536)
        Rup, _ = R_of(h_up)
        _report("UPSAMPLE->65536", h_up)
        if Rup > best_R:
            best_h = h_up
            best_R = Rup
        best_h, best_R = _revival_ladder(best_h, deadline, rungs, 125, "L65536")

    # (D) Final tie polish ladder + peak-window pads
    if elapsed() < deadline - 1.0:
        dl = min(deadline - 0.5, elapsed() + 0.15 * budget_seconds)
        h_tp, Rtp = _tie_polish(best_h, dl, betas=(1e4, 1e5, 1e6), iters=200)
        _report("FINAL tie polish", h_tp)
        if Rtp > best_R:
            best_h = h_tp
            best_R = Rtp

    # peak-window pads: revive a small fraction near the peak region
    for pad in (0.10, 0.05, 0.03):
        if elapsed() > deadline - 1.0:
            break
        h_rev = _revive(best_h, pad, 0.02)
        dl = min(deadline - 0.5, elapsed() + 0.10 * budget_seconds)
        h_pol = _lbfgs_all_pos(h_rev, 150, dl, beta=0.0)
        Rp, _ = R_of(h_pol)
        _report("PAD %.2f" % pad, h_pol)
        if Rp > best_R:
            best_h = h_pol
            best_R = Rp

    best_h = np.maximum(np.asarray(best_h, dtype=float), 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(len(best_h) if len(best_h) > 0 else 4096)
    if len(best_h) > 1000000:
        best_h = _resample(best_h, 1000000)
    Rf = _report("FINAL", best_h)

    result = {"best": best_h}
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float), 0.0)
        if s.sum() > 0:
            Rs, _ = R_of(s)
            if Rs > Rf:
                result["best"] = s
                result["alternative"] = best_h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return -1.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size, hi + pad)
    return np.arange(lo, hi)


def _prolongate(h, Nnew):
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew)
    edges = np.linspace(0.0, N, Nnew + 1)
    m = np.interp(edges, np.arange(N + 1), c)
    return np.maximum(np.diff(m), 0.0)


def _polish(h, deadline, levels=(0.0, 1e3, 1e4)):
    best = np.asarray(h, dtype=float)
    bestR = R_of(best)
    for beta in levels:
        if time.process_time() > deadline - 0.5:
            break
        cand = _lbfgs_all_pos(best, maxiter=400, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(best)
        cand = _lbfgs_block(best, win, maxiter=300, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
    return best, bestR


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    near01 = np.mean(Lf >= 0.999 * mx)
    near5 = np.mean(Lf >= 0.95 * mx)
    zf = np.mean(h <= 0.0)
    return zf, near01, near5


def _edge_inject(h, p, m, w_frac=0.02, w_min=16, cap_factor=1.0):
    h = np.clip(h, 0, None).astype(float)
    s = h.sum()
    if s <= 0:
        return h
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    lo = int(nz[0]); hi = int(nz[-1])
    N = h.size
    w = max(w_min, int(w_frac * N))
    w = min(w, (hi - lo + 1) // 2)
    if w < 2:
        return h
    cap = cap_factor * h.max()
    target_add = m * s
    h2 = h.copy()

    idxL = np.arange(lo, lo + w)
    shapeL = (np.arange(1, w + 1, dtype=float)) ** (-p)
    idxR = np.arange(hi - w + 1, hi + 1)
    shapeR = (np.arange(w, 0, -1, dtype=float)) ** (-p)

    oldL = h2[idxL].copy()
    oldR = h2[idxR].copy()

    def build(A):
        newL = np.minimum(cap, A * shapeL)
        newR = np.minimum(cap, A * shapeR)
        newL = np.maximum(newL, oldL)
        newR = np.maximum(newR, oldR)
        return newL, newR

    def added(A):
        nL, nR = build(A)
        return (nL.sum() - oldL.sum()) + (nR.sum() - oldR.sum())

    Alo, Ahi = 0.0, cap * 10.0
    for _ in range(60):
        if added(Ahi) >= target_add:
            break
        Ahi *= 2.0
    for _ in range(80):
        Amid = 0.5 * (Alo + Ahi)
        if added(Amid) < target_add:
            Alo = Amid
        else:
            Ahi = Amid
    A = 0.5 * (Alo + Ahi)
    nL, nR = build(A)
    h2[idxL] = nL
    h2[idxR] = nR
    return h2


def _realized_mass_frac(h_old, h_new):
    s_old = h_old.sum()
    if s_old <= 0:
        return 0.0
    return (h_new.sum() - s_old) / s_old


# ===== EXPERIMENT: spike amplification =====

def _spike_amp(h, A, w, sides='both', w_taper_mult=4.0):
    """Multiply h by (1 + A*exp(-(x-x0)^2/(2w^2))) at support ends x0=0,1,
    then rescale interior plateau multiplicatively to preserve total mass."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0:
        return h
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    lo = int(nz[0]); hi = int(nz[-1])
    N = h.size
    span = hi - lo + 1
    if span < 4:
        return h
    # x normalized to [0,1] over support
    idx = np.arange(N, dtype=float)
    x = (idx - lo) / float(span - 1)
    # Gaussian caps
    ww = max(w, 1e-6)
    gL = np.exp(-(x ** 2) / (2.0 * ww * ww))
    gR = np.exp(-((x - 1.0) ** 2) / (2.0 * ww * ww))
    if sides == 'both':
        g = gL + gR
    elif sides == 'left':
        g = gL
    elif sides == 'right':
        g = gR
    else:
        g = gL + gR
    mult = 1.0 + A * g
    h2 = h * mult
    # interior region to rescale (mass compensation): |x-0.5| < 0.5 - w_taper
    w_taper = w_taper_mult * ww
    inner = np.abs(x - 0.5) < (0.5 - w_taper)
    # also restrict to support
    inner &= (idx >= lo) & (idx <= hi)
    s2 = h2.sum()
    if s2 <= 0:
        return h
    # mass added by spikes
    added = s2 - s
    if added <= 0:
        return _rescale(h2)
    inner_mass = h2[inner].sum()
    if inner_mass <= 0:
        return _rescale(h2)
    # scale interior down so total mass restored
    target_inner = inner_mass - added
    if target_inner < 0:
        # cannot remove enough; scale everything
        return _rescale(h2 * (s / s2))
    factor = target_inner / inner_mass
    h2[inner] *= factor
    return _rescale(np.clip(h2, 0, None))


def _report(tag, h, base_R=None):
    r = R_of(h)
    zf, n01, n5 = _stats(h)
    Lf = _knots(h)
    mx = Lf.max()
    argmax = int(np.argmax(Lf)) / max(1, Lf.size - 1)
    mean_h = h.mean()
    mm = (h.max() / mean_h) if mean_h > 0 else 0.0
    extra = ""
    if base_R is not None:
        extra = " (base %.6f, d=%+.6f)" % (base_R, r - base_R)
    print("%s R=%.6f zero=%.3f max/mean=%.1f near01=%.3f near05=%.3f argmax=%.3f%s"
          % (tag, r, zf, mm, n01, n5, argmax, extra))
    return r


def _polish_ladder(h, r, deadline, pads=(0.10, 0.05, 0.03), tie_iters=250):
    """tie polish + peak pads, accept strict exact-R gains."""
    if time.process_time() > deadline - 0.5:
        return h, r
    ht = _lbfgs_all_pos(h, maxiter=tie_iters, deadline=deadline, beta=0.0)
    rt = R_of(ht)
    if rt > r:
        h, r = ht, rt
    _report("  after tie", h, r)
    for pad in pads:
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(h, tol=0.999, pad_frac=pad, extra=64)
        hc = _lbfgs_block(h, win, maxiter=250, deadline=deadline, beta=0.0)
        rc = R_of(hc)
        if rc > r:
            h, r = hc, rc
        _report("  after peak pad=%.2f" % pad, h, r)
    return h, r


def main_construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    best_h = None
    best_R = -1.0
    start_h = None
    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_h = s.copy()
            start_R = R_of(s)
            best_h = s.copy()
            best_R = start_R

    if best_h is None:
        best_h = np.ones(64)
        best_R = R_of(best_h)

    # Stage 1: polish the start at its own resolution
    if start_h is not None and time.process_time() < deadline - 2.0:
        h, r = _polish(start_h, min(deadline - 1.0, time.process_time() + 8.0))
        if r > best_R:
            best_R = r
            best_h = h
        print("start polish: %.6f" % best_R)

    # Stage 2: escalate resolutions with polishing
    targets = [8192, 16384, 32768, 65536]
    for Ntarget in targets:
        if time.process_time() > deadline - 2.0:
            break
        h = _prolongate(best_h, Ntarget)
        h, r = _polish(h, deadline)
        if r > best_R:
            best_R = r
            best_h = h
        print("escalated R at N=%d: %.6f" % (Ntarget, best_R))

    # Stage 3: final tight polish at current size
    if time.process_time() < deadline - 0.5:
        h, r = _polish(best_h, deadline, levels=(0.0, 1e4, 1e5))
        if r > best_R:
            best_R = r
            best_h = h

    zf, n01, n5 = _stats(best_h)
    print("pre-experiment R: %.6f N=%d zero=%.3f near01=%.3f near05=%.3f"
          % (best_R, best_h.size, zf, n01, n5))

    # === EXPERIMENT: spike amplification ===
    N0 = 32768
    if best_h.size != N0:
        h_base = _prolongate(best_h, N0)
    else:
        h_base = best_h.copy()
    if time.process_time() < deadline - 1.0:
        h_base, r_base = _polish(h_base,
                                 min(deadline - 0.5, time.process_time() + 5.0),
                                 levels=(0.0, 1e3))
        if r_base > best_R:
            best_R = r_base
            best_h = h_base
    else:
        r_base = R_of(h_base)
    _report("base N=%d" % h_base.size, h_base, r_base)

    # (B) candidate sweep
    As = [2.0, 8.0, 30.0, 100.0]
    ws = [0.005, 0.02]
    sides_list = ['both', 'left', 'right']
    cands = []
    for A in As:
        for w in ws:
            for sides in sides_list:
                if time.process_time() > deadline - 1.0:
                    break
                cand = _spike_amp(h_base, A, w, sides=sides)
                rc = R_of(cand)
                tag = "  A=%.0f w=%.3f %s" % (A, w, sides)
                _report(tag, cand, r_base)
                cands.append((rc, A, w, sides, cand))
    cands.sort(key=lambda t: -t[0])

    # (C) polish best 3
    polished = []
    for (rc, A, w, sides, cand) in cands[:3]:
        if time.process_time() > deadline - 1.0:
            break
        print("polishing A=%.0f w=%.3f %s (raw %.6f)" % (A, w, sides, rc))
        h, r = _polish_ladder(cand, rc, deadline,
                              pads=(0.10, 0.05, 0.03), tie_iters=250)
        polished.append((r, A, w, sides, h))
    if polished:
        polished.sort(key=lambda t: -t[0])
        r_best, A_best, w_best, sides_best, h_best = polished[0]
        if r_best > best_R:
            best_R = r_best
            best_h = h_best
        _report("best spike N=%d" % h_best.size, best_h, r_base)
    else:
        A_best = w_best = sides_best = None

    # (D) lift to N=65536 and repeat with shortened ladder
    if time.process_time() < deadline - 1.0 and A_best is not None:
        h = _prolongate(best_h, 65536)
        h, r = _polish(h, min(deadline - 0.5, time.process_time() + 5.0),
                       levels=(0.0, 1e3))
        if r > best_R:
            best_R = r
            best_h = h
        _report("lift N=65536", h, r)
        # re-inject at new resolution with best (A,w,sides) and neighbors
        trials = [(A_best, w_best, sides_best),
                  (A_best * 2.0, w_best, sides_best),
                  (A_best, w_best * 2.0, sides_best)]
        for (A, w, sides) in trials:
            if time.process_time() > deadline - 1.0:
                break
            cand = _spike_amp(h, A, w, sides=sides)
            rc = R_of(cand)
            _report("  N=65536 A=%.0f w=%.3f %s" % (A, w, sides), cand, r)
            if rc > r:
                hc, rc2 = _polish_ladder(cand, rc, deadline,
                                         pads=(0.08, 0.04, 0.02),
                                         tie_iters=200)
                if rc2 > r:
                    h, r = hc, rc2
        if r > best_R:
            best_R = r
            best_h = h
        _report("after N=65536", best_h, r_base)

    # final tight polish
    if time.process_time() < deadline - 0.5:
        h, r = _polish(best_h, deadline, levels=(0.0, 1e4, 1e5))
        if r > best_R:
            best_R = r
            best_h = h

    _report("final", best_h, start_R if start_R > 0 else None)

    if start_h is not None and start_R >= best_R:
        return start_h
    if start_h is not None and start_R > 0 and best_h is not None and best_R - start_R > 1e-6:
        return {"best": best_h, "alternative": start_h}
    return best_h


def construct(budget_seconds, start):
    try:
        return main_construct(budget_seconds, start)
    except Exception:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(64)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _diagnostics(h):
    Lf = _knots(h)
    mx = Lf.max()
    am = int(np.argmax(Lf))
    return {'N': h.size, 'R': R_of(h), 'zero_frac': float(np.mean(h <= 0)),
            'argmax': am, 'argmax_frac': am / max(1, h.size)}


def _perturb(h, rng, scale, frac):
    n = h.size
    k = max(4, int(n * frac))
    s = int(rng.integers(0, max(1, n - k)))
    h2 = h.copy()
    h2[s:s + k] *= np.exp(rng.normal(0.0, scale, size=k))
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    d = _diagnostics(best)
    print("start N=%d R=%.7f zero=%.3f argmax=%d (%.3f)"
          % (d['N'], d['R'], d['zero_frac'], d['argmax'], d['argmax_frac']))

    def _try(h, tag):
        nonlocal best, bestR
        if h is None:
            return False
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  %s R=%.7f" % (tag, r))
            return True
        return False

    # ---- Step A: sharp polish of start (tie-aware to escape flat peak) ----
    if time.process_time() < deadline - 30.0:
        h = _lbfgs_log(best, 200,
                       min(deadline - 28.0, time.process_time() + 4.0),
                       tie=True)
        _try(h, "A tie polish")

    # ---- Step B: peak-window block refinement (low-dim, fast) ----
    if time.process_time() < deadline - 20.0:
        for frac in (0.3, 0.15, 0.08, 0.04):
            if time.process_time() > deadline - 18.0:
                break
            free = _peak_window(best, tol=0.9995, pad_frac=frac, extra=32)
            hp = _lbfgs_block(best, free, 400,
                              min(deadline - 15.0, time.process_time() + 3.0),
                              tie=True)
            _try(hp, "B peak frac=%.2f" % frac)

    # ---- Step C: beta-continuation to sharpen the peak ----
    if time.process_time() < deadline - 12.0:
        for beta in (1e2, 1e3, 1e4, 1e5):
            if time.process_time() > deadline - 10.0:
                break
            hp = _lbfgs_log(best, 200,
                            min(deadline - 8.0, time.process_time() + 2.0),
                            beta=beta)
            _try(hp, "C beta=%.0e" % beta)

    # ---- Step D: basin hopping with structured perturbations ----
    it = 0
    while time.process_time() < deadline - 4.0:
        it += 1
        if it < 15:
            scale, frac = 0.06, 0.12
        elif it < 40:
            scale, frac = 0.03, 0.06
        else:
            scale, frac = 0.015, 0.03
        hp = _perturb(best, rng, scale, frac)
        hp = _lbfgs_log(hp, 150,
                        min(deadline - 3.0, time.process_time() + 1.5),
                        tie=True)
        if _try(hp, "D hop%d" % it):
            # re-polish peak after a win
            free = _peak_window(best, tol=0.9995, pad_frac=0.1, extra=32)
            hp2 = _lbfgs_block(best, free, 300,
                               min(deadline - 2.0, time.process_time() + 2.0),
                               tie=True)
            _try(hp2, "D polish")

    # ---- Step E: final sharp polish loop ----
    while time.process_time() < deadline - 0.8:
        hp = _lbfgs_log(best, 250,
                        min(deadline - 0.4, time.process_time() + 2.5),
                        tie=True)
        if not _try(hp, "E sharp"):
            break

    d = _diagnostics(best)
    print("final R=%.7f (N=%d) zero=%.3f"
          % (bestR, best.size, d['zero_frac']))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

