    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _refine(h):
    return _rescale(np.repeat(np.clip(h, 0, None), 2))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    print("base R=%.9f (N=%d)" % (baseR, baseH.size))

    # Refinement attempt on base
    h2 = _refine(baseH)
    r2 = R_of(h2)
    print("refined N=%d R=%.9f (delta %.2e)" % (h2.size, r2, r2 - baseR))
    if r2 > baseR:
        bestH, bestR = h2, r2
    else:
        bestH, bestR = baseH.copy(), baseR

    altH = bestH.copy()
    altR = bestR

    # Phase 1: beta-schedule
    for beta in (0.0, 1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 4.0:
            break
        cap = min(deadline - 3.0, time.process_time() + 6.0)
        hs = _lbfgs_log(bestH, 250, cap, beta=beta)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            print("  beta=%.0e -> R=%.9f" % (beta, bestR))

    if bestR > altR + 1e-14:
        altH, altR = bestH.copy(), bestR

    # Phase 2: alternate global log-optim and peak-window block LBFGS.
    it = 0
    loop_end = deadline - 3.0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 5.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        improved = False
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs
            improved = True
            print("  iter=%d global R=%.9f" % (it, bestR))
        if time.process_time() < loop_end - 1.0:
            frac = 0.03 + 0.07 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 150, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                improved = True
                print("  iter=%d peak frac=%.2f R=%.9f" % (it, frac, bestR))
        if improved and bestR > altR + 1e-14:
            altH, altR = bestH.copy(), bestR

    # Phase 3: refine to 2x resolution and re-optimize
    if time.process_time() < deadline - 2.0 and bestH.size < 500000:
        hr = _refine(bestH)
        rr = R_of(hr)
        if rr > bestR + 1e-12:
            bestH, bestR = hr, rr
            print("refined to N=%d R=%.9f" % (bestH.size, bestR))
        if time.process_time() < deadline - 1.5:
            cap = min(deadline - 1.0, time.process_time() + 3.0)
            hs = _lbfgs_log(bestH, 150, cap, beta=0.0)
            rs = R_of(hs)
            if rs > bestR + 1e-14:
                bestH, bestR = hs.copy(), rs
                print("refined polish R=%.9f" % bestR)

    # Phase 4: NEW - try coarsening then re-refining to escape local optimum.
    # A coarsened version loses fine detail; re-optimizing at low res and
    # then refining back can find a different/better basin.
    if time.process_time() < deadline - 3.0 and bestH.size > 512:
        hc = _coarsen(bestH)
        rc = R_of(hc)
        if time.process_time() < deadline - 2.5:
            cap = min(deadline - 2.0, time.process_time() + 2.0)
            hc = _lbfgs_log(hc, 100, cap, beta=0.0)
            rc = R_of(hc)
        # refine back
        hr = _refine(hc)
        rr = R_of(hr)
        if time.process_time() < deadline - 1.5:
            cap = min(deadline - 1.0, time.process_time() + 2.0)
            hr = _lbfgs_log(hr, 100, cap, beta=0.0)
            rr = R_of(hr)
        if rr > bestR + 1e-14:
            bestH, bestR = hr, rr
            print("coarsen+refine R=%.9f" % bestR)

    # Final polish
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.0)
        hs = _lbfgs_log(bestH, 150, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    if bestR > altR + 1e-14:
        altH, altR = bestH.copy(), bestR

    print("final R=%.9f N=%d (base %.9f)" % (bestR, bestH.size, baseR))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        return {"best": baseH, "alternative": altH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend_pow(h, K, p):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        w = (1.0 + k) ** (-p)
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * w
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * w
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline cycle on best (beta ladder + peak window)
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: random multi-start perturbations of the best
    rng2 = np.random.default_rng(987654321)
    amps = [0.005, 0.01, 0.02, 0.03, 0.05, 0.008, 0.015, 0.025, 0.04, 0.06]
    for trial, amp in enumerate(amps):
        if time.process_time() >= deadline - 1.0:
            break
        seed = _random_perturb(best, rng2, amp)
        r_seed = R_of(seed)
        w, b, br, org = _run_cycle(seed, seed.copy(), r_seed, deadline,
                                   'rand%d' % trial)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("rand%d amp=%.4f: R=%.9f NEW BEST" % (trial, amp, bestR))
        else:
            if br > alt_bestR and br > start_bestR + 1e-14:
                alt_best, alt_bestR = b, br
            print("rand%d amp=%.4f: R=%.9f (best %.9f)" % (trial, amp, br, bestR))

    # Phase C: power-law edge extension sweep
    if time.process_time() < deadline - 2.0:
        for (K, p) in [(2048, 3.0), (2048, 2.0), (1024, 4.0)]:
            if time.process_time() >= deadline - 1.0:
                break
            ext = _edge_extend_pow(best, K, p)
            r_ext = R_of(ext)
            w, b, br, org = _run_cycle(ext, ext.copy(), r_ext, deadline,
                                       'pow%d_%g' % (K, p))
            if br > bestR + 1e-14:
                best, bestR, origin = b, br, org
                print("pow K=%d p=%.1f NEW BEST R=%.9f" % (K, p, bestR))
            elif br > alt_bestR and br > start_bestR + 1e-14:
                alt_best, alt_bestR = b, br

    # Final polish: tight peak-window L-BFGS with beta ladder
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.15]:
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            for beta in [1e7, 1e8, 0.0]:
                if time.process_time() >= deadline - 0.4:
                    break
                ht = _lbfgs_block(best, win, 400, deadline - 0.3, beta=beta)
                r = R_of(ht)
                if r > bestR + 1e-14:
                    best, bestR = ht, r
                    origin = origin + '+finalwin'

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

