    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _near5(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(L >= mx * 0.95))


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_pnorm(h, p):
    """Surrogate: num_p = S_p^{2/p}, S_p = sum w_j L_j^p (trapezoid weights)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    n = Lf.size
    w = np.full(n, 2.0)
    w[0] = 1.0
    w[-1] = 1.0
    Lp = np.clip(Lf, 0.0, None)
    # avoid 0^(p-1) issues; p>1 so L^(p-1) fine at 0
    Sp = float(np.sum(w * Lp ** p))
    if Sp <= 0:
        return _fun_grad_tie(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    # d(-log num_p)/dL_j = -(2/p) * (1/Sp) * p * w_j * L_j^{p-1}
    #                     = -2 * w_j * L_j^{p-1} / Sp
    gLf = -2.0 * w * (Lp ** (p - 1.0)) / Sp
    # tie max term
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Sp) * (2.0 / p) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 pnorm=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if pnorm is not None:
        fg = (lambda hh: _fun_grad_pnorm(hh, pnorm))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        start = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[start:start + L] *= fac
    return c2


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _trust_newton(c0, deadline, method='trust-ncg', init_radius=1e-3):
    if time.process_time() >= deadline - 0.5:
        return c0
    c0 = np.clip(c0, 1e-30, None)
    v0 = np.sqrt(c0)

    def fg(v):
        c = v * v
        val, g = _fun_grad_tie(c)
        return val, 2.0 * v * g

    def hessp(v, w):
        eps = 1e-6 * (1.0 + np.linalg.norm(v))
        vp = v + eps * w
        vm = v - eps * w
        cp = vp * vp
        cm = vm * vm
        _, gp = _fun_grad_tie(cp)
        _, gm = _fun_grad_tie(cm)
        gvp = 2.0 * vp * gp
        gvm = 2.0 * vm * gm
        return (gvp - gvm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg, v0, jac=True, method=method, hessp=hessp,
                       callback=cb,
                       options={'maxiter': 300,
                                'initial_trust_radius': init_radius,
                                'max_trust_radius': 0.5,
                                'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None or not np.all(np.isfinite(res.x)):
        return c0
    c = res.x * res.x
    return _rescale(c)


def _coarse(c_in, m):
    n = c_in.size
    if m == n:
        return c_in.copy()
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 * (n / m)
    xi = np.arange(n, dtype=float) + 0.5
    return np.interp(x, xi, c_in)


def _prolong(c_coarse, m_out):
    m = c_coarse.size
    if m_out == m:
        return c_coarse.copy()
    x = np.linspace(0.0, m, m_out, endpoint=False) + 0.5 * (m_out / m)
    xi = np.arange(m, dtype=float) + 0.5
    return np.interp(x, xi, c_coarse)


def _polish_c(c, p, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return c, R_of(np.repeat(c, p))
    h = _rescale(np.repeat(c, p))
    h2 = _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=tie)
    c2 = h2.reshape(-1, p).mean(axis=1)
    hr = np.repeat(c2, p)
    return c2, R_of(hr)


def _vcycle(best, bestR, p, c, deadline, levels):
    n_c = c.size
    coarse_list = [(n_c, c.copy())]
    cur = c
    for m in levels[1:]:
        cur = _coarse(cur, m)
        coarse_list.append((m, cur.copy()))
    m, cc = coarse_list[-1]
    cc, r = _polish_c(cc, p, 80, min(deadline, time.process_time() + 3.0))
    coarse_list[-1] = (m, cc)
    print("  vcycle level=%d R=%.9f" % (m, r))
    if r > bestR + 1e-15:
        best = _rescale(np.repeat(cc, p)); bestR = r
    for i in range(len(coarse_list) - 2, -1, -1):
        m_out, _ = coarse_list[i]
        cc = _prolong(cc, m_out)
        cc, r = _polish_c(cc, p, 100,
                          min(deadline, time.process_time() + 4.0))
        coarse_list[i] = (m_out, cc)
        print("  vcycle level=%d R=%.9f" % (m_out, r))
        if r > bestR + 1e-15:
            best = _rescale(np.repeat(cc, p)); bestR = r
    return best, bestR, cc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p_rep, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p_rep, c.size))

    # ---- Phase V: multi-resolution V-cycles (shortened to leave room for p-anneal) ----
    v_end = t0 + (deadline - t0) * 0.35 + t0
    if p_rep > 1 and c.size >= 4 and time.process_time() < v_end - 3.0:
        n_c = c.size
        levels = [n_c]
        m = n_c
        while len(levels) < 3 and m > 8:
            m = max(8, m // 4)
            if m >= levels[-1]:
                break
            levels.append(m)
        print("vcycle levels=%s" % levels)
        cycle = 0
        while time.process_time() < v_end - 3.0:
            cycle += 1
            best, bestR, c = _vcycle(best, bestR, p_rep, c, v_end, levels)
            print("vcycle cycle=%d done bestR=%.9f" % (cycle, bestR))
            if cycle >= 2 and time.process_time() > v_end - 6.0:
                break

    # ---- Phase P: p-norm numerator annealing on the full array ----
    # Work on the current best full-resolution array; polish active cells.
    p_end = t0 + (deadline - t0) * 0.80 + t0
    p_list = [1.4, 1.6, 1.8, 1.95, 2.0]
    cur = best.copy()
    curR = R_of(cur)
    # Use a broad window (whole array if manageable, else peak window)
    if cur.size <= 120000:
        win = np.arange(cur.size)
    else:
        win = _peak_window(cur, pad_frac=0.5, extra=512)
    for pval in p_list:
        if time.process_time() >= p_end - 1.0:
            break
        slice_end = min(p_end - 0.5, time.process_time() + 6.5)
        ht = _lbfgs_block(cur, win, 400, slice_end, pnorm=pval)
        rt = R_of(ht)
        n5 = _near5(ht)
        print("pnorm p=%.2f R=%.9f near5=%.4f (cur %.9f)"
              % (pval, rt, n5, curR))
        if rt > curR + 1e-15:
            cur, curR = ht, rt
        else:
            # keep the surrogate state anyway to continue annealing from it
            cur = ht
    if curR > bestR + 1e-15:
        best, bestR = cur.copy(), curR
        print("pnorm ACCEPT R=%.9f" % bestR)

    # ---- Phase E: exact tie polish + peak-window pads ----
    c_end = deadline
    for pad in (0.06, 0.03, 0.015):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= c_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(c_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f near5=%.4f"
              % (pad, bestR, _near5(best)))

    print("final R=%.9f (start %.9f, N=%d, ties=%d, near5=%.4f)"
          % (bestR, startR, best.size, _tie_count(best), _near5(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline, beta=beta)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _detect_period(h):
    n = h.size
    for p in (2, 3, 4, 5, 6, 8, 10, 12, 16, 24, 32):
        if n % p != 0:
            continue
        m = n // p
        if m < 4:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-9, atol=1e-12):
            return p
    return 1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    # ---- base ----
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best, alt_bestR = None, -1.0

    # ---- Phase A: detect periodicity in start; if found, work on quotient ----
    p = _detect_period(best)
    quotient = None
    if p > 1:
        H = best.reshape(best.size // p, p)
        quotient = H.mean(axis=1).copy()
        print("period p=%d detected, quotient R=%.9f" % (p, R_of(np.repeat(quotient, p))))
    else:
        # try even/odd split as a cheap quotient
        if best.size % 2 == 0 and best.size >= 8:
            c = best[0::2]
            if R_of(np.repeat(c, 2)) >= bestR - 1e-6:
                quotient = c.copy()
                p = 2
                print("even/odd quotient R=%.9f" % R_of(np.repeat(quotient, 2)))

    # ---- Phase B: polish quotient with (beta, peak, all) ladder ----
    if quotient is not None and quotient.size >= 4:
        q = quotient.copy()
        qR = R_of(np.repeat(q, p))
        q_deadline = t0 + budget_seconds * 0.55
        rounds = 0
        while time.process_time() < q_deadline - 1.0:
            rounds += 1
            moved = False
            for beta in (1e6, 1e7):
                if time.process_time() >= q_deadline - 0.8:
                    break
                qt = _lbfgs_all(q, 250, q_deadline - 0.5, beta=beta)
                r = R_of(np.repeat(qt, p))
                if r > qR + 1e-14:
                    q, qR, moved = qt, r, True
            for pad in (0.30, 0.20, 0.12, 0.08):
                if time.process_time() >= q_deadline - 0.8:
                    break
                win = _peak_window(q, pad_frac=pad, extra=128)
                qt = _lbfgs_block(q, win, 300, q_deadline - 0.5, beta=1e7)
                r = R_of(np.repeat(qt, p))
                if r > qR + 1e-14:
                    q, qR, moved = qt, r, True
            if time.process_time() < q_deadline - 0.8:
                qt = _lbfgs_all(q, 250, q_deadline - 0.5, beta=0.0)
                r = R_of(np.repeat(qt, p))
                if r > qR + 1e-14:
                    q, qR, moved = qt, r, True
            if not moved:
                break
        print("quotient rounds=%d R=%.9f" % (rounds, qR))

        # densify: try eps-fill of zeros then lift
        for eps in (0.0, 1e-4, 1e-3, 1e-2):
            if time.process_time() >= deadline - 4.0:
                break
            qq = q.copy()
            zm = (qq == 0)
            if zm.any() and eps > 0:
                qq[zm] = eps * qq.mean()
            if time.process_time() < deadline - 3.0:
                qq = _lbfgs_all(qq, 250, deadline - 2.5, beta=1e7)
            h_lift = _rescale(np.repeat(qq, p))
            if time.process_time() < deadline - 1.5:
                h_lift = _lbfgs_all(h_lift, 300, deadline - 1.0, beta=1e6)
            r = R_of(h_lift)
            if r > bestR + 1e-13:
                best, bestR, origin = h_lift.copy(), r, 'quot-lift eps=%g' % eps
                print("lift NEW BEST R=%.9f (eps=%g, dens=%.3f)"
                      % (bestR, eps, float(np.mean(qq > 0))))
            elif r > alt_bestR:
                alt_best, alt_bestR = h_lift.copy(), r

    # ---- Phase C: full-resolution polish ----
    if time.process_time() < deadline - 2.0:
        for beta in (1e6, 1e7, 0.0):
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all(best, 300, deadline - 0.6, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, origin + '+all%g' % beta
                print("all beta=%g NEW BEST R=%.9f" % (beta, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 300, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pk'
            print("peak NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _upsample(h, factor):
    """Smooth piecewise-linear upsample by integer factor."""
    n = h.size
    m = n * factor
    if factor == 1:
        return h.copy()
    # linear interpolation on the fine grid, evaluated at cell midpoints
    x = (np.arange(m) + 0.5) / factor - 0.5  # in coarse-cell-index coords
    x = np.clip(x, 0.0, n - 1.0)
    i0 = np.floor(x).astype(int)
    i1 = np.minimum(i0 + 1, n - 1)
    frac = x - i0
    return h[i0] * (1 - frac) + h[i1] * frac


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0
    best_c = None
    best_cR = -1.0

    # ---- Phase A: refine start directly at full resolution ----
    work = best.copy()
    if time.process_time() < deadline - 8.0:
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 7.0:
                break
            ht = _lbfgs_all_pos(work, 400, deadline - 6.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR, origin = ht, ht.copy(), r, 'direct_%g' % beta
                print("direct NEW BEST R=%.9f" % bestR)
        # peak polish
        for pad in [0.20, 0.12, 0.08]:
            if time.process_time() >= deadline - 6.0:
                break
            win = _peak_window(work, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 400, deadline - 5.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work, best, bestR, origin = ht, ht.copy(), r, 'direct_pk'
                print("direct pk NEW BEST R=%.9f" % bestR)

    # ---- Phase B: upsampling exploration ----
    # Try to upsample the current best by factor 2 and refine; if the true
    # optimum needs finer discretization near the peak, this can help.
    if time.process_time() < deadline - 5.0 and best.size * 2 <= 1000000:
        up = _rescale(_upsample(best, 2))
        ru = R_of(up)
        print("upsample2 R=%.9f" % ru)
        # refit at full resolution
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 4.5:
                break
            ht = _lbfgs_all_pos(up, 400, deadline - 4.0, beta=beta)
            r = R_of(ht)
            up = ht
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'upsample'
                print("upsample NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        # peak polish at upsample resolution
        for pad in [0.15, 0.10]:
            if time.process_time() >= deadline - 3.5:
                break
            win = _peak_window(up, pad_frac=pad, extra=128)
            ht = _lbfgs_block(up, win, 400, deadline - 3.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'upsample_pk'
                print("upsample pk NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            up = ht

    # ---- Phase C: half-resolution search + lift (as in original) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = min(deadline - 1.5, t0 + budget_seconds * 0.60)
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase D: fine peak polish on best ----
    if time.process_time() < deadline - 0.8:
        for pad in [0.12, 0.08, 0.05]:
            if time.process_time() >= deadline - 0.7:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase E: trailing beta=0 polish ----
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("best_c=%.9f best_full=%.9f" % (best_cR if best_c is not None else -1, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_logeps(h, eps_frac):
    """F_eps = -sum log(L+eps) + 2 log(sum h) + log(max L)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    eps = eps_frac * mx
    d = Lf + eps
    if np.any(d <= 0):
        d = np.clip(d, 1e-30, None)
    inv = 1.0 / d
    gLf = -inv
    m = int(np.argmax(Lf))
    gLf[m] += 1.0 / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.sum(np.log(d)) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 logeps=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if logeps is not None:
        fg = (lambda hh: _fun_grad_logeps(hh, logeps))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log_eps(h0, eps_frac, maxiter, deadline):
    """L-BFGS-B on log h with the log-sum lower-tail objective."""
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_logeps(hh, eps_frac)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _stats(h, label):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        print("%s: degenerate" % label)
        return
    r = Lf / mx
    near01 = float(np.mean(r >= 0.999))
    near05 = float(np.mean(r >= 0.95))
    dec = float(np.percentile(r, 10))
    print("%s R=%.9f near01=%.4f near05=%.4f p10=%.6f"
          % (label, R_of(h), near01, near05, dec))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _trust_newton(c0, deadline, method='trust-ncg', init_radius=1e-3):
    if time.process_time() >= deadline - 0.5:
        return c0
    c0 = np.clip(c0, 1e-30, None)
    v0 = np.sqrt(c0)

    def fg(v):
        c = v * v
        val, g = _fun_grad_tie(c)
        return val, 2.0 * v * g

    def hessp(v, w):
        eps = 1e-6 * (1.0 + np.linalg.norm(v))
        vp = v + eps * w
        vm = v - eps * w
        cp = vp * vp
        cm = vm * vm
        _, gp = _fun_grad_tie(cp)
        _, gm = _fun_grad_tie(cm)
        gvp = 2.0 * vp * gp
        gvm = 2.0 * vm * gm
        return (gvp - gvm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg, v0, jac=True, method=method, hessp=hessp,
                       callback=cb,
                       options={'maxiter': 300,
                                'initial_trust_radius': init_radius,
                                'max_trust_radius': 0.5,
                                'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None or not np.all(np.isfinite(res.x)):
        return c0
    c = res.x * res.x
    return _rescale(c)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    _stats(best, "base")

    # ---- Phase L: lower-tail log objective ladder ----
    # Run L-BFGS-B on log h with F_eps for a sequence of eps, then exact
    # tie polish. This is the experiment: reward raising small knots.
    l_end = t0 + (deadline - t0) * 0.55 + t0
    eps_list = (0.20, 0.10, 0.05, 0.02)
    cur = best.copy()
    curR = bestR
    for eps_frac in eps_list:
        if time.process_time() >= l_end - 1.0:
            break
        # a couple of passes at this eps
        for rep in range(2):
            if time.process_time() >= l_end - 0.8:
                break
            hl = _lbfgs_log_eps(cur, eps_frac, 200,
                                min(l_end - 0.4,
                                    time.process_time() + 4.0))
            rl = R_of(hl)
            _stats(hl, "logeps=%.2f rep=%d" % (eps_frac, rep))
            # exact tie polish
            win = _peak_window(hl, pad_frac=0.03, extra=96)
            hp = _lbfgs_block(hl, win, 200,
                              min(l_end - 0.3,
                                  time.process_time() + 3.0), tie=True)
            rp = R_of(hp)
            if rp > rl:
                hl, rl = hp, rp
            if rl > curR + 1e-15:
                cur, curR = hl.copy(), rl
                print("  logeps=%.2f ACCEPT R=%.9f" % (eps_frac, curR))
            else:
                # keep going from current best but do not regress
                pass
        _stats(cur, "after eps=%.2f" % eps_frac)
        if curR > bestR + 1e-15:
            best, bestR = cur.copy(), curR

    print("PhaseL done bestR=%.9f" % bestR)

    # ---- Phase D: trust-region Newton on compressed quotient ----
    d_end = t0 + (deadline - t0) * 0.75 + t0
    if time.process_time() < d_end - 1.0:
        _, c_now = _detect_repeat(best)
        if c_now.size == best.size:
            n = min(4096, best.size)
            if best.size % n == 0:
                c_now = best.reshape(-1, best.size // n).mean(axis=1)
            else:
                c_now = np.interp(np.linspace(0, best.size - 1, n),
                                  np.arange(best.size), best)
        c_now = _rescale(np.clip(c_now, 1e-30, None))
        cR0 = R_of(c_now)
        print("Newton start n_c=%d cR=%.9f" % (c_now.size, cR0))
        c_new = _trust_newton(c_now, d_end, 'trust-ncg', 1e-3)
        cRn = R_of(c_new)
        if cRn <= cR0 + 1e-15 and time.process_time() < d_end - 1.0:
            c_new2 = _trust_newton(c_now, d_end, 'trust-krylov', 1e-2)
            if R_of(c_new2) > cRn:
                c_new, cRn = c_new2, R_of(c_new2)
        print("Newton end cR=%.9f (was %.9f)" % (cRn, cR0))
        if cRn > cR0 + 1e-15:
            if best.size % c_new.size == 0:
                fac = best.size // c_new.size
                full2 = np.repeat(c_new, fac)
            else:
                full2 = np.interp(np.linspace(0, c_new.size - 1, best.size),
                                  np.arange(c_new.size), c_new)
            full2 = _rescale(full2)
            rf = R_of(full2)
            print("Newton lift R(full)=%.9f" % rf)
            if rf > bestR + 1e-15:
                best, bestR = full2.copy(), rf
                print("Newton ACCEPT R=%.9f" % bestR)

    # ---- Phase E: final peak polish ----
    c_end = deadline
    for pad in (0.06, 0.03, 0.015):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= c_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(c_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    _stats(best, "final")
    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return -1.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size, hi + pad)
    return np.arange(lo, hi)


def _prolongate(h, Nnew):
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew)
    edges = np.linspace(0.0, N, Nnew + 1)
    m = np.interp(edges, np.arange(N + 1), c)
    return np.maximum(np.diff(m), 0.0)


def _polish(h, deadline, levels=(0.0, 1e3, 1e4)):
    best = np.asarray(h, dtype=float)
    bestR = R_of(best)
    for beta in levels:
        if time.process_time() > deadline - 0.5:
            break
        cand = _lbfgs_all_pos(best, maxiter=400, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(best)
        cand = _lbfgs_block(best, win, maxiter=300, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
    return best, bestR


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    near01 = np.mean(Lf >= 0.999 * mx)
    near5 = np.mean(Lf >= 0.95 * mx)
    zf = np.mean(h <= 0.0)
    return zf, near01, near5


def _report(tag, h, base_R=None):
    r = R_of(h)
    zf, n01, n5 = _stats(h)
    Lf = _knots(h)
    mx = Lf.max()
    argmax = int(np.argmax(Lf)) / max(1, Lf.size - 1)
    mean_h = h.mean()
    mm = (h.max() / mean_h) if mean_h > 0 else 0.0
    extra = ""
    if base_R is not None:
        extra = " (base %.6f, d=%+.6f)" % (base_R, r - base_R)
    print("%s R=%.6f zero=%.3f max/mean=%.1f near01=%.3f near05=%.3f argmax=%.3f%s"
          % (tag, r, zf, mm, n01, n5, argmax, extra))
    return r


def _polish_ladder(h, r, deadline, pads=(0.10, 0.05, 0.03), tie_iters=250):
    if time.process_time() > deadline - 0.5:
        return h, r
    ht = _lbfgs_all_pos(h, maxiter=tie_iters, deadline=deadline, beta=0.0)
    rt = R_of(ht)
    if rt > r:
        h, r = ht, rt
    _report("  after tie", h, r)
    for pad in pads:
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(h, tol=0.999, pad_frac=pad, extra=64)
        hc = _lbfgs_block(h, win, maxiter=250, deadline=deadline, beta=0.0)
        rc = R_of(hc)
        if rc > r:
            h, r = hc, rc
        _report("  after peak pad=%.2f" % pad, h, r)
    return h, r


def _power_contrast(h, gamma):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.sum() <= 0:
        return h
    mx = h.max()
    if mx <= 0:
        return h
    hn = h / mx
    return _rescale(hn ** gamma)


def main_construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    best_h = None
    best_R = -1.0
    start_h = None
    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_h = s.copy()
            start_R = R_of(s)
            best_h = s.copy()
            best_R = start_R

    if best_h is None:
        best_h = np.ones(64)
        best_R = R_of(best_h)

    # Stage 1: quick polish of the start at its own resolution
    if start_h is not None and time.process_time() < deadline - 2.0:
        h, r = _polish(start_h, min(deadline - 1.0, time.process_time() + 6.0))
        if r > best_R:
            best_R = r
            best_h = h
        print("start polish: %.6f" % best_R)

    # Stage 2: escalate resolution moderately (keep budget for experiment)
    targets = [16384, 32768]
    for Ntarget in targets:
        if time.process_time() > deadline - 2.0:
            break
        if best_h.size >= Ntarget:
            continue
        h = _prolongate(best_h, Ntarget)
        h, r = _polish(h, min(deadline - 1.0, time.process_time() + 6.0))
        if r > best_R:
            best_R = r
            best_h = h
        print("escalated R at N=%d: %.6f" % (Ntarget, best_R))

    # === EXPERIMENT: power contrast h^gamma ===
    N0 = 32768
    if best_h.size != N0:
        h_base = _prolongate(best_h, N0)
    else:
        h_base = best_h.copy()
    if time.process_time() < deadline - 1.0:
        h_base, r_base = _polish(h_base,
                                 min(deadline - 0.5, time.process_time() + 4.0),
                                 levels=(0.0, 1e3))
        if r_base > best_R:
            best_R = r_base
            best_h = h_base
    else:
        r_base = R_of(h_base)
    _report("base N=%d" % h_base.size, h_base, r_base)

    gammas = [0.8, 0.9, 1.15, 1.3, 1.5, 1.8, 2.2, 3.0, 5.0]
    cands = []
    for g in gammas:
        if time.process_time() > deadline - 1.0:
            break
        cand = _power_contrast(h_base, g)
        rc = R_of(cand)
        _report("  gamma=%.2f" % g, cand, r_base)
        cands.append((rc, g, cand))
    cands.sort(key=lambda t: -t[0])

    polished = []
    for (rc, g, cand) in cands[:3]:
        if time.process_time() > deadline - 1.0:
            break
        print("polishing gamma=%.2f (raw %.6f)" % (g, rc))
        h, r = _polish_ladder(cand, rc, deadline,
                              pads=(0.10, 0.05, 0.03), tie_iters=250)
        polished.append((r, g, h))
    if polished:
        polished.sort(key=lambda t: -t[0])
        r_best, g_best, h_best = polished[0]
        if r_best > best_R:
            best_R = r_best
            best_h = h_best
        _report("best gamma=%.2f N=%d" % (g_best, h_best.size), best_h, r_base)
    else:
        g_best = None

    # Lift best to N=65536 and repeat shortened ladder
    if time.process_time() < deadline - 1.0 and g_best is not None:
        h = _prolongate(best_h, 65536)
        h, r = _polish(h, min(deadline - 0.5, time.process_time() + 4.0),
                       levels=(0.0, 1e3))
        if r > best_R:
            best_R = r
            best_h = h
        _report("lift N=65536", h, r)
        trials = [g_best, max(1.0, g_best * 0.8), g_best * 1.25]
        for g in trials:
            if time.process_time() > deadline - 1.0:
                break
            cand = _power_contrast(h, g)
            rc = R_of(cand)
            _report("  N=65536 gamma=%.2f" % g, cand, r)
            if rc > r:
                hc, rc2 = _polish_ladder(cand, rc, deadline,
                                         pads=(0.08, 0.04, 0.02),
                                         tie_iters=200)
                if rc2 > r:
                    h, r = hc, rc2
        if r > best_R:
            best_R = r
            best_h = h
        _report("after N=65536", best_h, r_base)

    # final tight polish
    if time.process_time() < deadline - 0.5:
        h, r = _polish(best_h, deadline, levels=(0.0, 1e4, 1e5))
        if r > best_R:
            best_R = r
            best_h = h

    _report("final", best_h, start_R if start_R > 0 else None)

    if start_h is not None and start_R >= best_R:
        return start_h
    if start_h is not None and start_R > 0 and best_h is not None and best_R - start_R > 1e-6:
        return {"best": best_h, "alternative": start_h}
    return best_h


def construct(budget_seconds, start):
    try:
        return main_construct(budget_seconds, start)
    except Exception:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(64)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        start = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[start:start + L] *= fac
    return c2


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _trust_newton(c0, deadline, method='trust-ncg', init_radius=1e-3):
    if time.process_time() >= deadline - 0.5:
        return c0
    c0 = np.clip(c0, 1e-30, None)
    v0 = np.sqrt(c0)

    def fg(v):
        c = v * v
        val, g = _fun_grad_tie(c)
        return val, 2.0 * v * g

    def hessp(v, w):
        eps = 1e-6 * (1.0 + np.linalg.norm(v))
        vp = v + eps * w
        vm = v - eps * w
        cp = vp * vp
        cm = vm * vm
        _, gp = _fun_grad_tie(cp)
        _, gm = _fun_grad_tie(cm)
        gvp = 2.0 * vp * gp
        gvm = 2.0 * vm * gm
        return (gvp - gvm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg, v0, jac=True, method=method, hessp=hessp,
                       callback=cb,
                       options={'maxiter': 300,
                                'initial_trust_radius': init_radius,
                                'max_trust_radius': 0.5,
                                'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None or not np.all(np.isfinite(res.x)):
        return c0
    c = res.x * res.x
    return _rescale(c)


# ---------- multi-resolution homotopy helpers ----------
def _coarse(c_in, m):
    n = c_in.size
    if m == n:
        return c_in.copy()
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 * (n / m)
    xi = np.arange(n, dtype=float) + 0.5
    return np.interp(x, xi, c_in)


def _prolong(c_coarse, m_out):
    m = c_coarse.size
    if m_out == m:
        return c_coarse.copy()
    x = np.linspace(0.0, m, m_out, endpoint=False) + 0.5 * (m_out / m)
    xi = np.arange(m, dtype=float) + 0.5
    return np.interp(x, xi, c_coarse)


def _polish_c(c, p, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return c, R_of(np.repeat(c, p))
    h = _rescale(np.repeat(c, p))
    h2 = _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=tie)
    c2 = h2.reshape(-1, p).mean(axis=1)
    hr = np.repeat(c2, p)
    return c2, R_of(hr)


def _vcycle(best, bestR, p, c, deadline, levels):
    n_c = c.size
    coarse_list = [(n_c, c.copy())]
    cur = c
    for m in levels[1:]:
        cur = _coarse(cur, m)
        coarse_list.append((m, cur.copy()))
    m, cc = coarse_list[-1]
    cc, r = _polish_c(cc, p, 80, min(deadline, time.process_time() + 3.0))
    coarse_list[-1] = (m, cc)
    print("  vcycle level=%d R=%.9f" % (m, r))
    if r > bestR + 1e-15:
        best = _rescale(np.repeat(cc, p)); bestR = r
    for i in range(len(coarse_list) - 2, -1, -1):
        m_out, _ = coarse_list[i]
        cc = _prolong(cc, m_out)
        cc, r = _polish_c(cc, p, 100,
                          min(deadline, time.process_time() + 4.0))
        coarse_list[i] = (m_out, cc)
        print("  vcycle level=%d R=%.9f" % (m_out, r))
        if r > bestR + 1e-15:
            best = _rescale(np.repeat(cc, p)); bestR = r
    return best, bestR, cc


# ---------- H22: per-block multiplier optimization ----------
def _block_R(w, c, p):
    h = np.repeat(c, p) * np.repeat(w, c.size)
    return R_of(h)


def _opt_block_w(c, p, w0, deadline, maxiter=200):
    """Optimize w (length p) on log(w) via exact-R L-BFGS-B."""
    if time.process_time() >= deadline - 0.3:
        return w0, _block_R(w0, c, p)
    n_c = c.size
    hbase = np.repeat(c, p)
    blk = np.repeat(np.arange(p), n_c).astype(float)

    def f(x):
        w = np.exp(x)
        h = hbase * np.repeat(w, n_c)
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(p)
        num, dq, Lf = _num_and_dq(h)
        mx = Lf.max()
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        gh = _backprop(gLf, h) + 2.0 / s
        # d/dlog w_k = sum over block k of gh * h
        gw = np.bincount(blk.astype(int), weights=gh * h, minlength=p)
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
        return val, gw

    x0 = np.log(np.clip(w0, 1e-12, None))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return w0, _block_R(w0, c, p)
    if res is None or not np.all(np.isfinite(res.x)):
        return w0, _block_R(w0, c, p)
    w = np.exp(res.x)
    return w, _block_R(w, c, p)


def _opt_block_w_sym(c, p, w0, deadline, maxiter=200):
    """Optimize w with mirror symmetry w_k = w_{p-1-k}."""
    if time.process_time() >= deadline - 0.3:
        return w0, _block_R(w0, c, p)
    n_c = c.size
    hbase = np.repeat(c, p)
    blk = np.repeat(np.arange(p), n_c).astype(int)
    half = (p + 1) // 2
    # map block -> free index
    fmap = np.empty(p, dtype=int)
    for k in range(p):
        fmap[k] = k if k < half else p - 1 - k

    def expand(x):
        w = np.exp(x)
        return w[fmap]

    def f(x):
        w = expand(x)
        h = hbase * np.repeat(w, n_c)
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(half)
        num, dq, Lf = _num_and_dq(h)
        mx = Lf.max()
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        gh = _backprop(gLf, h) + 2.0 / s
        gw_full = np.bincount(blk, weights=gh * h, minlength=p)
        gw = np.zeros(half)
        for k in range(p):
            gw[fmap[k]] += gw_full[k]
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
        return val, gw

    x0 = np.log(np.clip(w0[:half], 1e-12, None))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return w0, _block_R(w0, c, p)
    if res is None or not np.all(np.isfinite(res.x)):
        return w0, _block_R(w0, c, p)
    w = expand(res.x)
    return w, _block_R(w, c, p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- Phase H22: per-block multiplier optimization ----
    h22_end = t0 + (deadline - t0) * 0.35 + t0
    if p > 1 and c.size >= 4 and time.process_time() < h22_end - 1.0:
        w_best = np.ones(p)
        wR = _block_R(w_best, c, p)
        print("H22 start wR=%.9f" % wR)
        k = np.arange(p, dtype=float)
        starts = [np.ones(p)]
        for a in (0.1, 0.3, 0.6):
            starts.append(1.0 + a * np.cos(np.pi * k / (p - 1)))
        for b in (0.1, 0.3):
            starts.append(1.0 + b * ((k - (p - 1) / 2.0) / ((p - 1) / 2.0)) ** 2)
        for i, w0 in enumerate(starts):
            if time.process_time() >= h22_end - 1.0:
                break
            w0 = np.clip(w0, 1e-6, None)
            w, r = _opt_block_w(c, p, w0,
                                min(h22_end - 0.5, time.process_time() + 3.0))
            print("H22 start %d wR=%.9f" % (i, r))
            if r > wR + 1e-15:
                w_best, wR = w, r
        # mirror-symmetric
        if time.process_time() < h22_end - 1.0:
            w, r = _opt_block_w_sym(c, p, w_best,
                                    min(h22_end - 0.5, time.process_time() + 3.0))
            print("H22 sym wR=%.9f" % r)
            if r > wR + 1e-15:
                w_best, wR = w, r
        print("H22 best wR=%.9f (base %.9f)" % (wR, bestR))
        if wR > bestR + 1e-15:
            h_new = np.repeat(c, p) * np.repeat(w_best, c.size)
            h_new = _rescale(h_new)
            rn = R_of(h_new)
            if rn > bestR + 1e-15:
                best, bestR = h_new, rn
                print("H22 ACCEPT R=%.9f" % bestR)

    # ---- Phase V: multi-resolution V-cycles ----
    v_end = t0 + (deadline - t0) * 0.60 + t0
    if p > 1 and c.size >= 4 and time.process_time() < v_end - 3.0:
        n_c = c.size
        levels = [n_c]
        m = n_c
        while len(levels) < 3 and m > 8:
            m = max(8, m // 4)
            if m >= levels[-1]:
                break
            levels.append(m)
        print("vcycle levels=%s" % levels)
        rrep = R_of(np.repeat(c, p))
        print("vcycle start R(repeat)=%.9f (best %.9f)" % (rrep, bestR))

        cycle = 0
        while time.process_time() < v_end - 3.0:
            cycle += 1
            print("vcycle cycle=%d" % cycle)
            best, bestR, c = _vcycle(best, bestR, p, c, v_end, levels)
            print("vcycle cycle=%d done bestR=%.9f" % (cycle, bestR))
            if cycle >= 2 and time.process_time() > v_end - 6.0:
                break

    # ---- Phase A: coarse jitter + repolish ----
    a_end = t0 + (deadline - t0) * 0.72 + t0
    if time.process_time() < a_end - 0.5:
        rng = np.random.default_rng(12345)
        c_best = c.copy()
        cR = R_of(np.repeat(c_best, p)) if p > 1 else R_of(c_best)
        accepted = 0
        rounds = 0
        while time.process_time() < a_end - 0.5:
            rounds += 1
            cj = _jitter(c_best, rng)
            cj = _lbfgs_log(cj, 150, min(a_end - 0.3,
                                         time.process_time() + 1.5))
            rj = R_of(np.repeat(cj, p)) if p > 1 else R_of(cj)
            if rj > cR + 1e-15:
                c_best, cR = cj, rj
                accepted += 1
        print("PhaseA rounds=%d accepted=%d cR=%.9f" % (rounds, accepted, cR))
        if cR > bestR + 1e-15:
            best = _rescale(np.repeat(c_best, p)) if p > 1 else _rescale(c_best)
            bestR = cR
            c = c_best

    # ---- Phase B: interpolating lift ladder ----
    b_end = t0 + (deadline - t0) * 0.82 + t0
    cur = c.copy()
    curR = R_of(np.repeat(cur, p)) if p > 1 else R_of(cur)
    for step in range(4):
        if time.process_time() >= b_end - 1.0:
            break
        if cur.size * 2 > 300000:
            break
        lifted = _interp_lift(cur)
        lifted = _lbfgs_log(lifted, 200, min(b_end - 0.5,
                                             time.process_time() + 6.0))
        rl = R_of(lifted)
        win = _peak_window(lifted, pad_frac=0.03, extra=64)
        polished = _lbfgs_block(lifted, win, 200,
                                min(b_end - 0.3,
                                    time.process_time() + 3.0), tie=True)
        rp = R_of(polished)
        if rp > rl:
            lifted, rl = polished, rp
        print("lift step=%d n=%d R=%.9f (cur %.9f)" % (step, lifted.size, rl, curR))
        if rl > curR + 1e-15:
            cur, curR = lifted, rl
        else:
            break

    # ---- Phase C: lift back to full N ----
    n_target = best.size
    if cur.size != n_target:
        if n_target % cur.size == 0:
            fac = n_target // cur.size
            full = np.repeat(cur, fac)
        else:
            full = np.interp(np.linspace(0, cur.size - 1, n_target),
                             np.arange(cur.size), cur)
    else:
        full = cur
    full = _rescale(full)
    rfull = R_of(full)
    if rfull > bestR + 1e-15:
        best, bestR = full.copy(), rfull
        print("lift ACCEPT R=%.9f" % bestR)

    # ---- Phase D: trust-region Newton ----
    d_end = t0 + (deadline - t0) * 0.90 + t0
    if time.process_time() < d_end - 1.0:
        _, c_now = _detect_repeat(best)
        if c_now.size == best.size:
            n = min(4096, best.size)
            if best.size % n == 0:
                c_now = best.reshape(-1, best.size // n).mean(axis=1)
            else:
                c_now = np.interp(np.linspace(0, best.size - 1, n),
                                  np.arange(best.size), best)
        c_now = _rescale(np.clip(c_now, 1e-30, None))
        cR0 = R_of(c_now)
        print("Newton start n_c=%d cR=%.9f" % (c_now.size, cR0))
        c_new = _trust_newton(c_now, d_end, 'trust-ncg', 1e-3)
        cRn = R_of(c_new)
        if cRn <= cR0 + 1e-15 and time.process_time() < d_end - 1.0:
            c_new2 = _trust_newton(c_now, d_end, 'trust-krylov', 1e-2)
            if R_of(c_new2) > cRn:
                c_new, cRn = c_new2, R_of(c_new2)
        print("Newton end cR=%.9f (was %.9f)" % (cRn, cR0))
        if cRn > cR0 + 1e-15:
            if best.size % c_new.size == 0:
                fac = best.size // c_new.size
                full2 = np.repeat(c_new, fac)
            else:
                full2 = np.interp(np.linspace(0, c_new.size - 1, best.size),
                                  np.arange(c_new.size), c_new)
            full2 = _rescale(full2)
            rf = R_of(full2)
            print("Newton lift R(full)=%.9f" % rf)
            if rf > bestR + 1e-15:
                best, bestR = full2.copy(), rf
                print("Newton ACCEPT R=%.9f" % bestR)

    # ---- Phase E: final peak polish ----
    c_end = deadline
    for pad in (0.06, 0.03, 0.015):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= c_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(c_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample(h, factor):
    n = h.size
    m = n * factor
    x = np.linspace(0.0, n - 1.0, m)
    return np.interp(x, np.arange(n, dtype=float), h)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=300, beta=1e6):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = -1.0

    def _record(h, tag):
        nonlocal best, bestR, alt, altR
        h = _rescale(h)
        r = R_of(h)
        zf = float(np.mean(h == 0.0))
        mm = float(h.max() / max(h.mean(), 1e-300))
        Lf = _knots(h)
        near = float(np.mean(Lf >= 0.999 * Lf.max()))
        print("%s R=%.7f N=%d zero=%.3f max/mean=%.2f near=%.4f"
              % (tag, r, h.size, zf, mm, near))
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
        elif r > altR:
            alt, altR = h.copy(), r
        return r

    # --- Stage A: local polish of start with smooth-max ladder ---
    cand = best.copy()
    candR = bestR
    refine_deadline = t0 + budget_seconds * 0.30
    for beta in (1e3, 1e4, 1e5, 1e6):
        if time.process_time() >= refine_deadline - 1.0:
            break
        hc = _lbfgs_log(cand, 120, refine_deadline, beta=beta)
        hc = _peak_ladder(hc, refine_deadline, beta=beta)
        hc = _rescale(hc)
        r = R_of(hc)
        if r > candR + 1e-13:
            cand, candR = hc, r
            _record(hc, "ref-b%.0e" % beta)
    if candR > bestR + 1e-13:
        best, bestR = cand.copy(), candR

    # --- Stage B: successive upsampling with smooth-max polish ---
    up_deadline = t0 + budget_seconds * 0.72
    cur = best.copy()
    curR = bestR
    for factor in (2, 2, 2):
        if time.process_time() >= up_deadline - 1.0:
            break
        if cur.size * factor > 900000:
            break
        hb = _rescale(_upsample(cur, factor))
        rem = up_deadline - time.process_time()
        slice_dl = min(up_deadline, time.process_time() + max(3.0, rem * 0.9))
        hb = _lbfgs_log(hb, 100, slice_dl, beta=1e5)
        hb = _peak_ladder(hb, slice_dl, beta=1e6)
        hb = _rescale(hb)
        r = _record(hb, "up%d" % factor)
        if r > curR + 1e-13:
            cur, curR = hb, r
            if curR > bestR + 1e-13:
                best, bestR = hb.copy(), curR

    # --- Stage C: final deep polish with tight peak window ---
    final = best.copy()
    finalR = bestR
    while time.process_time() < deadline - 1.5:
        improved = False
        for beta in (1e4, 1e5, 1e6, 1e7):
            if time.process_time() >= deadline - 1.5:
                break
            hc = _lbfgs_log(final, 100, deadline, beta=beta)
            hc = _peak_ladder(hc, deadline, pads=(0.08, 0.05, 0.03, 0.02), beta=beta)
            hc = _rescale(hc)
            r = R_of(hc)
            if r > finalR + 1e-13:
                final, finalR = hc, r
                improved = True
                _record(hc, "fin-b%.0e" % beta)
        if not improved:
            break

    _record(final, "final")

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_softmin(h, beta, gamma):
    """Soft-min surrogate: penalize low knots of Lf via -gamma*softmin/mx."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    z = np.clip(-beta * (Lf - mx), -60.0, 60.0)  # = beta*(mx-Lf) clipped
    e = np.exp(z)
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    # softmin = -(1/beta) log sum exp(-beta Lf)
    #         = mx - (1/beta) log sum exp(beta(mx-Lf))
    softmin = mx - np.log(Z) / beta
    # gradient of softmin wrt Lf: w (since d softmin/d Lf_j = e_j / Z)
    # tie-averaged gradient at max
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    wt = 1.0 / idx.size
    gLf[idx] += wt / mx
    # d/d Lf of (-gamma * softmin / mx) with mx treated as function of Lf:
    #   = -gamma * (w/mx - softmin * e_argmax / mx^2)
    e_arg = np.zeros_like(Lf)
    e_arg[idx] = wt
    gLf += gamma * (-w / mx + softmin * e_arg / (mx * mx))
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) - gamma * softmin / mx
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 softmin=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if softmin is not None:
        sb, sg = softmin
        fg = (lambda hh: _fun_grad_softmin(hh, sb, sg))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, softmin=None, tie=True):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)
    if softmin is not None:
        sb, sg = softmin
        fg = (lambda hh: _fun_grad_softmin(hh, sb, sg))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.exp(x)
        val, g = fg(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _bottom_frac(h, frac=0.10):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    k = max(1, int(Lf.size * frac))
    low = np.sort(Lf)[:k]
    return float(low.mean() / mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Soft-min surrogate ladder ----
    soft_end = t0 + (deadline - t0) * 0.55 + t0
    cur = best.copy()
    curR = bestR
    betas = [10.0, 100.0, 1000.0, 10000.0]
    gammas = [0.01, 0.03, 0.1]
    for beta in betas:
        b0 = _bottom_frac(cur, 0.10)
        for gamma in gammas:
            if time.process_time() >= soft_end - 1.0:
                break
            trial = _lbfgs_log(cur, 120,
                               min(soft_end - 0.5,
                                   time.process_time() + 2.5),
                               softmin=(beta, gamma), tie=False)
            rt = R_of(trial)
            # keep trial as working state for next gamma even if exact R drops,
            # but track best exact
            cur = trial
            if rt > curR + 1e-15:
                curR = rt
                if rt > bestR + 1e-15:
                    best, bestR = trial.copy(), rt
        b1 = _bottom_frac(cur, 0.10)
        print("softmin beta=%.0f bottom10%% %.5f->%.5f R=%.9f"
              % (beta, b0, b1, R_of(cur)))

    # ---- Exact tie polish on all cells ----
    pol_end = t0 + (deadline - t0) * 0.80 + t0
    for src in (cur, best):
        if time.process_time() >= pol_end - 1.0:
            break
        allc = np.arange(src.size)
        pol = _lbfgs_block(src, allc, 300,
                           min(pol_end - 0.5, time.process_time() + 4.0),
                           tie=True)
        rp = R_of(pol)
        print("exact polish R=%.9f (was %.9f)" % (rp, R_of(src)))
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    # ---- Peak-window polish ----
    c_end = deadline
    for pad in (0.05, 0.03):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= c_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(c_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx if mx > 0 else 1.0
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / max(1, idx.size)
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline,
                        beta=beta, tie=tie)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _detect_repeat(h, tol=1e-11):
    n = h.size
    for p in (2, 3, 4, 5, 6, 8, 12, 16):
        if n % p != 0:
            continue
        m = n // p
        if m < 8:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if c.sum() <= 0:
            continue
        scale = np.abs(h).max()
        if scale <= 0:
            continue
        if np.max(np.abs(H - c[:, None])) <= tol * scale:
            return p
    return 1


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all(work, 250, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
    if pads is None:
        pads = [0.25, 0.15, 0.10, 0.06]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 350, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all(work, 250, deadline - 0.3, beta=0.0, tie=True)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
    return work, best, bestR


def _lift(c, p, N):
    """Lift a quotient of period p to full resolution with interpolation."""
    m = c.size
    if p == 1:
        h = np.repeat(c, 2)
    else:
        h = np.repeat(c, p)
        if h.size < N:
            h = np.concatenate((h, np.full(N - h.size, h[-1])))
        h = h[:N]
        # smooth by convolving with small kernel per period
        if p >= 2:
            k = np.ones(p) / p
            h = np.convolve(h, k, mode='same')
    if h.size < N:
        h = np.concatenate((h, np.full(N - h.size, h[-1])))
    return _rescale(np.clip(h[:N], 0, None))


def _lift_interp(c, p, N):
    """Lift with linear interpolation between quotient samples."""
    m = c.size
    if p == 1:
        return _rescale(np.repeat(c, 2)[:N] if 2 * m >= N else
                        np.concatenate((np.repeat(c, 2), np.full(N - 2 * m, c[-1]))))
    # linear interp of c at positions i/p
    xs = np.arange(N) / float(p)
    return _rescale(np.interp(xs, np.arange(m), c) * (c.sum() > 0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    alt_best, alt_bestR = None, -1.0
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size

    # ---- Phase A: identify quotient period and do a quotient-level search ----
    period = _detect_repeat(best)
    print("detected period=%d" % period)

    if period > 1 and N % period == 0 and N // period >= 8:
        m = N // period
        q = best.reshape(m, period).mean(axis=1)
        q = _rescale(q)
        qR = R_of(q)
        print("quotient R=%.9f (m=%d, p=%d)" % (qR, m, period))

        # quotient-level optimization for a good fraction of budget
        q_deadline = t0 + budget_seconds * 0.45
        q_work = q.copy()
        q_best = q.copy()
        q_bestR = qR
        rng = np.random.RandomState(13579)
        rounds = 0
        while time.process_time() < q_deadline - 1.0:
            rounds += 1
            # full quotient polish with tie + beta
            q_work, q_best, q_bestR = _half_cycle(
                q_work, q_bestR, min(q_deadline, time.process_time() + 3.0),
                pads=[0.25, 0.15])
            # random block jitter
            nzq = np.flatnonzero(q_work > 0)
            if nzq.size >= 8:
                sigma = [0.001, 0.003, 0.01][rounds % 3]
                B = max(4, nzq.size // [40, 12, 4][rounds % 3])
                if nzq.size > B:
                    st = rng.randint(0, nzq.size - B + 1)
                    sel = nzq[st:st + B]
                else:
                    sel = nzq
                qc = q_work.copy()
                qc[sel] = qc[sel] * np.exp(sigma * rng.randn(sel.size))
                qc = _rescale(np.clip(qc, 0, None))
                now = time.process_time()
                sdl = min(now + 2.5, q_deadline - 0.5)
                if sdl > now + 0.3:
                    qc = _lbfgs_all(qc, 200, sdl, beta=1e7)
                    if time.process_time() < sdl - 0.3:
                        qc = _lbfgs_all(qc, 200, sdl, beta=0.0, tie=True)
                rc = R_of(qc)
                if rc > q_bestR + 1e-14:
                    q_work, q_best, q_bestR = qc, qc.copy(), rc
            if rounds % 3 == 0:
                print("q round %d R=%.9f" % (rounds, q_bestR))

        print("quotient done rounds=%d R=%.9f" % (rounds, q_bestR))

        # ---- Lift quotient back up with several schemes ----
        lift_deadline = min(deadline - 6.0, time.process_time() + 0.35 * budget_seconds)
        schemes = []
        schemes.append(('repeat', _lift(q_best, period, N)))
        schemes.append(('interp', _lift_interp(q_best, period, N)))
        # randomized per-block weights on top of repeat
        for s in [0.005, 0.02]:
            w = np.exp(s * rng.randn(m))
            w = w / w.mean()
            h = np.repeat(q_best, period)
            if h.size < N:
                h = np.concatenate((h, np.full(N - h.size, h[-1])))
            h = h[:N] * np.repeat(w, period)[:N]
            schemes.append(('rand%.3f' % s, _rescale(np.clip(h, 0, None))))

        for name, h in schemes:
            if time.process_time() >= lift_deadline - 0.5:
                break
            ht = h
            for beta in [1e6, 1e7]:
                if time.process_time() >= lift_deadline - 0.5:
                    break
                ht = _lbfgs_all(ht, 250, lift_deadline - 0.3, beta=beta)
            if time.process_time() < lift_deadline - 0.5:
                ht = _lbfgs_all(ht, 250, lift_deadline - 0.3, beta=0.0, tie=True)
            r = R_of(ht)
            print("lift %s R=%.9f (best %.9f)" % (name, r, bestR))
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'lift_' + name
                print("  lift NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase B: peak-focused local search on full resolution ----
    if time.process_time() < deadline - 2.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 400, deadline - 0.4, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, origin + '+pk'
                print("peak NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase C: full-resolution polish with tie ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all(best, 400, deadline - 0.4, beta=0.0, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+tie'
            print("tie polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        start = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[start:start + L] *= fac
    return c2


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _trust_newton(c0, deadline, method='trust-ncg', init_radius=1e-3):
    if time.process_time() >= deadline - 0.5:
        return c0
    c0 = np.clip(c0, 1e-30, None)
    v0 = np.sqrt(c0)

    def fg(v):
        c = v * v
        val, g = _fun_grad_tie(c)
        return val, 2.0 * v * g

    def hessp(v, w):
        eps = 1e-6 * (1.0 + np.linalg.norm(v))
        vp = v + eps * w
        vm = v - eps * w
        cp = vp * vp
        cm = vm * vm
        _, gp = _fun_grad_tie(cp)
        _, gm = _fun_grad_tie(cm)
        gvp = 2.0 * vp * gp
        gvm = 2.0 * vm * gm
        return (gvp - gvm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg, v0, jac=True, method=method, hessp=hessp,
                       callback=cb,
                       options={'maxiter': 300,
                                'initial_trust_radius': init_radius,
                                'max_trust_radius': 0.5,
                                'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None or not np.all(np.isfinite(res.x)):
        return c0
    c = res.x * res.x
    return _rescale(c)


# ---------- multi-resolution homotopy helpers ----------
def _coarse(c_in, m):
    n = c_in.size
    if m == n:
        return c_in.copy()
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 * (n / m)
    xi = np.arange(n, dtype=float) + 0.5
    return np.interp(x, xi, c_in)


def _prolong(c_coarse, m_out):
    m = c_coarse.size
    if m_out == m:
        return c_coarse.copy()
    x = np.linspace(0.0, m, m_out, endpoint=False) + 0.5 * (m_out / m)
    xi = np.arange(m, dtype=float) + 0.5
    return np.interp(x, xi, c_coarse)


def _polish_c(c, p, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return c, R_of(np.repeat(c, p))
    h = _rescale(np.repeat(c, p))
    h2 = _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=tie)
    c2 = h2.reshape(-1, p).mean(axis=1)
    hr = np.repeat(c2, p)
    return c2, R_of(hr)


def _vcycle(best, bestR, p, c, deadline, levels):
    n_c = c.size
    coarse_list = [(n_c, c.copy())]
    cur = c
    for m in levels[1:]:
        cur = _coarse(cur, m)
        coarse_list.append((m, cur.copy()))
    m, cc = coarse_list[-1]
    cc, r = _polish_c(cc, p, 80, min(deadline, time.process_time() + 3.0))
    coarse_list[-1] = (m, cc)
    print("  vcycle level=%d R=%.9f" % (m, r))
    if r > bestR + 1e-15:
        best = _rescale(np.repeat(cc, p)); bestR = r
    for i in range(len(coarse_list) - 2, -1, -1):
        m_out, _ = coarse_list[i]
        cc = _prolong(cc, m_out)
        cc, r = _polish_c(cc, p, 100,
                          min(deadline, time.process_time() + 4.0))
        coarse_list[i] = (m_out, cc)
        print("  vcycle level=%d R=%.9f" % (m_out, r))
        if r > bestR + 1e-15:
            best = _rescale(np.repeat(cc, p)); bestR = r
    return best, bestR, cc


# ---------- H22: per-block multiplier optimization ----------
def _block_R(w, c, p):
    h = np.repeat(c, p) * np.repeat(w, c.size)
    return R_of(h)


def _opt_block_w(c, p, w0, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return w0, _block_R(w0, c, p)
    n_c = c.size
    hbase = np.repeat(c, p)
    blk = np.repeat(np.arange(p), n_c).astype(float)

    def f(x):
        w = np.exp(x)
        h = hbase * np.repeat(w, n_c)
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(p)
        num, dq, Lf = _num_and_dq(h)
        mx = Lf.max()
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        gh = _backprop(gLf, h) + 2.0 / s
        gw = np.bincount(blk.astype(int), weights=gh * h, minlength=p)
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
        return val, gw

    x0 = np.log(np.clip(w0, 1e-12, None))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return w0, _block_R(w0, c, p)
    if res is None or not np.all(np.isfinite(res.x)):
        return w0, _block_R(w0, c, p)
    w = np.exp(res.x)
    return w, _block_R(w, c, p)


def _opt_block_w_sym(c, p, w0, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return w0, _block_R(w0, c, p)
    n_c = c.size
    hbase = np.repeat(c, p)
    blk = np.repeat(np.arange(p), n_c).astype(int)
    half = (p + 1) // 2
    fmap = np.empty(p, dtype=int)
    for k in range(p):
        fmap[k] = k if k < half else p - 1 - k

    def expand(x):
        w = np.exp(x)
        return w[fmap]

    def f(x):
        w = expand(x)
        h = hbase * np.repeat(w, n_c)
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(half)
        num, dq, Lf = _num_and_dq(h)
        mx = Lf.max()
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        gh = _backprop(gLf, h) + 2.0 / s
        gw_full = np.bincount(blk, weights=gh * h, minlength=p)
        gw = np.zeros(half)
        for k in range(p):
            gw[fmap[k]] += gw_full[k]
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
        return val, gw

    x0 = np.log(np.clip(w0[:half], 1e-12, None))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return w0, _block_R(w0, c, p)
    if res is None or not np.all(np.isfinite(res.x)):
        return w0, _block_R(w0, c, p)
    w = expand(res.x)
    return w, _block_R(w, c, p)


# ---------- NEW: fractional sub-cell shift optimization ----------
def _build_shifted(c, p, delta):
    """Build h of length p*n_c by interpolating block k at j+delta[k]."""
    n_c = c.size
    xi = np.arange(n_c, dtype=float)
    out = np.empty(p * n_c)
    for k in range(p):
        d = delta[k] if k < delta.size else 0.0
        out[k * n_c:(k + 1) * n_c] = np.interp(xi + d, xi, c)
    return out


def _opt_shift(c, p, delta0, deadline, maxiter=60):
    """Optimize free deltas (delta[0] fixed 0) on log R via finite diff."""
    if time.process_time() >= deadline - 0.5:
        return delta0, R_of(_build_shifted(c, p, delta0))
    nfree = p - 1
    if nfree < 1:
        return delta0, R_of(_build_shifted(c, p, delta0))

    def f(x):
        delta = np.zeros(p)
        delta[1:] = x
        h = _build_shifted(c, p, delta)
        r = R_of(h)
        if r <= 0:
            return 1e18, np.zeros(nfree)
        # finite-difference gradient on -log R
        eps = 1e-4
        g = np.zeros(nfree)
        base = -np.log(r)
        for i in range(nfree):
            xp = x.copy(); xp[i] += eps
            delta_p = np.zeros(p); delta_p[1:] = xp
            rp = R_of(_build_shifted(c, p, delta_p))
            g[i] = (-np.log(max(rp, 1e-300)) - base) / eps
        return base, g

    x0 = np.clip(delta0[1:].copy(), -8.0, 8.0)
    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       bounds=[(-8.0, 8.0)] * nfree,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-18, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return delta0, R_of(_build_shifted(c, p, delta0))
    if res is None or not np.all(np.isfinite(res.x)):
        return delta0, R_of(_build_shifted(c, p, delta0))
    delta = np.zeros(p)
    delta[1:] = res.x
    return delta, R_of(_build_shifted(c, p, delta))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- NEW Phase S: fractional sub-cell shift optimization ----
    s_end = t0 + (deadline - t0) * 0.45 + t0
    if p > 1 and c.size >= 4 and time.process_time() < s_end - 2.0:
        n_c = c.size
        # verify exact repeat
        is_exact = (best.size == p * n_c and
                    np.allclose(best, np.repeat(c, p), rtol=1e-12, atol=1e-15))
        print("shift exact_repeat=%s" % is_exact)
        if is_exact:
            delta_best = np.zeros(p)
            r_best = R_of(_build_shifted(c, p, delta_best))
            print("shift start R=%.9f" % r_best)
            k = np.arange(p, dtype=float)
            starts = [np.zeros(p)]
            alt = np.where(k % 2 == 0, 0.5, -0.5)
            starts.append(alt)
            for a in (0.5, 1.0, 2.0):
                starts.append(a * np.cos(2.0 * np.pi * k / p))
            for i, d0 in enumerate(starts):
                if time.process_time() >= s_end - 1.0:
                    break
                d0 = d0.copy(); d0[0] = 0.0
                d, r = _opt_shift(c, p, d0,
                                  min(s_end - 0.5,
                                      time.process_time() + 4.0))
                print("shift start %d R=%.9f" % (i, r))
                if r > r_best + 1e-15:
                    delta_best, r_best = d, r
            print("shift best R=%.9f (base %.9f)" % (r_best, bestR))
            if r_best > bestR + 1e-15:
                h_new = _rescale(_build_shifted(c, p, delta_best))
                rn = R_of(h_new)
                if rn > bestR + 1e-15:
                    best, bestR = h_new, rn
                    print("shift ACCEPT R=%.9f" % bestR)

    # ---- Phase H22: per-block multiplier optimization ----
    h22_end = t0 + (deadline - t0) * 0.55 + t0
    if p > 1 and c.size >= 4 and time.process_time() < h22_end - 1.0:
        w_best = np.ones(p)
        wR = _block_R(w_best, c, p)
        print("H22 start wR=%.9f" % wR)
        k = np.arange(p, dtype=float)
        starts = [np.ones(p)]
        for a in (0.1, 0.3, 0.6):
            starts.append(1.0 + a * np.cos(np.pi * k / (p - 1)))
        for b in (0.1, 0.3):
            starts.append(1.0 + b * ((k - (p - 1) / 2.0) / ((p - 1) / 2.0)) ** 2)
        for i, w0 in enumerate(starts):
            if time.process_time() >= h22_end - 1.0:
                break
            w0 = np.clip(w0, 1e-6, None)
            w, r = _opt_block_w(c, p, w0,
                                min(h22_end - 0.5, time.process_time() + 3.0))
            print("H22 start %d wR=%.9f" % (i, r))
            if r > wR + 1e-15:
                w_best, wR = w, r
        if time.process_time() < h22_end - 1.0:
            w, r = _opt_block_w_sym(c, p, w_best,
                                    min(h22_end - 0.5, time.process_time() + 3.0))
            print("H22 sym wR=%.9f" % r)
            if r > wR + 1e-15:
                w_best, wR = w, r
        print("H22 best wR=%.9f (base %.9f)" % (wR, bestR))
        if wR > bestR + 1e-15:
            h_new = np.repeat(c, p) * np.repeat(w_best, c.size)
            h_new = _rescale(h_new)
            rn = R_of(h_new)
            if rn > bestR + 1e-15:
                best, bestR = h_new, rn
                print("H22 ACCEPT R=%.9f" % bestR)

    # ---- Phase V: multi-resolution V-cycles ----
    v_end = t0 + (deadline - t0) * 0.70 + t0
    if p > 1 and c.size >= 4 and time.process_time() < v_end - 3.0:
        n_c = c.size
        levels = [n_c]
        m = n_c
        while len(levels) < 3 and m > 8:
            m = max(8, m // 4)
            if m >= levels[-1]:
                break
            levels.append(m)
        print("vcycle levels=%s" % levels)
        rrep = R_of(np.repeat(c, p))
        print("vcycle start R(repeat)=%.9f (best %.9f)" % (rrep, bestR))

        cycle = 0
        while time.process_time() < v_end - 3.0:
            cycle += 1
            print("vcycle cycle=%d" % cycle)
            best, bestR, c = _vcycle(best, bestR, p, c, v_end, levels)
            print("vcycle cycle=%d done bestR=%.9f" % (cycle, bestR))
            if cycle >= 2 and time.process_time() > v_end - 6.0:
                break

    # ---- Phase A: coarse jitter + repolish ----
    a_end = t0 + (deadline - t0) * 0.80 + t0
    if time.process_time() < a_end - 0.5:
        rng = np.random.default_rng(12345)
        c_best = c.copy()
        cR = R_of(np.repeat(c_best, p)) if p > 1 else R_of(c_best)
        accepted = 0
        rounds = 0
        while time.process_time() < a_end - 0.5:
            rounds += 1
            cj = _jitter(c_best, rng)
            cj = _lbfgs_log(cj, 150, min(a_end - 0.3,
                                         time.process_time() + 1.5))
            rj = R_of(np.repeat(cj, p)) if p > 1 else R_of(cj)
            if rj > cR + 1e-15:
                c_best, cR = cj, rj
                accepted += 1
        print("PhaseA rounds=%d accepted=%d cR=%.9f" % (rounds, accepted, cR))
        if cR > bestR + 1e-15:
            best = _rescale(np.repeat(c_best, p)) if p > 1 else _rescale(c_best)
            bestR = cR
            c = c_best

    # ---- Phase B: interpolating lift ladder ----
    b_end = t0 + (deadline - t0) * 0.86 + t0
    cur = c.copy()
    curR = R_of(np.repeat(cur, p)) if p > 1 else R_of(cur)
    for step in range(4):
        if time.process_time() >= b_end - 1.0:
            break
        if cur.size * 2 > 300000:
            break
        lifted = _interp_lift(cur)
        lifted = _lbfgs_log(lifted, 200, min(b_end - 0.5,
                                             time.process_time() + 6.0))
        rl = R_of(lifted)
        win = _peak_window(lifted, pad_frac=0.03, extra=64)
        polished = _lbfgs_block(lifted, win, 200,
                                min(b_end - 0.3,
                                    time.process_time() + 3.0), tie=True)
        rp = R_of(polished)
        if rp > rl:
            lifted, rl = polished, rp
        print("lift step=%d n=%d R=%.9f (cur %.9f)" % (step, lifted.size, rl, curR))
        if rl > curR + 1e-15:
            cur, curR = lifted, rl
        else:
            break

    # ---- Phase C: lift back to full N ----
    n_target = best.size
    if cur.size != n_target:
        if n_target % cur.size == 0:
            fac = n_target // cur.size
            full = np.repeat(cur, fac)
        else:
            full = np.interp(np.linspace(0, cur.size - 1, n_target),
                             np.arange(cur.size), cur)
    else:
        full = cur
    full = _rescale(full)
    rfull = R_of(full)
    if rfull > bestR + 1e-15:
        best, bestR = full.copy(), rfull
        print("lift ACCEPT R=%.9f" % bestR)

    # ---- Phase D: trust-region Newton ----
    d_end = t0 + (deadline - t0) * 0.91 + t0
    if time.process_time() < d_end - 1.0:
        _, c_now = _detect_repeat(best)
        if c_now.size == best.size:
            n = min(4096, best.size)
            if best.size % n == 0:
                c_now = best.reshape(-1, best.size // n).mean(axis=1)
            else:
                c_now = np.interp(np.linspace(0, best.size - 1, n),
                                  np.arange(best.size), best)
        c_now = _rescale(np.clip(c_now, 1e-30, None))
        cR0 = R_of(c_now)
        print("Newton start n_c=%d cR=%.9f" % (c_now.size, cR0))
        c_new = _trust_newton(c_now, d_end, 'trust-ncg', 1e-3)
        cRn = R_of(c_new)
        if cRn <= cR0 + 1e-15 and time.process_time() < d_end - 1.0:
            c_new2 = _trust_newton(c_now, d_end, 'trust-krylov', 1e-2)
            if R_of(c_new2) > cRn:
                c_new, cRn = c_new2, R_of(c_new2)
        print("Newton end cR=%.9f (was %.9f)" % (cRn, cR0))
        if cRn > cR0 + 1e-15:
            if best.size % c_new.size == 0:
                fac = best.size // c_new.size
                full2 = np.repeat(c_new, fac)
            else:
                full2 = np.interp(np.linspace(0, c_new.size - 1, best.size),
                                  np.arange(c_new.size), c_new)
            full2 = _rescale(full2)
            rf = R_of(full2)
            print("Newton lift R(full)=%.9f" % rf)
            if rf > bestR + 1e-15:
                best, bestR = full2.copy(), rf
                print("Newton ACCEPT R=%.9f" % bestR)

    # ---- Phase E: final peak polish ----
    c_end = deadline
    for pad in (0.06, 0.03, 0.015):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= c_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(c_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase: large-window tie-aware polish targeting the peak region
    h = best.copy()
    n = h.size
    win = _peak_window(h, pad_frac=0.15, extra=512)
    if win.size < n:
        ht = _lbfgs_block(h, win, 800, min(deadline, time.process_time() + 12.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("wide-peak tie ACCEPT R=%.9f" % bestR)

    # Phase: full tie polish
    if time.process_time() < deadline - 4.0:
        ht = _lbfgs_block(best, np.arange(best.size), 800,
                          min(deadline - 1.0, time.process_time() + 15.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("full tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))

    # Phase: beta smooth-max ladder with shrinking beta
    for beta in (1e6, 1e5, 1e4, 1e3, 1e2):
        if time.process_time() > deadline - 3.0:
            break
        win = _peak_window(best, pad_frac=0.10, extra=256)
        ht = _lbfgs_block(best, win, 400,
                          min(deadline - 1.0, time.process_time() + 5.0), beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("beta=%.0e ACCEPT R=%.9f" % (beta, bestR))

    # Phase: extra tie passes with slightly different peak window
    for pad in (0.20, 0.08, 0.05, 0.03):
        if time.process_time() > deadline - 2.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400,
                          min(deadline - 0.5, time.process_time() + 4.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("pad=%.2f ACCEPT R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h, beta=1e7):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=1e7):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


# --- NEW IDEA: fine-grained sliding-window polish ---------------------------
# The global gradient stalls because the active max constraint is a single
# knot. Instead, sweep many small overlapping windows across the whole
# support (and especially around the peak) with a smooth beta tie-breaker.
# Each window is small so L-BFGS converges fast; the sweep lets the shape
# creep upward in tiny coordinated steps that global descent cannot find.

def _sweep(h, deadline, winsz, stride, iters=40, beta=1e6, rounds=1):
    N = h.size
    for _ in range(rounds):
        pos = 0
        while pos < N:
            if time.process_time() > deadline - 0.5:
                return h
            lo = pos
            hi = min(N, pos + winsz)
            win = np.arange(lo, hi)
            ht = _lbfgs_block(h, win, iters, deadline - 0.4, beta)
            r0 = R_of(h); r1 = R_of(ht)
            if r1 > r0 + 1e-15:
                h = ht
            pos += stride
    return h


def _peak_sweep(h, deadline, iters=60):
    # dense sweep concentrated around the peak of f*f
    N = h.size
    win = _peak_window(h, tol=0.99, pad_frac=0.5, extra=512)
    if win.size == 0:
        return h
    lo, hi = int(win[0]), int(win[-1]) + 1
    span = hi - lo
    for winsz_frac in (0.5, 0.3, 0.18, 0.1, 0.05):
        if time.process_time() > deadline - 0.5:
            break
        winsz = max(32, int(span * winsz_frac))
        stride = max(8, winsz // 3)
        h = _sweep(h, deadline, winsz, stride, iters=iters, beta=1e6, rounds=1)
        h = _sweep(h, deadline, winsz, stride, iters=iters, beta=1e7, rounds=1)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)

    startR = R_of(best)
    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt = None
    altR = -1.0

    # Phase 1: short global L-BFGS to settle (smooth beta objective)
    ph1 = t0 + budget_seconds * 0.12
    if time.process_time() < ph1 - 1.0:
        ht = _lbfgs_block(best, np.arange(N), 250, ph1 - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P1 global R=%.9f" % bestR)

    # Phase 2: peak-focused fine sweep — the new idea
    ph2 = t0 + budget_seconds * 0.55
    if time.process_time() < ph2 - 2.0:
        ht = _peak_sweep(best.copy(), ph2 - 0.5, iters=50)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P2 peak sweep R=%.9f" % bestR)
        else:
            alt, altR = ht.copy(), r

    # Phase 3: whole-support fine sweep at multiple scales
    ph3 = t0 + budget_seconds * 0.82
    for winsz in (512, 256, 128, 64):
        if time.process_time() > ph3 - 2.0:
            break
        winsz = min(winsz, N)
        stride = max(8, winsz // 3)
        ht = _sweep(best.copy(), ph3 - 0.5, winsz, stride,
                    iters=35, beta=1e7, rounds=1)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P3 sweep w=%d R=%.9f" % (winsz, bestR))

    # Phase 4: final global polish
    fd = t0 + budget_seconds * 0.93
    if time.process_time() < fd - 1.5:
        ht = _lbfgs_block(best, np.arange(N), 300, fd - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P4 final R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt is not None and altR > startR + 1e-15 and bestR <= startR + 1e-14:
        result["alternative"] = alt
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_softmin(h, beta, gamma):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    z = np.clip(-beta * (Lf - mx), -60.0, 60.0)
    e = np.exp(z)
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    softmin = mx - np.log(Z) / beta
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    wt = 1.0 / idx.size
    gLf[idx] += wt / mx
    e_arg = np.zeros_like(Lf)
    e_arg[idx] = wt
    gLf += gamma * (-w / mx + softmin * e_arg / (mx * mx))
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) - gamma * softmin / mx
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 softmin=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if softmin is not None:
        sb, sg = softmin
        fg = (lambda hh: _fun_grad_softmin(hh, sb, sg))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, softmin=None, tie=True):
    if time.process_time() >= deadline - 0.2:
