    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _bottom_frac(h, frac=0.10):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    k = max(1, int(Lf.size * frac))
    low = np.sort(Lf)[:k]
    return float(low.mean() / mx)


# ---- repeat-family optimization: optimize c at fixed repeat count p ----
def _lbfgs_repeat(c0, p, maxiter, deadline):
    """Optimize c (log-param) so that h=np.tile(c,p) maximizes exact tie R."""
    if time.process_time() >= deadline - 0.2:
        return c0
    n_c = c0.size
    c = np.clip(c0, 1e-30, None)
    x0 = np.log(c)

    def f(x):
        cc = np.exp(x)
        h = np.tile(cc, p)
        val, g = _fun_grad_tie(h)
        gc = g.reshape(p, n_c).sum(axis=0)
        return val, gc * cc

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.exp(res.x)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Detect exact 32-repeat structure ----
    n_c = None
    c_orig = None
    if best.size % 32 == 0:
        n_c = best.size // 32
        rows = best.reshape(32, n_c)
        if np.all(np.abs(rows - rows[0]) <= 1e-12 * (np.abs(rows[0]).max() + 1e-300)):
            c_orig = rows[0].copy()
            print("detected 32-repeat, n_c=%d" % n_c)

    if c_orig is not None:
        # ---- Sweep repeat counts p, optimizing c at each ----
        ps = [1, 2, 4, 8, 16, 32, 64, 128, 256]
        best_c = c_orig.copy()
        best_p = 32
        bestRepR = bestR
        sweep_end = t0 + (deadline - t0) * 0.55
        for p in ps:
            if time.process_time() >= sweep_end - 1.0:
                break
            for cstart in (c_orig, best_c):
                if time.process_time() >= sweep_end - 0.8:
                    break
                tlim = min(sweep_end - 0.5, time.process_time() + 3.0)
                cc = _lbfgs_repeat(cstart, p, 80, tlim)
                h = np.tile(cc, p)
                r = R_of(h)
                if r > bestRepR + 1e-15:
                    bestRepR = r
                    best_c = cc.copy()
                    best_p = p
                    if r > bestR + 1e-15:
                        best = h.copy()
                        bestR = r
            # report best R achievable at this p from c_orig
            h_orig = np.tile(c_orig, p)
            print("p=%d N=%d R=%.12f" % (p, h_orig.size, R_of(h_orig)))
        print("winning p=%d R=%.12f" % (best_p, bestRepR))

        # ---- Full exact tie polish on best p ----
        if time.process_time() < deadline - 2.0:
            h_bp = np.tile(best_c, best_p)
            pol_end = min(deadline - 1.0, time.process_time() + 4.0)
            pol = _lbfgs_block(h_bp, np.arange(h_bp.size), 200, pol_end, tie=True)
            rp = R_of(pol)
            print("exact polish p=%d R=%.12f (was %.12f)" % (best_p, rp, R_of(h_bp)))
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

        # ---- Peak-window tie polish ----
        for pad in (0.08, 0.04, 0.02):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=96)
            tlim = min(deadline - 0.5, time.process_time() + 3.0)
            ht = _lbfgs_block(best, win, 300, tlim, tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
            print("peak pad=%.3f R=%.12f" % (pad, bestR))
    else:
        # Fallback: original base pipeline (softmin ladder + polish)
        soft_end = t0 + (deadline - t0) * 0.55
        cur = best.copy()
        curR = bestR
        for beta in [10.0, 100.0, 1000.0, 10000.0]:
            for gamma in [0.01, 0.03, 0.1]:
                if time.process_time() >= soft_end - 1.0:
                    break
                trial = _lbfgs_log(cur, 120,
                                   min(soft_end - 0.5, time.process_time() + 2.5),
                                   softmin=(beta, gamma), tie=False)
                rt = R_of(trial)
                cur = trial
                if rt > curR + 1e-15:
                    curR = rt
                    if rt > bestR + 1e-15:
                        best, bestR = trial.copy(), rt
        pol_end = t0 + (deadline - t0) * 0.80
        for src in (cur, best):
            if time.process_time() >= pol_end - 1.0:
                break
            pol = _lbfgs_block(src, np.arange(src.size), 300,
                               min(pol_end - 0.5, time.process_time() + 4.0), tie=True)
            rp = R_of(pol)
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp
        for pad in (0.05, 0.03):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=96)
            ht = _lbfgs_block(best, win, 300,
                              min(deadline - 0.5, time.process_time() + 3.0), tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _gauss_smooth(h, sigma):
    if sigma <= 0.5:
        return h.copy()
    r = int(3 * sigma) + 1
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def _smooth_perturb(h, sigma, amp, seed):
    n = h.size
    rng = np.random.RandomState(seed)
    m = max(16, n // 64)
    noise = rng.randn(m)
    xp = np.linspace(0, 1, m)
    xi = np.linspace(0, 1, n)
    p = np.interp(xi, xp, noise)
    return np.clip(h * np.exp(amp * p), 0, None)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-6)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    alt = None
    altR = 0.0

    # NEW: coarse-to-fine on a fresh smaller grid. Rebuild the current best as a
    # coarser representation, smooth it heavily, re-optimise from scratch, then
    # prolongate back. This lets the search escape the fine-grid basin that has
    # trapped the incumbent (which has a wide but not flat peak).
    if time.process_time() < deadline - 25.0:
        for Nc in (max(2048, N // 8), max(4096, N // 4), max(8192, N // 2)):
            if time.process_time() >= deadline - 22.0:
                break
            hc = _coarse(best, Nc)
            hc = _gauss_smooth(hc, sigma=max(2.0, Nc / 200.0))
            hc = _rescale(hc)
            hc = _lbfgs_log(hc, 800, deadline)
            hc = _window_polish_peak(hc, deadline, 0.6, 64)
            hc = _lbfgs_log(hc, 600, deadline)
            rc = R_of(hc)
            hp = _prolongate(hc, N)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 600, deadline)
            hp = _window_polish_peak(hp, deadline, 0.5, 32)
            hp = _lbfgs_log(hp, 400, deadline)
            rp = R_of(hp)
            print("ctf %d: rc=%.7f rp=%.7f ties=%d" % (Nc, rc, rp, _tie_count(hp)))
            if rp > altR:
                alt, altR = hp, rp
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("ctf wins R=%.7f" % bestR)

    # beta-anneal continuation aimed at flattening a multi-knot peak.
    if time.process_time() < deadline - 15.0:
        h = best.copy()
        for beta in (10.0, 40.0, 150.0, 500.0, 2000.0):
            if time.process_time() >= deadline - 12.0:
                break
            h = _lbfgs_log(h, 500, deadline, beta=beta)
            h = _window_polish_peak(h, deadline, 0.5, 48, beta=beta)
            r = R_of(h)
            print("beta %.0f R=%.7f ties=%d" % (beta, r, _tie_count(h)))
        h = _lbfgs_log(h, 800, deadline)
        h = _window_polish_peak(h, deadline, 0.5, 32)
        h = _lbfgs_log(h, 600, deadline)
        r = R_of(h)
        print("beta-anneal R=%.7f" % r)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("beta wins R=%.7f" % bestR)

    # Multiplicative perturbations from the current best.
    perturb_specs = [
        (max(2.0, N / 400.0), 0.04, 11),
        (max(2.0, N / 200.0), 0.06, 12),
        (max(3.0, N / 100.0), 0.05, 13),
        (max(3.0, N / 100.0), 0.09, 14),
    ]
    for sigma, amp, seed in perturb_specs:
        if time.process_time() >= deadline - 8.0:
            break
        hp = _smooth_perturb(best, sigma, amp, seed)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 500, deadline)
        hp = _window_polish_peak(hp, deadline, 0.4, 24)
        hp = _lbfgs_log(hp, 400, deadline)
        r = R_of(hp)
        print("perturb s=%.1f a=%.2f R=%.7f" % (sigma, amp, r))
        if r > altR:
            alt, altR = hp, r
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("perturb wins R=%.7f" % bestR)

    # Peak-focused polish at growing windows.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.2f) R=%.7f" % (frac, bestR))

    # Final alternating polish until budget exhausted.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

