def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_topq(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = max(1, int(round((1.0 - q) * n)))
    k = min(k, n)
    if k >= n:
        idx = np.arange(n)
    else:
        idx = np.argpartition(Lf, -k)[-k:]
    m = Lf[idx].mean()
    if m <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    gLf[idx] += 1.0 / (k * m)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(m)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False, q=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if q is not None:
        fg = (lambda hh: _fun_grad_topq(hh, q))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(start, Nf):
    start = np.asarray(start, dtype=float)
    n = start.size
    if n == Nf:
        return start.copy()
    c = np.concatenate([[0.0], np.cumsum(start)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nf)
    xs = np.linspace(0.0, 1.0, Nf + 1)
    old = np.linspace(0.0, 1.0, n + 1)
    cm = np.interp(xs, old, c)
    h = np.diff(cm) * Nf
    return h


def _prolongate(h):
    return _resample(h, h.size * 2)


def _polish(h, deadline, tie_iters, beta_iters, pads, betas=(1e3, 1e5, 1e7)):
    best = h.copy()
    best_r = R_of(best)

    if time.process_time() < deadline - 0.3:
        h1 = _lbfgs_all_pos(best, tie_iters, deadline, tie=True)
        r1 = R_of(h1)
        if r1 > best_r:
            best, best_r = h1, r1

    for beta in betas:
        if time.process_time() >= deadline - 0.3:
            break
        hb = _lbfgs_all_pos(best, beta_iters, deadline, beta=beta)
        rb = R_of(hb)
        if rb > best_r:
            best, best_r = hb, rb

    for pad in pads:
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(best, tol=0.999, pad_frac=pad, extra=128)
        hw = _lbfgs_block(best, win, 150, deadline, tie=True)
        rw = R_of(hw)
        if rw > best_r:
            best, best_r = hw, rw

    return best, best_r


def _envelope_jitter(h, rng, nmodes=4, amp=0.004):
    N = h.size
    i = np.arange(N)
    x = (i + 0.5) / N
    env = np.ones(N)
    for m in range(1, nmodes + 1):
        a = rng.normal(0.0, amp)
        env += a * np.cos(2.0 * np.pi * m * x)
    env = np.clip(env, 0.2, 5.0)
    return h * env


def _window_jitter(h, rng, nwin=4):
    N = h.size
    trial = h.copy()
    for _ in range(nwin):
        wlen = int(rng.uniform(0.005, 0.05) * N)
        wlen = max(4, min(N, wlen))
        lo = int(rng.integers(0, N - wlen + 1))
        sigma = rng.uniform(0.005, 0.03)
        trial[lo:lo + wlen] *= np.exp(rng.normal(0.0, sigma, wlen))
    return trial


def _near01(h):
    Lf = _knots(h)
    mx = Lf.max()
    return float(np.mean(Lf >= 0.999 * mx)) if mx > 0 else 0.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        seed = np.asarray(start, dtype=float).copy()
    else:
        N0 = 4096
        xk = (np.arange(N0) + 0.5) / N0
        seed = 1.0 / np.sqrt(np.maximum(xk * (1 - xk), 1e-3))
        seed = np.minimum(seed, 4.0 * np.mean(seed))

    best = seed.copy()
    best_r = R_of(best)
    print(f"start R={best_r:.9f} N={best.size} near01={_near01(best):.4f}")

    # (A) top-quantile CVaR ladder on all heights
    for q in (0.90, 0.75, 0.60, 0.45):
        if time.process_time() >= deadline - 0.5:
            break
        st = min(deadline, time.process_time() + 3.0)
        hq = _lbfgs_all_pos(best, 60, st, q=q)
        rq_raw = R_of(hq)
        # exact tie polish after each q
        if time.process_time() < deadline - 0.5:
            st2 = min(deadline, time.process_time() + 2.0)
            hp = _lbfgs_all_pos(hq, 120, st2, tie=True)
            rp = R_of(hp)
        else:
            hp, rp = hq, rq_raw
        if rp > best_r:
            best, best_r = hp, rp
            tag = "ACCEPT"
        elif rq_raw > best_r:
            best, best_r = hq, rq_raw
            tag = "raw-accept"
        else:
            tag = "revert"
        print(f"q={q:.2f} top_frac={1.0-q:.3f} exactR={rp:.9f} "
              f"raw={rq_raw:.9f} near01={_near01(best):.4f} {tag}")

    # (B) peak-window tie polish
    for pad in (0.10, 0.05, 0.02):
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, tol=0.999, pad_frac=pad, extra=128)
        hw = _lbfgs_block(best, win, 150, deadline, tie=True)
        rw = R_of(hw)
        if rw > best_r:
            best, best_r = hw, rw
            print(f"pad={pad:.2f} ACCEPT R={best_r:.9f} near01={_near01(best):.4f}")
        else:
            print(f"pad={pad:.2f} revert R={rw:.9f}")

    # (C) structured jitter loop with remaining time
    rng = np.random.default_rng(20240517)
    k = 0
    while time.process_time() < deadline - 0.5:
        k += 1
        seed_h = best.copy()
        seed_r = best_r

        trial = _envelope_jitter(seed_h, rng, nmodes=4, amp=0.004)
        trial = _window_jitter(trial, rng, nwin=4)
        trial = _rescale(trial)

        rem = deadline - time.process_time()
        if rem < 0.5:
            break
        st = min(deadline, time.process_time() + rem * 0.7)
        ht = _lbfgs_all_pos(trial, 150, st, tie=True)
        rt = R_of(ht)
        if rt > seed_r:
            st2 = min(deadline, time.process_time() + (deadline - time.process_time()) * 0.6)
            hb = _lbfgs_all_pos(ht, 80, st2, beta=1e7)
            rb = R_of(hb)
            if rb > rt:
                ht, rt = hb, rb
        if rt > seed_r:
            for pad in (0.05, 0.02):
                if time.process_time() >= deadline - 0.4:
                    break
                win = _peak_window(ht, tol=0.999, pad_frac=pad, extra=64)
                hw = _lbfgs_block(ht, win, 100, deadline, tie=True)
                rw = R_of(hw)
                if rw > rt:
                    ht, rt = hw, rw
        if rt > best_r:
            best, best_r = ht, rt
            accepted = "ACCEPT"
        else:
            accepted = "revert"
        print(f"round {k} N={best.size} R={rt:.9f} best={best_r:.9f} "
              f"near01={_near01(best):.4f} {accepted}")

    # (D) final full tie polish
    if time.process_time() < deadline - 0.4:
        hf = _lbfgs_all_pos(best, 200, deadline, tie=True)
        rf = R_of(hf)
        if rf > best_r:
            best, best_r = hf, rf

    print(f"final R={best_r:.9f} N={best.size} near01={_near01(best):.4f}")

    if start is not None:
        rs = R_of(np.asarray(start, dtype=float))
        if best_r >= rs:
            return best
        else:
            return {"best": np.asarray(start, dtype=float), "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_lav(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _upsample(h, factor):
    if factor <= 1:
        return h.copy()
    n = h.size
    m = n * factor
    x = np.linspace(0, n, m, endpoint=False)
    xi = np.arange(n)
    return np.interp(x, xi, h)


def _sharpen(h, deadline, iters=120):
    if time.process_time() >= deadline - 1.0:
        return h
    hb = _lbfgs_log(h, iters, deadline,
                    fg=lambda hh: _fun_grad_lav(hh, 9))
    hs = _lbfgs_log(hb, 40, deadline)
    return hs


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d) Lmax=%.6e argmax=%d near=%d" %
          (bestR, best.size, mx0, m0, near0))

    cur = best.copy()
    curR = bestR
    # Track a genuinely-different construction (from upsampling) as alternative
    alt = None
    altR = 0.0

    # ---- Phase 1: heavy sharpen + polish loop on current resolution ----
    stage = 0
    while time.process_time() < deadline - 8.0:
        stage += 1
        improved = False
        for kk in (15, 11, 9, 7, 5, 3, 1):
            if time.process_time() >= deadline - 6.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, 60, deadline, fg=fg)
            hs = _lbfgs_log(hb, 12, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.12, 48, maxiter=100)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 1e-13:
                cur, curR = cand, rc
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  stage %d k=%d R=%.7f" % (stage, kk, curR))
        if not improved:
            break

    # ---- Phase 2: try upsampling to escape resolution limit ----
    for factor in (2, 2):
        if time.process_time() >= deadline - 10.0:
            break
        n_new = cur.size * factor
        if n_new > 900000:
            break
        up = _rescale(_upsample(cur, factor))
        r_up = R_of(up)
        print("  upsample x%d -> N=%d R=%.7f (was %.7f)" %
              (factor, up.size, r_up, curR))
        cand = up
        rc = r_up
        for kk in (9, 5, 3, 1):
            if time.process_time() >= deadline - 8.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cand, 60, deadline, fg=fg)
            hs = _lbfgs_log(hb, 12, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 64, maxiter=100)
            rp = R_of(hp)
            if rp > rs:
                hs, rs = hp, rp
            if rs > rc:
                cand, rc = hs, rs
        # Record the upsampled construction as the genuinely-different alternative
        if rc > altR:
            alt, altR = cand.copy(), rc
        if rc > curR - 1e-9:
            cur, curR = cand, rc
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
            print("  refined R=%.7f" % curR)

    # ---- Phase 3: final extended polish ----
    while time.process_time() < deadline - 2.0:
        improved = False
        for (kk, iters) in [(11, 80), (7, 100), (5, 120), (3, 150), (1, 150)]:
            if time.process_time() >= deadline - 3.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, iters, deadline, fg=fg)
            hs = _lbfgs_log(hb, 10, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=120)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  final k=%d R=%.7f" % (kk, curR))
        if not improved:
            break

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
