import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_lav(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _upsample(h, factor):
    if factor <= 1:
        return h.copy()
    n = h.size
    m = n * factor
    x = np.linspace(0, n, m, endpoint=False)
    xi = np.arange(n)
    return np.interp(x, xi, h)


def _sharpen(h, deadline, iters=120):
    if time.process_time() >= deadline - 1.0:
        return h
    hb = _lbfgs_log(h, iters, deadline,
                    fg=lambda hh: _fun_grad_lav(hh, 9))
    hs = _lbfgs_log(hb, 40, deadline)
    return hs


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d) Lmax=%.6e argmax=%d near=%d" %
          (bestR, best.size, mx0, m0, near0))

    cur = best.copy()
    curR = bestR
    # Track a genuinely-different construction (from upsampling) as alternative
    alt = None
    altR = 0.0

    # ---- Phase 1: heavy sharpen + polish loop on current resolution ----
    stage = 0
    while time.process_time() < deadline - 8.0:
        stage += 1
        improved = False
        for kk in (15, 11, 9, 7, 5, 3, 1):
            if time.process_time() >= deadline - 6.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, 60, deadline, fg=fg)
            hs = _lbfgs_log(hb, 12, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.12, 48, maxiter=100)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 1e-13:
                cur, curR = cand, rc
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  stage %d k=%d R=%.7f" % (stage, kk, curR))
        if not improved:
            break

    # ---- Phase 2: try upsampling to escape resolution limit ----
    for factor in (2, 2):
        if time.process_time() >= deadline - 10.0:
            break
        n_new = cur.size * factor
        if n_new > 900000:
            break
        up = _rescale(_upsample(cur, factor))
        r_up = R_of(up)
        print("  upsample x%d -> N=%d R=%.7f (was %.7f)" %
              (factor, up.size, r_up, curR))
        cand = up
        rc = r_up
        for kk in (9, 5, 3, 1):
            if time.process_time() >= deadline - 8.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cand, 60, deadline, fg=fg)
            hs = _lbfgs_log(hb, 12, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 64, maxiter=100)
            rp = R_of(hp)
            if rp > rs:
                hs, rs = hp, rp
            if rs > rc:
                cand, rc = hs, rs
        # Record the upsampled construction as the genuinely-different alternative
        if rc > altR:
            alt, altR = cand.copy(), rc
        if rc > curR - 1e-9:
            cur, curR = cand, rc
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
            print("  refined R=%.7f" % curR)

    # ---- Phase 3: final extended polish ----
    while time.process_time() < deadline - 2.0:
        improved = False
        for (kk, iters) in [(11, 80), (7, 100), (5, 120), (3, 150), (1, 150)]:
            if time.process_time() >= deadline - 3.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, iters, deadline, fg=fg)
            hs = _lbfgs_log(hb, 10, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=120)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  final k=%d R=%.7f" % (kk, curR))
        if not improved:
            break

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d) Lmax=%.6e argmax=%d near=%d" %
          (bestR, best.size, mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    # Nothing beat start: keep start as best, offer genuinely-different upsampled
    # construction as alternative so new search lines can branch from it.
    if alt is not None and alt.size != start_best.size:
        return {"best": start_best, "alternative": alt}
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_beta(h, 0.0)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_beta(h, 0.0)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(h, np.arange(h.size), iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _resample_to(h, N):
    h = np.clip(h, 0, None)
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(N)
    tgt = np.linspace(0.0, total, N + 1)
    edges = np.interp(tgt, c, np.arange(n + 1, dtype=float))
    newh = np.diff(edges)
    return np.clip(newh, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(98765)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size

    # ---- Phase 1: alternating half-resolution refinement ----
    # Build a coarser representation, polish it hard, then lift back.
    # This escapes fine-scale local optima by smoothing.
    p1_deadline = min(deadline - 5.0, time.process_time() + budget_seconds * 0.45)
    work = best.copy()
    workR = bestR
    rounds = 0
    while time.process_time() < p1_deadline - 1.5:
        rounds += 1
        # Coarsen by averaging pairs (half resolution), polish, then upsample.
        m = N // 2
        if m < 16:
            break
        c = work[0:2 * m].reshape(m, 2).mean(axis=1)
        c = _rescale(c)
        cR0 = R_of(c)
        c = _polish_ladder(c, p1_deadline - 0.6, betas=(1e7, 1e8, 1e9, 0.0), iters=280)
        c = _peak_ladder(c, p1_deadline - 0.6,
                         pads=(0.20, 0.12, 0.08, 0.05), iters=320)
        cR1 = R_of(c)
        if time.process_time() >= p1_deadline - 0.6:
            break
        # Lift back with small per-pair perturbation to break symmetry.
        w = np.clip(np.exp(rng.normal(0.0, 0.25, 2)), 0.4, 2.5)
        f2 = np.repeat(c, 2) * np.tile(w, m)
        f2 = _rescale(f2)
        f2 = _polish_ladder(f2, p1_deadline - 0.6, betas=(1e8, 1e9, 0.0), iters=280)
        f2 = _peak_ladder(f2, p1_deadline - 0.6,
                          pads=(0.08, 0.05, 0.03), iters=280)
        cand = _resample_to(f2, N)
        cand = _rescale(cand)
        cand = _polish_ladder(cand, p1_deadline - 0.6, betas=(1e9, 0.0), iters=250)
        r = R_of(cand)
        if cand.size == best.size and r > workR + 1e-14:
            work, workR = cand.copy(), r
            print("half round=%d accepted R=%.9f (c %.9f->%.9f)" % (rounds, workR, cR0, cR1))
        else:
            print("half round=%d no accept R=%.9f (c %.9f->%.9f)" % (rounds, r, cR0, cR1))
    print("phase1 rounds=%d R=%.9f" % (rounds, workR))
    if workR > bestR + 1e-14:
        best, bestR = work.copy(), workR
        print("NEW BEST after phase1 R=%.9f" % bestR)

    # ---- Phase 2: aggressive peak polishing at full resolution ----
    p2_deadline = deadline - 2.0
    rounds2 = 0
    while time.process_time() < p2_deadline - 1.0:
        rounds2 += 1
        w = _peak_ladder(best, p2_deadline - 0.4,
                         pads=(0.04, 0.025, 0.015, 0.008), iters=320)
        w = _polish_ladder(w, p2_deadline - 0.4, betas=(1e9, 1e10, 1e11, 0.0), iters=300)
        r = R_of(w)
        if w.size == best.size and r > bestR + 1e-14:
            best, bestR = w.copy(), r
            print("peak round=%d accepted R=%.9f" % (rounds2, bestR))
        else:
            break
    print("phase2 rounds=%d R=%.9f" % (rounds2, bestR))

    # ---- Phase 3: final high-precision polish ----
    ht = _polish_ladder(best, deadline - 0.8,
                        betas=(1e10, 1e11, 1e12, 0.0), iters=400)
    offer(ht, 'finalhi')
    ht2 = _lbfgs_block(best, np.arange(best.size), 3000, deadline - 0.4, beta=0.0)
    offer(ht2, 'finalfull')

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    c = (m - 1) / 2.0
    n = h.size
    w = max(3, int(pad * n))
    lo = max(0, int(c - w))
    hi = min(n, int(c + w) + 1)
    if hi - lo < 2:
        return np.arange(n)
    return np.arange(lo, hi)


def _prolongate(h, N2):
    """Mass-preserving cumulative resampling to N2 steps."""
    N1 = h.size
    if N1 == N2:
        return _rescale(np.clip(h, 0, None))
    M = float(N1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, M, N2 + 1)
    cum_at = np.interp(edges, np.arange(N1 + 1), cum)
    mass = np.diff(cum_at)
    out = mass * (M / N2)
    return _rescale(np.clip(out, 0.0, None))


def _coarsen(h, N2):
    return _prolongate(h, N2)


def _tooth_perturb(h, rng, nteeth=64, sigma=0.06):
    n = h.size
    if n < 3:
        return h.copy()
    left = h[1:-1] >= h[:-2]
    right = h[1:-1] >= h[2:]
    loc = np.flatnonzero(left & right) + 1
    if loc.size == 0:
        return h.copy()
    vals = h[loc]
    k = min(nteeth, loc.size)
    order = np.argsort(-vals)[:k]
    pick = loc[order]
    h2 = h.copy()
    factors = 1.0 + sigma * rng.standard_normal(pick.size)
    h2[pick] = np.clip(h2[pick] * factors, 0.0, None)
    return _rescale(h2)


def _polish(h, deadline, rng, pads=(0.15, 0.07, 0.03)):
    best = h
    bestR = R_of(best)
    cand = _lbfgs_all_pos(best, 300, deadline, tie=True)
    r = R_of(cand)
    if r > bestR:
        best, bestR = cand, r
    for beta in (1e6, 1e8):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _lbfgs_all_pos(best, 100, deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, pad)
        cand = _lbfgs_block(best, free, 150, deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    return best, bestR


# ---------------- Comb detection & refit (the experiment) ----------------

def _smooth(h, w):
    if w < 2:
        return h.copy()
    k = np.ones(w) / w
    return np.convolve(h, k, mode='same')


def _estimate_period(h):
    n = h.size
    if n < 16:
        return 1
    cands = []
    # FFT of residual
    try:
        sm = _smooth(h, max(3, n // 200))
        res = h - sm
        F = np.abs(np.fft.rfft(res))
        if F.size > 8:
            # ignore low freqs
            lo = 4
            hi = min(F.size, max(9, F.size // 2))
            if hi > lo:
                k = lo + int(np.argmax(F[lo:hi]))
                if k > 0:
                    p = int(round(n / k))
                    if 2 <= p <= 512:
                        cands.append(p)
    except Exception:
        pass
    # autocorrelation of h
    try:
        m = min(n, 4096)
        seg = h[:m] - h[:m].mean()
        ac = np.correlate(seg, seg, mode='full')[m - 1:]
        if ac.size > 8 and ac[0] > 0:
            ac = ac / ac[0]
            # find local maxima
            loc = []
            for i in range(2, min(ac.size - 1, 600)):
                if ac[i] > ac[i - 1] and ac[i] >= ac[i + 1] and ac[i] > 0.05:
                    loc.append(i)
                    if len(loc) >= 6:
                        break
            for p in loc:
                if 2 <= p <= 512:
                    cands.append(int(p))
    except Exception:
        pass
    if not cands:
        return 1
    # pick the p with the best comb contrast: max variance of per-class medians
    best_p = 1
    best_score = -1.0
    for p in set(cands):
        if p < 2:
            continue
        idx = np.arange(n) % p
        # median per class
        try:
            a = np.array([np.median(h[idx == i]) for i in range(p)])
        except Exception:
            continue
        score = a.std() / (a.mean() + 1e-12)
        if score > best_score:
            best_score = score
            best_p = p
    return best_p


def _fit_comb(h, p):
    """Return per-residue amplitudes a[i] and quadratic envelope coefficients."""
    n = h.size
    if p < 2 or p > n:
        return None
    idx = np.arange(n) % p
    a = np.zeros(p)
    for i in range(p):
        mask = idx == i
        if mask.any():
            a[i] = np.median(h[mask])
    a = np.clip(a, 1e-12, None)
    # fit log(h/a[idx]) ~ c0 + c1*x + c2*x^2
    x = np.arange(n) / float(n)
    ratio = np.clip(h, 1e-12, None) / a[idx]
    y = np.log(ratio)
    # least squares quadratic
    A = np.stack([np.ones(n), x, x * x], axis=1)
    try:
        coef, *_ = np.linalg.lstsq(A, y, rcond=None)
    except Exception:
        coef = np.array([0.0, 0.0, 0.0])
    return a, coef


def _rasterize_comb(a, coef, N):
    j = np.arange(N)
    x = j / float(N)
    env = coef[0] + coef[1] * x + coef[2] * x * x
    env = np.exp(np.clip(env, -30.0, 30.0))
    h = a[j % a.size] * env
    return _rescale(np.clip(h, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.92 * budget_seconds
    rng = np.random.default_rng(20240607)

    start_arr = None
    startR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.size >= 2 and s.sum() > 0:
            start_arr = s
            startR = R_of(s)
            print("start R=%.9f N=%d" % (startR, s.size))

    if start_arr is None:
        n = 200
        x = (np.arange(n) + 0.5) / n
        h = np.exp(-40.0 * (x - 0.5) ** 2)
        start_arr = _rescale(h)
        startR = R_of(start_arr)
        print("init bump R=%.9f" % startR)

    best = start_arr.copy()
    bestR = startR
    best_alt = None
    best_altR = -1.0

    # ---- (0) Detect comb and fit on start ----
    p = _estimate_period(start_arr)
    print("comb period estimate p=%d" % p)
    fit = _fit_comb(start_arr, p) if p >= 2 else None
    if fit is not None:
        a, coef = fit
        print("comb fit: a.std/a.mean=%.3f" % (a.std() / (a.mean() + 1e-12)))

    # ---- (1) Comb ladder: rasterize at 2N, 4N, 8N ----
    N0 = start_arr.size
    ladder = []
    Nn = N0
    for _ in range(3):
        Nn *= 2
        if Nn > 1000000:
            break
        ladder.append(Nn)

    for N_new in ladder:
        if time.process_time() > deadline - 15.0:
            break
        # plain interpolation lift
        plain = _prolongate(best, N_new)
        plainR = R_of(plain)
        # rasterized comb lift
        if fit is not None:
            raster = _rasterize_comb(a, coef, N_new)
            rasterR0 = R_of(raster)
        else:
            raster = plain.copy()
            rasterR0 = plainR
        print("lift N=%d plainR=%.9f rasterR0=%.9f" % (N_new, plainR, rasterR0))

        # polish rasterized with log-space L-BFGS tie, time-box 8s
        slice_end = min(deadline - 8.0, time.process_time() + 8.0)
        cand = _lbfgs_all_pos(raster, 200, slice_end, tie=True)
        r = R_of(cand)
        # peak-window polish pad 0.05
        if time.process_time() < slice_end - 0.5:
            free = _peak_window(cand, 0.05)
            cand2 = _lbfgs_block(cand, free, 150, slice_end, tie=True)
            r2 = R_of(cand2)
            if r2 > r:
                cand, r = cand2, r2
        print("raster+polish N=%d R=%.9f (delta vs plain %.2e)" %
              (N_new, r, r - plainR))

        # also polish plain for comparison (short)
        if time.process_time() < deadline - 10.0:
            slice_end2 = min(deadline - 8.0, time.process_time() + 4.0)
            pcand = _lbfgs_all_pos(plain, 150, slice_end2, tie=True)
            pr = R_of(pcand)
            if pr > plainR:
                plain, plainR = pcand, pr
            print("plain+polish N=%d R=%.9f" % (N_new, plainR))

        # track best
        if r > bestR:
            best, bestR = cand.copy(), r
            print("accepted raster N=%d R=%.9f" % (N_new, bestR))
        if plainR > bestR:
            best, bestR = plain.copy(), plainR
            print("accepted plain N=%d R=%.9f" % (N_new, bestR))

        # remember alternative (rasterized) if genuinely different and not best
        if r > best_altR and r < bestR - 1e-12:
            best_alt, best_altR = cand.copy(), r

        # refit comb on the polished result for next level
        p2 = _estimate_period(cand)
        fit2 = _fit_comb(cand, p2) if p2 >= 2 else None
        if fit2 is not None:
            a2, coef2 = fit2
            # sanity: only adopt if it explains the data reasonably
            if p2 <= 512:
                a, coef, p = a2, coef2, p2

    # ---- (2) Final free L-BFGS tie polish at largest N ----
    if time.process_time() < deadline - 1.0:
        cand = _lbfgs_all_pos(best, 200, deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
            print("final free polish R=%.9f N=%d" % (bestR, best.size))

    best = _rescale(np.clip(best, 0, None))
    finalR = R_of(best)
    print("final R=%.9f N=%d" % (finalR, best.size))

    if start_arr is not None and startR >= finalR:
        out = {"best": start_arr}
        if best_alt is not None and best_altR > startR:
            out["alternative"] = best_alt
        elif best_alt is not None:
            out["alternative"] = best_alt
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_beta(h, 0.0) if beta > 0 else (1e18, np.zeros(h.size))
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_max(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf = -dq / num
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, use_max=False, free=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if free is None:
        active = np.arange(h.size)
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0
    x0 = h[active].copy()
    if use_max:
        fg = _fun_grad_max
    else:
        fg = (lambda hh: _fun_grad_beta(hh, beta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_chain(h, deadline, iters=250):
    """Robust polish: soft-max betas then hard max, tracking best."""
    best = h.copy(); bestR = R_of(h)
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.3:
            break
        ht = _lbfgs(h, iters, deadline, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, h = ht.copy(), r, ht
    if time.process_time() < deadline - 0.3:
        ht = _lbfgs(best, iters, deadline, use_max=True)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    return best, bestR


def _peak_polish(h, deadline, pads=(0.15, 0.10, 0.06, 0.04)):
    best = h.copy(); bestR = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs(best, 300, deadline, beta=1e7, free=win)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        if time.process_time() >= deadline - 0.3:
            break
        ht = _lbfgs(best, 300, deadline, use_max=True, free=win)
        r = R_of(ht)
