        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, tag
            print("%s NEW BEST R=%.9f" % (tag, bestR))
        elif r > alt_bestR and r < bestR:
            alt_best, alt_bestR = ht.copy(), r
        return r

