        ht, _ = _peak_polish(ht, sl)
        r = _consider(ht, 'rot%d' % v)
        print("rot%d R(c)=%.9f R=%.9f" % (v, cR, r))
        rounds += 1

    # ---- Phase C: perturb + polish restarts on half-res ----
    if best_c is not None and time.process_time() < deadline - 2.5:
        rng = np.random.default_rng(12345)
        amps = [0.006, 0.012, 0.025, 0.045, 0.08]
        ri = 0
        while time.process_time() < deadline - 2.5:
            amp = amps[ri % len(amps)]
            ri += 1
            cc = best_c.copy()
            nz = cc > 0
            if nz.sum() == 0:
                break
            cc[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
