    if time.process_time() < deadline - 0.5:
        ht, _ = _polish_chain(best, deadline - 0.4, iters=250)
        _consider(ht, origin + '+final')
    if time.process_time() < deadline - 0.4:
        ht, _ = _peak_polish(best, deadline - 0.3, pads=(0.08, 0.05))
        _consider(ht, origin + '+fpk')

    print("rounds=%d best_c=%.9f best_full=%.9f" %
          (rounds, best_cR, bestR))
