    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, tol=1e-2):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _coarsen(h, n):
    """Mass-preserving block-sum coarsening of h to length n."""
    N = h.size
    if N == n:
        return h.copy()
    edges = np.linspace(0, N, n + 1)
    out = np.zeros(n)
    for i in range(n):
        lo = int(np.floor(edges[i]))
        hi = int(np.floor(edges[i + 1]))
        if hi <= lo:
            hi = lo + 1
        lo = min(lo, N - 1)
        hi = min(hi, N)
        out[i] = h[lo:hi].sum()
    return out


def _lift(hc, N):
    """Lift coarse hc to length N by cumulative-mass interpolation."""
    n = hc.size
    if n == N:
        return hc.copy()
    c = np.concatenate(([0.0], np.cumsum(hc)))
    total = c[-1]
    if total <= 0:
        return np.ones(N) / N
    xs = np.linspace(0, n, N + 1)
    ys = np.interp(xs, np.arange(n + 1), c)
    out = np.diff(ys)
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return np.ones(N) / N
    return out


def _trapezoid_target(n, w, r, Lc):
    """Symmetric trapezoid of length n+1 knots, mass- and peak-matched to Lc."""
    x = np.linspace(0, 1, n + 1)
    T = np.zeros(n + 1)
    c = 0.5
    half_flat = w * 0.5
    for i, xi in enumerate(x):
        d = abs(xi - c)
        if d <= half_flat:
            T[i] = 1.0
        elif d <= half_flat + r:
            T[i] = 1.0 - (d - half_flat) / r
        else:
            T[i] = 0.0
    mx = T.max()
    if mx <= 0:
        return T
    T = T / mx * Lc.max()
    sT = T.sum()
    sL = Lc.sum()
    if sT > 0:
        T = T * (sL / sT)
    return T


def _deconv(h0, T, lam, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    Tn = float(np.sum(T * T))
    if Tn <= 0:
        return h0
    h0n = float(np.sum(h * h))
    if h0n <= 0:
        h0n = 1.0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        Lf = _knots(hh)
        r = Lf - T
        val = float(np.sum(r * r)) / Tn + lam * float(np.sum((hh - h) ** 2)) / h0n
        gLf = 2.0 * r / Tn
        g = _backprop(gLf, hh) + 2.0 * lam * (hh - h) / h0n
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_h = _rescale(base)
            startR = R_of(start_h)
        else:
            start_h, startR = None, 0.0
    else:
        start_h, startR = None, 0.0

    if start_h is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_h = _rescale(h)
        startR = R_of(start_h)

    best = start_h.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    Nfull = best.size
    n = 16384

    # ---- Coarsen start ----
    hc0 = _coarsen(best, n)
    hc0 = _rescale(hc0)
    Lc = _knots(hc0)
    print("coarse n=%d, Rc0=%.9f, frac near max(1%%)=%.4f"
          % (n, R_of(hc0), _frac_near_max(hc0, 1e-2)))

    # ---- Sweep trapezoid targets ----
    sweeps = [(0.45, 0.10), (0.55, 0.08), (0.65, 0.12), (0.55, 0.20)]
    coarse_cands = []
    for (w, r) in sweeps:
        if time.process_time() >= deadline - 20.0:
            break
        T = _trapezoid_target(n, w, r, Lc)
        tlim = min(deadline - 18.0, time.process_time() + 4.0)
        hd = _deconv(hc0, T, 1e-3, 200, tlim)
        rd = R_of(hd)
        fr = _frac_near_max(hd, 1e-2)
        print("w=%.2f r=%.2f: Rc=%.9f frac(1%%)=%.4f" % (w, r, rd, fr))
        coarse_cands.append((rd, hd.copy(), w, r))

    coarse_cands.sort(key=lambda t: -t[0])

    alt_best = None
    altR = -1.0

    # ---- Lift best few and polish at full resolution ----
    for k, (rc, hc, w, r) in enumerate(coarse_cands[:2]):
        if time.process_time() >= deadline - 2.0:
            break
        hf = _lift(hc, Nfull)
        hf = _rescale(hf)
        rf = R_of(hf)
        print("lift w=%.2f r=%.2f: Rc=%.9f -> Rf=%.9f (retain %.3f)"
              % (w, r, rc, rf, rf / rc if rc > 0 else 0.0))

        # tie polish
        if time.process_time() < deadline - 1.5:
            pol = _lbfgs_block(hf, np.arange(hf.size), 200,
                               min(deadline - 1.0, time.process_time() + 4.0),
                               tie=True)
            rp = R_of(pol)
            print("  tie polish R=%.9f" % rp)
            if rp > rf:
                hf, rf = pol, rp

        # beta ladder
        for beta in (1e3, 1e4, 1e5):
            if time.process_time() >= deadline - 1.0:
                break
            pol = _lbfgs_block(hf, np.arange(hf.size), 150,
                               min(deadline - 0.5, time.process_time() + 3.0),
                               beta=beta)
            rp = R_of(pol)
            print("  beta=%.0e R=%.9f" % (beta, rp))
            if rp > rf:
                hf, rf = pol, rp

        # peak-window tie polishes
        for pad in (0.15, 0.07):
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(hf, pad_frac=pad, extra=128)
            pol = _lbfgs_block(hf, win, 200,
                               min(deadline - 0.2, time.process_time() + 2.0),
                               tie=True)
            rp = R_of(pol)
            print("  window pad=%.2f R=%.9f" % (pad, rp))
            if rp > rf:
                hf, rf = pol, rp

        if rf > altR:
            altR = rf
            alt_best = hf.copy()
        if rf > bestR + 1e-15:
            best, bestR = hf.copy(), rf

    # ---- Safety net: tie polish on best ----
    if time.process_time() < deadline - 0.5:
        pol = _lbfgs_block(best, np.arange(best.size), 150,
                           min(deadline - 0.2, time.process_time() + 3.0),
                           tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = start_h.copy(), startR

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, tol=1e-2):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _coarsen(h, n):
    """Mass-preserving block-sum coarsening of h to length n."""
    N = h.size
    if N == n:
