def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- NEW: local discrete perturb-and-accept search ----------------
#
# The L-BFGS-B approach can stall on a plateau given by the max-knot constraint.
# A cheap direct search that perturbs a handful of heights at a time, recomputes
# R exactly (O(N log N) via FFT), and keeps any strict improvement, can escape
# small plateaus. Perturbations are multiplicative on a small contiguous window,
# which respects the non-negativity constraint and the shape.

def _local_search(h, bestR, deadline, rng, n_trials_cap=10**9):
    """Coordinate-window multiplicative perturbation search."""
    n = h.size
    if n == 0:
        return h, bestR
    scale = h.max() if h.max() > 0 else 1.0
    tries = 0
    cur = h.copy()
    curR = bestR
    # window sizes: small enough to be a local move, big enough to matter
    win_choices = (3, 8, 16, 32)
    while time.process_time() < deadline - 0.6 and tries < n_trials_cap:
        tries += 1
        w = win_choices[rng.integers(0, len(win_choices))]
        c = int(rng.integers(0, max(1, n - w)))
        # smooth perturbation: a small bump shaped like a gaussian over [c, c+w)
        j = np.arange(w, dtype=float)
        sigma = max(0.5, w / 4.0)
        bump = np.exp(-((j - (w - 1) / 2.0) ** 2) / (2.0 * sigma * sigma))
        amp = (rng.random() - 0.35) * 0.5  # biased slightly toward growth
        trial = cur.copy()
        trial[c:c + w] = np.clip(trial[c:c + w] * (1.0 + amp * bump), 0.0, None)
        # occasionally zero-out a window (structural move)
        if rng.random() < 0.05:
            trial[c:c + w] *= 0.0
        if trial.sum() <= 0:
            continue
        r = R_of(trial)
        if r > curR + 1e-12:
            cur, curR = _rescale(trial), r
    return cur, curR


# ---------------- tail-growth machinery (kept from parent) ----------------

def _boundary_value(h, side, k=8):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0.0
    if side == 'L':
        idx = pos[:k]
    else:
        idx = pos[-k:]
    return float(h[idx].mean())


def _make_profile(kind, length, v, eps):
    if length <= 0:
        return np.zeros(0)
    j = np.arange(length, dtype=float)
    if kind == 'eps-const':
        return np.full(length, eps)
    if kind == 'ramp-from-end':
        frac = j / max(1.0, length - 1.0)
        return v * (1.0 - frac) + eps * frac
    if kind == 'exp-decay':
        return v * np.exp(-j / 1500.0) + eps
    return np.full(length, eps)


def _build_padded(start, padL, padR, kind, eps):
    vL = _boundary_value(start, 'L')
    vR = _boundary_value(start, 'R')
    profL = _make_profile(kind, padL, vL, eps)
    profR = _make_profile(kind, padR, vR, eps)
    if padL > 0:
        profL = profL[::-1]
    return np.concatenate([profL, start, profR])


def _tail_polish(h, padL, padR, deadline, it1=250, it2=120):
    n = h.size
    if padL > 0:
        loL = 0
        hiL = min(n - 1, padL + 256)
    else:
        loL = hiL = -1
    if padR > 0:
        loR = max(0, n - padR - 256)
        hiR = n - 1
    else:
        loR = hiR = -1
    h = _lbfgs_all_pos(h, it1, deadline, beta=0.0)
    if padL > 0:
        free = np.arange(loL, hiL + 1)
        h = _lbfgs_block(h, free, it2, deadline, beta=1e7)
    if padR > 0:
        free = np.arange(loR, hiR + 1)
        h = _lbfgs_block(h, free, it2, deadline, beta=1e7)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    eps = 1e-3 * float(start_best.mean())
    pads = [0, 4000, 8000]
    profiles = ['eps-const', 'ramp-from-end', 'exp-decay']

    # (1) Parametric scan over asymmetric pads and profiles.
    table = []
    best_cand = best.copy()
    best_candR = bestR
    for padL in pads:
        for padR in pads:
            if padL == 0 and padR == 0:
                continue
            for kind in profiles:
                if time.process_time() >= deadline - 8.0:
                    break
                hp = _build_padded(start_best, padL, padR, kind, eps)
                hp = _rescale(hp)
                hp = _tail_polish(hp, padL, padR, deadline - 6.0)
                r = R_of(hp)
                dR = r - bestR
                table.append((padL, padR, kind, dR, r))
                if r > best_candR + 1e-13:
                    best_cand, best_candR = hp.copy(), r
            if time.process_time() >= deadline - 8.0:
                break
        if time.process_time() >= deadline - 8.0:
            break

    print("pad table (padL,padR,profile,dR,R):")
    for (pl, pr, k, dR, r) in table:
        print("  (%5d,%5d,%-13s) dR=%+.3e R=%.7f" % (pl, pr, k, dR, r))

    if best_candR > bestR + 1e-13:
        best, bestR = best_cand.copy(), best_candR
        print("scan best R=%.7f" % bestR)

    # (2) Full run_cycle on best candidate.
    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("cycle after scan R=%.7f" % bestR)

    # (3) NEW: Local perturb search before tail growth, so we have budget.
    if time.process_time() < deadline - 3.0:
        lsR0 = bestR
        best, bestR = _local_search(best, bestR, deadline - 3.0, rng)
        print("local search dR=%+.3e R=%.7f" % (bestR - lsR0, bestR))
        if time.process_time() < deadline - 2.5 and bestR > lsR0 + 1e-12:
            best, bestR, _ = run_cycle(best, bestR, deadline - 2.5)
            print("cycle after local R=%.7f" % bestR)

    # (4) Tail growth round: extend the winning side.
    if table and time.process_time() < deadline - 3.0:
        best_entry = max(table, key=lambda t: t[3])
        padL_w, padR_w = best_entry[0], best_entry[1]
        grow_right = padR_w >= padL_w
        extra = 3000
        if grow_right:
            new_padR = padR_w + extra
            new_padL = padL_w
        else:
            new_padL = padL_w + extra
            new_padR = padR_w
        kind = best_entry[2]
        hp = _build_padded(start_best, new_padL, new_padR, kind, eps)
        hp = _rescale(hp)
        n = hp.size
        if grow_right:
            lo = max(0, n - (new_padR - padR_w) - 512)
            hi = n - 1
        else:
            lo = 0
            hi = min(n - 1, (new_padL - padL_w) + 512)
        free = np.arange(lo, hi + 1)
        hp = _lbfgs_block(hp, free, 200, deadline - 2.0, beta=0.0)
        hp = _lbfgs_block(hp, free, 150, deadline - 2.0, beta=1e7)
        r = R_of(hp)
        print("tail grow %s dR=%+.3e R=%.7f" %
              ('R' if grow_right else 'L', r - bestR, r))
        if r > bestR + 1e-13:
            best, bestR = hp.copy(), r
        if time.process_time() < deadline - 2.0:
            best, bestR, _ = run_cycle(best, bestR, deadline - 2.0)
            print("cycle after tail grow R=%.7f" % bestR)

    # (5) Final polish + short local search to use remaining time.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 300, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.6:
        best2, bestR2 = _local_search(best, bestR, deadline - 0.4, rng)
        if bestR2 > bestR + 1e-12:
            best, bestR = best2, bestR2
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _near5(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= mx * 0.95))


def _detect_repeat(h):
    n = h.size
    for p in (64, 32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _coarse(c_in, m):
    n = c_in.size
    if m == n:
        return c_in.copy()
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 * (n / m)
    xi = np.arange(n, dtype=float) + 0.5
    return np.interp(x, xi, c_in)


def _prolong(c_coarse, m_out):
    m = c_coarse.size
    if m_out == m:
        return c_coarse.copy()
    x = np.linspace(0.0, m, m_out, endpoint=False) + 0.5 * (m_out / m)
    xi = np.arange(m, dtype=float) + 0.5
    return np.interp(x, xi, c_coarse)


def _polish_c(c, p, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return c, R_of(np.repeat(c, p))
    h = _rescale(np.repeat(c, p))
    h2 = _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=tie)
    c2 = h2.reshape(-1, p).mean(axis=1)
    hr = np.repeat(c2, p)
    return c2, R_of(hr)


def _vcycle(best, bestR, p, c, deadline, levels):
    n_c = c.size
    coarse_list = [(n_c, c.copy())]
    cur = c
    for m in levels[1:]:
        cur = _coarse(cur, m)
        coarse_list.append((m, cur.copy()))
    m, cc = coarse_list[-1]
    cc, r = _polish_c(cc, p, 80, min(deadline, time.process_time() + 3.0))
    coarse_list[-1] = (m, cc)
    if r > bestR + 1e-15:
        best = _rescale(np.repeat(cc, p)); bestR = r
    for i in range(len(coarse_list) - 2, -1, -1):
        m_out, _ = coarse_list[i]
        cc = _prolong(cc, m_out)
        cc, r = _polish_c(cc, p, 100,
                          min(deadline, time.process_time() + 4.0))
        coarse_list[i] = (m_out, cc)
        if r > bestR + 1e-15:
            best = _rescale(np.repeat(cc, p)); bestR = r
    return best, bestR, cc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p_rep, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p_rep, c.size))

    # ---- Phase V: multi-resolution V-cycles ----
    v_end = t0 + (deadline - t0) * 0.30 + t0
    if p_rep > 1 and c.size >= 4 and time.process_time() < v_end - 3.0:
        n_c = c.size
        levels = [n_c]
        m = n_c
        while len(levels) < 3 and m > 8:
            m = max(8, m // 4)
            if m >= levels[-1]:
                break
            levels.append(m)
        print("vcycle levels=%s" % levels)
        cycle = 0
        while time.process_time() < v_end - 3.0:
            cycle += 1
            best, bestR, c = _vcycle(best, bestR, p_rep, c, v_end, levels)
            print("vcycle cycle=%d bestR=%.9f" % (cycle, bestR))
            if cycle >= 2 and time.process_time() > v_end - 6.0:
                break

    # ---- Phase L: lift to 2x resolution, polish coarse then full ----
    lift_end = t0 + (deadline - t0) * 0.45 + t0
    if time.process_time() < lift_end - 2.0:
        p2, c2 = _detect_repeat(best)
        if p2 >= 2 and c2.size >= 4:
            c_lift = _interp_lift(c2)
            p_new = p2 * 2
            h_lift = _rescale(np.repeat(c_lift, p_new))
            h_lift = _lbfgs_block(h_lift, np.arange(h_lift.size), 200,
                                   min(lift_end, time.process_time() + 6.0),
                                   tie=True)
            r = R_of(h_lift)
            print("lift p=%d->%d R=%.9f (best %.9f)" % (p2, p_new, r, bestR))
            if r > bestR + 1e-15:
                best, bestR = h_lift, r

    # ---- Phase E: exact tie polish + peak-window pads ----
    c_end = deadline
    for pad in (0.10, 0.06, 0.03, 0.015, 0.008):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie in ((1e7, False), (1e5, False), (0.0, True)):
            if time.process_time() >= c_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(c_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f near5=%.4f"
              % (pad, bestR, _near5(best)))

    # ---- Phase F: full-array final polish if time remains ----
    if time.process_time() < c_end - 2.0 and best.size <= 200000:
        win = np.arange(best.size)
        for beta, tie in ((1e6, False), (0.0, True)):
            if time.process_time() >= c_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 400,
                              min(c_end - 0.5, time.process_time() + 4.0),
                              beta=beta, tie=tie)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("full R=%.9f near5=%.4f" % (bestR, _near5(best)))

    print("final R=%.9f (start %.9f, N=%d, ties=%d, near5=%.4f)"
          % (bestR, startR, best.size, _tie_count(best), _near5(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_flat_top(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    S = Lf >= tau * mx
    nS = int(S.sum())
    gLf = -dq / num
    # peak term
    m = int(np.argmax(Lf))
    gLf[m] += 1.0 / mx
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    if nS > 1 and kappa > 0:
        Ls = Lf[S]
        Lbar = Ls.mean()
        V = float(np.sum((Ls - Lbar) ** 2)) / (mx * mx * nS)
        val += kappa * V
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * (Ls - Lbar) / (mx * mx * nS)
        # treat mx as fixed (as base does)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 tau=0.0, kappa=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif kappa > 0:
        fg = (lambda hh: _fun_grad_flat_top(hh, tau, kappa))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _coarsen(h, n):
    """Mass-preserving block-sum coarsening to n bins."""
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == n:
        return h.copy()
    if N < n:
        # prolongate instead
        return _prolongate(h, n)
    edges = np.linspace(0, N, n + 1)
    out = np.zeros(n)
    for i in range(n):
        lo = int(np.floor(edges[i]))
        hi = int(np.ceil(edges[i + 1]))
        lo = max(0, min(N, lo))
        hi = max(lo, min(N, hi))
        if hi <= lo:
            out[i] = 0.0
            continue
        # fractional weights
        xs = np.arange(lo, hi, dtype=float)
        w = np.minimum(xs + 1.0, edges[i + 1]) - np.maximum(xs, edges[i])
        w = np.clip(w, 0.0, None)
        out[i] = np.sum(h[lo:hi] * w)
    return _rescale(out)


def _prolongate(h, n):
    """Mass-preserving linear interpolation of cumulative sum."""
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    # c has N+1 points at positions 0..N
    xs = np.linspace(0.0, N, n + 1)
    cn = np.interp(xs, np.arange(N + 1, dtype=float), c)
    out = np.diff(cn)
    out = np.clip(out, 0.0, None)
    return _rescale(out)


def _ladder(h, deadline, rungs, per_rung_sec, polish_sec, n_label):
    best = h.copy()
    bestR = R_of(best)
    for (tau, kappa) in rungs:
        if time.process_time() >= deadline - 1.0:
            break
        tlim = min(deadline - 0.5, time.process_time() + per_rung_sec)
        hh = _lbfgs_block(best, np.arange(best.size), 200, tlim,
                          tau=tau, kappa=kappa)
        r = R_of(hh)
        if r > bestR:
            best, bestR = hh.copy(), r
        # exact-R tie polish
        if time.process_time() < deadline - 0.5:
            tlim2 = min(deadline - 0.3, time.process_time() + polish_sec)
            hp = _lbfgs_block(best, np.arange(best.size), 100, tlim2, tie=True)
            rp = R_of(hp)
            if rp > bestR:
                best, bestR = hp.copy(), rp
        print("  [%s] tau=%.2f kappa=%.1f R=%.9f frac(1%%)=%.4f"
              % (n_label, tau, kappa, bestR, _frac_near_max(best, 1e-2)))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max 0.1/1/5%%: %.4f / %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    alt_best = None
    altR = -1.0

    # ---- Coarsen to n=2048 and run full ladder ----
    n0 = 2048
    hc = _coarsen(best, n0)
    print("coarsened to n=%d, R=%.9f" % (n0, R_of(hc)))
    rungs_full = [(0.99, 0.3), (0.95, 1.0), (0.90, 3.0),
                  (0.85, 10.0), (0.80, 30.0)]
    hc, rc = _ladder(hc, deadline, rungs_full, 4.0, 1.5, "n=%d" % n0)
    if rc > altR:
        altR, alt_best = rc, hc.copy()
    if rc > bestR:
        best, bestR = hc.copy(), rc

    # ---- Prolongate to 8192, shortened ladder ----
    if time.process_time() < deadline - 3.0:
        n1 = 8192
        hp = _prolongate(hc, n1)
        print("prolongated to n=%d, R=%.9f" % (n1, R_of(hp)))
        rungs_short = [(0.95, 1.0), (0.90, 3.0), (0.85, 10.0)]
        hp, rp = _ladder(hp, deadline, rungs_short, 3.0, 1.0, "n=%d" % n1)
        if rp > altR:
            altR, alt_best = rp, hp.copy()
        if rp > bestR:
            best, bestR = hp.copy(), rp
        print("frac near max 0.1/1/5%% at n=%d: %.4f / %.4f / %.4f"
              % (n1, _frac_near_max(hp, 1e-3), _frac_near_max(hp, 1e-2),
                 _frac_near_max(hp, 5e-2)))
    else:
        hp = hc

    # ---- Prolongate to 32768, shortened ladder ----
    if time.process_time() < deadline - 3.0:
        n2 = 32768
        hp2 = _prolongate(hp, n2)
        print("prolongated to n=%d, R=%.9f" % (n2, R_of(hp2)))
        rungs_short = [(0.90, 3.0), (0.85, 10.0)]
        hp2, rp2 = _ladder(hp2, deadline, rungs_short, 3.0, 1.0, "n=%d" % n2)
        if rp2 > altR:
            altR, alt_best = rp2, hp2.copy()
        if rp2 > bestR:
            best, bestR = hp2.copy(), rp2
        hp = hp2

    # ---- Final: prolongate to start's N (or 104992) and polish ----
    finalN = best.size if start is None else max(best.size, start.size)
    if time.process_time() < deadline - 2.0:
        hf = _prolongate(hp, finalN)
        rf = R_of(hf)
        print("prolongated to n=%d, R=%.9f" % (finalN, rf))
        if rf > altR:
            altR, alt_best = rf, hf.copy()
        if rf > bestR:
            best, bestR = hf.copy(), rf

        # full tie polish
        if time.process_time() < deadline - 1.5:
            pol = _lbfgs_block(best, np.arange(best.size), 200,
                               min(deadline - 1.0, time.process_time() + 4.0),
                               tie=True)
            rp = R_of(pol)
            if rp > altR:
                altR, alt_best = rp, pol.copy()
            if rp > bestR:
                best, bestR = pol.copy(), rp

        # peak-window polish
        for pad in (0.05, 0.03):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=96)
            ht = _lbfgs_block(best, win, 300,
                              min(deadline - 0.5, time.process_time() + 3.0),
                              tie=True)
            r = R_of(ht)
            if r > altR:
                altR, alt_best = r, ht.copy()
            if r > bestR:
                best, bestR = ht.copy(), r

    print("frac near max 0.1/1/5%% final: %.4f / %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    # safety net
    if bestR < startR - 1e-15 and start is not None:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = np.log(np.clip(h, 1e-12, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie  # default to tie-aware

    def f(x):
        hh = np.exp(np.clip(x, -30.0, 30.0))
        val, g = fg(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(np.clip(res.x, -30.0, 30.0)))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth(h, sigma):
    """Gaussian smooth the height array."""
    if sigma <= 0.5:
        return h.copy()
    rad = int(np.ceil(3 * sigma))
    x = np.arange(-rad, rad + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    n = h.size
    if n > 4000:
        # FFT-based
        hpad = np.concatenate([np.zeros(rad), h, np.zeros(rad)])
        c = fftconvolve(hpad, k, mode='same')
        return c[rad:rad + n]
    return np.convolve(h, k, mode='same')


def _coarsen(h, factor):
    n = h.size
    m = n // factor
    if m * factor != n:
        # pad
        pad = m * factor - n + factor
        h = np.concatenate([h, np.zeros(pad)])
        m = h.size // factor
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def _lift(h, factor):
    return np.repeat(h, factor)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    print("base R=%.12f (N=%d)" % (baseR, base.size))

    bestH = base.copy()
    bestR = baseR
    altH = base.copy()
    altR = baseR

    N = base.size
    rng = np.random.RandomState(777)

    # Phase 1: aggressive polish of start with tie-aware L-BFGS on peak window
    if time.process_time() < deadline - 2.0:
        free = _peak_window(base, tol=0.999, pad_frac=0.6, extra=512)
        cap = min(deadline - 1.0, time.process_time() + 5.0)
        hn = _lbfgs_block(base, free, 300, cap, beta=0.0, tie=True)
        rn = R_of(hn)
        if rn > bestR + 1e-14:
            bestH, bestR = hn, rn
            print("phase1 peak polish: %.12f (+%.3e)" % (bestR, bestR - baseR))

    # Phase 2: beta-ladder polish (helps widen near-max plateau)
    if time.process_time() < deadline - 2.0:
        cur = bestH.copy()
        curR = bestR
        for beta in [20.0, 100.0, 500.0]:
            if time.process_time() >= deadline - 1.5:
                break
            cap = min(deadline - 1.0, time.process_time() + 3.0)
            free = _peak_window(cur, tol=0.9995, pad_frac=0.5, extra=384)
            hn = _lbfgs_block(cur, free, 200, cap, beta=beta, tie=False)
            rn = R_of(hn)
            if rn > curR + 1e-15:
                cur, curR = hn, rn
        if curR > bestR + 1e-14:
            bestH, bestR = cur, curR
            print("phase2 beta ladder: %.12f (+%.3e)" % (bestR, bestR - baseR))

    # Phase 3: full-array polish
    if time.process_time() < deadline - 2.0:
        cap = min(deadline - 1.0, time.process_time() + 4.0)
        hn = _lbfgs_log(bestH, 200, cap, beta=0.0, tie=True)
        rn = R_of(hn)
        if rn > bestR + 1e-14:
            bestH, bestR = hn, rn
            print("phase3 full polish: %.12f (+%.3e)" % (bestR, bestR - baseR))

    # Phase 4: basin hopping with smoothing perturbations
    # Smooth the peak region to try to escape local basin, then re-polish.
    it = 0
    while time.process_time() < deadline - 3.0:
        it += 1
        # Try a smoothing scale; alternate small/large
        sigmas = [2.0, 5.0, 10.0, 20.0, 40.0, 80.0]
        sigma = sigmas[(it - 1) % len(sigmas)]

        # Only smooth the central support region (where peak lives)
        cand = bestH.copy()
        # Apply smoothing
        sm = _smooth(cand, sigma)
        # Blend: mix original and smoothed (preserve zeros at edges)
        alpha = 0.5
        cand = (1.0 - alpha) * cand + alpha * sm
        # Restore exact zeros at edges (where base had near-zero)
        if np.any(base > 0):
            nz = base > 0
            cand[~nz] = 0.0
        cand = _rescale(cand)
        cR = R_of(cand)

        # If smoothing already improved, accept
        if cR > bestR + 1e-14:
            bestH, bestR = cand, cR
            print("hop sigma=%.1f smooth-improved: %.12f (+%.3e)" %
                  (sigma, bestR, bestR - baseR))

        # Polish locally around peak
        if time.process_time() < deadline - 2.5:
            free = _peak_window(cand, tol=0.999, pad_frac=0.6, extra=512)
            cap = min(deadline - 1.5, time.process_time() + 2.5)
            hn = _lbfgs_block(cand, free, 200, cap, beta=0.0, tie=True)
            rn = R_of(hn)
            if rn > bestR + 1e-14:
                bestH, bestR = hn, rn
                print("hop sigma=%.1f polish-improved: %.12f (+%.3e)" %
                      (sigma, bestR, bestR - baseR))

    # Phase 5: final high-effort polish
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 4.0)
        free = _peak_window(bestH, tol=0.9999, pad_frac=0.7, extra=768)
        hn = _lbfgs_block(bestH, free, 400, cap, beta=0.0, tie=True)
        rn = R_of(hn)
        if rn > bestR + 1e-14:
            bestH, bestR = hn, rn
            print("phase5 final polish: %.12f (+%.3e)" % (bestR, bestR - baseR))

    # Alternative = best
    altH = bestH.copy()
    altR = bestR

    print("final best R=%.12f (N=%d) base R=%.12f gain=%+.3e" %
          (bestR, bestH.size, baseR, bestR - baseR))
    return {"best": bestH, "alternative": altH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_p(h):
    n = h.size
    for p in (32, 16, 8, 64, 24, 48, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-6, atol=1e-9):
            return p
    return 32


def _wmod_block(h, p, maxiter, deadline):
    n = h.size
    if n % p != 0:
        return h
    m = n // p
    if m < 2:
        return h
    H = h.reshape(m, p)
    c = H.mean(axis=1)
    if np.any(c <= 0):
        c = np.clip(c, 1e-12, None)
    w = (H / c[:, None]).mean(axis=0)
    if np.any(w <= 0):
        w = np.clip(w, 1e-12, None)
    lw = np.log(w)
    shift = lw.mean()
    lw = lw - shift
    c = c * np.exp(shift)
    w = np.exp(lw)

    def unpack(x):
        lc = x[:m]
        lw2 = x[m:]
        cc = np.exp(lc)
        ww = np.exp(lw2)
        sh = lw2.mean()
        if sh != 0.0:
            cc = cc * np.exp(sh)
            ww = ww * np.exp(-sh)
        return cc, ww

    def f(x):
        cc, ww = unpack(x)
        hh = (cc[:, None] * ww[None, :]).ravel()
        val, g = _fun_grad_tie(hh)
        G = g.reshape(m, p)
        gc = (G * (cc[:, None] * ww[None, :])).sum(axis=1)
        gw = (G * (cc[:, None] * ww[None, :])).sum(axis=0)
        gm = gw.mean()
        gw = gw - gm
        gc = gc + gm
        return val, np.concatenate([gc, gw])

    x0 = np.concatenate([np.log(c), lw])
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    cc, ww = unpack(res.x)
    hh = (cc[:, None] * ww[None, :]).ravel()
    return _rescale(hh)


def _quotient_opt(h, p, maxiter, deadline):
    n = h.size
    if n % p != 0:
        return h
    m = n // p
    if m < 2:
        return h
    c0 = h.reshape(m, p).mean(axis=1)
    cb = _make_cb(deadline - 0.3)

    def fq(x):
        c = np.clip(x, 0.0, None)
        hh = np.repeat(c, p)
        val, g = _fun_grad_tie(hh)
        gc = g.reshape(m, p).sum(axis=1)
        return val, gc

    try:
        res = minimize(fq, c0.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * m, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        if res is None:
            return h
        return _rescale(np.repeat(np.clip(res.x, 0.0, None), p))
    except (TimeoutError, Exception):
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p = _detect_p(best)
    print("detected p=%d" % p)

    # Phase A: quotient opt on detected period
    qa_end = t0 + budget_seconds * 0.25
    for pp in (p, p // 2, p * 2, 8, 4, 2):
        if pp is None or pp < 2 or best.size % pp != 0:
            continue
        if time.process_time() >= qa_end - 1.0:
            break
        ht = _quotient_opt(best, pp, 2000,
                            min(qa_end - 0.5, time.process_time() + 8.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("quot p=%d ACCEPT R=%.9f" % (pp, bestR))

    # Phase W: residue-class multiplier optimization
    w_end = t0 + budget_seconds * 0.50
    p = _detect_p(best)
    print("wmod p=%d" % p)
    for blk in range(5):
        if time.process_time() >= w_end - 1.5:
            break
        prevR = bestR
        ht = _wmod_block(best, p, 500, min(w_end - 0.5,
                                           time.process_time() + 12.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("wmod R=%.9f dR=%.2e" % (bestR, r - prevR))

    # Phase Q2: quotient on finer periods
    q2_end = t0 + budget_seconds * 0.68
    for pp in (16, 8, 32, 4, 2):
        if time.process_time() >= q2_end - 1.0:
            break
        if best.size % pp != 0:
            continue
        ht = _quotient_opt(best, pp, 2000,
                            min(q2_end - 0.5, time.process_time() + 5.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("quot2 p=%d ACCEPT R=%.9f" % (pp, bestR))

    # Phase P: peak ladder (full-N, windowed, multi-objective)
    peak_end = t0 + budget_seconds * 0.92
    pads = (0.08, 0.05, 0.03, 0.02, 0.012, 0.008, 0.004)
    for pad in pads:
        if time.process_time() >= peak_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (1e5, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= peak_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 500,
                              min(peak_end - 0.5,
                                  time.process_time() + 2.5),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # Phase F: final polish
    fd = t0 + budget_seconds * 0.99
    p = _detect_p(best)
    if time.process_time() < fd - 1.5 and best.size % p == 0:
        ht = _quotient_opt(best, p, 2000,
                            min(fd - 0.5, time.process_time() + 2.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final quot ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 1.0:
        win = _peak_window(best, pad_frac=0.02, extra=48)
        ht = _lbfgs_block(best, win, 400,
                          min(fd - 0.5, time.process_time() + 2.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, tau):
    # soft-max surrogate: log(sum exp(L/tau))/... smooths the max; helps
    # when the peak is nearly flat so the true max is degenerate.
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    z = Lf / tau
    z = z - z.max()
    e = np.exp(z)
    Z = e.sum()
    w = e / Z
    # softmax value ~ tau*log(Z) + max; use log(softmax) as smooth logmax
    logsm = np.log(Z) + z.max()  # = log sum exp(L/tau)
    gLf = -dq / num
    gLf += (1.0 / tau) * w / (logsm / 1.0) if False else 0.0
    # d/dh of log(softmax) = sum_i w_i * dL_i / tau ; but we use log(softmax)/1
    # Actually log(sm) where sm = tau*logsumexp; treat value log(sum exp(L/tau)) - log(1)
    # Simpler: use log(sum exp(L/tau)) directly as smooth log-max proxy (scaled)
    gLf = -dq / num
    gLf += w / tau / (logsm) * 1.0  # d log(logsm)... messy; fall back
    # Fall back to plain max if tau tiny to avoid instability.
    return _fun_grad(h)


def _fun_grad_lav(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _upsample(h, factor):
    if factor <= 1:
        return h.copy()
    n = h.size
    m = n * factor
    x = np.linspace(0, n, m, endpoint=False)
    xi = np.arange(n)
    return np.interp(x, xi, h)


def _downsample(h, factor):
    if factor <= 1:
        return h.copy()
    n = h.size
    m = n // factor
    edges = np.linspace(0, n, m + 1).astype(int)
    out = np.zeros(m)
    for i in range(m):
        a, b = edges[i], edges[i + 1]
        if b > a:
            out[i] = h[a:b].mean()
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d) Lmax=%.6e argmax=%d near=%d" %
          (bestR, best.size, mx0, m0, near0))

    cur = best.copy()
    curR = bestR
    alt = None
    altR = 0.0

    # ---- Phase 0: coarse re-solve at half resolution, then upsample back.
    # The half-res problem is cheaper and its optimum (with more margin)
    # often lands in a better basin; upsampling recovers fine structure.
    if cur.size >= 8192 and time.process_time() < deadline - 20.0:
        for dfac in (2, 3):
            if time.process_time() >= deadline - 18.0:
                break
            if cur.size % dfac != 0:
                continue
            nc = cur.size // dfac
            if nc < 2048:
                continue
            low = _rescale(_downsample(cur, dfac))
            rl = R_of(low)
            for kk in (11, 7, 5, 3, 1):
                if time.process_time() >= deadline - 16.0:
                    break
                fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
                low = _lbfgs_log(low, 80, deadline, fg=fg)
                low = _lbfgs_log(low, 20, deadline)
            low = _window_polish_peak(low, deadline, 0.15, 48, maxiter=150)
            rl2 = R_of(low)
            up = _rescale(_upsample(low, dfac))
            ru = R_of(up)
            # refine upsampled at full resolution
            for kk in (9, 5, 3, 1):
                if time.process_time() >= deadline - 12.0:
                    break
                fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
                up = _lbfgs_log(up, 60, deadline, fg=fg)
                up = _lbfgs_log(up, 15, deadline)
            ru2 = R_of(up)
            print("  coarse dfac=%d low %.7f->%.7f up %.7f->%.7f" %
                  (dfac, rl, rl2, ru, ru2))
            if ru2 > altR and up.size != start_best.size:
                alt, altR = up.copy(), ru2
            if ru2 > curR + 1e-12:
                cur, curR = up, ru2
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR

    # ---- Phase 1: heavy sharpen + polish loop ----
    stage = 0
    while time.process_time() < deadline - 8.0:
        stage += 1
        improved = False
        for kk in (15, 11, 9, 7, 5, 3, 1):
            if time.process_time() >= deadline - 6.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, 60, deadline, fg=fg)
            hs = _lbfgs_log(hb, 12, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.12, 48, maxiter=100)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 1e-13:
                cur, curR = cand, rc
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  stage %d k=%d R=%.7f" % (stage, kk, curR))
        if not improved:
            break

    # ---- Phase 2: upsampling to escape resolution limit ----
    for factor in (2, 2):
        if time.process_time() >= deadline - 10.0:
            break
        n_new = cur.size * factor
        if n_new > 900000:
            break
        up = _rescale(_upsample(cur, factor))
        r_up = R_of(up)
        print("  upsample x%d -> N=%d R=%.7f (was %.7f)" %
              (factor, up.size, r_up, curR))
        cand = up
        rc = r_up
        for kk in (9, 5, 3, 1):
            if time.process_time() >= deadline - 8.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cand, 60, deadline, fg=fg)
            hs = _lbfgs_log(hb, 12, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 64, maxiter=100)
            rp = R_of(hp)
            if rp > rs:
                hs, rs = hp, rp
            if rs > rc:
                cand, rc = hs, rs
        if rc > altR:
            alt, altR = cand.copy(), rc
        if rc > curR - 1e-9:
            cur, curR = cand, rc
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
            print("  refined R=%.7f" % curR)

    # ---- Phase 3: final extended polish ----
    while time.process_time() < deadline - 2.0:
        improved = False
        for (kk, iters) in [(11, 80), (7, 100), (5, 120), (3, 150), (1, 150)]:
            if time.process_time() >= deadline - 3.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, iters, deadline, fg=fg)
            hs = _lbfgs_log(hb, 10, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=120)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  final k=%d R=%.7f" % (kk, curR))
        if not improved:
            break

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d) Lmax=%.6e argmax=%d near=%d" %
          (bestR, best.size, mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    if alt is not None and alt.size != start_best.size:
        return {"best": start_best, "alternative": alt}
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_flat_top(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    S = Lf >= tau * mx
    nS = int(S.sum())
    gLf = -dq / num
    m = int(np.argmax(Lf))
    gLf[m] += 1.0 / mx
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    if nS > 1 and kappa > 0:
        Ls = Lf[S]
        Lbar = Ls.mean()
        V = float(np.sum((Ls - Lbar) ** 2)) / (mx * mx * nS)
        val += kappa * V
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * (Ls - Lbar) / (mx * mx * nS)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, tau=0.0, kappa=0.0):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if kappa > 0:
        fg = (lambda hh: _fun_grad_flat_top(hh, tau, kappa))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _coarsen(h, n):
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == n:
        return h.copy()
    if N < n:
        return _prolongate(h, n)
    edges = np.linspace(0, N, n + 1)
    out = np.zeros(n)
    for i in range(n):
        lo = int(np.floor(edges[i]))
        hi = int(np.ceil(edges[i + 1]))
        lo = max(0, min(N, lo))
        hi = max(lo, min(N, hi))
        if hi <= lo:
            out[i] = 0.0
            continue
        xs = np.arange(lo, hi, dtype=float)
        w = np.minimum(xs + 1.0, edges[i + 1]) - np.maximum(xs, edges[i])
        w = np.clip(w, 0.0, None)
        out[i] = np.sum(h[lo:hi] * w)
    return _rescale(out)


def _prolongate(h, n):
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, N, n + 1)
    cn = np.interp(xs, np.arange(N + 1, dtype=float), c)
    out = np.diff(cn)
    out = np.clip(out, 0.0, None)
    return _rescale(out)


def _ladder(h, deadline, rungs, per_rung_sec, polish_sec, n_label, bestR_ref):
    best = h.copy()
    bestR = R_of(best)
    for (tau, kappa) in rungs:
        if time.process_time() >= deadline - 0.3:
            break
        tlim = min(deadline - 0.2, time.process_time() + per_rung_sec)
        hh = _lbfgs_block(best, np.arange(best.size), 300, tlim,
                          tau=tau, kappa=kappa)
        r = R_of(hh)
        if r > bestR:
            best, bestR = hh.copy(), r
        if time.process_time() < deadline - 0.2:
            tlim2 = min(deadline - 0.1, time.process_time() + polish_sec)
            hp = _lbfgs_block(best, np.arange(best.size), 150, tlim2, tie=True)
            rp = R_of(hp)
            if rp > bestR:
                best, bestR = hp.copy(), rp
        print("  [%s] tau=%.2f kappa=%.1f R=%.9f near 0.1/1/5%%: %.4f/%.4f/%.4f"
              % (n_label, tau, kappa, bestR, _frac_near_max(best, 1e-3),
                 _frac_near_max(best, 1e-2), _frac_near_max(best, 5e-2)))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max 0.1/1/5%%: %.4f / %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    alt_best = None
    altR = -1.0

    def record(hh):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hh)
        if r > altR:
            altR, alt_best = r, hh.copy()
        if r > bestR:
            best, bestR = hh.copy(), r

    # ---- Coarsen to n=2048 and run full deep ladder ----
    n0 = 2048
    hc = _coarsen(best, n0)
    print("coarsened to n=%d, R=%.9f" % (n0, R_of(hc)))
    rungs_full = [(0.99, 0.3), (0.95, 1.0), (0.90, 3.0), (0.85, 10.0),
                  (0.80, 30.0), (0.75, 60.0), (0.70, 100.0)]
    hc, rc = _ladder(hc, deadline, rungs_full, 2.5, 1.5, "n=%d" % n0, bestR)
    record(hc)

    # ---- Prolongate to 8192, 32768, 104992 with shortened ladders ----
    rungs_short = [(0.95, 1.0), (0.90, 3.0), (0.85, 10.0), (0.80, 30.0)]
    hp = hc
    for n1 in (8192, 32768, 104992):
        if time.process_time() >= deadline - 1.0:
            break
        hp = _prolongate(hp, n1)
        print("prolongated to n=%d, R=%.9f" % (n1, R_of(hp)))
        record(hp)
        hp, rp = _ladder(hp, deadline, rungs_short, 2.0, 1.0,
                         "n=%d" % n1, bestR)
        record(hp)

    # ---- Final polishes at N=104992 ----
    finalN = 104992
    if best.size != finalN:
        hf = _prolongate(best, finalN)
        record(hf)

    if time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.3, time.process_time() + 8.0)
        pol = _lbfgs_block(best, np.arange(best.size), 400, tlim, tie=True)
        record(pol)

    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 0.3:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 400,
                          min(deadline - 0.1, time.process_time() + 3.0),
                          tie=True)
        record(ht)

    print("frac near max 0.1/1/5%% final: %.4f / %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    # safety net
    if bestR < startR - 1e-15 and start is not None:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_flat_top(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    S = Lf >= tau * mx
    nS = int(np.count_nonzero(S))
    V = 0.0
    if nS > 1:
        Ls = Lf[S]
        Lbar = Ls.mean()
        diff = Ls - Lbar
        V = float(np.sum(diff * diff)) / (mx * mx * nS)
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * diff / (mx * mx * nS)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * V
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 flat_top=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat_top is not None:
        tau, kappa = flat_top
        fg = (lambda hh: _fun_grad_flat_top(hh, tau, kappa))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _build_target(L, eps):
    mx = L.max()
    S = L >= (1.0 - eps) * mx
    T = L.copy()
    if not np.any(S):
        return T
    idx = np.flatnonzero(S)
    lo, hi = idx.min(), idx.max()
    val = L[S].mean()
    T[lo:hi + 1] = val
    k = 9
    ker = np.ones(k) / k
    T = np.convolve(T, ker, mode='same')
    return T


def _deconv_step(h0, T, lam, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    Tn = float(np.sum(T * T))
    if Tn <= 0:
        return h0
    h0n = float(np.sum(h * h))
    if h0n <= 0:
        h0n = 1.0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        Lf = _knots(hh)
        r = Lf - T
        val = float(np.sum(r * r)) / Tn + lam * float(np.sum((hh - h) ** 2)) / h0n
        gLf = 2.0 * r / Tn
        g = _backprop(gLf, hh) + 2.0 * lam * (hh - h) / h0n
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def _fracs(h):
    return (_frac_near_max(h, 1e-3), _frac_near_max(h, 1e-2),
            _frac_near_max(h, 5e-2))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    f0 = _fracs(best)
    print("frac near max before: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % f0)

    # ---- Base path (capped at 20 s from start) as safety net ----
    base_cap = min(deadline - 1.0, t0 + budget_seconds * 0.33)
    alt_best = None
    altR = -1.0
    for eps in (1e-2, 3e-3):
        if time.process_time() >= base_cap - 6.0:
            break
        L = _knots(best)
        T = _build_target(L, eps)
        tlim = min(base_cap - 4.0, time.process_time() + 8.0)
        hd = _deconv_step(best, T, 1e-3, 60, tlim)
        rd = R_of(hd)
        if rd > altR:
            altR, alt_best = rd, hd.copy()
        if time.process_time() < base_cap - 3.0:
            pol = _lbfgs_block(hd, np.arange(hd.size), 200,
                               min(base_cap - 2.0, time.process_time() + 5.0),
                               tie=True)
            rp = R_of(pol)
            if rp > altR:
                altR, alt_best = rp, pol.copy()
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

    # ---- New phase: flat-top variance penalty on 32x quotient ----
    Q = 32
    ladder = [(0.995, 0.05), (0.99, 0.2), (0.98, 1.0),
              (0.95, 3.0), (0.90, 10.0)]

    def run_coarse_phase(cur_best, curR, time_cap):
        n = cur_best.size
        if n % Q != 0:
            return cur_best, curR, None
        qh = _coarsen(cur_best, Q)
        if qh is None:
            return cur_best, curR, None
        qh = _rescale(qh)
        qR = R_of(qh)
        best_qh = qh.copy()
        best_qR = qR
        pre_prolong = None
        for (tau, kappa) in ladder:
            if time.process_time() >= time_cap - 3.0:
                break
            tlim = min(time_cap - 2.0, time.process_time() + 3.0)
            cand = _lbfgs_block(best_qh, np.arange(best_qh.size), 120,
                                tlim, flat_top=(tau, kappa))
            if time.process_time() < time_cap - 1.5:
                cand = _lbfgs_block(cand, np.arange(cand.size), 120,
                                    min(time_cap - 1.0, time.process_time() + 2.0),
                                    tie=True)
            r = R_of(cand)
            if r > best_qR:
                best_qh, best_qR = cand.copy(), r
            if pre_prolong is None:
                pre_prolong = cand.copy()
            ph = _prolongate(cand, Q)
            pr = R_of(ph)
            fr = _fracs(ph)
            print("tau=%.3f kappa=%.2f coarse R=%.9f prolonged R=%.9f "
                  "0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
                  % (tau, kappa, r, pr, fr[0], fr[1], fr[2]))
            if pr > curR + 1e-15:
                cur_best, curR = ph.copy(), pr
        return cur_best, curR, pre_prolong

    # Step 1
    if time.process_time() < deadline - 8.0:
        cap1 = min(deadline - 8.0, time.process_time() + 20.0)
        nb, nR, pre = run_coarse_phase(best, bestR, cap1)
        if nR > bestR:
            best, bestR = nb, nR
        if pre is not None:
            alt_best, altR = pre, R_of(pre)

        # Step 2: prolongate best-coarse, full tie + peak window polishes
        if time.process_time() < deadline - 4.0:
            if best.size % Q == 0:
                qh = _rescale(_coarsen(best, Q))
                ph = _prolongate(qh, Q)
            else:
                ph = best.copy()
            if time.process_time() < deadline - 3.0:
                pol = _lbfgs_block(ph, np.arange(ph.size), 200,
                                   min(deadline - 2.5, time.process_time() + 8.0),
                                   tie=True)
                rp = R_of(pol)
                if rp > bestR + 1e-15:
                    best, bestR = pol.copy(), rp
            for pad in (0.05, 0.03):
                if time.process_time() >= deadline - 1.5:
                    break
                win = _peak_window(best, pad_frac=pad, extra=96)
                ht = _lbfgs_block(best, win, 300,
                                  min(deadline - 1.0, time.process_time() + 3.0),
                                  tie=True)
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r

        # Step 3: repeat coarse phase once more if time remains
        if time.process_time() < deadline - 6.0:
            cap2 = deadline - 1.0
            nb, nR, pre2 = run_coarse_phase(best, bestR, cap2)
            if nR > bestR:
                best, bestR = nb, nR
            if pre2 is not None and R_of(pre2) > altR:
                alt_best, altR = pre2, R_of(pre2)

    # Final safety net
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 3.0),
                           tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    fa = _fracs(best)
    print("frac near max after: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % fa)
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size <= 1000000:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_flat_top(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    S = Lf >= tau * mx
    nS = int(np.count_nonzero(S))
    V = 0.0
    if nS > 1:
        Ls = Lf[S]
        Lbar = Ls.mean()
        diff = Ls - Lbar
        V = float(np.sum(diff * diff)) / (mx * mx * nS)
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * diff / (mx * mx * nS)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * V
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 flat_top=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat_top is not None:
        tau, kappa = flat_top
        fg = (lambda hh: _fun_grad_flat_top(hh, tau, kappa))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _build_target(L, eps):
    mx = L.max()
    S = L >= (1.0 - eps) * mx
    T = L.copy()
    if not np.any(S):
        return T
    idx = np.flatnonzero(S)
    lo, hi = idx.min(), idx.max()
    val = L[S].mean()
    T[lo:hi + 1] = val
    k = 9
    ker = np.ones(k) / k
    T = np.convolve(T, ker, mode='same')
    return T


def _deconv_step(h0, T, lam, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    Tn = float(np.sum(T * T))
    if Tn <= 0:
        return h0
    h0n = float(np.sum(h * h))
    if h0n <= 0:
        h0n = 1.0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        Lf = _knots(hh)
        r = Lf - T
        val = float(np.sum(r * r)) / Tn + lam * float(np.sum((hh - h) ** 2)) / h0n
        gLf = 2.0 * r / Tn
        g = _backprop(gLf, hh) + 2.0 * lam * (hh - h) / h0n
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def _fracs(h):
    return (_frac_near_max(h, 1e-3), _frac_near_max(h, 1e-2),
            _frac_near_max(h, 5e-2))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    f0 = _fracs(best)
    print("frac near max before: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % f0)

    # ---- Base path (capped at 20 s from start) as safety net ----
    base_cap = min(deadline - 1.0, t0 + budget_seconds * 0.33)
    alt_best = None
    altR = -1.0
    for eps in (1e-2, 3e-3):
        if time.process_time() >= base_cap - 6.0:
            break
        L = _knots(best)
        T = _build_target(L, eps)
        tlim = min(base_cap - 4.0, time.process_time() + 8.0)
        hd = _deconv_step(best, T, 1e-3, 60, tlim)
        rd = R_of(hd)
        if rd > altR:
            altR, alt_best = rd, hd.copy()
        if time.process_time() < base_cap - 3.0:
            pol = _lbfgs_block(hd, np.arange(hd.size), 200,
                               min(base_cap - 2.0, time.process_time() + 5.0),
                               tie=True)
            rp = R_of(pol)
            if rp > altR:
                altR, alt_best = rp, pol.copy()
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

    # ---- New phase: flat-top variance penalty on 32x quotient ----
    Q = 32
    ladder = [(0.995, 0.05), (0.99, 0.2), (0.98, 1.0),
              (0.95, 3.0), (0.90, 10.0)]

    def run_coarse_phase(cur_best, curR, time_cap):
        n = cur_best.size
        if n % Q != 0:
            return cur_best, curR, None
        qh = _coarsen(cur_best, Q)
        if qh is None:
            return cur_best, curR, None
        qh = _rescale(qh)
        qR = R_of(qh)
        best_qh = qh.copy()
        best_qR = qR
        pre_prolong = None
        for (tau, kappa) in ladder:
            if time.process_time() >= time_cap - 3.0:
                break
            tlim = min(time_cap - 2.0, time.process_time() + 3.0)
            cand = _lbfgs_block(best_qh, np.arange(best_qh.size), 120,
                                tlim, flat_top=(tau, kappa))
            if time.process_time() < time_cap - 1.5:
                cand = _lbfgs_block(cand, np.arange(cand.size), 120,
                                    min(time_cap - 1.0, time.process_time() + 2.0),
                                    tie=True)
            r = R_of(cand)
            if r > best_qR:
                best_qh, best_qR = cand.copy(), r
            if pre_prolong is None:
                pre_prolong = cand.copy()
            ph = _prolongate(cand, Q)
            pr = R_of(ph)
            fr = _fracs(ph)
            print("tau=%.3f kappa=%.2f coarse R=%.9f prolonged R=%.9f "
                  "0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
                  % (tau, kappa, r, pr, fr[0], fr[1], fr[2]))
            if pr > curR + 1e-15:
                cur_best, curR = ph.copy(), pr
        return cur_best, curR, pre_prolong

    # Step 1
    if time.process_time() < deadline - 8.0:
        cap1 = min(deadline - 8.0, time.process_time() + 20.0)
        nb, nR, pre = run_coarse_phase(best, bestR, cap1)
        if nR > bestR:
            best, bestR = nb, nR
        if pre is not None:
            alt_best, altR = pre, R_of(pre)

        # Step 2: prolongate best-coarse, full tie + peak window polishes
        if time.process_time() < deadline - 4.0:
            if best.size % Q == 0:
                qh = _rescale(_coarsen(best, Q))
                ph = _prolongate(qh, Q)
            else:
                ph = best.copy()
            if time.process_time() < deadline - 3.0:
                pol = _lbfgs_block(ph, np.arange(ph.size), 200,
                                   min(deadline - 2.5, time.process_time() + 8.0),
                                   tie=True)
                rp = R_of(pol)
                if rp > bestR + 1e-15:
                    best, bestR = pol.copy(), rp
            for pad in (0.05, 0.03):
                if time.process_time() >= deadline - 1.5:
                    break
                win = _peak_window(best, pad_frac=pad, extra=96)
                ht = _lbfgs_block(best, win, 300,
                                  min(deadline - 1.0, time.process_time() + 3.0),
                                  tie=True)
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r

        # Step 3: repeat coarse phase once more if time remains
        if time.process_time() < deadline - 6.0:
            cap2 = deadline - 1.0
            nb, nR, pre2 = run_coarse_phase(best, bestR, cap2)
            if nR > bestR:
                best, bestR = nb, nR
            if pre2 is not None and R_of(pre2) > altR:
                alt_best, altR = pre2, R_of(pre2)

    # Final safety net
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 3.0),
                           tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    fa = _fracs(best)
    print("frac near max after: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % fa)
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size <= 1000000:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _refine(h, deadline, rounds=6):
    """Alternate full and peak-window tie polishes, plus a beta-smoothed pass."""
    best = h.copy()
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        # full tie polish
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.5, time.process_time() + 5.0), tie=True)
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        # beta-smoothed pass (helps escape exact-tie degeneracies)
        if time.process_time() < deadline - 1.0:
            for beta in (50.0, 200.0):
                if time.process_time() >= deadline - 0.6:
                    break
                pb = _lbfgs_block(best, np.arange(best.size), 200,
                                 min(deadline - 0.4, time.process_time() + 4.0),
                                 beta=beta)
                rb = R_of(pb)
                if rb > bestR:
                    best, bestR = pb, rb
        # peak-window polish at increasing tightness
        for pad in (0.10, 0.05, 0.02):
            if time.process_time() >= deadline - 0.6:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 300,
                              min(deadline - 0.3, time.process_time() + 3.0), tie=True)
            r = R_of(ht)
            if r > bestR:
                best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%) before: %.4f" % _frac_near_max(best, 1e-3))

    # Main: repeatedly refine the start with tie/beta/window polishes.
    alt_best = None
    altR = -1.0

    if time.process_time() < deadline - 1.0:
        ref, refR = _refine(best, deadline, rounds=8)
        print("refine: R=%.12f (frac near max=%.4f)" % (refR, _frac_near_max(ref, 1e-3)))
        if refR > altR:
            altR, alt_best = refR, ref.copy()
        if refR > bestR + 1e-15:
            best, bestR = ref.copy(), refR

    print("frac near max (0.1%%) after: %.4f" % _frac_near_max(best, 1e-3))

    # Final safety: never return worse than start.
    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d)"
          % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_sm(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_sm(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _peak_window(h, frac, pad):
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    half = max(4, int(frac * n)) + pad
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _near_max_window(h, tol=0.999, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(512)
        best_r = R_of(best)
        start_arr = None

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    alt_returned = None

    # ---- Primary idea: refine on a finer grid; accept if mapped-back improves. ----
    if cur.size < 300000 and time.process_time() < deadline - 25.0:
        N_up = min(cur.size * 2, 500000)
        up = _rescale(_prolongate(cur, N_up))
        up = _lbfgs_log(up, maxiter=500, deadline=deadline - 20.0)
        for frac, pad in ((0.05, 4), (0.15, 10)):
            if time.process_time() >= deadline - 18.0:
                break
            win = _peak_window(up, frac, pad)
            cand = _lbfgs_block(up, win, maxiter=400, deadline=deadline - 18.0)
            if R_of(cand) > R_of(up):
                up = cand
        up_r = R_of(up)
        print("fine refine R = %.6f (N=%d)" % (up_r, N_up))
        back = _rescale(_coarsen(up, cur.size))
        back_r = R_of(back)
        if back_r > best_r:
            best, best_r = back.copy(), back_r
            cur, cur_r = back.copy(), back_r
        elif up_r > best_r:
            best, best_r = up.copy(), up_r
            cur, cur_r = up.copy(), up_r
        else:
            alt_returned = up.copy()

    # ---- Region-restricted polish of the current best on its own grid. ----
    if time.process_time() < deadline - 8.0:
        for frac, pad in ((0.02, 2), (0.05, 4), (0.12, 8)):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(cur, frac, pad)
            cand = _lbfgs_block(cur, win, maxiter=600, deadline=deadline - 8.0)
            rc = R_of(cand)
            if rc > cur_r:
                cur, cur_r = cand, rc
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r

    # ---- Smoothing continuation ----
    for beta in (4, 16, 64):
        if time.process_time() >= deadline - 4.0:
            break
        c2 = _lbfgs_log(cur, maxiter=200, deadline=deadline, beta=beta)
        r2 = R_of(c2)
        if r2 > cur_r:
            cur, cur_r = c2, r2
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        print("  beta=%d R=%.6f" % (beta, cur_r))

    # ---- Main loop: alternate full and windowed polish, restart on stall. ----
    restart_tries = 0
    no_improve = 0
    last_r = cur_r
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        for frac, pad in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cur, frac, pad)
            cand = _lbfgs_block(cur, win, maxiter=500, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt_returned is not None and alt_returned.size != best.size:
            out["alternative"] = alt_returned
        else:
            out["alternative"] = start_arr
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
