    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    alt_returned = None

    # ---- Primary idea: refine on a finer grid; accept if mapped-back improves. ----
    if cur.size < 300000 and time.process_time() < deadline - 25.0:
        N_up = min(cur.size * 2, 500000)
        up = _rescale(_prolongate(cur, N_up))
        up = _lbfgs_log(up, maxiter=500, deadline=deadline - 20.0)
        for frac, pad in ((0.05, 4), (0.15, 10)):
            if time.process_time() >= deadline - 18.0:
                break
            win = _peak_window(up, frac, pad)
            cand = _lbfgs_block(up, win, maxiter=400, deadline=deadline - 18.0)
            if R_of(cand) > R_of(up):
                up = cand
        up_r = R_of(up)
        print("fine refine R = %.6f (N=%d)" % (up_r, N_up))
        back = _rescale(_coarsen(up, cur.size))
        back_r = R_of(back)
        if back_r > best_r:
            best, best_r = back.copy(), back_r
            cur, cur_r = back.copy(), back_r
        elif up_r > best_r:
            best, best_r = up.copy(), up_r
            cur, cur_r = up.copy(), up_r
        else:
            alt_returned = up.copy()

    # ---- Region-restricted polish of the current best on its own grid. ----
    if time.process_time() < deadline - 8.0:
        for frac, pad in ((0.02, 2), (0.05, 4), (0.12, 8)):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(cur, frac, pad)
            cand = _lbfgs_block(cur, win, maxiter=600, deadline=deadline - 8.0)
            rc = R_of(cand)
            if rc > cur_r:
                cur, cur_r = cand, rc
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r

    # ---- Smoothing continuation ----
    for beta in (4, 16, 64):
        if time.process_time() >= deadline - 4.0:
            break
        c2 = _lbfgs_log(cur, maxiter=200, deadline=deadline, beta=beta)
        r2 = R_of(c2)
        if r2 > cur_r:
            cur, cur_r = c2, r2
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        print("  beta=%d R=%.6f" % (beta, cur_r))

    # ---- Main loop: alternate full and windowed polish, restart on stall. ----
    restart_tries = 0
    no_improve = 0
    last_r = cur_r
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        for frac, pad in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cur, frac, pad)
            cand = _lbfgs_block(cur, win, maxiter=500, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt_returned is not None and alt_returned.size != best.size:
            out["alternative"] = alt_returned
        else:
            out["alternative"] = start_arr
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.14, 0.09, 0.06, 0.04),
                 iters=400):
    best = h.copy()
    bestR = R_of(best)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2, r2
    return best, bestR


def _half_polish(c, bestR, deadline):
    best = c.copy()
    work = c.copy()
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
    for pad in [0.30, 0.20, 0.14, 0.10, 0.06]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
    return work, best, bestR


def _extract(c_full, k, m):
    if k == 0:
        c = c_full[0::2][:m].copy()
    elif k == 1:
        c = c_full[1::2][:m].copy()
    else:
        a = c_full[0::2][:m]
        b = c_full[1::2][:m]
        L = min(a.size, b.size)
        c = 0.5 * (a[:L] + b[:L])
        if c.size < m:
            c = np.concatenate((c, np.full(m - c.size, c[-1])))
    return c


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _shift_and_polish(h, shift, deadline, span=512):
    """Shift the pattern by `shift` steps, then polish a window around the peak."""
    N = h.size
    if shift == 0:
        return h
    h2 = np.zeros(N)
    if shift > 0:
        if shift < N:
            h2[shift:] = h[:N - shift]
    else:
        s = -shift
        if s < N:
            h2[:N - s] = h[s:]
    h2 = _rescale(h2)
    if time.process_time() >= deadline - 0.3:
        return h2
    win = _peak_window(h2, pad_frac=0.25, extra=span)
    h2 = _lbfgs_block(h2, win, 300, deadline - 0.2, beta=1e7)
    h2 = _lbfgs_all_pos(h2, 200, deadline - 0.2, beta=0.0)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 0: NEW -- translation search on the existing pattern ----
    # The score is invariant to translating h (f*f just translates too, and
    # ||.||_1, ||.||_2, ||.||_inf are translation-invariant).  But short-window
    # polishing is not translation invariant, so trying a spread of shifts and
    # polishing the peak window after each may find a slightly better local
    # optimum.  This is cheap and orthogonal to the existing phases.
    if time.process_time() < deadline - 6.0 and best.size >= 32:
        N = best.size
        act = np.flatnonzero(best > 0.01 * best.max())
        if act.size > 0:
            # cycle the pattern so that its mass starts at step 0
            shift0 = -int(act[0])
            hshift = _shift_and_polish(best, shift0, min(deadline - 4.0,
                                                         t0 + 0.12 * budget_seconds))
            r = R_of(hshift)
            if r > bestR + 1e-14:
                best, bestR, origin = hshift.copy(), r, 'shift0'
                print("  shift0 NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = hshift.copy(), r
        # try a handful of small shifts around the current alignment
        rng = np.random.RandomState(7)
        trial_end = t0 + 0.22 * budget_seconds
        tried = 0
        while time.process_time() < trial_end and tried < 12:
            tried += 1
            sh = int(rng.randint(-best.size // 8, best.size // 8 + 1))
            if sh == 0:
                continue
            slice_dl = min(deadline - 4.0, time.process_time() + 0.02 * budget_seconds)
            if slice_dl <= time.process_time() + 0.4:
                break
            hs = _shift_and_polish(best, sh, slice_dl)
            r = R_of(hs)
            if r > bestR + 1e-14:
                best, bestR, origin = hs.copy(), r, 'shift%d' % sh
                print("  shift %d NEW BEST R=%.9f" % (sh, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = hs.copy(), r
        print("shift search done tried=%d bestR=%.9f" % (tried, bestR))

    # ---- Phase 1: half-resolution quotient search ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.42
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR = _half_polish(work_c, best_cR, half_deadline)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: rotation of extract/lift cycles (all three variants) ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 8.0
        max_cycles = 9
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 6.0, now + 0.05 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            c = _extract(wk, k, m)
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR = _half_polish(c, cR0, slice_dl)
            except Exception:
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception:
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: structural edits (split/merge/move) ----
    struct_end = deadline - 5.0
    if time.process_time() < struct_end - 1.0 and best.size >= 4:
        Ns = best.size
        rng = np.random.RandomState(424242)
        trial = 0
        accepted = 0
        while time.process_time() < struct_end - 1.0:
            act = np.flatnonzero(best > 0.02 * best.max())
            if act.size == 0:
                break
            perm = rng.permutation(act)
            progressed = False
            for i in perm:
                i = int(i)
                if time.process_time() >= struct_end - 1.0:
                    break
                now = time.process_time()
                slice_dl = min(now + 1.0, deadline - 5.0)
                if slice_dl <= now + 0.3:
                    break
                trial += 1
                cands = []
                v = best[i]
                if v > 0:
                    for d in (-1, +1, -2, +2):
                        j = i + d
                        if 0 <= j < Ns and best[j] <= 0:
                            h2 = best.copy()
                            h2[i] = 0.0
                            h2[j] = h2[j] + v
                            cands.append(('move%d' % d, h2))
                            break
                if i + 1 < Ns:
                    h2 = best.copy()
                    half = 0.5 * best[i]
                    h2[i] = half
                    h2[i + 1] = h2[i + 1] + half
                    cands.append(('split', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    a = best[i] * (1.0 / 3.0)
                    h2[i] = a
                    h2[i + 1] = h2[i + 1] + (best[i] - a)
                    cands.append(('split2', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    h2[i] = h2[i] + h2[i + 1]
                    h2[i + 1] = 0.0
                    cands.append(('merge', h2))
                best_local = None
                best_localR = -1.0
                best_type = None
                for typ, h2 in cands:
                    if time.process_time() >= slice_dl - 0.3:
                        break
                    h2 = _rescale(np.clip(h2, 0, None))
                    win = _peak_window(h2, pad_frac=0.15, extra=384)
                    h2 = _lbfgs_block(h2, win, 120, slice_dl, beta=1e6)
                    if time.process_time() < slice_dl - 0.3:
                        h2 = _lbfgs_all_pos(h2, 120, slice_dl, beta=1e7)
                    r2 = R_of(h2)
                    if r2 > best_localR:
                        best_local, best_localR, best_type = h2, r2, typ
                if best_local is None:
                    continue
                progressed = True
                if best_localR > bestR + 1e-13:
                    best, bestR = best_local.copy(), best_localR
                    origin = 'struct_%s' % best_type
                    accepted += 1
                    print("struct trial %d %s at i=%d NEW BEST R=%.9f" %
                          (trial, best_type, i, bestR))
                elif best_localR > alt_bestR:
                    alt_best, alt_bestR = best_local.copy(), best_localR
            if not progressed:
                break
        print("struct edits done trials=%d accepted=%d bestR=%.9f" %
              (trial, accepted, bestR))

    # ---- Phase 4: final ladder polish ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _peak_ladder(best, deadline)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.14, 0.09, 0.06, 0.04),
                 iters=400):
    best = h.copy()
    bestR = R_of(best)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2, r2
    return best, bestR


def _half_polish(c, bestR, deadline):
    best = c.copy()
    work = c.copy()
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
    for pad in [0.30, 0.20, 0.14, 0.10, 0.06]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
    return work, best, bestR


def _extract(c_full, k, m):
    if k == 0:
        c = c_full[0::2][:m].copy()
    elif k == 1:
        c = c_full[1::2][:m].copy()
    else:
        a = c_full[0::2][:m]
        b = c_full[1::2][:m]
        L = min(a.size, b.size)
        c = 0.5 * (a[:L] + b[:L])
        if c.size < m:
            c = np.concatenate((c, np.full(m - c.size, c[-1])))
    return c


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _shift_and_polish(h, shift, deadline, span=512):
    """Shift the pattern by `shift` steps, then polish a window around the peak."""
    N = h.size
    if shift == 0:
        return h
    h2 = np.zeros(N)
    if shift > 0:
        if shift < N:
            h2[shift:] = h[:N - shift]
    else:
        s = -shift
        if s < N:
            h2[:N - s] = h[s:]
    h2 = _rescale(h2)
    if time.process_time() >= deadline - 0.3:
        return h2
    win = _peak_window(h2, pad_frac=0.25, extra=span)
    h2 = _lbfgs_block(h2, win, 300, deadline - 0.2, beta=1e7)
    h2 = _lbfgs_all_pos(h2, 200, deadline - 0.2, beta=0.0)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 0: NEW -- translation search on the existing pattern ----
    # The score is invariant to translating h (f*f just translates too, and
    # ||.||_1, ||.||_2, ||.||_inf are translation-invariant).  But short-window
    # polishing is not translation invariant, so trying a spread of shifts and
    # polishing the peak window after each may find a slightly better local
    # optimum.  This is cheap and orthogonal to the existing phases.
    if time.process_time() < deadline - 6.0 and best.size >= 32:
        N = best.size
        act = np.flatnonzero(best > 0.01 * best.max())
        if act.size > 0:
            # cycle the pattern so that its mass starts at step 0
            shift0 = -int(act[0])
            hshift = _shift_and_polish(best, shift0, min(deadline - 4.0,
                                                         t0 + 0.12 * budget_seconds))
            r = R_of(hshift)
            if r > bestR + 1e-14:
                best, bestR, origin = hshift.copy(), r, 'shift0'
                print("  shift0 NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = hshift.copy(), r
        # try a handful of small shifts around the current alignment
        rng = np.random.RandomState(7)
        trial_end = t0 + 0.22 * budget_seconds
        tried = 0
        while time.process_time() < trial_end and tried < 12:
            tried += 1
            sh = int(rng.randint(-best.size // 8, best.size // 8 + 1))
            if sh == 0:
                continue
            slice_dl = min(deadline - 4.0, time.process_time() + 0.02 * budget_seconds)
            if slice_dl <= time.process_time() + 0.4:
                break
            hs = _shift_and_polish(best, sh, slice_dl)
            r = R_of(hs)
            if r > bestR + 1e-14:
                best, bestR, origin = hs.copy(), r, 'shift%d' % sh
                print("  shift %d NEW BEST R=%.9f" % (sh, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = hs.copy(), r
        print("shift search done tried=%d bestR=%.9f" % (tried, bestR))

    # ---- Phase 1: half-resolution quotient search ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.42
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR = _half_polish(work_c, best_cR, half_deadline)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: rotation of extract/lift cycles (all three variants) ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 8.0
        max_cycles = 9
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 6.0, now + 0.05 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            c = _extract(wk, k, m)
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR = _half_polish(c, cR0, slice_dl)
            except Exception:
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception:
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: structural edits (split/merge/move) ----
    struct_end = deadline - 5.0
    if time.process_time() < struct_end - 1.0 and best.size >= 4:
        Ns = best.size
        rng = np.random.RandomState(424242)
        trial = 0
        accepted = 0
        while time.process_time() < struct_end - 1.0:
            act = np.flatnonzero(best > 0.02 * best.max())
            if act.size == 0:
                break
            perm = rng.permutation(act)
            progressed = False
            for i in perm:
                i = int(i)
                if time.process_time() >= struct_end - 1.0:
                    break
                now = time.process_time()
                slice_dl = min(now + 1.0, deadline - 5.0)
                if slice_dl <= now + 0.3:
                    break
                trial += 1
                cands = []
                v = best[i]
                if v > 0:
                    for d in (-1, +1, -2, +2):
                        j = i + d
                        if 0 <= j < Ns and best[j] <= 0:
                            h2 = best.copy()
                            h2[i] = 0.0
                            h2[j] = h2[j] + v
                            cands.append(('move%d' % d, h2))
                            break
                if i + 1 < Ns:
                    h2 = best.copy()
                    half = 0.5 * best[i]
                    h2[i] = half
                    h2[i + 1] = h2[i + 1] + half
                    cands.append(('split', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    a = best[i] * (1.0 / 3.0)
                    h2[i] = a
                    h2[i + 1] = h2[i + 1] + (best[i] - a)
                    cands.append(('split2', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    h2[i] = h2[i] + h2[i + 1]
                    h2[i + 1] = 0.0
                    cands.append(('merge', h2))
                best_local = None
                best_localR = -1.0
                best_type = None
                for typ, h2 in cands:
                    if time.process_time() >= slice_dl - 0.3:
                        break
                    h2 = _rescale(np.clip(h2, 0, None))
                    win = _peak_window(h2, pad_frac=0.15, extra=384)
                    h2 = _lbfgs_block(h2, win, 120, slice_dl, beta=1e6)
                    if time.process_time() < slice_dl - 0.3:
                        h2 = _lbfgs_all_pos(h2, 120, slice_dl, beta=1e7)
                    r2 = R_of(h2)
                    if r2 > best_localR:
                        best_local, best_localR, best_type = h2, r2, typ
                if best_local is None:
                    continue
                progressed = True
                if best_localR > bestR + 1e-13:
                    best, bestR = best_local.copy(), best_localR
                    origin = 'struct_%s' % best_type
                    accepted += 1
                    print("struct trial %d %s at i=%d NEW BEST R=%.9f" %
                          (trial, best_type, i, bestR))
                elif best_localR > alt_bestR:
                    alt_best, alt_bestR = best_local.copy(), best_localR
            if not progressed:
                break
        print("struct edits done trials=%d accepted=%d bestR=%.9f" %
              (trial, accepted, bestR))

    # ---- Phase 4: final ladder polish ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _peak_ladder(best, deadline)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0.0, None)
    # sum L^p
    Sp = np.sum(Lp ** p)
    if Sp <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num + (Lp ** (p - 1.0)) / Sp
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (1.0 / p) * np.log(Sp)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, pnorm=None, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if pnorm is not None:
        fg = (lambda hh: _fun_grad_pnorm(hh, pnorm))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _check_staircase(h, q):
    n = h.size
    if n % q != 0:
        return False
    blocks = h.reshape(-1, q)
    return bool(np.all(np.abs(blocks - blocks[:, :1]) <= 1e-9 * (1.0 + np.abs(blocks[:, :1]))))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max 0.1/1/5%% before: %.4f/%.4f/%.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2), _frac_near_max(best, 5e-2)))

    # ---- D8 flip: p-norm surrogate of inf-norm, at quotient resolution ----
    alt_best = None
    altR = -1.0

    N = best.size
    q = 32
    if N % q == 0 and _check_staircase(best, q):
        c0 = best[0::q].copy()
        print("staircase verified, quotient size %d" % c0.size)
    else:
        # fall back to block means
        nb = N // q
        c0 = best[:nb * q].reshape(nb, q).mean(axis=1)
        print("staircase NOT exact, using block means, quotient size %d" % c0.size)
    c0 = _rescale(c0)
    cR = R_of(c0)
    print("quotient R=%.9f" % cR)

    best_c = c0.copy()
    best_cR = cR

    p_list = [4, 8, 16, 32, 64, 128]
    for p in p_list:
        if time.process_time() >= deadline - 6.0:
            break
        tlim = min(deadline - 5.0, time.process_time() + 4.0)
        cp = _lbfgs_block(best_c, np.arange(best_c.size), 400, tlim, pnorm=p)
        rp = R_of(cp)
        # short exact tie polish
        if time.process_time() < deadline - 4.0:
            tlim2 = min(deadline - 3.5, time.process_time() + 1.5)
            cp2 = _lbfgs_block(cp, np.arange(cp.size), 100, tlim2, tie=True)
            rp2 = R_of(cp2)
            if rp2 >= rp:
                cp, rp = cp2, rp2
        print("p=%d exact R=%.12f  near-max 0.1/1/5%%: %.4f/%.4f/%.4f"
              % (p, rp, _frac_near_max(cp, 1e-3), _frac_near_max(cp, 1e-2), _frac_near_max(cp, 5e-2)))
        if rp > best_cR:
            best_c, best_cR = cp.copy(), rp
        if rp > altR:
            altR = rp
            alt_best = cp.copy()

    # expand best quotient back to N
    if best_c.size * q == N:
        h_exp = np.repeat(best_c, q)
    else:
        h_exp = np.repeat(best_c, q)[:N]
        if h_exp.size < N:
            h_exp = np.concatenate([h_exp, np.full(N - h_exp.size, h_exp[-1])])
    h_exp = _rescale(h_exp)
    r_exp = R_of(h_exp)
    print("expanded R=%.12f" % r_exp)
    if r_exp > altR:
        altR = r_exp
        alt_best = h_exp.copy()
    if r_exp > bestR + 1e-15:
        best, bestR = h_exp.copy(), r_exp

    # native tie polish
    if time.process_time() < deadline - 4.0:
        tlim = min(deadline - 3.0, time.process_time() + 6.0)
        pol = _lbfgs_block(best, np.arange(best.size), 300, tlim, tie=True)
        rp = R_of(pol)
        print("native polish R=%.12f" % rp)
        if rp > altR:
            altR = rp
            alt_best = pol.copy()
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    # peak-window polishes
    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        ht = _lbfgs_block(best, win, 300, tlim, tie=True)
        r = R_of(ht)
        if r > altR:
            altR = r
            alt_best = ht.copy()
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    print("frac near max 0.1/1/5%% after: %.4f/%.4f/%.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2), _frac_near_max(best, 5e-2)))

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _smooth_noise(n, w, rng):
    g = rng.standard_normal(n)
    if w <= 0:
        return g
    k = int(w)
    ker = np.exp(-0.5 * (np.arange(-3 * k, 3 * k + 1) / max(k, 1)) ** 2)
    ker /= ker.sum()
    out = np.convolve(g, ker, mode='same')
    sd = out.std()
    if sd > 0:
        out /= sd
    return out


def _box_smooth(c, w):
    if w <= 1:
        return c.copy()
    k = int(w)
    ker = np.ones(k) / k
    return np.convolve(c, ker, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Detect 32x staircase ----
    N = best.size
    stride = 32
    Nq = N // stride
    exact_stair = False
    if Nq * stride == N and Nq > 0:
        mat = best[:Nq * stride].reshape(Nq, stride)
        dev = np.max(np.abs(mat - mat[:, :1]))
        if dev <= 1e-9 * max(1.0, best.max()):
            exact_stair = True
    if exact_stair:
        c = best[:Nq * stride].reshape(Nq, stride)[:, 0].copy()
        print("exact 32x staircase detected, Nq=%d" % Nq)
    else:
        c = best[:Nq * stride].reshape(Nq, stride).mean(axis=1)
        print("using block means, Nq=%d" % Nq)

    c = _rescale(c)
    cR = R_of(c)
    print("quotient R=%.12f" % cR)

    rng = np.random.default_rng(12345)
    sigmas = [0.003, 0.01, 0.03]
    widths = [1, 2, 4, 8, 16, 32]

    trial = 0
    best_c = c.copy()
    best_cR = cR

    while time.process_time() < deadline - 2.0:
        trial += 1
        if trial % 10 == 0:
            w = int(rng.choice(widths))
            c_try = _box_smooth(best_c, w)
            c_try = _rescale(c_try)
        elif rng.random() < 0.2:
            w = int(rng.choice(widths))
            c_try = _box_smooth(best_c, w)
            c_try = _rescale(c_try)
        else:
            sigma = float(rng.choice(sigmas))
            w = int(rng.choice(widths))
            noise = _smooth_noise(best_c.size, w, rng)
            c_try = best_c * np.exp(sigma * noise)
            c_try = _rescale(c_try)

        tlim = min(deadline - 1.5, time.process_time() + 0.5)
        c_new = _lbfgs_block(c_try, np.arange(c_try.size), 200, tlim, tie=True)
        r_new = R_of(c_new)
        if r_new > best_cR + 1e-15:
            best_c = c_new.copy()
            best_cR = r_new

    print("trials=%d best quotient R=%.12f" % (trial, best_cR))

    # ---- Expand back to native and polish ----
    native = np.repeat(best_c, stride)
    native = _rescale(native)
    natR = R_of(native)
    print("expanded native R=%.12f" % natR)

    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(native, np.arange(native.size), 200,
                           min(deadline - 0.5, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        if rp > natR:
            native, natR = pol, rp

    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(native, pad_frac=pad, extra=96)
        ht = _lbfgs_block(native, win, 300,
                          min(deadline - 0.2, time.process_time() + 2.0), tie=True)
        r = R_of(ht)
        if r > natR:
            native, natR = ht, r

    if natR > bestR:
        best, bestR = native, natR
    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("frac near max 0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2), _frac_near_max(best, 5e-2)))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0.0, None)
    Lp = Lc ** p
    S = Lp.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = S ** (1.0 / p)
    if sm <= 0:
        return _fun_grad(h)
    w = Lc ** (p - 1) / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if free is None:
        active = np.arange(h.size)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- p-norm smoothing ladder ----
    pnorm_deadline = t0 + budget_seconds * 0.45
    ps = (4, 8, 16, 32, 64, 128)
    per_p = budget_seconds * 0.06
    for p in ps:
        if time.process_time() >= pnorm_deadline - 1.0:
            break
        dp = min(pnorm_deadline, time.process_time() + per_p)
        fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
        ht = _lbfgs(best, None, 200, dp, fg)
