          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _refine(h, deadline, rounds=6):
    best = h.copy()
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.5, time.process_time() + 5.0))
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        if time.process_time() < deadline - 1.0:
            for beta in (50.0, 200.0):
                if time.process_time() >= deadline - 0.6:
                    break
                pb = _lbfgs_block(best, np.arange(best.size), 200,
                                 min(deadline - 0.4, time.process_time() + 4.0),
                                 beta=beta)
                rb = R_of(pb)
                if rb > bestR:
                    best, bestR = pb, rb
        if time.process_time() < deadline - 1.0:
            win = _peak_window(best)
            pw = _lbfgs_block(best, win, 400,
                             min(deadline - 0.4, time.process_time() + 4.0))
            rw = R_of(pw)
            if rw > bestR:
                best, bestR = pw, rw
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, 800, deadline)
        cur, _ = _refine(cur, deadline)
        return cur

    cur = best.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    rng = np.random.default_rng(20240126)

    while time.process_time() < deadline - 0.8:
        # Focused band-flattening: beta tuned to actual near-max spread.
        Lf = _knots(cur)
        M = Lf.max()
        near = Lf[Lf >= 0.98 * M]
        if near.size > 1:
            spread = (M - near.min()) / max(M, 1e-12)
            beta_focus = float(np.clip(4.0 / max(spread, 1e-6), 100.0, 8000.0))
        else:
            beta_focus = 1500.0

        cand = _lbfgs_log(cur, 400, deadline - 0.5, beta=beta_focus)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        cand = _lbfgs_log(cur, 800, deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_log(cur, 300, deadline - 0.5, beta=beta)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        cand = _lbfgs_log(cur, 800, deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        # Peak-window polish (block method, broader window than before)
        win = _peak_window(cur, tol=0.999, pad_frac=0.5, extra=64)
        cand = _lbfgs_block(cur, win, 500, deadline - 0.5, beta=800.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        # Mutation: perturb a random block, then refine it fully.
        n = cur.size
        trial = cur.copy()
        blk = int(rng.integers(max(4, n // 25), max(8, n // 6)))
        lo = int(rng.integers(0, max(1, n - blk)))
        hi = min(n, lo + blk)
        noise = np.exp(rng.normal(0.0, 0.3, size=hi - lo))
        trial[lo:hi] = np.clip(trial[lo:hi] * noise, 0, None)
        trial = _rescale(trial)
        trial_r = R_of(trial)
        if trial_r > 0.7 * cur_r:
            trial, trial_r = _refine(trial, deadline - 0.5,
                                     rounds=3)
        if trial_r > cur_r:
            cur, cur_r = trial, trial_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif trial_r > alt_r:
            alternative, alt_r = trial.copy(), trial_r

    # Final refine on best
    if time.process_time() < deadline - 0.5:
        cand, r = _refine(best, deadline, rounds=4)
        if r > best_r:
            best, best_r = cand, r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

