        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_softmax(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat_top(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    S = Lf >= tau * mx
    nS = int(np.count_nonzero(S))
    V = 0.0
    if nS > 1:
        Ls = Lf[S]
        Lbar = Ls.mean()
        diff = Ls - Lbar
        V = float(np.sum(diff * diff)) / (mx * mx * nS)
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * diff / (mx * mx * nS)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * V
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, mode, param=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if mode == 'tie':
        fg = _fun_grad_tie
    elif mode == 'softmax':
        fg = (lambda hh: _fun_grad_softmax(hh, param))
    else:
        tau, kappa = param
        fg = (lambda hh: _fun_grad_flat_top(hh, tau, kappa))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _fracs(h):
    return (_frac_near_max(h, 1e-3), _frac_near_max(h, 1e-2),
            _frac_near_max(h, 5e-2))


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    startR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Stage A: full-resolution softmax polish (smooth max approximation) ----
    # This is the KEY new idea: use differentiable softmax in place of hard max,
    # then anneal beta -> large. This avoids the tie-gradient degeneracy.
    for beta in (30.0, 100.0, 300.0, 1000.0):
        if time.process_time() >= deadline - 4.0:
            break
        tlim = min(deadline - 3.0, time.process_time() + 4.0)
        cand = _lbfgs_block(best, np.arange(best.size), 300, tlim,
                            'softmax', beta)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
        # also a tie polish for the hard objective
        if time.process_time() < deadline - 2.5:
            cand2 = _lbfgs_block(best, np.arange(best.size), 200,
                                 min(deadline - 1.5, time.process_time() + 2.0),
                                 'tie')
            r2 = R_of(cand2)
            if r2 > bestR + 1e-15:
                best, bestR = cand2.copy(), r2
    print("after softmax: R=%.9f" % bestR)

    # ---- Stage B: coarse flat-top + prolongate ladder (multi-scale) ----
    alt_best = None
    altR = -1.0

    Q = 32
    ladder = [(0.995, 0.05), (0.99, 0.2), (0.98, 1.0),
              (0.95, 3.0), (0.90, 10.0)]

    def run_coarse_phase(cur_best, curR, time_cap):
        n = cur_best.size
        if n % Q != 0:
            return cur_best, curR, None
        qh = _coarsen(cur_best, Q)
        if qh is None:
            return cur_best, curR, None
        qh = _rescale(qh)
        best_qh = qh.copy()
        best_qR = R_of(qh)
        pre_prolong = None
        for (tau, kappa) in ladder:
            if time.process_time() >= time_cap - 2.0:
                break
            tlim = min(time_cap - 1.5, time.process_time() + 2.0)
            cand = _lbfgs_block(best_qh, np.arange(best_qh.size), 120,
                                tlim, 'flattop', (tau, kappa))
            if time.process_time() < time_cap - 1.0:
                cand = _lbfgs_block(cand, np.arange(cand.size), 120,
                                    min(time_cap - 0.8, time.process_time() + 1.0),
                                    'tie')
            r = R_of(cand)
            if r > best_qR:
                best_qh, best_qR = cand.copy(), r
            if pre_prolong is None:
                pre_prolong = cand.copy()
            ph = _prolongate(cand, Q)
            pr = R_of(ph)
            if pr > curR + 1e-15:
                cur_best, curR = ph.copy(), pr
        return cur_best, curR, pre_prolong

    if time.process_time() < deadline - 6.0:
        cap1 = min(deadline - 5.0, time.process_time() + 12.0)
        nb, nR, pre = run_coarse_phase(best, bestR, cap1)
        if nR > bestR:
            best, bestR = nb, nR
        if pre is not None:
            ph = _prolongate(pre, Q)
            if R_of(ph) > altR:
                alt_best, altR = ph, R_of(ph)

    # ---- Stage C: peak-window polish at full resolution ----
    for pad in (0.05, 0.03, 0.02):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 1.0, time.process_time() + 3.0),
                          'tie')
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    # ---- Stage D: another softmax round + coarse phase if time remains ----
    if time.process_time() < deadline - 5.0:
        for beta in (2000.0, 5000.0):
            if time.process_time() >= deadline - 3.0:
                break
            cand = _lbfgs_block(best, np.arange(best.size), 200,
                                min(deadline - 2.5, time.process_time() + 2.0),
                                'softmax', beta)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r

    if time.process_time() < deadline - 4.0:
        cap2 = deadline - 1.0
        nb, nR, pre2 = run_coarse_phase(best, bestR, cap2)
        if nR > bestR:
            best, bestR = nb, nR
        if pre2 is not None:
            ph = _prolongate(pre2, Q)
            if R_of(ph) > altR:
                alt_best, altR = ph, R_of(ph)

    # final tie polish
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 2.0),
                           'tie')
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    fa = _fracs(best)
    print("frac near max after: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % fa)
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size <= 1000000:
        result["alternative"] = alt_best
    return result

