            r2 = R_of(cand2)
            if r2 > bestR + 1e-15:
                best, bestR = cand2.copy(), r2
    print("after softmax: R=%.9f" % bestR)

    # ---- Stage B: coarse flat-top + prolongate ladder (multi-scale) ----
    alt_best = None
    altR = -1.0

    Q = 32
    ladder = [(0.995, 0.05), (0.99, 0.2), (0.98, 1.0),
              (0.95, 3.0), (0.90, 10.0)]

    def run_coarse_phase(cur_best, curR, time_cap):
        n = cur_best.size
        if n % Q != 0:
            return cur_best, curR, None
        qh = _coarsen(cur_best, Q)
        if qh is None:
            return cur_best, curR, None
        qh = _rescale(qh)
        best_qh = qh.copy()
        best_qR = R_of(qh)
        pre_prolong = None
        for (tau, kappa) in ladder:
            if time.process_time() >= time_cap - 2.0:
                break
            tlim = min(time_cap - 1.5, time.process_time() + 2.0)
            cand = _lbfgs_block(best_qh, np.arange(best_qh.size), 120,
                                tlim, 'flattop', (tau, kappa))
            if time.process_time() < time_cap - 1.0:
                cand = _lbfgs_block(cand, np.arange(cand.size), 120,
                                    min(time_cap - 0.8, time.process_time() + 1.0),
                                    'tie')
            r = R_of(cand)
            if r > best_qR:
                best_qh, best_qR = cand.copy(), r
            if pre_prolong is None:
                pre_prolong = cand.copy()
            ph = _prolongate(cand, Q)
            pr = R_of(ph)
            if pr > curR + 1e-15:
                cur_best, curR = ph.copy(), pr
        return cur_best, curR, pre_prolong

    if time.process_time() < deadline - 6.0:
        cap1 = min(deadline - 5.0, time.process_time() + 12.0)
        nb, nR, pre = run_coarse_phase(best, bestR, cap1)
        if nR > bestR:
            best, bestR = nb, nR
        if pre is not None:
            ph = _prolongate(pre, Q)
            if R_of(ph) > altR:
                alt_best, altR = ph, R_of(ph)

    # ---- Stage C: peak-window polish at full resolution ----
    for pad in (0.05, 0.03, 0.02):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 1.0, time.process_time() + 3.0),
                          'tie')
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    # ---- Stage D: another softmax round + coarse phase if time remains ----
    if time.process_time() < deadline - 5.0:
        for beta in (2000.0, 5000.0):
            if time.process_time() >= deadline - 3.0:
                break
            cand = _lbfgs_block(best, np.arange(best.size), 200,
                                min(deadline - 2.5, time.process_time() + 2.0),
                                'softmax', beta)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r

    if time.process_time() < deadline - 4.0:
        cap2 = deadline - 1.0
        nb, nR, pre2 = run_coarse_phase(best, bestR, cap2)
        if nR > bestR:
            best, bestR = nb, nR
        if pre2 is not None:
            ph = _prolongate(pre2, Q)
            if R_of(ph) > altR:
                alt_best, altR = ph, R_of(ph)

    # final tie polish
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 2.0),
                           'tie')
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    fa = _fracs(best)
    print("frac near max after: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % fa)
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size <= 1000000:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return 0.0
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate(h, Nnew):
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew)
    edges = np.linspace(0.0, N, Nnew + 1)
    m = np.interp(edges, np.arange(N + 1), c)
    newh = np.diff(m)
    return np.maximum(newh, 0.0)


def _refine(h, deadline, rounds=6):
    best = h.copy()
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.5, time.process_time() + 5.0), beta=0.0)
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        if time.process_time() < deadline - 1.0:
            for beta in (50.0, 200.0):
                if time.process_time() >= deadline - 0.6:
                    break
                pb = _lbfgs_block(best, np.arange(best.size), 200,
                                 min(deadline - 0.4, time.process_time() + 4.0),
                                 beta=beta)
                rb = R_of(pb)
                if rb > bestR:
                    best, bestR = pb, rb
        win = _peak_window(best)
        if win.size >= 4 and win.size < best.size:
            pw = _lbfgs_block(best, win, 200,
                             min(deadline - 0.3, time.process_time() + 3.0),
                             beta=0.0)
            rw = R_of(pw)
            if rw > bestR:
                best, bestR = pw, rw
    return best, bestR


def main_construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    best_h = None
    best_R = -1.0
    start_h = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_h = s.copy()
            best_h = s.copy()
            best_R = R_of(s)

    if best_h is None:
        # generic seed: symmetric-ish smooth bump
        N = 2048
        x = np.linspace(0, 1, N)
        best_h = (1.0 + np.cos(2 * np.pi * (x - 0.5))).clip(0) + 0.01
        best_R = R_of(best_h)

    # --- Stage 1: refine at current resolution ---
    h, r = _refine(best_h, min(deadline, time.process_time() + budget_seconds * 0.35))
    if r > best_R:
        best_h, best_R = h, r
    print("stage1 R=%.6f N=%d" % (best_R, best_h.size))

    # --- Stage 2: escalate resolution and re-polish ---
    Ns = [best_h.size]
    for mult in (2, 2, 2):
        Ns.append(Ns[-1] * mult)
    # cap so the final N is reasonable
    Ns = [n for n in Ns if n <= 500000]

    for Ntarget in Ns[1:]:
        if time.process_time() > deadline - 2.0:
            break
        h = _prolongate(best_h, Ntarget)
        r = R_of(h)
        if r > best_R:
            best_h, best_R = h, r
        sub_deadline = min(deadline - 1.0,
                           time.process_time() + budget_seconds * 0.20)
        h, r = _refine(best_h, sub_deadline, rounds=3)
        if r > best_R:
            best_h, best_R = h, r
        print("escalate N=%d R=%.6f" % (Ntarget, best_R))

    # --- Stage 3: last dedicated polish on best ---
    if time.process_time() < deadline - 1.0:
        h, r = _refine(best_h, deadline - 0.5, rounds=10)
        if r > best_R:
            best_h, best_R = h, r

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start_h is not None:
        rs = R_of(start_h)
        if rs >= best_R:
            return start_h
        return {"best": best_h, "alternative": start_h}
    return best_h


def construct(budget_seconds, start):
    try:
        return main_construct(budget_seconds, start)
    except Exception:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_floor(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    mask = Lf > 1e-9 * M
    gLf = np.zeros_like(Lf)
    gLf[mask] += -1.0 / Lf[mask]
    gLf[int(np.argmax(Lf))] += mask.sum() / M
    grad = _backprop(gLf, h)
    val = -np.sum(np.log(Lf[mask])) + mask.sum() * np.log(M)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False,
                 floor=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if floor:
        fg = _fun_grad_floor
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _near_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0
    return float(np.mean(Lf >= 0.99 * mx)), float(np.mean(Lf >= 0.95 * mx))


def _upsample(h, factor):
    """Linearly interpolate the step-height profile to a finer grid."""
    n = h.size
    m = int(round((n - 1) * factor)) + 1
    xp = np.arange(n, dtype=float)
    x = np.linspace(0.0, n - 1.0, m)
    return np.interp(x, xp, h)


def _exact_polish(h, deadline, bestR, best):
    win_all = np.arange(h.size)
    ht = _lbfgs_block(h, win_all, 400,
                      min(deadline, time.process_time() + 8.0), tie=True)
    r = R_of(ht)
    if r > bestR + 1e-15:
        best, bestR = ht.copy(), r
    for beta in (1e3, 1e5, 1e7):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(best, win_all, 150,
                          min(deadline, time.process_time() + 4.0), beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
    for pad in (0.15, 0.07, 0.03):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline, time.process_time() + 3.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase A: try upsampling to a finer grid, then polish ----
    # The score is a smooth function of the shape; a finer grid gives
    # L-BFGS more degrees of freedom to sharpen the peak plateau.
    if best.size < 400000 and time.process_time() < deadline - 8.0:
        for factor in (1.5, 2.0):
            if time.process_time() >= deadline - 6.0:
                break
            hs = _rescale(_upsample(best, factor))
            if hs.size > 900000:
                continue
            rs = R_of(hs)
            # polish on the upsampled grid
            hs2, rs2 = _exact_polish(
                hs, min(deadline, time.process_time() + 6.0), rs, hs)
            print("upsample x%.1f N=%d R=%.9f" % (factor, hs2.size, rs2))
            if rs2 > bestR + 1e-15:
                best, bestR = hs2.copy(), rs2
                print("upsample ACCEPT R=%.9f" % bestR)

    # ---- Phase B: exact-R polish of current best ----
    if time.process_time() < deadline - 3.0:
        best, bestR = _exact_polish(best, deadline, bestR, best)
    n01c, n1c = _near_fracs(best)
    print("polish R=%.9f near01=%.4f near1=%.4f" % (bestR, n01c, n1c))

    # ---- Phase C: jitter loop on best ----
    rng = np.random.default_rng(2024)
    rounds = 0
    acc = 0
    while time.process_time() < deadline - 1.5:
        rounds += 1
        n = best.size
        hj = best.copy()
        for _ in range(4):
            L = int(rng.integers(4, max(5, n // 8)))
            if L >= n:
                L = n
            st = int(rng.integers(0, n - L + 1))
            sig = rng.uniform(0.01, 0.03)
            hj[st:st + L] *= np.exp(rng.normal(0.0, sig, size=L))
        win = _peak_window(hj, pad_frac=0.05, extra=96)
        hj = _lbfgs_block(hj, win, 150,
                          min(deadline - 1.0, time.process_time() + 2.0),
                          tie=True)
        rj = R_of(hj)
        if rj > bestR + 1e-15:
            win2 = _peak_window(hj, pad_frac=0.02, extra=64)
            hj2 = _lbfgs_block(hj, win2, 150,
                               min(deadline - 0.8, time.process_time() + 1.5),
                               tie=True)
            rj2 = R_of(hj2)
            if rj2 > rj:
                hj, rj = hj2, rj2
            if rj > bestR + 1e-15:
                best, bestR = hj.copy(), rj
                acc += 1
                if acc % 3 == 0:
                    print("jitter round=%d acc=%d R=%.9f" % (rounds, acc, bestR))
    print("jitter done rounds=%d acc=%d R=%.9f" % (rounds, acc, bestR))

    # ---- Phase D: final exact polish ----
    if time.process_time() < deadline - 0.5:
        best, bestR = _exact_polish(best, deadline, bestR, best)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _coord_ascent(h, bestR, deadline, max_sweeps=2):
    h = h.copy()
    rng = np.random.default_rng(987654321)
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h, bestR
    for _ in range(max_sweeps):
        if time.process_time() >= deadline - 0.3:
            break
        improved = False
        k = min(nz.size, max(8, nz.size // 200))
        if k == 0:
            k = 1
        for _trial in range(6):
            if time.process_time() >= deadline - 0.3:
                break
            sel = rng.choice(nz, size=k, replace=False)
            factors = np.exp(0.01 * rng.standard_normal(k))
            h2 = h.copy()
            h2[sel] *= factors
            h2 = _rescale(h2)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                h, bestR = h2, r2
                improved = True
        if not improved:
            break
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    ri = 0
    if best_c is not None and time.process_time() < deadline - 7.0:
        rng = np.random.default_rng(12345)
        amps = [0.0015, 0.002, 0.003, 0.0015, 0.002, 0.003]
        while time.process_time() < deadline - 7.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc2 = best_c.copy()
            nz = cc2 > 0
            if nz.sum() == 0:
                break
            cc2[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc2 = _rescale(cc2)
            r0 = R_of(cc2)
            slice_deadline = min(deadline - 3.0,
                                 time.process_time() + 0.06 * budget_seconds)
            work_c2, cand_c, cand_cR, org = _half_cycle(
                cc2, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.20, 0.15])
            print("restart %d amp=%.4f R(c)=%.9f (best_c %.9f)" %
                  (ri, amp, cand_cR, best_cR))
            if cand_cR > best_cR + 1e-12:
                best_c = cand_c.copy()
                best_cR = cand_cR
                print("  ACCEPT R(c)=%.9f" % best_cR)
            h_lift = _rescale(np.repeat(cand_c, 2))
            ht = h_lift
            for beta in [1e6, 1e7]:
                if time.process_time() >= slice_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'restart_lift%d' % ri
                print("  restart lift NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    if best_c is not None:
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        if r_lift > bestR + 1e-14:
            best, bestR, origin = h_lift.copy(), r_lift, 'final_lift'
            print("final lift NEW BEST R=%.9f" % bestR)
        elif r_lift > alt_bestR:
            alt_best, alt_bestR = h_lift, r_lift
        ht = h_lift
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+full'
            print("full polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    if time.process_time() < deadline - 1.0:
        for pad in [0.12, 0.08, 0.05]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 1.5:
        ca_deadline = min(deadline - 0.8, time.process_time() + 0.10 * budget_seconds)
        h_ca, r_ca = _coord_ascent(best, bestR, ca_deadline, max_sweeps=3)
        if r_ca > bestR + 1e-13:
            ht = _lbfgs_all_pos(h_ca, 150, deadline - 0.4, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, origin + '+coord'
                print("coord polish NEW BEST R=%.9f" % bestR)
            elif r_ca > bestR + 1e-13:
                best, bestR, origin = h_ca.copy(), r_ca, origin + '+coord0'
                print("coord polish NEW BEST R=%.9f" % bestR)
            else:
                if r_ca > alt_bestR:
                    alt_best, alt_bestR = h_ca, r_ca

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("restarts=%d best_c=%.9f best_full=%.9f" % (ri, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
