    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _rolling_max(L, w):
    n = L.size
    out = L.copy()
    # simple O(N*w) is too slow for w=61 and N~1e5 -> use sliding window max via deque
    from collections import deque
    dq = deque()
    for i in range(n):
        while dq and L[dq[-1]] <= L[i]:
            dq.pop()
        dq.append(i)
        if dq[0] < i - w:
            dq.popleft()
        out[i] = L[dq[0]]
    # right side
    dq.clear()
    out2 = out.copy()
    for i in range(n - 1, -1, -1):
        while dq and L[dq[-1]] <= L[i]:
            dq.pop()
        dq.append(i)
        if dq[0] > i + w:
            dq.popleft()
        if L[dq[0]] > out2[i]:
            out2[i] = L[dq[0]]
    return out2


def _deconv_step(h0, T, lam, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    Tn = float(np.sum(T * T))
    if Tn <= 0:
        return h0
    h0n = float(np.sum(h * h))
    if h0n <= 0:
        h0n = 1.0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        Lf = _knots(hh)
        r = Lf - T
        val = float(np.sum(r * r)) / Tn + lam * float(np.sum((hh - h) ** 2)) / h0n
        gLf = 2.0 * r / Tn
        g = _backprop(gLf, hh) + 2.0 * lam * (hh - h) / h0n
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _build_envelope_target(L, w):
    T = _rolling_max(L, w)
    T = 0.5 * T + 0.5 * L
    k = 9
    ker = np.ones(k) / k
    T = np.convolve(T, ker, mode='same')
    return T


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%/5%%) before: %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 5e-2)))

    alt_best = None
    altR = -1.0

    # ---- Envelope-target deconvolution phase ----
    for w in (9, 25, 61):
        if time.process_time() >= deadline - 8.0:
            break
        L = _knots(best)
        T = _build_envelope_target(L, w)
        tlim = min(deadline - 6.0, time.process_time() + 8.0)
        hd = _deconv_step(best, T, 1e-3, 80, tlim)
        fr5 = _frac_near_max(hd, 5e-2)
        fr1 = _frac_near_max(hd, 1e-3)
        rd = R_of(hd)
        print("w=%d deconv: frac 0.1%%/5%%=%.4f/%.4f R=%.12f" % (w, fr1, fr5, rd))
        if rd > altR:
            altR = rd
            alt_best = hd.copy()
        if rd > bestR + 1e-15:
            best, bestR = hd.copy(), rd

        # tie polish
        if time.process_time() < deadline - 4.0:
            pol = _lbfgs_block(hd, np.arange(hd.size), 200,
                               min(deadline - 3.0, time.process_time() + 6.0),
                               tie=True)
            rp = R_of(pol)
            print("  tie polish R=%.12f (frac 0.1%%/5%%=%.4f/%.4f)"
                  % (rp, _frac_near_max(pol, 1e-3), _frac_near_max(pol, 5e-2)))
            if rp > altR:
                altR = rp
                alt_best = pol.copy()
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

        # peak-window polishes
        for pad in (0.05, 0.03):
            if time.process_time() >= deadline - 2.0:
                break
            win = _peak_window(hd, pad_frac=pad, extra=96)
            ht = _lbfgs_block(hd, win, 300,
                              min(deadline - 1.0, time.process_time() + 3.0), tie=True)
            r = R_of(ht)
            if r > altR:
                altR = r
                alt_best = ht.copy()
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r

    print("frac near max (0.1%%/5%%) after deconv: %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 5e-2)))

    # ---- Remaining budget: alternate tie / beta / peak-window polishes ----
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        if it % 3 == 1:
            pol = _lbfgs_block(best, np.arange(best.size), 200,
                               min(deadline - 1.0, time.process_time() + 4.0),
                               tie=True)
        elif it % 3 == 2:
            pol = _lbfgs_block(best, np.arange(best.size), 200,
                               min(deadline - 1.0, time.process_time() + 4.0),
                               beta=1e6)
        else:
            win = _peak_window(best, pad_frac=0.03, extra=96)
            pol = _lbfgs_block(best, win, 300,
                               min(deadline - 1.0, time.process_time() + 3.0),
                               tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            print("  iter %d improved R=%.12f" % (it, bestR))

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-9)))


def _stats_line(tag, h, r):
    Lf = _knots(h)
    mx = Lf.max()
    band = float(np.mean(Lf >= 0.999 * mx)) if mx > 0 else 0.0
    print("%s: N=%d R=%.8f ties=%d band01=%.2f%%" %
          (tag, h.size, r, _tie_count(h), 100.0 * band))


def _modern_schedule(h, deadline, tag=""):
    best = _rescale(np.clip(h, 0, None))
    bestR = R_of(best)
    steps = [
        (None, 250, 0.0, False),
        (0.05, 64, 1e7, False),
        (0.10, 64, 1e8, False),
        (0.25, 128, 1e8, False),
        (0.40, 256, 1e8, False),
        (None, 300, 0.0, True),
        (None, 300, 0.0, False),
    ]
    for (frac, maxiter, beta, tie) in steps:
        if time.process_time() >= deadline - 0.5:
            break
        if frac is None:
            free = np.arange(best.size)
        else:
            free = _peak_window(best, pad_frac=frac, extra=maxiter)
        ht = _lbfgs_block(best, free, maxiter=maxiter,
                          deadline=deadline - 0.5, beta=beta, tie=tie)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 16384
        i = np.arange(N, dtype=float)
        h = np.sqrt(i + 1.0) - np.sqrt(i)
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.8f (N=%d)" % (start_bestR, start_best.size))
    _stats_line("base", start_best, start_bestR)

    best = start_best.copy()
    bestR = start_bestR
    alt_cand = None
    altR = -1.0

    # Main strategy: continue optimising the given shape.
    if time.process_time() < deadline - 1.0:
        ht, rt = _modern_schedule(best, deadline - 0.5, tag="main")
        print("main polished R=%.8f" % rt)
        _stats_line("main", ht, rt)
        if rt > bestR + 1e-13:
            best, bestR = ht.copy(), rt
        else:
            alt_cand, altR = ht.copy(), rt

    # Secondary: try 2x upsampling + thinning to break discretisation, then polish.
    if time.process_time() < deadline - 2.0 and best.size * 2 <= 1000000:
        remaining = deadline - time.process_time()
        sub_deadline = time.process_time() + 0.45 * remaining
        try:
            hA = np.empty(2 * best.size, dtype=float)
            hA[0::2] = best
            hA[1::2] = best
            hA = _rescale(hA)
            rA = R_of(hA)
            print("upsample R=%.8f" % rA)
            hA2, rA2 = _modern_schedule(hA, sub_deadline, tag="up")
            print("upsample polished R=%.8f" % rA2)
            if rA2 > bestR + 1e-13:
                best, bestR = hA2.copy(), rA2
                print("upsample wins")
            elif rA2 > altR:
                alt_cand, altR = hA2.copy(), rA2
        except Exception as e:
            print("upsample failed: %s" % e)

    # Final full polish.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_block(best, np.arange(best.size), maxiter=300,
                          deadline=deadline - 0.5, beta=0.0, tie=False)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            print("final polish R=%.8f" % bestR)

    _stats_line("final", best, bestR)

    if bestR >= start_bestR - 1e-13:
        if alt_cand is not None and altR > start_bestR + 1e-13 and alt_cand.size != best.size:
            return {"best": best, "alternative": alt_cand}
        return best
    else:
        if alt_cand is not None and altR > -1.0:
            return {"best": start_best, "alternative": alt_cand}
        return start_best

