    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _to_quotient(h, Nq):
    N = h.size
    if N == Nq:
        return h.copy()
    if N % Nq == 0:
        k = N // Nq
        return h.reshape(Nq, k).mean(axis=1)
    idx = (np.arange(Nq + 1) * N) // Nq
    out = np.empty(Nq)
    for i in range(Nq):
        a, b = idx[i], max(idx[i] + 1, idx[i + 1])
        out[i] = h[a:b].mean()
    return out


# ---------- T133 experiment: top-quantile (CVaR) shoulder push ----------

def _topq_R_and_grad(c, q, kappa, S):
    """V = -R_lin + kappa*(1 - mean_S(L)/mx), S frozen set of top-q knot indices."""
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    num, dq, Lf = _num_and_dq(c)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(c.size)
    R = num / (s * s * mx)
    gLf = dq / (s * s * mx)
    # Clarke weight on max (from R denominator and from penalty)
    idx = np.flatnonzero(Lf >= (1.0 - 1e-8) * mx)
    w = 1.0 / idx.size
    # R max term
    gLf[idx] += (-num / (s * s * mx * mx)) * w
    # penalty
    if S.size > 0:
        meanS = Lf[S].mean()
        pen = kappa * (1.0 - meanS / mx)
        # d pen / d L_j for j in S: -kappa/(|S|*mx)
        gLf[S] += (-kappa / (S.size * mx))
        # d pen / d mx: +kappa*meanS/mx^2, distributed over argmax set
        gLf[idx] += (kappa * meanS / (mx * mx)) * w
    else:
        pen = 0.0
    grad = _backprop(gLf, c)
    grad += (-2.0 * num / (s * s * s * mx))
    val = -R + pen
    return val, grad


def _topq_set(c, q):
    Lf = _knots(c)
    n = Lf.size
    k = max(1, int(round(q * n)))
    if k >= n:
        return np.arange(n)
    order = np.argsort(Lf)[::-1]
    return np.sort(order[:k])


def _lbfgs_topq(c0, q, kappa, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c0
    c = np.clip(c0, 0, None)
    if c.sum() <= 0:
        return c0
    c = c / c.sum()
    S = _topq_set(c, q)
    x0 = c.copy()

    def f(x):
        cc = np.clip(x, 0.0, None)
        val, g = _topq_R_and_grad(cc, q, kappa, S)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * c.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c2 = np.clip(res.x, 0.0, None)
    s = c2.sum()
    if s <= 0:
        return c0
    return c2 / s


def _cs_lift(c, Nq, Nfull):
    if Nfull == Nq:
        return c.copy()
    xq = (np.arange(Nq) + 0.5) / Nq
    xf = (np.arange(Nfull) + 0.5) / Nfull
    h = np.interp(xf, xq, c)
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return _rescale(np.repeat(c, max(1, Nfull // Nq))[:Nfull])
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max (1%%) before: %.4f" % _frac_near_max(best, 1e-2))

    alt_best = None
    altR = -1.0

    # ---- T133: top-quantile shoulder push at quotient Nq=3281 ----
    Nq = 3281
    Nfull = best.size
    if Nfull % Nq == 0:
        c = best.reshape(Nq, Nfull // Nq).mean(axis=1)
    else:
        c = _to_quotient(best, Nq)
    c = np.clip(c, 0, None)
    if c.sum() <= 0:
        c = np.ones(Nq)
    c = c / c.sum()
    cR0 = R_of(c)
    print("quotient Nq=%d R=%.12f (ties=%d, 1%%-nm=%.4f)"
          % (Nq, cR0, _tie_count(c), _frac_near_max(c, 1e-2)))

    best_c = c.copy()
    best_cR = cR0

    qs = [0.10, 0.20]
    kappas = [0.5, 1.0, 2.0, 4.0]
    for q in qs:
        for kappa in kappas:
            if time.process_time() >= deadline - 25.0:
                break
            c = _lbfgs_topq(c, q, kappa, 150,
                            min(deadline - 22.0, time.process_time() + 6.0))
            r = R_of(c)
            fnm = _frac_near_max(c, 1e-2)
            print("  q=%.2f kappa=%.1f R=%.12f 1%%-nm=%.4f"
                  % (q, kappa, r, fnm))
            if r > best_cR + 1e-15:
                best_c = c.copy()
                best_cR = r
        if time.process_time() >= deadline - 25.0:
            break

    print("quotient best R=%.12f (was %.12f, 1%%-nm=%.4f)"
          % (best_cR, cR0, _frac_near_max(best_c, 1e-2)))

    if time.process_time() < deadline - 20.0:
        pol = _lbfgs_block(best_c, np.arange(best_c.size), 200,
                           min(deadline - 18.0, time.process_time() + 4.0), tie=True)
        rp = R_of(pol)
        if rp > best_cR + 1e-15:
            best_c, best_cR = pol, rp
            print("  quotient tie polish R=%.12f" % rp)

    # ---- cumulative-sum lift ladder ----
    stage_best = best_c.copy()
    stage_bestR = best_cR
    stage_Nq = Nq

    lift_plan = [(8192, [0.5, 1.0, 2.0], 0.10),
                 (32768, [0.3, 1.0], 0.10),
                 (Nfull, [0.3], 0.10)]

    for Nlift, kaps, q in lift_plan:
        if time.process_time() >= deadline - 8.0:
            break
        if Nlift <= stage_Nq:
            continue
        h_lift = _cs_lift(stage_best, stage_Nq, Nlift)
        h_lift = _rescale(h_lift)
        r_lift = R_of(h_lift)
        print("lift -> N=%d R=%.12f (1%%-nm=%.4f)"
              % (Nlift, r_lift, _frac_near_max(h_lift, 1e-2)))
        # top-quantile ladder at this level
        h_cur = h_lift.copy()
        r_cur = r_lift
        for kappa in kaps:
            if time.process_time() >= deadline - 6.0:
                break
            h_try = _lbfgs_topq(h_cur, q, kappa, 150,
                                min(deadline - 5.0, time.process_time() + 5.0))
            h_try = _rescale(h_try)
            r_try = R_of(h_try)
            print("  lift N=%d kappa=%.1f R=%.12f 1%%-nm=%.4f"
                  % (Nlift, kappa, r_try, _frac_near_max(h_try, 1e-2)))
            if r_try > r_cur + 1e-15:
                h_cur, r_cur = h_try, r_try
        # tie polish
        if time.process_time() < deadline - 4.0:
            pol = _lbfgs_block(h_cur, np.arange(h_cur.size), 200,
                               min(deadline - 3.0, time.process_time() + 4.0), tie=True)
            rp = R_of(pol)
            if rp > r_cur:
                h_cur, r_cur = pol, rp
                print("  tie polish N=%d R=%.12f" % (Nlift, rp))
        # peak-window polish
        if time.process_time() < deadline - 3.0:
            win = _peak_window(h_cur, pad_frac=0.05, extra=128)
            ht = _lbfgs_block(h_cur, win, 200,
                              min(deadline - 2.0, time.process_time() + 3.0), tie=True)
            r = R_of(ht)
            if r > r_cur:
                h_cur, r_cur = ht, r
                print("  peak polish N=%d R=%.12f" % (Nlift, r))
        if r_cur > stage_bestR + 1e-15 or Nlift == Nfull:
            stage_best = h_cur.copy()
            stage_bestR = r_cur
            stage_Nq = Nlift
        if r_cur > altR:
            altR = r_cur
            alt_best = h_cur.copy()

    print("lift stage best R=%.12f" % stage_bestR)

    if alt_best is not None and altR > bestR + 1e-15:
        best, bestR = alt_best.copy(), altR

    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("frac near max (1%%) after: %.4f" % _frac_near_max(best, 1e-2))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


