          % (Nq, cR0, _tie_count(c), _frac_near_max(c, 1e-2)))

    best_c = c.copy()
    best_cR = cR0

    qs = [0.10, 0.20]
    kappas = [0.5, 1.0, 2.0, 4.0]
    for q in qs:
        for kappa in kappas:
            if time.process_time() >= deadline - 25.0:
                break
            c = _lbfgs_topq(c, q, kappa, 150,
                            min(deadline - 22.0, time.process_time() + 6.0))
            r = R_of(c)
            fnm = _frac_near_max(c, 1e-2)
            print("  q=%.2f kappa=%.1f R=%.12f 1%%-nm=%.4f"
                  % (q, kappa, r, fnm))
            if r > best_cR + 1e-15:
                best_c = c.copy()
                best_cR = r
        if time.process_time() >= deadline - 25.0:
            break

    print("quotient best R=%.12f (was %.12f, 1%%-nm=%.4f)"
          % (best_cR, cR0, _frac_near_max(best_c, 1e-2)))

    if time.process_time() < deadline - 20.0:
        pol = _lbfgs_block(best_c, np.arange(best_c.size), 200,
                           min(deadline - 18.0, time.process_time() + 4.0), tie=True)
        rp = R_of(pol)
        if rp > best_cR + 1e-15:
            best_c, best_cR = pol, rp
            print("  quotient tie polish R=%.12f" % rp)

    # ---- cumulative-sum lift ladder ----
    stage_best = best_c.copy()
    stage_bestR = best_cR
    stage_Nq = Nq

    lift_plan = [(8192, [0.5, 1.0, 2.0], 0.10),
                 (32768, [0.3, 1.0], 0.10),
                 (Nfull, [0.3], 0.10)]

    for Nlift, kaps, q in lift_plan:
        if time.process_time() >= deadline - 8.0:
            break
        if Nlift <= stage_Nq:
            continue
        h_lift = _cs_lift(stage_best, stage_Nq, Nlift)
        h_lift = _rescale(h_lift)
        r_lift = R_of(h_lift)
        print("lift -> N=%d R=%.12f (1%%-nm=%.4f)"
              % (Nlift, r_lift, _frac_near_max(h_lift, 1e-2)))
        # top-quantile ladder at this level
        h_cur = h_lift.copy()
        r_cur = r_lift
        for kappa in kaps:
            if time.process_time() >= deadline - 6.0:
                break
            h_try = _lbfgs_topq(h_cur, q, kappa, 150,
                                min(deadline - 5.0, time.process_time() + 5.0))
            h_try = _rescale(h_try)
            r_try = R_of(h_try)
            print("  lift N=%d kappa=%.1f R=%.12f 1%%-nm=%.4f"
                  % (Nlift, kappa, r_try, _frac_near_max(h_try, 1e-2)))
            if r_try > r_cur + 1e-15:
                h_cur, r_cur = h_try, r_try
        # tie polish
        if time.process_time() < deadline - 4.0:
            pol = _lbfgs_block(h_cur, np.arange(h_cur.size), 200,
                               min(deadline - 3.0, time.process_time() + 4.0), tie=True)
            rp = R_of(pol)
            if rp > r_cur:
                h_cur, r_cur = pol, rp
                print("  tie polish N=%d R=%.12f" % (Nlift, rp))
        # peak-window polish
        if time.process_time() < deadline - 3.0:
            win = _peak_window(h_cur, pad_frac=0.05, extra=128)
            ht = _lbfgs_block(h_cur, win, 200,
                              min(deadline - 2.0, time.process_time() + 3.0), tie=True)
            r = R_of(ht)
            if r > r_cur:
                h_cur, r_cur = ht, r
                print("  peak polish N=%d R=%.12f" % (Nlift, r))
        if r_cur > stage_bestR + 1e-15 or Nlift == Nfull:
            stage_best = h_cur.copy()
            stage_bestR = r_cur
            stage_Nq = Nlift
        if r_cur > altR:
            altR = r_cur
            alt_best = h_cur.copy()

    print("lift stage best R=%.12f" % stage_bestR)

    if alt_best is not None and altR > bestR + 1e-15:
        best, bestR = alt_best.copy(), altR

    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("frac near max (1%%) after: %.4f" % _frac_near_max(best, 1e-2))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _to_quotient(h, Nq):
    N = h.size
    if N == Nq:
        return h.copy()
    if N % Nq == 0:
        k = N // Nq
        return h.reshape(Nq, k).mean(axis=1)
    idx = (np.arange(Nq + 1) * N) // Nq
    out = np.empty(Nq)
    for i in range(Nq):
        a, b = idx[i], max(idx[i] + 1, idx[i + 1])
        out[i] = h[a:b].mean()
    return out


# ---------- linear-form R + flat-top variance penalty ----------

def _linear_R_and_grad(c, tau, kappa):
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    num, dq, Lf = _num_and_dq(c)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(c.size)
    R = num / (s * s * mx)
    gLf = dq / (s * s * mx)
    idx = np.flatnonzero(Lf >= (1.0 - 1e-8) * mx)
    w = 1.0 / idx.size
    gLf[idx] += (-num / (s * s * mx * mx)) * w
    S = Lf >= tau * mx
    if np.any(S):
        vals = Lf[S]
        mu = vals.mean()
        var = np.mean((vals - mu) ** 2)
        nS = vals.size
        dvar_dL = np.zeros_like(Lf)
        dvar_dL[S] = (2.0 / nS) * (vals - mu)
        pen = kappa * var / (mx * mx)
        gLf += kappa * dvar_dL / (mx * mx)
        gLf[idx] += (-2.0 * kappa * var / (mx * mx * mx)) * w
    else:
        pen = 0.0
    grad = _backprop(gLf, c)
    grad += (-2.0 * num / (s * s * s * mx))
    val = -R + pen
    return val, grad


def _lbfgs_linear(c0, tau, kappa, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c0
    c = np.clip(c0, 0, None)
    if c.sum() <= 0:
        return c0
    c = c / c.sum()
    x0 = c.copy()

    def f(x):
        cc = np.clip(x, 0.0, None)
        return _linear_R_and_grad(cc, tau, kappa)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * c.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c2 = np.clip(res.x, 0.0, None)
    s = c2.sum()
    if s <= 0:
        return c0
    return c2 / s


def _cs_lift(c, Nq, Nfull):
    if Nfull == Nq:
        return c.copy()
    xq = (np.arange(Nq) + 0.5) / Nq
    xf = (np.arange(Nfull) + 0.5) / Nfull
    h = np.interp(xf, xq, c)
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return _rescale(np.repeat(c, max(1, Nfull // Nq))[:Nfull])
    return h


def _run_ladder(c, taus, kappas, maxiter, deadline, per_solve_cap):
    """Run tau x kappa ladder on c; return best (by exact R_of) and its R."""
    best_c = c.copy()
    bestR = R_of(c)
    for tau in taus:
        for kappa in kappas:
            now = time.process_time()
            if now >= deadline - 1.0:
                return best_c, bestR
            sub_deadline = min(deadline - 0.5, now + per_solve_cap)
            cc = _lbfgs_linear(best_c, tau, kappa, maxiter, sub_deadline)
            r = R_of(cc)
            if r > bestR + 1e-15:
                best_c, bestR = cc, r
    return best_c, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    Nfull = best.size
    print("base R=%.9f (N=%d)" % (bestR, Nfull))
    print("frac near max (1%%) before: %.4f" % _frac_near_max(best, 1e-2))

    # global best across all levels/cycles
    gbest = best.copy()
    gbestR = bestR
    alt_best = None
    altR = -1.0

    Nq = 3281
    # ladder configs per level
    ladder_3281 = ([0.90, 0.82, 0.72, 0.62], [3.0, 10.0, 30.0, 100.0])
    ladder_8192 = ([0.92, 0.85, 0.78], [3.0, 10.0, 30.0])
    ladder_32768 = ([0.92, 0.85], [3.0, 10.0, 30.0])
    ladder_full = ([0.95, 0.90, 0.85], [3.0, 8.0, 20.0])

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        print("=== cycle %d (t=%.1f/%.1f) ===" %
              (cycle, time.process_time() - t0, budget_seconds * 0.90))

        # (a) quotient to Nq=3281
        if time.process_time() >= deadline - 2.0:
            break
        c = _to_quotient(gbest, Nq)
        c = np.clip(c, 0, None)
        if c.sum() <= 0:
            c = np.ones(Nq)
        c = c / c.sum()
        cR0 = R_of(c)
        c, cR = _run_ladder(c, ladder_3281[0], ladder_3281[1], 200,
                            deadline, per_solve_cap=4.0)
        print("  3281: %.12f -> %.12f (1%%-nm=%.4f)"
              % (cR0, cR, _frac_near_max(c, 1e-2)))
        if cR > gbestR + 1e-15:
            gbest, gbestR = c.copy(), cR

        # (b) lift to 8192
        if time.process_time() >= deadline - 2.0:
            break
        h8 = _rescale(_cs_lift(c, Nq, 8192))
        r8_0 = R_of(h8)
        h8, r8 = _run_ladder(h8, ladder_8192[0], ladder_8192[1], 200,
                             deadline, per_solve_cap=3.0)
        print("  8192: %.12f -> %.12f (1%%-nm=%.4f)"
              % (r8_0, r8, _frac_near_max(h8, 1e-2)))
        if r8 > gbestR + 1e-15:
            gbest, gbestR = h8.copy(), r8
        if r8 > altR:
            alt_best, altR = h8.copy(), r8

        # (c) lift to 32768
        if time.process_time() >= deadline - 2.0:
            break
        h32 = _rescale(_cs_lift(h8, 8192, 32768))
        r32_0 = R_of(h32)
        h32, r32 = _run_ladder(h32, ladder_32768[0], ladder_32768[1], 200,
                               deadline, per_solve_cap=3.0)
        print("  32768: %.12f -> %.12f (1%%-nm=%.4f)"
              % (r32_0, r32, _frac_near_max(h32, 1e-2)))
        if r32 > gbestR + 1e-15:
            gbest, gbestR = h32.copy(), r32
        if r32 > altR:
            alt_best, altR = h32.copy(), r32

        # (d) lift to Nfull (104992)
        if time.process_time() >= deadline - 2.0:
            break
        hf = _rescale(_cs_lift(h32, 32768, Nfull))
        rf_0 = R_of(hf)
        hf, rf = _run_ladder(hf, ladder_full[0], ladder_full[1], 200,
                             deadline, per_solve_cap=2.5)
        print("  %d: %.12f -> %.12f (1%%-nm=%.4f)"
              % (Nfull, rf_0, rf, _frac_near_max(hf, 1e-2)))

        # exact-R tie polish at full
        if time.process_time() < deadline - 1.5:
            pol = _lbfgs_block(hf, np.arange(hf.size), 200,
                               min(deadline - 1.0, time.process_time() + 2.5),
                               tie=True)
            rp = R_of(pol)
            if rp > rf:
                hf, rf = pol, rp
                print("    tie polish %d: %.12f" % (Nfull, rf))
        # peak-window polish
        if time.process_time() < deadline - 1.0:
            win = _peak_window(hf, pad_frac=0.05, extra=128)
            ht = _lbfgs_block(hf, win, 200,
                              min(deadline - 0.5, time.process_time() + 2.0),
                              tie=True)
            r = R_of(ht)
            if r > rf:
                hf, rf = ht, r
                print("    peak polish %d: %.12f" % (Nfull, rf))

        print("  full best: %.12f (1%%-nm=%.4f, 5%%-nm=%.4f)"
              % (rf, _frac_near_max(hf, 1e-2), _frac_near_max(hf, 5e-2)))
        if rf > gbestR + 1e-15:
            gbest, gbestR = hf.copy(), rf
        if rf > altR:
            alt_best, altR = hf.copy(), rf

    # final safety: base tie polish on gbest
    if time.process_time() < deadline - 0.5:
        pol = _lbfgs_block(gbest, np.arange(gbest.size), 200,
                           min(deadline - 0.2, time.process_time() + 2.0),
                           tie=True)
        rp = R_of(pol)
        if rp > gbestR + 1e-15:
            gbest, gbestR = pol, rp

    if gbestR < startR:
        gbest = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        gbestR = startR

    print("frac near max (1%%) after: %.4f" % _frac_near_max(gbest, 1e-2))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (gbestR, startR, gbest.size, _tie_count(gbest)))

    result = {"best": gbest}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _to_quotient(h, Nq):
    N = h.size
    if N == Nq:
        return h.copy()
    if N % Nq == 0:
        k = N // Nq
        return h.reshape(Nq, k).mean(axis=1)
    idx = (np.arange(Nq + 1) * N) // Nq
    out = np.empty(Nq)
    for i in range(Nq):
        a, b = idx[i], max(idx[i] + 1, idx[i + 1])
        out[i] = h[a:b].mean()
    return out


# ---------- linear-form R + flat-top variance penalty ----------

def _linear_R_and_grad(c, tau, kappa):
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    num, dq, Lf = _num_and_dq(c)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(c.size)
    R = num / (s * s * mx)
    gLf = dq / (s * s * mx)
    idx = np.flatnonzero(Lf >= (1.0 - 1e-8) * mx)
    w = 1.0 / idx.size
    gLf[idx] += (-num / (s * s * mx * mx)) * w
    S = Lf >= tau * mx
    if np.any(S):
        vals = Lf[S]
        mu = vals.mean()
        var = np.mean((vals - mu) ** 2)
        nS = vals.size
        dvar_dL = np.zeros_like(Lf)
        dvar_dL[S] = (2.0 / nS) * (vals - mu)
        pen = kappa * var / (mx * mx)
        gLf += kappa * dvar_dL / (mx * mx)
        gLf[idx] += (-2.0 * kappa * var / (mx * mx * mx)) * w
    else:
        pen = 0.0
    grad = _backprop(gLf, c)
    grad += (-2.0 * num / (s * s * s * mx))
    val = -R + pen
    return val, grad


def _lbfgs_linear(c0, tau, kappa, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c0
    c = np.clip(c0, 0, None)
    if c.sum() <= 0:
        return c0
    c = c / c.sum()
    x0 = c.copy()

    def f(x):
        cc = np.clip(x, 0.0, None)
        return _linear_R_and_grad(cc, tau, kappa)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * c.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c2 = np.clip(res.x, 0.0, None)
    s = c2.sum()
    if s <= 0:
        return c0
    return c2 / s


def _cs_lift(c, Nq, Nfull):
    if Nfull == Nq:
        return c.copy()
    xq = (np.arange(Nq) + 0.5) / Nq
    xf = (np.arange(Nfull) + 0.5) / Nfull
    h = np.interp(xf, xq, c)
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return _rescale(np.repeat(c, max(1, Nfull // Nq))[:Nfull])
    return h


def _run_ladder(c, taus, kappas, maxiter, deadline, per_solve_cap):
    """Run tau x kappa ladder on c; return best (by exact R_of) and its R."""
    best_c = c.copy()
    bestR = R_of(c)
    for tau in taus:
        for kappa in kappas:
            now = time.process_time()
            if now >= deadline - 1.0:
                return best_c, bestR
            sub_deadline = min(deadline - 0.5, now + per_solve_cap)
            cc = _lbfgs_linear(best_c, tau, kappa, maxiter, sub_deadline)
            r = R_of(cc)
            if r > bestR + 1e-15:
                best_c, bestR = cc, r
    return best_c, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    Nfull = best.size
    print("base R=%.9f (N=%d)" % (bestR, Nfull))
    print("frac near max (1%%) before: %.4f" % _frac_near_max(best, 1e-2))

    # global best across all levels/cycles
    gbest = best.copy()
    gbestR = bestR
    alt_best = None
    altR = -1.0

    Nq = 3281
    # ladder configs per level
    ladder_3281 = ([0.90, 0.82, 0.72, 0.62], [3.0, 10.0, 30.0, 100.0])
    ladder_8192 = ([0.92, 0.85, 0.78], [3.0, 10.0, 30.0])
    ladder_32768 = ([0.92, 0.85], [3.0, 10.0, 30.0])
    ladder_full = ([0.95, 0.90, 0.85], [3.0, 8.0, 20.0])

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        print("=== cycle %d (t=%.1f/%.1f) ===" %
              (cycle, time.process_time() - t0, budget_seconds * 0.90))

        # (a) quotient to Nq=3281
        if time.process_time() >= deadline - 2.0:
            break
        c = _to_quotient(gbest, Nq)
        c = np.clip(c, 0, None)
        if c.sum() <= 0:
            c = np.ones(Nq)
        c = c / c.sum()
        cR0 = R_of(c)
        c, cR = _run_ladder(c, ladder_3281[0], ladder_3281[1], 200,
                            deadline, per_solve_cap=4.0)
        print("  3281: %.12f -> %.12f (1%%-nm=%.4f)"
              % (cR0, cR, _frac_near_max(c, 1e-2)))
        if cR > gbestR + 1e-15:
            gbest, gbestR = c.copy(), cR

        # (b) lift to 8192
        if time.process_time() >= deadline - 2.0:
            break
        h8 = _rescale(_cs_lift(c, Nq, 8192))
        r8_0 = R_of(h8)
        h8, r8 = _run_ladder(h8, ladder_8192[0], ladder_8192[1], 200,
                             deadline, per_solve_cap=3.0)
        print("  8192: %.12f -> %.12f (1%%-nm=%.4f)"
              % (r8_0, r8, _frac_near_max(h8, 1e-2)))
        if r8 > gbestR + 1e-15:
            gbest, gbestR = h8.copy(), r8
        if r8 > altR:
            alt_best, altR = h8.copy(), r8

        # (c) lift to 32768
        if time.process_time() >= deadline - 2.0:
            break
        h32 = _rescale(_cs_lift(h8, 8192, 32768))
        r32_0 = R_of(h32)
        h32, r32 = _run_ladder(h32, ladder_32768[0], ladder_32768[1], 200,
                               deadline, per_solve_cap=3.0)
        print("  32768: %.12f -> %.12f (1%%-nm=%.4f)"
              % (r32_0, r32, _frac_near_max(h32, 1e-2)))
        if r32 > gbestR + 1e-15:
            gbest, gbestR = h32.copy(), r32
        if r32 > altR:
            alt_best, altR = h32.copy(), r32

        # (d) lift to Nfull (104992)
        if time.process_time() >= deadline - 2.0:
            break
        hf = _rescale(_cs_lift(h32, 32768, Nfull))
        rf_0 = R_of(hf)
        hf, rf = _run_ladder(hf, ladder_full[0], ladder_full[1], 200,
                             deadline, per_solve_cap=2.5)
        print("  %d: %.12f -> %.12f (1%%-nm=%.4f)"
              % (Nfull, rf_0, rf, _frac_near_max(hf, 1e-2)))

        # exact-R tie polish at full
        if time.process_time() < deadline - 1.5:
            pol = _lbfgs_block(hf, np.arange(hf.size), 200,
                               min(deadline - 1.0, time.process_time() + 2.5),
                               tie=True)
            rp = R_of(pol)
            if rp > rf:
                hf, rf = pol, rp
                print("    tie polish %d: %.12f" % (Nfull, rf))
        # peak-window polish
        if time.process_time() < deadline - 1.0:
            win = _peak_window(hf, pad_frac=0.05, extra=128)
            ht = _lbfgs_block(hf, win, 200,
                              min(deadline - 0.5, time.process_time() + 2.0),
                              tie=True)
            r = R_of(ht)
            if r > rf:
                hf, rf = ht, r
                print("    peak polish %d: %.12f" % (Nfull, rf))

        print("  full best: %.12f (1%%-nm=%.4f, 5%%-nm=%.4f)"
              % (rf, _frac_near_max(hf, 1e-2), _frac_near_max(hf, 5e-2)))
        if rf > gbestR + 1e-15:
            gbest, gbestR = hf.copy(), rf
        if rf > altR:
            alt_best, altR = hf.copy(), rf

    # final safety: base tie polish on gbest
    if time.process_time() < deadline - 0.5:
        pol = _lbfgs_block(gbest, np.arange(gbest.size), 200,
                           min(deadline - 0.2, time.process_time() + 2.0),
                           tie=True)
        rp = R_of(pol)
        if rp > gbestR + 1e-15:
            gbest, gbestR = pol, rp

    if gbestR < startR:
        gbest = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        gbestR = startR

    print("frac near max (1%%) after: %.4f" % _frac_near_max(gbest, 1e-2))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (gbestR, startR, gbest.size, _tie_count(gbest)))

    result = {"best": gbest}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


# ---------- level-set (flatness) reformulation ----------
# Maximize sum L^2 / ((sum h)^2 * max L).  The key idea: push more knots
# INTO the peak plateau.  We use a "soft flatness" objective that rewards
# making many knots nearly equal to the max, which both raises ||L||_2^2
# (denominator max fixed) and reshapes the peak.  Concretely we maximise
#   Q_beta(h) = sum_j w_j L_j^2 / (sum h)^2,  with w_j = exp(beta (L_j - mx))
# normalised -- i.e. favour raising the mass of L near the top.

def _fun_grad_flat(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    # smooth surrogate for sum w L^2 (peaks-heavy second moment)
    num = float(np.sum(w * Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    dL = 2.0 * w * Lf
    gLf = -dL / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _lbfgs_flat(h0, free, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_flat(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # ---- Phase F: flatness-driven block polish across many betas ----
    # The plateau of f*f is where gains come from.  Iteratively raise the
    # second moment of L weighted toward the top, over shrinking windows.
    flat_end = t0 + budget_seconds * 0.55
    betas = [200.0, 800.0, 3000.0, 1e4, 3e4]
    cyc = 0
    while time.process_time() < flat_end - 2.0:
        cyc += 1
        moved = False
        for beta in betas:
            if time.process_time() >= flat_end - 1.5:
                break
            for pad in (0.20, 0.10, 0.05, 0.03):
                if time.process_time() >= flat_end - 1.0:
                    break
                win = _peak_window(best, pad_frac=pad, extra=128)
                ht = _lbfgs_flat(best, win, 250,
                                 min(flat_end - 0.5,
                                     time.process_time() + 3.0), beta)
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r
                    moved = True
        f01, f1, f5 = _nearmax_fracs(best)
        print("flat cyc=%d R=%.9f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (cyc, bestR, f01, f1, f5))
        if not moved and cyc > 1:
            break

    # ---- Phase T: tie-based exact polish (all near-max knots equalised) ----
    tie_end = t0 + budget_seconds * 0.75
    cyc = 0
    while time.process_time() < tie_end - 2.0:
        cyc += 1
        prevR = bestR
        for pad in (0.10, 0.05, 0.03, 0.02):
            if time.process_time() >= tie_end - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=96)
            ht = _lbfgs_block(best, win, 250,
                              min(tie_end - 0.5,
                                  time.process_time() + 3.0), tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        f01, f1, f5 = _nearmax_fracs(best)
        print("tie cyc=%d R=%.9f ties=%d near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (cyc, bestR, _tie_count(best), f01, f1, f5))
        if bestR <= prevR + 1e-16 and cyc > 1:
            break

    # ---- Phase B: band polish (targeted at each L-value band) ----
    band_end = t0 + budget_seconds * 0.88
    band_edges = [(0.0, 0.05), (0.05, 0.20), (0.20, 0.50),
                  (0.50, 0.80), (0.80, 0.95), (0.95, 1.001)]
    cyc = 0
    while time.process_time() < band_end - 2.0:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        order = rng.permutation(len(band_edges))
        gains = []
        for bi in order:
            if time.process_time() >= band_end - 1.5:
                break
            lo, hi = band_edges[bi]
            sel = np.flatnonzero((best > 0) & (v >= lo * M) & (v < hi * M))
            if sel.size == 0:
                gains.append(0.0)
                continue
            mask = np.zeros(n, dtype=bool)
            mask[sel] = True
            out = mask.copy()
            for d in range(1, 17):
                out[d:] |= mask[:-d]
                out[:-d] |= mask[d:]
            active = np.flatnonzero(out)
            if active.size < 20 or active.size > 0.8 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 300,
                              min(band_end - 1.0,
                                  time.process_time() + 5.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
        f01, f1, f5 = _nearmax_fracs(best)
        print("band cyc=%d R=%.9f gains=%s near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (cyc, bestR,
                 " ".join("%.1e" % g for g in gains), f01, f1, f5))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase C: final full-vector polish ----
    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 2.0:
        h_t = _lbfgs_flat(best, np.arange(best.size), 400, fd - 1.0, 1e4)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL flat ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_block(best, np.arange(best.size), 300, fd - 0.3, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- piecewise-linear machinery ----------------
MF = 104992
M = 3281


def _sample_pl(v, Mf):
    # v on M uniform knots x_i = i/(M-1), sample on Mf uniform points
    Mv = v.size
    xv = np.linspace(0.0, 1.0, Mv)
    xf = np.linspace(0.0, 1.0, Mf)
    return np.interp(xf, xv, v)


def _pl_obj_grad(v, beta, Mf):
    Mv = v.size
    fine = _sample_pl(v, Mf)
    dx = 1.0 / (Mf - 1)
    F = fftconvolve(fine, fine) * dx
    mass = dx * fine.sum()
    if mass <= 0:
        return 1e18, np.zeros(Mv)
    L2sq = dx * np.sum(F * F)
    if L2sq <= 0:
        return 1e18, np.zeros(Mv)
    Linf = F.max()
    if Linf <= 0:
        return 1e18, np.zeros(Mv)
    # softmax max surrogate
    e = np.exp(np.clip(beta * (F - Linf), -60.0, 60.0))
    Z = e.sum()
    sm = Linf + np.log(Z) / beta
    gF = 2.0 * F * dx / L2sq - (e / Z) / sm
    # backprop through conv: F = conv(fine,fine)*dx
    gfine = 2.0 * dx * fftconvolve(gF, fine[::-1], mode='valid')[:Mf]
    # mass term: d/d fine of -2 log(mass) = -2*dx/mass
    gfine += -2.0 * dx / mass
    # adjoint of linear interpolation: distribute gfine to vertices
    xv = np.linspace(0.0, 1.0, Mv)
    xf = np.linspace(0.0, 1.0, Mf)
    idx = np.clip(np.searchsorted(xv, xf) - 1, 0, Mv - 2)
    x0 = xv[idx]; x1 = xv[idx + 1]
    t = (xf - x0) / (x1 - x0)
    gv = np.zeros(Mv)
    np.add.at(gv, idx, gfine * (1.0 - t))
    np.add.at(gv, idx + 1, gfine * t)
    val = np.log(L2sq) - 2.0 * np.log(mass) - np.log(sm)
    return val, gv


def _pl_optimize(v0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return v0
    v = np.clip(v0, 0, None)
    if v.sum() <= 0:
        return v0

    def f(x):
        return _pl_obj_grad(np.clip(x, 0.0, None), beta, MF)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, v.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * v.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return v0
    if res is None:
        return v0
    return np.clip(res.x, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%) before: %.4f" % _frac_near_max(best, 1e-3))

    # ---- D2 flip: piecewise-linear representation ----
    alt_best = None
    altR = -1.0

    # initialise v from start's quotient h[0::32]
    if best.size >= M:
        stride = best.size // M
        if stride < 1:
            stride = 1
        v0 = best[0::stride][:M].copy()
        if v0.size < M:
            v0 = np.interp(np.linspace(0, 1, M),
                           np.linspace(0, 1, v0.size), v0)
    else:
        v0 = np.interp(np.linspace(0, 1, M),
                       np.linspace(0, 1, best.size), best)
    v0 = np.clip(v0, 0, None)
    if v0.sum() <= 0:
        v0 = np.ones(M)

    v = v0.copy()
    betas = [1e3, 1e4, 1e5, 1e6]
    for beta in betas:
        if time.process_time() >= deadline - 12.0:
            break
        tlim = min(deadline - 10.0, time.process_time() + 8.0)
        v = _pl_optimize(v, beta, 200, tlim)
        fine = _sample_pl(v, MF)
        hf = _rescale(fine)
        r = R_of(hf)
        print("beta=%.0e R=%.9f near(0.1/1/5%%)=%.4f/%.4f/%.4f"
              % (beta, r, _frac_near_max(hf, 1e-3),
                 _frac_near_max(hf, 1e-2), _frac_near_max(hf, 5e-2)))
        if r > altR:
            altR = r
            alt_best = hf.copy()
        if r > bestR + 1e-15:
            best, bestR = hf.copy(), r

    # ---- polish the piecewise-linear result with exact-R tie polish ----
    if alt_best is not None and time.process_time() < deadline - 6.0:
        pol = _lbfgs_block(alt_best, np.arange(alt_best.size), 200,
                           min(deadline - 4.0, time.process_time() + 5.0),
                           tie=True)
        rp = R_of(pol)
        print("  polish R=%.12f near(0.1/1/5%%)=%.4f/%.4f/%.4f"
              % (rp, _frac_near_max(pol, 1e-3),
                 _frac_near_max(pol, 1e-2), _frac_near_max(pol, 5e-2)))
        if rp > altR:
            altR = rp
            alt_best = pol.copy()
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    # ---- peak-window polish ----
    if alt_best is not None and time.process_time() < deadline - 3.0:
        win = _peak_window(alt_best, pad_frac=0.05, extra=96)
        ht = _lbfgs_block(alt_best, win, 300,
                          min(deadline - 1.5, time.process_time() + 3.0),
                          tie=True)
        r = R_of(ht)
        print("  peak polish R=%.12f" % r)
        if r > altR:
            altR = r
            alt_best = ht.copy()
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    print("frac near max (0.1%%) after: %.4f" % _frac_near_max(best, 1e-3))

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

