    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _lift_noncomm(h, num, den):
    """Resample h to length ceil(N*num/den) via cumulative-mass linear
    interpolation at non-commensurate positions i*den/num."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N == 0 or h.sum() <= 0:
        return h.copy()
    M = int(np.ceil(N * num / den))
    if M < 1:
        M = 1
    cs = np.concatenate(([0.0], np.cumsum(h)))
    cs /= cs[-1]
    # positions in [0, N] at i*den/num for i=0..M
    pos = np.arange(M + 1, dtype=float) * (den / num)
    pos = np.clip(pos, 0.0, N)
    vals = np.interp(pos, np.arange(N + 1, dtype=float), cs)
    hp = np.diff(vals)
    hp = np.clip(hp, 0, None)
    s = hp.sum()
    if s > 0:
        hp = hp / s * h.sum()
    return hp


def _map_back(hp, N):
    """Map hp back to length N via cumulative-mass interpolation."""
    hp = np.clip(np.asarray(hp, dtype=float), 0, None)
    M = hp.size
    if M == 0:
        return np.zeros(N)
    cs = np.concatenate(([0.0], np.cumsum(hp)))
    if cs[-1] <= 0:
        return np.zeros(N)
    cs /= cs[-1]
    pos = np.arange(N + 1, dtype=float) * (M / N)
    pos = np.clip(pos, 0.0, M)
    vals = np.interp(pos, np.arange(M + 1, dtype=float), cs)
    h = np.diff(vals)
    h = np.clip(h, 0, None)
    s = h.sum()
    if s > 0:
        h = h / s * hp.sum()
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N0 = best.size
    print("base R=%.12f (N=%d)" % (bestR, N0))
    print("frac near max (0.1%%/1%%/5%%) before: %.4f / %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    alt_best = None
    altR = -1.0

    def try_update(hcand, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hcand)
        fr1 = _frac_near_max(hcand, 1e-2)
        print("  %s: R=%.12f (1%% near max=%.4f)" % (tag, r, fr1))
        if r > altR:
            altR = r
            alt_best = hcand.copy()
        if r > bestR + 1e-15:
            best, bestR = hcand.copy(), r
            return True
        return False

    # ---- Experiment: non-commensurate lifts (5:4, 7:6) then map back ----
    ratios = [(5, 4), (7, 6)]
    for (num, den) in ratios:
        if time.process_time() >= deadline - 6.0:
            break
        hp = _lift_noncomm(best, num, den)
        if hp.size < 2:
            continue
        tlim = min(deadline - 4.0, time.process_time() + 8.0)
        hp2 = _lbfgs_block(hp, np.arange(hp.size), 150, tlim, tie=True)
        rp = R_of(hp2)
        print("lift %d:%d N=%d -> polish R=%.12f" % (num, den, hp.size, rp))
        hb = _map_back(hp2, N0)
        hb = _rescale(hb)
        try_update(hb, "back-map %d:%d" % (num, den))

    # ---- Alternating cycles: lift 5:4, polish, map back, tie polish ----
    cycle = 0
    while time.process_time() < deadline - 4.0:
        cycle += 1
        if cycle > 20:
            break
        num, den = 5, 4
        if cycle % 2 == 0:
            num, den = 7, 6
        hp = _lift_noncomm(best, num, den)
        if hp.size < 2:
            break
        tlim = min(deadline - 3.0, time.process_time() + 5.0)
        if tlim <= time.process_time() + 0.5:
            break
        hp2 = _lbfgs_block(hp, np.arange(hp.size), 120, tlim, tie=True)
        hb = _rescale(_map_back(hp2, N0))
        improved = try_update(hb, "cycle %d back-map %d:%d" % (cycle, num, den))
        if time.process_time() < deadline - 2.0:
            tlim2 = min(deadline - 1.5, time.process_time() + 3.0)
            if tlim2 > time.process_time() + 0.5:
                pol = _lbfgs_block(best, np.arange(best.size), 100, tlim2, tie=True)
                try_update(pol, "cycle %d tie polish" % cycle)

    print("frac near max (0.1%%/1%%/5%%) after: %.4f / %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    # ---- Safety net ----
    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None and alt_best is not None:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _to_quotient(h, Nq):
    N = h.size
    if N == Nq:
        return h.copy()
    if N % Nq == 0:
        k = N // Nq
        return h.reshape(Nq, k).mean(axis=1)
    idx = (np.arange(Nq + 1) * N) // Nq
    out = np.empty(Nq)
    for i in range(Nq):
        a, b = idx[i], max(idx[i] + 1, idx[i + 1])
        out[i] = h[a:b].mean()
    return out


def _linear_R_and_grad(c, tau, kappa):
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    num, dq, Lf = _num_and_dq(c)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(c.size)
    R = num / (s * s * mx)
    gLf = dq / (s * s * mx)
    idx = np.flatnonzero(Lf >= (1.0 - 1e-8) * mx)
    w = 1.0 / idx.size
    gLf[idx] += (-num / (s * s * mx * mx)) * w
    S = Lf >= tau * mx
    if np.any(S):
        vals = Lf[S]
        mu = vals.mean()
        var = np.mean((vals - mu) ** 2)
        nS = vals.size
        dvar_dL = np.zeros_like(Lf)
        dvar_dL[S] = (2.0 / nS) * (vals - mu)
        pen = kappa * var / (mx * mx)
        gLf += kappa * dvar_dL / (mx * mx)
        gLf[idx] += (-2.0 * kappa * var / (mx * mx * mx)) * w
    else:
        pen = 0.0
    grad = _backprop(gLf, c)
    grad += (-2.0 * num / (s * s * s * mx))
    val = -R + pen
    return val, grad


def _lbfgs_linear(c0, tau, kappa, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c0
    c = np.clip(c0, 0, None)
    if c.sum() <= 0:
        return c0
    c = c / c.sum()
    x0 = c.copy()

    def f(x):
        cc = np.clip(x, 0.0, None)
        val, g = _linear_R_and_grad(cc, tau, kappa)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * c.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c2 = np.clip(res.x, 0.0, None)
    s = c2.sum()
    if s <= 0:
        return c0
    return c2 / s


def _cs_lift(c, Nq, Nfull):
    if Nfull == Nq:
        return c.copy()
    xq = (np.arange(Nq) + 0.5) / Nq
    xf = (np.arange(Nfull) + 0.5) / Nfull
    h = np.interp(xf, xq, c)
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return _rescale(np.repeat(c, max(1, Nfull // Nq))[:Nfull])
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    ladder_deadline = t0 + budget_seconds * 0.65

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max 0.1/1/5%% before: %.4f %.4f %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    alt_best = None
    altR = -1.0

    # ---- T131 D8 at coarse quotient Nq=821 (block-mean 128) ----
    Nfull = best.size
    Nq = 821
    k = max(1, Nfull // Nq)
    if Nfull % Nq == 0:
        c = best.reshape(Nq, k).mean(axis=1)
    else:
        c = _to_quotient(best, Nq)
    c = np.clip(c, 0, None)
    if c.sum() <= 0:
        c = np.ones(Nq)
    c = c / c.sum()
    cR0 = R_of(c)
    print("quotient Nq=%d (k=%d) R=%.12f (ties=%d, nm 0.1/1/5%%=%.4f/%.4f/%.4f)"
          % (Nq, k, cR0, _tie_count(c),
             _frac_near_max(c, 1e-3), _frac_near_max(c, 1e-2),
             _frac_near_max(c, 5e-2)))

    best_c = c.copy()
    best_cR = cR0

    taus = [0.95, 0.90, 0.80, 0.70, 0.60]
    kappas = [3.0, 10.0, 30.0, 100.0]

    cycle = 0
    while time.process_time() < ladder_deadline - 1.0:
        cycle += 1
        improved = False
        for tau in taus:
            for kappa in kappas:
                if time.process_time() >= ladder_deadline - 0.5:
                    break
                c = _lbfgs_linear(c, tau, kappa, 250,
                                  min(ladder_deadline - 0.3,
                                      time.process_time() + 4.0))
                r = R_of(c)
                if r > best_cR + 1e-15:
                    best_c = c.copy()
                    best_cR = r
                    improved = True
            if time.process_time() >= ladder_deadline - 0.5:
                break
        print("cycle %d: quotient R=%.12f (nm 0.1/1/5%%=%.4f/%.4f/%.4f)"
              % (cycle, best_cR,
                 _frac_near_max(best_c, 1e-3), _frac_near_max(best_c, 1e-2),
                 _frac_near_max(best_c, 5e-2)))
        if not improved:
            break

    print("quotient best R=%.12f (was %.12f, nm 0.1/1/5%%=%.4f/%.4f/%.4f)"
          % (best_cR, cR0,
             _frac_near_max(best_c, 1e-3), _frac_near_max(best_c, 1e-2),
             _frac_near_max(best_c, 5e-2)))

    # exact-R tie polish at quotient
    if time.process_time() < deadline - 20.0:
        pol = _lbfgs_block(best_c, np.arange(best_c.size), 200,
                           min(deadline - 18.0, time.process_time() + 4.0), tie=True)
        rp = R_of(pol)
        if rp > best_cR + 1e-15:
            best_c, best_cR = pol, rp
            print("  quotient tie polish R=%.12f" % rp)

    # ---- lift ladder ----
    stage_best = best_c.copy()
    stage_bestR = best_cR
    stage_Nq = Nq

    for Nlift in (3281, 8192, 32768, 104992):
        if time.process_time() >= deadline - 8.0:
            break
        if Nlift <= stage_Nq:
            continue
        h_lift = _cs_lift(stage_best, stage_Nq, Nlift)
        h_lift = _rescale(h_lift)
        r_lift = R_of(h_lift)
        print("lift -> N=%d R=%.12f (nm 0.1/1/5%%=%.4f/%.4f/%.4f)"
              % (Nlift, r_lift,
                 _frac_near_max(h_lift, 1e-3), _frac_near_max(h_lift, 1e-2),
                 _frac_near_max(h_lift, 5e-2)))
        # tie polish
        if time.process_time() < deadline - 6.0:
            pol = _lbfgs_block(h_lift, np.arange(h_lift.size), 150,
                               min(deadline - 5.0, time.process_time() + 5.0), tie=True)
            rp = R_of(pol)
            if rp > r_lift:
                h_lift, r_lift = pol, rp
                print("  tie polish N=%d R=%.12f" % (Nlift, rp))
        # peak-window polish pad 0.05 then 0.03
        for pad in (0.05, 0.03):
            if time.process_time() < deadline - 4.0:
                win = _peak_window(h_lift, pad_frac=pad, extra=128)
                ht = _lbfgs_block(h_lift, win, 150,
                                  min(deadline - 3.0, time.process_time() + 3.0), tie=True)
                r = R_of(ht)
                if r > r_lift:
                    h_lift, r_lift = ht, r
                    print("  peak polish pad=%.2f N=%d R=%.12f" % (pad, Nlift, r))
        # re-flatten at 3281 only
        if Nlift == 3281 and time.process_time() < deadline - 5.0:
            c2 = h_lift.copy()
            c2 = c2 / c2.sum()
            c2 = _lbfgs_linear(c2, 0.85, 30.0, 200,
                               min(deadline - 4.0, time.process_time() + 3.0))
            r2 = R_of(c2)
            if r2 > r_lift:
                h_lift, r_lift = c2, r2
                print("  re-flatten 3281 R=%.12f" % r2)
        if r_lift > stage_bestR + 1e-15 or Nlift == 104992:
            stage_best = h_lift.copy()
            stage_bestR = r_lift
            stage_Nq = Nlift
        if r_lift > altR:
            altR = r_lift
            alt_best = h_lift.copy()

    print("lift stage best R=%.12f (N=%d)" % (stage_bestR, stage_best.size))

    if alt_best is not None and altR > bestR + 1e-15:
        best, bestR = alt_best.copy(), altR

    # final full tie polish until deadline-2s
    if time.process_time() < deadline - 2.0:
        pol = _lbfgs_block(best, np.arange(best.size), 400,
                           deadline - 1.5, tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            print("final tie polish R=%.12f" % rp)

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("frac near max 0.1/1/5%% after: %.4f %.4f %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _to_quotient(h, Nq):
    N = h.size
    if N == Nq:
        return h.copy()
    if N % Nq == 0:
        k = N // Nq
        return h.reshape(Nq, k).mean(axis=1)
    idx = (np.arange(Nq + 1) * N) // Nq
    out = np.empty(Nq)
    for i in range(Nq):
        a, b = idx[i], max(idx[i] + 1, idx[i + 1])
        out[i] = h[a:b].mean()
    return out


def _linear_R_and_grad(c, tau, kappa):
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    num, dq, Lf = _num_and_dq(c)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(c.size)
    R = num / (s * s * mx)
    gLf = dq / (s * s * mx)
    idx = np.flatnonzero(Lf >= (1.0 - 1e-8) * mx)
    w = 1.0 / idx.size
    gLf[idx] += (-num / (s * s * mx * mx)) * w
    S = Lf >= tau * mx
    if np.any(S):
        vals = Lf[S]
        mu = vals.mean()
        var = np.mean((vals - mu) ** 2)
        nS = vals.size
        dvar_dL = np.zeros_like(Lf)
        dvar_dL[S] = (2.0 / nS) * (vals - mu)
        pen = kappa * var / (mx * mx)
        gLf += kappa * dvar_dL / (mx * mx)
        gLf[idx] += (-2.0 * kappa * var / (mx * mx * mx)) * w
    else:
        pen = 0.0
    grad = _backprop(gLf, c)
    grad += (-2.0 * num / (s * s * s * mx))
    val = -R + pen
    return val, grad


def _lbfgs_linear(c0, tau, kappa, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c0
    c = np.clip(c0, 0, None)
    if c.sum() <= 0:
        return c0
    c = c / c.sum()
    x0 = c.copy()

    def f(x):
        cc = np.clip(x, 0.0, None)
        val, g = _linear_R_and_grad(cc, tau, kappa)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * c.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c2 = np.clip(res.x, 0.0, None)
    s = c2.sum()
    if s <= 0:
        return c0
    return c2 / s


def _cs_lift(c, Nq, Nfull):
    if Nfull == Nq:
        return c.copy()
    xq = (np.arange(Nq) + 0.5) / Nq
    xf = (np.arange(Nfull) + 0.5) / Nfull
    h = np.interp(xf, xq, c)
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return _rescale(np.repeat(c, max(1, Nfull // Nq))[:Nfull])
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    ladder_deadline = t0 + budget_seconds * 0.65

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max 0.1/1/5%% before: %.4f %.4f %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    alt_best = None
    altR = -1.0

    # ---- T131 D8 at coarse quotient Nq=821 (block-mean 128) ----
    Nfull = best.size
    Nq = 821
    k = max(1, Nfull // Nq)
    if Nfull % Nq == 0:
        c = best.reshape(Nq, k).mean(axis=1)
    else:
        c = _to_quotient(best, Nq)
    c = np.clip(c, 0, None)
    if c.sum() <= 0:
        c = np.ones(Nq)
    c = c / c.sum()
    cR0 = R_of(c)
    print("quotient Nq=%d (k=%d) R=%.12f (ties=%d, nm 0.1/1/5%%=%.4f/%.4f/%.4f)"
          % (Nq, k, cR0, _tie_count(c),
             _frac_near_max(c, 1e-3), _frac_near_max(c, 1e-2),
             _frac_near_max(c, 5e-2)))

    best_c = c.copy()
    best_cR = cR0

    taus = [0.95, 0.90, 0.80, 0.70, 0.60]
    kappas = [3.0, 10.0, 30.0, 100.0]

    cycle = 0
    while time.process_time() < ladder_deadline - 1.0:
        cycle += 1
        improved = False
        for tau in taus:
            for kappa in kappas:
                if time.process_time() >= ladder_deadline - 0.5:
                    break
                c = _lbfgs_linear(c, tau, kappa, 250,
                                  min(ladder_deadline - 0.3,
                                      time.process_time() + 4.0))
                r = R_of(c)
                if r > best_cR + 1e-15:
                    best_c = c.copy()
                    best_cR = r
                    improved = True
            if time.process_time() >= ladder_deadline - 0.5:
                break
        print("cycle %d: quotient R=%.12f (nm 0.1/1/5%%=%.4f/%.4f/%.4f)"
              % (cycle, best_cR,
                 _frac_near_max(best_c, 1e-3), _frac_near_max(best_c, 1e-2),
                 _frac_near_max(best_c, 5e-2)))
        if not improved:
            break

    print("quotient best R=%.12f (was %.12f, nm 0.1/1/5%%=%.4f/%.4f/%.4f)"
          % (best_cR, cR0,
             _frac_near_max(best_c, 1e-3), _frac_near_max(best_c, 1e-2),
             _frac_near_max(best_c, 5e-2)))

    # exact-R tie polish at quotient
    if time.process_time() < deadline - 20.0:
        pol = _lbfgs_block(best_c, np.arange(best_c.size), 200,
                           min(deadline - 18.0, time.process_time() + 4.0), tie=True)
        rp = R_of(pol)
        if rp > best_cR + 1e-15:
            best_c, best_cR = pol, rp
            print("  quotient tie polish R=%.12f" % rp)

    # ---- lift ladder ----
    stage_best = best_c.copy()
    stage_bestR = best_cR
    stage_Nq = Nq

    for Nlift in (3281, 8192, 32768, 104992):
        if time.process_time() >= deadline - 8.0:
            break
        if Nlift <= stage_Nq:
            continue
        h_lift = _cs_lift(stage_best, stage_Nq, Nlift)
        h_lift = _rescale(h_lift)
        r_lift = R_of(h_lift)
        print("lift -> N=%d R=%.12f (nm 0.1/1/5%%=%.4f/%.4f/%.4f)"
              % (Nlift, r_lift,
                 _frac_near_max(h_lift, 1e-3), _frac_near_max(h_lift, 1e-2),
                 _frac_near_max(h_lift, 5e-2)))
        # tie polish
        if time.process_time() < deadline - 6.0:
            pol = _lbfgs_block(h_lift, np.arange(h_lift.size), 150,
                               min(deadline - 5.0, time.process_time() + 5.0), tie=True)
            rp = R_of(pol)
            if rp > r_lift:
                h_lift, r_lift = pol, rp
                print("  tie polish N=%d R=%.12f" % (Nlift, rp))
        # peak-window polish pad 0.05 then 0.03
        for pad in (0.05, 0.03):
            if time.process_time() < deadline - 4.0:
                win = _peak_window(h_lift, pad_frac=pad, extra=128)
                ht = _lbfgs_block(h_lift, win, 150,
                                  min(deadline - 3.0, time.process_time() + 3.0), tie=True)
                r = R_of(ht)
                if r > r_lift:
                    h_lift, r_lift = ht, r
                    print("  peak polish pad=%.2f N=%d R=%.12f" % (pad, Nlift, r))
        # re-flatten at 3281 only
        if Nlift == 3281 and time.process_time() < deadline - 5.0:
            c2 = h_lift.copy()
            c2 = c2 / c2.sum()
            c2 = _lbfgs_linear(c2, 0.85, 30.0, 200,
                               min(deadline - 4.0, time.process_time() + 3.0))
            r2 = R_of(c2)
            if r2 > r_lift:
                h_lift, r_lift = c2, r2
                print("  re-flatten 3281 R=%.12f" % r2)
        if r_lift > stage_bestR + 1e-15 or Nlift == 104992:
            stage_best = h_lift.copy()
            stage_bestR = r_lift
            stage_Nq = Nlift
        if r_lift > altR:
            altR = r_lift
            alt_best = h_lift.copy()

    print("lift stage best R=%.12f (N=%d)" % (stage_bestR, stage_best.size))

    if alt_best is not None and altR > bestR + 1e-15:
        best, bestR = alt_best.copy(), altR

    # final full tie polish until deadline-2s
    if time.process_time() < deadline - 2.0:
        pol = _lbfgs_block(best, np.arange(best.size), 400,
                           deadline - 1.5, tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            print("final tie polish R=%.12f" % rp)

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("frac near max 0.1/1/5%% after: %.4f %.4f %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _upsample2(h):
    return np.repeat(h, 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    best_ref = start_best.copy()
    best_refR = start_bestR

    # --- Stage A: high-beta tie-softening polish on the start ---
    # This is the core new idea: use _fun_grad_beta with moderate beta
    # to gently smooth the max, allowing more knots to rise near the peak.
    if time.process_time() < hard - 4.0:
        cur = best.copy()
        curR = bestR
        for beta in (30.0, 100.0, 300.0, 1000.0):
            if time.process_time() >= hard - 3.5:
                break
            fg = (lambda hh, bb=beta: _fun_grad_beta(hh, bb))
            cap = min(hard - 3.0, time.process_time() + 3.0)
            hq = _lbfgs_log(cur, 200, cap, fg=fg)
            # final polish with true objective
            cap2 = min(hard - 2.0, time.process_time() + 2.0)
            hp = _lbfgs_log(hq, 150, cap2, fg=_fun_grad)
            rp = R_of(hp)
            if rp > curR + 1e-14:
                cur, curR = hp, rp
        if curR > best_refR:
            best_ref, best_refR = cur, curR
            print("  beta-polish R=%.9f" % best_refR)

    # --- Stage B: 2x refinement trials ---
    h2 = _rescale(_upsample2(best))
    N2 = h2.size
    rng = np.random.RandomState(12345)

    trials = []
    amps = [0.01, 0.03, 0.10]
    freqs = [1, 2, 4, 8]
    signs = [(1.0, -1.0), (1.0, 1.0)]
    idx = np.arange(N2 // 2, dtype=float)
    trial_count = 0
    max_trials = 8
    for a in amps:
        for f in freqs:
            if trial_count >= max_trials:
                break
            phase = rng.uniform(0, 2 * np.pi)
            s = signs[trial_count % 2]
            v = np.sin(2 * np.pi * f * idx / (N2 // 2) + phase)
            mult = np.empty(N2)
            mult[0::2] = 1.0 + a * s[0] * v
            mult[1::2] = 1.0 + a * s[1] * v
            w = max(1, N2 // 8)
            lo = rng.randint(0, max(1, N2 - w))
            jitter = 1.0 + rng.uniform(-0.03, 0.03, size=w)
            mult[lo:lo + w] *= jitter
            ht = _rescale(h2 * mult)
            rt = R_of(ht)
            trials.append((rt, ht))
            trial_count += 1
        if trial_count >= max_trials:
            break

    trials.sort(key=lambda x: -x[0])
    candidates = [t[1] for t in trials[:2]]
    for rt, _ in trials[:2]:
        print("  trial R=%.9f" % rt)

    # --- Stage C: beta polish on candidates ---
    for ci, cand in enumerate(candidates):
        if time.process_time() >= hard - 3.0:
            break
        cur = cand
        curR = R_of(cur)
        for beta in (100.0, 1000.0, 1e4, 1e5):
            if time.process_time() >= hard - 2.5:
                break
            fg = (lambda hh, bb=beta: _fun_grad_beta(hh, bb))
            cap = min(hard - 2.0, time.process_time() + 2.0)
            hq = _lbfgs_log(cur, 120, cap, fg=fg)
            cap2 = min(hard - 1.5, time.process_time() + 1.5)
            hp = _lbfgs_log(hq, 100, cap2, fg=_fun_grad)
            rp = R_of(hp)
            if rp > curR + 1e-14:
                cur, curR = hp, rp
        print("  cand%d R=%.9f" % (ci, curR))
        if curR > best_refR:
            best_ref, best_refR = cur, curR

    # --- Stage D: final polish with remaining budget ---
    if best_refR > bestR + 1e-14:
        best, bestR = best_ref, best_refR
        print("  refinement beat base: R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_topk(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    if k >= Lf.size:
        idx = np.arange(Lf.size)
    else:
        idx = np.argpartition(Lf, -k)[-k:]
    beta = 1.0 / (1e-3 * mx + 1e-30)
    vals = Lf[idx]
    m2 = vals.max()
    e = np.exp(beta * (vals - m2))
    Z = e.sum()
    w = e / Z
    sm = m2 + np.log(Z) / beta
    gsm = np.zeros_like(Lf)
    gsm[idx] = w / sm
    gLf = np.zeros_like(Lf)
    gLf[:-1] += (2 * Lf[:-1] + Lf[1:]) / 3.0
    gLf[1:] += (Lf[:-1] + 2 * Lf[1:]) / 3.0
    gLf = -gLf / num + gsm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _up_resample(h, N_big):
    n = h.size
    if n == N_big:
        return h.copy()
    x = np.linspace(0.0, 1.0, n)
    xb = np.linspace(0.0, 1.0, N_big)
    hb = np.interp(xb, x, h)
    return np.clip(hb, 0.0, None)


def _perturb(h, scale, rng):
    """Multiplicative log-space perturbation of a random subset."""
    h = h.copy()
    n = h.size
    mask = rng.random(n) < 0.3
    h[mask] *= np.exp(scale * rng.standard_normal(mask.sum()))
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size
    rng = np.random.default_rng(12345)

    # PHASE A: top-k soft-max polishing to flatten the peak band.
    for k in (256, 128, 64, 32):
        if time.process_time() >= deadline - 8.0:
            break
        fg = (lambda hh, kk=k: _fun_grad_topk(hh, kk))
        win = _peak_window(best, frac=0.35)
        h = _lbfgs_block(best, win, maxiter=200, deadline=deadline, fg=fg)
        if time.process_time() >= deadline - 6.0:
            break
        h = _lbfgs_log(h, 200, deadline, fg=fg)
        r = R_of(h)
        print("topk k=%d R=%.7f" % (k, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
        elif r > bestR - 0.001:
            best = h

    # PHASE B: exact-objective polish.
    for _ in range(3):
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs_log(best, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("sharp R=%.7f" % bestR)
        else:
            best, bestR = (h, r) if r > bestR else (best, bestR)
            break

    # PHASE C: basin hopping — random perturbations + polish, keep improvements.
    # This is the substantial new search dimension vs the base program.
    it = 0
    while time.process_time() < deadline - 2.5:
        it += 1
        # perturb with a scale that shrinks over time
        elapsed = time.process_time() - t0
        frac = elapsed / max(1e-6, budget_seconds * 0.9)
        scale = 0.05 * (1.0 - 0.7 * min(1.0, frac))
        cand = _perturb(best, scale, rng)
        # polish top-k then exact
        fg = (lambda hh: _fun_grad_topk(hh, 64))
        win = _peak_window(cand, frac=0.4)
        cand = _lbfgs_block(cand, win, maxiter=120, deadline=deadline, fg=fg)
        cand = _lbfgs_log(cand, 200, deadline)
        r = R_of(cand)
        if r > bestR + 1e-12:
            best, bestR = cand, r
            print("hop it=%d R=%.7f" % (it, bestR))
        elif r > bestR - 1e-6 and rng.random() < 0.3:
            # mild acceptance to keep exploring nearby
            best, bestR = cand, r

    # PHASE D: final refinement at higher resolution if budget allows.
    if time.process_time() < deadline - 6.0:
        N2 = int(min(1000000, max(n, int(n * 1.5))))
        if N2 > n:
            hu = _up_resample(best, N2)
            hu = _rescale(hu)
            fg = (lambda hh: _fun_grad_topk(hh, 64))
            hu = _lbfgs_log(hu, 250, deadline, fg=fg)
            hu = _lbfgs_log(hu, 350, deadline)
            r = R_of(hu)
            print("refine N=%d R=%.7f" % (N2, r))
            if r > bestR + 1e-12:
                best, bestR = hu, r

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

