def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _restrict(h, f, o):
    n = h.size
    hr = np.roll(h, -o)
    m = n // f
    hr = hr[:m * f]
    return hr.reshape(m, f).mean(axis=1)


def _prolong(hc, f, o, n):
    up = np.repeat(hc, f)
    if up.size < n:
        up = np.concatenate((up, np.full(n - up.size, up[-1] if up.size else 0.0)))
    else:
        up = up[:n]
    out = np.roll(up, o)
    return out


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, int(idx.min()) - 1)
    hi = min(h.size - 1, int(idx.max()))
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, 100.0 * np.mean(baseH <= 0), mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR
    n = baseH.size

    def try_cycle(h_cur, f, o, time_cap, beta=0.0):
        if time.process_time() >= time_cap - 0.5:
            return h_cur, R_of(h_cur)
        hc = _restrict(h_cur, f, o)
        if hc.size < 8:
            return h_cur, R_of(h_cur)
        hc = _rescale(hc)
        rc0 = R_of(hc)
        cap = min(time_cap - 0.3, time.process_time() + 6.0)
        hc = _lbfgs_log(hc, 400, cap, beta=beta)
        rc = R_of(hc)
        hp = _prolong(hc, f, o, n)
        hp = _rescale(hp)
        rp = R_of(hp)
        cap = min(time_cap - 0.2, time.process_time() + 3.0)
        hp = _lbfgs_log(hp, 300, cap, beta=beta)
        rp2 = R_of(hp)
        cap = min(time_cap - 0.2, time.process_time() + 2.0)
        hp = _lbfgs_log(hp, 150, cap, beta=0.0)
        rp3 = R_of(hp)
        print("  f=%d o=%d b=%.2f: coarse %.9f -> %.9f | prolong %.9f -> %.9f -> %.9f" %
              (f, o, beta, rc0, rc, rp, rp2, rp3))
        return hp, rp3

    # Phase 1: local block polish on peak window (fast, then full)
    if time.process_time() < deadline - 5.0:
        w = _peak_window(bestH)
        cap = min(deadline - 2.0, time.process_time() + 4.0)
        hp = _lbfgs_block(bestH, w, 200, cap)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            print("  peak-window polish improved: R=%.9f" % bestR)

    # Phase 2: multigrid cycles with multiple (f,o) factors, plus beta smoothing
    scan_cap = min(deadline, t0 + budget_seconds * 0.55)
    results = {}
    betas = (0.0, 200.0)
    for f in (2, 3):
        for o in range(f):
            for beta in betas:
                if time.process_time() >= scan_cap - 1.0:
                    break
                hp, rp = try_cycle(bestH, f, o, scan_cap, beta=beta)
                key = (f, o, beta)
                results[key] = (hp, rp)
                if rp > bestR + 1e-14:
                    bestH, bestR = hp.copy(), rp
                    print("  >>> new best from %s: R=%.9f" % (str(key), bestR))

    if results:
        best_key = max(results.keys(), key=lambda k: results[k][1])
    else:
        best_key = (2, 0, 0.0)
    print("selected %s with R=%.9f" % (str(best_key), results.get(best_key, (None, bestR))[1]))

    # Phase 3: alternate best cycle with peak-window block polish
    round_i = 0
    while time.process_time() < deadline - 2.0:
        round_i += 1
        improved = False
        f, o, beta = best_key
        hp, rp = try_cycle(bestH, f, o, deadline - 1.0, beta=beta)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            improved = True
            print("  round %d cycle improved: R=%.9f" % (round_i, bestR))
        if time.process_time() < deadline - 2.0:
            w = _peak_window(bestH)
            cap = min(deadline - 1.0, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, w, 200, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                improved = True
                print("  round %d window improved: R=%.9f" % (round_i, bestR))
        if not improved and time.process_time() > deadline - 6.0:
            break

    # Final full polish
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.5)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    mx, m, near = _stats(bestH)
    print("final N=%d R=%.9f zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestH.size, bestR, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        # try experiment best from multigrid if it differs
        alt = baseH
        if results:
            k = max(results.keys(), key=lambda k: results[k][1])
            rk = results[k][1]
            if rk > baseR + 1e-12:
                alt = results[k][0]
        return {"best": baseH, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------- D2 experiment: piecewise-linear blocks ----------

def _expand_ab(a, b, k):
    u = (np.arange(k, dtype=float) + 0.5) / k
    # h[b, u] = a_b + (b_b - a_b) * u
    h = a[:, None] + (b[:, None] - a[:, None]) * u[None, :]
    return h.reshape(-1)


def _reduce_grad_ab(gh, k):
    gh = gh.reshape(-1, k)
    u = (np.arange(k, dtype=float) + 0.5) / k
    ga = np.sum(gh * (1.0 - u)[None, :], axis=1)
    gb = np.sum(gh * u[None, :], axis=1)
    return ga, gb


def _ab_objective(a, b, k, tie=True):
    h = _expand_ab(a, b, k)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(a.size), np.zeros(b.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(a.size), np.zeros(b.size)
    gLf = -dq / num
    if tie:
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        w = 1.0 / idx.size
        gLf[idx] += w / mx
        sm = mx
    else:
        m = int(np.argmax(Lf))
        gLf[m] += 1.0 / mx
        sm = mx
    gh = _backprop(gLf, h) + 2.0 / s
    ga, gb = _reduce_grad_ab(gh, k)
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, ga, gb


def _optimize_ab(a0, b0, k, free_a, free_b, maxiter, deadline, tie):
    if time.process_time() >= deadline - 0.3:
        return a0, b0
    a = np.clip(a0, 0, None).copy()
    b = np.clip(b0, 0, None).copy()
    ia = np.flatnonzero(free_a)
    ib = np.flatnonzero(free_b)
    n = ia.size + ib.size
    if n == 0:
        return a, b
    x0 = np.concatenate([a[ia], b[ib]])

    def f(x):
        aa = a.copy(); bb = b.copy()
        aa[ia] = np.clip(x[:ia.size], 0.0, None)
        bb[ib] = np.clip(x[ia.size:], 0.0, None)
        val, ga, gb = _ab_objective(aa, bb, k, tie=tie)
        g = np.concatenate([ga[ia], gb[ib]])
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return a0, b0
    if res is None:
        return a0, b0
    aa = a.copy(); bb = b.copy()
    aa[ia] = np.clip(res.x[:ia.size], 0.0, None)
    bb[ib] = np.clip(res.x[ia.size:], 0.0, None)
    return aa, bb


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    altR = -1.0

    # ---- D2: piecewise-linear blocks ----
    N = best.size
    k = 32
    nb = N // k
    if nb >= 1 and N % k == 0:
        c = best.reshape(nb, k).mean(axis=1)
        a = c.copy()
        b = c.copy()

        # Stage (i): b only, a fixed
        if time.process_time() < deadline - 6.0:
            a1, b1 = _optimize_ab(a, b, k,
                                  np.zeros(nb, dtype=bool),
                                  np.ones(nb, dtype=bool),
                                  400, min(deadline - 4.0, time.process_time() + 15.0),
                                  tie=False)
            h1 = _rescale(_expand_ab(a1, b1, k))
            r1 = R_of(h1)
            print("D2 (i) b-only: R=%.12f" % r1)
            if r1 > altR:
                altR, alt_best = r1, h1.copy()
            if r1 > bestR + 1e-15:
                best, bestR = h1.copy(), r1
            a, b = a1, b1

        # Stage (ii): both, plain max
        if time.process_time() < deadline - 4.0:
            a2, b2 = _optimize_ab(a, b, k,
                                  np.ones(nb, dtype=bool),
                                  np.ones(nb, dtype=bool),
                                  400, min(deadline - 2.5, time.process_time() + 15.0),
                                  tie=False)
            h2 = _rescale(_expand_ab(a2, b2, k))
            r2 = R_of(h2)
            print("D2 (ii) both: R=%.12f" % r2)
            if r2 > altR:
                altR, alt_best = r2, h2.copy()
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
            a, b = a2, b2

        # Stage (iii): both, tie gradient
        if time.process_time() < deadline - 2.0:
            a3, b3 = _optimize_ab(a, b, k,
                                  np.ones(nb, dtype=bool),
                                  np.ones(nb, dtype=bool),
                                  400, min(deadline - 1.0, time.process_time() + 15.0),
                                  tie=True)
            h3 = _rescale(_expand_ab(a3, b3, k))
            r3 = R_of(h3)
            print("D2 (iii) both tie: R=%.12f" % r3)
            if r3 > altR:
                altR, alt_best = r3, h3.copy()
            if r3 > bestR + 1e-15:
                best, bestR = h3.copy(), r3

    # ---- Safety net: short full tie polish on best ----
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 5.0),
                           tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            print("full tie polish: R=%.12f" % rp)

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

