    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------- D2 experiment: piecewise-linear blocks ----------

def _expand_ab(a, b, k):
    u = (np.arange(k, dtype=float) + 0.5) / k
    # h[b, u] = a_b + (b_b - a_b) * u
    h = a[:, None] + (b[:, None] - a[:, None]) * u[None, :]
    return h.reshape(-1)


def _reduce_grad_ab(gh, k):
    gh = gh.reshape(-1, k)
    u = (np.arange(k, dtype=float) + 0.5) / k
    ga = np.sum(gh * (1.0 - u)[None, :], axis=1)
    gb = np.sum(gh * u[None, :], axis=1)
    return ga, gb


def _ab_objective(a, b, k, tie=True):
    h = _expand_ab(a, b, k)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(a.size), np.zeros(b.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(a.size), np.zeros(b.size)
    gLf = -dq / num
    if tie:
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        w = 1.0 / idx.size
        gLf[idx] += w / mx
        sm = mx
    else:
        m = int(np.argmax(Lf))
        gLf[m] += 1.0 / mx
        sm = mx
    gh = _backprop(gLf, h) + 2.0 / s
    ga, gb = _reduce_grad_ab(gh, k)
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, ga, gb


def _optimize_ab(a0, b0, k, free_a, free_b, maxiter, deadline, tie):
    if time.process_time() >= deadline - 0.3:
        return a0, b0
    a = np.clip(a0, 0, None).copy()
    b = np.clip(b0, 0, None).copy()
    ia = np.flatnonzero(free_a)
    ib = np.flatnonzero(free_b)
    n = ia.size + ib.size
    if n == 0:
        return a, b
    x0 = np.concatenate([a[ia], b[ib]])

    def f(x):
        aa = a.copy(); bb = b.copy()
        aa[ia] = np.clip(x[:ia.size], 0.0, None)
        bb[ib] = np.clip(x[ia.size:], 0.0, None)
        val, ga, gb = _ab_objective(aa, bb, k, tie=tie)
        g = np.concatenate([ga[ia], gb[ib]])
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return a0, b0
    if res is None:
        return a0, b0
    aa = a.copy(); bb = b.copy()
    aa[ia] = np.clip(res.x[:ia.size], 0.0, None)
    bb[ib] = np.clip(res.x[ia.size:], 0.0, None)
    return aa, bb


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    altR = -1.0

    # ---- D2: piecewise-linear blocks ----
    N = best.size
    k = 32
    nb = N // k
    if nb >= 1 and N % k == 0:
        c = best.reshape(nb, k).mean(axis=1)
        a = c.copy()
        b = c.copy()

        # Stage (i): b only, a fixed
        if time.process_time() < deadline - 6.0:
            a1, b1 = _optimize_ab(a, b, k,
                                  np.zeros(nb, dtype=bool),
                                  np.ones(nb, dtype=bool),
                                  400, min(deadline - 4.0, time.process_time() + 15.0),
                                  tie=False)
            h1 = _rescale(_expand_ab(a1, b1, k))
            r1 = R_of(h1)
            print("D2 (i) b-only: R=%.12f" % r1)
            if r1 > altR:
                altR, alt_best = r1, h1.copy()
            if r1 > bestR + 1e-15:
                best, bestR = h1.copy(), r1
            a, b = a1, b1

        # Stage (ii): both, plain max
        if time.process_time() < deadline - 4.0:
            a2, b2 = _optimize_ab(a, b, k,
                                  np.ones(nb, dtype=bool),
                                  np.ones(nb, dtype=bool),
                                  400, min(deadline - 2.5, time.process_time() + 15.0),
                                  tie=False)
            h2 = _rescale(_expand_ab(a2, b2, k))
            r2 = R_of(h2)
            print("D2 (ii) both: R=%.12f" % r2)
            if r2 > altR:
                altR, alt_best = r2, h2.copy()
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
            a, b = a2, b2

        # Stage (iii): both, tie gradient
        if time.process_time() < deadline - 2.0:
            a3, b3 = _optimize_ab(a, b, k,
                                  np.ones(nb, dtype=bool),
                                  np.ones(nb, dtype=bool),
                                  400, min(deadline - 1.0, time.process_time() + 15.0),
                                  tie=True)
            h3 = _rescale(_expand_ab(a3, b3, k))
            r3 = R_of(h3)
            print("D2 (iii) both tie: R=%.12f" % r3)
            if r3 > altR:
                altR, alt_best = r3, h3.copy()
            if r3 > bestR + 1e-15:
                best, bestR = h3.copy(), r3

    # ---- Safety net: short full tie polish on best ----
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 5.0),
                           tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            print("full tie polish: R=%.12f" % rp)

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, active, maxiter, deadline, mode='plain', beta=0.0, reg=0.0):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    if mode == 'tie':
        fg = _fun_grad_tie
    elif mode == 'beta':
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        if reg > 0:
            xa = np.clip(x, 0.0, None)
            val = val + reg * np.sum(xa * xa)
            g = g + 2.0 * reg * (hh - h)  # approx
        return val, g[active]

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = h.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)
    except Exception:
        return h0


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = idx.min(); hi = idx.max()
    span = hi - lo + 1
    pad = int(pad_frac * span) + extra
    lo = max(0, lo - pad); hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _double_N(h):
    N = len(h)
    N2 = N * 2
    c = np.cumsum(h)
    total = c[-1]
    if total <= 0:
        return np.ones(N2)
    xs = np.arange(N2 + 1) * 0.5
    cm = np.interp(xs, np.arange(N + 1), np.concatenate([[0], c]))
    m = np.diff(cm)
    new = m * 2.0
    if new.sum() <= 0:
        return np.ones(N2)
    return new


def _upsample_smooth(h, N2):
    # linear interpolate heights to finer grid (conserves shape not mass exactly)
    N = len(h)
    xs = np.linspace(0, N, N2 + 1)
    cm = np.concatenate([[0], np.cumsum(h)])
    mass = np.interp(xs, np.arange(N + 1), cm)
    new = np.diff(mass) * (N2 / N)
    if new.sum() <= 0:
        return np.ones(N2)
    return new


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best = np.ones(50)
    best_R = R_of(best)
    if start is not None:
        try:
            s = np.asarray(start, dtype=float)
            r = R_of(s)
            if r > best_R:
                best = s.copy(); best_R = r
        except Exception:
            pass

    def consider(h):
        nonlocal best, best_R
        if h is None:
            return
        h = np.asarray(h, dtype=float)
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return
        r = R_of(h)
        if r > best_R:
            best_R = r
            best = h.copy()

    # Phase 1: refine the start with local L-BFGS on full support
    if best is not None and best.size > 1:
        cur = best.copy()
        for it in range(3):
            if time.process_time() > deadline - 2:
                break
            nxt = _lbfgs(cur, np.arange(cur.size), 400, deadline, mode='tie')
            r = R_of(nxt)
            if r > R_of(cur):
                cur = nxt
            else:
                break
        consider(cur)

    # Phase 2: upsample and refine repeatedly
    N = best.size
    for target_N in (N * 2, N * 4, N * 8, N * 16):
        if time.process_time() > deadline - 3:
            break
        if target_N > 200000:
            break
        cur = _upsample_smooth(best, target_N)
        cur = _rescale(cur)
        for it in range(2):
            if time.process_time() > deadline - 2:
                break
            act = _peak_window(cur, tol=0.99, pad_frac=0.6, extra=512)
            nxt = _lbfgs(cur, act, 300, deadline, mode='tie')
            if R_of(nxt) > R_of(cur):
                cur = nxt
            else:
                break
        consider(cur)
        print(f"upsample N={cur.size} R={R_of(cur):.6f}")

    # Phase 3: if R is very high, try to push via beta-smoothing
    for beta in (200.0, 500.0, 1000.0):
        if time.process_time() > deadline - 2:
            break
        cur = best.copy()
        act = _peak_window(cur, tol=0.999, pad_frac=0.5, extra=512)
        nxt = _lbfgs(cur, act, 300, deadline, mode='beta', beta=beta)
        consider(nxt)

    # Phase 4: final tie polish on best
    if time.process_time() < deadline - 1:
        try:
            cur = best.copy()
            nxt = _lbfgs(cur, np.arange(cur.size), 300, deadline, mode='tie')
            consider(nxt)
        except Exception:
            pass

    if best is None:
        best = np.ones(50)
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _smooth(h, sigma):
    if sigma <= 0:
        return h
    r = int(np.ceil(3 * sigma))
    xs = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (xs / sigma) ** 2)
    k /= k.sum()
    hs = np.convolve(h, k, mode='same')
    return np.clip(hs, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: use a soft-max (log-sum-exp) surrogate for the L_inf term with a
    # moderate beta.  This lets the optimizer raise many near-tied knots of f*f
    # toward the peak simultaneously, instead of only the single argmax knot.
    # Alternating between the exact objective (beta=0) and a soft surrogate
    # (beta>0) lets the peak region broaden and the peak height rise.
    alt_best = best.copy()
    alt_R = bestR

    for beta in (200.0, 400.0, 800.0, 1600.0):
        if time.process_time() >= deadline - 3.0:
            break
        # warm start from current best
        h = best.copy()
        # polish the peak region with the soft surrogate
        h = _window_polish_peak(h, deadline, 0.30, 24, maxiter=300, beta=beta)
        # then exact full polish
        h = _lbfgs_log(h, 400, deadline)
        r = R_of(h)
        print("beta %.0f R=%.7f" % (beta, r))
        if r > alt_R + 1e-15:
            alt_best, alt_R = h, r
            best, bestR = h, r

    # Smoothing exploration as secondary diversification
    for sigma in (3.0, 8.0, 20.0, 50.0):
        if time.process_time() >= deadline - 3.0:
            break
        hs = _smooth(best, sigma)
        hs = _rescale(hs)
        hs = _lbfgs_log(hs, 400, deadline)
        r = R_of(hs)
        print("smooth %.1f R=%.7f" % (sigma, r))
        if r > bestR + 1e-15:
            best, bestR = hs, r
            alt_best, alt_R = hs, r

    # Continue the proven peak-polish loop until budget is exhausted.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            alt_best, alt_R = h, r
            print("peak(%.2f) R=%.7f" % (frac, bestR))

    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    startR = R_of(np.clip(np.asarray(start, dtype=float), 0, None)) if start is not None else 0.0
    if bestR <= startR + 1e-15:
        return {"best": np.clip(np.asarray(start, dtype=float), 0, None)
                if start is not None else best,
                "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    Q = np.sum(Lf * sig)
    if Q <= 0:
        return 1e18, np.zeros(h.size)
    dQ = sig + beta * Lf * sig * (1.0 - sig)
    gLf = dQ / Q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(Q) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _Q_value(h, c, beta):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    tau = c * M
    z = np.clip(beta * (Lf - tau), -60.0, 60.0)
    sig = 1.0 / (1.0 + np.exp(-z))
    return float(np.sum(Lf * sig))


# ---------- NEW: adaptive mesh refinement (AMR) ----------

def _refine(h, factor=2, keep_frac=0.5):
    """Insert extra resolution in the region near the peak of f*f.
    Each original cell becomes `factor` cells (linear interp of heights),
    but only in the peak window; elsewhere keep as-is (consistent N)."""
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    # window around peak in original index space (peak of convolution ~ center)
    half = max(64, int(0.5 * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    out = []
    for i in range(n):
        if lo <= i < hi:
            out.extend([h[i]] * factor)
        else:
            out.append(h[i])
    return _rescale(np.asarray(out, dtype=float))


def _smooth(h, k):
    """Light box smoothing preserving mass, k odd window."""
    if k <= 1:
        return h
    kernel = np.ones(k) / k
    hs = np.convolve(h, kernel, mode='same')
    # preserve edges (convolve same truncates; renormalize)
    hs = np.clip(hs, 0, None)
    return _rescale(hs)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = best.copy()
    alt_bestR = bestR

    # ---- Phase 1: try AMR refinement of the start shape ----
    if time.process_time() < hard - 30.0 and best.size < 400000:
        try:
            h2 = _refine(best, factor=2)
            r2 = R_of(h2)
            print("refine2 R=%.9f (N=%d)" % (r2, h2.size))
            cap = min(hard - 25.0, time.process_time() + 8.0)
            hp = _lbfgs_log(h2, 300, cap, fg=_fun_grad)
            rp = R_of(hp)
            print("  refine2+lbfgs R=%.9f" % rp)
            if rp > alt_bestR:
                alt_best, alt_bestR = hp, rp
                print("  AMR BEAT base")
        except Exception as e:
            print("  AMR failed:", e)

    # ---- Phase 2: Q-sweep and polish on the best ----
    if alt_bestR > bestR:
        best, bestR = alt_best, alt_bestR

    grid = [(0.90, 1e3), (0.95, 1e3), (0.95, 1e5),
            (0.99, 1e4), (0.99, 1e5)]

    sweep = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        for (c, beta) in grid:
            if time.process_time() >= hard - 3.0:
                break
            fg = (lambda hh, cc=c, bb=beta: _fun_grad_Q(hh, cc, bb))
            q0 = _Q_value(best, c, beta)
            cap = min(hard - 2.0, time.process_time() + 3.5)
            hq = _lbfgs_log(best, 150, cap, fg=fg)
            q1 = _Q_value(hq, c, beta)
            rq = R_of(hq)
            hp, rp = _polish(hq, min(hard - 1.0, time.process_time() + 6.0))
            beat = rp > bestR + 1e-14
            print("  [sweep%d c=%.2f beta=%.0e] Q %.6f->%.6f Rq=%.9f "
                  "polish=%.9f %s" %
                  (sweep, c, beta, q0, q1, rq, rp, "BEAT" if beat else ""))
            if beat:
                best, bestR = hp, rp
                improved = True
                print("    new best R=%.9f" % bestR)
        if not improved and sweep > 2:
            if time.process_time() < hard - 3.0:
                cap = min(hard - 2.0, time.process_time() + 3.0)
                hp = _lbfgs_log(best, 300, cap, fg=_fun_grad)
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best, bestR = hp, rp
                    print("    fallback best R=%.9f" % bestR)

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": alt_best}
    elif alt_bestR > start_bestR + 1e-13:
        return {"best": alt_best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": alt_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _lift2(h, alpha):
    """Asymmetric 2x lift: h2[2i]=(1-a)h[i]+a h[i-1]; h2[2i+1]=(1-a)h[i]+a h[i+1]."""
    n = h.size
    hp = np.empty(n)
    hp[1:] = h[:-1]
    hp[0] = h[0]
    hn = np.empty(n)
    hn[:-1] = h[1:]
    hn[-1] = h[-1]
    h2 = np.empty(2 * n)
    h2[0::2] = (1.0 - alpha) * h + alpha * hp
    h2[1::2] = (1.0 - alpha) * h + alpha * hn
    h2 = np.clip(h2, 0, None)
    s0 = h.sum()
    s2 = h2.sum()
    if s2 > 0:
        h2 = h2 * (s0 / s2)
    return _rescale(h2)


def _fold(h2):
    n = h2.size // 2
    return _rescale(h2[0:2 * n:2] + h2[1:2 * n:2])


def construct(budget_seconds, start):
    t0 = time.process_time()
