        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, free=None, tie=False):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad
    if free is None:
        active = None
        x0 = h.copy()
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0
        x0 = h[active].copy()

    def f(x):
        if active is None:
            hh = np.clip(x, 0.0, None)
        else:
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return (val, g if active is None else g[active])

    cb = _make_cb(deadline - 0.15)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    hh = h.copy()
    if active is None:
        hh = np.clip(res.x, 0.0, None)
    else:
        hh[active] = np.clip(res.x, 0.0, None)
    return _rescale(hh)


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _compact_support(h):
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    h = h[nz[0]:nz[-1] + 1]
    return h


def _peak_window(h, tol=0.999, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    best = None
    bestR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.sum() > 0:
            best = _compact_support(s)
            bestR = R_of(best)
            print("start R=%.6f N=%d" % (bestR, len(best)))

    if best is None:
        N0 = 2000
        h = np.zeros(N0)
        h[N0 // 4: N0 // 4 + 50] = 1.0
        best = _rescale(h)
        bestR = R_of(best)

    cur = best.copy()
    if len(cur) < 512:
        cur = _prolongate(cur, 512)

    # Multi-resolution refinement with beta smoothing.
    levels = []
    n = len(cur)
    while n < 200000:
        levels.append(n)
        n = int(n * 1.5) + 1
    levels.append(min(300000, max(n, len(cur))))

    for N in levels:
        if time.process_time() > deadline - 1.0:
            break
        cur = _rescale(_prolongate(cur, N))
        for beta in (6.0, 15.0, 0.0):
            if time.process_time() > deadline - 1.0:
                break
            cur = _lbfgs(cur, 400, deadline, beta=beta)
        Rc = R_of(cur)
        if Rc > bestR:
            cand = _compact_support(cur)
            Rcc = R_of(cand)
            if Rcc >= Rc - 1e-9:
                best = cand
                bestR = Rcc
            else:
                best = cur.copy()
                bestR = Rc
        print("level N=%d R=%.6f best=%.6f" % (N, Rc, bestR))

    # Peak-localized polish with shrinking windows.
