            try_accept(h)
        for beta in (100, 800, 4000):
            if not time_left():
                break
            c = _lbfgs_log(h, 250, deadline, beta=beta)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)
        # Tie-aware global pass
        if time_left():
            c = _lbfgs_block(h, np.arange(h.size), 400, deadline, tie=True)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)
        # Peak-region block refinement with tie-aware objective
        for tol, pad in ((0.999, 0.6), (0.995, 0.9)):
            if not time_left():
                break
            win = _peak_window(h, tol=tol, pad_frac=pad, extra=max(16, N // 300))
            for beta in (0.0, 1500.0):
                if not time_left():
                    break
                c = _lbfgs_block(h, win, 300, deadline, beta=beta)
                if R_of(c) > R_of(h):
                    h = c
                try_accept(h)
            c = _lbfgs_block(h, win, 300, deadline, tie=True)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)

    # --- Phase 2: polish best with alternating tie / beta / log passes ---
    fracs = (0.08, 0.20, 0.35, 0.50, 0.65, 0.15, 0.45)
    fi = 0
    while time_left():
        n = best.size

        # tie-aware global pass
        c = _lbfgs_block(best, np.arange(n), 300, deadline, tie=True)
        if R_of(c) > R_of(best):
            best = _rescale(c)
            bestR = R_of(best)
        else:
            try_accept(c)

        if not time_left():
            break

        # smooth-peak pass
        c = _lbfgs_log(best, 250, deadline, beta=2500.0)
        if R_of(c) > R_of(best):
            best = _rescale(c)
            bestR = R_of(best)
        else:
            try_accept(c)

        if not time_left():
            break

        # local block on peak region
        f = fracs[fi % len(fracs)]
        fi += 1
        L = _knots(best)
        k = int(np.argmax(L))
        half = max(2, int(f * n))
        lo = max(0, (k - half) // 2 - 16)
        hi = min(n, (k + half) // 2 + 17)
        if hi - lo >= 2:
            c = _lbfgs_block(best, np.arange(lo, hi), 250, deadline)
            if R_of(c) > R_of(best):
                best = _rescale(c)
                bestR = R_of(best)
            else:
                try_accept(c)

        if not time_left():
            break

        # plain log pass
        c = _lbfgs_log(best, 250, deadline)
        if R_of(c) > R_of(best):
            best = _rescale(c)
            bestR = R_of(best)
        else:
            try_accept(c)

    if alt is not None and altR > 0 and altR < bestR - 1e-9:
        return {"best": best, "alternative": alt}
    return best

