            if not time_left():
                break
            win = _peak_window(h, tol=tol, pad_frac=pad, extra=max(16, N // 300))
            for beta in (0.0, 1500.0):
                if not time_left():
                    break
                c = _lbfgs_block(h, win, 300, deadline, beta=beta)
                if R_of(c) > R_of(h):
                    h = c
                try_accept(h)
            c = _lbfgs_block(h, win, 300, deadline, tie=True)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)

    # --- Phase 2: polish best with alternating tie / beta / log passes ---
    fracs = (0.08, 0.20, 0.35, 0.50, 0.65, 0.15, 0.45)
    fi = 0
    while time_left():
        n = best.size

        # tie-aware global pass
        c = _lbfgs_block(best, np.arange(n), 300, deadline, tie=True)
        if R_of(c) > R_of(best):
            best = _rescale(c)
            bestR = R_of(best)
        else:
            try_accept(c)

        if not time_left():
            break

        # smooth-peak pass
        c = _lbfgs_log(best, 250, deadline, beta=2500.0)
        if R_of(c) > R_of(best):
            best = _rescale(c)
            bestR = R_of(best)
        else:
            try_accept(c)

        if not time_left():
            break

        # local block on peak region
        f = fracs[fi % len(fracs)]
        fi += 1
        L = _knots(best)
        k = int(np.argmax(L))
        half = max(2, int(f * n))
        lo = max(0, (k - half) // 2 - 16)
        hi = min(n, (k + half) // 2 + 17)
        if hi - lo >= 2:
            c = _lbfgs_block(best, np.arange(lo, hi), 250, deadline)
            if R_of(c) > R_of(best):
                best = _rescale(c)
                bestR = R_of(best)
            else:
                try_accept(c)

        if not time_left():
            break

        # plain log pass
        c = _lbfgs_log(best, 250, deadline)
        if R_of(c) > R_of(best):
            best = _rescale(c)
            bestR = R_of(best)
        else:
            try_accept(c)

    if alt is not None and altR > 0 and altR < bestR - 1e-9:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_band(h, eps, gamma):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    B = np.flatnonzero(Lf >= (1.0 - eps) * mx)
    if B.size > 0:
        gLf[B] -= gamma / (B.size * mx)
        deficit = float(np.mean(mx - Lf[B])) / mx
    else:
        deficit = 0.0
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + gamma * deficit
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 band=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if band is not None:
        eps, gamma = band
        fg = (lambda hh: _fun_grad_band(hh, eps, gamma))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _band_stats(h, eps):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0
    B = Lf >= (1.0 - eps) * mx
    frac = float(np.mean(B))
    if not np.any(B):
        return frac, 0.0
    deficit = float(np.mean(mx - Lf[B])) / mx
    return frac, deficit


def _build_target(L, eps):
    mx = L.max()
    S = L >= (1.0 - eps) * mx
    T = L.copy()
    if not np.any(S):
        return T
    idx = np.flatnonzero(S)
    lo, hi = idx.min(), idx.max()
    val = L[S].mean()
    T[lo:hi + 1] = val
    k = 9
    ker = np.ones(k) / k
    T = np.convolve(T, ker, mode='same')
    return T


def _deconv_step(h0, T, lam, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    Tn = float(np.sum(T * T))
    if Tn <= 0:
        return h0
    h0n = float(np.sum(h * h))
    if h0n <= 0:
        h0n = 1.0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        Lf = _knots(hh)
        r = Lf - T
        val = float(np.sum(r * r)) / Tn + lam * float(np.sum((hh - h) ** 2)) / h0n
        gLf = 2.0 * r / Tn
        g = _backprop(gLf, hh) + 2.0 * lam * (hh - h) / h0n
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- D8 baseline experiment (kept, time-boxed) ----
    alt_best = None
    altR = -1.0
    eps_list = [1e-2, 3e-3]
    for eps in eps_list:
        if time.process_time() >= deadline - 30.0:
            break
        L = _knots(best)
        T = _build_target(L, eps)
        tlim = min(deadline - 28.0, time.process_time() + 8.0)
        hd = _deconv_step(best, T, 1e-3, 60, tlim)
        rd = R_of(hd)
        print("eps=%.1e deconv: R=%.12f" % (eps, rd))
        if rd > altR:
            altR = rd
            alt_best = hd.copy()
        if time.process_time() < deadline - 26.0:
            pol = _lbfgs_block(hd, np.arange(hd.size), 200,
                               min(deadline - 25.0, time.process_time() + 5.0),
                               tie=True)
            rp = R_of(pol)
            if rp > altR:
                altR = rp
                alt_best = pol.copy()
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

    # ---- Band experiment ----
    fr0, def0 = _band_stats(best, 0.05)
    print("band eps=0.05 before: frac=%.4f deficit=%.6f" % (fr0, def0))

    ladder = [(0.05, 0.3), (0.05, 1.0), (0.05, 3.0),
              (0.02, 1.0), (0.02, 3.0), (0.01, 3.0)]
    full = np.arange(best.size)
    rung_best = {}
    for (eps, gamma) in ladder:
        if time.process_time() >= deadline - 12.0:
            break
        tlim = min(deadline - 11.0, time.process_time() + 5.0)
        hb = _lbfgs_block(best, full, 200, tlim, band=(eps, gamma))
        fr, df = _band_stats(hb, 0.05)
        rb = R_of(hb)
        print("band eps=%.2f g=%.1f: R=%.12f bandfrac=%.4f def=%.6f"
              % (eps, gamma, rb, fr, df))
        if time.process_time() < deadline - 8.0:
            pol = _lbfgs_block(hb, full, 200,
                               min(deadline - 7.0, time.process_time() + 4.0),
                               tie=True)
            rp = R_of(pol)
            rung_best[(eps, gamma)] = rp
            if rp > altR:
                altR = rp
                alt_best = pol.copy()
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp
            for pad in (0.05, 0.03):
                if time.process_time() >= deadline - 4.0:
                    break
                win = _peak_window(pol, pad_frac=pad, extra=96)
                ht = _lbfgs_block(pol, win, 300,
                                  min(deadline - 3.0, time.process_time() + 2.5),
                                  tie=True)
                r = R_of(ht)
                if r > altR:
                    altR = r
                    alt_best = ht.copy()
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r

    fr1, def1 = _band_stats(best, 0.05)
    print("band eps=0.05 after: frac=%.4f deficit=%.6f" % (fr1, def1))

    # ---- Cycle best rung with remaining budget ----
    if rung_best:
        best_rung = max(rung_best, key=rung_best.get)
    else:
        best_rung = (0.05, 1.0)
    while time.process_time() < deadline - 2.0:
        eps, gamma = best_rung
        tlim = min(deadline - 1.5, time.process_time() + 3.0)
        hb = _lbfgs_block(best, full, 150, tlim, band=(eps, gamma))
        pol = _lbfgs_block(hb, full, 150,
                           min(deadline - 1.0, time.process_time() + 2.0),
                           tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        else:
            break

    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, full, 200,
                           min(deadline - 0.5, time.process_time() + 2.0),
                           tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, active, maxiter, deadline, mode='plain', beta=0.0):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    if mode == 'tie':
        fg = _fun_grad_tie
    elif mode == 'beta':
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.05)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = h.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)
    except Exception:
        return h0


def _peak_window(h, tol=0.98, pad_frac=0.5, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = idx.min(); hi = idx.max()
    span = hi - lo + 1
    pad = int(pad_frac * span) + extra
    lo = max(0, lo - pad); hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample_mass(h, N2):
    # mass-preserving cumulative-sum interpolation: h_new[i] = H((i+1)/m*N) - H(i/m*N)
    N = len(h)
    c = np.concatenate([[0.0], np.cumsum(h)])
    xs = np.arange(N2 + 1) * (N / N2)
    cm = np.interp(xs, np.arange(N + 1), c)
    new = np.diff(cm) * (N2 / N)
    if new.sum() <= 0:
        return np.ones(N2)
    return np.clip(new, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    best = np.ones(50)
    best_R = R_of(best)
    if start is not None:
        try:
            s = np.asarray(start, dtype=float)
            r = R_of(s)
            if r > best_R:
                best = s.copy(); best_R = r
        except Exception:
            pass

    def consider(h):
        nonlocal best, best_R
        if h is None:
            return False
        h = np.asarray(h, dtype=float)
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return False
        r = R_of(h)
        if r > best_R:
            best_R = r
            best = h.copy()
            return True
        return False

    # Phase 1: refine the start with local L-BFGS on full support
    cur = best.copy()
    for it in range(3):
        if time.process_time() > deadline - 2:
            break
        nxt = _lbfgs(cur, np.arange(cur.size), 400, deadline, mode='tie')
        if R_of(nxt) > R_of(cur):
            cur = nxt
        else:
            break
    consider(cur)

    # Phase 2: real refine ladder
    levels = (200, 400, 800, 1600, 3200, 6400, 12800)
    for target_N in levels:
        if time.process_time() > deadline - 2:
            break
        if target_N <= best.size:
            continue
        level_deadline = min(deadline - 1.5,
                             time.process_time() + (deadline - time.process_time()) / 3.0)
        cur = _upsample_mass(best, target_N)
        cur = _rescale(cur)
        # beta ladder then plain tie
        for mode, beta in (('beta', 1e3), ('beta', 1e5), ('tie', 0.0)):
            if time.process_time() > level_deadline:
                break
            nxt = _lbfgs(cur, np.arange(cur.size), 300, level_deadline,
                         mode=mode, beta=beta)
            if R_of(nxt) > R_of(cur):
                cur = nxt
        # peak-window tie polish
        if time.process_time() < level_deadline:
            act = _peak_window(cur, tol=0.98, pad_frac=0.5, extra=256)
            nxt = _lbfgs(cur, act, 300, level_deadline, mode='tie')
            if R_of(nxt) > R_of(cur):
                cur = nxt
        consider(cur)
        print(f"ladder N={cur.size} R={R_of(cur):.6f}")

    # Phase 3: jitter restart at best N
    if time.process_time() < deadline - 2:
        cur = best.copy()
        rng = np.random.default_rng(12345)
        jit = cur * np.exp(rng.normal(0, 0.05, cur.size))
        jit = _rescale(jit)
        nxt = _lbfgs(jit, np.arange(jit.size), 300, deadline, mode='tie')
        act = _peak_window(nxt, tol=0.98, pad_frac=0.5, extra=256)
        nxt2 = _lbfgs(nxt, act, 300, deadline, mode='tie')
        consider(nxt2)

    # Phase 4: final tie polish on best
    if time.process_time() < deadline - 1:
        try:
            cur = best.copy()
            nxt = _lbfgs(cur, np.arange(cur.size), 300, deadline, mode='tie')
            consider(nxt)
        except Exception:
            pass

    if best is None:
        best = np.ones(50)
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
