    if start is not None:
        best = _rescale(np.asarray(start, dtype=float))
    else:
        N = 8192
        i = np.arange(N, dtype=float)
        best = np.sqrt(N) * (np.sqrt(i + 1) - np.sqrt(i))
        best = _rescale(best)
    bestR = R_of(best)
    print(f"[init] R={bestR:.6f} N={best.size} t={time.process_time()-t0:.2f}")

    def logR(h):
        return -_fun_grad_tie(h)[0]

    # Phase 1: peak-window tie polishes (cheap, precise)
    for k in range(6):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best)
        pol = _lbfgs_block(best, win, 250,
                           min(deadline - 0.5, time.process_time() + 3.0))
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        print(f"[win{k}] R={rp:.7f} best={bestR:.7f} t={time.process_time()-t0:.2f}")

    # Phase 2: beta-smoothed passes to escape ties
    for beta in (30.0, 100.0, 400.0):
        if time.process_time() >= deadline - 1.0:
            break
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 4.0),
                           beta=beta)
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        print(f"[beta{beta}] R={rp:.7f} best={bestR:.7f} t={time.process_time()-t0:.2f}")

    # Phase 3: full tie polishes until deadline
    while time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.5, time.process_time() + 5.0))
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        else:
            # try a small peak-window polish as a perturbation
            win = _peak_window(best, tol=0.9999, extra=64)
            pol2 = _lbfgs_block(best, win, 150,
                                min(deadline - 0.4, time.process_time() + 2.5))
            rp2 = R_of(pol2)
            if rp2 > bestR:
                best, bestR = pol2, rp2
        print(f"[full] R={rp:.7f} best={bestR:.7f} t={time.process_time()-t0:.2f}")

    best = _rescale(best)
    Rf = R_of(best)
    print(f"[final] R={Rf:.6f} N={best.size} t={time.process_time()-t0:.2f}")
    return best

