    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline, beta=beta)


def _peak_region(h, tol=0.9995):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size
    alt, altR = None, 0.0

    def polish(h, dl, betas, iters):
        for beta in betas:
            if time.process_time() >= dl - 0.5:
                break
            h = _lbfgs_all(h, iters, dl, beta=beta)
            h = _window_polish_peak(h, dl, 0.35, 64, maxiter=iters, beta=beta)
        h = _lbfgs_all(h, 800, dl)
        h = _window_polish_peak(h, dl, 0.5, 128)
        return h

    def try_candidate(h, tag, dl):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        print("%s R=%.7f" % (tag, r))
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("  -> new best %.7f" % bestR)

    betas = [4.0, 16.0, 64.0, 256.0, 1024.0, 4096.0, 16384.0]

    # Pass 1: high-beta anneal from start
    if time.process_time() < deadline - 25.0:
        h = polish(best, deadline - 18.0, betas, 300)
        try_candidate(h, "anneal", deadline - 12.0)

    # Pass 2: perturb + anneal (multi-scale noise)
    rng = np.random.RandomState(7)
    for trial in range(4):
        if time.process_time() >= deadline - 12.0:
            break
        n = best.size
        m = max(16, n // 64)
        noise = rng.randn(m)
        p = np.interp(np.linspace(0, 1, n), np.linspace(0, 1, m), noise)
        amp = 0.03 + 0.02 * trial
        hp = _rescale(np.clip(best * np.exp(amp * p), 0, None))
        hp = polish(hp, deadline - 8.0, betas[:5], 220)
        try_candidate(hp, "perturb%d" % trial, deadline - 4.0)

    # Final: alternate exact full/peak polish with high-beta flattening
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_all(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs_all(best, 400, deadline - 1.0, beta=32768.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.55, 128)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _argmax_frac(h):
    Lf = _knots(h)
    if Lf.size <= 2:
        return 0.0
    m = int(np.argmax(Lf))
    return m / float(Lf.size - 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 350, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _tilt_cycle(t, deadline, tag):
    work = t.copy()
    best = t.copy()
    bestR = R_of(t)
    origin = tag
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=1e6)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = tag + "b6"
    if time.process_time() < deadline - 0.5:
        win = _peak_window(work, pad_frac=0.2, extra=128)
        ht = _lbfgs_block(work, win, 200, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = tag + "pk"
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(work, 150, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = tag + "b0"
    return best, bestR, origin


def _upsample(h, factor):
    """Insert intermediate steps between every pair of heights (linear interp)."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    m = (n - 1) * factor + 1
    i = np.arange(m, dtype=float) / factor
    lo = np.floor(i).astype(int)
    hi = np.minimum(lo + 1, n - 1)
    w = i - lo
    out = h[lo] * (1.0 - w) + h[hi] * w
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: baseline polish on start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline: R=%.9f origin=%s" % (bestR, origin))

    # Phase U: upsampling experiment - refine at finer resolution
    for factor in [2, 3]:
        if time.process_time() >= deadline - 3.0:
            break
        up = _upsample(best, factor)
        r_up = R_of(up)
        print("upsample x%d: seed R=%.9f N=%d" % (factor, r_up, up.size))
        if time.process_time() >= deadline - 2.0:
            break
        w, b, br, org = _run_cycle(up, up.copy(), r_up,
                                    deadline - 1.0, 'up%d' % factor)
        print("upsample x%d: R=%.9f origin=%s" % (factor, br, org))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("upsample x%d NEW BEST R=%.9f" % (factor, bestR))
        elif br > alt_bestR and br > start_bestR + 1e-14:
            alt_best, alt_bestR = b, br

    # Phase B: random multi-start perturbations
    rng = np.random.default_rng(12345)
    amps = [0.01, 0.03, 0.05, 0.08, 0.12, 0.02, 0.04, 0.06, 0.10, 0.15]
    for trial, amp in enumerate(amps):
        if time.process_time() >= deadline - 1.0:
            break
        seed = _random_perturb(best, rng, amp)
        r_seed = R_of(seed)
        w, b, br, org = _run_cycle(seed, seed.copy(), r_seed, deadline,
                                   'rand%d' % trial)
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("rand%d amp=%.3f NEW BEST R=%.9f" % (trial, amp, bestR))
        else:
            if br > alt_bestR:
                alt_best, alt_bestR = b, br

    # Phase E: global exponential tilt experiment
    N = best.size
    i = np.arange(N, dtype=float)
    u = 2.0 * i / max(1.0, (N - 1)) - 1.0
    trials = []
    for kind in ['lin', 'quad']:
        for c in [-0.9, -0.45, -0.2, 0.2, 0.45, 0.9]:
            trials.append((kind, c))

    tilt_alt = None
    tilt_altR = -1.0
    idx = 0
    while time.process_time() < deadline - 1.0 and idx < len(trials) * 2:
        kind, c = trials[idx % len(trials)]
        idx += 1
        now = time.process_time()
        remaining = max(1, len(trials) - (idx % len(trials)) + 1)
        cap = now + max(0.5, (deadline - 1.0 - now) / remaining)
        sub_deadline = min(cap, deadline - 1.0)
        t = best.copy()
        if kind == 'lin':
            t *= np.exp(np.clip(c * u, -60.0, 60.0))
        else:
            t *= np.exp(np.clip(c * u * u, -60.0, 60.0))
        t = _rescale(np.clip(t, 0, None))
        r_seed = R_of(t)
        b, br, org = _tilt_cycle(t, sub_deadline, 'tilt_%s%g' % (kind, c))
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("tilt %s c=%+.2f NEW BEST R=%.9f" % (kind, c, bestR))
        elif br > tilt_altR and br > start_bestR + 1e-14:
            tilt_alt, tilt_altR = b, br

    # Final window sweep on best
    if time.process_time() < deadline - 0.5:
        for pad in [0.2, 0.1, 0.05]:
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                origin = "final_pk%g" % pad
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_all_pos(best, 200, deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                origin = "final_b0"

    if tilt_alt is not None and tilt_alt.size == best.size and tilt_altR < bestR:
        if alt_best is None or tilt_altR > alt_bestR:
            alt_best, alt_bestR = tilt_alt, tilt_altR

    print("final R=%.9f origin=%s (start %.9f, N=%d) argmax_frac=%.3f" %
          (bestR, origin, start_bestR, best.size, _argmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
