    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _coord_sweep(h, bestR, deadline, rng, n_runs=6):
    h = h.copy()
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h, bestR
    B = max(20, nz.size // 100)
    for _ in range(n_runs):
        if time.process_time() >= deadline - 0.2:
            break
        start = rng.integers(0, max(1, nz.size - B + 1))
        sel = nz[start:start + B]
        if sel.size == 0:
            continue
        factors = np.exp(0.01 * rng.standard_normal(sel.size))
        h2 = h.copy()
        h2[sel] *= factors
        h2 = _rescale(h2)
        r2 = R_of(h2)
        if r2 > bestR + 1e-13:
            h, bestR = h2, r2
    return h, bestR


def _half_cycle(c, bestR, deadline, tag="", pads=None, rng=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0
    rng = np.random.default_rng(20240607)

    # ---- NEW Phase 0: direct full-N heavy polish with mixed beta schedule ----
    # The start is already a strong full-N construction. Rather than immediately
    # descending to half-resolution (which loses fine detail), spend a solid
    # chunk polishing full-N directly with alternating beta=1e7 and beta=0.
    polish_end = min(deadline - 40.0, time.process_time() + 0.35 * budget_seconds)
    work = best.copy()
    round_i = 0
    while time.process_time() < polish_end - 1.0:
        round_i += 1
        for beta in [1e7, 0.0]:
            if time.process_time() >= polish_end - 0.8:
                break
            ht = _lbfgs_all_pos(work, 250, polish_end - 0.5, beta=beta)
            r = R_of(ht)
            if r >= bestR - 1e-15:
                work = ht
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                origin = 'p0_b%g' % beta
                print("phase0 beta=%g NEW BEST R=%.9f" % (beta, bestR))
        # peak polish
        if time.process_time() < polish_end - 1.0:
            win = _peak_window(work, pad_frac=0.08, extra=128)
            ht = _lbfgs_block(work, win, 300, polish_end - 0.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                work = ht
                best, bestR = ht.copy(), r
                origin = 'p0_pk'
                print("phase0 pk NEW BEST R=%.9f" % bestR)
            elif r > R_of(work) - 1e-15:
                work = ht
        if round_i % 2 == 0 and time.process_time() < polish_end - 1.0:
            h_ca, r_ca = _coord_sweep(work, R_of(work),
                                      min(polish_end - 0.5,
                                          time.process_time() + 1.5),
                                      rng, n_runs=6)
            if r_ca > R_of(work) + 1e-14:
                work = h_ca
                if r_ca > bestR + 1e-14:
                    best, bestR = h_ca.copy(), r_ca
                    origin = 'p0_ca'
                    print("phase0 ca NEW BEST R=%.9f" % bestR)
    print("after phase0 R=%.9f rounds=%d" % (bestR, round_i))

    # ---- Phase 1: half-resolution quotient search (kept, but shorter) ----
    best_c = None
    best_cR = -1.0
    half_deadline = min(deadline - 6.0, time.process_time() + 0.20 * budget_seconds)
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < half_deadline - 1.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds, rng=rng)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= half_deadline - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 300, half_deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: restarts from half-res with jitter, lifting to full ----
    ri = 0
    if best_c is not None and time.process_time() < deadline - 12.0:
        amps = [0.0015, 0.002, 0.003]
        while time.process_time() < deadline - 12.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc2 = best_c.copy()
            nz = cc2 > 0
            if nz.sum() == 0:
                break
            cc2[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc2 = _rescale(cc2)
            r0 = R_of(cc2)
            slice_deadline = min(deadline - 8.0,
                                 time.process_time() + 0.06 * budget_seconds)
            work_c2, cand_c, cand_cR, org = _half_cycle(
                cc2, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.20, 0.15], rng=rng)
            print("restart %d amp=%.4f R(c)=%.9f (best_c %.9f)" %
                  (ri, amp, cand_cR, best_cR))
            if cand_cR > best_cR + 1e-12:
                best_c = cand_c.copy()
                best_cR = cand_cR
                print("  ACCEPT R(c)=%.9f" % best_cR)
            h_lift = _rescale(np.repeat(cand_c, 2))
            ht = h_lift
            for beta in [1e6, 1e7]:
                if time.process_time() >= slice_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
            r_lift = R_of(ht)
            h_ca, r_ca = _coord_sweep(ht, r_lift, slice_deadline, rng, n_runs=6)
            if r_ca > r_lift + 1e-13:
                ht_ca = _lbfgs_all_pos(h_ca, 150, slice_deadline - 0.2, beta=1e7)
                r_ca2 = R_of(ht_ca)
                if r_ca2 > r_ca:
                    h_ca, r_ca = ht_ca, r_ca2
                mech = 'coord'
            else:
                mech = 'lift'
            if r_ca > r_lift:
                cand_h, cand_r, cand_mech = h_ca, r_ca, mech
            else:
                cand_h, cand_r, cand_mech = ht, r_lift, 'lift'
            if cand_r > bestR + 1e-13:
                best, bestR, origin = cand_h.copy(), cand_r, 'rs%d_%s' % (ri, cand_mech)
                print("  restart %s NEW BEST R=%.9f" % (cand_mech, bestR))
            elif cand_r > alt_bestR:
                alt_best, alt_bestR = cand_h.copy(), cand_r

    # ---- Phase 3: lift best half-res, full-N polish ----
    if best_c is not None:
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        if r_lift > bestR + 1e-14:
            best, bestR, origin = h_lift.copy(), r_lift, 'final_lift'
            print("final lift NEW BEST R=%.9f" % bestR)
        elif r_lift > alt_bestR:
            alt_best, alt_bestR = h_lift, r_lift
        ht = h_lift
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 5.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 4.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+full'
            print("full polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 4: fine peak polish on best ----
    if time.process_time() < deadline - 3.0:
        for pad in [0.12, 0.08, 0.05]:
            if time.process_time() >= deadline - 2.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 2.0, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 4b: coordinate-ascent micro-refinement ----
    if time.process_time() < deadline - 2.5:
        ca_deadline = min(deadline - 1.5, time.process_time() + 0.08 * budget_seconds)
        h_ca, r_ca = _coord_sweep(best, bestR, ca_deadline, rng, n_runs=8)
        if r_ca > bestR + 1e-13:
            ht = _lbfgs_all_pos(h_ca, 150, deadline - 1.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, origin + '+coord'
                print("coord polish NEW BEST R=%.9f" % bestR)
            elif r_ca > bestR + 1e-13:
                best, bestR, origin = h_ca.copy(), r_ca, origin + '+coord0'
                print("coord polish NEW BEST R=%.9f" % bestR)
            else:
                if r_ca > alt_bestR:
                    alt_best, alt_bestR = h_ca, r_ca

    # ---- NEW Phase 4d: final short block-jitter + beta alternation ----
    jit_end = deadline - 2.0
    sigmas = [0.004, 0.008]
    sweep = 0
    while time.process_time() < jit_end - 0.5:
        sigma = sigmas[sweep % len(sigmas)]
        sweep += 1
        nz = np.flatnonzero(best > 0)
        if nz.size == 0:
            break
        B = max(20, nz.size // 100)
        Lrun = max(1, nz.size // B)
        accepts = 0
        n_trials = max(4, min(20, Lrun))
        for _ in range(n_trials):
            if time.process_time() >= jit_end - 0.5:
                break
            if nz.size <= Lrun:
                idx = nz
            else:
                s0 = int(rng.integers(0, nz.size - Lrun + 1))
                idx = nz[s0:s0 + Lrun]
            trial = best.copy()
            trial[idx] *= np.exp(sigma * rng.standard_normal(idx.size))
            trial = _rescale(trial)
            r = R_of(trial)
            if r > bestR + 1e-15:
                best, bestR = trial, r
                origin = origin + '+jit'
                accepts += 1
        if accepts >= 1:
            now = time.process_time()
            d1 = min(deadline - 1.0, now + 2.0)
            ht = _lbfgs_all_pos(best, 150, d1, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, origin + '+jall'

    # ---- Phase 5: trailing beta=0 polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("restarts=%d best_c=%.9f best_full=%.9f" % (ri, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, active, maxiter, deadline, mode='plain', beta=0.0):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    if mode == 'tie':
        fg = _fun_grad_tie
    elif mode == 'beta':
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.05)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = h.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)
    except Exception:
        return h0


def _peak_window(h, tol=0.98, pad_frac=0.5, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = idx.min(); hi = idx.max()
    span = hi - lo + 1
    pad = int(pad_frac * span) + extra
    lo = max(0, lo - pad); hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample_mass(h, N2):
    N = len(h)
    c = np.concatenate([[0.0], np.cumsum(h)])
    xs = np.arange(N2 + 1) * (N / N2)
    cm = np.interp(xs, np.arange(N + 1), c)
    new = np.diff(cm) * (N2 / N)
    if new.sum() <= 0:
        return np.ones(N2)
    return np.clip(new, 0, None)


def _double(h):
    h2 = np.repeat(h, 2) / np.sqrt(2.0)
    k = np.array([0.25, 0.5, 0.25])
    sm = np.convolve(h2, k, mode='same')
    if sm.sum() <= 0:
        return h2
    return sm


def _frac_near(h, frac):
    Lf = _knots(h)
    mx = Lf.max()
    return float(np.mean(Lf >= mx * (1.0 - frac)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    best = np.ones(50)
    best_R = R_of(best)
    if start is not None:
        try:
            s = np.asarray(start, dtype=float)
            r = R_of(s)
            if r > best_R:
                best = s.copy(); best_R = r
        except Exception:
            pass

    def consider(h):
        nonlocal best, best_R
        if h is None:
            return False
        h = np.asarray(h, dtype=float)
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return False
        r = R_of(h)
        if r > best_R:
            best_R = r
            best = h.copy()
            return True
        return False

    # Phase 1: refine the start with local L-BFGS on full support
    cur = best.copy()
    for it in range(3):
        if time.process_time() > deadline - 2:
            break
        nxt = _lbfgs(cur, np.arange(cur.size), 400, deadline, mode='tie')
        if R_of(nxt) > R_of(cur):
            cur = nxt
        else:
            break
    consider(cur)

    # Phase 2: real refine ladder (base behavior)
    levels = (200, 400, 800, 1600, 3200, 6400, 12800)
    for target_N in levels:
        if time.process_time() > deadline - 2:
            break
        if target_N <= best.size:
            continue
        level_deadline = min(deadline - 1.5,
                             time.process_time() + (deadline - time.process_time()) / 3.0)
        cur = _upsample_mass(best, target_N)
        cur = _rescale(cur)
        for mode, beta in (('beta', 1e3), ('beta', 1e5), ('tie', 0.0)):
            if time.process_time() > level_deadline:
                break
            nxt = _lbfgs(cur, np.arange(cur.size), 300, level_deadline,
                         mode=mode, beta=beta)
            if R_of(nxt) > R_of(cur):
                cur = nxt
        if time.process_time() < level_deadline:
            act = _peak_window(cur, tol=0.98, pad_frac=0.5, extra=256)
            nxt = _lbfgs(cur, act, 300, level_deadline, mode='tie')
            if R_of(nxt) > R_of(cur):
                cur = nxt
        consider(cur)
        print(f"ladder N={cur.size} R={R_of(cur):.6f}")

    # Phase 3: EXPERIMENT - compounding doublings with genuine per-level optimization
    def window_5pct(h):
        Lf = _knots(h)
        mx = Lf.max()
        idx = np.flatnonzero(Lf >= 0.95 * mx)
        if idx.size == 0:
            return np.arange(h.size)
        lo = idx.min(); hi = idx.max()
        span = hi - lo + 1
        pad = int(0.30 * span)
        lo = max(0, lo - pad); hi = min(h.size - 1, hi + pad)
        win = np.arange(lo, hi + 1)
        if win.size > 0.60 * h.size:
            return np.arange(h.size)
        return win

    def level_optimize(h, level_deadline):
        # (2) tie-aware L-BFGS on peak window, time-box 6s
        act = window_5pct(h)
        d = min(level_deadline, time.process_time() + 6.0)
        nxt = _lbfgs(h, act, 300, d, mode='tie')
        if R_of(nxt) > R_of(h):
            h = nxt
        # (3) beta-softmax passes on same window
        for beta in (1e3, 1e4):
            if time.process_time() >= level_deadline:
                break
            act = window_5pct(h)
            d = min(level_deadline, time.process_time() + 3.0)
            nxt = _lbfgs(h, act, 150, d, mode='beta', beta=beta)
            if R_of(nxt) > R_of(h):
                h = nxt
        # (4) sharp exact-R tie polish on window, 2s
        if time.process_time() < level_deadline:
            act = window_5pct(h)
            d = min(level_deadline, time.process_time() + 2.0)
            nxt = _lbfgs(h, act, 200, d, mode='tie')
            if R_of(nxt) > R_of(h):
                h = nxt
        return h

    h_acc = best.copy()
    r_acc = best_R
    print(f"double N={h_acc.size} R={r_acc:.6f} "
          f"f01={_frac_near(h_acc,1e-3):.4f} f1={_frac_near(h_acc,1e-2):.4f} "
          f"f5={_frac_near(h_acc,5e-2):.4f}")

    while time.process_time() < deadline - 8 and h_acc.size < 262144:
        h2 = _double(h_acc)
        h2 = _rescale(h2)
        level_deadline = min(deadline - 8,
                             time.process_time() + 12.0)
        h2 = level_optimize(h2, level_deadline)
        r2 = R_of(h2)
        if r2 > r_acc:
            h_acc = h2
            r_acc = r2
            consider(h_acc)
            print(f"double N={h_acc.size} R={r_acc:.6f} "
                  f"f01={_frac_near(h_acc,1e-3):.4f} f1={_frac_near(h_acc,1e-2):.4f} "
                  f"f5={_frac_near(h_acc,5e-2):.4f}")
        else:
            # keep previous h, but try one more polish on the doubled version
            # then continue doubling from accepted best
            print(f"double N={h2.size} R={r2:.6f} (no gain, keep N={h_acc.size})")
            # still allow continuing: double from accepted best again next loop
            # but avoid infinite loop at same N: force accept structure if it's
            # the only way to grow, else break
            if h_acc.size >= 262144:
                break
            # try a stronger polish on h2 before giving up
            d = min(deadline - 8, time.process_time() + 6.0)
            act = np.arange(h2.size)
            h3 = _lbfgs(h2, act, 200, d, mode='tie')
            r3 = R_of(h3)
            if r3 > r_acc:
                h_acc = h3
                r_acc = r3
                consider(h_acc)
                print(f"double N={h_acc.size} R={r_acc:.6f} (full polish)")
            else:
                break

    # Phase 5: final full-array tie polish of best accepted h
    if time.process_time() < deadline - 1:
        d = deadline - 0.5
        nxt = _lbfgs(best, np.arange(best.size), 400, d, mode='tie')
        consider(nxt)

    if best is None:
        best = np.ones(50)
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Alternative construction: single-peak polish on the whole thing.
    # The key new idea: full-vector tie-penalised L-BFGS on the raw heights,
    # then a beta-continuation to sharpen the flat top of f*f.
    alt = best.copy()
    altR = bestR

    # Phase A: full non-negativity polish with tie objective
    if time.process_time() < deadline - 2.0:
        full = np.arange(alt.size)
        lim = min(deadline - 0.5, time.process_time() + budget_seconds * 0.35)
        h1 = _lbfgs_block(alt, full, 400, lim, beta=0.0)
        r1 = R_of(h1)
        if r1 > altR + 1e-14:
            alt, altR = h1, r1
            print("phaseA R=%.9f" % altR)

    # Phase B: beta continuation to make the max more robust (flat top)
    for beta in (30.0, 80.0, 200.0, 500.0):
        if time.process_time() >= deadline - 1.0:
            break
        lim = min(deadline - 0.5, time.process_time() + budget_seconds * 0.12)
        hb = _lbfgs_block(alt, np.arange(alt.size), 200, lim, beta=beta)
        rb = R_of(hb)
        if rb > altR + 1e-15:
            alt, altR = hb, rb
            print("beta=%.0f R=%.9f" % (beta, altR))

    # Phase C: final tie polish on window around peak(s)
    if time.process_time() < deadline - 1.0:
        win = _peak_window(alt, pad_frac=0.2, extra=128)
        lim = min(deadline - 0.3, time.process_time() + 3.0)
        ht = _lbfgs_block(alt, win, 300, lim, beta=0.0)
        rt = R_of(ht)
        if rt > altR + 1e-15:
            alt, altR = ht, rt
            print("phaseC R=%.9f" % altR)

    print("alt R=%.9f (start %.9f, N=%d, ties=%d)"
          % (altR, startR, alt.size, _tie_count(alt)))

    if altR > startR + 1e-14:
        return {"best": alt, "alternative": best}
    return {"best": best, "alternative": alt}

