        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _refine(h, deadline, rounds=6):
    """Alternate full and peak-window tie polishes, plus a beta-smoothed pass."""
    best = h.copy()
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.5, time.process_time() + 5.0))
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        if time.process_time() < deadline - 1.0:
            for beta in (50.0, 200.0):
                if time.process_time() >= deadline - 0.6:
                    break
                pb = _lbfgs_block(best, np.arange(best.size), 200,
                                 min(deadline - 0.4, time.process_time() + 4.0),
                                 beta=beta)
                rb = R_of(pb)
                if rb > bestR:
                    best, bestR = pb, rb
        if time.process_time() < deadline - 1.0:
            win = _peak_window(best, 0.9995, 0.4, 256)
            pw = _lbfgs_block(best, win, 300,
                             min(deadline - 0.4, time.process_time() + 3.0))
            rw = R_of(pw)
            if rw > bestR:
                best, bestR = pw, rw
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(64)
        best_r = R_of(best)

    cur = best.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand.copy(), r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # ---------------- Main loop: alternating full/beta/window polishes -------
    # Allocate the whole budget to iterated refinement, alternating full-vector
    # tie-based L-BFGS with beta-smoothed passes and peak-window polishes.
    try:
        h = cur.copy()
        it = 0
        while time.process_time() < deadline - 1.0:
            it += 1
            # full vector tie polish
            c = _lbfgs_block(h, np.arange(h.size), 400, deadline - 0.5)
            rc = R_of(c)
            if rc > R_of(h):
                h = c
            _consider(h, R_of(h))
            if time.process_time() >= deadline - 1.0:
                break
            # beta-smoothed escape passes (descending beta)
            for beta in (300.0, 120.0, 50.0, 20.0):
                if time.process_time() >= deadline - 1.0:
                    break
                cb = _lbfgs_block(h, np.arange(h.size), 250,
                                  min(deadline - 0.5, time.process_time() + 3.0),
                                  beta=beta)
                rb = R_of(cb)
                if rb > R_of(h):
                    h = cb
            _consider(h, R_of(h))
            if time.process_time() >= deadline - 1.0:
                break
            # peak-window polishes at shrinking windows
            for tol, pf, ex in ((0.9995, 0.4, 256), (0.999, 0.25, 128),
                                 (0.995, 0.15, 64)):
                if time.process_time() >= deadline - 1.0:
                    break
                win = _peak_window(h, tol, pf, ex)
                cw = _lbfgs_block(h, win, 300,
                                  min(deadline - 0.5, time.process_time() + 3.0))
                rw = R_of(cw)
                if rw > R_of(h):
                    h = cw
            _consider(h, R_of(h))
            print("iter %d R=%.6f frac=%.4f" % (it, best_r, _frac_near_max(best)))
    except Exception:
        pass

    # ---------------- Final concentrated polish ---------------------------
    try:
        if time.process_time() < deadline - 0.3:
            fin = _refine(best, deadline, rounds=4)
            _consider(fin, R_of(fin))
    except Exception:
        pass

    if start_arr is not None:
        sr = R_of(start_arr)
        if best_r < sr:
            best = start_arr.copy()
            best_r = sr

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine(h, factor):
    n = h.size
    newn = n * factor
    xn = np.linspace(0, n - 1, newn)
    out = np.interp(xn, np.arange(n, dtype=float), h)
    return _rescale(np.clip(out, 0, None))


def _coarsen(h, factor):
    n = h.size
    m = n // factor
    if m < 2:
        return h
    return h[:m * factor].reshape(m, factor).sum(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    np.random.seed(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    print("base R=%.9f N=%d" % (baseR, baseH.size))

    bestH, bestR = baseH.copy(), baseR
    altH, altR = None, 0.0

    # ---------- Stage A: resolution doubling + reopt ----------
    if baseH.size < 400000:
        factor = 2 if baseH.size < 200000 else 1
        if factor > 1:
            up = _seed_zeros(_refine(baseH, factor))
            cap = min(deadline - 5.0, time.process_time() + budget_seconds * 0.22)
            hu = _lbfgs_log(up, 120, cap, beta=0.0)
            ru = R_of(hu)
            print("upsample x%d R=%.9f" % (factor, ru))
            if ru > bestR + 1e-14:
                bestH, bestR = hu, ru
            else:
                altH, altR = hu, ru

    # ---------- Stage B: tie-aware polish (flat top) ----------
    if time.process_time() < deadline - 5.0:
        cap = min(deadline - 4.0, time.process_time() + budget_seconds * 0.15)
        ht = _lbfgs_log(bestH, 150, cap, tie=True)
        rt = R_of(ht)
        print("tie R=%.9f" % rt)
        if rt > bestR + 1e-15:
            bestH, bestR = ht, rt
        elif altH is None or rt > altR:
            altH, altR = ht, rt

    # ---------- Stage C: beta homotopy for sharper peak ----------
    for beta in (1000.0, 5000.0, 20000.0, 80000.0):
        if time.process_time() >= deadline - 4.0:
            break
        cap = min(deadline - 3.0, time.process_time() + budget_seconds * 0.10)
        hb = _lbfgs_log(bestH, 80, cap, beta=beta)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            bestH, bestR = hb, rb
            print("beta=%.0f R=%.9f" % (beta, bestR))

    # ---------- Stage D: alternate global / peak-window / tie ----------
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        progress = False
        # global
        cap = min(deadline - 1.0, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-15:
            bestH, bestR = hs, rs
            print("  G it=%d R=%.9f" % (it, bestR))
            progress = True
        if time.process_time() >= deadline - 1.5:
            break
        # tie-aware global
        cap = min(deadline - 1.0, time.process_time() + 2.0)
        ht = _lbfgs_log(bestH, 120, cap, tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            bestH, bestR = ht, rt
            print("  T it=%d R=%.9f" % (it, bestR))
            progress = True
        if time.process_time() >= deadline - 1.5:
            break
        # peak-window
        tol = [0.99995, 0.9999, 0.9995, 0.999, 0.995][it % 5]
        free = _peak_window(bestH, tol=tol)
        cap = min(deadline - 1.0, time.process_time() + 2.0)
        hp = _lbfgs_block(bestH, free, 200, cap, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            bestH, bestR = hp, rp
            print("  P it=%d tol=%.5f R=%.9f" % (it, tol, bestR))
            progress = True
        if not progress:
            # try a small beta push to escape
            cap = min(deadline - 1.0, time.process_time() + 1.5)
            hb = _lbfgs_log(bestH, 60, cap, beta=30000.0)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                bestH, bestR = hb, rb
                print("  B it=%d R=%.9f" % (it, bestR))

    print("fine R=%.9f (base %.9f)" % (bestR, baseR))

    if altH is None or altR <= baseR:
        altH = baseH
    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": altH}
    else:
        return {"best": baseH, "alternative": bestH}

