    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%) before: %.4f" % _frac_near_max(best, 1e-3))

    alt_best = None
    altR = -1.0

    # ---- D1 experiment: gradient step in L-space, deconvolve back to h ----
    etas = [0.002, 0.01, 0.03]
    tries = 0
    while time.process_time() < deadline - 6.0 and tries < 12:
        tries += 1
        h0 = best
        L0 = _knots(h0)
        mx = L0.max()
        if mx <= 0:
            break
        gL = _grad_L(L0)
        gmax = np.max(np.abs(gL))
        if gmax <= 0:
            break
        gL = gL / gmax
        improved_any = False
        for eta in etas:
            if time.process_time() >= deadline - 5.0:
                break
            T = L0 + eta * mx * gL
            T = np.clip(T, 0.0, None)
            tlim = min(deadline - 3.0, time.process_time() + 8.0)
            hd = _deconv_step(h0, T, 1e-4, 200, tlim)
            resid = _deconv_residual(hd, T)
            rd = R_of(hd)
            print("eta=%.3g deconv: resid=%.3e R=%.12f" % (eta, resid, rd))
            if rd > altR:
                altR = rd
                alt_best = hd.copy()
            # full-N tie polish
            if time.process_time() < deadline - 2.0:
                pol = _lbfgs_block(hd, np.arange(hd.size), 200,
                                   min(deadline - 1.5, time.process_time() + 8.0),
                                   tie=True)
                rp = R_of(pol)
                print("  full polish R=%.12f" % rp)
                if rp > altR:
                    altR = rp
                    alt_best = pol.copy()
                if rp > bestR + 1e-14:
                    best, bestR = pol.copy(), rp
                    improved_any = True
            # peak-window tie polish
            if time.process_time() < deadline - 1.5:
                win = _peak_window(hd, pad_frac=0.05, extra=96)
                ht = _lbfgs_block(hd, win, 300,
                                  min(deadline - 1.0, time.process_time() + 4.0),
                                  tie=True)
                r = R_of(ht)
                if r > altR:
                    altR = r
                    alt_best = ht.copy()
                if r > bestR + 1e-14:
                    best, bestR = ht.copy(), r
                    improved_any = True
        if not improved_any:
            # try smaller etas once more before giving up
            if tries >= 2:
                break

    print("frac near max (0.1%%) after: %.4f" % _frac_near_max(best, 1e-3))

    # safety net: base's own tie polish
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 4.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_flat(h, tau, kappa):
    """-log R + kappa * mean(relu(max(L)-L_j)/max(L))^2 over knots L_j >= tau*max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    sel = np.flatnonzero(Lf >= tau * mx)
    if sel.size > 0:
        Ls = Lf[sel]
        r = (mx - Ls) / mx
        m_r = r.mean()
        dpen_dL = np.zeros_like(Lf)
        coef = kappa * 2.0 * m_r
        dpen_dL[sel] += coef * (-1.0 / (sel.size * mx))
        dmdx = coef * (Ls.sum() / (sel.size * mx * mx))
        gLf[idx] += dmdx / idx.size
        gLf += dpen_dL
        pen = kappa * m_r * m_r
    else:
        pen = 0.0
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, tau=None, kappa=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if tau is not None:
        def fg(hh):
            return _fun_grad_flat(hh, tau, kappa)
    else:
        fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _frac_near_max_abs(h, frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _zero_frac(h):
    return float(np.mean(h <= 1e-12))


def _beta_softmax(h, win, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    active = np.asarray(win, dtype=int)
    if active.size == 0:
        return h
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(active.size)
        num, dq, Lf = _num_and_dq(hh)
        mx = Lf.max()
        if mx <= 0:
            return 1e18, np.zeros(active.size)
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        z = beta * Lf / mx
        zmax = z.max()
        ez = np.exp(z - zmax)
        S = ez.sum()
        T = (zmax + np.log(S) - np.log(Lf.size)) / beta
        w = ez / S
        gLf += w / beta
        grad = _backprop(gLf, hh) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) - T
        return val, grad[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zeros=%.3f)" % (bestR, best.size, _zero_frac(best)))
    print("frac near max 0.1/1/5%%: %.4f / %.4f / %.4f"
          % (_frac_near_max_abs(best, 1e-3), _frac_near_max_abs(best, 1e-2),
             _frac_near_max_abs(best, 5e-2)))

    alt_best = None
    altR = -1.0

    # Fill interior zeros (as base)
    h = best.copy()
    idx = np.flatnonzero(h > 0)
    if idx.size > 0:
        lo, hi = int(idx.min()), int(idx.max())
        mean_pos = float(h[h > 0].mean())
        floor = 1e-3 * mean_pos
        seg = h[lo:hi + 1]
        h[lo:hi + 1] = np.maximum(seg, floor)
    h = _rescale(h)
    cur = h
    curR = R_of(h)
    print("after fill: R=%.9f zeros=%.3f" % (curR, _zero_frac(cur)))

    # Extended flat-top ladder: lower tau, larger kappa
    ladder = [(0.6, 300.0), (0.5, 300.0), (0.5, 1000.0),
              (0.4, 1000.0), (0.35, 3000.0)]
    betas = (1e5, 1e6, 1e7)

    for tau, kappa in ladder:
        if time.process_time() >= deadline - 12.0:
            break
        tlim = min(deadline - 11.0, time.process_time() + 6.0)
        h_new = _lbfgs_block(cur, np.arange(cur.size), 600, tlim,
                             tau=tau, kappa=kappa)
        r_new = R_of(h_new)
        print("tau=%.2f kappa=%.0f: R=%.9f zeros=%.3f near 0.1/1/5%%: %.4f/%.4f/%.4f"
              % (tau, kappa, r_new, _zero_frac(h_new),
                 _frac_near_max_abs(h_new, 1e-3), _frac_near_max_abs(h_new, 1e-2),
                 _frac_near_max_abs(h_new, 5e-2)))
        if r_new > altR:
            altR = r_new; alt_best = h_new.copy()
        if r_new > bestR + 1e-15:
            best, bestR = h_new.copy(), r_new
        cur, curR = h_new, r_new

        # peak-window tie polish over knots within 5% of max, expanded 50%
        if time.process_time() < deadline - 6.0:
            win = _peak_window(cur, tol=0.95, pad_frac=0.5, extra=64)
            tlim = min(deadline - 5.5, time.process_time() + 2.0)
            hp = _lbfgs_block(cur, win, 300, tlim, tie=True)
            rp = R_of(hp)
            print("  polish: R=%.9f zeros=%.3f near 5%%: %.4f"
                  % (rp, _zero_frac(hp), _frac_near_max_abs(hp, 5e-2)))
            if rp > altR:
                altR = rp; alt_best = hp.copy()
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
            if rp > curR:
                cur, curR = hp, rp

            # higher-beta softmax passes
            for beta in betas:
                if time.process_time() >= deadline - 4.0:
                    break
                tlim = min(deadline - 3.5, time.process_time() + 2.0)
                hb = _beta_softmax(cur, win, beta, 300, tlim)
                rb = R_of(hb)
                print("  beta=%.0e: R=%.9f zeros=%.3f near 5%%: %.4f"
                      % (beta, rb, _zero_frac(hb), _frac_near_max_abs(hb, 5e-2)))
                if rb > altR:
                    altR = rb; alt_best = hb.copy()
                if rb > bestR + 1e-15:
                    best, bestR = hb.copy(), rb
                if rb > curR:
                    cur, curR = hb, rb

    # final full-array tie polish in last ~5 s
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 5.0)
        hf = _lbfgs_block(cur, np.arange(cur.size), 400, tlim, tie=True)
        rf = R_of(hf)
        print("final full polish: R=%.9f zeros=%.3f near 0.1/1/5%%: %.4f/%.4f/%.4f"
              % (rf, _zero_frac(hf), _frac_near_max_abs(hf, 1e-3),
                 _frac_near_max_abs(hf, 1e-2), _frac_near_max_abs(hf, 5e-2)))
        if rf > altR:
            altR = rf; alt_best = hf.copy()
        if rf > bestR + 1e-15:
            best, bestR = hf.copy(), rf

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d, zeros=%.3f)"
          % (bestR, startR, best.size, _tie_count(best), _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = (lambda hh: _fun_grad_beta(hh, 1e6))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolong_lin(h):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    H = np.empty(2 * n)
    H[0::2] = h
    mid = np.empty(n)
    mid[:-1] = 0.5 * (h[:-1] + h[1:])
    mid[-1] = h[-1]
    H[1::2] = mid
    return H


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    cand = best
    candR = bestR

    # Warm-up polish with soft-max (beta ramp) to land near true optimum
    for beta in (50.0, 200.0, 1000.0, 1e6):
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs(cand, np.arange(cand.size), 200, deadline, beta=beta)
        r = R_of(h)
        if r > candR + 1e-13:
            cand, candR = h, r
    print("warmup R=%.7f" % candR)

    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        # Full polish
        for beta in (200.0, 1e6):
            if time.process_time() >= deadline - 2.0:
                break
            h = _lbfgs(cand, np.arange(cand.size), 300, deadline, beta=beta)
            r = R_of(h)
            if r > candR + 1e-13:
                cand, candR = h, r
                print("  full #%d beta=%.0f R=%.7f" % (it, beta, candR))

        # Peak-window polish
        free = _peak_window(cand)
        for beta in (200.0, 1e6):
            if time.process_time() >= deadline - 2.0:
                break
            hp = _lbfgs(cand, free, 300, deadline, beta=beta)
            rp = R_of(hp)
            if rp > candR + 1e-13:
                cand, candR = hp, rp
                print("  peak #%d beta=%.0f R=%.7f" % (it, beta, rp))

        # Periodic refinement by doubling
        if it % 3 == 0 and cand.size < 900000 and time.process_time() < deadline - 10.0:
            H = _rescale(_prolong_lin(cand))
            hL = _lbfgs(H, np.arange(H.size), 200, deadline, beta=200.0)
            rL = R_of(hL)
            if rL > candR + 1e-13:
                cand, candR = hL, rL
                print("  prolong #%d R=%.7f (N=%d)" % (it, rL, cand.size))
            else:
                # discard larger if no better
                pass

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (candR, cand.size, 100.0 * np.mean(cand <= 0)))

    if candR > start_bestR + 1e-12:
        return cand
    alt = cand if candR > start_bestR - 1e-6 else None
    if alt is None:
        return start_best
    return {"best": start_best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(beta * (Lf - mx))
    Z = np.sum(e)
    Lmax_s = mx + np.log(Z) / beta
    gLf = -dq / num + e / Z
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lmax_s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    """Optimize only the free block of h (others fixed), in linear space >=0."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _smooth_perturb(h, sigma, amp, seed):
    n = h.size
    rng = np.random.RandomState(seed)
    m = max(16, n // 64)
    noise = rng.randn(m)
    xp = np.linspace(0, 1, m)
    xi = np.linspace(0, 1, n)
    p = np.interp(xi, xp, noise)
    return np.clip(h * np.exp(amp * p), 0, None)


def _polish_beta(h, deadline, budget=None):
    best = h.copy()
    bestR = R_of(best)
    for beta in (1e3, 1e4, 1e5, 1e6):
        if time.process_time() >= deadline - 0.5:
            break
        fg = (lambda hh, bb=beta: _fun_grad_beta(hh, bb))
        c = _lbfgs_log(best, 200, deadline, fg=fg)
        r = R_of(c)
        if r > bestR + 1e-14:
            best, bestR = c, r
    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(best, 400, deadline)
        r = R_of(c)
        if r > bestR + 1e-14:
            best, bestR = c, r
    return best, bestR


def _peak_window(h, tol=0.9990, pad_frac=0.5, extra=128):
    """Indices of h whose support overlaps the region where f*f is near max."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size

    alt, altR = None, 0.0
    # Record the starting construction as the alternative candidate.
    alt, altR = best.copy(), bestR

    # --- New idea: block-coordinate descent on the peak window ---
    # The dominant constraint is the max of f*f. Optimizing the whole vector
    # at once fights the peak; restricting the free variables to the window
    # of h that actually contributes to the peak lets the tail relax and
    # find a better numerator/peak tradeoff.
    if time.process_time() < deadline - 6.0:
        wins = _peak_window(best, tol=0.9990, pad_frac=0.5)
        h = _lbfgs_block(best, wins, 400, min(deadline, time.process_time() + 0.20 * budget_seconds))
        r = R_of(h)
        print("window-polish R=%.7f" % r)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r

    # Complement: freeze the peak window, free the rest.
    if time.process_time() < deadline - 6.0:
        wins = _peak_window(best, tol=0.9990, pad_frac=0.5)
        mask = np.ones(best.size, dtype=bool)
        mask[wins] = False
        rest = np.flatnonzero(mask)
        h = _lbfgs_block(best, rest, 400, min(deadline, time.process_time() + 0.15 * budget_seconds))
        r = R_of(h)
        print("tail-polish R=%.7f" % r)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r

    # Beta-ladder polish as before.
    if time.process_time() < deadline - 5.0:
        h, r = _polish_beta(best, min(deadline, time.process_time() + 0.20 * budget_seconds))
        print("beta-polish R=%.7f" % r)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r

    # Coarse-grid escape.
    if time.process_time() < deadline - 15.0:
        for factor in (2, 3):
            if time.process_time() >= deadline - 12.0:
                break
            Nc = max(512, N // factor)
            hc = _coarse(best, Nc)
            hc = _polish_beta(hc, min(deadline, time.process_time() + 0.12 * budget_seconds))[0]
            rc = R_of(hc)
            print("coarse %d R=%.7f" % (Nc, rc))
            if rc > altR:
                alt, altR = hc, rc
            hp = _prolongate(hc, N)
            hp, rp = _polish_beta(hp, min(deadline, time.process_time() + 0.12 * budget_seconds))
            print("prolong %d->%d R=%.7f" % (Nc, N, rp))
            if rp > altR:
                alt, altR = hp, rp
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("prolong wins R=%.7f" % bestR)

    # Perturbation exploration with beta polish.
    specs = [(N / 300.0, 0.05, 11), (N / 300.0, 0.10, 12),
             (N / 80.0, 0.06, 13), (N / 150.0, 0.08, 14)]
    for sigma, amp, seed in specs:
        if time.process_time() >= deadline - 8.0:
            break
        hp = _smooth_perturb(best, max(2.0, sigma), amp, seed)
        hp = _rescale(hp)
        hp, r = _polish_beta(hp, min(deadline, time.process_time() + 0.10 * budget_seconds))
        print("perturb s=%.1f a=%.2f R=%.7f" % (sigma, amp, r))
        if r > altR:
            alt, altR = hp, r
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # Final loop: alternate window-block, sharp, and beta-ladder polish.
    while time.process_time() < deadline - 1.5:
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if time.process_time() >= deadline - 3.0:
            break
        wins = _peak_window(best, tol=0.9990, pad_frac=0.5)
        h = _lbfgs_block(best, wins, 300, min(deadline, time.process_time() + 0.10 * budget_seconds))
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if time.process_time() >= deadline - 3.0:
            break
        h, r = _polish_beta(best, min(deadline, time.process_time() + 0.12 * budget_seconds))
        if r > bestR + 1e-15:
            best, bestR = h, r
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15 and altR > bestR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

