def _peak_window(h, tol=0.9990, pad_frac=0.5, extra=128):
    """Indices of h whose support overlaps the region where f*f is near max."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size

    alt, altR = None, 0.0
    # Record the starting construction as the alternative candidate.
    alt, altR = best.copy(), bestR

    # --- New idea: block-coordinate descent on the peak window ---
    # The dominant constraint is the max of f*f. Optimizing the whole vector
    # at once fights the peak; restricting the free variables to the window
    # of h that actually contributes to the peak lets the tail relax and
    # find a better numerator/peak tradeoff.
    if time.process_time() < deadline - 6.0:
        wins = _peak_window(best, tol=0.9990, pad_frac=0.5)
        h = _lbfgs_block(best, wins, 400, min(deadline, time.process_time() + 0.20 * budget_seconds))
        r = R_of(h)
        print("window-polish R=%.7f" % r)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r

    # Complement: freeze the peak window, free the rest.
    if time.process_time() < deadline - 6.0:
        wins = _peak_window(best, tol=0.9990, pad_frac=0.5)
        mask = np.ones(best.size, dtype=bool)
        mask[wins] = False
        rest = np.flatnonzero(mask)
        h = _lbfgs_block(best, rest, 400, min(deadline, time.process_time() + 0.15 * budget_seconds))
        r = R_of(h)
        print("tail-polish R=%.7f" % r)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r

    # Beta-ladder polish as before.
    if time.process_time() < deadline - 5.0:
        h, r = _polish_beta(best, min(deadline, time.process_time() + 0.20 * budget_seconds))
        print("beta-polish R=%.7f" % r)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r

    # Coarse-grid escape.
    if time.process_time() < deadline - 15.0:
        for factor in (2, 3):
            if time.process_time() >= deadline - 12.0:
                break
            Nc = max(512, N // factor)
            hc = _coarse(best, Nc)
            hc = _polish_beta(hc, min(deadline, time.process_time() + 0.12 * budget_seconds))[0]
            rc = R_of(hc)
            print("coarse %d R=%.7f" % (Nc, rc))
            if rc > altR:
                alt, altR = hc, rc
            hp = _prolongate(hc, N)
            hp, rp = _polish_beta(hp, min(deadline, time.process_time() + 0.12 * budget_seconds))
            print("prolong %d->%d R=%.7f" % (Nc, N, rp))
            if rp > altR:
                alt, altR = hp, rp
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("prolong wins R=%.7f" % bestR)

    # Perturbation exploration with beta polish.
    specs = [(N / 300.0, 0.05, 11), (N / 300.0, 0.10, 12),
             (N / 80.0, 0.06, 13), (N / 150.0, 0.08, 14)]
    for sigma, amp, seed in specs:
        if time.process_time() >= deadline - 8.0:
            break
        hp = _smooth_perturb(best, max(2.0, sigma), amp, seed)
        hp = _rescale(hp)
        hp, r = _polish_beta(hp, min(deadline, time.process_time() + 0.10 * budget_seconds))
        print("perturb s=%.1f a=%.2f R=%.7f" % (sigma, amp, r))
        if r > altR:
            alt, altR = hp, r
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # Final loop: alternate window-block, sharp, and beta-ladder polish.
    while time.process_time() < deadline - 1.5:
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if time.process_time() >= deadline - 3.0:
            break
        wins = _peak_window(best, tol=0.9990, pad_frac=0.5)
        h = _lbfgs_block(best, wins, 300, min(deadline, time.process_time() + 0.10 * budget_seconds))
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
        if time.process_time() >= deadline - 3.0:
            break
        h, r = _polish_beta(best, min(deadline, time.process_time() + 0.12 * budget_seconds))
        if r > bestR + 1e-15:
            best, bestR = h, r
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15 and altR > bestR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _resample_mass(h, Np):
    """Mass-preserving resample of step function h (length N) to length Np."""
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    t = np.linspace(0.0, N, Np + 1)
    cp = np.interp(t, np.arange(N + 1, dtype=float), c)
    hp = (Np / N) * np.diff(cp)
    return np.clip(hp, 0.0, None)


def _perturb(h, rng, scale=0.02):
    """Multiplicative random perturbation of heights."""
    h2 = h * (1.0 + scale * rng.standard_normal(h.size))
    return _rescale(np.clip(h2, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N_base = best.size
    rng = np.random.default_rng(12345)
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # The key idea: instead of a broad resolution sweep (which wastes budget
    # on the wrong N), do a *local* search at the base N first, then try a
    # small set of neighbours, and finally exploit random perturbation /
    # basin-hopping around the current best. Focus budget on the base N since
    # the previous program's sweep found that base N is already near-optimal.
    best_alt = None
    best_altR = -1.0

    def try_improve(h, deadline_local, iters=300):
        nonlocal best, bestR, best_alt, best_altR
        if time.process_time() >= deadline_local - 0.5:
            return False
        ht = _lbfgs_all_pos(h, iters, deadline_local - 0.3, tie=True)
        if time.process_time() < deadline_local - 0.4:
            ht = _peak_ladder(ht, deadline_local - 0.2,
                              pads=(0.08, 0.04), iters=150, tie=True)
        if time.process_time() < deadline_local - 0.2:
            ht = _lbfgs_all_pos(ht, 150, deadline_local - 0.1, tie=False)
        rt = R_of(ht)
        if rt > best_altR:
            best_alt, best_altR = ht.copy(), rt
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            return True
        return False

    # Phase 1: local polish at base N (most budget goes here)
    phase1_end = t0 + budget_seconds * 0.45
    try_improve(best, phase1_end, iters=400)
    print("phase1 R=%.9f" % bestR)

    # Phase 2: neighbouring resolutions (few, near base N)
    phase2_end = t0 + budget_seconds * 0.65
    N_list = [max(1, int(N_base * f)) for f in (0.95, 1.05, 0.9, 1.1)]
    N_list = [n for n in N_list if n != N_base and n <= 1_000_000]
    for Np in N_list:
        if time.process_time() >= phase2_end - 2.0:
            break
        hp = _resample_mass(best, Np)
        if hp.sum() <= 0:
            continue
        hp = _rescale(hp)
        slice_end = min(phase2_end, time.process_time() + 5.0)
        ht = _lbfgs_all_pos(hp, 250, slice_end - 1.0, tie=True)
        if time.process_time() < slice_end - 0.5:
            ht = _lbfgs_all_pos(ht, 100, slice_end - 0.2, tie=False)
        rt = R_of(ht)
        if rt > best_altR:
            best_alt, best_altR = ht.copy(), rt
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("N'=%d ACCEPT R=%.9f" % (Np, bestR))
        else:
            print("N'=%d no gain R=%.9f" % (Np, rt))

    # Phase 3: basin-hopping via random perturbation at base N, always
    # returning to best N to avoid drift to a worse resolution
    phase3_end = t0 + budget_seconds * 0.88
    hop = 0
    while time.process_time() < phase3_end - 1.5:
        hop += 1
        scale = 0.01 + 0.03 * rng.random()
        hp = _perturb(best, rng, scale=scale)
        slice_end = min(phase3_end, time.process_time() + 3.0)
        ht = _lbfgs_all_pos(hp, 200, slice_end - 0.5, tie=True)
        if time.process_time() < slice_end - 0.3:
            ht = _lbfgs_all_pos(ht, 80, slice_end - 0.1, tie=False)
        rt = R_of(ht)
        if rt > best_altR:
            best_alt, best_altR = ht.copy(), rt
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("hop %d scale=%.3f ACCEPT R=%.9f" % (hop, scale, bestR))

    # Final polish
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 2.0:
        h_t = _lbfgs_all_pos(best, 400, fd - 1.0, tie=True)
        if R_of(h_t) > bestR + 1e-15:
            best, bestR = h_t.copy(), R_of(h_t)
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if best_alt is not None and best_alt.size != best.size:
        result["alternative"] = best_alt
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

