    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _resample(h, Nnew):
    """Mass-preserving linear interpolation of cumsum onto a new grid."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if Nnew == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    # old knot positions i/N for i=0..N, new knot positions j/Nnew
    old_x = np.arange(N + 1) / N
    new_x = np.arange(Nnew + 1) / Nnew
    new_c = np.interp(new_x, old_x, c)
    out = np.diff(new_c)
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d, zero_frac=%.3f)" %
          (bestR, best.size, _zero_frac(best)))

    alt_best = None
    alt_bestR = -1.0

    def consider(h_cand, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        h_cand = _rescale(np.clip(h_cand, 0, None))
        r = R_of(h_cand)
        if r > bestR + 1e-14:
            best, bestR, origin = h_cand.copy(), r, tag
            print("  %s NEW BEST R=%.9f" % (tag, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = h_cand.copy(), r
        return r

    N0 = start_best.size
    ratios = [(3, 2), (4, 3)]
    n_ratios = len(ratios)
    per_ratio = (deadline - time.process_time()) / n_ratios

    for ri, (p, q) in enumerate(ratios):
        r_start = time.process_time()
        r_deadline = min(deadline, r_start + per_ratio)
        if r_start >= deadline - 2.0:
            break
        Nnew = int(round(N0 * p / q))
        Nnew = max(16, Nnew)
        h_lift = _resample(start_best, Nnew)
        h_lift = _rescale(h_lift)
        r_lift = R_of(h_lift)
        print("ratio %d:%d N'=%d lift R=%.9f (start %.9f, delta %+.2e)" %
              (p, q, Nnew, r_lift, start_bestR, r_lift - start_bestR))
        consider(h_lift, 'lift%d:%d' % (p, q))

        cur = h_lift.copy()
        curR = r_lift

        def stage(fn, tag):
            nonlocal cur, curR
            if time.process_time() >= r_deadline - 0.5:
                return
            h_new = fn(cur)
            r_new = R_of(h_new)
            if r_new > curR + 1e-14:
                cur, curR = h_new, r_new
                print("  %s ACCEPT R=%.9f" % (tag, curR))
            else:
                print("  %s no gain (%.9f)" % (tag, r_new))
            consider(h_new, tag)

        # two full-vector tie-aware passes, 6s each
        for k in range(2):
            if time.process_time() >= r_deadline - 0.5:
                break
            dl = min(r_deadline - 0.3, time.process_time() + 6.0)
            stage(lambda hh, dl=dl: _lbfgs_all_pos(hh, 300, dl, beta=0.0),
                  'full%d' % k)

        # beta ladder
        for beta in [1e4, 1e6, 1e7]:
            if time.process_time() >= r_deadline - 0.5:
                break
            dl = min(r_deadline - 0.3, time.process_time() + 4.0)
            stage(lambda hh, dl=dl, b=beta: _lbfgs_all_pos(hh, 300, dl, beta=b),
                  'beta%g' % beta)

        # peak-window polishes
        for pad in [0.30, 0.20, 0.12, 0.08, 0.05]:
            if time.process_time() >= r_deadline - 0.5:
                break
            dl = min(r_deadline - 0.3, time.process_time() + 3.0)
            win = _peak_window(cur, pad_frac=pad, extra=64)
            stage(lambda hh, dl=dl, w=win: _lbfgs_block(hh, w, 400, dl, beta=1e6),
                  'pad%.2f' % pad)

        # final full tie polish with remaining time in this ratio slot
        if time.process_time() < r_deadline - 0.5:
            stage(lambda hh: _lbfgs_all_pos(hh, 300, r_deadline - 0.3, beta=0.0),
                  'finalfull')

        print("ratio %d:%d done R=%.9f (zero_frac=%.3f, max/mean=%.2f)" %
              (p, q, curR, _zero_frac(cur),
               float(cur.max() / max(1e-30, cur.mean()))))

    # final full tie polish on best with whatever time remains
    if time.process_time() < deadline - 0.5:
        h_fin = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
        consider(h_fin, 'finalpol')

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = max(1, int(np.ceil(q * n)))
    k = min(k, n)
    # indices of the k largest knots
    idx = np.argpartition(Lf, n - k)[n - k:]
    cvar = float(Lf[idx].mean())
    if cvar <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    gLf[idx] += 1.0 / (idx.size * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False, cvar=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if cvar > 0:
        fg = (lambda hh: _fun_grad_cvar(hh, cvar))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _cvar_val(h, q):
    Lf = _knots(h)
    n = Lf.size
    k = max(1, int(np.ceil(q * n)))
    k = min(k, n)
    idx = np.argpartition(Lf, n - k)[n - k:]
    return float(Lf[idx].mean())


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%) before: %.4f, (5%%): %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 5e-2)))

    # ---- H22: CVaR ladder on the top band ----
    alt_best = None
    altR = -1.0
    q_list = [0.10, 0.05, 0.03, 0.02]
    for q in q_list:
        if time.process_time() >= deadline - 1.0:
            break
        tlim = min(deadline - 0.5, time.process_time() + 10.0)
        hc = _lbfgs_block(best, np.arange(best.size), 400, tlim, cvar=q)
        rc = R_of(hc)
        cv = _cvar_val(hc, q)
        fr5 = _frac_near_max(hc, 5e-2)
        print("q=%.2f cvar: R=%.12f cvar=%.6f frac5=%.4f" % (q, rc, cv, fr5))
        if rc > altR:
            altR = rc; alt_best = hc.copy()
        if rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc

        # full tie polish
        if time.process_time() < deadline - 1.0:
            pol = _lbfgs_block(hc, np.arange(hc.size), 200,
                               min(deadline - 0.5, time.process_time() + 4.0),
                               tie=True)
            rp = R_of(pol)
            print("  tie polish R=%.12f frac5=%.4f" % (rp, _frac_near_max(pol, 5e-2)))
            if rp > altR:
                altR = rp; alt_best = pol.copy()
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

        # peak-window polishes
        for pad in (0.08, 0.04):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(hc, pad_frac=pad, extra=96)
            ht = _lbfgs_block(hc, win, 300,
                              min(deadline - 0.5, time.process_time() + 3.0), tie=True)
            r = R_of(ht)
            if r > altR:
                altR = r; alt_best = ht.copy()
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r

    print("frac near max (5%%) after: %.4f" % _frac_near_max(best, 5e-2))

    # safety net: tie polish on best
    if time.process_time() < deadline - 0.5:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.3, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
