        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_staircase(h):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in (1, 2, 3, 4, 5, 8, 16, 32, 64):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-9:
            return c, p
    return None, 1


def _gauge(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    return h / h.sum()


def _refine(h, deadline, rounds=8):
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    allc = np.arange(n)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        pol = _lbfgs_block(best, allc, 400,
                           min(deadline - 0.5, time.process_time() + 6.0), tie=True)
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        for beta in (30.0, 100.0, 300.0, 1000.0):
            if time.process_time() >= deadline - 0.6:
                break
            pb = _lbfgs_block(best, allc, 250,
                             min(deadline - 0.4, time.process_time() + 4.0),
                             beta=beta)
            rb = R_of(pb)
            if rb > bestR:
                best, bestR = pb, rb
        for pad in (0.15, 0.08, 0.04, 0.02):
            if time.process_time() >= deadline - 0.6:
                break
            win = _peak_window(best, pad_frac=pad, extra=64)
            pw = _lbfgs_block(best, win, 300,
                             min(deadline - 0.4, time.process_time() + 4.0), tie=True)
            rw = R_of(pw)
            if rw > bestR:
                best, bestR = pw, rw
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: staircase-aware coarse optimization ----
    c, p = _detect_staircase(best)
    if c is not None and p > 1:
        print("staircase p=%d m=%d" % (p, c.size))
        work = _gauge(np.repeat(c, p))
        work, workR = _refine(work, deadline - 1.0, rounds=4)
        if workR > bestR + 1e-15:
            best, bestR = work, workR
            print("staircase refine ACCEPT R=%.9f" % bestR)

    # ---- Phase 2: fine-level refine on full array ----
    best2, bestR2 = _refine(best, deadline, rounds=10)
    if bestR2 > bestR:
        best, bestR = best2, bestR2
        print("refine ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))

    # ---- Phase 3: small random perturbation + refine (escape local opt) ----
    rng = np.random.default_rng(int(t0 * 1000) & 0xffff)
    while time.process_time() < deadline - 6.0:
        n = best.size
        # perturb a random subset of heights slightly
        trial = best.copy()
        kpert = min(n, max(16, n // 200))
        idx = rng.choice(n, size=kpert, replace=False)
        scale = 1.0 + 0.02 * rng.standard_normal(kpert)
        trial[idx] = np.clip(trial[idx] * scale, 0, None)
        trial = _rescale(trial)
        tr, trR = _refine(trial, min(deadline, time.process_time() + 5.0),
                          rounds=3)
        if trR > bestR + 1e-15:
            best, bestR = tr, trR
            print("perturb ACCEPT R=%.9f" % bestR)

    # ---- Phase 4: final full tie polish ----
    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 2.0:
        h_t = _lbfgs_block(best, np.arange(best.size), 800, fd - 0.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t, r_t
            print("FINAL ACCEPT R=%.9f" % bestR)

    f01, f1, f5 = _nearmax_fracs(best)
    print("final R=%.9f (start %.9f, N=%d, ties=%d, near=%.3f/%.3f/%.3f)"
          % (bestR, startR, best.size, _tie_count(best), f01, f1, f5))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline,
                        beta=beta, tie=tie)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h, Nnew):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0:
        return np.ones(Nnew)
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h))) / s
    u = np.linspace(0.0, 1.0, N + 1)
    v = np.linspace(0.0, 1.0, Nnew + 1)
    newC = np.interp(v, u, C)
    out = np.diff(newC)
    return _rescale(np.clip(out, 0, None))


def _warp(h, gamma):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0:
        return h
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h))) / s
    u = np.linspace(0.0, 1.0, N + 1)
    v = u ** gamma
    newC = np.interp(v, u, C)
    out = np.diff(newC)
    return _rescale(np.clip(out, 0, None))


def _peak_ladder(h, deadline, pads=(0.12, 0.06, 0.03), iters=300):
    r0 = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > r0 + 1e-14:
            h, r0 = ht, r
    return h, r0


def _sharpen(h, bestR, deadline):
    for beta in (1e6, 1e7, 0.0):
        if time.process_time() >= deadline - 0.3:
            break
        ht = _lbfgs_all(h, 200, deadline, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            h, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.3:
        h, bestR = _peak_ladder(h, deadline)
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_best, alt_bestR = None, 0.0

    # ---- Primary idea: upsample 2x early, with multiple warp attempts
    # at the higher resolution. This gives the optimiser more room to
    # resolve the peak plateau, which is where the gain lives. ----
    if time.process_time() < deadline - 3.0:
        hu = _prolong(best, best.size * 2)
        ru = R_of(hu)
        slice_end = min(deadline - 1.0,
                        time.process_time() + budget_seconds * 0.18)
        hu, ru = _sharpen(hu, ru, slice_end)
        if time.process_time() < deadline - 1.0:
            slice_end = min(deadline - 1.0,
                            time.process_time() + budget_seconds * 0.10)
            hu, ru = _sharpen(hu, ru, slice_end)
        if ru > bestR + 1e-13:
            best, bestR = hu.copy(), ru
        alt_best, alt_bestR = hu, ru
        print("upsampled R=%.7f (N=%d)" % (ru, hu.size))

    # ---- Warp-based basin escape on the upsampled construction ----
    for gamma in (0.98, 1.02, 0.95, 1.05, 0.92, 1.08):
        if time.process_time() >= deadline - 2.5:
            break
        hw = _warp(best, gamma)
        rw = R_of(hw)
        slice_end = min(deadline - 1.0,
                        time.process_time() + budget_seconds * 0.07)
        hw, rw = _sharpen(hw, rw, slice_end)
        if rw > bestR + 1e-13:
            best, bestR = hw.copy(), rw
        if alt_best is None or rw > alt_bestR:
            alt_best, alt_bestR = hw, rw
    print("warp R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Upsample again to 4x and refine (bigger N, more resolution) ----
    if time.process_time() < deadline - 3.0 and best.size < 800000:
        hu = _prolong(best, min(best.size * 2, 999000))
        ru = R_of(hu)
        slice_end = min(deadline - 0.8,
                        time.process_time() + budget_seconds * 0.25)
        hu, ru = _sharpen(hu, ru, slice_end)
        if ru > bestR + 1e-13:
            best, bestR = hu.copy(), ru
        if alt_best is None or ru > alt_bestR:
            alt_best, alt_bestR = hu, ru
        print("upsample2 R=%.7f (N=%d)" % (ru, hu.size))

    # final polish
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 3000, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt_best is not None:
        print("alt R=%.7f (N=%d)" % (alt_bestR, alt_best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_best is not None and alt_bestR > start_bestR - 0.05:
        out["alternative"] = alt_best
    return out

