        h, bestR = _peak_ladder(h, deadline)
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_best, alt_bestR = None, 0.0

    # ---- Primary idea: upsample 2x early, with multiple warp attempts
    # at the higher resolution. This gives the optimiser more room to
    # resolve the peak plateau, which is where the gain lives. ----
    if time.process_time() < deadline - 3.0:
        hu = _prolong(best, best.size * 2)
        ru = R_of(hu)
        slice_end = min(deadline - 1.0,
                        time.process_time() + budget_seconds * 0.18)
        hu, ru = _sharpen(hu, ru, slice_end)
        if time.process_time() < deadline - 1.0:
            slice_end = min(deadline - 1.0,
                            time.process_time() + budget_seconds * 0.10)
            hu, ru = _sharpen(hu, ru, slice_end)
        if ru > bestR + 1e-13:
            best, bestR = hu.copy(), ru
        alt_best, alt_bestR = hu, ru
        print("upsampled R=%.7f (N=%d)" % (ru, hu.size))

    # ---- Warp-based basin escape on the upsampled construction ----
    for gamma in (0.98, 1.02, 0.95, 1.05, 0.92, 1.08):
        if time.process_time() >= deadline - 2.5:
            break
        hw = _warp(best, gamma)
        rw = R_of(hw)
        slice_end = min(deadline - 1.0,
                        time.process_time() + budget_seconds * 0.07)
        hw, rw = _sharpen(hw, rw, slice_end)
        if rw > bestR + 1e-13:
            best, bestR = hw.copy(), rw
        if alt_best is None or rw > alt_bestR:
            alt_best, alt_bestR = hw, rw
    print("warp R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Upsample again to 4x and refine (bigger N, more resolution) ----
    if time.process_time() < deadline - 3.0 and best.size < 800000:
        hu = _prolong(best, min(best.size * 2, 999000))
        ru = R_of(hu)
        slice_end = min(deadline - 0.8,
                        time.process_time() + budget_seconds * 0.25)
        hu, ru = _sharpen(hu, ru, slice_end)
        if ru > bestR + 1e-13:
            best, bestR = hu.copy(), ru
        if alt_best is None or ru > alt_bestR:
            alt_best, alt_bestR = hu, ru
        print("upsample2 R=%.7f (N=%d)" % (ru, hu.size))

    # final polish
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 3000, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt_best is not None:
        print("alt R=%.7f (N=%d)" % (alt_bestR, alt_best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_best is not None and alt_bestR > start_bestR - 0.05:
        out["alternative"] = alt_best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _detect_staircase(h, plist=(64, 32, 16, 8, 4, 2, 1)):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in plist:
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-10:
            return c, p
    return None, 1


# ------------------------------------------------------------------
# Coarse objective machinery (optimise coarse profile c directly).
# ------------------------------------------------------------------

def _coarse_knots(c):
    return np.concatenate(([0.0], np.convolve(c, c), [0.0]))


def _R_coarse(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = _coarse_knots(c)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _coarse_grad_log(c):
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    Lf = _coarse_knots(c)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    if num <= 0:
        return 1e18, np.zeros(c.size)
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(c.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    gL = gLf[1:-1]
    if c.size > 1500:
        grad = 2.0 * fftconvolve(gL, c[::-1], mode='valid')[:c.size]
    else:
        grad = 2.0 * np.correlate(gL, c, mode='valid')[:c.size]
    grad = grad + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _coarse_lbfgs(c0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return c0
    c0 = np.clip(c0, 1e-12, None)
    x0 = np.log(c0)

    def f(x):
        c = np.exp(x)
        val, g = _coarse_grad_log(c)
        return val, g * c

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-np.inf, np.log(1e-6))] * c0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-18, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.exp(np.clip(res.x, -30.0, np.log(1e-6)))


def _propose(c, rng):
    m = c.size
    u = np.arange(m, dtype=float) / m
    kind = rng.integers(0, 4)
    s = np.exp(rng.uniform(np.log(0.01), np.log(0.4)))
    cp = c.copy()
    if kind == 0:
        E = np.zeros(m)
        for k in range(1, 5):
            a = rng.normal()
            phi = rng.uniform(0, 2 * np.pi)
            E += a * np.cos(2 * np.pi * k * u + phi)
        mE = np.max(np.abs(E))
        if mE > 0:
            E /= mE
        cp = c * (1.0 + s * E)
    elif kind == 1:
        nb = rng.integers(8, 65)
        edges = np.sort(rng.choice(m + 1, size=min(nb + 1, m + 1), replace=False))
        for i in range(len(edges) - 1):
            lo, hi = edges[i], edges[i + 1]
            if hi <= lo:
                continue
            f = np.exp(rng.uniform(np.log(1 / 1.5), np.log(1.5)))
            cp[lo:hi] *= f
    elif kind == 2:
        frac = rng.uniform(0.03, 0.05)
        k = max(1, int(frac * m))
        idx = rng.choice(m, size=min(k, m), replace=False)
        f = np.exp(rng.uniform(np.log(0.5), np.log(2.0), size=len(idx)))
        cp[idx] *= f
    else:
        frac = rng.uniform(0.01, 0.03)
        k = max(1, int(frac * m))
        idx = rng.choice(m, size=min(k, m), replace=False)
        cp[idx] = 0.0
    cp = np.clip(cp, 0.0, None)
    if cp.sum() <= 0:
        cp = c.copy()
    return cp


def _coarse_search(c_start, deadline, rng, reserve=3.0):
    c_work = c_start.copy()
    r_work = _R_coarse(c_work)
    c_work = _coarse_lbfgs(c_work, 400, deadline - reserve)
    r_new = _R_coarse(c_work)
    if r_new > r_work:
        r_work = r_new
    n_imp = 0
    n_res = 0
    while time.process_time() < deadline - reserve:
        n_res += 1
        cp = _propose(c_work, rng)
        iters = int(rng.integers(60, 151))
        c_new = _coarse_lbfgs(cp, iters, deadline - reserve + 1.0)
        r_new = _R_coarse(c_new)
        if r_new > r_work + 1e-16:
            c_work = c_new
            r_work = r_new
            n_imp += 1
    return c_work, r_work, n_res, n_imp


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    rng = np.random.default_rng(1234567)

    # Detect staircase; if present, work on the coarse profile.
    c_best, p_best = _detect_staircase(best)
    if c_best is None:
        p_best = 1
        c_best = best.copy()

    alt = None
    if p_best >= 2:
        r_coarse = _R_coarse(c_best)
        print("staircase p=%d m=%d R_coarse=%.12f R_full=%.12f"
              % (p_best, c_best.size, r_coarse, bestR))
        c_work, r_work, n_res, n_imp = _coarse_search(
            c_best, deadline, rng, reserve=4.0)
        print("coarse done restarts=%d improvements=%d R_coarse=%.12f"
              % (n_res, n_imp, r_work))

        h_rec = np.repeat(c_work, p_best)
        h_rec = _rescale(h_rec)
        r_rec = R_of(h_rec)
        print("reconstruct R_full=%.12f (coarse %.12f)" % (r_rec, r_work))
        polish_end = t0 + budget_seconds * 0.97
        for pad in (0.12, 0.08, 0.05, 0.03):
            if time.process_time() >= polish_end - 1.0:
                break
            win = _peak_window(h_rec, pad_frac=pad, extra=128)
            ht = _lbfgs_block(h_rec, win, 250,
                              min(polish_end - 0.5,
                                  time.process_time() + 4.0), beta=1e7)
            rt = R_of(ht)
            if rt > r_rec + 1e-15:
                h_rec = ht
                r_rec = rt
        ht = _lbfgs_block(h_rec, np.arange(h_rec.size), 400,
                          polish_end - 0.5, tie=True)
        rt = R_of(ht)
        if rt > r_rec + 1e-15:
            h_rec = ht
            r_rec = rt
        print("polished R_full=%.12f" % r_rec)
        alt = h_rec
        if r_rec > bestR + 1e-15:
            best = h_rec.copy()
            bestR = r_rec
            print("COARSE ACCEPT R=%.12f" % bestR)
        else:
            print("coarse no gain (%.12f vs %.12f)" % (r_rec, bestR))
    else:
        print("no staircase (p=%d), running peak ladder only" % p_best)

    # Peak-ladder polish on best.
    peak_end = t0 + budget_seconds * 0.99
    if time.process_time() < peak_end - 2.0:
        for pad in (0.06, 0.04, 0.02, 0.01):
            if time.process_time() >= peak_end - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 300,
                              min(peak_end - 0.5,
                                  time.process_time() + 4.0), tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak ladder ACCEPT R=%.12f" % bestR)

    f01, f1, f5 = _nearmax_fracs(best)
    print("final R=%.9f (start %.9f, N=%d, ties=%d, near 0.1/1/5=%.3f/%.3f/%.3f)"
          % (bestR, startR, best.size, _tie_count(best), f01, f1, f5))

    result = {"best": best}
    if alt is not None and R_of(alt) > startR + 1e-14:
        pass
    elif alt is not None:
        result["alternative"] = alt
    return result

