def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _down(h, n2):
    """Mass-preserving block-sum downsample to n2 steps."""
    h = np.asarray(h, dtype=float)
    n = h.size
    if n2 >= n:
        return h.copy()
    edges = np.linspace(0, n, n2 + 1)
    out = np.zeros(n2)
    for i in range(n2):
        a = edges[i]; b = edges[i + 1]
        ia = int(np.floor(a)); ib = int(np.floor(b))
        if ib <= ia:
            out[i] = h[ia] * (b - a)
        else:
            out[i] = h[ia] * (ia + 1 - a)
            if ib > ia + 1:
                out[i] += h[ia + 1:ib].sum()
            out[i] += h[ib] * (b - ib)
    return out


def _up(h, n2):
    """Mass-preserving linear interpolation of cumulative mass to n2 steps."""
    h = np.asarray(h, dtype=float)
    n = h.size
    if n2 <= n:
        return _rescale(h.copy())
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n2)
    xs = np.linspace(0.0, n, n2 + 1)
    cs = np.interp(xs, np.arange(n + 1), c)
    out = np.diff(cs)
    out = np.clip(out, 0, None)
    return _rescale(out)


def _near_frac(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (np.mean(Lf >= 0.999 * mx),
            np.mean(Lf >= 0.99 * mx),
            np.mean(Lf >= 0.95 * mx))


def _round_loop(h, deadline, caps, betas, pad_fracs, max_rounds=3):
    best = _rescale(h)
    bestR = R_of(best)
    for rnd in range(max_rounds):
        if time.process_time() >= deadline - 0.5:
            break
        startR = bestR
        # full tie
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.4, time.process_time() + caps[0]))
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        # beta passes
        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            pol = _lbfgs_block(best, np.arange(best.size), 200,
                               min(deadline - 0.4, time.process_time() + caps[1]),
                               beta=beta)
            rp = R_of(pol)
            if rp > bestR:
                best, bestR = pol, rp
        # peak-window polishes
        for pf in pad_fracs:
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=pf, extra=64)
            pol = _lbfgs_block(best, win, 200,
                               min(deadline - 0.4, time.process_time() + caps[2]))
            rp = R_of(pol)
            if rp > bestR:
                best, bestR = pol, rp
        if bestR - startR < 1e-9:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.92 * budget_seconds

    if start is not None:
        base = _rescale(np.asarray(start, dtype=float))
    else:
        N = 8192
        i = np.arange(N, dtype=float)
        base = np.sqrt(N) * (np.sqrt(i + 1) - np.sqrt(i))
        base = _rescale(base)
    baseR = R_of(base)
    print(f"[init] R={baseR:.6f} N={base.size} t={time.process_time()-t0:.2f}")

    best = base.copy()
    bestR = baseR

    def report(tag, h, r):
        a, b, c = _near_frac(h)
        print(f"[{tag}] R={r:.7f} N={h.size} "
              f"frac(0.1/1/5%)={a*100:.2f}/{b*100:.2f}/{c*100:.2f} "
              f"t={time.process_time()-t0:.2f}")

    betas = (1e3, 1e4, 1e5, 1e6)
    pad_fracs = (0.3, 0.2, 0.1)

    for n0 in (1024, 2048):
        if time.process_time() >= deadline - 2.0:
            break
        h = _down(base, n0)
        h = _rescale(h)
        r = R_of(h)
        report(f"down{n0}", h, r)
        if r > bestR:
            best, bestR = h.copy(), r
        h, r = _round_loop(h, deadline, caps=(3.0, 3.0, 2.0),
                           betas=betas, pad_fracs=pad_fracs, max_rounds=3)
        report(f"coarse{n0}", h, r)
        if r > bestR:
            best, bestR = h.copy(), r

        n = n0
        while n < 16384:
            if time.process_time() >= deadline - 2.0:
                break
            n2 = 2 * n
            if n2 > 16384:
                n2 = 16384
            if n2 == 32768:
                if time.process_time() > deadline - 12.0:
                    break
            h = _up(h, n2)
            r = R_of(h)
            report(f"up{n2}", h, r)
            if r > bestR:
                best, bestR = h.copy(), r
            h, r = _round_loop(h, deadline, caps=(2.5, 2.5, 1.5),
                               betas=betas, pad_fracs=pad_fracs, max_rounds=3)
            report(f"lvl{n2}", h, r)
            if r > bestR:
                best, bestR = h.copy(), r
            n = n2

        # optional 32768 if time remains
        if n == 16384 and time.process_time() < deadline - 12.0:
            h = _up(h, 32768)
            r = R_of(h)
            report("up32768", h, r)
            if r > bestR:
                best, bestR = h.copy(), r
            h, r = _round_loop(h, deadline, caps=(2.0, 2.0, 1.0),
                               betas=betas, pad_fracs=pad_fracs, max_rounds=2)
            report("lvl32768", h, r)
            if r > bestR:
                best, bestR = h.copy(), r

    # Final polish at best N
    while time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.4, time.process_time() + 4.0))
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        else:
            win = _peak_window(best, tol=0.9999, pad_frac=0.1, extra=64)
            pol2 = _lbfgs_block(best, win, 150,
                                min(deadline - 0.4, time.process_time() + 2.0))
            rp2 = R_of(pol2)
            if rp2 > bestR:
                best, bestR = pol2, rp2
        print(f"[full] R={rp:.7f} best={bestR:.7f} t={time.process_time()-t0:.2f}")

    best = _rescale(best)
    Rf = R_of(best)
    print(f"[final] R={Rf:.6f} N={best.size} t={time.process_time()-t0:.2f}")

    if Rf >= baseR:
        return best
    return {"best": base, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, q):
    """CVaR surrogate: raise the mean of the top-q fraction of knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = Lf.size
    k = max(2, int(np.ceil(q * m)))
    k = min(k, m)
    thr = np.partition(Lf, m - k)[m - k]
    S = np.flatnonzero(Lf >= thr)
    if S.size == 0:
        return _fun_grad(h)
    sm = Lf[S].mean()
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[S] += 1.0 / (S.size * sm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, cvar_q=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if cvar_q is not None:
        fg = (lambda hh: _fun_grad_cvar(hh, cvar_q))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _nearmax_fracs(h):
    return (_nearmax_frac(h, 0.999), _nearmax_frac(h, 0.99), _nearmax_frac(h, 0.95))


def _deficit_free(h, frac=0.15):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(h.size)
    gLf = (M - 2.0 * Lf) / M
    s = np.abs(_backprop(gLf, h))
    N = h.size
    k = max(1, int(frac * N))
    if k >= N:
        return np.arange(N)
    idx = np.argpartition(-s, k - 1)[:k]
    return np.sort(idx)


def _interlace_32(c, n_target, rng):
    m = c.size
    if m < 2:
        return np.repeat(c, max(1, n_target // max(1, m)))[:n_target]
    cm = np.cumsum(c)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    jitter = np.exp(0.02 * rng.standard_normal(n_target))
    t = np.clip(t * jitter, 1e-9, 1 - 1e-9)
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, m - 1)
    return c[idx].astype(float)


def _fold_back(h_fine, n_target):
    n = h_fine.size
    if n == n_target:
        return h_fine.copy()
    cm = np.cumsum(h_fine)
    if cm[-1] <= 0:
        return np.zeros(n_target)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, n - 1)
    return h_fine[idx].astype(float)


def _lift_round(member, rng, deadline):
    N = member.size
    if N % 2 == 0 and N >= 4:
        c = member[0::2].copy()
    else:
        c = member[::2].copy()
    c = _polish_ladder(c, deadline, betas=(1e6, 1e7, 0.0), iters=200)
    c = _peak_ladder(c, deadline, pads=(0.20, 0.12, 0.08), iters=250)
    h_fine = _interlace_32(c, 3 * c.size // 2, rng)
    h_fine = _rescale(h_fine)
    h_fine = _polish_ladder(h_fine, deadline, betas=(1e7, 1e8, 0.0), iters=200)
    h_back = _fold_back(h_fine, N)
    h_back = _rescale(h_back)
    h_back = _polish_ladder(h_back, deadline, betas=(1e7, 1e8, 0.0), iters=250)
    h_back = _peak_ladder(h_back, deadline, pads=(0.08, 0.05), iters=250)
    return h_back


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase A: half-resolution quotient polish (kept from base) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.15
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Experiment: CVaR shoulder-raising ladder ----
    start_nm = _nearmax_fracs(best)
    print("start nearmax 0.1%%/1%%/5%% = %.4f/%.4f/%.4f" % start_nm)
    cvar_deadline = t0 + budget_seconds * 0.55
    for q in (0.5, 0.3, 0.2, 0.1, 0.05, 0.02):
        if time.process_time() >= cvar_deadline - 1.0:
            break
        rung_dl = min(cvar_deadline, time.process_time() + 5.0)
        ht = _lbfgs_all_pos(best, 400, rung_dl, cvar_q=q)
        r = R_of(ht)
        nm = _nearmax_fracs(ht)
        improved = r > bestR + 1e-14
        if improved:
            best, bestR = ht.copy(), r
            print("CVAR q=%.2f exact R=%.9f NEW BEST nearmax=%.4f/%.4f/%.4f"
                  % (q, r, nm[0], nm[1], nm[2]))
        else:
            print("CVAR q=%.2f exact R=%.9f (best %.9f) nearmax=%.4f/%.4f/%.4f"
                  % (q, r, bestR, nm[0], nm[1], nm[2]))

    # ---- Phase D: deficit-sensitivity rounds (kept from base) ----
    deficit_deadline = deadline - 8.0
    for rnd in range(3):
        if time.process_time() >= deficit_deadline - 2.0:
            break
        free = _deficit_free(best, frac=0.15)
        if free.size == 0:
            print("deficit round=%d: no free cells" % rnd)
            continue
        ht = _lbfgs_block(best, free, 300, deficit_deadline, beta=1e6)
        ht = _lbfgs_block(ht, free, 300, deficit_deadline, beta=0.0)
        ht = _peak_ladder(ht, deficit_deadline, pads=(0.08, 0.05), iters=250)
        r = R_of(ht)
        improved = offer(ht, 'deficit_%d' % rnd)
        print("deficit round=%d freed=%d R=%.9f (best %.9f) improved=%s"
              % (rnd, free.size, r, bestR, improved))

    # ---- Phase B: high-beta sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=300)
        offer(ht, 'sharp')

    # ---- Phase P: pool keyed on argmax position ----
    pool = []

    def pool_insert(h, r):
        if h is None or h.size != best.size or h.sum() <= 0:
            return
        af = _argmax_frac(h)
        for i, (rr, hh) in enumerate(pool):
            if abs(_argmax_frac(hh) - af) < 0.005:
                if r > rr + 1e-14:
                    pool.pop(i)
                    pool.append((r, h.copy()))
                pool.sort(key=lambda x: -x[0])
                return
        pool.append((r, h.copy()))
        pool.sort(key=lambda x: -x[0])
        while len(pool) > 5:
            pool.pop()

    pool_insert(best, bestR)

    # ---- Seed pool with four variants ----
    seed_deadline = deadline - 20.0

    def _roundtrip_from_fine(h_fine, N, dl):
        h_back = _fold_back(h_fine, N)
        h_back = _rescale(h_back)
        h_back = _polish_ladder(h_back, dl, betas=(1e7, 1e8, 0.0), iters=250)
        h_back = _peak_ladder(h_back, dl, pads=(0.08, 0.05), iters=250)
        return h_back

    N = best.size

    if time.process_time() < seed_deadline - 4.0 and N >= 4:
        c = best[0::2].copy()
        c = _polish_ladder(c, seed_deadline - 3.0, betas=(1e6, 1e7, 0.0), iters=200)
        h_fine = _interlace_32(c, 3 * c.size // 2, rng)
        h_fine = _rescale(h_fine)
        h_fine = _polish_ladder(h_fine, seed_deadline - 2.0, betas=(1e7, 0.0), iters=200)
        h1 = _roundtrip_from_fine(h_fine, N, seed_deadline - 1.0)
        pool_insert(h1, R_of(h1))
        offer(h1, 'v1')

    if time.process_time() < seed_deadline - 4.0 and N >= 4:
        c = best[1::2].copy()
        c = _polish_ladder(c, seed_deadline - 3.0, betas=(1e6, 1e7, 0.0), iters=200)
        h_fine = _interlace_32(c, 3 * c.size // 2, rng)
        h_fine = _rescale(h_fine)
        h_fine = _polish_ladder(h_fine, seed_deadline - 2.0, betas=(1e7, 0.0), iters=200)
        h2 = _roundtrip_from_fine(h_fine, N, seed_deadline - 1.0)
        pool_insert(h2, R_of(h2))
        offer(h2, 'v2')

    if time.process_time() < seed_deadline - 4.0:
        w = np.exp(0.15 * rng.standard_normal(2 * N))
        h_fine = np.repeat(best, 2) * w
        h_fine = _rescale(h_fine)
        h_fine = _polish_ladder(h_fine, seed_deadline - 2.0, betas=(1e7, 0.0), iters=200)
        h3 = _roundtrip_from_fine(h_fine, N, seed_deadline - 1.0)
        pool_insert(h3, R_of(h3))
        offer(h3, 'v3')

    if time.process_time() < seed_deadline - 4.0:
        h4 = best.copy()
        zeros = np.flatnonzero(h4 <= 0)
        if zeros.size > 0:
            k = max(1, int(0.005 * zeros.size))
            sel = rng.choice(zeros, size=min(k, zeros.size), replace=False)
            mean_h = h4[h4 > 0].mean() if np.any(h4 > 0) else 1.0
            h4[sel] = 1e-2 * mean_h
            h4 = _rescale(h4)
            h4 = _polish_ladder(h4, seed_deadline - 2.0, betas=(1e7, 0.0), iters=200)
            h4 = _peak_ladder(h4, seed_deadline - 1.0, pads=(0.08, 0.05), iters=200)
            pool_insert(h4, R_of(h4))
            offer(h4, 'v4')

    print("pool seeded size=%d" % len(pool))

    # ---- Phase Q: round-robin lift rounds over pool ----
    pool_deadline = deadline - 4.0
    rounds = 0
    while time.process_time() < pool_deadline - 2.0 and len(pool) > 0:
        rounds += 1
        order = sorted(range(len(pool)), key=lambda i: -pool[i][0])
        progressed = False
        for i in order:
            if time.process_time() >= pool_deadline - 2.0:
                break
            if i >= len(pool):
                continue
            rr, hh = pool[i]
            cand = _lift_round(hh, rng, pool_deadline)
            rc = R_of(cand)
            if rc > bestR + 1e-14:
                best, bestR = cand.copy(), rc
                print("NEW BEST (pool) R=%.9f round=%d" % (bestR, rounds))
                progressed = True
            if rc > bestR - 5e-6:
                pool_insert(cand, rc)
                progressed = True
        if not progressed and time.process_time() < pool_deadline - 3.0:
            cand = _lift_round(best, rng, pool_deadline)
            rc = R_of(cand)
            if rc > bestR + 1e-14:
                best, bestR = cand.copy(), rc
                print("NEW BEST (pool-best) R=%.9f round=%d" % (bestR, rounds))
            if rc > bestR - 5e-6:
                pool_insert(cand, rc)

    print("pool rounds=%d pool_size=%d" % (rounds, len(pool)))

    # ---- Final polish on best ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 1e10, 0.0), iters=300)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht.copy(), R_of(ht)
        print("NEW BEST (finalhi) R=%.9f" % bestR)
    ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=250)
    if R_of(ht2) > bestR + 1e-14:
        best, bestR = ht2.copy(), R_of(ht2)
        print("NEW BEST (finalpeak) R=%.9f" % bestR)

    for (rr, hh) in pool:
        if rr > bestR + 1e-14:
            best, bestR = hh.copy(), rr
            print("NEW BEST (pool-final) R=%.9f" % bestR)
            break

    end_nm = _nearmax_fracs(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax=%.4f/%.4f/%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), end_nm[0], end_nm[1], end_nm[2]))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_flat_top(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    S = Lf >= tau * mx
    nS = int(np.count_nonzero(S))
    V = 0.0
    if nS > 1:
        Ls = Lf[S]
        diff = Ls - Ls.mean()
        V = float(np.sum(diff * diff)) / (mx * mx * nS)
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * diff / (mx * mx * nS)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * V
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, active, maxiter, deadline, mode='plain', beta=0.0, flat_top=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    if flat_top is not None:
        tau, kappa = flat_top
        fg = (lambda hh: _fun_grad_flat_top(hh, tau, kappa))
    elif mode == 'tie':
        fg = _fun_grad_tie
    elif mode == 'beta':
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif mode == 'flat':
        fg = _fun_grad_flat
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = h.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)
    except Exception:
        return h0


def _peak_window(h, tol=0.98, pad_frac=0.5, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = idx.min(); hi = idx.max()
    span = hi - lo + 1
    pad = int(pad_frac * span) + extra
    lo = max(0, lo - pad); hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample_mass(h, N2):
    N = len(h)
    c = np.concatenate([[0.0], np.cumsum(h)])
    xs = np.arange(N2 + 1) * (N / N2)
    cm = np.interp(xs, np.arange(N + 1), c)
    new = np.diff(cm) * (N2 / N)
    if new.sum() <= 0:
        return np.ones(N2)
    return np.clip(new, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    best = np.ones(50)
    best_R = R_of(best)
    if start is not None:
        try:
            s = np.asarray(start, dtype=float)
            r = R_of(s)
            if r > best_R:
                best = s.copy(); best_R = r
        except Exception:
            pass

    def consider(h):
        nonlocal best, best_R
        if h is None:
            return False
        h = np.asarray(h, dtype=float)
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return False
        r = R_of(h)
        if r > best_R:
            best_R = r
            best = h.copy()
            return True
        return False

    # Phase 1: polish the start
    cur = best.copy()
    for _ in range(3):
        if time.process_time() > deadline - 2:
            break
        nxt = _lbfgs(cur, np.arange(cur.size), 400, deadline, mode='tie')
        if R_of(nxt) > R_of(cur):
            cur = nxt
        else:
            break
    consider(cur)

    # Phase 2: aggressive ladder to high N (aim to go beyond 12800)
    levels = (1600, 3200, 6400, 12800, 25600, 51200)
    for target_N in levels:
        if time.process_time() > deadline - 2:
            break
        if target_N <= best.size:
            continue
        remain = deadline - time.process_time()
        level_deadline = min(deadline - 1.0, time.process_time() + remain / 2.5)
        cur = _upsample_mass(best, target_N)
        cur = _rescale(cur)
        for mode, beta in (('beta', 1e3), ('beta', 1e5), ('tie', 0.0)):
            if time.process_time() > level_deadline:
                break
            nxt = _lbfgs(cur, np.arange(cur.size), 300, level_deadline,
                         mode=mode, beta=beta)
            if R_of(nxt) > R_of(cur):
                cur = nxt
        if time.process_time() < level_deadline:
            act = _peak_window(cur, tol=0.98, pad_frac=0.5, extra=256)
            nxt = _lbfgs(cur, act, 300, level_deadline, mode='tie')
            if R_of(nxt) > R_of(cur):
                cur = nxt
        consider(cur)
        print(f"ladder N={cur.size} R={R_of(cur):.6f}")

    # Phase 3: flat-top shaping to flatten the max region
    if time.process_time() < deadline - 2:
        cur = best.copy()
        for kappa in (1e-2, 1e-1, 1.0):
            if time.process_time() > deadline - 1.5:
                break
            nxt = _lbfgs(cur, np.arange(cur.size), 300, deadline - 1.0,
                         flat_top=(0.999, kappa))
            if R_of(nxt) > R_of(cur):
                cur = nxt
        consider(cur)

    # Phase 4: jitter restart at best N
    if time.process_time() < deadline - 2:
        rng = np.random.default_rng(12345)
        for scale in (0.03, 0.08):
            if time.process_time() > deadline - 1.5:
                break
            jit = _rescale(best * np.exp(rng.normal(0, scale, best.size)))
            nxt = _lbfgs(jit, np.arange(jit.size), 300, deadline, mode='tie')
            act = _peak_window(nxt, tol=0.98, pad_frac=0.5, extra=256)
            nxt2 = _lbfgs(nxt, act, 300, deadline, mode='tie')
            consider(nxt2)

    # Phase 5: final tie polish
    if time.process_time() < deadline - 1:
        try:
            nxt = _lbfgs(best.copy(), np.arange(best.size), 400, deadline, mode='tie')
            consider(nxt)
        except Exception:
            pass

    if best is None:
        best = np.ones(50)
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
