    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _refine(h, best_r, deadline):
    """Alternate tie/beta smoothing on peak window and global polish."""
    # Tie-breaking polish on peak window, then full vector.
    for tol in (0.999, 0.9999):
        if time.process_time() >= deadline - 0.5:
            return h, best_r
        win = _peak_window(h, tol=tol)
        cand = _lbfgs_block(h, win, 300, deadline, tie=True)
        r = R_of(cand)
        if r > best_r:
            h, best_r = cand, r
    # Beta-smoothing homotopy on full vector.
    for beta in (32, 128, 512, 2048, 8192):
        if time.process_time() >= deadline - 0.5:
            return h, best_r
        cand = _lbfgs_block(h, np.arange(h.size), 200, deadline, beta=beta)
        r = R_of(cand)
        if r > best_r:
            h, best_r = cand, r
    return h, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        # Fresh: start from a smooth bump and grow.
        N = 256
        x = np.linspace(0, 1, N)
        best = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(best)
        best_r = R_of(best)
        while N < 65536 and time.process_time() < deadline - 5.0:
            N = min(N * 2, 65536)
            best = _rescale(_prolong(best, N))
            best_r = R_of(best)
            best, best_r = _refine(best, best_r, deadline)

    # Ensure size.
    if best.size < 65536:
        best = _rescale(_prolong(best, 65536))
        best_r = R_of(best)
    print("start R=%.6f N=%d ties=%d" % (best_r, best.size, _tie_count(best)))

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        prev = best_r
        best, best_r = _refine(best, best_r, deadline)
        # Full-vector tie polish.
        if time.process_time() < deadline - 1.0:
            cand = _lbfgs_block(best, np.arange(best.size), 200, deadline, tie=True)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
        # Peak-window with growing padding.
        for pf in (0.5, 0.25, 0.12, 0.05):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(best, tol=0.999, pad_frac=pf)
            cand = _lbfgs_block(best, win, 300, deadline, tie=True)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
        print("  it#%d R=%.6f ties=%d" % (it, best_r, _tie_count(best)))
        if best_r - prev < 1e-10 and it > 3:
            break

    best = _rescale(best)
    print("final R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None and start_r >= best_r:
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _shoulder_block(h):
    Lf = _knots(h)
    mx = Lf.max()
    n = h.size
    if mx <= 0:
        return np.arange(n)
    S = np.flatnonzero((Lf >= 0.80 * mx) & (Lf < 0.9995 * mx))
    if S.size == 0:
        return np.arange(n)
    lo = max(0, int(S.min()) - (n - 1))
    hi = min(n - 1, int(S.max()))
    blk = np.arange(lo, hi + 1)
    pw = _peak_window(h, pad_frac=0.15, extra=128)
    u = np.union1d(blk, pw)
    return u[(u >= 0) & (u < n)].astype(int)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max before: %.4f / %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    alt_best = None
    altR = -1.0
    round_no = 0
    while time.process_time() < deadline - 1.5:
        round_no += 1
        cur = best.copy()
        curR = bestR
        n = cur.size

        # (a) full-array tie polish
        if time.process_time() < deadline - 1.0:
            h1 = _lbfgs_block(cur, np.arange(n), 250,
                              min(deadline - 1.0, time.process_time() + 6.0),
                              tie=True)
            r1 = R_of(h1)
            if r1 > curR + 1e-12:
                cur, curR = h1, r1

        # (b) shoulder-block tie polish
        if time.process_time() < deadline - 1.0:
            blk = _shoulder_block(cur)
            h2 = _lbfgs_block(cur, blk, 400,
                              min(deadline - 1.0, time.process_time() + 6.0),
                              tie=True)
            r2 = R_of(h2)
            if r2 > curR + 1e-12:
                cur, curR = h2, r2

        # (c) peak-window polishes
        for pad in (0.30, 0.20, 0.12, 0.06):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cur, pad_frac=pad, extra=96)
            h3 = _lbfgs_block(cur, win, 250,
                              min(deadline - 1.0, time.process_time() + 3.0),
                              tie=True)
            r3 = R_of(h3)
            if r3 > curR + 1e-12:
                cur, curR = h3, r3

        # (d) if no improvement this round, smoothed beta pass on shoulder block
        if curR <= bestR + 1e-12 and time.process_time() < deadline - 1.0:
            blk = _shoulder_block(cur)
            hb = _lbfgs_block(cur, blk, 300,
                              min(deadline - 1.0, time.process_time() + 5.0),
                              beta=3e6)
            rb = R_of(hb)
            if rb > curR + 1e-12:
                cur, curR = hb, rb
            if time.process_time() < deadline - 1.0:
                ht = _lbfgs_block(cur, blk, 300,
                                  min(deadline - 1.0, time.process_time() + 4.0),
                                  tie=True)
                rt = R_of(ht)
                if rt > curR + 1e-12:
                    cur, curR = ht, rt

        improved = curR > bestR + 1e-12
        if improved:
            best, bestR = cur.copy(), curR
        print("round %d: R=%.12f (best %.12f) frac 0.1/1/5%%: %.4f / %.4f / %.4f"
              % (round_no, curR, bestR,
                 _frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
                 _frac_near_max(best, 5e-2)))
        if not improved:
            # record as alternative if genuinely different and not worse
            if alt_best is None or curR > altR:
                alt_best, altR = cur.copy(), curR
            break

    if alt_best is None:
        alt_best, altR = best.copy(), bestR

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14 and alt_best.size != best.size:
        result["alternative"] = alt_best
    elif alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    return result

