    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _expand(x, block):
    return np.repeat(x, block)


def _aggregate(g, block):
    return g.reshape(-1, block).sum(axis=1)


def _phi_grad_x(x, block):
    h = _expand(x, block)
    val, g = _fun_grad_tie(h)
    return val, _aggregate(g, block)


def _hessvec(x, v, block, eps=1e-4):
    _, g1 = _phi_grad_x(x + eps * v, block)
    _, g0 = _phi_grad_x(x - eps * v, block)
    return (g1 - g0) / (2.0 * eps)


def _lanczos_smallest(x, block, rng, m=25, deadline=None):
    n = x.size
    _, g = _phi_grad_x(x, block)
    gn = np.abs(g)
    thr = np.quantile(gn, 0.40)
    mask = gn >= thr
    idx = np.flatnonzero(mask)
    if idx.size < 4:
        idx = np.arange(n)
    r = rng.standard_normal(idx.size)
    v = np.zeros(n)
    v[idx] = r
    nv = np.linalg.norm(v)
    if nv <= 0:
        return 0.0, v
    v /= nv
    V = np.zeros((m + 1, n))
    V[0] = v
    alphas = np.zeros(m)
    betas = np.zeros(m)
    for j in range(m):
        if deadline is not None and time.process_time() > deadline:
            m = j
            break
        w = _hessvec(x, V[j], block)
        w[~mask] = 0.0
        a = float(np.dot(w, V[j]))
        alphas[j] = a
        w = w - a * V[j]
        if j > 0:
            w = w - betas[j - 1] * V[j - 1]
        b = float(np.linalg.norm(w))
        betas[j] = b
        if b < 1e-12:
            m = j + 1
            break
        V[j + 1] = w / b
    m = max(1, m)
    T = np.diag(alphas[:m])
    for j in range(m - 1):
        T[j, j + 1] = betas[j]
        T[j + 1, j] = betas[j]
    try:
        evals, evecs = np.linalg.eigh(T)
    except Exception:
        return 0.0, v
    lam = float(evals[0])
    y = evecs[:, 0]
    vv = y @ V[:m]
    nvv = np.linalg.norm(vv)
    if nvv > 0:
        vv /= nvv
    return lam, vv


def _lbfgs_x(x0, block, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return x0
    x = np.clip(x0, 0, None)
    if x.sum() <= 0:
        return x0

    def f(xx):
        xxc = np.clip(xx, 0.0, None)
        h = _expand(xxc, block)
        if beta > 0:
            val, g = _fun_grad_beta(h, beta)
        else:
            val, g = _fun_grad_tie(h)
        return val, _aggregate(g, block)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return x0
    if res is None:
        return x0
    return np.clip(res.x, 0.0, None)


def _resample(base, newN):
    n = base.size
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    h = np.interp(x_new, x_old, base)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    block = 32
    N = best.size
    if N % block != 0:
        block = 1
    nx = N // block
    x = best.reshape(nx, block).mean(axis=1)
    print("staircase block=%d nx=%d R(x)=%.9f" % (block, nx,
                                                  R_of(_expand(x, block))))

    rng = np.random.default_rng(2024)

    # ---- Curvature escape via Lanczos ----
    lanc_deadline = time.process_time() + min(10.0, budget_seconds * 0.18)
    lam, v = _lanczos_smallest(x, block, rng, m=25, deadline=lanc_deadline)
    print("smallest Ritz value = %.6e" % lam)

    accepted = False
    if lam < 0 and np.linalg.norm(v) > 0:
        xnorm = np.linalg.norm(x)
        vnorm = np.linalg.norm(v)
        scale = xnorm / max(vnorm, 1e-30)
        for step in (0.01, 0.03, 0.1):
            if time.process_time() > deadline - 8.0:
                break
            for sign in (+1, -1):
                if time.process_time() > deadline - 8.0:
                    break
                xt = x + sign * step * scale * v
                xt = np.clip(xt, 0.0, None)
                if xt.sum() <= 0:
                    continue
                slice_end = min(deadline - 4.0, time.process_time() + 6.0)
                xt = _lbfgs_x(xt, block, 250, slice_end)
                ht = _rescale(_expand(xt, block))
                ht = _peak_ladder(ht, min(deadline - 1.0,
                                          time.process_time() + 4.0),
                                  pads=(0.08, 0.05, 0.03), iters=150, tie=True)
                rt = R_of(ht)
                print("  trial step=%+.3f sign=%+d R=%.9f dR=%+.3e"
                      % (step, sign, rt, rt - bestR))
                if rt > bestR + 1e-15:
                    best, bestR = ht.copy(), rt
                    x = best.reshape(nx, block).mean(axis=1)
                    accepted = True
                    print("  ACCEPTED step=%+.3f sign=%+d R=%.9f"
                          % (step, sign, bestR))

    if not accepted:
        print("no curvature escape accepted; polishing base")

    # ---- Polish remaining time ----
    loop_end = t0 + budget_seconds * 0.88
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 6.0)
        h_t = _lbfgs_all_pos(best, 500, slice_end - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("polish %d ACCEPT R=%.9f" % (it, bestR))
        else:
            print("polish %d no gain R=%.9f" % (it, r_t))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=200, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("polish peak %d ACCEPT R=%.9f" % (it, bestR))

    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 400, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _block_mean(h, Nq):
    n = h.size
    if Nq >= n:
        return h.copy()
    edges = np.linspace(0, n, Nq + 1).astype(int)
    out = np.empty(Nq)
    for i in range(Nq):
        a, b = edges[i], edges[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _repeat_lift(hq, n):
    Nq = hq.size
    edges = np.linspace(0, n, Nq + 1).astype(int)
    out = np.empty(n)
    for i in range(Nq):
        a, b = edges[i], edges[i + 1]
        if b <= a:
            b = a + 1
        out[a:b] = hq[i]
    return out


def _flat_top_rung(h, tau, kappa):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    T = Lf.copy()
    # soft flat-top: pull values near max up toward max
    w = 1.0 / (1.0 + np.exp(-kappa * (Lf / mx - tau)))
    T = Lf * (1.0 - w) + mx * w
    # deconvolve approximately via gradient step: use LBFGS on ||conv-T||^2
    n = h.size
    Tn = float(np.sum(T * T))
    if Tn <= 0:
        return h
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        Lh = _knots(hh)
        r = Lh - T
        val = float(np.sum(r * r)) / Tn
        gLf = 2.0 * r / Tn
        g = _backprop(gLf, hh)
        return val, g

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
        if res is not None:
            return _rescale(np.clip(res.x, 0.0, None))
    except Exception:
        pass
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---------- Branch racing ----------
    branch_cap = 5.0
    candidates = []  # (R, h, name)

    def record(h, name):
        if h is None:
            return
        r = R_of(h)
        candidates.append((r, h.copy(), name))
        print("  branch %s R=%.12f (d=%.2e)" % (name, r, r - startR))

    # Branch A: full-array tie L-BFGS 400 iters
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + branch_cap)
        hA = _lbfgs_block(best, np.arange(best.size), 400, tlim, tie=True)
        record(hA, "A")

    # Branch B: beta ladder on peak windows
    if time.process_time() < deadline - 1.0:
        hB = best.copy()
        for pad in (0.2, 0.1, 0.05):
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(hB, pad_frac=pad, extra=96)
            tlim = min(deadline - 0.4, time.process_time() + branch_cap / 6.0)
            hB = _lbfgs_block(hB, win, 200, tlim, beta=1e5)
            if time.process_time() >= deadline - 0.4:
                break
            tlim = min(deadline - 0.4, time.process_time() + branch_cap / 6.0)
            hB = _lbfgs_block(hB, win, 200, tlim, beta=1e7)
            if time.process_time() >= deadline - 0.4:
                break
            tlim = min(deadline - 0.4, time.process_time() + branch_cap / 6.0)
            hB = _lbfgs_block(hB, win, 200, tlim, tie=True)
        record(hB, "B")

    # Branch C: block-mean to Nq=3281, flat-top rung, repeat-32 lift, tie polish
    if time.process_time() < deadline - 1.0:
        n = best.size
        Nq = min(3281, n)
        hq = _block_mean(best, Nq)
        hq = _flat_top_rung(hq, 0.8, 100.0)
        hC = _repeat_lift(hq, n)
        hC = _rescale(hC)
        tlim = min(deadline - 0.5, time.process_time() + branch_cap)
        hC = _lbfgs_block(hC, np.arange(hC.size), 300, tlim, tie=True)
        record(hC, "C")

    # Branch D: tail lift h <- h + a*mean(h)
    if time.process_time() < deadline - 1.0:
        hD_best = None
        hD_bestR = -1.0
        for a in (1e-4, 3e-4, 1e-3):
            if time.process_time() >= deadline - 0.5:
                break
            hD = best.copy()
            hD = hD + a * hD.mean()
            hD = _rescale(hD)
            tlim = min(deadline - 0.4, time.process_time() + branch_cap / 4.0)
            hD = _lbfgs_block(hD, np.arange(hD.size), 100, tlim, tie=True)
            r = R_of(hD)
            if r > hD_bestR:
                hD_bestR = r
                hD_best = hD
        record(hD_best, "D")

    # pick best candidate
    for r, h, name in candidates:
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    print("after branches best R=%.12f (start %.12f)" % (bestR, startR))

    # ---------- Final race ----------
    pads = [0.2, 0.1, 0.05, 0.02]
    rnd = 0
    while time.process_time() < deadline - 0.5:
        rnd += 1
        # full-array tie L-BFGS
        tlim = min(deadline - 0.4, time.process_time() + 6.0)
        h1 = _lbfgs_block(best, np.arange(best.size), 300, tlim, tie=True)
        r1 = R_of(h1)
        if r1 > bestR + 1e-15:
            best, bestR = h1.copy(), r1
        # shrinking peak window
        pad = pads[(rnd - 1) % len(pads)]
        if time.process_time() < deadline - 0.4:
            win = _peak_window(best, pad_frac=pad, extra=96)
            tlim = min(deadline - 0.3, time.process_time() + 4.0)
            h2 = _lbfgs_block(best, win, 300, tlim, tie=True)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
        # every third round beta=1e7 pass
        if rnd % 3 == 0 and time.process_time() < deadline - 0.4:
            win = _peak_window(best, pad_frac=0.1, extra=96)
            tlim = min(deadline - 0.3, time.process_time() + 4.0)
            h3 = _lbfgs_block(best, win, 200, tlim, beta=1e7)
            r3 = R_of(h3)
            if r3 > bestR + 1e-15:
                best, bestR = h3.copy(), r3

    print("frac near max (0.1%%) after: %.4f" % _frac_near_max(best, 1e-3))

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        # return the change's own construction as alternative
        if candidates:
            r, h, name = max(candidates, key=lambda t: t[0])
            if r > startR - 1e-12:
                result["alternative"] = h
    return result

import numpy as np
import time
from scipy.optimize import minimize


def _L(h):
    return np.concatenate(([0.0], np.convolve(h, h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _L(h)
    num = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    den = s * s * max(L.max(), 1e-300)
    return num / den


def _rescale(h):
    h = np.clip(np.asarray(h, dtype=float), 0.0, None)
    m = h.max()
    if m > 0:
        h = h / m
    return h


def _softmax_surrogate(L, beta):
    m = L.max()
    return m + np.log(np.sum(np.exp(beta * (L - m)))) / beta


def _flat_obj(h, beta, tau, kappa):
    """-log R + kappa * Var{L_j : L_j >= tau*Lmax}/Lmax^2 with softmax surrogate."""
    s = h.sum()
    if s <= 0:
        return 1e18
    L = _L(h)
    num = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    Lmax = _softmax_surrogate(L, beta)
    den = s * s * Lmax
    R = num / den
    if R <= 0:
        return 1e18
    thr = tau * Lmax
    mask = L >= thr
    if np.count_nonzero(mask) >= 2:
        v = L[mask]
        var = np.mean((v - v.mean()) ** 2)
    else:
        var = 0.0
    pen = kappa * var / (Lmax * Lmax)
    return -np.log(R) + pen


def _polish(h, beta, maxiter=200):
    h = np.asarray(h, dtype=float).copy()
    n = len(h)

    def fun(x):
        return _flat_obj(np.clip(x, 0.0, None), beta, 0.0, 0.0)

    try:
        res = minimize(fun, h, method="L-BFGS-B",
                       bounds=[(0.0, None)] * n,
                       options={"maxiter": maxiter, "maxfun": maxiter * 2})
        h = np.clip(res.x, 0.0, None)
    except Exception:
        pass
    return _rescale(h)


def _flat_rung(h, beta, tau, kappa, maxiter=200):
    h = np.asarray(h, dtype=float).copy()
    n = len(h)

    def fun(x):
        return _flat_obj(np.clip(x, 0.0, None), beta, tau, kappa)

    try:
        res = minimize(fun, h, method="L-BFGS-B",
                       bounds=[(0.0, None)] * n,
                       options={"maxiter": maxiter, "maxfun": maxiter * 2})
        h = np.clip(res.x, 0.0, None)
    except Exception:
        pass
    return _rescale(h)


def _peak_window_polish(h, beta, pad, maxiter=150):
    h = np.asarray(h, dtype=float).copy()
    n = len(h)
    L = _L(h)
    j = int(np.argmax(L))
    lo = max(0, j - int(pad * n) - 1)
    hi = min(n, j + int(pad * n) + 1)
    if hi - lo < 2:
        return h
    idx = np.arange(lo, hi)

    def fun(x):
        hh = h.copy()
        hh[idx] = np.clip(x, 0.0, None)
        return _flat_obj(hh, beta, 0.0, 0.0)

    try:
        res = minimize(fun, h[idx], method="L-BFGS-B",
                       bounds=[(0.0, None)] * len(idx),
                       options={"maxiter": maxiter, "maxfun": maxiter * 2})
        h[idx] = np.clip(res.x, 0.0, None)
    except Exception:
        pass
    return _rescale(h)


def _lift_double(h):
    n = len(h)
    out = np.zeros(2 * n)
    out[0::2] = h
    out[1::2] = h
    return out


def _stats(h):
    L = _L(h)
    mx = L.max()
    nz = float(np.mean(h == 0))
    mm = float(h.max() / max(h.mean(), 1e-300))
    near = [float(np.mean(np.abs(L - mx) <= f * mx)) for f in (0.01, 0.05)]
    return nz, mm, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.88 * budget_seconds

    best = None
    best_R = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        best = s
        best_R = R_of(s)
        print("start R:", round(best_R, 6), "N:", len(s))

    if best is None:
        best = np.ones(50)
        best_R = R_of(best)

    def ladder(h, level_name):
        nonlocal best_R, best
        rungs = [(0.9, 10), (0.8, 30), (0.7, 100), (0.6, 300), (0.5, 1000)]
        for tau, kappa in rungs:
            if time.process_time() > deadline:
                break
            rung_deadline = min(deadline, time.process_time() + 4.0)
            h2 = h
            for beta in [1e4, 1e6]:
                if time.process_time() > rung_deadline:
                    break
                h2 = _flat_rung(h2, beta, tau, kappa, maxiter=200)
            r = R_of(h2)
            if r > best_R:
                best_R = r
                best = h2.copy()
            # keep improving h even if not best
            if r >= R_of(h):
                h = h2
            nz, mm, near = _stats(h)
            print(f"{level_name} tau={tau} kappa={kappa} R={r:.6f} best={best_R:.6f} "
                  f"nz={nz:.3f} mm={mm:.2f} near={near}")
        return h

    h = ladder(best, "N%d" % len(best))

    for target in [8192, 16384]:
        if time.process_time() > deadline:
            break
        if len(h) * 2 <= target:
            h = _rescale(_lift_double(h))
            h = ladder(h, "N%d" % len(h))
            # tie polish
            for beta in [1e5, 1e6, 1e7]:
                if time.process_time() > deadline:
                    break
                h = _polish(h, beta, maxiter=200)
                r = R_of(h)
                if r > best_R:
                    best_R = r
                    best = h.copy()
            # peak window
            for pad in [0.2, 0.1]:
                if time.process_time() > deadline:
                    break
                h = _peak_window_polish(h, 1e6, pad, maxiter=150)
                r = R_of(h)
                if r > best_R:
                    best_R = r
                    best = h.copy()
            nz, mm, near = _stats(best)
            print(f"level N{len(best)} bestR={best_R:.6f} nz={nz:.3f} mm={mm:.2f} near={near}")

    # final tie polish loop
    h = best.copy()
    while time.process_time() < deadline:
        h2 = _polish(h, 1e7, maxiter=150)
        r = R_of(h2)
        if r > best_R:
            best_R = r
            best = h2.copy()
            h = h2
        else:
            break

    final = _rescale(best)
    r = R_of(final)
    nz, mm, near = _stats(final)
    print("final R:", r, "N:", len(final), "zero frac:", round(nz, 4),
          "max/mean:", round(mm, 2), "near-max 1%/5%:", [round(x, 4) for x in near])

    result = {"best": final}
    if start is not None:
        sr = R_of(np.asarray(start, dtype=float))
        if sr > r:
            result["best"] = np.asarray(start, dtype=float)
        else:
            result["alternative"] = np.asarray(start, dtype=float)
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    return _lbfgs_block(h0, np.arange(np.size(h0)), maxiter, deadline,
                        beta, tie)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.12, 0.07, 0.04, 0.02), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=64)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _refine(h, factor, deadline, iters=300):
    if factor <= 1:
        return h
    n = h.size
    xi = np.linspace(0, n, n * factor, endpoint=False)
    hi = np.interp(xi, np.arange(n), h)
    hi = _rescale(hi)
    return _lbfgs_all(hi, iters, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_end = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        cur = np.ones(512)
        cur = _lbfgs_all(cur, 800, hard_end)
        return cur

    alternative = None
    alt_r = -1.0

    def _consider(cand):
        nonlocal best, best_r, alternative, alt_r
        r = R_of(cand)
        if r > best_r:
            best = cand.copy(); best_r = r
        elif r > alt_r:
            alternative = cand.copy(); alt_r = r

    # Stage A: tie-aware smoothing polish of start
    h = start_arr.copy()
    for beta in (1e6, 1e5, 1e4, 1e3):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _lbfgs_all(h, 250, hard_end, beta=beta)
        if R_of(c) >= R_of(h) - 1e-12:
            h = c
    c = _lbfgs_all(h, 400, hard_end, tie=True)
    if R_of(c) >= R_of(h):
        h = c
    _consider(h)
    print("A R=%.6f N=%d" % (best_r, h.size))

    # Stage B: peak-ladder focused polishing
    for _ in range(3):
        if time.process_time() >= hard_end - 0.8:
            break
        c = _peak_ladder(best.copy(), hard_end)
        _consider(c)
    print("B R=%.6f N=%d" % (best_r, best.size))

    # Stage C: refine by upsampling
    cur = best.copy()
    for factor in (2, 2):
        if time.process_time() >= hard_end - 1.0:
            break
        if cur.size * factor > 1000000:
            break
        c = _refine(cur, factor, hard_end, iters=400)
        c = _peak_ladder(c, hard_end)
        c = _lbfgs_all(c, 400, hard_end)
        _consider(c)
        if R_of(c) >= R_of(cur) - 1e-12:
            cur = c
        print("C R=%.6f N=%d" % (best_r, best.size))

    # Stage D: fine polish with tie-aware gradient
    while time.process_time() < hard_end - 0.8:
        h = best.copy()
        c = _peak_ladder(h, hard_end,
                         pads=(0.10, 0.06, 0.03, 0.015, 0.007), iters=350)
        c = _lbfgs_all(c, 400, hard_end, tie=True)
        r = R_of(c)
        if r > best_r + 1e-13:
            _consider(c)
        else:
            break
    print("D R=%.6f N=%d" % (best_r, best.size))

    if start_arr is not None and R_of(start_arr) > best_r:
        best = start_arr.copy(); best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None and alt_r > -1:
        return {"best": best, "alternative": alternative}
    return best

