        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat_top is not None:
        tau, kappa = flat_top
        fg = (lambda hh: _fun_grad_flat_top(hh, tau, kappa))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _build_target(L, eps):
    mx = L.max()
    S = L >= (1.0 - eps) * mx
    T = L.copy()
    if not np.any(S):
        return T
    idx = np.flatnonzero(S)
    lo, hi = idx.min(), idx.max()
    val = L[S].mean()
    T[lo:hi + 1] = val
    k = 9
    ker = np.ones(k) / k
    T = np.convolve(T, ker, mode='same')
    return T


def _deconv_step(h0, T, lam, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    Tn = float(np.sum(T * T))
    if Tn <= 0:
        return h0
    h0n = float(np.sum(h * h))
    if h0n <= 0:
        h0n = 1.0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        Lf = _knots(hh)
        r = Lf - T
        val = float(np.sum(r * r)) / Tn + lam * float(np.sum((hh - h) ** 2)) / h0n
        gLf = 2.0 * r / Tn
        g = _backprop(gLf, hh) + 2.0 * lam * (hh - h) / h0n
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def _fracs(h):
    return (_frac_near_max(h, 1e-3), _frac_near_max(h, 1e-2),
            _frac_near_max(h, 5e-2))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    f0 = _fracs(best)
    print("frac near max before: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % f0)

    alt_best = None
    altR = -1.0
    start_best = best.copy()

    # ---- New strategy: multi-scale coarse-to-fine smoothing with beta continuation ----
    # The idea: iterate over several coarsening factors, at each scale run a beta-continuation
    # softmax-maximisation (smoothly approximating the max penalty) to broaden the plateau,
    # then prolongate back up and polish with full-resolution tie L-BFGS. This targets the
    # exact structure the problem rewards: a wide flat top of f*f.

    def beta_continuation(qh, qR, time_cap):
        """Run increasing beta to sharpen the max approximation on coarse grid."""
        cur = qh.copy(); curR = qR
        for beta in (2.0, 5.0, 12.0, 30.0, 80.0):
            if time.process_time() >= time_cap - 2.0:
                break
            tlim = min(time_cap - 1.5, time.process_time() + 2.5)
            cand = _lbfgs_block(cur, np.arange(cur.size), 100, tlim, beta=beta)
            r = R_of(cand)
            if r > curR - 1e-6:  # allow slight non-monotone for continuation
                cur, curR = cand.copy(), max(r, curR)
        return cur, curR

    for Q in (16, 8, 4, 2):
        if time.process_time() >= deadline - 6.0:
            break
        if best.size % Q != 0:
            continue
        qh = _coarsen(best, Q)
        if qh is None or qh.size < 32:
            continue
        qh = _rescale(qh)
        qR = R_of(qh)
        cap = min(deadline - 5.0, time.process_time() + 6.0)
        cand, cR = beta_continuation(qh, qR, cap)
        # polish on coarse with tie
        if time.process_time() < cap - 1.0:
            cand = _lbfgs_block(cand, np.arange(cand.size), 150,
                                min(cap, time.process_time() + 1.5), tie=True)
            cR = R_of(cand)
        ph = _prolongate(cand, Q)
        pr = R_of(ph)
        fr = _fracs(ph)
        print("Q=%d coarse R=%.9f prolonged R=%.9f 0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
              % (Q, cR, pr, fr[0], fr[1], fr[2]))
        if pr > bestR + 1e-15:
            best, bestR = ph.copy(), pr
        if pr > altR and (alt_best is None or ph.size == alt_best.size):
            alt_best, altR = ph.copy(), pr
        # full-resolution polish
        if time.process_time() < deadline - 3.0:
            pol = _lbfgs_block(best, np.arange(best.size), 150,
                               min(deadline - 2.5, time.process_time() + 3.0),
                               tie=True)
            rp = R_of(pol)
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

    # ---- Flat-top variance penalty on a coarsened version (from original) ----
    Q = 32
    if best.size % Q == 0 and time.process_time() < deadline - 4.0:
        qh = _rescale(_coarsen(best, Q))
        ladder = [(0.995, 0.05), (0.99, 0.2), (0.98, 1.0),
                  (0.95, 3.0), (0.90, 10.0)]
        best_qh = qh.copy(); best_qR = R_of(qh)
        for (tau, kappa) in ladder:
            if time.process_time() >= deadline - 3.0:
                break
            tlim = min(deadline - 2.5, time.process_time() + 2.0)
            cand = _lbfgs_block(best_qh, np.arange(best_qh.size), 100, tlim,
                                flat_top=(tau, kappa))
            r = R_of(cand)
            if r > best_qR:
                best_qh, best_qR = cand.copy(), r
            ph = _prolongate(cand, Q)
            pr = R_of(ph)
            if pr > bestR + 1e-15:
                best, bestR = ph.copy(), pr

    # ---- Final peak-window polishes ----
    for pad in (0.08, 0.04, 0.02):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.6, time.process_time() + 2.5),
                          tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    # Final global polish if time remains
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 150,
                           min(deadline - 0.4, time.process_time() + 2.0),
                           tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best = start_best
        bestR = startR

    fa = _fracs(best)
    print("frac near max after: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % fa)
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size <= 1000000 and alt_best.size != best.size:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- Branch C helpers: block-mean reduction and cumulative-mass lift ----

def _block_mean(h, Nq):
    n = h.size
    if Nq >= n:
        return h.copy()
    edges = np.linspace(0, n, Nq + 1)
    idx = np.round(edges).astype(int)
    out = np.zeros(Nq)
    for i in range(Nq):
        a, b = idx[i], idx[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _cum_lift(hq, N):
    """Lift Nq heights to N by cumulative-mass interpolation."""
    Nq = hq.size
    if Nq >= N:
        return hq.copy()
    cq = np.concatenate(([0.0], np.cumsum(hq)))
    xq = np.linspace(0.0, 1.0, Nq + 1)
    x = np.linspace(0.0, 1.0, N + 1)
    c = np.interp(x, xq, cq)
    h = np.diff(c)
    return np.clip(h, 0, None)


def _fun_grad_lin(h, tau, kappa):
    """Linear-form R with flat-top variance penalty."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    # flat-top: penalize variance of Lf above tau*mx
    thr = tau * mx
    mask = Lf >= thr
    if np.any(mask):
        Lm = Lf[mask].mean()
        var = np.mean((Lf[mask] - Lm) ** 2)
    else:
        Lm = mx
        var = 0.0
    gLf = -dq / num
    # gradient of log(max) via softmax-ish: use tie gradient
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    # gradient of variance penalty
    if np.any(mask) and var > 0:
        cnt = np.sum(mask)
        dvar = 2.0 * (Lf - Lm) / cnt
        gLf += kappa * dvar
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * var
    return val, grad


def _lbfgs_lin(h0, maxiter, deadline, tau, kappa):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_lin(hh, tau, kappa)

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


# ---- Branch D helper: mass-preserving 2x upsample with smoothing ----

def _upsample2(h):
    n = h.size
    out = np.zeros(2 * n)
    out[0::2] = h
    out[1::2] = h
    # width-3 smoothing [0.25,0.5,0.25]
    ker = np.array([0.25, 0.5, 0.25])
    sm = np.convolve(out, ker, mode='same')
    return sm


# ---- Branch definitions ----

def _branch_A(best, deadline):
    """Full-array tie L-BFGS, 100 iters."""
    return _lbfgs_block(best, np.arange(best.size), 100, deadline, tie=True)


def _branch_B(best, deadline):
    """Beta ladder 1e5 then 1e7 on peak windows, pads 0.2,0.1,0.05,0.02, 60 iters each."""
    h = best
    for beta in (1e5, 1e7):
        for pad in (0.2, 0.1, 0.05, 0.02):
            if time.process_time() >= deadline - 0.1:
                return h
            win = _peak_window(h, pad_frac=pad, extra=96)
            h = _lbfgs_block(h, win, 60, deadline, beta=beta)
    return h


def _branch_C(best, deadline):
    """Block-mean to Nq=821, lin-form solve 200 iters, cumulative-mass lift."""
    Nq = 821
    hq = _block_mean(best, Nq)
    hq = _rescale(hq)
    hq2 = _lbfgs_lin(hq, 200, deadline, tau=0.85, kappa=30.0)
    hl = _cum_lift(hq2, best.size)
    return _rescale(hl)


def _branch_D(best, deadline):
    """Mass-preserving 2x upsample + smoothing, then tie L-BFGS 100 iters."""
    hu = _upsample2(best)
    hu = _rescale(hu)
    hu2 = _lbfgs_block(hu, np.arange(hu.size), 100, deadline, tie=True)
    return hu2


_BRANCHES = {
    'A': _branch_A,
    'B': _branch_B,
    'C': _branch_C,
    'D': _branch_D,
}


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    alloc_stop = t0 + budget_seconds * 0.78

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%) before: %.4f" % _frac_near_max(best, 1e-3))

    # Per-branch state: list of (cpu_time, R)
    state = {k: [] for k in _BRANCHES}
    branch_best = {k: None for k in _BRANCHES}
    branch_bestR = {k: -1.0 for k in _BRANCHES}
    branch_cpu = {k: 0.0 for k in _BRANCHES}

    def run_quantum(name):
        nonlocal best, bestR
        fn = _BRANCHES[name]
        cpu_start = time.process_time()
        # per-quantum cap: 3 s CPU or deadline
        q_deadline = min(deadline, cpu_start + 3.0)
        try:
            h = fn(best, q_deadline)
        except Exception:
            h = best
        cpu_used = time.process_time() - cpu_start
        r = R_of(h)
        state[name].append((cpu_used, r))
