        branch_cpu[name] += cpu_used
        if r > branch_bestR[name]:
            branch_bestR[name] = r
            branch_best[name] = h.copy()
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        print("  quantum %s: R=%.12f cpu=%.2fs (best %.12f)"
              % (name, r, cpu_used, bestR))
