        return (r2 - r1) / dc

    def least_run():
        return min(_BRANCHES.keys(), key=lambda k: len(state[k]))

    rng = np.random.RandomState(12345)
    while time.process_time() < alloc_stop:
        if rng.rand() < 0.2:
            name = least_run()
        else:
            # max slope/(time) — use slope directly (already per-cpu)
            slopes = {k: slope(k) for k in _BRANCHES}
            name = max(_BRANCHES.keys(), key=lambda k: slopes[k])
        run_quantum(name)

    # ---- Final race: alternating full tie + peak-window polish ----
    print("frac near max (0.1%%) after alloc: %.4f" % _frac_near_max(best, 1e-3))

    # pick best branch result as seed if better
    for k in _BRANCHES:
        if branch_best[k] is not None and branch_bestR[k] > bestR + 1e-15:
            best, bestR = branch_best[k].copy(), branch_bestR[k]

    pads = [0.05, 0.03]
    pi = 0
    while time.process_time() < deadline - 2.0:
        # full-array tie
        if time.process_time() < deadline - 2.0:
            h = _lbfgs_block(best, np.arange(best.size), 150,
                             min(deadline - 1.5, time.process_time() + 4.0),
                             tie=True)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
        # peak-window polish
        if time.process_time() < deadline - 1.0:
