                best, bestR = h.copy(), r

    # final safety tie polish
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(best, np.arange(best.size), 200,
                         deadline - 0.2, tie=True)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # ---- Per-branch table ----
    print("branch | quanta | best R | total CPU | slope")
    for k in ('A', 'B', 'C', 'D'):
