    return _rescale(np.clip(res.x, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    f01, f1, f5 = _fracs(best)
    print("base R=%.12f (N=%d) fracs 0.1/1/5%%: %.4f/%.4f/%.4f"
          % (bestR, best.size, f01, f1, f5))

    alt_best = None
    altR = -1.0

    # ---- Shoulder-target deconvolution ladder ----
    for eps in (0.10, 0.05, 0.02):
        if time.process_time() >= deadline - 8.0:
            break
        L = _knots(best)
        T = _build_shoulder_target(L, eps)
        tlim = min(deadline - 6.0, time.process_time() + 10.0)
        hd = _deconv_shoulder(best, T, 1e-2, 80, tlim)
        rd = R_of(hd)
        f01, f1, f5 = _fracs(hd)
        print("eps=%.2f deconv: fracs 0.1/1/5%%=%.4f/%.4f/%.4f R=%.12f"
              % (eps, f01, f1, f5, rd))
        if rd > altR:
            altR = rd
            alt_best = hd.copy()
        if rd > bestR + 1e-15:
            best, bestR = hd.copy(), rd

        # full tie polish
        if time.process_time() < deadline - 4.0:
            pol = _lbfgs_block(hd, np.arange(hd.size), 200,
                               min(deadline - 3.0, time.process_time() + 6.0),
                               tie=True)
            rp = R_of(pol)
            f01, f1, f5 = _fracs(pol)
            print("  polish: fracs 0.1/1/5%%=%.4f/%.4f/%.4f R=%.12f"
                  % (f01, f1, f5, rp))
            if rp > altR:
                altR = rp
                alt_best = pol.copy()
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

        # peak-window polish
        for pad in (0.05, 0.03):
            if time.process_time() >= deadline - 2.0:
                break
            win = _peak_window(hd, pad_frac=pad, extra=96)
            ht = _lbfgs_block(hd, win, 300,
                              min(deadline - 1.0, time.process_time() + 3.0), tie=True)
            r = R_of(ht)
            if r > altR:
