    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, logspace=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0

    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    if logspace:
        x0 = np.log(np.clip(h[active], 1e-300, None))
        lo_b = -30.0
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = h.copy()
            hh[active] = np.exp(uu)
            val, g = fg(hh)
            return val, g[active] * hh[active]
        bounds = [(lo_b, 30.0)] * active.size
    else:
        x0 = h[active].copy()
        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g[active]
        bounds = [(0.0, None)] * active.size

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    if logspace:
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    else:
        h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR

    def _try(h, tag):
        nonlocal best, bestR
        if h is None:
            return False
        r = R_of(h)
        print("  %s R=%.7f" % (tag, r))
        if r > bestR + 1e-13:
            best, bestR = h, r
            return True
        return False

    # NEW IDEA: full-spectrum log-space polish on the whole vector with the
    # tie-aware gradient, then alternate peak-window and full passes.  The
    # original only polished a subset of coordinates and never used the
    # tie-aware (max) gradient on the full vector in log space; that is a
    # different descent path that can push the flat top further.

    # pass 1: full log-space tie polish from start
    if time.process_time() < deadline - 1.0:
        allidx = np.arange(best.size)
        hp = _lbfgs_block(best.copy(), allidx, 400,
                          min(deadline - 0.5, time.process_time() + 8.0),
                          tie=True, logspace=True)
        _try(hp, "L1 full-log")

    # pass 2: alternate peak-window and full tie polishes
    rounds = 0
    while time.process_time() < deadline - 1.0 and rounds < 20:
        rounds += 1
        # peak-window tie polish
        win = _peak_window(best, tol=0.999, pad_frac=0.5, extra=256)
        hp = _lbfgs_block(best, win, 300,
                          min(deadline - 0.4, time.process_time() + 3.0),
                          tie=True)
        got = _try(hp, "L2 peak")
        # full tie polish
        if time.process_time() < deadline - 0.6:
            hp = _lbfgs_block(best, np.arange(best.size), 300,
                              min(deadline - 0.3, time.process_time() + 3.0),
                              tie=True)
            got = _try(hp, "L2 full") or got
        # beta-smoothed to break exact ties
        if time.process_time() < deadline - 0.6:
            for beta in (100.0, 400.0):
                if time.process_time() >= deadline - 0.5:
                    break
                hp = _lbfgs_block(best, np.arange(best.size), 200,
                                  min(deadline - 0.3, time.process_time() + 2.5),
                                  beta=beta)
                _try(hp, "L2 beta%.0f" % beta)
        if not got and rounds > 2:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _refine(h):
    return np.repeat(h, 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    print("base R=%.9f N=%d" % (baseR, baseH.size))

    # Keep track of a "best" and an "alternative" (a construction from a
    # different basin). We seed the alternative with the base refined.
    bestH = baseH.copy()
    bestR = baseR
    alternative = baseH.copy()
    alternativeR = baseR

    def maybe_update(hnew, rnew, tag=""):
        nonlocal bestH, bestR, alternative, alternativeR
        if rnew > bestR + 1e-14:
            bestH, bestR = hnew.copy(), rnew
            if tag:
                print("  %s R=%.9f" % (tag, bestR))
            return True
        return False

    # ---- Phase A: refine the start (2x) and optimise. This is the "new idea":
    # a finer grid lets the optimiser sharpen the peak plateau so the maximum
    # of f*f is shared by more knots (tie-breaking), raising R.
    if baseH.size <= 480000:
        hr = _refine(baseH)
        rr = R_of(hr)
        # record the raw refinement as the alternative (genuinely different)
        alternative, alternativeR = hr.copy(), rr
        if rr > bestR - 1e-12:
            bestH, bestR = hr.copy(), rr
        print("refined N=%d R=%.9f" % (hr.size, rr))

        # Optimise the refined construction (tie-aware, then plain).
        cap = min(deadline - 2.0, time.process_time() + 8.0)
        hs = _lbfgs_log(hr, 300, cap, beta=0.0)
        rs = R_of(hs)
        maybe_update(hs, rs, "refine-opt")
        if time.process_time() < deadline - 2.0:
            free = _peak_window(bestH, pad_frac=0.25, extra=512)
            cap = min(deadline - 2.0, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 200, cap, beta=0.0, tie=True)
            rp = R_of(hp)
            maybe_update(hp, rp, "refine-tie")

    # ---- Phase B: alternating global + peak-window refinement ----
    it = 0
    loop_end = deadline - 2.5
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if maybe_update(hs, rs, "iter%d global" % it):
            continue
        if time.process_time() < loop_end - 1.0:
            pads = [0.40, 0.25, 0.15, 0.10, 0.06]
            pad = pads[it % len(pads)]
            free = _peak_window(bestH, pad_frac=pad, extra=384)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 200, cap, beta=0.0, tie=(it % 3 == 0))
            rp = R_of(hp)
            maybe_update(hp, rp, "iter%d peak pad=%.2f" % (it, pad))

    # ---- Final polish ----
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hs = _lbfgs_log(bestH, 100, cap, beta=0.0)
        rs = R_of(hs)
        maybe_update(hs, rs, "final")

    print("done bestR=%.9f altR=%.9f baseR=%.9f N=%d" %
          (bestR, alternativeR, baseR, bestH.size))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": alternative}
    else:
        return {"best": baseH, "alternative": alternative}

