    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _refine(h):
    return np.repeat(h, 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    print("base R=%.9f N=%d" % (baseR, baseH.size))

    # Keep track of a "best" and an "alternative" (a construction from a
    # different basin). We seed the alternative with the base refined.
    bestH = baseH.copy()
    bestR = baseR
    alternative = baseH.copy()
    alternativeR = baseR

    def maybe_update(hnew, rnew, tag=""):
        nonlocal bestH, bestR, alternative, alternativeR
        if rnew > bestR + 1e-14:
            bestH, bestR = hnew.copy(), rnew
            if tag:
                print("  %s R=%.9f" % (tag, bestR))
            return True
        return False

    # ---- Phase A: refine the start (2x) and optimise. This is the "new idea":
    # a finer grid lets the optimiser sharpen the peak plateau so the maximum
    # of f*f is shared by more knots (tie-breaking), raising R.
    if baseH.size <= 480000:
        hr = _refine(baseH)
        rr = R_of(hr)
        # record the raw refinement as the alternative (genuinely different)
        alternative, alternativeR = hr.copy(), rr
        if rr > bestR - 1e-12:
            bestH, bestR = hr.copy(), rr
        print("refined N=%d R=%.9f" % (hr.size, rr))

        # Optimise the refined construction (tie-aware, then plain).
        cap = min(deadline - 2.0, time.process_time() + 8.0)
        hs = _lbfgs_log(hr, 300, cap, beta=0.0)
        rs = R_of(hs)
        maybe_update(hs, rs, "refine-opt")
        if time.process_time() < deadline - 2.0:
            free = _peak_window(bestH, pad_frac=0.25, extra=512)
            cap = min(deadline - 2.0, time.process_time() + 4.0)
            hp = _lbfgs_block(bestH, free, 200, cap, beta=0.0, tie=True)
            rp = R_of(hp)
            maybe_update(hp, rp, "refine-tie")

    # ---- Phase B: alternating global + peak-window refinement ----
    it = 0
    loop_end = deadline - 2.5
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if maybe_update(hs, rs, "iter%d global" % it):
            continue
        if time.process_time() < loop_end - 1.0:
            pads = [0.40, 0.25, 0.15, 0.10, 0.06]
            pad = pads[it % len(pads)]
            free = _peak_window(bestH, pad_frac=pad, extra=384)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 200, cap, beta=0.0, tie=(it % 3 == 0))
            rp = R_of(hp)
            maybe_update(hp, rp, "iter%d peak pad=%.2f" % (it, pad))

    # ---- Final polish ----
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hs = _lbfgs_log(bestH, 100, cap, beta=0.0)
        rs = R_of(hs)
        maybe_update(hs, rs, "final")

    print("done bestR=%.9f altR=%.9f baseR=%.9f N=%d" %
          (bestR, alternativeR, baseR, bestH.size))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": alternative}
    else:
        return {"best": baseH, "alternative": alternative}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 1e-300, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w / Pm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _report(tag, h, R):
    mean = h.mean()
    ratio = (h.max() / mean) if mean > 0 else 0.0
    print("  %s R=%.7f zeros=%.1f%% max/mean=%.2f" %
          (tag, R, 100.0 * np.mean(h <= 0), ratio))


def _peak_window(h, tol=0.9995, pad_frac=0.5, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_flat(h):
    # Flatten the peak region of f*f toward its max via L2 on knots.
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _beta_fg(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 16384
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    _report("base", best, bestR)

    cur = best.copy()
    curR = bestR

    # Phase 0: NEW -- soft-max (beta) polish to break exact peak ties.
    # This targets the flat / tied peak that limits R via ||f*f||_inf.
    for beta in (2.0, 8.0, 30.0):
        if time.process_time() > deadline - 3.0:
            break
        h = _lbfgs_log(cur, 120, min(deadline - 2.0,
                                     time.process_time() + 3.0),
                       fg=(lambda hh, b=beta: _beta_fg(hh, b)))
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h.copy(), r
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
    _report("beta0", cur, curR)

    # Phase 1: peak-window block polish (local, cheap).
    if cur.size > 32:
        sub_end = min(deadline - 2.0, time.process_time() + budget_seconds * 0.12)
        free = _peak_window(cur, tol=0.99, extra=128)
        h2 = _lbfgs_block(cur, free, 200, sub_end)
        r2 = R_of(h2)
        if r2 > curR + 1e-13:
            cur, curR = h2, r2
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
        _report("window0", cur, curR)

    # Phase 2: p-norm polish.
    for p in (40.0, 100.0, 300.0):
        if time.process_time() > deadline - 3.0:
            break
        h = _lbfgs_log(cur, 120, min(deadline - 2.0,
                                     time.process_time() + 4.0),
                       fg=(lambda hh, pp=p: _fun_grad_pnorm(hh, pp)))
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h.copy(), r
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR

    # Phase 3: multi-scale prolongation.
    scale_end = t0 + budget_seconds * 0.45
    factors = [2, 2, 3, 2]
    fi = 0
    while time.process_time() < scale_end - 5.0:
        factor = factors[fi % len(factors)]
        fi += 1
        seed = np.repeat(cur, factor).astype(float)
        seed = _rescale(seed)
        sub_end = min(scale_end, time.process_time() + 8.0)
        h = _lbfgs_log(seed, 200, sub_end)
        r = R_of(h)
        if time.process_time() < sub_end - 2.0:
            free = _peak_window(h, tol=0.99, extra=200)
            h2 = _lbfgs_block(h, free, 150, sub_end)
            r2 = R_of(h2)
            if r2 > r:
                h, r = h2, r2
        if time.process_time() < sub_end - 2.0:
            h3 = _lbfgs_log(h, 100, sub_end,
                            fg=(lambda hh: _fun_grad_pnorm(hh, 80.0)))
            r3 = R_of(h3)
            if r3 > r:
                h, r = h3, r3
        print("  scale x%d R=%.7f (cur=%.7f best=%.7f)" %
              (factor, r, curR, bestR))
        if r > curR + 1e-13:
            cur, curR = h.copy(), r
            if r > bestR + 1e-13:
                best, bestR = h.copy(), r
                _report("scale x%d keep" % factor, best, bestR)

    # Phase 4: alternating full polish + peak-window + flat-knot polish.
    full = np.arange(cur.size)
    round_idx = 0
    while time.process_time() < deadline - 1.5:
        round_idx += 1
        sub_deadline = min(deadline - 0.8, time.process_time() + 6.0)
        h = _lbfgs_block(cur, full, 120, sub_deadline)
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h.copy(), r
        if time.process_time() < sub_deadline - 1.0:
            free = _peak_window(cur, tol=0.99, extra=100)
            h = _lbfgs_block(cur, free, 80, sub_deadline,
                             fg=_tie_flat)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h.copy(), r
        if round_idx % 2 == 0 and time.process_time() < sub_deadline - 1.0:
            h = _lbfgs_log(cur, 80, sub_deadline,
                           fg=(lambda hh: _beta_fg(hh, 20.0)))
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h.copy(), r
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


