    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- block-mean reduction / lift ----

def _block_mean(h, Nq):
    n = h.size
    if Nq >= n:
        return h.copy()
    edges = np.linspace(0, n, Nq + 1)
    idx = np.round(edges).astype(int)
    out = np.zeros(Nq)
    for i in range(Nq):
        a, b = idx[i], idx[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _cum_lift(hq, N):
    Nq = hq.size
    if Nq >= N:
        return hq.copy()
    cq = np.concatenate(([0.0], np.cumsum(hq)))
    xq = np.linspace(0.0, 1.0, Nq + 1)
    x = np.linspace(0.0, 1.0, N + 1)
    c = np.interp(x, xq, cq)
    h = np.diff(c)
    return np.clip(h, 0, None)


# ---- experiment: stochastic block-mean perturbation race ----

def _is_32fold(h, tol=1e-12):
    n = h.size
    if n % 32 != 0:
        return False
    m = n // 32
    blocks = h.reshape(m, 32)
    var = blocks.var(axis=1)
    mx = np.abs(h).max()
    if mx <= 0:
        return False
    return float(var.max()) < tol * mx * mx


def _reconstruct_32fold(h):
    n = h.size
    m = n // 32
    bm = h.reshape(m, 32).mean(axis=1)
    return np.repeat(bm, 32)


def _perturb_blocks(h, sigma, rng, width_frac=0.10):
    """Multiplicative zero-mean perturbation on a random contiguous window of
    block-mean cells (block size 32), mass-preserving."""
    n = h.size
    if n % 32 != 0:
        return h.copy()
    m = n // 32
    hb = h.reshape(m, 32).mean(axis=1)
    w = max(1, int(round(width_frac * m)))
    if w >= m:
        lo, hi = 0, m
    else:
        lo = rng.randint(0, m - w)
        hi = lo + w
    noise = rng.randn(hi - lo) * sigma
    # zero-mean over the window
    noise -= noise.mean()
    hb_new = hb.copy()
    hb_new[lo:hi] = hb[lo:hi] * (1.0 + noise)
    hb_new = np.clip(hb_new, 0, None)
    # preserve total mass
    s_old = hb.sum()
    s_new = hb_new.sum()
    if s_new > 0:
        hb_new *= s_old / s_new
    return np.repeat(hb_new, 32)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    alloc_stop = t0 + budget_seconds * 0.80

    rng = np.random.RandomState(12345)

    # ---- establish base ----
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            if base.size != 104992:
                if _is_32fold(base):
                    base = _reconstruct_32fold(base)
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%) before: %.4f" % _frac_near_max(best, 1e-3))

    # ---- arms: (branch, sigma) ----
    sigmas = [3e-3, 3e-4, 3e-5]
    arms = []
    for s in sigmas:
        arms.append(('A', s))
        arms.append(('B', s))
    arms.append(('C', None))  # control

    arm_gain = {a: 0.0 for a in arms}
    arm_cpu = {a: 0.0 for a in arms}
    arm_accepts = {a: 0 for a in arms}
    arm_tries = {a: 0 for a in arms}

    def run_quantum(arm):
        nonlocal best, bestR
        branch, sigma = arm
        cpu_start = time.process_time()
        q_deadline = min(deadline, cpu_start + 0.8)
        try:
            if branch == 'C':
                # control: unperturbed beta-ladder window polish
                h = best
                for beta in (1e5, 1e7):
                    if time.process_time() >= q_deadline - 0.05:
                        break
                    win = _peak_window(h, pad_frac=0.1, extra=96)
                    h = _lbfgs_block(h, win, 30, q_deadline, beta=beta)
                cand = h
            else:
                hpert = _perturb_blocks(best, sigma, rng)
                hpert = _rescale(hpert)
                if branch == 'A':
                    cand = _lbfgs_block(hpert, np.arange(hpert.size), 60,
                                        q_deadline, tie=True)
                else:  # B
                    win = _peak_window(hpert, pad_frac=0.1, extra=96)
                    cand = _lbfgs_block(hpert, win, 60, q_deadline, beta=1e7)
        except Exception:
            cand = best
        cpu_used = time.process_time() - cpu_start
        r = R_of(cand)
        arm_tries[arm] += 1
        arm_cpu[arm] += max(cpu_used, 1e-6)
        if r > bestR + 1e-15:
            gain = r - bestR
            best, bestR = cand.copy(), r
            arm_gain[arm] += gain
            arm_accepts[arm] += 1
        return r

    def pick_arm():
        if rng.rand() < 0.15:
            return arms[rng.randint(len(arms))]
        # highest cumulative dR per second
        best_arm = arms[0]
        best_rate = -1.0
        for a in arms:
            rate = arm_gain[a] / max(arm_cpu[a], 1e-6)
            if rate > best_rate:
                best_rate = rate
                best_arm = a
        return best_arm

    # ---- first pass: one quantum per arm ----
    for a in arms:
        if time.process_time() >= alloc_stop:
            break
        run_quantum(a)

    # ---- adaptive race ----
    qcount = len(arms)
    while time.process_time() < alloc_stop:
        a = pick_arm()
        run_quantum(a)
        qcount += 1
        if qcount % 10 == 0:
            print("  q%d best=%.12f" % (qcount, bestR))

    # ---- per-arm table ----
    print("arm | tries | accepts | gain | cpu | rate")
    for a in arms:
        rate = arm_gain[a] / max(arm_cpu[a], 1e-6)
        print("  %s sigma=%s | %d | %d | %.3e | %.2fs | %.3e"
              % (a[0], a[1], arm_tries[a], arm_accepts[a],
                 arm_gain[a], arm_cpu[a], rate))
    print("frac near max (0.1%%) after alloc: %.4f" % _frac_near_max(best, 1e-3))

    # ---- final polish: alternating full tie / peak-window ----
    pads = [0.05, 0.03]
    pi = 0
    while time.process_time() < deadline - 2.0:
        if time.process_time() < deadline - 2.0:
            h = _lbfgs_block(best, np.arange(best.size), 150,
                             min(deadline - 1.5, time.process_time() + 4.0),
                             tie=True)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
        if time.process_time() < deadline - 1.0:
            pad = pads[pi % len(pads)]
            pi += 1
            win = _peak_window(best, pad_frac=pad, extra=96)
            h = _lbfgs_block(best, win, 300,
                             min(deadline - 0.5, time.process_time() + 3.0),
                             tie=True)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r

    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(best, np.arange(best.size), 200,
                         deadline - 0.2, tie=True)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    # alternative: a perturbed-construction candidate if genuinely different
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h, tol=1e-10):
    """Tie-averaged max gradient: all knots within tol of max share equally."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    mask = Lf >= mx - tol * max(1.0, mx)
    cnt = mask.sum()
    if cnt > 0:
        gLf[mask] += (1.0 / mx) / cnt
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_tau(h, tau, kappa):
    """Variance-penalty objective: penalise knots near max with soft-max weighting.
    Uses a smooth surrogate: maximize num/(s^2 * (mx + kappa*std_of_top)) approx.
    Simpler: use the beta objective with beta scaled by 1/tau effectively.
    We implement a kappa-weighted soft max: sm = mx + kappa * weighted spread."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    # soft max with temperature related to tau
    beta = 1.0 / max(1e-6, (1.0 - tau) * mx + 1e-12)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    # kappa penalty: add kappa * (soft-mean of (mx - Lf)) to denominator
    gap = np.sum(w * (mx - Lf))
    denom = sm + kappa * gap
    gLf = -dq / num
    # gradient of denom wrt Lf: from sm (w/sm) and gap (-w + ...)
    gLf += w / denom
    gLf += -kappa * w / denom
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(denom)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.05, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _near_max_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _block_mean(h, Nq):
    n = h.size
    if n == Nq:
        return h.copy()
    # resample to Nq via block averaging / interpolation
    x_old = np.linspace(0, 1, n, endpoint=False)
    x_new = np.linspace(0, 1, Nq, endpoint=False)
    return np.interp(x_new, x_old, h)


def _lift(h, N):
    n = h.size
    if n == N:
        return h.copy()
    x_old = np.linspace(0, 1, n, endpoint=False)
    x_new = np.linspace(0, 1, N, endpoint=False)
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    f0 = _near_max_fracs(best)
    print("base R=%.9f N=%d fracs=%.4f/%.4f/%.4f" %
          (bestR, best.size, f0[0], f0[1], f0[2]))

    alt_best = None
    alt_bestR = -1.0

    def consider(h, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if h is None:
            return
        h = _rescale(np.clip(h, 0, None))
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR, origin = h.copy(), r, tag
            f = _near_max_fracs(best)
            print("%s NEW BEST R=%.9f fracs=%.4f/%.4f/%.4f" %
                  (tag, bestR, f[0], f[1], f[2]))
        elif r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r
        return h

    # ---- Stage 1: full-array tie L-BFGS ----
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5,
                            lambda hh: _fun_grad_tie(hh, 1e-10))
        consider(ht, 'tie_all')

    # ---- Stage 2: beta ladder on peak window ----
    if time.process_time() < deadline - 2.0:
        work = best.copy()
        for beta in [1e4, 1e5, 1e6, 1e7, 1e8]:
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(work, tol=0.95, pad_frac=0.05, extra=64)
            ht = _lbfgs_block(work, win, 120, deadline - 0.5,
                              lambda hh, b=beta: _fun_grad_beta(hh, b))
            r = R_of(ht)
            if r > R_of(work) + 1e-14:
                work = ht
                consider(ht, 'beta%g' % beta)

    # ---- Stage 3: coarse block-mean flat-top ladder ----
    if time.process_time() < deadline - 2.0:
        for Nq in [256, 1024]:
            if time.process_time() >= deadline - 1.0:
                break
            cq = _block_mean(best, Nq)
            cq = _rescale(np.clip(cq, 0, None))
            for tau in [0.9, 0.8, 0.7, 0.6]:
                for kappa in [3, 10, 30, 100]:
                    if time.process_time() >= deadline - 1.0:
                        break
                    ht = _lbfgs_all_pos(cq, 100, deadline - 0.5,
                                        lambda hh, t=tau, k=kappa:
                                        _fun_grad_tau(hh, t, k))
                    r = R_of(ht)
                    if r > R_of(cq) + 1e-14:
                        cq = ht
            # lift back to best.size
            hl = _lift(cq, best.size)
            hl = _rescale(np.clip(hl, 0, None))
            consider(hl, 'block%d' % Nq)
            # tie re-polish
            if time.process_time() < deadline - 1.0:
                ht = _lbfgs_all_pos(hl, 150, deadline - 0.5,
                                    lambda hh: _fun_grad_tie(hh, 1e-10))
                consider(ht, 'block%d+tie' % Nq)

    # ---- Stage 4: 2x prolongation + tie polish ----
    if time.process_time() < deadline - 2.0:
        N2 = 2 * best.size
        if N2 <= 1000000:
            h2 = _lift(best, N2)
            h2 = _rescale(np.clip(h2, 0, None))
            ht = _lbfgs_all_pos(h2, 200, deadline - 0.5,
                                lambda hh: _fun_grad_tie(hh, 1e-10))
            consider(ht, 'prolong2x')
            # beta ladder on finer grid
            work = ht
            for beta in [1e5, 1e6, 1e7]:
                if time.process_time() >= deadline - 1.0:
                    break
                win = _peak_window(work, tol=0.95, pad_frac=0.05, extra=128)
                ht2 = _lbfgs_block(work, win, 120, deadline - 0.5,
                                   lambda hh, b=beta: _fun_grad_beta(hh, b))
                if R_of(ht2) > R_of(work) + 1e-14:
                    work = ht2
                    consider(ht2, 'prolong2x+beta%g' % beta)

    # ---- Final tie polish on best ----
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3,
                            lambda hh: _fun_grad_tie(hh, 1e-10))
        consider(ht, 'final_tie')

    f = _near_max_fracs(best)
    print("final R=%.9f origin=%s N=%d fracs=%.4f/%.4f/%.4f (start %.9f)" %
          (bestR, origin, best.size, f[0], f[1], f[2], start_bestR))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, mode='sharp', beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if mode == 'beta':
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif mode == 'tie':
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.5, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(1234567)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
        else:
            base = None
    else:
        base = None

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)

    baseR = R_of(base)
    print("base R=%.7f (N=%d)" % (baseR, base.size))

    # Prolong to 2x grid
    H2 = _rescale(np.repeat(base, 2))
    H2R = R_of(H2)
    print("2x prolong R=%.7f (N=%d)" % (H2R, H2.size))

    best_fine = H2
    best_fineR = H2R

    # Main optimization loop on the 2x grid, alternating full/peak-window/tie
    rnd = 0
    while time.process_time() < deadline - 1.5:
        rnd += 1
        improved = False

        # (a) full sharp lbfgs
        H = _lbfgs_block(best_fine, np.arange(best_fine.size), 200, deadline, 'sharp')
        HR = R_of(H)
        if HR > best_fineR + 1e-13:
            best_fine, best_fineR = H, HR
            improved = True
            print("  r%d sharp R=%.7f" % (rnd, HR))
        if time.process_time() >= deadline - 1.2:
            break

        # (b) peak-window polish
        free = _peak_window(best_fine, tol=0.9995, pad_frac=0.5, extra=256)
        Hq = _lbfgs_block(best_fine, free, 200, deadline, 'sharp')
        HqR = R_of(Hq)
        if HqR > best_fineR + 1e-13:
            best_fine, best_fineR = Hq, HqR
            improved = True
            print("  r%d peak R=%.7f" % (rnd, HqR))
        if time.process_time() >= deadline - 1.2:
            break

        # (c) tie-aware polish (spreads peak flatness)
        Ht = _lbfgs_block(best_fine, free, 150, deadline, 'tie')
        HtR = R_of(Ht)
        if HtR > best_fineR + 1e-13:
            best_fine, best_fineR = Ht, HtR
            improved = True
            print("  r%d tie R=%.7f" % (rnd, HtR))
        if time.process_time() >= deadline - 1.2:
            break

        # (d) beta soft-max polish (encourages flat peak)
        Hb = _lbfgs_block(best_fine, np.arange(best_fine.size), 150, deadline,
                          'beta', beta=1e6)
        HbR = R_of(Hb)
        if HbR > best_fineR + 1e-13:
            best_fine, best_fineR = Hb, HbR
            improved = True
            print("  r%d beta R=%.7f" % (rnd, HbR))
        if time.process_time() >= deadline - 1.2:
            break

        if not improved:
            # stochastic perturbation around peak
            Lf = _knots(best_fine)
            m = int(np.argmax(Lf))
            win = int(rng.integers(96, 384))
            lo = max(0, m - win)
            hi = min(best_fine.size, m + win)
            if hi > lo:
                sigma = float(rng.uniform(0.01, 0.04))
                noise = rng.normal(0.0, sigma, size=hi - lo)
                k = 9
                if noise.size >= k:
                    noise = np.convolve(noise, np.ones(k) / k, mode='same')
                Hp = best_fine.copy()
                Hp[lo:hi] = Hp[lo:hi] * np.exp(noise)
                Hp = _rescale(Hp)
                Hp = _lbfgs_block(Hp, np.arange(Hp.size), 100, deadline, 'sharp')
                HpR = R_of(Hp)
                if HpR > best_fineR + 1e-13:
                    best_fine, best_fineR = Hp, HpR
                    print("  r%d stoch R=%.7f" % (rnd, HpR))

    Lf = _knots(best_fine)
    argmax_frac = float(np.argmax(Lf)) / max(1, best_fine.size)
    print("final R=%.7f (N=%d, zeros %.1f%%, argmax frac %.3f) vs base %.7f" %
          (best_fineR, best_fine.size, 100.0 * np.mean(best_fine <= 0),
           argmax_frac, baseR))

    if best_fineR > baseR + 1e-12:
        return {"best": best_fine, "alternative": base}
    return {"best": base, "alternative": best_fine}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _lanczos(h, beta, k, deadline):
    n = h.size
    Q = np.zeros((k + 1, n))
    alpha = np.zeros(k)
    betav = np.zeros(k)
    q = np.random.RandomState(0).randn(n)
    q /= np.linalg.norm(q)
    Q[0] = q
    for j in range(k):
        if time.process_time() > deadline:
            k = j
            break
        w = _hv(Q[j], h, beta)
        for _ in range(2):
            for i in range(j + 1):
                c = Q[i] @ w
                w -= c * Q[i]
        a = w @ Q[j]
        alpha[j] = a
        w -= a * Q[j]
        for _ in range(2):
            for i in range(j + 1):
                c = Q[i] @ w
                w -= c * Q[i]
        b = np.linalg.norm(w)
        betav[j] = b
        if b < 1e-12:
            k = j + 1
            break
        Q[j + 1] = w / b
    kk = min(k, len(alpha))
    T = np.diag(alpha[:kk])
    if kk > 1:
        T += np.diag(betav[:kk - 1], 1) + np.diag(betav[:kk - 1], -1)
    evals, evecs = np.linalg.eigh(T)
    V = Q[:kk].T @ evecs
    return evals, V


def _dq_of(Lf):
    a = Lf[:-1]; b = Lf[1:]
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return dq


def _hv(v, h, beta):
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    e = np.exp(np.clip(beta * (Lf - Lf[m]), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return np.zeros_like(h)
    w = e / Z
    sm = Lf[m] + np.log(Z) / beta
    dLf = np.concatenate(([0.0], 2.0 * _conv(v), [0.0]))
    dnum = dq @ dLf
    dq2 = _dq_of(dLf)
    de = beta * e * (dLf - dLf[m])
    dZ = de.sum()
    dw = de / Z - e * dZ / (Z * Z)
    dsm = dLf[m] + (dZ / Z) / beta
    dgLf = -(dq2 / num - dq * dnum / (num * num)) + (dw / sm - w * dsm / (sm * sm))
    gLf = -dq / num + w / sm
    Hv = _backprop(dgLf, h) + _backprop(gLf, v) - 2.0 * v.sum() / (s * s)
    return Hv


def _refine(h, deadline, rounds=8):
    best = h.copy()
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.5, time.process_time() + 5.0))
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        if time.process_time() < deadline - 1.0:
            for beta in (50.0, 200.0, 1e7):
                if time.process_time() >= deadline - 0.6:
                    break
                pb = _lbfgs_block(best, np.arange(best.size), 200,
                                 min(deadline - 0.4, time.process_time() + 4.0),
                                 beta=beta)
                rb = R_of(pb)
                if rb > bestR:
                    best, bestR = pb, rb
        win = _peak_window(best, pad_frac=0.10, extra=128)
        pw = _lbfgs_block(best, win, 250,
                         min(deadline - 0.4, time.process_time() + 4.0),
                         beta=1e7)
        rw = R_of(pw)
        if rw > bestR:
            best, bestR = pw, rw
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Try to produce a genuinely different construction via Ritz perturbation.
    alt = None
    altR = 0.0
    try:
        beta = 1e7
        evals, V = _lanczos(best, beta, 30, min(deadline - 20.0,
                                                 time.process_time() + 12.0))
        if V.shape[1] > 0:
            order = np.argsort(evals)
            neg = [i for i in order if evals[i] < 0]
            chosen = neg[:4] if neg else order[:3]
            hmax = best.max()
            cands = []
            for ci in chosen:
                v = V[:, ci].copy()
                nv = np.linalg.norm(v)
                if nv <= 0:
                    continue
                v /= nv
                vmax = np.abs(v).max()
                if vmax <= 0:
                    continue
                for sign in (1.0, -1.0):
                    for f in (0.05, 0.2):
                        t = f * hmax / vmax
                        cand = np.clip(best + sign * t * v, 0, None)
                        if cand.sum() <= 0:
                            continue
                        cand = _rescale(cand)
                        cands.append((R_of(cand), cand))
            cands.sort(key=lambda x: -x[0])
            for r0, c in cands[:2]:
                if time.process_time() >= deadline - 10.0:
                    break
                sub = min(deadline - 8.0, time.process_time() + 6.0)
                ht, rt = _refine(c, sub, rounds=4)
                if rt > altR:
                    alt, altR = ht, rt
            if alt is not None:
                print("ritz alt R=%.7f" % altR)
    except Exception as e:
        print("ritz failed: %s" % e)

    if alt is not None and altR > bestR + 1e-13:
        best, bestR = alt, altR
        origin = 'ritz'

    # Main refinement on best.
    ht, rt = _refine(best, deadline - 0.5, rounds=10)
    if rt > bestR + 1e-13:
        best, bestR = ht, rt

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001)))

    if bestR >= start_bestR - 1e-13:
        return best
    if alt is not None and altR > 0:
        return {"best": best, "alternative": alt}
    return {"best": best, "alternative": best}

