def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------- quotient-space machinery (stride S) ----------
STRIDE = 32


def _q_knots(c):
    Q = np.convolve(c, c)
    n = c.size
    Qfull = np.zeros(n)
    m = min(n, Q.size)
    Qfull[:m] = Q[:m]
    Qprev = np.zeros(n)
    Qprev[1:] = Qfull[:-1]
    r = np.arange(STRIDE, dtype=float)
    L = np.zeros(STRIDE * n + 1)
    Lint = (r[None, :] + 1.0) * Qfull[:, None] + (STRIDE - 1 - r[None, :]) * Qprev[:, None]
    L[1:STRIDE * n + 1] = Lint.reshape(-1)
    return L


def _q_R(c):
    s = c.sum()
    if s <= 0:
        return 0.0
    L = _q_knots(c)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _q_fun_grad(c):
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    L = _q_knots(c)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(L)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    mx = L.max()
    m = int(np.argmax(L))
    gL = -dq / num
    gL[m] += 1.0 / mx
    n = c.size
    gLint = gL[1:STRIDE * n + 1].reshape(n, STRIDE)
    r = np.arange(STRIDE, dtype=float)
    gQ = np.zeros(n)
    gQ += np.sum(gLint * (r[None, :] + 1.0), axis=1)
    gQprev = np.sum(gLint * (STRIDE - 1 - r[None, :]), axis=1)
    gQfull = gQ.copy()
    gQfull[:-1] += gQprev[1:]
    gc = 2.0 * np.correlate(gQfull, c, mode='full')[:n]
    gc += 2.0 / s
    F = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return F, gc


def _q_lbfgs(c0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c0
    c0 = np.clip(c0, 0, None)
    if c0.sum() <= 0:
        return c0
    x0 = c0.copy()

    def f(x):
        cc = np.clip(x, 0.0, None)
        val, g = _q_fun_grad(cc)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.clip(res.x, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%) before: %.4f" % _frac_near_max(best, 1e-3))

    alt_best = None
    altR = -1.0

    # ---- continuous beta-homotopy polish of the full construction ----
    # Smooth max via softmax with increasing beta converges to the tie-aware
    # objective, but avoids getting stuck on a single knot. This is the
    # substantial change: full-N softmax homotopy, then final tie polish.
    if best.size <= 200000:
        h_cur = best.copy()
        r_cur = bestR
        for beta in (50.0, 200.0, 1000.0, 5000.0):
            if time.process_time() >= deadline - 6.0:
                break
            tlim = min(deadline - 5.0, time.process_time() + 3.0)
            h_new = _lbfgs_block(h_cur, np.arange(h_cur.size), 150, tlim, beta=beta)
            r_new = R_of(h_new)
            print("beta=%.0f full-N R=%.12f (frac=%.4f)"
                  % (beta, r_new, _frac_near_max(h_new, 1e-3)))
            if r_new >= r_cur - 1e-12:
                h_cur, r_cur = h_new, r_new
            if r_new > altR:
                altR, alt_best = r_new, h_new.copy()
            if r_new > bestR + 1e-15:
                best, bestR = h_new.copy(), r_new

        # final tie-aware polish
        if time.process_time() < deadline - 1.5:
            tlim = min(deadline - 1.0, time.process_time() + 3.0)
            h_new = _lbfgs_block(h_cur, np.arange(h_cur.size), 200, tlim, tie=True)
            r_new = R_of(h_new)
            print("final tie polish R=%.12f" % r_new)
            if r_new > altR:
                altR, alt_best = r_new, h_new.copy()
            if r_new > bestR + 1e-15:
                best, bestR = h_new.copy(), r_new

        # peak-window refinement
        for pad in (0.05, 0.03, 0.02):
            if time.process_time() >= deadline - 0.6:
                break
            win = _peak_window(best, pad_frac=pad, extra=96)
            ht = _lbfgs_block(best, win, 200,
                              min(deadline - 0.3, time.process_time() + 1.5), tie=True)
            r = R_of(ht)
            if r > altR:
                altR, alt_best = r, ht.copy()
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r

    print("frac near max (0.1%%) after: %.4f" % _frac_near_max(best, 1e-3))

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
