def _argmax_loc(h):
    Lf = _knots(h)
    if Lf.size <= 1:
        return 0.0
    return float(np.argmax(Lf)) / (Lf.size - 1)


# ---------- H22 warp experiment helpers ----------

def _warp_nodes(N, a, K=13):
    """Control nodes x_k = k*N/(K-1), offsets a_k. Return (xs, ys) monotone."""
    K = len(a)
    xk = np.linspace(0.0, float(N), K)
    step = float(N) / (K - 1)
    min_step = 0.2 * step
    yk = xk + np.asarray(a, dtype=float) * step  # a is in units of step
    # enforce strictly increasing with min_step
    yk = yk.copy()
    yk[0] = 0.0
    for k in range(1, K):
        if yk[k] < yk[k - 1] + min_step:
            yk[k] = yk[k - 1] + min_step
    # clip to [0, N]
    yk = np.clip(yk, 0.0, float(N))
    # re-enforce after clip
    for k in range(1, K):
        if yk[k] < yk[k - 1] + min_step:
            yk[k] = yk[k - 1] + min_step
    if yk[-1] > N:
        yk[-1] = float(N)
    return xk, yk


def _pullback(h, a):
    """Mass pullback of h under monotone map phi with nodes (xk, yk)."""
    N = h.size
    xk, yk = _warp_nodes(N, a)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    # uniform new grid points t_i = phi^{-1}(i), i=0..N
    xs = np.arange(N + 1, dtype=float)
    # phi maps xk -> yk; inverse: given y (target x in new coords), find old x
    # np.interp needs increasing xp; yk is increasing
    t = np.interp(xs, yk, xk)
    t = np.clip(t, 0.0, float(N))
    # cum interpolated at t
    vals = np.interp(t, np.arange(N + 1, dtype=float), cum)
    g = np.diff(vals)
    g = np.clip(g, 0.0, None)
    return g


def _warp_objective(h, a):
    g = _pullback(h, a)
    if g.sum() <= 0:
        return 0.0
    return R_of(g)


def _optimize_warp(h, deadline, K=13):
    from scipy.optimize import minimize as _min
    a0 = np.zeros(K)
    best_a = a0.copy()
    best_r = _warp_objective(h, a0)
    # Nelder-Mead
    t_lim = min(deadline - 20.0, time.process_time() + 25.0)
    if time.process_time() < t_lim - 1.0:
        def f(a):
            if time.process_time() > t_lim:
                raise TimeoutError
            return -_warp_objective(h, a)
        try:
            res = _min(f, a0, method='Nelder-Mead',
                       options={'maxiter': 400, 'xatol': 1e-6, 'fatol': 1e-12})
            if res is not None and np.all(np.isfinite(res.x)):
                r = _warp_objective(h, res.x)
                if r > best_r:
                    best_r = r
                    best_a = res.x.copy()
        except (TimeoutError, Exception):
            pass
    # L-BFGS-B with 2-point finite differences
    t_lim2 = min(deadline - 10.0, time.process_time() + 20.0)
    if time.process_time() < t_lim2 - 1.0:
        hstep = 1e-4
        def fg(a):
            if time.process_time() > t_lim2:
                raise TimeoutError
            r0 = _warp_objective(h, a)
            g = np.zeros_like(a)
            for k in range(a.size):
                ap = a.copy(); ap[k] += hstep
                g[k] = (_warp_objective(h, ap) - r0) / hstep
            return -r0, -g
        try:
            res = _min(fg, best_a, jac=True, method='L-BFGS-B',
                       bounds=[(-0.15, 0.15)] * K,
                       options={'maxiter': 200, 'ftol': 1e-18, 'gtol': 1e-14})
            if res is not None and np.all(np.isfinite(res.x)):
                r = _warp_objective(h, res.x)
                if r > best_r:
                    best_r = r
                    best_a = res.x.copy()
        except (TimeoutError, Exception):
            pass
    return best_a, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))
    print("argmax loc=%.4f near-max frac 0.1/1/5%%: %.4f/%.4f/%.4f"
          % (_argmax_loc(best), _frac_near_max(best, 1e-3),
             _frac_near_max(best, 1e-2), _frac_near_max(best, 5e-2)))

    # ---- H22: abscissa warp experiment ----
    alt_best = None
    altR = -1.0
    if time.process_time() < deadline - 15.0:
        a_opt, r_warp = _optimize_warp(best, deadline, K=13)
        maxa = float(np.max(np.abs(a_opt))) if a_opt.size else 0.0
        print("warp: max|a|=%.5f R=%.12f" % (maxa, r_warp))
        h_warp = _pullback(best, a_opt)
        h_warp = _rescale(h_warp)
        rw = R_of(h_warp)
        print("warped raster R=%.12f argmax=%.4f near-max 0.1/1/5%%: %.4f/%.4f/%.4f"
              % (rw, _argmax_loc(h_warp), _frac_near_max(h_warp, 1e-3),
                 _frac_near_max(h_warp, 1e-2), _frac_near_max(h_warp, 5e-2)))
        if rw > altR:
            altR = rw
            alt_best = h_warp.copy()
        if rw > bestR + 1e-15:
            best, bestR = h_warp.copy(), rw

        # full-array tie polish (~10 s)
        if time.process_time() < deadline - 8.0:
            pol = _lbfgs_block(h_warp, np.arange(h_warp.size), 300,
                               min(deadline - 7.0, time.process_time() + 10.0),
                               tie=True)
            rp = R_of(pol)
            print("warped+polish R=%.12f" % rp)
            if rp > altR:
                altR = rp
                alt_best = pol.copy()
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

        # peak-window beta=1e7 polish (pad 0.05)
        if time.process_time() < deadline - 4.0:
            win = _peak_window(h_warp, pad_frac=0.05, extra=96)
            hb = _lbfgs_block(h_warp, win, 300,
                              min(deadline - 3.0, time.process_time() + 5.0),
                              beta=1e7)
            rb = R_of(hb)
            print("warped+beta polish R=%.12f" % rb)
            if rb > altR:
                altR = rb
                alt_best = hb.copy()
            if rb > bestR + 1e-15:
                best, bestR = hb.copy(), rb

    print("argmax loc after=%.4f near-max frac 0.1/1/5%%: %.4f/%.4f/%.4f"
          % (_argmax_loc(best), _frac_near_max(best, 1e-3),
             _frac_near_max(best, 1e-2), _frac_near_max(best, 5e-2)))

    # safety net: tie polish on best
    if time.process_time() < deadline - 2.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 1.0, time.process_time() + 4.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.05, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- Block-mean reduction and 2x lift ----

def _block_mean(h, Nq):
    n = h.size
    if Nq >= n:
        return h.copy()
    if n % Nq == 0:
        return h.reshape(Nq, n // Nq).mean(axis=1)
    edges = np.linspace(0, n, Nq + 1)
    idx = np.round(edges).astype(int)
    out = np.zeros(Nq)
    for i in range(Nq):
        a, b = idx[i], idx[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _lift2(hq, N):
    """2x upsample with mass-preserving repeat + [0.25,0.5,0.25] smoothing,
    repeated until reaching N (or close)."""
    h = hq.copy()
    while h.size < N:
        n = h.size
        out = np.zeros(2 * n)
        out[0::2] = h
        out[1::2] = h
        ker = np.array([0.25, 0.5, 0.25])
        sm = np.convolve(out, ker, mode='same')
        # preserve total mass
        if sm.sum() > 0:
            sm *= (h.sum() / sm.sum())
        h = sm
    if h.size > N:
        # block-mean down
        h = _block_mean(h, N)
    return _rescale(h)


def _fun_grad_lin(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    thr = tau * mx
    mask = Lf >= thr
    if np.any(mask):
        Lm = Lf[mask].mean()
        var = np.mean((Lf[mask] - Lm) ** 2)
    else:
        Lm = mx
        var = 0.0
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    if np.any(mask) and var > 0:
        cnt = np.sum(mask)
        dvar = 2.0 * (Lf - Lm) / cnt
        gLf += kappa * dvar
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * var
    return val, grad


def _lbfgs_lin(h0, maxiter, deadline, tau, kappa):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_lin(hh, tau, kappa)

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


# ---- Quotient arms ----

def _arm_A(hq, deadline):
    return _lbfgs_block(hq, np.arange(hq.size), 100, deadline, tie=True)


def _arm_B(hq, deadline):
    h = hq
    for beta in (1e4, 1e6, 1e8):
        if time.process_time() >= deadline - 0.05:
            return h
        win = _peak_window(h, tol=0.95, pad_frac=0.05, extra=32)
        h = _lbfgs_block(h, win, 60, deadline, beta=beta)
    return h


def _arm_C(hq, deadline):
    # lin-form flat-top with tau/kappa cycling
    combos = [(0.9, 10.0), (0.9, 100.0), (0.7, 10.0), (0.7, 100.0)]
    best = hq
    bestR = R_of(hq)
    for tau, kappa in combos:
        if time.process_time() >= deadline - 0.05:
            break
        h = _lbfgs_lin(hq, 100, deadline, tau, kappa)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
    return best


def _arm_D(hq, deadline):
    hu = _lift2(hq, 2 * hq.size)
    hu = _lbfgs_block(hu, np.arange(hu.size), 100, deadline, tie=True)
    hq2 = _block_mean(hu, hq.size)
    return _rescale(hq2)


_ARMS = {'A': _arm_A, 'B': _arm_B, 'C': _arm_C, 'D': _arm_D}


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best_full = _rescale(base)
            startR = R_of(best_full)
        else:
            best_full, startR = None, 0.0
    else:
        best_full, startR = None, 0.0

    if best_full is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best_full = _rescale(h)
        startR = R_of(best_full)

    N = best_full.size
    print("base R=%.9f (N=%d)" % (startR, N))

    # Build quotient
    Nq_target = 3281
    if N % Nq_target == 0:
        hq = best_full.reshape(Nq_target, N // Nq_target).mean(axis=1)
    else:
        hq = _block_mean(best_full, Nq_target)
    hq = _rescale(hq)
    Nq = hq.size
    print("quotient Nq=%d (N/Nq=%d)" % (Nq, N // Nq))
    qR = R_of(hq)
    print("quotient R=%.9f" % qR)

    # Race state
    best_q = hq.copy()
    best_qR = qR
    ema_slope = {k: 0.0 for k in _ARMS}
    cum_dR = {k: 0.0 for k in _ARMS}
    n_quanta = {k: 0 for k in _ARMS}
    lastR = {k: None for k in _ARMS}

    # Reserve time for final lift + polish
    lift_reserve = 18.0
    race_stop = deadline - lift_reserve
    quantum_seconds = 6.0

    rng = np.random.RandomState(12345)
    qcount = 0
    while time.process_time() < race_stop - quantum_seconds * 0.5:
        # choose arm
        if qcount % 4 == 0:
            # forced round-robin exploration
            name = list(_ARMS.keys())[(qcount // 4) % len(_ARMS)]
        else:
            name = max(_ARMS.keys(), key=lambda k: ema_slope[k])

        cpu_start = time.process_time()
        q_deadline = min(race_stop, cpu_start + quantum_seconds)
        try:
            h_new = _ARMS[name](best_q, q_deadline)
        except Exception:
            h_new = best_q
        cpu_used = max(1e-6, time.process_time() - cpu_start)
        r_new = R_of(h_new)
        dR = r_new - best_qR
        cum_dR[name] += dR
        n_quanta[name] += 1
        inst_slope = dR / cpu_used
        ema_slope[name] = 0.6 * ema_slope[name] + 0.4 * inst_slope
        if r_new > best_qR + 1e-15:
            best_q = h_new.copy()
            best_qR = r_new
        print("  q %s: R=%.12f dR=%+.3e cpu=%.2fs ema=%.3e best=%.12f"
              % (name, r_new, dR, cpu_used, ema_slope[name], best_qR))
        qcount += 1

    print("race done: best_qR=%.12f" % best_qR)
    print("arm | quanta | cum_dR | ema_slope")
    for k in _ARMS:
        print("  %s | %d | %+.3e | %.3e"
              % (k, n_quanta[k], cum_dR[k], ema_slope[k]))

    # ---- Lift best quotient to full N ----
    if time.process_time() < deadline - 2.0:
        lifted = _lift2(best_q, N)
        liftR = R_of(lifted)
        print("lift R=%.12f (loss %.3e vs quotient %.12f)"
              % (liftR, best_qR - liftR, best_qR))
    else:
        lifted = best_full
        liftR = startR

    # pick better of lifted vs start
    if liftR > startR:
        best_full = lifted
        bestR = liftR
    else:
        bestR = startR

    # ---- Final polish at full N ----
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(best_full, np.arange(best_full.size), 200,
                         min(deadline - 0.3, time.process_time() + 8.0),
                         tie=True)
        r = R_of(h)
        if r > bestR + 1e-15:
            best_full, bestR = h, r
        print("after full tie: R=%.12f" % bestR)

    if time.process_time() < deadline - 0.3:
        win = _peak_window(best_full, tol=0.95, pad_frac=0.05, extra=96)
        h = _lbfgs_block(best_full, win, 200,
                         deadline - 0.1, beta=1e7)
        r = R_of(h)
        if r > bestR + 1e-15:
            best_full, bestR = h, r
        print("after beta polish: R=%.12f" % bestR)

    if bestR < startR:
        best_full = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best_full.size, _tie_count(best_full)))

    result = {"best": best_full}
    # alternative: the lifted quotient if it's genuinely different and not better
    if liftR <= startR + 1e-14 and lifted.size == N:
        result["alternative"] = lifted
    return result

