    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- Block-mean reduction and 2x lift ----

def _block_mean(h, Nq):
    n = h.size
    if Nq >= n:
        return h.copy()
    if n % Nq == 0:
        return h.reshape(Nq, n // Nq).mean(axis=1)
    edges = np.linspace(0, n, Nq + 1)
    idx = np.round(edges).astype(int)
    out = np.zeros(Nq)
    for i in range(Nq):
        a, b = idx[i], idx[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _lift2(hq, N):
    """2x upsample with mass-preserving repeat + [0.25,0.5,0.25] smoothing,
    repeated until reaching N (or close)."""
    h = hq.copy()
    while h.size < N:
        n = h.size
        out = np.zeros(2 * n)
        out[0::2] = h
        out[1::2] = h
        ker = np.array([0.25, 0.5, 0.25])
        sm = np.convolve(out, ker, mode='same')
        # preserve total mass
        if sm.sum() > 0:
            sm *= (h.sum() / sm.sum())
        h = sm
    if h.size > N:
        # block-mean down
        h = _block_mean(h, N)
    return _rescale(h)


def _fun_grad_lin(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    thr = tau * mx
    mask = Lf >= thr
    if np.any(mask):
        Lm = Lf[mask].mean()
        var = np.mean((Lf[mask] - Lm) ** 2)
    else:
        Lm = mx
        var = 0.0
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    if np.any(mask) and var > 0:
        cnt = np.sum(mask)
        dvar = 2.0 * (Lf - Lm) / cnt
        gLf += kappa * dvar
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * var
    return val, grad


def _lbfgs_lin(h0, maxiter, deadline, tau, kappa):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_lin(hh, tau, kappa)

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


# ---- Quotient arms ----

def _arm_A(hq, deadline):
    return _lbfgs_block(hq, np.arange(hq.size), 100, deadline, tie=True)


def _arm_B(hq, deadline):
    h = hq
    for beta in (1e4, 1e6, 1e8):
        if time.process_time() >= deadline - 0.05:
            return h
        win = _peak_window(h, tol=0.95, pad_frac=0.05, extra=32)
        h = _lbfgs_block(h, win, 60, deadline, beta=beta)
    return h


def _arm_C(hq, deadline):
    # lin-form flat-top with tau/kappa cycling
    combos = [(0.9, 10.0), (0.9, 100.0), (0.7, 10.0), (0.7, 100.0)]
    best = hq
    bestR = R_of(hq)
    for tau, kappa in combos:
        if time.process_time() >= deadline - 0.05:
            break
        h = _lbfgs_lin(hq, 100, deadline, tau, kappa)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
    return best


def _arm_D(hq, deadline):
    hu = _lift2(hq, 2 * hq.size)
    hu = _lbfgs_block(hu, np.arange(hu.size), 100, deadline, tie=True)
    hq2 = _block_mean(hu, hq.size)
    return _rescale(hq2)


_ARMS = {'A': _arm_A, 'B': _arm_B, 'C': _arm_C, 'D': _arm_D}


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best_full = _rescale(base)
            startR = R_of(best_full)
        else:
            best_full, startR = None, 0.0
    else:
        best_full, startR = None, 0.0

    if best_full is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best_full = _rescale(h)
        startR = R_of(best_full)

    N = best_full.size
    print("base R=%.9f (N=%d)" % (startR, N))

    # Build quotient
    Nq_target = 3281
    if N % Nq_target == 0:
        hq = best_full.reshape(Nq_target, N // Nq_target).mean(axis=1)
    else:
        hq = _block_mean(best_full, Nq_target)
    hq = _rescale(hq)
    Nq = hq.size
    print("quotient Nq=%d (N/Nq=%d)" % (Nq, N // Nq))
    qR = R_of(hq)
    print("quotient R=%.9f" % qR)

    # Race state
    best_q = hq.copy()
    best_qR = qR
    ema_slope = {k: 0.0 for k in _ARMS}
    cum_dR = {k: 0.0 for k in _ARMS}
    n_quanta = {k: 0 for k in _ARMS}
    lastR = {k: None for k in _ARMS}

    # Reserve time for final lift + polish
    lift_reserve = 18.0
    race_stop = deadline - lift_reserve
    quantum_seconds = 6.0

    rng = np.random.RandomState(12345)
    qcount = 0
    while time.process_time() < race_stop - quantum_seconds * 0.5:
        # choose arm
        if qcount % 4 == 0:
            # forced round-robin exploration
            name = list(_ARMS.keys())[(qcount // 4) % len(_ARMS)]
        else:
            name = max(_ARMS.keys(), key=lambda k: ema_slope[k])

        cpu_start = time.process_time()
        q_deadline = min(race_stop, cpu_start + quantum_seconds)
        try:
            h_new = _ARMS[name](best_q, q_deadline)
        except Exception:
            h_new = best_q
        cpu_used = max(1e-6, time.process_time() - cpu_start)
        r_new = R_of(h_new)
        dR = r_new - best_qR
        cum_dR[name] += dR
        n_quanta[name] += 1
        inst_slope = dR / cpu_used
        ema_slope[name] = 0.6 * ema_slope[name] + 0.4 * inst_slope
        if r_new > best_qR + 1e-15:
            best_q = h_new.copy()
            best_qR = r_new
        print("  q %s: R=%.12f dR=%+.3e cpu=%.2fs ema=%.3e best=%.12f"
              % (name, r_new, dR, cpu_used, ema_slope[name], best_qR))
        qcount += 1

    print("race done: best_qR=%.12f" % best_qR)
    print("arm | quanta | cum_dR | ema_slope")
    for k in _ARMS:
        print("  %s | %d | %+.3e | %.3e"
              % (k, n_quanta[k], cum_dR[k], ema_slope[k]))

    # ---- Lift best quotient to full N ----
    if time.process_time() < deadline - 2.0:
        lifted = _lift2(best_q, N)
        liftR = R_of(lifted)
        print("lift R=%.12f (loss %.3e vs quotient %.12f)"
              % (liftR, best_qR - liftR, best_qR))
    else:
        lifted = best_full
        liftR = startR

    # pick better of lifted vs start
    if liftR > startR:
        best_full = lifted
        bestR = liftR
    else:
        bestR = startR

    # ---- Final polish at full N ----
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(best_full, np.arange(best_full.size), 200,
                         min(deadline - 0.3, time.process_time() + 8.0),
                         tie=True)
        r = R_of(h)
        if r > bestR + 1e-15:
            best_full, bestR = h, r
        print("after full tie: R=%.12f" % bestR)

    if time.process_time() < deadline - 0.3:
        win = _peak_window(best_full, tol=0.95, pad_frac=0.05, extra=96)
        h = _lbfgs_block(best_full, win, 200,
                         deadline - 0.1, beta=1e7)
        r = R_of(h)
        if r > bestR + 1e-15:
            best_full, bestR = h, r
        print("after beta polish: R=%.12f" % bestR)

    if bestR < startR:
        best_full = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best_full.size, _tie_count(best_full)))

    result = {"best": best_full}
    # alternative: the lifted quotient if it's genuinely different and not better
    if liftR <= startR + 1e-14 and lifted.size == N:
        result["alternative"] = lifted
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h, tol=1e-10):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    mask = Lf >= mx - tol * max(1.0, mx)
    cnt = mask.sum()
    if cnt > 0:
        gLf[mask] += (1.0 / mx) / cnt
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.05, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _near_max_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _argmax_loc(h):
    Lf = _knots(h)
    if Lf.size == 0:
        return 0.0
    return float(np.argmax(Lf)) / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 1e-15))


# ---- New: discrete support edits ----
def _edit_gap(h, amp):
    h = h.copy()
    nz = np.flatnonzero(h > 0)
    if nz.size < 2:
        return h
    lo, hi = nz[0], nz[-1]
    z = (h <= 0)
    i = lo
    while i <= hi:
        if z[i]:
            j = i
            while j <= hi and z[j]:
                j += 1
            run = j - i
            if run > 8:
                a = h[i - 1] if i - 1 >= 0 else 0.0
                b = h[j] if j < h.size else 0.0
                t = (np.arange(run) + 1.0) / (run + 1.0)
                ramp = (1.0 - t) * a + t * b
                mid = run // 2
                ramp[mid] *= amp
                h[i:j] = ramp
            i = j
        else:
            i += 1
    return h


def _edit_tail(h, amp, side='R', length=96):
    h = h.copy()
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    if side == 'R':
        last = nz[-1]
        base = h[last]
        k = np.arange(1, length + 1)
        tail = amp * base * (0.9 ** k)
        end = min(h.size, last + 1 + length)
        seg = tail[:end - (last + 1)]
        h[last + 1:end] = seg
    else:
        first = nz[0]
        base = h[first]
        k = np.arange(1, length + 1)
        tail = amp * base * (0.9 ** k)
        start = max(0, first - length)
        seg = tail[(length - (first - start)):]
        h[start:first] = seg
    return h


def _edit_prune(h, amp):
    h = h.copy()
    mx = h.max()
    if mx <= 0:
        return h
    h[h < amp * mx] = 0.0
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    f0 = _near_max_fracs(best)
    print("base R=%.9f N=%d fracs=%.4f/%.4f/%.4f zero=%.4f argmax=%.3f" %
          (bestR, best.size, f0[0], f0[1], f0[2],
           _zero_frac(best), _argmax_loc(best)))

    alt_best = None
    alt_bestR = -1.0

    def consider(h, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if h is None:
            return False
        h = _rescale(np.clip(h, 0, None))
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR, origin = h.copy(), r, tag
            f = _near_max_fracs(best)
            print("%s NEW BEST R=%.9f zero=%.4f argmax=%.3f fracs=%.4f/%.4f/%.4f" %
                  (tag, bestR, _zero_frac(best), _argmax_loc(best),
                   f[0], f[1], f[2]))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r
        return False

    # ---- Stage 1: full-array tie L-BFGS ----
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5,
                            lambda hh: _fun_grad_tie(hh, 1e-10))
        consider(ht, 'tie_all')

    # ---- Stage 2: beta ladder on peak window ----
    if time.process_time() < deadline - 2.0:
        work = best.copy()
        for beta in [1e4, 1e5, 1e6, 1e7, 1e8]:
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(work, tol=0.95, pad_frac=0.05, extra=64)
            ht = _lbfgs_block(work, win, 120, deadline - 0.5,
                              lambda hh, b=beta: _fun_grad_beta(hh, b))
            r = R_of(ht)
            if r > R_of(work) + 1e-14:
                work = ht
                consider(ht, 'beta%g' % beta)

    # ---- Stage 3: NEW discrete support edits ----
    edit_plan = []
    for amp in [1e-3, 1e-2, 1e-1]:
        edit_plan.append(('GAP', amp))
    for amp in [1e-2, 1e-1]:
        edit_plan.append(('TAILR', amp))
    for amp in [1e-2, 1e-1]:
        edit_plan.append(('TAILL', amp))
    for amp in [1e-4, 1e-3]:
        edit_plan.append(('PRUNE', amp))

    for mode, amp in edit_plan:
        if time.process_time() >= deadline - 3.0:
            break
        if mode == 'GAP':
            cand = _edit_gap(best, amp)
        elif mode == 'TAILR':
            cand = _edit_tail(best, amp, 'R')
        elif mode == 'TAILL':
            cand = _edit_tail(best, amp, 'L')
        else:
            cand = _edit_prune(best, amp)
        cand = _rescale(np.clip(cand, 0, None))
        # short tie polish
        ht = _lbfgs_all_pos(cand, 200, min(deadline - 0.5,
                                           time.process_time() + 3.0),
                            lambda hh: _fun_grad_tie(hh, 1e-10))
        accepted = consider(ht, '%s_%g' % (mode, amp))
        if accepted and time.process_time() < deadline - 2.0:
            # beta=1e7 peak-window polish
            win = _peak_window(best, tol=0.95, pad_frac=0.05, extra=64)
            ht2 = _lbfgs_block(best, win, 120,
                               min(deadline - 0.5,
                                   time.process_time() + 2.0),
                               lambda hh: _fun_grad_beta(hh, 1e7))
            consider(ht2, '%s_%g+beta' % (mode, amp))

    # ---- Stage 4: 2x prolongation + tie polish ----
    if time.process_time() < deadline - 2.0:
        N2 = 2 * best.size
        if N2 <= 1000000:
            x_old = np.linspace(0, 1, best.size, endpoint=False)
            x_new = np.linspace(0, 1, N2, endpoint=False)
            h2 = np.interp(x_new, x_old, best)
            h2 = _rescale(np.clip(h2, 0, None))
            ht = _lbfgs_all_pos(h2, 200, deadline - 0.5,
                                lambda hh: _fun_grad_tie(hh, 1e-10))
            consider(ht, 'prolong2x')

    # ---- Final tie polish on best ----
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3,
                            lambda hh: _fun_grad_tie(hh, 1e-10))
        consider(ht, 'final_tie')

    f = _near_max_fracs(best)
    print("final R=%.9f origin=%s N=%d zero=%.4f argmax=%.3f fracs=%.4f/%.4f/%.4f (start %.9f)" %
          (bestR, origin, best.size, _zero_frac(best), _argmax_loc(best),
           f[0], f[1], f[2], start_bestR))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    """-log R with exact gradient."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    if num <= 0:
        return 1e18, np.zeros(h.size)
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        grad = 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    else:
        grad = 2.0 * np.correlate(gL, h, mode='valid')[:n]
    grad = grad + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        return _fun_grad(np.clip(x, 0.0, None))

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.clip(res.x, 0.0, None)
    except (TimeoutError, Exception):
        return h0
    return _rescale(h2)


def _prolong(h, N2):
    N = len(h)
    if N2 == N:
        return h.copy()
    if N2 % N == 0:
        return np.repeat(h, N2 // N)
    idx = np.clip((np.arange(N2) * N // N2), 0, N - 1)
    return h[idx]


def _perturb(h, rng, scale=0.1):
    h = h.copy()
    mask = rng.random(h.size) < 0.15
    h[mask] *= np.exp(rng.normal(0, scale, mask.sum()))
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(12345)

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best_h = s.copy()
            best_R = _R(best_h)

    # seed with a good analytic init if no start
    if best_h is None:
        N = 4096
        i = np.arange(N)
        best_h = np.minimum(3.0, ((i + 0.5) / N) ** -0.5)
        best_h = _rescale(best_h)
        best_R = _R(best_h)

    # multi-resolution ladder: prolong start, then L-BFGS at increasing N
    ladder = []
    N0 = len(best_h)
    for N in (N0, N0 * 2, N0 * 4, 8192, 16384, 32768):
        if N >= N0 and N <= 32768:
            ladder.append(N)
    ladder = sorted(set(ladder))

    current = best_h
    for N in ladder:
        if time.process_time() >= deadline - 1.0:
            break
        if len(current) != N:
            current = _prolong(current, N)
        current = _rescale(current)
        # a few L-BFGS passes with restarts
        for _ in range(3):
            if time.process_time() >= deadline - 1.0:
                break
            iters = min(3000, max(200, int(200000 / N)))
            h2 = _lbfgs(current, iters, deadline)
            r2 = _R(h2)
            if r2 > _R(current):
                current = h2
            else:
                break
        r = _R(current)
        print("N=%d R=%.6f" % (N, r))
        if r > best_R:
            best_R = r
            best_h = current.copy()

    # random perturbations from best to escape local optima
    for trial in range(100):
        if time.process_time() >= deadline - 0.5:
            break
        h2 = _perturb(best_h, rng, scale=0.05 + 0.1 * rng.random())
        h2 = _lbfgs(h2, 1500, deadline)
        r2 = _R(h2)
        if r2 > best_R:
            best_R = r2
            best_h = h2.copy()
            print("perturb trial=%d R=%.6f" % (trial, r2))

    print("FINAL best R=%.6f N=%d" % (best_R, len(best_h)))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = _R(s) if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0 else -1
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _upsample(h, factor):
    """Linear-interpolate step heights to factor*N (keeps shape, refines grid)."""
    n = h.size
    m = n * factor
    xo = (np.arange(m) + 0.5) / m * n
    xi = np.arange(n) + 0.5
    return np.interp(xo, xi, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(64)
        best_r = R_of(best)

    cur = best.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand.copy(), r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    try:
        h = cur.copy()
        it = 0
        # Phase 1: repeated full/beta/window polish on current grid
        while time.process_time() < deadline - 1.0:
            it += 1
            c = _lbfgs_block(h, np.arange(h.size), 400, deadline - 0.5)
            rc = R_of(c)
            if rc > R_of(h):
                h = c
            _consider(h, R_of(h))
            if time.process_time() >= deadline - 1.0:
                break
            for beta in (300.0, 120.0, 50.0, 20.0):
                if time.process_time() >= deadline - 1.0:
                    break
                cb = _lbfgs_block(h, np.arange(h.size), 250,
                                  min(deadline - 0.5, time.process_time() + 3.0),
                                  beta=beta)
                rb = R_of(cb)
                if rb > R_of(h):
                    h = cb
            _consider(h, R_of(h))
            if time.process_time() >= deadline - 1.0:
                break
            for tol, pf, ex in ((0.9995, 0.4, 256), (0.999, 0.25, 128),
                                 (0.995, 0.15, 64)):
                if time.process_time() >= deadline - 1.0:
                    break
                win = _peak_window(h, tol, pf, ex)
                cw = _lbfgs_block(h, win, 300,
                                  min(deadline - 0.5, time.process_time() + 3.0))
                rw = R_of(cw)
                if rw > R_of(h):
                    h = cw
            _consider(h, R_of(h))
            print("iter %d R=%.6f frac=%.4f" % (it, best_r, _frac_near_max(best)))

            # NEW: geometric upsample and re-polish, periodically
            if it % 3 == 0 and h.size < 500000 and time.process_time() < deadline - 5.0:
                up = _upsample(h, 2)
                cu = _lbfgs_block(up, np.arange(up.size), 200,
                                  min(deadline - 0.5, time.process_time() + 5.0))
                ru = R_of(cu)
                if ru > R_of(h) - 1e-9:
                    h = cu
                    _consider(h, ru)
                    print("  upsample -> N=%d R=%.6f" % (h.size, best_r))
    except Exception:
        pass

    # Phase 2: final polish
    try:
        if time.process_time() < deadline - 0.3:
            for _ in range(4):
                if time.process_time() >= deadline - 0.5:
                    break
                pol = _lbfgs_block(best, np.arange(best.size), 300,
                                   min(deadline - 0.4, time.process_time() + 5.0))
                _consider(pol, R_of(pol))
    except Exception:
        pass

    if start_arr is not None:
        sr = R_of(start_arr)
        if best_r < sr:
            best = start_arr.copy()
            best_r = sr

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

