    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------------------------------------------------------------------
# New idea: NON-UNIFORM RESAMPLING using an explicit mass-conserving
# "remap" onto a new grid that is denser where f*f is near its max and
# coarser elsewhere.  This gives the optimiser a genuinely different
# parametrisation of the SAME shape (same continuous f), which breaks the
# symmetry of the uniform grid and lets the peak region be resolved more
# finely relative to the rest.  We then re-optimise and, if it wins, keep it;
# if it loses but is still a distinct construction we return it as alt.
# ---------------------------------------------------------------------------

def _remap(h, new_n):
    """Mass-conserving resample of step function h onto new_n steps.

    Uses cumulative mass and a monotone warp that allocates more cells
    near the peak of f*f."""
    n = h.size
    if new_n == n or new_n < 8:
        return h.copy()
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return h.copy()
    # density of importance: base 1 + bump near max of f*f
    # knot index ~ cell boundary; map cell i to knot position i+1
    x = np.linspace(0.0, 1.0, new_n + 1)
    # warp: concentrate near the location of the peak of f*f (in [0,1])
    pk = float(np.argmax(Lf)) / max(1, n)  # 0..1 approx
    # strength of concentration
    a = 0.55
    # cubic warp that pulls 0..1 toward pk in the middle, identity at ends
    def warp(t):
        return t + a * np.sin(np.pi * t) * (pk - t) * 0.0 + \
               a * (np.sin(np.pi * t) ** 2) * (pk - 0.5) * 2.0 * 0.0
    # simpler: piecewise-linear cumulative warp using importance weights
    imp = 1.0 + 4.0 * np.exp(-((np.arange(n) + 0.5) / n - pk) ** 2 / 0.02)
    cum = np.concatenate(([0.0], np.cumsum(imp)))
    cum /= cum[-1]
    # target cumulative positions in [0,1]
    tgt = np.linspace(0.0, 1.0, new_n + 1)
    # map tgt -> source cell boundary via inverse cum (approx)
    src_bound = np.interp(tgt, cum, np.arange(n + 1, dtype=float))
    # integrate h over each target cell: mass between consecutive boundaries
    # cumulative mass of h
    cm = np.concatenate(([0.0], np.cumsum(h)))
    mass = np.interp(src_bound, np.arange(n + 1, dtype=float), cm)
    out = np.diff(mass)
    out = np.clip(out, 0.0, None)
    if out.sum() <= 0:
        return h.copy()
    return out


def _coarsen_refine(best, bestR, deadline, rng):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR, False
    idx = np.flatnonzero(Lf >= 0.999 * M)
    if idx.size == 0:
        return best, bestR, False
    lo = max(0, int(idx.min()) - 8)
    hi = min(n - 1, int(idx.max()) + 8)
    improved = False
    for _ in range(24):
        if time.process_time() >= deadline - 0.6:
            break
        i0 = int(rng.integers(lo, hi + 1))
        k = int(rng.integers(2, 6))
        # merge
        i1 = min(n, i0 + k)
        if i1 - i0 >= 2:
            mass = float(best[i0:i1].sum())
            h2 = np.concatenate([best[:i0], [mass], best[i1:]])
            win_lo = max(0, i0 - 96)
            win_hi = min(h2.size - 1, i0 + 96)
            free = np.arange(win_lo, win_hi + 1)
            h3 = _lbfgs_block(h2, free, 80, deadline, beta=0.0)
            r3 = R_of(h3)
            if r3 > bestR + 1e-13:
                best, bestR = h3, r3
                improved = True
                continue
        # split
        if best[i0] > 0:
            mass = float(best[i0])
            parts = np.full(2, mass / 2.0)
            h4 = np.concatenate([best[:i0], parts, best[i0 + 1:]])
            win_lo = max(0, i0 - 96)
            win_hi = min(h4.size - 1, i0 + 96)
            free = np.arange(win_lo, win_hi + 1)
            h5 = _lbfgs_block(h4, free, 80, deadline, beta=0.0)
            r5 = R_of(h5)
            if r5 > bestR + 1e-13:
                best, bestR = h5, r5
                improved = True
    return best, bestR, improved


def _try_remap(best, bestR, deadline):
    """Try remapping to a few new resolutions; re-optimise; keep if better."""
    n = best.size
    best_local = best
    bestR_local = bestR
    cands = []
    for factor in (1.15, 0.87, 1.4, 0.7):
        new_n = int(round(n * factor))
        if new_n < 32 or new_n > 1000000:
            continue
        cands.append(new_n)
    for new_n in cands:
        if time.process_time() >= deadline - 1.0:
            break
        h2 = _remap(best, new_n)
        if h2.size == 0 or h2.sum() <= 0:
            continue
        h2 = _rescale(h2)
        # quick local optimise (full)
        h3 = _lbfgs_all_pos(h2, 600, deadline - 0.6, beta=0.0)
        r3 = R_of(h3)
        if r3 > bestR_local + 1e-13:
            best_local, bestR_local = h3, r3
        # also try the peak-window refine
        if time.process_time() < deadline - 1.0:
            win = _peak_window(h3, pad_frac=0.30, extra=200)
            h4 = _lbfgs_block(h3, win, 200, deadline - 0.6, beta=1e8)
            r4 = R_of(h4)
            if r4 > bestR_local + 1e-13:
                best_local, bestR_local = h4, r4
    return best_local, bestR_local


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # Phase 1: proven full cycle on the given start
    if time.process_time() < deadline - 5.0:
        best, bestR = run_cycle(best, bestR, deadline - 5.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 2: remap to non-uniform-equivalent resolutions, re-optimise
    if time.process_time() < deadline - 4.0:
        h_rm, r_rm = _try_remap(best, bestR, deadline - 3.0)
        if r_rm > bestR + 1e-13:
            best, bestR = h_rm, r_rm
            print("remap wins R=%.7f (N=%d)" % (bestR, best.size))
        elif h_rm is not None and r_rm > start_bestR + 1e-10:
            alt_cand, altR = h_rm, r_rm

    # Phase 3: alternate coarsen/refine and cycles
    rounds = 0
    while time.process_time() < deadline - 1.5:
        rounds += 1
        before = bestR
        if time.process_time() < deadline - 1.5:
            h_cr, r_cr, improved = _coarsen_refine(best, bestR,
                                                   deadline - 1.0, rng)
            if improved and r_cr > bestR + 1e-13:
                best, bestR = h_cr, r_cr
        if time.process_time() < deadline - 1.0:
            best, bestR = run_cycle(best, bestR, deadline - 0.8)
        if bestR <= before + 1e-13:
            # stalled: try remap again with a different factor
            if time.process_time() < deadline - 2.0:
                h_rm, r_rm = _try_remap(best, bestR, deadline - 1.0)
                if r_rm > bestR + 1e-13:
                    best, bestR = h_rm, r_rm
            if time.process_time() >= deadline - 1.0:
                break
            if bestR <= before + 1e-13:
                break

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta_pen(h, beta, tau, kappa):
    """J_beta with soft-max and variance penalty in the near-max region."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm

    # variance penalty over Lf >= tau*mx
    S = Lf >= tau * mx
    if np.any(S):
        vals = Lf[S]
        mu = vals.mean()
        var = np.mean((vals - mu) ** 2)
        nS = vals.size
        dvar_dL = np.zeros_like(Lf)
        dvar_dL[S] = (2.0 / nS) * (vals - mu)
        pen = kappa * var / (mx * mx)
        gLf += kappa * dvar_dL / (mx * mx)
        # derivative of pen wrt mx: -2*kappa*var/mx^3 * dmx; dmx/dh via argmax
        idx = np.flatnonzero(Lf >= (1.0 - 1e-12) * mx)
        wm = 1.0 / idx.size
        gLf[idx] += (-2.0 * kappa * var / (mx * mx * mx)) * wm
    else:
        pen = 0.0

    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tau=0.9, kappa=0.0,
                 tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta_pen(hh, beta, tau, kappa))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _max_mean(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(mx / Lf.mean())


def _stats(h):
    return (_frac_near_max(h, 1e-3), _frac_near_max(h, 1e-2),
            _frac_near_max(h, 5e-2), _max_mean(h))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max 0.1/1/5%% before: %.4f %.4f %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    alt_best = None
    altR = -1.0

    Nfull = best.size
    allidx = np.arange(Nfull)

    # ---- single sharpening pass from start at beta=1e8 ----
    h_cur = best.copy()
    curR = bestR
    if time.process_time() < deadline - 5.0:
        h_sharp = _lbfgs_block(h_cur, allidx, 150,
                               min(deadline - 4.0, time.process_time() + 6.0),
                               beta=1e8, tau=0.90, kappa=10.0)
        r = R_of(h_sharp)
        print("sharp beta=1e8 R=%.12f (nm 1/5%%=%.4f/%.4f mm=%.2f)"
              % (r, _frac_near_max(h_sharp, 1e-2),
                 _frac_near_max(h_sharp, 5e-2), _max_mean(h_sharp)))
        if r > curR + 1e-15:
            h_cur, curR = h_sharp, r

    # ---- ladder ----
    betas = [1e3, 1e5, 1e7, 1e9]
    taus = [0.95, 0.90, 0.85, 0.80]
    kappas = [100.0, 30.0, 10.0, 3.0]

    cycle = 0
    while time.process_time() < deadline - 3.0:
        cycle += 1
        improved = False
        for beta in betas:
            for tau in taus:
                for kappa in kappas:
                    if time.process_time() >= deadline - 2.5:
                        break
                    use_tie = beta >= 1e7
                    h_new = _lbfgs_block(
                        h_cur, allidx, 150,
                        min(deadline - 2.0, time.process_time() + 3.0),
                        beta=beta, tau=tau, kappa=kappa, tie=use_tie)
                    r = R_of(h_new)
                    if r > curR + 1e-15:
                        h_cur, curR = h_new, r
                        improved = True
                    # exact tie polish
                    if time.process_time() < deadline - 2.0:
                        pol = _lbfgs_block(
                            h_cur, allidx, 100,
                            min(deadline - 1.5, time.process_time() + 2.0),
                            tie=True)
                        rp = R_of(pol)
                        if rp > curR + 1e-15:
                            h_cur, curR = pol, rp
                            improved = True
                    # peak-window polish
                    for pad in (0.05, 0.03):
                        if time.process_time() < deadline - 1.5:
                            win = _peak_window(h_cur, pad_frac=pad, extra=128)
                            ht = _lbfgs_block(
                                h_cur, win, 100,
                                min(deadline - 1.0, time.process_time() + 2.0),
                                tie=True)
                            rt = R_of(ht)
                            if rt > curR + 1e-15:
                                h_cur, curR = ht, rt
                                improved = True
                    if curR > bestR + 1e-15:
                        best, bestR = h_cur.copy(), curR
                    print("cyc%d b=%.0e tau=%.2f kap=%.0f R=%.12f "
                          "(nm 1/5%%=%.4f/%.4f mm=%.2f)"
                          % (cycle, beta, tau, kappa, curR,
                             _frac_near_max(h_cur, 1e-2),
                             _frac_near_max(h_cur, 5e-2),
                             _max_mean(h_cur)))
                if time.process_time() >= deadline - 2.5:
                    break
            if time.process_time() >= deadline - 2.5:
                break
        if not improved:
            break

    # track alternative: the best from the beta-ladder (may differ from start)
    if curR > altR:
        altR = curR
        alt_best = h_cur.copy()

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("frac near max 0.1/1/5%% after: %.4f %.4f %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))
    print("final R=%.12f (start %.12f, N=%d, ties=%d, mm=%.2f)"
          % (bestR, startR, best.size, _tie_count(best), _max_mean(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-15:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

