        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- 32-periodic subcell experiment helpers ----

def _build_h(c, s, B):
    return np.repeat(c, B) * np.tile(s, c.size)


def _grad_s(h, c, s, B):
    _, g = _fun_grad_tie(h)
    g = g.reshape(-1, B)
    return np.sum(g * c[:, None], axis=0)


def _grad_c(h, c, s, B):
    _, g = _fun_grad_tie(h)
    g = g.reshape(-1, B)
    return np.sum(g * s[None, :], axis=1)


def _opt_s(c, s, B, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return s
    s = np.clip(s, 1e-12, None)

    def f(x):
        ss = np.clip(x, 0.0, None)
        h = _build_h(c, ss, B)
        val, _ = _fun_grad_tie(h)
        gs = _grad_s(h, c, ss, B)
        return val, gs

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, s.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * B, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return s
    if res is None:
        return s
    return np.clip(res.x, 0.0, None)


def _opt_c(c, s, B, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c
    c = np.clip(c, 1e-12, None)

    def f(x):
        cc = np.clip(x, 0.0, None)
        h = _build_h(cc, s, B)
        val, _ = _fun_grad_tie(h)
        gc = _grad_c(h, cc, s, B)
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * c.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c
    if res is None:
        return c
    return np.clip(res.x, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    altR = -1.0

    N = best.size
    B = 32
    if N % B != 0:
        # fall back: keep base, do a light polish
        if time.process_time() < deadline - 2.0:
            pol = _lbfgs_block(best, np.arange(best.size), 200,
                               min(deadline - 1.0, time.process_time() + 4.0), tie=True)
            rp = R_of(pol)
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp
        print("final R=%.12f (start %.12f, N=%d, ties=%d)"
              % (bestR, startR, best.size, _tie_count(best)))
        return {"best": best}

    nblocks = N // B
    c0 = best.reshape(-1, B).mean(1)
    s0 = np.ones(B)

    # restarts
    phases = [0.0, 1.3, 2.7]
    restarts = []
    for ph in phases:
        k = np.arange(B, dtype=float)
        restarts.append(1.0 + 0.15 * np.sin(2 * np.pi * k / B + ph))
    rng = np.random.RandomState(12345)
    for _ in range(2):
        restarts.append(np.exp(rng.normal(0.0, 0.1, B)))

    restart_idx = 0
    cur_c = c0.copy()
    cur_s = s0.copy()
    cur_h = _build_h(cur_c, cur_s, B)
    curR = R_of(cur_h)
    if curR > bestR:
        best, bestR = cur_h.copy(), curR

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        # (A) optimize s
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        new_s = _opt_s(cur_c, cur_s, B, 200, tlim)
        if new_s is not None and new_s.size == B:
            ms = new_s.mean()
            if ms > 0:
                cur_s = new_s / ms
                cur_c = cur_c * ms
        # (B) optimize c
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        new_c = _opt_c(cur_c, cur_s, B, 100, tlim)
        if new_c is not None and new_c.size == nblocks:
            cur_c = new_c

        cur_h = _build_h(cur_c, cur_s, B)
        curR = R_of(cur_h)
        dev = float(np.max(np.abs(cur_s - 1.0)))
        print("cycle %d R=%.12f max|s-1|=%.4f min(s)=%.4f max(s)=%.4f"
              % (cycle, curR, dev, cur_s.min(), cur_s.max()))

        if curR > bestR + 1e-15:
            best, bestR = cur_h.copy(), curR

        # short full-N tie polish
        if time.process_time() < deadline - 1.5:
            pol = _lbfgs_block(cur_h, np.arange(N), 60,
                               min(deadline - 1.0, time.process_time() + 2.0), tie=True)
            rp = R_of(pol)
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp
            if rp > altR:
                altR, alt_best = rp, pol.copy()
            # refresh cur from polished (project back to structure)
            c_new = pol.reshape(-1, B).mean(1)
            if c_new.sum() > 0:
                cur_c = c_new
                cur_h = _build_h(cur_c, cur_s, B)

        # peak-window polish
        for pad in (0.05, 0.03):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cur_h, pad_frac=pad, extra=96)
            ht = _lbfgs_block(cur_h, win, 120,
                              min(deadline - 0.5, time.process_time() + 1.5), tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
            if r > altR:
                altR, alt_best = r, ht.copy()

        # if s collapsed to uniform, try a restart
        if dev < 1e-3 and restart_idx < len(restarts):
            cur_s = restarts[restart_idx].copy()
            restart_idx += 1
            ms = cur_s.mean()
            if ms > 0:
                cur_s = cur_s / ms
            cur_c = c0.copy()
            cur_h = _build_h(cur_c, cur_s, B)
            print("  restart %d" % restart_idx)

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_tsm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0.0, None)
    mx = Lc.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    W = Lc ** (p - 1)
    S = W.sum()
    if S <= 0:
        return _fun_grad_tie(h)
    w = W / S
    r = Lc / mx
    sm = mx * (np.mean(r ** p)) ** (1.0 / p)
    if sm <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, kind='max', p=8):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if kind == 'max':
        fg = _fun_grad
    elif kind == 'tie':
        fg = _fun_grad_tie
    else:
        fg = (lambda hh: _fun_grad_tsm(hh, p))

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, kind='max', p=8):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if kind == 'max':
        fg = _fun_grad
    elif kind == 'tie':
        fg = _fun_grad_tie
    else:
        fg = (lambda hh: _fun_grad_tsm(hh, p))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _deficit_frac(h, lo=0.7, hi=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    r = Lf / mx
    return float(np.mean((r >= lo) & (r <= hi)))


def _refine(h, bestR, deadline, tag=""):
    for kind, iters in (('tie', 300), ('max', 300)):
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all(h, iters, deadline, kind=kind)
        r = R_of(ht)
        if r > bestR + 1e-15:
            h, bestR = ht, r
            print("%s %s NEW R=%.9f" % (tag, kind, bestR))
    for pad in (0.10, 0.06, 0.04, 0.025):
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, 250, deadline, kind='tie')
        r = R_of(ht)
        if r > bestR + 1e-15:
            h, bestR = ht, r
            print("%s peak pad=%.3f NEW R=%.9f" % (tag, pad, bestR))
    return h, bestR


def _smooth_seq(h, passes=6):
    """Rare: convolve with tiny [1,4,1] on interior to break grid-locking,
    preserving total mass and non-negativity. Cheap and quick."""
    h = np.clip(h, 0, None)
    if h.size < 3:
        return h
    for _ in range(passes):
        hn = h.copy()
        hn[1:-1] = (h[:-2] + 4.0 * h[1:-1] + h[2:]) / 6.0
        h = hn
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f N=%d zero=%.4f nearmax=%.4f deficit=%.4f"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _deficit_frac(best)))

    # Phase 1: tsm ladder (escapes single-max traps).
    tsm_deadline = t0 + budget_seconds * 0.40
    for p in (3, 5, 8, 14, 24):
        if time.process_time() >= tsm_deadline - 1.0:
            break
        ht = _lbfgs_all(best, 200, tsm_deadline, kind='tsm', p=p)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("tsm p=%d NEW R=%.9f" % (p, bestR))

    # Phase 2: smooth perturbation + polish — new idea to escape grid plateau.
    # Apply a tiny interior smoothing and re-optimise; if it helps keep it,
    # if not, fall back to un-smoothed best.
    sm_deadline = t0 + budget_seconds * 0.60
    for passes in (2, 4, 8):
        if time.process_time() >= sm_deadline - 1.5:
            break
        hs = _smooth_seq(best, passes=passes)
        rs = R_of(hs)
        # polish the smoothed version
        ht = _lbfgs_all(hs, 250, sm_deadline, kind='tie')
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("smooth passes=%d NEW R=%.9f" % (passes, bestR))
        elif rs > bestR + 1e-15:
            best, bestR = hs, rs
            print("smooth raw passes=%d NEW R=%.9f" % (passes, bestR))

    # Phase 3: tie-aware max polish + tight peak windows.
    mk_deadline = t0 + budget_seconds * 0.85
    best, bestR = _refine(best, bestR, mk_deadline, tag="P3")

    # Phase 4: final hard polish.
    fd = t0 + budget_seconds * 0.92
    ht = _lbfgs_all(best, 600, fd, kind='tie')
    r = R_of(ht)
    if r > bestR + 1e-14:
        best, bestR = ht, r
        print("FINAL tie ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        ht = _lbfgs_all(best, 400, fd, kind='max')
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("FINAL max ACCEPT R=%.9f" % bestR)
    if time.process_time() < fd - 0.5:
        for pad in (0.05, 0.03, 0.02):
            win = _peak_window(best, pad_frac=pad, extra=96)
            ht = _lbfgs_block(best, win, 300, fd, kind='tie')
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
                print("FINAL peak pad=%.3f ACCEPT R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, zero=%.4f, nearmax=%.4f, deficit=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _deficit_frac(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _detect_repeat(h):
    n = h.size
    for p in (64, 32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-10, atol=1e-13):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-11:
                return p, c
    return 1, h


def _refine_compressed(c, p, deadline, max_rounds=40):
    """Optimise the compressed core c (length m) directly, then expand by repeat p.
    This is cheaper per iteration than optimising all N samples, so we can do
    many more L-BFGS steps within the budget."""
    m = c.size
    if m < 2:
        return np.repeat(c, p)
    best_c = c.copy()
    bestR = R_of(np.repeat(best_c, p))
    for _ in range(max_rounds):
        if time.process_time() >= deadline - 0.5:
            break
        slice_end = min(deadline - 0.3, time.process_time() + 2.0)
        c_new = _lbfgs_block(best_c, np.arange(m), 200, slice_end, tie=True)
        R_new = R_of(np.repeat(c_new, p))
        if R_new > bestR + 1e-15:
            best_c, bestR = c_new, R_new
        else:
            # try one more with a different random perturbation to escape
            if time.process_time() >= deadline - 1.0:
                break
            rng = np.random.default_rng(int(time.process_time() * 1e6) & 0xffffffff)
            pert = best_c * (1.0 + 0.01 * rng.standard_normal(m))
            pert = _lbfgs_block(np.clip(pert, 0, None), np.arange(m), 100,
                                slice_end, tie=True)
            Rp = R_of(np.repeat(pert, p))
            if Rp > bestR + 1e-15:
                best_c, bestR = pert, Rp
    return np.repeat(best_c, p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # Main improvement: optimise the compressed core directly.
    # Compressed core is cheaper per iteration -> many more L-BFGS steps.
    alt_best = best.copy()
    alt_bestR = bestR

    if c.size >= 2 and c.size < best.size:
        # Give the compressed-core optimiser most of the remaining budget.
        core_deadline = deadline - 1.0
        h_comp = _refine_compressed(c, p, core_deadline, max_rounds=200)
        r_comp = R_of(h_comp)
        print("compressed refine R=%.9f" % r_comp)
        if r_comp > alt_bestR + 1e-15:
            alt_best, alt_bestR = h_comp, r_comp

    # Also try a few full-size tie polishes on the current best (short bursts).
    cur = alt_best.copy()
    curR = alt_bestR
    round_r = 0
    while time.process_time() < deadline - 1.0:
        round_r += 1
        slice_end = min(deadline - 0.4, time.process_time() + 2.0)
        h_opt = _lbfgs_block(cur, np.arange(cur.size), 60, slice_end, tie=True)
        r_opt = R_of(h_opt)
        # Fold to period p
        if h_opt.size % p == 0 and p > 1:
            p_new = h_opt.reshape(-1, p).mean(axis=1)
            h_new = np.repeat(p_new, p)
            r_new = R_of(h_new)
            if r_new >= r_opt:
                cand, candR = h_new, r_new
            else:
                cand, candR = h_opt, r_opt
        else:
            cand, candR = h_opt, r_opt
        if candR > curR + 1e-15:
            cur, curR = cand, candR
        if candR > alt_bestR + 1e-15:
            alt_best, alt_bestR = cand.copy(), candR
        print("round %d R=%.9f cur=%.9f" % (round_r, candR, curR))
        if candR <= curR - 1e-12:
            break

    # Final: one more compressed refine burst if there's time.
    if time.process_time() < deadline - 0.6:
        p2, c2 = _detect_repeat(alt_best)
        if c2.size >= 2 and c2.size < alt_best.size:
            h_f = _refine_compressed(c2, p2, deadline - 0.4, max_rounds=30)
            rf = R_of(h_f)
            if rf > alt_bestR + 1e-15:
                alt_best, alt_bestR = h_f, rf
                print("final compressed R=%.9f" % alt_bestR)

    print("final alt R=%.9f (start %.9f, N=%d)" %
          (alt_bestR, startR, alt_best.size))

    result = {}
    if alt_bestR > startR + 1e-14:
        result["best"] = alt_best
        if start is not None:
            result["alternative"] = best
    else:
        result["best"] = best
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


# ---------- new: direct nonlinear solve for equal-peak plateau ----------

def _plateau_targets(h):
    """Return indices of knots that are at (nearly) the global max."""
    Lf = _knots(h)
    mx = Lf.max()
    return np.flatnonzero(Lf >= mx * (1.0 - 1e-6)), mx


def _push_plateau(h, deadline, target_fracs=(0.8, 0.9, 0.95)):
    """Aggressively raise near-max knots toward equality using beta-smoothing
    with increasing beta and a wider peak window, pushing the plateau wider."""
    h = h.copy()
    best = h.copy()
    bestR = R_of(best)
    betas = [1e3, 1e4, 1e5, 1e6, 1e7, 1e8]
    for b in betas:
        if time.process_time() >= deadline - 0.5:
            break
        # wide window covering most of the support near the peak region
        win = _peak_window(h, tol=0.99, pad_frac=0.6, extra=512)
        ht = _lbfgs_block(h, win, 400, deadline - 0.3, beta=b)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best = ht.copy()
            bestR = r
            h = ht
    # final tie-aware polish
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, tol=0.999, pad_frac=0.3, extra=256)
        ht = _lbfgs_block(h, win, 400, deadline - 0.3, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best = ht.copy()
            bestR = r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    f01, f1, f5 = _nearmax_fracs(best)
    print("base R=%.9f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
          % (bestR, f01, f1, f5))

    # ---- Phase 1: aggressive plateau widening (main new idea) ----
    p1_end = t0 + budget_seconds * 0.55
    h, r = _push_plateau(best, p1_end)
    if r > bestR + 1e-15:
        best, bestR = h, r
        f01, f1, f5 = _nearmax_fracs(best)
        print("plateau ACCEPT R=%.9f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (bestR, f01, f1, f5))

    # ---- Phase 2: alternating full-res tie / argmax polishing ----
    p2_end = t0 + budget_seconds * 0.85
    cyc = 0
    while time.process_time() < p2_end - 2.0:
        cyc += 1
        progressed = False
        if time.process_time() < p2_end - 2.0:
            ht = _lbfgs_all_pos(best, 400,
                                min(p2_end - 1.0,
                                    time.process_time() + 8.0), tie=True)
            rt = R_of(ht)
            if rt > bestR + 1e-15:
                best, bestR = ht, rt
                progressed = True
        if time.process_time() < p2_end - 1.5:
            win = _peak_window(best, tol=0.999, pad_frac=0.15, extra=256)
            ht = _lbfgs_block(best, win, 400,
                              min(p2_end - 0.5,
                                  time.process_time() + 6.0), beta=1e7)
            rt = R_of(ht)
            if rt > bestR + 1e-15:
                best, bestR = ht, rt
                progressed = True
        f01, f1, f5 = _nearmax_fracs(best)
        print("polish cyc=%d R=%.9f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (cyc, bestR, f01, f1, f5))
        if not progressed and cyc > 2:
            break

    # ---- Phase 3: coordinate descent on a staircase if present ----
    # small local coordinate perturbation search: pick random blocks and
    # apply small multiplicative perturbations, keep if R improves.
    p3_end = t0 + budget_seconds * 0.97
    if time.process_time() < p3_end - 2.0:
        rng = np.random.default_rng(7)
        n = best.size
        # identify active region (non-tiny heights)
        thr = best.max() * 1e-4
        active = np.flatnonzero(best > thr)
        ncyc = 0
        while time.process_time() < p3_end - 1.0:
            ncyc += 1
            improved = False
            # try a few random block perturbations
            for _ in range(6):
                if time.process_time() >= p3_end - 0.8:
                    break
                k = rng.integers(4, max(5, min(64, active.size)))
                if active.size <= k:
                    continue
                idx = rng.choice(active, size=k, replace=False)
                idx.sort()
                scale = np.exp(rng.uniform(-0.3, 0.3, size=k))
                ht = best.copy()
                ht[idx] *= scale
                ht = _rescale(ht)
                rt = R_of(ht)
                if rt > bestR + 1e-15:
                    best, bestR = ht, rt
                    improved = True
                    break
            if not improved:
                break
        print("cd cyc=%d R=%.9f" % (ncyc, bestR))

    # ---- Phase 4: final full tie polish ----
    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 1.5:
        ht = _lbfgs_all_pos(best, 400, fd - 0.3, tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    f01, f1, f5 = _nearmax_fracs(best)
    print("final R=%.9f (start %.9f, N=%d, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, f5, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
import math
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)):
        return -1.0
    if np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    L2 = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    Linf = L.max()
    if Linf <= 0:
        return -1.0
    return L2 / (s * s * Linf)


def _factor(n):
    fs = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            fs.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        fs.append(n)
    return fs


def _primitive_root(p):
    if p == 2:
        return 1
    fs = _factor(p - 1)
    for g in range(2, p):
        ok = True
        for q in fs:
            if pow(g, (p - 1) // q, p) == 1:
                ok = False
                break
        if ok:
            return g
    return None


def _cubic_comb(p):
    g = _primitive_root(p)
    if g is None:
        return None
    h = np.full(p, 1e-3, dtype=float)
    # nonzero cubic residues: g^(3k) for k=0..(p-1)/3-1, excluding 1? include 1 (i>0)
    val = 1
    g3 = pow(g, 3, p)
    for _ in range((p - 1) // 3):
        if val != 0:
            h[val] = 1.0
        val = (val * g3) % p
    i = np.arange(p, dtype=float)
    env = np.sin(np.pi * i / (p - 1.0))
    env = np.maximum(0.05, np.power(np.maximum(env, 0.0), 0.5))
    h = h * env
    return h


def _softmax_param(h, beta):
    # parametrize via log of h+eps, softmax-ish; we optimize directly on x = log(h+eps)
    eps = 1e-6
    return np.log(h + eps)


def _polish(h, budget_deadline, maxiter, beta=None):
    """L-BFGS-B on log-params to keep positivity. beta unused (kept for schedule)."""
    n = h.size
    eps = 1e-8
    x0 = np.log(h + eps)

    def unpack(x):
        return np.exp(x)

    def obj(x):
        if time.process_time() > budget_deadline:
            raise TimeoutError
        hh = unpack(x)
        s = hh.sum()
        if s <= 0:
            return 1e10
        L = fftconvolve(hh, hh)
        L = np.concatenate(([0.0], L, [0.0]))
        L2 = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
        Linf = L.max()
        if Linf <= 0:
            return 1e10
        return -(L2 / (s * s * Linf))

    def grad(x):
        # numerical-free: use finite diff via scipy default (None) -> let it approximate
        return None

    try:
        res = minimize(obj, x0, method='L-BFGS-B',
                       bounds=[(-20, 20)] * n,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 4,
                                'ftol': 1e-12, 'gtol': 1e-10})
        hh = np.exp(res.x)
        return hh
    except TimeoutError:
        return h
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.75 * budget_seconds
    hard_deadline = t0 + budget_seconds - 4.0

    best = None
    best_R = -1.0

    if start is not None:
        try:
            s = np.asarray(start, dtype=float).ravel()
            if s.size > 0 and np.all(np.isfinite(s)) and np.all(s >= 0) and s.sum() > 0:
                r = _R(s)
                if r > best_R:
                    best_R = r
                    best = s.copy()
        except Exception:
            pass

    # Build cubic-residue comb at p=16381
    p = 16381
    h = None
    if time.process_time() < hard_deadline - 4:
        try:
            h = _cubic_comb(p)
        except Exception:
            h = None

    if h is not None:
        r0 = _R(h)
        print("raw cubic comb R=%.6f" % r0)
        if r0 > best_R:
            best_R = r0
            best = h.copy()

        # beta ladder: three rungs
        cur = h.copy()
        for beta, mi in [(1e3, 120), (1e5, 120), (1e7, 120)]:
            if time.process_time() > hard_deadline - 6:
                break
            stage_deadline = min(deadline, hard_deadline - 4)
            newh = _polish(cur, stage_deadline, mi, beta)
            rn = _R(newh)
            if rn > best_R:
                best_R = rn
                best = newh.copy()
            if rn >= _R(cur):
                cur = newh
            print("beta=%.0e R=%.6f best=%.6f" % (beta, rn, best_R))

        # exact tie polish
        if time.process_time() < hard_deadline - 6:
            stage_deadline = min(deadline, hard_deadline - 4)
            newh = _polish(cur, stage_deadline, 80)
            rn = _R(newh)
            if rn > best_R:
                best_R = rn
                best = newh.copy()
            if rn >= _R(cur):
                cur = newh
            print("tie R=%.6f best=%.6f" % (rn, best_R))

        # peak-window polish: focus on a window around peak of f*f
        if time.process_time() < hard_deadline - 6 and best is not None:
            try:
                L = np.convolve(best, best)
                peak = int(np.argmax(L))
                # window in h-space roughly around peak/2
                c = peak // 2
                w = max(4, int(0.05 * best.size))
                lo = max(0, c - w)
                hi = min(best.size, c + w)
                sub = best[lo:hi].copy()
                if sub.size > 0:
                    stage_deadline = min(deadline, hard_deadline - 4)
                    newsub = _polish(sub, stage_deadline, 60)
                    cand = best.copy()
                    cand[lo:hi] = newsub
                    rn = _R(cand)
                    if rn > best_R:
                        best_R = rn
                        best = cand
                    print("peakwin R=%.6f best=%.6f" % (rn, best_R))
            except Exception:
                pass

    if best is None:
        best = np.ones(50)

    # report
    try:
        b = np.asarray(best, dtype=float)
        zf = float(np.mean(b <= 1e-9))
        mm = float(b.max() / (b.mean() + 1e-30))
        L = np.convolve(b, b)
        pk = float(np.argmax(L)) / max(1, (L.size - 1))
        print("FINAL R=%.6f N=%d zero=%.3f max/mean=%.3f peakpos=%.3f"
              % (_R(b), b.size, zf, mm, pk))
    except Exception:
        pass

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta_pen(h, beta, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm

    S = Lf >= tau * mx
    if np.any(S):
        vals = Lf[S]
        mu = vals.mean()
        var = np.mean((vals - mu) ** 2)
        nS = vals.size
        dvar_dL = np.zeros_like(Lf)
        dvar_dL[S] = (2.0 / nS) * (vals - mu)
        pen = kappa * var / (mx * mx)
        gLf += kappa * dvar_dL / (mx * mx)
        idx = np.flatnonzero(Lf >= (1.0 - 1e-12) * mx)
        wm = 1.0 / idx.size
        gLf[idx] += (-2.0 * kappa * var / (mx * mx * mx)) * wm
    else:
        pen = 0.0

    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tau=0.9, kappa=0.0,
                 tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta_pen(hh, beta, tau, kappa))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _max_mean(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(mx / Lf.mean())


def _stats(h):
    return (_frac_near_max(h, 1e-3), _frac_near_max(h, 1e-2),
            _frac_near_max(h, 5e-2), _max_mean(h))


def _report(tag, h, r):
    f01, f1, f5, mm = _stats(h)
    zf = float(np.mean(h <= 0))
    print("%s R=%.12f nm 0.1/1/5%%=%.4f/%.4f/%.4f mm=%.2f zf=%.3f"
          % (tag, r, f01, f1, f5, mm, zf))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    _report("before", best, bestR)

    alt_best = None
    altR = -1.0

    Nfull = best.size
    allidx = np.arange(Nfull)

    h_cur = best.copy()
    curR = bestR

    # ---- (1)+(2) flat-top ladder: beta fixed 1e6, then sharpening pass ----
    ladder = [(0.80, 300.0), (0.70, 1000.0), (0.60, 3000.0),
              (0.50, 3000.0), (0.70, 300.0)]
    for (tau, kappa) in ladder:
        if time.process_time() >= deadline - 12.0:
            break
        h_new = _lbfgs_block(
            h_cur, allidx, 200,
            min(deadline - 11.0, time.process_time() + 6.0),
            beta=1e6, tau=tau, kappa=kappa)
        r = R_of(h_new)
        _report("flat tau=%.2f kap=%.0f" % (tau, kappa), h_new, r)
        if r > curR + 1e-15:
            h_cur, curR = h_new, r
        # sharpening pass at beta=1e8 (tie-averaged)
        if time.process_time() < deadline - 10.0:
            h_sh = _lbfgs_block(
                h_cur, allidx, 100,
                min(deadline - 9.0, time.process_time() + 3.0),
                beta=1e8, tau=tau, kappa=kappa, tie=True)
            rs = R_of(h_sh)
            _report("  sharp b=1e8", h_sh, rs)
            if rs > curR + 1e-15:
                h_cur, curR = h_sh, rs
        if curR > bestR + 1e-15:
            best, bestR = h_cur.copy(), curR

    if curR > altR:
        altR = curR
        alt_best = h_cur.copy()

    # ---- (3) ladder exhausted (or low time): tie polish + peak-window ----
    if time.process_time() < deadline - 6.0:
        pol = _lbfgs_block(
            h_cur, allidx, 100,
            min(deadline - 5.0, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        _report("tie polish", pol, rp)
        if rp > curR + 1e-15:
            h_cur, curR = pol, rp
        for pad in (0.05, 0.03):
            if time.process_time() < deadline - 5.0:
                win = _peak_window(h_cur, pad_frac=pad, extra=128)
                ht = _lbfgs_block(
                    h_cur, win, 100,
                    min(deadline - 4.0, time.process_time() + 2.5), tie=True)
                rt = R_of(ht)
                _report("peak pad=%.2f" % pad, ht, rt)
                if rt > curR + 1e-15:
                    h_cur, curR = ht, rt
        if curR > bestR + 1e-15:
            best, bestR = h_cur.copy(), curR
        if curR > altR:
            altR = curR
            alt_best = h_cur.copy()

    # ---- (4) mass-preserving 2x lift to N=65536 ----
    if time.process_time() < deadline - 15.0:
        h2 = np.repeat(h_cur, 2)
        k = np.array([0.25, 0.5, 0.25])
        h2 = np.convolve(h2, k, mode='same')
        h2 = _rescale(h2)
        r2 = R_of(h2)
        _report("lift x2", h2, r2)
        if r2 > curR + 1e-15:
            h_cur, curR = h2, r2
        idx2 = np.arange(h_cur.size)
        h_l = _lbfgs_block(
            h_cur, idx2, 100,
            min(deadline - 13.0, time.process_time() + 5.0),
            beta=1e8, tau=0.7, kappa=1000.0, tie=True)
        rl = R_of(h_l)
        _report("lift sharp", h_l, rl)
        if rl > curR + 1e-15:
            h_cur, curR = h_l, rl
        if time.process_time() < deadline - 8.0:
            h_t = _lbfgs_block(
                h_cur, np.arange(h_cur.size), 100,
                min(deadline - 7.0, time.process_time() + 4.0), tie=True)
            rt = R_of(h_t)
            _report("lift tie", h_t, rt)
            if rt > curR + 1e-15:
                h_cur, curR = h_t, rt
        if curR > bestR + 1e-15:
            best, bestR = h_cur.copy(), curR
        if curR > altR:
            altR = curR
            alt_best = h_cur.copy()

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    _report("after", best, bestR)
    print("final R=%.12f (start %.12f, N=%d, ties=%d, mm=%.2f)"
          % (bestR, startR, best.size, _tie_count(best), _max_mean(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-15:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

