    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- capped objective (H22) ----------
def _capped_fun_grad(h, tau):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    n = Lf.size
    w = np.ones(n)
    w[0] = 0.5
    w[-1] = 0.5
    u = tau * M
    below = Lf < u
    Lc = np.where(below, Lf, u)
    num = float(np.sum(w * Lc * Lc))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    S = s * s
    den = S * M
    # tie-averaged argmax indicator
    idx = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    nidx = idx.size
    e = np.zeros(n)
    e[idx] = 1.0 / nidx
    # W_up = sum of w_j over knots >= u
    up = ~below
    W_up = float(np.sum(w[up]))
    # d num / d L_k
    dnum = 2.0 * w * Lf * below.astype(float)
    # d num / d M = 2 * tau^2 * M * W_up
    dnum_dM = 2.0 * tau * tau * M * W_up
    # d den / d L_k = S * e_k ; d den / d M = S
    # F = -log(num) + log(den)
    gLf = -(dnum + dnum_dM * e) / num + (w * M + S * e) / den
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + np.log(den)
    return val, grad


def _capped_lbfgs(h0, tau, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _capped_fun_grad(hh, tau)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _sanity_check():
    rng = np.random.RandomState(0)
    N = 64
    h = rng.rand(N) + 0.1
    tau = 0.85
    val, grad = _capped_fun_grad(h, tau)
    eps = 1e-6
    err = 0.0
    for k in range(N):
        hp = h.copy(); hp[k] += eps
        hm = h.copy(); hm[k] -= eps
        vp, _ = _capped_fun_grad(hp, tau)
        vm, _ = _capped_fun_grad(hm, tau)
        fd = (vp - vm) / (2 * eps)
        err = max(err, abs(fd - grad[k]))
    return err


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    f01, f1, f5 = _fracs(best)
    print("fracs before: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % (f01, f1, f5))

    # sanity check gradient
    try:
        err = _sanity_check()
        print("capped grad sanity err=%.2e" % err)
    except Exception as e:
        print("sanity check failed:", e)

    alt_best = None
    altR = -1.0

    ladder = [0.90, 0.80, 0.70, 0.85, 0.95]
    cyc = 0
    while time.process_time() < deadline - 2.0:
        improved_cycle = False
        for tau in ladder:
            if time.process_time() >= deadline - 2.0:
                break
            tlim = min(deadline - 1.5, time.process_time() + 8.0)
            hc = _capped_lbfgs(best, tau, 150, tlim)
            rc = R_of(hc)
            # exact tie polish
            if time.process_time() < deadline - 1.0:
                pol = _lbfgs_block(hc, np.arange(hc.size), 100,
                                   min(deadline - 0.8, time.process_time() + 4.0),
                                   tie=True)
                rp = R_of(pol)
            else:
                pol, rp = hc, rc
            f01, f1, f5 = _fracs(pol)
            mx = _knots(pol).max()
            mean = pol.mean() if pol.mean() > 0 else 1.0
            print("cyc%d tau=%.2f R=%.12f fracs 0.1%%=%.4f 1%%=%.4f 5%%=%.4f max/mean=%.1f"
                  % (cyc, tau, rp, f01, f1, f5, mx / mean))
            if rp > altR:
                altR = rp
                alt_best = pol.copy()
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp
                improved_cycle = True
        cyc += 1
        if not improved_cycle and cyc > 3:
            # still keep cycling but avoid infinite tight loop
            if time.process_time() >= deadline - 2.0:
                break

    # final safety net: exact tie polish on best
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 150,
                           min(deadline - 0.5, time.process_time() + 4.0),
                           tie=True)
        rp = R_of(pol)
        if rp > altR:
            altR = rp
            alt_best = pol.copy()
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    f01, f1, f5 = _fracs(best)
    print("fracs after: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % (f01, f1, f5))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _smooth(h):
    # light smoothing: average adjacent steps to break grid artifacts
    if h.size < 3:
        return h
    hs = h.copy()
    hs[1:-1] = 0.25 * h[:-2] + 0.5 * h[1:-1] + 0.25 * h[2:]
    return _rescale(hs)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Main search: alternate exact-R polish, soft-max polish, and
    # peak-window block polish. Plus smoothing kicks to escape plateaus.
    bestH = best.copy()
    bestRH = bestR
    loop_end = deadline - 0.6
    it = 0
    rng = np.random.default_rng(12345)
    since_improve = 0

    while time.process_time() < loop_end:
        it += 1
        since_improve += 1

        # exact-R full polish
        cap = min(loop_end, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            since_improve = 0
            continue

        # soft-max polish
        for beta in (1e3, 1e4, 1e5):
            if time.process_time() >= loop_end - 0.8:
                break
            cap = min(loop_end, time.process_time() + 2.0)
            hb = _lbfgs_log(bestH, 100, cap, beta=beta)
            rb = R_of(hb)
            if rb > bestRH + 1e-13:
                bestH, bestRH = hb.copy(), rb
                since_improve = 0
                break
        if since_improve == 0:
            continue

        # peak-window block polish
        if time.process_time() < loop_end - 0.8:
            frac = 0.04 + 0.08 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 120, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                since_improve = 0
                continue

        # escape: smooth + polish
        if since_improve >= 3 and time.process_time() < loop_end - 2.0:
            hsm = _smooth(bestH)
            cap = min(loop_end, time.process_time() + 2.0)
            hsp = _lbfgs_log(hsm, 150, cap, beta=0.0)
            rsp = R_of(hsp)
            if rsp > bestRH + 1e-13:
                bestH, bestRH = hsp.copy(), rsp
                since_improve = 0
            else:
                since_improve = 0

    print("final R=%.9f (N=%d)" % (bestRH, bestH.size))

    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def _refine(h, deadline, rounds=8):
    """Alternate full tie polish, beta-smoothed passes, and peak-window polish."""
    best = h.copy()
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5,
                               time.process_time() + 5.0), tie=True)
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        for beta in (50.0, 200.0, 1000.0):
            if time.process_time() >= deadline - 0.6:
                break
            pb = _lbfgs_block(best, np.arange(best.size), 150,
                             min(deadline - 0.4,
                                 time.process_time() + 3.5), beta=beta)
            rb = R_of(pb)
            if rb > bestR:
                best, bestR = pb, rb
        for pad in (0.10, 0.05, 0.02):
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=64)
            hp = _lbfgs_block(best, win, 150,
                             min(deadline - 0.3,
                                 time.process_time() + 3.0), tie=True)
            rpp = R_of(hp)
            if rpp > bestR:
                best, bestR = hp, rpp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    f01, f1, f5 = _nearmax_fracs(best)
    print("base R=%.9f (N=%d) near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
          % (bestR, best.size, f01, f1, f5))

    rng = np.random.default_rng(987654321)

    # Phase 1: full tie polish + beta ladder
    h, r = _refine(best, t0 + budget_seconds * 0.55, rounds=10)
    if r > bestR + 1e-15:
        best, bestR = h, r
    f01, f1, f5 = _nearmax_fracs(best)
    print("P1 R=%.9f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
          % (bestR, f01, f1, f5))

    # Phase 2: value-band active-set polish with dilation
    band_end = t0 + budget_seconds * 0.80
    band_edges = [(0.0, 0.05), (0.05, 0.20), (0.20, 0.50),
                  (0.50, 0.80), (0.80, 0.95), (0.95, 1.001)]
    cyc = 0
    while time.process_time() < band_end - 2.0:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        order = rng.permutation(len(band_edges))
        gains = []
        for bi in order:
            if time.process_time() >= band_end - 1.5:
                break
            lo, hi = band_edges[bi]
            lo *= M; hi *= M
            sel = np.flatnonzero((best > 0) & (v >= lo) & (v < hi))
            if sel.size == 0:
                gains.append(0.0)
                continue
            active = _dilate(sel, n, 20)
            if active.size < 20 or active.size > 0.85 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 250,
                              min(band_end - 1.0,
                                  time.process_time() + 5.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
            if time.process_time() < band_end - 1.0:
                win = _peak_window(best, pad_frac=0.05, extra=64)
                ht2 = _lbfgs_block(best, win, 150,
                                   min(band_end - 0.5,
                                       time.process_time() + 3.0), beta=200.0)
                r2 = R_of(ht2)
                if r2 > bestR + 1e-15:
                    best, bestR = ht2.copy(), r2
        f01, f1, f5 = _nearmax_fracs(best)
        print("band cyc=%d R=%.9f gains=%s near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (cyc, bestR,
                 " ".join("%.1e" % g for g in gains), f01, f1, f5))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # Phase 3: final refine
    fd = t0 + budget_seconds * 0.98
    if time.process_time() < fd - 2.0:
        h2, r2 = _refine(best, fd - 0.5, rounds=6)
        if r2 > bestR + 1e-15:
            best, bestR = h2, r2

    print("final R=%.9f (start %.9f, N=%d)"
          % (bestR, startR, best.size))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta_pen(h, beta, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm

    S = Lf >= tau * mx
    if np.any(S):
        vals = Lf[S]
        mu = vals.mean()
        var = np.mean((vals - mu) ** 2)
        nS = vals.size
        dvar_dL = np.zeros_like(Lf)
        dvar_dL[S] = (2.0 / nS) * (vals - mu)
        pen = kappa * var / (mx * mx)
        gLf += kappa * dvar_dL / (mx * mx)
        idx = np.flatnonzero(Lf >= (1.0 - 1e-12) * mx)
        wm = 1.0 / idx.size
        gLf[idx] += (-2.0 * kappa * var / (mx * mx * mx)) * wm
    else:
        pen = 0.0

    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tau=0.9, kappa=0.0,
                 tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta_pen(hh, beta, tau, kappa))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _max_mean(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(mx / Lf.mean())


def _stats(h):
    return (_frac_near_max(h, 1e-3), _frac_near_max(h, 1e-2),
            _frac_near_max(h, 5e-2), _max_mean(h))


def _report(tag, h, r):
    f01, f1, f5, mm = _stats(h)
    zf = float(np.mean(h <= 0))
    print("%s R=%.12f nm 0.1/1/5%%=%.4f/%.4f/%.4f mm=%.2f zf=%.3f"
          % (tag, r, f01, f1, f5, mm, zf))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    _report("before", best, bestR)

    alt_best = None
    altR = -1.0

    Nfull = best.size
    allidx = np.arange(Nfull)

    h_cur = best.copy()
    curR = bestR

    # ---- (1) deeper flat-top ladder at beta=1e6 ----
    ladder = [(0.5, 3000.0), (0.4, 3000.0), (0.3, 3000.0),
              (0.25, 10000.0), (0.2, 30000.0)]
    for (tau, kappa) in ladder:
        if time.process_time() >= deadline - 12.0:
            break
        h_new = _lbfgs_block(
            h_cur, allidx, 120,
            min(deadline - 11.0, time.process_time() + 5.0),
            beta=1e6, tau=tau, kappa=kappa)
        r = R_of(h_new)
        _report("flat tau=%.2f kap=%.0f" % (tau, kappa), h_new, r)
        if r > curR + 1e-15:
            h_cur, curR = h_new, r
        # exact tie polish
        if time.process_time() < deadline - 10.0:
            h_sh = _lbfgs_block(
                h_cur, allidx, 80,
                min(deadline - 9.0, time.process_time() + 2.5), tie=True)
            rs = R_of(h_sh)
            _report("  tie polish", h_sh, rs)
            if rs > curR + 1e-15:
                h_cur, curR = h_sh, rs
        # peak-window polish at pad 0.05
        if time.process_time() < deadline - 9.0:
            win = _peak_window(h_cur, pad_frac=0.05, extra=128)
            hp = _lbfgs_block(
                h_cur, win, 80,
                min(deadline - 8.0, time.process_time() + 2.0), tie=True)
            rp = R_of(hp)
            _report("  peak pad=0.05", hp, rp)
            if rp > curR + 1e-15:
                h_cur, curR = hp, rp
        if curR > bestR + 1e-15:
            best, bestR = h_cur.copy(), curR

    if curR > altR:
        altR = curR
        alt_best = h_cur.copy()

    # ---- (2) mass-preserving 2x lift to N=65536 ----
    if time.process_time() < deadline - 15.0:
        h2 = np.repeat(h_cur, 2)
        k = np.array([0.25, 0.5, 0.25])
        h2 = np.convolve(h2, k, mode='same')
        h2 = _rescale(h2)
        r2 = R_of(h2)
        _report("lift x2", h2, r2)
        if r2 > curR + 1e-15:
            h_cur, curR = h2, r2
        idx2 = np.arange(h_cur.size)
        # beta=1e7 softmax full-array block
        h_l = _lbfgs_block(
            h_cur, idx2, 150,
            min(deadline - 13.0, time.process_time() + 6.0),
            beta=1e7, tau=0.3, kappa=3000.0)
        rl = R_of(h_l)
        _report("lift soft b=1e7", h_l, rl)
        if rl > curR + 1e-15:
            h_cur, curR = h_l, rl
        # exact tie polish
        if time.process_time() < deadline - 8.0:
            h_t = _lbfgs_block(
                h_cur, np.arange(h_cur.size), 100,
                min(deadline - 7.0, time.process_time() + 4.0), tie=True)
            rt = R_of(h_t)
            _report("lift tie", h_t, rt)
            if rt > curR + 1e-15:
                h_cur, curR = h_t, rt
        # peak-window polishes at pads 0.05/0.03
        for pad in (0.05, 0.03):
            if time.process_time() < deadline - 5.0:
                win = _peak_window(h_cur, pad_frac=pad, extra=128)
                ht = _lbfgs_block(
                    h_cur, win, 100,
                    min(deadline - 4.0, time.process_time() + 2.5), tie=True)
                rtp = R_of(ht)
                _report("lift peak pad=%.2f" % pad, ht, rtp)
                if rtp > curR + 1e-15:
                    h_cur, curR = ht, rtp
        if curR > bestR + 1e-15:
            best, bestR = h_cur.copy(), curR
        if curR > altR:
            altR = curR
            alt_best = h_cur.copy()

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    _report("after", best, bestR)
    print("final R=%.12f (start %.12f, N=%d, ties=%d, mm=%.2f)"
          % (bestR, startR, best.size, _tie_count(best), _max_mean(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-15:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

