    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.05, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _near_max_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _lift(h, N):
    n = h.size
    if n == N:
        return h.copy()
    x_old = np.linspace(0, 1, n, endpoint=False)
    x_new = np.linspace(0, 1, N, endpoint=False)
    return np.interp(x_new, x_old, h)


def _lift2x(h):
    """Mass-preserving 2x lift: repeat then smooth twice with [0.25,0.5,0.25]."""
    h2 = np.repeat(h, 2)
    k = np.array([0.25, 0.5, 0.25])
    for _ in range(2):
        h2 = np.convolve(h2, k, mode='same')
    return _rescale(np.clip(h2, 0, None))


def _stats(h):
    s = h.sum()
    zf = float(np.mean(h <= 1e-12))
    mm = float(h.max() / (s / h.size)) if s > 0 else 0.0
    return zf, mm


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    f0 = _near_max_fracs(best)
    zf0, mm0 = _stats(best)
    print("base R=%.9f N=%d zero=%.3f max/mean=%.2f fracs=%.4f/%.4f/%.4f" %
          (bestR, best.size, zf0, mm0, f0[0], f0[1], f0[2]))

    alt_best = None
    alt_bestR = -1.0

    def consider(h, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if h is None:
            return None
        h = _rescale(np.clip(h, 0, None))
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR, origin = h.copy(), r, tag
            f = _near_max_fracs(best)
            zf, mm = _stats(best)
            print("%s NEW BEST R=%.9f zero=%.3f max/mean=%.2f fracs=%.4f/%.4f/%.4f" %
                  (tag, bestR, zf, mm, f[0], f[1], f[2]))
        elif r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r
        return h

    # ---- Phase A: full-array tie-aware L-BFGS-B ----
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 400, min(deadline - 0.5, t0 + 12.0),
                            lambda hh: _fun_grad_tie(hh, 1e-10))
        consider(ht, 'A_tie_all')

    # ---- Phase B: peak-window polish at pads 0.10, 0.05, 0.03 ----
    if time.process_time() < deadline - 2.0:
        work = best.copy()
        for pad in [0.10, 0.05, 0.03]:
            if time.process_time() >= min(deadline - 1.0, t0 + 20.0):
                break
            win = _peak_window(work, tol=0.95, pad_frac=pad, extra=128)
            ht = _lbfgs_block(work, win, 100, min(deadline - 0.5, t0 + 20.0),
                              lambda hh: _fun_grad_tie(hh, 1e-10))
            if R_of(ht) > R_of(work) + 1e-14:
                work = ht
            consider(ht, 'B_pad%.2f' % pad)

    # ---- Phase C: mass-preserving 2x lift + tie polish + peak pads ----
    if time.process_time() < deadline - 2.0:
        for round_i in range(2):
            if time.process_time() >= min(deadline - 1.0, t0 + 40.0):
                break
            if best.size * 2 > 1000000:
                break
            h2 = _lift2x(best)
            ht = _lbfgs_all_pos(h2, 300, min(deadline - 0.5, t0 + 40.0),
                                lambda hh: _fun_grad_tie(hh, 1e-10))
            improved = consider(ht, 'C_lift2x_r%d' % round_i)
            work = best.copy()
            for pad in [0.05, 0.03]:
                if time.process_time() >= min(deadline - 1.0, t0 + 40.0):
                    break
                win = _peak_window(work, tol=0.95, pad_frac=pad, extra=128)
                ht2 = _lbfgs_block(work, win, 100,
                                   min(deadline - 0.5, t0 + 40.0),
                                   lambda hh: _fun_grad_tie(hh, 1e-10))
                if R_of(ht2) > R_of(work) + 1e-14:
                    work = ht2
                consider(ht2, 'C_r%d_pad%.2f' % (round_i, pad))
            if R_of(best) <= R_of(ht) + 1e-14 and round_i == 0:
                # no improvement from lift; skip second round
                pass

    # ---- Phase D: beta-softmax full-array passes ----
    if time.process_time() < deadline - 2.0:
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(best, 100, deadline - 0.5,
                                lambda hh, b=beta: _fun_grad_beta(hh, b))
            consider(ht, 'D_beta%g' % beta)
            if time.process_time() < deadline - 1.0:
                ht2 = _lbfgs_all_pos(best, 50, deadline - 0.5,
                                     lambda hh: _fun_grad_tie(hh, 1e-10))
                consider(ht2, 'D_beta%g_tie' % beta)

    # ---- Final tie polish ----
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3,
                            lambda hh: _fun_grad_tie(hh, 1e-10))
        consider(ht, 'final_tie')

    f = _near_max_fracs(best)
    zf, mm = _stats(best)
    print("final R=%.9f origin=%s N=%d zero=%.3f max/mean=%.2f fracs=%.4f/%.4f/%.4f (start %.9f)" %
          (bestR, origin, best.size, zf, mm, f[0], f[1], f[2], start_bestR))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_flat(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    sel = np.flatnonzero(Lf >= tau * mx)
    if sel.size > 0:
        Ls = Lf[sel]
        r = (mx - Ls) / mx
        m_r = r.mean()
        dpen_dL = np.zeros_like(Lf)
        coef = kappa * 2.0 * m_r
        dpen_dL[sel] += coef * (-1.0 / (sel.size * mx))
        dmdx = coef * (Ls.sum() / (sel.size * mx * mx))
        gLf[idx] += dmdx / idx.size
        gLf += dpen_dL
        pen = kappa * m_r * m_r
    else:
        pen = 0.0
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, tau=None, kappa=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if tau is not None:
        def fg(hh):
            return _fun_grad_flat(hh, tau, kappa)
    else:
        fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max_abs(h, frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _zero_frac(h):
    return float(np.mean(h <= 1e-12))


def _beta_softmax(h, win, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    active = np.asarray(win, dtype=int)
    if active.size == 0:
        return h
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(active.size)
        num, dq, Lf = _num_and_dq(hh)
        mx = Lf.max()
        if mx <= 0:
            return 1e18, np.zeros(active.size)
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        z = beta * Lf / mx
        zmax = z.max()
        ez = np.exp(z - zmax)
        S = ez.sum()
        T = (zmax + np.log(S) - np.log(Lf.size)) / beta
        w = ez / S
        gLf += w / beta
        grad = _backprop(gLf, hh) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) - T
        return val, grad[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _lift(h, factor, n_target):
    hh = np.repeat(h, factor)
    if hh.size < n_target:
        hh = np.concatenate([hh, np.full(n_target - hh.size, hh[-1])])
    elif hh.size > n_target:
        hh = hh[:n_target]
    return hh


def _smooth3(h, passes=2):
    h = h.copy()
    for _ in range(passes):
        hp = np.concatenate(([h[0]], h, [h[-1]]))
        h = 0.25 * hp[:-2] + 0.5 * hp[1:-1] + 0.25 * hp[2:]
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zeros=%.3f)" % (bestR, best.size, _zero_frac(best)))
    print("frac near max 0.1/1/5%%: %.4f / %.4f / %.4f"
          % (_frac_near_max_abs(best, 1e-3), _frac_near_max_abs(best, 1e-2),
             _frac_near_max_abs(best, 5e-2)))

    alt_best = None
    altR = -1.0

    N_full = best.size
    factor = 8
    N_coarse = max(1, N_full // factor)

    # ---- Stage 1: coarse flat-top ladder ----
    hc = _coarsen(best, factor)
    hc = _rescale(hc)
    coarseR = R_of(hc)
    print("coarse N=%d R=%.9f near 5%%: %.4f"
          % (hc.size, coarseR, _frac_near_max_abs(hc, 5e-2)))

    ladder = [(0.6, 3e3), (0.5, 3e3), (0.5, 1e4),
              (0.4, 1e4), (0.4, 3e4), (0.35, 3e4)]
    best_coarse = hc.copy()
    best_coarseR = coarseR
    cur_c = hc
    cur_cR = coarseR

    # reserve ~55% of budget for coarse ladder, rest for lift/polish
    coarse_deadline = t0 + budget_seconds * 0.50

    for tau, kappa in ladder:
        if time.process_time() >= coarse_deadline - 1.0:
            break
        tlim = min(coarse_deadline, time.process_time() + 4.0)
        h_new = _lbfgs_block(cur_c, np.arange(cur_c.size), 150, tlim,
                             tau=tau, kappa=kappa)
        r_new = R_of(h_new)
        print("coarse tau=%.2f kappa=%.0f: R=%.9f near 0.1/1/5%%: %.4f/%.4f/%.4f"
              % (tau, kappa, r_new, _frac_near_max_abs(h_new, 1e-3),
                 _frac_near_max_abs(h_new, 1e-2), _frac_near_max_abs(h_new, 5e-2)))
        if r_new > best_coarseR:
            best_coarse, best_coarseR = h_new.copy(), r_new
        cur_c, cur_cR = h_new, r_new

    print("best coarse R=%.9f" % best_coarseR)

    # ---- Stage 2: lift back to full N ----
    hf = _lift(best_coarse, factor, N_full)
    hf = _smooth3(hf, passes=2)
    hf = _rescale(hf)
    rf = R_of(hf)
    print("lifted R=%.9f zeros=%.3f near 0.1/1/5%%: %.4f/%.4f/%.4f"
          % (rf, _zero_frac(hf), _frac_near_max_abs(hf, 1e-3),
             _frac_near_max_abs(hf, 1e-2), _frac_near_max_abs(hf, 5e-2)))
    if rf > altR:
        altR = rf; alt_best = hf.copy()
    if rf > bestR + 1e-15:
        best, bestR = hf.copy(), rf
    cur, curR = hf, rf

    # ---- Stage 3: full-N polishes ----
    if time.process_time() < deadline - 8.0:
        tlim = min(deadline - 7.5, time.process_time() + 4.0)
        ht = _lbfgs_block(cur, np.arange(cur.size), 100, tlim, tie=True)
        rt = R_of(ht)
        print("tie polish(100): R=%.9f near 5%%: %.4f"
              % (rt, _frac_near_max_abs(ht, 5e-2)))
        if rt > altR:
            altR = rt; alt_best = ht.copy()
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
        if rt > curR:
            cur, curR = ht, rt

    if time.process_time() < deadline - 6.0:
        tlim = min(deadline - 5.5, time.process_time() + 3.0)
        hb = _lbfgs_block(cur, np.arange(cur.size), 80, tlim,
                          tau=0.35, kappa=3000.0)
        # beta=1e7 softmax equivalent: use flat with high kappa as proxy plus tie
        rb = R_of(hb)
        print("full flat (0.35,3e3): R=%.9f near 5%%: %.4f"
              % (rb, _frac_near_max_abs(hb, 5e-2)))
        if rb > altR:
            altR = rb; alt_best = hb.copy()
        if rb > bestR + 1e-15:
            best, bestR = hb.copy(), rb
        if rb > curR:
            cur, curR = hb, rb

    if time.process_time() < deadline - 4.0:
        tlim = min(deadline - 3.5, time.process_time() + 2.5)
        ht = _lbfgs_block(cur, np.arange(cur.size), 80, tlim, tie=True)
        rt = R_of(ht)
        print("tie polish(80): R=%.9f near 5%%: %.4f"
              % (rt, _frac_near_max_abs(ht, 5e-2)))
        if rt > altR:
            altR = rt; alt_best = ht.copy()
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
        if rt > curR:
            cur, curR = ht, rt

    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 2.0:
            break
        win = _peak_window(cur, tol=0.95, pad_frac=pad, extra=32)
        tlim = min(deadline - 1.5, time.process_time() + 1.5)
        hp = _lbfgs_block(cur, win, 120, tlim, tie=True)
        rp = R_of(hp)
        print("peak pad=%.2f: R=%.9f near 5%%: %.4f"
              % (pad, rp, _frac_near_max_abs(hp, 5e-2)))
        if rp > altR:
            altR = rp; alt_best = hp.copy()
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
        if rp > curR:
            cur, curR = hp, rp

    # ---- Stage 4: final full tie polish ----
    if time.process_time() < deadline - 0.8:
        tlim = min(deadline - 0.3, time.process_time() + 3.0)
        hf2 = _lbfgs_block(cur, np.arange(cur.size), 200, tlim, tie=True)
        rf2 = R_of(hf2)
        print("final tie polish: R=%.9f zeros=%.3f near 0.1/1/5%%: %.4f/%.4f/%.4f"
              % (rf2, _zero_frac(hf2), _frac_near_max_abs(hf2, 1e-3),
                 _frac_near_max_abs(hf2, 1e-2), _frac_near_max_abs(hf2, 5e-2)))
        if rf2 > altR:
            altR = rf2; alt_best = hf2.copy()
        if rf2 > bestR + 1e-15:
            best, bestR = hf2.copy(), rf2

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d, zeros=%.3f)"
          % (bestR, startR, best.size, _tie_count(best), _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _upsample(h, k):
    n = h.size
    m = n * k
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(m) + 0.5) / m
    return np.interp(x_new, x_old, h, left=h[0], right=h[-1])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            keep = _rescale(base)
            startR = R_of(keep)
        else:
            keep, startR = None, 0.0
    else:
        keep, startR = None, 0.0

    if keep is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        keep = _rescale(h)
        startR = R_of(keep)

    best = keep.copy()
    bestR = startR
    print("base R=%.9f (N=%d) frac5=%.4f"
          % (bestR, best.size, _frac_near_max(best, 0.95)))

    # Phase 1: refine at current resolution on the full array.
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_block(best, np.arange(best.size), 600,
                          min(deadline - 1.0, time.process_time() + 20.0))
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("phase1 full R=%.9f" % bestR)

    # Phase 2: peak-window drill-down at current resolution.
    if time.process_time() < deadline - 2.0:
        win = _peak_window(best, pad_frac=0.05, extra=256)
        ht = _lbfgs_block(best, win, 500,
                          min(deadline - 1.0, time.process_time() + 15.0))
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("phase2 win R=%.9f" % bestR)

    # Phase 3: upsample to higher resolution and re-optimize.
    for k in (2, 2):
        if time.process_time() >= deadline - 5.0 or best.size * k > 1000000:
            break
        up = _rescale(_upsample(best, k))
        win = _peak_window(up, pad_frac=0.1, extra=384)
        ht = _lbfgs_block(up, win, 400,
                          min(deadline - 2.0, time.process_time() + 12.0))
        r = R_of(ht)
        print("phase3 %dx win R=%.9f (N=%d)" % (k, r, ht.size))
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    # Phase 4: alternating full-array / window polish until the deadline.
    while time.process_time() < deadline - 1.0:
        rem = deadline - time.process_time()
        chunk = min(rem * 0.6, 8.0)
        win = _peak_window(best, pad_frac=0.02, extra=128)
        ht = _lbfgs_block(best, win, 400,
                          min(deadline - 0.5, time.process_time() + chunk))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        else:
            break

    print("final R=%.9f (start %.9f, N=%d, frac5=%.4f)"
          % (bestR, startR, best.size, _frac_near_max(best, 0.95)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.fft import next_fast_len


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_softmin(h, beta=1e5, eta=1.0):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    e2 = np.exp(np.clip(-beta * (Lf - mx), -60.0, 60.0))
    Z2 = e2.sum()
    if Z2 > 0:
        w2 = e2 / Z2
        smin = mx - np.log(Z2) / beta
        if smin > 1e-30:
            gLf2 = -w2 / smin
            grad2 = _backprop(gLf2, h)
            grad = grad - eta * grad2
            val = val - eta * np.log(smin)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, softmin=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if softmin:
        fg = _fun_grad_softmin
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    drefine = 0.0
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            drefine = r - bestR
            best, bestR = ht.copy(), r
    return best, bestR, drefine


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


# ---- New idea: flat-top construction via direct L-BFGS from a flat seed ----

def _flat_seed_like(h, plateau_frac=0.85, ramp_frac=0.10):
    """Build a flat-top seed with the same support as h."""
    n = h.size
    s0, s1 = _active_support(h)
    out = np.zeros(n)
    lo = s0
    hi = s1
    if hi <= lo:
        return h.copy()
    span = hi - lo
    ramp = max(1, int(ramp_frac * span))
    plateau_hi = hi - ramp
    plateau_lo = lo + ramp
    if plateau_lo >= plateau_hi:
        out[lo:hi + 1] = 1.0
    else:
        out[plateau_lo:plateau_hi + 1] = 1.0
        t = np.linspace(0.0, np.pi, ramp)
        rampup = 0.5 * (1.0 - np.cos(t))
        out[lo:lo + ramp] = rampup
        out[plateau_hi:hi + 1] = rampup[::-1]
    return out


def _flat_top_search(start, bestR, deadline, seed_fracs=(0.80, 0.90, 0.94, 0.97)):
    """Try several flat-top seeds and polish them with L-BFGS."""
    n = start.size
    best_cand = None
    best_candR = bestR
    for pf in seed_fracs:
        if time.process_time() >= deadline - 2.0:
            break
        ramp = 0.5 * (1.0 - pf)
        seed = _flat_seed_like(start, plateau_frac=pf, ramp_frac=ramp)
        # scale seed to match start's mass (roughly)
        if seed.sum() > 0:
            seed = seed * (start.sum() / seed.sum())
        seed = _rescale(seed)
        # polish with L-BFGS on full support
        h = _lbfgs_all_pos(seed, 400, deadline - 1.0, beta=0.0)
        r = R_of(h)
        if r > best_candR + 1e-13:
            best_cand = h
            best_candR = r
        # then a beta pass
        if time.process_time() < deadline - 1.0:
            h2 = _lbfgs_all_pos(h, 200, deadline - 1.0, beta=1e7)
            r2 = R_of(h2)
            if r2 > best_candR + 1e-13:
                best_cand = h2
                best_candR = r2
    return best_cand, best_candR


def _phase_flat(best, deadline, n_iters=30):
    n = best.size
    s0, s1 = _active_support(best)
    if s1 <= s0:
        return best
    M = next_fast_len(4 * n)
    gk = np.zeros(2 * n + 1, dtype=float)
    lo = 4 * s0
    hi = 4 * s1
    if hi <= lo:
        return best
    span = hi - lo
    ramp = max(1, int(0.035 * span))
    gk[lo:hi + 1] = 1.0
    if ramp > 1:
        t = np.linspace(0.0, np.pi, ramp)
        rampup = 0.5 * (1.0 - np.cos(t))
        gk[lo:lo + ramp] *= rampup
        gk[hi - ramp + 1:hi + 1] *= rampup[::-1]
    gp = np.zeros(M, dtype=float)
    L = min(M, gk.size)
    gp[:L] = gk[:L]
    A = np.sqrt(np.abs(np.fft.fft(gp)))
    f_pad = np.zeros(M, dtype=float)
    f_pad[:n] = np.clip(best, 0, None)
    mask = np.zeros(M, dtype=bool)
    mask[s0:s1 + 1] = True
    cand = best.copy()
    candR = R_of(cand)
    for it in range(n_iters):
        if time.process_time() >= deadline - 1.0:
            break
        F = np.fft.fft(f_pad)
        mag = np.abs(F)
        phase = F / np.maximum(mag, 1e-30)
        f_new = np.real(np.fft.ifft(A * phase))
        f_new = np.clip(f_new, 0.0, None)
        f_new[~mask] = 0.0
        f_pad = 0.7 * f_new + 0.3 * f_pad
        f_pad = np.clip(f_pad, 0.0, None)
        f_pad[~mask] = 0.0
        hc = f_pad[:n].copy()
        if hc.sum() <= 0:
            break
        hc = _rescale(hc)
        f_pad[:n] = hc
        f_pad[n:] = 0.0
        r = R_of(hc)
        if r > candR + 1e-13:
            cand = hc
            candR = r
    return cand


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # Phase 1: flat-top exploration early, since it's a genuinely different idea.
    flat_cand, flatR = _flat_top_search(start_best, start_bestR,
                                        deadline - 25.0)
    if flat_cand is not None:
        print("flat-top seed R=%.7f" % flatR)
        if flatR > altR:
            alt_cand, altR = flat_cand.copy(), flatR
        if flatR > bestR + 1e-13:
            best, bestR = flat_cand.copy(), flatR
            print("flat-top BEATS base R=%.7f" % bestR)

    # Phase 2: phase-flat + L-BFGS fused rounds
    loop_deadline = deadline - 15.0
    for rnd in range(3):
        if time.process_time() >= loop_deadline:
            break
        try:
            cand = _phase_flat(best, loop_deadline, n_iters=30)
            r = R_of(cand)
            if r > bestR + 1e-13:
                best, bestR = cand.copy(), r
            if r > altR:
                alt_cand, altR = cand.copy(), r
        except Exception as e:
            print("phase-flat failed: %s" % e)
            continue
        if time.process_time() >= loop_deadline:
            break
        ht = _lbfgs_all_pos(best, 60, loop_deadline, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        if time.process_time() >= loop_deadline:
            break
        ht = _lbfgs_all_pos(best, 60, loop_deadline, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        if time.process_time() >= loop_deadline:
            break
        ht = _lbfgs_all_pos(best, 60, loop_deadline, softmin=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        print("round %d fused R=%.7f" % (rnd, bestR))

    if time.process_time() < deadline - 4.0:
        best, bestR, _ = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f" % bestR)

    # Phase 3: fill remaining time with L-BFGS polishing (cheaper than dip loop,
    # which produced no gains in the original).
    while time.process_time() < deadline - 3.0:
        ht = _lbfgs_all_pos(best, 300, deadline - 3.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            print("polish R=%.7f" % bestR)
        else:
            break
    # A final flat-top probe at the very end with tighter plateau
    if time.process_time() < deadline - 3.0:
        fc, fr = _flat_top_search(best, bestR, deadline - 1.0,
                                  seed_fracs=(0.94, 0.96, 0.98))
        if fc is not None and fr > bestR + 1e-13:
            best, bestR = fc, fr
            print("flat-top end R=%.7f" % bestR)
        if fc is not None and fr > altR:
            alt_cand, altR = fc, fr

    if time.process_time() < deadline - 0.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, soft=0.0):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    if soft > 0:
        e = np.exp(np.clip((Lf - mx) / soft, -60.0, 60.0))
        w = e / e.sum()
        sm = mx + soft * np.log(e.sum())
        gLf += w / sm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    else:
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        w = 1.0 / idx.size
        gLf[idx] += w / mx
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, soft=0.0):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh, soft)
        return val, g[active]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _upsample2(h):
    n = h.size
    out = np.zeros(2 * n)
    out[0::2] = h
    out[1::2] = h
    ker = np.array([0.25, 0.5, 0.25])
    sm = np.convolve(out, ker, mode='same')
    return sm


def _refine(h, deadline, bestR):
    """Alternate full-array soft/tie polish and peak-window polish."""
    best = h
    pads = [0.15, 0.08, 0.04, 0.02]
    pi = 0
    while time.process_time() < deadline - 0.6:
        # soft-tie full polish (escapes exact-tie flatness)
        soft = 1e-3 if (pi % 2 == 0) else 0.0
        tcap = min(deadline - 0.3, time.process_time() + 4.0)
        h2 = _lbfgs_block(best, np.arange(best.size), 200, tcap, soft=soft)
        r = R_of(h2)
        if r > bestR + 1e-15:
            best, bestR = h2, r
        if time.process_time() >= deadline - 0.6:
            break
        pad = pads[pi % len(pads)]
        pi += 1
        win = _peak_window(best, pad_frac=pad, extra=64)
        tcap = min(deadline - 0.3, time.process_time() + 3.0)
        h3 = _lbfgs_block(best, win, 300, tcap, soft=0.0)
        r = R_of(h3)
        if r > bestR + 1e-15:
            best, bestR = h3, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d) ties=%d" % (bestR, best.size, _tie_count(best)))
    print("frac near max before: %.4f" % _frac_near_max(best, 1e-3))

    # Try an upsample candidate once (cheap): 2x with smoothing, then polish.
    alt = None
    altR = -1.0
    if best.size * 2 <= 1000000 and time.process_time() < deadline - 8.0:
        hu = _rescale(_upsample2(best))
        tcap = min(deadline - 4.0, time.process_time() + 4.0)
        hu = _lbfgs_block(hu, np.arange(hu.size), 80, tcap, soft=0.0)
        r = R_of(hu)
        alt, altR = hu, r
        print("upsample candidate R=%.9f (N=%d)" % (r, hu.size))
        if r > bestR + 1e-15:
            best, bestR = hu, r

    # Main refinement loop: alternate full/peak-window tie + soft-tie polishes.
    best, bestR = _refine(best, deadline, bestR)
    print("frac near max after: %.4f" % _frac_near_max(best, 1e-3))

    # Keep the upsample result as alternative if it's a different shape and not worse.
    if alt is not None and altR > 0 and alt.size != best.size and altR <= bestR + 1e-12:
        # Only offer alternative if it scores at least as much as start (so it's kept).
        if altR > startR - 1e-12:
            print("final R=%.12f (start %.12f, N=%d, ties=%d)"
                  % (bestR, startR, best.size, _tie_count(best)))
            return {"best": best, "alternative": alt}

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize, minimize_scalar
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


# ---------- Riemannian (projected-gradient) L-BFGS ----------

def _riemann_lbfgs(h0, maxiter, deadline):
    """L-BFGS-B with the scale direction projected out of the gradient,
    renormalising max(f*f)=1 after every iterate."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = _rescale(np.clip(h0, 0, None))
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        if hh.sum() <= 0:
            return 1e18, np.zeros(n)
        val, g = _fun_grad_tie(hh)
        hh2 = hh
        denom = float(np.dot(hh2, hh2))
        if denom > 0:
            g = g - (float(np.dot(g, hh2)) / denom) * hh2
        return val, g

    cb = _make_cb(deadline - 0.2)
    x0 = h.copy()
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


# ---------- seeds ----------

def _decimate(h, k):
    n = h.size
    m = n // k
    if m <= 0:
        return h.copy()
    hh = h[:m * k].reshape(m, k)
    return hh.mean(axis=1)


def _prolongate(h, N):
    """Cumulative-mass interpolation to length N."""
    n = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N) / N
    xs = np.linspace(0.0, total, N + 1)
    # positions in original index space
    src = np.linspace(0.0, n, N + 1)
    out = np.interp(xs, c, np.arange(n + 1, dtype=float))
    # out is in index space; convert to heights via derivative of cumulative mass
    hh = np.diff(out)
    hh = np.clip(hh, 0, None)
    if hh.sum() <= 0:
        return np.ones(N) / N
    return hh


def _comb(N, b, cap, A):
    i = np.arange(N, dtype=float)
    u = (i + 0.5) / N
    v = (N - i - 0.5) / N
    h = b + A * (u ** -0.5 + v ** -0.5)
    return np.minimum(h, cap)


def _comb_seed(N):
    rng = np.random.default_rng(7)
    best = None
    bestR = -1.0
    for _ in range(300):
        b = rng.uniform(0.0, 0.5)
        cap = rng.uniform(1.0, 20.0)
        A = rng.uniform(0.01, 2.0)
        h = _comb(256, b, cap, A)
        r = R_of(h)
        if r > bestR:
            bestR = r
            best = (b, cap, A)
    b0, c0, A0 = best

    def negR(p):
        b, cap, A = p
        if b < 0 or cap <= 0 or A < 0:
            return 1e6
        h = _comb(256, b, cap, A)
        return -R_of(h)

    try:
        res = minimize(negR, [b0, c0, A0], method='Nelder-Mead',
                       options={'maxiter': 400, 'xatol': 1e-4, 'fatol': 1e-8})
        if res is not None and -res.fun > bestR:
            b0, c0, A0 = res.x
            b0 = max(0.0, b0); c0 = max(1e-3, c0); A0 = max(0.0, A0)
    except Exception:
        pass
    h256 = _comb(256, b0, c0, A0)
    return _prolongate(h256, N)


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 4096
        best = _rescale(_comb_seed(N))
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Build three seeds
    seeds = []
    try:
        seeds.append(("dec32", _rescale(_decimate(best, 32))))
    except Exception:
        pass
    try:
        seeds.append(("dec8", _rescale(_decimate(best, 8))))
    except Exception:
        pass
    try:
        seeds.append(("comb4096", _rescale(_comb_seed(4096))))
    except Exception:
        pass

    # Evaluate seeds
    for name, s in seeds:
        r = R_of(s)
        print("seed %-10s N=%d R=%.9f" % (name, s.size, r))
        if r > bestR:
            best, bestR = s.copy(), r

    alt_best = None
    altR = -1.0

    # Run projected vs plain tracks on each seed
    for name, s in seeds:
        if time.process_time() >= deadline - 2.0:
            break
        # split remaining time between the two tracks
        remain = deadline - time.process_time()
        if remain < 1.0:
            break
        half = remain * 0.5

        # Riemannian track
        tlim = time.process_time() + half
        hr = _riemann_lbfgs(s, 400, tlim)
        rr = R_of(hr)
        # one plain tie polish
        if time.process_time() < tlim - 0.2:
            hr2 = _lbfgs_block(hr, np.arange(hr.size), 150,
                               min(tlim, time.process_time() + half * 0.4), tie=True)
            rr2 = R_of(hr2)
            if rr2 > rr:
                hr, rr = hr2, rr2

        # Plain track
        tlim2 = time.process_time() + half
        hp = _lbfgs_block(s, np.arange(s.size), 400, tlim2, tie=True)
        rp = R_of(hp)

        print("  %-10s projected R=%.9f  plain R=%.9f" % (name, rr, rp))

        if rr > altR:
            altR = rr
            alt_best = hr.copy()
        if rp > altR:
            altR = rp
            alt_best = hp.copy()
        if rr > bestR + 1e-15:
            best, bestR = hr.copy(), rr
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp

    # Final safety: plain tie polish on best
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR and start is not None:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.ndimage import gaussian_filter1d


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _pair_stats(h):
    """max_i |h[2i]/h[2i+1]-1| and fraction of pairs with rel diff > 1e-3."""
    n = h.size // 2
    if n < 1:
        return 0.0, 0.0
    a = h[0:2 * n:2]
    b = h[1:2 * n:2]
    denom = np.maximum(np.maximum(a, b), 1e-300)
    rel = np.abs(a - b) / denom
    return float(rel.max()), float(np.mean(rel > 1e-3))


def _smooth_field(n, L, rng):
    d = rng.standard_normal(n)
    if L > 1:
        d = gaussian_filter1d(d, sigma=float(L), mode='wrap')
    sd = d.std()
    if sd <= 0:
        return np.zeros(n)
    return (d - d.mean()) / sd


def _release(base, a, d):
    """Apply antisymmetric release: even *= (1+a*d), odd *= (1-a*d)."""
    h = base.copy()
    n = h.size // 2
    if n < 1:
        return _rescale(h)
    h[0:2 * n:2] *= (1.0 + a * d)
    h[1:2 * n:2] *= (1.0 - a * d)
    h = np.clip(h, 0, None)
    return _rescale(h)


def _full_polish(h, deadline, maxiter=250):
    """Full-array tie L-BFGS then peak-window polish."""
    ht = _lbfgs_all_pos(h, maxiter, deadline, beta=1e7)
    if time.process_time() < deadline - 0.5:
        win = _peak_window(ht, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(ht, win, 300, deadline, beta=1e7)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    N = best.size
    n_pairs = N // 2
    rng = np.random.default_rng(20240607)

    # Pre-generate smooth fields for each correlation length
    fields = {}
    for L in (256, 32, 8):
        if n_pairs >= 1:
            fields[L] = _smooth_field(n_pairs, L, rng)

    # ---- Phase A: antisymmetric release grid (spend >=85% of budget) ----
    grid_deadline = t0 + budget_seconds * 0.85
    amplitudes = [3e-2, 1e-2, 3e-3]
    lengths = [256, 32, 8]

    # Track best released candidate (for alternative reporting)
    rel_best = None
    rel_bestR = -1.0

    for a in amplitudes:
        for L in lengths:
            if time.process_time() >= grid_deadline - 1.0:
                break
            d = fields[L]
            h_rel = _release(best, a, d)
            ht = _full_polish(h_rel, deadline - 0.5, maxiter=250)
            r = R_of(ht)
            mx_rel, frac_rel = _pair_stats(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                origin = 'release_a%.0e_L%d' % (a, L)
                print("release a=%.0e L=%d R=%.9f NEW BEST maxrel=%.3e frac=%.3e"
                      % (a, L, bestR, mx_rel, frac_rel))
            else:
                if r > rel_bestR:
                    rel_best, rel_bestR = ht.copy(), r
                print("release a=%.0e L=%d R=%.9f (best %.9f) maxrel=%.3e frac=%.3e"
                      % (a, L, r, bestR, mx_rel, frac_rel))
        if time.process_time() >= grid_deadline - 1.0:
            break

    # ---- Annealed second round from best with a/4 ----
    if time.process_time() < grid_deadline - 1.0 and n_pairs >= 1:
        # pick the amplitude that produced the best improvement, else smallest
        a2 = 3e-3 / 4.0
        L2 = 32
        d = _smooth_field(n_pairs, L2, rng)
        h_rel = _release(best, a2, d)
        ht = _full_polish(h_rel, deadline - 0.5, maxiter=250)
        r = R_of(ht)
        mx_rel, frac_rel = _pair_stats(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = 'anneal_a%.0e_L%d' % (a2, L2)
            print("anneal a=%.0e L=%d R=%.9f NEW BEST maxrel=%.3e frac=%.3e"
                  % (a2, L2, bestR, mx_rel, frac_rel))
        else:
            if r > rel_bestR:
                rel_best, rel_bestR = ht.copy(), r
            print("anneal a=%.0e L=%d R=%.9f (best %.9f) maxrel=%.3e frac=%.3e"
                  % (a2, L2, r, bestR, mx_rel, frac_rel))

    # ---- Further local rounds from best until deadline ----
    round_idx = 0
    while time.process_time() < deadline - 2.0:
        round_idx += 1
        # alternate small releases and pure polishes
        if round_idx % 2 == 1:
            a = 1e-3 / (1.0 + round_idx)
            L = [256, 32, 8][round_idx % 3]
            d = _smooth_field(n_pairs, L, rng)
            h_rel = _release(best, a, d)
            ht = _full_polish(h_rel, deadline - 0.5, maxiter=250)
        else:
            ht = _full_polish(best, deadline - 0.5, maxiter=250)
        r = R_of(ht)
        mx_rel, frac_rel = _pair_stats(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = 'local%d' % round_idx
            print("local round %d R=%.9f NEW BEST maxrel=%.3e frac=%.3e"
                  % (round_idx, bestR, mx_rel, frac_rel))
        else:
            if r > rel_bestR:
                rel_best, rel_bestR = ht.copy(), r
            if round_idx % 2 == 1:
                print("local round %d R=%.9f (best %.9f) maxrel=%.3e frac=%.3e"
                      % (round_idx, r, bestR, mx_rel, frac_rel))

    # Final pair statistics report
    mx_rel, frac_rel = _pair_stats(best)
    print("final pair stats: max_i|h[2i]/h[2i+1]-1|=%.3e frac(>1e-3)=%.3e"
          % (mx_rel, frac_rel))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)"
          % (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if rel_best is not None and rel_best.size == best.size and rel_bestR < bestR - 1e-14:
        result["alternative"] = rel_best
    return result

