                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _pair_stats(h):
    """max_i |h[2i]/h[2i+1]-1| and fraction of pairs with rel diff > 1e-3."""
    n = h.size // 2
    if n < 1:
        return 0.0, 0.0
    a = h[0:2 * n:2]
    b = h[1:2 * n:2]
    denom = np.maximum(np.maximum(a, b), 1e-300)
    rel = np.abs(a - b) / denom
    return float(rel.max()), float(np.mean(rel > 1e-3))


def _smooth_field(n, L, rng):
    d = rng.standard_normal(n)
    if L > 1:
        d = gaussian_filter1d(d, sigma=float(L), mode='wrap')
    sd = d.std()
    if sd <= 0:
        return np.zeros(n)
    return (d - d.mean()) / sd


def _release(base, a, d):
    """Apply antisymmetric release: even *= (1+a*d), odd *= (1-a*d)."""
    h = base.copy()
    n = h.size // 2
    if n < 1:
        return _rescale(h)
    h[0:2 * n:2] *= (1.0 + a * d)
    h[1:2 * n:2] *= (1.0 - a * d)
    h = np.clip(h, 0, None)
    return _rescale(h)


def _full_polish(h, deadline, maxiter=250):
    """Full-array tie L-BFGS then peak-window polish."""
    ht = _lbfgs_all_pos(h, maxiter, deadline, beta=1e7)
    if time.process_time() < deadline - 0.5:
        win = _peak_window(ht, pad_frac=0.15, extra=128)
        ht = _lbfgs_block(ht, win, 300, deadline, beta=1e7)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    N = best.size
    n_pairs = N // 2
    rng = np.random.default_rng(20240607)

    # Pre-generate smooth fields for each correlation length
    fields = {}
    for L in (256, 32, 8):
        if n_pairs >= 1:
            fields[L] = _smooth_field(n_pairs, L, rng)

    # ---- Phase A: antisymmetric release grid (spend >=85% of budget) ----
    grid_deadline = t0 + budget_seconds * 0.85
    amplitudes = [3e-2, 1e-2, 3e-3]
    lengths = [256, 32, 8]

    # Track best released candidate (for alternative reporting)
    rel_best = None
    rel_bestR = -1.0

    for a in amplitudes:
        for L in lengths:
            if time.process_time() >= grid_deadline - 1.0:
                break
            d = fields[L]
            h_rel = _release(best, a, d)
            ht = _full_polish(h_rel, deadline - 0.5, maxiter=250)
            r = R_of(ht)
            mx_rel, frac_rel = _pair_stats(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                origin = 'release_a%.0e_L%d' % (a, L)
                print("release a=%.0e L=%d R=%.9f NEW BEST maxrel=%.3e frac=%.3e"
                      % (a, L, bestR, mx_rel, frac_rel))
            else:
                if r > rel_bestR:
                    rel_best, rel_bestR = ht.copy(), r
                print("release a=%.0e L=%d R=%.9f (best %.9f) maxrel=%.3e frac=%.3e"
                      % (a, L, r, bestR, mx_rel, frac_rel))
        if time.process_time() >= grid_deadline - 1.0:
            break

    # ---- Annealed second round from best with a/4 ----
    if time.process_time() < grid_deadline - 1.0 and n_pairs >= 1:
        # pick the amplitude that produced the best improvement, else smallest
        a2 = 3e-3 / 4.0
        L2 = 32
        d = _smooth_field(n_pairs, L2, rng)
        h_rel = _release(best, a2, d)
        ht = _full_polish(h_rel, deadline - 0.5, maxiter=250)
        r = R_of(ht)
        mx_rel, frac_rel = _pair_stats(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = 'anneal_a%.0e_L%d' % (a2, L2)
            print("anneal a=%.0e L=%d R=%.9f NEW BEST maxrel=%.3e frac=%.3e"
                  % (a2, L2, bestR, mx_rel, frac_rel))
        else:
            if r > rel_bestR:
                rel_best, rel_bestR = ht.copy(), r
            print("anneal a=%.0e L=%d R=%.9f (best %.9f) maxrel=%.3e frac=%.3e"
                  % (a2, L2, r, bestR, mx_rel, frac_rel))

    # ---- Further local rounds from best until deadline ----
    round_idx = 0
    while time.process_time() < deadline - 2.0:
        round_idx += 1
        # alternate small releases and pure polishes
        if round_idx % 2 == 1:
            a = 1e-3 / (1.0 + round_idx)
            L = [256, 32, 8][round_idx % 3]
            d = _smooth_field(n_pairs, L, rng)
            h_rel = _release(best, a, d)
            ht = _full_polish(h_rel, deadline - 0.5, maxiter=250)
        else:
            ht = _full_polish(best, deadline - 0.5, maxiter=250)
        r = R_of(ht)
        mx_rel, frac_rel = _pair_stats(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = 'local%d' % round_idx
            print("local round %d R=%.9f NEW BEST maxrel=%.3e frac=%.3e"
                  % (round_idx, bestR, mx_rel, frac_rel))
        else:
            if r > rel_bestR:
                rel_best, rel_bestR = ht.copy(), r
            if round_idx % 2 == 1:
                print("local round %d R=%.9f (best %.9f) maxrel=%.3e frac=%.3e"
                      % (round_idx, r, bestR, mx_rel, frac_rel))

    # Final pair statistics report
    mx_rel, frac_rel = _pair_stats(best)
    print("final pair stats: max_i|h[2i]/h[2i+1]-1|=%.3e frac(>1e-3)=%.3e"
          % (mx_rel, frac_rel))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)"
          % (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if rel_best is not None and rel_best.size == best.size and rel_bestR < bestR - 1e-14:
        result["alternative"] = rel_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, maxcor=10):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16,
                                'maxcor': maxcor})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------------- period detection ----------------
def _detect_period(h, periods=(1, 2, 4, 8, 16, 32, 64, 128), rtol=1e-9):
    n = h.size
    for p in periods:
        if p > 1 and n % p != 0:
            continue
        m = n // p
        if m < 1:
            continue
        blocks = h.reshape(m, p)
        c = blocks.mean(axis=1)
        rec = np.repeat(c, p)
        scale = max(1.0, np.max(np.abs(h)))
        if np.max(np.abs(rec - h)) <= rtol * scale:
            return p, c
    return 1, h.copy()


# ---------------- trust-ncg in quotient ----------------
def _trust_ncg(c0, deadline, maxiter=300, nres=6, rng=None):
    """Run trust-ncg on F(c) with tie-averaged gradient and FD hessp.
    Returns (best_c, best_R, neg_curv_seen, n_iter_total)."""
    if rng is None:
        rng = np.random.default_rng(12345)

    def F(c):
        c = np.clip(c, 0.0, None)
        return _fun_grad_tie(c)

    def hessp(c, v):
        c = np.clip(c, 0.0, None)
        cn = np.linalg.norm(c)
        vn = np.linalg.norm(v)
        if vn <= 0 or cn <= 0:
            return np.zeros_like(c)
        eps = 1e-6 * cn / vn
        _, g1 = F(c + eps * v)
        _, g2 = F(c - eps * v)
        return (g1 - g2) / (2.0 * eps)

    best_c = np.clip(c0.copy(), 0.0, None)
    bestR = R_of(best_c)
    neg_curv = False
    n_iter_total = 0

    def _one_run(c_init):
        nonlocal neg_curv, n_iter_total
        cb = _make_cb(deadline - 0.3)
        try:
            res = minimize(F, c_init, jac=True, method='trust-ncg',
                           hessp=hessp, callback=cb,
                           options={'maxiter': maxiter, 'gtol': 1e-14})
        except (TimeoutError, Exception):
            return None
        if res is None:
            return None
        n_iter_total += int(getattr(res, 'nit', 0) or 0)
        # detect negative curvature: trust-ncg doesn't report directly;
        # check if Hessian at solution has a negative eigenvalue via power it.
        c = np.clip(res.x, 0.0, None)
        try:
            # Lanczos-ish: check smallest eigenvalue sign via a few random probes
            for _ in range(3):
                v = rng.standard_normal(c.size)
                v /= np.linalg.norm(v)
                Hv = hessp(c, v)
                # Rayleigh quotient
                rq = float(v @ Hv)
                if rq < -1e-12:
                    neg_curv = True
                    break
        except Exception:
            pass
        return c

    c = _one_run(best_c)
    if c is not None:
        r = R_of(c)
        if r > bestR:
            best_c, bestR = c.copy(), r

    for k in range(nres):
        if time.process_time() >= deadline - 0.5:
            break
        # smooth random perturbation
        m = best_c.size
        noise = rng.standard_normal(m)
        # smooth via cumulative sum (random walk) then normalize
        noise = np.cumsum(noise)
        noise -= noise.mean()
        nrm = np.max(np.abs(noise))
        if nrm > 0:
            noise /= nrm
        c_init = np.clip(best_c * (1.0 + 1e-3 * noise), 0.0, None)
        c = _one_run(c_init)
        if c is not None:
            r = R_of(c)
            if r > bestR:
                best_c, bestR = c.copy(), r

    return best_c, bestR, neg_curv, n_iter_total


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # ---- (1) period detection ----
    p, c = _detect_period(best)
    Rc = R_of(c)
    Rh = R_of(best)
    print("period p=%d, len(c)=%d, R(c)=%.12f R(h)=%.12f diff=%.2e"
          % (p, c.size, Rc, Rh, abs(Rc - Rh)))

    alt_best = None
    altR = -1.0

    # ---- (2-4) trust-ncg in quotient ----
    t_tr = time.process_time()
    tr_deadline = min(deadline - 6.0, t0 + budget_seconds * 0.80)
    if p > 1:
        c_best, cR, neg_curv, nit = _trust_ncg(c, tr_deadline, maxiter=300, nres=6)
    else:
        # full array, reduced restarts
        c_best, cR, neg_curv, nit = _trust_ncg(c, tr_deadline, maxiter=200, nres=2)
    print("trust-ncg: R=%.12f (was %.12f) dR=%+.2e nit=%d neg_curv=%s t=%.1fs"
          % (cR, Rc, cR - Rc, nit, neg_curv, time.process_time() - t_tr))

    # expand and re-score
    h_tr = _rescale(np.repeat(c_best, p)) if p > 1 else _rescale(c_best)
    r_tr = R_of(h_tr)
    print("expanded R=%.12f dR vs base=%+.2e" % (r_tr, r_tr - bestR))
    if r_tr > bestR + 1e-15:
        best, bestR = h_tr.copy(), r_tr

    # ---- (5) L-BFGS-B with maxcor=50 on c ----
    if time.process_time() < deadline - 3.0:
        c_pol = _lbfgs_block(c_best, np.arange(c_best.size), 300,
                             min(deadline - 2.0, time.process_time() + 5.0),
                             tie=True, maxcor=50)
        r_cp = R_of(c_pol)
        h_cp = _rescale(np.repeat(c_pol, p)) if p > 1 else _rescale(c_pol)
        r_cp_full = R_of(h_cp)
        print("L-BFGS-B(maxcor=50) on c: R(c)=%.12f R(full)=%.12f dR=%+.2e"
              % (r_cp, r_cp_full, r_cp_full - bestR))
        if r_cp_full > bestR + 1e-15:
            best, bestR = h_cp.copy(), r_cp_full
            c_best = c_pol.copy()

    # ---- (6) peak-window tie polish on c ----
    if time.process_time() < deadline - 2.0:
        win_c = _peak_window(c_best, pad_frac=0.05, extra=64)
        c_win = _lbfgs_block(c_best, win_c, 300,
                             min(deadline - 1.0, time.process_time() + 4.0),
                             tie=True, maxcor=50)
        h_win = _rescale(np.repeat(c_win, p)) if p > 1 else _rescale(c_win)
        r_win = R_of(h_win)
        print("peak-window polish on c: R=%.12f dR=%+.2e" % (r_win, r_win - bestR))
        if r_win > bestR + 1e-15:
            best, bestR = h_win.copy(), r_win
            c_best = c_win.copy()

    # ---- safety net: full-array tie polish on best ----
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 3.0),
                           tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR - 1e-15:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    # alternative: the expanded trust-ncg result if it didn't beat start
    if r_tr > startR + 1e-15:
        alt_best = h_tr
        altR = r_tr
    elif p > 1:
        alt_best = _rescale(np.repeat(c_best, p))
        altR = R_of(alt_best)

    print("final R=%.12f (start %.12f, N=%d, ties=%d, p=%d)"
          % (bestR, startR, best.size, _tie_count(best), p))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    return result

