    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 0.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _refine(h, deadline, rounds=8):
    best = h.copy()
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.5, time.process_time() + 4.0))
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        if time.process_time() < deadline - 1.0:
            for beta in (30.0, 100.0, 400.0):
                if time.process_time() >= deadline - 0.6:
                    break
                pb = _lbfgs_block(best, np.arange(best.size), 200,
                                 min(deadline - 0.4, time.process_time() + 3.0),
                                 beta=beta)
                rb = R_of(pb)
                if rb > bestR:
                    best, bestR = pb, rb
        if time.process_time() < deadline - 1.0:
            win = _peak_window(best, tol=0.999, pad_frac=0.5, extra=200)
            pw = _lbfgs_block(best, win, 250,
                             min(deadline - 0.4, time.process_time() + 3.0))
            rw = R_of(pw)
            if rw > bestR:
                best, bestR = pw, rw
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    rng = np.random.RandomState(1234567)

    # First, refine whatever we have at current resolution
    h, r = _refine(best, min(deadline - 4.0, time.process_time() + budget_seconds * 0.25))
    if r > bestR:
        best, bestR = h, r
    print("refine-l0 R=%.7f" % bestR)

    # The key improvement: exact 2x prolongation, then refine at the finer grid.
    # The autoconvolution of a step function is piecewise linear; doubling the
    # resolution strictly enlarges the search space, so this can only help.
    levels = [best]
    cur = best
    for lvl in (2, 4):
        if time.process_time() >= deadline - 15.0:
            break
        H = _rescale(np.repeat(cur, 2))
        rH = R_of(H)
        print("prolong x%d R=%.7f (N=%d)" % (lvl, rH, H.size))
        sub = min(deadline - 8.0, time.process_time() + budget_seconds * 0.30)
        h, r = _refine(H, sub, rounds=10)
        if r > bestR:
            best, bestR = h, r
        cur = h if r > rH else H
        levels.append(cur)
        print("level%d refine R=%.7f (best=%.7f)" % (lvl, r, bestR))

    # Final polish loop at the finest level with continued exploration
    finest = levels[-1]
    rng_state = rng
    round_ = 0
    while time.process_time() < deadline - 1.5:
        round_ += 1
        sub = min(deadline - 1.0, time.process_time() + 5.0)
        # Random perturbation of peak region then refine, to escape local optima
        Lf = _knots(finest)
        m = int(np.argmax(Lf))
        wlen = int(rng_state.randint(64, 384))
        lo = max(0, m - wlen); hi = min(finest.size, m + wlen)
        if hi - lo >= 4:
            x = np.arange(lo, hi, dtype=float)
            c = rng_state.uniform(lo, hi)
            w = max(2.0, (hi - lo) * rng_state.uniform(0.02, 0.06))
            bump = np.exp(-0.5 * ((x - c) / w) ** 2)
            bump = np.convolve(bump, np.ones(9) / 9.0, mode='same')
            amp = rng_state.uniform(0.02, 0.06)
            trial = finest.copy()
            trial[lo:hi] *= np.exp(amp * bump)
            trial = _rescale(trial)
        else:
            trial = finest.copy()
        h, r = _refine(trial, sub, rounds=4)
        if r > bestR + 1e-13:
            best, bestR = h, r
            finest = h
            print("  R%d improved R=%.7f" % (round_, bestR))
        elif r > R_of(finest) + 1e-13:
            finest = h
        print("  R%d R=%.7f (best=%.7f, N=%d)" % (round_, r, bestR, best.size))

    print("final R=%.7f (N=%d, start=%.7f)" % (bestR, best.size, start_bestR))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, logspace=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    if logspace:
        hh0 = np.clip(h, 1e-30, None)
        x0 = np.log(hh0[active])

        def f(x):
            hh = h.copy()
            hh[active] = np.exp(np.clip(x, -60, 60))
            val, g = fg(hh)
            return val, g[active] * hh[active]
    else:
        x0 = h[active].copy()

        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    if logspace:
        h2[active] = np.exp(np.clip(res.x, -60, 60))
    else:
        h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _mass_resample(h, Np, phase):
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    total = C[-1]
    if total <= 0:
        return np.ones(Np)
    xs = (np.arange(Np) + 0.5) * (N / Np) + phase
    xs = np.clip(xs, 0.0, N)
    Cs = np.interp(xs, np.arange(N + 1), C)
    edges = np.concatenate(([0.0], Cs))
    g = np.diff(edges)
    g = np.clip(g, 0, None)
    if g.sum() <= 0:
        return np.ones(Np)
    return g


def _refine_full(h, deadline, time_cap):
    """Full tie polish, then peak-window tie polish; return best."""
    cur = h.copy()
    curR = R_of(cur)
    if time.process_time() >= deadline - 1.0:
        return cur, curR
    g1 = _lbfgs_block(cur, np.arange(cur.size), 300,
                      min(deadline - 0.6, time.process_time() + time_cap),
                      tie=True, logspace=True)
    r1 = R_of(g1)
    if r1 > curR:
        cur, curR = g1, r1
    for pad in (0.10, 0.05, 0.02):
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(cur, pad_frac=pad, extra=96)
        ht = _lbfgs_block(cur, win, 300,
                          min(deadline - 0.4, time.process_time() + time_cap * 0.5),
                          tie=True)
        r = R_of(ht)
        if r > curR + 1e-15:
            cur, curR = ht, r
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N0 = best.size
    print("base R=%.9f (N=%d)" % (bestR, N0))

    # Phase-shifted resamples at higher resolution. The key idea: a finer grid
    # (more steps) can represent the optimal blow-up shape with finer detail,
    # and multiple phases let us pick the best discretization.
    configs = [
        (262147, 0.37), (262147, 0.13), (262147, 0.71),
        (131071, 0.37), (131071, 0.13), (131071, 0.71),
        (104993, 0.37), (104993, 0.13),
    ]

    candidates = []
    for (Np, phase) in configs:
        if time.process_time() >= deadline - 8.0:
            break
        g = _mass_resample(best, Np, phase)
        g = _rescale(g)
        r0 = R_of(g)
        print("phase Np=%d ph=%.2f R0=%.9f" % (Np, phase, r0))

        g1 = _lbfgs_block(g, np.arange(Np), 300,
                          min(deadline - 5.0, time.process_time() + 6.0),
                          tie=True, logspace=True)
        r1 = R_of(g1)
        print("  after lbfgs R=%.9f" % r1)

        cur, curR = g1, r1
        for pad in (0.10, 0.05, 0.02):
            if time.process_time() >= deadline - 4.0:
                break
            win = _peak_window(cur, pad_frac=pad, extra=96)
            ht = _lbfgs_block(cur, win, 300,
                              min(deadline - 3.0, time.process_time() + 2.5),
                              tie=True)
            r = R_of(ht)
            if r > curR + 1e-15:
                cur, curR = ht, r
        for beta in (1e6, 1e8):
            if time.process_time() >= deadline - 3.0:
                break
            win = _peak_window(cur, pad_frac=0.05, extra=96)
            ht = _lbfgs_block(cur, win, 300,
                              min(deadline - 2.0, time.process_time() + 2.0),
                              beta=beta)
            r = R_of(ht)
            if r > curR + 1e-15:
                cur, curR = ht, r
        print("  final cand R=%.9f (Np=%d)" % (curR, Np))
        candidates.append((curR, cur, Np))

    # Pick best candidate. If it's at a different resolution, polish in place
    # (do not resample back to N0 — keep the finer grid, whose higher R stands).
    if candidates:
        candidates.sort(key=lambda x: -x[0])
        bestCandR, bestCand, bestNp = candidates[0]
        print("best candidate R=%.9f Np=%d" % (bestCandR, bestNp))
        finalCand = bestCand.copy()
        finalCandR = bestCandR

        # Extra refinement rounds on the winning candidate using remaining budget.
        while time.process_time() < deadline - 1.0:
            nc, nr = _refine_full(finalCand, deadline, 3.0)
            if nr > finalCandR + 1e-15:
                finalCand, finalCandR = nc, nr
                print("  refine up R=%.9f" % finalCandR)
            else:
                break

        if finalCandR > bestR + 1e-15:
            best, bestR = finalCand.copy(), finalCandR
            print("ACCEPT new best R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

