    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xi = np.linspace(0, n - 1, m)
    return np.interp(xi, np.arange(n), h)


def _jitter_full(h, rng, nblocks_lo=2, nblocks_hi=4, sigma=0.02, Lmax=65):
    n = h.size
    h2 = h.copy()
    nb = int(rng.integers(nblocks_lo, nblocks_hi))
    for _ in range(nb):
        L = int(rng.integers(2, Lmax))
        if L >= n:
            L = n
        st = int(rng.integers(0, n - L + 1))
        h2[st:st + L] *= np.exp(rng.normal(0.0, sigma, size=L))
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- (A) full-array tie polish, short ----
    a_end = min(deadline, time.process_time() + 6.0)
    hA = _lbfgs_block(best, np.arange(best.size), 400, a_end, tie=True)
    rA = R_of(hA)
    if rA > bestR + 1e-15:
        best, bestR = hA.copy(), rA
    print("PhaseA R=%.9f" % bestR)

    # ---- (B) peak-window polish at several scales ----
    c_end = min(deadline, time.process_time() + 8.0)
    for frac in (0.1, 0.05, 0.02, 0.01):
        if time.process_time() >= c_end - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=128)
        hp = _lbfgs_block(best, win, 400,
                          min(c_end, time.process_time() + 2.0), tie=True)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
    print("PhaseC R=%.9f" % bestR)

    # ---- (D) upsample to add resolution, re-polish ----
    d_end = min(deadline - 12.0, time.process_time() + 10.0)
    if best.size < 400000 and time.process_time() < d_end - 2.0:
        fac = 2
        hu = _rescale(_upsample(best, fac))
        hu = _lbfgs_block(hu, np.arange(hu.size), 300,
                          min(d_end, time.process_time() + 6.0), tie=True)
        ru = R_of(hu)
        if ru > bestR + 1e-15:
            best, bestR = hu.copy(), ru
            print("Upsample ACCEPT R=%.9f (N=%d)" % (bestR, best.size))
        else:
            print("Upsample no gain (%.9f vs %.9f)" % (ru, bestR))

    # ---- (E) long jitter rounds with peak-window re-polish ----
    rng = np.random.default_rng(int(20240607 + t0 * 1000) & 0x7fffffff)
    rounds = 0
    accepted = 0
    e_end = deadline
    while time.process_time() < e_end - 1.0:
        rounds += 1
        sigma = 0.03 if rounds < 4 else (0.01 if rounds < 10 else 0.004)
        hj = _jitter_full(best, rng, 2, 4, sigma, 65)
        win = _peak_window(hj, pad_frac=0.06, extra=128)
        hj = _lbfgs_block(hj, win, 200,
                          min(e_end - 0.5,
                              time.process_time() + 2.5), tie=True)
        rj = R_of(hj)
        if rj > bestR + 1e-15:
            best, bestR = hj.copy(), rj
            accepted += 1
            print("jitter round=%d ACCEPT R=%.9f" % (rounds, bestR))
    print("PhaseD rounds=%d accepted=%d R=%.9f" % (rounds, accepted, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

