        r0 = R_of(seed)
        cand, rc = _polish(seed, r0, deadline - 1.5, rounds=1)
        if rc > bestR + 1e-13:
            best, bestR = cand, rc
            print("  resample N=%d -> R=%.7f NEW BEST" % (best.size, bestR))
        else:
