        if not improved and best.size < 400000 and time.process_time() < deadline - 4.0:
            for fac in (1.25, 1.5, 2.0):
                if time.process_time() >= deadline - 4.0:
                    break
                hu = _densify(_resample_smooth(best, int(best.size * fac)))
                hu, ru = _polish(hu, R_of(hu), deadline - 2.0, rounds=1)
                if ru > bestR + 1e-13:
                    best, bestR = hu, ru
                    print("iter %d upsample x%.2f R=%.7f N=%d" %
                          (it, fac, bestR, best.size))
                    improved = True
                    break
        if not improved and it > 3:
            # Small random perturbation to escape local minima.
            if time.process_time() < deadline - 3.0:
                rng = np.random.default_rng(int(time.process_time() * 1e6) % (2**32))
                hp = best.copy()
                pos = np.flatnonzero(hp > 0)
                if pos.size > 0:
                    k = max(1, pos.size // 50)
                    sel = rng.choice(pos, size=min(k, pos.size), replace=False)
                    hp[sel] *= (1.0 + 0.05 * rng.standard_normal(sel.size))
