        c = int(np.argmax(Lf))
    else:
        c = (int(idx.min()) + int(idx.max())) // 2
    half = max(16, int(frac * n))
    lo = max(0, c - half)
    hi = min(n, c + half)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 2.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # New main idea: exploit the flat-top (tie) structure of the optimum.
    # The true optimum has many knots at the max; drive them all up with a tie gradient.
    cur = best.copy()
    curR = bestR

    # Stage 1: soft-max continuation to build up a flat top.
    betas = [3.0, 10.0, 30.0, 100.0, 300.0, 1000.0, 3000.0]
    for beta in betas:
        if time.process_time() >= hard - 8.0:
            break
        cap = min(hard - 7.0, time.process_time() + 3.0)
        hb = _lbfgs_log(cur, 250, cap, beta=beta)
        rb = R_of(hb)
        if rb > curR - 1e-10:
            cur, curR = hb, rb
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
            print("  beta=%.0f: R=%.9f" % (beta, bestR))

    # Stage 2: tie-gradient polish on full vector, growing the flat top.
    for _ in range(6):
        if time.process_time() >= hard - 2.0:
            break
        cap = min(hard - 1.5, time.process_time() + 2.5)
        ht = _lbfgs_log(best, 300, cap, fg=_fun_grad_tie)
        rt = R_of(ht)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            print("  tie: R=%.9f" % bestR)
        else:
            break

    # Stage 3: block polish on windows around the flat top, multiple scales.
    for frac in (0.02, 0.05, 0.10, 0.20, 0.40):
        if time.process_time() >= hard - 1.0:
            break
        free = _band_window(best, frac)
        cap = min(hard - 0.5, time.process_time() + 2.0)
        hb = _lbfgs_block(best, free, 200, cap, tie=True)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
            print("  band frac=%.2f: R=%.9f" % (frac, bestR))

    # Final hard-max pass.
    if time.process_time() < hard - 0.5:
        cap = min(hard - 0.3, time.process_time() + 1.5)
        hp = _lbfgs_log(best, 300, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
            print("  hard: R=%.9f" % bestR)

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _flank_runs(Lf, lo_frac=0.02, hi_frac=0.98, cap=4096):
    M = Lf.max()
    if M <= 0:
        return []
    mask = (Lf > lo_frac * M) & (Lf < hi_frac * M)
    n = mask.size
    runs = []
    i = 0
    while i < n:
        if mask[i]:
            j = i
            while j < n and mask[j]:
                j += 1
            runs.append((i, j - 1))
            i = j
        else:
            i += 1
    out = []
    for (a, b) in runs:
        if b - a + 1 > cap:
            mid = (a + b) // 2
            a = max(a, mid - cap // 2)
            b = min(b, a + cap - 1)
        out.append((a, b))
    return out


def _free_set(h, include_flanks=True):
    n = h.size
    Lf = _knots(h)
    free = set()
    if include_flanks:
        for (a, b) in _flank_runs(Lf):
            lo = max(0, a - 32)
            hi = min(n - 1, b + 32)
            free.update(range(lo, hi + 1))
    win = _peak_window(h)
    free.update(win.tolist())
    return np.array(sorted(free), dtype=int)


def _refine(h, deadline, rounds=8):
    best = h.copy()
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        # full tie polish (short time slice)
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.5, time.process_time() + 4.0))
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        # beta-smoothed passes to escape tie degeneracies
        for beta in (1e8, 1e7, 1e6, 0.0):
            if time.process_time() >= deadline - 0.6:
                break
            if beta > 0:
                free = _free_set(best)
            else:
                free = np.arange(best.size)
            pb = _lbfgs_block(best, free, 200,
                              min(deadline - 0.4, time.process_time() + 3.0),
                              beta=beta)
            rb = R_of(pb)
            if rb > bestR:
                best, bestR = pb, rb
        # peak-window polish at tight tolerance
        if time.process_time() < deadline - 0.6:
            win = _peak_window(best, tol=0.9999, pad_frac=0.5)
            pw = _lbfgs_block(best, win, 250,
                              min(deadline - 0.4, time.process_time() + 3.0),
                              beta=1e7)
            rw = R_of(pw)
            if rw > bestR:
                best, bestR = pw, rw
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.5
    hard = t0 + budget_seconds * 0.96

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_R = R_of(best_h)

    if best_h is None:
        Nbase = 4096
        x = np.linspace(0.0, 1.0, Nbase)
        cur = np.exp(-((x - 0.5) ** 2) / 0.02)
        cur /= cur.sum()
        best_h = cur.copy()
        best_R = R_of(cur)

    # Attempt a doubled grid from the start (more resolution can help)
    if best_h.size * 2 <= 1000000 and time.process_time() < hard - 25.0:
        h2 = np.repeat(best_h, 2)
        h2 = _lbfgs_block(h2, np.arange(h2.size), 250,
                          min(hard - 15.0, time.process_time() + 8.0), beta=1e7)
        R2 = R_of(h2)
        if R2 > best_R:
            best_h, best_R = h2, R2
            print("doubled R =", R2, "N =", len(h2))

    # Main refine loop: alternate full, beta-ladder, and peak/free windows
    best_h, best_R = _refine(best_h, hard)
    print("refine R =", best_R, "N =", len(best_h))

    # If time remains, one more doubling pass then refine again
    while time.process_time() < hard - 8.0 and best_h.size * 2 <= 1000000:
        h2 = np.repeat(best_h, 2)
        h2 = _lbfgs_block(h2, np.arange(h2.size), 250,
                          min(hard - 6.0, time.process_time() + 6.0), beta=1e7)
        R2 = R_of(h2)
        if R2 > best_R:
            best_h, best_R = h2, R2
            print("doubled R =", R2, "N =", len(h2))
            best_h, best_R = _refine(best_h, hard)
        else:
            break

    # Final quick polish
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_block(best_h, np.arange(best_h.size), 200, deadline - 0.3)
        Rf = R_of(hf)
        if Rf > best_R:
            best_R = Rf
            best_h = hf

    print("best R =", best_R, "N =", len(best_h))
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = max(1, int(np.ceil(q * n)))
    k = min(k, n)
    idx = np.argpartition(Lf, n - k)[n - k:]
    cvar = float(Lf[idx].mean())
    if cvar <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    gLf[idx] += 1.0 / (idx.size * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _fun_grad_pnorm(h, p):
    # soft-max via p-norm of the top band: ||L||_p ~ max. Larger p -> closer to max.
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None)
    # shift by max for stability
    mx = Lp.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    r = Lp / mx
    rp = r ** p
    Sp = rp.sum()
    if Sp <= 0:
        return _fun_grad_tie(h)
    # ||L||_p = mx * Sp^(1/p)
    logp = np.log(mx) + np.log(Sp) / p
    # d logp / dL_j = (1/mx) * d mx/dL_j + (1/p) * (p r^{p-1} / Sp) * (1/mx) dL/dL
    #               = delta_max/mx + r^{p-1}/Sp * (1/mx)  (for unshifted)
    # Actually with shift, d mx/dL = e_max, and d r_j / dL = (delta_ij - r_j e_max)/mx
    # d logp = e_max/mx + (1/(p Sp)) * sum_j p r_j^{p-1} * (delta_ij - r_j e_max)/mx
    #        = e_max/mx + (1/(Sp mx)) * (r_i^{p-1} - r_i^p e_max_sum... )
    e_max = np.zeros_like(Lf)
    e_max[int(np.argmax(Lp))] = 1.0
    rp1 = r ** (p - 1)
    # sum_j rp1_j (delta_ij - r_j e_max_j) = rp1_i - (sum_j rp1_j r_j) e_max_i
    S2 = np.sum(rp1 * r)
    dlogp = e_max / mx + (rp1 - S2 * e_max) / (Sp * mx)
    gLf = -dq / num + dlogp
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logp
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, cvar=0.0, pnorm=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if cvar > 0:
        fg = (lambda hh: _fun_grad_cvar(hh, cvar))
    elif pnorm > 0:
        fg = (lambda hh: _fun_grad_pnorm(hh, pnorm))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    alt_best, altR = None, -1.0
    print("base R=%.9f (N=%d) frac5=%.4f"
          % (bestR, best.size, _frac_near_max(best, 5e-2)))

    def consider(hc, tag):
        nonlocal best, bestR, alt_best, altR
        rc = R_of(hc)
        if rc > altR:
            altR = rc; alt_best = hc.copy()
        if rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc
            print("  %s R=%.12f frac5=%.4f *" % (tag, rc, _frac_near_max(hc, 5e-2)))
        return rc

    # ---- Phase A: p-norm continuation (sharpening the max) ----
    for p in (4.0, 8.0, 16.0, 32.0):
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 4.0)
        hp = _lbfgs_block(best, np.arange(best.size), 300, tlim, pnorm=p)
        consider(hp, "pnorm p=%.0f" % p)

    # ---- Phase B: CVaR ladder, warm-started from current best ----
    for q in (0.10, 0.05, 0.03, 0.02, 0.01):
        if time.process_time() >= deadline - 1.5:
            break
        tlim = min(deadline - 1.0, time.process_time() + 5.0)
        hc = _lbfgs_block(best, np.arange(best.size), 300, tlim, cvar=q)
        consider(hc, "cvar q=%.2f" % q)

        # tie polish on full vector
        if time.process_time() < deadline - 1.5:
            pol = _lbfgs_block(hc, np.arange(hc.size), 200,
                               min(deadline - 1.0, time.process_time() + 3.0),
                               tie=True)
            consider(pol, "  tie on cvar q=%.2f" % q)

        # peak-window polishes
        for pad in (0.10, 0.05):
            if time.process_time() >= deadline - 1.5:
                break
            win = _peak_window(hc, pad_frac=pad, extra=128)
            ht = _lbfgs_block(hc, win, 250,
                              min(deadline - 1.0, time.process_time() + 2.0),
                              tie=True)
            consider(ht, "  win pad=%.2f" % pad)

    # ---- Phase C: final global tie polish on best, then pnorm re-sharpen ----
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 400,
                           min(deadline - 0.5, time.process_time() + 6.0), tie=True)
        consider(pol, "final tie")
    if time.process_time() < deadline - 0.5:
        hp = _lbfgs_block(best, np.arange(best.size), 200,
                          min(deadline - 0.3, time.process_time() + 3.0), pnorm=24.0)
        consider(hp, "final pnorm")

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and R_of(alt_best) > startR + 1e-12:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _R_fft(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -1.0
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    L2 = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    Linf = L.max()
    if Linf <= 0:
        return -1.0
    return L2 / (s * s * Linf)


def _prolongate(h, N_new):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N == N_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0, 1, N + 1)
    x_new = np.linspace(0, 1, N_new + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.maximum(h_new, 0.0)


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_deficit(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    # deficit penalty over knots above tau*max
    thr = tau * mx
    sel = np.flatnonzero(Lf >= thr)
    pen = 0.0
    if sel.size > 0:
        d = (mx - Lf[sel]) / mx
        pen = kappa * np.mean(d * d)
        # d/dh of penalty: d depends on Lf and mx (mx = max over all knots)
        # treat mx as constant w.r.t. the selected knots' own L (soft); include
        # derivative through Lf[sel] only, ignoring mx dependence (small).
        gpen = np.zeros_like(Lf)
        # d(mean d^2)/dL_j = 2*d*(-1/mx)/n  for j in sel
        gpen[sel] = (2.0 * d * (-1.0 / mx)) / sel.size
        gLf += kappa * gpen
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, beta=0.0, deficit=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if deficit is not None:
        tau, kappa = deficit
        fg = (lambda hh: _fun_grad_deficit(hh, tau, kappa))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.15):
    L = _knots(h)
    mx = L.max()
    idx = np.flatnonzero(L >= (1.0 - frac) * mx)
    if idx.size == 0:
        return np.arange(len(h))
    lo = max(0, idx.min() - 2)
    hi = min(len(h), idx.max() + 2)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best_h = np.maximum(s, 0.0).copy()
            best_R = _R_fft(best_h)

    base = best_h if best_h is not None else np.ones(64)

    ladder = [(0.99, 1e3), (0.97, 1e3), (0.95, 3e3), (0.90, 1e4)]

    work = base.copy()
    for N_target in [32768, 65536]:
        if time.process_time() > deadline - 1.0:
            break
        work = _prolongate(work, N_target)
        for (tau, kappa) in ladder:
            if time.process_time() > deadline - 0.5:
                break
            free = np.arange(len(work))
            work = _lbfgs(work, free, maxiter=1500, deadline=deadline,
                          deficit=(tau, kappa))
            # exact tie polish
            work = _lbfgs(work, free, maxiter=800, deadline=deadline, beta=0.0)
            # peak-window tie polish
            pw = _peak_window(work, 0.15)
            work = _lbfgs(work, pw, maxiter=600, deadline=deadline, beta=0.0)
            Rw = _R_fft(work)
            if Rw > best_R:
                best_R = Rw
                best_h = work.copy()
                print(f"deficit N={len(work)} tau={tau} kappa={kappa} R={Rw:.6f}")

    # spend leftover time refining best at its own resolution
    if best_h is not None:
        while time.process_time() < deadline - 0.5:
            free = np.arange(len(best_h))
            h2 = _lbfgs(best_h, free, maxiter=1000, deadline=deadline, beta=0.0)
            pw = _peak_window(h2, 0.15)
            h2 = _lbfgs(h2, pw, maxiter=600, deadline=deadline, beta=0.0)
            R2 = _R_fft(h2)
            if R2 > best_R + 1e-9:
                best_R = R2
                best_h = h2.copy()
                print(f"refine R={R2:.6f}")
            else:
                break

    if best_h is None:
        best_h = np.ones(50)

    print(f"final R={_R_fft(best_h):.6f} N={len(best_h)}")
    return {"best": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _collapse_to_c(h, q):
    N = h.size
    nb = (N + q - 1) // q
    c = np.zeros(nb)
    for j in range(nb):
        seg = h[j * q:(j + 1) * q]
        if seg.size > 0:
            c[j] = seg.mean()
    return c


def _expand_from_c(c, q, N):
    h = np.repeat(c, q)[:N]
    if h.size < N:
        h = np.concatenate([h, np.full(N - h.size, c[-1] if c.size else 0.0)])
    return h


def _lbfgs_c(h0, q, maxiter, deadline):
    """Tie-averaged L-BFGS on block-constant c, gradient summed over blocks."""
    if time.process_time() >= deadline - 0.3:
        return h0
    N = h0.size
    c = _collapse_to_c(np.clip(h0, 0, None), q)
    nb = c.size
    if nb == 0:
        return h0

    def expand(cv):
        return _expand_from_c(np.clip(cv, 0, None), q, N)

    def f(cv):
        hh = expand(cv)
        val, g = _fun_grad_tie(hh)
        gc = np.zeros(nb)
        for j in range(nb):
            lo = j * q
            hi = min(N, (j + 1) * q)
            if hi > lo:
                gc[j] = g[lo:hi].sum()
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(expand(res.x))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Period sweep experiment ----
    q_list = [24, 28, 29, 30, 31, 32, 33, 34, 36, 40]
    results = {}
    alt_best = None
    altR = -1.0
    N = best.size

    # distribute time: each q gets a slice of the budget
    per_q = max(0.5, (budget_seconds * 0.80) / len(q_list))

    for q in q_list:
        if time.process_time() >= deadline - 1.0:
            break
        tq_end = min(deadline - 0.5, time.process_time() + per_q)
        # collapse to c
        c = _collapse_to_c(best, q)
        hq = _rescale(_expand_from_c(c, q, N))
        r0 = R_of(hq)
        # block-constant L-BFGS
        hq2 = _lbfgs_c(hq, q, 200, tq_end)
        r1 = R_of(hq2)
        # full-array tie polish
        if time.process_time() < tq_end - 0.2:
            hq3 = _lbfgs_block(hq2, np.arange(N), 80, tq_end, tie=True)
            r2 = R_of(hq3)
        else:
            hq3, r2 = hq2, r1
        results[q] = (r0, r1, r2)
        print("q=%d: r0=%.9f r1=%.9f r2=%.9f" % (q, r0, r1, r2))
        if r2 > altR:
            altR = r2
            alt_best = hq3.copy()
        if r2 > bestR + 1e-15:
            best, bestR = hq3.copy(), r2

    # report control vs best non-32
    ctrl = results.get(32, (0, 0, 0))[2]
    non32 = [(q, r[2]) for q, r in results.items() if q != 32]
    if non32:
        bq, br = max(non32, key=lambda t: t[1])
        print("control q=32: %.9f | best non-32 q=%d: %.9f | delta=%.2e"
              % (ctrl, bq, br, br - ctrl))

    # final safety: full tie polish on best
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 100,
                           min(deadline - 0.3, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

