    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _collapse_to_c(h, q):
    N = h.size
    nb = (N + q - 1) // q
    c = np.zeros(nb)
    for j in range(nb):
        seg = h[j * q:(j + 1) * q]
        if seg.size > 0:
            c[j] = seg.mean()
    return c


def _expand_from_c(c, q, N):
    h = np.repeat(c, q)[:N]
    if h.size < N:
        h = np.concatenate([h, np.full(N - h.size, c[-1] if c.size else 0.0)])
    return h


def _lbfgs_c(h0, q, maxiter, deadline):
    """Tie-averaged L-BFGS on block-constant c, gradient summed over blocks."""
    if time.process_time() >= deadline - 0.3:
        return h0
    N = h0.size
    c = _collapse_to_c(np.clip(h0, 0, None), q)
    nb = c.size
    if nb == 0:
        return h0

    def expand(cv):
        return _expand_from_c(np.clip(cv, 0, None), q, N)

    def f(cv):
        hh = expand(cv)
        val, g = _fun_grad_tie(hh)
        gc = np.zeros(nb)
        for j in range(nb):
            lo = j * q
            hi = min(N, (j + 1) * q)
            if hi > lo:
                gc[j] = g[lo:hi].sum()
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(expand(res.x))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Period sweep experiment ----
    q_list = [24, 28, 29, 30, 31, 32, 33, 34, 36, 40]
    results = {}
    alt_best = None
    altR = -1.0
    N = best.size

    # distribute time: each q gets a slice of the budget
    per_q = max(0.5, (budget_seconds * 0.80) / len(q_list))

    for q in q_list:
        if time.process_time() >= deadline - 1.0:
            break
        tq_end = min(deadline - 0.5, time.process_time() + per_q)
        # collapse to c
        c = _collapse_to_c(best, q)
        hq = _rescale(_expand_from_c(c, q, N))
        r0 = R_of(hq)
        # block-constant L-BFGS
        hq2 = _lbfgs_c(hq, q, 200, tq_end)
        r1 = R_of(hq2)
        # full-array tie polish
        if time.process_time() < tq_end - 0.2:
            hq3 = _lbfgs_block(hq2, np.arange(N), 80, tq_end, tie=True)
            r2 = R_of(hq3)
        else:
            hq3, r2 = hq2, r1
        results[q] = (r0, r1, r2)
        print("q=%d: r0=%.9f r1=%.9f r2=%.9f" % (q, r0, r1, r2))
        if r2 > altR:
            altR = r2
            alt_best = hq3.copy()
        if r2 > bestR + 1e-15:
            best, bestR = hq3.copy(), r2

    # report control vs best non-32
    ctrl = results.get(32, (0, 0, 0))[2]
    non32 = [(q, r[2]) for q, r in results.items() if q != 32]
    if non32:
        bq, br = max(non32, key=lambda t: t[1])
        print("control q=32: %.9f | best non-32 q=%d: %.9f | delta=%.2e"
              % (ctrl, bq, br, br - ctrl))

    # final safety: full tie polish on best
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 100,
                           min(deadline - 0.3, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _peak_pos(h):
    Lf = _knots(h)
    return int(np.argmax(Lf)) / max(1, h.size)


def _prolongate(h, factor):
    """Mass-preserving linear prolongation to ~factor*N."""
    n = h.size
    n2 = int(round(n * factor))
    if n2 <= n:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(n2) + 0.5) / n2
    out = np.interp(x_new, x_old, h, left=0.0, right=0.0)
    s_old = h.sum()
    s_new = out.sum()
    if s_new > 0:
        out *= s_old / s_new
    return np.clip(out, 0, None)


def _beta_ladder(h, betas, per_beta_time, deadline, maxiter=400):
    """Run beta-homotopy, each beta up to per_beta_time seconds."""
    best = h.copy()
    bestR = R_of(h)
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        slice_deadline = min(deadline - 0.3,
                             time.process_time() + per_beta_time)
        ht = _lbfgs_all_pos(best, maxiter, slice_deadline, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
    return best, bestR


def _tie_polish(h, deadline, pads=(0.30, 0.15, 0.10, 0.06)):
    best = h.copy()
    bestR = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2, r2
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d) peak_pos=%.4f" %
          (bestR, best.size, _peak_pos(best)))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: beta-homotopy on full array ----
    # betas 1e4..1e8, each up to ~6s (scaled by budget)
    per_beta = min(6.0, 0.10 * budget_seconds)
    betas = [1e4, 1e5, 1e6, 1e7, 1e8]
    phase1_deadline = min(deadline - 0.5, t0 + 0.45 * budget_seconds)
    ht, rt = _beta_ladder(best, betas, per_beta, phase1_deadline)
    print("beta-ladder R=%.9f (gain %.2e)" % (rt, rt - bestR))
    if rt > bestR + 1e-14:
        best, bestR, origin = ht, rt, 'beta-ladder'
    elif rt > alt_bestR:
        alt_best, alt_bestR = ht, rt

    # exact tie L-BFGS + peak-window polish
    if time.process_time() < deadline - 2.0:
        tie_deadline = min(deadline - 1.0, t0 + 0.60 * budget_seconds)
        ht2, rt2 = _tie_polish(best, tie_deadline)
        print("tie-polish R=%.9f (gain %.2e)" % (rt2, rt2 - bestR))
        if rt2 > bestR + 1e-14:
            best, bestR, origin = ht2, rt2, origin + '+tie'
        elif rt2 > alt_bestR:
            alt_best, alt_bestR = ht2, rt2

    # ---- Phase 2: prolongate to ~1.25x, high-beta pass + tie polish ----
    if time.process_time() < deadline - 4.0:
        h_pro = _rescale(_prolongate(best, 1.25))
        r_pro = R_of(h_pro)
        print("prolongate N=%d R=%.9f" % (h_pro.size, r_pro))
        pro_deadline = min(deadline - 2.0, t0 + 0.85 * budget_seconds)
        # one high-beta pass
        ht = h_pro
        for beta in [1e7, 1e8]:
            if time.process_time() >= pro_deadline - 0.5:
                break
            sd = min(pro_deadline - 0.3,
                     time.process_time() + 0.06 * budget_seconds)
            ht = _lbfgs_all_pos(ht, 400, sd, beta=beta)
        r = R_of(ht)
        # tie polish
        if time.process_time() < pro_deadline - 0.5:
            ht, r = _tie_polish(ht, pro_deadline)
        print("prolongate-polish R=%.9f (gain %.2e)" % (r, r - bestR))
        if r > bestR + 1e-14:
            best, bestR, origin = ht, r, 'prolongate'
        elif r > alt_bestR:
            alt_best, alt_bestR = ht, r

    # ---- Phase 3: extra beta-homotopy on best (if time remains) ----
    if time.process_time() < deadline - 3.0:
        extra_deadline = deadline - 1.0
        ht, rt = _beta_ladder(best, [1e6, 1e7, 1e8], 0.05 * budget_seconds,
                              extra_deadline)
        if rt > bestR + 1e-14:
            best, bestR, origin = ht, rt, origin + '+beta2'
            print("extra beta R=%.9f" % bestR)
        elif rt > alt_bestR:
            alt_best, alt_bestR = ht, rt
        if time.process_time() < extra_deadline - 0.5:
            ht2, rt2 = _tie_polish(best, extra_deadline)
            if rt2 > bestR + 1e-14:
                best, bestR, origin = ht2, rt2, origin + '+tie2'
                print("extra tie R=%.9f" % bestR)
            elif rt2 > alt_bestR:
                alt_best, alt_bestR = ht2, rt2

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f, "
          "peak_pos=%.4f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best),
           _peak_pos(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

