        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter, beta):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _smooth_kernel(h, sigma):
    if sigma <= 0:
        return h
    r = int(max(1, np.ceil(3 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.clip(np.convolve(h, k, mode='same'), 0.0, None)


def _envelope(n, rng, amp):
    if amp <= 0:
        return np.ones(n)
    idx = np.arange(n, dtype=float)
    env = np.ones(n)
    for k in range(1, 6):
        a = rng.standard_normal()
        env += amp * a * np.cos(np.pi * k * idx / n)
    return np.clip(env, 0.0, None)


def _interp_resample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xo = np.linspace(0.0, 1.0, n)
    xn = np.linspace(0.0, 1.0, N)
    return np.clip(np.interp(xn, xo, h), 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # (A) sharp full L-BFGS on start
    stageA_deadline = min(deadline - 2.0, t0 + 8.0)
    if time.process_time() < stageA_deadline - 0.5:
        h = _lbfgs_log(best, 400, stageA_deadline, 0.0)
        r = R_of(h)
        if r > bestR + 1e-12:
            best, bestR = h, r
            print("A sharp R=%.7f" % bestR)
        for frac in (0.20, 0.10):
            if time.process_time() >= stageA_deadline - 0.3:
                break
            hp = _window_polish_peak(best, stageA_deadline, frac, 32, 200, 0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("A peak frac=%.2f R=%.7f" % (frac, bestR))

    # (B) multi-resolution: resample to different N and re-optimise, keep best
    # This changes the discretisation, letting the optimiser escape local optima.
    resolutions = [best.size, int(best.size * 0.75), int(best.size * 1.25),
                   int(best.size * 0.5), int(best.size * 1.5)]
    resolutions = [r for r in resolutions if 16 <= r <= 1000000]
    rejected = []
    trial = 0
    accepted = 0
    res_idx = 0

    while time.process_time() < deadline - 3.0:
        trial += 1
        now = time.process_time()
        trial_deadline = min(now + 4.0, deadline - 2.0)
        if trial_deadline <= now + 0.2:
            break

        # pick a candidate seed
        if trial % 5 == 0 and rejected:
            _, _, hseed = heapq.nlargest(1, rejected)[0]
        else:
            hseed = best

        # resample to a new resolution
        N = resolutions[res_idx % len(resolutions)]
        res_idx += 1
        hp = _interp_resample(hseed, N)
        if hp.sum() <= 0:
            continue
        hp = _rescale(hp)

        # small smoothing to perturb
        sigma = [1, 2, 3][trial % 3]
        hp = _smooth_kernel(hp, sigma)
        env = _envelope(N, rng, 0.03)
        hp = _rescale(np.clip(hp * env, 0.0, None))

        ht = _lbfgs_log(hp, 250, trial_deadline, 0.0)
        for beta in (1e5, 1e7):
            if time.process_time() >= trial_deadline - 0.3:
                break
            ht = _lbfgs_log(ht, 80, trial_deadline, beta)
        if time.process_time() < trial_deadline - 0.3:
            ht = _window_polish_peak(ht, trial_deadline, 0.05, 32, 100, 0.0)

        rt = R_of(ht)
        acc = rt > bestR + 1e-12
        if acc:
            best, bestR = ht, rt
            accepted += 1
            print("trial %d N=%d sig=%d R=%.7f ACCEPT" % (trial, N, sigma, rt))
        else:
            heapq.heappush(rejected, (rt, trial, ht))
            if len(rejected) > 4:
                heapq.heappop(rejected)
            print("trial %d N=%d sig=%d R=%.7f (best %.7f)" %
                  (trial, N, sigma, rt, bestR))

    # final peak-window tie polish
    for frac in (0.05, 0.02, 0.01):
        if time.process_time() >= deadline - 0.5:
            break
        hp = _window_polish_peak(best, deadline, frac, 32, 200, 0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            best, bestR = hp, rp
            print("final peak frac=%.2f R=%.7f" % (frac, bestR))

    print("final R=%.7f (N=%d, zeros %.1f%%, accepted %d/%d)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), accepted, trial))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _refine(h, deadline, rounds=6):
    best = h.copy()
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.5, time.process_time() + 5.0))
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        if time.process_time() < deadline - 1.0:
            for beta in (50.0, 200.0):
                if time.process_time() >= deadline - 0.6:
                    break
                pb = _lbfgs_block(best, np.arange(best.size), 200,
                                 min(deadline - 0.4, time.process_time() + 4.0),
                                 beta=beta)
                rb = R_of(pb)
                if rb > bestR:
                    best, bestR = pb, rb
        free = _peak_window(best)
        pw = _lbfgs_block(best, free, 300,
                          min(deadline - 0.3, time.process_time() + 4.0))
        rw = R_of(pw)
        if rw > bestR:
            best, bestR = pw, rw
    return best, bestR


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    if start_arr is not None:
        print("start R=%.6f N=%d" % (start_r, start_arr.size))
        # Try refining at several downsampled sizes (cheaper -> deeper iterations),
        # and at the original size. Different N changes the discretisation basin.
        n0 = start_arr.size
        cands = [(start_r, start_arr.copy())]
        for tgt in (n0 // 4, n0 // 2, n0, min(n0 * 2, 1000000)):
            if time.process_time() >= deadline - 5.0:
                break
            if tgt < 16:
                continue
            c = _rescale(_prolong(start_arr, tgt))
            rc = R_of(c)
            c, rc = _refine(c, min(deadline - 2.0, time.process_time() + 10.0),
                            rounds=4)
            print("  N=%d R=%.6f" % (tgt, rc))
            cands.append((rc, c))

        for r, c in cands:
            if r > best_r:
                best, best_r = c, r

        # final long refine on best at full precision
        if best_r + 1e-9 < start_r or best is None:
            best, best_r = start_arr.copy(), start_r
        best, best_r = _refine(best, deadline, rounds=1000)
        if best_r < start_r:
            best, best_r = start_arr.copy(), start_r
        print("refined R=%.6f (start %.6f)" % (best_r, start_r))

    if best is None:
        N0 = 256
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best, best_r = _refine(best, deadline, rounds=1000)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    best = _rescale(best)
    if start_arr is not None:
        if start_r >= best_r:
            alt = best if not np.array_equal(best, start_arr) else None
            if alt is not None:
                return {"best": _rescale(start_arr), "alternative": alt}
            return _rescale(start_arr)
        return {"best": best, "alternative": _rescale(start_arr)}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


# ---- Flat-top target: push many knots up to the max simultaneously ----
def _fun_grad_flat(h, beta=3000.0):
    """Soft-min of the max: encourage a flat plateau near the maximum,
    which is what the true optimiser wants (variance reduction)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    # soft-min surrogate for max: -1/beta * log mean exp(-beta*L)
    # -> use log-sum-exp on (Lf), penalise low knots; equivalent to
    # beta-annealed max with reversed sign
    e = np.exp(np.clip(-beta * (mx - Lf), -60.0, 0.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    # surrogate max = mx - log(Z)/beta  (mean of top knots)
    sm = mx - np.log(Z) / beta
    if sm <= 1e-300:
        return _fun_grad(h)
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _refine_blocked(h, deadline, rng, rounds=3):
    n = h.size
    for r in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        nb = 4 + r
        edges = np.linspace(0, n, nb + 1).astype(int)
        for k in range(nb):
            if time.process_time() >= deadline - 1.0:
                break
            lo, hi = edges[k], edges[k + 1]
            if hi - lo < 4:
                continue
            free = np.arange(lo, hi)
            for beta in (1e7, 1e8, 0.0):
                if time.process_time() >= deadline - 1.0:
                    break
                ht = _lbfgs_block(h, free, 200, deadline - 0.5, beta=beta)
                if R_of(ht) > R_of(h) + 1e-15:
                    h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(20240917)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase A: sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, t0 + budget_seconds * 0.18,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        if R_of(ht) > bestR + 1e-14:
            best, bestR = ht, R_of(ht)
            print("NEW BEST (sharp) R=%.9f" % bestR)

    # ---- Phase A2: FLAT-TOP surrogate (new idea) ----
    # The true optimum has a broad plateau at the maximum of f*f.
    # Optimising a soft-min (=mean of top knots) of L pushes many
    # knots to the same max, then we sharpen with the real objective.
    if time.process_time() < deadline - 3.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, flat=True)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("NEW BEST (flat) R=%.9f" % bestR)
        # try flat on the peak window too
        win = _peak_window(best, tol=0.999, pad_frac=0.3, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.5, flat=True)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2, r2
            print("NEW BEST (flat-peak) R=%.9f" % bestR)
        # record flat-top attempt as alternative candidate
        alt_best = best.copy()
        alt_bestR = bestR

    # ---- Phase B: blocked coordinate refinement over whole vector ----
    block_deadline = t0 + budget_seconds * 0.60
    ht = _refine_blocked(best, block_deadline, rng, rounds=4)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht, R_of(ht)
        print("NEW BEST (blocked) R=%.9f" % bestR)

    # ---- Phase C: peak/off-peak alternating ----
    off_deadline = t0 + budget_seconds * 0.88
    settings = [
        ('peak',    0.9995, 0.30, 1e7),
        ('offpeak', 0.98, 0.06, 1e7),
        ('peak',    0.999,  0.20, 1e8),
        ('offpeak', 0.95, 0.15, 1e7),
        ('peak',    0.9995, 0.50, 1e8),
        ('offpeak', 0.98, 0.04, 0.0),
        ('peak',    0.999,  0.30, 0.0),
    ]
    accepted = 0
    rounds = 0
    while time.process_time() < off_deadline - 1.0:
        for (kind, tol, pad, beta) in settings:
            if time.process_time() >= off_deadline - 1.0:
                break
            rounds += 1
            win = _peak_window(best, tol=tol, pad_frac=pad, extra=64)
            if kind == 'offpeak':
                mask = np.ones(best.size, dtype=bool)
                mask[win] = False
                free = np.flatnonzero(mask)
            else:
                free = win
            cand = _lbfgs_block(best, free, 500, deadline - 3.0, beta=beta)
            r = R_of(cand)
            if cand.size == best.size and r > bestR + 1e-14:
                best, bestR = cand.copy(), r
                accepted += 1
                print("NEW BEST (%s) R=%.9f beta=%.0e" % (kind, bestR, beta))
    print("block rounds=%d accepted=%d" % (rounds, accepted))

    # ---- Phase D: fine local polish ----
    ht = _polish_ladder(best, deadline - 0.6, betas=(1e9, 1e10, 1e11, 0.0),
                        iters=250)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht, R_of(ht)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR - 1e-12:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _collapse_to_c(h, q):
    N = h.size
    nb = (N + q - 1) // q
    c = np.zeros(nb)
    for j in range(nb):
        seg = h[j * q:(j + 1) * q]
        if seg.size > 0:
            c[j] = seg.mean()
    return c


def _expand_from_c(c, q, N):
    h = np.repeat(c, q)[:N]
    if h.size < N:
        h = np.concatenate([h, np.full(N - h.size, c[-1] if c.size else 0.0)])
    return h


def _lbfgs_c(h0, q, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    N = h0.size
    c = _collapse_to_c(np.clip(h0, 0, None), q)
    nb = c.size
    if nb == 0:
        return h0

    def expand(cv):
        return _expand_from_c(np.clip(cv, 0, None), q, N)

    def f(cv):
        hh = expand(cv)
        val, g = _fun_grad_tie(hh)
        gc = np.zeros(nb)
        for j in range(nb):
            lo = j * q
            hi = min(N, (j + 1) * q)
            if hi > lo:
                gc[j] = g[lo:hi].sum()
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(expand(res.x))


def _cg_solve(hvp, b, lam, maxit, tol=1e-10):
    x = np.zeros_like(b)
    r = b.copy()
    p = r.copy()
    rs = r @ r
    if rs <= 0:
        return x
    for _ in range(maxit):
        Ap = hvp(p) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-30:
            break
        alpha = rs / pAp
        x += alpha * p
        r -= alpha * Ap
        rs_new = r @ r
        if rs_new < tol * tol * (b @ b):
            break
        p = r + (rs_new / rs) * p
        rs = rs_new
    return x


def _newton_block(h0, q, deadline, max_outer=60):
    """Damped Newton/trust-region on block-constant c (n = ceil(N/q))."""
    N = h0.size
    c = _collapse_to_c(np.clip(h0, 0, None), q)
    nb = c.size
    if nb == 0:
        return h0

    def expand(cv):
        return _expand_from_c(np.clip(cv, 0, None), q, N)

    def fg(cv):
        hh = expand(cv)
        val, g = _fun_grad_tie(hh)
        gc = np.zeros(nb)
        for j in range(nb):
            lo = j * q
            hi = min(N, (j + 1) * q)
            if hi > lo:
                gc[j] = g[lo:hi].sum()
        return val, gc

    val, g = fg(c)
    accepted = 0
    for it in range(max_outer):
        if time.process_time() >= deadline - 1.0:
            break
        gn = np.linalg.norm(g)
        if gn < 1e-8:
            print("newton: ||g||=%.2e < 1e-8, stop at it=%d" % (gn, it))
            break

        def hvp(p):
            eps = 1e-6 * max(np.max(np.abs(c)), 1.0) / max(np.max(np.abs(p)), 1.0)
            _, g2 = fg(c + eps * p)
            return (g2 - g) / eps

        lam = 1e-8 * gn
        p = _cg_solve(hvp, -g, lam, 40)
        # predicted decrease of quadratic model
        pred = -(g @ p) - 0.5 * (p @ hvp(p))
        step_norm = np.linalg.norm(p)
        if step_norm < 1e-14:
            print("newton: tiny step at it=%d" % it)
            break

        # Armijo line search
        alpha = 1.0
        ok = False
        for _ in range(30):
            cnew = np.clip(c + alpha * p, 0.0, None)
            vnew, gnew = fg(cnew)
            if vnew < val - 1e-4 * alpha * (g @ p) + 1e-16:
                ok = True
                break
            alpha *= 0.5
        if not ok:
            print("newton: line search failed at it=%d" % it)
            break

        actual = val - vnew
        c, val, g = cnew, vnew, gnew
        accepted += 1
        ratio = actual / pred if pred > 0 else 0.0
        print("newton it=%d acc=%d val=%.9f ||g||=%.2e alpha=%.3f ratio=%.3f"
              % (it, accepted, val, np.linalg.norm(g), alpha, ratio))
        if actual < 1e-14:
            break

    print("newton: %d accepted steps" % accepted)
    return _rescale(expand(c))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    altR = -1.0

    # ---- Newton on block-constant c (q=32) ----
    q = 32
    if time.process_time() < deadline - 2.0:
        # budget split: newton ~60%, polish ~40%
        newton_end = min(deadline - 1.0, time.process_time() + budget_seconds * 0.55)
        hn = _newton_block(best, q, newton_end, max_outer=60)
        rn = R_of(hn)
        print("newton block R=%.9f (lifted full-N)" % rn)
        if rn > altR:
            altR = rn
            alt_best = hn.copy()
        if rn > bestR + 1e-15:
            best, bestR = hn.copy(), rn

    # ---- fallback: block-constant L-BFGS on a few q values ----
    q_list = [32, 30, 34]
    for qq in q_list:
        if time.process_time() >= deadline - 1.0:
            break
        tq_end = min(deadline - 0.5, time.process_time() + (deadline - time.process_time()) / 2.0)
        hq = _lbfgs_c(best, qq, 200, tq_end)
        r1 = R_of(hq)
        print("q=%d lbfgs R=%.9f" % (qq, r1))
        if r1 > altR:
            altR = r1
            alt_best = hq.copy()
        if r1 > bestR + 1e-15:
            best, bestR = hq.copy(), r1

    # ---- full-N tie polish ----
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.3, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

