    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_kappa(h0, tau, kappa, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
