def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _near_max_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_polish(h, maxiter, deadline):
    ht = h
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, maxiter, deadline - 0.3, beta=beta)
    return ht


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _gauss_smooth(h, sigma):
    if sigma <= 0:
        return h
    rad = int(3 * sigma) + 1
    x = np.arange(-rad, rad + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    pad = np.concatenate((np.zeros(rad), h, np.zeros(rad)))
    out = np.convolve(pad, k, mode='valid')
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 0 (DEEP): kappa-penalty ladder on full array ----
    ladder = [(0.95, 300.0), (0.90, 1000.0), (0.85, 3000.0),
              (0.80, 10000.0), (0.75, 30000.0)]
    kappa_best = best.copy()
    kappa_bestR = bestR
    kappa_origin = 'start'
    for (tau, kappa) in ladder:
        if time.process_time() >= deadline - 8.0:
            break
        rung_deadline = min(deadline - 6.0, time.process_time() + 4.0)
        ht = _lbfgs_kappa(kappa_best, tau, kappa, 80, rung_deadline)
        r_kappa = R_of(ht)
        f01, f1, f5 = _near_max_fracs(ht)
        print("kappa tau=%.2f k=%.0f R=%.9f (0.1%%=%.4f 1%%=%.4f 5%%=%.4f)"
              % (tau, kappa, r_kappa, f01, f1, f5))
        # immediate tie polish to convert kappa distortion to real R
        tie_deadline = min(deadline - 5.0, time.process_time() + 1.5)
        ht2 = _lbfgs_tie(ht, 40, tie_deadline)
        r2 = R_of(ht2)
        f01b, f1b, f5b = _near_max_fracs(ht2)
        print("  tie R=%.9f (0.1%%=%.4f 1%%=%.4f 5%%=%.4f) rung_start=%.9f"
              % (r2, f01b, f1b, f5b, kappa_bestR))
        if r2 > kappa_bestR + 1e-14:
            kappa_best, kappa_bestR = ht2.copy(), r2
            kappa_origin = 'kappa%.2f_%.0f+tie' % (tau, kappa)
            print("  rung NEW BEST R=%.9f" % kappa_bestR)
        else:
            if r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2
            if r_kappa > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r_kappa

    if kappa_bestR > bestR + 1e-14:
        best, bestR, origin = kappa_best.copy(), kappa_bestR, kappa_origin
        print("kappa ladder NEW BEST R=%.9f origin=%s" % (bestR, origin))
    elif kappa_bestR > alt_bestR:
        alt_best, alt_bestR = kappa_best.copy(), kappa_bestR

    # ---- Phase 0b: full-N tie polish on best ----
    if time.process_time() < deadline - 8.0:
        tie_deadline = min(deadline - 6.0, time.process_time() + 8.0)
        ht = _lbfgs_tie(best, 200, tie_deadline)
        r = R_of(ht)
        f01, f1, f5 = _near_max_fracs(ht)
        print("full tie R=%.9f (0.1%%=%.4f 1%%=%.4f 5%%=%.4f)"
              % (r, f01, f1, f5))
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+tie'
            print("full tie NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 0c: peak-window polishes (pad 0.05/0.03) ----
    for pad in [0.05, 0.03]:
        if time.process_time() >= deadline - 4.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        slice_deadline = min(deadline - 2.0, time.process_time() + 3.0)
        ht2 = _lbfgs_block(best, win, 400, slice_deadline, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR, origin = ht2.copy(), r2, origin + '+pk%.2f' % pad
            print("peak pad=%.2f NEW BEST R=%.9f" % (pad, bestR))
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 1: half-resolution polish ----
    N = best.size
    best_c = None
    best_cR = -1.0
    half_deadline = t0 + budget_seconds * 0.72
    if N % 2 == 0 and N >= 4 and time.process_time() < half_deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: smoothing perturbations ----
    if time.process_time() < deadline - 6.0:
        sigmas = [0.6, 1.2, 2.0, 3.0, 1.8, 0.9]
        si = 0
        while time.process_time() < deadline - 5.0:
            sigma = sigmas[si % len(sigmas)]
            si += 1
            hs = _rescale(_gauss_smooth(best, sigma))
            slice_deadline = min(deadline - 2.0,
                                 time.process_time() + 0.05 * budget_seconds)
            ht = hs
            for beta in [1e6, 1e7]:
                if time.process_time() >= slice_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 250, slice_deadline - 0.3, beta=beta)
            if time.process_time() < slice_deadline - 0.5:
                win = _peak_window(ht, pad_frac=0.12, extra=128)
                ht2 = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
                if R_of(ht2) > R_of(ht):
                    ht = ht2
            if time.process_time() < slice_deadline - 0.5:
                ht = _lbfgs_all_pos(ht, 250, slice_deadline - 0.3, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'smooth%d' % si
                print("smooth sigma=%.2f NEW BEST R=%.9f" % (sigma, bestR))
            else:
                if r > alt_bestR:
                    alt_best, alt_bestR = ht.copy(), r
                print("smooth sigma=%.2f R=%.9f (no gain)" % (sigma, r))

    # ---- Phase 3: perturb-then-polish restarts on half-res ----
    restarts_done = 0
    if best_c is not None and time.process_time() < deadline - 4.0:
        rng = np.random.default_rng(7)
        amps = [0.008, 0.015, 0.03, 0.05]
        ri = 0
        while time.process_time() < deadline - 4.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc2 = best_c.copy()
            nz = cc2 > 0
            if nz.sum() == 0:
                break
            cc2[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc2 = _rescale(cc2)
            r0 = R_of(cc2)
            slice_deadline = min(deadline - 2.0,
                                 time.process_time() + 0.04 * budget_seconds)
            work_c2, cand_c, cand_cR, org = _half_cycle(
                cc2, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.15])
            restarts_done += 1
            if cand_cR > best_cR + 1e-12:
                best_c = cand_c.copy()
                best_cR = cand_cR
                print("restart %d amp=%.3f ACCEPT R(c)=%.9f" %
                      (ri, amp, best_cR))
            if time.process_time() >= deadline - 4.0:
                break

    # ---- Phase 4: lift best_c and full-N polish ----
    if best_c is not None:
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        if r_lift > bestR + 1e-14:
            best, bestR, origin = h_lift.copy(), r_lift, 'restart_lift'
            print("restart lift NEW BEST R=%.9f" % bestR)
        elif r_lift > alt_bestR:
            alt_best, alt_bestR = h_lift, r_lift
        ht = h_lift
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+full'
            print("full polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 5: fine peak polish on best ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    f01, f1, f5 = _near_max_fracs(best)
    print("restarts=%d best_c=%.9f best_full=%.9f" %
          (restarts_done, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f, "
          "near-max 0.1%%=%.4f 1%%=%.4f 5%%=%.4f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best),
           f01, f1, f5))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _rasterize(h, factor):
    M = h.size
    out = np.empty(M * factor)
    nxt = np.concatenate((h[1:], [0.0]))
    for j in range(factor):
        t = (j + 0.5) / factor
        out[j::factor] = h + (nxt - h) * t
    return out


def _upsample_pw_linear(h, factor):
    # treat h as samples of a piecewise-linear f at knots; resample densely
    return _rasterize(h, factor)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%) before: %.4f" % _frac_near_max(best, 1e-3))

    alt_best = None
    altR = -1.0

    # ---- Refinement at higher resolution ----
    # The start is a step function; treat it as a piecewise-constant f.
    # To escape the step-function plateau, we upsample to a finer step function
    # (piecewise-constant approximation of the same f) and re-polish.
    N = best.size
    # Try a few upsample factors and polish
    for factor in (2, 3, 4):
        if time.process_time() >= deadline - 8.0:
            break
        hu = np.repeat(best, factor)
        # preserve mass: piecewise-constant h at factor resolution, same f
        hu = hu / factor  # actually mass preserved: sum(hu) = sum(best)*factor/factor
        # Wait: repeat gives sum = factor*sum(best). Divide by factor gives same sum.
        hu = _rescale(hu)
        ru = R_of(hu)
        print("upsample x%d R=%.9f (N=%d)" % (factor, ru, hu.size))
        if ru > altR:
            altR = ru
            alt_best = hu.copy()
        # polish this upsampled version
        tlim = min(deadline - 4.0, time.process_time() + 6.0)
        pol = _lbfgs_block(hu, np.arange(hu.size), 250, tlim, tie=True)
        rp = R_of(pol)
        print("  upsampled polish R=%.12f" % rp)
        if rp > altR:
            altR = rp
            alt_best = pol.copy()
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            # restart from this finer version
            break

    # peak-window polish on best
    for pad in (0.05, 0.02, 0.01):
        if time.process_time() >= deadline - 2.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht2 = _lbfgs_block(best, win, 300,
                           min(deadline - 1.0, time.process_time() + 3.0), tie=True)
        r = R_of(ht2)
        if r > altR:
            altR = r
            alt_best = ht2.copy()
        if r > bestR + 1e-15:
            best, bestR = ht2.copy(), r

    print("frac near max (0.1%%) after: %.4f" % _frac_near_max(best, 1e-3))

    # final full polish on best
    if time.process_time() < deadline - 1.5:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 4.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            if rp > altR:
                altR = rp
                alt_best = pol.copy()

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _rasterize(h, factor):
    M = h.size
    out = np.empty(M * factor)
    nxt = np.concatenate((h[1:], [0.0]))
    for j in range(factor):
        t = (j + 0.5) / factor
        out[j::factor] = h + (nxt - h) * t
    return out


def _upsample_pw_linear(h, factor):
    # treat h as samples of a piecewise-linear f at knots; resample densely
    return _rasterize(h, factor)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%) before: %.4f" % _frac_near_max(best, 1e-3))

    alt_best = None
    altR = -1.0

    # ---- Refinement at higher resolution ----
    # The start is a step function; treat it as a piecewise-constant f.
    # To escape the step-function plateau, we upsample to a finer step function
    # (piecewise-constant approximation of the same f) and re-polish.
    N = best.size
    # Try a few upsample factors and polish
    for factor in (2, 3, 4):
        if time.process_time() >= deadline - 8.0:
            break
        hu = np.repeat(best, factor)
        # preserve mass: piecewise-constant h at factor resolution, same f
        hu = hu / factor  # actually mass preserved: sum(hu) = sum(best)*factor/factor
        # Wait: repeat gives sum = factor*sum(best). Divide by factor gives same sum.
        hu = _rescale(hu)
        ru = R_of(hu)
        print("upsample x%d R=%.9f (N=%d)" % (factor, ru, hu.size))
        if ru > altR:
            altR = ru
            alt_best = hu.copy()
        # polish this upsampled version
        tlim = min(deadline - 4.0, time.process_time() + 6.0)
        pol = _lbfgs_block(hu, np.arange(hu.size), 250, tlim, tie=True)
        rp = R_of(pol)
        print("  upsampled polish R=%.12f" % rp)
        if rp > altR:
            altR = rp
            alt_best = pol.copy()
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            # restart from this finer version
            break

    # peak-window polish on best
    for pad in (0.05, 0.02, 0.01):
        if time.process_time() >= deadline - 2.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht2 = _lbfgs_block(best, win, 300,
                           min(deadline - 1.0, time.process_time() + 3.0), tie=True)
        r = R_of(ht2)
        if r > altR:
            altR = r
            alt_best = ht2.copy()
        if r > bestR + 1e-15:
            best, bestR = ht2.copy(), r

    print("frac near max (0.1%%) after: %.4f" % _frac_near_max(best, 1e-3))

    # final full polish on best
    if time.process_time() < deadline - 1.5:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.5, time.process_time() + 4.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            if rp > altR:
                altR = rp
                alt_best = pol.copy()

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _extend_support(h, grow):
    if grow <= 0:
        return h.copy()
    eps = 1e-3 * h.mean() if h.mean() > 0 else 1e-3
    pad = np.full(grow, eps)
    return np.concatenate([pad, h, pad])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = 0.0
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: refine start
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 600, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # Phase B: grow support moderately (smaller grow helps with 60s budget)
    n0 = best.size
    grow = max(64, min(int(n0 * 0.10), 3000, (1000000 - n0) // 2))
    if grow > 0 and time.process_time() < deadline - 3.0:
        ext = _extend_support(best, grow)
        ext = _rescale(ext)
        extR = R_of(ext)
        print("grow=%d ext R=%.7f" % (grow, extR))
        if time.process_time() < deadline - 3.0:
            ht = _lbfgs_all_pos(ext, 400, deadline - 3.0, beta=1e7)
            r = R_of(ht)
            if r > extR:
                ext, extR = ht, r
        for it in range(5):
            if time.process_time() >= deadline - 2.5:
                break
            win = _peak_window(ext, pad_frac=0.3 + 0.1 * it, extra=128)
            ht = _lbfgs_block(ext, win, maxiter=250, deadline=deadline - 2.5,
                              beta=1e7)
            r = R_of(ht)
            if r > extR + 1e-14:
                ext, extR = ht, r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(ext, 500, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > extR + 1e-14:
                ext, extR = ht, r
        alt, altR = ext.copy(), extR
        print("extended line R=%.7f (N=%d)" % (altR, alt.size))
        if altR > bestR:
            best, bestR = alt.copy(), altR

    # Phase C: alternate polishing until deadline
    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 500, deadline - 1.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 300, deadline - 1.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for frac in (0.1, 0.25, 0.5):
            if time.process_time() >= deadline - 1.5:
                break
            win = _peak_window(best, pad_frac=frac, extra=256)
            ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.5,
                              beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, best.size))

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        if alt is not None and altR < bestR - 1e-9:
            return {"best": best, "alternative": alt}
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6 and altR > 0:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

