def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _extend_support(h, grow):
    if grow <= 0:
        return h.copy()
    eps = 1e-3 * h.mean() if h.mean() > 0 else 1e-3
    pad = np.full(grow, eps)
    return np.concatenate([pad, h, pad])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = 0.0
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: refine start
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 600, deadline - 2.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    # Phase B: grow support moderately (smaller grow helps with 60s budget)
    n0 = best.size
    grow = max(64, min(int(n0 * 0.10), 3000, (1000000 - n0) // 2))
    if grow > 0 and time.process_time() < deadline - 3.0:
        ext = _extend_support(best, grow)
        ext = _rescale(ext)
        extR = R_of(ext)
        print("grow=%d ext R=%.7f" % (grow, extR))
        if time.process_time() < deadline - 3.0:
            ht = _lbfgs_all_pos(ext, 400, deadline - 3.0, beta=1e7)
            r = R_of(ht)
            if r > extR:
                ext, extR = ht, r
        for it in range(5):
            if time.process_time() >= deadline - 2.5:
                break
            win = _peak_window(ext, pad_frac=0.3 + 0.1 * it, extra=128)
            ht = _lbfgs_block(ext, win, maxiter=250, deadline=deadline - 2.5,
                              beta=1e7)
            r = R_of(ht)
            if r > extR + 1e-14:
                ext, extR = ht, r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(ext, 500, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > extR + 1e-14:
                ext, extR = ht, r
        alt, altR = ext.copy(), extR
        print("extended line R=%.7f (N=%d)" % (altR, alt.size))
        if altR > bestR:
            best, bestR = alt.copy(), altR

    # Phase C: alternate polishing until deadline
    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 500, deadline - 1.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_all_pos(best, 300, deadline - 1.5, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for frac in (0.1, 0.25, 0.5):
            if time.process_time() >= deadline - 1.5:
                break
            win = _peak_window(best, pad_frac=frac, extra=256)
            ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.5,
                              beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, best.size))

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        if alt is not None and altR < bestR - 1e-9:
            return {"best": best, "alternative": alt}
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6 and altR > 0:
        out["alternative"] = alt
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_period(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p == 0:
            m = n // p
            c = h.reshape(m, p).mean(axis=1)
            if np.allclose(np.repeat(c, p), h, atol=1e-9 * (np.abs(h).max() + 1)):
                return p
    return 1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = R_of(best)
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # ---- H22 experiment: coarse envelope of the 32x staircase ----
    N = best.size
    period = _detect_period(best)
    print("detected period=%d (N=%d)" % (period, N))

    coarse_cand = None
    coarseR = -1.0
    if period > 1 and N % period == 0:
        m = N // period
        c = best.reshape(m, period).mean(axis=1)
        Rc = R_of(c)
        Rrep = R_of(np.repeat(c, period))
        print("coarse m=%d R_of(c)=%.12f R_of(repeat)=%.12f diff=%.3e"
              % (m, Rc, Rrep, Rc - Rrep))

        coarseBest = c if Rc > bestR else best
        # coarse L-BFGS at N=m
        cdead = min(deadline - 10.0, time.process_time() + 20.0)
        cpol = _lbfgs_block(c, np.arange(m), 300, cdead, tie=True)
        Rcp = R_of(cpol)
        print("coarse full polish R=%.12f" % Rcp)
        if Rcp > Rc:
            c, Rc = cpol, Rcp

        # peak-window polish on c
        if time.process_time() < deadline - 8.0:
            win = _peak_window(c, pad_frac=0.05, extra=96)
            cdead2 = min(deadline - 6.0, time.process_time() + 4.0)
            cpol2 = _lbfgs_block(c, win, 300, cdead2, tie=True)
            Rcp2 = R_of(cpol2)
            print("coarse peak polish R=%.12f" % Rcp2)
            if Rcp2 > Rc:
                c, Rc = cpol2, Rcp2

        coarse_cand = c
        coarseR = Rc
        print("coarse candidate R=%.12f (bestR=%.12f)" % (coarseR, bestR))
        if coarseR > bestR:
            best, bestR = c.copy(), coarseR
            print("  -> coarse beats fine, adopted")

        # expand polished c to full N and polish
        if time.process_time() < deadline - 6.0:
            expanded = _rescale(np.repeat(c, period))
            Rex = R_of(expanded)
            print("expanded R=%.12f" % Rex)
            edead = min(deadline - 4.0, time.process_time() + 8.0)
            epol = _lbfgs_block(expanded, np.arange(N), 200, edead, tie=True)
            Rep = R_of(epol)
            print("expanded full polish R=%.12f" % Rep)
            if Rep > Rex:
                expanded, Rex = epol, Rep
            for pad in (0.05, 0.03):
                if time.process_time() >= deadline - 1.0:
                    break
                win = _peak_window(expanded, pad_frac=pad, extra=96)
                edead2 = min(deadline - 0.5, time.process_time() + 3.0)
                epol2 = _lbfgs_block(expanded, win, 300, edead2, tie=True)
                Rep2 = R_of(epol2)
                print("expanded peak polish pad=%.2f R=%.12f" % (pad, Rep2))
                if Rep2 > Rex:
                    expanded, Rex = epol2, Rep2
            if Rex > bestR:
                best, bestR = expanded.copy(), Rex
                print("  -> expanded beats current, adopted")
    else:
        print("no 32x periodicity detected; skipping coarse experiment")

    # ---- Reserve: full-N tie polish on current best, then peak polishes ----
    if time.process_time() < deadline - 6.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 4.0, time.process_time() + 6.0), tie=True)
        rp = R_of(pol)
        print("full tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.5, time.process_time() + 3.0), tie=True)
        r = R_of(ht)
        print("peak polish pad=%.2f R=%.12f" % (pad, r))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if coarse_cand is not None and coarseR > startR + 1e-14 and coarseR <= bestR + 1e-14:
        result["alternative"] = coarse_cand
    return result

