        return h0
    N = h0.size
    c = _collapse_to_c(np.clip(h0, 0, None), q)
    nb = c.size
    if nb == 0:
        return h0

    def expand(cv):
        return _expand_from_c(np.clip(cv, 0, None), q, N)

    def f(cv):
        hh = expand(cv)
        val, g = _fun_grad_tie(hh)
        gc = np.zeros(nb)
        for j in range(nb):
            lo = j * q
            hi = min(N, (j + 1) * q)
            if hi > lo:
                gc[j] = g[lo:hi].sum()
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(expand(res.x))


# ---------------- D7 factorization: h = kron(c, g) ----------------

def _expand_cg(c, g):
    return np.repeat(c, g.size) * np.tile(g, c.size)


def _grad_cg(h, q):
    """Return grad_c (len nb) and grad_g (len q) for h = kron(c,g)."""
    val, gh = _fun_grad_tie(h)
    N = h.size
    nb = (N + q - 1) // q
    c = np.zeros(nb); g = np.zeros(q)
    for j in range(nb):
        lo = j * q; hi = min(N, (j + 1) * q)
        seg = h[lo:hi]
        if seg.size == 0:
            continue
        # c[j] = seg[0]/g[0] if g[0]!=0 else mean
        gg = seg.size
        # recover c[j] and g from h: c[j]*g[i] = h[lo+i]
        # use least squares: c[j] = sum h*g / sum g^2, g = sum h*c / sum c^2
        pass
    return val, gh


def _fit_cg(h, q):
    N = h.size
    nb = (N + q - 1) // q
    c = np.zeros(nb)
    g = np.ones(q)
    # initialize c from block means, g uniform
    for j in range(nb):
        lo = j * q; hi = min(N, (j + 1) * q)
        seg = h[lo:hi]
        if seg.size > 0:
            c[j] = seg.mean()
    return c, g


def _lbfgs_cg(c0, g0, q, N, which, maxiter, deadline):
    """Optimize c (which='c') or g (which='g') with the other fixed."""
    if time.process_time() >= deadline - 0.3:
        return c0, g0
    c = np.clip(c0, 0, None).copy()
    g = np.clip(g0, 0, None).copy()
    if which == 'c':
        x0 = c.copy()
        nb = c.size

        def expand(x):
            return np.repeat(np.clip(x, 0, None), q)[:N] * np.tile(g, nb)

        def f(x):
            hh = expand(x)
            val, gh = _fun_grad_tie(hh)
            gc = np.zeros(nb)
            for j in range(nb):
                lo = j * q; hi = min(N, (j + 1) * q)
                if hi > lo:
                    gc[j] = np.dot(gh[lo:hi], g[:hi - lo])
            return val, gc
    else:
        x0 = g.copy()
        nb = c.size

        def expand(x):
            gg = np.clip(x, 0, None)
            return np.repeat(c, q)[:N] * np.tile(gg, nb)[:N]

        def f(x):
            hh = expand(x)
            val, gh = _fun_grad_tie(hh)
            gg = np.zeros(q)
            for j in range(nb):
                lo = j * q; hi = min(N, (j + 1) * q)
                if hi > lo:
                    gg[:hi - lo] += gh[lo:hi] * c[j]
            return val, gg

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0, g0
    if res is None:
        return c0, g0
    if which == 'c':
        c = np.clip(res.x, 0, None)
    else:
        g = np.clip(res.x, 0, None)
        if g.mean() > 0:
            g = g / g.mean()
    return c, g


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    altR = -1.0

    # ---- D7 factorization: alternate c and g ----
    q = 32
    c, g = _fit_cg(best, q)
    g = np.ones(q)
    nb = c.size
    print("D7 init: nb=%d q=%d std(g)/mean=%.4f" % (nb, q, g.std() / max(g.mean(), 1e-12)))

    round_end = deadline - 8.0
    round_idx = 0
    while time.process_time() < round_end and round_idx < 6:
        round_idx += 1
        t_now = time.process_time()
        remaining = round_end - t_now
        if remaining < 1.0:
            break
        # 8s on c, 3s on g (scaled to remaining)
        c_end = min(round_end, t_now + min(8.0, remaining * 0.7))
        c, g = _lbfgs_cg(c, g, q, N, 'c', 300, c_end)
        g_end = min(round_end, time.process_time() + min(3.0, max(0.5, round_end - time.process_time()) * 0.6))
        c, g = _lbfgs_cg(c, g, q, N, 'g', 300, g_end)
        if g.mean() > 0:
            g = g / g.mean()
        hfull = _expand_cg(c, g)
        hfull = _rescale(hfull)
        r = R_of(hfull)
        gstd = g.std() / max(g.mean(), 1e-12)
        print("D7 round %d: R=%.9f std(g)/mean=%.4f" % (round_idx, r, gstd))
        if r > altR:
            altR = r
            alt_best = hfull.copy()
        if r > bestR + 1e-15:
            best, bestR = hfull.copy(), r

    # ---- Newton on block-constant c (q=32) from best ----
    if time.process_time() < deadline - 2.0:
        newton_end = min(deadline - 1.0, time.process_time() + budget_seconds * 0.25)
        hn = _lbfgs_c(best, q, 300, newton_end)
        rn = R_of(hn)
        print("block lbfgs R=%.9f" % rn)
        if rn > altR:
            altR = rn
            alt_best = hn.copy()
        if rn > bestR + 1e-15:
            best, bestR = hn.copy(), rn

    # ---- fallback: block-constant L-BFGS on a few q values ----
    q_list = [32, 30, 34]
    for qq in q_list:
        if time.process_time() >= deadline - 1.0:
            break
        tq_end = min(deadline - 0.5, time.process_time() + (deadline - time.process_time()) / 2.0)
        hq = _lbfgs_c(best, qq, 200, tq_end)
        r1 = R_of(hq)
        print("q=%d lbfgs R=%.9f" % (qq, r1))
        if r1 > altR:
            altR = r1
            alt_best = hq.copy()
        if r1 > bestR + 1e-15:
            best, bestR = hq.copy(), r1

    # ---- full-N tie polish ----
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.3, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_within(h, tol=0.01):
    Lf = _knots(h)
    mx = Lf.max()
    return float(np.mean(Lf >= mx * (1.0 - tol)))


def _exact_polish(best, bestR, deadline, fracs=(0.02, 0.05)):
    if time.process_time() >= deadline - 0.3:
        return best, bestR
    cap = min(deadline - 0.3, time.process_time() + 3.0)
    hp = _lbfgs_log(best, 300, cap, _fun_grad)
    rp = R_of(hp)
    if rp > bestR + 1e-15:
        best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, extra=max(64, int(frac * best.size)))
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 150, cap, _fun_grad)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    return best, bestR


def _beta_polish(best, bestR, beta, deadline, iters=200):
    fg = (lambda hh: _fun_grad_beta(hh, beta))
    cap = min(deadline - 0.3, time.process_time() + 3.0)
    hs = _lbfgs_log(best, iters, cap, fg)
    rs = R_of(hs)
    if rs > bestR + 1e-15:
        return hs, rs
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d) f1%%=%.4f"
          % (bestR, best.size, _frac_within(best)))

    # ---- Phase 1: exact polish of start ----
    best, bestR = _exact_polish(best, bestR, deadline)
    print("  polish1 R=%.9f f1%%=%.4f" % (bestR, _frac_within(best)))

    # ---- Phase 2: soft-max (beta) sweep to reshape peak ----
    for beta in (1e2, 3e2, 1e3, 3e3, 1e4):
        if time.process_time() >= deadline - 0.5:
            break
        hs, rs = _beta_polish(best, bestR, beta, deadline, iters=250)
        hb, rb = _exact_polish(hs, rs, deadline)
        print("  beta=%.0e Rpost=%.9f f1%%=%.4f" % (beta, rb, _frac_within(hb)))
        if rb > bestR + 1e-15:
            best, bestR = hb, rb

    # ---- Phase 3: stronger beta + peak-window blocks ----
    for beta in (3e3, 1e4, 3e4):
        if time.process_time() >= deadline - 0.5:
            break
        hs, rs = _beta_polish(best, bestR, beta, deadline, iters=300)
        # peak-window block polish at exact R
        free = _peak_window(hs, tol=0.999, pad_frac=0.5, extra=256)
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hb = _lbfgs_block(hs, free, 200, cap, _fun_grad)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
            print("  beta2=%.0e R=%.9f f1%%=%.4f" % (beta, bestR, _frac_within(best)))

    # ---- Phase 4: keep alternating until time runs out ----
    best_beta = 3e3
    stall = 0
    while time.process_time() < deadline - 0.5:
        hs, rs = _beta_polish(best, bestR, best_beta, deadline, iters=200)
        hb, rb = _exact_polish(hs, rs, deadline)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
            stall = 0
            print("  alt R=%.9f f1%%=%.4f" % (bestR, _frac_within(best)))
        else:
            stall += 1
            if stall >= 2:
                best_beta *= 3.0
                if best_beta > 1e5:
                    break
                stall = 0

    best, bestR = _exact_polish(best, bestR, deadline)

    print("final R=%.9f (N=%d) f1%%=%.4f"
          % (bestR, best.size, _frac_within(best)))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

