    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active_mask] if False else g

    def f2(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f2, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _jitter_block(h, p, nb, rng, amp, shift):
    n = h.size
    out = h.copy()
    for b in range(nb):
        lo = b * p
        hi = min(n, (b + 1) * p)
        if hi <= lo:
            break
        blk = h[lo:hi].copy()
        eps = rng.uniform(-amp, amp) if amp > 0 else 0.0
        blk = blk * np.exp(eps)
        if shift:
            s = int(rng.integers(-2, 3))
            if s != 0:
                blk = np.roll(blk, s)
        out[lo:hi] = blk
    return out


def _upsample(h, factor):
    """Smooth upsampling of the step heights (keeps shape, adds resolution)."""
    if factor <= 1:
        return h
    n = h.size
    m = n * factor
    # linear interpolation of step heights onto finer grid
    xs = (np.arange(m) + 0.5) / factor - 0.5
    idx = np.clip(np.floor(xs).astype(int), 0, n - 1)
    frac = xs - idx
    frac = np.clip(frac, 0.0, 1.0)
    nxt = np.clip(idx + 1, 0, n - 1)
    hp = np.concatenate((h, [h[-1]]))
    return hp[idx] * (1.0 - frac) + hp[nxt] * frac


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    alt = None
    altR = 0.0
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- NEW IDEA: try upsampled (finer resolution) versions of start ----
    # The peak is only ~35% wide; upsampling can let the optimiser shape
    # the peak more finely and possibly push R up slightly.
    N0 = best.size
    up_candidates = []
    for fac in (2, 3):
        if N0 * fac <= 900000:
            hu = _rescale(_upsample(best, fac))
            up_candidates.append(hu)

    race_end = t0 + min(budget_seconds * 0.55, 30.0)
    for i, cand in enumerate(up_candidates):
        if time.process_time() >= race_end - 1.0:
            break
        slice_end = min(race_end, time.process_time() + 7.0)
        h_t = _lbfgs_all_pos(cand, 250, slice_end - 0.5, tie=True)
        if time.process_time() < slice_end - 0.5:
            h_t = _peak_ladder(h_t, slice_end - 0.3,
                               pads=(0.08, 0.05, 0.03), iters=150, tie=True)
        r_t = R_of(h_t)
        print("upsample x%d R=%.9f dR=%+.3e ties=%d zero_frac=%.4f"
              % (i + 1, r_t, r_t - startR, _tie_count(h_t), _zero_frac(h_t)))
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("ACCEPT upsample dR=%+.3e" % (bestR - startR))
        elif r_t > altR:
            alt, altR = h_t.copy(), r_t

    # ---- period-jittered candidates on the current best ----
    rng = np.random.default_rng(12345)
    N = best.size
    p = max(1, N // 32)
    nb = max(1, N // p)

    candidates = []
    for c in range(1, 5):
        amp = 0.08
        shift = (c % 2 == 1)
        cand = _jitter_block(best, p, nb, rng, amp, shift)
        cand = _rescale(cand)
        candidates.append(cand)

    for i, cand in enumerate(candidates):
        if time.process_time() >= race_end - 1.0:
            break
        slice_end = min(race_end, time.process_time() + 4.0)
        h_t = _lbfgs_all_pos(cand, 200, slice_end - 0.5, tie=True)
        if time.process_time() < slice_end - 0.5:
            h_t = _peak_ladder(h_t, slice_end - 0.3,
                               pads=(0.08, 0.05, 0.03), iters=120, tie=True)
        r_t = R_of(h_t)
        print("jitter %d R=%.9f dR=%+.3e ties=%d zero_frac=%.4f"
              % (i + 1, r_t, r_t - startR, _tie_count(h_t), _zero_frac(h_t)))
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("ACCEPT jitter dR=%+.3e" % (bestR - startR))
        elif r_t > altR:
            alt, altR = h_t.copy(), r_t

    # ---- full polish loop on best ----
    loop_end = t0 + min(budget_seconds * 0.82, 49.0)
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 8.0)
        h_t = _lbfgs_all_pos(best, 600, slice_end - 3.0, tie=True)
        r_t = R_of(h_t)
        dR = r_t - bestR
        accepted = r_t > bestR + 1e-15
        if accepted:
            best, bestR = h_t.copy(), r_t
        print("tie pass %d N=%d dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f nearmax5=%.4f"
              % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                 bestR, _tie_count(h_t), _zero_frac(h_t),
                 _nearmax_frac(h_t)))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=250, tie=True)
            r_t = R_of(h_t)
            dR = r_t - bestR
            accepted = r_t > bestR + 1e-15
            if accepted:
                best, bestR = h_t.copy(), r_t
            print("tie peak %d N=%d dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f nearmax5=%.4f"
                  % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                     bestR, _tie_count(h_t), _zero_frac(h_t),
                     _nearmax_frac(h_t)))

    # ---- final passes ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 4.0:
        h_t = _lbfgs_all_pos(best, 600, fd - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL argmax no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        if alt is not None and altR > 0:
            result["alternative"] = alt
        else:
            result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_band(h, tau):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    band = Lf >= tau * M
    dev = M - Lf[band]
    S = float(np.sum(dev * dev)) + 1e-30
    gLf = np.zeros_like(Lf)
    gLf[band] = 2.0 * (Lf[band] - M)
    m = int(np.argmax(Lf))
    gLf[m] += 2.0 * float(np.sum(dev))
    grad = _backprop(gLf, h)
    val = np.log(S)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 band=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if band is not None:
        fg = (lambda hh: _fun_grad_band(hh, band))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _band_stats(h, tau):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0, 0
    band = Lf >= tau * M
    S = float(np.sum((M - Lf[band]) ** 2))
    return S, int(band.sum())


def _detect_period(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p == 0:
            m = n // p
            c = h.reshape(m, p).mean(axis=1)
            if np.allclose(np.repeat(c, p), h, atol=1e-9 * (np.abs(h).max() + 1)):
                return p
    return 1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N = best.size
    full = np.arange(N)

    # ---- D1 experiment: flatness objective on the near-max band of g=f*f ----
    reserve = 15.0
    tau_ladder = (0.9995, 0.995, 0.98, 0.95)
    band_best = best.copy()
    band_bestR = bestR
    band_improved = False

    for tau in tau_ladder:
        if time.process_time() >= deadline - reserve:
            print("band tau=%.4f skipped (time)" % tau)
            break
        tlim = min(deadline - reserve, time.process_time() + 6.0)
        cand = _lbfgs_block(best, full, 150, tlim, band=tau)
        S0, n0 = _band_stats(best, tau)
        S1, n1 = _band_stats(cand, tau)
        r = R_of(cand)
        print("band tau=%.4f S %.3e->%.3e band %d->%d R=%.12f (best %.12f)"
              % (tau, S0, S1, n0, n1, r, band_bestR))
        if r > band_bestR + 1e-15:
            band_best = cand.copy()
            band_bestR = r
            band_improved = True
            print("  band IMPROVES R -> %.12f" % r)

    if band_improved:
        best, bestR = band_best.copy(), band_bestR
    else:
        print("band ladder gave no R gain; keeping p2364")

    # ---- Reserve: full-N tie polish, then peak polishes ----
    alt_best = None
    altR = -1.0

    if time.process_time() < deadline - 6.0:
        pol = _lbfgs_block(best, full, 200,
                           min(deadline - 4.0, time.process_time() + 6.0), tie=True)
        rp = R_of(pol)
        print("full tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        if rp > altR:
            altR, alt_best = rp, pol.copy()

    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.5, time.process_time() + 3.0), tie=True)
        r = R_of(ht)
        print("peak polish pad=%.2f R=%.12f" % (pad, r))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > altR:
            altR, alt_best = r, ht.copy()

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d, band_improved=%s)"
          % (bestR, startR, best.size, _tie_count(best), band_improved))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
