    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q, a):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad_tie(h)
    v = np.quantile(Lf, q)
    band = Lf >= v
    nb = int(band.sum())
    if nb <= 0:
        return _fun_grad_tie(h)
    cv = float(Lf[band].mean())
    if cv <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    m = int(np.argmax(Lf))
    gLf[m] += (1.0 - a) / M
    gLf[band] += a / (nb * cv)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (1.0 - a) * np.log(M) + a * np.log(cv)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 cvar=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if cvar is not None:
        q, a = cvar
        fg = (lambda hh: _fun_grad_cvar(hh, q, a))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _detect_period(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p == 0:
            m = n // p
            c = h.reshape(m, p).mean(axis=1)
            if np.allclose(np.repeat(c, p), h, atol=1e-9 * (np.abs(h).max() + 1)):
                return p
    return 1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size

    # ---- CVaR ladder on full N ----
    ladder = [(0.5, 0.95), (1.0, 0.98), (1.0, 0.90)]
    for (a, q) in ladder:
        if time.process_time() >= deadline - 20.0:
            break
        tlim = min(deadline - 18.0, time.process_time() + 4.0)
        cand = _lbfgs_block(best, np.arange(N), 150, tlim, cvar=(q, a))
        r = R_of(cand)
        Lf = _knots(cand)
        mx = Lf.max()
        v = np.quantile(Lf, q)
        nb = int(np.sum(Lf >= v))
        frac1 = _frac_near_max(cand, 0.01)
        acc = r > bestR + 1e-15
        print("cvar a=%.2f q=%.2f R=%.12f band=%d frac1%%=%.2f %s"
              % (a, q, r, nb, 100 * frac1, "ACCEPT" if acc else "reject"))
        if acc:
            best, bestR = cand.copy(), r

    # ---- p2364 randomized block-coordinate descent on block-constant space ----
    period = _detect_period(best)
    print("detected period=%d (N=%d)" % (period, N))
    m = N // period
    c = best.reshape(m, period).mean(axis=1)
    best = _rescale(np.repeat(c, period))
    bestR = R_of(best)
    print("block-constant R=%.12f (m=%d)" % (bestR, m))

    W = 128
    if m <= W:
        win_starts = [0]
        W = m
    else:
        win_starts = list(range(0, m - W + 1, max(1, W // 2)))
    if win_starts and win_starts[-1] + W < m:
        win_starts.append(m - W)

    rng = np.random.RandomState(12345)
    accepted = 0
    tail_accepted = 0
    peak_pos = 0.298
    reserve = 4.0
    outer = 0
    while time.process_time() < deadline - reserve - 8.0:
        outer += 1
        order = rng.permutation(len(win_starts))
        any_accept = False
        for oi in order:
            if time.process_time() >= deadline - reserve - 8.0:
                break
            w0 = win_starts[oi]
            fine_lo = period * w0
            fine_hi = min(N, period * (w0 + W))
            free = np.arange(fine_lo, fine_hi)
            tlim = min(deadline - reserve - 8.0, time.process_time() + 0.5)
            cand = _lbfgs_block(best, free, 40, tlim, tie=True)
            r = R_of(cand)
            if r > bestR + 1e-15:
                gain = r - bestR
                best = cand
                bestR = r
                accepted += 1
                any_accept = True
                centre = (w0 + W / 2.0) / m
                if abs(centre - peak_pos) > 0.3:
                    tail_accepted += 1
        if not any_accept:
            break

    print("accepted windows=%d (tail=%d), outer=%d" % (accepted, tail_accepted, outer))

    alt_best = None
    altR = -1.0

    if time.process_time() < deadline - 3.0:
        pol = _lbfgs_block(best, np.arange(N), 200,
                           min(deadline - 2.0, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        print("full tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        if rp > altR:
            altR, alt_best = rp, pol.copy()

    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.3, time.process_time() + 1.5), tie=True)
        r = R_of(ht)
        print("peak polish pad=%.2f R=%.12f" % (pad, r))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > altR:
            altR, alt_best = r, ht.copy()

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None)
    mx = Lp.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    r = Lp / mx
    rp = r ** p
    Sp = rp.sum()
    if Sp <= 0:
        return _fun_grad_tie(h)
    logp = np.log(mx) + np.log(Sp) / p
    e_max = np.zeros_like(Lf)
    e_max[int(np.argmax(Lp))] = 1.0
    rp1 = r ** (p - 1)
    S2 = np.sum(rp1 * r)
    dlogp = e_max / mx + (rp1 - S2 * e_max) / (Sp * mx)
    gLf = -dq / num + dlogp
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logp
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, pnorm=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if pnorm > 0:
        fg = (lambda hh: _fun_grad_pnorm(hh, pnorm))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _upsample(h, factor):
    # linear interpolation upsampling of step heights
    n = h.size
    if factor <= 1:
        return h.copy()
    m = (n - 1) * factor + 1
    xo = np.linspace(0, n - 1, m)
    xi = np.arange(n)
    return np.interp(xo, xi, h)


def _downsample(h, target):
    n = h.size
    if n <= target:
        return h.copy()
    # block-average to target
    edges = np.linspace(0, n, target + 1)
    out = np.zeros(target)
    for k in range(target):
        a = int(round(edges[k])); b = int(round(edges[k + 1]))
        if b <= a:
            b = a + 1
        out[k] = h[a:b].mean()
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    alt_best, altR = None, -1.0
    print("base R=%.9f (N=%d) frac5=%.4f"
          % (bestR, best.size, _frac_near_max(best, 5e-2)))

    def consider(hc, tag):
        nonlocal best, bestR, alt_best, altR
        rc = R_of(hc)
        if rc > altR:
            altR = rc; alt_best = hc.copy()
        if rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc
            print("  %s R=%.12f frac5=%.4f *" % (tag, rc, _frac_near_max(hc, 5e-2)))
        return rc

    # ---- Phase A: p-norm continuation (sharpening the max) ----
    for p in (8.0, 16.0, 32.0, 64.0):
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 4.0)
        hp = _lbfgs_block(best, np.arange(best.size), 300, tlim, pnorm=p)
        consider(hp, "pnorm p=%.0f" % p)

    # ---- Phase B: tie polish on peak window (main driver) ----
    for pad in (0.6, 0.4, 0.25, 0.15, 0.08, 0.04):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=256)
        ht = _lbfgs_block(best, win, 400,
                          min(deadline - 1.0, time.process_time() + 4.0),
                          tie=True)
        consider(ht, "win pad=%.2f" % pad)

    # ---- Phase C: global tie polish ----
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 400,
                           min(deadline - 0.5, time.process_time() + 6.0), tie=True)
        consider(pol, "final global tie")

    # ---- Phase D: refinement via upsampling (more resolution) ----
    # Upsample best and re-polish; more steps allow a finer plateau.
    while time.process_time() < deadline - 2.0 and best.size < 900000:
        f = 2
        hu = _upsample(best, f)
        hu = _rescale(hu)
        # polish the peak window (coarse pass)
        win = _peak_window(hu, pad_frac=0.3, extra=512)
        ht = _lbfgs_block(hu, win, 300,
                          min(deadline - 1.0, time.process_time() + 6.0),
                          tie=True)
        rc = consider(ht, "upsample x%d win" % f)
        if rc < bestR - 1e-12:
            # no gain from upsampling; stop
            break
        # fine polish on full
        if time.process_time() < deadline - 1.0:
            pf = _lbfgs_block(best, np.arange(best.size), 200,
                              min(deadline - 0.5, time.process_time() + 4.0),
                              tie=True)
            consider(pf, "upsample x%d full" % f)

    # ---- Phase E: final pnorm re-sharpen & tie ----
    if time.process_time() < deadline - 0.8:
        hp = _lbfgs_block(best, np.arange(best.size), 200,
                          min(deadline - 0.4, time.process_time() + 3.0), pnorm=48.0)
        consider(hp, "final pnorm")
    if time.process_time() < deadline - 0.4:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.2, time.process_time() + 2.0), tie=True)
        consider(pol, "final tie2")

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and R_of(alt_best) > startR + 1e-12:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_width(h, tau, T, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad_tie(h)
    if T <= 0:
        T = 1e-12 * M
    z = (Lf - tau * M) / T
    w = 1.0 / (1.0 + np.exp(-np.clip(z, -60.0, 60.0)))
    S = w.sum() + 1e-30
    gLf = -dq / num
    m = int(np.argmax(Lf))
    gLf[m] += 1.0 / M
    gLf += -(lam / S) * w * (1.0 - w) / T
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) - lam * np.log(S)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, mode='tie', tau=0.999, T=None, lam=1.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    if mode == 'width':
        def fg(hh):
            M = _knots(hh).max()
            TT = T if T is not None else 0.002 * M
            return _fun_grad_width(hh, tau, TT, lam)
    elif mode == 'tie':
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-2):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.12f (N=%d, frac1%%=%.4f)" % (bestR, N, _frac_near_max(best, 1e-2)))

    # ---- Width (soft superlevel-count) ladder ----
    taus = (0.999, 0.995, 0.99, 0.98)
    lam = 1.0
    all_idx = np.arange(N)
    width_results = []
    for tau in taus:
        if time.process_time() >= deadline - 8.0:
            break
        tlim = min(deadline - 6.0, time.process_time() + 8.0)
        cand = _lbfgs_block(best, all_idx, 200, tlim,
                            mode='width', tau=tau, T=None, lam=lam)
        r = R_of(cand)
        f1 = _frac_near_max(cand, 1e-2)
        width_results.append((tau, r, f1))
        print("  width tau=%.3f R=%.12f frac1%%=%.4f" % (tau, r, f1))
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r

    # ---- Finish with base's full tie polish + peak windows ----
    if time.process_time() < deadline - 6.0:
        pol = _lbfgs_block(best, all_idx, 200,
                           min(deadline - 4.0, time.process_time() + 6.0),
                           mode='tie')
        rp = R_of(pol)
        print("full tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.5, time.process_time() + 3.0),
                          mode='tie')
        r = R_of(ht)
        print("peak polish pad=%.2f R=%.12f" % (pad, r))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d, frac1%%=%.4f)"
          % (bestR, startR, best.size, _tie_count(best), _frac_near_max(best, 1e-2)))

    result = {"best": best}
    # If width ladder produced a genuinely different construction that didn't win, keep as alternative
    if width_results and bestR <= startR + 1e-14:
        # rebuild a width construction to offer as alternative
        cand = _lbfgs_block(_rescale(np.clip(np.asarray(start, dtype=float), 0, None)),
                            all_idx, 100, time.process_time() + 2.0,
                            mode='width', tau=0.99, T=None, lam=lam)
        result["alternative"] = cand
    return result

