def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    if c[-1] <= 0:
        return np.ones(n_new)
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _polish(cur, deadline, tag=""):
    """Geometric beta continuation + tie-aware finishing."""
    r = R_of(cur)
    best, bestR = cur, r
    for beta in (2.0, 5.0, 12.0, 30.0, 80.0):
        if time.process_time() > deadline - 1.0:
            break
        cand = _lbfgs_log(best, 200, deadline - 1.0, beta=beta)
        rr = R_of(cand)
        if rr > bestR:
            best, bestR = cand, rr
    if time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(best, 250, deadline - 1.0, tie=True)
        rr = R_of(cand)
        if rr > bestR:
            best, bestR = cand, rr
    if time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(best, 250, deadline - 1.0, beta=0.0)
        rr = R_of(cand)
        if rr > bestR:
            best, bestR = cand, rr
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    bestR = -1.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            best = _rescale(s)
            bestR = R_of(best)

    # If start already has lots of steps, use it as primary and just refine.
    # Otherwise, seed a ladder.

    # Phase 1: quick small-N seed to get an alternative construction
    alt = None
    altR = -1.0
    if time.process_time() < deadline - 20.0:
        N0 = 192
        x = np.linspace(0, 1, N0)
        seeds = [np.cos(np.pi * (x - 0.5)) ** 2 + 1e-3,
                 np.exp(-((x - 0.35) / 0.2) ** 2) + 1e-3,
                 np.minimum(x, 1 - x) + 1e-3,
                 0.5 + 0.5 * np.cos(2 * np.pi * x) + 1e-3]
        for s in seeds:
            if time.process_time() > deadline - 20.0:
                break
            h = _lbfgs_log(s, 250, deadline - 20.0, beta=0.0)
            h, r = _polish(h, deadline - 20.0)
            if r > altR:
                alt, altR = h, r
        # ladder up
        cur = alt
        for n_new in [384, 768, 1536, 3072, 6144]:
            if time.process_time() > deadline - 12.0:
                break
            cur = _prolong(cur, n_new)
            cur = _lbfgs_log(cur, 200, deadline - 12.0, beta=0.0)
            cur, r = _polish(cur, deadline - 12.0)
            alt, altR = cur, r
        print(f"alt ladder: R={altR:.6f} N={len(alt)}")

    # Phase 2: improve from start / best via prolong+polish, plus higher-res refinements
    if best is None:
        best, bestR = (alt, altR) if alt is not None else (np.ones(64), 0.0)

    # Alternate: from best, try doubling and 1.5x resolution
    cur = best
    attempts = 0
    while time.process_time() < deadline - 3.0 and attempts < 12:
        attempts += 1
        n = len(cur)
        for mult in (2, 1.5, 1.25):
            if time.process_time() > deadline - 3.0:
                break
            n_new = int(n * mult)
            if n_new > 400000 or n_new <= n:
                continue
            cand = _prolong(cur, n_new)
            cand = _lbfgs_log(cand, 200, deadline - 3.0, beta=0.0)
            cand, rr = _polish(cand, deadline - 3.0)
            if rr > bestR + 1e-9:
                best, bestR = cand, rr
                cur = best
                print(f"refine {mult}x: R={rr:.6f} N={n_new}")
                break
        else:
            # no improvement from growing; try re-optimizing at current size with tie
            cand = _lbfgs_log(cur, 300, deadline - 3.0, tie=True)
            cand, rr = _polish(cand, deadline - 3.0)
            if rr > bestR + 1e-9:
                best, bestR = cand, rr
                cur = best
                print(f"tie-reopt: R={rr:.6f} N={len(cur)}")
            else:
                break

    # Phase 3: if we still have time, re-run from start with full polish
    if start is not None and time.process_time() < deadline - 2.0:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            cand = _rescale(s)
            cand, rr = _polish(cand, deadline - 2.0)
            if rr > bestR + 1e-9:
                best, bestR = cand, rr
                print(f"start-polish: R={rr:.6f}")

    if best is None:
        best = np.ones(64)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(64)

    print(f"final R={R_of(best):.6f} N={len(best)}")
    if alt is not None and altR > bestR - 1e-6 and not np.array_equal(alt, best) and len(alt) != len(best):
        return {"best": best, "alternative": alt}
    return best

