    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    if c[-1] <= 0:
        return np.ones(n_new)
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _polish(cur, deadline, tag=""):
    """Geometric beta continuation + tie-aware finishing."""
    r = R_of(cur)
    best, bestR = cur, r
    for beta in (2.0, 5.0, 12.0, 30.0, 80.0):
        if time.process_time() > deadline - 1.0:
            break
        cand = _lbfgs_log(best, 200, deadline - 1.0, beta=beta)
        rr = R_of(cand)
        if rr > bestR:
            best, bestR = cand, rr
    if time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(best, 250, deadline - 1.0, tie=True)
        rr = R_of(cand)
        if rr > bestR:
            best, bestR = cand, rr
    if time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(best, 250, deadline - 1.0, beta=0.0)
        rr = R_of(cand)
        if rr > bestR:
            best, bestR = cand, rr
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    bestR = -1.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            best = _rescale(s)
            bestR = R_of(best)

    # If start already has lots of steps, use it as primary and just refine.
    # Otherwise, seed a ladder.

    # Phase 1: quick small-N seed to get an alternative construction
    alt = None
    altR = -1.0
    if time.process_time() < deadline - 20.0:
        N0 = 192
        x = np.linspace(0, 1, N0)
        seeds = [np.cos(np.pi * (x - 0.5)) ** 2 + 1e-3,
                 np.exp(-((x - 0.35) / 0.2) ** 2) + 1e-3,
                 np.minimum(x, 1 - x) + 1e-3,
                 0.5 + 0.5 * np.cos(2 * np.pi * x) + 1e-3]
        for s in seeds:
            if time.process_time() > deadline - 20.0:
                break
            h = _lbfgs_log(s, 250, deadline - 20.0, beta=0.0)
            h, r = _polish(h, deadline - 20.0)
            if r > altR:
                alt, altR = h, r
        # ladder up
        cur = alt
        for n_new in [384, 768, 1536, 3072, 6144]:
            if time.process_time() > deadline - 12.0:
                break
            cur = _prolong(cur, n_new)
            cur = _lbfgs_log(cur, 200, deadline - 12.0, beta=0.0)
            cur, r = _polish(cur, deadline - 12.0)
            alt, altR = cur, r
        print(f"alt ladder: R={altR:.6f} N={len(alt)}")

    # Phase 2: improve from start / best via prolong+polish, plus higher-res refinements
    if best is None:
        best, bestR = (alt, altR) if alt is not None else (np.ones(64), 0.0)

    # Alternate: from best, try doubling and 1.5x resolution
    cur = best
    attempts = 0
    while time.process_time() < deadline - 3.0 and attempts < 12:
        attempts += 1
        n = len(cur)
        for mult in (2, 1.5, 1.25):
            if time.process_time() > deadline - 3.0:
                break
            n_new = int(n * mult)
            if n_new > 400000 or n_new <= n:
                continue
            cand = _prolong(cur, n_new)
            cand = _lbfgs_log(cand, 200, deadline - 3.0, beta=0.0)
            cand, rr = _polish(cand, deadline - 3.0)
            if rr > bestR + 1e-9:
                best, bestR = cand, rr
                cur = best
                print(f"refine {mult}x: R={rr:.6f} N={n_new}")
                break
        else:
            # no improvement from growing; try re-optimizing at current size with tie
            cand = _lbfgs_log(cur, 300, deadline - 3.0, tie=True)
            cand, rr = _polish(cand, deadline - 3.0)
            if rr > bestR + 1e-9:
                best, bestR = cand, rr
                cur = best
                print(f"tie-reopt: R={rr:.6f} N={len(cur)}")
            else:
                break

    # Phase 3: if we still have time, re-run from start with full polish
    if start is not None and time.process_time() < deadline - 2.0:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            cand = _rescale(s)
            cand, rr = _polish(cand, deadline - 2.0)
            if rr > bestR + 1e-9:
                best, bestR = cand, rr
                print(f"start-polish: R={rr:.6f}")

    if best is None:
        best = np.ones(64)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(64)

    print(f"final R={R_of(best):.6f} N={len(best)}")
    if alt is not None and altR > bestR - 1e-6 and not np.array_equal(alt, best) and len(alt) != len(best):
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _upsample_lin(h):
    n = h.size
    h2 = np.zeros(2 * n)
    h2[0::2] = h
    right = np.concatenate((h[1:], [h[-1]]))
    h2[1::2] = 0.5 * (h + right)
    return h2


def _upsample_zero(h):
    n = h.size
    h2 = np.zeros(2 * n)
    h2[0::2] = h
    return h2


def _coarsen(h2):
    n = h2.size // 2
    return 0.5 * (h2[0:2 * n:2] + h2[1:2 * n:2])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_bestR = bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _consider(h, r, tag, is_alt=True):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if r > bestR + 1e-14:
            best, bestR, origin = h.copy(), r, tag
            print("%s NEW BEST R=%.9f" % (tag, bestR))
            return True
        if is_alt and r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r
        return False

    # ---- Phase 1: iterated upsample-polish-coarsen cycles ----
    reserve = 8.0
    cycles = 0
    max_cycles = 3
    while cycles < max_cycles and time.process_time() < deadline - reserve - 2.0:
        cycles += 1
        use_zero = (cycles == 2)
        if use_zero:
            h2 = _upsample_zero(best)
        else:
            h2 = _upsample_lin(best)
        h2 = _rescale(h2)
        r_up = R_of(h2)
        # (b) full-vector tie L-BFGS-B on h2, time-boxed to 6 s
        up_dl = min(deadline - reserve, time.process_time() + 6.0)
        ht = h2
        for beta in [1e6, 1e7]:
            if time.process_time() >= up_dl - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 250, up_dl - 0.3, beta=beta)
        r_fine = R_of(ht)
        # (c) coarsen back
        c = _rescale(_coarsen(ht))
        r_coarse = R_of(c)
        # (d) full-vector exact-R tie polish at original N, time-boxed to 4 s
        co_dl = min(deadline - reserve, time.process_time() + 4.0)
        ht2 = c
        for beta in [1e7, 0.0]:
            if time.process_time() >= co_dl - 0.5:
                break
            ht2 = _lbfgs_all_pos(ht2, 250, co_dl - 0.3, beta=beta)
        r_final = R_of(ht2)
        print("cycle %d %s: up=%.9f fine=%.9f coarse=%.9f final=%.9f" %
              (cycles, 'zero' if use_zero else 'lin',
               r_up, r_fine, r_coarse, r_final))
        if r_final > bestR + 1e-14:
            best, bestR, origin = ht2.copy(), r_final, 'upcycle%d' % cycles
            print("cycle %d ACCEPT R=%.9f" % (cycles, bestR))
        else:
            if r_fine > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r_fine
            if r_final > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r_final
            print("cycle %d REVERT R=%.9f (best %.9f)" %
                  (cycles, r_final, bestR))

    # ---- Phase 2: final full-N tie polish ----
    if time.process_time() < deadline - reserve + 2.0:
        fin_dl = min(deadline - 1.0, time.process_time() + 4.0)
        ht = best
        for beta in [1e6, 1e7]:
            if time.process_time() >= fin_dl - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 300, fin_dl - 0.3, beta=beta)
        _consider(ht, R_of(ht), 'final_tie')

    # ---- Phase 3: peak-window polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.12, 0.08]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            _consider(ht2, R_of(ht2), 'peak%d' % int(pad * 100))

    # ---- Phase 4: trailing beta=0 polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        _consider(ht, R_of(ht), 'trailing_b0')

    print("cycles=%d best_full=%.9f" % (cycles, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    """Smooth-max objective: log-sum-exp of knots instead of hard max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta is None:
        fg = _fun_grad_beta if False else None
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta is not None else None
    if fg is None:
        # fall back to a small beta
        fg = lambda hh: _fun_grad_beta(hh, 50.0)

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            return p, c
    return 1, h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    def accept(hh):
        nonlocal best, bestR
        hh = _rescale(hh)
        r = R_of(hh)
        if r > bestR + 1e-15:
            best, bestR = hh, r
            return True
        return False

    # Alternate: sharpen the LSE (increasing beta) on the full resolution,
    # then periodically re-collapse the near-tied peak into a true plateau.
    c_cur = c.copy()
    betas = [20.0, 50.0, 120.0, 300.0, 800.0, 2000.0]
    for beta in betas:
        if time.process_time() >= deadline - 2.0:
            break
        remaining = deadline - time.process_time()
        slice_end = min(time.process_time() + 0.55 * remaining, deadline - 1.5)
        h_full = np.repeat(c_cur, p)
        h_new = _lbfgs(h_full, np.arange(h_full.size), 500, slice_end, beta=beta)
        accept(h_new)
        c_cur = h_new.reshape(-1, p).mean(axis=1) if h_new.size % p == 0 else c_cur
        print("beta=%.0f R=%.9f" % (beta, bestR))

    # Final: hard-max tie polish at full resolution, then collapse.
    while time.process_time() < deadline - 1.0:
        h_full = np.repeat(c_cur, p)
        slice_end = min(deadline - 0.5, time.process_time() + 2.5)
        h_new = _lbfgs(h_full, np.arange(h_full.size), 400, slice_end, beta=5000.0)
        if not accept(h_new):
            break
        c_cur = h_new.reshape(-1, p).mean(axis=1) if h_new.size % p == 0 else c_cur

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- new: coordinate-wise / block coordinate ascent on the tie-plateau ----------

def _plateau_blocks(h, nblocks):
    """Partition the peak plateau (plus a margin) into nblocks contiguous blocks."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return [np.arange(h.size)]
    idx = np.flatnonzero(Lf >= 0.9 * mx)
    if idx.size == 0:
        return [np.arange(h.size)]
    lo = max(0, idx.min() - 32)
    hi = min(h.size - 1, idx.max() + 32)
    edges = np.linspace(lo, hi + 1, nblocks + 1).astype(int)
    return [np.arange(edges[i], edges[i + 1]) for i in range(nblocks)]


def _block_coord_ascent(h, deadline, nblocks=16, sweeps=3, iters=40):
    """Sweep over contiguous blocks of the peak region, optimizing each in turn."""
    for _ in range(sweeps):
        if time.process_time() >= deadline - 0.5:
            break
        blocks = _plateau_blocks(h, nblocks)
        improved = False
        for blk in blocks:
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_block(h, blk, iters, deadline - 0.3, beta=1e7)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
                improved = True
        if not improved:
            break
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: block-coordinate ascent on the peak plateau ----
    # The previous program only did full-buffer L-BFGS and peak-window ladders.
    # Here we do repeated sweeps over contiguous blocks of the plateau, giving
    # many small independent local optimizations that escape the flat tie region.
    phase1_end = t0 + budget_seconds * 0.55
    if time.process_time() < phase1_end - 3.0:
        hb = _block_coord_ascent(best, phase1_end - 1.0,
                                 nblocks=24, sweeps=4, iters=60)
        rb = R_of(hb)
        print("block ascent R=%.9f" % rb)
        if rb > bestR + 1e-15:
            best, bestR = hb.copy(), rb
            print("BLOCK ACCEPT R=%.9f" % bestR)

    # ---- Phase 2: peak ladder on the incumbent ----
    phase2_end = t0 + budget_seconds * 0.80
    if time.process_time() < phase2_end - 3.0:
        ht = _peak_ladder(best, phase2_end - 1.0,
                          pads=(0.08, 0.04, 0.02), iters=300, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("peak ladder ACCEPT R=%.9f" % bestR)

    # ---- Phase 3: another block sweep at higher resolution ----
    phase3_end = t0 + budget_seconds * 0.92
    if time.process_time() < phase3_end - 3.0:
        hb = _block_coord_ascent(best, phase3_end - 1.0,
                                 nblocks=40, sweeps=3, iters=50)
        rb = R_of(hb)
        print("block ascent 2 R=%.9f" % rb)
        if rb > bestR + 1e-15:
            best, bestR = hb.copy(), rb
            print("BLOCK2 ACCEPT R=%.9f" % bestR)

    # ---- Phase 4: final full-buffer tie optimization ----
    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 2.0:
        h_t = _lbfgs_block(best, np.arange(best.size), 400, fd - 0.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

