def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cap(h, cap, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    exc = np.maximum(Lf - cap, 0.0)
    gLf = -dq / num
    gLf += 2.0 * lam * exc / (cap * cap * Lf.size)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cap) \
        + lam * np.sum(exc * exc) / (cap * cap * Lf.size)
    return val, grad


def _fun_grad_cvar(h, q, a):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad_tie(h)
    v = np.quantile(Lf, q)
    band = Lf >= v
    nb = int(band.sum())
    if nb <= 0:
        return _fun_grad_tie(h)
    cv = float(Lf[band].mean())
    if cv <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    m = int(np.argmax(Lf))
    gLf[m] += (1.0 - a) / M
    gLf[band] += a / (nb * cv)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (1.0 - a) * np.log(M) + a * np.log(cv)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, cvar=None, cap=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if cap is not None:
        capv, lam = cap
        fg = (lambda hh: _fun_grad_cap(hh, capv, lam))
    elif cvar is not None:
        q, a = cvar
        fg = (lambda hh: _fun_grad_cvar(hh, q, a))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _near_max_count(h, tol=1e-6):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - tol)))


def _num_over_s2(h):
    s = h.sum()
    if s <= 0:
        return 0.0
    num, _, _ = _num_and_dq(h)
    return num / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.12f (N=%d)" % (bestR, N))

    alt_best = None
    altR = -1.0

    # ---- D1: L-infinity cap augmented-Lagrangian ladder ----
    Lf = _knots(best)
    M0 = Lf.max()
    cap = M0 * (1.0 + 1e-9)
    q0 = _num_over_s2(best)
    for lam in (1e2, 1e3, 1e4, 1e5, 1e6):
        if time.process_time() >= deadline - 12.0:
            break
        tlim = min(deadline - 12.0, time.process_time() + 3.0)
        cand = _lbfgs_block(best, np.arange(N), 150, tlim, cap=(cap, lam))
        r = R_of(cand)
        Lc = _knots(cand)
        mc = Lc.max()
        qc = _num_over_s2(cand)
        nk = _near_max_count(cand, 1e-6)
        rel_rise = (qc - q0) / q0 if q0 > 0 else 0.0
        rel_max = (mc - M0) / M0 if M0 > 0 else 0.0
        acc = r > bestR + 1e-15
        print("cap lam=%.0e R=%.12f near-max=%d dq=%.3e dM=%.3e %s"
              % (lam, r, nk, rel_rise, rel_max, "ACCEPT" if acc else "reject"))
        if acc:
            best, bestR = cand.copy(), r
            Lf = Lc
            M0 = Lf.max()
            cap = M0 * (1.0 + 1e-9)
            q0 = _num_over_s2(best)
            if r > altR:
                altR, alt_best = r, cand.copy()

    # ---- p2392 full tie polish ----
    if time.process_time() < deadline - 6.0:
        pol = _lbfgs_block(best, np.arange(N), 200,
                           min(deadline - 5.0, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        print("full tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        if rp > altR:
            altR, alt_best = rp, pol.copy()

    # ---- peak polishes ----
    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.3, time.process_time() + 1.5), tie=True)
        r = R_of(ht)
        print("peak polish pad=%.2f R=%.12f" % (pad, r))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > altR:
            altR, alt_best = r, ht.copy()

    # ---- use remaining time: repeat cap ladder + tie polish ----
    while time.process_time() < deadline - 4.0:
        Lf = _knots(best)
        M0 = Lf.max()
        cap = M0 * (1.0 + 1e-9)
        improved = False
        for lam in (1e3, 1e4, 1e5, 1e6):
            if time.process_time() >= deadline - 4.0:
                break
            tlim = min(deadline - 4.0, time.process_time() + 1.5)
            cand = _lbfgs_block(best, np.arange(N), 100, tlim, cap=(cap, lam))
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r
                Lf = _knots(best)
                M0 = Lf.max()
                cap = M0 * (1.0 + 1e-9)
                improved = True
                if r > altR:
                    altR, alt_best = r, cand.copy()
        if time.process_time() < deadline - 3.0:
            pol = _lbfgs_block(best, np.arange(N), 150,
                               min(deadline - 2.0, time.process_time() + 1.5), tie=True)
            rp = R_of(pol)
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp
                improved = True
                if rp > altR:
                    altR, alt_best = rp, pol.copy()
        if not improved:
            break

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _resample_mass(h, M, alpha):
    h = np.asarray(h, dtype=float)
    n = h.size
    H = np.concatenate(([0.0], np.cumsum(h)))
    edges = (np.arange(M + 1) + alpha) * (n / float(M))
    edges = np.clip(edges, 0.0, float(n))
    h2 = np.diff(np.interp(edges, np.arange(n + 1), H))
    s = h.sum()
    s2 = h2.sum()
    if s2 > 0:
        h2 = h2 * (s / s2)
    return np.clip(h2, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_bestR = bestR
    origin = 'start'
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    alt_bestR = -1.0

    def _consider(h, r, tag, is_alt=True):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if r > bestR + 1e-14:
            best, bestR, origin = h.copy(), r, tag
            print("%s NEW BEST R=%.9f" % (tag, bestR))
            return True
        if is_alt and r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r
        return False

    # ---- Phase 1: 3:2 mass-preserving resample lifts ----
    M = int(round(1.5 * N))
    alphas = [0.0, 1.0 / 3.0, 2.0 / 3.0]
    reserve = 6.0
    rounds = 0
    max_rounds = 2
    while rounds < max_rounds and time.process_time() < deadline - reserve - 4.0:
        rounds += 1
        any_accept = False
        for alpha in alphas:
            if time.process_time() >= deadline - reserve - 2.0:
                break
            h2 = _resample_mass(best, M, alpha)
            h2 = _rescale(h2)
            r_up = R_of(h2)
            # tie L-BFGS on the 1.5N grid, time-boxed
            up_dl = min(deadline - reserve, time.process_time() + 6.0)
            hb = h2
            for beta in [1e7, 0.0]:
                if time.process_time() >= up_dl - 0.5:
                    break
                hb = _lbfgs_block(hb, np.arange(M), 400, up_dl - 0.3, beta=beta)
            r_fine = R_of(hb)
            # downsample back to N
            hd = _rescale(_resample_mass(hb, N, 0.0))
            r_down = R_of(hd)
            print("3:2 alpha=%.3f up=%.9f fine=%.9f down=%.9f gap=%.2e" %
                  (alpha, r_up, r_fine, r_down, r_fine - r_down))
            if r_down > bestR + 1e-15:
                best, bestR, origin = hd.copy(), r_down, 'resample_a%.3f' % alpha
                print("3:2 alpha=%.3f accepted R=%.9f" % (alpha, bestR))
                any_accept = True
            else:
                if r_fine > alt_bestR:
                    alt_best, alt_bestR = hb.copy(), r_fine
        if not any_accept:
            break

    # ---- Phase 2: full tie polish ----
    if time.process_time() < deadline - reserve + 2.0:
        fin_dl = min(deadline - 1.0, time.process_time() + 4.0)
        ht = best
        for beta in [1e6, 1e7]:
            if time.process_time() >= fin_dl - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 300, fin_dl - 0.3, beta=beta)
        _consider(ht, R_of(ht), 'final_tie')

    # ---- Phase 3: peak-window polishes ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.12, 0.05]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            _consider(ht2, R_of(ht2), 'peak%d' % int(pad * 100))

    # ---- Phase 4: trailing beta=0 polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        _consider(ht, R_of(ht), 'trailing_b0')

    print("rounds=%d best_full=%.9f" % (rounds, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

