    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d, ties=%d)" % (bestR, N, _tie_count(best)))

    alt_best = None
    altR = -1.0

    # Strategy: smooth-max (beta) L-BFGS on full vector to escape the exact-tie
    # local optimum, then sharpen with exact-tie polish.
    betas = [8.0, 30.0, 120.0, 500.0]
    cur = best.copy()
    for beta in betas:
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 5.0)
        cur2 = _lbfgs_block(cur, np.arange(N), 150, tlim, beta=beta)
        r2 = R_of(cur2)
        print("  beta=%.0f R=%.12f" % (beta, r2))
        if r2 > altR:
            altR = r2
            alt_best = cur2.copy()
        if r2 > bestR + 1e-15:
            best, bestR = cur2.copy(), r2
        cur = cur2

    # Exact-tie full polish
    if time.process_time() < deadline - 3.0:
        pol = _lbfgs_block(best, np.arange(N), 300,
                           min(deadline - 2.0, time.process_time() + 8.0), tie=True)
        rp = R_of(pol)
        print("  full tie polish R=%.12f" % rp)
        if rp > altR:
            altR = rp
            alt_best = pol.copy()
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    # Peak-window tie polishes
    for pad, extra in ((0.10, 128), (0.05, 96), (0.03, 64)):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=extra)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 1.0, time.process_time() + 3.0), tie=True)
        r = R_of(ht)
        print("  win pad=%.2f R=%.12f" % (pad, r))
        if r > altR:
            altR = r
            alt_best = ht.copy()
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    # Small beta polish on the peak window
    if time.process_time() < deadline - 2.0:
        win = _peak_window(best, pad_frac=0.06, extra=96)
        ht = _lbfgs_block(best, win, 200,
                          min(deadline - 1.0, time.process_time() + 3.0), beta=200.0)
        r = R_of(ht)
        if r > altR:
            altR = r
            alt_best = ht.copy()
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

