def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-7))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.5, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _up_resample(h, N_big):
    n = h.size
    if n == N_big:
        return h.copy()
    x = np.linspace(0.0, 1.0, n)
    xb = np.linspace(0.0, 1.0, N_big)
    hb = np.interp(xb, x, h)
    return np.clip(hb, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: bandwidth-continuation on a soft-max (beta annealing) applied
    # to the *whole* support, interleaved with a grid-up step.  The key change
    # vs p0047 is that we polish the *entire* profile at each beta level (not
    # just the peak window), so global shape co-adapts with the flattening of
    # the max, and we anneal beta much more aggressively (1e2 -> 1e5) while
    # growing N modestly.  This reaches higher R because the peak plateau and
    # the tails are optimised jointly rather than in isolation.

    # Stage 1: beta-annealed full-support polish on current grid.
    for beta in (30.0, 100.0, 300.0, 1000.0, 3000.0, 10000.0):
        if time.process_time() >= deadline - 12.0:
            break
        h = _lbfgs_block(best, np.arange(best.size), 500, deadline, beta=beta)
        r = R_of(h)
        print("beta=%.0f R=%.7f" % (beta, r))
        if r > bestR + 1e-13:
            best, bestR = h, r
        elif r > bestR - 5e-4:
            best = h  # allow small dip for continued smoothing

    # Stage 2: modest grid growth with peak-window + full-support polish.
    N0 = best.size
    Ncap = int(min(1000000, max(N0, int(N0 * 1.6))))
    cur = best.copy()
    Nt = N0
    while Nt < Ncap and time.process_time() < deadline - 12.0:
        Nt = int(min(Ncap, max(Nt + 512, int(Nt * 1.25))))
        hu = _up_resample(cur, Nt)
        hu = _rescale(hu)
        # full-support tie polish (locks the plateau)
        hu = _lbfgs_block(hu, np.arange(Nt), 400, deadline, tie=True)
        # peak-window beta polish
        win = _peak_window(hu, tol=0.999, pad_frac=0.5, extra=128)
        hu = _lbfgs_block(hu, win, 300, deadline, beta=300.0)
        hu = _lbfgs_block(hu, win, 300, deadline, beta=3000.0)
        # final sharp full-support
        hu = _lbfgs_block(hu, np.arange(Nt), 300, deadline)
        r = R_of(hu)
        print("lift N=%d R=%.7f" % (Nt, r))
        if r > bestR + 1e-13:
            best, bestR = hu, r
            cur = hu
        else:
            cur = hu if r > bestR - 3e-3 else cur

    # Stage 3: final sharp polish, tie then argmax.
    for _ in range(4):
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs_block(best, np.arange(best.size), 800, deadline, tie=True)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final tie R=%.7f" % bestR)
        h = _lbfgs_block(best, np.arange(best.size), 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final sharp R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if bestR > start_bestR - 1e-6:
        return {"best": start_best, "alternative": best if bestR > 0 else None}
    return {"best": start_best, "alternative": best if bestR > 0 else None}

