    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        st = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[st:st + L] *= fac
    return c2


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _trust_newton(c0, deadline, method='trust-ncg', init_radius=1e-3):
    if time.process_time() >= deadline - 0.5:
        return c0
    c0 = np.clip(c0, 1e-30, None)
    v0 = np.sqrt(c0)

    def fg(v):
        c = v * v
        val, g = _fun_grad_tie(c)
        return val, 2.0 * v * g

    def hessp(v, w):
        eps = 1e-6 * (1.0 + np.linalg.norm(v))
        vp = v + eps * w
        vm = v - eps * w
        _, gp = _fun_grad_tie(vp * vp)
        _, gm = _fun_grad_tie(vm * vm)
        return (2.0 * vp * gp - 2.0 * vm * gm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg, v0, jac=True, method=method, hessp=hessp,
                       callback=cb,
                       options={'maxiter': 300,
                                'initial_trust_radius': init_radius,
                                'max_trust_radius': 0.5,
                                'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None or not np.all(np.isfinite(res.x)):
        return c0
    return _rescale(res.x * res.x)


def _coarse(c_in, m):
    n = c_in.size
    if m == n:
        return c_in.copy()
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 * (n / m)
    xi = np.arange(n, dtype=float) + 0.5
    return np.interp(x, xi, c_in)


def _prolong(c_coarse, m_out):
    m = c_coarse.size
    if m_out == m:
        return c_coarse.copy()
    x = np.linspace(0.0, m, m_out, endpoint=False) + 0.5 * (m_out / m)
    xi = np.arange(m, dtype=float) + 0.5
    return np.interp(x, xi, c_coarse)


def _polish_c(c, p, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return c, R_of(np.repeat(c, p))
    h = _rescale(np.repeat(c, p))
    h2 = _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=tie)
    c2 = h2.reshape(-1, p).mean(axis=1)
    return c2, R_of(np.repeat(c2, p))


def _vcycle(best, bestR, p, c, deadline, levels):
    n_c = c.size
    coarse_list = [(n_c, c.copy())]
    cur = c
    for m in levels[1:]:
        cur = _coarse(cur, m)
        coarse_list.append((m, cur.copy()))
    m, cc = coarse_list[-1]
    cc, r = _polish_c(cc, p, 80, min(deadline, time.process_time() + 3.0))
    coarse_list[-1] = (m, cc)
    if r > bestR + 1e-15:
        best = _rescale(np.repeat(cc, p)); bestR = r
    for i in range(len(coarse_list) - 2, -1, -1):
        m_out, _ = coarse_list[i]
        cc = _prolong(cc, m_out)
        cc, r = _polish_c(cc, p, 100,
                          min(deadline, time.process_time() + 4.0))
        coarse_list[i] = (m_out, cc)
        if r > bestR + 1e-15:
            best = _rescale(np.repeat(cc, p)); bestR = r
    return best, bestR, cc


def _block_R(w, c, p):
    return R_of(np.repeat(c, p) * np.repeat(w, c.size))


def _opt_block_w(c, p, w0, deadline, maxiter=200, sym=False):
    if time.process_time() >= deadline - 0.3:
        return w0, _block_R(w0, c, p)
    n_c = c.size
    hbase = np.repeat(c, p)
    blk = np.repeat(np.arange(p), n_c)
    if sym:
        half = (p + 1) // 2
        fmap = np.array([k if k < half else p - 1 - k for k in range(p)])
        nfree = half
    else:
        fmap = None
        nfree = p

    def expand(x):
        w = np.exp(x)
        return w[fmap] if sym else w

    def f(x):
        w = expand(x)
        h = hbase * np.repeat(w, n_c)
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(nfree)
        num, dq, Lf = _num_and_dq(h)
        mx = Lf.max()
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        gh = _backprop(gLf, h) + 2.0 / s
        gw_full = np.bincount(blk, weights=gh * h, minlength=p)
        if sym:
            gw = np.zeros(half)
            for k in range(p):
                gw[fmap[k]] += gw_full[k]
        else:
            gw = gw_full
        return -np.log(num) + 2.0 * np.log(s) + np.log(mx), gw

    x0 = np.log(np.clip(w0[:nfree] if sym else w0, 1e-12, None))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return w0, _block_R(w0, c, p)
    if res is None or not np.all(np.isfinite(res.x)):
        return w0, _block_R(w0, c, p)
    w = expand(res.x)
    return w, _block_R(w, c, p)


def _direct_block_h(c, p, deadline):
    """Directly optimize the full h (block-structured) with tie-aware L-BFGS."""
    h0 = np.repeat(c, p)
    h = _lbfgs_block(h0, np.arange(h.size), 200, deadline, tie=True)
    return h, R_of(h)


def _sharpen_toward_ties(h, deadline, iters=6):
    """Use increasing beta in soft-max to push toward multiple ties at peak."""
    cur = h
    curR = R_of(cur)
    win = np.arange(h.size) if h.size <= 6000 else _peak_window(
        h, tol=0.999, pad_frac=0.5, extra=512)
    for beta in (1e3, 1e5, 1e6, 1e7, 1e8):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_block(cur, win, 150,
                          min(deadline - 0.3, time.process_time() + 4.0),
                          beta=beta)
        r = R_of(ht)
        if r > curR + 1e-15:
            cur, curR = ht, r
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- Phase S: direct full-resolution tie-aware polish ----
    s_end = t0 + (deadline - t0) * 0.30 + t0
    if time.process_time() < s_end - 1.0:
        for tag, h0 in (("full", best), ("repeat", np.repeat(c, p))):
            if time.process_time() >= s_end - 0.8:
                break
            win = _peak_window(h0, tol=0.9995, pad_frac=0.15, extra=512)
            ht = _lbfgs_block(h0, win, 400,
                              min(s_end - 0.3, time.process_time() + 6.0),
                              tie=True)
            r = R_of(ht)
            print("S %s R=%.9f" % (tag, r))
            if r > bestR + 1e-15:
                best, bestR = ht, r

    # ---- Phase H22: per-block multiplier optimization ----
    h22_end = t0 + (deadline - t0) * 0.55 + t0
    if p > 1 and c.size >= 4 and time.process_time() < h22_end - 2.0:
        w_best = np.ones(p)
        wR = _block_R(w_best, c, p)
        k = np.arange(p, dtype=float)
        starts = [np.ones(p)]
        for a in (0.1, 0.3, 0.6):
            starts.append(1.0 + a * np.cos(np.pi * k / (p - 1)))
        for i, w0 in enumerate(starts):
            if time.process_time() >= h22_end - 1.0:
                break
            w0 = np.clip(w0, 1e-6, None)
            w, r = _opt_block_w(c, p, w0,
                                min(h22_end - 0.5, time.process_time() + 3.0))
            print("H22 %d wR=%.9f" % (i, r))
            if r > wR + 1e-15:
                w_best, wR = w, r
        if time.process_time() < h22_end - 1.0:
            w, r = _opt_block_w(c, p, w_best,
                                min(h22_end - 0.5, time.process_time() + 3.0),
                                sym=True)
            print("H22 sym wR=%.9f" % r)
            if r > wR + 1e-15:
                w_best, wR = w, r
        if wR > bestR + 1e-15:
            h_new = _rescale(np.repeat(c, p) * np.repeat(w_best, c.size))
            rn = R_of(h_new)
            if rn > bestR + 1e-15:
                best, bestR = h_new, rn
                print("H22 ACCEPT R=%.9f" % bestR)

    # ---- Phase V: multi-resolution V-cycles ----
    v_end = t0 + (deadline - t0) * 0.72 + t0
    if p > 1 and c.size >= 8 and time.process_time() < v_end - 3.0:
        n_c = c.size
        levels = [n_c]
        m = n_c
        while len(levels) < 3 and m > 8:
            m = max(8, m // 3)
            if m >= levels[-1]:
                break
            levels.append(m)
        cycle = 0
        while time.process_time() < v_end - 3.0:
            cycle += 1
            best, bestR, c = _vcycle(best, bestR, p, c, v_end, levels)
            print("V cycle=%d bestR=%.9f" % (cycle, bestR))
            if cycle >= 3 and time.process_time() > v_end - 8.0:
                break

    # ---- Phase C: trust-region Newton on residual ----
    d_end = t0 + (deadline - t0) * 0.85 + t0
    if time.process_time() < d_end - 1.5:
        n = min(3072, best.size)
        if best.size % n == 0:
            c_now = best.reshape(-1, best.size // n).mean(axis=1)
        else:
            c_now = np.interp(np.linspace(0, best.size - 1, n),
                              np.arange(best.size), best)
        c_now = _rescale(np.clip(c_now, 1e-30, None))
        cR0 = R_of(c_now)
        c_new = _trust_newton(c_now, d_end, 'trust-ncg', 1e-3)
        cRn = R_of(c_new)
        if cRn <= cR0 + 1e-15 and time.process_time() < d_end - 1.0:
            c_new2 = _trust_newton(c_now, d_end, 'trust-krylov', 1e-2)
            if R_of(c_new2) > cRn:
                c_new, cRn = c_new2, R_of(c_new2)
        print("Newton cR=%.9f (was %.9f)" % (cRn, cR0))
        if cRn > cR0 + 1e-15:
            if best.size % c_new.size == 0:
                full2 = np.repeat(c_new, best.size // c_new.size)
            else:
                full2 = np.interp(np.linspace(0, c_new.size - 1, best.size),
                                  np.arange(c_new.size), c_new)
            full2 = _rescale(full2)
            rf = R_of(full2)
            if rf > bestR + 1e-15:
                best, bestR = full2, rf
                print("Newton ACCEPT R=%.9f" % bestR)

    # ---- Phase E: soft-max sharpening + final polish ----
    if time.process_time() < deadline - 2.0:
        best, bestR = _sharpen_toward_ties(
            best, min(deadline - 1.0, time.process_time() + 8.0))
        print("sharpen R=%.9f" % bestR)

    for pad in (0.06, 0.03, 0.015, 0.008):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e8, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= deadline - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(deadline - 0.5, time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht, r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, beta=1e7):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _refine_at_N(cur, curR, deadline, betas, tag=""):
    while time.process_time() < deadline - 3.0:
        hb = _lbfgs_log(cur, 250, deadline)
        rb = R_of(hb)
        if rb > curR + 1e-13:
            cur, curR = hb, rb
            print("    %slbfgs R=%.7f (N=%d)" % (tag, curR, cur.size))
        for beta in betas:
            if time.process_time() >= deadline - 4.0:
                break
            hb = _lbfgs_log(cur, 120, deadline, beta=beta)
            hs = _lbfgs_log(hb, 5, deadline)
            rs = R_of(hs)
            hp = _peak_ladder(hs, min(deadline, time.process_time() + 6.0))
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 1e-13:
                cur, curR = cand, rc
                print("    %sbeta=%.0e R=%.7f (N=%d)" % (tag, beta, curR, cur.size))
        if time.process_time() < deadline - 3.0:
            hp = _peak_ladder(cur, min(deadline, time.process_time() + 5.0),
                              pads=(0.03, 0.02))
            rp = R_of(hp)
            if rp > curR + 1e-13:
                cur, curR = hp, rp
                print("    %speak R=%.7f (N=%d)" % (tag, curR, cur.size))
    return cur, curR


def _smooth_extend(h, factor):
    """Resample h onto a finer grid by linear interpolation (widening support)."""
    n = h.size
    m = int(round(n * factor))
    x = np.linspace(0.0, 1.0, n)
    xm = np.linspace(0.0, 1.0, m)
    return np.interp(xm, x, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(987654321)

    best, bestR = None, 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    betas = (1e4, 1e5, 1e6, 1e7, 1e8)

    # Phase 1: refine at current N
    cur, curR = best.copy(), bestR
    cur, curR = _refine_at_N(cur, curR, t0 + budget_seconds * 0.50, betas, tag="N0 ")
    if curR > bestR + 1e-13:
        best, bestR = cur.copy(), curR

    # Phase 2: try both refine-at-2N (repeat) and smoothing-interp extension
    if time.process_time() < deadline - 8.0:
        # Option A: repeat (existing approach)
        hA = _rescale(np.repeat(best, 2))
        curA, curAR = _refine_at_N(hA, R_of(hA),
                                   min(deadline, time.process_time() + budget_seconds * 0.20),
                                   betas, tag="N2rep ")
        if curAR > bestR + 1e-12:
            best, bestR = curA.copy(), curAR
            print("  -> rep won: R=%.7f" % bestR)

    if time.process_time() < deadline - 6.0:
        # Option B: linear-interp smoothing extension (new idea: widen support smoothly)
        hB = _rescale(_smooth_extend(best, 1.5))
        curB, curBR = _refine_at_N(hB, R_of(hB),
                                   min(deadline, time.process_time() + budget_seconds * 0.20),
                                   betas, tag="Nsmooth ")
        if curBR > bestR + 1e-12:
            best, bestR = curB.copy(), curBR
            print("  -> smooth won: R=%.7f" % bestR)

    # Phase 3: aggressive peak-focused polish with varied beta
    if time.process_time() < deadline - 2.0:
        for beta in (1e5, 1e6, 1e7, 1e8):
            if time.process_time() >= deadline - 2.0:
                break
            hp = _peak_ladder(best, min(deadline, time.process_time() + 4.0),
                              pads=(0.05, 0.03, 0.02, 0.015), iters=300, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  peak b=%.0e R=%.7f" % (beta, bestR))

    # Phase 4: final full lbfgs
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    return _lbfgs_block(h, np.arange(h.size), maxiter, deadline, beta=beta)


def _peak_window(h, tol, pad_frac, extra):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _stats_line(tag, h, r):
    pos = h > 0
    mean_pos = h[pos].mean() if pos.any() else 0.0
    mx = h.max() if h.size else 0.0
    ratio = mx / mean_pos if mean_pos > 0 else 0.0
    print("%s: N=%d zeros=%.1f%% max/mean=%.2f R=%.7f" %
          (tag, h.size, 100.0 * np.mean(h <= 0), ratio, r))


def _polish(h, deadline):
    """Aggressive polish: all-pos LBFGS with beta heating, then peak-window blocks."""
    best = _rescale(np.clip(h, 0, None))
    bestR = R_of(best)
    if best.sum() <= 0:
        return best, bestR

    # beta heating schedule on all-pos
    for beta in (0.0, 8.0, 32.0, 128.0, 512.0, 0.0):
        if time.process_time() >= deadline - 0.5:
            break
        hs = _seed_zeros(best)
        ht = _lbfgs_all_pos(hs, 400, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    # peak-window refinements
    for frac, extra in ((0.10, 128), (0.25, 256), (0.50, 512)):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, 0.9995, frac, extra)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    if time.process_time() < deadline - 0.5:
        hs = _seed_zeros(best)
        ht = _lbfgs_all_pos(hs, 500, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    return best, bestR


def _thin_runs(h_orig, h_fine, frac):
    h_orig = np.clip(np.asarray(h_orig, dtype=float), 0, None)
    out = np.zeros_like(h_fine)
    n_fine = h_fine.size
    pos = h_orig > 0
    n = h_orig.size
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            k = j - i + 1
            mass = h_orig[i:j + 1].sum()
            m = max(1, int(np.ceil(k * frac)))
            lo = 2 * i
            hi = 2 * j + 1
            center = (lo + hi) // 2
            a = center - m // 2
            b = a + m - 1
            if a < 0:
                a = 0; b = m - 1
            if b >= n_fine:
                b = n_fine - 1; a = b - m + 1
            if a < 0:
                a = 0
            width = b - a + 1
            if width > 0:
                out[a:b + 1] += mass / width
            i = j + 1
        else:
            i += 1
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR

    # Branch 1: aggressive polish of start directly.
    now = time.process_time()
    reserve = 0.55 * (deadline - now)
    polish_deadline = deadline - reserve
    hp, rp = _polish(best, polish_deadline)
    print("polish(start) R=%.7f" % rp)
    if rp > bestR + 1e-14:
        best, bestR = hp.copy(), rp

    # Branch 2: upsample x2, thin to ~0.5 then polish; this is the "different line".
    alt_cand = None
    altR = -1.0
    if time.process_time() < deadline - 1.0:
        h_orig = start_best.copy()
        hA = np.empty(2 * h_orig.size); hA[0::2] = h_orig; hA[1::2] = h_orig
        rA = R_of(hA)
        print("upsample2 R=%.7f N=%d" % (rA, hA.size))
        # try a few thinning fractions; pick best raw, then polish
        cands = []
        for frac in (0.5, 0.6, 0.4, 0.7):
            hT = _thin_runs(h_orig, hA, frac)
            cands.append((R_of(hT), hT, frac))
        cands.append((rA, hA, -1.0))
        rawR, hraw, frac = max(cands, key=lambda z: z[0])
        print("best raw thin frac=%.2f R=%.7f" % (frac, rawR))
        hpp, rpp = _polish(hraw, deadline - 0.3)
        print("polish(thin) R=%.7f" % rpp)
        alt_cand, altR = hpp.copy(), rpp
        if rpp > bestR + 1e-14:
            best, bestR = hpp.copy(), rpp

    # Final aggressive polish of best if time remains.
    if time.process_time() < deadline - 0.5:
        hp, rp = _polish(best, deadline - 0.2)
        if rp > bestR + 1e-14:
            best, bestR = hp.copy(), rp
        print("final polish R=%.7f" % bestR)

    _stats_line("final", best, bestR)

    if bestR >= start_bestR - 1e-13:
        if alt_cand is not None and altR > -1.0:
            return {"best": best, "alternative": alt_cand}
        return best
    else:
        if alt_cand is not None and altR > -1.0:
            return {"best": start_best, "alternative": alt_cand}
        return start_best

