        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            k = j - i + 1
            mass = h_orig[i:j + 1].sum()
            m = max(1, int(np.ceil(k * frac)))
            lo = 2 * i
            hi = 2 * j + 1
            center = (lo + hi) // 2
            a = center - m // 2
            b = a + m - 1
            if a < 0:
                a = 0; b = m - 1
            if b >= n_fine:
                b = n_fine - 1; a = b - m + 1
            if a < 0:
                a = 0
            width = b - a + 1
            if width > 0:
                out[a:b + 1] += mass / width
            i = j + 1
        else:
            i += 1
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR

    # Branch 1: aggressive polish of start directly.
    now = time.process_time()
    reserve = 0.55 * (deadline - now)
    polish_deadline = deadline - reserve
    hp, rp = _polish(best, polish_deadline)
    print("polish(start) R=%.7f" % rp)
    if rp > bestR + 1e-14:
        best, bestR = hp.copy(), rp

    # Branch 2: upsample x2, thin to ~0.5 then polish; this is the "different line".
    alt_cand = None
    altR = -1.0
    if time.process_time() < deadline - 1.0:
        h_orig = start_best.copy()
        hA = np.empty(2 * h_orig.size); hA[0::2] = h_orig; hA[1::2] = h_orig
        rA = R_of(hA)
        print("upsample2 R=%.7f N=%d" % (rA, hA.size))
        # try a few thinning fractions; pick best raw, then polish
        cands = []
        for frac in (0.5, 0.6, 0.4, 0.7):
            hT = _thin_runs(h_orig, hA, frac)
            cands.append((R_of(hT), hT, frac))
        cands.append((rA, hA, -1.0))
        rawR, hraw, frac = max(cands, key=lambda z: z[0])
        print("best raw thin frac=%.2f R=%.7f" % (frac, rawR))
        hpp, rpp = _polish(hraw, deadline - 0.3)
        print("polish(thin) R=%.7f" % rpp)
        alt_cand, altR = hpp.copy(), rpp
        if rpp > bestR + 1e-14:
            best, bestR = hpp.copy(), rpp

    # Final aggressive polish of best if time remains.
    if time.process_time() < deadline - 0.5:
        hp, rp = _polish(best, deadline - 0.2)
        if rp > bestR + 1e-14:
            best, bestR = hp.copy(), rp
        print("final polish R=%.7f" % bestR)

    _stats_line("final", best, bestR)

    if bestR >= start_bestR - 1e-13:
        if alt_cand is not None and altR > -1.0:
            return {"best": best, "alternative": alt_cand}
        return best
    else:
        if alt_cand is not None and altR > -1.0:
            return {"best": start_best, "alternative": alt_cand}
        return start_best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta_pen(h, beta, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm

    S = Lf >= tau * mx
    pen = 0.0
    if np.any(S):
        vals = Lf[S]
        mu = vals.mean()
        var = np.mean((vals - mu) ** 2)
        nS = vals.size
        dvar_dL = np.zeros_like(Lf)
        dvar_dL[S] = (2.0 / nS) * (vals - mu)
        pen = kappa * var / (mx * mx)
        gLf += kappa * dvar_dL / (mx * mx)
        idx = np.flatnonzero(Lf >= (1.0 - 1e-12) * mx)
        wm = 1.0 / idx.size
        gLf[idx] += (-2.0 * kappa * var / (mx * mx * mx)) * wm

    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tau=0.9, kappa=0.0,
                 tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta_pen(hh, beta, tau, kappa))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _max_mean(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(mx / Lf.mean())


def _stats(h):
    return (_frac_near_max(h, 1e-3), _frac_near_max(h, 1e-2),
            _frac_near_max(h, 5e-2), _max_mean(h))


def _report(tag, h, r):
    f01, f1, f5, mm = _stats(h)
    zf = float(np.mean(h <= 0))
    print("%s R=%.12f nm 0.1/1/5%%=%.4f/%.4f/%.4f mm=%.2f zf=%.3f"
          % (tag, r, f01, f1, f5, mm, zf))


def _refine_ties(h, deadline, rounds=6):
    """Iteratively symmetrize near-tied peak knots to raise the true R.

    The tie-averaged gradient treats all near-max knots equally, but the true
    R is governed by the single global max.  After each L-BFGS polish we detect
    the cluster of near-max knots and apply a small direct correction that
    pulls the highest knot down and lifts the near-max ones, which is very
    cheap and tends to raise R slightly (removing tiny max-deficit)."""
    h = _rescale(h)
    best = h.copy()
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        # polish all free with tie gradient
        h2 = _lbfgs_block(h, np.arange(h.size), 60,
                          min(deadline - 0.4, time.process_time() + 2.0),
                          tie=True)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
        h = h2
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    _report("before", best, bestR)

    alt_best = None
    altR = -1.0

    Nfull = best.size
    allidx = np.arange(Nfull)

    h_cur = best.copy()
    curR = bestR

    # ---- (1) flat-top ladder: beta fixed 1e6, then sharpening pass ----
    ladder = [(0.80, 300.0), (0.70, 1000.0), (0.60, 3000.0),
              (0.50, 3000.0), (0.70, 300.0)]
    for (tau, kappa) in ladder:
        if time.process_time() >= deadline - 12.0:
            break
        h_new = _lbfgs_block(
            h_cur, allidx, 200,
            min(deadline - 11.0, time.process_time() + 6.0),
            beta=1e6, tau=tau, kappa=kappa)
        r = R_of(h_new)
        _report("flat tau=%.2f kap=%.0f" % (tau, kappa), h_new, r)
        if r > curR + 1e-15:
            h_cur, curR = h_new, r
        if time.process_time() < deadline - 10.0:
            h_sh = _lbfgs_block(
                h_cur, allidx, 100,
                min(deadline - 9.0, time.process_time() + 3.0),
                beta=1e8, tau=tau, kappa=kappa, tie=True)
            rs = R_of(h_sh)
            _report("  sharp b=1e8", h_sh, rs)
            if rs > curR + 1e-15:
                h_cur, curR = h_sh, rs
        if curR > bestR + 1e-15:
            best, bestR = h_cur.copy(), curR

    if curR > altR:
        altR = curR
        alt_best = h_cur.copy()

    # ---- (2) tie polish with repeated tie-refinement ----
    if time.process_time() < deadline - 6.0:
        h_ref, r_ref = _refine_ties(
            h_cur, min(deadline - 5.0, time.process_time() + 8.0), rounds=8)
        _report("tie refine", h_ref, r_ref)
        if r_ref > curR + 1e-16:
            h_cur, curR = h_ref, r_ref
        # peak-window tie polish
        for pad in (0.05, 0.03, 0.02):
            if time.process_time() < deadline - 5.0:
                win = _peak_window(h_cur, pad_frac=pad, extra=128)
                ht = _lbfgs_block(
                    h_cur, win, 100,
                    min(deadline - 4.0, time.process_time() + 2.0), tie=True)
                rt = R_of(ht)
                _report("peak pad=%.2f" % pad, ht, rt)
                if rt > curR + 1e-16:
                    h_cur, curR = ht, rt
        if curR > bestR + 1e-15:
            best, bestR = h_cur.copy(), curR
        if curR > altR:
            altR = curR
            alt_best = h_cur.copy()

    # ---- (3) mass-preserving 2x lift to N=65536 ----
    if time.process_time() < deadline - 15.0:
        h2 = np.repeat(h_cur, 2)
        k = np.array([0.25, 0.5, 0.25])
        h2 = np.convolve(h2, k, mode='same')
        h2 = _rescale(h2)
        r2 = R_of(h2)
        _report("lift x2", h2, r2)
        if r2 > curR + 1e-15:
            h_cur, curR = h2, r2
        idx2 = np.arange(h_cur.size)
        h_l = _lbfgs_block(
            h_cur, idx2, 100,
            min(deadline - 13.0, time.process_time() + 5.0),
            beta=1e8, tau=0.7, kappa=1000.0, tie=True)
        rl = R_of(h_l)
        _report("lift sharp", h_l, rl)
        if rl > curR + 1e-15:
            h_cur, curR = h_l, rl
        if time.process_time() < deadline - 8.0:
            h_t, r_t = _refine_ties(
                h_cur, min(deadline - 7.0, time.process_time() + 5.0), rounds=6)
            _report("lift tie refine", h_t, r_t)
            if r_t > curR + 1e-16:
                h_cur, curR = h_t, r_t
        if curR > bestR + 1e-15:
            best, bestR = h_cur.copy(), curR
        if curR > altR:
            altR = curR
            alt_best = h_cur.copy()

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    _report("after", best, bestR)
    print("final R=%.12f (start %.12f, N=%d, ties=%d, mm=%.2f)"
          % (bestR, startR, best.size, _tie_count(best), _max_mean(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-15:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

