        else:
            free = _peak_window(best, tol=0.99, pad_frac=0.4, extra=256)
            tag = "peak"

        # single-argmax step, short slice
        tlim = min(deadline - 1.0, time.process_time() + 0.6)
        cand = _lbfgs_block(best, free, 200, tlim, argmax=True)
        r_arg = R_of(cand)

        # tie polish on all cells, short slice
        tlim2 = min(deadline - 0.5, time.process_time() + 0.6)
        pol = _lbfgs_block(cand, np.arange(N), 150, tlim2, tie=True)
        r_pol = R_of(pol)

        if r_pol > bestR + 1e-15:
            best, bestR = pol.copy(), r_pol
            last_gain_iter = it
            print("it=%d %s m=%d drift=%+d argmaxR=%.12f tieR=%.12f ACCEPT"
                  % (it, tag, m, drift, r_arg, r_pol))
        else:
            print("it=%d %s m=%d drift=%+d argmaxR=%.12f tieR=%.12f reject"
                  % (it, tag, m, drift, r_arg, r_pol))

        if r_pol > altR:
            altR, alt_best = r_pol, pol.copy()

        # if no gain for a long time, try a peak-only argmax push
        if it - last_gain_iter >= 6:
            win = _peak_window(best, tol=0.999, pad_frac=0.1, extra=64)
            tlim3 = min(deadline - 0.4, time.process_time() + 0.5)
            cand2 = _lbfgs_block(best, win, 150, tlim3, argmax=True)
            r2 = R_of(cand2)
            if r2 > bestR + 1e-15:
                best, bestR = cand2.copy(), r2
                last_gain_iter = it
                print("  peak-push R=%.12f ACCEPT" % r2)
            if r2 > altR:
                altR, alt_best = r2, cand2.copy()

    # final tie polish
    if time.process_time() < deadline - 0.3:
        pol = _lbfgs_block(best, np.arange(N), 200,
                           min(deadline - 0.2, time.process_time() + 1.0), tie=True)
        rp = R_of(pol)
        print("final tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        if rp > altR:
            altR, alt_best = rp, pol.copy()

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _upsample_lin(h, k):
    n = h.size
    if k <= 1:
        return h.copy()
    x = np.linspace(0.0, n - 1.0, n * k)
    out = np.interp(x, np.arange(n, dtype=float), h)
    return np.clip(out, 0.0, None)


def _upsample_fft(h, k):
    """Band-limited interpolation (Fourier) of the heights, then clip."""
    n = h.size
    if k <= 1:
        return h.copy()
    m = n * k
    H = np.fft.rfft(h)
    out = np.fft.irfft(H, m) * (m / n)
    # resample onto same support endpoints: shift/scale so integral matches
    s_in = h.sum()
    s_out = out.sum()
    if s_out > 0:
        out *= s_in / s_out
    return np.clip(out, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    rng = np.random.default_rng(20240607)

    # ---- Phase 1: peak-window polish on the coarse grid ----
    p1_end = t0 + budget_seconds * 0.22
    if time.process_time() < p1_end - 2.0:
        for pad in (0.12, 0.07, 0.04):
            if time.process_time() >= p1_end - 1.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 300,
                              min(p1_end - 1.0, time.process_time() + 6.0),
                              beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
            ht = _lbfgs_block(best, win, 300,
                              min(p1_end - 1.0, time.process_time() + 6.0),
                              tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("phase1 R=%.9f" % bestR)

    # ---- Phase 2: mixed-lift refinement (new: lin + FFT upsampling) ----
    p2_end = t0 + budget_seconds * 0.60
    k_choices = (3, 2, 2)
    for k in k_choices:
        if time.process_time() >= p2_end - 3.0:
            break
        for ups in (_upsample_lin, _upsample_fft):
            if time.process_time() >= p2_end - 2.5:
                break
            hu = ups(best, k)
            if hu.size > 900000:
                break
            for beta in (1e5, 1e6, 0.0):
                if time.process_time() >= p2_end - 2.0:
                    break
                ht = _lbfgs_block(hu, np.arange(hu.size), 150,
                                  min(p2_end - 1.0,
                                      time.process_time() + 6.0),
                                  beta=beta, tie=(beta == 0.0))
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r
                    hu = ht
            print("  lift k=%d %s R=%.9f N=%d"
                  % (k, ups.__name__, bestR, best.size))

    # ---- Phase 3: value-band polish at fine resolution ----
    p3_end = t0 + budget_seconds * 0.88
    band_edges = [(0.0, 0.05), (0.05, 0.20), (0.20, 0.50),
                  (0.50, 0.80), (0.80, 0.95), (0.95, 1.001)]
    cyc = 0
    while time.process_time() < p3_end - 2.0:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        order = rng.permutation(len(band_edges))
        gains = []
        for bi in order:
            if time.process_time() >= p3_end - 1.5:
                break
            lo, hi = band_edges[bi]
            lo *= M; hi *= M
            sel = np.flatnonzero((best > 0) & (v >= lo) & (v < hi))
            if sel.size == 0:
                gains.append(0.0)
                continue
            mask = np.zeros(n, dtype=bool)
            mask[sel] = True
            active = mask.copy()
            for d in (1, 2, 4):
                active[d:] |= mask[:-d]
                active[:-d] |= mask[d:]
            active = np.flatnonzero(active)
            if active.size < 20 or active.size > 0.8 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 200,
                              min(p3_end - 1.0,
                                  time.process_time() + 5.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
        print("band cyc=%d R=%.9f gains=%s"
              % (cyc, bestR, " ".join("%.1e" % g for g in gains)))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase 4: final tie polish ----
    fd = t0 + budget_seconds * 0.96
    if time.process_time() < fd - 2.0:
        win = _peak_window(best, pad_frac=0.04, extra=64)
        ht = _lbfgs_block(best, win, 400, fd - 1.0, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, deadline, bestR):
    best = h.copy()
    bR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 200, min(deadline - 0.3, time.process_time() + 3.0))
        rs = R_of(hs)
        if rs > bR:
            best, bR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.3, time.process_time() + 3.0), tie=True)
        rs = R_of(hs)
        if rs > bR:
            best, bR = hs, rs
    return best, bR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    start_bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Randomized asymmetric 2N splitting trials (exploration) ----
    n_trials = 5
    per_trial_cap = 4.0
    for t in range(1, n_trials + 1):
        if time.process_time() >= deadline - 10.0:
            break
        h = best
        n = h.size
        if t == 1:
            alpha = np.full(n, 0.5)
        else:
            rng = np.random.RandomState(1000 + t)
            alpha = rng.uniform(0.15, 0.85, size=n)
        H = np.empty(2 * n, dtype=float)
        H[0::2] = alpha * h
        H[1::2] = (1.0 - alpha) * h
        H = _rescale(H)
        cap = min(deadline - 8.0, time.process_time() + per_trial_cap)
        H2 = _lbfgs_log(H, 120, cap)
        rH = R_of(H2)
        # compress back to n by summing adjacent pairs
        Hc = H2[0::2] + H2[1::2]
        Hc = _rescale(Hc)
        rC = R_of(Hc)
        print("  trial %d split R=%.12f compress R=%.12f (dR=%+.2e)" %
              (t, rH, rC, max(rH, rC) - bestR))
        if rH > experiment_bestR + 1e-13:
            # keep expanded result as alternative (different N)
            experiment_best, experiment_bestR = H2.copy(), rH
        if rC > bestR + 1e-13:
            best, bestR = Hc, rC

    # ---- Alternating polish loop to end ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hp, rp = _polish(best, cap, bestR)
        if rp > bestR + 1e-13:
            best, bestR = hp.copy(), rp
            print("  polish iter=%d R=%.12f" % (it, bestR))

    print("final R=%.12f (N=%d)" % (bestR, best.size))
    if bestR > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": best, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _resample_mass(h, Np):
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    t = np.linspace(0.0, N, Np + 1)
    cp = np.interp(t, np.arange(N + 1, dtype=float), c)
    hp = (Np / N) * np.diff(cp)
    return np.clip(hp, 0.0, None)


def _refine_at_N(h, deadline, iters=800):
    """Full polish at current N: tie-followed-by-argmax plus peak window."""
    h = _lbfgs_all_pos(h, iters, deadline, tie=True)
    if time.process_time() < deadline - 2.0:
        h = _peak_ladder(h, deadline - 1.0,
                         pads=(0.10, 0.06, 0.04, 0.02), iters=300, tie=True)
    if time.process_time() < deadline - 0.6:
        h = _lbfgs_all_pos(h, iters // 2, deadline - 0.3, tie=False)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N_base = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- resolution sweep (new: also try *nearby* N values around the base,
    #      and denser refinement at each N) ----
    sweep_end = t0 + min(budget_seconds * 0.78, 48.0)
    # Denser grid including N's around the base for local refinement.
    N_list = set()
    for n in (22000, 26000, 30000, 34000, 38000, 43752, 48000, 52496,
              58000, 64000, 70000, 76000, 84000, 92000):
        N_list.add(n)
    # N's around the base to allow fine local N-search
    for k in (0.85, 0.92, 1.0, 1.08, 1.16):
        N_list.add(int(N_base * k))
    N_list = sorted(n for n in N_list if n != N_base and n >= 512)

    best_alt = None
    best_altR = -1.0
    sweep_it = 0

    while time.process_time() < sweep_end - 4.0:
        progressed = False
        for Np in N_list:
            if time.process_time() >= sweep_end - 4.0:
                break
            sweep_it += 1
            slice_end = min(sweep_end, time.process_time() + 5.0)
            hp = _resample_mass(best, Np)
            if hp.sum() <= 0:
                continue
            hp = _rescale(hp)
            r0 = R_of(hp)
            ht = _lbfgs_all_pos(hp, 500, slice_end - 2.0, tie=True)
            if time.process_time() < slice_end - 1.5:
                ht = _peak_ladder(ht, slice_end - 1.0,
                                  pads=(0.08, 0.05, 0.03), iters=200, tie=True)
            if time.process_time() < slice_end - 0.6:
                ht = _lbfgs_all_pos(ht, 200, slice_end - 0.2, tie=False)
            rt = R_of(ht)
            if rt > best_altR:
                best_alt, best_altR = ht.copy(), rt
            dR = rt - bestR
            accepted = rt > bestR + 1e-15
            if accepted:
                best, bestR = ht.copy(), rt
                progressed = True
            print("sweep %d N'=%d r0=%.9f dR=%+.3e %s R=%.9f zero_frac=%.4f nearmax5=%.4f"
                  % (sweep_it, Np, r0, dR, "ACCEPT" if accepted else "no gain",
                     bestR, _zero_frac(ht), _nearmax_frac(ht)))
        if not progressed and time.process_time() > sweep_end - 4.0:
            break

    # ---- NEW: heavy final refinement at the *current best N* with
    #      alternating tie/argmax and peak-ladder restarts. ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _refine_at_N(best, fd - 1.0, iters=1200)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL refine ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
        else:
            print("FINAL refine no gain R=%.9f" % r_t)

    # A second full pass with tie-only polish, giving the flat-top more time.
    if time.process_time() < fd - 1.5:
        h_t = _lbfgs_all_pos(best, 600, fd - 0.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))

    if time.process_time() < fd - 0.6:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.2, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if best_alt is not None and best_alt.size != best.size and best_altR > startR + 1e-12:
        result["alternative"] = best_alt
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_shape(h):
    # Exact shape gradient of log R on the manifold max(f*f)=1:
    #   u = log Q - 2 log S   (no log M term)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if shape:
        fg = _fun_grad_shape
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _weighted_mean(h):
    # Q / S^2 : the weighted mean of f*f (equals R when max L = 1)
    s = h.sum()
    if s <= 0:
        return 0.0
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    Q = np.sum(a * a + a * b + b * b) / 3.0
    return float(Q / (s * s))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size
    shape_best = best.copy()
    shapeR = bestR

    # ---- shape-gradient rounds with hard projection ----
    reserve = 12.0
    round_i = 0
    while time.process_time() < deadline - reserve:
        round_i += 1
        tlim = min(deadline - reserve, time.process_time() + 6.0)
        cand = _lbfgs_block(shape_best, np.arange(N), 400, tlim, shape=True)
        r_pre = R_of(cand)
        wm_pre = _weighted_mean(cand)
        mx_pre = _knots(cand).max()
        # hard projection: max f*f = 1 exactly
        proj = _rescale(cand)
        r_post = R_of(proj)
        wm_post = _weighted_mean(proj)
        mx_post = _knots(proj).max()
        print("shape round %d: pre R=%.12f wm=%.9f maxL=%.6f | post R=%.12f wm=%.9f maxL=%.6f"
              % (round_i, r_pre, wm_pre, mx_pre, r_post, wm_post, mx_post))
        improved = False
        if r_post > shapeR + 1e-15:
            shape_best, shapeR = proj.copy(), r_post
            improved = True
        # one p2392 full-array tie polish on projected h
        if time.process_time() < deadline - reserve - 1.0:
            tlim2 = min(deadline - reserve, time.process_time() + 3.0)
            pol = _lbfgs_block(proj, np.arange(N), 150, tlim2, tie=True)
            rp = R_of(pol)
            if rp > shapeR + 1e-15:
                shape_best, shapeR = pol.copy(), rp
                improved = True
        if not improved and round_i >= 2:
            break

    print("shape phase done R=%.12f (rounds=%d)" % (shapeR, round_i))

    # update global best
    if shapeR > bestR + 1e-15:
        best, bestR = shape_best.copy(), shapeR

    # ---- p2392's own pipeline on the best h ----
    period = 1
    m = N
    W = 128
    if m <= W:
        win_starts = [0]
        W = m
    else:
        win_starts = list(range(0, m - W + 1, max(1, W // 2)))
    if win_starts and win_starts[-1] + W < m:
        win_starts.append(m - W)

    rng = np.random.RandomState(12345)
    accepted = 0
    reserve2 = 4.0
    outer = 0
    while time.process_time() < deadline - reserve2 - 4.0:
        outer += 1
        order = rng.permutation(len(win_starts))
        any_accept = False
        for oi in order:
            if time.process_time() >= deadline - reserve2 - 4.0:
                break
            w0 = win_starts[oi]
            fine_lo = w0
            fine_hi = min(N, w0 + W)
            free = np.arange(fine_lo, fine_hi)
            tlim = min(deadline - reserve2 - 4.0, time.process_time() + 0.5)
            cand = _lbfgs_block(best, free, 40, tlim, tie=True)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand
                bestR = r
                accepted += 1
                any_accept = True
        if not any_accept:
            break
    print("window descent accepted=%d outer=%d R=%.12f" % (accepted, outer, bestR))

    alt_best = None
    altR = -1.0

    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.3, time.process_time() + 1.5), tie=True)
        r = R_of(ht)
        print("peak polish pad=%.2f R=%.12f" % (pad, r))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > altR:
            altR, alt_best = r, ht.copy()

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if shape_best is not None and shapeR > startR + 1e-14 and shapeR < bestR - 1e-14:
        # shape construction genuinely different and not the final best
        result["alternative"] = shape_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    elif shape_best is not None and shapeR <= startR + 1e-14:
        result["alternative"] = shape_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q, a):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad_tie(h)
    v = np.quantile(Lf, q)
    band = Lf >= v
    nb = int(band.sum())
    if nb <= 0:
        return _fun_grad_tie(h)
    cv = float(Lf[band].mean())
    if cv <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    m = int(np.argmax(Lf))
    gLf[m] += (1.0 - a) / M
    gLf[band] += a / (nb * cv)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (1.0 - a) * np.log(M) + a * np.log(cv)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 cvar=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if cvar is not None:
        q, a = cvar
        fg = (lambda hh: _fun_grad_cvar(hh, q, a))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _detect_period(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p == 0:
            m = n // p
            c = h.reshape(m, p).mean(axis=1)
            if np.allclose(np.repeat(c, p), h, atol=1e-9 * (np.abs(h).max() + 1)):
                return p
    return 1


def _coarse_to_width(c, K):
    """Map a coarse array c (length m) to a fine array of length m*K by
    resampling c to a target coarse length so that repeat gives N."""
    m = c.size
    if K == 1:
        return c.copy()
    # target coarse length so that repeat(.,K) has length m*1 (original N)
    # We want fine length = m (coarse count) * 1 = original N. So target
    # coarse length = m / K * 1 ... simpler: build fine length N = m*K_orig.
    return None


def _build_at_width(c, K, N_target):
    """Build fine array of length N_target from coarse c by resampling c to
    length N_target//K then repeating K times."""
    m = c.size
    mc = N_target // K
    if mc == m:
        cc = c
    else:
        xi = np.linspace(0.0, m - 1.0, mc)
        cc = np.interp(xi, np.arange(m, dtype=float), c)
    return np.repeat(cc, K)


def _window_descent(best, bestR, N, period, deadline, reserve, rng,
                    W=128, max_outer=100):
    m = N // period
    if m <= W:
        win_starts = [0]
        W = m
    else:
        win_starts = list(range(0, m - W + 1, max(1, W // 2)))
    if win_starts and win_starts[-1] + W < m:
        win_starts.append(m - W)
    accepted = 0
    outer = 0
    while time.process_time() < deadline - reserve:
        outer += 1
        order = rng.permutation(len(win_starts))
        any_accept = False
        for oi in order:
            if time.process_time() >= deadline - reserve:
                break
            w0 = win_starts[oi]
            fine_lo = period * w0
            fine_hi = min(N, period * (w0 + W))
            free = np.arange(fine_lo, fine_hi)
            tlim = min(deadline - reserve, time.process_time() + 0.5)
            cand = _lbfgs_block(best, free, 40, tlim, tie=True)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand
                bestR = r
                accepted += 1
                any_accept = True
        if not any_accept or outer >= max_outer:
            break
    return best, bestR, accepted, outer


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.12f (N=%d)" % (bestR, N))

    # ---- confirm period and form coarse ----
    period = _detect_period(best)
    print("detected period=%d" % period)
    if N % period != 0:
        period = 1
    if period > 1:
        m = N // period
        c = best.reshape(m, period).mean(axis=1)
        best_block = _rescale(np.repeat(c, period))
        rb = R_of(best_block)
        print("block-constant R=%.12f (m=%d)" % (rb, m))
        if rb >= bestR - 1e-12:
            best = best_block
            bestR = rb
    else:
        m = N
        c = best.copy()

    # ---- duty-cycle sweep on plateau width K ----
    base_period = period if period > 1 else 32
    # coarse array c represents m values; original fine N = m*base_period
    # We want candidates of width K with same N: coarse length N//K.
    K_list = [8, 16, 32, 34, 68, 136, 272]
    K_list = [K for K in K_list if N % K == 0 and N // K >= 8]
    print("K sweep: %s" % (K_list,))

    rng = np.random.RandomState(12345)
    sweep_best = best.copy()
    sweep_bestR = bestR
    sweep_results = {}

    # per-K budget: ~6 s
    nK = max(1, len(K_list))
    per_K = max(2.0, min(6.0, (deadline - time.process_time() - 8.0) / nK))

    for K in K_list:
        if time.process_time() >= deadline - 8.0:
            break
        tK = time.process_time() + per_K
        try:
            cand = _build_at_width(c, K, N)
        except Exception:
            continue
        if cand.size != N:
            continue
        cand = _rescale(cand)
        r0 = R_of(cand)
        # full tie L-BFGS ~ up to 3 s
        tlim = min(tK - per_K * 0.4, time.process_time() + 3.0)
        cand1 = _lbfgs_block(cand, np.arange(N), 200, tlim, tie=True)
        r1 = R_of(cand1)
        # one window-descent pass ~ up to 2 s
        tlim2 = min(tK - 0.2, time.process_time() + 2.0)
        cand2, r2, acc, out = _window_descent(
            cand1, r1, N, period if period > 1 else K, tlim2, 0.2, rng,
            W=128, max_outer=2)
        sweep_results[K] = (r0, r1, r2)
        print("K=%3d pre=%.9f post_tie=%.9f post_win=%.9f"
              % (K, r0, r1, r2))
        if r2 > sweep_bestR + 1e-15:
            sweep_best = cand2.copy()
            sweep_bestR = r2
            print("  new sweep best K=%d R=%.12f" % (K, r2))

    if sweep_bestR > bestR + 1e-15:
        best = sweep_best
        bestR = sweep_bestR

    # ---- remaining time: p2392 pipeline verbatim on best ----
    per = _detect_period(best)
    if per <= 1:
        per = period if period > 1 else 1

    reserve = 4.0
    if time.process_time() < deadline - reserve - 2.0:
        best, bestR, acc, out = _window_descent(
            best, bestR, N, per, deadline, reserve, rng, W=128, max_outer=100)
        print("window descent accepted=%d outer=%d R=%.12f" % (acc, out, bestR))

    alt_best = None
    altR = -1.0

    if time.process_time() < deadline - 3.0:
        pol = _lbfgs_block(best, np.arange(N), 200,
                           min(deadline - 2.0, time.process_time() + 3.0), tie=True)
        rp = R_of(pol)
        print("full tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        if rp > altR:
            altR, alt_best = rp, pol.copy()

    for pad in (0.05, 0.03):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.3, time.process_time() + 1.5), tie=True)
        r = R_of(ht)
        print("peak polish pad=%.2f R=%.12f" % (pad, r))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > altR:
            altR, alt_best = r, ht.copy()

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-15:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    if num <= 0:
        return 1e18, np.zeros(h.size)
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        grad = 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    else:
        grad = 2.0 * np.correlate(gL, h, mode='valid')[:n]
    grad = grad + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        return _fun_grad(np.clip(x, 0.0, None))

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.clip(res.x, 0.0, None)
    except (TimeoutError, Exception):
        return h0
    return _rescale(h2)


def _prolong(h, N2):
    N = len(h)
    if N2 == N:
        return h.copy()
    if N2 % N == 0:
        return np.repeat(h, N2 // N)
    idx = np.clip((np.arange(N2) * N // N2), 0, N - 1)
    return h[idx]


def _perturb(h, rng, scale=0.1):
    h = h.copy()
    mask = rng.random(h.size) < 0.15
    h[mask] *= np.exp(rng.normal(0, scale, mask.sum()))
    return _rescale(h)


def _smooth(h, k=2):
    """Light smoothing to escape sharp local structure before re-refining."""
    if k <= 0 or h.size < 2 * k + 1:
        return h
    ker = np.ones(2 * k + 1) / (2 * k + 1)
    return _rescale(np.convolve(h, ker, mode='same'))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(987654321)

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best_h = s.copy()
            best_R = _R(best_h)

    if best_h is None:
        N = 4096
        i = np.arange(N)
        best_h = np.minimum(3.0, ((i + 0.5) / N) ** -0.5)
        best_h = _rescale(best_h)
        best_R = _R(best_h)

    N0 = len(best_h)

    # Phase 1: prolong to higher resolution and polish.
    # Push resolution higher than the start to allow finer structure.
    targets = []
    for N in (N0, N0 * 2, 8192, 16384, 32768, 65536):
        if N >= N0 and N <= 65536:
            targets.append(N)
    targets = sorted(set(targets))

    current = best_h
    for N in targets:
        if time.process_time() >= deadline - 1.5:
            break
        if len(current) != N:
            current = _prolong(current, N)
        current = _rescale(current)
        r_cur = _R(current)
        for _ in range(3):
            if time.process_time() >= deadline - 1.5:
                break
            iters = min(4000, max(300, int(300000 / N)))
            h2 = _lbfgs(current, iters, deadline)
            r2 = _R(h2)
            if r2 > r_cur + 1e-12:
                current = h2
                r_cur = r2
            else:
                break
        print("N=%d R=%.6f" % (N, r_cur))
        if r_cur > best_R:
            best_R = r_cur
            best_h = current.copy()

    # Phase 2: refinement at the best resolution with smoothing perturbations.
    # Smoothing + re-optimization explores different local basins than
    # multiplicative noise, often revealing a slightly higher peak.
    N_best = len(best_h)
    cur = best_h.copy()
    cur_R = best_R
    trial = 0
    while time.process_time() < deadline - 0.8:
        trial += 1
        # alternate: smoothing perturbation, then multiplicative noise
        if trial % 2 == 1:
            k = rng.integers(1, 4)
            cand = _smooth(cur, int(k))
        else:
            cand = _perturb(cur, rng, scale=0.03 + 0.08 * rng.random())
        # light polish
        iters = min(3000, max(200, int(200000 / N_best)))
        cand = _lbfgs(cand, iters, deadline)
        r2 = _R(cand)
        if r2 > best_R + 1e-12:
            best_R = r2
            best_h = cand.copy()
            cur = cand.copy()
            cur_R = r2
            print("trial %d improved R=%.6f" % (trial, r2))
        elif r2 > cur_R - 1e-9:
            # drift slightly toward candidate to keep exploring
            cur = cand.copy()
            cur_R = r2

    print("FINAL best R=%.6f N=%d" % (best_R, len(best_h)))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = _R(s) if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0 else -1
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample(h, factor):
    """Asymmetric-ish upsample preserving mass, then rescale."""
    n = h.size
    N = n * factor
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    H = np.interp(x_new, x_old, h, left=0.0, right=0.0)
    return _rescale(H)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = _rescale(s.copy())
            bestR = R_of(best)
    if best is None:
        best = np.ones(64)
        bestR = R_of(best)

    cur = best.copy()
    curR = bestR
    N = cur.size
    print("start R=%.6f N=%d" % (curR, N))

    # NEW IDEA: try upsampled resolutions (2x, 4x) and optimize there, then
    # keep whichever resolution gives the best R. Finer resolution gives the
    # optimiser more degrees of freedom to sharpen the peak region.
    candidates = [("N", cur.copy())]
    for fac in (2, 4):
        if cur.size * fac <= 1000000:
            candidates.append(("N*%d" % fac, _upsample(cur, fac)))

    best_res = cur.copy()
    best_resR = curR

    for name, h0 in candidates:
        if time.process_time() >= deadline - 5.0:
            break
        hh = h0.copy()
        hr = R_of(hh)
        print("res %s R0=%.6f N=%d" % (name, hr, hh.size))
        # quick full polish at this resolution with smoothing continuation
        for beta in (4, 16, 64):
            if time.process_time() >= deadline - 4.0:
                break
            cap = min(deadline - 3.0, time.process_time() + 2.5)
            cand = _lbfgs_log(hh, 300, cap,
                              fg=lambda h, b=beta: _fun_grad_sm(h, b))
            r = R_of(cand)
            if r > hr:
                hh, hr = cand, r
        if time.process_time() < deadline - 3.0:
            cap = min(deadline - 2.0, time.process_time() + 3.0)
            cand = _lbfgs_log(hh, 500, cap)
            r = R_of(cand)
            if r > hr:
                hh, hr = cand, r
        # peak-window polish at this resolution
        for frac in (0.02, 0.05, 0.10):
            if time.process_time() >= deadline - 2.0:
                break
            free = _peak_window(hh, frac=frac)
            cap = min(deadline - 1.5, time.process_time() + 1.5)
            hb = _lbfgs_block(hh, free, 120, cap)
            rb = R_of(hb)
            if rb > hr:
                hh, hr = hb, rb
        print("  res %s -> R=%.6f" % (name, hr))
        if hr > best_resR:
            best_res, best_resR = hh.copy(), hr

    cur, curR = best_res, best_resR
    if curR > bestR:
        best, bestR = cur.copy(), curR

    # Main loop at the best resolution found.
    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        cap = min(deadline - 0.5, time.process_time() + 4.0)
        cand = _lbfgs_log(cur, 800, cap)
        r = R_of(cand)
        if r > curR:
            cur, curR = cand, r
        if curR > bestR:
            best, bestR = cur.copy(), curR

        for frac in (0.01, 0.03, 0.07, 0.15, 0.30):
            if time.process_time() >= deadline - 0.8:
                break
            free = _peak_window(cur, frac=frac)
            cap = min(deadline - 0.5, time.process_time() + 2.0)
            hb = _lbfgs_block(cur, free, 150, cap)
            rb = R_of(hb)
            if rb > curR:
                cur, curR = hb, rb
            if curR > bestR:
                best, bestR = cur.copy(), curR
        print("iter %d R=%.6f (best %.6f)" % (it, curR, bestR))

    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.2, time.process_time() + 2.0)
        hb = _lbfgs_log(best, 400, cap, fg=lambda h: _fun_grad_sm(h, 64))
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb

    print("final R=%.6f N=%d" % (bestR, best.size))

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---- KEY NEW IDEA: symmetric plateau flattening of the peak ----
# The optimum wants many knots of f*f equal to the max (a flat top).
# Instead of tiny local moves, we do a large global reshape: remap the
# density in mass via a smooth symmetric "squash" of the peak region so
# that many knots land at exactly the max, then polish.

def _flat_top_polish(h, deadline, rounds=4):
    """Iteratively push down near-max knots and re-polish to grow plateau."""
    best = h.copy()
    bestR = R_of(best)
    for r in range(rounds):
        if time.process_time() > deadline - 1.0:
            break
        Lf = _knots(best)
        mx = Lf.max()
        # target: pull the top 5% of knots toward mx by rescaling the
        # density where f*f exceeds 0.9*mx.  We achieve this by a mass
        # redistribution: raise h slightly in the peak region so the
        # plateau grows; L-BFGS will then equalize.
        # Cheap effective move: use strong beta polish with growing beta.
        beta = 10.0 ** (4 + r)
        win = _peak_window(best, tol=0.98, pad_frac=0.6, extra=512)
        t_lim = min(deadline - 0.5, time.process_time() + 6.0)
        cand = _lbfgs_block(best, win, 400, t_lim, beta=beta)
        rc = R_of(cand)
        # full-array tie polish afterwards
        if time.process_time() < deadline - 1.0:
            t_lim2 = min(deadline - 0.3, time.process_time() + 6.0)
            cand2 = _lbfgs_block(cand, np.arange(cand.size), 300, t_lim2, tie=True)
            r2 = R_of(cand2)
            if r2 > rc:
                cand, rc = cand2, r2
        if rc > bestR + 1e-15:
            best, bestR = cand, rc
        else:
            best, bestR = cand if rc > bestR else best, max(bestR, rc)
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d, ties=%d)" % (bestR, best.size, _tie_count(best)))

    alternative = None

    # Phase 1: rapid beta-escalation full-array polish to fatten the plateau.
    betas = [1e3, 1e4, 1e5, 1e6, 1e7]
    for b in betas:
        if time.process_time() > deadline - 12.0:
            break
        t_lim = min(deadline - 10.0, time.process_time() + 5.0)
        cand = _lbfgs_block(best, np.arange(best.size), 200, t_lim, beta=b)
        rc = R_of(cand)
        if rc > bestR + 1e-15:
            best, bestR = cand, rc
        print("beta=%.0e R=%.12f ties=%d" % (b, rc, _tie_count(cand)))

    # Phase 2: flat-top plateau growth rounds.
    if time.process_time() < deadline - 6.0:
        flat, rf = _flat_top_polish(best, min(deadline - 3.0,
                                              time.process_time() + 30.0), rounds=4)
        print("flat-top R=%.12f ties=%d" % (rf, _tie_count(flat)))
        if rf > bestR + 1e-15:
            best, bestR = flat, rf
        elif rf > startR + 1e-14:
            alternative = flat

    # Phase 3: final full-array tie polish (drives exact ties).
    if time.process_time() < deadline - 2.0:
        t_lim = min(deadline - 0.5, time.process_time() + 8.0)
        cand = _lbfgs_block(best, np.arange(best.size), 400, t_lim, tie=True)
        rc = R_of(cand)
        print("final tie polish R=%.12f ties=%d" % (rc, _tie_count(cand)))
        if rc > bestR + 1e-15:
            best, bestR = cand, rc
        elif rc > startR + 1e-14 and alternative is None:
            alternative = cand

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alternative is not None and R_of(alternative) <= startR + 1e-14:
        result["alternative"] = alternative
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

