    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _maxknot(h):
    return _knots(h).max()


def _peak_window(h, tol=0.999, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _fun_u_grad(h):
    """u(h) = -log Q + 2 log S, plus max-knot tangent info."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size), None, None
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size), None, None
    gLf = -dq / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    mx = Lf.max()
    if mx <= 0:
        return val, grad, None, None
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-12))
    e = np.zeros_like(Lf)
    e[idx] = 1.0 / idx.size
    v = _backprop(e, h)
    return val, grad, v, mx


