def _lbfgs_proj(h0, free, maxiter, deadline):
    """L-BFGS-B on u with gradient projected orthogonal to v = dL_m/dh."""
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
