        m_before = _maxknot(cand)
        cand = _rescale(cand)
        m_after = _maxknot(cand)
        r = R_of(cand)
        acc = r > bestR + 1e-15
        print("%s |Lm-1| pre=%.3e post=%.3e R=%.12f %s"
              % (tag, abs(m_before - 1.0), abs(m_after - 1.0), r,
                 "ACCEPT" if acc else "reject"))
        if acc:
            best, bestR = cand.copy(), r
            improved_once = True
        if r > altR:
            altR, alt_best = r, cand.copy()
        return cand

    # ---- main loop: alternate full-array and peak-window projected blocks ----
    full = np.arange(N)
    it = 0
    while time.process_time() < deadline - 3.0:
        it += 1
        # full-array block
        tlim = min(deadline - 3.0, time.process_time() + 3.0)
        cand = _lbfgs_proj(best, full, 150, tlim)
        _try(cand, "full#%d" % it)
        if time.process_time() >= deadline - 3.0:
            break
        # peak-window blocks at several pads
        for pad in (0.4, 0.15, 0.05):
            if time.process_time() >= deadline - 3.0:
                break
            win = _peak_window(best, tol=0.999, pad_frac=pad, extra=128)
            tlim = min(deadline - 3.0, time.process_time() + 1.5)
            cand = _lbfgs_proj(best, win, 150, tlim)
            _try(cand, "peak#%d pad=%.2f" % (it, pad))

    print("iters=%d improved=%s bestR=%.12f startR=%.12f"
          % (it, improved_once, bestR, startR))

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR <= bestR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and alt_best is not None:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, a, q):
    """CVaR band: average of top (1-q) fraction of knots, softened."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    thr = q * mx
    # soft indicator: knots above threshold
    w = 1.0 / (1.0 + np.exp(np.clip(-(Lf - thr) / (a * mx + 1e-12), -60, 60)))
    Z = w.sum()
    if Z <= 0:
        return _fun_grad(h)
    wn = w / Z
    sm = np.sum(wn * Lf)
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num + wn / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, cvar=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if cvar is not None:
        a, q = cvar
        fg = lambda hh: _fun_grad_cvar(hh, a, q)
    elif beta > 0:
        fg = lambda hh: _fun_grad_beta(hh, beta)
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h):
    """Mass-preserving linear prolongation to 2N."""
    n = h.size
    out = np.zeros(2 * n)
    # each cell splits into two halves; linear interpolation of step function
    # mass preserving: out[2i] = out[2i+1] = h[i] (piecewise constant split)
    out[0::2] = h
    out[1::2] = h
    return out


def _zero_frac(h):
    return float(np.mean(h == 0))


def _knot_frac(h, frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _report(tag, h, R):
    print("%s R=%.9f N=%d zero_frac=%.3f knot0.1%%=%.4f" %
          (tag, R, h.size, _zero_frac(h), _knot_frac(h, 0.001)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    _report("base", best, bestR)

    alt_best = None
    alt_bestR = -1.0

    def consider(h, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR, origin = h.copy(), r, tag
            _report("  NEW BEST " + tag, best, bestR)
            return True
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = h.copy(), r
            _report("  " + tag + " (best %.9f)" % bestR, h, r)
            return False

    # Stage 1: full-array tie-gradient L-BFGS
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        consider(ht, "s1_full")
        # a couple more full polishes
        for k in range(2):
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            consider(ht, "s1_full%d" % k)

    # Stage 2: resolution ladder
    if best.size <= 250000 and time.process_time() < deadline - 2.0:
        cur = best.copy()
        curR = bestR
        while cur.size * 2 <= 1000000 and time.process_time() < deadline - 2.0:
            up = _prolong(cur)
            up = _rescale(up)
            ht = _lbfgs_all_pos(up, 300, deadline - 0.5, beta=0.0)
            consider(ht, "s2_lad%d_full" % ht.size)
            win = _peak_window(ht, tol=0.9995, pad_frac=0.4, extra=128)
            ht2 = _lbfgs_block(ht, win, 400, deadline - 0.5, beta=1e7)
            ht2 = _lbfgs_all_pos(ht2, 300, deadline - 0.5, beta=0.0)
            consider(ht2, "s2_lad%d_pk" % ht2.size)
            # continue ladder from whichever is best at this N
            if R_of(ht2) >= R_of(ht):
                cur = ht2
            else:
                cur = ht
            curR = R_of(cur)
            # if the ladder isn't buying anything, stop
            if curR <= bestR + 1e-9 and cur.size > best.size:
                break

    # Stage 3: CVaR band rungs at full N
    for (a, q) in [(1.0, 0.95), (1.0, 0.98)]:
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(best, 150, deadline - 0.5, cvar=(a, q))
        consider(ht, "s3_cvar_%.2f_%.2f" % (a, q))
        ht = _lbfgs_all_pos(best, 150, deadline - 0.5, beta=0.0)
        consider(ht, "s3_cvar_%.2f_%.2f_full" % (a, q))

    # Stage 4: randomised 128-cell block descent
    rng = np.random.default_rng(12345)
    n = best.size
    nblocks = 128
    block_time_end = min(deadline - 1.0, time.process_time() + 20.0)
    while time.process_time() < block_time_end:
        # random permutation of blocks
        order = rng.permutation(nblocks)
        improved = False
        for b in order:
            if time.process_time() >= block_time_end:
                break
            lo = (b * n) // nblocks
            hi = ((b + 1) * n) // nblocks
            if hi <= lo:
                continue
            free = np.arange(lo, hi)
            ht = _lbfgs_block(best, free, 60, block_time_end, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, "s4_blk%d" % b
                improved = True
        if not improved:
            # try a full polish to escape
            if time.process_time() < block_time_end:
                ht = _lbfgs_all_pos(best, 150, block_time_end, beta=0.0)
                consider(ht, "s4_full")
    _report("s4_done", best, bestR)

    # Stage 5: final peak polishes + full tie polish
    for pad in [0.05, 0.03]:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, tol=0.9995, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 0.5, beta=1e7)
        consider(ht, "s5_pk%.2f" % pad)
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        consider(ht, "s5_pk%.2f_full" % pad)

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
        consider(ht, "s5_final_full")

    _report("final", best, bestR)
    print("origin=%s (start %.9f)" % (origin, start_bestR))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_band(h, eps, gamma):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    B = np.flatnonzero(Lf >= (1.0 - eps) * mx)
    if B.size > 0:
        gLf[B] -= gamma / (B.size * mx)
        deficit = float(np.mean(mx - Lf[B])) / mx
    else:
        deficit = 0.0
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + gamma * deficit
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, band=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if band is not None:
        eps, gamma = band
        fg = (lambda hh: _fun_grad_band(hh, eps, gamma))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _band_stats(h, eps):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0
    B = Lf >= (1.0 - eps) * mx
    frac = float(np.mean(B))
    if not np.any(B):
        return frac, 0.0
    deficit = float(np.mean(mx - Lf[B])) / mx
    return frac, deficit


def _deconv_step(h0, T, lam, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    Tn = float(np.sum(T * T))
    if Tn <= 0:
        return h0
    h0n = float(np.sum(h * h))
    if h0n <= 0:
        h0n = 1.0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        Lf = _knots(hh)
        r = Lf - T
        val = float(np.sum(r * r)) / Tn + lam * float(np.sum((hh - h) ** 2)) / h0n
        gLf = 2.0 * r / Tn
        g = _backprop(gLf, hh) + 2.0 * lam * (hh - h) / h0n
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _build_target(L, eps):
    mx = L.max()
    S = L >= (1.0 - eps) * mx
    T = L.copy()
    if not np.any(S):
        return T
    idx = np.flatnonzero(S)
    lo, hi = idx.min(), idx.max()
    val = L[S].mean()
    T[lo:hi + 1] = val
    k = 9
    ker = np.ones(k) / k
    T = np.convolve(T, ker, mode='same')
    return T


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    full = np.arange(best.size)
    alt_best = None
    altR = -1.0

    def try_cand(hc, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hc)
        if r > altR:
            altR = r
            alt_best = hc.copy()
        if r > bestR + 1e-15:
            best, bestR = hc.copy(), r
            print("%s: R=%.12f NEW" % (tag, r))
        else:
            print("%s: R=%.12f" % (tag, r))
        return r

    # ---- Phase 1: deconvolution seeding at multiple eps ----
    for eps in [1e-2, 3e-3, 1e-3]:
        if time.process_time() >= deadline - 40.0:
            break
        L = _knots(best)
        T = _build_target(L, eps)
        tlim = min(deadline - 38.0, time.process_time() + 6.0)
        hd = _deconv_step(best, T, 1e-3, 80, tlim)
        try_cand(hd, "deconv eps=%.0e" % eps)
        if time.process_time() < deadline - 36.0:
            pol = _lbfgs_block(hd, np.arange(hd.size), 250,
                               min(deadline - 35.0, time.process_time() + 5.0))
            try_cand(pol, "  pol")

    # ---- Phase 2: band ladder ----
    ladder = [(0.05, 0.3), (0.05, 1.0), (0.05, 3.0), (0.03, 3.0),
              (0.02, 1.0), (0.02, 3.0), (0.01, 3.0)]
    rung_best = {}
    for (eps, gamma) in ladder:
        if time.process_time() >= deadline - 14.0:
            break
        tlim = min(deadline - 13.0, time.process_time() + 4.5)
        hb = _lbfgs_block(best, full, 250, tlim, band=(eps, gamma))
        rb = try_cand(hb, "band eps=%.2f g=%.1f" % (eps, gamma))
        rung_best[(eps, gamma)] = rb
        if time.process_time() < deadline - 10.0:
            pol = _lbfgs_block(hb, full, 250,
                               min(deadline - 9.0, time.process_time() + 4.0))
            rp = try_cand(pol, "  pol")
            rung_best[(eps, gamma)] = max(rb, rp)
            for pad in (0.05, 0.03):
                if time.process_time() >= deadline - 5.0:
                    break
                win = _peak_window(pol, pad_frac=pad, extra=96)
                ht = _lbfgs_block(pol, win, 300,
                                  min(deadline - 4.0, time.process_time() + 2.5))
                try_cand(ht, "  win pad=%.2f" % pad)

    fr1, def1 = _band_stats(best, 0.05)
    print("band eps=0.05 after: frac=%.4f deficit=%.6f" % (fr1, def1))

    # ---- Phase 3: cycle best rung with remaining budget ----
    if rung_best:
        best_rung = max(rung_best, key=rung_best.get)
    else:
        best_rung = (0.05, 1.0)
    while time.process_time() < deadline - 2.5:
        eps, gamma = best_rung
        tlim = min(deadline - 2.0, time.process_time() + 3.0)
        hb = _lbfgs_block(best, full, 200, tlim, band=(eps, gamma))
        pol = _lbfgs_block(hb, full, 200,
                           min(deadline - 1.0, time.process_time() + 2.0))
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            try_cand(pol, "cycle")
        else:
            break

    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, full, 250,
                           min(deadline - 0.5, time.process_time() + 2.0))
        try_cand(pol, "final")

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h, eps=1e-8):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - eps))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.3, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-8)))


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_beta(h0, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_beta(hh, beta)

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(h)

    bestR = startR
    N = best.size
    print("base R=%.12f (N=%d, ties=%d)" % (bestR, N, _tie_count(best)))

    work = best.copy()
    workR = bestR
    rng = np.random.RandomState(987654321)

    # Main loop: alternate full-vector tie-polish with peak-window polish,
    # and occasionally perturb the peak region for diversification.
    rnd = 0
    while time.process_time() < deadline - 0.5:
        rnd += 1
        sub = min(deadline - 0.3, time.process_time() + 8.0)

        # 1) tie-aware full polish (helps when max is nearly flat)
        if time.process_time() < sub - 0.3:
            ht = _lbfgs_block(work, np.arange(work.size), 200, sub, tie=True)
            r = R_of(ht)
            if r > workR + 1e-15:
                work, workR = ht, r

        # 2) peak window polish (focused, cheap)
        if time.process_time() < sub - 0.3:
            win = _peak_window(work, tol=0.999, pad_frac=0.25)
            ht = _lbfgs_block(work, win, 200, sub, tie=True)
            r = R_of(ht)
            if r > workR + 1e-15:
                work, workR = ht, r

        # 3) if stalled, perturb peak region and re-polish
        if workR <= bestR + 1e-15 and time.process_time() < sub - 0.3:
            Lf = _knots(work)
            m = int(np.argmax(Lf))
            lo = max(0, m - 600); hi = min(work.size, m + 600)
            if hi - lo > 8:
                x = np.arange(lo, hi, dtype=float)
                c = rng.uniform(lo, hi)
                w = max(2.0, (hi - lo) * rng.uniform(0.05, 0.2))
                bump = np.exp(-0.5 * ((x - c) / w) ** 2)
                bump = np.convolve(bump, np.ones(9) / 9.0, mode='same')
                amp = rng.uniform(0.003, 0.02)
                hp = work.copy()
                hp[lo:hi] *= np.exp(amp * bump)
                hp = _rescale(hp)
                ht = _lbfgs_block(hp, np.arange(hp.size), 150, sub, tie=True)
                r = R_of(ht)
                if r > workR + 1e-15:
                    work, workR = ht, r
                else:
                    # try beta-continuation from the perturbed point
                    if time.process_time() < sub - 0.3:
                        hb = _lbfgs_beta(hp, 120, sub, 1e7)
                        rb = R_of(hb)
                        if rb > workR + 1e-15:
                            work, workR = hb, rb

        if workR > bestR + 1e-15:
            best, bestR = work.copy(), workR

        if rnd % 3 == 0:
            print("R=%.10f (best=%.10f, ties=%d)" %
                  (workR, bestR, _tie_count(best)))

    if bestR > startR + 1e-12:
        return best
    return {"best": best,
            "alternative": work if workR > startR - 1e-7 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline,
                        beta=beta, tie=tie)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _densify(h):
    h = np.clip(h, 0, None)
    pos = h[h > 0]
    if pos.size == 0:
        return h
    eps = 1e-6 * pos.mean()
    out = h.copy()
    out[out <= 0] = eps
    return _rescale(out)


def _resample_smooth(h, newn):
    h = np.clip(h, 0, None)
    n = h.size
    if n == newn:
        return h.copy()
    if n == 0 or h.sum() <= 0:
        return h
    c = np.concatenate(([0.0], np.cumsum(h)))
    c /= c[-1]
    xs = np.linspace(0.0, 1.0, newn + 1)
    cn = np.interp(xs, np.linspace(0.0, 1.0, n + 1), c)
    hn = np.diff(cn)
    return _rescale(np.clip(hn, 0, None))


def _shrink_zeros(h):
    h = np.clip(h, 0, None)
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    return h[nz[0]:nz[-1] + 1]


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _polish(best, bestR, deadline, rounds=3):
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.3:
            break
        ht = _lbfgs_all(best, 800, deadline, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        ht = _lbfgs_all(best, 400, deadline, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        for beta in [1e5, 1e6, 1e7, 1e8]:
            if time.process_time() >= deadline - 0.3:
                break
            ht = _lbfgs_all(best, 200, deadline, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 0.3:
            win = _peak_window(best, tol=0.995, pad_frac=0.25, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    trimmed = _shrink_zeros(best)
    if trimmed.size > 0:
        t2 = _rescale(trimmed)
        r = R_of(t2)
        if r > bestR - 1e-9:
            best, bestR = t2, r
    best = _densify(best)
    bestR = R_of(best)
    print("trim+densify R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: full polish at current resolution (this is the key win path).
    best, bestR = _polish(best, bestR, deadline - 0.5, rounds=2)
    print("phase A R=%.7f (N=%d)" % (bestR, best.size))

    # Phase B: upsample ramp — many parallel-ish resolutions, each polished.
    n0 = best.size
    targets = []
    for nn in [int(round(n0 * f)) for f in (1.1, 1.25, 1.5, 2.0, 2.5, 3.0)]:
        if 32 <= nn <= 900000:
            targets.append(nn)
    for nn in [32768, 65536, 131072, 262144, 393216]:
        if 32 <= nn <= 900000 and nn not in targets:
            targets.append(nn)
    targets.sort()
    for nn in targets:
        if time.process_time() >= deadline - 1.5:
            break
        seed = _densify(_resample_smooth(best, nn))
        r0 = R_of(seed)
        cand, rc = _polish(seed, r0, deadline - 0.8, rounds=1)
        if rc > bestR + 1e-13:
            best, bestR = cand, rc
            print("  resample N=%d -> R=%.7f NEW BEST" % (best.size, bestR))
        else:
            print("  resample N=%d -> R=%.7f" % (best.size, rc))

    # Phase C: polish the winner + occasional upsample until the deadline.
    it = 0
    while time.process_time() < deadline - 0.8:
        it += 1
        improved = False
        h1, r1 = _polish(best, bestR, deadline - 0.4, rounds=1)
        if r1 > bestR + 1e-13:
            best, bestR = h1, r1
            improved = True
        if not improved and best.size < 400000 and time.process_time() < deadline - 3.0:
            for fac in (1.25, 1.5, 2.0):
                if time.process_time() >= deadline - 3.0:
                    break
                hu = _densify(_resample_smooth(best, int(best.size * fac)))
                hu, ru = _polish(hu, R_of(hu), deadline - 1.5, rounds=1)
                if ru > bestR + 1e-13:
                    best, bestR = hu, ru
                    print("iter %d upsample x%.2f R=%.7f N=%d" %
                          (it, fac, bestR, best.size))
                    improved = True
                    break
        if not improved and it > 2 and time.process_time() < deadline - 2.5:
            rng = np.random.default_rng(int(time.process_time() * 1e6) % (2**32))
            hp = best.copy()
            pos = np.flatnonzero(hp > 0)
            if pos.size > 0:
                k = max(1, pos.size // 80)
                sel = rng.choice(pos, size=min(k, pos.size), replace=False)
                hp[sel] *= (1.0 + 0.02 * rng.standard_normal(sel.size))
                hp = _rescale(np.clip(hp, 0, None))
                hp, rp = _polish(hp, R_of(hp), deadline - 1.0, rounds=1)
                if rp > bestR + 1e-13:
                    best, bestR = hp, rp
                    print("iter %d perturb R=%.7f" % (it, bestR))
                    improved = True
        if not improved and time.process_time() >= deadline - 1.5:
            break

    print("final R=%.7f (N=%d, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * _band_frac(best, 0.001),
           100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h, eps=1e-10):
    """Tie-gradient: average max-gradient over all knots within eps of max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    mask = Lf >= mx - eps * mx
    cnt = mask.sum()
    gLf = -dq / num
    gLf[mask] += 1.0 / (cnt * mx)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, a, q):
    """CVaR soft-max surrogate with soft indicator."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    # threshold at q-quantile of Lf
    thr = np.quantile(Lf, q)
    scale = max(a * mx, 1e-12)
    z = np.clip((Lf - thr) / scale, -60.0, 60.0)
    w = 1.0 / (1.0 + np.exp(-z))
    Zw = w.sum()
    if Zw <= 0:
        return _fun_grad(h)
    wn = w / Zw
    sm = np.sum(wn * Lf)
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num + wn / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fg, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, fg, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.2, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _frac_near_max(h, frac=0.001):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _box_down(h, target):
    n = h.size
    if n <= target:
        return h
    k = int(np.ceil(n / target))
    m = n // k
    if m < 1:
        return h
    hh = h[:m * k].reshape(m, k)
    return hh.mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    fallback_alt = None
    fallback_altR = -1.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            if base.size > 250000:
                down = _box_down(base, 210000)
                down = _rescale(down)
                fallback_alt = down
                fallback_altR = R_of(down)
                base = down
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_bestR = bestR
    print("base R=%.9f (N=%d, zero=%.3f, near=%.4f)" %
          (bestR, best.size, _zero_frac(best), _frac_near_max(best)))

    def _try(h, tag):
        nonlocal best, bestR
        if h is None:
            return False
        h = _rescale(np.clip(h, 0, None))
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR = h.copy(), r
            print("  %s R=%.9f (N=%d, zero=%.3f, near=%.4f)" %
                  (tag, bestR, best.size, _zero_frac(best), _frac_near_max(best)))
            return True
        return False

    # ---- Exact-R rounds ----
    rnd = 0
    while time.process_time() < deadline - 3.0:
        rnd += 1
        r_before = bestR
        round_dl = min(deadline - 2.5, time.process_time() + 20.0)

        # (1) full-array tie-gradient L-BFGS
        ht = _lbfgs(best, _fun_grad_tie, 300, min(round_dl, time.process_time() + 6.0))
        _try(ht, "r%d tie" % rnd)

        # (2) CVaR rungs
        for (a, q) in [(0.5, 0.95), (0.25, 0.98), (0.1, 0.995)]:
            if time.process_time() >= round_dl - 0.5:
                break
            fg = (lambda hh, a=a, q=q: _fun_grad_cvar(hh, a, q))
            ht = _lbfgs(best, fg, 150, min(round_dl, time.process_time() + 4.0))
            _try(ht, "r%d cvar(%.2f,%.3f)" % (rnd, a, q))

        # (3) peak-window tie polishes
        for pad in [0.20, 0.08, 0.03]:
            if time.process_time() >= round_dl - 0.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=32)
            ht = _lbfgs_block(best, win, _fun_grad_tie, 300,
                              min(round_dl, time.process_time() + 4.0))
            _try(ht, "r%d peak%.2f" % (rnd, pad))

        gain = bestR - r_before
        print("round %d gain=%.3e best=%.9f" % (rnd, gain, bestR))

        if gain < 1e-7:
            # jitter escape
            if time.process_time() >= deadline - 3.0:
                break
            rng = np.random.default_rng(12345 + rnd)
            hj = best.copy()
            pos = hj > 0
            noise = rng.normal(0.0, 1e-3, size=hj.size)
            hj[pos] = hj[pos] * np.exp(noise[pos])
            hj = _rescale(hj)
            rj = R_of(hj)
            if rj > bestR + 1e-14:
                best, bestR = hj, rj
                print("  jitter R=%.9f" % bestR)
            win = _peak_window(best, pad_frac=0.10, extra=48)
            ht = _lbfgs_block(best, win, _fun_grad_tie, 300,
                              min(deadline - 2.5, time.process_time() + 5.0))
            if _try(ht, "r%d jitter-peak" % rnd):
                continue
            # no gain from jitter -> stop rounds
            print("round %d saturated, stopping rounds" % rnd)
            break

    # ---- Final trailing tie polish ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs(best, _fun_grad_tie, 300, deadline - 0.5)
        _try(ht, "final tie")

    print("final R=%.9f (start %.9f, N=%d, zero=%.3f, near=%.4f)" %
          (bestR, start_bestR, best.size, _zero_frac(best), _frac_near_max(best)))

    result = {"best": best}
    if fallback_alt is not None and fallback_alt.size != best.size and fallback_altR < bestR:
        result["alternative"] = fallback_alt
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
