    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_shape(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if shape:
        fg = _fun_grad_shape
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


# ---------------- hard-max machinery ----------------

def _peak_window(h, tol=0.9995, pad_frac=0.3, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _Lm_and_band(h):
    """Return (L_m value, band index set) using band mean if multiple near max."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, np.array([0])
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-6))
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    return float(Lf[idx].mean()), idx


def _solve_alpha(h, p, Lm_target=1.0):
    """Solve L_m(h + alpha*p) = Lm_target for alpha, quadratic in alpha.
    L_m is linear in h (convolution), so L_m(h+alpha p) = L_m(h) + alpha * dLm.
    Actually L_m is a knot of conv(h,h) which is quadratic in h. So:
      L_m(h+alpha p) = L_m(h) + 2 alpha * <p, conv-part> + alpha^2 * L_m(p)
    We compute via knots of (h+alpha p) directly: quadratic in alpha.
    """
    # Compute knots of h, p, and cross term
    # conv(h+ap, h+ap) = conv(h,h) + 2a conv(h,p) + a^2 conv(p,p)
    # Use band index from h's current max
    Lm0, idx = _Lm_and_band(h)
    # knot index j corresponds to conv index j-1 (since Lf = [0, conv, 0])
    ci = idx - 1
    valid = (ci >= 0) & (ci < h.size + h.size - 1)
    ci = ci[valid]
    if ci.size == 0:
        return None
    hh = _conv(h)
    hp = _conv_cross(h, p)
    pp = _conv(p)
    # quadratic: A a^2 + B a + C = 0, with C = mean(hh[ci]) - Lm_target
    A = float(np.mean(pp[ci]))
    B = 2.0 * float(np.mean(hp[ci]))
    C = float(np.mean(hh[ci])) - Lm_target
    # solve
    if abs(A) < 1e-30:
        if abs(B) < 1e-30:
            return None
        return -C / B
    disc = B * B - 4 * A * C
    if disc < 0:
        return None
    sq = np.sqrt(disc)
    r1 = (-B + sq) / (2 * A)
    r2 = (-B - sq) / (2 * A)
    # pick positive root nearest 1
    cands = [r for r in (r1, r2) if r > 1e-12]
    if not cands:
        return None
    cands.sort(key=lambda r: abs(r - 1.0))
    return cands[0]


def _conv_cross(h, p):
    n = h.size
    if n > 1500:
        return fftconvolve(h, p)
    return np.convolve(h, p)


def _hard_max_block(h0, free, maxiter, deadline, Lm_target=1.0):
    """L-BFGS on u(h) = -log Q + 2 log S (no max term), with hard-max step control."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_shape(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    # enforce hard max at step level: solve for alpha so L_m = Lm_target
    p = h2 - h
    if np.max(np.abs(p)) < 1e-30:
        return h0
    alpha = _solve_alpha(h, p, Lm_target)
    if alpha is None or not np.isfinite(alpha):
        return _rescale(h2)
    # feasibility: no negative entries
    for _ in range(40):
        trial = h + alpha * p
        if np.all(trial >= -1e-12):
            break
        alpha *= 0.5
    trial = np.clip(h + alpha * p, 0.0, None)
    # verify Lm
    Lm, _ = _Lm_and_band(trial)
    if abs(Lm - Lm_target) > 1e-6:
        # fall back to rescale
        return _rescale(trial)
    return trial


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N = best.size

    # ---- normalize sum(h)=1 for hard-max phase ----
    work = best.copy()
    s0 = work.sum()
    if s0 > 0:
        work = work / s0
    # rescale so Lm = 1
    Lm0, _ = _Lm_and_band(work)
    if Lm0 > 0:
        work = work / np.sqrt(Lm0)
    workR = R_of(work)
    print("hard-max init: R=%.12f Lm=%.10f" % (workR, _Lm_and_band(work)[0]))

    hard_best = work.copy()
    hardR = workR

    # ---- Phase 1: three full-array blocks of 150 iters ----
    reserve = 6.0
    for blk in range(3):
        if time.process_time() >= deadline - reserve:
            break
        tlim = min(deadline - reserve, time.process_time() + 8.0)
        cand = _hard_max_block(work, np.arange(N), 150, tlim, Lm_target=1.0)
        r = R_of(cand)
        Lm, _ = _Lm_and_band(cand)
        print("phase1 blk %d: R=%.12f |Lm-1|=%.2e" % (blk + 1, r, abs(Lm - 1.0)))
        if r > workR + 1e-15:
            work = cand
            workR = r
            if r > hardR:
                hardR = r
                hard_best = cand.copy()

    print("phase1 done R=%.12f" % hardR)

    # ---- Phase 2: peak-window blocks with shrinking pad ----
    for pad in (0.3, 0.1, 0.03):
        if time.process_time() >= deadline - reserve:
            break
        win = _peak_window(work, tol=0.9995, pad_frac=pad)
        tlim = min(deadline - reserve, time.process_time() + 5.0)
        cand = _hard_max_block(work, win, 150, tlim, Lm_target=1.0)
        r = R_of(cand)
        Lm, _ = _Lm_and_band(cand)
        print("phase2 pad=%.2f: R=%.12f |Lm-1|=%.2e (win=%d)"
              % (pad, r, abs(Lm - 1.0), win.size))
        if r > workR + 1e-15:
            work = cand
            workR = r
            if r > hardR:
                hardR = r
                hard_best = cand.copy()

    print("phase2 done R=%.12f" % hardR)

    # ---- Phase 3: final exact-R tie-gradient polish ----
    if time.process_time() < deadline - 0.5:
        tlim = deadline - 0.3
        pol = _lbfgs_block(hard_best, np.arange(N), 300, tlim, tie=True)
        rp = R_of(pol)
        print("final tie polish R=%.12f" % rp)
        if rp > hardR + 1e-15:
            hard_best = pol.copy()
            hardR = rp

    # ---- compare to start ----
    if hardR > bestR + 1e-15:
        best = hard_best.copy()
        bestR = hardR

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if hardR > startR + 1e-14 and hardR < bestR - 1e-14:
        result["alternative"] = hard_best
    elif bestR <= startR + 1e-14 and hardR > startR - 1e-14:
        result["alternative"] = hard_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _detect_staircase(h):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in (1, 2, 3, 4, 5, 8, 16, 32, 64):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-8:
            return c, p
    return None, 1


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def _construct_initial(N):
    i = np.arange(N, dtype=float)
    h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
    return _rescale(h)


def _upsample(start, factor=2):
    """Refine a solution onto a finer grid (linear interp then rescale)."""
    n = start.size
    m = n * factor
    xo = np.linspace(0.0, 1.0, n, endpoint=False)
    xn = np.linspace(0.0, 1.0, m, endpoint=False)
    h = np.interp(xn, xo, start, left=start[0], right=start[-1])
    h = np.clip(h, 0, None)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    best = None
    startR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)

    if best is None:
        best = _construct_initial(16384)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f N=%d" % (bestR, best.size))

    rng = np.random.default_rng(2024)

    # ---- Phase 1: burst of local L-BFGS polish with tie-aware gradient,
    #              sweeping across a band of the peak region and full-block.
    # This reliably improves a converged start a bit more by re-optimising
    # under the exact tie objective at progressively wider windows.
    phase1_end = t0 + budget_seconds * 0.45
    win_pads = [0.20, 0.12, 0.08, 0.05, 0.03, 0.02, 0.01]
    cyc = 0
    while time.process_time() < phase1_end - 2.0:
        cyc += 1
        improved = False
        for pad in win_pads:
            if time.process_time() >= phase1_end - 1.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 500,
                              min(phase1_end - 0.5,
                                  time.process_time() + 5.0), tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                improved = True
        # full-vector polish
        if time.process_time() < phase1_end - 1.0:
            ht = _lbfgs_block(best, np.arange(best.size), 300,
                              min(phase1_end - 0.5,
                                  time.process_time() + 5.0), tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                improved = True
        f01, f1, f5 = _nearmax_fracs(best)
        print("  p1 cyc=%d R=%.9f near=%.3f/%.3f/%.3f"
              % (cyc, bestR, f01, f1, f5))
        if not improved and cyc > 1:
            break

    # ---- Phase 2: try refinement to a finer grid, then re-polish.
    # Upsampling changes the effective resolution; local L-BFGS can find
    # slightly better shapes on the finer grid. Only accept if it wins.
    phase2_end = t0 + budget_seconds * 0.72
    if best.size <= 500000 and time.process_time() < phase2_end - 3.0:
        for factor in (2, 3):
            if time.process_time() >= phase2_end - 2.0:
                break
            hu = _upsample(best, factor)
            if hu.size > 1000000:
                continue
            ru = R_of(hu)
            # local polish on finer grid
            win = _peak_window(hu, pad_frac=0.15, extra=256)
            ht = _lbfgs_block(hu, win, 400,
                              min(phase2_end - 1.0,
                                  time.process_time() + 8.0), tie=True)
            r = R_of(ht)
            if r > ru + 1e-15:
                ru, hu = r, ht
            if ru > bestR + 1e-15:
                best, bestR = hu.copy(), ru
                print("  p2 up x%d ACCEPT R=%.9f N=%d"
                      % (factor, bestR, best.size))

    # ---- Phase 3: strong final polish on the (possibly refined) best.
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 2.0:
        ht = _lbfgs_block(best, np.arange(best.size), 800, fd - 1.0, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        # last peak ladder
        for pad in (0.04, 0.02, 0.01):
            if time.process_time() >= fd - 0.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=64)
            ht = _lbfgs_block(best, win, 400,
                              min(fd - 0.3, time.process_time() + 3.0), tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14 and best.size != start.size:
        result["alternative"] = best
    return result

