    artifacts before re-optimising at finer resolution."""
    if factor <= 1:
        return h
    n = h.size
    m = n * factor
    # tent-ish kernel of width ~2*factor
    k = np.ones(factor)
    k = np.convolve(k, k)  # triangular
    k = k / k.sum()
    up = np.interp(np.linspace(0, n - 1, m), np.arange(n), h)
    # pad and smooth
    pad = k.size
    up2 = np.concatenate((np.full(pad, up[0]), up, np.full(pad, up[-1])))
    sm = np.convolve(up2, k, mode='same')[pad:pad + m]
    return np.clip(sm, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    alt = None
    altR = -1.0
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    N0 = best.size

    # ---- NEW IDEA: smooth-upsample the start to finer resolution, then
    # refine. This lets the optimizer reshape the peak more finely. ----
    refined_candidates = []
    for fac in (2,):
        if N0 * fac <= 900000:
            hu = _rescale(_smooth_upsample(best, fac))
            refined_candidates.append(hu)

    race_end = t0 + min(budget_seconds * 0.55, 32.0)
    for i, cand in enumerate(refined_candidates):
        if time.process_time() >= race_end - 1.0:
            break
        slice_end = min(race_end, time.process_time() + 9.0)
        h_t = _lbfgs_block(cand, np.arange(cand.size), 400, slice_end - 0.5,
                           beta=1e6)
        if time.process_time() < slice_end - 0.5:
