                               pads=(0.10, 0.06, 0.04), iters=200, tie=True)
        r_t = R_of(h_t)
        print("smoothup x%d R=%.9f dR=%+.3e ties=%d zero_frac=%.4f"
              % (i + 1, r_t, r_t - startR, _tie_count(h_t), _zero_frac(h_t)))
        if r_t > bestR + 1e-15:
