    # ---- full polish loop on best ----
    loop_end = t0 + min(budget_seconds * 0.82, 49.0)
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 8.0)
        h_t = _lbfgs_block(best, np.arange(best.size), 600, slice_end - 3.0,
                           tie=True)
        r_t = R_of(h_t)
        dR = r_t - bestR
        accepted = r_t > bestR + 1e-15
