import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, q, a):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad_tie(h)
    v = np.quantile(Lf, q)
    band = Lf >= v
    nb = int(band.sum())
    if nb <= 0:
        return _fun_grad_tie(h)
    cv = float(Lf[band].mean())
    if cv <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    m = int(np.argmax(Lf))
    gLf[m] += (1.0 - a) / M
    gLf[band] += a / (nb * cv)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (1.0 - a) * np.log(M) + a * np.log(cv)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, mode='hard', cvar=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if mode == 'cvar' and cvar is not None:
        q, a = cvar
        fg = (lambda hh: _fun_grad_cvar(hh, q, a))
    elif mode == 'tie':
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.4, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _gauss_smooth(h, sigma):
    if sigma <= 0.5:
        return h.copy()
    r = int(3 * sigma) + 1
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def _smooth_perturb(h, sigma, amp, seed):
    n = h.size
    rng = np.random.RandomState(seed)
    m = max(16, n // 64)
    noise = rng.randn(m)
    xp = np.linspace(0, 1, m)
    xi = np.linspace(0, 1, n)
    p = np.interp(xi, xp, noise)
    return np.clip(h * np.exp(amp * p), 0, None)


def _polish(h, deadline, maxiter=500, mode='hard', cvar=None,
           fracs=((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64))):
    """Alternate full-block and peak-window L-BFGS; return best h found."""
    best = h
    bestR = R_of(h)
    h = _lbfgs_block(best, np.arange(best.size), maxiter, deadline, mode=mode, cvar=cvar)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r
    for frac, extra in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, tol=0.999, pad_frac=frac, extra=extra)
        h = _lbfgs_block(best, win, maxiter, deadline, mode=mode, cvar=cvar)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size

    alt = None
    altR = 0.0

    # NEW IDEA: flatten the maximum via a CVaR (band-averaged) surrogate of the
    # max.  Instead of pushing a single knot up (hard max) or a softmax (which
    # still peaks), we average the top-q quantile band and reward raising *all*
    # of them.  This grows a genuinely flat plateau of near-equal peak knots,
    # giving a wider, flatter f*f peak -> larger ||f*f||_2^2 at fixed ||.||_inf.
    # We anneal: q shrinks / a grows from soft (band) to hard (max) so the
    # final objective matches the true R.
    if time.process_time() < deadline - 18.0:
        h = best.copy()
        sched = [(0.10, 0.6), (0.05, 0.7), (0.02, 0.8), (0.01, 0.9)]
        for q, a in sched:
            if time.process_time() >= deadline - 15.0:
                break
            h = _polish(h, deadline, maxiter=400, mode='cvar', cvar=(q, a),
                        fracs=((0.10, 4), (0.25, 16), (0.50, 32)))
            h = _lbfgs_block(h, np.arange(N), 400, deadline, mode='hard')
            r = R_of(h)
            print("cvar q=%.3f a=%.2f R=%.7f" % (q, a, r))
        # finish with hard-max polish
        h = _polish(h, deadline, maxiter=600, mode='hard')
        r = R_of(h)
        print("cvar-anneal final R=%.7f" % r)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("cvar wins R=%.7f" % bestR)

    # Tie-gradient polish: treat all near-max knots equally so the plateau
    # can settle at exactly equal heights.
    if time.process_time() < deadline - 12.0:
        h = _lbfgs_block(best, np.arange(N), 500, deadline, mode='tie')
        h = _polish(h, deadline, maxiter=400, mode='tie')
        r = R_of(h)
        print("tie R=%.7f" % r)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("tie wins R=%.7f" % bestR)

    # Smooth multiplicative perturbations from the improved best.
    perturb_specs = [
        (max(2.0, N / 300.0), 0.05, 11),
        (max(2.0, N / 300.0), 0.10, 12),
        (max(4.0, N / 150.0), 0.05, 13),
    ]
    for sigma, amp, seed in perturb_specs:
        if time.process_time() >= deadline - 6.0:
            break
        hp = _rescale(_smooth_perturb(best, sigma, amp, seed))
        hp = _polish(hp, deadline, maxiter=400, mode='hard')
        r = R_of(hp)
        print("perturb s=%.1f a=%.2f R=%.7f" % (sigma, amp, r))
        if r > altR:
            alt, altR = hp, r
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # Phase exploration.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _rescale(_phase_shift(best, delta))
        if hp.sum() <= 0:
            continue
        hp = _polish(hp, deadline, maxiter=500, mode='hard')
        r = R_of(hp)
        print("phase %+.2f R=%.7f" % (delta, r))
        if r > altR:
            alt, altR = hp, r
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # Final loop: keep the CVaR-to-hard cycle going until the budget runs out.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_block(best, np.arange(N), 800, deadline, mode='hard')
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        if stall >= 1:
            h = _lbfgs_block(best, np.arange(N), 400, deadline, mode='cvar',
                             cvar=(0.02, 0.85))
            h = _lbfgs_block(h, np.arange(N), 400, deadline, mode='hard')
        else:
            win = _peak_window(best, tol=0.999, pad_frac=0.4, extra=24)
            h = _lbfgs_block(best, win, 500, deadline, mode='hard')
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


# ---- Hard-max step control machinery (the experiment) ----

def _fun_grad_nomax(h):
    """u(h) = -log Q(h) + 2 log S(h); no inf-norm term."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    gLf = -dq / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _peak_set(Lf, tol=1e-6):
    mx = Lf.max()
    if mx <= 0:
        return np.array([int(np.argmax(Lf))])
    idx = np.flatnonzero(Lf >= mx - tol * max(1.0, abs(mx)))
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    return idx


def _Lm_of(h, peaks):
    Lf = _knots(h)
    return float(np.mean(Lf[peaks])), Lf


def _step_control(h, p, peaks, Lm_target=1.0):
    """Find alpha>0 with L_m(h+alpha p) = Lm_target, positive root nearest 1.
    L_m is quadratic in alpha (since knots are quadratic in h). We evaluate
    L_m at alpha=0,1,2 and fit a quadratic, then refine."""
    def Lm_at(a):
        hh = h + a * p
        Lf = _knots(hh)
        return float(np.mean(Lf[peaks]))

    L0 = Lm_at(0.0)
    L1 = Lm_at(1.0)
    L2 = Lm_at(2.0)
    # quadratic L(a) = A a^2 + B a + C
    C = L0
    # L1 = A + B + C ; L2 = 4A + 2B + C
    # B = L1 - C - A ; L2 = 4A + 2(L1-C-A) + C = 2A + 2L1 - C
    A = (L2 - 2.0 * L1 + C) / 2.0
    B = L1 - C - A
    # solve A a^2 + B a + (C - target) = 0
    target = Lm_target
    c0 = C - target
    if abs(A) < 1e-18:
        if abs(B) < 1e-18:
            return 1.0
        a = -c0 / B
        return a if a > 0 else 1.0
    disc = B * B - 4.0 * A * c0
    if disc < 0:
        return 1.0
    sq = np.sqrt(disc)
    r1 = (-B + sq) / (2.0 * A)
    r2 = (-B - sq) / (2.0 * A)
    roots = [r for r in (r1, r2) if r > 0 and np.isfinite(r)]
    if not roots:
        return 1.0
    roots.sort(key=lambda r: abs(r - 1.0))
    return roots[0]


def _lbfgs_hardmax(h0, free, maxiter, deadline, peaks_tol=1e-6):
    """L-BFGS-like descent using scipy but with hard-max step control applied
    to the returned point. We run a modest L-BFGS on u (no max term) then
    rescale to enforce L_m = 1 exactly via step control along (h_new - h)."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_nomax(hh)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.3:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h_new = h.copy()
    h_new[active] = np.clip(res.x, 0.0, None)
    if h_new.sum() <= 0:
        return h0
    # hard-max step control along direction p = h_new - h
    p = h_new - h
    Lf = _knots(h)
    peaks = _peak_set(Lf, peaks_tol)
    # target: current Lm (we want to keep max at its value, then rescale)
    Lm0 = float(np.mean(Lf[peaks]))
    if Lm0 <= 0:
        return _rescale(h_new)
    # We want L_m(h + alpha p) = Lm0 (preserve max), then rescale so max=1.
    alpha = _step_control(h, p, peaks, Lm_target=Lm0)
    # halve until nonnegative
    for _ in range(40):
        hh = h + alpha * p
        if np.all(hh >= -1e-12):
            break
        alpha *= 0.5
    hh = np.clip(h + alpha * p, 0.0, None)
    if hh.sum() <= 0:
        return h0
    # check |Lm - Lm0| small; if not, fall back to plain rescale
    Lf2 = _knots(hh)
    Lm2 = float(np.mean(Lf2[peaks]))
    if abs(Lm2 - Lm0) > 1e-10 * max(1.0, abs(Lm0)):
        # fall back: rescale h_new so its max = 1
        return _rescale(h_new)
    return _rescale(hh)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _Lm_dev(h, tol=1e-6):
    Lf = _knots(h)
    peaks = _peak_set(Lf, tol)
    return float(np.mean(Lf[peaks]))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 4.0  # 4 s margin
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N = best.size
    # Normalize sum(h) = 1 for the u(h) objective
    best = best / best.sum()
    bestR = R_of(best)

    # ---- Phase 1: three full-array hard-max blocks ----
    full_deadline = t0 + budget_seconds * 0.55
    all_idx = np.arange(N)
    for blk in range(3):
        if time.process_time() >= full_deadline - 1.0:
            break
        ht = _lbfgs_hardmax(best, all_idx, 150, full_deadline)
        r = R_of(ht)
        Lm = _Lm_dev(ht)
        print("full block=%d R=%.9f |Lm-1|=%.2e" % (blk, r, abs(Lm - 1.0)))
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("NEW BEST (full %d) R=%.9f" % (blk, bestR))

    # ---- Phase 2: peak-window hard-max blocks ----
    peak_deadline = t0 + budget_seconds * 0.82
    for pad in (0.3, 0.1, 0.03):
        if time.process_time() >= peak_deadline - 1.0:
            break
        win = _peak_window(best, tol=0.9995, pad_frac=pad, extra=128)
        ht = _lbfgs_hardmax(best, win, 200, peak_deadline)
        r = R_of(ht)
        Lm = _Lm_dev(ht)
        print("peak pad=%.2f R=%.9f |Lm-1|=%.2e" % (pad, r, abs(Lm - 1.0)))
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("NEW BEST (peak %.2f) R=%.9f" % (pad, bestR))

    # ---- Phase 3: exact tie-gradient L-BFGS (300 iters) ----
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all_pos(best, 300, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        Lm = _Lm_dev(ht)
        print("tie-polish R=%.9f |Lm-1|=%.2e" % (r, abs(Lm - 1.0)))
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("NEW BEST (tie) R=%.9f" % bestR)

    # ---- Phase 4: 2% padded peak tie polish ----
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, tol=0.9995, pad_frac=0.02, extra=64)
        ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("NEW BEST (peak-tie) R=%.9f" % bestR)

    # Never return below start
    if bestR < start_bestR - 1e-14:
        best = start_best.copy()
        bestR = start_bestR

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, deadline, peak_pads=(0.12, 0.08, 0.05, 0.03)):
    best = h.copy()
    bestR = R_of(best)
    ht = _lbfgs_all(best, 400, deadline)
    r = R_of(ht)
    if r > bestR:
        best, bestR = ht, r
    for pad in peak_pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.12f (N=%d)" % (bestR, N))

    alt_best = None
    altR = -1.0

    # Phase A: alternating full / peak-window polish on `best` until ~55% budget.
    phaseA_end = t0 + budget_seconds * 0.55
    rounds = 0
    while time.process_time() < phaseA_end - 1.0:
        rounds += 1
        slice_end = min(phaseA_end, time.process_time() + 0.18 * budget_seconds)
        ht = _lbfgs_all(best, 400, slice_end)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("  phaseA all NEW BEST R=%.12f" % bestR)
        elif r > altR:
            alt_best, altR = ht, r
        for pad in (0.10, 0.06, 0.04, 0.025):
            if time.process_time() >= slice_end - 0.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=96)
            ht = _lbfgs_block(best, win, 400, slice_end)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht, r
                print("  phaseA peak(%g) NEW BEST R=%.12f" % (pad, bestR))
            elif r > altR:
                alt_best, altR = ht, r

    # Phase B: perturb-then-polish restarts, keep improving until near deadline.
    rng = np.random.default_rng(20240607)
    amps = [1e-4, 2e-4, 4e-4, 8e-4, 1.5e-3, 3e-3]
    ri = 0
    n_acc = 0
    while time.process_time() < deadline - 2.0:
        amp = amps[ri % len(amps)]
        ri += 1
        cand = best.copy()
        nz = cand > 0
        if nz.sum() == 0:
            break
        cand[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
        cand = _rescale(cand)
        slice_end = min(deadline - 1.0,
                        time.process_time() + 0.08 * budget_seconds)
        cand, r = _polish(cand, slice_end, peak_pads=(0.10, 0.06, 0.04))
        if r > bestR + 1e-15:
            best, bestR = cand, r
            n_acc += 1
            print("  restart %d amp=%.4f NEW BEST R=%.12f" % (ri, amp, bestR))
        elif r > altR:
            alt_best, altR = cand, r

    # Final polish on best.
    if time.process_time() < deadline - 1.0:
        best, bestR = _polish(best, deadline - 0.5)

    print("rounds=%d restarts=%d accepted=%d final R=%.12f (start %.12f)" %
          (rounds, ri, n_acc, bestR, startR))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and altR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = idx.min(); hi = idx.max()
    span = hi - lo
    pad = int(span * pad_frac) + extra
    lo = max(0, lo - pad); hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(start, Nf):
    start = np.asarray(start, dtype=float)
    n = start.size
    if n == Nf:
        return start.copy()
    c = np.concatenate([[0.0], np.cumsum(start)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nf)
    xs = np.linspace(0.0, 1.0, Nf + 1)
    old = np.linspace(0.0, 1.0, n + 1)
    cm = np.interp(xs, old, c)
    return np.diff(cm) * Nf


def _smooth(h, w):
    if w <= 1:
        return h
    k = np.ones(w) / w
    return np.convolve(h, k, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    np.random.seed(12345)

    if start is not None:
        s = np.asarray(start, dtype=float)
        r_start = R_of(s)
    else:
        s = None
        r_start = -1.0

    # Start from a good baseline shape. If start given, use it; else build a
    # typical good shape (near-parabola with bumps).
    if s is not None:
        N = min(max(s.size, 2048), 16384)
        h = _resample(s, N)
    else:
        N = 8192
        x = (np.arange(N) + 0.5) / N
        h = 1.0 + 0.8 * np.sin(np.pi * x) + 0.3 * np.cos(4 * np.pi * x)
        h = np.clip(h, 0.05, None)

    h = _rescale(h)
    r_best = R_of(h)
    h_best = h.copy()
    print(f"init N={h.size} R={r_best:.6f}")

    # Alt-refine: multiple passes of full + local + beta + flat
    passes = 0
    while time.process_time() < deadline - 2.0:
        passes += 1
        # full refine
        h = _lbfgs_block(h, np.arange(h.size), 400, deadline)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"pass {passes} full R={r:.6f} best={r_best:.6f}")

        if time.process_time() > deadline - 2.0:
            break

        # local refine on peak window
        win = _peak_window(h, tol=0.999, pad_frac=0.3, extra=128)
        h = _lbfgs_block(h, win, 400, deadline)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"pass {passes} local R={r:.6f} best={r_best:.6f}")

        if time.process_time() > deadline - 2.0:
            break

        # beta (softmax) refine to sharpen the peak
        for beta in (1e3, 1e5, 1e7):
            if time.process_time() > deadline - 1.5:
                break
            h = _lbfgs_block(h, np.arange(h.size), 150, deadline, beta=beta)
            r = R_of(h)
            if r > r_best:
                r_best = r; h_best = h.copy()
            print(f"pass {passes} beta={beta:.0e} R={r:.6f} best={r_best:.6f}")

        if time.process_time() > deadline - 1.5:
            break

        # flat refine (drives L towards constant to increase ||L||_2^2/||L||_inf)
        h = _lbfgs_block(h, np.arange(h.size), 200, deadline, flat=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"pass {passes} flat R={r:.6f} best={r_best:.6f}")

        # tie refine (handles degenerate maxima)
        h = _lbfgs_block(h, np.arange(h.size), 200, deadline, tie=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()

        # occasional smoothing to escape
        if passes % 2 == 0:
            h = _smooth(h, 3)
            h = _rescale(h)

        # if not improving, restart from best with small perturbation
        if r_best <= r_best - 1e-12 and passes > 2:
            pass

    # try upsampling to 2x for a tiny gain
    if time.process_time() < deadline - 1.0:
        h2 = np.repeat(h_best, 2)
        h2 = _rescale(h2)
        r2 = R_of(h2)
        if r2 > r_best:
            r2b = _lbfgs_block(h2, np.arange(h2.size), 200, deadline)
            r2c = R_of(r2b)
            if r2c > r_best:
                r_best = r2c; h_best = r2b
            else:
                r_best = r2; h_best = h2
            print(f"2x R={r_best:.6f}")

    h_best = _rescale(h_best)
    if s is not None and r_best < r_start:
        return {"best": s, "alternative": h_best}
    return h_best

