    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_shape(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if shape:
        fg = _fun_grad_shape
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.3, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _Lm_and_band(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, np.array([0])
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-6))
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    return float(Lf[idx].mean()), idx


def _conv_cross(h, p):
    n = h.size
    if n > 1500:
        return fftconvolve(h, p)
    return np.convolve(h, p)


def _solve_alpha(h, p, Lm_target=1.0):
    Lm0, idx = _Lm_and_band(h)
    ci = idx - 1
    valid = (ci >= 0) & (ci < h.size + h.size - 1)
    ci = ci[valid]
    if ci.size == 0:
        return None
    hh = _conv(h)
    hp = _conv_cross(h, p)
    pp = _conv(p)
    A = float(np.mean(pp[ci]))
    B = 2.0 * float(np.mean(hp[ci]))
    C = float(np.mean(hh[ci])) - Lm_target
    if abs(A) < 1e-30:
        if abs(B) < 1e-30:
            return None
        return -C / B
    disc = B * B - 4 * A * C
    if disc < 0:
        return None
    sq = np.sqrt(disc)
    r1 = (-B + sq) / (2 * A)
    r2 = (-B - sq) / (2 * A)
    cands = [r for r in (r1, r2) if r > 1e-12]
    if not cands:
        return None
    cands.sort(key=lambda r: abs(r - 1.0))
    return cands[0]


def _hard_max_block(h0, free, maxiter, deadline, Lm_target=1.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_shape(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    p = h2 - h
    if np.max(np.abs(p)) < 1e-30:
        return h0
    alpha = _solve_alpha(h, p, Lm_target)
    if alpha is None or not np.isfinite(alpha):
        return _rescale(h2)
    for _ in range(40):
        trial = h + alpha * p
        if np.all(trial >= -1e-12):
            break
        alpha *= 0.5
    trial = np.clip(h + alpha * p, 0.0, None)
    Lm, _ = _Lm_and_band(trial)
    if abs(Lm - Lm_target) > 1e-6:
        return _rescale(trial)
    return trial


def _block_average(h, N0):
    """Mass-preserving block average from h (size N) to N0."""
    N = h.size
    if N == N0:
        return h.copy()
    edges = np.linspace(0, N, N0 + 1)
    out = np.empty(N0)
    for i in range(N0):
        lo = int(np.floor(edges[i]))
        hi = int(np.floor(edges[i + 1]))
        if hi <= lo:
            hi = lo + 1
        lo = min(lo, N - 1)
        hi = min(hi, N)
        out[i] = h[lo:hi].mean()
    return out


def _lift(h, N1):
    """Mass-preserving lift from h (size N0) to N1 by linear interpolation of cumulative mass."""
    N0 = h.size
    if N0 == N1:
        return h.copy()
    # cumulative mass at block edges
    cum = np.concatenate(([0.0], np.cumsum(h)))
    # target edges in source units
    edges = np.linspace(0, N0, N1 + 1)
    cum_at = np.interp(edges, np.arange(N0 + 1), cum)
    out = np.diff(cum_at)
    out = np.clip(out, 0, None)
    return out


def _normalize_hardmax(h):
    h = np.clip(h, 0, None)
    s = h.sum()
    if s > 0:
        h = h / s
    Lm, _ = _Lm_and_band(h)
    if Lm > 0:
        h = h / np.sqrt(Lm)
    return h


def _run_level(work, N, deadline, reserve, hard_best, hardR, level_name):
    """Run hard-max blocks at this level. Returns (work, hard_best, hardR)."""
    # three full-array blocks
    for blk in range(3):
        if time.process_time() >= deadline - reserve:
            break
        tlim = min(deadline - reserve, time.process_time() + 6.0)
        cand = _hard_max_block(work, np.arange(N), 150, tlim, Lm_target=1.0)
        r = R_of(cand)
        Lm, _ = _Lm_and_band(cand)
        print("%s full blk %d: R=%.12f |Lm-1|=%.2e" % (level_name, blk + 1, r, abs(Lm - 1.0)))
        if r > R_of(work) + 1e-15:
            work = cand
            if r > hardR:
                hardR = r
                hard_best = cand.copy()
    # peak-window blocks
    for pad in (0.2, 0.1, 0.05):
        if time.process_time() >= deadline - reserve:
            break
        win = _peak_window(work, tol=0.9995, pad_frac=pad)
        tlim = min(deadline - reserve, time.process_time() + 4.0)
        cand = _hard_max_block(work, win, 150, tlim, Lm_target=1.0)
        r = R_of(cand)
        Lm, _ = _Lm_and_band(cand)
        print("%s pad=%.2f: R=%.12f |Lm-1|=%.2e (win=%d)"
              % (level_name, pad, r, abs(Lm - 1.0), win.size))
        if r > R_of(work) + 1e-15:
            work = cand
            if r > hardR:
                hardR = r
                hard_best = cand.copy()
    # tie polish
    if time.process_time() < deadline - reserve - 0.5:
        tlim = deadline - reserve - 0.3
        pol = _lbfgs_block(work, np.arange(N), 200, tlim, tie=True)
        rp = R_of(pol)
        print("%s tie polish R=%.12f" % (level_name, rp))
        if rp > R_of(work) + 1e-15:
            work = pol
            if rp > hardR:
                hard_best = pol.copy()
                hardR = rp
    return work, hard_best, hardR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N_final = best.size

    # coarse-to-fine levels
    levels = [3281, 6562, 13124, N_final]
    levels = [L for L in levels if L <= N_final]
    if levels[-1] != N_final:
        levels.append(N_final)

    # start at coarsest
    work = _block_average(best, levels[0])
    work = _normalize_hardmax(work)
    hard_best = work.copy()
    hardR = R_of(work)
    print("coarse init N=%d R=%.12f" % (work.size, hardR))

    reserve = 4.0
    for li, N in enumerate(levels):
        if time.process_time() >= deadline - reserve:
            break
        if li > 0:
            work = _lift(work, N)
            work = _normalize_hardmax(work)
            r = R_of(work)
            print("lift to N=%d R=%.12f" % (N, r))
            if r > hardR:
                hard_best = work.copy()
                hardR = r
        work, hard_best, hardR = _run_level(
            work, N, deadline, reserve, hard_best, hardR, "L%d" % N)
        print("level N=%d done R=%.12f" % (N, hardR))

    # final: spend remaining time on shrinking peak windows at final N
    work = _lift(work, N_final) if work.size != N_final else work
    work = _normalize_hardmax(work)
    for pad in (0.05, 0.03, 0.02, 0.01, 0.005):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(work, tol=0.9995, pad_frac=pad, extra=64)
        tlim = deadline - 0.5
        cand = _hard_max_block(work, win, 200, tlim, Lm_target=1.0)
        r = R_of(cand)
        Lm, _ = _Lm_and_band(cand)
        print("final pad=%.3f: R=%.12f |Lm-1|=%.2e (win=%d)"
              % (pad, r, abs(Lm - 1.0), win.size))
        if r > R_of(work) + 1e-15:
            work = cand
            if r > hardR:
                hard_best = cand.copy()
                hardR = r

    # final tie polish
    if time.process_time() < deadline - 0.5:
        pol = _lbfgs_block(hard_best, np.arange(N_final), 300, deadline - 0.3, tie=True)
        rp = R_of(pol)
        print("final tie polish R=%.12f" % rp)
        if rp > hardR + 1e-15:
            hard_best = pol.copy()
            hardR = rp

    if hardR > bestR + 1e-15:
        best = hard_best.copy()
        bestR = hardR

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if hardR > startR + 1e-14 and hardR < bestR - 1e-14:
        result["alternative"] = hard_best
    elif bestR <= startR + 1e-14 and hardR > startR - 1e-14:
        result["alternative"] = hard_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, q):
    """CVaR / top-quantile surrogate: M_q = mean of largest (1-q) fraction."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = max(1, int(round((1.0 - q) * n)))
    if k >= n:
        k = n - 1
    # top-k indices
    idx = np.argpartition(-Lf, k - 1)[:k]
    Mq = Lf[idx].mean()
    if Mq <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[idx] += 1.0 / (Mq * k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Mq)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, cvar_q=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if cvar_q is not None:
        fg = (lambda hh: _fun_grad_cvar(hh, cvar_q))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _nearmax_frac_tight(h, frac=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _deficit_free(h, frac=0.15):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(h.size)
    gLf = (M - 2.0 * Lf) / M
    s = np.abs(_backprop(gLf, h))
    N = h.size
    k = max(1, int(frac * N))
    if k >= N:
        return np.arange(N)
    idx = np.argpartition(-s, k - 1)[:k]
    return np.sort(idx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase A: half-resolution quotient polish (kept from base) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.12
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase CVaR: the experiment ----
    # Normalize sum(h)=1 (R is scale invariant; helps numerics).
    def _norm1(h):
        s = h.sum()
        if s <= 0:
            return h
        return h / s

    cvar_deadline = t0 + budget_seconds * 0.72
    qs = (0.99, 0.995, 0.999, 0.9999)
    work = _norm1(best.copy())
    for q in qs:
        if time.process_time() >= cvar_deadline - 2.0:
            break
        ht = _lbfgs_all_pos(work, 200, cvar_deadline, cvar_q=q)
        rc = R_of(ht)
        nm = _nearmax_frac_tight(ht, 0.999)
        improved = offer(ht, 'cvar_q%.4f' % q)
        print("cvar q=%.4f R=%.9f (best %.9f) nearmax0.1%%=%.4f improved=%s"
              % (q, rc, bestR, nm, improved))
        # keep working from the better of the two for next q
        if rc > R_of(work):
            work = ht

    # ---- Exact tie-gradient polish (100 iters) ----
    if time.process_time() < cvar_deadline - 1.0:
        ht = _lbfgs_all_pos(best, 100, cvar_deadline, beta=0.0)
        offer(ht, 'tie_polish')

    # ---- Peak-window polishes pads 0.1 and 0.03 ----
    if time.process_time() < cvar_deadline - 1.0:
        ht = _peak_ladder(best, cvar_deadline, pads=(0.10, 0.03), iters=300)
        offer(ht, 'peak_cvar')

    # ---- Phase D: deficit-sensitivity rounds (kept from base) ----
    deficit_deadline = deadline - 8.0
    for rnd in range(2):
        if time.process_time() >= deficit_deadline - 2.0:
            break
        free = _deficit_free(best, frac=0.15)
        if free.size == 0:
            break
        ht = _lbfgs_block(best, free, 300, deficit_deadline, beta=1e6)
        ht = _lbfgs_block(ht, free, 300, deficit_deadline, beta=0.0)
        ht = _peak_ladder(ht, deficit_deadline, pads=(0.08, 0.05), iters=250)
        r = R_of(ht)
        improved = offer(ht, 'deficit_%d' % rnd)
        print("deficit round=%d freed=%d R=%.9f (best %.9f) improved=%s"
              % (rnd, free.size, r, bestR, improved))

    # ---- Phase B: high-beta sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=300)
        offer(ht, 'sharp')

    # ---- Final polish on best ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 1e10, 0.0), iters=300)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht.copy(), R_of(ht)
        print("NEW BEST (finalhi) R=%.9f" % bestR)
    ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=250)
    if R_of(ht2) > bestR + 1e-14:
        best, bestR = ht2.copy(), R_of(ht2)
        print("NEW BEST (finalpeak) R=%.9f" % bestR)

    # Never return below start.
    if start_best is not None and start_bestR > bestR + 1e-14:
        best, bestR = start_best.copy(), start_bestR
        print("reverted to start R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f, nearmax0.1%%=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best), _nearmax_frac_tight(best, 0.999)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _refine_resample(h, factor, deadline):
    """Upsample h by `factor` with linear interpolation, then polish."""
    if factor <= 1 or time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    m = (n - 1) * factor + 1
    xi = np.linspace(0, n - 1, m)
    h2 = np.interp(xi, np.arange(n), h)
    h2 = _rescale(np.clip(h2, 0, None))
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Try upsampling the start to a finer grid to escape discretization limits.
    # A step function's R is a smooth functional; finer grids allow sharper features.
    if start_best.size > 0 and start_best.size <= 200000:
        # pick factor so new N stays reasonable
        for factor in (2, 3):
            if time.process_time() >= deadline - 5.0:
                break
            newN = (start_best.size - 1) * factor + 1
            if newN > 900000:
                continue
            hu = _refine_resample(best, factor, deadline - 3.0)
            # quickly polish on the finer grid
            hu = _lbfgs_all_pos(hu, 400, deadline - 3.0, beta=0.0)
            ru = R_of(hu)
            print("  resample x%d -> N=%d R=%.7f" % (factor, hu.size, ru))
            if ru > bestR + 1e-9:
                best, bestR = hu.copy(), ru
                break  # keep the finer grid; further loops use it

    N = best.size
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 800, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 400, deadline - 2.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for (frac, extra, beta) in [(0.05, 64, 1e7), (0.10, 64, 1e8),
                                    (0.25, 128, 1e8), (0.40, 256, 1e8),
                                    (0.60, 512, 1e8)]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _window_polish_peak(best, deadline - 2.0, frac, extra,
                                     maxiter=300, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_log(best, 300, deadline - 2.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r

        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, N))

    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 4000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

