def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _upsample(h, factor):
    """Resample h to `factor` times the length via linear interpolation,
    preserving total mass per unit width approximately."""
    n = h.size
    m = n * factor
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 / factor
    xi = np.arange(n) + 0.5
    hp = np.interp(x, xi, h, left=h[0], right=h[-1])
    return np.clip(hp, 0.0, None)


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 4:
        return h
    hh = h[:m * factor].reshape(m, factor).mean(axis=1)
    return np.clip(hh, 0.0, None)


def run_cycle(best, bestR, deadline, maxiter_scale=1.0):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(600 * maxiter_scale), deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, int(300 * maxiter_scale), deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.15, 128, 1e8), (0.35, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        if win.size > 40000:
            continue
        ht = _lbfgs_block(best, win, maxiter=int(200 * maxiter_scale),
                          deadline=deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR, 0.0


def _report(tag, h, R):
    print("%s R=%.7f N=%d zeros=%.1f%%" % (tag, R, h.size, 100.0 * np.mean(h <= 0)))


def _polish(h, deadline):
    r = R_of(h)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(h, 250, deadline - 0.5, beta=0.0)
        rt = R_of(ht)
        if rt > r:
            h, r = ht, rt
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, pad_frac=0.15, extra=128)
        if win.size <= 60000:
            ht = _lbfgs_block(h, win, 200, deadline - 0.5, beta=1e7)
            rt = R_of(ht)
            if rt > r:
                h, r = ht, rt
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Try upsampled version: finer resolution often finds slightly higher R
    # because the true optimum is a continuous function.
    if time.process_time() < deadline - 2.0:
        up = _upsample(best, 2)
        upR = R_of(up)
        print("upsample x2 R=%.7f" % upR)
        up, upR = _polish(up, deadline - 1.5)
        print("polished x2 R=%.7f" % upR)
        if upR > bestR + 1e-13:
            best, bestR = up.copy(), upR
            _report("(up) accept", best, bestR)

    if time.process_time() < deadline - 1.5:
        best, bestR, _ = run_cycle(best, bestR, deadline - 1.5)
        _report("(1) cycle", best, bestR)

    # Random perturbation hops to escape local minima
    rng = np.random.default_rng(987654321)
    it = 0
    no_improve = 0
    while time.process_time() < deadline - 0.8:
        it += 1
        n = best.size
        # perturb a window
        wlen = int(rng.integers(max(16, n // 10), max(32, n // 3)))
        wlen = min(wlen, n)
        lo = int(rng.integers(0, n - wlen + 1))
        hi = lo + wlen
        hp = best.copy()
        amp = rng.uniform(0.01, 0.08)
        hp[lo:hi] = np.clip(hp[lo:hi] * (1.0 + amp * rng.standard_normal(wlen)), 0.0, None)
        hp = _rescale(hp)
        rp = R_of(hp)
        halo = 96
        flo = max(0, lo - halo)
        fhi = min(n, hi + halo)
        free = np.arange(flo, fhi)
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(hp, free, 200, deadline - 0.5, beta=1e7)
            rt = R_of(ht)
            if rt > rp:
                hp, rp = ht, rt
        if rp > bestR + 1e-13:
            best, bestR = hp.copy(), rp
            _report("(hop) %d" % it, best, bestR)
            no_improve = 0
        else:
            no_improve += 1
        # periodic global polish
        if it % 3 == 0 and time.process_time() < deadline - 0.8:
            ht = _lbfgs_all_pos(best, 300, deadline - 0.8, beta=0.0)
            rt = R_of(ht)
            if rt > bestR + 1e-13:
                best, bestR = ht.copy(), rt
                _report("(g) %d" % it, best, bestR)
                no_improve = 0
        if it > 200:
            break

    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-8))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_phi(h, M, w):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    r = np.maximum(Lf - M, 0.0)
    pen = w * np.sum(r * r)
    gLf = -dq / num
    gLf += 2.0 * w * r
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.99, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _peak_trim(h, deadline, tag, bestR_ref):
    """Peak-lowering sweep using tie-aware gradient, returns (h, R)."""
    cur = _rescale(h)
    best = cur.copy()
    bestR = R_of(cur)
    Lf = _knots(cur)
    Linf = Lf.max()
    if Linf <= 0:
        return best, bestR
    for mf in (0.9999, 0.999, 0.995, 0.99):
        M = mf * Linf
        for w in (1e2, 1e4, 1e6):
            if time.process_time() >= deadline - 0.5:
                break
            fg = (lambda hh, MM=M, ww=w: _fun_grad_phi(hh, MM, ww))
            cap = min(deadline - 0.3, time.process_time() + 2.0)
            hq = _lbfgs_log(cur, 150, cap, fg=fg)
            mx = _knots(hq).max()
            if mx > 0:
                hq = hq / np.sqrt(mx)
            rq = R_of(hq)
            if rq > bestR + 1e-14:
                best, bestR = hq.copy(), rq
            cur = hq
        if time.process_time() >= deadline - 0.5:
            break
    return best, bestR


def _refine(h):
    N = h.size
    sub = h[::2]
    up = np.interp(np.linspace(0, sub.size - 1, N), np.arange(sub.size), sub)
    return _rescale(up)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    hard = t0 + budget_seconds - 1.2

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    start_bestR = startR
    N = best.size
    print("base R=%.12f (N=%d, ties=%d)" % (bestR, N, _tie_count(best)))

    # Alternative branch: coarsen-refine to break the plateau (a different line)
    alt_best = None
    altR = -1.0
    if N >= 64 and time.process_time() < deadline - 4.0:
        cand = _refine(best)
        tlim = min(deadline - 2.0, time.process_time() + 6.0)
        cand = _lbfgs_block(cand, np.arange(N), 400, tlim, fg=_fun_grad_tie)
        r = R_of(cand)
        print("refine branch R=%.12f" % r)
        if r > altR:
            alt_best, altR = cand.copy(), r

    # Main loop: alternate peak-trim sweep and tie-aware full polish
    sweep = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        if time.process_time() < hard - 4.0:
            cap = min(hard - 2.0, time.process_time() + 6.0)
            ht, rt = _peak_trim(best, cap, "trim%d" % sweep, bestR)
            print("  [trim%d] R=%.12f %s" % (sweep, rt, "BEAT" if rt > bestR + 1e-14 else ""))
            if rt > bestR + 1e-14:
                best, bestR = ht, rt
                improved = True

        if time.process_time() < hard - 2.0:
            cap = min(hard - 1.0, time.process_time() + 4.0)
            ht = _lbfgs_log(best, 300, cap, fg=_fun_grad_tie)
            rt = R_of(ht)
            print("  [polish%d tie] R=%.12f %s" % (sweep, rt, "BEAT" if rt > bestR + 1e-14 else ""))
            if rt > bestR + 1e-14:
                best, bestR = ht, rt
                improved = True

        # window polish around the peak
        if time.process_time() < hard - 2.0:
            free = _peak_window(best, tol=0.98, pad_frac=0.5, extra=512)
            cap = min(hard - 1.0, time.process_time() + 2.5)
            hw = _lbfgs_block(best, free, 200, cap, fg=_fun_grad_tie)
            rw = R_of(hw)
            if rw > bestR + 1e-14:
                best, bestR = hw, rw
                improved = True

        # also try alt branch if it's competitive
        if alt_best is not None and time.process_time() < hard - 3.0:
            r0 = altR
            cap = min(hard - 2.0, time.process_time() + 3.0)
            ha = _lbfgs_log(alt_best, 200, cap, fg=_fun_grad_tie)
            ra = R_of(ha)
            if ra > altR:
                alt_best, altR = ha, ra
            if ra > bestR + 1e-14:
                best, bestR = ha, ra
                improved = True

        if not improved and sweep > 3:
            cap = min(hard - 1.0, time.process_time() + 3.0)
            ht = _lbfgs_log(best, 400, cap, fg=_fun_grad)
            rt = R_of(ht)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                print("    fallback R=%.12f" % bestR)
            else:
                break

    print("final R=%.12f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        alt = alt_best if (alt_best is not None and altR < bestR - 1e-12) else start_best
        return {"best": best, "alternative": alt}
    else:
        alt = alt_best if alt_best is not None else best
        return {"best": start_best, "alternative": alt}

