    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.99, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _peak_trim(h, deadline, tag, bestR_ref):
    """Peak-lowering sweep using tie-aware gradient, returns (h, R)."""
    cur = _rescale(h)
    best = cur.copy()
    bestR = R_of(cur)
    Lf = _knots(cur)
    Linf = Lf.max()
    if Linf <= 0:
        return best, bestR
    for mf in (0.9999, 0.999, 0.995, 0.99):
        M = mf * Linf
        for w in (1e2, 1e4, 1e6):
            if time.process_time() >= deadline - 0.5:
                break
            fg = (lambda hh, MM=M, ww=w: _fun_grad_phi(hh, MM, ww))
            cap = min(deadline - 0.3, time.process_time() + 2.0)
            hq = _lbfgs_log(cur, 150, cap, fg=fg)
            mx = _knots(hq).max()
            if mx > 0:
                hq = hq / np.sqrt(mx)
            rq = R_of(hq)
            if rq > bestR + 1e-14:
                best, bestR = hq.copy(), rq
            cur = hq
        if time.process_time() >= deadline - 0.5:
            break
    return best, bestR


def _refine(h):
    N = h.size
    sub = h[::2]
    up = np.interp(np.linspace(0, sub.size - 1, N), np.arange(sub.size), sub)
    return _rescale(up)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    hard = t0 + budget_seconds - 1.2

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    start_bestR = startR
    N = best.size
    print("base R=%.12f (N=%d, ties=%d)" % (bestR, N, _tie_count(best)))

    # Alternative branch: coarsen-refine to break the plateau (a different line)
    alt_best = None
    altR = -1.0
    if N >= 64 and time.process_time() < deadline - 4.0:
        cand = _refine(best)
        tlim = min(deadline - 2.0, time.process_time() + 6.0)
        cand = _lbfgs_block(cand, np.arange(N), 400, tlim, fg=_fun_grad_tie)
        r = R_of(cand)
        print("refine branch R=%.12f" % r)
        if r > altR:
            alt_best, altR = cand.copy(), r

    # Main loop: alternate peak-trim sweep and tie-aware full polish
    sweep = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        if time.process_time() < hard - 4.0:
            cap = min(hard - 2.0, time.process_time() + 6.0)
            ht, rt = _peak_trim(best, cap, "trim%d" % sweep, bestR)
            print("  [trim%d] R=%.12f %s" % (sweep, rt, "BEAT" if rt > bestR + 1e-14 else ""))
            if rt > bestR + 1e-14:
                best, bestR = ht, rt
                improved = True

        if time.process_time() < hard - 2.0:
            cap = min(hard - 1.0, time.process_time() + 4.0)
            ht = _lbfgs_log(best, 300, cap, fg=_fun_grad_tie)
            rt = R_of(ht)
            print("  [polish%d tie] R=%.12f %s" % (sweep, rt, "BEAT" if rt > bestR + 1e-14 else ""))
            if rt > bestR + 1e-14:
                best, bestR = ht, rt
                improved = True

        # window polish around the peak
        if time.process_time() < hard - 2.0:
            free = _peak_window(best, tol=0.98, pad_frac=0.5, extra=512)
            cap = min(hard - 1.0, time.process_time() + 2.5)
            hw = _lbfgs_block(best, free, 200, cap, fg=_fun_grad_tie)
            rw = R_of(hw)
            if rw > bestR + 1e-14:
                best, bestR = hw, rw
                improved = True

        # also try alt branch if it's competitive
        if alt_best is not None and time.process_time() < hard - 3.0:
            r0 = altR
            cap = min(hard - 2.0, time.process_time() + 3.0)
            ha = _lbfgs_log(alt_best, 200, cap, fg=_fun_grad_tie)
            ra = R_of(ha)
            if ra > altR:
                alt_best, altR = ha, ra
            if ra > bestR + 1e-14:
                best, bestR = ha, ra
                improved = True

        if not improved and sweep > 3:
            cap = min(hard - 1.0, time.process_time() + 3.0)
            ht = _lbfgs_log(best, 400, cap, fg=_fun_grad)
            rt = R_of(ht)
            if rt > bestR + 1e-13:
                best, bestR = ht, rt
                print("    fallback R=%.12f" % bestR)
            else:
                break

    print("final R=%.12f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        alt = alt_best if (alt_best is not None and altR < bestR - 1e-12) else start_best
        return {"best": best, "alternative": alt}
    else:
        alt = alt_best if alt_best is not None else best
        return {"best": start_best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = idx.min(); hi = idx.max()
    span = hi - lo
    pad = int(span * pad_frac) + extra
    lo = max(0, lo - pad); hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(start, Nf):
    start = np.asarray(start, dtype=float)
    n = start.size
    if n == Nf:
        return start.copy()
    c = np.concatenate([[0.0], np.cumsum(start)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nf)
    xs = np.linspace(0.0, 1.0, Nf + 1)
    old = np.linspace(0.0, 1.0, n + 1)
    cm = np.interp(xs, old, c)
    return np.diff(cm) * Nf


def _smooth(h, w):
    if w <= 1:
        return h
    k = np.ones(w) / w
    return np.convolve(h, k, mode='same')


def _cycle(h, r_best, h_best, deadline, cap, tag, rng):
    """One full alternation cycle, each rung capped at `cap` seconds."""
    def tcap():
        return min(deadline, time.process_time() + cap)

    # full tie polish
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(h, np.arange(h.size), 400, tcap(), tie=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"{tag} full R={r:.6f} best={r_best:.6f}")

    # peak-window polish
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, tol=0.999, pad_frac=0.3, extra=128)
        h = _lbfgs_block(h, win, 400, tcap())
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"{tag} local R={r:.6f} best={r_best:.6f}")

    # beta soft-max polishes
    for beta in (1e5, 1e7):
        if time.process_time() < deadline - 0.5:
            h = _lbfgs_block(h, np.arange(h.size), 150, tcap(), beta=beta)
            r = R_of(h)
            if r > r_best:
                r_best = r; h_best = h.copy()
            print(f"{tag} beta={beta:.0e} R={r:.6f} best={r_best:.6f}")

    # flat pass
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(h, np.arange(h.size), 200, tcap(), flat=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"{tag} flat R={r:.6f} best={r_best:.6f}")

    # high-beta rung restricted to top-knot window
    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, tol=0.9995, pad_frac=0.2, extra=64)
        h = _lbfgs_block(h, win, 150, tcap(), beta=1e8)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"{tag} beta=1e+08 R={r:.6f} best={r_best:.6f}")

    return h, r_best, h_best


def _escape(h, r_best, h_best, deadline, rng, tag):
    """Perturb 5% of active cells, re-polish, keep only if exact R improves."""
    if time.process_time() >= deadline - 1.0:
        return h, r_best, h_best
    act = np.flatnonzero(h > 0)
    if act.size == 0:
        return h, r_best, h_best
    k = max(1, int(0.05 * act.size))
    sel = rng.choice(act, size=k, replace=False)
    h2 = h.copy()
    h2[sel] *= (1.0 + 0.05 * rng.standard_normal(k))
    h2 = _rescale(h2)
    h2 = _lbfgs_block(h2, np.arange(h2.size), 200,
                      min(deadline, time.process_time() + 4.0), tie=True)
    r2 = R_of(h2)
    if r2 > r_best:
        r_best = r2; h_best = h2.copy()
        print(f"{tag} escape R={r2:.6f} best={r_best:.6f}")
    return h_best.copy(), r_best, h_best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        s = np.asarray(start, dtype=float)
        r_start = R_of(s)
    else:
        s = None
        r_start = -1.0

    # Baseline: p2454's construction at N=16384
    if s is not None:
        N0 = min(max(s.size, 2048), 16384)
        h = _resample(s, N0)
    else:
        N0 = 8192
        x = (np.arange(N0) + 0.5) / N0
        h = 1.0 + 0.8 * np.sin(np.pi * x) + 0.3 * np.cos(4 * np.pi * x)
        h = np.clip(h, 0.05, None)

    h = _rescale(h)
    r_best = R_of(h)
    h_best = h.copy()
    print(f"init N={h.size} R={r_best:.6f}")

    # Quick base polish to reach p2454-like quality (short)
    if time.process_time() < deadline - 8.0:
        h = _lbfgs_block(h, np.arange(h.size), 400,
                         min(deadline, time.process_time() + 6.0), tie=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"base polish R={r:.6f} best={r_best:.6f}")

    # Ladder: 32768 then 65536
    for N in (32768, 65536):
        if time.process_time() >= deadline - 6.0:
            break
        if h_best.size == N:
            h = h_best.copy()
        else:
            factor = N // h_best.size
            if factor >= 1 and h_best.size * factor == N:
                h = np.repeat(h_best, factor)
            else:
                h = _resample(h_best, N)
        h = _rescale(h)
        r_lift = R_of(h)
        print(f"lift N={N} R={r_lift:.6f} (best {r_best:.6f})")

        # two full cycles at this level
        for cyc in range(2):
            if time.process_time() >= deadline - 5.0:
                break
            h, r_best, h_best = _cycle(h, r_best, h_best, deadline, 6.0,
                                       f"N{N}c{cyc}", rng)
            if cyc == 0:
                h, r_best, h_best = _escape(h, r_best, h_best, deadline,
                                            rng, f"N{N}")

    # Reserve last ~5 s for full-array tie polish at top level
    if time.process_time() < deadline - 0.5:
        h = h_best.copy()
        h = _lbfgs_block(h, np.arange(h.size), 600, deadline, tie=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"final tie R={r:.6f} best={r_best:.6f}")

    h_best = _rescale(h_best)
    print(f"done R={r_best:.6f} N={h_best.size}")

    if s is not None and r_best < r_start:
        return {"best": s, "alternative": h_best}
    return h_best

