def _band01(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= 0.999 * mx))


def _perturb_plateau(h, rng, scale):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.9 * mx)
    lo = max(0, idx.min() - 2)
    hi = min(n, idx.max() + 2)
    if hi <= lo:
        return h
    L = hi - lo
    out = h.copy()
    t = np.linspace(0, 2 * np.pi, L)
    wig = np.zeros(L)
    for j in range(1, 4):
        wig += rng.normal(0, 1) * np.sin(j * t + rng.uniform(0, 2 * np.pi))
    wig = np.exp(scale * wig / (np.abs(wig).max() + 1e-12))
    out[lo:hi] *= wig
    return _rescale(np.clip(out, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(1234567)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Polish start with full optimize
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_all(best, 800, deadline - 2.0)
        r = R_of(ht)
        if r > bestR:
            best, bestR = ht, r
        print("polish R=%.7f" % bestR)

    # Basin hopping with block refine
    cur = best.copy(); curR = bestR
    hop_deadline = deadline - 2.0
    accepted = 0; hops = 0; since = 0
    while time.process_time() < hop_deadline - 0.5:
        now = time.process_time()
        remaining = hop_deadline - now
        scale = rng.uniform(0.005, 0.04)
        trial = _perturb_plateau(cur, rng, scale)
        if trial is None or trial.sum() <= 0:
            continue
        sub = now + min(3.5, max(0.6, remaining / 2.0))
        win = _peak_window(trial, pad_frac=0.25, extra=256)
        trial = _lbfgs_block(trial, win, 200, sub)
        trial = _lbfgs_all(trial, 200, sub)
        trialR = R_of(trial)
        hops += 1
        dR = trialR - curR
        temp = max(1e-9, 3e-7 * (remaining / max(1e-9, hop_deadline - t0)))
        accept = trialR > curR + 1e-13 or (rng.random() < np.exp(min(0.0, dR / temp)))
        if accept:
            cur, curR = trial.copy(), trialR
            since = 0
            if trialR > bestR + 1e-13:
                best, bestR = trial.copy(), trialR
                accepted += 1
                print("hop R=%.7f dR=%+.2e ACCEPT" % (trialR, dR))
        else:
            since += 1
            if since > 12:
                cur, curR = best.copy(), bestR; since = 0

    print("hops=%d accepted=%d curR=%.7f" % (hops, accepted, curR))

    # Final polish
    for frac, extra in [(0.10, 128), (0.25, 256)]:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, 300, deadline - 0.8)
        r = R_of(ht)
        if r > bestR:
            best, bestR = ht, r
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all(best, 400, deadline - 0.8)
        r = R_of(ht)
        if r > bestR:
            best, bestR = ht, r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), 100.0 * _band01(best)))

    out = {"best": best}
    if bestR < startR - 1e-12:
        out = {"best": _rescale(np.asarray(start, dtype=float)), "alternative": best}
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_period(h, maxT=64):
    n = h.size
    for T in range(2, maxT + 1):
        if n % T != 0:
            continue
        K = n // T
        bm = h.reshape(K, T).mean(axis=1)
        rep = np.repeat(bm, T)
        if np.max(np.abs(h - rep)) < 1e-9:
            return T, K
    return None, None


def _joint_stage(h, T, K, deadline, maxiter_c=60, maxiter_w=60):
    if time.process_time() >= deadline - 0.5:
        return None
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return None
    H = h.reshape(K, T)
    c = H.mean(axis=1)
    if np.any(c <= 0):
        c = np.clip(c, 1e-12, None)
    w = H.sum(axis=0) / H.sum()
    if w.sum() <= 0:
        return None
    w = w / w.mean()

    def build(c, w):
        return (c[:, None] * w[None, :]).ravel()

    def fg_c(logc):
        cc = np.exp(logc)
        hh = build(cc, w)
        val, g = _fun_grad_tie(hh)
        gc = (g.reshape(K, T) * w[None, :]).sum(axis=1) * cc
        return val, gc

    def fg_w(logw):
        ww = np.exp(logw)
        ww = ww / ww.mean()
        hh = build(c, ww)
        val, g = _fun_grad_tie(hh)
        gw = (g.reshape(K, T) * c[:, None]).sum(axis=0) * ww
        return val, gw

    x0 = np.log(np.clip(c, 1e-12, None))
    cb = _make_cb(deadline - 0.4)
    try:
        res = minimize(fg_c, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter_c, 'maxfun': 2 * maxiter_c,
                                'ftol': 1e-20, 'gtol': 1e-16})
        if res is not None and np.all(np.isfinite(res.x)):
            c = np.exp(res.x)
    except (TimeoutError, Exception):
        pass
    if time.process_time() >= deadline - 0.4:
        return _rescale(build(c, w))

    x0 = np.log(np.clip(w, 1e-12, None))
    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg_w, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter_w, 'maxfun': 2 * maxiter_w,
                                'ftol': 1e-20, 'gtol': 1e-16})
        if res is not None and np.all(np.isfinite(res.x)):
            ww = np.exp(res.x)
            ww = ww / ww.mean()
            w = ww
    except (TimeoutError, Exception):
        pass
    return _rescale(build(c, w))


def _refine_peak_window(h, deadline, rounds=6):
    """Local full-resolution polish restricted to the peak window."""
    best = h.copy()
    bestR = R_of(best)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        Lf = _knots(best)
        mx = Lf.max()
        idx = np.flatnonzero(Lf >= 0.999 * mx)
        if idx.size == 0:
            break
        lo = max(0, idx.min() - 1)
        hi = min(best.size - 1, idx.max())
        pad = max(256, int((hi - lo) * 0.5))
        lo = max(0, lo - pad)
        hi = min(best.size - 1, hi + pad)
        window = np.arange(lo, hi + 1)
        tlim = min(deadline - 0.3, time.process_time() + 4.0)
        cand = _lbfgs_block(best, window, 300, tlim)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand, r
        else:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N = best.size
    T, K = _detect_period(best)
    joint_best = None
    jointR = -1.0

    if T is not None and T >= 2:
        print("detected period T=%d K=%d" % (T, K))
        H = best.reshape(K, T)
        c0 = H.mean(axis=1)
        if np.any(c0 <= 0):
            c0 = np.clip(c0, 1e-12, None)
        w0 = H.sum(axis=0) / H.sum()
        w0 = w0 / w0.mean()
        hh = _rescale((c0[:, None] * w0[None, :]).ravel())
        cur = hh
        curR = R_of(cur)
        joint_best = cur.copy()
        jointR = curR
        round_i = 0
        reserve = 8.0
        while time.process_time() < deadline - reserve:
            round_i += 1
            tlim = min(deadline - reserve, time.process_time() + 8.0)
            cand = _joint_stage(cur, T, K, tlim, maxiter_c=80, maxiter_w=80)
            if cand is None:
                break
            r = R_of(cand)
            if r > curR + 1e-15:
                cur = cand
                curR = r
                if r > jointR:
                    jointR = r
                    joint_best = cand.copy()
            else:
                break
        print("joint phase done R=%.12f (rounds=%d)" % (jointR, round_i))
        if jointR > bestR + 1e-15:
            best = joint_best.copy()
            bestR = jointR

    # local peak-window polish
    cand, rc = _refine_peak_window(best, deadline)
    if rc > bestR + 1e-15:
        best, bestR = cand, rc
    print("peak-window polish R=%.12f" % bestR)

    # full-array tie polish
    if time.process_time() < deadline - 0.5:
        tlim = deadline - 0.3
        pol = _lbfgs_block(best, np.arange(best.size), 300, tlim)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        print("final tie polish R=%.12f" % rp)

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if joint_best is not None and jointR > startR + 1e-14 and jointR < bestR - 1e-14:
        result["alternative"] = joint_best
    elif bestR <= startR + 1e-14 and joint_best is not None:
        result["alternative"] = joint_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_shape(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if shape:
        fg = _fun_grad_shape
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04, 0.025), iters=400):
    cur_r = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
        r = R_of(ht)
        if r > cur_r + 1e-15:
            h, cur_r = ht, r
    return h, cur_r


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _resample_bilinear(h, m):
    """Resample by linear interpolation preserving shape (not cumulative)."""
    n = h.size
    if m == n:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, m)
    return np.clip(np.interp(x_new, x_old, h), 0.0, None)


def _refine_at_res(h, deadline, rcur, rounds=3):
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        n = h.size
        if n >= 1_000_000:
            break
        m = min(1_000_000, n * 2)
        h2 = _rescale(_prolong(h, m))
        cand = _lbfgs_block(h2, np.arange(m), 250, deadline, tie=True)
        r = R_of(cand)
        if r > rcur + 1e-15:
            h, rcur = cand, r
        else:
            h2b = _rescale(_resample_bilinear(h, m))
            cand2 = _lbfgs_block(h2b, np.arange(m), 250, deadline, tie=True)
            r2 = R_of(cand2)
            if r2 > rcur + 1e-15:
                h, rcur = cand2, r2
            else:
                break
    return h, rcur


def _smooth_dilate(h, k):
    if k <= 1:
        return h.copy()
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(h)
        best_r = R_of(best)
        start_r = best_r

    if best.size < 65536:
        best = _rescale(_prolong(best, 65536))
        best_r = R_of(best)

    # Direct full-resolution tie-based optimization (better than beta smoothing here).
    cand = _lbfgs_block(best, np.arange(best.size), 400, deadline, tie=True)
    r = R_of(cand)
    if r > best_r + 1e-15:
        best, best_r = cand, r
    print("after full R=%.6f" % best_r)

    # Peak-window polish with tie-aware gradient.
    best, best_r = _peak_ladder(best, deadline)
    print("after peak-ladder R=%.6f" % best_r)

    # Resolution refinement (cumulative prolongation + bilinear resample).
    best, best_r = _refine_at_res(best, deadline, best_r, rounds=2)
    print("after refine R=%.6f N=%d" % (best_r, best.size))

    alt = None
    alt_r = -1.0
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        for k in (3, 7, 15, 31):
            if time.process_time() >= deadline - 1.5:
                break
            seed = _rescale(_smooth_dilate(best, k))
            cand = _lbfgs_block(seed, np.arange(seed.size), 250, deadline, tie=True)
            r = R_of(cand)
            if r > best_r + 1e-15:
                best, best_r = cand, r
            elif alt is None or r > alt_r:
                alt, alt_r = cand, r

        best, best_r = _peak_ladder(best, deadline)
        cand = _lbfgs_block(best, np.arange(best.size), 250, deadline, tie=True)
        r = R_of(cand)
        if r > best_r + 1e-15:
            best, best_r = cand, r

        if it % 2 == 0:
            best, best_r = _refine_at_res(best, deadline, best_r, rounds=1)
        print("  it#%d R=%.6f N=%d" % (it, best_r, best.size))

    best = _rescale(best)
    print("best R=%.6f (start %.6f) N=%d" % (best_r, start_r, best.size))

    if start_arr is not None and start_r >= best_r:
        if alt is not None and alt_r > start_r:
            return {"best": start_arr, "alternative": alt}
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        if alt is not None and alt_r > 0 and R_of(alt) < best_r:
            return {"best": best, "alternative": alt}
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_shape(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if shape:
        fg = _fun_grad_shape
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_period(h, maxT=64):
    n = h.size
    for T in range(2, maxT + 1):
        if n % T != 0:
            continue
        K = n // T
        bm = h.reshape(K, T).mean(axis=1)
        rep = np.repeat(bm, T)
        if np.max(np.abs(h - rep)) < 1e-9:
            return T, K
    return None, None


# ---------------- fast staircase machinery ----------------

def _tri(T):
    # triangle kernel length 2T-1: 1,2,...,T,...,2,1
    a = np.arange(1, T + 1, dtype=float)
    return np.concatenate((a, a[-2::-1]))


def _knots_fast(c, T):
    cc = np.convolve(c, c)
    up = np.zeros(cc.size * T, dtype=float)
    up[::T] = cc
    tri = _tri(T)
    L = np.convolve(up, tri)
    return np.concatenate(([0.0], L, [0.0]))


def R_fast(c, T):
    c = np.asarray(c, dtype=float)
    s = c.sum()
    if s <= 0:
        return 0.0
    L = _knots_fast(c, T)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * T * T * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _fast_num_grad(c, T):
    """Return value -log R and gradient wrt c for the staircase family."""
    c = np.asarray(c, dtype=float)
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    cc = np.convolve(c, c)
    up = np.zeros(cc.size * T, dtype=float)
    up[::T] = cc
    tri = _tri(T)
    Lk = np.convolve(up, tri)
    Lf = np.concatenate(([0.0], Lk, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    if num <= 0:
        return 1e18, np.zeros(c.size)
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    mx = Lf.max()
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    # backprop through triangle conv -> gLk (length Lk)
    gLk = np.correlate(gLf, tri, mode='valid')[:Lk.size]
    # backprop through upsample -> gcc
    gcc = gLk[::T][:cc.size]
    # backprop through conv(c,c): d/dc = 2 * correlate(gcc, c)
    gc = 2.0 * np.correlate(gcc, c, mode='valid')[:c.size]
    gc += 2.0 / s * (T * T) * 0.0  # mass term handled below
    # val = -log(num) + 2 log(s) + 2 log(T) + log(mx)
    val = -np.log(num) + 2.0 * np.log(s) + 2.0 * np.log(T) + np.log(mx)
    # gradient of 2 log(s) wrt c is 2/s
    gc = gc + 2.0 / s
    return val, gc


def _resample_linear(c, Knew):
    K = c.size
    if K == Knew:
        return c.copy()
    x = np.linspace(0.0, 1.0, K)
    xn = np.linspace(0.0, 1.0, Knew)
    out = np.interp(xn, x, c)
    return np.clip(out, 0, None)


def _opt_c(c0, T, deadline, maxiter=1500):
    c0 = np.clip(np.asarray(c0, dtype=float), 0, None)
    if c0.sum() <= 0:
        return c0, -1.0
    x0 = c0.copy()

    def f(x):
        return _fast_num_grad(np.clip(x, 0.0, None), T)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0, R_fast(c0, T)
    if res is None or not np.all(np.isfinite(res.x)):
        return c0, R_fast(c0, T)
    c = np.clip(res.x, 0.0, None)
    return c, R_fast(c, T)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N = best.size
    T0, K0 = _detect_period(best)
    print("detected period T=%s K=%s" % (T0, K0))

    # The staircase sweep
    sweep_best_R = -1.0
    sweep_best = None  # (T, c)
    sweep_table = []

    if T0 is not None and T0 >= 2:
        c0 = best.reshape(K0, T0).mean(axis=1)
        # validate fast R
        rfast = R_fast(c0, T0)
        rexact = R_of(best)
        print("validate R_fast=%.12f R_of=%.12f diff=%.2e"
              % (rfast, rexact, abs(rfast - rexact)))

        T_list = [24, 28, 30, 31, 32, 33, 34, 36, 40]
        rng = np.random.RandomState(999)
        per_T_budget = 4.0
        for T in T_list:
            if time.process_time() >= deadline - 12.0:
                break
            K_T = int(round(N / T))
            if K_T < 2:
                continue
            cT = _resample_linear(c0, K_T)
            if cT.sum() <= 0:
                continue
            tlim = min(deadline - 12.0, time.process_time() + per_T_budget * 0.5)
            cA, rA = _opt_c(cT, T, tlim)
            # second seed: multiplicative jitter
            jit = np.clip(cT * (1.0 + 0.02 * rng.randn(K_T)), 1e-9, None)
            tlim2 = min(deadline - 12.0, time.process_time() + per_T_budget * 0.5)
            cB, rB = _opt_c(jit, T, tlim2)
            if rB > rA:
                cA, rA = cB, rB
            # second restart from cA
            tlim3 = min(deadline - 12.0, time.process_time() + per_T_budget * 0.3)
            cC, rC = _opt_c(cA, T, tlim3)
            if rC > rA:
                cA, rA = cC, rC
            sweep_table.append((T, K_T, rA))
            print("sweep T=%d K=%d R_fast=%.12f" % (T, K_T, rA))
            if rA > sweep_best_R:
                sweep_best_R = rA
                sweep_best = (T, cA.copy())

    # Map best staircase back and polish at full resolution
    if sweep_best is not None:
        Tb, cb = sweep_best
        hb = np.repeat(cb, Tb)
        if hb.size <= 1000000:
            hb = _rescale(hb)
            rb = R_of(hb)
            print("mapped best T=%d N=%d R_of=%.12f" % (Tb, hb.size, rb))
            if rb > bestR + 1e-15:
                best, bestR = hb.copy(), rb

    # Full-resolution tie polish on best
    if time.process_time() < deadline - 0.5:
        tlim = deadline - 0.3
        pol = _lbfgs_block(best, np.arange(best.size), 300, tlim, tie=True)
        rp = R_of(pol)
        print("final tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    # peak-window polish
    if time.process_time() < deadline - 0.5:
        win = _peak_window(best)
        tlim = deadline - 0.3
        pol = _lbfgs_block(best, win, 300, tlim, tie=True)
        rp = R_of(pol)
        print("peak-window polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if sweep_best is not None:
        Tb, cb = sweep_best
        hb = np.repeat(cb, Tb)
        if hb.size <= 1000000:
            hb = _rescale(hb)
            rb = R_of(hb)
            if rb > startR + 1e-14 and rb < bestR - 1e-14:
                result["alternative"] = hb
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = idx.min(); hi = idx.max()
    span = hi - lo
    pad = int(span * pad_frac) + extra
    lo = max(0, lo - pad); hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(start, Nf):
    start = np.asarray(start, dtype=float)
    n = start.size
    if n == Nf:
        return start.copy()
    c = np.concatenate([[0.0], np.cumsum(start)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nf)
    xs = np.linspace(0.0, 1.0, Nf + 1)
    old = np.linspace(0.0, 1.0, n + 1)
    cm = np.interp(xs, old, c)
    return np.diff(cm) * Nf


def _near_max_share(h, frac=0.001):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _cycle(h, r_best, h_best, deadline, cap, tag, rng):
    """Cycle with full tie, peak-window, one beta=1e7 pass. No flat pass."""
    def tcap():
        return min(deadline, time.process_time() + cap)

    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(h, np.arange(h.size), 400, tcap(), tie=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"{tag} full R={r:.6f} best={r_best:.6f}")

    if time.process_time() < deadline - 0.5:
        win = _peak_window(h, tol=0.999, pad_frac=0.3, extra=128)
        h = _lbfgs_block(h, win, 400, tcap())
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"{tag} local R={r:.6f} best={r_best:.6f}")

    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(h, np.arange(h.size), 150, tcap(), beta=1e7)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"{tag} beta=1e+07 R={r:.6f} best={r_best:.6f}")

    return h, r_best, h_best


def _birth_move(h, r_best, h_best, deadline, rng, tag):
    """Revive 20% of zero cells that have an active neighbour."""
    if time.process_time() >= deadline - 1.5:
        return h, r_best, h_best
    act = h > 0
    if not act.any():
        return h, r_best, h_best
    nbr = np.zeros_like(act)
    nbr[1:] |= act[:-1]
    nbr[:-1] |= act[1:]
    cand = np.flatnonzero((~act) & nbr)
    if cand.size == 0:
        return h, r_best, h_best
    k = max(1, int(0.20 * cand.size))
    sel = rng.choice(cand, size=k, replace=False)
    h2 = h.copy()
    for i in sel:
        left = h2[i - 1] if i > 0 else 0.0
        right = h2[i + 1] if i + 1 < h2.size else 0.0
        vals = [v for v in (left, right) if v > 0]
        if vals:
            h2[i] = 0.2 * float(np.mean(vals))
    h2 = _rescale(h2)
    win = _peak_window(h2, tol=0.999, pad_frac=0.3, extra=128)
    h2 = _lbfgs_block(h2, win, 300,
                      min(deadline, time.process_time() + 3.0), tie=True)
    r2 = R_of(h2)
    if r2 > r_best:
        r_best = r2; h_best = h2.copy()
        print(f"{tag} birth R={r2:.6f} best={r_best:.6f}")
    return h_best.copy(), r_best, h_best


def _escape(h, r_best, h_best, deadline, rng, tag):
    if time.process_time() >= deadline - 1.0:
        return h, r_best, h_best
    act = np.flatnonzero(h > 0)
    if act.size == 0:
        return h, r_best, h_best
    k = max(1, int(0.05 * act.size))
    sel = rng.choice(act, size=k, replace=False)
    h2 = h.copy()
    h2[sel] *= (1.0 + 0.05 * rng.standard_normal(k))
    h2 = _rescale(h2)
    h2 = _lbfgs_block(h2, np.arange(h2.size), 200,
                      min(deadline, time.process_time() + 4.0), tie=True)
    r2 = R_of(h2)
    if r2 > r_best:
        r_best = r2; h_best = h2.copy()
        print(f"{tag} escape R={r2:.6f} best={r_best:.6f}")
    return h_best.copy(), r_best, h_best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)
    rng_birth = np.random.default_rng(7)

    if start is not None:
        s = np.asarray(start, dtype=float)
        r_start = R_of(s)
    else:
        s = None
        r_start = -1.0

    # Base: p2464's construction (start) at its own N
    if s is not None:
        h = _resample(s, s.size)
    else:
        N0 = 8192
        x = (np.arange(N0) + 0.5) / N0
        h = 1.0 + 0.8 * np.sin(np.pi * x) + 0.3 * np.cos(4 * np.pi * x)
        h = np.clip(h, 0.05, None)

    h = _rescale(h)
    r_best = R_of(h)
    h_best = h.copy()
    print(f"init N={h.size} R={r_best:.6f}")

    # Quick base polish
    if time.process_time() < deadline - 8.0:
        h = _lbfgs_block(h, np.arange(h.size), 400,
                         min(deadline, time.process_time() + 6.0), tie=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"base polish R={r:.6f} best={r_best:.6f}")

    # Ladder: lift to 131072
    for Nt in (131072,):
        if time.process_time() >= deadline - 20.0:
            break
        if h_best.size == Nt:
            h = h_best.copy()
        else:
            factor = Nt // h_best.size
            if factor >= 1 and h_best.size * factor == Nt:
                h = np.repeat(h_best, factor)
            else:
                h = _resample(h_best, Nt)
        h = _rescale(h)
        r_lift = R_of(h)
        print(f"lift N={Nt} R={r_lift:.6f} (best {r_best:.6f})")
        if r_lift > r_best:
            r_best = r_lift; h_best = h.copy()

        for cyc in range(3):
            if time.process_time() >= deadline - 18.0:
                break
            h, r_best, h_best = _cycle(h, r_best, h_best, deadline, 5.0,
                                       f"N{Nt}c{cyc}", rng)
            h, r_best, h_best = _birth_move(h, r_best, h_best, deadline,
                                            rng_birth, f"N{Nt}c{cyc}")
            if cyc < 2:
                h, r_best, h_best = _escape(h, r_best, h_best, deadline,
                                            rng, f"N{Nt}c{cyc}")

    # Final: full-array tie L-BFGS at top rung, maxiter 2000, then 8 s peak window
    if time.process_time() < deadline - 0.5:
        h = h_best.copy()
        h = _lbfgs_block(h, np.arange(h.size), 2000, deadline, tie=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"final tie R={r:.6f} best={r_best:.6f}")

    if time.process_time() < deadline - 0.5:
        h = h_best.copy()
        win = _peak_window(h, tol=0.999, pad_frac=0.3, extra=128)
        h = _lbfgs_block(h, win, 800,
                         min(deadline, time.process_time() + 8.0), tie=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"final window R={r:.6f} best={r_best:.6f}")

    h_best = _rescale(h_best)
    zf = float(np.mean(h_best == 0))
    nm = _near_max_share(h_best, 0.001)
    print(f"done R={r_best:.6f} N={h_best.size} zero={zf:.3f} nearmax0.1%={nm:.4f}")

    if s is not None and r_best < r_start:
        return {"best": s, "alternative": h_best}
    return h_best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_flat_top(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    S = Lf >= tau * mx
    nS = int(np.count_nonzero(S))
    V = 0.0
    if nS > 1:
        Ls = Lf[S]
        Lbar = Ls.mean()
        diff = Ls - Lbar
        V = float(np.sum(diff * diff)) / (mx * mx * nS)
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * diff / (mx * mx * nS)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * V
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, flat_top=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat_top is not None:
        tau, kappa = flat_top
        fg = (lambda hh: _fun_grad_flat_top(hh, tau, kappa))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    alt_best = None
    altR = -1.0
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Flat-top variance penalty ladder on coarsened grids ----
    # The key insight: R rewards a wide, flat plateau of f*f near its max.
    # Coarsening first, then pushing the flat-top variance penalty down at
    # multiple scales, then prolongating back up, drives the plateau wider.
    for Q in (16, 8, 4, 2, 1):
        if time.process_time() >= deadline - 5.0:
            break
        if best.size % Q != 0:
            continue
        qh = best if Q == 1 else _coarsen(best, Q)
        if qh is None or qh.size < 32:
            continue
        qh = _rescale(qh)
        qR = R_of(qh)
        ladder = [(0.999, 0.02), (0.997, 0.1), (0.99, 0.5),
                  (0.98, 2.0), (0.95, 8.0), (0.90, 30.0)]
        best_qh = qh.copy(); best_qR = qR
        for (tau, kappa) in ladder:
            if time.process_time() >= deadline - 4.0:
                break
            tlim = min(deadline - 3.5, time.process_time() + 1.6)
            cand = _lbfgs_block(best_qh, np.arange(best_qh.size), 120, tlim,
                                flat_top=(tau, kappa))
            r = R_of(cand)
            if r > best_qR:
                best_qh, best_qR = cand.copy(), r
            ph = cand if Q == 1 else _prolongate(cand, Q)
            pr = R_of(ph)
            if pr > bestR + 1e-15:
                best, bestR = ph.copy(), pr
            if pr > altR and ph.size != best.size:
                alt_best, altR = ph.copy(), pr
        # polish on full resolution
        if time.process_time() < deadline - 3.0:
            pol = _lbfgs_block(best, np.arange(best.size), 120,
                               min(deadline - 2.5, time.process_time() + 1.8))
            rp = R_of(pol)
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

    # ---- Final full-resolution polishes ----
    while time.process_time() < deadline - 0.8:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.4, time.process_time() + 2.5))
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        else:
            break

    if bestR < startR:
        best = start_best
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size <= 1000000 and alt_best.size != best.size and altR > 0:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
