    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_shape(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if shape:
        fg = _fun_grad_shape
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- second-order probe ----------

def _hvp(h, v, eps=None):
    """Hessian-vector product of -log R (tie gradient) via central differences."""
    h = np.asarray(h, dtype=float)
    v = np.asarray(v, dtype=float)
    nv = np.max(np.abs(v))
    if nv <= 0:
        return np.zeros_like(h)
    nh = np.max(np.abs(h))
    if eps is None:
        eps = 1e-6 * (nh if nh > 0 else 1.0) / nv
    hp = np.clip(h + eps * v, 0.0, None)
    hm = np.clip(h - eps * v, 0.0, None)
    _, gp = _fun_grad_tie(hp)
    _, gm = _fun_grad_tie(hm)
    hv = (gp - gm) / (2.0 * eps)
    if not np.all(np.isfinite(hv)):
        _, gp = _fun_grad(hp)
        _, gm = _fun_grad(hm)
        hv = (gp - gm) / (2.0 * eps)
    return hv


def _lanczos_min_eig(h, m=24, seed=0):
    """Full-reorthogonalised Lanczos on the Hessian; return smallest Ritz pair."""
    n = h.size
    m = min(m, n)
    rng = np.random.RandomState(seed)
    q = rng.randn(n)
    q = q - q.mean()
    nq = np.linalg.norm(q)
    if nq <= 0:
        return 0.0, np.zeros(n)
    q /= nq
    Q = [q]
    alpha = []
    beta = []
    qprev = np.zeros(n)
    b = 0.0
    for j in range(m):
        w = _hvp(h, Q[j])
        # reorthogonalise twice
        for _ in range(2):
            for qi in Q:
                w -= np.dot(qi, w) * qi
        a = np.dot(Q[j], w)
        alpha.append(a)
        w = w - a * Q[j] - b * qprev
        for _ in range(2):
            for qi in Q:
                w -= np.dot(qi, w) * qi
        b = np.linalg.norm(w)
        beta.append(b)
        if b < 1e-12 or j == m - 1:
            break
        qprev = Q[j]
        Q.append(w / b)
    k = len(alpha)
    if k == 0:
        return 0.0, np.zeros(n)
    T = np.zeros((k, k))
    for i in range(k):
        T[i, i] = alpha[i]
        if i + 1 < k:
            T[i, i + 1] = beta[i]
            T[i + 1, i] = beta[i]
    try:
        evals, evecs = np.linalg.eigh(T)
    except Exception:
        return 0.0, np.zeros(n)
    idx = int(np.argmin(evals))
    lam = float(evals[idx])
    y = evecs[:, idx]
    v = np.zeros(n)
    for i in range(k):
        v += y[i] * Q[i]
    nv = np.linalg.norm(v)
    if nv > 0:
        v /= nv
    return lam, v


def _line_search_along(h, v, ts):
    nh = np.linalg.norm(h)
    nv = np.linalg.norm(v)
    if nv <= 0:
        return None, -1.0
    best_h, best_r = None, -1.0
    for t in ts:
        cand = _rescale(h + t * nh * v / nv)
        r = R_of(cand)
        if r > best_r:
            best_r, best_h = r, cand
    return best_h, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    h = best.copy()
    curR = bestR
    rng = np.random.RandomState(987654321)

    reserve = 6.0
    fail_streak = 0
    fallback_toggle = 0
    round_i = 0
    neg_lam_seen = False
    neg_lam_min = 0.0

    while time.process_time() < deadline - reserve:
        round_i += 1
        lam, v = _lanczos_min_eig(h, m=24, seed=round_i)
        print("round %d: lam=%.6e R=%.12f" % (round_i, lam, curR))
        if lam < neg_lam_min:
            neg_lam_min = lam
        if lam < -1e-4:
            neg_lam_seen = True

        accepted = False
        if lam < -1e-4:
            ts = [3e-2, 1e-2, 3e-3, 1e-3, 3e-4, 1e-4]
            cand, r = _line_search_along(h, v, ts)
            if cand is not None:
                tlim = min(deadline - reserve, time.process_time() + 3.0)
                pol = _lbfgs_block(cand, np.arange(cand.size), 250, tlim, tie=True)
                rp = R_of(pol)
                if rp > curR + 1e-13:
                    h, curR = pol, rp
                    accepted = True
                    print("  neg-curvature step accepted R=%.12f" % curR)
        else:
            # fallbacks alternate
            if fallback_toggle % 2 == 0:
                # trust-region along smallest positive curvature eigenvector
                ts = [1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5]
                cand, r = _line_search_along(h, v, ts)
                if cand is not None:
                    tlim = min(deadline - reserve, time.process_time() + 3.0)
                    pol = _lbfgs_block(cand, np.arange(cand.size), 250, tlim, tie=True)
                    rp = R_of(pol)
                    if rp > curR + 1e-13:
                        h, curR = pol, rp
                        accepted = True
                        print("  positive-curv TR step accepted R=%.12f" % curR)
            else:
                # random kick
                kick = h.copy()
                nz = np.flatnonzero(kick > 0)
                if nz.size > 0:
                    k = min(200, nz.size)
                    sel = rng.choice(nz, size=k, replace=False)
                    kick[sel] = kick[sel] * np.exp(0.05 * rng.randn(k))
                kick = _rescale(kick)
                tlim = min(deadline - reserve, time.process_time() + 3.0)
                pol = _lbfgs_block(kick, np.arange(kick.size), 250, tlim, tie=True)
                rp = R_of(pol)
                if rp > curR + 1e-13:
                    h, curR = pol, rp
                    accepted = True
                    print("  random kick accepted R=%.12f" % curR)
            fallback_toggle += 1

        if accepted:
            fail_streak = 0
            if curR > bestR + 1e-15:
                best, bestR = h.copy(), curR
        else:
            fail_streak += 1

        if fail_streak >= 4:
            # 2x lift
            print("  2x lift attempt")
            lift = _rescale(np.repeat(h, 2))
            lr = R_of(lift)
            cur_lift = lift
            for _ in range(3):
                if time.process_time() >= deadline - reserve:
                    break
                tlim = min(deadline - reserve, time.process_time() + 3.0)
                pol = _lbfgs_block(cur_lift, np.arange(cur_lift.size), 250, tlim, tie=True)
                rp = R_of(pol)
                if rp > lr + 1e-15:
                    cur_lift, lr = pol, rp
                else:
                    break
            # map back by pairwise mean
            back = _rescale(cur_lift.reshape(-1, 2).mean(axis=1))
            rb = R_of(back)
            if rb > curR + 1e-13:
                h, curR = back, rb
                if curR > bestR + 1e-15:
                    best, bestR = h.copy(), curR
                print("  lift->mean accepted R=%.12f" % curR)
            elif lr > curR + 1e-13:
                # keep lift itself only if better (store as best if larger)
                if lr > bestR + 1e-15:
                    best, bestR = cur_lift.copy(), lr
                    print("  lift kept R=%.12f" % lr)
                h, curR = back, rb
            fail_streak = 0

    # final full-array tie polish
    if time.process_time() < deadline - 0.5:
        tlim = deadline - 0.3
        pol = _lbfgs_block(best, np.arange(best.size), 300, tlim, tie=True)
        rp = R_of(pol)
        print("final tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d, neg_lam_seen=%s, min_lam=%.3e)"
          % (bestR, startR, best.size, _tie_count(best), neg_lam_seen, neg_lam_min))

    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


# ---------- banded smoothing of the values: the key new idea ----------
# Instead of only re-optimising raw heights, we directly smooth the shape of
# f*f near its maximum by moving a small number of "value bands" of the
# knot vector to a common target value.  This attacks the plateau structure
# that limits R, which gradient methods on h cannot reach easily.

def _value_band_smooth(h, deadline, rng, n_bands=12):
    """Directly flatten L near the peak by rescaling heights in value bands."""
    best = h.copy()
    bestR = R_of(best)
    for _ in range(40):
        if time.process_time() > deadline:
            break
        Lf = _knots(best)
        mx = Lf.max()
        if mx <= 0:
            break
        n = best.size
        # target: raise the lower knots of the top bands closer to mx
        lo_frac = rng.uniform(0.80, 0.95)
        sel = np.flatnonzero(Lf >= lo_frac * mx)
        if sel.size == 0:
            break
        # For each selected knot, nudge the two heights whose product sums
        # into it.  A knot L_j = sum_{i} h_i h_{j-i}; the cheapest local push
        # is to scale h at the peak's contributing window.
        # Simple heuristic: scale the peak window heights by a small factor
        # and accept if R improves.
        win = _peak_window(best, pad_frac=0.10, extra=128)
        for delta in (0.02, 0.01, 0.005, 0.002, 0.001, -0.001, -0.002,
                      -0.005, -0.01, -0.02):
            hc = best.copy()
            hc[win] *= (1.0 + delta)
            hc = _rescale(hc)
            rc = R_of(hc)
            if rc > bestR + 1e-15:
                best, bestR = hc, rc
                break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    rng = np.random.default_rng(20240101)

    # ---- Phase 1: value-band direct smoothing (new idea) ----
    phase1_end = t0 + budget_seconds * 0.45
    cyc = 0
    while time.process_time() < phase1_end - 2.0:
        cyc += 1
        hc, rc = _value_band_smooth(best, min(phase1_end - 1.0,
                                              time.process_time() + 6.0), rng)
        if rc > bestR + 1e-15:
            best, bestR = hc, rc
        # follow up with a short peak polish
        win = _peak_window(best, pad_frac=0.08, extra=128)
        ht = _lbfgs_block(best, win, 150,
                          min(phase1_end - 0.5, time.process_time() + 3.0),
                          beta=1e7)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
        f01, f1, f5 = _nearmax_fracs(best)
        print("  band cyc=%d R=%.9f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (cyc, bestR, f01, f1, f5))

    # ---- Phase 2: exact tie polish on the full vector ----
    phase2_end = t0 + budget_seconds * 0.72
    if time.process_time() < phase2_end - 2.0:
        ht = _lbfgs_all_pos(best, 800, min(phase2_end - 1.0,
                                           time.process_time() + 10.0),
                            tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
            print("  tie polish R=%.9f" % bestR)

    # ---- Phase 3: peak ladder ----
    phase3_end = t0 + budget_seconds * 0.90
    for pad in (0.06, 0.04, 0.03, 0.02):
        if time.process_time() >= phase3_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 250,
                          min(phase3_end - 0.5, time.process_time() + 4.0),
                          tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
            print("  ladder pad=%.2f R=%.9f" % (pad, bestR))

    # ---- Phase 4: final argmax polish ----
    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 1.5:
        ht = _lbfgs_all_pos(best, 500, fd - 0.5, tie=False)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
            print("  final argmax R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- NEW: explicit knot-level (peak-flattening) optimization ----------
def _fun_grad_maxsoft(h, beta):
    """Objective: -log(num) + 2log(s) + log(softmax_beta(L))."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_soft(h0, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_maxsoft(hh, beta)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _softmax_ladder(h0, deadline, betas=(1e3, 1e4, 1e5, 1e6, 1e7, 1e8)):
    """Progressively sharpen the softmax toward hard max; keep best R."""
    best = h0.copy()
    bestR = R_of(best)
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        hb = _lbfgs_soft(best, 200, min(deadline - 0.3,
                                        time.process_time() + 4.0), beta)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    return best, bestR


# ---------- NEW: whole-vector direct L-BFGS on h (no blocks) ----------
def _full_lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


# ---------- NEW: log-domain full-vector polish ----------
def _full_lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: softmax sharpening ladder (full vector, cheap for N~1e5) ----
    p1_end = t0 + (deadline - t0) * 0.30 + t0
    if time.process_time() < p1_end - 2.0:
        h1, r1 = _softmax_ladder(best, p1_end)
        print("softmax ladder R=%.9f (base %.9f)" % (r1, bestR))
        if r1 > bestR + 1e-15:
            best, bestR = h1, r1
            print("softmax ACCEPT R=%.9f" % bestR)

    # ---- Phase 2: full-vector L-BFGS on h (bounded) ----
    p2_end = t0 + (deadline - t0) * 0.50 + t0
    if time.process_time() < p2_end - 2.0:
        h2 = _full_lbfgs(best, 400, p2_end)
        r2 = R_of(h2)
        print("full lbfgs R=%.9f" % r2)
        if r2 > bestR + 1e-15:
            best, bestR = h2, r2
            print("full lbfgs ACCEPT R=%.9f" % bestR)

    # ---- Phase 3: log-domain full-vector polish ----
    p3_end = t0 + (deadline - t0) * 0.68 + t0
    if time.process_time() < p3_end - 2.0:
        h3 = _full_lbfgs_log(best, 400, p3_end)
        r3 = R_of(h3)
        print("full log lbfgs R=%.9f" % r3)
        if r3 > bestR + 1e-15:
            best, bestR = h3, r3
            print("full log lbfgs ACCEPT R=%.9f" % bestR)

    # ---- Phase 4: peak-window polish with sharpened softmax + ties ----
    p4_end = t0 + (deadline - t0) * 0.85 + t0
    for pad in (0.20, 0.08, 0.04, 0.02):
        if time.process_time() >= p4_end - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        for beta in (1e6, 1e7, 1e8):
            if time.process_time() >= p4_end - 1.0:
                break
            hw = _lbfgs_soft(best, 200,
                             min(p4_end - 0.6,
                                 time.process_time() + 2.5), beta)
            rw = R_of(hw)
            if rw > bestR + 1e-15:
                best, bestR = hw, rw
        ht = _lbfgs_block(best, win, 200,
                          min(p4_end - 0.4,
                              time.process_time() + 2.0), tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---- Phase 5: final full-vector L-BFGS polish until deadline ----
    while time.process_time() < deadline - 1.5:
        prev = bestR
        h5 = _full_lbfgs(best, 200,
                         min(deadline - 0.5,
                             time.process_time() + 3.0))
        r5 = R_of(h5)
        if r5 > bestR + 1e-15:
            best, bestR = h5, r5
        h5l = _full_lbfgs_log(best, 200,
                              min(deadline - 0.3,
                                  time.process_time() + 3.0))
        r5l = R_of(h5l)
        if r5l > bestR + 1e-15:
            best, bestR = h5l, r5l
        print("final polish R=%.9f" % bestR)
        if bestR <= prev + 1e-15:
            break

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_shape(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if shape:
        fg = _fun_grad_shape
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if shape:
        fg = _fun_grad_shape
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    # ---- establish base ----
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(h, org, tag="NEW BEST"):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if h is None:
            return
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR, origin = h.copy(), r, org
            print("  %s R=%.9f (%s)" % (tag, bestR, org))
        elif r > alt_bestR:
            alt_best, alt_bestR = h.copy(), r

    # ---- Phase A: shape-gradient descent on the free manifold ----
    # Directly minimise log Q - 2 log S with max fixed, which is faster per step
    # than the peak-penalised objective and avoids the peak-tracking overhead.
    if time.process_time() < deadline - 8.0:
        ht = best.copy()
        for _ in range(3):
            if time.process_time() >= deadline - 8.0:
                break
            ht = _lbfgs_all_pos(ht, 400, deadline - 7.0, shape=True)
            ht = _lbfgs_all_pos(ht, 300, deadline - 7.0, beta=0.0)
            consider(ht, 'shape', "shape")
        # peak-window shape polish
        for pad in [0.06, 0.04, 0.03]:
            if time.process_time() >= deadline - 7.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=192)
            hp = _lbfgs_block(best, win, 400, deadline - 6.0, beta=1e7)
            consider(hp, 'pk%g' % pad, "peak")
            hs = _lbfgs_block(hp, win, 200, deadline - 6.0, shape=True)
            consider(hs, 'pk%g+shape' % pad, "peak shape")

    # ---- Phase B: half-resolution extract / lift rotation ----
    N = best.size
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 5.0:
        m = N // 2
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        cyc = 0
        max_cycles = 8
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(cycle_end, now + 0.085 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]; b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            work_c = c.copy()
            best_c = c.copy()
            best_cR = cR0
            try:
                for beta in [1e6, 1e7]:
                    if time.process_time() >= slice_dl - 0.5:
                        break
                    hh = _lbfgs_all_pos(work_c, 300, slice_dl - 0.3, beta=beta)
                    r = R_of(hh)
                    if r > best_cR + 1e-14:
                        work_c, best_c, best_cR = hh, hh.copy(), r
                for pad in [0.20, 0.12]:
                    if time.process_time() >= slice_dl - 0.5:
                        break
                    win = _peak_window(work_c, pad_frac=pad, extra=64)
                    hh = _lbfgs_block(work_c, win, 350, slice_dl - 0.3, beta=1e7)
                    r = R_of(hh)
                    if r > best_cR + 1e-14:
                        work_c, best_c, best_cR = hh, hh.copy(), r
                hh = _lbfgs_all_pos(work_c, 250, slice_dl - 0.3, shape=True)
                r = R_of(hh)
                if r > best_cR + 1e-14:
                    work_c, best_c, best_cR = hh, hh.copy(), r
            except Exception as e:
                print("cycle %d var %d exception %s" % (cyc, k, e))
                continue
            # lift back to full resolution
            try:
                if k == 1:
                    hf = np.zeros(N)
                    hf[1::2] = best_c[:hf[1::2].size]
                    ev = np.empty(hf[0::2].size)
                    ev[0] = best_c[0]
                    if ev.size > 1:
                        k2 = min(ev.size - 1, best_c.size - 1)
                        ev[1:1 + k2] = 0.5 * (best_c[:k2] + best_c[1:1 + k2])
                        if ev.size > 1 + k2:
                            ev[1 + k2:] = best_c[-1]
                    hf[0::2] = ev
                    hnew = _rescale(hf)
                else:
                    hnew = _rescale(np.repeat(best_c, 2))
            except Exception as e:
                print("lift %d var %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.4:
                    break
                ht = _lbfgs_all_pos(ht, 250, slice_dl - 0.2, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, best_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            consider(ht, 'v%dcy%d' % (k, cyc), "cycle")
        print("rotation cycles=%d wR=%s" % (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase C: sub-step insertion refinement ----
    if time.process_time() < deadline - 12.0 and best.size < 400000:
        try:
            N2 = 2 * best.size
            hf = np.zeros(N2)
            hf[0::2] = best
            hf[1::2] = 0.5 * (best + np.concatenate((best[1:], [best[-1]])))
            hf = _rescale(hf)
            for beta in [1e6, 1e7]:
                if time.process_time() >= deadline - 11.0:
                    break
                hf = _lbfgs_all_pos(hf, 400, deadline - 10.0, beta=beta)
            for pad in [0.12, 0.08, 0.05]:
                if time.process_time() >= deadline - 10.5:
                    break
                win = _peak_window(hf, pad_frac=pad, extra=256)
                hf2 = _lbfgs_block(hf, win, 400, deadline - 10.0, beta=1e7)
                if R_of(hf2) > R_of(hf):
                    hf = hf2
            hf = _lbfgs_all_pos(hf, 250, deadline - 10.0, shape=True)
            consider(hf, 'refine', "refine")
        except Exception as e:
            print("refine exception %s" % e)

    # ---- Phase D: round-robin perturbation portfolio ----
    jit_end = deadline - 4.0
    if time.process_time() < jit_end - 1.0 and best.size >= 8:
        rng = np.random.RandomState(13579)
        sigmas = [0.003, 0.008, 0.02]
        pads_j = [0.06, 0.04, 0.03]
        rnd = 0
        accepted = [0, 0, 0, 0]
        while time.process_time() < jit_end - 1.0:
            mech = rnd % 4
            rnd += 1
            now = time.process_time()
            slice_dl = min(now + 2.5, jit_end)
            if slice_dl <= now + 0.4:
                break
            cand = None
            try:
                if mech == 0:
                    nz = np.flatnonzero(best > 0)
                    if nz.size < 4:
                        break
                    sigma = sigmas[rnd % len(sigmas)]
                    Bs = [max(4, nz.size // 100), max(4, nz.size // 50)]
                    B = Bs[(rnd // len(sigmas)) % len(Bs)]
                    if nz.size <= B:
                        sel = nz
                    else:
                        st = rng.randint(0, nz.size - B + 1)
                        sel = nz[st:st + B]
                    h2 = best.copy()
                    h2[sel] *= np.exp(sigma * rng.randn(sel.size))
                    cand = _rescale(np.clip(h2, 0, None))
                elif mech == 1:
                    h2 = best.copy()
                    zeros = np.flatnonzero(h2 <= 0)
                    act = h2[h2 > 0]
                    if zeros.size > 0 and act.size > 0:
                        h2[zeros] = 1e-3 * act.mean()
                    cand = _rescale(h2)
                    for beta in [1e5, 1e6, 1e7]:
                        if time.process_time() >= slice_dl - 0.5:
                            break
                        cand = _lbfgs_all_pos(cand, 200, slice_dl - 0.3, beta=beta)
                else:
                    h2 = best.copy()
                    act = np.flatnonzero(h2 > 0)
                    if act.size < 2:
                        continue
                    mx = h2.max()
                    big = act[h2[act] > 0.02 * mx]
                    if big.size == 0:
                        big = act
                    i = int(big[rng.randint(big.size)])
                    op = rng.randint(3)
                    if op == 0:
                        d = 1 if rng.rand() < 0.5 else -1
                        j = i + d
                        if 0 <= j < h2.size:
                            h2[j] += h2[i]; h2[i] = 0.0
                    elif op == 1:
                        v = h2[i]; h2[i] = v / 3.0
                        for d in (-1, 1):
                            j = i + d
                            if 0 <= j < h2.size:
                                h2[j] += v / 3.0
                    else:
                        nb = i - 1 if (i > 0 and (i == h2.size - 1 or rng.rand() < 0.5)) else i + 1
                        if 0 <= nb < h2.size:
                            h2[nb] += h2[i]; h2[i] = 0.0
                    cand = _rescale(np.clip(h2, 0, None))
            except Exception as e:
                print("round %d mech %d exception %s" % (rnd, mech, e))
                continue
            if cand is None:
                continue
            # polish: shape then peak
            pad = pads_j[rnd % len(pads_j)]
            win = _peak_window(cand, pad_frac=pad, extra=128)
            cand = _lbfgs_block(cand, win, 250, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.3:
                cand = _lbfgs_all_pos(cand, 200, slice_dl, shape=True)
            r = R_of(cand)
            if r > bestR + 1e-13:
                best, bestR = cand.copy(), r
                origin = 'rr_m%d_r%d' % (mech, rnd)
                accepted[mech] += 1
                print("  round %d mech %d NEW BEST R=%.9f" % (rnd, mech, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = cand.copy(), r
        print("portfolio rounds=%d accepted=%s bestR=%.9f" %
              (rnd, accepted, bestR))

    # ---- Phase E: final polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.06, 0.04, 0.03]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 350, deadline - 0.4, beta=1e7)
            consider(ht2, origin + '+pk', "final peak")
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 250, deadline - 0.4, beta=0.0, tie=True)
        consider(ht, origin + '+b0tie', "trailing tie")

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    tie = Lf >= mx - 1e-12 * max(1.0, abs(mx))
    k = int(tie.sum())
    gLf = -dq / num
    gLf[tie] += (1.0 / mx) / k
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_shape(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[int(np.argmax(Lf))] += 1.0 / mx
    grad = _backprop(gLf, h)
    hn = h / (np.linalg.norm(h) + 1e-300)
    grad = grad - np.dot(grad, hn) * hn
    val = -np.log(num) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if shape:
        fg = _fun_grad_shape
    elif tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if shape:
        fg = _fun_grad_shape
    elif tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.2, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, deadline, tie_iters=300, win_iters=200):
    """Full-array exact tie L-BFGS then peak-window polish."""
    ht = _lbfgs_all_pos(h, tie_iters, deadline, tie=True)
    r = R_of(ht)
    if r >= R_of(h) - 1e-15:
        h = ht
    if time.process_time() < deadline - 0.3:
        win = _peak_window(h, tol=0.999, pad_frac=0.2, extra=256)
        ht = _lbfgs_block(h, win, win_iters, deadline)
        if R_of(ht) > R_of(h):
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: collapse 2-fold duplication if present
    h = best.copy()
    if h.size % 2 == 0:
        a = h[0::2]; b = h[1::2]
        if a.size == b.size and np.max(np.abs(a - b)) < 1e-12:
            hc = 0.5 * (a + b)
            rc = R_of(hc)
            print("A collapse N=%d -> %d R=%.9f (was %.9f)" %
                  (h.size, hc.size, rc, bestR))
            if abs(rc - bestR) < 1e-6:
                h = hc
                best = hc.copy()
                bestR = rc
                origin = 'A_collapse'

    # Phase B: sparsify/revive ladder
    phaseB_deadline = t0 + budget_seconds * 0.85
    qs = [0.01, 0.02, 0.05, 0.10, 0.20]
    rng = np.random.RandomState(12345)

    def sparsify(h, q):
        h2 = h.copy()
        nz = np.flatnonzero(h2 > 0)
        if nz.size == 0:
            return h2
        k = max(1, int(round(q * nz.size)))
        k = min(k, nz.size)
        order = nz[np.argsort(h2[nz])]
        h2[order[:k]] = 0.0
        return h2

    def revive(h, q):
        h2 = h.copy()
        z = np.flatnonzero(h2 <= 0)
        if z.size == 0:
            return h2
        k = max(1, int(round(q * z.size)))
        k = min(k, z.size)
        # choose zeros adjacent to largest heights: score each zero by max neighbour
        n = h2.size
        score = np.zeros(z.size)
        for i, zi in enumerate(z):
            lo = max(0, zi - 3); hi = min(n, zi + 4)
            score[i] = h2[lo:hi].max()
        # mix: half by adjacency score, half random
        k1 = k // 2
        k2 = k - k1
        idx_sorted = np.argsort(-score)
        chosen = list(z[idx_sorted[:k1]])
        remaining = np.setdiff1d(z, np.array(chosen, dtype=int), assume_unique=False)
        if k2 > 0 and remaining.size > 0:
            k2 = min(k2, remaining.size)
            chosen.extend(rng.choice(remaining, size=k2, replace=False).tolist())
        chosen = np.array(chosen, dtype=int)
        # fill with mean of nearest nonzero neighbours
        nz = np.flatnonzero(h2 > 0)
        if nz.size == 0:
            h2[chosen] = 1.0
            return h2
        for ci in chosen:
            j = np.searchsorted(nz, ci)
            vals = []
            if j > 0:
                vals.append(h2[nz[j - 1]])
            if j < nz.size:
                vals.append(h2[nz[j]])
            h2[ci] = float(np.mean(vals)) if vals else 1.0
        return h2

    round_id = 0
    while time.process_time() < phaseB_deadline - 3.0:
        for q in qs:
            if time.process_time() >= phaseB_deadline - 3.0:
                break
            for mode in ('sparsify', 'revive'):
                if time.process_time() >= phaseB_deadline - 3.0:
                    break
                if mode == 'sparsify':
                    cand = sparsify(best, q)
                else:
                    cand = revive(best, q)
                if cand.sum() <= 0:
                    continue
                cand = _rescale(cand)
                # time-boxed polish: 3 s
                sub_deadline = min(phaseB_deadline - 1.0,
                                   time.process_time() + 3.0)
                cand = _polish(cand, sub_deadline, tie_iters=300, win_iters=200)
                r = R_of(cand)
                zf = float(np.mean(cand <= 0))
                print("B q=%.2f %s R=%.9f zf=%.3f (best %.9f)" %
                      (q, mode, r, zf, bestR))
                if r > bestR + 1e-14:
                    best = cand.copy()
                    bestR = r
                    origin = 'B_%s_q%.2f' % (mode, q)
                    print("  NEW BEST R=%.9f" % bestR)
                elif r > alt_bestR:
                    alt_best = cand.copy()
                    alt_bestR = r
        round_id += 1
        if round_id > 20:
            break

    # Phase C: final full-array exact tie polishes
    while time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.4, tie=True)
        r = R_of(ht)
        print("C tie R=%.9f" % r)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            origin = origin + '+C'
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            break

    print("final R=%.9f origin=%s N=%d (start %.9f)" %
          (bestR, origin, best.size, start_bestR))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _band_indices(Lf, tau, q):
    """Return boolean mask of band knots."""
    mx = Lf.max()
    if mx <= 0:
        return None
    if tau is not None:
        return Lf >= tau * mx
    else:
        n = Lf.size
        k = max(2, int(q * n))
        thr = np.partition(Lf, n - k)[n - k]
        return Lf >= thr


def _fun_grad_band(h, tau, q, kappa):
    """-log Q + 2 log S + log(smoothed max) + kappa * V / mx^2."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    mask = _band_indices(Lf, tau, q)
    if mask is None or mask.sum() < 2:
        return _fun_grad_tie(h)
    vals = Lf[mask]
    mean = vals.mean()
    var = np.mean((vals - mean) ** 2)
    # gradient of V wrt Lf (only band knots)
    gV = np.zeros_like(Lf)
    # d var / d L_i = 2 (L_i - mean)/n  (mean also depends on L but sum of deviations is 0)
    gV[mask] = 2.0 * (vals - mean) / vals.size
    # V_normalized = var / mx^2
    # d/dLi = gV_i / mx^2 - 2 var / mx^3 * d mx/dLi
    # d mx/dLi is 1 at argmax, 0 elsewhere (use tie-averaged)
    idxmax = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    wm = 1.0 / idxmax.size
    gLf = -dq / num
    gLf[idxmax] += wm / mx
    # add kappa * d(V/mx^2)
    gLf += kappa * gV / (mx * mx)
    gLf[idxmax] += kappa * (-2.0 * var / (mx ** 3)) * wm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * var / (mx * mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False,
                 band=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if band is not None:
        tau, q, kappa = band
        fg = (lambda hh: _fun_grad_band(hh, tau, q, kappa))
    elif flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = idx.min(); hi = idx.max()
    span = hi - lo
    pad = int(span * pad_frac) + extra
    lo = max(0, lo - pad); hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(start, Nf):
    start = np.asarray(start, dtype=float)
    n = start.size
    if n == Nf:
        return start.copy()
    c = np.concatenate([[0.0], np.cumsum(start)])
    total = c[-1]
    if total <= 0:
        return np.ones(Nf)
    xs = np.linspace(0.0, 1.0, Nf + 1)
    old = np.linspace(0.0, 1.0, n + 1)
    cm = np.interp(xs, old, c)
    return np.diff(cm) * Nf


def _band_share(h, tol=0.001):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240)

    if start is not None:
        s = np.asarray(start, dtype=float)
        r_start = R_of(s)
    else:
        s = None
        r_start = -1.0

    # Build baseline from start
    if s is not None:
        h = _resample(s, s.size)
    else:
        N0 = 16384
        x = (np.arange(N0) + 0.5) / N0
        h = 1.0 + 0.8 * np.sin(np.pi * x) + 0.3 * np.cos(4 * np.pi * x)
        h = np.clip(h, 0.05, None)

    h = _rescale(h)
    r_best = R_of(h)
    h_best = h.copy()
    print(f"init N={h.size} R={r_best:.6f} share={_band_share(h):.4f}")

    # Quick exact polish of start to make sure we're at H20 level
    if time.process_time() < deadline - 8.0:
        h = _lbfgs_block(h, np.arange(h.size), 400,
                         min(deadline, time.process_time() + 4.0), tie=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"base polish R={r:.6f} best={r_best:.6f} share={_band_share(h):.4f}")

    # Band-variance ladder
    taus = [0.999, 0.99, 0.95, 0.9]
    qs = [0.005, 0.01, 0.03]
    kappas = [0.5, 2.0, 8.0, 30.0, 100.0]

    def polish_and_check(h, tag):
        nonlocal r_best, h_best
        # exact tie polish
        if time.process_time() < deadline - 1.0:
            h2 = _lbfgs_block(h, np.arange(h.size), 300,
                              min(deadline, time.process_time() + 2.0), tie=True)
            r2 = R_of(h2)
            if r2 > r_best:
                r_best = r2; h_best = h2.copy()
                print(f"{tag} tie R={r2:.6f} best={r_best:.6f} share={_band_share(h2):.4f}")
            h = h2
        # peak-window polish
        if time.process_time() < deadline - 1.0:
            win = _peak_window(h, tol=0.999, pad_frac=0.3, extra=128)
            h3 = _lbfgs_block(h, win, 300,
                              min(deadline, time.process_time() + 2.0))
            r3 = R_of(h3)
            if r3 > r_best:
                r_best = r3; h_best = h3.copy()
                print(f"{tag} win R={r3:.6f} best={r_best:.6f} share={_band_share(h3):.4f}")
            h = h3
        return h

    # Run band ladder: alternate tau and q
    rungs = []
    for tau in taus:
        for kappa in kappas:
            rungs.append((tau, None, kappa))
    for q in qs:
        for kappa in kappas:
            rungs.append((None, q, kappa))

    for tau, q, kappa in rungs:
        if time.process_time() >= deadline - 6.0:
            break
        h = h_best.copy()
        h = _lbfgs_block(h, np.arange(h.size), 200,
                         min(deadline, time.process_time() + 2.0),
                         band=(tau, q, kappa))
        r = R_of(h)
        tag = f"tau={tau} q={q} k={kappa}"
        print(f"{tag} R={r:.6f} best={r_best:.6f} share={_band_share(h):.4f}")
        h = polish_and_check(h, tag)

    # Escape: perturb and re-polish
    for it in range(3):
        if time.process_time() >= deadline - 3.0:
            break
        act = np.flatnonzero(h_best > 0)
        if act.size == 0:
            break
        k = max(1, int(0.05 * act.size))
        sel = rng.choice(act, size=k, replace=False)
        h2 = h_best.copy()
        h2[sel] *= (1.0 + 0.05 * rng.standard_normal(k))
        h2 = _rescale(h2)
        h2 = _lbfgs_block(h2, np.arange(h2.size), 200,
                          min(deadline, time.process_time() + 3.0), tie=True)
        r2 = R_of(h2)
        if r2 > r_best:
            r_best = r2; h_best = h2.copy()
            print(f"escape{it} R={r2:.6f} best={r_best:.6f}")

    # Final pure exact-tier polish
    if time.process_time() < deadline - 0.5:
        h = h_best.copy()
        h = _lbfgs_block(h, np.arange(h.size), 800, deadline, tie=True)
        r = R_of(h)
        if r > r_best:
            r_best = r; h_best = h.copy()
        print(f"final tie R={r:.6f} best={r_best:.6f}")

    h_best = _rescale(h_best)
    print(f"done R={r_best:.6f} N={h_best.size} share={_band_share(h_best):.4f}")

    if s is not None and r_best < r_start:
        return {"best": s, "alternative": h_best}
    return h_best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c):
    return _rescale(np.repeat(c, 2))


def _polish(h, deadline, betas=(1e6, 1e7, 0.0)):
    ht = h
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, deadline - 0.3, beta=beta)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Extract the half-resolution signal only if the start has even length.
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4:
        c = best[0::2].copy()
        best_c = c.copy()
        best_cR = R_of(c)
        print("half-res R(c)=%.9f" % best_cR)

    alt_best = None
    alt_bestR = -1.0

    # Budget split: half-res search draws half of remaining budget, then alternate.
    def _try_full_lift(c, slice_deadline, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        hl = _lift(c)
        ht = _polish(hl, slice_deadline)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR, origin = ht.copy(), r, tag
            print("  %s NEW BEST R=%.9f" % (tag, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        return r

    if best_c is not None:
        half_deadline = t0 + budget_seconds * 0.30
        work_c = best_c.copy()
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, cand_c, cand_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
            if cand_cR > best_cR + 1e-13:
                best_c, best_cR = cand_c.copy(), cand_cR
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        # Lift the best half-resolution signal to full.
        _try_full_lift(best_c, deadline, 'lift')

    # Randomized restarts on the half-resolution signal, alternate with full polish.
    if best_c is not None:
        rng = np.random.default_rng(2024)
        ri = 0
        amps = [0.0015, 0.002, 0.003, 0.0025, 0.0018, 0.0035]
        while time.process_time() < deadline - 4.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc = best_c.copy()
            nz = cc > 0
            if nz.sum() == 0:
                break
            cc[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc = _rescale(cc)
            r0 = R_of(cc)
            slice_deadline = min(deadline - 2.0,
                                 time.process_time() + 0.05 * budget_seconds)
            work_c, cand_c, cand_cR, org = _half_cycle(
                cc, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.20, 0.15, 0.10])
            print("restart %d amp=%.4f R(c)=%.9f (best_c %.9f)" %
                  (ri, amp, cand_cR, best_cR))
            if cand_cR > best_cR + 1e-12:
                best_c, best_cR = cand_c.copy(), cand_cR
                print("  ACCEPT R(c)=%.9f" % best_cR)
            _try_full_lift(cand_c, slice_deadline, 'restart_lift%d' % ri)

    # Final polish of best half-res lift.
    if best_c is not None:
        _try_full_lift(best_c, deadline, origin + '+finlift')

    # Peak-window polish of the current best full signal.
    if time.process_time() < deadline - 1.5:
        for pad in [0.12, 0.08, 0.05]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # Trailing full-signal gradient polish.
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("restarts=%d best_c=%.9f best_full=%.9f" % (ri, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

