    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c):
    return _rescale(np.repeat(c, 2))


def _polish(h, deadline, betas=(1e6, 1e7, 0.0)):
    ht = h
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, deadline - 0.3, beta=beta)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Extract the half-resolution signal only if the start has even length.
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4:
        c = best[0::2].copy()
        best_c = c.copy()
        best_cR = R_of(c)
        print("half-res R(c)=%.9f" % best_cR)

    alt_best = None
    alt_bestR = -1.0

    # Budget split: half-res search draws half of remaining budget, then alternate.
    def _try_full_lift(c, slice_deadline, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        hl = _lift(c)
        ht = _polish(hl, slice_deadline)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR, origin = ht.copy(), r, tag
            print("  %s NEW BEST R=%.9f" % (tag, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        return r

    if best_c is not None:
        half_deadline = t0 + budget_seconds * 0.30
        work_c = best_c.copy()
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, cand_c, cand_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
            if cand_cR > best_cR + 1e-13:
                best_c, best_cR = cand_c.copy(), cand_cR
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        # Lift the best half-resolution signal to full.
        _try_full_lift(best_c, deadline, 'lift')

    # Randomized restarts on the half-resolution signal, alternate with full polish.
    if best_c is not None:
        rng = np.random.default_rng(2024)
        ri = 0
        amps = [0.0015, 0.002, 0.003, 0.0025, 0.0018, 0.0035]
        while time.process_time() < deadline - 4.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc = best_c.copy()
            nz = cc > 0
            if nz.sum() == 0:
                break
            cc[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc = _rescale(cc)
            r0 = R_of(cc)
            slice_deadline = min(deadline - 2.0,
                                 time.process_time() + 0.05 * budget_seconds)
            work_c, cand_c, cand_cR, org = _half_cycle(
                cc, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.20, 0.15, 0.10])
            print("restart %d amp=%.4f R(c)=%.9f (best_c %.9f)" %
                  (ri, amp, cand_cR, best_cR))
            if cand_cR > best_cR + 1e-12:
                best_c, best_cR = cand_c.copy(), cand_cR
                print("  ACCEPT R(c)=%.9f" % best_cR)
            _try_full_lift(cand_c, slice_deadline, 'restart_lift%d' % ri)

    # Final polish of best half-res lift.
    if best_c is not None:
        _try_full_lift(best_c, deadline, origin + '+finlift')

    # Peak-window polish of the current best full signal.
    if time.process_time() < deadline - 1.5:
        for pad in [0.12, 0.08, 0.05]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # Trailing full-signal gradient polish.
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("restarts=%d best_c=%.9f best_full=%.9f" % (ri, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_flat(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    sel = np.flatnonzero(Lf >= tau * mx)
    if sel.size > 0:
        Ls = Lf[sel]
        r = (mx - Ls) / mx
        m_r = r.mean()
        dpen_dL = np.zeros_like(Lf)
        coef = kappa * 2.0 * m_r
        dpen_dL[sel] += coef * (-1.0 / (sel.size * mx))
        dmdx = coef * (Ls.sum() / (sel.size * mx * mx))
        gLf[idx] += dmdx / idx.size
        gLf += dpen_dL
        pen = kappa * m_r * m_r
    else:
        pen = 0.0
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + pen
    return val, grad


def _fun_grad_beta(h, beta):
    """Sharpening objective: replace log(mx) with a log-sum-exp soft-max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - mx)
    zmax = z.max()
    ez = np.exp(z - zmax)
    S = ez.sum()
    lse = mx + (zmax + np.log(S)) / beta
    w = ez / S
    gLf = -dq / num
    gLf += w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(lse)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, tau=None, kappa=0.0,
                 beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta is not None:
        def fg(hh):
            return _fun_grad_beta(hh, beta)
    elif tau is not None:
        def fg(hh):
            return _fun_grad_flat(hh, tau, kappa)
    else:
        fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max_abs(h, frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _zero_frac(h):
    return float(np.mean(h <= 1e-12))


def _max_over_mean(h):
    m = h.mean()
    if m <= 0:
        return 0.0
    return float(h.max() / m)


def _coarsen(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _lift(h, factor, n_target):
    hh = np.repeat(h, factor)
    if hh.size < n_target:
        hh = np.concatenate([hh, np.full(n_target - hh.size, hh[-1])])
    elif hh.size > n_target:
        hh = hh[:n_target]
    return hh


def _smooth3(h, passes=2):
    h = h.copy()
    for _ in range(passes):
        hp = np.concatenate(([h[0]], h, [h[-1]]))
        h = 0.25 * hp[:-2] + 0.5 * hp[1:-1] + 0.25 * hp[2:]
    return h


def _contrast_restart(h, p):
    m = h.mean()
    if m <= 0:
        return h.copy()
    hh = m * np.power(np.clip(h, 0, None) / m, p)
    return _rescale(hh)


def _report(tag, h):
    print("%s: R=%.9f max/mean=%.2f near 0.1/1/5%%: %.4f/%.4f/%.4f"
          % (tag, R_of(h), _max_over_mean(h), _frac_near_max_abs(h, 1e-3),
             _frac_near_max_abs(h, 1e-2), _frac_near_max_abs(h, 5e-2)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zeros=%.3f, max/mean=%.2f)"
          % (bestR, best.size, _zero_frac(best), _max_over_mean(best)))
    print("frac near max 0.1/1/5%%: %.4f / %.4f / %.4f"
          % (_frac_near_max_abs(best, 1e-3), _frac_near_max_abs(best, 1e-2),
             _frac_near_max_abs(best, 5e-2)))

    alt_best = None
    altR = -1.0

    cur = best.copy()
    curR = bestR

    def consider(h_new, tag):
        nonlocal best, bestR, alt_best, altR, cur, curR
        r = R_of(h_new)
        _report(tag, h_new)
        if r > altR:
            altR = r; alt_best = h_new.copy()
        if r > bestR + 1e-15:
            best, bestR = h_new.copy(), r
        if r > curR + 1e-15:
            cur, curR = h_new.copy(), r
        return r

    N_full = cur.size
    full = np.arange(N_full)

    # ---- Stage A: beta (log-sum-exp) sharpening ladder ----
    betas = [1e3, 1e4, 1e5, 1e6, 1e7, 1e8]
    for beta in betas:
        if time.process_time() >= deadline - 3.0:
            break
        tlim = min(deadline - 2.5, time.process_time() + 3.0)
        hb = _lbfgs_block(cur, full, 200, tlim, beta=beta)
        consider(hb, "beta=%.0e" % beta)
        # exact tie polish between rungs
        if time.process_time() < deadline - 3.0:
            tlim = min(deadline - 2.5, time.process_time() + 1.5)
            ht = _lbfgs_block(cur, full, 100, tlim, tie=True)
            consider(ht, "  tie after beta=%.0e" % beta)

    print("after beta ladder: bestR=%.9f" % bestR)

    # ---- Stage B: contrast restarts ----
    for p in (1.5, 2.0, 3.0):
        if time.process_time() >= deadline - 3.0:
            break
        hc = _contrast_restart(cur, p)
        _report("contrast p=%.1f (pre)" % p, hc)
        tlim = min(deadline - 2.5, time.process_time() + 2.5)
        ht = _lbfgs_block(hc, full, 150, tlim, tie=True)
        consider(ht, "contrast p=%.1f tie" % p)

    print("after contrast restarts: bestR=%.9f" % bestR)

    # ---- Stage C: light flat-top rung then exact tie to deadline ----
    if time.process_time() < deadline - 3.0:
        tlim = min(deadline - 2.5, time.process_time() + 2.0)
        hf = _lbfgs_block(cur, full, 80, tlim, tau=0.5, kappa=1e3)
        consider(hf, "flat tau=0.5 kappa=1e3")

    # final exact tie polish, loop until near deadline
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 2.0)
        ht = _lbfgs_block(cur, full, 120, tlim, tie=True)
        r = R_of(ht)
        _report("final tie", ht)
        if r > altR:
            altR = r; alt_best = ht.copy()
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            break

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d, zeros=%.3f, max/mean=%.2f)"
          % (bestR, startR, best.size, _tie_count(best), _zero_frac(best),
             _max_over_mean(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

