    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _lift_noncomm(h, num, den):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N == 0 or h.sum() <= 0:
        return h.copy()
    M = int(np.ceil(N * num / den))
    if M < 1:
        M = 1
    cs = np.concatenate(([0.0], np.cumsum(h)))
    cs /= cs[-1]
    pos = np.arange(M + 1, dtype=float) * (den / num)
    pos = np.clip(pos, 0.0, N)
    vals = np.interp(pos, np.arange(N + 1, dtype=float), cs)
    hp = np.diff(vals)
    hp = np.clip(hp, 0, None)
    s = hp.sum()
    if s > 0:
        hp = hp / s * h.sum()
    return hp


def _map_back(hp, N):
    hp = np.clip(np.asarray(hp, dtype=float), 0, None)
    M = hp.size
    if M == 0:
        return np.zeros(N)
    cs = np.concatenate(([0.0], np.cumsum(hp)))
    if cs[-1] <= 0:
        return np.zeros(N)
    cs /= cs[-1]
    pos = np.arange(N + 1, dtype=float) * (M / N)
    pos = np.clip(pos, 0.0, M)
    vals = np.interp(pos, np.arange(M + 1, dtype=float), cs)
    h = np.diff(vals)
    h = np.clip(h, 0, None)
    s = h.sum()
    if s > 0:
        h = h / s * hp.sum()
    return h


def _smooth_perturb(h, rng, amp=0.02):
    """Smooth multiplicative perturbation using a low-frequency random field."""
    n = h.size
    k = max(3, n // 200)
    kmax = min(k, n // 2)
    if kmax < 2:
        return h.copy()
    c = rng.standard_normal(kmax)
    u = np.linspace(0, np.pi * (kmax - 1), n)
    field = np.zeros(n)
    for j in range(kmax):
        field += c[j] * np.cos((j + 1) * u)
    field /= (np.abs(field).max() + 1e-12)
    hp = h * (1.0 + amp * field)
    return np.clip(hp, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N0 = best.size
    rng = np.random.default_rng(12345)
    print("base R=%.12f (N=%d)" % (bestR, N0))
    print("frac near max (0.1%%/1%%/5%%) before: %.4f / %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    alt_best = None
    altR = -1.0

    def try_update(hcand, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hcand)
        fr1 = _frac_near_max(hcand, 1e-2)
        print("  %s: R=%.12f (1%% near max=%.4f)" % (tag, r, fr1))
        if r > altR:
            altR = r
            alt_best = hcand.copy()
        if r > bestR + 1e-15:
            best, bestR = hcand.copy(), r
            return True
        return False

    # Initial tie polish of start
    if time.process_time() < deadline - 3.0:
        tlim = min(deadline - 2.0, time.process_time() + 6.0)
        pol = _lbfgs_block(best, np.arange(best.size), 200, tlim)
        try_update(pol, "init tie polish")

    # Perturb-and-polish restarts: smooth multiplicative perturbations of best,
    # then tie-polish. This explores new local optima directly at full N.
    cycle = 0
    while time.process_time() < deadline - 2.5:
        cycle += 1
        if cycle > 40:
            break
        amp = 0.02 + 0.03 * ((cycle % 5) / 4.0)
        hp = _smooth_perturb(best, rng, amp=amp)
        hp = _rescale(hp)
        tlim = min(deadline - 1.5, time.process_time() + 4.0)
        if tlim <= time.process_time() + 0.5:
            break
        hpol = _lbfgs_block(hp, np.arange(hp.size), 120, tlim)
        try_update(hpol, "perturb cycle %d (amp=%.3f)" % (cycle, amp))

    # Lift 5:4 polish and back map as a final structural move
    if time.process_time() < deadline - 2.0:
        hp = _lift_noncomm(best, 5, 4)
        if hp.size >= 2:
            tlim = min(deadline - 1.0, time.process_time() + 4.0)
            if tlim > time.process_time() + 0.5:
                hp2 = _lbfgs_block(hp, np.arange(hp.size), 150, tlim)
                hb = _rescale(_map_back(hp2, N0))
                try_update(hb, "lift 5:4 back-map")

    print("frac near max (0.1%%/1%%/5%%) after: %.4f / %.4f / %.4f"
          % (_frac_near_max(best, 1e-3), _frac_near_max(best, 1e-2),
             _frac_near_max(best, 5e-2)))

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None and alt_best is not None:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_shape(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, shape=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_shape if shape else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.25, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = idx.min(); hi = idx.max()
    pad = int(pad_frac * (hi - lo)) + extra
    lo = max(0, lo - pad); hi = min(h.size, hi + pad)
    return np.arange(lo, hi)


def _resample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xi = (np.arange(N) + 0.5) * (n / N) - 0.5
    xi = np.clip(xi, 0, n - 1)
    i0 = np.floor(xi).astype(int)
    i1 = np.minimum(i0 + 1, n - 1)
    t = xi - i0
    return h[i0] * (1 - t) + h[i1] * t


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(1357911)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        start_best = _rescale(np.ones(N))
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best_h = start_best.copy()
    best_R = start_bestR
    alt_h = None
    alt_R = 0.0

    # Track 1: shape-gradient refine (no peak-locking bias) on full support.
    if time.process_time() < deadline - 3.0:
        h = _lbfgs_block(best_h, np.arange(best_h.size), 600,
                         min(deadline - 3.0, time.process_time() + 8.0), shape=True)
        r = R_of(h)
        if r > best_R + 1e-13:
            best_R = r; best_h = h.copy()
            print("  shape refine R=%.7f" % best_R)

    # Track 2: peak-window block refine with shape gradient.
    if time.process_time() < deadline - 3.0:
        for tol in (0.9999, 0.999, 0.99):
            if time.process_time() >= deadline - 2.0:
                break
            free = _peak_window(best_h, tol=tol)
            sub = min(deadline - 2.0, time.process_time() + 6.0)
            h = _lbfgs_block(best_h, free, 400, sub, shape=True)
            r = R_of(h)
            if r > best_R + 1e-13:
                best_R = r; best_h = h.copy()
                print("  shape peak tol=%.4f R=%.7f" % (tol, best_R))
            elif r > alt_R + 1e-13 and alt_h is None:
                alt_R = r; alt_h = h.copy()

    # Track 3: upsampled full refine to escape discretisation ceiling.
    if time.process_time() < deadline - 3.0 and best_h.size <= 400000:
        N2 = min(1000000, best_h.size * 2)
        h2 = _resample(best_h, N2)
        sub = min(deadline - 2.0, time.process_time() + 10.0)
        h2 = _lbfgs_block(h2, np.arange(h2.size), 500, sub, shape=True)
        r = R_of(h2)
        if r > best_R + 1e-13:
            best_R = r; best_h = h2.copy()
            print("  upsample N=%d R=%.7f" % (N2, best_R))
        elif r > alt_R + 1e-13 and alt_h is None:
            alt_R = r; alt_h = h2.copy()

    # Track 4: ILS with multi-scale kicks then shape refine.
    n_rounds = 0
    while time.process_time() < deadline - 1.0:
        h = best_h.copy()
        kick = (0.06, 0.02, 0.0)[n_rounds % 3]
        if kick > 0:
            n = h.size
            w = max(64, n // 6)
            lo = max(0, n // 2 - w); hi = min(n, n // 2 + w)
            h[lo:hi] *= np.exp(kick * rng.standard_normal(hi - lo))
            h = _rescale(h)
        free = _peak_window(h, tol=0.999, pad_frac=0.3)
        sub = min(deadline - 0.5, time.process_time() + 4.0)
        h = _lbfgs_block(h, free, 300, sub, shape=True)
        r = R_of(h)
        if r > best_R + 1e-13:
            best_R = r; best_h = h.copy()
            print("  ILS %d R=%.7f" % (n_rounds, best_R))
        n_rounds += 1
        if n_rounds > 200:
            break

    # Final polish: alternate full and peak-window shape refine.
    while time.process_time() < deadline - 0.5:
        h1 = _lbfgs_block(best_h, np.arange(best_h.size), 300,
                          min(deadline - 0.5, time.process_time() + 3.0), shape=True)
        r1 = R_of(h1)
        if r1 > best_R + 1e-13:
            best_R = r1; best_h = h1.copy()
        free = _peak_window(best_h, tol=0.9999, pad_frac=0.2)
        h2 = _lbfgs_block(best_h, free, 250,
                          min(deadline - 0.3, time.process_time() + 3.0), shape=True)
        r2 = R_of(h2)
        if r2 > best_R + 1e-13:
            best_R = r2; best_h = h2.copy()
        else:
            break

    print("final best R=%.7f (start %.7f)" % (best_R, start_bestR))

    if best_R > start_bestR + 1e-12:
        if alt_h is not None and alt_R > start_bestR + 1e-12 and alt_R < best_R - 1e-9:
            return {"best": best_h, "alternative": alt_h}
        return best_h
    if alt_h is not None and alt_R > start_bestR - 1e-9:
        return {"best": start_best, "alternative": alt_h}
    return start_best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_period(h, maxT=64):
    n = h.size
    for T in range(2, maxT + 1):
        if n % T != 0:
            continue
        K = n // T
        bm = h.reshape(K, T).mean(axis=1)
        rep = np.repeat(bm, T)
        if np.max(np.abs(h - rep)) < 1e-9:
            return T, K
    return None, None


# ---------------- fast staircase machinery ----------------

def _tri(T):
    a = np.arange(1, T + 1, dtype=float)
    return np.concatenate((a, a[-2::-1]))


def _knots_fast(c, T):
    cc = np.convolve(c, c)
    up = np.zeros(cc.size * T, dtype=float)
    up[::T] = cc
    tri = _tri(T)
    L = np.convolve(up, tri)
    return np.concatenate(([0.0], L, [0.0]))


def R_fast(c, T):
    c = np.asarray(c, dtype=float)
    s = c.sum()
    if s <= 0:
        return 0.0
    L = _knots_fast(c, T)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * T * T * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _fast_num_grad(c, T):
    c = np.asarray(c, dtype=float)
    s = c.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    cc = np.convolve(c, c)
    up = np.zeros(cc.size * T, dtype=float)
    up[::T] = cc
    tri = _tri(T)
    Lk = np.convolve(up, tri)
    Lf = np.concatenate(([0.0], Lk, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    if num <= 0:
        return 1e18, np.zeros(c.size)
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf = -dq / num
    gLf[idx] += (1.0 / idx.size) / mx
    gLk = np.correlate(gLf, tri, mode='valid')[:Lk.size]
    gcc = gLk[::T][:cc.size]
    gc = 2.0 * np.correlate(gcc, c, mode='valid')[:c.size]
    val = -np.log(num) + 2.0 * np.log(s) + 2.0 * np.log(T) + np.log(mx)
    gc = gc + 2.0 / s
    return val, gc


def _resample_linear(c, Knew):
    K = c.size
    if K == Knew:
        return c.copy()
    x = np.linspace(0.0, 1.0, K)
    xn = np.linspace(0.0, 1.0, Knew)
    out = np.interp(xn, x, c)
    return np.clip(out, 0, None)


def _opt_c(c0, T, deadline, maxiter=1500):
    c0 = np.clip(np.asarray(c0, dtype=float), 0, None)
    if c0.sum() <= 0:
        return c0, -1.0
    x0 = c0.copy()

    def f(x):
        return _fast_num_grad(np.clip(x, 0.0, None), T)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0, R_fast(c0, T)
    if res is None or not np.all(np.isfinite(res.x)):
        return c0, R_fast(c0, T)
    c = np.clip(res.x, 0.0, None)
    return c, R_fast(c, T)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N = best.size
    T0, K0 = _detect_period(best)
    print("detected period T=%s K=%s" % (T0, K0))

    # The staircase sweep: try many T, keep the best (T, c), then map back.
    sweep_best_R = -1.0
    sweep_best = None

    if T0 is not None and T0 >= 2:
        c0 = best.reshape(K0, T0).mean(axis=1)
        rng = np.random.RandomState(999)
        T_list = [2, 3, 4, 5, 6, 7, 8, 10, 12, 14, 16, 20, 24, 28, 30, 31,
                  32, 33, 34, 36, 40, 44, 48, 52, 56, 60, 64]
        per_T_budget = 1.2
        for T in T_list:
            if time.process_time() >= deadline - 10.0:
                break
            K_T = int(round(N / T))
            if K_T < 2 or K_T > 4000:
                continue
            cT = _resample_linear(c0, K_T)
            if cT.sum() <= 0:
                continue
            tlim = min(deadline - 10.0, time.process_time() + per_T_budget * 0.6)
            cA, rA = _opt_c(cT, T, tlim)
            jit = np.clip(cT * (1.0 + 0.02 * rng.randn(K_T)), 1e-9, None)
            tlim2 = min(deadline - 10.0, time.process_time() + per_T_budget * 0.4)
            cB, rB = _opt_c(jit, T, tlim2)
            if rB > rA:
                cA, rA = cB, rB
            print("sweep T=%d K=%d R_fast=%.12f" % (T, K_T, rA))
            if rA > sweep_best_R:
                sweep_best_R = rA
                sweep_best = (T, cA.copy())

    if sweep_best is not None:
        Tb, cb = sweep_best
        hb = np.repeat(cb, Tb)
        if hb.size <= 1000000:
            hb = _rescale(hb)
            rb = R_of(hb)
            print("mapped best T=%d N=%d R_of=%.12f" % (Tb, hb.size, rb))
            if rb > bestR + 1e-15:
                best, bestR = hb.copy(), rb

    # Full-resolution tie polish on best
    if time.process_time() < deadline - 0.5:
        tlim = deadline - 0.3
        pol = _lbfgs_block(best, np.arange(best.size), 400, tlim, tie=True)
        rp = R_of(pol)
        print("final tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    # peak-window polish
    if time.process_time() < deadline - 0.5:
        win = _peak_window(best)
        tlim = deadline - 0.3
        pol = _lbfgs_block(best, win, 400, tlim, tie=True)
        rp = R_of(pol)
        print("peak-window polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if sweep_best is not None:
        Tb, cb = sweep_best
        hb = np.repeat(cb, Tb)
        if hb.size <= 1000000:
            hb = _rescale(hb)
            rb = R_of(hb)
            if rb > startR + 1e-14 and rb < bestR - 1e-14:
                result["alternative"] = hb
    return result

import numpy as np
import time
from scipy.optimize import minimize


def _L(h):
    return np.concatenate(([0.0], np.convolve(h, h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _L(h)
    num = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    den = s * s * max(L.max(), 1e-300)
    return num / den


def _rescale(h):
    h = np.clip(np.asarray(h, dtype=float), 0.0, None)
    m = h.max()
    if m > 0:
        h = h / m
    return h


def _softmax_surrogate(L, beta):
    m = L.max()
    return m + np.log(np.sum(np.exp(beta * (L - m)))) / beta


def _stats(h):
    L = _L(h)
    mx = L.max()
    nz = float(np.mean(h == 0))
    mm = float(h.max() / max(h.mean(), 1e-300))
    near = [float(np.mean(np.abs(L - mx) <= f * mx)) for f in (0.01, 0.05)]
    return nz, mm, near


def _exact_obj(h):
    """-log R."""
    s = h.sum()
    if s <= 0:
        return 1e18
    L = _L(h)
    num = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    Lmax = L.max()
    if Lmax <= 0 or num <= 0:
        return 1e18
    return -np.log(num / (s * s * Lmax))


def _sharp_obj(h, lam, beta=1e6):
    """log Q - 2 log S - lam*log(max) with softmax max surrogate."""
    s = h.sum()
    if s <= 0:
        return 1e18
    L = _L(h)
    num = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    if num <= 0:
        return 1e18
    Lmax = _softmax_surrogate(L, beta)
    return np.log(num) - 2.0 * np.log(s) - lam * np.log(Lmax)


def _polish_exact(h, maxiter=200):
    h = np.asarray(h, dtype=float).copy()
    n = len(h)

    def fun(x):
        return _exact_obj(np.clip(x, 0.0, None))

    try:
        res = minimize(fun, h, method="L-BFGS-B",
                       bounds=[(0.0, None)] * n,
                       options={"maxiter": maxiter, "maxfun": maxiter * 2})
        h = np.clip(res.x, 0.0, None)
    except Exception:
        pass
    return _rescale(h)


def _polish_sharp(h, lam, maxiter=200):
    h = np.asarray(h, dtype=float).copy()
    n = len(h)

    def fun(x):
        return _sharp_obj(np.clip(x, 0.0, None), lam)

    try:
        res = minimize(fun, h, method="L-BFGS-B",
                       bounds=[(0.0, None)] * n,
                       options={"maxiter": maxiter, "maxfun": maxiter * 2})
        h = np.clip(res.x, 0.0, None)
    except Exception:
        pass
    return _rescale(h)


def _peak_window_polish(h, pad, maxiter=150):
    h = np.asarray(h, dtype=float).copy()
    n = len(h)
    L = _L(h)
    j = int(np.argmax(L))
    lo = max(0, j - int(pad * n) - 1)
    hi = min(n, j + int(pad * n) + 1)
    if hi - lo < 2:
        return h
    idx = np.arange(lo, hi)

    def fun(x):
        hh = h.copy()
        hh[idx] = np.clip(x, 0.0, None)
        return _exact_obj(hh)

    try:
        res = minimize(fun, h[idx], method="L-BFGS-B",
                       bounds=[(0.0, None)] * len(idx),
                       options={"maxiter": maxiter, "maxfun": maxiter * 2})
        h[idx] = np.clip(res.x, 0.0, None)
    except Exception:
        pass
    return _rescale(h)


def _lift_double(h):
    n = len(h)
    out = np.zeros(2 * n)
    out[0::2] = h
    out[1::2] = h
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.9 * budget_seconds

    def now():
        return time.process_time()

    best = None
    best_R = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        best = s
        best_R = R_of(s)
        print("start R:", round(best_R, 6), "N:", len(s))

    if best is None:
        best = np.ones(50)
        best_R = R_of(best)

    def consider(h2, tag):
        nonlocal best, best_R
        r = R_of(h2)
        if r > best_R:
            best_R = r
            best = h2.copy()
        nz, mm, near = _stats(h2)
        print(f"{tag} R={r:.6f} best={best_R:.6f} nz={nz:.3f} mm={mm:.2f} near={near}")
        return r

    # (A) exact polish at current N
    h = best.copy()
    if now() < deadline:
        h2 = _polish_exact(h, maxiter=250)
        consider(h2, "A-exact")
        h = best.copy()
    if now() < deadline:
        h2 = _peak_window_polish(h, 0.15, maxiter=150)
        consider(h2, "A-peak")
        h = best.copy()

    # (B) sharpening ladder
    for lam in [0.2, 0.5, 1.0, 2.0]:
        if now() > deadline:
            break
        rung_dl = min(deadline, now() + 4.0)
        h2 = h
        for _ in range(2):
            if now() > rung_dl:
                break
            h2 = _polish_sharp(h2, lam, maxiter=200)
        # exact-R polish after each rung
        if now() < deadline:
            h3 = _polish_exact(h2, maxiter=150)
        else:
            h3 = h2
        r = consider(h3, f"B-lam{lam}")
        # accept only strict exact-R gains for continuation
        if r > R_of(h):
            h = h3
        else:
            h = best.copy()

    # (C) support trials
    if now() < deadline:
        h = best.copy()
        n = len(h)
        k = max(1, int(0.02 * n))
        idx = np.argsort(h)[:k]
        h2 = h.copy()
        h2[idx] = 0.0
        h2 = _polish_exact(h2, maxiter=150)
        consider(h2, "C-prune")
    if now() < deadline:
        h = best.copy()
        zeros = np.where(h == 0)[0]
        if len(zeros) > 0:
            k = max(1, int(0.01 * len(h)))
            sel = zeros[:k]
            h2 = h.copy()
            h2[sel] = 1e-3 * h.mean()
            h2 = _polish_exact(h2, maxiter=150)
            consider(h2, "C-revive")

    # (D) doubling ladder
    h = best.copy()
    for target in [8192, 16384, 32768]:
        if now() > deadline:
            break
        if len(h) * 2 > target:
            continue
        h = _rescale(_lift_double(h))
        if now() < deadline:
            h = _polish_exact(h, maxiter=200)
        consider(h, f"D-lift{len(h)}")
        if now() < deadline:
            h2 = _peak_window_polish(h, 0.15, maxiter=150)
            consider(h2, f"D-peak{len(h)}")
        h = best.copy()

    # final polish until 1.5s before deadline
    h = best.copy()
    while now() < deadline - 1.5:
        h2 = _polish_exact(h, maxiter=150)
        r = R_of(h2)
        if r > best_R:
            best_R = r
            best = h2.copy()
            h = h2
        else:
            break

    final = _rescale(best)
    r = R_of(final)
    nz, mm, near = _stats(final)
    print("final R:", r, "N:", len(final), "zero frac:", round(nz, 4),
          "max/mean:", round(mm, 2), "near-max 1%/5%:", [round(x, 4) for x in near])

    result = {"best": final}
    if start is not None:
        sr = R_of(np.asarray(start, dtype=float))
        if sr > r:
            result["best"] = np.asarray(start, dtype=float)
        else:
            result["alternative"] = np.asarray(start, dtype=float)
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 3 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.5, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _to_quotient(h, Nq):
    N = h.size
    if N == Nq:
        return h.copy()
    if N % Nq == 0:
        return h.reshape(Nq, N // Nq).mean(axis=1)
    idx = (np.arange(Nq + 1) * N) // Nq
    return np.array([h[idx[i]:max(idx[i] + 1, idx[i + 1])].mean()
                     for i in range(Nq)])


def _lift(c, Nq, Nfull):
    if Nfull == Nq:
        return c.copy()
    xq = (np.arange(Nq) + 0.5) / Nq
    xf = (np.arange(Nfull) + 0.5) / Nfull
    h = np.interp(xf, xq, c)
    return _rescale(np.clip(h, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)

    bestR = R_of(best)
    startR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Track the best "genuinely new" construction separately.
    alt_best = None
    altR = -1.0

    # Multi-scale refinement: try several working resolutions.
    # Key idea from p2495: work at reduced representations, polish, then lift.
    # We run a ladder of coarsen -> polish -> lift, keeping the best.
    candidates = []

    Nfull = best.size

    # Build a coarsening ladder anchored on the start's resolution.
    # Try several quotient sizes and polish each fully before lifting.
    ladder = []
    for Nq in (1024, 2048, 4096, 8192):
        if Nq <= Nfull:
            ladder.append(Nq)
    if Nfull not in ladder:
        ladder.append(Nfull)
    ladder = sorted(set(ladder))

    # Seed: coarse version of best
    seeds = []
    for Nq in ladder:
        c = _to_quotient(best, Nq) if Nq != Nfull else best.copy()
        c = _rescale(np.clip(c, 0, None))
        seeds.append((Nq, c, R_of(c)))

    # Sort seeds by R descending; polish the most promising first.
    seeds.sort(key=lambda z: -z[2])

    work = seeds[0][1].copy()
    workN = seeds[0][0]
    workR = seeds[0][2]

    # Phase 1: full polish at the best coarse resolution we have.
    if time.process_time() < deadline - 15.0:
        h = _lbfgs_block(work, np.arange(work.size), 400,
                         min(deadline - 12.0, time.process_time() + 8.0))
        r = R_of(h)
        if r > workR:
            work, workR = h, r
        print("phase1 polish N=%d R=%.12f" % (work.size, workR))

    # Phase 2: lift to next resolution(s), polish peak window then full.
    Ntarget = Nfull
    if workN < Ntarget:
        h_lift = _lift(work, workN, Ntarget)
        r_lift = R_of(h_lift)
        print("lift -> N=%d R=%.12f" % (Ntarget, r_lift))
        if r_lift > workR:
            work, workR = h_lift, r_lift
            workN = Ntarget

    # Phase 3: iterative polish at full resolution (peak window + full),
    # repeated while budget remains. This is the main workhorse.
    it = 0
    while time.process_time() < deadline - 3.0:
        it += 1
        prevR = workR
        # Peak window polish
        win = _peak_window(work, tol=0.999, pad_frac=0.3, extra=256)
        h = _lbfgs_block(work, win, 300,
                         min(deadline - 2.0, time.process_time() + 4.0))
        r = R_of(h)
        if r > workR + 1e-16:
            work, workR = h, r
        # Full polish
        if time.process_time() < deadline - 2.0:
            h = _lbfgs_block(work, np.arange(work.size), 300,
                             min(deadline - 1.0, time.process_time() + 4.0))
            r = R_of(h)
            if r > workR + 1e-16:
                work, workR = h, r
        if workR - prevR < 1e-13:
            break
    print("phase3 iters=%d R=%.12f" % (it, workR))

    if workR > altR:
        alt_best = work.copy()
        altR = workR

    # Final: keep the better of work and start for "best".
    if workR > bestR:
        best, bestR = work.copy(), workR

    # Final safety: ensure best is at least start.
    if start is not None and bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-14:
        result["alternative"] = alt_best
    elif alt_best is not None and altR <= startR + 1e-14 and start is not None:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------------- new: coordinate/block sweeps on the peak ----------------

def _block_sweep(h, deadline, tol=1e-15):
    """Sweep disjoint blocks across the peak window, optimizing each with
    tie-aware L-BFGS. Accepts improvements greedily."""
    win = _peak_window(h, pad_frac=0.15, extra=128)
    lo, hi = int(win[0]), int(win[-1])
    span = hi - lo + 1
    # choose block sizes: coarse to fine
    for bsize in (max(8, span // 24), max(4, span // 48), max(2, span // 96), 1):
        if time.process_time() >= deadline - 0.5:
            break
        nblk = max(1, span // bsize)
        step = max(1, bsize)
        base = R_of(h)
        for k in range(nblk):
            if time.process_time() >= deadline - 0.5:
                break
            a = lo + k * step
            b = min(hi + 1, a + step)
            if b <= a:
                continue
            blk = np.arange(a, b)
            ht = _lbfgs_block(h, blk, 40, deadline - 0.3, tie=True)
            rt = R_of(ht)
            if rt > base + tol:
                h = ht
                base = rt
    return h


# ---------------- new: mass-resample to different N ----------------

def _mass_resample(base, newN):
    n = base.size
    if n == newN:
        return _rescale(base.copy())
    c = np.concatenate(([0.0], np.cumsum(base)))
    total = c[-1]
    if total <= 0:
        return _rescale(np.ones(newN))
    edges = np.linspace(0.0, total, newN + 1)
    x_src = np.linspace(0.0, 1.0, n + 1)
    x_new = np.interp(edges, c, x_src)
    widths = np.diff(x_new)
    masses = np.diff(edges)
    h = np.where(widths > 1e-15, masses / np.maximum(widths, 1e-15), 0.0)
    return _rescale(h)


def _polish(h, deadline, rounds=6, iters=400):
    """Alternating full tie-polish and peak-ladder polish."""
    best = h
    bestR = R_of(h)
    for it in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        slice_end = min(deadline, time.process_time() + 6.0)
        ht = _lbfgs_block(best, np.arange(best.size), iters,
                          slice_end - 0.5, tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
        if time.process_time() < slice_end - 0.5:
            win = _peak_window(best, pad_frac=0.08, extra=128)
            ht = _lbfgs_block(best, win, iters, slice_end - 0.3, tie=True)
            rt = R_of(ht)
            if rt > bestR + 1e-15:
                best, bestR = ht, rt
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, N, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- Try resampling to a few alternate N values, polish each briefly,
    #      keep whichever wins. This explores a genuinely different line. ----
    alt_best = best
    alt_bestR = bestR
    alt_N = N
    resample_targets = []
    for mult in (1.5, 0.75, 2.0, 0.5):
        tgt = int(round(N * mult))
        tgt = max(64, min(1_000_000, tgt))
        if tgt != N:
            resample_targets.append(tgt)

    race_end = t0 + budget_seconds * 0.45
    for tgt in resample_targets:
        if time.process_time() >= race_end - 2.0:
            break
        try:
            cand = _mass_resample(best, tgt)
        except Exception:
            continue
        slice_end = min(race_end, time.process_time() + 5.0)
        ht, rt = _polish(cand, slice_end, rounds=3, iters=200)
        if rt > alt_bestR + 1e-15:
            alt_best, alt_bestR, alt_N = ht, rt, ht.size
        print("resample N=%d dR=%+.3e R=%.9f"
              % (tgt, rt - bestR, rt))

    if alt_bestR > bestR + 1e-15:
        best, bestR, N = alt_best, alt_bestR, alt_N
        print("resample won: N=%d R=%.9f" % (N, bestR))

    # ---- Block-coordinate sweeps on the peak (new idea) ----
    sweep_end = t0 + budget_seconds * 0.68
    while time.process_time() < sweep_end - 3.0:
        h_s = _block_sweep(best, min(sweep_end, time.process_time() + 10.0))
        r_s = R_of(h_s)
        dR = r_s - bestR
        accepted = r_s > bestR + 1e-15
        if accepted:
            best, bestR = h_s, r_s
        print("block sweep dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f"
              % (dR, "ACCEPT" if accepted else "no gain", bestR,
                 _tie_count(h_s), _zero_frac(h_s)))
        # follow with a full tie polish
        if time.process_time() < sweep_end - 3.0:
            slice_end = min(sweep_end, time.process_time() + 8.0)
            ht = _lbfgs_block(best, np.arange(best.size), 600,
                              slice_end - 0.5, tie=True)
            rt = R_of(ht)
            if rt > bestR + 1e-15:
                best, bestR = ht, rt
                print("  full polish ACCEPT R=%.9f" % bestR)

    # ---- Final polish loop ----
    loop_end = t0 + budget_seconds * 0.90
    it = 0
    while time.process_time() < loop_end - 2.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 6.0)
        ht = _lbfgs_block(best, np.arange(best.size), 600,
                          slice_end - 0.5, tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
            print("final pass %d ACCEPT R=%.9f" % (it, bestR))
        else:
            print("final pass %d no gain R=%.9f" % (it, rt))
            break
        if time.process_time() < slice_end - 0.5:
            win = _peak_window(best, pad_frac=0.05, extra=128)
            ht = _lbfgs_block(best, win, 300, slice_end - 0.3, tie=True)
            rt = R_of(ht)
            if rt > bestR + 1e-15:
                best, bestR = ht, rt

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, tau):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - tau))
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    gLf[idx] += 1.0 / (idx.size * Lf[idx])
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_flat_top(h, tau, kappa):
    """Flat-top variance penalty: encourage a wide plateau of f*f near max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h, 1e-10)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    S = Lf >= tau * mx
    nS = int(np.count_nonzero(S))
    V = 0.0
    if nS > 1:
        Ls = Lf[S]
        Lbar = Ls.mean()
        diff = Ls - Lbar
        V = float(np.sum(diff * diff)) / (mx * mx * nS)
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * diff / (mx * mx * nS)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * V
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    alt_best = None
    altR = -1.0
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, altR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("BEST R=%.9f (%s N=%d)" % (bestR, tag, best.size))
            return True
        if r > altR:
            alt_best, altR = cand.copy(), r
        return False

    # ---- Phase 1: flat-top penalty ladder on multiscale coarsened grids ----
    # Coarsen to a small grid, drive a wide flat plateau of f*f via variance
    # penalty, prolongate back up; repeat at finer scales.
    phase1_deadline = t0 + budget_seconds * 0.45
    for Q in (16, 8, 4, 2, 1):
        if time.process_time() >= phase1_deadline - 3.0:
            break
        if best.size % Q != 0:
            continue
        qh = best if Q == 1 else _coarsen(best, Q)
        if qh is None or qh.size < 32:
            continue
        for (tau, kappa) in ((0.9, 1.0), (0.9, 5.0), (0.95, 10.0)):
            if time.process_time() >= phase1_deadline - 2.0:
                break
            fg = (lambda hh, tau=tau, kappa=kappa:
                  _fun_grad_flat_top(hh, tau, kappa))
            qh2 = _lbfgs_block(qh, np.arange(qh.size), 300,
                               phase1_deadline - 1.0, fg)
            if R_of(_prolongate(qh2, Q)) > R_of(_prolongate(qh, Q)):
                qh = qh2
        cand = _prolongate(qh, Q)
        offer(cand, 'flat-top Q=%d' % Q)
    print("Phase1 done R=%.9f" % bestR)

    # ---- Phase 2: exact tie subgradient ladder at full resolution ----
    phase2_deadline = t0 + budget_seconds * 0.75
    for tau in (1e-12, 1e-10, 1e-8, 1e-6, 1e-4):
        if time.process_time() >= phase2_deadline - 2.0:
            break
        fg = (lambda hh, tau=tau: _fun_grad_tie(hh, tau))
        ht = _lbfgs_block(best, np.arange(best.size), 300,
                          phase2_deadline - 1.0, fg)
        offer(ht, 'tie tau=%.0e' % tau)
    print("Phase2 done R=%.9f" % bestR)

    # ---- Phase 3: final polishing with flat-top and plain tie ----
    final_deadline = t0 + budget_seconds * 0.98
    fg = (lambda hh: _fun_grad_flat_top(hh, 0.95, 20.0))
    ht = _lbfgs_block(best, np.arange(best.size), 400,
                      final_deadline - 1.0, fg)
    offer(ht, 'final floattop')
    fg = (lambda hh: _fun_grad_tie(hh, 1e-9))
    ht = _lbfgs_block(best, np.arange(best.size), 400,
                      final_deadline - 0.3, fg)
    offer(ht, 'final tie')

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and altR < bestR:
        result["alternative"] = alt_best
    return result

