    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h, 1e-10)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    S = Lf >= tau * mx
    nS = int(np.count_nonzero(S))
    V = 0.0
    if nS > 1:
        Ls = Lf[S]
        Lbar = Ls.mean()
        diff = Ls - Lbar
        V = float(np.sum(diff * diff)) / (mx * mx * nS)
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * diff / (mx * mx * nS)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * V
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    alt_best = None
    altR = -1.0
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, altR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("BEST R=%.9f (%s N=%d)" % (bestR, tag, best.size))
            return True
        if r > altR:
            alt_best, altR = cand.copy(), r
        return False

    # ---- Phase 1: flat-top penalty ladder on multiscale coarsened grids ----
    # Coarsen to a small grid, drive a wide flat plateau of f*f via variance
    # penalty, prolongate back up; repeat at finer scales.
    phase1_deadline = t0 + budget_seconds * 0.45
    for Q in (16, 8, 4, 2, 1):
        if time.process_time() >= phase1_deadline - 3.0:
            break
        if best.size % Q != 0:
            continue
        qh = best if Q == 1 else _coarsen(best, Q)
        if qh is None or qh.size < 32:
            continue
        for (tau, kappa) in ((0.9, 1.0), (0.9, 5.0), (0.95, 10.0)):
            if time.process_time() >= phase1_deadline - 2.0:
                break
            fg = (lambda hh, tau=tau, kappa=kappa:
                  _fun_grad_flat_top(hh, tau, kappa))
            qh2 = _lbfgs_block(qh, np.arange(qh.size), 300,
                               phase1_deadline - 1.0, fg)
            if R_of(_prolongate(qh2, Q)) > R_of(_prolongate(qh, Q)):
                qh = qh2
        cand = _prolongate(qh, Q)
        offer(cand, 'flat-top Q=%d' % Q)
    print("Phase1 done R=%.9f" % bestR)

    # ---- Phase 2: exact tie subgradient ladder at full resolution ----
    phase2_deadline = t0 + budget_seconds * 0.75
    for tau in (1e-12, 1e-10, 1e-8, 1e-6, 1e-4):
        if time.process_time() >= phase2_deadline - 2.0:
            break
        fg = (lambda hh, tau=tau: _fun_grad_tie(hh, tau))
        ht = _lbfgs_block(best, np.arange(best.size), 300,
                          phase2_deadline - 1.0, fg)
        offer(ht, 'tie tau=%.0e' % tau)
    print("Phase2 done R=%.9f" % bestR)

    # ---- Phase 3: final polishing with flat-top and plain tie ----
    final_deadline = t0 + budget_seconds * 0.98
    fg = (lambda hh: _fun_grad_flat_top(hh, 0.95, 20.0))
    ht = _lbfgs_block(best, np.arange(best.size), 400,
                      final_deadline - 1.0, fg)
    offer(ht, 'final floattop')
    fg = (lambda hh: _fun_grad_tie(hh, 1e-9))
    ht = _lbfgs_block(best, np.arange(best.size), 400,
                      final_deadline - 0.3, fg)
    offer(ht, 'final tie')

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and altR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _refine(h, deadline, rounds=6, beta_start=12.0, beta_end=1500.0):
    """Anneal beta on full vector then peak window, tracking best R."""
    best = h.copy()
    bestR = R_of(best)
    N = best.size
    full = np.arange(N)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        frac = k / max(1, rounds - 1)
        beta = beta_start * (beta_end / beta_start) ** frac
        tlim = min(deadline - 0.5, time.process_time() + 4.0)
        h2 = _lbfgs(best, full, 120, tlim, beta)
        r2 = R_of(h2)
        if r2 > bestR + 1e-15:
            best, bestR = h2, r2
        # window refine
        if time.process_time() < deadline - 1.0:
            win = _peak_window(best, pad_frac=0.08, extra=128)
            tlim = min(deadline - 0.5, time.process_time() + 3.0)
            h3 = _lbfgs(best, win, 200, tlim, beta * 1.5)
            r3 = R_of(h3)
            if r3 > bestR + 1e-15:
                best, bestR = h3, r3
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # Multi-stage beta annealing from current best
    cur = best.copy()
    curR = bestR
    betas = [10.0, 40.0, 160.0, 600.0, 2400.0]
    for beta in betas:
        if time.process_time() >= deadline - 1.5:
            break
        tlim = min(deadline - 0.5, time.process_time() + 5.0)
        h2 = _lbfgs(cur, np.arange(N), 200, tlim, beta)
        r2 = R_of(h2)
        if r2 > curR + 1e-15:
            cur, curR = h2, r2
        if r2 > bestR + 1e-15:
            best, bestR = h2, r2
        print("  beta=%.0f R=%.12f" % (beta, r2))

    # Repeated window refinement with increasing beta, tracking best
    alt_best = cur.copy()
    altR = curR
    while time.process_time() < deadline - 1.5:
        win = _peak_window(best, pad_frac=0.05, extra=96)
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        beta = 400.0 * (1.0 + (time.process_time() - t0) / max(1.0, budget_seconds))
        h2 = _lbfgs(best, win, 200, tlim, beta)
        r2 = R_of(h2)
        if r2 > altR:
            alt_best, altR = h2, r2
        if r2 > bestR + 1e-15:
            best, bestR = h2, r2
        # full polish occasionally
        if time.process_time() < deadline - 2.5:
            tlim = min(deadline - 0.5, time.process_time() + 2.5)
            h3 = _lbfgs(best, np.arange(N), 120, tlim, beta * 2.0)
            r3 = R_of(h3)
            if r3 > altR:
                alt_best, altR = h3, r3
            if r3 > bestR + 1e-15:
                best, bestR = h3, r3

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14 and altR > 0:
        result["alternative"] = alt_best
    return result

