    taus = [0.9995, 0.999, 0.997, 0.99, 0.98]
    kappas = [1e-4, 3e-4, 1e-3, 3e-3, 1e-2]

    # ---- Full-resolution flat-top penalty ladder ----
    for tau in taus:
