    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.arange(h.size)
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + min(budget_seconds * 0.92, 55.0)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        best = _rescale(np.ones(8192))
        bestR = R_of(best)

    print("start R=%.9f N=%d" % (bestR, best.size))

    # Step 1: full-resolution exact tie polish of start, capped at 8 s.
    if time.process_time() < deadline - 2.0:
        lim = min(deadline - 1.0, time.process_time() + 8.0)
        cand = _lbfgs_block(best, 400, lim)
        rc = R_of(cand)
        if rc > bestR:
            best, bestR = cand, rc
        print("full polish R=%.9f" % bestR)

    # Step 2: multi-resolution ladder Q=4,2,1, repeated.
    def ladder_round():
        nonlocal best, bestR
        for Q in (4, 2, 1):
            if time.process_time() >= deadline - 2.0:
                return
            qh = _coarsen(best, Q)
            if qh is None or qh.sum() <= 0:
                continue
            qh = _rescale(qh)
            lim = min(deadline - 1.5, time.process_time() + 3.0)
            qc = _lbfgs_block(qh, 300, lim)
            rq = R_of(qc)
            if rq > bestR:
                # prolongate and full-res polish
                hf = _prolongate(qc, Q)
                lim2 = min(deadline - 1.0, time.process_time() + 3.0)
                hf = _lbfgs_block(hf, 300, lim2)
                rf = R_of(hf)
                if rf > bestR:
                    best, bestR = hf, rf
                elif rq > bestR:
                    best, bestR = _prolongate(qc, Q), rq
                print("Q=%d R=%.9f" % (Q, bestR))

    # Run ladder rounds until deadline.
    rounds = 0
    while time.process_time() < deadline - 3.0 and rounds < 6:
        before = bestR
        ladder_round()
        rounds += 1
        if bestR <= before + 1e-12 and rounds >= 2:
            # no progress; one more full polish then stop
            if time.process_time() < deadline - 2.0:
                lim = min(deadline - 1.0, time.process_time() + 3.0)
                cand = _lbfgs_block(best, 300, lim)
                rc = R_of(cand)
                if rc > bestR:
                    best, bestR = cand, rc
            break

    print("final R=%.12f N=%d" % (bestR, best.size))

    result = {"best": best}
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
