def _lbfgs_block(h0, free, maxiter, deadline, tie=True, flat_top=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat_top is not None:
        tau, kappa = flat_top
        fg = (lambda hh: _fun_grad_flat_top(hh, tau, kappa))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.3, extra=512):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, deadline):
    """Flat-top L-BFGS then exact-tie polish on peak window."""
    r0 = R_of(h)
    kappas = [0.5, 0.2, 0.05, 0.0]
    cur = h
    curR = r0
    for kap in kappas:
        if time.process_time() >= deadline - 0.5:
            break
        sub = min(deadline - 0.4, time.process_time() + 3.0)
        if kap > 0:
            cand = _lbfgs_all_pos(cur, 300, sub, flat_top=(0.999, kap))
        else:
            cand = _lbfgs_all_pos(cur, 300, sub, tie=True)
        r = R_of(cand)
        if r > curR + 1e-15:
            cur, curR = cand, r
    if time.process_time() < deadline - 0.5:
        win = _peak_window(cur)
        sub = min(deadline - 0.4, time.process_time() + 3.0)
        cand = _lbfgs_block(cur, win, 300, sub, flat_top=(0.999, 0.05))
        r = R_of(cand)
        if r > curR:
            cur, curR = cand, r
        sub = min(deadline - 0.4, time.process_time() + 3.0)
        cand = _lbfgs_block(cur, win, 300, sub, tie=True)
        r = R_of(cand)
        if r > curR:
            cur, curR = cand, r
    return cur


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n or m < 4:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f N=%d" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: collapse 2-fold duplication if present
    h = best.copy()
    if h.size % 2 == 0:
        a = h[0::2]; b = h[1::2]
        if a.size == b.size and np.max(np.abs(a - b)) < 1e-12:
            hc = 0.5 * (a + b)
            rc = R_of(hc)
            print("A collapse N=%d -> %d R=%.9f" % (h.size, hc.size, rc))
            if abs(rc - bestR) < 1e-6:
                h = hc
                best = hc.copy()
                bestR = rc
                origin = 'A_collapse'

    # Phase C0: quick flat-top polish of start
    ht = _polish(best, min(deadline - 1.0, time.process_time() + 6.0))
    r = R_of(ht)
    print("C0 polish R=%.9f (was %.9f)" % (r, bestR))
    if r > bestR + 1e-15:
        best, bestR = ht, r
        origin = origin + '+C0'

    # Phase D: multi-scale coarsen/prolongate moves
    phaseB_deadline = t0 + budget_seconds * 0.80
    qs = [2, 3, 4, 5, 6, 8]

    while time.process_time() < phaseB_deadline - 2.0:
        improved = False
        for q in qs:
            if time.process_time() >= phaseB_deadline - 2.0:
                break
            ch = _coarsen(best, q)
            if ch is None:
                continue
            if ch.sum() <= 0:
                continue
            sub = min(phaseB_deadline - 1.0, time.process_time() + 2.0)
            ch2 = _lbfgs_all_pos(ch, 200, sub, flat_top=(0.999, 0.1))
            ch2 = _lbfgs_all_pos(ch2, 200, sub, tie=True)
            rc = R_of(ch2)
            ph = _prolongate(ch2, q)
            sub = min(phaseB_deadline - 1.0, time.process_time() + 2.0)
            ph = _polish(ph, sub)
            rp = R_of(ph)
            print("D q=%d coarsen R=%.9f prolong R=%.9f (best %.9f)" %
                  (q, rc, rp, bestR))
            if rp > bestR + 1e-14:
                best, bestR = ph, rp
                origin = 'D_q%d' % q
                improved = True
                print("  NEW BEST R=%.9f" % bestR)
            elif rp > alt_bestR:
                alt_best, alt_bestR = ph.copy(), rp
        if not improved:
            break

    # Phase C: final full-array exact tie polishes
    while time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 500, deadline - 0.4, tie=True)
        r = R_of(ht)
        print("C tie R=%.9f" % r)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            origin = origin + '+C'
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            break

    # Phase E: last short flat-top on peak window
    if time.process_time() < deadline - 0.5:
        win = _peak_window(best)
        ht = _lbfgs_block(best, win, 400, deadline - 0.3, flat_top=(0.999, 0.02))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            origin = origin + '+E'
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        print("E flat R=%.9f" % r)

    print("final R=%.9f origin=%s N=%d (start %.9f)" %
          (bestR, origin, best.size, start_bestR))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag="", pads=None):
    if pads is None:
        pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _zero_frac(h):
    return float(np.mean(h == 0))


def _resample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xp = (np.arange(n) + 0.5) / n
    x = (np.arange(N) + 0.5) / N
    return np.interp(x, xp, h)


def _block_average(h, q):
    # coarse-grain by summing q adjacent steps; keeps autocorrelation comparable
    n = h.size
    m = n // q
    if m < 8:
        return None
    return h[:m * q].reshape(m, q).sum(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    rng = np.random.default_rng(20240517)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: short baseline cycle to squeeze the start
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            start_best.copy(), best.copy(), bestR, deadline, 'base',
            pads=[0.30, 0.15, 0.08])
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B (NEW): multi-resolution ladder. Coarsen the current best by
    # block-averaging, optimise at the coarse level (cheaper per iter, can
    # escape the fine-grid local optimum), then prolongate back and polish.
    if time.process_time() < deadline - 2.0 and best.size >= 64:
        for q in [8, 4, 2]:
            if time.process_time() >= deadline - 2.0:
                break
            hc = _block_average(best, q)
            if hc is None:
                continue
            hc = _rescale(hc)
            rc = R_of(hc)
            for beta in [1e6, 1e7]:
                if time.process_time() >= deadline - 2.0:
                    break
                hc = _lbfgs_all_pos(hc, 250, deadline - 2.0, beta=beta)
            rc = R_of(hc)
            # prolongate back to best.size
            hp = _rescale(np.repeat(hc, q))
            if hp.size != best.size:
                hp = _resample(hc, best.size)
            hp = _rescale(hp)
            rp = R_of(hp)
            for beta in [1e6, 1e7]:
                if time.process_time() >= deadline - 2.0:
                    break
                hp = _lbfgs_all_pos(hp, 200, deadline - 2.0, beta=beta)
            rp = R_of(hp)
            print("multigrid q=%d coarse R=%.9f prolong R=%.9f" %
                  (q, rc, rp))
            if rp > bestR + 1e-14 and hp.size == best.size:
                best, bestR, origin = hp, rp, "mg%d" % q
                print("  NEW BEST from multigrid q=%d" % q)
            elif hp.size == best.size and rp > alt_bestR:
                alt_best, alt_bestR = hp, rp

    # Phase C: peak-window cycle from best
    if time.process_time() < deadline - 1.0:
        w, b, br, org = _run_cycle(
            best.copy(), best.copy(), bestR, deadline, 'pk',
            pads=[0.30, 0.20, 0.15, 0.10, 0.08])
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
            print("pk-cycle: R=%.9f NEW BEST zero_frac=%.3f" %
                  (bestR, _zero_frac(best)))
        else:
            if br > alt_bestR and b.size == best.size:
                alt_best, alt_bestR = b, br

    # Phase D: random perturb restarts
    if time.process_time() < deadline - 1.0:
        tries = 0
        while time.process_time() < deadline - 1.0 and tries < 8:
            tries += 1
            amp = 0.005 + 0.03 * rng.random()
            hp = _random_perturb(best, rng, amp)
            for beta in [1e6, 1e7]:
                if time.process_time() >= deadline - 1.0:
                    break
                hp = _lbfgs_all_pos(hp, 200, deadline - 1.0, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                best, bestR, origin = hp, rp, "perturb%d" % tries
                print("perturb%d amp=%.3f R=%.9f NEW BEST" % (tries, amp, rp))
            elif hp.size == best.size and rp > alt_bestR:
                alt_best, alt_bestR = hp, rp

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _softmax_max(Lf, beta):
    # smooth max via logsumexp; returns value and weights w.r.t. Lf
    m = Lf.max()
    z = beta * (Lf - m)
    e = np.exp(z)
    Z = e.sum()
    val = m + np.log(Z) / beta
    w = e / Z
    return val, w


def _fun_grad_soft(h, beta, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    smax, w = _softmax_max(Lf, beta)
    gLf = -dq / num
    gLf += w / smax
    # flat-top kappa penalty: push down knots within kappa of max
    thr = mx * (1.0 - kappa)
    idx = np.flatnonzero(Lf >= thr)
    if idx.size > 0:
        # penalty = sum (Lf - thr)^2 for near-max knots
        diff = Lf[idx] - thr
        pen = np.sum(diff * diff)
        gLf[idx] += 2.0 * diff
        val = -np.log(num) + 2.0 * np.log(s) + np.log(smax) + pen
    else:
        val = -np.log(num) + 2.0 * np.log(s) + np.log(smax)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, maxiter, deadline, fun_grad=_fun_grad_tie):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.arange(h.size)
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def _upsample2(h):
    n = h.size
    x = np.arange(n)
    x2 = np.linspace(0, n - 1, 2 * n)
    return _rescale(np.interp(x2, x, h))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + min(budget_seconds * 0.93, 56.0)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        best = _rescale(np.ones(8192))
        bestR = R_of(best)

    print("start R=%.9f N=%d" % (bestR, best.size))

    # Phase 0: exact tie polish of start, capped at 6 s.
    if time.process_time() < deadline - 2.0:
        lim = min(deadline - 1.0, time.process_time() + 6.0)
        cand = _lbfgs_block(best, 300, lim)
        rc = R_of(cand)
        if rc > bestR:
            best, bestR = cand, rc
        print("polish R=%.9f" % bestR)

    # Alternate sharpening (A) and resolution escalation (B).
    betas = [1e2, 1e3, 1e4, 1e5]
    kappa = 0.001
    maxN = 32768

    def phase_A():
        nonlocal best, bestR
        for beta in betas:
            if time.process_time() >= deadline - 2.0:
                return False
            fg = (lambda hh, b=beta: _fun_grad_soft(hh, b, kappa))
            lim = min(deadline - 1.5, time.process_time() + 2.5)
            cand = _lbfgs_block(best, 200, lim, fun_grad=fg)
            rc = R_of(cand)
            if rc > bestR + 1e-12:
                best, bestR = cand, rc
                print("A beta=%.0e R=%.9f" % (beta, bestR))
        return True

    def phase_B():
        nonlocal best, bestR
        if best.size * 2 > maxN:
            return False
        if time.process_time() >= deadline - 3.0:
            return False
        up = _upsample2(best)
        lim = min(deadline - 2.0, time.process_time() + 4.0)
        cand = _lbfgs_block(up, 300, lim)
        rc = R_of(cand)
        if rc > bestR + 1e-12:
            best, bestR = cand, rc
            print("B up N=%d R=%.9f" % (best.size, bestR))
        else:
            # keep upsampled as candidate only if better; else stay
            if rc > bestR:
                best, bestR = cand, rc
        # Q=2 coarsen/prolongate round
        if time.process_time() < deadline - 3.0:
            qh = _coarsen(best, 2)
            if qh is not None and qh.sum() > 0:
                qh = _rescale(qh)
                lim2 = min(deadline - 2.0, time.process_time() + 3.0)
                qc = _lbfgs_block(qh, 300, lim2)
                hf = _prolongate(qc, 2)
                lim3 = min(deadline - 1.5, time.process_time() + 3.0)
                hf = _lbfgs_block(hf, 300, lim3)
                rf = R_of(hf)
                if rf > bestR + 1e-12:
                    best, bestR = hf, rf
                    print("B Q2 R=%.9f" % bestR)
        return True

    rounds = 0
    while time.process_time() < deadline - 3.0 and rounds < 8:
        before = bestR
        phase_A()
        if time.process_time() >= deadline - 3.0:
            break
        phase_B()
        rounds += 1
        if bestR <= before + 1e-9 and rounds >= 3:
            # no progress; final polish then stop
            if time.process_time() < deadline - 2.0:
                lim = min(deadline - 1.0, time.process_time() + 3.0)
                cand = _lbfgs_block(best, 300, lim)
                rc = R_of(cand)
                if rc > bestR:
                    best, bestR = cand, rc
            break

    print("final R=%.12f N=%d" % (bestR, best.size))

    result = {"best": best}
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample2(h):
    n = h.size
    out = np.empty(2 * n - 1)
    out[0::2] = h
    out[1::2] = 0.5 * (h[:-1] + h[1:])
    return out


def _lbfgs_masked(h0, mask, maxiter, deadline, beta=0.0):
    return _lbfgs_block(h0, np.flatnonzero(mask), maxiter, deadline, beta=beta)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _record(cand):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        cand = _rescale(np.clip(cand, 0, None))
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand.copy(), r
            origin = 'up'
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Strategy A: dense 2x refinement of the whole construction ----
    # The start is saturated on its grid. Refining to 2x and re-optimising the
    # full array (all-positive L-BFGS with smoothing) searches a strictly
    # larger function space, so it can only help.
    if time.process_time() < deadline - 3.0:
        N0 = best.size
        h2 = _upsample2(best)
        h2 = _rescale(np.clip(h2, 0, None))
        r_init = R_of(h2)
        print("upsample init R=%.9f (start %.9f, N %d->%d)" %
              (r_init, bestR, N0, h2.size))
        slice_dl = min(deadline - 2.0,
                       time.process_time() + 0.55 * budget_seconds)
        work = h2
        # beta schedule: high beta first to sharpen max, then 0 to polish num
        for beta in [1e5, 1e6, 1e7, 1e8, 0.0]:
            if time.process_time() >= slice_dl - 0.5:
                break
            work = _lbfgs_all_pos(work, 400, slice_dl - 0.3, beta=beta)
            r = R_of(work)
            if r > bestR + 1e-13:
                best, bestR, origin = work.copy(), r, 'up2x_b%g' % beta
                print("  UPSAMPLE NEW BEST R=%.9f (beta %g)" % (bestR, beta))
            elif r > alt_bestR and work.size == best.size:
                alt_best, alt_bestR = work.copy(), r
        # peak-window polish on the refined array
        for pad in [0.15, 0.08, 0.05]:
            if time.process_time() >= slice_dl - 0.5:
                break
            win = _peak_window(work, pad_frac=pad, extra=128)
            work = _lbfgs_block(work, win, 400, slice_dl, beta=1e7)
            r = R_of(work)
            if r > bestR + 1e-13:
                best, bestR, origin = work.copy(), r, 'up2x_pk'
                print("  UPSAMPLE PEAK NEW BEST R=%.9f" % bestR)
            elif r > alt_bestR and work.size == best.size:
                alt_best, alt_bestR = work.copy(), r

    # ---- Strategy B: half-res quotient search, then lift back ----
    if best.size % 2 == 0 and best.size >= 8 and \
            time.process_time() < deadline - 3.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_dl = min(deadline - 6.0,
                      time.process_time() + 0.20 * budget_seconds)
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_dl - 1.0:
            for beta in [1e5, 1e6, 1e7]:
                if time.process_time() >= half_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(work_c, 300, half_dl - 0.3, beta=beta)
                r = R_of(ht)
                if r > best_cR + 1e-14:
                    work_c, best_c, best_cR = ht, ht.copy(), r
            for pad in [0.20, 0.10]:
                if time.process_time() >= half_dl - 0.5:
                    break
                win = _peak_window(work_c, pad_frac=pad, extra=128)
                ht = _lbfgs_block(work_c, win, 400, half_dl - 0.3, beta=1e7)
                r = R_of(ht)
                if r > best_cR + 1e-14:
                    work_c, best_c, best_cR = ht, ht.copy(), r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR and ht.size == best.size:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Strategy C: perturb-polish chain, all remaining time ----
    rng = np.random.RandomState(987654321)
    chain_end = deadline - 2.5
    attempt = 0
    accepted_total = 0

    while time.process_time() < chain_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 2.5, chain_end)
        if slice_dl <= now + 0.5:
            break
        attempt += 1
        try:
            choice = rng.randint(3)
            cand = best.copy()
            Ncur = cand.size
            if choice == 0:
                # block perturbation on active region
                Bopts = [max(8, Ncur // 200), max(8, Ncur // 60),
                         max(8, Ncur // 20)]
                B = Bopts[rng.randint(len(Bopts))]
                sigma = [0.004, 0.015, 0.05][rng.randint(3)]
                eps = [3e-3, 1e-2][rng.randint(2)]
                thr = [1e-4, 1e-3, 3e-3][rng.randint(3)]
                nz = np.flatnonzero(cand > 0)
                if nz.size < 4:
                    continue
                mean_act = cand[nz].mean()
                if Ncur <= B:
                    s0, Bc = 0, Ncur
                else:
                    s0 = rng.randint(0, Ncur - B + 1)
                    Bc = B
                blk = cand[s0:s0 + Bc] * np.exp(sigma * rng.randn(Bc))
                z = (blk == 0)
                if np.any(z):
                    blk[z] = eps * mean_act
                cand[s0:s0 + Bc] = blk
                cand = _rescale(np.clip(cand, 0, None))
                win = _peak_window(cand, pad_frac=0.05, extra=128)
                cand = _lbfgs_block(cand, win, 250, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 200, slice_dl, beta=0.0)
                mx = cand.max()
                if mx > 0:
                    cand[cand < thr * mx] = 0.0
                cand = _rescale(np.clip(cand, 0, None))
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 150, slice_dl, beta=1e7)
            elif choice == 1:
                # upsample-then-optimise (fine detail discovery)
                h2 = _upsample2(cand)
                h2 = _rescale(np.clip(h2, 0, None))
                for beta in [1e6, 1e7, 0.0]:
                    if time.process_time() >= slice_dl - 0.4:
                        break
                    h2 = _lbfgs_all_pos(h2, 250, slice_dl - 0.3, beta=beta)
                cand = h2
            else:
                # peak-window polish at multiple scales
                for pad in [0.10, 0.05, 0.03]:
                    if time.process_time() >= slice_dl - 0.5:
                        break
                    win = _peak_window(cand, pad_frac=pad, extra=128)
                    cand = _lbfgs_block(cand, win, 300, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    cand = _lbfgs_all_pos(cand, 200, slice_dl, beta=0.0)

            r2 = R_of(cand)
            if r2 > bestR + 1e-13:
                best, bestR = cand.copy(), r2
                origin = 'chain%d' % attempt
                accepted_total += 1
                print("chain acc choice=%d R=%.9f" % (choice, bestR))
            elif r2 > alt_bestR:
                alt_best, alt_bestR = cand.copy(), r2
        except Exception as e:
            print("chain attempt %d exception %s" % (attempt, e))
            continue

    print("chain attempts=%d accepted=%d bestR=%.9f" %
          (attempt, accepted_total, bestR))

    # ---- Final polish on the winning construction ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR and ht2.size == best.size:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR and ht.size == best.size:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and \
            alt_bestR < bestR and alt_bestR > -1:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.15, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(h, newN):
    n = h.size
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, newN)
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: one uninterrupted full-array exact tie-averaged L-BFGS-B ----
    p1_deadline = min(t0 + 45.0, deadline - 6.0)
    if time.process_time() < p1_deadline - 1.0:
        ht = _lbfgs_all_pos(best, 4000, p1_deadline, beta=0.0)
        r = R_of(ht)
        dR = r - bestR
        print("phase1 exact full R=%.9f dR=%.3e" % (r, dR))
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'exact-full'
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: non-commensurate resample to 1.5x, exact polish ----
    if time.process_time() < deadline - 4.0:
        preR = bestR
        newN = int(np.floor(1.5 * best.size))
        hr = _resample(best, newN)
        hr = _rescale(hr)
        r0 = R_of(hr)
        print("resample 1.5x N=%d R=%.9f (pre %.9f)" % (newN, r0, preR))
        p2_deadline = min(deadline - 2.0, time.process_time() + 0.30 * budget_seconds)
        ht = _lbfgs_all_pos(hr, 1500, p2_deadline, beta=0.0)
        r = R_of(ht)
        print("phase2 resample polish R=%.9f" % r)
        # accept only if strictly exceeds pre-resample best
        if r > preR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'resample1.5x'
            print("resample NEW BEST R=%.9f" % bestR)
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            # also try a couple more resample factors quickly
            for fac in [1.37, 1.63, 1.21]:
                if time.process_time() >= deadline - 3.0:
                    break
                newN2 = int(np.floor(fac * best.size))
                hr2 = _rescale(_resample(best, newN2))
                r0b = R_of(hr2)
                p2b = min(deadline - 2.0,
                          time.process_time() + 0.12 * budget_seconds)
                ht2 = _lbfgs_all_pos(hr2, 800, p2b, beta=0.0)
                r2 = R_of(ht2)
                print("resample %.2fx N=%d R=%.9f" % (fac, newN2, r2))
                if r2 > bestR + 1e-14:
                    best, bestR, origin = ht2.copy(), r2, 'resample%.2fx' % fac
                    print("resample NEW BEST R=%.9f" % bestR)
                elif r2 > alt_bestR:
                    alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 3: up to three peak-window polish rounds on top 5% knots ----
    for it in range(3):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, tol=0.95, pad_frac=0.15, extra=128)
        slice_deadline = min(deadline - 0.5,
                             time.process_time() + 0.06 * budget_seconds)
        ht = _lbfgs_block(best, win, 600, slice_deadline, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+pk%d' % it
            print("peak polish %d NEW BEST R=%.9f" % (it, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        # gentle full polish after each peak round
        if time.process_time() < deadline - 1.0:
            slice_deadline2 = min(deadline - 0.5,
                                  time.process_time() + 0.05 * budget_seconds)
            ht2 = _lbfgs_all_pos(best, 400, slice_deadline2, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+all'
                print("full polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    elif alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, beta=1e7):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _refine_at_N(cur, curR, deadline, betas, tag=""):
    while time.process_time() < deadline - 3.0:
        hb = _lbfgs_log(cur, 250, deadline)
        rb = R_of(hb)
        if rb > curR + 1e-13:
            cur, curR = hb, rb
            print("    %slbfgs R=%.7f (N=%d)" % (tag, curR, cur.size))
        for beta in betas:
            if time.process_time() >= deadline - 4.0:
                break
            hb = _lbfgs_log(cur, 120, deadline, beta=beta)
            hs = _lbfgs_log(hb, 5, deadline)
            rs = R_of(hs)
            hp = _peak_ladder(hs, min(deadline, time.process_time() + 6.0))
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 1e-13:
                cur, curR = cand, rc
                print("    %sbeta=%.0e R=%.7f (N=%d)" % (tag, beta, curR, cur.size))
        if time.process_time() < deadline - 3.0:
            hp = _peak_ladder(cur, min(deadline, time.process_time() + 5.0),
                              pads=(0.03, 0.02))
            rp = R_of(hp)
            if rp > curR + 1e-13:
                cur, curR = hp, rp
                print("    %speak R=%.7f (N=%d)" % (tag, curR, cur.size))
    return cur, curR


def _smooth_extend(h, factor):
    n = h.size
    m = int(round(n * factor))
    x = np.linspace(0.0, 1.0, n)
    xm = np.linspace(0.0, 1.0, m)
    return np.interp(xm, x, h)


def _upsample_spline(h, factor):
    """Upsample via cubic-ish (Catmull-Rom-ish) using np.interp on padded signal."""
    n = h.size
    m = int(round(n * factor))
    x = np.arange(n, dtype=float)
    xm = np.linspace(0.0, n - 1.0, m)
    # simple linear + mild smoothing
    out = np.interp(xm, x, h)
    # light smoothing to reduce staircase
    if m > 4:
        k = np.array([0.25, 0.5, 0.25])
        out = np.convolve(out, k, mode='same')
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(987654321)

    best, bestR = None, 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    betas = (1e4, 1e5, 1e6, 1e7, 1e8)

    # Phase 1: refine at current N
    cur, curR = best.copy(), bestR
    cur, curR = _refine_at_N(cur, curR, t0 + budget_seconds * 0.40, betas, tag="N0 ")
    if curR > bestR + 1e-13:
        best, bestR = cur.copy(), curR

    # Phase 2: try several upsampling variants; keep the best
    candidates = []
    if time.process_time() < deadline - 8.0:
        for fac, tag in ((2.0, "rep2"), (1.5, "lin1.5"), (1.75, "spl1.75")):
            if time.process_time() >= deadline - 8.0:
                break
            if tag == "rep2":
                hU = _rescale(np.repeat(best, 2))
            elif tag == "lin1.5":
                hU = _rescale(_smooth_extend(best, fac))
            else:
                hU = _rescale(_upsample_spline(best, fac))
            rU = R_of(hU)
            curU, curUR = _refine_at_N(hU, rU,
                                       min(deadline, time.process_time() + budget_seconds * 0.15),
                                       betas, tag=tag + " ")
            candidates.append((curUR, curU, tag))
            if curUR > bestR + 1e-12:
                best, bestR = curU.copy(), curUR
                print("  -> %s won: R=%.7f" % (tag, bestR))

    # Phase 3: aggressive peak-focused polish with varied beta
    if time.process_time() < deadline - 2.0:
        for beta in (1e5, 1e6, 1e7, 1e8):
            if time.process_time() >= deadline - 2.0:
                break
            hp = _peak_ladder(best, min(deadline, time.process_time() + 4.0),
                              pads=(0.05, 0.03, 0.02, 0.015), iters=300, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  peak b=%.0e R=%.7f" % (beta, bestR))

    # Phase 4: final full lbfgs
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

