    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = max(1, int(round((1.0 - q) * n)))
    if k >= n:
        k = n - 1
    idx = np.argpartition(-Lf, k - 1)[:k]
    Mq = Lf[idx].mean()
    if Mq <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[idx] += 1.0 / (Mq * k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Mq)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, cvar_q=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if cvar_q is not None:
        fg = (lambda hh: _fun_grad_cvar(hh, cvar_q))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _nearmax_frac_tight(h, frac=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _deficit_free(h, frac=0.15):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(h.size)
    gLf = (M - 2.0 * Lf) / M
    s = np.abs(_backprop(gLf, h))
    N = h.size
    k = max(1, int(frac * N))
    if k >= N:
        return np.arange(N)
    idx = np.argpartition(-s, k - 1)[:k]
    return np.sort(idx)


def _upsample(h, factor):
    """Repeat each entry `factor` times (step-doubling), preserving shape."""
    if factor <= 1:
        return h.copy()
    return np.repeat(h, factor)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase A: half-resolution polish (kept from base) ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.10
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- NEW IDEA: refine at doubled resolution ----
    # Step-doubling can expose more degrees of freedom; polish at 2x resolution.
    # Because R is scale-free, an upsampled-then-polished h can only improve.
    refine_deadline = t0 + budget_seconds * 0.30
    if best.size * 2 <= 1000000 and time.process_time() < refine_deadline - 2.0:
        h2x = _upsample(best, 2)
        h2x = _rescale(h2x)
        r2 = R_of(h2x)
        print("2x upsample R=%.9f (best %.9f)" % (r2, bestR))
        # polish the doubled array
        work2 = h2x.copy()
        work2 = _polish_ladder(work2, refine_deadline,
                               betas=(1e6, 1e7, 1e8), iters=250)
        work2 = _peak_ladder(work2, refine_deadline,
                             pads=(0.15, 0.10, 0.06), iters=300)
        offer(work2, 'refine2x')
        # also try high-beta sharpening directly
        if time.process_time() < refine_deadline - 2.0:
            work3 = _lbfgs_all_pos(work2, 300, refine_deadline, beta=1e8)
            offer(work3, 'refine2x_sharp')

    # ---- Phase CVaR: top-quantile polish ----
    def _norm1(h):
        s = h.sum()
        if s <= 0:
            return h
        return h / s

    cvar_deadline = t0 + budget_seconds * 0.60
    qs = (0.99, 0.995, 0.999, 0.9999)
    work = _norm1(best.copy())
    for q in qs:
        if time.process_time() >= cvar_deadline - 2.0:
            break
        ht = _lbfgs_all_pos(work, 200, cvar_deadline, cvar_q=q)
        rc = R_of(ht)
        nm = _nearmax_frac_tight(ht, 0.999)
        improved = offer(ht, 'cvar_q%.4f' % q)
        print("cvar q=%.4f R=%.9f (best %.9f) nearmax0.1%%=%.4f improved=%s"
              % (q, rc, bestR, nm, improved))
        if rc > R_of(work):
            work = ht

    # ---- Exact tie-gradient polish ----
    if time.process_time() < cvar_deadline - 1.0:
        ht = _lbfgs_all_pos(best, 100, cvar_deadline, beta=0.0)
        offer(ht, 'tie_polish')

    # ---- Peak-window polishes ----
    if time.process_time() < cvar_deadline - 1.0:
        ht = _peak_ladder(best, cvar_deadline, pads=(0.10, 0.03), iters=300)
        offer(ht, 'peak_cvar')

    # ---- Phase D: deficit-sensitivity rounds ----
    deficit_deadline = deadline - 6.0
    for rnd in range(2):
        if time.process_time() >= deficit_deadline - 2.0:
            break
        free = _deficit_free(best, frac=0.15)
        if free.size == 0:
            break
        ht = _lbfgs_block(best, free, 300, deficit_deadline, beta=1e6)
        ht = _lbfgs_block(ht, free, 300, deficit_deadline, beta=0.0)
        ht = _peak_ladder(ht, deficit_deadline, pads=(0.08, 0.05), iters=250)
        r = R_of(ht)
        improved = offer(ht, 'deficit_%d' % rnd)
        print("deficit round=%d freed=%d R=%.9f (best %.9f) improved=%s"
              % (rnd, free.size, r, bestR, improved))

    # ---- Phase B: high-beta sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=300)
        offer(ht, 'sharp')

    # ---- Final polish on best ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 1e9, 1e10, 0.0), iters=300)
    if R_of(ht) > bestR + 1e-14:
        best, bestR = ht.copy(), R_of(ht)
        print("NEW BEST (finalhi) R=%.9f" % bestR)
    ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=250)
    if R_of(ht2) > bestR + 1e-14:
        best, bestR = ht2.copy(), R_of(ht2)
        print("NEW BEST (finalpeak) R=%.9f" % bestR)

    if start_best is not None and start_bestR > bestR + 1e-14:
        best, bestR = start_best.copy(), start_bestR
        print("reverted to start R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f, nearmax0.1%%=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best), _nearmax_frac_tight(best, 0.999)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _softmax_max(Lf, beta):
    m = Lf.max()
    z = beta * (Lf - m)
    e = np.exp(z)
    Z = e.sum()
    val = m + np.log(Z) / beta
    w = e / Z
    return val, w


def _fun_grad_soft(h, beta, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    smax, w = _softmax_max(Lf, beta)
    gLf = -dq / num
    gLf += w / smax
    thr = mx * (1.0 - kappa)
    idx = np.flatnonzero(Lf >= thr)
    if idx.size > 0:
        diff = Lf[idx] - thr
        pen = np.sum(diff * diff)
        gLf[idx] += 2.0 * diff
        val = -np.log(num) + 2.0 * np.log(s) + np.log(smax) + pen
    else:
        val = -np.log(num) + 2.0 * np.log(s) + np.log(smax)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, maxiter, deadline, fun_grad=_fun_grad_tie):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.arange(h.size)
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def _upsample2(h):
    n = h.size
    x = np.arange(n)
    x2 = np.linspace(0, n - 1, 2 * n)
    return _rescale(np.interp(x2, x, h))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + min(budget_seconds * 0.95, 57.0)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        best = _rescale(np.ones(8192))
        bestR = R_of(best)

    print("start R=%.9f N=%d" % (bestR, best.size))

    # Phase 0: exact tie polish of start.
    if time.process_time() < deadline - 2.0:
        lim = min(deadline - 1.0, time.process_time() + 6.0)
        cand = _lbfgs_block(best, 300, lim)
        rc = R_of(cand)
        if rc > bestR:
            best, bestR = cand, rc
        print("polish R=%.9f" % bestR)

    betas = [1e2, 1e3, 1e4, 1e5]
    kappa = 0.001
    maxN = 131072

    def phase_A():
        nonlocal best, bestR
        if time.process_time() >= deadline - 2.0:
            return False
        lim = min(deadline - 1.0, time.process_time() + 5.0)
        cand = _lbfgs_block(best, 400, lim)
        rc = R_of(cand)
        if rc > bestR + 1e-12:
            best, bestR = cand, rc
            print("A tie R=%.9f" % bestR)
            return True
        return False

    def phase_B():
        nonlocal best, bestR
        gained = False
        for beta in betas:
            if time.process_time() >= deadline - 2.0:
                return gained
            fg = (lambda hh, b=beta: _fun_grad_soft(hh, b, kappa))
            lim = min(deadline - 1.5, time.process_time() + 2.5)
            cand = _lbfgs_block(best, 200, lim, fun_grad=fg)
            rc = R_of(cand)
            if rc > bestR + 1e-12:
                best, bestR = cand, rc
                gained = True
                print("B beta=%.0e R=%.9f" % (beta, bestR))
        return gained

    def phase_C():
        nonlocal best, bestR
        if best.size * 2 > maxN:
            return False
        if time.process_time() >= deadline - 3.0:
            return False
        up = _upsample2(best)
        lim = min(deadline - 2.0, time.process_time() + 5.0)
        cand = _lbfgs_block(up, 300, lim)
        rc = R_of(cand)
        if rc > bestR + 1e-12:
            best, bestR = cand, rc
            print("C up N=%d R=%.9f" % (best.size, bestR))
            return True
        return False

    def phase_D():
        nonlocal best, bestR
        if time.process_time() >= deadline - 3.0:
            return False
        qh = _coarsen(best, 2)
        if qh is None or qh.sum() <= 0:
            return False
        qh = _rescale(qh)
        lim2 = min(deadline - 2.0, time.process_time() + 3.0)
        qc = _lbfgs_block(qh, 300, lim2)
        hf = _prolongate(qc, 2)
        lim3 = min(deadline - 1.5, time.process_time() + 3.0)
        hf = _lbfgs_block(hf, 300, lim3)
        rf = R_of(hf)
        if rf > bestR + 1e-12:
            best, bestR = hf, rf
            print("D Q2 R=%.9f" % bestR)
            return True
        return False

    last_up_time = time.process_time()
    rounds = 0
    while time.process_time() < deadline - 2.0:
        before = bestR
        phase_A()
        if time.process_time() >= deadline - 2.0:
            break
        phase_B()
        if time.process_time() >= deadline - 2.0:
            break
        gained = bestR > before + 1e-12
        now = time.process_time()
        if (gained or now - last_up_time > 12.0) and best.size * 2 <= maxN:
            if phase_C():
                last_up_time = time.process_time()
        if time.process_time() >= deadline - 2.0:
            break
        phase_D()
        rounds += 1
        if bestR <= before + 1e-12 and rounds >= 2:
            # no progress this round; try one more upsample then break
            if best.size * 2 <= maxN and time.process_time() < deadline - 3.0:
                if phase_C():
                    last_up_time = time.process_time()
                    continue
            break

    # Final polish
    if time.process_time() < deadline - 1.0:
        lim = min(deadline - 0.5, time.process_time() + 3.0)
        cand = _lbfgs_block(best, 400, lim)
        rc = R_of(cand)
        if rc > bestR:
            best, bestR = cand, rc

    print("final R=%.12f N=%d" % (bestR, best.size))

    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _short_polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        hs = _lbfgs_log(best, 120, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    if time.process_time() < deadline - 0.5:
        free = _peak_window(best, frac=0.08)
        hs = _lbfgs_block(best, free, 100, min(deadline - 0.3, time.process_time() + 2.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _coarsen(h):
    n = h.size
    if n % 2 == 1:
        h = np.concatenate((h, [0.0]))
        n += 1
    return 0.5 * (h[0::2] + h[1::2])


def _prolongate(hc, n_target):
    mc = hc.size
    cum_c = np.concatenate(([0.0], np.cumsum(hc)))
    xc = np.linspace(0.0, 1.0, mc + 1)
    xn = np.linspace(0.0, 1.0, n_target + 1)
    cum_n = np.interp(xn, xc, cum_c)
    hn = np.diff(cum_n)
    hn = np.clip(hn, 0.0, None)
    return _rescale(hn)


# ---------- Gauss-Newton on near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=50):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-22 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(28):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-15:
            return hn, rn
        alpha *= 0.4
    return h, bestR


def _gn_plateau(h, deadline, label=""):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005, 0.002]
    lams = [1e-8, 1e-6, 1e-4, 1e-2]
    stall = 0
    while time.process_time() < deadline:
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                hn, rn = _gn_try(best, bestR, kappa, lam,
                                 min(deadline, time.process_time() + 3.0))
                if rn > bestR + 1e-15:
                    best, bestR = hn, rn
                    improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0
            if time.process_time() < deadline - 1.0:
                cap = min(deadline, time.process_time() + 2.0)
                hp, rp = _short_polish(best, cap, bestR)
                if rp > bestR:
                    best, bestR = hp, rp
    return best, bestR


# ---------- adaptive refinement: upsample then polish ----------

def _refine(h, deadline, bestR, target_n, label=""):
    if h.size >= target_n or time.process_time() >= deadline - 2.0:
        return h, bestR
    hu = _prolongate(h, target_n)
    ru = R_of(hu)
    cap = min(deadline, time.process_time() + 6.0)
    hp = _lbfgs_log(hu, 200, cap, beta=0.0)
    rp = R_of(hp)
    if rp < ru:
        hp, rp = hu, ru
    if time.process_time() < deadline - 1.5:
        cap = min(deadline, time.process_time() + 4.0)
        hg, rg = _gn_plateau(hp, cap, label=label)
        if rg > rp:
            hp, rp = hg, rg
    if rp > bestR + 1e-15:
        print("  refine -> N=%d R=%.9f" % (hp.size, rp))
        return hp, rp
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n_fine = best.size
    bestH = best.copy()
    bestRH = bestR
    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Phase 1: coarsen and GN on multiple scales (global structure) ----
    scales = []
    hs = bestH
    for _ in range(4):
        hs = _coarsen(hs)
        if hs.size < 64:
            break
        scales.append(hs.copy())

    for hc in reversed(scales):
        if time.process_time() >= deadline - 3.0:
            break
        gn_cap = min(deadline - 2.0, time.process_time() + budget_seconds * 0.08)
        gh, gr = _gn_plateau(hc, gn_cap, label="scale%d" % (hc.size))
        print("GN scale N=%d end: R=%.9f" % (hc.size, gr))
        if gr > R_of(hc) + 1e-14:
            hf = _prolongate(gh, n_fine)
            rf = R_of(hf)
            if time.process_time() < deadline - 3.0:
                cap = min(deadline - 2.0, time.process_time() + 4.0)
                hp, rp = _polish(hf, cap, rf)
                if rp > experiment_bestR + 1e-14:
                    experiment_best, experiment_bestR = hp.copy(), rp
                if rp > bestRH + 1e-14:
                    bestH, bestRH = hp.copy(), rp
                    print("  NEW BEST R=%.9f (scale %d)" % (bestRH, hc.size))

    # ---- Phase 2: upsampling ladder ----
    ladder = [n_fine * 2, n_fine * 4, n_fine * 8, n_fine * 12, n_fine * 16]
    ladder = [n for n in ladder if n <= 1000000]
    for target in ladder:
        if time.process_time() >= deadline - 8.0:
            break
        hu, ru = _refine(bestH, deadline - 4.0, bestRH, target,
                         label="ladder%d" % target)
        if ru > bestRH + 1e-14:
            bestH, bestRH = hu, ru
            if ru > experiment_bestR + 1e-14:
                experiment_best, experiment_bestR = hu.copy(), ru
            print("  ladder NEW BEST N=%d R=%.9f" % (bestH.size, bestRH))

    # ---- Phase 3: full-N GN + alternating L-BFGS/GN passes ----
    if time.process_time() < deadline - 6.0:
        gn_deadline2 = min(deadline - 3.0, time.process_time() + 8.0)
        gn_hf, gn_Rf = _gn_plateau(bestH, gn_deadline2, label="fullN")
        if gn_Rf > bestRH + 1e-14:
            bestH, bestRH = gn_hf, gn_Rf
            print("  NEW BEST (fullN GN) R=%.9f" % bestRH)
        if gn_Rf > experiment_bestR + 1e-14:
            experiment_best, experiment_bestR = gn_hf.copy(), gn_Rf

    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        cap_t = min(loop_end, time.process_time() + 3.5)
        hs = _lbfgs_log(bestH, 200, cap_t, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-14:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
        if time.process_time() < loop_end - 1.5:
            gn_cap = min(loop_end, time.process_time() + 3.0)
            gh, gr = _gn_plateau(bestH, gn_cap, label="loop")
            if gr > bestRH + 1e-14:
                bestH, bestRH = gh, gr
                print("  loop GN iter=%d R=%.9f" % (it, bestRH))
                continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.03 + 0.12 * np.random.random()
            free = _peak_window(bestH, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-14:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))
        if time.process_time() < loop_end - 2.0 and it % 3 == 0:
            beta = 10.0 ** np.random.uniform(2, 5)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(bestH, 150, cap_t, beta=beta)
            rs = R_of(hs)
            if rs > bestRH + 1e-14:
                bestH, bestRH = hs.copy(), rs
                print("  final beta=%.0e iter=%d R=%.9f" % (beta, it, bestRH))

    print("final R=%.9f (best of experiment)" % bestRH)
    mx, m, near = _stats(bestH)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestRH, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestRH > start_bestR + 1e-12:
        alt = experiment_best if experiment_bestR > start_bestR + 1e-12 else start_best
        return {"best": bestH, "alternative": alt}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_flat_top(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    S = Lf >= tau * mx
    nS = int(np.count_nonzero(S))
    V = 0.0
    if nS > 1:
        Ls = Lf[S]
        Lbar = Ls.mean()
        diff = Ls - Lbar
        V = float(np.sum(diff * diff)) / (mx * mx * nS)
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * diff / (mx * mx * nS)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * V
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, flat_top=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat_top is not None:
        tau, kappa = flat_top
        fg = (lambda hh: _fun_grad_flat_top(hh, tau, kappa))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def _project_tangent(v, active):
    if v.size == 0:
        return v
    return v - v.mean()


def _newton_cg(h, deadline, max_outer=20, verbose=True):
    h = _rescale(np.clip(h, 0, None))
    Rcur = R_of(h)
    best = h.copy()
    bestR = Rcur
    neg_curv_total = 0
    accepted_total = 0

    for outer in range(max_outer):
        if time.process_time() >= deadline - 1.0:
            break
        active = np.flatnonzero(h > 1e-12)
        if active.size < 2:
            break
        val, g = _fun_grad_tie(h)
        gA = g[active].copy()
        gA = _project_tangent(gA, active)
        gnorm = float(np.linalg.norm(gA))
        if verbose:
            print("  NCG outer %d: |g_proj|=%.3e R=%.12f" % (outer, gnorm, Rcur))
        if gnorm < 1e-10:
            break

        hA = h[active].copy()
        hnorm = float(np.linalg.norm(hA)) + 1e-30

        def Hv(v):
            v = _project_tangent(v, active)
            vnorm = float(np.linalg.norm(v))
            if vnorm < 1e-30:
                return np.zeros_like(v)
            eps = 1e-6 * hnorm / vnorm
            hp = h.copy()
            hp[active] = np.clip(hA + eps * v, 0.0, None)
            hm = h.copy()
            hm[active] = np.clip(hA - eps * v, 0.0, None)
            _, gp = _fun_grad_tie(hp)
            _, gm = _fun_grad_tie(hm)
            Hv_raw = (gp[active] - gm[active]) / (2.0 * eps)
            return _project_tangent(Hv_raw, active)

        delta = max(1e-3 * hnorm, 1e-6)
        x = np.zeros_like(gA)
        r = -gA.copy()
        p = r.copy()
        rr = float(r @ r)
        tol = min(0.5, np.sqrt(gnorm)) * gnorm
        neg_curv = False
        for it in range(min(200, active.size)):
            if time.process_time() >= deadline - 0.8:
                break
            if np.sqrt(rr) < tol:
                break
            Hp = Hv(p)
            pHp = float(p @ Hp)
            if pHp <= 1e-14 * (float(p @ p) + 1e-30):
                neg_curv = True
                pp = float(p @ p)
                if pp > 1e-30:
                    alpha = np.sqrt(delta * delta / pp)
                    x = x + alpha * p
                break
            alpha = rr / pHp
            xnew = x + alpha * p
            if float(xnew @ xnew) > delta * delta:
                pp = float(p @ p)
                xp = float(x @ p)
                disc = xp * xp + pp * (delta * delta - float(x @ x))
                if disc < 0:
                    disc = 0.0
                tau = (-xp + np.sqrt(disc)) / (pp + 1e-30)
                x = x + tau * p
                break
            x = xnew
            r = r - alpha * Hp
            rr_new = float(r @ r)
            beta = rr_new / (rr + 1e-30)
            p = r + beta * p
            rr = rr_new

        if neg_curv:
            neg_curv_total += 1

        step = x
        step_norm = float(np.linalg.norm(step))
        if step_norm < 1e-14:
            step = -gA / (gnorm + 1e-30) * min(1e-3 * hnorm, delta)
            step_norm = float(np.linalg.norm(step))

        accepted = False
        for ls in range(30):
            if time.process_time() >= deadline - 0.8:
                break
            t = 0.5 ** ls
            htry = h.copy()
            htry[active] = np.clip(hA + t * step, 0.0, None)
            htry = _rescale(htry)
            rtry = R_of(htry)
            if rtry > Rcur + 1e-15:
                h = htry
                Rcur = rtry
                accepted = True
                accepted_total += 1
                if Rcur > bestR:
                    best = h.copy()
                    bestR = Rcur
                break
        if not accepted:
            break

    if verbose:
        print("  NCG done: neg_curv=%d accepted=%d bestR=%.12f" %
              (neg_curv_total, accepted_total, bestR))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    alt_best = None
    altR = -1.0
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Projected Newton-CG on the active support (main new attempt) ----
    if time.process_time() < deadline - 8.0:
        ncg_deadline = min(deadline - 6.0,
                           time.process_time() + budget_seconds * 0.45)
        nh, nR = _newton_cg(best, ncg_deadline, max_outer=20)
        if nR > bestR + 1e-15:
            best, bestR = nh.copy(), nR
        elif nh.size == best.size:
            if nR > altR:
                alt_best, altR = nh.copy(), nR

    for Q in (16, 8, 4, 2, 1):
        if time.process_time() >= deadline - 5.0:
            break
        if best.size % Q != 0:
            continue
        qh = best if Q == 1 else _coarsen(best, Q)
        if qh is None or qh.size < 32:
            continue
        qh = _rescale(qh)
        qR = R_of(qh)
        ladder = [(0.999, 0.02), (0.997, 0.1), (0.99, 0.5),
                  (0.98, 2.0), (0.95, 8.0), (0.90, 30.0)]
        best_qh = qh.copy(); best_qR = qR
        for (tau, kappa) in ladder:
            if time.process_time() >= deadline - 4.0:
                break
            tlim = min(deadline - 3.5, time.process_time() + 1.6)
            cand = _lbfgs_block(best_qh, np.arange(best_qh.size), 120, tlim,
                                flat_top=(tau, kappa))
            r = R_of(cand)
            if r > best_qR:
                best_qh, best_qR = cand.copy(), r
            ph = cand if Q == 1 else _prolongate(cand, Q)
            pr = R_of(ph)
            if pr > bestR + 1e-15:
                best, bestR = ph.copy(), pr
            if pr > altR and ph.size != best.size:
                alt_best, altR = ph.copy(), pr
        if time.process_time() < deadline - 3.0:
            pol = _lbfgs_block(best, np.arange(best.size), 120,
                               min(deadline - 2.5, time.process_time() + 1.8))
            rp = R_of(pol)
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

    while time.process_time() < deadline - 0.8:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.4, time.process_time() + 2.5))
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        else:
            break

    if bestR < startR:
        best = start_best
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size <= 1000000 and alt_best.size != best.size and altR > 0:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, tau=1e-10):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - tau))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tau=1e-10):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh, tau)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.RandomState(98765)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    n = best.size
    print("base R=%.12f (N=%d)" % (bestR, n))

    # Try multi-scale: coarsen start to smaller N, optimize, prolongate back.
    # This escapes the local optimum on a coarser grid where L-BFGS can move
    # more freely, then refine. New line of search distinct from perturb loop.
    def multiscale_attempt(Nc_target, tlimit):
        # build a coarsened version of best
        n_cur = best.size
        q = max(1, n_cur // Nc_target)
        ch = _coarsen(best, q)
        if ch is None or ch.size < 8:
            return None
        ch = _rescale(ch)
        # optimize coarse
        opt_c = _lbfgs_block(ch, np.arange(ch.size), 300,
                             min(tlimit, time.process_time() + 20.0), tau=1e-8)
        # prolongate back to full resolution
        full = _rescale(np.repeat(opt_c, q))
        if full.size != n_cur:
            return None
        # then full polish
        opt_f = _lbfgs_block(full, np.arange(n_cur), 300,
                             min(tlimit, time.process_time() + 20.0), tau=1e-10)
        return opt_f

    # Try a few coarsening scales
    scales = [max(64, n // 8), max(64, n // 4), max(64, n // 2), max(64, (2 * n) // 3)]
    for Nc in scales:
        if time.process_time() >= deadline - 5.0:
            break
        r = multiscale_attempt(Nc, deadline - 4.0)
        if r is not None:
            rr = R_of(r)
            if rr > bestR + 1e-15:
                best, bestR = r, rr
                print("multiscale Nc=%d NEW R=%.12f" % (Nc, bestR))

    # Perturbation loop with tau annealing and mixed strategies
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        cand = best.copy()
        mode = it % 4
        if mode == 0:
            # random block multiplicative
            for _ in range(rng.randint(1, 3)):
                width = max(4, int(n * rng.uniform(0.02, 0.2)))
                lo = rng.randint(0, max(1, n - width))
                amp = rng.uniform(0.02, 0.12)
                cand[lo:lo + width] *= (1.0 + rng.uniform(-amp, amp, width))
        elif mode == 1:
            # additive Gaussian on whole array (small)
            cand += rng.normal(0, 0.01 * cand.mean(), size=n)
        elif mode == 2:
            # coarse perturbation: change coarse blocks
            q = max(2, n // 256)
            m = n // q
            if m * q == n:
                cc = cand.reshape(m, q).mean(axis=1)
                cc *= (1.0 + rng.uniform(-0.05, 0.05, m))
                cand = np.repeat(cc, q)
        else:
            # single-index spike
            k = rng.randint(0, n)
            cand[k] += rng.uniform(0.1, 0.5) * cand.mean()
        cand = np.clip(cand, 0, None)
        if cand.sum() <= 0:
            continue
        cand = _rescale(cand)

        tlim = min(deadline - 1.0, time.process_time() + 6.0)
        tau = 1e-10 if (it % 3 != 0) else 1e-6
        opt = _lbfgs_block(cand, np.arange(n), 150, tlim, tau=tau)
        ro = R_of(opt)
        if ro > bestR + 1e-15:
            best, bestR = opt, ro
            f01, f1, f5 = _fracs(best)
            print("it%d NEW R=%.12f fracs %.4f %.4f %.4f"
                  % (it, bestR, f01, f1, f5))
        elif it % 10 == 0:
            print("it%d R=%.12f best %.12f" % (it, ro, bestR))

    # final polish
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(n), 300,
                           min(deadline - 0.5, time.process_time() + 5.0), tau=1e-12)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol, rp

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    f01, f1, f5 = _fracs(best)
    print("fracs after: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % (f01, f1, f5))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h, N1):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n == N1:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N1) / N1
    tgt = np.linspace(0.0, total, N1 + 1)
    idx = np.searchsorted(c, tgt, side='right') - 1
    idx = np.clip(idx, 0, n - 1)
    out = h[idx].copy()
    s = out.sum()
    if s > 0:
        out *= total / s
    return out


def _restrict(h, N1):
    """Coarsen block-averaging to N1 steps (preserve integral)."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n == N1:
        return h.copy()
    if N1 > n:
        return _prolong(h, N1)
    b = n // N1
    if b * N1 != n:
        return _prolong(h, N1)
    return h.reshape(N1, b).mean(axis=1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.20, 128, 1e8), (0.45, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: multigrid refinement - start coarse, prolong, polish.
    N0 = best.size
    # Coarsen first (cheap moves on a small grid), then prolong upward.
    coarse_levels = []
    Nc = N0
    while Nc > 4096 and len(coarse_levels) < 4:
        Nc //= 2
        if N0 % Nc == 0:
            coarse_levels.append(Nc)
    coarse_levels = coarse_levels[::-1]  # smallest first

    # Coarse phase: restrict to a small grid, optimize hard there.
    work = best
    workR = bestR
    if coarse_levels:
        Nc = coarse_levels[0]
        hc = _restrict(work, Nc)
        rc = R_of(hc)
        print("coarse N=%d R=%.7f" % (Nc, rc))
        # Spend a fixed slice of the budget on the coarse grid.
        coarse_dl = min(deadline - 3.0, time.process_time() +
                        (deadline - time.process_time()) * 0.30)
        if rc >= workR - 1e-6:
            work, workR = hc, rc
        best_c, best_cR = work, workR
        for _ in range(6):
            if time.process_time() >= coarse_dl - 0.5:
                break
            best_c, best_cR = run_cycle(best_c, best_cR, coarse_dl)
        work, workR = best_c, best_cR
        print("coarse-opt N=%d R=%.7f" % (work.size, workR))

    # Refinement ladder back up to N0, then beyond.
    levels = [N0]
    if N0 < 40000:
        levels.append(min(40000, N0 * 3))
    if N0 < 200000 and levels[-1] < 200000:
        levels.append(200000)

    for li, N in enumerate(levels):
        now = time.process_time()
        if now >= deadline - 3.0:
            break
        frac = 0.25 if li == 0 else (0.35 if li == 1 else 0.45)
        rung_dl = min(deadline - 3.0, now + (deadline - 3.0 - now) * frac)
        h = _prolong(work, N) if N != work.size else work.copy()
        hR = R_of(h)
        if hR >= workR - 1e-9:
            work, workR = h, hR
        work, workR = run_cycle(work, workR, rung_dl)
        print("level N=%d R=%.7f" % (work.size, workR))

    if workR > bestR:
        best, bestR = work, workR

    # Phase 2: continuous polishing at final resolution.
    stall = 0
    while time.process_time() < deadline - 1.5 and stall < 4:
        prev = bestR
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        if bestR - prev < 5e-10:
            stall += 1
        else:
            stall = 0

    if time.process_time() < deadline - 0.8:
        win = _peak_window(best, tol=0.95, pad_frac=0.5, extra=1024)
        ht = _lbfgs_block(best, win, maxiter=400, deadline=deadline - 0.6,
                          beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, deadline, frac=0.4, extra=256, maxiter=400, beta=0.0):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.9995 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=40):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    A = np.flatnonzero(L >= (1.0 - kappa) * mx)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx

    def Jd(d):
        if n > 1500:
            cd = fftconvolve(h, d)
        else:
            cd = np.convolve(h, d)
        return 2.0 * cd[A - 1]

    def JT(y):
        yp = np.zeros(2 * n - 1)
        idx = A - 1
        yp[idx] = y
        if n > 1500:
            c = fftconvolve(yp, h[::-1], mode='valid')
        else:
            c = np.correlate(yp, h, mode='valid')
        out = np.zeros(n)
        m = min(n, c.size)
        out[:m] = 2.0 * c[:m]
        return out

    b = JT(r)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Ap = Jd(p)
        Ap = JT(Ap) + lam * p
        pAp = p @ Ap
        if pAp <= 0:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-12 * bn * bn:
            break
        p = res + (rs_new / rs) * p
        rs = rs_new
    return d


def _gn_polish(h, deadline, kappa=0.02, lam_scale=1e-3, rounds=6):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() > deadline - 0.5:
            break
        d = _gn_step(best, kappa, lam_scale, deadline)
        if d is None:
            break
        improved = False
        step = 1.0
        for _ in range(6):
            cand = np.clip(best + step * d, 0.0, None)
            if cand.sum() <= 0:
                step *= 0.5
                continue
            cand = _rescale(cand)
            rr = R_of(cand)
            if rr > bestR + 1e-13:
                best, bestR = cand, rr
                improved = True
                break
            step *= 0.5
        if not improved:
            if lam_scale < 1.0:
                lam_scale *= 10.0
            else:
                break
    return best, bestR


def _prolong(h, factor=2):
    n = h.size
    m = n * factor
    xp = (np.arange(n) + 0.5) / n
    xq = (np.arange(m) + 0.5) / m
    return np.interp(xq, xp, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: local refinement at the starting resolution (fast, mostly converged).
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 400, deadline)
        rr = R_of(h)
        if rr > bestR + 1e-15:
            best, bestR = h, rr
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _peak_window(best, deadline, frac=0.15, extra=16, maxiter=300)
        rr = R_of(h)
        if rr > bestR + 1e-15:
            best, bestR = h, rr
            improved = True
            print("win R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h, rr = _gn_polish(best, deadline, kappa=0.02, lam_scale=1e-3, rounds=3)
        if rr > bestR + 1e-15:
            best, bestR = h, rr
            improved = True
            print("gn R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("local R=%.7f" % bestR)

    # Phase 2: increase resolution substantially and refine there. The main
    # improvement over the original: try larger upsampling factors (up to 4x)
    # with a good interpolation seed, then L-BFGS + GN polish at the finer grid.
    if time.process_time() < deadline - 4.0:
        # choose factor so that we get a finer grid but not too big for the budget
        n0 = best.size
        candidates = [4, 3, 2]
        # pick largest factor giving N <= 400000 (fftconvolve is fine but
        # L-BFGS at large N is slow); leave room.
        factor = 1
        for f in candidates:
            if n0 * f <= 400000 and n0 * f >= 20000:
                factor = f
                break
        if factor > 1 and time.process_time() < deadline - 4.0:
            seed = _rescale(_prolong(best, factor))
            h = _lbfgs_log(seed, 800, deadline)
            rr = R_of(h)
            print("res%d R=%.7f (N=%d)" % (factor, rr, h.size))
            if rr > bestR + 1e-12:
                best, bestR = h, rr
            # heavy polish at the new resolution
            for _ in range(4):
                if time.process_time() >= deadline - 1.5:
                    break
                h2 = _peak_window(best, deadline, frac=0.3, extra=128,
                                  maxiter=500, beta=200.0)
                rr2 = R_of(h2)
                if rr2 > bestR + 1e-15:
                    best, bestR = h2, rr2
                    print("res%d winB R=%.7f" % (factor, bestR))
                h2, rr2 = _gn_polish(best, deadline, kappa=0.02,
                                     lam_scale=1e-3, rounds=4)
                if rr2 > bestR + 1e-15:
                    best, bestR = h2, rr2
                    print("res%d gn R=%.7f" % (factor, bestR))
                h2 = _peak_window(best, deadline, frac=0.1, extra=32,
                                  maxiter=300)
                rr2 = R_of(h2)
                if rr2 > bestR + 1e-15:
                    best, bestR = h2, rr2
                    print("res%d win R=%.7f" % (factor, bestR))
            print("res%d polished R=%.7f" % (factor, bestR))

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

