    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= 0.9995 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, beta=1e7):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _resample(h, Np):
    n = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    t = np.linspace(0.0, n, Np + 1)
    ci = np.interp(t, np.arange(n + 1, dtype=float), c)
    hp = np.diff(ci)
    hp = np.clip(hp, 0.0, None)
    return _rescale(hp)


def _relift(h, factor, rng):
    n = h.size
    Np = n * factor
    out = np.zeros(Np)
    for i in range(n):
        w = rng.dirichlet(np.array([2.0, 2.0] * (factor // 2) + ([2.0] if factor % 2 else [])))
        out[i * factor:(i + 1) * factor] = h[i] * w
    return _rescale(out)


def _coarse_ladder(h, deadline, betas=(1e4, 1e5, 1e6, 1e7)):
    best = h
    bestR = R_of(h)
    for b in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        ht = _lbfgs_log(best, 300, cap, beta=b)
        rt = R_of(ht)
        if rt > bestR + 1e-14:
            best, bestR = ht, rt
        cap2 = min(deadline - 0.3, time.process_time() + 2.0)
        hl = _peak_ladder(best, cap2, pads=(0.10, 0.06, 0.04), iters=200, beta=b)
        rl = R_of(hl)
        if rl > bestR + 1e-14:
            best, bestR = hl, rl
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 3.0)
        hs = _lbfgs_log(best, 300, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            best, bestR = hs, rs
    return best, bestR


def _splat(h, Np):
    """Mass-preserving splat: map each cell to nearest fine cell by center."""
    n = h.size
    centers = (np.arange(n) + 0.5) / n
    fine_centers = (np.arange(Np) + 0.5) / Np
    idx = np.searchsorted(centers, fine_centers)
    idx = np.clip(idx, 0, n - 1)
    # prefer nearest neighbor
    left = np.clip(idx - 1, 0, n - 1)
    d_l = np.abs(fine_centers - centers[left])
    d_r = np.abs(fine_centers - centers[idx])
    use = np.where(d_l < d_r, left, idx)
    out = np.zeros(Np)
    np.add.at(out, use, h[use] * (n / Np))
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 1.5
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.9f (N=%d)" % (start_bestR, start_best.size))
    Nfull = start_best.size

    best = start_best.copy()
    bestR = start_bestR
    alt_best = None
    alt_bestR = -1.0

    # ---- Phase A: full-N beta ladder on start (cheap, keeps precision) ----
    # We do a first, robust full-N polish of the start, so the "best" is at
    # least as good as the start with a strict improvement attempt.
    cap = min(hard - 20.0, time.process_time() + 6.0)
    if cap > time.process_time() + 0.5:
        hp = _lbfgs_log(best, 400, cap, beta=1e6)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("  full polish: %.9f -> %.9f" % (start_bestR, bestR))

    # ---- Phase B: coarse-grid beta ladders --------------------------------
    coarse_solutions = []
    for Np in (42496, 21248, 10624):
        if time.process_time() >= hard - 22.0:
            break
        if Np >= Nfull:
            continue
        hc = _resample(start_best, Np)
        rc0 = R_of(hc)
        cap = min(hard - 16.0, time.process_time() + 5.0)
        hc2, rc2 = _coarse_ladder(hc, cap)
        if rc2 > rc0 + 1e-14:
            coarse_solutions.append((Np, hc2, rc2))
            print("  coarse N=%d: %.9f -> %.9f" % (Np, rc0, rc2))
        else:
            coarse_solutions.append((Np, hc, rc0))
            print("  coarse N=%d: %.9f (no gain)" % (Np, rc0))

    # ---- Phase C: relift best coarse solutions to full N ------------------
    coarse_solutions.sort(key=lambda z: -z[2])
    for (Np, hc, rc) in coarse_solutions[:2]:
        if time.process_time() >= hard - 12.0:
            break
        factor = Nfull // Np
        if factor < 2:
            continue
        for trial in range(3):
            if time.process_time() >= hard - 10.0:
                break
            if trial == 0:
                hr = _splat(hc, Nfull)
            else:
                hr = _relift(hc, factor, rng)
            if hr.size != Nfull:
                if hr.size > Nfull:
                    hr = hr[:Nfull]
                else:
                    hr = np.concatenate([hr, np.zeros(Nfull - hr.size)])
                hr = _rescale(hr)
            rr0 = R_of(hr)
            cap = min(hard - 6.0, time.process_time() + 4.0)
            hr2, rr2 = _coarse_ladder(hr, cap, betas=(1e5, 1e6, 1e7))
            print("  relift N=%d trial%d: %.9f -> %.9f" % (Np, trial, rr0, rr2))
            if rr2 > alt_bestR:
                alt_best, alt_bestR = hr2, rr2
            if rr2 > bestR + 1e-14:
                best, bestR = hr2, rr2

    # ---- Phase D: full-N polish of best -----------------------------------
    sweep = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        cap = min(hard - 2.0, time.process_time() + 3.0)
        hp = _lbfgs_log(best, 400, cap, beta=1e6)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            improved = True
            print("  [sweep%d full] R=%.9f" % (sweep, bestR))
        cap2 = min(hard - 1.5, time.process_time() + 2.5)
        hl = _peak_ladder(best, cap2, beta=1e7)
        rl = R_of(hl)
        if rl > bestR + 1e-14:
            best, bestR = hl, rl
            improved = True
            print("  [sweep%d peak] R=%.9f" % (sweep, bestR))
        if not improved and sweep > 2:
            break

    # Final sharp pass
    if time.process_time() < hard - 0.5:
        cap = hard - 0.3
        hs = _lbfgs_log(best, 300, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        if alt_best is not None and alt_bestR > start_bestR + 1e-13 and alt_bestR < bestR:
            return {"best": best, "alternative": alt_best}
        return {"best": best, "alternative": start_best}
    else:
        if alt_best is not None and alt_bestR > start_bestR + 1e-13:
            return {"best": alt_best, "alternative": start_best}
        return {"best": start_best, "alternative": best if bestR > 0 else start_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_kappa(h, kappa, tau=0.999):
    """Exact objective with flat-top variance penalty.

    val = -log Q + 2 log S + log mx + kappa * Var(L_S)/mx^2
    where S = {j: L_j >= tau*mx}, Var over S.
    """
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    mask = Lf >= tau * mx
    cnt = mask.sum()
    gLf = -dq / num
    gLf[int(np.argmax(Lf))] += 1.0 / mx
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    if kappa > 0 and cnt > 1:
        Ls = Lf[mask]
        mean = Ls.mean()
        var = np.mean((Ls - mean) ** 2)
        # d var / d L_j for j in S: (2/cnt)*(L_j - mean)
        # (mean derivative cancels because sum(L_j-mean)=0)
        dvar = np.zeros_like(Lf)
        dvar[mask] = (2.0 / cnt) * (Ls - mean)
        # term = kappa * var / mx^2
        # d/dx = kappa*(dvar/mx^2 - 2*var/mx^3 * dmx)
        gLf += kappa * dvar / (mx * mx)
        # derivative w.r.t. mx (only through argmax knot):
        gLf[int(np.argmax(Lf))] += -2.0 * kappa * var / (mx ** 3)
        val += kappa * var / (mx * mx)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, kappa=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if kappa > 0:
        fg = (lambda hh: _fun_grad_kappa(hh, kappa))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def _block_sum(h, k):
    """Mass-preserving block-sum: groups of k cells summed."""
    n = h.size
    m = n // k
    if m < 1:
        return h.copy()
    hh = h[:m * k].reshape(m, k)
    return hh.sum(axis=1)


def _block_repeat(h, k, target_n):
    """Repeat each cell k times, then pad/trim to target_n (mass-preserving)."""
    up = np.repeat(h, k)
    if up.size == target_n:
        return up
    if up.size > target_n:
        # trim by merging extra tail into last cell (rare)
        up = up[:target_n].copy()
        return up
    # pad by appending zeros (won't usually happen)
    pad = target_n - up.size
    return np.concatenate([up, np.zeros(pad)])


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(h, pad_frac=frac, extra=8)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_line(h, r, deadline, tag):
    while time.process_time() < deadline - 1.5:
        c = _lbfgs_block(h, np.arange(h.size), maxiter=200, deadline=deadline)
        r2 = R_of(c)
        if r2 > r:
            h, r = c, r2
        c = _lbfgs_block(h, np.arange(h.size), maxiter=200,
                         deadline=deadline, beta=2048.0)
        r2 = R_of(c)
        if r2 > r:
            h, r = c, r2
        h, r = _polish(h, deadline, r,
                       fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=400)
        print("  %s R=%.6f" % (tag, r))
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is None:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        return best

    n0 = start_arr.size
    print("start base R=%.6f N=%d" % (start_r, n0))

    # NEW IDEA (H6): compress to N=125000 via mass-preserving block-sum of
    # groups of 8, then run a flat-top kappa ladder with exact L-BFGS-B,
    # then an exact tie-averaged polish, then prolongate back to N=1e6.
    base = start_arr.copy()
    base_r = start_r

    # compression factor
    k = 8
    if n0 % k != 0:
        # fall back: pick largest divisor <= 8
        for kk in (8, 7, 6, 5, 4, 3, 2, 1):
            if n0 % kk == 0:
                k = kk
                break
    nC = n0 // k
    if nC < 64:
        k = 1
        nC = n0
    print("compress k=%d -> N=%d" % (k, nC))

    c = _rescale(_block_sum(base, k))
    rc = R_of(c)
    print("  compressed R=%.6f" % rc)

    # kappa ladder with exact L-BFGS-B
    kappa_ladder = (1.0, 10.0, 100.0)
    best_c, best_rc = c.copy(), rc
    for kappa in kappa_ladder:
        if time.process_time() >= deadline - 8.0:
            break
        cc = _lbfgs_block(c, np.arange(c.size), maxiter=200,
                          deadline=deadline, kappa=kappa)
        rcc = R_of(cc)
        print("  kappa=%.0f R=%.6f" % (kappa, rcc))
        if rcc > rc:
            c, rc = cc, rcc
        if rcc > best_rc:
            best_c, best_rc = cc.copy(), rcc
        # also try a plain polish after each kappa step
        cc2 = _lbfgs_block(c, np.arange(c.size), maxiter=200,
                           deadline=deadline)
        rcc2 = R_of(cc2)
        if rcc2 > rc:
            c, rc = cc2, rcc2
        if rcc2 > best_rc:
            best_c, best_rc = cc2.copy(), rcc2

    # exact tie-averaged polish at compressed resolution
    if time.process_time() < deadline - 5.0:
        c, rc = _polish(best_c, deadline, best_rc,
                        fracs=(0.5, 0.25, 0.12, 0.06, 0.03), maxiter=400)
        if rc > best_rc:
            best_c, best_rc = c.copy(), rc
        # beta-smoothed exact polish
        if time.process_time() < deadline - 4.0:
            cc = _lbfgs_block(best_c, np.arange(best_c.size), maxiter=300,
                              deadline=deadline, beta=1024.0)
            rcc = R_of(cc)
            if rcc > best_rc:
                best_c, best_rc = cc, rcc
        print("  compressed polish R=%.6f" % best_rc)

    # prolongate back to full resolution
    if time.process_time() < deadline - 3.0:
        up = _rescale(_block_repeat(best_c, k, n0))
        ru = R_of(up)
        print("  prolonged R=%.6f" % ru)
        if ru > base_r:
            base, base_r = up, ru
        # short exact polish at full res
        if time.process_time() < deadline - 2.5:
            cc = _lbfgs_block(base, _peak_window(base, pad_frac=0.3, extra=16),
                              maxiter=200, deadline=deadline)
            rcc = R_of(cc)
            if rcc > base_r:
                base, base_r = cc, rcc
            base, base_r = _polish(base, deadline, base_r,
                                   fracs=(0.30, 0.15, 0.07, 0.03), maxiter=300)
            print("  full polish R=%.6f" % base_r)

    # if time remains, run the base's refine line as a safety net
    if time.process_time() < deadline - 2.0:
        base, base_r = _refine_line(base, base_r, deadline, "final")

    print("best R=%.6f (start %.6f)" % (base_r, start_r))
    base = _rescale(base)

    # report near-max fraction as diagnostic
    Lf = _knots(base)
    mx = Lf.max()
    frac01 = np.mean(Lf >= 0.999 * mx)
    print("  near-max frac (0.1%%): %.4f" % frac01)

    if start_r >= base_r:
        return {"best": _rescale(start_arr), "alternative": base}
    return {"best": base, "alternative": _rescale(start_arr)}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_argmax(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, mode='tie', beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if mode == 'tie':
        fg = _fun_grad_tie
    elif mode == 'beta':
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_argmax

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _detect_staircase(h):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in (1, 2, 3, 4, 5, 8, 16, 32, 64):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-10:
            return c, p
    return None, 1


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(99991)

    # Detect staircase, optimize in compressed coordinate system if present
    c, p = _detect_staircase(best)
    if c is not None and p > 1:
        print("staircase p=%d m=%d" % (p, c.size))
        work = c.copy()
        # alternating: block coordinate polish + full tie polish
        while time.process_time() < deadline - 2.0:
            # full tie polish on repeated
            h_rep = np.repeat(work, p)
            h_rep = _rescale(h_rep)
            win = _peak_window(h_rep, pad_frac=0.06, extra=64)
            ht = _lbfgs_block(h_rep, win, 300,
                              min(deadline - 1.0, time.process_time() + 5.0),
                              mode='tie')
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                c2, p2 = _detect_staircase(best)
                if c2 is not None and p2 == p:
                    work = c2.copy()
            # beta warmup on peak
            if time.process_time() < deadline - 1.0:
                ht = _lbfgs_block(best, win, 200,
                                  min(deadline - 0.5, time.process_time() + 4.0),
                                  mode='beta', beta=1e6)
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r
            f01, f1, f5 = _nearmax_fracs(best)
            print("  R=%.9f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
                  % (bestR, f01, f1, f5))
            if time.process_time() > deadline - 2.0:
                break

    # Main loop: peak-window tie polish + all-pos tie polish + beta polish
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        prevR = bestR
        # peak window tie
        win = _peak_window(best, pad_frac=0.05, extra=64)
        ht = _lbfgs_block(best, win, 400,
                          min(deadline - 1.5, time.process_time() + 4.0),
                          mode='tie')
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        # all positions tie
        if time.process_time() < deadline - 1.5:
            ht = _lbfgs_block(best, np.arange(best.size), 300,
                              min(deadline - 1.0, time.process_time() + 4.0),
                              mode='tie')
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        # beta polish
        if time.process_time() < deadline - 1.0:
            ht = _lbfgs_block(best, np.arange(best.size), 200,
                              min(deadline - 0.5, time.process_time() + 3.0),
                              mode='beta', beta=1e6)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        f01, f1, f5 = _nearmax_fracs(best)
        print("it=%d R=%.9f ties=%d near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (it, bestR, _tie_count(best), f01, f1, f5))
        if bestR <= prevR + 1e-15 and it > 3:
            break

    # Final argmax polish
    fd = t0 + budget_seconds * 0.97
    if time.process_time() < fd - 1.0:
        ht = _lbfgs_block(best, np.arange(best.size), 200, fd - 0.3,
                          mode='argmax')
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_fracs(best)[2], _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

