    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth(h, passes=1):
    h = h.copy()
    for _ in range(passes):
        h[1:-1] = 0.25 * h[:-2] + 0.5 * h[1:-1] + 0.25 * h[2:]
    return _rescale(h)


# ---- New: block-coordinate resample refinement (merging/splitting) ----
def _resample_refine(h, deadline, consider, tag, rng):
    """Try to change resolution: down/up-sample, reoptimize, keep if better."""
    n = h.size
    # Downsample by 2 (pairwise average) then refine at half N
    if n >= 16 and n % 2 == 0:
        for src in [h[0::2].copy(), 0.5 * (h[0::2] + h[1::2])]:
            if time.process_time() >= deadline - 0.5:
                break
            c = _rescale(src)
            dl = min(time.process_time() + 1.2, deadline - 0.3)
            c = _lbfgs_all_pos(c, 200, dl, beta=1e7)
            if time.process_time() < dl - 0.3:
                c = _lbfgs_all_pos(c, 200, dl, beta=0.0)
            # lift back by duplication
            h2 = np.repeat(c, 2)[:n]
            if h2.size < n:
                h2 = np.concatenate([h2, np.zeros(n - h2.size)])
            h2 = _rescale(h2)
            dl = min(time.process_time() + 0.8, deadline - 0.3)
            h2 = _lbfgs_all_pos(h2, 250, dl, beta=1e7)
            consider(h2, tag + '_dn')


# ---- New: block-wise multiplicative perturbation sweep with fine LBFGS ----
def _block_sweep(best, bestR, end, consider, rng, tag):
    n = best.size
    BLK = 64
    nblocks = (n + BLK - 1) // BLK
    order = rng.permutation(nblocks)
    for bi in order:
        if time.process_time() >= end - 0.5:
            break
        s0 = bi * BLK
        s1 = min(s0 + BLK, n)
        idx = np.arange(s0, s1)
        dl = min(time.process_time() + 0.15, end - 0.3)
        cand = _lbfgs_block(best, idx, 20, dl, beta=1e7)
        r = R_of(cand)
        if r > bestR:
            consider(cand, tag + '_b%d' % bi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(ht, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if ht is None or ht.size == 0:
            return
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR, origin = ht.copy(), r, tag
            print("  NEW BEST R=%.9f (%s)" % (bestR, tag))
        elif r > alt_bestR and r < bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 1: quick tighten on start ----
    win = _peak_window(best, pad_frac=0.1, extra=128)
    dl = min(time.process_time() + 1.5, deadline - 2.0)
    ht = _lbfgs_block(best, win, 300, dl, beta=1e7)
    consider(ht, 'p1a')
    if time.process_time() < dl - 0.3:
        ht = _lbfgs_block(ht, win, 300, dl, beta=0.0)
        consider(ht, 'p1b')
    print("after phase1: R=%.9f" % bestR)

    # ---- Phase 2: resolution change attempts (new idea) ----
    if time.process_time() < deadline - 4.0:
        _resample_refine(best, min(deadline - 3.0, time.process_time() + 4.0),
                         consider, 'rs', rng)
        print("after resample: R=%.9f" % bestR)

    # ---- Phase 3: alternating sweeps + window tighten ----
    round_i = 0
    while time.process_time() < deadline - 2.0:
        round_i += 1
        slice_end = min(time.process_time() + 2.5, deadline - 1.0)
        if slice_end <= time.process_time() + 0.5:
            break
        _block_sweep(best, bestR, slice_end, consider, rng, 'sw%d' % round_i)
        if time.process_time() < slice_end - 0.5:
            win = _peak_window(best, pad_frac=0.05, extra=96)
            ht = _lbfgs_block(best, win, 300, slice_end, beta=1e7)
            consider(ht, 'w%d' % round_i)
        if time.process_time() < slice_end - 0.4:
            hs = _smooth(best, passes=1)
            hs = _lbfgs_all_pos(hs, 200, slice_end, beta=1e7)
            consider(hs, 'sm%d' % round_i)

    # ---- Final aggressive tighten ----
    for pad in [0.03, 0.02, 0.015, 0.01]:
        if time.process_time() >= deadline - 0.4:
            break
        slice_end = min(time.process_time() + 1.0, deadline - 0.3)
        win = _peak_window(best, pad_frac=pad, extra=64)
        ht = _lbfgs_block(best, win, 400, slice_end, beta=1e7)
        consider(ht, 'fin%d' % int(pad * 1000))
        if time.process_time() < slice_end - 0.3:
            ht = _lbfgs_block(ht, win, 400, slice_end, beta=0.0)
            consider(ht, 'finb%d' % int(pad * 1000))

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

