        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth(h, passes=1):
    h = h.copy()
    for _ in range(passes):
        h[1:-1] = 0.25 * h[:-2] + 0.5 * h[1:-1] + 0.25 * h[2:]
    return _rescale(h)


# ---- New: block-coordinate resample refinement (merging/splitting) ----
def _resample_refine(h, deadline, consider, tag, rng):
    """Try to change resolution: down/up-sample, reoptimize, keep if better."""
    n = h.size
    # Downsample by 2 (pairwise average) then refine at half N
    if n >= 16 and n % 2 == 0:
        for src in [h[0::2].copy(), 0.5 * (h[0::2] + h[1::2])]:
            if time.process_time() >= deadline - 0.5:
                break
            c = _rescale(src)
            dl = min(time.process_time() + 1.2, deadline - 0.3)
            c = _lbfgs_all_pos(c, 200, dl, beta=1e7)
            if time.process_time() < dl - 0.3:
                c = _lbfgs_all_pos(c, 200, dl, beta=0.0)
            # lift back by duplication
            h2 = np.repeat(c, 2)[:n]
            if h2.size < n:
                h2 = np.concatenate([h2, np.zeros(n - h2.size)])
            h2 = _rescale(h2)
            dl = min(time.process_time() + 0.8, deadline - 0.3)
            h2 = _lbfgs_all_pos(h2, 250, dl, beta=1e7)
            consider(h2, tag + '_dn')


# ---- New: block-wise multiplicative perturbation sweep with fine LBFGS ----
def _block_sweep(best, bestR, end, consider, rng, tag):
    n = best.size
    BLK = 64
    nblocks = (n + BLK - 1) // BLK
    order = rng.permutation(nblocks)
    for bi in order:
        if time.process_time() >= end - 0.5:
            break
        s0 = bi * BLK
        s1 = min(s0 + BLK, n)
        idx = np.arange(s0, s1)
        dl = min(time.process_time() + 0.15, end - 0.3)
        cand = _lbfgs_block(best, idx, 20, dl, beta=1e7)
        r = R_of(cand)
        if r > bestR:
            consider(cand, tag + '_b%d' % bi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(ht, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if ht is None or ht.size == 0:
            return
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR, origin = ht.copy(), r, tag
            print("  NEW BEST R=%.9f (%s)" % (bestR, tag))
        elif r > alt_bestR and r < bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 1: quick tighten on start ----
    win = _peak_window(best, pad_frac=0.1, extra=128)
    dl = min(time.process_time() + 1.5, deadline - 2.0)
    ht = _lbfgs_block(best, win, 300, dl, beta=1e7)
    consider(ht, 'p1a')
    if time.process_time() < dl - 0.3:
        ht = _lbfgs_block(ht, win, 300, dl, beta=0.0)
        consider(ht, 'p1b')
    print("after phase1: R=%.9f" % bestR)

    # ---- Phase 2: resolution change attempts (new idea) ----
    if time.process_time() < deadline - 4.0:
        _resample_refine(best, min(deadline - 3.0, time.process_time() + 4.0),
                         consider, 'rs', rng)
        print("after resample: R=%.9f" % bestR)

    # ---- Phase 3: alternating sweeps + window tighten ----
    round_i = 0
    while time.process_time() < deadline - 2.0:
        round_i += 1
        slice_end = min(time.process_time() + 2.5, deadline - 1.0)
        if slice_end <= time.process_time() + 0.5:
            break
        _block_sweep(best, bestR, slice_end, consider, rng, 'sw%d' % round_i)
        if time.process_time() < slice_end - 0.5:
            win = _peak_window(best, pad_frac=0.05, extra=96)
            ht = _lbfgs_block(best, win, 300, slice_end, beta=1e7)
            consider(ht, 'w%d' % round_i)
        if time.process_time() < slice_end - 0.4:
            hs = _smooth(best, passes=1)
            hs = _lbfgs_all_pos(hs, 200, slice_end, beta=1e7)
            consider(hs, 'sm%d' % round_i)

    # ---- Final aggressive tighten ----
    for pad in [0.03, 0.02, 0.015, 0.01]:
        if time.process_time() >= deadline - 0.4:
            break
        slice_end = min(time.process_time() + 1.0, deadline - 0.3)
        win = _peak_window(best, pad_frac=pad, extra=64)
        ht = _lbfgs_block(best, win, 400, slice_end, beta=1e7)
        consider(ht, 'fin%d' % int(pad * 1000))
        if time.process_time() < slice_end - 0.3:
            ht = _lbfgs_block(ht, win, 400, slice_end, beta=0.0)
            consider(ht, 'finb%d' % int(pad * 1000))

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _resample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    new_n = n * factor
    x_new = np.linspace(0.0, 1.0, new_n, endpoint=False)
    return np.interp(x_new, x_old, h, right=h[-1])


def _build_from_b_s(b, s):
    return (b[:, None] * s[None, :]).ravel()


def _optimize_s(b, s0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return s0
    nb, K = b.shape[0], s0.size

    def f(sx):
        sx = np.clip(sx, 0.0, None)
        h = _build_from_b_s(b, sx)
        val, g = _fun_grad_tie(h)
        gh = g.reshape(nb, K)
        gs = (gh * b[:, None]).sum(axis=0)
        return val, gs

    x0 = s0.copy()
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * K,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return s0
    if res is None:
        return s0
    return np.clip(res.x, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = 0.0
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size
    rng = np.random.RandomState(20240607)

    # NEW IDEA: exploit block-constant structure. The good optima are
    # piecewise-constant on blocks of fixed width. Rebuild h as
    # h[j*K + r] = b[j] * s[r] with a common block shape s, then
    # alternately optimize (b | s). This parametrization has far fewer
    # effective DOF than N and escapes the flat L-BFGS valley.

    def alt_blockshape(h0, R0, dl, K):
        if h0.size % K != 0 or h0.size // K < 4:
            return h0, R0
        nb = h0.size // K
        blk = h0.reshape(nb, K)
        b = blk.mean(axis=1)
        s = np.ones(K) / 1.0
        # init s from mean block shape (normalized)
        s = blk.mean(axis=0)
        if s.sum() <= 0:
            s = np.ones(K)
        s = s / s.mean()
        h_bc = _rescale(_build_from_b_s(b, s))
        R_bc = R_of(h_bc)
        hc, Rc = (h_bc, R_bc) if R_bc > R0 else (h0, R0)
        for sweep in range(6):
            if time.process_time() >= dl - 0.5:
                break
            # optimize b (block means) with s fixed
            bvec = _build_from_b_s(np.ones(nb), s)  # template
            # optimize full b-vector via chain gradient
            def fb(bx):
                bx = np.clip(bx, 0.0, None)
                hh = _build_from_b_s(bx, s)
                val, g = _fun_grad_tie(hh)
                gh = g.reshape(nb, K)
                gb = (gh * s[None, :]).sum(axis=1)
                return val, gb
            cb = _make_cb(dl - 0.5)
            try:
                res = minimize(fb, b.copy(), jac=True, method='L-BFGS-B',
                               bounds=[(0.0, None)] * nb, callback=cb,
                               options={'maxiter': 300, 'maxfun': 600,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                if res is not None:
                    b = np.clip(res.x, 0.0, None)
            except (TimeoutError, Exception):
                pass
            if time.process_time() >= dl - 0.5:
                break
            # optimize s with b fixed
            s = _optimize_s(b, s, 300, dl)
            hs = _rescale(_build_from_b_s(b, s))
            Rs = R_of(hs)
            if Rs > Rc + 1e-13:
                hc, Rc = hs, Rs
        return hc, Rc

    # Phase A: block-shape on the original grid, several block sizes.
    if time.process_time() < deadline - 10.0:
        for K in (32, 16, 64, 8):
            if time.process_time() >= deadline - 8.0:
                break
            hc, Rc = alt_blockshape(best, bestR, deadline - 8.0, K)
            print("blockshape K=%d R=%.9f" % (K, Rc))
            if Rc > bestR + 1e-13:
                best, bestR = hc, Rc
            elif alt is None and Rc > altR:
                alt, altR = hc, Rc

    # Phase B: resample x2 then block-shape (finer structure).
    if time.process_time() < deadline - 5.0 and best.size * 2 <= 900000:
        try:
            hf = _rescale(_seed_zeros(_resample(best, 2)))
            rf = R_of(hf)
            for K in (32, 64, 16):
                if time.process_time() >= deadline - 4.0:
                    break
                hf2, rf2 = alt_blockshape(hf, rf, deadline - 4.0, K)
                print("resample2 K=%d R=%.9f" % (K, rf2))
                if rf2 > bestR + 1e-13:
                    best, bestR = hf2, rf2
                elif alt is None and rf2 > altR:
                    alt, altR = hf2, rf2
        except Exception as e:
            print("resample failed: %s" % e)

    # Phase C: full-grid polish on peak window with tie-gradient.
    for tol in (0.9999, 0.999, 0.995):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, tol=tol, pad_frac=0.15, extra=64)
        ht = _lbfgs_block(best, win, 400, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    print("polish R=%.9f" % bestR)

    # Phase D: final full-grid L-BFGS polish if time remains.
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.20, extra=128)
        ht = _lbfgs_block(best, win, 500, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR >= start_bestR - 1e-13:
        if alt is not None and altR > start_bestR + 1e-13 and alt.size <= 1000000:
            return {"best": best, "alternative": alt}
        return best
    out = {"best": best}
    if alt is not None and alt.size <= 1000000 and altR > 0:
        out["alternative"] = alt
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    """Objective -log R, with argmax-max (single knot) for L_inf."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, beta):
    """Smoothed L_inf via log-sum-exp; good for escaping single-knot traps."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_soft(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_soft(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _smooth(best, deg):
    """Local average smoothing of heights; returns rescaled h."""
    if deg <= 0:
        return best.copy()
    k = 2 * deg + 1
    ker = np.ones(k) / k
    # pad with edge values so ends don't collapse
    pad = np.concatenate([np.full(deg, best[0]), best, np.full(deg, best[-1])])
    sm = np.convolve(pad, ker, mode='valid')
    return _rescale(np.clip(sm, 0, None))


def _random_perturb(h, scale, rng):
    n = h.size
    # smooth low-frequency perturbation: random walk then smoothed
    v = rng.standard_normal(n)
    # smooth a few times
    for _ in range(8):
        v = np.convolve(np.concatenate([[v[0]], v, [v[-1]]]),
                        [0.25, 0.5, 0.25], mode='valid')
    vmax = np.abs(v).max()
    if vmax <= 0:
        return h.copy()
    hmax = h.max()
    out = np.clip(h + scale * hmax * v / vmax, 0, None)
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Stage A: baseline local polish from start ----
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            origin = 'polish'
    print("after baseline polish R=%.7f (origin=%s)" % (bestR, origin))

    # ---- Stage B: multi-start exploration over smoothed perturbations ----
    rng = np.random.RandomState(2024)
    # Candidate perturbations: various smoothing degrees and scales
    cand_specs = []
    for deg in (0, 1, 2, 4, 8, 16):
        for scale in (0.02, 0.05, 0.10, 0.20):
            cand_specs.append((deg, scale))
    rng.shuffle(cand_specs)

    # Budget for exploration: ~2/3 of remaining time
    explore_deadline = min(deadline - 5.0,
                           time.process_time() + (deadline - time.process_time()) * 0.65)
    tried = 0
    for deg, scale in cand_specs:
        if time.process_time() >= explore_deadline:
            break
        cand = _smooth(best, deg)
        cand = _random_perturb(cand, scale, rng)
        r0 = R_of(cand)
        # Short polish of candidate
        sub_deadline = min(explore_deadline,
                           time.process_time() + max(1.0, (explore_deadline - time.process_time()) / 6.0))
        ht = _lbfgs_all_pos(cand, 250, sub_deadline, beta=0.0)
        r1 = R_of(ht)
        # A quick peak-windowed soft polish
        if time.process_time() < sub_deadline:
            win = _peak_window(ht, pad_frac=0.15, extra=128)
            ht2 = _lbfgs_block(ht, win, 150, sub_deadline, beta=1e7)
            r2 = R_of(ht2)
            if r2 > r1:
                ht, r1 = ht2, r2
        tried += 1
        if r1 > bestR + 1e-13:
            best, bestR = ht.copy(), r1
            origin = 'explore(d%d,s%.2f)' % (deg, scale)
            print("improved via explore deg=%d scale=%.2f: R=%.9f" % (deg, scale, bestR))
    print("exploration done: tried=%d best R=%.7f" % (tried, bestR))

    # ---- Stage C: intensive alternating polish of the best ----
    while time.process_time() < deadline - 0.5:
        prevR = bestR
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = 'final-polish'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.05, extra=64)
            ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = 'final-peak'
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=1e8)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = 'final-soft'
        if bestR <= prevR + 1e-14:
            break

    # ---- Stage D: one more robust attempt at tiny max-L_inf tie-break ----
    # (single-knot argmax can lock; try a very hard soft polish ladder)
    if time.process_time() < deadline - 0.5:
        for beta in (1e9, 1e10):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = 'final-hard-soft'

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _downsample(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth_noise(h, rng, sigma):
    n = h.size
    if n < 16:
        return h
    k = max(4, n // 40)
    w = np.exp(-0.5 * (np.arange(-3 * k, 3 * k + 1) / k) ** 2)
    w /= w.sum()
    z = rng.normal(0.0, 1.0, n + 6 * k)
    zs = np.convolve(z, w, mode='same')[3 * k:3 * k + n]
    zs = zs / (np.std(zs) + 1e-12)
    fac = np.exp(sigma * zs)
    h2 = h * fac
    return _rescale(h2)


def _flat_fg(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    c = Lf.max()
    w = Lf * Lf + 1e-12
    diff = Lf - c
    num = np.sum(w * diff * diff)
    den = np.sum(w)
    if den <= 0:
        return 1e18, np.zeros(h.size)
    val = np.log(num / den + 1e-300)
    gLf = 2.0 * w * diff / num
    grad = _backprop(gLf, h)
    return val, grad


def _lbfgs_flat(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _flat_fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2
    hard_end = deadline - 0.4

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=hard_end)
        return cur

    start_r = R_of(start_arr)
    best = start_arr.copy()
    best_r = start_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    n0 = start_arr.size

    # Phase A: flat-target descent
    h_flat = _lbfgs_flat(start_arr, maxiter=400, deadline=min(hard_end, time.process_time() + 7.0))
    c = _lbfgs_log(h_flat, maxiter=400, deadline=min(hard_end, time.process_time() + 5.0))
    if R_of(c) > R_of(h_flat):
        h_flat = c
    for frac, extra in ((0.20, 12), (0.10, 6), (0.05, 3)):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _window_polish_peak(h_flat, hard_end, frac, extra, maxiter=250, beta=None)
        if R_of(c) >= R_of(h_flat):
            h_flat = c
    _consider(h_flat, R_of(h_flat))

    # Phase B: raise resolution, polish
    N_big = 128000 if n0 <= 128000 else n0
    h_big = _prolongate(best, N_big)
    big_r = R_of(h_big)
    _consider(h_big, big_r)
    if big_r > start_r - 1e-6 and time.process_time() < hard_end - 4.0:
        c = _lbfgs_flat(h_big, maxiter=300, deadline=min(hard_end, time.process_time() + 5.0))
        c = _lbfgs_log(c, maxiter=400, deadline=min(hard_end, time.process_time() + 5.0))
        if R_of(c) > big_r:
            h_big = c
            big_r = R_of(c)
            _consider(h_big, big_r)

    # Phase C: perturb-and-polish loop
    rng = np.random.default_rng(2718281)
    sigmas = [0.03, 0.06, 0.10, 0.16, 0.25]
    attempts = 0
    while time.process_time() < hard_end - 1.5:
        attempts += 1
        sig = sigmas[attempts % len(sigmas)]
        base = best if best.size == N_big else _prolongate(best, N_big)
        h = _smooth_noise(base, rng, sig)
        for beta in (3000.0, 1000.0, 400.0, 150.0):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 1.0:
            c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        for frac, extra in ((0.15, 8), (0.06, 4)):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _window_polish_peak(h, hard_end, frac, extra, maxiter=300, beta=None)
            if R_of(c) >= R_of(h):
                h = c
        _consider(h, R_of(h))
        if attempts % 3 == 0:
            print("iter %d R=%.6f N=%d" % (attempts, best_r, best.size))

    # Phase D: fallback at original resolution
    if time.process_time() < hard_end - 2.0:
        try:
            h = _downsample(best, n0) if best.size != n0 else best.copy()
            if R_of(h) < start_r - 1e-6:
                h = start_arr.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=200, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra, maxiter=300, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
        except Exception:
            pass

    if best_r < start_r:
        best = start_arr.copy()
        best_r = start_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0, None)
    return _rescale(h2)


def _riemann_lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = _rescale(np.clip(h0, 0, None))
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        if hh.sum() <= 0:
            return 1e18, np.zeros(n)
        val, g = _fun_grad_tie(hh)
        denom = float(np.dot(hh, hh))
        if denom > 0:
            g = g - (float(np.dot(g, hh)) / denom) * hh
        return val, g

    cb = _make_cb(deadline - 0.15)
    x0 = h.copy()
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0, None))


def _prolongate(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N) / N
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(n + 1, dtype=float))
    hh = np.clip(np.diff(out), 0, None)
    if hh.sum() <= 0:
        return np.ones(N) / N
    return hh


def _rasterise(widths, heights):
    N = int(widths.sum())
    h = np.empty(N, dtype=float)
    pos = 0
    for w, a in zip(widths, heights):
        h[pos:pos + w] = a
        pos += w
    return h


def _collapse(h, nb):
    n = h.size
    edges = np.linspace(0, n, nb + 1).astype(int)
    widths = np.diff(edges)
    heights = np.empty(nb)
    for i in range(nb):
        lo, hi = edges[i], edges[i + 1]
        if hi > lo:
            heights[i] = h[lo:hi].mean()
        else:
            heights[i] = 0.0
    return widths.astype(int), heights


def _brief_polish(h, deadline, maxiter=25):
    if time.process_time() >= deadline - 0.3:
        return h
    hp = _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=True)
    if R_of(hp) >= R_of(h):
        return hp
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240607)
    N = 3281
    NB = 64

    startR = 0.0
    start_h = None
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            if s.size != N:
                s = _rescale(_prolongate(s, N))
            else:
                s = _rescale(s)
            start_h = s
            startR = R_of(s)

    if start_h is None:
        # fallback: build something reasonable
        start_h = _rescale(np.ones(N))
        startR = R_of(start_h)

    # Extract 64-block genome from start
    w, a = _collapse(start_h, NB)
    w = np.maximum(1, w.astype(int))
    # fix sum to N
    diff = N - w.sum()
    i = 0
    while diff != 0 and i < 1000000:
        j = i % NB
        if diff > 0:
            w[j] += 1; diff -= 1
        elif w[j] > 1:
            w[j] -= 1; diff += 1
        i += 1

    # Polish heights with widths fixed to establish baseline
    def polish_genome(w, a, maxiter, dl):
        h = _rescale(_rasterise(w, a))
        hp = _lbfgs_block(h, np.arange(N), maxiter, dl, tie=True)
        return hp, R_of(hp)

    cur_h, curR = polish_genome(w, a, 100, deadline)
    best_h, bestR = cur_h.copy(), curR
    print("baseline R=%.9f (start %.9f)" % (bestR, startR))

    # Also keep a full-resolution polished version as best
    if time.process_time() < deadline - 2.0:
        hp = _riemann_lbfgs(best_h, 150, deadline - 1.0)
        rp = R_of(hp)
        if rp > bestR:
            best_h, bestR = hp, rp
            print("full polish R=%.9f" % bestR)

    # Local width-shift search
    accepted = 0
    moves_tried = 0
    since_full = 0

    while time.process_time() < deadline - 1.5:
        moves_tried += 1
        # propose width move: pick 1-3 blocks, shift +-1..+-8 cells between neighbours
        w2 = w.copy()
        nmoves = int(rng.integers(1, 4))
        ok = True
        for _ in range(nmoves):
            j = int(rng.integers(0, NB))
            d = int(rng.choice([-1, 1]) * rng.integers(1, 9))
            if d > 0:
                if w2[j] - d >= 1:
                    k = (j + 1) % NB
                    w2[j] -= d; w2[k] += d
            else:
                k = (j + 1) % NB
                if w2[k] + d >= 1:
                    w2[j] -= d; w2[k] += d
        # occasionally split/merge
        if rng.random() < 0.15:
            j = int(rng.integers(0, NB))
            if w2[j] >= 4:
                # split: give half to neighbour
                half = w2[j] // 2
                k = (j + 1) % NB
                w2[j] -= half; w2[k] += half

        if w2.sum() != N or np.any(w2 < 1):
            continue

        # brief height polish with new widths
        h2 = _rescale(_rasterise(w2, a))
        hp = _lbfgs_block(h2, np.arange(N), 60, deadline - 1.0, tie=True)
        rp = R_of(hp)

        if rp > curR + 1e-12:
            w = w2
            a = _collapse(hp, NB)[1]
            cur_h, curR = hp, rp
            accepted += 1
            since_full += 1
            if rp > bestR:
                best_h, bestR = hp.copy(), rp
            print("accept %d R=%.9f wstd=%.3f" % (accepted, bestR, float(np.std(w))))

            # every 10 accepted moves, full polish
            if since_full >= 10 and time.process_time() < deadline - 3.0:
                since_full = 0
                hf = _riemann_lbfgs(cur_h, 100, deadline - 1.0)
                rf = R_of(hf)
                if rf > curR:
                    cur_h, curR = hf, rf
                    if rf > bestR:
                        best_h, bestR = hf.copy(), rf
                    print("full polish R=%.9f" % bestR)
        else:
            # try a quick full polish on the candidate occasionally
            if rng.random() < 0.1 and time.process_time() < deadline - 3.0:
                hf = _riemann_lbfgs(hp, 60, deadline - 1.0)
                rf = R_of(hf)
                if rf > curR + 1e-12:
                    w = w2
                    a = _collapse(hf, NB)[1]
                    cur_h, curR = hf, rf
                    accepted += 1
                    since_full += 1
                    if rf > bestR:
                        best_h, bestR = hf.copy(), rf
                    print("accept-full %d R=%.9f wstd=%.3f" % (accepted, bestR, float(np.std(w))))

    # Final full polish
    if time.process_time() < deadline - 0.5:
        hp = _riemann_lbfgs(best_h, 200, deadline)
        rp = R_of(hp)
        if rp > bestR:
            best_h, bestR = hp, rp

    if start_h is not None and bestR < startR:
        best_h = start_h
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, moves=%d, accepted=%d)" % (
        bestR, startR, best_h.size, moves_tried, accepted))

    result = {"best": best_h}
    # provide alternative if distinct
    if cur_h is not None and R_of(cur_h) > startR + 1e-12:
        na = np.linalg.norm(cur_h); nb = np.linalg.norm(best_h)
        if na > 0 and nb > 0 and float(np.dot(cur_h, best_h) / (na * nb)) < 0.9999:
            result["alternative"] = cur_h
    return result

