    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True, logp=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    cb = _make_cb(deadline - 0.2)
    try:
        if logp:
            pos = active[h[active] > 0]
            if pos.size == 0:
                return h0
            hmax = h.max()
            floor = 1e-12 * hmax if hmax > 0 else 1e-12
            u0 = np.log(np.clip(h[pos], floor, None))

            def f(u):
                hh = h.copy()
                hh[pos] = np.exp(u)
                val, g = fg(hh)
                return val, g[pos] * hh[pos]

            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * pos.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            if res is None:
                return h0
            h2 = h.copy()
            h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
            return _rescale(h2)
        else:
            x0 = h[active].copy()

            def f(x):
                hh = h.copy()
                hh[active] = np.clip(x, 0.0, None)
                val, g = fg(hh)
                return val, g[active]

            res = minimize(f, x0, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * active.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            if res is None:
                return h0
            h2 = h.copy()
            h2[active] = np.clip(res.x, 0.0, None)
            return _rescale(h2)
    except (TimeoutError, Exception):
        return h0


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d, ties=%d)" % (bestR, best.size, _tie_count(best)))

    alt = None

    # Phase 1: log-parameterised full polish (positive part) to sharpen plateau.
    if time.process_time() < deadline - 20.0:
        t_lim = min(deadline - 18.0, time.process_time() + 10.0)
        cand = _lbfgs_block(best, np.arange(best.size), 300, t_lim, tie=True, logp=True)
        rc = R_of(cand)
        print("logp polish R=%.12f ties=%d" % (rc, _tie_count(cand)))
        if rc > bestR + 1e-15:
            best, bestR = cand, rc
        elif rc > startR + 1e-14:
            alt = cand

    # Phase 2: beta escalation on peak window (cheap) then full.
    betas = [1e3, 1e4, 1e5, 1e6, 1e7, 1e8]
    for b in betas:
        if time.process_time() > deadline - 8.0:
            break
        t_lim = min(deadline - 6.0, time.process_time() + 4.0)
        cand = _lbfgs_block(best, np.arange(best.size), 200, t_lim, beta=b, logp=True)
        rc = R_of(cand)
        if rc > bestR + 1e-15:
            best, bestR = cand, rc
        print("beta=%.0e R=%.12f ties=%d" % (b, rc, _tie_count(cand)))

    # Phase 3: final full tie polish (linear) to drive exact ties.
    if time.process_time() < deadline - 1.5:
        t_lim = min(deadline - 0.4, time.process_time() + 8.0)
        cand = _lbfgs_block(best, np.arange(best.size), 500, t_lim, tie=True)
        rc = R_of(cand)
        print("final tie polish R=%.12f ties=%d" % (rc, _tie_count(cand)))
        if rc > bestR + 1e-15:
            best, bestR = cand, rc
        elif rc > startR + 1e-14 and alt is None:
            alt = cand

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt is not None and R_of(alt) <= startR + 1e-14:
        result["alternative"] = alt
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _build_from_b_s(b, s):
    return (b[:, None] * s[None, :]).ravel()


def _optimize_s(b, s0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return s0
    nb, K = b.shape[0], s0.size

    def f(sx):
        sx = np.clip(sx, 0.0, None)
        h = _build_from_b_s(b, sx)
        val, g = _fun_grad_tie(h)
        gh = g.reshape(nb, K)
        gs = (gh * b[:, None]).sum(axis=0)
        return val, gs

    x0 = s0.copy()
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * K,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return s0
    if res is None:
        return s0
    return np.clip(res.x, 0.0, None)


def _optimize_b(b0, s, maxiter, deadline):
    """Optimize block heights b with fixed within-block shape s."""
    if time.process_time() >= deadline - 0.3:
        return b0
    nb, K = b0.size, s.size

    def f(bx):
        bx = np.clip(bx, 0.0, None)
        h = _build_from_b_s(bx, s)
        val, g = _fun_grad_tie(h)
        gh = g.reshape(nb, K)
        gb = (gh * s[None, :]).sum(axis=1)
        return val, gb

    x0 = b0.copy()
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return b0
    if res is None:
        return b0
    return np.clip(res.x, 0.0, None)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-9)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    n = best.size
    # Try block-structured optimization: h[j*K + r] = b[j]*s[r]
    K = 32
    if n % K == 0 and n // K >= 4:
        nb = n // K
        blk = best.reshape(nb, K)
        b = blk.mean(axis=1)
        s = np.ones(K); s = s / s.mean()
        h_bc = _rescale(_build_from_b_s(b, s))
        r_bc = R_of(h_bc)
        print("block rebuild R=%.9f (nb=%d,K=%d)" % (r_bc, nb, K))
        # Alternate optimize b and s
        alt_deadline = t0 + budget_seconds * 0.55
        cur_s = s.copy()
        cur_b = b.copy()
        cur_h = _build_from_b_s(cur_b, cur_s)
        cur_h = _rescale(cur_h)
        cur_r = R_of(cur_h)
        it = 0
        while time.process_time() < alt_deadline - 0.5:
            it += 1
            new_b = _optimize_b(cur_b, cur_s, 200, alt_deadline)
            new_s = _optimize_s(new_b, cur_s, 200, alt_deadline)
            nh = _rescale(_build_from_b_s(new_b, new_s))
            nr = R_of(nh)
            if nr > cur_r + 1e-16:
                cur_b, cur_s, cur_h, cur_r = new_b, new_s, nh, nr
            else:
                # slight perturbation to escape
                cur_s = np.clip(cur_s * (1.0 + 0.01 * np.random.default_rng(it).standard_normal(K)), 0, None)
                if cur_s.sum() <= 0:
                    break
            if it % 5 == 0:
                print("  block-alt it=%d R=%.12f" % (it, cur_r))
        print("block-alt done it=%d R=%.12f" % (it, cur_r))

        # Polish with full-resolution peak-window L-BFGS
        if cur_r > bestR - 1e-9:
            h_pol = cur_h
            for pad in (0.10, 0.05, 0.03):
                if time.process_time() >= deadline - 3.0:
                    break
                win = _peak_window(h_pol, pad_frac=pad, extra=128)
                ht = _lbfgs_block(h_pol, win, 300,
                                  min(deadline - 1.5,
                                      time.process_time() + 4.0))
                rt = R_of(ht)
                if rt > R_of(h_pol) + 1e-15:
                    h_pol = ht
            r_pol = R_of(h_pol)
            if r_pol > bestR + 1e-15:
                best, bestR = h_pol.copy(), r_pol
                print("block polish ACCEPT R=%.12f" % bestR)
            else:
                print("block polish kept R=%.12f (best %.12f)" % (r_pol, bestR))

    # Final full-resolution peak polish
    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 2.0:
        win = _peak_window(best, pad_frac=0.02, extra=128)
        ht = _lbfgs_block(best, win, 400, fd - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("FINAL peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = int(np.ceil((1.0 - q) * n))
    if m < 1:
        m = 1
    if m > n:
        m = n
    order = np.argsort(Lf)
    top = order[-m:]
    mean_top = Lf[top].mean()
    if mean_top <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[top] += (1.0 / m) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
