        win = _peak_window(best, tol=0.95, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 200, fd2, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("loop %d peak ACCEPT R=%.9f top1%%=%.9f"
                  % (loop, bestR, _top_frac_mean(best, 0.01)))

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None)
    mx = Lp.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    r = Lp / mx
    rp = r ** p
    Sp = rp.sum()
    if Sp <= 0:
        return _fun_grad_tie(h)
    logp = np.log(mx) + np.log(Sp) / p
    e_max = np.zeros_like(Lf)
    e_max[int(np.argmax(Lp))] = 1.0
    rp1 = r ** (p - 1)
    S2 = np.sum(rp1 * r)
    dlogp = e_max / mx + (rp1 - S2 * e_max) / (Sp * mx)
    gLf = -dq / num + dlogp
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logp
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, pnorm=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if pnorm > 0:
        fg = (lambda hh: _fun_grad_pnorm(hh, pnorm))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _upsample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    m = (n - 1) * factor + 1
    xo = np.linspace(0, n - 1, m)
    xi = np.arange(n)
    return np.interp(xo, xi, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    alt_best, altR = None, -1.0
    print("base R=%.9f (N=%d) frac5=%.4f"
          % (bestR, best.size, _frac_near_max(best, 5e-2)))

    def consider(hc, tag):
        nonlocal best, bestR, alt_best, altR
        rc = R_of(hc)
        if rc > altR:
            altR = rc; alt_best = hc.copy()
        if rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc
            print("  %s R=%.12f frac5=%.4f *" % (tag, rc, _frac_near_max(hc, 5e-2)))
        return rc

    # ---- Phase A: upsampling to higher resolution first (key new idea) ----
    # A finer grid lets the plateau be resolved better before polishing.
    while (time.process_time() < deadline - 8.0 and best.size < 400000):
        f = 2
        hu = _upsample(best, f)
        hu = _rescale(hu)
        win = _peak_window(hu, pad_frac=0.3, extra=512)
        ht = _lbfgs_block(hu, win, 250,
                          min(deadline - 4.0, time.process_time() + 6.0))
        rc = consider(ht, "upsample x%d win" % f)
        if rc < bestR - 1e-12:
            break
        if time.process_time() < deadline - 4.0:
            pf = _lbfgs_block(best, np.arange(best.size), 150,
                              min(deadline - 3.0, time.process_time() + 4.0))
            consider(pf, "upsample x%d full" % f)

    # ---- Phase B: p-norm continuation (sharpening the max) ----
    for p in (8.0, 16.0, 32.0, 64.0):
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hp = _lbfgs_block(best, np.arange(best.size), 250, tlim, pnorm=p)
        consider(hp, "pnorm p=%.0f" % p)

    # ---- Phase C: tie polish on peak window (main driver) ----
    for pad in (0.4, 0.25, 0.15, 0.08, 0.04):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=256)
        ht = _lbfgs_block(best, win, 400,
                          min(deadline - 1.0, time.process_time() + 4.0))
        consider(ht, "win pad=%.2f" % pad)

    # ---- Phase D: global tie polish ----
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 400,
                           min(deadline - 0.5, time.process_time() + 6.0))
        consider(pol, "final global tie")

    # ---- Phase E: final pnorm re-sharpen & tie ----
    if time.process_time() < deadline - 0.8:
        hp = _lbfgs_block(best, np.arange(best.size), 200,
                          min(deadline - 0.4, time.process_time() + 3.0), pnorm=48.0)
        consider(hp, "final pnorm")
    if time.process_time() < deadline - 0.4:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.2, time.process_time() + 2.0))
        consider(pol, "final tie2")

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and R_of(alt_best) > startR + 1e-12:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.12, 0.08, 0.05), iters=300, beta=1e7):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=0.0)
            if R_of(ht2) > R_of(h) + 1e-14:
                h = ht2
    return h


def _refine_split(h, jitter):
    n = h.size
    out = np.zeros(2 * n)
    sign = np.where(np.arange(n) % 2 == 0, 1.0, -1.0)
    fac = 1.0 + jitter * sign
    out[0::2] = h * fac
    out[1::2] = h * (2.0 - fac)
    return out


def _upsample_smooth(h, factor=2):
    """Smooth interpolation upsampling: preserves shape better than split."""
    n = h.size
    m = (n - 1) * factor + 1
    xi = np.linspace(0, n - 1, m)
    lo = np.floor(xi).astype(int)
    hi = np.minimum(lo + 1, n - 1)
    t = xi - lo
    out = h[lo] * (1 - t) + h[hi] * t
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            sbest = _rescale(base)
            sR = R_of(sbest)
        else:
            sbest, sR = None, 0.0
    else:
        sbest, sR = None, 0.0

    if sbest is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        sbest = _rescale(h)
        sR = R_of(sbest)

    best = sbest.copy()
    bestR = sR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # === NEW IDEA: smooth-interpolation upsampling + full reoptimize ===
    alt = None
    if time.process_time() < deadline - 2.0:
        h2 = _upsample_smooth(sbest, 2)
        h2 = _rescale(h2)
        # beta ladder at fine grid
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_all_pos(h2, 200, deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-14:
                h2 = ht
        h2 = _peak_ladder(h2, deadline, pads=(0.20, 0.12, 0.08, 0.05), iters=250)
        altR = R_of(h2)
        alt = h2
        print("smooth-upsample branch: R=%.9f N=%d" % (altR, h2.size))
        if altR > bestR + 1e-14:
            best, bestR, origin = h2.copy(), altR, "upsample"

    # === Continue from current best with peak ladder until deadline ===
    work = best.copy()
    curR = bestR
    pads = [0.12, 0.08, 0.06, 0.10, 0.15, 0.20, 0.04, 0.03]
    it = 0
    while time.process_time() < deadline - 0.6:
        pad = pads[it % len(pads)]
        it += 1
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 250, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > curR + 1e-14:
            work, curR = ht, r
            if curR > bestR + 1e-14:
                best, bestR, origin = ht.copy(), curR, "pad%d" % it
        if time.process_time() < deadline - 0.5:
            ht2 = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > curR + 1e-14:
                work, curR = ht2, r2
                if curR > bestR + 1e-14:
                    best, bestR, origin = ht2.copy(), curR, "all0_%d" % it

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, sR, best.size))

    if bestR > sR + 1e-12:
        return {"best": best, "alternative": alt if alt is not None else best}
    if alt is not None:
        return {"best": best, "alternative": alt}
    return best

