    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.12, 0.08, 0.05), iters=300, beta=1e7):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=0.0)
            if R_of(ht2) > R_of(h) + 1e-14:
                h = ht2
    return h


def _refine_split(h, jitter):
    n = h.size
    out = np.zeros(2 * n)
    sign = np.where(np.arange(n) % 2 == 0, 1.0, -1.0)
    fac = 1.0 + jitter * sign
    out[0::2] = h * fac
    out[1::2] = h * (2.0 - fac)
    return out


def _upsample_smooth(h, factor=2):
    """Smooth interpolation upsampling: preserves shape better than split."""
    n = h.size
    m = (n - 1) * factor + 1
    xi = np.linspace(0, n - 1, m)
    lo = np.floor(xi).astype(int)
    hi = np.minimum(lo + 1, n - 1)
    t = xi - lo
    out = h[lo] * (1 - t) + h[hi] * t
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            sbest = _rescale(base)
            sR = R_of(sbest)
        else:
            sbest, sR = None, 0.0
    else:
        sbest, sR = None, 0.0

    if sbest is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        sbest = _rescale(h)
        sR = R_of(sbest)

    best = sbest.copy()
    bestR = sR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # === NEW IDEA: smooth-interpolation upsampling + full reoptimize ===
    alt = None
    if time.process_time() < deadline - 2.0:
        h2 = _upsample_smooth(sbest, 2)
        h2 = _rescale(h2)
        # beta ladder at fine grid
        for beta in [1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_all_pos(h2, 200, deadline - 0.3, beta=beta)
            if R_of(ht) > R_of(h2) + 1e-14:
                h2 = ht
        h2 = _peak_ladder(h2, deadline, pads=(0.20, 0.12, 0.08, 0.05), iters=250)
        altR = R_of(h2)
        alt = h2
        print("smooth-upsample branch: R=%.9f N=%d" % (altR, h2.size))
        if altR > bestR + 1e-14:
            best, bestR, origin = h2.copy(), altR, "upsample"

    # === Continue from current best with peak ladder until deadline ===
    work = best.copy()
    curR = bestR
    pads = [0.12, 0.08, 0.06, 0.10, 0.15, 0.20, 0.04, 0.03]
    it = 0
    while time.process_time() < deadline - 0.6:
        pad = pads[it % len(pads)]
        it += 1
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 250, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > curR + 1e-14:
            work, curR = ht, r
            if curR > bestR + 1e-14:
                best, bestR, origin = ht.copy(), curR, "pad%d" % it
        if time.process_time() < deadline - 0.5:
            ht2 = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > curR + 1e-14:
                work, curR = ht2, r2
                if curR > bestR + 1e-14:
                    best, bestR, origin = ht2.copy(), curR, "all0_%d" % it

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, sR, best.size))

    if bestR > sR + 1e-12:
        return {"best": best, "alternative": alt if alt is not None else best}
    if alt is not None:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.ndimage import gaussian_filter1d


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = int(np.ceil((1.0 - q) * n))
    if m < 1:
        m = 1
    if m > n:
        m = n
    order = np.argsort(Lf)
    top = order[-m:]
    mean_top = Lf[top].mean()
    if mean_top <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[top] += (1.0 / m) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_cvar(h0, q, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_cvar(hh, q)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def _argmax_pos(h):
    Lf = _knots(h)
    return float(np.argmax(Lf)) / max(1, Lf.size - 1)


def _jump_profile(h, a, b, rng):
    L = b - a
    seg = h[a:b].copy()
    if rng.random() < 1.0 / 3.0:
        m = seg.mean() if seg.size else h.mean()
        g = np.full(L, m)
    else:
        sig1 = max(1.0, L / 20.0)
        sig2 = max(1.0, L / 40.0)
        base = gaussian_filter1d(seg, sig1, mode='nearest')
        noise = rng.standard_normal(L)
        noise = gaussian_filter1d(noise, sig2, mode='nearest')
        g = base * (1.0 + 0.35 * noise)
    g = np.clip(g, 0.0, None)
    return g


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    inc = start_best.copy()
    incR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f argmax=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01), _argmax_pos(best)))

    # ---- CVaR q-anneal ladder (kept from base) ----
    qs = (0.90, 0.95, 0.98, 0.995, 0.999)
    cvar_deadline = t0 + budget_seconds * 0.30
    per_q = budget_seconds * 0.05
    for q in qs:
        if time.process_time() >= cvar_deadline - 1.0:
            break
        dq = min(cvar_deadline, time.process_time() + per_q)
        ht = _lbfgs_cvar(best, q, 20, dq)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            inc, incR = ht.copy(), r
            print("cvar q=%.3f NEW BEST R=%.9f" % (q, bestR))

    # ---- structural jump Metropolis loop ----
    N = best.size
    T = 2e-6
    trial = 0
    accepted = 0
    while time.process_time() < deadline - 1.5:
        trial += 1
        L = int(rng.integers(max(2, int(0.03 * N)), max(3, int(0.15 * N))))
        a = int(rng.integers(0, max(1, N - L)))
        b = min(N, a + L)
        cand = inc.copy()
        cand[a:b] = _jump_profile(inc, a, b, rng)
        cand = _rescale(cand)

        # local re-optimize on window
        fd = min(deadline, time.process_time() + budget_seconds * 0.02)
        win = np.arange(a, b)
        cand = _lbfgs_block(cand, win, 80, fd)
        # peak-window polish
        if time.process_time() < deadline - 1.0:
            fd2 = min(deadline, time.process_time() + budget_seconds * 0.02)
            pw = _peak_window(cand, tol=0.95, pad_frac=0.05, extra=64)
            cand = _lbfgs_block(cand, pw, 150, fd2)

        r = R_of(cand)
        dR = r - incR
        if dR > 0:
            inc, incR = cand.copy(), r
            accepted += 1
        else:
            if T > 0 and rng.random() < np.exp(dR / T):
                inc, incR = cand.copy(), r
                accepted += 1
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
            print("trial %d NEW BEST R=%.9f (a=%d,L=%d, zero=%.4f, nearmax5=%.4f, argmax=%.4f)"
                  % (trial, bestR, a, L, _zero_frac(best),
                     _nearmax_frac(best), _argmax_pos(best)))
        T *= 0.97
        if T < 1e-12:
            T = 2e-6 * 0.5  # reheat

        if trial % 60 == 0 and time.process_time() < deadline - 2.0:
            fd3 = min(deadline, time.process_time() + budget_seconds * 0.05)
            ht = _lbfgs_all_pos(inc, 120, fd3)
            r2 = R_of(ht)
            if r2 > incR:
                inc, incR = ht.copy(), r2
            if r2 > bestR + 1e-15:
                best, bestR = ht.copy(), r2
                print("trial %d full-polish NEW BEST R=%.9f" % (trial, bestR))
            if time.process_time() < deadline - 1.5:
                fd4 = min(deadline, time.process_time() + budget_seconds * 0.05)
                hb = _lbfgs_all_pos(best, 120, fd4)
                rb = R_of(hb)
                if rb > bestR + 1e-15:
                    best, bestR = hb.copy(), rb
                    print("trial %d best-polish NEW BEST R=%.9f" % (trial, bestR))

    print("final R=%.9f (start %.9f, N=%d, trials=%d, accepted=%d, zero_frac=%.4f, nearmax5=%.4f, argmax=%.4f)"
          % (bestR, start_bestR, best.size, trial, accepted,
             _zero_frac(best), _nearmax_frac(best), _argmax_pos(best)))

    result = {"best": best}
    if incR > bestR + 1e-15:
        result["best"] = inc
    result["alternative"] = inc
    return result

