        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _block_sum(h, factor):
    n = h.size
    nb = (n + factor - 1) // factor
    pad = nb * factor - n
    if pad > 0:
        h = np.concatenate([h, np.zeros(pad)])
    return h.reshape(nb, factor).sum(axis=1)


def _upsample(h, target_n):
    n = h.size
    factor = int(round(target_n / n))
    if factor < 1:
        factor = 1
    up = np.repeat(h, factor)
    if up.size > target_n:
        up = up[:target_n]
    elif up.size < target_n:
        up = np.concatenate([up, np.full(target_n - up.size, up[-1])])
    return up


def _softmax_pass(h, beta, maxiter, deadline):
    # surrogate: smooth max via softmax over knots
    if time.process_time() >= deadline - 0.3:
        return h
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(n)
        num, dq, Lf = _num_and_dq(hh)
        m = Lf.max()
        e = np.exp(beta * (Lf - m))
        Z = e.sum()
        sm = (e * Lf).sum() / Z
        # d sm / d Lf
        dsm = e * (Lf - sm) / Z * beta + e / Z
        gLf = -dq / num + dsm / sm
        grad = _backprop(gLf, hh) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
        return val, grad

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, pad_frac, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    n = h.size
    Lf = _knots(h)
    k = int(np.argmax(Lf))
    # f*f knot k corresponds to convolution index k-1; peak in h roughly at k/2
    center = k // 2
    half = max(4, int(pad_frac * n))
    lo = max(0, center - half)
    hi = min(n, center + half)
    if hi - lo < 4:
        return h
    free = np.arange(lo, hi)
    return _lbfgs_block(h, free, maxiter, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    start_best = best.copy()
    startR = R_of(start_best)
    N_full = best.size
    print("base R=%.9f (N=%d)" % (startR, N_full))

    # Build ladder by block-summing
    factors = [16, 8, 4, 2, 1]
    levels = []
    for fac in factors:
        if fac == 1:
            levels.append(best.copy())
        else:
            levels.append(_block_sum(best, fac))

    cur = levels[0]
    curR = R_of(cur)
    print("level N=%d R=%.9f" % (cur.size, curR))

    for li in range(len(levels)):
        target_n = levels[li].size
        # upsample cur to target_n
        if cur.size != target_n:
            cur = _upsample(cur, target_n)
            cur = _rescale(cur)
        # full tie polish
        if time.process_time() < deadline - 2.0:
            tlim = min(deadline - 1.0, time.process_time() + 8.0)
            pol = _lbfgs_block(cur, np.arange(cur.size), 400, tlim)
            rp = R_of(pol)
            if rp > R_of(cur):
                cur = pol
        # softmax pass if stalled or always once
        if time.process_time() < deadline - 1.5:
            tlim = min(deadline - 0.8, time.process_time() + 4.0)
            sm = _softmax_pass(cur, 1e5, 200, tlim)
            if R_of(sm) > R_of(cur):
                cur = sm
        curR = R_of(cur)
        print("level N=%d R=%.9f" % (cur.size, curR))
        if curR > R_of(best):
            best = cur.copy()

    # full-resolution state right after ladder
    ladder_full = cur.copy()
    bestR = R_of(best)
    print("post-ladder R=%.9f" % bestR)

    # peak-window ladder loop
    pads = [0.08, 0.05, 0.03]
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        improved = False
        for pad in pads:
            if time.process_time() >= deadline - 1.5:
                break
            tlim = min(deadline - 0.8, time.process_time() + 3.0)
            w = _peak_window(best, pad, 250, tlim)
            rw = R_of(w)
            if rw > bestR + 1e-12:
                best = w
                bestR = rw
                improved = True
        if time.process_time() < deadline - 1.5:
            tlim = min(deadline - 0.5, time.process_time() + 3.0)
            pol = _lbfgs_block(best, np.arange(best.size), 250, tlim)
            rp = R_of(pol)
            if rp > bestR + 1e-12:
                best = pol
                bestR = rp
                improved = True
        if not improved and it > 2:
            break

    bestR = R_of(best)
    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if bestR > startR:
        return {"best": best, "alternative": ladder_full}
    else:
        return {"best": start_best, "alternative": ladder_full}

