import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _free_support(h, thresh=1e-9):
    return np.flatnonzero(h > thresh * h.max())


def _active_set_polish(best, bestR, deadline):
    """Identify and free the 'inactive' heights (zeros), then re-optimize
    the full support; loop until no further improvement."""
    for _ in range(6):
        if time.process_time() >= deadline - 0.5:
            break
        act = _free_support(best)
        if act.size == 0:
            break
        # Try to open support at edges of the active region + random zeros
        n = best.size
        lo = int(act.min()); hi = int(act.max())
        cand = []
        for k in (lo - 1, lo - 2, hi + 1, hi + 2):
            if 0 <= k < n and best[k] <= 0:
                cand.append(k)
        # add a few random zeros inside the support
        zeros = np.flatnonzero(best <= 0)
        if zeros.size > 0:
            rng = np.random.default_rng(int(time.process_time() * 1e6) & 0xffffffff)
            pick = rng.choice(zeros, size=min(8, zeros.size), replace=False)
            cand.extend(pick.tolist())
        if not cand:
            break
        trial = best.copy()
        eps = 1e-6 * best.mean() if best.mean() > 0 else 1e-9
        for k in cand:
            trial[k] = eps
        trial = _rescale(trial)
        r = R_of(trial)
        if r > bestR + 1e-13:
            best, bestR = trial, r
        else:
            # try opening all zeros at once (broad exploration)
            trial2 = best.copy()
            trial2[trial2 <= 0] = eps
            trial2 = _rescale(trial2)
            r2 = R_of(trial2)
            if r2 > bestR + 1e-13:
                best, bestR = trial2, r2
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Experiment: active-set zero-opening ----
    alt_best = None
    alt_bestR = 0.0
    try:
        h_alt, r_alt = _active_set_polish(best.copy(), bestR, deadline)
        alt_best, alt_bestR = h_alt, r_alt
        print("active-set polish: R=%.9f (start %.9f)" % (r_alt, start_bestR))
        if r_alt > bestR + 1e-13:
            best, bestR = h_alt.copy(), r_alt
            origin = 'start+activeset'
    except Exception as e:
        print("active-set failed: %s" % e)

    # ---- Newton-style beta-smoothed polish, concentrated on peak ----
    newton_best = best.copy()
    newton_bestR = bestR
    try:
        cur = best.copy()
        for beta in (1e5, 1e6, 1e7):
            if time.process_time() >= deadline - 6.0:
                break
            win = _peak_window(cur, pad_frac=0.15, extra=256)
            ht = _lbfgs_block(cur, win, 400, deadline - 6.0, beta=beta)
            r = R_of(ht)
            print("beta polish %.0e: R=%.9f" % (beta, r))
            if r > newton_bestR + 1e-13:
                newton_best, newton_bestR = ht.copy(), r
            cur = ht
        print("beta polish done: R=%.9f" % newton_bestR)
        if newton_bestR > bestR + 1e-13:
            best, bestR = newton_best.copy(), newton_bestR
            origin = origin + '+beta'
    except Exception as e:
        print("beta polish failed: %s" % e)

    # ---- Base cycle ----
    if time.process_time() < deadline - 0.5:
        # tight window polish beta=0
        try:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight0'
            print("tight0: R=%.9f" % bestR)
        except Exception:
            pass
        # full L-BFGS polish
        try:
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+full0'
            print("full0: R=%.9f" % bestR)
        except Exception:
            pass

    # ---- Outer-window passes ----
    try:
        n = best.size
        k = min(2000, n // 4)
        if k > 0:
            outer = np.concatenate((np.arange(0, k), np.arange(n - k, n)))
            for beta in (0.0, 1e7):
                if time.process_time() >= deadline - 0.5:
                    break
                ht = _lbfgs_block(best, outer, 200, deadline - 0.5, beta=beta)
                r = R_of(ht)
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+outer%.0e' % beta
    except Exception:
        pass

    print("final R=%.9f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if alt_best is not None and alt_bestR < bestR - 1e-13:
        return {"best": best, "alternative": alt_best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _block_sum(h, factor):
    n = h.size
    nb = (n + factor - 1) // factor
    pad = nb * factor - n
    if pad > 0:
        h = np.concatenate([h, np.zeros(pad)])
    return h.reshape(nb, factor).sum(axis=1)


def _upsample(h, target_n):
    n = h.size
    factor = int(round(target_n / n))
    if factor < 1:
        factor = 1
    up = np.repeat(h, factor)
    if up.size > target_n:
        up = up[:target_n]
    elif up.size < target_n:
        up = np.concatenate([up, np.full(target_n - up.size, up[-1])])
    return up


def _softmax_pass(h, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(n)
        num, dq, Lf = _num_and_dq(hh)
        m = Lf.max()
        e = np.exp(beta * (Lf - m))
        Z = e.sum()
        sm = (e * Lf).sum() / Z
        dsm = e * (Lf - sm) / Z * beta + e / Z
        gLf = -dq / num + dsm / sm
        grad = _backprop(gLf, hh) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
        return val, grad

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, pad_frac, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    n = h.size
    Lf = _knots(h)
    k = int(np.argmax(Lf))
    center = k // 2
    half = max(4, int(pad_frac * n))
    lo = max(0, center - half)
    hi = min(n, center + half)
    if hi - lo < 4:
        return h
    free = np.arange(lo, hi)
    return _lbfgs_block(h, free, maxiter, deadline)


def _full_polish(h, maxiter, deadline):
    return _lbfgs_block(h, np.arange(h.size), maxiter, deadline)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    frac01 = np.mean(Lf >= mx * 0.999)
    frac5 = np.mean(Lf >= mx * 0.95)
    nz = h[h > 0]
    mm = (h.max() / h.mean()) if h.mean() > 0 else 0.0
    return frac01, frac5, mm


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)

    start_best = best.copy()
    startR = R_of(start_best)
    print("base R=%.9f (N=%d)" % (startR, start_best.size))

    bestR = startR
    pre_sharp = best.copy()

    betas = np.logspace(4, 8, 6)
    pads = [0.10, 0.06, 0.04, 0.02]

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        improved = False

        # (1) exact tie polish
        if time.process_time() < deadline - 2.0:
            tlim = min(deadline - 1.0, time.process_time() + 6.0)
            pol = _full_polish(best, 400, tlim)
            rp = R_of(pol)
            if rp > bestR + 1e-12:
                best = pol; bestR = rp; improved = True
            print("cyc%d (1) R=%.9f" % (cycle, bestR))

        # (2) sharpening ladder
        for beta in betas:
            if time.process_time() >= deadline - 2.0:
                break
            tlim = min(deadline - 1.0, time.process_time() + 3.0)
            sm = _softmax_pass(best, beta, 200, tlim)
            if time.process_time() < deadline - 1.5:
                tlim2 = min(deadline - 0.8, time.process_time() + 3.0)
                sm2 = _full_polish(sm, 250, tlim2)
            else:
                sm2 = sm
            rs = R_of(sm2)
            if rs > bestR + 1e-12:
                best = sm2; bestR = rs; improved = True
        print("cyc%d (2) R=%.9f" % (cycle, bestR))

        # (3) peak-window ladder
        for pad in pads:
            if time.process_time() >= deadline - 2.0:
                break
            tlim = min(deadline - 1.0, time.process_time() + 3.0)
            w = _peak_window(best, pad, 250, tlim)
            rw = R_of(w)
            if rw > bestR + 1e-12:
                best = w; bestR = rw; improved = True
        if time.process_time() < deadline - 1.5:
            tlim = min(deadline - 0.8, time.process_time() + 3.0)
            pol = _full_polish(best, 250, tlim)
            rp = R_of(pol)
            if rp > bestR + 1e-12:
                best = pol; bestR = rp; improved = True
        print("cyc%d (3) R=%.9f" % (cycle, bestR))

        # (4) upsampling
        for factor in (2, 4):
            if time.process_time() >= deadline - 2.0:
                break
            if best.size * factor > 1000000:
                break
            up = _rescale(np.repeat(best, factor))
            tlim = min(deadline - 1.0, time.process_time() + 5.0)
            up = _full_polish(up, 300, tlim)
            for pad in (0.06, 0.03):
                if time.process_time() >= deadline - 2.0:
                    break
                tlim = min(deadline - 1.0, time.process_time() + 3.0)
                w = _peak_window(up, pad, 250, tlim)
                if R_of(w) > R_of(up):
                    up = w
            ru = R_of(up)
            if ru > bestR + 1e-12:
                best = up; bestR = ru; improved = True
                print("cyc%d (4) up x%d R=%.9f N=%d" % (cycle, factor, bestR, best.size))
                break

        # (5) block-coordinate pass
        if time.process_time() < deadline - 2.0:
            n = best.size
            rng = np.random.RandomState(cycle)
            nblocks = 8
            for _ in range(nblocks):
                if time.process_time() >= deadline - 2.0:
                    break
                bs = 32
                start_i = rng.randint(0, max(1, n - bs))
                free = np.arange(start_i, min(n, start_i + bs))
                tlim = min(deadline - 1.0, time.process_time() + 1.5)
                w = _lbfgs_block(best, free, 5, tlim)
                rw = R_of(w)
                if rw > bestR + 1e-12:
                    best = w; bestR = rw; improved = True
            print("cyc%d (5) R=%.9f" % (cycle, bestR))

        f01, f5, mm = _stats(best)
        print("cyc%d stats: frac0.1%%=%.4f frac5%%=%.4f max/mean=%.2f" % (cycle, f01, f5, mm))

        if not improved and cycle >= 2:
            break

    bestR = R_of(best)
    f01, f5, mm = _stats(best)
    print("final R=%.12f (start %.12f, N=%d) frac0.1%%=%.4f max/mean=%.2f"
          % (bestR, startR, best.size, f01, mm))

    if bestR > startR:
        return {"best": best, "alternative": pre_sharp}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    tie = Lf >= mx - 1e-12 * max(1.0, abs(mx))
    k = int(tie.sum())
    gLf = -dq / num
    gLf[tie] += (1.0 / mx) / k
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad_frac=0.1, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= 0.9995 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    stop = deadline - 2.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    def try_accept(cand, tag):
        nonlocal best, bestR
        if cand is None or cand.size == 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = _rescale(cand), r
            print("%s R=%.9f (gain %.2e)" % (tag, bestR, bestR - startR))
            return True
        return False

    round_i = 0
    while time.process_time() < stop:
        round_i += 1
        # (a) full-array exact tie
        if time.process_time() < stop:
            cand = _lbfgs_all_pos(best, 300, min(stop, deadline - 1.0), tie=True)
            try_accept(cand, "a%d tie" % round_i)

        # (b) block-sum by 2, polish at N/2, upsample
        if time.process_time() < stop and best.size % 2 == 0 and best.size >= 4:
            N = best.size
            hs = best.reshape(N // 2, 2).sum(axis=1)
            hs = _rescale(hs)
            cand_s = _lbfgs_all_pos(hs, 300, min(stop, deadline - 1.0), tie=True)
            up = _rescale(np.repeat(cand_s, 2))
            if try_accept(up, "b%d blk" % round_i):
                cand = _lbfgs_all_pos(best, 200, min(stop, deadline - 1.0), tie=True)
                try_accept(cand, "b%d pol" % round_i)

        # (c) high-beta sharpening ladder
        if time.process_time() < stop:
            for beta in np.logspace(5, 8, 4):
                if time.process_time() >= stop:
                    break
                cand = _lbfgs_all_pos(best, 150, min(stop, deadline - 1.0), beta=beta)
                if try_accept(cand, "c%d b%.0e" % (round_i, beta)):
                    cand = _lbfgs_all_pos(best, 200, min(stop, deadline - 1.0), tie=True)
                    try_accept(cand, "c%d tie" % round_i)

        # (d) peak-window ladder
        if time.process_time() < stop:
            for pad in [0.06, 0.04, 0.02, 0.01]:
                if time.process_time() >= stop:
                    break
                win = _peak_window(best, pad_frac=pad, extra=256)
                cand = _lbfgs_block(best, win, 250, min(stop, deadline - 1.0), tie=True)
                try_accept(cand, "d%d p%.2f" % (round_i, pad))
            if time.process_time() < stop:
                cand = _lbfgs_all_pos(best, 300, min(stop, deadline - 1.0), tie=True)
                try_accept(cand, "d%d fin" % round_i)

        # (e) one 2x lift
        if time.process_time() < stop and best.size * 2 <= 1000000:
            up = _rescale(np.repeat(best, 2))
            if try_accept(up, "e%d lift" % round_i):
                cand = _lbfgs_all_pos(best, 200, min(stop, deadline - 1.0), tie=True)
                try_accept(cand, "e%d pol" % round_i)

        if time.process_time() >= stop:
            break

    # final safety polish
    if time.process_time() < deadline - 0.8:
        cand = _lbfgs_all_pos(best, 300, deadline - 0.4, tie=True)
        try_accept(cand, "final")

    print("final R=%.9f N=%d (start %.9f, gain %.2e)" %
          (bestR, best.size, startR, bestR - startR))
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, free, maxiter, deadline):
    """L-BFGS-B in log-space on the free coordinates (keeps positivity)."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-10 * hmax if hmax > 0 else 1e-10
    u0 = np.log(np.clip(h[active], floor, None))

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _upsample(h, k):
    n = h.size
    m = n * k
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(m) + 0.5) / m
    return np.interp(x_new, x_old, h, left=h[0], right=h[-1])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            keep = _rescale(base)
            startR = R_of(keep)
        else:
            keep, startR = None, 0.0
    else:
        keep, startR = None, 0.0

    if keep is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        keep = _rescale(h)
        startR = R_of(keep)

    best = keep.copy()
    bestR = startR
    print("base R=%.9f (N=%d) frac5=%.4f"
          % (bestR, best.size, _frac_near_max(best, 0.95)))

    # Phase 1: full-array log-space polish.
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_log(best, np.arange(best.size), 400,
                        min(deadline - 1.0, time.process_time() + 18.0))
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("phase1 full R=%.9f" % bestR)

    # Phase 2: peak-window log-space polish.
    if time.process_time() < deadline - 2.0:
        win = _peak_window(best, pad_frac=0.05, extra=256)
        ht = _lbfgs_log(best, win, 400,
                        min(deadline - 1.0, time.process_time() + 14.0))
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("phase2 win R=%.9f" % bestR)

    # Phase 3: upsample to higher resolution and re-optimize (log-space).
    for k in (2, 2):
        if time.process_time() >= deadline - 5.0 or best.size * k > 1000000:
            break
        up = _rescale(_upsample(best, k))
        win = _peak_window(up, pad_frac=0.1, extra=384)
        ht = _lbfgs_log(up, win, 350,
                        min(deadline - 2.0, time.process_time() + 12.0))
        r = R_of(ht)
        print("phase3 %dx win R=%.9f (N=%d)" % (k, r, ht.size))
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    # Phase 4: alternating window polish, log-space, until deadline.
    while time.process_time() < deadline - 1.0:
        rem = deadline - time.process_time()
        chunk = min(rem * 0.6, 8.0)
        win = _peak_window(best, pad_frac=0.02, extra=128)
        ht = _lbfgs_log(best, win, 400,
                        min(deadline - 0.5, time.process_time() + chunk))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        else:
            break

    print("final R=%.9f (start %.9f, N=%d, frac5=%.4f)"
          % (bestR, startR, best.size, _frac_near_max(best, 0.95)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

