    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def _project_tangent(v, active):
    if v.size == 0:
        return v
    return v - v.mean()


def _newton_cg(h, deadline, max_outer=30, verbose=True):
    h = _rescale(np.clip(h, 0, None))
    Rcur = R_of(h)
    best = h.copy()
    bestR = Rcur
    neg_curv_total = 0
    accepted_total = 0

    for outer in range(max_outer):
        if time.process_time() >= deadline - 1.0:
            break
        active = np.flatnonzero(h > 1e-12)
        if active.size < 2:
            break
        val, g = _fun_grad_tie(h)
        gA = g[active].copy()
        gA = _project_tangent(gA, active)
        gnorm = float(np.linalg.norm(gA))
        if verbose:
            print("  NCG outer %d: |g_proj|=%.3e R=%.12f" % (outer, gnorm, Rcur))
        if gnorm < 1e-11:
            break

        hA = h[active].copy()
        hnorm = float(np.linalg.norm(hA)) + 1e-30

        def Hv(v):
            v = _project_tangent(v, active)
            vnorm = float(np.linalg.norm(v))
            if vnorm < 1e-30:
                return np.zeros_like(v)
            eps = 1e-6 * hnorm / vnorm
            hp = h.copy()
            hp[active] = np.clip(hA + eps * v, 0.0, None)
            hm = h.copy()
            hm[active] = np.clip(hA - eps * v, 0.0, None)
            _, gp = _fun_grad_tie(hp)
            _, gm = _fun_grad_tie(hm)
            Hv_raw = (gp[active] - gm[active]) / (2.0 * eps)
            return _project_tangent(Hv_raw, active)

        delta = max(1e-3 * hnorm, 1e-6)
        x = np.zeros_like(gA)
        r = -gA.copy()
        p = r.copy()
        rr = float(r @ r)
        tol = min(0.5, np.sqrt(gnorm)) * gnorm
        neg_curv = False
        for it in range(min(300, active.size)):
            if time.process_time() >= deadline - 0.8:
                break
            if np.sqrt(rr) < tol:
                break
            Hp = Hv(p)
            pHp = float(p @ Hp)
            if pHp <= 1e-14 * (float(p @ p) + 1e-30):
                neg_curv = True
                pp = float(p @ p)
                if pp > 1e-30:
                    alpha = np.sqrt(delta * delta / pp)
                    x = x + alpha * p
                break
            alpha = rr / pHp
            xnew = x + alpha * p
            if float(xnew @ xnew) > delta * delta:
                pp = float(p @ p)
                xp = float(x @ p)
                disc = xp * xp + pp * (delta * delta - float(x @ x))
                if disc < 0:
                    disc = 0.0
                tau = (-xp + np.sqrt(disc)) / (pp + 1e-30)
                x = x + tau * p
                break
            x = xnew
            r = r - alpha * Hp
            rr_new = float(r @ r)
            beta = rr_new / (rr + 1e-30)
            p = r + beta * p
            rr = rr_new

        if neg_curv:
            neg_curv_total += 1

        step = x
        step_norm = float(np.linalg.norm(step))
        if step_norm < 1e-14:
            step = -gA / (gnorm + 1e-30) * min(1e-3 * hnorm, delta)
            step_norm = float(np.linalg.norm(step))

        accepted = False
        for ls in range(40):
            if time.process_time() >= deadline - 0.8:
                break
            t = 0.5 ** ls
            htry = h.copy()
            htry[active] = np.clip(hA + t * step, 0.0, None)
            htry = _rescale(htry)
            rtry = R_of(htry)
            if rtry > Rcur + 1e-16:
                h = htry
                Rcur = rtry
                accepted = True
                accepted_total += 1
                if Rcur > bestR:
                    best = h.copy()
                    bestR = Rcur
                break
        if not accepted:
            break

    if verbose:
        print("  NCG done: neg_curv=%d accepted=%d bestR=%.12f" %
              (neg_curv_total, accepted_total, bestR))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Main new attempt: projected Newton-CG on active support ----
    if time.process_time() < deadline - 8.0:
        ncg_deadline = min(deadline - 6.0,
                           time.process_time() + budget_seconds * 0.55)
        nh, nR = _newton_cg(best, ncg_deadline, max_outer=40)
        if nR > bestR + 1e-15:
            best, bestR = nh.copy(), nR

    # ---- Coarse-to-fine L-BFGS polishing ----
    for Q in (4, 2, 1):
        if time.process_time() >= deadline - 5.0:
            break
        if best.size % Q != 0:
            continue
        qh = best if Q == 1 else _coarsen(best, Q)
        if qh is None or qh.size < 32:
            continue
        qh = _rescale(qh)
        qR = R_of(qh)
        best_qh = qh.copy(); best_qR = qR
        for _ in range(3):
            if time.process_time() >= deadline - 4.0:
                break
            tlim = min(deadline - 3.5, time.process_time() + 1.5)
            cand = _lbfgs_block(best_qh, np.arange(best_qh.size), 150, tlim)
            r = R_of(cand)
            if r > best_qR:
                best_qh, best_qR = cand.copy(), r
            else:
                break
        ph = best_qh if Q == 1 else _prolongate(best_qh, Q)
        pr = R_of(ph)
        if pr > bestR + 1e-15:
            best, bestR = ph.copy(), pr

    # ---- Final full-resolution polish until deadline ----
    while time.process_time() < deadline - 0.8:
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.4, time.process_time() + 3.0))
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        else:
            break

    if bestR < startR:
        best = start_best
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best}

