    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta, window):
    # soft peak penalty: penalise knots near max via -beta * sum(exp(beta*(L-Lmax)))
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    # soft-max style: weight knots within window fraction of max
    thr = mx * (1.0 - window)
    idx = np.flatnonzero(Lf >= thr)
    if idx.size > 0:
        # push these down: gradient of log(mx) approx via softmax
        w = np.exp(beta * (Lf[idx] - mx))
        w = w / w.sum()
        gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0, None)
    return _rescale(h2)


def _lbfgs_beta(h0, beta, window, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = _rescale(np.clip(h0, 0, None))
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        if hh.sum() <= 0:
            return 1e18, np.zeros(n)
        return _fun_grad_beta(hh, beta, window)

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, h.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0, None))


def _riemann_lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = _rescale(np.clip(h0, 0, None))
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        if hh.sum() <= 0:
            return 1e18, np.zeros(n)
        val, g = _fun_grad_tie(hh)
        denom = float(np.dot(hh, hh))
        if denom > 0:
            g = g - (float(np.dot(g, hh)) / denom) * hh
        return val, g

    cb = _make_cb(deadline - 0.15)
    x0 = h.copy()
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0, None))


def _prolongate(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N) / N
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(n + 1, dtype=float))
    hh = np.clip(np.diff(out), 0, None)
    if hh.sum() <= 0:
        return np.ones(N) / N
    return hh


def _rasterise(widths, heights):
    N = int(widths.sum())
    h = np.empty(N, dtype=float)
    pos = 0
    for w, a in zip(widths, heights):
        h[pos:pos + w] = a
        pos += w
    return h


def _collapse(h, nb):
    n = h.size
    edges = np.linspace(0, n, nb + 1).astype(int)
    widths = np.diff(edges)
    heights = np.empty(nb)
    for i in range(nb):
        lo, hi = edges[i], edges[i + 1]
        if hi > lo:
            heights[i] = h[lo:hi].mean()
        else:
            heights[i] = 0.0
    return widths.astype(int), heights


def _polish_full(h, deadline, maxiter):
    hp = _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=True)
    if R_of(hp) >= R_of(h):
        return hp
    return h


def _width_search(h, NB, N, deadline, rng, maxiter_polish=80):
    w, a = _collapse(h, NB)
    w = np.maximum(1, w.astype(int))
    # fix sum
    diff = N - w.sum()
    i = 0
    while diff != 0 and i < 1000000:
        j = i % NB
        if diff > 0:
            w[j] += 1; diff -= 1
        elif w[j] > 1:
            w[j] -= 1; diff += 1
        i += 1

    cur_h = _rescale(_rasterise(w, a))
    hp = _lbfgs_block(cur_h, np.arange(N), maxiter_polish, deadline, tie=True)
    cur_h = hp
    curR = R_of(cur_h)
    best_h = cur_h.copy()
    bestR = curR
    accepted = 0
    moves = 0
    since_full = 0

    while time.process_time() < deadline - 1.0:
        moves += 1
        w2 = w.copy()
        nmoves = int(rng.integers(1, 4))
        for _ in range(nmoves):
            j = int(rng.integers(0, NB))
            d = int(rng.choice([-1, 1]) * rng.integers(1, 9))
            k = (j + 1) % NB
            if d > 0:
                if w2[j] - d >= 1:
                    w2[j] -= d; w2[k] += d
            else:
                if w2[k] + d >= 1:
                    w2[j] -= d; w2[k] += d
        if rng.random() < 0.15:
            j = int(rng.integers(0, NB))
            if w2[j] >= 4:
                half = w2[j] // 2
                k = (j + 1) % NB
                w2[j] -= half; w2[k] += half
        if w2.sum() != N or np.any(w2 < 1):
            continue

        h2 = _rescale(_rasterise(w2, a))
        hp = _lbfgs_block(h2, np.arange(N), maxiter_polish, deadline - 0.5, tie=True)
        rp = R_of(hp)
        if rp > curR + 1e-12:
            w = w2
            a = _collapse(hp, NB)[1]
            cur_h, curR = hp, rp
            accepted += 1
            since_full += 1
            if rp > bestR:
                best_h, bestR = hp.copy(), rp
            if since_full >= 8 and time.process_time() < deadline - 3.0:
                since_full = 0
                hf = _riemann_lbfgs(cur_h, 80, deadline - 1.0)
                rf = R_of(hf)
                if rf > curR:
                    cur_h, curR = hf, rf
                    if rf > bestR:
                        best_h, bestR = hf.copy(), rf
    return best_h, bestR, accepted, moves


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240607)

    startR = 0.0
    start_h = None
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            start_h = _rescale(s)
            startR = R_of(start_h)
    if start_h is None:
        start_h = _rescale(np.ones(3281))
        startR = R_of(start_h)

    best_h = start_h.copy()
    bestR = startR
    print("start R=%.9f N=%d" % (startR, start_h.size))

    # Level 1: lift to N=6562
    N1 = 6562
    h1 = _rescale(_prolongate(start_h, N1))
    r1 = R_of(h1)
    print("lift N=%d R=%.9f" % (N1, r1))

    # Full tie L-BFGS
    hp = _lbfgs_block(h1, np.arange(N1), 300, deadline - 1.0, tie=True)
    rp = R_of(hp)
    if rp > r1:
        h1, r1 = hp, rp
        print("polish N=%d R=%.9f" % (N1, r1))

    # beta passes
    for beta, win in [(1e4, 0.01), (1e6, 0.001)]:
        if time.process_time() < deadline - 3.0:
            hb = _lbfgs_beta(h1, beta, win, 200, deadline - 1.0)
            rb = R_of(hb)
            if rb > r1:
                h1, r1 = hb, rb
                print("beta %.0e N=%d R=%.9f" % (beta, N1, r1))

    if r1 > bestR:
        best_h, bestR = h1.copy(), r1

    # Width search at N=6562 with 128 blocks
    if time.process_time() < deadline - 5.0:
        hw, rw, acc, mv = _width_search(h1, 128, N1, deadline * 0.6 + t0 * 0.4 if False else (t0 + (deadline - t0) * 0.55), rng, maxiter_polish=80)
        print("width N=%d R=%.9f acc=%d/%d" % (N1, rw, acc, mv))
        if rw > bestR:
            best_h, bestR = hw.copy(), rw
            h1 = hw.copy()

    # Level 2: lift to N=13124
    N2 = 13124
    if time.process_time() < deadline - 8.0:
        h2 = _rescale(_prolongate(best_h, N2))
        r2 = R_of(h2)
        print("lift N=%d R=%.9f" % (N2, r2))
        hp = _lbfgs_block(h2, np.arange(N2), 300, deadline - 1.0, tie=True)
        rp = R_of(hp)
        if rp > r2:
            h2, r2 = hp, rp
            print("polish N=%d R=%.9f" % (N2, r2))
        for beta, win in [(1e4, 0.01), (1e6, 0.001)]:
            if time.process_time() < deadline - 3.0:
                hb = _lbfgs_beta(h2, beta, win, 200, deadline - 1.0)
                rb = R_of(hb)
                if rb > r2:
                    h2, r2 = hb, rb
                    print("beta %.0e N=%d R=%.9f" % (beta, N2, r2))
        if r2 > bestR:
            best_h, bestR = h2.copy(), r2
            h2_best = h2.copy()
        else:
            h2_best = best_h.copy()

        # Width search at N=13124 with 256 blocks
        if time.process_time() < deadline - 5.0:
            hw, rw, acc, mv = _width_search(h2_best, 256, N2, deadline - 0.5, rng, maxiter_polish=60)
            print("width N=%d R=%.9f acc=%d/%d" % (N2, rw, acc, mv))
            if rw > bestR:
                best_h, bestR = hw.copy(), rw

    # Final polish
    if time.process_time() < deadline - 0.5:
        hp = _riemann_lbfgs(best_h, 200, deadline)
        rp = R_of(hp)
        if rp > bestR:
            best_h, bestR = hp, rp

    if bestR < startR:
        best_h = start_h
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best_h.size))

    result = {"best": best_h}
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolong(h, Nnew):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0:
        return np.ones(Nnew)
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h))) / s
    u = np.linspace(0.0, 1.0, N + 1)
    v = np.linspace(0.0, 1.0, Nnew + 1)
    newC = np.interp(v, u, C)
    out = np.diff(newC)
    return _rescale(np.clip(out, 0, None))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.12, 0.08, 0.05, 0.03), iters=300):
    r0 = R_of(h)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3)
        r = R_of(ht)
        if r > r0 + 1e-14:
            h, r0 = ht, r
    return h, r0


def _sharpen(h, bestR, deadline):
    # Full-gradient polish then peak-window refine
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(h, np.arange(h.size), 600, deadline - 0.3)
        r = R_of(ht)
        if r > bestR + 1e-13:
            h, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        h, bestR = _peak_ladder(h, deadline - 0.3)
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = 0.0

    # ---- Strategy A: incremental upsampling ladder ----
    # Progressively refine at 1x, 2x, 4x. Each level's result seeds the next.
    # Upsampling changes the discretization so L-BFGS can find new directions.
    h = _sharpen(best, bestR, min(deadline - 1.0,
                                  time.process_time() + budget_seconds * 0.18))
    r = R_of(h)
    if r > bestR + 1e-13:
        best, bestR = h.copy(), r
    print("level1 R=%.7f (N=%d)" % (bestR, best.size))

    for factor in (2, 2):
        if time.process_time() >= deadline - 3.0:
            break
        if best.size * factor > 900000:
            break
        hu = _prolong(best, best.size * factor)
        ru = R_of(hu)
        slice_end = min(deadline - 1.0,
                        time.process_time() + budget_seconds * 0.20)
        hu, ru = _sharpen(hu, ru, slice_end)
        if ru > bestR + 1e-13:
            best, bestR = hu.copy(), ru
        if alt_best is None or ru > alt_bestR:
            alt_best, alt_bestR = hu, ru
        print("upsample x%d R=%.7f (N=%d)" % (factor, ru, hu.size))

    # ---- Strategy B: peak-window intensity at current resolution ----
    if time.process_time() < deadline - 1.5:
        slice_end = min(deadline - 1.0,
                        time.process_time() + budget_seconds * 0.15)
        h, r = _peak_ladder(best, slice_end, pads=(0.20, 0.12, 0.06, 0.03, 0.02),
                            iters=400)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
        print("peak-ladder R=%.7f" % bestR)

    # ---- Strategy C: full-gradient final polish, largest N ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_block(best, np.arange(best.size), 4000, deadline - 0.4)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt_best is not None:
        print("alt R=%.7f (N=%d)" % (alt_bestR, alt_best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_best is not None and alt_bestR > start_bestR - 0.05:
        out["alternative"] = alt_best
    return out

