def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, fg=None, logx=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    if fg is None:
        fg = _fun_grad_tie

    if logx:
        pos = active[h[active] > 0]
        if pos.size == 0:
            return h0
        hmax = h.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        u0 = np.log(np.clip(h[pos], floor, None))

        def f(u):
            hh = h.copy()
            hh[pos] = np.exp(u)
            val, g = fg(hh)
            return val, g[pos] * hh[pos]

        cb = _make_cb(deadline - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * pos.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return h0
        if res is None:
            return h0
        h2 = h.copy()
        h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
        return _rescale(h2)

    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            return p, c
    return 1, h


def _knot_rows(c, p, tie_idx):
    n = c.size
    h = np.repeat(c, p)
    nk = h.size + 1
    G = np.empty((len(tie_idx), n))
    for r, j in enumerate(tie_idx):
        gLf = np.zeros(nk)
        gLf[j] = 1.0
        gh = _backprop(gLf, h)
        G[r] = gh.reshape(n, p).sum(axis=1)
    return G


def _nullspace_step(c, p, tie_idx, rng, scales, G=None, GGt_inv=None):
    if G is None:
        G = _knot_rows(c, p, tie_idx)
    if GGt_inv is None:
        GGt = G @ G.T
        GGt[np.diag_indices_from(GGt)] += 1e-12
        try:
            GGt_inv = np.linalg.inv(GGt)
        except np.linalg.LinAlgError:
            return None, None, G, GGt_inv
    try:
        v = rng.standard_normal(c.size)
        Gv = G @ v
        x = GGt_inv @ Gv
        vproj = v - G.T @ x
    except np.linalg.LinAlgError:
        return None, None, G, GGt_inv
    nv = np.linalg.norm(vproj)
    if nv <= 0:
        return None, None, G, GGt_inv
    vproj /= nv
    base = c.mean()
    best_c = None
    best_r = R_of(np.repeat(c, p))
    for s in scales:
        cn = np.clip(c + s * base * vproj, 0.0, None)
        if cn.sum() <= 0:
            continue
        r = R_of(np.repeat(cn, p))
        if r > best_r + 1e-15:
            best_r = r
            best_c = cn
    return best_c, best_r, G, GGt_inv


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase N (full-h nullspace): ties exploration ----
    n_end = t0 + budget_seconds * 0.80
    h_cur = best.copy()
    h_curR = bestR
    Lf = _knots(h_cur)
    mx = Lf.max()
    tie_idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    print("PhaseN full-h ties=%d R=%.9f" % (tie_idx.size, h_curR))

    scales = [1e-6, 3e-6, 1e-5, 3e-5, 1e-4, 3e-4, 1e-3, 3e-3]
    nrng = np.random.default_rng(999)
    nacc = 0
    nrounds = 0
    G = None
    GGt_inv = None
    if tie_idx.size > 0:
        try:
            G = _knot_rows(h_cur, 1, tie_idx)
            if G.shape != (tie_idx.size, h_cur.size):
                G = None
            else:
                GGt = G @ G.T
                GGt[np.diag_indices_from(GGt)] += 1e-10
                GGt_inv = np.linalg.inv(GGt)
        except Exception:
            G = None
            GGt_inv = None

    while nrounds < 40 and time.process_time() < n_end - 1.5 and GGt_inv is not None:
        nrounds += 1
        v = nrng.standard_normal(h_cur.size)
        Gv = G @ v
        x = GGt_inv @ Gv
        vproj = v - G.T @ x
        nv = np.linalg.norm(vproj)
        if nv <= 0:
            continue
        vproj /= nv
        base_mean = h_cur.mean()
        best_try = None
        best_try_r = h_curR
        for s in scales:
            hn = np.clip(h_cur + s * base_mean * vproj, 0.0, None)
            if hn.sum() <= 0:
                continue
            r = R_of(hn)
            if r > best_try_r + 1e-12:
                best_try_r = r
                best_try = hn
        if best_try is not None:
            h_cur = best_try
            h_curR = best_try_r
            nacc += 1
            allidx = np.arange(h_cur.size)
            dl = min(t0 + budget_seconds * 0.85,
                     time.process_time() + 2.0)
            h_pol = _lbfgs(h_cur, allidx, 60, dl, logx=True)
            rp = R_of(h_pol)
            if rp > h_curR + 1e-15:
                h_cur = h_pol
                h_curR = rp
            if h_curR > bestR + 1e-15:
                best = _rescale(h_cur.copy())
                bestR = h_curR
            print("PhaseN round=%d acc=%d R=%.9f" % (nrounds, nacc, bestR))
        else:
            if nrounds % 5 == 0:
                print("PhaseN round=%d acc=%d R=%.9f (no accept)"
                      % (nrounds, nacc, bestR))

    print("PhaseN done rounds=%d acc=%d R=%.9f" % (nrounds, nacc, bestR))

    # ---- Phase E: final peak polish ----
    c_end = t0 + budget_seconds * 0.99
    for pad in (0.03, 0.015):
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, logx in ((1e7, False), (0.0, True), (0.0, False)):
            if time.process_time() >= c_end - 0.8:
                break
            fg = (lambda hh, b=beta: _fun_grad_soft(hh, b)) if beta > 0 else _fun_grad_tie
            ht = _lbfgs(best, win, 300,
                        min(c_end - 0.5, time.process_time() + 3.0),
                        fg=fg, logx=logx)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = (_fun_grad(hh) if beta is None else _fun_grad_sm(hh, beta))
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _restrict(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, sigma):
    if sigma <= 0:
        return h
    n = h.size
    r = max(1, int(np.ceil(3 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    if n > 4000:
        return np.clip(fftconvolve(h, k, mode='same'), 0, None)
    return np.clip(np.convolve(h, k, mode='same'), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size

    # NEW IDEA: coarsen the current best to a lower resolution, optimise
    # there (cheap, many iterations, escapes fine-scale local minima),
    # then prolongate back.  This is a proper multigrid-style move that
    # the original never did.
    alt_best = best.copy()
    altR = bestR

    if time.process_time() < deadline - 8.0:
        # try several coarse resolutions
        for N_small in (1024, 2048, 4096):
            if time.process_time() >= deadline - 6.0:
                break
            if N_small >= N:
                continue
            hc = _restrict(best, N_small)
            # soft-max anneal at coarse level
            for beta in (500.0, 120.0, 30.0, 8.0):
                if time.process_time() >= deadline - 5.0:
                    break
                hc = _lbfgs_log(hc, 400, deadline, beta=beta)
            hc = _lbfgs_log(hc, 600, deadline)
            # prolongate back to full resolution
            hf = _prolongate(hc, N)
            r = R_of(hf)
            if r > altR:
                altR = r
                alt_best = hf
                print("multigrid N=%d -> R=%.7f" % (N_small, altR))

    # Now polish the (possibly improved) full-resolution candidate.
    if altR > bestR + 1e-15:
        best, bestR = alt_best, altR
        print("adopt multigrid R=%.7f" % bestR)

    # smoothed full-resolution pass
    if time.process_time() < deadline - 5.0:
        h = best.copy()
        for beta in (30.0, 8.0, 2.0):
            if time.process_time() >= deadline - 4.0:
                break
            h = _lbfgs_log(h, 400, deadline, beta=beta)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                print("sm beta=%.0f R=%.7f" % (beta, bestR))

    # wide peak polish
    if time.process_time() < deadline - 4.0:
        lo, hi = _peak_region(best, tol=0.995)
        span = hi - lo
        lo2 = max(0, lo - max(8, span // 2))
        hi2 = min(N - 1, hi + max(8, span // 2))
        free = np.arange(lo2, hi2 + 1)
        h = _lbfgs_block(best, free, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("wide-peak R=%.7f" % bestR)

    # multi-scale window polish
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.55, 32)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.2f) R=%.7f" % (frac, bestR))

    # final polish loop
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if altR > R_of(np.asarray(start, dtype=float)) if start is not None else False:
        pass
    if start is not None and alt_best is not None and alt_best.size == np.asarray(start).size:
        if R_of(alt_best) > R_of(np.asarray(start, dtype=float)) - 1e-12 and alt_best is not None:
            # alt is genuinely different construction (from multigrid); offer as alternative
            return {"best": best, "alternative": alt_best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_con(h, theta, mu, rho):
    """Constrained formulation: mass fixed at 1 (u = h/s), maximize L2 term
    subject to ||f*f||_inf <= theta via augmented Lagrangian."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    u = h / s
    num, dq, Lf = _num_and_dq(u)
    mx = Lf.max()
    gLf = -dq / num
    viol = max(0.0, mx - theta)
    if mx > theta:
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        w = 1.0 / idx.size
        gLf[idx] += (mu + rho * viol) * w / mx
    grad_u = _backprop(gLf, u)
    uu = (u * u).sum()
    if uu > 0:
        proj = (u * grad_u).sum() / uu
        grad_u = grad_u - proj * u
    grad = grad_u / s
    val = -np.log(num) + mu * viol + 0.5 * rho * viol * viol
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_con(h0, free, maxiter, deadline, theta, mu, rho):
    """L-BFGS-B in log-space on active cells with the constrained gradient."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = np.log(np.clip(h[active], 1e-30, None))

    def f(x):
        hh = h.copy()
        hh[active] = np.exp(np.clip(x, -60.0, 60.0))
        val, g = _fun_grad_con(hh, theta, mu, rho)
        ga = g[active] * hh[active]
        return val, ga

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -60.0, 60.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _compress(h, n):
    if h.size % n == 0:
        return h.reshape(-1, h.size // n).mean(axis=1)
    return np.interp(np.linspace(0, h.size - 1, n),
                     np.arange(h.size), h)


def _expand(c, n):
    if n % c.size == 0:
        return np.repeat(c, n // c.size)
    return np.interp(np.linspace(0, c.size - 1, n),
                     np.arange(c.size), c)


def _block_fun_grad(c, BLK, beta=0.0):
    h = np.repeat(c, BLK)
    if beta > 0:
        val, g = _fun_grad_beta(h, beta)
    else:
        val, g = _fun_grad_tie(h)
    gc = g.reshape(-1, BLK).sum(axis=1)
    return val, gc


def _newton_round(c0, BLK, deadline, maxiter=60, beta=0.0):
    c = np.asarray(c0, dtype=float).copy()
    if time.process_time() >= deadline - 0.5:
        return c0

    def f(cv):
        return _block_fun_grad(cv, BLK, beta)

    def hessp(cv, v):
        nv = np.linalg.norm(v)
        if nv == 0:
            return np.zeros_like(v)
        eps = 1e-6 * max(1.0, np.max(np.abs(cv))) / nv
        _, gp = _block_fun_grad(cv + eps * v, BLK, beta)
        _, gm = _block_fun_grad(cv - eps * v, BLK, beta)
        return (gp - gm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, c, jac=True, method='trust-ncg', hessp=hessp,
                       callback=cb,
                       options={'maxiter': maxiter, 'gtol': 1e-18,
                                'xtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return res.x


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: coarse Newton on block-mean at moderate resolution ----
    if time.process_time() < deadline - 5.0:
        for target_n in (2048, 4096, 1024):
            if time.process_time() >= deadline - 4.0:
                break
            n = min(target_n, best.size)
            c = _compress(best, n)
            c = _rescale(np.clip(c, 1e-30, None))
            BLK = max(1, best.size // n)
            sub_deadline = min(deadline - 2.0, time.process_time() + 5.0)
            for beta in (1e4, 1e5, 0.0):
                c_new = _newton_round(c, BLK, sub_deadline, maxiter=40, beta=beta)
                if c_new is None:
                    break
                c_new = _rescale(np.clip(c_new, 1e-30, None))
                if R_of(_expand(c_new, best.size)) > R_of(_expand(c, best.size)):
                    c = c_new
                if time.process_time() >= sub_deadline - 0.5:
                    break
            full = _rescale(_expand(c, best.size))
            r = R_of(full)
            if r > bestR + 1e-15:
                best, bestR = full, r
                print("coarse-Newton n=%d R=%.9f" % (n, bestR))

    # ---- Phase 2: full-resolution tie L-BFGS polish ----
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_block(best, np.arange(best.size), 300,
                          min(deadline - 1.5, time.process_time() + 6.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("full tie polish R=%.9f" % bestR)

    # ---- Phase 3: peak-window tie polishes ----
    for pad in (0.08, 0.05, 0.03, 0.02, 0.01):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        for beta in (1e7, 1e5, 0.0):
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(deadline - 0.6,
                                  time.process_time() + 2.5),
                              beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---- Phase 4: NEW constrained-formulation annealing loop ----
    # Fix mass at 1, maximize L2 term subject to ||f*f||_inf <= theta.
    # theta annealed down; augmented Lagrangian multiplier mu, penalty rho.
    if time.process_time() < deadline - 2.0:
        Lf = _knots(best)
        theta = Lf.max()
        mu = 0.0
        rho = 10.0
        con_best = best.copy()
        con_bestR = bestR
        active = np.arange(best.size)
        for rnd in range(40):
            if time.process_time() >= deadline - 1.5:
                break
            sub_deadline = min(deadline - 1.5,
                               time.process_time() + max(0.5, (deadline - time.process_time()) / 4.0))
            cand = _lbfgs_con(con_best, active, 60, sub_deadline,
                              theta, mu, rho)
            # exact tie-averaged polish
            if time.process_time() < sub_deadline - 0.3:
                cand = _lbfgs_block(cand, active, 40,
                                    min(sub_deadline, time.process_time() + 1.0))
            # peak-window polish
            if time.process_time() < sub_deadline - 0.2:
                win = _peak_window(cand, pad_frac=0.03, extra=128)
                cand = _lbfgs_block(cand, win, 40,
                                    min(sub_deadline, time.process_time() + 0.8))
            r = R_of(cand)
            Lc = _knots(cand)
            mxc = Lc.max()
            viol = max(0.0, mxc - theta)
            if r > con_bestR + 1e-13:
                con_best, con_bestR = cand.copy(), r
                if r > bestR + 1e-15:
                    best, bestR = cand.copy(), r
                print("con rnd=%d theta=%.6f viol=%.2e R=%.9f" %
                      (rnd, theta, viol, con_bestR))
            theta *= (1.0 - 2e-3)
            mu += rho * viol
            rho = min(2.0 * rho, 1e6)

    # ---- Phase 5: final full-resolution polish with remaining time ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_block(best, np.arange(best.size), 500,
                          deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("final polish R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        alt = _rescale(_interp_lift(np.clip(best, 0, None)))
        altR = R_of(alt)
        if altR > bestR:
            result["best"] = alt
            result["alternative"] = best
        else:
            result["alternative"] = alt
    return result

