            return np.zeros_like(v)
        eps = 1e-6 * max(1.0, np.max(np.abs(cv))) / nv
        _, gp = _block_fun_grad(cv + eps * v, BLK, beta)
        _, gm = _block_fun_grad(cv - eps * v, BLK, beta)
        return (gp - gm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, c, jac=True, method='trust-ncg', hessp=hessp,
                       callback=cb,
                       options={'maxiter': maxiter, 'gtol': 1e-18,
                                'xtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return res.x


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: coarse Newton on block-mean at moderate resolution ----
    if time.process_time() < deadline - 5.0:
        for target_n in (2048, 4096, 1024):
            if time.process_time() >= deadline - 4.0:
                break
            n = min(target_n, best.size)
            c = _compress(best, n)
            c = _rescale(np.clip(c, 1e-30, None))
            BLK = max(1, best.size // n)
            sub_deadline = min(deadline - 2.0, time.process_time() + 5.0)
            for beta in (1e4, 1e5, 0.0):
                c_new = _newton_round(c, BLK, sub_deadline, maxiter=40, beta=beta)
                if c_new is None:
                    break
                c_new = _rescale(np.clip(c_new, 1e-30, None))
                if R_of(_expand(c_new, best.size)) > R_of(_expand(c, best.size)):
                    c = c_new
                if time.process_time() >= sub_deadline - 0.5:
                    break
            full = _rescale(_expand(c, best.size))
            r = R_of(full)
            if r > bestR + 1e-15:
                best, bestR = full, r
                print("coarse-Newton n=%d R=%.9f" % (n, bestR))

    # ---- Phase 2: full-resolution tie L-BFGS polish ----
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_block(best, np.arange(best.size), 300,
                          min(deadline - 1.5, time.process_time() + 6.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("full tie polish R=%.9f" % bestR)

    # ---- Phase 3: peak-window tie polishes ----
    for pad in (0.08, 0.05, 0.03, 0.02, 0.01):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        for beta in (1e7, 1e5, 0.0):
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(deadline - 0.6,
                                  time.process_time() + 2.5),
                              beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---- Phase 4: NEW constrained-formulation annealing loop ----
    # Fix mass at 1, maximize L2 term subject to ||f*f||_inf <= theta.
    # theta annealed down; augmented Lagrangian multiplier mu, penalty rho.
    if time.process_time() < deadline - 2.0:
        Lf = _knots(best)
        theta = Lf.max()
        mu = 0.0
        rho = 10.0
        con_best = best.copy()
        con_bestR = bestR
        active = np.arange(best.size)
        for rnd in range(40):
            if time.process_time() >= deadline - 1.5:
                break
            sub_deadline = min(deadline - 1.5,
                               time.process_time() + max(0.5, (deadline - time.process_time()) / 4.0))
            cand = _lbfgs_con(con_best, active, 60, sub_deadline,
                              theta, mu, rho)
            # exact tie-averaged polish
            if time.process_time() < sub_deadline - 0.3:
                cand = _lbfgs_block(cand, active, 40,
                                    min(sub_deadline, time.process_time() + 1.0))
            # peak-window polish
            if time.process_time() < sub_deadline - 0.2:
                win = _peak_window(cand, pad_frac=0.03, extra=128)
                cand = _lbfgs_block(cand, win, 40,
                                    min(sub_deadline, time.process_time() + 0.8))
            r = R_of(cand)
            Lc = _knots(cand)
            mxc = Lc.max()
            viol = max(0.0, mxc - theta)
            if r > con_bestR + 1e-13:
                con_best, con_bestR = cand.copy(), r
                if r > bestR + 1e-15:
                    best, bestR = cand.copy(), r
                print("con rnd=%d theta=%.6f viol=%.2e R=%.9f" %
                      (rnd, theta, viol, con_bestR))
            theta *= (1.0 - 2e-3)
            mu += rho * viol
            rho = min(2.0 * rho, 1e6)

    # ---- Phase 5: final full-resolution polish with remaining time ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_block(best, np.arange(best.size), 500,
                          deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("final polish R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        alt = _rescale(_interp_lift(np.clip(best, 0, None)))
        altR = R_of(alt)
        if altR > bestR:
            result["best"] = alt
            result["alternative"] = best
        else:
            result["alternative"] = alt
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, free, maxiter, deadline, cvar_q=None):
    """Optimize log-heights on `free` indices. cvar_q None -> tie objective."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    floor = 1e-12 * max(h.max(), 1e-30)
    u0 = np.log(np.clip(h[active], floor, None))
    fg = (lambda hh: _fun_grad_cvar(hh, cvar_q)) if cvar_q is not None else _fun_grad_tie

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size
    allidx = np.arange(N)

    # Stage 1: full-length CVaR homotopy to sharpen the peak region, then exact polish.
    cur = best.copy()
    for q in (0.98, 0.995, 0.999):
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + budget_seconds * 0.18)
        cand = _lbfgs_log(cur, allidx, 120, tlim, cvar_q=q)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand.copy(), r
        cur = cand

    # Stage 2: alternate full-length tie polish and peak-window polish.
    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        tlim = min(deadline - 0.5, time.process_time() + budget_seconds * 0.20)
        cand = _lbfgs_log(best, allidx, 80, tlim)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r

        for pad in (0.05, 0.02):
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            tlim = min(deadline - 0.4, time.process_time() + budget_seconds * 0.10)
            cand = _lbfgs_log(best, win, 120, tlim)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r

        print("cycle %d R=%.12f ties=%d" % (cycle, bestR, _tie_count(best)))

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, deadline, maxiter=150, fg=_fun_grad_tie, log=True):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if log:
        pos = np.flatnonzero(h > 1e-13 * h.max())
        if pos.size == 0:
            return h0
        u0 = np.log(np.clip(h[pos], 1e-300, None))

        def f(u):
            hh = np.zeros(n)
            hh[pos] = np.exp(np.clip(u, -40, 40))
            val, g = fg(hh)
            return val, g[pos] * hh[pos]
    else:
        pos = np.arange(n)
        x0 = h.copy()

        def f(x):
            hh = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g

        u0 = x0

    cb = _make_cb(deadline - 0.2)
    try:
        if log:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * pos.size, callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        else:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * pos.size, callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    if log:
        h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    else:
        h2[pos] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.clip(np.diff(C2), 0, None)
    return h2


def _peak_window(h, pad_frac=0.25, min_pad=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(min_pad, int(span * pad_frac))
    return max(0, lo - pad), min(h.size - 1, hi + pad)


def _peak_polish(h, deadline, iters=200):
    if time.process_time() >= deadline - 0.5:
        return h
    lo, hi = _peak_window(h)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    n = h.size
    hc = h.copy()
    x0 = hc[free].copy()
    if x0.max() <= 0:
        return h

    def f(x):
        hh = hc.copy()
        hh[free] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[free]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * free.size, callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = hc.copy()
    h2[free] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tallest_peaks(h, k=24):
    n = h.size
    if n < 3:
        return np.array([], dtype=int)
    left = np.concatenate(([-1.0], h[:-1]))
    right = np.concatenate((h[1:], [-1.0]))
    is_peak = (h >= left) & (h >= right) & (h > 0)
    idx = np.flatnonzero(is_peak)
    if idx.size == 0:
        return np.argsort(h)[::-1][:k].astype(int)
    order = idx[np.argsort(h[idx])[::-1]]
    return order[:k].astype(int)


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad_tie(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    startH = None
    startR = 0.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            s = _rescale(s)
            startH = s
            startR = R_of(s)

    if startH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        startH = _rescale(h)
        startR = R_of(startH)

    bestH = startH.copy()
    bestR = startR
    mx0, m0, near0 = _stats(bestH)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, bestH.size, 100.0 * np.mean(bestH <= 0), mx0, m0, near0))

    # ---- Phase A: upsample to larger N and polish (main new idea) ----
    # Try a big ladder of N values; keep the best.
    target_Ns = []
    n0 = bestH.size
    for mult in (2, 3, 4, 6, 8, 12, 16):
        cand = n0 * mult
        if cand <= 900000:
            target_Ns.append(cand)
    # also a few absolute sizes
    for N in (65536, 131072, 262144, 524288):
        if N > n0 and N <= 900000 and N not in target_Ns:
            target_Ns.append(N)

    # Phase A budget: up to 55% of total
    phaseA_end = t0 + budget_seconds * 0.55

    best_candidates = [(bestH.copy(), bestR)]
    for idx, N in enumerate(target_Ns):
        if time.process_time() >= phaseA_end - 1.0:
            break
        if N <= bestH.size:
            continue
        hs = _lift_mass_preserving(bestH if idx == 0 else startH, N)
        hs = _rescale(hs)
        # short polish to let it settle
        cap = min(phaseA_end, time.process_time() + 5.0)
        hs = _lbfgs(hs, cap, maxiter=120)
        r = R_of(hs)
        # peak polish
        cap2 = min(phaseA_end, time.process_time() + 3.0)
        hs2 = _peak_polish(hs, cap2, 120)
        r2 = R_of(hs2)
        if r2 > r:
            hs, r = hs2, r2
        best_candidates.append((hs.copy(), r))
        print("  lift N=%d R=%.7f" % (N, r))
        if r > bestR + 1e-13:
            bestH, bestR = hs.copy(), r
            print("  new best R=%.7f N=%d" % (bestR, bestH.size))

    # ---- Phase B: sharp L-BFGS + p-norm homotopy on current best ----
    phaseB_end = t0 + budget_seconds * 0.88
    ladder = (2, 4, 8, 16, 32, 64, 128, 256)
    roundN = 0
    while time.process_time() < phaseB_end - 1.5:
        roundN += 1
        for p in ladder:
            if time.process_time() >= phaseB_end - 1.0:
                break
            sub = min(phaseB_end, time.process_time() + 5.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs(bestH, sub, maxiter=150, fg=fg)
            r = R_of(h)
            if r > bestR + 1e-13:
                bestH, bestR = h.copy(), r
            if p >= 32:
                sub2 = min(phaseB_end, time.process_time() + 3.0)
                hs = _lbfgs(bestH, sub2, maxiter=100)
                rs = R_of(hs)
                if rs > bestR + 1e-13:
                    bestH, bestR = hs.copy(), rs
                hs = _peak_polish(bestH, sub2, 100)
                rs = R_of(hs)
                if rs > bestR + 1e-13:
                    bestH, bestR = hs.copy(), rs
        print("  round %d R=%.7f N=%d" % (roundN, bestR, bestH.size))

    # ---- Phase C: final sharp polish ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs(bestH, deadline - 0.5, maxiter=300)
        r = R_of(h)
        if r > bestR + 1e-13:
            bestH, bestR = h.copy(), r
        bestH = _peak_polish(bestH, deadline - 0.3, 200)
        bestR = R_of(bestH)
        print("final sharp R=%.7f" % bestR)

    mx, m, near = _stats(bestH)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, bestH.size, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if startH is not None and bestR > startR + 1e-12:
        return bestH
    alt = bestH if bestR > startR - 1e-6 else None
    return {"best": startH, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, q):
    # CVaR-style: average of top (1-q) fraction of knots as the "max" surrogate.
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    thr = np.quantile(Lf, q)
    mask = Lf >= thr
    k = mask.sum()
    if k == 0:
        return _fun_grad(h)
    w = mask.astype(float) / k
    sm = np.dot(w, Lf)
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_cvar(h0, maxiter, deadline, q):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_cvar(hh, q)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _coarsen(h, N0):
    # Mass-preserving block sum coarsen to N0 bins.
    n = h.size
    if n == N0:
        return h.copy()
    if n < N0:
        # upsample by mass-preserving interpolation
        return _lift(h, N0)
    edges = np.linspace(0, n, N0 + 1)
    out = np.zeros(N0)
    for i in range(N0):
        a = int(np.floor(edges[i]))
        b = int(np.ceil(edges[i + 1]))
        a = max(0, min(n, a)); b = max(a, min(n, b))
        if b <= a:
            out[i] = 0.0
            continue
        # fractional weights
        seg = np.zeros(b - a)
        for j in range(a, b):
            lo = max(edges[i], j)
            hi = min(edges[i + 1], j + 1)
            if hi > lo:
                seg[j - a] = hi - lo
        out[i] = np.dot(h[a:b], seg)
    return out


def _lift(h, N1):
    # Mass-preserving piecewise-constant lift from n bins to N1 bins.
    n = h.size
    if n == N1:
        return h.copy()
    edges = np.linspace(0, n, N1 + 1)
    out = np.zeros(N1)
    for i in range(N1):
        lo = edges[i]; hi = edges[i + 1]
        a = int(np.floor(lo)); b = int(np.ceil(hi))
        a = max(0, min(n - 1, a)); b = max(a + 1, min(n, b))
        acc = 0.0
        for j in range(a, b):
            seg_lo = max(lo, j); seg_hi = min(hi, j + 1)
            if seg_hi > seg_lo:
                acc += h[j] * (seg_hi - seg_lo)
        out[i] = acc
    return out


def _stack_at_N(h, deadline, tag=""):
    # Full modern stack at fixed N. Returns (best_h, bestR).
    cur = _rescale(np.clip(h, 0, None))
    curR = R_of(cur)
    best, bestR = cur.copy(), curR

    def try_cand(cand, label):
        nonlocal best, bestR, cur, curR
        rc = R_of(cand)
        if rc > curR + 1e-13:
            cur, curR = cand, rc
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
                print("  %s %s R=%.7f" % (tag, label, bestR))

    if time.process_time() >= deadline - 1.0:
        return best, bestR

    # Exact tie-averaged L-BFGS-B
    h1 = _lbfgs_log(cur, 200, deadline)
    try_cand(h1, "tie")

    # beta ladder
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            return best, bestR
        hb = _lbfgs_log(cur, 100, deadline, beta=beta)
        try_cand(hb, "beta%.0e" % beta)
        ht = _lbfgs_log(cur, 50, deadline)
        try_cand(ht, "tie")

    # CVaR polishes
    for q in (0.99, 0.999):
        if time.process_time() >= deadline - 1.0:
            return best, bestR
        hc = _lbfgs_cvar(cur, 60, deadline, q)
        try_cand(hc, "cvar%.3f" % q)

    # peak-window tie polish
    if time.process_time() < deadline - 1.0:
        hw = _window_polish_peak(cur, deadline, 0.10, 32, maxiter=100)
        try_cand(hw, "win")

    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # --- Experiment: coarse-commit line ---
    N0 = 2048
    h_coarse = _coarsen(start_best, N0)
    h_coarse = _rescale(h_coarse)
    r_coarse0 = R_of(h_coarse)
    print("coarse N0=%d init R=%.7f" % (N0, r_coarse0))

    coarse_best, coarse_bestR = _stack_at_N(h_coarse, deadline, tag="N0")
    print("committed coarse R=%.7f" % coarse_bestR)

    # Lift to 8192 and run stack
    lift_best = coarse_best
    lift_bestR = coarse_bestR
    lift_N = N0
    if time.process_time() < deadline - 3.0:
        h8 = _rescale(_lift(coarse_best, 8192))
        r8 = R_of(h8)
        print("lift 8192 init R=%.7f" % r8)
        b8, r8b = _stack_at_N(h8, deadline, tag="L8")
        print("lift 8192 R=%.7f (fold loss vs coarse %.2e)" %
              (r8b, coarse_bestR - r8b))
        if r8b > lift_bestR:
            lift_best, lift_bestR, lift_N = b8, r8b, 8192

    # Lift to 32768 (native) and run stack
    if time.process_time() < deadline - 4.0:
        h32 = _rescale(_lift(lift_best, 32768))
        r32 = R_of(h32)
        print("lift 32768 init R=%.7f" % r32)
        b32, r32b = _stack_at_N(h32, deadline, tag="L32")
        print("lift 32768 R=%.7f (fold loss vs prev %.2e)" %
              (r32b, lift_bestR - r32b))
        if r32b > lift_bestR:
            lift_best, lift_bestR, lift_N = b32, r32b, 32768

    # Lift to 65536 if time permits
    if time.process_time() < deadline - 6.0:
        h64 = _rescale(_lift(lift_best, 65536))
        r64 = R_of(h64)
        print("lift 65536 init R=%.7f" % r64)
        b64, r64b = _stack_at_N(h64, deadline, tag="L64")
        print("lift 65536 R=%.7f" % r64b)
        if r64b > lift_bestR:
            lift_best, lift_bestR, lift_N = b64, r64b, 65536

    print("lift line best R=%.7f at N=%d" % (lift_bestR, lift_N))

    # Compare against base start; keep whichever is better as "best"
    if lift_bestR > bestR + 1e-13:
        best, bestR = lift_best.copy(), lift_bestR
        print("  lift wins R=%.7f" % bestR)

    # Final sharp polish on best
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 200, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf
            print("  final sharp R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    alt = coarse_best if coarse_bestR > 0 else None
    if bestR > start_bestR + 1e-12:
        if alt is not None and alt.size != best.size:
            return {"best": best, "alternative": alt}
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _flank_window(h, side, lo_frac=0.55, hi_frac=0.995, pad_frac=0.10,
                  extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    m = int(np.argmax(Lf))
    lo_v = lo_frac * mx
    hi_v = hi_frac * mx
    if side == 'left':
        seg = Lf[:m + 1]
        idx = np.flatnonzero((seg >= lo_v) & (seg <= hi_v))
    else:
        seg = Lf[m:]
        idx = np.flatnonzero((seg >= lo_v) & (seg <= hi_v))
        idx = idx + m
    if idx.size == 0:
        return _peak_window(h, pad_frac=pad_frac, extra=extra)
    lo = max(0, int(idx.min()) - 1)
    hi = min(h.size - 1, int(idx.max()))
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    modes = ['left', 'peak', 'right', 'peak']
    pads = [0.05, 0.08, 0.10, 0.12, 0.15]
    step = 0
    while time.process_time() < deadline - 0.5:
        mode = modes[step % len(modes)]
        pad = pads[(step // len(modes)) % len(pads)]
        if mode == 'peak':
            win = _peak_window(work, pad_frac=pad, extra=128)
        else:
            win = _flank_window(work, mode, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 350, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        gained = False
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%s%s%d" % (tag, mode[0], step)
            gained = True
        if step % 3 == 2 and time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 250, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%s%s%d+all0" % (tag, mode[0], step)
                gained = True
        if not gained:
            pass
        step += 1
    return work, best, bestR, origin


def _edge_extend_pow(h, K, p):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        w = (1.0 + k) ** (-p)
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * w
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * w
    return _rescale(h)


def _erode_grow(h, factor):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    m = max(1, int(round(n * factor)))
    if m == n:
        return h.copy()
    xi = np.linspace(0.0, n - 1.0, m)
    xp = np.arange(n, dtype=float)
    return _rescale(np.interp(xi, xp, h))


def _dilate_zero_runs(h, deadline, maxiter=60):
    """Find zero-runs that can be activated (fill in) to improve R.

    The structure of the optimum has a tall central peak with decaying
    shoulders.  Zero gaps between support regions likely hurt: try filling
    a few of them in and let L-BFGS decide.
    """
    if time.process_time() >= deadline - 1.0:
        return h
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    if n < 16:
        return h
    zero = (h <= 0.0)
    if not zero.any():
        return h
    # find contiguous zero runs
    dz = np.diff(zero.astype(np.int8))
    starts = np.flatnonzero(dz == 1) + 1
    ends = np.flatnonzero(dz == -1) + 1
    if zero[0]:
        starts = np.concatenate(([0], starts))
    if zero[-1]:
        ends = np.concatenate((ends, [n]))
    if starts.size != ends.size:
        m = min(starts.size, ends.size)
        starts, ends = starts[:m], ends[:m]
    if starts.size == 0:
        return h
    # consider only interior gaps (not leading/trailing zeros)
    keep = (starts > 0) & (ends < n)
    starts = starts[keep]; ends = ends[keep]
    if starts.size == 0:
        return h
    lengths = ends - starts
    # pick the longest few interior gaps
    order = np.argsort(-lengths)
    picked = []
    for oi in order[:3]:
        s = int(starts[oi]); e = int(ends[oi])
        # fill with small values based on nearest nonzero neighbors
        left_val = h[s - 1] if s - 1 >= 0 else 0.0
        right_val = h[e] if e < n else 0.0
        base = 0.5 * (left_val + right_val)
        if base <= 0:
            continue
        h[s:e] = base
        picked.append((s, e))
    if not picked:
        return h
    h = _rescale(h)
    h2 = _lbfgs_all_pos(h, maxiter, deadline, beta=1e6)
    if R_of(h2) > R_of(h):
        h = h2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = -1.0
    origin = "start"
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase A: refine on the given grid (shorter).
    phase_a_deadline = min(deadline - 1.0, t0 + budget_seconds * 0.45)
    work, best, bestR, origin = _run_cycle(
        start_best.copy(), best.copy(), bestR, phase_a_deadline, 'base')

    # Phase B: dilate zero-runs (fill gaps) — new idea.
    if time.process_time() < deadline - 3.0:
        hd = _dilate_zero_runs(best, min(deadline - 1.5,
                                          time.process_time() + budget_seconds * 0.15))
        rd = R_of(hd)
        if rd > bestR + 1e-14:
            print("  dilate R=%.9f" % rd)
            work, best, bestR, origin = _run_cycle(
                hd.copy(), hd.copy(), rd, deadline, 'dilate')
        else:
            if alt is None or rd > altR:
                alt = hd.copy(); altR = rd

    # Phase C: try a finer grid via linear interpolation, then refine.
    if time.process_time() < deadline - 2.0:
        for factor in (2.0,):
            if time.process_time() >= deadline - 2.0:
                break
            hg = _erode_grow(best, factor)
            if hg.size > 1000000:
                continue
            rg = R_of(hg)
            print("  grow x%.1f -> N=%d R=%.9f" % (factor, hg.size, rg))
            if rg > bestR + 1e-14:
                work, best, bestR, origin = _run_cycle(
                    hg.copy(), hg.copy(), rg, deadline, 'grow')
            else:
                work, best2, bestR2, origin2 = _run_cycle(
                    hg.copy(), best.copy(), bestR, deadline, 'growtry')
                if bestR2 > bestR + 1e-14:
                    best, bestR, origin = best2, bestR2, origin2

    # Phase D: edge extension to fill in low tails (may improve R).
    if time.process_time() < deadline - 1.0:
        K = max(4, best.size // 64)
        he = _edge_extend_pow(best, K, 2.0)
        re_ = R_of(he)
        if re_ > bestR + 1e-14:
            print("  edge-extend R=%.9f" % re_)
            work, best2, bestR2, origin2 = _run_cycle(
                he.copy(), he.copy(), re_, deadline, 'edge')
            if bestR2 > bestR:
                best, bestR = best2, bestR2
        else:
            if alt is None or re_ > altR:
                alt = he.copy(); altR = re_

    # Final polish (full free, no beta).
    if time.process_time() < deadline - 0.8:
        hp = _lbfgs_all_pos(best, 400, deadline - 0.3, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("  final polish R=%.9f" % bestR)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if alt is not None and altR > -1:
        return {"best": best, "alternative": alt}
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fg(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lbfgs_lin(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_log(best, 200, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_log(best, 100, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.25, 128, 1e8), (0.40, 256, 1e8),
              (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_lin(best, 100, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _flatten_peak(h, deadline):
    """Newton-like push to flatten the peak region: L2-project to a
    constant over the near-peak band."""
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.9995 * M)
    if idx.size < 4:
        return h
    T = np.zeros_like(Lf)
    # target: same as Lf but flattened to M over the peak band
    lo = max(0, idx.min() - 1)
    hi = min(Lf.size - 1, idx.max() + 1)
    T[:] = Lf / M
    T[lo:hi + 1] = 1.0
    n = h.size

    def f(xv):
        hh = np.clip(xv, 0.0, None)
        Lh = _knots(hh)
        d = Lh / M - T
        val = np.sum(d * d)
        gLf = 2.0 * d / M
        g = _backprop(gLf, hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, np.clip(h, 0, None), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': 120, 'maxfun': 240,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    return _rescale(np.clip(res.x, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # Try a flatten-peak projection to build a genuinely different shape.
    if time.process_time() < deadline - 8.0:
        try:
            hf = _flatten_peak(best, deadline - 6.0)
            hf = _lbfgs_log(hf, 100, deadline - 5.0, beta=0.0)
            rf = R_of(hf)
            print("flatten R=%.7f" % rf)
            if rf > altR:
                alt_cand = hf.copy()
                altR = rf
            if rf > bestR + 1e-13:
                best, bestR = hf.copy(), rf
                print("flatten improved base to R=%.7f" % bestR)
        except Exception as e:
            print("flatten failed: %s" % e)

    # Main alternating cycle
    while time.process_time() < deadline - 2.0:
        oldR = bestR
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        if bestR <= oldR + 1e-13:
            # try a flatten push again with fresh state
            if time.process_time() < deadline - 4.0:
                hf = _flatten_peak(best, deadline - 2.5)
                hf = _lbfgs_log(hf, 80, deadline - 2.0, beta=0.0)
                rf = R_of(hf)
                if rf > altR:
                    alt_cand = hf.copy()
                    altR = rf
                if rf > bestR + 1e-13:
                    best, bestR = hf.copy(), rf
                    continue
            break

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _upsample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    N = n * factor
    x_old = np.arange(n, dtype=float)
    x_new = np.arange(N, dtype=float) / factor
    return np.interp(x_new, x_old, h, left=h[0], right=h[-1])


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _plateau_polish(h0, deadline, iters=40, frac=0.02):
    """Directly push the near-max plateau toward a flat top by reweighting.

    For each near-max knot, we add a tiny penalty pulling L toward the max.
    This is a cheap way to flatten the plateau, which raises ||f*f||_inf
    without changing the L2 mass much, so R rises."""
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.flatnonzero(h > 1e-13 * h.max())
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        hh = np.zeros(n)
        hh[active] = np.exp(np.clip(u, -30.0, 30.0))
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(active.size)
        num, dq, Lf = _num_and_dq(hh)
        mx = Lf.max()
        # treat top plateau as tied-max; use softmax over plateau
        idx = np.flatnonzero(Lf >= mx * (1.0 - frac))
        gLf = -dq / num
        w = 1.0 / idx.size
        gLf[idx] += w / mx
        # penalize spread among the plateau (encourage flat top)
        Lp = Lf[idx]
        pen = np.sum((Lp - mx) ** 2) * 0.0  # placeholder, off
        grad = _backprop(gLf, hh) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
        return val, grad[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    bestH = best.copy()
    bestRH = bestR

    # Phase 0: beta-homotopy sharpening on the current grid.
    phase0_end = min(t0 + budget_seconds * 0.18, deadline - 5.0)
    for beta in (100, 400, 1500, 5000):
        if time.process_time() >= phase0_end - 1.0:
            break
        cap = min(phase0_end, time.process_time() + 3.0)
        h = _lbfgs_log(bestH, 200, cap, beta=beta)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  p0 beta=%d R=%.7f" % (beta, bestRH))

    # Phase 1: upsample and re-optimise on a finer grid, with a plateau polish.
    phase1_end = min(t0 + budget_seconds * 0.60, deadline - 3.0)
    for factor in (2, 2, 3):
        if time.process_time() >= phase1_end - 2.0:
            break
        if bestH.size * factor > 900000:
            break
        hs = _upsample(bestH, factor)
        hs = _rescale(hs)
        cap = min(phase1_end, time.process_time() + 5.0)
        hs = _lbfgs_log(hs, 250, cap, tie=True)
        rs = R_of(hs)
        if rs > bestRH + 1e-12:
            bestH, bestRH = hs.copy(), rs
        # plateau polish specifically targets the peak-flatness
        if time.process_time() < phase1_end - 1.5:
            cap = min(phase1_end, time.process_time() + 3.0)
            hp = _plateau_polish(bestH, cap, iters=60, frac=0.01)
            rp = R_of(hp)
            if rp > bestRH + 1e-12:
                bestH, bestRH = hp.copy(), rp
        print("  p1 up x%d R=%.7f (N=%d)" % (factor, bestRH, bestH.size))

    # Phase 2: alternating tie-LBFGS and plateau polish.
    phase2_end = min(t0 + budget_seconds * 0.90, deadline - 2.0)
    rnd = 0
    while time.process_time() < phase2_end - 1.5:
        rnd += 1
        if time.process_time() >= phase2_end - 1.0:
            break
        cap = min(phase2_end, time.process_time() + 3.0)
        h = _lbfgs_log(bestH, 200, cap, tie=True)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        if time.process_time() >= phase2_end - 1.5:
            break
        cap = min(phase2_end, time.process_time() + 3.0)
        h = _plateau_polish(bestH, cap, iters=60, frac=0.01)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("  p2 round %d R=%.7f (N=%d)" % (rnd, bestRH, bestH.size))

    # Final sharp polish.
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5, tie=True)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final R=%.7f (N=%d)" % (bestRH, bestH.size))

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=maxiter, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _find_block(h):
    """Find largest BLK>1 dividing N such that h is exactly block-constant."""
    N = h.size
    for BLK in range(min(64, N), 1, -1):
        if N % BLK != 0:
            continue
        K = N // BLK
        c = h.reshape(K, BLK)
        if np.allclose(c, c[:, :1], rtol=1e-12, atol=1e-15):
            return BLK
    return 1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(h)
        best_r = R_of(best)
        start_r = best_r

    alt = None
    alt_r = -1.0

    # Detect if the start (or best) is block-constant, and use the block
    # structure as the main working representation: fewer variables, better
    # conditioning, and block structure is preserved by the construction.
    BLK = _find_block(best)
    print("start R=%.6f N=%d BLK=%d" % (start_r, best.size, BLK))

    # Main loop: block-structured optimization with softmax homotopy restarts.
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        N = best.size
        K = N // BLK
        c = best.reshape(K, BLK).mean(axis=1)
        c = _rescale(np.repeat(c, BLK)).reshape(K, BLK).mean(axis=1)

        rng = np.random.default_rng(it * 7919)
        noise = 1.0 + 0.05 * rng.standard_normal(K)
        cseed = np.clip(c * noise, 0.0, None)
        seed = np.repeat(cseed, BLK)
        seed = _rescale(seed)

        cand, r = _homotopy(seed, (32, 128, 512, 2048, 8192), 150, deadline)
        if r > best_r:
            best, best_r = cand, r
        elif alt is None or r > alt_r:
            alt, alt_r = cand, r

        # Polish on full resolution around the peak.
        cand, r = _polish(best, deadline, best_r)
        if r > best_r:
            best, best_r = cand, r

        # Full-resolution L-BFGS occasionally.
        if it % 3 == 0:
            cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
            print("  it#%d R=%.6f (start %.6f)" % (it, best_r, start_r))

    best = _rescale(best)
    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None:
        if start_r >= best_r:
            if alt is not None and alt_r > start_r:
                return {"best": start_arr, "alternative": alt}
            return {"best": start_arr, "alternative": best}
        if alt is not None and alt_r > 0 and alt_r < best_r:
            return {"best": best, "alternative": alt}
        return {"best": best, "alternative": start_arr}
    return best

