    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------------------------------------------------------------------------
# NEW: higher-resolution refinement.  When the current best has many tied
# knots at the max, the true optimum of this family likely wants a *finer*
# discretisation to spread the peak over more knots.  We lift h to a finer
# grid (mass-preserving, then fold back if it doesn't help), re-polish, and
# keep the finer representation if it improves R.  This is a genuinely
# different direction from the original (which only re-polishes at fixed N).
# ---------------------------------------------------------------------------
def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    h = np.diff(C)
    return np.clip(h, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- Phase 1: refinement at current N (tie-aware full + peak ladder) ----
    phase1_end = t0 + budget_seconds * 0.35
    it = 0
    while time.process_time() < phase1_end - 1.5:
        it += 1
        slice_end = min(phase1_end, time.process_time() + 4.0)
        h_t = _lbfgs_all_pos(best, 300, slice_end - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
        if time.process_time() < slice_end - 1.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=200, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
    print("phase1 done R=%.9f (N=%d, ties=%d)"
          % (bestR, best.size, _tie_count(best)))

    # ---- Phase 2: lift to finer grid and polish there ----
    # Try a small ladder of upsampling factors; whichever improves R wins,
    # and we keep the finer representation (it is what gets scored).
    phase2_end = t0 + budget_seconds * 0.80
    N0 = best.size
    factors = [1.5, 2.0, 3.0, 4.0]
    for f in factors:
        if time.process_time() >= phase2_end - 2.0:
            break
        N2 = int(round(N0 * f))
        if N2 > 1000000:
            N2 = 1000000
        if N2 <= N0:
            continue
        h_fine = _lift_mass_preserving(best, N2)
        h_fine = _rescale(h_fine)
        r_fine0 = R_of(h_fine)
        # polish at fine resolution
        slice_end = min(phase2_end, time.process_time() + 6.0)
        h_pol = _lbfgs_all_pos(h_fine, 250, slice_end - 3.0, tie=True)
        if time.process_time() < slice_end - 2.5:
            h_pol = _peak_ladder(h_pol, slice_end - 1.5,
                                 pads=(0.06, 0.04), iters=150, tie=True)
        if time.process_time() < slice_end - 1.0:
            h_pol = _lbfgs_all_pos(h_pol, 200, slice_end - 0.3, tie=False)
        r_pol = R_of(h_pol)
        # also try folding the polished fine version back to N0
        h_fold = _rescale(_fold_back(h_pol, N0))
        r_fold = R_of(h_fold)
        improved = False
        if r_pol > bestR + 1e-15:
            best, bestR = h_pol.copy(), r_pol
            improved = True
        if r_fold > bestR + 1e-15:
            best, bestR = h_fold.copy(), r_fold
            improved = True
        print("lift x%.1f N=%d r_lift0=%.9f r_pol=%.9f r_fold=%.9f %s"
              % (f, N2, r_fine0, r_pol, r_fold,
                 "ACCEPT" if improved else "no gain"))
        if improved:
            # continue refining from the new (possibly finer) best
            N0 = best.size

    # ---- Phase 3: final polish on the best representation ----
    loop_end = t0 + budget_seconds * 0.88
    it = 0
    while time.process_time() < loop_end - 1.5:
        it += 1
        slice_end = min(loop_end, time.process_time() + 4.0)
        h_t = _lbfgs_all_pos(best, 300, slice_end - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
        if time.process_time() < slice_end - 1.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.06, 0.04, 0.02), iters=180, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t

    # final non-tie polish
    if time.process_time() < deadline - 0.5:
        h_t = _lbfgs_all_pos(best, 200, deadline - 0.2, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0, None)
    return _rescale(h2)


def _riemann_lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = _rescale(np.clip(h0, 0, None))
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        if hh.sum() <= 0:
            return 1e18, np.zeros(n)
        val, g = _fun_grad_tie(hh)
        denom = float(np.dot(hh, hh))
        if denom > 0:
            g = g - (float(np.dot(g, hh)) / denom) * hh
        return val, g

    cb = _make_cb(deadline - 0.15)
    x0 = h.copy()
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0, None))


def _prolongate(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N) / N
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(n + 1, dtype=float))
    hh = np.clip(np.diff(out), 0, None)
    if hh.sum() <= 0:
        return np.ones(N) / N
    return hh


def _rasterise(widths, heights):
    N = int(widths.sum())
    h = np.empty(N, dtype=float)
    pos = 0
    for w, a in zip(widths, heights):
        h[pos:pos + w] = a
        pos += w
    return h


def _collapse(h, nb):
    n = h.size
    edges = np.linspace(0, n, nb + 1).astype(int)
    widths = np.diff(edges)
    heights = np.empty(nb)
    for i in range(nb):
        lo, hi = edges[i], edges[i + 1]
        if hi > lo:
            heights[i] = h[lo:hi].mean()
        else:
            heights[i] = 0.0
    return widths.astype(int), heights


def _split_genome(w64, a64):
    # split each block into two, preserving rasterisation exactly
    NB = w64.size
    w128 = np.empty(2 * NB, dtype=int)
    a128 = np.empty(2 * NB, dtype=float)
    for k in range(NB):
        w = int(w64[k])
        w1 = w // 2
        w2 = w - w1
        if w1 < 1:
            w1 = 1
            w2 = w - 1
        if w2 < 1:
            w2 = 1
            w1 = w - 1
        w128[2 * k] = w1
        w128[2 * k + 1] = w2
        a128[2 * k] = a64[k]
        a128[2 * k + 1] = a64[k]
    return w128, a128


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240607)
    N = 3281
    NB64 = 64
    NB = 128

    startR = 0.0
    start_h = None
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            if s.size != N:
                s = _rescale(_prolongate(s, N))
            else:
                s = _rescale(s)
            start_h = s
            startR = R_of(s)

    if start_h is None:
        start_h = _rescale(np.ones(N))
        startR = R_of(start_h)

    # Extract 64-block genome from start, then split to 128
    w64, a64 = _collapse(start_h, NB64)
    w64 = np.maximum(1, w64.astype(int))
    diff = N - w64.sum()
    i = 0
    while diff != 0 and i < 1000000:
        j = i % NB64
        if diff > 0:
            w64[j] += 1; diff -= 1
        elif w64[j] > 1:
            w64[j] -= 1; diff += 1
        i += 1

    w, a = _split_genome(w64, a64)
    # verify rasterisation reproduces start_h approximately
    h_check = _rasterise(w, a)
    if h_check.size != N:
        # fallback: just use start_h directly
        w, a = _collapse(start_h, NB)
        w = np.maximum(1, w.astype(int))
        diff = N - w.sum()
        i = 0
        while diff != 0 and i < 1000000:
            j = i % NB
            if diff > 0:
                w[j] += 1; diff -= 1
            elif w[j] > 1:
                w[j] -= 1; diff += 1
            i += 1

    def polish(w, a, maxiter, dl):
        h = _rescale(_rasterise(w, a))
        hp = _lbfgs_block(h, np.arange(N), maxiter, dl, tie=True)
        return hp, R_of(hp)

    # Baseline polish
    cur_h, curR = polish(w, a, 100, deadline)
    best_h, bestR = cur_h.copy(), curR
    if startR > bestR:
        best_h, bestR = start_h.copy(), startR
    print("baseline R=%.9f (start %.9f)" % (bestR, startR))

    # Pool of genomes (w, a, h, R) - keep top 3
    pool = [(w.copy(), a.copy(), cur_h.copy(), curR)]

    def pool_add(w2, a2, h2, r2):
        pool.append((w2.copy(), a2.copy(), h2.copy(), r2))
        pool.sort(key=lambda t: -t[3])
        del pool[3:]

    accepted = 0
    moves_tried = 0
    since_full = 0

    # Width-shift search phase
    while time.process_time() < deadline - 2.0:
        moves_tried += 1
        w2 = w.copy()
        nmoves = int(rng.integers(1, 4))
        for _ in range(nmoves):
            j = int(rng.integers(0, NB))
            d = int(rng.choice([-1, 1]) * rng.integers(1, 7))
            if d > 0:
                if w2[j] - d >= 1:
                    k = (j + 1) % NB
                    w2[j] -= d; w2[k] += d
            else:
                k = (j + 1) % NB
                if w2[k] + d >= 1:
                    w2[j] -= d; w2[k] += d
        if rng.random() < 0.15:
            j = int(rng.integers(0, NB))
            if w2[j] >= 4:
                half = w2[j] // 2
                k = (j + 1) % NB
                w2[j] -= half; w2[k] += half

        if w2.sum() != N or np.any(w2 < 1):
            continue

        h2 = _rescale(_rasterise(w2, a))
        hp = _lbfgs_block(h2, np.arange(N), 70, deadline - 1.0, tie=True)
        rp = R_of(hp)

        if rp > curR + 1e-12:
            w = w2
            a = _collapse(hp, NB)[1]
            cur_h, curR = hp, rp
            accepted += 1
            since_full += 1
            if rp > bestR:
                best_h, bestR = hp.copy(), rp
            pool_add(w, a, hp, rp)
            print("accept %d R=%.9f wstd=%.3f" % (accepted, bestR, float(np.std(w))))

            if since_full >= 5 and time.process_time() < deadline - 3.0:
                since_full = 0
                hf = _riemann_lbfgs(cur_h, 200, deadline - 1.0)
                rf = R_of(hf)
                if rf > curR:
                    cur_h, curR = hf, rf
                    a = _collapse(hf, NB)[1]
                    if rf > bestR:
                        best_h, bestR = hf.copy(), rf
                    pool_add(w, a, hf, rf)
                    print("full polish R=%.9f" % bestR)

        # GA burst occasionally
        if rng.random() < 0.08 and len(pool) >= 2 and time.process_time() < deadline - 3.0:
            # crossover two best genomes
            p1 = pool[0]; p2 = pool[1]
            w1p, a1p = p1[0], p1[1]
            w2p, a2p = p2[0], p2[1]
            # crossover: take widths from one, heights from other, then perturb
            wc = w1p.copy()
            ac = a2p.copy()
            # fix sum
            diff = N - wc.sum()
            i = 0
            while diff != 0 and i < 1000000:
                j = i % NB
                if diff > 0:
                    wc[j] += 1; diff -= 1
                elif wc[j] > 1:
                    wc[j] -= 1; diff += 1
                i += 1
            # perturb 2 blocks' widths
            for _ in range(2):
                j = int(rng.integers(0, NB))
                d = int(rng.choice([-1, 1]) * rng.integers(1, 5))
                if d > 0 and wc[j] - d >= 1:
                    k = (j + 1) % NB
                    wc[j] -= d; wc[k] += d
                elif d < 0:
                    k = (j + 1) % NB
                    if wc[k] + d >= 1:
                        wc[j] -= d; wc[k] += d
            # perturb 3 heights log-normal
            for _ in range(3):
                j = int(rng.integers(0, NB))
                ac[j] *= float(np.exp(rng.normal(0, 0.1)))
            hc, rc = polish(wc, ac, 70, deadline - 1.0)
            if rc > pool[-1][3]:
                pool_add(wc, ac, hc, rc)
                if rc > bestR:
                    best_h, bestR = hc.copy(), rc
                    w, a, cur_h, curR = wc.copy(), ac.copy(), hc.copy(), rc
                    print("GA accept R=%.9f" % bestR)

    # Final full polish
    if time.process_time() < deadline - 0.5:
        hp = _riemann_lbfgs(best_h, 250, deadline)
        rp = R_of(hp)
        if rp > bestR:
            best_h, bestR = hp, rp

    if start_h is not None and bestR < startR:
        best_h = start_h
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, moves=%d, accepted=%d)" % (
        bestR, startR, best_h.size, moves_tried, accepted))

    result = {"best": best_h}
    if cur_h is not None and R_of(cur_h) > startR + 1e-12:
        na = np.linalg.norm(cur_h); nb = np.linalg.norm(best_h)
        if na > 0 and nb > 0 and float(np.dot(cur_h, best_h) / (na * nb)) < 0.9999:
            result["alternative"] = cur_h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _warp(h, a, K):
    N = h.size
    j = np.arange(N + 1, dtype=float)
    t = j.copy()
    for k in range(1, K + 1):
        t += a[k - 1] * np.sin(2.0 * np.pi * k * j / N)
    t[0] = 0.0
    t[N] = float(N)
    if np.any(np.diff(t) <= 0):
        return None
    C = np.concatenate(([0.0], np.cumsum(h)))
    Ct = np.interp(t, j, C)
    hnew = np.diff(Ct)
    hnew = np.clip(hnew, 0.0, None)
    if hnew.sum() <= 0:
        return None
    return hnew


def _warp_bounds(N, K):
    k = np.arange(1, K + 1, dtype=float)
    return 0.15 * N / (2.0 * np.pi * k)


def _optimize_warp(h, K, deadline, x0=None):
    N = h.size
    b = _warp_bounds(N, K)
    if x0 is None:
        x0 = np.zeros(K)
    else:
        x0 = np.asarray(x0, dtype=float)[:K]
        if x0.size < K:
            x0 = np.concatenate([x0, np.zeros(K - x0.size)])
        x0 = np.clip(x0, -b, b)

    best = {'a': x0.copy(), 'R': R_of(h), 'h': h}
    h0R = best['R']

    def f(a):
        if time.process_time() > deadline:
            raise TimeoutError
        hh = _warp(h, a, K)
        if hh is None:
            return 1e6
        r = R_of(hh)
        if r > best['R']:
            best['R'] = r
            best['a'] = a.copy()
            best['h'] = hh
        return -r

    try:
        res = minimize(f, x0, method='Nelder-Mead',
                       options={'maxiter': 4000, 'xatol': 1e-6,
                                'fatol': 1e-12, 'adaptive': True})
        a_opt = res.x
    except (TimeoutError, Exception):
        a_opt = best['a']
    if best['R'] > h0R:
        return best['h'], best['a'], best['R']
    return h, x0, h0R


def _smooth(h, sigma):
    """Light Gaussian smoothing applied to heights; preserves non-negativity."""
    if sigma <= 0:
        return h
    r = int(np.ceil(3 * sigma))
    if r < 1:
        return h
    x = np.arange(-r, r + 1, dtype=float)
    ker = np.exp(-0.5 * (x / sigma) ** 2)
    ker /= ker.sum()
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- Phase A: smoothing + peak polish (new idea: small-scale smoothing
    #      lets the optimizer reflow tiny structures near the peak) ----
    phaseA_end = t0 + budget_seconds * 0.30
    if time.process_time() < phaseA_end - 2.0:
        for sigma in (0.7, 1.2, 2.0):
            if time.process_time() >= phaseA_end - 1.5:
                break
            hs = _smooth(best, sigma)
            hs = _rescale(hs)
            ht = _peak_ladder(hs, phaseA_end - 0.5,
                              pads=(0.06, 0.04, 0.03), iters=200)
            rt = R_of(ht)
            if rt > bestR + 1e-15:
                best, bestR = ht.copy(), rt
                print("PHASE A smooth sigma=%.2f ACCEPT R=%.9f" % (sigma, bestR))
            else:
                print("PHASE A smooth sigma=%.2f no gain R=%.9f" % (sigma, rt))

    # ---- Phase B: warp K=16 then K=32 ----
    warp_a = None
    phaseB_end = t0 + budget_seconds * 0.62
    if time.process_time() < phaseB_end - 2.0:
        hw, a16, rw = _optimize_warp(best, 16, phaseB_end - 0.5)
        dR = rw - bestR
        print("PHASE B warp K=16 dR=%+.3e sum|a|=%.4f R=%.9f"
              % (dR, float(np.sum(np.abs(a16))), rw))
        if rw > bestR + 1e-9:
            best, bestR = hw.copy(), rw
            warp_a = a16.copy()

    phaseC_end = t0 + budget_seconds * 0.78
    if time.process_time() < phaseC_end - 2.0:
        x0 = None
        if warp_a is not None:
            x0 = np.zeros(32)
            x0[:min(16, warp_a.size)] = warp_a[:16]
        hw, a32, rw = _optimize_warp(best, 32, phaseC_end - 0.5, x0=x0)
        dR = rw - bestR
        print("PHASE C warp K=32 dR=%+.3e sum|a|=%.4f R=%.9f"
              % (dR, float(np.sum(np.abs(a32))), rw))
        if rw > bestR + 1e-9:
            best, bestR = hw.copy(), rw

    # ---- Phase D: peak-ladder polish with tie ----
    phaseD_end = t0 + budget_seconds * 0.86
    if time.process_time() < phaseD_end - 2.0:
        ht = _peak_ladder(best, phaseD_end - 0.5,
                          pads=(0.08, 0.05, 0.03), iters=250)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("PHASE D peak ACCEPT R=%.9f" % bestR)
        else:
            print("PHASE D peak no gain R=%.9f" % rt)

    # ---- Final: tight peak polish ----
    fd = t0 + budget_seconds * 0.92
    while time.process_time() < fd - 0.6:
        win = _peak_window(best, pad_frac=0.02, extra=64)
        ht = _lbfgs_block(best, win, 200, fd - 0.3, tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-16:
            best, bestR = ht.copy(), rt
            print("FINAL peak ACCEPT R=%.9f" % bestR)
            fd = min(fd, time.process_time() + 1.5)
        else:
            break

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
import random


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.size == 0:
        return -1.0
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    l2 = np.sum(Lp[:-1] ** 2 + Lp[:-1] * Lp[1:] + Lp[1:] ** 2) / 3.0
    linf = L.max()
    l1 = s * s
    if linf <= 0 or l1 <= 0:
        return -1.0
    return l2 / (l1 * linf)


def _fun_grad_tie(h, N):
    """Return (R, grad) with tie-averaged gradient in log space via finite diff on R."""
    # We'll just use numerical gradient of R via central differences on a few coords;
    # but that's expensive. Instead use analytic-ish: compute R and a smoothed gradient.
    # Simpler: use finite differences over all coords is too slow for large N.
    # Use a cheap gradient: perturb each coord by eps and recompute R — O(N^2) convolve.
    # For N up to 65536 that's too slow. Use scipy-free approach: only used at small N.
    return _R(h), None


def _find_diff_set(v, k, deadline, rng):
    """Local search for (v,k,1) cyclic difference set. Returns (S, F)."""
    best_S = None
    best_F = 10 ** 9
    restarts = 0
    while restarts < 30:
        if time.process_time() > deadline:
            break
        restarts += 1
        S = sorted(rng.sample(range(v), k))
        Sset = set(S)
        # counts of ordered differences
        cnt = np.zeros(v, dtype=np.int32)
        for i in range(k):
            for j in range(k):
                if i != j:
                    cnt[(S[i] - S[j]) % v] += 1
        F = int(np.sum(np.maximum(0, cnt - 1)))
        for sweep in range(300):
            if F == 0:
                break
            if time.process_time() > deadline:
                break
            improved = False
            for idx in range(k):
                cur = S[idx]
                # best alternative
                best_alt = cur
                best_altF = F
                # temporarily remove cur
                for j in range(k):
                    if j != idx:
                        cnt[(cur - S[j]) % v] -= 1
                        cnt[(S[j] - cur) % v] -= 1
                baseF = int(np.sum(np.maximum(0, cnt - 1)))
                for cand in range(v):
                    if cand == cur or cand in Sset:
                        continue
                    # add cand
                    dF = 0
                    for j in range(k):
                        if j != idx:
                            r1 = (cand - S[j]) % v
                            r2 = (S[j] - cand) % v
                            dF += (1 if cnt[r1] >= 1 else 0)
                            dF += (1 if cnt[r2] >= 1 else 0)
                    # approximate new F
                    newF = baseF + dF
                    if newF < best_altF:
                        best_altF = newF
                        best_alt = cand
                # commit best_alt
                if best_alt != cur:
                    Sset.discard(cur)
                    Sset.add(best_alt)
                    S[idx] = best_alt
                    for j in range(k):
                        if j != idx:
                            cnt[(best_alt - S[j]) % v] += 1
                            cnt[(S[j] - best_alt) % v] += 1
                    F = best_altF
                    improved = True
                else:
                    # restore cur
                    for j in range(k):
                        if j != idx:
                            cnt[(cur - S[j]) % v] += 1
                            cnt[(S[j] - cur) % v] += 1
            if not improved:
                break
        if F < best_F:
            best_F = F
            best_S = S[:]
            if F == 0:
                break
    return best_S, best_F


def _rasterise(S, v, w, taper_exp, taper_cap):
    N = v * w
    h = np.zeros(N)
    for d in S:
        for c in range(w):
            x = (d * w + c) / N
            t = (x * (1 - x)) ** taper_exp
            t = min(t, taper_cap)
            h[d * w + c] = t
    return h


def _lbfgs_simple(h, N, iters, deadline):
    """Simple gradient ascent in log space using finite differences on a subsample."""
    h = np.asarray(h, dtype=float).copy()
    if h.size != N:
        return h
    best = h.copy()
    bestR = _R(h)
    eps = 1e-3
    # coordinate-wise finite diff on a random subset each iter
    rng = np.random.default_rng(0)
    for it in range(iters):
        if time.process_time() > deadline:
            break
        idxs = rng.choice(N, size=min(N, 32), replace=False)
        grad = np.zeros(N)
        for i in idxs:
            hp = h.copy(); hp[i] *= (1 + eps)
            hm = h.copy(); hm[i] *= (1 - eps)
            grad[i] = (_R(hp) - _R(hm)) / (2 * eps)
        # normalize and step
        gn = np.linalg.norm(grad)
        if gn < 1e-12:
            break
        step = 0.05
        hnew = h * np.exp(step * grad / gn)
        rnew = _R(hnew)
        if rnew > bestR:
            bestR = rnew
            best = hnew.copy()
            h = hnew
        else:
            step *= 0.5
            h = h * np.exp(step * grad / gn)
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = random.Random(12345)
    nprng = np.random.default_rng(12345)

    best_h = None
    best_R = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and np.all(s >= 0) and s.sum() > 0:
            best_h = s.copy()
            best_R = _R(s)

    # Stage 1: find difference sets
    stage1_deadline = min(deadline, t0 + 8.0)
    configs = [8, 12, 14, 18]
    found = []
    for k in configs:
        if time.process_time() > stage1_deadline:
            break
        v = k * (k - 1) + 1
        S, F = _find_diff_set(v, k, stage1_deadline, rng)
        if S is not None:
            found.append((F, k, v, S))
            print(f"diffset k={k} v={v} F={F}")

    if not found:
        # fallback: just return start or constant
        if best_h is not None:
            return best_h
        return np.ones(50)

    # pick smallest F, largest k
    found.sort(key=lambda x: (x[0], -x[1]))
    F, k, v, S = found[0]
    print(f"chosen diffset k={k} v={v} F={F}")

    # Stage 2: rasterise with taper search
    stage2_deadline = min(deadline, time.process_time() + 6.0)
    best_raster = None
    best_rasterR = -1.0
    for w in (4, 8, 16):
        N = v * w
        if N > 65536:
            continue
        for taper_exp in (0.25, 0.5, 1.0):
            for taper_cap in (1.0, 2.0):
                if time.process_time() > stage2_deadline:
                    break
                h = _rasterise(S, v, w, taper_exp, taper_cap)
                r = _R(h)
                if r > best_rasterR:
                    best_rasterR = r
                    best_raster = h
        if best_raster is not None and best_rasterR > best_R:
            best_R = best_rasterR
            best_h = best_raster.copy()
    print(f"raster best R={best_rasterR:.6f} N={best_raster.size if best_raster is not None else 0}")

    # Stage 3: ladder of L-BFGS-like refinement
    if best_h is not None:
        for mult in (4, 8, 16):
            if time.process_time() > deadline:
                break
            N = v * mult
            if N > 65536:
                continue
            # resample best_h to N
            if best_h.size != N:
                x_old = np.linspace(0, 1, best_h.size)
                x_new = np.linspace(0, 1, N)
                h = np.interp(x_new, x_old, best_h)
            else:
                h = best_h.copy()
            sub_deadline = min(deadline, time.process_time() + 4.0)
            h2 = _lbfgs_simple(h, N, 250, sub_deadline)
            r2 = _R(h2)
            print(f"ladder N={N} R={r2:.6f}")
            if r2 > best_R:
                best_R = r2
                best_h = h2.copy()

    # Stage 4: polish
    if best_h is not None:
        while time.process_time() < deadline:
            sub_deadline = min(deadline, time.process_time() + 3.0)
            h2 = _lbfgs_simple(best_h, best_h.size, 30, sub_deadline)
            r2 = _R(h2)
            if r2 > best_R:
                best_R = r2
                best_h = h2.copy()
            else:
                break

    print(f"final R={best_R:.6f} N={best_h.size if best_h is not None else 0}")
    if best_h is None:
        return np.ones(50)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs_cvar(h0, q, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_cvar(hh, q)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    h = np.diff(C)
    return np.clip(h, 0, None)


def _polish(h, deadline):
    """Full polish: tie-LBFGS then CVAR-LBFGS ladder, keeping the best."""
    best = _rescale(np.clip(h, 0, None))
    bestR = R_of(best)
    if time.process_time() >= deadline - 1.0:
        return best, bestR

    def _try(cand):
        nonlocal best, bestR
        if time.process_time() >= deadline - 0.5:
            return
        cand = _rescale(np.clip(cand, 0, None))
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()

    _try(_full_lbfgs(best, deadline, maxiter=200))
    for q in [0.05, 0.02, 0.1, 0.01]:
        if time.process_time() >= deadline - 0.6:
            break
        _try(_full_lbfgs_cvar(best, q, deadline, maxiter=150))
        _try(_full_lbfgs(best, deadline, maxiter=80))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.93 * budget_seconds

    global_best = None
    global_bestR = -1.0

    def _consider(h, r):
        nonlocal global_best, global_bestR
        if r > global_bestR:
            global_bestR = r
            global_best = h.copy()

    if start is not None and np.asarray(start).size > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0.0, None))
    else:
        p, q = 127, 43
        N = 3 * p * q
        Dp = np.unique((np.arange(p) ** 2) % p)
        Dq = np.unique((np.arange(q) ** 2) % q)
        S = np.unique((Dp[:, None] * q + Dq[None, :]).ravel()) % (p * q)
        h = np.zeros(N)
        idx = 3 * S
        idx = idx[idx < N]
        h[idx] = 1.0
        base = _rescale(np.clip(h, 0.0, None))

    _consider(base, R_of(base))

    # Ladder: polish at increasing resolutions, lift best to next level.
    Nw = base.size
    ladder = [N for N in [512, 1024, 2048, 4096, 8192, 16384, 32768] if N >= min(Nw, 512)]
    if not ladder or ladder[0] > Nw:
        ladder = [Nw] + ladder

    working = base.copy()
    for i, Nt in enumerate(ladder):
        if time.process_time() >= deadline - 1.0:
            break
        if working.size != Nt:
            working = _lift_mass_preserving(working, Nt) if Nt > working.size else _fold_back(working, Nt)
        levels_left = len(ladder) - i
        now = time.process_time()
        slice_end = now + (deadline - now) / levels_left
        cand, r = _polish(working, slice_end)
        working = cand
        _consider(cand, r)
        print(f"level N={Nt} R={r:.9f}")

    # Extra passes on the best if time remains.
    if global_best is not None:
        for _ in range(3):
            if time.process_time() >= deadline - 1.0:
                break
            cand, r = _polish(global_best, deadline)
            _consider(cand, r)

    if global_best is None:
        global_best = working
        global_bestR = R_of(working)

    print(f"final R={global_bestR:.6f} N={global_best.size}")

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and R_of(s) > global_bestR:
            return s
    return global_best

