def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolong(h):
    out = np.empty(h.size * 2)
    out[0::2] = h
    out[1::2] = h
    return out


def _polish(h, deadline, rounds=3, tie=False):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 150, cap, tie=tie)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.5)
        hp = _lbfgs_all(best, 250, cap, tie=tie)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
    return best, bestR


def _smooth(h, k):
    """Moving-average smoothing to fill tiny dips."""
    if k < 2:
        return h
    ker = np.ones(k) / k
    return np.convolve(h, ker, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.9f (N=%d)" % (baseR, base.size))

    best = base.copy()
    bestR = baseR

    # Phase A: tie-aware polish of the start (flat-top attempts).
    if time.process_time() < deadline - 20.0:
        hp, rp = _polish(best, min(deadline - 15.0, time.process_time() + 8.0),
                         rounds=2, tie=True)
        print("tie polish R=%.9f" % rp)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp

    # Phase B: prolong + polish with tie handling several times.
    for _ in range(4):
        if best.size >= 500000 or time.process_time() >= deadline - 12.0:
            break
        hN = _prolong(best)
        cap = min(deadline - 10.0, time.process_time() + 6.0)
        hN, rN = _polish(hN, cap, rounds=2, tie=True)
        print("prolong+polish R=%.9f (N=%d)" % (rN, hN.size))
        if rN > bestR + 1e-14:
            best, bestR = hN, rN
        else:
            break

    # Phase C: smoothing perturbations to escape shallow minima.
    rng = np.random.RandomState(12345)
    M = best.size
    while time.process_time() < deadline - 4.0:
        hmod = best.copy()
        k = rng.choice([3, 5, 9, 17, 33])
        hmod = _smooth(hmod, int(k))
        hmod = _rescale(hmod)
        cap = min(deadline - 3.0, time.process_time() + 3.0)
        ht = _lbfgs_all(hmod, 200, cap, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("  smooth improve %.9f" % bestR)

    # Phase D: final tie-aware polish of peak window + all-pos.
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        hb = _lbfgs_block(best, _peak_window(best), 300, cap, tie=True)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb

    print("final best=%.9f (N=%d) start=%.9f" % (bestR, best.size, start_bestR))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

