    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    if logspace:
        hmax = h.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        x0 = np.log(np.clip(x0, floor, None))

        def f(x):
            hh = h.copy()
            hh[active] = np.exp(np.clip(x, -40.0, 40.0))
            val, g = fg(hh)
            return val, g[active] * hh[active]

        bounds = [(-40.0, 40.0)] * active.size

        def unpack(x):
            hh = h.copy()
            hh[active] = np.exp(np.clip(x, -40.0, 40.0))
            return hh
    else:
        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g[active]

        bounds = [(0.0, None)] * active.size

        def unpack(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            return hh

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(unpack(res.x))


def _peak_window(h, tol=0.9995, pad_frac=0.35, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    print("base R=%.12f (N=%d)" % (baseR, base.size))

    bestH = base.copy()
    bestR = baseR
    altH = base.copy()
    altR = baseR

    cur = base.copy()
    curR = baseR

    def try_improve(cur, curR, free, iters, beta, tcap):
        if time.process_time() >= deadline - 1.0:
            return cur, curR
        cap = min(deadline - 0.6, time.process_time() + tcap)
        h2 = _lbfgs_block(cur, free, iters, cap, beta=beta)
        r2 = R_of(h2)
        if r2 > curR + 1e-14:
            return h2, r2
        return cur, curR

    # Phase 1: polish current resolution using log-space on peak window,
    # then wider windows, then a global log-space pass.
    n = cur.size
    pw = _peak_window(cur, tol=0.9995, pad_frac=0.5, extra=max(128, n // 64))
    if time.process_time() < deadline - 3.0:
        cap = min(deadline - 1.0, time.process_time() + 8.0)
        h2 = _lbfgs_block(cur, pw, 400, cap, beta=0.0, logspace=True)
        r2 = R_of(h2)
        if r2 > curR + 1e-14:
            cur, curR = h2, r2
            if curR > bestR:
                bestH, bestR = cur.copy(), curR
            print("  log polish N=%d R=%.12f" % (cur.size, curR))

    # Phase 2: resolution doubling with mass-preserving lift and log-space polish
    while time.process_time() < deadline - 3.0 and cur.size < 1_000_000:
        N2 = min(cur.size * 2, 1_000_000)
        h2 = _lift_mass_preserving(cur, N2)
        h2 = _rescale(h2)
        r2 = R_of(h2)
        pw2 = _peak_window(h2, tol=0.9995, pad_frac=0.6, extra=max(256, N2 // 64))
        cap = min(deadline - 1.0, time.process_time() + 10.0)
        h3 = _lbfgs_block(h2, pw2, 400, cap, beta=0.0, logspace=True)
        r3 = R_of(h3)
        if r3 > r2:
            h2, r2 = h3, r3
        # also try a soft-max pass
        if time.process_time() < deadline - 2.0:
            cap = min(deadline - 0.8, time.process_time() + 5.0)
            h4 = _lbfgs_block(h2, pw2, 300, cap, beta=5e3, logspace=True)
            r4 = R_of(h4)
            if r4 > r2:
                h2, r2 = h4, r4
        if r2 > curR + 1e-13:
            cur, curR = h2, r2
            if curR > bestR:
                bestH, bestR = cur.copy(), curR
            print("  doubled N=%d R=%.12f" % (cur.size, curR))
        else:
            if r2 > altR:
                altH, altR = h2, r2
            break

    # Phase 3: final polish at highest resolution: global log-space alternating
    # with peak-window log-space, until deadline.
    while time.process_time() < deadline - 1.5:
        n = cur.size
        pw = _peak_window(cur, tol=0.9995, pad_frac=0.7, extra=max(128, n // 48))
        cap = min(deadline - 0.8, time.process_time() + 6.0)
        h2 = _lbfgs_block(cur, pw, 300, cap, beta=0.0, logspace=True)
        r2 = R_of(h2)
        if r2 > curR + 1e-14:
            cur, curR = h2, r2
        else:
            cur, curR = h2, r2  # accept even if tiny change to escape
        if curR > bestR + 1e-14:
            bestH, bestR = cur.copy(), curR
            print("  polish N=%d R=%.12f" % (cur.size, curR))
        if time.process_time() >= deadline - 1.5:
            break
        # occasional wide global pass
        if n <= 40000:
            free = np.arange(n)
        else:
            mask = np.zeros(n, dtype=bool)
            mask[::2] = True
            mask[pw] = True
            free = np.flatnonzero(mask)
        cap = min(deadline - 0.5, time.process_time() + 6.0)
        h3 = _lbfgs_block(cur, free, 200, cap, beta=0.0, logspace=True)
        r3 = R_of(h3)
        if r3 > bestR + 1e-14:
            cur, curR = h3, r3
            bestH, bestR = h3.copy(), r3
            print("  global N=%d R=%.12f" % (cur.size, r3))
        else:
            if r3 > altR:
                altH, altR = h3, r3

    if bestR > baseR + 1e-13:
        print("final R=%.12f (N=%d) gain=%+.2e" % (bestR, bestH.size, bestR - baseR))
        if altR > bestR:
            return {"best": altH, "alternative": bestH}
        return {"best": bestH, "alternative": altH}
    else:
        print("no gain, R=%.12f" % baseR)
        return {"best": base, "alternative": altH if altR > baseR else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_window_polish(h, deadline, pad=3, maxiter=100):
    if time.process_time() >= deadline - 0.3:
        return h
    win = _peak_window(h, pad_frac=0.0, extra=pad * 32)
    h2 = _lbfgs_block(h, win, maxiter, deadline)
    return h2


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lift(h, N2):
    """Mass-preserving cumulative-sum interpolation to N2 steps."""
    N = h.size
    if N2 == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    # total mass preserved; sample cumulative at N2+1 points
    xs = np.linspace(0.0, N, N2 + 1)
    cs = np.interp(xs, np.arange(N + 1), c)
    h2 = np.diff(cs)
    return _rescale(np.clip(h2, 0, None))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _max_mean(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(mx / Lf.mean())


def _stats(h):
    return (_frac_near_max(h, 1e-3), _frac_near_max(h, 1e-2),
            _frac_near_max(h, 5e-2), _max_mean(h))


def _report(tag, h, r):
    f01, f1, f5, mm = _stats(h)
    zf = float(np.mean(h <= 0))
    print("%s R=%.12f nm 0.1/1/5%%=%.4f/%.4f/%.4f mm=%.2f zf=%.3f"
          % (tag, r, f01, f1, f5, mm, zf))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    _report("before", best, bestR)

    incumbent = best.copy()
    incR = bestR

    # ---- resolution ladder: lift and refine at each N2 ----
    targets = [65536, 98304, 131072, 163840]
    for N2 in targets:
        if time.process_time() >= deadline - 8.0:
            break
        h_lift = _lift(incumbent, N2)
        r_lift = R_of(h_lift)
        _report("lift N=%d" % N2, h_lift, r_lift)
        # full L-BFGS up to 10 s
        t_end = min(deadline - 7.0, time.process_time() + 10.0)
        h_ref = _full_lbfgs(h_lift, t_end, maxiter=300)
        r_ref = R_of(h_ref)
        _report("  lbfgs N=%d" % N2, h_ref, r_ref)
        # peak window polish up to 4 s
        if time.process_time() < deadline - 6.0:
            t_end2 = min(deadline - 6.0, time.process_time() + 4.0)
            h_pk = _peak_window_polish(h_ref, t_end2, pad=3, maxiter=150)
            r_pk = R_of(h_pk)
            _report("  peak N=%d" % N2, h_pk, r_pk)
            if r_pk > r_ref:
                h_ref, r_ref = h_pk, r_pk
        if r_ref > incR + 1e-12:
            incumbent, incR = h_ref.copy(), r_ref
            print("  ACCEPT lift N=%d R=%.12f" % (N2, incR))
        else:
            print("  reject lift N=%d (%.12f vs %.12f)" % (N2, r_ref, incR))

    # ---- final full L-BFGS on incumbent with remaining time ----
    if time.process_time() < deadline - 1.0:
        h_fin = _full_lbfgs(incumbent, deadline - 0.5, maxiter=400)
        r_fin = R_of(h_fin)
        _report("final lbfgs", h_fin, r_fin)
        if r_fin > incR + 1e-15:
            incumbent, incR = h_fin, r_fin

    if incR < startR:
        incumbent = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        incR = startR

    _report("after", incumbent, incR)
    print("final R=%.12f (start %.12f, N=%d)"
          % (incR, startR, incumbent.size))

    result = {"best": incumbent}
    if incR <= startR + 1e-14 and start is not None:
        result["alternative"] = incumbent
    return result

