def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_period(h, maxT=64):
    n = h.size
    for T in range(2, maxT + 1):
        if n % T != 0:
            continue
        K = n // T
        bm = h.reshape(K, T).mean(axis=1)
        rep = np.repeat(bm, T)
        if np.max(np.abs(h - rep)) < 1e-9:
            return T, K
    return None, None


def _tri_kernel(T):
    j = np.arange(2 * T + 1, dtype=float)
    tri = np.where(j <= T, j, 2 * T - j)
    return tri


def _build_L_from_c(c, T, tri):
    K = c.size
    u = np.convolve(c, c)
    up = np.zeros((2 * K - 1 - 1) * T + 1)
    up[::T] = u
    L = np.convolve(up, tri)
    return L


def _R_fast(c, T, tri):
    K = c.size
    if c.sum() <= 0:
        return 0.0, None
    L = _build_L_from_c(c, T, tri)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    s = c.sum() * T
    den = s * s * L.max()
    if den <= 0:
        return 0.0, None
    return num / den, L


def _R_fast_grad(c, T, tri):
    K = c.size
    if c.sum() <= 0:
        return 0.0, np.zeros(K)
    L = _build_L_from_c(c, T, tri)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    s = c.sum() * T
    Lm = L.max()
    if Lm <= 0 or num <= 0:
        return 0.0, np.zeros(K)
    dq = np.zeros_like(L)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    gL = -dq / num
    m = int(np.argmax(L))
    gL[m] += 1.0 / Lm
    g_up = np.correlate(gL, tri, mode='valid')
    g_u = g_up[::T][:2 * K - 1]
    g_c = 2.0 * np.correlate(g_u, c, mode='valid')[:K]
    g_c = g_c + 2.0 * T / s
    R = num / (s * s * Lm)
    return R, g_c


def _gauss_kernel(sigma):
    if sigma <= 0:
        return np.array([1.0])
    r = int(np.ceil(4 * sigma))
    x = np.arange(-r, r + 1, dtype=float)
    g = np.exp(-0.5 * (x / sigma) ** 2)
    g /= g.sum()
    return g


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N = best.size
    alternative = None
    T, K = _detect_period(best)

    if T is not None and T >= 2:
        print("detected period T=%d K=%d" % (T, K))
        H = best.reshape(K, T)
        c = H.mean(axis=1)
        tri = _tri_kernel(T)
        Rf, _ = _R_fast(c, T, tri)
        diff = abs(Rf - bestR)
        print("R_fast(c)=%.12f vs R_of(h)=%.12f diff=%.3e" % (Rf, bestR, diff))
        if diff > 1e-8:
            print("fast evaluator mismatch, skipping reduced phase")
            T = None

    if T is not None and T >= 2:
        tri = _tri_kernel(T)
        c_cur = best.reshape(K, T).mean(axis=1).copy()

        # Phase B: sigma annealing on reduced problem, cheap
        for sigma in [4.0, 2.0, 1.0, 0.5, 0.0]:
            if time.process_time() >= deadline - 8.0:
                break
            G = _gauss_kernel(sigma)

            def fg(x, G=G):
                cvec = np.exp(x)
                if G.size == 1:
                    cb = cvec
                else:
                    cb = np.convolve(cvec, G, mode='same')
                R, gc = _R_fast_grad(cb, T, tri)
                if R <= 0:
                    return 1e18, np.zeros_like(x)
                if G.size > 1:
                    gc = np.convolve(gc, G, mode='same')
                return -np.log(R), -gc * cvec

            x0 = np.log(np.clip(c_cur, 1e-12, None))
            cb = _make_cb(min(deadline - 6.0, time.process_time() + 4.0))
            try:
                res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                               callback=cb,
                               options={'maxiter': 400, 'maxfun': 800,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                if res is not None and np.all(np.isfinite(res.x)):
                    c_cur = np.exp(res.x)
            except (TimeoutError, Exception):
                pass
            h_new = _rescale(np.repeat(c_cur, T))
            rn = R_of(h_new)
            if rn > bestR + 1e-15:
                best, bestR = h_new, rn
                print("sigma=%.1f new best R=%.12f" % (sigma, bestR))

        # Phase C: alternating polish
        round_i = 0
        while time.process_time() < deadline - 2.0:
            round_i += 1
            tlim = min(deadline - 1.5, time.process_time() + 4.0)
            pol = _lbfgs_block(best, np.arange(best.size), 200, tlim, tie=True)
            rp = R_of(pol)
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp
                c_cur = best.reshape(K, T).mean(axis=1)
            if time.process_time() >= deadline - 2.0:
                break
            # reduced rung
            def fg0(x):
                cvec = np.exp(x)
                R, gc = _R_fast_grad(cvec, T, tri)
                if R <= 0:
                    return 1e18, np.zeros_like(x)
                return -np.log(R), -gc * cvec
            x0 = np.log(np.clip(c_cur, 1e-12, None))
            cb = _make_cb(min(deadline - 1.5, time.process_time() + 3.0))
            try:
                res = minimize(fg0, x0, jac=True, method='L-BFGS-B',
                               callback=cb,
                               options={'maxiter': 300, 'maxfun': 600,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                if res is not None and np.all(np.isfinite(res.x)):
                    c_cur = np.exp(res.x)
            except (TimeoutError, Exception):
                pass
            h_new = _rescale(np.repeat(c_cur, T))
            rn = R_of(h_new)
            if rn > bestR + 1e-15:
                best, bestR = h_new, rn
            print("round %d: best=%.12f c_rung=%.12f" % (round_i, bestR, rn))
            if round_i >= 20:
                break

        alt_h = _rescale(np.repeat(c_cur, T))
        ar = R_of(alt_h)
        if ar > startR + 1e-14 and ar < bestR - 1e-14:
            alternative = alt_h
    else:
        # No period: flat full polish loop
        while time.process_time() < deadline - 1.0:
            tlim = min(deadline - 0.8, time.process_time() + 5.0)
            pol = _lbfgs_block(best, np.arange(best.size), 300, tlim, tie=True)
            rp = R_of(pol)
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp
                print("polish new best R=%.12f" % bestR)
            else:
                break

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alternative is not None:
        result["alternative"] = alternative
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return float(num / den)


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]
    b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, pos_only=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if pos_only:
        pos = np.flatnonzero(h > 0)
        if pos.size == 0:
            return h0
    else:
        pos = np.arange(h.size)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    x0 = np.log(np.clip(h[pos], floor, None))

    def f(x):
        hh = h.copy()
        hh[pos] = np.exp(np.clip(x, -40.0, 40.0))
        if beta > 0:
            val, g = _fun_grad_beta(hh, beta)
        else:
            val, g = _fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lbfgs_block(h0, active, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lift(h, N):
    """Mass-preserving cumulative-sum linear lift to length N."""
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N + 1, dtype=float) * (M / N)
    C2 = np.interp(x, np.arange(M + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.maximum(h2, 0.0)


def _peak_window(h, tol=0.999, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    def time_left():
        return time.process_time() < deadline

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = R_of(best)

    if best is None:
        best = np.ones(64)
        bestR = R_of(best)

    alt = None
    altR = -1.0

    def try_accept(cand):
        nonlocal best, bestR, alt, altR
        rc = R_of(cand)
        if rc > bestR + 1e-14:
            bestR = rc
            best = cand.copy()
            return True
        if rc > altR + 1e-14 and rc < bestR - 1e-9:
            altR = rc
            alt = cand.copy()
        return False

    h = best.copy()

    # Multi-resolution refinement. Start from current resolution and
    # escalate; also refresh from best periodically.
    cur_n = h.size
    levels = [cur_n]
    for N in (8000, 32000, 96000, 200000, 400000):
        if N > cur_n:
            levels.append(N)
    # Cap upper bound if we started already large
    levels = [N for N in levels if N <= 400000]

    for li, N in enumerate(levels):
        if not time_left():
            break
        if N != h.size:
            h = _lift(h, N)
            try_accept(h)
        it = 1000 if li == 0 else 500
        it_s = 250 if li == 0 else 150
        if time_left():
            c = _lbfgs_log(h, it, deadline)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)
        for beta in (50, 300, 1500, 8000):
            if not time_left():
                break
            c = _lbfgs_log(h, it_s, deadline, beta=beta)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)
        for tol, pad in ((0.9995, 0.5), (0.999, 0.6), (0.995, 0.8)):
            if not time_left():
                break
            win = _peak_window(h, tol=tol, pad_frac=pad, extra=max(8, N // 400))
            for beta in (0.0, 500.0, 5000.0):
                if not time_left():
                    break
                c = _lbfgs_block(h, win, it_s, deadline, beta=beta)
                if R_of(c) > R_of(h):
                    h = c
                try_accept(h)

    # Polishing loop on best.
    fracs = (0.10, 0.25, 0.40, 0.15, 0.55)
    fi = 0
    while time_left():
        c = _lbfgs_log(best, 400, deadline)
        if R_of(c) > R_of(best):
            best = c
            bestR = R_of(best)
        else:
            try_accept(c)
        if not time_left():
            break
        n = best.size
        f = fracs[fi % len(fracs)]
        fi += 1
        L = _knots(best)
        k = int(np.argmax(L))
        half = max(2, int(f * n))
        lo = max(0, (k - half) // 2 - 16)
        hi = min(n, (k + half) // 2 + 17)
        if hi - lo >= 2:
            c = _lbfgs_block(best, np.arange(lo, hi), 300, deadline)
            if R_of(c) > R_of(best):
                best = c
                bestR = R_of(best)
            else:
                try_accept(c)
        if not time_left():
            break
        c = _lbfgs_log(best, 300, deadline, beta=3000.0)
        if R_of(c) > R_of(best):
            best = c
            bestR = R_of(best)
        else:
            try_accept(c)

    if alt is not None and altR > 0 and altR < bestR - 1e-9:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = int(np.ceil((1.0 - q) * n))
    if m < 1:
        m = 1
    if m > n:
        m = n
    order = np.argsort(Lf)
    top = order[-m:]
    mean_top = Lf[top].mean()
    if mean_top <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[top] += (1.0 / m) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_cvar(h0, q, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_cvar(hh, q)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def _upsample(h, factor):
    """Refine a step function by linear interpolation onto a finer grid,
    preserving mass. This lets us move to a larger N and continue polishing."""
    n = h.size
    if factor <= 1:
        return h.copy()
    m = n * factor
    # sample original piecewise-constant at cell centers of new grid
    x = (np.arange(m) + 0.5) / m * n  # in old cell units
    i0 = np.floor(x).astype(int)
    frac = x - i0
    i0 = np.clip(i0, 0, n - 1)
    i1 = np.clip(i0 + 1, 0, n - 1)
    out = h[i0] * (1.0 - frac) + h[i1] * frac
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    # ---- CVaR q-anneal ladder (smooths the max, then tightens) ----
    qs = (0.90, 0.95, 0.98, 0.995, 0.999)
    cvar_deadline = t0 + budget_seconds * 0.45
    per_q = budget_seconds * 0.08
    for q in qs:
        if time.process_time() >= cvar_deadline - 1.0:
            break
        dq = min(cvar_deadline, time.process_time() + per_q)
        ht = _lbfgs_cvar(best, q, 20, dq)
        r = R_of(ht)
        tf = _top_frac_mean(ht, 0.01)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("cvar q=%.3f NEW BEST R=%.9f top1%%=%.9f nearmax5=%.4f"
                  % (q, bestR, tf, _nearmax_frac(best)))
        else:
            print("cvar q=%.3f no gain (R=%.9f vs %.9f, top1%%=%.9f)"
                  % (q, r, bestR, tf))

    # ---- Main improvement: upsampling ladder ----
    # The construction is a step function; refining to more steps gives the
    # optimiser more freedom, which historically helps push R up. We refine
    # progressively and re-polish at each resolution, keeping the best.
    h_up = best.copy()
    upR = bestR
    # Try a couple of upsampling factors within budget.
    for factor in (2, 2):
        remaining = deadline - time.process_time()
        if remaining < budget_seconds * 0.15:
            break
        if h_up.size * factor > 1000000:
            break
        cand = _upsample(h_up, factor)
        cand = _rescale(cand)
        # quick polish at new resolution
        pd = min(deadline, time.process_time() + remaining * 0.45)
        ht = _lbfgs_all_pos(cand, 300, pd)
        r = R_of(ht)
        if r > upR + 1e-15:
            h_up, upR = ht.copy(), r
            print("upsample x%d ACCEPT R=%.9f (N=%d, nearmax5=%.4f)"
                  % (factor, upR, h_up.size, _nearmax_frac(h_up)))
        else:
            print("upsample x%d no gain (R=%.9f vs %.9f, N=%d)"
                  % (factor, r, upR, cand.size))
        if upR > bestR + 1e-15:
            best, bestR = h_up.copy(), upR

    # ---- loop: full polish + peak-window polish on best ----
    loop = 0
    while time.process_time() < deadline - 2.0:
        loop += 1
        fd = min(deadline, time.process_time() + budget_seconds * 0.12)
        ht = _lbfgs_all_pos(best, 200, fd)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("loop %d tie-polish ACCEPT R=%.9f top1%%=%.9f"
                  % (loop, bestR, _top_frac_mean(best, 0.01)))
        if time.process_time() >= deadline - 1.5:
            break
        fd2 = min(deadline, time.process_time() + budget_seconds * 0.12)
        win = _peak_window(best, tol=0.95, pad_frac=0.10, extra=128)
        # window block polish: reuse all_pos on a slice by zeroing outside
        # (kept simple: full polish already covers this, so use cvar tighten)
        ht = _lbfgs_cvar(best, 0.9999, 20, fd2)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("loop %d tighten ACCEPT R=%.9f top1%%=%.9f"
                  % (loop, bestR, _top_frac_mean(best, 0.01)))

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        return _rescale(np.clip(res.x, 0.0, None))
    except Exception:
        return h0


def _peak_window_polish(h, deadline, pad=8, win_frac=0.25, maxiter=300):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return h
    lo = idx.min(); hi = idx.max()
    span = hi - lo + 1
    half = max(span, int(win_frac * h.size))
    lo = max(0, lo - half - pad)
    hi = min(h.size - 1, hi + half + pad)
    active = np.arange(lo, hi + 1)
    hh = h.copy()
    x0 = hh[active].copy()

    def f(x):
        tmp = hh.copy()
        tmp[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(tmp)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = hh.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)
    except Exception:
        return h


def _upsample_mass(h, N2):
    N = len(h)
    c = np.concatenate([[0.0], np.cumsum(h)])
    xs = np.arange(N2 + 1) * (N / N2)
    cm = np.interp(xs, np.arange(N + 1), c)
    new = np.diff(cm) * (N2 / N)
    if new.sum() <= 0:
        return np.ones(N2)
    return np.clip(new, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    best = np.ones(50)
    best_R = R_of(best)
    if start is not None:
        try:
            s = np.asarray(start, dtype=float)
            r = R_of(s)
            if r > best_R:
                best = s.copy(); best_R = r
        except Exception:
            pass

    def consider(h):
        nonlocal best, best_R
        if h is None:
            return False
        h = np.asarray(h, dtype=float)
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return False
        r = R_of(h)
        if r > best_R + 1e-10:
            best_R = r
            best = h.copy()
            return True
        return False

    # Phase 1: polish start
    cur = best.copy()
    for _ in range(2):
        if time.process_time() > deadline - 3:
            break
        nxt = _full_lbfgs(cur, 400, min(deadline - 1.0, time.process_time() + 10))
        if R_of(nxt) > R_of(cur):
            cur = nxt
        else:
            break
    consider(cur)

    # Phase 2: ladder 51200, 102400
    for target_N in (51200, 102400):
        if time.process_time() > deadline - 3:
            break
        if target_N <= best.size:
            continue
        remain = deadline - time.process_time()
        level_deadline = min(deadline - 1.0, time.process_time() + remain / 2.0)
        cur = _upsample_mass(best, target_N)
        cur = _rescale(cur)
        cur = _full_lbfgs(cur, 600, min(level_deadline, time.process_time() + 20))
        cur = _peak_window_polish(cur, level_deadline, pad=8, win_frac=0.25, maxiter=400)
        consider(cur)
        print(f"ladder N={cur.size} R={R_of(cur):.6f}")

    # Phase 3: alternate full + wide polish at best N
    while time.process_time() < deadline - 2:
        cur = best.copy()
        cur = _full_lbfgs(cur, 400, min(deadline - 1.0, time.process_time() + 8))
        consider(cur)
        if time.process_time() > deadline - 2:
            break
        cur = _peak_window_polish(best.copy(), min(deadline - 1.0, time.process_time() + 8),
                                  pad=8, win_frac=1.0 / 3.0, maxiter=400)
        consider(cur)
        if time.process_time() > deadline - 2:
            break

    # Final polish
    if time.process_time() < deadline - 1:
        try:
            nxt = _full_lbfgs(best.copy(), 400, deadline - 0.5)
            consider(nxt)
        except Exception:
            pass

    if best is None:
        best = np.ones(50)
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    r = Lf / mx
    rp = np.power(np.clip(r, 1e-300, None), p)
    Z = rp.sum()
    sm = mx * np.power(Z, 1.0 / p)
    w = rp / Z
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, p=0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if p > 0:
        fg = (lambda hh: _fun_grad_pnorm(hh, p))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, p=0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if p > 0:
        fg = (lambda hh: _fun_grad_pnorm(hh, p))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, p=0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, p=p)


def _polish(h, deadline, caps):
    cur = h
    curR = R_of(cur)
    for (maxiter, p) in caps:
        if time.process_time() >= deadline - 0.5:
            break
        sub = min(deadline - 0.3, time.process_time() + 8.0)
        hn = _lbfgs_log(cur, maxiter, sub, p=p)
        rn = R_of(hn)
        if rn > curR + 1e-14:
            cur, curR = hn, rn
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 0.5:
            break
        sub = min(deadline - 0.3, time.process_time() + 5.0)
        hn = _window_polish_peak(cur, sub, frac, 32, maxiter=120, p=0)
        rn = R_of(hn)
        if rn > curR + 1e-14:
            cur, curR = hn, rn
    return cur, curR


def _stats(h):
    return (h.size, 100.0 * np.mean(h <= 0),
            h.max() / max(h.mean(), 1e-300))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    n0, z0, mm0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%, max/mean %.1f)" %
          (bestR, n0, z0, mm0))

    cur = best
    curR = bestR

    # -------- Phase A: refine at the existing resolution --------
    if time.process_time() < deadline - 20.0:
        caps = [(200, 0), (200, 0), (120, 16), (120, 48)]
        sub = min(deadline - 20.0, time.process_time() + 12.0)
        hp, rp = _polish(cur, sub, caps)
        if rp > curR + 1e-14:
            cur, curR = hp, rp
        print("  refine0 R=%.7f (N=%d)" % (curR, cur.size))

    # -------- Phase B: doubling then polish at higher resolution --------
    for level in range(4):
        remain = deadline - time.process_time()
        if remain < 6.0:
            break
        # only double if we still have room
        h2 = np.repeat(cur, 2)
        r2 = R_of(h2)
        if r2 < curR - 1e-9:
            # doubling lost accuracy; still try to polish from doubled
            pass
        # time-box polish at this level; give more time at higher levels
        budget_here = min(remain - 3.0, 5.0 + 3.0 * level)
        sub = min(deadline - 3.0, time.process_time() + budget_here)
        # quick log polish then a pnorm attempt to spread the peak
        hq = _lbfgs_log(h2, 200, sub, p=0)
        rq = R_of(hq)
        if rq < r2:
            hq, rq = h2, r2
        if time.process_time() < sub - 0.5:
            sub2 = min(deadline - 3.0, time.process_time() + max(2.0, budget_here * 0.5))
            hb = _lbfgs_log(hq, 120, sub2, p=64)
            rb = R_of(hb)
            if rb > rq:
                hq, rq = hb, rb
        n2, z2, mm2 = _stats(hq)
        print("  dbl%d R=%.7f (N=%d, zeros %.1f%%, max/mean %.1f)" %
              (level, rq, n2, z2, mm2))
        if rq > curR + 1e-12:
            cur, curR = hq, rq
        else:
            # higher resolution didn't help; stop doubling
            break
        if curR > bestR + 1e-12:
            best, bestR = cur, curR

    # -------- Phase C: final heavy polish at best resolution --------
    if time.process_time() < deadline - 1.0:
        caps = [(300, 0), (200, 0), (150, 16), (150, 64), (100, 256)]
        sub = deadline - 0.5
        hp, rp = _polish(cur, sub, caps)
        if rp > curR + 1e-14:
            cur, curR = hp, rp
        if curR > bestR + 1e-12:
            best, bestR = cur, curR

    nf, zf, mmf = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%, max/mean %.1f)" %
          (bestR, nf, zf, mmf))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    return {"best": start_best, "alternative": best}

