    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _log_lbfgs(h0, deadline, maxiter=150, free=None):
    """L-BFGS on log-heights (positivity-preserving, smooth)."""
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if free is None:
        pos = np.flatnonzero(h > 0)
    else:
        pos = np.intersect1d(np.flatnonzero(h > 0), np.asarray(free, dtype=int))
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad=4):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - pad)
    hi = min(h.size - 1, idx.max() + pad)
    return np.arange(lo, hi + 1)


def _lift(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    return np.clip(np.diff(C2), 0, None)


def _polish(h, deadline, budget=200):
    """Alternate log-LBFGS on whole array and on peak window."""
    best = h.copy()
    bestR = R_of(best)
    # Whole-array log polish
    if time.process_time() < deadline - 0.5:
        ht = _log_lbfgs(best, min(deadline - 0.3, time.process_time() + budget * 0.6), 200)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
    # Peak-window log polish (finer)
    for _ in range(3):
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, tol=0.999, pad=8)
        ht = _log_lbfgs(best, min(deadline - 0.3, time.process_time() + budget * 0.4),
                        120, free=win)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
        else:
            break
    return best, bestR


def _mirror_extend(best, r, deadline):
    S = np.flatnonzero(best > 0)
    if S.size == 0:
        return best, R_of(best)
    i0 = int(S.min()); i1 = int(S.max())
    L = min(8000, i1 - i0 + 1)
    if L <= 0:
        return best, R_of(best)
    left_ext = best[i0 + 1: min(i0 + L + 1, best.size)][::-1] * r
    right_ext = best[max(i1 - L, 0): i1][::-1] * r
    h_new = np.concatenate([left_ext, best, right_ext])
    h_new = _rescale(np.clip(h_new, 0, None))
    nL = left_ext.size
    nB = best.size
    halo = 400
    idxs = []
    if nL > 0:
        idxs.append(np.arange(0, nL))
        lo = max(0, nL - halo); hi = min(h_new.size - 1, nL + halo)
        idxs.append(np.arange(lo, hi + 1))
    if nB > 0:
        lo = max(0, nL + nB - halo); hi = min(h_new.size - 1, nL + nB + halo)
        idxs.append(np.arange(lo, hi + 1))
        if right_ext.size > 0:
            idxs.append(np.arange(nL + nB, h_new.size))
    free = np.unique(np.concatenate(idxs)) if idxs else np.arange(h_new.size)
    ht = _log_lbfgs(h_new, deadline - 1.0, 300, free=free)
    return ht, R_of(ht)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240101)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: aggressive log-space polish on start
    if time.process_time() < deadline - 3.0:
        best, bestR = _polish(best, deadline - 3.0, budget=20.0)
        print("polish1 R=%.7f N=%d" % (bestR, best.size))

    # Phase 2: mirror continuation experiments with log polish
    for r in [0.5, 0.75, 1.0, 0.3]:
        if time.process_time() >= deadline - 2.5:
            break
        try:
            ht, rt = _mirror_extend(best, r, deadline - 1.5)
        except Exception:
            continue
        print("mirror r=%.2f R=%.7f dR=%+.7f N=%d" %
              (r, rt, rt - bestR, ht.size))
        if rt > bestR + 1e-13:
            best, bestR = ht.copy(), rt
            if time.process_time() < deadline - 2.0:
                best, bestR = _polish(best, deadline - 1.5, budget=12.0)
                print("  post-mirror R=%.7f" % bestR)

    # Phase 3: resolution lift experiments
    if time.process_time() < deadline - 2.0:
        for fac in [1.5, 2.0, 3.0]:
            if time.process_time() >= deadline - 2.0:
                break
            try:
                N2 = int(best.size * fac)
                if N2 > 900000:
                    N2 = 900000
                hl = _lift(best, N2)
                ht = _log_lbfgs(hl, deadline - 1.5, 150)
                rt = R_of(ht)
                print("lift fac=%.1f R=%.7f dR=%+.7f N=%d" %
                      (fac, rt, rt - bestR, ht.size))
                if rt > bestR + 1e-13:
                    best, bestR = ht, rt
                    best, bestR = _polish(best, deadline - 1.0, budget=10.0)
                    print("  post-lift R=%.7f" % bestR)
                    break
            except Exception:
                continue

    # Phase 4: keep polishing until deadline
    while time.process_time() < deadline - 0.8:
        prev = bestR
        best, bestR = _polish(best, deadline - 0.5, budget=6.0)
        if bestR <= prev + 1e-13:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-5:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _resample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xo = np.linspace(0.0, 1.0, n)
    xn = np.linspace(0.0, 1.0, N)
    return np.clip(np.interp(xn, xo, h), 0.0, None)


def _lift_mass(h, N2):
    """Mass-preserving lift: integrate, resample cumulative mass, differentiate."""
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def _peak_window_polish(h, deadline, pad_frac=0.15):
    """Polish only the region of h that determines the peak of f*f."""
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    n = h.size
    c_lo = max(0, idx.min() // 2)
    c_hi = min(n, idx.max() // 2 + 2)
    pad = max(64, int(pad_frac * n))
    lo = max(0, c_lo - pad)
    hi = min(n, c_hi + pad)
    free = np.arange(lo, hi)
    return _lbfgs_block(h, free, 400, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR

    bestH = best.copy()
    bestRH = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    # ===== Stage 1: mass-preserving lift to a higher resolution + polish =====
    # The key new idea: the optimum is a smooth-ish shape with a sharp peak region.
    # A mass-preserving lift (integrate -> resample cumulative -> differentiate)
    # preserves R exactly at the continuous level while doubling resolution,
    # then a short sharp polish exploits the finer grid.
    n0 = bestH.size
    for factor in (2, 4):
        if time.process_time() > deadline - 20.0:
            break
        N2 = min(1000000, n0 * factor)
        if N2 == bestH.size:
            continue
        hL = _rescale(_lift_mass(bestH, N2))
        rL = R_of(hL)
        # short sharp polish on the lifted grid
        sub_dl = min(deadline - 12.0, time.process_time() + 8.0)
        hP = _lbfgs_log(hL, 300, sub_dl)
        rP = R_of(hP)
        if rP > rL:
            hL, rL = hP, rP
        print("  lift x%d -> R=%.7f (best %.7f)" % (factor, rL, bestRH))
        if rL > bestRH + 1e-13:
            bestH, bestRH = hL.copy(), rL
            print("    LIFT ACCEPT R=%.7f N=%d" % (bestRH, bestH.size))

    # ===== Stage 2: peak-window polish (the crux) + soft-max escape =====
    while time.process_time() < deadline - 3.0:
        before = bestRH
        sub_dl = min(deadline - 2.0, time.process_time() + 6.0)
        hb = _peak_window_polish(bestH, sub_dl)
        rb = R_of(hb)
        if rb > bestRH + 1e-13:
            bestH, bestRH = hb.copy(), rb
            print("  peak ACCEPT R=%.7f" % bestRH)
            continue
        # global sharp polish
        sub_dl = min(deadline - 1.5, time.process_time() + 5.0)
        h = _lbfgs_log(bestH, 400, sub_dl)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
            print("  sharp ACCEPT R=%.7f" % bestRH)
            continue
        # soft-max escape on plateau
        moved = False
        for beta in (1e2, 1e3, 1e4):
            if time.process_time() > deadline - 2.0:
                break
            sub_dl = min(deadline - 1.0, time.process_time() + 2.5)
            hb2 = _lbfgs_log(bestH, 150, sub_dl,
                             fg=lambda hh, b=beta: _fun_grad_beta(hh, b))
            rb2 = R_of(hb2)
            if rb2 > bestRH + 1e-13:
                bestH, bestRH = hb2.copy(), rb2
                print("  beta=%.0e ACCEPT R=%.7f" % (beta, bestRH))
                moved = True
                break
        if not moved and bestRH <= before + 1e-13:
            # no progress at all: one more mass-preserving lift + polish
            if bestH.size < 400000 and time.process_time() < deadline - 10.0:
                N2 = min(400000, bestH.size * 2)
                hL = _rescale(_lift_mass(bestH, N2))
                sub_dl = min(deadline - 6.0, time.process_time() + 6.0)
                hP = _lbfgs_log(hL, 300, sub_dl)
                rP = R_of(hP)
                if rP > bestRH + 1e-13:
                    bestH, bestRH = hP, rP
                    print("  relaunch-lift R=%.7f N=%d" % (bestRH, bestH.size))
                else:
                    break
            else:
                break

    # ===== Stage 3: final sharp polish =====
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 500, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

