        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None, log=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if log:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
        if active.size == 0:
            return h0
        u0 = np.log(np.clip(h[active], 1e-300, None))
    else:
        active = np.arange(n)
        u0 = np.clip(h, 0.0, None)
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    if log:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fg(hh)
            return val, g[active] * hh[active]
        bounds = [(-30.0, 30.0)] * active.size
    else:
        def f(x):
            hh = np.zeros(n)
            hh[active] = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g[active]
        bounds = [(0.0, None)] * active.size

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=bounds,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    if log:
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    else:
        h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _rand_field(M, rng, nk=6):
    e = np.zeros(M)
    for _ in range(nk):
        f = np.exp(rng.uniform(np.log(1.0), np.log(64.0)))
        ph = rng.uniform(0, 2 * np.pi)
        c = rng.normal()
        i = np.arange(M)
        e += c * np.sin(2 * np.pi * f * i / M + ph)
    m = np.max(np.abs(e))
    if m > 0:
        e /= m
    return e


def _apply_block_check(h, e, B):
    n = h.size
    edges = (np.arange(B + 1) * n) // B
    h2 = h.copy()
    for i in range(B):
        sign = 1.0 if (i % 2 == 0) else -1.0
        h2[edges[i]:edges[i + 1]] *= (1.0 + sign * e[i])
    h2 = np.clip(h2, 0.0, None)
    return _rescale(h2)


def _apply_block_scale(h, e, B):
    n = h.size
    edges = (np.arange(B + 1) * n) // B
    h2 = h.copy()
    for i in range(B):
        h2[edges[i]:edges[i + 1]] *= (1.0 + e[i])
    h2 = np.clip(h2, 0.0, None)
    return _rescale(h2)


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(float)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts.astype(int))
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = h + np.repeat(d, counts.astype(int))
    hh = np.clip(hh, 0.0, None)
    return _rescale(hh)


def _find_block(h):
    N = h.size
    for BLK in range(min(64, N), 1, -1):
        if N % BLK != 0:
            continue
        K = N // BLK
        c = h.reshape(K, BLK)
        if np.allclose(c, c[:, :1], rtol=1e-12, atol=1e-15):
            return BLK
    return 1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(13579)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n = best.size
    if n < 4:
        return {"best": start_best, "alternative": start_best}

    experiment_best = best.copy()
    experiment_bestR = bestR

    # ---- Phase 0: full free (linear, non-log) L-BFGS to break symmetry ----
    # The start is likely a fixed point of log-mode; a linear-mode step with
    # all coordinates free can escape the flat directions of a converged point.
    cap_t = min(deadline - 30.0, time.process_time() + 8.0)
    hs = _lbfgs_log(experiment_best, 400, cap_t, beta=0.0, log=False)
    rs = R_of(hs)
    print("  full-lin R=%.9f (dR=%+.2e)" % (rs, rs - experiment_bestR))
    if rs > experiment_bestR + 1e-13:
        experiment_best, experiment_bestR = hs.copy(), rs

    # ---- Phase 1: block probes ----
    probe_deadline = min(deadline - 25.0, time.process_time() + 12.0)
    candidates = []
    for B in (8, 16, 32, 64, 128, 256):
        for k in range(min(10, 4 + B // 16)):
            if time.process_time() >= probe_deadline:
                break
            if k == 0:
                e = np.zeros(B)
            else:
                e = _rand_field(B, rng, nk=3)
            for d in (1e-3, 1e-2, 3e-2, 0.1):
                cand = _apply_block_check(experiment_best, d * e, B)
                r = R_of(cand)
                candidates.append((r, e.copy(), d, B, 'check'))
        for k in range(min(5, 2 + B // 32)):
            if time.process_time() >= probe_deadline:
                break
            e = _rand_field(B, rng, nk=3) if k > 0 else np.zeros(B)
            for d in (1e-3, 1e-2, 3e-2):
                cand = _apply_block_scale(experiment_best, d * e, B)
                r = R_of(cand)
                candidates.append((r, e.copy(), d, B, 'scale'))

    candidates.sort(key=lambda t: -t[0])
    print("  probes: %d evaluated, best raw R=%.9f (base %.9f, dR=%+.2e)" %
          (len(candidates), candidates[0][0], experiment_bestR,
           candidates[0][0] - experiment_bestR))

    seen = set()
    top = []
    for c in candidates:
        key = (c[3], c[4], round(c[2], 8))
        if key in seen:
            continue
        seen.add(key)
        top.append(c)
        if len(top) >= 3:
            break

    for idx, (r, e, d, B, kind) in enumerate(top):
        if time.process_time() >= deadline - 10.0:
            break
        if kind == 'check':
            cand = _apply_block_check(experiment_best, d * e, B)
        else:
            cand = _apply_block_scale(experiment_best, d * e, B)
        cap_t = min(deadline - 3.0, time.process_time() + 7.0)
        hp, rp = _polish(cand, cap_t, r)
        print("  polish top%d (B=%d %s) raw %.9f -> %.9f" % (idx, B, kind, r, rp))
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp
            print("    NEW BEST R=%.9f" % experiment_bestR)

    # ---- Phase 2: block-additive ----
    for B in (128, 256, 512, 1024, 2048):
        if time.process_time() >= deadline - 3.0:
            break
        cap_t = min(deadline - 1.5, time.process_time() + 5.0)
        hb = _block_additive(experiment_best, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= experiment_bestR - 3e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 5.0), experiment_bestR)
        else:
            hp, rp = hb, r_raw
        print("  B=%-5d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp
            print("    NEW BEST R=%.9f" % experiment_bestR)

    # ---- Phase 3: if block-constant structure, exploit it ----
    BLK = _find_block(experiment_best)
    if BLK > 1 and BLK <= 32:
        K = experiment_best.size // BLK
        c0 = experiment_best.reshape(K, BLK)[:, 0].copy()
        if time.process_time() < deadline - 12.0:
            def f(c):
                hh = np.repeat(np.clip(c, 0.0, None), BLK)
                val, g = _fun_grad(hh)
                gc = np.add.reduceat(g, np.arange(0, hh.size, BLK))
                return val, gc
            cb = _make_cb(deadline - 8.0)
            try:
                res = minimize(f, c0, jac=True, method='L-BFGS-B',
                               bounds=[(0.0, None)] * K, callback=cb,
                               options={'maxiter': 500, 'maxfun': 1000,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                if res is not None:
                    hc = _rescale(np.repeat(np.clip(res.x, 0.0, None), BLK))
                    rc = R_of(hc)
                    print("  block-const K=%d R=%.9f" % (K, rc))
                    if rc > experiment_bestR + 1e-13:
                        experiment_best, experiment_bestR = hc, rc
            except Exception:
                pass

    # ---- Phase 4: keep polishing until deadline ----
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        use_lin = (it % 5 == 0)
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(experiment_best, 200, cap_t, beta=0.0, log=not use_lin)
        rs = R_of(hs)
        if rs > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, experiment_bestR))
            continue
        if time.process_time() < loop_end - 1.0:
            beta = (1e3, 1e4, 1e5)[it % 3]
            cap_t = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(experiment_best, 150, cap_t, beta=beta)
            rs = R_of(hs)
            if rs > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hs.copy(), rs
                print("  final beta=%g iter=%d R=%.9f" % (beta, it, experiment_bestR))
                continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.02 + 0.18 * np.random.random()
            free = _peak_window(experiment_best, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(experiment_best, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, experiment_bestR))

    print("final R=%.9f (best of experiment)" % experiment_bestR)
    mx, m, near = _stats(experiment_best)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (experiment_bestR, experiment_best.size,
           100.0 * np.mean(experiment_best <= 0), mx, m, near))

    if experiment_bestR > start_bestR + 1e-12:
        return {"best": experiment_best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    """Exact tie-averaged objective: log of mean of max knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return _fun_grad(h)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _fun_grad_band(h, lam, thr):
    """Band-variance objective: penalise spread of near-max band."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return _fun_grad(h)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)

    B = np.flatnonzero(Lf >= thr * c)
    if B.size > 0:
        diff = c - Lf[B]
        val += lam * np.mean(diff * diff) / (c * c)
        gLf[B] -= 2.0 * lam * diff / (B.size * c * c)

    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_band(h0, lam, thr, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_band(hh, lam, thr)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def _band_stats(h, thr):
    Lf = _knots(h)
    c = Lf.max()
    if c <= 0:
        return 0, 0.0
    B = Lf[Lf >= thr * c]
    if B.size == 0:
        return 0, 0.0
    return B.size, float(np.std(B) / c)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    def polish(h, fd):
        """Exact tie-averaged full polish + 3-pad peak-window polish."""
        ht = _lbfgs_all_pos(h, 200, fd)
        r = R_of(ht)
        if r > R_of(h) + 1e-15:
            h = ht
        if time.process_time() < fd - 0.5:
            win = _peak_window(h, tol=0.95, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(h, win, 200, fd)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
        return h

    # ---- Band-variance anneal ladder ----
    stages = [(0.01, 0.90), (0.05, 0.95), (0.2, 0.99), (1.0, 0.999)]
    band_deadline = t0 + budget_seconds * 0.55
    per_stage = budget_seconds * 0.09
    for lam, thr in stages:
        if time.process_time() >= band_deadline - 1.0:
            break
        ds = min(band_deadline, time.process_time() + per_stage)
        ht = _lbfgs_band(best, lam, thr, 25, ds)
        nb, bstd = _band_stats(ht, thr)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            tag = "NEW BEST"
        else:
            tag = "no gain"
        print("band lam=%.3f thr=%.3f |B|/n=%.4f bandstd/c=%.6f R=%.9f %s"
              % (lam, thr, nb / max(1, ht.size), bstd, r, tag))
        # polish
        fd = min(band_deadline, time.process_time() + per_stage * 0.6)
        hp = polish(best, fd)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
            print("  polish ACCEPT R=%.9f top1%%=%.9f" % (bestR, _top_frac_mean(best, 0.01)))

    # ---- Loop the last two stages until deadline ----
    loop = 0
    last_stages = [(0.2, 0.99), (1.0, 0.999)]
    while time.process_time() < deadline - 2.0:
        loop += 1
        for lam, thr in last_stages:
            if time.process_time() >= deadline - 2.0:
                break
            fd = min(deadline, time.process_time() + budget_seconds * 0.10)
            ht = _lbfgs_band(best, lam, thr, 25, fd)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                print("loop %d band lam=%.3f thr=%.3f ACCEPT R=%.9f"
                      % (loop, lam, thr, bestR))
            if time.process_time() >= deadline - 2.0:
                break
            fd2 = min(deadline, time.process_time() + budget_seconds * 0.10)
            hp = polish(best, fd2)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
                print("loop %d polish ACCEPT R=%.9f top1%%=%.9f"
                      % (loop, bestR, _top_frac_mean(best, 0.01)))

    # Final exact polish to squeeze
    if time.process_time() < deadline - 1.0:
        fd = deadline - 0.5
        hp = polish(best, fd)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    u0 = np.log(np.clip(h[pos], 1e-300, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt = None
    altR = 0.0

    # NEW IDEA: coarse-to-fine multigrid continuation.
    # The optimum at small N is a good seed for larger N. Solving at
    # increasing resolution gives better convergence than a single large
    # L-BFGS run, and each level is cheap. We also try a fresh alternative
    # starting from a smoothed/perturbed version to escape the plateau.
    N = best.size

    # Level sequence: go down then back up to clean up low-frequency error,
    # then refine upward past the original size.
    levels = sorted(set([max(64, N // 8), max(128, N // 4),
                         max(256, N // 2), N,
                         min(1000000, int(N * 1.5)),
                         min(1000000, int(N * 2.5))]))

    # Start from best; do a few cycles of coarse/fine.
    cur = best.copy()
    curR = bestR
    for rep in range(3):
        if time.process_time() >= deadline - 8.0:
            break
        for Nc in levels:
            if time.process_time() >= deadline - 6.0:
                break
            h = _coarse(cur, Nc)
            h = _lbfgs_log(h, 400, deadline)
            h = _window_polish_peak(h, deadline, 0.4, 16, maxiter=200)
            h = _prolongate(h, N)
            h = _window_polish_peak(h, deadline, 0.4, 16, maxiter=200)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h, r
                print("mg rep%d Nc=%d R=%.7f" % (rep, Nc, curR))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    # Alternative: perturbed restart to explore a different basin.
    if time.process_time() < deadline - 25.0:
        rng = np.random.default_rng(12345)
        for trial in range(4):
            if time.process_time() >= deadline - 20.0:
                break
            h = best.copy()
            # smooth multiplicative perturbation
            k = max(3, h.size // 200)
            ker = np.ones(k) / k
            noise = rng.standard_normal(h.size)
            noise = np.convolve(noise, ker, mode='same')
            h = h * np.exp(0.15 * noise)
            h = _rescale(h)
            h = _lbfgs_log(h, 600, deadline)
            h = _window_polish_peak(h, deadline, 0.5, 20, maxiter=300)
            h = _lbfgs_log(h, 400, deadline)
            r = R_of(h)
            if r > altR:
                alt, altR = h, r
                print("alt trial%d R=%.7f" % (trial, altR))
            if r > bestR + 1e-13:
                best, bestR = h, r
                print("alt->best R=%.7f" % bestR)

    # Final alternating polish until budget exhausted.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.5, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        if alt is not None and altR > start_bestR + 1e-12 and altR < bestR - 1e-13:
            return {"best": best, "alternative": alt}
        return best
    if alt is not None and altR > start_bestR + 1e-12:
        return {"best": alt, "alternative": best}
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
