    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-8))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, deadline, maxiter, fg):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-14 * hmax if hmax > 0 else 1e-14
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fg(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-50.0, 50.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -50.0, 50.0))
    return _rescale(h2)


def _lbfgs_pos(h0, deadline, maxiter, fg):
    """L-BFGS in linear space with nonneg bounds."""
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, deadline, maxiter, fg):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth_filter(h, k):
    if k <= 0 or h.size < 2 * k + 1:
        return h
    ker = np.ones(2 * k + 1) / (2 * k + 1)
    hs = np.convolve(h, ker, mode='same')
    return _rescale(np.clip(hs, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_state = [None, -1.0]

    # Phase 1: CVaR-driven reshaping.  Optimising a CVaR surrogate for
    # ||f*f||_inf pushes several near-peak knots up simultaneously, which is
    # the standard trick to escape the "single peak" local maximum.
    cvar_end = t0 + budget_seconds * 0.30
    for q in [0.90, 0.94, 0.96, 0.97, 0.98]:
        if time.process_time() > cvar_end - 2.0:
            break
        fg = lambda hh, q=q: _fun_grad_cvar(hh, q)
        hp = _lbfgs_log(best, min(time.process_time() + 4.0, cvar_end), 120, fg)
        r = R_of(hp)
        if r > bestR + 1e-13:
            best, bestR = hp.copy(), r
            origin = 'cvar%.2f' % q
            print("cvar q=%.2f NEW BEST R=%.9f" % (q, bestR))
        elif r > alt_state[1]:
            alt_state[0], alt_state[1] = hp.copy(), r

    # Phase 2: tie-aware gradient ascent in log space (multi-knot peak).
    tie_end = t0 + budget_seconds * 0.55
    hop = 0
    while time.process_time() < tie_end - 2.0:
        now = time.process_time()
        slice_dl = min(now + 4.0, tie_end)
        if hop == 0:
            hp = best.copy()
        else:
            k = [1, 2, 3, 5, 8][hop % 5]
            hp = _smooth_filter(best, k)
        if time.process_time() < slice_dl - 0.5:
            hp = _lbfgs_log(hp, slice_dl - 0.2, 150, _fun_grad_tie)
        if time.process_time() < slice_dl - 0.5:
            hp = _lbfgs_pos(hp, slice_dl - 0.2, 100, _fun_grad_tie)
        r = R_of(hp)
        if r > bestR + 1e-13:
            best, bestR = hp.copy(), r
            origin = 'tie%d' % hop
            print("tie%d NEW BEST R=%.9f" % (hop, bestR))
        elif r > alt_state[1]:
            alt_state[0], alt_state[1] = hp.copy(), r
        hop += 1
    print("tie rounds=%d R=%.9f" % (hop, bestR))

    # Phase 3: peak-window polish with the tie-aware objective and plain R.
    while time.process_time() < deadline - 1.0:
        improved = False
        for pad in [0.10, 0.06, 0.04, 0.03]:
            if time.process_time() > deadline - 1.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, deadline - 0.4, 300, _fun_grad_tie)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2.copy(), r2
                improved = True
            elif r2 > alt_state[1]:
                alt_state[0], alt_state[1] = ht2.copy(), r2
        if time.process_time() > deadline - 1.0:
            break
        ht = _lbfgs_pos(best, deadline - 0.4, 200, _fun_grad_tie)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            improved = True
        elif r > alt_state[1]:
            alt_state[0], alt_state[1] = ht.copy(), r
        if not improved:
            hp = _smooth_filter(best, 2)
            hp = _lbfgs_log(hp, deadline - 0.4, 150, _fun_grad_tie)
            r = R_of(hp)
            if r > bestR + 1e-14:
                best, bestR = hp.copy(), r
            else:
                break

    if bestR < start_bestR - 1e-14:
        best, bestR = start_best.copy(), start_bestR

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if (alt_state[0] is not None and alt_state[0].size == best.size
            and alt_state[0].sum() > 0
            and alt_state[1] < bestR - 1e-14):
        result["alternative"] = alt_state[0]
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    """Exact tie-averaged objective: log of mean of max knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return _fun_grad(h)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _fun_grad_band(h, lam, thr):
    """Band-variance objective: penalise spread of near-max band."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return _fun_grad(h)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)

    B = np.flatnonzero(Lf >= thr * c)
    if B.size > 0:
        diff = c - Lf[B]
        val += lam * np.mean(diff * diff) / (c * c)
        gLf[B] -= 2.0 * lam * diff / (B.size * c * c)

    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_band(h0, lam, thr, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_band(hh, lam, thr)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def _band_stats(h, thr):
    Lf = _knots(h)
    c = Lf.max()
    if c <= 0:
        return 0, 0.0
    B = Lf[Lf >= thr * c]
    if B.size == 0:
        return 0, 0.0
    return B.size, float(np.std(B) / c)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    def polish(h, fd):
        """Exact tie-averaged full polish + peak-window polish."""
        ht = _lbfgs_all_pos(h, 200, fd)
        r = R_of(ht)
        if r > R_of(h) + 1e-15:
            h = ht
        if time.process_time() < fd - 0.5:
            win = _peak_window(h, tol=0.95, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(h, win, 200, fd)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
        return h

    # ---- Initial polish of the start ----
    if time.process_time() < deadline - 3.0:
        fd = min(deadline, time.process_time() + budget_seconds * 0.15)
        hp = polish(best, fd)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
            print("init polish ACCEPT R=%.9f top1%%=%.9f"
                  % (bestR, _top_frac_mean(best, 0.01)))

    # ---- Revival-based climb ----
    # Track revived indices across rounds.
    revived = np.zeros(best.size, dtype=bool)
    K_schedule = [32, 16, 8, 4]
    eps_schedule = [1e-2, 1e-3, 1e-4]
    round_i = 0
    while time.process_time() < deadline - 1.5:
        round_i += 1
        K = K_schedule[(round_i - 1) % len(K_schedule)]
        eps = eps_schedule[(round_i - 1) % len(eps_schedule)]

        # Prune revived cells that have fallen below threshold.
        mh = best.mean()
        if mh > 0:
            prune = revived & (best < 1e-10 * mh)
            if np.any(prune):
                best = best.copy()
                best[prune] = 0.0
                revived[prune] = False
                best = _rescale(best)
                bestR = R_of(best)

        # Compute exact gradient of -logR.
        _, g = _fun_grad_tie(best)
        zeros = np.flatnonzero(best <= 0)
        if zeros.size == 0:
            print("round %d: no zero cells left" % round_i)
            break
        gz = g[zeros]
        order = np.argsort(gz)  # most negative first
        pick = zeros[order[:min(K, zeros.size)]]

        trial = best.copy()
        trial[pick] = eps * mh
        trial = _rescale(trial)
        trialR = R_of(trial)

        # Full L-BFGS polish on trial.
        fd = min(deadline - 1.0, time.process_time() + budget_seconds * 0.10)
        if time.process_time() < fd - 0.5:
            hp = polish(trial, fd)
            rp = R_of(hp)
        else:
            hp, rp = trial, trialR

        # Count survivors among picked.
        surv = int(np.sum(hp[pick] > 1e-10 * max(hp.mean(), 1e-300)))

        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
            revived[pick] = True
            # Prune any revived that died.
            mh2 = best.mean()
            if mh2 > 0:
                dead = revived & (best < 1e-10 * mh2)
                if np.any(dead):
                    best = best.copy()
                    best[dead] = 0.0
                    revived[dead] = False
                    best = _rescale(best)
                    bestR = R_of(best)
            tag = "NEW BEST"
        else:
            tag = "no gain"

        print("round %d K=%d eps=%.0e revived_survive=%d zero_frac=%.4f R=%.9f %s"
              % (round_i, K, eps, surv, _zero_frac(best), bestR, tag))

        # Occasionally do a band-assisted nudge (kept from base) to escape.
        if round_i % 4 == 0 and time.process_time() < deadline - 3.0:
            fd2 = min(deadline - 1.5, time.process_time() + budget_seconds * 0.08)
            ht = _lbfgs_band(best, 0.2, 0.99, 25, fd2)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                print("  band nudge ACCEPT R=%.9f" % bestR)

    # Final polish.
    if time.process_time() < deadline - 1.0:
        fd = deadline - 0.5
        hp = polish(best, fd)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f, revived=%d)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01), int(revived.sum())))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta_pen(h, beta, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm

    S = Lf >= tau * mx
    if np.any(S):
        vals = Lf[S]
        mu = vals.mean()
        var = np.mean((vals - mu) ** 2)
        nS = vals.size
        dvar_dL = np.zeros_like(Lf)
        dvar_dL[S] = (2.0 / nS) * (vals - mu)
        pen = kappa * var / (mx * mx)
        gLf += kappa * dvar_dL / (mx * mx)
        idx = np.flatnonzero(Lf >= (1.0 - 1e-12) * mx)
        wm = 1.0 / idx.size
        gLf[idx] += (-2.0 * kappa * var / (mx * mx * mx)) * wm
    else:
        pen = 0.0

    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tau=0.9, kappa=0.0,
                 tie=False, logspace=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta_pen(hh, beta, tau, kappa))
    else:
        fg = _fun_grad_tie

    if logspace:
        hmax = h.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        u0 = np.log(np.clip(h[active], floor, None))

        def f(u):
            hh = h.copy()
            va = np.exp(u)
            hh[active] = va
            val, g = fg(hh)
            return val, g[active] * va

        cb = _make_cb(deadline - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * active.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return h0
        if res is None:
            return h0
        h2 = h.copy()
        h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
        return _rescale(h2)

    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
