              (0.45, 2000.0), (0.55, 1000.0)]
    allidx = np.arange(h_cur.size)
    for (tau, kappa) in ladder:
        if time.process_time() >= deadline - 20.0:
            break
        h_new = _lbfgs_block(
            h_cur, allidx, 200,
            min(deadline - 18.0, time.process_time() + 5.0),
            beta=1e6, tau=tau, kappa=kappa)
        maybe_update(h_new, "flat tau=%.2f k=%.0f" % (tau, kappa))
