        for deg in (1, 2):
            h2 = _lift_poly(h_cur, deg=deg)
            r2 = R_of(h2)
            _report("lift deg=%d" % deg, h2, r2)
            if r2 > best_liftR:
                best_liftR, best_lift = r2, h2
        if best_lift is not None and best_liftR > curR + 1e-15:
            h_cur, curR = best_lift, best_liftR
