        if time.process_time() < deadline - 6.0:
            idx2 = np.arange(h_cur.size)
            h_l = _lbfgs_block(
                h_cur, idx2, 150,
                min(deadline - 3.0, time.process_time() + 6.0),
                tie=True, logspace=True)
            maybe_update(h_l, "lift logtie")
        if curR > bestR + 1e-15:
            best, bestR = h_cur.copy(), curR
        if curR > altR:
            altR = curR
            alt_best = h_cur.copy()

    # ---- Phase D: final tie polish at full resolution ----
    if time.process_time() < deadline - 1.0:
        h_f = _lbfgs_block(
            h_cur, np.arange(h_cur.size), 200,
            deadline - 0.5, tie=True, logspace=True)
