    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_band(h, q, wR):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    mask = Lf >= q * mx
    cnt = mask.sum()
    if cnt == 0:
        return 1e18, np.zeros(h.size)
    dev = Lf[mask] - mx
    band = np.mean(dev * dev) / (mx * mx)
    # gradient of band term
    gLf = np.zeros_like(Lf)
    # d band / d L_j
    # band = (1/cnt) sum (L_j - mx)^2 / mx^2
    # d/dL_j (j in band) = 2(L_j-mx)/(cnt*mx^2)
    gLf[mask] += 2.0 * dev / (cnt * mx * mx)
    # d/dmx: mx = max Lf, treat as one of the band knots (they equal mx)
    # d band/dmx = -2/(cnt*mx^2) * sum(dev) + (-2/(mx^3)) * mean(dev^2)
    #            = -2*sum(dev)/(cnt*mx^2) - 2*band/mx
    dband_dmx = -2.0 * dev.sum() / (cnt * mx * mx) - 2.0 * band / mx
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += dband_dmx / idx.size
    # small -log R term
    if wR != 0.0:
        gR = -dq / num
        gR[idx] += (1.0 / mx) / idx.size
        gR = _backprop(gR, h) + 2.0 / s
        gLf = gLf + wR * gR
    grad = _backprop(gLf, h)
    val = band
    if wR != 0.0:
        val = val - wR * np.log(num) + wR * 2.0 * np.log(s) + wR * np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0, None)
    return _rescale(h2)


def _band_lbfgs(h0, q, wR, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = _rescale(np.clip(h0, 0, None))
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        if hh.sum() <= 0:
            return 1e18, np.zeros(n)
        val, g = _fun_grad_band(hh, q, wR)
        denom = float(np.dot(hh, hh))
        if denom > 0:
            g = g - (float(np.dot(g, hh)) / denom) * hh
        return val, g

    cb = _make_cb(deadline - 0.15)
    x0 = h.copy()
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0, None))


def _riemann_lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = _rescale(np.clip(h0, 0, None))
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        if hh.sum() <= 0:
            return 1e18, np.zeros(n)
        val, g = _fun_grad_tie(hh)
        denom = float(np.dot(hh, hh))
        if denom > 0:
            g = g - (float(np.dot(g, hh)) / denom) * hh
        return val, g

    cb = _make_cb(deadline - 0.15)
    x0 = h.copy()
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0, None))


def _prolongate(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N) / N
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(n + 1, dtype=float))
    hh = np.clip(np.diff(out), 0, None)
    if hh.sum() <= 0:
        return np.ones(N) / N
    return hh


def _rasterise(widths, heights):
    N = int(widths.sum())
    h = np.empty(N, dtype=float)
    pos = 0
    for w, a in zip(widths, heights):
        h[pos:pos + w] = a
        pos += w
    return h


def _collapse(h, nb):
    n = h.size
    edges = np.linspace(0, n, nb + 1).astype(int)
    widths = np.diff(edges)
    heights = np.empty(nb)
    for i in range(nb):
        lo, hi = edges[i], edges[i + 1]
        if hi > lo:
            heights[i] = h[lo:hi].mean()
        else:
            heights[i] = 0.0
    return widths.astype(int), heights


def _split_genome(w64, a64):
    NB = w64.size
    w128 = np.empty(2 * NB, dtype=int)
    a128 = np.empty(2 * NB, dtype=float)
    for k in range(NB):
        w = int(w64[k])
        w1 = w // 2
        w2 = w - w1
        if w1 < 1:
            w1 = 1
            w2 = w - 1
        if w2 < 1:
            w2 = 1
            w1 = w - 1
        w128[2 * k] = w1
        w128[2 * k + 1] = w2
        a128[2 * k] = a64[k]
        a128[2 * k + 1] = a64[k]
    return w128, a128


def _band_stats(h, q):
    L = _knots(h)
    c = L.max()
    if c <= 0:
        return 0.0, 0.0
    mask = L >= q * c
    band_rms = float(np.sqrt(np.mean((L[mask] - c) ** 2)) / c) if mask.any() else 0.0
    share01 = float(np.mean(L >= 0.999 * c))
    return band_rms, share01


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240607)
    N = 3281
    NB64 = 64
    NB = 128

    startR = 0.0
    start_h = None
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            if s.size != N:
                s = _rescale(_prolongate(s, N))
            else:
                s = _rescale(s)
            start_h = s
            startR = R_of(s)

    if start_h is None:
        start_h = _rescale(np.ones(N))
        startR = R_of(start_h)

    w64, a64 = _collapse(start_h, NB64)
    w64 = np.maximum(1, w64.astype(int))
    diff = N - w64.sum()
    i = 0
    while diff != 0 and i < 1000000:
        j = i % NB64
        if diff > 0:
            w64[j] += 1; diff -= 1
        elif w64[j] > 1:
            w64[j] -= 1; diff += 1
        i += 1

    w, a = _split_genome(w64, a64)
    h_check = _rasterise(w, a)
    if h_check.size != N:
        w, a = _collapse(start_h, NB)
        w = np.maximum(1, w.astype(int))
        diff = N - w.sum()
        i = 0
        while diff != 0 and i < 1000000:
            j = i % NB
            if diff > 0:
                w[j] += 1; diff -= 1
            elif w[j] > 1:
                w[j] -= 1; diff += 1
            i += 1

    def polish(w, a, maxiter, dl):
        h = _rescale(_rasterise(w, a))
        hp = _lbfgs_block(h, np.arange(N), maxiter, dl, tie=True)
        return hp, R_of(hp)

    cur_h, curR = polish(w, a, 100, deadline)
    best_h, bestR = cur_h.copy(), curR
    if startR > bestR:
        best_h, bestR = start_h.copy(), startR
    print("baseline R=%.9f (start %.9f)" % (bestR, startR))

    pool = [(w.copy(), a.copy(), cur_h.copy(), curR)]

    def pool_add(w2, a2, h2, r2):
        pool.append((w2.copy(), a2.copy(), h2.copy(), r2))
        pool.sort(key=lambda t: -t[3])
        del pool[3:]

    q_list = [0.90, 0.95, 0.99]
    q_idx = 0
    accepted = 0
    moves_tried = 0
    since_full = 0

    while time.process_time() < deadline - 2.0:
        q = q_list[q_idx % len(q_list)]
        q_idx += 1

        # (a) band polish on all heights, then exact-R polish
        hb = _band_lbfgs(cur_h, q, 1e-3, 200, deadline - 1.0)
        hp = _lbfgs_block(hb, np.arange(N), 100, deadline - 0.5, tie=True)
        rp = R_of(hp)
        if rp > curR + 1e-12:
            cur_h, curR = hp, rp
            a = _collapse(hp, NB)[1]
            if rp > bestR:
                best_h, bestR = hp.copy(), rp
            pool_add(w, a, hp, rp)
            brms, sh = _band_stats(hp, q)
            print("band-accept q=%.2f R=%.9f rms=%.4f sh01=%.3f" % (q, bestR, brms, sh))

        # (b) width-shift search on 128 blocks
        for _ in range(4):
            if time.process_time() >= deadline - 2.0:
                break
            moves_tried += 1
            w2 = w.copy()
            nmoves = int(rng.integers(1, 4))
            for _ in range(nmoves):
                j = int(rng.integers(0, NB))
                d = int(rng.choice([-1, 1]) * rng.integers(1, 7))
                if d > 0:
                    if w2[j] - d >= 1:
                        k = (j + 1) % NB
                        w2[j] -= d; w2[k] += d
                else:
                    k = (j + 1) % NB
                    if w2[k] + d >= 1:
                        w2[j] -= d; w2[k] += d
            if w2.sum() != N or np.any(w2 < 1):
                continue
            h2 = _rescale(_rasterise(w2, a))
            v0, _ = _fun_grad_band(cur_h, q, 1e-3)
            hb2 = _band_lbfgs(h2, q, 1e-3, 40, deadline - 1.0)
            v2, _ = _fun_grad_band(hb2, q, 1e-3)
            if v2 < v0:
                hp2 = _lbfgs_block(hb2, np.arange(N), 100, deadline - 0.5, tie=True)
                rp2 = R_of(hp2)
                if rp2 > curR + 1e-12:
                    w = w2
                    a = _collapse(hp2, NB)[1]
                    cur_h, curR = hp2, rp2
                    accepted += 1
                    since_full += 1
                    if rp2 > bestR:
                        best_h, bestR = hp2.copy(), rp2
                    pool_add(w, a, hp2, rp2)
                    brms, sh = _band_stats(hp2, q)
                    print("waccept %d q=%.2f R=%.9f rms=%.4f sh01=%.3f" % (
                        accepted, q, bestR, brms, sh))

        # (c) full exact polish every 8 accepted moves
        if since_full >= 8 and time.process_time() < deadline - 3.0:
            since_full = 0
            hf = _riemann_lbfgs(cur_h, 300, deadline - 1.0)
            rf = R_of(hf)
            if rf > curR:
                cur_h, curR = hf, rf
                a = _collapse(hf, NB)[1]
                if rf > bestR:
                    best_h, bestR = hf.copy(), rf
                pool_add(w, a, hf, rf)
                print("full polish R=%.9f" % bestR)

        # GA burst
        if rng.random() < 0.08 and len(pool) >= 2 and time.process_time() < deadline - 3.0:
            p1 = pool[0]; p2 = pool[1]
            w1p, a1p = p1[0], p1[1]
            w2p, a2p = p2[0], p2[1]
            wc = w1p.copy()
            ac = a2p.copy()
            diff = N - wc.sum()
            i = 0
            while diff != 0 and i < 1000000:
                j = i % NB
                if diff > 0:
                    wc[j] += 1; diff -= 1
                elif wc[j] > 1:
                    wc[j] -= 1; diff += 1
                i += 1
            for _ in range(2):
                j = int(rng.integers(0, NB))
                d = int(rng.choice([-1, 1]) * rng.integers(1, 5))
                if d > 0 and wc[j] - d >= 1:
                    k = (j + 1) % NB
                    wc[j] -= d; wc[k] += d
                elif d < 0:
                    k = (j + 1) % NB
                    if wc[k] + d >= 1:
                        wc[j] -= d; wc[k] += d
            for _ in range(3):
                j = int(rng.integers(0, NB))
                ac[j] *= float(np.exp(rng.normal(0, 0.1)))
            hc, rc = polish(wc, ac, 70, deadline - 1.0)
            if rc > pool[-1][3]:
                pool_add(wc, ac, hc, rc)
                if rc > bestR:
                    best_h, bestR = hc.copy(), rc
                    w, a, cur_h, curR = wc.copy(), ac.copy(), hc.copy(), rc
                    print("GA accept R=%.9f" % bestR)

    if time.process_time() < deadline - 0.5:
        hp = _riemann_lbfgs(best_h, 250, deadline)
        rp = R_of(hp)
        if rp > bestR:
            best_h, bestR = hp, rp

    if start_h is not None and bestR < startR:
        best_h = start_h
        bestR = startR

    brms, sh = _band_stats(best_h, 0.99)
    print("final R=%.12f (start %.12f, N=%d, moves=%d, accepted=%d, rms=%.4f, sh01=%.3f)" % (
        bestR, startR, best_h.size, moves_tried, accepted, brms, sh))

    result = {"best": best_h}
    if cur_h is not None and R_of(cur_h) > startR + 1e-12:
        na = np.linalg.norm(cur_h); nb = np.linalg.norm(best_h)
        if na > 0 and nb > 0 and float(np.dot(cur_h, best_h) / (na * nb)) < 0.9999:
            result["alternative"] = cur_h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta_pen(h, beta, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm

    S = Lf >= tau * mx
    if np.any(S):
        vals = Lf[S]
        mu = vals.mean()
        var = np.mean((vals - mu) ** 2)
        nS = vals.size
        dvar_dL = np.zeros_like(Lf)
        dvar_dL[S] = (2.0 / nS) * (vals - mu)
        pen = kappa * var / (mx * mx)
        gLf += kappa * dvar_dL / (mx * mx)
        idx = np.flatnonzero(Lf >= (1.0 - 1e-12) * mx)
        wm = 1.0 / idx.size
        gLf[idx] += (-2.0 * kappa * var / (mx * mx * mx)) * wm
    else:
        pen = 0.0

    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tau=0.9, kappa=0.0,
                 tie=False, logspace=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta_pen(hh, beta, tau, kappa))
    else:
        fg = _fun_grad_tie

    if logspace:
        hmax = h.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        u0 = np.log(np.clip(h[active], floor, None))

        def f(u):
            hh = h.copy()
            va = np.exp(u)
            hh[active] = va
            val, g = fg(hh)
            return val, g[active] * va

        cb = _make_cb(deadline - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * active.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return h0
        if res is None:
            return h0
        h2 = h.copy()
        h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
        return _rescale(h2)

    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _max_mean(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(mx / Lf.mean())


def _stats(h):
    return (_frac_near_max(h, 1e-3), _frac_near_max(h, 1e-2),
            _frac_near_max(h, 5e-2), _max_mean(h))


def _report(tag, h, r):
    f01, f1, f5, mm = _stats(h)
    zf = float(np.mean(h <= 0))
    print("%s R=%.12f nm 0.1/1/5%%=%.4f/%.4f/%.4f mm=%.2f zf=%.3f"
          % (tag, r, f01, f1, f5, mm, zf))


def _lift2(h, taps=(0.25, 0.5, 0.25)):
    h2 = np.repeat(h, 2)
    k = np.array(taps)
    h2 = np.convolve(h2, k, mode='same')
    return _rescale(h2)


def _lift_poly(h, deg=3):
    h2 = np.repeat(h, 2)
    for _ in range(deg):
        k = np.array([0.25, 0.5, 0.25])
        h2 = np.convolve(h2, k, mode='same')
    return _rescale(h2)


def _mass_lift(h, factor):
    """Mass-preserving cumulative-sum linear interpolation to N*factor."""
    n = h.size
    N = n * factor
    # cumulative mass at original cell boundaries
    cs = np.concatenate(([0.0], np.cumsum(h)))
    # new cell boundaries at positions j/factor in original index units
    x = np.arange(N + 1, dtype=float) / factor
    # piecewise linear interpolation of cumulative mass
    cnew = np.interp(x, np.arange(n + 1, dtype=float), cs)
    h2 = np.diff(cnew) * factor  # mass per new cell (density)
    return _rescale(np.clip(h2, 0, None))


def _fold_back(h, n_target):
    n = h.size
    if n == n_target:
        return h.copy()
    # block-sum fold: assume n is a multiple of n_target
    if n % n_target == 0:
        f = n // n_target
        return _rescale(h.reshape(n_target, f).sum(axis=1))
    # fallback: resample by cumulative
    cs = np.concatenate(([0.0], np.cumsum(h)))
    x = np.linspace(0, n, n_target + 1)
    cnew = np.interp(x, np.arange(n + 1, dtype=float), cs)
    return _rescale(np.clip(np.diff(cnew), 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    _report("before", best, bestR)

    alt_best = None
    altR = -1.0

    h_cur = best.copy()
    curR = bestR
    N0 = h_cur.size

    def maybe_update(h_new, tag):
        nonlocal h_cur, curR, best, bestR
        r = R_of(h_new)
        _report(tag, h_new, r)
        if r > curR + 1e-15:
            h_cur, curR = h_new, r
            if curR > bestR + 1e-15:
                best, bestR = h_cur.copy(), curR
        return r

    # ---- Phase A: alternating beta-penalty ladder and log-space tie polish ----
    ladder = [(0.70, 1000.0), (0.60, 3000.0), (0.50, 3000.0),
              (0.45, 2000.0), (0.55, 1000.0)]
    allidx = np.arange(h_cur.size)
    for (tau, kappa) in ladder:
        if time.process_time() >= deadline - 25.0:
            break
        h_new = _lbfgs_block(
            h_cur, allidx, 200,
            min(deadline - 23.0, time.process_time() + 4.0),
            beta=1e6, tau=tau, kappa=kappa)
        maybe_update(h_new, "flat tau=%.2f k=%.0f" % (tau, kappa))
        if time.process_time() < deadline - 21.0:
            h_sh = _lbfgs_block(
                h_cur, allidx, 120,
                min(deadline - 19.0, time.process_time() + 3.0),
                tie=True, logspace=True)
            maybe_update(h_sh, "  logtie")

    if curR > altR:
        altR = curR
        alt_best = h_cur.copy()

    # ---- Phase B: local window polish with log-space ----
    if time.process_time() < deadline - 18.0:
        for pad in (0.15, 0.08, 0.04):
            if time.process_time() >= deadline - 16.0:
                break
            win = _peak_window(h_cur, pad_frac=pad, extra=128)
            ht = _lbfgs_block(
                h_cur, win, 100,
                min(deadline - 15.0, time.process_time() + 2.5),
                tie=True, logspace=True)
            maybe_update(ht, "peak logpad=%.2f" % pad)

    # ---- Phase C: 2x lift with better refinement ----
    if time.process_time() < deadline - 14.0:
        best_lift = None; best_liftR = -1.0
        for deg in (1, 2):
            h2 = _lift_poly(h_cur, deg=deg)
            r2 = R_of(h2)
            _report("lift deg=%d" % deg, h2, r2)
            if r2 > best_liftR:
                best_liftR, best_lift = r2, h2
        if best_lift is not None and best_liftR > curR + 1e-15:
            h_cur, curR = best_lift, best_liftR
        if time.process_time() < deadline - 12.0:
            idx2 = np.arange(h_cur.size)
            h_l = _lbfgs_block(
                h_cur, idx2, 150,
                min(deadline - 10.0, time.process_time() + 4.0),
                tie=True, logspace=True)
            maybe_update(h_l, "lift logtie")
        if curR > bestR + 1e-15:
            best, bestR = h_cur.copy(), curR
        if curR > altR:
            altR = curR
            alt_best = h_cur.copy()

    # ---- Phase D: final tie polish at full resolution ----
    if time.process_time() < deadline - 9.0:
        h_f = _lbfgs_block(
            h_cur, np.arange(h_cur.size), 200,
            min(deadline - 8.0, time.process_time() + 3.0),
            tie=True, logspace=True)
        maybe_update(h_f, "final logtie")

    # ---- Phase E: log-space resolution ladder (the experiment) ----
    h_src = h_cur.copy()
    srcR = curR
    for factor in (2, 4):
        if time.process_time() >= deadline - 2.0:
            break
        try:
            h_lift = _mass_lift(h_src, factor)
        except Exception:
            continue
        r_lift = R_of(h_lift)
        print("ladder f=%d N=%d lift R=%.12f" % (factor, h_lift.size, r_lift))
        # log-space L-BFGS-B on all positions, exact tie gradient
        tstop = min(deadline - 1.5, time.process_time() + 3.0)
        h_opt = _lbfgs_block(h_lift, np.arange(h_lift.size), 120, tstop,
                             tie=True, logspace=True)
        r_opt = R_of(h_opt)
        print("ladder f=%d N=%d opt R=%.12f" % (factor, h_opt.size, r_opt))
        # peak-window beta ladder
        Lf = _knots(h_opt)
        am = int(np.argmax(Lf))
        n = h_opt.size
        c = am // 2
        half = max(64, n // 8)
        lo = max(0, c - half)
        hi = min(n, c + half)
        win = np.arange(lo, hi)
        for beta in (1e4, 1e6, 1e8):
            if time.process_time() >= deadline - 1.0:
                break
            tstop = min(deadline - 0.8, time.process_time() + 1.5)
            h_b = _lbfgs_block(h_opt, win, 80, tstop,
                               beta=beta, tau=0.5, kappa=0.0,
                               tie=False, logspace=True)
            r_b = R_of(h_b)
            if r_b > r_opt:
                h_opt, r_opt = h_b, r_b
        print("ladder f=%d N=%d peak R=%.12f" % (factor, h_opt.size, r_opt))
        # fold back to N0
        h_fold = _fold_back(h_opt, N0)
        r_fold = R_of(h_fold)
        print("ladder f=%d fold R=%.12f" % (factor, r_fold))
        if r_fold > bestR + 1e-12:
            best, bestR = h_fold.copy(), r_fold
            h_cur, curR = h_fold.copy(), r_fold
            if curR > altR:
                altR = curR
                alt_best = h_cur.copy()
        # also keep the fine-level construction if it beats current best
        if r_opt > bestR + 1e-12 and h_opt.size <= 1000000:
            best, bestR = h_opt.copy(), r_opt
            if curR > altR:
                altR = curR
                alt_best = h_opt.copy()

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    _report("after", best, bestR)
    print("final R=%.12f (start %.12f, N=%d, ties=%d, mm=%.2f)"
          % (bestR, startR, best.size, _tie_count(best), _max_mean(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-15:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, deadline, maxiter=150, beta=0.0):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fg(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    return np.clip(np.diff(C), 0, None)


def _peak_window_polish(h, deadline, frac=0.02, extra=64, maxiter=200, beta=0.0):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    n = h.size
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    hh = h.copy()
    x0 = hh[free].copy()
    if beta > 0:
        fg = (lambda hx: _fun_grad_beta(hx, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        h2 = hh.copy()
        h2[free] = np.clip(x, 0.0, None)
        val, g = fg(h2)
        return val, g[free]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * free.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = hh.copy()
    h2[free] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = best.copy()

    # Stage A: full tie-averaged polish
    if time.process_time() < deadline - 5.0:
        h = _lbfgs_log(cur, deadline, maxiter=250)
        r = R_of(h)
        print("full R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
        if r > bestR - 0.003:
            cur = h

    # Stage B: beta ladder with peak polishes
    for beta in (1e2, 1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(cur, deadline, maxiter=200, beta=beta)
        r = R_of(h)
        print("beta=%.0e R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
        if r > bestR - 0.003:
            cur = h
        for frac in (0.005, 0.01, 0.02, 0.05):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _peak_window_polish(cur, deadline, frac=frac, extra=48,
                                     maxiter=200, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp.copy(), rp
                print("  peak frac=%.3f R=%.7f" % (frac, rp))
            if rp > bestR - 0.003:
                cur = hp

    # Stage C: alternating full + peak polishes, plus resize trials
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, deadline, maxiter=200)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("  alt full #%d R=%.7f" % (it, bestR))
        if time.process_time() >= deadline - 1.5:
            break
        frac = 0.01 if it % 2 else 0.03
        hp = _peak_window_polish(best, deadline, frac=frac, extra=64,
                                 maxiter=200)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            best, bestR = hp.copy(), rp
            print("  alt peak #%d R=%.7f" % (it, rp))

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _mass_resample(base, newN):
    n = base.size
    if n == newN:
        return _rescale(base.copy())
    c = np.concatenate(([0.0], np.cumsum(base)))
    total = c[-1]
    if total <= 0:
        return _rescale(np.ones(newN))
    edges = np.linspace(0.0, total, newN + 1)
    x_src = np.linspace(0.0, 1.0, n + 1)
    x_new = np.interp(edges, c, x_src)
    widths = np.diff(x_new)
    masses = np.diff(edges)
    h = np.where(widths > 1e-15, masses / np.maximum(widths, 1e-15), 0.0)
    return _rescale(h)


def _detect_block(h):
    """Return largest BLK dividing N such that h is approximately block-constant."""
    N = h.size
    for BLK in range(min(64, N), 1, -1):
        if N % BLK != 0:
            continue
        K = N // BLK
        c = h.reshape(K, BLK)
        if np.allclose(c, c[:, :1], rtol=1e-10, atol=1e-14):
            return BLK
    return 1


def _coarse_from_block(h, BLK):
    """Collapse block-constant h to its per-block value (length N/BLK)."""
    N = h.size
    K = N // BLK
    c = h.reshape(K, BLK).mean(axis=1)
    return _rescale(c)


def _fine_from_coarse(c, BLK):
    """Expand coarse heights back by repeating each BLK times."""
    return _rescale(np.repeat(c, BLK))


def _polish_full(h, deadline, maxiter=600):
    return _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=True)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, N, _zero_frac(best), _nearmax_frac(best), _tie_count(best)))

    # Detect if the start is block-constant (fine grid of a coarser problem).
    # If so, work in the coarse representation for the bulk of the time:
    # many fewer variables => deeper optimisation reachable.
    BLK = _detect_block(best)
    coarse_mode = BLK > 1
    if coarse_mode:
        cbest = _coarse_from_block(best, BLK)
        cbestR = R_of(_fine_from_coarse(cbest, BLK))
        print("block-constant detected BLK=%d K=%d (coarse R=%.9f)"
              % (BLK, cbest.size, cbestR))

    # ---- Phase A: if block-constant, run intensive coarse optimisation. ----
    if coarse_mode:
        phaseA_end = t0 + budget_seconds * 0.55
        while time.process_time() < phaseA_end - 2.0:
            slice_end = min(phaseA_end, time.process_time() + 8.0)
            ct = _lbfgs_block(cbest, np.arange(cbest.size), 800,
                              slice_end - 0.5, tie=True)
            ctR = R_of(_fine_from_coarse(ct, BLK))
            if ctR > cbestR + 1e-15:
                cbest, cbestR = ct, ctR
                print("  coarse full ACCEPT R=%.9f" % cbestR)
            else:
                break
        # Refine in fine space around the coarse optimum.
        hf = _fine_from_coarse(cbest, BLK)
        phaseB_end = t0 + budget_seconds * 0.75
        while time.process_time() < phaseB_end - 2.0:
            slice_end = min(phaseB_end, time.process_time() + 6.0)
            ht = _polish_full(hf, slice_end, maxiter=400)
            rt = R_of(ht)
            if rt > cbestR + 1e-15:
                hf, cbestR = ht, rt
                print("  fine full ACCEPT R=%.9f" % cbestR)
            else:
                break
        if cbestR > bestR + 1e-15:
            best, bestR = hf, cbestR
            print("coarse line won: R=%.9f" % bestR)

    # ---- Phase B: try resampling to alternative N values. ----
    alt_best = best
    alt_bestR = bestR
    race_end = t0 + budget_seconds * 0.80
    for mult in (1.5, 0.75, 2.0, 0.5, 3.0):
        if time.process_time() >= race_end - 3.0:
            break
        tgt = int(round(N * mult))
        tgt = max(64, min(1_000_000, tgt))
        if tgt == N:
            continue
        try:
            cand = _mass_resample(best, tgt)
        except Exception:
            continue
        slice_end = min(race_end, time.process_time() + 5.0)
        ht = _polish_full(cand, slice_end, maxiter=300)
        rt = R_of(ht)
        if rt > alt_bestR + 1e-15:
            alt_best, alt_bestR = ht, rt
        print("resample N=%d dR=%+.3e R=%.9f" % (tgt, rt - bestR, rt))

    if alt_bestR > bestR + 1e-15:
        best, bestR = alt_best, alt_bestR
        print("resample won: N=%d R=%.9f" % (best.size, bestR))

    # ---- Phase C: final full-grid polishing until deadline. ----
    loop_end = t0 + budget_seconds * 0.90
    it = 0
    while time.process_time() < loop_end - 2.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 6.0)
        ht = _polish_full(best, slice_end, maxiter=600)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
            print("final pass %d ACCEPT R=%.9f" % (it, bestR))
        else:
            print("final pass %d no gain R=%.9f" % (it, rt))
            break

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_band(h, eps, gamma):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    B = np.flatnonzero(Lf >= (1.0 - eps) * mx)
    if B.size > 0:
        gLf[B] -= gamma / (B.size * mx)
        deficit = float(np.mean(mx - Lf[B])) / mx
    else:
        deficit = 0.0
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + gamma * deficit
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, band=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if band is not None:
        eps, gamma = band
        fg = (lambda hh: _fun_grad_band(hh, eps, gamma))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _band_stats(h, eps):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0
    B = Lf >= (1.0 - eps) * mx
    frac = float(np.mean(B))
    if not np.any(B):
        return frac, 0.0
    deficit = float(np.mean(mx - Lf[B])) / mx
    return frac, deficit


def _deconv_step(h0, T, lam, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    Tn = float(np.sum(T * T))
    if Tn <= 0:
        return h0
    h0n = float(np.sum(h * h))
    if h0n <= 0:
        h0n = 1.0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        Lf = _knots(hh)
        r = Lf - T
        val = float(np.sum(r * r)) / Tn + lam * float(np.sum((hh - h) ** 2)) / h0n
        gLf = 2.0 * r / Tn
        g = _backprop(gLf, hh) + 2.0 * lam * (hh - h) / h0n
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _build_target(L, eps):
    mx = L.max()
    S = L >= (1.0 - eps) * mx
    T = L.copy()
    if not np.any(S):
        return T
    idx = np.flatnonzero(S)
    lo, hi = idx.min(), idx.max()
    val = L[S].mean()
    T[lo:hi + 1] = val
    k = 9
    ker = np.ones(k) / k
    T = np.convolve(T, ker, mode='same')
    return T


def _resample(h, N):
    """Linear-interpolation resample of step heights to N steps."""
    n = h.size
    if n == N:
        return h.copy()
    x = np.linspace(0.0, 1.0, n, endpoint=False) + 0.5 / n
    xn = np.linspace(0.0, 1.0, N, endpoint=False) + 0.5 / N
    return np.interp(xn, x, h, left=h[0], right=h[-1])


def _smooth_mask(h, k):
    """Return a boolean mask of h smoothed by a box of width k (for remeshing)."""
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return hs


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    full = np.arange(best.size)
    alt_best = None
    altR = -1.0

    def try_cand(hc, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hc)
        if r > altR:
            altR = r
            alt_best = hc.copy()
        if r > bestR + 1e-15:
            best, bestR = hc.copy(), r
            print("%s: R=%.12f NEW" % (tag, r))
        else:
            print("%s: R=%.12f" % (tag, r))
        return r

    # ---- Phase 1: deconvolution seeding at multiple eps ----
    for eps in [1e-2, 3e-3, 1e-3]:
        if time.process_time() >= deadline - 40.0:
            break
        L = _knots(best)
        T = _build_target(L, eps)
        tlim = min(deadline - 38.0, time.process_time() + 6.0)
        hd = _deconv_step(best, T, 1e-3, 80, tlim)
        try_cand(hd, "deconv eps=%.0e" % eps)
        if time.process_time() < deadline - 36.0:
            pol = _lbfgs_block(hd, np.arange(hd.size), 250,
                               min(deadline - 35.0, time.process_time() + 5.0))
            try_cand(pol, "  pol")

    # ---- Phase 2: band ladder ----
    ladder = [(0.05, 0.3), (0.05, 1.0), (0.05, 3.0), (0.03, 3.0),
              (0.02, 1.0), (0.02, 3.0), (0.01, 3.0)]
    rung_best = {}
    for (eps, gamma) in ladder:
        if time.process_time() >= deadline - 14.0:
            break
        tlim = min(deadline - 13.0, time.process_time() + 4.5)
        hb = _lbfgs_block(best, full, 250, tlim, band=(eps, gamma))
        rb = try_cand(hb, "band eps=%.2f g=%.1f" % (eps, gamma))
        rung_best[(eps, gamma)] = rb
        if time.process_time() < deadline - 10.0:
            pol = _lbfgs_block(hb, full, 250,
                               min(deadline - 9.0, time.process_time() + 4.0))
            rp = try_cand(pol, "  pol")
            rung_best[(eps, gamma)] = max(rb, rp)
            for pad in (0.05, 0.03):
                if time.process_time() >= deadline - 5.0:
                    break
                win = _peak_window(pol, pad_frac=pad, extra=96)
                ht = _lbfgs_block(pol, win, 300,
                                  min(deadline - 4.0, time.process_time() + 2.5))
                try_cand(ht, "  win pad=%.2f" % pad)

    fr1, def1 = _band_stats(best, 0.05)
    print("band eps=0.05 after: frac=%.4f deficit=%.6f" % (fr1, def1))

    # ---- Phase 3: remesh + cycle with remaining budget ----
    if rung_best:
        best_rung = max(rung_best, key=rung_best.get)
    else:
        best_rung = (0.05, 1.0)

    # Remeshing attempt: build a finer/cleaner grid from a smoothed copy.
    # This breaks the current local basin by re-parametrising the shape.
    remesh_done = False
    while time.process_time() < deadline - 2.5:
        if not remesh_done and time.process_time() < deadline - 20.0:
            remesh_done = True
            # Try a few grid sizes, pick the best after short polish
            for Nf in [best.size // 2, int(best.size * 0.75),
                       int(best.size * 1.25), best.size * 2]:
                if Nf < 64 or Nf > 900000:
                    continue
                if time.process_time() >= deadline - 16.0:
                    break
                hr = _resample(best, Nf)
                hr = _rescale(hr)
                # quick smooth to avoid artefact spikes at boundaries
                k = max(3, Nf // 4000)
                if k % 2 == 0:
                    k += 1
                hr = _smooth_mask(hr, k)
                hr = _rescale(hr)
                tlim = min(deadline - 15.0, time.process_time() + 4.0)
                hp = _lbfgs_block(hr, np.arange(hr.size), 250, tlim,
                                  band=best_rung)
                try_cand(hp, "remesh N=%d" % Nf)
            # If remesh improved, adopt the best; otherwise revert to prior best.
            # (best is already updated by try_cand when improved.)

        eps, gamma = best_rung
        tlim = min(deadline - 2.0, time.process_time() + 3.0)
        hb = _lbfgs_block(best, full, 200, tlim, band=(eps, gamma))
        pol = _lbfgs_block(hb, full, 200,
                           min(deadline - 1.0, time.process_time() + 2.0))
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
            try_cand(pol, "cycle")
        else:
            # Try a different rung to escape local optimum
            alt_rungs = [k for k in rung_best if k != best_rung]
            if alt_rungs:
                best_rung = max(alt_rungs, key=lambda k: rung_best[k])
                alt_rungs = [k for k in alt_rungs if k != best_rung]
            else:
                break

    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, full, 250,
                           min(deadline - 0.5, time.process_time() + 2.0))
        try_cand(pol, "final")

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, log=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if log:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
        if active.size == 0:
            return h0
        u0 = np.log(np.clip(h[active], 1e-300, None))
    else:
        active = np.arange(n)
        u0 = np.clip(h, 0.0, None)
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    if log:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fg(hh)
            return val, g[active] * hh[active]
        bounds = [(-30.0, 30.0)] * active.size
    else:
        def f(x):
            hh = np.zeros(n)
            hh[active] = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g[active]
        bounds = [(0.0, None)] * active.size

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    if log:
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    else:
        h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 2e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_log(best, 300, min(deadline - 0.5, time.process_time() + 6.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        hs = _lbfgs_log(best, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=beta)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 4.0), beta=0.0)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def _rand_field(M, rng, nk=6):
    e = np.zeros(M)
    for _ in range(nk):
        f = np.exp(rng.uniform(np.log(1.0), np.log(64.0)))
        ph = rng.uniform(0, 2 * np.pi)
        c = rng.normal()
        i = np.arange(M)
        e += c * np.sin(2 * np.pi * f * i / M + ph)
    m = np.max(np.abs(e))
    if m > 0:
        e /= m
    return e


def _apply_block_check(h, e, B):
    n = h.size
    edges = (np.arange(B + 1) * n) // B
    h2 = h.copy()
    for i in range(B):
        sign = 1.0 if (i % 2 == 0) else -1.0
        h2[edges[i]:edges[i + 1]] *= (1.0 + sign * e[i])
    return _rescale(np.clip(h2, 0.0, None))


def _apply_block_scale(h, e, B):
    n = h.size
    edges = (np.arange(B + 1) * n) // B
    h2 = h.copy()
    for i in range(B):
        h2[edges[i]:edges[i + 1]] *= (1.0 + e[i])
    return _rescale(np.clip(h2, 0.0, None))


def _block_additive(h0, B, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    B = max(1, min(B, n))
    edges = (np.arange(B + 1) * n) // B
    counts = np.diff(edges).astype(int)
    hmax = h.max()
    d0 = np.zeros(B)
    lo_bound = -0.5 * hmax

    def f(d):
        hh = h + np.repeat(d, counts)
        hh = np.clip(hh, 0.0, None)
        val, g = _fun_grad(hh)
        gb = np.add.reduceat(g, edges[:-1])
        return val, gb

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, d0, jac=True, method='L-BFGS-B',
                       bounds=[(lo_bound, None)] * B, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    d = res.x
    hh = np.clip(h + np.repeat(d, counts), 0.0, None)
    return _rescale(hh)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(13579)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    n = best.size
    if n < 4:
        return {"best": start_best, "alternative": start_best}

    experiment_best = best.copy()
    experiment_bestR = bestR

    # Phase 0: full free linear-mode L-BFGS to break symmetry.
    cap_t = min(deadline - 30.0, time.process_time() + 8.0)
    hs = _lbfgs_log(experiment_best, 400, cap_t, beta=0.0, log=False)
    rs = R_of(hs)
    print("  full-lin R=%.9f (dR=%+.2e)" % (rs, rs - experiment_bestR))
    if rs > experiment_bestR + 1e-13:
        experiment_best, experiment_bestR = hs.copy(), rs

    # Phase 1: block probes.
    probe_deadline = min(deadline - 25.0, time.process_time() + 10.0)
    candidates = []
    for B in (8, 16, 32, 64, 128, 256):
        for k in range(min(8, 3 + B // 32)):
            if time.process_time() >= probe_deadline:
                break
            e = np.zeros(B) if k == 0 else _rand_field(B, rng, nk=3)
            for d in (1e-3, 1e-2, 3e-2, 0.1):
                cand = _apply_block_check(experiment_best, d * e, B)
                candidates.append((R_of(cand), e.copy(), d, B, 'check'))
        for k in range(min(4, 2 + B // 64)):
            if time.process_time() >= probe_deadline:
                break
            e = np.zeros(B) if k == 0 else _rand_field(B, rng, nk=3)
            for d in (1e-3, 1e-2, 3e-2):
                cand = _apply_block_scale(experiment_best, d * e, B)
                candidates.append((R_of(cand), e.copy(), d, B, 'scale'))

    candidates.sort(key=lambda t: -t[0])
    print("  probes: %d evaluated, best raw R=%.9f (dR=%+.2e)" %
          (len(candidates), candidates[0][0] if candidates else 0,
           (candidates[0][0] - experiment_bestR) if candidates else 0))

    seen = set()
    top = []
    for c in candidates:
        key = (c[3], c[4], round(c[2], 8))
        if key in seen:
            continue
        seen.add(key)
        top.append(c)
        if len(top) >= 2:
            break

    for idx, (r, e, d, B, kind) in enumerate(top):
        if time.process_time() >= deadline - 12.0:
            break
        cand = _apply_block_check(experiment_best, d * e, B) if kind == 'check' \
            else _apply_block_scale(experiment_best, d * e, B)
        cap_t = min(deadline - 3.0, time.process_time() + 6.0)
        hp, rp = _polish(cand, cap_t, r)
        print("  polish top%d (B=%d %s) raw %.9f -> %.9f" % (idx, B, kind, r, rp))
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp
            print("    NEW BEST R=%.9f" % experiment_bestR)

    # Phase 2: block-additive with a wider range of block counts.
    for B in (64, 128, 256, 512, 1024, 2048, 4096):
        if time.process_time() >= deadline - 3.0:
            break
        cap_t = min(deadline - 1.5, time.process_time() + 4.0)
        hb = _block_additive(experiment_best, B, cap_t, maxiter=150)
        r_raw = R_of(hb)
        if r_raw >= experiment_bestR - 3e-3:
            hp, rp = _polish(hb, min(deadline - 0.5, time.process_time() + 4.0), experiment_bestR)
        else:
            hp, rp = hb, r_raw
        print("  B=%-5d raw R=%.9f polished R=%.9f" % (B, r_raw, rp))
        if rp > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hp.copy(), rp
            print("    NEW BEST R=%.9f" % experiment_bestR)

    # Phase 3: keep polishing until deadline.
    loop_end = deadline - 0.5
    it = 0
    while time.process_time() < loop_end:
        it += 1
        use_lin = (it % 5 == 0)
        cap_t = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_log(experiment_best, 200, cap_t, beta=0.0, log=not use_lin)
        rs = R_of(hs)
        if rs > experiment_bestR + 1e-13:
            experiment_best, experiment_bestR = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, experiment_bestR))
            continue
        if time.process_time() < loop_end - 1.0:
            beta = (1e3, 1e4, 1e5)[it % 3]
            cap_t = min(loop_end, time.process_time() + 3.0)
            hs = _lbfgs_log(experiment_best, 150, cap_t, beta=beta)
            rs = R_of(hs)
            if rs > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hs.copy(), rs
                print("  final beta=%g iter=%d R=%.9f" % (beta, it, experiment_bestR))
                continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.02 + 0.18 * rng.random()
            free = _peak_window(experiment_best, frac=frac)
            cap_t = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(experiment_best, free, 150, cap_t, beta=0.0)
            rp = R_of(hp)
            if rp > experiment_bestR + 1e-13:
                experiment_best, experiment_bestR = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, experiment_bestR))

    mx, m, near = _stats(experiment_best)
    print("final R=%.9f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (experiment_bestR, experiment_best.size,
           100.0 * np.mean(experiment_best <= 0), mx, m, near))

    if experiment_bestR > start_bestR + 1e-12:
        return {"best": experiment_best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": experiment_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return 1e18, np.zeros(h.size)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, free, maxiter, deadline):
    """L-BFGS-B in log space on free cells, exact tie objective."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hv = h[active]
    floor = max(1e-12, 1e-9 * h.mean())
    x0 = np.log(np.clip(hv, floor, None))

    def f(x):
        hh = h.copy()
        hh[active] = np.exp(np.clip(x, -60.0, 60.0))
        val, g = _fun_grad_tie(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -60.0, 60.0))
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def _polish(h, fd):
    ht = _lbfgs_all_pos(h, 200, fd)
    if R_of(ht) > R_of(h) + 1e-15:
        h = ht
    if time.process_time() < fd - 0.5:
        win = _peak_window(h, tol=0.95, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(h, win, 200, fd)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    # ---- D3 support flip: revive zeros / prune weak actives ----
    M_ladder = [8, 16, 32, 64]
    eps_ladder = [1e-3, 1e-2, 1e-1]

    def support_flip(h, M, eps, fd):
        h = np.clip(h, 0, None)
        n = h.size
        _, g = _fun_grad_tie(h)
        # g is gradient of -log R; positive g means increasing h[i] lowers -logR (raises R)
        zeros = np.flatnonzero(h <= 0)
        active = np.flatnonzero(h > 0)
        if zeros.size == 0 or active.size == 0:
            return h
        # rank zeros by positive gradient (most beneficial to revive)
        zord = zeros[np.argsort(-g[zeros])]
        rev = zord[:M]
        if rev.size == 0:
            return h
        h2 = h.copy()
        mean_h = h.mean()
        h2[rev] = eps * mean_h
        # optionally prune lowest-sensitivity active cells (most negative g)
        aord = active[np.argsort(g[active])]
        pr = aord[:min(M, aord.size)]
        h2[pr] = 0.0
        # free set: all active in h2 plus revived
        free = np.flatnonzero(h2 > 0)
        h2 = _lbfgs_log(h2, free, 200, fd)
        if time.process_time() < fd - 0.5:
            win = _peak_window(h2, tol=0.95, pad_frac=0.10, extra=128)
            h3 = _lbfgs_block(h2, win, 150, fd)
            if R_of(h3) > R_of(h2):
                h2 = h3
        return h2

    loop = 0
    while time.process_time() < deadline - 2.0:
        loop += 1
        improved = False
        for M in M_ladder:
            if time.process_time() >= deadline - 2.0:
                break
            for eps in eps_ladder:
                if time.process_time() >= deadline - 2.0:
                    break
                fd = min(deadline, time.process_time() + budget_seconds * 0.06)
                cand = support_flip(best, M, eps, fd)
                r = R_of(cand)
                if r > bestR + 1e-12:
                    best, bestR = cand.copy(), r
                    improved = True
                    print("loop %d flip M=%d eps=%.0e ACCEPT R=%.9f zf=%.4f"
                          % (loop, M, eps, bestR, _zero_frac(best)))
                    break
                else:
                    print("loop %d flip M=%d eps=%.0e reject R=%.9f (best %.9f) zf=%.4f"
                          % (loop, M, eps, r, bestR, _zero_frac(cand)))
        # after a full sweep, do a plain polish to consolidate
        if time.process_time() < deadline - 2.0:
            fd = min(deadline, time.process_time() + budget_seconds * 0.08)
            hp = _polish(best, fd)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
                print("loop %d polish ACCEPT R=%.9f zf=%.4f" % (loop, bestR, _zero_frac(best)))
        if not improved and loop >= 3:
            # no progress in a full sweep; keep trying but with polish only
            pass

    if time.process_time() < deadline - 1.0:
        fd = deadline - 0.5
        hp = _polish(best, fd)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_band(h, tau):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    band = Lf >= tau * M
    dev = M - Lf[band]
    S = float(np.sum(dev * dev)) + 1e-30
    gLf = np.zeros_like(Lf)
    gLf[band] = 2.0 * (Lf[band] - M)
    m = int(np.argmax(Lf))
    gLf[m] += 2.0 * float(np.sum(dev))
    grad = _backprop(gLf, h)
    val = np.log(S)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=False, band=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if band is not None:
        fg = lambda hh: _fun_grad_band(hh, band)
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N = best.size
    full = np.arange(N)

    # ---- Phase 1: band-flattening on the near-max band of g=f*f ----
    # This is the genuinely different idea: flatten the top band of the
    # autoconvolution, which raises the effective L^inf while keeping the
    # L^2 mass, then re-tie-polish.
    reserve = 8.0
    alt_best = None
    altR = -1.0
    band_best = best.copy()
    band_bestR = bestR
    band_improved = False
    for tau in (0.999, 0.995, 0.99, 0.98, 0.96):
        if time.process_time() >= deadline - reserve:
            break
        tlim = min(deadline - reserve, time.process_time() + 5.0)
        cand = _lbfgs_block(best, full, 120, tlim, band=tau)
        if cand is None:
            continue
        r = R_of(cand)
        print("band tau=%.4f R=%.12f (best %.12f)" % (tau, r, band_bestR))
        if r > band_bestR + 1e-15:
            band_best, band_bestR = cand.copy(), r
            band_improved = True
        if r > altR:
            altR, alt_best = r, cand.copy()

    if band_improved:
        best, bestR = band_best.copy(), band_bestR

    # ---- Phase 2: full-N tie polish ----
    if time.process_time() < deadline - 4.0:
        pol = _lbfgs_block(best, full, 250,
                           min(deadline - 3.0, time.process_time() + 8.0), tie=True)
        rp = R_of(pol)
        print("full tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        if rp > altR:
            altR, alt_best = rp, pol.copy()

    # ---- Phase 3: peak-window tie polish ----
    for pad in (0.08, 0.05, 0.03):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.3, time.process_time() + 3.0), tie=True)
        r = R_of(ht)
        print("peak polish pad=%.2f R=%.12f" % (pad, r))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > altR:
            altR, alt_best = r, ht.copy()

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, band_improved=%s)"
          % (bestR, startR, best.size, band_improved))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
