    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, free, maxiter, deadline, cvar_q=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    floor = 1e-12 * max(h.max(), 1e-30)
    u0 = np.log(np.clip(h[active], floor, None))
    fg = (lambda hh: _fun_grad_cvar(hh, cvar_q)) if cvar_q is not None else _fun_grad_tie

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _find_block(h, tol=1e-9):
    """Detect the largest BLK>1 such that h is (approximately) block-constant."""
    N = h.size
    if N < 2:
        return 1
    # try blocks that divide N, coarse-to-fine
    for BLK in range(min(256, N), 1, -1):
        if N % BLK != 0:
            continue
        K = N // BLK
        c = h.reshape(K, BLK)
        scale = max(np.abs(c).max(), 1e-30)
        # check block-constant with relative tolerance scaled by overall magnitude
        if np.max(np.abs(c - c[:, :1])) <= tol * scale:
            return BLK
    return 1


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best = None
    startR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size
    allidx = np.arange(N)

    # Stage 1: full-length CVaR homotopy to sharpen the peak region.
    cur = best.copy()
    for q in (0.98, 0.995, 0.999):
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + budget_seconds * 0.14)
        cand = _lbfgs_log(cur, allidx, 120, tlim, cvar_q=q)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand.copy(), r
        cur = cand

    # Stage 2: alternate full-length tie polish and peak-window polish.
    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        tlim = min(deadline - 0.5, time.process_time() + budget_seconds * 0.16)
        cand = _lbfgs_log(best, allidx, 80, tlim)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r

        for pad in (0.05, 0.02):
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            tlim = min(deadline - 0.4, time.process_time() + budget_seconds * 0.10)
            cand = _lbfgs_log(best, win, 120, tlim)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r

        print("cycle %d R=%.12f ties=%d" % (cycle, bestR, _tie_count(best)))

    # Stage 3: block-structured refinement. Exploit any block-constancy in the
    # current best: optimize at block resolution, then lift back to full length.
    # This can resolve flat tie structure at higher precision than full-length
    # L-BFGS, and the lifted result may score higher.
    if time.process_time() < deadline - 1.5:
        BLK = _find_block(best, tol=1e-7)
        if BLK > 1:
            K = N // BLK
            c0 = best.reshape(K, BLK).mean(axis=1)
            hc = np.repeat(np.clip(c0, 0, None), BLK)
            hc = _rescale(hc)
            rc = R_of(hc)
            if rc > bestR + 1e-14:
                best, bestR = hc.copy(), rc
            # Block-level refinement on the compressed vector.
            for _ in range(6):
                if time.process_time() >= deadline - 0.6:
                    break
                idx = np.arange(K)
                tlim = min(deadline - 0.4, time.process_time() + budget_seconds * 0.05)
                # Optimize on the compressed representation using the full N
                # objective (lifted) via a custom closure.
                if time.process_time() >= tlim - 0.3:
                    break
                floor = 1e-12 * max(c0.max(), 1e-30)
                u0 = np.log(np.clip(hc[::BLK], floor, None))

                def f(u, _BLK=BLK):
                    cc = np.exp(np.clip(u, -40.0, 40.0))
                    hh = np.repeat(cc, _BLK)
                    val, g = _fun_grad_tie(hh)
                    # chain-rule back to blocks
                    gg = g.reshape(cc.size, _BLK).sum(axis=1) * cc
                    return val, gg

                cb = _make_cb(tlim - 0.2)
                try:
                    res = minimize(f, u0, jac=True, method='L-BFGS-B',
                                   bounds=[(-40.0, 40.0)] * K,
                                   callback=cb,
                                   options={'maxiter': 120, 'maxfun': 240,
                                            'ftol': 1e-20, 'gtol': 1e-16})
                except (TimeoutError, Exception):
                    break
                if res is None or not res.success and res.fun is None:
                    break
                cc = np.exp(np.clip(res.x, -40.0, 40.0))
                hc = _rescale(np.repeat(cc, BLK))
                rc = R_of(hc)
                if rc > bestR + 1e-14:
                    best, bestR = hc.copy(), rc
                else:
                    break

    # Stage 4: final full-length polish on remaining time.
    if time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.3, time.process_time() + budget_seconds * 0.15)
        cand = _lbfgs_log(best, allidx, 120, tlim)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

