    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _perturb_window_at(h, lo, hi, rng, sigma=0.30):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo))
    hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _prolongate(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def _downsample(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at) * (M / N)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def _polish_chain(h, deadline, log_iters, sm_betas, sm_iters, polish_fracs,
                  polish_extra, polish_iters):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=log_iters, deadline=deadline))
    for beta in sm_betas:
        if time.process_time() >= deadline - 0.5:
            break
        _try(_lbfgs_sm(cur, beta, maxiter=sm_iters, deadline=deadline))
    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=log_iters, deadline=deadline))
    for frac in polish_fracs:
        if time.process_time() >= deadline - 0.5:
            break
        _try(_window_polish_peak(cur, deadline, frac, polish_extra,
                                 maxiter=polish_iters, beta=None))
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # ============ NEW MAIN EXPERIMENT: multi-resolution lift =============
    # Downsample start to a coarse grid, polish hard, then lift back to a
    # HIGHER resolution than the start and polish. The lift to more steps
    # (rather than just regrowing to the same N) is the new idea: it gives
    # the optimiser extra degrees of freedom to sharpen the peak region.
    # We try two coarse levels and two lift targets, using whichever start
    # resolution is available.
    N0 = base.size
    results = []

    coarse_levels = [max(2000, N0 // 8), max(4000, N0 // 4)]
    for Nc in coarse_levels:
        if time.process_time() >= hard_end - 3.0:
            break
        hc = _downsample(base, Nc)
        hc, rc = _polish_chain(
            hc, hard_end,
            log_iters=1500,
            sm_betas=(200.0, 1000.0, 4000.0),
            sm_iters=350,
            polish_fracs=(),
            polish_extra=0,
            polish_iters=0,
        )
        if time.process_time() < hard_end - 2.0:
            c = _lbfgs_log(hc, maxiter=1000, deadline=hard_end)
            if R_of(c) > rc:
                hc, rc = c, R_of(c)
        results.append((Nc, hc, rc))
        print("coarse %d R=%.6f" % (Nc, rc))

    # Lift each coarse solution up to higher resolution and polish.
    for (Nc, hc, rc) in results:
        if time.process_time() >= hard_end - 2.0:
            break
        for Nf in (min(200000, Nc * 4), min(200000, Nc * 8)):
            if time.process_time() >= hard_end - 1.5:
                break
            hf = _prolongate(hc, Nf)
            hf, rf = _polish_chain(
                hf, hard_end,
                log_iters=800,
                sm_betas=(400.0, 2000.0, 6000.0),
                sm_iters=250,
                polish_fracs=(0.05, 0.10, 0.20),
                polish_extra=8,
                polish_iters=300,
            )
            print("lift %d->%d R=%.6f" % (Nc, Nf, rf))
            if rf > base_r:
                _consider(hf, rf)

    print("experiment R=%.6f N=%d | base R=%.6f N=%d"
          % (best_r, best.size, base_r, base.size))

    # ============ Also: fine polish at original resolution ===============
    if time.process_time() < hard_end - 3.0:
        hf, rf = _polish_chain(
            base, hard_end,
            log_iters=1200,
            sm_betas=(300.0, 1500.0, 5000.0),
            sm_iters=300,
            polish_fracs=(0.05, 0.10, 0.20),
            polish_extra=8,
            polish_iters=350,
        )
        print("fine-base R=%.6f" % rf)
        if rf > base_r:
            _consider(hf, rf)

    # ============ Fallback refinement loop ===============================
    try:
        cur = best.copy()
        cur_r = best_r
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (150.0, 70.0, 35.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            if R_of(h) > cur_r:
                cur, cur_r = h, R_of(h)
                _consider(h, cur_r)
            if time.process_time() >= hard_end - 1.0:
                break
        print("fallback R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, beta=1e7):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_soft(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _detect_repeat(h):
    n = h.size
    for p in (64, 32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            return p, c
    return 1, h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f N=%d" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- Phase A: soft-max L-BFGS at full resolution with decreasing beta ----
    # The key idea is that a soft-max surrogate (log-sum-exp) gives smoother
    # gradients near the peak tie than hard max, letting L-BFGS move past
    # flat plateaus. Descend beta from large to small (annealed continuation).
    a_end = t0 + budget_seconds * 0.60
    cur_full = best.copy()
    cur_R = bestR
    n_full = best.size
    all_idx = np.arange(n_full)

    betas_A = [1e6, 1e5, 1e4, 1e3, 1e2, 30.0, 10.0, 3.0, 1.0]
    for bi, beta in enumerate(betas_A):
        if time.process_time() >= a_end - 0.5:
            break
        h1 = _lbfgs(cur_full, all_idx, 400,
                    min(a_end - 0.3, time.process_time() + 3.0),
                    beta=beta)
        r = R_of(h1)
        if r > cur_R + 1e-14:
            cur_full, cur_R = h1, r
        print("  phaseA beta=%.0e R=%.12f" % (beta, cur_R))

    if cur_R > bestR + 1e-15:
        best, bestR = cur_full, cur_R
        print("phaseA ACCEPT R=%.12f" % bestR)

    # ---- Phase B: local window polish at full resolution, tiny beta ----
    c_end = deadline
    for beta in (1e3, 100.0, 10.0, 1.0):
        if time.process_time() >= c_end - 0.5:
            break
        Lf = _knots(best)
        mx = Lf.max()
        idx = np.flatnonzero(Lf >= 0.99 * mx)
        if idx.size == 0:
            win = all_idx
        else:
            lo = max(0, idx.min() - 1)
            hi = min(best.size - 1, idx.max())
            pad = max(256, int((hi - lo) * 0.75))
            lo = max(0, lo - pad)
            hi = min(best.size - 1, hi + pad)
            win = np.arange(lo, hi + 1)
        h1 = _lbfgs(best, win, 400,
                    min(c_end - 0.3, time.process_time() + 2.5),
                    beta=beta)
        r = R_of(h1)
        if r > bestR + 1e-15:
            best, bestR = h1, r
        print("phaseB beta=%.0e R=%.12f" % (beta, bestR))

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)):
        return -1.0
    if np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    L2 = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    Linf = np.max(L)
    if Linf <= 0:
        return -1.0
    return L2 / (s * s * Linf)


def _build_chirp(N, M, c, d, hk):
    """Build chirped comb on N cells with M teeth, chirp rate c, duty d."""
    if M < 2:
        M = 2
    k = np.arange(M)
    centre_idx = (M - 1) / 2.0
    if centre_idx <= 0:
        centre_idx = 1.0
    s = 1.0 + c * (k - centre_idx) / centre_idx
    s = np.maximum(s, 0.05)
    s = s / s.sum() * N
    # centres
    X = np.concatenate(([0.0], np.cumsum(s)[:-1]))
    widths = d * s
    h = np.zeros(N)
    for i in range(M):
        lo = int(round(X[i]))
        hi = int(round(X[i] + widths[i]))
        if hi <= lo:
            hi = lo + 1
        if lo < 0:
            lo = 0
        if hi > N:
            hi = N
        if hi <= lo:
            continue
        w = np.linspace(1.0, 1.0, hi - lo)  # flat taper (linear taper across tooth)
        # linear taper: 0.5 at edges, 1 at center? Use simple ramp
        m = hi - lo
        if m >= 2:
            ramp = np.linspace(0.5, 1.0, m)
            ramp = np.minimum(ramp, ramp[::-1])
        else:
            ramp = np.ones(m)
        h[lo:hi] = np.maximum(h[lo:hi], hk[i] * ramp)
    return h


def _extract_tooth_heights(h, N, M, c, d):
    """Given a fine array, extract average height per tooth region."""
    k = np.arange(M)
    centre_idx = (M - 1) / 2.0
    if centre_idx <= 0:
        centre_idx = 1.0
    s = 1.0 + c * (k - centre_idx) / centre_idx
    s = np.maximum(s, 0.05)
    s = s / s.sum() * N
    X = np.concatenate(([0.0], np.cumsum(s)[:-1]))
    widths = d * s
    hk = np.zeros(M)
    for i in range(M):
        lo = int(round(X[i]))
        hi = int(round(X[i] + widths[i]))
        if hi <= lo:
            hi = lo + 1
        lo = max(0, lo)
        hi = min(N, hi)
        if hi > lo:
            hk[i] = h[lo:hi].mean()
    return hk


def _objective_hk(loghk, N, M, c, d):
    hk = np.exp(np.clip(loghk, -20, 20))
    h = _build_chirp(N, M, c, d, hk)
    return -_R_of(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0):
            r = _R_of(s)
            if r > best_R:
                best_R = r
                best_h = s.copy()

    N = 131072
    # Seed scan
    Ms = [256, 512, 1024, 2048]
    cs = [0.0, 0.25, -0.25, 0.5, -0.5, 0.8, -0.8]
    ds = [0.15, 0.25, 0.35]

    candidates = []
    for M in Ms:
        k = np.arange(M)
        hk0 = 1.0 / np.sqrt((k + 1.0) * (M - k))
        hk0 = hk0 / hk0.max()
        for c in cs:
            for d in ds:
                if time.process_time() > deadline:
                    break
                h = _build_chirp(N, M, c, d, hk0)
                r = _R_of(h)
                candidates.append((r, M, c, d, hk0.copy()))
            if time.process_time() > deadline:
                break
        if time.process_time() > deadline:
            break

    candidates.sort(key=lambda x: -x[0])
    top = candidates[:3]

    # Climb on top few
    for (r0, M, c, d, hk0) in top:
        if time.process_time() > deadline:
            break
        loghk0 = np.log(np.maximum(hk0, 1e-6))
        try:
            res = minimize(
                _objective_hk, loghk0,
                args=(N, M, c, d),
                method='L-BFGS-B',
                options={'maxiter': 200, 'maxfun': 400},
            )
            hk = np.exp(np.clip(res.x, -20, 20))
        except Exception:
            hk = hk0
        # try chirp rescans around c
        best_local_c = c
        best_local_R = -1.0
        best_local_h = None
        for dc in [0.0, 0.05, -0.05, 0.1, -0.1, 0.2, -0.2]:
            if time.process_time() > deadline:
                break
            cc = c + dc
            h = _build_chirp(N, M, cc, d, hk)
            rr = _R_of(h)
            if rr > best_local_R:
                best_local_R = rr
                best_local_c = cc
                best_local_h = h
        if best_local_h is not None and best_local_R > best_R:
            best_R = best_local_R
            best_h = best_local_h

    # Final fine polish on the best comb: re-optimize hk with more iterations
    if best_h is not None and time.process_time() < deadline:
        # Try to identify which M/c/d produced best; re-scan
        best_params = None
        best_rr = -1.0
        for (r0, M, c, d, hk0) in top:
            hk = _extract_tooth_heights(best_h, N, M, c, d)
            h = _build_chirp(N, M, c, d, hk)
            rr = _R_of(h)
            if rr > best_rr:
                best_rr = rr
                best_params = (M, c, d, hk)
        if best_params is not None:
            M, c, d, hk = best_params
            loghk = np.log(np.maximum(hk, 1e-6))
            try:
                res = minimize(
                    _objective_hk, loghk,
                    args=(N, M, c, d),
                    method='L-BFGS-B',
                    options={'maxiter': 300, 'maxfun': 600},
                )
                hk2 = np.exp(np.clip(res.x, -20, 20))
                h2 = _build_chirp(N, M, c, d, hk2)
                r2 = _R_of(h2)
                if r2 > best_R:
                    best_R = r2
                    best_h = h2
            except Exception:
                pass

    if best_h is None:
        best_h = np.ones(50)

    # Compare with start
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0):
            r_start = _R_of(s)
            r_new = _R_of(best_h)
            if r_new > r_start:
                return {"best": best_h, "alternative": s}
            else:
                return {"best": s, "alternative": best_h}
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        return _fun_grad_tie(np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _find_block(h):
    N = h.size
    for BLK in range(min(96, N), 1, -1):
        if N % BLK != 0:
            continue
        K = N // BLK
        c = h.reshape(K, BLK)
        if np.allclose(c, c[:, :1], rtol=1e-10, atol=1e-14):
            # Must be truly near-constant
            m = c.mean(axis=1, keepdims=True)
            if np.all(np.abs(c - m) <= 1e-9 * (np.abs(m) + 1e-15)):
                return BLK
    return 1


def _solve_block(h, BLK, deadline, maxiter=200):
    """Optimise on block-constant subspace (K free vars)."""
    if time.process_time() >= deadline - 0.5:
        return h
    N = h.size
    K = N // BLK
    c0 = h.reshape(K, BLK).mean(axis=1)

    def expand(c):
        return np.repeat(np.clip(c, 0.0, None), BLK)

    def f(c):
        hh = expand(c)
        val, g = _fun_grad_tie(hh)
        # chain: derivative w.r.t. block value = BLK * mean over block of gradient
        gb = g.reshape(K, BLK).sum(axis=1)
        return val, gb

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, c0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * K, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    return _rescale(expand(res.x))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Detect block structure in start -> optimise on reduced coordinates
    BLK = _find_block(best)
    print("block size detected: %d (K=%d)" % (BLK, best.size // BLK))

    if BLK > 1:
        hb = _solve_block(best, BLK, deadline)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb.copy(), rb
            print("block-solve NEW BEST R=%.9f" % bestR)

    # Full-space tie-aware polish
    while time.process_time() < deadline - 1.0:
        fd = min(deadline, time.process_time() + budget_seconds * 0.20)
        ht = _lbfgs_all_pos(best, 250, fd)
        r = R_of(ht)
        if r > bestR + 1e-16:
            best, bestR = ht.copy(), r
            print("full-polish ACCEPT R=%.9f" % bestR)
        else:
            break

    # If still block-structured: re-solve block after full-polish nudges
    if BLK > 1 and time.process_time() < deadline - 1.0:
        hb = _solve_block(best, BLK, deadline)
        rb = R_of(hb)
        if rb > bestR + 1e-16:
            best, bestR = hb.copy(), rb
            print("block re-solve NEW BEST R=%.9f" % bestR)

    # Final full-space polish with remaining time
    fd = min(deadline, time.process_time() + budget_seconds * 0.30)
    ht = _lbfgs_all_pos(best, 400, fd)
    r = R_of(ht)
    if r > bestR + 1e-16:
        best, bestR = ht.copy(), r
        print("final-polish ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    if bestR > start_bestR + 1e-14:
        return {"best": best}
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options={'maxiter': maxiter,
                                             'maxfun': 2 * maxiter,
                                             'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.4:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.25, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.25, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r

    # ---- Phase 1: aggressive high-beta sharpening ladder (cheap, high value) ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e9, 1e10, 1e11, 1e8, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Phase 2: half-resolution quotient polish + lift ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 8.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline - 5.0,
                                betas=(1e9, 1e10, 1e8, 0.0), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase 3: basin perturbations around best ----
    rng = np.random.RandomState(987654)

    def _basin_try(h, dl, n_tries=40, amp=0.05):
        cur = h
        curR = R_of(cur)
        n = h.size
        Lf = _knots(h)
        M = Lf.max() if Lf.size else 1.0
        zero_idx = np.flatnonzero(h <= 0)
        peak_idx = np.flatnonzero(Lf >= 0.5 * M)
        if peak_idx.size:
            peak_cells = np.unique(np.clip(peak_idx // 2, 0, n - 1))
        else:
            peak_cells = np.arange(n)
        for t in range(n_tries):
            if time.process_time() > dl - 1.0:
                break
            cand = cur.copy()
            if t % 3 == 0 and zero_idx.size > 0:
                k = rng.randint(1, 4)
                sel = rng.choice(zero_idx, size=min(k, zero_idx.size), replace=False)
                cand[sel] = amp * cur.max() * rng.rand(sel.size)
            else:
                k = rng.randint(1, 8)
                sel = rng.choice(peak_cells, size=min(k, peak_cells.size), replace=False)
                cand[sel] *= (1.0 + amp * (rng.rand(sel.size) - 0.5))
                cand = np.clip(cand, 0, None)
            ht = _lbfgs_all_pos(cand, 120, dl - 0.5, beta=1e10)
            if R_of(ht) > curR + 1e-15:
                ht2 = _lbfgs_all_pos(ht, 120, dl - 0.4, beta=0.0)
                if R_of(ht2) > R_of(ht):
                    ht = ht2
                r = R_of(ht)
                if r > curR + 1e-15:
                    cur, curR = ht, r
        return cur

    if time.process_time() < deadline - 6.0:
        cand = _basin_try(best, deadline - 5.0, n_tries=50, amp=0.08)
        offer(cand, 'basin')

    # ---- Phase 4: peak-band free block optimisation ----
    if time.process_time() < deadline - 4.0:
        win = _peak_window(best, pad_frac=0.10, extra=200)
        ht = _lbfgs_block(best, win, 500, deadline - 3.0, beta=1e10)
        ht = _polish_ladder(ht, deadline - 2.0, betas=(1e9, 0.0), iters=200)
        offer(ht, 'band')

    # ---- Phase 5: final polish ----
    ht = _polish_ladder(best, deadline - 0.5, betas=(1e10, 0.0), iters=250)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.3, pads=(0.06, 0.04), iters=300)
    offer(ht, 'finalpk')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_p(h):
    n = h.size
    for p in (32, 16, 8, 64, 24, 48):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-6, atol=1e-9):
            return p
    return 32


def _wmod_block(h, p, maxiter, deadline):
    n = h.size
    if n % p != 0:
        return h
    m = n // p
    if m < 2:
        return h
    H = h.reshape(m, p)
    c = H.mean(axis=1)
    if np.any(c <= 0):
        c = np.clip(c, 1e-12, None)
    w = (H / c[:, None]).mean(axis=0)
    if np.any(w <= 0):
        w = np.clip(w, 1e-12, None)
    lw = np.log(w)
    shift = lw.mean()
    lw = lw - shift
    c = c * np.exp(shift)
    w = np.exp(lw)

    def unpack(x):
        lc = x[:m]
        lw2 = x[m:]
        cc = np.exp(lc)
        ww = np.exp(lw2)
        sh = lw2.mean()
        if sh != 0.0:
            cc = cc * np.exp(sh)
            ww = ww * np.exp(-sh)
        return cc, ww

    def f(x):
        cc, ww = unpack(x)
        hh = (cc[:, None] * ww[None, :]).ravel()
        val, g = _fun_grad_tie(hh)
        G = g.reshape(m, p)
        HW = cc[:, None] * ww[None, :]
        gc = (G * HW).sum(axis=1)
        gw = (G * HW).sum(axis=0)
        gm = gw.mean()
        gw = gw - gm
        gc = gc + gm
        return val, np.concatenate([gc, gw])

    x0 = np.concatenate([np.log(c), lw])
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    cc, ww = unpack(res.x)
    hh = (cc[:, None] * ww[None, :]).ravel()
    return _rescale(hh)


def _quotient_block(h, pp, maxiter, deadline):
    n = h.size
    if n % pp != 0:
        return h
    m = n // pp
    if m < 2:
        return h
    c0 = h.reshape(m, pp).mean(axis=1)

    def fq(x):
        c = np.clip(x, 0.0, None)
        hh = np.repeat(c, pp)
        val, g = _fun_grad_tie(hh)
        gc = g.reshape(m, pp).sum(axis=1)
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(fq, c0.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * m, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    return _rescale(np.repeat(np.clip(res.x, 0.0, None), pp))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase W: residue-class multiplier optimization ----
    w_end = t0 + budget_seconds * 0.62
    p = _detect_p(best)
    print("wmod p=%d" % p)
    for blk in range(4):
        if time.process_time() >= w_end - 1.5:
            break
        prevR = bestR
        ht = _wmod_block(best, p, 200, min(w_end - 0.5,
                                           time.process_time() + 12.0))
        r = R_of(ht)
        dR = r - prevR
        print("wmod R=%.9f dR=%.2e" % (r, dR))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    # ---- Phase Q: quotient L-BFGS at p=32, then 16, then 8 ----
    q_end = t0 + budget_seconds * 0.74
    for pp in (32, 16, 8):
        if time.process_time() >= q_end - 1.0:
            break
        h2 = _quotient_block(best, pp, 400,
                             min(q_end - 0.3,
                                 time.process_time() + 8.0))
        r2 = R_of(h2)
        if r2 > bestR + 1e-15:
            best, bestR = h2, r2
            print("quot p=%d ACCEPT R=%.9f" % (pp, bestR))

    # ---- Phase P: peak ladder ----
    peak_end = t0 + budget_seconds * 0.86
    pads = (0.06, 0.03, 0.02, 0.012)
    for pad in pads:
        if time.process_time() >= peak_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        for beta, tie, flat in ((1e7, False, False),
                                (0.0, True, False),
                                (0.0, False, True)):
            if time.process_time() >= peak_end - 0.8:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(peak_end - 0.5,
                                  time.process_time() + 3.0),
                              beta=beta, tie=tie, flat=flat)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---- Phase F: final short peak-window tie polish ----
    fd = t0 + budget_seconds * 0.99
    if time.process_time() < fd - 1.5:
        win = _peak_window(best, pad_frac=0.02, extra=48)
        ht = _lbfgs_block(best, win, 200,
                          min(fd - 0.5, time.process_time() + 2.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final peak ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

