def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _timed_beta_pass(h, beta, iters, cap_seconds):
    t0 = time.process_time()
    deadline = t0 + cap_seconds
    ht = _lbfgs_all_pos(h, iters, deadline, beta=beta)
    return ht, time.process_time() - t0


def _find_block(h):
    """Find largest BLK>1 dividing N such that h is (near) exactly block-constant."""
    N = h.size
    for BLK in range(min(64, N), 1, -1):
        if N % BLK != 0:
            continue
        K = N // BLK
        c = h.reshape(K, BLK)
        if np.allclose(c, c[:, :1], rtol=1e-9, atol=1e-13):
            return BLK
    return 1


def _coarse_optimize(h, deadline):
    """If h is block-constant, optimize the K block values directly."""
    BLK = _find_block(h)
    if BLK == 1:
        return h
    K = h.size // BLK
    c0 = h.reshape(K, BLK).mean(axis=1)

    def make_h(cc):
        return np.repeat(np.clip(cc, 0, None), BLK)

    def f(c):
        hh = make_h(c)
        val, g = _fun_grad(hh)
        gk = g.reshape(K, BLK).sum(axis=1)
        return val, gk

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * K,
                       callback=cb,
                       options={'maxiter': 200, 'maxfun': 400,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    return _rescale(np.clip(make_h(res.x), 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.5

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # New idea: if the start is block-constant, optimize the block values
    # directly (far cheaper per iteration, breaks through plateau).
    # Then prolongate back to full resolution.
    BLK = _find_block(h)
    print("block factor = %d" % BLK)
    if BLK > 1 and time.process_time() < deadline - 5.0:
        cap = min(0.4 * (deadline - time.process_time()), 20.0)
        hc = _coarse_optimize(h, time.process_time() + cap)
        rc = R_of(hc)
        print("coarse opt R=%.6f (from %.6f)" % (rc, best_R))
        if rc > best_R + 1e-13:
            # prolongate back to full N and polish
            hfull = _rescale(_prolongate_mass(hc, h.size))
            # immediately try to recover the exact block structure
            hfull = _rescale(np.repeat(
                hfull.reshape(h.size // BLK, BLK).mean(axis=1), BLK))
            rf = R_of(hfull)
            if rf > best_R + 1e-13:
                best_h, best_R = hfull, rf
                print("reprolongated R=%.6f" % best_R)

    hw = best_h.copy()
    Rw = best_R

    betas = (16, 32, 64, 128, 256, 512, 1024)
    pad_fracs = (0.30, 0.15, 0.08)

    def phase_B(hw, Rw):
        for beta in betas:
            if time.process_time() > deadline - 3.0:
                return hw, Rw
            cap = min(8.0, deadline - time.process_time() - 2.0)
            if cap < 0.5:
                return hw, Rw
            ht = _lbfgs_all_pos(hw, 60, time.process_time() + cap, beta=beta)
            r = R_of(ht)
            if r > Rw + 1e-13:
                hw, Rw = ht, r
            print("rung beta=%d R=%.6f" % (beta, Rw))
            for pf in pad_fracs:
                if time.process_time() > deadline - 2.0:
                    break
                win = _peak_window(hw, 1.0, pf, 512)
                cap2 = min(4.0, deadline - time.process_time() - 1.5)
                if cap2 < 0.3:
                    break
                ht2 = _lbfgs_block(hw, win, 80,
                                   time.process_time() + cap2, beta=beta)
                r2 = R_of(ht2)
                if r2 > Rw + 1e-13:
                    hw, Rw = ht2, r2
            if time.process_time() < deadline - 1.5:
                win = _peak_window(hw, 1.0, 0.05, 512)
                cap3 = min(4.0, deadline - time.process_time() - 1.0)
                if cap3 > 0.3:
                    ht3 = _lbfgs_block(hw, win, 80,
                                       time.process_time() + cap3, beta=0.0)
                    r3 = R_of(ht3)
                    if r3 > Rw + 1e-13:
                        hw, Rw = ht3, r3
            print("  after polishes R=%.6f" % Rw)
        return hw, Rw

    def phase_C(hw, Rw):
        if time.process_time() > deadline - 3.0:
            return hw, Rw
        mean = hw.mean()
        keep = hw >= 1e-4 * mean
        if keep.sum() < 16 or keep.sum() == hw.size:
            return hw, Rw
        hc = hw[keep].copy()
        cap = min(3.0, deadline - time.process_time() - 2.0)
        if cap > 0.3:
            ht = _lbfgs_all_pos(hc, 60, time.process_time() + cap, beta=256)
            rc = R_of(ht)
            if rc > 0:
                hc = ht
        hfull = _rescale(_prolongate_mass(hc, hw.size))
        rf = R_of(hfull)
        if rf > Rw + 1e-13:
            hw, Rw = hfull, rf
            print("prune+reprolongate R=%.6f (kept %d/%d)" % (Rw, keep.sum(), keep.size))
        else:
            print("prune+reprolongate no gain R=%.6f" % Rw)
        if time.process_time() < deadline - 1.5:
            win = _peak_window(hw, 1.0, 0.05, 512)
            cap = min(3.0, deadline - time.process_time() - 1.0)
            if cap > 0.3:
                ht = _lbfgs_block(hw, win, 80, time.process_time() + cap, beta=0.0)
                r = R_of(ht)
                if r > Rw + 1e-13:
                    hw, Rw = ht, r
                    print("  tight polish R=%.6f" % Rw)
        return hw, Rw

    iteration = 0
    while time.process_time() < deadline - 2.0:
        iteration += 1
        hw, Rw = phase_B(hw, Rw)
        if Rw > best_R:
            best_R, best_h = Rw, hw.copy()
        print("after B#%d R=%.6f best=%.6f" % (iteration, Rw, best_R))
        if time.process_time() > deadline - 2.0:
            break
        hw, Rw = phase_C(hw, Rw)
        if Rw > best_R:
            best_R, best_h = Rw, hw.copy()
        print("after C#%d R=%.6f best=%.6f" % (iteration, Rw, best_R))
        if time.process_time() > deadline - 4.0:
            break

    # Final coarse-block optimization on the best full-res result.
    if time.process_time() < deadline - 3.0:
        BLK2 = _find_block(best_h)
        if BLK2 > 1:
            cap = min(deadline - time.process_time() - 1.5, 6.0)
            if cap > 0.5:
                hc = _coarse_optimize(best_h, time.process_time() + cap)
                hfull = _rescale(np.repeat(
                    hc.reshape(best_h.size // BLK2, BLK2).mean(axis=1), BLK2))
                rf = R_of(hfull)
                if rf > best_R + 1e-13:
                    best_h, best_R = hfull, rf
                    print("final coarse R=%.6f" % best_R)

    if time.process_time() < deadline - 1.0:
        cap = deadline - time.process_time() - 0.5
        ht = _lbfgs_all_pos(best_h, 100, time.process_time() + cap, beta=0.0)
        r = R_of(ht)
        if r > best_R:
            best_R, best_h = r, ht.copy()

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    """Soft-tie gradient: distribute grad over near-max knots to escape
    the flat ridge that the single-argmax gradient gets stuck on."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-6))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if tie:
        fg = _fun_grad_tie
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_cvar(h0, free, maxiter, deadline, q):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_cvar(hh, q)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- CVaR pass: broaden the flat top so the tie-gradient has room ----

def _cvar_pass(best, bestR, deadline):
    for q in (0.90, 0.95, 0.98):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, tol=0.85, pad_frac=0.6, extra=512)
        ht = _lbfgs_block_cvar(best, win, 300, deadline - 0.5, q=q)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        if time.process_time() < deadline - 0.5:
            pw = _peak_window(best, pad_frac=0.15, extra=128)
            ht2 = _lbfgs_block(best, pw, 100, deadline - 0.5, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-13:
                best, bestR = ht2.copy(), r2
        print("cvar q=%.2f R=%.7f" % (q, bestR))
    return best, bestR


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


# ---- hop moves ----

def _move_m1(best, rng):
    n = best.size
    w = int(rng.uniform(0.02, 0.15) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    z = rng.standard_normal(w)
    h[win] = h[win] * np.exp(0.05 * z)
    return h, win


def _move_m2(best, rng):
    _, g = _fun_grad(best)
    zeros = np.flatnonzero(best <= 0)
    if zeros.size == 0:
        return None, None
    gz = g[zeros]
    order = np.argsort(gz)[::-1]
    k = int(rng.choice([16, 64, 256]))
    k = min(k, zeros.size)
    pick = zeros[order[:k]]
    h = best.copy()
    amp = 1e-3 * best.mean()
    h[pick] = h[pick] + amp
    return h, pick


def _move_m3(best, rng):
    n = best.size
    P = int(rng.choice([1000, 3000]))
    P = min(P, 200000)
    amp = 1e-3 * best.mean()
    pad = np.full(P, amp)
    if rng.random() < 0.5:
        h = np.concatenate((pad, best))
        touched = np.arange(0, P)
    else:
        h = np.concatenate((best, pad))
        touched = np.arange(n, n + P)
    h = _rescale(h)
    return h, touched


def _move_m4(best, rng):
    n = best.size
    w = max(1, int(0.10 * n))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    amp = 0.02 * best.mean()
    t = np.linspace(0, np.pi, w)
    h[win] = h[win] + amp * np.sin(t)
    return h, win


def _halo(touched, n, halo=64):
    if touched is None or touched.size == 0:
        return np.arange(n)
    lo = max(0, int(touched.min()) - halo)
    hi = min(n - 1, int(touched.max()) + halo)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94
    rng = np.random.default_rng(20250101)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: CVaR broadening + soft-tie polish (the new experiment).
    if time.process_time() < deadline - 1.5:
        best, bestR = _cvar_pass(best, bestR, deadline - 1.5)
        print("after cvar R=%.7f" % bestR)

    # Phase 2: tie-gradient full polish (broad-top aware).
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all_pos(best, 500, deadline - 1.5, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        print("after tie R=%.7f" % bestR)

    # Phase 3: full run_cycle.
    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # Phase 4: hop loop, alternating tie and beta polish.
    hop = 0
    acc = 0
    moves = [_move_m1, _move_m2, _move_m3, _move_m4]
    while time.process_time() < deadline - 1.6:
        hop += 1
        mv = moves[int(rng.integers(0, 4))]
        try:
            h_try, touched = mv(best, rng)
        except Exception:
            h_try, touched = None, None
        if h_try is None:
            continue
        h_try = np.clip(h_try, 0, None)
        if h_try.sum() <= 0:
            continue
        n = h_try.size
        free = _halo(touched, n, 64)
        ht = _lbfgs_block(h_try, free, 150, deadline - 1.0, beta=1e7)
        if time.process_time() < deadline - 1.0:
            pw = _peak_window(ht, pad_frac=0.20, extra=128)
            ht = _lbfgs_block(ht, pw, 100, deadline - 1.0, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            acc += 1
        if hop % 5 == 0:
            print("hop %d acc %d bestR=%.7f" % (hop, acc, bestR))

    print("hops done: %d accepted %d bestR=%.7f" % (hop, acc, bestR))

    # Phase 5: final polish.
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, tie_tol=1e-7):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - tie_tol))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, tie_tol=1e-7):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_tie(hh, tie_tol)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, tie_tol=1e-7):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh, tie_tol)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.9995):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _up_resample(h, N_big):
    n = h.size
    if n == N_big:
        return h.copy()
    x = np.linspace(0.0, 1.0, n)
    xb = np.linspace(0.0, 1.0, N_big)
    hb = np.interp(xb, x, h)
    return np.clip(hb, 0.0, None)


def _smooth_up(h, N_big):
    """Mass-preserving smooth prolongation (spline on cumulative mass)."""
    n = h.size
    if n == N_big:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hb = np.clip(np.diff(Sb), 0.0, None)
    if hb.sum() <= 0:
        return np.ones(N_big)
    return hb


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: the binding constraint is the single max knot of L=f*f.
    # The plateau goal needs the peak NOT to be a single spike.  Strategy:
    #  (1) soften tie tolerance so several near-max knots share the barrier
    #      -> this pushes toward a flat top (raises ||L||_2 at fixed ||L||_inf).
    #  (2) run a short homotopy  tol: 1e-9 -> 1e-4 -> 1e-3 -> 1e-2 -> 0.
    #  (3) alternate full-log and peak-window polish at the true objective.
    cur = best.copy()
    dev = None
    devR = bestR

    for tol in (1e-6, 1e-4, 1e-3, 1e-2):
        if time.process_time() >= deadline - 6.0:
            break
        trial = _lbfgs_log(cur, 200, deadline, tie_tol=tol)
        trial = _lbfgs_log(trial, 200, deadline, tie_tol=0.0)
        r = R_of(trial)
        print("homotopy tol=%.0e R=%.7f" % (tol, r))
        if r > devR + 1e-12:
            dev, devR = trial, r
        if r > R_of(cur) + 1e-12:
            cur = trial

    if dev is not None and devR > bestR + 1e-12:
        best, bestR = dev, devR

    # Try a modest N increase then full polish.
    if time.process_time() < deadline - 18.0 and best.size < 200000:
        for mult in (1.15, 1.3):
            if time.process_time() >= deadline - 14.0:
                break
            Nt = int(min(300000, best.size * mult))
            up = _smooth_up(best, Nt)
            up = _lbfgs_log(up, 250, deadline)
            r = R_of(up)
            print("up N=%d R=%.7f" % (Nt, r))
            if r > bestR + 1e-12:
                best, bestR = up, r
            else:
                break

    # Final alternating polish toward the true objective.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline, tie_tol=0.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.5, 64, maxiter=400)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if dev is not None and devR > start_bestR + 1e-12:
        return {"best": dev, "alternative": start_best}
    return {"best": start_best, "alternative": dev if dev is not None else start_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    z = beta * (Lf - mx)
    e = np.exp(z)
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample(h, factor):
    if factor <= 1:
        return h.copy()
    return np.repeat(h, factor)


# ---- new: multi-peak support growth via coordinate-style block descent ----
def _grow_support(h, deadline, Rcur):
    """Try adding small bumps adjacent to the current support boundary
    (the two ends of the nonzero region), polishing locally. This lets
    R climb by extending the shape, not just re-shaping existing mass."""
    n = h.size
    pos = np.flatnonzero(h > 1e-9 * h.max())
    if pos.size == 0:
        return h, Rcur
    lo, hi = pos[0], pos[-1]
    # widening window at each side, try growing outward
    for width in (1, 2, 4, 8, 16):
        if time.process_time() > deadline - 1.0:
            break
        for side in ('L', 'R'):
            if time.process_time() > deadline - 1.0:
                break
            h2 = h.copy()
            if side == 'L':
                a = max(0, lo - width)
                b = lo
                if b <= a:
                    continue
                h2[a:b] = h2[lo] * 0.5 if h2[lo] > 0 else 0.01
                free = np.arange(a, min(n, lo + width))
            else:
                a = hi + 1
                b = min(n, hi + 1 + width)
                if b <= a:
                    continue
                h2[a:b] = h2[hi] * 0.5 if h2[hi] > 0 else 0.01
                free = np.arange(max(0, hi - width + 1), b)
            h2 = _rescale(h2)
            hp = _lbfgs_block(h2, free, 60, min(deadline - 0.5,
                                                time.process_time() + 1.5))
            rp = R_of(hp)
            if rp > Rcur + 1e-10:
                h, Rcur = hp, rp
                pos = np.flatnonzero(h > 1e-9 * h.max())
                if pos.size == 0:
                    return h, Rcur
                lo, hi = pos[0], pos[-1]
                break
    return h, Rcur


# ---- new: local sharpening of the peak band with a tie-aware objective ----
def _fun_grad_tie(h, band):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    # weight the band of near-max knots to encourage flat-top widening
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-6))
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _lbfgs_block_tie(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh, None)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    bestH = best.copy()
    bestRH = bestR

    # (0) NEW: try growing the support outward at both ends first (cheap,
    #     and can unlock shape improvements that polishing alone cannot).
    if time.process_time() < deadline - 30.0:
        sub_dl = min(deadline - 25.0, time.process_time() + 6.0)
        hp, rp = _grow_support(bestH, sub_dl, bestRH)
        if rp > bestRH + 1e-10:
            bestH, bestRH = hp, rp
            print("  grow R=%.7f N=%d" % (bestRH, bestH.size))

    # (1) Upsample-refinement
    if time.process_time() < deadline - 20.0:
        if bestH.size * 2 <= 1000000:
            h2 = _upsample(bestH, 2)
            if time.process_time() < deadline - 18.0:
                hp = _lbfgs_log(h2, 400, deadline - 15.0)
                rp = R_of(hp)
                if rp > bestRH + 1e-13:
                    bestH, bestRH = hp.copy(), rp
                    print("  refine core R=%.7f" % bestRH)

    # (2) Peak-region beta polish (smoothing the max)
    if time.process_time() < deadline - 12.0:
        win = _peak_window(bestH, frac=0.15)
        for beta in (30.0, 120.0, 500.0):
            if time.process_time() > deadline - 10.0:
                break
            sub_dl = min(deadline - 8.0, time.process_time() + 3.5)
            hp = _lbfgs_block(bestH, win, 150, sub_dl, beta=beta)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  beta=%.0f peak R=%.7f" % (beta, bestRH))

    # (2b) NEW: tie-aware sharp polish of the peak band (flat-top widening)
    if time.process_time() < deadline - 6.0:
        win = _peak_window(bestH, frac=0.20)
        sub_dl = min(deadline - 4.0, time.process_time() + 3.0)
        hp = _lbfgs_block_tie(bestH, win, 120, sub_dl)
        rp = R_of(hp)
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("  tie peak R=%.7f" % bestRH)

    # (3) Full beta polish
    if time.process_time() < deadline - 4.0:
        for beta in (80.0, 320.0):
            if time.process_time() > deadline - 3.5:
                break
            sub_dl = min(deadline - 2.5, time.process_time() + 2.0)
            hp = _lbfgs_log(bestH, 200, sub_dl, beta=beta)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  beta=%.0f full R=%.7f" % (beta, bestRH))

    # (4) Final sharp polish
    if time.process_time() < deadline - 0.5:
        h = _lbfgs_log(bestH, 500, deadline - 0.3)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d zeros %.1f%%) argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad_tie

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _block_average(h, k, offset):
    n = h.size
    start = offset
    if start >= n:
        return None
    m = (n - start) // k
    if m < 4:
        return None
    idx = start + np.arange(m)[:, None] * k + np.arange(k)[None, :]
    return h[idx].mean(axis=1)


def _prolongate_block(hc, k, offset, n_full):
    m = hc.size
    out = np.empty(n_full)
    start = offset
    end = start + m * k
    end = min(end, n_full)
    seg = np.repeat(hc, k)[:end - start]
    out[start:end] = seg
    if start > 0:
        out[:start] = hc[0]
    if end < n_full:
        out[end:] = hc[-1]
    return _rescale(out)


def _argmax_pos(h):
    Lf = _knots(h)
    return int(np.argmax(Lf)) / max(1, Lf.size - 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None and np.asarray(start).size > 0 and np.sum(start) > 0:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        best = base.copy()
        bestR = R_of(best)
    else:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    def try_new(name, cand):
        nonlocal best, bestR
        if cand is None:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f N=%d argmax=%.4f" %
                  (name, bestR, best.size, _argmax_pos(best)))
            return True
        return False

    loop_end = deadline - 0.5
    n_full = best.size

    # Main focus: aggressive full-resolution polish with escalating windows,
    # interleaved with multi-scale coarse passes.
    cycle = 0
    while time.process_time() < loop_end - 1.0:
        cycle += 1
        improved = False

        # (1) Full-resolution log-parametrised L-BFGS
        if time.process_time() < loop_end - 2.0:
            cap = min(loop_end, time.process_time() + 6.0)
            hf = _lbfgs_log(best, 400, cap)
            if try_new("full c=%d" % cycle, hf):
                improved = True

        # (2) Peak windows of increasing size (refine the peak region)
        for frac in (0.015, 0.03, 0.06, 0.12):
            if time.process_time() >= loop_end - 1.5:
                break
            free = _peak_window(best, frac=frac)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(best, free, 200, cap)
            if try_new("peak%.3f c=%d" % (frac, cycle), hp):
                improved = True

        # (3) Multi-scale coarse cycles (k = 2,3,4)
        if time.process_time() < loop_end - 5.0:
            for k in (2, 3, 4):
                if time.process_time() >= loop_end - 4.0:
                    break
                for offset in range(k):
                    if time.process_time() >= loop_end - 4.0:
                        break
                    hk = _block_average(best, k, offset)
                    if hk is None:
                        continue
                    if R_of(hk) < bestR - 1e-3:
                        continue
                    cap = min(loop_end, time.process_time() + 3.0)
                    hc = _lbfgs_log(hk, 200, cap)
                    hp = _prolongate_block(hc, k, offset, n_full)
                    cap = min(loop_end, time.process_time() + 2.5)
                    hp = _lbfgs_log(hp, 200, cap)
                    if try_new("k=%d o=%d c=%d" % (k, offset, cycle), hp):
                        improved = True

        if not improved and time.process_time() > loop_end - 4.0:
            break

    # Final safety: quick full polish
    if time.process_time() < loop_end:
        cap = min(loop_end, time.process_time() + 3.0)
        hf = _lbfgs_log(best, 300, cap)
        try_new("final", hf)

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1200:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1200:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _prolongate(h, N):
    n = h.size
    if n == N:
        return h.copy()
    edges_old = np.linspace(0, 1, n + 1)
    edges_new = np.linspace(0, 1, N + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    def F(x):
        idx = np.clip(np.searchsorted(edges_old, x, side='right') - 1, 0, n - 1)
        frac = (x - edges_old[idx]) / (edges_old[idx + 1] - edges_old[idx])
        return cum[idx] + frac * h[idx]
    out = (F(edges_new[1:]) - F(edges_new[:-1])) / (edges_new[1:] - edges_new[:-1])
    return out


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 6)
    hi = min(n, int(c) + pad + n // 6)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 120, 'maxfun': 240,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0):
            best_h = s.copy()
            best_R = R_of(best_h)

    if best_h is None:
        # bootstrap from p2534-style seed
        N = 512
        i = np.arange(N, dtype=float) + 0.5
        h = 0.5 + 3.0 * np.power(i, -0.5) + 3.0 * np.power((N - i), -0.5)
        best_h = h
        best_R = R_of(h)

    # Work at start's resolution or higher
    N0 = max(best_h.size, 512)

    # Stage 1: full L-BFGS at current resolution
    h = _full_lbfgs(best_h, deadline, maxiter=300)
    r = R_of(h)
    if r > best_R:
        best_h, best_R = h, r

    # Stage 2: ladder refinement
    for N in (1024, 2048, 4096, 8192):
        if time.process_time() > deadline - 2.0:
            break
        if N <= best_h.size:
            h = best_h.copy()
        else:
            h = _prolongate(best_h, N)
        r = R_of(h)
        if r > best_R:
            best_h, best_R = h, r
        h = _full_lbfgs(h, deadline, maxiter=200)
        r = R_of(h)
        if r > best_R:
            best_h, best_R = h, r
        # peak-window extra polish
        h2 = _peak_window_polish(best_h, deadline)
        r2 = R_of(h2)
        if r2 > best_R:
            best_h, best_R = h2, r2

    # Final peak window polish at highest resolution
    if time.process_time() < deadline - 1.0:
        h2 = _peak_window_polish(best_h, deadline)
        r2 = R_of(h2)
        if r2 > best_R:
            best_h, best_R = h2, r2

    if best_h is None:
        return np.ones(50)
    if not np.all(np.isfinite(best_h)) or not np.any(best_h > 0):
        return np.ones(50)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0):
            if R_of(s) >= best_R:
                return s

    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


# ---------------- slot-1 barrier objective ----------------
def _fun_grad_bar(h, mu=1e-3, slack=3e-3, band=0.90):
    """Barrier objective: -log(num) + 2 log(s) + log(mx) with smooth
    soft-max over knots above band*mx, plus a log-barrier keeping the
    knots below (1+slack)*mx. Normalisation is inside f."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    # soft max over knots near the peak
    thr = band * mx
    mask = Lf >= thr
    # smooth soft-max via logsumexp on masked knots
    z = (Lf[mask] - mx) / (mu * mx)
    z = np.clip(z, -60.0, 0.0)
    e = np.exp(z)
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    sm = mx * (1.0 + mu * np.log(Z))
    gLf = -dq / num
    # gradient of soft-max
    w = np.zeros_like(Lf)
    w[mask] = e / Z
    gLf += w / sm
    # log barrier: -log((1+slack)*mx - Lf) for knots close to peak
    cap = (1.0 + slack) * mx
    gap = cap - Lf
    gap = np.clip(gap, 1e-12, None)
    bar_mask = Lf >= band * mx
    gLf[bar_mask] -= 1.0 / gap[bar_mask]
    # derivative of cap wrt mx
    dcap = (1.0 + slack)
    gLf[bar_mask] += dcap / gap[bar_mask]
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    val -= np.sum(np.log(gap[bar_mask]))
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_bar(h0, maxiter, deadline, mu=1e-3, slack=3e-3, band=0.90):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_bar(hh, mu=mu, slack=slack, band=band)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _within_frac(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _resample_mass(h, Np):
    """Mass-preserving resample of step function h (length N) to length Np.
    Exact for block-constant arrays (cumsum interpolation)."""
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    t = np.linspace(0.0, N, Np + 1)
    cp = np.interp(t, np.arange(N + 1, dtype=float), c)
    hp = (Np / N) * np.diff(cp)
    return np.clip(hp, 0.0, None)


def _block_sum(h, Np):
    """Exact block-sum down-sampling when N is a multiple of Np."""
    N = h.size
    if N % Np == 0:
        f = N // Np
        return h.reshape(Np, f).sum(axis=1)
    return _resample_mass(h, Np)


def _block_lift(h, Np):
    """Exact block-lift up-sampling when Np is a multiple of N."""
    N = h.size
    if Np % N == 0:
        f = Np // N
        return np.repeat(h, f) / f
    return _resample_mass(h, Np)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N_base = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- exact block-sum ladder down from N_base ----
    ladder = [best.copy()]
    cur = best.copy()
    N_cur = cur.size
    while N_cur > 3281:
        N_next = max(3281, N_cur // 2)
        if N_next == N_cur:
            break
        cur = _block_sum(cur, N_next)
        cur = _rescale(cur)
        N_cur = N_next
        ladder.append(cur.copy())
        if len(ladder) > 8:
            break

    print("ladder sizes:", [a.size for a in ladder])

    # ---- optimise each rung with barrier + full L-BFGS ----
    rung_best = None
    rung_bestR = -1.0
    rung_bestN = None
    sweep_end = t0 + budget_seconds * 0.55
    for lvl, h in enumerate(ladder):
        if time.process_time() >= sweep_end - 2.0:
            break
        N = h.size
        r0 = R_of(h)
        slice_end = min(sweep_end, time.process_time() + 8.0)
        # barrier stage
        hb = _lbfgs_bar(h, 400, slice_end - 3.0, mu=1e-3, slack=3e-3,
                        band=0.90)
        rb = R_of(hb)
        if rb > r0:
            h = hb
        # full L-BFGS
        if time.process_time() < slice_end - 1.5:
            ht = _lbfgs_all_pos(h, 300, slice_end - 0.5, tie=True)
            rt = R_of(ht)
            if rt > R_of(h):
                h = ht
        r = R_of(h)
        print("rung %d N=%d r0=%.9f -> r=%.9f (dR=%+.3e) within0.1%%=%.4f"
              % (lvl, N, r0, r, r - r0, _within_frac(h)))
        if r > rung_bestR:
            rung_best, rung_bestR, rung_bestN = h.copy(), r, N

    # ---- lift best rung back up to N_base and polish ----
    if rung_best is not None:
        h_lift = _block_lift(rung_best, N_base)
        h_lift = _rescale(h_lift)
        r_lift = R_of(h_lift)
        print("lift N=%d -> %d: R=%.9f (rung %.9f)"
              % (rung_bestN, N_base, r_lift, rung_bestR))
    else:
        h_lift = best.copy()
        r_lift = bestR

    # full-resolution polish: barrier stages then full L-BFGS
    fd = t0 + budget_seconds * 0.92
    h_work = h_lift
    if time.process_time() < fd - 6.0:
        for mu in (1e-3, 1e-4, 3e-5):
            if time.process_time() >= fd - 4.0:
                break
            ht = _lbfgs_bar(h_work, 300, min(fd - 3.0,
                                             time.process_time() + 3.0),
                            mu=mu, slack=3e-3, band=0.90)
            rt = R_of(ht)
            if rt > R_of(h_work):
                h_work = ht
            print("full barrier mu=%.0e R=%.9f" % (mu, R_of(h_work)))

    if time.process_time() < fd - 3.0:
        ht = _lbfgs_all_pos(h_work, 400, fd - 2.0, tie=True)
        rt = R_of(ht)
        if rt > R_of(h_work):
            h_work = ht
        print("full tie R=%.9f" % R_of(h_work))

    if time.process_time() < fd - 1.5:
        ht = _peak_ladder(h_work, fd - 0.5, pads=(0.08, 0.05, 0.03),
                          iters=200, tie=True)
        if R_of(ht) > R_of(h_work):
            h_work = ht
        print("peak polish R=%.9f" % R_of(h_work))

    if time.process_time() < fd - 0.5:
        ht = _lbfgs_all_pos(h_work, 200, fd - 0.2, tie=False)
        if R_of(ht) > R_of(h_work):
            h_work = ht
        print("full argmax R=%.9f" % R_of(h_work))

    finalR = R_of(h_work)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (finalR, startR, h_work.size, _zero_frac(h_work),
             _nearmax_frac(h_work), _tie_count(h_work)))

    result = {}
    if finalR > startR + 1e-15:
        result["best"] = h_work
        if rung_best is not None and rung_best.size != h_work.size:
            result["alternative"] = rung_best
    else:
        result["best"] = best
        if rung_best is not None and rung_best.size != best.size:
            result["alternative"] = rung_best
        elif finalR > startR - 1e-9:
            result["alternative"] = h_work
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _coarsen(h, f):
    n = h.size
    m = n // f
    if m <= 0:
        return None
    hh = h[:m * f].reshape(m, f)
    return hh.mean(axis=1)


def _refine_up(g, n_target):
    m = g.size
    C = np.concatenate(([0.0], np.cumsum(g)))
    u_new = np.linspace(0.0, 1.0, m + 1)
    u_old = np.linspace(0.0, 1.0, n_target + 1)
    h_up = np.diff(np.interp(u_old, u_new, C)) * (n_target / m)
    return _rescale(np.clip(h_up, 0, None))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f" % bestR)

    # Coarse-level ladder with round-trips (as in p1020)
    N = best.size
    levels = [f for f in (4, 8) if N // f >= 8000]
    for li, f in enumerate(levels):
        now = time.process_time()
        if now >= deadline - 6.0:
            break
        remaining = deadline - 6.0 - now
        n_left = len(levels) - li
        level_deadline = now + remaining / n_left

        g = _coarsen(best, f)
        if g is None or g.sum() <= 0:
            continue
        g = _rescale(g)
        gR = R_of(g)
        cur, curR = g, gR
        while time.process_time() < level_deadline - 0.5:
            prev = curR
            cur, curR = run_cycle(cur, curR, level_deadline - 0.5)
            if curR - prev < 1e-9:
                break
        h_up = _refine_up(cur, N)
        r_up = R_of(h_up)
        now2 = time.process_time()
        if now2 < level_deadline - 0.5:
            h_up, r_up = run_cycle(h_up, r_up, level_deadline - 0.5)
        if r_up > bestR + 1e-13:
            best, bestR = h_up.copy(), r_up
            print("accepted f=%d R=%.7f" % (f, bestR))

    # Final peak-ladder rungs + all-pos
    for frac, extra, beta in [(0.10, 128, 1e8), (0.25, 256, 1e8)]:
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 1.0,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 1.0, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_full(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        h = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
    return h


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    return np.clip(np.diff(C2), 0, None)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.20, 0.15, 0.10]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 300, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: fine peak polish on start ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("initial peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 2: upsampled (2x) quotient search, then fold back ----
    # Idea: optimize a finer-grid version of the current best, then fold
    # mass-preservingly back to the original N. This explores a different
    # neighborhood than the half-resolution search used by p1949.
    if time.process_time() < deadline - 3.0:
        N = best.size
        N2 = min(2 * N, 1000000)
        up = _lift_mass_preserving(best, N2)
        upR = R_of(up)
        print("upsampled R(u)=%.9f (N2=%d, full %.9f)" % (upR, N2, bestR))
        up_deadline = t0 + budget_seconds * 0.55
        work_u = _rescale(up)
        best_u = work_u.copy()
        best_uR = R_of(best_u)
        rounds = 0
        rng = np.random.default_rng(12345)
        while time.process_time() < up_deadline - 1.0:
            amp = [0.0008, 0.0015, 0.0025, 0.004][rounds % 4]
            cu = best_u.copy()
            nz = cu > 0
            if nz.sum() > 0:
                cu[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cu = _rescale(cu)
            r0 = R_of(cu)
            work_u, cand_u, cand_uR, org = _half_cycle(
                cu, r0, up_deadline, tag='u%d' % rounds)
            if cand_uR > best_uR + 1e-12:
                best_u = cand_u.copy()
                best_uR = cand_uR
                print("  up ACCEPT R(u)=%.9f (round %d)" % (best_uR, rounds))
            rounds += 1
        print("upsampled rounds=%d R(u)=%.9f" % (rounds, best_uR))
        # fold back to N by mass-preserving block sums
        bnd = np.arange(N + 1, dtype=float) * (N2 / N)
        C2 = np.concatenate(([0.0], np.cumsum(best_u)))
        C = np.interp(bnd, np.arange(N2 + 1, dtype=float), C2)
        h_fold = np.clip(np.diff(C), 0, None)
        h_fold = _rescale(h_fold)
        ht = _polish_full(h_fold, deadline)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'upsample-fold'
            print("upsample-fold NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: fine peak polish on best ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 4: trailing polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

