        for pad in [0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("initial peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 2: upsampled (2x) quotient search, then fold back ----
    # Idea: optimize a finer-grid version of the current best, then fold
    # mass-preservingly back to the original N. This explores a different
    # neighborhood than the half-resolution search used by p1949.
    if time.process_time() < deadline - 3.0:
        N = best.size
        N2 = min(2 * N, 1000000)
        up = _lift_mass_preserving(best, N2)
        upR = R_of(up)
        print("upsampled R(u)=%.9f (N2=%d, full %.9f)" % (upR, N2, bestR))
        up_deadline = t0 + budget_seconds * 0.55
        work_u = _rescale(up)
        best_u = work_u.copy()
        best_uR = R_of(best_u)
        rounds = 0
        rng = np.random.default_rng(12345)
        while time.process_time() < up_deadline - 1.0:
            amp = [0.0008, 0.0015, 0.0025, 0.004][rounds % 4]
            cu = best_u.copy()
            nz = cu > 0
            if nz.sum() > 0:
                cu[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cu = _rescale(cu)
            r0 = R_of(cu)
            work_u, cand_u, cand_uR, org = _half_cycle(
                cu, r0, up_deadline, tag='u%d' % rounds)
            if cand_uR > best_uR + 1e-12:
                best_u = cand_u.copy()
                best_uR = cand_uR
                print("  up ACCEPT R(u)=%.9f (round %d)" % (best_uR, rounds))
            rounds += 1
        print("upsampled rounds=%d R(u)=%.9f" % (rounds, best_uR))
        # fold back to N by mass-preserving block sums
        bnd = np.arange(N + 1, dtype=float) * (N2 / N)
        C2 = np.concatenate(([0.0], np.cumsum(best_u)))
        C = np.interp(bnd, np.arange(N2 + 1, dtype=float), C2)
        h_fold = np.clip(np.diff(C), 0, None)
        h_fold = _rescale(h_fold)
        ht = _polish_full(h_fold, deadline)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'upsample-fold'
            print("upsample-fold NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: fine peak polish on best ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 4: trailing polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return 1e18, np.zeros(h.size)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _block_lbfgs(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.10, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_window_polish(h, deadline, pad_frac=0.10, extra=128, maxiter=200):
    if time.process_time() >= deadline - 0.5:
        return h
    win = _peak_window(h, tol=0.95, pad_frac=pad_frac, extra=extra)
    ht = _block_lbfgs(h, win, maxiter, deadline)
    if R_of(ht) > R_of(h) + 1e-15:
        return ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    # ---- Deadline-driven exact tie-averaged polish loop ----
    loop = 0
    while time.process_time() < deadline - 2.0:
        loop += 1
        # (a) full exact tie-averaged L-BFGS for up to 8 s
        fd = min(deadline - 2.0, time.process_time() + 8.0)
        ht = _full_lbfgs(best, 200, fd)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("loop %d full ACCEPT R=%.9f top1%%=%.9f"
                  % (loop, bestR, _top_frac_mean(best, 0.01)))
            # (b) peak-window block polish (pad=3) for up to 4 s
            if time.process_time() < deadline - 2.0:
                fd2 = min(deadline - 2.0, time.process_time() + 4.0)
                hp = _peak_window_polish(best, fd2, pad_frac=0.10, extra=384,
                                         maxiter=200)
                rp = R_of(hp)
                if rp > bestR + 1e-15:
                    best, bestR = hp.copy(), rp
                    print("loop %d window ACCEPT R=%.9f top1%%=%.9f"
                          % (loop, bestR, _top_frac_mean(best, 0.01)))
        else:
            print("loop %d full no gain R=%.9f" % (loop, r))

    # ---- Final 10 s full tie L-BFGS pass ----
    if time.process_time() < deadline - 0.5:
        fd = deadline - 0.3
        ht = _full_lbfgs(best, 300, fd)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final full ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


# ---------------------------------------------------------------------------
#  NEW core idea: a block-constant (coarse) parameterization with a
#  block-resampling multiscale search.  Represent h as a piecewise-constant
#  function on M blocks (M small, e.g. 256..1024).  Optimize the M block
#  values directly with exact R(np.repeat(c, B)).  Then, in the fine problem,
#  *fix* the coarse structure and only allow a short "shape residual" per
#  block (one scalar per block) to vary -- this keeps the coarse profile
#  that produces the sharp autocorrelation peak while letting fine detail
#  tune the peak.  This is a genuinely different parameterization that
#  regularizes the peak better than full per-step optimization.
# ---------------------------------------------------------------------------

def _to_blocks(h, M, B):
    """Downsample h (length M*B) to block means."""
    c = h.reshape(M, B).mean(axis=1)
    return c


def _from_blocks(c, B):
    return np.repeat(c, B)


def _opt_blocks(c0, B, deadline, maxiter=300, beta=None):
    """Optimize block means c directly, objective = R(np.repeat(c,B))."""
    if time.process_time() >= deadline - 0.5:
        return c0
    M = c0.size
    pos = np.flatnonzero(c0 > 1e-12 * (c0.max() + 1e-30))
    if pos.size == 0:
        return c0
    u0 = np.log(np.clip(c0[pos], 1e-300, None))

    def f(u):
        c = c0.copy()
        c[pos] = np.exp(np.clip(u, -30.0, 30.0))
        hh = np.repeat(c, B)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        # chain: h -> c (block mean); grad_c = sum over block of grad_h
        gc = g.reshape(M, B).sum(axis=1)
        return val, gc[pos] * c[pos]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c = c0.copy()
    c[pos] = np.exp(np.clip(res.x, -30.0, 30.0))
    return np.clip(c, 0, None)


def _opt_residual(h0, B, alpha, deadline, maxiter=250, beta=None):
    """Multiscale polish: h = block_const * (1 + alpha * residual_per_block),
    residual is one scalar per block.  alpha small keeps coarse structure."""
    if time.process_time() >= deadline - 0.5:
        return h0
    n = h0.size
    M = n // B
    if M * B != n:
        return h0
    c0 = h0.reshape(M, B).mean(axis=1)
    base = np.repeat(c0, B)
    # residual r per block, starting at 0
    r0 = np.zeros(M)

    def build(r):
        fac = 1.0 + alpha * np.tanh(r)
        return np.clip(base * np.repeat(fac, B), 0, None)

    def f(r):
        hh = build(r)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        # chain rule: h = base * (1 + alpha tanh(r)); d h / d r = base * alpha * (1-tanh^2)
        fac = 1.0 + alpha * np.tanh(r)
        dfac = alpha * (1.0 - np.tanh(r) ** 2)
        gb = g.reshape(M, B)
        # d/dr_m = sum_b g_b * base_b * dfac_m ; base_b = c0[m]
        gr = np.sum(gb, axis=1) * c0 * dfac
        return val, gr

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, r0, jac=True, method='L-BFGS-B',
                       bounds=[(-3.0, 3.0)] * M,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    hh = build(res.x)
    return _rescale(hh)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r + 1e-12:
            # old best becomes alternative if it's genuinely different
            if alternative is None or best_r > alt_r:
                alternative, alt_r = best.copy(), best_r
            best, best_r = cand.copy(), r
        elif r > alt_r and cand is not best:
            alternative, alt_r = cand.copy(), r

    # ---- Pick a block size B that divides N.  Try a few divisors. ----
    N = base.size

    def _pick_B(N):
        # prefer B in [16, 256] that divides N
        for B in (64, 32, 128, 16, 256, 8, 4, 2):
            if N % B == 0 and N // B >= 32:
                return B
        return 1

    B = _pick_B(N)
    M = N // B if B > 0 else N

    # ---- Idea 1: block-mean optimization from the base (coarse first) ----
    cur = base.copy()
    cur_r = base_r
    if B > 1 and M >= 32:
        c0 = _to_blocks(base, M, B)
        c0 = np.clip(c0, 0, None)
        # ascending-beta homotopy on blocks (smoothed max)
        for beta in (200.0, 100.0, 50.0, 25.0):
            if time.process_time() >= hard_end - 1.0:
                break
            c0 = _opt_blocks(c0, B, hard_end, maxiter=120, beta=beta)
        c0 = _opt_blocks(c0, B, hard_end, maxiter=300, beta=None)
        hb = _from_blocks(c0, B)
        hb = _rescale(hb)
        rb = R_of(hb)
        print("blocks M=%d R=%.6f (base %.6f)" % (M, rb, base_r))
        if rb > cur_r:
            cur, cur_r = hb, rb
        _consider(hb, rb)

    # ---- Idea 2: residual polish on top of block structure ----
    for alpha in (0.5, 0.25, 0.12, 0.06):
        if time.process_time() >= hard_end - 1.0:
            break
        h2 = _opt_residual(cur, B, alpha, hard_end, maxiter=200, beta=None)
        r2 = R_of(h2)
        print("  residual alpha=%.2f R=%.6f" % (alpha, r2))
        if r2 > cur_r:
            cur, cur_r = h2, r2
        _consider(h2, r2)

    # ---- Idea 3: full-resolution polish of the peak window ----
    for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2)):
        if time.process_time() >= hard_end - 0.5:
            break
        h2 = _window_polish_peak(cur, hard_end, frac, extra,
                                 maxiter=400, beta=None)
        r2 = R_of(h2)
        if r2 > cur_r:
            cur, cur_r = h2, r2
            _consider(h2, r2)

    # ---- Idea 4: full log polish (final) ----
    if time.process_time() < hard_end - 0.5:
        h2 = _lbfgs_log(cur, maxiter=500, deadline=hard_end)
        r2 = R_of(h2)
        if r2 > cur_r:
            cur, cur_r = h2, r2
            _consider(h2, r2)
        print("final log R=%.6f" % cur_r)

    # ---- Fallback: smoothed-max polish loop ----
    try:
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=200, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=300, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if R_of(h) > cur_r:
                cur, cur_r = h, R_of(h)
                _consider(h, cur_r)
            if time.process_time() >= hard_end - 1.0:
                break
    except Exception:
        pass

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


# ---------------------------------------------------------------------------
#  NEW core idea: a block-constant (coarse) parameterization with a
#  block-resampling multiscale search.  Represent h as a piecewise-constant
#  function on M blocks (M small, e.g. 256..1024).  Optimize the M block
#  values directly with exact R(np.repeat(c, B)).  Then, in the fine problem,
#  *fix* the coarse structure and only allow a short "shape residual" per
#  block (one scalar per block) to vary -- this keeps the coarse profile
#  that produces the sharp autocorrelation peak while letting fine detail
#  tune the peak.  This is a genuinely different parameterization that
#  regularizes the peak better than full per-step optimization.
# ---------------------------------------------------------------------------

def _to_blocks(h, M, B):
    """Downsample h (length M*B) to block means."""
    c = h.reshape(M, B).mean(axis=1)
    return c


def _from_blocks(c, B):
    return np.repeat(c, B)


def _opt_blocks(c0, B, deadline, maxiter=300, beta=None):
    """Optimize block means c directly, objective = R(np.repeat(c,B))."""
    if time.process_time() >= deadline - 0.5:
        return c0
    M = c0.size
    pos = np.flatnonzero(c0 > 1e-12 * (c0.max() + 1e-30))
    if pos.size == 0:
        return c0
    u0 = np.log(np.clip(c0[pos], 1e-300, None))

    def f(u):
        c = c0.copy()
        c[pos] = np.exp(np.clip(u, -30.0, 30.0))
        hh = np.repeat(c, B)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        # chain: h -> c (block mean); grad_c = sum over block of grad_h
        gc = g.reshape(M, B).sum(axis=1)
        return val, gc[pos] * c[pos]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c = c0.copy()
    c[pos] = np.exp(np.clip(res.x, -30.0, 30.0))
    return np.clip(c, 0, None)


def _opt_residual(h0, B, alpha, deadline, maxiter=250, beta=None):
    """Multiscale polish: h = block_const * (1 + alpha * residual_per_block),
    residual is one scalar per block.  alpha small keeps coarse structure."""
    if time.process_time() >= deadline - 0.5:
        return h0
    n = h0.size
    M = n // B
    if M * B != n:
        return h0
    c0 = h0.reshape(M, B).mean(axis=1)
    base = np.repeat(c0, B)
    # residual r per block, starting at 0
    r0 = np.zeros(M)

    def build(r):
        fac = 1.0 + alpha * np.tanh(r)
        return np.clip(base * np.repeat(fac, B), 0, None)

    def f(r):
        hh = build(r)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        # chain rule: h = base * (1 + alpha tanh(r)); d h / d r = base * alpha * (1-tanh^2)
        fac = 1.0 + alpha * np.tanh(r)
        dfac = alpha * (1.0 - np.tanh(r) ** 2)
        gb = g.reshape(M, B)
        # d/dr_m = sum_b g_b * base_b * dfac_m ; base_b = c0[m]
        gr = np.sum(gb, axis=1) * c0 * dfac
        return val, gr

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, r0, jac=True, method='L-BFGS-B',
                       bounds=[(-3.0, 3.0)] * M,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    hh = build(res.x)
    return _rescale(hh)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
