        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _perturb_window(h, rng):
    """Perturb the right-half window [0.55N, N) with block multiplications."""
    h = h.copy()
    n = h.size
    lo = int(0.55 * n)
    hi = n
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    cuts = np.sort(rng.choice(np.arange(1, W), size=nblocks - 1, replace=False))
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(nblocks):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, 0.25))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _smooth_perturb(h, rng, sigma=0.05):
    """Global smooth multiplicative perturbation (low-frequency)."""
    n = h.size
    k = max(3, n // 40)
    ctrl = rng.normal(0.0, sigma, size=k)
    x = np.linspace(0, k - 1, n)
    fac = np.interp(x, np.arange(k), ctrl)
    fac = np.exp(fac)
    return _rescale(h * fac)


def _refine_full(cur, deadline, iters=2):
    """Full-array smoothing ladder + exact polish. Best generic refinement."""
    h = cur
    for _ in range(iters):
        if time.process_time() >= deadline - 1.0:
            break
        for beta in (120.0, 60.0, 30.0, 15.0):
            if time.process_time() >= deadline - 0.5:
                break
            c = _lbfgs_sm(h, beta, maxiter=250, deadline=deadline)
            if R_of(c) > R_of(h):
                h = c
        if time.process_time() < deadline - 0.5:
            c = _lbfgs_log(h, maxiter=600, deadline=deadline)
            if R_of(c) > R_of(h):
                h = c
        for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
            if time.process_time() >= deadline - 0.5:
                break
            c = _window_polish_peak(h, deadline, frac, extra, maxiter=400)
            if R_of(c) > R_of(h):
                h = c
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand.copy(), r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    hard_end = deadline - 0.5
    rng = np.random.default_rng(98765)

    # ---------------- Phase 1: new idea - global smooth perturbations + full refine ----------
    n_seeds = 8
    for seed in range(n_seeds):
        if time.process_time() >= hard_end - 2.0:
            break
        rs = np.random.default_rng(5000 + seed)
        h = _smooth_perturb(cur, rs, sigma=0.06)
        # quick smoothing ladder
        for beta in (200.0, 80.0, 40.0):
            if time.process_time() >= hard_end - 1.0:
                break
            c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 1.0:
            c = _lbfgs_log(h, maxiter=500, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        # full refine from this seed if time permits
        h = _refine_full(h, min(hard_end, time.process_time() + max(
            3.0, (hard_end - time.process_time()) / max(1, n_seeds - seed))), iters=1)
        r = R_of(h)
        _consider(h, r)

    print("phase1 R=%.6f N=%d" % (best_r, best.size))

    # ---------------- Phase 2: window perturbation experiments from best ----------
    for seed in range(12):
        if time.process_time() >= hard_end - 2.0:
            break
        rng_s = np.random.default_rng(1000 + seed)
        h = _perturb_window(cur, rng_s)
        for beta in (300.0, 800.0, 2000.0):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_sm(h, beta, maxiter=300, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(h, maxiter=800, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        for frac in (0.15, 0.30):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _window_polish_peak(h, hard_end, frac, 8, maxiter=400, beta=None)
            if R_of(c) >= R_of(h):
                h = c
        _consider(h, R_of(h))

    print("phase2 R=%.6f N=%d" % (best_r, best.size))

    # ---------------- Phase 3: base-style polishing loop on cur until time out ----------
    try:
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= hard_end - 1.0:
                break
        print("final R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- quotient/stride machinery: model h as blocks of B equal steps ----------
def _block_sum(h, B):
    n = h.size
    m = n // B
    if m * B != n:
        # pad with zeros to a multiple of B (no effect: zeros are steps of height 0)
        pad = m * B + B - n
        h = np.concatenate([h, np.zeros(pad)])
        m = h.size // B
    return h.reshape(m, B).mean(axis=1), h


def _expand(c, B):
    return np.repeat(c, B)


def _fun_grad_c(c, B):
    """Gradient w.r.t. block means c, where h = repeat(c, B)."""
    h = np.repeat(c, B)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(c.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad_h = _backprop(gLf, h) + 2.0 / s
    # chain rule to block means: sum gradient over each block, times B (d h / d c = 1)
    grad_c = grad_h.reshape(c.size, B).sum(axis=1)
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad_c


def _lbfgs_c(c0, B, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c0
    c0 = np.clip(c0, 0, None)
    if c0.sum() <= 0:
        return c0

    def f(x):
        cc = np.clip(x, 0.0, None)
        return _fun_grad_c(cc, B)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c0.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * c0.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return np.clip(res.x, 0.0, None)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d) frac=%.4f" % (bestR, best.size, _frac_near_max(best, 1e-3)))

    alt_best = None
    altR = -1.0

    def consider(h_new, r_new, tag):
        nonlocal best, bestR, alt_best, altR
        if r_new > altR:
            altR, alt_best = r_new, h_new.copy()
        if r_new > bestR + 1e-15:
            best, bestR = h_new.copy(), r_new
            print("%s R=%.12f frac=%.4f *" % (tag, r_new, _frac_near_max(h_new, 1e-3)))
        else:
            print("%s R=%.12f frac=%.4f" % (tag, r_new, _frac_near_max(h_new, 1e-3)))

    # ---- Phase 1: block-coarsened optimization (quotient space) ----
    # Model h as repeat(c, B) with a modest number of blocks; optimize c exactly.
    # This regularises the problem and lets the optimizer move whole features.
    n0 = best.size
    Bs = []
    for B in (32, 16, 8, 4, 2):
        if n0 // B >= 16:
            Bs.append(B)
    # also try a coarse block size if the start is large
    if n0 // 64 >= 16 and 64 not in Bs:
        Bs = [64] + Bs

    cur = best.copy()
    curR = bestR
    for B in Bs:
        if time.process_time() >= deadline - 8.0:
            break
        c0, hp = _block_sum(cur, B)
        B_eff = hp.size // c0.size  # actual block size after padding
        tlim = min(deadline - 6.0, time.process_time() + 4.0)
        c1 = _lbfgs_c(c0, B_eff, 300, tlim)
        h_new = _rescale(_expand(c1, B_eff))
        r_new = R_of(h_new)
        consider(h_new, r_new, "block B=%d" % B_eff)
        if r_new >= curR - 1e-12:
            cur, curR = h_new, r_new

    # ---- Phase 2: full-resolution softmax homotopy from the block result ----
    if cur.size <= 200000:
        for beta in (100.0, 500.0, 2000.0, 8000.0):
            if time.process_time() >= deadline - 5.0:
                break
            tlim = min(deadline - 4.0, time.process_time() + 3.0)
            h_new = _lbfgs_block(cur, np.arange(cur.size), 200, tlim, beta=beta)
            r_new = R_of(h_new)
            consider(h_new, r_new, "beta=%.0f" % beta)
            if r_new >= curR - 1e-12:
                cur, curR = h_new, r_new

        # final tie-aware polish
        if time.process_time() < deadline - 1.5:
            tlim = min(deadline - 1.0, time.process_time() + 3.0)
            h_new = _lbfgs_block(cur, np.arange(cur.size), 300, tlim, tie=True)
            r_new = R_of(h_new)
            consider(h_new, r_new, "tie")
            if r_new >= curR - 1e-12:
                cur, curR = h_new, r_new

        # peak-window refinement
        for pad in (0.05, 0.02):
            if time.process_time() >= deadline - 0.6:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 300,
                              min(deadline - 0.3, time.process_time() + 1.5), tie=True)
            r = R_of(ht)
            consider(ht, r, "window pad=%.2f" % pad)

    print("frac near max (0.1%%) after: %.4f" % _frac_near_max(best, 1e-3))

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

