    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, free, maxiter, deadline):
    """LBFGS in log-space on the free coordinates (positive, scale-free)."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[active], floor, None))

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = _fun_grad_tie(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth_filter(h, k):
    if k <= 0 or h.size < 2 * k + 1:
        return h
    ker = np.ones(2 * k + 1) / (2 * k + 1)
    hs = np.convolve(h, ker, mode='same')
    return _rescale(np.clip(hs, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_state = [None, -1.0]

    # Phase 1: log-space basin hopping with smoothing perturbations.
    hop_end = t0 + budget_seconds * 0.50
    hop = 0
    while time.process_time() < hop_end - 2.0:
        now = time.process_time()
        slice_dl = min(now + 5.0, hop_end)
        k = [2, 4, 8, 16, 32][hop % 5]
        hp = _smooth_filter(best, k)
        if time.process_time() < slice_dl - 0.6:
            win = _peak_window(hp, pad_frac=0.10, extra=256)
            hp = _lbfgs_log(hp, win, 250, slice_dl - 0.3)
        if time.process_time() < slice_dl - 0.6:
            hp = _lbfgs_log(hp, np.arange(hp.size), 200, slice_dl - 0.3)
        r = R_of(hp)
        if r > bestR + 1e-13:
            best, bestR = hp.copy(), r
            origin = 'hop%d' % hop
            print("hop%d k=%d NEW BEST R=%.9f" % (hop, k, bestR))
        elif r > alt_state[1]:
            alt_state[0], alt_state[1] = hp.copy(), r
        hop += 1
    print("hop rounds=%d R=%.9f" % (hop, bestR))

    # Phase 2: peak-window refinement in log-space, shrinking window.
    for pad in [0.10, 0.06, 0.04, 0.03, 0.02]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_log(best, win, 400, deadline - 0.3)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
        elif r2 > alt_state[1]:
            alt_state[0], alt_state[1] = ht2.copy(), r2

    # Phase 3: full log-space polish.
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_log(best, np.arange(best.size), 300, deadline - 0.4)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        elif r > alt_state[1]:
            alt_state[0], alt_state[1] = ht.copy(), r

    if bestR < start_bestR - 1e-14:
        best, bestR = start_best.copy(), start_bestR

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if (alt_state[0] is not None and alt_state[0].size == best.size
            and alt_state[1] < bestR - 1e-14):
        result["alternative"] = alt_state[0]
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, log=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    if log:
        pos = active[h[active] > 0]
        if pos.size == 0:
            return h0
        hmax = h.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        u0 = np.log(np.clip(h[pos], floor, None))

        def f(u):
            hh = h.copy()
            hh[pos] = np.exp(u)
            val, g = _fun_grad_tie(hh)
            return val, g[pos] * hh[pos]

        cb = _make_cb(deadline - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * pos.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return h0
        if res is None:
            return h0
        h2 = h.copy()
        h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
        return _rescale(h2)
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _trust_newton(c0, deadline, method='trust-ncg', init_radius=1e-3):
    if time.process_time() >= deadline - 0.5:
        return c0
    c0 = np.clip(c0, 1e-30, None)
    v0 = np.sqrt(c0)

    def fg(v):
        c = v * v
        val, g = _fun_grad_tie(c)
        return val, 2.0 * v * g

    def hessp(v, w):
        eps = 1e-6 * (1.0 + np.linalg.norm(v))
        vp = v + eps * w
        vm = v - eps * w
        cp = vp * vp
        cm = vm * vm
        _, gp = _fun_grad_tie(cp)
        _, gm = _fun_grad_tie(cm)
        gvp = 2.0 * vp * gp
        gvm = 2.0 * vm * gm
        return (gvp - gvm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg, v0, jac=True, method=method, hessp=hessp,
                       callback=cb,
                       options={'maxiter': 300,
                                'initial_trust_radius': init_radius,
                                'max_trust_radius': 0.5,
                                'gtol': 1e-14})
    except (TimeoutError, Exception):
        return c0
    if res is None or not np.all(np.isfinite(res.x)):
        return c0
    c = res.x * res.x
    return _rescale(c)


def _resample_cells(c, m):
    n = c.size
    if m == n:
        return c.copy()
    C = np.concatenate(([0.0], np.cumsum(c)))
    total = C[-1]
    if total <= 0:
        return np.full(m, 1.0 / m)
    targets = np.linspace(0.0, total, m + 1)
    pos = np.interp(targets, C, np.arange(n + 1, dtype=float))
    Cpos = np.interp(pos, np.arange(n + 1, dtype=float), C)
    masses = np.diff(Cpos)
    widths = np.clip(np.diff(pos), 1e-12, None)
    h_new = masses / widths
    s = h_new.sum()
    if s > 0:
        h_new *= (c.sum() / s)
    return h_new


def _polish_full(h, deadline, slice_seconds):
    if time.process_time() >= deadline - 0.5:
        return h
    end = min(deadline - 0.3, time.process_time() + slice_seconds)
    h = _rescale(h)
    h = _lbfgs_block(h, np.arange(h.size), 400, end, log=True)
    for pad in (0.06, 0.03, 0.015):
        if time.process_time() >= end - 0.3:
            break
        win = _peak_window(h, pad_frac=pad, extra=96)
        ht = _lbfgs_block(h, win, 300,
                          min(end, time.process_time() + 1.5), log=True)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0
    am = float(np.argmax(Lf)) / (Lf.size - 1)
    near5 = float(np.mean(Lf >= 0.95 * mx))
    return am, near5


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _newton_cells(c0, q, deadline, maxiter=80):
    """Newton-CG on cell vector c (h = repeat(c,q)); higher-order than LBFGS."""
    if time.process_time() >= deadline - 0.5:
        return c0
    c0 = np.clip(c0, 1e-30, None)

    def fg(c):
        h = np.repeat(c, q)
        val, g = _fun_grad_tie(h)
        gc = g.reshape(-1, q).sum(axis=1)
        return val, gc

    def hessp(c, v):
        nv = np.linalg.norm(v)
        if nv == 0:
            return np.zeros_like(v)
        eps = 1e-6 * max(1.0, np.max(np.abs(c))) / nv
        _, gp = fg(c + eps * v)
        _, gm = fg(c - eps * v)
        return (gp - gm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fg, c0, jac=True, method='trust-ncg', hessp=hessp,
                       callback=cb,
                       options={'maxiter': maxiter, 'gtol': 1e-16,
                                'initial_trust_radius': 1e-3,
                                'max_trust_radius': 0.5})
    except (TimeoutError, Exception):
        return c0
    if res is None or not np.all(np.isfinite(res.x)):
        return c0
    return _rescale(np.repeat(np.clip(res.x, 0, None), q)), res.x


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    N0 = best.size
    am0, n50 = _stats(best)
    print("start argmax=%.4f near5=%.4f" % (am0, n50))

    # ---- Newton-CG on cell vector at same q (highest-order polish) ----
    # This is the main new idea: exploit the exact periodicity structure
    # with a second-order method, which L-BFGS cannot replicate.
    if p > 1 and time.process_time() < deadline - 2.0:
        slice_t = (deadline - time.process_time()) * 0.55
        h_n, c_n = _newton_cells(c, p, time.process_time() + slice_t)
        r_n = R_of(h_n)
        print("newton q=%d: R=%.9f (was %.9f)" % (p, r_n, bestR))
        if r_n > bestR + 1e-15:
            best, bestR = h_n, r_n
            c = c_n
            print("NEWTON ACCEPT R=%.9f" % bestR)

    # ---- try alternative q values, small sweep ----
    qs = [p - 1, p + 1, p - 2, p + 2]
    qs = [q for q in qs if q >= 2]
    remaining = deadline - time.process_time()
    per_cand = max(1.0, (remaining * 0.55) / max(1, len(qs)))

    results = []
    for q in qs:
        if time.process_time() >= deadline - 1.5:
            break
        n_q = int(round(N0 / q))
        if n_q < 2:
            continue
        c_q = _resample_cells(c, n_q)
        c_q = np.clip(c_q, 0, None)
        if c_q.sum() <= 0:
            continue
        h_q = _rescale(np.repeat(c_q, q))
        if h_q.size > 1000000:
            continue
        r_before = R_of(h_q)
        h_q = _polish_full(h_q, deadline, per_cand)
        r_after = R_of(h_q)
        print("q=%d n_q=%d: R_before=%.9f R_after=%.9f N=%d"
              % (q, n_q, r_before, r_after, h_q.size))
        results.append((r_after, h_q, q, n_q))

    if results:
        results.sort(key=lambda x: x[0], reverse=True)
        r_best, h_best, q_best, nq_best = results[0]
        print("best q=%d n_q=%d R=%.9f" % (q_best, nq_best, r_best))
        if r_best > bestR + 1e-15:
            best, bestR = h_best.copy(), r_best
            print("QVAR ACCEPT R=%.9f" % bestR)

    # ---- final polish ----
    if time.process_time() < deadline - 1.0:
        h_fin = _polish_full(best, deadline,
                             max(2.0, deadline - time.process_time() - 1.0))
        rf = R_of(h_fin)
        if rf > bestR + 1e-15:
            best, bestR = h_fin, rf
            print("final polish ACCEPT R=%.9f" % bestR)

    am, n5 = _stats(best)
    print("final R=%.9f (start %.9f, N=%d, ties=%d, argmax=%.4f, near5=%.4f)"
          % (bestR, startR, best.size, _tie_count(best), am, n5))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        # always provide the newton-refined cell structure as alternative
        p2, c2 = _detect_repeat(best)
        if p2 > 1:
            result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1200:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1200:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, tie=False, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    if free is None:
        active = None
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0

    if active is None:
        def f(x):
            hh = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g
        x0 = h.copy()
        nb = n
    else:
        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g[active]
        x0 = h[active].copy()
        nb = active.size

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    if active is None:
        return _rescale(np.clip(res.x, 0.0, None))
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _prolongate(h, n_new):
    r0 = R_of(h)
    rep = n_new // len(h)
    if rep >= 1 and rep * len(h) == n_new:
        cand = np.repeat(h, rep)
        cand = _rescale(cand)
        if R_of(cand) >= r0 - 1e-6:
            return cand
    cand = _prolong(h, n_new)
    cand = _rescale(cand)
    return cand


def _peak_window(h, tol=0.9995, pad_frac=0.3, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size, hi + pad)
    return np.arange(lo, hi)


def _cycle(cur, cur_R, best, best_R, deadline, betas, windows,
           it_beta=60, it_win=100, it_sharp=80, tag="", beta_cap=None):
    for beta in betas:
        now = time.process_time()
        if now >= deadline - 0.5:
            break
        if beta_cap is not None and now >= beta_cap:
            break
        cand = _lbfgs(cur, it_beta, deadline, beta=beta)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand; cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy(); best_R = r
        print(f"  {tag} beta={beta:.0e} R={cur_R:.6f} best={best_R:.6f}")
    for win in windows:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(cur, tol=win)
        cand = _lbfgs(cur, it_win, deadline, free=free)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand; cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy(); best_R = r
        print(f"  {tag} win={win} R={cur_R:.6f} best={best_R:.6f}")
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs(cur, it_sharp, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R + 1e-12:
            cur = cand; cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy(); best_R = r
        print(f"  {tag} sharp R={cur_R:.6f} best={best_R:.6f}")
    return cur, cur_R, best, best_R


def _support_reselect(h, deadline, tag=""):
    """One round of support re-selection: prune weak active cells, revive
    promising zero cells, then refine in tie mode + peak-window polish."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    val, g = _fun_grad_tie(h)
    active = h > 0
    zero = ~active
    n_act = int(active.sum())
    if n_act == 0:
        return h
    k = max(8, int(0.005 * n_act))
    # value of active cells: h_i * max(g_i, 0)  (contribution to improvement)
    act_idx = np.flatnonzero(active)
    act_val = h[act_idx] * np.maximum(g[act_idx], 0.0)
    # prune lowest-value active cells
    if act_val.size > k:
        prune_order = np.argsort(act_val)
        prune_idx = act_idx[prune_order[:k]]
    else:
        prune_idx = act_idx
    # zero cells with positive gradient are candidates to revive
    z_idx = np.flatnonzero(zero)
    if z_idx.size > 0:
        gz = g[z_idx]
        pos = gz > 0
        z_idx = z_idx[pos]
        gz = gz[pos]
        if z_idx.size > k:
            # top positive gradient
            order = np.argsort(-gz)
            revive_idx = z_idx[order[:k]]
        else:
            revive_idx = z_idx
    else:
        revive_idx = np.array([], dtype=int)
    if prune_idx.size == 0 and revive_idx.size == 0:
        return h
    new_h = h.copy()
    new_h[prune_idx] = 0.0
    mean_act = h[active].mean()
    if revive_idx.size > 0:
        new_h[revive_idx] = 0.01 * mean_act
    new_h = _rescale(new_h)
    return new_h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None; best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy(); best_R = R_of(best)

    if best is None:
        best = np.ones(1024); best_R = R_of(best)

    cur = best.copy(); cur_R = best_R

    # Prolongate to at least 131072.
    if len(cur) < 131072:
        cand = _prolongate(cur, 131072)
        r = R_of(cand)
        print(f"prolongate 131072: R {cur_R:.6f} -> {r:.6f}")
        cand = _lbfgs(cand, 200, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R - 1e-9:
            cur = cand; cur_R = r
            if r > best_R:
                best = cand.copy(); best_R = r
        print(f"after prolong N={len(cur)} R={cur_R:.6f}")

    # Phase 1: sharpening cycles at 131072 (betas + tie + peak windows).
    betas1 = [1e6, 1e7, 1e8, 1e9]
    wins1 = [0.9999, 0.999, 0.99, 0.95]
    for c in range(2):
        if time.process_time() >= deadline - 25.0:
            break
        prev = cur_R
        cur, cur_R, best, best_R = _cycle(cur, cur_R, best, best_R,
                                          deadline, betas1, wins1,
                                          it_beta=50, it_win=80, it_sharp=60,
                                          tag=f"p1c{c+1}")
        if time.process_time() < deadline - 20.0:
            cand = _lbfgs(cur, 60, deadline, tie=True)
            r = R_of(cand)
            if r > cur_R + 1e-12:
                cur = cand; cur_R = r
                if r > best_R:
                    best = cand.copy(); best_R = r
        print(f"phase1 cycle {c+1}: cur={cur_R:.6f} best={best_R:.6f} gain={cur_R-prev:.2e}")

    # Phase 2: prolongate to 262144 and refine.
    if len(cur) < 262144 and time.process_time() < deadline - 20.0:
        r_before = cur_R
        cand = _prolongate(cur, 262144)
        r_after = R_of(cand)
        print(f"prolongate 262144: R {r_before:.6f} -> {r_after:.6f}")
        cand = _lbfgs(cand, 150, deadline, beta=0.0)
        r = R_of(cand)
        if r > cur_R - 1e-9:
            cur = cand; cur_R = r
            if r > best_R:
                best = cand.copy(); best_R = r
        print(f"after prolong N={len(cur)} R={cur_R:.6f}")

        betas2 = [1e7, 1e8, 1e9, 1e10]
        wins2 = [0.9999, 0.999, 0.99]
        for c in range(2):
            if time.process_time() >= deadline - 6.0:
                break
            prev = cur_R
            cur, cur_R, best, best_R = _cycle(cur, cur_R, best, best_R,
                                              deadline, betas2, wins2,
                                              it_beta=40, it_win=60, it_sharp=50,
                                              tag=f"p2c{c+1}")
            print(f"phase2 cycle {c+1}: cur={cur_R:.6f} best={best_R:.6f} gain={cur_R-prev:.2e}")

    # Phase 3 (experiment): support re-selection rounds.
    for rnd in range(4):
        now = time.process_time()
        if now >= deadline - 6.0:
            break
        prev_best = best.copy(); prev_best_R = best_R
        trial = _support_reselect(best, deadline, tag=f"rs{rnd+1}")
        # refine in tie mode for a few seconds
        trial = _lbfgs(trial, 200, min(deadline, time.process_time() + 10.0), tie=True)
        rt = R_of(trial)
        # one peak-window polish
        if time.process_time() < deadline - 4.0:
            free = _peak_window(trial, tol=0.999)
            trial2 = _lbfgs(trial, 80, min(deadline, time.process_time() + 4.0), free=free)
            r2 = R_of(trial2)
            if r2 > rt:
                trial = trial2; rt = r2
        print(f"reselect round {rnd+1}: trial R={rt:.6f} vs best={best_R:.6f}")
        if rt > best_R + 1e-7:
            best = trial; best_R = rt
            cur = trial.copy(); cur_R = rt
            print(f"  accepted: best={best_R:.6f}")
        else:
            best = prev_best; best_R = prev_best_R
            print(f"  rejected, restored best={best_R:.6f}")

    # Final polish.
    if time.process_time() < deadline - 0.5:
        cand = _lbfgs(best, 500, deadline, beta=0.0)
        r = R_of(cand)
        if r > best_R:
            best = cand; best_R = r
        print(f"final polish R={best_R:.6f}")

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={best_R:.6f} N={len(best)}")

    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            start_R = R_of(s)

    if best_R >= start_R:
        return best
    return {"best": np.asarray(start, dtype=float), "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _quotient(best, s, r):
    N = best.size
    idx = np.arange(r, N, s)
    return best[idx].copy()


def _relift(q, s, r, N, best):
    out = best.copy()
    nq = q.size
    for j in range(nq):
        b = r + s * j
        if b >= N:
            break
        hi = min(N, b + s)
        k = hi - b
        w = np.random.dirichlet(np.ones(k) + 1.0)
        out[b:hi] = q[j] * w * k
    return out


def _quotient_roundtrip(best, s, r, slice_end):
    N = best.size
    q = _quotient(best, s, r)
    if q.size < 8:
        return best
    q2 = _lbfgs_all_pos(q, 300, slice_end - 3.0)
    if R_of(q2) > R_of(q):
        q = q2
    q2 = _lbfgs_all_pos(q, 300, slice_end - 2.0)
    if R_of(q2) > R_of(q):
        q = q2
    if time.process_time() < slice_end - 1.5:
        q2 = _peak_ladder(q, slice_end - 0.8,
                          pads=(0.15, 0.08, 0.04), iters=250)
        if R_of(q2) > R_of(q):
            q = q2
    h = _relift(q, s, r, N, best)
    h = _rescale(h)
    if time.process_time() < slice_end - 0.5:
        h2 = _lbfgs_all_pos(h, 400, slice_end - 0.4)
        if R_of(h2) > R_of(h):
            h = h2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    sweep = [(2, 1), (3, 1), (2, 1), (3, 2), (5, 1)]
    for (s, r) in sweep:
        if time.process_time() >= deadline - 6.0:
            break
        slice_end = min(deadline - 2.0, time.process_time() + 6.0)
        if slice_end <= time.process_time() + 1.0:
            break
        h_t = _quotient_roundtrip(best, s, r, slice_end)
        r_t = R_of(h_t)
        dR = r_t - bestR
        accepted = r_t > bestR + 1e-15
        if accepted:
            best, bestR = h_t.copy(), r_t
        print("quot s=%d r=%d N=%d dR=%+.3e %s R=%.9f zero_frac=%.4f nearmax5=%.4f ties=%d"
              % (s, r, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                 bestR, _zero_frac(h_t), _nearmax_frac(h_t),
                 _tie_count(h_t)))

    it = 0
    while time.process_time() < deadline - 4.0:
        it += 1
        slice_end = min(deadline - 2.0, time.process_time() + 8.0)
        h_t = _lbfgs_all_pos(best, 600, slice_end - 3.0)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("exact pass %d dR=%+.3e R=%.9f" % (it, r_t - bestR, bestR))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.05, 0.03), iters=250)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("peak pass %d dR=%+.3e R=%.9f" % (it, r_t - bestR, bestR))
        if time.process_time() >= slice_end - 1.0:
            break

    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL exact ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL exact no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

