    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    """Tie-averaged objective: log of mean of max knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return 1e18, np.zeros(h.size)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_window_polish(h, deadline, frac=0.2):
    win = _peak_window(h, tol=0.95, pad_frac=frac, extra=128)
    ht = _lbfgs_block(h, win, 200, deadline)
    if R_of(ht) > R_of(h) + 1e-15:
        return ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _nearmax_fracs(h, fracs=(0.001, 0.01, 0.05)):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return [0.0] * len(fracs)
    return [float(np.mean(Lf >= f * mx)) for f in fracs]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best)))

    k_fracs = [0.0005, 0.002, 0.008]
    cyc = 0
    while time.process_time() < deadline - 2.5:
        k_frac = k_fracs[cyc % len(k_fracs)]
        cyc += 1

        # (1) gradient at current point
        val, g = _fun_grad(best)
        active_mask = best > 0
        active_idx = np.flatnonzero(active_mask)
        zero_idx = np.flatnonzero(~active_mask)
        n_active = active_idx.size
        if n_active == 0 or zero_idx.size == 0:
            break

        k = max(4, int(k_frac * n_active))
        k = min(k, n_active, zero_idx.size)

        # rank active cells by h_i * max(g_i, 0): weakest to prune
        score_active = best[active_idx] * np.maximum(g[active_idx], 0.0)
        prune_order = np.argsort(score_active)
        prune_idx = active_idx[prune_order[:k]]

        # zero cells with most negative g_i: best to revive
        g_zero = g[zero_idx]
        revive_order = np.argsort(g_zero)
        revive_idx = zero_idx[revive_order[:k]]

        cand = best.copy()
        cand[prune_idx] = 0.0
        fill = 1e-3 * float(np.mean(best[active_idx]))
        cand[revive_idx] = fill
        cand = _rescale(cand)

        # (2) full L-BFGS then peak-window polish
        fd1 = min(deadline - 1.0, time.process_time() + 6.0)
        ht = _full_lbfgs(cand, 150, fd1)
        if time.process_time() < deadline - 1.0:
            fd2 = min(deadline - 0.5, time.process_time() + 3.0)
            ht = _peak_window_polish(ht, fd2, frac=0.2)

        r = R_of(ht)
        if r > bestR + 1e-9:
            best, bestR = ht.copy(), r
            print("ACCEPT k_frac=%.4f k=%d R=%.9f active=%d zero_frac=%.4f"
                  % (k_frac, k, bestR, int(np.sum(best > 0)), _zero_frac(best)))
        else:
            print("reject k_frac=%.4f k=%d R=%.9f (best %.9f)"
                  % (k_frac, k, r, bestR))

        # keep a full tie polish on best between rounds
        if time.process_time() < deadline - 2.5:
            fd = min(deadline - 1.0, time.process_time() + 4.0)
            hp = _full_lbfgs(best, 150, fd)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
                print("polish ACCEPT R=%.9f" % bestR)

    # final polish
    if time.process_time() < deadline - 1.0:
        fd = deadline - 0.5
        hp = _full_lbfgs(best, 200, fd)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
        if time.process_time() < deadline - 0.5:
            hp = _peak_window_polish(best, deadline - 0.3, frac=0.2)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp

    f001, f01, f05 = _nearmax_fracs(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, "
          "nearmax 0.1%%=%.4f 1%%=%.4f 5%%=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best), f001, f01, f05))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    return np.clip(np.diff(C2), 0, None)


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    return np.clip(np.diff(C), 0, None)


# ---------------- transport parameterization ----------------

def _h_to_u(h, m, total):
    N = h.size
    cs = np.concatenate(([0.0], np.cumsum(h)))
    idx = np.linspace(0, N, m)
    S_coarse = np.interp(idx, np.arange(N + 1, dtype=float), cs)
    S_coarse = np.maximum.accumulate(S_coarse)
    g = np.diff(S_coarse)
    g = np.clip(g, 1e-12 * max(total, 1.0) / m, None)
    u = np.log(np.expm1(np.clip(g, 1e-12, 1e12)))
    return u


def _transport_optimize(h0, m, maxiter, deadline, total):
    if time.process_time() >= deadline - 0.5:
        return h0
    N = h0.size
    m = min(m, N)
    x0 = _h_to_u(h0, m, total)

    def f(uu):
        g = np.logaddexp(0.0, uu)
        S = np.concatenate(([0.0], np.cumsum(g)))
        xc = np.linspace(0.0, N, m + 1)
        xf = np.arange(N + 1, dtype=float)
        Sf = np.interp(xf, xc, S)
        hh = np.clip(np.diff(Sf), 0.0, None)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros_like(uu)
        num, dq, Lf = _num_and_dq(hh)
        mx = Lf.max()
        if mx <= 0:
            return 1e18, np.zeros_like(uu)
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        w = 1.0 / idx.size
        gLf[idx] += w / mx
        dh = _backprop(gLf, hh) + 2.0 / s
        dSf = np.zeros(N + 1)
        dSf[:-1] -= dh
        dSf[1:] += dh
        pos = xf / N * m
        k0 = np.clip(np.floor(pos).astype(int), 0, m - 1)
        frac = pos - k0
        dS = np.zeros(m + 1)
        np.add.at(dS, k0, dSf * (1.0 - frac))
        np.add.at(dS, k0 + 1, dSf * frac)
        dg = np.cumsum(dS[::-1])[::-1][1:]
        sig = 1.0 / (1.0 + np.exp(-np.clip(uu, -60, 60)))
        du = dg * sig
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
        return val, du

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    uu = res.x
    g = np.logaddexp(0.0, uu)
    S = np.concatenate(([0.0], np.cumsum(g)))
    xc = np.linspace(0.0, N, m + 1)
    xf = np.arange(N + 1, dtype=float)
    Sf = np.interp(xf, xc, S)
    return _rescale(np.clip(np.diff(Sf), 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    total = best.sum()
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    altR = -1.0

    def consider(h, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(h)
        print("%s: R=%.12f frac=%.4f" % (tag, r, _frac_near_max(h, 1e-3)))
        if r > altR:
            altR, alt_best = r, h.copy()
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # ---- Stage A: lift to finer grid, transport polish ----
    N2 = min(1000000, N * 4)
    if time.process_time() < deadline - 30.0:
        hf = _lift_mass_preserving(best, N2)
        hf = _transport_optimize(hf, max(256, N2 // 8), 400,
                                 min(deadline - 25.0, time.process_time() + 15.0),
                                 hf.sum())
        consider(hf, "lift+transport N=%d" % N2)
        # full-grid tie polish at fine resolution
        if time.process_time() < deadline - 12.0:
            hp = _lbfgs_block(best if best.size > hf.size else hf,
                              np.arange(max(best.size, hf.size)), 300,
                              min(deadline - 8.0, time.process_time() + 8.0),
                              tie=True)
            consider(hp, "fine tie polish")

    # ---- Stage B: transport sweeps at growing m on current best ----
    for m_div, iters in ((8, 250), (4, 250), (2, 200)):
        if time.process_time() >= deadline - 4.0:
            break
        m = max(128, best.size // m_div)
        t_cap = min(deadline - 3.0, time.process_time() + 6.0)
        h1 = _transport_optimize(best, m, iters, t_cap, best.sum())
        consider(h1, "transport m=%d" % m)

    # ---- Stage C: beta-continuation tie polish ----
    if time.process_time() < deadline - 2.0:
        for beta in (30.0, 100.0, 300.0):
            if time.process_time() >= deadline - 1.5:
                break
            hb = _lbfgs_block(best, np.arange(best.size), 150,
                              min(deadline - 1.0, time.process_time() + 3.0),
                              beta=beta)
            consider(hb, "beta=%.0f" % beta)

    # ---- final tie polish ----
    if time.process_time() < deadline - 0.8:
        hp = _lbfgs_block(best, np.arange(best.size), 200,
                          min(deadline - 0.4, time.process_time() + 2.5),
                          tie=True)
        consider(hp, "final tie polish")

    if start is not None and bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

