import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.99, pad_frac=0.10, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def polish(h, deadline, rounds=3):
    if time.process_time() > deadline - 0.5:
        return h
    h = _lbfgs_all_pos(h, 500, deadline)
    R = R_of(h)
    for beta in (50.0, 200.0, 800.0, 3000.0):
        if time.process_time() > deadline - 0.5:
            break
        hb = _lbfgs_all_pos(h, 200, deadline, beta=beta)
        Rb = R_of(hb)
        if Rb > R:
            R = Rb
            h = hb
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_all_pos(h, 300, deadline)
        if R_of(h2) > R:
            h = h2
    for _ in range(rounds):
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(h)
        h2 = _lbfgs_block(h, win, 300, deadline)
        if R_of(h2) > R_of(h):
            h = h2
    return h


def _beta_ladder(h, betas, iters, deadline):
    for beta in betas:
        if time.process_time() > deadline - 0.5:
            break
        h = _lbfgs_all_pos(h, iters, deadline, beta=beta)
    return h


def _peak_ladder(h, deadline, pads=(0.06, 0.03)):
    for pad in pads:
        if time.process_time() > deadline - 0.5:
            break
        win = _peak_window(h, tol=0.99, pad_frac=pad)
        h2 = _lbfgs_block(h, win, 300, deadline, beta=1e7)
        if R_of(h2) > R_of(h):
            h = h2
        h2 = _lbfgs_block(h, win, 300, deadline, beta=0.0)
        if R_of(h2) > R_of(h):
            h = h2
    return h


def _flank_runs(Lf, lo_frac=0.02, hi_frac=0.98, cap=4096):
    M = Lf.max()
    if M <= 0:
        return []
    mask = (Lf > lo_frac * M) & (Lf < hi_frac * M)
    n = mask.size
    runs = []
    i = 0
    while i < n:
        if mask[i]:
            j = i
            while j < n and mask[j]:
                j += 1
            runs.append((i, j - 1))
            i = j
        else:
            i += 1
    out = []
    for (a, b) in runs:
        if b - a + 1 > cap:
            mid = (a + b) // 2
            a = max(a, mid - cap // 2)
            b = min(b, a + cap - 1)
        out.append((a, b))
    return out


def _phase_R(best, best_R, deadline, max_rounds=8):
    for rnd in range(max_rounds):
        if time.process_time() > deadline - 2.0:
            break
        Lf = _knots(best)
        M = Lf.max()
        if M <= 0:
            break
        runs = _flank_runs(Lf)
        free = set()
        n = best.size
        for (a, b) in runs:
            lo = max(0, a - 32)
            hi = min(n - 1, b + 32)
            free.update(range(lo, hi + 1))
        win = _peak_window(best, tol=0.99, pad_frac=0.10)
        free.update(win.tolist())
        free = np.array(sorted(free), dtype=int)
        R0 = best_R
        cur = best
        curR = best_R
        for beta in (1e8, 1e7, 0.0):
            if time.process_time() > deadline - 2.0:
                break
            hb = _lbfgs_block(cur, free, 300, deadline, beta=beta)
            Rb = R_of(hb)
            if Rb > curR:
                cur = hb
                curR = Rb
        if time.process_time() < deadline - 2.0:
            hb = _peak_ladder(cur, deadline, pads=(0.06, 0.03))
            Rb = R_of(hb)
            if Rb > curR:
                cur = hb
                curR = Rb
        if time.process_time() < deadline - 6.0:
            hb = _lbfgs_all_pos(cur, 300, deadline, beta=0.0)
            Rb = R_of(hb)
            if Rb > curR:
                cur = hb
                curR = Rb
        dR = curR - R0
        print("R round", rnd, "dR =", dR, "R =", curR)
        if curR > best_R:
            best = cur
            best_R = curR
        if dR <= 0 and rnd >= 2:
            if rnd >= 4:
                break
    return best, best_R


def _refine_candidate(h, R0, deadline):
    """Try a strong local refinement on a candidate; return (h, R) best found."""
    cur = h
    curR = R0
    if time.process_time() > deadline - 1.0:
        return cur, curR
    hb = polish(cur, min(deadline, time.process_time() + 10.0), rounds=2)
    Rb = R_of(hb)
    if Rb > curR:
        cur, curR = hb, Rb
    if time.process_time() < deadline - 2.0:
        hb, Rb = _phase_R(cur, curR, deadline, max_rounds=4)
        if Rb > curR:
            cur, curR = hb, Rb
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.0
    hard = t0 + budget_seconds * 0.95

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best_h = s.copy()
            best_R = R_of(best_h)

    if best_h is None:
        Nbase = 4096
        x = np.linspace(0.0, 1.0, Nbase)
        cur = np.exp(-((x - 0.5) ** 2) / 0.02)
        cur /= cur.sum()
        best_h = cur.copy()
        best_R = R_of(cur)

    alt_h = None
    alt_R = -1.0

    # Phase 1: polish start (short).
    cur = best_h.copy()
    cur = polish(cur, min(deadline, t0 + budget_seconds * 0.15))
    R = R_of(cur)
    print("seed polish R =", R, "N =", len(cur))
    if R > best_R:
        best_R = R; best_h = cur.copy()

    # Phase 2: flank polish on start.
    best_h, best_R = _phase_R(best_h, best_R, min(hard, t0 + budget_seconds * 0.55))

    # Phase 3: try a doubled grid from the best so far (genuinely different construction).
    if best_h.size * 2 <= 1000000 and time.process_time() < hard - 6.0:
        h2 = np.repeat(best_h, 2)
        h2 = _beta_ladder(h2, (1e6, 1e7, 1e8, 0.0), 200, min(hard, time.process_time() + 15.0))
        R2 = R_of(h2)
        print("doubled R =", R2, "N =", len(h2))
        if R2 > best_R - 1e-4:
            # refine the doubled version
            h2, R2 = _refine_candidate(h2, R2, hard)
            if R2 > best_R:
                best_h, best_R = h2, R2
                print("doubled improved R =", R2, "N =", len(h2))
            else:
                alt_h, alt_R = h2, R2

    # Phase 4: final polish on best.
    if time.process_time() < hard - 0.5:
        hf = polish(best_h, hard)
        Rf = R_of(hf)
        if Rf > best_R:
            best_R = Rf
            best_h = hf

    print("best R =", best_R, "N =", len(best_h))
    if alt_h is not None and alt_R > 0:
        return {"best": best_h, "alternative": alt_h}
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = max(8, int(np.ceil((1.0 - q) * n)))
    if m >= n:
        m = n - 1
    order = np.argsort(Lf)
    idx = order[-m:]
    M = Lf[idx].mean()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += 1.0 / (m * M)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _opt_log(h0, deadline, fg, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fg(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _opt_log(h0, deadline, _fun_grad_tie, maxiter)


def _cvar_lbfgs(h0, q, deadline, maxiter=150):
    return _opt_log(h0, deadline, lambda hh: _fun_grad_cvar(hh, q), maxiter)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    h = np.diff(C)
    return np.clip(h, 0, None)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _near_max_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(Lf >= mx * 0.999),
            np.mean(Lf >= mx * 0.99),
            np.mean(Lf >= mx * 0.95))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase A: CVaR ladder
    qs = [0.80, 0.90, 0.95, 0.98, 0.99, 0.995]
    for q in qs:
        if time.process_time() >= deadline - 4.0:
            break
        tlim = min(deadline - 3.0, time.process_time() + 3.0)
        h_c = _cvar_lbfgs(best, q, tlim, maxiter=150)
        r_c = R_of(h_c)
        # peak-window polish (exact tie)
        if time.process_time() < deadline - 2.0:
            tlim = min(deadline - 1.5, time.process_time() + 1.0)
            h_p = _peak_window_polish(h_c, tlim, pad=3)
            r_p = R_of(h_p)
            if r_p > r_c:
                h_c, r_c = h_p, r_p
        # full exact tie polish
        if time.process_time() < deadline - 2.0:
            tlim = min(deadline - 1.5, time.process_time() + 1.5)
            h_f = _full_lbfgs(h_c, tlim, maxiter=150)
            r_f = R_of(h_f)
            if r_f > r_c:
                h_c, r_c = h_f, r_f
        f1, f5, f25 = _near_max_fracs(h_c)
        print("q=%.3f exact R=%.9f fracs %.3f/%.3f/%.3f" % (q, r_c, f1, f5, f25))
        if r_c > bestR + 1e-12:
            best = h_c
            bestR = r_c

    # Phase B: alternate exact tie full polish and peak-window polish
    N = best.size
    while time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.5, time.process_time() + 3.0)
        h_f = _full_lbfgs(best, tlim, maxiter=150)
        rf = R_of(h_f)
        if rf > bestR + 1e-15:
            best, bestR = h_f, rf
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 1.2, time.process_time() + 1.0)
        h_p = _peak_window_polish(best, tlim, pad=3)
        rp = R_of(h_p)
        if rp > bestR + 1e-15:
            best, bestR = h_p, rp

    # One lift attempt if enough time remains
    if time.process_time() < deadline - 8.0:
        N2 = int(round(N * 2))
        if 16 <= N2 <= 1000000:
            h_lift = _lift_mass_preserving(best, N2)
            if h_lift.sum() > 0:
                h_lift = _rescale(h_lift)
                tlim = min(deadline - 5.0, time.process_time() + 3.0)
                h_lift = _full_lbfgs(h_lift, tlim, maxiter=150)
                h_fold = _fold_back(h_lift, N)
                if h_fold.sum() > 0:
                    h_fold = _rescale(h_fold)
                    r_fold = R_of(h_fold)
                    if r_fold > bestR + 1e-12:
                        best, bestR = h_fold, r_fold
                        print("lift 2x accepted R=%.9f" % r_fold)
                    else:
                        print("lift 2x rejected R=%.9f (best %.9f)" % (r_fold, bestR))

    # Final polish
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.8, time.process_time() + 6.0)
        h_f = _full_lbfgs(best, tlim, maxiter=200)
        rf = R_of(h_f)
        if rf > bestR + 1e-15:
            best, bestR = h_f, rf

    f1, f5, f25 = _near_max_fracs(best)
    print("final R=%.12f (start %.12f, N=%d) fracs %.3f/%.3f/%.3f"
          % (bestR, startR, best.size, f1, f5, f25))

    if bestR < startR:
        best = start_best
        bestR = startR

    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h
    bestR = R_of(h)
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 200, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.2, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
    return best, bestR


def _downsample(h, m):
    """Area-preserving block averaging to m samples."""
    n = h.size
    if n == m:
        return h.copy()
    if n < m:
        # upsample by linear interp
        x = np.linspace(0, 1, n)
        xi = np.linspace(0, 1, m)
        return np.interp(xi, x, h) * (n / m)
    edges = np.linspace(0, n, m + 1)
    c = np.cumsum(np.concatenate(([0.0], h)))
    out = np.empty(m)
    for i in range(m):
        a = edges[i]; b = edges[i + 1]
        ia = int(np.floor(a)); ib = int(np.floor(b))
        s = 0.0
        if ia == ib:
            s = h[ia] * (b - a)
        else:
            s += h[ia] * (ia + 1 - a)
            if ib > ia + 1:
                s += c[ib] - c[ia + 1]
            if ib < n:
                s += h[ib] * (b - ib)
        out[i] = s / (b - a)
    return out


def _fine_refine(hc, N, deadline, maxiter=200):
    """Expand coarse hc to N via interp, then full L-BFGS + local block polish."""
    m = hc.size
    x = np.linspace(0, 1, m)
    xi = np.linspace(0, 1, N)
    hf = np.interp(xi, x, hc)
    hf = _rescale(hf)
    cap = min(deadline - 0.4, time.process_time() + 5.0)
    hf = _lbfgs_log(hf, maxiter, cap, fg=_fun_grad)
    return hf


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Key new stage: coarse multi-resolution search ---------------------
    # The optimum's fine structure is hard to find at full N. Search at a
    # coarse N (say 2048/4096), where L-BFGS explores the landscape faster,
    # then refine at full N. This often escapes the local basin of `start`.
    Nfull = best.size
    coarse_best = None
    coarse_R = -1.0

    for Nc in (2048, 4096):
        if time.process_time() >= hard - 20.0:
            break
        hc = _downsample(best, Nc)
        hc = _rescale(hc)
        Rc = R_of(hc)
        print("  coarse init N=%d R=%.9f" % (Nc, Rc))
        # aggressive multi-restart full L-BFGS at coarse scale
        for trial in range(3):
            if time.process_time() >= hard - 16.0:
                break
            cap = min(hard - 14.0, time.process_time() + 2.5)
            hc2 = _lbfgs_log(hc, 400, cap, fg=_fun_grad)
            Rc2 = R_of(hc2)
            if Rc2 > Rc + 1e-12:
                hc, Rc = hc2, Rc2
                print("    coarse N=%d trial%d R=%.9f" % (Nc, trial, Rc))
        if Rc > coarse_R:
            coarse_best, coarse_R = hc, Rc

    # refine coarse best to full N scale
    if coarse_best is not None and time.process_time() < hard - 8.0:
        hf = _fine_refine(coarse_best, Nfull, hard)
        Rf = R_of(hf)
        print("  fine refine from coarse R=%.9f" % Rf)
        if Rf > bestR + 1e-13:
            best, bestR = hf, Rf
            print("  coarse->fine improved to R=%.9f" % bestR)

    # ---- alternating polish at full scale ----------------------------------
    sweep = 0
    while time.process_time() < hard - 3.0:
        sweep += 1
        improved = False
        if time.process_time() < hard - 3.0:
            cap = min(hard - 2.0, time.process_time() + 3.0)
            hp = _lbfgs_log(best, 300, cap, fg=_fun_grad)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                best, bestR = hp, rp
                improved = True
                print("  [sweep%d full] R=%.9f" % (sweep, bestR))
        for frac in (0.02, 0.05, 0.10):
            if time.process_time() >= hard - 2.0:
                break
            free = _peak_window(best, frac=frac)
            cap = min(hard - 1.0, time.process_time() + 1.5)
            hb = _lbfgs_block(best, free, 100, cap, fg=_fun_grad)
            rb = R_of(hb)
            if rb > bestR + 1e-14:
                best, bestR = hb, rb
                improved = True
                print("  [sweep%d frac=%.2f] R=%.9f" % (sweep, frac, bestR))
        if not improved and sweep > 2:
            break

    if time.process_time() < hard - 0.5:
        hp, rp = _polish(best, hard)
        if rp > bestR:
            best, bestR = hp, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _full_lbfgs(h, deadline, maxiter=300):
    ht = h
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, maxiter, deadline - 0.3, beta=beta)
    return ht


def _peak_window_polish(h, deadline, pad=3):
    ht = h
    for pf in [0.10, 0.06, 0.04, 0.03]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pf, extra=128)
        ht2 = _lbfgs_block(ht, win, 400, deadline - 0.3, beta=1e7)
        if R_of(ht2) > R_of(ht) + 1e-15:
            ht = ht2
    return ht


def _lift2x(h):
    """Mass-preserving 2x upsample: linear interp of cumulative sum on 2N+1 boundaries."""
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))  # length N+1, C[i]=mass in [0,i)
    # new boundaries at j/(2N) for j=0..2N, sample C at N*(j/(2N)) = j/2
    j = np.arange(2 * N + 1, dtype=float)
    pos = j * 0.5  # in units of original step index
    C2 = np.interp(pos, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2) * 2.0  # each new step is half width -> double density
    return np.clip(h2, 0.0, None)


def _fold2x(h2):
    """Fold 2N back to N by cumulative-sum interpolation at original boundaries."""
    M = h2.size
    N = M // 2
    C2 = np.concatenate(([0.0], np.cumsum(h2)))  # length M+1
    j = np.arange(N + 1, dtype=float)
    pos = j * 2.0  # original boundary i corresponds to 2i in half-grid
    Cf = np.interp(pos, np.arange(M + 1, dtype=float), C2)
    hf = np.diff(Cf) * 0.5
    return np.clip(hf, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _consider(ht, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR, origin = ht.copy(), r, tag
            print("%s NEW BEST R=%.9f" % (tag, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        return r

    # ---- Phase A: full L-BFGS polish of the start ----
    h = best.copy()
    phaseA_deadline = min(deadline - 4.0, time.process_time() + 10.0)
    h = _full_lbfgs(h, phaseA_deadline, maxiter=200)
    h = _rescale(h)
    rA = _consider(h, 'phaseA')
    print("Phase A R=%.9f" % rA)

    # ---- Phase B: lift 2x -> polish -> fold back ----
    folds_accepted = 0
    for it in range(3):
        if time.process_time() >= deadline - 4.0:
            break
        h2 = _lift2x(h)
        h2 = _rescale(h2)
        b_deadline = min(deadline - 3.0, time.process_time() + 8.0)
        h2 = _full_lbfgs(h2, b_deadline, maxiter=150)
        hf = _fold2x(h2)
        hf = _rescale(hf)
        r_old = R_of(h)
        r_new = R_of(hf)
        if r_new > r_old + 1e-12:
            h = hf
            folds_accepted += 1
            print("Phase B iter %d FOLD ACCEPT R=%.9f (was %.9f)" % (it, r_new, r_old))
            _consider(h, 'fold%d' % it)
        else:
            print("Phase B iter %d fold rejected (%.9f vs %.9f)" % (it, r_new, r_old))
            if r_new > alt_bestR:
                alt_best, alt_bestR = hf.copy(), r_new

    # ---- Phase C: full polish + peak window polish ----
    if time.process_time() < deadline - 2.0:
