import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, deadline, maxiter=200):
    """L-BFGS in log-coordinates over positive entries (tie-averaged)."""
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _upsample_mass(h, factor):
    """Mass-preserving linear upsample via cumulative-mass interpolation."""
    if factor <= 1:
        return h.copy()
    n = h.size
    m = n * factor
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(m + 1, dtype=float) * (n / m)
    C2 = np.interp(x, np.arange(n + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    alt = None
    altR = -1.0
    print("base R=%.9f N=%d" % (bestR, best.size))

    N0 = best.size

    # ---- NEW IDEA: mass-preserving upsample then log-coord L-BFGS ----
    # This preserves the shape exactly while doubling resolution, then
    # the log-coordinate optimiser can carve finer structure into the peak.
    cands = []
    for fac in (2, 3):
        if N0 * fac <= 900000:
            cands.append((fac, _rescale(_upsample_mass(best, fac))))

    race_end = t0 + min(budget_seconds * 0.55, 34.0)
    for fac, cand in cands:
        if time.process_time() >= race_end - 1.0:
            break
        slice_end = min(race_end, time.process_time() + 12.0)
        h_t = _lbfgs_log(cand, slice_end - 0.5, maxiter=400)
        r_t = R_of(h_t)
        print("upsample x%d R=%.9f dR=%+.3e" % (fac, r_t, r_t - startR))
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("ACCEPT upsample dR=%+.3e" % (bestR - startR))
        elif r_t > altR:
            alt, altR = h_t.copy(), r_t

    # ---- polish loop: alternate log-coord and linear-coord L-BFGS ----
    loop_end = min(deadline, t0 + budget_seconds * 0.90)
    it = 0
    while time.process_time() < loop_end - 2.5:
        it += 1
        slice_end = min(loop_end, time.process_time() + 7.0)
        h_t = _lbfgs_log(best, slice_end - 2.0, maxiter=300)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("log pass %d ACCEPT R=%.9f" % (it, bestR))
        else:
            print("log pass %d no gain R=%.9f" % (it, r_t))
        if time.process_time() < slice_end - 1.0:
            h_t = _lbfgs_log(best, slice_end - 0.3, maxiter=200)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("log pass %d ACCEPT2 R=%.9f" % (it, bestR))

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))
    result = {"best": best}
    if alt is not None and altR > 0 and alt.size != best.size:
        result["alternative"] = alt
    return result

