    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _coarsen(h, factor):
    n = h.size
    m = max(1, n // factor)
    edges = np.linspace(0, n, m + 1).astype(int)
    out = np.empty(m)
    for i in range(m):
        a, b = edges[i], edges[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _jitter_seed(h, rng, n_blocks, sigma=0.20):
    N = h.size
    out = h.copy()
    fracs = rng.uniform(0.015, 0.08, size=n_blocks)
    positions = []
    for k in range(n_blocks):
        w = max(2, int(fracs[k] * N))
        lo = int(rng.integers(0, max(1, N - w)))
        positions.append((lo, lo + w))
    positions.sort()
    last_hi = -1
    for lo, hi in positions:
        if lo < last_hi:
            continue
        last_hi = hi
        fac = np.exp(rng.normal(0.0, sigma, size=hi - lo))
        out[lo:hi] = out[lo:hi] * fac
    out = np.clip(out, 0, None)
    if out.sum() <= 0:
        return h.copy()
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        cur = np.ones(256)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        for beta in (60.0, 200.0, 600.0):
            if time.process_time() >= deadline - 1.0:
                break
            cur = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline - 0.5)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        cur = _window_polish_peak(cur, deadline - 0.5, 0.3, 16, maxiter=400, beta=600.0)
        cur = _lbfgs_log(cur, maxiter=600, deadline=deadline - 0.5)
        return _rescale(cur)

    cur = start_arr.copy()
    cur_r = best_r
    rng = np.random.default_rng(int(t0 * 1e6) & 0xffffffff)

    alt = None
    alt_r = -1.0

    # ---- Phase A: coarse-to-fine multiresolution search (the new idea) ----
    # Coarsen to a smaller grid, optimize there (cheaper, escapes fine local minima),
    # then prolongate back to full resolution and polish.
    N_full = cur.size
    factors = [8, 4, 2]
    for fac in factors:
        if N_full // fac < 32:
            continue
        if time.process_time() >= deadline - 4.0:
            break
        hc = _coarsen(cur, fac)
        hc = _rescale(hc)
        # small jitter to escape current basin
        hc = _jitter_seed(hc, rng, n_blocks=int(rng.integers(3, 8)), sigma=0.20)
        slice_end = min(deadline - 2.0, time.process_time() + 6.0)
        for beta in (40.0, 150.0, 500.0):
            if time.process_time() >= slice_end - 0.4:
                break
            hc = _lbfgs_sm(hc, beta, maxiter=300, deadline=slice_end)
        if time.process_time() < slice_end - 0.4:
            hc = _lbfgs_log(hc, maxiter=500, deadline=slice_end)
        # prolongate back to full resolution
        hf = _prolongate(hc, N_full)
        hf = _rescale(hf)
        # polish at full resolution
        if time.process_time() < slice_end - 0.3:
            hf = _lbfgs_log(hf, maxiter=400, deadline=slice_end)
        if time.process_time() < slice_end - 0.3:
            hf = _window_polish_peak(hf, slice_end, 0.30, 20, maxiter=300, beta=600.0)
        r = R_of(hf)
        print("multires fac=%d R=%.6f (cur %.6f)" % (fac, r, cur_r))
        if r > cur_r:
            cur, cur_r = hf, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif r > alt_r:
            alt, alt_r = hf.copy(), r

    # ---- Phase B: full-resolution jittered restarts ----
    n_restarts = 0
    while time.process_time() < deadline - 2.5:
        n_restarts += 1
        n = cur.size
        n_blocks = int(rng.integers(4, 14))
        seed = _jitter_seed(cur, rng, n_blocks, sigma=0.25)
        if R_of(seed) < 0.85 * cur_r:
            continue
        slice_end = min(deadline - 1.5, time.process_time() + 3.5)
        for beta in (60.0, 200.0, 800.0):
            if time.process_time() >= slice_end - 0.4:
                break
            seed = _lbfgs_sm(seed, beta, maxiter=200, deadline=slice_end)
        if time.process_time() < slice_end - 0.4:
            seed = _lbfgs_log(seed, maxiter=400, deadline=slice_end)
        if time.process_time() < slice_end - 0.4:
            seed = _window_polish_peak(seed, slice_end, 0.25, 16, maxiter=300, beta=600.0)
        r = R_of(seed)
        print("restart %d R=%.6f (cur %.6f)" % (n_restarts, r, cur_r))
        if r > cur_r:
            cur, cur_r = seed, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif r > alt_r:
            alt, alt_r = seed.copy(), r

    if time.process_time() < deadline - 0.8:
        cand = _window_polish_peak(best, deadline - 0.5, 0.4, 32,
                                   maxiter=600, beta=1000.0)
        cand = _lbfgs_log(cand, maxiter=800, deadline=deadline - 0.4)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r

    print("final R=%.6f (start %.6f)" % (best_r, R_of(start_arr)))
    if alt is not None and alt_r > 0:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_topband(h, q):
    """CVaR top-band surrogate: replace log(max L) with log(mean of top-m knots)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    nL = Lf.size
    m = max(16, int(round(0.02 * nL)))
    m = min(m, nL)
    # knots within top q fraction of max
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    thr = q * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size < m:
        # take top-m by value
        idx = np.argpartition(Lf, -m)[-m:]
    else:
        # among those above thr, take top-m
        if idx.size > m:
            sub = Lf[idx]
            sel = np.argpartition(sub, -m)[-m:]
            idx = idx[sel]
    sm = Lf[idx].mean()
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[idx] += (1.0 / (sm * idx.size))
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_topband(h0, q, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_topband(hh, q)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _window_around_argmax(h, half_len):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - half_len)
    hi = min(h.size - 1, m + half_len)
    return np.arange(lo, hi + 1)


def _lift_to(h, N):
    """Mass-preserving lift from size n to size N (N a multiple of n) via repeat."""
    n = h.size
    if n == N:
        return h.copy()
    if N % n == 0:
        k = N // n
        return np.repeat(h, k) / k
    # general: linear resample preserving mass
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    f = np.interp(x_new, x_old, h)
    s_old = h.sum()
    s_new = f.sum()
    if s_new > 0:
        f = f * (s_old / s_new)
    return f


TARGET_N = 104992


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    # Mass-preserving lift to target N if needed
    if start_best.size < TARGET_N:
        start_best = _rescale(_lift_to(start_best, TARGET_N))
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(ht, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, tag
            print("%s NEW BEST R=%.9f" % (tag, bestR))
            return True
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            return False

    N = best.size
    half_win = max(64, N // 16)  # N/8 window => half_len N/16

    rounds = 0
    while time.process_time() < deadline - 2.0:
        rounds += 1
        # (a) exact tie-averaged log-space L-BFGS on active cells, ~5s
        slice_dl = min(deadline - 2.0, time.process_time() + 5.0)
        ht = _lbfgs_all_pos(best, 400, slice_dl - 0.3, beta=1e7)
        consider(ht, 'r%d_tie' % rounds)

        # (b) CVaR top-band surrogate for q in 0.95,0.98,0.99, ~4s each
        for q in (0.95, 0.98, 0.99):
            if time.process_time() >= deadline - 2.0:
                break
            slice_dl = min(deadline - 2.0, time.process_time() + 4.0)
            htq = _lbfgs_topband(best, q, 300, slice_dl - 0.3)
            consider(htq, 'r%d_q%.2f' % (rounds, q))

        # (c) exact full tie polish ~4s
        if time.process_time() < deadline - 2.0:
            slice_dl = min(deadline - 2.0, time.process_time() + 4.0)
            ht = _lbfgs_all_pos(best, 400, slice_dl - 0.3, beta=1e7)
            consider(ht, 'r%d_full' % rounds)

        # (d) peak-window polish on window of length N/8 around argmax, ~3s
        if time.process_time() < deadline - 2.0:
            slice_dl = min(deadline - 2.0, time.process_time() + 3.0)
            win = _window_around_argmax(best, half_win)
            htw = _lbfgs_block(best, win, 400, slice_dl - 0.3, beta=1e7)
            consider(htw, 'r%d_pk' % rounds)

    # Finish with one full exact tie L-BFGS
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.3, beta=1e7)
        consider(ht, origin + '+final')

    print("rounds=%d bestR=%.9f" % (rounds, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, free, maxiter, deadline, cvar_q=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    floor = 1e-12 * max(h.max(), 1e-30)
    u0 = np.log(np.clip(h[active], floor, None))
    fg = (lambda hh: _fun_grad_cvar(hh, cvar_q)) if cvar_q is not None else _fun_grad_tie

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _find_block(h, tol=1e-9):
    N = h.size
    if N < 2:
        return 1
    for BLK in range(min(256, N), 1, -1):
        if N % BLK != 0:
            continue
        K = N // BLK
        c = h.reshape(K, BLK)
        scale = max(np.abs(c).max(), 1e-30)
        if np.max(np.abs(c - c[:, :1])) <= tol * scale:
            return BLK
    return 1


def _fun_grad_pnorm(h, p=32.0):
    """Smooth-max surrogate of ||f*f||_inf: (sum L^p)^(1/p). p large -> max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None) ** p
    Sp = Lp.sum()
    if Sp <= 0:
        return 1e18, np.zeros(h.size)
    M = Sp ** (1.0 / p)
    gLf = -dq / num
    # dM/dL = L^(p-1) * M^(1-p)
    gLf += (np.clip(Lf, 0, None) ** (p - 1.0)) * (M ** (1.0 - p))
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    return val, grad


def _lbfgs_log_pnorm(h0, free, maxiter, deadline, p):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    floor = 1e-12 * max(h.max(), 1e-30)
    u0 = np.log(np.clip(h[active], floor, None))

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = _fun_grad_pnorm(hh, p)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best = None
    startR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size
    allidx = np.arange(N)

    # Stage 1: smooth-max (p-norm) homotopy with increasing p, then CVaR.
    # The p-norm surrogate avoids the non-differentiability of the tie set
    # and can push height into the tie region more smoothly.
    cur = best.copy()
    for p in (8.0, 16.0, 32.0, 64.0):
        if time.process_time() >= deadline - 4.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + budget_seconds * 0.05)
        cand = _lbfgs_log_pnorm(cur, allidx, 60, tlim, p)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand.copy(), r
        cur = cand

    for q in (0.98, 0.995, 0.999):
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + budget_seconds * 0.06)
        cand = _lbfgs_log(cur, allidx, 80, tlim, cvar_q=q)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand.copy(), r
        cur = cand

    # Stage 2: alternate full-length tie polish and peak-window polish.
    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        tlim = min(deadline - 0.5, time.process_time() + budget_seconds * 0.16)
        cand = _lbfgs_log(best, allidx, 80, tlim)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r

        for pad in (0.05, 0.02):
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            tlim = min(deadline - 0.4, time.process_time() + budget_seconds * 0.10)
            cand = _lbfgs_log(best, win, 120, tlim)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r

        print("cycle %d R=%.12f ties=%d" % (cycle, bestR, _tie_count(best)))

    # Stage 3: block-structured refinement.
    if time.process_time() < deadline - 1.5:
        BLK = _find_block(best, tol=1e-7)
        if BLK > 1:
            K = N // BLK
            c0 = best.reshape(K, BLK).mean(axis=1)
            hc = np.repeat(np.clip(c0, 0, None), BLK)
            hc = _rescale(hc)
            rc = R_of(hc)
            if rc > bestR + 1e-14:
                best, bestR = hc.copy(), rc
            for _ in range(6):
                if time.process_time() >= deadline - 0.6:
                    break
                tlim = min(deadline - 0.4, time.process_time() + budget_seconds * 0.05)
                if time.process_time() >= tlim - 0.3:
                    break
                floor = 1e-12 * max(c0.max(), 1e-30)
                u0 = np.log(np.clip(hc[::BLK], floor, None))

                def f(u, _BLK=BLK):
                    cc = np.exp(np.clip(u, -40.0, 40.0))
                    hh = np.repeat(cc, _BLK)
                    val, g = _fun_grad_tie(hh)
                    gg = g.reshape(cc.size, _BLK).sum(axis=1) * cc
                    return val, gg

                cb = _make_cb(tlim - 0.2)
                try:
                    res = minimize(f, u0, jac=True, method='L-BFGS-B',
                                   bounds=[(-40.0, 40.0)] * K,
                                   callback=cb,
                                   options={'maxiter': 120, 'maxfun': 240,
                                            'ftol': 1e-20, 'gtol': 1e-16})
                except (TimeoutError, Exception):
                    break
                if res is None:
                    break
                cc = np.exp(np.clip(res.x, -40.0, 40.0))
                hc = _rescale(np.repeat(cc, BLK))
                rc = R_of(hc)
                if rc > bestR + 1e-14:
                    best, bestR = hc.copy(), rc
                else:
                    break

    # Stage 4: final polish.
    if time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.3, time.process_time() + budget_seconds * 0.15)
        cand = _lbfgs_log(best, allidx, 120, tlim)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return 1e18, np.zeros(h.size)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-10))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_tie(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.125, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_polish(h, deadline):
    if time.process_time() >= deadline - 0.5:
        return h
    win = _peak_window(h, tol=0.95, pad_frac=0.125, extra=256)
    ht = _lbfgs_block(h, win, 150, deadline)
    if R_of(ht) > R_of(h) + 1e-15:
        return ht
    return h


def _lift(h, Nnew):
    """Mass-preserving cumulative-sum linear interpolation to Nnew steps."""
    N = h.size
    if Nnew == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    # boundaries in old index space for new step edges
    edges = np.arange(Nnew + 1) * (N / Nnew)
    # cumulative mass at edges via linear interp of c at integer boundaries
    # c has N+1 entries at positions 0..N
    cmass = np.interp(edges, np.arange(N + 1), c)
    hnew = np.diff(cmass)
    hnew = np.clip(hnew, 0, None)
    return hnew


def _fold(h, N):
    """Fold by weighted block sums via cumulative mass at boundaries b_i=i*N'/N."""
    Np = h.size
    if Np == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(N + 1) * (Np / N)
    cmass = np.interp(edges, np.arange(Np + 1), c)
    hnew = np.diff(cmass)
    return np.clip(hnew, 0, None)


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _zero_frac(h):
    return float(np.mean(h <= 0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best)))

    rng = np.random.default_rng(12345)
    ratios = [(3, 2), (5, 3), (7, 4), (2, 1)]
    ri = 0
    consec_reject = 0

    def try_chain(h, Np, fd):
        """Lift to Np, tie-LBFGS, fold back, tie-LBFGS, peak polish."""
        hl = _lift(h, Np)
        hl = _rescale(hl)
        fd1 = min(fd, time.process_time() + 12.0)
        hl = _lbfgs_tie(hl, 150, fd1)
        if time.process_time() >= fd - 0.5:
            return h
        hf = _fold(hl, h.size)
        hf = _rescale(hf)
        fd2 = min(fd, time.process_time() + 8.0)
        hf = _lbfgs_tie(hf, 150, fd2)
        hf = _peak_polish(hf, fd)
        return hf

    while time.process_time() < deadline - 3.0:
        p, q = ratios[ri % len(ratios)]
        ri += 1
        N = best.size
        Np = int(round(N * p / q))
        if Np < 16 or Np > 1000000:
            continue
        fd = min(deadline - 2.0, time.process_time() + 25.0)
        hc = try_chain(best, Np, fd)
        rc = R_of(hc)
        if rc > bestR + 1e-12:
            best, bestR = hc.copy(), rc
            consec_reject = 0
            print("ACCEPT lift (%d,%d) N'=%d R=%.9f" % (p, q, Np, bestR))
        else:
            consec_reject += 1

        if consec_reject >= 6 and time.process_time() < deadline - 6.0:
            consec_reject = 0
            # randomized upsample restart
            Nc = best.size
            c = best.copy()
            eps = rng.uniform(-0.1, 0.1, size=Nc)
            h2 = np.empty(2 * Nc)
            h2[0::2] = c * (1.0 + eps)
            h2[1::2] = c * (1.0 - eps)
            h2 = np.clip(h2, 0, None)
            h2 = _rescale(h2)
            fd = min(deadline - 2.0, time.process_time() + 8.0)
            h2 = _lbfgs_tie(h2, 150, fd)
            h2 = _peak_polish(h2, deadline - 1.0)
            r2 = R_of(h2)
            if r2 > bestR + 1e-12:
                best, bestR = h2.copy(), r2
                print("ACCEPT restart R=%.9f" % bestR)
            else:
                print("restart rejected R=%.9f" % r2)

    # final polish
    if time.process_time() < deadline - 1.0:
        hp = _peak_polish(best, deadline - 0.5)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

