    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return 1e18, np.zeros(h.size)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hv = h[active]
    floor = max(1e-12, 1e-9 * h.mean())
    x0 = np.log(np.clip(hv, floor, None))

    def f(x):
        hh = h.copy()
        hh[active] = np.exp(np.clip(x, -60.0, 60.0))
        val, g = _fun_grad_tie(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -60.0, 60.0))
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def _polish(h, fd):
    ht = _lbfgs_all_pos(h, 200, fd)
    if R_of(ht) > R_of(h) + 1e-15:
        h = ht
    if time.process_time() < fd - 0.5:
        win = _peak_window(h, tol=0.95, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(h, win, 200, fd)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def _resample(h, N):
    """Resample step function h (length n) onto N equal steps of the same
    total support width, by exact interval-averaging of the piecewise-constant
    function. This keeps the shape (and hence R approximately) invariant."""
    n = h.size
    if n == N:
        return h.copy()
    # edges of source intervals on [0,1]
    xs = np.linspace(0.0, 1.0, n + 1)
    xt = np.linspace(0.0, 1.0, N + 1)
    # cumulative integral of h at source edges
    cum = np.concatenate(([0.0], np.cumsum(h * np.diff(xs))))
    # integral at target edges by linear interpolation of cum
    cumt = np.interp(xt, xs, cum)
    return np.diff(cumt) * (N / 1.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    # ---- NEW: multi-resolution refinement ----
    # The core idea: the optimum at N steps is a discretisation of a smooth
    # continuous profile. Go to a *larger* N (upsampled), optimise there, then
    # down-sample back. Higher resolution lifts the discretisation ceiling.
    # We also try a smaller N (downsampled) then up again, to escape local
    # traps in the step-pattern.
    n0 = best.size

    def try_resolution(h, Nnew, fd_frac):
        if time.process_time() >= deadline - 2.0:
            return h, R_of(h)
        fd = min(deadline, time.process_time() + budget_seconds * fd_frac)
        hr = _resample(h, Nnew)
        hr = _rescale(hr)
        hr = _lbfgs_all_pos(hr, 120, fd)
        # polish peak window
        if time.process_time() < fd - 0.5:
            win = _peak_window(hr, tol=0.95, pad_frac=0.10, extra=128)
            hb = _lbfgs_block(hr, win, 120, fd)
            if R_of(hb) > R_of(hr):
                hr = hb
        # return at original resolution (down-sample back) AND as-is
        return hr

    # Try upsampling ladder — but keep both resolutions and pick best
    up_ladder = [int(n0 * 1.5), int(n0 * 2.0), int(n0 * 3.0)]
    up_ladder = [N for N in up_ladder if N <= 1000000]
    best_hi = None
    best_hiR = 0.0
    for N in up_ladder:
        if time.process_time() >= deadline - 2.0:
            break
        hr = try_resolution(best, N, 0.10)
        r = R_of(hr)
        if r > bestR + 1e-12:
            best, bestR = hr.copy(), r
            print("upsample N=%d ACCEPT R=%.9f" % (N, bestR))
        else:
            print("upsample N=%d reject R=%.9f (best %.9f)" % (N, r, bestR))
        if r > best_hiR:
            best_hi, best_hiR = hr.copy(), r

    # Downsample-then-refine to escape pattern traps
    down_ladder = [max(64, n0 // 2), max(64, n0 // 3)]
    for N in down_ladder:
        if time.process_time() >= deadline - 2.0:
            break
        hr = try_resolution(best, N, 0.06)
        # re-upsample to original size and polish
        if time.process_time() < deadline - 2.0:
            fd = min(deadline, time.process_time() + budget_seconds * 0.05)
            hu = _resample(hr, n0)
            hu = _rescale(hu)
            hu = _lbfgs_all_pos(hu, 100, fd)
            r = R_of(hu)
            if r > bestR + 1e-12:
                best, bestR = hu.copy(), r
                print("down/up N=%d ACCEPT R=%.9f" % (N, bestR))
            else:
                print("down/up N=%d reject R=%.9f (best %.9f)" % (N, r, bestR))

    # ---- support flip loop (as before, but on best) ----
    M_ladder = [8, 16, 32, 64]
    eps_ladder = [1e-3, 1e-2, 1e-1]

    def support_flip(h, M, eps, fd):
        h = np.clip(h, 0, None)
        _, g = _fun_grad_tie(h)
        zeros = np.flatnonzero(h <= 0)
        active = np.flatnonzero(h > 0)
        if zeros.size == 0 or active.size == 0:
            return h
        zord = zeros[np.argsort(-g[zeros])]
        rev = zord[:M]
        if rev.size == 0:
            return h
        h2 = h.copy()
        mean_h = h.mean()
        h2[rev] = eps * mean_h
        aord = active[np.argsort(g[active])]
        pr = aord[:min(M, aord.size)]
        h2[pr] = 0.0
        free = np.flatnonzero(h2 > 0)
        h2 = _lbfgs_log(h2, free, 200, fd)
        if time.process_time() < fd - 0.5:
            win = _peak_window(h2, tol=0.95, pad_frac=0.10, extra=128)
            h3 = _lbfgs_block(h2, win, 150, fd)
            if R_of(h3) > R_of(h2):
                h2 = h3
        return h2

    loop = 0
    while time.process_time() < deadline - 2.0:
        loop += 1
        improved = False
        for M in M_ladder:
            if time.process_time() >= deadline - 2.0:
                break
            for eps in eps_ladder:
                if time.process_time() >= deadline - 2.0:
                    break
                fd = min(deadline, time.process_time() + budget_seconds * 0.05)
                cand = support_flip(best, M, eps, fd)
                r = R_of(cand)
                if r > bestR + 1e-12:
                    best, bestR = cand.copy(), r
                    improved = True
                    print("loop %d flip M=%d eps=%.0e ACCEPT R=%.9f zf=%.4f"
                          % (loop, M, eps, bestR, _zero_frac(best)))
                    break
                else:
                    print("loop %d flip M=%d eps=%.0e reject R=%.9f (best %.9f) zf=%.4f"
                          % (loop, M, eps, r, bestR, _zero_frac(cand)))
        if time.process_time() < deadline - 2.0:
            fd = min(deadline, time.process_time() + budget_seconds * 0.08)
            hp = _polish(best, fd)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
                print("loop %d polish ACCEPT R=%.9f zf=%.4f" % (loop, bestR, _zero_frac(best)))

    # final: try a fine-resolution push if time allows
    if time.process_time() < deadline - 2.0:
        N_fin = min(1000000, int(best.size * 2))
        hr = try_resolution(best, N_fin, 0.06)
        r = R_of(hr)
        if r > bestR + 1e-12:
            best, bestR = hr.copy(), r
            print("final upsample N=%d ACCEPT R=%.9f" % (N_fin, bestR))

    if time.process_time() < deadline - 1.0:
        fd = deadline - 0.5
        hp = _polish(best, fd)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        # If we only found an equal result via a different route, still offer it
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_ceiling(h, c, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    g = Lf
    excess = np.maximum(g - c, 0.0)
    nk = g.size
    scale = c * c * nk
    pen = mu * np.sum(excess * excess) / scale
    gLf = -dq / num
    gLf += mu * 2.0 * excess / scale
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _opt_log(h0, fun, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _opt_log(h0, _fun_grad_tie, deadline, maxiter)


def _ceiling_lbfgs(h0, c, mu, deadline, maxiter=40):
    return _opt_log(h0, lambda hh: _fun_grad_ceiling(hh, c, mu), deadline, maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    deltas = [1e-4, 3e-4, 1e-3, 3e-3, 1e-2]
    mu = 1e4

    rounds = 0
    while time.process_time() < deadline - 2.0:
        rounds += 1
        Lf = _knots(best)
        mx = Lf.max()
        improved_any = False
        for delta in deltas:
            if time.process_time() >= deadline - 2.0:
                break
            c = mx * (1.0 - delta)
            tlim = min(deadline - 1.5, time.process_time() + 3.0)
            h_ceil = _ceiling_lbfgs(best, c, mu, tlim, maxiter=40)
            # exact tie recovery at N
            if time.process_time() < deadline - 2.0:
                tlim = min(deadline - 1.5, time.process_time() + 4.0)
                h_rec = _full_lbfgs(h_ceil, tlim, maxiter=150)
                r_rec = R_of(h_rec)
                if r_rec > bestR + 1e-12:
                    best = h_rec
                    bestR = r_rec
                    improved_any = True
                    print("delta=%.0e ACCEPT R=%.12f" % (delta, bestR))
                else:
                    print("delta=%.0e reject R=%.12f (best %.12f)"
                          % (delta, r_rec, bestR))
            if time.process_time() < deadline - 2.0:
                tlim = min(deadline - 1.2, time.process_time() + 3.0)
                h_pk = _peak_window_polish(best, tlim, pad=3)
                rp = R_of(h_pk)
                if rp > bestR + 1e-12:
                    best = h_pk
                    bestR = rp
                    improved_any = True
        # full exact tie L-BFGS after ladder
        if time.process_time() < deadline - 2.0:
            tlim = min(deadline - 1.5, time.process_time() + 8.0)
            h_full = _full_lbfgs(best, tlim, maxiter=200)
            rf = R_of(h_full)
            if rf > bestR + 1e-12:
                best = h_full
                bestR = rf
                improved_any = True
        if not improved_any and rounds > 1:
            break

    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.8, time.process_time() + 6.0)
        h_full = _full_lbfgs(best, tlim, maxiter=200)
        rf = R_of(h_full)
        if rf > bestR + 1e-15:
            best = h_full
            bestR = rf

    print("rounds %d" % rounds)
    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if bestR >= startR:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, deadline, maxiter=150, cvar=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))
    fg = _fun_grad_tie if cvar is None else (lambda hh: _fun_grad_cvar(hh, cvar))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fg(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    return np.clip(np.diff(C2), 0, None)


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    return np.clip(np.diff(C), 0, None)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    sub = h[lo:hi].copy()
    if sub.sum() <= 0:
        return h
    # polish the window as its own problem, then paste back
    subp = _full_lbfgs(sub, deadline, maxiter=120)
    out = h.copy()
    # rescale window so its peak matches original scale
    out[lo:hi] = subp
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(0xC0FFEE)

    start_h = None
    startR = 0.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            start_h = _rescale(s)
            startR = R_of(start_h)

    if start_h is None:
        N0 = 4096
        h = np.ones(N0)
        h = _rescale(h)
        start_h = h
        startR = R_of(h)

    N = start_h.size

    best_h = start_h.copy()
    bestR = startR

    # Stage 1: full log-space L-BFGS polish at native N.
    hp = _full_lbfgs(best_h, deadline, maxiter=200)
    rp = R_of(hp)
    if rp > bestR:
        best_h, bestR = hp, rp
    print("stage1 R=%.9f (start %.9f, N=%d)" % (bestR, startR, N))

    # Stage 2: lift to larger N, polish, fold back if better.
    if time.process_time() < deadline - 3.0:
        for factor in (2, 3):
            if time.process_time() >= deadline - 3.0:
                break
            N2 = min(200000, N * factor)
            if N2 <= N:
                continue
            hl = _lift_mass_preserving(best_h, N2)
            hl = _rescale(hl)
            hp2 = _full_lbfgs(hl, deadline, maxiter=120)
            rp2 = R_of(hp2)
            hf = _fold_back(hp2, N)
            hf = _rescale(hf)
            rf = R_of(hf)
            print("lift x%d: direct %.9f folded %.9f" % (factor, rp2, rf))
            if rf > bestR + 1e-10:
                best_h, bestR = hf, rf
            if rp2 > bestR + 1e-10:
                # keep larger-N result too
                best_h, bestR = hp2, rp2
                N = N2

    # Stage 3: CVaR warm-start polish to escape the sharp max plateau.
    if time.process_time() < deadline - 2.0:
        for q in (0.999, 0.995, 0.99):
            if time.process_time() >= deadline - 2.0:
                break
            hc = _full_lbfgs(best_h, deadline, maxiter=80, cvar=q)
            hc = _full_lbfgs(hc, deadline, maxiter=120)
            rc = R_of(hc)
            if rc > bestR + 1e-12:
                best_h, bestR = hc, rc
                print("cvar %.4f -> R=%.9f" % (q, bestR))

    # Stage 4: peak-window refinements.
    for _ in range(3):
        if time.process_time() >= deadline - 1.0:
            break
        hw = _peak_window_polish(best_h, deadline)
        rw = R_of(hw)
        if rw > bestR + 1e-12:
            best_h, bestR = hw, rw
            print("peak-window R=%.9f" % bestR)

    # Stage 5: final full polish.
    if time.process_time() < deadline - 0.5:
        hf = _full_lbfgs(best_h, deadline, maxiter=200)
        rf = R_of(hf)
        if rf > bestR:
            best_h, bestR = hf, rf

    if start_h is not None and bestR < startR:
        best_h, bestR = start_h, startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best_h.size))

    result = {"best": best_h}
    # alternative: the lift-stage candidate if it differs and beats start
    try:
        if 'hp2' in dir() and hp2 is not None:
            ra = R_of(hp2)
            if ra > startR + 1e-12 and hp2.size != best_h.size:
                na = np.linalg.norm(hp2); nb = np.linalg.norm(best_h)
                if na > 0 and nb > 0 and float(np.dot(hp2, best_h) / (na * nb)) < 0.9999:
                    result["alternative"] = hp2
    except Exception:
        pass
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, fg=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        elif tie:
            fg = _fun_grad_tie
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _band_window(h, frac):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(n)
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        c = int(np.argmax(Lf))
    else:
        c = (int(idx.min()) + int(idx.max())) // 2
    half = max(16, int(frac * n))
    lo = max(0, c - half)
    hi = min(n, c + half)
    return np.arange(lo, hi)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 2.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # New main idea: refine on a finer grid (lift via mass-preserving interp),
    # then polish there. More resolution near the flat top should help.
    N0 = best.size
    cur = best.copy()
    curR = bestR

    # Try lifting to a modestly finer grid (up to 2x, capped).
    N1 = min(2 * N0, 200000)
    if N1 > N0 * 1.2 and time.process_time() < hard - 25.0:
        try:
            lifted = _rescale(_lift_mass_preserving(best, N1))
            rl = R_of(lifted)
            print("  lift N=%d: R=%.9f" % (N1, rl))
            if rl >= bestR - 1e-6:
                cur, curR = lifted, rl
                if rl > bestR + 1e-13:
                    best, bestR = lifted.copy(), rl
        except Exception:
            pass

    # Stage 1: soft-max continuation to build up a flat top.
    betas = [3.0, 10.0, 30.0, 100.0, 300.0, 1000.0, 3000.0]
    for beta in betas:
        if time.process_time() >= hard - 10.0:
            break
        cap = min(hard - 9.0, time.process_time() + 3.0)
        hb = _lbfgs_log(cur, 250, cap, beta=beta)
        rb = R_of(hb)
        if rb > curR - 1e-10:
            cur, curR = hb, rb
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
            print("  beta=%.0f: R=%.9f" % (beta, bestR))

    # Stage 2: tie-gradient polish on full vector.
    for _ in range(4):
        if time.process_time() >= hard - 4.0:
            break
        cap = min(hard - 3.5, time.process_time() + 3.0)
        ht = _lbfgs_log(best, 300, cap, fg=_fun_grad_tie)
        rt = R_of(ht)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            print("  tie: R=%.9f" % bestR)
        else:
            break

    # Stage 3: block polish on windows around the flat top.
    for frac in (0.02, 0.05, 0.10, 0.20, 0.40, 0.60):
        if time.process_time() >= hard - 1.5:
            break
        free = _band_window(best, frac)
        cap = min(hard - 1.0, time.process_time() + 3.0)
        hb = _lbfgs_block(best, free, 200, cap, tie=True)
        rb = R_of(hb)
        if rb > bestR:
            best, bestR = hb, rb
            print("  band frac=%.2f: R=%.9f" % (frac, bestR))

    # Final hard-max pass.
    if time.process_time() < hard - 0.5:
        cap = min(hard - 0.3, time.process_time() + 2.0)
        hp = _lbfgs_log(best, 400, cap, fg=_fun_grad)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp, rp
            print("  hard: R=%.9f" % bestR)

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (np.mean(L >= 0.999 * mx), np.mean(L >= 0.99 * mx),
            np.mean(L >= 0.95 * mx))


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    """Tie-aware: average gradient over all near-max knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    mask = Lf >= mx * (1.0 - 1e-9)
    cnt = mask.sum()
    gLf = -dq / num
    gLf[mask] += (1.0 / mx) / cnt
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _block_lbfgs_log(h0, idx, maxiter, deadline):
    """Block-coordinate L-BFGS on log of h[idx]."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    idx = np.asarray(idx, dtype=int)
    if idx.size == 0:
        return h0
    hv = h[idx]
    floor = max(hv.max() * 1e-9, 1e-300)
    u0 = np.log(np.maximum(hv, floor))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(np.clip(u, -700, 700))
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -700, 700))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_window_polish(h, deadline, pads=(0.10, 0.06, 0.04)):
    best = h.copy()
    bestR = R_of(best)
    for pad in pads:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _block_lbfgs_log(best, win, 400, deadline - 0.3)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
    return best, bestR


def _lift_offset(h, N2, offset):
    """Mass-preserving lift to N2 via cumulative-mass interpolation at
    x = j*N/N2 + offset*N/N2 (clipped)."""
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return _rescale(np.repeat(h, 2)[:N2])
    # target sample positions in units of original cells
    j = np.arange(N2, dtype=float)
    x = (j + offset) * (N / N2)
    x = np.clip(x, 0.0, N)
    mass = np.interp(x, np.arange(N + 1, dtype=float), c)
    hm = np.diff(np.concatenate(([0.0], mass)))
    hm = np.clip(hm, 0, None)
    return _rescale(hm)


def _fold_offset(h, N, offset):
    """Fold back to N via cumulative-mass interpolation with offset."""
    N2 = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return _rescale(h[0::2][:N])
    j = np.arange(N, dtype=float)
    x = (j + offset) * (N2 / N)
    x = np.clip(x, 0.0, N2)
    mass = np.interp(x, np.arange(N2 + 1, dtype=float), c)
    hm = np.diff(np.concatenate(([0.0], mass)))
    hm = np.clip(hm, 0, None)
    return _rescale(hm)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(hc, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(hc)
        if r > bestR + 1e-13:
            best, bestR, origin = hc.copy(), r, tag
            print("  NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        if r > alt_bestR:
            alt_best, alt_bestR = hc.copy(), r
        return False

    N = best.size
    if N < 8:
        return {"best": best}

    # ---- Block-coordinate descent over interleaved sub-lattices ----
    round_no = 0
    phi_seq = [1, 0, 1, 0]
    while time.process_time() < deadline - 1.5:
        phi = phi_seq[round_no % len(phi_seq)]
        round_no += 1
        idx = np.arange(phi, N, 2)
        if idx.size < 2:
            continue
        now = time.process_time()
        slice_dl = min(deadline - 1.0, now + 0.10 * budget_seconds)
        if slice_dl <= now + 0.5:
            break

        # block-coordinate step on this sublattice
        hb = _block_lbfgs_log(best, idx, 400, slice_dl - 0.3)
        rb = R_of(hb)
        accepted = False
        if rb > bestR + 1e-13:
            best, bestR, origin = hb.copy(), rb, 'phi%d_r%d' % (phi, round_no)
            accepted = True
            print("  NEW BEST R=%.9f (phi=%d block)" % (bestR, phi))
        elif rb > alt_bestR:
            alt_best, alt_bestR = hb.copy(), rb

        # full-N tie polish
        if time.process_time() < slice_dl - 0.6:
            hf = _full_lbfgs(best if accepted else hb, 300, slice_dl - 0.3,
                             beta=0.0)
            if consider(hf, 'phi%d_full_r%d' % (phi, round_no)):
                accepted = True

        # peak-window polish
        if time.process_time() < slice_dl - 0.5:
            hp, rp = _peak_window_polish(best, slice_dl)
            if consider(hp, 'phi%d_pk_r%d' % (phi, round_no)):
                accepted = True

        sh = _shares(best)
        print("cycle %d phi=%d acc=%s R=%.9f shares=%.3f/%.3f/%.3f (best %.9f)"
              % (round_no, phi, accepted, R_of(best), sh[0], sh[1], sh[2],
                 bestR))

        # Every third round: 2x mass-preserving lift with half-cell offset
        if round_no % 3 == 0 and time.process_time() < deadline - 2.0:
            N2 = 2 * N
            if N2 <= 1000000:
                lift_dl = min(deadline - 1.0,
                              time.process_time() + 0.12 * budget_seconds)
                if lift_dl > time.process_time() + 0.8:
                    hl = _lift_offset(best, N2, 0.5)
                    hl = _full_lbfgs(hl, 300, lift_dl - 0.4, beta=0.0)
                    if time.process_time() < lift_dl - 0.4:
                        hl = _full_lbfgs(hl, 300, lift_dl - 0.3, beta=1e6)
                    # fold back with complementary offset
                    hf = _fold_offset(hl, N, 0.5)
                    hf, rf = _peak_window_polish(hf, lift_dl)
                    if consider(hf, 'lift2x_r%d' % round_no):
                        pass
                    sh = _shares(best)
                    print("  lift2x round %d R=%.9f shares=%.3f/%.3f/%.3f"
                          % (round_no, R_of(best), sh[0], sh[1], sh[2]))

    # ---- Final polish ----
    if time.process_time() < deadline - 0.8:
        hp, rp = _peak_window_polish(best, deadline)
        consider(hp, origin + '+finalpk')
    if time.process_time() < deadline - 0.6:
        hf = _full_lbfgs(best, 300, deadline - 0.4, beta=0.0)
        consider(hf, origin + '+finalb0')

    print("final R=%.9f origin=%s (start %.9f, N=%d)"
          % (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, deadline, maxiter=150, pos=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if pos is None:
        pos = np.flatnonzero(h > 0)
        if pos.size == 0:
            return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _prolongate(h, N_new):
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N_new == N:
        return h.copy()
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    if total <= 0:
        return np.ones(N_new) / N_new
    xs = np.linspace(0.0, total, N_new + 1)
    old_x = np.linspace(0.0, total, N + 1)
    new_mass = np.interp(xs, old_x, cum)
    masses = np.diff(new_mass)
    h_new = masses * N_new
    return np.maximum(h_new, 0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    def time_left():
        return deadline - time.process_time()

    best_h = None
    best_R = -1.0
    start_h = None
    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            start_h = s.copy()
            start_R = R_of(start_h)
            best_h = start_h.copy()
            best_R = start_R

    rng = np.random.RandomState(20240101)

    # Build a coarse seed if no start: smooth bumpy profile.
    def make_seed(N):
        x = np.linspace(0, 1, N, endpoint=False)
        base = np.exp(-((x - 0.5) ** 2) / (2 * 0.18 ** 2))
        mod = 1.0 + 0.3 * np.sin(2 * np.pi * 3 * x + 0.7)
        return base * mod

    # ---- Stage 1: work at moderate N ----
    work = None
    if best_h is not None:
        # coarse-grain start down for fast polishing if it's large
        if len(best_h) > 8192:
            work = _prolongate(best_h, 8192)
        else:
            work = best_h.copy()
    else:
        work = make_seed(1024)

    # Polish at current size
    work = _lbfgs(work, deadline, maxiter=300)
    R = R_of(work)
    if R > best_R:
        best_R = R; best_h = work.copy()
    print(f"stage1 N={len(work)} R={R:.6f}")

    # ---- Stage 2: ladder of resolutions with polish each ----
    for N_target in (2048, 4096, 8192, 16384, 32768, 65536):
        if time_left() < 3.0:
            break
        h = _prolongate(best_h if best_h is not None else work, N_target)
        # a couple of polish rounds
        h = _lbfgs(h, deadline, maxiter=200)
        if time_left() > 2.0:
            h = _lbfgs(h, deadline, maxiter=200)
        R = R_of(h)
        if R > best_R:
            best_R = R; best_h = h.copy()
        print(f"stage2 N={N_target} R={R:.6f} best={best_R:.6f}")

    # ---- Stage 3: peak-window refinement at highest res ----
    if best_h is not None and time_left() > 2.0:
        h = best_h.copy()
        n = h.size
        for _ in range(4):
            if time_left() < 1.5:
                break
            Lf = _knots(h)
            pk = int(np.argmax(Lf))
            c = pk / 2.0
            lo = max(0, int(c) - n // 6)
            hi = min(n, int(c) + n // 6)
            if hi - lo < 8:
                break
            idx = np.arange(lo, hi)
            h = _lbfgs(h, deadline, maxiter=120, pos=idx)
            R = R_of(h)
            if R > best_R:
                best_R = R; best_h = h.copy()
        print(f"stage3 R={best_R:.6f}")

    # Final full polish
    if time_left() > 2.0 and best_h is not None:
        h = _lbfgs(best_h, deadline, maxiter=200)
        R = R_of(h)
        if R > best_R:
            best_R = R; best_h = h
        print(f"final R={best_R:.6f} N={len(best_h)}")

    if best_h is None:
        best_h = np.ones(64)

    if start_h is not None and start_R > best_R:
        return {"best": start_h, "alternative": best_h}
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = best.copy()

    # Stage A: sharp log-space full L-BFGS.
    if time.process_time() < deadline - 5.0:
        h = _lbfgs_log(cur, 800, deadline)
        r = R_of(h)
        print("log-lbfgs R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur

    # Stage B: beta sweep + peak polishes.
    for beta in (1e3, 1e4, 5e4, 2e5):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(cur, 250, deadline, beta=beta)
        r = R_of(h)
        print("beta=%.0e R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(cur, deadline, frac, 32,
                                     maxiter=200, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                print("  peak frac=%.2f R=%.7f" % (frac, rp))
            cur = hp if rp > bestR - 0.003 else cur

    # Stage C: final sharp.
    if time.process_time() < deadline - 2.0:
        h = _lbfgs_log(best, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final sharp R=%.7f" % bestR)

    # Stage D: alternate full sharp + peak polish until near deadline.
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  alt full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  alt peak #%d frac=%.2f R=%.7f" % (it, frac, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, deadline, maxiter=150, cvar=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))
    fg = _fun_grad_tie if cvar is None else (lambda hh: _fun_grad_cvar(hh, cvar))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fg(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    return np.clip(np.diff(C2), 0, None)


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    return np.clip(np.diff(C), 0, None)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    sub = h[lo:hi].copy()
    if sub.sum() <= 0:
        return h
    subp = _full_lbfgs(sub, deadline, maxiter=120)
    out = h.copy()
    out[lo:hi] = subp
    return _rescale(out)


def _near_max_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= mx * 0.999)),
            float(np.mean(Lf >= mx * 0.99)),
            float(np.mean(Lf >= mx * 0.95)))


def _split_pass(h, deadline, rng):
    """Subdivide every cell into two with random perturbation, polish, fold back."""
    N = h.size
    if N * 2 > 900000:
        return h
    eps = rng.uniform(-0.15, 0.15, size=N)
    h2 = np.empty(2 * N)
    h2[0::2] = h * (1.0 + eps)
    h2[1::2] = h * (1.0 - eps)
    h2 = _rescale(np.clip(h2, 0, None))
    hp = _full_lbfgs(h2, deadline, maxiter=100)
    hf = _rescale(_fold_back(hp, N))
    return hf


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(0xC0FFEE)

    start_h = None
    startR = 0.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            start_h = _rescale(s)
            startR = R_of(start_h)

    if start_h is None:
        N0 = 3281
        h = np.ones(N0)
        h = _rescale(h)
        start_h = h
        startR = R_of(h)

    N0 = start_h.size

    best_h = start_h.copy()
    bestR = startR
    bestN = N0

    # Initial native-N polish to establish a good baseline.
    if time.process_time() < deadline - 2.0:
        hp = _full_lbfgs(best_h, deadline, maxiter=200)
        rp = R_of(hp)
        if rp > bestR:
            best_h, bestR = hp, rp
        print("init R=%.9f (start %.9f, N=%d)" % (bestR, startR, best_h.size))

    N_levels = [N0, N0 * 2, N0 * 4]
    q_ladder = [0.999, 0.995, 0.99, 0.98, 0.95]

    loop = 0
    while time.process_time() < deadline - 1.0:
        loop += 1
        loop_start_R = bestR
        improved = False

        # (ii) N-loop with CVaR ladder + tie polish + peak-window polish
        for Nt in N_levels:
            if time.process_time() >= deadline - 1.0:
                break
            if Nt > 900000:
                continue
            if Nt == best_h.size:
                cand = best_h.copy()
            else:
                cand = _rescale(_lift_mass_preserving(best_h, Nt))
            # CVaR ladder warm starts
            for q in q_ladder:
                if time.process_time() >= deadline - 1.0:
                    break
                hc = _full_lbfgs(cand, deadline, maxiter=60, cvar=q)
                rc = R_of(hc)
                if rc > R_of(cand):
                    cand = hc
            # exact tie polish
            if time.process_time() < deadline - 1.0:
                ht = _full_lbfgs(cand, deadline, maxiter=120)
                if R_of(ht) > R_of(cand):
                    cand = ht
            # peak-window polish at this N
            if time.process_time() < deadline - 1.0:
                hw = _peak_window_polish(cand, deadline)
                if R_of(hw) > R_of(cand):
                    cand = hw
            rc = R_of(cand)
            if rc > bestR + 1e-12:
                best_h, bestR, bestN = cand, rc, cand.size
                improved = True
                sh = _near_max_shares(best_h)
                print("loop %d N=%d R=%.9f shares %.3f/%.3f/%.3f"
                      % (loop, bestN, bestR, sh[0], sh[1], sh[2]))

        # (iii) split pass at best N
        if time.process_time() < deadline - 1.5:
            hs = _split_pass(best_h, deadline, rng)
            rs = R_of(hs)
            if rs > bestR + 1e-12:
                best_h, bestR = hs, rs
                improved = True
                print("loop %d split R=%.9f" % (loop, bestR))

        if not improved:
            # small perturbation to try to escape
            if time.process_time() < deadline - 2.0:
                hpert = best_h * (1.0 + rng.uniform(-0.02, 0.02, size=best_h.size))
                hpert = _rescale(np.clip(hpert, 0, None))
                hp = _full_lbfgs(hpert, deadline, maxiter=80)
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best_h, bestR = hp, rp
                    improved = True
                    print("loop %d perturb R=%.9f" % (loop, bestR))
            if not improved:
                break

    # Final polish
    if time.process_time() < deadline - 0.5:
        hf = _full_lbfgs(best_h, deadline, maxiter=200)
        rf = R_of(hf)
        if rf > bestR:
            best_h, bestR = hf, rf

    if bestR < startR:
        best_h, bestR = start_h, startR

    print("final R=%.12f (start %.12f, N=%d, loops=%d)"
          % (bestR, startR, best_h.size, loop))

    result = {"best": best_h}
    if best_h.size != start_h.size:
        result["alternative"] = start_h
    return result

