    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    def cvar_stage(h, alpha, tlim):
        hp = _lbfgs_custom(h, lambda hh: _fun_grad_cvar(hh, alpha),
                           tlim, maxiter=120)
        return hp

    alphas = [0.02, 0.008, 0.003, 0.001, 0.0003, 0.0001, 0.00003]

    for alpha in alphas:
        if time.process_time() >= deadline - 1.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 6.0)
        hc = cvar_stage(best, alpha, tlim)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 2.0)
            hc = _full_lbfgs(hc, tlim2, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim3 = min(deadline - 1.0, time.process_time() + 1.5)
            hc = _peak_window_polish(hc, tlim3, pad=3)
        rc = R_of(hc)
        m = max(1, int(round(alpha * (hc.size + 1))))
        print("cvar a=%.5f m=%d R=%.9f (best %.9f)" % (alpha, m, rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc

    # Alternate the two smallest alphas + exact tie polish
    small = [0.0001, 0.00003]
    k = 0
    while time.process_time() < deadline - 1.0:
        alpha = small[k % 2]
        k += 1
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hc = cvar_stage(best, alpha, tlim)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 2.0)
            hc = _full_lbfgs(hc, tlim2, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim3 = min(deadline - 1.0, time.process_time() + 1.0)
            hc = _peak_window_polish(hc, tlim3, pad=3)
        rc = R_of(hc)
        print("alt a=%.5f R=%.9f (best %.9f)" % (alpha, rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (np.mean(L >= 0.999 * mx), np.mean(L >= 0.99 * mx),
            np.mean(L >= 0.95 * mx))


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    mask = Lf >= mx * (1.0 - 1e-9)
    cnt = mask.sum()
    gLf = -dq / num
    gLf[mask] += (1.0 / mx) / cnt
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _block_lbfgs_log(h0, idx, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    idx = np.asarray(idx, dtype=int)
    if idx.size == 0:
        return h0
    hv = h[idx]
    floor = max(hv.max() * 1e-9, 1e-300)
    u0 = np.log(np.maximum(hv, floor))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(np.clip(u, -700, 700))
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -700, 700))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_window_polish(h, deadline, pads=(0.10, 0.06, 0.04)):
    best = h.copy()
    bestR = R_of(best)
    for pad in pads:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _block_lbfgs_log(best, win, 400, deadline - 0.3)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
    return best, bestR


def _shrink_avg(h, N2):
    """Exact mass-preserving interval averaging to N2 cells."""
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return _rescale(np.ones(N2))
    j = np.arange(N2 + 1, dtype=float)
    x = j * (N / N2)
    x = np.clip(x, 0.0, N)
    mass = np.interp(x, np.arange(N + 1, dtype=float), c)
    hm = np.diff(mass)
    hm = np.clip(hm, 0, None)
    return _rescale(hm)


def _prolong(h, N2):
    """Mass-preserving cumulative-mass interpolation to N2 cells."""
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return _rescale(np.ones(N2))
    j = np.arange(N2 + 1, dtype=float)
    x = j * (N / N2)
    x = np.clip(x, 0.0, N)
    mass = np.interp(x, np.arange(N + 1, dtype=float), c)
    hm = np.diff(mass)
    hm = np.clip(hm, 0, None)
    return _rescale(hm)


def _coarse_climb(hc, deadline, climb_seconds):
    """Log-space L-BFGS-B on all active cells of hc, then peak polish."""
    n = hc.size
    idx = np.arange(n)
    now = time.process_time()
    dl = min(deadline - 0.3, now + climb_seconds)
    if dl <= now + 0.3:
        return hc
    hc2 = _block_lbfgs_log(hc, idx, 2000, dl)
    if time.process_time() < dl - 0.3:
        hp, _ = _peak_window_polish(hc2, dl, pads=(3.0, 1.5, 0.8))
        hc2 = hp
    return hc2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(hc, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(hc)
        if r > bestR + 1e-13:
            best, bestR, origin = hc.copy(), r, tag
            print("  NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        if r > alt_bestR:
            alt_best, alt_bestR = hc.copy(), r
        return False

    N = best.size
    if N < 8:
        return {"best": best}

    depths = [2, 4, 8]
    round_no = 0
    while time.process_time() < deadline - 2.0:
        D = depths[round_no % len(depths)]
        round_no += 1
        Nc = max(8, N // D)
        if Nc >= N:
            continue
        now = time.process_time()
        remain = deadline - now
        if remain < 1.5:
            break
        # allocate: coarse climb ~ 45% of remaining, prolong+full ~ rest
        climb_s = min(6.0, 0.45 * remain)
        hc = _shrink_avg(best, Nc)
        rc0 = R_of(hc)
        hc = _coarse_climb(hc, deadline, climb_s)
        rc1 = R_of(hc)

        # prolong back to full N
        hp = _prolong(hc, N)
        rp = R_of(hp)

        # full-N exact-tie L-BFGS + peak polish
        now = time.process_time()
        dl = min(deadline - 0.5, now + min(4.0, 0.5 * (deadline - now)))
        if dl > now + 0.4:
            hf = _full_lbfgs(hp, 400, dl, beta=0.0)
            if time.process_time() < dl - 0.4:
                hf, _ = _peak_window_polish(hf, dl)
        else:
            hf = hp
        rf = R_of(hf)
        accepted = consider(hf, 'shrink%d_r%d' % (D, round_no))
        sh = _shares(best)
        print("round %d D=%d Nc=%d Rc=%.9f->%.9f Rp=%.9f Rf=%.9f acc=%s "
              "best=%.9f shares=%.3f/%.3f/%.3f"
              % (round_no, D, Nc, rc0, rc1, rp, rf, accepted, bestR,
                 sh[0], sh[1], sh[2]))

    # Final polish on best
    if time.process_time() < deadline - 0.8:
        hp, _ = _peak_window_polish(best, deadline)
        consider(hp, origin + '+finalpk')
    if time.process_time() < deadline - 0.6:
        hf = _full_lbfgs(best, 300, deadline - 0.4, beta=0.0)
        consider(hf, origin + '+finalb0')

    print("final R=%.9f origin=%s (start %.9f, N=%d)"
          % (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

