    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _mass_resample(base, newN):
    n = base.size
    if n == newN:
        return _rescale(base.copy())
    c = np.concatenate(([0.0], np.cumsum(base)))
    total = c[-1]
    if total <= 0:
        return _rescale(np.ones(newN))
    edges = np.linspace(0.0, total, newN + 1)
    x_src = np.linspace(0.0, 1.0, n + 1)
    x_new = np.interp(edges, c, x_src)
    widths = np.diff(x_new)
    masses = np.diff(edges)
    h = np.where(widths > 1e-15, masses / np.maximum(widths, 1e-15), 0.0)
    return _rescale(h)


def _tile_blocks(hc, block_w, N):
    tiled = np.repeat(hc, block_w)
    if tiled.size != N:
        tiled = _mass_resample(tiled, N)
    return _rescale(tiled)


def _smooth_perturb(h, rng, scale=0.02, smooth=16):
    """Smooth multiplicative perturbation of h."""
    n = h.size
    k = max(1, n // smooth)
    noise = rng.standard_normal(k)
    # smooth interpolation
    xk = np.linspace(0, 1, k)
    xn = np.linspace(0, 1, n)
    pert = np.interp(xn, xk, noise)
    return _rescale(h * (1.0 + scale * pert))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, N, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- Phase A: quick multi-scale resample race (short, ~15% budget) ----
    race_end = t0 + budget_seconds * 0.18
    w0 = 32
    nb = N // w0
    if nb * w0 == N and nb >= 1:
        hc = _rescale(best.reshape(nb, w0).mean(axis=1))
    else:
        hc = best.copy()
        nb = N

    mb_list = [1640, 2188, 2625, 3281, 4375, 6562]
    best_cand = best.copy()
    best_candR = bestR
    for mb in mb_list:
        if time.process_time() >= race_end - 1.0:
            break
        try:
            hc_mb = _mass_resample(hc, mb)
            bw = max(1, N // mb)
            cand = _tile_blocks(hc_mb, bw, N)
        except Exception:
            continue
        r0 = R_of(cand)
        if r0 <= best_candR - 1e-6:
            continue
        slice_end = min(race_end, time.process_time() + 3.0)
        h = _lbfgs_all_pos(cand, 200, slice_end - 0.5, tie=True)
        r = R_of(h)
        if r > best_candR + 1e-15:
            best_cand, best_candR = h.copy(), r
        print("mb %d dR=%+.3e R=%.9f" % (mb, r - bestR, r))

    if best_candR > bestR + 1e-15:
        best, bestR = best_cand.copy(), best_candR
        print("race winner R=%.9f" % bestR)

    # ---- Phase B: structured perturbation search (basin escape) ----
    # Try a few small smooth perturbations; keep any improvement.
    rng = np.random.default_rng(12345)
    pert_end = t0 + budget_seconds * 0.42
    n_try = 0
    while time.process_time() < pert_end - 3.0 and n_try < 12:
        n_try += 1
        scale = [0.005, 0.01, 0.02, 0.04][n_try % 4]
        smooth = [8, 16, 32, 64][n_try % 4]
        hp = _smooth_perturb(best, rng, scale=scale, smooth=smooth)
        slice_end = min(pert_end, time.process_time() + 3.5)
        hp = _lbfgs_all_pos(hp, 300, slice_end - 0.5, tie=True)
        if time.process_time() < slice_end - 1.0:
            hp = _peak_ladder(hp, slice_end - 0.3,
                              pads=(0.05, 0.03), iters=120, tie=True)
        r = R_of(hp)
        dR = r - bestR
        if r > bestR + 1e-15:
            best, bestR = hp.copy(), r
            print("pert %d s=%.3f sm=%d ACCEPT dR=%+.3e R=%.9f"
                  % (n_try, scale, smooth, dR, bestR))
        else:
            print("pert %d s=%.3f sm=%d no gain dR=%+.3e R=%.9f"
                  % (n_try, scale, smooth, dR, bestR))

    # ---- Phase C: deep polish with peak ladder + tie/argmax alternation ----
    loop_end = t0 + budget_seconds * 0.85
    it = 0
    while time.process_time() < loop_end - 3.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 6.0)
        h_t = _lbfgs_all_pos(best, 600, slice_end - 3.0, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("tie %d ACCEPT R=%.9f ties=%d" % (it, bestR, _tie_count(best)))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=250, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("peak %d ACCEPT R=%.9f ties=%d nearmax5=%.4f"
                      % (it, bestR, _tie_count(best), _nearmax_frac(best)))

    # ---- Final passes ----
    fd = t0 + budget_seconds * 0.94
    if time.process_time() < fd - 4.0:
        h_t = _lbfgs_all_pos(best, 600, fd - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    alt = None
    if bestR <= startR + 1e-14 and start is not None:
        alt = best
    else:
        alt = best
    result["alternative"] = alt
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _support_trim(h, eps=1e-9):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    thr = eps * h.max()
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    return h[idx[0]:idx[-1] + 1].copy()


def _band_rand_perturb(h, rng, amp):
    """Multiplicative random perturbation of a contiguous band of h."""
    n = h.size
    if n < 16:
        return h
    w = max(4, n // 16)
    c = rng.randint(0, n)
    lo = max(0, c - w // 2)
    hi = min(n, lo + w)
    g = np.ones(n)
    g[lo:hi] = np.exp(amp * rng.randn(hi - lo))
    h2 = h * g
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    # ---- Prolongate to N=65536 ----
    N_big = 65536
    h = _prolongate(start_arr, N_big)
    h = _rescale(h)
    cur_r = R_of(h)
    print("prolong R=%.6f N=%d" % (cur_r, h.size))

    # ---- Descending-beta smooth-max continuation ----
    for beta in (1500.0, 800.0, 400.0, 200.0):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _lbfgs_sm(h, beta, maxiter=200, deadline=hard_end)
        rc = R_of(c)
        if rc >= cur_r:
            h, cur_r = c, rc
        print("beta=%.0f R=%.6f" % (beta, cur_r))

    # ---- Exact-objective log L-BFGS ----
    if time.process_time() < hard_end - 0.5:
        c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
        rc = R_of(c)
        if rc >= cur_r:
            h, cur_r = c, rc
        print("exact R=%.6f" % cur_r)

    # ---- Peak-window exact polish ----
    for frac, extra in ((0.05, 8), (0.10, 12), (0.20, 20)):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _window_polish_peak(h, hard_end, frac, extra, maxiter=400, beta=None)
        rc = R_of(c)
        if rc >= cur_r:
            h, cur_r = c, rc
        print("win frac=%.2f R=%.6f" % (frac, cur_r))

    # ---- Support-trimmed re-prolongation cycle ----
    if time.process_time() < hard_end - 2.0:
        ht = _support_trim(h, eps=1e-6)
        if ht.size < h.size and ht.size > 100:
            N_trim = min(65536, max(ht.size, int(ht.size * 1.2)))
            h2 = _prolongate(ht, N_trim)
            h2 = _rescale(h2)
            r2 = R_of(h2)
            if r2 >= cur_r - 0.001:
                c = _lbfgs_sm(h2, 400.0, maxiter=200, deadline=hard_end)
                rc = R_of(c)
                if rc > cur_r:
                    h, cur_r = c, rc
                    print("reprolong R=%.6f N=%d" % (cur_r, h.size))

    # ---- NEW: SPSA-style stochastic basin hopping on bands ----
    # While time remains, occasionally perturb a random band multiplicatively and
    # re-polish. This escapes the smooth local optimum that L-BFGS gets stuck in.
    rng = np.random.RandomState(0x5EED)
    hop_amp = 0.05
    hop_tries = 0
    while time.process_time() < hard_end - 3.0:
        hop_tries += 1
        cand = _band_rand_perturb(h, rng, hop_amp)
        c = _lbfgs_log(cand, maxiter=120, deadline=hard_end)
        rc = R_of(c)
        if rc > cur_r:
            h, cur_r = c, rc
            hop_amp = min(0.20, hop_amp * 1.3)
            print("hop#%d R=%.6f" % (hop_tries, cur_r))
        else:
            hop_amp = max(0.01, hop_amp * 0.85)
        if hop_tries % 4 == 0 and time.process_time() < hard_end - 4.0:
            c = _window_polish_peak(h, hard_end, 0.10, 12, maxiter=200, beta=None)
            rc = R_of(c)
            if rc >= cur_r:
                h, cur_r = c, rc

    # ---- Alternate full exact polish and peak-window polish ----
    try:
        while time.process_time() < hard_end - 1.0:
            c = _lbfgs_log(h, maxiter=400, deadline=hard_end)
            rc = R_of(c)
            if rc >= cur_r:
                h, cur_r = c, rc
            if time.process_time() >= hard_end - 0.5:
                break
            for frac, extra in ((0.20, 20), (0.10, 12), (0.05, 8)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=300, beta=None)
                rc = R_of(c)
                if rc >= cur_r:
                    h, cur_r = c, rc
            if time.process_time() >= hard_end - 1.0:
                break
    except Exception:
        pass

    print("final R=%.6f N=%d" % (cur_r, h.size))

    if cur_r > best_r:
        return {"best": h, "alternative": best}
    return {"best": best, "alternative": h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None)
    # power mean Mp = (mean(Lf**p))**(1/p)
    Lpow = Lp ** p
    Sp = Lpow.sum()
    if Sp <= 0:
        return 1e18, np.zeros(h.size)
    Mp = (Sp / Lf.size) ** (1.0 / p)
    if Mp <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    # d log Mp / d Lf = Lf**(p-1) / sum(Lf**p)
    gLf = gLf + (Lp ** (p - 1)) / Sp
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Mp)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, deadline, maxiter=150, cvar=None, pnorm=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))
    if pnorm is not None:
        fg = lambda hh: _fun_grad_pnorm(hh, pnorm)
    elif cvar is not None:
        fg = lambda hh: _fun_grad_cvar(hh, cvar)
    else:
        fg = _fun_grad_tie

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fg(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    return np.clip(np.diff(C2), 0, None)


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    return np.clip(np.diff(C), 0, None)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    sub = h[lo:hi].copy()
    if sub.sum() <= 0:
        return h
    subp = _full_lbfgs(sub, deadline, maxiter=120)
    out = h.copy()
    out[lo:hi] = subp
    return _rescale(out)


def _near_max_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= mx * 0.999)),
            float(np.mean(Lf >= mx * 0.99)),
            float(np.mean(Lf >= mx * 0.95)))


def _split_pass(h, deadline, rng):
    N = h.size
    if N * 2 > 900000:
        return h
    eps = rng.uniform(-0.15, 0.15, size=N)
    h2 = np.empty(2 * N)
    h2[0::2] = h * (1.0 + eps)
    h2[1::2] = h * (1.0 - eps)
    h2 = _rescale(np.clip(h2, 0, None))
    hp = _full_lbfgs(h2, deadline, maxiter=100)
    hf = _rescale(_fold_back(hp, N))
    return hf


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(0xC0FFEE)

    start_h = None
    startR = 0.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            start_h = _rescale(s)
            startR = R_of(start_h)

    if start_h is None:
        N0 = 3281
        h = np.ones(N0)
        h = _rescale(h)
        start_h = h
        startR = R_of(h)

    N0 = start_h.size

    best_h = start_h.copy()
    bestR = startR
    bestN = N0

    if time.process_time() < deadline - 2.0:
        hp = _full_lbfgs(best_h, deadline, maxiter=200)
        rp = R_of(hp)
        if rp > bestR:
            best_h, bestR = hp, rp
        print("init R=%.9f (start %.9f, N=%d)" % (bestR, startR, best_h.size))

    p_ladder = [4, 8, 16, 32, 64, 128, 256]
    N_cap = 200000

    loop = 0
    while time.process_time() < deadline - 1.0:
        loop += 1
        loop_start_R = bestR
        improved = False

        # lift ladder N, 2N, 4N
        N_levels = []
        for k in (1, 2, 4):
            Nt = bestN * k
            if Nt <= N_cap and Nt not in N_levels:
                N_levels.append(Nt)

        for Nt in N_levels:
            if time.process_time() >= deadline - 1.0:
                break
            if Nt == best_h.size:
                cand = best_h.copy()
            else:
                cand = _rescale(_lift_mass_preserving(best_h, Nt))
            candR = R_of(cand)

            # p-norm anneal
            for p in p_ladder:
                if time.process_time() >= deadline - 1.0:
                    break
                # ~2s budget per stage
                stage_deadline = min(deadline - 1.0, time.process_time() + 2.0)
                hc = _full_lbfgs(cand, stage_deadline, maxiter=40, pnorm=p)
                rc = R_of(hc)
                if rc > candR:
                    cand = hc
                    candR = rc
                sh = _near_max_shares(cand)
                print("loop %d N=%d p=%d R=%.9f shares %.3f/%.3f/%.3f"
                      % (loop, cand.size, p, candR, sh[0], sh[1], sh[2]))

            # exact-tie polish ~1.5s
            if time.process_time() < deadline - 1.0:
                stage_deadline = min(deadline - 1.0, time.process_time() + 1.5)
                ht = _full_lbfgs(cand, stage_deadline, maxiter=80)
                rt = R_of(ht)
                if rt > candR:
                    cand = ht
                    candR = rt
                    print("loop %d N=%d tie R=%.9f" % (loop, cand.size, candR))

            # peak-window polish ~1s
            if time.process_time() < deadline - 1.0:
                hw = _peak_window_polish(cand, deadline)
                rw = R_of(hw)
                if rw > candR:
                    cand = hw
                    candR = rw
                    print("loop %d N=%d peak R=%.9f" % (loop, cand.size, candR))

            if candR > bestR + 1e-12:
                best_h, bestR, bestN = cand, candR, cand.size
                improved = True
                sh = _near_max_shares(best_h)
                print("loop %d N=%d R=%.9f shares %.3f/%.3f/%.3f"
                      % (loop, bestN, bestR, sh[0], sh[1], sh[2]))

        # split pass
        if time.process_time() < deadline - 1.5:
            hs = _split_pass(best_h, deadline, rng)
            rs = R_of(hs)
            if rs > bestR + 1e-12:
                best_h, bestR = hs, rs
                improved = True
                print("loop %d split R=%.9f" % (loop, bestR))

        if not improved:
            if time.process_time() < deadline - 2.0:
                hpert = best_h * (1.0 + rng.uniform(-0.02, 0.02, size=best_h.size))
                hpert = _rescale(np.clip(hpert, 0, None))
                hp = _full_lbfgs(hpert, deadline, maxiter=80)
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best_h, bestR = hp, rp
                    improved = True
                    print("loop %d perturb R=%.9f" % (loop, bestR))
            if not improved:
                # try p-norm anneal from scratch at best N to escape
                if time.process_time() < deadline - 3.0:
                    cand = best_h.copy()
                    candR = bestR
                    for p in p_ladder:
                        if time.process_time() >= deadline - 1.0:
                            break
                        stage_deadline = min(deadline - 1.0, time.process_time() + 2.0)
                        hc = _full_lbfgs(cand, stage_deadline, maxiter=40, pnorm=p)
                        rc = R_of(hc)
                        if rc > candR:
                            cand = hc
                            candR = rc
                    if candR > bestR + 1e-12:
                        best_h, bestR = cand, candR
                        improved = True
                        print("loop %d reanneal R=%.9f" % (loop, bestR))
                if not improved:
                    break

    if time.process_time() < deadline - 0.5:
        hf = _full_lbfgs(best_h, deadline, maxiter=200)
        rf = R_of(hf)
        if rf > bestR:
            best_h, bestR = hf, rf

    if bestR < startR:
        best_h, bestR = start_h, startR

    print("final R=%.12f (start %.12f, N=%d, loops=%d)"
          % (bestR, startR, best_h.size, loop))

    result = {"best": best_h}
    if best_h.size != start_h.size:
        result["alternative"] = start_h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return _fun_grad(h)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _fun_grad_band(h, lam, thr):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return _fun_grad(h)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)

    B = np.flatnonzero(Lf >= thr * c)
    if B.size > 0:
        diff = c - Lf[B]
        val += lam * np.mean(diff * diff) / (c * c)
        gLf[B] -= 2.0 * lam * diff / (B.size * c * c)

    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_band(h0, lam, thr, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_band(hh, lam, thr)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _window_around(h, center, half):
    n = h.size
    lo = max(0, int(center) - half)
    hi = min(n - 1, int(center) + half)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def _band_stats(h, thr):
    Lf = _knots(h)
    c = Lf.max()
    if c <= 0:
        return 0, 0.0
    B = Lf[Lf >= thr * c]
    if B.size == 0:
        return 0, 0.0
    return B.size, float(np.std(B) / c)


# ---- shrink-and-prolong helpers ----

def _coarsen(h, Nc):
    """Mass-preserving cumulative-mass interval averaging to Nc bins."""
    n = h.size
    if Nc >= n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nc)
    edges = np.linspace(0.0, total, Nc + 1)
    idx = np.searchsorted(c, edges, side='right') - 1
    idx = np.clip(idx, 0, n - 1)
    # fractional mass in each coarse bin
    out = np.zeros(Nc)
    for k in range(Nc):
        lo = edges[k]; hi = edges[k + 1]
        ilo = idx[k]; ihi = idx[k + 1]
        if ilo == ihi:
            out[k] = (hi - lo)
        else:
            # mass from lo to c[ilo+1] in bin ilo (fractional), full bins, then partial
            seg = 0.0
            # partial in ilo
            binmass = c[ilo + 1] - c[ilo]
            if binmass > 0:
                frac = (c[ilo + 1] - lo) / binmass
                seg += h[ilo] * frac
            # full bins between
            if ihi > ilo + 1:
                seg += np.sum(h[ilo + 1:ihi])
            # partial in ihi
            binmass2 = c[ihi + 1] - c[ihi]
            if binmass2 > 0 and ihi > ilo:
                frac2 = (hi - c[ihi]) / binmass2
                seg += h[ihi] * frac2
            out[k] = seg
    # convert mass to height: each coarse bin has width (1/Nc) in normalized units,
    # original bin width 1/n.  mass = height * width.  So height_c = mass / width_c.
    # width_c / width_orig = (1/Nc)/(1/n) = n/Nc
    out = out * (Nc / n) * (n / Nc)  # placeholder; heights from mass
    # Actually: mass in coarse bin = height_c * (1/Nc).  So height_c = mass * Nc.
    # But mass here is in units of original-bin-width * height.  Original mass per bin = h_i * (1/n).
    # Our c is cumsum(h) which is sum of heights, i.e. mass * n.  So mass = c/n.
    # height_c = mass * Nc = (c/n)*Nc.  Our "out" is in cumsum units (sum of heights).
    # So height_c = out * Nc / n.
    out = out * Nc / n
    return np.clip(out, 0, None)


def _prolong(hc, N):
    """Cumulative-mass interpolation lift from Nc to N."""
    Nc = hc.size
    if Nc >= N:
        return hc[:N].copy()
    c = np.concatenate(([0.0], np.cumsum(hc)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    edges = np.linspace(0.0, total, N + 1)
    idx = np.searchsorted(c, edges, side='right') - 1
    idx = np.clip(idx, 0, Nc - 1)
    out = np.zeros(N)
    for k in range(N):
        lo = edges[k]; hi = edges[k + 1]
        ilo = idx[k]; ihi = idx[k + 1]
        if ilo == ihi:
            out[k] = (hi - lo)
        else:
            binmass = c[ilo + 1] - c[ilo]
            seg = 0.0
            if binmass > 0:
                seg += hc[ilo] * (c[ilo + 1] - lo) / binmass
            if ihi > ilo + 1:
                seg += np.sum(hc[ilo + 1:ihi])
            binmass2 = c[ihi + 1] - c[ihi]
            if binmass2 > 0 and ihi > ilo:
                seg += hc[ihi] * (hi - c[ihi]) / binmass2
            out[k] = seg
    out = out * N / Nc
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    N = best.size
    rng = np.random.default_rng(12345)

    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    def polish(h, fd):
        ht = _lbfgs_all_pos(h, 200, fd)
        r = R_of(ht)
        if r > R_of(h) + 1e-15:
            h = ht
        if time.process_time() < fd - 0.5:
            win = _peak_window(h, tol=0.95, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(h, win, 200, fd)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
        return h

    def try_accept(hcand, tag):
        nonlocal best, bestR
        if hcand is None:
            return False
        r = R_of(hcand)
        if r > bestR + 1e-15:
            best = hcand.copy()
            bestR = r
            print("%s ACCEPT R=%.9f N=%d nearmax5=%.4f top1%%=%.9f"
                  % (tag, bestR, best.size, _nearmax_frac(best),
                     _top_frac_mean(best, 0.01)))
            return True
        print("%s no-gain R=%.9f (best %.9f)" % (tag, r, bestR))
        return False

    # ---- initial band anneal (short) ----
    stages = [(0.01, 0.90), (0.05, 0.95), (0.2, 0.99), (1.0, 0.999)]
    init_deadline = t0 + budget_seconds * 0.20
    per_stage = budget_seconds * 0.04
    for lam, thr in stages:
        if time.process_time() >= init_deadline - 1.0:
            break
        ds = min(init_deadline, time.process_time() + per_stage)
        ht = _lbfgs_band(best, lam, thr, 25, ds)
        try_accept(ht, "init band lam=%.3f thr=%.3f" % (lam, thr))
        fd = min(init_deadline, time.process_time() + per_stage * 0.6)
        hp = polish(best, fd)
        try_accept(hp, "init polish")

    # ---- anytime loop ----
    loop = 0
    while time.process_time() < deadline - 1.0:
        loop += 1
        round_start = time.process_time()

        # (i) shrink-and-prolong at N/2 and N/4
        for div in (2, 4):
            if time.process_time() >= deadline - 1.0:
                break
            Nc = max(64, N // div)
            hc = _coarsen(best, Nc)
            if hc.sum() <= 0:
                continue
            hc = _rescale(hc)
            rc = R_of(hc)
            # short band anneal on coarse
            fd = min(deadline - 1.0, time.process_time() + 3.0)
            hc2 = _lbfgs_band(hc, 0.2, 0.99, 30, fd)
            if R_of(hc2) > rc:
                hc = hc2
            fd = min(deadline - 1.0, time.process_time() + 1.5)
            hc3 = _lbfgs_all_pos(hc, 60, fd)
            if R_of(hc3) > R_of(hc):
                hc = hc3
            # lift back
            hl = _prolong(hc, N)
            hl = _rescale(hl)
            fd = min(deadline - 1.0, time.process_time() + 2.0)
            hl = polish(hl, fd)
            try_accept(hl, "loop %d shrink/%d" % (loop, div))

        # (ii) 3 peak-window polishes
        if time.process_time() < deadline - 1.0:
            Lf = _knots(best)
            c = Lf.max()
            if c > 0:
                am = int(np.argmax(Lf))
                band = np.flatnonzero(Lf >= 0.95 * c)
                if band.size > 0:
                    left = int(band.min())
                    right = int(band.max())
                else:
                    left = right = am
                centers = [am, left, right]
                for ci, ctr in enumerate(centers):
                    if time.process_time() >= deadline - 1.0:
                        break
                    half = max(64, N // (2 * (2 ** ci)))
                    win = _window_around(best, ctr, half)
                    fd = min(deadline - 1.0, time.process_time() + 1.5)
                    hp = _lbfgs_block(best, win, 200, fd)
                    try_accept(hp, "loop %d win%d" % (loop, ci))

        # (iii) randomized asymmetric 2x split
        if time.process_time() < deadline - 1.0:
            e = rng.uniform(-0.2, 0.2, size=N)
            h2 = np.empty(2 * N)
            h2[0::2] = best * (1.0 + e)
            h2[1::2] = best * (1.0 - e)
            h2 = np.clip(h2, 0, None)
            h2 = _rescale(h2)
            fd = min(deadline - 1.0, time.process_time() + 3.0)
            h2p = _lbfgs_all_pos(h2, 80, fd)
            if R_of(h2p) > R_of(h2):
                h2 = h2p
            # fold back by pair averaging
            hf = 0.5 * (h2[0::2] + h2[1::2])
            hf = _rescale(hf)
            fd = min(deadline - 1.0, time.process_time() + 2.0)
            hf = polish(hf, fd)
            try_accept(hf, "loop %d split2x" % loop)

        if time.process_time() - round_start < 0.05:
            # avoid tight spin
            time.sleep(0.01)

    # final polish
    if time.process_time() < deadline - 0.5:
        fd = deadline - 0.3
        hp = polish(best, fd)
        try_accept(hp, "final polish")

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=1e7):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Refinement loop: alternate peak-window local polish with shrinking
    # windows, cycling beta values to break ties and escape plateaus.
    pads = [0.40, 0.30, 0.20, 0.15, 0.10, 0.08, 0.06, 0.05, 0.04, 0.03]
    betas = [1e7, 1e6, 1e5]

    rounds = 0
    while time.process_time() < deadline - 1.0:
        changed = False
        for pad in pads:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            for beta in betas:
                if time.process_time() >= deadline - 0.6:
                    break
                ht = _lbfgs_block(best, win, 200, deadline - 0.4, beta=beta)
                r = R_of(ht)
                if r > bestR + 1e-14:
                    best, bestR = ht.copy(), r
                    changed = True
                    print("round %d pad %.2f beta %.0e R=%.9f" %
                          (rounds, pad, beta, bestR))
                    break
        rounds += 1
        if not changed and rounds > 2:
            # final full-window attempt
            win = _peak_window(best, pad_frac=0.02, extra=64)
            ht = _lbfgs_block(best, win, 300, deadline - 0.4, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
            break

    # Track alternative if best matches start
    if bestR <= startR + 1e-14 and startR > 0:
        alt_best = best.copy()
        alt_bestR = bestR
        best = _rescale(np.asarray(start, dtype=float).copy())
        bestR = startR

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR > 0 and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_log(h0, free, maxiter, deadline):
    """Optimize in log-space over the free set (keeps positivity, better cond.)."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-9 * hmax if hmax > 0 else 1e-9
    u0 = np.log(np.clip(h[active], floor, None))

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth(h, iters=1):
    k = np.array([1.0, 2.0, 1.0]) / 4.0
    out = h
    for _ in range(iters):
        out = np.convolve(out, k, mode='same')
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    print("base R=%.9f N=%d" % (baseR, baseH.size))

    bestH = baseH.copy()
    bestR = baseR

    def _consider(h, tag):
        nonlocal bestH, bestR
        if h is None:
            return bestR
        r = R_of(h)
        if r > bestR + 1e-14:
            bestH, bestR = _rescale(h).copy(), r
            print("  %s -> new best R=%.9f" % (tag, bestR))
        return r

    # Stage 1: full-space L-BFGS polish of start.
    work = bestH.copy()
    cap = min(deadline - 2.0, time.process_time() + 12.0)
    ht = _lbfgs_all_pos(work, 600, cap)
    _consider(ht, "full")
    if R_of(ht) > R_of(work):
        work = ht

    # Stage 2: log-space polish over peak window (robust to tiny heights).
    for pad in (0.30, 0.15, 0.08, 0.04):
        if time.process_time() >= deadline - 2.0:
            break
        win = _peak_window(bestH, pad_frac=pad)
        cap = min(deadline - 1.5, time.process_time() + 5.0)
        hp = _lbfgs_log(bestH, win, 400, cap)
        _consider(hp, "peak-log pad=%.2f" % pad)

    # Stage 3: smoothing-perturbed restarts from best.
    cycle = 0
    while time.process_time() < deadline - 3.0:
        cycle += 1
        hs = _smooth(bestH, iters=1)
        cap = min(deadline - 2.0, time.process_time() + 6.0)
        ht = _lbfgs_all_pos(hs, 400, cap)
        _consider(ht, "smooth+full cyc%d" % cycle)
        if time.process_time() < deadline - 2.5:
            win = _peak_window(hs, pad_frac=0.10)
            cap = min(deadline - 1.5, time.process_time() + 4.0)
            ht2 = _lbfgs_log(hs, win, 300, cap)
            _consider(ht2, "smooth+peak cyc%d" % cycle)

    # Final peak-window polish.
    if time.process_time() < deadline - 1.0:
        win = _peak_window(bestH, pad_frac=0.08)
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        hp = _lbfgs_log(bestH, win, 300, cap)
        _consider(hp, "final peak-log")

    print("final bestR=%.9f baseR=%.9f" % (bestR, baseR))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    return {"best": baseH, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, p=4.0):
    """Soft-max (L^p norm) surrogate on the peak: smoother, avoids peak-locking."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h, 1.0) if p > 1.0 else (1e18, np.zeros(h.size))
    # p-norm surrogate of max
    Lp = np.power(Lf / mx, p)
    Z = Lp.sum()
    sm = mx * np.power(Z, 1.0 / p)
    gLf = -dq / num
    w = np.power(Lf / mx, p - 1.0) / (mx * Z) * (mx / sm) ** p
    # d sm / d Lf = (Lf/mx)^(p-1) / (mx * Z) * sm ... let's do it directly
    # sm = (sum Lf^p)^(1/p) ; d sm/d Lf_i = Lf_i^(p-1) / sm^(p-1)
    # Use exact formula:
    Lp_raw = np.power(Lf, p)
    Zraw = Lp_raw.sum()
    sm2 = np.power(Zraw, 1.0 / p)
    gLf = -dq / num
    gLf += np.power(Lf, p - 1.0) / sm2
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm2)
    return val, grad


def _fun_grad_peak(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun_grad, deadline, maxiter=300, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if free is None:
        active = np.arange(h.size)
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _resample(h, N2):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N2 == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(N2)
    x = np.linspace(0.0, N, N2 + 1)
    cm = np.interp(x, np.arange(N + 1), c)
    h2 = np.diff(cm)
    return np.clip(h2, 0, None)


# ---------- Main driver ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alternatives = []

    # The key idea: the hard part is the peak of f*f being a single sharp point.
    # Use a smooth p-norm surrogate for the max to escape the peak-locking
    # that traps plain max-based gradient ascent.  Then polish with the true max.
    try:
        for p_val, iters in ((8.0, 300), (16.0, 300), (32.0, 250), (64.0, 200), (128.0, 150)):
            if time.process_time() >= deadline - 3.0:
                break
            fg = (lambda hh, pv=p_val: _fun_grad_tie(hh, pv))
            ht = _lbfgs(best, fg, deadline - 3.0, maxiter=iters)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
        print("A psurrogate: R=%.9f" % bestR)
    except Exception as e:
        print("A failed: %s" % e)

    # True-max polish
    try:
        for _ in range(6):
            if time.process_time() >= deadline - 3.0:
                break
            ht = _lbfgs(best, _fun_grad_peak, deadline - 3.0, maxiter=300)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
            else:
                break
        print("B peak: R=%.9f" % bestR)
    except Exception as e:
        print("B failed: %s" % e)

    # Peak-window polish at increasing tightness, alternating surrogate and peak
    try:
        for pad in (0.20, 0.12, 0.08, 0.05, 0.03):
            if time.process_time() >= deadline - 3.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            for p_val in (32.0, 128.0):
                if time.process_time() >= deadline - 3.0:
                    break
                fg = (lambda hh, pv=p_val: _fun_grad_tie(hh, pv))
                ht = _lbfgs(best, fg, deadline - 3.0, maxiter=200, free=win)
                r = R_of(ht)
                if r > bestR + 1e-14:
                    best, bestR = ht.copy(), r
            if time.process_time() >= deadline - 3.0:
                break
            ht = _lbfgs(best, _fun_grad_peak, deadline - 3.0, maxiter=200, free=win)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
        print("C window: R=%.9f" % bestR)
    except Exception as e:
        print("C failed: %s" % e)

    # Upsample and refine (finer resolution), keep best.
    try:
        for factor in (2.0, 1.5, 3.0):
            if time.process_time() >= deadline - 3.0:
                break
            if best.size * factor > 500000:
                continue
            hu = _resample(best, int(best.size * factor))
            hu = _rescale(hu)
            ru = R_of(hu)
            for p_val in (32.0, 128.0):
                if time.process_time() >= deadline - 3.0:
                    break
                fg = (lambda hh, pv=p_val: _fun_grad_tie(hh, pv))
                ht = _lbfgs(hu, fg, deadline - 3.0, maxiter=300)
                r = R_of(ht)
                if r > ru + 1e-14:
                    hu, ru = ht, r
            if time.process_time() < deadline - 3.0:
                ht = _lbfgs(hu, _fun_grad_peak, deadline - 3.0, maxiter=250)
                r = R_of(ht)
                if r > ru + 1e-14:
                    hu, ru = ht, r
            print("D up x%.1f: R=%.9f (N=%d)" % (factor, ru, hu.size))
            if ru > bestR + 1e-14:
                best, bestR = hu.copy(), ru
            elif ru > start_bestR + 1e-14 and hu.size != start_best.size:
                alternatives.append((ru, hu.copy()))
    except Exception as e:
        print("D failed: %s" % e)

    # Final polish loop: surrogate -> peak -> window
    try:
        while time.process_time() < deadline - 0.5:
            moved = False
            for p_val in (64.0, 256.0):
                if time.process_time() >= deadline - 0.5:
                    break
                fg = (lambda hh, pv=p_val: _fun_grad_tie(hh, pv))
                ht = _lbfgs(best, fg, deadline - 0.5, maxiter=200)
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht, r
                    moved = True
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.06, extra=96)
            ht = _lbfgs(best, _fun_grad_peak, deadline - 0.5, maxiter=200, free=win)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht, r
                moved = True
            if not moved:
                break
    except Exception as e:
        print("polish failed: %s" % e)

    print("final R=%.9f (N=%d, start %.9f)" % (bestR, best.size, start_bestR))

    if bestR >= start_bestR - 1e-13:
        if alternatives:
            alternatives.sort(key=lambda x: -x[0])
            alt = alternatives[0][1]
            if alt.size != best.size or not np.allclose(alt, best):
                return {"best": best, "alternative": alt}
        return best
    if alternatives:
        alternatives.sort(key=lambda x: -x[0])
        alt = alternatives[0][1]
        if alternatives[0][0] > start_bestR + 1e-14:
            return {"best": alt, "alternative": start_best}
    return start_best

import numpy as np
import time
import math


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.size == 0:
        return -1.0
    m = L.max()
    if m <= 0:
        return -1.0
    # ||f*f||_2^2 via trapezoid-like exact formula on knots [0, L..., 0]
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    a = Lp[:-1]
    b = Lp[1:]
    l2 = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    return l2 / (l1 * m)


def _rescale(h):
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    s = h.sum()
    if s <= 0:
        return h
    return h * (1.0 / s)


def _trapezoid_target(M, w, r, b):
    t = np.linspace(0.0, 1.0, M)
    g = np.zeros(M)
    lo = 0.5 - 0.5 * w
    hi = 0.5 + 0.5 * w
    for i, x in enumerate(t):
        if x < lo - r or x > hi + r:
            v = 0.0
        elif x < lo:
            v = (x - (lo - r)) / r
        elif x <= hi:
            v = 1.0
        else:
            v = ((hi + r) - x) / r
        g[i] = v
    g = np.maximum(g, 0.0)
    if b != 0.0:
        g = g * (1.0 + b * t)
    return g


def _hann_target(M, w):
    t = np.linspace(0.0, 1.0, M)
    g = np.zeros(M)
    lo = 0.5 - 0.5 * w
    hi = 0.5 + 0.5 * w
    for i, x in enumerate(t):
        if x < lo or x > hi:
            g[i] = 0.0
        else:
            g[i] = 0.5 * (1.0 - math.cos(2.0 * math.pi * (x - lo) / max(hi - lo, 1e-9)))
    return g


def _gs_seed(g, N, iters=20):
    M = g.size
    L = 1
    while L < M:
        L *= 2
    G = np.fft.rfft(g, n=L)
    Fmag = np.sqrt(np.maximum(G.real, 0.0))
    f = np.abs(np.fft.irfft(Fmag, n=L))[:N]
    f = _rescale(f)
    best = f.copy()
    bestR = _R_of(best)
    for _ in range(iters):
        fc = np.maximum(f, 0.0)
        # power spectrum of fc*fc
        conv = np.convolve(fc, fc)
        # pad/truncate to M
        if conv.size < M:
            conv = np.concatenate([conv, np.zeros(M - conv.size)])
        else:
            conv = conv[:M]
        Gc = np.fft.rfft(conv, n=L)
        mag = np.sqrt(np.maximum(Gc.real, 0.0)) + 1e-12
        scale = Fmag / mag
        Gnew = Gc * scale
        fnew = np.abs(np.fft.irfft(Gnew, n=L))[:N]
        fnew = _rescale(fnew)
        f = fnew
        r = _R_of(f)
        if r > bestR:
            bestR = r
            best = f.copy()
    return best, bestR


def _lift(h, factor):
    N = h.size
    M = N * factor
    x = np.linspace(0.0, N, M + 1)
    xi = np.arange(M) * (N / M)
    out = np.interp(xi, np.arange(N) + 0.5, h, left=h[0], right=h[-1])
    return _rescale(out)


def _lbfgs_polish(h, budget_end, max_iter=200):
    try:
        from scipy.optimize import minimize
    except Exception:
        return h, _R_of(h)
    N = h.size
    x0 = np.log(np.maximum(h, 1e-6))
    def obj(x):
        hh = np.exp(x)
        return -_R_of(hh)
    best = h.copy()
    bestR = _R_of(h)
    try:
        res = minimize(obj, x0, method="L-BFGS-B",
                       options={"maxiter": max_iter, "maxfun": max_iter * 3})
        hh = np.exp(res.x)
        r = _R_of(hh)
        if r > bestR:
            bestR = r
            best = _rescale(hh)
    except Exception:
        pass
    return best, bestR


def _peak_window_polish(h, budget_end):
    N = h.size
    L = np.convolve(h, h)
    m = L.max()
    idx = np.where(L >= 0.98 * m)[0]
    if idx.size == 0:
        return h, _R_of(h)
    lo = max(0, idx.min() - 2)
    hi = min(N, idx.max() + 2)
    best = h.copy()
    bestR = _R_of(h)
    # small multiplicative perturbations on the peak window
    for _ in range(30):
        if time.process_time() > budget_end:
            break
        hh = h.copy()
        seg = hh[lo:hi]
        if seg.size == 0:
            continue
        noise = 1.0 + 0.05 * (np.random.rand(seg.size) - 0.5)
        hh[lo:hi] = np.maximum(seg * noise, 0.0)
        hh = _rescale(hh)
        r = _R_of(hh)
        if r > bestR:
            bestR = r
            best = hh
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    N = 4096
    M = 2 * N - 1

    # Build candidate targets
    targets = []
    for w in (0.3, 0.5, 0.7):
        for r in (0.05, 0.1, 0.2):
            for b in (0.0, 0.15):
                targets.append(_trapezoid_target(M, w, r, b))
    for w in (0.3, 0.5, 0.7):
        targets.append(_hann_target(M, w))

    best_seed = None
    best_seed_R = -1.0
    for g in targets:
        if time.process_time() > deadline:
            break
        f, r = _gs_seed(g, N, iters=20)
        if r > best_seed_R:
            best_seed_R = r
            best_seed = f.copy()
    print("seed R = %.6f" % best_seed_R)

    if best_seed is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    best = best_seed
    bestR = best_seed_R

    # Ladder: lift and polish
    cur = best_seed
    curR = bestR
    for factor in (2, 2, 2, 2, 2):
        if time.process_time() > deadline:
            break
        target_N = min(cur.size * factor, 200000)
        if target_N <= cur.size:
            break
        lifted = _lift(cur, target_N // cur.size)
        r = _R_of(lifted)
        # polish
        polished, pr = _lbfgs_polish(lifted, deadline, max_iter=150)
        if pr > r:
            lifted, r = polished, pr
        pw, pwr = _peak_window_polish(lifted, deadline)
        if pwr > r:
            lifted, r = pw, pwr
        if r > curR:
            cur, curR = lifted, r
        if curR > bestR:
            best, bestR = cur.copy(), curR
        print("level N=%d R=%.6f (best %.6f)" % (cur.size, curR, bestR))

    # Final polish loop until deadline
    while time.process_time() < deadline:
        polished, pr = _lbfgs_polish(best, deadline, max_iter=100)
        if pr > bestR:
            best, bestR = polished, pr
        pw, pwr = _peak_window_polish(best, deadline)
        if pwr > bestR:
            best, bestR = pw, pwr
        if pr <= bestR and pwr <= bestR:
            break

    # Compare with start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if _R_of(s) > bestR:
            return s
    print("final R = %.6f N=%d" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _full_lbfgs(h0, deadline, maxiter=150, cvar=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))
    fg = _fun_grad_tie if cvar is None else (lambda hh: _fun_grad_cvar(hh, cvar))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fg(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    return np.clip(np.diff(C2), 0, None)


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    return np.clip(np.diff(C), 0, None)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    sub = h[lo:hi].copy()
    if sub.sum() <= 0:
        return h
    subp = _full_lbfgs(sub, deadline, maxiter=120)
    out = h.copy()
    out[lo:hi] = subp
    return _rescale(out)


def _near_max_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= mx * 0.999)),
            float(np.mean(Lf >= mx * 0.99)),
            float(np.mean(Lf >= mx * 0.95)))


def _split_pass(h, deadline, rng):
    N = h.size
    if N * 2 > 900000:
        return h
    eps = rng.uniform(-0.15, 0.15, size=N)
    h2 = np.empty(2 * N)
    h2[0::2] = h * (1.0 + eps)
    h2[1::2] = h * (1.0 - eps)
    h2 = _rescale(np.clip(h2, 0, None))
    hp = _full_lbfgs(h2, deadline, maxiter=100)
    hf = _rescale(_fold_back(hp, N))
    return hf


def _sparsify_keep_fraction(h, f):
    """Zero the smallest heights so that fraction f of cells remain active."""
    N = h.size
    keep = max(2, int(round(f * N)))
    if keep >= N:
        return h.copy()
    idx = np.argsort(h)
    out = h.copy()
    out[idx[:N - keep]] = 0.0
    return out


def _sparsify_soft(h, tau):
    """Soft threshold: h <- max(h - tau*mean(h), 0)."""
    m = h.mean()
    return np.clip(h - tau * m, 0, None)


def _sparsity_phase(best_h, bestR, deadline, rng):
    """Try sparsification variants; return (h, R, label) of best improvement or None."""
    if time.process_time() >= deadline - 1.0:
        return None
    N = best_h.size
    # Cap candidate N for speed
    if N > 13124:
        hbase = _rescale(_fold_back(best_h, 13124))
    else:
        hbase = best_h.copy()
    baseR = R_of(hbase)
    best_local = None

    variants = []
    for f in (0.9, 0.8, 0.7, 0.6, 0.5):
        variants.append(('f', f))
    for tau in (0.1, 0.3, 0.6, 1.0):
        variants.append(('tau', tau))

    for kind, val in variants:
        if time.process_time() >= deadline - 1.0:
            break
        if kind == 'f':
            hs = _sparsify_keep_fraction(hbase, val)
            label = "f=%.2f" % val
        else:
            hs = _sparsify_soft(hbase, val)
            label = "tau=%.2f" % val
        if hs.sum() <= 0:
            continue
        hs = _rescale(hs)
        zfrac = float(np.mean(hs <= 0))
        # Polish on active cells only
        hp = _full_lbfgs(hs, deadline, maxiter=80)
        rp = R_of(hp)
        # Revive pass: set zeroed cells to 1e-4*max and re-polish all
        if time.process_time() < deadline - 1.0:
            hr = hp.copy()
            z = hr <= 0
            if np.any(z):
                hr[z] = 1e-4 * hr.max()
                hr = _rescale(hr)
                hr = _full_lbfgs(hr, deadline, maxiter=80)
                rr = R_of(hr)
                if rr > rp:
                    hp, rp = hr, rr
        zfinal = float(np.mean(hp <= 0))
        print("  sparsity %s: zero %.3f -> R=%.9f (zero after %.3f, base %.9f)"
              % (label, zfrac, rp, zfinal, baseR))
        if rp > baseR + 1e-9:
            if best_local is None or rp > best_local[1]:
                best_local = (hp, rp, label)

    if best_local is not None and best_local[1] > bestR + 1e-9:
        return best_local
    return None


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(0xC0FFEE)

    start_h = None
    startR = 0.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            start_h = _rescale(s)
            startR = R_of(start_h)

    if start_h is None:
        N0 = 3281
        h = np.ones(N0)
        h = _rescale(h)
        start_h = h
        startR = R_of(h)

    N0 = start_h.size

    best_h = start_h.copy()
    bestR = startR
    bestN = N0

    if time.process_time() < deadline - 2.0:
        hp = _full_lbfgs(best_h, deadline, maxiter=200)
        rp = R_of(hp)
        if rp > bestR:
            best_h, bestR = hp, rp
        print("init R=%.9f (start %.9f, N=%d)" % (bestR, startR, best_h.size))

    N_levels = [N0, N0 * 2, N0 * 4]
    q_ladder = [0.999, 0.995, 0.99, 0.98, 0.95]

    loop = 0
    while time.process_time() < deadline - 1.0:
        loop += 1
        improved = False

        # (ii) N-loop with CVaR ladder + tie polish + peak-window polish
        for Nt in N_levels:
            if time.process_time() >= deadline - 1.0:
                break
            if Nt > 900000:
                continue
            if Nt == best_h.size:
                cand = best_h.copy()
            else:
                cand = _rescale(_lift_mass_preserving(best_h, Nt))
            for q in q_ladder:
                if time.process_time() >= deadline - 1.0:
                    break
                hc = _full_lbfgs(cand, deadline, maxiter=60, cvar=q)
                rc = R_of(hc)
                if rc > R_of(cand):
                    cand = hc
            if time.process_time() < deadline - 1.0:
                ht = _full_lbfgs(cand, deadline, maxiter=120)
                if R_of(ht) > R_of(cand):
                    cand = ht
            if time.process_time() < deadline - 1.0:
                hw = _peak_window_polish(cand, deadline)
                if R_of(hw) > R_of(cand):
                    cand = hw
            rc = R_of(cand)
            if rc > bestR + 1e-12:
                best_h, bestR, bestN = cand, rc, cand.size
                improved = True
                sh = _near_max_shares(best_h)
                print("loop %d N=%d R=%.9f shares %.3f/%.3f/%.3f"
                      % (loop, bestN, bestR, sh[0], sh[1], sh[2]))

        # (iii) split pass at best N
        if time.process_time() < deadline - 1.5:
            hs = _split_pass(best_h, deadline, rng)
            rs = R_of(hs)
            if rs > bestR + 1e-12:
                best_h, bestR = hs, rs
                improved = True
                print("loop %d split R=%.9f" % (loop, bestR))

        # (iv) NEW: sparsity phase on current best
        if time.process_time() < deadline - 1.5:
            res = _sparsity_phase(best_h, bestR, deadline, rng)
            if res is not None:
                best_h, bestR, label = res
                improved = True
                sh = _near_max_shares(best_h)
                print("loop %d sparsity(%s) R=%.9f shares %.3f/%.3f/%.3f"
                      % (loop, label, bestR, sh[0], sh[1], sh[2]))

        if not improved:
            if time.process_time() < deadline - 2.0:
                hpert = best_h * (1.0 + rng.uniform(-0.02, 0.02, size=best_h.size))
                hpert = _rescale(np.clip(hpert, 0, None))
                hp = _full_lbfgs(hpert, deadline, maxiter=80)
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best_h, bestR = hp, rp
                    improved = True
                    print("loop %d perturb R=%.9f" % (loop, bestR))
            if not improved:
                break

    if time.process_time() < deadline - 0.5:
        hf = _full_lbfgs(best_h, deadline, maxiter=200)
        rf = R_of(hf)
        if rf > bestR:
            best_h, bestR = hf, rf

    if bestR < startR:
        best_h, bestR = start_h, startR

    print("final R=%.12f (start %.12f, N=%d, loops=%d, zeros=%.3f)"
          % (bestR, startR, best_h.size, loop, float(np.mean(best_h <= 0))))

    result = {"best": best_h}
    if best_h.size != start_h.size:
        result["alternative"] = start_h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    x = np.linspace(0, n - 1, m)
    return np.interp(x, np.arange(n), h)


def _lift_mass(h, N2):
    """Mass-preserving lift using linear interpolation of cumulative mass."""
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.clip(np.diff(C2), 0, None)
    return h2


def _refine(h, deadline, rounds=8):
    best = h.copy()
    bestR = R_of(best)
    for k in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 0.5, time.process_time() + 4.0), tie=True)
        rp = R_of(pol)
        if rp > bestR:
            best, bestR = pol, rp
        if time.process_time() < deadline - 1.0:
            for beta in (50.0, 300.0, 2000.0):
                if time.process_time() >= deadline - 0.6:
                    break
                pb = _lbfgs_block(best, np.arange(best.size), 200,
                                 min(deadline - 0.4, time.process_time() + 3.0),
                                 beta=beta)
                rb = R_of(pb)
                if rb > bestR:
                    best, bestR = pb, rb
        if time.process_time() < deadline - 1.0:
            win = _peak_window(best)
            pw = _lbfgs_block(best, win, 200,
                              min(deadline - 0.5, time.process_time() + 2.0), tie=True)
            rw = R_of(pw)
            if rw > bestR:
                best, bestR = pw, rw
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: refine at current resolution
    if time.process_time() < deadline - 2.0:
        d1 = min(deadline - 1.0, t0 + budget_seconds * 0.30)
        best, bestR = _refine(best, d1, rounds=8)
        print("after refine R=%.7f" % bestR)

    # Phase 2: alternate mass-preserving upsample and refine
    # Key idea: mass-preserving lift keeps ||f*f||_1 unchanged, giving a better
    # starting point for finer optimization than naive linear interpolation.
    factor = 2
    while time.process_time() < deadline - 5.0 and best.size * factor <= 900_000:
        # try both lift methods, pick better after short refine
        up_mass = _rescale(_lift_mass(best, best.size * factor))
        up_lin = _rescale(_upsample(best, factor))
        rm = R_of(up_mass)
        rl = R_of(up_lin)
        up = up_mass if rm >= rl else up_lin
        upR = R_of(up)
        if upR <= 0:
            break
        remaining = deadline - time.process_time()
        d2 = min(deadline - 1.0, time.process_time() + remaining * 0.55)
        cand, candR = _refine(up, d2, rounds=5)
        print("upsample x%d -> N=%d R=%.7f" % (factor, cand.size, candR))
        if candR > bestR + 1e-10:
            best, bestR = cand, candR
        if time.process_time() > deadline - 8.0:
            break
        factor = 2

    # Phase 3: final intensive refine
    if time.process_time() < deadline - 0.5:
        best, bestR = _refine(best, deadline, rounds=12)

    # Phase 4: last peak polish
    if time.process_time() < deadline - 0.4:
        win = _peak_window(best)
        pw = _lbfgs_block(best, win, 300, deadline - 0.2, tie=True)
        rw = R_of(pw)
        if rw > bestR + 1e-13:
            best, bestR = pw, rw

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, free, maxiter, deadline, beta=0.0):
    """Optimise heights of `free` indices in log-space (keeps positivity)."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad
    hmax = h.max()
    floor = 1e-14 * hmax if hmax > 0 else 1e-14
    u0 = np.log(np.clip(h[active], floor, None))

    def f(u):
        hh = h.copy()
        vals = np.exp(np.clip(u, -40.0, 40.0))
        hh[active] = vals
        val, g = fg(hh)
        return val, g[active] * vals

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    return _lbfgs_log(h0, np.arange(h0.size), maxiter, deadline, beta=beta)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=150, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_log(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _upsample(h, factor):
    """Interpolate heights onto a finer grid (linear resample)."""
    n = h.size
    m = n * factor
    x = (np.arange(m) + 0.5) / factor - 0.5
    x = np.clip(x, 0, n - 1)
    i0 = np.floor(x).astype(int)
    i1 = np.minimum(i0 + 1, n - 1)
    t = x - i0
    return (1 - t) * h[i0] + t * h[i1]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: higher-order upsampling with log-space polishing, then
    # shrinking down to a coarser grid that can be polished more precisely.
    for factor in (2, 2):
        N = best.size
        if N * factor > 900000:
            break
        if time.process_time() >= deadline - 2.0:
            break
        up = _rescale(_upsample(best, factor))
        r_up = R_of(up)
        print("upsample x%d R=%.7f (N=%d)" % (factor, r_up, up.size))
        ht = _lbfgs_all_pos(up, 500, deadline - 1.5, beta=0.0)
        r = R_of(ht)
        if r > r_up:
            up, r_up = ht, r
        print("upsample refined R=%.7f" % r_up)
        if r_up > bestR + 1e-12:
            best, bestR = up.copy(), r_up

    N = best.size

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 800, deadline - 2.0, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 2.0:
            ht = _lbfgs_all_pos(best, 300, deadline - 2.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        for (frac, extra, beta) in [(0.05, 64, 1e7), (0.10, 64, 1e8),
                                    (0.25, 128, 1e8), (0.40, 256, 1e8)]:
            if time.process_time() >= deadline - 2.0:
                break
            ht = _window_polish_peak(best, deadline - 2.0, frac, extra,
                                     maxiter=300, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
        Lf = _knots(best)
        am = int(np.argmax(Lf))
        print("cycle %d R=%.7f zeros=%.1f%% argmax=%d/%d"
              % (cycle, bestR, 100.0 * np.mean(best <= 0), am, N))
        if cycle >= 3:
            break

    # Final sharp polishes
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 3000, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 2000, deadline - 0.2)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    if best.size != start_best.size and bestR > start_bestR - 1e-6:
        return {"best": start_best, "alternative": best}
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_dinkel(h, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    dmax = np.zeros_like(Lf)
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    dmax[idx] = 1.0 / idx.size
    dD = 2.0 * s * mx * np.ones_like(h) + s * s * _backprop(dmax, h)
    dnum = _backprop(dq, h)
    grad = dnum - lam * dD
    val = -(num - lam * s * s * mx) / max(num, 1e-300)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _coarsen(h, c):
    n = h.size
    m = (n + c - 1) // c
    pad = m * c - n
    if pad > 0:
        hp = np.concatenate([h, np.zeros(pad)])
    else:
        hp = h
    return hp.reshape(m, c).sum(axis=1)


def _lift(hc, n):
    c = (n + hc.size - 1) // hc.size
    out = np.repeat(hc / c, c)
    if out.size > n:
        out = out[:n]
    elif out.size < n:
        out = np.concatenate([out, np.zeros(n - out.size)])
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    N = best.size
    print("base R=%.12f (N=%d)" % (bestR, N))

    # Coarse V-cycle: coarsen -> optimize coarse -> lift -> full polish -> peak polish
    factors = [2, 4, 8]
    cyc = 0
    while time.process_time() < deadline - 1.0:
        cyc += 1
        improved = False
        for c in factors:
            if time.process_time() >= deadline - 1.0:
                break
            ncoarse = (N + c - 1) // c
            if ncoarse < 16:
                continue
            hc = _coarsen(best, c)
            # coarse optimize ~1.5s
            tlim = min(deadline - 1.0, time.process_time() + 1.5)
            hc_opt = _lbfgs_custom(hc, _fun_grad_tie, tlim, maxiter=200)
            rc_coarse = R_of(hc_opt)
            # lift to full N
            hlift = _lift(hc_opt, N)
            # full-N polish ~3s
            if time.process_time() < deadline - 1.0:
                tlim2 = min(deadline - 1.0, time.process_time() + 3.0)
                hlift = _full_lbfgs(hlift, tlim2, maxiter=200)
            # peak polish ~1.5s
            if time.process_time() < deadline - 1.0:
                tlim3 = min(deadline - 1.0, time.process_time() + 1.5)
                hlift = _peak_window_polish(hlift, tlim3, pad=3)
            rlift = R_of(hlift)
            print("cyc=%d c=%d coarseR=%.12f liftedR=%.12f (best %.12f)"
                  % (cyc, c, rc_coarse, rlift, bestR))
            if rlift > bestR + 1e-10:
                best = hlift
                bestR = rlift
                improved = True
        if not improved and cyc > 3:
            # try a dinkel/cvar nudge to escape
            if time.process_time() < deadline - 1.0:
                tlim = min(deadline - 1.0, time.process_time() + 3.0)
                hc = _lbfgs_custom(best, lambda hh: _fun_grad_dinkel(hh, bestR),
                                   tlim, maxiter=150)
                if time.process_time() < deadline - 1.0:
                    tlim2 = min(deadline - 1.0, time.process_time() + 2.0)
                    hc = _full_lbfgs(hc, tlim2, maxiter=150)
                rc = R_of(hc)
                print("cyc=%d dinkel R=%.12f (best %.12f)" % (cyc, rc, bestR))
                if rc > bestR + 1e-10:
                    best = hc
                    bestR = rc

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best, "alternative": best.copy()}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_softmax(h, beta):
    """Smooth max via logsumexp-ish: penalise via softmax weights over top knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - mx)
    w = np.exp(z)
    w /= w.sum()
    # soft max approx: 1/beta * log(sum exp(beta L)) - but we use weighted mean as proxy
    soft = float(np.sum(w * Lf))
    if soft <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    # d/dh of log(soft) with soft = sum w L: treat w as constant (approx)
    gLf += w / soft
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(soft)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, fun_grad, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.flatnonzero(h > 1e-14)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def _project_tangent(v):
    if v.size == 0:
        return v
    return v - v.mean()


def _newton_cg(h, deadline, max_outer=15):
    h = _rescale(np.clip(h, 0, None))
    Rcur = R_of(h)
    best = h.copy()
    bestR = Rcur
    for outer in range(max_outer):
        if time.process_time() >= deadline - 1.0:
            break
        active = np.flatnonzero(h > 1e-12)
        if active.size < 2:
            break
        val, g = _fun_grad_tie(h)
        gA = _project_tangent(g[active].copy())
        gnorm = float(np.linalg.norm(gA))
        if gnorm < 1e-12:
            break
        hA = h[active].copy()
        hnorm = float(np.linalg.norm(hA)) + 1e-30

        def Hv(v):
            v = _project_tangent(v)
            vnorm = float(np.linalg.norm(v))
            if vnorm < 1e-30:
                return np.zeros_like(v)
            eps = 1e-6 * hnorm / vnorm
            hp = h.copy(); hp[active] = np.clip(hA + eps * v, 0.0, None)
            hm = h.copy(); hm[active] = np.clip(hA - eps * v, 0.0, None)
            _, gp = _fun_grad_tie(hp)
            _, gm = _fun_grad_tie(hm)
            return _project_tangent((gp[active] - gm[active]) / (2.0 * eps))

        delta = max(1e-3 * hnorm, 1e-6)
        x = np.zeros_like(gA)
        r = -gA.copy()
        p = r.copy()
        rr = float(r @ r)
        tol = min(0.5, np.sqrt(gnorm)) * gnorm
        for it in range(min(150, active.size)):
            if time.process_time() >= deadline - 0.8:
                break
            if np.sqrt(rr) < tol:
                break
            Hp = Hv(p)
            pHp = float(p @ Hp)
            if pHp <= 1e-14 * (float(p @ p) + 1e-30):
                pp = float(p @ p)
                if pp > 1e-30:
                    x = x + np.sqrt(delta * delta / pp) * p
                break
            alpha = rr / pHp
            xnew = x + alpha * p
            if float(xnew @ xnew) > delta * delta:
                pp = float(p @ p); xp = float(x @ p)
                disc = xp * xp + pp * (delta * delta - float(x @ x))
                if disc < 0:
                    disc = 0.0
                x = x + ((-xp + np.sqrt(disc)) / (pp + 1e-30)) * p
                break
            x = xnew
            r = r - alpha * Hp
            rr_new = float(r @ r)
            p = r + (rr_new / (rr + 1e-30)) * p
            rr = rr_new

        step = x
        if float(np.linalg.norm(step)) < 1e-14:
            step = -gA / (gnorm + 1e-30) * min(1e-3 * hnorm, delta)

        accepted = False
        for ls in range(25):
            if time.process_time() >= deadline - 0.8:
                break
            t = 0.5 ** ls
            htry = h.copy()
            htry[active] = np.clip(hA + t * step, 0.0, None)
            htry = _rescale(htry)
            rtry = R_of(htry)
            if rtry > Rcur + 1e-15:
                h = htry; Rcur = rtry; accepted = True
                if Rcur > bestR:
                    best = h.copy(); bestR = Rcur
                break
        if not accepted:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    alt_best = None
    altR = -1.0
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Softmax approach: smooth the max to escape kinks ----
    # The tie gradient is piecewise; softmax with moderate beta lets the optimizer
    # find a slightly better "spread" of the max plateau.
    if time.process_time() < deadline - 6.0:
        sm_deadline = min(deadline - 4.0,
                          time.process_time() + budget_seconds * 0.35)
        best_sm = best.copy(); best_smR = bestR
        for beta_scale in (1e4, 3e4, 1e5, 3e5, 1e6):
            if time.process_time() >= sm_deadline:
                break
            beta = beta_scale / max(_knots(best).max(), 1e-30)
            fg = lambda hh, b=beta: _fun_grad_softmax(hh, b)
            tlim = min(sm_deadline, time.process_time() + 2.5)
            cand = _lbfgs_block(best_sm, fg, 200, tlim)
            r = R_of(cand)
            if r > best_smR + 1e-15:
                best_sm, best_smR = cand.copy(), r
        if best_smR > bestR + 1e-15:
            best, bestR = best_sm.copy(), best_smR
        elif best_smR > altR and best_sm.size != best.size:
            alt_best, altR = best_sm.copy(), best_smR

    # ---- Newton-CG on active support ----
    if time.process_time() < deadline - 6.0:
        ncg_deadline = min(deadline - 4.0,
                           time.process_time() + budget_seconds * 0.3)
        nh, nR = _newton_cg(best, ncg_deadline, max_outer=15)
        if nR > bestR + 1e-15:
            best, bestR = nh.copy(), nR
        elif nR > altR and nh.size != best.size:
            alt_best, altR = nh.copy(), nR

    # ---- Multi-scale tie polish ----
    for Q in (8, 4, 2, 1):
        if time.process_time() >= deadline - 4.0:
            break
        if best.size % Q != 0:
            continue
        qh = best if Q == 1 else _coarsen(best, Q)
        if qh is None or qh.size < 32:
            continue
        qh = _rescale(qh)
        tlim = min(deadline - 3.5, time.process_time() + 2.0)
        cand = _lbfgs_block(qh, _fun_grad_tie, 200, tlim)
        ph = cand if Q == 1 else _prolongate(cand, Q)
        pr = R_of(ph)
        if pr > bestR + 1e-15:
            best, bestR = ph.copy(), pr
        if pr > altR and ph.size != best.size:
            alt_best, altR = ph.copy(), pr

    # ---- Final polish ----
    while time.process_time() < deadline - 0.8:
        pol = _lbfgs_block(best, _fun_grad_tie, 300,
                           min(deadline - 0.4, time.process_time() + 3.0))
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        else:
            break

    if bestR < startR:
        best = start_best
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if (alt_best is not None and alt_best.size <= 1000000
            and alt_best.size != best.size and altR > 0):
        result["alternative"] = alt_best
    return result

