    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_kappa(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    tol = 1e-12 * M
    tie = Lf >= (M - tol)
    Mtie = Lf[tie].mean()
    B = Lf >= tau * M
    nB = int(B.sum())
    if nB == 0:
        return _fun_grad(h)
    u = (Lf[B] - M) / M
    pen = kappa * np.mean(u * u)
    gpen = np.zeros_like(Lf)
    gpen[B] = kappa * (2.0 / nB) * (u / M)
    gLf = -dq / num + gpen
    gLf[tie] += (1.0 / Mtie) / tie.sum()
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Mtie) + pen
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    tol = 1e-12 * M
    tie = Lf >= (M - tol)
    Mtie = Lf[tie].mean()
    gLf = -dq / num
    gLf[tie] += (1.0 / Mtie) / tie.sum()
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Mtie)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_kappa(h0, tau, kappa, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        return _fun_grad_kappa(np.clip(x, 0.0, None), tau, kappa)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_tie(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        return _fun_grad_tie(np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _near_max_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _gauss_smooth(h, sigma):
    if sigma <= 0:
        return h
    rad = int(3 * sigma) + 1
    x = np.arange(-rad, rad + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    pad = np.concatenate((np.zeros(rad), h, np.zeros(rad)))
    out = np.convolve(pad, k, mode='valid')
    return out


def _refine(h, deadline, budget):
    """Given a candidate h, run a short beta-ladder + peak polish. Return (h,R)."""
    ht = h
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 250, deadline - 0.3, beta=beta)
    if time.process_time() < deadline - 0.5:
        win = _peak_window(ht, pad_frac=0.12, extra=128)
        ht2 = _lbfgs_block(ht, win, 400, deadline - 0.3, beta=1e7)
        if R_of(ht2) > R_of(ht):
            ht = ht2
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(ht, 250, deadline - 0.3, beta=0.0)
    return ht, R_of(ht)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(h, r, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if r > bestR + 1e-14:
            best, bestR, origin = h.copy(), r, tag
            print("NEW BEST R=%.9f origin=%s" % (bestR, origin))
        elif r > alt_bestR and r < bestR - 1e-14:
            alt_best, alt_bestR = h.copy(), r

    # ---- Phase 0: kappa ladder ----
    ladder = [(0.95, 300.0), (0.90, 1000.0), (0.85, 3000.0),
              (0.80, 10000.0), (0.75, 30000.0)]
    kappa_best = best.copy()
    kappa_bestR = bestR
    for (tau, kappa) in ladder:
        if time.process_time() >= deadline - 8.0:
            break
        rung_deadline = min(deadline - 6.0, time.process_time() + 4.0)
        ht = _lbfgs_kappa(kappa_best, tau, kappa, 80, rung_deadline)
        tie_deadline = min(deadline - 5.0, time.process_time() + 1.5)
        ht2 = _lbfgs_tie(ht, 40, tie_deadline)
        r2 = R_of(ht2)
        if r2 > kappa_bestR + 1e-14:
            kappa_best, kappa_bestR = ht2.copy(), r2
            print("kappa tau=%.2f k=%.0f R=%.9f NEW" % (tau, kappa, r2))
        else:
            consider(ht2, r2, 'kappa%.2f' % tau)
            consider(ht, R_of(ht), 'kappa_raw%.2f' % tau)

    consider(kappa_best, kappa_bestR, 'kappa_ladder')

    # ---- Phase 0b: full-N tie ----
    if time.process_time() < deadline - 8.0:
        tie_deadline = min(deadline - 6.0, time.process_time() + 8.0)
        ht = _lbfgs_tie(best, 200, tie_deadline)
        consider(ht, R_of(ht), origin + '+tie')

    # ---- Phase 0c: peak polishes ----
    for pad in [0.05, 0.03]:
        if time.process_time() >= deadline - 4.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        slice_deadline = min(deadline - 2.0, time.process_time() + 3.0)
        ht2 = _lbfgs_block(best, win, 400, slice_deadline, beta=1e7)
        consider(ht2, R_of(ht2), origin + '+pk%.2f' % pad)

    # ---- Phase 1: half-resolution polish ----
    N = best.size
    best_c = None
    best_cR = -1.0
    half_deadline = t0 + budget_seconds * 0.72
    if N % 2 == 0 and N >= 4 and time.process_time() < half_deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        consider(ht, R_of(ht), 'lift+ladder')

    # ---- Phase 2: smoothing perturbations ----
    if time.process_time() < deadline - 6.0:
        sigmas = [0.6, 1.2, 2.0, 3.0, 1.8, 0.9]
        si = 0
        while time.process_time() < deadline - 5.0:
            sigma = sigmas[si % len(sigmas)]
            si += 1
            hs = _rescale(_gauss_smooth(best, sigma))
            slice_deadline = min(deadline - 2.0,
                                 time.process_time() + 0.05 * budget_seconds)
            ht, r = _refine(hs, slice_deadline, budget_seconds)
            consider(ht, r, 'smooth%d' % si)

    # ---- Phase 3: perturb-then-polish restarts on half-res ----
    restarts_done = 0
    if best_c is not None and time.process_time() < deadline - 4.0:
        rng = np.random.default_rng(7)
        amps = [0.008, 0.015, 0.03, 0.05]
        ri = 0
        while time.process_time() < deadline - 4.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc2 = best_c.copy()
            nz = cc2 > 0
            if nz.sum() == 0:
                break
            cc2[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc2 = _rescale(cc2)
            r0 = R_of(cc2)
            slice_deadline = min(deadline - 2.0,
                                 time.process_time() + 0.04 * budget_seconds)
            work_c2, cand_c, cand_cR, org = _half_cycle(
                cc2, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.15])
            restarts_done += 1
            if cand_cR > best_cR + 1e-12:
                best_c = cand_c.copy()
                best_cR = cand_cR
                print("restart %d amp=%.3f ACCEPT R(c)=%.9f" %
                      (ri, amp, best_cR))
            if time.process_time() >= deadline - 4.0:
                break

    # ---- Phase 4: lift best_c and polish ----
    if best_c is not None:
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        consider(ht, R_of(ht), origin + '+full')

    # ---- Phase 5: fine peak polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            consider(ht2, R_of(ht2), origin + '+pk')

    f01, f1, f5 = _near_max_fracs(best)
    print("restarts=%d best_c=%.9f best_full=%.9f" %
          (restarts_done, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f, "
          "near-max 0.1%%=%.4f 1%%=%.4f 5%%=%.4f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best),
           f01, f1, f5))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _make_fg(kind, param):
    if kind == 'tie':
        return _fun_grad_tie
    if kind == 'beta':
        return lambda hh: _fun_grad_beta(hh, param)
    if kind == 'cvar':
        return lambda hh: _fun_grad_cvar(hh, param)
    return _fun_grad_tie


def _lbfgs_log(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _restrict(h, f, o):
    n = h.size
    hr = np.roll(h, -o)
    m = n // f
    hr = hr[:m * f]
    return hr.reshape(m, f).mean(axis=1)


def _prolong(hc, f, o, n):
    up = np.repeat(hc, f)
    if up.size < n:
        up = np.concatenate((up, np.full(n - up.size, up[-1] if up.size else 0.0)))
    else:
        up = up[:n]
    return np.roll(up, o)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, int(idx.min()) - 1)
    hi = min(h.size - 1, int(idx.max()))
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR
    n = baseH.size
    fg_tie = _fun_grad_tie

    def try_cycle(h_cur, f, o, time_cap, fg):
        if time.process_time() >= time_cap - 0.5:
            return h_cur, R_of(h_cur)
        hc = _restrict(h_cur, f, o)
        if hc.size < 8:
            return h_cur, R_of(h_cur)
        hc = _rescale(hc)
        rc0 = R_of(hc)
        cap = min(time_cap - 0.3, time.process_time() + 5.0)
        hc = _lbfgs_log(hc, 350, cap, fg)
        rc = R_of(hc)
        hp = _prolong(hc, f, o, n)
        hp = _rescale(hp)
        rp = R_of(hp)
        cap = min(time_cap - 0.2, time.process_time() + 3.0)
        hp = _lbfgs_log(hp, 250, cap, fg)
        rp2 = R_of(hp)
        cap = min(time_cap - 0.2, time.process_time() + 2.0)
        hp = _lbfgs_log(hp, 150, cap, fg_tie)
        rp3 = R_of(hp)
        print("  f=%d o=%d: coarse %.9f -> %.9f | prolong %.9f -> %.9f -> %.9f" %
              (f, o, rc0, rc, rp, rp2, rp3))
        return hp, rp3

    # Phase 1: local block polish on peak window with tie-aware gradient
    if time.process_time() < deadline - 5.0:
        w = _peak_window(bestH)
        cap = min(deadline - 2.0, time.process_time() + 4.0)
        hp = _lbfgs_block(bestH, w, 200, cap, fg_tie)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            print("  peak-window polish improved: R=%.9f" % bestR)

    # Phase 2: multigrid cycles with tie-aware gradient and beta smoothing,
    # plus finer factors (f=4,8) for deeper refinement.
    scan_cap = min(deadline, t0 + budget_seconds * 0.60)
    results = {}
    fgs = [('tie', None), ('beta', 200.0), ('beta', 800.0)]
    for f in (2, 3, 4, 8):
        for o in range(f):
            for kind, param in fgs:
                if time.process_time() >= scan_cap - 1.0:
                    break
                fg = _make_fg(kind, param)
                hp, rp = try_cycle(bestH, f, o, scan_cap, fg)
                key = (f, o, kind, param)
                results[key] = (hp, rp)
                if rp > bestR + 1e-14:
                    bestH, bestR = hp.copy(), rp
                    print("  >>> new best from %s: R=%.9f" % (str(key), bestR))

    if results:
        best_key = max(results.keys(), key=lambda k: results[k][1])
    else:
        best_key = (2, 0, 'tie', None)
    print("selected %s with R=%.9f" % (str(best_key), results.get(best_key, (None, bestR))[1]))

    # Phase 3: alternate best cycle with peak-window block polish
    round_i = 0
    while time.process_time() < deadline - 2.0:
        round_i += 1
        improved = False
        f, o, kind, param = best_key
        fg = _make_fg(kind, param)
        hp, rp = try_cycle(bestH, f, o, deadline - 1.0, fg)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            improved = True
            print("  round %d cycle improved: R=%.9f" % (round_i, bestR))
        if time.process_time() < deadline - 2.0:
            w = _peak_window(bestH)
            cap = min(deadline - 1.0, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, w, 200, cap, fg_tie)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                improved = True
                print("  round %d window improved: R=%.9f" % (round_i, bestR))
        if not improved and time.process_time() > deadline - 6.0:
            break

    # Final full polish
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.5)
        hs = _lbfgs_log(bestH, 200, cap, fg_tie)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    mx, m, near = _stats(bestH)
    print("final N=%d R=%.9f zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestH.size, bestR, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        alt = baseH
        if results:
            k = max(results.keys(), key=lambda k: results[k][1])
            rk = results[k][1]
            if rk > baseR + 1e-12:
                alt = results[k][0]
        return {"best": baseH, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return _fun_grad(h)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _fun_grad_band(h, lam, thr):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return _fun_grad(h)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)

    B = np.flatnonzero(Lf >= thr * c)
    if B.size > 0:
        diff = c - Lf[B]
        val += lam * np.mean(diff * diff) / (c * c)
        gLf[B] -= 2.0 * lam * diff / (B.size * c * c)

    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_band(h0, lam, thr, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_band(hh, lam, thr)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


# ---- Square parameterization: h = v^2, unconstrained v ----

def _lbfgs_square_tie(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    v0 = np.sqrt(h)
    n = v0.size

    def f(v):
        hh = v * v
        val, g = _fun_grad_tie(hh)
        return val, 2.0 * v * g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, v0, jac=True, method='L-BFGS-B',
                       bounds=[(-np.inf, np.inf)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(res.x * res.x)


def _lbfgs_square_band(h0, lam, thr, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    v0 = np.sqrt(h)
    n = v0.size

    def f(v):
        hh = v * v
        val, g = _fun_grad_band(hh, lam, thr)
        return val, 2.0 * v * g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, v0, jac=True, method='L-BFGS-B',
                       bounds=[(-np.inf, np.inf)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(res.x * res.x)


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def _band_stats(h, thr):
    Lf = _knots(h)
    c = Lf.max()
    if c <= 0:
        return 0, 0.0
    B = Lf[Lf >= thr * c]
    if B.size == 0:
        return 0, 0.0
    return B.size, float(np.std(B) / c)


def _zero_revival_kick(h, frac=0.05):
    """Set small h_i to sqrt(1e-4*hmax) on cells nearest the f*f argmax window."""
    h = h.copy()
    hmax = h.max()
    if hmax <= 0:
        return h
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    # window in h-index space: knots index m corresponds to h index m-1
    n = h.size
    win = max(8, n // 20)
    lo = max(0, m - 1 - win)
    hi = min(n, m - 1 + win)
    small = np.flatnonzero(h < 1e-8 * hmax)
    if small.size == 0:
        return h
    # prefer small cells inside the peak window
    inside = small[(small >= lo) & (small < hi)]
    target = inside if inside.size > 0 else small
    k = max(1, int(frac * target.size))
    # nearest to argmax
    dist = np.abs(target - (m - 1))
    order = np.argsort(dist)[:k]
    h[target[order]] = np.sqrt(1e-4 * hmax)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    def polish_h(h, fd):
        ht = _lbfgs_all_pos(h, 200, fd)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
        if time.process_time() < fd - 0.5:
            win = _peak_window(h, tol=0.95, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(h, win, 200, fd)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
        return h

    # ---- Phase 1: square-parameterization band anneal ----
    stages = [(0.05, 0.95), (0.2, 0.99), (1.0, 0.999)]
    band_deadline = t0 + budget_seconds * 0.45
    per_stage = budget_seconds * 0.13
    for lam, thr in stages:
        if time.process_time() >= band_deadline - 1.0:
            break
        ds = min(band_deadline, time.process_time() + per_stage)
        ht = _lbfgs_square_band(best, lam, thr, 120, ds)
        nb, bstd = _band_stats(ht, thr)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            tag = "NEW BEST"
        else:
            tag = "no gain"
        print("sq-band lam=%.3f thr=%.3f |B|/n=%.4f bandstd/c=%.6f R=%.9f zf=%.4f %s"
              % (lam, thr, nb / max(1, ht.size), bstd, r, _zero_frac(ht), tag))
        fd = min(band_deadline, time.process_time() + per_stage * 0.5)
        hp = polish_h(best, fd)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp
            print("  polish ACCEPT R=%.9f zf=%.4f" % (bestR, _zero_frac(best)))

    # ---- Phase 2: alternate square-tie polish, h-window polish, revival kicks ----
    loop = 0
    while time.process_time() < deadline - 2.0:
        loop += 1
        prevR = bestR
        # square-parameterization exact tie polish
        fd = min(deadline, time.process_time() + budget_seconds * 0.10)
        ht = _lbfgs_square_tie(best, 150, fd)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        # h-space window polish
        if time.process_time() < deadline - 2.0:
            fd2 = min(deadline, time.process_time() + budget_seconds * 0.10)
            hp = polish_h(best, fd2)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
        # revival kick
        if time.process_time() < deadline - 2.0:
            hk = _zero_revival_kick(best, frac=0.05)
            hk = _rescale(hk)
            fd3 = min(deadline, time.process_time() + budget_seconds * 0.08)
            hk = _lbfgs_all_pos(hk, 120, fd3)
            rk = R_of(hk)
            if rk > bestR + 1e-15:
                best, bestR = hk.copy(), rk
        print("loop %d R=%.9f dR=%.3e zf=%.4f nearmax5=%.4f"
              % (loop, bestR, bestR - prevR, _zero_frac(best),
                 _nearmax_frac(best)))

    # Final polish
    if time.process_time() < deadline - 1.0:
        fd = deadline - 0.5
        hp = polish_h(best, fd)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, topfrac=1e-10):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - topfrac))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150, maxfun=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))
    if maxfun is None:
        maxfun = 2 * maxiter

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, deadline, alpha=0.25, maxiter=150):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_cvar(hh, alpha),
                         deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _box_smooth(a, width):
    width = max(1, int(width))
    if width <= 1:
        return a
    k = np.ones(width) / width
    return np.convolve(a, k, mode='same')


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    h = np.diff(C)
    return np.clip(h, 0, None)


def _seed_perturb(c, seed, amp, smooth_frac):
    N = c.size
    rng = np.random.RandomState(seed)
    a = rng.normal(0.0, amp, size=N)
    a = _box_smooth(a, max(1, N // smooth_frac))
    a = np.clip(a, -0.5, 0.5)
    h = np.clip(c * (1.0 + a), 0, None)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 1: local polishes on the start (cheap, guaranteed-ish small gains)
    if time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.5, time.process_time() + 4.0)
        h = _full_lbfgs(best, tlim, maxiter=120)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("polish R=%.12f" % bestR)

    # Phase 2: CVaR-smoothed escape then tie polishes (different objective
    # basin, then return to true objective). This is the new idea: CVaR
    # objective on top-alpha knots avoids getting stuck on the single-tie
    # gradient, exploring a smoother landscape.
    for alpha in (0.30, 0.15, 0.06):
        if time.process_time() >= deadline - 3.0:
            break
        tlim = min(deadline - 2.5, time.process_time() + 6.0)
        h = _cvar_lbfgs(best, tlim, alpha=alpha, maxiter=120)
        # return to true objective
        tlim = min(deadline - 2.0, time.process_time() + 5.0)
        h = _full_lbfgs(h, tlim, maxiter=150)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("cvar a=%.2f R=%.12f" % (alpha, bestR))
        else:
            # try a small perturbation + polish
            hp = _seed_perturb(best, 100 + int(alpha * 100), 0.03,
                               max(8, best.size // 64))
            tlim = min(deadline - 1.5, time.process_time() + 4.0)
            hp = _full_lbfgs(hp, tlim, maxiter=100)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("perturb a=%.2f R=%.12f" % (alpha, bestR))

    # Phase 3: 2N upsample refinement (as in original) with more seeds
    for seed in range(6):
        if time.process_time() >= deadline - 3.0:
            break
        c = best
        N = c.size
        if 2 * N > 1000000:
            break
        rng = np.random.RandomState(seed)
        a = rng.normal(0.0, 0.15, size=N)
        a = _box_smooth(a, max(1, N // 128))
        a = np.clip(a, -0.5, 0.5)
        h2 = np.empty(2 * N, dtype=float)
        h2[0::2] = c * (1.0 + a)
        h2[1::2] = c * (1.0 - a)
        h2 = _rescale(h2)

        tlim = min(deadline - 2.0, time.process_time() + 8.0)
        h2p = _full_lbfgs(h2, tlim, maxiter=180)
        r_after = R_of(h2p)
        accepted = False
        if r_after > bestR + 1e-12:
            best, bestR = h2p, r_after
            accepted = True
            print("seed %d: 2N after=%.12f ACCEPT" % (seed, bestR))
        if not accepted:
            h_fold = _fold_back(h2p, N)
            if h_fold.sum() > 0:
                h_fold = _rescale(h_fold)
                tlim = min(deadline - 1.5, time.process_time() + 3.5)
                h_fold = _full_lbfgs(h_fold, tlim, maxiter=120)
                r_fold = R_of(h_fold)
                if r_fold > bestR + 1e-12:
                    best, bestR = h_fold, r_fold
                    print("seed %d: fold R=%.12f ACCEPT" % (seed, bestR))

    # Phase 4: peak window polish
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.6, time.process_time() + 3.0)
        h_pk = _peak_window_polish(best, tlim, pad=3)
        rp = R_of(h_pk)
        if rp > bestR + 1e-15:
            best, bestR = h_pk, rp

    # Phase 5: last-chance full polish
    if time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.3, time.process_time() + 4.0)
        h = _full_lbfgs(best, tlim, maxiter=200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r

    if bestR < startR:
        best = start_best
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best, "alternative": best}

