def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True,
                 alpha=0.0, logparam=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0

    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif alpha > 0:
        fg = (lambda hh: _fun_grad_cvar(hh, alpha))
    else:
        fg = _fun_grad_tie

    if logparam:
        pos = active[h[active] > 1e-14 * max(h.max(), 1e-30)]
        if pos.size == 0:
            return h0
        floor = 1e-10 * h.max()
        u0 = np.log(np.clip(h[pos], floor, None))

        def f(u):
            hh = h.copy()
            hh[pos] = np.exp(u)
            val, g = fg(hh)
            return val, g[pos] * hh[pos]

        cb = _make_cb(deadline - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * pos.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return h0
        if res is None:
            return h0
        h2 = h.copy()
        h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
        return _rescale(h2)

    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _upsample_lin(h, k):
    n = h.size
    if k <= 1:
        return h.copy()
    x = np.linspace(0.0, n - 1.0, n * k)
    out = np.interp(x, np.arange(n, dtype=float), h)
    return np.clip(out, 0.0, None)


def _upsample_fft(h, k):
    n = h.size
    if k <= 1:
        return h.copy()
    m = n * k
    H = np.fft.rfft(h)
    out = np.fft.irfft(H, m) * (m / n)
    s_in = h.sum()
    s_out = out.sum()
    if s_out > 0:
        out *= s_in / s_out
    return np.clip(out, 0.0, None)


def _upsample_spline(h, k):
    """Cubic spline / smooth upsample via cosine window, keeps positivity."""
    n = h.size
    if k <= 1:
        return h.copy()
    x = np.linspace(0.0, n - 1.0, n * k)
    try:
        from scipy.interpolate import CubicSpline
        cs = CubicSpline(np.arange(n, dtype=float), h)
        out = cs(x)
    except Exception:
        out = np.interp(x, np.arange(n, dtype=float), h)
    return np.clip(out, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    rng = np.random.default_rng(20240607)

    # ---- Phase 0: log-param polish on the coarse grid (new) ----
    p0_end = t0 + budget_seconds * 0.18
    if time.process_time() < p0_end - 2.0:
        win = _peak_window(best, pad_frac=0.15, extra=200)
        ht = _lbfgs_block(best, win, 400,
                          min(p0_end - 1.0, time.process_time() + 8.0),
                          tie=True, logparam=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        # cvar warm-up to break ties
        for alpha in (0.02, 0.005, 0.001):
            if time.process_time() >= p0_end - 1.5:
                break
            ht = _lbfgs_block(best, np.arange(best.size), 200,
                              min(p0_end - 1.0, time.process_time() + 4.0),
                              alpha=alpha)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("phase0 R=%.9f" % bestR)

    # ---- Phase 1: peak-window polish on the coarse grid ----
    p1_end = t0 + budget_seconds * 0.30
    if time.process_time() < p1_end - 2.0:
        for pad in (0.12, 0.07, 0.04):
            if time.process_time() >= p1_end - 1.5:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 300,
                              min(p1_end - 1.0, time.process_time() + 5.0),
                              beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
            ht = _lbfgs_block(best, win, 300,
                              min(p1_end - 1.0, time.process_time() + 5.0),
                              tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("phase1 R=%.9f" % bestR)

    # ---- Phase 2: mixed-lift refinement (lin + FFT + spline) ----
    p2_end = t0 + budget_seconds * 0.62
    k_choices = (3, 2, 2)
    for k in k_choices:
        if time.process_time() >= p2_end - 3.0:
            break
        for ups in (_upsample_lin, _upsample_fft, _upsample_spline):
            if time.process_time() >= p2_end - 2.5:
                break
            hu = ups(best, k)
            if hu.size > 900000:
                continue
            for beta in (1e5, 1e6, 0.0):
                if time.process_time() >= p2_end - 2.0:
                    break
                ht = _lbfgs_block(hu, np.arange(hu.size), 150,
                                  min(p2_end - 1.0,
                                      time.process_time() + 6.0),
                                  beta=beta, tie=(beta == 0.0))
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r
                    hu = ht
            print("  lift k=%d %s R=%.9f N=%d"
                  % (k, ups.__name__, bestR, best.size))

    # ---- Phase 3: value-band polish at fine resolution ----
    p3_end = t0 + budget_seconds * 0.90
    band_edges = [(0.0, 0.05), (0.05, 0.20), (0.20, 0.50),
                  (0.50, 0.80), (0.80, 0.95), (0.95, 1.001)]
    cyc = 0
    while time.process_time() < p3_end - 2.0:
        cyc += 1
        Lf = _knots(best)
        M = Lf.max()
        n = best.size
        v = Lf[:n]
        order = rng.permutation(len(band_edges))
        gains = []
        for bi in order:
            if time.process_time() >= p3_end - 1.5:
                break
            lo, hi = band_edges[bi]
            lo *= M; hi *= M
            sel = np.flatnonzero((best > 0) & (v >= lo) & (v < hi))
            if sel.size == 0:
                gains.append(0.0)
                continue
            mask = np.zeros(n, dtype=bool)
            mask[sel] = True
            active = mask.copy()
            for d in (1, 2, 4):
                active[d:] |= mask[:-d]
                active[:-d] |= mask[d:]
            active = np.flatnonzero(active)
            if active.size < 20 or active.size > 0.8 * n:
                gains.append(0.0)
                continue
            prevR = R_of(best)
            ht = _lbfgs_block(best, active, 200,
                              min(p3_end - 1.0,
                                  time.process_time() + 5.0), tie=True)
            r = R_of(ht)
            if r > prevR + 1e-15:
                best, bestR = ht.copy(), r
                gains.append(r - prevR)
            else:
                gains.append(0.0)
        print("band cyc=%d R=%.9f gains=%s"
              % (cyc, bestR, " ".join("%.1e" % g for g in gains)))
        if all(g == 0.0 for g in gains) and cyc > 1:
            break

    # ---- Phase 4: final global polish (logparam + tie) ----
    fd = t0 + budget_seconds * 0.985
    while time.process_time() < fd - 1.5:
        win = _peak_window(best, pad_frac=0.04, extra=64)
        ht = _lbfgs_block(best, win, 400,
                          min(fd - 1.0, time.process_time() + 4.0),
                          tie=True, logparam=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final polish R=%.9f" % bestR)
        else:
            break
    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return 1e18, np.zeros(h.size)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_tie(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        return _fun_grad_tie(np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.10, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def _band_stats(h, thr):
    Lf = _knots(h)
    c = Lf.max()
    if c <= 0:
        return 0, 0.0
    B = Lf[Lf >= thr * c]
    if B.size == 0:
        return 0, 0.0
    return B.size, float(np.std(B) / c)


def _gs_step(h, T, step):
    """One Gerchberg-Saxton style step: fit knot values toward target T."""
    Lf = _knots(h)
    r = Lf - T
    g = _backprop(r, h)
    h2 = np.clip(h - step * g, 0.0, None)
    if h2.sum() <= 0:
        return h
    # rescale so max(f*f) equals target peak
    target_peak = T.max()
    mx = _knots(h2).max()
    if mx > 0 and target_peak > 0:
        h2 = h2 * np.sqrt(target_peak / mx)
    return h2


def _gs_run(h, thr, nsteps, deadline):
    """Build target from current knots, run GS steps with annealed step size."""
    Lf = _knots(h)
    c = Lf.max()
    if c <= 0:
        return h
    T = np.where(Lf >= (1.0 - thr) * c, c, Lf)
    for k in range(nsteps):
        if time.process_time() >= deadline - 0.2:
            break
        Lf = _knots(h)
        r = Lf - T
        g = _backprop(r, h)
        gmax = np.abs(g).max()
        if gmax <= 0:
            break
        frac = 0.5 * (1.0 - k / max(1, nsteps - 1)) + 0.01 * (k / max(1, nsteps - 1))
        step = frac / gmax
        h = _gs_step(h, T, step)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    def polish(h, fd):
        ht = _lbfgs_tie(h, 200, fd)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
        if time.process_time() < fd - 0.5:
            win = _peak_window(h, tol=0.95, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(h, win, 200, fd)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
        return h

    thrs = [0.05, 0.10, 0.20, 0.35]
    nsteps = 40
    loop = 0
    while time.process_time() < deadline - 2.0:
        loop += 1
        for thr in thrs:
            if time.process_time() >= deadline - 2.0:
                break
            nb0, bs0 = _band_stats(best, thr)
            # GS phase
            gs_deadline = min(deadline - 1.5, time.process_time() + budget_seconds * 0.06)
            hg = _gs_run(best, thr, nsteps, gs_deadline)
            nb1, bs1 = _band_stats(hg, thr)
            rg = R_of(hg)
            # exact polish
            fd = min(deadline - 0.5, time.process_time() + budget_seconds * 0.05)
            hp = polish(hg, fd)
            rp = R_of(hp)
            tag = ""
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
                tag = "NEW BEST"
            print("L%d thr=%.2f bandstd %.6f->%.6f R_gs=%.9f R_pol=%.9f %s"
                  % (loop, thr, bs0, bs1, rg, rp, tag))

    if time.process_time() < deadline - 1.0:
        fd = deadline - 0.5
        hp = polish(best, fd)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _block_fun_grad(c, BLK, beta=0.0):
    h = np.repeat(c, BLK)
    if beta > 0:
        val, g = _fun_grad_beta(h, beta)
    else:
        val, g = _fun_grad_tie(h)
    gc = g.reshape(-1, BLK).sum(axis=1)
    return val, gc


def _newton_round(c0, BLK, deadline, maxiter=60, beta=0.0):
    c = np.asarray(c0, dtype=float).copy()
    if time.process_time() >= deadline - 0.5:
        return c0

    def f(cv):
        return _block_fun_grad(cv, BLK, beta)

    def hessp(cv, v):
        nv = np.linalg.norm(v)
        if nv == 0:
            return np.zeros_like(v)
        eps = 1e-6 * max(1.0, np.max(np.abs(cv))) / nv
        _, gp = _block_fun_grad(cv + eps * v, BLK, beta)
        _, gm = _block_fun_grad(cv - eps * v, BLK, beta)
        return (gp - gm) / (2.0 * eps)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, c, jac=True, method='trust-ncg', hessp=hessp,
                       callback=cb,
                       options={'maxiter': maxiter, 'gtol': 1e-18,
                                'xtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    return res.x


def _compress(h, n):
    if h.size % n == 0:
        return h.reshape(-1, h.size // n).mean(axis=1)
    return np.interp(np.linspace(0, h.size - 1, n),
                     np.arange(h.size), h)


def _expand(c, n):
    if n % c.size == 0:
        return np.repeat(c, n // c.size)
    return np.interp(np.linspace(0, c.size - 1, n),
                     np.arange(c.size), c)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: coarse Newton on block-mean at moderate resolution ----
    if time.process_time() < deadline - 5.0:
        for target_n in (2048, 4096, 1024):
            if time.process_time() >= deadline - 4.0:
                break
            n = min(target_n, best.size)
            c = _compress(best, n)
            c = _rescale(np.clip(c, 1e-30, None))
            BLK = max(1, best.size // n)
            sub_deadline = min(deadline - 2.0, time.process_time() + 5.0)
            for beta in (1e4, 1e5, 0.0):
                c_new = _newton_round(c, BLK, sub_deadline, maxiter=40, beta=beta)
                if c_new is None:
                    break
                c_new = _rescale(np.clip(c_new, 1e-30, None))
                if R_of(_expand(c_new, best.size)) > R_of(_expand(c, best.size)):
                    c = c_new
                if time.process_time() >= sub_deadline - 0.5:
                    break
            full = _rescale(_expand(c, best.size))
            r = R_of(full)
            if r > bestR + 1e-15:
                best, bestR = full, r
                print("coarse-Newton n=%d R=%.9f" % (n, bestR))

    # ---- Phase 2: full-resolution tie L-BFGS polish ----
    if time.process_time() < deadline - 2.0:
        ht = _lbfgs_block(best, np.arange(best.size), 300,
                          min(deadline - 1.5, time.process_time() + 6.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("full tie polish R=%.9f" % bestR)

    # ---- Phase 3: peak-window tie polishes (multiple passes, shrinking) ----
    for pad in (0.08, 0.05, 0.03, 0.02, 0.01, 0.006):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        for beta in (1e7, 1e5, 0.0):
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_block(best, win, 300,
                              min(deadline - 0.6,
                                  time.process_time() + 2.5),
                              beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---- Phase 4: final full-resolution polish with remaining time ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_block(best, np.arange(best.size), 500,
                          deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("final polish R=%.9f" % bestR)

    # ---- Phase 5: refine in a finer grid (double resolution) with L-BFGS ----
    # A genuinely different construction: upsample to 2N and re-optimise.
    alt = None
    if time.process_time() < deadline - 0.8:
        n2 = min(1000000, 2 * best.size)
        up = np.interp(np.linspace(0, best.size - 1, n2),
                       np.arange(best.size), best)
        up = _rescale(np.clip(up, 0, None))
        ht = _lbfgs_block(up, np.arange(n2), 200, deadline - 0.4)
        alt = _rescale(ht)
        altR = R_of(alt)
        if altR > bestR + 1e-15:
            best, bestR = alt, altR
            alt = None
            print("upsample polish R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt is not None:
        result["alternative"] = alt
    elif start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_softmax(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flattop(h, tau, kappa):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    m = int(np.argmax(Lf))
    gLf = -dq / num
    gLf[m] += 1.0 / mx
    S = Lf >= tau * mx
    nS = int(np.count_nonzero(S))
    V = 0.0
    if nS > 1:
        Ls = Lf[S]
        Lbar = Ls.mean()
        diff = Ls - Lbar
        V = float(np.sum(diff * diff)) / (mx * mx * nS)
        dV = np.zeros_like(Lf)
        dV[S] = 2.0 * diff / (mx * mx * nS)
        gLf += kappa * dV
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + kappa * V
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, mode, param=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if mode == 'tie':
        fg = _fun_grad_tie
    elif mode == 'softmax':
        fg = (lambda hh: _fun_grad_softmax(hh, param))
    else:
        tau, kappa = param
        fg = (lambda hh: _fun_grad_flattop(hh, tau, kappa))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad_frac=0.05, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= 0.9995 * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n or m < 8:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    startR = 0.0
    best = None
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # New idea: multi-scale refinement. Coarsen the current best by q, optimize
    # at coarse scale with softmax+flattop, prolongate back, then polish at full
    # resolution. This lets large-scale structure change that full-res L-BFGS
    # can't reach (it gets stuck in local tie-degenerate configurations).
    q_candidates = [2, 3, 4, 5, 6, 8]
    alt_best = None
    altR = -1.0

    def polish_full(cur, curR, cap):
        # softmax anneal
        for beta in (100.0, 400.0, 1500.0):
            if time.process_time() >= cap - 0.5:
                break
            cand = _lbfgs_block(cur, np.arange(cur.size), 250,
                                min(cap - 0.3, time.process_time() + 2.0),
                                'softmax', beta)
            r = R_of(cand)
            if r > curR + 1e-15:
                cur, curR = cand, r
        # tie polish
        if time.process_time() < cap - 0.3:
            cand = _lbfgs_block(cur, np.arange(cur.size), 200,
                                min(cap - 0.1, time.process_time() + 1.5),
                                'tie')
            r = R_of(cand)
            if r > curR + 1e-15:
                cur, curR = cand, r
        return cur, curR

    # Stage A: initial full polish
    if time.process_time() < deadline - 8.0:
        cap = min(deadline - 7.0, time.process_time() + 10.0)
        nb, nR = polish_full(best, bestR, cap)
        if nR > bestR:
            best, bestR = nb, nR
    print("after initial polish: R=%.9f" % bestR)

    # Stage B: multi-scale cycle — try coarsening with several q's, picking
    # the best coarse scale, then prolongate and polish.
    attempt = 0
    while time.process_time() < deadline - 4.0 and attempt < 6:
        attempt += 1
        # pick q
        q = q_candidates[(attempt - 1) % len(q_candidates)]
        qh = _coarsen(best, q)
        if qh is None:
            continue
        qh = _rescale(qh)
        # optimize coarse scale with flattop ladder then softmax
        cap_c = min(deadline - 3.0, time.process_time() + 4.0)
        for (tau, kappa) in ((0.99, 0.3), (0.97, 1.5), (0.93, 5.0)):
            if time.process_time() >= cap_c - 0.5:
                break
            cand = _lbfgs_block(qh, np.arange(qh.size), 150,
                                min(cap_c - 0.3, time.process_time() + 1.2),
                                'flattop', (tau, kappa))
            r = R_of(cand)
            if r > R_of(qh):
                qh = cand
        if time.process_time() < cap_c - 0.3:
            for beta in (200.0, 800.0):
                if time.process_time() >= cap_c - 0.2:
                    break
                cand = _lbfgs_block(qh, np.arange(qh.size), 150,
                                    min(cap_c - 0.1, time.process_time() + 1.0),
                                    'softmax', beta)
                r = R_of(cand)
                if r > R_of(qh):
                    qh = cand
        # prolongate
        ph = _prolongate(qh, q)
        pr = R_of(ph)
        if pr > altR:
            alt_best, altR = ph.copy(), pr
        # polish at full resolution
        cap_p = min(deadline - 2.0, time.process_time() + 4.0)
        nb, nR = polish_full(ph, pr, cap_p)
        if nR > bestR + 1e-15:
            best, bestR = nb, nR
            print("  q=%d -> R=%.9f" % (q, bestR))
        if nR > altR:
            alt_best, altR = nb.copy(), nR

    # Stage C: peak-window polish at full resolution
    for pad in (0.08, 0.05, 0.03):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 1.0, time.process_time() + 2.0),
                          'tie')
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r

    # Stage D: final full softmax->tie
    if time.process_time() < deadline - 1.0:
        for beta in (3000.0, 8000.0):
            if time.process_time() >= deadline - 0.5:
                break
            cand = _lbfgs_block(best, np.arange(best.size), 200,
                                min(deadline - 0.3, time.process_time() + 1.0),
                                'softmax', beta)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r
        if time.process_time() < deadline - 0.3:
            pol = _lbfgs_block(best, np.arange(best.size), 150,
                               min(deadline - 0.1, time.process_time() + 0.8),
                               'tie')
            rp = R_of(pol)
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size <= 1000000 and altR > startR - 1e-9:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, deadline, alpha=0.1, maxiter=200):
    return _lbfgs_custom(h0, lambda h: _fun_grad_cvar(h, alpha),
                         deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _find_block(h):
    N = h.size
    for BLK in range(min(64, N), 1, -1):
        if N % BLK != 0:
            continue
        K = N // BLK
        c = h.reshape(K, BLK)
        if np.allclose(c, c[:, :1], rtol=1e-12, atol=1e-15):
            return BLK
    return 1


def _refine_via_cvar(h, deadline, rounds=4):
    """Use CVaR surrogate (smooth max approx) to escape tie-flatness, then tie-polish."""
    best = h
    bestR = R_of(h)
    alphas = [0.3, 0.15, 0.07, 0.03]
    for r in range(rounds):
        if time.process_time() > deadline - 1.0:
            break
        a = alphas[r % len(alphas)]
        sub_deadline = min(deadline - 0.8, time.process_time() + 6.0)
        h_try = _cvar_lbfgs(best, sub_deadline, alpha=a, maxiter=120)
        R_try = R_of(h_try)
        if R_try > bestR + 1e-13:
            best = h_try
            bestR = R_try
            print("cvar a=%.2f R=%.9f" % (a, bestR))
        # polish with true tie objective
        if time.process_time() < deadline - 0.5:
            sub_deadline = min(deadline - 0.4, time.process_time() + 5.0)
            h_p = _full_lbfgs(best, sub_deadline, maxiter=100)
            Rp = R_of(h_p)
            if Rp > bestR + 1e-13:
                best = h_p
                bestR = Rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Main new idea: alternate CVaR-surrogate ascents and true-tie polish.
    # CVaR over top-alpha knots is a smooth proxy that lets the optimizer
    # move across the L-inf tie-flat region, then exact tie-LBFGS recovers.
    best, bestR = _refine_via_cvar(best, deadline, rounds=6)

    # Peak polish
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.8, time.process_time() + 6.0)
        h_pk = _peak_window_polish(best, tlim, pad=3)
        rp = R_of(h_pk)
        if rp > bestR + 1e-15:
            best = h_pk
            bestR = rp
            print("peak polish: R=%.9f" % bestR)

    # Final full tie polish
    if time.process_time() < deadline - 0.8:
        tlim = min(deadline - 0.6, time.process_time() + 8.0)
        h_full = _full_lbfgs(best, tlim, maxiter=250)
        rf = R_of(h_full)
        if rf > bestR + 1e-15:
            best = h_full
            bestR = rf

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if bestR < startR:
        return {"best": start_best, "alternative": best}
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lift_mass(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def _peak_window_polish(h, deadline, pad_frac=0.15):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    n = h.size
    c_lo = max(0, idx.min() // 2)
    c_hi = min(n, idx.max() // 2 + 2)
    pad = max(64, int(pad_frac * n))
    lo = max(0, c_lo - pad)
    hi = min(n, c_hi + pad)
    free = np.arange(lo, hi)
    return _lbfgs_block(h, free, 400, deadline)


def _coarsen(h, c):
    """Average-coarsen by factor c (piecewise-constant downsample, mass preserving)."""
    n = h.size
    m = n // c
    if m < 1:
        return h.copy()
    return h[:m * c].reshape(m, c).mean(axis=1) * c


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    bestH = best.copy()
    bestRH = bestR
    print("base R=%.7f N=%d" % (bestR, best.size))

    # ===== Stage 0: coarsen-and-refine escape =====
    # Idea: a coarsened version has fewer DOF and L-BFGS can move it to a
    # different local basin; lifting back gives a genuinely different shape.
    if time.process_time() < deadline - 30.0 and bestH.size >= 2000:
        for c in (2, 4, 8):
            if time.process_time() > deadline - 25.0:
                break
            hc = _coarsen(bestH, c)
            if hc.size < 16:
                continue
            sub_dl = min(deadline - 20.0, time.process_time() + 6.0)
            hc = _lbfgs_log(hc, 400, sub_dl)
            rc = R_of(hc)
            # lift back to original size
            hb = _rescale(_lift_mass(hc, bestH.size))
            sub_dl = min(deadline - 15.0, time.process_time() + 6.0)
            hb = _lbfgs_log(hb, 300, sub_dl)
            rb = R_of(hb)
            print("  coarsen x%d -> R=%.7f (best %.7f)" % (c, rb, bestRH))
            if rb > bestRH + 1e-13:
                bestH, bestRH = hb.copy(), rb
                print("    COARSEN ACCEPT R=%.7f" % bestRH)

    # ===== Stage 1: mass-preserving lift + polish =====
    n0 = bestH.size
    for factor in (2, 4):
        if time.process_time() > deadline - 20.0:
            break
        N2 = min(1000000, n0 * factor)
        if N2 == bestH.size:
            continue
        hL = _rescale(_lift_mass(bestH, N2))
        rL = R_of(hL)
        sub_dl = min(deadline - 12.0, time.process_time() + 8.0)
        hP = _lbfgs_log(hL, 300, sub_dl)
        rP = R_of(hP)
        if rP > rL:
            hL, rL = hP, rP
        print("  lift x%d -> R=%.7f (best %.7f)" % (factor, rL, bestRH))
        if rL > bestRH + 1e-13:
            bestH, bestRH = hL.copy(), rL
            print("    LIFT ACCEPT R=%.7f N=%d" % (bestRH, bestH.size))

    # ===== Stage 2: peak-window polish + soft-max escape =====
    while time.process_time() < deadline - 3.0:
        before = bestRH
        sub_dl = min(deadline - 2.0, time.process_time() + 6.0)
        hb = _peak_window_polish(bestH, sub_dl)
        rb = R_of(hb)
        if rb > bestRH + 1e-13:
            bestH, bestRH = hb.copy(), rb
            print("  peak ACCEPT R=%.7f" % bestRH)
            continue
        sub_dl = min(deadline - 1.5, time.process_time() + 5.0)
        h = _lbfgs_log(bestH, 400, sub_dl)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
            print("  sharp ACCEPT R=%.7f" % bestRH)
            continue
        moved = False
        for beta in (1e2, 1e3, 1e4):
            if time.process_time() > deadline - 2.0:
                break
            sub_dl = min(deadline - 1.0, time.process_time() + 2.5)
            hb2 = _lbfgs_log(bestH, 150, sub_dl,
                             fg=lambda hh, b=beta: _fun_grad_beta(hh, b))
            rb2 = R_of(hb2)
            if rb2 > bestRH + 1e-13:
                bestH, bestRH = hb2.copy(), rb2
                print("  beta=%.0e ACCEPT R=%.7f" % (beta, bestRH))
                moved = True
                break
        if not moved and bestRH <= before + 1e-13:
            if bestH.size < 400000 and time.process_time() < deadline - 10.0:
                N2 = min(400000, bestH.size * 2)
                hL = _rescale(_lift_mass(bestH, N2))
                sub_dl = min(deadline - 6.0, time.process_time() + 6.0)
                hP = _lbfgs_log(hL, 300, sub_dl)
                rP = R_of(hP)
                if rP > bestRH + 1e-13:
                    bestH, bestRH = hP, rP
                    print("  relaunch-lift R=%.7f N=%d" % (bestRH, bestH.size))
                else:
                    break
            else:
                break

    # ===== Stage 3: final sharp polish =====
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 500, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

