    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _log_lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    """Optimise in log-space over a block: heights stay strictly positive,
    avoids basis-pursuit style collapse to the boundary.  A real change of
    parametrisation that lets the peak region sharpen without getting stuck."""
    if time.process_time() >= deadline - 0.4:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size < 2:
        return h0
    x0 = h[active].copy()
    pos = x0 > 0
    if not np.any(pos):
        return h0
    # work only on strictly-positive entries (log parametrisation)
    idx_pos = active[pos]
    floor = 1e-12 * max(x0.max(), 1e-30)
    u0 = np.log(np.clip(h[idx_pos], floor, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        hh = h.copy()
        hh[idx_pos] = np.exp(np.clip(u, -60.0, 60.0))
        val, g = fg(hh)
        return val, g[idx_pos] * hh[idx_pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx_pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[idx_pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _newton_polish(best, bestR, deadline, pad_frac=0.25):
    if time.process_time() >= deadline - 0.5:
        return best, bestR, False
    win = _peak_window(best, pad_frac=pad_frac, extra=256)
    free = win[best[win] > 0]
    if free.size < 2:
        return best, bestR, False
    z0 = np.log(np.clip(best[free], 1e-300, None))
    base = best.copy()

    def fz(z):
        hh = base.copy()
        hh[free] = np.exp(np.clip(z, -700, 700))
        val, g = _fun_grad(hh)
        return val, g[free] * hh[free]

    def gz(z):
        return fz(z)[1]

    def hessp(z, p):
        try:
            nz = np.linalg.norm(z)
            np_ = np.linalg.norm(p)
            eps = 1e-6 * (1.0 + nz) / max(np_, 1e-30)
            gp = gz(z + eps * p)
            gm = gz(z - eps * p)
            return (gp - gm) / (2.0 * eps)
        except Exception:
            return p

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(fz, z0, jac=True, hessp=hessp, method='trust-krylov',
                       callback=cb,
                       options={'maxiter': 80, 'gtol': 1e-10,
                                'initial_tr_radius': 1e-3})
    except (TimeoutError, Exception):
        return best, bestR, False
    if res is None:
        return best, bestR, False
    ht = base.copy()
    ht[free] = np.exp(np.clip(res.x, -700, 700))
    ht = _rescale(np.clip(ht, 0.0, None))
    r = R_of(ht)
    if r > bestR + 1e-14:
        return ht, r, True
    return best, bestR, False


def _zero_frac(h):
    return float(np.mean(h == 0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # Phase A: log-space peak polish (new idea) — sharpen the peak region.
    if time.process_time() < deadline - 1.0:
        win = _peak_window(best, pad_frac=0.30, extra=256)
        ht = _log_lbfgs_block(best, win, 300, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = 'logpk'
            print("logpk: R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # Phase B: baseline cycle on best
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.6:
            break
        ht = _lbfgs_all_pos(best, 250, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = "beta%g" % beta
            print("beta=%g: R=%.9f" % (beta, bestR))
    for it, pad in enumerate([0.20, 0.12, 0.08]):
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 350, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = "pk%d" % it
            print("pk%d: R=%.9f" % (it, bestR))

    # Phase C: alternating Newton + log-peak polish — repeated, keeps
    # improving until time runs out.  This is the key change: the Newton
    # step in log-space around the peak plus a log-space L-BFGS polish
    # chases the sharp peak that determines ||f*f||_inf.
    while time.process_time() < deadline - 1.5 and best.size <= 200000:
        improved = False
        for pfrac in [0.20, 0.12, 0.08, 0.30]:
            if time.process_time() >= deadline - 1.0:
                break
            ht, r, gain = _newton_polish(best, bestR, deadline, pad_frac=pfrac)
            if gain:
                best, bestR = ht, r
                origin = origin + '+N%.2f' % pfrac
                print("newton pad=%.2f: R=%.9f" % (pfrac, bestR))
                improved = True
                break
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        if time.process_time() >= deadline - 1.0:
            break
        # log-space polish on peak window
        win = _peak_window(best, pad_frac=0.15, extra=128)
        ht = _log_lbfgs_block(best, win, 200, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + '+log'
            print("log polish: R=%.9f" % bestR)
            improved = True
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        # full polish with beta
        if time.process_time() < deadline - 0.6:
            ht = _lbfgs_all_pos(best, 150, deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                improved = True
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
        if not improved:
            # nudge: random multiplicative perturbation on peak window and retry
            if time.process_time() >= deadline - 1.0:
                break
            cand = best.copy()
            win = _peak_window(cand, pad_frac=0.20, extra=128)
            nz = win[cand[win] > 0]
            if nz.size > 0:
                cand[nz] *= np.exp(0.02 * rng.standard_normal(nz.size))
                cand = _rescale(np.clip(cand, 0, None))
                r0 = R_of(cand)
                if r0 > bestR - 1e-6:
                    ht = _lbfgs_all_pos(cand, 120, deadline - 0.3, beta=1e7)
                    r = R_of(ht)
                    if r > bestR + 1e-14:
                        best, bestR = ht.copy(), r
                        origin = origin + '+nudge'
                        print("nudge: R=%.9f" % bestR)
                    elif r > alt_bestR:
                        alt_best, alt_bestR = ht.copy(), r

    # Phase D: final peak polishes
    for pad in [0.15, 0.10, 0.08, 0.20, 0.12]:
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 350, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + '+pk%.2f' % pad
            print("pad=%.2f: R=%.9f" % (pad, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_fg(h0, fun_grad, deadline, maxiter=300):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block_fg(h0, free, fun_grad, deadline, maxiter=300):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.3, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _smooth(h, w):
    if w <= 1:
        return h.copy()
    k = np.ones(w) / w
    return np.convolve(h, k, mode='same')


def _try(h, best, bestR, deadline, tag=""):
    r = R_of(h)
    if r > bestR + 1e-14:
        print("%s NEW BEST R=%.9f" % (tag, r))
        return h.copy(), r, True
    return best, bestR, False


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, nearmax50=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best, 0.95),
             _nearmax_frac(best, 0.5)))

    # Phase A: CVaR smoothing ladder (heavier averaging of the top of f*f
    # spreads the peak -> directly grows the flat region). Cheap warmup.
    A_deadline = t0 + budget_seconds * 0.20
    for alpha in (0.05, 0.02, 0.01, 0.005):
        if time.process_time() >= A_deadline - 1.0:
            break
        dp = min(A_deadline, time.process_time() + budget_seconds * 0.04)
        ht = _lbfgs_fg(best, lambda hh, a=alpha: _fun_grad_cvar(hh, a), dp, 300)
        best, bestR, _ = _try(ht, best, bestR, deadline, "cvar a=%.3f" % alpha)

    # Phase B: perturbation cycle with fresh ideas.
    B_deadline = t0 + budget_seconds * 0.72
    level = 0
    stale = 0
    while time.process_time() < B_deadline - 2.0 and level < 60:
        level += 1
        before = bestR
        n = best.size
        trials = []
        for w in (2, 3, 4, 6, 9, 14):
            trials.append(_smooth(best, w))
        if n > 4000:
            trials.append(best[:(n // 2) * 2].reshape(-1, 2).mean(axis=1))
        if n > 8000:
            trials.append(best[:(n // 4) * 4].reshape(-1, 4).mean(axis=1))
        amp = max(5e-4, 0.03 * (0.55 ** level))
        for _ in range(2):
            trials.append(np.clip(best * (1.0 + rng.uniform(-amp, amp, n)),
                                  0, None))
        for ht in trials:
            if time.process_time() >= B_deadline - 1.0:
                break
            ht = _rescale(ht)
            sd = min(B_deadline, time.process_time() + 2.5)
            ht = _lbfgs_fg(ht, _fun_grad_tie, sd, 250)
            best, bestR, imp = _try(ht, best, bestR, deadline,
                                    "perturb lvl=%d" % level)
            if imp:
                break
        if bestR > before + 1e-14:
            stale = 0
        else:
            stale += 1
            if stale > 5:
                ht = _rescale(_smooth(best, 18))
                sd = min(B_deadline, time.process_time() + 2.5)
                ht = _lbfgs_fg(ht, _fun_grad_tie, sd, 250)
                best, bestR, imp = _try(ht, best, bestR, deadline,
                                        "wide-smooth")
                if imp:
                    stale = 0

    # Phase C: final polish - full tie-grad + peak-window ladder.
    fd = t0 + budget_seconds * 0.90
    ht = _lbfgs_fg(best, _fun_grad_tie, fd, 800)
    best, bestR, _ = _try(ht, best, bestR, deadline, "FINAL tie")
    for pad in (0.10, 0.06, 0.04, 0.025):
        if time.process_time() >= fd - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block_fg(best, win, _fun_grad_tie, fd, 300)
        best, bestR, _ = _try(ht, best, bestR, deadline,
                              "FINAL peak pad=%.3f" % pad)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, "
          "nearmax50=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best, 0.95), _nearmax_frac(best, 0.5)))

    result = {"best": best}
    if start_best is not None and bestR <= start_bestR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


# ---------- Gauss-Newton on the near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=60):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-22 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_try(h, bestR, kappa, lam_scale, deadline):
    d = _gn_step(h, kappa, lam_scale, deadline)
    if d is None or not np.any(d):
        return h, bestR
    alpha = 1.0
    for _ in range(28):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * d, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        rn = R_of(hn)
        if rn > bestR + 1e-15:
            return hn, rn
        alpha *= 0.5
    return h, bestR


def _gn_plateau(h, deadline):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005, 0.002]
    lams = [1e-6, 1e-4, 1e-2, 1e-1]
    while time.process_time() < deadline:
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                hn, rn = _gn_try(best, bestR, kappa, lam,
                                 min(deadline, time.process_time() + 3.0))
                if rn > bestR + 1e-15:
                    best, bestR = hn, rn
                    improved = True
        if not improved:
            break
        if time.process_time() < deadline - 0.5:
            cap = min(deadline, time.process_time() + 1.5)
            hp = _lbfgs_log(best, 100, cap)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
    return best, bestR


# ---------- coarse-basis linearized least squares ----------

def _coarsen(h, M):
    n = h.size
    if n <= M:
        return h.copy()
    while h.size > M:
        m = h.size
        if m % 2 == 1:
            h = np.concatenate((h, [h[-1]]))
            m += 1
        h = 0.5 * (h[0::2] + h[1::2])
    return h


def _bspline_basis(M, K):
    x = np.arange(M, dtype=float) + 0.5
    B = np.zeros((K, M))
    centers = np.linspace(0, M, K)
    width = (M / (K - 1)) * 1.5 if K > 1 else M
    for k in range(K):
        t = (x - centers[k]) / width
        u = np.abs(t)
        w = np.where(u < 1.0, (4 - 6*u*u + 3*u**3)/6.0, 0.0)
        w = np.where((u >= 1.0) & (u < 2.0), (2 - u)**3 / 6.0, w)
        B[k] = w
    E = np.zeros((16, M))
    half = max(1, M // 64)
    for j in range(8):
        lo = j * half
        E[j, lo:lo+half] = np.linspace(1, 0, half) if half > 0 else 0
    for j in range(8):
        hi = M - j * half
        E[8+j, max(0, hi-half):hi] = np.linspace(0, 1, half) if half > 0 else 0
    B = np.vstack([B, E])
    s = B.sum(axis=1, keepdims=True)
    s[s <= 0] = 1
    B = B / s
    return B


def _basis_step(h, B, eps, lam, deadline):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None, 0.0
    thresh = (1.0 - eps) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * h.size - 1)]
    if A.size < 2:
        return None, 0.0
    c = L[A].mean()
    r = c - L[A]
    K = B.shape[0]
    J = np.zeros((A.size, K))
    for k in range(K):
        if time.process_time() > deadline:
            return None, 0.0
        cd = fftconvolve(h, B[k])
        J[:, k] = 2.0 * cd[A - 1]
    JtJ = J.T @ J
    Jtr = J.T @ r
    dg = np.diag(JtJ).copy()
    dg[dg <= 0] = 1.0
    reg = JtJ + lam * np.diag(dg)
    try:
        d = np.linalg.solve(reg, Jtr)
    except np.linalg.LinAlgError:
        return None, 0.0
    pred = float(r @ r - (r - J @ d) @ (r - J @ d))
    return d, pred


def _basis_try(h, bestR, B, eps, lam, deadline):
    d, pred = _basis_step(h, B, eps, lam, deadline)
    if d is None or not np.any(d):
        return h, bestR, 0.0
    delta = B.T @ d
    alpha = 1.0
    for _ in range(24):
        if time.process_time() > deadline:
            break
        hn = np.clip(h + alpha * delta, 0.0, None)
        if hn.sum() <= 0:
            alpha *= 0.5
            continue
        hn = _rescale(hn)
        rn = R_of(hn)
        if rn > bestR + 1e-15:
            return hn, rn, pred
        alpha *= 0.5
    return h, bestR, pred


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    M = 42496
    K = 256
    hc = _coarsen(best, M)
    B = _bspline_basis(hc.size, K)

    eps_list = [0.002, 0.005, 0.01, 0.02, 0.05]
    lam_list = [1e-6, 1e-4, 1e-2, 1e-1]

    coarse_best = hc.copy()
    coarse_bestR = R_of(coarse_best)
    for eps in eps_list:
        for lam in lam_list:
            if time.process_time() >= deadline - 2.0:
                break
            hn, rn, pred = _basis_try(coarse_best, coarse_bestR, B, eps, lam,
                                      min(deadline - 1.0, time.process_time() + 2.0))
            if rn > coarse_bestR + 1e-15:
                coarse_best, coarse_bestR = hn, rn

    if coarse_bestR > bestR + 1e-13 and coarse_best.size != best.size:
        n = best.size
        idx = (np.arange(n) * coarse_best.size // n).astype(int)
        up = _rescale(coarse_best[idx])
        ru = R_of(up)
        if ru > bestR + 1e-15:
            best, bestR = up, ru
            print("  upsample R=%.9f" % bestR)

    betas = [1.0, 5.0, 20.0, 80.0, 300.0, 1000.0]
    it = 0
    while time.process_time() < deadline - 0.5:
        it += 1
        improved = False

        if time.process_time() < deadline - 3.0:
            hc2 = _coarsen(best, M)
            Bc = _bspline_basis(hc2.size, K)
            cb = hc2.copy()
            cbR = R_of(cb)
            for eps in eps_list:
                for lam in lam_list:
                    if time.process_time() >= deadline - 2.0:
                        break
                    hn, rn, pred = _basis_try(cb, cbR, Bc, eps, lam,
                                              min(deadline - 1.0, time.process_time() + 1.5))
                    if rn > cbR + 1e-15:
                        cb, cbR = hn, rn
            if cbR > R_of(_coarsen(best, M)) + 1e-13:
                n = best.size
                idx = (np.arange(n) * cb.size // n).astype(int)
                up = _rescale(cb[idx])
                ru = R_of(up)
                if ru > bestR + 1e-15:
                    best, bestR = up, ru
                    improved = True
                    print("  basis iter=%d R=%.9f" % (it, bestR))

        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            cap = min(deadline - 0.3, time.process_time() + 3.0)
            hp = _lbfgs_log(best, 200, cap, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                improved = True
                print("  beta=%.0f iter=%d R=%.9f" % (beta, it, bestR))

        if time.process_time() < deadline - 0.5:
            gn_cap = min(deadline - 0.3, time.process_time() + 3.0)
            gh, gr = _gn_plateau(best, gn_cap)
            if gr > bestR + 1e-15:
                best, bestR = gh, gr
                improved = True
                print("  GN iter=%d R=%.9f" % (it, bestR))

        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 0.3, time.process_time() + 2.5)
            hp = _lbfgs_log(best, 200, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                improved = True
                print("  hard iter=%d R=%.9f" % (it, bestR))

        if it % 2 == 0 and time.process_time() < deadline - 1.0:
            free = _peak_window(best, frac=0.05)
            cap = min(deadline - 0.3, time.process_time() + 1.5)
            hb = _lbfgs_block(best, free, 150, cap)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb, rb
                improved = True
                print("  block iter=%d R=%.9f" % (it, bestR))

        if not improved:
            rng = np.random.default_rng(it)
            pert = best * (1.0 + 0.001 * rng.standard_normal(best.size))
            pert = _rescale(np.clip(pert, 0, None))
            rp = R_of(pert)
            if rp > bestR:
                best, bestR = pert, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_dinkel(h, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    dmax = np.zeros_like(Lf)
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    dmax[idx] = 1.0 / idx.size
    dD = 2.0 * s * mx * np.ones_like(h) + s * s * _backprop(dmax, h)
    dnum = _backprop(dq, h)
    grad = dnum - lam * dD
    val = -(num - lam * s * s * mx) / max(num, 1e-300)
    return val, grad


def _fun_grad_logflat(h, eps):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    dg = -1.0 / (Lf.size * (Lf + eps * M))
    idx = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    dg[idx] += 1.0 / idx.size / M
    grad = _backprop(dg, h)
    val = -(np.mean(np.log(Lf + eps * M))) + np.log(M)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # logflat ladder
    logflat_best = best.copy()
    logflat_bestR = bestR
    eps_list = [1e-2, 3e-3, 1e-3, 3e-4, 1e-4]
    for eps in eps_list:
        if time.process_time() >= deadline - 1.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 4.5)
        hc = _lbfgs_custom(best, lambda hh: _fun_grad_logflat(hh, eps),
                           tlim, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 2.0)
            hc = _full_lbfgs(hc, tlim2, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim3 = min(deadline - 1.0, time.process_time() + 1.5)
            hc = _peak_window_polish(hc, tlim3, pad=3)
        rc = R_of(hc)
        # surrogate Q value
        Lf = _knots(hc)
        M = Lf.max()
        if M > 0:
            Q = np.mean(np.log(Lf + eps * M)) - np.log(M)
        else:
            Q = -np.inf
        print("logflat eps=%.1e Q=%.9f R=%.12f (best %.12f)"
              % (eps, Q, rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc
        if rc > logflat_bestR:
            logflat_best = hc
            logflat_bestR = rc

    # Fill remaining budget with cvar/tie alternation from best
    alphas = [0.0001, 0.00003]
    k = 0
    while time.process_time() < deadline - 1.0:
        alpha = alphas[k % 2]
        k += 1
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hc = _lbfgs_custom(best, lambda hh: _fun_grad_cvar(hh, alpha),
                           tlim, maxiter=120)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 2.0)
            hc = _full_lbfgs(hc, tlim2, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim3 = min(deadline - 1.0, time.process_time() + 1.0)
            hc = _peak_window_polish(hc, tlim3, pad=3)
        rc = R_of(hc)
        print("fill a=%.5f R=%.9f (best %.9f)" % (alpha, rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, logflat %.12f, N=%d)"
          % (bestR, startR, logflat_bestR, best.size))

    return {"best": best, "alternative": logflat_best}

import numpy as np
import time
from scipy.optimize import minimize


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.size == 0:
        return -1.0
    Lm = L.max()
    if Lm <= 0:
        return -1.0
    # ||f*f||_2^2 = sum (L_j^2 + L_j L_{j+1} + L_{j+1}^2)/3 over padded knots
    Lp = np.concatenate(([0.0], L, [0.0]))
    a = Lp[:-1]
    b = Lp[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = (s * s) * Lm
    if den <= 0:
        return -1.0
    return num / den


def _seed_from_params(p, N0):
    cap, b, AL, AR, pL, pR, eL, eR, A, c, w = p
    x = (np.arange(N0) + 0.5) / N0
    f = b + AL * np.power(x + eL, -pL) + AR * np.power(1.0 - x + eR, -pR)
    f = f + A * np.exp(-((x - c) ** 2) / (2.0 * w * w))
    f = np.minimum(f, cap)
    f = np.maximum(f, 0.0)
    return f


def _sample_params(rng):
    logu = lambda lo, hi: np.exp(rng.uniform(np.log(lo), np.log(hi)))
    return np.array([
        logu(1.0, 100.0),      # cap
        logu(1e-4, 1.0),       # b
        logu(0.01, 3.0),       # AL
        logu(0.01, 3.0),       # AR
        rng.uniform(0.2, 0.8), # pL
        rng.uniform(0.2, 0.8), # pR
        logu(1e-4, 0.1),       # eL
        logu(1e-4, 0.1),       # eR
        rng.uniform(0.0, 5.0), # A
        rng.uniform(0.15, 0.85), # c
        logu(0.01, 0.2),       # w
    ])


def _lift(h, Nnew):
    """Mass-preserving linear interpolation of cumulative mass, constant on cells."""
    h = np.asarray(h, dtype=float)
    N = h.size
    if N == Nnew:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nnew)
    xn = (np.arange(Nnew) + 0.5) / Nnew
    cm = np.interp(xn, (np.arange(N) + 0.5) / N, c[:-1] + 0.5 * h)
    # derivative -> heights
    edges = np.concatenate(([0.0], np.cumsum(np.full(Nnew, total / Nnew))))
    # simpler: sample cumulative at cell edges
    xe = np.linspace(0, 1, Nnew + 1)
    ce = np.interp(xe, np.linspace(0, 1, N + 1), c)
    hn = np.diff(ce) * Nnew
    hn = np.maximum(hn, 0.0)
    if hn.sum() <= 0:
        return np.ones(Nnew)
    return hn


def _lbfgs_custom(h0, budget, deadline):
    """L-BFGS on log-heights with numerical gradient, exact R objective."""
    h0 = np.asarray(h0, dtype=float)
    N = h0.size
    eps = 1e-6
    y0 = np.log(np.maximum(h0, eps))

    def obj(y):
        h = np.exp(y)
        return -_R_of(h)

    def grad(y):
        g = np.zeros_like(y)
        base = obj(y)
        for i in range(N):
            yp = y.copy()
            yp[i] += 1e-5
            g[i] = (obj(yp) - base) / 1e-5
        return g

    try:
        res = minimize(obj, y0, jac=grad, method='L-BFGS-B',
                       options={'maxiter': 200, 'maxfun': 5000})
        if _R_of(np.exp(res.x)) > _R_of(h0):
            return np.exp(res.x)
    except Exception:
        pass
    return h0


def _full_lbfgs(h0, deadline):
    return _lbfgs_custom(h0, 3.0, deadline)


def _peak_window_polish(h0, deadline):
    """Polish cells near the peak of f*f."""
    h = np.asarray(h0, dtype=float).copy()
    N = h.size
    if N < 8:
        return h
    L = np.convolve(h, h)
    k = int(np.argmax(L))
    # window in h-space roughly around k/2
    c = k / 2.0
    w = max(4, N // 20)
    lo = max(0, int(c - w))
    hi = min(N, int(c + w))
    if hi - lo < 3:
        return h
    sub = h[lo:hi]
    best = h.copy()
    bestR = _R_of(best)
    for _ in range(3):
        trial = h.copy()
        trial[lo:hi] = sub * (1.0 + 0.02 * np.random.randn(hi - lo))
        trial = np.maximum(trial, 0.0)
        r = _R_of(trial)
        if r > bestR:
            bestR = r
            best = trial
    return best


def _cvar_polish(h0, alpha, deadline):
    """Smooth-max style polish: reduce weight of knots far below max."""
    h = np.asarray(h0, dtype=float).copy()
    best = h.copy()
    bestR = _R_of(best)
    N = h.size
    for _ in range(20):
        if time.process_time() > deadline:
            break
        L = np.convolve(h, h)
        Lm = L.max()
        if Lm <= 0:
            break
        # gradient-ish: perturb cells where L is near max
        mask = L > (1.0 - alpha) * Lm
        idx = np.where(mask)[0]
        if idx.size == 0:
            break
        trial = h.copy()
        # boost cells contributing to near-max knots
        contrib = np.zeros(N)
        for k in idx:
            for i in range(max(0, k - N + 1), min(N, k + 1)):
                j = k - i
                if 0 <= j < N:
                    contrib[i] += h[j]
        contrib = contrib / (contrib.max() + 1e-12)
        trial = trial * (1.0 + 0.05 * contrib)
        trial = np.maximum(trial, 0.0)
        r = _R_of(trial)
        if r > bestR:
            bestR = r
            best = trial
            h = trial
        else:
            h = best
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.0
    rng = np.random.default_rng(12345)

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = _R_of(best)

    try:
        N0 = 512
        # (a) sample seed params
        n_samples = 200
        scored = []
        for _ in range(n_samples):
            if time.process_time() > deadline - 40:
                break
            p = _sample_params(rng)
            try:
                f = _seed_from_params(p, N0)
                r = _R_of(f)
                if r > 0:
                    scored.append((r, p))
            except Exception:
                continue
        scored.sort(key=lambda t: -t[0])
        top = scored[:8]

        # refine with Nelder-Mead
        refined = []
        for r0, p0 in top:
            if time.process_time() > deadline - 30:
                break
            try:
                def negR(p):
                    try:
                        return -_R_of(_seed_from_params(p, N0))
                    except Exception:
                        return 1e9
                res = minimize(negR, p0, method='Nelder-Mead',
                               options={'maxiter': 300, 'xatol': 1e-4, 'fatol': 1e-6})
                pr = res.x
                rr = -res.fun
                refined.append((rr, pr))
            except Exception:
                refined.append((r0, p0))
        refined.sort(key=lambda t: -t[0])
        if refined:
            rr, pr = refined[0]
            try:
                fbest = _seed_from_params(pr, N0)
                print("seed R=%.6f params=%s" % (rr, np.array2string(pr, precision=3)))
                if _R_of(fbest) > bestR:
                    bestR = _R_of(fbest)
                    best = fbest
            except Exception:
                pass

        if best is None:
            best = np.ones(50)
            bestR = _R_of(best)

        # (b) lift to 2048 then 8192
        for Nlvl in (2048, 8192):
            if time.process_time() > deadline - 20:
                break
            try:
                hl = _lift(best, Nlvl)
                rl = _R_of(hl)
                print("lift N=%d R=%.6f" % (Nlvl, rl))
                cand = hl
                if time.process_time() < deadline - 12:
                    cand2 = _lbfgs_custom(cand, 5.0, deadline - 10)
                    if _R_of(cand2) > _R_of(cand):
                        cand = cand2
                if time.process_time() < deadline - 6:
                    cand3 = _full_lbfgs(cand, deadline - 5)
                    if _R_of(cand3) > _R_of(cand):
                        cand = cand3
                if time.process_time() < deadline - 3:
                    cand4 = _peak_window_polish(cand, deadline - 2)
                    if _R_of(cand4) > _R_of(cand):
                        cand = cand4
                rc = _R_of(cand)
                print("after polish N=%d R=%.6f" % (Nlvl, rc))
                if rc > bestR:
                    bestR = rc
                    best = cand
            except Exception as e:
                print("lift error:", e)
                continue

        # (c) cvar polish at N=8192
        if best is not None and best.size >= 100:
            for alpha in (0.003, 0.001, 0.0003):
                if time.process_time() > deadline - 1:
                    break
                try:
                    cand = _cvar_polish(best, alpha, deadline - 0.5)
                    rc = _R_of(cand)
                    if rc > bestR:
                        bestR = rc
                        best = cand
                        print("cvar alpha=%.4f R=%.6f" % (alpha, rc))
                except Exception:
                    continue

    except Exception as e:
        print("outer error:", e)

    if best is None or best.size == 0 or not np.all(np.isfinite(best)) or best.sum() <= 0:
        best = np.ones(50)

    print("final R=%.6f N=%d" % (_R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _block_mean(h, Nq):
    n = h.size
    if Nq >= n:
        return h.copy()
    edges = np.linspace(0, n, Nq + 1)
    idx = np.round(edges).astype(int)
    out = np.zeros(Nq)
    for i in range(Nq):
        a, b = idx[i], idx[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _cum_lift(hq, N):
    Nq = hq.size
    if Nq >= N:
        return hq.copy()
    cq = np.concatenate(([0.0], np.cumsum(hq)))
    xq = np.linspace(0.0, 1.0, Nq + 1)
    x = np.linspace(0.0, 1.0, N + 1)
    c = np.interp(x, xq, cq)
    h = np.diff(c)
    return np.clip(h, 0, None)


def _upsample2(h):
    n = h.size
    out = np.zeros(2 * n)
    out[0::2] = h
    out[1::2] = h
    ker = np.array([0.25, 0.5, 0.25])
    sm = np.convolve(out, ker, mode='same')
    return sm


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Alternative track: block-mean down to smaller N, optimize, lift back.
    alt = None
    altR = -1.0
    if best.size > 2000:
        Nq = max(821, best.size // 4)
        hq = _block_mean(best, Nq)
        hq = _rescale(hq)
        mid = t0 + budget_seconds * 0.35
        hq = _lbfgs_block(hq, np.arange(hq.size), 300, mid, tie=True)
        hl = _cum_lift(hq, best.size)
        hl = _rescale(hl)
        hl = _lbfgs_block(hl, np.arange(hl.size), 200,
                          t0 + budget_seconds * 0.55, tie=True)
        altR = R_of(hl)
        alt = hl
        print("alt R=%.12f (N=%d)" % (altR, alt.size))
        if altR > bestR + 1e-15:
            best, bestR = alt.copy(), altR

    # Main polish: alternate full-array tie L-BFGS and peak-window polish.
    pads = [0.05, 0.03, 0.02, 0.01]
    pi = 0
    while time.process_time() < deadline - 2.0:
        if time.process_time() < deadline - 2.0:
            h = _lbfgs_block(best, np.arange(best.size), 150,
                             min(deadline - 1.5, time.process_time() + 4.5),
                             tie=True)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
        if time.process_time() < deadline - 1.0:
            pad = pads[pi % len(pads)]
            pi += 1
            win = _peak_window(best, pad_frac=pad, extra=96)
            h = _lbfgs_block(best, win, 300,
                             min(deadline - 0.5, time.process_time() + 3.0),
                             tie=True)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r

    if time.process_time() < deadline - 0.5:
        h = _lbfgs_block(best, np.arange(best.size), 200,
                         deadline - 0.2, tie=True)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt is not None and alt.size != best.size and altR <= startR + 1e-14:
        result["alternative"] = alt
    elif bestR <= startR + 1e-14 and start is not None and alt is None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _coarse_upsample(h, N2):
    """Resample a coarser profile onto N2 steps by linear interp on cumulative mass."""
    n = h.size
    if n == N2:
        return h.copy()
    xo = (np.arange(n) + 0.5) / n
    xn = (np.arange(N2) + 0.5) / N2
    return np.interp(xn, xo, h)


def _refine_full(cur, deadline, iters=2):
    h = cur
    for _ in range(iters):
        if time.process_time() >= deadline - 1.0:
            break
        for beta in (120.0, 60.0, 30.0, 15.0):
            if time.process_time() >= deadline - 0.5:
                break
            c = _lbfgs_sm(h, beta, maxiter=250, deadline=deadline)
            if R_of(c) > R_of(h):
                h = c
        if time.process_time() < deadline - 0.5:
            c = _lbfgs_log(h, maxiter=600, deadline=deadline)
            if R_of(c) > R_of(h):
                h = c
        for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
            if time.process_time() >= deadline - 0.5:
                break
            c = _window_polish_peak(h, deadline, frac, extra, maxiter=400)
            if R_of(c) > R_of(h):
                h = c
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(64)
        best_r = R_of(best)

    alternative = None
    alt_r = -1.0
    cur = best.copy()
    cur_r = best_r

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand.copy(), r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # ---------- New idea: coarse-to-fine multiscale restarts ----------
    # Build a coarser profile from `cur`, optimise there (cheap, escapes local minima),
    # then upsample back and polish. This is genuinely different from the base's
    # smooth/block perturbations, which stay at fixed N.
    if start_arr is not None and time.process_time() < hard_end - 4.0:
        n0 = cur.size
        for fac in (8, 4, 2):
            if time.process_time() >= hard_end - 3.0:
                break
            Nc = max(64, n0 // fac)
            hc = _coarse_upsample(cur, Nc)
            # short smoothing ladder at coarse resolution
            for beta in (80.0, 40.0):
                if time.process_time() >= hard_end - 2.0:
                    break
                c = _lbfgs_sm(hc, beta, maxiter=200, deadline=hard_end)
                if R_of(c) >= R_of(hc):
                    hc = c
            if time.process_time() < hard_end - 2.0:
                c = _lbfgs_log(hc, maxiter=400, deadline=hard_end)
                if R_of(c) >= R_of(hc):
                    hc = c
            # upsample back to full N and refine
            hf = _coarse_upsample(hc, n0)
            hf = _refine_full(hf, min(hard_end, time.process_time() + max(
                4.0, (hard_end - time.process_time()) * 0.5)), iters=1)
            _consider(hf, R_of(hf))
        print("coarse-to-fine R=%.6f" % best_r)

    # ---------- Exploit full budget on the best we have ----------
    try:
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra, maxiter=400)
                if R_of(c) > R_of(h):
                    h = c
            _consider(h, R_of(h))
            if time.process_time() >= hard_end - 1.0:
                break
        print("final R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if start_arr is not None and best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None:
        if alt_r > best_r:
            return {"best": alternative, "alternative": best}
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = max(1, int(round((1.0 - q) * n)))
    if k >= n:
        k = n - 1
    idx = np.argpartition(-Lf, k - 1)[:k]
    Mq = Lf[idx].mean()
    if Mq <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[idx] += 1.0 / (Mq * k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Mq)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, cvar_q=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if cvar_q is not None:
        fg = (lambda hh: _fun_grad_cvar(hh, cvar_q))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _deficit_free(h, frac=0.15):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(h.size)
    gLf = (M - 2.0 * Lf) / M
    s = np.abs(_backprop(gLf, h))
    N = h.size
    k = max(1, int(frac * N))
    if k >= N:
        return np.arange(N)
    idx = np.argpartition(-s, k - 1)[:k]
    return np.sort(idx)


def _nearmax_frac_tight(h, frac=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _snap_blocks(h, k):
    """Rasterise h to k equal blocks via block means; returns (k,)."""
    n = h.size
    if n == k:
        return h.copy()
    if n % k == 0:
        return h.reshape(k, n // k).mean(axis=1)
    edges = np.linspace(0, n, k + 1)
    out = np.empty(k)
    for i in range(k):
        lo = int(np.floor(edges[i]))
        hi = int(np.floor(edges[i + 1]))
        if hi <= lo:
            hi = lo + 1
        out[i] = h[lo:hi].mean()
    return out


def _lift_refine(h, k, deadline, iters=250):
    """Snap h to k blocks, refine, expand back, polish. Returns (N-array, R)."""
    hk = _snap_blocks(h, k)
    hk = _rescale(hk)
    hk = _polish_ladder(hk, deadline, betas=(1e6, 1e7, 0.0), iters=iters)
    hk = _peak_ladder(hk, deadline, pads=(0.15, 0.08, 0.04), iters=iters)
    # expand to original size (nearest-neighbour style repeat)
    n = h.size
    if n % k == 0:
        hl = np.repeat(hk, n // k)
    else:
        edges = np.linspace(0, n, k + 1)
        hl = np.empty(n)
        for i in range(k):
            lo = int(np.floor(edges[i]))
            hi = int(np.floor(edges[i + 1]))
            if hi <= lo:
                hi = lo + 1
            hl[lo:hi] = hk[i]
    hl = _polish_ladder(hl, deadline, betas=(1e6, 1e7), iters=iters)
    return hl


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    N0 = best.size

    # ---- Phase A: multiresolution snap-and-lift ----
    # Coarse representations of the same shape, refined at low resolution then
    # lifted back. This can escape local optima the full-resolution LBFGS
    # cannot, because at low resolution the whole peak is a single coordinate.
    if N0 >= 64 and time.process_time() < deadline - 4.0:
        for k in (64, 128, 256, 512):
            if k >= N0:
                break
            if time.process_time() >= deadline - 4.0:
                break
            stage_deadline = min(deadline - 2.0,
                                 time.process_time() + budget_seconds * 0.10)
            hl = _lift_refine(best, k, stage_deadline, iters=200)
            r = R_of(hl)
            improved = offer(hl, 'lift_k%d' % k)
            print("lift k=%d R=%.9f (best %.9f) improved=%s"
                  % (k, r, bestR, improved))

    # ---- Phase CVaR ladder ----
    cvar_deadline = min(deadline - 2.0,
                        t0 + budget_seconds * 0.55)
    qs = (0.99, 0.995, 0.999, 0.9999)
    work = best.copy()
    for q in qs:
        if time.process_time() >= cvar_deadline - 1.5:
            break
        ht = _lbfgs_all_pos(work, 200, cvar_deadline, cvar_q=q)
        rc = R_of(ht)
        nm = _nearmax_frac_tight(ht, 0.999)
        improved = offer(ht, 'cvar_q%.4f' % q)
        print("cvar q=%.4f R=%.9f (best %.9f) nearmax0.1%%=%.4f improved=%s"
              % (q, rc, bestR, nm, improved))
        if rc > R_of(work):
            work = ht

    # ---- Peak-window polish ----
    if time.process_time() < cvar_deadline - 1.0:
        ht = _peak_ladder(best, cvar_deadline, pads=(0.10, 0.05, 0.03),
                          iters=300)
        offer(ht, 'peak_cvar')

    # ---- Deficit-sensitivity rounds ----
    deficit_deadline = deadline - 4.0
    for rnd in range(3):
        if time.process_time() >= deficit_deadline - 1.5:
            break
        free = _deficit_free(best, frac=0.15)
        if free.size == 0:
            break
        ht = _lbfgs_block(best, free, 300, deficit_deadline, beta=1e6)
        ht = _lbfgs_block(ht, free, 300, deficit_deadline, beta=0.0)
        ht = _peak_ladder(ht, deficit_deadline, pads=(0.08, 0.05), iters=250)
        r = R_of(ht)
        improved = offer(ht, 'deficit_%d' % rnd)
        print("deficit round=%d freed=%d R=%.9f (best %.9f) improved=%s"
              % (rnd, free.size, r, bestR, improved))

    # ---- Final high-beta sharpening ----
    ht = _polish_ladder(best, deadline - 0.8,
                        betas=(1e8, 1e9, 1e10, 0.0), iters=300)
    offer(ht, 'finalhi')
    ht2 = _peak_ladder(best, deadline - 0.4, pads=(0.06, 0.04), iters=250)
    offer(ht2, 'finalpeak')

    if start_best is not None and start_bestR > bestR + 1e-14:
        best, bestR = start_best.copy(), start_bestR
        print("reverted to start R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "nearmax5=%.4f, nearmax0.1%%=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best),
             _nearmax_frac_tight(best, 0.999)))

    result = {"best": best}
    if (alt_best is not None and alt_best.size == best.size
            and alt_bestR < bestR):
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.5, extra=512):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _upsample(h, Nnew):
    """Resample step function h onto Nnew steps preserving cumulative mass."""
    N = h.size
    if Nnew == N:
        return h.copy()
    cs = np.concatenate(([0.0], np.cumsum(h)))
    xf = np.linspace(0.0, N, Nnew + 1)
    Sf = np.interp(xf, np.arange(N + 1, dtype=float), cs)
    g = np.diff(Sf)
    return np.clip(g, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    altR = -1.0

    def consider(h, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(h)
        print("%s: R=%.12f frac=%.4f" % (tag, r, _frac_near_max(h, 1e-3)))
        if r > altR:
            altR, alt_best = r, h.copy()
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Key new idea: the flat top of f*f is the active constraint. To push R
    # higher we need the flat region to be as wide as possible relative to
    # the whole support while keeping ||f*f||_2^2 high. The existing code
    # only polishes locally. Here we do a multi-resolution cycle:
    # upsample to a finer grid, polish globally, which allows the flat top
    # to grow and the tails to re-organize, then continue at fine scale.

    # Stage A: windowed tie polish at current N (quick warm-up)
    win = _peak_window(best, tol=0.999, pad_frac=0.6, extra=1024)
    win_set = np.zeros(N, dtype=bool)
    win_set[win] = True
    stride = max(1, N // 512)
    outside = np.flatnonzero(~win_set)
    if outside.size:
        win_set[outside[::stride]] = True
    free = np.flatnonzero(win_set)

    t_cap = min(deadline - 40.0, time.process_time() + 6.0)
    if time.process_time() < deadline - 40.0:
        h1 = _lbfgs_block(best, free, 400, t_cap, tie=True)
        consider(h1, "stageA window tie")

    # Stage B: refine on a finer grid (2x upsample), global polish.
    # Finer grid = more degrees of freedom for the flat top to grow.
    if time.process_time() < deadline - 25.0:
        N2 = min(2 * N, 400000)
        h_up = _upsample(best, N2)
        h_up = _rescale(h_up)
        r_up = R_of(h_up)
        print("stageB upsample N=%d: R=%.12f" % (N2, r_up))
        if r_up > bestR:
            best, bestR = h_up, r_up
        # global polish at finer grid
        t_cap = min(deadline - 15.0, time.process_time() + 10.0)
        if time.process_time() < deadline - 15.0:
            hf = _lbfgs_block(best, np.arange(best.size), 250, t_cap, tie=True)
            consider(hf, "stageB global polish N=%d" % best.size)

    # Stage C: a second upsample + polish cycle
    if time.process_time() < deadline - 5.0:
        N3 = min(int(best.size * 1.5), 500000)
        h_up = _upsample(best, N3)
        h_up = _rescale(h_up)
        r_up = R_of(h_up)
        print("stageC upsample N=%d: R=%.12f" % (N3, r_up))
        if r_up > bestR:
            best, bestR = h_up, r_up
        t_cap = min(deadline - 2.0, time.process_time() + 4.0)
        if time.process_time() < deadline - 2.0:
            hf = _lbfgs_block(best, np.arange(best.size), 150, t_cap, tie=True)
            consider(hf, "stageC global polish N=%d" % best.size)

    # Stage D: final windowed polish on current grid
    if time.process_time() < deadline - 1.0:
        Nf = best.size
        win = _peak_window(best, tol=0.999, pad_frac=0.7, extra=1024)
        t_cap = min(deadline - 0.5, time.process_time() + 2.0)
        hw = _lbfgs_block(best, win, 200, t_cap, tie=True)
        consider(hw, "stageD final window tie")

    if start is not None and bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, deadline, maxiter=200, fun=None):
    if fun is None:
        fun = _fun_grad_tie
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _upsample_mass(h, m):
    """Resample h (mass-preserving) to m cells."""
    n = h.size
    if m == n:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(m + 1, dtype=float) * (n / m)
    C2 = np.interp(x, np.arange(n + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def _stats(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return "degenerate"
    frac = L / mx
    s1 = np.mean(frac >= 0.999)
    s2 = np.mean(frac >= 0.99)
    s3 = np.mean(frac >= 0.95)
    arg = int(np.argmax(L)) / (L.size - 1)
    zeros = np.mean(h <= 0)
    ratio = h.max() / (h.mean() + 1e-30)
    k = max(1, int(0.01 * h.size))
    top = np.sort(h)[-k:].sum() / (h.sum() + 1e-30)
    return ("zeros=%.1f%% max/mean=%.2f near-max 0.1%%/1%%/5%%=%.2f%%/%.2f%%/%.2f%% "
            "argmax=%.3f top1%%mass=%.3f" %
            (100 * zeros, ratio, 100 * s1, 100 * s2, 100 * s3, arg, top))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(98765)

    best = None
    bestR = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best = _rescale(s.copy())
            bestR = R_of(best)
            print("start R=%.9f N=%d" % (bestR, best.size))

    # If no start (or tiny), build a seed.
    if best is None or bestR <= 0:
        N0 = 2048
        M = 48
        w = rng.uniform(8.0, 80.0, size=M); w = w / w.sum() * N0
        heights = np.exp(rng.normal(0.0, 1.5, size=M)) * (w ** -0.5)
        h = np.zeros(N0)
        edges = np.concatenate(([0.0], np.cumsum(w)))
        for i in range(M):
            a = int(round(edges[i])); b = int(round(edges[i + 1]))
            if b <= a: b = a + 1
            a = min(a, N0 - 1); b = min(b, N0)
            h[a:b] = heights[i]
        best = _rescale(h); bestR = R_of(best)

    alt = None; altR = -1.0

    def consider(h, tag=""):
        nonlocal best, bestR, alt, altR
        h = _rescale(h)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("ACCEPT %s R=%.9f N=%d" % (tag, bestR, h.size))
            return True
        elif r > altR and (alt is None or h.size != best.size):
            alt, altR = h.copy(), r
        return False

    def remaining():
        return deadline - time.process_time()

    # ---- refine the start: log-space L-BFGS at its own resolution ----
    if remaining() > 3.0:
        end = min(deadline - 1.0, time.process_time() + 8.0)
        h = _lbfgs_log(best, end, maxiter=250)
        consider(h, "refine-n")

    # ---- increase resolution and refine (mass-preserving upsampling) ----
    n0 = best.size
    for target in [n0 * 2, n0 * 4, n0 * 8]:
        if remaining() < 6.0:
            break
        if target > 1000000:
            target = 1000000
        if target <= best.size:
            continue
        h = _upsample_mass(best, target)
        end = min(deadline - 2.0, time.process_time() + 9.0)
        h = _lbfgs_log(h, end, maxiter=250)
        consider(h, "upsample-%d" % target)

    # ---- randomized split restarts (fold back down) ----
    sigmas = [0.15, 0.30, 0.10, 0.05]
    for sigma in sigmas:
        if remaining() < 5.0:
            break
        n = best.size
        c = best.copy()
        eps = rng.normal(0.0, sigma, size=n)
        h2 = np.zeros(2 * n)
        h2[0::2] = c * (1.0 + eps)
        h2[1::2] = c * (1.0 - eps)
        h2 = _rescale(np.clip(h2, 0, None))
        end = min(deadline - 2.0, time.process_time() + 4.0)
        h2 = _lbfgs_log(h2, end, maxiter=200)
        hf = 0.5 * (h2[0::2] + h2[1::2])
        consider(hf, "split-%.2f" % sigma)

    # ---- final polish loop until near the deadline ----
    while remaining() > 1.5:
        end = min(deadline - 0.5, time.process_time() + 4.0)
        h_t = _lbfgs_log(best, end, maxiter=200)
        if not consider(h_t, "polish"):
            # tiny random kick to escape
            if remaining() < 3.0:
                break
            h_k = np.clip(best * (1.0 + rng.normal(0, 0.02, best.size)), 0, None)
            end = min(deadline - 0.5, time.process_time() + 3.0)
            h_k = _lbfgs_log(_rescale(h_k), end, maxiter=150)
            if not consider(h_k, "kick"):
                break

    print("final R=%.9f N=%d" % (bestR, best.size))
    print("stats: " + _stats(best))

    result = {"best": best}
    if alt is not None and altR > 0:
        result["alternative"] = alt
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _refine_peak_region(h, deadline, budget_seconds, max_rounds=40):
    best = h.copy()
    bestR = R_of(best)
    pads = [0.15, 0.10, 0.07, 0.05, 0.035, 0.025, 0.018, 0.012]
    rnd = 0
    while time.process_time() < deadline - 0.8 and rnd < max_rounds:
        pad = pads[rnd % len(pads)]
        rnd += 1
        now = time.process_time()
        slice_dl = min(now + 0.20 * budget_seconds, deadline - 0.6)
        if slice_dl <= now + 0.3:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        if win.size < 4:
            break
        h1 = _lbfgs_block(best, win, 250, slice_dl, beta=1e7)
        r1 = R_of(h1)
        improved = False
        if r1 > bestR + 1e-15:
            best, bestR = h1, r1
            improved = True
        if time.process_time() < slice_dl - 0.3:
            h2 = _lbfgs_all_pos(best, 200, slice_dl, beta=1e7)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2, r2
                improved = True
        if time.process_time() < slice_dl - 0.3 and (rnd % 3 == 0 or not improved):
            h3 = _lbfgs_all_pos(best, 200, slice_dl, beta=0.0)
            r3 = R_of(h3)
            if r3 > bestR + 1e-15:
                best, bestR = h3, r3
                improved = True
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # NEW: immediate peak refinement (dominant gains come from local polish)
    peak_deadline = t0 + budget_seconds * 0.55
    if time.process_time() < peak_deadline - 1.0:
        hpk, rpk = _refine_peak_region(best, peak_deadline, budget_seconds,
                                       max_rounds=80)
        if rpk > bestR + 1e-14:
            best, bestR, origin = hpk, rpk, 'peak0'
            print("peak0 NEW BEST R=%.9f" % bestR)
        elif rpk > alt_bestR:
            alt_best, alt_bestR = hpk, rpk

    # short 2N-lift randomized multi-start
    phase3b_end = min(deadline - 4.0, time.process_time() + 0.15 * budget_seconds)
    if time.process_time() < phase3b_end - 1.0 and best.size >= 2:
        n = best.size
        sigmas = [0.02, 0.05, 0.10]
        rnd = 0
        while time.process_time() < phase3b_end - 1.0:
            sigma = sigmas[rnd % 3]
            rnd += 1
            now = time.process_time()
            slice_dl = min(now + 1.5, phase3b_end)
            if slice_dl <= now + 0.3:
                break
            try:
                d = np.clip(sigma * np.random.randn(n), -0.6, 0.6)
                u = np.empty(2 * n)
                u[0::2] = best * (1.0 + d)
                u[1::2] = best * (1.0 - d)
                u = _rescale(u)
                u = _lbfgs_all_pos(u, 100, slice_dl, beta=1e7)
                h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:n]
                if time.process_time() < slice_dl - 0.3:
                    h2 = _lbfgs_all_pos(h2, 150, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 0.3:
                    h2 = _lbfgs_all_pos(h2, 150, slice_dl, beta=1e7)
                r_fold = R_of(h2)
                print("rnd %d sigma=%.2f r_fold=%.9f (best %.9f)" %
                      (rnd, sigma, r_fold, bestR))
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'rnd%d' % rnd
                    print("  rnd NEW BEST R=%.9f" % bestR)
                elif r_fold > alt_bestR:
                    alt_best, alt_bestR = h2.copy(), r_fold
            except Exception as e:
                print("rnd %d exception %s" % (rnd, e))

    # second peak refinement on improved best
    if time.process_time() < deadline - 3.0:
        hpk, rpk = _refine_peak_region(best, deadline - 3.0, budget_seconds,
                                       max_rounds=60)
        if rpk > bestR + 1e-14:
            best, bestR, origin = hpk, rpk, origin + '+peak2'
            print("peak2 NEW BEST R=%.9f" % bestR)
        elif rpk > alt_bestR:
            alt_best, alt_bestR = hpk, rpk

    # final peak pads + beta=0
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _dedup(h, k):
    h = np.asarray(h, dtype=float)
    N = h.size
    M = N // k
    if M < 1:
        return h.copy()
    hh = h[:M * k].reshape(M, k)
    return hh.mean(axis=1)


def _expand(v, k):
    return np.repeat(np.asarray(v, dtype=float), k)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _resample(h, M):
    """Resample h (piecewise-constant step function) onto M equal steps
    over the same total support, preserving the integral."""
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    # cumulative integral at original breakpoints
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    # new breakpoints in original-index coordinates
    xs = np.linspace(0.0, N, M + 1)
    vals = np.interp(xs, np.arange(N + 1, dtype=float), c)
    out = np.diff(vals) * (M / N)
    return np.clip(out, 0.0, None)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    alt_best = None
    alt_R = 0.0
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    def consider(arr, tag):
        nonlocal best, bestR, alt_best, alt_R, origin
        arr = _rescale(np.clip(arr, 0, None))
        r = R_of(arr)
        if r > bestR + 1e-13:
            best, bestR = arr.copy(), r
            origin = origin + '+' + tag
        elif r > alt_R + 1e-13:
            alt_best, alt_R = arr.copy(), r
        return r

    N0 = best.size

    # ---- NEW: upsampling refinement ----
    # Try refining on a finer grid (2x) to escape the current discretisation.
    def upsample_round(h_full, hR, k, time_frac):
        N = h_full.size
        M = N * k
        if M > 900000:
            return h_full, hR
        v = _resample(h_full, M)
        v = _rescale(v)
        rv = R_of(v)
        print("upsample k=%d: R(v)=%.9f R(full)=%.9f" % (k, rv, hR))
        now = time.process_time()
        rem = deadline - now
        sub_deadline = now + max(0.5, rem * time_frac)
        vbest, vR = v.copy(), rv
        try:
            vbest, vR = run_cycle(v, vR, sub_deadline)
        except Exception as e:
            print("upsample k=%d cycle failed: %s" % (k, e))
        print("upsample k=%d refined: R=%.9f (was %.9f)" % (k, vR, rv))
        # Downsample back to original size
        if vbest.size != N0:
            down = _resample(vbest, N0)
            down = _rescale(down)
        else:
            down = _rescale(vbest)
        rdown = R_of(down)
        print("upsample k=%d down to N0: R=%.9f" % (k, rdown))
        consider(down, 'up%d' % k)
        return best, bestR

    # Try upsampling first (uses remaining budget)
    try:
        if time.process_time() < deadline - 5.0 and N0 < 400000:
            best, bestR = upsample_round(best, bestR, 2, 0.55)
    except Exception as e:
        print("upsample failed: %s" % e)

    # ---- Full-length polish ----
    try:
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("full lbfgs beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+full0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+tight7'
    except Exception as e:
        print("full polish failed: %s" % e)

    # ---- Final tight polish ----
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 250, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("final tight beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                origin = origin + '+ft0'
    except Exception as e:
        print("final tight failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best if alt_best is None else alt_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _build_basis(N, K):
    i = np.arange(N, dtype=float)
    B = np.empty((K, N))
    for k in range(1, K + 1):
        B[k - 1] = np.cos(2.0 * np.pi * k * i / N)
    return B


def _h_from_a(h0, B, a):
    logmod = a @ B
    h = h0 * np.exp(np.clip(logmod, -30.0, 30.0))
    return _rescale(h)


def _proj_grad(h0, B, a):
    h = _h_from_a(h0, B, a)
    val, g = _fun_grad_tie(h)
    ga = B @ (g * h)
    return val, ga, h


def _subspace_newton(h0, B, deadline, max_iters=15, hstep=1e-4):
    K = B.shape[0]
    a = np.zeros(K)
    val, ga, h = _proj_grad(h0, B, a)
    bestR = R_of(h)
    best_h = h
    for it in range(max_iters):
        if time.process_time() > deadline - 0.5:
            break
        H = np.empty((K, K))
        for k in range(K):
            if time.process_time() > deadline - 0.5:
                return best_h, bestR
            ap = a.copy(); ap[k] += hstep
            am = a.copy(); am[k] -= hstep
            _, gap, _ = _proj_grad(h0, B, ap)
            _, gam, _ = _proj_grad(h0, B, am)
            H[:, k] = (gap - gam) / (2.0 * hstep)
        H = 0.5 * (H + H.T)
        lam = 0.0
        da = None
        for _ in range(30):
            try:
                A = H + lam * np.eye(K)
                da = np.linalg.solve(A, -ga)
            except Exception:
                lam = max(lam * 2.0, 1e-6)
                continue
            pred = -(ga @ da) - 0.5 * (da @ H @ da)
            if pred > 0 and np.max(np.abs(da)) <= 0.05:
                break
            lam = max(lam * 2.0, 1e-4)
            if lam > 1e6:
                da = None
                break
        if da is None:
            break
        step = 1.0
        improved = False
        for _ in range(8):
            a_new = a + step * da
            h_new = _h_from_a(h0, B, a_new)
            r_new = R_of(h_new)
            if r_new > bestR + 1e-14:
                a = a_new
                bestR = r_new
                best_h = h_new
                improved = True
                break
            step *= 0.5
        if not improved:
            break
        val, ga, h = _proj_grad(h0, B, a)
        if np.max(np.abs(ga)) < 1e-9:
            break
    return best_h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size

    # Phase 1: CVaR-driven ascent to escape single-peak-tie local maxima;
    # this raises the "shoulder" of f*f and often lets the exact tie-gradient
    # polish find a strictly better point.
    alphas = [0.30, 0.15, 0.08, 0.04, 0.02]
    cur = best.copy()
    for al in alphas:
        if time.process_time() > deadline - 1.0:
            break
        tlim = min(deadline - 0.8, time.process_time() + 4.0)
        hc = _lbfgs_custom(cur, lambda hh, a=al: _fun_grad_cvar(hh, a),
                           tlim, maxiter=80)
        rc = R_of(hc)
        print("cvar a=%.2f R=%.9f (cur %.9f)" % (al, rc, bestR))
        if rc > bestR + 1e-15:
            best = hc; bestR = rc; cur = hc.copy()
        else:
            cur = hc  # continue from CVaR point anyway

    # Phase 2: exact tie-gradient polish
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.6, time.process_time() + 6.0)
        hf = _full_lbfgs(best, tlim, maxiter=200)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best = hf; bestR = rf
            print("polish R=%.9f" % bestR)

    # Phase 3: subspace Newton on smooth basis, then re-polish
    h0 = best.copy()
    Ks = [16, 64, 32, 96]
    ki = 0
    while time.process_time() < deadline - 2.0:
        K = Ks[ki % len(Ks)]
        ki += 1
        if K >= N:
            continue
        B = _build_basis(N, K)
        tlim = min(deadline - 1.5, time.process_time() + 5.0)
        h_new, r_new = _subspace_newton(h0, B, tlim)
        print("K=%d R=%.9f (best %.9f)" % (K, r_new, bestR))
        if r_new > bestR + 1e-14:
            best = h_new; bestR = r_new; h0 = best.copy()
            if time.process_time() < deadline - 1.5:
                tlim = min(deadline - 1.0, time.process_time() + 4.0)
                hf = _full_lbfgs(best, tlim, maxiter=150)
                rf = R_of(hf)
                if rf > bestR + 1e-15:
                    best = hf; bestR = rf; h0 = best.copy()

    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.8, time.process_time() + 5.0)
        hf = _full_lbfgs(best, tlim, maxiter=200)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best = hf; bestR = rf

    if bestR < startR - 1e-15:
        print("final R=%.12f (start %.12f, N=%d) [kept start]"
              % (startR, startR, start_best.size))
        return {"best": start_best, "alternative": best}

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    if bestR > startR + 1e-12:
        return {"best": best, "alternative": start_best}
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    Lr = Lf / mx
    Lp = Lr ** p
    Sp = Lp.sum()
    if Sp <= 0:
        Sp = 1e-300
    gLf = -dq / num
    gLf += (Lr ** (p - 1.0)) / (mx * Sp)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (1.0 / p) * np.log(Sp)
    return val, grad


def _fun_grad_shoulder(h, thr, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    u = Lf / mx
    phi = np.maximum(0.0, thr - u)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    n = Lf.size
    gLf += lam * (-2.0 * phi / (n * mx))
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx) + lam * np.mean(phi ** 2)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=200):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _pnorm_lbfgs(h0, p, deadline, maxiter=200):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_pnorm(hh, p),
                         deadline, maxiter=maxiter)


def _shoulder_lbfgs(h0, thr, lam, deadline, maxiter=200):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_shoulder(hh, thr, lam),
                         deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window_polish_frac(h, deadline, frac):
    n = h.size
    pad = max(3, n // frac)
    return _peak_window_polish(h, deadline, pad=pad)


def _shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    u = Lf / mx
    return (np.mean(u >= 0.999), np.mean(u >= 0.99), np.mean(u >= 0.95))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    h_cur = h0.copy()
    R_cur = startR

    # reserve time for final polish
    polish_reserve = max(6.0, budget_seconds * 0.15)
    stage_deadline = deadline - polish_reserve

    # Stage ladder: shoulder hinge with varying thr and lam
    thr_list = [0.995, 0.99, 0.98, 0.96]
    lam_list = [3.0, 30.0, 300.0]
    for thr in thr_list:
        for lam in lam_list:
            if time.process_time() >= stage_deadline - 0.5:
                break
            tl = min(stage_deadline, time.process_time() + 2.0)
            h_try = _shoulder_lbfgs(h_cur, thr, lam, tl, maxiter=200)
            tl2 = min(stage_deadline, time.process_time() + 1.2)
            h_try = _full_lbfgs(h_try, tl2, maxiter=200)
            Rt = R_of(h_try)
            if Rt > R_cur + 1e-12:
                h_cur = h_try
                R_cur = Rt
                if Rt > bestR:
                    best = h_try.copy()
                    bestR = Rt
            s01, s1, s5 = _shares(h_cur)
            print("thr=%.3f lam=%5.1f R=%.9f (best %.9f) sh=%.4f/%.4f/%.4f"
                  % (thr, lam, Rt, bestR, s01, s1, s5))
        if time.process_time() >= stage_deadline - 0.5:
            break

    # p-norm continuation
    for p in (64, 256, 1024, 4096):
        if time.process_time() >= stage_deadline - 0.5:
            break
        tl = min(stage_deadline, time.process_time() + 2.0)
        h_try = _pnorm_lbfgs(h_cur, p, tl, maxiter=200)
        tl2 = min(stage_deadline, time.process_time() + 1.0)
        h_try = _full_lbfgs(h_try, tl2, maxiter=200)
        Rt = R_of(h_try)
        if Rt > R_cur + 1e-12:
            h_cur = h_try
            R_cur = Rt
            if Rt > bestR:
                best = h_try.copy()
                bestR = Rt
        s01, s1, s5 = _shares(h_cur)
        print("p=%5d R=%.9f (best %.9f) sh=%.4f/%.4f/%.4f"
              % (p, Rt, bestR, s01, s1, s5))

    # remaining budget: peak-window polish at multiple scales + final full
    hc = best.copy()
    for frac in (8, 32, 3):
        if time.process_time() >= deadline - 1.0:
            break
        hc = _peak_window_polish_frac(hc, deadline - 0.5, frac)
        Rc = R_of(hc)
        if Rc > bestR:
            best = hc.copy()
            bestR = Rc
        print("polish frac=%d R=%.9f" % (frac, Rc))

    if time.process_time() < deadline - 0.5:
        hc = _full_lbfgs(hc, deadline - 0.3, maxiter=200)
        Rc = R_of(hc)
        if Rc > bestR:
            best = hc.copy()
            bestR = Rc
        print("final full R=%.9f" % Rc)

    alt = hc.copy()
    if R_of(alt) < startR:
        alt = h0.copy()

    s01, s1, s5 = _shares(best)
    print("final R=%.12f (start %.12f, N=%d) sh=%.4f/%.4f/%.4f"
          % (bestR, startR, best.size, s01, s1, s5))
    return {"best": best, "alternative": alt}

