    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _upsample(h, m):
    n = h.size
    if m <= n:
        return h
    xold = np.arange(n, dtype=float)
    xnew = np.linspace(0.0, n - 1.0, m)
    H = np.interp(xnew, xold, h)
    return _rescale(H)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, mx0, m0, near0))

    cur = best.copy()
    curR = bestR

    # ---- Stage A: resolution refinement (upsample then full polish) ----
    N0 = cur.size
    levels = []
    for mult in (1.5, 2.0, 3.0):
        target = int(N0 * mult)
        if target <= 1000000 and target > cur.size:
            levels.append(target)
    levels = levels[:3]

    remaining = max(0.0, deadline - time.process_time())
    weights = [1.0, 1.5, 2.5][:len(levels)]
    tw = sum(weights) if weights else 1.0
    acc = time.process_time()
    level_deadlines = []
    for w in weights:
        acc += remaining * (w / tw)
        level_deadlines.append(min(acc, deadline))

    for li, target in enumerate(levels):
        ldead = level_deadlines[li]
        if time.process_time() >= ldead - 1.0:
            break
        H = _upsample(cur, target)
        H = _full_lbfgs(H, ldead - 0.5, maxiter=400)
        r = R_of(H)
        if r > curR + 1e-13:
            cur, curR = H.copy(), r
            print("  L%d N=%d R=%.7f" % (li, cur.size, curR))
        else:
            print("  L%d N=%d no gain (%.7f)" % (li, H.size, r))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    cur = best.copy()
    curR = bestR

    # ---- Stage B: alternate full/peak polish until deadline ----
    rnd = 0
    while time.process_time() < deadline - 1.0:
        rnd += 1
        sub = min(deadline - 0.5, time.process_time() + 8.0)

        h = _full_lbfgs(cur, sub, maxiter=200)
        r = R_of(h)
        if r > curR + 1e-13:
            cur, curR = h.copy(), r

        if time.process_time() < sub - 0.5:
            h = _peak_window_polish(cur, sub)
            r = R_of(h)
            if r > curR + 1e-13:
                cur, curR = h.copy(), r

        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR
        print("  B%d R=%.7f (best=%.7f) N=%d" % (rnd, curR, bestR, cur.size))

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    c = (m - 1) / 2.0
    n = h.size
    w = max(3, int(pad * n))
    lo = max(0, int(c - w))
    hi = min(n, int(c + w) + 1)
    if hi - lo < 2:
        return np.arange(n)
    return np.arange(lo, hi)


def _prolongate(h, N2):
    N1 = h.size
    if N1 == N2:
        return _rescale(np.clip(h, 0, None))
    M = float(N1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, M, N2 + 1)
    cum_at = np.interp(edges, np.arange(N1 + 1), cum)
    mass = np.diff(cum_at)
    out = mass * (M / N2)
    return _rescale(np.clip(out, 0.0, None))


def _coarsen(h, N2):
    return _prolongate(h, N2)


def _tooth_perturb(h, rng, nteeth=64, sigma=0.06):
    n = h.size
    if n < 3:
        return h.copy()
    left = h[1:-1] >= h[:-2]
    right = h[1:-1] >= h[2:]
    loc = np.flatnonzero(left & right) + 1
    if loc.size == 0:
        return h.copy()
    vals = h[loc]
    k = min(nteeth, loc.size)
    order = np.argsort(-vals)[:k]
    pick = loc[order]
    h2 = h.copy()
    factors = 1.0 + sigma * rng.standard_normal(pick.size)
    h2[pick] = np.clip(h2[pick] * factors, 0.0, None)
    return _rescale(h2)


def _polish(h, deadline, rng, pads=(0.15, 0.07, 0.03)):
    best = h
    bestR = R_of(best)
    cand = _lbfgs_all_pos(best, 300, deadline, tie=True)
    r = R_of(cand)
    if r > bestR:
        best, bestR = cand, r
    for beta in (1e6, 1e8):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _lbfgs_all_pos(best, 100, deadline, beta=beta)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best, pad)
        cand = _lbfgs_block(best, free, 150, deadline, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    return best, bestR


# ---- New helpers for the QR/Legendre comb experiment ----

def _qr_seed(p):
    v = np.zeros(p)
    for j in range(1, p):
        if (j * j) % p in range(p):
            pass
    # proper: nonzero quadratic residues mod p
    res = set((j * j) % p for j in range(1, p))
    for j in range(p):
        if j in res:
            v[j] = 1.0
    return v


def _qr_seed_fast(p):
    v = np.zeros(p)
    sq = (np.arange(1, p) ** 2) % p
    v[np.unique(sq)] = 1.0
    return v


def _count_teeth(h):
    n = h.size
    if n < 3:
        return 0
    left = h[1:-1] >= h[:-2]
    right = h[1:-1] >= h[2:]
    return int(np.sum(left & right))


def _log_lbfgs(v0, maxiter, deadline):
    """Optimize in log-space (v = exp(u)) to keep positivity; return v."""
    if time.process_time() >= deadline - 0.05:
        return np.clip(v0, 0, None)
    v0 = np.clip(v0, 1e-6, None)
    u0 = np.log(v0)

    def f(u):
        v = np.exp(np.clip(u, -30.0, 30.0))
        val, g = _fun_grad_tie(v)
        # chain rule through v = exp(u): dval/du = g * v
        return val, g * v

    cb = _make_cb(deadline - 0.03)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return np.clip(v0, 0, None)
    if res is None:
        return np.clip(v0, 0, None)
    return np.exp(np.clip(res.x, -30.0, 30.0))


def _coarse_search_prime(p, rng, deadline, n_restart=12):
    """Search seeds for prime p; return (best_v, bestR, teeth)."""
    seeds = []
    v_qr = _qr_seed_fast(p)
    seeds.append(v_qr.copy())
    # two-valued seed
    v2 = 1.0 + 0.05 * v_qr
    seeds.append(v2)
    # random jitter restarts around QR
    for _ in range(n_restart):
        jit = np.exp(0.30 * rng.standard_normal(p))
        seeds.append(np.clip(v_qr * jit, 1e-6, None))

    best_v = None
    bestR = -1.0
    for s in seeds:
        if time.process_time() >= deadline - 0.05:
            break
        v = _log_lbfgs(s, 200, deadline)
        r = R_of(v)
        if r > bestR:
            bestR = r
            best_v = v
    if best_v is None:
        best_v = v_qr
        bestR = R_of(best_v)
    teeth = _count_teeth(best_v)
    return best_v, bestR, teeth


def _asym_split_round(h, rng, deadline, sigma=0.25):
    """Pair up steps: h[2i]=c(1+a), h[2i+1]=c(1-a)."""
    n = h.size
    if n < 2:
        return h
    m = n // 2
    c = h[:2 * m].reshape(m, 2).mean(axis=1)
    a = sigma * rng.standard_normal(m)
    a = np.clip(a, -0.95, 0.95)
    h2 = h.copy()
    h2[0:2 * m:2] = c * (1.0 + a)
    h2[1:2 * m:2] = c * (1.0 - a)
    return _rescale(np.clip(h2, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.92 * budget_seconds
    rng = np.random.default_rng(20240607)

    start_arr = None
    startR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.size >= 2 and s.sum() > 0:
            start_arr = s
            startR = R_of(s)
            print("start R=%.9f N=%d" % (startR, s.size))

    if start_arr is None:
        n = 200
        x = (np.arange(n) + 0.5) / n
        h = np.exp(-40.0 * (x - 0.5) ** 2)
        start_arr = _rescale(h)
        startR = R_of(start_arr)
        print("init bump R=%.9f" % startR)

    best = start_arr.copy()
    bestR = startR

    # ---- Phase A: sweep primes, coarse QR comb search ----
    A_end = t0 + 0.55 * budget_seconds
    primes = [61, 67, 71, 73, 79, 83, 89, 97, 101, 103, 107, 109, 113, 127, 131]

    # reference row: current construction's effective prime (teeth count)
    ref_teeth = _count_teeth(_coarsen(start_arr, min(start_arr.size, 16384)))
    print("ref teeth=%d R=%.9f" % (ref_teeth, startR))

    results = []
    for p in primes:
        if time.process_time() >= A_end - 0.5:
            break
        v, r, teeth = _coarse_search_prime(p, rng, A_end, n_restart=12)
        results.append((r, p, v, teeth))
        print("p=%d coarseR=%.9f teeth=%d" % (p, r, teeth))

    if not results:
        # fallback: just polish start
        cand, r = _polish(best, deadline, rng)
        if r > bestR:
            best, bestR = cand, r
        finalR = R_of(best)
        print("final R=%.9f N=%d" % (finalR, best.size))
        if start_arr is not None and startR >= finalR:
            return {"best": start_arr, "alternative": best}
        return best

    results.sort(key=lambda t: -t[0])
    top = results[:3]
    print("top primes: " + ", ".join("p=%d R=%.9f" % (t[1], t[0]) for t in top))

    # ---- Phase B: lift best 3 to full resolution, polish, asym-split ----
    B_end = t0 + 0.97 * budget_seconds
    N_target = 65536
    N_final = 131072

    for (r_coarse, p, v, teeth) in top:
        if time.process_time() >= B_end - 3.0:
            break
        m = max(1, N_target // p)
        h = np.repeat(v, m)
        h = _rescale(np.clip(h, 0, None))
        r0 = R_of(h)
        # full lbfgs tie
        now = time.process_time()
        slice_end = min(B_end - 1.5, now + max(2.0, (B_end - now) * 0.35))
        cand = _lbfgs_all_pos(h, 300, slice_end, tie=True)
        r = R_of(cand)
        if r > r0:
            h = cand
        # peak polish
        for pad in (0.10, 0.04):
            if time.process_time() >= slice_end - 0.5:
                break
            free = _peak_window(h, pad)
            cand = _lbfgs_block(h, free, 150, slice_end, tie=True)
            rr = R_of(cand)
            if rr > R_of(h):
                h = cand
        r65536 = R_of(h)
        print("p=%d lift65536 R=%.9f" % (p, r65536))
        if r65536 > bestR:
            best, bestR = h.copy(), r65536

        # lift to 131072
        if time.process_time() < B_end - 2.0:
            h2 = _prolongate(h, N_final)
            now = time.process_time()
            slice_end2 = min(B_end - 1.0, now + max(2.0, (B_end - now) * 0.5))
            cand = _lbfgs_all_pos(h2, 150, slice_end2, tie=True)
            if R_of(cand) > R_of(h2):
                h2 = cand
            for pad in (0.08, 0.03):
                if time.process_time() >= slice_end2 - 0.5:
                    break
                free = _peak_window(h2, pad)
                cand = _lbfgs_block(h2, free, 150, slice_end2, tie=True)
                if R_of(cand) > R_of(h2):
                    h2 = cand
            r131072 = R_of(h2)
            print("p=%d lift131072 R=%.9f" % (p, r131072))
            if r131072 > bestR:
                best, bestR = h2.copy(), r131072

            # asymmetric-split rounds
            work = h2.copy()
            workR = r131072
            for k in range(6):
                if time.process_time() >= B_end - 1.0:
                    break
                cand = _asym_split_round(work, rng, B_end)
                now = time.process_time()
                s_end = min(B_end - 0.5, now + 2.0)
                cand = _lbfgs_all_pos(cand, 80, s_end, tie=True)
                rc = R_of(cand)
                if rc > workR + 1e-12:
                    work, workR = cand, rc
                    if rc > bestR:
                        best, bestR = cand.copy(), rc
                print("  p=%d split%d R=%.9f bestR=%.9f" % (p, k, workR, bestR))

    # Final polish of best
    if time.process_time() < B_end - 1.0:
        cand = _lbfgs_all_pos(best, 150, B_end, tie=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
            print("final full R=%.9f N=%d" % (bestR, best.size))

    best = _rescale(np.clip(best, 0, None))
    finalR = R_of(best)
    print("final R=%.9f N=%d" % (finalR, best.size))

    if start_arr is not None and startR >= finalR:
        return {"best": start_arr, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    z = np.clip(beta * (Lf - M), -60.0, 60.0)
    w = np.exp(z)
    S = w.sum()
    if S <= 0:
        return _fun_grad(h)
    logLm = M + np.log(S) / beta
    gLf = -dq / num + w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_sm(hh, beta)) if beta else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_sm(hh, beta)) if beta else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _fine_polish(h, deadline):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    lo, hi = _peak_region(cur)
    span = hi - lo
    n = cur.size
    for frac in (0.02, 0.05, 0.10, 0.20):
        if time.process_time() >= deadline - 0.4:
            break
        pad = max(8, int(span * frac))
        lo2 = max(0, lo - pad); hi2 = min(n - 1, hi + pad)
        free = np.arange(lo2, hi2 + 1)
        for beta in (None, 20000.0):
            if time.process_time() >= deadline - 0.4:
                break
            _try(_lbfgs_block(cur, free, maxiter=300, deadline=deadline, beta=beta))
    if time.process_time() < deadline - 0.4:
        _try(_lbfgs_log(cur, maxiter=600, deadline=deadline))
        _try(_lbfgs_log(cur, maxiter=600, deadline=deadline, beta=20000.0))
    return cur, cur_r


def _prolong_mass(h, N2):
    n = h.size
    if N2 <= n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N2)
    edges = np.linspace(0.0, float(n), N2 + 1)
    newc = np.interp(edges, np.arange(n + 1, dtype=float), c)
    h2 = np.diff(newc)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return np.ones(N2)
    return h2


def _perturb_window(h, lo, hi, rng, sigma=0.35):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo)); hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]; c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r + 1e-12:
            best, best_r = cand.copy(), r
        elif r > alt_r + 1e-12:
            alternative = cand.copy(); alt_r = r

    n = base.size

    # Prolong to 256000 (or keep if already >=)
    N2 = max(256000, n)
    hf = _prolong_mass(base, N2)
    hf = _rescale(hf)
    r0 = R_of(hf)
    print("prolonged R=%.7f (base %.7f) N=%d" % (r0, base_r, hf.size))
    _consider(hf, r0)

    if time.process_time() < hard_end - 2.0:
        hp, rp = _fine_polish(hf, hard_end)
        print("fine polish R=%.7f" % rp)
        _consider(hp, rp)
        if rp > r0:
            hf, r0 = hp, rp

    cur = hf; cur_r = r0; n = cur.size

    # Intensified perturbation search with tighter, more numerous windows
    seed = 0
    while time.process_time() < hard_end - 1.0 and seed < 10:
        rng = np.random.default_rng(9001 + seed * 313)
        lo = int(rng.uniform(0.05, 0.45) * n)
        width = n // 2 if seed % 2 == 0 else n // 3
        hi = min(n, lo + width)
        base_for_pert = cur[::-1].copy() if seed % 3 == 2 else cur
        sigma = 0.55 if seed % 4 == 1 else 0.30
        hp = _perturb_window(base_for_pert, lo, hi, rng, sigma=sigma)
        hp = _lbfgs_log(hp, maxiter=600, deadline=hard_end)
        hp, rp = _fine_polish(hp, min(hard_end, time.process_time() + (hard_end - time.process_time()) * 0.6))
        print("seed %d R=%.7f (cur %.7f base %.7f)" % (seed, rp, cur_r, base_r))
        _consider(hp, rp)
        if rp > cur_r + 1e-12:
            cur, cur_r = hp, rp
        seed += 1

    if time.process_time() < hard_end - 0.5:
        hfin, rfin = _fine_polish(cur, hard_end)
        _consider(hfin, rfin)

    print("final R=%.7f N=%d | base R=%.7f N=%d"
          % (best_r, best.size, base_r, base.size))

    if best_r < base_r:
        best = base.copy(); best_r = base_r

    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time

def Rvec(v):
    v = np.asarray(v, dtype=float)
    if v.ndim != 1 or v.size == 0 or not np.all(np.isfinite(v)) or v.sum() <= 0:
        return -1.0
    L = np.concatenate(([0.0], np.convolve(v, v), [0.0]))
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = (v.sum()**2) * L.max()
    if den <= 0:
        return -1.0
    return num / den

def R_of(h):
    return Rvec(h)

def _full_lbfgs(h, deadline, maxiter=200):
    h = np.asarray(h, dtype=float).copy()
    if h.size == 0 or h.sum() <= 0:
        return h, -1.0
    try:
        from scipy.optimize import minimize
    except Exception:
        return h, R_of(h)
    best = h.copy(); bestR = R_of(h)
    # parametrize in log space
    def negR(x):
        v = np.exp(x)
        return -Rvec(v)
    x0 = np.log(np.maximum(h, 1e-12))
    try:
        res = minimize(negR, x0, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter*3,
                                'ftol': 1e-12, 'gtol': 1e-10})
        v = np.exp(res.x)
        r = Rvec(v)
        if r > bestR:
            best = v; bestR = r
    except Exception:
        pass
    return best, bestR

def _peak_window_polish(h, pad=3, frac=8, deadline=None):
    h = np.asarray(h, dtype=float).copy()
    best = h.copy(); bestR = R_of(h)
    N = h.size
    # find peak of f*f
    L = np.convolve(h, h)
    pk = int(np.argmax(L))
    # window around peak in h-space: peak of conv at index pk corresponds to h indices ~ pk/2
    c = pk // 2
    w = max(4, N // frac)
    lo = max(0, c - w); hi = min(N, c + w)
    for _ in range(3):
        if deadline is not None and time.process_time() > deadline:
            break
        seg = h[lo:hi]
        if seg.size < 2:
            break
        # local L-BFGS on the window
        def negR(x):
            v = h.copy(); v[lo:hi] = np.exp(x)
            return -Rvec(v)
        x0 = np.log(np.maximum(seg, 1e-12))
        try:
            from scipy.optimize import minimize
            res = minimize(negR, x0, method='L-BFGS-B',
                           options={'maxiter': 100, 'ftol': 1e-13, 'gtol': 1e-11})
            v = h.copy(); v[lo:hi] = np.exp(res.x)
            r = Rvec(v)
            if r > bestR:
                best = v; bestR = r; h = v.copy()
        except Exception:
            break
        w = max(2, w // 2)
        lo = max(0, c - w); hi = min(N, c + w)
    return best, bestR

def _es_refine(v, iters, rng, deadline=None):
    v = np.asarray(v, dtype=float).copy()
    best = v.copy(); bestR = Rvec(v)
    sigma = 0.3
    for i in range(iters):
        if deadline is not None and time.process_time() > deadline:
            break
        sigma = 0.3 * (0.01/0.3) ** (i / max(1, iters-1))
        cand = best * np.exp(rng.normal(0, sigma, size=best.size))
        r = Rvec(cand)
        if r > bestR:
            best = cand; bestR = r
    return best, bestR

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(12345)

    best_h = None; best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best_h = s.copy(); best_R = R_of(s)

    # Phase A: coarse multistart over M
    tA_end = t0 + budget_seconds * 0.35
    Ms = (6, 8, 10, 12, 16, 20, 24, 32)
    coarse = []
    for M in Ms:
        if time.process_time() > tA_end:
            break
        cands = []
        for _ in range(400):
            v = np.exp(rng.normal(0, 0.7, size=M) + 0.5)
            cands.append((Rvec(v), v))
        cands.sort(key=lambda t: -t[0])
        top = [v for _, v in cands[:5]]
        bestM = -1.0; bestV = None
        for v in top:
            if time.process_time() > tA_end:
                break
            vv, rr = _es_refine(v, 300, rng, deadline=tA_end)
            if rr > bestM:
                bestM = rr; bestV = vv
        coarse.append((M, bestM, bestV))
        print(f"[A] M={M} coarseR={bestM:.6f}")

    # Phase B: lift to fine N
    tB_end = t0 + budget_seconds * 0.80
    coarse_sorted = sorted([c for c in coarse if c[2] is not None], key=lambda t: -t[1])
    top3 = coarse_sorted[:3]
    for (M, rM, v) in top3:
        for m in (16, 128, 1024, 8192):
            if time.process_time() > tB_end:
                break
            N = M * m
            if N > 131072:
                continue
            # symmetric lift
            h = np.repeat(v, m)
            hh, rr = _full_lbfgs(h, tB_end, maxiter=200)
            if rr > best_R:
                best_R = rr; best_h = hh.copy()
            print(f"[B] M={M} m={m} N={N} symR={rr:.6f} best={best_R:.6f}")
            if time.process_time() > tB_end:
                break
            # asymmetric ramp lift
            h2 = np.empty(N)
            for j in range(M):
                a = v[j]
                b = v[j+1] if j+1 < M else v[j]
                h2[j*m:(j+1)*m] = np.linspace(a, b, m, endpoint=False)
            hh2, rr2 = _full_lbfgs(h2, tB_end, maxiter=200)
            if rr2 > best_R:
                best_R = rr2; best_h = hh2.copy()
            print(f"[B] M={M} m={m} N={N} rampR={rr2:.6f} best={best_R:.6f}")

    # Phase C: polish
    if best_h is not None:
        hh, rr = _peak_window_polish(best_h, pad=3, frac=8, deadline=deadline)
        if rr > best_R:
            best_R = rr; best_h = hh.copy()
        print(f"[C] polishR={rr:.6f} best={best_R:.6f}")
        while time.process_time() < deadline - 0.5:
            hh, rr = _full_lbfgs(best_h, deadline, maxiter=200)
            if rr > best_R:
                best_R = rr; best_h = hh.copy()
            else:
                break
            print(f"[C] lbfgsR={rr:.6f} best={best_R:.6f}")

    if best_h is None:
        best_h = np.ones(50)
    print(f"[final] R={R_of(best_h):.6f} N={best_h.size}")
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, deadline, beta, maxiter=200):
    """L-BFGS in log-space on positive entries; better for sharp peaks."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-14 * hmax if hmax > 0 else 1e-14
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(np.clip(u, -50, 50))
        val, g = _fun_grad_beta(hh, beta)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-50.0, 50.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -50.0, 50.0))
    return _rescale(h2)


def _lbfgs_raw(h0, deadline, beta, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_beta(hh, beta)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, pad_frac=0.10, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _lbfgs_block_log(h0, free, deadline, beta, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-14 * hmax if hmax > 0 else 1e-14
    u0 = np.log(np.clip(h[active], floor, None))

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, -50, 50))
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-50.0, 50.0)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -50.0, 50.0))
    return _rescale(h2)


def _upsample(h, factor):
    n = h.size
    n2 = n * factor
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, n2)
    return _rescale(np.interp(x_new, x_old, h))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: median beta-continuation on current resolution (log-space)
    betas = [1e4, 1e5, 1e6, 1e7, 1e8, 1e9]
    for beta in betas:
        if time.process_time() >= deadline * 0.55:
            break
        h_try = _lbfgs_log(best, deadline * 0.55, beta, maxiter=120)
        r = R_of(h_try)
        if r > bestR + 1e-14:
            best, bestR = h_try, r
    print("beta-cont: R=%.7f" % bestR)

    # Phase 2: try upsampling x2 and polish in log-space
    if time.process_time() < deadline - 15.0 and best.size < 500000:
        hu = _upsample(best, 2)
        for beta in [1e6, 1e7, 1e8]:
            if time.process_time() >= deadline - 12.0:
                break
            hu = _lbfgs_log(hu, deadline - 12.0, beta, maxiter=100)
        ru = R_of(hu)
        if ru > bestR + 1e-12:
            best, bestR = hu, ru
            print("upsample x2: R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 3: peak-window log-polish with decreasing pad
    if time.process_time() < deadline - 8.0:
        for pad in [0.15, 0.08, 0.05, 0.03, 0.02]:
            if time.process_time() >= deadline - 7.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            h_try = _lbfgs_block_log(best, win, deadline - 6.0, 1e8, maxiter=120)
            r = R_of(h_try)
            if r > bestR + 1e-14:
                best, bestR = h_try, r
        print("window: R=%.7f" % bestR)

    # Phase 4: perturbation sweep with log-space peak polish
    rng = np.random.RandomState(2024)
    ks = [1, 2, 3, 5, 7, 11]
    amps = [3e-4, 1e-3, 3e-3, 1e-2]
    sweep = 0
    while time.process_time() < deadline - 2.0:
        sweep += 1
        improved = False
        grid = [(k, phi, a) for k in ks
                for phi in np.linspace(0, 2 * np.pi, 4, endpoint=False)
                for a in amps]
        rng.shuffle(grid)
        for (k, phi, a) in grid:
            if time.process_time() >= deadline - 2.0:
                break
            n_idx = np.arange(best.size, dtype=float)
            mode = np.cos(2.0 * np.pi * k * n_idx / best.size + phi)
            h2 = np.clip(best * (1.0 + a * mode), 0.0, None)
            if h2.sum() <= 0:
                continue
            h2 = _rescale(h2)
            win = _peak_window(h2, pad_frac=0.06, extra=64)
            h2 = _lbfgs_block_log(h2, win, deadline - 1.5, 1e8, maxiter=100)
            r1 = R_of(h2)
            if r1 > bestR + 1e-13:
                best, bestR = h2, r1
                improved = True
        if not improved and sweep >= 1:
            break

    # Final full log-space polish
    if time.process_time() < deadline - 0.4:
        hf = _lbfgs_log(best, deadline - 0.3, 1e9, maxiter=150)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > startR + 1e-12:
        return best
    alt = best if bestR > startR - 1e-6 else None
    return {"best": best if bestR >= startR else (start if start is not None else best),
            "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _block_refine(h, deadline, nblocks, iters_per=120, overlap=0.15):
    N = h.size
    if N < 8:
        return h
    edges = np.linspace(0, N, nblocks + 1).astype(int)
    ov = max(1, int(N / nblocks * overlap))
    Lf = _knots(h)
    mx = Lf.max()
    impact = []
    for b in range(nblocks):
        lo = edges[b]; hi = edges[b + 1]
        khi = min(Lf.size, hi + 2)
        impact.append(np.sum(np.abs(Lf[lo:khi] - mx)))
    order = [b for _, b in sorted(zip(impact, range(nblocks)), reverse=True)]
    for b in order:
        if time.process_time() > deadline - 0.5:
            break
        lo = max(0, edges[b] - ov)
        hi = min(N, edges[b + 1] + ov)
        win = np.arange(lo, hi)
        ht = _lbfgs_block(h, win, iters_per, deadline - 0.4, beta=1e6)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
        if time.process_time() > deadline - 0.5:
            break
        ht = _lbfgs_block(h, win, iters_per, deadline - 0.4, tie=True)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


# ---------- NEW: local knot-insertion / shape mutation search ----------
# The existing L-BFGS polish is stuck at a local optimum of the *given*
# discretisation. Instead of only resampling, we perturb individual heights
# and re-optimise a window around the perturbation, accepting any strict
# improvement. This explores new discrete shapes the gradient cannot reach.

def _mutate_and_polish(h, deadline, rng, tries=400, win_frac=0.06):
    N = h.size
    if N < 16:
        return h
    bestR = R_of(h)
    best = h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    for _ in range(tries):
        if time.process_time() > deadline - 0.5:
            break
        # choose a position, biased toward the peak region
        if rng.random() < 0.6:
            center = int(pk / 2.0 + rng.normal(0, N * 0.05))
            center = np.clip(center, 0, N - 1)
        else:
            center = rng.integers(0, N)
        w = max(4, int(N * win_frac * (0.5 + rng.random())))
        lo = max(0, center - w)
        hi = min(N, center + w)
        win = np.arange(lo, hi)
        # perturb: multiplicative jitter on a random sub-block
        h2 = h.copy()
        sub = rng.choice(win, size=min(len(win), max(1, len(win) // 4)),
                         replace=False)
        scale = np.exp(rng.normal(0, 0.25, sub.size))
        h2[sub] = np.clip(h2[sub] * scale, 0, None)
        h2 = _rescale(h2)
        ht = _lbfgs_block(h2, win, 80, deadline - 0.4, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
    return best


# ---------- NEW: adaptive N refinement (upsample + re-optimise) ----------
# If the current shape is "smooth enough", a finer discretisation can hold
# more structure and raise R. We upsample then run global + window polish.

def _upsample(h, factor):
    N = h.size
    N2 = N * factor
    x = np.linspace(0, N - 1, N2)
    return _rescale(np.interp(x, np.arange(N), h))


def _try_finer(h, deadline, factor=2, iters=200):
    if time.process_time() > deadline - 2.0:
        return h
    h2 = _upsample(h, factor)
    h2 = _lbfgs_all_pos(h2, iters, deadline - 0.4, tie=True)
    if R_of(h2) <= R_of(h):
        return h
    # polish peak window
    win = _peak_window(h2, pad_frac=0.05, extra=64)
    h3 = _lbfgs_block(h2, win, iters, deadline - 0.4, tie=True)
    return h3 if R_of(h3) >= R_of(h2) else h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        best = _rescale(base) if base.size > 0 and base.sum() > 0 else None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(best)
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt = None
    altR = -1.0
    rng = np.random.default_rng(12345)

    # Phase A: local mutation search on the existing discretisation.
    phA = t0 + budget_seconds * 0.42
    ht = _mutate_and_polish(best.copy(), phA, rng, tries=500)
    r = R_of(ht)
    if r > bestR + 1e-15:
        best, bestR = ht.copy(), r
        print("PA mutate R=%.9f" % bestR)
    else:
        alt, altR = ht.copy(), r

    # Phase B: try a finer discretisation (upsample + re-optimise).
    phB = t0 + budget_seconds * 0.60
    if time.process_time() < phB - 3.0:
        ht = _try_finer(best.copy(), phB, factor=2, iters=200)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("PB finer R=%.9f (N=%d)" % (bestR, best.size))
        elif alt is None or r > altR:
            alt, altR = ht.copy(), r

    # Phase C: block refinement on the (possibly finer) shape.
    phC = t0 + budget_seconds * 0.74
    for nb in (64, 128, 192):
        if time.process_time() > phC - 1.5:
            break
        ht = _block_refine(best.copy(), phC, nb, iters_per=100)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("PC block nb=%d R=%.9f" % (nb, bestR))
        elif alt is None or r > altR:
            alt, altR = ht.copy(), r

    # Phase D: peak ladder.
    phD = t0 + budget_seconds * 0.83
    if time.process_time() < phD - 1.5:
        ht = _peak_ladder(best.copy(), phD - 0.5,
                          pads=(0.10, 0.06, 0.04, 0.02), iters=200)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("PD peak R=%.9f" % bestR)

    # Phase E: second mutation pass.
    phE = t0 + budget_seconds * 0.90
    if time.process_time() < phE - 1.5:
        ht = _mutate_and_polish(best.copy(), phE, rng, tries=300,
                                win_frac=0.03)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("PE mutate2 R=%.9f" % bestR)
        elif alt is None or r > altR:
            alt, altR = ht.copy(), r

    # Phase F: final global polish.
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 1.5:
        ht = _lbfgs_all_pos(best, 400, fd - 0.5, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("PF final R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt is not None and altR > startR + 1e-15:
        result["alternative"] = alt
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _restrict(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    return _prolongate(h_big, N_small)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _random_start(Nc, rng):
    k = rng.integers(3, 7)
    knots = np.sort(rng.uniform(0.0, 1.0, size=k))
    knots = np.concatenate(([0.0], knots, [1.0]))
    amps = rng.uniform(-1.0, 1.0, size=knots.size)
    amps = np.cumsum(amps) * 0.7
    x = np.linspace(0.0, 1.0, Nc)
    env = np.exp(np.interp(x, knots, amps))
    pzero = rng.choice([0.1, 0.3, 0.5])
    mask = (rng.random(Nc) > pzero).astype(float)
    h = env * mask
    if h.sum() <= 0:
        h = env.copy()
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

