        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


# ---------- K-mode Fourier search ----------

def _modeR(x, idx, F, N, K):
    F2 = F.copy()
    F2[idx] = x[:K] + 1j * x[K:]
    h = np.fft.irfft(F2, n=N)
    h = np.clip(h, 0, None)
    return _rescale(h)


def _mode_fun_grad(x, idx, F, N, K):
    h = _modeR(x, idx, F, N, K)
    val, gh = _fun_grad_tie(h)  # val = -log R, gh = d(-log R)/dh
    # dR/dh = -R * gh ; we minimise -log R, so use gh directly.
    G = np.fft.rfft(gh)
    # h = irfft(F2); d/dRe F_k contributes (2/N) Re(G_k), d/dIm F_k = -(2/N) Im(G_k)
    Gk = G[idx]
    gRe = (2.0 / N) * np.real(Gk)
    gIm = -(2.0 / N) * np.imag(Gk)
    # halve k=0 (and Nyquist if present)
    for t, k in enumerate(idx):
        if k == 0:
            gRe[t] *= 0.5
            gIm[t] *= 0.5
        elif k == N // 2 and N % 2 == 0:
            gRe[t] *= 0.5
            gIm[t] *= 0.5
    return val, np.concatenate([gRe, gIm])


def _run_mode_search(h_base, K, deadline, jitter_rad, rng):
    N = h_base.size
    s = np.sqrt(np.clip(h_base, 0, None))
    F = np.fft.rfft(s)
    idx = np.argsort(-np.abs(F))[:K]
    idx = np.sort(idx)
    x0 = np.concatenate([np.real(F[idx]), np.imag(F[idx])])
    if jitter_rad > 0:
        amp = np.abs(x0[:K] + 1j * x0[K:])
        ph = np.angle(x0[:K] + 1j * x0[K:]) + jitter_rad * rng.randn(K)
        x0 = np.concatenate([amp * np.cos(ph), amp * np.sin(ph)])
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(lambda x: _mode_fun_grad(x, idx, F, N, K),
                       x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': 200, 'maxfun': 400,
                                'ftol': 1e-18, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h_base, idx
    if res is None:
        return h_base, idx
    h = _modeR(res.x, idx, F, N, K)
    return h, idx


def _shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (np.mean(Lf >= mx * 0.999),
            np.mean(Lf >= mx * 0.99),
            np.mean(Lf >= mx * 0.95))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt = None
    altR = -1.0

    rng = np.random.RandomState(20240604)
    configs = [(48, 0.0), (64, 0.05), (96, 0.05)]

    for K, jit in configs:
        if time.process_time() >= deadline - 3.0:
            break
        tlim = min(deadline - 2.0, time.process_time() + 10.0)
        hc, idx = _run_mode_search(best, K, tlim, jit, rng)
        Rc = R_of(hc)
        print("mode K=%d jit=%.2f R=%.9f" % (K, jit, Rc))
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 4.0)
            hc = _full_lbfgs(hc, tlim2, maxiter=200)
        if time.process_time() < deadline - 1.0:
            tlim3 = min(deadline - 1.0, time.process_time() + 2.0)
            hc = _peak_window_polish(hc, tlim3, pad=3, frac=8)
        Rc = R_of(hc)
        sh = _shares(hc)
        print("mode K=%d polished R=%.9f shares %.4f/%.4f/%.4f"
              % (K, Rc, sh[0], sh[1], sh[2]))
        if Rc > bestR:
            best = hc
            bestR = Rc
            print("ACCEPT K=%d: %.9f" % (K, Rc))
        else:
            if alt is None or Rc > altR:
                alt = hc
                altR = Rc

    # leftover: fill loop from base
    alphas = [0.0001, 0.00003]
    k = 0
    while time.process_time() < deadline - 1.0:
        alpha = alphas[k % 2]
        k += 1
        tlim = min(deadline - 1.0, time.process_time() + 2.5)
        hc = _lbfgs_custom(best, lambda hh: _fun_grad_cvar(hh, alpha),
                           tlim, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 1.5)
            hc = _full_lbfgs(hc, tlim2, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim3 = min(deadline - 1.0, time.process_time() + 1.0)
            hc = _peak_window_polish(hc, tlim3, pad=3, frac=8)
        rc = R_of(hc)
        print("fill a=%.5f R=%.9f (best %.9f)" % (alpha, rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if alt is not None and altR > 0 and alt is not best:
        return {"best": best, "alternative": alt}
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lanczos_min(hop, n, m, rng, deadline):
    """Lanczos with full reorthogonalization. Returns (lam_min, v_min, lam_abs_max, v_abs_max)."""
    V = np.zeros((m + 1, n))
    alpha = np.zeros(m)
    beta = np.zeros(m)
    v = rng.randn(n)
    v /= np.linalg.norm(v)
    V[0] = v
    for j in range(m):
        if time.process_time() > deadline:
            m = j
            alpha = alpha[:m]; beta = beta[:max(0, m - 1)]
            V = V[:m]
            break
        w = hop(V[j])
        alpha[j] = np.dot(w, V[j])
        w = w - alpha[j] * V[j]
        if j > 0:
            w = w - beta[j - 1] * V[j - 1]
        # full reorthogonalization
        for _ in range(2):
            w = w - V[:j + 1].T @ (V[:j + 1] @ w)
        bj = np.linalg.norm(w)
        beta[j] = bj
        if bj < 1e-12:
            m = j + 1
            alpha = alpha[:m]; beta = beta[:max(0, m - 1)]
            V = V[:m]
            break
        V[j + 1] = w / bj
    k = alpha.size
    if k == 0:
        return 0.0, np.zeros(n), 0.0, np.zeros(n)
    T = np.diag(alpha)
    if k > 1:
        T += np.diag(beta[:k - 1], 1) + np.diag(beta[:k - 1], -1)
    evals, evecs = np.linalg.eigh(T)
    imin = int(np.argmin(evals))
    iabs = int(np.argmax(np.abs(evals)))
    vmin = V[:k].T @ evecs[:, imin]
    vabs = V[:k].T @ evecs[:, iabs]
    nv = np.linalg.norm(vmin)
    if nv > 0:
        vmin /= nv
    nv = np.linalg.norm(vabs)
    if nv > 0:
        vabs /= nv
    return evals[imin], vmin, evals[iabs], vabs


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    h = best.copy()
    hmax = h.max()
    pos = np.flatnonzero(h > 1e-12 * hmax)
    if pos.size == 0:
        pos = np.flatnonzero(h > 0)
    u = np.log(np.clip(h[pos], 1e-300, None))

    def gfun(uu):
        hh = h.copy()
        hh[pos] = np.exp(np.clip(uu, -40.0, 40.0))
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    eps = 1e-4
    n = pos.size

    def hop(v):
        _, gp = gfun(u + eps * v)
        _, gm = gfun(u - eps * v)
        return (gp - gm) / (2.0 * eps)

    tgrid = [0.02, 0.05, 0.1, 0.2, 0.4, 0.8]

    def try_direction(v, tag):
        nonlocal best, bestR
        cands = []
        for t in tgrid:
            for sgn in (1.0, -1.0):
                if time.process_time() > deadline - 1.0:
                    break
                ht = h.copy()
                ht[pos] = np.exp(np.clip(u + sgn * t * v, -40.0, 40.0))
                ht = _rescale(ht)
                rt = R_of(ht)
                cands.append((rt, ht))
        cands.sort(key=lambda x: -x[0])
        for rt, ht in cands[:2]:
            if time.process_time() > deadline - 1.0:
                break
            tlim = min(deadline - 1.0, time.process_time() + 4.0)
            hp = _full_lbfgs(ht, tlim, maxiter=200)
            for pad, frac in ((n // 8, 8), (n // 32, 32), (3, 8)):
                if time.process_time() > deadline - 1.0:
                    break
                tlim2 = min(deadline - 1.0, time.process_time() + 2.0)
                hp = _peak_window_polish(hp, tlim2, pad=pad, frac=frac)
            rp = R_of(hp)
            print("%s t=%.3f R=%.9f (best %.9f)" % (tag, rt, rp, bestR))
            if rp > bestR:
                best = hp.copy()
                bestR = rp

    for r in range(3):
        if time.process_time() > deadline - 2.0:
            break
        rng = np.random.RandomState(1000 + r)
        lam_min, v_min, lam_abs, v_abs = _lanczos_min(hop, n, 30, rng, deadline - 1.0)
        print("lanczos r=%d lam_min=%.6e lam_abs=%.6e" % (r, lam_min, lam_abs))
        if lam_min < -1e-9:
            try_direction(v_min, "esc r%d" % r)
        else:
            print("no negative curvature")
            try_direction(v_abs, "abs r%d" % r)

    # leftover budget: polish best
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 1.0, time.process_time() + 4.0)
        hp = _full_lbfgs(best, tlim, maxiter=200)
        for pad, frac in ((n // 8, 8), (n // 32, 32), (3, 8)):
            if time.process_time() > deadline - 1.0:
                break
            tlim2 = min(deadline - 1.0, time.process_time() + 2.0)
            hp = _peak_window_polish(hp, tlim2, pad=pad, frac=frac)
        rp = R_of(hp)
        print("polish R=%.9f (best %.9f)" % (rp, bestR))
        if rp > bestR:
            best = hp.copy()
            bestR = rp
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best}

