    return _lbfgs_custom(h0, lambda h: _fun_grad_tie(h, tie_tol),
                         deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=64, frac=0.5, maxiter=80):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.9995 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    p = max(pad, int(span * frac))
    lo = max(0, lo - p)
    hi = min(h.size - 1, hi + p)
    free = np.arange(lo, hi + 1)
    if free.size < 8:
        return h
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[free], floor, None))

    def f(u):
        hh = h.copy()
        hh[free] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = _fun_grad_tie(hh, 0.0)
        return val, g[free] * hh[free]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * free.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[free] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _smooth_up(h, N_big):
    n = h.size
    if n == N_big:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hb = np.clip(np.diff(Sb), 0.0, None)
    if hb.sum() <= 0:
        return np.ones(N_big)
    return hb


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = best.copy()
    dev = None
    devR = bestR

    # CVaR homotopy: alpha from large to small pushes several top knots
    # toward a common (flat) plateau. This is the key new driver versus
    # a plain max or a discrete tie-tolerance homotopy.
    for alpha in (0.20, 0.10, 0.05, 0.02, 0.01, 0.005, 0.002):
        if time.process_time() >= deadline - 6.0:
            break
        trial = _lbfgs_custom(cur, lambda h, a=alpha: _fun_grad_cvar(h, a),
                              deadline, maxiter=200)
        # then snap to true max
        trial = _lbfgs_log(trial, 200, deadline, tie_tol=1e-6)
        trial = _lbfgs_log(trial, 200, deadline, tie_tol=0.0)
        r = R_of(trial)
        print("cvar a=%.3f R=%.7f" % (alpha, r))
        if r > devR + 1e-12:
            dev, devR = trial, r
        if r > R_of(cur) + 1e-12:
            cur = trial

    if dev is not None and devR > bestR + 1e-12:
        best, bestR = dev, devR

    # Try a modest N increase then full polish.
    if time.process_time() < deadline - 18.0 and best.size < 200000:
        for mult in (1.15, 1.3):
            if time.process_time() >= deadline - 14.0:
                break
            Nt = int(min(300000, best.size * mult))
            up = _smooth_up(best, Nt)
            up = _lbfgs_log(up, 250, deadline)
            r = R_of(up)
            print("up N=%d R=%.7f" % (Nt, r))
            if r > bestR + 1e-12:
                best, bestR = up, r
            else:
                break

    # Final alternating polish toward the true objective.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline, tie_tol=0.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _peak_window_polish(best, deadline, pad=64, frac=0.5, maxiter=400)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if dev is not None and devR > start_bestR + 1e-12:
        return {"best": dev, "alternative": start_best}
    return {"best": start_best, "alternative": dev if dev is not None else start_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    """CVaR-of-top-alpha smoothing of the max: robust to knot-tie plateaus."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, fg=None):
    return _lbfgs_block(h0, np.arange(np.asarray(h0).size), maxiter, deadline, fg)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _report(tag, h, R):
    print("%s R=%.7f N=%d" % (tag, R, h.size))


def _cvar_ladder(h, bestR, deadline, rng):
    """CVaR continuation on the peak window: robustly reshape the plateau."""
    if time.process_time() >= deadline - 1.0:
        return h, bestR
    win = _peak_window(h, tol=0.98, pad_frac=0.6, extra=1024)
    if win.size > 60000:
        return h, bestR
    cur, curR = h.copy(), bestR
    for alpha in (0.20, 0.10, 0.05, 0.02, 0.01):
        if time.process_time() >= deadline - 0.8:
            break
        fg = (lambda hh, a=alpha: _fun_grad_cvar(hh, a))
        ht = _lbfgs_block(cur, win, 150, deadline - 0.8, fg=fg)
        rt = R_of(ht)
        if rt > curR - 1e-9:
            cur, curR = ht, rt
    if curR > bestR + 1e-13:
        return cur, curR
    return h, bestR


def _hop(h, bestR, deadline, rng):
    n = h.size
    if n < 8:
        return h, bestR
    wlen = int(rng.integers(max(8, n // 20), max(16, n // 4)))
    wlen = min(wlen, n)
    lo = int(rng.integers(0, n - wlen + 1))
    hi = lo + wlen
    hp = h.copy()
    amp = rng.uniform(0.02, 0.15)
    noise = 1.0 + amp * rng.standard_normal(wlen)
    hp[lo:hi] = np.clip(hp[lo:hi] * noise, 0.0, None)
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 64
    flo = max(0, lo - halo); fhi = min(n, hi + halo)
    free = np.arange(flo, fhi)
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 200, deadline - 0.5,
                          fg=lambda hh: _fun_grad_beta(hh, 1e7))
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if time.process_time() < deadline - 0.5:
        win = _peak_window(hp, tol=0.95, pad_frac=0.5, extra=512)
        if win.size <= 40000:
            ht = _lbfgs_block(hp, win, 250, deadline - 0.5)
            rt = R_of(ht)
            if rt > rp:
                hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def _mutate(h, bestR, deadline, rng):
    n = h.size
    hp = h.copy()
    blen = int(rng.integers(max(8, n // 40), max(16, n // 8)))
    blen = min(blen, n)
    lo = int(rng.integers(0, n - blen + 1))
    hi = lo + blen
    hp[lo:hi] = 0.0
    hp = _rescale(hp)
    rp = R_of(hp)
    halo = 128
    free = np.arange(max(0, lo - halo), min(n, hi + halo))
    if free.size > 0 and time.process_time() < deadline - 0.5:
        ht = _lbfgs_block(hp, free, 300, deadline - 0.5)
        rt = R_of(ht)
        if rt > rp:
            hp, rp = ht, rt
    if rp > bestR + 1e-13:
        return hp, rp
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(20250101)

    # Stage (a): full polish (exact-max).
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_all(best, 800, deadline - 1.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(a)", best, bestR)

    # Stage (b): CVaR continuation on peak window - the new ingredient.
    # Exact-max polish stalls on knot-tie plateaus; CVaR reshapes the top
    # band smoothly, then a final exact-max polish re-tightens it.
    for alpha_scale in (1.0, 0.5):
        if time.process_time() >= deadline - 1.0:
            break
        ht, rt = _cvar_ladder(best, bestR, deadline - 1.0, rng)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
        if time.process_time() < deadline - 0.8:
            win = _peak_window(best, pad_frac=0.3, extra=512)
            if win.size <= 40000:
                ht = _lbfgs_block(best, win, 250, deadline - 0.8)
                r = R_of(ht)
                if r > bestR + 1e-13:
                    best, bestR = ht, r
    _report("(b)", best, bestR)

    # Stage (c): peak-window refinements at multiple scales (exact-max).
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        if win.size > 40000:
            continue
        ht = _lbfgs_block(best, win, 250, deadline - 1.0,
                          fg=lambda hh, b=beta: _fun_grad_beta(hh, b))
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("(c)", best, bestR)

    # Stage (d): alternating hop / mutate / CVaR-anneal.
    n_hops = 0
    n_accept = 0
    while time.process_time() < deadline - 1.2:
        n_hops += 1
        mode = n_hops % 4
        if mode == 0:
            hnew, rnew = _mutate(best, bestR, deadline - 1.2, rng)
        elif mode == 1:
            hnew, rnew = _cvar_ladder(best, bestR, deadline - 1.2, rng)
        else:
            hnew, rnew = _hop(best, bestR, deadline - 1.2, rng)
        if rnew > bestR + 1e-13:
            best, bestR = hnew, rnew
            n_accept += 1
        if n_hops > 500:
            break
    print("(d) hops=%d accepted=%d" % (n_hops, n_accept))
    _report("(d)", best, bestR)

    # Stage (e): final broad polish, with and without zero-seeding.
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all(best, 500, deadline - 0.6)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        hs = _seed_zeros(best)
        ht = _lbfgs_all(hs, 300, deadline - 0.4)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    _report("final", best, bestR)

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_polish(h, deadline, pads=(0.10, 0.06, 0.04)):
    best = h.copy()
    bestR = R_of(best)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 200, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2, r2
    return best, bestR


def _resample_area(h, N2):
    """Area-preserving resampling of step function h (N cells) onto N2 cells."""
    N = h.size
    # cumulative integral at cell boundaries, normalized to [0,1] in x
    cum = np.concatenate(([0.0], np.cumsum(h)))
    # output cell boundaries in x: j/N2 for j=0..N2
    xb = np.arange(N2 + 1, dtype=float) / N2
    # input cell boundaries: i/N for i=0..N
    xi = np.arange(N + 1, dtype=float) / N
    # integral of h over [0, x] as function of x (piecewise linear in cum)
    # value at xb via interpolation
    vals = np.interp(xb, xi, cum)
    h2 = np.diff(vals) * N  # scale so mean preserved
    return np.clip(h2, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h = _rescale(base)
            bestR = R_of(h)
        else:
            h = None
    else:
        h = None

    if h is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        h = _rescale(h)
        bestR = R_of(h)

    N = h.size
    best = h.copy()
    startR = bestR
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase A: non-commensurate lifts ----
    factors = [1.5, 1.25, 0.8]
    lift_results = []
    # allocate roughly 55% of budget to lifts, split evenly
    lift_total = budget_seconds * 0.55
    per_lift = lift_total / len(factors)
    for fi, factor in enumerate(factors):
        if time.process_time() >= deadline - 3.0:
            break
        now = time.process_time()
        chunk_dl = min(deadline - 2.5, now + per_lift)
        if chunk_dl <= now + 0.5:
            break
        N2 = max(4, int(round(factor * N)))
        try:
            h2 = _resample_area(h, N2)
        except Exception as e:
            print("factor %.2f resample exception %s" % (factor, e))
            continue
        if h2.sum() <= 0:
            continue
        h2 = _rescale(h2)
        r_lift = R_of(h2)
        # optional multiplicative noise once
        try:
            h2n = h2 * np.exp(0.05 * np.random.randn(N2))
            h2n = _rescale(h2n)
            r_lift_n = R_of(h2n)
        except Exception:
            h2n, r_lift_n = h2, r_lift
        # optimize both, keep best
        cand = h2
        candR = r_lift
        if r_lift_n > candR:
            cand, candR = h2n, r_lift_n
        # full lbfgs with tie gradient
        if time.process_time() < chunk_dl - 0.5:
            ht = _lbfgs_all_pos(cand, 250, chunk_dl - 0.3, beta=0.0)
            r_opt = R_of(ht)
            if r_opt > candR:
                cand, candR = ht, r_opt
        # peak polish
        if time.process_time() < chunk_dl - 0.5:
            hp, rp = _peak_polish(cand, chunk_dl - 0.3)
            if rp > candR:
                cand, candR = hp, rp
        lift_results.append((factor, N2, r_lift, candR))
        print("factor %.2f N2=%d R_lift=%.9f R_polish=%.9f (best %.9f)" %
              (factor, N2, r_lift, candR, bestR))
        if candR > bestR + 1e-13:
            best, bestR = cand.copy(), candR
            print("  lift NEW BEST R=%.9f (factor %.2f N2=%d)" %
                  (bestR, factor, N2))
        elif candR > alt_bestR:
            alt_best, alt_bestR = cand.copy(), candR

    # ---- Phase B: polish best at its own N ----
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("own-N beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht, r
    if time.process_time() < deadline - 1.0:
        hp, rp = _peak_polish(best, deadline - 0.4)
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("own-N peak NEW BEST R=%.9f" % bestR)
        elif rp > alt_bestR:
            alt_best, alt_bestR = hp, rp

    # ---- Phase C: if a lift won, try lifting the winner again ----
    if best.size != N and time.process_time() < deadline - 4.0:
        # try one more non-commensurate lift from the new best
        now = time.process_time()
        chunk_dl = min(deadline - 1.5, now + budget_seconds * 0.15)
        if chunk_dl > now + 1.0:
            for factor in [1.5, 1.25, 0.8]:
                if time.process_time() >= chunk_dl - 1.0:
                    break
                N3 = max(4, int(round(factor * best.size)))
                try:
                    h3 = _resample_area(best, N3)
                    h3 = _rescale(h3)
                    r3 = R_of(h3)
                    ht = _lbfgs_all_pos(h3, 200, chunk_dl - 0.3, beta=0.0)
                    r3o = R_of(ht)
                    if r3o > bestR + 1e-13:
                        best, bestR = ht, r3o
                        print("re-lift factor %.2f N3=%d NEW BEST R=%.9f" %
                              (factor, N3, bestR))
                    elif r3o > alt_bestR:
                        alt_best, alt_bestR = ht, r3o
                except Exception as e:
                    print("re-lift exception %s" % e)

    # ---- Phase D: final polish ----
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        elif r > alt_bestR:
            alt_best, alt_bestR = ht, r

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))
    for fr in lift_results:
        print("  lift factor=%.2f N2=%d R_lift=%.9f R_polish=%.9f" % fr)

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_masked(h0, mask, deadline, maxiter=200):
    """Optimise only entries where mask is True (in log space)."""
    h = np.clip(h0, 0, None)
    pos = np.flatnonzero(mask)
    if pos.size == 0 or h.sum() <= 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=200):
    return _lbfgs_masked(h0, np.ones(h0.size, bool), deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.3:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    mask = np.zeros(n, bool)
    mask[lo:hi] = True
    return _lbfgs_masked(h, mask, deadline, maxiter=120)


# ---- periodic-block structure exploitation ----
# The optimal construction is suspected to be a periodic block repeated k times.
# We coarsen by block-averaging into M cells, optimise, then rasterise back.

def _coarsen(h, M):
    N = h.size
    if N % M == 0:
        k = N // M
        return h.reshape(M, k).mean(axis=1)
    edges = np.linspace(0, N, M + 1).astype(int)
    out = np.empty(M)
    for j in range(M):
        a = edges[j]; b = max(a + 1, edges[j + 1])
        out[j] = h[a:b].mean()
    return out


def _rasterise(c, N):
    M = c.size
    if N % M == 0:
        return np.tile(c, N // M)
    edges = np.linspace(0, N, M + 1).astype(int)
    h = np.empty(N)
    for j in range(M):
        a = edges[j]; b = max(a + 1, edges[j + 1])
        h[a:b] = c[j]
    return h


def _coarse_grad(c, N, M):
    h = _rasterise(c, N)
    if h.sum() <= 0:
        return np.zeros(M)
    _, g = _fun_grad_tie(h)
    if N % M == 0:
        k = N // M
        return g.reshape(M, k).sum(axis=1)
    edges = np.linspace(0, N, M + 1).astype(int)
    gc = np.zeros(M)
    for j in range(M):
        gc[j] = g[edges[j]:edges[j + 1]].sum()
    return gc


def _coarse_lbfgs(c0, N, M, deadline, maxiter=300):
    c = np.clip(c0, 0, None)
    if c.sum() <= 0:
        return c0
    pos = np.flatnonzero(c > 0)
    if pos.size == 0:
        return c0
    cmax = c.max()
    floor = 1e-12 * cmax if cmax > 0 else 1e-12
    u0 = np.log(np.clip(c[pos], floor, None))

    def f(u):
        cc = c.copy()
        cc[pos] = np.exp(u)
        h = _rasterise(cc, N)
        if h.sum() <= 0:
            return 1e18, np.zeros(pos.size)
        num, dq, Lf = _num_and_dq(h)
        mx = Lf.max()
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        gh = _backprop(gLf, h) + 2.0 / h.sum()
        if N % M == 0:
            k = N // M
            gc = gh.reshape(M, k).sum(axis=1)
        else:
            edges = np.linspace(0, N, M + 1).astype(int)
            gc = np.zeros(M)
            for j in range(M):
                gc[j] = gh[edges[j]:edges[j + 1]].sum()
        val = -np.log(num) + 2.0 * np.log(h.sum()) + np.log(mx)
        return val, gc[pos] * cc[pos]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c2 = c.copy()
    c2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return np.clip(c2, 0, None)


def _pick_divisor(N, target):
    best = None
    best_d = None
    for d in range(1, min(target, N) + 1):
        if N % d == 0:
            if best_d is None or abs(d - target) < abs(best_d - target):
                best_d = d
    return best_d if best_d is not None else min(target, N)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # ---- Step 1: full-resolution polish from start ----
    if time.process_time() < deadline - 3.0:
        tlim = min(deadline - 2.0, time.process_time() + 8.0)
        h_full = _full_lbfgs(best, tlim, maxiter=250)
        rf = R_of(h_full)
        if rf > bestR + 1e-14:
            best = h_full
            bestR = rf
            print("full polish R=%.12f" % bestR)

    # ---- Step 2: peak-window polish ----
    if time.process_time() < deadline - 3.0:
        tlim = min(deadline - 2.0, time.process_time() + 6.0)
        h_pk = _peak_window_polish(best, tlim, pad=4, frac=6)
        rp = R_of(h_pk)
        if rp > bestR + 1e-14:
            best = h_pk
            bestR = rp
            print("peak polish R=%.12f" % bestR)

    # ---- Step 3: coarse-block re-optimisation at multiple scales ----
    # Try several block sizes; optimise coarse then lift and polish.
    for target_M in (2048, 4096, 1024, 8192, 512):
        if time.process_time() > deadline - 2.5:
            break
        M = _pick_divisor(N, target_M)
        if M is None or M < 16 or M > N // 2:
            continue
        c = np.clip(_coarsen(best, M), 0, None)
        if c.sum() <= 0:
            continue
        tlim = min(deadline - 1.5, time.process_time() + 4.0)
        c2 = _coarse_lbfgs(c, N, M, tlim, maxiter=250)
        h_try = _rescale(_rasterise(c2, N))
        r_try = R_of(h_try)
        if time.process_time() < deadline - 2.0:
            tlim = min(deadline - 1.2, time.process_time() + 4.0)
            h_try2 = _full_lbfgs(h_try, tlim, maxiter=150)
            r2 = R_of(h_try2)
            if r2 > r_try:
                h_try = h_try2
                r_try = r2
        print("  M=%d coarse R=%.12f (best %.12f)" % (M, r_try, bestR))
        if r_try > bestR + 1e-10:
            best = h_try
            bestR = r_try
            print("  ACCEPT M=%d R=%.12f" % (M, bestR))

    # ---- Step 4: iterative refine at the current best scale ----
    # Alternate coarse optimise and full polish until time out.
    while time.process_time() < deadline - 2.0:
        M = _pick_divisor(N, 4096)
        if M is None:
            break
        c = np.clip(_coarsen(best, M), 0, None)
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        c2 = _coarse_lbfgs(c, N, M, tlim, maxiter=400)
        h_try = _rescale(_rasterise(c2, N))
        r_try = R_of(h_try)
        if r_try > bestR + 1e-12:
            best = h_try
            bestR = r_try
            print("  refine R=%.12f" % bestR)
        else:
            # no improvement; try full polish on current best to escape
            if time.process_time() < deadline - 1.0:
                tlim = min(deadline - 0.6, time.process_time() + 2.0)
                h_full = _full_lbfgs(best, tlim, maxiter=150)
                rf = R_of(h_full)
                if rf > bestR + 1e-13:
                    best = h_full
                    bestR = rf
                    print("  full refine R=%.12f" % bestR)
            break

    # ---- Final polish ----
    if time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 4.0)
        h_full = _full_lbfgs(best, tlim, maxiter=300)
        rf = R_of(h_full)
        if rf > bestR + 1e-15:
            best = h_full
            bestR = rf

    if bestR < startR:
        best = start_best
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    return {"best": best, "alternative": best}

