def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_band(h, delta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return _fun_grad(h)
    Lb = Lf[B]
    Lb_safe = np.clip(Lb, 1e-300, None)
    val = -np.log(num) + 2.0 * np.log(s) + np.mean(np.log(Lb_safe))
    gLf = -dq / num
    gLf[B] += (1.0 / nB) / Lb_safe
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log_band(h0, maxiter, deadline, delta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_band(hh, delta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, delta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if delta is None:
        fg = _fun_grad
    else:
        fg = (lambda hh: _fun_grad_band(hh, delta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=200, delta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, delta=delta)


def _band_stats(h, delta):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, 0.0, 0.0
    B = Lf >= (1.0 - delta) * mx
    nB = int(B.sum())
    if nB == 0:
        return 0, 0.0, mx
    Lb = Lf[B]
    ratio = float(Lb.min() / mx)
    return nB, ratio, mx


def _refine_resample(h, factor, deadline, iters=120):
    """Upsample h by `factor` (linear interp) and re-optimise in the band sense."""
    if factor <= 1 or time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    n2 = n * factor
    x = np.linspace(0.0, 1.0, n)
    x2 = np.linspace(0.0, 1.0, n2)
    h2 = np.interp(x2, x, h)
    h2 = _rescale(h2)
    # Alternate band smoothings
    cur = h2
    curR = R_of(cur)
    for d in (0.05, 0.02, 0.01):
        if time.process_time() >= deadline - 0.5:
            break
        hb = _lbfgs_log_band(cur, iters, deadline, d)
        rb = R_of(hb)
        if rb > curR + 1e-13:
            cur, curR = hb, rb
    return cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    cur = best.copy()
    curR = bestR

    # Try resampling to a finer grid early (a genuinely different construction).
    # Only accept if it beats the base; otherwise keep as alternative candidate.
    alt_best, alt_bestR = None, 0.0
    if time.process_time() < deadline - 20.0:
        for fac in (2, 2):
            if time.process_time() >= deadline - 15.0:
                break
            hr = _refine_resample(cur, fac, deadline - 8.0, iters=100)
            rr = R_of(hr)
            print("  resample x%d R=%.7f (base %.7f)" % (fac, rr, curR))
            if rr > alt_bestR:
                alt_best, alt_bestR = hr.copy(), rr
            if rr > curR + 1e-13:
                cur, curR = hr, rr
                break

    pass_no = 0
    while time.process_time() < deadline - 3.0:
        pass_no += 1

        if time.process_time() < deadline - 5.0:
            hb = _lbfgs_log_band(cur, 250, deadline, 0.05)
            rb = R_of(hb)
            nB, ratio, mx = _band_stats(hb, 0.05)
            print("  pass %d band0.05 R=%.7f |B|=%d min/max=%.5f" %
                  (pass_no, rb, nB, ratio))
            if rb > curR + 1e-13:
                cur, curR = hb, rb

        if time.process_time() < deadline - 4.0:
            hb = _lbfgs_log_band(cur, 150, deadline, 0.02)
            rb = R_of(hb)
            nB, ratio, mx = _band_stats(hb, 0.02)
            print("  pass %d band0.02 R=%.7f |B|=%d min/max=%.5f" %
                  (pass_no, rb, nB, ratio))
            if rb > curR + 1e-13:
                cur, curR = hb, rb

        if pass_no % 2 == 0 and time.process_time() < deadline - 4.0:
            hb = _lbfgs_log_band(cur, 120, deadline, 0.01)
            rb = R_of(hb)
            if rb > curR + 1e-13:
                cur, curR = hb, rb
                print("  pass %d band0.01 R=%.7f" % (pass_no, curR))

        # Window polish around peak region (tight)
        if time.process_time() < deadline - 3.0:
            hp = _window_polish_peak(cur, deadline, 0.10, 32, maxiter=150, delta=0.02)
            rp = R_of(hp)
            if rp > curR + 1e-13:
                cur, curR = hp, rp

        # Exact polish on peak-only window (delta=None) to sharpen the max
        if time.process_time() < deadline - 2.5:
            hp = _window_polish_peak(cur, deadline, 0.05, 16, maxiter=120, delta=None)
            rp = R_of(hp)
            if rp > curR + 1e-13:
                cur, curR = hp, rp

        print("  pass %d R=%.7f" % (pass_no, curR))
        if curR > bestR + 1e-13:
            best, bestR = cur.copy(), curR

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    alt = alt_best if (alt_best is not None and alt_bestR > start_bestR - 1e-6) else None
    return {"best": start_best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


# ------- NEW: reproject via mass-preserving resample to N2 (denser) -------
def _resample_mass(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    return np.clip(np.diff(C2), 0, None)


# ------- NEW: generate a "smoothed" start by convolving h with a small kernel -------
def _smooth(h, k):
    if k <= 1:
        return h.copy()
    ker = np.ones(k) / k
    s = np.convolve(h, ker, mode='same')
    return np.clip(s, 0, None)


# ------- NEW: exact-gradient L-BFGS in log-space, with positivity floor -------
def _lbfgs_log(h0, fun_grad, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 1e-14 * h.max())
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-10 * hmax
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(np.clip(u, -40, 40))
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40, 40))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    # ---- Set up base ----
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- Phase 1: multi-start log-space polish + tie polish ----
    phase1_end = t0 + budget_seconds * 0.40
    it = 0
    while time.process_time() < phase1_end - 1.0:
        it += 1
        slice_end = min(phase1_end, time.process_time() + 5.0)
        # log-space polish (different geometry: multiplicative steps)
        h_t = _lbfgs_log(best, _fun_grad_tie, slice_end - 1.5, maxiter=250)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
        if time.process_time() < slice_end - 1.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.10, 0.05, 0.03), iters=220, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
    print("phase1 done R=%.9f (N=%d, ties=%d)"
          % (bestR, best.size, _tie_count(best)))

    # ---- Phase 2: LIFT to finer grid, polish with log-space (better near ties) ----
    phase2_end = t0 + budget_seconds * 0.82
    N0 = best.size
    # Try upsample ladder; keep whichever wins; then try a second level
    factors = [1.5, 2.0, 3.0, 4.0, 6.0]
    for f in factors:
        if time.process_time() >= phase2_end - 2.0:
            break
        N2 = int(round(N0 * f))
        if N2 > 1000000:
            N2 = 1000000
        if N2 <= N0:
            continue
        h_fine = _resample_mass(best, N2)
        h_fine = _rescale(h_fine)
        r_fine0 = R_of(h_fine)
        slice_end = min(phase2_end, time.process_time() + 7.0)
        h_pol = _lbfgs_log(h_fine, _fun_grad_tie, slice_end - 3.0, maxiter=200)
        if time.process_time() < slice_end - 2.5:
            h_pol = _peak_ladder(h_pol, slice_end - 1.5,
                                 pads=(0.06, 0.04), iters=180, tie=True)
        if time.process_time() < slice_end - 1.0:
            h_pol = _lbfgs_all_pos(h_pol, 180, slice_end - 0.3, tie=True)
        r_pol = R_of(h_pol)
        improved = False
        if r_pol > bestR + 1e-15:
            best, bestR = h_pol.copy(), r_pol
            improved = True
        print("lift x%.1f N=%d r_lift0=%.9f r_pol=%.9f %s"
              % (f, N2, r_fine0, r_pol, "ACCEPT" if improved else "no gain"))
        if improved:
            N0 = best.size

    # ---- Phase 3: final log-space polish + peak ladder ----
    loop_end = t0 + budget_seconds * 0.88
    it = 0
    while time.process_time() < loop_end - 1.5:
        it += 1
        slice_end = min(loop_end, time.process_time() + 5.0)
        h_t = _lbfgs_log(best, _fun_grad_tie, slice_end - 1.5, maxiter=250)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
        if time.process_time() < slice_end - 1.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.05, 0.03, 0.02), iters=180, tie=True)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t

    # final micro-polish
    if time.process_time() < deadline - 0.5:
        h_t = _lbfgs_all_pos(best, 200, deadline - 0.2, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
