import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _coarse_envelope(h, coarse=512):
    N = h.size
    if N <= coarse:
        return h.copy()
    edges = np.linspace(0, N, coarse + 1).astype(int)
    env_c = np.zeros(coarse)
    for j in range(coarse):
        a, b = edges[j], edges[j + 1]
        if b > a:
            env_c[j] = h[a:b].mean()
    # linearly upsample back to N
    centers = 0.5 * (edges[:-1] + edges[1:])
    xi = np.arange(N) + 0.5
    env = np.interp(xi, centers, env_c)
    return np.clip(env, 0, None)


def _polish(h2, deadline, slice_dl):
    """beta ladder + peak window polish on active cells."""
    active = np.flatnonzero(h2 > 0)
    if active.size == 0:
        return h2
    ht = h2
    for beta in [0.0, 1e5, 1e7]:
        if time.process_time() >= slice_dl - 0.4:
            break
        ht = _lbfgs_block(ht, active, 200, slice_dl, beta=beta)
        active = np.flatnonzero(ht > 0)
        if active.size == 0:
            break
    if time.process_time() < slice_dl - 0.4:
        win = _peak_window(ht, pad_frac=0.10, extra=128)
        win = np.intersect1d(win, np.flatnonzero(ht > 0))
        if win.size > 0:
            ht = _lbfgs_block(ht, win, 120, slice_dl, beta=1e7)
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h = _rescale(base)
        else:
            h = None
    else:
        h = None

    if h is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        h = _rescale(h)

    best = h.copy()
    bestR = R_of(best)
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    alt_bestR = -1.0

    # Build coarse envelope with mass preserved
    env = _coarse_envelope(best, coarse=512)
    env = _rescale(env)
    target_mass = best.sum()

    # Candidate masks
    candidates = []
    for p in [2, 4, 5, 7]:
        mask = (np.arange(N) % p) == 0
        candidates.append(("p=%d" % p, mask))
    rng1 = np.random.RandomState(12345)
    candidates.append(("rand keep=0.34", rng1.rand(N) < 0.34))
    rng2 = np.random.RandomState(67890)
    candidates.append(("rand keep=0.70", rng2.rand(N) < 0.70))

    # Reserve ~5s at end for winner polish
    work_end = deadline - 5.0

    for name, mask in candidates:
        if time.process_time() >= work_end - 1.0:
            break
        now = time.process_time()
        slice_dl = min(now + 2.5, work_end)
        if slice_dl <= now + 0.3:
            break
        h2 = np.zeros(N)
        h2[mask] = env[mask]
        if h2.sum() <= 0:
            continue
        h2 = h2 * (target_mass / h2.sum())
        h2 = _rescale(h2)
        try:
            ht = _polish(h2, deadline, slice_dl)
        except Exception as e:
            print("mask %s exception %s" % (name, e))
            continue
        r = R_of(ht)
        dens = np.count_nonzero(ht) / float(N)
        print("mask %s R=%.9f (density %.3f) (best %.9f)" % (name, r, dens, bestR))
        if r > bestR + 1e-9:
            best, bestR = ht.copy(), r
            print("  mask NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # Final ~5s: re-optimise winner with beta=0 and peak-window polish
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("final beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
    if time.process_time() < deadline - 0.8:
        win = _peak_window(best, pad_frac=0.06, extra=128)
        ht2 = _lbfgs_block(best, win, 300, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
            print("final peak NEW BEST R=%.9f" % bestR)
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2

    print("final R=%.9f (base %.9f, N=%d)" % (bestR, R_of(h), best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

