    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, alpha, deadline, maxiter=120):
    fg = _fun_grad_tie if alpha <= 0 else (lambda h: _fun_grad_cvar(h, alpha))
    return _lbfgs_custom(h0, fg, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _coarsen(h, k):
    n = h.size
    m = (n + k - 1) // k
    hp = np.zeros(m * k)
    hp[:n] = h
    return hp.reshape(m, k).mean(axis=1)


def _prolong(hc, N):
    m = hc.size
    xc = (np.arange(m) + 0.5) / m
    xf = (np.arange(N) + 0.5) / N
    hf = np.interp(xf, xc, hc, left=0.0, right=0.0)
    hf = np.clip(hf, 0, None)
    sc = hc.sum()
    sf = hf.sum()
    if sf > 0 and sc > 0:
        hf = hf * (sc / sf)
    return hf


def _top_shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0, 0.0
    return float(np.mean(L >= mx * 0.999)), float(np.mean(L >= mx * 0.95))


_CVAR_LADDER = [0.05, 0.02, 0.01, 0.005, 0.002]


def _cvar_ladder(h, deadline, maxiter=120, per_stage_cap=5.0):
    """Run CVaR annealing on h, snapping to exact tie objective after each stage."""
    cur = h
    curR = R_of(cur)
    for alpha in _CVAR_LADDER:
        now = time.process_time()
        if now >= deadline - 1.0:
            break
        tlim = min(now + per_stage_cap, deadline - 0.8)
        hc = _cvar_lbfgs(cur, alpha, tlim, maxiter=maxiter)
        # snap to exact tie objective
        now = time.process_time()
        if now < deadline - 0.5:
            hc2 = _full_lbfgs(hc, min(now + 2.0, deadline - 0.4), maxiter=60)
        else:
            hc2 = hc
        rc = R_of(hc2)
        print("cvar a=%.3f R=%.9f (cur %.9f)" % (alpha, rc, curR))
        if rc >= curR:
            cur = hc2
            curR = rc
        else:
            # keep the cvar result as candidate but continue from better
            if R_of(hc) > curR:
                cur = hc
                curR = R_of(hc)
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))
    s01, s5 = _top_shares(best)
    print("base shares 0.1%%=%.4f%% 5%%=%.4f%%" % (100 * s01, 100 * s5))

    alt = None
    altR = -1.0

    def _chunk(frac, cap=None):
        now = time.process_time()
        rem = deadline - now
        if rem <= 0.5:
            return None
        t = now + max(0.3, rem * frac)
        if cap is not None:
            t = min(t, now + cap)
        return min(t, deadline - 0.5)

    def _polish(hc, tlim):
        if tlim is None or time.process_time() >= tlim - 0.3:
            return hc
        hc = _full_lbfgs(hc, tlim, maxiter=200)
        if time.process_time() < tlim - 0.2:
            hc = _peak_window_polish(hc, tlim, pad=3, frac=8)
        return hc

    # ---- (1) CVaR ladder on the full array ----
    if time.process_time() < deadline - 3.0:
        hc, rc = _cvar_ladder(best, min(deadline - 2.0, time.process_time() + 12.0),
                              maxiter=120, per_stage_cap=2.5)
        print("cvar full R=%.9f (best %.9f)" % (rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc
            print("ACCEPT cvar full: %.9f" % rc)
        elif alt is None or rc > altR:
            alt = hc
            altR = rc

    # ---- (2) Multigrid pass at CVaR optimum ----
    for k in [2, 4]:
        if time.process_time() >= deadline - 3.0:
            break
        hc = _coarsen(best, k)
        # short CVaR ladder at coarse level
        hc, rc = _cvar_ladder(hc, min(deadline - 2.0, time.process_time() + 4.0),
                              maxiter=80, per_stage_cap=1.0)
        print("level k=%d Nc=%d coarse R=%.9f" % (k, hc.size, rc))
        if time.process_time() >= deadline - 1.5:
            break
        hp = _prolong(hc, N)
        tlim = _chunk(0.15)
        hp = _polish(hp, tlim)
        Rp = R_of(hp)
        print("level k=%d N=%d fine R=%.9f (best %.9f)" % (k, N, Rp, bestR))
        if Rp > bestR:
            best = hp
            bestR = Rp
            print("ACCEPT k=%d: %.9f" % (k, Rp))
        elif alt is None or Rp > altR:
            alt = hp
            altR = Rp

    # ---- (3) remaining time: alternate full_lbfgs and peak polish ----
    while time.process_time() < deadline - 1.0:
        tlim = _chunk(0.4, cap=6.0)
        if tlim is None:
            break
        hc = _full_lbfgs(best, tlim, maxiter=100)
        if time.process_time() < tlim - 0.3:
            hc = _peak_window_polish(hc, min(deadline - 0.5, time.process_time() + 2.0),
                                     pad=3, frac=8)
        rc = R_of(hc)
        print("fill R=%.9f (best %.9f)" % (rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc
        else:
            if alt is None or rc > altR:
                alt = hc
                altR = rc
            # small jitter restart from best
            if time.process_time() < deadline - 2.0:
                rng = np.random.RandomState(int(time.process_time() * 1000) % 2**31)
                hj = _coarsen(best, 2)
                hmax = hj.max()
                if hmax > 0:
                    hj = np.clip(hj * np.exp(0.08 * rng.randn(hj.size)), 1e-6 * hmax, None)
                hj = _rescale(hj)
                hj = _prolong(hj, N)
                tlim2 = _chunk(0.2, cap=3.0)
                hj = _polish(hj, tlim2)
                rj = R_of(hj)
                print("jitter R=%.9f (best %.9f)" % (rj, bestR))
                if rj > bestR:
                    best = hj
                    bestR = rj
                elif alt is None or rj > altR:
                    alt = hj
                    altR = rj
            else:
                break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    s01, s5 = _top_shares(best)
    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    print("final shares 0.1%%=%.4f%% 5%%=%.4f%%" % (100 * s01, 100 * s5))

    if alt is not None and altR > 0 and alt is not best:
        return {"best": best, "alternative": alt}
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    floor = 1e-12 * h.max()
    u0 = np.log(np.clip(h[active], floor, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _frac_within(h, tol=0.01):
    Lf = _knots(h)
    mx = Lf.max()
    return float(np.mean(Lf >= mx * (1.0 - tol)))


def _exact_polish(best, bestR, deadline, fracs=(0.02, 0.05, 0.10)):
    if time.process_time() >= deadline - 0.3:
        return best, bestR
    cap = min(deadline - 0.3, time.process_time() + 3.0)
    hp = _lbfgs_log(best, 300, cap, _fun_grad_tie)
    rp = R_of(hp)
    if rp > bestR + 1e-15:
        best, bestR = hp, rp
    for frac in fracs:
        if time.process_time() >= deadline - 0.3:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        # block polish on log-space subset
        if time.process_time() >= cap - 0.1:
            continue
        h = np.clip(best, 0, None)
        n = h.size
        active = np.asarray(free, dtype=int)
        floor = 1e-12 * h.max() if h.max() > 0 else 1e-12
        u0 = np.log(np.clip(h[active], floor, None))

        def f(u):
            hh = h.copy()
            hh[active] = np.exp(np.clip(u, -30.0, 30.0))
            val, g = _fun_grad_tie(hh)
            return val, g[active] * hh[active]

        cb = _make_cb(cap - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * active.size,
                           callback=cb,
                           options={'maxiter': 150, 'maxfun': 300,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            if res is not None:
                hb = h.copy()
                hb[active] = np.exp(np.clip(res.x, -30.0, 30.0))
                hb = _rescale(hb)
                rb = R_of(hb)
                if rb > bestR + 1e-15:
                    best, bestR = hb, rb
        except Exception:
            pass
    return best, bestR


def _fourier_grad(z, N):
    w = np.fft.irfft(z, n=N)
    h = w * w
    val, gh = _fun_grad_tie(h)
    dw = 2.0 * w * gh
    gz = np.fft.rfft(dw) * (2.0 / N)
    if N % 2 == 0:
        gz[0] *= 0.5
        gz[-1] *= 0.5
    return val, gz, h


def _fourier_improve(h0, deadline, iters=400):
    """Reparameterize h = w^2 with w = irfft(z), optimize z. Smoothness prior."""
    if time.process_time() >= deadline - 0.5:
        return h0
    n = h0.size
    N = n
    # initial w = sqrt(h), z = rfft(w)
    w0 = np.sqrt(np.clip(h0, 0, None))
    z0 = np.fft.rfft(w0)
    nz = z0.size

    def pack(z):
        return np.concatenate([z.real, z.imag])

    def unpack(x):
        return x[:nz] + 1j * x[nz:]

    x0 = pack(z0)

    def f(x):
        z = unpack(x)
        val, gz, h = _fourier_grad(z, N)
        return val, pack(gz)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    z = unpack(res.x)
    w = np.fft.irfft(z, n=N)
    h = w * w
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d) f1%%=%.4f"
          % (bestR, best.size, _frac_within(best)))

    # ---- direct exact polish first ----
    best, bestR = _exact_polish(best, bestR, deadline)
    print("after polish R=%.9f f1%%=%.4f" % (bestR, _frac_within(best)))

    # ---- Fourier w^2 reparametrization (smoothness prior) ----
    for _ in range(6):
        if time.process_time() >= deadline - 1.0:
            break
        cap = min(deadline - 0.5, time.process_time() + 4.0)
        hf = _fourier_improve(best, cap, iters=300)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best, bestR = hf, rf
            print("  fourier R=%.9f f1%%=%.4f" % (bestR, _frac_within(best)))
            best, bestR = _exact_polish(best, bestR, deadline)
            print("  +polish R=%.9f f1%%=%.4f" % (bestR, _frac_within(best)))
        else:
            # still exact polish best once more to squeeze
            hb, rb = _exact_polish(best, bestR, deadline)
            if rb > bestR + 1e-15:
                best, bestR = hb, rb
            else:
                break

    # final polish
    best, bestR = _exact_polish(best, bestR, deadline)
    print("final R=%.9f (N=%d) f1%%=%.4f"
          % (bestR, best.size, _frac_within(best)))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

