        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _subdivide(h):
    n = h.size
    out = np.empty(2 * n - 1)
    out[0::2] = h
    out[1::2] = 0.5 * (h[:-1] + h[1:])
    return out


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _compress(h):
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    lo, hi = nz[0], nz[-1]
    if hi - lo + 1 < h.size:
        return h[lo:hi + 1]
    return h


def _lbfgs_logit(h0, free, maxiter, deadline, beta=0.0):
    """Optimize in log-space on a free subset (better for near-zero heights)."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[active], floor, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    rng = np.random.RandomState(20240607)

    # Phase A: tie-aware polish at current resolution
    if time.process_time() < deadline - 10.0:
        for beta, mi in [(0.0, 2000), (1e6, 800), (1e7, 800), (1e8, 800)]:
            if time.process_time() >= deadline - 8.0:
                break
            h_try = _lbfgs_all(best, mi, deadline - 7.0, beta=beta, tie=True)
            r = R_of(h_try)
            if r > bestR + 1e-14:
                best, bestR = h_try.copy(), r
                print("A polish beta=%.0e R=%.7f" % (beta, bestR))

    # Phase B: subdivide, then aggressively polish the peak window with
    # log-parametrisation. This is the main new idea: at higher resolution
    # the peak region needs fine structure, and log-space avoids the
    # log-barrier artefacts near small heights.
    while time.process_time() < deadline - 8.0 and best.size < 400000:
        sub = _subdivide(best)
        h_try = _lbfgs_all(sub, 1200, deadline - 6.0, beta=0.0, tie=True)
        if time.process_time() < deadline - 5.0:
            free = _peak_window(h_try, tol=0.999, pad_frac=0.5, extra=512)
            h_try2 = _lbfgs_logit(h_try, free, 400, deadline - 4.0, beta=0.0)
            r2 = R_of(h_try2)
            if r2 > R_of(h_try):
                h_try = h_try2
        r = R_of(h_try)
        print("B subdivide N=%d R=%.7f (best %.7f)" % (h_try.size, r, bestR))
        if r > bestR - 2e-5:
            best = _compress(h_try)
            if r > bestR:
                bestR = r
        else:
            break

    # Phase C: random block coordinate passes (mixed linear and logit)
    n = best.size
    attempts = 0
    while time.process_time() < deadline - 4.0:
        attempts += 1
        wlen = int(n * rng.uniform(0.05, 0.35))
        wlen = max(64, min(n, wlen))
        lo = rng.randint(0, max(1, n - wlen))
        free = np.arange(lo, lo + wlen)
        if rng.rand() < 0.5:
            h_try = _lbfgs_block(best, free, 400, deadline - 3.0,
                                 beta=0.0, tie=True)
        else:
            h_try = _lbfgs_logit(best, free, 400, deadline - 3.0, beta=0.0)
        r = R_of(h_try)
        if r > bestR + 1e-14:
            best, bestR = h_try, r
            print("C block wlen=%d R=%.7f" % (wlen, bestR))
        if attempts % 6 == 0 and time.process_time() < deadline - 4.0:
            hs = _lbfgs_all(_seed_zeros(best), 800, deadline - 3.0, tie=True)
            r = R_of(hs)
            if r > bestR + 1e-14:
                best, bestR = _compress(hs), r
                print("C reseed+global R=%.7f (N=%d)" % (bestR, best.size))

    # Phase D: final aggressive polish (logit on peak window + global)
    if time.process_time() < deadline - 1.0:
        hf = _lbfgs_all(best, 3000, deadline - 0.8, tie=True)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf
        if time.process_time() < deadline - 0.6:
            free = _peak_window(best, tol=0.999, pad_frac=0.5, extra=256)
            hf = _lbfgs_logit(best, free, 400, deadline - 0.3, beta=0.0)
            rf = R_of(hf)
            if rf > bestR + 1e-14:
                best, bestR = hf, rf

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return _fun_grad(h)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _fun_grad_beta(h, beta):
    """Exact-tie objective plus soft-max (log-sum-exp) with weight beta."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return _fun_grad(h)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)

    if beta > 0:
        # log-sum-exp over knots, scaled by c to keep numbers sane
        z = beta * (Lf / c - 1.0)
        zmax = z.max()
        w = np.exp(z - zmax)
        sw = w.sum()
        lse = zmax + np.log(sw)
        val += (lse - np.log(beta)) * 0.0  # placeholder; keep val tied to c
        # gradient of lse wrt Lf: w/sw * beta / c
        gLf += (w / sw) * (beta / c)

    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        if beta > 0:
            return _fun_grad_beta(hh, beta)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta > 0:
            val, g = _fun_grad_beta(hh, beta)
        else:
            val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    n = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, n, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    rng = np.random.default_rng(12345)

    def polish_support(h, fd, beta=0.0):
        ht = _lbfgs_all_pos(h, 200, fd, beta=beta)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
        if time.process_time() < fd - 0.5:
            win = _peak_window(h, tol=0.95, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(h, win, 200, fd, beta=beta)
            if R_of(ht) > R_of(h) + 1e-15:
                h = ht
        return h

    sigmas = [0.02, 0.05, 0.10, 0.20]
    cyc = 0
    while time.process_time() < deadline - 2.5:
        sigma = sigmas[cyc % len(sigmas)]
        cyc += 1
        h = best
        d = np.clip(sigma * rng.standard_normal(n), -0.6, 0.6)
        u = np.empty(2 * n)
        u[0::2] = h * (1.0 + d)
        u[1::2] = h * (1.0 - d)
        u = _rescale(u)

        # Polish the 2N lift
        fd = min(deadline - 2.0, time.process_time() + 2.5)
        u = polish_support(u, fd, beta=0.0)
        R2N = R_of(u)

        # Fold back by pairwise means
        h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:n]

        # Polish folded (beta=0 then beta=1e7)
        fd = min(deadline - 1.5, time.process_time() + 1.0)
        h2 = polish_support(h2, fd, beta=0.0)
        if time.process_time() < deadline - 1.5:
            fd = min(deadline - 1.0, time.process_time() + 1.0)
            h2 = polish_support(h2, fd, beta=1e7)
        if time.process_time() < deadline - 1.0:
            fd = min(deadline - 0.8, time.process_time() + 0.6)
            win = _peak_window(h2, tol=0.95, pad_frac=0.10, extra=128)
            h2 = _lbfgs_block(h2, win, 200, fd, beta=0.0)

        Rf = R_of(h2)
        accepted = Rf > bestR + 1e-12
        if accepted:
            best, bestR = h2.copy(), Rf
        print("cyc %d sigma=%.3f R2N=%.9f Rfold=%.9f %s bestR=%.9f"
              % (cyc, sigma, R2N, Rf, "ACCEPT" if accepted else "reject", bestR))

    # Final exact polish
    if time.process_time() < deadline - 0.5:
        fd = deadline - 0.3
        hp = polish_support(best, fd, beta=0.0)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp.copy(), rp

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14:
        result["alternative"] = best
    return result

