    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h2, deadline, betas, iters=200):
    active = np.flatnonzero(h2 > 0)
    if active.size == 0:
        return h2
    ht = h2
    for beta in betas:
        if time.process_time() >= deadline - 0.4:
            break
        ht = _lbfgs_block(ht, active, iters, deadline, beta=beta)
        active = np.flatnonzero(ht > 0)
        if active.size == 0:
            break
    return ht


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h = _rescale(base)
        else:
            h = None
    else:
        h = None

    if h is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        h = _rescale(h)

    best = h.copy()
    bestR = R_of(best)
    n = best.size
    print("base R=%.9f (N=%d)" % (bestR, n))

    alt_best = None
    alt_bestR = -1.0

    work_end = deadline - 3.0
    rng = np.random.RandomState(987654321)
    sigmas = [0.05, 0.15, 0.30]
    it = 0
    while time.process_time() < work_end - 0.5:
        it += 1
        sigma = sigmas[it % len(sigmas)]
        now = time.process_time()
        slice_dl = min(now + 2.5, work_end)
        if slice_dl <= now + 0.4:
            break

        # Build 2N lift on active cells
        d = np.clip(sigma * rng.randn(n), -0.7, 0.7)
        u = np.zeros(2 * n)
        active = best > 0
        u[0::2] = best * (1.0 + d)
        u[1::2] = best * (1.0 - d)
        u[~np.repeat(active, 2)] = 0.0
        u = _rescale(u)

        # Polish u at 2N with beta ladder
        try:
            u = _polish_ladder(u, slice_dl, [0.0, 1e5, 1e7], iters=200)
        except Exception as e:
            print("2N polish exception %s" % e)
            continue
        r2N = R_of(u)

        # Fold back
        h2 = 0.5 * (u[0::2] + u[1::2])
        h2 = _rescale(h2)
        try:
            h2 = _polish_ladder(h2, slice_dl, [0.0, 1e6, 1e7], iters=200)
        except Exception as e:
            print("fold polish exception %s" % e)
            continue
        if time.process_time() < slice_dl - 0.4:
            win = _peak_window(h2, pad_frac=0.08, extra=128)
            win = np.intersect1d(win, np.flatnonzero(h2 > 0))
            if win.size > 0:
                h2 = _lbfgs_block(h2, win, 120, slice_dl, beta=1e7)
        rfold = R_of(h2)

        accepted = False
        if rfold > bestR + 1e-12:
            best, bestR = h2.copy(), rfold
            accepted = True
        elif rfold > alt_bestR:
            alt_best, alt_bestR = h2.copy(), rfold

        print("it=%d sigma=%.2f 2N R=%.9f fold R=%.9f acc=%s best=%.9f"
              % (it, sigma, r2N, rfold, accepted, bestR))

    # Final ~5s: re-polish winner with beta=0 and peak-pad ladder
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("final beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
    for pad in [0.10, 0.08, 0.06]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 200, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
            print("final peak pad=%.2f NEW BEST R=%.9f" % (pad, bestR))
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2

    print("final R=%.9f (base %.9f, N=%d)" % (bestR, R_of(h), best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve

def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)

def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))

def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den

def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf

def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]

def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)

def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad

def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad

def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb

def _lbfgs(h0, active, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = np.clip(h[active], 0.0, None)
    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]
    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)

def _upsample(h, factor):
    """Smoothly upsample the height profile by `factor` using linear interp."""
    n = h.size
    m = n * factor
    x = np.arange(m) / factor
    x0 = np.floor(x).astype(int)
    x1 = np.minimum(x0 + 1, n - 1)
    w = x - x0
    return (1 - w) * h[x0] + w * h[x1]

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    hard = t0 + budget_seconds * 0.96

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
        else:
            base = None
    else:
        base = None

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)

    start_best = base.copy()
    start_bestR = R_of(start_best)
    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f N=%d" % (bestR, best.size))

    # Strategy: refine on a moderately-sized working resolution, then upsample
    # to a finer grid and continue.  Working at moderate N keeps L-BFGS dense
    # steps affordable; upsampling exposes finer structure the coarse grid
    # cannot represent, letting us push past the start's local optimum.
    # We also use a CVaR (soft-max) continuation to break the flat-top tie.

    def polish(h, fracs, deadline_inner, iters=400):
        """Dense + peak-window polish with hard-max objective."""
        n = h.size
        h = _lbfgs(h, np.arange(n), iters, deadline_inner, _fun_grad)
        r = R_of(h)
        Lf = _knots(h)
        m = int(np.argmax(Lf))
        for frac in fracs:
            if time.process_time() >= deadline_inner - 0.3:
                break
            half = max(16, int(frac * n))
            lo = max(0, m - half); hi = min(n, m + half)
            h2 = _lbfgs(h, np.arange(lo, hi), 200, deadline_inner, _fun_grad)
            r2 = R_of(h2)
            if r2 > r:
                h, r = h2, r2
                Lf = _knots(h)
                m = int(np.argmax(Lf))
        return h, r

    # CVaR continuation: smooth the max over top-alpha fraction of knots.
    def cvar_polish(h, deadline_inner):
        n = h.size
        for alpha in (0.05, 0.02, 0.01, 0.005, 0.002):
            if time.process_time() >= deadline_inner - 0.3:
                break
            fg = (lambda hh, a=alpha: _fun_grad_cvar(hh, a))
            h2 = _lbfgs(h, np.arange(n), 200, deadline_inner, fg)
            if R_of(h2) > R_of(h):
                h = h2
        return h

    # Phase 1: work at current resolution.
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 10.0)
        h = cvar_polish(best, cap)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        print("cvar -> %.9f" % bestR)

    # Phase 2: upsample and re-polish at finer resolutions.
    for factor in (2, 2, 2):
        if time.process_time() >= deadline - 1.0:
            break
        if best.size * factor > 999000:
            break
        hu = _upsample(best, factor)
        hu = _rescale(hu)
        ru = R_of(hu)
        cap = min(deadline - 0.5, time.process_time() + 8.0)
        hu, ru = polish(hu, (0.05, 0.10, 0.20, 0.35), cap)
        if ru > bestR:
            best, bestR = hu, ru
        print("upsample x%d -> %.9f N=%d" % (factor, bestR, best.size))

    # Phase 3: repeated cvar + dense polish until no gain.
    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        prev = bestR
        cap = min(deadline - 0.5, time.process_time() + 4.0)
        h = cvar_polish(best, cap)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        cap = min(deadline - 0.5, time.process_time() + 4.0)
        best, bestR = polish(best, (0.04, 0.08, 0.15, 0.30), cap)
        if bestR <= prev + 1e-14:
            break
        print("cycle %d -> %.9f" % (cycle, bestR))

    if time.process_time() < hard - 1.0:
        cap = min(hard - 0.5, time.process_time() + 2.0)
        hf = _lbfgs(best, np.arange(best.size), 200, cap, _fun_grad)
        rf = R_of(hf)
        if rf > bestR:
            best, bestR = hf, rf

    print("final R=%.9f N=%d" % (bestR, best.size))
    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num + w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.4:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = (_fun_grad(hh) if beta is None else _fun_grad_sm(hh, beta))
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None, fun_grad=None):
    if time.process_time() >= deadline - 0.4:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fun_grad is None:
        fun_grad = _fun_grad if beta is None else (lambda hh: _fun_grad_sm(hh, beta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


# ---------- Fourier (w = irfft(z), h = w^2) machinery ----------

def _fourier_grad(z, N):
    w = np.fft.irfft(z, n=N)
    h = w * w
    val, gh = _fun_grad_tie(h)
    dw = 2.0 * w * gh
    gz = np.fft.rfft(dw) * (2.0 / N)
    if N % 2 == 0:
        gz[0] = gz[0].real + 0j
        gz[-1] = gz[-1].real + 0j
    return val, gz, h


def _fourier_pack(z):
    return np.concatenate([z.real, z.imag])


def _fourier_unpack(x, nz):
    return x[:nz] + 1j * x[nz:]


def _fourier_polish(h0, deadline, maxiter=300):
    """Optimise h = w^2 with w = irfft(z); z free. Smooth (no positivity wall)."""
    if time.process_time() >= deadline - 0.5:
        return h0
    n = h0.size
    N = n  # irfft length; h = w^2 has length N
    w0 = np.sqrt(np.clip(h0, 0, None))
    if w0.size != N:
        return h0
    z0 = np.fft.rfft(w0)
    nz = z0.size
    x0 = _fourier_pack(z0)

    def f(x):
        z = _fourier_unpack(x, nz)
        val, gz, _h = _fourier_grad(z, N)
        return val, _fourier_pack(gz)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    z = _fourier_unpack(res.x, nz)
    w = np.fft.irfft(z, n=N)
    h = w * w
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    def p(msg):
        print(msg)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    p("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size

    # Stage 0: Fourier-domain (h = w^2) polish -- smooth landscape, no positivity wall.
    if time.process_time() < deadline - 8.0:
        h = _fourier_polish(best, deadline, maxiter=250)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            p("fourier R=%.7f" % bestR)

    # Stage 1: soft-max annealing to break symmetric near-tied peaks.
    if time.process_time() < deadline - 6.0:
        h = best.copy()
        for beta in (500.0, 120.0, 30.0, 8.0):
            if time.process_time() >= deadline - 5.0:
                break
            h = _lbfgs_log(h, 400, deadline, beta=beta)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                p("sm beta=%.0f R=%.7f" % (beta, bestR))

    # Stage 2: wide-peak exact rebalancing.
    if time.process_time() < deadline - 5.0:
        lo, hi = _peak_region(best, tol=0.995)
        span = hi - lo
        lo2 = max(0, lo - max(8, span // 2))
        hi2 = min(N - 1, hi + max(8, span // 2))
        h = _lbfgs_block(best, np.arange(lo2, hi2 + 1), 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            p("wide-peak R=%.7f" % bestR)

    # Stage 3: multi-scale peak polish.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.55, 32)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 400, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            p("peak(%.2f) R=%.7f" % (frac, bestR))

    # Stage 4: final polish loop, alternating full, window, and Fourier.
    stall = 0
    turn = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        if turn % 3 == 0 and time.process_time() < deadline - 3.0:
            h = _fourier_polish(best, deadline, maxiter=150)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                improved = True
                p("fourier R=%.7f" % bestR)
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            p("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            p("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0
        turn += 1

    p("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


# ---------- k-vector (repeated) machinery ----------

def R_vec(v, k, N):
    m = N // k
    h = np.repeat(v, m)
    return R_of(h)


def _negR_logu(u, k, N):
    v = np.exp(np.clip(u, -12.0, 12.0))
    return -R_vec(v, k, N)


def _polish_k(u0, k, N, deadline, maxiter=300):
    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(_negR_logu, u0, args=(k, N), method='L-BFGS-B',
                       bounds=[(-12.0, 12.0)] * k, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-18, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return u0, -_negR_logu(u0, k, N)
    if res is None:
        return u0, -_negR_logu(u0, k, N)
    return res.x, -res.fun


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt = None
    altR = -1.0

    N = best.size
    ks = [k for k in (32, 34, 68) if N % k == 0]
    print("N=%d, usable k=%s" % (N, ks))

    # record's k=32 block means for calibration / init
    rec_u32 = None
    if 32 in ks:
        m32 = N // 32
        v32 = np.array([best[j * m32:(j + 1) * m32].mean() for j in range(32)])
        if v32.min() > 0:
            rec_u32 = np.log(v32)
            print("record k=32 R=%.9f" % R_vec(v32, 32, N))

    overall_best_v = None
    overall_best_k = None
    overall_best_R = -1.0

    for k in ks:
        if time.process_time() >= deadline - 3.0:
            break
        m = N // k
        # init population
        init = []
        if k == 32 and rec_u32 is not None:
            init.append(rec_u32)
        # random inits
        rng = np.random.RandomState(1000 + k)
        for _ in range(4):
            init.append(rng.uniform(-6.0, 6.0, k))
        # small jitter around record if k==32
        if k == 32 and rec_u32 is not None:
            for _ in range(3):
                init.append(rec_u32 + 0.1 * rng.randn(k))
        init = np.array(init)

        # time slice for DE
        remaining = deadline - time.process_time()
        de_budget = min(remaining * 0.45, 14.0)
        de_deadline = time.process_time() + de_budget

        def de_cb(xk, convergence=None):
            if time.process_time() > de_deadline:
                raise TimeoutError

        try:
            res = differential_evolution(
                _negR_logu, [( -12.0, 12.0)] * k, args=(k, N),
                init=init, popsize=20, maxiter=1000, tol=1e-10,
                mutation=(0.5, 1.0), recombination=0.7,
                callback=de_cb, polish=False, seed=2000 + k)
            de_u = res.x
            de_R = -res.fun
        except (TimeoutError, Exception):
            de_u = init[0]
            de_R = -_negR_logu(de_u, k, N)
        print("k=%d DE R=%.9f" % (k, de_R))

        # polish best few candidates
        cands = [de_u]
        if k == 32 and rec_u32 is not None:
            cands.append(rec_u32)
        for _ in range(3):
            cands.append(de_u + 0.05 * rng.randn(k))

        best_k_u = de_u
        best_k_R = de_R
        for c in cands:
            if time.process_time() >= deadline - 2.5:
                break
            tlim = min(deadline - 2.0, time.process_time() + 2.0)
            up, Rp = _polish_k(c, k, N, tlim, maxiter=200)
            if Rp > best_k_R:
                best_k_R = Rp
                best_k_u = up
        print("k=%d polished R=%.9f" % (k, best_k_R))

        if best_k_R > overall_best_R:
            overall_best_R = best_k_R
            overall_best_v = np.exp(np.clip(best_k_u, -12.0, 12.0))
            overall_best_k = k

    # lift overall best to N and polish
    if overall_best_v is not None:
        m = N // overall_best_k
        hlift = np.repeat(overall_best_v, m)
        Rlift = R_of(hlift)
        print("lifted k=%d R=%.9f (coarse %.9f, start %.9f)"
              % (overall_best_k, Rlift, overall_best_R, startR))

        if time.process_time() < deadline - 1.5:
            tlim = min(deadline - 1.0, time.process_time() + 6.0)
            hp = _full_lbfgs(hlift, tlim, maxiter=200)
            Rp = R_of(hp)
            print("lifted+full R=%.9f" % Rp)
            if Rp > Rlift:
                hlift = hp
                Rlift = Rp
        if time.process_time() < deadline - 1.0:
            tlim = min(deadline - 0.5, time.process_time() + 4.0)
            hp = _peak_window_polish(hlift, tlim, pad=3, frac=8)
            Rp = R_of(hp)
            print("lifted+peak R=%.9f" % Rp)
            if Rp > Rlift:
                hlift = hp
                Rlift = Rp

        if Rlift > bestR:
            best = hlift
            bestR = Rlift
            print("ACCEPT lifted: %.9f > %.9f" % (Rlift, startR))
        else:
            print("lifted did not beat start (%.9f vs %.9f)" % (Rlift, startR))
            if alt is None or Rlift > altR:
                alt = hlift
                altR = Rlift

    # --- Base's fill loop to use remaining budget ---
    alphas = [0.0001, 0.00003]
    kk = 0
    while time.process_time() < deadline - 1.0:
        alpha = alphas[kk % 2]
        kk += 1
        tlim = min(deadline - 1.0, time.process_time() + 2.5)
        hc = _lbfgs_custom(best, lambda hh: _fun_grad_cvar(hh, alpha),
                           tlim, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 1.5)
            hc = _full_lbfgs(hc, tlim2, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim3 = min(deadline - 1.0, time.process_time() + 1.0)
            hc = _peak_window_polish(hc, tlim3, pad=3, frac=8)
        rc = R_of(hc)
        print("fill a=%.5f R=%.9f (best %.9f)" % (alpha, rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if alt is not None and altR > 0 and alt is not best:
        return {"best": best, "alternative": alt}
    return {"best": best}

