    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


# ---------- k-vector (repeated) machinery ----------

def R_vec(v, k, N):
    m = N // k
    h = np.repeat(v, m)
    return R_of(h)


def _negR_logu(u, k, N):
    v = np.exp(np.clip(u, -12.0, 12.0))
    return -R_vec(v, k, N)


def _polish_k(u0, k, N, deadline, maxiter=300):
    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(_negR_logu, u0, args=(k, N), method='L-BFGS-B',
                       bounds=[(-12.0, 12.0)] * k, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-18, 'gtol': 1e-14})
    except (TimeoutError, Exception):
        return u0, -_negR_logu(u0, k, N)
    if res is None:
        return u0, -_negR_logu(u0, k, N)
    return res.x, -res.fun


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt = None
    altR = -1.0

    N = best.size
    ks = [k for k in (32, 34, 68) if N % k == 0]
    print("N=%d, usable k=%s" % (N, ks))

    # record's k=32 block means for calibration / init
    rec_u32 = None
    if 32 in ks:
        m32 = N // 32
        v32 = np.array([best[j * m32:(j + 1) * m32].mean() for j in range(32)])
        if v32.min() > 0:
            rec_u32 = np.log(v32)
            print("record k=32 R=%.9f" % R_vec(v32, 32, N))

    overall_best_v = None
    overall_best_k = None
    overall_best_R = -1.0

    for k in ks:
        if time.process_time() >= deadline - 3.0:
            break
        m = N // k
        # init population
        init = []
        if k == 32 and rec_u32 is not None:
            init.append(rec_u32)
        # random inits
        rng = np.random.RandomState(1000 + k)
        for _ in range(4):
            init.append(rng.uniform(-6.0, 6.0, k))
        # small jitter around record if k==32
        if k == 32 and rec_u32 is not None:
            for _ in range(3):
                init.append(rec_u32 + 0.1 * rng.randn(k))
        init = np.array(init)

        # time slice for DE
        remaining = deadline - time.process_time()
        de_budget = min(remaining * 0.45, 14.0)
        de_deadline = time.process_time() + de_budget

        def de_cb(xk, convergence=None):
            if time.process_time() > de_deadline:
                raise TimeoutError

        try:
            res = differential_evolution(
                _negR_logu, [( -12.0, 12.0)] * k, args=(k, N),
                init=init, popsize=20, maxiter=1000, tol=1e-10,
                mutation=(0.5, 1.0), recombination=0.7,
                callback=de_cb, polish=False, seed=2000 + k)
            de_u = res.x
            de_R = -res.fun
        except (TimeoutError, Exception):
            de_u = init[0]
            de_R = -_negR_logu(de_u, k, N)
        print("k=%d DE R=%.9f" % (k, de_R))

        # polish best few candidates
        cands = [de_u]
        if k == 32 and rec_u32 is not None:
            cands.append(rec_u32)
        for _ in range(3):
            cands.append(de_u + 0.05 * rng.randn(k))

        best_k_u = de_u
        best_k_R = de_R
        for c in cands:
            if time.process_time() >= deadline - 2.5:
                break
            tlim = min(deadline - 2.0, time.process_time() + 2.0)
            up, Rp = _polish_k(c, k, N, tlim, maxiter=200)
            if Rp > best_k_R:
                best_k_R = Rp
                best_k_u = up
        print("k=%d polished R=%.9f" % (k, best_k_R))

        if best_k_R > overall_best_R:
            overall_best_R = best_k_R
            overall_best_v = np.exp(np.clip(best_k_u, -12.0, 12.0))
            overall_best_k = k

    # lift overall best to N and polish
    if overall_best_v is not None:
        m = N // overall_best_k
        hlift = np.repeat(overall_best_v, m)
        Rlift = R_of(hlift)
        print("lifted k=%d R=%.9f (coarse %.9f, start %.9f)"
              % (overall_best_k, Rlift, overall_best_R, startR))

        if time.process_time() < deadline - 1.5:
            tlim = min(deadline - 1.0, time.process_time() + 6.0)
            hp = _full_lbfgs(hlift, tlim, maxiter=200)
            Rp = R_of(hp)
            print("lifted+full R=%.9f" % Rp)
            if Rp > Rlift:
                hlift = hp
                Rlift = Rp
        if time.process_time() < deadline - 1.0:
            tlim = min(deadline - 0.5, time.process_time() + 4.0)
            hp = _peak_window_polish(hlift, tlim, pad=3, frac=8)
            Rp = R_of(hp)
            print("lifted+peak R=%.9f" % Rp)
            if Rp > Rlift:
                hlift = hp
                Rlift = Rp

        if Rlift > bestR:
            best = hlift
            bestR = Rlift
            print("ACCEPT lifted: %.9f > %.9f" % (Rlift, startR))
        else:
            print("lifted did not beat start (%.9f vs %.9f)" % (Rlift, startR))
            if alt is None or Rlift > altR:
                alt = hlift
                altR = Rlift

    # --- Base's fill loop to use remaining budget ---
    alphas = [0.0001, 0.00003]
    kk = 0
    while time.process_time() < deadline - 1.0:
        alpha = alphas[kk % 2]
        kk += 1
        tlim = min(deadline - 1.0, time.process_time() + 2.5)
        hc = _lbfgs_custom(best, lambda hh: _fun_grad_cvar(hh, alpha),
                           tlim, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 1.5)
            hc = _full_lbfgs(hc, tlim2, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim3 = min(deadline - 1.0, time.process_time() + 1.0)
            hc = _peak_window_polish(hc, tlim3, pad=3, frac=8)
        rc = R_of(hc)
        print("fill a=%.5f R=%.9f (best %.9f)" % (alpha, rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if alt is not None and altR > 0 and alt is not best:
        return {"best": best, "alternative": alt}
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, deadline, alpha=0.02, maxiter=150):
    def fg(hh):
        return _fun_grad_cvar(hh, alpha)
    return _lbfgs_custom(h0, fg, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 120, 'maxfun': 240,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


# ---------- Fourier (w = irfft(z), h = w^2) machinery ----------

def _fourier_grad(z, N):
    w = np.fft.irfft(z, n=N)
    h = w * w
    val, gh = _fun_grad_tie(h)
    dw = 2.0 * w * gh
    gz = np.fft.rfft(dw) * (2.0 / N)
    if N % 2 == 0:
        gz[0] *= 0.5
        gz[-1] *= 0.5
    return val, gz, h


def _fourier_pack(z):
    return np.concatenate([z.real, z.imag])


def _fourier_unpack(x, nz):
    return x[:nz] + 1j * x[nz:]


def _fourier_lbfgs(h0, deadline, maxiter=200):
    n = h0.size
    w = np.sqrt(np.clip(h0, 0, None))
    z0 = np.fft.rfft(w)
    nz = z0.size
    x0 = _fourier_pack(z0)

    def f(x):
        z = _fourier_unpack(x, nz)
        val, gz, _ = _fourier_grad(z, n)
        return val, _fourier_pack(gz)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    z = _fourier_unpack(res.x, nz)
    w = np.fft.irfft(z, n=n)
    return _rescale(w * w)


def _upsample(h, N2):
    n = h.size
    u_old = (np.arange(n) + 0.5) / n
    u_new = (np.arange(N2) + 0.5) / N2
    return np.interp(u_new, u_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    # Candidate list of (R, h)
    candidates = []

    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.size > 0 and hs.sum() > 0:
            candidates.append((R_of(hs), hs.copy()))

    # Baseline seed: a smooth bump
    if not candidates:
        N0 = 200
        u = np.linspace(0, 1, N0)
        h = np.clip(1.0 - np.abs(2 * u - 1) ** 1.5, 0, None)
        candidates.append((R_of(h), h))

    # Always try to polish the best current seed on a moderate grid first.
    def best_seed():
        candidates.sort(key=lambda x: -x[0])
        return candidates[0]

    R_best, h_best = best_seed()

    # Stage 1: polish on current grid (tie-aware full L-BFGS)
    t_stage = t0 + 0.25 * budget_seconds
    hp = _full_lbfgs(h_best, t_stage, maxiter=400)
    Rp = R_of(hp)
    if Rp > R_best:
        R_best, h_best = Rp, hp
        candidates.append((R_best, h_best.copy()))

    # Stage 2: CVaR-smoothed polish to escape plateau (soft max)
    t_stage = t0 + 0.40 * budget_seconds
    for alpha in (0.05, 0.02, 0.01):
        if time.process_time() > t_stage:
            break
        hp = _cvar_lbfgs(h_best, t_stage, alpha=alpha, maxiter=200)
        hp = _full_lbfgs(hp, t_stage, maxiter=150)
        Rp = R_of(hp)
        if Rp > R_best:
            R_best, h_best = Rp, hp
            candidates.append((R_best, h_best.copy()))

    # Stage 3: progressive upsampling with polishing
    t_stage = t0 + 0.80 * budget_seconds
    N = h_best.size
    targets = [n for n in (2 * N, 4 * N, 8 * N, 16 * N) if n <= 40000]
    for N2 in targets:
        if time.process_time() > t_stage:
            break
        h_up = _upsample(h_best, N2)
        h_up = _rescale(h_up)
        h_up = _full_lbfgs(h_up, t_stage, maxiter=250)
        h_up = _peak_window_polish(h_up, t_stage, frac=6)
        h_up = _full_lbfgs(h_up, t_stage, maxiter=150)
        Rp = R_of(h_up)
        if Rp > R_best:
            R_best, h_best = Rp, h_up
            candidates.append((R_best, h_best.copy()))

    # Stage 4: Fourier (sqrt) parametrisation - different landscape
    t_fourier = t0 + 0.90 * budget_seconds
    if time.process_time() < t_fourier - 1.0:
        hf = _fourier_lbfgs(h_best, t_fourier, maxiter=300)
        hf = _peak_window_polish(hf, t_fourier, frac=6)
        hf = _full_lbfgs(hf, t_fourier, maxiter=200)
        Rf = R_of(hf)
        if Rf > R_best:
            R_best, h_best = Rf, hf
            candidates.append((R_best, h_best.copy()))

    # Stage 5: final peak-window fine polish
    while time.process_time() < deadline - 0.5:
        hp = _peak_window_polish(h_best, deadline, frac=10)
        Rp = R_of(hp)
        if Rp > R_best + 1e-12:
            R_best, h_best = Rp, hp
        else:
            break

    if h_best is None or h_best.sum() <= 0:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    print("final R =", R_best, "N =", len(h_best))

    result = {"best": h_best}
    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        sr = R_of(hs)
        if sr > R_best:
            result["best"] = hs
        else:
            result["alternative"] = hs
    return result

