        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


# ---------- NEW IDEA: sub-cell degrees of freedom via lift/fold ----------
# The plateau near the max of f*f stalls per-knot L-BFGS. We lift the shape to
# a finer grid (mass-preserving cumulative-sum interpolation), optimise there,
# and fold back. The lift/fold pair is exactly mass-preserving, so ||f*f||_1
# is untouched; we gain sub-cell degrees of freedom.

def _lift(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    return np.clip(np.diff(C2), 0, None)


def _fold(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    return np.clip(np.diff(C), 0, None)


def _lift_polish(h, deadline, factor=2, iters=120):
    if time.process_time() >= deadline - 0.8:
        return h
    N = h.size
    N2 = min(N * factor, 250000)
    if N2 <= N:
        return h
    h2 = _lift(h, N2)
    h2 = _rescale(h2)
    r2 = R_of(h2)
    h2b = _lbfgs_all_pos(h2, iters, deadline - 0.5)
    if R_of(h2b) > r2:
        h2 = h2b
    hf = _fold(h2, N)
    hf = _rescale(hf)
    if R_of(hf) > R_of(h) + 1e-15:
        return hf
    return h


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _block_refine(h, deadline, nblocks, iters_per=120, overlap=0.15):
    N = h.size
    if N < 8:
        return h
    edges = np.linspace(0, N, nblocks + 1).astype(int)
    ov = max(1, int(N / nblocks * overlap))
    Lf = _knots(h)
    mx = Lf.max()
    impact = []
    for b in range(nblocks):
        lo = edges[b]; hi = edges[b + 1]
        khi = min(Lf.size, hi + 2)
        impact.append(np.sum(np.abs(Lf[lo:khi] - mx)))
    order = [b for _, b in sorted(zip(impact, range(nblocks)), reverse=True)]
    for b in order:
        if time.process_time() > deadline - 0.5:
            break
        lo = max(0, edges[b] - ov)
        hi = min(N, edges[b + 1] + ov)
        win = np.arange(lo, hi)
        ht = _lbfgs_block(h, win, iters_per, deadline - 0.4)
        if R_of(ht) > R_of(h) + 1e-15:
            h = ht
    return h


def _coarsen(h, c):
    n = h.size
    m = (n + c - 1) // c
    pad = m * c - n
    hh = np.concatenate((h, np.zeros(pad)))
    return hh.reshape(m, c).sum(axis=1)


def _refine_roundtrip(h, deadline, factor=2, iters=120):
    """Coarsen then lift back: another way to escape the plateau."""
    if time.process_time() >= deadline - 1.0:
        return h
    hc = _coarsen(h, factor)
    hc = _rescale(hc)
    hc = _lbfgs_all_pos(hc, iters, deadline - 0.6)
    hl = _lift(hc, h.size)
    hl = _rescale(hl)
    if R_of(hl) > R_of(h) + 1e-15:
        return hl
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)

    startR = R_of(best)
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase 0: lift-to-finer-grid polish.
    ph0 = t0 + budget_seconds * 0.35
    for fac in (2, 3):
        if time.process_time() > ph0 - 3.0:
            break
        ht = _lift_polish(best, ph0, factor=fac, iters=100)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P0 lift x%d R=%.9f" % (fac, bestR))

    # Phase 1: block refinement.
    ph1 = t0 + budget_seconds * 0.55
    if time.process_time() < ph1 - 3.0:
        ht = _block_refine(best, ph1, nblocks=64, iters_per=120)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P1 block R=%.9f" % bestR)

    # Phase 2: peak ladder on tight window around max.
    ph2 = t0 + budget_seconds * 0.68
    if time.process_time() < ph2 - 3.0:
        ht = _peak_ladder(best, ph2 - 0.5, pads=(0.08, 0.05, 0.03), iters=200)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P2 peak R=%.9f" % bestR)

    # Phase 3: coarsen/lift roundtrip.
    ph3 = t0 + budget_seconds * 0.78
    if time.process_time() < ph3 - 3.0:
        ht = _refine_roundtrip(best, ph3, factor=2, iters=100)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P3 roundtrip R=%.9f" % bestR)

    # Phase 4: second lift pass.
    ph4 = t0 + budget_seconds * 0.87
    if time.process_time() < ph4 - 3.0:
        ht = _lift_polish(best, ph4, factor=2, iters=100)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P4 lift2 R=%.9f" % bestR)

    # Phase 5: final global L-BFGS.
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 2.0:
        ht = _lbfgs_all_pos(best, 300, fd - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P5 global R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


# ---------- sharp staircase representation ----------
# Represent h as M levels a_j on contiguous blocks, allowing exact block
# boundaries to be optimised. This explores a structurally different family
# (piecewise-constant with sharp jumps) than the free per-step optimisation.

def _build_sharp(a, bounds, N):
    M = a.size
    h = np.empty(N)
    prev = 0
    for j in range(M - 1):
        bb = int(min(max(bounds[j], prev), N))
        h[prev:bb] = a[j]
        prev = bb
    h[prev:] = a[M - 1]
    return h


def _fun_grad_sharp(a, bounds, N):
    h = _build_sharp(a, bounds, N)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(a.size), np.zeros(a.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    gh = _backprop(gLf, h) + 2.0 / s
    # gradient wrt levels = sum over block of gh
    ga = np.zeros(a.size)
    gb = np.zeros(a.size)
    prev = 0
    for j in range(a.size - 1):
        bb = int(min(max(bounds[j], prev), N))
        ga[j] = gh[prev:bb].sum()
        # boundary gradient: d/db of (a[j] - a[j+1]) * gh at boundary
        if bb < N:
            gb[j] = (a[j] - a[j + 1]) * gh[bb]
        prev = bb
    ga[-1] = gh[prev:].sum()
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, ga, gb


def _optimize_sharp(a0, b0, N, deadline, maxiter=300):
    a = np.clip(a0, 1e-12, None).copy()
    b = np.asarray(b0, dtype=float).copy()
    M = a.size
    # joint variables: log(a) and continuous b
    x0 = np.concatenate([np.log(a), b])

    def unpack(x):
        aa = np.exp(np.clip(x[:M], -40.0, 40.0))
        bb = x[M:]
        return aa, bb

    def f(x):
        aa, bb = unpack(x)
        val, ga, gb = _fun_grad_sharp(aa, bb, N)
        return val, np.concatenate([ga * aa, gb])

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * M + [(0.0, N)] * (M - 1),
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return None
    if res is None:
        return None
    aa, bb = unpack(res.x)
    return _build_sharp(aa, bb, N)


def _extract_blocks(h, max_blocks=400):
    """Coarsen h into a staircase: merge into ~max_blocks blocks by
    quantising heights and finding runs."""
    n = h.size
    if n <= max_blocks:
        return h.copy(), np.arange(1, n)
    # simple: equal-count bins with mean height
    edges = np.linspace(0, n, max_blocks + 1).astype(int)
    a = np.empty(max_blocks)
    for i in range(max_blocks):
        a[i] = h[edges[i]:edges[i + 1]].mean()
    b = edges[1:-1].copy()
    return a, b


def _sharp_restart(h, deadline, block_sizes=(200, 400, 800)):
    """Try staircase representation at various block counts."""
    best = h.copy()
    bestR = R_of(h)
    for M in block_sizes:
        if time.process_time() >= deadline - 1.0:
            break
        if M >= h.size:
            continue
        a, b = _extract_blocks(h, M)
        cand = _optimize_sharp(a, b, h.size, deadline - 0.8, maxiter=200)
        if cand is None:
            continue
        cand = _rescale(cand)
        r = R_of(cand)
        if r > bestR + 1e-13:
            best, bestR = cand, r
    return best, bestR


def _insert_peak_step(h, deadline):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h, R_of(h)
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    Lf = _knots(best)
    m = int(np.argmax(Lf))
    tries = set()
    for off in (-3, -2, -1, 0, 1, 2, 3):
        p = m + off
        if 1 <= p < n:
            tries.add(p)
    for p in sorted(tries):
        if time.process_time() >= deadline - 0.2:
            break
        val = 0.5 * (best[p - 1] + best[p]) if p < n else best[p - 1]
        cand = np.concatenate([best[:p], [val], best[p:]])
        win = np.arange(max(0, p - 8), min(cand.size, p + 9))
        cand2 = _lbfgs_block(cand, win, maxiter=80, deadline=deadline, beta=0.0)
        r = R_of(cand2)
        if r > bestR + 1e-14:
            best, bestR = cand2, r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: full polish.
    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("cycle1 R=%.7f" % bestR)

    # Phase 2: staircase restarts (structurally different family).
    if time.process_time() < deadline - 3.0:
        hs, rs = _sharp_restart(best, deadline - 2.0)
        if rs > bestR + 1e-13:
            best, bestR = hs, rs
            best, bestR = run_cycle(best, bestR, deadline - 2.0)
        print("sharp restart R=%.7f" % bestR)

    # Phase 3: insertion near peak.
    rounds = 0
    while time.process_time() < deadline - 2.5 and rounds < 3:
        before = bestR
        ht, rt = _insert_peak_step(best, deadline - 2.0)
        if rt > bestR + 1e-13:
            best, bestR = ht, rt
            best, bestR = run_cycle(best, bestR, deadline - 2.0)
        rounds += 1
        print("insert %d R=%.7f dR=%.2e" % (rounds, bestR, bestR - before))
        if bestR - before < 1e-11:
            break

    # Phase 4: final polish.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.8, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-5:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0 or h.size < 1:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    m = L.max()
    if m <= 0:
        return 0.0
    return num / (s * s * m)


def _rescale(h):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0:
        return h
    return h / s * h.size


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _lbfgs(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        x = res.x
    except Exception:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_R = -1.0
    start_h = None
    start_R = -1.0

    if start is not None:
        s = np.clip(np.asarray(start, dtype=float), 0, None)
        if s.size > 0 and s.sum() > 0:
            start_h = _rescale(s.copy())
            start_R = _R_of(start_h)
            best_h = start_h.copy()
            best_R = start_R

    if best_h is None:
        N = 4096
        best_h = _rescale(np.ones(N))
        best_R = _R_of(best_h)

    print(f"start N={best_h.size} R={best_R:.6f}")

    def consider(hh):
        nonlocal best_h, best_R
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh.copy()
        return R

    def fg_exact(hh):
        return _fun_grad(hh)

    # Phase 1: CVaR-based smooth approximation to max (better than softmax for
    # sharp peaks), plus beta ladder, windowed then full.
    alphas = [0.30, 0.15, 0.08, 0.04, 0.02]
    for alpha in alphas:
        if time.process_time() > hard_deadline - 2.0:
            break
        remaining = hard_deadline - time.process_time()
        seg_deadline = time.process_time() + remaining * 0.10
        free = _peak_window(best_h, tol=0.999, pad_frac=0.5)
        fg = (lambda hh, a=alpha: _fun_grad_cvar(hh, a))
        hh = _lbfgs(best_h, free, maxiter=120, deadline=seg_deadline, fg=fg)
        consider(hh)

    betas = [4.0, 16.0, 64.0]
    for beta in betas:
        if time.process_time() > hard_deadline - 2.0:
            break
        remaining = hard_deadline - time.process_time()
        seg_deadline = time.process_time() + remaining * 0.10
        free = _peak_window(best_h, tol=0.999, pad_frac=0.5)
        fg = (lambda hh, b=beta: _fun_grad_beta(hh, b))
        hh = _lbfgs(best_h, free, maxiter=120, deadline=seg_deadline, fg=fg)
        consider(hh)
        print(f"beta={beta:.1f} best={best_R:.6f}")

    # Phase 2: full-variable exact polish
    for it in range(4):
        if time.process_time() > hard_deadline - 1.0:
            break
        remaining = hard_deadline - time.process_time()
        seg_deadline = time.process_time() + remaining * 0.25
        free = np.arange(best_h.size)
        hh = _lbfgs(best_h, free, maxiter=150, deadline=seg_deadline, fg=fg_exact)
        consider(hh)
        print(f"full it={it} best={best_R:.6f}")

    # Phase 3: windowed exact polishes at varying scales centered on peak
    fracs = [0.30, 0.20, 0.12, 0.07, 0.04, 0.02]
    cyc = 0
    while time.process_time() < hard_deadline - 0.5:
        frac = fracs[cyc % len(fracs)]
        cyc += 1
        remaining = hard_deadline - time.process_time()
        seg_deadline = time.process_time() + min(remaining * 0.25, remaining)
        Lf = _knots(best_h)
        am = int(np.argmax(Lf))
        center = am / 2.0
        half = max(8.0, frac * best_h.size)
        lo = max(0, int(center - half))
        hi = min(best_h.size, int(center + half) + 1)
        free = np.arange(lo, hi)
        hh = _lbfgs(best_h, free, maxiter=200, deadline=seg_deadline, fg=fg_exact)
        consider(hh)
        if cyc % 3 == 0:
            print(f"win frac={frac} best={best_R:.6f}")

    best_h = _rescale(best_h)
    print(f"final R={_R_of(best_h):.6f}")

    if start_h is not None:
        Rb = _R_of(best_h)
        if start_R > Rb:
            return {"best": start_h, "alternative": best_h}
        if Rb > start_R:
            return {"best": best_h, "alternative": start_h}
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = int(np.ceil((1.0 - q) * n))
    if m < 1:
        m = 1
    if m > n:
        m = n
    order = np.argsort(Lf)
    top = order[-m:]
    mean_top = Lf[top].mean()
    if mean_top <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[top] += (1.0 / m) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_cvar(h0, q, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_cvar(hh, q)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def _argmax_pos(h):
    Lf = _knots(h)
    return float(np.argmax(Lf)) / max(1, Lf.size - 1)


def _jump_profile(h, a, b, rng):
    from scipy.ndimage import gaussian_filter1d
    L = b - a
    if L <= 0:
        return np.zeros(0)
    seg = h[a:b].copy()
    if rng.random() < 1.0 / 3.0:
        m = seg.mean() if seg.size else h.mean()
        g = np.full(L, m)
    else:
        sig1 = max(1.0, L / 20.0)
        sig2 = max(1.0, L / 40.0)
        base = gaussian_filter1d(seg, sig1, mode='nearest')
        noise = rng.standard_normal(L)
        noise = gaussian_filter1d(noise, sig2, mode='nearest')
        g = base * (1.0 + 0.35 * noise)
    g = np.clip(g, 0.0, None)
    return g


def _flatten(h, factor):
    """Blend heights toward their local mean to escape sharp local optima."""
    if factor <= 0:
        return h
    from scipy.ndimage import uniform_filter1d
    m = uniform_filter1d(h, size=max(2, int(h.size * 0.02)), mode='nearest')
    return np.clip((1 - factor) * h + factor * m, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    inc = start_best.copy()
    incR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f argmax=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01), _argmax_pos(best)))

    # ---- CVaR q-anneal ladder ----
    qs = (0.90, 0.95, 0.98, 0.995, 0.999)
    cvar_deadline = t0 + budget_seconds * 0.25
    per_q = budget_seconds * 0.04
    for q in qs:
        if time.process_time() >= cvar_deadline - 1.0:
            break
        dq = min(cvar_deadline, time.process_time() + per_q)
        ht = _lbfgs_cvar(best, q, 20, dq)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            inc, incR = ht.copy(), r
            print("cvar q=%.3f NEW BEST R=%.9f" % (q, bestR))

    # ---- structural jump Metropolis loop with flattening restarts ----
    N = best.size
    T = 2e-6
    trial = 0
    accepted = 0
    since_improve = 0
    while time.process_time() < deadline - 1.5:
        trial += 1
        L = int(rng.integers(max(2, int(0.03 * N)), max(3, int(0.15 * N))))
        a = int(rng.integers(0, max(1, N - L)))
        b = min(N, a + L)
        cand = inc.copy()
        cand[a:b] = _jump_profile(inc, a, b, rng)
        cand = _rescale(cand)

        fd = min(deadline, time.process_time() + budget_seconds * 0.02)
        win = np.arange(a, b)
        cand = _lbfgs_block(cand, win, 80, fd)
        if time.process_time() < deadline - 1.0:
            fd2 = min(deadline, time.process_time() + budget_seconds * 0.02)
            pw = _peak_window(cand, tol=0.95, pad_frac=0.05, extra=64)
            cand = _lbfgs_block(cand, pw, 150, fd2)

        r = R_of(cand)
        dR = r - incR
        if dR > 0:
            inc, incR = cand.copy(), r
            accepted += 1
        else:
            if T > 0 and rng.random() < np.exp(dR / T):
                inc, incR = cand.copy(), r
                accepted += 1
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
            since_improve = 0
            print("trial %d NEW BEST R=%.9f (a=%d,L=%d, zero=%.4f, nearmax5=%.4f, argmax=%.4f)"
                  % (trial, bestR, a, L, _zero_frac(best),
                     _nearmax_frac(best), _argmax_pos(best)))
        else:
            since_improve += 1
        T *= 0.97
        if T < 1e-12:
            T = 2e-6 * 0.5

        # Restart from a slightly flattened copy of best when stuck
        if since_improve > 40 and time.process_time() < deadline - 3.0:
            f = rng.uniform(0.02, 0.10)
            cand = _flatten(best, f)
            cand = _rescale(cand)
            fd = min(deadline, time.process_time() + budget_seconds * 0.03)
            cand = _lbfgs_all_pos(cand, 100, fd)
            r2 = R_of(cand)
            if r2 > incR:
                inc, incR = cand.copy(), r2
            if r2 > bestR + 1e-15:
                best, bestR = cand.copy(), r2
                print("trial %d flatten-restart NEW BEST R=%.9f" % (trial, bestR))
            since_improve = 0

        if trial % 60 == 0 and time.process_time() < deadline - 2.0:
            fd3 = min(deadline, time.process_time() + budget_seconds * 0.05)
            ht = _lbfgs_all_pos(inc, 120, fd3)
            r2 = R_of(ht)
            if r2 > incR:
                inc, incR = ht.copy(), r2
            if r2 > bestR + 1e-15:
                best, bestR = ht.copy(), r2
                print("trial %d full-polish NEW BEST R=%.9f" % (trial, bestR))
            if time.process_time() < deadline - 1.5:
                fd4 = min(deadline, time.process_time() + budget_seconds * 0.05)
                hb = _lbfgs_all_pos(best, 120, fd4)
                rb = R_of(hb)
                if rb > bestR + 1e-15:
                    best, bestR = hb.copy(), rb
                    print("trial %d best-polish NEW BEST R=%.9f" % (trial, bestR))

    print("final R=%.9f (start %.9f, N=%d, trials=%d, accepted=%d, zero_frac=%.4f, nearmax5=%.4f, argmax=%.4f)"
          % (bestR, start_bestR, best.size, trial, accepted,
             _zero_frac(best), _nearmax_frac(best), _argmax_pos(best)))

    result = {"best": best}
    if incR > bestR + 1e-15:
        result["best"] = inc
    result["alternative"] = inc
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


# ---------- log-domain (positivity-preserving) polish ----------

def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _lbfgs_log(h0, deadline, maxiter=150, fun_grad=_fun_grad_tie,
               mask=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if mask is None:
        pos = np.flatnonzero(h > 0)
    else:
        pos = np.flatnonzero(mask & (h > 0))
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


# ---------- Fourier (w = irfft(z), h = w^2) machinery ----------

def _fourier_grad(z, N):
    w = np.fft.irfft(z, n=N)
    h = w * w
    val, gh = _fun_grad_tie(h)
    dw = 2.0 * w * gh
    gz = np.fft.rfft(dw) * (2.0 / N)
    if N % 2 == 0:
        gz[0] *= 0.5
        gz[-1] *= 0.5
    return val, gz, h


def _fourier_pack(z):
    return np.concatenate([z.real, z.imag])


def _fourier_unpack(x, nz):
    return x[:nz] + 1j * x[nz:]


def _fourier_polish(h0, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.5:
        return h0
    N = h0.size
    w0 = np.sqrt(np.clip(h0, 0, None))
    z0 = np.fft.rfft(w0)
    nz = z0.size
    x0 = _fourier_pack(z0)

    def f(x):
        z = _fourier_unpack(x, nz)
        val, gz, _ = _fourier_grad(z, N)
        return val, _fourier_pack(gz)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    z = _fourier_unpack(res.x, nz)
    w = np.fft.irfft(z, n=N)
    h = w * w
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    work = start_best.copy()

    # Phase A: full-array beta polish.
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "beta%g" % beta
        print("beta%g: R=%.9f" % (beta, r))

    # Phase B: log-domain interior polish on positive indices.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_log(work, deadline - 0.5, maxiter=200)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "log"
        print("log: R=%.9f" % r)

    # Phase C: sharp beta=0 full polish.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(work, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "sharp0"
        print("sharp0: R=%.9f" % r)

    # Phase D: Fourier (w^2) polish — a genuinely different coordinate
    # system that keeps h >= 0 automatically and lets smooth structure
    # emerge in w-space.
    if time.process_time() < deadline - 1.0:
        ht = _fourier_polish(work, deadline - 0.5, maxiter=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "fourier"
        print("fourier: R=%.9f" % r)

    # Phase E: peak-window polish cycles alternating sharp and log.
    pads = [0.25, 0.15, 0.20, 0.10, 0.18, 0.08, 0.15, 0.06]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        mask = np.zeros(work.size, dtype=bool)
        mask[win] = True
        ht = _lbfgs_log(work, deadline - 0.3, maxiter=150, mask=mask)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "pklog%d" % it
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "pk%d+all" % it
        print("cycle %d pad=%.2f: R=%.9f" % (it, pad, bestR))

    # Phase F: final Fourier + sharp polish if time remains.
    if time.process_time() < deadline - 1.0:
        ht = _fourier_polish(work, deadline - 0.4, maxiter=200)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = origin + "+fourier2"
        print("fourier2: R=%.9f" % r)
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = origin + "+sharp0b"
        print("sharp0b: R=%.9f" % r)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if work is not None and work.size == start_best.size:
        return {"best": best, "alternative": work}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8, maxiter=80):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


# ---------- sharp staircase machinery ----------

def _build_sharp(u, b, N):
    M = u.size
    a = np.exp(np.clip(u, -40.0, 40.0))
    bounds = np.clip(np.asarray(b, dtype=int), 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] < bounds[j - 1] + 1:
            bounds[j] = bounds[j - 1] + 1
    h = np.empty(N)
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        h[prev:bb] = a[j]
        prev = bb
    h[prev:] = a[M - 1]
    return h


def _fun_grad_sharp(u, b, N):
    h = _build_sharp(u, b, N)
    val, gh = _fun_grad_tie(h)
    # backprop to levels: a[j] gets sum of gh over its block
    M = u.size
    bounds = np.clip(np.asarray(b, dtype=int), 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] < bounds[j - 1] + 1:
            bounds[j] = bounds[j - 1] + 1
    edges = np.concatenate(([0], bounds, [N]))
    a = np.exp(np.clip(u, -40.0, 40.0))
    ga = np.zeros(M)
    for j in range(M):
        lo = edges[j]; hi = edges[j + 1]
        ga[j] = np.sum(gh[lo:hi])
    gu = ga * a
    return val, gu


def _optimize_sharp(u0, b0, N, deadline, maxiter=200):
    M = u0.size
    x0 = np.concatenate([u0, np.asarray(b0, dtype=float)])

    def f(x):
        u = x[:M]
        b = np.round(x[M:]).astype(int)
        val, gu = _fun_grad_sharp(u, b, N)
        gb = np.zeros(M - 1)
        return val, np.concatenate([gu, gb])

    cb = _make_cb(deadline - 0.2)
    bounds = [(-40.0, 40.0)] * M + [(1, N - 1)] * (M - 1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
