def _extract_sharp_levels(h, M):
    """Fit an M-level staircase to h by clustering."""
    n = h.size
    idx = np.linspace(0, n, M + 1).astype(int)
    u = np.zeros(M)
    b = np.zeros(M - 1, dtype=int)
    for j in range(M):
        lo = idx[j]; hi = idx[j + 1]
        u[j] = np.log(max(h[lo:hi].mean(), 1e-10))
        if j < M - 1:
            b[j] = hi
    return u, b


def construct(budget_seconds, start):
    t0 = time.process_time()
