    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_bestR = bestR
    origin = 'start'
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _try(ht, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        if ht is None:
            return
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR, origin = ht.copy(), r, tag
            print("%s NEW BEST R=%.12f" % (tag, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # Phase 0: quick full polish on the start at its own resolution
    if time.process_time() < deadline - 5.0:
        slice_deadline = min(deadline - 3.0,
                             time.process_time() + 0.10 * budget_seconds)
        ht = best
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= slice_deadline - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
        _try(ht, 'polish')

    # Phase A: half-resolution cycle (coarsen, polish, lift back)
    N = best.size
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 3.0:
        c = best[0::2].copy()
        cR = R_of(c)
        half_deadline = min(deadline - 2.0,
                            time.process_time() + 0.25 * budget_seconds)
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            if rounds > 0:
                rng = np.random.default_rng(rounds + 11)
                amp = [0.008, 0.02, 0.04][rounds % 3]
                cc = work_c.copy()
                nz = cc > 0
                if nz.sum() > 0:
                    cc[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
                work_c = _rescale(cc)
            for beta in [1e6, 1e7]:
                if time.process_time() >= half_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(work_c, 300, half_deadline - 0.3, beta=beta)
                r = R_of(ht)
                if r > best_cR + 1e-15:
                    work_c, best_c, best_cR = ht, ht.copy(), r
            for pad in [0.15, 0.10]:
                if time.process_time() >= half_deadline - 0.5:
                    break
                win = _peak_window(work_c, pad_frac=pad, extra=64)
                ht = _lbfgs_block(work_c, win, 300, half_deadline - 0.3, beta=1e7)
                r = R_of(ht)
                if r > best_cR + 1e-15:
                    work_c, best_c, best_cR = ht, ht.copy(), r
            rounds += 1
        print("half-res rounds=%d R(c)=%.12f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        _try(ht, 'lift')

    # Phase B: smoothing perturbations to escape local optimum
    if time.process_time() < deadline - 4.0:
        sigmas = [0.6, 1.2, 2.0, 3.0, 1.8, 0.9]
        si = 0
        while time.process_time() < deadline - 3.5:
            sigma = sigmas[si % len(sigmas)]
            si += 1
            hs = _rescale(_gauss_smooth(best, sigma))
            slice_deadline = min(deadline - 1.5,
                                 time.process_time() + 0.06 * budget_seconds)
            ht = hs
            for beta in [1e6, 1e7]:
                if time.process_time() >= slice_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 250, slice_deadline - 0.3, beta=beta)
            if time.process_time() < slice_deadline - 0.5:
                ht = _peak_ladder(ht, slice_deadline)
            if time.process_time() < slice_deadline - 0.5:
                ht = _lbfgs_all_pos(ht, 250, slice_deadline - 0.3, beta=0.0)
            if time.process_time() < slice_deadline - 0.5:
                pass
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR, origin = ht.copy(), r, 'smooth%d' % si
                print("smooth sigma=%.2f NEW BEST R=%.12f" % (sigma, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # Phase C: upsample (interleave) to higher N and re-optimize to break grid symmetry
    if time.process_time() < deadline - 3.0:
        n = best.size
        h2 = np.zeros(2 * n)
        h2[0::2] = best
        h2[1::2] = 0.5 * (np.roll(best, 1) + best)
        h2 = _rescale(h2)
        slice_deadline = min(deadline - 1.0,
                             time.process_time() + 0.20 * budget_seconds)
        ht = h2
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= slice_deadline - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
        _try(ht, 'upsample')
        if ht.size == 2 * n:
            hd = _rescale(0.5 * (ht[0::2] + ht[1::2]))
            if time.process_time() < deadline - 1.0:
                hd = _lbfgs_all_pos(hd, 300, deadline - 0.5, beta=0.0)
            _try(hd, 'upsample+down')

    # Phase C2: piecewise-linear upsample (smoother) and polish
    if time.process_time() < deadline - 3.0:
        try:
            h3 = _rescale(_upsample_linear(best, 2))
            slice_deadline = min(deadline - 1.0,
                                 time.process_time() + 0.15 * budget_seconds)
            ht = h3
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
            _try(ht, 'upsample-lin')
        except Exception:
            pass

    # Phase D: fine peak polish on best
    if time.process_time() < deadline - 0.8:
        ht2 = _peak_ladder(best, deadline)
        _try(ht2, origin + '+pk')

    # Phase E: final all-pos polish
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
        _try(ht, origin + '+fin')

    print("final R=%.12f origin=%s (start %.12f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_cvar(h, alpha):
    """Smooth the max via the mean of the top-alpha knots (CVaR-style)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun_grad, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.flatnonzero(h > 1e-14)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _coarsen(h, q):
    n = h.size
    m = n // q
    if m * q != n:
        return None
    return h.reshape(m, q).sum(axis=1)


def _prolongate(qh, q):
    return _rescale(np.repeat(qh, q))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- CVaR smoothing: sweep alpha to spread the max plateau ----
    # The optimum has a broad flat top of the autoconvolution; the tie-gradient
    # is a kink there. Averaging over the top-alpha knots smooths it and lets
    # L-BFGS-B move along the plateau to a better point.
    if time.process_time() < deadline - 4.0:
        cvar_deadline = min(deadline - 2.0,
                            time.process_time() + budget_seconds * 0.5)
        best_cv = best.copy(); best_cvR = bestR
        for alpha in (0.35, 0.25, 0.18, 0.12, 0.08, 0.05, 0.03, 0.02):
            if time.process_time() >= cvar_deadline:
                break
            fg = lambda hh, a=alpha: _fun_grad_cvar(hh, a)
            tlim = min(cvar_deadline, time.process_time() + 2.5)
            cand = _lbfgs(best_cv, fg, tlim, maxiter=150)
            r = R_of(cand)
            if r > best_cvR + 1e-15:
                best_cv, best_cvR = cand.copy(), r
        if best_cvR > bestR + 1e-15:
            best, bestR = best_cv.copy(), best_cvR

    # ---- Multi-scale tie polish: coarsen to smooth, refine ----
    for Q in (8, 4, 2, 1):
        if time.process_time() >= deadline - 2.5:
            break
        if best.size % Q != 0:
            continue
        qh = best if Q == 1 else _coarsen(best, Q)
        if qh is None or qh.size < 32:
            continue
        qh = _rescale(qh)
        tlim = min(deadline - 2.0, time.process_time() + 2.0)
        cand = _lbfgs(qh, _fun_grad_tie, tlim, maxiter=200)
        ph = cand if Q == 1 else _prolongate(cand, Q)
        pr = R_of(ph)
        if pr > bestR + 1e-15:
            best, bestR = ph.copy(), pr

    # ---- Final tie polish until deadline ----
    while time.process_time() < deadline - 0.8:
        pol = _lbfgs(best, _fun_grad_tie,
                     min(deadline - 0.4, time.process_time() + 3.0),
                     maxiter=300)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        else:
            break

    if bestR < startR:
        best = start_best
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    alt = None
    altR = 0.0

    def try_update(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s R=%.7f" % (tag, bestR))
        else:
            if alt is None or r > altR:
                alt, altR = h, r

    # Phase 1: CVaR continuation — smooth the max over the top-alpha band,
    # gradually sharpening alpha toward the true max. This lets mass move
    # across near-tied peak knots, which the hard-max gradient cannot do.
    for alpha in (0.5, 0.25, 0.12, 0.06, 0.03, 0.015, 0.008):
        if time.process_time() >= deadline - 8.0:
            break
        fg = (lambda a=alpha: (lambda hh: _fun_grad_cvar(hh, a)))()
        h = _lbfgs_log(best, 200, deadline, fg=fg)
        try_update(h, "cvar(a=%.3f)" % alpha)

    # Phase 2: tie-aware exact-max polish + peak windows
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 600, deadline, fg=_fun_grad_tie)
        try_update(h, "tie")
        for frac in (0.03, 0.06, 0.12, 0.25):
            if time.process_time() >= deadline - 1.5:
                break
            free = _peak_window(best, frac=frac)
            h = _lbfgs_block(best, free, 300, deadline, fg=_fun_grad_tie)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                improved = True
                print("win(%.2f) R=%.7f" % (frac, bestR))
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if start is not None:
        try:
            startR = R_of(np.asarray(start, dtype=float))
        except Exception:
            startR = 0.0
        if alt is not None and altR > 0 and bestR <= startR + 1e-12:
            return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_softmax(h, beta):
    """Softmax (log-sum-exp) surrogate for max — smoother landscape."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    # shifted log-sum-exp
    z = beta * (Lf - mx)
    w = np.exp(z)
    wsum = w.sum()
    lse = mx + np.log(wsum) / beta
    gLf = -dq / num
    gLf += w / (wsum * lse)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(lse)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=200):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _softmax_lbfgs(h0, deadline, beta=200.0, maxiter=200):
    return _lbfgs_custom(h0, lambda h: _fun_grad_softmax(h, beta),
                         deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=6):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 120, 'maxfun': 240,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _downsample(h, newn):
    """Average-pool h into newn bins (mass-preserving resize)."""
    n = h.size
    if newn == n:
        return h.copy()
    # cumulative mass upsampling
    cs = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, n, newn + 1)
    # interpolate cumulative at edges
    vals = np.interp(edges, np.arange(n + 1), cs)
    out = np.diff(vals)
    return np.clip(out, 0, None)


def _upsample(h, newn):
    """Piecewise-linear upsample preserving rough shape."""
    n = h.size
    if newn == n:
        return h.copy()
    xold = np.linspace(0.0, 1.0, n, endpoint=False)
    xnew = np.linspace(0.0, 1.0, newn, endpoint=False)
    return np.clip(np.interp(xnew, xold, h), 0, None)


def _grad_u(h, pos):
    val, g = _fun_grad_tie(h)
    return g[pos] * h[pos]


def _hvp(u, pos, v, h_template, eps):
    def G(uu):
        hh = h_template.copy()
        hh[pos] = np.exp(uu)
        return _grad_u(hh, pos)
    gp = G(u + eps * v)
    gm = G(u - eps * v)
    return (gp - gm) / (2.0 * eps)


def _lanczos(u, pos, h_template, m=30, deadline=None):
    n = u.size
    m = min(m, n)
    if m < 2:
        return 0.0, np.zeros(n)
    nv = np.linalg.norm(u)
    if nv <= 0:
        nv = 1.0
    eps = 1e-6 * max(1.0, nv)

    def op(v):
        nvv = np.linalg.norm(v)
        if nvv <= 0:
            return np.zeros_like(v)
        e = eps / nvv
        return _hvp(u, pos, v, h_template, e)

    Q = np.zeros((m, n))
    alpha = np.zeros(m)
    beta = np.zeros(m)
    q = np.random.RandomState(12345).randn(n)
    q -= u * (q @ u) / max(u @ u, 1e-30)
    q /= max(np.linalg.norm(q), 1e-30)
    Q[0] = q
    for j in range(m):
        if deadline is not None and time.process_time() > deadline:
            m = j + 1
            Q = Q[:m]; alpha = alpha[:m]; beta = beta[:m]
            break
        w = op(Q[j])
        a = w @ Q[j]
        alpha[j] = a
        w = w - a * Q[j]
        if j > 0:
            w = w - beta[j - 1] * Q[j - 1]
        for _ in range(2):
            w = w - Q[:j + 1].T @ (Q[:j + 1] @ w)
        b = np.linalg.norm(w)
        beta[j] = b
        if j + 1 < m:
            if b < 1e-12:
                m = j + 1
                Q = Q[:m]; alpha = alpha[:m]; beta = beta[:m]
                break
            Q[j + 1] = w / b
    k = len(alpha)
    if k == 0:
        return 0.0, np.zeros(n)
    T = np.diag(alpha[:k])
    for i in range(k - 1):
        T[i, i + 1] = beta[i]
        T[i + 1, i] = beta[i]
    try:
        evals, evecs = np.linalg.eigh(T)
    except Exception:
        return 0.0, np.zeros(n)
    lmin = float(evals[0])
    v = Q[:k].T @ evecs[:, 0]
    return lmin, v


def _escape_along(h, pos, u, v, Rcur, deadline):
    """Try multiple step sizes along direction v (log coords)."""
    vinf = np.max(np.abs(v))
    if vinf <= 0:
        return h, Rcur
    best_h, bestR = h, Rcur
    for scale in (0.02, 0.05, 0.1, 0.2, 0.4, -0.02, -0.05, -0.1, -0.2):
        if time.process_time() > deadline - 0.5:
            break
        vv = v * (scale / vinf)
        hc = h.copy()
        hc[pos] = np.exp(np.clip(u + vv, -40.0, 40.0))
        hc = _rescale(hc)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best_h, bestR = hc, rc
    return best_h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Multi-scale exploration: work at coarser N to escape basin,
    # then upsample back. Small N is much faster per L-BFGS iteration.
    # Try a few scales.
    Nfull = best.size
    scale_candidates = []
    for div in (8, 4, 2):
        nN = max(64, Nfull // div)
        if nN < Nfull:
            scale_candidates.append(nN)

    for nN in scale_candidates:
        if time.process_time() > deadline - 8.0:
            break
        hc0 = _downsample(best, nN) if nN < Nfull else best.copy()
        hc0 = _rescale(hc0)
        # Polish at this scale (cheap)
        tlim = min(deadline - 4.0, time.process_time() + 4.0)
        hp = _full_lbfgs(hc0, tlim, maxiter=200)
        rp = R_of(hp)
        # Upsample back and polish
        if nN < Nfull:
            hu = _upsample(hp, Nfull)
            hu = _rescale(hu)
            tlim = min(deadline - 2.0, time.process_time() + 6.0)
            hf = _full_lbfgs(hu, tlim, maxiter=200)
            rf = R_of(hf)
            if rf > bestR + 1e-15:
                print("  scale N=%d -> upsampled R=%.9f" % (nN, rf))
                best, bestR = hf, rf
        else:
            if rp > bestR + 1e-15:
                print("  scale N=%d R=%.9f" % (nN, rp))
                best, bestR = hp, rp

    # ---- Softmax (smooth max) polish — different landscape, can escape
    if time.process_time() < deadline - 6.0:
        tlim = min(deadline - 3.0, time.process_time() + 5.0)
        hs = _softmax_lbfgs(best, tlim, beta=300.0, maxiter=200)
        rs = R_of(hs)
        if rs > bestR + 1e-15:
            print("  softmax beta=300 R=%.9f" % rs)
            best, bestR = hs, rs

    # ---- Main loop: Lanczos with wider escape + wider peak polish
    iteration = 0
    while time.process_time() < deadline - 2.0:
        iteration += 1
        pos = np.flatnonzero(best > 0)
        if pos.size < 4:
            break
        hmax = best.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        u = np.log(np.clip(best[pos], floor, None))

        lanc_deadline = min(deadline - 1.5, time.process_time() + 10.0)
        lmin, v = _lanczos(u, pos, best, m=30, deadline=lanc_deadline)
        print("iter %d: lambda_min=%.6e (N=%d, active=%d)"
              % (iteration, lmin, best.size, pos.size))

        improved = False
        if lmin < -1e-6 and np.any(v != 0):
            hc, rc = _escape_along(best, pos, u, v, bestR, deadline)
            if rc > bestR + 1e-15:
                print("  escape R=%.9f (was %.9f)" % (rc, bestR))
                tlim = min(deadline - 1.0, time.process_time() + 8.0)
                hp = _full_lbfgs(hc, tlim, maxiter=200)
                rp = R_of(hp)
                if rp > bestR + 1e-15:
                    best, bestR = hp, rp
                    improved = True
                    print("  after polish R=%.9f" % bestR)
                else:
                    best, bestR = hc, rc
                    improved = True

        if not improved:
            tlim = min(deadline - 1.0, time.process_time() + 8.0)
            hp = _full_lbfgs(best, tlim, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp

        # Wider peak polish
        if time.process_time() < deadline - 1.0:
            tlim = min(deadline - 0.8, time.process_time() + 4.0)
            hpk = _peak_window_polish(best, tlim, pad=3, frac=6)
            rpk = R_of(hpk)
            if rpk > bestR + 1e-15:
                best, bestR = hpk, rpk
                print("  peak polish R=%.9f" % bestR)

    # Final polish
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.6, time.process_time() + 6.0)
        h_full = _full_lbfgs(best, tlim, maxiter=250)
        rf = R_of(h_full)
        if rf > bestR + 1e-15:
            best, bestR = h_full, rf

    if bestR < startR:
        best = start_best
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    # Mark alternative if fundamentally different (could be from scale-up)
    alt = best
    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- New idea in this version: a "shifted-support" perturbation. ----
# The start is a highly symmetric optimum. We try nudging the support
# boundaries (trim a few steps from one end, add zeros on the other)
# and re-optimising. Different basin, may climb higher.

def _shift_support(h, shift):
    n = h.size
    if shift == 0:
        return h.copy()
    out = np.zeros_like(h)
    if shift > 0:
        if shift >= n:
            return h.copy()
        out[shift:] = h[:n - shift]
    else:
        s = -shift
        if s >= n:
            return h.copy()
        out[:n - s] = h[s:]
    return out


def _resample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n, endpoint=False)
    new_n = n * factor
    x_new = np.linspace(0.0, 1.0, new_n, endpoint=False)
    return np.interp(x_new, x_old, h, right=h[-1])


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e8), (0.25, 128, 1e8), (0.40, 256, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: base machinery on the start array.
    if time.process_time() < deadline - 8.0:
        ht, rt = run_cycle(best, bestR, deadline - 8.0)
        if rt > bestR + 1e-13:
            best, bestR, origin = ht, rt, origin + '+cycle'
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # Phase B (NEW): shifted-support perturbations. Trim / pad each end,
    # re-optimise on the peak window, keep if better.
    n = best.size
    shifts = [max(1, n // 200), -max(1, n // 200),
              max(1, n // 50), -max(1, n // 50)]
    for sh in shifts:
        if time.process_time() >= deadline - 4.0:
            break
        try:
            hs = _shift_support(best, sh)
            hs = _rescale(hs)
            if hs.sum() <= 0:
                continue
            hs = _seed_zeros(hs)
            win = _peak_window(hs, pad_frac=0.30, extra=128)
            ht = _lbfgs_block(hs, win, maxiter=150,
                              deadline=deadline - 4.0, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR, origin = ht, r, origin + '+shift%d' % sh
                print("shift %d: R=%.9f" % (sh, r))
        except Exception as e:
            print("shift %d failed: %s" % (sh, e))

    # Phase C: try refining on a finer grid (up to 2x), keeping the best.
    for factor in (2,):
        if time.process_time() >= deadline - 3.0:
            break
        try:
            hf = _resample(best, factor)
            if hf.size > 900000:
                continue
            hf = _rescale(hf)
            hf = _seed_zeros(hf)
            hf, rf = run_cycle(hf, R_of(hf), deadline - 3.0)
            print("resample x%d: R=%.9f (N=%d)" % (factor, rf, hf.size))
            if rf > bestR + 1e-13:
                best, bestR, origin = hf, rf, origin + '+fine'
        except Exception as e:
            print("resample failed: %s" % e)

    # Phase D: tight polish on the peak window with whatever time remains.
    try:
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=0.0)
            r = R_of(ht)
            print("tight polish beta=0: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR, origin = ht, r, origin + '+tight0'
        if time.process_time() < deadline - 0.5:
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_block(best, win, 300, deadline - 0.5, beta=1e7)
            r = R_of(ht)
            print("tight polish beta=1e7: R=%.9f" % r)
            if r > bestR + 1e-13:
                best, bestR, origin = ht, r, origin + '+tight7'
    except Exception as e:
        print("tight polish failed: %s" % e)

    print("final R=%.7f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    if beta > 0:
        e = np.exp(np.clip(beta * (Lf - mx), -60, 0))
        Z = e.sum()
        w = e / Z
        sm = mx + np.log(Z) / beta
        gLf = -dq / num + w / sm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    else:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _gauss_smooth(h, sigma):
    if sigma <= 0.5:
        return h.copy()
    r = int(3 * sigma) + 1
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size
    alt, altR = None, 0.0

    def consider(hc, tag=""):
        nonlocal best, bestR, alt, altR
        r = R_of(hc)
        if r > altR:
            alt, altR = hc.copy(), r
        if r > bestR + 1e-15:
            best, bestR = hc.copy(), r
        if tag:
            print("%s R=%.7f" % (tag, r))

    # NEW primary idea: CVaR-over-top-knots polish.
    # Instead of a softmax (which can flatten the true peak) we replace
    # L_inf by the mean of the top alpha-fraction of knots. This gives a
    # dense gradient on the near-peak plateau while still (as alpha -> 0)
    # approaching the true max, and it is more numerically stable than
    # large-beta softmax. Anneal alpha down to a tiny value.
    alphas = [0.05, 0.02, 0.008, 0.003, 0.001, 0.0003]
    h_cur = best.copy()
    for alpha in alphas:
        if time.process_time() >= deadline - 6.0:
            break
        # wrap cvar objective in a log-param L-BFGS
        if time.process_time() < deadline - 6.5:
            h_cur = _lbfgs_cvar(h_cur, alpha, 300, deadline)
            h_cur = _window_polish_cvar(h_cur, deadline, 0.40, 24, alpha)
        r = R_of(h_cur)
        print("cvar alpha=%.4f R=%.7f" % (alpha, r))
        consider(h_cur)

    # Then anneal softmax starting from the cvar result to sharpen peak.
    for beta in [30.0, 100.0, 300.0, 0.0]:
        if time.process_time() >= deadline - 3.0:
            break
        h_cur = _lbfgs_log(h_cur, 300, deadline, beta=beta)
        h_cur = _window_polish_peak(h_cur, deadline, 0.40, 24, beta=beta)
        r = R_of(h_cur)
        print("softmax beta=%.1f R=%.7f" % (beta, r))
        consider(h_cur)

    # Final loop: alternate hard and cvar polishing until time is up.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs_cvar(best, 0.002, 300, deadline)
        h = _window_polish_cvar(h, deadline, 0.40, 24, 0.002)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best


def _lbfgs_cvar(h0, alpha, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_cvar(hh, alpha)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _window_polish_cvar(h, deadline, frac, extra, alpha, maxiter=400):
    if time.process_time() >= deadline - 0.3:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    active = np.arange(lo, hi + 1)
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_cvar(hh, alpha)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, deadline, alpha=0.02, maxiter=150):
    def fg(hh):
        return _fun_grad_cvar(hh, alpha)
    return _lbfgs_custom(h0, fg, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 100, 'maxfun': 200,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(256)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    alt_returned = None

    # Refine on finer grid, map back, or keep if better
    if time.process_time() < deadline - 20.0:
        N_up = min(cur.size * 2, 500000)
        up = _rescale(_prolongate(cur, N_up))
        up = _full_lbfgs(up, deadline - 15.0, maxiter=400)
        up = _peak_window_polish(up, deadline - 12.0, pad=8, frac=6)
        up_r = R_of(up)
        print("alt fine R = %.6f (N_up=%d)" % (up_r, N_up))
        back = _rescale(_coarsen(up, cur.size))
        back_r = R_of(back)
        if back_r > best_r:
            best, best_r = back.copy(), back_r
            cur, cur_r = back.copy(), back_r
        elif up_r > best_r:
            best, best_r = up.copy(), up_r
            cur, cur_r = up.copy(), up_r
        else:
            alt_returned = up.copy()

    # CVaR-based continuation: escape local max by smoothing over top knots
    if time.process_time() < deadline - 8.0:
        for alpha in (0.05, 0.02, 0.01):
            if time.process_time() >= deadline - 6.0:
                break
            c2 = _cvar_lbfgs(cur, deadline - 4.0, alpha=alpha, maxiter=200)
            c2 = _full_lbfgs(c2, deadline - 2.0, maxiter=200)
            r2 = R_of(c2)
            if r2 > cur_r:
                cur, cur_r = c2, r2
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
            print("  cvar a=%.3f R=%.6f" % (alpha, cur_r))

    # Main loop: alternate full LBFGS and peak-window polish with restarts
    last_r = cur_r
    no_improve = 0
    restart_tries = 0
    while time.process_time() < deadline - 1.0:
        cand = _full_lbfgs(cur, deadline, maxiter=1200)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        for frac, pad in ((8, 3), (6, 8), (4, 16)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _peak_window_polish(cur, deadline, pad=pad, frac=frac)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _full_lbfgs(seed, deadline, maxiter=800)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _full_lbfgs(_rescale(perturbed), deadline, maxiter=1000)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt_returned is not None and alt_returned.size != best.size:
            out["alternative"] = alt_returned
        else:
            out["alternative"] = start_arr
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


_LOG_LO = -25.0
_LOG_HI = 12.0


def _lbfgs_logall(h0, maxiter, deadline, beta=0.0, fun_grad=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    hmax = h.max()
    if hmax <= 0:
        return h0
    active = np.flatnonzero(h > 1e-12 * hmax)
    if active.size == 0:
        return h0
    u0 = np.clip(np.log(np.maximum(h[active], 1e-300)), _LOG_LO, _LOG_HI)
    if fun_grad is not None:
        fg = fun_grad
    elif beta > 0:
        fg = lambda hh: _fun_grad_beta(hh, beta)
    else:
        fg = _fun_grad

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, _LOG_LO, _LOG_HI))
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(_LOG_LO, _LOG_HI)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, _LOG_LO, _LOG_HI))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hmax = h.max()
    if hmax <= 0:
        return h0
    mask = h[active] > 1e-12 * hmax
    if not np.any(mask):
        return h0
    sub = active[mask]
    u0 = np.clip(np.log(np.maximum(h[sub], 1e-300)), _LOG_LO, _LOG_HI)
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        hh = h.copy()
        hh[sub] = np.exp(np.clip(u, _LOG_LO, _LOG_HI))
        val, g = fg(hh)
        return val, g[sub] * hh[sub]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(_LOG_LO, _LOG_HI)] * sub.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[sub] = np.exp(np.clip(res.x, _LOG_LO, _LOG_HI))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _active_frac(h, thresh=1e-8):
    hmax = h.max()
    if hmax <= 0:
        return 0.0
    return float(np.mean(h > thresh * hmax))


def _lift_ratio(best, r, rng):
    N = best.size
    M = int(round(N * r))
    if M < 2:
        M = 2
    xf = np.arange(M, dtype=float)
    pos = np.arange(N, dtype=float) * r
    hf = np.interp(xf, pos, best)
    hs = hf.copy()
    hs[1:-1] = 0.25 * hf[:-2] + 0.5 * hf[1:-1] + 0.25 * hf[2:]
    w = rng.dirichlet([3.0, 3.0, 3.0], size=N)
    parent = np.clip(np.round(xf / r).astype(int), 0, N - 1)
    comp = rng.integers(0, 3, size=N)
    pw = w[np.arange(N), comp]
    hs = hs * pw[parent]
    return _rescale(hs)


def _lift_fine(best, factor, rng):
    """Refine to a finer grid by pure interpolation + tiny smoothing,
    keeping the shape (mass preserving)."""
    N = best.size
    M = int(round(N * factor))
    if M < 2:
        M = 2
    xf = np.arange(M, dtype=float)
    pos = np.arange(N, dtype=float) * factor
    hf = np.interp(xf, pos, best)
    hf = np.clip(hf, 0, None)
    return _rescale(hf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, active1e-8=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _active_frac(best)))

    rng = np.random.default_rng(12345)

    # ---- Phase 1: ratio sweep (coarse) ----
    ratios = [(5.0 / 4.0, "5/4"), (4.0 / 3.0, "4/3"), (8.0 / 7.0, "8/7"),
              (7.0 / 6.0, "7/6"), (5.0 / 3.0, "5/3"), (3.0 / 2.0, "3/2")]
    sweep_end = t0 + budget_seconds * 0.55
    per_ratio = 5.0
    consec_fail = 0
    for r, name in ratios:
        if time.process_time() >= sweep_end - 1.0:
            break
        if consec_fail >= 3:
            print("early stop: 3 consecutive ratios with dR<0")
            break
        slice_end = min(sweep_end, time.process_time() + per_ratio)
        try:
            h_r = _lift_ratio(best, r, rng)
        except Exception:
            continue
        h_r = _lbfgs_logall(h_r, 200, slice_end - 3.0, beta=1e4)
        if time.process_time() < slice_end - 2.0:
            h_r = _lbfgs_logall(h_r, 200, slice_end - 1.2, beta=1e5)
        if time.process_time() < slice_end - 1.0:
            h_r = _lbfgs_logall(h_r, 300, slice_end - 0.3, beta=0.0)
        rR = R_of(h_r)
        dR = rR - bestR
        if rR > bestR + 1e-15:
            best, bestR = h_r.copy(), rR
            consec_fail = 0
            print("ratio %s N=%d dR=%+.3e NEW BEST R=%.9f zero_frac=%.4f nearmax5=%.4f active1e-8=%.4f"
                  % (name, best.size, dR, bestR, _zero_frac(best),
                     _nearmax_frac(best), _active_frac(best)))
        else:
            consec_fail += 1
            print("ratio %s N=%d dR=%+.3e no gain (R=%.9f vs %.9f)"
                  % (name, h_r.size, dR, rR, bestR))

    # ---- Phase 2: multi-scale refinement ----
    # Try finer grids: this exposes finer structure that may raise R.
    refine_end = t0 + budget_seconds * 0.78
    for factor, name in [(1.25, "x1.25"), (1.5, "x1.5"), (2.0, "x2.0")]:
        if time.process_time() >= refine_end - 2.0:
            break
        if best.size * factor > 900000:
            continue
        slice_end = min(refine_end, time.process_time() + 5.0)
        h_f = _lift_fine(best, factor, rng)
        h_f = _lbfgs_logall(h_f, 300, slice_end - 2.0, beta=1e5)
        if time.process_time() < slice_end - 1.0:
            h_f = _lbfgs_logall(h_f, 400, slice_end - 0.3, beta=0.0)
        rR = R_of(h_f)
        dR = rR - bestR
        if rR > bestR + 1e-15:
            best, bestR = h_f.copy(), rR
            print("refine %s N=%d dR=%+.3e NEW BEST R=%.9f zero_frac=%.4f nearmax5=%.4f active1e-8=%.4f"
                  % (name, best.size, dR, bestR, _zero_frac(best),
                     _nearmax_frac(best), _active_frac(best)))
        else:
            print("refine %s N=%d dR=%+.3e no gain (R=%.9f vs %.9f)"
                  % (name, h_f.size, dR, rR, bestR))

    # ---- Phase 3: full-active polish with peak-ladder on best ----
    fd = t0 + budget_seconds * 0.92
    # Alternate: full active then peak only then full active again
    for it in range(3):
        if time.process_time() >= fd - 2.0:
            break
        ht = _lbfgs_logall(best, 600, min(fd, time.process_time() + 3.0), beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("POLISH log beta0 ACCEPT R=%.9f" % bestR)
        if time.process_time() >= fd - 1.5:
            break
        ht = _peak_ladder(best, min(fd, time.process_time() + 2.0),
                          pads=(0.06, 0.04, 0.03), iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("POLISH peak ACCEPT R=%.9f" % bestR)
        if time.process_time() >= fd - 1.2:
            break
        ht = _lbfgs_logall(best, 400, min(fd, time.process_time() + 1.5), beta=1e8)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("POLISH log beta8 ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, active1e-8=%.4f)"
          % (bestR, startR, best.size, _zero_frac(best), _nearmax_frac(best),
             _active_frac(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = max(1, int(round(alpha * n)))
    if m >= n:
        m = n - 1
    S = np.argpartition(Lf, n - m)[n - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=200):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, alpha, deadline, maxiter=200):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_cvar(hh, alpha),
                         deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window_polish_frac(h, deadline, frac):
    n = h.size
    pad = max(3, n // frac)
    return _peak_window_polish(h, deadline, pad=pad)


def _shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    u = Lf / mx
    return (np.mean(u >= 0.999), np.mean(u >= 0.99), np.mean(u >= 0.95))


def _revive_and_polish(h, deadline, maxiter=30):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    R0 = R_of(h)
    active = h > 0
    if active.sum() == 0:
        return h
    mean_active = h[active].mean()
    h2 = h.copy()
    h2[~active] = 1e-3 * mean_active
    h2 = _rescale(h2)
    if time.process_time() >= deadline - 0.5:
        return h
    h3 = _full_lbfgs(h2, deadline, maxiter=maxiter)
    if R_of(h3) > R0:
        return h3
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Large-alpha CVaR ladder targeting the plateau fraction.
    alphas = (0.50, 0.40, 0.35, 0.32, 0.30, 0.28, 0.25, 0.20, 0.15, 0.10, 0.05, 0.02)
    # Reserve ~12% of budget for final polish.
    c_end = min(deadline - 1.0, t0 + budget_seconds * 0.88)
    stage_time = max(0.5, (c_end - time.process_time()) / len(alphas))

    for alpha in alphas:
        if time.process_time() >= c_end - 0.5:
            break
        stage_deadline = min(c_end, time.process_time() + stage_time)
        hc = _cvar_lbfgs(best, alpha, stage_deadline, maxiter=80)
        # exact tie polish
        if time.process_time() < stage_deadline - 0.2:
            pol_deadline = min(stage_deadline, time.process_time() + stage_time * 0.5)
            hp = _full_lbfgs(hc, pol_deadline, maxiter=80)
            if R_of(hp) > R_of(hc):
                hc = hp
        Rc = R_of(hc)
        if Rc > bestR:
            best = hc.copy()
            bestR = Rc
        # support revival after small-enough alpha rungs
        if alpha <= 0.35 and time.process_time() < c_end - 1.0:
            rev_deadline = min(c_end, time.process_time() + stage_time * 0.6)
            hr = _revive_and_polish(best, rev_deadline, maxiter=30)
            Rr = R_of(hr)
            if Rr > bestR:
                best = hr.copy()
                bestR = Rr
        s01, s1, s5 = _shares(best)
        print("C a=%.3f R=%.9f best=%.9f sh=%.4f/%.4f/%.4f"
              % (alpha, Rc, bestR, s01, s1, s5))

    # Final exact tie-gradient full polish.
    if time.process_time() < deadline - 1.0:
        pol_deadline = min(deadline - 0.5,
                           time.process_time() + (deadline - time.process_time()) * 0.5)
        hp = _full_lbfgs(best, pol_deadline, maxiter=100)
        if R_of(hp) > bestR:
            best = hp.copy()
            bestR = R_of(hp)
    # Peak-window polish.
    if time.process_time() < deadline - 0.5:
        hp = _peak_window_polish_frac(best, deadline, 8)
        Rp = R_of(hp)
        if Rp > bestR:
            best = hp.copy()
            bestR = Rp
        print("final polish R=%.9f" % Rp)

    s01, s1, s5 = _shares(best)
    print("final R=%.12f (start %.12f, N=%d) sh=%.4f/%.4f/%.4f"
          % (bestR, startR, best.size, s01, s1, s5))
    return {"best": best, "alternative": best.copy()}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _collapse_to_c(h, q):
    N = h.size
    nb = (N + q - 1) // q
    c = np.zeros(nb)
    for j in range(nb):
        seg = h[j * q:(j + 1) * q]
        if seg.size > 0:
            c[j] = seg.mean()
    return c


def _expand_from_c(c, q, N):
    h = np.repeat(c, q)[:N]
    if h.size < N:
        h = np.concatenate([h, np.full(N - h.size, c[-1] if c.size else 0.0)])
    return h


def _lbfgs_c(h0, q, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    N = h0.size
    c = _collapse_to_c(np.clip(h0, 0, None), q)
    nb = c.size
    if nb == 0:
        return h0

    def expand(cv):
        return _expand_from_c(np.clip(cv, 0, None), q, N)

    def f(cv):
        hh = expand(cv)
        val, g = _fun_grad_tie(hh)
        gc = np.zeros(nb)
        for j in range(nb):
            lo = j * q
            hi = min(N, (j + 1) * q)
            if hi > lo:
                gc[j] = g[lo:hi].sum()
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(expand(res.x))


def _newton_block(h0, q, deadline, max_outer=60):
    N = h0.size
    c = _collapse_to_c(np.clip(h0, 0, None), q)
    nb = c.size
    if nb == 0:
        return h0

    def expand(cv):
        return _expand_from_c(np.clip(cv, 0, None), q, N)

    def fg(cv):
        hh = expand(cv)
        val, g = _fun_grad_tie(hh)
        gc = np.zeros(nb)
        for j in range(nb):
            lo = j * q
            hi = min(N, (j + 1) * q)
            if hi > lo:
                gc[j] = g[lo:hi].sum()
        return val, gc

    val, g = fg(c)
    accepted = 0
    for it in range(max_outer):
        if time.process_time() >= deadline - 1.0:
            break
        gn = np.linalg.norm(g)
        if gn < 1e-10:
            break
        # Diagonal-preconditioned gradient direction (cheaper, robust)
        # Use Hessian-vector via finite differences + CG
        state = {'k': 0}

        def hvp(p):
            eps = 1e-6 * max(np.max(np.abs(c)), 1.0) / max(np.max(np.abs(p)), 1.0)
            _, g2 = fg(c + eps * p)
            return (g2 - g) / eps

        # simple CG on (H + lam I) p = -g
        x = np.zeros_like(g)
        r = -g.copy()
        p = r.copy()
        rs = r @ r
        lam = 1e-8 * gn
        if rs <= 0:
            break
        for _ in range(30):
            Ap = hvp(p) + lam * p
            pAp = p @ Ap
            if pAp <= 1e-30:
                break
            alpha = rs / pAp
            x += alpha * p
            r -= alpha * Ap
            rs_new = r @ r
            if rs_new < 1e-20 * (g @ g):
                break
            p = r + (rs_new / rs) * p
            rs = rs_new
        p = x
        step_norm = np.linalg.norm(p)
        if step_norm < 1e-15:
            break
        alpha = 1.0
        ok = False
        for _ in range(30):
            cnew = np.clip(c + alpha * p, 0.0, None)
            vnew, gnew = fg(cnew)
            if vnew < val - 1e-4 * alpha * (g @ p):
                ok = True
                break
            alpha *= 0.5
        if not ok:
            break
        actual = val - vnew
        c, val, g = cnew, vnew, gnew
        accepted += 1
        if actual < 1e-14:
            break
    return _rescale(expand(c))


def _lift_linear(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xp = (np.arange(n) + 0.5) / n
    xq = (np.arange(N) + 0.5) / N
    return np.interp(xq, xp, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    altR = -1.0

    # Strategy: iterate over progressively finer block sizes with Newton,
    # then refine on full N.  This mirrors the original but adds a coarse-to-fine
    # schedule and a finer final block pass.

    q_schedule = [64, 48, 32, 24, 16]
    time_for_newton = budget_seconds * 0.65
    newton_end = min(deadline - 1.0, time.process_time() + time_for_newton)

    for i, q in enumerate(q_schedule):
        if time.process_time() >= newton_end - 1.0:
            break
        # allocate remaining time proportionally to remaining q's
        remaining = newton_end - time.process_time()
        this_end = time.process_time() + remaining / (len(q_schedule) - i)
        hn = _newton_block(best, q, this_end, max_outer=40)
        rn = R_of(hn)
        print("newton q=%d R=%.9f" % (q, rn))
        if rn > altR:
            altR = rn
            alt_best = hn.copy()
        if rn > bestR + 1e-15:
            best, bestR = hn.copy(), rn

    # L-BFGS on block-constant at a moderate q to escape Newton's local basin
    for qq in [32, 16, 8]:
        if time.process_time() >= deadline - 1.0:
            break
        tq_end = min(deadline - 0.5, time.process_time() + (deadline - time.process_time()) / 3.0)
        hq = _lbfgs_c(best, qq, 200, tq_end)
        r1 = R_of(hq)
        print("q=%d lbfgs R=%.9f" % (qq, r1))
        if r1 > altR:
            altR = r1
            alt_best = hq.copy()
        if r1 > bestR + 1e-15:
            best, bestR = hq.copy(), r1

    # full-N tie polish
    if time.process_time() < deadline - 0.5:
        pol = _lbfgs_block(best, np.arange(best.size), 200,
                           min(deadline - 0.3, time.process_time() + 4.0), tie=True)
        rp = R_of(pol)
        print("full-N polish R=%.9f" % rp)
        if rp > altR:
            altR = rp
            alt_best = pol.copy()
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if start is not None and bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = _fun_grad if beta is None else (lambda hh: _fun_grad_sm(hh, beta))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad if beta is None else (lambda hh: _fun_grad_sm(hh, beta))

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        g = fg(hh)
        return g[0], g[1][active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _perturb_peak(h, rng, scale=0.05):
    h = h.copy()
    n = h.size
    lo, hi = _peak_region(h, tol=0.98)
    pad = max(4, int(0.12 * n))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    W = hi - lo + 1
    if W < 4:
        return h
    nmodes = int(rng.integers(1, 4))
    x = np.linspace(0.0, 1.0, W)
    mod = np.ones(W)
    for _ in range(nmodes):
        k = int(rng.integers(1, 5))
        amp = rng.normal(0.0, scale)
        phase = rng.uniform(0, 2 * np.pi)
        mod *= (1.0 + amp * np.sin(2 * np.pi * k * x + phase))
    mod = np.clip(mod, 0.5, 1.5)
    h[lo:hi + 1] *= mod
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard_end = t0 + budget_seconds - 1.2

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=hard_end)
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal cur, cur_r, best, best_r, alternative, alt_r
        if r > cur_r:
            cur, cur_r = cand, r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # Stage 1: baseline smoothing polish (continuation on beta) on start
    h = cur.copy()
    for beta in (400.0, 150.0, 60.0, 25.0):
        if time.process_time() >= hard_end - 0.5:
            break
        c = _lbfgs_log(h, maxiter=300, deadline=hard_end, beta=beta)
        if R_of(c) >= R_of(h):
            h = c
    if time.process_time() < hard_end - 0.5:
        c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
        if R_of(c) >= R_of(h):
            h = c
    _consider(h, R_of(h))
    print("baseline R=%.6f N=%d" % (best_r, best.size))

    # Stage 2: peak-window perturbations with smoothing continuation
    for seed in range(6):
        if time.process_time() >= hard_end - 0.8:
            break
        rng_s = np.random.default_rng(7000 + seed)
        h = _perturb_peak(cur, rng_s, scale=0.07)
        for beta in (600.0, 200.0, 80.0):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _lbfgs_log(h, maxiter=200, deadline=hard_end, beta=beta)
            if R_of(c) >= R_of(h):
                h = c
        if time.process_time() < hard_end - 0.5:
            c = _lbfgs_log(h, maxiter=500, deadline=hard_end)
            if R_of(c) >= R_of(h):
                h = c
        for frac, extra in ((0.20, 12), (0.08, 4)):
            if time.process_time() >= hard_end - 0.5:
                break
            c = _window_polish_peak(h, hard_end, frac, extra, maxiter=300)
            if R_of(c) >= R_of(h):
                h = c
        _consider(h, R_of(h))
    print("peak-exp R=%.6f N=%d" % (best_r, best.size))

    # Stage 3: repeated fine polishing of best
    while time.process_time() < hard_end - 0.8:
        h = best.copy()
        changed = False
        for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4), (0.03, 2), (0.015, 1)):
            if time.process_time() >= hard_end - 0.4:
                break
            c = _window_polish_peak(h, hard_end, frac, extra, maxiter=350)
            if R_of(c) > R_of(h):
                h = c
                changed = True
        if time.process_time() < hard_end - 0.4:
            c = _lbfgs_log(h, maxiter=500, deadline=hard_end)
            if R_of(c) > R_of(h):
                h = c
                changed = True
        r = R_of(h)
        if r > best_r:
            _consider(h, r)
        if not changed:
            break
    print("polish R=%.6f" % best_r)

    if best_r < R_of(start_arr):
        best = start_arr.copy()
        best_r = R_of(best)

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None and alt_r > -1 and alt_r < best_r:
        return {"best": best, "alternative": alternative}
    return best

