        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _grow_refine(h, deadline, target_max=2000000):
    best = h.copy()
    bestR = R_of(best)
    if time.process_time() >= deadline - 1.0:
        return best, bestR
    for factor in [2, 2, 2]:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=0.5, extra=256)
        if win.size < 8:
            break
        lo, hi = win[0], win[-1] + 1
        seg = best[lo:hi]
        up = np.repeat(seg, factor)
        new = np.concatenate([best[:lo], up, best[hi:]])
        if new.size > target_max:
            break
        new = _rescale(new)
        ht = new
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 0.6:
                break
            ht = _lbfgs_all_pos(ht, 200, deadline - 0.4, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            print("refine x%d NEW BEST R=%.9f N=%d" % (factor, bestR, best.size))
        else:
            break
    return best, bestR


def _shift_insert(h, shift, deadline):
    """Insert a step at position `shift` (splitting one step into two equal
    halves), then reoptimise locally. This grows resolution at a chosen
    location, e.g. where the f*f peak sits, without global upsampling."""
    n = h.size
    if shift <= 0 or shift >= n:
        return h, R_of(h)
    hs = np.concatenate([h[:shift], 0.5 * (h[shift - 1] + h[shift]),
                         0.5 * (h[shift - 1] + h[shift]), h[shift:]])
    hs = _rescale(hs)
    ht = hs
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 250, deadline - 0.3, beta=beta)
    return ht, R_of(ht)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: local refinement (upsample peak region) ----
    if time.process_time() < deadline - 3.0:
        best, bestR = _grow_refine(best, t0 + budget_seconds * 0.30)
        origin = 'refine'

    # ---- Phase 2: half-res quotient search ----
    N = best.size
    best_c = None
    best_cR = -1.0
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.42
        work_c, best_c, best_cR, org = _half_cycle(
            c, cR, half_deadline, tag='h0')
        print("half-res R(c)=%.9f" % best_cR)
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2b: NEW - adaptive peak-targeted insertion ----
    # Instead of global upsampling, insert a single step at the location of
    # the f*f peak (which sharpens the peak's shoulder) and locally refine.
    # This adds resolution only where it matters, turning extra steps into
    # better R rather than diluting the profile.
    if time.process_time() < deadline - 4.0:
        ins_deadline = t0 + budget_seconds * 0.60
        tries = 0
        for _ in range(40):
            if time.process_time() >= ins_deadline - 1.0:
                break
            Lf = _knots(best)
            pk = int(np.argmax(Lf))
            # peak of f*f at knot pk corresponds to f index ~ pk/2
            cen = max(1, min(best.size - 1, pk // 2))
            # try a few candidate insertion points around center
            cands = [cen, cen - 1, cen + 1, cen - 2, cen + 2]
            cands = [s for s in cands if 1 <= s < best.size]
            improved = False
            for s in cands:
                if time.process_time() >= ins_deadline - 1.0:
                    break
                ht, r = _shift_insert(best, s, ins_deadline)
                tries += 1
                if r > bestR + 1e-13:
                    best, bestR = ht, r
                    origin = origin + '+ins%d' % s
                    improved = True
                    print("insert@%d NEW BEST R=%.9f N=%d" % (s, bestR, best.size))
                    break
                elif r > alt_bestR:
                    alt_best, alt_bestR = ht.copy(), r
            if not improved:
                # no more gains from insertion; stop early
                if tries > 6:
                    break

    # ---- Phase 3: perturb-restarts on half-res ----
    restart_deadline = t0 + budget_seconds * 0.72
    restarts_done = 0
    restarts_accepted = 0
    if best_c is not None and time.process_time() < restart_deadline - 2.0:
        rng = np.random.default_rng(7)
        amps = [0.004, 0.008, 0.012, 0.02, 0.006, 0.015, 0.003, 0.01]
        ri = 0
        while time.process_time() < restart_deadline - 2.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc2 = best_c.copy()
            nz = cc2 > 0
            if nz.sum() == 0:
                break
            cc2[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc2 = _rescale(cc2)
            r0 = R_of(cc2)
            slice_deadline = min(restart_deadline,
                                 time.process_time() + 0.085 * budget_seconds)
            work_c2, cand_c, cand_cR, org = _half_cycle(
                cc2, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.20, 0.15])
            restarts_done += 1
            h_lift = _rescale(np.repeat(cand_c, 2))
            ht = h_lift
            for beta in [1e6, 1e7]:
                if time.process_time() >= slice_deadline - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 400, slice_deadline - 0.3, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht.copy(), r
                best_c = cand_c.copy()
                best_cR = cand_cR
                restarts_accepted += 1
                origin = 'restart%d' % ri
                print("restart %d amp=%.3f ACCEPT R=%.9f R(c)=%.9f" %
                      (ri, amp, bestR, best_cR))
            else:
                if cand_cR > best_cR + 1e-12:
                    best_c = cand_c.copy()
                    best_cR = cand_cR
                if r > alt_bestR:
                    alt_best, alt_bestR = ht.copy(), r
            if time.process_time() >= restart_deadline - 2.0:
                break

    # ---- Phase 4: refine again on the accepted best (upsample peak) ----
    if time.process_time() < deadline - 3.0:
        best, bestR = _grow_refine(best, t0 + budget_seconds * 0.85)
        origin = origin + '+refine2'

    # ---- Phase 5: full-N polish ----
    if time.process_time() < deadline - 1.5:
        ht = best
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_all_pos(ht, 400, deadline - 1.0, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+full'
            print("full polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    for pad in [0.12, 0.08, 0.05]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.4, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR, origin = ht2.copy(), r2, origin + '+pk'
            print("peak polish pad=%.2f NEW BEST R=%.9f" % (pad, bestR))
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("restarts=%d accepted=%d best_c=%.9f best_full=%.9f" %
          (restarts_done, restarts_accepted, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _cvar_ladder(h0, deadline, alphas, per_rung_time, polish_iters=40):
    """Run CVaR band ladder, returning best (h, R)."""
    best = h0.copy()
    bestR = R_of(best)
    h = h0.copy()
    for a in alphas:
        if time.process_time() >= deadline - 1.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + per_rung_time)
        hc = _lbfgs_custom(h, lambda hh: _fun_grad_cvar(hh, a),
                           tlim, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + per_rung_time * 0.4)
            hc = _lbfgs_custom(hc, _fun_grad_tie, tlim2, maxiter=polish_iters)
        rc = R_of(hc)
        print("cvar a=%.3f R=%.9f (best %.9f)" % (a, rc, bestR))
        h = hc
        if rc > bestR:
            best = hc.copy()
            bestR = rc
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt = None
    altR = -1.0

    alphas = [0.35, 0.25, 0.15, 0.08, 0.04, 0.02]

    # --- main CVaR band ladder ---
    if time.process_time() < deadline - 2.0:
        h1, r1 = _cvar_ladder(best, deadline, alphas, per_rung_time=3.0)
        if r1 > bestR:
            best = h1
            bestR = r1
            print("ACCEPT ladder: %.9f > %.9f" % (bestR, startR))
        else:
            if alt is None or r1 > altR:
                alt = h1
                altR = r1

    # --- restarts with jitter ---
    rng = np.random.RandomState(20240517)
    for r in range(2):
        if time.process_time() >= deadline - 3.0:
            break
        hj = best * (1.0 + 0.005 * rng.randn(best.size))
        hj = _rescale(np.clip(hj, 0, None))
        h2, r2 = _cvar_ladder(hj, deadline, alphas, per_rung_time=2.0)
        print("restart %d R=%.9f (best %.9f)" % (r, r2, bestR))
        if r2 > bestR:
            best = h2
            bestR = r2
        elif alt is None or r2 > altR:
            alt = h2
            altR = r2

    # --- final exact tie polish ---
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 8.0)
        hp = _full_lbfgs(best, tlim, maxiter=150)
        rp = R_of(hp)
        print("final tie polish R=%.9f" % rp)
        if rp > bestR:
            best = hp
            bestR = rp

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if alt is not None and altR > 0 and alt is not best:
        return {"best": best, "alternative": alt}
    return {"best": best}

import numpy as np
import time
