    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _collapse_to_c(h, q):
    N = h.size
    nb = (N + q - 1) // q
    c = np.zeros(nb)
    for j in range(nb):
        seg = h[j * q:(j + 1) * q]
        if seg.size > 0:
            c[j] = seg.mean()
    return c


def _expand_from_c(c, q, N):
    h = np.repeat(c, q)[:N]
    if h.size < N:
        h = np.concatenate([h, np.full(N - h.size, c[-1] if c.size else 0.0)])
    return h


def _lbfgs_c(h0, q, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    N = h0.size
    c = _collapse_to_c(np.clip(h0, 0, None), q)
    nb = c.size
    if nb == 0:
        return h0

    def expand(cv):
        return _expand_from_c(np.clip(cv, 0, None), q, N)

    def f(cv):
        hh = expand(cv)
        val, g = _fun_grad_tie(hh)
        gc = np.zeros(nb)
        for j in range(nb):
            lo = j * q
            hi = min(N, (j + 1) * q)
            if hi > lo:
                gc[j] = g[lo:hi].sum()
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(expand(res.x))


def _kron_optimize(h0, q, maxiter, deadline, rng, jitter_g=0.02, jitter_c=0.002):
    """Optimise h = kron(c, g) with shared intra-block profile g in log space."""
    if time.process_time() >= deadline - 0.3:
        return h0
    N = h0.size
    nc = N // q
    if nc * q != N or nc < 1:
        return h0
    h0c = np.clip(h0, 0, None)
    # init c from block means, g = 1
    c0 = h0c.reshape(nc, q).mean(axis=1)
    if c0.sum() <= 0:
        return h0
    g0 = np.ones(q)
    # jitter in log space
    lc = np.log(np.maximum(c0, 1e-12)) + jitter_c * rng.standard_normal(nc)
    lg = np.log(np.maximum(g0, 1e-12)) + jitter_g * rng.standard_normal(q)
    # center g to remove scale ambiguity (c absorbs scale)
    lg -= lg.mean()

    def build(lc, lg):
        c = np.exp(np.clip(lc, -40, 40))
        g = np.exp(np.clip(lg, -40, 40))
        return np.outer(c, g).ravel()

    def fg(x):
        lc = x[:nc]
        lg = x[nc:]
        hh = build(lc, lg)
        val, gh = _fun_grad_tie(hh)
        gh2 = gh.reshape(nc, q)
        # d/dlog c_j = sum_r h[j,r] * gh[j,r]
        gc = (hh.reshape(nc, q) * gh2).sum(axis=1)
        # d/dlog g_r = sum_j h[j,r] * gh[j,r]
        gg = (hh.reshape(nc, q) * gh2).sum(axis=0)
        # remove scale direction: subtract mean of gg (c absorbs)
        gg = gg - gg.mean()
        return val, np.concatenate([gc, gg])

    x0 = np.concatenate([lc, lg])
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(fg, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * x0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = build(res.x[:nc], res.x[nc:])
    return _rescale(h2)


def _g_spread(h, q):
    N = h.size
    nc = N // q
    if nc * q != N or nc < 1:
        return 0.0
    hh = np.clip(h, 0, None).reshape(nc, q)
    c = hh.mean(axis=1)
    mask = c > 1e-12
    if mask.sum() == 0:
        return 0.0
    g = (hh[mask] / c[mask, None]).mean(axis=0)
    if g.mean() <= 0:
        return 0.0
    return float(g.std() / g.mean())


def _lift_linear(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xp = (np.arange(n) + 0.5) / n
    xq = (np.arange(N) + 0.5) / N
    return np.interp(xq, xp, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    altR = -1.0
    rng = np.random.default_rng(12345)

    def consider(hcand, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hcand)
        print("%s R=%.9f" % (tag, r))
        if r > altR:
            altR = r
            alt_best = hcand.copy()
        if r > bestR + 1e-15:
            best, bestR = hcand.copy(), r
        return r

    # ---- Kronecker experiment: h = kron(c, g) ----
    # q must divide N.  N=104992 = 2^5*17*193.  Divisors: 32, 68, 136, 272.
    q_candidates = [q for q in [32, 68, 136, 272] if N % q == 0]
    print("kron q candidates:", q_candidates)

    # allocate ~55% of budget to kron phase
    kron_end = min(deadline - 2.0, time.process_time() + budget_seconds * 0.55)
    control_R = None

    for qi, q in enumerate(q_candidates):
        if time.process_time() >= kron_end - 1.0:
            break
        remaining = kron_end - time.process_time()
        n_rest = len(q_candidates) - qi
        this_end = time.process_time() + remaining / n_rest
        n_restarts = 3
        q_best = None
        q_bestR = -1.0
        for rst in range(n_restarts):
            if time.process_time() >= this_end - 0.5:
                break
            sub_end = this_end if rst == n_restarts - 1 else \
                time.process_time() + (this_end - time.process_time()) / (n_restarts - rst)
            jg = 0.02 if rst > 0 else 0.0
            jc = 0.002 if rst > 0 else 0.0
            hk = _kron_optimize(best, q, 120, sub_end, rng,
                                jitter_g=jg, jitter_c=jc)
            rk = R_of(hk)
            if rk > q_bestR:
                q_best, q_bestR = hk, rk
        if q_best is not None:
            spread = _g_spread(q_best, q)
            print("kron q=%d bestR=%.9f g_spread=%.4f" % (q, q_bestR, spread))
            consider(q_best, "kron q=%d" % q)
            if q == 32:
                control_R = q_bestR

    # ---- full-N polish of the best kron candidate ----
    if time.process_time() < deadline - 1.0:
        pol_end = min(deadline - 0.5, time.process_time() + budget_seconds * 0.20)
        pol = _lbfgs_block(best, np.arange(best.size), 80, pol_end, tie=True)
        consider(pol, "full-N polish")

    # ---- fall back to base's block-constant refinement if time remains ----
    if time.process_time() < deadline - 1.0:
        for qq in [16, 8]:
            if time.process_time() >= deadline - 0.5:
                break
            tq_end = min(deadline - 0.3,
                         time.process_time() + (deadline - time.process_time()) / 2.0)
            hq = _lbfgs_c(best, qq, 200, tq_end)
            consider(hq, "q=%d lbfgs" % qq)

    if start is not None and bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.1:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[active], floor, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.05)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.05, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _block_mean(h, Nq):
    n = h.size
    if Nq >= n:
        return h.copy()
    if n % Nq == 0:
        return h.reshape(Nq, n // Nq).mean(axis=1)
    edges = np.linspace(0, n, Nq + 1)
    idx = np.round(edges).astype(int)
    out = np.zeros(Nq)
    for i in range(Nq):
        a, b = idx[i], idx[i + 1]
        if b <= a:
            b = a + 1
        out[i] = h[a:b].mean()
    return out


def _lift_linear(h, N):
    """Mass-preserving linear interpolation from h (size n) to size N."""
    n = h.size
    if n == N:
        return h.copy()
    xp = (np.arange(n) + 0.5) / n
    x = (np.arange(N) + 0.5) / N
    out = np.interp(x, xp, h, left=h[0], right=h[-1])
    out = np.clip(out, 0, None)
    if out.sum() > 0 and h.sum() > 0:
        out *= (h.sum() / out.sum())
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best_full = _rescale(base)
            startR = R_of(best_full)
        else:
            best_full, startR = None, 0.0
    else:
        best_full, startR = None, 0.0

    if best_full is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best_full = _rescale(h)
        startR = R_of(best_full)

    N = best_full.size
    print("base R=%.12f (N=%d)" % (startR, N))

    # Work at a reduced quotient for speed, then lift and polish at full N.
    Nq_target = 4096
    hq = _block_mean(best_full, Nq_target)
    hq = _rescale(hq)
    Nq = hq.size
    qR = R_of(hq)
    print("quotient Nq=%d qR=%.12f" % (Nq, qR))

    best_q = hq.copy()
    best_qR = qR

    # Stage 1: full-log polish on quotient
    q_deadline = min(deadline - 15.0, time.process_time() + 10.0)
    if time.process_time() < q_deadline - 0.5:
        h = _lbfgs_log(best_q, np.arange(Nq), 300, q_deadline, beta=0.0)
        r = R_of(h)
        if r > best_qR:
            best_q, best_qR = h, r
            print("q full-log: R=%.12f" % best_qR)

    # Stage 2: beta-window polish on quotient
    if time.process_time() < q_deadline - 0.3:
        win = _peak_window(best_q, tol=0.95, extra=32)
        h = _lbfgs_log(best_q, win, 200, q_deadline, beta=1e6)
        r = R_of(h)
        if r > best_qR:
            best_q, best_qR = h, r
            print("q beta: R=%.12f" % best_qR)

    # Lift quotient to full N
    if time.process_time() < deadline - 5.0:
        lifted = _lift_linear(best_q, N)
        liftR = R_of(lifted)
        print("lift R=%.12f (loss %.3e)" % (liftR, best_qR - liftR))
    else:
        lifted, liftR = best_full, startR

    if liftR > startR:
        cand, candR = lifted, liftR
    else:
        cand, candR = best_full, startR

    # Stage 3: full-N log polish (global)
    t_left = deadline - time.process_time()
    if t_left > 2.0:
        h = _lbfgs_log(cand, np.arange(N), 150,
                       min(deadline - 1.0, time.process_time() + t_left * 0.6),
                       beta=0.0)
        r = R_of(h)
        if r > candR:
            cand, candR = h, r
        print("full log: R=%.12f" % candR)

    # Stage 4: full-N beta-window polish
    if time.process_time() < deadline - 0.5:
        win = _peak_window(cand, tol=0.95, extra=96)
        h = _lbfgs_log(cand, win, 200, deadline - 0.2, beta=1e7)
        r = R_of(h)
        if r > candR:
            cand, candR = h, r
        print("full beta: R=%.12f" % candR)

    if candR < startR:
        cand = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        candR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (candR, startR, cand.size))

    result = {"best": cand}
    if liftR > startR + 1e-14 and lifted.size == N and liftR < candR:
        result["alternative"] = lifted
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    altR = -1.0

    def consider(hc, tag=""):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hc)
        if r > altR:
            altR = r
            alt_best = hc.copy()
        if r > bestR + 1e-15:
            best, bestR = hc.copy(), r
            print("  %s R=%.12f" % (tag, r))
            return True
        return False

    # Multi-scale continuation on beta (soft-max) -> tie (hard max).
    # This is the key change: smooth homotopy on the max term plus
    # peak-window polishing, iterated until convergence.
    full = np.arange(best.size)

    # Phase A: beta-homotopy on full array.
    for beta in [2.0, 8.0, 30.0, 120.0, 500.0, 2000.0]:
        if time.process_time() >= deadline - 3.0:
            break
        fg = (lambda hh, b=beta: _fun_grad_beta(hh, b))
        hc = _lbfgs(best, full, 150,
                    min(deadline - 2.0, time.process_time() + 6.0), fg)
        consider(hc, "beta=%.0f" % beta)

    # Phase B: alternating full tie polish + local window polish.
    for it in range(40):
        if time.process_time() >= deadline - 1.0:
            break
        improved = False

        # full tie polish
        hc = _lbfgs(best, full, 200,
                    min(deadline - 0.8, time.process_time() + 3.0),
                    _fun_grad_tie)
        if consider(hc, "tie-full"):
            improved = True

        # local peak window polish
        Lf = _knots(best)
        pk = int(np.argmax(Lf))
        c = pk / 2.0
        n = best.size
        for frac in [4, 8, 16]:
            if time.process_time() >= deadline - 1.0:
                break
            w = max(16, n // frac)
            lo = max(0, int(c) - w)
            hi = min(n, int(c) + w)
            if hi - lo < 8:
                continue
            idx = np.arange(lo, hi)
            hc = _lbfgs(best, idx, 120,
                        min(deadline - 0.6, time.process_time() + 2.0),
                        _fun_grad_tie)
            if consider(hc, "tie-win/%d" % frac):
                improved = True

        if not improved:
            break

    # Phase C: final beta softening + polish, in case a slightly
    # wider plateau helps.
    if time.process_time() < deadline - 2.0:
        fg = (lambda hh: _fun_grad_beta(hh, 20.0))
        hc = _lbfgs(best, full, 100,
                    min(deadline - 1.0, time.process_time() + 3.0), fg)
        consider(hc, "beta-reheat")
        hc = _lbfgs(best, full, 200, deadline - 0.4, _fun_grad_tie)
        consider(hc, "final-tie")

    print("frac near max (0.1%%) after: %.4f" % _frac_near_max(best, 1e-3))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-15 and alt_best.size == best.size:
        # genuinely different construction that didn't beat start
        if not np.allclose(alt_best, best):
            result = {"best": best, "alternative": alt_best}
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    """CVaR over top-alpha knots of Lf. Value = -log(num) + 2log(s) + log(mean_top)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = max(1, int(round(alpha * n)))
    idx = np.argpartition(Lf, n - m)[n - m:]
    Lm = Lf[idx].mean()
    if Lm <= 0:
        return _fun_grad(h)
    w = np.zeros(n)
    w[idx] = 1.0 / m
    gLf = -dq / num + w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_cvar_log(h0, alpha, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    x0 = np.log(h[pos])

    def f(x):
        hh = h.copy()
        hh[pos] = np.exp(np.clip(x, -50, 50))
        val, g = _fun_grad_cvar(hh, alpha)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -50, 50))
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=3.0, extra=8):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_polish(h, deadline, iters=200):
    win = _peak_window(h)
    ht = _lbfgs_block(h, win, iters, deadline)
    if R_of(ht) > R_of(h):
        return ht
    return h


def _mult_ascent(h, deadline, steps=3000, eta0=5e-3, eta1=1e-5):
    """Cheap long multiplicative ascent restricted to peak window."""
    win = _peak_window(h, tol=0.95, pad_frac=3.0, extra=8)
    if win.size == 0:
        return h
    hw = h.copy()
    for k in range(steps):
        if time.process_time() >= deadline - 0.3:
            break
        val, g = _fun_grad(hw)
        gh = g[win]
        gmax = np.max(np.abs(gh))
        if gmax <= 0:
            break
        frac = k / max(1, steps - 1)
        eta = eta0 * (eta1 / eta0) ** frac
        # ascent direction: -grad (since val is -log R)
        hw[win] = np.clip(hw[win] * (1.0 - eta * gh / gmax), 0.0, None)
        if hw.sum() <= 0:
            return h
    hw = _rescale(hw)
    return hw


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alphas = [0.35, 0.22, 0.14, 0.09, 0.05, 0.03, 0.015, 0.008]
    n_rungs = len(alphas)
    stall = 0
    last_R = bestR
    target = 0.94144174
    exceeded = False

    # time allocation for rungs: up to 60% of budget
    rung_end = t0 + budget_seconds * 0.60
    per_rung = (rung_end - t0) / max(1, n_rungs)

    for ri, alpha in enumerate(alphas):
        if time.process_time() >= rung_end - 0.5:
            break
        rung_dl = min(rung_end, time.process_time() + per_rung)
        h = best.copy()
        ht = _lbfgs_cvar_log(h, alpha, 70, rung_dl)
        # exact tie-aware L-BFGS 40 iters
        ht = _lbfgs_all_pos(ht, 40, rung_dl)
        # peak window polish
        ht = _peak_polish(ht, rung_dl, iters=60)
        r = R_of(ht)
        improved = r > bestR + 1e-14
        if improved:
            best, bestR = ht.copy(), r
            stall = 0
        else:
            stall += 1
        if bestR > target:
            exceeded = True
        print("rung a=%.3f R=%.9f %s (stall=%d)"
              % (alpha, r, "ACCEPT" if improved else "reject", stall))

        # restart from best if exact R dropped a lot (safety)
        if r < bestR - 2e-4:
            pass  # best already kept

        # after rung 4 (index 3) do multiplicative ascent
        if ri == 3:
            madl = min(rung_end, time.process_time() + per_rung * 1.5)
            hm = _mult_ascent(best, madl, steps=3000)
            rm = R_of(hm)
            if rm > bestR + 1e-14:
                best, bestR = hm.copy(), rm
                print("  mult-ascent ACCEPT R=%.9f" % bestR)
            else:
                print("  mult-ascent reject R=%.9f" % rm)

        # support revival if stalled
        if stall >= 3:
            Lf = _knots(best)
            mx = Lf.max()
            if mx > 0:
                # zero-level blocks: heights < 1e-3 * max
                hmax = best.max()
                zeros = np.flatnonzero(best < 1e-3 * hmax) if hmax > 0 else np.array([], dtype=int)
                if zeros.size > 0:
                    rng = np.random.default_rng(12345 + ri)
                    n_trials = min(6, zeros.size)
                    pick = rng.choice(zeros, size=n_trials, replace=False)
                    for z in pick:
                        if time.process_time() >= rung_end - 0.5:
                            break
                        ht2 = best.copy()
                        ht2[z] = rng.uniform(1e-3, 1e-1) * hmax
                        ht2 = _rescale(ht2)
                        ht2 = _lbfgs_all_pos(ht2, 30, rung_end)
                        r2 = R_of(ht2)
                        if r2 > bestR + 1e-14:
                            best, bestR = ht2.copy(), r2
                            stall = 0
                            print("  revival z=%d ACCEPT R=%.9f" % (z, bestR))
                            break
            if stall >= 3:
                print("  revival no gain")

    # final multiplicative ascent
    if time.process_time() < deadline - 2.0:
        fmadl = min(deadline - 1.0, time.process_time() + 2.0)
        hm = _mult_ascent(best, fmadl, steps=3000)
        rm = R_of(hm)
        if rm > bestR + 1e-14:
            best, bestR = hm.copy(), rm
            print("final mult-ascent ACCEPT R=%.9f" % bestR)
        else:
            print("final mult-ascent reject R=%.9f" % rm)

    # full-array tie polish
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 500, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("final full polish ACCEPT R=%.9f" % bestR)
        else:
            print("final full polish reject R=%.9f" % r)

    # peak window polish with remaining time
    if time.process_time() < deadline - 0.3:
        ht = _peak_polish(best, deadline, iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("final peak polish ACCEPT R=%.9f" % bestR)
        else:
            print("final peak polish reject R=%.9f" % r)

    print("final R=%.9f (start %.9f, N=%d, exceeded_target=%s)"
          % (bestR, start_bestR, best.size, exceeded))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = start_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150, gtol=1e-16):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': gtol})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _coarsen(h, c):
    n = h.size
    m = (n + c - 1) // c
    pad = m * c - n
    if pad > 0:
        h = np.concatenate([h, np.zeros(pad)])
    return h.reshape(m, c).mean(axis=1)


def _refine(h, c, deadline, maxiter=100):
    # coarse optimize then refine via upsample
    hc = _coarsen(h, c)
    hc = _full_lbfgs(hc, deadline, maxiter=maxiter)
    idx = np.linspace(0, hc.size - 1, h.size)
    return np.interp(idx, np.arange(hc.size), hc)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.9
    rng = np.random.default_rng(1234567)

    best_h = None
    best_R = -1.0

    def consider(h):
        nonlocal best_h, best_R
        if h is None:
            return
        h = np.clip(np.asarray(h, dtype=float), 0, None)
        if h.sum() <= 0:
            return
        r = R_of(h)
        if r > best_R:
            best_R = r
            best_h = h.copy()

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.max() > 0:
            consider(s)

    # Work at a moderate N; start is 32768
    N = 32768
    if best_h is None:
        h0 = np.ones(N)
        h0[: N // 4] = 0.0
        h0[3 * N // 4:] = 0.0
        best_h = h0
        best_R = R_of(h0)

    # Ensure right size
    if best_h.size != N:
        idx = np.linspace(0, best_h.size - 1, N)
        best_h = np.interp(idx, np.arange(best_h.size), best_h)
        best_R = R_of(best_h)

    # Multi-scale refinement: coarse optimize, then refine at N
    # Phase 1: coarse (speed)
    cur = best_h.copy()
    for c in (32, 16, 8, 4, 2, 1):
        if time.process_time() > deadline * 0.85:
            break
        hc = _coarsen(cur, c)
        hc = _full_lbfgs(hc, min(deadline * 0.85, time.process_time() + (deadline - time.process_time()) * 0.4),
                         maxiter=60)
        idx = np.linspace(0, hc.size - 1, N)
        cur = np.interp(idx, np.arange(hc.size), hc)
        consider(cur)

    # Phase 2: full-res tie polish
    cur = _full_lbfgs(best_h, deadline * 0.92, maxiter=200)
    consider(cur)

    # Phase 3: peak window polish at full resolution (multiple windows)
    cur = best_h.copy()
    for _ in range(3):
        if time.process_time() > deadline * 0.95:
            break
        cur = _peak_window_polish(cur, deadline * 0.95, frac=6)
        consider(cur)

    # Phase 4: final tie polish
    if time.process_time() < deadline:
        cur = _full_lbfgs(best_h, deadline, maxiter=100)
        consider(cur)

    if start is not None:
        Rs = R_of(np.asarray(start, dtype=float))
        if Rs > best_R:
            print(f"start wins: {Rs:.6f} vs {best_R:.6f}")
            return {"best": np.asarray(start, dtype=float), "alternative": best_h}

    print(f"best R={best_R:.6f}  CPU {time.process_time()-t0:.1f}s")
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += 1.0 / (idx.size * mx)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _coarsen(h, f):
    N = h.size
    m = N // f
    if m <= 0:
        return None, 0
    hh = h[:m * f].reshape(m, f)
    g = hh.mean(axis=1)
    return g, m


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # One cheap polish cycle on the start.
    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # NEW IDEA: shift-invariant periodic perturbation / lattice-breaking.
    # The step-function optimum has a blocky structure (many exact zeros and
    # plateaus).  The coarsen+prolongate round trip in the original program
    # only perturbs with alternating tilt.  Here we additionally run
    # coarsen+prolongate with a *random small jitter* in each cell, which
    # breaks the symmetry of the block structure and lets L-BFGS escape
    # from the local basin it is stuck in (the "coarse round-trip" was the
    # only part of the original that ever helped, so we amplify it with
    # more perturbations and accept-if-better).
    N = best.size
    rng = np.random.default_rng(12345)
    for rnd in (1, 2, 3):
        for f in (4, 8, 16, 32):
            if N // f < 4000:
                continue
            now = time.process_time()
            if now >= deadline - 1.5:
                break
            remaining = deadline - 1.5 - now
            share = max(1.0, min(remaining / 4.0, 5.0))
            g, m = _coarsen(best, f)
            if g is None or g.sum() <= 0:
                continue
            g = _rescale(g)
            gR = R_of(g)
            g, gR = run_cycle(g, gR, now + share)
            hp = np.repeat(g, f)
            if hp.size < N:
                hp = np.concatenate([hp, np.full(N - hp.size, hp[-1] if hp.size else 0.0)])
            elif hp.size > N:
                hp = hp[:N]
            # random per-cell jitter instead of alternating tilt
            jit = 1.0 + (rng.random(N) - 0.5) * 0.04
            hp = np.clip(hp * jit, 0.0, None)
            hp = _rescale(hp)
            hpR = R_of(hp)
            now2 = time.process_time()
            share2 = max(1.0, min(share, 5.0))
            hp, hpR = run_cycle(hp, hpR, now2 + share2)
            dR = hpR - bestR
            print("round %d f=%d R=%.7f dR=%.2e zeros=%.1f%% band01=%.2f%% band1=%.2f%%"
                  % (rnd, f, hpR, dR, 100.0 * np.mean(hp <= 0),
                     100.0 * _band_frac(hp, 0.001), 100.0 * _band_frac(hp, 0.01)))
            if hpR > bestR + 1e-9:
                best, bestR = hp.copy(), hpR

    while time.process_time() < deadline - 1.0:
        prev = bestR
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        if bestR - prev < 1e-10:
            break

    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.6, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = max(1, int(round(alpha * n)))
    if m >= n:
        m = n - 1
    S = np.argpartition(Lf, n - m)[n - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_deficit(h, p, thr=0.6):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    # exact tie gradient on tied-max knots
    idx = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / M
    # deficit p-norm surcharge over near-max band
    B = np.flatnonzero(Lf >= thr * M)
    # exclude tied-max knots from deficit term (they get tie gradient)
    B = np.setdiff1d(B, idx, assume_unique=False)
    if B.size > 0:
        d = (M - Lf[B]) / M
        d = np.clip(d, 0.0, None)
        dp = d ** p
        Sdp = dp.sum() + 1e-300
        # d/dLf_j of (1/p) log(sum d^p): d_j^(p-1) / (M * sum d^p)
        coef = (d ** (p - 1)) / (M * Sdp)
        gLf[B] += coef
        val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + (1.0 / p) * np.log(Sdp)
    else:
        val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=200):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, alpha, deadline, maxiter=200):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_cvar(hh, alpha),
                         deadline, maxiter=maxiter)


def _deficit_lbfgs(h0, p, thr, deadline, maxiter=200):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_deficit(hh, p, thr),
                         deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window_polish_frac(h, deadline, frac):
    n = h.size
    pad = max(3, n // frac)
    return _peak_window_polish(h, deadline, pad=pad)


def _shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    u = Lf / mx
    return (np.mean(u >= 0.999), np.mean(u >= 0.99), np.mean(u >= 0.95))


def _coarsen(h, k):
    n = h.size
    m = int(np.ceil(n / k))
    pad = m * k - n
    if pad > 0:
        hp = np.concatenate((h, np.zeros(pad)))
    else:
        hp = h
    return hp.reshape(m, k).mean(axis=1)


def _prolong(hc, k, N):
    m = hc.size
    xc = (np.arange(m) + 0.5) * k
    xn = np.arange(N) + 0.5
    hn = np.interp(xn, xc, hc, left=hc[0], right=hc[-1])
    return _rescale(hn)


def _retract(h):
    h = np.clip(h, 0, None)
    for _ in range(3):
        s = h.sum()
        if s <= 0:
            return h
        h = h / s
        Lf = _knots(h)
        mx = Lf.max()
        if mx <= 0:
            return h
        h = h / np.sqrt(mx)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # Phase A: deficit p-norm ladder, thr=0.6
    phaseA_deadline = min(deadline - 1.0, t0 + budget_seconds * 0.30)
    ps_A = (4, 8, 16, 32, 64)
    for p in ps_A:
        if time.process_time() >= phaseA_deadline - 0.5:
            break
        rung_deadline = min(phaseA_deadline,
                            time.process_time() +
                            (phaseA_deadline - time.process_time()) /
                            max(1, len(ps_A) - ps_A.index(p)))
        hc = _deficit_lbfgs(best, p, 0.6, rung_deadline, maxiter=60)
        # exact tie polish
        if time.process_time() < rung_deadline - 0.3:
            tl = min(rung_deadline, time.process_time() + 1.5)
            hp = _full_lbfgs(hc, tl, maxiter=30)
            if R_of(hp) > R_of(hc):
                hc = hp
        # peak-window polish
        if time.process_time() < rung_deadline - 0.3:
            hp = _peak_window_polish_frac(hc, rung_deadline, 8)
            if R_of(hp) > R_of(hc):
                hc = hp
        Rc = R_of(hc)
        if Rc > bestR:
            best = hc.copy()
            bestR = Rc
        s01, s1, s5 = _shares(best)
        print("A p=%d R=%.9f best=%.9f sh=%.4f/%.4f/%.4f"
              % (p, Rc, bestR, s01, s1, s5))

    # Phase B: deficit p-ladder with thr=0.4
    phaseB_deadline = min(deadline - 1.0, t0 + budget_seconds * 0.55)
    ps_B = (16, 64)
    for p in ps_B:
        if time.process_time() >= phaseB_deadline - 0.5:
            break
        rung_deadline = min(phaseB_deadline,
                            time.process_time() +
                            (phaseB_deadline - time.process_time()) /
                            max(1, len(ps_B) - ps_B.index(p)))
        hc = _deficit_lbfgs(best, p, 0.4, rung_deadline, maxiter=60)
        if time.process_time() < rung_deadline - 0.3:
            tl = min(rung_deadline, time.process_time() + 1.5)
            hp = _full_lbfgs(hc, tl, maxiter=30)
            if R_of(hp) > R_of(hc):
                hc = hp
        if time.process_time() < rung_deadline - 0.3:
            hp = _peak_window_polish_frac(hc, rung_deadline, 8)
            if R_of(hp) > R_of(hc):
                hc = hp
        Rc = R_of(hc)
        if Rc > bestR:
            best = hc.copy()
            bestR = Rc
        s01, s1, s5 = _shares(best)
        print("B p=%d R=%.9f best=%.9f sh=%.4f/%.4f/%.4f"
              % (p, Rc, bestR, s01, s1, s5))

    # Phase C: one CVaR rung alpha=0.01, then final polish
    phaseC_deadline = min(deadline - 1.0, t0 + budget_seconds * 0.75)
    if time.process_time() < phaseC_deadline - 0.5:
        hc = _cvar_lbfgs(best, 0.01, phaseC_deadline, maxiter=80)
        Rc = R_of(hc)
        if Rc > bestR:
            best = hc.copy()
            bestR = Rc
        s01, s1, s5 = _shares(best)
        print("C a=0.01 R=%.9f best=%.9f sh=%.4f/%.4f/%.4f"
              % (Rc, bestR, s01, s1, s5))

    # Final: full-array tie polish + peak-window polish with remaining time
    if time.process_time() < deadline - 1.0:
        pol_deadline = min(deadline - 0.5,
                           time.process_time() +
                           (deadline - time.process_time()) * 0.5)
        hp = _full_lbfgs(best, pol_deadline, maxiter=100)
        if R_of(hp) > bestR:
            best = hp.copy()
            bestR = R_of(hp)
    if time.process_time() < deadline - 0.5:
        hp = _peak_window_polish_frac(best, deadline, 8)
        Rp = R_of(hp)
        if Rp > bestR:
            best = hp.copy()
            bestR = Rp
        print("final polish R=%.9f" % Rp)

    # Never return below start
    if startR > bestR:
        best = h0.copy()
        bestR = startR

    s01, s1, s5 = _shares(best)
    print("final R=%.12f (start %.12f, N=%d) sh=%.4f/%.4f/%.4f"
          % (bestR, startR, best.size, s01, s1, s5))
    return {"best": best, "alternative": best.copy()}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = max(1, int(round(alpha * n)))
    if m >= n:
        m = n - 1
    S = np.argpartition(Lf, n - m)[n - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_shoulder(h, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    lo = 0.5 * mx
    hi = 0.95 * mx
    S = np.flatnonzero((Lf >= lo) & (Lf <= hi))
    if S.size > 0:
        coef = -mu / S.size * (1.0 / Lf[S] - 1.0 / mx)
        gLf[S] += coef
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    if S.size > 0:
        val += -mu * np.mean(np.log(Lf[S] / mx))
    return val, grad


def _fun_grad_cliff(h, mu, lo_f=0.2, hi_f=0.8):
    """Lift the cliff band [lo_f,hi_f]*max by -mu*mean(log L) over that band."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    lo = lo_f * mx
    hi = hi_f * mx
    S = np.flatnonzero((Lf >= lo) & (Lf <= hi))
    if S.size > 0:
        coef = -mu / S.size * (1.0 / Lf[S] - 1.0 / mx)
        gLf[S] += coef
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    if S.size > 0:
        val += -mu * np.mean(np.log(Lf[S] / mx))
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=200):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, alpha, deadline, maxiter=200):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_cvar(hh, alpha),
                         deadline, maxiter=maxiter)


def _shoulder_lbfgs(h0, mu, deadline, maxiter=200):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_shoulder(hh, mu),
                         deadline, maxiter=maxiter)


def _cliff_lbfgs(h0, mu, deadline, maxiter=25):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_cliff(hh, mu),
                         deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window_polish_frac(h, deadline, frac):
    n = h.size
    pad = max(3, n // frac)
    return _peak_window_polish(h, deadline, pad=pad)


def _shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    u = Lf / mx
    return (np.mean(u >= 0.999), np.mean(u >= 0.99), np.mean(u >= 0.95))


def _revive_and_polish(h, deadline, maxiter=40):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    R0 = R_of(h)
    active = h > 0
    if active.sum() == 0:
        return h
    mean_active = h[active].mean()
    h2 = h.copy()
    h2[~active] = 1e-3 * mean_active
    h2 = _rescale(h2)
    if time.process_time() >= deadline - 0.5:
        return h
    h3 = _full_lbfgs(h2, deadline, maxiter=maxiter)
    if R_of(h3) > R0:
        return h3
    return h


def _prolongate2(h):
    """Mass-preserving exact doubling: h2[2i]=h2[2i+1]=h[i]."""
    n = h.size
    h2 = np.empty(2 * n, dtype=float)
    h2[0::2] = h
    h2[1::2] = h
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Prolongation to 2N (mass-preserving) ----
    if time.process_time() < deadline - 2.0:
        h2 = _prolongate2(best)
        R2 = R_of(h2)
        print("prolong N=%d R=%.12f diff=%.3e" % (h2.size, R2, abs(R2 - bestR)))
        # Accept lifted grid as working state only if R preserved
        if R2 >= bestR - 1e-9:
            best = h2
            bestR = R2
        N = best.size
    else:
        N = best.size

    def _report(tag, h, R):
        s01, s1, s5 = _shares(h)
        live = int(np.sum(h > 0))
        print("%s R=%.9f best=%.9f sh=%.4f/%.4f/%.4f live=%d/%d"
              % (tag, R, bestR, s01, s1, s5, live, h.size))

    # ---- Lifted ladder: CVaR rungs + tie polish + revival ----
    alphas = (0.08, 0.05, 0.03, 0.02, 0.012, 0.007, 0.004, 0.002)
    c_end = min(deadline - 1.0, t0 + budget_seconds * 0.72)
    stage_time = max(1.0, (c_end - time.process_time()) / len(alphas))
    for si, alpha in enumerate(alphas):
        if time.process_time() >= c_end - 0.5:
            break
        stage_deadline = min(c_end, time.process_time() + stage_time)
        hc = _cvar_lbfgs(best, alpha, stage_deadline, maxiter=80)
        if time.process_time() < stage_deadline:
            pol_deadline = min(stage_deadline, time.process_time() + stage_time * 0.4)
            hp = _full_lbfgs(hc, pol_deadline, maxiter=30)
            if R_of(hp) > R_of(hc):
                hc = hp
        Rc = R_of(hc)
        if Rc > bestR:
            best = hc.copy()
            bestR = Rc
        if alpha <= 0.02 and time.process_time() < c_end - 1.0:
            rev_deadline = min(c_end, time.process_time() + stage_time * 0.8)
            hr = _revive_and_polish(best, rev_deadline, maxiter=40)
            Rr = R_of(hr)
            if Rr > bestR:
                best = hr.copy()
                bestR = Rr
        _report("C a=%.3f" % alpha, best, Rc)

        # Cliff-lift pass after rung 4 (index 3, alpha=0.02)
        if si == 3 and time.process_time() < c_end - 1.0:
            for mu in (0.05, 0.2):
                if time.process_time() >= c_end - 0.5:
                    break
                cl_deadline = min(c_end, time.process_time() + stage_time * 0.6)
                hcl = _cliff_lbfgs(best, mu, cl_deadline, maxiter=25)
                if time.process_time() < cl_deadline:
                    hp = _full_lbfgs(hcl, cl_deadline, maxiter=30)
                    if R_of(hp) > R_of(hcl):
                        hcl = hp
                Rcl = R_of(hcl)
                if Rcl > bestR:
                    best = hcl.copy()
                    bestR = Rcl
                _report("cliff mu=%.2f" % mu, best, Rcl)

    # ---- Shoulder anneal (kept from base, shortened) ----
    mus = (0.05, 0.15, 0.3)
    d_end = min(deadline - 1.0, t0 + budget_seconds * 0.86)
    mu_time = max(1.0, (d_end - time.process_time()) / len(mus))
    for mu in mus:
        if time.process_time() >= d_end - 0.5:
            break
        mu_deadline = min(d_end, time.process_time() + mu_time)
        hs = _shoulder_lbfgs(best, mu, mu_deadline, maxiter=25)
        if time.process_time() < mu_deadline:
            hp = _full_lbfgs(hs, mu_deadline, maxiter=40)
            if R_of(hp) > R_of(hs):
                hs = hp
        Rs = R_of(hs)
        if Rs > bestR:
            best = hs.copy()
            bestR = Rs
        _report("D mu=%.2f" % mu, best, Rs)

    # ---- Final: full tie polish then peak-window polish ----
    if time.process_time() < deadline - 1.0:
        pol_deadline = min(deadline - 0.5,
                           time.process_time() + (deadline - time.process_time()) * 0.5)
        hp = _full_lbfgs(best, pol_deadline, maxiter=100)
        if R_of(hp) > bestR:
            best = hp.copy()
            bestR = R_of(hp)
    if time.process_time() < deadline - 0.5:
        hp = _peak_window_polish_frac(best, deadline, 8)
        Rp = R_of(hp)
        if Rp > bestR:
            best = hp.copy()
            bestR = Rp
        print("final polish R=%.9f" % Rp)

    # Never return below start
    if R_of(best) < startR:
        best = h0.copy()
        bestR = startR

    s01, s1, s5 = _shares(best)
    print("final R=%.12f (start %.12f, N=%d) sh=%.4f/%.4f/%.4f"
          % (bestR, startR, best.size, s01, s1, s5))
    return {"best": best, "alternative": best.copy()}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    m = L.max()
    if m <= 0:
        return -1.0
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    return float(num / (s * s * m))


def _num_and_dq(L):
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(L)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return num, dq


def _backprop(gLf, h):
    n = h.size
    gL = gLf[1:-1]
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    L = _knots(h)
    num, dq = _num_and_dq(L)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    M = L.max()
    gL = -dq / num
    idx = np.flatnonzero(L >= M * (1.0 - 1e-10))
    gL[idx] += 1.0 / (idx.size * M)
    gh = _backprop(gL, h) + 2.0 / s
    return -np.log(num) + 2.0 * np.log(s) + np.log(M), gh


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    L = _knots(h)
    num, dq = _num_and_dq(L)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    m = max(1, int(round(alpha * L.size)))
    if m >= L.size:
        S = np.arange(L.size)
    else:
        S = np.argpartition(L, L.size - m)[L.size - m:]
    cm = L[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gL = -dq / num
    gL[S] += 1.0 / (m * cm)
    gh = _backprop(gL, h) + 2.0 / s
    return -np.log(num) + 2.0 * np.log(s) + np.log(cm), gh


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, fun_grad, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -40.0, 40.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, fun_grad, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def _peak_window(h, frac=0.15):
    L = _knots(h)
    m = int(np.argmax(L))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    def time_left():
        return time.process_time() < deadline - 0.5

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = np.clip(s, 0, None)
            bestR = _R_of(best)

    if best is None:
        best = np.ones(64)
        bestR = _R_of(best)

    base = best.copy()
    baseR = bestR

    def try_accept(c):
        nonlocal best, bestR
        if c is None:
            return False
        rc = _R_of(c)
        if rc > bestR:
            bestR = rc
            best = c.copy()
            return True
        return False

    # Main line: refine best with log-LBFGS (tie-aware), CVaR smoothing,
    # and peak-window block polish. Alternate these until budget is used.
    N = max(best.size, 8001)
    h = _prolongate(best, N)
    if _R_of(h) < bestR:
        h = best.copy()
    else:
        try_accept(h)

    # Phase 1: full optimization at working resolution
    if time_left():
        c = _lbfgs_log(h, _fun_grad_tie, 2000, deadline)
        if _R_of(c) > _R_of(h):
            h = c
        try_accept(h)

    # CVaR-smoothing rounds pull up the near-max plateau
    for alpha in (0.05, 0.02, 0.008, 0.003):
        if not time_left():
            break
        c = _lbfgs_log(h, lambda hh, a=alpha: _fun_grad_cvar(hh, a),
                       400, deadline)
        if _R_of(c) > _R_of(h):
            h = c
        try_accept(h)
        if time_left():
            c = _lbfgs_log(h, _fun_grad_tie, 500, deadline)
            if _R_of(c) > _R_of(h):
                h = c
            try_accept(h)

    # Phase 2: alternate peak-window block polish and full polish
    fracs = (0.08, 0.12, 0.20, 0.30)
    fi = 0
    while time_left():
        c = _lbfgs_log(best, _fun_grad_tie, 600, deadline)
        try_accept(c)
        if not time_left():
            break
        f = fracs[fi % len(fracs)]
        fi += 1
        win = _peak_window(best, f)
        c = _lbfgs_block(best, win, _fun_grad_tie, 400, deadline)
        try_accept(c)
        if not time_left():
            break
        alpha = (0.02, 0.008, 0.003)[fi % 3]
        c = _lbfgs_log(best, lambda hh, a=alpha: _fun_grad_cvar(hh, a),
                       300, deadline)
        try_accept(c)

    # Phase 3: if time remains, upsample best and re-polish at finer grid
    if time_left() and best.size < 32000:
        N2 = min(32000, max(16000, best.size * 2))
        h2 = _prolongate(best, N2)
        if time_left():
            c = _lbfgs_log(h2, _fun_grad_tie, 800, deadline)
            if _R_of(c) > _R_of(h2):
                h2 = c
        for alpha in (0.02, 0.008, 0.003):
            if not time_left():
                break
            c = _lbfgs_log(h2, lambda hh, a=alpha: _fun_grad_cvar(hh, a),
                           300, deadline)
            if _R_of(c) > _R_of(h2):
                h2 = c
        if time_left():
            c = _lbfgs_log(h2, _fun_grad_tie, 500, deadline)
            if _R_of(c) > _R_of(h2):
                h2 = c
        if _R_of(h2) > bestR:
            best = h2
            bestR = _R_of(h2)

    # Final short polish
    while time_left():
        c = _lbfgs_log(best, _fun_grad_tie, 300, deadline)
        if not try_accept(c):
            break

    # Return an alternative if it's distinct from best and beats base
    alt = None
    if baseR > 0 and bestR > baseR + 1e-9:
        if not np.array_equal(base, best):
            alt = base

    if alt is not None and _R_of(alt) > 0 and not np.array_equal(alt, best):
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---- NEW: sharp-level (staircase) parameterization ----
def _build_sharp(u, b, N):
    M = u.size
    a = np.exp(np.clip(u, -40.0, 40.0))
    bounds = np.clip(np.asarray(b, dtype=int), 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] < bounds[j - 1] + 1:
            bounds[j] = bounds[j - 1] + 1
    h = np.empty(N)
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        h[prev:bb] = a[j]
        prev = bb
    h[prev:] = a[M - 1]
    return h


def _sharp_fun_grad(u, b, N, beta):
    h = _build_sharp(u, b, N)
    if beta > 0:
        val, gh = _fun_grad_beta(h, beta)
    else:
        val, gh = _fun_grad(h)
    # gradient wrt levels: sum of gh over each block
    M = u.size
    a = np.exp(np.clip(u, -40.0, 40.0))
    bounds = np.clip(np.asarray(b, dtype=int), 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] < bounds[j - 1] + 1:
            bounds[j] = bounds[j - 1] + 1
    gu = np.empty(M)
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        gu[j] = np.sum(gh[prev:bb]) * a[j]
        prev = bb
    gu[M - 1] = np.sum(gh[prev:]) * a[M - 1]
    return val, gu, h


def _optimize_sharp(h0, N, n_levels, deadline, beta=1e7, maxiter=200):
    """Build a staircase approximation of h0 with n_levels, then refine levels."""
    if time.process_time() >= deadline - 0.5:
        return h0
    # initialize levels by binning h0 into n_levels equal blocks
    M = n_levels
    edges = np.linspace(0, N, M + 1).astype(int)
    edges[0] = 0; edges[-1] = N
    a0 = np.array([h0[edges[j]:edges[j + 1]].mean() if edges[j + 1] > edges[j]
                   else 1e-6 for j in range(M)])
    a0 = np.maximum(a0, 1e-9)
    u0 = np.log(a0)
    b0 = edges[1:-1].copy()

    def f(x):
        u = x[:M]
        b = x[M:]
        val, gu, _ = _sharp_fun_grad(u, b, N, beta)
        # gradient wrt bounds: a[j] vs a[j+1] difference at boundary
        gb = np.zeros(M - 1)
        a = np.exp(np.clip(u, -40.0, 40.0))
        for j in range(M - 1):
            gb[j] = 0.0  # integer, no smooth gradient; ignored
        return val, np.concatenate([gu, gb])

    # Only optimize levels (bounds fixed) - much easier
    def f_levels(u):
        val, gu, _ = _sharp_fun_grad(u, b0, N, beta)
        return val, gu

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f_levels, u0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h = _build_sharp(res.x, b0, N)
    return _rescale(h)


def _sharpen_from(h, deadline, levels_list=(200, 500, 1000, 2000)):
    """Convert h to staircase at increasing resolution; refine each."""
    best = h
    bestR = R_of(h)
    N = h.size
    for M in levels_list:
        if time.process_time() >= deadline - 0.5:
            break
        if M > N:
            break
        ht = _optimize_sharp(best, N, M, deadline - 0.3, beta=1e7, maxiter=120)
        ht = _peak_ladder(ht, deadline - 0.2, pads=(0.05, 0.03), iters=120)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
    return best


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    amax0 = _argmax_frac(best)

    # ---- Phase S (NEW): staircase sharpening ----
    s_deadline = t0 + budget_seconds * 0.40
    hs = _sharpen_from(best, s_deadline, levels_list=(150, 400, 900, 2000))
    offer(hs, 'S-sharp')

    # ---- Phase A: peak-window beta ladder ----
    a_deadline = t0 + budget_seconds * 0.55
    for pad in (0.06, 0.04, 0.025):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3, beta=1e7)
        offer(ht, 'A-beta pad=%.3f' % pad)

    # ---- Phase S2: sharpen again from improved point ----
    s2_deadline = t0 + budget_seconds * 0.75
    hs = _sharpen_from(best, s2_deadline, levels_list=(400, 1000, 2500))
    offer(hs, 'S2-sharp')

    # ---- Final polish ----
    final_deadline = t0 + budget_seconds * 0.97
    ht = _lbfgs_block(best, np.arange(best.size), 400,
                      final_deadline - 0.5, beta=1e8)
    offer(ht, 'final-beta1e8')
    ht = _lbfgs_block(best, np.arange(best.size), 400,
                      final_deadline - 0.3, beta=0.0)
    offer(ht, 'final-plain')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, alpha, deadline, maxiter=120):
    fg = _fun_grad_tie if alpha <= 0 else (lambda h: _fun_grad_cvar(h, alpha))
    return _lbfgs_custom(h0, fg, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _top_shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (float(np.mean(L >= mx * 0.999)),
            float(np.mean(L >= mx * 0.99)),
            float(np.mean(L >= mx * 0.95)))


_CVAR_LADDER = [0.03, 0.01, 0.003]


def _cvar_ladder(h, deadline, maxiter=120, per_stage_cap=2.5):
    cur = h
    curR = R_of(cur)
    for alpha in _CVAR_LADDER:
        now = time.process_time()
        if now >= deadline - 1.0:
            break
        tlim = min(now + per_stage_cap, deadline - 0.8)
        hc = _cvar_lbfgs(cur, alpha, tlim, maxiter=maxiter)
        now = time.process_time()
        if now < deadline - 0.5:
            hc2 = _full_lbfgs(hc, min(now + 1.5, deadline - 0.4), maxiter=60)
        else:
            hc2 = hc
        rc = R_of(hc2)
        if rc >= curR:
            cur = hc2
            curR = rc
        else:
            rc2 = R_of(hc)
            if rc2 > curR:
                cur = hc
                curR = rc2
    return cur, curR


def _support_revive(h, deadline, frac=0.0075, eps_scale=0.01):
    """Zero cells with positive exact-R directional derivative -> epsilon."""
    if time.process_time() >= deadline - 0.5:
        return h
    val, gh = _fun_grad_tie(h)
    hmax = h.max()
    if hmax <= 0:
        return h
    thr = 1e-12 * hmax
    zero = h < thr
    cand = zero & (gh > 0)
    if not np.any(cand):
        return h
    idx = np.flatnonzero(cand)
    # prioritise near active support
    active = np.flatnonzero(h >= thr)
    if active.size > 0:
        # distance to nearest active cell (approx via searchsorted on sorted active)
        pos = np.searchsorted(active, idx)
        left = np.clip(pos - 1, 0, active.size - 1)
        right = np.clip(pos, 0, active.size - 1)
        d = np.minimum(np.abs(idx - active[left]), np.abs(idx - active[right]))
    else:
        d = np.zeros(idx.size)
    # score: prefer near support, then larger gh
    score = gh[idx] / (1.0 + d)
    k = max(1, int(frac * idx.size))
    if k > idx.size:
        k = idx.size
    sel = idx[np.argpartition(-score, k - 1)[:k]]
    mean_active = h[active].mean() if active.size > 0 else hmax
    eps = eps_scale * mean_active
    gsel = gh[sel]
    gmax = gsel.max()
    if gmax <= 0:
        return h
    h2 = h.copy()
    h2[sel] = eps * (gsel / gmax)
    return _rescale(h2)


def _edge_expand(h, deadline, eps_scale=0.01):
    """Small symmetric support expansion at outer active edges."""
    if time.process_time() >= deadline - 0.5:
        return h
    hmax = h.max()
    if hmax <= 0:
        return h
    thr = 1e-12 * hmax
    active = np.flatnonzero(h >= thr)
    if active.size == 0:
        return h
    lo = active[0]
    hi = active[-1]
    mean_active = h[active].mean()
    eps = eps_scale * mean_active
    h2 = h.copy()
    n = h.size
    changed = False
    for j in range(1, 4):
        if lo - j >= 0 and h2[lo - j] < thr:
            h2[lo - j] = eps / j
            changed = True
        if hi + j < n and h2[hi + j] < thr:
            h2[hi + j] = eps / j
            changed = True
    if not changed:
        return h
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    N = best.size
    s01, s1, s5 = _top_shares(best)
    print("base R=%.9f (N=%d) zero=%.3f%% 1%%=%.4f%%" %
          (bestR, N, 100 * np.mean(best < 1e-12 * max(best.max(), 1e-30)), 100 * s1))

    alt = None
    altR = -1.0

    def _chunk(frac, cap=None):
        now = time.process_time()
        rem = deadline - now
        if rem <= 0.5:
            return None
        t = now + max(0.3, rem * frac)
        if cap is not None:
            t = min(t, now + cap)
        return min(t, deadline - 0.5)

    def _polish(hc, tlim):
        if tlim is None or time.process_time() >= tlim - 0.3:
            return hc
        hc = _full_lbfgs(hc, tlim, maxiter=200)
        if time.process_time() < tlim - 0.2:
            hc = _peak_window_polish(hc, tlim, pad=3, frac=8)
        return hc

    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        # (1) short CVaR ladder
        hc = best
        if time.process_time() < deadline - 3.0:
            hc, rc = _cvar_ladder(best, min(deadline - 2.0, time.process_time() + 8.0),
                                  maxiter=100, per_stage_cap=2.0)
            print("cyc%d cvar R=%.9f (best %.9f)" % (cycle, rc, bestR))
            if rc > bestR:
                best = hc
                bestR = rc
            elif alt is None or rc > altR:
                alt = hc
                altR = rc

        # (2) support revival
        if time.process_time() < deadline - 2.0:
            hr = _support_revive(best, deadline - 1.0, frac=0.0075, eps_scale=0.01)
            tlim = _chunk(0.15, cap=3.0)
            hr = _polish(hr, tlim)
            rr = R_of(hr)
            zf = 100 * np.mean(hr < 1e-12 * max(hr.max(), 1e-30))
            _, r1, _ = _top_shares(hr)
            print("cyc%d revive R=%.9f zero=%.3f%% 1%%=%.4f%% (best %.9f)" %
                  (cycle, rr, zf, 100 * r1, bestR))
            if rr > bestR:
                best = hr
                bestR = rr
                print("ACCEPT revive: %.9f" % rr)
            elif alt is None or rr > altR:
                alt = hr
                altR = rr

        # (3) edge expansion once per cycle
        if time.process_time() < deadline - 2.0:
            he = _edge_expand(best, deadline - 1.0, eps_scale=0.01)
            tlim = _chunk(0.12, cap=2.5)
            he = _polish(he, tlim)
            re = R_of(he)
            print("cyc%d edge R=%.9f (best %.9f)" % (cycle, re, bestR))
            if re > bestR:
                best = he
                bestR = re
                print("ACCEPT edge: %.9f" % re)
            elif alt is None or re > altR:
                alt = he
                altR = re

        # (4) extra full polish
        if time.process_time() < deadline - 1.5:
            tlim = _chunk(0.2, cap=4.0)
            hp = _polish(best, tlim)
            rp = R_of(hp)
            print("cyc%d polish R=%.9f (best %.9f)" % (cycle, rp, bestR))
            if rp > bestR:
                best = hp
                bestR = rp
            elif alt is None or rp > altR:
                alt = hp
                altR = rp

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    s01, s1, s5 = _top_shares(best)
    zf = 100 * np.mean(best < 1e-12 * max(best.max(), 1e-30))
    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    print("final zero=%.3f%% 1%%=%.4f%% 5%%=%.4f%%" % (zf, 100 * s1, 100 * s5))

    if alt is not None and altR > 0 and alt is not best:
        return {"best": best, "alternative": alt}
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0

    def f(x):
        return fg(np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _band_window(h, thr_frac=0.9, pad_frac=0.5, extra=512):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= thr_frac * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _ladder(best, bestR, deadline):
    """CVaR ladder: smooth max-approx then push the top band up to raise
    ||f*f||_2^2 relative to ||f*f||_inf (flattening the plateau)."""
    sched = [0.4, 0.2, 0.1, 0.05, 0.02, 0.01, 0.005]
    for alpha in sched:
        if time.process_time() >= deadline - 0.5:
            break
        fg = (lambda a: (lambda hh: _fun_grad_cvar(hh, a)))(alpha)
        ht = _lbfgs_all(best, 300, deadline - 0.3, fg)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _polish(best, bestR, deadline, fg, iters=400):
    if time.process_time() >= deadline - 0.5:
        return best, bestR
    ht = _lbfgs_all(best, iters, deadline - 0.3, fg)
    r = R_of(ht)
    if r > bestR + 1e-13:
        best, bestR = ht.copy(), r
    return best, bestR


def _band_polish(best, bestR, deadline, fg, iters=250):
    if time.process_time() >= deadline - 0.5:
        return best, bestR
    win = _band_window(best, thr_frac=0.95, pad_frac=0.6, extra=256)
    ht = _lbfgs_block(best, win, iters, deadline - 0.3, fg)
    r = R_of(ht)
    if r > bestR + 1e-13:
        best, bestR = ht.copy(), r
    return best, bestR


def _move_jitter(best, rng):
    n = best.size
    w = max(1, min(n, int(rng.uniform(0.01, 0.08) * n)))
    lo = int(rng.integers(0, n - w + 1))
    win = np.arange(lo, lo + w)
    h = best.copy()
    h[win] = h[win] * np.exp(0.02 * rng.standard_normal(w))
    return h, win


def _halo(touched, n, halo=64):
    if touched is None or touched.size == 0:
        return np.arange(n)
    lo = max(0, int(touched.min()) - halo)
    hi = min(n - 1, int(touched.max()) + halo)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240608)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = np.sqrt(i + 1.0) - np.sqrt(i)
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: CVaR ladder to flatten the plateau.
    if time.process_time() < deadline - 2.0:
        best, bestR = _ladder(best, bestR, deadline - 1.5)
        print("cvar-ladder R=%.7f band1=%.2f%%" %
              (bestR, 100.0 * _band_frac(best, 0.01)))

    # Phase B: band polish with tie objective.
    if time.process_time() < deadline - 1.5:
        best, bestR = _band_polish(best, bestR, deadline - 1.5, _fun_grad)
        print("band-polish R=%.7f" % bestR)

    # Phase C: local jitter hops.
    hop = 0; acc = 0
    while time.process_time() < deadline - 1.5:
        hop += 1
        h_try, touched = _move_jitter(best, rng)
        h_try = np.clip(h_try, 0, None)
        if h_try.sum() <= 0:
            continue
        free = _halo(touched, h_try.size, 48)
        ht = _lbfgs_block(h_try, free, 120, deadline - 1.0, _fun_grad)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
            acc += 1
        if hop % 25 == 0:
            print("hop %d acc %d bestR=%.7f" % (hop, acc, bestR))

    print("hops done: %d accepted %d bestR=%.7f" % (hop, acc, bestR))

    # Phase D: final CVaR + plain polish.
    if time.process_time() < deadline - 1.0:
        best, bestR = _ladder(best, bestR, deadline - 1.0)
        print("final cvar-ladder R=%.7f" % bestR)
    if time.process_time() < deadline - 0.6:
        ht = _lbfgs_all(best, 400, deadline - 0.4, _fun_grad)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _top_shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (float(np.mean(L >= mx * 0.999)),
            float(np.mean(L >= mx * 0.99)),
            float(np.mean(L >= mx * 0.95)))


def _prolong2x(h):
    return np.repeat(h, 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    cur = best.copy()
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))
    s01, s1, s5 = _top_shares(best)
    print("base shares 0.1%%=%.4f%% 1%%=%.4f%% 5%%=%.4f%%" % (100*s01, 100*s1, 100*s5))

    alt = None
    altR = -1.0

    def _accept(hc, tag):
        nonlocal best, bestR, cur, alt, altR
        rc = R_of(hc)
        if rc > bestR:
            best = hc.copy()
            bestR = rc
            cur = hc.copy()
            print("ACCEPT %s R=%.9f" % (tag, rc))
            return True
        else:
            print("reject %s R=%.9f (best %.9f)" % (tag, rc, bestR))
            if alt is None or rc > altR:
                alt = hc.copy()
                altR = rc
            cur = best.copy()
            return False

    # ---- Wide-band CVaR ladder ----
    ladder = [0.35, 0.25, 0.15, 0.08, 0.04, 0.02]
    for alpha in ladder:
        now = time.process_time()
        if now >= deadline - 8.0:
            break
        tlim = min(now + 4.0, deadline - 8.0)
        fg = (lambda x, a=alpha: _fun_grad_cvar(x, a))
        h_c = _lbfgs_custom(cur, fg, tlim, maxiter=150)
        now = time.process_time()
        if now < deadline - 6.0:
            h_s = _full_lbfgs(h_c, min(now + 2.0, deadline - 6.0), maxiter=60)
        else:
            h_s = h_c
        accepted = _accept(h_s, "cvar a=%.2f" % alpha)
        # peak polish on selected rungs
        if alpha in (0.15, 0.04) and accepted:
            now = time.process_time()
            if now < deadline - 5.0:
                hp = _peak_window_polish(best, min(now + 2.0, deadline - 5.0),
                                         pad=3, frac=8)
                _accept(hp, "peak a=%.2f" % alpha)

    # ---- 2x prolongation pass ----
    if time.process_time() < deadline - 12.0:
        hf = _prolong2x(best)
        hf = _rescale(hf)
        now = time.process_time()
        hf = _full_lbfgs(hf, min(now + 6.0, deadline - 6.0), maxiter=150)
        now = time.process_time()
        if now < deadline - 4.0:
            fg = (lambda x: _fun_grad_cvar(x, 0.02))
            hf = _lbfgs_custom(hf, fg, min(now + 3.0, deadline - 4.0), maxiter=100)
        now = time.process_time()
        if now < deadline - 2.0:
            hf = _peak_window_polish(hf, min(now + 2.0, deadline - 2.0),
                                     pad=3, frac=8)
        _accept(hf, "prolong2x")

    # ---- remaining: alternate full polish and wide CVaR ----
    while time.process_time() < deadline - 1.5:
        now = time.process_time()
        tlim = min(now + 4.0, deadline - 1.0)
        hc = _full_lbfgs(best, tlim, maxiter=120)
        rc = R_of(hc)
        if rc > bestR:
            best = hc.copy(); bestR = rc; cur = hc.copy()
            print("fill R=%.9f" % rc)
        else:
            if alt is None or rc > altR:
                alt = hc.copy(); altR = rc
            now = time.process_time()
            if now < deadline - 3.0:
                fg = (lambda x: _fun_grad_cvar(x, 0.08))
                hc2 = _lbfgs_custom(best, fg, min(now + 2.0, deadline - 2.0), maxiter=80)
                _accept(hc2, "fill-cvar")
            else:
                break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    s01, s1, s5 = _top_shares(best)
    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    print("final shares 0.1%%=%.4f%% 1%%=%.4f%% 5%%=%.4f%%" % (100*s01, 100*s1, 100*s5))

    if alt is not None and altR > 0 and alt is not best:
        return {"best": best, "alternative": alt}
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, h.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _refine(h, maxiter, deadline, beta=0.0, tie=True):
    """A single L-BFGS stage returning the improved array (no accept logic)."""
    if time.process_time() >= deadline - 0.3:
        return h
    return _lbfgs_all_pos(h, maxiter, deadline, beta=beta, tie=tie)


def _flat_plateau_escape(h, deadline, tries=4):
    """Try shrinking the plateau slightly (compress the peak region) then re-polish.
    Aimed at sharpening the tied maximum to a corner where the derivative is
    balanced from both sides -- a known structure for near-optimal profiles."""
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    best = h
    bestR = R_of(h)
    n = h.size
    for k in range(tries):
        if time.process_time() >= deadline - 0.8:
            break
        # find near-peak support
        Lf = _knots(h)
        mx = Lf.max()
        idx = np.flatnonzero(Lf >= 0.9999 * mx)
        if idx.size == 0:
            continue
        lo = max(0, idx.min() - 2)
        hi = min(n - 1, idx.max() + 1)
        # apply a tiny local smoothing / reshaping near the peak
        cand = h.copy()
        seg = np.arange(lo, hi + 1)
        if seg.size < 4:
            continue
        # blend toward a flatter top with a small perturbation
        amp = 1e-3 * (1 + k)
        cand[seg] = cand[seg] * (1.0 + amp * np.sin(np.linspace(0, 2 * np.pi, seg.size)))
        cand = _rescale(np.clip(cand, 0, None))
        cand = _refine(cand, 200, deadline, beta=0.0, tie=True)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    def try_stage(seed, seedR, maxiter, beta, tie, label):
        nonlocal best, bestR
        if time.process_time() >= deadline - 0.5:
            return seed, seedR
        h = _lbfgs_all_pos(seed, maxiter, deadline, beta=beta, tie=tie)
        r = R_of(h)
        print("%s beta=%g R=%.9f best=%.9f" % (label, beta, r, bestR))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("  ACCEPT %s beta=%g -> best=%.9f" % (label, beta, bestR))
        if r >= seedR - 1e-15:
            return h, r
        return seed, seedR

    # Phase A: band ladder from start
    seed, seedR = best.copy(), bestR
    for beta in (8.0, 32.0, 128.0, 512.0, 2048.0):
        if time.process_time() >= deadline - 0.5:
            break
        seed, seedR = try_stage(seed, seedR, 250, beta, False, "A")
        seed, seedR = try_stage(seed, seedR, 120, 1e6, False, "A")
        seed, seedR = try_stage(seed, seedR, 150, 0.0, True, "A")

    # Phase B: retighten with peak-window tie polishes
    for pad in (0.08, 0.04, 0.02):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 200,
                          min(deadline - 0.3,
                              time.process_time() + 4.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("B pad=%.3f R=%.9f best=%.9f" % (pad, r, bestR))

    # Phase C: spend the rest with mixed strategies
    while time.process_time() < deadline - 1.0:
        seed, seedR = best.copy(), bestR
        for beta in (4.0, 16.0, 64.0):
            if time.process_time() >= deadline - 0.5:
                break
            seed, seedR = try_stage(seed, seedR, 400, beta, False, "C")
        if time.process_time() >= deadline - 0.5:
            break
        seed, seedR = try_stage(seed, seedR, 300, 0.0, True, "C")
        # plateau escape: try to sharpen the top and re-polish
        if time.process_time() < deadline - 3.0:
            cand, r = _flat_plateau_escape(best, deadline, tries=2)
            if r > bestR + 1e-15:
                best, bestR = cand, r
                print("  ESCAPE -> best=%.9f" % bestR)
        if seedR <= bestR + 1e-15 and time.process_time() >= deadline - 2.0:
            break

    best = _rescale(best)
    bestR = R_of(best)
    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _riemann_lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = _rescale(np.clip(h0, 0, None))
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        if hh.sum() <= 0:
            return 1e18, np.zeros(n)
        val, g = _fun_grad_tie(hh)
        denom = float(np.dot(hh, hh))
        if denom > 0:
            g = g - (float(np.dot(g, hh)) / denom) * hh
        return val, g

    cb = _make_cb(deadline - 0.15)
    x0 = h.copy()
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0, None))


def _prolongate(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N) / N
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(n + 1, dtype=float))
    hh = np.clip(np.diff(out), 0, None)
    if hh.sum() <= 0:
        return np.ones(N) / N
    return hh


def _peak_window(h, pad=0.03):
    L = _knots(h)
    mx = L.max()
    idx = np.flatnonzero(L >= mx * 0.9)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx[0] - 1)
    hi = min(h.size, idx[-1])
    span = hi - lo
    lo = max(0, lo - int(span * pad))
    hi = min(h.size, hi + int(span * pad))
    return np.arange(lo, hi)


def _cvar_polish(h, slice_end):
    """Use CVaR-type smoothing at multiple alphas to escape tie-plateaus."""
    best = h
    bestR = R_of(h)
    alphas = [0.001, 0.005, 0.02, 0.05]
    for a in alphas:
        if time.process_time() >= slice_end - 0.3:
            break
        tlim = min(slice_end, time.process_time() + 1.2)
        hc = _lbfgs_custom(best, lambda hh, a=a: _fun_grad_cvar(hh, a),
                           tlim, maxiter=120)
        rc = R_of(hc)
        if rc > bestR:
            best, bestR = hc, rc
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 3281
        i = np.arange(N, dtype=float)
        u = (i + 0.5) / N
        v = (N - i - 0.5) / N
        best = _rescale(np.minimum(0.1 + 0.5 * (u ** -0.5 + v ** -0.5), 8.0))
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    gbest = best.copy()
    gbestR = bestR
    gbestN = best.size
    seed = best.copy()

    # Phase 1: multi-resolution scan around start's N
    N0 = best.size
    N_list = sorted(set([max(64, int(N0 * f)) for f in
                         (0.55, 0.7, 0.85, 1.0, 1.2, 1.5, 2.0, 2.6)]))

    for N in N_list:
        if time.process_time() >= deadline - 6.0:
            break
        hN = _rescale(_prolongate(seed, N))
        preR = R_of(hN)
        now = time.process_time()
        r_end = min(now + 2.5, deadline - 5.0)
        hr = _riemann_lbfgs(hN, 300, r_end)
        rR = R_of(hr)
        now = time.process_time()
        p_end = min(now + 1.5, deadline - 3.5)
        hp = _lbfgs_block(hr, np.arange(hr.size), 200, p_end)
        pR = R_of(hp)
        cand, candR = hp, pR
        if candR > gbestR + 1e-15:
            gbestR, gbest, gbestN = candR, cand.copy(), N
            print("  NEW N=%d R=%.9f" % (N, gbestR))
        print("N=%d pre=%.9f riem=%.9f final=%.9f" % (N, preR, rR, candR))

    # Phase 2: alternate polish on global best with three modes
    round_n = 0
    while time.process_time() < deadline - 1.0:
        round_n += 1
        now = time.process_time()
        slice_end = min(now + 4.0, deadline - 0.5)
        if slice_end - now < 0.5:
            break
        improved = False

        # mode A: full-array tie
        hA = _lbfgs_block(gbest, np.arange(gbest.size), 250, slice_end)
        rA = R_of(hA)
        if rA > gbestR + 1e-15:
            gbest, gbestR = hA, rA
            improved = True

        # mode B: peak-window tie
        if time.process_time() < slice_end - 0.3:
            win = _peak_window(gbest)
            if 0 < win.size < gbest.size:
                tlim = min(slice_end, time.process_time() + 1.5)
                hB = _lbfgs_block(gbest, win, 200, tlim)
                rB = R_of(hB)
                if rB > gbestR + 1e-15:
                    gbest, gbestR = hB, rB
                    improved = True

        # mode C: CVaR escape then tie polish
        if time.process_time() < slice_end - 0.5:
            tlim = min(slice_end, time.process_time() + 2.0)
            hC, rC = _cvar_polish(gbest, tlim)
            if rC > gbestR + 1e-15:
                hC = _lbfgs_block(hC, np.arange(hC.size), 150, slice_end)
                rC = R_of(hC)
                if rC > gbestR + 1e-15:
                    gbest, gbestR = hC, rC
                    improved = True

        if improved:
            print("  POLISH R=%.9f (N=%d)" % (gbestR, gbest.size))
        elif round_n > 2:
            # gentle Riemannian kick to escape local optimum
            if time.process_time() < slice_end - 0.5:
                tlim = min(slice_end, time.process_time() + 1.5)
                zh = _rescale(gbest * (1.0 + 0.02 * np.random.randn(gbest.size)))
                hk = _riemann_lbfgs(zh, 150, tlim)
                rk = R_of(hk)
                if rk > gbestR + 1e-15:
                    gbest, gbestR = hk, rk
                    print("  KICK R=%.9f" % gbestR)

    if gbestR < startR and start is not None:
        gbest = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        gbestR = startR

    print("final R=%.12f (start %.12f, best N=%d)" % (gbestR, startR, gbest.size))

    result = {"best": gbest}
    if gbestR <= startR + 1e-14 and start is not None:
        result["alternative"] = gbest
    return result

