def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _lift_noncomm(h, num, den):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N == 0 or h.sum() <= 0:
        return h.copy()
    M = int(np.ceil(N * num / den))
    if M < 1:
        M = 1
    cs = np.concatenate(([0.0], np.cumsum(h)))
    cs /= cs[-1]
    pos = np.arange(M + 1, dtype=float) * (den / num)
    pos = np.clip(pos, 0.0, N)
    vals = np.interp(pos, np.arange(N + 1, dtype=float), cs)
    hp = np.diff(vals)
    hp = np.clip(hp, 0, None)
    s = hp.sum()
    if s > 0:
        hp = hp / s * h.sum()
    return hp


def _map_back(hp, N):
    hp = np.clip(np.asarray(hp, dtype=float), 0, None)
    M = hp.size
    if M == 0:
        return np.zeros(N)
    cs = np.concatenate(([0.0], np.cumsum(hp)))
    if cs[-1] <= 0:
        return np.zeros(N)
    cs /= cs[-1]
    pos = np.arange(N + 1, dtype=float) * (M / N)
    pos = np.clip(pos, 0.0, M)
    vals = np.interp(pos, np.arange(M + 1, dtype=float), cs)
    h = np.diff(vals)
    h = np.clip(h, 0, None)
    s = h.sum()
    if s > 0:
        h = h / s * hp.sum()
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N0 = best.size
    print("base R=%.12f (N=%d)" % (bestR, N0))

    alt_best = None
    altR = -1.0

    def try_update(hcand, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hcand)
        print("  %s: R=%.12f" % (tag, r))
        if r > altR:
            altR = r
            alt_best = hcand.copy()
        if r > bestR + 1e-15:
            best, bestR = hcand.copy(), r
            return True
        return False

    # Main idea: continuous-beta homotopy. Start with large beta (near max-only
    # gradient, which is the hard part: only a few knots are at the max), then
    # anneal beta down to a small value so many knots get pushed toward max.
    # This is a different mechanism than lift/map-back and allows more knots
    # to approach the maximum, exploiting Holder's inequality better.
    ratios = [(5, 4), (7, 6), (9, 8)]
    cycle = 0
    while time.process_time() < deadline - 4.0:
        cycle += 1
        if cycle > 30:
            break
        num, den = ratios[(cycle - 1) % len(ratios)]
        hp = _lift_noncomm(best, num, den)
        if hp.size < 2:
            break
        # beta homotopy: large beta -> small beta
        betas = [200.0, 80.0, 30.0, 12.0, 5.0, 2.0, 0.8, 0.3]
        cur = hp
        for bi, beta in enumerate(betas):
            if time.process_time() >= deadline - 3.5:
                break
            tlim = min(deadline - 3.0, time.process_time() + 2.0)
            if tlim <= time.process_time() + 0.3:
                break
            cur = _lbfgs_block(cur, np.arange(cur.size), 60, tlim, beta=beta)
        # final tie polish
        if time.process_time() < deadline - 3.0:
            tlim = min(deadline - 2.5, time.process_time() + 2.0)
            cur = _lbfgs_block(cur, np.arange(cur.size), 60, tlim, tie=True)
        hb = _rescale(_map_back(cur, N0))
        try_update(hb, "cycle %d homotopy beta %d:%d" % (cycle, num, den))
        # tie polish on best
        if time.process_time() < deadline - 2.0:
            tlim = min(deadline - 1.5, time.process_time() + 2.0)
            if tlim > time.process_time() + 0.3:
                pol = _lbfgs_block(best, np.arange(best.size), 80, tlim, tie=True)
                try_update(pol, "cycle %d tie polish" % cycle)

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None and alt_best is not None:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


# ---------- direct low-dim subspace search on a coarse parameterization ----------

def _segment_compress(h, m):
    """Compress h (length N) to m segment means, then reconstruct via interpolation
    back to length N. Differentiable-ish; used to seed new structures."""
    N = h.size
    if m >= N:
        return h.copy()
    edges = np.linspace(0, N, m + 1).astype(int)
    seg = np.zeros(m)
    for j in range(m):
        lo, hi = edges[j], edges[j + 1]
        if hi > lo:
            seg[j] = h[lo:hi].mean()
    # upsample by linear interp of segment values at segment centers
    centers = 0.5 * (edges[:-1] + edges[1:])
    x = np.arange(N) + 0.5
    return np.interp(x, centers, seg)


def _fun_grad_on_segments(seg_m, h_base, m):
    """Evaluate R and its gradient wrt segment-mean parameters, with h_base length N.
    We rebuild h from seg, then chain rule through piecewise-constant assignment."""
    pass  # not used; kept for clarity


def _es_on_segments(h_best, R_best, m, deadline, rng, sigma0=0.05, mu=6, lam=12):
    """ES over m segment-mean log-parameters. Returns (R, h) of best."""
    N = h_best.size
    edges = np.linspace(0, N, m + 1).astype(int)
    centers = 0.5 * (edges[:-1] + edges[1:]).astype(float)
    x = np.arange(N, dtype=float) + 0.5

    # initial segment values: mean of current h per segment (positive)
    seg0 = np.array([h_best[edges[j]:edges[j+1]].mean() if edges[j+1] > edges[j] else 0.0
                     for j in range(m)])
    seg0 = np.clip(seg0, 1e-12, None)
    u0 = np.log(seg0)

    def to_h(u):
        seg = np.exp(u)
        hh = np.interp(x, centers, seg)
        return np.clip(hh, 0, None)

    def E(u):
        hh = to_h(u)
        return R_of(hh), hh

    u = u0.copy()
    best_R, best_h = E(u)
    best_u = u.copy()
    sigma = sigma0
    no_improve = 0
    evals = 1
    max_evals = 4000
    while evals < max_evals and time.process_time() < deadline:
        pop = []
        for _ in range(lam):
            if time.process_time() >= deadline:
                break
            uc = u + sigma * rng.randn(m)
            Rc, hc = E(uc)
            evals += 1
            pop.append((Rc, uc, hc))
        if not pop:
            break
        pop.sort(key=lambda t: -t[0])
        top = pop[:mu]
        u = np.mean([t[1] for t in top], axis=0)
        if top[0][0] > best_R + 1e-15:
            best_R = top[0][0]
            best_u = top[0][1].copy()
            best_h = top[0][2].copy()
            no_improve = 0
        else:
            no_improve += 1
        succ = sum(1 for t in pop if t[0] > best_R - 1e-15) / max(1, len(pop))
        if succ > 0.2:
            sigma *= 1.2
        else:
            sigma *= 0.85
        sigma = float(np.clip(sigma, 1e-4, 3.0))
        if no_improve > 60:
            break
    return best_R, best_h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h_best = _rescale(base)
        else:
            N = 8192
            i = np.arange(N, dtype=float)
            h_best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))
    else:
        N = 8192
        i = np.arange(N, dtype=float)
        h_best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    R_best = R_of(h_best)
    startR = R_best
    N = h_best.size
    print("base R=%.9f (N=%d)" % (R_best, N))

    rng = np.random.RandomState(135792468)

    # Phase 1: low-dim segment-mean ES to explore genuinely new shapes.
    # Use several resolutions; keep the best that beats start.
    best_alt = None
    best_alt_R = -1.0
    res_list = [48, 96, 192, 384]
    for m in res_list:
        if time.process_time() > deadline - 20.0:
            break
        tlim = min(deadline - 18.0, time.process_time() + 8.0)
        Rc, hc = _es_on_segments(h_best, R_best, m, tlim, rng, sigma0=0.08)
        print("segment ES m=%d R=%.9f" % (m, Rc))
        if Rc > best_alt_R:
            best_alt_R = Rc
            best_alt = hc
        if Rc > R_best + 1e-12:
            h_best = hc
            R_best = Rc
            print("  ACCEPT segment ES R=%.9f" % R_best)

    # Phase 2: gradient polish of the best (either start or alternative).
    while time.process_time() < deadline - 3.0:
        tlim = min(deadline - 2.0, time.process_time() + 6.0)
        hp = _full_lbfgs(h_best, tlim, maxiter=120)
        Rp = R_of(hp)
        if Rp > R_best + 1e-13:
            h_best = hp
            R_best = Rp
            print("full polish R=%.9f" % Rp)
        else:
            break
        if time.process_time() > deadline - 4.0:
            break

    # Phase 3: peak-window polish
    for _ in range(3):
        if time.process_time() > deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hp = _peak_window_polish(h_best, tlim, pad=3, frac=8)
        Rp = R_of(hp)
        if Rp > R_best + 1e-14:
            h_best = hp
            R_best = Rp
            print("peak polish R=%.9f" % Rp)
        else:
            break

    print("final R=%.12f (start %.12f, N=%d)" % (R_best, startR, h_best.size))

    # If we improved on start, return as best. If the alternative differs and
    # doesn't beat start, return it as alternative.
    if R_best >= startR - 1e-15:
        return {"best": h_best}
    else:
        # didn't beat start; keep start as best, alternative = our attempt
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        alt = h_best if best_alt is None or R_of(h_best) >= best_alt_R else best_alt
        if alt is None:
            alt = h_best
        return {"best": base, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1200:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1200:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    """CVaR top-alpha: soft-max over the top alpha fraction of knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    k = max(1, int(alpha * Lf.size))
    # top-k threshold
    if k >= Lf.size:
        idx = np.arange(Lf.size)
    else:
        thr = np.partition(Lf, Lf.size - k)[Lf.size - k]
        idx = np.flatnonzero(Lf >= thr)
    w = 1.0 / idx.size
    gLf = -dq / num
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, tie=False, free=None, cvar=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if cvar is not None:
        fg = (lambda hh: _fun_grad_cvar(hh, cvar))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    if free is None:
        active = None
    else:
        active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0

    if active is None:
        def f(x):
            hh = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g
        x0 = h.copy()
        nb = n
    else:
        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g[active]
        x0 = h[active].copy()
        nb = active.size

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    if active is None:
        return _rescale(np.clip(res.x, 0.0, None))
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline, lam=0.0, thr=0.6, tie=True):
    """Log-space L-BFGS-B on active cells with interior-shoulder hinge penalty."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.flatnonzero(h > 0)
    if active.size == 0:
        return h0
    n = h.size
    base = h.copy()

    def f(z):
        hh = base.copy()
        hh[active] = np.exp(np.clip(z, -60.0, 60.0))
        val, g = (_fun_grad_tie(hh) if tie else _fun_grad(hh))
        # hinge penalty on interior knots below thr*max
        if lam > 0:
            num, dq, Lf = _num_and_dq(hh)
            mx = Lf.max()
            # interior knots: exclude the very ends
            lo = max(1, Lf.size // 20)
            hi = Lf.size - lo
            seg = Lf[lo:hi]
            below = seg < thr * mx
            if np.any(below):
                deficit = (thr * mx - seg) * below
                pen = lam * np.mean(deficit)
                val = val + pen
                # gradient of penalty wrt Lf
                gLf_pen = np.zeros_like(Lf)
                cnt = hi - lo
                gLf_pen[lo:hi] = -lam * below / cnt
                # plus thr*mx term contributes to max knot
                m = int(np.argmax(Lf))
                gLf_pen[m] += lam * thr * np.sum(below) / cnt
                gpen = _backprop(gLf_pen, hh)
                g = g + gpen
        # chain rule through exp
        gz = g[active] * hh[active]
        return val, gz

    z0 = np.log(np.maximum(base[active], 1e-12))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, z0, jac=True, method='L-BFGS-B',
                       bounds=[(-60.0, 60.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = base.copy()
    h2[active] = np.exp(np.clip(res.x, -60.0, 60.0))
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    c = np.concatenate(([0.0], np.cumsum(h)))
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _prolongate(h, n_new):
    r0 = R_of(h)
    rep = n_new // len(h)
    if rep >= 1 and rep * len(h) == n_new:
        cand = np.repeat(h, rep)
        cand = _rescale(cand)
        if R_of(cand) >= r0 - 1e-6:
            return cand
    cand = _prolong(h, n_new)
    cand = _rescale(cand)
    return cand


def _block_sum(h, factor):
    n = len(h)
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor).sum(axis=1)
    return _rescale(hh)


def _peak_window(h, tol=0.9995, pad_frac=0.3, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size, hi + pad)
    return np.arange(lo, hi)


def _shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(Lf >= 0.999 * mx),
            np.mean(Lf >= 0.99 * mx),
            np.mean(Lf >= 0.95 * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None; best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy(); best_R = R_of(best)

    if best is None:
        best = np.ones(1024); best_R = R_of(best)

    start_R = best_R
    cur = best.copy(); cur_R = best_R
    N = len(cur)
    print(f"start R={best_R:.6f} N={N}")

    # ---- Phase A: coarsen + log-space hinge-annealed climb ----
    phaseA_end = min(deadline - 30.0, t0 + 25.0)
    levels = []
    for f in (8, 4, 2):
        if N // f >= 256:
            levels.append(N // f)
    levels.append(N)

    for lvl in levels:
        if time.process_time() >= phaseA_end:
            break
        if lvl < N:
            h_lvl = _block_sum(cur, N // lvl)
        else:
            h_lvl = _prolongate(cur, lvl) if len(cur) != lvl else cur.copy()
        r_lvl = R_of(h_lvl)
        print(f"phaseA level {lvl}: R={r_lvl:.6f}")
        # anneal lam
        for lam in (0.1, 0.03, 0.01):
            if time.process_time() >= phaseA_end:
                break
            h_lvl = _lbfgs_log(h_lvl, 120, phaseA_end, lam=lam, thr=0.6, tie=True)
            r_lvl = R_of(h_lvl)
            print(f"  lam={lam:.2f} R={r_lvl:.6f}")
        # also plain tie polish
        if time.process_time() < phaseA_end:
            h_lvl = _lbfgs(h_lvl, 80, phaseA_end, tie=True)
            r_lvl = R_of(h_lvl)
        # prolongate back up to cur's level
        if lvl < N:
            cand = _prolongate(h_lvl, N)
        else:
            cand = h_lvl
        cand = _lbfgs(cand, 100, phaseA_end, tie=True)
        r = R_of(cand)
        print(f"  back to N: R={r:.6f} best={best_R:.6f}")
        if r > cur_R + 1e-12:
            cur = cand; cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy(); best_R = r

    # ---- Phase B: CVaR top-alpha ladder at full N ----
    phaseB_end = min(deadline - 15.0, time.process_time() + 15.0)
    for alpha in (0.05, 0.02, 0.01):
        if time.process_time() >= phaseB_end:
            break
        cand = _lbfgs(cur, 60, phaseB_end, cvar=alpha)
        r = R_of(cand)
        print(f"phaseB alpha={alpha} R={r:.6f} best={best_R:.6f}")
        if r > cur_R + 1e-12:
            cur = cand; cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy(); best_R = r

    # ---- Phase C: peak-window polish + tie-mode full polish ----
    for tol in (0.9999, 0.999, 0.99, 0.95):
        if time.process_time() >= deadline - 4.0:
            break
        free = _peak_window(cur, tol=tol)
        cand = _lbfgs(cur, 80, deadline - 3.0, free=free)
        r = R_of(cand)
        print(f"phaseC win={tol} R={r:.6f} best={best_R:.6f}")
        if r > cur_R + 1e-12:
            cur = cand; cur_R = r
            if r > best_R + 1e-12:
                best = cand.copy(); best_R = r

    if time.process_time() < deadline - 0.5:
        cand = _lbfgs(best, 400, deadline, tie=True)
        r = R_of(cand)
        if r > best_R:
            best = cand; best_R = r
        print(f"final tie polish R={best_R:.6f}")

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    s01, s1, s5 = _shares(best)
    print(f"final R={best_R:.6f} N={len(best)} shares 0.1%/1%/5% = {s01:.4f}/{s1:.4f}/{s5:.4f}")

    if best_R >= start_R:
        return best
    return {"best": np.asarray(start, dtype=float), "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _coarsen(h, c):
    n = h.size
    if c <= 1:
        return h.copy()
    m = (n + c - 1) // c
    pad = m * c - n
    hp = np.concatenate((h, np.zeros(pad)))
    return hp.reshape(m, c).mean(axis=1)


def _refine(h, deadline, rng, factor=2):
    """Upsample by linear interpolation then gradient polish at higher resolution."""
    n = h.size
    m = n * factor
    x = np.arange(m) + 0.5
    xp = (np.arange(n) + 0.5) * (m / n)
    hu = np.interp(x, xp, h)
    hu = _rescale(np.clip(hu, 0, None))
    return _full_lbfgs(hu, deadline, maxiter=200)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h_best = _rescale(base)
        else:
            N = 8192
            i = np.arange(N, dtype=float)
            h_best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))
    else:
        N = 8192
        i = np.arange(N, dtype=float)
        h_best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    R_best = R_of(h_best)
    startR = R_best
    print("base R=%.9f (N=%d)" % (R_best, h_best.size))

    alt_h = None
    alt_R = -1.0

    # Phase 1: coarsen -> gradient polish -> refine back, at several scales.
    # This explores smoother perturbations that full-res L-BFGS can't reach.
    for c in [8, 4, 2]:
        if time.process_time() > deadline - 8.0:
            break
        hc = _coarsen(h_best, c)
        tlim = min(deadline - 6.0, time.process_time() + 4.0)
        hc = _full_lbfgs(hc, tlim, maxiter=200)
        Rc = R_of(hc)
        if Rc > R_best + 1e-12:
            h_best = hc
            R_best = Rc
            print("coarsen c=%d R=%.9f" % (c, Rc))
        # try refining the coarse solution back up
        if time.process_time() < deadline - 4.0:
            tlim = min(deadline - 3.0, time.process_time() + 3.0)
            hr = _refine(hc, tlim)
            Rr = R_of(hr)
            if Rr > R_best + 1e-12:
                h_best = hr
                R_best = Rr
                print("  refine R=%.9f" % Rr)

    # Phase 2: full-resolution polish loop
    while time.process_time() < deadline - 3.0:
        tlim = min(deadline - 2.0, time.process_time() + 6.0)
        hp = _full_lbfgs(h_best, tlim, maxiter=150)
        Rp = R_of(hp)
        if Rp > R_best + 1e-13:
            h_best = hp
            R_best = Rp
            print("full polish R=%.9f" % Rp)
        else:
            break
        if time.process_time() > deadline - 4.0:
            break

    # Phase 3: peak-window polish
    for _ in range(3):
        if time.process_time() > deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hp = _peak_window_polish(h_best, tlim, pad=3, frac=8)
        Rp = R_of(hp)
        if Rp > R_best + 1e-14:
            h_best = hp
            R_best = Rp
            print("peak polish R=%.9f" % Rp)
        else:
            break

    print("final R=%.12f (start %.12f, N=%d)" % (R_best, startR, h_best.size))

    if R_best >= startR - 1e-15:
        return {"best": h_best}
    else:
        base = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        return {"best": base, "alternative": h_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _full_polish(h, deadline, iters=400):
    ht = h
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, iters, deadline - 0.3, beta=beta)
    return ht


def _interlace_step(best, alpha, slice_dl):
    n = best.size
    h2 = np.zeros(2 * n)
    h2[0::2] = best
    left = np.concatenate(([0.0], best[:-1]))
    right = np.concatenate((best[1:], [0.0]))
    h2[1::2] = alpha * (left + right)
    h2 = _rescale(h2)
    ht = h2
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= slice_dl - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
    if time.process_time() < slice_dl - 0.5:
        win = _peak_window(ht, pad_frac=0.12, extra=128)
        ht2 = _lbfgs_block(ht, win, 400, slice_dl - 0.3, beta=1e7)
        if R_of(ht2) > R_of(ht):
            ht = ht2
    h1 = 0.5 * (ht[0::2] + ht[1::2])
    h1 = _rescale(h1)
    return h1


def _lift_step(working, slice_dl):
    c = working[0::2].copy()
    c = _full_polish(c, slice_dl, iters=400)
    h_lift = _rescale(np.repeat(c, 2))
    ht = h_lift
    for beta in [1e6, 1e7]:
        if time.process_time() >= slice_dl - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 400, slice_dl - 0.3, beta=beta)
    return ht


def _fine_peak_shrink(best, bestR, deadline, alt_best, alt_bestR):
    """NEW: progressively finer peak-window polish with shrinking pads."""
    for pad, iters in [(0.20, 500), (0.12, 500), (0.07, 500), (0.04, 500),
                       (0.025, 500), (0.015, 500)]:
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
    return best, bestR, alt_best, alt_bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    N = best.size
    best_c = None
    best_cR = -1.0
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.18
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift+ladder'
            print("lift+ladder NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    alphas = [0.25, 0.5, 0.125, 0.25, 0.5]
    working = best.copy()
    combined_rounds = 0
    for k in range(5):
        if time.process_time() >= deadline - 5.0:
            break
        slice_dl = min(deadline - 5.0,
                       time.process_time() + 0.13 * budget_seconds)
        h1 = _interlace_step(working, alphas[k], slice_dl)
        r1 = R_of(h1)
        if r1 > bestR + 1e-13:
            best, bestR = h1.copy(), r1
            origin = 'comb_int%d' % (k + 1)
            print("comb round %d interlace ACCEPT R=%.9f" % (k + 1, bestR))
        else:
            print("comb round %d interlace rejected R=%.9f" % (k + 1, r1))
        working = h1
        if time.process_time() >= deadline - 5.0:
            break
        h_lift = _lift_step(working, slice_dl)
        r2 = R_of(h_lift)
        if r2 > bestR + 1e-13:
            best, bestR = h_lift.copy(), r2
            origin = 'comb_lift%d' % (k + 1)
            print("comb round %d lift ACCEPT R=%.9f" % (k + 1, bestR))
        else:
            print("comb round %d lift no gain R=%.9f" % (k + 1, r2))
        working = h_lift
        combined_rounds += 1
        if r2 > alt_bestR and r2 < bestR:
            alt_best, alt_bestR = h_lift.copy(), r2

    print("combined rounds=%d" % combined_rounds)

    lift_rounds = 0
    while lift_rounds < 2 and time.process_time() < deadline - 6.0:
        if best.size % 2 != 0 or best.size < 4:
            break
        slice_dl = min(deadline - 5.0,
                       time.process_time() + 0.11 * budget_seconds)
        h_lift = _lift_step(best, slice_dl)
        r = R_of(h_lift)
        lift_rounds += 1
        if r > bestR + 1e-13:
            best, bestR, origin = h_lift.copy(), r, 'lift%d' % lift_rounds
            print("lift round %d NEW BEST R=%.9f" % (lift_rounds, bestR))
        else:
            if r > alt_bestR:
                alt_best, alt_bestR = h_lift.copy(), r
            print("lift round %d no gain R=%.9f" % (lift_rounds, r))

    # NEW: fine peak shrink before restarts, using leftover time
    if time.process_time() < deadline - 8.0:
        best, bestR, alt_best, alt_bestR = _fine_peak_shrink(
            best, bestR, min(deadline - 6.0,
                             time.process_time() + 0.15 * budget_seconds),
            alt_best, alt_bestR)
        print("fine-peak R=%.9f" % bestR)

    restarts_done = 0
    if best_c is not None and time.process_time() < deadline - 4.0:
        rng = np.random.default_rng(7)
        amps = [0.008, 0.015, 0.03, 0.05]
        ri = 0
        while time.process_time() < deadline - 4.0:
            amp = amps[ri % len(amps)]
            ri += 1
            cc2 = best_c.copy()
            nz = cc2 > 0
            if nz.sum() == 0:
                break
            cc2[nz] *= np.exp(amp * rng.standard_normal(int(nz.sum())))
            cc2 = _rescale(cc2)
            r0 = R_of(cc2)
            slice_deadline = min(deadline - 2.0,
                                 time.process_time() + 0.04 * budget_seconds)
            work_c2, cand_c, cand_cR, org = _half_cycle(
                cc2, r0, slice_deadline, tag='rs%d' % ri,
                pads=[0.30, 0.15])
            restarts_done += 1
            if cand_cR > best_cR + 1e-12:
                best_c = cand_c.copy()
                best_cR = cand_cR
                print("restart %d amp=%.3f ACCEPT R(c)=%.9f" %
                      (ri, amp, best_cR))
            if time.process_time() >= deadline - 4.0:
                break

    if best_c is not None:
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        if r_lift > bestR + 1e-14:
            best, bestR, origin = h_lift.copy(), r_lift, 'restart_lift'
            print("restart lift NEW BEST R=%.9f" % bestR)
        elif r_lift > alt_bestR:
            alt_best, alt_bestR = h_lift, r_lift
        ht = h_lift
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+full'
            print("full polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # Final fine peak shrink rounds
    best, bestR, alt_best, alt_bestR = _fine_peak_shrink(
        best, bestR, deadline, alt_best, alt_bestR)

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("combined_rounds=%d lift_rounds=%d restarts=%d best_c=%.9f best_full=%.9f" %
          (combined_rounds, lift_rounds, restarts_done, best_cR, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_logM(h0, maxiter, deadline):
    """Log-space L-BFGS-B on a small (length-M) vector."""
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    x0 = np.log(h[pos])

    def f(x):
        hh = h.copy()
        hh[pos] = np.exp(np.clip(x, -50, 50))
        val, g = _fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-18, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -50, 50))
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=3.0, extra=8):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_polish(h, deadline, iters=200):
    win = _peak_window(h)
    ht = _lbfgs_block(h, win, iters, deadline)
    if R_of(ht) > R_of(h):
        return ht
    return h


def _detect_period(h, tol=1e-9):
    """Detect block period p such that h is constant in blocks of size p."""
    n = h.size
    hmax = h.max()
    if hmax <= 0:
        return n
    for p in range(1, min(n, 4096) + 1):
        if n % p != 0:
            continue
        m = n // p
        blocks = h.reshape(m, p)
        if np.all(np.abs(blocks - blocks[:, :1]) <= tol * hmax):
            return p
    return n


def _coarsen(h, p):
    n = h.size
    m = n // p
    return h.reshape(m, p).mean(axis=1)


def _expand(v, N):
    M = v.size
    m = N // M
    if m < 1:
        return v.copy()
    h = np.repeat(v, m)
    rem = N - h.size
    if rem > 0:
        h = np.concatenate([h, np.full(rem, v[-1])])
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # Detect period to get exact block staircase
    p = _detect_period(best)
    if p >= N:
        # not a staircase; just do base fill
        print("no block period detected, falling back")
        v0 = None
    else:
        v0 = _coarsen(best, p)
        M0 = v0.size
        # verify R_M(v0) == R_of(start)
        r_check = R_of(v0)
        print("period=%d M0=%d R_M(v0)=%.12f vs R(start)=%.12f diff=%.2e"
              % (p, M0, r_check, bestR, abs(r_check - bestR)))

    if v0 is None:
        # fallback: use base's fill loop
        if time.process_time() < deadline - 1.0:
            ht = _lbfgs_all_pos(best, 500, deadline - 0.5)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
        result = {"best": best}
        if bestR <= start_bestR + 1e-14 and start_best is not None:
            result["alternative"] = start_best
        return result

    # Sequential continuation M = M0, M0+1, ..., M_max
    M_max = max(M0 + 24, 56)
    cur_v = v0.copy()
    cur_R = R_of(cur_v)
    best_v = cur_v.copy()
    best_vR = cur_R
    best_M = M0
    rng = np.random.default_rng(2024)

    # time budget: leave ~16s for final polish
    seq_end = deadline - 16.0
    if seq_end < t0 + 1.0:
        seq_end = t0 + budget_seconds * 0.6

    print("start sequential continuation M=%d..%d, R=%.9f"
          % (M0, M_max, cur_R))

    for M in range(M0, M_max):
        if time.process_time() >= seq_end - 0.3:
            print("time out at M=%d" % M)
            break
        # per-M time slice
        slice_end = min(seq_end, time.process_time() + max(0.5, (seq_end - time.process_time()) / max(1, (M_max - M))))
        Mnew = M + 1
        best_cand = None
        best_candR = -1.0
        best_j = -1

        # (1) deterministic splits: for each j, duplicate level j
        for j in range(M):
            if time.process_time() >= slice_end - 0.2:
                break
            cand = np.concatenate([cur_v[:j+1], cur_v[j:]])
            cand = _lbfgs_logM(cand, 40, slice_end)
            r = R_of(cand)
            if r > best_candR:
                best_candR = r
                best_cand = cand
                best_j = j

        # (2) random splits with offset
        n_rand = 20
        for _ in range(n_rand):
            if time.process_time() >= slice_end - 0.2:
                break
            j = int(rng.integers(0, M))
            a = cur_v[j]
            fac = np.exp(rng.uniform(-0.5, 0.5))
            hi = a * fac
            lo = a / fac
            cand = np.concatenate([cur_v[:j], [lo, hi], cur_v[j+1:]])
            cand = _lbfgs_logM(cand, 40, slice_end)
            r = R_of(cand)
            if r > best_candR:
                best_candR = r
                best_cand = cand
                best_j = j

        if best_cand is None:
            print("M=%d no candidate" % Mnew)
            break

        improved = best_candR > cur_R + 1e-14
        if improved:
            cur_v = best_cand
            cur_R = best_candR
        if best_candR > best_vR + 1e-14:
            best_v = best_cand.copy()
            best_vR = best_candR
            best_M = Mnew
        print("M=%d best R_M=%.9f split_j=%d %s (best %.9f @M=%d)"
              % (Mnew, best_candR, best_j,
                 "ACCEPT" if improved else "reject", best_vR, best_M))

    print("sequential done: best R_M=%.9f at M=%d (start %.9f)"
          % (best_vR, best_M, start_bestR))

    # If best M-level beats start, expand and polish
    if best_vR > start_bestR + 1e-9:
        print("expanding M=%d to N=%d and polishing" % (best_M, N))
        h_exp = _expand(best_v, N)
        h_exp = _rescale(h_exp)
        r_exp = R_of(h_exp)
        print("expanded R=%.9f" % r_exp)
        # full polish 10s
        if time.process_time() < deadline - 6.0:
            dl = min(deadline - 6.0, time.process_time() + 10.0)
            ht = _lbfgs_all_pos(h_exp, 500, dl)
            r = R_of(ht)
            if r > r_exp:
                h_exp, r_exp = ht, r
                print("full polish ACCEPT R=%.9f" % r_exp)
            else:
                print("full polish reject R=%.9f" % r)
        # peak window polish 6s
        if time.process_time() < deadline - 0.5:
            dl = min(deadline - 0.3, time.process_time() + 6.0)
            ht = _peak_polish(h_exp, dl, iters=300)
            r = R_of(ht)
            if r > r_exp:
                h_exp, r_exp = ht, r
                print("peak polish ACCEPT R=%.9f" % r_exp)
            else:
                print("peak polish reject R=%.9f" % r)
        if r_exp > bestR + 1e-14:
            best, bestR = h_exp, r_exp
            print("NEW BEST R=%.9f" % bestR)
    else:
        print("M-level best did not beat start; keeping start")

    # fill remaining budget with base's full polish
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_all_pos(best, 500, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("final full polish ACCEPT R=%.9f" % bestR)
        else:
            print("final full polish reject R=%.9f" % r)

    if time.process_time() < deadline - 0.3:
        ht = _peak_polish(best, deadline, iters=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            print("final peak polish ACCEPT R=%.9f" % bestR)
        else:
            print("final peak polish reject R=%.9f" % r)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = start_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
