    alt_best = None
    altR = -1.0

    # ---- Phase 1: coarsen to a smaller resolution, optimize at low N, then refine ----
    # The key idea: the optimal f is smooth at large scale; optimizing a coarse
    # representation escapes the flat landscape that traps full-resolution polish.
    N = best.size
    for c in (16, 8, 4, 2):
        if time.process_time() >= deadline - 5.0:
            break
        hc = _coarsen(best, c)
        if hc.size < 32:
            break
        # optimize coarse with CVaR then tie
        tlim = min(deadline - 4.0, time.process_time() + 4.0)
        hc2 = _lbfgs(hc, lambda hh: _fun_grad_cvar(hh, 0.02), tlim, maxiter=150)
        r_c = R_of(_refine(hc2, c))
        print("coarse c=%d R=%.12f" % (c, r_c))
        if r_c > altR:
            altR, alt_best = r_c, _refine(hc2, c)
        # refine back up and do a short full polish
        hr = _refine(hc2, c)
        # pad/trim to N
        if hr.size < N:
            hr = np.concatenate([hr, np.zeros(N - hr.size)])
        elif hr.size > N:
            hr = hr[:N]
        if time.process_time() < deadline - 3.0:
            tlim2 = min(deadline - 2.0, time.process_time() + 3.0)
            hr = _lbfgs(hr, _fun_grad_tie, tlim2, maxiter=120)
        r = R_of(hr)
        print("refined c=%d R=%.12f (best %.12f)" % (c, r, bestR))
        if r > bestR + 1e-15:
            best, bestR = hr.copy(), r
        if r > altR:
            altR, alt_best = r, hr.copy()

    # ---- Phase 2: full tie polish ----
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 6.0)
        pol = _lbfgs(best, _fun_grad_tie, tlim, maxiter=300)
        rp = R_of(pol)
        print("tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        else:
            break
        if rp > altR:
            altR, alt_best = rp, pol.copy()

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

