    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, cvar=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if cvar > 0:
        fg = (lambda hh: _fun_grad_cvar(hh, cvar))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad(h):
    return _fun_grad_tie(h)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- sharp staircase machinery ----------

def _build_sharp(u, b, N):
    M = u.size
    a = np.exp(np.clip(u, -40.0, 40.0))
    bounds = np.clip(np.asarray(b, dtype=int), 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] < bounds[j - 1] + 1:
            bounds[j] = bounds[j - 1] + 1
    h = np.empty(N)
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        h[prev:bb] = a[j]
        prev = bb
    h[prev:] = a[M - 1]
    return h


def _fun_grad_sharp(u, b, N):
    h = _build_sharp(u, b, N)
    val, gh = _fun_grad_tie(h)
    M = u.size
    a = np.exp(np.clip(u, -40.0, 40.0))
    bounds = np.clip(np.asarray(b, dtype=int), 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] < bounds[j - 1] + 1:
            bounds[j] = bounds[j - 1] + 1
    gu = np.zeros(M)
    gb = np.zeros(M - 1)
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        seg = slice(prev, bb)
        # gradient wrt level a[j] via chain rule u -> a
        gu[j] += np.sum(gh[seg]) * a[j]
        prev = bb
    gu[M - 1] += np.sum(gh[prev:]) * a[M - 1]
    # boundary gradients (b[j] moves one unit from level j+1 to level j)
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        if 1 <= bb < N - 1:
            gb[j] = gh[bb - 1] - gh[bb]
        prev = bb
    return val, (gu, gb)


def _optimize_sharp(u0, b0, N, deadline, maxiter=200):
    M = u0.size
    if M < 2:
        return _build_sharp(u0, b0, N)
    # joint optimization: parameters = [u (M), b (M-1)]
    x0 = np.concatenate([u0, np.asarray(b0, dtype=float)])

    def f(x):
        u = x[:M]
        b = x[M:]
        val, (gu, gb) = _fun_grad_sharp(u, b, N)
        return val, np.concatenate([gu, gb])

    # bounds: u in [-40,40], b in [1, N-1]
    bounds = [(-40.0, 40.0)] * M + [(1.0, float(N - 1))] * (M - 1)
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return _build_sharp(u0, b0, N)
    if res is None:
        return _build_sharp(u0, b0, N)
    u = res.x[:M]
    b = np.round(res.x[M:]).astype(int)
    h = _build_sharp(u, b, N)
    return _rescale(h)


def _init_sharp_from_h(h, M):
    """Compress h into M levels + boundaries via cumulative-mass quantiles."""
    N = h.size
    c = np.cumsum(h)
    total = c[-1]
    if total <= 0:
        a = np.ones(M)
        bounds = np.linspace(0, N, M + 1).astype(int)[1:-1]
        return np.log(a), bounds
    targets = total * np.linspace(0, 1, M + 1)[1:-1]
    bounds = np.searchsorted(c, targets)
    bounds = np.clip(bounds, 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] < bounds[j - 1] + 1:
            bounds[j] = bounds[j - 1] + 1
    a = np.empty(M)
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        if bb > prev:
            a[j] = h[prev:bb].mean()
        else:
            a[j] = h[prev] if prev < N else 1.0
        prev = bb
    a[M - 1] = h[prev:].mean() if prev < N else 1.0
    a = np.clip(a, 1e-12, None)
    return np.log(a), bounds


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    candidates = []

    def record(h, name):
        if h is None:
            return
        r = R_of(h)
        candidates.append((r, h.copy(), name))
        print("  branch %s R=%.12f (d=%.2e)" % (name, r, r - startR))

    N = best.size

    # Branch A: sharp staircase at moderate M, joint optimize
    if time.process_time() < deadline - 1.0:
        for M in (64, 128, 256):
            if time.process_time() >= deadline - 1.0:
                break
            u0, b0 = _init_sharp_from_h(best, M)
            tlim = min(deadline - 0.5, time.process_time() + 4.0)
            hA = _optimize_sharp(u0, b0, N, tlim, maxiter=300)
            record(hA, "sharp%d" % M)

    # Branch B: CVaR polish on best (encourages flat top)
    if time.process_time() < deadline - 1.0:
        hB = best.copy()
        for alpha in (0.3, 0.2, 0.1, 0.05):
            if time.process_time() >= deadline - 0.5:
                break
            tlim = min(deadline - 0.4, time.process_time() + 2.0)
            hB = _lbfgs_block(hB, np.arange(hB.size), 150, tlim, cvar=alpha)
        record(hB, "cvar")

    # Branch C: beta ladder on full array
    if time.process_time() < deadline - 1.0:
        hC = best.copy()
        for beta in (1e3, 1e5, 1e7):
            if time.process_time() >= deadline - 0.5:
                break
            tlim = min(deadline - 0.4, time.process_time() + 2.0)
            hC = _lbfgs_block(hC, np.arange(hC.size), 150, tlim, beta=beta)
        record(hC, "beta")

    for r, h, name in candidates:
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    print("after branches best R=%.12f (start %.12f)" % (bestR, startR))

    # ---------- Final race: alternate sharp + full ----------
    N = best.size
    rnd = 0
    Ms = [256, 512, 1024]
    while time.process_time() < deadline - 0.5:
        rnd += 1
        # full tie polish
        tlim = min(deadline - 0.4, time.process_time() + 3.0)
        h1 = _lbfgs_block(best, np.arange(best.size), 200, tlim, tie=True)
        r1 = R_of(h1)
        if r1 > bestR + 1e-15:
            best, bestR = h1.copy(), r1
        # sharp staircase at increasing M
        M = Ms[(rnd - 1) % len(Ms)]
        if M <= N and time.process_time() < deadline - 0.5:
            u0, b0 = _init_sharp_from_h(best, M)
            tlim = min(deadline - 0.3, time.process_time() + 4.0)
            h2 = _optimize_sharp(u0, b0, N, tlim, maxiter=200)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
        # CVaR polish occasionally
        if rnd % 2 == 0 and time.process_time() < deadline - 0.4:
            tlim = min(deadline - 0.3, time.process_time() + 2.0)
            h3 = _lbfgs_block(best, np.arange(best.size), 100, tlim, cvar=0.1)
            r3 = R_of(h3)
            if r3 > bestR + 1e-15:
                best, bestR = h3.copy(), r3

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if candidates:
        r, h, name = max(candidates, key=lambda t: t[0])
        if r > startR - 1e-12 and r < bestR - 1e-15:
            result["alternative"] = h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_lse(h, beta):
    """LogSumExp surrogate for L-inf: smooth, gives plateau-widening gradients."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_pnorm(h, p):
    """p-norm surrogate for L-inf (favor flat top)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 1e-300, None)
    # softmax-like weights for p-norm
    w = Lp ** (p - 1.0)
    Sp = np.sum(Lp ** p)
    if Sp <= 0:
        return _fun_grad(h)
    sm = Sp ** (1.0 / p)
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -40.0, 40.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, fg=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, fg=fg)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _coarsen(h, k):
    n = h.size
    n2 = (n + k - 1) // k
    pad = n2 * k - n
    if pad > 0:
        hp = np.concatenate([h, np.zeros(pad)])
    else:
        hp = h
    return hp.reshape(n2, k).sum(axis=1)


def _prolong(H, k, n_target):
    out = np.repeat(H, k)
    if out.size > n_target:
        out = out[:n_target]
    elif out.size < n_target:
        out = np.concatenate([out, np.zeros(n_target - out.size)])
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    N = best.size
    cur = best.copy()
    curR = bestR

    # ---- Coarse multi-resolution polish with LSE + p-norm surrogates ----
    for k in (8, 16, 4):
        if time.process_time() >= deadline - 8.0:
            break
        H = _coarsen(cur, k)
        H = _rescale(H)
        Rc0 = R_of(_prolong(H, k, N))
        print("  coarse k=%d: R before=%.7f (n=%d)" % (k, Rc0, H.size))
        Hc = H.copy()
        for rnd in range(4):
            if time.process_time() >= deadline - 8.0:
                break
            Hc = _lbfgs_log(Hc, 600, deadline, fg=_fun_grad)
            for p in (4.0, 8.0, 16.0, 32.0):
                if time.process_time() >= deadline - 8.0:
                    break
                Hc = _lbfgs_log(Hc, 250, deadline,
                                fg=(lambda hh, pp=p: _fun_grad_pnorm(hh, pp)))
            for beta in (1e4, 1e6, 1e8, 1e10):
                if time.process_time() >= deadline - 8.0:
                    break
                Hc = _lbfgs_log(Hc, 250, deadline,
                                fg=(lambda hh, bb=beta: _fun_grad_lse(hh, bb)))
            Rc = R_of(_prolong(Hc, k, N))
            if Rc > Rc0 + 3e-13:
                Rc0 = Rc
                print("    k=%d rnd %d R=%.7f" % (k, rnd, Rc0))
            else:
                print("    k=%d rnd %d R=%.7f (no gain)" % (k, rnd, Rc))
        hp = _rescale(_prolong(Hc, k, N))
        rp = R_of(hp)
        print("  coarse k=%d: after prolong R=%.7f" % (k, rp))
        if rp > curR + 3e-13:
            cur, curR = hp, rp
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR

    # ---- Full-resolution alternating surrogate pipeline ----
    stage = 0
    surrogates = []
    for p in (4.0, 8.0, 16.0):
        surrogates.append(("p%.0f" % p,
                           (lambda hh, pp=p: _fun_grad_pnorm(hh, pp))))
    for beta in (1e4, 1e6, 1e8):
        surrogates.append(("lse%.0e" % beta,
                           (lambda hh, bb=beta: _fun_grad_lse(hh, bb))))

    while time.process_time() < deadline - 3.0:
        stage += 1
        for name, fg in surrogates:
            if time.process_time() >= deadline - 4.0:
                break
            hb = _lbfgs_log(cur, 100, deadline, fg=fg)
            hs = _lbfgs_log(hb, 8, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.12, 48, maxiter=120)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            mx, m, near = _stats(cand)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                print("  stage %d %s R=%.7f Lmax=%.6e argmax=%d near=%d" %
                      (stage, name, curR, mx, m, near))
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
            else:
                print("  stage %d %s R=%.7f (no gain) argmax=%d near=%d" %
                      (stage, name, rc, m, near))

        # occasional exact-log polish
        if time.process_time() < deadline - 3.0:
            hb = _lbfgs_log(cur, 150, deadline, fg=_fun_grad)
            rs = R_of(hb)
            if rs > curR + 3e-13:
                cur, curR = hb, rs
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  stage %d exact R=%.7f" % (stage, curR))

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline, fg=_fun_grad)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    m = min(m, Lf.size)
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _coarsen(h, c):
    n = h.size
    m = (n + c - 1) // c
    pad = m * c - n
    if pad > 0:
        hh = np.concatenate([h, np.zeros(pad)])
    else:
        hh = h
    return hh.reshape(m, c).sum(axis=1)


def _refine(h, c):
    return np.repeat(h, c) / c


def _coarsen_offset(h, c, o):
    # sum-preserving coarsen with offset o; block sums / c
    n = h.size
    if o > 0:
        hh = np.concatenate([np.zeros(o), h])
    else:
        hh = h
    m = (hh.size + c - 1) // c
    pad = m * c - hh.size
    if pad > 0:
        hh = np.concatenate([hh, np.zeros(pad)])
    q = hh.reshape(m, c).sum(axis=1) / c
    return q, o


def _refine_offset(q, c, o, N):
    hr = np.repeat(q, c)
    if o > 0:
        hr = hr[o:]
    if hr.size < N:
        hr = np.concatenate([hr, np.zeros(N - hr.size)])
    elif hr.size > N:
        hr = hr[:N]
    return hr


def _shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(L >= mx * 0.999), np.mean(L >= mx * 0.99),
            np.mean(L >= mx * 0.95))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    N = best.size
    print("base R=%.12f (N=%d)" % (bestR, N))

    alt_best = None
    altR = -1.0

    def consider(cand, tag):
        nonlocal best, bestR, alt_best, altR
        cand = _rescale(np.clip(cand, 0, None))
        r = R_of(cand)
        if r > altR:
            altR, alt_best = r, cand.copy()
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
            s1, s2, s3 = _shares(best)
            print("%s R=%.12f shares %.4f/%.4f/%.4f" % (tag, r, s1, s2, s3))
            return True
        return False

    def time_left():
        return deadline - time.process_time()

    # ---- Phase 1: intermediate-level CVaR anneal with offset coarsening ----
    for c in (64, 32, 16, 8, 4, 2):
        if time_left() < 8.0:
            break
        max_off = min(c - 1, 7)
        for o in range(0, max_off + 1):
            if time_left() < 8.0:
                break
            q, oo = _coarsen_offset(best, c, o)
            if q.size < 16:
                continue
            for alpha in (0.30, 0.15, 0.07, 0.03, 0.015):
                if time_left() < 6.0:
                    break
                q = _lbfgs(q, lambda hh: _fun_grad_cvar(hh, alpha),
                           deadline - 1.0, maxiter=60)
            hr = _refine_offset(q, c, oo, N)
            if time_left() < 4.0:
                consider(hr, "c=%d o=%d" % (c, o))
                continue
            hr = _lbfgs(hr, _fun_grad_tie, deadline - 1.0, maxiter=30)
            consider(hr, "c=%d o=%d" % (c, o))

    # ---- Phase 2: final alpha ladder + tie polish on best ----
    if time_left() > 3.0:
        h = best.copy()
        for alpha in (0.02, 0.01, 0.005, 0.002):
            if time_left() < 2.0:
                break
            h = _lbfgs(h, lambda hh: _fun_grad_cvar(hh, alpha),
                       deadline - 0.5, maxiter=40)
        if time_left() > 1.0:
            h = _lbfgs(h, _fun_grad_tie, deadline - 0.5, maxiter=60)
        consider(h, "final-ladder")

    # ---- Phase 3: peak-window polish ----
    if time_left() > 2.0:
        try:
            h = best.copy()
            L = _knots(h)
            j = int(np.argmax(L))
            # knot j corresponds to region in h around j-1; window in h
            half = max(8, N // 64)
            lo = max(0, j - 1 - half)
            hi = min(N, j - 1 + half)
            if hi > lo:
                sub = h[lo:hi].copy()
                if sub.sum() > 0:
                    sub = _lbfgs(sub, _fun_grad_tie, deadline - 0.5, maxiter=60)
                    h2 = h.copy()
                    h2[lo:hi] = sub
                    consider(h2, "peak-window")
        except Exception:
            pass

    # ---- Phase 4: spend the rest cycling tie polish ----
    while time_left() > 1.0:
        h = _lbfgs(best, _fun_grad_tie, deadline - 0.5, maxiter=80)
        if not consider(h, "tie-cycle"):
            break

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_clip(h, c, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num_full, dq_full, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    Mb = mx + np.log(Z) / beta
    t = c * Mb
    mask = Lf < t
    u = np.minimum(Lf, t)
    a = u[:-1]; b = u[1:]
    num_c = np.sum(a * a + a * b + b * b) / 3.0
    if num_c <= 0:
        return _fun_grad(h)
    dqc = np.zeros_like(u)
    dqc[:-1] += (2 * a + b)
    dqc[1:] += (a + 2 * b)
    dqc /= 3.0
    above = ~mask
    sum_above = dqc[above].sum()
    dLf = np.where(mask, dqc, c * sum_above * w)
    grad = _backprop(dLf, h) + 2.0 / s
    val = -np.log(num_c) + 2.0 * np.log(s) + np.log(Mb)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_block_clip(h0, free, maxiter, deadline, c, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_clip(hh, c, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- Gaussian smoothing / resampling helpers (NEW) ----

def _gauss_kernel(sigma):
    r = max(1, int(np.ceil(4.0 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    return k / k.sum()


def _smooth(h, sigma):
    if sigma <= 0.05:
        return h
    k = _gauss_kernel(sigma)
    return np.convolve(h, k, mode='same')


def _resample(h, n_new):
    n = h.size
    if n_new == n:
        return h.copy()
    xp = (np.arange(n) + 0.5) / n
    xq = (np.arange(n_new) + 0.5) / n_new
    return np.interp(xq, xp, h)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: base polish.
    if time.process_time() < deadline - 1.5:
        best, bestR = run_cycle(best, bestR, deadline - 1.5)
        print("base cycle R=%.7f" % bestR)

    # NEW Phase 2: multi-scale resample + polish. Try coarser and finer
    # resolutions; a coarser grid can escape local structure, a finer one
    # resolves the peak better. Keep whichever wins.
    for scale in (0.5, 0.75, 2.0, 1.5):
        if time.process_time() >= deadline - 3.0:
            break
        n_new = int(np.clip(int(round(best.size * scale)), 256, 300000))
        if n_new == best.size:
            continue
        hs = _resample(best, n_new)
        hs = _rescale(np.clip(hs, 0, None))
        # quick polish at new resolution
        hs = _lbfgs_all_pos(hs, 300, deadline - 3.0, beta=0.0)
        r = R_of(hs)
        print("scale %.2f R=%.7f N=%d" % (scale, r, hs.size))
        if r > bestR + 1e-13:
            best, bestR = hs.copy(), r

    # NEW Phase 3: Gaussian smoothing kicks — re-blur the profile at a few
    # scales and re-optimize (helps break the sharp local optimum).
    for sigma in (1.0, 2.5, 5.0, 10.0, 20.0):
        if time.process_time() >= deadline - 2.5:
            break
        hs = _smooth(best, sigma)
        hs = _rescale(np.clip(hs, 0, None))
        hs = _lbfgs_all_pos(hs, 250, deadline - 2.5, beta=0.0)
        r = R_of(hs)
        print("smooth sigma=%.1f R=%.7f" % (sigma, r))
        if r > bestR + 1e-13:
            best, bestR = hs.copy(), r

    # Phase 4: slow low-c anneal of the clipped-L2 objective (from p1040).
    anneal = [(0.40, 1e2), (0.55, 1e2), (0.70, 1e3), (0.82, 1e3),
              (0.90, 1e4), (0.95, 1e4), (0.98, 1e5), (0.995, 1e5)]
    for i, (c, beta) in enumerate(anneal):
        if time.process_time() >= deadline - 2.0:
            break
        free = _peak_window(best, tol=0.90, pad_frac=0.6, extra=1024)
        ht = _lbfgs_block_clip(best, free, 400, deadline - 2.0, c, beta)
        ht = _rescale(ht)
        r = R_of(ht)
        print("anneal c=%.3f R=%.7f" % (c, r))
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        if (i % 2 == 1) and time.process_time() < deadline - 2.0:
            hp = _lbfgs_all_pos(best, 200, deadline - 2.0, beta=0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp.copy(), rp

    # Phase 5: full run_cycle after anneal.
    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("post-anneal cycle R=%.7f" % bestR)

    # Phase 6: final full L-BFGS polish.
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
