    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(1e6, 1e7, 0.0), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _interlace(h, w):
    k = len(w)
    n = h.size
    out = np.empty(k * n, dtype=float)
    for j in range(k):
        out[j::k] = h * w[j]
    return out


def _fold(hk, k):
    n = hk.size // k
    return hk[:k * n].reshape(n, k).sum(axis=1)


def _opt_weights(h, k, deadline, max_evals=60):
    best_w = np.ones(k)
    best_r = R_of(_interlace(h, best_w))
    evals = 1
    grid = np.array([0.6, 0.8, 1.0, 1.25, 1.6])
    for j in range(1, k):
        for g in grid:
            if evals >= max_evals or time.process_time() > deadline - 0.5:
                break
            w = best_w.copy()
            w[j] = g
            r = R_of(_interlace(h, w))
            evals += 1
            if r > best_r:
                best_r, best_w = r, w
    if evals < max_evals and time.process_time() < deadline - 1.0:
        def neg_r(x):
            w = np.ones(k)
            for j in range(1, k):
                w[j] = max(1e-3, x[j - 1])
            return -R_of(_interlace(h, w))
        try:
            x0 = best_w[1:].copy()
            res = minimize(neg_r, x0, method='Nelder-Mead',
                           options={'xatol': 1e-4, 'fatol': 1e-11,
                                    'maxiter': 60, 'maxfev': max(20, max_evals - evals)})
            if res is not None and np.isfinite(res.fun):
                w = np.ones(k)
                for j in range(1, k):
                    w[j] = max(1e-3, res.x[j - 1])
                r = R_of(_interlace(h, w))
                if r > best_r:
                    best_r, best_w = r, w
        except Exception:
            pass
    return best_w, best_r


def _merge_pairs(h, deadline):
    """Merge adjacent pairs (coarsen by factor 2) then re-polish.
    This gives a fresh structural perturbation different from a lift."""
    n = h.size
    if n < 8:
        return h
    if n % 2 == 0:
        hc = h[0::2] + h[1::2]
    else:
        hc = h[:-1:2] + h[1::2]
    hc = _rescale(hc)
    hc = _polish_ladder(hc, deadline - 0.5, betas=(1e6, 1e7, 0.0), iters=200)
    # re-expand by splitting back
    hr = np.repeat(hc, 2)
    hr = _rescale(hr)
    return hr


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase A: half-res quotient polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.16
        work_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_cR = r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, betas=(1e6, 1e7), iters=300)
        offer(h_lift, 'lift')

    # ---- Phase B: high-beta sharpening ladder ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0,
                            betas=(1e8, 1e9, 1e10, 0.0), iters=350)
        offer(ht, 'sharp')

    # ---- Phase B2: merge-pairs structural perturbation ----
    if time.process_time() < deadline - 6.0:
        hm = _merge_pairs(best, deadline - 3.0)
        offer(hm, 'merge-pairs')

    # ---- Phase C: multi-k interlaced lift with per-phase weights ----
    lift_deadline = deadline - 5.0
    if time.process_time() < lift_deadline - 2.0:
        best_lift = None
        best_liftR = -1.0
        best_lift_k = 1
        for k in (2, 3, 4):
            if best.size * k > 1000000:
                continue
            if time.process_time() > lift_deadline - 2.0:
                break
            w, r_w = _opt_weights(best, k, lift_deadline - 1.0, max_evals=50)
            hk = _rescale(_interlace(best, w))
            hk = _polish_ladder(hk, lift_deadline - 0.6,
                                betas=(1e6, 1e7, 0.0), iters=250)
            hk = _peak_ladder(hk, lift_deadline - 0.4,
                              pads=(0.10, 0.06, 0.04), iters=250)
            rk = R_of(hk)
            if rk > best_liftR:
                best_lift, best_liftR, best_lift_k = hk, rk, k
            print("lift%d weights=%s R=%.9f" % (k, np.round(w, 3), rk))
        if best_lift is not None and time.process_time() < deadline - 2.0:
            hfold = _rescale(_fold(best_lift, best_lift_k))
            hfold = _polish_ladder(hfold, deadline - 1.5, betas=(1e7, 0.0), iters=300)
            hfold = _peak_ladder(hfold, deadline - 1.0, pads=(0.08, 0.05), iters=300)
            rf = R_of(hfold)
            print("multi-k best k=%d R(3N)=%.9f R(fold)=%.9f"
                  % (best_lift_k, best_liftR, rf))
            if best_liftR >= rf:
                offer(best_lift, 'lift%d' % best_lift_k)
                offer(hfold, 'lift%d-fold-alt' % best_lift_k)
            else:
                offer(hfold, 'lift%d-fold' % best_lift_k)
                offer(best_lift, 'lift%d-alt' % best_lift_k)

    # ---- Phase D: final polish ----
    ht = _polish_ladder(best, deadline - 1.0, betas=(1e8, 0.0), iters=250)
    offer(ht, 'finalhi')
    ht = _peak_ladder(best, deadline - 0.6, pads=(0.06, 0.04), iters=300)
    offer(ht, 'finalpk')
    ht = _polish_ladder(best, deadline - 0.3, betas=(0.0,), iters=300)
    offer(ht, 'finalb0')

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _argmax_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    """CVaR-style: emphasize knots in the top-alpha band below max (shoulder)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    # weight knots in band [ (1-alpha)*mx, mx ], smooth via soft threshold
    thr = (1.0 - alpha) * mx
    w = np.clip((Lf - thr) / (alpha * mx + 1e-30), 0.0, 1.0)
    w = 0.5 * (1.0 - np.cos(np.pi * w))  # smooth ramp
    Z = w.sum()
    if Z <= 1e-12:
        return _fun_grad_tie(h)
    # weighted soft-max surrogate for the inf norm
    sm = (w * Lf).sum() / Z
    gLf = -dq / num + w / (Z * sm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fg, deadline, maxiter):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, frac=32):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = max(1, hi - lo)
    pad = max(8, span // frac)
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_window_polish(h, deadline, pad=3, frac=32, maxiter=60):
    if time.process_time() >= deadline - 0.3:
        return h
    win = _peak_window(h, frac=frac)
    if win.size == 0:
        return h
    active = win
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _coarsen(h, c, offset):
    n = h.size
    m = n // c
    if m < 1:
        return h.copy()
    start = offset
    end = start + m * c
    if end > n:
        m = (n - start) // c
        end = start + m * c
    if m < 1:
        return h.copy()
    seg = h[start:end].reshape(m, c)
    return seg.sum(axis=1) / c


def _prolongate(q, c, n):
    hp = np.repeat(q, c)
    if hp.size < n:
        hp = np.concatenate([hp, np.full(n - hp.size, hp[-1] if hp.size else 0.0)])
    return hp[:n]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)

    bestR = R_of(best)
    s01, s1, s5 = _shares(best)
    print("base R=%.9f N=%d shares 0.1/1/5%%=%.4f/%.4f/%.4f argmax=%.4f"
          % (bestR, best.size, s01, s1, s5, _argmax_frac(best)))

    start_best = best.copy()
    start_bestR = bestR

    def accept(cand, tag):
        nonlocal best, bestR
        if cand is None or cand.size != best.size or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            s01, s1, s5 = _shares(best)
            print("  %s R=%.9f shares 0.1/1/5%%=%.4f/%.4f/%.4f argmax=%.4f"
                  % (tag, bestR, s01, s1, s5, _argmax_frac(best)))
            return True
        return False

    alphas = [0.40, 0.25, 0.15, 0.08, 0.04]
    rnd = 0
    while time.process_time() < deadline - 1.0:
        rnd += 1
        # (i) CVaR ladder
        for a in alphas:
            if time.process_time() >= deadline - 1.0:
                break
            cand = _lbfgs(best, lambda h, aa=a: _fun_grad_cvar(h, aa),
                          deadline - 1.0, maxiter=50)
            accept(cand, "cvar a=%.2f" % a)
        # (ii) exact tie
        if time.process_time() < deadline - 1.0:
            cand = _lbfgs(best, _fun_grad_tie, deadline - 1.0, maxiter=60)
            accept(cand, "tie")
        # (iii) peak window
        if time.process_time() < deadline - 1.0:
            cand = _peak_window_polish(best, deadline - 1.0, pad=3, frac=32, maxiter=60)
            accept(cand, "peak")
        # (iv) offset-coarsen at stride 4 and 2
        for c in (4, 2):
            if time.process_time() >= deadline - 1.0:
                break
            for off in (0, 1):
                if time.process_time() >= deadline - 1.0:
                    break
                q = _coarsen(best, c, off)
                if q.size < 4:
                    continue
                q = _rescale(q)
                q = _lbfgs(q, lambda h: _fun_grad_cvar(h, 0.25),
                           deadline - 1.0, maxiter=40)
                hp = _prolongate(q, c, best.size)
                hp = _rescale(hp)
                hp = _lbfgs(hp, _fun_grad_tie, deadline - 1.0, maxiter=40)
                accept(hp, "coarse c=%d off=%d" % (c, off))
        if rnd >= 4:
            break

    # Final exact-tie polish + shrinking peak-window
    for frac in (16, 32, 64):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _lbfgs(best, _fun_grad_tie, deadline - 0.5, maxiter=80)
        accept(cand, "final tie")
        cand = _peak_window_polish(best, deadline - 0.5, pad=3, frac=frac, maxiter=80)
        accept(cand, "final peak frac=%d" % frac)

    if R_of(best) < start_bestR:
        best = start_best
        bestR = start_bestR

    s01, s1, s5 = _shares(best)
    print("final R=%.9f (start %.9f, N=%d, shares 0.1/1/5%%=%.4f/%.4f/%.4f, argmax=%.4f)"
          % (bestR, start_bestR, best.size, s01, s1, s5, _argmax_frac(best)))

    result = {"best": best}
    if R_of(best) < start_bestR - 1e-14:
        result["alternative"] = best
    return result

