def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    m = min(m, Lf.size)
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _coarsen_offset(h, c, o):
    n = h.size
    if o > 0:
        hh = np.concatenate([np.zeros(o), h])
    else:
        hh = h
    m = (hh.size + c - 1) // c
    pad = m * c - hh.size
    if pad > 0:
        hh = np.concatenate([hh, np.zeros(pad)])
    q = hh.reshape(m, c).sum(axis=1) / c
    return q, o


def _refine_offset(q, c, o, N):
    hr = np.repeat(q, c)
    if o > 0:
        hr = hr[o:]
    if hr.size < N:
        hr = np.concatenate([hr, np.zeros(N - hr.size)])
    elif hr.size > N:
        hr = hr[:N]
    return hr


def _shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(L >= mx * 0.999), np.mean(L >= mx * 0.99),
            np.mean(L >= mx * 0.95))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    loop_deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    N = best.size
    s1, s2, s3 = _shares(best)
    print("base R=%.12f (N=%d) shares %.4f/%.4f/%.4f" % (bestR, N, s1, s2, s3))

    alt_best = None
    altR = -1.0

    def consider(cand, tag):
        nonlocal best, bestR, alt_best, altR
        cand = _rescale(np.clip(cand, 0, None))
        r = R_of(cand)
        if r > altR:
            altR, alt_best = r, cand.copy()
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
            s1, s2, s3 = _shares(best)
            L = _knots(best)
            am = float(np.argmax(L)) / max(1, L.size - 1)
            print("%s R=%.12f shares %.4f/%.4f/%.4f argmax %.3f"
                  % (tag, r, s1, s2, s3, am))
            return True
        return False

    def time_left():
        return deadline - time.process_time()

    def loop_left():
        return loop_deadline - time.process_time()

    def peak_polish(h, tag):
        # shrinking peak-window polish in log space
        cur = h.copy()
        curR = R_of(cur)
        for pad_div in (16, 32, 64):
            if time_left() < 2.0:
                break
            L = _knots(cur)
            j = int(np.argmax(L))
            half = max(8, N // pad_div)
            lo = max(0, j - 1 - half)
            hi = min(N, j - 1 + half)
            if hi <= lo:
                continue
            sub = cur[lo:hi].copy()
            if sub.sum() <= 0:
                continue
            # work in log space on positive entries
            eps = 1e-12
            subp = np.clip(sub, eps, None)
            logsub = np.log(subp)

            def fg(z):
                hh = np.exp(z)
                val, g = _fun_grad_tie(hh)
                return val, g * hh

            cb = _make_cb(deadline - 0.3)
            try:
                res = minimize(fg, logsub, jac=True, method='L-BFGS-B',
                               bounds=[(-30.0, 30.0)] * logsub.size,
                               callback=cb,
                               options={'maxiter': 60, 'maxfun': 120,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                newsub = np.exp(res.x)
            except (TimeoutError, Exception):
                continue
            h2 = cur.copy()
            h2[lo:hi] = newsub
            h2 = _rescale(np.clip(h2, 0, None))
            r2 = R_of(h2)
            if r2 > curR + 1e-15:
                cur, curR = h2, r2
        consider(cur, tag)

    # ---- main loop ----
    it = 0
    while loop_left() > 1.0:
        it += 1
        improved = False

        # (i) moderate-alpha CVaR ladder at full N
        h = best.copy()
        for a in (0.30, 0.18, 0.10):
            if time_left() < 1.5:
                break
            h = _lbfgs(h, lambda hh, aa=a: _fun_grad_cvar(hh, aa),
                       deadline - 0.8, maxiter=60)
        if consider(h, "it%d cvar-ladder" % it):
            improved = True

        # (ii) exact-tie polish
        if time_left() > 1.5:
            h = _lbfgs(best, _fun_grad_tie, deadline - 0.8, maxiter=60)
            if consider(h, "it%d tie" % it):
                improved = True

        # (iii) offset coarsen at stride 4 and 2, CVaR alpha=0.18, prolongate, tie
        for c, offs in ((4, (0, 1, 2, 3)), (2, (0, 1))):
            if time_left() < 2.0:
                break
            for o in offs:
                if time_left() < 1.5:
                    break
                q, oo = _coarsen_offset(best, c, o)
                if q.size < 16:
                    continue
                q = _lbfgs(q, lambda hh: _fun_grad_cvar(hh, 0.18),
                           deadline - 0.8, maxiter=40)
                hr = _refine_offset(q, c, oo, N)
                if time_left() > 1.5:
                    hr = _lbfgs(hr, _fun_grad_tie, deadline - 0.8, maxiter=30)
                if consider(hr, "it%d c=%d o=%d" % (it, c, o)):
                    improved = True

        # (iv) shrinking peak-window polish
        if time_left() > 2.0:
            peak_polish(best, "it%d peak" % it)

        if not improved and time_left() < 3.0:
            break

    # ---- remainder: cycle tie polish ----
    while time_left() > 1.0:
        h = _lbfgs(best, _fun_grad_tie, deadline - 0.5, maxiter=80)
        if not consider(h, "tie-cycle"):
            break

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    s1, s2, s3 = _shares(best)
    print("final R=%.12f (start %.12f, N=%d) shares %.4f/%.4f/%.4f"
          % (bestR, startR, best.size, s1, s2, s3))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---------- Hessian-vector via analytic-adjoint FD of gradient ----------

def _hess_vec(h, g, eps, deadline, fg):
    if time.process_time() >= deadline - 0.5:
        return np.zeros(h.size)
    hp = np.clip(h + eps * g, 0.0, None)
    _, gp = fg(hp)
    if time.process_time() >= deadline - 0.5:
        return np.zeros(h.size)
    hm = np.clip(h - eps * g, 0.0, None)
    _, gm = fg(hm)
    return (gp - gm) / (2.0 * eps)


def _newton_cg_step(h, grad, Delta, deadline, fg, max_cg=25, tol=1e-8):
    n = h.size
    gnorm = np.linalg.norm(grad)
    if gnorm < 1e-14:
        return np.zeros(n), 0.0, False
    hscale = max(np.mean(np.abs(h)), 1e-12)
    eps = 1e-6 * hscale / max(gnorm, 1e-12)
    eps = max(min(eps, 1e-4 * hscale), 1e-12)

    s = np.zeros(n)
    r = -grad.copy()
    p = r.copy()
    rr = float(r @ r)
    min_curv = 0.0
    ok = True
    for it in range(max_cg):
        if time.process_time() >= deadline - 0.5:
            ok = False
            break
        Hp = _hess_vec(h, p, eps, deadline, fg)
        pHp = float(p @ Hp)
        if pHp < min_curv:
            min_curv = pHp
        if pHp <= 1e-14:
            pnorm = np.linalg.norm(p)
            if pnorm < 1e-16:
                break
            tau = Delta / pnorm
            s = s + tau * p
            ok = True
            break
        alpha = rr / pHp
        s_new = s + alpha * p
        if np.linalg.norm(s_new) >= Delta:
            pnorm = np.linalg.norm(p)
            snorm = np.linalg.norm(s)
            a = pnorm * pnorm
            b = 2.0 * float(s @ p)
            c = snorm * snorm - Delta * Delta
            disc = b * b - 4 * a * c
            if disc < 0:
                disc = 0.0
            tau = (-b + np.sqrt(disc)) / (2 * a)
            if tau < 0:
                tau = (-b - np.sqrt(disc)) / (2 * a)
            s = s + tau * p
            break
        s = s_new
        r = r - alpha * Hp
        rr_new = float(r @ r)
        if rr_new < tol * tol * gnorm * gnorm:
            break
        beta = rr_new / rr
        p = r + beta * p
        rr = rr_new
    return s, min_curv, ok


def _newton_trust_region(h0, deadline, Delta0, max_outer=300, beta=0.0, tie=True):
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else (
        _fun_grad_tie if tie else _fun_grad)
    h = _rescale(np.clip(h0, 0, None))
    bestR = R_of(h)
    best = h.copy()
    Delta = Delta0
    shrink = 0
    for outer in range(max_outer):
        if time.process_time() >= deadline - 1.0:
            break
        val, grad = fg(h)
        gproj = grad.copy()
        gproj[(h <= 1e-15) & (gproj > 0)] = 0.0
        gnorm = np.linalg.norm(gproj)
        if gnorm < 1e-12:
            break
        step, min_curv, ok = _newton_cg_step(h, gproj, Delta, deadline, fg)
        if not ok:
            break
        if np.linalg.norm(step) < 1e-16:
            break
        h_new = _rescale(np.clip(h + step, 0.0, None))
        newR = R_of(h_new)
        accepted = newR >= bestR - 1e-15
        if accepted:
            h = h_new
            if newR > bestR:
                bestR = newR
                best = h.copy()
            shrink = 0
            Delta = min(Delta * 1.5, Delta0 * 100.0)
        else:
            shrink += 1
            Delta *= 0.5
            if Delta < 1e-12 or shrink > 12:
                break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    print("frac near max (0.1%%) before: %.4f" % _frac_near_max(best, 1e-3))

    alt_best = None
    altR = -1.0

    # Stage 1: smooth beta-objective Newton-CG (annealed). This is the new idea:
    # instead of a hard max / exact tie-average, run the same trust-region Newton
    # on a soft-max with increasing beta. It gently rounds the peak and lets
    # the broad base co-optimise, escaping the degenerate tie plateau.
    if time.process_time() < deadline - 20.0:
        Delta0 = 1e-4 * max(np.mean(np.abs(best)), 1e-12)
        hb = best.copy()
        rB = bestR
        for beta in (50.0, 200.0, 800.0, 3000.0):
            if time.process_time() >= deadline - 15.0:
                break
            sub_dl = min(deadline - 12.0,
                         time.process_time() + max(2.0, (deadline - time.process_time() - 12.0) / 2.0))
            nb, nr = _newton_trust_region(hb, sub_dl, Delta0, max_outer=80,
                                          beta=beta, tie=False)
            # verify with true tie objective
            pol = _lbfgs_block(nb, np.arange(nb.size), 60,
                               min(deadline - 10.0, time.process_time() + 3.0),
                               tie=True)
            rp = R_of(pol)
            print("  beta=%.0f newton R=%.12f polish R=%.12f (best %.12f)"
                  % (beta, nr, rp, bestR))
            if rp > rB:
                rB, hb = rp, pol.copy()
            if rp > bestR + 1e-15:
                best, bestR = pol.copy(), rp
            elif rp > altR:
                altR, alt_best = rp, pol.copy()

    # Stage 2: hard tie-average Newton-CG polish from current best.
    if time.process_time() < deadline - 8.0:
        Delta0 = 1e-5 * max(np.mean(np.abs(best)), 1e-12)
        nb, nr = _newton_trust_region(best, deadline - 4.0, Delta0,
                                      max_outer=200, tie=True)
        print("tie newton: R=%.12f (best %.12f)" % (nr, bestR))
        if nr > bestR + 1e-15:
            best, bestR = nb.copy(), nr
        elif nr > altR:
            altR, alt_best = nr, nb.copy()

    # Stage 3: final tie LBFGS safety net.
    if time.process_time() < deadline - 2.0:
        pol = _lbfgs_block(best, np.arange(best.size), 300,
                           min(deadline - 1.0, time.process_time() + 4.0),
                           tie=True)
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR > 0 and altR < bestR - 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None and alt_best is not None:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
