    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.14, 0.09, 0.06, 0.04), iters=400):
    best = h.copy()
    bestR = R_of(best)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2, r2
    return best, bestR


def _half_polish(c, bestR, deadline):
    best = c.copy()
    work = c.copy()
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
    for pad in [0.30, 0.20, 0.14, 0.10, 0.06]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
    return work, best, bestR


def _extract(c_full, k, m):
    if k == 0:
        c = c_full[0::2][:m].copy()
    elif k == 1:
        c = c_full[1::2][:m].copy()
    else:
        a = c_full[0::2][:m]
        b = c_full[1::2][:m]
        L = min(a.size, b.size)
        c = 0.5 * (a[:L] + b[:L])
        if c.size < m:
            c = np.concatenate((c, np.full(m - c.size, c[-1])))
    return c


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _block_refine(h0, deadline, rounds=6):
    """Refine by repeatedly polishing peak window with growing tolerance."""
    best = h0.copy()
    bestR = R_of(best)
    for tol in (0.999, 0.99, 0.97, 0.95, 0.92):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, tol=tol, pad_frac=0.25, extra=256)
        ht = _lbfgs_block(best, win, 300, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-15:
                best, bestR = ht2, r2
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR = _half_polish(work_c, best_cR, half_deadline)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: rotation of extract/lift cycles (all three variants) ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 8.0
        max_cycles = 9
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 6.0, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            c = _extract(wk, k, m)
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR = _half_polish(c, cR0, slice_dl)
            except Exception:
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception:
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: structural edits (split/merge/move) ----
    struct_end = deadline - 5.0
    if time.process_time() < struct_end - 1.0 and best.size >= 4:
        Ns = best.size
        rng = np.random.RandomState(424242)
        trial = 0
        accepted = 0
        while time.process_time() < struct_end - 1.0:
            act = np.flatnonzero(best > 0.02 * best.max())
            if act.size == 0:
                break
            perm = rng.permutation(act)
            progressed = False
            for i in perm:
                i = int(i)
                if time.process_time() >= struct_end - 1.0:
                    break
                now = time.process_time()
                slice_dl = min(now + 1.2, deadline - 5.0)
                if slice_dl <= now + 0.3:
                    break
                trial += 1
                cands = []
                v = best[i]
                if v > 0:
                    for d in (-1, +1, -2, +2):
                        j = i + d
                        if 0 <= j < Ns and best[j] <= 0:
                            h2 = best.copy()
                            h2[i] = 0.0
                            h2[j] = h2[j] + v
                            cands.append(('move%d' % d, h2))
                            break
                if i + 1 < Ns:
                    h2 = best.copy()
                    half = 0.5 * best[i]
                    h2[i] = half
                    h2[i + 1] = h2[i + 1] + half
                    cands.append(('split', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    a = best[i] * (1.0 / 3.0)
                    h2[i] = a
                    h2[i + 1] = h2[i + 1] + (best[i] - a)
                    cands.append(('split2', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    h2[i] = h2[i] + h2[i + 1]
                    h2[i + 1] = 0.0
                    cands.append(('merge', h2))
                best_local = None
                best_localR = -1.0
                best_type = None
                for typ, h2 in cands:
                    if time.process_time() >= slice_dl - 0.3:
                        break
                    h2 = _rescale(np.clip(h2, 0, None))
                    win = _peak_window(h2, pad_frac=0.15, extra=384)
                    h2 = _lbfgs_block(h2, win, 120, slice_dl, beta=1e6)
                    if time.process_time() < slice_dl - 0.3:
                        h2 = _lbfgs_all_pos(h2, 120, slice_dl, beta=1e7)
                    r2 = R_of(h2)
                    if r2 > best_localR:
                        best_local, best_localR, best_type = h2, r2, typ
                if best_local is None:
                    continue
                progressed = True
                if best_localR > bestR + 1e-13:
                    best, bestR = best_local.copy(), best_localR
                    origin = 'struct_%s' % best_type
                    accepted += 1
                    print("struct trial %d %s at i=%d NEW BEST R=%.9f" %
                          (trial, best_type, i, bestR))
                elif best_localR > alt_bestR:
                    alt_best, alt_bestR = best_local.copy(), best_localR
            if not progressed:
                break
        print("struct edits done trials=%d accepted=%d bestR=%.9f" %
              (trial, accepted, bestR))

    # ---- Phase 4: final ladder polish + block refine ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _peak_ladder(best, deadline)
    if time.process_time() < deadline - 1.0:
        best2, bestR2 = _block_refine(best, deadline)
        if bestR2 > bestR + 1e-15:
            best, bestR = best2, bestR2
            origin = origin + '+refine'

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.14, 0.09, 0.06, 0.04), iters=400):
    best = h.copy()
    bestR = R_of(best)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2, r2
    return best, bestR


def _half_polish(c, bestR, deadline):
    best = c.copy()
    work = c.copy()
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
    for pad in [0.30, 0.20, 0.14, 0.10, 0.06]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
    return work, best, bestR


def _extract(c_full, k, m):
    if k == 0:
        c = c_full[0::2][:m].copy()
    elif k == 1:
        c = c_full[1::2][:m].copy()
    else:
        a = c_full[0::2][:m]
        b = c_full[1::2][:m]
        L = min(a.size, b.size)
        c = 0.5 * (a[:L] + b[:L])
        if c.size < m:
            c = np.concatenate((c, np.full(m - c.size, c[-1])))
    return c


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _block_refine(h0, deadline, rounds=6):
    """Refine by repeatedly polishing peak window with growing tolerance."""
    best = h0.copy()
    bestR = R_of(best)
    for tol in (0.999, 0.99, 0.97, 0.95, 0.92):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, tol=tol, pad_frac=0.25, extra=256)
        ht = _lbfgs_block(best, win, 300, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-15:
                best, bestR = ht2, r2
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR = _half_polish(work_c, best_cR, half_deadline)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: rotation of extract/lift cycles (all three variants) ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 8.0
        max_cycles = 9
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 6.0, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            c = _extract(wk, k, m)
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR = _half_polish(c, cR0, slice_dl)
            except Exception:
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception:
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: structural edits (split/merge/move) ----
    struct_end = deadline - 5.0
    if time.process_time() < struct_end - 1.0 and best.size >= 4:
        Ns = best.size
        rng = np.random.RandomState(424242)
        trial = 0
        accepted = 0
        while time.process_time() < struct_end - 1.0:
            act = np.flatnonzero(best > 0.02 * best.max())
            if act.size == 0:
                break
            perm = rng.permutation(act)
            progressed = False
            for i in perm:
                i = int(i)
                if time.process_time() >= struct_end - 1.0:
                    break
                now = time.process_time()
                slice_dl = min(now + 1.2, deadline - 5.0)
                if slice_dl <= now + 0.3:
                    break
                trial += 1
                cands = []
                v = best[i]
                if v > 0:
                    for d in (-1, +1, -2, +2):
                        j = i + d
                        if 0 <= j < Ns and best[j] <= 0:
                            h2 = best.copy()
                            h2[i] = 0.0
                            h2[j] = h2[j] + v
                            cands.append(('move%d' % d, h2))
                            break
                if i + 1 < Ns:
                    h2 = best.copy()
                    half = 0.5 * best[i]
                    h2[i] = half
                    h2[i + 1] = h2[i + 1] + half
                    cands.append(('split', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    a = best[i] * (1.0 / 3.0)
                    h2[i] = a
                    h2[i + 1] = h2[i + 1] + (best[i] - a)
                    cands.append(('split2', h2))
                if i + 1 < Ns:
                    h2 = best.copy()
                    h2[i] = h2[i] + h2[i + 1]
                    h2[i + 1] = 0.0
                    cands.append(('merge', h2))
                best_local = None
                best_localR = -1.0
                best_type = None
                for typ, h2 in cands:
                    if time.process_time() >= slice_dl - 0.3:
                        break
                    h2 = _rescale(np.clip(h2, 0, None))
                    win = _peak_window(h2, pad_frac=0.15, extra=384)
                    h2 = _lbfgs_block(h2, win, 120, slice_dl, beta=1e6)
                    if time.process_time() < slice_dl - 0.3:
                        h2 = _lbfgs_all_pos(h2, 120, slice_dl, beta=1e7)
                    r2 = R_of(h2)
                    if r2 > best_localR:
                        best_local, best_localR, best_type = h2, r2, typ
                if best_local is None:
                    continue
                progressed = True
                if best_localR > bestR + 1e-13:
                    best, bestR = best_local.copy(), best_localR
                    origin = 'struct_%s' % best_type
                    accepted += 1
                    print("struct trial %d %s at i=%d NEW BEST R=%.9f" %
                          (trial, best_type, i, bestR))
                elif best_localR > alt_bestR:
                    alt_best, alt_bestR = best_local.copy(), best_localR
            if not progressed:
                break
        print("struct edits done trials=%d accepted=%d bestR=%.9f" %
              (trial, accepted, bestR))

    # ---- Phase 4: final ladder polish + block refine ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _peak_ladder(best, deadline)
    if time.process_time() < deadline - 1.0:
        best2, bestR2 = _block_refine(best, deadline)
        if bestR2 > bestR + 1e-15:
            best, bestR = best2, bestR2
            origin = origin + '+refine'

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    m = min(m, Lf.size)
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_shoulder(h, hi_frac=0.30, lo_frac=0.005):
    # CVaR over knots in top hi_frac but outside top lo_frac of max
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    hi = mx * (1.0 - hi_frac)
    lo = mx * (1.0 - lo_frac)
    mask = (Lf >= hi) & (Lf < lo)
    S = np.flatnonzero(mask)
    if S.size == 0:
        # fall back to a thin band just below the top
        S = np.flatnonzero(Lf >= mx * (1.0 - hi_frac))
        if S.size == 0:
            return _fun_grad_tie(h)
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    m = S.size
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _coarsen_offset(h, c, o):
    n = h.size
    if o > 0:
        hh = np.concatenate([np.zeros(o), h])
    else:
        hh = h
    m = (hh.size + c - 1) // c
    pad = m * c - hh.size
    if pad > 0:
        hh = np.concatenate([hh, np.zeros(pad)])
    q = hh.reshape(m, c).sum(axis=1) / c
    return q, o


def _refine_offset(q, c, o, N):
    hr = np.repeat(q, c)
    if o > 0:
        hr = hr[o:]
    if hr.size < N:
        hr = np.concatenate([hr, np.zeros(N - hr.size)])
    elif hr.size > N:
        hr = hr[:N]
    return hr


def _shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(L >= mx * 0.999), np.mean(L >= mx * 0.99),
            np.mean(L >= mx * 0.95))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    loop_deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    N = best.size
    s1, s2, s3 = _shares(best)
    print("base R=%.12f (N=%d) shares %.4f/%.4f/%.4f" % (bestR, N, s1, s2, s3))

    alt_best = None
    altR = -1.0

    def consider(cand, tag):
        nonlocal best, bestR, alt_best, altR
        cand = _rescale(np.clip(cand, 0, None))
        r = R_of(cand)
        if r > altR:
            altR, alt_best = r, cand.copy()
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
            s1, s2, s3 = _shares(best)
            L = _knots(best)
            am = float(np.argmax(L)) / max(1, L.size - 1)
            print("%s R=%.12f shares %.4f/%.4f/%.4f argmax %.3f"
                  % (tag, r, s1, s2, s3, am))
            return True
        return False

    def time_left():
        return deadline - time.process_time()

    def loop_left():
        return loop_deadline - time.process_time()

    def peak_polish(h, tag):
        cur = h.copy()
        curR = R_of(cur)
        for pad_div in (16, 32, 64):
            if time_left() < 2.0:
                break
            L = _knots(cur)
            j = int(np.argmax(L))
            half = max(8, N // pad_div)
            lo = max(0, j - 1 - half)
            hi = min(N, j - 1 + half)
            if hi <= lo:
                continue
            sub = cur[lo:hi].copy()
            if sub.sum() <= 0:
                continue
            eps = 1e-12
            subp = np.clip(sub, eps, None)
            logsub = np.log(subp)

            def fg(z):
                hh = np.exp(z)
                val, g = _fun_grad_tie(hh)
                return val, g * hh

            cb = _make_cb(deadline - 0.3)
            try:
                res = minimize(fg, logsub, jac=True, method='L-BFGS-B',
                               bounds=[(-30.0, 30.0)] * logsub.size,
                               callback=cb,
                               options={'maxiter': 60, 'maxfun': 120,
                                        'ftol': 1e-20, 'gtol': 1e-16})
                newsub = np.exp(res.x)
            except (TimeoutError, Exception):
                continue
            h2 = cur.copy()
            h2[lo:hi] = newsub
            h2 = _rescale(np.clip(h2, 0, None))
            r2 = R_of(h2)
            if r2 > curR + 1e-15:
                cur, curR = h2, r2
        consider(cur, tag)

    def shoulder_polish(h, tag):
        # shoulder-band CVaR in log space on active cells
        cur = h.copy()
        curR = R_of(cur)
        if time_left() < 2.0:
            return
        act = np.flatnonzero(cur > 1e-12)
        if act.size == 0:
            return
        sub = cur[act].copy()
        logsub = np.log(sub)

        def fg(z):
            hh = np.zeros_like(cur)
            hh[act] = np.exp(z)
            val, g = _fun_grad_shoulder(hh)
            return val, g[act] * np.exp(z)

        cb = _make_cb(deadline - 0.3)
        try:
            res = minimize(fg, logsub, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * logsub.size,
                           callback=cb,
                           options={'maxiter': 60, 'maxfun': 120,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            newsub = np.exp(res.x)
        except (TimeoutError, Exception):
            return
        h2 = cur.copy()
        h2[act] = newsub
        h2 = _rescale(np.clip(h2, 0, None))
        r2 = R_of(h2)
        if r2 > curR + 1e-15:
            cur, curR = h2, r2
        consider(cur, tag)

    # ---- main loop ----
    it = 0
    while loop_left() > 1.0:
        it += 1
        improved = False

        # (i) moderate-alpha CVaR ladder at full N
        h = best.copy()
        for a in (0.30, 0.18, 0.10):
            if time_left() < 1.5:
                break
            h = _lbfgs(h, lambda hh, aa=a: _fun_grad_cvar(hh, aa),
                       deadline - 0.8, maxiter=60)
        if consider(h, "it%d cvar-ladder" % it):
            improved = True

        # (ii) exact-tie polish
        if time_left() > 1.5:
            h = _lbfgs(best, _fun_grad_tie, deadline - 0.8, maxiter=60)
            if consider(h, "it%d tie" % it):
                improved = True

        # (iii) shoulder-band CVaR polish
        if time_left() > 2.0:
            shoulder_polish(best, "it%d shoulder" % it)

        # (iv) offset coarsen at stride 4 and 2, CVaR alpha=0.18, prolongate, tie
        for c, offs in ((4, (0, 1, 2, 3)), (2, (0, 1))):
            if time_left() < 2.0:
                break
            for o in offs:
                if time_left() < 1.5:
                    break
                q, oo = _coarsen_offset(best, c, o)
                if q.size < 16:
                    continue
                q = _lbfgs(q, lambda hh: _fun_grad_cvar(hh, 0.18),
                           deadline - 0.8, maxiter=40)
                hr = _refine_offset(q, c, oo, N)
                if time_left() > 1.5:
                    hr = _lbfgs(hr, _fun_grad_tie, deadline - 0.8, maxiter=30)
                if consider(hr, "it%d c=%d o=%d" % (it, c, o)):
                    improved = True

        # (v) shrinking peak-window polish
        if time_left() > 2.0:
            peak_polish(best, "it%d peak" % it)

        if not improved and time_left() < 3.0:
            break

    # ---- remainder: cycle tie + shoulder polish ----
    while time_left() > 1.0:
        h = _lbfgs(best, _fun_grad_tie, deadline - 0.5, maxiter=80)
        got = consider(h, "tie-cycle")
        if time_left() > 1.5:
            shoulder_polish(best, "shoulder-cycle")
        if not got:
            break

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    s1, s2, s3 = _shares(best)
    print("final R=%.12f (start %.12f, N=%d) shares %.4f/%.4f/%.4f"
          % (bestR, startR, best.size, s1, s2, s3))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _edge_extend_pow(h, K, p):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    n = h.size
    mx = h.max()
    if mx <= 0:
        return h
    thr = 1e-9 * mx
    idx = np.flatnonzero(h > thr)
    if idx.size == 0:
        return h
    i0 = int(idx.min()); i1 = int(idx.max())
    hL = h[i0]; hR = h[i1]
    for k in range(1, K + 1):
        w = (1.0 + k) ** (-p)
        if i0 - k >= 0 and h[i0 - k] == 0.0:
            h[i0 - k] = hL * w
        if i1 + k < n and h[i1 + k] == 0.0:
            h[i1 + k] = hR * w
    return _rescale(h)


def _run_cycle(work, best, bestR, deadline, origin, tag=""):
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    pads = [0.30, 0.20, 0.30, 0.15, 0.25, 0.12, 0.20, 0.10, 0.18, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _random_perturb(h, rng, amp):
    h = np.clip(np.asarray(h, dtype=float).copy(), 0, None)
    nz = h > 0
    noise = np.exp(amp * rng.standard_normal(h.size))
    h[nz] *= noise[nz]
    return _rescale(h)


def _cheap_cycle(seed, deadline, tag=""):
    work = seed.copy()
    best = seed.copy()
    bestR = R_of(seed)
    origin = tag + "seed"
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.15, 0.08]):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 250, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
    if time.process_time() < deadline - 0.6:
        ht2 = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=0.0)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            work, best, bestR = ht2, ht2.copy(), r2
            origin = "%sall0" % tag
    return best, bestR, origin


def _interp_resize(h, Nnew):
    """Resample a step function to Nnew steps, preserving mass & shape."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n == Nnew:
        return h.copy()
    xold = (np.arange(n) + 0.5) / n
    xnew = (np.arange(Nnew) + 0.5) / Nnew
    hn = np.interp(xnew, xold, h, left=0.0, right=0.0)
    return hn


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # NEW IDEA: resolution-upsampling move.  Re-express the current
    # construction on a finer grid (interpolation preserves the shape but
    # gives the optimiser more freedom to refine cell boundaries), then
    # polish.  This is a genuinely different construction from `start`.
    rng = np.random.default_rng(20240607)

    if time.process_time() < deadline - 4.0 and best.size < 900000:
        Nup = min(900000, int(best.size * 1.5) + 4096)
        up = _interp_resize(best, Nup)
        up = _rescale(up)
        r_up = R_of(up)
        w, b, br, org = _run_cycle(up, up.copy(), r_up, deadline, 'up')
        if br > bestR + 1e-14:
            best, bestR, origin = b, br, org
        elif br > alt_bestR:
            alt_best, alt_bestR = b, br
        print("upsample(%d->%d): R=%.9f (best %.9f)" %
              (start_best.size, Nup, br, bestR))

    # Phase A: baseline full cycle on current best.
    if time.process_time() < deadline - 1.0:
        work0, best0, bestR0, origin0 = _run_cycle(
            best.copy(), best.copy(), bestR, deadline, 'base')
        if bestR0 > bestR + 1e-14:
            best, bestR, origin = best0, bestR0, origin0
        print("baseline cycle: R=%.9f origin=%s" % (bestR, origin))

    # Phase B: cheap perturb->polish->accept loop.
    lo = np.log(0.003)
    hi = np.log(0.05)
    n_trials = 0
    while time.process_time() < deadline - 6.0 and n_trials < 8:
        amp = float(np.exp(rng.uniform(lo, hi)))
        seed = _random_perturb(best, rng, amp)
        r_seed = R_of(seed)
        b, br, org = _cheap_cycle(seed, deadline, tag='t%d' % n_trials)
        improved = br > bestR + 1e-14
        if improved:
            best, bestR, origin = b, br, org
        if br > alt_bestR and not improved:
            alt_best, alt_bestR = b, br
        print("trial%d amp=%.4f seedR=%.9f postR=%.9f %s (best %.9f)" %
              (n_trials, amp, r_seed, br, "NEW BEST" if improved else "", bestR))
        n_trials += 1

    # Phase C: power-law edge extension sweep.
    if time.process_time() < deadline - 2.0:
        for (K, p) in [(2048, 3.0), (2048, 2.0)]:
            if time.process_time() >= deadline - 1.0:
                break
            ext = _edge_extend_pow(best, K, p)
            r_ext = R_of(ext)
            w, b, br, org = _run_cycle(ext, ext.copy(), r_ext, deadline,
                                       'pow%d_%g' % (K, p))
            if br > bestR + 1e-14:
                best, bestR, origin = b, br, org
            elif br > alt_bestR:
                alt_best, alt_bestR = b, br

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _block_upsample(v, m, N):
    """Expand block values v (each of width m) to a length-N array."""
    M = len(v)
    h = np.empty(N)
    for j in range(M):
        lo = j * m; hi = min(N, (j + 1) * m)
        h[lo:hi] = v[j]
    return h


def _block_refine(v, m, N, deadline, iters=40):
    """Coordinate-wise refinement of block levels (multiplicative) on coarse grid."""
    M = len(v)
    v = np.clip(v.copy(), 1e-12, None)

    def obj(vv):
        h = _block_upsample(vv, m, N)
        return -R_of(h)

    best = v.copy()
    bR = R_of(_block_upsample(v, m, N))
    step = 0.3
    for it in range(iters):
        if time.process_time() > deadline - 0.5:
            break
        improved = False
        for j in range(M):
            for sgn in (1.0, -1.0):
                vt = best.copy()
                vt[j] *= np.exp(sgn * step)
                R = R_of(_block_upsample(vt, m, N))
                if R > bR:
                    best = vt; bR = R; improved = True
                    break
        if not improved:
            step *= 0.5
            if step < 1e-4:
                break
    return best, bR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # --- Approach A: coarse block search on a downsampled grid, then upsample ---
    alt = None
    altR = -1.0
    N = best.size

    # Try several downsampling factors; block-average the start
    for fac in (8, 4, 16):
        if time.process_time() > deadline - 3.0:
            break
        if N % fac != 0:
            continue
        M = N // fac
        if M < 16 or M > 4000:
            continue
        v0 = np.array([best[j * fac:(j + 1) * fac].mean() for j in range(M)])
        v0 = np.clip(v0, 1e-12, None)
        tlim = min(deadline - 1.0, time.process_time() + 4.0)
        v1, R1 = _block_refine(v0, fac, N, tlim, iters=60)
        print("block fac=%d R=%.9f (start %.9f)" % (fac, R1, startR))
        if R1 > bestR:
            hb = _rescale(_block_upsample(v1, fac, N))
            # Polish with full L-BFGS
            if time.process_time() < deadline - 1.0:
                tlim = min(deadline - 1.0, time.process_time() + 10.0)
                hp = _full_lbfgs(hb, tlim, maxiter=200)
                Rp = R_of(hp)
                if Rp > R1:
                    hb = hp; R1 = Rp
            if R1 > bestR:
                best = hb; bestR = R1
                print("ACCEPT block fac=%d: %.9f" % (fac, R1))
            else:
                if alt is None or R1 > altR:
                    alt = hb; altR = R1

    # --- Approach B: peak window polish on a finer scale ---
    if time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.0, time.process_time() + 6.0)
        hp = _peak_window_polish(best, tlim, pad=5, frac=6)
        Rp = R_of(hp)
        if Rp > bestR:
            print("peak polish improved: %.9f" % Rp)
            best = hp; bestR = Rp

    # --- Approach C: fill loop with CVaR + full polish ---
    alphas = [0.0001, 0.00003, 0.0003]
    k = 0
    while time.process_time() < deadline - 1.0:
        alpha = alphas[k % len(alphas)]
        k += 1
        tlim = min(deadline - 1.0, time.process_time() + 2.5)
        hc = _lbfgs_custom(best, lambda hh: _fun_grad_cvar(hh, alpha),
                           tlim, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 1.5)
            hc = _full_lbfgs(hc, tlim2, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim3 = min(deadline - 1.0, time.process_time() + 1.0)
            hc = _peak_window_polish(hc, tlim3, pad=3, frac=8)
        rc = R_of(hc)
        print("fill a=%.5f R=%.9f (best %.9f)" % (alpha, rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if alt is not None and altR > 0 and alt is not best:
        return {"best": best, "alternative": alt}
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


# ---- smooth extension: add a small offset to all heights and optimise ----
# The key idea: the optimizer gets stuck on the boundary of the
# non-negativity constraint.  Adding a tiny uniform offset (regularisation)
# keeps every coordinate strictly interior, so L-BFGS-B can move them freely
# and escape the plateau.  We then rescale after each step and only keep the
# result if R actually improved.

def _smooth_polish(h, deadline, rounds=6, offset_frac=2e-3, maxiter=600):
    """Repeatedly add a small uniform offset, L-BFGS on all coordinates,
    and keep the best.  The offset is proportional to the mean positive
    height so it stays scale-invariant."""
    best = h.copy()
    bestR = R_of(best)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.4:
            break
        pos = best[best > 0]
        if pos.size == 0:
            break
        eps = offset_frac * pos.mean()
        hs = best + eps
        ht = _lbfgs_all_pos(hs, maxiter, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht, r
            # shrink the offset as we converge
            offset_frac *= 0.5
        else:
            # if no gain, try a larger offset to break out
            offset_frac *= 1.5
            if offset_frac > 0.2:
                break
    return best, bestR


def _move_shift(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.35) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    s = int(rng.choice([-3, -2, -1, 1, 2, 3]))
    h = np.zeros_like(best)
    if s > 0:
        h[:lo] = best[:lo]
        hi_end = min(n, lo + w + s)
        h[lo + s:hi_end] = best[lo:hi_end - s]
        if hi_end < n:
            h[hi_end:] = best[hi_end:]
    else:
        d = -s
        h[:max(0, lo - d)] = best[:max(0, lo - d)]
        start_dst = max(0, lo - d)
        start_src = start_dst + d
        end = min(n, lo + w - d)
        if end > start_dst:
            h[start_dst:end] = best[start_src:start_src + (end - start_dst)]
        if lo + w < n:
            h[lo + w:] = best[lo + w:]
    return h, ("SHIFT", s, lo, w)


def _move_mirror(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.35) * n)
    w = max(1, min(w, n))
    lo = int(rng.integers(0, n - w + 1))
    h = best.copy()
    h[lo:lo + w] = h[lo:lo + w][::-1]
    return h, ("MIRROR", 0, lo, w)


def _move_swap(best, rng):
    n = best.size
    w = int(rng.uniform(0.05, 0.20) * n)
    w = max(1, min(w, n // 2))
    if n - 2 * w <= 0:
        return None, None
    lo = int(rng.integers(0, n - 2 * w + 1))
    lo2 = int(rng.integers(lo + w, n - w + 1))
    h = best.copy()
    h[lo:lo + w], h[lo2:lo2 + w] = best[lo2:lo2 + w].copy(), best[lo:lo + w].copy()
    return h, ("SWAP", 0, lo, w, lo2)


def _junction_free(touched, n, halo=128):
    kind = touched[0]
    lo = touched[2]; w = touched[3]
    wins = [(lo - halo, lo + halo), (lo + w - halo, lo + w + halo)]
    if kind == "SWAP":
        lo2 = touched[4]
        wins += [(lo2 - halo, lo2 + halo), (lo2 + w - halo, lo2 + w + halo)]
    idx = []
    for a, b in wins:
        a = max(0, a); b = min(n - 1, b)
        if b >= a:
            idx.append(np.arange(a, b + 1))
    if not idx:
        return np.arange(n)
    return np.unique(np.concatenate(idx))


def _densify(h):
    h = np.clip(h, 0, None)
    pos = h[h > 0]
    if pos.size == 0:
        return h
    eps = 1e-6 * pos.mean()
    out = h.copy()
    out[out <= 0] = eps
    return _rescale(out)


def _resample(h, N_new):
    """Resample a step function onto N_new equal steps by integrating
    the piecewise-constant function exactly."""
    n = h.size
    if n == N_new:
        return h.copy()
    # cumulative integral of h over unit steps
    cum = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, n, N_new + 1)
    # integral from 0 to xs, using linear interpolation of cum
    vals = np.interp(xs, np.arange(n + 1), cum)
    out = np.diff(vals)  # mass in each new cell
    out = out * (n / N_new)  # convert mass to average height
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: smooth polish to get off the constraint boundary ----
    if time.process_time() < deadline - 2.0:
        best, bestR = _smooth_polish(best, deadline - 2.0, rounds=8)
        print("smooth polish R=%.7f zeros=%.1f%%" % (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Phase 2: resample to a smaller N and re-optimise ----
    # Smaller N = fewer variables = faster convergence and a different
    # landscape; the optimal shape is smooth, so this is a valid move.
    for N_try in [best.size, max(2048, best.size // 2), max(4096, best.size // 3),
                  max(8192, best.size // 2)]:
        if time.process_time() >= deadline - 1.5:
            break
        if N_try == best.size:
            continue
        try:
            hr = _resample(best, N_try)
            hr = _rescale(hr)
            hr, r = _smooth_polish(hr, deadline - 1.5, rounds=4)
            if r > bestR + 1e-13:
                best, bestR = hr, r
                print("resample N=%d -> R=%.7f" % (N_try, bestR))
        except Exception:
            pass

    # ---- Phase 3: alternating smooth-polish + peak-window local refinement ----
    it = 0
    while time.process_time() < deadline - 1.2:
        it += 1
        prevR = bestR

        # smooth polish on all coordinates
        best, bestR = _smooth_polish(best, deadline - 1.2, rounds=3,
                                     offset_frac=1e-3, maxiter=500)

        # peak-window focused refinement: only the region around the max
        # of f*f matters for ||f*f||_inf, so we concentrate effort there.
        if time.process_time() < deadline - 1.2:
            win = _peak_window(best, tol=0.99, pad_frac=0.3, extra=256)
            ht = _lbfgs_block(best, win, 300, deadline - 1.2, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r

        # beta continuation: softmax approximation of the max
        for beta in [1e4, 1e5, 1e6, 1e7]:
            if time.process_time() >= deadline - 1.2:
                break
            ht = _lbfgs_all_pos(best, 200, deadline - 1.2, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r

        print("iter %d R=%.7f (gain %.2e) zeros=%.1f%% band01=%.2f%%" %
              (it, bestR, bestR - prevR, 100.0 * np.mean(best <= 0),
               100.0 * _band_frac(best, 0.001)))

    # ---- Phase 4: final smooth polish ----
    if time.process_time() < deadline - 0.5:
        best, bestR = _smooth_polish(best, deadline - 0.5, rounds=2,
                                     offset_frac=5e-4, maxiter=400)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _cum_resample(h, Np):
    """Cumulative-mass interpolation onto Np cells."""
    N = h.size
    if Np == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(Np + 1, dtype=float) * (N / Np)
    src = np.arange(N + 1, dtype=float)
    Cp = np.interp(x, src, C)
    hp = np.diff(Cp)
    return np.clip(hp, 0.0, None)


def _near_max_shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(L >= mx * 0.999)),
            float(np.mean(L >= mx * 0.99)),
            float(np.mean(L >= mx * 0.95)))


def _argmax_frac(h):
    L = _knots(h)
    return float(np.argmax(L) / (L.size - 1))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
