    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    m = min(m, Lf.size)
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_band(h, lo, hi, p, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    S = np.flatnonzero((Lf >= lo * M) & (Lf <= hi * M))
    if S.size < 64:
        S = np.flatnonzero((Lf >= 0.4 * M) & (Lf <= hi * M))
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / M
    sm = 0.0
    if S.size > 0:
        y = Lf[S] / M
        ymin = y.min()
        e = np.exp(-p * (y - ymin))
        Z = e.sum()
        if Z > 0:
            sm = -(np.log(Z) / p) + ymin
            gLf[S] += mu * (e / Z) / M
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) - mu * sm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _coarsen_offset(h, c, o):
    n = h.size
    if o > 0:
        hh = np.concatenate([np.zeros(o), h])
    else:
        hh = h
    m = (hh.size + c - 1) // c
    pad = m * c - hh.size
    if pad > 0:
        hh = np.concatenate([hh, np.zeros(pad)])
    q = hh.reshape(m, c).sum(axis=1) / c
    return q, o


def _refine_offset(q, c, o, N):
    hr = np.repeat(q, c)
    if o > 0:
        hr = hr[o:]
    if hr.size < N:
        hr = np.concatenate([hr, np.zeros(N - hr.size)])
    elif hr.size > N:
        hr = hr[:N]
    return hr


def _shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(L >= mx * 0.999), np.mean(L >= mx * 0.99),
            np.mean(L >= mx * 0.95))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    loop_deadline = t0 + budget_seconds * 0.94
    hard_stop = t0 + budget_seconds * 0.97

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    N = best.size
    s1, s2, s3 = _shares(best)
    print("base R=%.12f (N=%d) shares %.4f/%.4f/%.4f" % (bestR, N, s1, s2, s3))

    alt_best = None
    altR = -1.0

    def consider(cand, tag):
        nonlocal best, bestR, alt_best, altR
        cand = _rescale(np.clip(cand, 0, None))
        r = R_of(cand)
        if r > altR:
            altR, alt_best = r, cand.copy()
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
            s1, s2, s3 = _shares(best)
            L = _knots(best)
            am = float(np.argmax(L)) / max(1, L.size - 1)
            print("%s R=%.12f shares %.4f/%.4f/%.4f argmax %.3f"
                  % (tag, r, s1, s2, s3, am))
            return True
        return False

    def time_left():
        return deadline - time.process_time()

    def loop_left():
        return loop_deadline - time.process_time()

    def peak_polish(h, tag):
        cur = h.copy()
        curR = R_of(cur)
        for pad_div in (16, 32, 64):
            if time_left() < 2.0:
                break
            L = _knots(cur)
            j = int(np.argmax(L))
            half = max(8, N // pad_div)
            lo = max(0, j - 1 - half)
            hi = min(N, j - 1 + half)
            if hi <= lo:
                continue
            sub = cur[lo:hi].copy()
            if sub.sum() <= 0:
                continue
            eps = 1e-12
            subp = np.clip(sub, eps, None)
            logsub = np.log(subp)

            def fg(z):
                hh = np.exp(z)
                val, g = _fun_grad_tie(hh)
                return val, g * hh

            cb = _make_cb(deadline - 0.3)
            try:
                res = minimize(fg, logsub, jac=True, method='L-BFGS-B',
                               bounds=[(-30.0, 30.0)] * logsub.size,
                               callback=cb,
                               options={'maxiter': 60, 'maxfun': 120,
                                        'ftol': 1e-20, 'gtol': 1e-16})
