            h2[lo:hi] = newsub
            h2 = _rescale(np.clip(h2, 0, None))
            r2 = R_of(h2)
            if r2 > curR + 1e-15:
                cur, curR = h2, r2
        consider(cur, tag)

    # ---- band (maximin / soft-min) rungs ----
    rungs = [
        (0.55, 0.95, 40.0, 3.0),
        (0.70, 0.98, 40.0, 10.0),
        (0.55, 0.90, 40.0, 10.0),
        (0.85, 0.995, 40.0, 30.0),
        (0.55, 0.95, 40.0, 30.0),
    ]
    rung_gain = [0.0] * len(rungs)

    band_deadline = t0 + budget_seconds * 0.80

    it = 0
    while time.process_time() < band_deadline and loop_left() > 1.0:
        it += 1
        for ri, (lo, hi, p, mu) in enumerate(rungs):
            if time.process_time() >= band_deadline or time_left() < 3.0:
                break
            now = time.process_time()
            sub_deadline = min(deadline - 8.0, now + 6.0)
            if sub_deadline <= now + 0.5:
                break
            before = bestR
            h = _lbfgs(best, lambda hh, a=lo, b=hi, c=p, d=mu:
                       _fun_grad_band(hh, a, b, c, d),
                       sub_deadline, maxiter=120)
            if time_left() > 2.0:
                h = _lbfgs(h, _fun_grad_tie,
                           min(deadline - 4.0, time.process_time() + 2.0),
                           maxiter=60)
            if time_left() > 2.0:
                peak_polish(h, "band-peak")
            if consider(h, "it%d band lo=%.2f hi=%.2f mu=%.0f" % (it, lo, hi, mu)):
                rung_gain[ri] += bestR - before

    # ---- pick best rung, cycle it ----
    best_ri = int(np.argmax(rung_gain))
    lo, hi, p, mu = rungs[best_ri]
    print("best rung %d (lo=%.2f hi=%.2f mu=%.0f) gain %.3e"
          % (best_ri, lo, hi, mu, rung_gain[best_ri]))

    while time_left() > 1.0 and time.process_time() < hard_stop:
        now = time.process_time()
        sub_deadline = min(deadline - 4.0, now + 5.0)
        if sub_deadline <= now + 0.5:
            break
        h = _lbfgs(best, lambda hh: _fun_grad_band(hh, lo, hi, p, mu),
                   sub_deadline, maxiter=120)
        if time_left() > 1.5:
            h = _lbfgs(h, _fun_grad_tie,
                       min(deadline - 2.0, time.process_time() + 2.0),
                       maxiter=60)
        if time_left() > 1.5:
            peak_polish(h, "cycle-peak")
        if not consider(h, "cycle band"):
            # fall back to tie polish
            if time_left() > 1.0:
                h2 = _lbfgs(best, _fun_grad_tie,
                            min(deadline - 1.0, time.process_time() + 2.0),
                            maxiter=60)
                consider(h2, "cycle tie")

    # ---- remainder: tie polish + peak polish ----
    while time_left() > 1.0 and time.process_time() < hard_stop:
        h = _lbfgs(best, _fun_grad_tie, deadline - 0.5, maxiter=80)
        if not consider(h, "tie-cycle"):
            break
    if time_left() > 1.0 and time.process_time() < hard_stop:
        peak_polish(best, "final-peak")

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    s1, s2, s3 = _shares(best)
    print("final R=%.12f (start %.12f, N=%d) shares %.4f/%.4f/%.4f"
          % (bestR, startR, best.size, s1, s2, s3))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    """Exact-tie objective: log of mean of all knots at the max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    tie = np.flatnonzero(Lf >= M * (1.0 - 1e-12))
    k = tie.size
    w = np.zeros_like(Lf)
    w[tie] = 1.0 / k
    gLf = -dq / num + w / M
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_toe(h, frac, p, nu):
    """Soft-min over the lowest knots inside the support, plus exact-tie max term."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    sup = np.flatnonzero(Lf > 1e-12 * M)
    if sup.size < 4:
        return _fun_grad_tie(h)
    lo, hi = sup[0], sup[-1]
    supp = np.arange(lo, hi + 1)
    k = max(8, int(frac * supp.size))
    k = min(k, supp.size)
    order = np.argsort(Lf[supp])
    T = supp[order[:k]]
    y = Lf[T] / M
    ymin = y.min()
    e = np.exp(np.clip(-p * (y - ymin), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = -(np.log(Z) / p) + ymin
    tie = np.flatnonzero(Lf >= M * (1.0 - 1e-12))
    kt = tie.size
    gLf = -dq / num
    gLf[tie] += (1.0 / kt) / M
    gLf[T] += nu * w / M
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) - nu * sm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fg, deadline, maxiter):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad
    return _lbfgs_custom(h0, fg, deadline, maxiter)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_window_polish(h, deadline):
    if time.process_time() >= deadline - 0.05:
        return h
    win = _peak_window(h, pad_frac=0.15, extra=128)
    return _lbfgs_block(h, win, 200, deadline, beta=1e7)


def _toe_stats(h):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0, 0.0
    sup = np.flatnonzero(Lf > 1e-12 * M)
    if sup.size < 4:
        return 0.0, 0.0
    lo, hi = sup[0], sup[-1]
    supp = np.arange(lo, hi + 1)
    k = max(1, int(0.10 * supp.size))
    order = np.argsort(Lf[supp])
    T = supp[order[:k]]
    toe = float(np.mean(Lf[T]) / M)
    argmax_frac = float(np.argmax(Lf) / max(1, h.size - 1))
    return toe, argmax_frac


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.97
    work_deadline = t0 + budget_seconds * 0.80

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    rungs = [(0.30, 60.0, 2.0), (0.20, 60.0, 8.0),
             (0.30, 60.0, 20.0), (0.10, 60.0, 40.0)]

    for (frac, p, nu) in rungs:
        if time.process_time() >= work_deadline - 1.0:
            break
        fg = (lambda hh, fr=frac, pp=p, nn=nu: _fun_grad_toe(hh, fr, pp, nn))
        seg_end = min(work_deadline - 0.5, time.process_time() + 7.0)
        cand = _lbfgs_custom(best, fg, seg_end, 150)
        # exact-tie polish
        seg_end2 = min(work_deadline - 0.3, time.process_time() + 2.0)
        cand = _lbfgs_custom(cand, _fun_grad_tie, seg_end2, 60)
        # peak window polish
        seg_end3 = min(work_deadline - 0.1, time.process_time() + 2.0)
        cand = _peak_window_polish(cand, seg_end3)
        r = R_of(cand)
        toe, amf = _toe_stats(cand)
        if r > bestR + 1e-12:
            best, bestR = cand, r
            origin = "toe(%.2f,%g,%g)" % (frac, p, nu)
        elif r > alt_bestR:
            alt_best, alt_bestR = cand, r
        print("rung frac=%.2f p=%g nu=%g: R=%.9f (best %.9f) toe=%.6f argmax=%.3f"
              % (frac, p, nu, r, bestR, toe, amf))

    # Final full polish: exact-tie then peak window, up to hard deadline.
    if time.process_time() < deadline - 1.0:
        seg = min(deadline - 0.6, time.process_time() + 4.0)
        cand = _lbfgs_custom(best, _fun_grad_tie, seg, 200)
        r = R_of(cand)
        if r > bestR + 1e-12:
            best, bestR = cand, r
            origin = origin + "+tie"
        if time.process_time() < deadline - 0.5:
            seg = min(deadline - 0.2, time.process_time() + 3.0)
            cand = _peak_window_polish(best, seg)
            r = R_of(cand)
            if r > bestR + 1e-12:
                best, bestR = cand, r
                origin = origin + "+pk"

    toe, amf = _toe_stats(best)
    print("final R=%.9f origin=%s (start %.9f, N=%d) toe=%.6f argmax=%.3f"
          % (bestR, origin, start_bestR, best.size, toe, amf))

    if alt_best is not None and alt_best.size == best.size and alt_bestR > start_bestR:
        return {"best": best, "alternative": alt_best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
