    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _fun_grad_maxsoft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_soft(h0, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_maxsoft(hh, beta)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _full_lbfgs(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _full_lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- NEW: refine by resampling to a finer grid ----------
def _refine(h, factor=2):
    """Upsample step function by linear interp (keeps mass roughly, shape)."""
    n = h.size
    m = n * factor
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(m) + 0.5) / m
    hr = np.interp(x_new, x_old, h, left=0.0, right=0.0)
    return _rescale(hr)


# ---------- NEW: block-coordinate descent over contiguous overlapping windows ----------
def _block_sweep(h, deadline, nblocks=8, overlap=0.25, maxiter=60):
    """Sweep over overlapping windows, polishing each. Cheap + effective."""
    n = h.size
    if n < 16:
        return h
    best = h.copy()
    bestR = R_of(best)
    blen = max(8, int(n / nblocks * (1.0 + overlap)))
    step = max(1, int(blen * (1.0 - overlap)))
    starts = list(range(0, max(1, n - blen + 1), step))
    if starts[-1] + blen < n:
        starts.append(n - blen)
    improved = True
    it = 0
    while improved and it < maxiter and time.process_time() < deadline - 1.0:
        improved = False
        it += 1
        for s in starts:
            if time.process_time() >= deadline - 0.8:
                break
            e = min(n, s + blen)
            free = np.arange(s, e)
            hb = _lbfgs_block(best, free, 40,
                              min(deadline - 0.5,
                                  time.process_time() + 1.5))
            rb = R_of(hb)
            if rb > bestR + 1e-14:
                best, bestR = hb, rb
                improved = True
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: block sweep at current resolution ----
    p1_end = t0 + (deadline - t0) * 0.25 + t0
    if time.process_time() < p1_end - 1.5:
        h1 = _block_sweep(best, p1_end, nblocks=8, overlap=0.25)
        r1 = R_of(h1)
        print("block sweep R=%.9f" % r1)
        if r1 > bestR + 1e-15:
            best, bestR = h1, r1
            print("block sweep ACCEPT R=%.9f" % bestR)

    # ---- Phase 2: full-vector L-BFGS polish ----
    p2_end = t0 + (deadline - t0) * 0.45 + t0
    if time.process_time() < p2_end - 1.5:
        h2 = _full_lbfgs(best, 400, p2_end)
        r2 = R_of(h2)
        print("full lbfgs R=%.9f" % r2)
        if r2 > bestR + 1e-15:
            best, bestR = h2, r2
            print("full lbfgs ACCEPT R=%.9f" % bestR)
        h2l = _full_lbfgs_log(best, 400, p2_end)
        r2l = R_of(h2l)
        if r2l > bestR + 1e-15:
            best, bestR = h2l, r2l
            print("full log lbfgs ACCEPT R=%.9f" % bestR)

    # ---- Phase 3: sharpened-softmax peak-flattening ladder ----
    p3_end = t0 + (deadline - t0) * 0.62 + t0
    if time.process_time() < p3_end - 1.5:
        for beta in (1e4, 1e5, 1e6, 1e7, 1e8):
            if time.process_time() >= p3_end - 1.0:
                break
            hb = _lbfgs_soft(best, 200,
                             min(p3_end - 0.6,
                                 time.process_time() + 3.0), beta)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb, rb
        print("softmax ladder R=%.9f" % bestR)

    # ---- Phase 4: peak-window polish at multiple scales ----
    p4_end = t0 + (deadline - t0) * 0.82 + t0
    for pad in (0.20, 0.08, 0.04, 0.02):
        if time.process_time() >= p4_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 200,
                          min(p4_end - 0.5,
                              time.process_time() + 2.0), tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht, rt
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---- Phase 5: try refinement to a 2x finer grid, then polish ----
    p5_end = t0 + (deadline - t0) * 0.90 + t0
    if best.size <= 300000 and time.process_time() < p5_end - 4.0:
        hr = _refine(best, 2)
        hr = _full_lbfgs(hr, 200,
                         min(p5_end - 1.0,
                             time.process_time() + 4.0))
        rr = R_of(hr)
        print("refine x2 R=%.9f" % rr)
        if rr > bestR + 1e-15:
            best, bestR = hr, rr
            print("refine ACCEPT R=%.9f" % bestR)

    # ---- Phase 6: final polish until deadline ----
    while time.process_time() < deadline - 1.5:
        prev = bestR
        h6 = _full_lbfgs(best, 150,
                         min(deadline - 0.5,
                             time.process_time() + 3.0))
        r6 = R_of(h6)
        if r6 > bestR + 1e-15:
            best, bestR = h6, r6
        h6l = _full_lbfgs_log(best, 150,
                              min(deadline - 0.3,
                                  time.process_time() + 3.0))
        r6l = R_of(h6l)
        if r6l > bestR + 1e-15:
            best, bestR = h6l, r6l
        print("final polish R=%.9f" % bestR)
        if bestR <= prev + 1e-15:
            break

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        # try coarse block sweep as an alternative diverse construction
        alt_end = time.process_time() + max(1.0, deadline - time.process_time() - 0.5)
        try:
            alt = _block_sweep(best, min(alt_end, deadline - 0.5),
                               nblocks=6, overlap=0.4)
            if R_of(alt) > startR + 1e-14 and R_of(alt) >= bestR - 1e-12:
                result["best"] = alt
            else:
                result["alternative"] = alt
        except Exception:
            result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-8))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150, free_idx=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if free_idx is None:
        pos = np.flatnonzero(h > 0)
    else:
        pos = np.asarray(free_idx, dtype=int)
        pos = pos[h[pos] > 0]
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-14 * hmax if hmax > 0 else 1e-14
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, deadline, fr, maxiter=120):
    """Optimize a window around the peak of f*f (support of the peak)."""
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    half = max(8, int(n * fr))
    lo = max(0, int(c) - half)
    hi = min(n, int(c) + half)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    return _lbfgs_custom(h, _fun_grad_tie, deadline, maxiter=maxiter, free_idx=idx)


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def _restrict(h, m):
    n = h.size
    if m >= n:
        return _prolong(h, m)
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    return np.clip(np.diff(c_new), 0.0, None)


def _polish(h, r, deadline, fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=200):
    for fr in fracs:
        if time.process_time() >= deadline - 0.5:
            break
        cand = _peak_window(h, deadline, fr, maxiter=maxiter)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
    return h, r


def _refine(h, r, deadline, tag):
    # full tie-gradient pass
    cand = _lbfgs_custom(h, _fun_grad_tie, deadline, maxiter=250)
    r2 = R_of(cand)
    if r2 > r:
        h, r = cand, r2
    # CVaR smoothing at a few alphas
    for alpha in (0.02, 0.005):
        if time.process_time() >= deadline - 0.5:
            break
        fg = (lambda a: (lambda hh: _fun_grad_cvar(hh, a)))(alpha)
        cand = _lbfgs_custom(h, fg, deadline, maxiter=150)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
    # windowed polish
    h, r = _polish(h, r, deadline)
    print("  %s R=%.7f N=%d" % (tag, r, h.size))
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0
    alt = None
    alt_r = -1.0

    if start_arr is not None:
        cur = start_arr
        cur_r = start_r
        print("start base R=%.7f N=%d" % (cur_r, cur.size))

        # Phase A: refine at the current resolution.
        cur, cur_r = _refine(cur, cur_r, deadline, "base")
        best, best_r = cur, cur_r

        # Phase B: try finer resolutions (2x, 4x) — refinement helps at
        # higher N because it resolves the peak of f*f better.
        if time.process_time() < deadline - 8.0:
            for factor in (2, 4):
                if time.process_time() >= deadline - 6.0:
                    break
                hi = _rescale(_prolong(best, factor * best.size))
                hi_r = R_of(hi)
                print("  split x%d N=%d R=%.7f" % (factor, hi.size, hi_r))
                hi, hi_r = _refine(hi, hi_r, deadline, "split%d" % factor)
                if hi_r > alt_r:
                    alt, alt_r = hi, hi_r
                if hi_r > best_r:
                    best, best_r = hi, hi_r

        # Phase C: coarse restart from the current best.
        if time.process_time() < deadline - 4.0 and best.size > 256:
            lo = _rescale(_restrict(best, best.size // 2))
            lo_r = R_of(lo)
            print("  coarsen N=%d R=%.7f" % (lo.size, lo_r))
            lo, lo_r = _refine(lo, lo_r, deadline, "coarse")
            if lo_r > alt_r:
                alt, alt_r = lo, lo_r

        # Phase D: final burst on the winner.
        if time.process_time() < deadline - 1.5:
            if alt_r > best_r:
                best, best_r = alt, alt_r
            while time.process_time() < deadline - 1.0:
                cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=200)
                r2 = R_of(cand)
                if r2 > best_r:
                    best, best_r = cand, r2
                    print("  final R=%.7f" % best_r)
                else:
                    # polish window then break
                    cand, r2 = _polish(best, best_r, deadline,
                                       fracs=(0.10, 0.05, 0.02), maxiter=150)
                    if r2 > best_r:
                        best, best_r = cand, r2
                        print("  final R=%.7f" % best_r)
                    else:
                        break

    if best is None:
        N0 = 64
        x = np.linspace(0, 1, N0)
        best = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        best_r = R_of(best)

    print("best R=%.7f (start %.7f)" % (best_r, start_r))

    if start_arr is not None and start_r >= best_r:
        if alt is not None and alt_r > start_r and not np.array_equal(alt, start_arr):
            return {"best": _rescale(start_arr), "alternative": _rescale(alt)}
        return _rescale(start_arr)

    if start_arr is not None:
        return {"best": _rescale(best), "alternative": _rescale(start_arr)}
    return _rescale(best)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    tie = np.flatnonzero(Lf >= M * (1.0 - 1e-12))
    k = tie.size
    w = np.zeros_like(Lf)
    w[tie] = 1.0 / k
    gLf = -dq / num + w / M
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_toe_scaled(h, frac, p, nu, gamma):
    """Toe surrogate with the toe gradient explicitly rescaled to the
    norm of the num-gradient, so it cannot be swallowed."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    sup = np.flatnonzero(Lf > 1e-12 * M)
    if sup.size < 4:
        return _fun_grad_tie(h)
    i0, i1 = sup[0], sup[-1]
    span = i1 - i0 + 1
    k = max(8, int(frac * span))
    k = min(k, span)
    seg = np.arange(i0, i1 + 1)
    order = np.argsort(Lf[seg])
    S = seg[order[:k]]
    # soft-min over S with temperature nu*M
    temp = nu * M + 1e-300
    y = Lf[S]
    ymin = y.min()
    e = np.exp(np.clip(-(y - ymin) / temp, -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    softmin = float(np.sum(w * y))
    # gradient of softmin wrt knot values at S
    g_toe_knots = w * (y - softmin) / temp
    gLf_toe = np.zeros_like(Lf)
    gLf_toe[S] = g_toe_knots
    g_toe = _backprop(gLf_toe, h)
    # num-gradient part (same pattern as _fun_grad, minus max term)
    gLf_num = -dq / num
    g_num = _backprop(gLf_num, h) + 2.0 / s
    nt = np.linalg.norm(g_toe)
    nn = np.linalg.norm(g_num)
    if nt > 0:
        g_toe = g_toe / nt * (nn + 1e-30)
    grad = g_num + gamma * g_toe
    val = -np.log(num) + 2.0 * np.log(s) + np.log(softmin)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fg, deadline, maxiter):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_window_polish(h, deadline, pad_frac=0.15, extra=128):
    if time.process_time() >= deadline - 0.05:
        return h
    win = _peak_window(h, pad_frac=pad_frac, extra=extra)
    return _lbfgs_block(h, win, 200, deadline, beta=1e7)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _toe_stat(h, frac=0.20):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0
    sup = np.flatnonzero(Lf > 1e-12 * M)
    if sup.size < 4:
        return 0.0
    i0, i1 = sup[0], sup[-1]
    seg = np.arange(i0, i1 + 1)
    k = max(1, int(frac * seg.size))
    order = np.argsort(Lf[seg])
    T = seg[order[:k]]
    return float(np.mean(Lf[T]) / M)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.97

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d) toe=%.6f" % (bestR, best.size, _toe_stat(best)))

    alt_best = None
    alt_bestR = -1.0

    rungs = [(0.40, 20.0, 0.05, 0.3),
             (0.25, 40.0, 0.02, 1.0),
             (0.12, 80.0, 0.005, 3.0)]

    for (frac, p, nu, gamma) in rungs:
        if time.process_time() >= deadline - 14.0:
            break
        cur = best.copy()
        toe_before = _toe_stat(cur)
        R_before = R_of(cur)
        fg = (lambda hh, fr=frac, pp=p, nn=nu, gg=gamma:
              _fun_grad_toe_scaled(hh, fr, pp, nn, gg))
        seg_end = min(deadline - 12.0, time.process_time() + 6.0)
        cur = _lbfgs_custom(cur, fg, seg_end, 250)
        R_mid = R_of(cur)
        toe_mid = _toe_stat(cur)
        print("toe frac=%.2f p=%g nu=%g gamma=%g: R %.9f -> %.9f (dR=%.2e) toe %.6f -> %.6f"
              % (frac, p, nu, gamma, R_before, R_mid, R_mid - R_before,
                 toe_before, toe_mid))
        # repair with exact-tie polish
        seg_end2 = min(deadline - 6.0, time.process_time() + 5.0)
        cur = _lbfgs_custom(cur, _fun_grad_tie, seg_end2, 200)
        seg_end3 = min(deadline - 2.0, time.process_time() + 3.0)
        cur = _peak_window_polish(cur, seg_end3, pad_frac=0.15, extra=128)
        r = R_of(cur)
        print("  repaired R=%.9f (best %.9f) toe=%.6f" % (r, bestR, _toe_stat(cur)))
        if r > bestR + 1e-12:
            best, bestR = cur, r
        elif r > alt_bestR:
            alt_best, alt_bestR = cur, r

    # Spend remainder alternating tie polish and peak-window polish.
    while time.process_time() < deadline - 1.0:
        seg = min(deadline - 0.6, time.process_time() + 3.0)
        cand = _lbfgs_custom(best, _fun_grad_tie, seg, 200)
        r = R_of(cand)
        if r > bestR + 1e-12:
            best, bestR = cand, r
        if time.process_time() >= deadline - 0.5:
            break
        seg = min(deadline - 0.2, time.process_time() + 2.0)
        cand = _peak_window_polish(best, seg, pad_frac=0.15, extra=128)
        r = R_of(cand)
        if r > bestR + 1e-12:
            best, bestR = cand, r
        else:
            break

    print("final R=%.9f (start %.9f, N=%d) toe=%.6f"
          % (bestR, start_bestR, best.size, _toe_stat(best)))

    if alt_best is not None and alt_best.size == best.size and alt_bestR > start_bestR:
        return {"best": best, "alternative": alt_best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.14, 0.09, 0.06, 0.04), iters=400):
    best = h.copy()
    bestR = R_of(best)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2, r2
    return best, bestR


def _polish(c, bestR, deadline):
    best = c.copy()
    work = c.copy()
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
    for pad in [0.30, 0.20, 0.14, 0.10, 0.06]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
    return work, best, bestR


def _extract(c_full, k, m):
    if k == 0:
        c = c_full[0::2][:m].copy()
    elif k == 1:
        c = c_full[1::2][:m].copy()
    else:
        a = c_full[0::2][:m]
        b = c_full[1::2][:m]
        L = min(a.size, b.size)
        c = 0.5 * (a[:L] + b[:L])
        if c.size < m:
            c = np.concatenate((c, np.full(m - c.size, c[-1])))
    return c


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _block_refine(h0, deadline, rounds=6):
    best = h0.copy()
    bestR = R_of(best)
    for tol in (0.999, 0.99, 0.97, 0.95, 0.92):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, tol=tol, pad_frac=0.25, extra=256)
        ht = _lbfgs_block(best, win, 300, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-15:
                best, bestR = ht2, r2
    return best, bestR


def _birth_death_grad(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    return grad * h


def _birth_death_sweep(h, deadline, rng, max_trials=4000):
    """Try turning on currently-zero cells with the best one-sided gradient."""
    best = h.copy()
    bestR = R_of(best)
    n = h.size
    trial = 0
    while time.process_time() < deadline - 1.0 and trial < max_trials:
        zeros = np.flatnonzero(best <= 0)
        if zeros.size == 0:
            break
        g = _birth_death_grad(best)
        # candidates with positive birth gradient
        gz = g[zeros]
        order = np.argsort(-gz)
        improved = False
        for oi in order[:8]:
            if time.process_time() >= deadline - 1.0:
                break
            if gz[oi] <= 0:
                break
            j = int(zeros[oi])
            trial += 1
            h2 = best.copy()
            # give it mass equal to a fraction of the mean positive height
            pos = best[best > 0]
            if pos.size == 0:
                break
            m0 = pos.mean()
            h2[j] = m0
            h2 = _rescale(h2)
            win = _peak_window(h2, pad_frac=0.15, extra=384)
            slice_dl = min(deadline - 0.8, time.process_time() + 1.5)
            h2 = _lbfgs_block(h2, win, 200, slice_dl, beta=1e7)
            if time.process_time() < slice_dl - 0.3:
                h2 = _lbfgs_all_pos(h2, 150, slice_dl, beta=0.0)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best, bestR = h2, r2
                improved = True
                break
        if not improved:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0
    rng = np.random.RandomState(987654)

    # ---- Phase 1: birth/death sweep (adds support where gradient is positive) ----
    bd_end = t0 + budget_seconds * 0.28
    if time.process_time() < bd_end - 1.0:
        try:
            hbd, rbd = _birth_death_sweep(best, bd_end, rng)
            if rbd > bestR + 1e-14:
                best, bestR, origin = hbd.copy(), rbd, 'birthdeath'
                print("birthdeath NEW BEST R=%.9f" % bestR)
            elif rbd > alt_bestR:
                alt_best, alt_bestR = hbd.copy(), rbd
        except Exception as e:
            print("birthdeath failed", e)

    # ---- Phase 2: rotation of extract/lift cycles (all three variants) ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 8.0
        max_cycles = 9
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 6.0, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            c = _extract(wk, k, m)
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR = _polish(c, cR0, slice_dl)
            except Exception:
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception:
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: final ladder polish + block refine ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _peak_ladder(best, deadline)
    if time.process_time() < deadline - 1.0:
        best2, bestR2 = _block_refine(best, deadline)
        if bestR2 > bestR + 1e-15:
            best, bestR = best2, bestR2
            origin = origin + '+refine'

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _collapse_to_c(h, q):
    N = h.size
    nb = (N + q - 1) // q
    c = np.zeros(nb)
    for j in range(nb):
        seg = h[j * q:(j + 1) * q]
        if seg.size > 0:
            c[j] = seg.mean()
    return c


def _expand_from_c(c, q, N):
    h = np.repeat(c, q)[:N]
    if h.size < N:
        h = np.concatenate([h, np.full(N - h.size, c[-1] if c.size else 0.0)])
    return h


def _lbfgs_c(h0, q, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    N = h0.size
    c = _collapse_to_c(np.clip(h0, 0, None), q)
    nb = c.size
    if nb == 0:
        return h0

    def expand(cv):
        return _expand_from_c(np.clip(cv, 0, None), q, N)

    def f(cv):
        hh = expand(cv)
        val, g = _fun_grad_tie(hh)
        gc = np.zeros(nb)
        for j in range(nb):
            lo = j * q
            hi = min(N, (j + 1) * q)
            if hi > lo:
                gc[j] = g[lo:hi].sum()
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, c.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(expand(res.x))


def _lift(h, N):
    """Mass-preserving lift of step function h to N steps via cumulative mass."""
    n = h.size
    if n == N:
        return h.copy()
    hc = np.clip(h, 0, None)
    mass = np.concatenate(([0.0], np.cumsum(hc)))
    total = mass[-1]
    if total <= 0:
        return np.zeros(N)
    # target cumulative mass at new cell boundaries
    xq = np.linspace(0.0, total, N + 1)
    # interpolate cumulative mass at new boundaries
    xp = np.linspace(0.0, total, n + 1)
    newmass = np.interp(xq, xp, mass)
    hnew = np.diff(newmass)
    return np.clip(hnew, 0, None)


def _near_max_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (100.0 * np.mean(Lf >= mx * 0.999),
            100.0 * np.mean(Lf >= mx * 0.99),
            100.0 * np.mean(Lf >= mx * 0.95))


def _peak_polish(h, deadline, maxiter=60):
    """Polish the peak region (near-max knots) with full-N L-BFGS."""
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    # knots near max correspond to h indices; take a window
    idx = np.flatnonzero(Lf >= mx * 0.90)
    if idx.size == 0:
        return h
    lo = max(0, idx.min() - 2)
    hi = min(h.size, idx.max() + 2)
    active = np.arange(lo, hi)
    return _lbfgs_block(h, active, maxiter, deadline, tie=True)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N0 = best.size
    print("base R=%.9f (N=%d)" % (bestR, N0))

    rng = np.random.default_rng(12345)
    alt_best = None
    altR = -1.0

    def consider(hcand, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hcand)
        sh = _near_max_shares(hcand)
        print("%s R=%.9f N=%d shares=%.1f/%.1f/%.1f"
              % (tag, r, hcand.size, sh[0], sh[1], sh[2]))
        if r > altR:
            altR = r
            alt_best = hcand.copy()
        if r > bestR + 1e-15:
            best, bestR = hcand.copy(), r
        return r

    # ---- resolution ladder ----
    ladder = [(4, 12.0), (16, 12.0), (32, 14.0)]
    q_sched = [64, 48, 32, 24, 16, 8]

    for L, cap in ladder:
        if time.process_time() >= deadline - 2.0:
            break
        N_L = L * N0
        if N_L > 1000000:
            print("skip L=%d (N_L=%d too big)" % (L, N_L))
            continue
        level_start = time.process_time()
        level_end = min(deadline - 1.5, level_start + cap)
        hL = _lift(best, N_L)
        hL = _rescale(hL)
        print("L=%d N_L=%d start R=%.9f" % (L, N_L, R_of(hL)))

        for rnd in range(4):
            if time.process_time() >= level_end - 0.5:
                break
            # (i) block-Newton q-schedule on block means
            for q in q_sched:
                if time.process_time() >= level_end - 0.5:
                    break
                if N_L // q < 4:
                    continue
                tq_end = min(level_end - 0.3,
                             time.process_time() + (level_end - time.process_time()) / 3.0)
                hL = _lbfgs_c(hL, q, 60, tq_end)
            # (ii) full-N L-BFGS
            if time.process_time() < level_end - 0.5:
                hL = _lbfgs_block(hL, np.arange(N_L), 150, level_end - 0.3, tie=True)
            # (iii) peak polish
            if time.process_time() < level_end - 0.5:
                hL = _peak_polish(hL, level_end - 0.2, maxiter=40)
            hL = _rescale(hL)
            rL = R_of(hL)
            print("  L=%d rnd=%d R=%.9f" % (L, rnd, rL))
            if rL > bestR + 1e-15:
                consider(hL, "L=%d accept" % L)
            else:
                # still record as alternative
                if rL > altR:
                    altR = rL
                    alt_best = hL.copy()

    # ---- final full-N polish of best ----
    if time.process_time() < deadline - 1.0:
        pol = _lbfgs_block(best, np.arange(best.size), 300, deadline - 0.5, tie=True)
        consider(pol, "final full-N polish")

    # ---- cycle tie polish + peak polish until deadline ----
    cyc = 0
    while time.process_time() < deadline - 1.0:
        cyc += 1
        tcyc_end = min(deadline - 0.5,
                       time.process_time() + (deadline - time.process_time()) / 2.0)
        hc = _lbfgs_block(best, np.arange(best.size), 200, tcyc_end, tie=True)
        hc = _peak_polish(hc, tcyc_end, maxiter=40)
        consider(hc, "cycle %d" % cyc)
        if time.process_time() >= deadline - 1.0:
            break

    if start is not None and bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400,
                 tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _resample(base, newN):
    n = base.size
    if n == newN:
        return base.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    h = np.interp(x_new, x_old, base)
    return _rescale(h)


def _merge_neighbors(h, deadline):
    """Try merging small adjacent cells (coarsen) then re-polish.
    Preserves integral; merges by summing. Reduces N."""
    n = h.size
    if n < 8:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    # find pairs where both cells are small (in the tails)
    order = np.argsort(h)
    # candidate merge indices: adjacent to a small cell
    thresh = np.median(h) * 0.5
    small = h < thresh
    cand = []
    for j in range(n - 1):
        if small[j] and small[j + 1]:
            cand.append(j)
        if len(cand) > 2000:
            break
    if not cand:
        return h
    # merge a fraction of candidates
    cand = np.array(cand)
    k = max(1, len(cand) // 8)
    sel = cand[:k]
    mask = np.ones(n, dtype=bool)
    mask[sel + 1] = False
    h2 = h.copy()
    h2[sel] = h[sel] + h[sel + 1]
    h2 = h2[mask]
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- Primary loop: alternate full-tie polish and peak-ladder polish,
    # plus a coarsening attempt when time allows. ----
    loop_end = t0 + budget_seconds * 0.86
    it = 0
    while time.process_time() < loop_end - 4.0:
        it += 1
        slice_end = min(loop_end, time.process_time() + 7.0)
        h_t = _lbfgs_all_pos(best, 600, slice_end - 3.0, tie=True)
        r_t = R_of(h_t)
        dR = r_t - bestR
        accepted = r_t > bestR + 1e-15
        if accepted:
            best, bestR = h_t.copy(), r_t
        print("tie pass %d N=%d dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f nearmax5=%.4f"
              % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                 bestR, _tie_count(h_t), _zero_frac(h_t),
                 _nearmax_frac(h_t)))
        if time.process_time() < slice_end - 1.5:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.10, 0.06, 0.04), iters=250, tie=True)
            r_t = R_of(h_t)
            dR = r_t - bestR
            accepted = r_t > bestR + 1e-15
            if accepted:
                best, bestR = h_t.copy(), r_t
            print("tie peak %d N=%d dR=%+.3e %s R=%.9f ties=%d zero_frac=%.4f nearmax5=%.4f"
                  % (it, h_t.size, dR, "ACCEPT" if accepted else "no gain",
                     bestR, _tie_count(h_t), _zero_frac(h_t),
                     _nearmax_frac(h_t)))

        # Occasionally attempt a coarsening (merge small neighbors) and
        # re-polish. This changes the discretisation and can break out of
        # a local optimum that the fixed-N optimiser is stuck in.
        if it % 3 == 0 and time.process_time() < slice_end - 2.0:
            try:
                hc = _merge_neighbors(best, slice_end - 1.0)
                if hc.size < best.size:
                    hc2 = _lbfgs_all_pos(hc, 400, slice_end - 0.5, tie=True)
                    rc = R_of(hc2)
                    if rc > bestR + 1e-15:
                        best, bestR = hc2.copy(), rc
                        print("coarsen ACCEPT N=%d R=%.9f" % (best.size, bestR))
                    else:
                        print("coarsen no gain N=%d R=%.9f" % (hc2.size, rc))
            except Exception:
                pass

    # ---- Final passes ----
    fd = t0 + budget_seconds * 0.93
    if time.process_time() < fd - 4.0:
        h_t = _lbfgs_all_pos(best, 600, fd - 2.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
        else:
            print("FINAL tie no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)
        else:
            print("FINAL argmax no gain R=%.9f" % r_t)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift_stride(c, s, rng=None):
    N = c.size * s
    if rng is None:
        return _rescale(np.repeat(c, s))
    w = np.exp(0.25 * rng.randn(s))
    w = w * (s / w.sum())
    out = np.repeat(c, s) * np.tile(w, c.size)
    return _rescale(np.clip(out, 0.0, None))


def _smooth_extend(h, factor, rng):
    """Insert `factor-1` interpolated points between each pair, with jitter."""
    n = h.size
    N = n * factor
    x_old = np.arange(n, dtype=float)
    x_new = np.arange(N, dtype=float) / factor
    out = np.interp(x_new, x_old, h)
    out *= np.exp(0.15 * rng.randn(N))
    return _rescale(np.clip(out, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient polish ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.25
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: alternating-stride quotient polish + lift ----
    jit_start = t0 + budget_seconds * 0.28
    jit_end = deadline - 7.0
    if time.process_time() < jit_start:
        while time.process_time() < jit_start - 0.05:
            time.sleep(0.01)
    cycle = [2, 4, 2, 8, 4, 2]
    if time.process_time() < jit_end - 1.0 and best.size >= 8:
        rnd = 0
        while time.process_time() < jit_end - 1.0:
            now = time.process_time()
            slice_dl = min(now + 5.5, deadline - 7.0)
            if slice_dl <= now + 0.8:
                break
            s = cycle[rnd % len(cycle)]
            Ncur = best.size
            if Ncur % s != 0:
                s = 2
                if Ncur % 2 != 0:
                    break
            c = best[0::s].copy()
            cR0 = R_of(c)
            work_c, best_c, best_cR, org = _half_cycle(
                c, cR0, slice_dl - 0.5, tag='s%d_%d' % (s, rnd))
            if time.process_time() >= slice_dl - 0.4:
                rnd += 1
                continue
            rng = None if rnd == 0 else np.random.RandomState(4000 + rnd)
            h = _lift_stride(best_c, s, rng)
            if time.process_time() < slice_dl - 0.3:
                h = _lbfgs_all_pos(h, 120, slice_dl - 0.2, beta=1e6)
            if time.process_time() < slice_dl - 0.3:
                h = _lbfgs_all_pos(h, 120, slice_dl - 0.2, beta=1e7)
            if time.process_time() < slice_dl - 0.3:
                win = _peak_window(h, pad_frac=0.06, extra=128)
                h = _lbfgs_block(h, win, 180, slice_dl - 0.2, beta=1e7)
            if time.process_time() < slice_dl - 0.3:
                h = _lbfgs_all_pos(h, 120, slice_dl - 0.2, beta=0.0)
            r = R_of(h)
            acc = False
            if h.size == best.size and r > bestR + 1e-13:
                best, bestR = h.copy(), r
                origin = 'stride%d_r%d' % (s, rnd)
                acc = True
            elif r > alt_bestR:
                alt_best, alt_bestR = h.copy(), r
            print("stride %d round %d R(c)=%.9f postLift=%.9f %s (best %.9f)"
                  % (s, rnd, best_cR, r, "ACCEPT" if acc else "reject", bestR))
            rnd += 1

    # ---- Phase 2b: refinement at higher resolution (upsample + polish) ----
    refine_end = deadline - 3.5
    if time.process_time() < refine_end - 1.5 and best.size < 500000:
        rng = np.random.RandomState(777)
        factor = 2
        h_up = _smooth_extend(best, factor, rng)
        r0 = R_of(h_up)
        for beta in [1e6, 1e7]:
            if time.process_time() >= refine_end - 0.8:
                break
            h_up = _lbfgs_all_pos(h_up, 250, refine_end - 0.4, beta=beta)
        if time.process_time() < refine_end - 0.6:
            win = _peak_window(h_up, pad_frac=0.05, extra=256)
            h_up = _lbfgs_block(h_up, win, 300, refine_end - 0.3, beta=1e7)
        if time.process_time() < refine_end - 0.4:
            h_up = _lbfgs_all_pos(h_up, 200, refine_end - 0.2, beta=0.0)
        r1 = R_of(h_up)
        print("refine x%d R: %.9f -> %.9f (best %.9f)" % (factor, r0, r1, bestR))
        if r1 > bestR + 1e-13:
            best, bestR = h_up.copy(), r1
            origin = 'refine_x%d' % factor
            print("refine NEW BEST R=%.9f" % bestR)
        elif r1 > alt_bestR:
            alt_best, alt_bestR = h_up.copy(), r1

    # ---- Phase 3: final pad ladder + beta ladder ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _split2(h, rng):
    """Randomized asymmetric 2-split: each cell -> two half-cells."""
    N = h.size
    a = 0.5 + 0.35 * (rng.random(N) - 0.5)
    h2 = np.empty(2 * N)
    h2[0::2] = a * h
    h2[1::2] = (1.0 - a) * h
    return h2


def _polish(h, deadline, verbose=True):
    """Full tie polish, CVaR ladder, peak polish, tie polish."""
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 1.0, time.process_time() + 6.0)
        hp = _full_lbfgs(h, tlim, maxiter=200)
        if R_of(hp) > R_of(h):
            h = hp
    for alpha, iters in ((0.30, 80), (0.18, 80), (0.10, 80), (0.05, 80)):
        if time.process_time() >= deadline - 1.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hc = _lbfgs_custom(h, lambda hh, a=alpha: _fun_grad_cvar(hh, a),
                           tlim, maxiter=iters)
        if R_of(hc) > R_of(h):
            h = hc
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 1.0, time.process_time() + 2.0)
        hp = _peak_window_polish(h, tlim, pad=3, frac=8)
        if R_of(hp) > R_of(h):
            h = hp
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 1.0, time.process_time() + 4.0)
        hp = _full_lbfgs(h, tlim, maxiter=200)
        if R_of(hp) > R_of(h):
            h = hp
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h = _rescale(base)
        else:
            h = None
    else:
        h = None

    if h is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h)
    best = h.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt = None
    altR = -1.0

    def _try_split_round(hcur, bestR, best, alt, altR, trials, tag):
        N = hcur.size
        round_best = hcur
        round_bestR = bestR
        for t in range(trials):
            if time.process_time() >= deadline - 1.0:
                break
            rng = np.random.default_rng(1000 * tag + t)
            h2 = _split2(hcur, rng)
            # short L-BFGS: ~20% of remaining budget
            rem = deadline - time.process_time()
            tlim = min(deadline - 1.0, time.process_time() + max(1.0, 0.20 * rem))
            h2p = _full_lbfgs(h2, tlim, maxiter=60)
            r2 = R_of(h2p)
            print("  [%s trial %d] split R=%.9f" % (tag, t, r2))
            if r2 > round_bestR:
                round_best = h2p
                round_bestR = r2
        return round_best, round_bestR

    # Round 1: 2x lift
    if time.process_time() < deadline - 1.0:
        rb, rbR = _try_split_round(best, bestR, best, alt, altR, 6, 1)
        if rbR > bestR:
            best = rb
            bestR = rbR
            print("round1 split improved: %.9f" % bestR)
        else:
            # keep as alternative if genuinely different
            if rb is not best and R_of(rb) > altR:
                alt = rb
                altR = R_of(rb)

    # Long polish on best
    if time.process_time() < deadline - 1.0:
        hp = _polish(best, deadline)
        rp = R_of(hp)
        print("polish R=%.9f (best %.9f)" % (rp, bestR))
        if rp > bestR:
            best = hp
            bestR = rp

    # Round 2: 4x lift if time remains
    if time.process_time() < deadline - 8.0:
        rb, rbR = _try_split_round(best, bestR, best, alt, altR, 4, 2)
        if rbR > bestR:
            best = rb
            bestR = rbR
            print("round2 split improved: %.9f" % bestR)
            hp = _polish(best, deadline)
            rp = R_of(hp)
            print("round2 polish R=%.9f" % rp)
            if rp > bestR:
                best = hp
                bestR = rp

    if bestR < startR:
        best = h.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if alt is not None and altR > 0 and alt is not best:
        return {"best": best, "alternative": alt}
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    """CVaR objective: -log(num) + 2 log(s) + log(mean of top-alpha Lf)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = Lf.size
    k = max(1, int(np.ceil(alpha * m)))
    # top-k indices
    idx = np.argpartition(Lf, m - k)[m - k:]
    cm = Lf[idx].mean()
    if cm <= 0:
        cm = 1e-30
    gLf = -dq / num
    gLf[idx] += (1.0 / (k * cm))
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, fun=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fun is None:
        fun = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _collapse_to_c(h, q):
    N = h.size
    nb = (N + q - 1) // q
    c = np.zeros(nb)
    for j in range(nb):
        seg = h[j * q:(j + 1) * q]
        if seg.size > 0:
            c[j] = seg.mean()
    return c


def _expand_from_c(c, q, N):
    h = np.repeat(c, q)[:N]
    if h.size < N:
        h = np.concatenate([h, np.full(N - h.size, c[-1] if c.size else 0.0)])
    return h


def _block_newton_cvar(h0, q, alpha, n_outer, deadline, fun):
    """Block-Newton on q-collapsed means c, expanded to full-N h, using `fun`."""
    if time.process_time() >= deadline - 0.3:
        return h0
    N = h0.size
    c = _collapse_to_c(np.clip(h0, 0, None), q)
    nb = c.size
    if nb == 0:
        return h0

    def expand(cv):
        return _expand_from_c(np.clip(cv, 0, None), q, N)

    def fc(cv):
        hh = expand(cv)
        val, g = fun(hh)
        gc = np.zeros(nb)
        for j in range(nb):
            lo = j * q
            hi = min(N, (j + 1) * q)
            if hi > lo:
                gc[j] = g[lo:hi].sum()
        return val, gc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(fc, c.copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * nb, callback=cb,
                       options={'maxiter': n_outer, 'maxfun': 2 * n_outer,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(expand(res.x))


def _peak_window_polish(h, deadline, iters=60):
    """p2971-style peak-window polish: lbfgs on cells near the peak."""
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    # knots near max: window around argmax
    idx = np.flatnonzero(Lf >= mx * 0.98)
    if idx.size == 0:
        return h
    lo = max(0, idx.min() - 2)
    hi = min(h.size, idx.max() + 1)
    free = np.arange(lo, hi)
    return _lbfgs_block(h, free, iters, deadline, fun=_fun_grad_tie)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    altR = -1.0

    def consider(hcand, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hcand)
        print("%s R=%.9f" % (tag, r))
        if r > altR:
            altR = r
            alt_best = hcand.copy()
        if r > bestR + 1e-15:
            best, bestR = hcand.copy(), r
        return r

    def cvar_fun(alpha):
        def f(hh):
            return _fun_grad_cvar(hh, alpha)
        return f

    def run_ladder(ladder, tag_prefix):
        nonlocal best, bestR
        for (q, alpha) in ladder:
            if time.process_time() >= deadline - 1.5:
                break
            qq = q
            # ensure q divides N; else use nearest divisor
            if N % qq != 0:
                # find divisor near q
                cand = [d for d in range(2, min(N, 400)) if N % d == 0]
                if not cand:
                    continue
                qq = min(cand, key=lambda d: abs(d - q))
            rung_end = min(deadline - 1.0,
                           time.process_time() +
                           (deadline - time.process_time()) / 2.0)
            fun = cvar_fun(alpha)
            # block-Newton on collapsed means with CVaR objective
            hc = _block_newton_cvar(best, qq, alpha, 25, rung_end, fun)
            consider(hc, "%s q=%d a=%.2f newton" % (tag_prefix, qq, alpha))
            # full-N lbfgs with CVaR on active cells
            if time.process_time() < rung_end - 0.5:
                ha = _lbfgs_block(hc, np.arange(N), 40, rung_end, fun=fun)
                consider(ha, "%s q=%d a=%.2f cvar-lbfgs" % (tag_prefix, qq, alpha))
            # short exact-tie lbfgs
            if time.process_time() < rung_end - 0.3:
                ht = _lbfgs_block(best, np.arange(N), 30, rung_end,
                                  fun=_fun_grad_tie)
                consider(ht, "%s q=%d a=%.2f tie" % (tag_prefix, qq, alpha))

    ladder1 = [(64, 0.30), (32, 0.18), (16, 0.10), (8, 0.05)]
    run_ladder(ladder1, "L1")

    # exact-tie full-N polish
    if time.process_time() < deadline - 1.0:
        pol_end = min(deadline - 0.5, time.process_time() + 5.0)
        pol = _lbfgs_block(best, np.arange(N), 100, pol_end, fun=_fun_grad_tie)
        consider(pol, "full-N tie polish")
        pw = _peak_window_polish(best, pol_end, 60)
        consider(pw, "peak-window polish")

    # second ladder if time
    if time.process_time() < deadline - 15.0:
        ladder2 = [(32, 0.10), (16, 0.05), (8, 0.02)]
        run_ladder(ladder2, "L2")
        if time.process_time() < deadline - 1.0:
            pol_end = min(deadline - 0.5, time.process_time() + 5.0)
            pol = _lbfgs_block(best, np.arange(N), 100, pol_end,
                               fun=_fun_grad_tie)
            consider(pol, "final tie polish")
            pw = _peak_window_polish(best, pol_end, 60)
            consider(pw, "final peak-window")

    if start is not None and bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    Lf = _knots(best)
    mx = Lf.max()
    mm = best.mean() if best.mean() > 0 else 1.0
    near5 = np.mean(Lf >= mx * 0.95)
    print("final R=%.12f (start %.12f, N=%d, ties=%d, max/mean=%.2f, 5%%-near=%.4f)"
          % (bestR, startR, best.size, _tie_count(best), best.max() / mm, near5))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, deadline, alpha=0.1, maxiter=200):
    return _lbfgs_custom(h0, lambda h: _fun_grad_cvar(h, alpha),
                         deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _upsample(h, factor):
    """Split each step into `factor` equal sub-steps (piecewise-constant)."""
    if factor <= 1:
        return h.copy()
    return np.repeat(h, factor).astype(float)


def _mutate_perturb(h, rng, scale):
    """Multiplicative random perturbation on a block, then rescale."""
    h2 = h.copy()
    n = h2.size
    w = max(8, n // 20)
    c = rng.integers(0, n)
    lo = max(0, c - w // 2)
    hi = min(n, lo + w)
    noise = np.exp(rng.normal(0.0, scale, hi - lo))
    h2[lo:hi] *= noise
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # New idea: refine on an upsampled grid. The optimum is piecewise-smooth
    # with sharp corners; a finer raster lets L-BFGS find a better shape than
    # the current N allows, then we keep whichever R is better.
    cands = []
    for factor in (2, 3):
        if time.process_time() > deadline - 3.0:
            break
        h_up = _upsample(best, factor)
        if h_up.size > 1000000:
            continue
        tlim = min(deadline - 1.0, time.process_time() + (deadline - time.process_time()) * 0.35)
        h_p = _full_lbfgs(h_up, tlim, maxiter=200)
        Rp = R_of(h_p)
        print("upsample x%d: R=%.9f (N=%d)" % (factor, Rp, h_p.size))
        if Rp > bestR + 1e-13:
            best = h_p
            bestR = Rp
        cands.append((Rp, h_p))

    # CVaR-surrogate ascent on the current best (smoothes the tie flat region)
    alphas = [0.25, 0.12, 0.05]
    for a in alphas:
        if time.process_time() > deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + (deadline - time.process_time()) * 0.3)
        h_try = _cvar_lbfgs(best, tlim, alpha=a, maxiter=120)
        Rt = R_of(h_try)
        if Rt > bestR + 1e-13:
            best = h_try
            bestR = Rt
            print("cvar a=%.2f R=%.9f" % (a, bestR))
        # polish
        if time.process_time() < deadline - 0.5:
            tlim = min(deadline - 0.4, time.process_time() + 4.0)
            h_p = _full_lbfgs(best, tlim, maxiter=100)
            Rp = R_of(h_p)
            if Rp > bestR + 1e-13:
                best = h_p
                bestR = Rp

    # Random perturbations to escape local minima, then polish.
    tries = 0
    while time.process_time() < deadline - 2.0 and tries < 20:
        tries += 1
        scale = 0.02 * (1.5 ** (tries % 4))
        h_m = _mutate_perturb(best, rng, scale)
        tlim = min(deadline - 1.0, time.process_time() + 2.5)
        h_p = _full_lbfgs(h_m, tlim, maxiter=80)
        Rp = R_of(h_p)
        if Rp > bestR + 1e-13:
            best = h_p
            bestR = Rp
            print("perturb t=%d scale=%.3f R=%.9f" % (tries, scale, bestR))

    # Peak polish
    if time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.8, time.process_time() + 4.0)
        h_pk = _peak_window_polish(best, tlim, pad=3)
        rp = R_of(h_pk)
        if rp > bestR + 1e-15:
            best = h_pk
            bestR = rp
            print("peak polish: R=%.9f" % bestR)

    # Final full tie polish
    if time.process_time() < deadline - 0.8:
        tlim = min(deadline - 0.5, time.process_time() + 5.0)
        h_full = _full_lbfgs(best, tlim, maxiter=250)
        rf = R_of(h_full)
        if rf > bestR + 1e-15:
            best = h_full
            bestR = rf

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if bestR < startR:
        return {"best": start_best, "alternative": best}
    return {"best": best, "alternative": start_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        st = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[st:st + L] *= fac
    return c2


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _coarse(c_in, m):
    n = c_in.size
    if m == n:
        return c_in.copy()
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 * (n / m)
    xi = np.arange(n, dtype=float) + 0.5
    return np.interp(x, xi, c_in)


def _prolong(c_coarse, m_out):
    m = c_coarse.size
    if m_out == m:
        return c_coarse.copy()
    x = np.linspace(0.0, m, m_out, endpoint=False) + 0.5 * (m_out / m)
    xi = np.arange(m, dtype=float) + 0.5
    return np.interp(x, xi, c_coarse)


def _polish_c(c, p, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return c, R_of(np.repeat(c, p))
    h = _rescale(np.repeat(c, p))
    h2 = _lbfgs_block(h, np.arange(h.size), maxiter, deadline, tie=tie)
    c2 = h2.reshape(-1, p).mean(axis=1)
    return c2, R_of(np.repeat(c2, p))


def _vcycle(best, bestR, p, c, deadline, levels):
    n_c = c.size
    coarse_list = [(n_c, c.copy())]
    cur = c
    for m in levels[1:]:
        cur = _coarse(cur, m)
        coarse_list.append((m, cur.copy()))
    m, cc = coarse_list[-1]
    cc, r = _polish_c(cc, p, 80, min(deadline, time.process_time() + 3.0))
    coarse_list[-1] = (m, cc)
    print("  vcycle level=%d R=%.9f" % (m, r))
    if r > bestR + 1e-15:
        best = _rescale(np.repeat(cc, p)); bestR = r
    for i in range(len(coarse_list) - 2, -1, -1):
        m_out, _ = coarse_list[i]
        cc = _prolong(cc, m_out)
        cc, r = _polish_c(cc, p, 100,
                          min(deadline, time.process_time() + 4.0))
        coarse_list[i] = (m_out, cc)
        print("  vcycle level=%d R=%.9f" % (m_out, r))
        if r > bestR + 1e-15:
            best = _rescale(np.repeat(cc, p)); bestR = r
    return best, bestR, cc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- Phase V: multi-resolution V-cycles ----
    v_end = t0 + (deadline - t0) * 0.50 + t0
    if p > 1 and c.size >= 4 and time.process_time() < v_end - 3.0:
        n_c = c.size
        levels = [n_c]
        m = n_c
        while len(levels) < 3 and m > 8:
            m = max(8, m // 4)
            if m >= levels[-1]:
                break
            levels.append(m)
        print("vcycle levels=%s" % levels)
        cycle = 0
        while time.process_time() < v_end - 3.0:
            cycle += 1
            print("vcycle cycle=%d" % cycle)
            best, bestR, c = _vcycle(best, bestR, p, c, v_end, levels)
            print("vcycle cycle=%d done bestR=%.9f" % (cycle, bestR))
            if cycle >= 2 and time.process_time() > v_end - 6.0:
                break

    # ---- Phase A: coarse jitter + repolish ----
    a_end = t0 + (deadline - t0) * 0.62 + t0
    if time.process_time() < a_end - 0.5:
        rng = np.random.default_rng(12345)
        c_best = c.copy()
        cR = R_of(np.repeat(c_best, p)) if p > 1 else R_of(c_best)
        accepted = 0
        rounds = 0
        while time.process_time() < a_end - 0.5:
            rounds += 1
            cj = _jitter(c_best, rng)
            cj = _lbfgs_log(cj, 150, min(a_end - 0.3,
                                         time.process_time() + 1.5))
            rj = R_of(np.repeat(cj, p)) if p > 1 else R_of(cj)
            if rj > cR + 1e-15:
                c_best, cR = cj, rj
                accepted += 1
        print("PhaseA rounds=%d accepted=%d cR=%.9f" % (rounds, accepted, cR))
        if cR > bestR + 1e-15:
            best = _rescale(np.repeat(c_best, p)) if p > 1 else _rescale(c_best)
            bestR = cR
            c = c_best

    # ---- Phase B: interpolating lift ladder ----
    b_end = t0 + (deadline - t0) * 0.74 + t0
    cur = c.copy()
    curR = R_of(np.repeat(cur, p)) if p > 1 else R_of(cur)
    for step in range(4):
        if time.process_time() >= b_end - 1.0:
            break
        if cur.size * 2 > 300000:
            break
        lifted = _interp_lift(cur)
        lifted = _lbfgs_log(lifted, 200, min(b_end - 0.5,
                                             time.process_time() + 6.0))
        rl = R_of(lifted)
        win = _peak_window(lifted, pad_frac=0.03, extra=64)
        polished = _lbfgs_block(lifted, win, 200,
                                min(b_end - 0.3,
                                    time.process_time() + 3.0), tie=True)
        rp = R_of(polished)
        if rp > rl:
            lifted, rl = polished, rp
        print("lift step=%d n=%d R=%.9f (cur %.9f)" % (step, lifted.size, rl, curR))
        if rl > curR + 1e-15:
            cur, curR = lifted, rl
        else:
            break

    # ---- Phase C: lift back to full N ----
    n_target = best.size
    if cur.size != n_target:
        if n_target % cur.size == 0:
            fac = n_target // cur.size
            full = np.repeat(cur, fac)
        else:
            full = np.interp(np.linspace(0, cur.size - 1, n_target),
                             np.arange(cur.size), cur)
    else:
        full = cur
    full = _rescale(full)
    rfull = R_of(full)
    if rfull > bestR + 1e-15:
        best, bestR = full.copy(), rfull
        print("lift ACCEPT R=%.9f" % bestR)

    # ---- Phase E: aggressive final peak polish with sliding windows ----
    c_end = deadline
    pad_seq = (0.10, 0.06, 0.04, 0.025, 0.015, 0.008, 0.004)
    for pad in pad_seq:
        if time.process_time() >= c_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400,
                          min(c_end - 0.5, time.process_time() + 4.0),
                          tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---- Phase F: full log-space polish if time remains ----
    if time.process_time() < c_end - 1.5:
        ht = _lbfgs_log(best, 200, c_end - 1.0)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        print("final log polish R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad(hh)) if beta <= 0 else None

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_ladder(h, deadline, betas=(0.0,), iters=300):
    for beta in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _deficit_free(h, frac=0.15):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(h.size)
    gLf = (M - 2.0 * Lf) / M
    s = np.abs(_backprop(gLf, h))
    N = h.size
    k = max(1, int(frac * N))
    if k >= N:
        return np.arange(N)
    idx = np.argpartition(-s, k - 1)[:k]
    return np.sort(idx)


def _peak_free(h, frac=0.25):
    """Elements whose associated knot sits near the max: these control ||f*f||_inf."""
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(h.size)
    # gradient of max wrt knots: -1 near peak (want lower), + elsewhere
    # Free set: elements touching near-max knots (they raise the peak when grown)
    idx = np.flatnonzero(Lf >= 0.97 * M)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size, idx.max() + 1)
    return np.arange(lo, hi)


def _fold_back(h_fine, n_target):
    n = h_fine.size
    if n == n_target:
        return h_fine.copy()
    cm = np.cumsum(h_fine)
    if cm[-1] <= 0:
        return np.zeros(n_target)
    cm = cm / cm[-1]
    t = (np.arange(n_target) + 0.5) / n_target
    idx = np.searchsorted(cm, t)
    idx = np.clip(idx, 0, n - 1)
    return h_fine[idx].astype(float)


def _upsample_blocks(h, factor):
    return np.repeat(h, factor).astype(float)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s)" % (bestR, tag))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase 1: coarse (half-res) polish, then lift. This is the classic
    # "denoise at lower N then refine" move. ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.15
        work_c = c.copy()
        while time.process_time() < half_deadline - 1.0:
            work_c = _polish_ladder(work_c, half_deadline, iters=300)
            work_c = _peak_ladder(work_c, half_deadline,
                                  pads=(0.30, 0.20, 0.15, 0.10, 0.08), iters=400)
        h_lift = _rescale(np.repeat(work_c, 2))
        h_lift = _polish_ladder(h_lift, deadline, iters=300)
        offer(h_lift, 'lift')

    # ---- Phase 2: peak-boundary polish (controls ||f*f||_inf tightly). ----
    # The ratio is most sensitive to the maximum; free only the elements
    # whose knots are near the peak and let them re-balance.
    if time.process_time() < deadline - 3.0:
        for rnd in range(3):
            if time.process_time() >= deadline - 3.0:
                break
            free = _peak_free(best, frac=0.25)
            if free.size == 0:
                break
            ht = _lbfgs_block(best, free, 400, deadline - 1.0)
            if not offer(ht, 'peak_%d' % rnd):
                if rnd >= 1:
                    break

    # ---- Phase 3: deficit-sensitivity rounds. ----
    deficit_deadline = deadline - 8.0
    for rnd in range(4):
        if time.process_time() >= deficit_deadline - 2.0:
            break
        free = _deficit_free(best, frac=0.15)
        if free.size == 0:
            continue
        ht = _lbfgs_block(best, free, 400, deficit_deadline)
        ht = _peak_ladder(ht, deficit_deadline, pads=(0.08, 0.05), iters=250)
        r = R_of(ht)
        improved = offer(ht, 'deficit_%d' % rnd)
        print("deficit round=%d freed=%d R=%.9f (best %.9f) improved=%s"
              % (rnd, free.size, r, bestR, improved))
        if not improved and rnd >= 2:
            break

    # ---- Phase 4: full polish ladder. ----
    if time.process_time() < deadline - 3.0:
        ht = _polish_ladder(best, deadline - 1.0, iters=400)
        offer(ht, 'full')

    # ---- Phase 5: upsampled fine polish. The start N (~105k) is large, and
    # the true optimum is likely at higher resolution. Doubling once and
    # polishing at the finer grid can find extra mass distribution. ----
    if best.size * 2 <= 1000000 and time.process_time() < deadline - 5.0:
        fine = _upsample_blocks(best, 2)
        # polish fine grid briefly
        fine_deadline = deadline - 1.0
        fine = _polish_ladder(fine, fine_deadline, iters=200)
        fine = _peak_ladder(fine, fine_deadline, pads=(0.06, 0.04), iters=200)
        r = R_of(fine)
        print("fine N=%d R=%.9f (best %.9f)" % (fine.size, r, bestR))
        if r > bestR + 1e-14:
            # fold back to original size to preserve N, keep as best
            folded = _fold_back(fine, best.size)
            folded = _rescale(folded)
            fr = R_of(folded)
            if fr > bestR + 1e-14:
                best, bestR = folded, fr
                print("NEW BEST (fine-fold) R=%.9f" % bestR)
            # keep fine as alternative if genuinely different
            if r > alt_bestR:
                alt_best, alt_bestR = fine.copy(), r

    # ---- Final peak polish. ----
    ht2 = _peak_ladder(best, deadline - 0.5, pads=(0.06, 0.04), iters=250)
    if R_of(ht2) > bestR + 1e-14:
        best, bestR = ht2.copy(), R_of(ht2)
        print("NEW BEST (finalpeak) R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d)" % (bestR, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter, beta):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    hh = h.copy()
    if free.size == 0:
        return h
    n_all = h.size
    active = free

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        h2 = hh.copy()
        h2[active] = np.exp(uu)
        val, g = _fun_grad_beta(h2, beta)
        return val, g[active] * h2[active]

    u0 = np.log(np.clip(hh[active], 1e-300, None))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = hh.copy()
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _reparameterise(h, newN):
    n = h.size
    if n == newN:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    xs = np.linspace(0.0, total, newN + 1)
    ys = np.interp(xs, c, np.arange(n + 1, dtype=float))
    hn = np.diff(ys) * (n / newN)
    return np.clip(hn, 0.0, None)


def _jitter(h, rng):
    n = h.size
    h2 = h.copy()
    nblocks = rng.integers(2, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        s = int(rng.integers(0, n - L + 1))
        env = np.cos(np.linspace(-np.pi / 2, np.pi / 2, L)) ** 2
        fac = np.exp(rng.normal(0.0, 0.05, size=L))
        h2[s:s + L] *= (1.0 + (fac - 1.0) * env)
    return np.clip(h2, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    def _tie_polish(h0, iters, betas, dl):
        h = h0
        r = R_of(h)
        for beta in betas:
            if time.process_time() >= dl - 1.0:
                break
            ht = _lbfgs_log(h, iters, dl, beta)
            rt = R_of(ht)
            if rt > r:
                h, r = ht, rt
        return h, r

    # A: tie-aware polish on start
    if time.process_time() < deadline - 8.0:
        h, r = _tie_polish(best, 400, (0.0, 1e5, 1e7), min(deadline, t0 + 8.0))
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("A tie-polish R=%.7f" % bestR)
        for frac, pad in ((0.05, 32), (0.02, 16)):
            if time.process_time() >= deadline - 6.0:
                break
            hp = _window_polish_peak(best, deadline, frac, pad, 200, 0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("A peak frac=%.2f R=%.7f" % (frac, rp))

    # B: coarse ladder (quick)
    levels = [1024, 2048, 4096, 8192, 16384]
    level_bests = {}

    def _coarse_search(h_level, level_deadline, iters=250):
        h = h_level
        r = R_of(h)
        ht = _lbfgs_log(h, iters, deadline=level_deadline, beta=0.0)
        rt = R_of(ht)
        if rt > r:
            h, r = ht, rt
        accepted = 0
        rounds = 0
        while time.process_time() < level_deadline - 0.5 and rounds < 25:
            rounds += 1
            hj = _rescale(_jitter(h, rng))
            rj = R_of(hj)
            if rj > r - 0.002:
                ht = _lbfgs_log(hj, 120, level_deadline, 0.0)
                rt = R_of(ht)
                if rt > r + 1e-13:
                    h, r = ht, rt
                    accepted += 1
        return h, r, accepted

    if time.process_time() < deadline - 20.0:
        tB_start = time.process_time()
        tB_end = min(deadline - 15.0, tB_start + 20.0)
        per_level = (tB_end - tB_start) / len(levels)
        cur_best = best
        cur_bestR = bestR
        for N in levels:
            if time.process_time() >= tB_end - 1.0:
                break
            level_deadline = min(tB_end, time.process_time() + per_level)
            hN = _rescale(_reparameterise(cur_best, N))
            rN0 = R_of(hN)
            hN, rN, acc = _coarse_search(hN, level_deadline)
            level_bests[N] = (hN.copy(), rN)
            hl = _rescale(_reparameterise(hN, cur_best.size))
            hl = _lbfgs_log(hl, 100, deadline, 0.0)
            rl = R_of(hl)
            print("B N=%d R %.7f->%.7f acc=%d lift=%.7f" %
                  (N, rN0, rN, acc, rl))
            if rl > cur_bestR + 1e-13:
                cur_best, cur_bestR = hl, rl
                if rl > bestR + 1e-13:
                    best, bestR = hl, rl

    # C: prolongate best coarse back to full N
    fullN = start_best.size
    if level_bests and time.process_time() < deadline - 8.0:
        best_lvl = max(level_bests.items(), key=lambda kv: kv[1][1])
        hc = _rescale(_reparameterise(best_lvl[1][0], fullN))
        rc = R_of(hc)
        hc, rc = _tie_polish(hc, 400, (0.0, 1e5, 1e7),
                             min(deadline - 5.0, time.process_time() + 6.0))
        print("C prolongate from N=%d R=%.7f" % (best_lvl[0], rc))
        if rc > bestR + 1e-13:
            best, bestR = hc, rc
        for frac, pad in ((0.2, 32), (0.1, 32), (0.05, 32), (0.02, 16), (0.01, 16)):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(best, deadline, frac, pad, 200, 0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("C peak frac=%.2f R=%.7f" % (frac, rp))

    # D: focused peak-window polish, cycling widths down to tiny scales
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        fracs = (0.02, 0.01, 0.005, 0.002)
        improved = False
        for frac in fracs:
            if time.process_time() >= deadline - 2.0:
                break
            hp = _window_polish_peak(best, deadline, frac, 8, 120, 0.0)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                improved = True
                print("D peak frac=%.3f #%d R=%.7f" % (frac, it, bestR))
        if not improved:
            # occasional jitter kick to escape
            hj = _rescale(_jitter(best, rng))
            rj = R_of(hj)
            if rj > bestR - 0.002:
                ht = _lbfgs_log(hj, 150, deadline, 0.0)
                rt = R_of(ht)
                if rt > bestR + 1e-13:
                    best, bestR = ht, rt
                    print("D jitter #%d R=%.7f" % (it, bestR))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_smooth(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, fun_grad, deadline, maxiter=150, lo=-40.0, hi=40.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(np.clip(u, lo, hi))
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(lo, hi)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, lo, hi))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_log(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _smooth_anneal(h, deadline, betas=(2.0, 1.0, 0.5, 0.25, 0.1)):
    for beta in betas:
        if time.process_time() >= deadline - 2.0:
            break
        h2 = _lbfgs_log(h, lambda hh: _fun_grad_smooth(hh, beta), deadline, maxiter=200)
        if R_of(h2) >= R_of(h) - 1e-10:
            h = h2
    return h


def _peak_window_polish(h, deadline, pad=3, frac=8, maxiter=100):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    free = np.arange(lo, hi)
    h2 = h.copy()
    # optimize only free block via masked log-param
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[free], floor, None))

    def f(u):
        hh = h.copy()
        hh[free] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = _fun_grad_tie(hh)
        return val, g[free] * hh[free]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * free.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2[free] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _refine_resample(h, factor):
    """Upsample then downsample to equal total, keeping shape."""
    n = h.size
    m = int(n * factor)
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(m) + 0.5) / m
    C = np.concatenate(([0.0], np.cumsum(h)))
    Cq = np.interp(x_new, x_old, np.interp(x_old, np.arange(n + 1) / n, C))
    g = np.diff(np.concatenate(([0.0], Cq)))
    return np.clip(g, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    start_best = best.copy()
    start_R = bestR
    alt = None
    altR = 0.0

    # Phase 1: smooth-max homotopy from the start
    if time.process_time() < deadline - 10.0:
        h = _smooth_anneal(best.copy(), deadline)
        r = R_of(h)
        if r > altR:
            alt, altR = h.copy(), r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("homotopy R=%.7f" % bestR)

    # Phase 2: peak-window polish with growing windows
    for frac in (8, 5, 3, 2):
        if time.process_time() >= deadline - 2.0:
            break
        h = _peak_window_polish(best, deadline, pad=3 + 2 * (8 // frac), frac=frac)
        h = _full_lbfgs(h, deadline, maxiter=120)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(1/%d) R=%.7f" % (frac, bestR))

    # Phase 3: phase shifts
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _rescale(_phase_shift(best, delta))
        if hp.sum() <= 0:
            continue
        hp = _full_lbfgs(hp, deadline, maxiter=200)
        hp = _peak_window_polish(hp, deadline, pad=6, frac=4)
        r = R_of(hp)
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("phase %+.2f R=%.7f" % (delta, bestR))

    # Phase 4: alternating full / window polish
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _full_lbfgs(best, deadline, maxiter=200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _peak_window_polish(best, deadline, pad=6, frac=4)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and altR > 0 and bestR <= start_R + 1e-15:
        return {"best": start_best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True,
                 alpha=0.0, logparam=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0

    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif alpha > 0:
        fg = (lambda hh: _fun_grad_cvar(hh, alpha))
    else:
        fg = _fun_grad_tie

    if logparam:
        pos = active[h[active] > 1e-14 * max(h.max(), 1e-30)]
        if pos.size == 0:
            return h0
        floor = 1e-10 * h.max()
        u0 = np.log(np.clip(h[pos], floor, None))

        def f(u):
            hh = h.copy()
            hh[pos] = np.exp(u)
            val, g = fg(hh)
            return val, g[pos] * hh[pos]

        cb = _make_cb(deadline - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * pos.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return h0
        if res is None:
            return h0
        h2 = h.copy()
        h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
        return _rescale(h2)

    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _upsample_fft(h, k):
    n = h.size
    if k <= 1:
        return h.copy()
    m = n * k
    H = np.fft.rfft(h)
    out = np.fft.irfft(H, m) * (m / n)
    s_in = h.sum()
    s_out = out.sum()
    if s_out > 0:
        out *= s_in / s_out
    return np.clip(out, 0.0, None)


def _upsample_lin(h, k):
    n = h.size
    if k <= 1:
        return h.copy()
    x = np.linspace(0.0, n - 1.0, n * k)
    out = np.interp(x, np.arange(n, dtype=float), h)
    return np.clip(out, 0.0, None)


def _peak_window(h, frac=0.5, pad=64):
    """Return indices around the peak region of f*f, sized to include enough
    of the near-peak plateau to matter for R, plus padding."""
    Lf = _knots(h)
    n = h.size
    mx = Lf.max()
    if mx <= 0:
        return np.arange(n)
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return np.arange(n)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    span = hi - lo
    extra = max(pad, int(span * frac))
    lo = max(0, lo - extra)
    hi = min(n - 1, hi + extra)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    best = None
    startR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("start R=%.9f N=%d ties=%d" % (bestR, best.size, _tie_count(best)))

    # Phase A (new idea): exploit the near-peak plateau by directly optimizing
    # a *weighted* objective that pushes down the largest f*f knots while
    # keeping the mass. We sweep through beta (smooth-max) values starting
    # from a moderate window, then expand.
    pA_end = t0 + budget_seconds * 0.40
    if time.process_time() < pA_end - 2.0:
        # start with a moderate peak window at current resolution
        for frac, pad in ((0.6, 128), (0.4, 96), (0.25, 64)):
            if time.process_time() >= pA_end - 2.0:
                break
            win = _peak_window(best, frac=frac, pad=pad)
            if win.size < 8:
                win = np.arange(best.size)
            for beta in (1e4, 1e5, 1e6, 1e7):
                if time.process_time() >= pA_end - 1.5:
                    break
                ht = _lbfgs_block(best, win, 250,
                                  min(pA_end - 1.0,
                                      time.process_time() + 4.0),
                                  beta=beta)
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r
        # finish with pure tie objective
        for frac, pad in ((0.2, 48), (0.1, 32)):
            if time.process_time() >= pA_end - 1.5:
                break
            win = _peak_window(best, frac=frac, pad=pad)
            ht = _lbfgs_block(best, win, 300,
                              min(pA_end - 1.0, time.process_time() + 5.0),
                              tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
            ht = _lbfgs_block(best, win, 300,
                              min(pA_end - 1.0, time.process_time() + 5.0),
                              tie=True, logparam=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("phaseA R=%.9f" % bestR)

    # Phase B: upsample with FFT (smooth), and re-polish near-peak region.
    # This is where most gains come from: a finer grid resolves the near-peak
    # plateau, letting the peak knots become equal.
    pB_end = t0 + budget_seconds * 0.72
    for k in (2, 2, 3):
        if time.process_time() >= pB_end - 3.0:
            break
        if best.size * k > 900000:
            continue
        hu = _upsample_fft(best, k)
        if hu.size == best.size:
            continue
        # polish whole thing with smooth-max, then tie
        ht = _lbfgs_block(hu, np.arange(hu.size), 200,
                          min(pB_end - 1.0, time.process_time() + 6.0),
                          beta=1e6)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            hu = ht
        else:
            hu = best if best.size == hu.size else hu
        # peak-window polish
        for frac, pad in ((0.5, 64), (0.25, 48), (0.12, 32)):
            if time.process_time() >= pB_end - 1.5:
                break
            win = _peak_window(hu, frac=frac, pad=pad)
            ht = _lbfgs_block(hu, win, 250,
                              min(pB_end - 1.0, time.process_time() + 5.0),
                              tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                hu = ht
            ht = _lbfgs_block(hu, win, 250,
                              min(pB_end - 1.0, time.process_time() + 5.0),
                              tie=True, logparam=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                hu = ht
        print("phaseB k=%d R=%.9f N=%d ties=%d"
              % (k, bestR, best.size, _tie_count(best)))

    # Phase C: alternating full tie polish + peak-window polish. This is the
    # final squeeze. Keep going until time runs out.
    fd = t0 + budget_seconds * 0.985
    cyc = 0
    while time.process_time() < fd - 1.5:
        cyc += 1
        prevR = bestR
        # full tie polish (short)
        ht = _lbfgs_block(best, np.arange(best.size), 120,
                          min(fd - 1.0, time.process_time() + 4.0),
                          tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        # peak-window
        for frac, pad in ((0.15, 32), (0.08, 24)):
            if time.process_time() >= fd - 1.0:
                break
            win = _peak_window(best, frac=frac, pad=pad)
            ht = _lbfgs_block(best, win, 250,
                              min(fd - 0.8, time.process_time() + 3.5),
                              tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
            ht = _lbfgs_block(best, win, 250,
                              min(fd - 0.8, time.process_time() + 3.5),
                              tie=True, logparam=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        if bestR - prevR < 1e-13 and cyc > 3:
            # try one more upsample as a last resort
            if best.size * 2 <= 900000 and time.process_time() < fd - 5.0:
                hu = _upsample_fft(best, 2)
                ht = _lbfgs_block(hu, np.arange(hu.size), 200,
                                  min(fd - 1.0, time.process_time() + 5.0),
                                  beta=1e6)
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r
                else:
                    break
            else:
                break
        print("phaseC cyc=%d R=%.9f" % (cyc, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_v(h0, fun_grad, deadline, maxiter=80):
    """L-BFGS-B in h = v^2 unconstrained parameterisation."""
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    v0 = np.sqrt(h)

    def f(v):
        hh = v * v
        val, g = fun_grad(hh)
        return val, g * 2.0 * v

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, v0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * v0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = res.x * res.x
    return _rescale(h2)


def _peak_window_polish(h, deadline, pad_frac=0.2):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    pad = max(3, int(pad_frac * n / 2))
    lo = max(0, int(c) - pad)
    hi = min(n, int(c) + pad)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alphas = [0.30, 0.20, 0.12, 0.06, 0.03, 0.015, 0.008, 0.004]
    pads = [0.20, 0.10, 0.05, 0.02]

    def run_ladder(hcur):
        nonlocal best, bestR
        h = hcur
        for a in alphas:
            if time.process_time() >= deadline - 1.0:
                return h
            tlim = min(deadline - 1.0, time.process_time() + 3.0)
            h = _lbfgs_v(h, lambda hh, aa=a: _fun_grad_cvar(hh, aa),
                         tlim, maxiter=80)
            rc = R_of(h)
            if rc > bestR:
                best = h.copy(); bestR = rc
        # exact tie polish
        if time.process_time() < deadline - 1.0:
            tlim = min(deadline - 1.0, time.process_time() + 3.0)
            h = _lbfgs_v(h, _fun_grad_tie, tlim, maxiter=60)
            rc = R_of(h)
            if rc > bestR:
                best = h.copy(); bestR = rc
        # peak-window polish with shrinking pad
        for pf in pads:
            if time.process_time() >= deadline - 1.0:
                break
            tlim = min(deadline - 1.0, time.process_time() + 1.5)
            h = _peak_window_polish(h, tlim, pad_frac=pf)
            rc = R_of(h)
            if rc > bestR:
                best = h.copy(); bestR = rc
        return h

    hcur = best.copy()
    rnd = 0
    while time.process_time() < deadline - 1.0:
        rnd += 1
        hcur = run_ladder(hcur)
        print("ladder rnd=%d R=%.12f (best %.12f)" % (rnd, R_of(hcur), bestR))
        if rnd >= 2 and time.process_time() >= deadline - 8.0:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _upsample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return h.copy()
    c /= total
    newn = n * factor
    newx = np.arange(newn + 1, dtype=float) * (n / float(newn))
    cv = np.interp(newx, np.arange(n + 1, dtype=float), c)
    out = np.diff(cv)
    return np.clip(out, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR
    expH = baseH.copy()
    expR = baseR

    def maybe(hcand):
        nonlocal bestH, bestR, expH, expR
        rc = R_of(hcand)
        if rc > bestR + 1e-15:
            bestH, bestR = hcand.copy(), rc
        if rc > expR + 1e-15:
            expH, expR = hcand.copy(), rc
        return rc

    # ---- Key new idea: try multiple resolutions with finer upsampling ----
    # The peak of f*f is a smooth bump; resolving it well matters. Try
    # upsampling by factors 2 and 3 and re-optimizing, keeping whichever
    # resolution actually maximizes R.
    n = bestH.size
    for factor in (2, 3):
        if time.process_time() >= deadline - 8.0:
            break
        if n * factor > 1_000_000:
            continue
        hd = _rescale(_upsample(bestH, factor))
        rd = R_of(hd)
        print("  [up%d] raw R=%.9f (delta %.2e)" % (factor, rd, rd - baseR))
        cap = min(deadline - 6.0, time.process_time() + 5.0)
        hp = _lbfgs_log(hd, 120, cap, _fun_grad_tie)
        rp = R_of(hp)
        print("  [up%d] polished R=%.9f" % (factor, rp))
        maybe(hp)

    # ---- Main alternating loop: block polishing + beta ladder ----
    if time.process_time() < deadline - 4.0:
        cap = min(deadline - 2.0, time.process_time() + 6.0)
        hp = _lbfgs_log(bestH, 200, cap, _fun_grad_tie)
        maybe(hp)
        print("  [polish0] R=%.9f" % bestR)

    improved_round = 0
    while time.process_time() < deadline - 3.0 and improved_round < 8:
        improved_round += 1
        prevR = bestR
        for frac in (0.02, 0.05, 0.10, 0.20, 0.35):
            if time.process_time() >= deadline - 2.0:
                break
            free = _peak_window(bestH, frac=frac)
            cap = min(deadline - 1.0, time.process_time() + 1.5)
            hb = _lbfgs_block(bestH, free, 120, cap, _fun_grad_tie)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                bestH, bestR = hb.copy(), rb
                maybe(hb)
                print("  [peak %.2f] R=%.9f (+%.2e)" % (frac, bestR, bestR - prevR))
        if time.process_time() < deadline - 4.0 and improved_round % 2 == 0:
            for beta in (1e3, 1e4):
                cap = min(deadline - 1.0, time.process_time() + 1.5)
                hs = _lbfgs_log(bestH, 150, cap,
                                lambda hh, b=beta: _fun_grad_beta(hh, b))
                rs = R_of(hs)
                if rs > bestR + 1e-15:
                    bestH, bestR = hs.copy(), rs
                    maybe(hs)
                    print("  [beta %.0e] R=%.9f" % (beta, bestR))
        if bestR - prevR < 1e-11:
            break

    # ---- Final full polish ----
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 200, cap, _fun_grad_tie)
        maybe(hs)
        if R_of(hs) > bestR:
            bestH, bestR = hs, R_of(hs)

    print("final R=%.9f (base %.9f, delta %.2e)" %
          (bestR, baseR, bestR - baseR))
    mx, m, near = _stats(bestH)

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        return {"best": baseH, "alternative": expH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, active, maxiter, deadline, mode='plain', beta=0.0):
    if time.process_time() >= deadline - 0.05:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    if mode == 'tie':
        fg = _fun_grad_tie
    elif mode == 'beta':
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.05)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = h.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)
    except Exception:
        return h0


def _upsample_mass(h, N2):
    N = len(h)
    c = np.concatenate([[0.0], np.cumsum(h)])
    xs = np.arange(N2 + 1) * (N / N2)
    cm = np.interp(xs, np.arange(N + 1), c)
    new = np.diff(cm) * (N2 / N)
    if new.sum() <= 0:
        return np.ones(N2)
    return np.clip(new, 0, None)


def _half(h):
    # coarsen by factor 2 with mass conservation
    N = len(h)
    if N < 2:
        return h.copy()
    hh = h[: (N // 2) * 2].reshape(-1, 2).sum(axis=1)
    return _rescale(hh)


def _doubling_ladder(h_acc, deadline, consider, log):
    """Repeatedly double support with genuine per-level optimization,
    keeping the best at each scale and moving up."""
    while time.process_time() < deadline - 3 and h_acc.size < 1_000_000:
        N2 = min(h_acc.size * 2, 1_000_000)
        if N2 <= h_acc.size:
            break
        h2 = _upsample_mass(h_acc, N2)
        h2 = _rescale(h2)
        level_deadline = min(deadline - 2.5,
                             time.process_time() + 8.0)
        # short local passes on the doubled version
        for mode, beta in (('beta', 1e3), ('beta', 1e5), ('tie', 0.0)):
            if time.process_time() >= level_deadline:
                break
            d = min(level_deadline, time.process_time() + 2.5)
            nxt = _lbfgs(h2, np.arange(h2.size), 150, d, mode=mode, beta=beta)
            if R_of(nxt) > R_of(h2):
                h2 = nxt
        r2 = R_of(h2)
        r_acc = R_of(h_acc)
        log(f"double N={h2.size} R={r2:.6f} (cur {r_acc:.6f})")
        if r2 > r_acc:
            h_acc = h2
            consider(h_acc)
        else:
            # even if not better, keep growing at same scale to explore finer
            # resolution: accept structurally, but only *report* better ones
            h_acc = h2 if r2 > r_acc - 5e-4 else h_acc
            if h_acc is not h2:
                break
    return h_acc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    best = np.ones(50)
    best_R = R_of(best)
    if start is not None:
        try:
            s = np.asarray(start, dtype=float)
            r = R_of(s)
            if r > best_R:
                best = s.copy(); best_R = r
        except Exception:
            pass

    def consider(h):
        nonlocal best, best_R
        if h is None:
            return False
        h = np.asarray(h, dtype=float)
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return False
        r = R_of(h)
        if r > best_R:
            best_R = r
            best = h.copy()
            return True
        return False

    def log(msg):
        print(msg)

    # Phase 1: refine start with local L-BFGS tie-averaged
    cur = best.copy()
    for _ in range(2):
        if time.process_time() > deadline - 2:
            break
        d = min(deadline - 1.5, time.process_time() + 6.0)
        nxt = _lbfgs(cur, np.arange(cur.size), 300, d, mode='tie')
        if R_of(nxt) > R_of(cur):
            cur = nxt
        else:
            break
    consider(cur)

    # Phase 2: doubling ladder - this is the main change vs the start.
    # The start program stopped at 25600; here we keep doubling with a
    # real per-level optimization and only accept genuine improvements at
    # each scale, which lets the peak sharpen at finer resolution.
    h_acc = best.copy()
    log(f"ladder start N={h_acc.size} R={R_of(h_acc):.6f}")
    h_acc = _doubling_ladder(h_acc, deadline, consider, log)
    consider(h_acc)

    # Phase 3: half-scale refinement (go DOWN one level to escape plateau,
    # then re-optimize and go back up). This can move the peak position
    # relative to the start's fixed structure.
    if time.process_time() < deadline - 4 and h_acc.size >= 4:
        hh = _half(h_acc)
        d = min(deadline - 3, time.process_time() + 4.0)
        hh = _lbfgs(hh, np.arange(hh.size), 200, d, mode='tie')
        # re-double with local passes, continuing the ladder from half
        h_acc2 = _doubling_ladder(hh, deadline, consider, log)
        consider(h_acc2)

    # Phase 4: final full-array polish of best
    if time.process_time() < deadline - 1:
        d = deadline - 0.5
        nxt = _lbfgs(best, np.arange(best.size), 400, d, mode='tie')
        consider(nxt)

    if best is None:
        best = np.ones(50)
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-8))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


# ---------- Gauss-Newton on the near-max plateau ----------

def _Jd(h, d, A):
    if h.size > 1500:
        cd = fftconvolve(h, d)
    else:
        cd = np.convolve(h, d)
    return 2.0 * cd[A - 1]


def _JT(h, y, A, n):
    yp = np.zeros(2 * n - 1)
    valid = (A >= 1) & (A <= 2 * n - 1)
    idx = A[valid] - 1
    yp[idx] = y[valid]
    if n > 1500:
        c = fftconvolve(yp, h[::-1], mode='valid')
    else:
        c = np.correlate(yp, h, mode='valid')
    out = np.zeros(n)
    m = min(n, c.size)
    out[:m] = 2.0 * c[:m]
    return out


def _gn_step(h, kappa, lam_scale, deadline, cg_iters=80):
    n = h.size
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return None
    thresh = (1.0 - kappa) * mx
    A = np.flatnonzero(L >= thresh)
    A = A[(A >= 1) & (A <= 2 * n - 1)]
    if A.size == 0:
        return None
    r = L[A] - mx
    b = _JT(h, r, A, n)
    bn = np.linalg.norm(b)
    if bn <= 0:
        return None
    lam = lam_scale * bn
    d = np.zeros(n)
    res = b.copy()
    p = res.copy()
    rs = res @ res
    for it in range(cg_iters):
        if time.process_time() > deadline:
            break
        Jp = _Jd(h, p, A)
        Ap = _JT(h, Jp, A, n) + lam * p
        pAp = p @ Ap
        if pAp <= 1e-300:
            break
        alpha = rs / pAp
        d += alpha * p
        res -= alpha * Ap
        rs_new = res @ res
        if rs_new < 1e-22 * (b @ b):
            break
        beta = rs_new / rs
        p = res + beta * p
        rs = rs_new
    return d


def _gn_plateau(h, deadline):
    best = h.copy()
    bestR = R_of(best)
    kappas = [0.05, 0.02, 0.01, 0.005, 0.002]
    lams = [1e-6, 1e-4, 1e-2, 1e-1]
    while time.process_time() < deadline:
        improved = False
        for kappa in kappas:
            if time.process_time() >= deadline:
                break
            for lam in lams:
                if time.process_time() >= deadline:
                    break
                d = _gn_step(best, kappa, lam,
                             min(deadline, time.process_time() + 2.0))
                if d is None or not np.any(d):
                    continue
                alpha = 1.0
                for _ in range(24):
                    if time.process_time() > deadline:
                        break
                    hn = np.clip(best + alpha * d, 0.0, None)
                    if hn.sum() <= 0:
                        alpha *= 0.5
                        continue
                    rn = R_of(hn)
                    if rn > bestR + 1e-15:
                        best, bestR = hn, rn
                        improved = True
                        break
                    alpha *= 0.5
        if not improved:
            break
    return best, bestR


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    betas = [1.0, 5.0, 20.0, 80.0, 300.0, 1000.0]
    it = 0
    while time.process_time() < deadline - 0.5:
        it += 1
        improved = False

        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            cap = min(deadline - 0.3, time.process_time() + 3.0)
            fg = (lambda hh, b=beta: _fun_grad_beta(hh, b))
            hp = _lbfgs_log(best, 200, cap, fg)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                improved = True
                print("  beta=%.0f iter=%d R=%.9f" % (beta, it, bestR))

        if time.process_time() < deadline - 0.5:
            gn_cap = min(deadline - 0.3, time.process_time() + 4.0)
            gh, gr = _gn_plateau(best, gn_cap)
            if gr > bestR + 1e-15:
                best, bestR = gh, gr
                improved = True
                print("  GN iter=%d R=%.9f" % (it, bestR))

        if time.process_time() < deadline - 1.0:
            cap = min(deadline - 0.3, time.process_time() + 3.0)
            hp = _lbfgs_log(best, 200, cap, _fun_grad_tie)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                improved = True
                print("  hard iter=%d R=%.9f" % (it, bestR))

        if not improved:
            rng = np.random.default_rng(it)
            pert = best * (1.0 + 0.001 * rng.standard_normal(best.size))
            pert = _rescale(np.clip(pert, 0, None))
            rp = R_of(pert)
            if rp > bestR:
                best, bestR = pert, rp

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=200):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 100, 'maxfun': 200,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Direct polish of the start: full L-BFGS in log-space on ALL positive entries.
    # This is the main improvement: instead of spending most of the budget in coarse
    # g-space (which is lossy), polish the fine construction directly with a long
    # L-BFGS run, then alternate with windowed polishes around the peak.
    hc = h0.copy()

    # Phase 1: full fine L-BFGS
    tlim = min(deadline - 2.0, time.process_time() + budget_seconds * 0.45)
    if time.process_time() < tlim - 0.5:
        hc = _full_lbfgs(hc, tlim, maxiter=400)
    Rc = R_of(hc)
    print("phase1 R=%.9f" % Rc)
    if Rc > bestR:
        best = hc.copy(); bestR = Rc

    # Phase 2: alternate peak-window polish and full polish
    while time.process_time() < deadline - 1.5:
        tlim = min(deadline - 1.5, time.process_time() + 3.0)
        hc2 = _peak_window_polish(hc, tlim, pad=6)
        R2 = R_of(hc2)
        if R2 > Rc:
            hc = hc2; Rc = R2
        if time.process_time() >= deadline - 1.5:
            break
        tlim = min(deadline - 1.5, time.process_time() + 4.0)
        hc3 = _full_lbfgs(hc, tlim, maxiter=150)
        R3 = R_of(hc3)
        if R3 > Rc:
            hc = hc3; Rc = R3
        else:
            # no progress: break out and try wider peak window
            tlim = min(deadline - 1.5, time.process_time() + 3.0)
            hc4 = _peak_window_polish(hc, tlim, pad=20)
            R4 = R_of(hc4)
            if R4 > Rc:
                hc = hc4; Rc = R4
            else:
                break
        if Rc > bestR:
            best = hc.copy(); bestR = Rc
        print("iter R=%.9f" % Rc)

    if Rc > bestR:
        best = hc.copy(); bestR = Rc

    alt = hc.copy()
    if Rc > startR:
        best = hc
        bestR = Rc
    else:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_softmax(h, beta):
    """Smooth surrogate: replace log(max L) with log(sum exp(beta L))/beta."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    # softmax weights over knots
    z = beta * Lf
    z = z - z.max()
    e = np.exp(z)
    Z = e.sum()
    w = e / Z
    Lsm = Lf @ w  # smooth max approximation
    if Lsm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    # d/dLi [log(Lsm)] = w_i / Lsm
    gLf += w / Lsm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lsm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_softmax(h0, beta, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.arange(h.size)
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_softmax(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
