    cur = best.copy()
    curR = bestR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Annealing schedule: start low beta (very smooth), raise it.
    # beta scales with 1/typical knot magnitude. Use relative-to-max scaling.
    Lf = _knots(cur)
    Lm = Lf.max()
    if Lm <= 0:
        return {"best": best}

    # beta values: fraction of 1/Lm upward
    betas = []
    b = 2.0 / Lm
    while b * Lm < 4000 and len(betas) < 60:
        betas.append(b)
        b *= 1.6
    print("schedule: %d betas from %.3g to %.3g (1/Lm=%.3g)"
          % (len(betas), betas[0], betas[-1], 1.0/Lm))

    rng = np.random.RandomState(12345)

    for bi, beta in enumerate(betas):
        if time.process_time() > deadline - 1.0:
            break
        cand = _lbfgs_softmax(cur, beta, deadline - 0.5, maxiter=200)
        r = R_of(cand)
        if r > curR + 1e-15:
            cur, curR = cand.copy(), r
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r
            print("beta=%.4g R=%.12f *" % (beta, r))
        else:
            print("beta=%.4g R=%.12f" % (beta, r))

    # Optional: local re-tiling perturbation of the tooth structure to escape
    # any remaining flat region, using softmax on a window.
    if time.process_time() < deadline - 2.0:
        # small random perturbation + polish
        for trial in range(6):
            if time.process_time() > deadline - 1.5:
                break
            hh = cur * (1.0 + 0.003 * rng.randn(cur.size))
            hh = _rescale(np.clip(hh, 0, None))
            # high beta polish
            bhi = betas[-1]
            cand = _lbfgs_softmax(hh, bhi, deadline - 0.5, maxiter=120)
            r = R_of(cand)
            if r > curR + 1e-15:
                cur, curR = cand.copy(), r
                if r > bestR + 1e-15:
                    best, bestR = cand.copy(), r
                print("pert trial %d R=%.12f *" % (trial, r))

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d)"
          % (bestR, startR, best.size))

    result = {"best": best}
    if curR > startR + 1e-14 and curR < bestR - 1e-14:
        result["alternative"] = cur
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _perturb(base, rng):
    h = base.copy()
    n = h.size
    wlen = int(n * rng.uniform(0.02, 0.10))
    wlen = max(1, min(n, wlen))
    start_i = rng.integers(0, max(1, n - wlen + 1))
    factor = rng.choice([0.0, 0.5, 1.5])
    h[start_i:start_i + wlen] *= factor
    return _rescale(h)


def _perturb_multi(base, rng):
    """Multiple disjoint perturbations to escape stronger local minima."""
    h = base.copy()
    n = h.size
    nb = int(rng.integers(2, 6))
    for _ in range(nb):
        wlen = max(1, int(n * rng.uniform(0.01, 0.06)))
        s = rng.integers(0, max(1, n - wlen + 1))
        f = rng.choice([0.0, 0.3, 0.6, 1.4, 2.0])
        h[s:s + wlen] *= f
    return _rescale(h)


def _detect_period(h):
    n = h.size
    mx = h.max() if h.size else 0.0
    if mx <= 0:
        return 1
    tol = 1e-12 * mx
    for p in range(2, 65):
        if n % p != 0:
            continue
        m = n // p
        blocks = h.reshape(p, m)
        if np.max(np.abs(blocks - blocks[0])) < tol:
            return p
    return 1


def _resample(base, newN):
    n = base.size
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    return _rescale(np.interp(x_new, x_old, base))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, N, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    rng = np.random.default_rng(1234567)
    alternative = None
    altR = 0.0

    # ---- Phase 1: full-N annealed softmax polish from start ----
    # This is the primary improvement: work directly at full resolution
    # with a smooth softmax surrogate, annealing beta up.
    phase1_end = t0 + budget_seconds * 0.35
    h = best.copy()
    for beta in (1e3, 1e4, 1e5, 1e6, 1e7, 1e8):
        if time.process_time() >= phase1_end - 1.0:
            break
        slice_end = min(phase1_end, time.process_time() + 2.5)
        ht = _lbfgs_all_pos(h, 300, slice_end - 0.3, beta=beta)
        if R_of(ht) >= R_of(h) - 1e-12:
            h = ht
    ht = _lbfgs_all_pos(h, 400, phase1_end - 0.3, tie=True)
    if R_of(ht) > R_of(h):
        h = ht
    r1 = R_of(h)
    if r1 > bestR + 1e-15:
        best, bestR = h.copy(), r1
        print("Phase1 anneal ACCEPT R=%.9f (+%.2e)" % (bestR, bestR - startR))
    else:
        print("Phase1 no gain R=%.9f (start %.9f)" % (r1, startR))

    # ---- Phase 2: multi-perturbation restarts at full N ----
    phase2_end = t0 + budget_seconds * 0.68
    tries = 0
    accepted = 0
    while time.process_time() < phase2_end - 2.0:
        tries += 1
        if tries % 2 == 0:
            cand = _perturb_multi(best, rng)
        else:
            cand = _perturb(best, rng)
        slice_end = min(phase2_end, time.process_time() + 4.0)
        hh = _lbfgs_all_pos(cand, 300, slice_end - 0.5, beta=1e7)
        if time.process_time() < slice_end - 0.4:
            hh = _lbfgs_all_pos(hh, 300, slice_end - 0.3, tie=True)
        if time.process_time() < slice_end - 0.3:
            hh = _peak_ladder(hh, slice_end - 0.05,
                              pads=(0.08, 0.05, 0.03), iters=150, tie=True)
        r = R_of(hh)
        if r > bestR + 1e-15:
            best, bestR = hh.copy(), r
            accepted += 1
            print("P2 try %d ACCEPT R=%.9f (+%.2e)" % (tries, r, r - startR))
    print("Phase2: tries=%d accepted=%d best R=%.9f" % (tries, accepted, bestR))

    # ---- Phase 3: resample to nearby N to break grid-local structure ----
    # The objective depends on N; small changes in N can unlock gains.
    phase3_end = t0 + budget_seconds * 0.84
    for dN in (0, -1, 1, -2, 2, -3, 3, -5, 5):
        if time.process_time() >= phase3_end - 3.0:
            break
        newN = best.size + dN
        if newN < 64 or newN > 1000000:
            continue
        hs = _resample(best, newN) if dN != 0 else best.copy()
        slice_end = min(phase3_end, time.process_time() + 3.0)
        hs = _lbfgs_all_pos(hs, 300, slice_end - 0.5, beta=1e7)
        if time.process_time() < slice_end - 0.4:
            hs = _lbfgs_all_pos(hs, 300, slice_end - 0.2, tie=True)
        r = R_of(hs)
        if r > bestR + 1e-15:
            best, bestR = hs.copy(), r
            print("P3 dN=%+d ACCEPT R=%.9f (+%.2e) N=%d"
                  % (dN, r, r - startR, best.size))

    # ---- Phase 4: final full-N polish ----
    phase4_end = t0 + budget_seconds * 0.92
    it = 0
    while time.process_time() < phase4_end - 3.0:
        it += 1
        slice_end = min(phase4_end, time.process_time() + 6.0)
        ht = _lbfgs_all_pos(best, 500, slice_end - 3.0, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("P4 tie %d ACCEPT R=%.9f" % (it, bestR))
        if time.process_time() < slice_end - 2.0:
            ht = _peak_ladder(best, slice_end - 0.5,
                              pads=(0.08, 0.05, 0.03), iters=250, tie=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                print("P4 peak %d ACCEPT R=%.9f" % (it, bestR))

    fd = t0 + budget_seconds * 0.94
    if time.process_time() < fd - 3.0:
        ht = _lbfgs_all_pos(best, 500, fd - 2.0, tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, "
          "ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    m = max(8, int(np.ceil((1.0 - q) * n)))
    if m >= n:
        m = n - 1
    order = np.argsort(Lf)
    idx = order[-m:]
    M = Lf[idx].mean()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += 1.0 / (m * M)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    return val, grad


def _fun_grad_softmax(h, tau):
    """Smooth max via log-sum-exp; tau small -> close to true max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    z = (Lf - mx) / tau
    e = np.exp(z)
    Z = e.sum()
    soft = mx + tau * np.log(Z)
    gLf = -dq / num
    gLf += e / Z
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(soft)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cvar_lbfgs(h0, q, deadline, maxiter=150):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_cvar(hh, q), deadline, maxiter)


def _softmax_lbfgs(h0, tau, deadline, maxiter=150):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_softmax(hh, tau), deadline, maxiter)


def _lift_mass_preserving(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    C = np.concatenate(([0.0], np.cumsum(h)))
    x = np.arange(N2 + 1, dtype=float) * (N / N2)
    C2 = np.interp(x, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2)
    return np.clip(h2, 0, None)


def _fold_back(h2, N):
    N2 = h2.size
    if N2 == N:
        return h2.copy()
    b = np.arange(N + 1, dtype=float) * (N2 / N)
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    C = np.interp(b, np.arange(N2 + 1, dtype=float), C2)
    h = np.diff(C)
    return np.clip(h, 0, None)


def _near_max_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(Lf >= mx * 0.999),
            np.mean(Lf >= mx * 0.99),
            np.mean(Lf >= mx * 0.95))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase A: soft-max ladder at a few temperatures, then exact tie polish.
    # The soft-max is a smooth surrogate for ||f*f||_inf; annealing tau
    # moves mass away from the peak plateau and reshapes the profile,
    # which the plain tie-averaged gradient tends to leave stuck.
    for tau in [1e-2, 3e-3, 1e-3, 3e-4]:
        if time.process_time() >= deadline - 4.0:
            break
        tlim = min(deadline - 3.0, time.process_time() + 2.5)
        h_s = _softmax_lbfgs(best, tau, tlim, maxiter=120)
        r_s = R_of(h_s)
        if r_s > bestR + 1e-12:
            best, bestR = h_s, r_s
        if time.process_time() < deadline - 2.5:
            tlim = min(deadline - 2.0, time.process_time() + 1.5)
            h_f = _full_lbfgs(best, tlim, maxiter=120)
            rf = R_of(h_f)
            if rf > bestR + 1e-12:
                best, bestR = h_f, rf
        f1, f5, f25 = _near_max_fracs(best)
        print("tau=%.1e R=%.9f fracs %.3f/%.3f/%.3f" % (tau, bestR, f1, f5, f25))

    # Phase B: CVaR ladder to broaden the near-max plateau slightly.
    for q in [0.90, 0.95, 0.98, 0.99]:
        if time.process_time() >= deadline - 4.0:
            break
        tlim = min(deadline - 3.0, time.process_time() + 2.0)
        h_c = _cvar_lbfgs(best, q, tlim, maxiter=120)
        r_c = R_of(h_c)
        if time.process_time() < deadline - 2.0:
            tlim = min(deadline - 1.5, time.process_time() + 1.5)
            h_f = _full_lbfgs(h_c, tlim, maxiter=120)
            rf = R_of(h_f)
            if rf > r_c:
                h_c, r_c = h_f, rf
        if r_c > bestR + 1e-12:
            best, bestR = h_c, r_c
        f1, f5, f25 = _near_max_fracs(best)
        print("q=%.3f R=%.9f fracs %.3f/%.3f/%.3f" % (q, bestR, f1, f5, f25))

    # Phase C: lift to 2x resolution, polish, fold back.
    N = best.size
    if time.process_time() < deadline - 10.0:
        N2 = int(round(N * 2))
        if 16 <= N2 <= 1000000:
            h_lift = _lift_mass_preserving(best, N2)
            if h_lift.sum() > 0:
                h_lift = _rescale(h_lift)
                tlim = min(deadline - 6.0, time.process_time() + 4.0)
                h_lift = _full_lbfgs(h_lift, tlim, maxiter=200)
                h_fold = _fold_back(h_lift, N)
                if h_fold.sum() > 0:
                    h_fold = _rescale(h_fold)
                    r_fold = R_of(h_fold)
                    if r_fold > bestR + 1e-12:
                        best, bestR = h_fold, r_fold
                        print("lift 2x accepted R=%.9f" % r_fold)
                    else:
                        print("lift 2x rejected R=%.9f (best %.9f)" % (r_fold, bestR))

    # Phase D: keep hammering exact tie polish until near deadline.
    while time.process_time() < deadline - 1.5:
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        h_f = _full_lbfgs(best, tlim, maxiter=200)
        rf = R_of(h_f)
        if rf > bestR + 1e-15:
            best, bestR = h_f, rf
        else:
            break

    f1, f5, f25 = _near_max_fracs(best)
    print("final R=%.12f (start %.12f, N=%d) fracs %.3f/%.3f/%.3f"
          % (bestR, startR, best.size, f1, f5, f25))

    if bestR < startR:
        best = start_best
        bestR = startR

    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= 0.9995 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample(h, N):
    m = h.size
    if m == N:
        return h.copy()
    x_old = (np.arange(m) + 0.5) / m
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _refine_fixed(h, deadline, rounds=4):
    """Repeated full-pos + peak-window L-BFGS at current resolution."""
    best = h.copy()
    bestR = R_of(best)
    for it in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
        for pad in (0.20, 0.10, 0.05):
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
        if time.process_time() < deadline - 0.8:
            ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=1e7)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase A: refine at current resolution (fast, cheap) ----
    # Use a small time slice for the fixed-resolution polish first.
    phaseA_end = min(deadline - 30.0, t0 + budget_seconds * 0.18)
    if phaseA_end > time.process_time() + 2.0:
        ht, r = _refine_fixed(best, phaseA_end, rounds=3)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'refineA'
            print("refineA R=%.9f" % bestR)

    # ---- Phase B: upsampling ladder.  The key idea: try increasingly
    #      finer resolutions, upsampling + polishing each.  Higher N
    #      lets the optimum concentrate the peak more sharply. ----
    N0 = best.size
    targets = []
    for f in (1.5, 2.0, 3.0, 4.0):
        N = int(round(N0 * f))
        if N <= 1000000:
            targets.append(N)
    # Always try at least a couple of resolutions, even if start is large.
    if not targets:
        targets = [min(1000000, int(N0 * 1.5))]

    alt_best = None
    alt_bestR = -1.0

    # Reserve time proportionally; last target gets the biggest share.
    total_targets = len(targets)
    for ti, N in enumerate(targets):
        if time.process_time() >= deadline - 6.0:
            break
        # time slice for this target
        remaining = deadline - time.process_time()
        targets_left = total_targets - ti
        slice_len = remaining * (1.0 / targets_left) * 0.9
        this_end = time.process_time() + slice_len
        if this_end > deadline - 2.0:
            this_end = deadline - 2.0
        if this_end <= time.process_time() + 1.0:
            break

        h_up = _upsample(best, N)
        h_up = _rescale(h_up)
        r_up = R_of(h_up)
        print("upsample N=%d R=%.9f (from %.9f)" % (N, r_up, bestR))

        # Warm up with all-pos and peak-window
        ht, r = _refine_fixed(h_up, this_end, rounds=2)
        print("  refined N=%d R=%.9f" % (N, r))
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'up%d' % N
            print("  NEW BEST R=%.9f at N=%d" % (bestR, N))
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase C: final push at best resolution ----
    if time.process_time() < deadline - 2.0:
        ht, r = _refine_fixed(best, deadline - 0.5, rounds=6)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'final'
            print("final refine R=%.9f" % bestR)

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fg, active, tlim, maxiter=120):
    if time.process_time() >= tlim - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(tlim - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_window_polish(h, tlim):
    win = _peak_window(h, tol=0.95, pad_frac=0.5, extra=64)
    return _lbfgs_custom(h, _fun_grad_tie, win, tlim, maxiter=80)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max_abs(h, frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _zero_frac(h):
    return float(np.mean(h <= 1e-12))


def _max_over_mean(h):
    m = h.mean()
    if m <= 0:
        return 0.0
    return float(h.max() / m)


def _sparsify(h, frac):
    n = h.size
    k = int(round(frac * n))
    if k <= 0:
        return h.copy()
    if k >= n:
        k = n - 1
    order = np.argsort(h)
    hh = h.copy()
    hh[order[:k]] = 0.0
    return _rescale(hh)


def _report(tag, h):
    print("%s: R=%.9f zero=%.3f max/mean=%.2f near 0.1/1/5%%: %.4f/%.4f/%.4f"
          % (tag, R_of(h), _zero_frac(h), _max_over_mean(h),
             _frac_near_max_abs(h, 1e-3), _frac_near_max_abs(h, 1e-2),
             _frac_near_max_abs(h, 5e-2)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    _report("base", best)

    alt_best = None
    altR = -1.0

    cur = best.copy()
    curR = bestR

    def consider(h_new, tag):
        nonlocal best, bestR, alt_best, altR, cur, curR
        r = R_of(h_new)
        _report(tag, h_new)
        if r > altR:
            altR = r; alt_best = h_new.copy()
        if r > bestR + 1e-15:
            best, bestR = h_new.copy(), r
        if r > curR + 1e-15:
            cur, curR = h_new.copy(), r
        return r

    fracs = [0.10, 0.20, 0.30, 0.40]
    N_full = cur.size

    # First pass over fracs
    for frac in fracs:
        if time.process_time() >= deadline - 3.0:
            break
        hs = _sparsify(cur, frac)
        _report("sparsify frac=%.2f (pre)" % frac, hs)
        active = np.flatnonzero(hs > 0)
        tlim = min(deadline - 2.5, time.process_time() + 3.0)
        ht = _lbfgs_custom(hs, _fun_grad_tie, active, tlim, maxiter=120)
        consider(ht, "sparsify frac=%.2f tie" % frac)
        if time.process_time() < deadline - 2.5:
            tlim = min(deadline - 2.0, time.process_time() + 1.0)
            hp = _peak_window_polish(ht, tlim)
            consider(hp, "sparsify frac=%.2f peak" % frac)

    print("after first sparsify pass: bestR=%.9f" % bestR)

    # Cycle fracs re-polishing current best until near deadline
    it = 0
    while time.process_time() < deadline - 2.0:
        frac = fracs[it % len(fracs)]
        it += 1
        if time.process_time() >= deadline - 2.5:
            break
        hs = _sparsify(cur, frac)
        active = np.flatnonzero(hs > 0)
        tlim = min(deadline - 1.5, time.process_time() + 2.5)
        ht = _lbfgs_custom(hs, _fun_grad_tie, active, tlim, maxiter=100)
        consider(ht, "cycle frac=%.2f tie" % frac)
        if time.process_time() < deadline - 1.5:
            tlim = min(deadline - 1.0, time.process_time() + 1.0)
            hp = _peak_window_polish(ht, tlim)
            consider(hp, "cycle frac=%.2f peak" % frac)

    # Final exact tie polish on full support
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.3, time.process_time() + 2.0)
        full = np.arange(cur.size)
        ht = _lbfgs_custom(cur, _fun_grad_tie, full, tlim, maxiter=120)
        r = R_of(ht)
        _report("final tie", ht)
        if r > altR:
            altR = r; alt_best = ht.copy()
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            break

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d, zeros=%.3f, max/mean=%.2f)"
          % (bestR, startR, best.size, _tie_count(best), _zero_frac(best),
             _max_over_mean(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline, beta=beta)


def _peak_region(h, tol=0.9995):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _refine(h, deadline, rounds=1):
    """A quick polish: full lbfgs then peak window."""
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        h = _lbfgs_all(h, 400, deadline)
        h = _window_polish_peak(h, deadline, 0.5, 128, maxiter=300)
    return h


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _compress(h, N_small):
    return _prolongate(h, N_small)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    N = best.size
    alt, altR = None, 0.0

    def try_candidate(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        print("%s R=%.7f" % (tag, r))
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("  -> new best %.7f" % bestR)

    # Pass 1: sharpen current best with tie-averaged polish
    h = _refine(best, deadline - 0.5, rounds=2)
    try_candidate(h, "refine")

    # Pass 2: multi-scale re-resolution cycle (compress -> optimize -> prolongate)
    # Idea: the optimum has a sharp peak; coarse optimizations escape local
    # minima; going back up re-introduces fine structure near the peak.
    scales = [max(512, N // 16), max(1024, N // 8), max(2048, N // 4), N // 2]
    scales = [s for s in scales if 256 <= s < N]
    rng = np.random.RandomState(12345)
    trial = 0
    while time.process_time() < deadline - 2.0 and trial < 12:
        s = scales[trial % len(scales)]
        h = _compress(best, s)
        # a small perturbation to escape local minima at coarse scale
        if trial >= len(scales):
            m = max(8, s // 128)
            noise = rng.randn(m)
            p = np.interp(np.linspace(0, 1, s), np.linspace(0, 1, m), noise)
            h = _rescale(np.clip(h * np.exp(0.05 * p), 0, None))
        h = _refine(h, min(deadline - 1.0, time.process_time() + (deadline - time.process_time()) * 0.4), rounds=2)
        h = _prolongate(h, N)
        h = _refine(h, deadline - 0.5, rounds=1)
        try_candidate(h, "multiscale%d" % trial)
        trial += 1

    # Pass 3: high-beta anneal to sharpen peak then tie
    betas = [64.0, 512.0, 4096.0, 32768.0]
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        h = _lbfgs_all(best, 400, deadline - 0.5, beta=beta)
        h = _window_polish_peak(h, deadline - 0.5, 0.55, 128, maxiter=300)
        h = _lbfgs_all(h, 400, deadline - 0.5)
        try_candidate(h, "anneal%.0f" % beta)

    # Final: alternating polish until time
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_all(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, 0.55, 128)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

