    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, beta=0.0, free=None, tie=False, logparam=False):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    if free is None:
        active = np.arange(h.size)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0

    if logparam:
        hmax = h.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        u0 = np.log(np.clip(h[active], floor, None))

        def f(u):
            hh = h.copy()
            hh[active] = np.exp(np.clip(u, -40.0, 40.0))
            val, g = fg(hh)
            return val, g[active] * hh[active]

        x0 = u0
        bounds = [(-40.0, 40.0)] * active.size
        cb = _make_cb(deadline - 0.15)
        opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
                'ftol': 1e-20, 'gtol': 1e-16}
        try:
            res = minimize(f, x0, jac=True, method='L-BFGS-B',
                           bounds=bounds, callback=cb, options=opts)
        except (TimeoutError, Exception):
            return h0
        if res is None:
            return h0
        hh = h.copy()
        hh[active] = np.exp(np.clip(res.x, -40.0, 40.0))
        return _rescale(hh)

    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * x0.size,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    hh = h.copy()
    hh[active] = np.clip(res.x, 0.0, None)
    return _rescale(hh)


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _compact_support(h):
    nz = np.flatnonzero(h > 1e-14 * h.max())
    if nz.size == 0:
        return h
    return h[nz[0]:nz[-1] + 1]


def _peak_window(h, tol=0.999, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    pad = max(extra, int((hi - lo) * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    best = None
    bestR = -1.0
    if start is not None:
        s = _rescale(np.asarray(start, dtype=float))
        if s.sum() > 0:
            best = _compact_support(s)
            bestR = R_of(best)
            print("start R=%.6f N=%d" % (bestR, len(best)))

    if best is None:
        N0 = 2000
        h = np.zeros(N0)
        h[N0 // 4: N0 // 4 + 50] = 1.0
        best = _rescale(h)
        bestR = R_of(best)

    # Alternative construction from a coarse trapezoid-ish start, independent of `start`.
    alt = None
    altR = -1.0

    def _push(cand):
        nonlocal best, bestR, alt, altR
        cand = _compact_support(_rescale(cand))
        rc = R_of(cand)
        if rc > bestR:
            best = cand; bestR = rc
        if rc > altR:
            alt = cand; altR = rc

    # ---- Main multi-resolution refinement from `start` ----
    cur = best.copy()
    if len(cur) < 512:
        cur = _prolongate(cur, 512)

    levels = []
    n = len(cur)
    while n < 300000:
        levels.append(n)
        n = int(n * 1.45) + 1
    levels.append(min(400000, max(n, len(cur))))

    for N in levels:
        if time.process_time() > deadline - 1.0:
            break
        cur = _rescale(_prolongate(cur, N))
        for beta in (6.0, 15.0, 0.0):
            if time.process_time() > deadline - 1.0:
                break
            cur = _lbfgs(cur, 400, deadline, beta=beta)
            _push(cur)
        print("level N=%d R=%.6f best=%.6f" % (N, R_of(cur), bestR))

    # ---- Log-parameter polish to escape boundary-flat regions ----
    while time.process_time() < deadline - 2.0:
        cur = best.copy()
        N = len(cur)
        if N > 60000:
            break
        cur = _lbfgs(cur, 300, deadline, tie=True, logparam=True)
        _push(cur)
        if R_of(cur) <= bestR + 1e-9:
            break
        print("log-polish R=%.6f" % bestR)

    # ---- Peak-localized polish with shrinking windows ----
    while time.process_time() < deadline - 1.0:
        cur = best.copy()
        win = _peak_window(cur, tol=0.999, pad_frac=0.6, extra=128)
        for beta in (0.0, 8.0, 0.0):
            if time.process_time() > deadline - 1.0:
                break
            cur = _lbfgs(cur, 500, deadline, beta=beta, free=win)
            _push(cur)
        if time.process_time() < deadline - 1.0:
            cur = _lbfgs(cur, 300, deadline, tie=True)
            _push(cur)
        print("polish R=%.6f best=%.6f N=%d" % (R_of(cur), bestR, len(best)))
        if R_of(cur) <= bestR + 1e-9:
            break

    print("final R=%.6f N=%d altR=%.6f" % (bestR, len(best) if best is not None else 0, altR))

    if best is None:
        return np.ones(50)
    if alt is not None and altR < bestR:
        # alt is genuinely different (from a fresh line we attempted); report it
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_flat(h):
    """Objective: -log(||L||^2) + 2 log(sum h).  Used to build a broad plateau
    of high knots (the true optimum appears to want many near-max knots)."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun_grad, deadline, maxiter=200, logparam=True):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 1e-300)
    if pos.size == 0:
        pos = np.arange(h.size)
    if logparam:
        hmax = h.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        x0 = np.log(np.clip(h[pos], floor, None))
        bounds = [(-40.0, 40.0)] * pos.size
        def f(x):
            hh = h.copy()
            hh[pos] = np.exp(x)
            val, g = fun_grad(hh)
            return val, g[pos] * hh[pos]
    else:
        x0 = h[pos].copy()
        bounds = [(0.0, None)] * pos.size
        def f(x):
            hh = h.copy()
            hh[pos] = np.clip(x, 0, None)
            val, g = fun_grad(hh)
            return val, g[pos]
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', bounds=bounds,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    if logparam:
        h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    else:
        h2[pos] = np.clip(res.x, 0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _upsample_to(h, N):
    n = h.size
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d, ties=%d)" % (bestR, best.size, _tie_count(best)))

    # ---- 1) Broad-plateau push: flat objective to spread knot energy. ----
    # The optimum has many knots near the max; a flat ||L||^2 objective
    # naturally widens the plateau, then tie-polish sharpens it.
    cur = best.copy()
    curR = bestR
    flat_end = t0 + (deadline - t0) * 0.35
    while time.process_time() < flat_end - 1.5:
        hl = _lbfgs(cur, _fun_grad_flat, min(flat_end - 0.5, time.process_time() + 3.0),
                    maxiter=120)
        r = R_of(hl)
        cur = hl
        # then tie-polish
        ht = _lbfgs(hl, _fun_grad_tie, min(flat_end - 0.5, time.process_time() + 3.0),
                    maxiter=150)
        rt = R_of(ht)
        if rt > curR + 1e-15:
            cur, curR = ht, rt
        if curR > bestR + 1e-15:
            best, bestR = cur.copy(), curR
        print("flat-iter R=%.12f best=%.12f ties=%d" % (curR, bestR, _tie_count(best)))
        if time.process_time() > flat_end - 1.5:
            break

    # ---- 2) CVaR ladder on near-max knots (helps push ties up). ----
    cvar_end = t0 + (deadline - t0) * 0.60
    for alpha in (0.02, 0.05, 0.10, 0.20):
        if time.process_time() >= cvar_end - 1.0:
            break
        fg = (lambda hh, a=alpha: _fun_grad_cvar(hh, a))
        hc = _lbfgs(best, fg, min(cvar_end - 0.5, time.process_time() + 3.0), maxiter=120)
        ht = _lbfgs(hc, _fun_grad_tie, min(cvar_end - 0.5, time.process_time() + 3.0),
                    maxiter=150)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("cvar a=%.2f R=%.12f best=%.12f" % (alpha, r, bestR))

    # ---- 3) Upsample + refine: try doubling resolution to find more room. ----
    if time.process_time() < deadline - 4.0 and best.size * 2 <= 1000000:
        N2 = best.size * 2
        h2 = _upsample_to(best, N2)
        r2 = R_of(h2)
        if r2 >= bestR - 0.002:  # upsampling shouldn't lose much
            ht = _lbfgs(h2, _fun_grad_tie,
                        min(deadline - 1.5, time.process_time() + 5.0), maxiter=150)
            rt = R_of(ht)
            print("upsample N=%d R=%.12f" % (N2, rt))
            if rt > bestR + 1e-15:
                best, bestR = ht.copy(), rt

    # ---- 4) Final exact tie polish to convergence. ----
    while time.process_time() < deadline - 0.5:
        ht = _lbfgs(best, _fun_grad_tie,
                    min(deadline - 0.3, time.process_time() + 4.0), maxiter=250)
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

