def _peak_window_polish(h, tlim):
    win = _peak_window(h, tol=0.95, pad_frac=0.5, extra=64)
    return _lbfgs_custom(h, _fun_grad_tie, win, tlim, maxiter=80)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max_abs(h, frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _zero_frac(h):
    return float(np.mean(h <= 1e-12))


def _max_over_mean(h):
    m = h.mean()
    if m <= 0:
        return 0.0
    return float(h.max() / m)


def _sparsify(h, frac):
    n = h.size
    k = int(round(frac * n))
    if k <= 0:
        return h.copy()
    if k >= n:
        k = n - 1
    order = np.argsort(h)
    hh = h.copy()
    hh[order[:k]] = 0.0
    return _rescale(hh)


def _report(tag, h):
    print("%s: R=%.9f zero=%.3f max/mean=%.2f near 0.1/1/5%%: %.4f/%.4f/%.4f"
          % (tag, R_of(h), _zero_frac(h), _max_over_mean(h),
             _frac_near_max_abs(h, 1e-3), _frac_near_max_abs(h, 1e-2),
             _frac_near_max_abs(h, 5e-2)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    _report("base", best)

    alt_best = None
    altR = -1.0

    cur = best.copy()
    curR = bestR

    def consider(h_new, tag):
        nonlocal best, bestR, alt_best, altR, cur, curR
        r = R_of(h_new)
        _report(tag, h_new)
        if r > altR:
            altR = r; alt_best = h_new.copy()
        if r > bestR + 1e-15:
            best, bestR = h_new.copy(), r
        if r > curR + 1e-15:
            cur, curR = h_new.copy(), r
        return r

    N = cur.size

    # (a) annealed sparsification in 2% steps
    def anneal(cur_h, cur_r):
        h = cur_h.copy()
        r = cur_r
        for frac in np.arange(0.12, 0.401, 0.02):
            if time.process_time() >= deadline - 2.5:
                break
            hs = _sparsify(h, frac)
            active = np.flatnonzero(hs > 0)
            tlim = min(deadline - 2.0, time.process_time() + 2.0)
            ht = _lbfgs_custom(hs, _fun_grad_tie, active, tlim, maxiter=150)
            if time.process_time() < deadline - 1.5:
                tlim = min(deadline - 1.0, time.process_time() + 1.0)
                hp = _peak_window_polish(ht, tlim)
            else:
                hp = ht
            rt = R_of(hp)
            _report("frac=%.2f" % frac, hp)
            if rt > r + 1e-15:
                h, r = hp, rt
                consider(hp, "accept frac=%.2f" % frac)
            else:
                # keep going from the annealed candidate even if not accepted,
                # so the shape can follow the shrinking support
                h = hp
        return h, r

    # (b) revival: bring back most-negative-gradient zero cells
    def revive(cur_h, cur_r):
        h = cur_h.copy()
        val, g = _fun_grad_tie(h)
        zero_idx = np.flatnonzero(h <= 1e-12)
        if zero_idx.size == 0:
            return h, cur_r
        k = min(200, zero_idx.size)
        # most negative gradient among zeros -> largest descent
        order = np.argsort(g[zero_idx])[:k]
        pick = zero_idx[order]
        m = h.mean()
        if m <= 0:
            return h, cur_r
        h2 = h.copy()
        h2[pick] = 1e-3 * m
        h2 = _rescale(h2)
        active = np.flatnonzero(h2 > 0)
        tlim = min(deadline - 1.5, time.process_time() + 2.0)
        ht = _lbfgs_custom(h2, _fun_grad_tie, active, tlim, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim = min(deadline - 0.5, time.process_time() + 1.0)
            hp = _peak_window_polish(ht, tlim)
        else:
            hp = ht
        rt = R_of(hp)
        _report("revive", hp)
        if rt > cur_r + 1e-15:
            consider(hp, "accept revive")
            return hp, rt
        return h, cur_r

    # (c) beta-sharpening rung + exact tie polish
    def beta_sharpen(cur_h, cur_r):
        h = cur_h.copy()
        r = cur_r
        for beta in (1e4, 1e5):
            if time.process_time() >= deadline - 2.5:
                break

            def fg_beta(hh, beta=beta):
                s = hh.sum()
                if s <= 0:
                    return 1e18, np.zeros(hh.size)
                num, dq, Lf = _num_and_dq(hh)
                mx = Lf.max()
                # soft-max via logsumexp with temperature 1/beta
                z = beta * (Lf - mx)
                e = np.exp(z)
                Z = e.sum()
                gLf = -dq / num
                # d/dh of log(softmax) = (1/Z) * sum_j e_j * beta * dLf_j
                # but we want gradient of log(softmax); chain through backprop
                # approximate: use softmax weights on Lf
                w = e / Z
                gLf = gLf + w / max(mx, 1e-30)
                grad = _backprop(gLf, hh) + 2.0 / s
                val = -np.log(num) + 2.0 * np.log(s) + np.log(max(mx, 1e-30))
                return val, grad

            active = np.flatnonzero(h > 0)
            tlim = min(deadline - 2.0, time.process_time() + 1.5)
            ht = _lbfgs_custom(h, fg_beta, active, tlim, maxiter=100)
            # exact tie polish
            tlim = min(deadline - 1.0, time.process_time() + 1.0)
            full = np.arange(ht.size)
            hp = _lbfgs_custom(ht, _fun_grad_tie, full, tlim, maxiter=100)
            rt = R_of(hp)
            _report("beta=%.0e" % beta, hp)
            if rt > r + 1e-15:
                h, r = hp, rt
                consider(hp, "accept beta=%.0e" % beta)
        return h, r

    # main cycle
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h, r = anneal(cur, curR)
        if time.process_time() >= deadline - 2.0:
            break
        h, r = revive(h, r)
        if time.process_time() >= deadline - 2.0:
            break
        h, r = beta_sharpen(h, r)
        if time.process_time() >= deadline - 2.0:
            break
        if r > curR + 1e-15:
            cur, curR = h, r
        else:
            # no progress in full cycle; try one more anneal from best
            if it > 3:
                break

    # Final exact tie polish on full support
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.3, time.process_time() + 2.0)
        full = np.arange(cur.size)
        ht = _lbfgs_custom(cur, _fun_grad_tie, full, tlim, maxiter=120)
        r = R_of(ht)
        _report("final tie", ht)
        if r > altR:
            altR = r; alt_best = ht.copy()
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            break

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d, zeros=%.3f, max/mean=%.2f)"
          % (bestR, startR, best.size, _tie_count(best), _zero_frac(best),
             _max_over_mean(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h == 0))


def _half_cycle(c, bestR, deadline, tag=""):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    for it, pad in enumerate([0.30, 0.20, 0.15, 0.10, 0.08]):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _full_polish(h, slice_deadline, pads=(0.30, 0.15, 0.08)):
    ht = h
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= slice_deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=beta)
    for pad in pads:
        if time.process_time() >= slice_deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pad, extra=128)
        ht = _lbfgs_block(ht, win, 400, slice_deadline - 0.3, beta=1e7)
    if time.process_time() < slice_deadline - 0.5:
        ht = _lbfgs_all_pos(ht, 300, slice_deadline - 0.3, beta=0.0)
    return ht


def _local_resample(h, factor, deadline):
    """Resample h to a finer/coarser grid by linear interpolation, then rescale."""
    n = h.size
    m = int(round(n * factor))
    if m < 4 or m > 1000000:
        return None
    xs = (np.arange(m) + 0.5) / m * n
    xp = np.arange(n) + 0.5
    hs = np.interp(xs, xp, h)
    return _rescale(hs)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _consider(hc, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(hc)
        if r > bestR + 1e-14:
            best, bestR, origin = hc.copy(), r, tag
            print("%s NEW BEST R=%.9f" % (tag, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = hc.copy(), r
        return r

    # ---- Phase 1: half-resolution quotient polish ----
    N = best.size
    if N % 2 == 0 and N >= 4 and time.process_time() < deadline - 2.0:
        h0 = best.copy()
        c = h0[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.24
        rounds = 0
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
            if time.process_time() >= half_deadline - 1.0:
                break
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        _consider(h_lift, 'lift')
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 400, deadline - 0.5, beta=beta)
        _consider(ht, 'lift+ladder')

    # ---- Phase 2: quotient-extract -> polish -> lift cycles ----
    cycle = 0
    while cycle < 6 and time.process_time() < deadline - 4.0:
        cycle += 1
        c = best[0::2].copy()
        nz = c > 0
        if nz.sum() == 0:
            break
        rng = np.random.default_rng(100 + cycle)
        c[nz] *= np.exp(0.003 * rng.standard_normal(int(nz.sum())))
        c = _rescale(c)
        slice_dl = min(deadline - 3.0, time.process_time() + 6.0)
        cc = _full_polish(c, slice_dl, pads=(0.20, 0.10))
        h_lift = _rescale(np.repeat(cc, 2))
        hl = h_lift
        if time.process_time() < deadline - 1.5:
            hl = _lbfgs_all_pos(hl, 400, deadline - 1.5, beta=1e6)
        if time.process_time() < deadline - 1.5:
            hl = _lbfgs_all_pos(hl, 400, deadline - 1.5, beta=1e7)
        _consider(hl, 'cycle%d' % cycle)

    # ---- Phase 3: resample refinement (the new idea) ----
    # Try lifting the current best onto a finer grid, then polishing.
    for factor in (2.0, 1.5):
        if time.process_time() >= deadline - 5.0:
            break
        if best.size * factor > 900000:
            continue
        hr = _local_resample(best, factor, deadline)
        if hr is None:
            continue
        slice_dl = min(deadline - 2.0, time.process_time() + 8.0)
        hp = _full_polish(hr, slice_dl, pads=(0.20, 0.10))
        _consider(hp, 'resample%.1f' % factor)

    # ---- Phase 4: peak polish + trailing beta=0 ----
    if time.process_time() < deadline - 2.0:
        win = _peak_window(best, pad_frac=0.10, extra=128)
        ht = _lbfgs_block(best, win, 400, deadline - 1.0, beta=1e7)
        _consider(ht, origin + '+pk')
        if time.process_time() < deadline - 1.0:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
            _consider(ht2, origin + '+all0')

    print("cycles=%d best_full=%.9f" % (cycle, bestR))
    print("final R=%.9f origin=%s (start %.9f, N=%d, zero_frac=%.3f)" %
          (bestR, origin, start_bestR, best.size, _zero_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

