    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _dip_moves(best, bestR, deadline, stats):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR
    a_ = Lf[:-2]; b_ = Lf[1:-1]; c_ = Lf[2:]
    is_min = (b_ <= a_) & (b_ <= c_)
    idx = np.flatnonzero(is_min) + 1
    if idx.size == 0:
        return best, bestR
    mask = Lf[idx] < 0.998 * M
    idx = idx[mask]
    if idx.size == 0:
        return best, bestR
    order = np.argsort(Lf[idx])
    idx = idx[order][:40]
    stats['dips'] += idx.size

    pos = np.flatnonzero(best > 0)
    if pos.size == 0:
        return best, bestR
    mean_pos = best[pos].mean()
    ts = np.geomspace(0.02 * mean_pos, 3.0 * mean_pos, 40)

    best_h = None
    best_r = bestR
    best_info = None

    for d in idx:
        if time.process_time() >= deadline - 0.5:
            break
        a0 = d // 2
        for a in (a0 - 1, a0, a0 + 1):
            if a < 0 or a >= n:
                continue
            lo = max(0, a - 200)
            hi = min(n - 1, a + 200)
            seg = best[lo:hi + 1]
            if seg.size == 0:
                continue
            b = lo + int(np.argmax(seg))
            if b == a:
                continue
            hb = best[b]
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                if t > hb:
                    continue
                h2 = best.copy()
                h2[b] = hb - t
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'transfer')
            for t in ts:
                if time.process_time() >= deadline - 0.5:
                    break
                h2 = best.copy()
                h2[a] = h2[a] + t
                r = R_of(h2)
                if r > best_r + 1e-13:
                    best_r = r
                    best_h = h2
                    best_info = (a, b, t, 'birth')

    stats['best_raw'] = max(stats['best_raw'], best_r - bestR)
    if best_h is None:
        return best, bestR

    a, b, t, kind = best_info
    lo = max(0, a - 64)
    hi = min(n - 1, a + 64)
    free = np.arange(lo, hi + 1)
    hp = _lbfgs_block(best_h, free, 40, deadline, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-12:
        stats['accepted'] += 1
        return hp, rp
    if best_r > bestR + 1e-12:
        stats['accepted'] += 1
        return best_h, best_r
    return best, bestR


def _block_cd(h, bestR, deadline, passes=4):
    n = h.size
    if n < 64:
        return h, bestR
    nb = 16
    edges = np.linspace(0, n, nb + 1).astype(int)
    for it in range(passes):
        if time.process_time() >= deadline - 0.5:
            break
        rng = range(nb) if (it % 2 == 0) else range(nb - 1, -1, -1)
        improved = False
        for bi in rng:
            if time.process_time() >= deadline - 0.5:
                break
            lo = max(0, edges[bi] - 4)
            hi = min(n - 1, edges[bi + 1] + 4)
            free = np.arange(lo, hi + 1)
            ht = _lbfgs_block(h, free, 60, deadline, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                h, bestR = ht, r
                improved = True
        if not improved:
            break
    return h, bestR


def _random_perturb(best, bestR, deadline, rng):
    n = best.size
    if n < 128:
        return best, bestR
    while time.process_time() < deadline - 0.5:
        w = int(rng.integers(32, max(64, n // 4)))
        w = min(w, n)
        c = int(rng.integers(0, n))
        lo = max(0, c - w // 2)
        hi = min(n, lo + w)
        if hi - lo < 8:
            break
        h2 = best.copy()
        amp = 0.05 + 0.25 * rng.random()
        noise = 1.0 + amp * rng.standard_normal(hi - lo)
        h2[lo:hi] = np.clip(h2[lo:hi] * noise, 0.0, None)
        free = np.arange(lo, hi)
        h2 = _lbfgs_block(h2, free, 80, deadline, beta=0.0)
        r2 = R_of(h2)
        if r2 > bestR + 1e-13:
            lo2 = max(0, lo - 48)
            hi2 = min(n - 1, hi + 48)
            free2 = np.arange(lo2, hi2 + 1)
            h3 = _lbfgs_block(h2, free2, 60, deadline, beta=0.0)
            r3 = R_of(h3)
            if r3 > bestR + 1e-13:
                best, bestR = h3, r3
                continue
            best, bestR = h2, r2
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _fun_grad_cvar(h, alpha):
    """Smooth-max surrogate: average of top-alpha fraction of knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _lbfgs_fg(h0, fg, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _smoothmax_polish(best, bestR, deadline):
    """Optimise a smooth-max surrogate (top-fraction mean) to flatten the
    plateau, then polish with the true max. Helps escape the R upper bound
    imposed by a tall isolated peak."""
    while time.process_time() < deadline - 0.6:
        improved = False
        for alpha in (0.30, 0.20, 0.12, 0.07, 0.04):
            if time.process_time() >= deadline - 0.6:
                break
            fg = (lambda hh, a=alpha: _fun_grad_cvar(hh, a))
            ht = _lbfgs_fg(best, fg, 200, deadline - 0.6)
            # polish with true max
            ht = _lbfgs_all_pos(ht, 150, deadline - 0.6, beta=0.0)
            r = R_of(ht)
            if r > bestR + 1e-13:
                best, bestR = ht, r
                improved = True
        if not improved:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: short cycle on the start (cheap polish).
    if time.process_time() < deadline - 0.7:
        best, bestR = run_cycle(best, bestR, min(deadline - 0.5,
                                                 t0 + 0.22 * budget_seconds))
        print("phase1 R=%.7f" % bestR)

    # Phase 2 (NEW): smooth-max flattening.
    if time.process_time() < deadline - 0.7:
        best, bestR = _smoothmax_polish(
            best, bestR,
            min(deadline - 0.5, t0 + 0.42 * budget_seconds))
        print("smoothmax R=%.7f" % bestR)

    # Phase 3: block-coordinate descent sweeps.
    if time.process_time() < deadline - 0.7:
        best, bestR = _block_cd(best, bestR,
                                min(deadline - 0.5,
                                    t0 + 0.55 * budget_seconds), passes=6)
        print("block-CD R=%.7f" % bestR)

    # Phase 4: dip moves + mini cycles until ~78% of budget.
    stats = {'dips': 0, 'best_raw': -1e9, 'accepted': 0}
    last_mini = time.process_time()
    phase4_end = t0 + 0.78 * budget_seconds
    while time.process_time() < min(phase4_end, deadline - 0.6):
        best, bestR = _dip_moves(best, bestR,
                                 min(deadline - 0.5, phase4_end), stats)
        now = time.process_time()
        if now - last_mini > 6.0:
            last_mini = now
            if time.process_time() < min(phase4_end, deadline - 0.7):
                st, r = _mini_cycle(best, bestR,
                                    min(deadline - 0.6, phase4_end))
                if r > bestR + 1e-13:
                    best, bestR = st, r
    print("dip phase R=%.7f (dips=%d acc=%d)" %
          (bestR, stats['dips'], stats['accepted']))

    # Phase 5: random perturb-and-reoptimise until ~90% of budget.
    phase5_end = t0 + 0.90 * budget_seconds
    if time.process_time() < phase5_end - 0.6:
        best, bestR = _random_perturb(best, bestR,
                                      min(deadline - 0.5, phase5_end), rng)
        print("perturb R=%.7f" % bestR)

    # Phase 6: final polish cycle.
    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR >= start_bestR - 1e-13:
        return best
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _cvar_weights(Lf, alpha):
    # soft top-alpha: weights over knots above the (1-alpha) quantile, normalized
    n = Lf.size
    k = max(1, int(round(alpha * n)))
    if k >= n:
        w = np.ones(n)
    else:
        thr = np.partition(Lf, n - k)[n - k]
        w = np.where(Lf >= thr, 1.0, 0.0)
        # tie-average: give partial weight to knots exactly at threshold
        cnt = w.sum()
        if cnt > k:
            w = w * (k / cnt)
    Z = w.sum()
    if Z <= 0:
        w = np.ones(n) / n
        return w
    return w / Z


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    w = _cvar_weights(Lf, alpha)
    sm = float(np.dot(w, Lf))
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, alpha=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if alpha > 0:
        fg = (lambda hh: _fun_grad_cvar(hh, alpha))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, alpha=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if alpha > 0:
        fg = (lambda hh: _fun_grad_cvar(hh, alpha))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _downsample(h, k):
    # block-mass downsample: sum of k consecutive bins (mass preserving)
    n = h.size
    m = n // k
    if m < 2:
        return h.copy()
    hh = h[:m * k].reshape(m, k)
    return hh.sum(axis=1)


def _prolongate(c, k, N):
    # mass-preserving prolongation: distribute each coarse bin's mass
    # uniformly across k fine bins, then fit to length N
    m = c.size
    h = np.repeat(c / k, k)
    if h.size < N:
        # pad by repeating last value
        h = np.concatenate((h, np.full(N - h.size, h[-1])))
    return _rescale(h[:N])


def _cvar_ladder(h, deadline, alphas=(0.30, 0.18, 0.10, 0.05), iters=200):
    best = h.copy()
    bestR = R_of(best)
    work = h.copy()
    for a in alphas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, iters, deadline - 0.3, alpha=a)
        # tie-averaged exact-R polish
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_all_pos(ht, iters, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-15:
            work, best, bestR = ht, ht.copy(), r
        else:
            work = ht
    return best, bestR


def _sharpen_ladder(h, deadline, betas=(1e4, 1e5, 1e6, 1e7)):
    best = h.copy()
    bestR = R_of(best)
    work = h.copy()
    for b in betas:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 200, deadline - 0.3, beta=b)
        r = R_of(ht)
        if r > bestR + 1e-15:
            work, best, bestR = ht, ht.copy(), r
        else:
            work = ht
        # peak-window polish after each rung
        if time.process_time() < deadline - 0.5:
            win = _peak_window(work, pad_frac=0.10, extra=128)
            ht2 = _lbfgs_block(work, win, 200, deadline - 0.3, beta=b)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-15:
                work, best, bestR = ht2, ht2.copy(), r2
    return best, bestR


def _resolution_cycle(h, deadline, N):
    # (a) downsample by 2 and 4, (b) CVaR ladder at each level,
    # (c) prolongate back, (d) sharpen ladder, (e) accept gains only
    best = h.copy()
    bestR = R_of(best)
    work = h.copy()
    for k in (2, 4):
        if time.process_time() >= deadline - 1.0:
            break
        c = _downsample(work, k)
        if c.size < 4:
            continue
        cR0 = R_of(c)
        cbest, cR = _cvar_ladder(c, deadline - 0.5)
        if cR < cR0 - 1e-12:
            cbest, cR = c, cR0
        # prolongate back to N
        hp = _prolongate(cbest, k, N)
        # sharpen
        hs, hsR = _sharpen_ladder(hp, deadline)
        if hsR > bestR + 1e-14:
            best, bestR = hs.copy(), hsR
            work = hs.copy()
        else:
            # still continue from the sharpened version for next level
            work = hs.copy()
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    alt_best = None
    alt_bestR = -1.0

    # ---- Main loop: resolution cycling with CVaR + sharpen ladders ----
    cycle = 0
    cycle_end = deadline - 4.0
    while time.process_time() < cycle_end - 1.5:
        cycle += 1
        now = time.process_time()
        slice_dl = min(deadline - 3.0, now + 0.28 * budget_seconds)
        if slice_dl <= now + 1.0:
            break
        hc, hcR = _resolution_cycle(best, slice_dl, N)
        # final full-array exact-R polish of this cycle's candidate
        if time.process_time() < slice_dl - 0.5:
            hc = _lbfgs_all_pos(hc, 200, slice_dl - 0.3, beta=0.0)
            hcR = R_of(hc)
        print("cycle %d R=%.9f (best %.9f)" % (cycle, hcR, bestR))
        if hcR > bestR + 1e-14:
            best, bestR, origin = hc.copy(), hcR, 'cycle%d' % cycle
            print("  cycle NEW BEST R=%.9f" % bestR)
        elif hcR > alt_bestR:
            alt_best, alt_bestR = hc.copy(), hcR

    # ---- Final reserve: full-array exact-R polish + peak windows ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _resample(h, N):
    """Resample length-n array to length-N by linear interpolation on
    cumulative-mass coordinate (mass-preserving)."""
    n = h.size
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    startR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
            startR = R_of(h0)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))
        startR = R_of(h0)

    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase 1: polish the start at its own resolution with exact R.
    if time.process_time() < deadline - 8.0:
        tlim = min(deadline - 6.0, time.process_time() + 8.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        if time.process_time() < deadline - 5.0:
            tlim2 = min(deadline - 4.0, time.process_time() + 3.0)
            hc = _peak_window_polish(hc, tlim2, pad=3)
        rc = R_of(hc)
        print("polish start R=%.12f (was %.12f)" % (rc, bestR))
        if rc > bestR:
            best = hc; bestR = rc

    # Phase 2: multi-resolution upsampling.  The optimum looks smooth on
    # large scales but the peak needs fine resolution; increasing N lets
    # the optimiser find new degrees of freedom near the peak.
    alt_best = None
    alt_bestR = -1.0
    scale = best.copy()
    scaleR = bestR
    Ns = [int(scale.size * f) for f in (1.5, 2.0, 3.0)]
    Ns = [n for n in Ns if n <= 400000]
    for N in Ns:
        if time.process_time() >= deadline - 6.0:
            break
        h_up = _resample(scale, N)
        h_up = _rescale(h_up)
        r_up = R_of(h_up)
        print("upsample N=%d R=%.12f" % (N, r_up))
        tlim = min(deadline - 5.0, time.process_time() + 4.0)
        hc = _full_lbfgs(h_up, tlim, maxiter=150)
        if time.process_time() < deadline - 4.0:
            tlim2 = min(deadline - 3.0, time.process_time() + 2.0)
            hc = _peak_window_polish(hc, tlim2, pad=3)
        rc = R_of(hc)
        print("upsample N=%d polished R=%.12f" % (N, rc))
        if rc > alt_bestR:
            alt_best = hc; alt_bestR = rc
        if rc > scaleR:
            scale = hc; scaleR = rc
        if rc > bestR:
            best = hc; bestR = rc

    # Phase 3: sharpening the peak region on the best resolution.
    if time.process_time() < deadline - 3.0:
        tlim = min(deadline - 2.0, time.process_time() + 2.5)
        hc = _peak_window_polish(best, tlim, pad=5, frac=6)
        rc = R_of(hc)
        print("peak polish R=%.12f" % rc)
        if rc > bestR:
            best = hc; bestR = rc
        if rc > alt_bestR:
            alt_best = hc; alt_bestR = rc

    # Phase 4: refine on a slightly finer grid once more if time permits.
    if time.process_time() < deadline - 2.0:
        N2 = min(500000, int(best.size * 1.5))
        if N2 != best.size:
            h_up = _resample(best, N2)
            h_up = _rescale(h_up)
            tlim = min(deadline - 1.5, time.process_time() + 2.0)
            hc = _full_lbfgs(h_up, tlim, maxiter=100)
            rc = R_of(hc)
            print("final upsample N=%d R=%.12f" % (N2, rc))
            if rc > bestR:
                best = hc; bestR = rc
            if rc > alt_bestR:
                alt_best = hc; alt_bestR = rc

    if alt_best is None:
        alt_best = best.copy()
        alt_bestR = bestR

    if startR > bestR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, alt %.12f, N=%d)"
          % (bestR, startR, alt_bestR, best.size))

    return {"best": best, "alternative": alt_best}

