    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _perturb(h, rng, sigma):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    return _rescale(h * np.exp(sigma * rng.standard_normal(h.size)))


def _refine_resample(h, factor):
    n = h.size
    n2 = min(int(n * factor), 900000)
    if n2 <= n:
        return h
    xi = np.linspace(0.0, n - 1, n2)
    return _rescale(np.interp(xi, np.arange(n), h))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(987654321)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 16384
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur, curR = best.copy(), bestR

    # Resolution refinement on the start.
    if best.size < 400000 and time.process_time() < deadline - 15.0:
        for factor in (1.5, 2.0):
            if time.process_time() > deadline - 15.0:
                break
            hr = _refine_resample(best, factor)
            if hr.size == best.size:
                continue
            ht = _lbfgs_all_pos(hr, 120, deadline, beta=0.0)
            rt = R_of(ht)
            if rt > curR + 1e-14:
                cur, curR = ht, rt
                if curR > bestR + 1e-14:
                    best, bestR = cur.copy(), curR
                print("  refine x%.1f N=%d R=%.7f" % (factor, best.size, bestR))
                break

    beta_seq = [200.0, 800.0, 3000.0, 0.0]
    pass_no = 0
    while time.process_time() < deadline - 3.0:
        pass_no += 1
        b = beta_seq[pass_no % len(beta_seq)]

        if time.process_time() < deadline - 4.0:
            hb = _lbfgs_all_pos(cur, 300, deadline, beta=b)
            rb = R_of(hb)
            if rb > curR + 1e-14:
                cur, curR = hb, rb
            print("  pass %d beta=%.0f R=%.7f" % (pass_no, b, rb))

        if curR > bestR + 1e-14:
            best, bestR = cur.copy(), curR

        # Perturbation restarts
        if pass_no % 3 == 0 and time.process_time() < deadline - 8.0:
            sigma = 0.001 + 0.0015 * ((pass_no // 3) % 5)
            cand = _perturb(best, rng, sigma)
            hc = _lbfgs_all_pos(cand, 150, deadline, beta=0.0)
            rc = R_of(hc)
            if rc > bestR + 1e-14:
                best, bestR = hc.copy(), rc
                cur, curR = hc.copy(), rc
                print("  perturb s=%.4f R=%.7f" % (sigma, bestR))

        # Occasionally multi-scale refinement
        if pass_no % 4 == 0 and best.size < 500000 and \
                time.process_time() < deadline - 12.0:
            hr = _refine_resample(best, 1.4)
            if hr.size > best.size:
                ht = _lbfgs_all_pos(hr, 150, deadline, beta=1000.0)
                rt = R_of(ht)
                if rt > bestR + 1e-14:
                    best, bestR = ht.copy(), rt
                    cur, curR = ht.copy(), rt
                    print("  re-refine N=%d R=%.7f" % (best.size, bestR))

    if time.process_time() < deadline - 1.0:
        hf = _lbfgs_all_pos(best, 500, deadline, beta=0.0)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if best.size != start_best.size and bestR > start_bestR - 1e-6:
        return {"best": start_best, "alternative": best}
    return start_best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish(h, deadline, iters=400):
    for beta in [1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        h = _lbfgs_all_pos(h, iters, deadline - 0.3, beta=beta)
    return h


def _coarse_optimize(h, B, deadline, iters=400):
    """Optimize block-mass softmax representation, then rasterize back."""
    n = h.size
    if B >= n or B < 4:
        return h
    edges = np.linspace(0, n, B + 1).astype(int)
    m = np.add.reduceat(h, edges[:-1])
    m = np.clip(m, 1e-300, None)
    u0 = np.log(m)

    def rasterize(u):
        uu = u - u.max()
        e = np.exp(uu)
        e /= e.sum()
        hB = np.empty(n)
        for j in range(B):
            hB[edges[j]:edges[j + 1]] = e[j]
        return hB, e

    def f(u):
        hB, p = rasterize(u)
        num, dq, Lf = _num_and_dq(hB)
        M = Lf.max()
        if M <= 0 or num <= 0:
            return 1e18, np.zeros(B)
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= M * (1.0 - 1e-9))
        gLf[idx] += (1.0 / idx.size) / M
        g_h = _backprop(gLf, hB)
        G = np.add.reduceat(g_h, edges[:-1])
        dot = np.dot(p, G)
        gu = p * (G - dot)
        val = -np.log(num) + np.log(M)
        return val, gu

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * B,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    hB, _ = rasterize(res.x)
    return _rescale(hB)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    alt_best, alt_bestR = None, -1.0
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase A: coarse-to-fine block-mass smoothing ----
    # Try several block counts; keep best candidate. This is a genuinely
    # different move: it reparametrises the height field by block masses
    # (softmax-normalized), which acts as a strong implicit regulariser and
    # lets gradients flow across the whole array at once.
    coarse_best = None
    coarse_bestR = -1.0
    if best.size >= 64 and time.process_time() < deadline - 8.0:
        n = best.size
        block_counts = [max(16, n // 24), max(16, n // 12),
                        max(16, n // 6), max(16, n // 3)]
        for B in block_counts:
            if time.process_time() >= deadline - 6.0:
                break
            slice_dl = min(deadline - 5.0,
                           time.process_time() + 0.06 * budget_seconds)
            hc = _coarse_optimize(best, B, slice_dl, iters=400)
            hc = _polish(hc, slice_dl, iters=300)
            rc = R_of(hc)
            print("coarse B=%d R=%.9f" % (B, rc))
            if rc > coarse_bestR:
                coarse_best, coarse_bestR = hc, rc
        if coarse_best is not None and coarse_bestR > bestR + 1e-14:
            best, bestR = coarse_best.copy(), coarse_bestR
            origin = 'coarse'
            print("coarse NEW BEST R=%.9f" % bestR)
        elif coarse_best is not None and coarse_bestR > alt_bestR:
            alt_best, alt_bestR = coarse_best.copy(), coarse_bestR

    # ---- Phase B: full-N polish ----
    if time.process_time() < deadline - 2.0:
        slice_dl = min(deadline - 1.5,
                       time.process_time() + 0.25 * budget_seconds)
        ht = _polish(best, slice_dl, iters=400)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+polish'
            print("polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase C: peak-window fine polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.12, 0.08, 0.05]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase D: trailing full polish ----
    if time.process_time() < deadline - 0.8:
        ht = best
        for beta in [1e6, 1e7, 0.0]:
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.4, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing polish NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

