    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    """CVaR-style objective: reward raising the top-alpha fraction of knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = max(1, int(round(alpha * n)))
    # top-k knots by value
    idx = np.argpartition(Lf, n - k)[n - k:]
    mx = Lf.max()
    Lm = max(mx, 1e-30)
    # objective: -log(num) + 2 log(s) + log(mean of top-k)
    top_mean = Lf[idx].mean()
    top_mean = max(top_mean, 1e-30)
    gLf = -dq / num
    w = 1.0 / (k * top_mean)
    gLf[idx] += w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(top_mean)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fg, active, tlim, maxiter=120):
    if time.process_time() >= tlim - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(active, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(tlim - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.95, pad_frac=0.5, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_window_polish(h, tlim):
    win = _peak_window(h, tol=0.95, pad_frac=0.5, extra=64)
    return _lbfgs_custom(h, _fun_grad_tie, win, tlim, maxiter=80)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max_abs(h, frac):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - frac) * mx))


def _zero_frac(h):
    return float(np.mean(h <= 1e-12))


def _max_over_mean(h):
    m = h.mean()
    if m <= 0:
        return 0.0
    return float(h.max() / m)


def _sparsify(h, frac):
    n = h.size
    k = int(round(frac * n))
    if k <= 0:
        return h.copy()
    if k >= n:
        k = n - 1
    order = np.argsort(h)
    hh = h.copy()
    hh[order[:k]] = 0.0
    return _rescale(hh)


def _report(tag, h):
    print("%s: R=%.9f zero=%.3f max/mean=%.2f near 0.1/1/5%%: %.4f/%.4f/%.4f"
          % (tag, R_of(h), _zero_frac(h), _max_over_mean(h),
             _frac_near_max_abs(h, 1e-3), _frac_near_max_abs(h, 1e-2),
             _frac_near_max_abs(h, 5e-2)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    _report("base", best)

    alt_best = None
    altR = -1.0

    cur = best.copy()
    curR = bestR

    def consider(h_new, tag):
        nonlocal best, bestR, alt_best, altR, cur, curR
        r = R_of(h_new)
        _report(tag, h_new)
        if r > altR:
            altR = r; alt_best = h_new.copy()
        if r > bestR + 1e-15:
            best, bestR = h_new.copy(), r
        if r > curR + 1e-15:
            cur, curR = h_new.copy(), r
        return r

    # (a) 1%-step anneal from frac=0.14 to 0.34
    def anneal(cur_h, cur_r):
        h = cur_h.copy()
        r = cur_r
        for frac in np.arange(0.14, 0.341, 0.01):
            if time.process_time() >= deadline - 2.5:
                break
            hs = _sparsify(h, frac)
            active = np.flatnonzero(hs > 0)
            tlim = min(deadline - 2.0, time.process_time() + 2.0)
            ht = _lbfgs_custom(hs, _fun_grad_tie, active, tlim, maxiter=150)
            if time.process_time() < deadline - 1.5:
                tlim = min(deadline - 1.0, time.process_time() + 1.0)
                hp = _peak_window_polish(ht, tlim)
            else:
                hp = ht
            rt = R_of(hp)
            _report("frac=%.2f" % frac, hp)
            if rt > r + 1e-15:
                h, r = hp, rt
                consider(hp, "accept frac=%.2f" % frac)
            else:
                h = hp
        return h, r

    # (b) CVaR ladder
    def cvar_ladder(cur_h, cur_r):
        h = cur_h.copy()
        r = cur_r
        for alpha in (0.05, 0.02, 0.01):
            if time.process_time() >= deadline - 2.5:
                break
            active = np.flatnonzero(h > 0)
            if active.size == 0:
                break
            fg = lambda hh, a=alpha: _fun_grad_cvar(hh, a)
            tlim = min(deadline - 2.0, time.process_time() + 1.5)
            ht = _lbfgs_custom(h, fg, active, tlim, maxiter=120)
            # final tie polish
            if time.process_time() < deadline - 1.0:
                tlim = min(deadline - 0.5, time.process_time() + 1.0)
                full = np.arange(ht.size)
                hp = _lbfgs_custom(ht, _fun_grad_tie, full, tlim, maxiter=100)
            else:
                hp = ht
            rt = R_of(hp)
            _report("alpha=%.2f" % alpha, hp)
            if rt > r + 1e-15:
                h, r = hp, rt
                consider(hp, "accept alpha=%.2f" % alpha)
        return h, r

    # (c) revival
    def revive(cur_h, cur_r):
        h = cur_h.copy()
        val, g = _fun_grad_tie(h)
        zero_idx = np.flatnonzero(h <= 1e-12)
        if zero_idx.size == 0:
            return h, cur_r
        k = min(200, zero_idx.size)
        order = np.argsort(g[zero_idx])[:k]
        pick = zero_idx[order]
        m = h.mean()
        if m <= 0:
            return h, cur_r
        h2 = h.copy()
        h2[pick] = 1e-3 * m
        h2 = _rescale(h2)
        active = np.flatnonzero(h2 > 0)
        tlim = min(deadline - 1.5, time.process_time() + 2.0)
        ht = _lbfgs_custom(h2, _fun_grad_tie, active, tlim, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim = min(deadline - 0.5, time.process_time() + 1.0)
            hp = _peak_window_polish(ht, tlim)
        else:
            hp = ht
        rt = R_of(hp)
        _report("revive", hp)
        if rt > cur_r + 1e-15:
            consider(hp, "accept revive")
            return hp, rt
        return h, cur_r

    # main cycle
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h, r = anneal(cur, curR)
        if time.process_time() >= deadline - 2.0:
            break
        h, r = cvar_ladder(h, r)
        if time.process_time() >= deadline - 2.0:
            break
        h, r = revive(h, r)
        if time.process_time() >= deadline - 2.0:
            break
        if r > curR + 1e-15:
            cur, curR = h, r
        else:
            if it > 3:
                break

    # Final exact tie polish
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.3, time.process_time() + 2.0)
        full = np.arange(cur.size)
        ht = _lbfgs_custom(cur, _fun_grad_tie, full, tlim, maxiter=120)
        r = R_of(ht)
        _report("final tie", ht)
        if r > altR:
            altR = r; alt_best = ht.copy()
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            break

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d, zeros=%.3f, max/mean=%.2f)"
          % (bestR, startR, best.size, _tie_count(best), _zero_frac(best),
             _max_over_mean(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _half_cycle(c, bestR, deadline, tag="", pads=None):
    best = c.copy()
    work = c.copy()
    origin = tag
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%sbeta%g" % (tag, beta)
    if pads is None:
        pads = [0.30, 0.20, 0.15, 0.10, 0.08]
    for it, pad in enumerate(pads):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
            origin = "%spk%d" % (tag, it)
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
                origin = "%spk%d+all0" % (tag, it)
    return work, best, bestR, origin


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _coarsen_blocksum(h, s, o):
    """Block-sum h[o::s] into a coarse quotient c (mass preserved per block)."""
    n = h.size
    idx = np.arange(o, n, s)
    if idx.size == 0:
        return None
    c = h[idx].copy()
    return c


def _prolongate(h_best, c, s, o):
    """Restore coarse mass c back into block positions h_best[o::s]."""
    h_new = h_best.copy()
    idx = np.arange(o, h_new.size, s)
    L = min(idx.size, c.size)
    h_new[idx[:L]] = c[:L]
    return _rescale(np.clip(h_new, 0, None))


def _log_param_lbfgs(c0, maxiter, deadline, cap):
    """Optimize c with log-parametrised entries, per-entry cap."""
    if time.process_time() >= deadline - 0.3:
        return c0
    c0 = np.clip(c0, 0.0, cap)
    if c0.sum() <= 0:
        return c0
    # log parametrisation: c = exp(x), clipped to cap
    eps = 1e-12
    x0 = np.log(np.clip(c0, eps, cap))

    def f(x):
        c = np.exp(np.clip(x, np.log(eps), np.log(cap)))
        val, g = _fun_grad(c)
        # chain rule: dc/dx = c
        return val, g * c

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c = np.exp(np.clip(res.x, np.log(eps), np.log(cap)))
    return _rescale(np.clip(c, 0.0, cap))


def _peak_window_polish(h, deadline, budget_seconds, bestR, alt_best, alt_bestR, origin):
    for pad in [0.10, 0.06, 0.04]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(h, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            h, bestR, origin = ht2.copy(), r2, origin + '+pk'
            print("peak polish NEW BEST R=%.9f" % bestR)
        elif r2 > alt_bestR:
            alt_best, alt_bestR = ht2.copy(), r2
    return h, bestR, alt_best, alt_bestR, origin


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    best_c = None
    best_cR = -1.0
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.20
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR, org = _half_cycle(
                work_c, best_cR, half_deadline, tag='h%d' % rounds)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        r_lift = R_of(h_lift)
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: 3-variant rotation of extract/lift cycles ----
    N = best.size
    m = N // 2
    cyc = 0
    variant_hits = [0.0, 0.0, 0.0]
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 5.0
        max_cycles = 6
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 4.0, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            if k == 0:
                c = wk[0::2][:m].copy()
            elif k == 1:
                c = wk[1::2][:m].copy()
            else:
                a = wk[0::2][:m]
                b = wk[1::2][:m]
                L = min(a.size, b.size)
                c = 0.5 * (a[:L] + b[:L])
                if c.size < m:
                    c = np.concatenate((c, np.full(m - c.size, c[-1])))
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR, org = _half_cycle(
                    c, cR0, slice_dl, tag='v%dcy%d' % (k, cyc),
                    pads=[0.30, 0.20, 0.12])
            except Exception as e:
                print("cycle %d variant %d exception %s" % (cyc, k, e))
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception as e:
                print("lift %d variant %d exception %s" % (cyc, k, e))
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                variant_hits[k] = max(variant_hits[k], r)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r
            if r > bestR - 1e-5:
                variant_hits[k] = max(variant_hits[k], r)
        print("rotation cycles=%d wR=%s" %
              (cyc, ["%.9f" % x for x in wR]))

    # ---- Phase 3: reserve last ~5s for peak-window + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    # ---- Phase 3e: discrete structural edits (move / split) ----
    struct_start = t0 + budget_seconds * 0.42
    struct_end = deadline - 5.0
    if time.process_time() < struct_start:
        while time.process_time() < struct_start - 0.05:
            time.sleep(0.01)
    if time.process_time() < struct_end - 1.0 and best.size >= 4:
        Ns = best.size
        rng = np.random.RandomState(12345)
        trial = 0
        accepted = 0
        while time.process_time() < struct_end - 1.0:
            act = np.flatnonzero(best > 0.02 * best.max())
            if act.size == 0:
                break
            perm = rng.permutation(act)
            progressed = False
            for i in perm:
                i = int(i)
                if time.process_time() >= struct_end - 1.0:
                    break
                now = time.process_time()
                slice_dl = min(now + 1.2, deadline - 5.0)
                if slice_dl <= now + 0.3:
                    break
                trial += 1
                cands = []
                # MOVE
                v = best[i]
                if v > 0:
                    for d in (-1, +1):
                        j = i + d
                        if 0 <= j < Ns and best[j] <= 0:
                            h2 = best.copy()
                            h2[i] = 0.0
                            h2[j] = h2[j] + v
                            cands.append(('move', d, h2))
                            break
                # SPLIT
                if i + 1 < Ns:
                    h2 = best.copy()
                    half = 0.5 * best[i]
                    h2[i] = half
                    h2[i + 1] = h2[i + 1] + half
                    cands.append(('split', 0, h2))
                best_local = None
                best_localR = -1.0
                best_type = None
                for typ, d, h2 in cands:
                    if time.process_time() >= slice_dl - 0.3:
                        break
                    h2 = _rescale(np.clip(h2, 0, None))
                    win = _peak_window(h2, pad_frac=0.15, extra=384)
                    h2 = _lbfgs_block(h2, win, 120, slice_dl, beta=1e6)
                    if time.process_time() < slice_dl - 0.3:
                        h2 = _lbfgs_all_pos(h2, 120, slice_dl, beta=1e7)
                    r2 = R_of(h2)
                    if r2 > best_localR:
                        best_local, best_localR, best_type = h2, r2, typ
                if best_local is None:
                    continue
                progressed = True
                if best_localR > bestR + 1e-13:
                    best, bestR = best_local.copy(), best_localR
                    origin = 'struct_%s' % best_type
                    accepted += 1
                    print("struct trial %d %s at i=%d (frac %.3f) NEW BEST R=%.9f" %
                          (trial, best_type, i, i / float(Ns), bestR))
                elif best_localR > alt_bestR:
                    alt_best, alt_bestR = best_local.copy(), best_localR
                if trial % 20 == 0:
                    print("struct trial %d type=%s R=%.9f (best %.9f, acc %d)" %
                          (trial, best_type, best_localR, bestR, accepted))
            if not progressed:
                break
        print("struct edits done trials=%d accepted=%d bestR=%.9f" %
              (trial, accepted, bestR))

    # ---- Phase 4: final peak pads + beta=0 ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_smooth(h, eps):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = Lf.max()
    band = Lf > (m - eps * m)
    w = np.zeros_like(Lf)
    w[band] = np.exp((Lf[band] - m) / (eps * m + 1e-30))
    Z = w.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = w / Z
    softmax = np.dot(w, Lf)
    if softmax <= 0:
        return _fun_grad(h)
    gLf = -dq / num + w / softmax
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(softmax)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, eps=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_smooth(hh, eps)) if eps > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, eps=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, eps=eps)


def _up_resample(h, N_big):
    n = h.size
    if n == N_big:
        return h.copy()
    x = np.linspace(0.0, 1.0, n)
    xb = np.linspace(0.0, 1.0, N_big)
    hb = np.interp(xb, x, h)
    return np.clip(hb, 0.0, None)


def _smooth_heights(h, k):
    if k <= 0:
        return h
    x = np.arange(-k, k + 1, dtype=float)
    ker = np.exp(-0.5 * (x / max(k / 2.0, 0.5)) ** 2)
    ker /= ker.sum()
    return np.clip(np.convolve(h, ker, mode='same'), 0.0, None)


def _perturb(h, sigma, rng):
    lp = np.log(np.clip(h, 1e-12, None))
    lp = lp + sigma * rng.standard_normal(h.size)
    hp = np.clip(np.exp(lp), 0.0, None)
    return _rescale(hp)


def _lbfgs_log(h0, maxiter, deadline, eps=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_smooth(hh, eps)) if eps > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(20240607)

    # NEW IDEA: refinement by upsampling to a finer grid, then continuing
    # optimisation on the finer grid. The start's local optimum on the coarse
    # grid is not a local optimum on a finer grid; upsampling + L-BFGS on the
    # fine grid can slide the shape into a better basin that was previously
    # unreachable. We alternate: (a) upsample current best to 2x steps and
    # polish, (b) full peak-window polish. If the finer grid gives a higher R,
    # keep it; if not, keep the coarse one but still return the finer as
    # alternative so future generations can build on it.

    coarse_best = best.copy()
    coarse_bestR = bestR

    # Stage 1: initial fine peak polish on current grid
    if time.process_time() < deadline - 20.0:
        h = _window_polish_peak(best, deadline, 0.60, 64, maxiter=400, eps=0.005)
        r = R_of(h)
        if r > bestR + 1e-12:
            best, bestR = h, r
        print("peak polish R=%.7f" % bestR)

    # Stage 2: upsampling refinement loop
    upsample_attempts = 0
    while time.process_time() < deadline - 6.0 and upsample_attempts < 6:
        upsample_attempts += 1
        n_cur = best.size
        # cap total N to keep fftconv cheap; up to ~200k
        if n_cur >= 150000:
            break
        N_big = min(int(n_cur * 2), 200000)
        if N_big <= n_cur + 16:
            break
        hb = _up_resample(best, N_big)
        hb = _rescale(hb)
        r0 = R_of(hb)
        # polish on fine grid
        hb = _lbfgs_log(hb, 400, deadline, eps=0.003 if upsample_attempts <= 2 else 0.0)
        if time.process_time() < deadline - 4.0:
            hb = _window_polish_peak(hb, deadline, 0.40, 96, maxiter=300, eps=0.0)
        if time.process_time() < deadline - 3.0:
            hb = _lbfgs_log(hb, 400, deadline, eps=0.0)
        r1 = R_of(hb)
        print("upsample x%d: N=%d R0=%.7f -> R1=%.7f" % (upsample_attempts, N_big, r0, r1))
        if r1 > bestR + 1e-12:
            best, bestR = hb, r1
            # continue upsampling from the improved fine grid
        else:
            # Fine grid did not beat coarse; keep the finer as an alternative
            # for future generations and break out (avoid wasting budget).
            if r1 > coarse_bestR - 1e-6:
                coarse_alt = hb.copy()
                coarse_altR = r1
            break

    # Stage 3: final sharp polish on the best
    for _ in range(5):
        if time.process_time() >= deadline - 1.0:
            break
        h = _lbfgs_log(best, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final sharp R=%.7f" % bestR)
        else:
            break
    if time.process_time() < deadline - 0.5:
        h = _window_polish_peak(best, deadline, 0.30, 48, maxiter=200, eps=0.0)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    # build an alternative: the finer grid if it exists, else a light perturbation
    alt = None
    try:
        alt = coarse_alt
    except NameError:
        alt = None
    if alt is None:
        alt = best
    if R_of(alt) < start_bestR - 1e-9:
        alt = start_best
    return {"best": start_best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_soft(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---- New idea: multiscale / block-coarsening refinement ----
# The optimum is believed to have a self-similar, possibly fractal structure.
# Coarsening the array to a smaller N, optimizing there (cheap, well-conditioned),
# then refining back up by interpolation gives a different basin than local
# height-space L-BFGS. Alternating coarse/fine polish explores new structure.

def _coarsen(h, m):
    """Reduce h (length N) to length ~N/m by averaging m-blocks."""
    n = h.size
    nb = n // m
    if nb < 8:
        return h.copy()
    trim = nb * m
    hb = h[:trim].reshape(nb, m).mean(axis=1)
    return hb


def _refine(hb, n):
    """Upsample coarse hb to length n by linear interpolation."""
    nb = hb.size
    x = np.linspace(0.0, 1.0, nb, endpoint=False)
    xn = np.linspace(0.0, 1.0, n, endpoint=False)
    return np.interp(xn, x, hb)


def _coarse_polish(h, deadline, m, iters=300):
    """Coarsen by factor m, L-BFGS on ALL coarse heights, refine back."""
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    hb = _coarsen(h, m)
    if hb.size < 8:
        return h
    # optimize the coarse representation fully (all free)
    free = np.arange(hb.size)
    hb2 = _lbfgs_block(hb, free, iters, deadline - 0.3, beta=0.0, tie=True)
    if hb2.sum() <= 0:
        return h
    # refine back to full resolution
    hr = _refine(hb2, n)
    hr = _rescale(hr)
    # quick fine polish near peak
    win = _peak_window(hr, pad_frac=0.10, extra=128)
    hp = _lbfgs_block(hr, win, 200, deadline - 0.3, beta=0.0, tie=True)
    return hp


def _warp(h, a, K):
    N = h.size
    j = np.arange(N + 1, dtype=float)
    t = j.copy()
    for k in range(1, K + 1):
        t += a[k - 1] * np.sin(2.0 * np.pi * k * j / N)
    t[0] = 0.0
    t[N] = float(N)
    if np.any(np.diff(t) <= 0):
        return None
    C = np.concatenate(([0.0], np.cumsum(h)))
    Ct = np.interp(t, j, C)
    hnew = np.diff(Ct)
    hnew = np.clip(hnew, 0.0, None)
    if hnew.sum() <= 0:
        return None
    return hnew


def _warp_bounds(N, K):
    k = np.arange(1, K + 1, dtype=float)
    return 0.15 * N / (2.0 * np.pi * k)


def _optimize_warp(h, K, deadline, x0=None):
    N = h.size
    b = _warp_bounds(N, K)
    if x0 is None:
        x0 = np.zeros(K)
    else:
        x0 = np.asarray(x0, dtype=float)[:K]
        if x0.size < K:
            x0 = np.concatenate([x0, np.zeros(K - x0.size)])
        x0 = np.clip(x0, -b, b)

    best = {'a': x0.copy(), 'R': R_of(h), 'h': h}
    h0R = best['R']

    def f(a):
        if time.process_time() > deadline:
            raise TimeoutError
        hh = _warp(h, a, K)
        if hh is None:
            return 1e6
        r = R_of(hh)
        if r > best['R']:
            best['R'] = r
            best['a'] = a.copy()
            best['h'] = hh
        return -r

    try:
        minimize(f, x0, method='Nelder-Mead',
                 options={'maxiter': 4000, 'xatol': 1e-6,
                          'fatol': 1e-12, 'adaptive': True})
    except (TimeoutError, Exception):
        pass
    if best['R'] > h0R:
        return best['h'], best['a'], best['R']
    return h, x0, h0R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- Phase A: multiscale coarsening sweep (new idea) ----
    phaseA_end = t0 + budget_seconds * 0.40
    for m in (8, 16, 32, 64):
        if time.process_time() >= phaseA_end - 3.0:
            break
        ht = _coarse_polish(best, phaseA_end - 1.0, m, iters=250)
        # try a fine peak-ladder polish on the refined candidate
        if time.process_time() < phaseA_end - 2.0:
            for pad in (0.06, 0.03):
                if time.process_time() >= phaseA_end - 1.5:
                    break
                win = _peak_window(ht, pad_frac=pad, extra=96)
                h2 = _lbfgs_block(ht, win, 200, phaseA_end - 0.8,
                                  beta=0.0, tie=True)
                if R_of(h2) > R_of(ht):
                    ht = h2
        rt = R_of(ht)
        if rt > bestR + 1e-15:
            best, bestR = ht.copy(), rt
            print("PHASE A coarse m=%d ACCEPT R=%.9f" % (m, bestR))
        else:
            print("PHASE A coarse m=%d no gain R=%.9f" % (m, rt))

    # ---- Phase B: warp K=16 then K=32 (search new basin) ----
    phaseB_end = t0 + budget_seconds * 0.62
    if time.process_time() < phaseB_end - 2.0:
        hw, a16, rw = _optimize_warp(best, 16, phaseB_end - 0.5)
        dR = rw - bestR
        print("PHASE B warp K=16 dR=%+.3e R=%.9f" % (dR, rw))
        if rw > bestR + 1e-9:
            best, bestR = hw.copy(), rw
        else:
            # still try polishing the warped candidate (may escape basin)
            win = _peak_window(hw, pad_frac=0.05, extra=128)
            h2 = _lbfgs_block(hw, win, 250, phaseB_end - 0.5, tie=True)
            if R_of(h2) > bestR + 1e-9:
                best, bestR = h2.copy(), R_of(h2)
                print("PHASE B polish ACCEPT R=%.9f" % bestR)

    phaseC_end = t0 + budget_seconds * 0.78
    if time.process_time() < phaseC_end - 2.0:
        hw, a32, rw = _optimize_warp(best, 32, phaseC_end - 0.5)
        dR = rw - bestR
        print("PHASE C warp K=32 dR=%+.3e R=%.9f" % (dR, rw))
        if rw > bestR + 1e-9:
            best, bestR = hw.copy(), rw

    # ---- Phase D: soft-max polish (beta increasing) ----
    phaseD_end = t0 + budget_seconds * 0.86
    if time.process_time() < phaseD_end - 2.0:
        win = _peak_window(best, pad_frac=0.05, extra=128)
        cur = best
        for beta in (1e3, 1e5, 1e6):
            if time.process_time() >= phaseD_end - 1.0:
                break
            h2 = _lbfgs_block(cur, win, 200, phaseD_end - 0.5,
                              beta=beta, tie=False)
            if R_of(h2) > R_of(cur):
                cur = h2
        rt = R_of(cur)
        if rt > bestR + 1e-15:
            best, bestR = cur.copy(), rt
            print("PHASE D soft ACCEPT R=%.9f" % bestR)
        else:
            print("PHASE D soft no gain R=%.9f" % rt)

    # ---- Final: tight peak polish with tie ----
    fd = t0 + budget_seconds * 0.92
    while time.process_time() < fd - 0.6:
        win = _peak_window(best, pad_frac=0.015, extra=64)
        ht = _lbfgs_block(best, win, 250, fd - 0.3, tie=True)
        rt = R_of(ht)
        if rt > bestR + 1e-16:
            best, bestR = ht.copy(), rt
            print("FINAL peak ACCEPT R=%.9f" % bestR)
            fd = min(fd, time.process_time() + 1.5)
        else:
            break

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


# ---- NEW: squared parametrisation solver ----
def _sq_param_lbfgs(c0, maxiter, deadline, beta=0.0, cap=None):
    """Optimize c = clip(x,0,None)^2 with unconstrained L-BFGS-B on x."""
    if time.process_time() >= deadline - 0.3:
        return c0
    c0 = np.clip(c0, 0.0, None)
    if c0.sum() <= 0:
        return c0
    if cap is None:
        cap = max(c0.max(), 1e-12) * 4.0
    x0 = np.sqrt(np.clip(c0, 0.0, cap))
    lim = np.sqrt(cap)
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        c = np.clip(x, 0.0, None) ** 2
        val, g = fg(c)
        # chain rule: dc/dx = 2*clip(x,0,None)
        return val, g * (2.0 * np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-lim, lim)] * x0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c = np.clip(res.x, 0.0, None) ** 2
    return _rescale(c)


def _sq_polish_full(h, deadline, maxiter=150):
    """Full-N squared-param polish with beta ramp 1e6, 1e7, then exact."""
    cur = h
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.4:
            break
        ht = _sq_param_lbfgs(cur, maxiter, deadline - 0.3, beta=beta)
        if R_of(ht) >= R_of(cur) - 1e-15:
            cur = ht
    return cur


def _inject_mass(h, frac=0.05, scale=1e-3, rng=None):
    """Add scale*max(h) to a random frac of currently-zero cells."""
    if rng is None:
        rng = np.random.RandomState()
    h = h.copy()
    zeros = np.flatnonzero(h <= 0)
    if zeros.size == 0:
        return h
    k = max(1, int(frac * zeros.size))
    if k >= zeros.size:
        sel = zeros
    else:
        sel = rng.choice(zeros, size=k, replace=False)
    mx = h.max()
    if mx <= 0:
        return h
    h[sel] += scale * mx
    return _rescale(h)


def _coarsen_blocksum(h, s, o):
    idx = np.arange(o, h.size, s)
    if idx.size == 0:
        return None
    return h[idx].copy()


def _prolongate(h_best, c, s, o):
    h_new = h_best.copy()
    idx = np.arange(o, h_new.size, s)
    L = min(idx.size, c.size)
    h_new[idx[:L]] = c[:L]
    return _rescale(np.clip(h_new, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0
    rng = np.random.RandomState(2024)

    # ---- NEW Phase A: squared-param offset/odd coarsening cycles ----
    N = best.size
    cycle_end = deadline - 2.0
    cyc = 0
    if N >= 6:
        while time.process_time() < cycle_end - 1.0:
            cyc += 1
            now = time.process_time()
            slice_dl = min(cycle_end, now + 0.10 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            # choose stride/offset
            s = 2 if (cyc % 2 == 1) else 3
            o = cyc % s
            c0 = _coarsen_blocksum(best, s, o)
            if c0 is None or c0.size < 4:
                continue
            cR0 = R_of(c0)
            # squared-param optimize the coarse quotient
            c = c0.copy()
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ct = _sq_param_lbfgs(c, 150, slice_dl - 0.3, beta=beta)
                if R_of(ct) >= R_of(c) - 1e-15:
                    c = ct
            cR = R_of(c)
            # prolongate back
            hnew = _prolongate(best, c, s, o)
            # inject mass into random zero cells
            hnew = _inject_mass(hnew, frac=0.05, scale=1e-3, rng=rng)
            # full-N squared-param polish
            ht = _sq_polish_full(hnew, slice_dl, maxiter=150)
            r = R_of(ht)
            # peak-window polish
            if time.process_time() < slice_dl - 0.5:
                win = _peak_window(ht, pad_frac=0.10, extra=128)
                ht2 = _lbfgs_block(ht, win, 200, slice_dl - 0.3, beta=1e7)
                r2 = R_of(ht2)
                if r2 > r:
                    ht, r = ht2, r2
            zeros = float(np.mean(ht <= 0))
            print("cyc %d s=%d o=%d R(c)=%.9f liftR=%.9f zeros=%.3f (best %.9f)" %
                  (cyc, s, o, cR, r, zeros, bestR))
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'sq_s%d_o%d_cy%d' % (s, o, cyc)
                print("  SQ NEW BEST R=%.9f zeros=%.3f" % (bestR, zeros))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase B: reserve last seconds for peak-window + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    zeros_final = float(np.mean(best <= 0))
    print("final R=%.9f origin=%s zeros=%.3f (start %.9f, N=%d)" %
          (bestR, origin, zeros_final, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
