    dmax = np.zeros_like(Lf)
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    dmax[idx] = 1.0 / idx.size
    dD = 2.0 * s * mx * np.ones_like(h) + s * s * _backprop(dmax, h)
    dnum = _backprop(dq, h)
    grad = dnum - lam * dD
    val = -(num - lam * s * s * mx) / max(num, 1e-300)
    return val, grad


def _fun_grad_al(h, S, lam, rho):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idxmax = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    gLf[idxmax] += (1.0 / idxmax.size) / M
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    if S.size > 0:
        Lj = Lf[S]
        r = Lj / M - 1.0
        val += np.sum(lam * r + 0.5 * rho * r * r)
        gLf[S] += (lam + rho * r) / M
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _al_round(h, deadline, rho, lam, maxiter=300):
    Lf = _knots(h)
    M = Lf.max()
    S = np.flatnonzero(Lf >= M * (1.0 - 1e-6))
    if lam is None or lam.size != S.size:
        lam = np.zeros(S.size)
    hc = _lbfgs_custom(h, lambda hh: _fun_grad_al(hh, S, lam, rho),
                       deadline, maxiter=maxiter)
    Lf2 = _knots(hc)
    M2 = Lf2.max()
    r = Lf2[S] / M2 - 1.0
    lam = lam + rho * r
    return hc, S, lam, r


def _repeat_lift(v, m):
    return np.tile(v, m)


def _extract_block(h, K):
    n = h.size
    blk = n // K
    if blk < 1:
        return None
    return h[:blk * K].reshape(K, blk).mean(axis=1)


def _pad_candidate(h0, side, m, rho):
    """Build extended array with a decaying tail on the given side(s)."""
    h0 = np.asarray(h0, dtype=float)
    n = h0.size
    m = int(m)
    if m < 1:
        return None
    j = np.arange(1, m + 1, dtype=float)
    tail = rho ** j
    left_edge = h0[0] if h0[0] > 0 else (h0.max() * 1e-3)
    right_edge = h0[-1] if h0[-1] > 0 else (h0.max() * 1e-3)
    if side == 'left':
        ext = np.concatenate((left_edge * tail[::-1], h0))
    elif side == 'right':
        ext = np.concatenate((h0, right_edge * tail))
    elif side == 'both':
        ext = np.concatenate((left_edge * tail[::-1], h0, right_edge * tail))
    elif side == 'asym':
        ext = np.concatenate((left_edge * tail[::-1], h0, right_edge * tail))
    else:
        return None
    if ext.sum() <= 0:
        return None
    return ext


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    s0 = h0.sum()
    N0 = h0.size

    # (b) Build 48 padding candidates
    sides = ['left', 'right', 'both', 'asym']
    m_fracs = [N0 // 64, N0 // 16, N0 // 4]
    rhos = [0.5, 0.7, 0.85, 0.95]

    candidates = []
    for side in sides:
        for m in m_fracs:
            if m < 1:
                continue
            for rho in rhos:
                ext = _pad_candidate(h0, side, m, rho)
                if ext is None:
                    continue
                # rescale to sum s0
                if ext.sum() <= 0:
                    continue
                ext = ext * (s0 / ext.sum())
                candidates.append((side, m, rho, ext))

    print("built %d padding candidates" % len(candidates))

    # (c) short polish each candidate
    scored = []
    for (side, m, rho, ext) in candidates:
        if time.process_time() >= deadline - 1.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 0.25)
        try:
            hc = _lbfgs_custom(ext, _fun_grad_tie, tlim, maxiter=60)
        except Exception:
            hc = ext
        rc = R_of(hc)
        scored.append((rc, side, m, rho, hc))

    scored.sort(key=lambda x: -x[0])
    if scored:
        print("top pad: %s m=%d rho=%.2f R=%.9f (base %.9f)"
              % (scored[0][1], scored[0][2], scored[0][3], scored[0][0], startR))

    # (d) take best 3, alternate polish
    top3 = scored[:3]
    phase_d_end = min(deadline - 1.0, t0 + budget_seconds * 0.55)

    for (rc0, side, m, rho, hc) in top3:
        if hc is None:
            continue
        cur = hc
        curR = rc0
        # alternating: full L-BFGS (3s), peak polish (1.5s), CVaR round
        if time.process_time() < phase_d_end:
            tlim = min(phase_d_end, time.process_time() + 3.0)
            hc2 = _full_lbfgs(cur, tlim, maxiter=150)
            rc = R_of(hc2)
            if rc > curR:
                cur = hc2; curR = rc
        if time.process_time() < phase_d_end:
            tlim = min(phase_d_end, time.process_time() + 1.5)
            hc2 = _peak_window_polish(cur, tlim, pad=3)
            rc = R_of(hc2)
            if rc > curR:
                cur = hc2; curR = rc
        if time.process_time() < phase_d_end:
            tlim = min(phase_d_end, time.process_time() + 2.0)
            try:
                hc2 = _lbfgs_custom(cur, lambda hh: _fun_grad_cvar(hh, 0.05),
                                    tlim, maxiter=120)
                rc = R_of(hc2)
                if rc > curR:
                    cur = hc2; curR = rc
            except Exception:
                pass
        if curR > bestR:
            best = cur
            bestR = curR
            print("pad win: %s m=%d rho=%.2f R=%.9f" % (side, m, rho, bestR))

    # final long polish loop
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 2.0)
        hc = _full_lbfgs(best, tlim, maxiter=150)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
        if time.process_time() < deadline - 1.0:
            tlim = min(deadline - 0.5, time.process_time() + 1.5)
            hc = _peak_window_polish(best, tlim, pad=3)
            rc = R_of(hc)
            if rc > bestR:
                best = hc; bestR = rc
        print("polish R=%.12f (best %.12f)" % (rc, bestR))

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    # Report padded-cell mass fraction for the winner (if it has padding)
    if best.size > N0:
        # estimate padded mass: extra cells beyond N0
        extra = best.size - N0
        # assume padding split; just report total mass in cells outside original indices
        # find where original support likely sits: compare to h0 pattern via correlation is overkill
        # simpler: report mass in first/last extra cells assuming symmetric padding
        # We conservatively report mass in the first and last `extra//2` cells
        half = extra // 2
        if half > 0:
            pad_mass = best[:half].sum() + best[-half:].sum()
        else:
            pad_mass = best[:extra].sum()
        frac = pad_mass / max(best.sum(), 1e-300)
        print("winner padded mass fraction=%.6f (N=%d, N0=%d)"
              % (frac, best.size, N0))
    else:
        print("winner has no padding (N=%d, N0=%d)" % (best.size, N0))

    print("final R=%.12f (start %.12f, N=%d)"
          % (bestR, startR, best.size))

    # alternative: best padding candidate (different construction)
    alt = best
    if scored:
        alt = scored[0][4]
        if alt is None or R_of(alt) < startR * 0.5:
            alt = best

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


# ---- free-width block helpers ----

def _rasterize(bounds, amps, N):
    h = np.zeros(N)
    M = len(amps)
    for j in range(M):
        lo = bounds[j]; hi = bounds[j + 1]
        if hi > lo:
            h[lo:hi] = amps[j]
    return h


def _block_grad(h, bounds, M):
    val, g = _fun_grad_tie(h)
    gb = np.zeros(M)
    for j in range(M):
        lo = bounds[j]; hi = bounds[j + 1]
        if hi > lo:
            gb[j] = g[lo:hi].sum()
    return val, gb


def _opt_heights(h, bounds, M, deadline, maxiter=150):
    amps = np.array([h[bounds[j]:bounds[j + 1]].mean() if bounds[j + 1] > bounds[j]
                     else 0.0 for j in range(M)])
    pos = np.flatnonzero(amps > 0)
    if pos.size == 0:
        return h
    floor = 1e-9 * max(amps.max(), 1e-12)
    u0 = np.log(np.clip(amps[pos], floor, None))

    def f(u):
        a = amps.copy()
        a[pos] = np.exp(u)
        hh = _rasterize(bounds, a, h.size)
        val, gb = _block_grad(hh, bounds, M)
        return val, gb[pos] * a[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    a = amps.copy()
    a[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(_rasterize(bounds, a, h.size))


def _pattern_search_widths(h, bounds, M, deadline, N, max_steps=60):
    bounds = bounds.copy()
    cur = h.copy()
    curR = R_of(cur)
    step = 4
    it = 0
    while step >= 1 and time.process_time() < deadline - 0.5 and it < max_steps:
        it += 1
        improved = False
        for j in range(1, M):
            if time.process_time() >= deadline - 0.5:
                break
            for d in (-step, step):
                nb = bounds.copy()
                nb[j] += d
                ok = True
                for k in range(M):
                    if nb[k + 1] - nb[k] < 2:
                        ok = False; break
                if not ok:
                    continue
                if nb[0] < 0 or nb[M] > N:
                    continue
                hh = _opt_heights(cur, nb, M, min(deadline, time.process_time() + 0.5),
                                  maxiter=60)
                rr = R_of(hh)
                if rr > curR + 1e-12:
                    cur = hh; curR = rr; bounds = nb; improved = True
                    break
            if improved:
                break
        if not improved:
            step //= 2
    return cur, bounds, curR


def _boundary_pass(h, bounds, M, deadline, N, max_sweeps=3):
    """Greedy boundary-move pass: shift each interior boundary by +-1,+-2 cells."""
    bounds = bounds.copy()
    cur = h.copy()
    curR = R_of(cur)
    rng = np.random.default_rng(int(time.process_time() * 1e6) & 0xffffffff)
    for sweep in range(max_sweeps):
        if time.process_time() >= deadline - 0.5:
            break
        improved_any = False
        order = np.arange(1, M)
        rng.shuffle(order)
        for j in order:
            if time.process_time() >= deadline - 0.5:
                break
            best_local = None
            best_localR = curR
            for d in (-2, -1, 1, 2):
                if time.process_time() >= deadline - 0.5:
                    break
                nb = bounds.copy()
                nb[j] += d
                ok = True
                for k in range(M):
                    if nb[k + 1] - nb[k] < 2:
                        ok = False; break
                if not ok:
                    continue
                if nb[0] < 0 or nb[M] > N:
                    continue
                hh = _opt_heights(cur, nb, M,
                                  min(deadline, time.process_time() + 0.4),
                                  maxiter=50)
                rr = R_of(hh)
                if rr > best_localR + 1e-13:
                    best_localR = rr
                    best_local = (hh, nb)
            if best_local is not None:
                cur, bounds = best_local
                curR = best_localR
                improved_any = True
        if not improved_any:
            break
    return cur, bounds, curR


def _prolongate(bounds0, amps0, N0, N):
    M = len(amps0)
    bN = np.round(np.asarray(bounds0, dtype=float) * (N / N0)).astype(int)
    bN[0] = 0; bN[M] = N
    for j in range(1, M + 1):
        if bN[j] <= bN[j - 1]:
            bN[j] = bN[j - 1] + 1
    if bN[M] > N:
        bN[M] = N
        for j in range(M - 1, -1, -1):
            if bN[j] >= bN[j + 1]:
                bN[j] = bN[j + 1] - 1
        bN[0] = max(0, bN[0])
    return _rasterize(bN, amps0, N), bN


def _extract_amps(h, bounds, M):
    return np.array([h[bounds[j]:bounds[j + 1]].mean() if bounds[j + 1] > bounds[j]
                     else 0.0 for j in range(M)])


def _split_widest(bounds, amps, M, N, rng, frac_blocks=0.5):
    """Split only the widest frac_blocks of blocks in two at random interior fraction."""
    widths = np.array([bounds[j + 1] - bounds[j] for j in range(M)])
    nsplit = max(1, int(round(frac_blocks * M)))
    order = np.argsort(-widths)
    to_split = set(order[:nsplit].tolist())
    new_bounds = [bounds[0]]
    new_amps = []
    for j in range(M):
        lo = bounds[j]; hi = bounds[j + 1]
        w = hi - lo
        if j in to_split and w >= 4:
            frac = rng.uniform(0.4, 0.6)
            cut = lo + max(1, min(w - 1, int(round(frac * w))))
        else:
            cut = None
        if cut is None:
            new_bounds.append(hi)
            new_amps.append(amps[j])
        else:
            new_bounds.append(cut)
            new_bounds.append(hi)
            new_amps.append(amps[j])
            new_amps.append(amps[j])
    nb = np.array(new_bounds, dtype=int)
    nb[0] = 0
    nb[-1] = N
    for j in range(1, len(nb)):
        if nb[j] <= nb[j - 1]:
            nb[j] = nb[j - 1] + 1
    if nb[-1] > N:
        nb[-1] = N
        for j in range(len(nb) - 2, -1, -1):
            if nb[j] >= nb[j + 1]:
                nb[j] = nb[j + 1] - 1
        nb[0] = max(0, nb[0])
    return nb, np.array(new_amps)


def _split_blocks(bounds, amps, M, N, rng):
    """Split every block in two at random interior fraction 0.4-0.6."""
    new_bounds = [bounds[0]]
    new_amps = []
    for j in range(M):
        lo = bounds[j]; hi = bounds[j + 1]
        w = hi - lo
        if w >= 2:
            frac = rng.uniform(0.4, 0.6)
            cut = lo + max(1, min(w - 1, int(round(frac * w))))
        else:
            cut = lo + 1 if lo + 1 <= hi else hi
        if cut <= lo:
            cut = lo + 1
        if cut >= hi:
            cut = hi - 1 if hi - 1 > lo else lo
        new_bounds.append(cut)
        new_bounds.append(hi)
        new_amps.append(amps[j])
        new_amps.append(amps[j])
    nb = np.array(new_bounds, dtype=int)
    nb[0] = 0
    nb[-1] = N
    for j in range(1, len(nb)):
        if nb[j] <= nb[j - 1]:
            nb[j] = nb[j - 1] + 1
    if nb[-1] > N:
        nb[-1] = N
        for j in range(len(nb) - 2, -1, -1):
            if nb[j] >= nb[j + 1]:
                nb[j] = nb[j + 1] - 1
        nb[0] = max(0, nb[0])
    return nb, np.array(new_amps)


def _near_max_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(Lf >= mx * 0.999) * 100.0,
            np.mean(Lf >= mx * 0.99) * 100.0,
            np.mean(Lf >= mx * 0.95) * 100.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(20240117)
    N0 = 4096
    Nfull = h0.size if h0.size >= 4096 else 104992

    # ---- Level M=8: best of several random Dirichlet starts ----
    M = 8
    best_coarse = None
    best_coarseR = -1.0
    level_end = min(deadline - 1.0, t0 + budget_seconds * 0.08)
    trials = 0
    while trials < 20 and time.process_time() < level_end:
        trials += 1
        cuts = np.sort(rng.choice(np.arange(4, N0 - 3, 1), size=M - 1, replace=False))
        bounds = np.concatenate(([0], cuts, [N0])).astype(int)
        for j in range(1, M + 1):
            if bounds[j] - bounds[j - 1] < 4:
                bounds[j] = bounds[j - 1] + 4
        if bounds[M] > N0:
            bounds[M] = N0
            for j in range(M - 1, -1, -1):
                if bounds[j] >= bounds[j + 1] - 3:
                    bounds[j] = bounds[j + 1] - 4
            bounds[0] = max(0, bounds[0])
        amps = np.exp(rng.uniform(-2, 2, M))
        h0c = _rescale(_rasterize(bounds, amps, N0))
        tlim = min(level_end, time.process_time() + 0.3)
        hc = _opt_heights(h0c, bounds, M, tlim, maxiter=80)
        rc = R_of(hc)
        if rc > best_coarseR:
            best_coarseR = rc
            best_coarse = (hc.copy(), bounds.copy(), _extract_amps(hc, bounds, M).copy())

    if best_coarse is None:
        bounds = np.linspace(0, N0, M + 1).astype(int)
        amps = np.ones(M)
        hc = _rescale(_rasterize(bounds, amps, N0))
        best_coarse = (hc, bounds, amps)
        best_coarseR = R_of(hc)

    cur_h, cur_bounds, cur_amps = best_coarse
    curR = best_coarseR
    print("M=%d R=%.9f (coarse init)" % (M, curR))

    def polish_full(hc, bounds, M, tlim, pad=0.05):
        hf, bN = _prolongate(bounds, _extract_amps(hc, bounds, M), N0, Nfull)
        hf = _rescale(hf)
        r = R_of(hf)
        h1 = _opt_heights(hf, bN, M, min(tlim, time.process_time() + 1.5), maxiter=150)
        r1 = R_of(h1)
        if r1 > r:
            hf = h1; r = r1
        h2 = _full_lbfgs(hf, min(tlim, time.process_time() + 1.5), maxiter=150)
        r2 = R_of(h2)
        if r2 > r:
            hf = h2; r = r2
        h3 = _peak_window_polish(hf, min(tlim, time.process_time() + 1.0),
                                 pad=max(1, int(pad * hf.size)))
        r3 = R_of(h3)
        if r3 > r:
            hf = h3; r = r3
        return hf, r

    # initial full polish of M=8
    tlim = min(deadline - 1.0, time.process_time() + 3.0)
    hf, rf = polish_full(cur_h, cur_bounds, M, tlim)
    if rf > bestR:
        best = hf.copy(); bestR = rf
    print("M=%d R=%.9f full" % (M, rf))

    # ---- M-doubling homotopy: 16, 32, 64, 128, 256, 512, 1024, 2048 ----
    levels = [16, 32, 64, 128, 256, 512, 1024, 2048]
    # reserve 30% of budget for final re-polish
    homotopy_end = t0 + budget_seconds * 0.63
    # skip to highest L that still gets >=3s per level
    remaining_levels = []
    for idx, L in enumerate(levels):
        levels_left = len(levels) - idx
        if (homotopy_end - time.process_time()) / max(1, levels_left) >= 3.0:
            remaining_levels.append(L)
    if not remaining_levels:
        remaining_levels = [16]

    for L in remaining_levels:
        if time.process_time() >= homotopy_end - 1.0:
            break
        levels_left = len([x for x in remaining_levels if x >= L])
        per_level = max(3.0, (homotopy_end - time.process_time()) / max(1, levels_left))
        level_end = min(homotopy_end - 0.5, time.process_time() + per_level)

        # split only the widest 50% of blocks
        nb, na = _split_widest(cur_bounds, cur_amps, M, N0, rng, frac_blocks=0.5)
        M = len(na)
        hc = _rescale(_rasterize(nb, na, N0))
        # height polish
        hc = _opt_heights(hc, nb, M, min(level_end, time.process_time() + per_level * 0.25),
                          maxiter=120)
        # width pattern search
        hc, nb, rc = _pattern_search_widths(hc, nb, M, level_end, N0, max_steps=40)
        # greedy boundary move pass
        hc, nb, rc = _boundary_pass(hc, nb, M, level_end, N0, max_sweeps=3)
        # re-optimise heights
        hc = _opt_heights(hc, nb, M, min(level_end, time.process_time() + per_level * 0.15),
                          maxiter=120)
        rc = R_of(hc)
        cur_h, cur_bounds = hc, nb
        cur_amps = _extract_amps(hc, nb, M)
        curR = rc

        # full polish
        tlim = min(level_end, time.process_time() + per_level * 0.35)
        hf, rf = polish_full(cur_h, cur_bounds, M, tlim, pad=0.05)
        if rf > bestR:
            best = hf.copy(); bestR = rf

        nz = np.mean(hf <= 1e-12)
        mm = hf.max() / max(hf.mean(), 1e-300)
        s01, s1, s5 = _near_max_shares(hf)
        print("M=%d R=%.9f zeros=%.3f max/mean=%.2f shares=%.2f/%.2f/%.2f"
              % (M, rf, nz, mm, s01, s1, s5))

    # ---- final re-polish of overall best (last ~30%) ----
    print("final polish, best so far R=%.9f" % bestR)
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.3, time.process_time() + 2.0)
        hc = _full_lbfgs(best, tlim, maxiter=300)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
        if time.process_time() < deadline - 0.5:
            for pad in (0.15, 0.06, 0.02):
                if time.process_time() >= deadline - 0.5:
                    break
                tlim = min(deadline - 0.3, time.process_time() + 1.0)
                hc = _peak_window_polish(best, tlim, pad=max(1, int(pad * best.size)))
                rc = R_of(hc)
                if rc > bestR:
                    best = hc; bestR = rc
        if time.process_time() < deadline - 0.5:
            tlim = min(deadline - 0.3, time.process_time() + 1.5)
            hc = _lbfgs_custom(best, lambda hh: _fun_grad_cvar(hh, 0.05), tlim, maxiter=150)
            rc = R_of(hc)
            if rc > bestR:
                best = hc; bestR = rc
        print("polish R=%.12f (best %.12f)" % (rc, bestR))

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _refine(h, deadline, levels=(2, 3, 4)):
    """Upsample via linear interpolation to finer grids and polish on each."""
    best = _rescale(h.copy())
    bestR = R_of(best)
    n0 = best.size
    for fac in levels:
        if time.process_time() >= deadline - 0.5:
            break
        n = min(1000000, n0 * fac)
        if n <= best.size:
            continue
        x_old = np.linspace(0.0, 1.0, best.size)
        x_new = np.linspace(0.0, 1.0, n)
        h_up = np.interp(x_new, x_old, best)
        h_up = _rescale(np.clip(h_up, 0, None))
        r_up = R_of(h_up)
        if r_up > bestR:
            best = h_up; bestR = r_up
        # polish on the finer grid
        tlim = min(deadline - 0.3, time.process_time() + 4.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 1: polish the given start well
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    # Phase 2: refinement cascade (upsample + polish) -- the main new idea
    alt_best = best.copy()
    altR = bestR
    if time.process_time() < deadline - 2.0:
        hc, rc = _refine(best, deadline - 0.5)
        if rc > bestR:
            best = hc; bestR = rc
            print("refined R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 3: continue polishing on finest grid
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    alt = alt_best if altR > 0 else best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if beta > 0:
        fg = (lambda hh: _fun_grad_cvar(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_cvar(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _stats_line(tag, h, r):
    pos = h > 0
    mean_pos = h[pos].mean() if pos.any() else 0.0
    mx = h.max() if h.size else 0.0
    ratio = mx / mean_pos if mean_pos > 0 else 0.0
    print("%s: N=%d zeros=%.1f%% max/mean=%.2f R=%.7f band01=%.2f%% band1=%.2f%% band5=%.2f%%" %
          (tag, h.size, 100.0 * np.mean(h <= 0), ratio, r,
           100.0 * _band_frac(h, 1e-3), 100.0 * _band_frac(h, 1e-2),
           100.0 * _band_frac(h, 5e-2)))


def _modern_schedule(h, deadline):
    best = _rescale(np.clip(h, 0, None))
    bestR = R_of(best)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 250, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    # CVaR smoothing at decreasing alpha to escape single-knot max trap
    for alpha in (0.02, 0.01, 0.005):
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(best, 200, deadline - 0.5, beta=alpha)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64), (0.10, 64), (0.25, 128), (0.40, 256)]
    for frac, extra in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _find_runs(h):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    pos = h > 0
    n = h.size
    runs = []
    i = 0
    while i < n:
        if pos[i]:
            j = i
            while j + 1 < n and pos[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _upsample2(h):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    out = np.empty(2 * h.size, dtype=float)
    out[0::2] = h
    out[1::2] = h
    return out


def _thin_runs(h_orig, h_fine, frac=0.5):
    h_orig = np.clip(np.asarray(h_orig, dtype=float), 0, None)
    out = np.zeros_like(h_fine)
    n_fine = h_fine.size
    for (i, j) in _find_runs(h_orig):
        k = j - i + 1
        mass = h_orig[i:j + 1].sum()
        m = max(1, int(np.ceil(k * frac)))
        lo = 2 * i
        hi = 2 * j + 1
        center = (lo + hi) // 2
        a = center - m // 2
        b = a + m - 1
        if a < 0:
            a = 0
            b = m - 1
        if b >= n_fine:
            b = n_fine - 1
            a = b - m + 1
        if a < 0:
            a = 0
        width = b - a + 1
        if width <= 0:
            continue
        out[a:b + 1] += mass / width
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    alt_cand = None
    altR = -1.0
    best = start_best.copy()
    bestR = start_bestR

    # Upsample + thinning exploration branch (may or may not beat start)
    exp_h = None
    expR = -1.0
    try:
        h_orig = start_best.copy()
        hA = _upsample2(h_orig)
        rA = R_of(hA)
        print("StageA: N=%d R=%.10f" % (hA.size, rA))
        _stats_line("StageA", hA, rA)

        now = time.process_time()
        remaining = max(0.0, deadline - now)
        reserve = min(12.0, 0.25 * remaining)
        explore_deadline = deadline - reserve

        candidates = [(hA, rA, "unthin")]
        for frac in (0.5, 0.6, 0.4):
            if time.process_time() >= explore_deadline:
                break
            hT = _thin_runs(h_orig, hA, frac=frac)
            rT = R_of(hT)
            hp, rp = _modern_schedule(hT, min(explore_deadline,
                                              time.process_time() +
                                              max(1.0, 0.3 * (explore_deadline -
                                                              time.process_time()))))
            print("thin frac=%.2f raw R=%.7f polished R=%.7f" %
                  (frac, rT, rp))
            candidates.append((hp, rp, "thin%.2f" % frac))

        if time.process_time() < explore_deadline:
            hp, rp = _modern_schedule(hA, min(explore_deadline,
                                              time.process_time() +
                                              max(1.0, 0.3 * (explore_deadline -
                                                              time.process_time()))))
            print("unthin polished R=%.7f" % rp)
            candidates.append((hp, rp, "unthin_pol"))

        best_c, best_rc, tag = max(candidates, key=lambda z: z[1])
        print("chosen candidate: %s R=%.7f" % (tag, best_rc))
        exp_h, expR = _modern_schedule(best_c, deadline)
        print("StageC polished: R=%.7f" % expR)
        _stats_line("StageC", exp_h, expR)

        if expR > bestR + 1e-13:
            best, bestR = exp_h.copy(), expR
            print("experiment beats start: R=%.7f" % bestR)
        else:
            print("experiment did not beat start: %.7f vs %.7f" %
                  (expR, start_bestR))
            alt_cand, altR = exp_h.copy(), expR
    except Exception as e:
        print("experiment failed: %s" % e)

    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
        print("final polish R=%.7f" % bestR)

    _stats_line("final", best, bestR)

    if bestR >= start_bestR - 1e-13:
        if alt_cand is not None and altR > -1.0:
            return {"best": best, "alternative": alt_cand}
        return best
    else:
        if alt_cand is not None and altR > -1.0:
            return {"best": start_best, "alternative": alt_cand}
        return start_best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_al(h, S, lam, rho):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idxmax = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    gLf[idxmax] += (1.0 / idxmax.size) / M
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    if S.size > 0:
        Lj = Lf[S]
        r = Lj / M - 1.0
        val += np.sum(lam * r + 0.5 * rho * r * r)
        gLf[S] += (lam + rho * r) / M
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _fun_grad_flat(h, eps, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idxmax = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    gLf[idxmax] += (1.0 / idxmax.size) / M
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    if lam > 0 and eps > 0:
        S = np.flatnonzero(Lf >= (1.0 - eps) * M)
        if S.size > 0:
            r = Lf[S] / M - 1.0
            val += lam * np.sum(r * r)
            gLf[S] += 2.0 * lam * r / M
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _al_round(h, deadline, rho, lam, maxiter=300):
    Lf = _knots(h)
    M = Lf.max()
    S = np.flatnonzero(Lf >= M * (1.0 - 1e-6))
    if lam is None or lam.size != S.size:
        lam = np.zeros(S.size)
    hc = _lbfgs_custom(h, lambda hh: _fun_grad_al(hh, S, lam, rho),
                       deadline, maxiter=maxiter)
    Lf2 = _knots(hc)
    M2 = Lf2.max()
    r = Lf2[S] / M2 - 1.0
    lam = lam + rho * r
    return hc, S, lam, r


def _newton_cg(h0, deadline, eps=0.01, lam=2.0, maxiter=60, cap=8.0):
    """Newton-CG in log parametrisation over active cells."""
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, None
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0, None
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_flat(hh, eps, lam)
        return val, g[pos] * hh[pos]

    def hessp(u, p):
        eps_fd = 1e-6
        _, g1 = f(u + eps_fd * p)
        _, g0 = f(u)
        return (g1 - g0) / eps_fd

    end = min(deadline - 0.5, time.process_time() + cap)
    cb = _make_cb(end - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='Newton-CG', hessp=hessp,
                       callback=cb,
                       options={'maxiter': maxiter, 'xtol': 1e-16,
                                'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0, None
    if res is None:
        return h0, None
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    h2 = _rescale(h2)
    return h2, float(np.linalg.norm(res.jac))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    def _report(tag, h):
        Lf = _knots(h)
        num, _, _ = _num_and_dq(h)
        _, g = _fun_grad_flat(h, 0.01, 2.0)
        print("%s R=%.12f max=%.6f num=%.6f |g|=%.3e"
              % (tag, R_of(h), Lf.max(), num, np.linalg.norm(g)))

    _report("start", best)

    # ---- Phase A: L-BFGS on flat objective (25% of budget) ----
    phaseA_end = min(deadline - 1.0, t0 + budget_seconds * 0.25)
    flat_params = [(0.05, 1.0), (0.02, 1.0), (0.01, 2.0)]
    for eps, lam in flat_params:
        if time.process_time() >= phaseA_end:
            break
        tlim = min(phaseA_end, time.process_time() + 4.0)
        hc = _lbfgs_custom(best, lambda hh: _fun_grad_flat(hh, eps, lam),
                           tlim, maxiter=150)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
        print("A eps=%.3f lam=%.1f R=%.12f (best %.12f)"
              % (eps, lam, rc, bestR))

    # ---- Phase B: Newton-CG (50% of budget) ----
    phaseB_end = min(deadline - 1.0, t0 + budget_seconds * 0.75)
    newton_iters = 0
    while time.process_time() < phaseB_end - 0.5:
        cap = min(8.0, phaseB_end - time.process_time())
        if cap < 0.5:
            break
        hc, gn = _newton_cg(best, phaseB_end, eps=0.01, lam=2.0,
                            maxiter=60, cap=cap)
        newton_iters += 1
        rc = R_of(hc)
        _report("B newton#%d" % newton_iters, hc)
        if rc > bestR:
            best = hc; bestR = rc
        else:
            # no gain: try with weaker penalty once, then break
            if newton_iters >= 2:
                break

    # ---- Phase C: final polish ----
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 2.5)
        hc = _full_lbfgs(best, tlim, maxiter=150)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
        if time.process_time() < deadline - 1.0:
            tlim = min(deadline - 0.5, time.process_time() + 1.5)
            hc = _peak_window_polish(best, tlim, pad=3)
            rc = R_of(hc)
            if rc > bestR:
                best = hc; bestR = rc
        if time.process_time() < deadline - 1.0:
            tlim = min(deadline - 0.5, time.process_time() + 1.5)
            hc = _peak_window_polish(best, tlim, pad=1)
            rc = R_of(hc)
            if rc > bestR:
                best = hc; bestR = rc
        if time.process_time() < deadline - 1.0:
            tlim = min(deadline - 0.5, time.process_time() + 2.0)
            try:
                hc, S, lam, r = _al_round(best, tlim, 1.0, None, maxiter=200)
                rc = R_of(hc)
                if rc > bestR:
                    best = hc; bestR = rc
            except Exception:
                pass
        print("C polish R=%.12f (best %.12f)" % (rc, bestR))

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    _report("final", best)
    print("final R=%.12f (start %.12f, N=%d)"
          % (bestR, startR, best.size))

    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
