    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-9)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.12f N=%d ties=%d" % (bestR, N, _tie_count(best)))

    alt_best = None
    altR = -1.0

    # ---- CVaR smoothing phase: useful when many knots near max (plateau) ----
    cvar_best = best.copy()
    cvarR = bestR
    for alpha in (0.02, 0.05, 0.1):
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 2.0, time.process_time() + 3.0)
        cand = _lbfgs_block(cvar_best, np.arange(N), 200, tlim,
                            lambda h: _fun_grad_cvar(h, alpha))
        r = R_of(cand)
        if r > cvarR + 1e-15:
            cvar_best, cvarR = cand.copy(), r
    print("cvar phase R=%.12f" % cvarR)
    if cvarR > bestR + 1e-15:
        best, bestR = cvar_best.copy(), cvarR
    if cvarR > altR and cvarR < bestR - 1e-15:
        altR, alt_best = cvarR, cvar_best.copy()

    # ---- full-array tie polish ----
    for _ in range(3):
        if time.process_time() >= deadline - 1.5:
            break
        tlim = min(deadline - 1.5, time.process_time() + 4.0)
        cand = _lbfgs_block(best, np.arange(N), 300, tlim, _fun_grad_tie)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
        else:
            break
    print("full tie R=%.12f ties=%d" % (bestR, _tie_count(best)))

    # ---- window descent over whole array ----
    W = max(64, N // 64)
    if N <= W:
        win_starts = [0]
        W = N
    else:
        win_starts = list(range(0, N - W + 1, max(1, W // 2)))
        if win_starts and win_starts[-1] + W < N:
            win_starts.append(N - W)

    rng = np.random.RandomState(999)
    accepted = 0
    outer = 0
    while time.process_time() < deadline - 2.0:
        outer += 1
        order = rng.permutation(len(win_starts))
        any_accept = False
        for oi in order:
            if time.process_time() >= deadline - 2.0:
                break
            w0 = win_starts[oi]
            free = np.arange(w0, min(N, w0 + W))
            tlim = min(deadline - 2.0, time.process_time() + 0.4)
            cand = _lbfgs_block(best, free, 40, tlim, _fun_grad_tie)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand, r
                accepted += 1
                any_accept = True
        if not any_accept:
            break
    print("window descent accepted=%d outer=%d R=%.12f" % (accepted, outer, bestR))

    # ---- final peak polish ----
    if time.process_time() < deadline - 0.5:
        Lf = _knots(best)
        pk = int(np.argmax(Lf))
        half = N // 4
        lo = max(0, pk // 2 - half)
        hi = min(N, pk // 2 + half)
        if hi - lo >= 8:
            tlim = min(deadline - 0.3, time.process_time() + 2.5)
            cand = _lbfgs_block(best, np.arange(lo, hi), 200, tlim, _fun_grad_tie)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r
            print("peak polish R=%.12f" % bestR)

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _near_max_shares(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(Lf >= mx * 0.999) * 100.0,
            np.mean(Lf >= mx * 0.99) * 100.0,
            np.mean(Lf >= mx * 0.95) * 100.0)


def _refine(h, deadline, alpha, pads):
    """One alpha round: CVaR L-BFGS, full L-BFGS, then peak-window pads."""
    best = h
    bestR = R_of(h)
    if time.process_time() >= deadline - 0.5:
        return best, bestR
    tlim = min(deadline - 0.3, time.process_time() + 2.0)
    hc = _lbfgs_custom(best, lambda hh: _fun_grad_cvar(hh, alpha), tlim, maxiter=150)
    rc = R_of(hc)
    if rc > bestR:
        best = hc; bestR = rc
    if time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.3, time.process_time() + 2.0)
        hc = _full_lbfgs(best, tlim, maxiter=100)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
    for frac in pads:
        if time.process_time() >= deadline - 0.5:
            break
        tlim = min(deadline - 0.3, time.process_time() + 1.0)
        hc = _peak_window_polish(best, tlim, pad=max(1, int(frac * best.size)))
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
    return best, bestR


def _interp_to(h, Nnew):
    """Resample step heights onto Nnew cells by cumulative mass interpolation."""
    N = h.size
    if N == Nnew:
        return h.copy()
    x_old = (np.arange(N) + 0.5) / N
    x_new = (np.arange(Nnew) + 0.5) / Nnew
    hn = np.interp(x_new, x_old, h)
    return _rescale(hn)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase A: alpha ladder at current resolution ----
    phaseA_end = t0 + budget_seconds * 0.40
    alphasA = [0.10, 0.05, 0.03, 0.02]
    padsA = [0.20, 0.10, 0.05]
    for a in alphasA:
        if time.process_time() >= phaseA_end - 0.5:
            break
        hc, rc = _refine(best, min(phaseA_end, deadline - 0.5), a, padsA)
        if rc > bestR:
            best = hc; bestR = rc
        s01, s1, s5 = _near_max_shares(best)
        mm = best.max() / max(best.mean(), 1e-300)
        print("A alpha=%.3f N=%d R=%.9f shares=%.2f/%.2f/%.2f max/mean=%.2f"
              % (a, best.size, bestR, s01, s1, s5, mm))

    # ---- Phase B: upsample to 2x finer grid, alpha ladder ----
    phaseB_end = t0 + budget_seconds * 0.70
    Nnew = min(1000000, best.size * 2)
    if Nnew > best.size and time.process_time() < phaseB_end - 1.0:
        hb = _interp_to(best, Nnew)
        rb = R_of(hb)
        if rb > bestR:
            best = hb; bestR = rb
        print("B upsample N=%d R=%.9f" % (best.size, bestR))
        alphasB = [0.05, 0.03, 0.02, 0.01]
        padsB = [0.10, 0.05, 0.02]
        for a in alphasB:
            if time.process_time() >= phaseB_end - 0.5:
                break
            hc, rc = _refine(best, min(phaseB_end, deadline - 0.5), a, padsB)
            if rc > bestR:
                best = hc; bestR = rc
            s01, s1, s5 = _near_max_shares(best)
            mm = best.max() / max(best.mean(), 1e-300)
            print("B alpha=%.3f N=%d R=%.9f shares=%.2f/%.2f/%.2f max/mean=%.2f"
                  % (a, best.size, bestR, s01, s1, s5, mm))

    # ---- Phase C: alternate full L-BFGS and CVaR + pad ladder ----
    padsC = [0.15, 0.06, 0.02, 0.008]
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.3, time.process_time() + 2.0)
        hc = _full_lbfgs(best, tlim, maxiter=300)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
        if time.process_time() >= deadline - 1.0:
            break
        hc, rc = _refine(best, min(deadline - 0.5, time.process_time() + 3.0),
                         0.02, padsC)
        if rc > bestR:
            best = hc; bestR = rc
        s01, s1, s5 = _near_max_shares(best)
        mm = best.max() / max(best.mean(), 1e-300)
        print("C N=%d R=%.9f shares=%.2f/%.2f/%.2f max/mean=%.2f"
              % (best.size, bestR, s01, s1, s5, mm))

    if bestR < startR:
        print("final R=%.12f (start %.12f, N=%d) no gain" % (bestR, startR, best.size))
        return {"best": h0, "alternative": best}

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (np.mean(L >= 0.999 * mx), np.mean(L >= 0.99 * mx), np.mean(L >= 0.95 * mx))


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    thr = mx * (1.0 - alpha)
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    w = 1.0 / idx.size
    gLf[idx] += w / np.maximum(Lf[idx], 1e-12)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(np.mean(Lf[idx]))
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        return _rescale(np.clip(res.x, 0.0, None))
    except Exception:
        return h0


def _full_lbfgs(h0, maxiter, deadline):
    return _lbfgs_custom(h0, _fun_grad_tie, maxiter, deadline)


def _peak_window_polish(h, deadline, pad=8, win_frac=0.25, maxiter=300):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return h
    lo = idx.min(); hi = idx.max()
    span = hi - lo + 1
    half = max(span, int(win_frac * h.size))
    lo = max(0, lo - half - pad)
    hi = min(h.size - 1, hi + half + pad)
    active = np.arange(lo, hi + 1)
    hh = h.copy()
    x0 = hh[active].copy()

    def f(x):
        tmp = hh.copy()
        tmp[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(tmp)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = hh.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)
    except Exception:
        return h


def _prolong(h, L):
    """Mass-conserving refinement: split each cell into L cells via
    cumulative-mass interpolation at offsets k/L."""
    N = len(h)
    if L == 1:
        return h.copy()
    N2 = N * L
    c = np.concatenate([[0.0], np.cumsum(h)])
    # knot positions in units of original cells
    xs = np.arange(N2 + 1) / L
    cm = np.interp(xs, np.arange(N + 1), c)
    new = np.diff(cm) * L
    if new.sum() <= 0:
        return np.ones(N2)
    return _rescale(np.clip(new, 0, None))


def _shift_refine(h, deadline):
    """Evaluate half/quarter-cell fractional shifts via cumulative-mass
    interpolation; keep the best after a short polish."""
    N = len(h)
    c = np.concatenate([[0.0], np.cumsum(h)])
    best = h
    bestR = R_of(h)
    for frac in (0.5, 0.25, 0.75):
        if time.process_time() > deadline - 1.5:
            break
        xs = np.arange(N + 1) + frac
        xs[0] = 0.0
        xs[-1] = N
        cm = np.interp(xs, np.arange(N + 1), c)
        new = np.diff(cm)
        if new.sum() <= 0:
            continue
        new = _rescale(np.clip(new, 0, None))
        r = R_of(new)
        if r > bestR:
            bestR = r
            best = new
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    best = np.ones(50)
    best_R = R_of(best)
    if start is not None:
        try:
            s = np.asarray(start, dtype=float)
            r = R_of(s)
            if r > best_R:
                best = s.copy(); best_R = r
        except Exception:
            pass

    def consider(h):
        nonlocal best, best_R
        if h is None:
            return False
        h = np.asarray(h, dtype=float)
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return False
        r = R_of(h)
        if r > best_R + 1e-10:
            best_R = r
            best = h.copy()
            return True
        return False

    # Phase A: report base
    sh = _shares(best)
    print(f"base N={best.size} R={best_R:.6f} shares={sh[0]:.3f}/{sh[1]:.3f}/{sh[2]:.3f}")

    # Phase B: resolution ladder L = 1, 2, 4
    phase_b_end = t0 + budget_seconds * 0.50
    finest_improved = best.copy()
    finest_R = best_R
    for L in (1, 2, 4):
        if time.process_time() > phase_b_end - 2:
            break
        if best.size * L > 400000:
            continue
        hi = _prolong(best, L) if L > 1 else best.copy()
        level_deadline = min(phase_b_end, time.process_time() + max(3.0, (phase_b_end - time.process_time()) / 2.0))
        hi = _full_lbfgs(hi, 150, level_deadline)
        hi = _peak_window_polish(hi, level_deadline, pad=max(4, int(0.04 * hi.size)),
                                 win_frac=0.04, maxiter=200)
        hi = _peak_window_polish(hi, level_deadline, pad=max(2, int(0.012 * hi.size)),
                                 win_frac=0.012, maxiter=200)
        r = R_of(hi)
        sh = _shares(hi)
        print(f"L={L} N={hi.size} R={r:.6f} shares={sh[0]:.3f}/{sh[1]:.3f}/{sh[2]:.3f}")
        if r > finest_R + 1e-9:
            finest_R = r
            finest_improved = hi.copy()
        consider(hi)

    # Phase C: cycle on finest level
    cur = finest_improved.copy()
    while time.process_time() < deadline - 1.5:
        # (a) full lbfgs
        nxt = _full_lbfgs(cur, 200, min(deadline - 1.0, time.process_time() + 6))
        if R_of(nxt) > R_of(cur):
            cur = nxt
        consider(cur)
        if time.process_time() > deadline - 1.5:
            break
        # (b) CVaR alpha ladder
        for alpha in (0.10, 0.05, 0.02):
            if time.process_time() > deadline - 1.5:
                break
            nxt = _lbfgs_custom(cur, lambda h, a=alpha: _fun_grad_cvar(h, a),
                                150, min(deadline - 1.0, time.process_time() + 4))
            if R_of(nxt) > R_of(cur):
                cur = nxt
            consider(cur)
        if time.process_time() > deadline - 1.5:
            break
        # (c) peak-window polish with shrinking pads
        for pad_frac in (0.05, 0.02, 0.008):
            if time.process_time() > deadline - 1.5:
                break
            nxt = _peak_window_polish(cur, min(deadline - 1.0, time.process_time() + 4),
                                      pad=max(2, int(pad_frac * cur.size)),
                                      win_frac=max(0.02, pad_frac), maxiter=200)
            if R_of(nxt) > R_of(cur):
                cur = nxt
            consider(cur)
        if time.process_time() > deadline - 1.5:
            break
        # (d) sub-cell shift refinement
        nxt = _shift_refine(cur, deadline)
        if R_of(nxt) > R_of(cur):
            cur = nxt
        consider(cur)

    # Final polish
    if time.process_time() < deadline - 0.5:
        try:
            nxt = _full_lbfgs(best.copy(), 200, deadline - 0.3)
            consider(nxt)
        except Exception:
            pass

    if best is None:
        best = np.ones(50)
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _swap_perturb(h, deadline, n_trials=6):
    """Try to improve by moving mass across a block (block-swap moves)."""
    best = h
    bestR = R_of(h)
    n = h.size
    rng = np.random.default_rng(12345)
    for _ in range(n_trials):
        if time.process_time() >= deadline - 1.0:
            break
        # pick a random contiguous block, shift its mass to a nearby block
        w = int(n * 0.02) + 4
        a = int(rng.integers(0, n - w))
        b = int(rng.integers(0, n - w))
        if a == b:
            continue
        hh = h.copy()
        mass = hh[a:a + w].copy()
        # blend: subtract half from a, add half to b (scaled by widths)
        hh[a:a + w] *= 0.5
        hh[b:b + w] += 0.5 * mass
        hh = _rescale(hh)
        r = R_of(hh)
        if r > bestR:
            # local polish of the moved block
            lo = max(0, min(a, b) - w)
            hi = min(n, max(a, b) + 2 * w)
            hh = _lbfgs_block(hh, np.arange(lo, hi), 120, deadline)
            r = R_of(hh)
            if r > bestR:
                best, bestR = hh, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    alternative = None

    # NEW IDEA: block-swap perturb-and-polish. Instead of only local
    # gradient descent (which stalls on the flat-top plateau), periodically
    # try moving a chunk of mass to another location, then locally polish.
    # Accept if R improves. This effectively explores the non-convex shape
    # space in a way plain L-BFGS cannot.

    # Stage 1: softmax homotopy to break plateau (as before, short).
    for beta in (16.0, 64.0):
        if time.process_time() >= deadline - 8.0:
            break
        h = _lbfgs_log(best, 200, deadline, beta=beta)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("soft beta=%.0f R=%.7f" % (beta, bestR))
        h = _lbfgs_log(best, 200, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("exact R=%.7f" % bestR)

    # Stage 2: block-swap exploration with local polish.
    alt_candidate = best.copy()
    altR = bestR
    while time.process_time() < deadline - 6.0:
        startR = bestR
        h, r = _swap_perturb(best, deadline, n_trials=4)
        if r > bestR + 1e-12:
            best, bestR = h, r
            print("swap R=%.7f" % bestR)
        # full polish after each swap round
        h = _lbfgs_log(best, 150, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("swap+full R=%.7f" % bestR)
        if bestR - startR < 1e-9:
            # converged; try a bigger kick once
            h, r = _swap_perturb(best, deadline, n_trials=8)
            if r > bestR + 1e-12:
                best, bestR = h, r
                print("bigswap R=%.7f" % bestR)
            else:
                break
    if bestR > altR + 1e-12:
        alt_candidate = best.copy()
        altR = bestR

    # Stage 3: final peak-focused polish + exact full polish.
    while time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("full R=%.7f" % bestR)
        else:
            break
    if bestR > altR + 1e-12:
        alt_candidate = best.copy()

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if R_of(alt_candidate) < bestR - 1e-12:
        return {"best": best, "alternative": alt_candidate}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (np.mean(L >= 0.999 * mx), np.mean(L >= 0.99 * mx), np.mean(L >= 0.95 * mx))


def _maxmean(h):
    m = h.mean()
    if m <= 0:
        return 0.0
    return h.max() / m


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    thr = mx * (1.0 - alpha)
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    w = 1.0 / idx.size
    gLf[idx] += w / np.maximum(Lf[idx], 1e-12)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(np.mean(Lf[idx]))
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    x0 = h.copy()

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        return _rescale(np.clip(res.x, 0.0, None))
    except Exception:
        return h0


def _full_lbfgs(h0, maxiter, deadline):
    return _lbfgs_custom(h0, _fun_grad_tie, maxiter, deadline)


def _peak_window_polish(h, deadline, pad=8, win_frac=0.25, maxiter=300):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return h
    lo = idx.min(); hi = idx.max()
    span = hi - lo + 1
    half = max(span, int(win_frac * h.size))
    lo = max(0, lo - half - pad)
    hi = min(h.size - 1, hi + half + pad)
    active = np.arange(lo, hi + 1)
    hh = h.copy()
    x0 = hh[active].copy()

    def f(x):
        tmp = hh.copy()
        tmp[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(tmp)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = hh.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)
    except Exception:
        return h


def _prolong(h, L):
    N = len(h)
    if L == 1:
        return h.copy()
    N2 = N * L
    c = np.concatenate([[0.0], np.cumsum(h)])
    xs = np.arange(N2 + 1) / L
    cm = np.interp(xs, np.arange(N + 1), c)
    new = np.diff(cm) * L
    if new.sum() <= 0:
        return np.ones(N2)
    return _rescale(np.clip(new, 0, None))


def _shift_refine(h, deadline):
    N = len(h)
    c = np.concatenate([[0.0], np.cumsum(h)])
    best = h
    bestR = R_of(h)
    for frac in (0.5, 0.25, 0.75):
        if time.process_time() > deadline - 1.5:
            break
        xs = np.arange(N + 1) + frac
        xs[0] = 0.0
        xs[-1] = N
        cm = np.interp(xs, np.arange(N + 1), c)
        new = np.diff(cm)
        if new.sum() <= 0:
            continue
        new = _rescale(np.clip(new, 0, None))
        r = R_of(new)
        if r > bestR:
            bestR = r
            best = new
    return best


def _sparsify(h, q):
    """Set the smallest q fraction of currently positive cells to zero."""
    h = np.asarray(h, dtype=float).copy()
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h
    k = int(round(q * pos.size))
    if k <= 0:
        return h
    k = min(k, pos.size - 1)
    if k <= 0:
        return h
    vals = h[pos]
    order = np.argsort(vals)
    kill = pos[order[:k]]
    h[kill] = 0.0
    return _rescale(h)


def _sharpen(h, p):
    if p == 1.0:
        return _rescale(np.clip(h, 0, None))
    return _rescale(np.clip(h, 0, None) ** p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    best = np.ones(50)
    best_R = R_of(best)
    if start is not None:
        try:
            s = np.asarray(start, dtype=float)
            r = R_of(s)
            if r > best_R:
                best = s.copy(); best_R = r
        except Exception:
            pass

    def consider(h):
        nonlocal best, best_R
        if h is None:
            return False
        h = np.asarray(h, dtype=float)
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return False
        r = R_of(h)
        if r > best_R + 1e-10:
            best_R = r
            best = h.copy()
            return True
        return False

    sh = _shares(best)
    print(f"base N={best.size} R={best_R:.6f} shares={sh[0]:.3f}/{sh[1]:.3f}/{sh[2]:.3f}")

    # Ensure we have a good working resolution to sparsify/sharpen on.
    # If start is coarse, refine it once (keeps shape, adds resolution).
    cur = best.copy()
    if cur.size < 40000 and time.process_time() < t0 + budget_seconds * 0.15:
        L = 2
        while cur.size * L < 100000 and L < 8:
            L *= 2
        hi = _prolong(cur, L)
        hi = _full_lbfgs(hi, 120, min(deadline - 1.0, time.process_time() + 6))
        if R_of(hi) > R_of(cur) - 1e-9:
            cur = hi
            consider(cur)

    # Phase B: resolution ladder (keep base's good behavior)
    phase_b_end = t0 + budget_seconds * 0.30
    for L in (1, 2):
        if time.process_time() > phase_b_end - 2:
            break
        if cur.size * L > 400000:
            continue
        hi = _prolong(cur, L) if L > 1 else cur.copy()
        ld = min(phase_b_end, time.process_time() + max(3.0, (phase_b_end - time.process_time()) / 2.0))
        hi = _full_lbfgs(hi, 150, ld)
        hi = _peak_window_polish(hi, ld, pad=max(4, int(0.04 * hi.size)),
                                 win_frac=0.04, maxiter=200)
        r = R_of(hi)
        if r > R_of(cur) + 1e-9:
            cur = hi
        consider(hi)
        sh = _shares(hi)
        print(f"L={L} N={hi.size} R={r:.6f} shares={sh[0]:.3f}/{sh[1]:.3f}/{sh[2]:.3f}")

    # Phase C: sparsification + sharpening homotopy
    q_schedule = (0.05, 0.10, 0.15, 0.20, 0.25, 0.30, 0.35)
    p_cycle = (1.0, 1.5, 2.0, 3.0)
    stop_sparsify = False
    qi = 0
    pi = 0
    while time.process_time() < deadline - 2.0:
        if not stop_sparsify:
            q = q_schedule[qi % len(q_schedule)]
            p = p_cycle[pi % len(p_cycle)]
            qi += 1
            pi += 1
            cand = _sparsify(cur, q)
            cand = _sharpen(cand, p)
        else:
            q = 0.0; p = 1.0
            cand = cur.copy()

        # Polish: full lbfgs
        ld = min(deadline - 1.0, time.process_time() + 5)
        cand = _full_lbfgs(cand, 200, ld)
        if time.process_time() > deadline - 1.5:
            consider(cand)
            break
        # CVaR ladder
        for alpha in (0.10, 0.05, 0.02):
            if time.process_time() > deadline - 1.5:
                break
            cand = _lbfgs_custom(cand, lambda h, a=alpha: _fun_grad_cvar(h, a),
                                 100, min(deadline - 1.0, time.process_time() + 3))
        if time.process_time() > deadline - 1.5:
            consider(cand)
            break
        # Peak-window polish
        for pad_frac in (0.10, 0.04, 0.015):
            if time.process_time() > deadline - 1.5:
                break
            cand = _peak_window_polish(cand, min(deadline - 1.0, time.process_time() + 3),
                                       pad=max(2, int(pad_frac * cand.size)),
                                       win_frac=max(0.02, pad_frac), maxiter=200)

        r = R_of(cand)
        mm = _maxmean(cand)
        sh = _shares(cand)
        improved = r > R_of(cur) + 1e-9
        if improved:
            cur = cand
        consider(cand)
        print(f"q={q:.2f} p={p:.2f} N={cand.size} R={r:.6f} mm={mm:.2f} "
              f"shares={sh[0]:.3f}/{sh[1]:.3f}/{sh[2]:.3f} imp={int(improved)}")

        if mm > 90:
            stop_sparsify = True

        if time.process_time() > deadline - 2.0:
            break

    # Phase D: final full-array and wide peak-window polish on best
    while time.process_time() < deadline - 0.8:
        nxt = _full_lbfgs(best.copy(), 200, min(deadline - 0.5, time.process_time() + 4))
        consider(nxt)
        if time.process_time() > deadline - 0.8:
            break
        nxt = _peak_window_polish(best.copy(), min(deadline - 0.5, time.process_time() + 3),
                                  pad=max(4, int(0.05 * best.size)),
                                  win_frac=0.10, maxiter=200)
        consider(nxt)
        if time.process_time() > deadline - 0.8:
            break
        nxt = _shift_refine(best.copy(), deadline)
        consider(nxt)

    if best is None:
        best = np.ones(50)
    sh = _shares(best)
    print(f"final N={best.size} R={best_R:.6f} mm={_maxmean(best):.2f} "
          f"shares={sh[0]:.3f}/{sh[1]:.3f}/{sh[2]:.3f}")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1200:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1200:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolong(h, n_new):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == n_new:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    if c[-1] <= 0:
        return np.ones(n_new)
    c = c / c[-1]
    x_new = np.linspace(0, 1, n_new + 1)
    c_new = np.interp(x_new, np.linspace(0, 1, n + 1), c)
    h_new = np.diff(c_new)
    h_new = np.maximum(h_new, 0)
    if h_new.sum() <= 0:
        h_new = np.ones(n_new)
    return h_new


def _seed_cosine(n):
    x = np.linspace(0, 1, n)
    return np.cos(np.pi * (x - 0.5)) ** 2 + 1e-3


def _seed_asym(n):
    x = np.linspace(0, 1, n)
    return np.exp(-((x - 0.35) / 0.2) ** 2) + 1e-3


def _seed_triangular(n):
    x = np.linspace(0, 1, n)
    return np.minimum(x, 1 - x) + 1e-3


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    bestR = -1.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if s.size > 0 and s.sum() > 0:
            best = _rescale(s)
            bestR = R_of(best)

    start_arr = None
    if start is not None:
        ss = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if ss.size > 0 and ss.sum() > 0:
            start_arr = ss

    # Phase A: only if no start, seed from scratch
    ladder_best = None
    ladder_R = -1.0
    if start_arr is None:
        N0 = 256
        seeds = [("cosine", _seed_cosine(N0)),
                 ("asym", _seed_asym(N0)),
                 ("triangular", _seed_triangular(N0))]
        survivors = []
        for name, s in seeds:
            if time.process_time() > deadline - 20.0:
                break
            try:
                h = _lbfgs_log(s, 300, deadline - 20.0, beta=0.0)
                h = _lbfgs_log(h, 300, deadline - 20.0, beta=8.0)
                r = R_of(h)
                survivors.append((r, name, h))
            except Exception:
                pass
        survivors.sort(key=lambda t: -t[0])
        if survivors:
            cur = survivors[0][2]
            for n_new in [512, 1024, 2048, 4096, 8192, 16384, 32768]:
                if time.process_time() > deadline - 10.0:
                    break
                cur = _prolong(cur, n_new)
                cur = _lbfgs_log(cur, 250, deadline - 10.0, beta=0.0)
                cur = _lbfgs_log(cur, 150, deadline - 10.0, beta=10.0)
            r = R_of(cur)
            print(f"ladder: R={r:.6f} N={len(cur)}")
            if r > ladder_R:
                ladder_R = r
                ladder_best = cur
            if ladder_best is not None and ladder_R > bestR:
                best = ladder_best
                bestR = ladder_R

    # Phase B: main work — refine from `start` (or best) up a ladder of resolutions
    if best is not None:
        cur = best.copy()
        # Determine ladder: start from current N, double, then continue
        n0 = len(cur)
        ladder = []
        n = n0
        while n < 200000:
            ladder.append(n)
            n *= 2
        # ensure we at least reach a decent resolution
        if len(ladder) < 4:
            n = n0
            while len(ladder) < 4:
                ladder.append(n)
                n *= 2

        # First pass: jump up the ladder quickly with modest iterations
        for n_new in ladder:
            if time.process_time() > deadline - 6.0:
                break
            cur = _prolong(cur, n_new)
            cur = _lbfgs_log(cur, 200, deadline - 6.0, beta=0.0)
            cur = _lbfgs_log(cur, 100, deadline - 6.0, beta=12.0)
            r = R_of(cur)
            if r > bestR:
                best, bestR = cur.copy(), r
                print(f"ladder: R={r:.6f} N={len(cur)}")

        # Second pass: keep pushing to highest resolution and polish
        while time.process_time() < deadline - 3.0:
            n_cur = len(best)
            if n_cur >= 200000:
                # polish at current resolution
                cur = _lbfgs_log(best, 400, deadline - 2.0, beta=0.0)
                r = R_of(cur)
                if r > bestR + 1e-10:
                    best, bestR = cur, r
                    print(f"polish: R={r:.6f} N={len(cur)}")
                else:
                    # try beta
                    cur = _lbfgs_log(best, 400, deadline - 2.0, beta=15.0)
                    r = R_of(cur)
                    if r > bestR + 1e-10:
                        best, bestR = cur, r
                        print(f"polish-beta: R={r:.6f}")
                    else:
                        break
            else:
                n_new = min(2 * n_cur, 200000)
                cur = _prolong(best, n_new)
                cur = _lbfgs_log(cur, 250, deadline - 3.0, beta=0.0)
                r = R_of(cur)
                if r > bestR - 1e-6:
                    best, bestR = cur, max(bestR, r)
                    print(f"refine: R={r:.6f} N={len(cur)}")
                else:
                    # failed to improve at this resolution; try beta
                    cur = _lbfgs_log(_prolong(best, n_new), 250, deadline - 3.0, beta=12.0)
                    r = R_of(cur)
                    if r > bestR:
                        best, bestR = cur, r
                        print(f"refine-beta: R={r:.6f} N={len(cur)}")
                    else:
                        break

    if best is None:
        best = np.ones(50)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)

    alt = None
    if ladder_best is not None and abs(ladder_R - bestR) > 1e-9 and ladder_best.shape != best.shape:
        alt = ladder_best
    elif ladder_best is not None and abs(ladder_R - bestR) > 1e-9 and not np.array_equal(ladder_best, best):
        alt = ladder_best

    print(f"final R={R_of(best):.6f} N={len(best)}")
    if alt is not None:
        return {"best": best, "alternative": alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _R_from_h(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    mx = Lp.max()
    if mx <= 0:
        return -1.0
    q = Lp * Lp
    cross = np.dot(Lp[:-1], Lp[1:])
    num = (2.0 * q.sum() + cross) / 3.0
    den = (s * s) * mx
    return num / den


def _rasterize(params, K, N):
    a = np.exp(params[0:K])
    c = params[K:2 * K]
    w = np.exp(params[2 * K:3 * K])
    x = (np.arange(N) + 0.5) / N
    h = np.zeros(N)
    for k in range(K):
        h += a[k] * np.exp(-((x - c[k]) / w[k]) ** 2)
    return h


def _nelder_mead_polish(params, K, N, budget_evals, deadline):
    best = params.copy()
    best_r = _R_from_h(_rasterize(best, K, N))

    def obj(p):
        if time.process_time() > deadline:
            return 1e9
        r = _R_from_h(_rasterize(p, K, N))
        return -r

    try:
        res = minimize(obj, best, method='Nelder-Mead',
                       options={'maxfev': budget_evals, 'xatol': 1e-6, 'fatol': 1e-8})
        if -res.fun > best_r:
            return res.x, -res.fun
    except Exception:
        pass
    return best, best_r


def _negR_grad_full(h, mask=None):
    """Return -R and -dR/dv for h where v=log(h). If mask given, only those indices."""
    N = h.size
    s = h.sum()
    if s <= 0:
        return 1e9, np.zeros(N)
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    mx = Lp.max()
    if mx <= 0:
        return 1e9, np.zeros(N)
    q = Lp * Lp
    cross = np.dot(Lp[:-1], Lp[1:])
    num = (2.0 * q.sum() + cross) / 3.0
    den = (s * s) * mx
    R = num / den
    A = np.correlate(Lp[1:], h, 'valid')
    B = np.correlate(Lp[2:], h, 'valid')
    T = A[:N] + B[:N]
    if Lp.size >= 3 + N:
        C = np.correlate(Lp[3:], h, 'valid')
    else:
        C = np.zeros(N)
    U = B[:N] + C[:N]
    dnum = T + U / 3.0
    jmax = int(np.argmax(Lp))
    dmx = np.zeros(N)
    for off in (1, 2):
        # dLp[jmax]/dh_i = h[jmax-off-i]
        i_lo = max(0, jmax - off - (N - 1))
        i_hi = min(N, jmax - off + 1)
        for i in range(i_lo, i_hi):
            j = jmax - off - i
            if 0 <= j < N:
                dmx[i] += h[j]
    dden = 2.0 * s * mx + s * s * dmx
    dR_dh = (dnum * den - num * dden) / (den * den)
    dR_dv = dR_dh * h
    if mask is not None:
        return -R, -dR_dv[mask]
    return -R, -dR_dv


def _polish_log(h0, deadline, maxiter=200, active_mask=None):
    h0 = np.asarray(h0, dtype=float)
    N = h0.size
    if N == 0:
        return h0, -1.0
    eps = 1e-12
    if active_mask is None:
        active_mask = np.ones(N, dtype=bool)
    active_mask = np.asarray(active_mask, dtype=bool)
    if not np.any(active_mask):
        return h0, _R_from_h(h0)
    v0 = np.log(np.maximum(h0[active_mask], eps))

    def obj(v):
        if time.process_time() > deadline:
            return 1e9, np.zeros_like(v)
        h = h0.copy()
        h[active_mask] = np.exp(v)
        return _negR_grad_full(h, active_mask)

    try:
        res = minimize(obj, v0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-15, 'gtol': 1e-13})
        h = h0.copy()
        h[active_mask] = np.exp(res.x)
    except Exception:
        h = h0
    r = _R_from_h(h)
    if r > _R_from_h(h0):
        return h, r
    return h0, _R_from_h(h0)


def _peak_window_polish(h, deadline, pad_fracs=(0.10, 0.05, 0.02)):
    h = np.asarray(h, dtype=float).copy()
    N = h.size
    best_r = _R_from_h(h)
    best_h = h.copy()
    for pad in pad_fracs:
        if time.process_time() > deadline:
            break
        L = np.convolve(h, h)
        Lp = np.concatenate(([0.0], L, [0.0]))
        mx = Lp.max()
        thresh = mx * (1.0 - pad)
        idx = np.where(Lp >= thresh)[0]
        if idx.size == 0:
            continue
        lo = max(0, int(idx.min()) - 2)
        hi = min(N, int(idx.max()) + 2)
        if hi - lo < 2:
            continue
        mask = np.zeros(N, dtype=bool)
        mask[lo:hi] = True
        hh, r = _polish_log(h, deadline, maxiter=60, active_mask=mask)
        if r > best_r:
            best_r = r
            best_h = hh.copy()
            h = hh.copy()
    return best_h, best_r


def _lift(h, N_new):
    N = h.size
    if N_new <= N:
        return h.copy()
    x_old = (np.arange(N) + 0.5) / N
    x_new = (np.arange(N_new) + 0.5) / N_new
    h_new = np.interp(x_new, x_old, h, left=0.0, right=0.0)
    return np.maximum(h_new, 0.0)


def _sharpen_prune(h, p, q, floor_frac=1e-10):
    h = np.asarray(h, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h
    h = h / s
    hp = h ** p
    if q > 0:
        pos = hp[hp > 0]
        if pos.size > 0:
            k = int(q * pos.size)
            if k > 0 and k < pos.size:
                thr = np.partition(pos, k - 1)[k - 1]
                hp = np.where(hp <= thr, 0.0, hp)
    mx = hp.max()
    if mx <= 0:
        return h
    hp = np.maximum(hp, floor_frac * mx)
    return hp


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(12345)

    best_h = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0):
            best_h = s.copy()
            best_r = _R_from_h(best_h)

    # Phase 1: Gaussian-mixture seeding at N=4096
    N1 = 4096
    n_samples = 200
    candidates = []
    for _ in range(n_samples):
        if time.process_time() > deadline:
            break
        K = int(rng.integers(8, 49))
        a = np.exp(rng.uniform(-1.0, 1.0, K))
        c = np.sort(rng.uniform(0.0, 1.0, K))
        w = np.exp(rng.uniform(np.log(0.01), np.log(0.3), K))
        params = np.concatenate([np.log(a), c, np.log(w)])
        h = _rasterize(params, K, N1)
        r = _R_from_h(h)
        candidates.append((r, params, K))
    candidates.sort(key=lambda t: -t[0])
    top = candidates[:5]

    # Phase 2: Nelder-Mead on top 5
    for r0, params, K in top:
        if time.process_time() > deadline:
            break
        p, r = _nelder_mead_polish(params, K, N1, 300, deadline)
        h = _rasterize(p, K, N1)
        if r > best_r:
            best_r = r
            best_h = h.copy()

    # Phase 3: L-BFGS log-param polish on best
    if best_h is not None and time.process_time() < deadline:
        h, r = _polish_log(best_h, deadline, maxiter=150)
        if r > best_r:
            best_r = r
            best_h = h.copy()

    # Phase 4: peak-window polish
    if best_h is not None and time.process_time() < deadline:
        h, r = _peak_window_polish(best_h, deadline)
        if r > best_r:
            best_r = r
            best_h = h.copy()

    # Phase 5: lifts to 16384 and 32768
    if best_h is not None:
        for N_new in (16384, 32768):
            if time.process_time() > deadline:
                break
            h = _lift(best_h, N_new)
            h, r = _polish_log(h, deadline, maxiter=80)
            if r > best_r:
                best_r = r
                best_h = h.copy()
            if time.process_time() < deadline:
                h2, r2 = _peak_window_polish(best_h, deadline)
                if r2 > best_r:
                    best_r = r2
                    best_h = h2.copy()

    # Phase 6: sharpening/pruning homotopy at N=32768
    if best_h is not None and best_h.size < 32768:
        h = _lift(best_h, 32768)
        h, r = _polish_log(h, deadline, maxiter=60)
        if r > best_r:
            best_r = r
            best_h = h.copy()

    if best_h is not None and time.process_time() < deadline:
        N_h = best_h.size
        base_h = best_h.copy()
        base_r = best_r
        for p in (1.5, 2.0, 3.0, 4.0):
            if time.process_time() > deadline:
                break
            for q in (0.0, 0.10, 0.20, 0.30, 0.40):
                if time.process_time() > deadline:
                    break
                h = _sharpen_prune(base_h, p, q)
                h, r = _polish_log(h, deadline, maxiter=120)
                if r > best_r:
                    best_r = r
                    best_h = h.copy()
                if time.process_time() < deadline:
                    h2, r2 = _peak_window_polish(best_h, deadline)
                    if r2 > best_r:
                        best_r = r2
                        best_h = h2.copy()

    # Phase 7: fresh random Gaussian mixtures at N=4096, lift top 2 to 32768
    if time.process_time() < deadline:
        fresh = []
        for _ in range(8):
            if time.process_time() > deadline:
                break
            K = int(rng.choice([8, 16, 32, 48]))
            a = np.exp(rng.uniform(-1.0, 1.0, K))
            c = np.sort(rng.uniform(0.0, 1.0, K))
            w = np.exp(rng.uniform(np.log(0.01), np.log(0.3), K))
            params = np.concatenate([np.log(a), c, np.log(w)])
            h = _rasterize(params, K, N1)
            r = _R_from_h(h)
            fresh.append((r, h))
        fresh.sort(key=lambda t: -t[0])
        for r0, h0 in fresh[:2]:
            if time.process_time() > deadline:
                break
            h = _lift(h0, 32768)
            h, r = _polish_log(h, deadline, maxiter=80)
            if r > best_r:
                best_r = r
                best_h = h.copy()
            if time.process_time() < deadline:
                h2, r2 = _peak_window_polish(best_h, deadline)
                if r2 > best_r:
                    best_r = r2
                    best_h = h2.copy()

    # Phase 8: cycle sharpening/pruning at current best until deadline
    if best_h is not None:
        cycle = 0
        while time.process_time() < deadline:
            cycle += 1
            p = [1.5, 2.0, 2.5, 3.0, 4.0, 5.0][cycle % 6]
            q = [0.0, 0.10, 0.20, 0.30, 0.40, 0.50][cycle % 6]
            h = _sharpen_prune(best_h, p, q)
            h, r = _polish_log(h, deadline, maxiter=100)
            if r > best_r:
                best_r = r
                best_h = h.copy()
            if time.process_time() < deadline:
                h2, r2 = _peak_window_polish(best_h, deadline)
                if r2 > best_r:
                    best_r = r2
                    best_h = h2.copy()
            if cycle > 40:
                break

    if best_h is None:
        best_h = np.ones(50)
        best_r = _R_from_h(best_h)

    try:
        h = best_h
        s = h.sum()
        if s > 0:
            L = np.convolve(h, h)
            Lp = np.concatenate(([0.0], L, [0.0]))
            mx = Lp.max()
            zero_frac = float(np.mean(h == 0))
            mm = float(h.max() / h.mean()) if h.mean() > 0 else 0.0
            near = float(np.mean(Lp >= 0.95 * mx))
            print(f"R={best_r:.6f} N={h.size} max/mean={mm:.2f} zero={zero_frac:.3f} near-max={near:.4f}")
    except Exception:
        pass

    start_r = _R_from_h(start) if start is not None else -1.0
    if best_r >= start_r:
        return best_h
    else:
        return {"best": np.asarray(start, dtype=float) if start is not None else best_h,
                "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _frac_near_max(h, tol=1e-3):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _lbfgs_block(h0, free, maxiter, deadline, fun_grad):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    # ---------- baseline ----------
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d) near=%.4f"
          % (bestR, best.size, _frac_near_max(best, 1e-3)))

    # Track the best "alternative" we build that is genuinely different.
    alt_best = None
    altR = -1.0

    def consider(hcand, tag):
        nonlocal best, bestR, alt_best, altR
        hcand = _rescale(np.clip(hcand, 0, None))
        r = R_of(hcand)
        print("  %s R=%.12f near=%.4f/%.4f/%.4f"
              % (tag, r, _frac_near_max(hcand, 1e-3),
                 _frac_near_max(hcand, 1e-2), _frac_near_max(hcand, 5e-2)))
        if r > altR:
            altR, alt_best = r, hcand.copy()
        if r > bestR + 1e-15:
            best, bestR = hcand.copy(), r

    # ---------- Stage 1: CVaR-style plateau-shaping (new idea) ----------
    # Instead of sharpening a single max, gradually push a whole band of
    # knots up to the maximum. This flattens the top of f*f, which is
    # exactly what maximizes R = ||.||_2^2 / (||.||_1 ||.||_inf).
    work = best.copy()
    # progressively wider CVaR window: start broad (many knots near max),
    # narrow down as the plateau forms.
    alphas = [0.60, 0.50, 0.42, 0.36, 0.30, 0.25, 0.20, 0.16, 0.12]
    for k, alpha in enumerate(alphas):
        if time.process_time() >= deadline - 8.0:
            break
        tlim = min(deadline - 7.0, time.process_time() + 4.0)
        fg = (lambda h, a=alpha: _fun_grad_cvar(h, a))
        work = _lbfgs_custom(work, fg, tlim, maxiter=200)
        if k in (0, 3, len(alphas) - 1):
            consider(work, "cvar a=%.2f" % alpha)

    # ---------- Stage 2: exact-R tie polish, full then peak window ----------
    if time.process_time() < deadline - 5.0:
        work = _lbfgs_custom(work, _fun_grad_tie,
                             min(deadline - 4.0, time.process_time() + 4.0),
                             maxiter=300)
        consider(work, "tie full")

    for extra in (96, 256, 512):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(work, pad_frac=0.05, extra=extra)
        work = _lbfgs_block(work, win, 300,
                            min(deadline - 1.0, time.process_time() + 2.5),
                            _fun_grad_tie)
        consider(work, "tie win%d" % extra)

    # ---------- Stage 3: final tiny CVaR polish around the max ----------
    if time.process_time() < deadline - 0.5:
        work = _lbfgs_custom(work, lambda h: _fun_grad_cvar(h, 0.05),
                             deadline - 0.3, maxiter=120)
        consider(work, "cvar fine")

    # ensure we never regress below start
    if bestR < startR - 1e-15 and start is not None:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    num = float(np.sum(Lf * Lf))
    if num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -2.0 * Lf / num
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False, flat=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if flat:
        fg = _fun_grad_flat
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample(h, factor):
    """Smoothly refine the step function by a factor using linear interpolation."""
    n = h.size
    m = n * factor
    x = np.linspace(0, n, m, endpoint=False)
    xi = np.arange(n)
    return np.interp(x, xi, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (baseR, base.size, 100.0 * np.mean(base <= 0)))

    best = base.copy()
    bestR = baseR

    # Phase 0: refine resolution by upsampling. This is the substantial change:
    # the landscape of R on finer grids differs, and a finer start often escapes
    # the local optimum of the coarse construction. We try a few factors and keep
    # whichever polishes to the highest R.
    if base.size < 400000:
        factors = [2, 3, 4] if base.size < 120000 else [2]
        for fac in factors:
            if time.process_time() >= deadline - 6.0:
                break
            hu = _upsample(base, fac)
            if hu.size > 900000:
                continue
            hu = _rescale(hu)
            t_end = min(deadline - 4.0, time.process_time() + 8.0)
            h = _lbfgs_block(hu, np.arange(hu.size), 400, t_end, tie=True)
            r = R_of(h)
            if r > bestR + 1e-13:
                best, bestR = h, r
                print("upsample x%d R=%.7f (N=%d)" % (fac, bestR, best.size))
            # discard if bigger but worse
            elif r > bestR - 5e-4:
                # try polishing the upsampled one further as alternative seed
                t_end = min(deadline - 3.0, time.process_time() + 5.0)
                h2 = _lbfgs_block(h, np.arange(h.size), 300, t_end, beta=1e3)
                r2 = R_of(h2)
                if r2 > bestR + 1e-13:
                    best, bestR = h2, r2
                    print("upsample x%d beta R=%.7f (N=%d)" % (fac, bestR, best.size))

    # Phase 1: multi-pass polish with tie-awareness and beta smoothing.
    passes = [
        (None, 400, dict(beta=0.0, tie=True)),
        (None, 300, dict(beta=1e4)),
        (None, 300, dict(beta=1e3)),
        (None, 300, dict(beta=1e2)),
        (None, 300, dict(beta=0.0, tie=True)),
    ]
    for free, mi, kw in passes:
        if time.process_time() >= deadline - 2.0:
            break
        fr = free if free is not None else np.arange(best.size)
        t_end = min(deadline - 1.5, time.process_time() + 5.0)
        h = _lbfgs_block(best, fr, mi, t_end, **kw)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("pass R=%.7f" % bestR)

    # Phase 2: peak-window polishing with tie-aware gradient.
    for tol, pf, ex in [(0.9999, 0.5, 512), (0.9995, 0.3, 256),
                        (0.999, 0.2, 128), (0.99, 0.1, 64)]:
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, tol=tol, pad_frac=pf, extra=ex)
        t_end = min(deadline - 1.0, time.process_time() + 4.0)
        h = _lbfgs_block(best, win, 200, t_end, tie=True)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("peak tol=%.4f R=%.7f" % (tol, bestR))

    # Phase 3: flat-gradient polish.
    if time.process_time() < deadline - 3.0:
        t_end = min(deadline - 2.0, time.process_time() + 4.0)
        h = _lbfgs_block(best, np.arange(best.size), 300, t_end, flat=True)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("flat R=%.7f" % bestR)
        t_end = min(deadline - 1.0, time.process_time() + 4.0)
        h = _lbfgs_block(best, np.arange(best.size), 300, t_end, tie=True)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("post-flat R=%.7f" % bestR)

    # Phase 4: stochastic escapes with tie-aware polish.
    rng = np.random.default_rng(1234567)
    sigmas = [0.03, 0.01, 0.005, 0.002, 0.001]
    si = 0
    while time.process_time() < deadline - 2.0:
        sigma = sigmas[si % len(sigmas)]
        si += 1
        trial = best * np.exp(rng.normal(0.0, sigma, size=best.size))
        trial = _rescale(trial)
        t_end = min(deadline - 1.0, time.process_time() + 3.5)
        h = _lbfgs_block(trial, np.arange(best.size), 200, t_end, tie=True)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("escape sig=%.4f R=%.7f" % (sigma, bestR))

    # Final polish.
    for _ in range(3):
        if time.process_time() >= deadline - 1.0:
            break
        t_end = min(deadline - 0.8, time.process_time() + 3.0)
        h = _lbfgs_block(best, np.arange(best.size), 200, t_end, tie=True)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
        else:
            break

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _upsample_and_polish(h, deadline, fac=2):
    """Upsample via linear interpolation to a finer grid and polish."""
    if time.process_time() >= deadline - 0.5:
        return h, R_of(h)
    n0 = h.size
    n = min(1000000, n0 * fac)
    if n <= n0:
        return h, R_of(h)
    x_old = np.linspace(0.0, 1.0, n0)
    x_new = np.linspace(0.0, 1.0, n)
    h_up = np.interp(x_new, x_old, h)
    h_up = _rescale(np.clip(h_up, 0, None))
    r0 = R_of(h_up)
    hc = _lbfgs_all_pos(h_up, 200, min(deadline - 0.3,
                                       time.process_time() + 6.0), beta=0.0)
    rc = R_of(hc)
    if rc > r0:
        return hc, rc
    return h_up, r0


def _coarsen_refine(best, bestR, deadline, rng):
    n = best.size
    Lf = _knots(best)
    M = Lf.max()
    if M <= 0:
        return best, bestR, False
    idx = np.flatnonzero(Lf >= 0.999 * M)
    if idx.size == 0:
        return best, bestR, False
    lo = max(0, int(idx.min()) - 8)
    hi = min(n - 1, int(idx.max()) + 8)
    improved = False
    for _ in range(24):
        if time.process_time() >= deadline - 0.6:
            break
        i0 = int(rng.integers(lo, hi + 1))
        k = int(rng.integers(2, 6))
        i1 = min(n, i0 + k)
        if i1 - i0 < 2:
            continue
        mass = float(best[i0:i1].sum())
        h2 = np.concatenate([best[:i0], [mass], best[i1:]])
        win_lo = max(0, i0 - 96)
        win_hi = min(h2.size - 1, i0 + 96)
        free = np.arange(win_lo, win_hi + 1)
        h3 = _lbfgs_block(h2, free, 80, deadline, beta=0.0)
        r3 = R_of(h3)
        if r3 > bestR + 1e-13:
            best, bestR = h3, r3
            improved = True
    return best, bestR, improved


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(20240517)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Proven pipeline first.
    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    alt_cand = None
    altR = -1.0

    # New channel: upsample to finer grid and polish.  This is a
    # resolution increase that the original pipeline never does, and it
    # can unlock gains because the fine grid better represents sharp
    # features near the peak of f*f.
    for _ in range(6):
        if time.process_time() >= deadline - 1.5:
            break
        h_u, r_u = _upsample_and_polish(best, deadline - 1.0, fac=2)
        if r_u > bestR + 1e-13:
            if alt_cand is None:
                alt_cand, altR = h_u.copy(), r_u
            best, bestR = h_u, r_u
            print("upsample wins: R=%.7f (N=%d)" % (bestR, best.size))
            # Polish the upsampled version with the cycle machinery.
            if time.process_time() < deadline - 1.5:
                best, bestR = run_cycle(best, bestR, deadline - 1.0)
        else:
            break

    # Alternate: coarsen / refine / cycle until budget runs out.
    while time.process_time() < deadline - 1.5:
        before = bestR
        if time.process_time() < deadline - 1.5:
            h_cr, r_cr, imp = _coarsen_refine(best, bestR, deadline - 1.0, rng)
            if imp and r_cr > bestR + 1e-13:
                best, bestR = h_cr, r_cr
        if time.process_time() < deadline - 0.8:
            best, bestR = run_cycle(best, bestR, deadline - 0.8)
        if bestR <= before + 1e-13:
            if time.process_time() < deadline - 1.5:
                h_u, r_u = _upsample_and_polish(best, deadline - 1.0, fac=2)
                if r_u > bestR + 1e-13:
                    best, bestR = h_u, r_u
                    continue
            if bestR <= before + 1e-13:
                break

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    w = e / Z
    softmax_val = M + (np.log(Z) + zmax) / beta
    gLf = -dq / num
    gLf += w / softmax_val
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(softmax_val)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _soft_lbfgs(h0, deadline, beta, maxiter=150):
    return _lbfgs_custom(h0, lambda h: _fun_grad_soft(h, beta),
                         deadline, maxiter=maxiter)


def _upsample_linear(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    up = np.interp(x_new, x_old, h)
    return _rescale(np.clip(up, 0, None))


def _peak_align_polish(h, deadline, iters=40):
    """Directly target ||f*f||_inf: nudge the peak down / widen the top by
    rescaling the region around the argmax of f*f and re-running tie LBFGS."""
    best = h.copy()
    bestR = R_of(best)
    Lf = _knots(best)
    am = int(np.argmax(Lf))
    n = best.size
    for w in (0.02, 0.04, 0.08):
        if time.process_time() > deadline:
            break
        lo = max(0, am - int(w * n))
        hi = min(n, am + int(w * n))
        if hi <= lo:
            continue
        h2 = best.copy()
        h2[lo:hi] *= 0.98
        h2 = _rescale(h2)
        h2 = _full_lbfgs(h2, min(deadline, time.process_time() + 1.0),
                         maxiter=iters)
        r2 = R_of(h2)
        if r2 > bestR:
            best = h2
            bestR = r2
    return best, bestR


def _refine(h, deadline, levels=(2, 3)):
    best = _rescale(h.copy())
    bestR = R_of(best)
    n0 = best.size
    for fac in levels:
        if time.process_time() >= deadline - 0.5:
            break
        n = min(1000000, n0 * fac)
        if n <= best.size:
            continue
        h_up = _upsample_linear(best, n)
        r_up = R_of(h_up)
        if r_up > bestR:
            best = h_up; bestR = r_up
        tlim = min(deadline - 0.3, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
        # soft-max variant pushes toward flat top
        hc2 = _soft_lbfgs(best, min(deadline - 0.3, time.process_time() + 2.0),
                          beta=40.0, maxiter=120)
        rc2 = R_of(hc2)
        if rc2 > bestR:
            best = hc2; bestR = rc2
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93 - 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float), 0, None)
        if base.sum() <= 0:
            base = np.ones(64)
    else:
        base = np.ones(64)

    best = _rescale(base.copy())
    bestR = R_of(best)
    startR = bestR if start is not None else -1.0

    # 1) direct polish of the start at its own resolution
    if time.process_time() < deadline - 1.0:
        h = _full_lbfgs(best, min(deadline, time.process_time() + 2.5),
                        maxiter=200)
        r = R_of(h)
        if r > bestR:
            best = h; bestR = r

    # 2) soft-max polish to encourage flat top
    if time.process_time() < deadline - 1.0:
        h = _soft_lbfgs(best, min(deadline, time.process_time() + 2.0),
                        beta=30.0, maxiter=150)
        r = R_of(h)
        if r > bestR:
            best = h; bestR = r

    # 3) peak-alignment polish
    if time.process_time() < deadline - 1.0:
        h, r = _peak_align_polish(best, min(deadline, time.process_time() + 4.0))
        if r > bestR:
            best = h; bestR = r

    # 4) upsample & refine (the main gain)
    if time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, levels=(2, 3))
        if r > bestR:
            best = h; bestR = r

    # 5) final full polish at current resolution with remaining budget
    while time.process_time() < deadline - 0.5:
        h = _full_lbfgs(best, min(deadline, time.process_time() + 2.0),
                        maxiter=200)
        r = R_of(h)
        if r > bestR + 1e-9:
            best = h; bestR = r
        else:
            # try soft again to break out
            h2 = _soft_lbfgs(best, min(deadline, time.process_time() + 1.5),
                             beta=60.0, maxiter=120)
            r2 = R_of(h2)
            if r2 > bestR:
                best = h2; bestR = r2
            else:
                break

    print("R=%.6f N=%d startR=%.6f" % (bestR, best.size, startR))

    if start is not None:
        s_arr = np.asarray(start, dtype=float)
        if bestR > startR + 1e-9:
            return {"best": best, "alternative": s_arr}
        else:
            return {"best": s_arr, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    c = Lf.max()
    if c <= 0:
        return 1e18, np.zeros(h.size)
    ties = np.flatnonzero(Lf >= c * (1.0 - 1e-12))
    m = ties.size
    gLf = -dq / num
    gLf[ties] += (1.0 / m) / c
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(c)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=200):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad_frac=0.10, extra=384, maxiter=200):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.95 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    win = np.arange(lo, hi + 1)
    if win.size < 8:
        return h
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[win], floor, None))

    def f(u):
        hh = h.copy()
        hh[win] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[win] * hh[win]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * win.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[win] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _top_frac_mean(h, frac=0.01):
    Lf = _knots(h)
    n = Lf.size
    m = max(1, int(np.ceil(frac * n)))
    top = np.sort(Lf)[-m:]
    return float(top.mean())


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _top_frac_mean(best, 0.01)))

    loop = 0
    while time.process_time() < deadline - 2.0:
        loop += 1
        fd = min(deadline - 2.0, time.process_time() + 8.0)
        ht = _full_lbfgs(best, fd, maxiter=200)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("loop %d full ACCEPT R=%.9f top1%%=%.9f"
                  % (loop, bestR, _top_frac_mean(best, 0.01)))
            if time.process_time() < deadline - 2.0:
                fd2 = min(deadline - 2.0, time.process_time() + 4.0)
                hp = _peak_window_polish(best, fd2, pad_frac=0.10, extra=384,
                                         maxiter=200)
                rp = R_of(hp)
                if rp > bestR + 1e-15:
                    best, bestR = hp.copy(), rp
                    print("loop %d window ACCEPT R=%.9f top1%%=%.9f"
                          % (loop, bestR, _top_frac_mean(best, 0.01)))
        else:
            print("loop %d full no gain R=%.9f" % (loop, r))

    if time.process_time() < deadline - 0.5:
        fd = deadline - 0.3
        ht = _full_lbfgs(best, fd, maxiter=300)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            print("final full ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, top1%%=%.9f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             _nearmax_frac(best), _top_frac_mean(best, 0.01)))

    result = {"best": best}
    if bestR <= start_bestR + 1e-14 and start_best is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize, nnls
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _refine(h, deadline, levels=(2, 3, 4), target_n=104992):
    best = _rescale(h.copy())
    bestR = R_of(best)
    n0 = best.size
    for fac in levels:
        if time.process_time() >= deadline - 0.5:
            break
        n = min(target_n, n0 * fac)
        if n <= best.size:
            continue
        x_old = np.linspace(0.0, 1.0, best.size)
        x_new = np.linspace(0.0, 1.0, n)
        h_up = np.interp(x_new, x_old, best)
        h_up = _rescale(np.clip(h_up, 0, None))
        r_up = R_of(h_up)
        if r_up > bestR:
            best = h_up; bestR = r_up
        tlim = min(deadline - 0.3, time.process_time() + 4.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
    return best, bestR


def _downsample(h, Nc):
    """Mass-preserving block sums from h to Nc bins."""
    n = h.size
    if n == Nc:
        return h.copy()
    edges = np.linspace(0, n, Nc + 1)
    out = np.zeros(Nc)
    idx = np.arange(n)
    bin_id = np.minimum((idx * Nc // n).astype(int), Nc - 1)
    np.add.at(out, bin_id, h)
    return out


def _build_A(Nc):
    """Convolution matrix A (interior knots, size 2Nc-1) mapping f (Nc) to
    the interior knot values of f*f. Knot k (1..2Nc-1) = sum_i f_i f_{k-i}."""
    A = np.zeros((2 * Nc - 1, Nc))
    for k in range(2 * Nc - 1):
        for i in range(Nc):
            j = k - i
            if 0 <= j < Nc:
                A[k, i] += 1.0
    return A


def _target_g(Nc, a, b, p):
    t = (np.arange(2 * Nc - 1) + 1.0) / (2.0 * Nc)  # interior knot positions in (0,1)
    g = np.ones_like(t)
    left = t < a
    right = t > b
    if a > 0:
        g[left] = (t[left] / a) ** p
    if b < 1:
        g[right] = ((1.0 - t[right]) / (1.0 - b)) ** p
    return g


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 1: polish the given start well
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    # Phase 2: deconvolution experiment on coarse grid
    alt_best = best.copy()
    altR = bestR
    Nc = 1024
    target_n = max(104992, best.size)
    try:
        hc0 = _downsample(best, Nc)
        hc0 = _rescale(hc0)
        A = _build_A(Nc)
        # candidates
        cands = []
        for a in (0.10, 0.15, 0.20):
            for b in (0.80, 0.85, 0.90):
                for p in (1, 2, 4):
                    if time.process_time() >= deadline - 3.0:
                        break
                    g = _target_g(Nc, a, b, p)
                    # scale target so that alpha*g roughly matches A f scale
                    Af = A @ hc0
                    scale = (Af @ g) / (g @ g + 1e-12)
                    for lam in (1e-3, 1e-2):
                        if time.process_time() >= deadline - 3.0:
                            break
                        # augment for ridge
                        An = np.vstack([A, np.sqrt(lam) * np.eye(Nc)])
                        bn = np.concatenate([scale * g, np.zeros(Nc)])
                        try:
                            f, _ = nnls(An, bn, maxiter=200)
                        except Exception:
                            continue
                        if f.sum() <= 0:
                            continue
                        f = _rescale(f)
                        r = R_of(f)
                        cands.append((r, f, a, b, p, lam))
        cands.sort(key=lambda x: -x[0])
        print("deconv: %d cands, top R=%.12f" % (len(cands), cands[0][0] if cands else 0))
        # lift top candidates and polish
        for r, f, a, b, p, lam in cands[:4]:
            if time.process_time() >= deadline - 2.0:
                break
            # lift to target_n
            x_old = np.linspace(0.0, 1.0, f.size)
            x_new = np.linspace(0.0, 1.0, target_n)
            h_up = np.interp(x_new, x_old, f)
            h_up = _rescale(np.clip(h_up, 0, None))
            r_up = R_of(h_up)
            tlim = min(deadline - 1.0, time.process_time() + 4.0)
            hc = _full_lbfgs(h_up, tlim, maxiter=200)
            rc = R_of(hc)
            if rc > r_up:
                r_up = rc; h_up = hc
            if r_up > altR:
                alt_best = h_up.copy(); altR = r_up
                print("deconv lift a=%.2f b=%.2f p=%d lam=%.0e R=%.12f" % (a, b, p, lam, r_up))
            if r_up > bestR:
                best = h_up.copy(); bestR = r_up
                print("deconv new best R=%.12f" % bestR)
    except Exception as e:
        print("deconv failed: %s" % e)

    # Phase 3: refinement cascade on best
    if time.process_time() < deadline - 2.0:
        hc, rc = _refine(best, deadline - 0.5, target_n=target_n)
        if rc > bestR:
            best = hc; bestR = rc
            print("refined R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 4: continue polishing
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    alt = alt_best if altR > 0 else best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

