    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _argmax_frac(h):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    return m / max(1, Lf.size - 1)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("NEW BEST R=%.9f (%s, N=%d)" % (bestR, tag, best.size))
            return True
        elif r > alt_bestR:
            alt_best, alt_bestR = cand.copy(), r
        return False

    amax0 = _argmax_frac(best)

    # ---- Phase A: front-loaded peak-window polish ----
    a_deadline = t0 + budget_seconds * 0.12
    for pad in (0.06, 0.04, 0.025):
        if time.process_time() >= a_deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300, a_deadline - 0.3)
        offer(ht, 'A-pad=%.3f' % pad)
    print("Phase A done R=%.9f argmax_frac=%.4f" % (bestR, _argmax_frac(best)))

    # ---- Phase X: explicit support selection (reinsert/prune cells) ----
    x_deadline = t0 + budget_seconds * 0.80
    n_accept = 0
    for rnd in range(6):
        if time.process_time() >= x_deadline - 6.0:
            print("X round %d skipped (time)" % rnd)
            break
        R_before = bestR
        val, g = _fun_grad(best)
        active = best > 0
        zeros = ~active
        n_act = int(active.sum())
        if n_act < 10:
            print("X round %d: too few active" % rnd)
            break
        med_act = float(np.median(np.abs(g[active])))
        mean_act = float(np.mean(best[active]))

        # zero-candidates: most negative gradient
        zidx = np.flatnonzero(zeros)
        rev = np.array([], dtype=int)
        max_neg_g = 0.0
        if zidx.size:
            zg = g[zidx]
            order = np.argsort(zg)
            top = zidx[order[:6]]
            top_g = zg[order[:6]]
            rev = top[top_g < 0]
            max_neg_g = float(-top_g[0])

        # prune-candidates: largest g*h among smallest 30% active heights
        aidx = np.flatnonzero(active)
        hact = best[aidx]
        prune = np.array([], dtype=int)
        if aidx.size > 4:
            thr = np.quantile(hact, 0.30)
            small = aidx[hact <= thr]
            if small.size == 0:
                small = aidx[np.argsort(hact)[:max(1, aidx.size // 10)]]
            gh = g[small] * best[small]
            pr_order = np.argsort(-gh)
            prune = small[pr_order[:6]]
            sm2 = aidx[np.argsort(hact)[:2]]
            prune = np.unique(np.concatenate([prune, sm2]))

        print("X round %d: n_rev=%d n_prune=%d max(-g_rev)=%.3e med|g_act|=%.3e"
              % (rnd, rev.size, prune.size, max_neg_g, med_act))

        best_cand = None
        best_candR = -1.0
        for alpha in (1e-3, 1e-2, 5e-2):
            if time.process_time() >= x_deadline - 4.0:
                break
            h2 = best.copy()
            if rev.size:
                h2[rev] = alpha * mean_act
            if prune.size:
                h2[prune] = 0.0
            win = _peak_window(best, pad_frac=0.05, extra=128)
            extra_idx = []
            for idx in np.concatenate([rev, prune]):
                lo = max(0, idx - 8); hi = min(best.size - 1, idx + 8)
                extra_idx.append(np.arange(lo, hi + 1))
            if extra_idx:
                free = np.unique(np.concatenate([win] + extra_idx))
            else:
                free = win
            dl = x_deadline - 3.0
            ht = _lbfgs_block(h2, free, 300, dl)
            ht = _lbfgs_all_pos(ht, 300, dl)
            ht = _peak_ladder(ht, dl, pads=(0.05, 0.03), iters=200)
            r = R_of(ht)
            if r > best_candR:
                best_cand, best_candR = ht, r
        if best_cand is not None:
            if best_candR > bestR + 1e-12:
                best, bestR = best_cand.copy(), best_candR
                n_accept += 1
                print("X round %d ACCEPT R=%.9f dR=%.3e" % (rnd, bestR, bestR - R_before))
            else:
                if best_candR > alt_bestR:
                    alt_best, alt_bestR = best_cand.copy(), best_candR
                print("X round %d reject R=%.9f dR=%.3e" % (rnd, best_candR, best_candR - R_before))
    print("Phase X done R=%.9f n_accept=%d N=%d" % (bestR, n_accept, best.size))

    # ---- Final polish: full-vector L-BFGS then peak ladder ----
    final_deadline = t0 + budget_seconds * 0.97
    ht = _lbfgs_all_pos(best, 500, final_deadline - 0.5)
    offer(ht, 'final-full')
    ht = _peak_ladder(best, final_deadline - 0.2, pads=(0.05, 0.03, 0.02), iters=300)
    offer(ht, 'final-peak')

    amax1 = _argmax_frac(best)
    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, argmax_frac=%.4f, "
          "d_argmax=%.4f, nearmax5=%.4f)"
          % (bestR, start_bestR, best.size, _zero_frac(best),
             amax1, amax1 - amax0, _nearmax_frac(best)))

    result = {"best": best}
    if alt_best is not None and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _refine(h, deadline, levels=(2, 3, 4)):
    best = _rescale(h.copy())
    bestR = R_of(best)
    n0 = best.size
    for fac in levels:
        if time.process_time() >= deadline - 0.5:
            break
        n = min(1000000, n0 * fac)
        if n <= best.size:
            continue
        x_old = np.linspace(0.0, 1.0, best.size)
        x_new = np.linspace(0.0, 1.0, n)
        h_up = np.interp(x_new, x_old, best)
        h_up = _rescale(np.clip(h_up, 0, None))
        r_up = R_of(h_up)
        if r_up > bestR:
            best = h_up; bestR = r_up
        tlim = min(deadline - 0.3, time.process_time() + 4.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
    return best, bestR


def _mult_step(h, gamma, nsteps, deadline):
    """Multiplicative (exponentiated-gradient) update toward a flattened g."""
    h = np.clip(h, 0, None).astype(float)
    if h.sum() <= 0:
        return h
    for _ in range(nsteps):
        if time.process_time() >= deadline:
            break
        s = h.sum()
        Lf = _knots(h)
        M = Lf.max()
        if M <= 0:
            break
        # Build flattened target on knot grid
        ratio = Lf / M
        T = Lf.copy()
        mask = Lf >= 0.4 * M
        T[mask] = M * np.power(np.clip(ratio[mask], 0.0, None), gamma)
        # r = T / L on interior knots
        Lint = Lf[1:-1]
        r = T[1:-1] / (Lint + 1e-12)
        # gradient of L2/KL misfit wrt h via backprop
        gLf = np.zeros_like(Lf)
        gLf[1:-1] = r
        grad = _backprop(gLf, h)
        eps_scale = s
        upd = np.clip(grad / (eps_scale + 1e-30) + 1e-3, 0.2, 5.0)
        h = h * upd
        # renormalise to unit mass
        tot = h.sum()
        if tot <= 0:
            break
        h = h / tot
    return _rescale(h)


def _gamma_loop(h, deadline, gammas=(0.85, 0.70, 0.55), cycles=3, nsteps=40):
    best = h.copy()
    bestR = R_of(best)
    for gamma in gammas:
        for c in range(cycles):
            if time.process_time() >= deadline - 1.0:
                break
            hc = _mult_step(best, gamma, nsteps, deadline - 1.0)
            rc = R_of(hc)
            # polish with exact-tie L-BFGS
            tlim = min(deadline - 0.5, time.process_time() + 3.0)
            hp = _full_lbfgs(hc, tlim, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best = hp; bestR = rp
                print("gamma=%.2f cyc=%d R=%.12f" % (gamma, c, bestR))
            elif rc > bestR + 1e-15:
                best = hc; bestR = rc
        if time.process_time() >= deadline - 1.0:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 1: polish the given start well
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    # Phase 2: multiplicative g-first route (new experiment)
    alt_best = best.copy()
    altR = bestR
    if time.process_time() < deadline - 5.0:
        # run gamma loop on current grid
        hc, rc = _gamma_loop(best, deadline - 3.0)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("g-first R=%.12f" % bestR)
        if bestR > altR:
            alt_best = best.copy(); altR = bestR

    # Phase 2b: run gamma loop once on 2x-lifted grid
    if time.process_time() < deadline - 4.0:
        n = min(1000000, best.size * 2)
        if n > best.size:
            x_old = np.linspace(0.0, 1.0, best.size)
            x_new = np.linspace(0.0, 1.0, n)
            h_up = np.interp(x_new, x_old, best)
            h_up = _rescale(np.clip(h_up, 0, None))
            r_up = R_of(h_up)
            if r_up > bestR:
                best = h_up; bestR = r_up
            hc, rc = _gamma_loop(best, deadline - 2.0)
            if rc > bestR + 1e-15:
                best = hc; bestR = rc
                print("g-first 2x R=%.12f (N=%d)" % (bestR, best.size))
            if bestR > altR:
                alt_best = best.copy(); altR = bestR

    # Phase 3: refinement cascade
    if time.process_time() < deadline - 2.0:
        hc, rc = _refine(best, deadline - 0.5)
        if rc > bestR:
            best = hc; bestR = rc
            print("refined R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 4: continue polishing on finest grid
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    alt = alt_best if altR > 0 else best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


