    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _shares(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (np.mean(L >= 0.999 * mx), np.mean(L >= 0.99 * mx),
            np.mean(L >= 0.95 * mx))


def _num_and_dq(h):
