    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, deadline, maxiter=300, beta=0.0, log_param=False, idx=None):
    if time.process_time() >= deadline - 0.25:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    if idx is None:
        idx = np.arange(h.size)
    idx = np.asarray(idx, dtype=int)
    if idx.size == 0:
        return h0

    if log_param:
        hv = h[idx]
        hmax = hv.max() if hv.size else 1.0
        floor = max(hmax * 1e-12, 1e-300)
        x0 = np.log(np.maximum(hv, floor))

        def f(x):
            hh = h.copy()
            hh[idx] = np.exp(np.clip(x, -700, 700))
            val, g = fg(hh)
            return val, g[idx] * hh[idx]
        bounds = [(-40.0, 40.0)] * idx.size
    else:
        x0 = h[idx]

        def f(x):
            hh = h.copy()
            hh[idx] = np.clip(x, 0.0, None)
            val, g = fg(hh)
            return val, g[idx]
        bounds = [(0.0, None)] * idx.size

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    if log_param:
        h2[idx] = np.exp(np.clip(res.x, -700, 700))
    else:
        h2[idx] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.5, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_polish(h, deadline, pads=(0.08, 0.05, 0.03)):
    best = h.copy()
    bestR = R_of(best)
    for pad in pads:
        if time.process_time() >= deadline - 0.6:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs(best, deadline - 0.3, maxiter=250, log_param=True, idx=win)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
    return best, bestR


# ---- Higher-resolution (2x) refinement: work at 2N, keep best of up/fold ----

def _lift2(h, offset=0.5):
    N = h.size
    N2 = 2 * N
    c = np.concatenate(([0.0], np.cumsum(h)))
    j = np.arange(N2, dtype=float)
    x = (j + offset) * (N / N2)
    x = np.clip(x, 0.0, N)
    mass = np.interp(x, np.arange(N + 1, dtype=float), c)
    hm = np.diff(np.concatenate(([0.0], mass)))
    return _rescale(np.clip(hm, 0, None))


def _fold2(h, N, offset=0.5):
    N2 = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    j = np.arange(N, dtype=float)
    x = (j + offset) * (N2 / N)
    x = np.clip(x, 0.0, N2)
    mass = np.interp(x, np.arange(N2 + 1, dtype=float), c)
    hm = np.diff(np.concatenate(([0.0], mass)))
    return _rescale(np.clip(hm, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def consider(hc, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(hc)
        if r > bestR + 1e-13:
            best, bestR, origin = hc.copy(), r, tag
            print("  NEW BEST R=%.9f (%s) N=%d" % (bestR, tag, best.size))
            return True
        if r > alt_bestR:
            alt_best, alt_bestR = hc.copy(), r
        return False

    N = best.size
    if N < 8:
        return {"best": best}

    round_no = 0
    phi_seq = [1, 0]
    while time.process_time() < deadline - 1.5:
        phi = phi_seq[round_no % len(phi_seq)]
        round_no += 1
        N = best.size
        idx = np.arange(phi, N, 2)
        if idx.size < 2:
            continue
        now = time.process_time()
        slice_dl = min(deadline - 1.0, now + 0.11 * budget_seconds)
        if slice_dl <= now + 0.5:
            break

        # block-coordinate on this sublattice (log-param)
        hb = _lbfgs(best, slice_dl - 0.3, maxiter=250, log_param=True, idx=idx)
        rb = R_of(hb)
        accepted = False
        if rb > bestR + 1e-13:
            best, bestR, origin = hb.copy(), rb, 'phi%d_r%d' % (phi, round_no)
            accepted = True
            print("  NEW BEST R=%.9f (phi=%d block)" % (bestR, phi))
        elif rb > alt_bestR:
            alt_best, alt_bestR = hb.copy(), rb

        # full-N polish with beta smoothing
        if time.process_time() < slice_dl - 0.5:
            hf = _lbfgs(best, slice_dl - 0.3, maxiter=200, beta=0.0,
                        log_param=False)
            if consider(hf, 'phi%d_full_r%d' % (phi, round_no)):
                accepted = True

        # peak-window polish
        if time.process_time() < slice_dl - 0.4:
            hp, rp = _peak_polish(best, slice_dl)
            if consider(hp, 'phi%d_pk_r%d' % (phi, round_no)):
                accepted = True

        sh = _shares(best)
        print("cycle %d phi=%d acc=%s R=%.9f shares=%.3f/%.3f/%.3f (best %.9f)"
              % (round_no, phi, accepted, R_of(best), sh[0], sh[1], sh[2],
                 bestR))

        # Refinement at 2x resolution: optimize there, then fold back and polish
        if round_no % 2 == 0 and time.process_time() < deadline - 2.0:
            N = best.size
            N2 = 2 * N
            if N2 <= 1000000:
                lift_dl = min(deadline - 1.0,
                              time.process_time() + 0.15 * budget_seconds)
                if lift_dl > time.process_time() + 0.8:
                    hl = _lift2(best, 0.5)
                    # full polish at 2N
                    hl = _lbfgs(hl, lift_dl - 0.4, maxiter=200, beta=0.0,
                                log_param=False)
                    if time.process_time() < lift_dl - 0.4:
                        hp, _ = _peak_polish(hl, lift_dl)
                        if R_of(hp) > R_of(hl):
                            hl = hp
                    # try both fold offsets; keep best
                    cand = [hl]
                    for off in (0.5, 0.0):
                        if time.process_time() >= lift_dl - 0.3:
                            break
                        hf = _fold2(hl, N, off)
                        hf, _ = _peak_polish(hf, lift_dl)
                        cand.append(hf)
                    best_cand = max(cand, key=R_of)
                    if consider(best_cand, 'lift2x_r%d' % round_no):
                        pass
                    sh = _shares(best)
                    print("  lift2x round %d R=%.9f shares=%.3f/%.3f/%.3f"
                          % (round_no, R_of(best), sh[0], sh[1], sh[2]))

    # Final polish
    if time.process_time() < deadline - 0.8:
        hp, rp = _peak_polish(best, deadline)
        consider(hp, origin + '+finalpk')
    if time.process_time() < deadline - 0.5:
        hf = _lbfgs(best, deadline - 0.3, maxiter=200, beta=0.0,
                    log_param=False)
        consider(hf, origin + '+finalb0')

    print("final R=%.9f origin=%s (start %.9f, N=%d)"
          % (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.20, 0.14, 0.09, 0.06, 0.04), iters=400):
    best = h.copy()
    bestR = R_of(best)
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, iters, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR = ht2, r2
    return best, bestR


def _half_polish(c, bestR, deadline):
    best = c.copy()
    work = c.copy()
    for beta in [1e5, 1e6, 1e7]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
    for pad in [0.30, 0.20, 0.14, 0.10, 0.06]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(work, pad_frac=pad, extra=128)
        ht = _lbfgs_block(work, win, 400, deadline - 0.3, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            work, best, bestR = ht, ht.copy(), r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(work, 300, deadline - 0.3, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                work, best, bestR = ht2, ht2.copy(), r2
    return work, best, bestR


def _extract(c_full, k, m):
    if k == 0:
        c = c_full[0::2][:m].copy()
    elif k == 1:
        c = c_full[1::2][:m].copy()
    else:
        a = c_full[0::2][:m]
        b = c_full[1::2][:m]
        L = min(a.size, b.size)
        c = 0.5 * (a[:L] + b[:L])
        if c.size < m:
            c = np.concatenate((c, np.full(m - c.size, c[-1])))
    return c


def _lift(c, k, N):
    m = c.size
    if k == 0:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])
    elif k == 1:
        h = np.zeros(N)
        h[1::2] = c[:h[1::2].size]
        ev = np.empty(h[0::2].size)
        ev[0] = c[0]
        if ev.size > 1:
            k2 = min(ev.size - 1, m - 1)
            ev[1:1 + k2] = 0.5 * (c[:k2] + c[1:1 + k2])
            if ev.size > 1 + k2:
                ev[1 + k2:] = c[-1]
        h[0::2] = ev
        return _rescale(h)
    else:
        h = np.repeat(c, 2)
        if h.size < N:
            h = np.concatenate((h, [h[-1]]))
        return _rescale(h[:N])


def _block_refine(h0, deadline, rounds=6):
    best = h0.copy()
    bestR = R_of(best)
    for tol in (0.999, 0.99, 0.97, 0.95, 0.92):
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, tol=tol, pad_frac=0.25, extra=256)
        ht = _lbfgs_block(best, win, 300, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        if time.process_time() < deadline - 0.6:
            ht2 = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-15:
                best, bestR = ht2, r2
    return best, bestR


def _upsample(h, factor):
    """Upsample step heights by a factor via linear interpolation of the
    piecewise-constant profile onto a finer grid (preserves the shape)."""
    n = h.size
    if factor == 1:
        return h.copy()
    N = n * factor
    x = (np.arange(N) + 0.5) / factor  # position in original units
    idx = np.clip(x.astype(int), 0, n - 1)
    return _rescale(h[idx].astype(float))


def _structural_edit(best, bestR, alt_best, alt_bestR, deadline):
    """Finer-grained structural edits on a downsampled companion, then lift."""
    if time.process_time() >= deadline - 1.5 or best.size < 8:
        return best, bestR, alt_best, alt_bestR
    Ns = best.size
    rng = np.random.RandomState(999)
    trial = 0
    accepted = 0
    while time.process_time() < deadline - 1.5:
        act = np.flatnonzero(best > 0.02 * best.max())
        if act.size == 0:
            break
        progressed = False
        perm = rng.permutation(act)
        for i in perm[:min(20, perm.size)]:
            i = int(i)
            if time.process_time() >= deadline - 1.5:
                break
            now = time.process_time()
            slice_dl = min(now + 1.0, deadline - 1.5)
            if slice_dl <= now + 0.3:
                break
            trial += 1
            cands = []
            v = best[i]
            if v > 0:
                for d in (-1, +1):
                    j = i + d
                    if 0 <= j < Ns and best[j] <= 0.01 * best.max():
                        h2 = best.copy()
                        h2[i] = 0.0
                        h2[j] = h2[j] + v
                        cands.append(h2)
                        break
            if i + 1 < Ns:
                h2 = best.copy()
                half = 0.5 * best[i]
                h2[i] = half
                h2[i + 1] = h2[i + 1] + half
                cands.append(h2)
            if i + 1 < Ns:
                h2 = best.copy()
                a = best[i] * (1.0 / 3.0)
                h2[i] = a
                h2[i + 1] = h2[i + 1] + (best[i] - a)
                cands.append(h2)
            if i + 1 < Ns:
                h2 = best.copy()
                h2[i] = h2[i] + h2[i + 1]
                h2[i + 1] = 0.0
                cands.append(h2)
            local = None
            localR = -1.0
            for h2 in cands:
                if time.process_time() >= slice_dl - 0.3:
                    break
                h2 = _rescale(np.clip(h2, 0, None))
                win = _peak_window(h2, pad_frac=0.15, extra=384)
                h2 = _lbfgs_block(h2, win, 120, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 0.3:
                    h2 = _lbfgs_all_pos(h2, 120, slice_dl, beta=1e7)
                r2 = R_of(h2)
                if r2 > localR:
                    local, localR = h2, r2
            if local is None:
                continue
            progressed = True
            if localR > bestR + 1e-13:
                best, bestR = local.copy(), localR
                accepted += 1
            elif localR > alt_bestR:
                alt_best, alt_bestR = local.copy(), localR
        if not progressed:
            break
    print("struct edits trials=%d accepted=%d bestR=%.9f" %
          (trial, accepted, bestR))
    return best, bestR, alt_best, alt_bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution quotient search ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 2.0:
        c = best[0::2].copy()
        cR = R_of(c)
        print("half-res R(c)=%.9f (full %.9f)" % (cR, bestR))
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        best_c = c.copy()
        best_cR = cR
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            work_c, best_c, best_cR = _half_polish(work_c, best_cR, half_deadline)
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        h_lift = _rescale(np.repeat(best_c, 2))
        ht = h_lift
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_all_pos(ht, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'lift'
            print("lift NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: rotation of extract/lift cycles (all three variants) ----
    N = best.size
    m = N // 2
    cyc = 0
    if N % 2 == 0 and N >= 4 and m >= 2:
        w = [best.copy(), best.copy(), best.copy()]
        wR = [R_of(w[0]), R_of(w[1]), R_of(w[2])]
        cycle_end = deadline - 8.0
        max_cycles = 9
        while cyc < max_cycles and time.process_time() < cycle_end - 1.0:
            k = cyc % 3
            cyc += 1
            now = time.process_time()
            slice_dl = min(deadline - 6.0, now + 0.06 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            wk = w[k]
            c = _extract(wk, k, m)
            cR0 = R_of(c)
            try:
                work_c, cand_c, cand_cR = _half_polish(c, cR0, slice_dl)
            except Exception:
                continue
            try:
                hnew = _lift(cand_c, k, N)
            except Exception:
                continue
            ht = hnew
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ht = _lbfgs_all_pos(ht, 300, slice_dl - 0.3, beta=beta)
            r = R_of(ht)
            print("cycle %d var %d R(c)=%.9f liftR=%.9f (best %.9f)" %
                  (cyc, k, cand_cR, r, bestR))
            if r > wR[k] + 1e-13:
                w[k] = ht.copy()
                wR[k] = r
            if r > bestR + 1e-13:
                best, bestR, origin = ht.copy(), r, 'v%dcy%d' % (k, cyc)
                print("  cycle NEW BEST R=%.9f (var %d)" % (bestR, k))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 3: structural edits ----
    struct_end = deadline - 5.0
    if time.process_time() < struct_end - 1.0 and best.size >= 4:
        best, bestR, alt_best, alt_bestR = _structural_edit(
            best, bestR, alt_best, alt_bestR, struct_end)

    # ---- Phase 3.5: fine-grained upsample + polish ----
    if time.process_time() < deadline - 3.0 and best.size * 2 <= 1000000:
        up = _upsample(best, 2)
        upR = R_of(up)
        for beta in [1e6, 1e7]:
            if time.process_time() >= deadline - 3.0:
                break
            up = _lbfgs_all_pos(up, 300, deadline - 2.5, beta=beta)
        r = R_of(up)
        if r > bestR + 1e-14:
            best, bestR, origin = up.copy(), r, origin + '+up2'
            print("upsample x2 NEW BEST R=%.9f (N=%d)" % (bestR, best.size))
        elif r > alt_bestR:
            alt_best, alt_bestR = up.copy(), r

    # ---- Phase 4: final ladder polish + block refine ----
    if time.process_time() < deadline - 1.0:
        best, bestR = _peak_ladder(best, deadline)
    if time.process_time() < deadline - 1.0:
        best2, bestR2 = _block_refine(best, deadline)
        if bestR2 > bestR + 1e-15:
            best, bestR = best2, bestR2
            origin = origin + '+refine'

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _warp(h, theta, x):
    N = h.size
    d = np.zeros(N)
    for m in range(7):
        d += theta[2 * m] * np.sin(2 * np.pi * m * x)
        d += theta[2 * m + 1] * np.cos(2 * np.pi * m * x)
    y = np.clip(x + d, 0.0, 1.0)
    hw = np.interp(y, x, h)
    return _rescale(hw)


def _powell_warp(h, deadline, maxfev=3000):
    N = h.size
    x = (np.arange(N) + 0.5) / N
    bound = 1.5e-4
    bnds = [(-bound, bound)] * 14

    def obj(theta):
        if time.process_time() > deadline:
            raise TimeoutError
        hw = _warp(h, theta, x)
        return -R_of(hw)

    best_theta = np.zeros(14)
    best_val = -R_of(h)
    starts = [np.zeros(14)]
    rng = np.random.RandomState(12345)
    for _ in range(4):
        starts.append(rng.uniform(-bound * 0.5, bound * 0.5, 14))
    for th0 in starts:
        if time.process_time() > deadline - 0.5:
            break
        try:
            res = minimize(obj, th0, method='Powell', bounds=bnds,
                           options={'maxfev': maxfev, 'xtol': 1e-10, 'ftol': 1e-14})
        except (TimeoutError, Exception):
            break
        if res is not None and res.fun < best_val:
            best_val = res.fun
            best_theta = res.x.copy()
    return best_theta, -best_val


def _upsample(h, N2):
    N = h.size
    if N2 == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, c[-1], N2 + 1)
    y = np.interp(xs, np.linspace(0.0, c[-1], N + 1), c)
    return np.diff(y)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 120, 'maxfun': 240,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Phase 1: coordinate warp via Powell ----
    warp_deadline = min(deadline - 2.0, time.process_time() + budget_seconds * 0.15)
    theta, rw = _powell_warp(bestH, warp_deadline)
    N = bestH.size
    x = (np.arange(N) + 0.5) / N
    hw = _warp(bestH, theta, x)
    rw = R_of(hw)
    print("warp R=%.7f" % rw)
    if rw > bestRH + 1e-13:
        bestH, bestRH = hw.copy(), rw

    # ---- Phase 2: p-norm ladder + sharp polish ----
    ladder = (4, 8, 16, 32, 64, 128)
    loop_end = t0 + budget_seconds * 0.78
    stage_count = 0
    roundN = 0

    while time.process_time() < loop_end - 1.5 and time.process_time() < deadline - 3.0:
        roundN += 1
        for p in ladder:
            if time.process_time() >= loop_end - 1.5 or time.process_time() >= deadline - 3.0:
                break
            sub_deadline = min(loop_end, time.process_time() + 7.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(bestH, 80, sub_deadline, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-13:
                bestH, bestRH = h.copy(), r
            print("  R%d p=%d R=%.7f" % (roundN, p, bestRH))
            stage_count += 1

            if stage_count % 2 == 0:
                if time.process_time() >= loop_end - 1.0:
                    break
                sub2 = min(loop_end, time.process_time() + 6.0)
                hs = _lbfgs_log(bestH, 200, sub2)
                rs = R_of(hs)
                if rs > bestRH + 1e-13:
                    bestH, bestRH = hs.copy(), rs
                print("  R%d sharp R=%.7f" % (roundN, bestRH))

    # ---- Phase 3: CVaR-style polish (different objective, escapes ties) ----
    cvar_end = min(deadline - 3.0, time.process_time() + budget_seconds * 0.08)
    for alpha in (0.002, 0.005, 0.01):
        if time.process_time() >= cvar_end:
            break
        fg = (lambda hh, _a=alpha: _fun_grad_cvar(hh, _a))
        h = _lbfgs_log(bestH, 120, cvar_end, fg=fg)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("cvar a=%.4f R=%.7f" % (alpha, bestRH))

    # ---- Phase 4: upsample refine ----
    if time.process_time() < deadline - 5.0:
        Ncur = bestH.size
        Nnew = min(1000000, int(Ncur * 2))
        if Nnew > Ncur:
            try:
                hu = _rescale(_upsample(bestH, Nnew))
                ru = R_of(hu)
                if ru > bestRH - 1e-6:
                    sub = min(deadline - 2.0, time.process_time() + 10.0)
                    h2 = _lbfgs_log(hu, 150, sub)
                    r2 = R_of(h2)
                    if r2 > bestRH + 1e-13:
                        bestH, bestRH = h2.copy(), r2
                        print("upsample N=%d R=%.7f" % (Nnew, bestRH))
            except Exception:
                pass

    # ---- Final sharp polish + tie-aware peak-window ----
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(bestH, 400, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final sharp R=%.7f" % bestRH)

    if time.process_time() < deadline - 1.0:
        h = _peak_window_polish(bestH, deadline - 0.5)
        r = R_of(h)
        if r > bestRH + 1e-13:
            bestH, bestRH = h.copy(), r
        print("final peak-window R=%.7f" % bestRH)

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_flat(h, eps, lam):
    """Tie objective plus a quadratic penalty pulling near-peak knots up
    toward the max: flattens the plateau so the max can be pushed down."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idxmax = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    gLf[idxmax] += (1.0 / idxmax.size) / M
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    if lam > 0 and eps > 0:
        S = np.flatnonzero(Lf >= (1.0 - eps) * M)
        if S.size > 0:
            r = Lf[S] / M - 1.0
            val += lam * np.sum(r * r)
            gLf[S] += 2.0 * lam * r / M
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, mode='tie', param=None,
                 logparam=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0

    if mode == 'beta':
        fg = (lambda hh: _fun_grad_beta(hh, param))
    elif mode == 'flat':
        eps, lam = param
        fg = (lambda hh: _fun_grad_flat(hh, eps, lam))
    else:
        fg = _fun_grad_tie

    if logparam:
        pos = active[h[active] > 1e-14 * max(h.max(), 1e-30)]
        if pos.size == 0:
            return h0
        floor = 1e-10 * h.max()
        u0 = np.log(np.clip(h[pos], floor, None))

        def f(u):
            hh = h.copy()
            hh[pos] = np.exp(u)
            val, g = fg(hh)
            return val, g[pos] * hh[pos]

        cb = _make_cb(deadline - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * pos.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return h0
        if res is None:
            return h0
        h2 = h.copy()
        h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
        return _rescale(h2)

    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _upsample_fft(h, k):
    n = h.size
    if k <= 1:
        return h.copy()
    m = n * k
    H = np.fft.rfft(h)
    out = np.fft.irfft(H, m) * (m / n)
    s_in = h.sum()
    s_out = out.sum()
    if s_out > 0:
        out *= s_in / s_out
    return np.clip(out, 0.0, None)


def _peak_window(h, frac=0.5, pad=64):
    Lf = _knots(h)
    n = h.size
    mx = Lf.max()
    if mx <= 0:
        return np.arange(n)
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return np.arange(n)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    span = hi - lo
    extra = max(pad, int(span * frac))
    lo = max(0, lo - extra)
    hi = min(n - 1, hi + extra)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _plateau_score(h):
    """R exactly, plus a tiebreaker: fraction of near-peak knots. Used to
    prefer constructions with a broader flat plateau (more room to grow)."""
    return R_of(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    best = None
    startR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("start R=%.9f N=%d ties=%d"
          % (bestR, best.size, _tie_count(best)))

    # Phase A (new idea): flatten the near-peak plateau with a penalty term
    # that pulls near-peak knots up toward the max before pushing the max
    # down. This is different from pure tie gradient: we actively widen the
    # plateau so future upsample steps have more equal knots to work with.
    pA_end = t0 + budget_seconds * 0.40
    if time.process_time() < pA_end - 2.0:
        for eps, lam in ((0.02, 1e2), (0.02, 1e3), (0.01, 1e3),
                         (0.01, 1e4), (0.005, 1e4)):
            if time.process_time() >= pA_end - 2.0:
                break
            win = _peak_window(best, frac=0.5, pad=96)
            if win.size < 8:
                win = np.arange(best.size)
            ht = _lbfgs_block(best, win, 250,
                              min(pA_end - 1.0, time.process_time() + 4.0),
                              mode='flat', param=(eps, lam))
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
            # follow with pure tie to convert the flatter plateau into R.
            ht = _lbfgs_block(best, win, 250,
                              min(pA_end - 1.0, time.process_time() + 4.0),
                              mode='tie')
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("phaseA R=%.9f" % bestR)

    # Phase B: upsample with FFT and re-polish.
    pB_end = t0 + budget_seconds * 0.72
    for k in (2, 2, 3):
        if time.process_time() >= pB_end - 3.0:
            break
        if best.size * k > 900000:
            continue
        hu = _upsample_fft(best, k)
        if hu.size == best.size:
            continue
        ht = _lbfgs_block(hu, np.arange(hu.size), 200,
                          min(pB_end - 1.0, time.process_time() + 6.0),
                          mode='beta', param=1e6)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
            hu = ht
        else:
            hu = best if best.size == hu.size else hu
        for frac, pad in ((0.5, 64), (0.25, 48), (0.12, 32)):
            if time.process_time() >= pB_end - 1.5:
                break
            win = _peak_window(hu, frac=frac, pad=pad)
            ht = _lbfgs_block(hu, win, 250,
                              min(pB_end - 1.0, time.process_time() + 5.0),
                              mode='flat', param=(0.01, 1e3))
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                hu = ht
            ht = _lbfgs_block(hu, win, 250,
                              min(pB_end - 1.0, time.process_time() + 5.0),
                              mode='tie')
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                hu = ht
            ht = _lbfgs_block(hu, win, 250,
                              min(pB_end - 1.0, time.process_time() + 5.0),
                              mode='tie', logparam=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
                hu = ht
        print("phaseB k=%d R=%.9f N=%d ties=%d"
              % (k, bestR, best.size, _tie_count(best)))

    # Phase C: alternating full tie polish + peak-window polish + flat.
    fd = t0 + budget_seconds * 0.985
    cyc = 0
    while time.process_time() < fd - 1.5:
        cyc += 1
        prevR = bestR
        ht = _lbfgs_block(best, np.arange(best.size), 120,
                          min(fd - 1.0, time.process_time() + 4.0),
                          mode='tie')
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        for frac, pad in ((0.15, 32), (0.08, 24)):
            if time.process_time() >= fd - 1.0:
                break
            win = _peak_window(best, frac=frac, pad=pad)
            ht = _lbfgs_block(best, win, 250,
                              min(fd - 0.8, time.process_time() + 3.5),
                              mode='flat', param=(0.01, 1e3))
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
            ht = _lbfgs_block(best, win, 250,
                              min(fd - 0.8, time.process_time() + 3.5),
                              mode='tie')
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
            ht = _lbfgs_block(best, win, 250,
                              min(fd - 0.8, time.process_time() + 3.5),
                              mode='tie', logparam=True)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        if bestR - prevR < 1e-13 and cyc > 3:
            if best.size * 2 <= 900000 and time.process_time() < fd - 5.0:
                hu = _upsample_fft(best, 2)
                ht = _lbfgs_block(hu, np.arange(hu.size), 200,
                                  min(fd - 1.0, time.process_time() + 5.0),
                                  mode='beta', param=1e6)
                r = R_of(ht)
                if r > bestR + 1e-15:
                    best, bestR = ht.copy(), r
                else:
                    break
            else:
                break
        print("phaseC cyc=%d R=%.9f" % (cyc, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


# ---- objective variants ----

def _fun_grad_max(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_max(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad_max(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad_max

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad_max

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # ---- Strategy A: CVaR-style smoothing with decreasing alpha ----
    # The current max-based objective is very peaky; using a CVaR over the top
    # fraction of knots lets the whole near-peak plateau rise together,
    # then we tighten alpha back to a max.
    alphas = [0.5, 0.2, 0.1, 0.05, 0.02, 0.01, 0.005, 0.002]
    for alpha in alphas:
        if time.process_time() >= deadline - 6.0:
            break
        sub = min(deadline - 3.0, time.process_time() + 4.0)
        fg = (lambda hh, _a=alpha: _fun_grad_cvar(hh, _a))
        h = _lbfgs_log(bestH, 80, sub, fg=fg)
        r = R_of(h)
        if r > bestRH + 1e-14:
            bestH, bestRH = h.copy(), r
        print("  cvar a=%.3f R=%.7f (best %.7f)" % (alpha, r, bestRH))

    # ---- Strategy B: p-norm ladder with a finer schedule ----
    ladder = (2, 4, 8, 16, 32, 64, 128, 256)
    it = 0
    while time.process_time() < deadline - 3.0:
        improved = False
        for p in ladder:
            if time.process_time() >= deadline - 2.5:
                break
            sub = min(deadline - 1.5, time.process_time() + 3.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_log(bestH, 80, sub, fg=fg)
            r = R_of(h)
            if r > bestRH + 1e-14:
                bestH, bestRH = h.copy(), r
                improved = True

        # Peak-local block polish with plain max objective
        if time.process_time() < deadline - 2.0:
            lo, hi = _peak_region(bestH, tol=0.9995)
            span = hi - lo
            pad = max(256, int(span * 0.5))
            lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
            if hi2 > lo2:
                free = np.arange(lo2, hi2 + 1)
                sub = min(deadline - 1.0, time.process_time() + 3.0)
                hp = _lbfgs_block(bestH, free, 120, sub, fg=_fun_grad_max)
                rp = R_of(hp)
                if rp > bestRH + 1e-14:
                    bestH, bestRH = hp.copy(), rp
                    improved = True

        print("  iter %d p-ladder done R=%.7f" % (it, bestRH))
        it += 1
        if not improved and time.process_time() > deadline - 5.0:
            break

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

