def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


# ---- block-level machinery ----

def _coarsen(h, K):
    """Mass-preserving coarsen to K bins. Returns v (log heights) and m."""
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, N, K + 1)
    masses = np.interp(edges, np.arange(N + 1), c)
    block_mass = np.diff(masses)
    m = N // K
    v = np.log(np.clip(block_mass / m, 1e-300, None))
    return v, m


def _expand(v, m):
    return np.repeat(np.exp(v), m)


def _R_block(v, m):
    return R_of(_expand(v, m))


def _grad_block(v, m):
    h = _expand(v, m)
    val, g = _fun_grad_tie(h)
    # gradient of val wrt v: sum over block of g_h * h
    K = v.size
    gv = np.zeros(K)
    for k in range(K):
        sl = g[k * m:(k + 1) * m]
        hs = h[k * m:(k + 1) * m]
        gv[k] = np.sum(sl * hs)
    return val, gv


def _hess_block(v, m, gv0):
    K = v.size
    H = np.zeros((K, K))
    eps = 1e-6
    for j in range(K):
        vp = v.copy(); vp[j] += eps
        vm = v.copy(); vm[j] -= eps
        _, gp = _grad_block(vp, m)
        _, gm = _grad_block(vm, m)
        H[:, j] = (gp - gm) / (2 * eps)
    H = 0.5 * (H + H.T)
    return H


def _newton_block(v, m, deadline, max_iter=60, verbose=True):
    """Trust-region Newton on v (log-heights) maximizing R_block."""
    v = v.copy()
    R = _R_block(v, m)
    lam = 1e-3
    for it in range(max_iter):
        if time.process_time() > deadline:
            break
        _, g = _grad_block(v, m)
        gnorm = np.linalg.norm(g)
        if gnorm < 1e-13:
            if verbose:
                print("  newton conv it=%d |g|=%.2e R=%.12f" % (it, gnorm, R))
            break
        H = _hess_block(v, m, g)
        # try to solve (H+lam I) p = -g
        accepted = False
        for _ in range(30):
            try:
                A = H + lam * np.eye(v.size)
                p = np.linalg.solve(A, -g)
            except np.linalg.LinAlgError:
                lam *= 10.0
                continue
            pnorm = np.linalg.norm(p)
            # cap step
            if pnorm > 2.0:
                p = p * (2.0 / pnorm)
            vn = v + p
            Rn = _R_block(vn, m)
            pred = -g @ p - 0.5 * p @ H @ p
            actual = Rn - R
            if actual > 0:
                ratio = actual / pred if pred > 1e-300 else 1.0
                if ratio > 0.25:
                    lam = max(lam * 0.5, 1e-12)
                else:
                    lam = min(lam * 2.0, 1e6)
                v = vn; R = Rn
                accepted = True
                break
            else:
                lam *= 4.0
                if lam > 1e8:
                    break
        if verbose:
            print("  newton it=%d |g|=%.2e lam=%.1e R=%.12f acc=%s"
                  % (it, gnorm, lam, R, accepted))
        if not accepted:
            break
        if np.linalg.norm(p) < 1e-12:
            break
    return v, R


def _saddle_escape(v, m, deadline, R_cur, verbose=True):
    """Try escaping along negative-curvature directions of the Hessian."""
    _, g = _grad_block(v, m)
    H = _hess_block(v, m, g)
    w, V = np.linalg.eigh(H)
    if verbose:
        print("  hess eig min=%.3e max=%.3e" % (w[0], w[-1]))
    best_v = v; best_R = R_cur
    if w[0] >= -1e-9:
        return best_v, best_R
    for delta in (1e-4, 1e-3, 1e-2, 1e-1):
        if time.process_time() > deadline:
            break
        for sign in (1.0, -1.0):
            vn = v + sign * delta * V[:, 0]
            Rn = _R_block(vn, m)
            if Rn > best_R:
                vn2, Rn2 = _newton_block(vn, m, deadline, max_iter=40,
                                         verbose=False)
                if Rn2 > best_R:
                    best_v = vn2; best_R = Rn2
                    if verbose:
                        print("  saddle escape delta=%.0e sign=%+.0f R=%.12f"
                              % (delta, sign, best_R))
    return best_v, best_R


def _split_blocks(v):
    """Split each block into two equal halves (K -> 2K)."""
    return np.repeat(v, 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    alt_best = best.copy()
    altR = bestR

    # ---- Block-Newton experiment ----
    N = best.size
    K = 32
    if N % K == 0:
        v, m = _coarsen(best, K)
        hrep = _expand(v, m)
        Rrep = R_of(hrep)
        print("coarsen K=%d m=%d R(np.repeat)=%.12f" % (K, m, Rrep))

        for Kcur in (32, 64, 128):
            if time.process_time() > deadline - 5.0:
                break
            if Kcur == 32:
                vc = v.copy()
            else:
                vc = _split_blocks(vc)
            mc = N // Kcur
            if mc * Kcur != N:
                continue
            Rc = _R_block(vc, mc)
            print("start K=%d R=%.12f" % (Kcur, Rc))
            vc, Rc = _newton_block(vc, mc, deadline - 4.0, max_iter=80)
            print("after newton K=%d R=%.12f" % (Kcur, Rc))
            # saddle escapes
            for _ in range(6):
                if time.process_time() > deadline - 4.0:
                    break
                vn, Rn = _saddle_escape(vc, mc, deadline - 4.0, Rc)
                if Rn > Rc + 1e-14:
                    vc, Rc = vn, Rn
                else:
                    break
            # rasterise and check
            hc = _rescale(_expand(vc, mc))
            rc = R_of(hc)
            if rc > bestR + 1e-15:
                best = hc; bestR = rc
                print("block-Newton improved R=%.12f (K=%d)" % (bestR, Kcur))
            if rc > altR:
                alt_best = hc.copy(); altR = rc

    # ---- polish with full L-BFGS on the finest grid ----
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    alt = alt_best if altR > 0 else best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    """Objective: -log(num) + 2 log(s) + log(Lmax). Gradient wrt h."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _lbfgs(h0, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad(hh)
        return val, g[pos] * hh[pos]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _prolong(h, N):
    h = np.asarray(h, dtype=float)
    n = len(h)
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    x = np.linspace(0, total, N + 1)
    out = np.interp(x, c, np.linspace(0, n, n + 1))
    out = np.diff(out)
    return np.maximum(out, 0.0)


def _report(tag, h):
    try:
        r = R_of(h)
        L = _knots(h)
        Lmax = L.max()
        print("%s R=%.6f N=%d zero=%.3f max/mean=%.2f w1=%.3f argmax=%.3f" % (
            tag, r, len(h), np.mean(h == 0),
            h.max() / max(h.mean(), 1e-12),
            np.mean(L > 0.99 * Lmax),
            np.argmax(L) / (len(L) - 1)))
    except Exception:
        pass


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.90 * budget_seconds

    best_h = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best_h = s.copy()
            best_R = R_of(s)
            _report("start", best_h)

    # Seed: if no start, use a smooth bump
    if best_h is None:
        N0 = 512
        x = np.linspace(0, 1, N0)
        best_h = np.exp(-((x - 0.5) ** 2) / (2 * 0.12 ** 2))
        best_R = R_of(best_h)

    # Main loop: progressively escalate N, polish each time, keep improving.
    # The key insight from the strong program p3170: the "tie" gradient
    # (average over all near-max knots) plus L-BFGS in log-space works well.
    # We escalate through a ladder of resolutions, always widening the
    # peak window so the flat top can grow.
    ladder = [1024, 2048, 4096, 8192, 16384, 32768]

    h = best_h.copy()
    for N in ladder:
        if time.process_time() > deadline - 1.0:
            break
        if len(h) != N:
            h = _prolong(h, N)
        # several polish passes at this resolution
        for _ in range(3):
            if time.process_time() > deadline - 1.0:
                break
            h2 = _lbfgs(h, deadline, maxiter=300)
            r2 = R_of(h2)
            if r2 > R_of(h) + 1e-12:
                h = h2
            else:
                break
        r = R_of(h)
        if r > best_R:
            best_R = r
            best_h = h.copy()
        _report("N=%d" % N, h)

    # Final high-resolution polish at the largest feasible N
    if time.process_time() < deadline - 0.5:
        # Try to push N higher if budget allows
        for N in [65536, 131072]:
            if time.process_time() > deadline - 2.0:
                break
            h2 = _prolong(best_h, N)
            h2 = _lbfgs(h2, deadline, maxiter=200)
            r2 = R_of(h2)
            if r2 > best_R:
                best_R = r2
                best_h = h2
                _report("N=%d" % N, h2)

    if best_h is None or best_h.sum() <= 0 or not np.all(np.isfinite(best_h)):
        best_h = np.ones(50)
    best_h = np.maximum(best_h, 0.0)

    _report("final", best_h)
    print("CPU %.1f s" % (time.process_time() - t0))

    start_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            start_R = R_of(s)

    if start_R > best_R:
        return {"best": np.asarray(start, dtype=float), "alternative": best_h}
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_final(best, bestR, deadline):
    for pad in [0.10, 0.06, 0.04]:
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
        r2 = R_of(ht2)
        if r2 > bestR + 1e-14:
            best, bestR = ht2.copy(), r2
    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
    return best, bestR


def _fold_up(best, bestR, deadline, target_R, rounds=6):
    """Repeated 2x upsample-refine-fold, keeping the best folded result.
    This is the main 'finer discretisation' search, done many more rounds
    with a per-round time slice driven by the remaining budget."""
    N0 = best.size
    rnd = 0
    while time.process_time() < deadline - 2.0 and N0 >= 8 and rnd < rounds:
        rnd += 1
        now = time.process_time()
        slice_dl = min(deadline - 1.0, now + max(1.5, (deadline - now) / (rounds - rnd + 1)))
        if slice_dl <= now + 0.5:
            break
        try:
            xo = np.arange(N0, dtype=float)
            xn = np.arange(2 * N0, dtype=float) * 0.5
            u = np.interp(xn, xo, best)
            u = _rescale(u)
            u = _lbfgs_all_pos(u, 200, slice_dl - 0.3, beta=1e6)
            if time.process_time() < slice_dl - 0.4:
                u = _lbfgs_all_pos(u, 200, slice_dl - 0.3, beta=1e7)
            if time.process_time() < slice_dl - 0.4:
                win = _peak_window(u, pad_frac=0.08, extra=256)
                u = _lbfgs_block(u, win, 200, slice_dl - 0.3, beta=1e7)
            h2 = _rescale(0.5 * (u[0::2][:N0] + u[1::2][:N0]))
            if time.process_time() < slice_dl - 0.4:
                h2 = _lbfgs_all_pos(h2, 200, slice_dl - 0.3, beta=1e6)
            if time.process_time() < slice_dl - 0.4:
                h2 = _lbfgs_all_pos(h2, 200, slice_dl - 0.3, beta=1e7)
            r_fold = R_of(h2)
            print("fold%d r_fold=%.9f (best %.9f)" % (rnd, r_fold, bestR))
            if r_fold > bestR + 1e-13:
                best, bestR = h2.copy(), r_fold
                print("  fold NEW BEST R=%.9f" % bestR)
            if bestR >= target_R:
                break
        except Exception as e:
            print("fold%d exception %s" % (rnd, e))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _maybe_alt(h2, r2):
        nonlocal alt_best, alt_bestR
        if r2 > alt_bestR:
            alt_best, alt_bestR = h2.copy(), r2

    # ---- Phase A: many fold rounds on the finer grid ----
    fold_end = t0 + budget_seconds * 0.55
    best, bestR = _fold_up(best, bestR, fold_end, bestR + 1e-4, rounds=8)
    if bestR > start_bestR + 1e-13:
        origin = 'fold'

    # ---- Phase B: randomized 2N lift ----
    lift_end = min(t0 + budget_seconds * 0.75, deadline - 4.0)
    if time.process_time() < lift_end - 1.0 and best.size >= 2:
        n = best.size
        sigmas = [0.02, 0.05, 0.10, 0.03, 0.15]
        rnd = 0
        while time.process_time() < lift_end - 1.0:
            sigma = sigmas[rnd % len(sigmas)]
            rnd += 1
            now = time.process_time()
            slice_dl = min(now + 2.0, deadline - 3.0)
            if slice_dl <= now + 0.3:
                break
            try:
                d = np.clip(sigma * np.random.randn(n), -0.6, 0.6)
                u = np.empty(2 * n)
                u[0::2] = best * (1.0 + d)
                u[1::2] = best * (1.0 - d)
                u = _rescale(u)
                u = _lbfgs_all_pos(u, 120, slice_dl, beta=1e7)
                if time.process_time() < slice_dl - 0.4:
                    win = _peak_window(u, pad_frac=0.10, extra=128)
                    u = _lbfgs_block(u, win, 150, slice_dl, beta=1e7)
                h2 = _rescale(0.5 * (u[0::2] + u[1::2]))[:n]
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e6)
                if time.process_time() < slice_dl - 0.4:
                    h2 = _lbfgs_all_pos(h2, 200, slice_dl, beta=1e7)
                r_fold = R_of(h2)
                if r_fold > bestR + 1e-13:
                    best, bestR, origin = h2.copy(), r_fold, 'rnd%d' % rnd
                    print("  rnd NEW BEST R=%.9f" % bestR)
                else:
                    _maybe_alt(h2, r_fold)
