import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    w = e / Z
    softmax_val = M + (np.log(Z) + zmax) / beta
    gLf = -dq / num
    gLf += w / softmax_val
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(softmax_val)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _soft_lbfgs(h0, deadline, beta, maxiter=150):
    return _lbfgs_custom(h0, lambda h: _fun_grad_soft(h, beta),
                         deadline, maxiter=maxiter)


def _upsample(h, N):
    n = h.size
    if n == N:
        return h.copy()
    # density-preserving resample via cumulative integral (mass per cell)
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    out = np.clip(np.diff(Sb), 0.0, None)
    if out.sum() <= 0:
        return np.ones(N)
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: soft-max surrogate polishing at decreasing temperature.
    # Smoothly penalizing near-ties widens the plateau around the max,
    # which is precisely what lifts R. Re-optimise true R after each.
    def soft_phase(h, betas, per_soft, per_full):
        for beta in betas:
            if time.process_time() >= deadline - 1.0:
                return h, R_of(h)
            h = _soft_lbfgs(h, deadline, beta, maxiter=per_soft)
            h = _full_lbfgs(h, deadline, maxiter=per_full)
        return h, R_of(h)

    # Stage 1: soft-max push on the start shape to escape the current basin.
    for betas in ([200.0, 500.0, 1000.0, 2000.0],
                  [4000.0, 8000.0]):
        if time.process_time() >= deadline - 3.0:
            break
        h, r = soft_phase(best.copy(), betas, 120, 200)
        print("soft R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h, r

    # Stage 2: multiscale refinement -- upsample and refine at growing N.
    # This is the key structural move: the optimum's fine structure benefits
    # from a finer grid, and the smoother soft-max basin upsamples well.
    cur = best.copy()
    curR = bestR
    target_levels = []
    N0 = cur.size
    for fac in (1.5, 2.0, 3.0, 4.0):
        Nt = int(N0 * fac)
        if Nt <= 1000000 and Nt > N0:
            target_levels.append(Nt)
    for Nt in target_levels:
        if time.process_time() >= deadline - 3.0:
            break
        hp = _upsample(cur, Nt)
        hp = _rescale(hp)
        r = R_of(hp)
        hp = _full_lbfgs(hp, deadline, maxiter=300)
        r = R_of(hp)
        if r > curR:
            cur, curR = hp, r
            if r > bestR + 1e-12:
                best, bestR = hp, r
        print("lift N=%d R=%.7f" % (Nt, curR))

    # Stage 3: alternating soft/full polish at current resolution.
    stall = 0
    it = 0
    betas_cycle = [1000.0, 3000.0, 8000.0]
    while time.process_time() < deadline - 1.0:
        it += 1
        improved = False
        h = _full_lbfgs(best, deadline, maxiter=400)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        beta = betas_cycle[it % len(betas_cycle)]
        h = _soft_lbfgs(best, deadline, beta, maxiter=150)
        h = _full_lbfgs(h, deadline, maxiter=250)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best, "alternative": best}

