    h = np.clip(h0, 0, None)
    if h.sum() <= 0 or free.size == 0:
        return h0
    x0 = h[free].copy()

    def f(x):
        hh = h.copy()
        hh[free] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[free]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * free.size,
