    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _stats(h, label):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        print("%s: degenerate" % label)
        return
    r = Lf / mx
    near01 = float(np.mean(r >= 0.999))
    near05 = float(np.mean(r >= 0.95))
    dec = float(np.percentile(r, 10))
    print("%s R=%.9f near01=%.4f near05=%.4f p10=%.6f"
          % (label, R_of(h), near01, near05, dec))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    _stats(best, "base")

    # Phase A: full global tie polish with progressively wider windows
    # and finer beta smoothing ladder. This is where progress is made.
    for pad, extra in ((0.15, 512), (0.06, 256), (0.03, 128), (0.015, 96)):
        if time.process_time() >= deadline - 1.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=extra)
        for beta, tie in ((1e6, False), (1e7, False),
                          (0.0, True)):
            if time.process_time() >= deadline - 1.0:
                break
            ht = _lbfgs_block(best, win, 400,
                              min(deadline - 0.5,
                                  time.process_time() + 5.0),
                              beta=beta, tie=tie)
            r = R_of(ht)
            if r > bestR + 1e-15:
                best, bestR = ht.copy(), r
        print("pad=%.3f R=%.9f" % (pad, bestR))

    # Phase B: global full-array polish with the tie objective.
    if time.process_time() < deadline - 1.0:
        ht = _lbfgs_block(best, np.arange(best.size), 300,
                          min(deadline - 0.4,
                              time.process_time() + 6.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("global tie R=%.9f" % bestR)

        ht = _lbfgs_block(best, np.arange(best.size), 300,
                          min(deadline - 0.3,
                              time.process_time() + 4.0), beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("global beta R=%.9f" % bestR)

    # Phase C: last tight peak polish
    for pad in (0.02, 0.01):
        if time.process_time() >= deadline - 0.8:
            break
        win = _peak_window(best, pad_frac=pad, extra=64)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.3,
                              time.process_time() + 3.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("final pad=%.3f R=%.9f" % (pad, bestR))

    _stats(best, "final")
    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

