    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    w = e / Z
    softmax_val = M + (np.log(Z) + zmax) / beta
    gLf = -dq / num
    gLf += w / softmax_val
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(softmax_val)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _soft_lbfgs(h0, deadline, beta, maxiter=150):
    return _lbfgs_custom(h0, lambda h: _fun_grad_soft(h, beta),
                         deadline, maxiter=maxiter)


# ---- active-set polish: only near-peak knots matter ----
def _fun_grad_active(h, S):
    """Objective using only a chosen set S of knots for the max (others ignored),
    plus full L1/L2. Gradient zero outside S for the max term."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if S.size == 0:
        return 1e18, np.zeros(h.size)
    M = Lf[S].max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    idx = S[Lf[S] >= M * (1.0 - 1e-12)]
    gLf = -dq / num
    gLf[idx] += (1.0 / idx.size) / M
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    return val, grad


def _active_lbfgs(h0, deadline, pad=0.02, maxiter=200):
    """L-BFGS restricted to knots within (1-pad) of the peak; re-selected each call."""
    if time.process_time() >= deadline - 0.5:
        return h0
    Lf = _knots(h0)
    M = Lf.max()
    S = np.flatnonzero(Lf >= (1.0 - pad) * M)
    if S.size < 4:
        return h0
    return _lbfgs_custom(h0, lambda h: _fun_grad_active(h, S),
                         deadline, maxiter=maxiter)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    alt_best = best.copy()
    altR = bestR

    # Phase 1: alternate full LBFGS and active-set LBFGS on the peak knots.
    # The full objective often stalls flattening the peak; the active-set
    # restriction lets the search concentrate capacity on the dominant knots.
    stall = 0
    while time.process_time() < deadline - 1.0 and stall < 6:
        improved = False
        tlim = min(deadline - 0.5, time.process_time() + 2.5)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-14:
            best = hc; bestR = rc
            improved = True
            print("polish R=%.12f" % bestR)
        for pad in (0.05, 0.02, 0.01):
            if time.process_time() >= deadline - 0.6:
                break
            tlim = min(deadline - 0.5, time.process_time() + 1.5)
            hc = _active_lbfgs(best, tlim, pad=pad, maxiter=120)
            rc = R_of(hc)
            if rc > bestR + 1e-14:
                best = hc; bestR = rc
                improved = True
                print("active(pad=%.3f) R=%.12f" % (pad, bestR))
        if not improved:
            stall += 1
        else:
            stall = 0

    # Phase 2: soft-max surrogate polish
    if time.process_time() < deadline - 3.0:
        Lf = _knots(best)
        M = Lf.max()
        if M > 0:
            for beta_frac in (2e-3, 5e-4, 1e-4):
                if time.process_time() >= deadline - 2.0:
                    break
                beta = beta_frac / M
                tlim = min(deadline - 1.0, time.process_time() + 3.0)
                hc = _soft_lbfgs(best, tlim, beta, maxiter=200)
                rc = R_of(hc)
                if rc > bestR + 1e-15:
                    best = hc; bestR = rc
                    print("soft(beta=%.2e) R=%.12f" % (beta_frac, bestR))
                    tlim = min(deadline - 0.5, time.process_time() + 2.0)
                    hc2 = _full_lbfgs(best, tlim, maxiter=200)
                    rc2 = R_of(hc2)
                    if rc2 > bestR:
                        best = hc2; bestR = rc2
                        print("polish-after-soft R=%.12f" % bestR)

    if bestR > altR:
        alt_best = best.copy(); altR = bestR

    # Phase 3: keep alternating full/active-set until the deadline.
    stall = 0
    while time.process_time() < deadline - 0.5 and stall < 8:
        improved = False
        tlim = min(deadline - 0.3, time.process_time() + 2.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            improved = True
            print("polish R=%.12f" % bestR)
        for pad in (0.03, 0.015, 0.008):
            if time.process_time() >= deadline - 0.4:
                break
            tlim = min(deadline - 0.3, time.process_time() + 1.2)
            hc = _active_lbfgs(best, tlim, pad=pad, maxiter=100)
            rc = R_of(hc)
            if rc > bestR + 1e-15:
                best = hc; bestR = rc
                improved = True
                print("active(pad=%.3f) R=%.12f" % (pad, bestR))
        if not improved:
            stall += 1
        else:
            stall = 0

    if bestR < startR:
        best = h0.copy()
        bestR = startR
    if altR <= 0:
        alt_best = best.copy()
        altR = bestR

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full(h0, deadline, maxiter=150):
    return _lbfgs(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 200, 'maxfun': 400,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size

    # Resolution sweep upward.
    if time.process_time() < deadline - 15.0:
        for Nt in (int(N * 1.25), int(N * 1.5), int(N * 2.0)):
            if Nt <= best.size:
                continue
            if Nt > 400000:
                Nt = 400000
            if time.process_time() >= deadline - 12.0:
                break
            hp = _prolongate(best, Nt)
            hp = _rescale(hp)
            hp = _full(hp, deadline, maxiter=300)
            r = R_of(hp)
            print("grow %d -> R=%.7f" % (Nt, r))
            if r > bestR + 1e-16:
                best, bestR = hp, r

    # Soft-max sweeps to escape hard-max plateaus.
    for beta in (30.0, 80.0, 200.0, 500.0):
        if time.process_time() >= deadline - 6.0:
            break
        h = _peak_window_polish(best, deadline, pad=16)
        h = _lbfgs(h, lambda hh: _fun_grad_beta(hh, beta), deadline, maxiter=250)
        h = _full(h, deadline, maxiter=250)
        r = R_of(h)
        print("beta %.0f R=%.7f" % (beta, r))
        if r > bestR + 1e-16:
            best, bestR = h, r

    # Peak-focused polish at multiple window sizes.
    for pad in (4, 8, 16, 32, 64, 128):
        if time.process_time() >= deadline - 2.0:
            break
        h = _peak_window_polish(best, deadline, pad=pad)
        h = _full(h, deadline, maxiter=400)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("peak(pad=%d) R=%.7f" % (pad, bestR))

    # Phase exploration.
    for delta in (-0.5, -0.25, 0.25, 0.5, 1.0):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale(hp)
        if hp.sum() <= 0:
            continue
        hp = _full(hp, deadline, maxiter=500)
        r = R_of(hp)
        print("phase %+.2f R=%.7f" % (delta, r))
        if r > bestR + 1e-16:
            best, bestR = hp, r

    # Final loop: alternate full and peak polish.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _full(best, deadline, maxiter=800)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _peak_window_polish(best, deadline, pad=24)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
