    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3,
                          fg=lambda hh: _fun_grad_cvar(hh, 0.02))
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, fg=_fun_grad_tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _resample_mass(h, Np):
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    t = np.linspace(0.0, N, Np + 1)
    cp = np.interp(t, np.arange(N + 1, dtype=float), c)
    hp = (Np / N) * np.diff(cp)
    return np.clip(hp, 0.0, None)


def _refine_at_N(h, deadline, iters=800):
    h = _lbfgs_all_pos(h, iters, deadline, fg=_fun_grad_tie)
    if time.process_time() < deadline - 2.0:
        h = _peak_ladder(h, deadline - 1.0,
                         pads=(0.10, 0.06, 0.04, 0.02), iters=300)
    if time.process_time() < deadline - 0.6:
        h = _lbfgs_all_pos(h, iters // 2, deadline - 0.3, fg=_fun_grad)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N_base = best.size
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best),
             _tie_count(best)))

    # ---- primary: refine at current N with cvar/tie ladder, then try other N ----
    sweep_end = t0 + min(budget_seconds * 0.80, 48.0)

    # First, refine at the base N with cvar + tie using more iterations.
    if time.process_time() < sweep_end - 6.0:
        ht = _lbfgs_all_pos(best, 1500, sweep_end - 4.0,
                            fg=lambda hh: _fun_grad_cvar(hh, 0.01))
        if R_of(ht) > bestR + 1e-15:
            best, bestR = ht.copy(), R_of(ht)
            print("cvar refine ACCEPT R=%.9f" % bestR)
        if time.process_time() < sweep_end - 4.0:
            ht = _peak_ladder(best, sweep_end - 3.0,
                              pads=(0.10, 0.06, 0.04, 0.02), iters=400)
            if R_of(ht) > bestR + 1e-15:
                best, bestR = ht.copy(), R_of(ht)
                print("peak ladder ACCEPT R=%.9f" % bestR)

    N_list = set()
    for n in (26000, 34000, 43752, 52496, 64000, 76000, 92000):
        N_list.add(n)
    for k in (0.88, 0.95, 1.0, 1.06, 1.14):
        N_list.add(int(N_base * k))
    N_list = sorted(n for n in N_list if n != N_base and n >= 512)

    best_alt = None
    best_altR = -1.0
    sweep_it = 0

    while time.process_time() < sweep_end - 4.0:
        progressed = False
        for Np in N_list:
            if time.process_time() >= sweep_end - 4.0:
                break
            sweep_it += 1
            slice_end = min(sweep_end, time.process_time() + 5.0)
            hp = _resample_mass(best, Np)
            if hp.sum() <= 0:
                continue
            hp = _rescale(hp)
            r0 = R_of(hp)
            ht = _lbfgs_all_pos(hp, 500, slice_end - 2.0, fg=_fun_grad_tie)
            if time.process_time() < slice_end - 1.5:
                ht = _peak_ladder(ht, slice_end - 1.0,
                                  pads=(0.08, 0.05, 0.03), iters=200)
            if time.process_time() < slice_end - 0.6:
                ht = _lbfgs_all_pos(ht, 200, slice_end - 0.2, fg=_fun_grad)
            rt = R_of(ht)
            if rt > best_altR:
                best_alt, best_altR = ht.copy(), rt
            dR = rt - bestR
            accepted = rt > bestR + 1e-15
            if accepted:
                best, bestR = ht.copy(), rt
                progressed = True
            print("sweep %d N'=%d r0=%.9f dR=%+.3e %s R=%.9f"
                  % (sweep_it, Np, r0, dR, "ACCEPT" if accepted else "no gain",
                     bestR))
        if not progressed and time.process_time() > sweep_end - 4.0:
            break

    # ---- final refinement ----
    fd = t0 + budget_seconds * 0.92
    if time.process_time() < fd - 3.0:
        h_t = _refine_at_N(best, fd - 1.0, iters=1200)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL refine ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))
        else:
            print("FINAL refine no gain R=%.9f" % r_t)

    if time.process_time() < fd - 1.5:
        h_t = _lbfgs_all_pos(best, 600, fd - 0.5, fg=_fun_grad_tie)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACCEPT R=%.9f" % bestR)

    if time.process_time() < fd - 0.6:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.2, fg=_fun_grad)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACCEPT R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if best_alt is not None and best_alt.size != best.size and best_altR > startR + 1e-12:
        result["alternative"] = best_alt
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if Lm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _coarse_envelope(h, coarse=512):
    N = h.size
    if N <= coarse:
        return h.copy()
    edges = np.linspace(0, N, coarse + 1).astype(int)
    env_c = np.zeros(coarse)
    for j in range(coarse):
        a, b = edges[j], edges[j + 1]
        if b > a:
            env_c[j] = h[a:b].mean()
    centers = 0.5 * (edges[:-1] + edges[1:])
    xi = np.arange(N) + 0.5
    env = np.interp(xi, centers, env_c)
    return np.clip(env, 0, None)


def _polish(h2, slice_dl):
    active = np.flatnonzero(h2 > 0)
    if active.size == 0:
        return h2
    ht = h2
    for beta in [0.0, 1e5, 1e7]:
        if time.process_time() >= slice_dl - 0.4:
            break
        ht = _lbfgs_block(ht, active, 200, slice_dl, beta=beta)
        active = np.flatnonzero(ht > 0)
        if active.size == 0:
            break
    if time.process_time() < slice_dl - 0.4:
        win = _peak_window(ht, pad_frac=0.10, extra=128)
        win = np.intersect1d(win, np.flatnonzero(ht > 0))
        if win.size > 0:
            ht = _lbfgs_block(ht, win, 120, slice_dl, beta=1e7)
    return ht


def _refine_from(h, deadline, label=""):
    """Continuous polish: beta ladder on all active + peak window, using all time."""
    best = _rescale(np.clip(h, 0, None))
    bestR = R_of(best)
    # beta ladder
    for beta in [0.0, 1e4, 1e6, 1e8]:
        if time.process_time() >= deadline - 1.0:
            break
        active = np.flatnonzero(best > 0)
        if active.size == 0:
            break
        ht = _lbfgs_block(best, active, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
    # peak window polish
    while time.process_time() < deadline - 1.5:
        win = _peak_window(best, pad_frac=0.08, extra=128)
        win = np.intersect1d(win, np.flatnonzero(best > 0))
        if win.size == 0:
            break
        ht = _lbfgs_block(best, win, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        else:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h = _rescale(base)
        else:
            h = None
    else:
        h = None

    if h is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        h = _rescale(h)

    best = h.copy()
    bestR = R_of(best)
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # First: a direct continuous polish of the start — this is the reliable gain.
    # Reserve a slice for exploring masked variants; if polish is enough, that's fine.
    polish_end = t0 + budget_seconds * 0.55
    if time.process_time() < polish_end - 1.0:
        hp, rp = _refine_from(best, polish_end, "polish")
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("polish NEW BEST R=%.9f" % bestR)

    alt_best = None
    alt_bestR = -1.0

    # Explore masked variants from the coarse envelope of the improved best.
    env = _rescale(_coarse_envelope(best, coarse=512))
    target_mass = best.sum()

    candidates = []
    for p in [2, 4, 5, 7]:
        candidates.append(("p=%d" % p, (np.arange(N) % p) == 0))
    rng1 = np.random.RandomState(12345)
    candidates.append(("rand keep=0.34", rng1.rand(N) < 0.34))
    rng2 = np.random.RandomState(67890)
    candidates.append(("rand keep=0.70", rng2.rand(N) < 0.70))

    work_end = deadline - 4.0

    for name, mask in candidates:
        if time.process_time() >= work_end - 1.0:
            break
        now = time.process_time()
        slice_dl = min(now + 2.0, work_end)
        if slice_dl <= now + 0.3:
            break
        h2 = np.zeros(N)
        h2[mask] = env[mask]
        if h2.sum() <= 0:
            continue
        h2 = h2 * (target_mass / h2.sum())
        h2 = _rescale(h2)
        try:
            ht = _polish(h2, slice_dl)
        except Exception as e:
            print("mask %s exception %s" % (name, e))
            continue
        r = R_of(ht)
        dens = np.count_nonzero(ht) / float(N)
        print("mask %s R=%.9f (density %.3f) (best %.9f)" % (name, r, dens, bestR))
        if r > bestR + 1e-9:
            best, bestR = ht.copy(), r
            print("  mask NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # Final: spend remaining time polishing the winner.
    if time.process_time() < deadline - 1.0:
        hp, rp = _refine_from(best, deadline - 0.3, "final")
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("final NEW BEST R=%.9f" % bestR)
        elif rp > alt_bestR:
            alt_best, alt_bestR = hp, rp

    print("final R=%.9f (base %.9f, N=%d)" % (bestR, R_of(h), best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR and alt_bestR > -1:
        result["alternative"] = alt_best
    return result

