    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _coarse_envelope(h, coarse=512):
    N = h.size
    if N <= coarse:
        return h.copy()
    edges = np.linspace(0, N, coarse + 1).astype(int)
    env_c = np.zeros(coarse)
    for j in range(coarse):
        a, b = edges[j], edges[j + 1]
        if b > a:
            env_c[j] = h[a:b].mean()
    centers = 0.5 * (edges[:-1] + edges[1:])
    xi = np.arange(N) + 0.5
    env = np.interp(xi, centers, env_c)
    return np.clip(env, 0, None)


def _polish(h2, slice_dl):
    active = np.flatnonzero(h2 > 0)
    if active.size == 0:
        return h2
    ht = h2
    for beta in [0.0, 1e5, 1e7]:
        if time.process_time() >= slice_dl - 0.4:
            break
        ht = _lbfgs_block(ht, active, 200, slice_dl, beta=beta)
        active = np.flatnonzero(ht > 0)
        if active.size == 0:
            break
    if time.process_time() < slice_dl - 0.4:
        win = _peak_window(ht, pad_frac=0.10, extra=128)
        win = np.intersect1d(win, np.flatnonzero(ht > 0))
        if win.size > 0:
            ht = _lbfgs_block(ht, win, 120, slice_dl, beta=1e7)
    return ht


def _refine_from(h, deadline, label=""):
    """Continuous polish: beta ladder on all active + peak window, using all time."""
    best = _rescale(np.clip(h, 0, None))
    bestR = R_of(best)
    # beta ladder
    for beta in [0.0, 1e4, 1e6, 1e8]:
        if time.process_time() >= deadline - 1.0:
            break
        active = np.flatnonzero(best > 0)
        if active.size == 0:
            break
        ht = _lbfgs_block(best, active, 300, deadline - 0.5, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
    # peak window polish
    while time.process_time() < deadline - 1.5:
        win = _peak_window(best, pad_frac=0.08, extra=128)
        win = np.intersect1d(win, np.flatnonzero(best > 0))
        if win.size == 0:
            break
        ht = _lbfgs_block(best, win, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
        else:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h = _rescale(base)
        else:
            h = None
    else:
        h = None

    if h is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        h = _rescale(h)

    best = h.copy()
    bestR = R_of(best)
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # First: a direct continuous polish of the start — this is the reliable gain.
    # Reserve a slice for exploring masked variants; if polish is enough, that's fine.
    polish_end = t0 + budget_seconds * 0.55
    if time.process_time() < polish_end - 1.0:
        hp, rp = _refine_from(best, polish_end, "polish")
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("polish NEW BEST R=%.9f" % bestR)

    alt_best = None
    alt_bestR = -1.0

    # Explore masked variants from the coarse envelope of the improved best.
    env = _rescale(_coarse_envelope(best, coarse=512))
    target_mass = best.sum()

    candidates = []
    for p in [2, 4, 5, 7]:
        candidates.append(("p=%d" % p, (np.arange(N) % p) == 0))
    rng1 = np.random.RandomState(12345)
    candidates.append(("rand keep=0.34", rng1.rand(N) < 0.34))
    rng2 = np.random.RandomState(67890)
    candidates.append(("rand keep=0.70", rng2.rand(N) < 0.70))

    work_end = deadline - 4.0

    for name, mask in candidates:
        if time.process_time() >= work_end - 1.0:
            break
        now = time.process_time()
        slice_dl = min(now + 2.0, work_end)
        if slice_dl <= now + 0.3:
            break
        h2 = np.zeros(N)
        h2[mask] = env[mask]
        if h2.sum() <= 0:
            continue
        h2 = h2 * (target_mass / h2.sum())
        h2 = _rescale(h2)
        try:
            ht = _polish(h2, slice_dl)
        except Exception as e:
            print("mask %s exception %s" % (name, e))
            continue
        r = R_of(ht)
        dens = np.count_nonzero(ht) / float(N)
        print("mask %s R=%.9f (density %.3f) (best %.9f)" % (name, r, dens, bestR))
        if r > bestR + 1e-9:
            best, bestR = ht.copy(), r
            print("  mask NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # Final: spend remaining time polishing the winner.
    if time.process_time() < deadline - 1.0:
        hp, rp = _refine_from(best, deadline - 0.3, "final")
        if rp > bestR + 1e-14:
            best, bestR = hp, rp
            print("final NEW BEST R=%.9f" % bestR)
        elif rp > alt_bestR:
            alt_best, alt_bestR = hp, rp

    print("final R=%.9f (base %.9f, N=%d)" % (bestR, R_of(h), best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR and alt_bestR > -1:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    """Optimize a soft max via mean of top-alpha fraction of knots.
    Drives many knots near the maximum instead of a single point."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (S.size * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_plateau(h, alpha, eps):
    """CVaR-like but penalize deviation above the CVaR mean (plateau shaping)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (S.size * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    # penalize spikes above the plateau mean
    excess = np.clip(Lf - cm * (1.0 + eps), 0.0, None)
    if excess.sum() > 0:
        val += 1e-3 * np.sum(excess * excess)
        dpen = 2e-3 * excess
        dpen[Lf <= cm * (1.0 + eps)] = 0.0
        grad = grad + _backprop(dpen, h) / num
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        fg = (lambda hh, b=beta: _fun_grad_beta(hh, b))
        cand = _lbfgs_log(cur, maxiter=maxiter, deadline=deadline, fg=fg)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _cvar_polish(h, deadline, rcur, alphas=(0.05, 0.02, 0.01, 0.005)):
    """Novel move: push many knots near the peak using CVaR of the knots.
    This flattens the top of f*f, increasing ||f*f||_2^2 relative to ||f*f||_inf."""
    for a in alphas:
        if time.process_time() >= deadline - 1.0:
            break
        fg = (lambda hh, aa=a: _fun_grad_cvar(hh, aa))
        cand = _lbfgs_log(h, maxiter=200, deadline=deadline, fg=fg)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _plateau_polish(h, deadline, rcur):
    """Plateau-shaping objective: reward CVaR while penalizing spikes."""
    for a, eps in ((0.03, 0.02), (0.015, 0.01), (0.008, 0.005)):
        if time.process_time() >= deadline - 1.0:
            break
        fg = (lambda hh, aa=a, ee=eps: _fun_grad_plateau(hh, aa, ee))
        cand = _lbfgs_log(h, maxiter=200, deadline=deadline, fg=fg)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_near_peak(h, deadline, rcur, iters=4, maxiter=250):
    for k in range(iters):
        if time.process_time() >= deadline - 1.0:
            break
        Lf = _knots(h)
        m = int(np.argmax(Lf))
        n = h.size
        c = m // 2
        half = max(16, int(0.30 * n))
        lo_h = max(0, c - half)
        hi_h = min(n - 1, c + half)
        free = np.arange(lo_h, hi_h + 1)
        beta = 64.0 * (2 ** k)
        fg = (lambda hh, b=beta: _fun_grad_beta(hh, b))
        sub = h.copy()
        # mask outside free
        mask = np.zeros(n, dtype=bool)
        mask[free] = True
        cand = _lbfgs_log_masked(sub, mask, maxiter, deadline, fg)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _lbfgs_log_masked(h0, mask, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.flatnonzero(mask & (h > 1e-13 * h.max()))
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = h.copy()
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        N0 = 128
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(h)
        best_r = R_of(best)
        start_r = best_r

    alt = None
    alt_r = -1.0

    # ---- Novel move: CVaR / plateau shaping. This attacks the real bottleneck:
    # the maximum of f*f is a single sharp peak, but R improves if many knots
    # reach close to that peak. CVaR objective flattens the top.
    if time.process_time() < deadline - 8:
        cand, r = _cvar_polish(best, deadline, best_r)
        if r > best_r:
            best, best_r = cand, r
        else:
            alt, alt_r = cand, r
        print("cvar R=%.6f" % best_r)

    if time.process_time() < deadline - 6:
        cand, r = _plateau_polish(best, deadline, best_r)
        if r > best_r:
            best, best_r = cand, r
        elif alt is None or r > alt_r:
            alt, alt_r = cand, r
        print("plateau R=%.6f" % best_r)

    # Sharpen with beta homotopy.
    if time.process_time() < deadline - 5:
        h_sharp, r_sharp = _homotopy(
            best, (64, 256, 1024, 4096), 180, deadline)
        if r_sharp > best_r:
            best, best_r = h_sharp, r_sharp
        print("sharpen R=%.6f" % best_r)

    if time.process_time() < deadline - 4:
        h_pk, r_pk = _refine_near_peak(best, deadline, best_r, iters=3, maxiter=200)
        if r_pk > best_r:
            best, best_r = h_pk, r_pk
        print("peak-refine R=%.6f" % best_r)

    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        seed = best.copy()
        rng = np.random.default_rng(it * 7919)
        noise = 1.0 + 0.04 * rng.standard_normal(seed.size)
        seed = _rescale(np.clip(seed * noise, 0.0, None))

        cand, r = _homotopy(seed, (128, 512, 2048), 120, deadline)
        if r > best_r:
            best, best_r = cand, r
        elif alt is None or r > alt_r:
            alt, alt_r = cand, r

        cand, r = _cvar_polish(best, deadline, best_r, alphas=(0.03, 0.01, 0.005))
        if r > best_r:
            best, best_r = cand, r

        if it % 2 == 0:
            cand, r = _plateau_polish(best, deadline, best_r)
            if r > best_r:
                best, best_r = cand, r

        if it % 3 == 0:
            cand = _lbfgs_log(best, maxiter=250, deadline=deadline)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
            print("  it#%d R=%.6f (start %.6f)" % (it, best_r, start_r))

    best = _rescale(best)
    nz = np.flatnonzero(best > 1e-14 * best.max())
    if nz.size > 0:
        lo = max(0, nz[0] - 2)
        hi = min(best.size, nz[-1] + 3)
        best = _rescale(best[lo:hi])

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None:
        if start_r >= best_r:
            if alt is not None and alt_r > start_r:
                return {"best": start_arr, "alternative": alt}
            return {"best": start_arr, "alternative": best}
        if alt is not None and alt_r > 0 and alt_r < best_r:
            return {"best": best, "alternative": alt}
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    """Optimize a soft max via mean of top-alpha fraction of knots.
    Drives many knots near the maximum instead of a single point."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (S.size * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_plateau(h, alpha, eps):
    """CVaR-like but penalize deviation above the CVaR mean (plateau shaping)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (S.size * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    # penalize spikes above the plateau mean
    excess = np.clip(Lf - cm * (1.0 + eps), 0.0, None)
    if excess.sum() > 0:
        val += 1e-3 * np.sum(excess * excess)
        dpen = 2e-3 * excess
        dpen[Lf <= cm * (1.0 + eps)] = 0.0
        grad = grad + _backprop(dpen, h) / num
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        fg = (lambda hh, b=beta: _fun_grad_beta(hh, b))
        cand = _lbfgs_log(cur, maxiter=maxiter, deadline=deadline, fg=fg)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _cvar_polish(h, deadline, rcur, alphas=(0.05, 0.02, 0.01, 0.005)):
    """Novel move: push many knots near the peak using CVaR of the knots.
    This flattens the top of f*f, increasing ||f*f||_2^2 relative to ||f*f||_inf."""
    for a in alphas:
        if time.process_time() >= deadline - 1.0:
            break
        fg = (lambda hh, aa=a: _fun_grad_cvar(hh, aa))
        cand = _lbfgs_log(h, maxiter=200, deadline=deadline, fg=fg)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _plateau_polish(h, deadline, rcur):
    """Plateau-shaping objective: reward CVaR while penalizing spikes."""
    for a, eps in ((0.03, 0.02), (0.015, 0.01), (0.008, 0.005)):
        if time.process_time() >= deadline - 1.0:
            break
        fg = (lambda hh, aa=a, ee=eps: _fun_grad_plateau(hh, aa, ee))
        cand = _lbfgs_log(h, maxiter=200, deadline=deadline, fg=fg)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_near_peak(h, deadline, rcur, iters=4, maxiter=250):
    for k in range(iters):
        if time.process_time() >= deadline - 1.0:
            break
        Lf = _knots(h)
        m = int(np.argmax(Lf))
        n = h.size
        c = m // 2
        half = max(16, int(0.30 * n))
        lo_h = max(0, c - half)
        hi_h = min(n - 1, c + half)
        free = np.arange(lo_h, hi_h + 1)
        beta = 64.0 * (2 ** k)
        fg = (lambda hh, b=beta: _fun_grad_beta(hh, b))
        sub = h.copy()
        # mask outside free
        mask = np.zeros(n, dtype=bool)
        mask[free] = True
        cand = _lbfgs_log_masked(sub, mask, maxiter, deadline, fg)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _lbfgs_log_masked(h0, mask, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.flatnonzero(mask & (h > 1e-13 * h.max()))
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = h.copy()
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        N0 = 128
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best = _rescale(h)
        best_r = R_of(best)
        start_r = best_r

    alt = None
    alt_r = -1.0

    # ---- Novel move: CVaR / plateau shaping. This attacks the real bottleneck:
    # the maximum of f*f is a single sharp peak, but R improves if many knots
    # reach close to that peak. CVaR objective flattens the top.
    if time.process_time() < deadline - 8:
        cand, r = _cvar_polish(best, deadline, best_r)
        if r > best_r:
            best, best_r = cand, r
        else:
            alt, alt_r = cand, r
        print("cvar R=%.6f" % best_r)

    if time.process_time() < deadline - 6:
        cand, r = _plateau_polish(best, deadline, best_r)
        if r > best_r:
            best, best_r = cand, r
        elif alt is None or r > alt_r:
            alt, alt_r = cand, r
        print("plateau R=%.6f" % best_r)

    # Sharpen with beta homotopy.
    if time.process_time() < deadline - 5:
        h_sharp, r_sharp = _homotopy(
            best, (64, 256, 1024, 4096), 180, deadline)
        if r_sharp > best_r:
            best, best_r = h_sharp, r_sharp
        print("sharpen R=%.6f" % best_r)

    if time.process_time() < deadline - 4:
        h_pk, r_pk = _refine_near_peak(best, deadline, best_r, iters=3, maxiter=200)
        if r_pk > best_r:
            best, best_r = h_pk, r_pk
        print("peak-refine R=%.6f" % best_r)

    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        seed = best.copy()
        rng = np.random.default_rng(it * 7919)
        noise = 1.0 + 0.04 * rng.standard_normal(seed.size)
        seed = _rescale(np.clip(seed * noise, 0.0, None))

        cand, r = _homotopy(seed, (128, 512, 2048), 120, deadline)
        if r > best_r:
            best, best_r = cand, r
        elif alt is None or r > alt_r:
            alt, alt_r = cand, r

        cand, r = _cvar_polish(best, deadline, best_r, alphas=(0.03, 0.01, 0.005))
        if r > best_r:
            best, best_r = cand, r

        if it % 2 == 0:
            cand, r = _plateau_polish(best, deadline, best_r)
            if r > best_r:
                best, best_r = cand, r

        if it % 3 == 0:
            cand = _lbfgs_log(best, maxiter=250, deadline=deadline)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
            print("  it#%d R=%.6f (start %.6f)" % (it, best_r, start_r))

    best = _rescale(best)
    nz = np.flatnonzero(best > 1e-14 * best.max())
    if nz.size > 0:
        lo = max(0, nz[0] - 2)
        hi = min(best.size, nz[-1] + 3)
        best = _rescale(best[lo:hi])

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None:
        if start_r >= best_r:
            if alt is not None and alt_r > start_r:
                return {"best": start_arr, "alternative": alt}
            return {"best": start_arr, "alternative": best}
        if alt is not None and alt_r > 0 and alt_r < best_r:
            return {"best": best, "alternative": alt}
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=0.0, tie=False):
    return _lbfgs_block(h0, np.arange(h0.size), maxiter, deadline,
                        beta=beta, tie=tie)


def _prolong(h, Nnew):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0:
        return np.ones(Nnew)
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h))) / s
    u = np.linspace(0.0, 1.0, N + 1)
    v = np.linspace(0.0, 1.0, Nnew + 1)
    newC = np.interp(v, u, C)
    out = np.diff(newC)
    return _rescale(np.clip(out, 0, None))


def _warp(h, gamma):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    s = h.sum()
    if s <= 0:
        return h
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h))) / s
    u = np.linspace(0.0, 1.0, N + 1)
    v = u ** gamma
    newC = np.interp(v, u, C)
    out = np.diff(newC)
    return _rescale(np.clip(out, 0, None))


def _sharpen(h, bestR, deadline):
    for beta in (1e6, 1e7, 0.0):
        if time.process_time() >= deadline - 0.3:
            break
        ht = _lbfgs_all(h, 200, deadline, beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            h, bestR = ht.copy(), r
    return h, bestR


def _smooth(h, k):
    if k <= 1:
        return h
    kern = np.ones(k) / k
    out = np.convolve(h, kern, mode='same')
    return _rescale(np.clip(out, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_best, alt_bestR = None, 0.0

    # ---- New idea: multi-scale refinement ----
    # The start is already near a local optimum.  We try to escape by
    # refining on a *coarser* representation (downsample then upsample),
    # which perturbs the fine structure while keeping the coarse shape.
    # Then upsample 2x for more DoF.
    for fact in (2, 3):
        if time.process_time() >= deadline - 5.0:
            break
        if best.size // fact < 64:
            continue
        # downsample by averaging
        N = best.size
        Nd = (N // fact) * fact
        hd = best[:Nd].reshape(-1, fact).mean(axis=1)
        hd = _rescale(hd)
        # upsample back to best.size via prolong
        hu = _prolong(hd, N)
        ru = R_of(hu)
        slice_end = min(deadline - 2.0,
                        time.process_time() + budget_seconds * 0.08)
        hu, ru = _sharpen(hu, ru, slice_end)
        if ru > bestR + 1e-13:
            best, bestR = hu.copy(), ru
        if alt_best is None or ru > alt_bestR:
            alt_best, alt_bestR = hu, ru
        print("down/up %d R=%.7f" % (fact, ru))

    # ---- Upsample 2x and refine ----
    if time.process_time() < deadline - 3.0 and best.size < 500000:
        hu = _prolong(best, min(best.size * 2, 999000))
        ru = R_of(hu)
        slice_end = min(deadline - 1.0,
                        time.process_time() + budget_seconds * 0.20)
        hu, ru = _sharpen(hu, ru, slice_end)
        if time.process_time() < deadline - 1.0:
            slice_end = min(deadline - 1.0,
                            time.process_time() + budget_seconds * 0.10)
            hu, ru = _sharpen(hu, ru, slice_end)
        if ru > bestR + 1e-13:
            best, bestR = hu.copy(), ru
        if alt_best is None or ru > alt_bestR:
            alt_best, alt_bestR = hu, ru
        print("upsampled R=%.7f (N=%d)" % (ru, hu.size))

    # ---- Warp-based basin escape ----
    for gamma in (0.98, 1.02):
        if time.process_time() >= deadline - 2.5:
            break
        hw = _warp(best, gamma)
        rw = R_of(hw)
        slice_end = min(deadline - 1.0,
                        time.process_time() + budget_seconds * 0.05)
        hw, rw = _sharpen(hw, rw, slice_end)
        if rw > bestR + 1e-13:
            best, bestR = hw.copy(), rw
        if alt_best is None or rw > alt_bestR:
            alt_best, alt_bestR = hw, rw
    print("warp R=%.7f (N=%d)" % (bestR, best.size))

    # final polish
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all(best, 3000, deadline - 0.3, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    if alt_best is not None:
        print("alt R=%.7f (N=%d)" % (alt_bestR, alt_best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_best is not None and alt_bestR > start_bestR - 0.05:
        out["alternative"] = alt_best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    w = e / Z
    softmax_val = M + (np.log(Z) + zmax) / beta
    gLf = -dq / num
    gLf += w / softmax_val
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(softmax_val)
    return val, grad


def _fun_grad_cap(h, C, rho):
    """Quadratic barrier above ceiling C on the knot values."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    gLf = -dq / num
    v = np.maximum(Lf - C, 0.0)
    gLf = gLf + 2.0 * rho * v
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + rho * np.sum(v * v)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _soft_lbfgs(h0, deadline, beta, maxiter=150):
    return _lbfgs_custom(h0, lambda h: _fun_grad_soft(h, beta),
                         deadline, maxiter=maxiter)


def _cap_lbfgs(h0, deadline, C, rho, maxiter=150):
    return _lbfgs_custom(h0, lambda h: _fun_grad_cap(h, C, rho),
                         deadline, maxiter=maxiter)


def _fracs(h):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(Lf >= M * 0.999),
            np.mean(Lf >= M * 0.99),
            np.mean(Lf >= M * 0.95))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Initial exact-R polish of the start
    while time.process_time() < deadline - 20.0:
        tlim = min(deadline - 15.0, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    # Ceiling continuation phase
    alt_best = best.copy()
    altR = bestR
    last_capped = best.copy()
    ceiling_gain = False

    deltas = (1e-2, 5e-3, 2e-3, 1e-3, 3e-4, 1e-4)
    rhos = (1e2, 1e4, 1e6, 1e8)

    for delta in deltas:
        if time.process_time() >= deadline - 13.0:
            break
        # rescale so current knot max = 1
        Lf = _knots(best)
        M = Lf.max()
        if M <= 0:
            break
        cur = best / np.sqrt(M)  # keep knot max = 1
        for rho in rhos:
            if time.process_time() >= deadline - 13.0:
                break
            Lf2 = _knots(cur)
            C = (1.0 - delta) * Lf2.max()
            tlim = min(deadline - 12.0, time.process_time() + 2.5)
            hc = _cap_lbfgs(cur, tlim, C, rho, maxiter=200)
            # always follow with exact-R tie polish
            tlim2 = min(deadline - 11.0, time.process_time() + 2.0)
            hp = _full_lbfgs(hc, tlim2, maxiter=200)
            rp = R_of(hp)
            last_capped = hc.copy()
            f01, f1, f5 = _fracs(hp)
            print("cap d=%.0e rho=%.0e R=%.12f (%.4f/%.4f/%.4f)"
                  % (delta, rho, rp, f01, f1, f5))
            if rp > bestR + 1e-15:
                best = hp; bestR = rp
                ceiling_gain = True
                print("  NEW best R=%.12f" % bestR)
            # also track capped state itself as alternative if its R is high
            rc_cap = R_of(hc)
            if rc_cap > altR:
                alt_best = hc.copy(); altR = rc_cap

    # beta-sharpening pass if ceiling phase gained
    if ceiling_gain and time.process_time() < deadline - 12.0:
        Lf = _knots(best)
        M = Lf.max()
        if M > 0:
            beta = 5e-4 / M
            tlim = min(deadline - 11.0, time.process_time() + 3.0)
            hc = _soft_lbfgs(best, tlim, beta, maxiter=200)
            tlim2 = min(deadline - 10.0, time.process_time() + 2.0)
            hp = _full_lbfgs(hc, tlim2, maxiter=200)
            rp = R_of(hp)
            if rp > bestR:
                best = hp; bestR = rp
                print("soft-sharpen R=%.12f" % bestR)

    # Final phase: repeated exact-R tie polishes
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("final polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    if altR <= 0:
        alt_best = last_capped

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _smooth_perturb(h, rng, scale):
    n = h.size
    k = max(4, n // 200)
    x = rng.standard_normal(n + k)
    kern = np.ones(k) / k
    sm = np.convolve(x, kern, mode='same')[:n]
    sm = sm / (np.std(sm) + 1e-12)
    return h * np.exp(scale * sm)


def _refine(h, deadline, rounds=3):
    """Full exact + window polish loop; returns best h found."""
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        h2 = _lbfgs_block(best, np.arange(best.size), 400, deadline)
        r2 = R_of(h2)
        if r2 > bestR:
            best, bestR = h2, r2
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, tol=0.9995, pad_frac=0.5, extra=64)
        h3 = _lbfgs_block(best, free, 300, deadline)
        r3 = R_of(h3)
        if r3 > bestR:
            best, bestR = h3, r3
        if r3 <= r2 + 1e-15 and r2 <= bestR + 1e-15:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(20240517)

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
    if best is None:
        N = 4096
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    start_best = best.copy()
    start_R = bestR
    alt = None
    altR = 0.0

    # Phase A: exponential-smoothed max (beta) polish on full problem, then exact.
    for beta in (30.0, 100.0, 300.0):
        if time.process_time() >= deadline - 3.0:
            break
        h = _lbfgs_block(best, np.arange(best.size), 400, deadline, beta=beta)
        h = _lbfgs_block(h, np.arange(h.size), 300, deadline)
        r = R_of(h)
        print("beta=%.0f R=%.7f" % (beta, r))
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r

    # Phase B: peak-window polish (exact) with growing windows.
    for tol, pf, ex in ((0.9995, 0.40, 64), (0.999, 0.6, 128), (0.99, 1.0, 256)):
        if time.process_time() >= deadline - 2.0:
            break
        free = _peak_window(best, tol=tol, pad_frac=pf, extra=ex)
        h = _lbfgs_block(best, free, 400, deadline)
        r = R_of(h)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.4f) R=%.7f" % (tol, bestR))

    # Phase C: basin hopping with smooth perturbations, refine each candidate.
    hop = 0
    while time.process_time() < deadline - 3.0 and hop < 60:
        hop += 1
        scale = 0.008 + 0.03 * ((hop * 7) % 5) / 4.0
        h = _smooth_perturb(best, rng, scale)
        h = _rescale(h)
        h, r = _refine(h, deadline, rounds=2)
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("hop %d R=%.7f" % (hop, bestR))

    # Phase D: dedicated full+window refinement until the very end.
    while time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, rounds=2)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and altR > 0 and bestR <= start_R + 1e-15:
        return {"best": start_best, "alternative": alt}
    return best

