        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.1)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-9)))


def _resample(h, n):
    """Resample step function h to n steps, preserving mass."""
    m = h.size
    if m == n:
        return h.copy()
    # treat as piecewise-constant function on [0,1]; compute new step averages
    # edges old: i/m, new: j/n
    old_edges = np.arange(m + 1) / m
    new_edges = np.arange(n + 1) / n
    # cumulative integral at new edges via searchsorted
    cum = np.concatenate(([0.0], np.cumsum(h)))
    # integral of h from 0 to t (t in [0,1]) = (cum[i] + h[i]*(t - i/m)) if i/m<=t<(i+1)/m
    idx = np.searchsorted(old_edges, new_edges, side='right') - 1
    idx = np.clip(idx, 0, m - 1)
    frac = (new_edges - old_edges[idx]) * m
    vals = cum[idx] + h[idx] * frac
    # new step averages: (F(new_edge[j+1]) - F(new_edge[j])) * n (to keep mass)
    out = (vals[1:] - vals[:-1]) * n
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.12f N=%d ties=%d" % (bestR, N, _tie_count(best)))

    alt_best = None
    altR = -1.0

    # ---- CVaR smoothing phase ----
    cvar_best = best.copy()
    cvarR = bestR
    for alpha in (0.02, 0.05, 0.1):
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 2.0, time.process_time() + 3.0)
        cand = _lbfgs_block(cvar_best, np.arange(N), 200, tlim,
                            lambda h: _fun_grad_cvar(h, alpha))
        r = R_of(cand)
        if r > cvarR + 1e-15:
            cvar_best, cvarR = cand.copy(), r
    print("cvar phase R=%.12f" % cvarR)
    if cvarR > bestR + 1e-15:
        best, bestR = cvar_best.copy(), cvarR
    if cvarR > altR and cvarR < bestR - 1e-15:
        altR, alt_best = cvarR, cvar_best.copy()

    # ---- KEY NEW IDEA: refine resolution (upsample) and re-optimize ----
    # The scored objective is invariant to N, but finer N can capture sharper peaks.
    # We upsample the best shape and run full-array L-BFGS on the finer grid.
    cur_best = best.copy()
    curR = bestR
    if N < 400000:
        for fac in (2, 2):
            if time.process_time() >= deadline - 8.0:
                break
            n_new = min(400000, cur_best.size * fac)
            if n_new <= cur_best.size:
                break
            up = _resample(cur_best, n_new)
            up = _rescale(up)
            upR = R_of(up)
            print("upsample to %d: R=%.12f (was %.12f)" % (n_new, upR, curR))
            if upR >= curR - 1e-6:
                # re-optimize at higher resolution
                tlim = min(deadline - 6.0, time.process_time() + 6.0)
                cand = _lbfgs_block(up, np.arange(n_new), 300, tlim, _fun_grad_tie)
                r = R_of(cand)
                if r > curR + 1e-15:
                    cur_best, curR = cand.copy(), r
                elif upR > curR + 1e-15:
                    cur_best, curR = up, upR
            if curR > bestR + 1e-15:
                best, bestR = cur_best.copy(), curR
        N = best.size

    # ---- full-array tie polish ----
    for _ in range(3):
        if time.process_time() >= deadline - 1.5:
            break
        tlim = min(deadline - 1.5, time.process_time() + 4.0)
        cand = _lbfgs_block(best, np.arange(N), 300, tlim, _fun_grad_tie)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
        else:
            break
    print("full tie R=%.12f ties=%d" % (bestR, _tie_count(best)))

    # ---- window descent over whole array ----
    W = max(64, N // 64)
    if N <= W:
        win_starts = [0]
        W = N
    else:
        win_starts = list(range(0, N - W + 1, max(1, W // 2)))
        if win_starts and win_starts[-1] + W < N:
            win_starts.append(N - W)

    rng = np.random.RandomState(999)
    accepted = 0
    outer = 0
    while time.process_time() < deadline - 2.0:
        outer += 1
        order = rng.permutation(len(win_starts))
        any_accept = False
        for oi in order:
            if time.process_time() >= deadline - 2.0:
                break
            w0 = win_starts[oi]
            free = np.arange(w0, min(N, w0 + W))
            tlim = min(deadline - 2.0, time.process_time() + 0.4)
            cand = _lbfgs_block(best, free, 40, tlim, _fun_grad_tie)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand, r
                accepted += 1
                any_accept = True
        if not any_accept:
            break
    print("window descent accepted=%d outer=%d R=%.12f" % (accepted, outer, bestR))

    # ---- final peak polish ----
    if time.process_time() < deadline - 0.5:
        Lf = _knots(best)
        pk = int(np.argmax(Lf))
        half = N // 4
        lo = max(0, pk // 2 - half)
        hi = min(N, pk // 2 + half)
        if hi - lo >= 8:
            tlim = min(deadline - 0.3, time.process_time() + 2.5)
            cand = _lbfgs_block(best, np.arange(lo, hi), 200, tlim, _fun_grad_tie)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r
            print("peak polish R=%.12f" % bestR)

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR > startR + 1e-14 and altR < bestR - 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    gLf[idx] += (1.0 / idx.size) / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    w = e / Z
    softmax_val = M + (np.log(Z) + zmax) / beta
    gLf = -dq / num
    gLf += w / softmax_val
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(softmax_val)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, fun_grad, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full(h0, deadline, maxiter=200):
    return _lbfgs_log(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _soft(h0, deadline, beta, maxiter=200):
    return _lbfgs_log(h0, lambda h: _fun_grad_soft(h, beta), deadline, maxiter=maxiter)


def _peak_region(h, tol=0.9995):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    return max(0, idx.min() - 1), min(h.size - 1, idx.max())


def _window_soft(h, deadline, frac, extra, beta, maxiter=200):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    mask = np.zeros(n, dtype=bool)
    mask[lo:hi + 1] = True
    hh = h.copy()
    hh[~mask] = 0.0
    # keep only free indices via zeroing others; we do a masked soft polish
    pos = np.flatnonzero(mask)
    hmax = hh.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(hh[pos], floor, None))

    def f(u):
        hc = hh.copy()
        hc[pos] = np.exp(u)
        val, g = _fun_grad_soft(hc, beta)
        return val, g[pos] * hc[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    out = h.copy()
    out[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(out)


def _refine(h, deadline, factors=(2, 3, 4), per=6.0):
    best = _rescale(h.copy())
    bestR = R_of(best)
    n0 = best.size
    for fac in factors:
        if time.process_time() >= deadline - 0.5:
            break
        n = min(1000000, n0 * fac)
        if n <= best.size:
            continue
        x_old = np.linspace(0.0, 1.0, best.size)
        x_new = np.linspace(0.0, 1.0, n)
        h_up = np.interp(x_new, x_old, best)
        h_up = _rescale(np.clip(h_up, 0, None))
        r_up = R_of(h_up)
        if r_up > bestR:
            best = h_up; bestR = r_up
        tlim = min(deadline - 0.3, time.process_time() + per)
        hc = _full(best, tlim, maxiter=250)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))
    alt, altR = None, 0.0

    def try_cand(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        print("%s R=%.7f (N=%d)" % (tag, r, h.size))
        if r > altR:
            alt, altR = h, r
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("  -> new best %.7f" % bestR)

    # Pass A: soft-max L-BFGS with increasing beta (widens the top plateau).
    betas = [8.0, 32.0, 128.0, 512.0, 2048.0, 8192.0, 32768.0]
    h = best.copy()
    for beta in betas:
        if time.process_time() >= deadline - 20.0:
            break
        h = _soft(h, deadline - 18.0, beta, maxiter=250)
        h = _window_soft(h, deadline - 16.0, 0.4, 64, beta, maxiter=200)
    h = _full(h, deadline - 12.0, maxiter=400)
    if R_of(h) > bestR:
        try_cand(h, "soft-anneal")
    else:
        print("soft-anneal R=%.7f (no gain)" % R_of(h))
        if R_of(h) > altR:
            alt, altR = h, R_of(h)

    # Pass B: resolution refinement (linear upsample + polish).
    if time.process_time() < deadline - 8.0:
        h2, r2 = _refine(best, deadline - 6.0, factors=(2, 3), per=3.0)
        try_cand(h2, "refine")

    # Pass C: perturb with multi-scale noise + soft re-anneal.
    rng = np.random.RandomState(12345)
    for trial in range(3):
        if time.process_time() >= deadline - 4.0:
            break
        n = best.size
        m = max(24, n // 48)
        noise = rng.randn(m)
        p = np.interp(np.linspace(0, 1, n), np.linspace(0, 1, m), noise)
        amp = 0.02 + 0.015 * trial
        hp = _rescale(np.clip(best * np.exp(amp * p), 0, None))
        for beta in [64.0, 512.0, 4096.0]:
            if time.process_time() >= deadline - 3.0:
                break
            hp = _soft(hp, deadline - 2.5, beta, maxiter=180)
        hp = _full(hp, deadline - 1.5, maxiter=300)
        try_cand(hp, "perturb%d" % trial)

    # Final polish: alternate soft/hard on current best until time is up.
    while time.process_time() < deadline - 1.0:
        prev = bestR
        h = _full(best, deadline, maxiter=400)
        if R_of(h) > bestR:
            best, bestR = h, R_of(h)
        if time.process_time() >= deadline - 1.5:
            break
        h = _soft(best, deadline, 16384.0, maxiter=250)
        if R_of(h) > bestR:
            best, bestR = h, R_of(h)
        if bestR <= prev + 1e-12:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and bestR <= startR + 1e-15:
        return {"best": best, "alternative": alt}
    return best

